            CREATE TABLE `FinPR_books` (
                `id` INT AUTO_INCREMENT PRIMARY KEY,
                `name` VARCHAR(255)
            );
            

            CREATE TABLE `FinPR_verses` (
                `id` INT AUTO_INCREMENT PRIMARY KEY,
