INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Alussa loi Jumala taivaan ja maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Ja maa oli autio ja tyhjä, ja pimeys oli syvyyden päällä, ja Jumalan Henki liikkui vetten päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Ja Jumala sanoi: \"Tulkoon valkeus\". Ja valkeus tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Ja Jumala näki, että valkeus oli hyvä; ja Jumala erotti valkeuden pimeydestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Ja Jumala kutsui valkeuden päiväksi, ja pimeyden hän kutsui yöksi. Ja tuli ehtoo, ja tuli aamu, ensimmäinen päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Ja Jumala sanoi: \"Tulkoon taivaanvahvuus vetten välille erottamaan vedet vesistä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Ja Jumala teki taivaanvahvuuden ja erotti vedet, jotka olivat taivaanvahvuuden alla, vesistä, jotka olivat taivaanvahvuuden päällä; ja tapahtui niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Ja Jumala kutsui vahvuuden taivaaksi. Ja tuli ehtoo, ja tuli aamu, toinen päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Ja Jumala sanoi: \"Kokoontukoot vedet, jotka ovat taivaan alla, yhteen paikkaan, niin että kuiva tulee näkyviin\". Ja tapahtui niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Ja Jumala kutsui kuivan maaksi, ja paikan, mihin vedet olivat kokoontuneet, hän kutsui mereksi. Ja Jumala näki, että se oli hyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Ja Jumala sanoi: \"Kasvakoon maa vihantaa, ruohoja, jotka tekevät siementä, ja hedelmäpuita, jotka lajiensa mukaan kantavat maan päällä hedelmää, jossa niiden siemen on\". Ja tapahtui niin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'maa tuotti vihantaa, ruohoja, jotka tekivät siementä lajiensa mukaan, ja puita, jotka lajiensa mukaan kantoivat hedelmää, jossa niiden siemen oli. Ja Jumala näki, että se oli hyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Ja tuli ehtoo, ja tuli aamu, kolmas päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Ja Jumala sanoi: \"Tulkoot valot taivaanvahvuuteen erottamaan päivää yöstä, ja olkoot ne merkkeinä osoittamassa aikoja, päiviä ja vuosia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'ja olkoot valoina taivaanvahvuudella paistamassa maan päälle\". Ja tapahtui niin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Jumala teki kaksi suurta valoa, suuremman valon hallitsemaan päivää ja pienemmän valon hallitsemaan yötä, sekä tähdet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Ja Jumala pani ne taivaanvahvuuteen, paistamaan maan päälle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'ja hallitsemaan päivää ja yötä ja erottamaan valon pimeästä. Ja Jumala näki, että se oli hyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Ja tuli ehtoo, ja tuli aamu, neljäs päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Ja Jumala sanoi: \"Viliskööt vedet eläviä olentoja, ja lentäkööt linnut maan päällä, taivaanvahvuuden alla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Ja Jumala loi suuret merieläimet ja kaikkinaiset liikkuvat, vesissä vilisevät elävät olennot, kunkin lajinsa mukaan, ja kaikkinaiset siivekkäät linnut, kunkin lajinsa mukaan. Ja Jumala näki, että se oli hyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Ja Jumala siunasi ne sanoen: \"Olkaa hedelmälliset ja lisääntykää ja täyttäkää meren vedet, ja linnut lisääntykööt maan päällä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Ja tuli ehtoo, ja tuli aamu, viides päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Ja Jumala sanoi: \"Tuottakoon maa elävät olennot, kunkin lajinsa mukaan, karjaeläimet ja matelijat ja metsäeläimet, kunkin lajinsa mukaan\". Ja tapahtui niin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Jumala teki metsäeläimet, kunkin lajinsa mukaan, ja karjaeläimet, kunkin lajinsa mukaan, ja kaikki maan matelijat, kunkin lajinsa mukaan. Ja Jumala näki, että se oli hyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Ja Jumala sanoi: \"Tehkäämme ihminen kuvaksemme, kaltaiseksemme; ja vallitkoot he meren kalat ja taivaan linnut ja karjaeläimet ja koko maan ja kaikki matelijat, jotka maassa matelevat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Ja Jumala loi ihmisen omaksi kuvaksensa, Jumalan kuvaksi hän hänet loi; mieheksi ja naiseksi hän loi heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Ja Jumala siunasi heidät, ja Jumala sanoi heille: \"Olkaa hedelmälliset ja lisääntykää ja täyttäkää maa ja tehkää se itsellenne alamaiseksi; ja vallitkaa meren kalat ja taivaan linnut ja kaikki maan päällä liikkuvat eläimet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Ja Jumala sanoi: \"Katso, minä annan teille kaikkinaiset siementä tekevät ruohot, joita kasvaa kaikkialla maan päällä, ja kaikki puut, joissa on siementä tekevä hedelmä; olkoot ne teille ravinnoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Ja kaikille metsäeläimille ja kaikille taivaan linnuille ja kaikille, jotka maassa matelevat ja joissa on elävä henki, minä annan kaikkinaiset viheriät ruohot ravinnoksi\". Ja tapahtui niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Ja Jumala katsoi kaikkea, mitä hän tehnyt oli, ja katso, se oli sangen hyvää. Ja tuli ehtoo, ja tuli aamu, kuudes päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Niin tulivat valmiiksi taivas ja maa kaikkine joukkoinensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Ja Jumala päätti seitsemäntenä päivänä työnsä, jonka hän oli tehnyt, ja lepäsi seitsemäntenä päivänä kaikesta työstänsä, jonka hän oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Ja Jumala siunasi seitsemännen päivän ja pyhitti sen, koska hän sinä päivänä lepäsi kaikesta luomistyöstänsä, jonka hän oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Tämä on kertomus taivaan ja maan synnystä, kun ne luotiin. Siihen aikaan kun Herra Jumala teki maan ja taivaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'ei ollut vielä yhtään kedon pensasta maan päällä, eikä vielä kasvanut mitään ruohoa kedolla, koska Herra Jumala ei vielä ollut antanut sataa maan päälle eikä ollut ihmistä maata viljelemässä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'vaan sumu nousi maasta ja kasteli koko maan pinnan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Silloin Herra Jumala teki maan tomusta ihmisen ja puhalsi hänen sieramiinsa elämän hengen, ja niin ihmisestä tuli elävä sielu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Ja Herra Jumala istutti paratiisin Eedeniin, itään, ja asetti sinne ihmisen, jonka hän oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Ja Herra Jumala kasvatti maasta kaikkinaisia puita, ihania nähdä ja hyviä syödä, ja elämän puun keskelle paratiisia, niin myös hyvän-ja pahantiedon puun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Ja Eedenistä lähti joki, joka kasteli paratiisia, ja se jakaantui sieltä neljään haaraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Ensimmäisen nimi on Piison; se kiertää koko Havilan maan, jossa on kultaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'ja sen maan kulta on hyvää. Siellä on myös bedellion-pihkaa ja onyks-kiveä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Toisen virran nimi on Giihon; se kiertää koko Kuusin maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Kolmannen virran nimi on Hiddekel; se juoksee Assurin editse. Ja neljäs virta on Eufrat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Ja Herra Jumala otti ihmisen ja pani hänet Eedenin paratiisiin viljelemään ja varjelemaan sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Ja Herra Jumala käski ihmistä sanoen: \"Syö vapaasti kaikista muista paratiisin puista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'mutta hyvän-ja pahantiedon puusta älä syö, sillä sinä päivänä, jona sinä siitä syöt, pitää sinun kuolemalla kuoleman\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Ja Herra Jumala sanoi: \"Ei ole ihmisen hyvä olla yksinänsä, minä teen hänelle avun, joka on hänelle sopiva\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Ja Herra Jumala teki maasta kaikki metsän eläimet ja kaikki taivaan linnut ja toi ne ihmisen eteen nähdäkseen, kuinka hän ne nimittäisi; ja niinkuin ihminen nimitti kunkin elävän olennon, niin oli sen nimi oleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Ja ihminen antoi nimet kaikille karjaeläimille ja taivaan linnuille ja kaikille metsän eläimille. Mutta Aadamille ei löytynyt apua, joka olisi hänelle sopinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Niin Herra Jumala vaivutti ihmisen raskaaseen uneen, ja kun hän nukkui, otti hän yhden hänen kylkiluistaan ja täytti sen paikan lihalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Ja Herra Jumala rakensi vaimon siitä kylkiluusta, jonka hän oli ottanut miehestä, ja toi hänet miehen luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Ja mies sanoi: \"Tämä on nyt luu minun luistani ja liha minun lihastani; hän kutsuttakoon miehettäreksi, sillä hän on miehestä otettu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Sentähden mies luopukoon isästänsä ja äidistänsä ja liittyköön vaimoonsa, ja he tulevat yhdeksi lihaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Ja he olivat molemmat, mies ja hänen vaimonsa, alasti eivätkä hävenneet toisiansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Mutta käärme oli kavalin kaikista kedon eläimistä, jotka Herra Jumala oli tehnyt; ja se sanoi vaimolle: \"Onko Jumala todellakin sanonut: \'Älkää syökö kaikista paratiisin puista\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Niin vaimo vastasi käärmeelle: \"Me saamme syödä muiden puiden hedelmiä paratiisissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'mutta sen puun hedelmästä, joka on keskellä paratiisia, on Jumala sanonut: \'Älkää syökö siitä älkääkä koskeko siihen, ettette kuolisi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Niin käärme sanoi vaimolle: \"Ette suinkaan kuole;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'vaan Jumala tietää, että sinä päivänä, jona te siitä syötte, aukenevat teidän silmänne, ja te tulette niinkuin Jumala tietämään hyvän ja pahan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Ja vaimo näki, että siitä puusta oli hyvä syödä ja että se oli ihana katsella ja suloinen puu antamaan ymmärrystä; ja hän otti sen hedelmästä ja söi ja antoi myös miehellensä, joka oli hänen kanssansa, ja hänkin söi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Silloin aukenivat heidän molempain silmät, ja he huomasivat olevansa alasti; ja he sitoivat yhteen viikunapuun lehtiä ja tekivät itselleen vyöverhot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Ja he kuulivat, kuinka Herra Jumala käyskenteli paratiisissa illan viileydessä. Ja mies vaimoineen lymysi Herran Jumalan kasvojen edestä paratiisin puiden sekaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Mutta Herra Jumala huusi miestä ja sanoi hänelle: \"Missä olet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Hän vastasi: \"Minä kuulin sinun askeleesi paratiisissa ja pelkäsin, sillä minä olen alasti, ja sentähden minä lymysin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Ja hän sanoi: \"Kuka sinulle ilmoitti, että olet alasti? Etkö syönyt siitä puusta, josta minä kielsin sinua syömästä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Mies vastasi: \"Vaimo, jonka annoit olemaan minun kanssani, antoi minulle siitä puusta, ja minä söin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Niin Herra Jumala sanoi vaimolle: \"Mitäs olet tehnyt?\" Vaimo vastasi: \"Käärme petti minut, ja minä söin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Ja Herra Jumala sanoi käärmeelle: \"Koska tämän teit, kirottu ole sinä kaikkien karjaeläinten ja kaikkien metsän eläinten joukossa. Vatsallasi sinun pitää käymän ja tomua syömän koko elinaikasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Ja minä panen vainon sinun ja vaimon välille ja sinun siemenesi ja hänen siemenensä välille; se on polkeva rikki sinun pääsi, ja sinä olet pistävä sitä kantapäähän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Ja vaimolle hän sanoi: \"Minä teen suuriksi sinun raskautesi vaivat, kivulla sinun pitää synnyttämän lapsia; mutta mieheesi on sinun halusi oleva, ja hän on sinua vallitseva\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Ja Aadamille hän sanoi: \"Koska kuulit vaimoasi ja söit puusta, josta minä kielsin sinua sanoen: \'Älä syö siitä\', niin kirottu olkoon maa sinun tähtesi. Vaivaa nähden sinun pitää elättämän itseäsi siitä koko elinaikasi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'orjantappuroita ja ohdakkeita se on kasvava sinulle, ja kedon ruohoja sinun on syötävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Otsasi hiessä sinun pitää syömän leipäsi, kunnes tulet maaksi jälleen, sillä siitä sinä olet otettu. Sillä maasta sinä olet, ja maaksi pitää sinun jälleen tuleman.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Ja mies antoi vaimolleen nimen Eeva, sillä hänestä tuli kaiken elävän äiti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Ja Herra Jumala teki Aadamille ja hänen vaimollensa puvut nahasta ja puki ne heidän yllensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Ja Herra Jumala sanoi: \"Katso, ihminen on tullut sellaiseksi kuin joku meistä, niin että hän tietää hyvän ja pahan. Kun ei hän nyt vain ojentaisi kättänsä ja ottaisi myös elämän puusta ja söisi ja eläisi iankaikkisesti!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Niin Herra Jumala ajoi hänet pois Eedenin paratiisista viljelemään maata, josta hän oli otettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Ja hän karkoitti ihmisen ja asetti Eedenin paratiisin itäpuolelle kerubit ynnä välkkyvän, leimuavan miekan vartioitsemaan elämän puun tietä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Ja mies yhtyi vaimoonsa Eevaan; ja tämä tuli raskaaksi ja synnytti Kainin ja sanoi: \"Minä olen saanut pojan Herran avulla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Ja taas hän synnytti pojan, veljen Kainille, Aabelin. Ja Aabelista tuli lampuri, mutta Kainista peltomies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Ja jonkun ajan kuluttua tapahtui, että Kain toi maan hedelmistä uhrilahjan Herralle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'ja myöskin Aabel toi uhrilahjan laumansa esikoisista, niiden rasvoista. Ja Herra katsoi Aabelin ja hänen uhrilahjansa puoleen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'mutta Kainin ja hänen uhrilahjansa puoleen hän ei katsonut. Silloin Kain vihastui kovin, ja hänen hahmonsa synkistyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Ja Herra sanoi Kainille: \"Miksi olet vihastunut, ja miksi hahmosi synkistyy?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Eikö niin: jos teet hyvin, voit kohottaa katseesi; mutta jos et hyvin tee, niin väijyy synti ovella, ja sen halu on sinuun, mutta hallitse sinä sitä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Ja Kain sanoi veljellensä Aabelille: \"Menkäämme kedolle\". Ja heidän kedolla ollessansa Kain karkasi veljensä Aabelin kimppuun ja tappoi hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Niin Herra sanoi Kainille: \"Missä on veljesi Aabel?\" Hän vastasi: \"En tiedä; olenko minä veljeni vartija?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Ja hän sanoi: \"Mitä olet tehnyt? Kuule, veljesi veri huutaa minulle maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Ja nyt ole kirottu ja karkoitettu pois tältä vainiolta, joka avasi suunsa ottamaan veljesi veren sinun kädestäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Kun maata viljelet, ei se ole enää sinulle satoansa antava; kulkija ja pakolainen pitää sinun oleman maan päällä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Ja Kain sanoi Herralle: \"Syyllisyyteni on suurempi, kuin että sen kantaa voisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Katso, sinä karkoitat minut nyt pois vainiolta, ja minun täytyy lymytä sinun kasvojesi edestä ja olla kulkija ja pakolainen maan päällä; ja kuka ikinä minut kohtaa, se tappaa minut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Mutta Herra sanoi hänelle: \"Sentähden, kuka ikinä tappaa Kainin, hänelle se pitää seitsenkertaisesti kostettaman\". Ja Herra pani Kainiin merkin, ettei kukaan, joka hänet kohtaisi, tappaisi häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Niin Kain poistui Herran kasvojen edestä ja asettui asumaan Noodin maahan, itään päin Eedenistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Ja Kain yhtyi vaimoonsa, ja tämä tuli raskaaksi ja synnytti Hanokin. Ja hän rakensi kaupungin ja antoi sille kaupungille poikansa nimen Hanok.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Ja Hanokille syntyi Iirad, Iiradille syntyi Mehujael, Mehujaelille syntyi Metusael, Metusaelille syntyi Lemek.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lemek otti itselleen kaksi vaimoa, toisen nimi oli Aada ja toisen nimi Silla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Ja Aada synnytti Jaabalin; hänestä tuli niiden kantaisä, jotka teltoissa asuvat ja karjanhoitoa harjoittavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Ja hänen veljensä nimi oli Juubal; hänestä tuli kaikkien niiden kantaisä, jotka kannelta ja huilua soittavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Myöskin Silla synnytti pojan, Tuubal-Kainin; hänestä tuli kaikkinaisten vaski-ja rauta-aseiden takoja. Ja Tuubal-Kainin sisar oli Naema.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Ja Lemek lausui vaimoillensa: \"Aada ja Silla, kuulkaa puhettani, te Lemekin emännät, ottakaa sanani korviinne: minä surmaan miehen haavastani ja nuorukaisen mustelmastani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Niin, Kain kostetaan seitsenkertaisesti, mutta Lemek seitsemänkymmentä seitsemän kertaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Ja Aadam yhtyi taas vaimoonsa, ja tämä synnytti pojan ja antoi hänelle nimen Seet, sanoen: \"Jumala on suonut minulle toisen pojan Aabelin sijaan, koska Kain hänet surmasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Ja myöskin Seetille syntyi poika, ja hän antoi hänelle nimen Enos. Siihen aikaan ruvettiin avuksi huutamaan Herran nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Tämä on Aadamin sukuluettelo. Kun Jumala loi ihmisen, teki hän hänet Jumalan kaltaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Mieheksi ja naiseksi hän heidät loi ja siunasi heidät ja antoi heille nimen ihminen, silloin kun heidät luotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Kun Aadam oli sadan kolmenkymmenen vuoden vanha, syntyi hänelle poika, joka oli hänen kaltaisensa, hänen kuvansa, ja hän antoi hänelle nimen Seet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Ja Aadam eli Seetin syntymän jälkeen kahdeksansataa vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Niin oli Aadamin koko elinaika yhdeksänsataa kolmekymmentä vuotta; sitten hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Kun Seet oli sadan viiden vuoden vanha, syntyi hänelle Enos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Ja Seet eli Enoksen syntymän jälkeen kahdeksansataa seitsemän vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Niin oli Seetin koko elinaika yhdeksänsataa kaksitoista vuotta; sitten hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Kun Enos oli yhdeksänkymmenen vuoden vanha, syntyi hänelle Keenan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Ja Enos eli Keenanin syntymän jälkeen kahdeksansataa viisitoista vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Niin oli Enoksen koko elinaika yhdeksänsataa viisi vuotta; sitten hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kun Keenan oli seitsemänkymmenen vuoden vanha, syntyi hänelle Mahalalel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Ja Keenan eli Mahalalelin syntymän jälkeen kahdeksansataa neljäkymmentä vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Niin oli Keenanin koko elinaika yhdeksänsataa kymmenen vuotta; sitten hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Kun Mahalalel oli kuudenkymmenen viiden vuoden vanha, syntyi hänelle Jered.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Ja Mahalalel eli Jeredin syntymän jälkeen kahdeksansataa kolmekymmentä vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Niin oli Mahalalelin koko elinaika kahdeksansataa yhdeksänkymmentä viisi vuotta; sitten hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Kun Jered oli sadan kuudenkymmenen kahden vuoden vanha, syntyi hänelle Hanok.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Ja Jered eli Hanokin syntymän jälkeen kahdeksansataa vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Niin oli Jeredin koko elinaika yhdeksänsataa kuusikymmentä kaksi vuotta; sitten hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Kun Hanok oli kuudenkymmenen viiden vuoden vanha, syntyi hänelle Metusalah.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Ja Hanok vaelsi Metusalahin syntymän jälkeen Jumalan yhteydessä kolmesataa vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Niin oli Hanokin koko elinaika kolmesataa kuusikymmentä viisi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Ja kun Hanok oli vaeltanut Jumalan yhteydessä, ei häntä enää ollut, sillä Jumala oli ottanut hänet pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Kun Metusalah oli sadan kahdeksankymmenen seitsemän vuoden vanha, syntyi hänelle Lemek.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Ja Metusalah eli Lemekin syntymän jälkeen seitsemänsataa kahdeksankymmentä kaksi vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Niin oli Metusalahin koko elinaika yhdeksänsataa kuusikymmentä yhdeksän vuotta; sitten hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Kun Lemek oli sadan kahdeksankymmenen kahden vuoden vanha, syntyi hänelle poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Ja hän antoi hänelle nimen Nooa, sanoen: \"Tämä lohduttaa meitä työssämme ja kättemme vaivoissa viljellessämme maata, jonka Herra on kironnut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Ja Lemek eli Nooan syntymän jälkeen viisisataa yhdeksänkymmentä viisi vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Niin oli Lemekin koko elinaika seitsemänsataa seitsemänkymmentä seitsemän vuotta; sitten hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Kun Nooa oli viidensadan vuoden vanha, syntyivät hänelle Seem, Haam ja Jaafet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Kun ihmiset alkoivat lisääntyä maan päällä ja heille syntyi tyttäriä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'huomasivat Jumalan pojat ihmisten tyttäret ihaniksi ja ottivat vaimoikseen kaikki, jotka he parhaiksi katsoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Silloin Herra sanoi: \"Minun Henkeni ei ole vallitseva ihmisessä iankaikkisesti, koska hän on liha. Niin olkoon hänen aikansa sata kaksikymmentä vuotta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Siihen aikaan eli maan päällä jättiläisiä, ja myöhemminkin, kun Jumalan pojat yhtyivät ihmisten tyttäriin ja nämä synnyttivät heille lapsia; nämä olivat noita muinaisajan kuuluisia sankareita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Mutta kun Herra näki, että ihmisten pahuus oli suuri maan päällä ja että kaikki heidän sydämensä aivoitukset ja ajatukset olivat kaiken aikaa ainoastaan pahat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'niin Herra katui tehneensä ihmiset maan päälle, ja hän tuli murheelliseksi sydämessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Ja Herra sanoi: \"Minä hävitän maan päältä ihmiset, jotka minä loin, sekä ihmiset että karjan, matelijat ja taivaan linnut; sillä minä kadun ne tehneeni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Mutta Nooa sai armon Herran silmien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Tämä on kertomus Nooan suvusta. Nooa oli aikalaistensa keskuudessa hurskas ja nuhteeton mies ja vaelsi Jumalan yhteydessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Ja Nooalle syntyi kolme poikaa, Seem, Haam ja Jaafet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Mutta maa turmeltui Jumalan edessä, ja maa tuli täyteen väkivaltaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Niin Jumala näki, että maa oli turmeltunut; sillä kaikki liha oli turmellut vaelluksensa maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Silloin Jumala sanoi Nooalle: \"Minä olen päättänyt tehdä lopun kaikesta lihasta, sillä maa on heidän tähtensä täynnä väkivaltaa; katso, minä hävitän heidät ynnä maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Tee itsellesi arkki honkapuista, rakenna arkki täyteen kammioita, ja tervaa se sisältä ja ulkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Ja näin on sinun se rakennettava: kolmesataa kyynärää olkoon arkin pituus, viisikymmentä kyynärää sen leveys ja kolmekymmentä kyynärää sen korkeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Tee arkkiin valoaukko, ja tee se kyynärän korkuiseksi, ja sijoita arkin ovi sen kylkeen; rakenna siihen kolme kerrosta, alimmainen, keskimmäinen ja ylimmäinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Sillä katso, minä annan vedenpaisumuksen tulla yli maan hävittämään taivaan alta kaiken lihan, kaiken, jossa on elämän henki; kaikki, mikä on maan päällä, on hukkuva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Mutta sinun kanssasi minä teen liiton, ja sinun on mentävä arkkiin, sinun ja sinun poikiesi, vaimosi ja miniäisi sinun kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Ja kaikista eläimistä, kaikesta lihasta, sinun on vietävä arkkiin kaksi kutakin lajia säilyttääksesi ne hengissä kanssasi; niitä olkoon koiras ja naaras.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Lintuja lajiensa mukaan, karjaeläimiä lajiensa mukaan ja kaikkia maan matelijoita lajiensa mukaan tulkoon kaksi kutakin lajia sinun luoksesi, säilyttääksesi ne hengissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Ja hanki itsellesi kaikkinaista ravintoa, syötäväksi kelpaavaa, ja kokoa sitä talteesi, että se olisi ruuaksi sinulle ja heille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Ja Nooa teki näin; aivan niin kuin Jumala hänen käski tehdä, niin hän teki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Ja Herra sanoi Nooalle: \"Mene sinä ja koko perheesi arkkiin, sillä sinut minä olen tässä sukukunnassa havainnut hurskaaksi edessäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Kaikkia puhtaita eläimiä ota luoksesi seitsemän paria, koiraita ja naaraita, mutta epäpuhtaita eläimiä kutakin yksi pari, koiras ja naaras.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Niin myös taivaan lintuja seitsemän paria, koiraita ja naaraita, että siemen säilyisi elossa koko maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Sillä seitsemän päivän kuluttua minä annan sataa maan päälle neljäkymmentä päivää ja neljäkymmentä yötä ja hävitän maan päältä kaikki olennot, jotka olen tehnyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Ja Nooa teki näin, aivan niin kuin Herra oli hänen käskenyt tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Nooa oli kuudensadan vuoden vanha, kun vedenpaisumus tuli maan päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Ja Nooa ja hänen poikansa, vaimonsa ja miniänsä hänen kanssaan menivät arkkiin vedenpaisumusta pakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Puhtaita eläimiä ja epäpuhtaita eläimiä, lintuja ja kaikkia, joita maassa matelee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'meni Nooan luo arkkiin kaksittain, koiras ja naaras, niinkuin Jumala oli Nooalle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Ja niiden seitsemän päivän kuluttua tuli vedenpaisumus maan päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Ja sinä vuonna, jona Nooa oli kuudensadan vuoden vanha, sen toisena kuukautena, kuukauden seitsemäntenätoista päivänä, sinä päivänä puhkesivat kaikki suuren syvyyden lähteet, ja taivaan akkunat aukenivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Ja satoi rankasti maan päälle neljäkymmentä päivää ja neljäkymmentä yötä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Juuri sinä päivänä menivät Nooa sekä Seem, Haam ja Jaafet, Nooan pojat, ja Nooan vaimo ja hänen kolme miniäänsä heidän kanssaan arkkiin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'he ja kaikki metsäeläimet lajiensa mukaan ja kaikki karjaeläimet lajiensa mukaan ja kaikki matelijat, jotka maan päällä matelevat, lajiensa mukaan ja kaikki linnut lajiensa mukaan, kaikki lintuset, kaikki, mikä siivekästä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Ja ne menivät Nooan luo arkkiin kaksittain, kaikki liha, kaikki, jossa oli elämän henki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Ja ne, jotka menivät sisälle, olivat koiras ja naaras kaikesta lihasta, niinkuin Jumala oli hänelle käskyn antanut. Ja Herra sulki oven hänen jälkeensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Silloin tuli vedenpaisumus maan päälle, tuli neljänäkymmenenä päivänä; ja vedet paisuivat ja nostivat arkin, niin että se kohosi korkealle maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Ja vedet saivat vallan ja paisuivat suuresti maan päällä, ja arkki ajelehti veden pinnalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Ja vedet nousivat nousemistaan maan päällä, niin että kaikki korkeat vuoret kaiken taivaan alla peittyivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Viisitoista kyynärää vesi nousi vuorten yli, niin että ne peittyivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Silloin hukkui kaikki liha, joka maan päällä liikkui: linnut, karjaeläimet, metsäeläimet ja kaikki pikkueläimet, joita maassa vilisi, sekä kaikki ihmiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Kaikki, joiden sieramissa oli elämän hengen henkäys, kaikki, jotka elivät kuivalla maalla, kuolivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Niin Herra hävitti kaikki olennot, jotka maan päällä olivat, niin hyvin ihmiset kuin myös karjaeläimet, matelijat ja taivaan linnut; ne hävisivät maan päältä. Ainoastaan Nooa sekä ne, jotka olivat hänen kanssansa arkissa, jäivät henkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Ja vedet vallitsivat maan päällä sata viisikymmentä päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Silloin Jumala muisti Nooaa ja kaikkia metsäeläimiä ja kaikkia karjaeläimiä, jotka olivat hänen kanssansa arkissa. Ja Jumala nosti tuulen puhaltamaan yli maan, niin että vesi laskeutui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Ja syvyyden lähteet ja taivaan akkunat sulkeutuivat, ja sade taivaasta taukosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Ja vesi väistyi väistymistään maan päältä; sadan viidenkymmenen päivän kuluttua alkoi vesi vähentyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Niin arkki pysähtyi seitsemäntenä kuukautena, kuukauden seitsemäntenätoista päivänä, Araratin vuorille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Ja vesi väheni vähenemistään aina kymmenenteen kuukauteen asti. Kymmenentenä kuukautena, kuukauden ensimmäisenä päivänä, tulivat vuorten huiput näkyviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Neljänkymmenen päivän kuluttua Nooa avasi arkin ikkunan, jonka hän oli tehnyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'ja laski kaarneen lentoon, ja se lenteli edestakaisin, kunnes vesi maan päältä kuivui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Sitten hän laski luotansa kyyhkysen nähdäksensä, oliko vesi vähentynyt maan pinnalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Mutta kyyhkynen ei löytänyt paikkaa, missä lepuuttaa jalkaansa, vaan palasi hänen luoksensa arkkiin, sillä koko maa oli vielä veden peitossa; niin hän ojensi kätensä ja otti sen luoksensa arkkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Ja hän odotti vielä toiset seitsemän päivää ja laski taas kyyhkysen arkista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Ja kyyhkynen tuli hänen luoksensa ehtoopuolella, ja katso, sen suussa oli tuore öljypuun lehti. Niin Nooa ymmärsi, että vesi oli vähentynyt maan päältä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Mutta hän odotti vielä toiset seitsemän päivää ja laski kyyhkysen lentoon, eikä se enää palannut hänen luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Ja Nooan kuudentenasadantena yhdentenä ikävuotena, vuoden ensimmäisenä kuukautena, kuukauden ensimmäisenä päivänä, oli vesi kuivunut maan päältä. Niin Nooa poisti katon arkista ja katseli; ja katso, maan pinta oli kuivunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Ja toisena kuukautena, kuukauden kahdentenakymmenentenä seitsemäntenä päivänä, oli maa aivan kuiva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Ja Jumala puhui Nooalle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '\"Lähde arkista, sinä ja vaimosi, poikasi ja miniäsi sinun kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Ja kaikki eläimet, jotka ovat luonasi, kaikki liha, linnut ja karjaeläimet ja kaikki matelijat, jotka maan päällä matelevat, vie ne ulos kanssasi. Niitä vilisköön maassa, ja ne olkoot hedelmälliset ja lisääntykööt maan päällä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Ja Nooa ja hänen poikansa, vaimonsa ja miniänsä hänen kanssaan lähtivät ulos,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'niin myös kaikki metsäeläimet, kaikki matelijat ja kaikki linnut, kaikki, mikä liikkuu maan päällä, lähtivät arkista suvuittain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Ja Nooa rakensi alttarin Herralle ja otti kaikkia puhtaita karjaeläimiä ja kaikkia puhtaita lintuja ja uhrasi polttouhreja alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Ja Herra tunsi suloisen tuoksun ja sanoi sydämessänsä: \"En minä koskaan enää kiroa maata ihmisen tähden; sillä ihmisen sydämen aivoitukset ovat pahat nuoruudesta saakka. Enkä minä koskaan enää tuhoa kaikkea, mikä elää, niinkuin nyt olen tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Niin kauan kuin maa pysyy, ei lakkaa kylväminen eikä leikkaaminen, ei vilu eikä helle, ei kesä eikä talvi, ei päivä eikä yö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Ja Jumala siunasi Nooan ja hänen poikansa ja sanoi heille: \"Olkaa hedelmälliset ja lisääntykää ja täyttäkää maa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Ja peljätkööt ja vaviskoot teitä kaikki eläimet maan päällä ja kaikki taivaan linnut ja kaikki, jotka maassa matelevat, ja kaikki meren kalat; ne olkoot teidän valtaanne annetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Kaikki, mikä liikkuu ja elää, olkoon teille ravinnoksi; niinkuin minä olen antanut teille viheriäiset kasvit, niin minä annan teille myös tämän kaiken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Älkää vain syökö lihaa, jossa sen sielu, sen veri, vielä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Mutta teidän oman verenne minä kostan; jokaiselle eläimelle minä sen kostan, ja myöskin ihmisille minä kostan ihmisen sielun, toiselle toisen sielun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Joka ihmisen veren vuodattaa, hänen verensä on ihminen vuodattava, sillä Jumala on tehnyt ihmisen kuvaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Ja te olkaa hedelmälliset ja lisääntykää, enentykää maassa ja lisääntykää siinä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Ja Jumala puhui Nooalle ja hänen pojillensa, jotka olivat hänen kanssansa, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '\"Katso, minä teen liiton teidän ja teidän jälkeläistenne kanssa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'ja kaikkien elävien olentojen kanssa, jotka luonanne ovat, lintujen, karjaeläinten ja kaikkien metsäeläinten kanssa, jotka luonanne ovat, kaikkien kanssa, jotka arkista lähtivät, kaikkien maan eläinten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Minä teen liiton teidän kanssanne: ei koskaan enää pidä kaikkea lihaa hukutettaman vedenpaisumuksella, eikä vedenpaisumus koskaan enää maata turmele.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Ja Jumala sanoi: \"Tämä on sen liiton merkki, jonka minä ikuisiksi ajoiksi teen itseni ja teidän ja kaikkien elävien olentojen välillä, jotka teidän luonanne ovat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'minä panen kaareni pilviin, ja se on oleva liiton merkkinä minun ja maan välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Ja kun minä kokoan pilviä maan päälle ja kaari näkyy pilvissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'muistan minä liittoni, joka on minun ja teidän ja kaikkien elävien olentojen, kaiken lihan välillä, eikä vesi enää paisu tulvaksi hävittämään kaikkea lihaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Niin kaari on oleva pilvissä, ja minä katselen sitä muistaakseni iankaikkista liittoa Jumalan ja kaikkien elävien olentojen, kaiken lihan välillä, joka maan päällä on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Ja Jumala sanoi Nooalle: \"Tämä on sen liiton merkki, jonka minä olen tehnyt itseni ja kaiken lihan välillä, joka maan päällä on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Ja Nooan pojat, jotka lähtivät arkista, olivat Seem, Haam ja Jaafet. Ja Haam oli Kanaanin isä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Nämä kolme ovat Nooan pojat, ja heistä kaikki maan asukkaat polveutuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Ja Nooa oli peltomies ja ensimmäinen, joka istutti viinitarhan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Mutta kun hän joi viiniä, niin hän juopui ja makasi alasti majassansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Ja Haam, Kanaanin isä, näki isänsä hävyn ja kertoi siitä molemmille veljillensä ulkona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Niin Seem ja Jaafet ottivat vaipan ja panivat molemmat sen hartioilleen ja menivät selin sisään ja peittivät isänsä hävyn; ja heidän kasvonsa olivat käännetyt toisaalle, niin etteivät he nähneet isänsä häpyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Kun Nooa heräsi päihtymyksestänsä ja sai tietää, mitä hänen nuorin poikansa oli hänelle tehnyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'niin hän sanoi: \"Kirottu olkoon Kanaan, olkoon hän veljiensä orjain orja\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Vielä hän sanoi: \"Kiitetty olkoon Herra, Seemin Jumala, ja olkoon Kanaan heidän orjansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Jumala laajentakoon Jaafetin, ja asukoon hän Seemin majoissa, ja Kanaan olkoon heidän orjansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Ja Nooa eli vedenpaisumuksen jälkeen kolmesataa viisikymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Niin Nooan koko ikä oli yhdeksänsataa viisikymmentä vuotta; sitten hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Tämä on kertomus Nooan poikien, Seemin, Haamin ja Jaafetin, suvusta. Heille syntyi poikia vedenpaisumuksen jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Jaafetin pojat olivat Goomer, Maagog, Maadai, Jaavan, Tuubal, Mesek ja Tiiras.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Ja Goomerin pojat olivat Askenas, Riifat ja Toogarma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Ja Jaavanin pojat olivat Elisa, Tarsis, kittiläiset ja doodanilaiset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'heistä haarautuivat pakanoiden saarten asukkaat maittensa, eri kieltensä, heimojensa ja kansakuntiensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Ja Haamin pojat olivat Kuus, Misraim, Puut ja Kanaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Ja Kuusin pojat olivat Seba, Havila, Sabta, Raema ja Sabteka. Ja Raeman pojat olivat Saba ja Dedan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Ja Kuusille syntyi Nimrod. Hän oli ensimmäinen valtias maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Hän oli mahtava metsämies Herran edessä. Siitä on sananparsi: \"Mahtava metsämies Herran edessä niinkuin Nimrod\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Ja hänen valtakuntansa alkuna olivat Baabel, Erek, Akkad ja Kalne Sinearin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Siitä maasta hän lähti Assuriin ja rakensi Niiniven, Rehobot-Iirin ja Kelahin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'sekä Resenin Niiniven ja Kelahin välille; se on tuo suuri kaupunki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Ja Misraimille syntyivät luudilaiset, anamilaiset, lehabilaiset, naftuhilaiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'patrokselaiset, kasluhilaiset, joista filistealaiset ovat lähteneet, sekä kaftorilaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Ja Kanaanille syntyivät Siidon, hänen esikoisensa, ja Heet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'sekä jebusilaiset, amorilaiset, girgasilaiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'hivviläiset, arkilaiset, siiniläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'arvadilaiset, semarilaiset ja hamatilaiset. Sittemmin hajaantuivat kanaanilaisten heimot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Ja kanaanilaisten alue ulottui Siidonista Gerariin päin aina Gassaan asti sekä Sodomaan, Gomorraan, Admaan ja Seboimiin päin aina Lesaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Nämä olivat Haamin pojat heimojensa, kieltensä, maittensa ja kansakuntiensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Myöskin Seemille, Jaafetin vanhimmalle veljelle, josta tuli kaikkien Eeberin poikien kantaisä, syntyi poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Seemin pojat olivat Eelam, Assur, Arpaksad, Luud ja Aram.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Ja Aramin pojat olivat Uus, Huul, Geter ja Mas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arpaksadille syntyi Selah, ja Selahille syntyi Eeber.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Ja Eeberille syntyi kaksi poikaa: toisen nimi oli Peleg, sillä hänen aikanansa jakaantuivat maan asukkaat, ja hänen veljensä nimi oli Joktan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Ja Joktanille syntyi Almodad, Selef, Hasarmavet, Jerah,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadoram, Uusal, Dikla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Oobal, Abimael, Saba,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Oofir, Havila ja Joobab. Kaikki nämä olivat Joktanin poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Ja heidän asumasijansa ulottuivat Meesasta aina Sefariin, Itävuorelle asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Nämä olivat Seemin pojat heimojensa, kieltensä, maittensa ja kansakuntiensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Nämä olivat Nooan poikien heimot sukukuntiensa ja kansakuntiensa mukaan; ja niistä haarautuivat kansat maan päälle vedenpaisumuksen jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Ja kaikessa maassa oli yksi kieli ja yksi puheenparsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Kun he lähtivät liikkeelle itään päin, löysivät he lakeuden Sinearin maassa ja asettuivat sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Ja he sanoivat toisillensa: \"Tulkaa, tehkäämme tiiliä ja polttakaamme ne koviksi\". Ja tiiltä he käyttivät kivenä, ja maapihkaa he käyttivät laastina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Ja he sanoivat: \"Tulkaa, rakentakaamme itsellemme kaupunki ja torni, jonka huippu ulottuu taivaaseen, ja tehkäämme itsellemme nimi, ettemme hajaantuisi yli kaiken maan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Niin Herra astui alas katsomaan kaupunkia ja tornia, jonka ihmislapset olivat rakentaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Ja Herra sanoi: \"Katso, he ovat yksi kansa, ja heillä kaikilla on yksi kieli, ja tämä on heidän ensimmäinen yrityksensä. Ja nyt ei heille ole mahdotonta mikään, mitä aikovatkin tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Tulkaa, astukaamme alas ja sekoittakaamme siellä heidän kielensä, niin ettei toinen ymmärrä toisen kieltä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Ja niin Herra hajotti heidät sieltä yli kaiken maan, niin että he lakkasivat kaupunkia rakentamasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Siitä tuli sen nimeksi Baabel, koska Herra siellä sekoitti kaiken maan kielen; ja sieltä Herra hajotti heidät yli kaiken maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Tämä on kertomus Seemin suvusta. Kun Seem oli sadan vuoden vanha, syntyi hänelle Arpaksad kaksi vuotta vedenpaisumuksen jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Ja Seem eli Arpaksadin syntymän jälkeen viisisataa vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Kun Arpaksad oli kolmenkymmenen viiden vuoden vanha, syntyi hänelle Selah.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Ja Arpaksad eli Selahin syntymän jälkeen neljäsataa kolme vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Kun Selah oli kolmenkymmenen vuoden vanha, syntyi hänelle Eeber.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Ja Selah eli Eeberin syntymän jälkeen neljäsataa kolme vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Kun Eeber oli kolmenkymmenen neljän vuoden vanha, syntyi hänelle Peleg.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Ja Eeber eli Pelegin syntymän jälkeen neljäsataa kolmekymmentä vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Kun Peleg oli kolmenkymmenen vuoden vanha, syntyi hänelle Regu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Ja Peleg eli Regun syntymän jälkeen kaksisataa yhdeksän vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Kun Regu oli kolmenkymmenen kahden vuoden vanha, syntyi hänelle Serug.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Ja Regu eli Serugin syntymän jälkeen kaksisataa seitsemän vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Kun Serug oli kolmenkymmenen vuoden vanha, syntyi hänelle Naahor.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Ja Serug eli Naahorin syntymän jälkeen kaksisataa vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Kun Naahor oli kahdenkymmenen yhdeksän vuoden vanha, syntyi hänelle Terah.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Ja Naahor eli Terahin syntymän jälkeen sata yhdeksäntoista vuotta, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Kun Terah oli seitsemänkymmenen vuoden vanha, syntyivät hänelle Abram, Naahor ja Haaran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Ja tämä on kertomus Terahin suvusta. Terahille syntyivät Abram, Naahor ja Haaran. Ja Haaranille syntyi Loot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Ja Haaran kuoli ennen isäänsä Terahia synnyinmaassansa, Kaldean Uurissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Ja Abram ja Naahor ottivat itsellensä vaimot; Abramin vaimon nimi oli Saarai, ja Naahorin vaimon nimi oli Milka, Haaranin tytär; Haaran oli Milkan ja Jiskan isä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Mutta Saarai oli hedelmätön, hänellä ei ollut lasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Ja Terah otti poikansa Abramin ja poikansa pojan Lootin, Haaranin pojan, ja miniänsä Saarain, poikansa Abramin vaimon, ja he lähtivät heidän kanssaan Kaldean Uurista mennäksensä Kanaanin maahan, ja he saapuivat Harraniin asti ja asuivat siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Ja Terahin ikä oli kaksisataa viisi vuotta; sitten Terah kuoli Harranissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Ja Herra sanoi Abramille: \"Lähde maastasi, suvustasi ja isäsi kodista siihen maahan, jonka minä sinulle osoitan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Niin minä teen sinusta suuren kansan, siunaan sinut ja teen sinun nimesi suureksi, ja sinä olet tuleva siunaukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Ja minä siunaan niitä, jotka sinua siunaavat, ja kiroan ne, jotka sinua kiroavat, ja sinussa tulevat siunatuiksi kaikki sukukunnat maan päällä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Niin Abram lähti, niinkuin Herra oli hänelle puhunut, ja Loot meni hänen kanssansa. Abram oli Harranista lähtiessänsä seitsemänkymmenen viiden vuoden vanha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Ja Abram otti vaimonsa Saarain ja veljensä pojan Lootin sekä kaiken omaisuuden, jonka he olivat koonneet, ja ne palvelijat, jotka he olivat hankkineet Harranissa, ja he lähtivät menemään Kanaanin maahan. Ja he tulivat Kanaanin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Ja Abram kulki maan läpi aina Sikemin paikkakunnalle, Mooren tammelle asti. Ja siihen aikaan kanaanilaiset asuivat siinä maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Silloin Herra ilmestyi Abramille ja sanoi: \"Sinun jälkeläisillesi minä annan tämän maan\". Niin hän rakensi sinne alttarin Herralle, joka oli hänelle ilmestynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Sieltä hän siirtyi edemmäksi vuoristoon, itään päin Beetelistä, ja pystytti telttansa, niin että Beetel oli lännessä ja Ai idässä, ja hän rakensi sinne alttarin Herralle ja huusi avuksi Herran nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Ja sieltä Abram lähti ja vaelsi yhä edemmäksi Etelämaahan päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Niin tuli nälänhätä maahan, ja Abram meni Egyptiin, asuakseen siellä jonkun aikaa, sillä nälänhätä maassa oli kova.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Ja kun hän lähestyi Egyptiä, puhui hän vaimollensa Saaraille: \"Katso, minä tiedän, että sinä olet kaunis nainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Kun egyptiläiset saavat nähdä sinut, niin he sanovat: \'Hän on hänen vaimonsa\', ja tappavat minut, mutta antavat sinun elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Sano siis olevasi minun sisareni, että minun kävisi hyvin sinun tähtesi ja minä sinun takiasi saisin jäädä henkiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Kun Abram tuli Egyptiin, näkivät egyptiläiset, että Saarai oli hyvin kaunis nainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Ja kun faraon ruhtinaat olivat nähneet hänet, ylistelivät he häntä faraolle; ja vaimo vietiin faraon hoviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Ja Abramia hän kohteli hyvin hänen tähtensä. Ja hän sai pikkukarjaa, raavaskarjaa ja aaseja, palvelijoita ja palvelijattaria, aasintammoja ja kameleja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Mutta Herra antoi kovien vitsausten kohdata faraota ja hänen hoviansa Saarain, Abramin vaimon, tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Silloin farao kutsui Abramin luoksensa ja sanoi: \"Mitä olet minulle tehnyt? Miksi et ilmoittanut minulle, että hän on sinun vaimosi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Miksi sanoit: \'Hän on minun sisareni\', niin että minä otin hänet vaimokseni? Katso, tässä on vaimosi, ota hänet ja mene.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Ja farao antoi hänestä käskyn miehillensä, että he saattaisivat hänet pois, hänet ja hänen vaimonsa sekä kaiken, mitä hänellä oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Niin Abram lähti pois Egyptistä, hän ja hänen vaimonsa ja kaikki, mitä hänellä oli, ja Loot hänen kanssaan, Etelämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Abram oli hyvin rikas: hänellä oli karjaa, hopeata ja kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Ja hän vaelsi, kulkien levähdyspaikasta toiseen, Etelämaasta Beeteliin asti, aina siihen paikkaan, missä hänen majansa oli ensi kerralla ollut, Beetelin ja Ain välillä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'siihen paikkaan, johon hän ennen oli rakentanut alttarin; ja Abram huusi siinä avuksi Herran nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Ja myöskin Lootilla, joka vaelsi Abramin kanssa, oli pikkukarjaa, raavaskarjaa ja telttoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Eikä maa riittänyt heidän asuakseen yhdessä, sillä heillä oli paljon omaisuutta, niin etteivät voineet yhdessä asua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Niin syntyi riitaa Abramin karjapaimenten ja Lootin karjapaimenten välillä. Ja siihen aikaan asuivat siinä maassa kanaanilaiset ja perissiläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Silloin Abram sanoi Lootille: \"Älköön olko riitaa meidän välillämme, minun ja sinun, älköönkä minun paimenteni ja sinun paimentesi välillä, sillä olemmehan veljeksiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Eikö koko maa ole avoinna edessäsi? Eroa minusta. Jos sinä menet vasemmalle, niin minä menen oikealle, tahi jos sinä menet oikealle, niin minä menen vasemmalle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Ja Loot nosti silmänsä ja näki koko Jordanin lakeuden olevan runsasvetistä seutua; ennenkuin Herra hävitti Sodoman ja Gomorran, oli se Sooariin saakka niinkuin Herran puutarha, niinkuin Egyptin maa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Niin Loot valitsi itselleen koko Jordanin lakeuden ja siirtyi itään päin, ja he erkanivat toisistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram asettui Kanaanin maahan, Loot asettui lakeuden kaupunkeihin ja siirtyi siirtymistään telttoineen Sodomaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Mutta Sodoman kansa oli kovin pahaa ja syntistä Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Ja Herra sanoi Abramille, sen jälkeen kuin Loot oli hänestä eronnut: \"Nosta silmäsi ja katso siitä paikasta, missä olet, pohjoiseen, etelään, itään ja länteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Sillä kaiken maan, jonka näet, minä annan sinulle ja sinun jälkeläisillesi ikuisiksi ajoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Ja minä teen sinun jälkeläistesi luvun paljoksi kuin maan tomun. Jos voidaan lukea maan tomu, niin voidaan lukea myöskin sinun jälkeläisesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Nouse ja vaella maata pitkin ja poikin, sillä sinulle minä sen annan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Ja Abram siirtyi siirtymistään telttoineen ja tuli ja asettui Mamren tammistoon, joka on Hebronin luona, ja rakensi sinne alttarin Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Ja tapahtui siihen aikaan, kun Amrafel oli Sinearin kuninkaana, Arjok Ellasarin kuninkaana, Kedorlaomer Eelamin kuninkaana ja Tidal Goojimin kuninkaana,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'että he alottivat sodan Beraa, Sodoman kuningasta, Birsaa, Gomorran kuningasta, Sinabia, Adman kuningasta, Semeberiä, Seboimin kuningasta, ja Belan, se on Sooarin, kuningasta vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Nämä kaikki liittoutuivat kokoontuen Siddimin laaksoon, jossa Suolameri nyt on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Kaksitoista vuotta he olivat olleet Kedorlaomerille alamaiset, mutta kolmantenatoista vuotena he tekivät kapinan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Neljäntenätoista vuotena tulivat Kedorlaomer ja ne kuninkaat, jotka olivat hänen kanssaan; ja he voittivat refalaiset Astarot-Karnaimissa ja suusilaiset Haamissa, niin myös eemiläiset Kirjataimin tasangolla');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'ja hoorilaiset heidän vuoristossaan, Seirissä, aina Eel-Paaraniin asti, joka on erämaan laidassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Ja he palasivat ja tulivat Mispatin lähteelle, se on Kaadekseen, ja valloittivat koko amalekilaisten maan ja voittivat myöskin amorilaiset, jotka asuivat Hasason-Taamarissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Silloin lähtivät Sodoman kuningas, Gomorran kuningas, Adman kuningas, Seboimin kuningas ja Belan, se on Sooarin, kuningas ja asettuivat Siddimin laaksossa sotarintaan heitä vastaan-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Eelamin kuningasta Kedorlaomeria, Goojimin kuningasta Tidalia, Sinearin kuningasta Amrafelia ja Ellasarin kuningasta Arjokia vastaan, neljä kuningasta viittä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Mutta Siddimin laakso oli täynnä maapihkakuoppia. Ja Sodoman ja Gomorran kuninkaat pakenivat ja putosivat niihin; mutta henkiin jääneet pakenivat vuoristoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Ja he ottivat Sodomasta ja Gomorrasta kaiken tavaran ja kaikki ruokavarat ja menivät matkaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Ja lähtiessään he ottivat mukaansa myöskin Lootin, Abramin veljenpojan, ja hänen omaisuutensa; hän näet asui Sodomassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Mutta muuan pakolainen tuli ja ilmoitti siitä Abramille, hebrealaiselle; tämä asui tammistossa, joka oli amorilaisen Mamren, Eskolin ja Aanerin veljen, oma, ja he olivat Abramin liittolaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Kun Abram kuuli, että hänen sukulaisensa oli otettu vangiksi, aseisti hän luotettavimmat palvelijansa, jotka olivat hänen kodissaan syntyneet, kolmesataa kahdeksantoista miestä, ja ajoi vihollisia takaa aina Daaniin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Ja hän jakoi väkensä ja hyökkäsi palvelijoineen yöllä vihollisten kimppuun ja voitti heidät ja ajoi heitä takaa aina Hoobaan saakka, joka on Damaskosta pohjoiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Ja hän toi takaisin kaiken tavaran; myöskin sukulaisensa Lootin ja hänen tavaransa hän toi takaisin, niin myös vaimot ja muun väen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Kun hän oli paluumatkalla, voitettuaan Kedorlaomerin ja ne kuninkaat, jotka olivat tämän kanssa, meni Sodoman kuningas häntä vastaan Saaven laaksoon, jota sanotaan \"Kuninkaan laaksoksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Ja Melkisedek, Saalemin kuningas, toi leipää ja viiniä; hän oli Jumalan, Korkeimman, pappi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Ja hän siunasi hänet sanoen: \"Siunatkoon Abramia Jumala, Korkein, taivaan ja maan luoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Ja kiitetty olkoon Jumala, Korkein, joka antoi vihollisesi sinun käsiisi.\" Ja Abram antoi hänelle kymmenykset kaikesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Ja Sodoman kuningas sanoi Abramille: \"Anna minulle väki ja pidä sinä tavara\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Mutta Abram sanoi Sodoman kuninkaalle: \"Minä nostan käteni Herran, Jumalan, Korkeimman, taivaan ja maan luojan, puoleen ja vannon:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'En totisesti ota, en langan päätä, en kengän paulaa enkä mitään muuta, mikä on sinun, ettet sanoisi: \'Minä olen tehnyt Abramin rikkaaksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'En tahdo mitään, paitsi mitä palvelijat ovat kuluttaneet ja mikä on niille miehille tuleva, jotka minua seurasivat, Aanerille, Eskolille ja Mamrelle; he saakoot osansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Näiden tapausten jälkeen tuli Abramille näyssä tämä Herran sana: \"Älä pelkää, Abram! Minä olen sinun kilpesi; sinun palkkasi on oleva sangen suuri.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Mutta Abram sanoi: \"Oi Herra, Herra, mitä sinä minulle annat? Minä lähden täältä lapsetonna, ja omaisuuteni haltijaksi tulee damaskolainen mies, Elieser.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Ja Abram sanoi vielä: \"Sinä et ole antanut minulle jälkeläistä; katso, talossani syntynyt palvelija on minut perivä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Mutta katso, hänelle tuli tämä Herran sana: \"Hän ei ole sinua perivä, vaan joka lähtee sinun omasta ruumiistasi, hän on sinut perivä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Ja hän vei hänet ulos ja sanoi: \"Katso taivaalle ja lue tähdet, jos ne taidat lukea\". Ja hän sanoi hänelle: \"Niin paljon on sinulla oleva jälkeläisiä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Ja Abram uskoi Herraan, ja Herra luki sen hänelle vanhurskaudeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Ja hän sanoi hänelle: \"Minä olen Herra, joka toin sinut Kaldean Uurista, antaakseni sinulle tämän maan omaksesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Mutta hän sanoi: \"Oi Herra, Herra, mistä minä tiedän, että saan sen omakseni?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Ja hän sanoi hänelle: \"Tuo minulle kolmivuotias hieho, kolmivuotias vuohi ja kolmivuotias oinas sekä metsäkyyhkynen ja nuori kyyhkynen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Ja hän toi nämä kaikki ja halkaisi ne ja asetti puolikkaat vastakkain; lintuja hän ei kuitenkaan halkaissut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Niin laskeutui petolintuja ruumiiden päälle, mutta Abram karkoitti ne pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Kun aurinko oli laskemaisillaan, valtasi raskas uni Abramin, ja katso, kauhu ja suuri pimeys valtasi hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Ja Herra sanoi Abramille: \"Niin tiedä totisesti, että sinun jälkeläisesi tulevat elämään muukalaisina maassa, joka ei ole heidän omansa, ja heidän on niitä palveleminen, ja ne sortavat heitä neljäsataa vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Mutta myös sen kansan, jota he palvelevat, minä tuomitsen; ja sitten he pääsevät lähtemään, mukanaan paljon tavaraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Mutta sinä saat mennä isiesi tykö rauhassa, ja sinut haudataan päästyäsi korkeaan ikään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Ja neljännessä polvessa sinun jälkeläisesi palaavat tänne takaisin; sillä amorilaisten syntivelka ei ole vielä täysi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Ja kun aurinko oli laskenut ja oli tullut pilkkopimeä, näkyi suitsuava pätsi ja liekehtivä tuli, joka liikkui uhrikappaleiden välissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Sinä päivänä Herra teki Abramin kanssa liiton, sanoen: \"Sinun jälkeläisillesi minä annan tämän maan, Egyptin virrasta aina suureen virtaan, Eufrat-virtaan saakka:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'keeniläiset, kenissiläiset, kadmonilaiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'heettiläiset, perissiläiset, refalaiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'amorilaiset, kanaanilaiset, girgasilaiset ja jebusilaiset\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Saarai, Abramin vaimo, ei synnyttänyt hänelle lasta. Mutta Saarailla oli egyptiläinen orjatar, jonka nimi oli Haagar.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Ja Saarai sanoi Abramille: \"Katso, Herra on sulkenut minut synnyttämästä; yhdy siis minun orjattareeni, ehkä minä saisin lapsia hänestä\". Ja Abram kuuli Saaraita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Ja Saarai, Abramin vaimo, otti egyptiläisen orjattarensa Haagarin, sitten kuin Abram oli asunut kymmenen vuotta Kanaanin maassa, ja antoi hänet miehellensä Abramille vaimoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Ja hän yhtyi Haagariin, ja Haagar tuli raskaaksi. Kun hän huomasi olevansa raskaana, tuli hänen emäntänsä halvaksi hänen silmissään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Silloin Saarai sanoi Abramille: \"Minun kärsimäni vääryys kohdatkoon sinua; minä annoin orjattareni sinun syliisi, mutta kun hän huomasi olevansa raskaana, tulin minä halvaksi hänen silmissään. Herra tuomitkoon meidän välillämme, minun ja sinun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Abram sanoi Saaraille: \"Katso, orjattaresi on sinun vallassasi, tee hänelle, mitä tahdot\". Niin Saarai kuritti häntä, ja hän pakeni hänen luotaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Ja Herran enkeli tapasi hänet vesilähteeltä erämaassa, sen lähteen luota, joka on Suurin tien varressa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Ja hän sanoi: \"Haagar, Saarain orjatar, mistä tulet ja mihin menet?\" Hän vastasi: \"Olen paossa emäntääni Saaraita\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Ja Herran enkeli sanoi hänelle: \"Palaa emäntäsi tykö ja nöyrry hänen kätensä alle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Ja Herran enkeli sanoi hänelle: \"Minä teen sinun jälkeläistesi luvun niin suureksi, ettei heitä voida lukea heidän paljoutensa tähden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Vielä Herran enkeli puhui hänelle: \"Katso, sinä olet raskaana ja synnytät pojan ja kutsut hänet Ismaeliksi, sillä Herra on kuullut sinun hätäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Hänestä tulee mies kuin villiaasi: hänen kätensä on kaikkia vastaan, ja kaikkien käsi on häntä vastaan, ja hän on kaikkien veljiensä niskassa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Ja Haagar nimitti Herraa, joka oli häntä puhutellut, nimellä: \"Sinä olet ilmestyksen Jumala\". Sillä hän sanoi: \"Olenko minä tässä vilaukselta saanut nähdä hänet, joka minut näkee?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Sentähden kutsutaan kaivoa nimellä Lahai-Roin kaivo; se on Kaadeksen ja Beredin välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Ja Haagar synnytti Abramille pojan, ja Abram antoi pojallensa, jonka Haagar oli hänelle synnyttänyt, nimen Ismael.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Ja Abram oli kahdeksankymmenen kuuden vuoden vanha, kun Haagar synnytti hänelle Ismaelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Kun Abram oli yhdeksänkymmenen yhdeksän vuoden vanha, ilmestyi Herra hänelle ja sanoi hänelle: \"Minä olen Jumala, Kaikkivaltias; vaella minun edessäni ja ole nuhteeton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Ja minä teen liittoni meidän välillemme, minun ja sinun, ja lisään sinut ylen runsaasti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Ja Abram lankesi kasvoilleen, ja Jumala puhui hänelle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '\"Katso, tämä on minun liittoni sinun kanssasi: sinusta tulee kansojen paljouden isä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Niin älköön sinua enää kutsuttako Abramiksi, vaan nimesi olkoon Aabraham, sillä minä teen sinusta kansojen paljouden isän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Minä teen sinut sangen hedelmälliseksi ja annan sinusta tulla kansoja, ja sinusta on polveutuva kuninkaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Ja minä teen liiton sinun kanssasi ja sinun jälkeläistesi kanssa, sukupolvesta sukupolveen, iankaikkisen liiton, ollakseni sinun ja sinun jälkeläistesi Jumala,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'ja minä annan sinulle ja sinun jälkeläisillesi sen maan, jossa sinä muukalaisena asut, koko Kanaanin maan, ikuiseksi omaisuudeksi; ja minä olen heidän Jumalansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Ja Jumala sanoi Aabrahamille: \"Mutta sinä pidä minun liittoni, sinä ja sinun jälkeläisesi, sukupolvesta sukupolveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Ja tämä on minun liittoni sinun ja sinun jälkeläistesi kanssa; pitäkää se: ympärileikatkaa jokainen miehenpuoli keskuudessanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Ympärileikatkaa esinahkanne liha, ja se olkoon liiton merkki meidän välillämme, minun ja teidän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Sukupolvesta sukupolveen ympärileikattakoon jokainen poikalapsi teidän keskuudessanne kahdeksan päivän vanhana, niin hyvin kotona syntynyt palvelija kuin muukalaiselta, keneltä tahansa, rahalla ostettu, joka ei ole sinun jälkeläisiäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Ympärileikattakoon sekä kotonasi syntynyt että rahalla ostamasi; ja niin minun liittoni on oleva merkitty teidän lihaanne iankaikkiseksi liitoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Mutta ympärileikkaamaton miehenpuoli, jonka esinahan liha ei ole ympärileikattu, hävitettäköön kansastansa; hän on rikkonut minun liittoni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Ja Jumala sanoi Aabrahamille: \"Älä kutsu vaimoasi Saaraita enää Saaraiksi, vaan Saara olkoon hänen nimensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Ja minä siunaan häntä ja annan hänestäkin sinulle pojan; niin, minä siunaan häntä, ja hänestä tulee kansakuntia, polveutuu kansojen kuninkaita.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Aabraham lankesi kasvoillensa ja naurahti, sillä hän ajatteli sydämessään: \"Voiko satavuotiaalle syntyä poika, ja voiko Saara, joka on yhdeksänkymmenen vuoden vanha, vielä synnyttää?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Ja Aabraham sanoi Jumalalle: \"Kunpa edes Ismael saisi elää sinun edessäsi!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Niin Jumala sanoi: \"Totisesti, sinun vaimosi Saara synnyttää sinulle pojan, ja sinun on pantava hänen nimekseen Iisak, ja minä teen liittoni hänen kanssaan iankaikkiseksi liitoksi hänen jälkeläisillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Mutta myös Ismaelista minä olen kuullut sinun rukouksesi; katso, minä siunaan häntä ja teen hänet hedelmälliseksi ja annan hänen lisääntyä ylen runsaasti. Hänestä on polveutuva kaksitoista ruhtinasta, ja minä teen hänestä suuren kansan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Mutta liittoni minä teen Iisakin kanssa, jonka Saara sinulle synnyttää tähän aikaan tulevana vuonna.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Kun Jumala oli lakannut puhumasta Aabrahamin kanssa, kohosi hän ylös hänen luotansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Ja Aabraham otti poikansa Ismaelin sekä kaikki kotona syntyneet ja kaikki rahalla ostamansa palvelijat, kaikki Aabrahamin perheen miehenpuolet, ja ympärileikkasi sinä samana päivänä heidän esinahkansa lihan, niinkuin Jumala oli hänelle sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Aabraham oli yhdeksänkymmenen yhdeksän vuoden vanha, kun hänen esinahkansa liha ympärileikattiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Ja hänen poikansa Ismael oli kolmentoista vuoden vanha, kun hänen esinahkansa liha ympärileikattiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Aabraham ja hänen poikansa Ismael ympärileikattiin sinä samana päivänä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'ja kaikki hänen perheensä miehet, sekä kotona syntyneet että muukalaisilta rahalla ostetut, ympärileikattiin hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Ja Herra ilmestyi hänelle Mamren tammistossa, jossa hän istui telttamajansa ovella päivän ollessa palavimmillaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Kun hän nosti silmänsä ja katseli, niin katso, kolme miestä seisoi hänen edessänsä; nähdessään heidät hän riensi heitä vastaan majan ovelta ja kumartui maahan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'ja sanoi: \"Herrani, jos olen saanut armon sinun silmiesi edessä, älä mene palvelijasi ohitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Sallikaa tuoda vähän vettä pestäksenne jalkanne ja levätkää puun siimeksessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Minä tuon palasen leipää virkistääksenne itseänne, ennenkuin jatkatte matkaanne, sillä kaiketi sitä varten olette poikenneet palvelijanne luo.\" He sanoivat: \"Tee, niinkuin olet puhunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Ja Aabraham kiiruhti majaan Saaran tykö ja sanoi: \"Hae joutuin kolme vakallista lestyjä jauhoja, sotke ja leivo kaltiaisia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Sitten Aabraham riensi karjaan, otti nuoren ja kauniin vasikan ja antoi palvelijalle, joka ryhtyi nopeasti sitä valmistamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Ja hän otti voita ja maitoa sekä vasikan, jonka hän oli valmistuttanut, ja pani ne heidän eteensä; itse hän seisoi heidän luonansa puun alla sillä aikaa, kuin he söivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Ja he kysyivät häneltä: \"Missä vaimosi Saara on?\" Hän vastasi: \"Tuolla majassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Ja hän sanoi: \"Minä palaan luoksesi tulevana vuonna tähän aikaan, ja katso, vaimollasi Saaralla on silloin oleva poika\". Mutta Saara kuunteli majan ovella hänen takanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Mutta Aabraham ja Saara olivat iäkkäät, eikä Saaran enää ollut, niinkuin naisten tavallisesti on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Sentähden Saara naurahti itseksensä ja ajatteli: \"Heräisikö minussa, näin kuihduttuani, vielä halu? Ja myös minun herrani on vanha.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Mutta Herra sanoi Aabrahamille: \"Miksi Saara nauroi ajatellen: \'Synnyttäisinkö minä todella, minä, joka olen näin vanha?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Onko mikään Herralle mahdotonta? Tähän aikaan minä palaan luoksesi tulevana vuonna, ja Saaralla on silloin poika.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Ja Saara kielsi sanoen: \"En minä nauranut\"; sillä hän pelkäsi. Mutta hän sanoi: \"Ei ole niin; sinä nauroit\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Silloin miehet nousivat siitä ja kääntyivät Sodomaan päin, ja Aabraham kulki heidän kanssaan saattaaksensa heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Ja Herra sanoi: \"Salaisinko minä Aabrahamilta, mitä olen tekevä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Onhan Aabrahamista tuleva suuri ja väkevä kansa, ja kaikki kansakunnat maan päällä tulevat hänessä siunatuiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Sillä minä olen valinnut hänet, että hän käskisi lapsiansa ja perhettänsä, joka jää hänen jälkeensä, noudattamaan Herran tietä ja tekemään sitä, mikä vanhurskaus ja oikeus on, jotta Herra antaisi Aabrahamille tapahtua, mitä hän on hänelle luvannut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Niin Herra sanoi: \"Valitushuuto Sodoman ja Gomorran tähden on suuri, ja heidän syntinsä ovat ylen raskaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Sentähden minä menen alas katsomaan, ovatko he todella tehneet kaiken sen, josta huuto on minun eteeni tullut, vai eivätkö; minä tahdon sen tietää.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Ja miehet kääntyivät sieltä ja kulkivat Sodomaan päin, mutta Aabraham jäi vielä seisomaan Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Ja Aabraham lähestyi häntä ja sanoi: \"Aiotko siis hukuttaa vanhurskaan yhdessä jumalattoman kanssa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Entä jos kaupungissa on viisikymmentä vanhurskasta; aiotko hukuttaa heidät etkä säästä paikkaa siellä olevain viidenkymmenen vanhurskaan tähden?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Pois se, että sinä näin tekisit: surmaisit vanhurskaan yhdessä jumalattoman kanssa, niin että vanhurskaan kävisi samoin kuin jumalattoman! Pois se sinusta! Eikö kaiken maan tuomari tekisi oikeutta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Ja Herra sanoi: \"Jos löydän Sodoman kaupungista viisikymmentä vanhurskasta, niin minä heidän tähtensä säästän koko paikan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Aabraham vastasi ja sanoi: \"Katso, olen rohjennut puhua Herralleni, vaikka olen tomu ja tuhka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Entä jos viidestäkymmenestä vanhurskaasta puuttuu viisi; hävitätkö viiden tähden koko kaupungin?\" Hän sanoi: \"En hävitä, jos löydän sieltä neljäkymmentä viisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Ja hän puhui vielä hänelle sanoen: \"Entä jos siellä on neljäkymmentä?\" Hän vastasi: \"Niiden neljänkymmenen tähden jätän sen tekemättä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Aabraham sanoi: \"Älköön Herrani vihastuko, että vielä puhun. Entä jos siellä on kolmekymmentä?\" Hän vastasi: \"En tee sitä, jos löydän sieltä kolmekymmentä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Mutta hän sanoi: \"Katso, minä olen rohjennut puhua Herralleni. Entä jos siellä on kaksikymmentä?\" Hän vastasi: \"Niiden kahdenkymmenen tähden jätän hävittämättä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Ja hän sanoi: \"Älköön Herrani vihastuko, että puhun vielä tämän ainoan kerran. Entä jos siellä on kymmenen?\" Hän vastasi: \"Niiden kymmenen tähden jätän hävittämättä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Ja Herra lähti pois, senjälkeen kuin hän oli lakannut puhumasta Aabrahamin kanssa, ja Aabraham palasi kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Ja ne kaksi enkeliä tulivat Sodomaan illalla, ja Loot istui Sodoman portissa; ja nähtyänsä heidät Loot nousi heitä vastaan ja kumartui maahan kasvoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Ja hän sanoi: \"Oi herrani, poiketkaa palvelijanne taloon yöksi ja peskää jalkanne! Aamulla varhain voitte jatkaa matkaanne.\" He sanoivat: \"Emme, vaan me jäämme yöksi taivasalle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Mutta hän pyysi heitä pyytämällä, ja he poikkesivat hänen luoksensa ja tulivat hänen taloonsa. Ja hän valmisti heille aterian ja leipoi happamattomia leipiä, ja he söivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Ennenkuin he olivat laskeutuneet levolle, piirittivät kaupungin miehet, sodomalaiset, sekä nuoret että vanhat, koko kansa kaikkialta, talon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Ja he huusivat Lootia sanoen hänelle: \"Missä ne miehet ovat, jotka tulivat luoksesi yöllä? Tuo heidät tänne meidän luoksemme, ryhtyäksemme heihin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Silloin Loot meni ulos heidän luokseen portille ja sulki oven jälkeensä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'ja sanoi: \"Älkää, veljeni, tehkö niin pahoin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Katsokaa, minulla on kaksi tytärtä, jotka eivät vielä miehestä tiedä. Ne minä tuon teille, tehkää heille, mitä tahdotte. Älkää vain tehkö näille miehille mitään pahaa, sillä he ovat tulleet minun kattoni suojaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Mutta he vastasivat: \"Mene tiehesi!\" Ja he sanoivat: \"Tuo yksi on tullut tänne asumaan muukalaisena, ja yhtäkaikki hän alati pyrkii hallitsemaan. Nytpä me pitelemmekin sinua pahemmin kuin heitä.\" Ja he tunkeutuivat väkivaltaisesti miehen, Lootin, kimppuun ja kävivät murtamaan ovea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Silloin miehet ojensivat kätensä, vetivät Lootin luoksensa huoneeseen ja sulkivat oven.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Ja he sokaisivat ne miehet, jotka olivat talon ovella, sekä nuoret että vanhat, niin että he turhaan koettivat löytää ovea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Ja miehet sanoivat Lootille: \"Vieläkö sinulla on ketään omaista täällä? Vie pois täältä vävysi, poikasi, tyttäresi ja kaikki, keitä sinulla kaupungissa on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'sillä me hävitämme tämän paikan. Koska huuto heistä on käynyt suureksi Herran edessä, lähetti Herra meidät hävittämään sen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Silloin Loot meni puhuttelemaan vävyjänsä, joiden oli aikomus ottaa hänen tyttärensä, ja sanoi: \"Nouskaa, lähtekää pois tästä paikasta, sillä Herra hävittää tämän kaupungin\". Mutta hänen vävynsä luulivat hänen laskevan leikkiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Aamun sarastaessa enkelit kiirehtivät Lootia sanoen: \"Nouse, ota vaimosi ja molemmat tyttäresi, jotka ovat luonasi, ettet hukkuisi kaupungin syntivelan tähden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Ja kun hän vielä vitkasteli, tarttuivat miehet hänen käteensä sekä hänen vaimonsa ja molempien tyttäriensä käteen, sillä Herra tahtoi säästää hänet, ja veivät hänet ulos ja jättivät hänet ulkopuolelle kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Ja viedessään heitä ulos sanoi mies: \"Pakene henkesi tähden, älä katso taaksesi äläkä pysähdy mihinkään lakeudella. Pakene vuorille, ettet hukkuisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Mutta Loot sanoi heille: \"Oi herrani, ei niin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Katso, palvelijasi on saanut armon sinun silmiesi edessä, ja suuri on sinun laupeutesi, jota olet minulle osoittanut pelastaaksesi henkeni, mutta minä en voi päästä pakoon vuorille; pelkään, että onnettomuus saavuttaa minut ja minä kuolen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Katso, tuolla on kaupunki lähellä, vähän matkan päässä, paetakseni sinne; salli minun pelastua sinne-onhan se vähän matkan päässä-jäädäkseni eloon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Ja hän sanoi hänelle: \"Katso, minä teen sinulle mieliksi tässäkin kohden; en hävitä kaupunkia, josta puhut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Pakene nopeasti sinne, sillä minä en voi tehdä mitään, ennenkuin olet sinne saapunut.\" Siitä kaupunki sai nimekseen Sooar.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Aurinko oli noussut, kun Loot saapui Sooariin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Ja Herra antoi sataa Sodoman ja Gomorran päälle tulikiveä ja tulta, Herran tyköä taivaasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'ja hävitti nämä kaupungit ynnä koko lakeuden sekä kaikki niiden kaupunkien asukkaat ja maan kasvullisuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Ja Lootin vaimo, joka tuli hänen jäljessään, katsoi taaksensa, ja niin hän muuttui suolapatsaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Aabraham nousi varhain aamulla ja meni siihen paikkaan, jossa hän oli seisonut Herran edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'katseli Sodomaan ja Gomorraan päin ja yli koko lakeuden, ja katso, maasta nousi savu niinkuin pätsin savu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Kun Jumala tuhosi sen lakeuden kaupungit, muisti Jumala Aabrahamia ja johdatti Lootin pois hävityksen keskeltä, hävittäessään ne kaupungit, joissa Loot oli asunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Ja Loot lähti Sooarista ja asettui vuoristoon molempien tyttäriensä kanssa, sillä hän pelkäsi asua Sooarissa; ja hän asui luolassa, hän ja hänen molemmat tyttärensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Niin vanhempi sanoi nuoremmalle: \"Isämme on vanha, eikä tässä maassa ole ketään miestä, joka voisi tulla luoksemme siten, kuin on kaiken maan tapa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Tule, juottakaamme isällemme viiniä ja maatkaamme hänen kanssaan, saadaksemme isästämme jälkeläisen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Niin he juottivat sinä yönä isällensä viiniä. Ja vanhempi meni ja makasi hänen kanssaan, eikä tämä huomannut, milloin hän tuli hänen viereensä ja milloin hän nousi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Seuraavana päivänä sanoi vanhempi nuoremmalle: \"Katso, minä makasin viime yönä isäni kanssa; juottakaamme hänelle tänäkin yönä viiniä, ja mene sinä ja makaa hänen kanssaan, saadaksemme isästämme jälkeläisen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Niin he juottivat sinäkin yönä isällensä viiniä; ja nuorempi meni ja makasi hänen kanssaan, eikä tämä huomannut, milloin hän tuli hänen viereensä ja milloin hän nousi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Ja niin Lootin molemmat tyttäret tulivat isästänsä raskaiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Ja vanhempi synnytti pojan ja antoi hänelle nimen Mooab; hänestä polveutuvat mooabilaiset aina tähän päivään saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Ja myöskin nuorempi synnytti pojan ja antoi hänelle nimen Ben-Ammi; hänestä polveutuvat ammonilaiset aina tähän päivään saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Ja Aabraham siirtyi sieltä Etelämaahan ja asettui Kaadeksen ja Suurin välimaille; ja hän asui jonkun aikaa Gerarissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Ja Aabraham sanoi vaimostansa Saarasta: \"Hän on minun sisareni\". Niin Abimelek, Gerarin kuningas, lähetti noutamaan Saaran luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Mutta Jumala tuli Abimelekin tykö yöllä unessa ja sanoi hänelle: \"Katso, sinun on kuoltava sen vaimon tähden, jonka olet ottanut, sillä hän on toisen miehen aviovaimo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Mutta Abimelek ei ollut ryhtynyt häneen, ja hän sanoi: \"Herra, surmaatko syyttömänkin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Eikö hän itse sanonut minulle: \'Hän on minun sisareni\'? Ja samoin tämäkin sanoi: \'Hän on minun veljeni\'. Olen tehnyt tämän vilpittömin sydämin ja viattomin käsin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Ja Jumala sanoi hänelle unessa: \"Niin, minä tiedän, että sinä teit sen vilpittömin sydämin. Sentähden minä estinkin sinut tekemästä syntiä minua vastaan enkä sallinut sinun kajota häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Niin anna nyt miehelle hänen vaimonsa takaisin, sillä hän on profeetta, ja hän on rukoileva sinun puolestasi, että saisit elää. Mutta jollet anna häntä takaisin, niin tiedä, että olet kuolemalla kuoleva, sinä ja kaikki sinun omaisesi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Niin Abimelek nousi varhain aamulla ja kutsui kaikki palvelijansa ja kertoi heille tämän kaiken; ja miehet olivat kovin peloissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Ja Abimelek kutsui Aabrahamin ja sanoi hänelle: \"Mitä oletkaan meille tehnyt! Mitä minä olen rikkonut sinua vastaan, koska olet saattanut minut ja minun valtakuntani syypääksi näin suureen rikokseen? Sinä olet tehnyt minulle, mitä ei sovi tehdä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Ja Abimelek sanoi vielä Aabrahamille: \"Mikä oli tarkoituksesi, kun tämän teit?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Aabraham vastasi: \"Minä ajattelin näin: \'Tällä paikkakunnalla ei varmaankaan peljätä Jumalaa; he surmaavat minut vaimoni tähden\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Ja hän onkin todella minun sisareni, isäni tytär, vaikkei olekaan äitini tytär; ja niin hänestä tuli minun vaimoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Mutta kun Jumala lähetti minut kulkemaan pois isäni kodista, sanoin minä hänelle: \'Osoita minulle se rakkaus, että, mihin paikkaan ikinä tulemmekin, sanot minusta: hän on minun veljeni\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Silloin Abimelek otti pikkukarjaa ja raavaskarjaa, palvelijoita ja palvelijattaria ja antoi ne Aabrahamille. Ja hän lähetti hänelle takaisin hänen vaimonsa Saaran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Ja Abimelek sanoi: \"Katso, minun maani on avoinna edessäsi; asu, missä mielesi tekee!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Ja Saaralle hän sanoi: \"Katso, minä annan veljellesi tuhat sekeliä hopeata. Olkoot ne sinulle hyvitykseksi kaikkien niiden edessä, jotka sinun kanssasi ovat; niin olet kaikkien edessä todistettu viattomaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Mutta Aabraham rukoili Jumalaa, ja Jumala paransi Abimelekin ja hänen vaimonsa ja hänen orjattarensa, niin että he synnyttivät lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Sillä Herra oli sulkenut jokaisen kohdun Abimelekin huoneessa Saaran, Aabrahamin vaimon, tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Ja Herra piti Saarasta huolen, niinkuin oli luvannut; ja Herra teki Saaralle, niinkuin oli puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Ja Saara tuli raskaaksi ja synnytti Aabrahamille pojan hänen vanhoilla päivillään, juuri sinä aikana, jonka Jumala oli hänelle sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Ja Aabraham nimitti poikansa, joka hänelle oli syntynyt, sen, jonka Saara oli hänelle synnyttänyt, Iisakiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Ja Aabraham ympärileikkasi poikansa Iisakin, tämän ollessa kahdeksan päivän vanha, niinkuin Jumala oli hänen käskenyt tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Aabraham oli sadan vuoden vanha, kun hänen poikansa Iisak syntyi hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Ja Saara sanoi: \"Jumala on saattanut minut naurunalaiseksi; kuka ikinä saa tämän kuulla, se nauraa minulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Ja hän sanoi vielä: \"Kuka olisi tiennyt sanoa Aabrahamille: Saara on imettävä lapsia? Ja nyt minä kuitenkin olen synnyttänyt hänelle pojan hänen vanhoilla päivillään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Ja poika kasvoi, ja hänet vieroitettiin. Ja Aabraham laittoi suuret pidot siksi päiväksi, jona Iisak vieroitettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Ja Saara näki egyptiläisen Haagarin pojan, jonka tämä oli Aabrahamille synnyttänyt, ilvehtivän');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'ja sanoi Aabrahamille: \"Aja pois tuo orjatar poikinensa, sillä ei tuon orjattaren poika saa periä minun poikani, Iisakin, kanssa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Aabraham pahastui suuresti tästä puheesta poikansa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Mutta Jumala sanoi Aabrahamille: \"Älä pahastu siitä poikasi ja orjattaresi tähden. Kuule Saaraa kaikessa, mitä hän sinulle sanoo, sillä ainoastaan Iisakista sinä saat nimellesi jälkeläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Mutta myöskin orjattaren pojasta minä teen suuren kansan, koska hän on sinun jälkeläisesi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Varhain seuraavana aamuna Aabraham otti leipää ja vesileilin ja antoi ne Haagarille, pannen ne hänen olalleen, sekä pojan, ja lähetti hänet menemään. Hän lähti ja harhaili Beerseban erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Mutta kun vesi loppui leilistä, heitti hän pojan pensaan alle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'meni ja istui syrjään jousenkantaman päähän, sillä hän ajatteli: \"En voi nähdä pojan kuolevan\". Ja istuessaan siinä syrjässä hän korotti äänensä ja itki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Silloin Jumala kuuli pojan valituksen, ja Jumalan enkeli huusi taivaasta Haagarille sanoen: \"Mikä sinun on, Haagar? Älä pelkää, sillä Jumala on kuullut pojan valituksen, siinä missä hän makaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Nouse, nosta poika maasta ja tartu hänen käteensä, sillä minä teen hänestä suuren kansan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Ja Jumala avasi hänen silmänsä, niin että hän huomasi vesikaivon. Ja hän meni ja täytti leilin vedellä ja antoi pojan juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Ja Jumala oli pojan kanssa, ja hän kasvoi ja asui erämaassa, ja hänestä tuli jousimies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Ja hän asui Paaranin erämaassa; ja hänen äitinsä otti hänelle vaimon Egyptin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Siihen aikaan puhui Abimelek ja hänen sotapäällikkönsä Piikol Aabrahamille sanoen: \"Jumala on sinun kanssasi kaikessa, mitä teet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Vanno nyt tässä minulle Jumalan kautta, ettet ole oleva petollinen minulle etkä minun suvulleni etkä jälkeläisilleni, vaan tee sinäkin laupeus minulle ja sille maalle, jossa muukalaisena asut, niinkuin minä olen sinulle tehnyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Aabraham sanoi: \"Minä vannon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Aabraham nuhteli kuitenkin Abimelekia vesikaivon tähden, jonka Abimelekin palvelijat olivat vallanneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Mutta Abimelek vastasi: \"En tiedä, kuka sen on tehnyt; et ole itse minulle mitään ilmoittanut, enkä ole siitä kuullut ennen kuin tänään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Silloin Aabraham otti pikkukarjaa ja raavaskarjaa ja antoi Abimelekille; ja he tekivät molemmat keskenänsä liiton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Ja Aabraham asetti laumasta seitsemän uuhikaritsaa erilleen muista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Silloin Abimelek sanoi Aabrahamille: \"Mitä tarkoittavat nuo seitsemän karitsaa, jotka olet asettanut tuonne erilleen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Hän vastasi: \"Nämä seitsemän karitsaa on sinun otettava minun kädestäni, todistukseksi minulle siitä, että tämä kaivo on minun kaivamani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Siitä kutsuttiin paikkaa Beersebaksi, koska he molemmat vannoivat siinä toisilleen valan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Niin he tekivät liiton Beersebassa. Ja Abimelek nousi ja Piikol, hänen sotapäällikkönsä, ja he palasivat filistealaisten maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Ja Aabraham istutti tamariskipuun Beersebaan ja huusi siinä avuksi Herran, iankaikkisen Jumalan, nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Ja Aabraham asui kauan muukalaisena filistealaisten maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Näiden tapausten jälkeen Jumala koetteli Aabrahamia ja sanoi hänelle: \"Aabraham!\" Hän vastasi: \"Tässä olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Ja hän sanoi: \"Ota Iisak, ainokainen poikasi, jota rakastat, ja mene Moorian maahan ja uhraa hänet siellä polttouhriksi vuorella, jonka minä sinulle sanon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Varhain seuraavana aamuna Aabraham satuloi aasinsa ja otti mukaansa kaksi palvelijaansa sekä poikansa Iisakin, ja halottuaan polttouhripuita hän lähti menemään siihen paikkaan, jonka Jumala oli hänelle sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Kolmantena päivänä Aabraham nosti silmänsä ja näki sen paikan kaukaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Silloin Aabraham sanoi palvelijoilleen: \"Jääkää tähän aasin kanssa. Minä ja poika menemme tuonne rukoilemaan; sitten me palaamme luoksenne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Ja Aabraham otti polttouhripuut ja sälytti ne poikansa Iisakin selkään; itse hän otti käteensä tulen ja veitsen, ja niin he astuivat molemmat yhdessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Iisak puhui isällensä Aabrahamille sanoen: \"Isäni!\" Tämä vastasi: \"Tässä olen, poikani\". Ja hän sanoi: \"Katso, tässä on tuli ja halot, mutta missä on lammas polttouhriksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Aabraham vastasi: \"Jumala on katsova itselleen lampaan polttouhriksi, poikani\". Ja he astuivat molemmat yhdessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Ja kun he olivat tulleet siihen paikkaan, jonka Jumala oli hänelle sanonut, rakensi Aabraham siihen alttarin, latoi sille halot, sitoi poikansa Iisakin ja pani hänet alttarille halkojen päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Ja Aabraham ojensi kätensä ja tarttui veitseen teurastaakseen poikansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Silloin Herran enkeli huusi hänelle taivaasta sanoen: \"Aabraham, Aabraham!\" Hän vastasi: \"Tässä olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Niin hän sanoi: \"Älä satuta kättäsi poikaan äläkä tee hänelle mitään, sillä nyt minä tiedän, että sinä pelkäät Jumalaa, kun et kieltänyt minulta ainokaista poikaasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Niin Aabraham nosti silmänsä ja huomasi takanansa oinaan, joka oli sarvistaan takertunut pensaikkoon. Ja Aabraham meni, otti oinaan ja uhrasi sen polttouhriksi poikansa sijasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Ja Aabraham pani sen paikan nimeksi \"Herra näkee\". Niinpä vielä tänä päivänä sanotaan: \"Vuorella, missä Herra ilmestyy\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Ja Herran enkeli huusi Aabrahamille toistamiseen taivaasta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'ja sanoi: \"Minä vannon itse kauttani, sanoo Herra: Sentähden että tämän teit etkä kieltänyt minulta ainokaista poikaasi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'minä runsaasti siunaan sinua ja teen sinun jälkeläistesi luvun paljoksi kuin taivaan tähdet ja hiekka, joka on meren rannalla, ja sinun jälkeläisesi valtaavat vihollistensa portit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Ja sinun siemenessäsi tulevat siunatuiksi kaikki kansakunnat maan päällä, sentähden että olit minun äänelleni kuuliainen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Sitten Aabraham palasi palvelijainsa luo, ja he nousivat ja kulkivat yhdessä Beersebaan. Ja Aabraham jäi asumaan Beersebaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Näiden tapausten jälkeen ilmoitettiin Aabrahamille: \"Katso, myöskin Milka on synnyttänyt poikia sinun veljellesi Naahorille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Nämä olivat Uus, hänen esikoisensa, tämän veli Buus, Kemuel, Aramin isä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Kesed, Haso, Pildas, Jidlaf ja Betuel;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'ja Betuelille syntyi Rebekka. Nämä kahdeksan synnytti Milka Naahorille, Aabrahamin veljelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Ja hänen sivuvaimonsa, nimeltä Reuma, synnytti myös lapsia: Tebahin, Gahamin, Tahaan ja Maakan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Ja Saara eli sadan kahdenkymmenen seitsemän vuoden vanhaksi; niin vanhaksi eli Saara.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Ja Saara kuoli Kirjat-Arbassa, se on Hebronissa, Kanaanin maassa. Ja Aabraham meni murehtimaan Saaraa ja itkemään häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Senjälkeen Aabraham nousi ja lähti vainajan luota ja puhui heettiläisille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '\"Minä olen muukalainen ja vieras teidän keskuudessanne; antakaa minulle perintöhauta maassanne, haudatakseni ja kätkeäkseni siihen vainajani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Heettiläiset vastasivat Aabrahamille, sanoen hänelle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '\"Kuule meitä, herra. Sinä olet Jumalan ruhtinas meidän keskuudessamme; hautaa vainajasi parhaaseen hautaamme. Ei kukaan meistä kiellä sinua hautaamasta vainajaasi hautaansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Niin Aabraham nousi ja kumarsi maan kansalle, heettiläisille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'ja puhui heille sanoen: \"Jos teidän mieleenne on, että minä hautaan ja kätken vainajani, niin kuulkaa minua ja taivuttakaa Efron, Sooharin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'antamaan minulle Makpelan luola, joka on hänen omansa ja on hänen vainionsa perällä. Täydestä hinnasta hän antakoon sen minulle perintöhaudaksi teidän keskuudessanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Mutta Efron istui siellä heettiläisten joukossa. Ja Efron, heettiläinen, vastasi Aabrahamille heettiläisten kuullen, kaikkien, jotka kulkivat hänen kaupunkinsa portista, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, '\"Ei, herrani, vaan kuule minua. Vainion minä lahjoitan sinulle ja myöskin luolan, joka siinä on, minä lahjoitan sinulle; kansalaisteni nähden minä sen sinulle lahjoitan. Hautaa vainajasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Ja Aabraham kumarsi maan kansalle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'ja puhui Efronille, maan kansan kuullen, sanoen: \"Jospa kuitenkin-oi, kuule minua! Minä maksan vainion hinnan; ota se minulta ja anna minun haudata siihen vainajani.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Efron vastasi Aabrahamille, sanoen hänelle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, '\"Herrani, kuule minua. Neljänsadan hopeasekelin maa, mitä se minulle ja sinulle merkitsee? Hautaa vainajasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Kuultuaan Efronin sanat Aabraham punnitsi Efronille sen rahasumman, jonka tämä oli maininnut heettiläisten kuullen, neljäsataa hopeasekeliä, kaupassa käypää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Niin Efronin vainio, joka on Makpelassa itään päin Mamresta, sekä vainio että siellä oleva luola ynnä kaikki puut, jotka kasvoivat vainiolla, koko sillä alueella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'joutuivat Aabrahamin omaksi kaikkien heettiläisten nähden, jotka kulkivat hänen kaupunkinsa portista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Senjälkeen Aabraham hautasi vaimonsa Saaran luolaan, joka on Makpelan vainiolla, itään päin Mamresta, se on Hebronista, Kanaanin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Niin vainio ja siellä oleva luola siirtyi heettiläisiltä Aabrahamille, perintöhaudaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Ja Aabraham oli vanha ja iälliseksi tullut, ja Herra oli siunannut Aabrahamia kaikessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Niin Aabraham sanoi palvelijallensa, talonsa vanhimmalle, joka hallitsi kaikkea, mitä hänellä oli: \"Pane kätesi kupeeni alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Minä vannotan sinua Herran, taivaan ja maan Jumalan, kautta, ettet ota pojalleni vaimoa kanaanilaisten tyttäristä, joiden keskuudessa minä asun,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'vaan menet minun omaan maahani ja sukuni luo ja otat sieltä vaimon pojalleni Iisakille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Palvelija sanoi hänelle: \"Entä jos tyttö ei tahdo seurata minua tähän maahan, onko minun silloin vietävä poikasi takaisin siihen maahan, josta olet lähtenyt?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Aabraham vastasi hänelle: \"Varo, ettet vie poikaani takaisin sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Herra, taivaan Jumala, joka otti minut pois isäni kodista ja synnyinmaastani, hän, joka puhui minulle ja vannoi minulle sanoen: \'Sinun jälkeläisillesi minä annan tämän maan\', hän lähettää enkelinsä sinun edelläsi, niin että saat sieltä vaimon pojalleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Mutta jos tyttö ei tahdo seurata sinua, niin olet tästä valasta vapaa. Älä vain vie poikaani sinne takaisin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Niin palvelija pani kätensä herransa Aabrahamin kupeen alle ja lupasi sen hänelle valalla vannoen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Ja palvelija otti herransa kameleista kymmenen sekä kaikkinaisia kalleuksia herransa tavaroista; ja hän nousi ja lähti Mesopotamiaan, Naahorin kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Ja hän antoi kamelien asettua kaupungin ulkopuolelle vesikaivon ääreen lepäämään, illan suussa, jolloin naiset tulivat vettä ammentamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Ja hän sanoi: \"Herra, minun herrani Aabrahamin Jumala, suo minulle tänään menestystä ja tee laupeus herralleni Aabrahamille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Katso, minä seison tässä lähteellä, ja kaupunkilaisten tyttäret tulevat ammentamaan vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Niin tapahtukoon, että se tyttö, jolle minä sanon: \'Kallista tänne vesiastiaasi juodakseni\', ja joka vastaa: \'Juo, minä juotan kamelisikin\', on juuri se, jonka sinä olet määrännyt palvelijallesi Iisakille; ja siitä minä tiedän, että olet tehnyt laupeuden herralleni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Tuskin hän oli lakannut puhumasta, niin tuli siihen Rebekka, joka oli Aabrahamin veljen Naahorin ja hänen vaimonsa Milkan pojan, Betuelin, tytär; ja hänellä oli vesiastia olallaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Ja tyttö oli näöltään hyvin ihana, neitsyt, johon ei mies ollut koskenut. Ja hän astui alas lähteelle, täytti astiansa ja tuli ylös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Silloin palvelija riensi häntä vastaan ja sanoi: \"Anna minun juoda vähän vettä astiastasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Hän vastasi: \"Juo, herrani\". Ja hän laski nopeasti astiansa alas kädelleen ja antoi hänen juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Ja annettuaan hänen juoda hän sanoi: \"Minä ammennan vettä myös sinun kameleillesi, kunnes ne ovat juoneet kyllikseen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Niin hän tyhjensi nopeasti astiansa kaukaloon ja riensi jälleen kaivolle ammentamaan vettä ja ammensi kaikille hänen kameleilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Ja mies katseli häntä ääneti saadakseen tietää, oliko Herra antanut hänen matkansa onnistua vai ei.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Kun kamelit olivat juoneet, otti mies kultaisen nenärenkaan, joka painoi puolen sekeliä, ja hänen käsiinsä kaksi rannerengasta, jotka painoivat kymmenen kultasekeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Ja hän kysyi: \"Kenenkä tytär olet? Sano minulle. Onko isäsi talossa tilaa yötä ollaksemme?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Hän vastasi hänelle: \"Olen Betuelin, Naahorin ja Milkan pojan, tytär\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Ja hän sanoi hänelle vielä: \"Meillä on runsaasti olkia ja rehua; myöskin yösijaa on meillä antaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Silloin mies kumartui maahan ja rukoili Herraa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'ja sanoi: \"Kiitetty olkoon Herra, minun herrani Aabrahamin Jumala, joka ei ole ottanut pois armoansa ja totuuttansa minun herraltani. Herra on johdattanut minut tätä tietä herrani veljen kotiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Mutta tyttö riensi ilmoittamaan äitinsä perheelle, mitä oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Rebekalla oli veli, jonka nimi oli Laaban; ja Laaban riensi ulos miehen luo lähteelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Sillä kun hän näki nenärenkaan ja rannerenkaat sisarensa käsissä ja kuuli sisarensa Rebekan kertovan ja sanovan: \"Näin mies puhui minulle\", meni hän miehen luo; ja katso, hän seisoi vielä kamelien luona lähteellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Ja hän sanoi hänelle: \"Tule sisään, sinä Herran siunattu. Minkätähden seisot ulkona? Minä olen valmistanut tilaa talossa ja sijaa kameleille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Niin mies tuli taloon, ja Laaban riisui kamelit ja antoi kameleille olkia ja rehua sekä hänelle ja hänen seuralaisilleen vettä jalkojen pesemiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Sitten pantiin ruokaa hänen eteensä, mutta hän sanoi: \"En syö, ennenkuin olen puhunut asiani\". Laaban vastasi: \"Puhu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Hän sanoi: \"Minä olen Aabrahamin palvelija.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Herra on suuresti siunannut minun herraani, niin että hänestä on tullut mahtava mies; hän on antanut hänelle pikkukarjaa ja raavaskarjaa, hopeata ja kultaa, palvelijoita ja palvelijattaria, kameleja ja aaseja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Ja Saara, herrani vaimo, on vanhalla iällänsä synnyttänyt herralleni pojan; ja tälle hän on antanut kaiken omaisuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Ja herrani vannotti minua sanoen: \'Älä ota pojalleni vaimoa kanaanilaisten tyttäristä, joiden maassa minä asun,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'vaan mene minun isäni kotiin ja sukuni luo ja ota sieltä pojalleni vaimo\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Silloin minä sanoin herralleni: \'Entä jos tyttö ei seuraa minua?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Hän vastasi minulle: \'Herra, jonka edessä minä olen vaeltanut, lähettää enkelinsä sinun kanssasi ja antaa matkasi onnistua, niin että saat pojalleni vaimon minun suvustani ja isäni perheestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Silloin, kun saavut sukuni luo, olet vapaa valasta, jonka minulle vannoit; jos he eivät häntä sinulle anna, olet valasta vapaa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Niin minä tänään tulin lähteelle ja sanoin: \'Herra, minun herrani Aabrahamin Jumala, jos annat onnistua sen matkan, jolla olen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'salli tapahtua niin, että se neitonen, joka minun seisoessani tässä vesilähteellä tulee ammentamaan vettä ja sanoessani hänelle: \'Anna minun juoda vähän vettä astiastasi\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'vastaa minulle: \'Juo itse, ja minä ammennan myös sinun kameleillesi\' -että hän on se vaimo, jonka Herra on määrännyt minun herrani pojalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Tuskin olin lakannut näin puhumasta itsekseni, niin katso, Rebekka tuli sinne, vesiastia olallansa, astui alas lähteelle ja ammensi. Ja minä sanoin hänelle: \'Anna minun juoda\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Hän laski nopeasti astian alas olaltansa ja sanoi: \'Juo, minä juotan myös sinun kamelisi\'. Niin minä join, ja hän juotti myös kamelit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Ja minä kysyin häneltä sanoen: \'Kenenkä tytär sinä olet?\' Hän vastasi: \'Olen Betuelin, Naahorin ja Milkan pojan, tytär\'. Niin minä panin nenärenkaan hänen nenäänsä ja rannerenkaat hänen käsiinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Ja minä kumarruin maahan ja rukoilin Herraa, kiittäen Herraa, minun herrani Aabrahamin Jumalaa, joka oli johdattanut minut oikeata tietä saamaan herrani veljen tyttären hänen pojalleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Ja jos nyt tahdotte osoittaa suosiota ja uskollisuutta minun herralleni, niin ilmoittakaa se minulle; jollette, niin ilmoittakaa minulle sekin, kääntyäkseni toisaalle, oikealle tai vasemmalle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Laaban ja Betuel vastasivat sanoen: \"Herralta tämä on tullut; emme voi tässä asiassa puhua sinulle hyvää emmekä pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Katso, siinä on Rebekka edessäsi, ota hänet ja mene. Tulkoon hän herrasi pojan vaimoksi, niinkuin Herra on sanonut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Kuultuaan heidän sanansa Aabrahamin palvelija kumartui maahan Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Sitten palvelija otti esille hopea-ja kultakaluja sekä vaatteita ja antoi ne Rebekalle. Myöskin hänen veljelleen ja äidilleen hän antoi kallisarvoisia lahjoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Ja he söivät ja joivat, hän ja hänen seuralaisensa, ja olivat siellä yötä. Mutta kun he olivat nousseet seuraavana aamuna, sanoi hän: \"Päästäkää minut menemään herrani luo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Tytön veli ja äiti vastasivat: \"Anna tytön viipyä luonamme vielä joku aika, edes kymmenen päivää. Sitten saat lähteä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Mutta hän sanoi heille: \"Älkää viivyttäkö minua, koska Herra on antanut matkani onnistua. Päästäkää minut menemään, tahdon lähteä herrani luo.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'He vastasivat: \"Kutsukaamme tänne tyttö ja kysykäämme häneltä itseltään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Ja he kutsuivat Rebekan ja sanoivat hänelle: \"Tahdotko lähteä tämän miehen kanssa?\" Hän vastasi: \"Tahdon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Niin he lähettivät sisarensa Rebekan imettäjineen matkalle Aabrahamin palvelijan ja hänen miestensä mukana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Ja he siunasivat Rebekan ja lausuivat hänelle: \"Oi sisaremme, tulkoon sinusta tuhat kertaa kymmenentuhatta, ja vallatkoot sinun jälkeläisesi vihamiestensä portit!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Ja Rebekka nousi palvelijattarineen, ja he istuivat kamelien selkään ja seurasivat miestä. Niin palvelija otti Rebekan mukaansa ja lähti matkalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Ja Iisak oli tulossa Lahai-Roin kaivon tienoilta; hän asui näet Etelämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Ja Iisak oli illan suussa lähtenyt kedolle käyskentelemään, ja kun hän nosti silmänsä, näki hän kamelien lähestyvän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Kun Rebekka nosti silmänsä ja näki Iisakin, laskeutui hän nopeasti maahan kamelin selästä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'ja kysyi palvelijalta: \"Kuka on tuo mies, joka tulee kedolla meitä vastaan?\" Palvelija vastasi: \"Hän on minun herrani\". Niin hän otti hunnun ja verhoutui siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Ja palvelija kertoi Iisakille kaikki, mitä hän oli toimittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Ja Iisak vei Rebekan äitinsä Saaran majaan ja otti hänet luokseen, ja hänestä tuli hänen vaimonsa, ja hän rakasti häntä. Niin Iisak sai lohdutuksen äitinsä kuoltua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Ja Aabraham otti vielä vaimon, ja hänen nimensä oli Ketura.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Ja hän synnytti hänelle Simranin ja Joksanin, Medanin ja Midianin, Jisbakin ja Suuahin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Mutta Joksanille syntyi Seba ja Dedan. Dedanin jälkeläisiä olivat: assurilaiset, letusilaiset ja leummilaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Ja Midianin pojat olivat Eefa, Eefer, Hanok, Abida ja Eldaa. Kaikki nämä ovat Keturan jälkeläisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Ja Aabraham antoi kaiken omaisuutensa Iisakille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Mutta sivuvaimojensa pojille Aabraham antoi lahjoja; ja hän lähetti heidät vielä eläessänsä pois poikansa Iisakin luota itään päin, Itäiselle maalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Tämä on Aabrahamin elinvuosien luku: sata seitsemänkymmentä viisi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Ja Aabraham vaipui kuolemaan korkeassa iässä, vanhana ja elämästä kyllänsä saaneena, ja tuli otetuksi heimonsa tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Ja hänen poikansa Iisak ja Ismael hautasivat hänet Makpelan luolaan, heettiläisen Efronin, Sooharin pojan, vainiolle, joka on itään päin Mamresta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'sille vainiolle, jonka Aabraham oli ostanut heettiläisiltä; siihen haudattiin Aabraham ja hänen vaimonsa Saara.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Ja Aabrahamin kuoltua Jumala siunasi hänen poikaansa Iisakia. Ja Iisak asui Lahai-Roin kaivon tienoilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Ja tämä on kertomus Ismaelin suvusta, Aabrahamin pojan, jonka Saaran egyptiläinen orjatar Haagar synnytti Aabrahamille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Nämä ovat Ismaelin poikien nimet heidän nimiensä ja polveutumisensa mukaan: Nebajot, Ismaelin esikoinen, Keedar, Adbeel, Mibsam,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Misma, Duuma, Massa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadad, Teema, Jetur, Naafis ja Keedma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Nämä ovat Ismaelin pojat ja nämä heidän nimensä heidän kyliensä ja leiripaikkojensa mukaan, kaksitoista ruhtinasta heimokuntineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Ja tämä on Ismaelin elinvuosien luku: sata kolmekymmentä seitsemän vuotta; ja hän vaipui kuolemaan ja tuli otetuksi heimonsa tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Ja he asuivat Havilasta aina Suuriin asti, joka on Egyptistä itään päin Assyriaan mentäessä. Hän kävi kaikkien veljiensä kimppuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Ja tämä on kertomus Iisakin, Aabrahamin pojan, suvusta. Aabrahamille syntyi Iisak.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Ja Iisak oli neljänkymmenen vuoden vanha, kun hän otti vaimokseen Rebekan, joka oli aramilaisen Betuelin tytär Mesopotamiasta ja aramilaisen Laabanin sisar.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Ja Iisak rukoili Herraa vaimonsa puolesta, sillä tämä oli hedelmätön. Ja Herra kuuli hänen rukouksensa, ja hänen vaimonsa Rebekka tuli raskaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Ja lapset sysäsivät toisiaan hänen kohdussansa. Niin hän sanoi: \"Jos näin käy, minkätähden minä elän?\" Ja hän meni kysymään Herralta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Ja Herra sanoi hänelle: \"Kaksi kansaa on sinun kohdussasi, kaksi heimoa erkanee sinun ruumiistasi, toinen heimo on toista voimakkaampi, vanhempi palvelee nuorempaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Kun hänen synnyttämisensä aika oli tullut, katso, hänen kohdussaan oli kaksoiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Joka ensiksi tuli hänen kohdustaan, oli ruskea ja yliyltään niinkuin karvainen vaippa; sentähden pantiin hänelle nimeksi Eesau.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Senjälkeen tuli ulos hänen veljensä, ja hän piti kädellään Eesaun kantapäästä. Ja hänelle pantiin nimeksi Jaakob. Iisak oli kuudenkymmenen vuoden vanha heidän syntyessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Ja pojat kasvoivat suuriksi, ja Eesausta tuli taitava metsästäjä, aron mies; Jaakob sitä vastoin oli hiljainen mies, joka pysyi kotosalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Iisak rakasti enemmän Eesauta, sillä hän söi mielellänsä metsänriistaa, mutta Rebekka rakasti enemmän Jaakobia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Kerran, kun Jaakob oli keittänyt itselleen keiton, tuli Eesau kedolta nälästä nääntyneenä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Ja Eesau sanoi Jaakobille: \"Anna minun särpiä tuota ruskeata, tuota ruskeata keittoa, sillä minä olen nälästä nääntynyt\". Sentähden hän sai nimen Edom.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Mutta Jaakob sanoi: \"Myy minulle ensin esikoisuutesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Eesau vastasi: \"Katso, minä kuolen kuitenkin, mitä minä esikoisuudellani teen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Jaakob sanoi: \"Vanno minulle ensin\". Ja hän vannoi hänelle ja myi esikoisuutensa Jaakobille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Ja Jaakob antoi Eesaulle leipää ja hernekeittoa. Ja hän söi ja joi, nousi ja meni matkoihinsa. Niin halpana Eesau piti esikoisuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Mutta maahan tuli nälänhätä, toinen kuin se nälänhätä, joka oli ollut aikaisemmin, Aabrahamin päivinä. Silloin Iisak meni Abimelekin, filistealaisten kuninkaan, luo Gerariin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Ja Herra ilmestyi hänelle ja sanoi: \"Älä mene Egyptiin, vaan jää asumaan maahan, jonka minä sinulle sanon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Oleskele muukalaisena tässä maassa, ja minä olen sinun kanssasi ja siunaan sinua. Sillä sinulle ja sinun jälkeläisillesi minä annan kaikki nämä maat ja pidän valan, jonka minä olen vannonut sinun isällesi Aabrahamille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Ja minä teen sinun jälkeläistesi luvun paljoksi kuin taivaan tähdet ja annan jälkeläisillesi kaikki nämä maat, ja sinun siemenessäsi tulevat siunatuiksi kaikki kansakunnat maan päällä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'sentähden että Aabraham kuuli minua ja noudatti, mitä minä noudatettavaksi annoin, minun käskyjäni, säädöksiäni ja opetuksiani.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Niin Iisak asettui Gerariin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Ja kun sen paikkakunnan miehet kysyivät hänen vaimostansa, sanoi hän: \"Hän on minun sisareni\". Hän näet pelkäsi sanoa: \"Hän on minun vaimoni\", sillä hän ajatteli: \"Nuo miehet voivat tappaa minut Rebekan tähden, sillä hän on näöltään kaunis\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Kun hän oli viipynyt siellä jonkun aikaa, niin tapahtui, että Abimelek, filistealaisten kuningas, kerran katsellessaan ulos akkunasta näki Iisakin hyväilevän vaimoansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Niin Abimelek kutsutti Iisakin ja sanoi: \"Katso, hänhän on sinun vaimosi! Miksi olet sanonut: \'Hän on minun sisareni\'?\" Iisak vastasi hänelle: \"Minä ajattelin, että minut muuten ehkä tapetaan hänen tähtensä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Abimelek sanoi: \"Mitä oletkaan meille tehnyt! Kuinka helposti olisikaan voinut tapahtua, että joku kansasta olisi maannut sinun vaimosi kanssa, ja niin sinä olisit saattanut meidät syyhyn!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Ja Abimelek antoi käskyn kaikelle kansalle, sanoen: \"Joka koskee tähän mieheen tai hänen vaimoonsa, se on kuolemalla rangaistava\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Ja Iisak kylvi siinä maassa ja sai sinä vuonna satakertaisesti, sillä Herra siunasi häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Ja hän rikastui ja hyötyi hyötymistään, kunnes hänestä tuli hyvin rikas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Ja hänellä oli laumoittain sekä pikkukarjaa että raavaskarjaa ja paljon palvelijoita, niin että filistealaiset alkoivat kadehtia häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Ja filistealaiset tukkivat kaikki ne kaivot, jotka hänen isänsä palvelijat olivat kaivaneet hänen isänsä Aabrahamin päivinä, ja täyttivät ne mullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Silloin Abimelek sanoi Iisakille: \"Mene pois luotamme, sillä sinä olet tullut paljon väkevämmäksi meitä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Niin Iisak lähti sieltä ja leiriytyi Gerarin laaksoon ja asui siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Ja Iisak kaivatti uudelleen auki ne vesikaivot, jotka hänen isänsä Aabrahamin päivinä olivat kaivetut, mutta jotka filistealaiset olivat Aabrahamin kuoltua tukkineet, ja antoi niille jälleen ne nimet, jotka hänen isänsä oli niille antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Ja Iisakin palvelijat kaivoivat laaksossa ja löysivät sieltä kaivon, jossa oli juoksevaa vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Mutta Gerarin paimenet alkoivat riidellä Iisakin paimenten kanssa, sanoen: \"Vesi on meidän\". Niin hän kutsui kaivon Eesekiksi, koska he olivat riidelleet hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Senjälkeen he kaivoivat toisen kaivon ja joutuivat riitaan siitäkin; niin hän antoi sille nimen Sitna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Sitten hän muutti sieltä pois ja kaivoi vielä yhden kaivon. Siitä ei syntynyt riitaa. Sentähden hän nimitti sen Rehobotiksi ja sanoi: \"Nyt Herra on antanut meille tilaa, niin että voimme lisääntyä maassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Sieltä hän meni Beersebaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Ja Herra ilmestyi hänelle sinä yönä ja sanoi: \"Minä olen sinun isäsi Aabrahamin Jumala; älä pelkää, sillä minä olen sinun kanssasi ja siunaan sinua ja teen sinun jälkeläistesi luvun suureksi palvelijani Aabrahamin tähden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Silloin hän rakensi sinne alttarin, huusi avuksi Herran nimeä ja pystytti sinne telttansa. Ja Iisakin palvelijat kaivoivat siihen kaivon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Niin Abimelek lähti hänen luokseen Gerarista ystävänsä Ahusatin ja sotapäällikkönsä Piikolin seuraamana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Mutta Iisak sanoi heille: \"Minkätähden tulette minun luokseni, vaikka olette minulle vihamieliset ja karkoititte minut luotanne?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'He vastasivat: \"Me olemme selvästi nähneet, että Herra on sinun kanssasi. Sentähden ajattelimme: \'Olkoon sinun ja meidän välillämme valallinen sopimus; me tahdomme tehdä sinun kanssasi liiton,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'ettet tee meille mitään pahaa, niinkuin emme mekään ole sinuun koskeneet, vaan olemme tehneet sinulle ainoastaan hyvää ja sallineet sinun lähteä rauhassa\'. Sinä olet nyt Herran siunattu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Silloin hän laittoi heille pidot, ja he söivät ja joivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Varhain seuraavana aamuna he vannoivat valan toisillensa; senjälkeen Iisak päästi heidät menemään, ja he lähtivät hänen luotaan rauhassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Samana päivänä Iisakin palvelijat tulivat ja kertoivat hänelle kaivosta, jonka olivat kaivaneet, sanoen hänelle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, '\"Me löysimme vettä\". Ja hän antoi sille nimen Siba. Sentähden on kaupungin nimi vielä tänäkin päivänä Beerseba.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Kun Eesau oli neljänkymmenen vuoden vanha, otti hän vaimoikseen Jehuditin, heettiläisen Beerin tyttären, ja Baasematin, heettiläisen Eelonin tyttären.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Näistä tuli Iisakille ja Rebekalle katkera suru.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Kun Iisak oli tullut vanhaksi ja hänen silmänsä olivat hämärtyneet, niin ettei hän enää voinut nähdä, kutsui hän Eesaun, vanhemman poikansa, ja sanoi hänelle: \"Poikani!\" Tämä vastasi hänelle: \"Tässä olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Niin hän sanoi: \"Katso, minä olen tullut vanhaksi enkä tiedä, milloin kuolen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Ota siis aseesi, viinesi ja jousesi, ja mene kedolle ja pyydystä minulle riistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Ja laita minulle herkkuruoka, minun mieliruokani, ja tuo se syödäkseni, että minä siunaisin sinut, ennenkuin kuolen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Mutta Rebekka kuuli, kuinka Iisak puhui pojallensa Eesaulle. Ja kun Eesau oli lähtenyt kedolle pyydystämään riistaa, tuodakseen isällensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'puhui Rebekka pojalleen Jaakobille sanoen: \"Katso, minä kuulin sinun isäsi puhuvan veljellesi Eesaulle ja sanovan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '\'Tuo minulle riistaa ja laita minulle herkkuruoka syödäkseni, että siunaisin sinut Herran edessä, ennenkuin kuolen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Kuule siis, poikani, mitä sanon, ja tee, mitä minä käsken:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'mene laumaan ja ota sieltä minulle kaksi hyvää vohlaa laittaakseni niistä isällesi herkkuruuan, hänen mieliruokansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Ja sinun on vietävä se isäsi syödä, että hän siunaisi sinut, ennenkuin kuolee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Mutta Jaakob sanoi äidillensä Rebekalle: \"Katso, veljeni Eesau on karvainen, mutta minä olen sileäihoinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Entä jos isäni tunnustelee minua? Silloin minä joudun hänen silmissään pilkkaajaksi ja hankin itselleni kirouksen enkä siunausta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Hänen äitinsä sanoi hänelle: \"Kohdatkoon se kirous minua, poikani; kuule vain, mitä minä sanon, mene ja nouda\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Niin hän meni noutamaan ne ja toi ne äidilleen; ja hänen äitinsä laittoi herkkuruuan, hänen isänsä mieliruuan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Ja Rebekka otti vanhemman poikansa Eesaun parhaat vaatteet, jotka olivat hänen hallussaan talossa, ja puki ne nuoremman poikansa Jaakobin ylle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Mutta vohlain nahat hän kääri hänen käsiinsä ja paljaaseen kaulaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Sitten hän antoi herkkuruuan ynnä leipomansa leivän poikansa Jaakobin käteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Ja Jaakob meni isänsä luo ja sanoi: \"Isäni!\" Hän vastasi: \"Tässä olen; kuka sinä olet, poikani?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jaakob sanoi isällensä: \"Minä olen Eesau, esikoisesi. Olen tehnyt, niinkuin käskit minun tehdä; nouse istumaan ja syö riistaani, siunataksesi minut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Mutta Iisak sanoi pojalleen: \"Kuinka olet, poikani, niin pian löytänyt?\" Hän vastasi: \"Herra, sinun Jumalasi, johdatti sen minun eteeni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Niin Iisak sanoi Jaakobille: \"Tulehan lähemmä, poikani, tunnustellakseni, oletko sinä poikani Eesau vai etkö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Ja Jaakob astui isänsä Iisakin luo, ja tämä tunnusteli häntä ja sanoi: \"Ääni on Jaakobin ääni, mutta kädet ovat Eesaun kädet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Eikä Iisak tuntenut häntä, sillä hänen kätensä olivat karvaiset, niinkuin hänen veljensä Eesaun kädet, ja hän siunasi hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Vielä hän kysyi: \"Oletko sinä todella minun poikani Eesau?\" Hän vastasi: \"Olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Silloin hän sanoi: \"Tuo ruoka minulle, syödäkseni poikani riistaa, että siunaisin sinut\". Niin hän toi hänelle sen, ja hän söi; ja hän tarjosi hänelle viiniä, ja hän joi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Senjälkeen hänen isänsä Iisak sanoi hänelle: \"Tule tänne ja suutele minua, poikani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Hän astui hänen luokseen ja suuteli häntä. Niin Iisak tunsi hänen vaatteidensa hajun ja siunasi hänet, sanoen: \"Katso, minun poikani tuoksu on kuin kedon tuoksu, jonka Herra on siunannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Jumala antakoon sinulle taivaan kastetta ja maan lihavuutta, jyviä ja viiniä yllin kyllin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Kansat palvelkoot sinua, kansakunnat sinua kumartakoot. Ole veljiesi herra, ja äitisi pojat kumartakoot sinua. Kirottu olkoon, joka sinua kiroaa, siunattu, joka sinua siunaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Kun Iisak oli ehtinyt siunata Jaakobin ja tämä juuri oli lähtenyt isänsä Iisakin luota, niin hänen veljensä Eesau tuli kotiin metsästämästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Ja hänkin laittoi herkkuruuan, vei sen isälleen ja sanoi isälleen: \"Nouse, isäni, ja syö poikasi riistaa, siunataksesi minut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Hänen isänsä Iisak kysyi häneltä: \"Kuka olet?\" Hän vastasi: \"Minä olen poikasi Eesau, sinun esikoisesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Silloin Iisak säikähtyi kovin ja sanoi: \"Kuka sitten oli se metsästäjä, joka toi minulle riistaa, niin että minä, ennenkuin sinä tulit, söin kaikkea ja siunasin hänet? Siunattu hän myös on oleva.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Kun Eesau kuuli isänsä sanat, puhkesi hän valittamaan äänekkäästi ja haikeasti ja sanoi isälleen: \"Siunaa minutkin, isäni!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Mutta hän vastasi: \"Veljesi tuli kavalasti ja riisti sinulta siunauksen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Niin hän sanoi: \"Oikeinpa häntä kutsutaankin Jaakobiksi. Sillä hän on nyt kahdesti minut pettänyt: esikoisuuteni hän on minulta vienyt, ja katso, nyt hän riisti minulta myöskin siunauksen.\" Ja hän kysyi: \"Eikö sinulla ole mitään siunausta minun varalleni?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Ja Iisak vastasi ja sanoi Eesaulle: \"Katso, minä olen asettanut hänet sinun herraksesi ja antanut kaikki hänen veljensä hänelle palvelijoiksi sekä varustanut hänet jyvillä ja viinillä; mitä voisin enää tehdä sinun hyväksesi, poikani?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Eesau sanoi isällensä: \"Tuo yksi ainoa siunausko sinulla vain onkin, isäni? Siunaa myöskin minut, isäni!\" Ja Eesau korotti äänensä ja itki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Niin hänen isänsä Iisak vastasi ja sanoi hänelle: \"Katso, sinun asuinsijasi on oleva kaukana lihavasta maasta ja vailla taivaan kastetta ylhäältä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Miekkasi varassa sinä olet elävä ja palveleva veljeäsi. Mutta valtoimena kierrellen sinä riisut hänen ikeensä niskaltasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Ja Eesau alkoi vihata Jaakobia siunauksen tähden, jolla hänen isänsä oli hänet siunannut; ja Eesau ajatteli itsekseen: \"Pian tulee aika, jolloin suremme isäämme; silloin minä tapan veljeni Jaakobin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Mutta Rebekalle ilmoitettiin hänen vanhemman poikansa Eesaun aikeista; ja hän kutsutti luokseen nuoremman poikansa Jaakobin ja sanoi hänelle: \"Katso, veljesi Eesau uhkaa kostaa sinulle ja tappaa sinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Kuule siis, mitä sanon, poikani: nouse ja pakene minun veljeni Laabanin luo Harraniin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'ja jää hänen luokseen joksikin aikaa, kunnes veljesi kiukku asettuu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'kunnes veljesi lakkaa sinua vihaamasta ja unhottaa, mitä olet hänelle tehnyt. Sitten minä lähetän noutamaan sinut sieltä. Minkätähden menettäisin teidät molemmat samana päivänä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Ja Rebekka sanoi Iisakille: \"Minä olen kyllästynyt elämääni Heetin tyttärien tähden. Jos Jaakobkin ottaa vaimon Heetin tyttäristä, tässä maassa syntyneen, sellaisen kuin nämä, niin mitä varten minä enää elän?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Silloin Iisak kutsui Jaakobin ja siunasi hänet; hän käski häntä ja sanoi hänelle: \"Älä ota vaimoksesi ketään Kanaanin tyttäristä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'vaan nouse ja mene Mesopotamiaan, isoisäsi Betuelin kotiin, ja ota sieltä itsellesi vaimo enosi Laabanin tyttäristä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Ja Jumala, Kaikkivaltias, siunatkoon sinua ja antakoon sinun tulla hedelmälliseksi ja lisääntyä, niin että sinusta tulee suuri kansojen joukko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Ja hän suokoon sinulle Aabrahamin siunauksen, sinulle ynnä sinun jälkeläisillesi, että saisit omaksesi maan, jossa sinä muukalaisena asut ja jonka Jumala on antanut Aabrahamille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Niin Iisak lähetti Jaakobin matkalle, ja hän lähti Mesopotamiaan Laabanin luo, joka oli aramilaisen Betuelin poika ja Rebekan, Jaakobin ja Eesaun äidin, veli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Kun Eesau näki, että Iisak oli siunannut Jaakobin ja lähettänyt hänet Mesopotamiaan ottamaan sieltä itselleen vaimoa-sillä hän oli siunannut hänet, käskenyt häntä ja sanonut: \"Älä ota vaimoa Kanaanin tyttäristä\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'ja että Jaakob oli totellut isäänsä ja äitiänsä ja lähtenyt Mesopotamiaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'silloin hän huomasi, että Kanaanin tyttäret olivat hänen isälleen Iisakille vastenmieliset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'ja niin Eesau meni Ismaelin luo ja otti Mahalatin, Aabrahamin pojan Ismaelin tyttären, Nebajotin sisaren, vaimokseen entisten lisäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Niin Jaakob lähti Beersebasta mennäksensä Harraniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Ja hän osui erääseen paikkaan, johon yöpyi, sillä aurinko oli laskenut; ja hän otti sen paikan kivistä yhden, pani sen päänsä alaiseksi ja asettui nukkumaan siihen paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Niin hän näki unta, ja katso, maan päälle oli asetettu tikapuut, joiden pää ulottui taivaaseen, ja katso, Jumalan enkelit kulkivat niitä myöten ylös ja alas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Ja katso, Herra seisoi hänen edessään ja sanoi: \"Minä olen Herra, sinun Isäsi Aabrahamin Jumala ja Iisakin Jumala. Tämän maan, jonka päällä sinä makaat, minä annan sinulle ja sinun jälkeläisillesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Ja sinun jälkeläistesi paljous on oleva kuin maan tomu, ja sinä leviät länteen ja itään, pohjoiseen ja etelään, ja sinussa ja sinun siemenessäsi tulevat siunatuiksi kaikki sukukunnat maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Ja katso, minä olen sinun kanssasi ja varjelen sinua, missä ikinä kuljet, ja saatan sinut takaisin tähän maahan; sillä minä en jätä sinua, ennenkuin olen toteuttanut sen, minkä minä olen sinulle puhunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Silloin Jaakob heräsi unestansa ja sanoi: \"Herra on totisesti tässä paikassa, enkä minä sitä tiennyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Ja pelko valtasi hänet, ja hän sanoi: \"Kuinka peljättävä onkaan tämä paikka! Tässä on varmasti Jumalan huone ja taivaan portti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Ja Jaakob nousi varhain aamulla, otti kiven, jonka hän oli pannut päänsä alaiseksi, ja nosti sen pystyyn patsaaksi ja vuodatti öljyä sen päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Ja hän kutsui paikan Beeteliksi; mutta ennen oli kaupungin nimenä Luus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Ja Jaakob teki lupauksen, sanoen: \"Jos Jumala on minun kanssani ja varjelee minut sillä tiellä, jota nyt kuljen, ja antaa minulle leipää syödäkseni ja vaatteita pukeutuakseni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'niin että saan palata rauhassa isäni kotiin, niin on Herra oleva minun Jumalani;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'ja tämä kivi, jonka olen patsaaksi pystyttänyt, on oleva Jumalan huone, ja kaikesta, mitä minulle suot, minä totisesti annan sinulle kymmenykset\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Ja Jaakob lähti matkaan ja tuli Idän miesten maalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Ja katso, hän huomasi kedolla kaivon, ja katso, sen ääressä makasi kolme lammaslaumaa, sillä siitä kaivosta oli tapana juottaa laumoja. Ja kaivon suulla oli suuri kivi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Sentähden annettiin kaikkien laumojen kokoontua sinne ja sitten vieritettiin kivi kaivon suulta ja juotettiin lampaat, jonka jälkeen kivi taas pantiin paikoilleen kaivon suulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Ja Jaakob sanoi heille: \"Veljeni, mistä te olette?\" He vastasivat: \"Harranista olemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Hän kysyi heiltä: \"Tunnetteko Laabanin, Naahorin pojan?\" He vastasivat: \"Tunnemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Ja hän kysyi heiltä: \"Voiko hän hyvin?\" He vastasivat: \"Hyvin hän voi; ja katso, Raakel, hänen tyttärensä, tulee tuolla lammasten kanssa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Hän sanoi: \"Vielä on täysi päivä ja liian aikaista koota lauma; juottakaa lampaat ja viekää ne takaisin laitumelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'He vastasivat: \"Emme voi, ennenkuin kaikki laumat ovat koolla ja kivi on vieritetty kaivon suulta; sitten juotamme lampaat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Hänen vielä puhuessaan heidän kanssaan tuli Raakel isänsä lammasten kanssa, sillä hänen oli tapana olla paimenessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Kun Jaakob näki Raakelin, enonsa Laabanin tyttären, ja enonsa Laabanin lampaat, astui hän esiin ja vieritti kiven kaivon suulta ja juotti enonsa Laabanin lampaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Ja Jaakob suuteli Raakelia ja korotti äänensä ja itki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Niin Jaakob ilmoitti Raakelille, että hän oli hänen isänsä sukulainen ja Rebekan poika; ja Raakel riensi pois ja ilmoitti sen isällensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Kun Laaban kuuli kerrottavan Jaakobista, sisarensa pojasta, riensi hän häntä vastaan, syleili ja suuteli häntä ja toi hänet kotiinsa; ja hän kertoi Laabanille kaikki, mitä oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Ja Laaban sanoi hänelle: \"Niin, sinä olet minun luutani ja lihaani\". Ja hän asui hänen luonaan kuukauden päivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Ja Laaban sanoi Jaakobille: \"Olet tosin sukulaiseni, mutta palvelisitko silti minua palkatta? Sano minulle, mikä on palkkasi oleva.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Mutta Laabanilla oli kaksi tytärtä; vanhemman nimi oli Leea, nuoremman nimi oli Raakel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Ja Leealla oli sameat silmät, mutta Raakelilla oli kaunis vartalo ja kauniit kasvot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Ja Jaakob rakasti Raakelia; niin hän sanoi: \"Minä palvelen sinua seitsemän vuotta saadakseni Raakelin, nuoremman tyttäresi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Laaban vastasi: \"Parempi on, että annan hänet sinulle, kuin että antaisin hänet jollekin toiselle; jää luokseni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Jaakob palveli siis seitsemän vuotta saadakseen Raakelin, ja ne tuntuivat hänestä muutamilta päiviltä; niin hän rakasti häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Senjälkeen Jaakob sanoi Laabanille: \"Anna minulle vaimoni, sillä aikani on nyt kulunut umpeen, mennäkseni hänen tykönsä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Silloin Laaban kutsui kokoon kaikki sen paikkakunnan asukkaat ja laittoi pidot;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'mutta illalla hän otti tyttärensä Leean ja vei hänet hänen luokseen; ja hän yhtyi häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Ja Laaban antoi orjattarensa Silpan tyttärellensä Leealle orjattareksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Aamulla hän näki, että se oli Leea. Ja hän sanoi Laabanille: \"Mitä oletkaan minulle tehnyt? Olenhan palvellut sinua saadakseni Raakelin! Miksi petit minut?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Laaban vastasi: \"Ei ole meidän maassamme tapana antaa nuorempaa ennen vanhempaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Vietä nyt vain tämä hääviikko loppuun, niin annetaan sinulle toinenkin, kunhan olet palveluksessani vielä toiset seitsemän vuotta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Ja Jaakob suostui siihen, ja kun hän oli viettänyt sen viikon loppuun, antoi Laaban myöskin tyttärensä Raakelin hänelle vaimoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Ja Laaban antoi orjattarensa Bilhan tyttärellensä Raakelille orjattareksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Ja hän yhtyi myös Raakeliin, ja Raakel oli hänelle rakkaampi kuin Leea; ja hän palveli Laabanin luona vielä toiset seitsemän vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Ja kun Herra näki, että Leeaa hyljittiin, avasi hän hänen kohtunsa; mutta Raakel oli hedelmätön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Niin Leea tuli raskaaksi ja synnytti pojan ja antoi hänelle nimen Ruuben, sanoen: \"Herra on nähnyt minun kurjuuteni; nyt on mieheni rakastava minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Ja hän tuli jälleen raskaaksi ja synnytti pojan ja sanoi: \"Herra on kuullut, että minua hyljitään, ja on antanut minulle myös tämän\". Niin hän antoi hänelle nimen Simeon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Ja hän tuli jälleen raskaaksi ja synnytti pojan ja sanoi: \"Nyt kai mieheni vihdoinkin kiintyy minuun, sillä olenhan synnyttänyt hänelle kolme poikaa\". Sentähden hän antoi hänelle nimen Leevi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Ja hän tuli vieläkin raskaaksi ja synnytti pojan ja sanoi: \"Nyt minä kiitän Herraa\". Sentähden hän antoi hänelle nimen Juuda. Sitten hän lakkasi synnyttämästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Kun Raakel näki, ettei hän synnyttänyt Jaakobille, kadehti hän sisartaan ja sanoi Jaakobille: \"Hanki minulle lapsia, muuten minä kuolen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Niin Jaakob vihastui Raakeliin ja sanoi: \"Minäkö olen Jumala, joka on kieltänyt sinulta kohdun hedelmän?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Mutta Raakel sanoi: \"Tässä on orjattareni Bilha; yhdy häneen, että hän synnyttäisi minun helmaani ja minäkin siten saisin lapsia hänestä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Ja hän antoi hänelle orjattarensa Bilhan vaimoksi ja Jaakob yhtyi häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Ja Bilha tuli raskaaksi ja synnytti Jaakobille pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Niin Raakel sanoi: \"Jumala hankki minulle oikeuden, ja hän kuuli minun ääneni ja antoi minulle pojan\". Sentähden hän antoi hänelle nimen Daan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Ja Bilha, Raakelin orjatar, tuli jälleen raskaaksi ja synnytti Jaakobille toisen pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Niin Raakel sanoi: \"Jumalan taisteluja minä olen taistellut sisareni kanssa ja olen voittanut\". Ja hän antoi hänelle nimen Naftali.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Kun Leea näki lakanneensa synnyttämästä, otti hän orjattarensa Silpan ja antoi hänet Jaakobille vaimoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Ja Silpa, Leean orjatar, synnytti Jaakobille pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Niin Leea sanoi: \"Onneksi!\" Ja hän antoi hänelle nimen Gaad.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Ja Silpa, Leean orjatar, synnytti Jaakobille toisen pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Niin Leea sanoi: \"Onnellista minua! Niin, naiset ylistävät minua onnelliseksi.\" Ja hän antoi hänelle nimen Asser.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Mutta Ruuben meni kerran ulos nisunleikkuun aikana ja löysi lemmenmarjoja vainiolta ja toi ne äidillensä Leealle. Niin Raakel sanoi Leealle: \"Anna minulle poikasi lemmenmarjoja\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Leea vastasi hänelle: \"Eikö riitä, että olet vienyt minulta mieheni, koska tahdot ottaa vielä poikani lemmenmarjatkin?\" Raakel sanoi: \"Olkoon, maatkoon hän tämän yön sinun kanssasi, kunhan saan poikasi lemmenmarjat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Kun Jaakob illalla palasi vainiolta, meni Leea häntä vastaan ja sanoi: \"Minun luokseni sinun on tultava, sillä minä olen ostanut sinut poikani lemmenmarjoilla\". Ja hän makasi sen yön hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Ja Jumala kuuli Leeaa, ja Leea tuli raskaaksi ja synnytti Jaakobille viidennen pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Niin Leea sanoi: \"Jumala on palkinnut minulle sen, että annoin orjattareni miehelleni\". Ja hän antoi hänelle nimen Isaskar.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Ja Leea tuli jälleen raskaaksi ja synnytti Jaakobille kuudennen pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Silloin Leea sanoi: \"Jumala on antanut minulle hyvän lahjan. Nyt mieheni on asuva minun luonani, sillä minä olen synnyttänyt hänelle kuusi poikaa.\" Ja hän antoi hänelle nimen Sebulon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Sitten hän synnytti tyttären ja antoi hänelle nimen Diina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Mutta Jumala muisti Raakeliakin, ja Jumala kuuli häntä ja avasi hänen kohtunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Niin hän tuli raskaaksi ja synnytti pojan ja sanoi: \"Jumala on ottanut pois minun häpeäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Ja hän antoi hänelle nimen Joosef, sanoen: \"Herra antakoon minulle vielä toisen pojan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Ja kun Raakel oli synnyttänyt Joosefin, sanoi Jaakob Laabanille: \"Päästä minut menemään kotiini ja omaan maahani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Anna minulle vaimoni ja lapseni, joiden vuoksi olen sinua palvellut, mennäkseni pois; sillä tiedäthän itse, kuinka olen sinua palvellut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Laaban vastasi hänelle: \"Jospa saisin armon silmiesi edessä! Merkkini ilmoittavat, että Herra sinun tähtesi on siunannut minua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Ja hän sanoi vielä: \"Määrää palkka, joka minun on sinulle maksettava, niin minä sen annan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Hän vastasi hänelle: \"Itsehän tiedät, kuinka minä olen sinua palvellut ja millaiseksi karjasi on tullut minun hoidossani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Sillä vähän sinulla oli ennen minun tuloani, mutta sitten se on karttunut suureksi, ja Herra on siunannut sinua, missä vain minä liikuin. Mutta milloin saan ruveta tekemään työtä minäkin oman perheeni hyväksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Hän vastasi: \"Mitä minun on sinulle annettava?\" Jaakob sanoi: \"Ei sinun tarvitse antaa minulle mitään. Jos myönnät minulle tämän, niin minä yhä edelleen paimennan ja vartioitsen sinun laumojasi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'minä tarkastan tänään kaiken laumasi; erota siitä pois kaikki pilkulliset ja kirjavat lampaat sekä karitsoista kaikki mustat ja vuohista kirjavat ja pilkulliset. Ja minun palkkani on sitten oleva tämä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'ja siinä minun rehellisyyteni tulee toteennäytetyksi: kun vasta tulet omin silmin katsomaan minun palkkaani, niin kaikki vuohet, jotka eivät ole pilkullisia eivätkä kirjavia, ja kaikki karitsat, jotka eivät ole mustia, katsottakoon minun varastamikseni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Laaban vastasi: \"Hyvä, olkoon, niinkuin olet puhunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Ja samana päivänä hän erotti pois juovikkaat ja kirjavat vuohipukit ja kaikki pilkulliset ja kirjavat vuohet-kaikki, joissa oli jotakin valkoista-sekä kaikki mustat karitsat ja jätti ne poikiensa hoitoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Ja hän asetti niin, että oli kolmen päivän välimatka hänen ja Jaakobin välillä; ja Jaakob paimensi Laabanin muuta karjaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Mutta Jaakob otti itselleen tuoreita haavan, mantelipuun ja plataanin oksia ja kuori niihin valkeita juovia, paljastaen oksien valkoisen rungon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Ja kuorimansa oksat hän pani eläinten eteen vesikaukaloihin eli juoma-astioihin, joista ne tulivat juomaan; ja ne olivat kiimallaan tullessansa juomaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Ja eläimet pariutuivat oksien edessä ja synnyttivät juovikkaita, pilkullisia ja kirjavia karitsoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Sitten Jaakob erotti karitsat; ja hän asetti eläinten päät niihin päin, jotka olivat pilkullisia, ja kaikkiin niihin päin, jotka olivat mustia Laabanin laumassa; siten hän hankki itselleen eri laumansa eikä päästänyt niitä Laabanin laumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Ja joka kerta kun voimakkaat eläimet olivat kiimallaan, pani Jaakob oksat eläinten silmien eteen vesikaukaloihin, niin että ne pariutuivat oksien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Mutta heikkojen eläinten eteen hän ei niitä pannut. Niin joutuivat heikot Laabanille ja voimakkaat Jaakobille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Ja siten mies tuli ylen rikkaaksi; hän sai paljon pikkukarjaa sekä palvelijattaria, palvelijoita, kameleja ja aaseja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Mutta hän sai kuulla, että Laabanin pojat puhuivat näin: \"Jaakob on anastanut kaikki, mitä isämme omisti; isämme omaisuudesta hän on hankkinut itselleen kaiken tämän rikkauden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Ja Jaakob huomasi Laabanin kasvoista, ettei hän ollut häntä kohtaan niinkuin ennen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Ja Herra sanoi Jaakobille: \"Palaja isiesi maahan ja sukusi tykö. Minä olen sinun kanssasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Niin Jaakob kutsutti Raakelin ja Leean kedolle laumansa luo,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'ja hän sanoi heille: \"Minä huomaan isänne kasvoista, ettei hän ole minua kohtaan niinkuin ennen, vaikka isäni Jumala on ollut minun kanssani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Te tiedätte, että minä olen palvellut isäänne kaikin voimin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'mutta isänne on kohdellut minua petollisesti ja muuttanut palkkaani kymmenen kertaa. Jumala ei kuitenkaan ole sallinut hänen tehdä minulle mitään vahinkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Kun hän sanoi: \'Pilkulliset olkoot sinun palkkasi\', niin koko lauma kantoi pilkullisia; ja kun hän sanoi: \'Juovikkaat olkoot sinun palkkasi\', niin koko lauma kantoi juovikkaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Niin on Jumala ottanut isänne omaisuuden ja antanut minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Mutta lauman pariutumisen aikana minä nostin silmäni ja näin unessa, että vuohipukit, jotka astuivat laumaa, olivat juovikkaita, pilkullisia ja kirjavia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Ja Jumalan enkeli sanoi minulle unessa: \'Jaakob!\' Minä vastasin: \'Tässä olen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Niin hän sanoi: \'Nosta silmäsi ja katso, kaikki vuohipukit, jotka astuvat laumaa, ovat juovikkaita, pilkullisia ja kirjavia, sillä minä olen nähnyt kaiken, mitä Laaban sinulle tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Minä olen Jumala, joka ilmestyin Beetelissä, jossa sinä voitelit patsaan ja jossa teit minulle lupauksen. Nouse nyt ja lähde tästä maasta ja palaja synnyinmaahasi.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Silloin Raakel ja Leea vastasivat ja sanoivat hänelle: \"Ei meillä ole enää osaa eikä perintöä isämme talossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Eikö hän pitänyt meitä kuin vieraita, koska myi meidät ja söi suuhunsa meistä saamansa hinnan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Niin, koko se rikkaus, jonka Jumala on ottanut isältämme, meidän se on ja meidän lastemme. Tee siis nyt kaikki, mitä Jumala on sinulle sanonut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Silloin Jaakob nousi ja nosti lapsensa ja vaimonsa kamelien selkään');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'ja kuljetti pois kaiken karjansa ja kaiken omaisuutensa, jonka hän oli koonnut, kaiken omistamansa ja Mesopotamiassa hankkimansa karjan, mennäkseen isänsä Iisakin luo Kanaanin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Mutta Laaban oli mennyt keritsemään lampaitaan. Silloin Raakel varasti isänsä kotijumalat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Ja Jaakob lähti varkain aramilaisen Laabanin luota eikä ilmaissut hänelle pakenemisaiettaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Niin hän pakeni kaikkinensa, lähti ja meni virran yli ja suuntasi kulkunsa Gileadin vuorille päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Mutta kolmantena päivänä Laabanille ilmoitettiin, että Jaakob oli paennut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Silloin hän otti mukaansa heimonsa miehet ja ajoi häntä takaa seitsemän päivänmatkaa ja saavutti hänet Gileadin vuorilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Mutta Jumala tuli aramilaisen Laabanin luo unessa yöllä ja sanoi hänelle: \"Varo, ettet puhu Jaakobille hyvää etkä pahaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Ja Laaban saavutti Jaakobin. Jaakob oli pystyttänyt telttansa vuorelle, Laaban taas pystytti telttansa Gileadin vuorelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Ja Laaban sanoi Jaakobille: \"Mitä oletkaan tehnyt? Sinä olet pettänyt minut ja kuljettanut pois minun tyttäreni niinkuin miekalla otetut!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Minkätähden pakenit salaa, läksit luotani varkain? Et ilmoittanut minulle mitään, ja niin minä en saanut saattaa sinua matkalle iloiten ja laulaen, vaskirummuin ja kantelein,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'etkä suonut minun suudella lasteni lapsia ja tyttäriäni. Tyhmästi sinä olet menetellyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Minulla olisi valta tehdä teille pahaa, mutta teidän isänne Jumala sanoi minulle viime yönä näin: \'Varo, ettet puhu Jaakobille hyvää etkä pahaa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Olkoon: sinä olet nyt lähtenyt matkallesi, koska niin suuresti ikävöit isäsi kotiin, mutta minkätähden olet varastanut minun jumalani?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Jaakob vastasi ja sanoi Laabanille: \"Minä pelkäsin, sillä ajattelin, että sinä riistäisit minulta tyttäresi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Mutta se, jonka hallusta löydät jumalasi, menettäköön henkensä. Heimojemme miesten läsnäollessa tutki, mitä minulla on, ja ota pois, mikä on omaasi.\" Sillä Jaakob ei tiennyt, että Raakel oli ne varastanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Ja Laaban meni Jaakobin telttaan, Leean telttaan ja molempien orjatarten telttaan, mutta ei löytänyt mitään. Ja tultuaan ulos Leean teltasta hän meni Raakelin telttaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Mutta Raakel oli ottanut kotijumalat, pannut ne kamelin satulaan ja istunut niiden päälle. Ja Laaban penkoi koko teltan, mutta ei löytänyt mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Ja hän sanoi isällensä: \"Älä vihastu, herrani, siitä etten voi nousta sinun edessäsi, sillä minun on, niinkuin naisten tavallisesti on\". Ja Laaban etsi, mutta ei löytänyt kotijumalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Silloin Jaakob vihastui ja soimasi Laabania; Jaakob puhkesi puhumaan ja sanoi Laabanille: \"Mitä minä olen rikkonut, mitä pahaa minä olen tehnyt, että näin minua ahdistat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Nyt olet penkonut kaikki minun tavarani; mitä olet löytänyt sellaista, joka olisi sinun talosi tavaraa? Tuo se tähän minun heimoni ja sinun heimosi miesten eteen, että he ratkaisisivat meidän molempien välin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Jo kaksikymmentä vuotta minä olen ollut sinun luonasi; sinun uuhesi ja vuohesi eivät ole synnyttäneet keskoisia, enkä minä ole oinaita sinun laumastasi syönyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Pedon haaskaamaa en ole sinulle tuonut, se oli minun itseni korvattava; minulta sinä sen vaadit, olipa se viety päivällä tai viety yöllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Päivällä vaivasi minua helle, yöllä vilu, ja uni pakeni silmistäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Jo kaksikymmentä vuotta minä olen ollut sinun talossasi; neljätoista vuotta minä palvelin sinua saadakseni molemmat tyttäresi ja kuusi vuotta saadakseni sinulta karjaa, mutta kymmenen kertaa sinä muutit minun palkkani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Jos minun isäni Jumala, Aabrahamin Jumala, jota myöskin Iisak pelkää, ei olisi ollut minun puolellani, niin sinä olisit nyt lähettänyt minut tyhjänä tieheni. Jumala on nähnyt minun kurjuuteni ja kätteni vaivannäön, ja hän ratkaisi viime yönä asian.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Niin Laaban vastasi ja sanoi Jaakobille: \"Tyttäret ovat minun tyttäriäni, ja lapset ovat minun lapsiani, ja karja on minun karjaani, ja kaikki, mitä näet, on minun omaani. Mutta minkä minä nyt mahdan näille tyttärilleni tai lapsille, jotka he ovat synnyttäneet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Tule siis, tehkäämme liitto keskenämme, ja olkoon se todistuksena meidän välillämme, minun ja sinun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Silloin Jaakob otti kiven ja nosti sen pystyyn patsaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Ja Jaakob sanoi heimonsa miehille: \"Kootkaa kiviä\". Ja he ottivat kiviä ja rakensivat roukkion ja aterioivat siinä sen kiviroukkion päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Ja Laaban antoi sille nimen Jegar-Saahaduta, mutta Jaakob antoi sille nimen Galed.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Ja Laaban sanoi: \"Tämä roukkio olkoon tänään todistajana meidän välillämme, minun ja sinun\"; sentähden hän antoi sille nimen Galed');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'ja myöskin nimen Mispa, sillä hän sanoi: \"Herra olkoon vartija meidän välillämme, minun ja sinun, kun joudumme loitolle toistemme näkyvistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Jos sinä kohtelet pahasti minun tyttäriäni tahi otat toisia vaimoja tyttärieni lisäksi, niin tiedä, että vaikkei ketään ihmistä olekaan läsnä, Jumala kuitenkin on todistajana meidän välillämme, minun ja sinun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Ja Laaban sanoi vielä Jaakobille: \"Katso, tämä roukkio ja tämä patsas, jonka minä olen pystyttänyt meidän välillemme, minun ja sinun');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, '-tämä roukkio olkoon todistuksena, ja myöskin tämä patsas olkoon todistuksena siitä, etten minä kulje tämän roukkion ohi sinun luoksesi ja ettet sinäkään kulje tämän roukkion ja tämän patsaan ohi minun luokseni paha mielessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Aabrahamin Jumala ja Naahorin Jumala, heidän isiensä Jumala, olkoon tuomarina meidän välillämme.\" Ja Jaakob vannoi valansa Jumalan kautta, jota hänen isänsä Iisak pelkäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Ja Jaakob uhrasi vuorella teurasuhrin ja kutsui heimonsa miehet aterioimaan, ja he aterioivat ja olivat yötä vuorella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Mutta varhain seuraavana aamuna Laaban nousi, suuteli lastensa lapsia ja tyttäriään ja hyvästeli heidät; sitten hän lähti matkaan ja palasi kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Mutta Jaakob kulki tietänsä; ja Jumalan enkeleitä tuli häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Ja nähdessään heidät Jaakob sanoi: \"Tämä on Jumalan sotajoukkoa\". Ja hän antoi sille paikalle nimen Mahanaim.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Sitten Jaakob lähetti sanansaattajat edellään veljensä Eesaun luo Seirin maahan, Edomin alueelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Ja hän käski heitä sanoen: \"Sanokaa herralleni Eesaulle näin: \'Sinun palvelijasi Jaakob sanoo: Minä olen oleskellut Laabanin luona ja viipynyt siellä tähän saakka;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'ja minä olen saanut raavaita, aaseja, pikkukarjaa, palvelijoita ja palvelijattaria ja lähetän nyt sanan herralleni, että saisin armon sinun silmiesi edessä\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Sanansaattajat palasivat Jaakobin luo ja sanoivat: \"Me tulimme veljesi Eesaun luo; hän on jo matkalla sinua vastaan, neljäsataa miestä mukanaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Silloin valtasi Jaakobin suuri pelko ja ahdistus. Ja hän jakoi väen, joka oli hänen kanssansa, ja pikkukarjan ja raavaskarjan ja kamelit kahteen joukkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Sillä hän ajatteli: \"Jos Eesau hyökkää toisen joukon kimppuun ja tuhoaa sen, niin toinen joukko pääsee pakoon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Ja Jaakob sanoi: \"Isäni Aabrahamin Jumala ja isäni Iisakin Jumala, Herra, sinä, joka sanoit minulle: \'Palaja maahasi ja sukusi luo, niin minä teen sinulle hyvää!\' 32:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Minä olen liian halpa kaikkeen siihen armoon ja kaikkeen siihen uskollisuuteen, jota sinä olet palvelijallesi osoittanut; sillä ainoastaan sauva kädessäni minä kuljin tämän Jordanin yli, ja nyt on minulle karttunut kaksi joukkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Pelasta minut veljeni Eesaun käsistä, sillä minä pelkään, että hän tulee ja tuhoaa minut ynnä äidit lapsineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Olethan itse sanonut: \'Minä teen sinulle hyvää ja annan sinun jälkeläistesi luvun tulla paljoksi kuin meren hiekka, jota ei voida lukea sen paljouden tähden\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Ja hän jäi siihen siksi yöksi. Sitten hän erotti omaisuudestaan lahjaksi veljelleen Eesaulle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'kaksisataa vuohta ja kaksikymmentä vuohipukkia, kaksisataa uuhta ja kaksikymmentä oinasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'kolmekymmentä imettävää kamelia varsoinensa, neljäkymmentä lehmää ja kymmenen härkää, kaksikymmentä aasintammaa ja kymmenen aasia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Ja hän jätti ne palvelijainsa haltuun, kunkin lauman erikseen, ja sanoi palvelijoilleen: \"Menkää minun edelläni ja jättäkää välimatka kunkin lauman välille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Ja hän käski ensimmäistä sanoen: \"Kun veljeni Eesau kohtaa sinut ja kysyy: \'Kenen sinä olet, ja mihin menet, ja kenen ovat nuo elukat tuolla edelläsi?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'niin vastaa: \'Ne ovat palvelijasi Jaakobin, lähetetyt lahjaksi herralleni Eesaulle; ja katso, myös hän itse tulee jäljessämme\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Samoin hän käski toista ja kolmatta ja kaikkia muita, jotka laumoja ajoivat, sanoen: \"Juuri näin on teidän sanottava Eesaulle, kun tapaatte hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Ja sanokaa myös: \'Katso, sinun palvelijasi Jaakob tulee meidän jäljessämme\'.\" Sillä hän ajatteli: \"Minä koetan lepyttää häntä lahjalla, joka kulkee edelläni. Sitten astun itse hänen kasvojensa eteen; ehkä hän ottaa minut ystävällisesti vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Niin lahja kulki hänen edellänsä, mutta itse hän jäi siksi yöksi leiriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Mutta yöllä hän nousi, otti molemmat vaimonsa ja molemmat orjattarensa ja yksitoista lastansa ja meni kahlauspaikasta Jabbokin yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Ja hän otti heidät ja vei heidät joen yli ja vei sen yli kaiken, mitä hänellä oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Ja Jaakob jäi yksinänsä toiselle puolelle. Silloin painiskeli hänen kanssaan muuan mies päivän koittoon saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Ja kun mies huomasi, ettei hän häntä voittanut, iski hän häntä lonkkaluuhun, niin että Jaakobin lonkka nyrjähti hänen painiskellessaan hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Ja mies sanoi: \"Päästä minut, sillä päivä koittaa\". Mutta hän vastasi: \"En päästä sinua, ellet siunaa minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Ja hän sanoi hänelle: \"Mikä sinun nimesi on?\" Hän vastasi: \"Jaakob\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Silloin hän sanoi: \"Sinun nimesi älköön enää olko Jaakob, vaan Israel, sillä sinä olet taistellut Jumalan ja ihmisten kanssa ja olet voittanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Ja Jaakob kysyi ja sanoi: \"Ilmoita nimesi\". Hän vastasi: \"Miksi kysyt minun nimeäni?\" Ja hän siunasi hänet siinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Ja Jaakob antoi sille paikalle nimen Penuel, \"sillä\", sanoi hän, \"minä olen nähnyt Jumalan kasvoista kasvoihin, ja kuitenkin on minun henkeni pelastunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Ja kun hän oli kulkenut Penuelin ohitse, nousi aurinko; mutta hän ontui lonkkaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Sentähden israelilaiset eivät vielä tänäkään päivänä syö reisijännettä, joka kulkee lonkkaluun yli; sillä hän iski Jaakobia lonkkaluuhun, reisijänteen kohdalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Kun Jaakob nosti silmänsä ja katseli, niin katso, Eesau oli tulossa, neljäsataa miestä mukanaan. Silloin hän jakoi lapset Leealle, Raakelille ja molemmille orjattarille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Ja hän asetti orjattaret lapsineen ensimmäisiksi, niiden jälkeen Leean lapsineen ja Raakelin Joosefin kanssa viimeiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Mutta itse hän astui heidän edellänsä ja kumartui maahan seitsemän kertaa, kunnes oli saapunut veljensä eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Mutta Eesau riensi häntä vastaan ja sulki hänet syliinsä, halasi häntä kaulasta ja suuteli häntä; ja he itkivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Ja hän nosti silmänsä ja näki vaimot ja lapset ja kysyi: \"Keitä ovat nämä, jotka ovat sinun seurassasi?\" Hän vastasi: \"Ne ovat minun lapseni, jotka Jumala on palvelijallesi lahjoittanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Niin orjattaret lähestyivät lapsineen ja kumartuivat maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Myöskin Leea lapsineen lähestyi, ja he kumartuivat maahan. Viimein lähestyivät Joosef ja Raakel ja kumartuivat maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Sitten hän kysyi: \"Mitä tarkoitit kaikella sillä joukolla, jonka minä kohtasin?\" Hän vastasi: \"Saada armon herrani silmien edessä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Mutta Eesau sanoi: \"Minulla on itselläni kyllin; pidä, veljeni, omasi!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Jaakob vastasi: \"Ei niin; jos olen saanut armon sinun silmiesi edessä, niin ota minulta vastaan lahjani; sillä olenhan saanut nähdä sinun kasvosi, niinkuin nähdään Jumalan kasvot, ja sinä olet ottanut minut suosiollisesti vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Ota siis tervehdyslahjani, joka sinulle tuotiin, sillä Jumala on ollut minulle armollinen, ja minulla on yllin kyllin kaikkea.\" Ja hän pyysi häntä pyytämällä, kunnes hän otti sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Sitten Eesau sanoi: \"Lähtekäämme liikkeelle ja vaeltakaamme eteenpäin; minä vaellan sinun edelläsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Mutta Jaakob sanoi hänelle: \"Herrani näkee itse, että lapset ovat pieniä ja että minulla on imettäviä lampaita ja lehmiä mukanani; jos näitä ajaa kiivaasti päivänkään, kuolee koko lauma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Kulkekoon siis herrani palvelijansa edellä; minä seuraan hiljalleen jäljessä, sen mukaan kuin karja, jota kuljetan, ja lapset jaksavat käydä, kunnes saavun herrani luo Seiriin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Eesau vastasi: \"Minä jätän luoksesi osan väestäni\". Hän sanoi: \"Minkätähden niin? Kunhan vain saan armon herrani silmien edessä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Niin Eesau sinä päivänä kääntyi takaisin ja meni sitä tietään Seiriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Mutta Jaakob lähti Sukkotiin ja rakensi siellä itsellensä majan. Ja karjallensa hän teki tarhoja. Siitä tuli sen paikan nimeksi Sukkot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Ja Jaakob saapui matkallansa Mesopotamiasta onnellisesti Sikemin kaupunkiin, joka on Kanaanin maassa, ja leiriytyi kaupungin edustalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Ja hän osti sen maapalstan, johon hän oli pystyttänyt telttansa, Hamorin, Sikemin isän, pojilta sadalla kesitalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Ja hän pystytti siihen alttarin ja antoi sille nimen Eel, Israelin Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Ja Diina, Leean tytär, jonka hän oli synnyttänyt Jaakobille, meni tapaamaan sen maan tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Ja Sikem, joka oli hivviläisen Hamorin, sen maan ruhtinaan, poika, näki hänet, otti hänet luokseen, makasi hänen kanssaan ja teki hänelle väkivaltaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Ja hänen sydämensä kiintyi Diinaan, Jaakobin tyttäreen, ja hän rakasti tyttöä ja viihdytteli häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Ja Sikem puhui isällensä Hamorille sanoen: \"Hanki minulle tämä tyttö vaimoksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Ja Jaakob oli saanut kuulla, että Sikem oli raiskannut hänen tyttärensä Diinan; mutta kun hänen poikansa olivat hänen laumansa kanssa kedolla, oli Jaakob vaiti siksi, kunnes he palasivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Ja Hamor, Sikemin isä, meni Jaakobin luo puhuttelemaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Ja Jaakobin pojat tulivat kedolta. Kuultuaan, mitä oli tapahtunut, miehet sydäntyivät ja vihastuivat kovin siitä, että hän oli tehnyt häpeällisen teon Israelissa, kun oli maannut Jaakobin tyttären; sillä semmoista ei saa tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Niin Hamor puhui heille sanoen: \"Poikani Sikemin sydän on mielistynyt teidän sisareenne; antakaa hänet hänelle vaimoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Lankoutukaa meidän kanssamme, antakaa te tyttäriänne meille, ja ottakaa te itsellenne meidän tyttäriämme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'ja jääkää asumaan meidän luoksemme. Maa on oleva teille avoinna, asukaa siinä ja kierrelkää siinä ja asettukaa sinne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Ja Sikem sanoi tytön isälle ja veljille: \"Suokaa minun saada armo silmienne edessä, ja mitä te vaaditte minulta, sen minä annan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Vaatikaa minulta kuinka suuri morsiamen hinta ja kuinka suuret antimet tahansa: minä annan, mitä te minulta vaaditte. Antakaa minulle vain se tyttö vaimoksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Mutta Jaakobin pojat vastasivat Sikemille ja hänen isällensä Hamorille puhuen petollisesti, sentähden että hän oli raiskannut heidän sisarensa Diinan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'he sanoivat heille: \"Emme voi tehdä sitä, että antaisimme sisaremme ympärileikkaamattomalle miehelle, sillä se olisi meistä häpeällistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Me suostumme ainoastaan sillä ehdolla, että te tulette meidän kaltaisiksemme, niin että kaikki miehenpuolenne ympärileikataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Silloin me annamme omia tyttäriämme teille ja otamme itsellemme teidän tyttäriänne, ja me asetumme teidän luoksenne ja tulemme yhdeksi kansaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Mutta jos te ette kuule meitä ettekä ympärileikkauta itseänne, niin me otamme sisaremme ja menemme tiehemme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Ja heidän puheensa kelpasi Hamorille ja Sikemille, Hamorin pojalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Eikä nuori mies viivytellyt niin tekemästä, sillä hän oli mieltynyt Jaakobin tyttäreen; ja hän oli suuremmassa arvossa kuin kukaan muu hänen isänsä perheessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Niin menivät Hamor ja hänen poikansa Sikem kaupunkinsa porttiin ja puhuivat kaupunkinsa miehille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '\"Näillä miehillä on rauha mielessä meitä kohtaan; antakaamme heidän siis asettua tähän maahan ja kierrellä siinä, onhan maa tilava heillekin joka suuntaan. Ottakaamme me heidän tyttäriänsä vaimoiksemme, ja antakaamme me tyttäriämme heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Mutta ainoastaan sillä ehdolla miehet suostuvat asettumaan meidän luoksemme, tullaksensa meidän kanssamme yhdeksi kansaksi, että kaikki miehenpuolemme ympärileikataan, niinkuin he itsekin ovat ympärileikatut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Tulevathan silloin heidän karjansa ja tavaransa ja kaikki heidän juhtansa meidän omiksemme. Suostukaamme siis, niin he asettuvat luoksemme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Ja he kuulivat Hamoria ja hänen poikaansa Sikemiä; kaikki, jotka kulkivat hänen kaupunkinsa portista; ja niin kaikki miehenpuolet, kaikki, jotka kulkivat hänen kaupunkinsa portista, ympärileikkauttivat itsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Mutta kolmantena päivänä, kun he olivat kipeimmillään, Jaakobin kaksi poikaa, Simeon ja Leevi, Diinan veljet, ottivat kumpikin miekkansa ja hyökkäsivät, kenenkään aavistamatta, kaupunkiin ja tappoivat jokaisen miehenpuolen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Myöskin Hamorin ja hänen poikansa Sikemin he tappoivat miekan terällä, ottivat Diinan Sikemin talosta ja menivät pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Ja Jaakobin pojat karkasivat haavoitettujen kimppuun ja ryöstivät kaupungin, sentähden että he olivat raiskanneet heidän sisarensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Ja he anastivat heidän pikkukarjansa ja raavaskarjansa ja aasinsa ja kaikki, mitä oli sekä kaupungissa että kedolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Ja kaikki heidän tavaransa, kaikki heidän lapsensa ja vaimonsa he veivät saaliinaan, ja he ryöstivät samoin kaiken muun, mitä taloissa oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Niin Jaakob sanoi Simeonille ja Leeville: \"Te olette syösseet minut onnettomuuteen, saattaneet minut tämän maan asukkaiden, kanaanilaisten ja perissiläisten, vihoihin. Minun joukkoni on vähäinen; jos he kokoontuvat minua vastaan, niin he tuhoavat minut, ja niin minut ja minun sukuni hävitetään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Mutta he vastasivat: \"Pitikö hänen kohdella meidän sisartamme niinkuin porttoa!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Ja Jumala sanoi Jaakobille: \"Nouse, mene Beeteliin, asetu sinne ja rakenna sinne alttari Jumalalle, joka ilmestyi sinulle paetessasi veljeäsi Eesauta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Niin Jaakob sanoi perheellensä ja kaikille, jotka olivat hänen kanssaan: \"Poistakaa vieraat jumalat, joita teillä on keskuudessanne, puhdistautukaa ja muuttakaa vaatteenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Ja nouskaamme ja menkäämme Beeteliin, rakentaakseni sinne alttarin Jumalalle, joka kuuli minua ahdistukseni aikana ja oli minun kanssani tiellä, jota vaelsin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Niin he jättivät Jaakobille kaikki vieraat jumalat, jotka olivat heidän hallussansa, sekä renkaat, jotka olivat heidän korvissaan, ja Jaakob kätki ne maahan tammen alle, joka oli Sikemissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Ja he lähtivät liikkeelle; ja Jumalan kauhu valtasi heidän ympärillään olevat kaupungit, niin etteivät nämä ajaneet takaa Jaakobin poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Ja Jaakob saapui Luusiin, joka on Kanaanin maassa, se on Beeteliin, kaiken väen kanssa, joka oli hänen seurassaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Ja hän rakensi sinne alttarin ja nimitti paikan Eel-Beeteliksi, koska Jumala oli siellä ilmestynyt hänelle, silloin kun hän pakeni veljeään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Mutta Debora, Rebekan imettäjä, kuoli, ja hänet haudattiin Beetelin alapuolelle tammen alle, ja se sai siitä nimen \"Itkutammi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Ja Jumala ilmestyi jälleen Jaakobille hänen palattuaan Mesopotamiasta ja siunasi hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Ja Jumala sanoi hänelle: \"Sinun nimesi on Jaakob; mutta älköön sinua enää kutsuttako Jaakobiksi, vaan nimesi olkoon Israel\". -Niin hän sai nimen Israel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Ja Jumala sanoi hänelle: \"Minä olen Jumala, Kaikkivaltias; ole hedelmällinen ja lisäänny. Kansa, suuri kansojen joukko on sinusta tuleva, ja kuninkaita lähtee sinun kupeistasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Ja maan, jonka minä olen antanut Aabrahamille ja Iisakille, minä annan sinulle; myöskin sinun jälkeläisillesi minä annan sen maan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Ja Jumala kohosi ylös hänen luotaan siitä paikasta, jossa hän oli häntä puhutellut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Ja Jaakob pystytti patsaan siihen paikkaan, jossa hän oli häntä puhutellut, kivipatsaan, ja vuodatti juomauhrin sen päälle ja kaatoi öljyä sen päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Ja Jaakob nimitti sen paikan, jossa Jumala oli häntä puhutellut, Beeteliksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Sitten he lähtivät liikkeelle Beetelistä. Ja kun vielä oli jonkun verran matkaa Efrataan, joutui Raakel synnytystuskiin, ja hänen synnytystuskansa olivat hyvin kovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Ja kun hänen synnytystuskansa olivat kovimmillaan, sanoi kätilövaimo hänelle: \"Älä pelkää, sillä tälläkin kertaa sinä saat pojan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Mutta kun hänen henkensä oli lähtemäisillään, sillä hänen oli kuoltava, antoi hän hänelle nimen Benoni, mutta hänen isänsä antoi hänelle nimen Benjamin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Niin Raakel kuoli siellä, ja hänet haudattiin Efratan tien varteen, se on Beetlehemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Ja Jaakob pystytti hänen haudalleen patsaan; tämä Raakelin hautapatsas on olemassa vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Ja Israel lähti liikkeelle sieltä ja pystytti telttansa tuolle puolen Karjatornia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Ja tapahtui, kun Israel asui siinä maassa, että Ruuben meni ja makasi Bilhan, isänsä sivuvaimon, kanssa. Ja Israel sai sen kuulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Jaakobilla oli kaksitoista poikaa. Leean pojat olivat Ruuben, Jaakobin esikoinen, Simeon, Leevi, Juuda, Isaskar ja Sebulon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Raakelin pojat olivat Joosef ja Benjamin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Bilhan, Raakelin orjattaren, pojat olivat Daan ja Naftali.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Silpan, Leean orjattaren, pojat olivat Gaad ja Asser. Nämä ovat ne Jaakobin pojat, jotka syntyivät hänelle Mesopotamiassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Ja Jaakob saapui isänsä Iisakin luo Mamreen, Kirjat-Arbaan, se on Hebroniin, jossa Aabraham ja Iisak olivat asuneet muukalaisina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Ja Iisakin elinaika oli sata kahdeksankymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Ja Iisak vaipui kuolemaan ja tuli otetuksi heimonsa tykö, vanhana ja elämästä kyllänsä saaneena. Ja hänen poikansa Eesau ja Jaakob hautasivat hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Tämä on kertomus Eesaun, se on Edomin, suvusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Eesau otti vaimoikseen Kanaanin tyttäristä Aadan, heettiläisen Eelonin tyttären, ja Oholibaman, joka oli hivviläisen Sibonin pojan Anan tytär,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'ja Baasematin, Ismaelin tyttären, Nebajotin sisaren.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Aada synnytti Eesaulle Elifaan, ja Baasemat synnytti Reguelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Ja Oholibama synnytti Jeuksen, Jalamin ja Koorahin. Nämä olivat Eesaun pojat, jotka syntyivät hänelle Kanaanin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Ja Eesau otti vaimonsa, poikansa ja tyttärensä ja kaiken talonväkensä, karjansa ja kaikki juhtansa ja kaiken tavaransa, jonka hän oli hankkinut Kanaanin maassa; ja hän lähti toiseen maahan, pois veljensä Jaakobin luota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Sillä heidän omaisuutensa oli niin suuri, etteivät he voineet asua yhdessä, eikä se maa, jossa he asuivat muukalaisina, riittänyt heille heidän karjansa paljouden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Ja Eesau asettui Seirin vuoristoon, Eesau, se on Edom.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Ja tämä on kertomus edomilaisten isän Eesaun suvusta, hänen, joka asui Seirin vuoristossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Nämä ovat Eesaun poikien nimet: Elifas, Eesaun vaimon Aadan poika; Reguel, Eesaun vaimon Baasematin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Ja Elifaan pojat olivat Teeman, Oomar, Sefo, Gaetam ja Kenas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Mutta Timna oli Elifaan, Eesaun pojan, sivuvaimo, ja hän synnytti Elifaalle Amalekin. Nämä olivat Eesaun vaimon Aadan pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Reguelin pojat olivat nämä: Nahat ja Serah, Samma ja Missa. Ne olivat Eesaun vaimon Baasematin pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Mutta nämä olivat Eesaun vaimon Oholibaman, Sibonin pojan Anan tyttären, pojat, jotka hän synnytti Eesaulle: Jeus, Jalam ja Koorah.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Nämä olivat Eesaun poikien sukuruhtinaat: Elifaan, Eesaun esikoisen, pojat olivat ruhtinas Teeman, ruhtinas Oomar, ruhtinas Sefo, ruhtinas Kenas,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'ruhtinas Koorah, ruhtinas Gaetam, ruhtinas Amalek. Nämä olivat ne ruhtinaat, jotka polveutuivat Elifaasta Edomin maassa; ne olivat Aadan pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Ja nämä olivat Reguelin, Eesaun pojan, pojat: ruhtinas Nahat, ruhtinas Serah, ruhtinas Samma, ruhtinas Missa. Nämä olivat ne ruhtinaat, jotka polveutuivat Reguelista Edomin maassa; ne olivat Eesaun vaimon Baasematin pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Ja nämä olivat Eesaun vaimon Oholibaman pojat: ruhtinas Jeus, ruhtinas Jalam, ruhtinas Koorah. Nämä olivat ne ruhtinaat, jotka polveutuivat Eesaun vaimosta, Anan tyttärestä Oholibamasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Nämä olivat Eesaun, se on Edomin, pojat, ja nämä heidän sukuruhtinaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Mutta nämä olivat hoorilaisen Seirin pojat, sen maan alkuasukkaat: Lootan, Soobal, Sibon, Ana,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Diison, Eeser ja Diisan. Nämä olivat hoorilaisten sukuruhtinaat, Seirin pojat, Edomin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Mutta Lootanin pojat olivat Hoori ja Heemam; ja Lootanin sisar oli Timna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Ja nämä olivat Soobalin pojat: Alvan, Maanahat ja Eebal, Sefo ja Oonam.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Nämä olivat Sibonin pojat: Aija ja Ana. Tämä oli se Ana, joka löysi ne lämpimät lähteet erämaassa, paimentaessaan isänsä Sibonin aaseja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Ja nämä olivat Anan lapset: Diison ja Oholiba, Anan tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Nämä olivat Diisonin pojat: Hemdan, Esban, Jitran ja Keran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Nämä olivat Eeserin pojat: Bilhan, Saavan ja Akan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Nämä olivat Diisanin pojat: Uus ja Aran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Nämä olivat hoorilaisten sukuruhtinaat: ruhtinas Lootan, ruhtinas Soobal, ruhtinas Sibon, ruhtinas Ana,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'ruhtinas Diison, ruhtinas Eeser, ruhtinas Diisan. Nämä olivat hoorilaisten sukuruhtinaat, ruhtinas ruhtinaalta, Seirin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Ja nämä olivat ne kuninkaat, jotka hallitsivat Edomin maassa, ennenkuin yksikään kuningas oli hallinnut israelilaisia:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela, Beorin poika, oli kuninkaana Edomissa, ja hänen kaupunkinsa nimi oli Dinhaba.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Kun Bela kuoli, tuli Joobab, Serahin poika, Bosrasta, kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Kun Joobab kuoli, tuli Huusam, teemanilaisten maasta, kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Kun Huusam kuoli, tuli Hadad, Bedadin poika, kuninkaaksi hänen sijaansa, hän, joka voitti midianilaiset Mooabin kedolla; ja hänen kaupunkinsa nimi oli Avit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Kun Hadad kuoli, tuli Samla, Masrekasta, kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Kun Samla kuoli, tuli Saul, Rehobotista, virran varrelta, kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Kun Saul kuoli, tuli Baal-Haanan, Akborin poika, kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Kun Baal-Haanan, Akborin poika, kuoli, tuli Hadar kuninkaaksi hänen sijaansa, ja hänen kaupunkinsa nimi oli Paagu; ja hänen vaimonsa nimi oli Mehetabel, joka oli Matredin, Mee-Saahabin tyttären, tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Ja nämä ovat Eesaun sukuruhtinasten nimet, heidän sukujensa, asuinpaikkojensa ja nimiensä mukaan: ruhtinas Timna, ruhtinas Alva, ruhtinas Jetet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'ruhtinas Oholibama, ruhtinas Eela, ruhtinas Piinon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'ruhtinas Kenas, ruhtinas Teeman, ruhtinas Mibsar,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'ruhtinas Magdiel, ruhtinas Iiram. Nämä olivat Edomin sukuruhtinaat, heidän asuinsijojensa mukaan heidän perintömaassaan-Edomin, se on Eesaun, edomilaisten isän, sukuruhtinaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Mutta Jaakob asui siinä maassa, jossa hänen isänsä oli oleskellut muukalaisena, Kanaanin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Tämä on kertomus Jaakobin suvusta. Kun Joosef oli seitsemäntoista vuoden vanha, oli hän veljiensä kanssa lampaita paimentamassa; hän oli nuorukaisena isänsä vaimojen Bilhan ja Silpan poikien seurassa. Ja hän kertoi isälleen, mitä pahaa kuuli heistä puhuttavan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Ja Israel rakasti Joosefia enemmän kuin kaikkia muita poikiansa, koska hän oli syntynyt hänelle hänen vanhalla iällänsä, ja hän teetti hänelle pitkäliepeisen, hihallisen ihokkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Kun hänen veljensä näkivät, että heidän isänsä rakasti häntä enemmän kuin kaikkia hänen veljiänsä, vihasivat he häntä eivätkä voineet puhutella häntä ystävällisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Kerran Joosef näki unen ja kertoi sen veljilleen; sen jälkeen he vihasivat häntä vielä enemmän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Hän näet sanoi heille: \"Kuulkaa, minkä unen minä olen nähnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Katso, me olimme sitovinamme lyhteitä vainiolla, ja katso, minun lyhteeni nousi seisomaan, ja teidän lyhteenne asettuivat ympärille ja kumarsivat minun lyhdettäni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Niin hänen veljensä sanoivat hänelle: \"Sinäkö tulisit meidän kuninkaaksemme, sinäkö hallitsisit meitä?\" Ja he vihasivat häntä vielä enemmän hänen uniensa ja puheidensa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Ja hän näki vielä toisenkin unen, jonka hän kertoi veljilleen ja sanoi: \"Minä näin vielä unen: katso, aurinko ja kuu ja yksitoista tähteä kumarsivat minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Ja kun hän kertoi sen isälleen ja veljilleen, nuhteli hänen isänsä häntä ja sanoi hänelle: \"Mikä uni se on, jonka sinä olet nähnyt? Olisiko minun ja äitisi ja veljiesi tultava kumartumaan sinun eteesi maahan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Ja hänen veljensä kadehtivat häntä; mutta hänen isänsä pani tämän mieleensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Kun hänen veljensä olivat menneet kaitsemaan isänsä lampaita Sikemiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'sanoi Israel Joosefille: \"Sinun veljesi ovat paimenessa Sikemissä; tule, minä lähetän sinut heidän luokseen\". Hän vastasi: \"Tässä olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Ja hän sanoi hänelle: \"Mene katsomaan, kuinka veljesi ja karja voivat, ja kerro sitten minulle\". Niin hän lähetti hänet matkalle Hebronin laaksosta, ja hän tuli Sikemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Ja muuan mies kohtasi hänet, hänen harhaillessaan kedolla; ja mies kysyi häneltä: \"Mitä etsit?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Hän vastasi: \"Minä etsin veljiäni; sano minulle, missä he ovat paimentamassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Mies vastasi: \"He lähtivät pois täältä, sillä minä kuulin heidän sanovan: \'Menkäämme Dootaniin\'.\" Niin Joosef meni veljiensä jäljissä ja löysi heidät Dootanista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Kun he kaukaa näkivät hänet ja ennenkuin hän saapui heidän luokseen, pitivät he neuvoa tappaaksensa hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'He sanoivat toisillensa: \"Katso, tuolla tulee se unennäkijä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Tulkaa, tappakaamme nyt hänet ja heittäkäämme hänet johonkin kaivoon ja sanokaamme: villipeto on hänet syönyt. Saammepa sitten nähdä, mitä hänen unistaan tulee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Kun Ruuben sen kuuli, tahtoi hän pelastaa hänet heidän käsistään ja sanoi: \"Älkäämme lyökö häntä kuoliaaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Vielä Ruuben sanoi heille: \"Älkää vuodattako verta; heittäkää hänet tähän kaivoon, joka on täällä erämaassa, mutta älkää satuttako kättänne häneen\". Hän näet tahtoi pelastaa hänet heidän käsistään, saattaaksensa hänet takaisin isänsä tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Kun Joosef sitten tuli veljiensä luo, riisuivat he Joosefilta hänen ihokkaansa, pitkäliepeisen, hihallisen ihokkaan, joka oli hänen yllään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'ja ottivat hänet ja heittivät hänet kaivoon; mutta kaivo oli tyhjä, siinä ei ollut vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Senjälkeen he istuivat aterioimaan. Ja kun he nostivat silmänsä, näkivät he ismaelilaismatkueen tulevan Gileadista; heidän kamelinsa kuljettivat kumihartsia, balsamia ja hajupihkaa, ja he olivat viemässä niitä Egyptiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Silloin Juuda sanoi veljillensä: \"Mitä hyötyä meillä on siitä, että surmaamme veljemme ja salaamme hänen verensä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Tulkaa, myykäämme hänet ismaelilaisille, mutta älköön kätemme sattuko häneen, sillä hän on meidän veljemme, meidän omaa lihaamme.\" Ja hänen veljensä kuulivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Kun nyt midianilaiset kauppiaat menivät siitä ohitse, vetivät veljet Joosefin ylös kaivosta; ja he myivät Joosefin kahdestakymmenestä hopeasekelistä ismaelilaisille. Nämä veivät Joosefin Egyptiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Kun sitten Ruuben palasi kaivolle, niin Joosefia ei enää ollut kaivossa. Silloin hän repäisi vaatteensa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'palasi veljiensä luo ja sanoi: \"Poika on kadonnut. Voi minua, minne minä joudun!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Niin he ottivat Joosefin ihokkaan, teurastivat vuohipukin ja kastoivat ihokkaan vereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Sitten he lähettivät tuon pitkäliepeisen, hihallisen ihokkaan kotiin isälleen ja sanoivat: \"Tämän me löysimme; tarkasta, onko se poikasi ihokas vai eikö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Ja tarkastettuaan sen hän sanoi: \"Tämä on minun poikani ihokas. Villipeto on hänet syönyt; totisesti, Joosef on raadeltu kuoliaaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Ja Jaakob repäisi vaatteensa, pani säkin lanteilleen ja suri poikaansa pitkät ajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Ja kaikki hänen poikansa ja tyttärensä kävivät häntä lohduttamaan, mutta hän ei huolinut lohdutuksesta, vaan sanoi: \"Murehtien minä menen tuonelaan poikani tykö\". Ja hänen isänsä itki häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Mutta midianilaiset myivät hänet Egyptiin Potifarille, joka oli faraon hoviherra ja henkivartijain päämies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Siihen aikaan Juuda lähti pois veljiensä luota ja asettui erään Adullamissa asuvan miehen luo, jonka nimi oli Hiira.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Siellä Juuda näki Suua nimisen kanaanilaisen miehen tyttären, ja hän otti tämän luokseen ja yhtyi häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Ja hän tuli raskaaksi ja synnytti pojan; ja hän antoi hänelle nimen Eer.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Ja taas hän tuli raskaaksi ja synnytti pojan ja antoi hänelle nimen Oonan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Ja hän synnytti vieläkin pojan ja antoi hänelle nimen Seela; ja synnyttäessään hänet hän oli Kesibissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Ja Juuda otti Eerille, esikoisellensa, vaimon, jonka nimi oli Taamar.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Mutta Eer, Juudan esikoinen, ei ollut Herralle otollinen; sentähden Herra antoi hänen kuolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Niin Juuda sanoi Oonanille: \"Yhdy veljesi leskeen ja ota hänet avioksesi ja herätä siemen veljellesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Mutta kun Oonan tiesi, ettei jälkeläinen olisi oleva hänen, niin hän antoi, aina kun yhtyi veljensä vaimoon, siemenensä mennä maahan, ettei hankkisi jälkeläistä veljelleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Mutta se, minkä hän teki, oli paha Herran silmissä; sentähden hän antoi hänenkin kuolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Silloin Juuda sanoi miniällensä Taamarille: \"Asu leskenä isäsi talossa, kunnes poikani Seela joutuu täysikasvuiseksi\". Hän näet ajatteli: \"Kun ei vain tämäkin kuolisi niinkuin hänen veljensä\". Niin Taamar meni pois ja jäi asumaan isänsä kotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Pitkän aikaa sen jälkeen Suuan tytär, Juudan vaimo, kuoli. Suruajan mentyä Juuda lähti ystävänsä adullamilaisen Hiiran kanssa Timnaan lammastensa keritsiäisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Niin tuotiin Taamarille tämä sanoma: \"Katso, appesi menee Timnaan keritsemään lampaitaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Silloin hän riisui pois leskenvaatteensa ja verhoutui huntuun peittäytyen siihen ja istui Eenaimin portille, Timnaan vievän tien varteen. Sillä hän oli nähnyt, että vaikka Seela oli täysikasvuinen, ei häntä annettu hänelle vaimoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Kun nyt Juuda näki hänet, luuli hän häntä portoksi; sillä hän oli peittänyt kasvonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Ja hän poikkesi hänen luokseen tiepuoleen ja sanoi: \"Anna minun yhtyä sinuun\". Hän näet ei tiennyt, että nainen oli hänen miniänsä. Tämä vastasi: \"Mitä annat minulle saadaksesi yhtyä minuun?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Hän sanoi: \"Lähetän sinulle vohlan laumastani\". Nainen vastasi: \"Annatko minulle pantin, kunnes sen lähetät?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Hän sanoi: \"Mitä on minun annettava sinulle pantiksi?\" Hän vastasi: \"Sinettisi, nauhasi ja sauvasi, joka on kädessäsi\". Niin hän antoi ne hänelle ja yhtyi häneen, ja hän tuli hänestä raskaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Ja hän nousi ja meni sieltä ja pani pois huntunsa ja pukeutui leskenvaatteisiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Mutta Juuda lähetti adullamilaisen ystävänsä viemään vohlaa, saadaksensa takaisin pantin naiselta; mutta hän ei löytänyt häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Ja hän kyseli sen paikkakunnan miehiltä ja sanoi: \"Missä on se pyhäkköportto, joka istui Eenaimissa tien varressa?\" He vastasivat: \"Ei täällä ole ollut mitään pyhäkköporttoa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Ja hän palasi Juudan luo ja sanoi: \"En löytänyt häntä; ja myös sen paikkakunnan miehet sanoivat, ettei siellä ole ollutkaan mitään pyhäkköporttoa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Silloin Juuda sanoi: \"Pitäköön sen sitten, ettemme joutuisi häpeään. Katso, minä olen lähettänyt tämän vohlan, mutta sinä et ole löytänyt häntä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Noin kolmen kuukauden kuluttua ilmoitettiin Juudalle: \"Sinun miniäsi Taamar on harjoittanut haureutta, ja haureudesta hän on myös tullut raskaaksi\". Juuda sanoi: \"Viekää hänet poltettavaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Mutta kun häntä vietiin, lähetti hän sanan apelleen sanoen: \"Minä olen raskaana siitä miehestä, jonka nämä ovat\". Ja hän käski sanoa: \"Tarkasta, kenen tämä sinetti, nämä nauhat ja tämä sauva ovat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Ja Juuda tunsi ne ja sanoi: \"Hän on oikeassa minua vastaan, koska minä en antanut häntä pojalleni Seelalle\". Ei hän kuitenkaan enää yhtynyt häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Kun hänen synnyttämisensä aika tuli, katso, hänen kohdussaan oli kaksoiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Ja hänen synnyttäessään pisti toinen kätensä ulos; kätilövaimo otti punaista lankaa ja sitoi sen hänen käteensä ja sanoi: \"Tämä tuli ensiksi ulos\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Mutta kun hän sitten taas veti kätensä takaisin, katso, silloin tuli hänen veljensä ulos; ja kätilövaimo sanoi: \"Minkä repeämän oletkaan reväissyt itsellesi!\" Ja hän sai nimen Peres.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Sitten tuli hänen veljensä, jonka kädessä oli punainen lanka; ja hän sai nimen Serah.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Ja Joosef vietiin Egyptiin, ja Potifar, egyptiläinen mies, joka oli faraon hoviherra ja henkivartijain päämies, osti hänet ismaelilaisilta, jotka olivat hänet sinne tuoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Mutta Herra oli Joosefin kanssa, niin että hän menestyi kaikessa, ja hän oleskeli isäntänsä, egyptiläisen, talossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Ja hänen isäntänsä näki, että Herra oli hänen kanssaan ja että Herra antoi kaiken, mitä hän teki, menestyä hänen käsissään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Niin Joosef saavutti hänen suosionsa ja sai palvella häntä. Ja hän asetti hänet talonsa hoitajaksi ja uskoi hänen haltuunsa kaikki, mitä hänellä oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Ja siitä ajasta lähtien, kun hän oli uskonut hänen hoitoonsa talonsa ja kaiken, mitä hänellä oli, Herra siunasi egyptiläisen taloa Joosefin tähden, ja Herran siunaus oli kaikessa, mitä hänellä oli kotona ja kedolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Niin hän jätti Joosefin haltuun kaikki, mitä hänellä oli, eikä hän itse välittänyt mistään, paitsi ruuasta, jota hän söi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Mutta Joosefilla oli kaunis vartalo ja kauniit kasvot. Ja tapahtui jonkun ajan kuluttua, että hänen isäntänsä puoliso iski silmänsä Joosefiin ja sanoi: \"Makaa minun kanssani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Mutta hän kieltäytyi ja sanoi isäntänsä puolisolle: \"Katso, isäntäni ei itse välitä mistään, mitä talossa on, vaan on uskonut minun haltuuni kaikki, mitä hänellä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Hänellä ei ole tässä talossa enemmän valtaa kuin minulla, eikä hän ole kieltänyt minulta mitään, paitsi sinut, koska olet hänen puolisonsa. Kuinka minä siis tekisin niin suuren pahanteon ja rikkoisin Jumalaa vastaan!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Ja vaikka vaimo joka päivä puhui sellaista Joosefille, ei tämä suostunut makaamaan hänen vieressänsä eikä olemaan hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Mutta eräänä päivänä, kun Joosef tuli taloon toimittamaan askareitaan eikä ketään talonväestä ollut sisällä saapuvilla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'tarttui hän Joosefin vaippaan ja sanoi: \"Makaa minun kanssani\". Mutta tämä jätti vaippansa hänen käsiinsä, pakeni ja riensi ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Kun hän nyt huomasi, että Joosef oli jättänyt vaippansa hänen käsiinsä ja paennut ulos,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'huusi hän talonväkeään ja sanoi heille näin: \"Katsokaa, hän on tuonut meille hebrealaisen miehen pitämään meitä pilkkanaan; tämä tuli luokseni maatakseen minun kanssani, mutta minä huusin kovalla äänellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Ja kun hän kuuli minun kirkaisevan ja huutavan, jätti hän vaippansa viereeni, pakeni ja riensi ulos.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Ja hän pani vaipan viereensä siksi, kunnes Joosefin isäntä tuli kotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Ja hän puhui hänelle samalla tavalla, sanoen: \"Tuo hebrealainen orja, jonka olet tuonut meille, tuli luokseni pitämään minua pilkkanaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'mutta kun minä kirkaisin ja huusin, jätti hän vaippansa viereeni ja pakeni ulos\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Kun hänen isäntänsä kuuli puolisonsa kertovan ja sanovan: \"Näin sinun orjasi on tehnyt minulle\", syttyi hänen vihansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Ja Joosefin isäntä otti hänet ja pani hänet vankilaan, paikkaan, jossa kuninkaan vangit säilytettiin; ja hän jäi siihen vankilaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Mutta Herra oli Joosefin kanssa ja soi hänen saavuttaa suosiota ja päästä vankilan päällikön armoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Ja vankilan päällikkö uskoi kaikki vangit, jotka vankilassa olivat, Joosefin haltuun. Ja kaikki, mitä siellä toimitettiin, tehtiin hänen toimestaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Eikä vankilan päällikkö ollenkaan valvonut sitä, mikä oli Joosefille uskottu, sillä Herra oli Joosefin kanssa. Ja Herra antoi menestyä sen, mitä hän teki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Ja tapahtui jonkun ajan kuluttua, että Egyptin kuninkaan juomanlaskija ja leipoja rikkoivat herraansa, Egyptin kuningasta, vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Ja farao vihastui näihin kahteen hoviherraansa, ylimmäiseen juomanlaskijaan ja ylimmäiseen leipojaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'ja panetti heidät vankeuteen henkivartijain päämiehen taloon, samaan vankilaan, jossa Joosef oli vankina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Ja henkivartijain päämies antoi heille Joosefin heitä palvelemaan. Niin he olivat jonkun aikaa vankeudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Ollessaan vankilassa vangittuina he molemmat, Egyptin kuninkaan juomanlaskija ja leipoja, näkivät samana yönä unta, kumpikin unensa, ja kummankin unella oli oma selityksensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Ja kun Joosef aamulla tuli heidän luokseen, huomasi hän heidät alakuloisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Silloin hän kysyi faraon hoviherroilta, jotka olivat hänen kanssansa vankeudessa hänen isäntänsä talossa: \"Miksi te olette tänään niin murheellisen näköiset?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'He vastasivat hänelle: \"Olemme kumpikin nähneet unen, eikä ole niiden selittäjää\". Ja Joosef sanoi heille: \"Unien selitykset ovat Jumalan; kertokaa kuitenkin minulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Niin ylimmäinen juomanlaskija kertoi unensa Joosefille ja sanoi hänelle: \"Minä näin unta, ja katso, minun edessäni oli viinipuu;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'viinipuussa oli kolme oksaa, ja samassa kun se alkoi versoa, sen kukat puhkesivat ja marjat sen rypäleissä kypsyivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Ja minulla oli faraon malja kädessäni, ja minä otin marjat ja pusersin niistä mehun faraon maljaan ja annoin maljan faraon käteen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Ja Joosef sanoi hänelle: \"Tämä on sen selitys: kolme oksaa merkitsee kolmea päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Kolmen päivän kuluttua farao korottaa sinun pääsi ja asettaa sinut jälleen virkaasi. Ja sinä annat faraon maljan hänen käteensä niinkuin ennenkin, kun olit hänen juomanlaskijansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Mutta muista minua, kun sinun hyvin käy, ja tee minulle laupeus mainitsemalla minusta faraolle ja toimittamalla minut pois tästä talosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Sillä minut on varastettu hebrealaisten maasta, enkä minä ole täälläkään tehnyt mitään, mistä minut olisi tullut panna tähän vankikuoppaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Kun ylimmäinen leipoja näki, että Joosef antoi hyvän selityksen, sanoi hän hänelle: \"Myöskin minä näin unen, ja katso, kolme nisuleipäkoria oli minun pääni päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Ja ylimmässä korissa oli kaikenlaisia leivoksia faraon syötäväksi, mutta linnut söivät ne korista, joka oli minun pääni päällä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Joosef vastasi ja sanoi: \"Tämä on sen selitys: kolme koria merkitsee kolmea päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Kolmen päivän kuluttua farao korottaa sinun pääsi ripustamalla sinut hirsipuuhun, ja taivaan linnut syövät sinun lihasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Kolmantena päivänä sen jälkeen, faraon syntymäpäivänä, tämä laittoi pidot kaikille palvelijoilleen. Silloin hän korotti palvelijainsa joukosta sekä ylimmäisen juomanlaskijan että ylimmäisen leipojan pään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Ylimmäisen juomanlaskijan hän asetti hänen entiseen juomanlaskijan toimeensa, niin että hän sai antaa maljan faraon käteen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'mutta ylimmäisen leipojan hän hirtätti, niinkuin Joosef oli heille selityksessään sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Mutta ylimmäinen juomanlaskija ei muistanut Joosefia, vaan unhotti hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Kahden vuoden kuluttua tapahtui, että farao näki unen; hän oli seisovinaan Niilivirran rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Ja katso, virrasta nousi seitsemän kaunista ja lihavaa lehmää, jotka kävivät laitumella kaislikossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Ja katso, niiden jälkeen nousi virrasta toiset seitsemän lehmää, rumia ja laihoja; ne asettuivat edellisten lehmien viereen virran rannalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Ja ne rumat ja laihat lehmät söivät ne seitsemän kaunista ja lihavaa lehmää. Siihen farao heräsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Mutta hän nukkui uudestaan ja näki toisen kerran unta: seitsemän paksua ja kaunista tähkäpäätä kasvoi samassa oljessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Ja katso, niiden jälkeen kasvoi vielä seitsemän tähkäpäätä, ohutta ja itätuulen polttamaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Ja nämä ohuet tähkäpäät nielivät ne seitsemän paksua ja täyteläistä tähkäpäätä. Siihen farao heräsi, ja katso, se oli unta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Mutta aamulla hänen mielensä oli levoton, ja hän kutsutti eteensä kaikki Egyptin tietäjät ja kaikki viisaat; ja farao kertoi heille unensa, mutta ei ollut sitä, joka olisi voinut selittää ne faraolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Silloin puhui ylimmäinen juomanlaskija faraolle sanoen: \"Nyt minä muistan rikokseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Farao oli vihastunut palvelijoihinsa, ja hän pani minut vankeuteen henkivartijain päämiehen taloon, minut ja ylimmäisen leipojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Niin me molemmat, minä ja hän, näimme samana yönä unta; me näimme kumpikin unemme, jolla oli oma selityksensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Ja siellä oli meidän kanssamme hebrealainen nuorukainen, henkivartijain päämiehen palvelija. Hänelle me kerroimme unemme, ja hän selitti ne meille; hän selitti, mitä kummankin uni merkitsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Ja niinkuin hän meille oli selittänyt, niin kävikin: minut asetettiin entiseen virkaani, toinen hirtettiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Silloin farao kutsutti Joosefin eteensä. Ja hänet tuotiin kiiruusti vankikuopasta. Ja hän ajatti hiuksensa ja muutti vaatteensa ja tuli faraon eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Ja farao sanoi Joosefille: \"Minä olen nähnyt unen, eikä ole sen selittäjää, mutta olen kuullut kerrottavan sinusta, että kun kuulet unen, sinä voit sen selittää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Joosef vastasi faraolle sanoen: \"En minä; mutta Jumala antaa faraolle suotuisan vastauksen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Ja farao puhui Joosefille: \"Minä näin unen; olin seisovinani Niilivirran rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Ja katso, virrasta nousi seitsemän lihavaa ja kaunista lehmää, jotka kävivät laitumella kaislikossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Ja katso, niiden jälkeen nousi virrasta toiset seitsemän lehmää, kurjia, kovin rumia ja laihoja; en ole koko Egyptin maassa nähnyt niin rumia kuin ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Ja nämä laihat ja rumat lehmät söivät ne ensimmäiset, ne lihavat lehmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Mutta vaikka ne olivat nielleet nämä, ei voinut huomata, että ne olivat nielleet ne, vaan ne olivat yhtä rumannäköiset kuin ennenkin. Siihen minä heräsin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Mutta taas minä näin unta: seitsemän täyteläistä ja kaunista tähkäpäätä kasvoi samassa oljessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Ja katso, niiden jälkeen kasvoi vielä seitsemän tähkäpäätä, kuivunutta, ohutta ja itätuulen polttamaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Ja nämä ohuet tähkäpäät nielivät ne seitsemän kaunista tähkäpäätä. Minä kerroin tämän tietäjille, mutta ei kukaan kyennyt sanomaan minulle, mitä se merkitsee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Niin Joosef sanoi faraolle: \"Faraon unet merkitsevät kumpikin samaa; Jumala on ilmaissut faraolle, mitä hän on tekevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Seitsemän kaunista lehmää merkitsee seitsemää vuotta, seitsemän kaunista tähkäpäätä merkitsee myös seitsemää vuotta; unilla on sama merkitys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Ja seitsemän laihaa ja rumaa lehmää, jotka nousivat niiden jälkeen, merkitsee seitsemää vuotta, ja seitsemän tyhjää, itätuulen polttamaa tähkäpäätä merkitsee seitsemää nälkävuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Tätä minä tarkoitin, kun sanoin faraolle: Jumala on antanut faraon nähdä, mitä hän on tekevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Katso, tulee seitsemän vuotta, jolloin on suuri viljavuus koko Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Mutta niitä seuraa seitsemän sellaista nälkävuotta, että Egyptin maan entinen viljavuus kokonaan unhottuu, ja nälänhätä tuottaa maalle häviön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Eikä enää tiedetä mitään maassa vallinneesta viljavuudesta sitä seuraavan nälänhädän vuoksi, sillä se on oleva ylen kova.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Mutta että uni toistui faraolle, se tietää, että Jumala on asian varmasti päättänyt ja että Jumala antaa sen pian tapahtua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Nyt valitkoon siis farao ymmärtäväisen ja taitavan miehen ja asettakoon hänet Egyptin hallitusmieheksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Näin tehköön farao: asettakoon päällysmiehiä maahan ja ottakoon viidennen osan Egyptin maan sadosta seitsemänä viljavuotena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Ja koottakoon näinä hyvinä vuosina, jotka tulevat, kaikki niiden sato ja kasattakoon viljaa faraon haltuun, talletettakoon sato kaupunkeihin ja säilytettäköön,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'niin että maalla on eloa säästössä seitsemän nälkävuoden varalle, jotka kohtaavat Egyptin maata. Niin ei maa joudu perikatoon nälänhädän aikana.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Tämä puhe miellytti faraota ja kaikkia hänen palvelijoitansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Ja farao sanoi palvelijoilleen: \"Voisimmeko löytää ketään, jossa on Jumalan henki niinkuin tässä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Ja farao sanoi Joosefille: \"Koska Jumala on sinulle ilmoittanut kaiken tämän, ei ole ketään niin ymmärtäväistä ja taitavaa, kuin sinä olet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Hoida sinä minun taloani, ja sinun käskyäsi totelkoon kaikki minun kansani; ainoastaan valtaistuimen puolesta minä olen sinua korkeampi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Ja farao sanoi Joosefille: \"Katso, minä asetan sinut koko Egyptin maan hallitusmieheksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Ja farao otti sinettisormuksensa kädestään ja pani sen Joosefin käteen ja puetti hänen ylleen hienot pellavavaatteet ja ripusti kultakäädyt hänen kaulaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Ja hän antoi hänen ajaa omissa, lähinnä parhaissa vaunuissaan, ja hänen edellään huudettiin: abrek! Niin asetettiin hänet koko Egyptin maan hallitusmieheksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Ja farao sanoi Joosefille: \"Minä olen farao, mutta sinun tahtomattasi älköön kukaan nostako kättä tai jalkaa koko Egyptin maassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Ja farao nimitti Joosefin Saafenat-Paneahiksi ja antoi hänelle puolisoksi Aasenatin, Oonin papin Poti-Feran tyttären. Niin Joosef lähti tarkastamaan Egyptin maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Joosef oli kolmenkymmenen vuoden vanha, kun hän tuli faraon, Egyptin kuninkaan, palvelijaksi. Ja Joosef lähti faraon luota ja kulki läpi koko Egyptin maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Ja seitsemänä viljavuotena maa kasvoi ylen runsaasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Ja näinä seitsemänä hyvänä vuotena, jotka tulivat Egyptin maahan, hän kokosi kaikkea eloa ja talletti sen kaupunkeihin. Hän talletti kuhunkin kaupunkiin sen elon, joka tuotiin ympäristön vainioilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Niin Joosef kasasi viljaa niinkuin meren hiekkaa, ylen suuret määrät, siihen asti että lakattiin sitä mittaamasta, sillä se ei ollut enää mitattavissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Joosefille syntyi, ennenkuin nälkävuosi tuli, kaksi poikaa, jotka Aasenat, Oonin papin Poti-Feran tytär, synnytti hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Esikoiselle Joosef antoi nimen Manasse, \"sillä\", sanoi hän, \"Jumala on saattanut minut unhottamaan kaikki vaivani ja koko isäni kodin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Toiselle hän antoi nimen Efraim, \"sillä\", sanoi hän, \"Jumala on tehnyt minut hedelmälliseksi kärsimysteni maassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Ne seitsemän viljavuotta, jotka tulivat Egyptin maahan, kuluivat loppuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Senjälkeen alkoi seitsemän nälkävuotta, niinkuin Joosef oli sanonut, ja tuli nälänhätä kaikkiin maihin, mutta Egyptin maassa oli leipäviljaa kaikkialla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Mutta koko Egyptin maa näki nälkää, ja kansa huusi faraolta leipää. Silloin farao sanoi kaikille egyptiläisille: \"Menkää Joosefin luo ja tehkää, mitä hän käskee teidän tehdä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Kun nälkä ahdisti koko maata, avasi Joosef kaikki varastot ja myi viljaa egyptiläisille. Mutta nälänhätä tuli yhä kovemmaksi Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Ja kaikista maista tultiin Egyptiin Joosefin luo ostamaan viljaa, sillä kaikissa maissa oli kova nälänhätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Mutta kun Jaakob sai tietää, että Egyptissä oli viljaa, sanoi hän pojillensa: \"Mitä epäröitte?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Ja hän sanoi: \"Katso, minä olen kuullut, että Egyptissä on viljaa. Menkää sinne ja ostakaa meille sieltä viljaa, että pysyisimme hengissä emmekä kuolisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Niin kymmenen Joosefin veljeä lähti ostamaan viljaa Egyptistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Mutta Benjaminia, Joosefin veljeä, Jaakob ei lähettänyt hänen veljiensä mukana, sillä hän pelkäsi, että häntä kohtaisi jokin onnettomuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Niin Israelin pojat tulivat muiden tulijain mukana ostamaan viljaa, sillä Kanaanin maassa oli nälänhätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Mutta Joosef oli vallanpitäjänä maassa; hän myi viljaa kaikelle maan kansalle. Niin Joosefin veljet tulivat ja kumartuivat hänen edessään kasvoilleen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Ja Joosef näki veljensä, ja hän tunsi heidät, mutta tekeytyi heille vieraaksi, puhutteli heitä ankarasti ja kysyi heiltä: \"Mistä te tulette?\" He vastasivat: \"Kanaanin maasta tulemme, ostamaan elintarpeita\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Ja Joosef tunsi veljensä, mutta he eivät tunteneet häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Silloin Joosef muisti unet, jotka hän oli nähnyt heistä, ja sanoi heille: \"Te olette vakoojia; olette tulleet katsomaan, mistä maa olisi avoin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'He vastasivat hänelle: \"Ei, herra; palvelijasi ovat tulleet ostamaan elintarpeita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Me olemme kaikki saman miehen poikia, olemme rehellisiä miehiä; palvelijasi eivät ole vakoojia.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Mutta hän sanoi heille: \"Ei ole niin, vaan te olette tulleet katsomaan, mistä maa olisi avoin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'He vastasivat: \"Meitä, sinun palvelijoitasi, on kaksitoista veljestä, saman miehen poikia Kanaanin maasta; nuorin on nyt kotona isämme luona, ja yhtä ei enää ole\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Joosef sanoi heille: \"Niin on, kuin olen teille puhunut: te olette vakoojia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Näin te tulette koeteltaviksi: niin totta kuin farao elää, te ette pääse täältä lähtemään, ellei nuorin veljenne tule tänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Lähettäkää yksi joukostanne noutamaan veljenne tänne, mutta teidän muiden on jääminen tänne vangeiksi, että koeteltaisiin, oletteko puhuneet totta; muuten, niin totta kuin farao elää, te olette vakoojia.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Ja hän panetti heidät vankeuteen kolmeksi päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Mutta kolmantena päivänä Joosef sanoi heille: \"Jos tahdotte elää, niin tehkää näin, sillä minä olen Jumalaa pelkääväinen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'jos olette rehellisiä miehiä, niin jääköön yksi teistä, veljeksistä, vangiksi vankilaan, jossa teitä säilytettiin, mutta te muut menkää viemään kotiin viljaa perheittenne nälänhätään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Ja tuokaa nuorin veljenne minun luokseni. Jos teidän puheenne siten todeksi vahvistuu, niin vältätte kuoleman.\" Ja heidän täytyi tehdä niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Mutta he sanoivat toinen toisellensa: \"Totisesti, me olemme syylliset sen tähden, mitä teimme veljellemme; sillä me näimme hänen sielunsa tuskan, kun hän anoi meiltä armoa, emmekä kuulleet häntä. Sentähden on meille tullut tämä tuska.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Ruuben vastasi heille sanoen: \"Enkö minä sanonut teille: \'Älkää tehkö pahoin nuorukaista vastaan!\' Mutta te ette kuulleet minua; katsokaa, nyt kostetaan hänen verensä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Mutta he eivät tienneet, että Joosef ymmärsi heitä, sillä hän puhui heille tulkin kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Ja hän kääntyi pois heistä ja itki. Sitten hän kääntyi taas heihin päin ja puhui heidän kanssaan. Ja hän otti heidän joukostaan Simeonin ja vangitutti hänet heidän nähtensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Ja Joosef käski täyttää heidän säkkinsä viljalla ja panna jokaisen rahat takaisin hänen säkkiinsä sekä antaa heille evästä matkalle. Ja heille tehtiin niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Ja he sälyttivät viljansa aasien selkään ja lähtivät sieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Kun sitten eräs heistä yöpaikassa avasi säkkinsä syöttääkseen aasiansa, huomasi hän rahansa säkin suussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Hän sanoi veljilleen: \"Minulle on annettu rahani takaisin; katso, se on minun säkissäni\". Silloin heidän sydämensä vavahti, ja he katsoivat säikähtyneinä toisiinsa sanoen: \"Mitä Jumala on meille tehnyt?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Tultuansa isänsä Jaakobin luo Kanaanin maahan he ilmoittivat hänelle kaikki, mitä heille oli tapahtunut, ja sanoivat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '\"Mies, joka on sen maan valtiaana, puhutteli meitä ankarasti ja kohteli meitä, niinkuin olisimme olleet maata vakoilemassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Mutta me sanoimme hänelle: \'Olemme rehellisiä miehiä emmekä mitään vakoojia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'meitä on kaksitoista veljestä, saman isän poikia; yhtä ei enää ole, ja nuorin on nyt kotona isämme luona Kanaanin maassa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Mutta mies, sen maan valtias, sanoi meille: \'Siitä minä saan tietää, oletteko rehellisiä miehiä: jättäkää yksi veljistänne minun luokseni; ottakaa sitten viljaa perheittenne nälänhätään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Ja menkää ja tuokaa nuorin veljenne luokseni, saadakseni tietää, ettette ole vakoojia, vaan rehellisiä miehiä. Sitten minä annan teille veljenne takaisin, ja te saatte vapaasti liikkua maassa\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Kun he sitten tyhjensivät säkkinsä, niin katso, kunkin rahakukkaro oli hänen säkissään; ja nähdessään rahakukkaronsa he sekä heidän isänsä peljästyivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Ja heidän isänsä Jaakob sanoi heille: \"Te teette minut lapsettomaksi; Joosefia ei enää ole, Simeonia ei enää ole, ja Benjamininkin te tahdotte viedä minulta; kaikki tämä kohtaa minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Ruuben vastasi isälleen sanoen: \"Saat surmata minun molemmat poikani, jos en tuo häntä sinulle takaisin; anna hänet minun huostaani, niin minä tuon hänet sinulle takaisin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Mutta hän sanoi: \"Ei minun poikani saa lähteä teidän kanssanne, sillä hänen veljensä on kuollut, ja hän on yksin jäljellä; jos onnettomuus kohtaa häntä matkalla, jolle aiotte lähteä, niin te saatatte minun harmaat hapseni vaipumaan murheella tuonelaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Mutta nälänhätä oli maassa kova.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Ja kun he olivat syöneet loppuun sen viljan, jonka olivat tuoneet Egyptistä, sanoi heidän isänsä heille: \"Menkää jälleen ostamaan meille vähän elintarpeita\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Juuda vastasi hänelle sanoen: \"Se mies teroitti meille teroittamalla: \'Ette saa tulla minun kasvojeni eteen, ellei veljenne ole teidän kanssanne\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Jos annat veljemme seurata meidän mukanamme, niin me lähdemme ostamaan sinulle elintarpeita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Mutta jos et anna, niin emme lähde; sillä se mies sanoi meille: \'Ette saa tulla minun kasvojeni eteen, ellei veljenne ole teidän kanssanne\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Israel sanoi: \"Minkätähden teitte niin pahasti minua kohtaan, että ilmaisitte tuolle miehelle teillä olevan vielä veljen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'He vastasivat: \"Mies kyseli tuiki tarkasti meitä ja meidän sukuamme, sanoen: \'Elääkö isänne vielä? Onko teillä vielä veljeä?\' Silloin me ilmoitimme hänelle, niinkuin asia on. Saatoimmeko tietää, että hän sanoisi: \'Tuokaa tänne veljenne\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Ja Juuda sanoi isällensä Israelille: \"Anna nuorukaisen seurata minun mukanani, niin me nousemme ja lähdemme matkalle, että jäisimme eloon, sekä me että sinä ja vaimomme ja lapsemme, emmekä kuolisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Minä vastaan hänestä; minun kädestäni saat vaatia hänet. Jos en tuo häntä takaisin sinun luoksesi ja aseta häntä eteesi, niin minä olen syyllinen sinun edessäsi kaiken elinaikani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Totisesti, jos emme olisi näin vitkastelleet, niin olisimme jo kaksikin kertaa voineet olla sieltä kotona.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Silloin heidän isänsä Israel sanoi heille: \"Jos niin on, tehkää ainakin tämä: ottakaa säkkeihinne maan parhaimpia tuotteita ja viekää ne sille miehelle lahjaksi: vähän balsamia ja vähän hunajaa, kumihartsia ja hajupihkaa, pähkinöitä ja manteleita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Ja ottakaa mukaanne kaksinkertainen raha, niin että viette takaisin sen rahan, joka palautettiin säkkienne suussa. Ehkä se oli erehdys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Ottakaa sitten mukaanne myöskin veljenne ja nouskaa ja menkää jälleen sen miehen luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Jumala, Kaikkivaltias, suokoon, että se mies tekisi teille laupeuden ja antaisi toisen veljenne sekä Benjaminin palata kotiin teidän kanssanne. Mutta jos tulen lapsettomaksi, niin tulen lapsettomaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Niin miehet ottivat mukaansa lahjan ja kaksinkertaisen rahan sekä myöskin Benjaminin ja nousivat ja menivät Egyptiin; ja he astuivat Joosefin eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Kun Joosef näki Benjaminin heidän seurassaan, sanoi hän huoneenhaltijalleen: \"Vie nämä miehet sisään; teurasta teuras ja valmista se, sillä miehet saavat syödä päivällistä minun kanssani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Ja mies teki, niinkuin Joosef oli käskenyt, ja vei miehet Joosefin taloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Mutta miehet pelkäsivät, kun heitä vietiin Joosefin taloon, arvellen: \"Sen rahan tähden, joka viime kerralla tuli takaisin meidän säkeissämme, ne nyt vievät meitä tänne hyökätäkseen ja karatakseen meidän kimppuumme, ottaakseen meidät orjiksi ja anastaakseen aasimme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Niin he menivät Joosefin huoneenhaltijan luo ja puhuttelivat häntä talon ovella');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'ja sanoivat: \"Oi kuule, herra, me olemme kerran ennen käyneet täällä ostamassa elintarpeita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'ja kun me tulimme yöpaikkaan ja avasimme säkkimme, niin katso, jokaisen raha oli hänen säkkinsä suussa täysipainoisena; olemme nyt tuoneet ne mukanamme takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Ja olemme tuoneet mukanamme toisenkin rahan ostaaksemme viljaa elatukseksemme. Emme tiedä, kuka on pannut meidän rahamme säkkeihimme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Hän vastasi: \"Olkaa rauhassa, älkää peljätkö. Teidän Jumalanne ja teidän isänne Jumala on antanut teidän löytää aarteen säkeistänne. Teidän rahanne minä olen saanut.\" Ja hän toi heidän luokseen Simeonin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Ja hän vei miehet Joosefin taloon ja antoi heille vettä jalkain pesemiseksi ja heidän aaseilleen rehua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'He laittoivat lahjansa järjestykseen siksi, kunnes Joosef tulisi päivälliselle; sillä he olivat kuulleet, että saisivat aterioida siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Kun Joosef oli tullut kotiin, veivät he hänelle huoneeseen lahjat, jotka heillä oli mukanaan, ja kumartuivat maahan hänen edessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Hän tervehti heitä ja kysyi: \"Kuinka voi teidän vanha isänne, josta puhuitte? Vieläkö hän elää?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'He vastasivat: \"Palvelijasi, meidän isämme, voi hyvin; hän elää vielä\". Ja he kumartuivat ja heittäytyivät maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Ja hän nosti silmänsä ja näki veljensä Benjaminin, äitinsä pojan, ja kysyi: \"Onko tämä teidän nuorin veljenne, josta puhuitte?\" Sitten hän sanoi: \"Jumala olkoon sinulle, poikani, armollinen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Mutta silloin Joosef keskeytti äkkiä puheensa, sillä nähdessään veljensä hän tuli sydämessään liikutetuksi ja etsi tilaisuutta itkeäkseen; niin hän meni sisähuoneeseen ja itki siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Senjälkeen hän pestyään kasvonsa tuli ulos, hillitsi itsensä ja käski: \"Tarjotkaa ruokaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Ja tarjottiin erikseen hänelle ja erikseen heille ja erikseen egyptiläisille, jotka aterioivat hänen kanssaan; egyptiläiset näet eivät saata syödä yhdessä hebrealaisten kanssa, sillä se on egyptiläisille kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'He istuivat vastapäätä häntä iän mukaan, esikoinen ensimmäisenä ja nuorin viimeisenä; ja ihmetellen miehet katselivat toisiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Ja hän antoi kantaa omasta pöydästään ruokia heille, ja Benjaminin annos oli viisi kertaa suurempi kuin kaikkien muiden. Ja he joivat hänen kanssaan ja juopuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Sen jälkeen Joosef käski huoneenhaltijaansa sanoen: \"Täytä miesten säkit viljalla, niin paljon kuin he voivat kuljettaa, ja pane itsekunkin raha hänen säkkinsä suuhun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Ja nuorimman säkin suuhun pane minun maljani, tuo hopeamalja, ynnä hänen viljarahansa.\" Ja hän teki, niinkuin Joosef käski.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Aamulla päivän valjetessa miehet saivat aaseinensa lähteä matkalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Mutta kun he olivat ehtineet vähän matkaa kaupungin ulkopuolelle, sanoi Joosef huoneenhaltijalleen: \"Nouse ja aja miehiä takaa, ja kun saavutat heidät, sano heille: \'Minkätähden olette palkinneet hyvän pahalla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Onhan se juuri se, josta isäntäni juo ja josta hän salaisia tiedustelee. Te olette pahoin tehneet menetellessänne näin.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Kun hän sitten saavutti heidät, puhui hän heille nämä sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'He vastasivat hänelle: \"Minkätähden herramme puhuu näin? Pois se, että palvelijasi tekisivät niin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Katso, rahan, jonka löysimme säkkiemme suusta, me olemme tuoneet takaisin sinulle Kanaanin maasta; kuinka siis olisimme varastaneet hopeata tai kultaa herrasi talosta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Se palvelijoistasi, jolta se löydetään, kuolkoon; ja me muut tulemme herramme orjiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Hän vastasi: \"Olkoon niin, kuin olette puhuneet; se, jolta se löydetään, olkoon minun orjani. Mutta te muut pääsette vapaiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Ja he laskivat nopeasti säkkinsä maahan, ja jokainen avasi säkkinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Ja hän etsi, alkaen vanhimmasta ja lopettaen nuorimpaan, ja malja löytyi Benjaminin säkistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Silloin he repäisivät vaatteensa, kuormasivat kukin tavaransa aasinsa selkään ja palasivat kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Ja Juuda meni veljinensä Joosefin taloon, jossa tämä vielä oli, ja he lankesivat maahan hänen eteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Silloin Joosef sanoi heille: \"Mitä olettekaan tehneet! Ettekö tienneet, että minun kaltaiseni mies saa salatut ilmi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Juuda vastasi: \"Mitä sanoisimmekaan herralleni, mitä puhuisimme ja millä puolustautuisimme! Jumala on paljastanut palvelijaisi syyllisyyden. Katso, me olemme herrani orjat, niin hyvin me muut kuin se, jolta malja löytyi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Hän sanoi: \"Pois se, että minä tekisin niin! Se, jolta malja löytyi, olkoon minun orjani, mutta te muut menkää rauhassa kotiin isänne luo.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Silloin Juuda astui hänen eteensä ja sanoi: \"Oi herrani, salli palvelijasi puhua sananen herrani kuullen, älköönkä vihasi syttykö palvelijaasi kohtaan, sillä sinä olet niinkuin itse farao!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Herrani kysyi palvelijoiltaan sanoen: \'Onko teillä isää tai veljeä?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Me vastasimme herralleni: \'Meillä on kotona vanha isä ja veli, joka on syntynyt hänen vanhoilla päivillänsä ja on vielä nuori; mutta tämän veli on kuollut, ja niin hän on jäänyt yksin äidistänsä, ja hänen isänsä rakastaa häntä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Niin sinä sanoit palvelijoillesi: \'Tuokaa hänet tänne minun luokseni, että silmäni saisivat katsella häntä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Me vastasimme herralleni: \'Nuorukainen ei saata jättää isäänsä, sillä jos hän jättäisi isänsä, niin tämä kuolisi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Mutta sinä sanoit palvelijoillesi: \'Jos nuorin veljenne ei tule tänne teidän kanssanne, niin älkää enää näyttäytykö minun kasvojeni edessä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Ja me menimme kotiin palvelijasi, minun isäni, luo ja kerroimme hänelle herrani sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Niin isämme sanoi: \'Menkää jälleen ostamaan meille vähän elintarpeita\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Me sanoimme: \'Emme voi lähteä sinne; ainoastaan jos nuorin veljemme seuraa mukanamme, me lähdemme, sillä me emme voi näyttäytyä sen miehen kasvojen edessä, jollei nuorin veljemme ole mukanamme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Niin palvelijasi, minun isäni, sanoi meille: \'Tiedättehän itse, että vaimoni synnytti minulle kaksi poikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Toinen lähti pois luotani, ja minä sanoin: Varmaan hänet on raadeltu kuoliaaksi, enkä minä ole häntä siitä päivin nähnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Jos te nyt viette minulta tämänkin ja jos onnettomuus kohtaa häntä, niin te saatatte minun harmaat hapseni vaipumaan tuskalla tuonelaan.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Jos minä siis tulisin kotiin palvelijasi, isäni, luo eikä meillä olisi mukanamme nuorukaista, johon hän on kaikesta sielustaan kiintynyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'niin hän nähdessään, ettei nuorukainen ole kanssamme, kuolisi, ja me, sinun palvelijasi, saattaisimme palvelijasi, isämme, harmaat hapset vaipumaan murheella tuonelaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Sillä palvelijasi on luvannut isälleen vastata nuorukaisesta ja sanonut: \'Jos en tuo häntä takaisin luoksesi, niin minä olen syyllinen isäni edessä kaiken elinaikani\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Ja jääköön siis palvelijasi herralleni orjaksi nuorukaisen sijaan, ja nuorukainen menköön kotiin veljiensä kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Sillä kuinka minä voisin mennä kotiin isäni luo, jollei nuorukainen olisi kanssani? En voisi nähdä sitä surkeutta, joka tulisi isäni osaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Silloin Joosef ei voinut kauemmin hillitä itseään kaikkien niiden nähden, jotka seisoivat hänen ympärillään. Hän huusi: \"Antakaa kaikkien mennä pois minun luotani!\" Niin ei ollut ketään saapuvilla, kun Joosef ilmaisi itsensä veljilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Ja hän purskahti ääneensä itkemään, niin että egyptiläiset ja faraon hoviväki sen kuulivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Ja Joosef sanoi veljilleen: \"Minä olen Joosef. Vieläkö minun isäni elää?\" Mutta hänen veljensä eivät voineet vastata hänelle, niin hämmästyksissään he olivat hänen edessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Mutta Joosef sanoi veljilleen: \"Tulkaa tänne luokseni\". Ja he tulivat. Niin hän sanoi: \"Minä olen Joosef, teidän veljenne, jonka myitte Egyptiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Mutta älkää nyt olko murheissanne älkääkä pahoitelko sitä, että olette myyneet minut tänne, sillä Jumala on minut lähettänyt teidän edellänne pitääkseen teidät hengissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Kaksi vuotta on nyt nälänhätä ollut maassa, ja vielä on jäljellä viisi vuotta, joina ei kynnetä eikä eloa korjata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Niin Jumala lähetti minut teidän edellänne säilyttääkseen teille jälkeläisiä maan päällä ja pitääkseen teidät hengissä, pelastukseksi monille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Ette siis te ole lähettäneet minua tänne, vaan Jumala; hän asetti minut faraon neuvonantajaksi ja koko hänen hovinsa herraksi ja koko Egyptin maan valtiaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Menkää, rientäkää minun isäni tykö ja sanokaa hänelle: \'Näin sanoo poikasi Joosef: Jumala on asettanut minut koko Egyptin herraksi, tule luokseni, älä viivyttele!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Sinä saat asettua Goosenin maakuntaan ja olla minun läheisyydessäni, sinä ja sinun lapsesi ja lastesi lapset, pikkukarjasi ja raavaskarjasi, kaikki, mitä sinulla on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Minä elätän sinua siellä-vielä on näet viisi nälkävuotta-niin ettet sinä eikä sinun perheesi eikä kukaan omaisistasi ole sortuva puutteeseen.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Te näette omin silmin, ja myöskin veljeni Benjamin näkee, että minä itse teille puhun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Kertokaa siis isällenne kaikesta siitä kunniasta, joka on tullut minun osakseni Egyptissä, ja kaikesta, mitä olette nähneet, ja rientäkää ja tuokaa isäni tänne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Ja hän lankesi veljensä Benjaminin kaulaan ja itki, ja myöskin Benjamin itki hänen kaulassaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Ja hän suuteli kaikkia veljiään ja itki heidän rinnoillaan. Senjälkeen hänen veljensä puhelivat hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Kun sanoma siitä, että Joosefin veljet olivat saapuneet, kuului faraon hoviin, oli se faraon ja kaikkien hänen palvelijainsa mieleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Ja farao sanoi Joosefille: \"Sano veljillesi: \'Tehkää näin: sälyttäkää kuormat juhtainne selkään ja lähtekää kotiin Kanaanin maahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'ottakaa isänne ja perheenne ja tulkaa minun luokseni, niin minä annan teille parasta, mitä Egyptissä on, ja te saatte syödä maan lihavuudesta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Ja näin sinun on käskettävä heitä: \'Tehkää näin: ottakaa itsellenne vaunuja Egyptin maasta lapsianne ja vaimojanne varten ja tuokaa isänne ja tulkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Älkää surko taloustavaroitanne, sillä mitä parasta on koko Egyptin maassa, se on oleva teidän omanne.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Israelin pojat tekivät niin, ja Joosef antoi heille vaunuja faraon käskyn mukaan sekä evästä matkaa varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Hän antoi kullekin heistä juhlapuvun, mutta Benjaminille hän antoi kolmesataa hopeasekeliä sekä viisi juhlapukua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Samoin hän lähetti isälleen lahjaksi kymmenen aasia, jotka olivat kuormitetut Egyptin parhaimmilla tavaroilla, ja kymmenen aasintammaa, jotka kantoivat viljaa ja leipää sekä eväitä hänen isälleen matkaa varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Sitten hän päästi veljensä menemään ja sanoi heille: \"Älkää riidelkö matkalla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Niin he lähtivät Egyptistä ja tulivat isänsä Jaakobin luo Kanaanin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Ja he kertoivat hänelle ja sanoivat: \"Joosef on vielä elossa ja on koko Egyptin maan valtias\". Mutta hänen sydämensä pysyi kylmänä, sillä hän ei uskonut heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Niin he kertoivat hänelle kaiken, mitä Joosef oli heille puhunut. Ja kun hän näki vaunut, jotka Joosef oli lähettänyt häntä tuomaan, niin elpyi heidän isänsä Jaakobin henki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Ja Israel sanoi: \"Nyt on minulla kyllin; poikani Joosef elää vielä, minä menen häntä katsomaan, ennenkuin kuolen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Niin Israel lähti matkalle mukanaan kaikki, mitä hänellä oli. Ja kun hän saapui Beersebaan, uhrasi hän teurasuhreja isänsä Iisakin Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Ja Jumala puhui Israelille näyssä yöllä; hän sanoi: \"Jaakob, Jaakob!\" Tämä vastasi: \"Tässä olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Niin hän sanoi: \"Minä olen Jumala, sinun isäsi Jumala; älä pelkää mennä Egyptiin, sillä minä teen sinut siellä suureksi kansaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Minä menen sinun kanssasi Egyptiin, ja minä myös johdatan sinut sieltä takaisin. Ja Joosefin käsi on sulkeva sinun silmäsi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Ja Jaakob lähti Beersebasta, ja Israelin pojat nostivat isänsä Jaakobin, lapsensa ja vaimonsa vaunuihin, jotka farao oli lähettänyt häntä noutamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Ja he ottivat karjansa ja tavaransa, jotka he olivat hankkineet Kanaanin maassa, ja tulivat niin Egyptiin, Jaakob ynnä kaikki hänen jälkeläisensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Poikansa ja poikiensa pojat, tyttärensä ja poikiensa tyttäret, kaikki jälkeläisensä, hän vei mukanaan Egyptiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Nämä ovat Israelin lasten nimet, niiden, jotka tulivat Egyptiin: Jaakob ja hänen poikansa. Jaakobin esikoinen oli Ruuben.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Ruubenin pojat olivat Hanok, Pallu, Hesron ja Karmi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Simeonin pojat olivat Jemuel, Jaamin, Oohad, Jaakin, Soohar ja Saul, kanaanilaisen vaimon poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Leevin pojat olivat Geerson, Kehat ja Merari.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Juudan pojat olivat Eer, Oonan, Seela, Peres ja Serah; mutta Eer ja Oonan kuolivat Kanaanin maassa. Pereksen pojat olivat Hesron ja Haamul.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Isaskarin pojat olivat Toola, Puvva, Joob ja Simron.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Sebulonin pojat olivat Sered, Eelon ja Jahleel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Nämä olivat Leean pojat; ne hän synnytti Jaakobille Mesopotamiassa sekä tyttären Diinan. Näitä Jaakobin poikia ja tyttäriä oli kaikkiaan kolmekymmentä kolme henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Gaadin pojat olivat Sifjon ja Haggi, Suuni ja Esbon, Eeri ja Arodi ja Areli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Asserin pojat olivat Jimna, Jisva, Jisvi ja Beria; heidän sisarensa oli Serah. Berian pojat olivat Heber ja Malkiel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Nämä olivat Silpan lapset, hänen, jonka Laaban antoi tyttärellensä Leealle, ja hän synnytti ne Jaakobille, kuusitoista henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Raakelin, Jaakobin vaimon, pojat olivat Joosef ja Benjamin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Ja pojat, jotka syntyivät Joosefille Egyptin maassa, olivat Manasse ja Efraim; nämä synnytti hänelle Aasenat, Oonin papin Poti-Feran tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Benjaminin pojat olivat Bela, Beker ja Asbel, Geera ja Naaman, Eehi ja Roos, Muppim ja Huppim ja Ard.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Nämä olivat Raakelin pojat, jotka syntyivät Jaakobille, kaikkiaan neljätoista henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Daanin poika oli Husim.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Naftalin pojat olivat Jahseel, Guuni, Jeeser ja Sillem.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Nämä olivat Bilhan pojat, hänen, jonka Laaban antoi tyttärellensä Raakelille, ja hän synnytti ne Jaakobille, kaikkiaan seitsemän henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Kaikkiaan oli niitä, jotka Jaakobin kanssa siirtyivät Egyptiin ja olivat lähteneet hänen kupeistansa, paitsi Jaakobin miniöitä, yhteensä kuusikymmentä kuusi henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Ja Joosefin poikia, jotka syntyivät hänelle Egyptissä, oli kaksi. Jaakobin perheen jäseniä, jotka siirtyivät Egyptiin, oli kaikkiaan seitsemänkymmentä henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Ja hän lähetti Juudan edellänsä Joosefin luo ilmoittamaan hänelle tulostaan Gooseniin. Niin he tulivat Goosenin maakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Ja Joosef valjastutti vaununsa ja meni isäänsä Israelia vastaan Gooseniin. Ja kun hän saapui hänen eteensä, lankesi hän hänen kaulaansa ja itki kauan hänen kaulassaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Ja Israel sanoi Joosefille: \"Nyt minä kuolen mielelläni, kun olen nähnyt sinun kasvosi ja tiedän, että sinä vielä elät\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Sen jälkeen Joosef sanoi veljilleen ja isänsä perheelle: \"Minä menen ilmoittamaan faraolle ja sanon hänelle: \'Minun veljeni ja minun isäni perhe, jotka ovat olleet Kanaanin maassa, ovat saapuneet luokseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Ja nämä miehet ovat paimenia, sillä he hoitavat karjaa; ja he ovat tuoneet mukanaan lampaansa, karjansa ja kaiken muun omaisuutensa.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Kun siis farao kutsuu teidät eteensä ja kysyy: \'Mikä teidän ammattinne on?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'niin vastatkaa: \'Me, sinun palvelijasi, olemme hoitaneet karjaa nuoruudestamme tähän asti, me niinkuin meidän isämmekin\' -että saisitte asettua Goosenin maakuntaan. Sillä kaikki paimenet ovat egyptiläisille kauhistus.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Ja Joosef meni ja ilmoitti faraolle, sanoen: \"Minun isäni ja veljeni ovat pikkukarjoineen ja raavaskarjoineen, kaikkine omaisuuksineen, tulleet Kanaanin maasta, ja katso, he ovat Goosenin maakunnassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Ja hän oli ottanut mukaansa veljiensä joukosta viisi miestä; ne hän toi faraon eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Niin farao kysyi hänen veljiltänsä: \"Mikä on teidän ammattinne?\" He vastasivat faraolle: \"Me, sinun palvelijasi, olemme paimenia, me niinkuin isämmekin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Ja he sanoivat vielä faraolle: \"Me olemme tulleet asuaksemme jonkun aikaa tässä maassa; sillä palvelijoillasi ei ollut laidunta karjalleen, koska kova nälänhätä on Kanaanin maassa. Suo siis palvelijaisi asettua Goosenin maakuntaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Niin farao sanoi Joosefille: \"Isäsi ja veljesi ovat tulleet sinun luoksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Egyptin maa on avoinna sinun edessäsi; sijoita isäsi ja veljesi maan parhaaseen osaan. Asukoot Goosenin maakunnassa; ja jos tiedät heidän joukossaan olevan kelvollisia miehiä, niin aseta heidät minun karjani päällysmiehiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Senjälkeen Joosef toi isänsä Jaakobin sisään ja esitti hänet faraolle. Ja Jaakob toivotti faraolle siunausta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Niin farao kysyi Jaakobilta: \"Kuinka monta ikävuotta sinulla on?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jaakob vastasi faraolle: \"Minun vaellusaikani on kestänyt sata kolmekymmentä vuotta. Vähät ja pahat ovat olleet minun elinvuosieni päivät eivätkä ole saavuttaneet sitä elinvuosien määrää, mikä isilläni oli vaelluksensa aikana.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Ja Jaakob toivotti faraolle siunausta ja lähti hänen luotaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Ja Joosef sijoitti isänsä ja veljensä Egyptin maahan ja antoi heille maaomaisuutta maan parhaasta osasta, Ramseksen maakunnasta, niinkuin farao oli hänen käskenyt tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Ja Joosef elätti isäänsä ja veljiänsä ja koko isänsä perhettä antamalla jokaiselle elatusta vaimojen ja lasten luvun mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Mutta ei missään koko maassa ollut leipää; sillä nälänhätä oli hyvin kova, niin että Egyptin maa ja Kanaanin maa olivat nääntymässä nälkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Ja viljalla, jota ostettiin, Joosef kokosi kaiken rahan, mitä oli Egyptin maassa ja Kanaanin maassa; ja Joosef vei rahat faraon hoviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Kun raha oli loppunut Egyptin maasta ja Kanaanin maasta, tulivat kaikki egyptiläiset Joosefin luo, sanoen: \"Anna meille leipää. Miksi me kuolisimme sinun silmiesi edessä? Sillä raha on loppunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Joosef vastasi: \"Tuokaa tänne karjanne. Minä annan teille leipää karjastanne, jos rahanne on loppunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Ja he toivat Joosefille karjansa, ja Joosef antoi heille leipää hevosista, lampaista, raavaskarjasta ja aaseista. Niin hän sen vuoden elätti heitä leivällä kaiken heidän karjansa hinnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Niin kului se vuosi. Seuraavana vuonna he tulivat taas hänen luoksensa ja sanoivat hänelle: \"Emme tahdo salata herraltamme, että raha on lopussa, ja myöskin eläimemme ovat joutuneet herramme omiksi; meillä ei ole muuta jäljellä annettavana herrallemme kuin ruumiimme ja peltomme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Miksi me menehtyisimme sinun silmiesi edessä, sekä me itse että meidän peltomme? Osta meidät ja peltomme leivällä, niin me tulemme peltoinemme faraon orjiksi. Anna meille siementä, että eläisimme emmekä kuolisi eivätkä peltomme joutuisi autioiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Niin Joosef osti faraolle kaikki Egyptin pellot; sillä egyptiläiset myivät jokainen vainionsa, koska nälkä ahdisti heitä. Niin joutui maa faraon omaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Ja hän siirsi kansan kaupunkeihin, Egyptin toisesta äärestä toiseen saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Ainoastaan pappien peltoja hän ei ostanut; sillä papeilla oli määrätyt tulot faraolta ja he elivät niistä määrätyistä tuloistaan, jotka he faraolta saivat. Sentähden heidän ei tarvinnut myydä peltojansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Ja Joosef sanoi kansalle: \"Katso, minä olen nyt ostanut teidät ja teidän peltonne faraolle; katso, tässä on teille siementä, kylväkää peltonne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Mutta sadosta teidän on annettava viides osa faraolle; mutta neljä viidettä osaa jääköön teille pellon siemeneksi sekä ravinnoksi itsellenne ja niille, jotka talossanne ovat, sekä elatukseksi vaimoillenne ja lapsillenne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'He vastasivat: \"Sinä olet pitänyt meidät hengissä; suo meidän vain saada armo herramme silmien edessä, niin olemme faraon orjia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Niin Joosef teki sen säädökseksi, joka vielä tänäkin päivänä on voimassa Egyptin pelloista, että faraolle on annettava viides osa. Ainoastaan pappien pellot eivät joutuneet faraon omiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Niin Israel jäi asumaan Egyptiin, Goosenin maakuntaan; he asettuivat sinne ja olivat hedelmällisiä ja lisääntyivät suuresti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Ja Jaakob eli Egyptin maassa seitsemäntoista vuotta, ja koko hänen elinaikansa oli sata neljäkymmentä seitsemän vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Kun lähestyi aika, jolloin Israelin oli kuoltava, kutsui hän poikansa Joosefin ja sanoi hänelle: \"Jos olen saanut armon sinun silmiesi edessä, niin pane nyt kätesi minun kupeeni alle ja osoita minulle laupeus ja uskollisuus: älä hautaa minua Egyptiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'sillä minä tahdon levätä isieni luona; vie siis minut Egyptistä ja hautaa minut heidän hautaansa\". Hän vastasi: \"Minä teen, niinkuin sanot\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Hän sanoi: \"Vanno se minulle\". Ja hän vannoi hänelle. Silloin Israel rukoili, kumartuneena vuoteensa päänalaista vasten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Tämän jälkeen tuotiin Joosefille sana: \"Katso, isäsi on sairaana\". Ja hän otti mukaansa molemmat poikansa, Manassen ja Efraimin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Ja Jaakobille ilmoitettiin ja sanottiin: \"Katso, poikasi Joosef on tullut sinun luoksesi\". Niin Israel kokosi voimansa ja nousi istumaan vuoteessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Ja Jaakob sanoi Joosefille: \"Jumala, Kaikkivaltias, ilmestyi minulle Luusissa Kanaanin maassa ja siunasi minut');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'ja sanoi minulle: \'Katso, minä teen sinut hedelmälliseksi ja annan sinun lisääntyä, annan tulla sinusta suuren kansojen joukon, ja minä annan sinun jälkeläisillesi tämän maan ikuiseksi perintömaaksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Kaksi poikaasi, jotka ovat sinulle syntyneet Egyptin maassa, ennenkuin minä tulin luoksesi Egyptiin, olkoot minun omani; Efraim ja Manasse olkoot minun omani niinkuin Ruuben ja Simeon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Mutta ne lapsesi, jotka ovat syntyneet sinulle heidän jälkeensä, olkoot sinun; nimitettäköön heitä veljiensä nimellä heidän perintöosassaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Palatessani Mesopotamiasta kuoli minulta Raakel matkalla Kanaanissa, kun vielä oli jonkun verran matkaa Efrataan; ja minä hautasin hänet siellä Efratan\" -se on Beetlehemin-\"tien varteen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Kun nyt Israel huomasi Joosefin pojat, kysyi hän: \"Keitä nämä ovat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Joosef vastasi isälleen: \"Ne ovat minun poikani, jotka Jumala on minulle täällä antanut\". Hän sanoi: \"Tuo heidät minun luokseni siunatakseni heidät\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Mutta Israelin silmät olivat vanhuudesta hämärät, niin ettei hän voinut nähdä. Niin Joosef toi heidät hänen luokseen, ja hän suuteli heitä ja syleili heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Ja Israel sanoi Joosefille: \"En olisi uskonut saavani nähdä sinun kasvojasi; ja katso, Jumala on suonut minun nähdä sinun jälkeläisiäsikin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Ja Joosef otti heidät pois hänen polviltansa ja kumartui maahan kasvoilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Sitten Joosef tarttui heihin molempiin, Efraimiin oikealla kädellänsä, vasemmalla Israelista, ja Manasseen vasemmalla kädellänsä, oikealla Israelista, ja toi heidät niin hänen eteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Mutta Israel ojensi oikean kätensä ja laski sen Efraimin pään päälle, vaikka tämä oli nuorempi, ja vasemman kätensä Manassen pään päälle; hän pani siis kätensä ristikkäin, sillä Manasse oli esikoinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Ja hän siunasi Joosefin sanoen: \"Jumala, jonka kasvojen edessä minun isäni Aabraham ja Iisak ovat vaeltaneet, Jumala, joka on minua kainnut syntymästäni hamaan tähän päivään asti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'enkeli, joka on minut pelastanut kaikesta pahasta, siunatkoon näitä nuorukaisia; heitä mainittaessa mainittakoon minun nimeni ja minun isieni Aabrahamin ja Iisakin nimi, ja he lisääntykööt suuresti keskellä maata\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Mutta kun Joosef huomasi, että hänen isänsä laski oikean kätensä Efraimin pään päälle, pani hän sen pahakseen ja tarttui isänsä käteen siirtääkseen sen Efraimin pään päältä Manassen pään päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Ja Joosef sanoi isälleen: \"Ei niin, isäni, sillä tämä on esikoinen; pane oikea kätesi hänen päänsä päälle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Mutta hänen isänsä epäsi ja sanoi: \"Kyllä tiedän, poikani, kyllä tiedän; hänestäkin on tuleva kansa, hänkin on tuleva suureksi, mutta hänen nuorempi veljensä on kuitenkin tuleva häntä suuremmaksi, ja hänen jälkeläisistään on tuleva kansan paljous\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Ja niin hän siunasi heidät sinä päivänä, sanoen: \"Sinun nimelläsi siunataan Israelissa, sanotaan: Jumala tehköön sinut Efraimin ja Manassen kaltaiseksi\". Niin hän asetti Efraimin Manassen edelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Ja Israel sanoi Joosefille: \"Katso, minä kuolen, mutta Jumala on teidän kanssanne ja vie teidät takaisin isienne maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Ja lisäksi siihen, minkä veljesi saavat, minä annan sinulle vuorenharjanteen, jonka olen miekallani ja jousellani ottanut amorilaisilta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Sitten Jaakob kutsui poikansa ja sanoi: \"Kokoontukaa, niin minä ilmoitan teille, mitä teille päivien lopulla tapahtuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Tulkaa kokoon ja kuulkaa, Jaakobin pojat, kuulkaa isäänne Israelia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruuben, sinä olet minun esikoiseni, minun voimani ja minun miehuuteni ensimmäinen, ensi sijalla arvossa, ensi sijalla vallassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Mutta sinä kuohahdat kuin vesi, et pysy ensi sijalla, sillä sinä nousit isäsi leposijalle; silloin sinä sen saastutit. Niin, hän nousi vuoteeseeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon ja Leevi, veljekset, heidän aseensa ovat väkivallan aseet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'Heidän neuvoonsa ei suostu minun sieluni, heidän seuraansa ei yhdy minun sydämeni; sillä vihassaan he murhasivat miehiä, omavaltaisuudessaan he silpoivat härkiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Kirottu olkoon heidän vihansa, sillä se on raju, heidän kiukkunsa, sillä se on julma. Minä jakelen heidät Jaakobin sekaan ja hajotan heidät Israelin sekaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juuda, sinua sinun veljesi ylistävät; sinun kätesi on vihollistesi niskassa, sinua kumartavat isäsi pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Juuda on nuori leijona; saaliilta olet, poikani, noussut. Hän on asettunut makaamaan, hän lepää kuin leijona, kuin naarasleijona-kuka uskaltaa häntä häiritä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Ei siirry valtikka pois Juudalta eikä hallitsijansauva hänen polviensa välistä, kunnes tulee hän, jonka se on ja jota kansat tottelevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Hän sitoo aasinsa viinipuuhun, viiniköynnökseen aasinsa varsan; hän huuhtoo vaatteensa viinissä; viittansa rypäleen veressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Hänen silmänsä ovat viinistä sameat, hänen hampaansa valkeat maidosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon asuu meren rannalla, laivojen rannikolla, hänen sivunsa on Siidoniin päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isaskar on luiseva aasi, joka loikoilee karjatarhojen välissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Hän huomasi lepopaikkansa suloiseksi ja maan ihanaksi; niin hän taivutti olkansa taakan alle ja joutui työveroa tekemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Daan hankkii oikeutta kansalleen, hänkin yhtenä Israelin sukukunnista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Daan on käärmeenä tiellä, on polulla kyynä, joka puree hevosta vuohiseen, niin että ratsastaja syöksyy selin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Sinulta minä odotan pelastusta, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gaadia ahdistavat rosvojoukot, mutta hän itse ahdistaa heitä heidän kintereillään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Asserista tulee lihavuus, hänen leipänsä, hän tarjoaa kuninkaan herkkuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naftali on nopea peura; hän antaa kauniita sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Joosef on nuori hedelmäpuu, nuori hedelmäpuu lähteen reunalla; sen oksat ulottuvat yli muurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Jousimiehet hätyyttävät häntä, ampuvat ja ahdistavat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Mutta hänen jousensa pysyy lujana, ja hänen käsivartensa ovat notkeat Jaakobin Väkevän avulla, kaitsijan, Israelin kallion,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'isäsi Jumalan, avulla, joka sinua auttakoon, Kaikkivaltiaan avulla, joka sinua siunatkoon, antakoon siunauksia taivaasta ylhäältä, siunauksia syvyydestä alhaalta, siunauksia nisistä ja kohdusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Sinun isäsi siunaukset kohoavat yli minun vanhempaini siunausten, yli ikuisten kukkulain ihanuuden. Ne laskeutukoot Joosefin pään päälle, veljiensä ruhtinaan päälaelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin on raatelevainen susi; aamulla hän syö riistaa, ja illalla hän jakaa saalista.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Nämä ovat kaikki Israelin sukukunnat, luvultaan kaksitoista, ja tämän puhui heille heidän isänsä siunatessaan heidät; hän siunasi jokaisen erikseen erityisellä siunauksella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Ja hän käski heitä ja sanoi heille: \"Minut otetaan pois heimoni tykö; haudatkaa minut isieni viereen, siihen luolaan, joka on heettiläisen Efronin vainiolla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'luolaan, joka on Makpelan vainiolla, itään päin Mamresta Kanaanin maassa, jonka vainion Aabraham osti heettiläiseltä Efronilta perintöhaudakseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Siihen on haudattu Aabraham ja hänen vaimonsa Saara, siihen on haudattu Iisak ja hänen vaimonsa Rebekka, ja siihen minäkin hautasin Leean,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'siihen vainioon, joka luolineen on ostettu heettiläisiltä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Kun Jaakob oli antanut määräyksensä pojilleen, veti hän jalkansa vuoteeseen ja kuoli ja tuli otetuksi heimonsa tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Ja Joosef vaipui isänsä kasvoja vasten, itki siinä kumartuneena hänen ylitsensä ja suuteli häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Sitten Joosef käski lääkäreitä, jotka olivat hänen palveluksessaan, balsamoimaan hänen isänsä, ja lääkärit balsamoivat Israelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Siihen kului neljäkymmentä päivää, sillä niin pitkä aika kuluu balsamoimiseen. Ja egyptiläiset itkivät häntä seitsemänkymmentä päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Sittenkuin hänen muistoksensa vietetty suruaika oli päättynyt, puhui Joosef faraon hoviväelle: \"Jos olen saanut armon teidän silmienne edessä, niin puhukaa minun puolestani faraolle näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Isäni vannotti minua sanoen: \'Katso, minä kuolen, hautaa minut omaan hautaani, jonka olen kaivanut itselleni Kanaanin maassa\'. Anna minun siis nyt mennä hautaamaan isäni; sitten palaan takaisin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Farao vastasi: \"Mene hautaamaan isäsi sen valan mukaan, jonka olet hänelle vannonut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Niin Joosef meni hautaamaan isäänsä, ja hänen kanssaan menivät kaikki faraon palvelijat, hänen hovinsa vanhimmat ja kaikki Egyptin maan vanhimmat');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'sekä koko Joosefin perhe, hänen veljensä ja hänen isänsä perhe; ainoastaan vaimonsa, lapsensa, pikkukarjansa ja raavaskarjansa he jättivät Goosenin maakuntaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'hänen mukanaan meni myös sekä vaunuja että ratsumiehiä. Ja niin heitä oli sangen suuri joukko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Kun he saapuivat Gooren-Aatadiin, joka on Jordanin tuolla puolella, panivat he siellä toimeen ylen suuret ja juhlalliset valittajaiset, ja hän vietti isänsä surujuhlaa seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Ja kun maan asukkaat, kanaanilaiset, näkivät surujuhlan Gooren-Aatadissa, sanoivat he: \"Siellä on egyptiläisillä suuri surujuhla\". Siitä sai paikka nimekseen Aabel-Misraim; se on Jordanin tuolla puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Ja hänen poikansa tekivät hänelle, niinkuin hän oli määrännyt heille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'hänen poikansa veivät hänet Kanaanin maahan ja hautasivat hänet Makpelan vainiolla olevaan luolaan, jonka vainion Aabraham oli ostanut perintöhaudaksi heettiläiseltä Efronilta ja joka oli itään päin Mamresta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Senjälkeen kuin Joosef oli haudannut isänsä, palasi hän Egyptiin, hän ja hänen veljensä sekä kaikki, jotka hänen kanssaan olivat menneet hautaamaan hänen isäänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Mutta kun Joosefin veljet näkivät, että heidän isänsä oli kuollut, ajattelivat he: \"Ehkä Joosef nyt alkaa vainota meitä ja kostaa meille kaiken sen pahan, mitä me olemme hänelle tehneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Niin he lähettivät Joosefille tämän sanan: \"Isäsi käski ennen kuolemaansa ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '\'Sanokaa Joosefille näin: Oi, anna anteeksi veljiesi rikos ja synti, sillä pahasti he ovat menetelleet sinua kohtaan\'. Anna siis isäsi Jumalan palvelijoille anteeksi heidän rikoksensa.\" Ja Joosef itki kuullessaan nämä heidän sanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Sitten tulivat Joosefin veljet itse, lankesivat maahan hänen eteensä ja sanoivat: \"Katso, me olemme sinun orjiasi!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Mutta Joosef vastasi heille: \"Älkää peljätkö, olenko minä Jumalan sijassa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Te tosin hankitsitte minua vastaan pahaa, mutta Jumala on kääntänyt sen hyväksi, että hän saisi aikaan sen, mikä nyt on tapahtunut, ja pitäisi hengissä paljon kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Älkää siis peljätkö; minä elätän teidät ja teidän vaimonne ja lapsenne.\" Ja hän lohdutti ja rauhoitti heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Ja Joosef sekä hänen isänsä perhe jäivät asumaan Egyptiin. Ja Joosef eli sadan kymmenen vuoden vanhaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Ja Joosef sai nähdä Efraimin lapsia kolmanteen polveen; myöskin Maakirista, Manassen pojasta, syntyi lapsia Joosefin polville.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Niin Joosef sanoi veljilleen: \"Minä kuolen, mutta Jumala pitää huolen teistä ja johdattaa teidät tästä maasta siihen maahan, jonka hän valalla vannoen on luvannut Aabrahamille, Iisakille ja Jaakobille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Ja Joosef vannotti Israelin poikia sanoen: \"Kun Jumala pitää huolen teistä, viekää silloin minun luuni täältä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Ja Joosef kuoli sadan kymmenen vuoden vanhana. Ja hänet balsamoitiin ja pantiin arkkuun Egyptissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Nämä ovat Egyptiin tulleiden Israelin poikien nimet; Jaakobin kanssa he olivat itsekukin perheineen tulleet sinne:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruuben, Simeon, Leevi ja Juuda,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isaskar, Sebulon ja Benjamin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Daan, Naftali, Gaad ja Asser.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Ja Jaakobin kupeista lähteneitä oli kaikkiaan seitsemänkymmentä henkeä. Mutta Joosef oli jo ennestään Egyptissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Ja Joosef kuoli ja kaikki hänen veljensä ynnä koko se sukupolvi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Mutta israelilaiset olivat hedelmälliset ja sikisivät, lisääntyivät ja enenivät hyvin suurilukuisiksi, niin että maa tuli heitä täyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Niin Egyptiin tuli uusi kuningas, joka ei Joosefista mitään tiennyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Tämä sanoi kansallensa: \"Katso, israelilaisten kansa on suurempi ja väkevämpi kuin me.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Tulkaa, menetelkäämme siis viisaasti heitä kohtaan, että he eivät lisääntyisi eivätkä, jos sota syttyisi, liittyisi hekin vihollisiimme ja sotisi meitä vastaan ja lähtisi maasta pois.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Niin heille asetettiin työnjohtajia rasittamaan heitä raskaalla työllä. Ja heidän täytyi rakentaa faraolle varastokaupungit Piitom ja Ramses.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Mutta kuta enemmän kansaa rasitettiin, sitä enemmän se lisääntyi, ja sitä enemmän se levisi, niin että israelilaisia ruvettiin pelkäämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Niin egyptiläiset pitivät israelilaisia orjantyössä väkivalloin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'ja katkeroittivat heidän elämänsä kovalla laasti-ja tiilityöllä ja kaikenlaisella työllä ulkona kedolla, kaikenlaisella työllä, jota he teettivät heillä väkivalloin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Ja Egyptin kuningas puhui hebrealaisille kätilövaimoille, joista toisen nimi oli Sifra ja toisen Puua;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'ja hän sanoi: \"Kun te autatte hebrealaisia vaimoja heidän synnyttäessänsä, niin tarkastakaa lapsen sukupuoli: jos se on poika, surmatkaa se, mutta jos se on tyttö, jääköön eloon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Mutta kätilövaimot pelkäsivät Jumalaa eivätkä tehneet, niinkuin Egyptin kuningas oli heille sanonut, vaan antoivat poikalasten elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Niin Egyptin kuningas kutsui kätilövaimot ja sanoi heille: \"Miksi te näin teette ja annatte poikalasten elää?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Kätilövaimot vastasivat faraolle: \"Hebrealaiset vaimot eivät ole niinkuin egyptiläiset. He ovat voimakkaita; ennenkuin kätilövaimo tulee heidän luoksensa, ovat he jo synnyttäneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Mutta Jumala salli kätilövaimojen menestyä, ja kansa lisääntyi ja eneni suurilukuiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Ja koska kätilövaimot pelkäsivät Jumalaa, niin hän antoi heille runsaasti perhettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Niin farao antoi käskyn kaikelle kansallensa, sanoen: \"Kaikki poikalapset, jotka syntyvät, heittäkää Niilivirtaan, mutta kaikkien tyttölasten antakaa elää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Niin eräs mies, joka oli Leevin sukua, meni ja nai leeviläisen neidon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Ja vaimo tuli raskaaksi ja synnytti pojan. Ja kun hän näki, että se oli ihana lapsi, salasi hän sitä kolme kuukautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Mutta kun hän ei voinut sitä enää salata, otti hän kaisla-arkun, siveli sen maapihkalla ja piellä, pani lapsen siihen ja laski sen kaislikkoon Niilivirran rantaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Ja lapsen sisar asettui taammaksi nähdäksensä, mitä hänelle tapahtuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Silloin faraon tytär tuli alas peseytymään virrassa, ja hänen seuranaisensa kävelivät virran rannalla; ja kun hän näki arkun kaislikossa, lähetti hän palvelijattarensa ja otatti sen ylös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Ja kun hän avasi sen, näki hän lapsen; ja katso, siinä oli poikanen, joka itki. Niin hänen tuli sitä sääli, ja hän sanoi: \"Tämä on hebrealaisten lapsia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Niin lapsen sisar sanoi faraon tyttärelle: \"Menenkö kutsumaan sinulle hebrealaisen imettäjän, joka voi imettää sen lapsen sinulle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Faraon tytär vastasi hänelle: \"Mene!\" Niin tyttö meni ja kutsui lapsen äidin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Ja faraon tytär sanoi hänelle: \"Ota tämä lapsi ja imetä se minulle, niin minä maksan sinulle siitä palkan\". Ja vaimo otti lapsen ja imetti sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Mutta kun lapsi oli kasvanut, toi hän sen faraon tyttärelle, ja tämä otti sen pojaksensa ja antoi hänelle nimen Mooses, sillä hän sanoi: \"Minä olen vetänyt hänet ylös vedestä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Ja tapahtui niihin aikoihin, kun Mooses oli kasvanut suureksi, että hän meni veljiensä luo ja näki heidän raskaan työnsä. Ja hän näki egyptiläisen miehen lyövän hebrealaista miestä, erästä hänen veljistään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Silloin hän katseli ympärillensä joka taholle, ja kun hän näki, ettei ketään ollut läheisyydessä, löi hän egyptiläisen kuoliaaksi ja kätki hänet hiekkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Ja hän meni toisena päivänä ulos ja näki kaksi hebrealaista miestä tappelemassa keskenään; ja hän sanoi syylliselle: \"Miksi lyöt toveriasi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Tämä vastasi: \"Kuka on asettanut sinut meidän päämieheksemme ja tuomariksemme? Aiotko tappaa minutkin, niinkuin tapoit egyptiläisen?\" Silloin Mooses peljästyi ja ajatteli: \"Se on siis tullut ilmi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Ja kun farao sai kuulla tästä tapahtumasta, etsi hän Moosesta tappaaksensa hänet. Mutta Mooses lähti faraota pakoon ja pysähtyi Midianin maahan ja istahti eräälle kaivolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Ja Midianin papilla oli seitsemän tytärtä; nämä tulivat vettä ammentamaan ja täyttivät vesikaukalot, juottaakseen isänsä lampaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Mutta paimenet tulivat ja ajoivat heidät pois. Silloin Mooses nousi ja auttoi heitä ja juotti heidän lampaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Ja kun he tulivat isänsä Reguelin luo, kysyi hän: \"Kuinka te tänä päivänä niin pian jouduitte?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'He vastasivat: \"Egyptiläinen mies auttoi meitä paimenten käsistä, ammensipa vielä vettäkin meille ja juotti lampaat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Ja hän sanoi tyttärillensä: \"Missä hän on? Miksi te niin jätitte miehen? Kutsukaa hänet aterioimaan meidän kanssamme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Ja Mooses suostui asumaan sen miehen luona, ja hän antoi Moosekselle tyttärensä Sipporan vaimoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Tämä synnytti pojan, ja Mooses antoi hänelle nimen Geersom; sillä hän sanoi: \"Minä olen muukalainen vieraalla maalla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Ja kun oli kulunut pitkä aika, kuoli Egyptin kuningas. Ja israelilaiset huokailivat orjuuttansa ja valittivat; ja heidän huutonsa heidän orjuutensa tähden nousi Jumalan tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Ja Jumala kuuli heidän vaikeroimisensa, ja Jumala muisti liittonsa Aabrahamin, Iisakin ja Jaakobin kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Ja Jumala katsoi israelilaisten puoleen, ja Jumala piti heistä huolta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Ja Mooses kaitsi appensa Jetron, Midianin papin, lampaita. Ja kun hän kerran ajoi lampaita erämaan tuolle puolen, tuli hän Jumalan vuoren, Hoorebin, juurelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Silloin Herran enkeli ilmestyi hänelle tulen liekissä keskellä orjantappurapensasta; ja hän näki, että pensas paloi ilmitulessa, mutta pensas ei kuitenkaan kulunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Niin Mooses sanoi: \"Minä käyn tuonne ja katson tätä suurta näkyä, miksi ei pensas pala poroksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Kun Herra näki hänen tulevan katsomaan, huusi hän, Jumala, hänelle pensaasta ja sanoi: \"Mooses, Mooses!\" Hän vastasi: \"Tässä olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Hän sanoi: \"Älä tule tänne! Riisu kengät jalastasi, sillä paikka, jossa seisot, on pyhä maa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Ja hän sanoi vielä: \"Minä olen sinun isäsi Jumala, Aabrahamin Jumala, Iisakin Jumala ja Jaakobin Jumala\". Ja Mooses peitti kasvonsa, sillä hän pelkäsi katsoa Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Ja Herra sanoi: \"Minä olen nähnyt kansani kurjuuden Egyptissä ja kuullut heidän huutonsa sortajainsa tähden; niin, minä tiedän heidän tuskansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Sentähden minä olen astunut alas vapauttamaan heidät egyptiläisten kädestä ja johdattamaan heidät siitä maasta hyvään ja tilavaan maahan, maahan, joka vuotaa maitoa ja mettä, sinne, missä kanaanilaiset, heettiläiset, amorilaiset, perissiläiset, hivviläiset ja jebusilaiset asuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Ja nyt on israelilaisten huuto tullut minun kuuluviini, ja minä olen myös nähnyt sen sorron, jolla egyptiläiset heitä sortavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Niin mene nyt, minä lähetän sinut faraon tykö, ja vie minun kansani, israelilaiset, pois Egyptistä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Mutta Mooses sanoi Jumalalle: \"Mikä minä olen menemään faraon tykö ja viemään israelilaisia pois Egyptistä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Hän vastasi: \"Minä olen sinun kanssasi; ja tämä olkoon sinulle tunnusmerkkinä, että minä olen sinut lähettänyt: kun olet vienyt kansan pois Egyptistä, niin te palvelette Jumalaa tällä vuorella\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Mooses sanoi Jumalalle: \"Katso, kun minä menen israelilaisten luo ja sanon heille: \'Teidän isienne Jumala on lähettänyt minut teidän luoksenne\', ja kun he kysyvät minulta: \'Mikä hänen nimensä on?\' niin mitä minä heille vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Jumala vastasi Moosekselle: \"Minä olen se, joka minä olen\". Ja hän sanoi vielä: \"Sano israelilaisille näin: \'Minä olen\' lähetti minut teidän luoksenne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Ja Jumala sanoi vielä Moosekselle: \"Sano israelilaisille näin: Herra, teidän isienne Jumala, Aabrahamin Jumala, Iisakin Jumala ja Jaakobin Jumala, lähetti minut teidän luoksenne; tämä on minun nimeni iankaikkisesti, ja näin minua kutsuttakoon sukupolvesta sukupolveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Mene ja kokoa Israelin vanhimmat ja sano heille: Herra, teidän isienne Jumala, Aabrahamin, Iisakin ja Jaakobin Jumala, on ilmestynyt minulle ja sanonut: \'Totisesti minä pidän teistä huolen ja pidän silmällä, mitä teille tapahtuu Egyptissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Ja minä olen päättänyt näin: minä johdatan teidät pois Egyptin kurjuudesta kanaanilaisten, heettiläisten, amorilaisten, perissiläisten, hivviläisten ja jebusilaisten maahan, siihen maahan, joka vuotaa maitoa ja mettä.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Ja he kuulevat sinua. Niin mene sitten, sinä ja Israelin vanhimmat, Egyptin kuninkaan tykö, ja sanokaa hänelle: \'Herra, hebrealaisten Jumala, on kohdannut meitä. Anna siis meidän mennä kolmen päivän matka erämaahan uhraamaan Herralle, Jumalallemme.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Mutta minä tiedän, että Egyptin kuningas ei päästä teitä menemään, ei edes väkevän käden pakolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Mutta minä ojennan käteni ja lyön Egyptiä kaikenkaltaisilla ihmeilläni, joita minä olen siellä tekevä, ja sitten hän päästää teidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Ja minä annan tämän kansan päästä egyptiläisten suosioon, niin että te lähtiessänne ette lähde tyhjin käsin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Vaan jokainen vaimo on pyytävä naapuriltaan ja luonaan majailevalta vaimolta hopea-ja kultakaluja ja vaatteita. Niihin te puette poikanne ja tyttärenne ja viette ne saaliina egyptiläisiltä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Mooses vastasi ja sanoi: \"Katso, he eivät usko minua eivätkä kuule minua, vaan sanovat: \'Ei Herra ole sinulle ilmestynyt\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Herra sanoi hänelle: \"Mikä sinulla on kädessäsi?\" Hän vastasi: \"Sauva\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Hän sanoi: \"Heitä se maahan\". Ja hän heitti sen maahan, ja se muuttui käärmeeksi; ja Mooses pakeni sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Mutta Herra sanoi Moosekselle: \"Ojenna kätesi ja tartu sen pyrstöön\". Niin hän ojensi kätensä ja tarttui siihen, ja se muuttui sauvaksi hänen kädessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '-\"Siitä he uskovat, että Herra, heidän isiensä Jumala, Aabrahamin Jumala, Iisakin Jumala ja Jaakobin Jumala, on sinulle ilmestynyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Ja Herra sanoi vielä hänelle: \"Pistä kätesi poveesi\". Ja hän pisti kätensä poveensa. Ja kun hän veti sen ulos, niin katso, hänen kätensä oli pitalista valkoinen niinkuin lumi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Ja hän sanoi: \"Pistä kätesi takaisin poveesi\". Ja hän pisti kätensä takaisin poveensa. Ja kun hän veti sen ulos povestansa, niin katso, se oli taas niinkuin hänen muukin ihonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Herra sanoi: \"Jos he eivät usko sinua eivätkä tottele ensimmäistä tunnustekoa, niin he uskovat toisen tunnusteon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Mutta jos he eivät usko näitäkään kahta tunnustekoa eivätkä kuule sinua, niin ota vettä Niilivirrasta ja kaada kuivalle maalle, niin se vesi, jonka virrasta otat, on muuttuva vereksi kuivalla maalla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Niin Mooses sanoi Herralle: \"Oi Herra, minä en ole puhetaitoinen mies; en ole ollut ennen enkä senkään jälkeen, kuin sinä puhuit palvelijallesi; sillä minulla on hidas puhe ja kankea kieli\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Ja Herra sanoi hänelle: \"Kuka on antanut ihmiselle suun, tahi kuka tekee mykän tai kuuron, näkevän tai sokean? Enkö minä, Herra?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Mene siis nyt, minä olen sinun suusi apuna ja opetan sinulle, mitä sinun on puhuttava.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Mutta hän sanoi: \"Oi Herra, lähetä kuka muu tahansa!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Niin Herra vihastui Moosekseen ja sanoi: \"Eikö sinulla ole veljesi Aaron, leeviläinen? Minä tiedän, että hän osaa puhua. Ja katso, hän tuleekin sinua vastaan; ja kun hän näkee sinut, iloitsee hän sydämestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Ja puhu sinä hänelle ja pane sanat hänen suuhunsa. Ja minä olen sinun suusi apuna ja hänen suunsa apuna ja opetan teille, mitä teidän on tehtävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Ja hän on puhuva sinun puolestasi kansalle; niin hän on oleva sinulla suuna, ja sinä olet oleva hänellä jumalana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Ja ota käteesi tämä sauva, jolla olet tekevä nuo tunnusteot.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Niin Mooses tuli takaisin appensa Jetron luo ja sanoi hänelle: \"Anna minun mennä takaisin veljieni tykö Egyptiin, katsomaan, ovatko he vielä elossa\". Jetro sanoi Moosekselle: \"Mene rauhassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Ja Herra sanoi Moosekselle Midianissa: \"Mene takaisin Egyptiin, sillä kaikki ne ovat kuolleet, jotka väijyivät sinun henkeäsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Niin Mooses otti vaimonsa ja poikansa ja pani heidät aasin selkään ja palasi Egyptin maahan; ja Mooses otti käteensä Jumalan sauvan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Ja Herra sanoi Moosekselle: \"Kun tulet takaisin Egyptiin, niin katso, että teet faraon edessä kaikki ne ihmeet, jotka minä olen pannut sinun käteesi. Mutta minä paadutan hänen sydämensä, niin että hän ei päästä kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Sano silloin faraolle: \'Näin sanoo Herra: Israel on minun esikoispoikani;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'sentähden minä sanon sinulle: Päästä minun poikani palvelemaan minua. Mutta jos kieltäydyt päästämästä häntä, niin katso, minä tapan sinun esikoispoikasi.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Ja matkan varrella yöpaikassa tapahtui, että Herra kävi hänen kimppuunsa ja tahtoi surmata hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Silloin Sippora otti terävän kiven ja leikkasi pois poikansa esinahan, kosketti sillä Moosesta alhaalta ja sanoi: \"Sinä olet minun veriylkäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Niin hän jätti hänet rauhaan. Silloin Sippora sanoi: \"Veriylkä ympärileikkauksen kautta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Ja Herra sanoi Aaronille: \"Mene Moosesta vastaan erämaahan\". Ja hän meni ja kohtasi hänet Jumalan vuorella ja suuteli häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Ja Mooses kertoi Aaronille kaikki, mitä Herra oli puhunut lähettäessään hänet, ja kaikki ne tunnusteot, jotka hän oli käskenyt hänen tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Niin Mooses ja Aaron menivät ja kokosivat kaikki israelilaisten vanhimmat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Ja Aaron puhui kaikki, mitä Herra oli Moosekselle sanonut, ja Mooses teki tunnusteot kansan silmien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Ja kansa uskoi. Ja kun he kuulivat, että Herra oli pitänyt huolta israelilaisista ja nähnyt heidän kurjuutensa, kumartuivat he maahan ja rukoilivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Senjälkeen Mooses ja Aaron menivät ja sanoivat faraolle: \"Näin sanoo Herra, Israelin Jumala: Päästä minun kansani viettämään minulle juhlaa erämaassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Mutta farao vastasi: \"Kuka on Herra, jota minun pitäisi kuulla ja päästää Israel? Minä en tunne Herraa enkä päästä Israelia.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Niin he sanoivat: \"Hebrealaisten Jumala on kohdannut meitä. Anna siis meidän mennä kolmen päivän matka erämaahan uhraamaan Herralle, Jumalallemme, ettei hän rankaisisi meitä rutolla tai miekalla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Mutta Egyptin kuningas vastasi heille: \"Miksi te, Mooses ja Aaron, pidätätte kansaa työnteosta? Menkää töihinne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Ja farao sanoi vielä: \"Katsokaa, liian paljon on muutenkin joutoväkeä maassa, ja te tahdotte saattaa heidät kulkemaan työttöminä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Ja farao antoi sinä päivänä käskyn kansan työnteettäjille ja päällysmiehille, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '\"Älkää enää antako kansalle olkia tiilien tekemistä varten niinkuin ennen; he menkööt itse ja kootkoot itselleen oljet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Pankaa kuitenkin heidän tehtäväkseen sama tiilimäärä, jonka he ennenkin ovat tehneet, siitä mitään vähentämättä; sillä he ovat laiskoja, sentähden he huutavat näin: \'Menkäämme uhraamaan Jumalallemme!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Pantakoon miehille raskasta työtä, että heillä olisi siinä tekemistä ja että he eivät kuuntelisi valhepuheita.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Niin kansan työnteettäjät ja päällysmiehet menivät ja sanoivat kansalle: \"Näin sanoo farao: \'Minä en anna teille enää olkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Menkää itse ja hankkikaa itsellenne olkia, mistä vain löydätte, mutta työstänne ei vähennetä mitään.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Niin kansa hajosi pitkin Egyptin maata keräämään pehkuja olkien asemesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Ja työnteettäjät ahdistivat heitä sanoen: \"Tehkää työnne valmiiksi, kunkin päivän määrä päivälleen, niinkuin silloinkin, kun saitte olkia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Ja israelilaisten päällysmiehiä, joita faraon työnteettäjät olivat heille asettaneet, piestiin, ja heille sanottiin: \"Miksi ette ole eilen ettekä tänään suorittaneet tähänastista määräänne tiilien teossa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Niin israelilaisten päällysmiehet menivät ja valittivat faraolle, sanoen: \"Minkätähden teet näin palvelijoillesi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Olkia palvelijoillesi ei anneta, mutta kuitenkin sanotaan meille: \'Tehkää tiilet\'. Ja katso, palvelijoitasi piestään, vaikka vika on sinun oman väkesi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Mutta hän sanoi: \"Te olette laiskoja, laiskoja olette; sentähden te sanotte: \'Menkäämme uhraamaan Herralle\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Menkää vain työhönne. Olkia ei teille anneta, mutta määrätty luku tiiliä on teidän hankittava.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Niin israelilaisten päällysmiehet huomasivat joutuneensa ahtaalle, kun heille sanottiin: \"Ette saa mitään tiililuvun vähennystä kunkin päivän määrästä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Ja kun he lähtivät faraon luota, kohtasivat he Mooseksen ja Aaronin, jotka odottivat heitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'ja he sanoivat näille: \"Herra kostakoon teille ja tuomitkoon teidät; sillä te olette saattaneet meidät faraon ja hänen palvelijainsa vihoihin ja antaneet heidän käteensä miekan, meille surmaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Silloin Mooses palasi Herran tykö ja sanoi: \"Herra, miksi olet tehnyt niin pahoin tälle kansalle? Miksi olet lähettänyt minut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Sillä siitä asti, kun minä menin faraon tykö puhumaan sinun nimessäsi, hän on tehnyt pahaa tälle kansalle, etkä sinä suinkaan ole kansaasi vapahtanut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Mutta Herra vastasi Moosekselle: \"Nyt saat nähdä, mitä minä faraolle teen; sillä väkevän käden pakottamana hän on päästävä heidät, ja väkevän käden pakottamana hän on ajava heidät maastansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Ja Jumala puhui Moosekselle ja sanoi hänelle: \"Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Ja minä olen ilmestynyt Aabrahamille, Iisakille ja Jaakobille \'Jumalana Kaikkivaltiaana\', mutta nimelläni \'Herra\' en minä ole tehnyt itseäni heille tunnetuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Ja minä tein myös liittoni heidän kanssansa, antaakseni heille Kanaanin maan, sen maan, jossa he muukalaisina asuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Ja nyt minä olen kuullut israelilaisten vaikeroimisen, kun egyptiläiset pitävät heitä orjantyössä, ja olen muistanut liittoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Sano sentähden israelilaisille: \'Minä olen Herra, ja minä vien teidät pois egyptiläisten sorron alta ja vapautan teidät orjuudesta ja pelastan teidät ojennetulla käsivarrella ja suurilla rangaistustuomioilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Niin minä otan teidät kansakseni ja olen teidän Jumalanne; ja te tulette tietämään, että minä olen Herra, teidän Jumalanne, joka vien teidät pois egyptiläisten sorron alta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Ja minä johdatan teidät siihen maahan, jonka minä olen kättä kohottaen luvannut antaa Aabrahamille, Iisakille ja Jaakobille; ja sen minä annan teille omaksi. Minä olen Herra.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Ja Mooses puhui näin israelilaisille; mutta he eivät kuulleet Moosesta tuskaantumisensa ja raskaan orjuutensa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Sitten Herra puhui Moosekselle ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, '\"Mene ja sano faraolle, Egyptin kuninkaalle, että hän päästää israelilaiset maastansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Mutta Mooses puhui Herran edessä ja sanoi: \"Katso, israelilaiset eivät kuulleet minua; kuinka sitten farao kuulisi minua, joka olen huuliltani ympärileikkaamaton?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Mutta Herra puhui Moosekselle ja Aaronille ja käski heitä menemään israelilaisten ja faraon, Egyptin kuninkaan, tykö ja viemään israelilaiset pois Egyptin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Nämä ovat heidän perhekuntainsa päämiehet: Ruubenin, Israelin esikoisen, pojat olivat Hanok ja Pallu, Hesron ja Karmi. Nämä ovat Ruubenin sukukunnat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Simeonin pojat olivat Jemuel, Jaamin, Oohad, Jaakin, Soohar ja Saul, kanaanilaisen vaimon poika. Nämä ovat Simeonin sukukunnat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Ja nämä ovat Leevin poikien nimet heidän polveutumisensa mukaan: Geerson, Kehat ja Merari. Ja Leevin elinaika oli sata kolmekymmentä seitsemän vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Geersonin pojat olivat Libni ja Siimei, sukujensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel. Ja Kehatin elinaika oli sata kolmekymmentä kolme vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Merarin pojat olivat Mahli ja Muusi. Nämä ovat Leevin suvut polveutumisensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Mutta Amram otti isänsä sisaren Jookebedin vaimokseen, ja tämä synnytti hänelle Aaronin ja Mooseksen. Ja Amramin elinaika oli sata kolmekymmentä seitsemän vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Jisharin pojat olivat Koorah, Nefeg ja Sikri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Ussielin pojat olivat Miisael, Elsafan ja Sitri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Ja Aaron otti vaimoksensa Eliseban, Amminadabin tyttären, Nahsonin sisaren, ja tämä synnytti hänelle Naadabin, Abihun, Eleasarin ja Iitamarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Koorahin pojat olivat Assir, Elkana ja Abiasaf. Nämä ovat koorahilaisten suvut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Ja Eleasar, Aaronin poika, otti itsellensä vaimon Puutielin tyttäristä, ja tämä synnytti hänelle Piinehaan. Nämä ovat leeviläisten perhekuntien päämiehet heidän sukujensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Nämä olivat Aaron ja Mooses, joille Herra sanoi: \"Viekää israelilaiset joukkoinensa pois Egyptin maasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Nämä puhuivat faraolle, Egyptin kuninkaalle, että he aikoivat viedä israelilaiset pois Egyptistä, nimittäin Mooses ja Aaron.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Ja niihin aikoihin, kun Herra puhui Moosekselle Egyptin maassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'puhui Herra Moosekselle näin: \"Minä olen Herra. Sano faraolle, Egyptin kuninkaalle, kaikki, mitä minä sinulle puhun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Mutta Mooses vastasi Herran edessä: \"Katso, minä olen huuliltani ympärileikkaamaton, kuinka siis farao kuulisi minua?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Mutta Herra sanoi Moosekselle: \"Katso, minä asetan sinut jumalaksi faraolle, ja veljesi Aaron on oleva sinun profeettasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Puhu kaikki, mitä minä sinun käsken puhua; ja Aaron, sinun veljesi, puhukoon faraolle, että hän päästää israelilaiset maastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Mutta minä paadutan faraon sydämen ja teen monta tunnustekoa ja ihmettä Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Ja farao ei kuule teitä, mutta minä asetan käteni Egyptiä vastaan ja vien pois joukkoni, kansani, israelilaiset, Egyptin maasta, toimittaen suuret rangaistustuomiot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Ja egyptiläiset tulevat tietämään, että minä olen Herra, kun minä ojennan käteni Egyptin yli ja vien pois israelilaiset heidän keskeltänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Ja Mooses ja Aaron tekivät, niinkuin Herra oli heitä käskenyt; niin he tekivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Mutta Mooses oli kahdeksankymmenen vuoden vanha ja Aaron kahdeksankymmenen kolmen vuoden vanha, kun he puhuivat faraon kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Ja Herra puhui Moosekselle ja Aaronille ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, '\"Kun farao puhuu teille ja sanoo: \'Tehkää jokin ihmetyö\', niin sano sinä Aaronille: \'Ota sauvasi ja heitä se faraon eteen, niin se muuttuu käärmeeksi\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Niin Mooses ja Aaron menivät faraon tykö ja tekivät, niinkuin Herra oli käskenyt. Aaron heitti sauvansa faraon ja hänen palvelijainsa eteen, ja se muuttui käärmeeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Ja faraokin kutsui maansa viisaat ja velhot; ja nämä Egyptin tietäjät tekivät samoin taioillansa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'he heittivät kukin sauvansa maahan, ja ne muuttuivat käärmeiksi. Mutta Aaronin sauva nieli heidän sauvansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Ja faraon sydän paatui, eikä hän kuullut heitä, niinkuin Herra oli sanonutkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Sitten Herra sanoi Moosekselle: \"Faraon sydän on kovettunut, hän kieltäytyy päästämästä kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Mene faraon tykö huomenaamuna, kun hän menee veden luo, ja seisahdu hänen tielleen Niilivirran partaalle. Ja ota käteesi se sauva, joka oli muuttunut käärmeeksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'ja sano hänelle: \'Herra, hebrealaisten Jumala, on lähettänyt minut sinun luoksesi ja käskenyt sanoa: Päästä minun kansani palvelemaan minua erämaassa. Mutta katso, sinä et ole totellut tähän asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Sentähden Herra sanoo näin: Tästä olet tunteva, että minä olen Herra: katso, minä lyön sauvalla, joka on kädessäni, virran veteen, ja se muuttuu vereksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Ja kalat virrassa kuolevat, ja virta rupeaa haisemaan, niin että egyptiläisiä inhottaa juoda vettä virrasta.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Ja Herra sanoi Moosekselle: \"Sano Aaronille: \'Ota sauvasi ja ojenna kätesi Egyptin vetten yli, sen jokien, kanavien ja lammikkojen yli ja kaikkien niiden paikkojen yli, joihin on vettä kokoontunut, niin ne muuttuvat vereksi. Ja verta on oleva Egyptin maassa kaikkialla, sekä puuastioissa että kiviastioissa.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Ja Mooses ja Aaron tekivät, niinkuin Herra oli käskenyt. Hän kohotti sauvan ja löi Niilivirran veteen faraon ja hänen palvelijainsa nähden; ja kaikki vesi, joka virrassa oli, muuttui vereksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Ja kalat virrassa kuolivat, ja virta haisi, niin että egyptiläiset eivät saattaneet juoda vettä virrasta; ja verta oli kaikkialla Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Mutta Egyptin tietäjät tekivät samoin taioillansa. Ja faraon sydän paatui, eikä hän kuullut heitä, niinkuin Herra oli sanonutkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Ja farao kääntyi ja palasi kotiinsa eikä välittänyt tästäkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Mutta kaikki egyptiläiset kaivoivat Niilivirran ympäriltä vettä juodaksensa; sillä he eivät voineet juoda virran vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Ja näin oli kulunut seitsemän päivää siitä, kun Herra oli lyönyt Niilivirtaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Sitten Herra sanoi Moosekselle: \"Mene faraon luo ja sano hänelle: \'Näin sanoo Herra: Päästä minun kansani palvelemaan minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Mutta jos kieltäydyt päästämästä heitä, niin katso, minä rankaisen koko sinun maatasi sammakoilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Ja Niilivirta on vilisevä sammakoita, ja ne nousevat maalle ja tulevat sinun taloosi ja makuuhuoneeseesi ja vuoteeseesi, sekä sinun palvelijaisi taloihin ja kansasi sekaan, sinun leivinuuneihisi ja taikinakaukaloihisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Jopa sinun ja sinun kansasi ja kaikkien sinun palvelijaisi päälle hyppii sammakoita.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Ja Herra sanoi Moosekselle: \"Sano Aaronille: \'Ojenna kätesi sauvoinensa jokien, kanavien ja lammikkojen yli ja nostata sammakoita Egyptin maahan\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Niin Aaron ojensi kätensä Egyptin vetten yli, ja sammakoita nousi, ja ne peittivät Egyptin maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Ja tietäjät tekivät samoin taioillansa ja nostattivat sammakoita Egyptin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Niin farao kutsui Mooseksen ja Aaronin ja sanoi: \"Rukoilkaa Herraa, että hän ottaisi pois sammakot vaivaamasta minua ja minun kansaani, niin minä päästän kansan uhraamaan Herralle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Mooses sanoi faraolle: \"Suvaitse määrätä minulle aika, jonka kuluessa minun on rukoiltava, sinun itsesi, sinun palvelijaisi ja kansasi puolesta, sammakot hävitettäviksi luotasi ja taloistasi, niin että niitä jää ainoastaan Niilivirtaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Hän vastasi: \"Huomiseksi\". Niin Mooses sanoi: \"Tapahtukoon, niinkuin sanoit, tietääksesi, ettei kukaan ole niinkuin Herra, meidän Jumalamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Sammakot katoavat luotasi ja taloistasi ja sinun palvelijaisi ja kansasi luota, ja niitä jää ainoastaan Niilivirtaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Niin Mooses ja Aaron lähtivät faraon luota. Ja Mooses huusi Herran puoleen sammakkojen tähden, jotka hän oli pannut faraon vaivaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Ja Herra teki Mooseksen sanan mukaan: sammakot kuolivat huoneista, pihoilta ja kedoilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Ja he kokosivat niitä läjittäin, ja maa rupesi haisemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Mutta kun farao näki päässeensä hengähtämään, kovensi hän sydämensä eikä kuullut heitä, niinkuin Herra oli sanonutkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Sitten Herra sanoi Moosekselle: \"Sano Aaronille: \'Ojenna sauvasi ja lyö maan tomua, niin siitä tulee sääskiä koko Egyptin maahan\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Ja he tekivät niin: Aaron ojensi kätensä ja sauvansa ja löi maan tomua; niin sääsket ahdistivat ihmisiä ja karjaa. Kaikki maan tomu muuttui sääskiksi koko Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Ja tietäjät tekivät samoin taioillansa saadakseen sääskiä syntymään, mutta he eivät voineet. Ja sääsket ahdistivat ihmisiä ja karjaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Niin tietäjät sanoivat faraolle: \"Tämä on Jumalan sormi\". Mutta faraon sydän paatui, eikä hän kuullut heitä, niinkuin Herra oli sanonutkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Ja Herra sanoi Moosekselle: \"Astu huomenaamuna varhain faraon eteen, kun hän menee veden luo, ja sano hänelle: \'Näin sanoo Herra: Päästä minun kansani palvelemaan minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Sillä jos et päästä minun kansaani, niin katso, minä lähetän paarmoja sinun, sinun palvelijaisi ja sinun kansasi kimppuun ja sinun taloihisi, niin että egyptiläisten talot, jopa se maa, jonka päällä ne ovat, tulevat paarmoja täyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Mutta minä erotan sinä päivänä Goosenin maan, jossa minun kansani asuu, ettei sinne paarmoja tule, tietääksesi, että minä olen maan Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Näin minä panen pelastuksen erottamaan oman kansani sinun kansastasi. Huomenna on tämä ihme tapahtuva.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Ja Herra teki niin: paarmoja tuli suuret parvet faraon ja hänen palvelijainsa taloihin; ja paarmat tulivat maan turmioksi koko Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Niin farao kutsutti Mooseksen ja Aaronin ja sanoi: \"Menkää ja uhratkaa Jumalallenne tässä maassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Mutta Mooses sanoi: \"Ei sovi niin tehdä; sillä me uhraamme Herralle, Jumalallemme, sellaista, joka on egyptiläisille kauhistus. Jos me nyt uhraamme egyptiläisten nähden sellaista, joka on heille kauhistus, niin eivätkö he kivitä meitä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Salli meidän mennä kolmen päivän matka erämaahan uhraamaan Herralle, Jumalallemme, niinkuin hän on meille sanonut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Farao sanoi: \"Minä päästän teidät uhraamaan Herralle, Jumalallenne, erämaassa; älkää vain menkö kovin kauas. Rukoilkaa minun puolestani.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Niin Mooses sanoi: \"Katso, kun olen lähtenyt sinun luotasi, rukoilen minä Herraa, ja paarmat häviävät pois huomenna faraolta, hänen palvelijoiltansa ja hänen kansaltaan. Älköön vain farao enää pettäkö, niin ettei hän päästäkään kansaa uhraamaan Herralle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Ja Mooses lähti faraon luota ja rukoili Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'Ja Herra teki, niinkuin Mooses oli sanonut: hän vapautti faraon, hänen palvelijansa ja hänen kansansa paarmoista, niin ettei niitä jäänyt ainoatakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Mutta farao kovensi sydämensä tälläkin kerralla eikä päästänyt kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Sitten Herra sanoi Moosekselle: \"Mene faraon tykö ja puhu hänelle: \'Näin sanoo Herra, hebrealaisten Jumala: Päästä minun kansani palvelemaan minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Sillä jos kieltäydyt päästämästä heitä ja vielä pidätät heitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'niin katso, Herran käsi on lyövä sinun karjaasi, joka on kedolla, hevosia, aaseja, kameleita, nautoja ja lampaita ylen ankaralla ruttotaudilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Mutta Herra on tekevä erotuksen israelilaisten karjan ja egyptiläisten karjan välillä, niin ettei mitään kuole siitä, mikä on israelilaisten omaa.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Ja Herra asetti määrätyn ajan ja sanoi: \"Huomenna on Herra tekevä niin tässä maassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Ja seuraavana päivänä Herra teki niin, ja kaikki Egyptin karja kuoli; mutta israelilaisten karjasta ei kuollut ainoatakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Ja kun farao lähetti tiedustelemaan, niin katso, israelilaisten karjasta ei ollut kuollut ainoatakaan. Mutta faraon sydän kovettui, eikä hän päästänyt kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Sitten Herra sanoi Moosekselle ja Aaronille: \"Ottakaa kahmalonne täyteen pätsin nokea, ja Mooses viskatkoon sen taivasta kohti faraon silmien edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'niin se muuttuu tomuksi, joka peittää koko Egyptin maan, ja siitä tulee ihmisiin ja karjaan märkäpaiseita kaikkialla Egyptin maassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Ja he ottivat pätsin nokea ja astuivat faraon eteen, ja Mooses viskasi sen taivasta kohti; niin märkäpaiseita tuli ihmisiin ja karjaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Eivätkä tietäjätkään voineet pitää puoliaan Moosesta vastaan paiseiden tähden, sillä paiseita oli tietäjissä samoin kuin kaikissa muissakin egyptiläisissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Mutta Herra paadutti faraon sydämen, niin ettei hän kuullut heitä, niinkuin Herra oli sanonutkin Moosekselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Sitten Herra sanoi Moosekselle: \"Astu huomenaamuna varhain faraon eteen ja sano hänelle: \'Näin sanoo Herra, hebrealaisten Jumala: Päästä minun kansani palvelemaan minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Muutoin minä tällä kertaa lähetän kaikki vitsaukseni vaivaamaan sinua itseäsi, sinun palvelijoitasi ja kansaasi, tietääksesi, ettei ketään ole minun vertaistani koko maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Sillä minä olisin jo ojentanut käteni ja lyönyt sinua ja sinun kansaasi ruttotaudilla, niin että olisit kokonaan hävinnyt maan päältä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'mutta juuri sitä varten minä olen antanut sinun säilyä, että näyttäisin sinulle voimani ja että minun nimeni julistettaisiin kaiken maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Jos sinä vielä estät minun kansaani etkä päästä heitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'niin katso, huomenna tähän aikaan minä annan tulla ylen ankaran raesateen, jonka kaltaista ei ole Egyptissä ollut siitä päivästä saakka, jona sen perustus pantiin, aina tähän asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Lähetä siis nyt saattamaan suojaan karjasi ja kaikki, mitä sinulla on kedolla. Sillä kaikki ihmiset ja karja, jotka ovat kedolla ja joita ei ole korjattu kotiin, joutuvat raesateen alle ja kuolevat.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Se faraon palvelijoista, joka pelkäsi Herran sanaa, toimitti silloin palvelijansa ja karjansa huoneiden suojaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'mutta joka ei välittänyt Herran sanasta, se jätti palvelijansa ja karjansa kedolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Ja Herra sanoi Moosekselle: \"Ojenna kätesi taivasta kohti, niin raesade kohtaa koko Egyptin maata, ihmisiä, karjaa ja kaikkia kedon kasveja Egyptin maassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Niin Mooses ojensi sauvansa taivasta kohti, ja Herra antoi jylistä ja lähetti rakeita, ja tulta iski maahan. Näin Herra antoi sataa rakeita yli Egyptin maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Ja rakeita tuli, ja tulta leimahteli rakeiden keskellä. Raesade oli ylen ankara, niin ettei sellainen ollut kohdannut koko Egyptin maata siitä ajasta saakka, jolloin se tuli asutuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Ja rakeet löivät maahan kaikkialla Egyptin maassa kaiken, mitä kedolla oli, sekä ihmiset että karjan; ja rakeet tuhosivat kaikki maan kasvit ja pirstoivat kaikki kedon puut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Ainoastaan Goosenin maata, jossa israelilaiset olivat, ei raesade kohdannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Niin farao kutsutti Mooseksen ja Aaronin ja sanoi heille: \"Minä olen tehnyt syntiä tällä kertaa. Herra on oikeassa, mutta minä ja minun kansani olemme väärässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Rukoilkaa Herraa, sillä jo on meillä kyllin Jumalan jylinää ja rakeita. Minä päästän teidät, eikä teidän tarvitse enää viipyä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Mooses vastasi hänelle: \"Kun lähden kaupungista, niin minä ojennan käteni Herran puoleen, ja jylinä lakkaa eikä rakeita enää tule, tietääksesi, että maa on Herran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Mutta et sinä eivätkä sinun palvelijasi, sen kyllä tiedän, vielä nytkään pelkää Herraa Jumalaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Niin pellava ja ohra tuhoutuivat, sillä ohra oli tähkällä ja pellava kukalla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'mutta nisu ja kolmitahkoinen vehnä eivät turmeltuneet, sillä ne tuleentuvat myöhemmin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Ja Mooses lähti faraon luota, ulos kaupungista, ja ojensi kätensä Herran puoleen; ja jylinä ja rakeet lakkasivat, eikä sade enää vuotanut maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Kun farao näki, että sade, rakeet ja jylinä lakkasivat, teki hän yhä edelleen syntiä ja kovensi sydämensä, sekä hän että hänen palvelijansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Niin faraon sydän paatui, eikä hän päästänyt israelilaisia, niinkuin Herra oli Mooseksen kautta sanonutkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Sitten Herra sanoi Moosekselle: \"Mene faraon tykö, sillä minä olen koventanut hänen sydämensä ja hänen palvelijainsa sydämet, että tekisin nämä tunnustekoni heidän keskellänsä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'ja että sinä kertoisit lapsillesi ja lastesi lapsille, mitä minä olen tehnyt egyptiläisille, ja minun tunnustekoni, jotka olen tehnyt heidän keskellänsä, tietääksenne, että minä olen Herra\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Niin Mooses ja Aaron menivät faraon tykö ja sanoivat hänelle: \"Näin sanoo Herra, hebrealaisten Jumala: Kuinka kauan sinä kieltäydyt nöyrtymästä minun edessäni? Päästä minun kansani palvelemaan minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Sillä jos sinä kieltäydyt päästämästä minun kansaani, niin katso, minä annan huomenna tulla sinun maahasi heinäsirkkoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Ja ne peittävät maan pinnan, niin ettei maata näy, ja ne syövät tähteet siitä, mikä teille rakeilta pelastui ja jäi, ja ne syövät kaikki teidän puunne, jotka kedolla kasvavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Ja ne täyttävät sinun talosi ja kaikkien sinun palvelijaisi talot ja kaikkien egyptiläisten talot, niin ettei sinun isäsi eivätkä esi-isäsi ole sellaista nähneet siitä päivästä, jona tulivat maailmaan, hamaan tähän päivään asti.\" Ja hän kääntyi ja lähti pois faraon luota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Mutta faraon palvelijat sanoivat hänelle: \"Kuinka kauan tämä mies on oleva meille paulaksi? Päästä miehet palvelemaan Herraa, heidän Jumalaansa. Etkö vieläkään ymmärrä, että Egypti joutuu perikatoon?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Niin Mooses ja Aaron tuotiin takaisin faraon eteen. Ja tämä sanoi heille: \"Menkää ja palvelkaa Herraa, Jumalaanne. Vaan ketkä menevät?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Mooses vastasi: \"Me menemme, nuoret ja vanhat, me menemme poikinemme ja tyttärinemme, lampainemme ja karjoinemme; sillä meillä on Herran juhla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Niin hän sanoi heille: \"Olkoon vain Herra teidän kanssanne, kunhan minä ensin päästän teidät ja teidän vaimonne ja lapsenne. Katsokaa, teillä on paha mielessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Siitä ei tule mitään. Mutta menkää te, miehet, ja palvelkaa Herraa, sillä sitähän te olette pyytäneetkin.\" Ja heidät ajettiin pois faraon edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Ja Herra sanoi Moosekselle: \"Ojenna kätesi Egyptin maan yli ja tuo tänne heinäsirkat; tulkoon niitä Egyptin maahan, ja syökööt ne kaikki maan kasvit, kaikki, mitä rakeilta on jäänyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Niin Mooses ojensi sauvansa Egyptin maan yli, ja Herra antoi itätuulen puhaltaa yli maan koko sen päivän ja koko yön; kun aamu tuli, toi itätuuli heinäsirkat mukanaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Ja heinäsirkkoja tuli koko Egyptin maahan, ja ne laskeutuivat ylen suurina laumoina koko Egyptin alueelle; niin paljon ei heinäsirkkoja ollut koskaan sitä ennen tullut eikä sen jälkeen tule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Ne peittivät koko maan pinnan, niin että maa tuli mustaksi; ja ne söivät kaikki maan kasvit ja kaikki puiden hedelmät, jotka olivat rakeilta säilyneet. Niin ei jäänyt mitään vihantaa jäljelle puihin eikä kedon kasveihin koko Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Silloin farao kutsutti kiiruusti Mooseksen ja Aaronin ja sanoi: \"Minä olen rikkonut Herraa, teidän Jumalaanne, ja teitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Anna nyt anteeksi minun rikkomukseni vielä tämä kerta, ja rukoilkaa Herraa, Jumalaanne, että hän poistaisi minulta ainakin tämän surman.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Niin hän lähti pois faraon luota ja rukoili Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Ja Herra käänsi tuulen hyvin kovaksi länsituuleksi; se vei heinäsirkat mukanaan ja painoi ne Kaislamereen, niin ettei yhtäkään heinäsirkkaa jäänyt koko Egyptin alueelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Mutta Herra paadutti faraon sydämen, niin ettei hän päästänyt israelilaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Sitten Herra sanoi Moosekselle: \"Ojenna kätesi taivasta kohti, niin Egyptin maahan tulee sellainen pimeys, että siihen voi käsin tarttua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Ja Mooses ojensi kätensä taivasta kohti, ja koko Egyptin maahan tuli synkeä pimeys kolmeksi päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Ei kukaan voinut nähdä toistansa, eikä kukaan voinut liikkua paikaltansa kolmeen päivään. Mutta kaikilla israelilaisilla oli valoisata asuinpaikoissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Niin farao kutsui Mooseksen ja sanoi: \"Menkää ja palvelkaa Herraa; ainoastaan lampaanne ja karjanne jääkööt tänne. Myöskin vaimonne ja lapsenne menkööt teidän mukananne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mutta Mooses sanoi: \"Sinun on annettava mukaamme myös teurasuhrit ja polttouhrit, uhrataksemme niitä Herralle, Jumalallemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Karjammekin täytyy tulla meidän kanssamme, ei sorkkaakaan saa jäädä, sillä siitä meidän on otettava uhrit palvellaksemme Herraa, Jumalaamme, emmekä itsekään tiedä, ennenkuin tulemme sinne, mitä meidän on uhrattava palvellessamme Herraa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Mutta Herra paadutti faraon sydämen, niin että hän ei tahtonut päästää heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Ja farao sanoi hänelle: \"Mene pois luotani ja varo, ettet enää tule minun kasvojeni eteen; sillä sinä päivänä, jona tulet minun kasvojeni eteen, sinä olet kuoleva\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Mooses vastasi: \"Oikein sinä puhuit; minä en tule tämän jälkeen sinun kasvojesi eteen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Sitten Herra sanoi Moosekselle: \"Vielä yhden vitsauksen minä annan tulla faraolle ja Egyptiin; sen jälkeen hän päästää teidät täältä. Ja kun hän todella päästää teidät, niin hän ajamalla ajaa teidät täältä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Puhu siis nyt kansalle, että he, jokainen mies ja jokainen vaimo, pyytävät lähimmäisiltänsä hopea-ja kultakaluja.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Ja Herra antoi kansan päästä egyptiläisten suosioon. Myöskin Mooses oli hyvin arvossapidetty mies Egyptin maassa, sekä faraon palvelijain että kansan silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Ja Mooses sanoi: \"Näin sanoo Herra: Puoliyön aikana minä lähden kulkemaan kautta Egyptin maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Ja kaikki esikoiset Egyptin maassa kuolevat, valtaistuimellansa istuvan faraon esikoisesta käsikiveä vääntävän orjattaren esikoiseen asti, ynnä kaikki karjan esikoiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Ja koko Egyptin maassa on oleva kova valitus, jonka kaltaista ei ole ollut eikä koskaan tule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Mutta kenellekään israelilaiselle ei koirakaan ole muriseva, ei ihmiselle eikä eläimelle, tietääksesi, että Herra tekee erotuksen egyptiläisten ja Israelin välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Ja kaikki nämä sinun palvelijasi tulevat minun luokseni, kumartavat minua ja sanovat: \'Mene pois, sinä ja kaikki kansa, joka sinua seuraa\'. Ja sen jälkeen minä menen.\" Ja niin hän lähti faraon luota vihasta hehkuen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Mutta Herra sanoi Moosekselle: \"Farao ei kuule teitä, että paljon minun ihmeitäni tapahtuisi Egyptin maassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Ja Mooses ja Aaron tekivät kaikki nämä ihmeet faraon edessä; mutta Herra paadutti faraon sydämen, niin ettei hän päästänyt israelilaisia maastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Ja Herra puhui Moosekselle ja Aaronille Egyptin maassa sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '\"Tämä kuukausi olkoon teillä kuukausista ensimmäinen; siitä alottakaa vuoden kuukaudet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Puhukaa koko Israelin kansalle ja sanokaa: Tämän kuun kymmenentenä päivänä ottakoon kukin perheenisäntä itsellensä karitsan, yhden karitsan joka perhekuntaa kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Mutta jos perhe on liian pieni koko karitsaa syömään, niin ottakoon lähimmän naapurinsa kanssa yhteisen karitsan, henkilöluvun mukaan. Karitsaa kohti laskekaa niin monta, että voivat sen syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Ja karitsanne olkoon virheetön, vuoden vanha urospuoli; lampaista tai vuohista se ottakaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Ja pitäkää se tallella neljänteentoista päivään tätä kuuta; silloin Israelin koko seurakunta teurastakoon sen iltahämärässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Ja he ottakoot sen verta ja sivelkööt sillä molemmat pihtipielet ja ovenpäällisen niissä taloissa, joissa he sitä syövät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Ja he syökööt lihan samana yönä; tulessa paistettuna, happamattoman leivän ja katkerain yrttien kanssa he sen syökööt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Älkää syökö siitä mitään raakana tai vedessä keitettynä, vaan tulessa paistettuna päineen, jalkoineen ja sisälmyksineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Älkääkä jättäkö siitä mitään huomenaamuksi; mutta jos jotakin siitä jäisi huomenaamuksi, niin polttakaa se tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Ja syökää se näin: kupeet vyötettyinä, kengät jalassanne ja sauva kädessänne; ja syökää se kiiruusti. Tämä on pääsiäinen Herran kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Sillä minä kuljen sinä yönä kautta Egyptin maan ja surmaan kaikki esikoiset Egyptin maassa, sekä ihmiset että eläimet, ja panen toimeen rangaistustuomion, jonka minä olen langettanut kaikista Egyptin jumalista. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Ja veri on oleva merkki, teille suojelukseksi, taloissa, joissa olette; sillä kun minä näen veren, niin minä menen teidän ohitsenne, eikä rangaistus ole tuhoava teitä, kun minä rankaisen Egyptin maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Ja tämä päivä olkoon teille muistopäivä, ja viettäkää sitä Herran juhlana; sukupolvesta sukupolveen viettäkää sitä ikuisena säädöksenä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Seitsemän päivää syökää happamatonta leipää; jo ensimmäisenä päivänä korjatkaa pois hapan taikina taloistanne. Sillä jokainen, joka hapanta syö, ensimmäisestä päivästä seitsemänteen päivään asti, hävitettäköön Israelista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Ensimmäisenä päivänä pitäkää pyhä kokous ja samoin myös seitsemäntenä päivänä pyhä kokous. Mitään työtä älköön tehtäkö niinä päivinä; ainoastaan se, mitä kukin tarvitsee ruuaksi, ainoastaan se valmistettakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Ja pitäkää tätä happamattoman leivän juhlaa, sillä juuri sinä päivänä minä vein teidän joukkonne pois Egyptin maasta; sentähden pitäkää tätä päivää, sukupolvesta sukupolveen, ikuisena säädöksenä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, ehtoolla, syökää happamatonta leipää, ja niin tehkää aina saman kuun yhdennenkolmatta päivän ehtooseen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Seitsemään päivään älköön hapanta taikinaa olko teidän taloissanne; sillä jokainen, joka hapanta leipää syö, hävitettäköön Israelin kansasta, olipa hän muukalainen tai maassasyntynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Älkää syökö mitään hapanta, vaan syökää happamatonta leipää, missä asuttekin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Ja Mooses kutsui kaikki Israelin vanhimmat ja sanoi heille: \"Menkää ja ottakaa lammas kutakin perhekuntaanne kohti ja teurastakaa pääsiäislammas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Ja ottakaa isoppikimppu, kastakaa se vereen, joka on maljassa, ja sivelkää ovenpäällinen ja molemmat pihtipielet sillä verellä, joka on maljassa. Älköönkä kukaan menkö ulos talonsa ovesta ennen aamua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Sillä Herra kulkee rankaisemassa egyptiläisiä; mutta kun Herra näkee veren ovenpäällisessä ja molemmissa pihtipielissä, menee hän sen oven ohi eikä salli tuhoojan tulla teidän taloihinne teitä vitsauksella lyömään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Noudattakaa tätä; se olkoon ikuinen säädös sinulle ja sinun lapsillesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Ja kun te tulette siihen maahan, jonka Herra on teille antava, niinkuin hän on sanonut, niin noudattakaa näitä menoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Kun sitten lapsenne kysyvät teiltä: \'Mitä nämä menot merkitsevät?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'niin vastatkaa: \'Tämä on pääsiäisuhri Herralle, joka meni israelilaisten talojen ohi Egyptissä, kun hän rankaisi egyptiläisiä, mutta säästi meidän kotimme\'.\" Silloin kansa kumartui maahan ja rukoili.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Ja israelilaiset menivät ja tekivät, niinkuin Herra oli Moosekselle ja Aaronille käskyn antanut; niin he tekivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Ja puoliyön aikana tapahtui, että Herra surmasi kaikki Egyptin maan esikoiset, valtaistuimellaan istuvan faraon esikoisesta vankikuopassa olevan vangin esikoiseen asti, ynnä kaikki karjan esikoiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Niin farao nousi sinä yönä ja kaikki hänen palvelijansa ynnä kaikki egyptiläiset, ja kova valitus oli Egyptissä; sillä ei ollut yhtään taloa, jossa ei ollut kuollutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Ja hän kutsutti yöllä Mooseksen ja Aaronin ja sanoi: \"Nouskaa ja menkää pois minun kansani joukosta, sekä te että israelilaiset; menkää ja palvelkaa Herraa, niinkuin olette puhuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Ottakaa myös lampaanne ja karjanne mukaanne, niinkuin olette puhuneet, ja menkää ja rukoilkaa minullekin siunausta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Ja egyptiläiset ahdistivat kansaa jouduttaaksensa heidän lähtöänsä maasta pois, sillä he ajattelivat: \"Me kuolemme kaikki\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Ja kansa otti taikinansa, ennenkuin se oli hapannut, ja kantoi taikinakaukalonsa vaippoihin käärittyinä olkapäillään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Ja israelilaiset olivat tehneet Mooseksen sanan mukaan: he olivat pyytäneet egyptiläisiltä hopea-ja kultakaluja sekä vaatteita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Ja Herra oli antanut kansan päästä egyptiläisten suosioon, niin että nämä suostuivat heidän pyyntöönsä; ja niin he veivät saalista egyptiläisiltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Ja israelilaiset lähtivät liikkeelle ja kulkivat Ramseksesta Sukkotiin; heitä oli noin kuusisataa tuhatta jalkamiestä, paitsi vaimoja ja lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Ja myös paljon sekakansaa meni heidän kanssansa, sekä lampaita ja raavaskarjaa suuret laumat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Ja he leipoivat siitä taikinasta, jonka olivat tuoneet Egyptistä, happamattomia leipiä; sillä se ei ollut hapannut, kun heidät karkoitettiin Egyptistä. He eivät olleet saaneet viipyä, eivätkä he myöskään olleet valmistaneet itsellensä evästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Mutta aika, jonka israelilaiset olivat asuneet Egyptissä, oli neljäsataa kolmekymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Kun ne neljäsataa kolmekymmentä vuotta olivat kuluneet, niin juuri sinä päivänä kaikki Herran joukot lähtivät Egyptin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Valvontayö Herran kunniaksi on tämä yö, koska hän silloin vei heidät pois Egyptin maasta; tämän yön kaikki israelilaiset valvokoot Herran kunniaksi, sukupolvesta sukupolveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Ja Herra sanoi Moosekselle ja Aaronille: \"Tämä on säädös pääsiäislampaasta: Kukaan muukalainen älköön siitä syökö;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'mutta jokainen rahalla ostettu orja syököön siitä, kunhan olet ympärileikannut hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Loinen ja päiväpalkkalainen älkööt siitä syökö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'Samassa talossa se syötäköön; älköön mitään siitä lihasta vietäkö talosta ulos, älkääkä siitä luuta rikkoko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Koko Israelin seurakunta viettäköön sitä ateriaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Ja jos joku muukalainen asuu sinun luonasi ja tahtoo viettää pääsiäistä Herran kunniaksi, niin ympärileikkauttakoon kaikki miehenpuolensa ja sitten käyköön sitä viettämään ja olkoon silloin niinkuin maassasyntynyt. Mutta yksikään ympärileikkaamaton älköön siitä syökö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Sama laki olkoon maassasyntyneellä ja muukalaisella, joka asuu teidän keskuudessanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Ja kaikki israelilaiset tekivät, niinkuin Herra oli Moosekselle ja Aaronille käskyn antanut; niin he tekivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, '{12:50} Ja juuri sinä päivänä Herra vei israelilaiset joukkoinensa pois Egyptin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '\"Pyhitä minulle jokainen esikoinen, jokainen, joka israelilaisten seassa, sekä ihmisistä että karjasta, avaa äidinkohdun; se on minun\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Ja Mooses sanoi kansalle: \"Muistakaa tämä päivä, jona te lähditte Egyptistä, orjuuden pesästä; sillä Herra vei teidät sieltä pois väkevällä kädellä. Sentähden älköön mitään hapanta syötäkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Tänä päivänä aabib-kuussa te lähditte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Ja kun Herra vie sinut kanaanilaisten, heettiläisten, amorilaisten, hivviläisten ja jebusilaisten maahan, jonka hän sinun isillesi vannotulla valalla on luvannut antaa sinulle, siihen maahan, joka vuotaa maitoa ja mettä, niin vietä tämä jumalanpalvelus tässä kuussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Syö seitsemänä päivänä happamatonta leipää, ja seitsemäntenä päivänä olkoon Herran juhla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Happamatonta leipää syötäköön näinä seitsemänä päivänä; älköön mitään hapanta olko, älköön olko hapanta taikinaa koko sinun maassasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Ja kerro pojallesi sinä päivänä ja sano: \'Näin tehdään sen johdosta, mitä Herra minulle teki, kun minä lähdin Egyptistä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Ja se olkoon merkkinä sinun kädessäsi ja muistutuksena sinun otsallasi, että Herran laki olisi sinun suussasi; sillä Herra vei sinut väkevällä kädellä pois Egyptistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Sentähden noudata tätä säädöstä määräaikanansa vuodesta vuoteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Ja kun Herra on vienyt sinut kanaanilaisten maahan, niinkuin hän on sinulle ja sinun isillesi vannonut, ja kun hän on sen sinulle antanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'niin luovuta Herralle kaikki, mikä avaa äidinkohdun; ja kaikki ensiksisyntyneet karjastasi, urospuolet, olkoot Herran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Mutta jokainen aasin ensiksisynnyttämä lunasta lampaalla; mutta jos et sitä lunasta, niin taita siltä niska. Ja lunasta jokainen ihmisen esikoinen poikiesi seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Ja kun sinun poikasi vastaisuudessa kysyy sinulta ja sanoo: \'Mitä tämä merkitsee?\' niin vastaa hänelle: \'Herra vei meidät väkevällä kädellä pois Egyptistä, orjuuden pesästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Sillä kun farao paatui ja kieltäytyi päästämästä meitä, surmasi Herra kaikki esikoiset Egyptin maassa, ihmisten esikoisista karjan esikoisiin asti. Sentähden minä uhraan Herralle jokaisen urospuolen, joka avaa äidinkohdun, ja jokaisen esikoisen pojistani minä lunastan.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Ja se olkoon merkkinä sinun kädessäsi ja muistolauseena sinun otsallasi; sillä Herra vei meidät väkevällä kädellä pois Egyptistä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Mutta kun farao oli päästänyt kansan, ei Jumala johdattanut heitä sitä tietä, joka kulki filistealaisten maan kautta, vaikka se oli suorin, sillä Jumala ajatteli, että kansa ehkä katuisi nähdessänsä sodan syttyvän ja palaisi Egyptiin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'vaan Jumala antoi kansan poiketa erämaan tietä myöten Kaislamerta kohti. Ja taisteluun valmiina israelilaiset lähtivät Egyptin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Ja Mooses otti mukaansa Joosefin luut; sillä tämä oli vannottanut israelilaisia ja sanonut: \"Kun Jumala pitää huolen teistä, viekää silloin minun luuni täältä mukananne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Ja he lähtivät liikkeelle Sukkotista ja leiriytyivät Eetamiin, erämaan reunaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Ja Herra kulki heidän edellänsä, päivällä pilvenpatsaassa johdattaaksensa heitä tietä myöten ja yöllä tulenpatsaassa valaistaksensa heidän kulkunsa, niin että he voivat vaeltaa sekä päivällä että yöllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Pilvenpatsas ei poistunut päivällä eikä tulenpatsas yöllä kansan edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, '\"Sano israelilaisille, että he kääntyvät takaisin ja leiriytyvät Pii-Hahirotin kohdalle Migdolin ja meren välille; leiriytykää vastapäätä Baal-Sefonia meren rannalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Ja farao on ajatteleva, että israelilaiset ovat eksyneet maassa ja että erämaa on saartanut heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Ja minä paadutan faraon sydämen, niin että hän ajaa heitä takaa; mutta minä näytän kunniani tuhoamalla faraon ja koko hänen sotajoukkonsa; ja niin egyptiläiset tulevat tietämään, että minä olen Herra.\" Ja he tekivät niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Kun Egyptin kuninkaalle ilmoitettiin, että kansa oli paennut, muuttui faraon ja hänen palvelijainsa mieli kansaa kohtaan, ja he sanoivat: \"Mitä teimmekään, kun päästimme Israelin meitä palvelemasta!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Ja hän valjastutti hevoset sotavaunujensa eteen ja otti väkensä mukaansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'ja hän otti kuudetsadat valitut sotavaunut sekä kaikki muut Egyptin sotavaunut ynnä vaunusoturit niihin kaikkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Sillä Herra paadutti faraon, Egyptin kuninkaan, sydämen, niin että hän lähti ajamaan takaa israelilaisia, vaikka israelilaiset olivat lähteneet matkaan voimallisen käden suojassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Ja egyptiläiset, kaikki faraon hevoset, sotavaunut ja ratsumiehet ja koko hänen sotajoukkonsa, ajoivat heitä takaa ja saavuttivat heidät leiriytyneinä meren rannalle, Pii-Hahirotin kohdalle, vastapäätä Baal-Sefonia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Ja kun farao oli lähellä, nostivat israelilaiset silmänsä ja näkivät, että egyptiläiset olivat tulossa heidän jäljessänsä. Silloin israelilaiset peljästyivät kovin ja huusivat Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Ja he sanoivat Moosekselle: \"Eikö Egyptissä ollut hautoja, kun toit meidät tänne erämaahan kuolemaan? Mitä teit meille, kun johdatit meidät pois Egyptistä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Emmekö sanoneet tätä sinulle Egyptissä? Sanoimmehan: Anna meidän olla rauhassa, että palvelisimme egyptiläisiä. Sillä parempi olisi ollut palvella egyptiläisiä kuin kuolla erämaahan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Mooses vastasi kansalle: \"Älkää peljätkö; pysykää paikoillanne, niin te näette, minkä pelastuksen Herra tänä päivänä antaa teille; sillä sellaista, minkä näette egyptiläisille tapahtuvan tänä päivänä, ette koskaan enää tule näkemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Herra sotii teidän puolestanne, ja te olkaa hiljaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Ja Herra sanoi Moosekselle: \"Miksi huudat minulle? Sano israelilaisille, että he lähtevät liikkeelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Mutta sinä nosta sauvasi ja ojenna kätesi meren yli ja halkaise se, niin että israelilaiset voivat käydä meren poikki kuivaa myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Ja katso, minä paadutan egyptiläisten sydämet, niin että he tulevat heidän perässänsä; minä näytän kunniani tuhoamalla faraon ja koko hänen sotajoukkonsa, hänen sotavaununsa ja ratsumiehensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Ja egyptiläiset tulevat tietämään, että minä olen Herra, kun minä näytän kunniani tuhoamalla faraon, hänen sotavaununsa ja ratsumiehensä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Niin Jumalan enkeli, joka oli kulkenut Israelin joukon edellä, siirtyi kulkemaan heidän takanansa; ja pilvenpatsas siirtyi heidän edeltänsä ja asettui heidän taaksensa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'ja tuli egyptiläisten joukon ja Israelin joukon väliin; ja pilvi oli pimeä noille ja valaisi yön näille. Näin koko yönä toinen joukko ei voinut lähestyä toista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Ja Mooses ojensi kätensä meren yli. Niin Herra saattoi vahvalla itätuulella, joka puhalsi koko yön, meren väistymään ja muutti meren kuivaksi maaksi; ja vesi jakautui kahtia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Ja israelilaiset kulkivat meren poikki kuivaa myöten, ja vesi oli heillä muurina sekä oikealla että vasemmalla puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Ja egyptiläiset, kaikki faraon hevoset, hänen sotavaununsa ja ratsumiehensä, ajoivat heitä takaa ja tulivat heidän perässänsä keskelle merta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Kun aamuvartio tuli, katsahti Herra egyptiläisten joukkoa tulenpatsaasta ja pilvestä ja saattoi hämminkiin egyptiläisten joukon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Ja hän antoi heidän vaunujensa pyöräin irtautua, niin että heille kävi vaikeaksi päästä eteenpäin. Niin egyptiläiset sanoivat: \"Paetkaamme Israelia, sillä Herra sotii heidän puolestansa egyptiläisiä vastaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Mutta Herra sanoi Moosekselle: \"Ojenna kätesi meren yli, että vedet palautuisivat ja peittäisivät egyptiläiset, heidän sotavaununsa ja ratsumiehensä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Niin Mooses ojensi kätensä meren yli, ja aamun koittaessa meri palasi paikoillensa, egyptiläisten paetessa sitä vastaan; ja Herra syöksi egyptiläiset keskelle merta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Ja vedet palasivat ja peittivät sotavaunut ja ratsumiehet, koko faraon sotajoukon, joka oli seurannut heitä mereen; ei yksikään heistä pelastunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Mutta israelilaiset kulkivat kuivaa myöten meren poikki, ja vesi oli heillä muurina sekä oikealla että vasemmalla puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Niin Herra pelasti Israelin sinä päivänä egyptiläisten käsistä, ja Israel näki egyptiläiset kuolleina meren rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Ja Israel näki sen suuren teon, jonka Herra teki tuhotessaan egyptiläiset. Silloin kansa pelkäsi Herraa ja uskoi Herraan ja uskoi hänen palvelijaansa Moosesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Silloin Mooses ja israelilaiset veisasivat Herralle tämän virren; he sanoivat näin: \"Minä veisaan Herralle, sillä hän on ylen korkea; hevoset ja miehet hän mereen syöksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Herra on minun väkevyyteni ja ylistysvirteni, ja hänestä tuli minulle pelastus. Hän on minun Jumalani, ja minä ylistän häntä, hän on minun isäni Jumala, ja minä kunnioitan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Herra on sotasankari, Herra on hänen nimensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Faraon vaunut ja hänen sotajoukkonsa hän suisti mereen, hänen valitut vaunusoturinsa hukkuivat Kaislamereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Syvyys peitti heidät; he vajosivat pohjaan niinkuin kivi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Sinun oikea kätesi, Herra, sinä voimassa jalo, sinun oikea kätesi, Herra, murskaa vihollisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Valtasuuruudessasi sinä kukistat vastustajasi. Sinä päästät vihasi valloilleen, ja se kuluttaa heidät niinkuin korret.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Ja sinun vihasi puhalluksesta kasaantuivat vedet, laineet seisahtuivat roukkioiksi, syvyyden aallot hyytyivät keskelle merta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Vihollinen sanoi: \'Minä ajan takaa, minä saavutan heidät, minä jaan saaliin ja tyydytän heissä kostonhimoni; minä paljastan miekkani, minun käteni hävittää heidät\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Sinun tuulesi puhalsi, ja meri peitti heidät; he upposivat valtavesiin niinkuin lyijy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Herra, kuka on sinun vertaisesi jumalien joukossa! Kuka on sinun vertaisesi, sinä pyhyydessä jalo; sinä ylistettävissä teoissa peljättävä, sinä ihmeitten tekijä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Sinä ojensit oikean kätesi, maa nielaisi heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Mutta armossasi sinä johdatit lunastamaasi kansaa, sinä veit sen voimallasi pyhään asuntoosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Kansat kuulivat sen ja vapisivat, tuska valtasi Filistean asukkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Silloin peljästyivät Edomin ruhtinaat, Mooabin sankarit valtasi vavistus, kaikki Kanaanin asukkaat menehtyivät pelkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Kauhu ja väristys valtasi heidät; sinun käsivartesi väkevyyden tähden he kävivät mykiksi niinkuin kivi. Niin sinun kansasi, Herra, kulkee perille, kulkee perille se kansa, jonka olet itsellesi hankkinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Sinä viet heidät perille ja istutat heidät vuorelle, joka on sinun perintöosasi, paikkaan, jonka sinä, Herra, olet asunnoksesi valmistanut, pyhäkköösi, Herra, jonka sinun kätesi ovat tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Herra on kuningas aina ja iankaikkisesti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Sillä kun faraon hevoset ja hänen sotavaununsa ja ratsumiehensä menivät mereen, palautti Herra meren vedet heidän päällensä; mutta israelilaiset kulkivat kuivaa myöten meren poikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Ja naisprofeetta Mirjam, Aaronin sisar, otti vaskirummun käteensä, ja kaikki naiset seurasivat häntä vaskirumpuja lyöden ja karkeloiden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Ja Mirjam viritti heille virren: \"Veisatkaa Herralle, sillä hän on ylen korkea, hevoset ja miehet hän mereen syöksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Sitten Mooses antoi israelilaisten lähteä liikkeelle Kaislameren luota, ja he menivät Suurin erämaahan. Ja he vaelsivat kolme päivää erämaassa löytämättä vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Sitten he tulivat Maaraan; mutta he eivät voineet juoda Maaran vettä; sillä se oli karvasta. Sentähden paikka sai nimen Maara.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Niin kansa napisi Moosesta vastaan ja sanoi: \"Mitä me juomme?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Mutta hän huusi Herran puoleen; ja Herra osoitti hänelle puun, jonka hän heitti veteen, ja vesi tuli makeaksi. Siellä hän antoi kansalle lain ja oikeuden, ja siellä hän koetteli sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Hän sanoi: \"Jos sinä kuulet Herraa, Jumalaasi, ja teet, mikä on oikein hänen silmissänsä, tarkkaat hänen käskyjänsä ja noudatat kaikkea hänen lakiansa, niin minä en pane sinun kärsittäväksesi yhtäkään niistä vaivoista, jotka olen pannut egyptiläisten kärsittäviksi, sillä minä olen Herra, sinun parantajasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Sitten he tulivat Eelimiin; siellä oli kaksitoista vesilähdettä ja seitsemänkymmentä palmupuuta. Ja he leiriytyivät siellä veden ääreen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Sitten he lähtivät, koko Israelin kansa, liikkeelle Eelimistä ja tulivat Siinin erämaahan, joka on Eelimin ja Siinain välillä, toisen kuun viidentenätoista päivänä siitä, kun he olivat lähteneet Egyptin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Ja koko Israelin kansa napisi Moosesta ja Aaronia vastaan erämaassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'ja israelilaiset sanoivat heille: \"Jospa olisimme saaneet surmamme Herran kädestä Egyptin maassa, jossa istuimme lihapatain ääressä ja leipää oli kyllin syödäksemme! Mutta te olette tuoneet meidät tähän erämaahan antaaksenne koko tämän joukon kuolla nälkään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Niin Herra sanoi Moosekselle: \"Katso, minä annan sataa teille leipää taivaasta. Ja kansa menköön ja kootkoon kunakin päivänä sen päivän tarpeen. Näin minä koettelen heitä, vaeltavatko he minun lakini mukaan vai eivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Ja kun he kuudentena päivänä valmistavat sen, mitä ovat tuoneet kotiin, niin sitä on oleva kaksi kertaa niin paljon, kuin mitä he muutoin joka päivä kokoavat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Ja Mooses ja Aaron sanoivat kaikille israelilaisille: \"Tänä iltana te tulette tietämään, että Herra on vienyt teidät pois Egyptin maasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'ja huomenaamuna te tulette näkemään Herran kunnian, koska Herra on kuullut teidän napinanne häntä vastaan. Sillä mitä olemme me, että te meitä vastaan napisette?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Ja Mooses sanoi vielä: \"Herra antaa teille tänä iltana lihaa syödäksenne ja huomenna leipää yltäkyllin ravinnoksenne, koska Herra on kuullut teidän napinanne, kun olette napisseet häntä vastaan. Sillä mitä olemme me? Ette ole napisseet meitä vastaan, vaan Herraa vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Ja Mooses sanoi Aaronille: \"Sano koko Israelin kansalle: Astukaa Herran eteen, sillä hän on kuullut teidän napinanne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Ja kun Aaron oli puhunut tämän koko Israelin seurakunnalle, kääntyivät he erämaahan päin, ja katso, Herran kunnia näkyi pilvessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '\"Minä olen kuullut israelilaisten napinan. Puhu heille ja sano: Iltahämärässä teillä on oleva lihaa syödäksenne, ja huomenna on teillä leipää yltäkyllin; niin te tulette tietämään, että minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Ja illalla tuli viiriäisiä, ja ne peittivät leirin, ja aamulla laskeutui kastesumu leirin ympärille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Ja kun kastesumu oli haihtunut, katso, erämaassa oli maan pinnalla jotakin hienoa, suomujen tapaista, jotakin hienoa niinkuin härmä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Kun israelilaiset näkivät sen, kyselivät he toisiltansa: \"Mitä tämä on?\" Sillä he eivät tienneet, mitä se oli. Ja Mooses sanoi heille: \"Tämä on se leipä, jonka Herra on antanut teille syötäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Ja näin on Herra käskenyt: Kootkaa sitä, jokainen tarpeenne mukaan; ottakaa goomer-mitta mieheen perheenne pääluvun mukaan, kukin niin monelle, kuin kullakin majassansa on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Ja israelilaiset tekivät niin, ja he kokosivat, yksi enemmän, toinen vähemmän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Mutta kun he mittasivat sen goomer-mitalla, niin ei sille jäänyt liikaa, joka oli koonnut enemmän, eikä siltä puuttunut, joka oli koonnut vähemmän; jokainen oli koonnut niin paljon, kuin hän tarvitsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Ja Mooses sanoi heille: \"Älköön kukaan jättäkö siitä mitään huomiseksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Mutta he eivät kuulleet Moosesta, vaan muutamat jättivät siitä jotakin huomiseksi. Niin siihen kasvoi matoja, ja se rupesi haisemaan; ja Mooses vihastui heihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Ja he kokosivat sitä joka aamu sen verran, kuin kukin tarvitsi; mutta kun aurinko alkoi paahtaa, niin se suli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Mutta kuudentena päivänä he kokosivat sitä leipää kaksinkertaisesti, kaksi goomeria kullekin. Ja kaikki kansan päämiehet tulivat ja ilmoittivat sen Moosekselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Niin hän sanoi heille: \"Tämä tapahtuu Herran sanan mukaan; huomenna on levon päivä, Herralle pyhitetty sapatti. Mitä leivotte, se leipokaa, ja mitä keitätte, se keittäkää; mutta kaikki, mitä tähteeksi jää, pankaa talteen huomiseksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Ja he panivat sen talteen huomiseksi, niinkuin Mooses oli käskenyt, eikä se ruvennut haisemaan, eikä siihen tullut matoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Ja Mooses sanoi: \"Syökää se tänä päivänä, sillä tänä päivänä on Herran sapatti; tänään ette löydä kedolta mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Kuutena päivänä on teidän sitä koottava, mutta seitsemäntenä päivänä on sapatti; silloin ei sitä ole.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Kuitenkin muutamat kansasta lähtivät seitsemäntenä päivänä kokoamaan sitä, mutta he eivät löytäneet mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Niin Herra sanoi Moosekselle: \"Kuinka kauan aiotte kieltäytyä noudattamasta minun käskyjäni ja lakejani?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Katsokaa, Herra on antanut teille sapatin; sentähden hän antaa teille kuudentena päivänä kahden päivän leivän. Olkoon jokainen alallaan, älköönkä kukaan lähtekö paikaltansa seitsemäntenä päivänä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Ja kansa lepäsi seitsemäntenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Ja Israelin heimo antoi sille nimen manna. Ja se oli valkean korianderinsiemenen kaltaista ja maistui hunajakakulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Ja Mooses sanoi: \"Näin on Herra käskenyt: Ota sitä goomerin täysi säilytettäväksi sukupolvesta sukupolveen, että he näkisivät sen leivän, jolla minä olen ravinnut teitä erämaassa, johdattaessani teitä Egyptin maasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Ja Mooses sanoi Aaronille: \"Ota astia ja pane siihen goomerin täysi mannaa ja aseta se Herran eteen säilytettäväksi sukupolvesta sukupolveen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Ja Aaron asetti sen talteen lain arkin eteen, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Ja israelilaiset söivät mannaa neljäkymmentä vuotta, kunnes he tulivat asuttuun maahan; he söivät mannaa siihen asti, kunnes tulivat Kanaanin maan rajalle. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Goomer on kymmenesosa eefaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Sitten kaikki israelilaisten seurakunta lähti liikkeelle Siinin erämaasta ja matkusti levähdyspaikasta toiseen Herran käskyn mukaan. Ja he leiriytyivät Refidimiin; siellä ei ollut vettä kansan juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Niin kansa riiteli Moosesta vastaan ja sanoi: \"Antakaa meille vettä juoda!\" Mooses vastasi heille: \"Miksi riitelette minua vastaan? Miksi kiusaatte Herraa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Mutta kansalla oli siellä jano, ja he napisivat yhä Moosesta vastaan ja sanoivat: \"Minkätähden olet tuonut meidät Egyptistä, antaaksesi meidän ja meidän lastemme ja karjamme kuolla janoon?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Niin Mooses huusi Herraa ja sanoi: \"Mitä minä teen tälle kansalle? Ei paljon puutu, että he kivittävät minut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Herra vastasi Moosekselle: \"Mene kansan edellä ja ota mukaasi muutamia Israelin vanhimpia. Ja ota käteesi sauva, jolla löit Niilivirtaa, ja mene.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Katso, minä seison siellä sinun edessäsi kalliolla Hoorebin luona; lyö kallioon, ja siitä on vuotava vettä, niin että kansa saa juoda.\" Ja Mooses teki niin Israelin vanhimpain nähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Ja hän antoi sille paikalle nimen Massa ja Meriba sentähden, että israelilaiset siellä riitelivät ja kiusasivat Herraa, sanoen: \"Onko Herra meidän keskellämme vai ei?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Sitten tulivat amalekilaiset ja taistelivat Israelia vastaan Refidimissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Niin Mooses sanoi Joosualle: \"Valitse meille miehiä, mene ja taistele huomenna amalekilaisia vastaan. Minä asetun vuoren huipulle, Jumalan sauva kädessäni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Ja Joosua teki, niinkuin Mooses oli hänelle sanonut, ja taisteli amalekilaisia vastaan. Mutta Mooses, Aaron ja Huur nousivat vuoren huipulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Ja niin kauan kuin Mooses piti kätensä ylhäällä, oli Israel voitolla; mutta kun hän antoi kätensä vaipua, olivat amalekilaiset voitolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Mutta kun Mooseksen kädet väsyivät, ottivat he kiven ja asettivat sen hänen allensa, ja hän istui sille, ja Aaron ja Huur kannattivat hänen käsiänsä kumpikin puoleltansa. Näin hänen kätensä kestivät vahvoina auringon laskuun asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Ja Joosua voitti amalekilaiset ja heidän sotaväkensä miekan terällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Ja Herra sanoi Moosekselle: \"Kirjoita tämä kirjaan muistoksi ja teroita se Joosuan mieleen: Minä pyyhin pois amalekilaisten muiston taivaan alta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Ja Mooses rakensi alttarin ja pani sille nimeksi: \"Herra on minun lippuni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Ja hän sanoi: \"Minä nostan käteni Herran istuinta kohden: Herra sotii amalekilaisia vastaan sukupolvesta sukupolveen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Ja Midianin pappi Jetro, Mooseksen appi, sai kuulla kaikki, mitä Jumala oli tehnyt Moosekselle ja kansalleen Israelille, kuinka Herra oli vienyt Israelin pois Egyptistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Ja Jetro, Mooseksen appi, otti mukaansa Sipporan, Mooseksen vaimon, jonka tämä oli lähettänyt kotiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'ja hänen kaksi poikaansa; näistä oli toisen nimi Geersom, koska Mooses oli sanonut: \"Minä olen muukalainen vieraalla maalla\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'ja toisen nimi Elieser, koska hän oli sanonut: \"Isäni Jumala oli minun apuni ja pelasti minut faraon miekasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Ja Jetro, Mooseksen appi, tuli hänen poikiensa ja hänen vaimonsa kanssa Mooseksen luo erämaahan, jossa tämä oli leiriytynyt Jumalan vuoren juurelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Ja hän käski sanoa Moosekselle: \"Minä, Jetro, sinun appesi, ynnä vaimosi kahden poikansa kanssa olemme tulleet luoksesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Niin Mooses meni appeansa vastaan, kumarsi ja suuteli häntä. Ja kun he olivat tervehtineet toisiansa, menivät he telttaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Ja Mooses kertoi apellensa kaikki, mitä Herra oli tehnyt faraolle ja egyptiläisille Israelin tähden, ja kaikki ne vaikeudet, jotka heitä olivat kohdanneet matkalla, ja kuinka Herra oli pelastanut heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Ja Jetro iloitsi kaikesta siitä hyvästä, mitä Herra oli tehnyt Israelille, pelastaessaan heidät egyptiläisten kädestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Ja Jetro sanoi: \"Kiitetty olkoon Herra, joka on pelastanut teidät egyptiläisten ja faraon kädestä, Herra, joka on pelastanut kansansa egyptiläisten vallasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nyt minä tiedän, että Herra on suurempi kaikkia jumalia; sillä sentähden, että egyptiläiset ylpeilivät, on heidän näin käynyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Ja Jetro, Mooseksen appi, toimitti polttouhrin ja teurasuhreja Jumalalle; ja Aaron ja kaikki Israelin vanhimmat tulivat aterioimaan Mooseksen apen kanssa Jumalan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Seuraavana päivänä Mooses istui tuomitsemaan kansaa, ja kansa seisoi Mooseksen ympärillä aamusta iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Kun Mooseksen appi näki kaiken, mitä hän teki kansalle, sanoi hän: \"Mitä tämä puuha on, jota sinulla on kansan kanssa? Miksi sinä istut yksin ja kaikki kansa seisoo ympärilläsi aamusta iltaan asti?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Mooses vastasi apellensa: \"Kansa tulee minun luokseni kysymään Jumalalta neuvoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Kun heillä on jokin riita-asia, tulevat he minun luokseni, ja minä ratkaisen heidän riitansa ja ilmoitan heille Jumalan säädökset ja lait.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Niin Mooseksen appi sanoi hänelle: \"Siinä sinä et menettele viisaasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Sinä uuvutat sekä itsesi että tämän kansan, joka on kanssasi; sillä tämä tehtävä on sinulle liian raskas, etkä sinä voi sitä yksinäsi toimittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Kuule nyt, mitä minä sanon. Minä neuvon sinua, ja Jumala on oleva sinun kanssasi. Ole sinä kansan edusmies Jumalan edessä, ja saata sinä sen asiat Jumalan eteen. Ja opeta heille säädökset ja lait,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'ja neuvo heille tie, jota heidän on kuljettava, ja mitä heidän on tehtävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Mutta valitse koko kansasta kelvollisia ja Jumalaa pelkääväisiä, luotettavia ja väärää voittoa vihaavia miehiä, ja aseta ne heille tuhannen, sadan, viidenkymmenen ja kymmenen päämiehiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Nämä tuomitkoot kansaa joka aika. Kaikki suuret asiat he saattakoot sinun tietoosi, mutta kaikki vähäiset asiat ratkaiskoot itse. Huojenna näin jotakin itseltäsi, ja kantakoot he kuormaa sinun kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Jos näin teet ja Jumala itse sinua näin käskee, niin sinä jaksat sen kestää; ja kaikki tämä kansa saa mennä rauhassa kotiinsa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Ja Mooses noudatti appensa puhetta ja teki kaiken, mitä tämä oli sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Mooses valitsi kelvollisia miehiä koko Israelista ja asetti heidät kansan johtoon, tuhannen, sadan, viidenkymmenen ja kymmenen päämiehiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Nämä tuomitsivat kansaa joka aika. Vaikeat asiat he lykkäsivät Moosekselle, mutta vähäiset asiat he ratkaisivat itse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Sitten Mooses saattoi appensa matkaan, ja tämä meni omaan maahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Kolmantena kuukautena siitä, kun israelilaiset olivat lähteneet Egyptin maasta, juuri samana kuukauden päivänä, he tulivat Siinain erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Sillä he olivat lähteneet Refidimistä, tulleet Siinain erämaahan ja leiriytyneet erämaahan; ja Israel oli siellä leirissä vuoren kohdalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Ja Mooses nousi Jumalan tykö, ja Herra huusi häntä vuorelta ja sanoi: \"Sano näin Jaakobin heimolle ja ilmoita israelilaisille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, '\'Te olette nähneet, mitä minä olen tehnyt egyptiläisille ja kuinka minä olen kantanut teitä kotkan siivillä ja tuonut teidät luokseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Jos te nyt kuulette minun ääntäni ja pidätte minun liittoni, niin te olette minun omaisuuteni ennen kaikkia muita kansoja; sillä koko maa on minun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Ja te olette minulle pappisvaltakunta ja pyhä kansa.\' Sano nämä sanat israelilaisille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Kun Mooses tuli takaisin, kutsui hän kokoon kansan vanhimmat ja puhui heille kaikki ne sanat, jotka Herra oli hänen käskenyt puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Niin koko kansa vastasi yhtenä miehenä ja sanoi: \"Kaiken, mitä Herra on puhunut, me teemme\". Ja Mooses vei kansan vastauksen Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Niin Herra sanoi Moosekselle: \"Katso, minä tulen sinun tykösi paksussa pilvessä, että kansa kuulisi, kun minä puhun sinun kanssasi, ja uskoisi myös sinua ainiaan\". Ja Mooses ilmoitti Herralle kansan vastauksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Niin Herra sanoi Moosekselle: \"Mene kansan luo ja pyhitä heidät tänä päivänä ja huomenna, ja peskööt he vaatteensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Ja olkoot valmiit kolmanneksi päiväksi; sillä kolmantena päivänä Herra astuu koko kansan nähden alas Siinain vuorelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Ja merkitse raja kansalle yltympäri ja sano: \'Varokaa nousemasta vuorelle tahi koskettamasta sen juureen. Jokainen, joka vuoreen koskee, rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Älköön kenenkään käsi häneen koskeko, vaan hänet kivitettäköön tahi ammuttakoon kuoliaaksi. Olipa eläin tai ihminen, ei se saa jäädä eloon.\' Vasta kun pitkä torven puhallus kuuluu, he nouskoot vuorelle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Ja Mooses astui alas vuorelta kansan luo; ja hän pyhitti kansan, ja he pesivät vaatteensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Ja hän sanoi kansalle: \"Olkaa kolmanneksi päiväksi valmiit; älköön kukaan ryhtykö naiseen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Ja kolmantena päivänä, kun aamu oli tullut, alkoi jylistä ja salamoida, ja paksu pilvi laskeutui vuoren ylle, ja kuului ylen kova pasunan ääni, niin että koko kansa, joka oli leirissä, vapisi pelosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Silloin Mooses vei kansan leiristä Jumalaa vastaan, ja he asettuivat vuoren juurelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Ja koko Siinain vuori peittyi savuun, kun Herra astui sille alas tulessa, ja siitä nousi savu niinkuin pätsin savu, ja koko vuori vapisi kovasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Ja pasunan ääni koveni kovenemistaan. Mooses puhui, ja Jumala vastasi hänelle jylinällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Ja Herra astui alas Siinain vuorelle, vuoren kukkulalle, ja Herra kutsui Mooseksen vuoren kukkulalle; ja Mooses nousi sinne ylös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Niin Herra sanoi Moosekselle: \"Astu alas ja varoita kansaa tunkeutumasta lähelle Herraa, häntä nähdäkseen, sillä silloin heistä monta kaatuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Papitkin, jotka saavat lähestyä Herraa, pyhittäkööt itsensä, ettei Herra heitä tuhoaisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Mutta Mooses vastasi Herralle: \"Kansa ei voi nousta Siinain vuorelle, sillä sinä olet varoittanut meitä ja sanonut: \'Merkitse raja vuoren ympäri ja pyhitä se\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Niin Herra sanoi hänelle: \"Astu alas ja tule taas ylös, sinä ja Aaron sinun kanssasi. Mutta papit ja kansa älkööt tunkeutuko ylös, Herraa lähelle, ettei hän heitä tuhoaisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Ja Mooses astui alas kansan luo ja sanoi heille tämän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Ja Jumala puhui kaikki nämä sanat ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '\"Minä olen Herra, sinun Jumalasi, joka vein sinut pois Egyptin maasta, orjuuden pesästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Älä pidä muita jumalia minun rinnallani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Älä tee itsellesi jumalankuvaa äläkä mitään kuvaa, älä niistä, jotka ovat ylhäällä taivaassa, älä niistä, jotka ovat alhaalla maan päällä, äläkä niistä, jotka ovat vesissä maan alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Älä kumarra niitä äläkä palvele niitä. Sillä minä, Herra, sinun Jumalasi, olen kiivas Jumala, joka kostan isien pahat teot lapsille kolmanteen ja neljänteen polveen, niille, jotka minua vihaavat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'mutta teen laupeuden tuhansille, jotka minua rakastavat ja pitävät minun käskyni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Älä turhaan lausu Herran, sinun Jumalasi, nimeä, sillä Herra ei jätä rankaisematta sitä, joka hänen nimensä turhaan lausuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Muista pyhittää lepopäivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Kuusi päivää tee työtä ja toimita kaikki askareesi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'mutta seitsemäs päivä on Herran, sinun Jumalasi, sapatti; silloin älä mitään askaretta toimita, älä sinä älköönkä sinun poikasi tai tyttäresi, sinun palvelijasi tai palvelijattaresi tai juhtasi älköönkä muukalaisesi, joka sinun porteissasi on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Sillä kuutena päivänä Herra teki taivaan ja maan ja meren ja kaikki, mitä niissä on, mutta seitsemäntenä päivänä hän lepäsi; sentähden Herra siunasi lepopäivän ja pyhitti sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Kunnioita isääsi ja äitiäsi, että kauan eläisit siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Älä tapa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Älä tee huorin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Älä varasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Älä sano väärää todistusta lähimmäisestäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Älä himoitse lähimmäisesi huonetta. Älä himoitse lähimmäisesi vaimoa äläkä hänen palvelijaansa, palvelijatartaan, härkäänsä, aasiansa äläkä mitään, mikä on lähimmäisesi omaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Ja kaikki kansa havaitsi jylinän, tulen leimaukset, pasunan äänen ja vuoren suitsuamisen; ja kun he sen havaitsivat, vapisivat he ja pysyivät taampana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Ja he sanoivat Moosekselle: \"Puhu sinä meidän kanssamme, niin me kuulemme. Älköön Jumala puhuko meidän kanssamme, ettemme kuolisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Mutta Mooses vastasi kansalle: \"Älkää peljätkö, sillä Jumala on tullut koettelemaan teitä, että Herran pelko olisi teidän silmäinne edessä ja ettette syntiä tekisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Ja kansa pysyi taampana, mutta Mooses lähestyi pimeyttä, jossa Jumala oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Ja Herra sanoi Moosekselle: \"Sano israelilaisille näin: Te olette nähneet, että minä olen puhunut teille taivaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Älkää tehkö jumalia minun rinnalleni; hopeaisia tai kultaisia jumalia älkää tehkö itsellenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Tee minulle alttari maasta, ja uhraa sen päällä polttouhrisi ja yhteysuhrisi, lampaasi ja raavaasi. Joka paikassa, mihin minä säädän nimeni muiston, minä tulen sinun tykösi ja siunaan sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Mutta jos sinä teet minulle kivialttarin, niin älä rakenna sitä hakatusta kivestä; sillä jos sinä kosket taltallasi kiveen, niin sinä saastutat sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Äläkä nouse portaita myöten minun alttarilleni, ettei häpysi sen päällä paljastuisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, '\"Nämä ovat ne oikeudet, jotka sinun tulee asettaa heidän eteensä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Jos sinä ostat hebrealaisen orjan, niin hän palvelkoon kuusi vuotta, mutta seitsemäntenä hän pääsköön vapaaksi maksutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Jos hän on tullut yksinäisenä, niin yksinäisenä lähteköönkin; mutta jos hän oli nainut, niin lähteköön vaimo hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Jos hänen isäntänsä on antanut hänelle vaimon, ja tämä on synnyttänyt hänelle poikia tai tyttäriä, niin vaimo lapsinensa jääköön isännän omaksi, ja hän lähteköön yksinään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Mutta jos orja vakuuttaa: \'Minä rakastan isäntääni, vaimoani ja lapsiani enkä tahdo päästä vapaaksi\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'niin hänen isäntänsä vieköön hänet Jumalan eteen ja asettakoon hänet ovea tai pihtipieltä vasten, ja hänen isäntänsä lävistäköön hänen korvansa naskalilla, ja hän olkoon hänen orjansa ainiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Jos joku myy tyttärensä orjaksi, älköön tämä pääskö vapaaksi, niinkuin miesorjat pääsevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Jos hän ei miellytä isäntäänsä, sitten kuin tämä jo on määrännyt hänet itsellensä, niin tämä sallikoon lunastaa hänet pois. Vieraaseen kansaan älköön hänellä olko valtaa häntä myydä, kun hän hänet hylkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Mutta jos hän määrää hänet pojallensa, niin antakoon hänen nauttia tyttärien oikeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Jos hän ottaa itselleen toisen vaimon, niin älköön vähentäkö ensimmäiseltä tämän ravintoa, vaatetusta ja aviollista oikeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Jos hän ei tee hänelle näitä kolmea, niin lähteköön vaimo pois maksutta ja rahakorvauksetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Joka lyö ihmistä, niin että tämä kuolee, se rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Mutta jos hän ei ole tehnyt sitä murha-aikeessa, vaan Jumala on sallinut sen vahingon tapahtua hänen kätensä kautta, niin minä määrään sinulle paikan, johon hän voi paeta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Mutta jos joku menettelee niin rikollisesti lähimmäistänsä kohtaan, että tappaa hänet kavalasti, on sinun otettava hänet minun alttarinikin luota surmattavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Joka lyö isäänsä tai äitiänsä, se rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Joka varastaa ihmisen ja joko myy hänet tahi pitää häntä hallussansa, se rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Joka kiroaa isäänsä tai äitiänsä, se rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Jos miehet riitelevät keskenänsä ja toinen lyö toista kivellä tai nyrkillä, mutta tämä ei kuole, vaan joutuu vuoteen omaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'niin olkoon, jos hän tointuu ja voi mennä ulos sauvaansa nojaten, lyöjä vapaa rangaistuksesta; korvatkoon ainoastaan hänen sairastamisaikansa ja pitäköön huolta hänen paranemisestaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Jos joku lyö orjaansa tai orjatartaan sauvalla, niin että tämä kuolee hänen käsiinsä, niin häntä rangaistakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Mutta jos se elää päivän tai kaksi, niin älköön lyöjää rangaistako, sillä se on hänen omaa rahaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Jos miehet tappelevat keskenänsä ja loukkaavat raskasta vaimoa, niin että hän synnyttää kesken, mutta vahinkoa ei tapahdu, niin sakotettakoon syyllistä vaimon miehen vaatimuksen ja riidanratkaisijain harkinnan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Mutta jos vahinko tapahtuu, niin annettakoon henki hengestä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'silmä silmästä, hammas hampaasta, käsi kädestä, jalka jalasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'palovamma palovammasta, haava haavasta, mustelma mustelmasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Jos joku lyö orjaansa tai orjatartansa silmään ja turmelee sen, niin päästäköön hänet vapaaksi silmän tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Ja jos hän lyö orjaltaan tai orjattareltaan hampaan suusta, niin päästäköön hänet vapaaksi hampaan tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Jos härkä puskee miehen tai naisen kuoliaaksi, niin härkä kivitettäköön, älköönkä sen lihaa syötäkö; mutta härän omistaja olkoon vapaa rangaistuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Mutta jos härkä on ennenkin puskenut ja sen isäntää on varoitettu eikä hän ole sitä vartioinut, ja jos se tappaa miehen tai naisen, niin härkä kivitettäköön, ja myös sen isäntä rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Mutta jos hänelle määrätään lunastusmaksu, niin maksakoon henkensä lunnaiksi niin paljon, kuin hänelle määrätään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Jos se puskee pojan tai tytön, niin meneteltäköön saman lain mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Jos härkä puskee orjan tai orjattaren, niin maksakoon sen omistaja pusketun isännälle kolmekymmentä hopeasekeliä, ja härkä kivitettäköön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Jos joku jättää kaivon auki tahi kaivaa kaivon eikä peitä sitä, ja härkä tai aasi putoaa siihen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'niin kaivon omistaja korvatkoon isännälle sen rahassa; mutta kuollut eläin olkoon hänen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Jos jonkun härkä puskee toisen härän kuoliaaksi, niin myykööt elävän härän ja jakakoot sen hinnan, ja myös kuolleen jakakoot keskenään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Jos taas oli tunnettua, että se härkä ennenkin oli puskenut eikä sen isäntä ollut sitä vartioinut, niin antakoon härän härästä, mutta kuollut olkoon hänen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, '\"Jos joku varastaa härän tai lampaan ja teurastaa tahi myy sen, antakoon viisi raavasta yhdestä härästä ja neljä lammasta yhdestä lampaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Jos varas tavataan murtautumasta sisälle ja lyödään kuoliaaksi, ei tappaja ole vereen vikapää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Mutta jos aurinko jo oli noussut, niin tappaja on vereen vikapää. Varas maksakoon korvauksen; mutta jos hänellä ei ole mitään, niin myytäköön hänet varastamansa tavaran korvaukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Jos varastettu eläin, olipa se härkä, aasi tai lammas, tavataan hänen hallustaan elävänä, niin korvatkoon sen kaksinkertaisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Jos joku turmelee toiselta pellon tai viinitarhan päästämällä siihen karjansa ja syöttämällä sitä toisen pellossa, antakoon korvaukseksi peltonsa tai viinitarhansa parhaimman kasvun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Jos tuli pääsee irti ja tarttuu orjantappuroihin ja jos kuhilaat tai vilja tai pelto palaa, niin korvatkoon vahingon se, joka on kulovalkean sytyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Jos joku antaa toiselle rahaa tai tavaraa säilytettäväksi ja se varastetaan tämän talosta, niin varas, jos hänet tavataan, korvatkoon sen kaksinkertaisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Mutta jos varasta ei tavata, astukoon talon omistaja Jumalan eteen ja vannokoon, ettei hän ole kädellänsä kajonnut toisen omaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Jokaisessa anastusasiassa, koskipa se härkää tai aasia tai lammasta tai vaatetta tai mitä tahansa kadonnutta, josta joku sanoo: \'Tämä se on\', tulkoon kummankin asia Jumalan eteen; ja se, jonka Jumala tuomitsee syylliseksi, korvatkoon toiselle kaksinkertaisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Jos joku antaa toiselle aasin tai härän tai lampaan tai minkä eläimen tahansa säilytettäväksi ja se kuolee tai vahingoittuu tai ryöstetään pois kenenkään näkemättä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'niin vala Herran edessä ratkaiskoon heidän välillään, onko toinen kädellänsä kajonnut toisen omaan; omistaja hyväksyköön valan, ja toinen olkoon korvauksesta vapaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Mutta jos se on häneltä varastettu, korvatkoon sen omistajalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Jos se on raadeltu, tuokoon sen esiin todistukseksi, eikä hänen tarvitse raadeltua korvata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Jos joku lainaa toiselta elukan ja se vahingoittuu tai kuolee eikä sen omistaja ole saapuvilla, korvatkoon sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Jos sen omistaja on saapuvilla, ei tarvitse korvausta maksaa; jos se oli vuokralla, olkoon vuokra korvauksena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Jos joku viettelee neitsyen, joka ei ole kihlattu, ja makaa hänet, maksakoon hänestä morsiamenhinnan ja ottakoon hänet vaimokseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Jos isä kieltäytyy antamasta häntä hänelle, maksakoon mies rahassa morsiamenhinnan niinkuin neitsyestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Velhonaisen älä salli elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Jokainen, joka sekaantuu eläimeen, rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Joka uhraa muille jumalille kuin Herralle, ainoalle, olkoon vihitty tuhon omaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Älä sorra äläkä ahdista muukalaista, sillä te olette itse olleet muukalaisina Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Älkää sortako leskeä tai orpoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Sillä jos sinä sorrat heitä ja he huutavat minua avuksensa, niin minä totisesti kuulen heidän huutonsa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'ja minun vihani syttyy, ja minä surmaan teidät miekalla, niin että teidän vaimonne joutuvat leskiksi ja lapsenne orvoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Jos lainaat rahaa jollekin minun kansastani, jollekin köyhälle, joka on sinun luonasi, niin älä menettele koronkiskurin tavoin häntä kohtaan. Älkää panko korkoa hänen maksettavakseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Jos sinä olet lähimmäiseltäsi ottanut pantiksi vaipan, anna se hänelle takaisin, ennenkuin aurinko laskee;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'sillä se on hänen ainoa peitteensä, johon hän käärii ruumiinsa. Missä hän muutoin makaisi? Ja jos hän huutaa minua avukseen, kuulen minä häntä, sillä minä olen laupias.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Jumalaa älä herjaa, ja kansasi ruhtinasta älä kiroa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Älä viivyttele antamasta antia vilja-ja mehusatosi runsaudesta. Esikoinen pojistasi anna minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Samoin tee raavaittesi ja lampaittesi ensiksisyntyneelle. Seitsemän päivää se olkoon emänsä kanssa; kahdeksantena päivänä anna se minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Ja te olkaa minulle pyhä kansa. Älkää syökö kedolla raadellun eläimen lihaa, vaan heittäkää se koirille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, '\"Älä levitä valheellista huhua, äläkä anna apuasi syylliselle rupeamalla vääräksi todistajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Älä ole joukon mukana tekemässä pahaa, äläkä todista riita-asiassa niin, että taivut joukon mukaan ja väännät oikean vääräksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Älä ole puolueellinen alhaisen hyväksi hänen asiassansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Jos tapaat vihollisesi härän tai aasin eksyksissä, niin saata se hänelle takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Jos näet vihamiehesi aasin makaavan kuormansa alla, niin älä jätä häntä auttamatta, vaan auta häntä sitä päästämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Älä väännä vääräksi keskuudessanne asuvan köyhän oikeutta hänen riita-asiassansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Pysy erilläsi väärästä asiasta, äläkä surmaa viatonta ja syytöntä, sillä minä en julista syyllistä syyttömäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Äläkä ota lahjusta, sillä lahjus sokaisee näkevät ja vääristää syyttömien asiat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Muukalaista älä sorra, sillä te tiedätte muukalaisen mielialan, koska itsekin olette olleet muukalaisina Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Kuutena vuotena kylvä maasi ja korjaa sen sato.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Mutta seitsemäntenä vuotena jätä se korjaamatta ja lepäämään, että kansasi köyhät saisivat siitä syödä; ja mitä jäljelle jää, sen metsän eläimet syökööt. Samoin tee viinitarhallesi ja öljytarhallesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Kuusi päivää tee työtäsi, mutta lepää seitsemäs päivä, että härkäsi ja aasisi saisivat hengähtää ja orjattaresi poika ynnä muukalainen saisivat virkistyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Kaikkea, mitä minä olen sanonut teille, noudattakaa. Vierasten jumalien nimiä älkää mainitko, älköön niitä kuuluko teidän huuliltanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Kolme kertaa vuodessa vietä juhlaa minun kunniakseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Pidä happamattoman leivän juhla: seitsemänä päivänä syö happamatonta leipää, niinkuin minä olen sinua käskenyt, määrättynä aikana aabib-kuussa, sillä siinä kuussa sinä olet lähtenyt Egyptistä; mutta tyhjin käsin älköön tultako minun kasvojeni eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Ja vietä leikkuujuhla, kun leikkaat uutiset viljastasi, jonka olet kylvänyt vainioon, ja korjuujuhla vuoden lopussa, kun korjaat satosi vainiolta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Kolme kertaa vuodessa tulkoon kaikki sinun miesväkesi Herran, Herran, kasvojen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Älä uhraa minun teurasuhrini verta happamen leivän ohella. Ja minun juhlauhrini rasvaa älköön jääkö yön yli seuraavaan aamuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Parhaat maasi uutisesta tuo Herran, Jumalasi, huoneeseen. Älä keitä vohlaa emänsä maidossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Katso, minä lähetän enkelin sinun edellesi varjelemaan sinua tiellä ja johdattamaan sinua siihen paikkaan, jonka minä olen valmistanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Ole varuillasi hänen edessään ja kuule häntä äläkä pahoita hänen mieltänsä. Hän ei jätä teidän rikoksianne rankaisematta, sillä minun nimeni on hänessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Mutta jos sinä kuulet häntä ja teet kaikki, mitä minä käsken, niin minä olen sinun vihollistesi vihollinen ja vastustajaisi vastustaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Sillä minun enkelini käy sinun edelläsi ja johdattaa sinut amorilaisten, heettiläisten, perissiläisten, kanaanilaisten, hivviläisten ja jebusilaisten maahan, ja minä hävitän heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Älä kumarra heidän jumaliansa, älä palvele niitä äläkä tee, niinkuin he tekevät, vaan kukista ne maahan ja murskaa niiden patsaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Palvelkaa Herraa, Jumalaanne, niin hän siunaa sinun ruokasi ja juomasi, ja minä pidän puutteen sinusta kaukana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Ei keskensynnyttäjää eikä hedelmätöntä ole sinun maassasi oleva. Ja sinun päiviesi luvun minä teen täydeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Minä lähetän kauhuni sinun edelläsi ja saatan hämminkiin kaikki kansat, joiden luo sinä tulet, ja ajan kaikki vihollisesi pakoon sinun edestäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Ja minä lähetän herhiläisiä sinun edelläsi karkoittamaan hivviläiset, kanaanilaiset ja heettiläiset sinun tieltäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Mutta minä en karkoita heitä sinun tieltäsi yhtenä vuotena, ettei maa tulisi autioksi eivätkä metsän pedot lisääntyisi sinun vahingoksesi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'vähitellen minä karkoitan heidät sinun tieltäsi, kunnes olet tullut kyllin lukuisaksi ottamaan haltuusi maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Ja minä asetan sinun rajasi Kaislamerestä filistealaisten mereen ja erämaasta Eufrat-virtaan asti; sillä minä annan maan asukkaat teidän valtaanne, ja sinä karkoitat heidät tieltäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Älä tee liittoa heidän äläkä heidän jumaliensa kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Älkööt he jääkö asumaan sinun maahasi, etteivät saattaisi sinua tekemään syntiä minua vastaan; sillä jos sinä palvelet heidän jumaliansa, on se sinulle paulaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Ja hän sanoi Moosekselle: \"Nouse Herran tykö, sinä ja Aaron, Naadab ja Abihu ynnä seitsemänkymmentä Israelin vanhinta; ja kumartukaa ja rukoilkaa taampana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Mooses yksinään lähestyköön Herraa; muut älkööt lähestykö, ja kansa älköön nousko sinne hänen kanssansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Ja Mooses tuli ja kertoi kansalle kaikki Herran sanat ja kaikki hänen säädöksensä. Niin koko kansa vastasi yhteen ääneen ja sanoi: \"Kaiken, mitä Herra on puhunut, me teemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Sitten Mooses kirjoitti kaikki Herran sanat. Ja hän nousi varhain seuraavana aamuna ja rakensi alttarin vuoren juurelle sekä pystytti kaksitoista patsasta Israelin kahdentoista sukukunnan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Ja hän lähetti israelilaisten joukosta nuoria miehiä uhraamaan polttouhreja ja teurastamaan härkiä yhteysuhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Ja Mooses otti verestä puolet ja pani uhrimaljoihin, ja toisen puolen hän vihmoi alttarille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Ja hän otti liitonkirjan ja luki sen kansan kuullen. Ja he sanoivat: \"Kaikkea, mitä Herra on puhunut, me noudatamme ja tottelemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Niin Mooses otti veren ja vihmoi sitä kansan päälle ja sanoi: \"Katso, tämä on sen liiton veri, jonka Herra on tehnyt teidän kanssanne kaikkien näiden sanojen perusteella\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Ja Mooses ja Aaron, Naadab ja Abihu ynnä seitsemänkymmentä Israelin vanhinta nousivat vuorelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Ja he näkivät Israelin Jumalan; ja hänen jalkainsa alla oli alusta, niinkuin safiirikivistä, kirkas kuin itse taivas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Eikä hän kajonnut kädellänsä israelilaisten valittuihin, ja he katselivat Jumalaa, söivät ja joivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Ja Herra sanoi Moosekselle: \"Nouse minun tyköni vuorelle ja ole siellä, niin minä annan sinulle kivitaulut ynnä lain ja käskyt, jotka minä olen kirjoittanut heille opetukseksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Silloin Mooses ja hänen palvelijansa Joosua lähtivät; ja Mooses nousi Jumalan vuorelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Mutta vanhimmille hän sanoi: \"Odottakaa meitä täällä, kunnes palaamme teidän tykönne. Ja katso, Aaron ja Huur ovat teidän kanssanne; jolla on jotakin asiaa, kääntyköön heidän puoleensa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Kun Mooses oli noussut vuorelle, peitti pilvi vuoren.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Ja Herran kirkkaus laskeutui Siinain vuorelle, ja pilvi peitti sen kuusi päivää; ja seitsemäntenä päivänä hän huusi Moosesta pilven keskeltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Ja Herran kirkkaus vuoren kukkulalla näytti israelilaisten silmissä kuluttavalta tulelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Ja Mooses meni pilven keskelle ja nousi vuorelle. Ja Mooses oli vuorella neljäkymmentä päivää ja neljäkymmentä yötä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, '\"Sano israelilaisille, että he kokoavat anteja minulle; jokaiselta, jonka sydän on siihen altis, ottakaa vastaan anti minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Ja nämä ovat ne annit, joita teidän on otettava vastaan heiltä: kultaa, hopeata ja vaskea,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'punasinisiä, purppuranpunaisia ja helakanpunaisia lankoja ja valkoisia pellavalankoja sekä vuohenkarvoja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'punaisia oinaannahkoja, sireeninnahkoja, akasiapuuta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'ljyä seitsenhaaraista lamppua varten, hajuaineita voiteluöljyä ja hyvänhajuista suitsutusta varten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'onyks-kiviä ja muita jalokiviä kasukkaa ja rintakilpeä varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Ja tehkööt he minulle pyhäkön asuakseni heidän keskellään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Tehkää asumus ja kaikki sen kalusto tarkoin sen kaavan mukaan, jonka minä sinulle näytän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Tehkööt he arkin akasiapuusta, puolenkolmatta kyynärän pituisen, puolentoista kyynärän levyisen ja puolentoista kyynärän korkuisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Ja päällystä se puhtaalla kullalla, päällystä se sisältä ja ulkoa; ja tee siihen kultareunus yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Ja vala siihen neljä kultarengasta ja kiinnitä ne sen neljään jalkaan, niin että kaksi rengasta tulee sen toiselle puolelle ja kaksi rengasta sen toiselle puolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Ja tee korennot akasiapuusta ja päällystä ne kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Ja pistä renkaisiin arkin sivuille korennot, joilla arkki on kannettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Korennot jääkööt arkin renkaisiin, älköönkä niitä vedettäkö pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Ja pane arkkiin laki, jonka minä sinulle annan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Tee myös armoistuin puhtaasta kullasta, puolenkolmatta kyynärän pituinen ja puolentoista kyynärän levyinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Ja tee kaksi kultakerubia, tee ne kohotakoista tekoa, armoistuimen molempiin päihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Tee toinen kerubi toiseen päähän ja toinen kerubi toiseen päähän. Tehkää kerubit armoistuimesta kohoaviksi, sen kumpaankin päähän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Ja kerubit levittäkööt siipensä ylöspäin, niin että ne peittävät siivillänsä armoistuimen, ja niiden kasvot olkoot vastakkain; armoistuinta kohti olkoot kerubien kasvot käännetyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Ja aseta armoistuin arkin päälle ja pane arkkiin laki, jonka minä sinulle annan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Ja siinä minä ilmestyn sinulle ja puhun sinulle armoistuimelta, niiden kahden kerubin välistä, jotka ovat lain arkin päällä, kaiken sen, minkä minä sinun kauttasi israelilaisille säädän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Ja tee pöytä akasiapuusta, kahden kyynärän pituinen, kyynärän levyinen ja puolentoista kyynärän korkuinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Ja päällystä se puhtaalla kullalla ja tee siihen kultareunus yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Ja tee sen ympäri kämmenen korkuinen lista ja listan ympäri kultareunus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Ja tee siihen neljä kultarengasta ja kiinnitä renkaat sen neljään kulmaan, kunkin neljän jalan kohdalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Renkaat olkoot juuri listan alla niiden korentojen pitiminä, joilla pöytä on kannettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Ja tee ne korennot akasiapuusta ja päällystä ne kullalla, ja niillä on pöytä kannettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Tee myös siihen vadit ja kupit, kannut ja maljat, joista juomauhrit vuodatetaan; tee ne puhtaasta kullasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Ja pidä aina minun edessäni pöydällä näkyleivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Ja tee myös seitsenhaarainen lamppu puhtaasta kullasta. Tee lamppu jalkoineen ja varsineen kohotakoista tekoa; sen kukkakuvut, nuput kukkalehtineen, olkoot samaa kappaletta kuin se.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Kuusi haaraa lähteköön lampun sivuista, kolme haaraa toisesta sivusta ja kolme haaraa toisesta sivusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Toisessa haarassa olkoon kolme mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen, ja toisessa haarassa samoin kolme mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen; näin olkoon jokaisessa kuudessa haarassa, jotka lampusta lähtevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Mutta lampussa itsessään olkoon neljä mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Yksi nuppu olkoon aina jokaisen haaraparin alla niistä kuudesta haarasta, jotka lampusta lähtevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Nuput ja haarat olkoot samaa kappaletta kuin se; olkoon se kauttaaltaan samaa kohotakoista tekoa, puhdasta kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Ja tee siihen seitsemän lamppua, ja lamput asetettakoon niin, että seitsenhaarainen lamppu heittää valonsa etupuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Ja sen lamppusakset ja karstakupit olkoot puhdasta kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Yhdestä talentista puhdasta kultaa tehtäköön sekä se että kaikki nämä kalut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Ja katso, että teet ne sen kaavan mukaan, joka sinulle niistä vuorella näytettiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, '\"Ja tee asumus kymmenestä telttakankaan kaistasta, jotka ovat valmistetut kerratuista valkoisista pellavalangoista ja punasinisistä, purppuranpunaisista ja helakanpunaisista langoista, ja tee niihin taidokkaasti kudottuja kerubeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Kunkin kaistan pituus olkoon kaksikymmentäkahdeksan kyynärää ja leveys neljä kyynärää; kaikilla kaistoilla olkoon sama mitta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Viisi kaistaa yhdistettäköön toisiinsa, ja samoin toiset viisi kaistaa yhdistettäköön toisiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Ja tee silmukat punasinisestä langasta ensimmäisen kaistan reunaan, yhdistetyn kappaleen laitaan, ja samoin toisen yhdistetyn kappaleen viimeisen kaistan reunaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Tee viisikymmentä silmukkaa ensimmäiseen kaistaan, ja tee viisikymmentä silmukkaa vastaavan kaistan laitaan, toiseen yhdistettyyn kappaleeseen, niin että silmukat ovat kohdakkain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Ja tee viisikymmentä kultahakasta ja yhdistä kaistat toisiinsa näillä hakasilla, niin että siitä tulee yhtenäinen asumus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Tee vielä kaistoista, jotka ovat kudotut vuohenkarvoista, teltta asumuksen suojaksi; tee niitä kaistoja yksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Kunkin kaistan pituus olkoon kolmekymmentä kyynärää ja leveys neljä kyynärää; niillä yhdellätoista kaistalla olkoon sama mitta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Liitä yhteen viisi kaistaa erikseen ja kuusi kaistaa erikseen, ja aseta kuudes niistä kaksin kerroin teltan etupuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Ja tee viisikymmentä silmukkaa toisen yhdistetyn kappaleen viimeisen kaistan reunaan ja viisikymmentä silmukkaa toisen yhdistetyn kappaleen vastaavan kaistan reunaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Tee myös viisikymmentä vaskihakasta ja pistä hakaset silmukkoihin ja liitä teltta yhteen, niin että siitä tulee yhtenäinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Siitä telttakaistojen liiasta osasta, joka jää riippumaan, jääköön puolet riippumaan asumuksen takasivulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Ja siitä, mikä telttakaistoissa on liikaa pituutta, riippukoon kyynärän verran asumuksen kummallakin sivulla sitä peittämässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Ja tee teltalle peite punaisista oinaannahoista ja sen päälle vielä toinen peite sireeninnahoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Asumuksen laudat tee akasiapuusta, pystyyn asetettaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Jokainen lauta olkoon kymmentä kyynärää pitkä ja puoltatoista kyynärää leveä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Jokaisessa laudassa olkoon kaksi tappia, jotka ovat poikkilistalla yhdistetyt keskenään; tee näin kaikki asumuksen laudat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Ja asumuksen lautoja tee kaksikymmentä lautaa eteläpuolta varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Ja tee neljäkymmentä hopeajalustaa kahdenkymmenen laudan alle, aina kaksi jalustaa kunkin laudan alle sen kahta tappia varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Samoin asumuksen toista sivua, pohjoispuolta, varten kaksikymmentä lautaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'ja neljäkymmentä hopeajalustaa, aina kaksi jalustaa kunkin laudan alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Mutta asumuksen takasivua, länsipuolta, varten tee kuusi lautaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Ja tee kaksi lautaa asumuksen peränurkkia varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Ja ne olkoot yhteenliitettyjä kaksoislautoja ja alhaalta alkaen kiinni toisissaan ylös saakka, ensimmäiseen renkaaseen asti; näin tehtäköön ne molemmat ja asetettakoon kumpaankin nurkkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Näin tulee olemaan yhteensä kahdeksan lautaa ja niihin kuusitoista hopeajalustaa, aina kaksi jalustaa kunkin laudan alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Tee myös viisi poikkitankoa akasiapuusta asumuksen toisen sivun lautoja varten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'ja viisi poikkitankoa asumuksen toisen sivun lautoja varten, ja viisi poikkitankoa asumuksen takasivun, länsipuolen, lautoja varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Ja keskimmäinen poikkitanko asetettakoon keskelle lautoja, ja kulkekoon se reunasta reunaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Ja päällystä laudat kullalla ja tee kullasta niiden renkaat poikkitankojen pitimiksi ja päällystä poikkitangot kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Ja aseta asumus pystyyn sen muotoiseksi, kuin sinulle vuorella näytettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Tee vielä esirippu punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista; ja tehtäköön siihen taidokkaasti kudottuja kerubeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Ja ripusta se neljään akasiapuiseen, kullalla päällystettyyn pylvääseen, joissa on kultakoukut ja jotka seisovat neljällä hopeajalustalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Ja ripusta esirippu hakasten alle ja vie sinne esiripun sisäpuolelle lain arkki. Ja niin olkoon esirippu teille väliseinänä pyhän ja kaikkeinpyhimmän välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Ja aseta armoistuin lain arkin päälle, joka on kaikkeinpyhimmässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Mutta pöytä sijoita esiripun ulkopuolelle ja seitsenhaarainen lamppu vastapäätä pöytää, asumuksen eteläsivulle; aseta siis pöytä pohjoissivulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Tee myös teltan oveen uudin, kirjaellen kudottu punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Ja tee uudinta varten viisi pylvästä akasiapuusta ja päällystä ne kullalla, mutta niiden koukut olkoot kultaa; ja vala niille viisi vaskijalustaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, '\"Ja tee alttari akasiapuusta; se olkoon neliskulmainen, viittä kyynärää pitkä ja viittä kyynärää leveä sekä kolmea kyynärää korkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Tee siihen sarvet, sen neljään kulmaan, niin että sarvet ovat samaa kappaletta kuin se. Ja päällystä se vaskella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Tee siihen kuuluvat kattilat tuhan poisviemistä varten sekä lapiot, maljat, haarukat ja hiilipannut. Kaikki sen kalusto tee vaskesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Ja tee siihen myös verkonkaltainen ristikkokehys vaskesta ja tee verkkoon neljä vaskirengasta, ristikon neljään kulmaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Ja aseta se alttarin välireunuksen alle, maahan kiinni, niin että verkko ulottuu puolitiehen alttaria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Ja tee alttariin korennot akasiapuusta ja päällystä ne vaskella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Ja korennot pistettäköön renkaisiin, niin että korennot ovat kahden puolen alttaria, sitä kannettaessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Tee se laudoista, ontoksi. Niinkuin sinulle näytettiin vuorella, niin se tehtäköön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Tee myös asumukselle esipiha. Etelän puolella olkoot esipihan ympärysverhot kerratuista valkoisista pellavalangoista, sadan kyynärän pituiset tätä yhtä sivua varten;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'ja olkoon niiden pylväitä kaksikymmentä ja näiden vaskijalustoja kaksikymmentä, mutta pylväiden koukut ja niiden koristepienat olkoot hopeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Samoin myös pohjoisen puolella olkoot ympärysverhot sadan kyynärän pituiset; ja olkoon niiden pylväitä kaksikymmentä ja näiden vaskijalustoja kaksikymmentä, mutta pylväiden koukut ja niiden koristepienat olkoot hopeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Ja esipihan lännenpuoleisella sivulla olkoot ympärysverhot viidenkymmenen kyynärän pituiset, ja olkoon niiden pylväitä kymmenen ja näiden jalustoja kymmenen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Ja esipihan leveys etupuolella, itään päin, olkoon viisikymmentä kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Ja olkoot ympärysverhot portin toisella puolella viidentoista kyynärän pituiset, ja olkoon niiden pylväitä kolme ja näiden jalustoja kolme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Samoin olkoot ympärysverhot toisella puolella viidentoista kyynärän pituiset, ja olkoon niiden pylväitä kolme ja näiden jalustoja kolme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Ja esipihan portissa olkoon kahdenkymmenen kyynärän pituinen uudin, kirjaellen kudottu punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista, ja olkoon sen pylväitä neljä ja näiden jalustoja neljä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Kaikissa pylväissä esipihan ympärillä olkoot koristepienat hopeata ja koukut hopeata, mutta jalustat vaskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Esipihan pituus olkoon sata kyynärää ja leveys viisikymmentä kyynärää; ympärysverho olkoon viittä kyynärää korkea ja kudottu kerratuista valkoisista pellavalangoista, ja jalustat olkoot vaskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Koko asumuksen kalusto kaikkia siinä tehtäviä töitä varten, samoin kuin kaikki sen vaarnat ja kaikki esipihan vaarnat, olkoot vaskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Ja käske israelilaisten tuoda sinulle puhdasta, survomalla saatua öljypuun öljyä seitsenhaaraista lamppua varten, että lamput aina voidaan nostaa paikoilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Ilmestysmajassa, ulkopuolella esirippua, joka on lain arkin edessä, hoitakoon Aaron poikineen niitä illasta aamuun asti Herran edessä. Tämä olkoon ikuinen säädös, jota israelilaiset noudattakoot sukupolvesta sukupolveen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, '\"Ja kutsu eteesi israelilaisten joukosta veljesi Aaron poikineen, että he pappeina palvelisivat minua, Aaron ja hänen poikansa Naadab ja Abihu, Eleasar ja Iitamar.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Ja teetä veljellesi Aaronille pyhät vaatteet, kunniaksi ja kaunistukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Ja puhuttele kaikkia taidollisia miehiä, jotka minä olen täyttänyt taidollisuuden hengellä, että he tekevät vaatteet Aaronille, jotta hänet pyhitettäisiin pappina palvelemaan minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Ja nämä ovat ne vaatteet, jotka heidän on tehtävä: rintakilpi, kasukka, viitta, ruutuinen ihokas, käärelakki ja vyö. Ja he tehkööt sinun veljellesi Aaronille ja hänen pojilleen pyhät vaatteet, että he pappeina palvelisivat minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Ja he ottakoot tätä varten kultaa sekä punasinisiä, purppuranpunaisia ja helakanpunaisia lankoja ja valkoisia pellavalankoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Kasukan he tehkööt kullasta sekä punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista, taidokkaasti kutomalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Siinä olkoon kaksi yhdistettävää olkakappaletta, ja se kiinnitettäköön niihin molemmista päistään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Ja vyö, jolla kasukka kiinnitetään, olkoon tehty samalla tavalla ja samasta kappaleesta kuin se: kullasta sekä punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Ota sitten kaksi onyks-kiveä ja kaiverra niihin Israelin poikien nimet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'kuusi heidän nimeään toiseen kiveen ja toiset kuusi nimeä toiseen kiveen siinä järjestyksessä, kuin he ovat syntyneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Niinkuin taidokkaasti hiotaan kiveä, kaiverretaan sinettisormuksia, niin kaiverra Israelin poikien nimet niihin kahteen kiveen. Ja kehystettäköön ne kultapalmikoimilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Ja pane molemmat kivet kasukan olkakappaleihin kiviksi, jotka johdattavat muistoon israelilaiset; näin Aaron kantakoon heidän nimiänsä molemmilla olkapäillään Herran kasvojen edessä, että heitä muistettaisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Ja tee kultapalmikoimia');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'ja kahdet käädyt puhtaasta kullasta; tee ne punomalla, niinkuin punonnaista tehdään, ja kiinnitä punotut käädyt palmikoimiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Ja jumalanvastausten rintakilpi tee taidokkaasti kutomalla; tee sekin samalla tavalla, kuin kasukka on tehty: tee se kullasta sekä punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Se olkoon neliskulmainen ja taskun muotoon tehty, vaaksan pituinen ja vaaksan levyinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Ja kiinnitä sen pintaan kiviä yliyltään, neljään riviin: ensimmäiseen riviin karneoli, topaasi ja smaragdi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'toiseen riviin rubiini, safiiri ja jaspis;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'kolmanteen riviin hyasintti, akaatti ja ametisti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'ja neljänteen riviin krysoliitti, onyks ja berylli. Kultapalmikoimilla kehystettyinä kiinnitettäköön ne paikoilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Kiviä olkoon Israelin poikain nimien mukaan kaksitoista, yksi kutakin nimeä kohti; kussakin kivessä olkoon yksi kahdentoista sukukunnan nimistä, kaiverrettuna samalla tavalla, kuin kaiverretaan sinettisormuksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Ja tee rintakilpeen puhtaasta kullasta käädyt, punotut, niinkuin punonnaista tehdään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Ja tee rintakilpeen kaksi kultarengasta ja kiinnitä molemmat renkaat rintakilven kahteen yläkulmaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Ja kiinnitä ne molemmat kultapunonnaiset kahteen renkaaseen rintakilven yläkulmiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Ja kiinnitä molempien punonnaisten toiset kaksi päätä kahteen palmikoimaan ja kiinnitä nämä kasukan olkakappaleihin, sen etupuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Ja tee vielä kaksi kultarengasta ja pane ne rintakilven molempiin alakulmiin, sen sisäpuoliseen, kasukkaa vasten olevaan reunaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Ja tee vieläkin kaksi kultarengasta ja kiinnitä ne kasukan molempiin olkakappaleihin, niiden alareunaan, etupuolelle, sauman kohdalle, kasukan vyön yläpuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Ja rintakilpi solmittakoon renkaistaan punasinisellä nauhalla kasukan renkaisiin, niin että se on kasukan vyön yläpuolella; näin rintakilpi ei irtaudu kasukasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Ja niin Aaron kantakoon jumalanvastausten rintakilvessä sydämensä päällä, astuessaan pyhäkköön, Israelin poikain nimet, että heidät alati johdatettaisiin muistoon Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Ja pane jumalanvastausten rintakilpeen uurim ja tummim, niin että ne ovat Aaronin sydämen päällä, hänen astuessaan Herran eteen. Ja niin kantakoon Aaron Jumalan vastaukset israelilaisille sydämensä päällä aina Herran edessä ollessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Kasukan viitta tee kokonaan punasinisistä langoista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'ja sen keskellä olkoon pääntie, ja tämä pääntie ympäröitäköön kudotulla päärmeellä niinkuin haarniskan aukko, ettei se repeäisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Ja tee sen helmaan granaattiomenia punasinisistä, purppuranpunaisista ja helakanpunaisista langoista, ja kiinnitä ne helmaan ympärinsä ja niiden väliin kultatiukuja yltympäri,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'vuorotellen kultatiuku ja granaattiomena, viitan helmaan ympärinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Ja Aaron pitäköön sen yllään toimittaessaan virkaansa, niin että kuuluu, kun hän menee pyhäkköön Herran eteen ja tulee sieltä ulos, ettei hän kuolisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Tee myös otsakoriste puhtaasta kullasta ja kaiverra siihen, niinkuin sinettisormusta kaiverretaan, sanat: \'Herralle pyhitetty\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Ja sido se punasinisellä nauhalla, niin että se on kiinni käärelakissa; etupuolella käärelakkia se olkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Ja se olkoon Aaronin otsalla, niin että Aaron kantaa kaiken sen, mitä israelilaiset rikkovat uhratessaan pyhiä uhrejansa ja antaessaan pyhiä lahjojansa; ja se olkoon alati hänen otsallaan, että Herran mielisuosio tulisi heidän osaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Kudo myös ruutuinen ihokas valkoisista pellavalangoista, ja tee käärelakki valkoisista pellavalangoista, ja tee vyö kirjokudoksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Ja Aaronin pojille tee ihokkaat ja vyöt; ja tee heille päähineet kunniaksi ja kaunistukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Ja pue ne veljesi Aaronin ja hänen poikiensa ylle; ja voitele heidät ja vihi heidät virkaansa ja pyhitä heidät pappeina palvelemaan minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Ja tee heille pellavakaatiot hävyn peitteeksi; ulottukoot ne lanteilta reisiin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Ja Aaron ja hänen poikansa pitäkööt ne yllään mennessänsä ilmestysmajaan, tahi kun he lähestyvät alttaria tehdäkseen palvelusta pyhäkössä, etteivät he joutuisi syynalaisiksi ja kuolisi. Tämä olkoon ikuinen säädös hänelle ja hänen jälkeläisilleen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, '\"Tee heille näin, pyhittääksesi heidät pappeina palvelemaan minua: Ota mullikka ja kaksi virheetöntä oinasta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'ja happamatonta leipää ja öljyyn leivottuja happamattomia kakkuja ja öljyllä voideltuja happamattomia ohukaisia; leivo ne lestyistä nisujauhoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Ja pane ne samaan koriin ja tuo ne korissa, samalla kertaa kuin tuot mullikan ja kaksi oinasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Tuo sitten Aaron poikinensa ilmestysmajan ovelle ja pese heidät vedellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Ja ota vaatteet ja pue Aaronin ylle ihokas ja kasukan viitta ja kasukka ja rintakilpi; ja sido hänen ympärilleen kasukan vyö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Pane myös käärelakki hänen päähänsä ja kiinnitä pyhä otsalehti käärelakkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Ja ota voiteluöljyä ja vuodata hänen päähänsä ja voitele hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Ja tuo hänen poikansa esille ja pue heidän ylleen ihokkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Ja vyötä heidät vyöllä, sekä Aaron että hänen poikansa, ja sido päähineet heidän päähänsä, että pappeus olisi heillä ikuisena säätynä. Vihi näin virkaansa Aaron ja hänen poikansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Ja tuo mullikka ilmestysmajan eteen, ja Aaron poikineen laskekoon kätensä mullikan pään päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Ja teurasta sitten mullikka Herran edessä, ilmestysmajan ovella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Ja ota mullikan verta ja sivele sitä sormellasi alttarin sarviin; mutta kaikki muu veri vuodata alttarin juurelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Ja ota kaikki sisälmyksiä peittävä rasva ja maksanlisäke ja molemmat munuaiset ynnä niiden päällä oleva rasva, ja polta ne alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Mutta mullikan liha, nahka ja rapa polta tulessa leirin ulkopuolella. Se on syntiuhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Ja ota toinen oinaista, ja Aaron poikinensa laskekoon kätensä sen oinaan pään päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Teurasta sitten oinas ja ota sen veri ja vihmo se alttarille ympärinsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'ja leikkele oinas määräkappaleiksi ja pese sen sisälmykset ja jalat ja pane ne kappaleiden ja pään päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Ja polta koko oinas alttarilla. Se on polttouhri Herralle, se on suloisesti tuoksuva uhri Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Ota sitten toinen oinas, ja Aaron poikinensa laskekoon kätensä oinaan pään päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Ja teurasta oinas ja ota sen verta ja sivele Aaronin ja hänen poikiensa oikean korvan lehteen ja oikean käden peukaloon ja heidän oikean jalkansa isoonvarpaaseen, mutta vihmo muu veri alttarille ympärinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Ja ota alttarilla olevaa verta ja voiteluöljyä ja pirskoita Aaronin ja hänen vaatteidensa päälle, ja samoin hänen poikiensa ja heidän vaatteidensa päälle. Näin hän tulee pyhäkölle pyhitetyksi, sekä hän itse että hänen vaatteensa, ja samoin hänen poikansa ja hänen poikiensa vaatteet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Ota sitten oinaasta rasva ja rasvahäntä ja sisälmyksiä peittävä rasva ja maksanlisäke ja molemmat munuaiset ynnä niiden päällä oleva rasva ja oikea reisi, sillä tämä on vihkiäisoinas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Ja ota pyöreä leipä ja öljyyn leivottu kakku ja ohukainen happamattomien leipien korista, joka on Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Ja pane kaikki nämä Aaronin käsiin ja hänen poikiensa käsiin, että toimitettaisiin niiden heilutus Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Ota ne sitten heidän käsistään ja polta alttarilla, polttouhrin päällä, suloiseksi tuoksuksi Herran edessä. Se on Herran uhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Ja ota rintaliha Aaronin vihkiäisoinaasta ja toimituta sen heilutus Herran edessä; ja se olkoon sinun osasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Näin sinun on pyhitettävä heilutettu rintaliha ja anniksi annettu reisi, se, mitä on heilutettu ja anniksi annettu Aaronin ja hänen poikiensa vihkiäisoinaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Ja ne olkoot Aaronin ja hänen poikiensa ikuinen osuus, israelilaisilta saatu, sillä se on anti. Se olkoon israelilaisten anti heidän yhteysuhreistaan, heidän antinsa Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Aaronin pyhät vaatteet tulkoot hänen pojillensa hänen jälkeensä, että heidät niissä voideltaisiin ja vihittäisiin virkaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Seitsemänä päivänä on sen hänen pojistaan, joka tulee papiksi hänen sijaansa, puettava ne ylleen, kun hän menee ilmestysmajaan toimittamaan virkaansa pyhäkössä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Ja ota vihkiäisoinas ja keitä sen liha pyhässä paikassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Ja Aaron poikinensa syököön ilmestysmajan ovella oinaan lihan ynnä leivän, joka on korissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'He syökööt sen, mitä käytettiin heidän sovittamisekseen, kun heidät vihittiin virkaansa ja pyhitettiin, mutta syrjäinen älköön sitä syökö, sillä se on pyhää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Jos jotakin jää tähteeksi vihkiäislihasta tai leivästä seuraavaan aamuun, polta tähteeksi jäänyt tulessa; älköön sitä syötäkö, sillä se on pyhää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Tee näin Aaronille ja hänen pojillensa, aivan niinkuin minä olen sinua käskenyt. Seitsemän päivää kestäköön heidän vihkimisensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Ja uhraa joka päivä syntiuhrimullikka sovitukseksi, ja puhdista alttari toimittamalla sen sovitus ja voitele se pyhittääksesi sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Seitsemänä päivänä toimita alttarin sovitus ja pyhitä se. Näin tulee alttarista korkeasti-pyhä; jokainen, joka alttariin koskee, on pyhäkölle pyhitetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Ja uhraa alttarilla tämä: kaksi vuodenvanhaa karitsaa joka päivä, ainiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Uhraa toinen karitsa aamulla ja toinen karitsa iltahämärässä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'ja kumpaakin karitsaa kohti kymmenennes lestyjä jauhoja, sekoitettuna neljännekseen hiin-mittaa survomalla saatua öljyä, ja juomauhriksi neljännes hiin-mittaa viiniä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Ja uhraa toinen karitsa iltahämärässä; uhrattakoon se toimittamalla samankaltainen ruokauhri ja juomauhri kuin aamullakin, suloisesti tuoksuvaksi uhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Tämä olkoon teillä jokapäiväinen polttouhri sukupolvesta sukupolveen ilmestysmajan ovella Herran edessä, jossa minä ilmestyn teille puhuakseni sinun kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Siinä minä ilmestyn israelilaisille, ja se on oleva minun kirkkauteni pyhittämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Ja minä pyhitän ilmestysmajan ja alttarin; ja minä pyhitän Aaronin poikinensa pappeina palvelemaan minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Ja minä asun israelilaisten keskellä ja olen heidän Jumalansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Ja he tulevat tietämään, että minä olen Herra, heidän Jumalansa, joka vein heidät pois Egyptin maasta, asuakseni heidän keskellään. Minä olen Herra, heidän Jumalansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, '\"Tee myös alttari suitsutuksen polttamista varten; tee se akasiapuusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Olkoon se kyynärän pituinen ja kyynärän levyinen, siis neliskulmainen, ja kahta kyynärää korkea; sen sarvet olkoot samaa kappaletta kuin sekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Ja päällystä se puhtaalla kullalla, sekä sen levy että sivut ympärinsä ja sen sarvet; ja tee kultareunus sen ympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Ja tee siihen kaksi kultarengasta; pane ne reunuksen alle, kummallekin sivulle, molempiin sivukappaleihin. Ne olkoot niiden korentojen pitiminä, joilla alttari on kannettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Ja tee korennotkin akasiapuusta ja päällystä ne kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Ja aseta se lain arkin edessä olevan esiripun eteen, niin että se tulee armoistuimen kohdalle, joka on lain arkin päällä ja jossa minä sinulle ilmestyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Ja Aaron polttakoon sen päällä hyvänhajuista suitsutusta; joka aamu, kun hän laittaa lamput kuntoon, hän polttakoon sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Samoin myös, kun Aaron iltahämärässä nostaa lamput paikoilleen, hän polttakoon sitä. Tämä olkoon teillä jokapäiväinen suitsutusuhri Herran edessä sukupolvesta sukupolveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Älkää uhratko sen päällä vierasta suitsutusta älkääkä polttouhria tai ruokauhria; älkää myöskään vuodattako juomauhria sen päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Ja Aaron toimittakoon kerran vuodessa sen sarvien sovituksen; sovitukseksi uhratun syntiuhrin verellä hän toimittakoon kerran vuodessa sen sovituksen, sukupolvesta sukupolveen. Se on korkeasti-pyhä Herralle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, '\"Kun sinä lasket israelilaisten lukumäärän-niiden, joiden on oltava katselmuksessa-niin jokainen heistä suorittakoon, heistä katselmusta pidettäessä, hengestään sovitusmaksun Herralle, ettei mikään rangaistus heitä kohtaisi, heistä katselmusta pidettäessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Jokainen katselmuksessa oleva antakoon puoli sekeliä, pyhäkkösekelin painon mukaan, kaksikymmentä geeraa laskettuna sekeliin; puoli sekeliä olkoon anti Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Kaikki katselmuksessa olevat, kaksikymmenvuotiaat ja sitä vanhemmat, antakoot tämän annin Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Rikas älköön antako enemmän älköönkä köyhä vähemmän kuin puoli sekeliä, antina Herralle, maksaaksenne sovituksen hengestänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Ja ota sovitusrahat israelilaisilta ja käytä ne palvelukseen ilmestysmajassa, että israelilaiset johdatettaisiin muistoon Herran edessä teidän henkenne sovitukseksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '\"Tee myös vaskiallas vaskijalustoineen peseytymistä varten ja aseta se ilmestysmajan ja alttarin välille ja kaada siihen vettä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'ja Aaron ja hänen poikansa peskööt siinä kätensä ja jalkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Kun he menevät ilmestysmajaan, peseytykööt vedessä, etteivät kuolisi; samoin myös, kun he lähestyvät alttaria ja käyvät toimittamaan virkaansa polttamalla uhrin Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'He peskööt kätensä ja jalkansa, etteivät kuolisi. Ja tämä olkoon heille ikuinen säädös, hänelle itselleen ja hänen jälkeläisillensä, sukupolvesta sukupolveen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '\"Ota itsellesi hajuaineita parasta lajia: sulavaa mirhaa viisisataa sekeliä, hyvänhajuista kanelia puolet siitä eli kaksisataa viisikymmentä sekeliä ja hyvänhajuista kalmoruokoa samoin kaksisataa viisikymmentä sekeliä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'sitten vielä kassiaa viisisataa sekeliä, pyhäkkösekelin painon mukaan, ja hiin-mitta öljypuun öljyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Ja tee siitä pyhä voiteluöljy, höystetty voide, jollaista voiteensekoittaja valmistaa; se olkoon pyhä voiteluöljy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Voitele sillä ilmestysmaja, lain arkki');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'ja pöytä kaikkine kaluineen, seitsenhaarainen lamppu kaluineen, niin myös suitsutusalttari,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'polttouhrialttari kaikkine kaluineen ynnä allas jalustoineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Ja pyhitä ne, niin että ne tulevat korkeasti-pyhiksi. Jokainen, joka niihin koskee, tulee pyhäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Voitele myös Aaron ja hänen poikansa ja pyhitä heidät pappeina palvelemaan minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Puhu myös israelilaisille ja sano: Tämä olkoon teillä minun pyhä voiteluöljyni sukupolvesta sukupolveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Kenenkään muun ihmisen ruumiille älköön sitä vuodatettako, älkääkä sen sekoitusta jäljitelkö. Pyhä se on, ja pyhänä se pitäkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Jokainen, joka valmistaa sellaisen voiteen, ja jokainen, joka sivelee sitä syrjäiseen, hävitettäköön kansastansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Ja Herra sanoi Moosekselle vielä: \"Ota itsellesi hyvänhajuisia aineita, hajupihkaa, simpukankuorta, tuoksukumia, näitä hyvänhajuisia aineita, ja puhdasta suitsuketta, yhtä paljon kutakin lajia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'ja tee niistä suitsutus, höystesekoitus, jollaista voiteensekoittaja valmistaa, suolansekainen, puhdas ja pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Ja hienonna osa siitä jauhoksi ja pane sitä lain arkin eteen ilmestysmajaan, jossa minä ilmestyn sinulle. Korkeasti-pyhänä se pitäkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Älkää valmistako itsellenne mitään muuta suitsutusta tämän sekoituksen mukaan. Pidä tämä Herralle pyhitettynä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Jokainen, joka sellaista tekee nauttiaksensa sen tuoksusta, hävitettäköön kansastansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '\"Katso, minä olen nimeltään kutsunut Besalelin, Uurin pojan, Huurin pojanpojan, Juudan sukukunnasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'ja minä olen täyttänyt hänet Jumalan hengellä, taidollisuudella, ymmärryksellä, tiedolla ja kaikkinaisella kätevyydellä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'sommittelemaan taidokkaita teoksia ja valmistamaan niitä kullasta, hopeasta ja vaskesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'hiomaan ja kiinnittämään kiviä ja veistämään puuta, tekemään kaikkinaisia töitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Ja katso, minä olen antanut hänelle apulaiseksi Oholiabin, Ahisamakin pojan, Daanin sukukunnasta, ja olen antanut kaikkien taidollisten sydämeen taidollisuuden tehdä kaikki, mitä minä olen sinun käskenyt teettää:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'ilmestysmajan, lain arkin, armoistuimen sen päälle, kaiken majan kaluston,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'pöydän kaluinensa, aitokultaisen seitsenhaaraisen lampun kaikkine kaluinensa, suitsutusalttarin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'polttouhrialttarin kaikkine kaluinensa, altaan jalustoineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'virkapuvut ja pappi Aaronin muut pyhät vaatteet sekä hänen poikiensa pappispuvut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'voiteluöljyn ja hyvänhajuisen suitsukkeen pyhäkköä varten. He tehkööt kaiken niin, kuin minä olen sinulle käskyn antanut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, '\"Puhu israelilaisille ja sano: Pitäkää minun sapattini, sillä se on merkkinä meidän välillämme, minun ja teidän, sukupolvesta sukupolveen, tietääksenne, että minä olen Herra, joka pyhitän teidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Siis pitäkää sapatti, sillä se on teille pyhä. Joka sen rikkoo, rangaistakoon kuolemalla; sillä kuka ikinä silloin työtä tekee, hävitettäköön kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Kuusi päivää tehtäköön työtä, mutta seitsemäntenä päivänä on sapatti, levon päivä, Herralle pyhitetty. Kuka ikinä tekee työtä sapatinpäivänä, rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Ja pitäkööt israelilaiset sapatin, niin että he viettävät sapattia sukupolvesta sukupolveen ikuisena liittona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Se on oleva ikuinen merkki minun ja israelilaisten välillä; sillä kuutena päivänä Herra teki taivaan ja maan, mutta seitsemäntenä päivänä hän lepäsi ja hengähti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Ja kun hän oli lakannut puhumasta Mooseksen kanssa Siinain vuorella, antoi hän hänelle kaksi laintaulua, kivitaulua, joitten kirjoitus oli Jumalan sormella kirjoitettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Mutta kun kansa näki, että Mooses viipyi eikä tullut alas vuorelta, kokoontui kansa Aaronin ympärille ja sanoi hänelle: \"Nouse, tee meille jumala, joka käy meidän edellämme. Sillä me emme tiedä, mitä on tapahtunut Moosekselle, tälle miehelle, joka johdatti meidät Egyptin maasta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Niin Aaron sanoi heille: \"Irroittakaa kultarenkaat, jotka ovat vaimojenne, poikienne ja tyttärienne korvissa, ja tuokaa ne minulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Ja kaikki kansa irroitti kultarenkaat, jotka heillä oli korvissaan, ja he toivat ne Aaronille;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'ja hän otti vastaan kullan heidän käsistään, kaavaili sitä piirtimellä ja teki siitä valetun vasikan. Ja he sanoivat: \"Tämä on sinun jumalasi, Israel, se, joka on johdattanut sinut Egyptin maasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Kun Aaron tämän näki, rakensi hän sille alttarin; ja Aaron julisti ja sanoi: \"Huomenna on Herran juhla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Ja he nousivat varhain seuraavana päivänä ja uhrasivat polttouhreja ja toivat yhteysuhreja; ja kansa istui syömään ja juomaan, ja sitten he nousivat iloa pitämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Silloin Herra sanoi Moosekselle: \"Mene, astu alas, sillä sinun kansasi, jonka johdatit Egyptin maasta, on turmion tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Pian he poikkesivat siltä tieltä, jota minä käskin heidän kulkea; he tekivät itselleen valetun vasikan. Sitä he ovat kumartaneet, ja sille he ovat uhranneet ja sanoneet: \'Tämä on sinun jumalasi, Israel, se, joka on johdattanut sinut Egyptin maasta\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Ja Herra sanoi vielä Moosekselle: \"Minä näen, että tämä kansa on niskurikansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Anna minun olla, että vihani leimahtaisi heitä vastaan, hukuttaakseni heidät; mutta sinusta minä teen suuren kansan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Mutta Mooses rukoili armoa Herralta, Jumalaltansa, ja sanoi: \"Herra, miksi sinun vihasi syttyy omaa kansaasi vastaan, jonka olet vienyt pois Egyptin maasta suurella voimalla ja väkevällä kädellä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Miksi egyptiläiset saisivat sanoa: \'Heidän onnettomuudekseen hän vei heidät pois, tappaaksensa heidät vuorilla ja hävittääksensä heidät maan päältä\'? Käänny vihasi hehkusta ja kadu sitä turmiota, jonka aioit tuottaa kansallesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Muista palvelijoitasi Aabrahamia, Iisakia ja Israelia, joille olet itse kauttasi vannonut ja sanonut: \'Minä teen teidän jälkeläistenne luvun paljoksi kuin taivaan tähdet; ja koko tämän maan, josta olen puhunut, minä annan teidän jälkeläisillenne, ja he saavat sen ikuiseksi perinnöksi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Niin Herra katui sitä turmiota, jonka hän oli uhannut tuottaa kansallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Ja Mooses kääntyi ja astui alas vuorelta, ja hänen kädessään oli kaksi laintaulua. Ja tauluihin oli kirjoitettu molemmille puolille; etupuolelle ja takapuolelle oli niihin kirjoitettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Ja taulut olivat Jumalan tekemät, ja kirjoitus oli Jumalan kirjoitusta, joka oli tauluihin kaiverrettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Kun Joosua kuuli kansan huudon, sen melutessa, sanoi hän Moosekselle: \"Sotahuuto kuuluu leiristä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Mutta tämä vastasi: \"Se ei ole voittajien huutoa, eikä se ole voitettujen huutoa; minä kuulen laulua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Ja kun Mooses lähestyi leiriä ja näki vasikan ja karkelon, niin hänen vihansa syttyi, ja hän heitti taulut käsistänsä ja murskasi ne vuoren juurella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Senjälkeen hän otti vasikan, jonka he olivat tehneet, poltti sen tulessa ja rouhensi sen hienoksi ja hajotti veteen ja juotti sen israelilaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Ja Mooses sanoi Aaronille: \"Mitä tämä kansa on tehnyt sinulle, kun olet saattanut heidät näin suureen syntiin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aaron vastasi: \"Älköön herrani viha syttykö; sinä tiedät itse, että tämä kansa on paha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'He sanoivat minulle: \'Tee meille jumala, joka käy meidän edellämme; sillä emme tiedä, mitä on tapahtunut Moosekselle, tälle miehelle, joka johdatti meidät Egyptin maasta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Niin minä sanoin heille: \'Jolla on kultaa, irroittakoon sen yltänsä\'; ja he antoivat sen minulle. Ja minä heitin sen tuleen, ja siitä tuli tämä vasikka.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Kun Mooses näki, että kansa oli kurittomuuden vallassa, koska Aaron oli päästänyt heidät kurittomuuden valtaan, vahingoniloksi heidän vihollisillensa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'niin Mooses seisahtui leirin portille ja huusi: \"Joka on Herran oma, se tulkoon minun luokseni\". Silloin kokoontuivat hänen luoksensa kaikki leeviläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Ja hän sanoi heille: \"Näin sanoo Herra, Israelin Jumala: \'Jokainen sitokoon miekkansa vyölleen. Käykää sitten edestakaisin leirin halki portista porttiin ja tappakaa jokainen, olkoon vaikka oma veli, ystävä tai sukulainen.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Niin leeviläiset tekivät Mooseksen käskyn mukaan; ja sinä päivänä kaatui kansaa noin kolmetuhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Ja Mooses sanoi: \"Koska te nyt olette olleet omia poikianne ja veljiänne vastaan, niin vihkiytykää tänä päivänä Herran palvelukseen, että hän tänä päivänä antaisi siunauksen teille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Seuraavana päivänä Mooses sanoi kansalle: \"Te olette tehneet suuren synnin. Minä nousen nyt Herran tykö-jos ehkä voisin sovittaa teidän rikoksenne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Ja Mooses palasi Herran tykö ja sanoi: \"Voi, tämä kansa on tehnyt suuren synnin! He ovat tehneet itselleen jumalan kullasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Jospa nyt antaisit heidän rikoksensa anteeksi! Mutta jos et, niin pyyhi minut pois kirjastasi, johon kirjoitat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Mutta Herra vastasi Moosekselle: \"Joka on tehnyt syntiä minua vastaan, sen minä pyyhin pois kirjastani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Mene nyt ja johdata kansa siihen paikkaan, josta minä olen sinulle puhunut; katso, minun enkelini käy sinun edelläsi. Mutta kostoni päivänä minä kostan heille heidän rikoksensa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Niin Herra rankaisi kansaa, koska he olivat teettäneet vasikan, jonka Aaron teki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Sitten Herra sanoi Moosekselle: \"Lähde täältä ja vaella, sinä ja kansa, jonka olet johdattanut Egyptin maasta, siihen maahan, jonka minä olen vannoen luvannut Aabrahamille, Iisakille ja Jaakobille, sanoen: \'Sinun jälkeläisillesi minä annan sen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Ja minä lähetän enkelin sinun edelläsi ja karkoitan pois kanaanilaiset, amorilaiset, heettiläiset, perissiläiset, hivviläiset ja jebusilaiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'että tulisit siihen maahan, joka vuotaa maitoa ja mettä. Sillä minä en itse vaella sinun kanssasi, koska olet niskurikansa, etten minä sinua tiellä hukuttaisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Kun kansa kuuli tämän kovan puheen, tulivat he murheellisiksi, eikä yksikään pukenut koristuksiaan yllensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Ja Herra sanoi Moosekselle: \"Sano israelilaisille: Te olette niskurikansa. Jos minä silmänräpäyksenkään vaeltaisin sinun keskelläsi, minä hukuttaisin sinut. Riisu nyt koristuksesi yltäsi, niin minä ajattelen, mitä sinulle tekisin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Niin israelilaiset riisuivat koristuksensa ja olivat Hoorebin vuoren luota lähtien ilman niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Mutta Mooses otti majan ja pystytti sen leirin ulkopuolelle, jonkun matkan päähän leiristä, ja kutsui sen ilmestysmajaksi; ja jokaisen, jolla oli kysyttävää Herralta, oli mentävä ilmestysmajalle, leirin ulkopuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Ja kun Mooses lähti majalle, nousi koko kansa, ja kukin asettui majansa ovelle ja katseli Mooseksen jälkeen, kunnes hän oli mennyt majaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Ja aina kun Mooses meni majaan, laskeutui pilvenpatsas ja seisahtui majan ovelle; ja Herra puhutteli Moosesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Ja kaikki kansa näki pilvenpatsaan seisovan majan ovella; niin kaikki kansa nousi, ja he kumartuivat itsekukin majansa ovella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Ja Herra puhutteli Moosesta kasvoista kasvoihin, niinkuin mies puhuttelee toista. Sitten Mooses palasi takaisin leiriin; mutta Joosua, Nuunin poika, hänen apumiehensä ja palvelijansa, ei poistunut majasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Ja Mooses sanoi Herralle: \"Katso, sinä sanot minulle: \'Johdata tämä kansa sinne\', mutta et ole ilmoittanut minulle, kenen sinä lähetät minun kanssani. Ja kuitenkin sinä sanoit: \'Minä tunnen sinut nimeltäsi, ja sinä olet myös saanut armon minun silmieni edessä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Jos siis olen saanut armon sinun silmiesi edessä, niin ilmoita minulle tiesi, että tulisin tuntemaan sinut ja tietäisin saaneeni armon sinun silmiesi edessä; ja katso: tämä kansa on sinun kansasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Hän sanoi: \"Pitäisikö minun kasvojeni käymän sinun kanssasi ja minun viemän sinut lepoon?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Hän vastasi hänelle: \"Elleivät sinun kasvosi käy meidän kanssamme, niin älä johdata meitä täältä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Sillä mistä muutoin tiedetään, että minä olen saanut armon sinun silmiesi edessä, minä ja sinun kansasi, ellei siitä, että sinä käyt meidän kanssamme, niin että me, minä ja sinun kansasi, olemme erikoiset kaikkien kansojen joukossa, jotka maan päällä ovat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Herra vastasi Moosekselle: \"Mitä sinä nyt pyydät, sen minä myös teen; sillä sinä olet saanut armon minun silmieni edessä, ja minä tunnen sinut nimeltäsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Silloin hän sanoi: \"Anna siis minun nähdä sinun kirkkautesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Hän vastasi: \"Minä annan kaiken ihanuuteni käydä sinun ohitsesi ja huudan nimen \'Herra\' sinun edessäsi. Ja minä olen armollinen, kenelle olen armollinen, armahdan, ketä armahdan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Ja hän sanoi vielä: \"Sinä et voi nähdä minun kasvojani; sillä ei kukaan, joka näkee minut, jää eloon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Sitten Herra sanoi: \"Katso, tässä on paikka minun läheisyydessäni; astu tuohon kalliolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Ja kun minun kirkkauteni kulkee ohitse, asetan minä sinut kallion rotkoon ja peitän sinut kädelläni, kunnes olen kulkenut ohi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Kun minä sitten siirrän pois käteni, näet sinä minun selkäpuoleni; mutta minun kasvojani ei voi kenkään katsoa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Ja Herra sanoi Moosekselle: \"Veistä itsellesi kaksi kivitaulua, entisten kaltaista, niin minä kirjoitan niihin tauluihin ne sanat, jotka olivat entisissä tauluissa, jotka sinä murskasit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Ole siis huomenaamuksi valmis; ja nouse huomenaamuna Siinain vuorelle ja seiso siellä minua vastassa vuoren huipulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Mutta älköön kukaan nousko sinne sinun kanssasi, älköönkä ketään näkykö koko vuorella; lampaitakaan ja karjaa älköön käykö laitumella vuoren vaiheilla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Ja Mooses veisti kaksi kivitaulua, entisten kaltaista. Ja varhain seuraavana aamuna Mooses nousi Siinain vuorelle, niinkuin Herra oli häntä käskenyt, ja otti ne kaksi kivitaulua käteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Niin Herra astui alas pilvessä, ja Mooses asettui siellä hänen läheisyyteensä ja huusi Herran nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Ja Herra kulki hänen ohitsensa ja huusi: \"Herra, Herra on laupias ja armahtavainen Jumala, pitkämielinen ja suuri armossa ja uskollisuudessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'joka pysyy armollisena tuhansille, joka antaa anteeksi pahat teot, rikokset ja synnit, mutta ei kuitenkaan jätä rankaisematta, vaan kostaa isien pahat teot lapsille ja lasten lapsille kolmanteen ja neljänteen polveen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Niin Mooses kumartui nopeasti maahan ja rukoili ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, '\"Herra, jos olen saanut armon sinun silmiesi edessä, niin käyköön Herra meidän keskellämme. Sillä tämä on tosin niskurikansa, mutta anna anteeksi meidän pahat tekomme ja syntimme ja ota meidät perintöosaksesi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Hän vastasi: \"Katso, minä teen liiton, minä teen kaiken sinun kansasi nähden ihmeellisiä tekoja, joiden kaltaisia ei ole tehty yhdessäkään maassa, ei minkään kansan keskuudessa. Niin koko kansa, jonka keskellä sinä olet, on näkevä Herran teot, sillä peljättävää on se, mitä minä sinulle teen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Noudata, mitä minä tänä päivänä käsken sinun noudattaa. Katso, minä karkoitan sinun tieltäsi amorilaiset, kanaanilaiset, heettiläiset, perissiläiset, hivviläiset ja jebusilaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Kavahda, ettet tee liittoa sen maan asukasten kanssa, johon tulet, etteivät he tulisi teidän keskuudessanne ansaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'vaan kukistakaa heidän alttarinsa ja murskatkaa heidän patsaansa ja hakatkaa maahan heidän asera-karsikkonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Älä kumarra muuta jumalaa; sillä Herra on nimeltänsä Kiivas, hän on kiivas Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Älä siis tee liittoa maan asukasten kanssa, ettet, kun he kulkevat haureudessa jumaliensa jäljessä ja uhraavat jumalillensa ja kutsuvat sinua, sinä söisi heidän uhristaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'ja etteivät heidän tyttärensä, kun sinä otat heitä pojillesi vaimoiksi ja kun he kulkevat haureudessa jumaliensa jäljessä, viettelisi sinun poikiasikin haureudessa kulkemaan heidän jumaliensa jäljessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Älä tee itsellesi valettuja jumalankuvia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Vietä happamattoman leivän juhlaa: seitsemänä päivänä syö happamatonta leipää, niinkuin minä olen sinua käskenyt, määrättynä aikana, aabib-kuussa, sillä aabib-kuussa sinä olet lähtenyt Egyptistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Kaikki, mikä avaa äidinkohdun, on minun; samoin myös kaikki sinun karjasi urospuolet, raavaittesi ja lampaittesi ensiksisynnyttämät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Mutta aasin ensiksisynnyttämä lunasta lampaalla, mutta jos et sitä lunasta, niin taita siltä niska. Jokainen esikoinen pojistasi lunasta. Ja tyhjin käsin älköön tultako minun kasvojeni eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Kuusi päivää tee työtä, mutta lepää seitsemäs päivä; kyntö-ja elonleikkuuaikanakin sinun on levättävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Ja vietä viikkojuhla, kun leikkaat nisusi uutisen, ja korjuujuhla vuoden vaihteessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Kolme kertaa vuodessa kaikki sinun miesväkesi tulkoon Herran, sinun Herrasi, Israelin Jumalan, kasvojen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Sillä minä karkoitan kansat sinun tieltäsi ja laajennan sinun alueesi; eikä kukaan ole himoitseva sinun maatasi, kun sinä kolme kertaa vuodessa vaellat tullaksesi Herran, sinun Jumalasi, kasvojen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Älä uhraa minun teurasuhrini verta happamen leivän ohella. Ja pääsiäisjuhlan uhrista älköön mitään jääkö yli yön seuraavaan aamuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Parhaat maasi uutisesta tuo Herran, sinun Jumalasi, huoneeseen. Älä keitä vohlaa emänsä maidossa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Ja Herra sanoi Moosekselle: \"Kirjoita itsellesi nämä sanat, sillä näiden sanojen mukaisesti minä olen tehnyt liiton sinun ja Israelin kanssa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Ja hän oli siellä Herran tykönä neljäkymmentä päivää ja neljäkymmentä yötä syömättä ja juomatta. Ja hän kirjoitti tauluihin liiton sanat, ne kymmenen sanaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Ja kun Mooses astui alas Siinain vuorelta ja hänellä vuorelta alas astuessaan oli kädessänsä kaksi laintaulua, ei hän tiennyt, että hänen kasvojensa iho oli tullut säteileväksi hänen puhuessaan Herran kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Ja kun Aaron ja kaikki israelilaiset näkivät Mooseksen kasvojen ihon säteilevän, pelkäsivät he lähestyä häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Mutta Mooses huusi heitä; niin Aaron ja kaikki kansan päämiehet kääntyivät takaisin hänen luokseen, ja Mooses puhui heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Sitten kaikki israelilaiset lähestyivät häntä, ja hän käski heidän noudattaa kaikkea, mitä Herra oli puhunut hänelle Siinain vuorella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Ja kun Mooses oli lakannut puhumasta heidän kanssaan, pani hän peitteen kasvoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Mutta niin usein kuin hän meni Herran eteen puhuttelemaan häntä, poisti hän peitteen, siksi kunnes tuli ulos. Ja tultuaan ulos hän puhui israelilaisille, mitä hänen oli käsketty puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Ja israelilaiset näkivät joka kerta Mooseksen kasvojen ihon säteilevän; ja Mooses veti peitteen kasvoillensa, siksi kunnes hän jälleen meni puhuttelemaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Ja Mooses kokosi kaiken Israelin kansan ja sanoi heille: \"Näin on Herra käskenyt teidän tehdä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Kuusi päivää tehtäköön työtä, mutta seitsemäs päivä olkoon teille pyhä sapatti, levon päivä, Herralle pyhitetty. Kuka ikinä silloin työtä tekee, se surmattakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Älkää sytyttäkö tulta sapatin päivänä, missä asuttekin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Ja Mooses sanoi koko Israelin kansalle näin: \"Näin on Herra käskenyt ja sanonut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Ottakaa siitä, mitä teillä on, anti Herralle; jokainen, jonka sydän on siihen altis, tuokoon anniksi Herralle kultaa, hopeata ja vaskea,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'punasinisiä, purppuranpunaisia ja helakanpunaisia lankoja ja valkoisia pellavalankoja sekä vuohenkarvoja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'punaisia oinaannahkoja, sireeninnahkoja, akasiapuuta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'ljyä seitsenhaaraista lamppua varten, hajuaineita voiteluöljyä ja hyvänhajuista suitsutusta varten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'onyks-kiviä ja muita jalokiviä kasukkaa ja rintakilpeä varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Ja kaikki taidolliset teidän keskuudessanne tulkoot ja tehkööt kaikki, mitä Herra on käskenyt:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'asumuksen telttoineen ja peitteineen, hakasineen, lautoineen, poikkitankoineen, pylväineen ja jalustoineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'arkin korentoineen, armoistuimen ja sitä verhoavan esiripun,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'pöydän korentoineen ja kaikkine kaluineen sekä näkyleivät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'seitsenhaaraisen lampun kaluineen ja lamppuineen, öljyä seitsenhaaraista lamppua varten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'suitsutusalttarin korentoineen, voiteluöljyn ja hyvänhajuisen suitsukkeen, oviuutimen asumuksen ovelle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'polttouhrialttarin vaskiristikkoineen, korentoineen ja kaikkine kaluineen, altaan jalustoineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'esipihan ympärysverhot pylväineen ja jalustoineen sekä esipihan porttiin uutimen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'asumuksen vaarnat ja esipihan vaarnat köysineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'virkapuvut pyhäkköpalvelusta varten ja pappi Aaronin muut pyhät vaatteet sekä hänen poikiensa pappispuvut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Ja kaikki israelilaisten seurakunta meni pois Mooseksen luota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Sitten he tulivat takaisin, jokainen, jonka sydän häntä siihen vaati, ja jokainen, jonka henki oli siihen altis, ja toivat antinsa Herralle ilmestysmajan valmistamista varten ja kaikkea siinä vietettävää jumalanpalvelusta varten ja pyhiä vaatteita varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'He tulivat, sekä miehet että naiset, jokainen, jonka sydän oli siihen altis, ja toivat solkia, korvarenkaita, sormuksia ja kaulakoristeita, kaikkinaisia kultakaluja-jokainen, joka toi Herralle kultaa heilutusuhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Ja jokainen, jolla oli punasinisiä, purppuranpunaisia ja helakanpunaisia lankoja, valkoisia pellavalankoja, vuohen karvoja, punaisia oinaannahkoja tai sireeninnahkoja, toi niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Ja jokainen, joka voi antaa anniksi hopeata ja vaskea, toi annin Herralle. Ja jokainen, jolla oli akasiapuuta, toi sitä kaikkinaisten töiden valmistamista varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Ja kaikki taitavat naiset kehräsivät omin käsin ja toivat kehräämänsä punasiniset, purppuranpunaiset ja helakanpunaiset langat ja valkoiset pellavalangat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'ja kaikki naiset, joiden taidollinen sydän heitä siihen vaati, kehräsivät vuohenkarvoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Mutta päämiehet toivat onyks-kiviä ja muita jalokiviä kasukkaa ja rintakilpeä varten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'ja hajuaineita ja öljyä seitsenhaaraista lamppua varten sekä voiteluöljyksi ja hyvänhajuiseksi suitsutukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Kaikki israelilaiset, miehet ja naiset, joiden sydän oli altis ja vaati heitä tuomaan jotakin niitä töitä varten, joita Herra Mooseksen kautta oli käskenyt tehdä, toivat vapaaehtoisen lahjan Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Ja Mooses sanoi israelilaisille: \"Katsokaa, Herra on nimeltään kutsunut Besalelin, Uurin pojan, Huurin pojanpojan, Juudan sukukunnasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'ja on täyttänyt hänet Jumalan hengellä, taidollisuudella, ymmärryksellä, tiedolla ja kaikkinaisella kätevyydellä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'sommittelemaan taidokkaita teoksia ja valmistamaan niitä kullasta, hopeasta ja vaskesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'hiomaan ja kiinnittämään kiviä ja veistämään puuta, tekemään kaikkinaisia taidokkaita töitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Hänelle ja Oholiabille, Ahisamakin pojalle, Daanin sukukunnasta, hän on myös antanut kyvyn opettaa muita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Nämä hän on täyttänyt taidollisuudella tekemään kaikkinaisia töitä, jommoisia tekevät seppä, kuvakudosten tekijä, kirjokankaiden kutoja, joka valmistaa punasinisiä, purppuranpunaisia ja helakanpunaisia kankaita ja valkoisia pellavakankaita, sekä muu kankuri, ne, jotka valmistavat kaikkinaisia töitä ja sommittelevat taidokkaita teoksia.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, '\"Ja Besalel ja Oholiab ynnä kaikki taidolliset, joille Herra on antanut taidollisuuden ja ymmärryksen tietää, miten mikin pyhäkössä tehtävä työ on suoritettava, tehkööt kaikissa kohdin, niinkuin Herra on käskenyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Niin Mooses kutsui luoksensa Besalelin ja Oholiabin ja kaikki taidolliset, joiden sydämeen Herra oli antanut taidollisuuden, kaikki, joiden sydän vaati heitä ryhtymään työhön suorittaaksensa sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Ja he ottivat Moosekselta kaikki annit, jotka israelilaiset olivat tuoneet pyhäkössä tehtävien töiden suorittamista varten. Mutta he toivat hänelle vielä joka aamu vapaaehtoisia lahjoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Niin tulivat kaikki taidolliset, jotka tekivät kaikkinaista työtä pyhäkössä, mies toisensa jälkeen, siitä työstä, jota kukin oli tekemässä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'ja sanoivat Moosekselle näin: \"Kansa tuo enemmän, kuin mitä tarvitaan sen työn valmistamiseksi, jonka Herra on käskenyt tehdä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Niin Mooses käski kuuluttaa leirissä ja sanoa: \"Älköön kukaan, mies tai nainen, enää valmistako mitään anniksi pyhäkköä varten\". Ja niin kansa lakkasi tuomasta lahjoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Sillä kaikkea työtä varten, mikä oli tehtävä, oli jo koottu riittävästi, jopa liiaksikin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Ja niin kaikki taidolliset, jotka siinä työssä olivat, tekivät asumuksen kymmenestä telttakankaan kaistasta, jotka olivat valmistetut kerratuista valkoisista pellavalangoista ja punasinisistä, purppuranpunaisista ja helakanpunaisista langoista; ja niihin tehtiin taidokkaasti kudottuja kerubeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Kunkin kaistan pituus oli kaksikymmentä kahdeksan kyynärää ja leveys neljä kyynärää; kaikilla kaistoilla oli sama mitta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Ja viisi kaistaa yhdistettiin toisiinsa, ja samoin toiset viisi kaistaa yhdistettiin toisiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Sitten tehtiin silmukat punasinisestä langasta ensimmäisen kaistan reunaan, yhdistetyn kappaleen laitaan, ja samoin toisen yhdistetyn kappaleen viimeisen kaistan reunaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Viisikymmentä silmukkaa tehtiin ensimmäiseen kaistaan ja viisikymmentä silmukkaa vastaavan kaistan laitaan, toiseen yhdistettyyn kappaleeseen, niin että silmukat olivat kohdakkain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Ja sitten tehtiin viisikymmentä kultahakasta, ja kaistat yhdistettiin toisiinsa näillä hakasilla, niin että siitä tuli yhtenäinen asumus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Vielä tehtiin vuohen karvoista telttakankaan kaistoja asumusta suojaavaksi teltaksi; niitä kaistoja tehtiin yksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Kunkin kaistan pituus oli kolmekymmentä kyynärää ja leveys neljä kyynärää; niillä yhdellätoista kaistalla oli sama mitta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Kaistat liitettiin yhteen, viisi kaistaa erikseen ja kuusi kaistaa erikseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Ja viisikymmentä silmukkaa tehtiin toisen yhdistetyn kappaleen viimeisen kaistan reunaan ja viisikymmentä silmukkaa toisen yhdistetyn kappaleen vastaavan kaistan reunaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Sitten tehtiin viisikymmentä vaskihakasta, joilla teltta liitettiin yhteen, niin että siitä tuli yhtenäinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Vielä tehtiin teltalle peite punaisista oinaannahoista ja sen päälle vielä toinen peite sireeninnahoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Asumuksen laudat tehtiin akasiapuusta, pystyyn asetettaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Jokainen lauta oli kymmentä kyynärää pitkä ja puoltatoista kyynärää leveä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Jokaisessa laudassa oli kaksi tappia, jotka olivat poikkilistalla yhdistetyt keskenään; näin tehtiin kaikki asumuksen laudat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Ja asumuksen lautoja tehtiin kaksikymmentä lautaa eteläpuolta varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Ja tehtiin neljäkymmentä hopeajalustaa kahdenkymmenen laudan alle, aina kaksi jalustaa kunkin laudan alle, sen kahta tappia varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Samoin asumuksen toista sivua, pohjoispuolta, varten tehtiin kaksikymmentä lautaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'ja neljäkymmentä hopeajalustaa, aina kaksi jalustaa kunkin laudan alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Mutta asumuksen takasivua, länsipuolta, varten tehtiin kuusi lautaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Ja kaksi lautaa tehtiin asumuksen peränurkkia varten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'ja ne olivat yhteenliitettyjä kaksoislautoja ja alhaalta alkaen kiinni toisissaan ylös saakka, ensimmäiseen renkaaseen asti; näin ne molemmat tehtiin kumpaakin nurkkaa varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Näin tuli olemaan yhteensä kahdeksan lautaa ja niihin kuusitoista hopeajalustaa, aina kaksi jalustaa kunkin laudan alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Sitten tehtiin myös viisi poikkitankoa akasiapuusta asumuksen toisen sivun lautoja varten');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'ja viisi poikkitankoa asumuksen toisen sivun lautoja varten ja viisi poikkitankoa asumuksen takasivun, länsipuolen, lautoja varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Ja keskimmäinen poikkitanko tehtiin kulkemaan lautojen keskikohdalta, reunasta reunaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Ja laudat päällystettiin kullalla, ja niiden renkaat tehtiin kullasta poikkitankojen pitimiksi, ja poikkitangotkin päällystettiin kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Vielä tehtiin esirippu punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista; ja siihen tehtiin taidokkaasti kudottuja kerubeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Ja siihen tehtiin neljä pylvästä akasiapuusta, ja ne päällystettiin kullalla, ja niiden koukut olivat kultaa; ja niitä varten valettiin neljä hopeajalustaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Sitten tehtiin myös teltan oveen uudin, kirjaellen kudottu punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'ja siihen viisi pylvästä koukkuineen; ja niiden päät ja niiden koristepienat päällystettiin kullalla, ja niiden viisi jalustaa tehtiin vaskesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Ja Besalel teki arkin akasiapuusta, puolenkolmatta kyynärän pituisen, puolentoista kyynärän levyisen ja puolentoista kyynärän korkuisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Ja hän päällysti sen puhtaalla kullalla sisältä ja ulkoa ja teki siihen kultareunuksen yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Ja hän valoi siihen neljä kultarengasta, sen neljään kulmaan, niin että kaksi rengasta tuli sen toiselle puolelle ja kaksi rengasta sen toiselle puolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Ja hän teki korennot akasiapuusta ja päällysti ne kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Ja hän pisti arkin sivuilla oleviin renkaisiin korennot, joilla arkki oli kannettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Ja hän teki armoistuimen puhtaasta kullasta, puoltakolmatta kyynärää pitkän ja puoltatoista kyynärää leveän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Ja hän teki kaksi kultakerubia, kohotakoista tekoa, armoistuimen molempiin päihin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'toisen kerubin toiseen päähän ja toisen kerubin toiseen päähän. Armoistuimesta kohoaviksi hän teki kerubit, sen kumpaankin päähän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Ja kerubit levittivät siipensä ylöspäin, niin että ne peittivät siivillänsä armoistuimen, ja niiden kasvot olivat vastakkain; kerubien kasvot olivat käännetyt armoistuinta kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Hän teki myös pöydän akasiapuusta, kahta kyynärää pitkän, kyynärää leveän ja puoltatoista kyynärää korkean.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Ja hän päällysti sen puhtaalla kullalla ja teki siihen kultareunuksen yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Ja hän teki sen ympäri kämmenen korkuisen listan, ja listan ympäri kultareunuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Ja hän valoi siihen neljä kultarengasta ja kiinnitti renkaat neljään kulmaan, sen neljän jalan kohdalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Renkaat olivat juuri listan alla niiden korentojen pitiminä, joilla pöytä oli kannettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Ja hän teki korennot akasiapuusta ja päällysti ne kullalla; ja niillä oli pöytä kannettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Hän teki puhtaasta kullasta pöydällä pidettävät astiat: vadit ja kupit, maljat ja kannut, joista juomauhri vuodatetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Hän teki myös seitsenhaaraisen lampun puhtaasta kullasta. Kohotakoista tekoa hän teki seitsenhaaraisen lampun jalkoineen ja varsineen; sen kukkakuvut, nuput kukkalehtineen, olivat samaa kappaletta kuin se.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Kuusi haaraa lähti lampun sivuista, kolme haaraa toisesta sivusta ja kolme haaraa toisesta sivusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Toisessa haarassa oli kolme mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen, ja toisessa haarassa samoin kolme mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen; näin oli jokaisessa kuudessa haarassa, jotka lampusta lähtivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Mutta itse seitsenhaaraisessa lampussa oli neljä mantelinkukan muotoista kukkakupua, nuppua kukkalehtineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Yksi nuppu oli aina jokaisen haaraparin alla niistä kuudesta haarasta, jotka lampusta lähtivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Nuput ja haarat olivat samaa kappaletta kuin se; se oli kokonaan samaa kohotakoista tekoa, puhdasta kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Ja hän teki siihen seitsemän lamppua ja siihen kuuluvat lamppusakset ja karstakupit puhtaasta kullasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Yhdestä talentista puhdasta kultaa hän teki sekä sen että kaikki sen kalut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Hän teki myös suitsutusalttarin akasiapuusta, kyynärän pituisen ja kyynärän levyisen, siis neliskulmaisen, ja kahta kyynärää korkean; sen sarvet olivat samaa kappaletta kuin se.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Ja hän päällysti sen puhtaalla kullalla, sekä sen levyn että sivut ympärinsä ja sen sarvet; ja hän teki kultareunuksen sen ympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Ja hän teki siihen kaksi kultarengasta reunuksen alle molemmin puolin, molempiin sivuihin, niiden korentojen pitimiksi, joilla alttari oli kannettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Ja korennotkin hän teki akasiapuusta ja päällysti ne kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Ja hän teki pyhän voiteluöljyn ja puhtaan, hyvänhajuisen suitsukkeen, jollaista voiteensekoittaja valmistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Ja hän teki polttouhrialttarin akasiapuusta, neliskulmaisen, viittä kyynärää pitkän, viittä kyynärää leveän ja kolmea kyynärää korkean.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Ja hän teki siihen sarvet, sen neljään kulmaan, niin että sarvet olivat samaa kappaletta kuin se. Ja hän päällysti sen vaskella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Ja hän teki kaikki alttarin kalut: kattilat, lapiot, maljat, haarukat ja hiilipannut. Kaikki sen kalut hän teki vaskesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Ja hän teki alttariin verkonkaltaisen ristikkokehyksen vaskesta, alttarin välireunuksen alle, maahan kiinni, niin että se ulottui puolitiehen alttaria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Ja hän valoi neljä rengasta vaskiristikon neljään kulmaan, korentojen pitimiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Ja korennot hän teki akasiapuusta ja päällysti ne vaskella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Ja hän pisti alttarin sivuilla oleviin renkaisiin korennot, joilla se oli kannettava. Ja hän teki sen laudoista, ontoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Ja hän teki vaskialtaan vaskijalustoineen niiden naisten kuvastimista, jotka toimittivat palvelusta ilmestysmajan ovella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Sitten hän teki esipihan. Etelän puolella olivat esipihan ympärysverhot kerratuista valkoisista pellavalangoista, sadan kyynärän pituiset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'niiden pylväitä oli kaksikymmentä ja näiden vaskijalustoja kaksikymmentä, mutta pylväiden koukut ja niiden koristepienat olivat hopeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Samoin olivat ympärysverhot myös pohjoisen puolella sadan kyynärän pituiset; niiden pylväitä oli kaksikymmentä ja näiden vaskijalustoja kaksikymmentä, mutta pylväiden koukut ja niiden koristepienat olivat hopeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Mutta lännen puolella olivat ympärysverhot viidenkymmenen kyynärän pituiset; niiden pylväitä oli kymmenen ja näiden jalustoja kymmenen, ja pylväiden koukut ja niiden koristepienat olivat hopeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Ja etupuolella, itään päin, olivat ympärysverhot viidenkymmenen kyynärän pituiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Ympärysverhot olivat portin toisella sivulla viidentoista kyynärän pituiset, ja niiden pylväitä oli kolme ja näiden jalustoja kolme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Samoin olivat ympärysverhot toisellakin sivulla, siis esipihan portin kummallakin puolella, viidentoista kyynärän pituiset; niiden pylväitä oli kolme ja näiden jalustoja kolme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Kaikki esipihan ympärysverhot yltympäri olivat kerratuista valkoisista pellavalangoista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'ja pylväiden jalustat olivat vaskea, mutta pylväiden koukut ja niiden koristepienat olivat hopeata, ja niiden päiden päällystys oli hopeata; kaikki esipihan pylväät olivat ympäröidyt hopeaisilla koristepienoilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Ja esipihan portin uudin oli kirjaellen kudottu punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista, kahdenkymmenen kyynärän pituinen ja niinkuin esipihan ympärysverhotkin viiden kyynärän korkuinen, vaatteen leveyden mukaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'ja sen pylväitä oli neljä ja näiden vaskijalustoja neljä, mutta niiden koukut olivat hopeata, ja niiden päiden päällystys ja niiden koristepienat olivat hopeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Ja kaikki asumuksen ja ympärillä olevan esipihan vaarnat olivat vaskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Näin paljon lasketaan menneen asumuksen, lain asumuksen, kustannuksiin, joka lasku tehtiin Mooseksen käskyn mukaan leeviläisten toimesta, Iitamarin, pappi Aaronin pojan, johdolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Ja Besalel, Uurin poika, Huurin pojanpoika, Juudan sukukunnasta, oli tehnyt kaikki, mistä Herra oli Moosekselle käskyn antanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'ja hänellä oli apulaisena Oholiab, Ahisamakin poika, Daanin sukukunnasta, seppä ja kuvakudosten tekijä; tämä valmisti kirjokankaita punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja valkoisista pellavalangoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Kultaa, joka käytettiin siihen työhön, kaikkeen työhön pyhäkössä, oli heilutusuhrina tuotu kaikkiaan kaksikymmentä yhdeksän talenttia, seitsemänsataa kolmekymmentä sekeliä, pyhäkkösekelin painon mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Ja hopeata, joka kansalta katselmusta pidettäessä kerääntyi, oli sata talenttia ja tuhat seitsemänsataa seitsemänkymmentä viisi sekeliä, pyhäkkösekelin painon mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'puolikas, puoli sekeliä, henkeä kohti, pyhäkkösekelin painon mukaan, jokaiselta katselmuksessa olleelta kaksikymmenvuotiaalta ja sitä vanhemmalta, kaikkiaan kuudeltasadalta kolmelta tuhannelta viideltäsadalta viideltäkymmeneltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Ja ne sata talenttia hopeata käytettiin pyhäkön jalustain ja esiripun jalustain valamiseen: sata talenttia sataan jalustaan, talentti jalustaa kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Ja niistä tuhannesta seitsemästäsadasta seitsemästäkymmenestä viidestä sekelistä tehtiin koukut pylväisiin ja päällystettiin hopealla niiden päät ja tehtiin niihin koristepienat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Ja heilutusuhri-vaskea oli seitsemänkymmentä talenttia, kaksituhatta neljäsataa sekeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Siitä tehtiin jalustat ilmestysmajan oveen, vaskialttari ja siihen kuuluva vaskinen ristikkokehys ja kaikki alttarin kalut');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'sekä jalustat ympärillä olevaan esipihaan ja jalustat esipihan porttiin ja kaikki asumuksen vaarnat ja kaikki vaarnat ympärillä olevaan esipihaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Ja punasinisistä, purppuranpunaisista ja helakanpunaisista langoista tehtiin virkapuvut pyhäkköpalvelusta varten; ja samoin tehtiin muut pyhät vaatteet Aaronille, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Kasukka tehtiin kullasta sekä punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Kultalevyt taottiin ohuiksi ja leikattiin säikeiksi, taidokkaasti kudottaviksi punasinisten, purppuranpunaisten ja helakanpunaisten lankojen ja valkoisten pellavalankojen sekaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Siihen tehtiin yhdistettävät olkakappaleet; molemmista päistänsä se kiinnitettiin niihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Ja vyö, joka oli oleva kasukassa sen kiinnittämiseksi, oli tehty samasta kappaleesta kuin se, samalla tavalla kullasta sekä punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Sitten valmistettiin kultapalmikoimilla kehystetyt onyks-kivet, joihin oli kaiverrettu Israelin poikien nimet, niinkuin kaiverretaan sinettisormuksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Ja ne pantiin kasukan olkakappaleihin, että ne kivet johdattaisivat muistoon israelilaiset, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Rintakilpi tehtiin taidokkaasti kutomalla, samalla tavalla kuin kasukkakin oli tehty, kullasta sekä punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja kerratuista valkoisista pellavalangoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Se oli neliskulmainen ja taskun muotoon tehty; rintakilpi tehtiin vaaksan pituinen ja vaaksan levyinen, taskun muotoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Ja sen pintaan kiinnitettiin kiviä yliyltään, neljään riviin: ensimmäiseen riviin karneoli, topaasi ja smaragdi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'toiseen riviin rubiini, safiiri ja jaspis;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'kolmanteen riviin hyasintti, akaatti ja ametisti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'ja neljänteen riviin krysoliitti, onyks ja berylli. Kultapalmikoimilla kehystettyinä ne kiinnitettiin paikoilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Kiviä oli Israelin poikien nimien mukaan kaksitoista, yksi kutakin nimeä kohti; kussakin kivessä oli yksi kahdentoista sukukunnan nimistä, kaiverrettuna samalla tavalla, kuin kaiverretaan sinettisormuksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Ja rintakilpeen tehtiin puhtaasta kullasta käädyt, punotut, niinkuin punonnaista tehdään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Vielä tehtiin kaksi kultapalmikoimaa ja kaksi kultarengasta, ja molemmat renkaat kiinnitettiin rintakilven molempiin yläkulmiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Ja molemmat kultapunonnaiset kiinnitettiin kahteen renkaaseen rintakilven yläkulmiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Ja molempien punonnaisten toiset kaksi päätä kiinnitettiin kahteen palmikoimaan, ja nämä kiinnitettiin kasukan olkakappaleihin, sen etupuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Vielä tehtiin kaksi kultarengasta, ja ne pantiin rintakilven molempiin alakulmiin, sen sisäpuoliseen, kasukkaa vasten olevaan reunaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Ja vieläkin tehtiin kaksi kultarengasta, ja ne kiinnitettiin kasukan molempiin olkakappaleihin, niiden alareunaan, etupuolelle, sauman kohdalle, kasukan vyön yläpuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Sitten rintakilpi solmittiin renkaistaan punasinisellä nauhalla kasukan renkaisiin, niin että se oli kasukan vyön yläpuolella, eikä siis rintakilpi irtautunut kasukasta-kaikki, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Kasukan viitta tehtiin kokonaan kutomalla punasinisistä langoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Ja pääntie viitan keskellä oli niinkuin haarniskan aukko, ja pääntie ympäröitiin päärmeellä, ettei se repeäisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Ja viitan helmaan tehtiin granaattiomenia punasinisistä, purppuranpunaisista ja helakanpunaisista kerratuista langoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Sitten tehtiin tiukuja puhtaasta kullasta, ja nämä tiuvut kiinnitettiin granaattiomenien väliin viitan helmaan ympärinsä, granaattiomenien väliin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'vuorotellen tiuku ja granaattiomena viitan helmaan ympärinsä, käytettäviksi virantoimituksessa, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Sitten tehtiin Aaronille ja hänen pojilleen ihokkaat, kudotut valkoisista pellavalangoista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'käärelakki valkoisista pellavalangoista, koristepäähineet valkoisista pellavalangoista ja pellavakaatiot kerratuista valkoisista pellavalangoista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'ja vihdoin vyö kerratuista valkoisista pellavalangoista ja punasinisistä, purppuranpunaisista ja helakanpunaisista langoista, kirjaellen kudottu, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Vielä tehtiin otsakoriste, pyhä otsalehti, puhtaasta kullasta ja siihen piirrettiin, niinkuin sinettisormusta kaiverretaan, kirjoitus: \"Herralle pyhitetty\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Ja siihen kiinnitettiin punasininen nauha sidottavaksi käärelakin yläreunaan, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Ja niin valmistui koko työ: asumus, ilmestysmaja. Ja israelilaiset tekivät kaiken, niinkuin Herra oli Moosekselle käskyn antanut; niin he tekivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Ja he toivat Mooseksen eteen asumuksen, majan kaikkine kaluineen, hakasineen, lautoineen, poikkitankoineen, pylväineen ja jalustoineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'punaisista oinaannahoista tehdyn peitteen ja sireeninnahoista tehdyn peitteen ja verhona olevan esiripun,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'lain arkin korentoineen, armoistuimen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'pöydän kaikkine kaluineen ja näkyleivät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'aitokultaisen seitsenhaaraisen lampun riviin pantavine lamppuineen ja kaikkine kaluineen sekä öljyä seitsenhaaraista lamppua varten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'kultaisen alttarin, voiteluöljyn ja hyvänhajuisen suitsukkeen, majan oven uutimen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'vaskialttarin vaskisine ristikkokehyksineen, sen korennot ja kaikki kalut, altaan jalustoineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'esipihan ympärysverhot pylväineen ja jalustoineen, esipihan portin uutimen sekä sen köydet ja vaarnat, ja kaikki kalut, joita tarvitaan asumuksen, ilmestysmajan, tehtävissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'virkapuvut pyhäkköpalvelusta varten ja pappi Aaronin muut pyhät vaatteet sekä hänen poikiensa pappispuvut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Aivan niinkuin Herra oli Moosekselle käskyn antanut, niin olivat israelilaiset tehneet kaiken sen työn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Ja Mooses katseli kaikkea työtä, ja katso, he olivat tehneet sen niin, kuin Herra oli käskenyt; niin he olivat tehneet. Silloin Mooses siunasi heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '\"Ensimmäisen kuukauden ensimmäisenä päivänä pystytä asumus, ilmestysmaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Ja aseta sinne lain arkki ja ripusta esirippu arkin eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Ja tuo sinne pöytä ja lado sille näkyleivät päälletysten; ja tuo sinne seitsenhaarainen lamppu ja nosta sen lamput paikoilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Ja sijoita kultainen suitsutusalttari lain arkin eteen ja ripusta uudin majan oveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Ja polttouhrialttari sijoita asumuksen, ilmestysmajan, oven eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Ja allas sijoita ilmestysmajan ja alttarin välille ja kaada siihen vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Ja tee esipiha yltympäri ja pane uudin esipihan porttiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Ota sitten voiteluöljyä ja voitele asumus ja kaikki, mitä siinä on, ja pyhitä se kalustoineen, että se tulisi pyhäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Ja voitele polttouhrialttari kaikkine kaluineen ja pyhitä alttari, että alttari tulisi korkeasti-pyhäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Voitele myös allas jalustoineen ja pyhitä se.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Tuo sitten Aaron poikineen ilmestysmajan ovelle ja pese heidät vedellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Ja pue Aaron pyhiin vaatteisiin ja voitele hänet ja pyhitä hänet, että hän pappina palvelisi minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Ja tuo myös hänen poikansa ja pue heidän ylleen ihokkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Ja voitele heidät, niinkuin sinä voitelit heidän isänsäkin, että he pappeina palvelisivat minua. Niin tämä on oleva heille voitelu ikuiseen pappeuteen, sukupolvesta sukupolveen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Ja Mooses teki kaiken, niinkuin Herra oli häntä käskenyt; niin hän teki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Ja asumus pystytettiin toisen vuoden ensimmäisessä kuussa, kuukauden ensimmäisenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Silloin Mooses pystytti asumuksen. Hän asetti paikoilleen sen jalustat, kiinnitti sen laudat, sovitti paikoilleen sen poikkitangot ja pystytti sen pylväät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Ja hän levitti asumuksen ylle teltan ja asetti ylimmäksi sen päälle telttapeitteen, niinkuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Sitten hän otti lain, pani sen arkkiin ja kiinnitti arkkiin korennot ja asetti armoistuimen arkin päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Ja hän toi arkin asumukseen ja sijoitti paikoilleen sitä verhoavan esiripun, ripustaen sen lain arkin eteen, niinkuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Ja hän asetti pöydän ilmestysmajaan, asumuksen pohjoissivulle, esiripun ulkopuolelle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'ja latoi sille näkyleivät päälletysten Herran eteen, niinkuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Ja hän asetti seitsenhaaraisen lampun ilmestysmajaan, vastapäätä pöytää, asumuksen eteläsivulle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'ja nosti lamput paikoilleen Herran eteen, niinkuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Ja hän asetti kultaisen alttarin ilmestysmajaan esiripun eteen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'ja poltti siinä hyvänhajuista suitsuketta, niinkuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Ja hän ripusti uutimen asumuksen oveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Ja polttouhrialttarin hän asetti asumuksen, ilmestysmajan, oven eteen ja uhrasi sen päällä polttouhrin ja ruokauhrin, niinkuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Ja altaan hän asetti ilmestysmajan ja alttarin välille ja kaatoi siihen vettä peseytymistä varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Ja Mooses ja Aaron ja hänen poikansa pesivät siinä kätensä ja jalkansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'kun he menivät ilmestysmajaan tahi lähestyivät alttaria, niin he aina peseytyivät, niinkuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Ja asumuksen ja alttarin ympärille hän laittoi esipihan ja ripusti uutimen esipihan porttiin. Ja niin Mooses päätti sen työn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Sitten pilvi peitti ilmestysmajan, ja Herran kirkkaus täytti asumuksen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'eikä Mooses voinut mennä ilmestysmajaan, sillä pilvi oli laskeutunut sen päälle, ja Herran kirkkaus täytti asumuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Ja joka kerta, kun pilvi kohosi asumuksen päältä, lähtivät israelilaiset liikkeelle; näin oli koko heidän vaelluksensa ajan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Mutta milloin pilvi ei kohonnut, he eivät lähteneet liikkeelle, ennenkuin sinä päivänä, jona se taas kohosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Sillä Herran pilvi oli päivällä asumuksen päällä, ja yöllä oli pilvessä tulen hohde kaikkien israelilaisten silmien edessä; näin oli koko heidän vaelluksensa ajan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Ja Herra kutsui Mooseksen ja puhui hänelle sisältä ilmestysmajasta sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, '\"Puhu israelilaisille ja sano heille: Jos joku teistä tahtoo tuoda uhrilahjan Herralle, niin tuokaa uhrilahjanne karjasta, joko raavaista tai lampaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Jos hänen uhrilahjansa on raavaspolttouhri, tuokoon virheettömän urospuolen; ilmestysmajan ovelle hän tuokoon sen, että Herran mielisuosio tulisi hänen osaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Ja hän laskekoon kätensä polttouhriteuraan pään päälle; niin se on oleva otollinen ja tuottava hänelle sovituksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Ja hän teurastakoon mullikan Herran kasvojen edessä, ja papit, Aaronin pojat, tuokoot veren ja vihmokoot veren ympärinsä alttarille, joka on ilmestysmajan ovella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Ja hän nylkeköön polttouhriteuraan ja leikelköön sen määräkappaleiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Ja pappi Aaronin pojat tehkööt tulen alttarille ja pankoot halkoja tuleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Ja papit, Aaronin pojat, asettakoot kappaleet ynnä pään ja rasvan halkojen päälle, jotka ovat tulessa alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Mutta sisälmykset ja jalat hän pesköön vedessä, ja pappi polttakoon kaiken alttarilla; se on polttouhri, suloisesti tuoksuva uhri Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Ja jos hänen uhrilahjansa, joka on tarkoitettu polttouhriksi, on otettu pikkukarjasta, lampaista tai vuohista, tuokoon virheettömän urospuolen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Ja teurastakoon sen alttarin pohjoissivulla, Herran edessä; ja papit, Aaronin pojat, vihmokoot sen veren alttarille ympärinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Ja hän leikelköön sen määräkappaleiksi, ja pappi asettakoon ne ynnä pään ja rasvan halkojen päälle, jotka ovat tulessa alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Mutta sisälmykset ja jalat hän pesköön vedessä, ja pappi tuokoon sen kaiken ja polttakoon alttarilla; se on polttouhri, suloisesti tuoksuva uhri Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Ja jos hänen uhrilahjansa Herralle on lintupolttouhri, tuokoon uhrilahjanaan metsäkyyhkysiä tai kyyhkysenpoikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Ja pappi tuokoon sen alttarille, vääntäköön siltä niskat poikki ja polttakoon sen alttarilla, ja puserrettakoon sen veri alttarin seinään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Ja hän ottakoon sen kuvun rapoineen pois ja heittäköön sen alttarin viereen itäpuolelle, tuhkaläjälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Sitten hän reväisköön sen auki siipien kohdalta, niitä kuitenkaan irroittamatta, ja pappi polttakoon sen alttarilla halkojen päällä, jotka ovat tulessa; se on polttouhri, suloisesti tuoksuva uhri Herralle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, '\"Jos joku tahtoo tuoda Herralle lahjaksi ruokauhrin, olkoon hänen uhrilahjanaan lestyjä jauhoja; ja hän vuodattakoon siihen öljyä ja pankoon sen päälle suitsuketta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'ja vieköön sen papeille, Aaronin pojille, ja pappi ottakoon kourallisen niitä jauhoja ja sitä öljyä ynnä kaiken suitsukkeen ja polttakoon tämän alttariuhriosan alttarilla suloisesti tuoksuvana uhrina Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Mutta se, mikä jää tähteeksi ruokauhrista, olkoon Aaronin ja hänen poikiensa oma; se on korkeasti-pyhää, Herran uhria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Mutta jos tahdot tuoda ruokauhrilahjan uunissa paistetusta, olkoon uhrinasi lestyistä jauhoista valmistetut, öljyyn leivotut happamattomat kakut tai öljyllä voidellut happamattomat ohukaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Jos taas uhrilahjasi on ruokauhri, joka leivinlevyllä paistetaan, olkoon se valmistettu lestyistä jauhoista, öljyyn leivottu ja happamaton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Paloittele se palasiksi ja vuodata öljyä sen päälle; se on ruokauhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Ja jos uhrilahjasi on ruokauhri, joka paistetaan pannussa, valmistettakoon se lestyistä jauhoista ynnä öljystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Ja vie ruokauhri, joka näin on valmistettu, Herralle; se vietäköön papille, ja hän tuokoon sen alttarin ääreen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Ja pappi erottakoon ruokauhrista alttariuhriosan ja polttakoon sen alttarilla suloisesti tuoksuvana uhrina Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Mutta se, mikä jää tähteeksi ruokauhrista, olkoon Aaronin ja hänen poikiensa oma; se on korkeasti-pyhää, Herran uhria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Mitään ruokauhria, jonka te tuotte Herralle, älköön valmistettako happamesta; älkää polttako uhria Herralle mistään happamesta taikinasta tai hunajasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Uutisuhrilahjana saatte tuoda niitä Herralle, mutta älkööt ne tulko alttarille suloiseksi tuoksuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Ja jokainen ruokauhrilahjasi suolaa suolalla, äläkä anna Jumalasi liitonsuolan puuttua ruokauhristasi; jokaiseen uhrilahjaasi sinun on tuotava suolaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Mutta jos tahdot tuoda uutisesta ruokauhrin Herralle, niin tuo uutisruokauhrinasi tulessa paahdettuja tähkäpäitä tai survottuja jyviä tuleentumattomasta viljasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Ja vuodata siihen öljyä ja pane siihen suitsuketta; se on ruokauhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Ja pappi polttakoon alttariuhriosan survotuista jyvistä ja öljystä ynnä kaiken suitsukkeen uhrina Herralle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, '\"Jos hänen uhrilahjansa on yhteysuhri, tuokoon hän, jos hän tuo raavaskarjasta härän tai lehmän, virheettömän eläimen Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Ja hän laskekoon kätensä uhriteuraansa pään päälle ja teurastakoon sen ilmestysmajan ovella; ja papit, Aaronin pojat, vihmokoot veren alttarille ympärinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Ja hän tuokoon yhteysuhrista uhrina Herralle sisälmyksiä peittävän rasvan ja kaiken sisälmysten rasvan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'ja molemmat munuaiset ynnä niiden päällä lantiolihaksissa olevan rasvan ja maksanlisäkkeen, joka on irroitettava munuaisten luota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Ja Aaronin pojat polttakoot sen alttarilla polttouhrin päällä, joka on halkojen päällä tulessa, suloisesti tuoksuvana uhrina Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Mutta jos hän tuo uhrilahjanaan Herralle yhteysuhriksi pikkukarjasta urospuolen tai naaraspuolen, niin tuokoon virheettömän eläimen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Jos hän tuo uhrilahjanaan lampaan, niin tuokoon sen Herran eteen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'ja laskekoon kätensä uhriteuraansa pään päälle ja teurastakoon sen ilmestysmajan ovella, ja Aaronin pojat vihmokoot sen veren alttarille ympärinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Ja hän tuokoon yhteysuhrista uhrina Herralle sen rasvan, koko rasvahännän, joka on irroitettava häntänikamista, sisälmyksiä peittävän rasvan ja kaiken sisälmysten rasvan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'ja molemmat munuaiset ynnä niiden päällä lantiolihaksissa olevan rasvan ja maksanlisäkkeen, joka on irroitettava munuaisten luota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Ja pappi polttakoon sen alttarilla uhriruokana Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Ja jos hänen uhrilahjansa on vuohi, tuokoon sen Herran eteen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'ja laskekoon kätensä sen pään päälle ja teurastakoon sen ilmestysmajan ovella; ja Aaronin pojat vihmokoot sen veren alttarille ympärinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Ja hän tuokoon siitä uhrilahjanaan Herralle uhriksi sisälmyksiä peittävän rasvan ja kaiken sisälmysten rasvan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'ja molemmat munuaiset ynnä niiden päällä lantiolihaksissa olevan rasvan ja maksanlisäkkeen, joka on irroitettava munuaisten luota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Ja pappi polttakoon ne alttarilla uhriruokana, suloisesti tuoksuvana uhrina; kaikki rasva olkoon Herran oma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Tämä olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin: mitään rasvaa tai verta älkää syökö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, '\"Puhu israelilaisille ja sano: Jos joku erehdyksestä rikkoo jotakuta Herran käskyä vastaan ja tekee jotakin, mitä ei saa tehdä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'niin, jos voideltu pappi tekee rikkomuksen ja saattaa kansan vikapääksi, tuokoon rikkomuksensa tähden, jonka hän on tehnyt, virheettömän mullikan Herralle syntiuhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Ja vieköön mullikan ilmestysmajan ovelle Herran eteen ja laskekoon kätensä mullikan pään päälle ja teurastakoon mullikan Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Ja ottakoon se voideltu pappi mullikan verta ja vieköön sen ilmestysmajaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'ja pappi kastakoon sormensa vereen ja pirskoittakoon verta seitsemän kertaa Herran edessä, pyhäkön esiripun edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Ja pappi sivelköön sitä verta alttarin sarviin, jolla poltetaan hyvänhajuista suitsutusta Herran edessä ja joka on ilmestysmajassa; mullikan kaiken muun veren hän vuodattakoon ilmestysmajan oven edessä olevan polttouhrialttarin juurelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Ja kaiken syntiuhrimullikan rasvan hän erottakoon siitä pois, sekä sisälmyksiä peittävän rasvan että kaiken sisälmysten rasvan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'ja molemmat munuaiset ynnä niiden päällä lantiolihaksissa olevan rasvan ja maksanlisäkkeen, joka on irroitettava munuaisten luota,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'samalla tavalla kuin se erotetaan pois yhteysuhrihärästä; ja pappi polttakoon ne polttouhrialttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Mutta mullikan nahan ja kaiken lihan ynnä pään ja jalat, sisälmykset ja ravan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'koko mullikan, hän vieköön leirin ulkopuolelle puhtaaseen paikkaan, johon tuhka heitetään, ja polttakoon sen halkojen päällä tulessa; siinä paikassa, johon tuhka heitetään, se poltettakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Ja jos koko Israelin seurakunta erehdyksestä tekee rikkomuksen ja seurakunta ei siitä tiedä ja he rikkomalla jotakuta Herran käskyä vastaan ovat tehneet sellaista, mitä ei saa tehdä, ja niin joutuneet vikapäiksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'ja jos sitten rikkomus, jonka he ovat tehneet sitä vastaan, tulee tunnetuksi, niin tuokoon seurakunta mullikan syntiuhriksi ja vieköön sen ilmestysmajan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Ja seurakunnan vanhimmat laskekoot kätensä mullikan pään päälle Herran edessä, ja mullikka teurastettakoon Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Ja voideltu pappi vieköön mullikan verta ilmestysmajaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Ja pappi kastakoon sormensa vereen ja pirskoittakoon sitä seitsemän kertaa Herran edessä, esiripun edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Ja hän sivelköön sitä verta alttarin sarviin, joka on Herran edessä ilmestysmajassa; kaiken muun veren hän vuodattakoon ilmestysmajan oven edessä olevan polttouhrialttarin juurelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Ja hän erottakoon siitä pois kaiken rasvan ja polttakoon sen alttarilla');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'ja tehköön tälle mullikalle, niinkuin hän teki syntiuhrimullikalle; samalla tavalla hän sille tehköön. Kun pappi näin on toimittanut heille sovituksen, annetaan heille anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Ja mullikan hän vieköön leirin ulkopuolelle ja polttakoon sen, niinkuin hän poltti edellisen mullikan; se on seurakunnan syntiuhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Jos päämies tekee rikkomuksen ja erehdyksestä rikkomalla jotakuta Herran, Jumalansa, käskyä vastaan tekee sellaista, mitä ei saa tehdä, ja niin joutuu vikapääksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'ja hän sitten saa tietää rikkomuksensa, jonka hän on tehnyt, niin tuokoon uhrilahjanaan kauriin, virheettömän urospuolen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'ja laskekoon kätensä kauriin pään päälle ja teurastakoon sen siinä paikassa, jossa polttouhriteuraat Herran edessä teurastetaan; se on hänen syntiuhrinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Ja pappi ottakoon syntiuhrin verta sormeensa ja sivelköön sitä polttouhrialttarin sarviin; muun veren hän vuodattakoon polttouhrialttarin juurelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Mutta kaiken sen rasvan hän polttakoon alttarilla, niinkuin yhteysuhrin rasvan. Kun pappi näin on toimittanut hänelle sovituksen hänen rikkomuksestansa, annetaan hänelle anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Jos joku rahvaasta erehdyksestä rikkoo jotakuta Herran käskyä vastaan tekemällä sellaista, mitä ei saa tehdä, ja niin joutuu vikapääksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'ja hän sitten saa tietää rikkomuksensa, jonka hän on tehnyt, niin tuokoon rikkomuksensa tähden, jonka hän on tehnyt, uhrilahjanaan vuohen, virheettömän naaraspuolen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'ja laskekoon kätensä tämän syntiuhriteuraan pään päälle ja teurastakoon sen polttouhripaikalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Ja pappi ottakoon sen verta sormeensa ja sivelköön sitä polttouhrialttarin sarviin; kaiken muun veren hän vuodattakoon alttarin juurelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Ja hän irroittakoon kaiken sen rasvan, niinkuin rasva irroitetaan yhteysuhrista, ja pappi polttakoon sen alttarilla suloisena tuoksuna Herralle. Kun pappi näin on toimittanut hänelle sovituksen, annetaan hänelle anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Mutta jos hän tuo uhrilahjanaan karitsan syntiuhriksi, niin tuokoon virheettömän uuhen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'ja laskekoon kätensä tämän syntiuhriteuraan pään päälle ja teurastakoon sen syntiuhriksi siinä paikassa, jossa polttouhrieläin teurastetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Ja pappi ottakoon syntiuhrin verta sormeensa ja sivelköön polttouhrialttarin sarviin; kaiken muun veren hän vuodattakoon alttarin juurelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Ja kaiken sen rasvan hän irroittakoon, niinkuin yhteysuhrilampaan rasva irroitetaan, ja pappi polttakoon sen alttarilla Herran uhrin päällä. Kun pappi on toimittanut hänelle sovituksen hänen rikkomuksestansa, jonka hän on tehnyt, annetaan hänelle anteeksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, '\"Jos joku rikkoo siten, että hän, vaikka kuulee vannotuksen ja voisi olla todistajana, joko hän on ollut silminnäkijänä tahi muuten saanut asiasta tietää, ei kuitenkaan ilmoita sitä ja niin joutuu syynalaiseksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'tahi jos joku tietämättään koskee johonkin saastaiseen, mihin tahansa, joko saastaisen metsäeläimen raatoon tai saastaisen kotieläimen raatoon tai saastaisen matelijan raatoon, ja on siten tullut saastaiseksi ja vikapääksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'tahi jos hän tietämättään koskee ihmisen saastaan, olipa se mitä saastaa tahansa, josta tulee saastaiseksi, mutta sitten huomaa sen ja joutuu vikapääksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'tahi jos joku, ajattelemattomasti puhuen huulillansa, tietämättään vannoo tekevänsä jotakin, pahaa tai hyvää-vannoipa mitä hyvänsä, mitä ihminen saattaa ajattelemattomasti vannoa-mutta sitten huomaa sen ja joutuu johonkin sellaiseen vikapääksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'niin, jos hän on vikapää johonkin sellaiseen, tunnustakoon sen, mitä on rikkonut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'ja tuokoon hyvityksenä Herralle rikkomuksesta, jonka hän on tehnyt, naaraspuolen pikkukarjasta, uuhen tai vuohen, syntiuhriksi; ja pappi toimittakoon hänelle sovituksen hänen rikkomuksestansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Mutta jollei hän saa hankituksi sellaista eläintä, niin tuokoon Herralle hyvitykseksi siitä, mitä on rikkonut, kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa, toisen syntiuhriksi ja toisen polttouhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'ja vieköön ne papille. Tämä uhratkoon ensiksi sen, joka on määrätty syntiuhriksi, vääntäköön siltä niskat poikki, päätä kuitenkaan irroittamatta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'ja pirskoittakoon syntiuhrin verta alttarin seinään, ja puserrettakoon se veri, joka jää jäljelle, alttarin juurelle; se on syntiuhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Ja toisen hän säädetyllä tavalla valmistakoon polttouhriksi. Kun pappi näin on toimittanut hänelle sovituksen hänen rikkomuksestaan, jonka hän on tehnyt, annetaan hänelle anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Jollei hän saa hankituksi kahta metsäkyyhkystä tai kahta kyyhkysenpoikaa, niin tuokoon uhrilahjanaan sen sovittamiseksi, mitä on rikkonut, kymmenennen osan eefa-mittaa lestyjä jauhoja syntiuhriksi, mutta älköön vuodattako siihen öljyä älköönkä panko sen päälle suitsuketta, sillä se on syntiuhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Ja vieköön sen papille, ja pappi ottakoon siitä kourallisen, alttariuhriosan, ja polttakoon sen alttarilla Herran uhrin päällä; se on syntiuhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Kun pappi näin on toimittanut hänelle sovituksen jostakin sellaisesta hänen tekemästään rikkomuksesta, annetaan hänelle anteeksi. Ja papille tulkoon se, mikä ruokauhristakin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, '\"Jos joku lankeaa uskottomuuteen ja erehdyksestä rikkoo anastamalla sitä, mikä on Herralle pyhitetty, tuokoon hyvityksenä Herralle vikauhriksi virheettömän oinaan pikkukarjasta, niin monen hopeasekelin arvoisen, pyhäkkösekelin painon mukaan, kuin sinä arvioit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Ja mitä hän on pyhitetystä anastanut itselleen, sen hän korvatkoon ja pankoon siihen lisäksi vielä viidennen osan sen arvosta ja antakoon sen papille. Kun pappi näin on toimittanut hänelle sovituksen uhraamalla vikauhrioinaan, annetaan hänelle anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Jos joku rikkoo jotakuta Herran käskyä vastaan ja tekee tietämättään sellaista, mitä ei saa tehdä, ja tulee vikapääksi ja joutuu syynalaiseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'niin tuokoon papille vikauhriksi pikkukarjasta sinun arviosi mukaisen, virheettömän oinaan. Kun pappi on toimittanut hänelle sovituksen siitä erehdyksestä, jonka hän on tietämättään tehnyt, annetaan hänelle anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Se on vikauhri; sillä hän on tullut vikapääksi Herran edessä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '\"Jos joku tekee rikkomuksen ja on uskoton Herraa kohtaan kieltämällä saaneensa lähimmäiseltään, mitä tämä on hänen haltuunsa antanut tai hänen hoitoonsa uskonut, tahi mitä hän itse on väkisin ottanut tai vääryydellä anastanut lähimmäiseltään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'tahi jos hän on löytänyt kadotetun esineen ja kieltää sen, tahi vannoo väärin missä asiassa tahansa, jossa ihminen helposti rikkoo,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'niin hän, jos hän näin on rikkonut ja tullut vikapääksi, antakoon takaisin, mitä hän väkisin on ottanut tai vääryydellä anastanut, tahi mitä hänen haltuunsa oli uskottu, tahi kadotetun esineen, jonka hän oli löytänyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'kaiken, jonka tähden hän oli väärin vannonut; ja korvatkoon sen täyteen määräänsä ja pankoon siihen vielä lisäksi viidennen osan sen arvosta. Sille, jonka oma se on, hän antakoon sen sinä päivänä, jona hän vikauhrinsa toimittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Mutta hyvityksenä Herralle hän tuokoon papille vikauhriksi sinun arviosi mukaisen, virheettömän oinaan pikkukarjasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Kun pappi näin on toimittanut hänelle sovituksen Herran edessä, annetaan hänelle anteeksi kaikki, mitä hän on tehnyt sellaista, josta hän on tullut vikapääksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, '\"Käske Aaronia ja hänen poikiansa ja sano: Tämä on laki polttouhrista. Polttouhri olkoon alttarin liedellä koko yön aamuun asti, ja tulta pidettäköön siten vireillä alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Ja pappi pukeutukoon pellavapukuunsa ja pukeutukoon pellavakaatioihin peittääkseen häpynsä, ja korjatkoon pois tuhan, joksi tuli on kuluttanut polttouhrin alttarilla, ja pankoon sen alttarin viereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Ja sitten hän riisukoon vaatteensa ja pukeutukoon toisiin vaatteisiin, ja vieköön tuhan leirin ulkopuolelle puhtaaseen paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Ja tulta pidettäköön siten vireillä alttarilla älköönkä se koskaan sammuko; ja pappi sytyttäköön alttarilla halot joka aamu ja asettakoon sen päälle polttouhrin ja polttakoon sen päällä yhteysuhrin rasvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Tuli palakoon aina alttarilla älköönkä koskaan sammuko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Ja tämä on laki ruokauhrista: Aaronin pojat tuokoot sen Herran eteen, alttarin ääreen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Ja pappi erottakoon ruokauhrista kourallisen lestyjä jauhoja ja öljyä ja kaiken suitsukkeen, joka on ruokauhrin päällä, ja polttakoon alttarilla alttariuhriosan suloiseksi tuoksuksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Ja mikä siitä jää tähteeksi, sen syököön Aaron poikinensa; happamatonna se syötäköön pyhässä paikassa, ilmestysmajan esipihalla he sen syökööt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Älköön sitä leivottako hapatettuna. Heidän osakseen minä olen sen uhreistani antanut; se on korkeasti-pyhää niinkuin syntiuhri ja vikauhrikin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Jokainen miehenpuoli Aaronin jälkeläisistä syököön siitä. Tämä olkoon heidän ikuinen osuutensa Herran uhreista sukupolvesta sukupolveen. Jokainen, joka niihin koskee, on pyhäkölle pyhitetty.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, '\"Tämä olkoon Aaronin ja hänen poikiensa uhrilahja, joka heidän on tuotava Herralle voitelupäivänänsä: kymmenes osa eefa-mittaa lestyjä jauhoja jokapäiväiseksi ruokauhriksi, puolet aamulla ja puolet illalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Leivinlevyllä se valmistettakoon öljyyn leivottuna; tuo se hyvin sotkettuna ja uhraa se palasiksi paloiteltuna ruokauhrina suloiseksi tuoksuksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Ja pappi, joka hänen pojistaan on hänen sijaansa voideltu, toimittakoon sen. Se on Herran ikuinen osuus; se poltettakoon kokonaisuhrina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Jokainen papin ruokauhri on kokonaisuhri; älköön sitä syötäkö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, '\"Puhu Aaronille ja hänen pojillensa ja sano: Tämä on laki syntiuhrista. Siinä paikassa, missä polttouhri teurastetaan, teurastettakoon myös syntiuhri Herran edessä; ja se on korkeasti-pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Pappi, joka syntiuhrin uhraa, syököön sen; pyhässä paikassa se syötäköön, ilmestysmajan esipihalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Jokainen, joka sen lihaan koskee, on pyhäkölle pyhitetty, ja jos sen verta on pirskunut vaatteille, niin pese pyhässä paikassa se, mihin sitä on pirskunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Ja saviastia, jossa se keitetään, rikottakoon; jos se on keitetty vaskiastiassa, hangattakoon astia puhtaaksi ja huuhdottakoon vedellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Jokainen miehenpuoli papeista saakoon sitä syödä; se on korkeasti-pyhää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Mutta mitään syntiuhria, jonka verta viedään ilmestysmajaan sovituksen toimittamista varten pyhäkössä, älköön syötäkö, vaan se poltettakoon tulessa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, '\"Ja tämä on laki vikauhrista. Se on korkeasti-pyhää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Siinä paikassa, missä polttouhri teurastetaan, teurastettakoon myös vikauhri, ja sen veri vihmottakoon alttarille ympärinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Ja kaikki sen rasva uhrattakoon, sekä rasvahäntä että sisälmyksiä peittävä rasva,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'ja molemmat munuaiset ynnä niiden päällä lantiolihaksissa oleva rasva ja maksanlisäke, joka on irroitettava munuaisten luota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Ja pappi polttakoon ne alttarilla uhrina Herralle; se on vikauhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Jokainen miehenpuoli papeista saakoon sitä syödä. Se syötäköön pyhässä paikassa; se on korkeasti-pyhää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Mitä on säädetty syntiuhrista, koskee vikauhriakin; laki on sama molemmista. Se olkoon sen papin oma, joka sillä sovituksen toimittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Ja pappi, joka toimittaa jonkun puolesta polttouhrin, saakoon uhraamansa polttouhriteuraan nahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Ja jokainen ruokauhri, joka paistetaan uunissa, ja jokainen pannussa tai leivinlevyllä valmistettu, olkoon sen papin oma, joka uhrin toimittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Mutta jokainen muu ruokauhri, olipa siihen sekoitettu öljyä tai olipa se kuiva, olkoon kaikkien Aaronin poikien oma, yhden niinkuin toisenkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Ja tämä on laki yhteysuhrista, joka Herralle tuodaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Jos joku tuo sen kiitokseksi, niin tuokoon kiitosuhriteuraan lisäksi öljyyn leivottuja happamattomia kakkuja, öljyllä voideltuja happamattomia ohukaisia ja sekoitettuja lestyjä jauhoja öljyyn leivottuina kakkuina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Hapatetusta taikinasta leivottujen kakkujen ohella hän tuokoon tämän uhrilahjansa kiitosuhrina uhratun yhteysuhriteuraan lisäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Ja hän tuokoon siitä yhden kutakin uhrilahja-lajia anniksi Herralle; se olkoon sen papin oma, joka vihmoo yhteysuhrin veren.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Ja kiitosuhrina uhratun yhteysuhriteuraan liha syötäköön sinä päivänä, jona se on uhrattu, älköönkä mitään siitä jätettäkö seuraavaan aamuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Mutta jos uhrilahjana tuotu teuras on lupausuhri tai vapaaehtoinen uhri, syötäköön se sinä päivänä, jona se on tuotu; jos kuitenkin jotakin siitä jää tähteeksi, saatakoon se syödä seuraavana päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Mutta mitä uhrilihasta on tähteenä kolmantena päivänä, se poltettakoon tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Jos yhteysuhriteuraan lihaa syödään kolmantena päivänä, ei se ole otollinen eikä sitä lueta tuojan hyväksi, vaan se on saastaista; jokainen, joka sitä syö, joutuu syynalaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Sitä lihaa, joka on sattunut saastaiseen, mihin tahansa, älköön syötäkö, vaan se poltettakoon tulessa; muuten saakoon jokainen, joka on puhdas, syödä yhteysuhriteuraan lihaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Mutta jokainen, joka saastaisena ollessaan syö yhteysuhriteuraan lihaa, joka on Herran oma, hävitettäköön kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Jos joku koskee johonkin saastaiseen, mihin tahansa, joko ihmisen saastaan tahi saastaiseen karjaeläimeen tai mihin inhottavaan saastaan tahansa, ja syö yhteysuhriteuraan lihaa, joka on Herran oma, hänet hävitettäköön kansastansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, '\"Puhu israelilaisille ja sano: Älkää syökö mitään härän, lampaan tai vuohen rasvaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Itsestään kuolleen tai kuoliaaksi raadellun eläimen rasva käytettäköön kaikkinaisiin tarpeisiin; mutta älkää sitä syökö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Sillä jokainen, joka syö sen eläimen rasvaa, josta tuodaan Herralle uhri, hävitettäköön kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Älkää myöskään, missä asuttekin, syökö mitään verta, ei lintujen eikä karjaeläinten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Jokainen, joka syö verta, minkälaista hyvänsä, hävitettäköön kansastansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, '\"Puhu israelilaisille ja sano: Joka tuo Herralle yhteysuhrinsa, tuokoon Herralle uhrilahjan tästä yhteysuhristaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Omin käsin hän tuokoon Herran uhrit; tuokoon rasvan ynnä rintalihan, ja toimitettakoon niiden heilutus Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Ja pappi polttakoon rasvan alttarilla, mutta rintaliha olkoon Aaronin ja hänen poikiensa oma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Ja oikea reisi antakaa papille anniksi yhteysuhriteuraistanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Se Aaronin pojista, joka uhraa yhteysuhrin veren ja rasvan, saakoon oikean reiden osaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Sillä minä olen ottanut heilutus-rintalihan ja anniksi annetun reiden israelilaisilta heidän yhteysuhriteuraistansa ja antanut ne pappi Aaronille ja hänen pojillensa ikuiseksi osuudeksi israelilaisilta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Tämä on Aaronin ja hänen poikiensa osa Herran uhreista, joka heille määrättiin sinä päivänä, jona hän toi heidät pappeina palvelemaan Herraa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'sen osan Herra käski sinä päivänä, jona hän heidät voiteli, israelilaisten antaa heille ikuiseksi osuudeksi sukupolvesta sukupolveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Tämä on se laki polttouhrista, ruokauhrista, syntiuhrista, vikauhrista, vihkiäisuhrista ja yhteysuhrista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'jonka lain Herra antoi Moosekselle Siinain vuorella sinä päivänä, jona hän antoi israelilaisille käskyn tuoda uhrilahjansa Herralle Siinain erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, '\"Ota Aaron ja hänen poikansa ynnä heidän vaatteensa ja voiteluöljy sekä syntiuhrimullikka ja ne kaksi oinasta ja kori, jossa happamattomat leivät ovat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'ja kokoa kaikki seurakunta ilmestysmajan oven eteen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Ja Mooses teki, niinkuin Herra oli häntä käskenyt, ja seurakunta kokoontui ilmestysmajan oven eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Ja Mooses sanoi seurakunnalle: \"Näin on Herra käskenyt tehdä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Ja Mooses toi Aaronin ja hänen poikansa esille ja pesi heidät vedellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Sitten hän pani hänen yllensä ihokkaan ja vyötti hänet vyöllä ja puki hänet viittaan ja pani kasukan hänen päälleen ja vyötti hänet kasukan vyöllä ja sitoi sen hänen ympärilleen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'ja asetti hänen rintaansa rintakilven ja pani kilpeen uurimin ja tummimin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'ja pani käärelakin hänen päähänsä ja pani käärelakkiin, sen etupuolelle, kultaisen otsakoristeen, pyhän otsalehden, niinkuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Ja Mooses otti voiteluöljyn ja voiteli asumuksen ja kaikki, mitä siinä oli, ja pyhitti ne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'ja hän pirskoitti sitä seitsemän kertaa alttarille ja voiteli alttarin kaikkine kaluineen ynnä altaan jalustoineen pyhittääkseen ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Ja hän vuodatti voiteluöljyä Aaronin päähän ja voiteli hänet pyhittääkseen hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Ja Mooses toi esille Aaronin pojat ja puki heidän yllensä ihokkaat ja vyötti heidät vyöllä ja sitoi päähineet heidän päähänsä, niinkuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Ja hän toi esille syntiuhrimullikan, ja Aaron ja hänen poikansa laskivat kätensä syntiuhrimullikan pään päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Sitten Mooses teurasti sen ja otti sen verta ja siveli sitä sormellansa alttarin sarviin yltympäri ja puhdisti alttarin; ja muun veren hän vuodatti alttarin juurelle ja pyhitti sen toimittamalla sen sovituksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Ja Mooses otti kaiken sisälmysten päällä olevan rasvan ja maksanlisäkkeen ja molemmat munuaiset rasvoineen ja poltti ne alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Mutta mullikan nahkoinensa, lihoinensa ja rapoinensa hän poltti tulessa leirin ulkopuolella, niinkuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Ja hän toi esille polttouhrioinaan, ja Aaron ja hänen poikansa laskivat kätensä oinaan pään päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Ja Mooses teurasti sen ja vihmoi veren alttarille ympärinsä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'ja leikkeli oinaan määräkappaleiksi; sitten Mooses poltti pään ynnä kappaleet ja rasvan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Mutta sisälmykset ja jalat hän pesi vedessä; ja niin Mooses poltti koko oinaan alttarilla. Se oli polttouhri suloiseksi tuoksuksi, uhri Herralle, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Ja hän toi esille toisen oinaan, vihkiäisoinaan, ja Aaron ja hänen poikansa laskivat kätensä oinaan pään päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Ja Mooses teurasti sen ja otti sen verta ja siveli sitä Aaronin oikean korvan lehteen ja oikean käden peukaloon ja oikean jalan isoonvarpaaseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Ja Mooses toi Aaronin pojat esille ja siveli verta heidän oikean korvansa lehteen ja oikean kätensä peukaloon ja heidän oikean jalkansa isoonvarpaaseen, mutta vihmoi muun veren alttarille ympärinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Ja hän otti rasvan ja rasvahännän ja kaiken sisälmysten päällä olevan rasvan ja maksanlisäkkeen ja molemmat munuaiset rasvoineen ja oikean reiden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Sitten hän otti happamattomien leipien korista, joka oli Herran edessä, yhden happamattoman kakun ja yhden öljyyn leivotun kakun ja yhden ohukaisen ja pani ne rasvojen ja oikean reiden päälle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'ja pani kaikki nämä Aaronin käsiin ja hänen poikiensa käsiin, ja toimitutti niiden heilutuksen Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Sitten Mooses otti ne heidän käsistänsä ja poltti ne alttarilla polttouhrin päällä; tämä oli vihkiäisuhri suloiseksi tuoksuksi, uhri Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Ja Mooses otti rintalihan ja toimitti sen heilutuksen Herran edessä; vihkiäisoinaasta tuli tämä Mooseksen osaksi, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Ja Mooses otti voiteluöljyä ja verta, jota oli alttarilla, ja pirskoitti sitä Aaronin ja hänen vaatteidensa päälle ja samoin hänen poikiensa ja heidän vaatteidensa päälle ja pyhitti niin Aaronin ja hänen vaatteensa ynnä hänen poikansa ja heidän vaatteensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Ja Mooses sanoi Aaronille ja hänen pojillensa: \"Keittäkää liha ilmestysmajan ovella ja syökää se siinä ynnä leipä, joka on vihkiäisuhriin kuuluvassa korissa, niinkuin minä olen käskenyt ja sanonut: Aaron poikinensa syököön sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Mutta mitä jää tähteeksi lihasta ja leivästä, se polttakaa tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Seitsemään päivään älkää lähtekö ilmestysmajan ovelta, älkää ennenkuin teidän vihkimispäivänne ovat kuluneet umpeen, sillä seitsemän päivää kestää teidän vihkimisenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Niinkuin on tehty tänä päivänä, niin on Herra käskenyt vastakin tehdä toimittaakseen teille sovituksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Ja olkaa seitsemän päivää ilmestysmajan ovella, päivät ja yöt, ja toimittakaa Herran palvelustehtävät, ettette kuolisi; sillä niin on minulle käsky annettu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Ja Aaron ja hänen poikansa tekivät kaiken, mitä Herra oli Mooseksen kautta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Ja kahdeksantena päivänä Mooses kutsui Aaronin ja hänen poikansa ja Israelin vanhimmat');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'ja sanoi Aaronille: \"Ota itsellesi härkävasikka syntiuhriksi ja oinas polttouhriksi, molemmat virheettömiä, ja tuo ne Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Ja puhu israelilaisille ja sano: \'Ottakaa kauris syntiuhriksi ja vasikka ja karitsa, molemmat vuoden vanhoja ja virheettömiä, polttouhriksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'ja härkä ja oinas yhteysuhriksi, uhrattaviksi Herran edessä, ynnä ruokauhri, johon on öljyä sekoitettu, sillä tänä päivänä ilmestyy teille Herra\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Ja he toivat, mitä Mooses oli käskenyt, ilmestysmajan edustalle, ja koko seurakunta astui esiin ja asettui Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Ja Mooses sanoi: \"Näin Herra on käskenyt teidän tehdä, että Herran kirkkaus ilmestyisi teille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Ja Mooses sanoi Aaronille: \"Astu alttarin ääreen ja uhraa syntiuhrisi ja polttouhrisi ja toimita itsellesi ja kansalle sovitus ja uhraa sitten kansan uhrilahja ja toimita heille sovitus, niinkuin Herra on käskenyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Niin Aaron astui alttarin ääreen ja teurasti oman syntiuhrivasikkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Ja Aaronin pojat toivat hänelle veren, ja hän kastoi sormensa vereen ja siveli sitä alttarin sarviin, mutta muun veren hän vuodatti alttarin juurelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Mutta syntiuhriteuraan rasvan ja munuaiset ja maksanlisäkkeen hän poltti alttarilla, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Ja lihan ja nahan hän poltti tulessa leirin ulkopuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Sitten hän teurasti polttouhrin, ja Aaronin pojat ojensivat hänelle veren, ja hän vihmoi sen alttarille ympärinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Ja he ojensivat hänelle polttouhrin kappaleittain ynnä pään, ja hän poltti ne alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Ja hän pesi sisälmykset ja jalat ja poltti ne polttouhrin päällä alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Sitten hän toi kansan uhrilahjan ja otti kansan syntiuhrikauriin, teurasti sen ja uhrasi sen syntiuhrina samalla tavalla kuin edellisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Ja hän toi myös polttouhrin ja uhrasi sen säädetyllä tavalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Ja hän toi ruokauhrin ja otti siitä kouransa täyden ja poltti sen alttarilla aamu-polttouhrin lisäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Sitten hän teurasti härän ja oinaan kansan yhteysuhriksi, ja Aaronin pojat ojensivat hänelle veren, ja hän vihmoi sen alttarille ympärinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Mutta härän ja oinaan rasvat, rasvahännän, rasvakalvon, munuaiset ja maksanlisäkkeen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'nämä rasvat he panivat rintalihojen päälle, ja hän poltti rasvat alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Mutta rintalihain ja oikean reiden heilutuksen Aaron toimitti Herran edessä, niinkuin Mooses oli käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Ja Aaron kohotti kätensä kansaa kohti ja siunasi heidät, ja kun hän oli toimittanut syntiuhrin, polttouhrin ja yhteysuhrin, astui hän alas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Ja Mooses ja Aaron menivät ilmestysmajaan, ja kun he tulivat sieltä ulos, siunasivat he kansan. Silloin Herran kirkkaus ilmestyi kaikelle kansalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Ja tuli lähti Herran tyköä ja kulutti polttouhrin ja rasvat alttarilta. Ja kaikki kansa näki sen, ja he riemuitsivat ja lankesivat kasvoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Ja Aaronin pojat Naadab ja Abihu ottivat kumpikin hiilipannunsa ja virittivät niihin tulen ja panivat suitsuketta sen päälle ja toivat vierasta tulta Herran eteen, vastoin hänen käskyänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Silloin lähti tuli Herran tyköä ja kulutti heidät, niin että he kuolivat Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Niin Mooses sanoi Aaronille: \"Tämä tapahtuu Herran sanan mukaan: Niissä, jotka ovat minua lähellä, minä osoitan pyhyyteni ja kaiken kansan edessä kirkkauteni\". -Mutta Aaron oli ääneti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Ja Mooses kutsui Miisaelin ja Elsafanin, Aaronin sedän Ussielin pojat, ja sanoi heille: \"Astukaa esiin ja kantakaa sukulaisenne pyhäkön läheisyydestä leirin ulkopuolelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Ja he astuivat esiin ja kantoivat heidät ihokkaineen leirin ulkopuolelle, niinkuin Mooses oli sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Sitten Mooses sanoi Aaronille ja hänen pojillensa Eleasarille ja Iitamarille: \"Älkää päästäkö tukkaanne hajalle älkääkä repikö vaatteitanne, ettette kuolisi ja ettei hänen vihansa kohtaisi koko seurakuntaa; mutta teidän veljenne, koko Israelin heimo, itkekööt tätä paloa, jonka Herra on sytyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Älkääkä poistuko ilmestysmajan ovelta, ettette kuolisi, sillä Herran voiteluöljy on teissä.\" Ja he tekivät, niinkuin Mooses oli sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Ja Herra puhui Aaronille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, '\"Viiniä ja väkijuomaa älkää juoko, älä sinä älköötkä sinun poikasi sinun kanssasi, kun menette ilmestysmajaan, ettette kuolisi. Tämä olkoon teille ikuinen säädös sukupolvesta sukupolveen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'tehdäksenne erotuksen pyhän ja epäpyhän, saastaisen ja puhtaan välillä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'ja opettaaksenne israelilaisille kaikki ne käskyt, jotka Herra on heille Mooseksen kautta puhunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Ja Mooses puhui Aaronille ja hänen eloon jääneille pojillensa Eleasarille ja Iitamarille: \"Ottakaa se ruokauhri, joka on jäänyt tähteeksi Herran uhreista, ja syökää se happamattomana alttarin ääressä; sillä se on korkeasti-pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Ja syökää se pyhässä paikassa, sillä se on sinun osuutesi ja sinun poikiesi osuus Herran uhreista; niin on minulle käsky annettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Mutta heilutus-rintaliha ja anniksi annettu reisi syökää puhtaassa paikassa, sinä ja sinun poikasi ja tyttäresi sinun kanssasi; sillä ne ovat sinun osuudeksesi ja sinun poikiesi osuudeksi annetut israelilaisten yhteysuhriteuraista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Anniksi annettu reisi ja heilutus-rintaliha tuotakoon uhrirasvojen kanssa ja toimitettakoon niiden heilutus Herran edessä; ne olkoot sinun ja sinun poikiesi ikuinen osuus, niinkuin Herra on käskenyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Ja Mooses tiedusteli syntiuhrikaurista, ja katso, se oli poltettu. Silloin hän vihastui Eleasariin ja Iitamariin, Aaronin eloon jääneihin poikiin, ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '\"Miksi ette ole syöneet syntiuhria pyhässä paikassa? Sehän on korkeasti-pyhä, ja hän on antanut sen teille, että poistaisitte kansan syntivelan ja toimittaisitte heille sovituksen Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Katso, ei ole sen verta tuotu pyhäkköön sisälle; teidän olisi tullut syödä se pyhäkössä, niinkuin minä olen käskenyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Mutta Aaron sanoi Moosekselle: \"Katso, he ovat tänä päivänä tuoneet syntiuhrinsa ja polttouhrinsa Herran eteen, ja kuitenkin on tämä minua kohdannut; jos minä tänä päivänä söisin syntiuhria, olisikohan se Herralle otollista?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Kun Mooses sen kuuli, tyytyi hän siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Ja Herra puhui Moosekselle ja Aaronille sanoen heille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, '\"Puhukaa israelilaisille ja sanokaa: Nämä ovat ne eläimet, joita te saatte syödä kaikista nelijalkaisista eläimistä maan päällä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Kaikkia nelijalkaisia eläimiä, joilla on kokonansa halkinaiset sorkat ja jotka märehtivät, te saatte syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Näitä älkää kuitenkaan syökö niistä, jotka märehtivät, ja niistä, joilla on sorkat: kamelia, joka kyllä märehtii, mutta jolla ei ole sorkkia: se olkoon teille saastainen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'tamaania, joka kyllä märehtii, mutta jolla ei ole sorkkia: se olkoon teille saastainen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'jänistä, joka kyllä märehtii, mutta jolla ei ole sorkkia: se olkoon teille saastainen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'sikaa, jolla tosin on kokonansa halkinaiset sorkat, mutta joka ei märehdi: se olkoon teille saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Näiden lihaa älkää syökö ja näiden raatoihin älkää koskeko, ne olkoot teille saastaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Näitä te saatte syödä kaikista vesieläimistä: kaikkia, joilla on evät ja suomukset ja jotka elävät vedessä, niin hyvin merissä kuin joissa, te saatte syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Mutta kaikista niistä, joita vedet vilisevät, kaikista elollisista, jotka elävät vedessä, inhotkaa kaikkia niitä, joilla ei ole eviä eikä suomuksia, elivätpä merissä tai joissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Niitä inhotkaa; niiden lihaa älkää syökö, ja niiden raadot inhottakoot teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Kaikkia niitä vesieläimiä, joilla ei ole eviä eikä suomuksia, inhotkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Linnuista taas inhotkaa näitä; älköön niitä syötäkö, vaan olkoot inhottavia: kotka, partakorppikotka ja harmaa korppikotka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'haarahaukka ja suohaukkalajit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'kaikki kaarnelajit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'kamelikurki, pääskynen, kalalokki ja jalohaukkalajit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'huuhkaja, kalasääksi ja kissapöllö,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'sarvipöllö, pelikaani ja likakorppikotka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'haikara ja sirriäislajit, harjalintu ja yölepakko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Ja kaikkia siivellisiä pikkueläimiä, jotka liikkuvat neljällä jalalla, inhotkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Kuitenkin saatte siivellisistä pikkueläimistä, jotka liikkuvat neljällä jalalla, syödä niitä, joilla jalkojen yläpuolella on kaksi säärtä hypelläksensä niillä maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Niistä te saatte syödä seuraavia: heinäsirkkalajeja, solam-sirkkalajeja, hargol-sirkkalajeja ja haagab-sirkkalajeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Mutta kaikkia muita siivellisiä pikkueläimiä, joilla on neljä jalkaa, inhotkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Seuraavista eläimistä te tulette saastaisiksi; jokainen, joka niiden raatoihin koskee, olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Ja jokainen, joka niiden raatoja kantaa, pesköön vaatteensa ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Kaikki nelijalkaiset eläimet, joilla on sorkat, mutta ei kokonaan halkinaiset, ja jotka eivät märehdi, olkoot teille saastaiset; jokainen, joka niihin koskee, olkoon saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Ja kaikki nelijalkaiset eläimet, jotka käyvät käpälillä, olkoot teille saastaiset; jokainen, joka niiden raatoihin koskee, olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Ja joka kantaa niiden raatoja, pesköön vaatteensa ja olkoon saastainen iltaan asti; ne olkoot teille saastaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Ja nämä olkoot teille saastaiset niistä pikkueläimistä, jotka liikkuvat maassa: myyrä, hiiri ja sisiliskolajit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'anaka-eläin, kooah-eläin, letaa-eläin, hoomet-eläin ja kameleontti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Ne olkoot teille saastaiset kaikista pikkueläimistä; jokainen, joka niihin koskee, sittenkuin ne ovat kuolleet, olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Ja kaikki, minkä päälle joku niistä kuolleena putoaa, on saastaista, olipa se sitten puuastia tai vaatekappale tai nahka tai säkki tai mikä tahansa kalu, jota johonkin tarpeeseen käytetään. Se pantakoon veteen ja olkoon saastainen iltaan asti; sitten se on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Ja jos joku niistä putoaa saviastiaan, on kaikki, mitä siinä on, saastaista, ja astia rikottakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Kaikki ruoka, jota syödään, on saastaista, jos sen astian vettä tulee siihen; ja kaikki juoma, jota juodaan, on jokaisessa sellaisessa astiassa saastaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Ja kaikki, minkä päälle niiden raato putoaa, tulee saastaiseksi; olkoon se leivinuuni tai liesi, niin se revittäköön maahan; sillä saastaisia ne ovat ja saastaisia ne teille olkoot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Kuitenkin lähde tai kaivo, paikka, johon vettä on kokoontunut, pysyy puhtaana. Mutta joka niiden raatoon koskee, olkoon saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Ja jos niiden raato putoaa kylvösiemenen päälle, minkä hyvänsä, joka kylvetään, pysyy tämä puhtaana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Mutta jos siemen on vedellä kasteltu ja niiden raato putoaa sen päälle, tulee siemen teille saastaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Ja jos joku eläin, joka on teille ravinnoksi, kuolee, olkoon se, joka sen raatoon koskee, saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Ja joka syö sen raatoa, pesköön vaatteensa ja olkoon saastainen iltaan asti; ja joka kantaa sen raatoa, pesköön vaatteensa ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Kaikki pikkueläimet, jotka liikkuvat maassa, olkoot inhottavia; älköön niitä syötäkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Kaikista niistä, jotka käyvät vatsallansa, ja kaikista pikkueläimistä, jotka liikkuvat maassa, käyden neljällä tai useammalla jalalla, niistä älkää mitään syökö, sillä ne ovat inhottavia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Älkää saattako itseänne inhottaviksi koskemalla matelevaan pikkueläimeen, mihin tahansa, älkääkä saastuttako itseänne niillä, niin että tulette niistä saastaisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Sillä minä olen Herra, teidän Jumalanne; pyhittäkää siis itsenne ja olkaa pyhät, sillä minä olen pyhä. Niin älkää saastuttako itseänne koskemalla mihinkään pikkueläimeen, joka liikkuu maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Sillä minä olen Herra, joka olen johdattanut teidät Egyptin maasta, ja joka olen teidän Jumalanne; olkaa siis pyhät, sillä minä olen pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Tämä on laki nelijalkaisista eläimistä ja linnuista ja kaikista elollisista, joita vedessä vilisee, ja kaikista olennoista, joita maassa liikkuu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'että tietäisitte erottaa puhtaat saastaisista ja syötävät eläimet niistä eläimistä, joita ei saa syödä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, '\"Puhu israelilaisille ja sano: Kun vaimo tulee hedelmälliseksi ja synnyttää poikalapsen, olkoon hän saastainen seitsemän päivää; yhtä monta päivää kuin hänen kuukautisensa kestävät, hän olkoon saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Ja kahdeksantena päivänä ympärileikattakoon pojan esinahan liha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Mutta vaimo pysyköön kotona kolmekymmentä kolme päivää puhdistavan verenvuotonsa aikana; älköön hän koskeko mihinkään, mikä on pyhää, älköönkä tulko pyhäkköön, ennenkuin hänen puhdistuspäivänsä ovat kuluneet umpeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Mutta jos hän synnyttää tyttölapsen, olkoon hän saastainen kaksi viikkoa, samoinkuin kuukautisissaan, ja pysyköön kotona kuusikymmentä kuusi päivää puhdistavan verenvuotonsa aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Mutta kun hänen puhdistuspäivänsä pojan tai tyttären jälkeen ovat kuluneet umpeen, vieköön hän vuoden vanhan karitsan polttouhriksi ja kyyhkysenpojan tai metsäkyyhkysen syntiuhriksi ilmestysmajan oven eteen papille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Ja tämä tuokoon ne Herran eteen ja toimittakoon hänelle sovituksen, niin hän on puhdas verenvuodostansa. Tämä on laki lapsensynnyttäjästä, olipa hän synnyttänyt poika-tai tyttölapsen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Mutta jos hän ei saa hankituksi lammasta, ottakoon kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa, toisen polttouhriksi ja toisen syntiuhriksi; ja pappi toimittakoon hänelle sovituksen, niin hän on puhdas.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Ja Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, '\"Jos jonkun ihoon tulee nystyrä tai ihottuma tai vaalea pilkku, niinkuin pitalitauti olisi tulemassa hänen ihoonsa, vietäköön hänet pappi Aaronin tai jonkun hänen poikansa, pappien, eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Ja jos pappi tarkastaessaan sairasta paikkaa ihossa huomaa, että karvat sairaassa paikassa ovat muuttuneet valkoisiksi ja että se paikka näyttää muuta ihoa matalammalta, on se pitalitautia; ja niin pian kuin pappi on sen huomannut, julistakoon hän hänet saastaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Ja jos hänen ihossansa on valkea pilkku, mutta se ei näytä muuta ihoa matalammalta eivätkä karvat ole muuttuneet valkoisiksi, sulkekoon pappi sairaan sisälle seitsemäksi päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Ja seitsemäntenä päivänä pappi tarkastakoon häntä, ja jos sairas paikka hänestä näyttää pysyneen entisellään sairauden leviämättä ihossa, sulkekoon pappi hänet sisälle vielä seitsemäksi päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Ja seitsemäntenä päivänä pappi uudestaan tarkastakoon häntä, ja jos hän huomaa että sairas paikka on käynyt vaaleaksi ja että sairaus ei ole ihossa levinnyt, julistakoon pappi hänet puhtaaksi, sillä se on ihottumaa; hän pesköön vaatteensa, ja niin hän on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Mutta jos ihottuma leviää leviämistään hänen ihossansa, sen jälkeen kuin hän oli näyttäytynyt papille tullakseen puhtaaksi julistetuksi, näyttäytyköön uudestaan papille;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'ja jos pappi huomaa ihottuman levinneen ihossa, julistakoon pappi hänet saastaiseksi; se on pitalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Jos pitalitauti ilmestyy ihmiseen, vietäköön hänet papin luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Ja jos pappi tarkastaessaan huomaa ihossa valkoisen nystyrän, jonka kohdalta karvat ovat muuttuneet valkoisiksi, ja liikaa lihaa kasvavan nystyrään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'on hänen ihossaan jo vanha pitali, ja sentähden pappi julistakoon hänet saastaiseksi älköönkä enää sulkeko häntä sisälle, sillä hän on saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Ja jos pitali puhkeaa ihossa, niin että se peittää sairaan koko ihon päästä jalkoihin asti, mihin pappi katsokoonkin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'ja jos pappi tarkastaessaan huomaa pitalin peittävän koko ihon, niin julistakoon hän sairaan puhtaaksi; hän on kokonansa muuttunut valkoiseksi ja on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Mutta niin pian kuin häneen ilmestyy liikaa lihaa, on hän saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Ja kun pappi huomaa liian lihan, julistakoon hän hänet saastaiseksi; liika liha on saastaista, se on pitalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Mutta jos liika liha häviää ja sairas paikka muuttuu valkoiseksi, menköön hän papin luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Ja jos pappi huomaa, että sairas paikka on muuttunut valkoiseksi, julistakoon pappi sairaan puhtaaksi; hän on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Ja jos jonkun ihoon tulee paise, joka paranee jälleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'ja paiseen sijalle tulee valkoinen nystyrä tai vaaleanpunainen pilkku, näyttäytyköön hän papille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Ja jos pappi tarkastaessaan huomaa, että se paikka näyttää muuta ihoa matalammalta ja että karvat siinä ovat muuttuneet valkoisiksi, julistakoon pappi hänet saastaiseksi; paiseeseen on puhjennut pitalitauti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Mutta jos pappi tarkastaessaan huomaa, ettei siinä ole valkoisia karvoja ja ettei se paikka ole muuta ihoa matalampi ja että se on käynyt vaaleaksi, sulkekoon pappi hänet sisälle seitsemäksi päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Ja jos se leviää leviämistään hänen ihossaan, julistakoon pappi hänet saastaiseksi; se on pitalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Mutta jos pilkku pysyy alallansa eikä leviä, on se paiseen arpi, ja pappi julistakoon hänet puhtaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Tahi jos joku saa palohaavan ihoonsa ja palohaavaan kasvavaan lihaan ilmestyy vaaleanpunainen tai valkoinen pilkku,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'ja jos pappi tarkastaessaan huomaa karvojen muuttuneen valkoisiksi siinä pilkussa ja sen paikan näyttävän muuta ihoa matalammalta, niin on palohaavaan puhjennut pitali, ja pappi julistakoon hänet saastaiseksi; se on pitalitautia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Mutta jos pappi tarkastaessaan huomaa, ettei pilkussa ole valkoisia karvoja ja ettei se ole muuta ihoa matalampi ja että se on käynyt vaaleaksi, niin sulkekoon pappi hänet sisälle seitsemäksi päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Ja seitsemäntenä päivänä pappi tarkastakoon häntä; jos se on yhä levinnyt ihossa, julistakoon pappi hänet saastaiseksi; se on pitalitautia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Mutta jos pilkku on pysynyt alallansa eikä ole levinnyt ihossa ja on edelleen vaalennut, on se palohaavasta syntynyt nystyrä, ja pappi julistakoon hänet puhtaaksi; se on palohaavan arpi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Jos mieheen tai naiseen tulee sairas paikka päähän tai partaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'ja jos pappi tarkastaessaan sairasta paikkaa huomaa, että se näyttää muuta ihoa matalammalta ja että siinä on ohuita, kellertäviä karvoja, niin julistakoon pappi hänet saastaiseksi; se on pitalisyyhelmää, se on pää-eli partapitalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Ja jos pappi tarkastaessaan sairasta paikkaa huomaa, ettei se näytä muuta ihoa matalammalta, mutta ettei siinä ole mustia karvoja, sulkekoon pappi syyhelmää sairastavan sisälle seitsemäksi päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Ja jos pappi seitsemäntenä päivänä tarkastaessaan sairasta paikkaa huomaa, ettei syyhelmä ole levinnyt ja ettei siinä ole kellertäviä karvoja ja ettei syyhelmä näytä muuta ihoa matalammalta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'niin ajakoon sairas hiuksensa tai partansa, kuitenkaan ajamatta sairasta paikkaa, ja pappi sulkekoon syyhelmää sairastavan sisälle vielä seitsemäksi päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Ja jos pappi seitsemäntenä päivänä tarkastaessaan sairasta paikkaa huomaa, ettei syyhelmä ole levinnyt ihossa ja ettei se näytä muuta ihoa matalammalta, julistakoon pappi hänet puhtaaksi; hän pesköön vaatteensa, ja niin hän on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Mutta jos syyhelmä leviää leviämistään ihossa, sen jälkeen kuin hänet julistettiin puhtaaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'ja jos pappi tarkastaessaan häntä huomaa, että syyhelmä on levinnyt ihossa, älköön pappi enää etsikö kellertäviä karvoja; hän on saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Mutta jos syyhelmä hänestä näyttää pysyneen entisellään ja jos siihen on kasvanut mustia karvoja, on syyhelmä parantunut; hän on puhdas, ja pappi julistakoon hänet puhtaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Jos miehen tai naisen ihoon tulee pilkkuja, valkoisia pilkkuja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'ja jos pappi tarkastaessaan huomaa vaalenevia, valkoisia pilkkuja heidän ihossaan, on se vaaratonta valkoista ihottumaa, joka on puhjennut ihoon; hän on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Jos hiukset lähtevät miehen päästä, takaraivosta, on hän takakalju; hän on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Ja jos hiukset lähtevät päästä, ohimoista, on hän otsakalju; hän on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Mutta jos vaaleanpunainen pilkku ilmestyy takaraivon tai otsapuolen paljaaseen paikkaan, on se pitalia, joka on puhkeamassa takaraivon tai otsapuolen paljaaseen paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Ja jos pappi tarkastaessaan häntä huomaa, että nystyrä takaraivon tai otsapuolen paljaassa paikassa on vaaleanpunainen näyttäen samanlaiselta kuin pitali muussa ihossa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'niin mies on pitalinen ja saastainen; pappi julistakoon hänet heti saastaiseksi hänen päässänsä olevan sairauden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Joka sairastaa pitalia, hän käyköön rikkirevityissä vaatteissa, tukka hajallaan ja parta peitettynä ja huutakoon: \'Saastainen, saastainen!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Niin kauan kuin sairaus hänessä on, olkoon hän saastainen; saastaisena hän asukoon yksinänsä, hänen asuinsijansa olkoon leirin ulkopuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Jos pitalitartuntaa tulee vaatekappaleeseen, olipa vaatekappale villainen tai pellavainen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'tai kudottuun tai solmustettuun kankaaseen, olipa se pellavaista tai villaista, tai nahkaan tai mihin nahasta tehtyyn esineeseen tahansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'ja jos tartunnan paikka näyttää vihertävältä tai punertavalta vaatekappaleessa tai nahassa tai kudotussa tai solmustetussa kankaassa tai missä nahasta tehdyssä esineessä tahansa, niin se on pitalia, ja se on näytettävä papille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Ja kun pappi on tarkastanut tartunnan paikan, sulkekoon hän tartutetun sisälle seitsemäksi päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Ja jos hän seitsemäntenä päivänä tarkastaessaan tartunnan paikkaa huomaa, että tarttuma on levinnyt vaatekappaleessa tai kudotussa tai solmustetussa kankaassa tai nahassa tai missä nahasta tehdyssä esineessä tahansa, on tarttuma pahanlaatuista pitalia; ne ovat saastaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Ja hän polttakoon vaatekappaleen tai kudotun tai solmustetun kankaan, olipa se villainen tai pellavainen, tai nahasta tehdyn esineen, olipa se mikä tahansa, jossa tarttuma on, sillä se on pahanlaatuista pitalia; kaikki sellainen poltettakoon tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Mutta jos pappi tarkastaessaan huomaa, ettei tarttuma ole levinnyt vaatekappaleessa tai kudotussa tai solmustetussa kankaassa tai nahasta tehdyssä esineessä, olipa se mikä tahansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'käskeköön pappi pestä esineen, jossa tarttuma on, ja sulkekoon sen sisälle vielä seitsemäksi päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Ja jos pappi tarkastaessaan tartunnan saanutta esinettä, sen jälkeen kuin se on pesty, huomaa, ettei tarttuma ole muuttunut näöltään, on esine, vaikka tarttuma ei olekaan levinnyt, saastainen, ja se poltettakoon tulessa; se on pitalin syömä, olkoon sitten nurjalta tai oikealta puolelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Mutta jos pappi tarkastaessaan huomaa, että tartunnan paikka on pesemisen jälkeen vaalennut, reväisköön hän sen pois vaatekappaleesta tai nahasta tai kudotusta tai solmustetusta kankaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Ja jos sitten vielä tarttumaa ilmestyy vaatekappaleeseen tai kudottuun tai solmustettuun kankaaseen tai mihin nahasta tehtyyn esineeseen tahansa, on se puhkeavaa pitalia; se esine, jossa tarttuma on, poltettakoon tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Mutta vaatekappale tai kudottu tai solmustettu kangas tai mikä nahasta tehty esine tahansa, josta tarttuma on pesemällä kadonnut, pestäköön vielä kerran, ja niin se on puhdas.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Tämä on laki pitalitarttumasta vaatekappaleessa, villaisessa tai pellavaisessa, tai kudotussa tai solmustetussa kankaassa tai missä nahasta tehdyssä esineessä tahansa, laki niiden puhtaiksi tai saastaisiksi julistamisesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, '\"Tämä olkoon laki pitalitautisen puhdistamispäivästä. Hänet tuotakoon papin eteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'ja pappi menköön leirin ulkopuolelle; ja jos pappi tarkastaessaan pitalista huomaa, että hän on parantunut pitalitaudista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'käskeköön pappi puhdistettavaa varten ottaa kaksi elävää, puhdasta lintua, setripuuta, helakanpunaista lankaa ja isoppikorren.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Ja pappi käskeköön teurastaa toisen linnun saviastian päällä, jossa on raikasta vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Sitten hän ottakoon sen elävän linnun ynnä setripuun, helakanpunaisen langan ja isoppikorren ja kastakoon ne ynnä elävän linnun sen linnun vereen, joka teurastettiin raikkaan veden päällä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'ja pirskoittakoon sitä seitsemän kertaa siihen, joka on pitalista puhdistettava; ja puhdistettuaan hänet hän päästäköön sen elävän linnun lentämään kedolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Ja puhdistettava pesköön vaatteensa, ajakoon kaikki hiuksensa ja peseytyköön vedessä, niin hän on puhdas. Sen jälkeen hän saa mennä leiriin; asukoon kuitenkin ulkona teltastansa seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Seitsemäntenä päivänä hän ajakoon kaikki hiukset päästänsä, partansa ja kulmakarvansa: kaikki karvat hän ajakoon; pesköön sitten vaatteensa ja pesköön ruumiinsa vedessä, niin hän on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Ja kahdeksantena päivänä hän ottakoon kaksi virheetöntä karitsaa ja virheettömän, vuoden vanhan uuhikaritsan sekä kolme kymmenennestä lestyjä jauhoja, joihin on sekoitettu öljyä, ruokauhriksi, ja yhden loog-mitan öljyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Ja puhdistusta toimittava pappi asettakoon puhdistettavan henkilön ja nämä esineet Herran eteen ilmestysmajan ovelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Sitten pappi ottakoon toisen karitsan ja tuokoon sen vikauhriksi ynnä loog-mitan öljyä, ja toimittakoon niiden heilutuksen Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Ja niin hän teurastakoon karitsan siinä paikassa, jossa syntiuhri-ja polttouhriteuraat teurastetaan, pyhässä paikassa; sillä vikauhri on, niinkuin syntiuhrikin, papin oma, se on korkeasti-pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Ja pappi ottakoon vikauhrin verta ja sivelköön sitä puhdistettavan oikeaan korvanlehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Senjälkeen pappi ottakoon öljyä loog-mitasta ja kaatakoon sitä vasempaan käteensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'ja pappi kastakoon oikean kätensä etusormen öljyyn, jota on hänen vasemmassa kädessään, ja pirskoittakoon öljyä sormellansa seitsemän kertaa Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Ja käteensä jäänyttä öljyä pappi sivelköön puhdistettavan oikeaan korvanlehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen vikauhrin veren päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Ja käteensä vielä jääneen öljyn pappi sivelköön puhdistettavan päähän; näin pappi toimittakoon hänelle sovituksen Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Sitten pappi uhratkoon syntiuhrin ja toimittakoon puhdistettavalle sovituksen hänen saastaisuudestansa, ja senjälkeen hän teurastakoon polttouhriteuraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Ja pappi uhratkoon polttouhrin ja ruokauhrin alttarilla, ja kun pappi näin on toimittanut hänelle sovituksen, on hän puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Mutta jos hän on köyhä eikä saa hankituksi niin paljoa, ottakoon vain yhden karitsan vikauhriksi, heilutettavaksi, toimittaakseen itsellensä sovituksen, sekä vain yhden kymmenenneksen lestyjä jauhoja, joihin on sekoitettu öljyä, ruokauhriksi, ja loog-mitan öljyä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'sekä kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa, mikäli hän on saanut ne hankituksi; toinen olkoon syntiuhriksi ja toinen polttouhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Ja hän vieköön ne papille puhdistustaan varten kahdeksantena päivänä, ilmestysmajan ovelle Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Ja pappi ottakoon vikauhrikaritsan ja loog-mitan öljyä, ja pappi toimittakoon niiden heilutuksen Herran edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'ja vikauhrikaritsa teurastettakoon, ja pappi ottakoon vikauhrin verta ja sivelköön sitä puhdistettavan oikeaan korvanlehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Sitten pappi kaatakoon öljyä vasempaan käteensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'ja pappi pirskoittakoon oikealla etusormellaan öljyä, jota on hänen vasemmassa kädessään, seitsemän kertaa Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Ja käteensä jäänyttä öljyä pappi sivelköön puhdistettavan oikeaan korvanlehteen sekä oikean käden peukaloon ja oikean jalan isoonvarpaaseen, siihen paikkaan, missä on vikauhrin verta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Ja käteensä vielä jääneen öljyn pappi sivelköön puhdistettavan päähän toimittaakseen hänelle sovituksen Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Ja hän uhratkoon toisen niistä metsäkyyhkysistä tai kyyhkysenpojista, jotka hän on hankkinut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'mikäli on saanut ne hankituiksi, toisen syntiuhriksi ja toisen polttouhriksi ruokauhrin ohella. Näin pappi toimittakoon puhdistettavalle sovituksen Herran edessä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Tämä on laki pitalitautia sairastavasta, joka ei saa hankituksi puhdistukseensa sitä, mikä on säädetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Ja Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, '\"Kun te tulette Kanaanin maahan, jonka minä annan teille perintömaaksi, ja minä sallin pitalin tarttua johonkin taloon siinä maassa, jonka te saatte perintömaaksenne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'niin talon omistaja menköön ja ilmoittakoon sen papille sanoen: \'Minun talooni näyttää ilmestyneen jotakin pitalitarttuman tapaista\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Ja pappi käskeköön tyhjentää talon, ennenkuin menee tarkastamaan tarttumaa, ettei kaikki, mitä talossa on, tulisi saastaiseksi; sitten pappi menköön tarkastamaan taloa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Ja jos hän tarkastaessaan tarttumaa näkee tartunnan paikassa talon seinissä vihertäviä tai punertavia syvennyksiä, jotka näyttävät muuta seinää matalammilta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'menköön pappi talosta ulos talon ovelle ja sulkekoon talon seitsemäksi päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Ja jos pappi palattuaan seitsemäntenä päivänä tarkastaessaan huomaa tarttuman levinneen talon seinissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'käskeköön hän murtaa pois ne kivet, joissa tarttuma on, ja heittää ne ulos kaupungista saastaiseen paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Ja talo kaavittakoon sisältä ympärinsä puhtaaksi, ja kaavittu savi heitettäköön ulos kaupungista saastaiseen paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Ja otettakoon toisia kiviä ja pantakoon entisten kivien sijaan, ja otettakoon toista savea ja savettakoon talo sillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Jos tarttuma taas ilmestyy taloon, sen jälkeen kuin kivet ovat murretut pois ja talo on puhtaaksi kaavittu ja uudestaan savettu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'menköön pappi sisälle, ja jos hän tarkastaessaan huomaa tarttuman levinneen talossa, niin on talossa pahanlaatuinen pitali; se on saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Sentähden se talo revittäköön, sekä sen kivet että puuaineet ja kaikki sen savi, ja vietäköön ne ulos kaupungista saastaiseen paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Ja se, joka on käynyt talossa sinä aikana, jona sen oli oltava suljettuna, olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Ja se, joka siinä talossa on maannut, pesköön vaatteensa, ja se, joka siinä talossa on syönyt, pesköön vaatteensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Mutta jos pappi menee sisälle ja tarkastaessaan huomaa, ettei tarttuma ole levinnyt talossa, sen jälkeen kuin talo on savettu, niin julistakoon pappi talon puhtaaksi, sillä tarttuma on hävinnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Ja hän ottakoon talon puhdistamiseksi kaksi lintua, setripuuta, helakanpunaista lankaa ja isoppikorren.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Ja teurastakoon toisen linnun saviastian päällä, jossa on raikasta vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Ja ottakoon setripuun, isoppikorren ja helakanpunaisen langan ja elävän linnun, kastakoon ne teurastetun linnun vereen ja raikkaaseen veteen ja pirskoittakoon sitä taloon seitsemän kertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Näin hän puhdistakoon talon linnun verellä ja raikkaalla vedellä, elävällä linnulla, setripuulla, isoppikorrella ja helakanpunaisella langalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Ja sitten hän päästäköön elävän linnun lentämään ulkopuolelle kaupunkia kedolle. Kun hän näin on toimittanut talolle sovituksen, on se puhdas.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Tämä on laki kaikkinaisesta pitalitaudista ja syyhelmästä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'pitalista vaatteissa ja taloissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'nystyröistä, ihottumista ja vaaleista pilkuista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'neuvoksi siitä, milloin mikin on saastainen, milloin puhdas. Tämä on laki pitalista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Ja Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, '\"Puhukaa israelilaisille ja sanokaa heille: Jos jollakin, kenellä tahansa, on elimestään liman vuoto, on hänen vuotonsa saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Hänen vuotonsa saastaisuus on sellainen, että hän, niin hyvin silloin, kun hänen elimestään vuotaa, kuin silloin, kun hänen elimensä pidättää vuodon, on saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Jokainen vuode, jossa vuotoa sairastava lepää, tulee saastaiseksi, ja jokainen istuin, jolla hän istuu, tulee saastaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Ja se, joka koskee hänen vuoteeseensa, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Ja se, joka istuu istuimelle, jolla vuotoa sairastava on istunut, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Ja se, joka koskee vuotoa sairastavan ruumiiseen, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Ja jos vuotoa sairastava sylkee puhtaan ihmisen päälle, niin tämä pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Ja jokainen satula, jossa vuotoa sairastava ratsastaa, tulee saastaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Ja jokainen, joka koskee mihin hyvänsä, mikä on ollut hänen allaan, olkoon saastainen iltaan asti; ja joka sellaista kantaa, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Ja jokainen, johon vuotoa sairastava koskee, ennenkuin on huuhtonut kätensä vedessä, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Ja saviastia, johon vuotoa sairastava koskee, rikottakoon; mutta jokainen puuastia huuhdottakoon vedessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Ja kun vuotoa sairastava tulee puhtaaksi vuodostansa, niin hän laskekoon puhtaaksi-tulemisestaan seitsemän päivää ja sitten pesköön vaatteensa ja pesköön ruumiinsa raikkaassa vedessä, niin hän on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Ja kahdeksantena päivänä hän ottakoon kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa ja tulkoon Herran eteen ilmestysmajan ovelle ja antakoon ne papille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Ja pappi uhratkoon ne, toisen syntiuhriksi ja toisen polttouhriksi. Näin pappi toimittakoon Herran edessä hänelle sovituksen hänen vuodostansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Kun miehellä on ollut siemenvuoto, pesköön hän koko ruumiinsa vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Ja jokainen vaatekappale ja jokainen nahka, johon siemenvuotoa on tullut, pestäköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Ja kun mies on maannut naisen kanssa ja vuodattanut siemenensä, peseytykööt he vedessä ja olkoot saastaiset iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Ja kun naisella on vuoto, niin että verta vuotaa hänen ruumiistansa, olkoon hän kuukautistilassaan seitsemän päivää, ja jokainen, joka häneen koskee, olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Ja kaikki, minkä päällä hän lepää kuukautistilansa aikana, tulee saastaiseksi, ja kaikki, minkä päällä hän istuu, tulee saastaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Ja jokainen, joka hänen vuoteeseensa koskee, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Ja jokainen, joka koskee istuimeen, mihin hyvänsä, jolla hän on istunut, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Ja jos joku koskee esineeseen, joka on hänen vuoteellaan tai istuimella, jolla hän on istunut, olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Ja jos mies makaa hänen kanssaan ja hänen kuukautistansa tulee hänen päällensä, olkoon hän saastainen seitsemän päivää, ja jokainen vuode, jossa hän lepää, tulee saastaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Jos naisen verenvuoto kestää kauan aikaa, vaikka ei ole hänen kuukautisaikansa, tahi jos se jatkuu hänen kuukautisaikansa ohitse, pidettäköön hänet koko vuotonsa ajan saastaisena, niinkuin hänen kuukautisaikanaankin; hän on saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Jokaisesta vuoteesta, jossa hän lepää vuotonsa aikana, olkoon voimassa, mitä on säädetty hänen kuukautisaikana käyttämästään vuoteesta; ja jokainen istuin, jolla hän istuu, tulee saastaiseksi niinkuin hänen kuukautisaikanaankin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Ja jokainen, joka niihin koskee, tulee saastaiseksi; hän pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Mutta kun hän tulee puhtaaksi vuodostansa, laskekoon seitsemän päivää, ja sitten hän on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Ja kahdeksantena päivänä hän ottakoon kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa ja tuokoon ne papille, ilmestysmajan ovelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Ja pappi uhratkoon toisen syntiuhriksi ja toisen polttouhriksi. Näin pappi toimittakoon Herran edessä hänelle sovituksen hänen saastaisesta vuodostaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Näin teidän on varoitettava israelilaisia saastaisuudesta, etteivät he saastaisuudessansa kuolisi, jos saastuttavat minun asumukseni, joka on heidän keskellänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Tämä on laki miehestä, joka sairastaa vuotoa, ja miehestä, jolla on siemenvuoto ja joka tulee siitä saastaiseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'ja naisesta, jolla on kuukautisensa, ja miehestä ja naisesta, jotka sairastavat jotakin vuotoa, sekä miehestä, joka makaa saastaisen naisen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Ja Herra puhui Moosekselle, sen jälkeen kuin kaksi Aaronin poikaa oli kuollut, joita kuolema kohtasi, kun he astuivat Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Ja Herra sanoi Moosekselle: \"Sano veljellesi Aaronille: älköön hän joka aika menkö pyhimpään, esiripun sisäpuolelle, armoistuimen eteen, joka on arkin päällä, ettei hän kuolisi; sillä minä ilmestyn pilvessä armoistuimen kohdalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Mutta näin Aaron menköön pyhimpään: hänellä olkoon mukanaan mullikka syntiuhriksi ja oinas polttouhriksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'ja hän pukekoon pyhän pellava-ihokkaan yllensä, peittäköön häpynsä pellavakaatioilla, vyöttäköön itsensä pellavavyöllä ja pankoon pellavaisen käärelakin päähänsä. Nämä ovat pyhät vaatteet; ja hän pesköön ruumiinsa vedessä ja pukekoon ne yllensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Ja hän ottakoon israelilaisten seurakunnalta kaksi kaurista syntiuhriksi ja yhden oinaan polttouhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Ja Aaron tuokoon oman syntiuhrimullikkansa ja toimittakoon sovituksen itsellensä ja perheellensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Sitten hän ottakoon ne kaksi kaurista ja asettakoon ne Herran eteen ilmestysmajan ovelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Ja Aaron heittäköön arpaa niistä kahdesta kauriista: toisen arvan Herralle ja toisen Asaselille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Ja Aaron tuokoon sen kauriin, jonka arpa määräsi Herralle, ja uhratkoon sen syntiuhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Mutta se kauris, jonka arpa määräsi Asaselille, asetettakoon elävänä Herran eteen, että sille toimitettaisiin sovitus ja se sitten päästettäisiin erämaahan Asaselille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Senjälkeen Aaron tuokoon oman syntiuhrimullikkansa ja toimittakoon sovituksen itsellensä ja perheellensä ja teurastakoon oman syntiuhrimullikkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Ja hän ottakoon hiilipannun täyteen tulisia hiiliä alttarilta, joka on Herran edessä, ja kahmalonsa täyteen survottua hyvänhajuista suitsuketta ja vieköön ne esiripun sisäpuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Ja hän pankoon suitsukkeen tulen päälle Herran eteen, niin että suitsutus pilvenä peittää lain arkin päällä olevan armoistuimen, ettei hän kuolisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Ja hän ottakoon mullikan verta ja pirskoittakoon sitä sormellansa armoistuimen etupuolelle; ja armoistuimen eteen hän pirskoittakoon sormellansa verta seitsemän kertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Sitten hän teurastakoon kansan syntiuhrikauriin ja vieköön sen verta esiripun sisäpuolelle ja tehköön sen verellä, niinkuin hän teki mullikan verellä: pirskoittakoon sitä armoistuimelle ja armoistuimen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Ja näin hän toimittakoon pyhäkölle sovituksen israelilaisten saastaisuudesta ja heidän rikoksistaan, olivatpa heidän syntinsä minkälaiset tahansa; näin hän tehköön myös ilmestysmajalle, joka on heidän tykönänsä, keskellä heidän saastaisuuttansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Älköön yhtään ihmistä olko ilmestysmajassa, kun hän tulee toimittamaan sovitusta pyhimmässä, siihen saakka kunnes hän sieltä lähtee ja on toimittanut itsellensä ja perheellensä ja koko Israelin seurakunnalle sovituksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Sitten hän lähteköön sieltä alttarin ääreen, joka on Herran edessä, ja toimittakoon sille sovituksen; ja hän ottakoon mullikan verta ja kauriin verta ja sivelköön sitä alttarin sarviin yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Ja hän pirskoittakoon sormellansa sen päälle verta seitsemän kertaa ja puhdistakoon ja pyhittäköön sen israelilaisten saastaisuudesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Ja kun hän on loppuun toimittanut pyhäkön ja ilmestysmajan ja alttarin sovittamisen, tuokoon hän sen elävän kauriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Ja Aaron laskekoon molemmat kätensä elävän kauriin pään päälle ja tunnustakoon siinä kaikki israelilaisten pahat teot ja kaikki heidän rikkomuksensa, olipa heillä mitä syntejä tahansa, ja pankoon ne kauriin pään päälle ja lähettäköön sen, sitä varten varatun miehen viemänä, erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Näin kauris kantakoon kaikki heidän pahat tekonsa autioon seutuun; ja kauris päästettäköön erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Ja Aaron menköön ilmestysmajaan ja riisukoon yltänsä pellavavaatteet, jotka hän oli pukenut päälleen mennessänsä pyhäkköön, ja jättäköön ne sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Ja hän pesköön pyhässä paikassa ruumiinsa vedessä ja pukekoon ylleen omat vaatteensa; sitten hän lähteköön sieltä ja uhratkoon sekä oman polttouhrinsa että kansan polttouhrin ja toimittakoon niin sekä itsellensä että kansalle sovituksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Ja syntiuhrin rasvan hän polttakoon alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Ja se, joka päästi kauriin Asaselille, pesköön vaatteensa ja pesköön ruumiinsa vedessä, ja sitten hän tulkoon leiriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Ja syntiuhrimullikka ja syntiuhrikauris, joiden veri tuotiin sovitukseksi pyhäkköön, vietäköön leirin ulkopuolelle, ja niiden nahka, liha ja rapa poltettakoon tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Ja se, joka ne polttaa, pesköön vaatteensa ja pesköön ruumiinsa vedessä, ja sitten hän tulkoon leiriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Tämä olkoon teille ikuinen säädös: seitsemännessä kuussa, kuukauden kymmenentenä päivänä, kurittakaa itseänne paastolla älkääkä yhtäkään askaretta toimittako, älköön maassa syntynyt älköönkä muukalainen, joka asuu teidän keskellänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Sillä sinä päivänä toimitetaan teille sovitus teidän puhdistamiseksenne; kaikista synneistänne te tulette puhtaiksi Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Se olkoon teille levon päivä, kurittakaa silloin itseänne paastolla; se olkoon ikuinen säädös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Ja sovituksen toimittakoon se pappi, joka on voideltu ja joka on vihitty papinvirkaan isänsä sijaan; hän pukekoon yllensä pellavavaatteet, pyhät vaatteet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'ja toimittakoon sovituksen kaikkeinpyhimmälle ja sovituksen ilmestysmajalle ja alttarille sekä sovituksen myös papeille ja kaikelle seurakunnan kansalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Tämä olkoon teille ikuinen säädös, että toimitatte israelilaisille sovituksen kaikista heidän synneistänsä kerran vuodessa.\" Ja hän teki, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, '\"Puhu Aaronille ja hänen pojillensa ja kaikille israelilaisille ja sano heille: Näin on Herra käskenyt sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Kuka ikinä Israelin heimosta teurastaa härän tai karitsan tai vuohen leirissä tai leirin ulkopuolella');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'eikä tuo sitä ilmestysmajan ovelle antaaksensa sen uhrilahjana Herralle Herran asumuksen edessä, hänet pidettäköön vereen vikapäänä; hän on vuodattanut verta, ja se mies hävitettäköön kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Sentähden israelilaiset tuokoot uhriteuraansa, jotka he ovat teurastaneet kedolla, Herran eteen ilmestysmajan ovelle, papille, ja siellä uhratkoot ne yhteysuhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Ja pappi vihmokoon veren Herran alttarille ilmestysmajan oven edessä ja polttakoon rasvan suloiseksi tuoksuksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Ja älkööt he enää uhratko uhrejansa metsänpeikoille, joiden jäljessä he haureudessa kulkevat. Tämä olkoon heille ikuinen säädös sukupolvesta sukupolveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Ja sano heille: Kuka ikinä Israelin heimosta tai muukalaisista, jotka asuvat teidän keskellänne, uhraa polttouhrin tai teurasuhrin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'eikä tuo sitä ilmestysmajan ovelle, Herralle uhrattavaksi, se mies hävitettäköön kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Kuka ikinä Israelin heimosta tai muukalaisista, jotka asuvat teidän keskellänne, syö verta, mitä tahansa, sitä ihmistä vastaan, joka verta syö, minä käännän kasvoni ja hävitän hänet kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Sillä lihan sielu on veressä, ja minä olen sen teille antanut alttarille, että se tuottaisi teille sovituksen; sillä veri tuottaa sovituksen, koska sielu on siinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Sentähden minä olen sanonut israelilaisille: Älköön kukaan teistä syökö verta; älköön myöskään muukalainen, joka asuu teidän keskellänne, syökö verta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Ja kuka ikinä Israelin heimosta tai muukalaisista, jotka asuvat teidän keskellänne, saa pyydystetyksi syötävän metsäeläimen tai linnun, hän vuodattakoon sen veren maahan ja peittäköön multaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Sillä kaiken lihan sielu on sen veri, jossa sen sielu on; sentähden minä sanon israelilaisille: Älkää syökö minkään lihan verta. Sillä kaiken lihan sielu on sen veri; jokainen, joka sitä syö, hävitettäköön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Ja jokainen, olipa hän maassa syntynyt tai muukalainen, joka syö itsestään kuollutta tai kuoliaaksi raadeltua eläintä, pesköön vaatteensa ja peseytyköön vedessä ja olkoon saastainen iltaan asti; niin hän tulee puhtaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Mutta jos hän ei pese vaatteitansa eikä pese ruumistansa, joutuu hän syynalaiseksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, '\"Puhu israelilaisille ja sano heille: Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Älkää tehkö, niinkuin tehdään Egyptin maassa, jossa te asuitte, älkääkä tehkö, niinkuin tehdään Kanaanin maassa, johon minä teidät vien; älkää vaeltako heidän tapojensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Vaan seuratkaa minun säädöksiäni ja noudattakaa minun käskyjäni vaeltaaksenne niiden mukaan. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Noudattakaa minun käskyjäni ja säädöksiäni, sillä se ihminen, joka ne pitää, on niistä elävä. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Älköön kukaan teistä ryhtykö veriheimolaiseensa paljastaakseen hänen häpyänsä. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Isäsi häpyä ja äitisi häpyä älä paljasta. Hän on sinun äitisi, älä hänen häpyänsä paljasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Älä paljasta äitipuolesi häpyä, se on sinun isäsi häpy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Älä paljasta sisaresi häpyä, olipa hän isäsi tytär tai äitisi tytär, kotona tai ulkona syntynyt; älä paljasta heidän häpyänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Älä paljasta poikasi tyttären tai tyttäresi tyttären häpyä, sillä se on sinun oma häpysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Älä paljasta äitipuolesi tyttären häpyä, tyttären, joka on sinun isällesi syntynyt; hän on sinun sisaresi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Älä paljasta isäsi sisaren häpyä; hän on sinun isäsi veriheimolainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Älä paljasta äitisi sisaren häpyä, sillä hän on sinun äitisi veriheimolainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Älä paljasta setäsi häpyä, älä ryhdy hänen vaimoonsa; hän on sinun tätisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Älä paljasta miniäsi häpyä; hän on sinun poikasi vaimo, älä paljasta hänen häpyänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Älä paljasta veljesi vaimon häpyä; se on sinun veljesi häpy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Älä paljasta vaimon ja hänen tyttärensä häpyä, äläkä ota vaimoksi hänen poikansa tytärtä tai tyttärensä tytärtä paljastaaksesi hänen häpyänsä, sillä he ovat veriheimolaisia; se on sukurutsausta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Älä ota vaimosi eläessä hänen sisartansa vaimoksesi ja paljasta hänen häpyänsä, sillä se tuo riidan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Älä ryhdy vaimoon paljastaaksesi hänen häpyänsä, kun hän on saastainen kuukautisaikanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Älä makaa lähimmäisesi vaimon kanssa, ettet siten itseäsi saastuttaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Älä anna lapsiasi poltettaviksi uhrina Molokille, ettet häpäisisi Jumalasi nimeä. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Älä makaa miehenpuolen kanssa, niinkuin naisen kanssa maataan; se on kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Älä sekaannu mihinkään eläimeen, ettet siten itseäsi saastuttaisi. Älköönkä nainen tarjoutuko eläimelle pariutuaksensa sen kanssa; se on iljettävyys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Älkää saastuttako itseänne millään näistä, sillä näillä kaikilla ovat itsensä saastuttaneet ne kansat, jotka minä karkoitan teidän tieltänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Ja maa tuli saastaiseksi, ja minä kostin sille sen pahat teot, niin että maa oksensi ulos asujamensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Sentähden noudattakaa minun käskyjäni ja säädöksiäni älkääkä mitään näistä kauhistuksista tehkö, älköön maassa syntynyt älköönkä muukalainen, joka asuu teidän keskellänne-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'sillä kaikkia näitä kauhistuksia ovat tehneet tämän maan asukkaat, jotka olivat ennen teitä, niin että maa tuli saastaiseksi-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'ettei maa teitäkin oksentaisi, jos te sen saastutatte, niinkuin se on oksentanut ulos sen kansan, joka oli ennen teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Sillä jokainen, joka tekee minkä tahansa näistä kauhistuksista, hävitettäköön kansastansa, kaikki, jotka semmoista tekevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Sentähden noudattakaa minun määräyksiäni, ettette seuraisi niitä kauhistavia tapoja, joita on seurattu ennen teitä, ettekä saastuttaisi itseänne niillä. Minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, '\"Puhu kaikelle israelilaisten seurakunnalle ja sano heille: Olkaa pyhät, sillä minä, Herra, teidän Jumalanne, olen pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Jokainen teistä peljätköön äitiänsä ja isäänsä, ja pitäkää minun sapattini. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Älkää kääntykö epäjumalien puoleen älkääkä tehkö itsellenne valettuja jumalankuvia. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Ja kun te uhraatte yhteysuhria Herralle, uhratkaa se niin, että hänen mielisuosionsa tulee teidän osaksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Syökää se samana päivänä, jona te uhraatte, tai seuraavana päivänä; mutta mitä tähteeksi jää kolmanteen päivään, se poltettakoon tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Jos sitä syödään kolmantena päivänä, niin se on saastaista, ei otollista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Ja joka sitä syö, joutuu syynalaiseksi, sillä hän on häväissyt Herran pyhän, ja hänet hävitettäköön kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Kun te korjaatte eloa maastanne, niin älä leikkaa viljaa pelloltasi reunoja myöten äläkä poimi tähkäpäitä leikkuun jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Älä myöskään korjaa tyhjäksi viinitarhaasi äläkä poimi varisseita marjoja, vaan jätä ne köyhälle ja muukalaiselle. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Älkää varastako, älkää valhetelko älkääkä lähimmäistänne pettäkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Älkää vannoko väärin minun nimeeni, ettet häpäisisi Jumalasi nimeä. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Älä tee lähimmäisellesi vääryyttä äläkä ota mitään väkisin. Päivämiehesi palkka älköön olko sinun takanasi huomiseen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Älä kiroa kuuroa äläkä pane kompastusta sokean eteen, vaan pelkää Jumalaasi. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Älkää tehkö vääryyttä tuomitessanne; älä ole puolueellinen köyhän hyväksi äläkä pidä ylhäisen puolta, vaan tuomitse lähimmäisesi oikein.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Älä liiku panettelijana kansasi keskellä äläkä vaani lähimmäisesi verta. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Älä vihaa veljeäsi sydämessäsi, vaan nuhtele lähimmäistäsi, ettet joutuisi hänen tähtensä syynalaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Älä kosta äläkä pidä vihaa kansasi lapsia vastaan, vaan rakasta lähimmäistäsi niinkuin itseäsi. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Noudattakaa minun käskyjäni. Älä anna karjassasi kahden erilaisen eläimen pariutua, älä kylvä peltoosi kahdenlaista siementä, älköönkä kahdenlaisista langoista kudottua vaatetta tulko yllesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Jos mies makaa naisen, joka on orjatar ja toisen miehen oma eikä ole lunastettu eikä vapaaksi laskettu, rangaistakoon heitä, ei kuitenkaan kuolemalla, koska nainen ei ollut vapaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Ja mies tuokoon hyvityksenään Herralle vikauhri-oinaan ilmestysmajan ovelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Ja kun pappi on toimittanut hänelle vikauhri-oinaalla Herran edessä sovituksen siitä synnistä, jonka hän on tehnyt, annetaan hänelle hänen tekemänsä synti anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Kun te tulette siihen maahan ja istutatte kaikkinaisia hedelmäpuita, niin jättäkää niiden hedelmä, niiden esinahka, koskemattomaksi; kolmena vuotena pitäkää ne ympärileikkaamattomina, älkää niitä syökö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Mutta neljäntenä vuotena pyhitettäköön kaikki niiden hedelmät ilojuhlassa Herralle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'ja vasta viidentenä vuotena syökää niiden hedelmää; näin te lisäätte niiden tuottoa. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Älkää syökö mitään verinensä. Älkää merkeistä ennustelko älkääkä harjoittako noituutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Älkää keritkö tukkaanne päälaen ympäriltä, äläkä leikkaamalla turmele partasi reunaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Älkää viileskelkö ihoanne vainajan tähden älkääkä koristelko itseänne ihopiirroksilla. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Älä häpäise tytärtäsi antamalla hänen tulla portoksi, ettei maa harjoittaisi haureutta ja tulisi täyteen iljettävyyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Pitäkää minun sapattini ja peljätkää minun pyhäkköäni. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Älkää kääntykö vainaja-ja tietäjähenkien puoleen; älkää etsikö heitä, ettette tulisi heistä saastutetuiksi. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Nouse harmaapään edessä ja kunnioita vanhusta sekä pelkää Jumalaasi. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Kun muukalainen asuu luonasi teidän maassanne, älkää sortako häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Muukalainen, joka asuu teidän luonanne, olkoon niinkuin maassa syntynyt teikäläinen. Rakasta häntä niinkuin itseäsi, sillä tekin olitte muukalaisina Egyptin maassa. Minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Älkää tehkö vääryyttä tuomitessanne älkääkä käyttäessänne pituus-,paino-tai astiamittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Olkoon teillä oikea vaaka, oikeat punnukset, oikea eefa-mitta ja oikea hiin-mitta. Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Noudattakaa kaikkia minun käskyjäni ja kaikkia minun säädöksiäni ja pitäkää ne. Minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, '\"Sano israelilaisille: Jos joku, kuka tahansa israelilainen tai muukalainen, joka asuu Israelissa, antaa lapsiansa Molokille, hänet rangaistakoon kuolemalla; maan kansa kivittäköön hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Ja minä käännän kasvoni sitä miestä vastaan ja hävitän hänet hänen kansastansa, koska hän on antanut Molokille lapsiansa saastuttaen minun pyhäkköni ja häväisten minun pyhän nimeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Ja jos maan kansa säästää sitä miestä, joka antaa lapsiansa Molokille, niin etteivät he häntä surmaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'niin minä itse käännän kasvoni sitä miestä vastaan ja hänen sukuansa vastaan; hänet ja kaikki, jotka häntä seuraten ovat lähteneet haureudessa kulkemaan Molokin jäljessä, minä hävitän heidän kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Ja jos joku kääntyy vainaja-tai tietäjähenkien puoleen, lähtien haureudessa kulkemaan heidän jäljessänsä, sitä ihmistä vastaan minä käännän kasvoni ja hävitän hänet hänen kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Pyhittäkää siis itsenne ja olkaa pyhät; sillä minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Ja noudattakaa minun käskyjäni ja pitäkää ne. Minä olen Herra, joka pyhitän teidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Kuka ikinä kiroaa isäänsä tai äitiänsä, hänet rangaistakoon kuolemalla; isäänsä ja äitiänsä hän on kironnut, hän on verivelan alainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Jos joku tekee aviorikoksen toisen miehen vaimon kanssa, jos hän tekee aviorikoksen lähimmäisensä vaimon kanssa, niin heidät, sekä avionrikkoja mies että-nainen, rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Jos joku makaa äitipuolensa kanssa, paljastaa hän isänsä hävyn; heidät molemmat rangaistakoon kuolemalla, he ovat verivelan alaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Jos joku makaa miniänsä kanssa, rangaistakoon heidät molemmat kuolemalla; he ovat tehneet iljettävyyden, he ovat verivelan alaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Jos joku makaa miehenpuolen kanssa, niinkuin naisen kanssa maataan, tekevät he molemmat kauhistuksen; heidät rangaistakoon kuolemalla, he ovat verivelan alaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Jos joku ottaa vaimoksi naisen ja hänen äitinsä, on se iljettävyys; sekä hänet että ne molemmat poltettakoon tulessa, ettei mitään iljettävyyttä olisi teidän seassanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Jos joku sekaantuu eläimeen, rangaistakoon hänet kuolemalla, ja se eläin tappakaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Ja jos nainen ryhtyy eläimeen, mihin tahansa, pariutuaksensa sen kanssa, niin surmaa sekä nainen että eläin; heidät rangaistakoon kuolemalla, he ovat verivelan alaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Jos joku ottaa vaimoksi sisarensa, isänsä tyttären tai äitinsä tyttären, ja näkee hänen häpynsä ja tämä näkee hänen häpynsä, niin se on häpeä, ja heidät hävitettäköön kansalaistensa silmien edessä; hän on paljastanut sisarensa hävyn, hän on joutunut syynalaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Jos joku makaa kuukautistilassa olevan naisen kanssa ja paljastaa hänen häpynsä, avaa hänen lähteensä, ja nainen paljastaa verensä lähteen, niin heidät molemmat hävitettäköön kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Älä paljasta äitisi sisaren tai isäsi sisaren häpyä; sillä se, joka niin tekee, on paljastanut veriheimolaisensa; he joutuvat syynalaisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Jos joku makaa setänsä vaimon kanssa, on hän paljastanut setänsä hävyn; he joutuvat syynalaisiksi, lapsettomina he kuolkoot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Jos joku ottaa vaimoksi veljensä vaimon, on se saastaisuus; hän on paljastanut veljensä hävyn, lapsettomiksi he jääkööt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Noudattakaa siis kaikkia minun käskyjäni ja kaikkia minun säädöksiäni ja pitäkää ne, ettei teitä oksentaisi ulos se maa, johon minä vien teidät asumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Ja älkää vaeltako sen kansan tapojen mukaan, jonka minä karkoitan teidän tieltänne; sillä kaikkia näitä he ovat tehneet ja nostaneet minun inhoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Mutta minä sanon teille: Te saatte ottaa omaksenne heidän maansa, sillä minä annan sen teille omaksi, maan, joka vuotaa maitoa ja mettä. Minä olen Herra, teidän Jumalanne, joka olen teidät erottanut muista kansoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Erottakaa myös puhtaat eläimet saastaisista ja saastaiset linnut puhtaista, ettette saattaisi itseänne inhottaviksi koskemalla nelijalkaisiin eläimiin, lintuihin tai maan matelijoihin, mihin tahansa, jotka minä olen erottanut, että te pitäisitte ne saastaisina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Olkaa siis minulle pyhät, sillä minä, Herra, olen pyhä, ja minä olen teidät erottanut muista kansoista olemaan minun omani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Jos jossakin miehessä tai naisessa on vainaja-tai tietäjähenki, niin heidät rangaistakoon kuolemalla; heidät kivitettäköön, he ovat verivelan alaiset.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Ja Herra sanoi Moosekselle: \"Puhu papeille, Aaronin pojille, ja sano heille: Pappi älköön saattako itseänsä saastaiseksi kenestäkään kuolleesta sukulaisestansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'paitsi lähimmästä veriheimolaisestaan: äidistänsä, isästänsä, pojastansa, tyttärestänsä ja veljestänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'sekä sisarestansa, jos tämä oli neitsyt ja eli hänen luonaan eikä ollut naitu; hänestä hän saa saastua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Älköön hän, sukunsa päämies, saattako itseänsä saastaiseksi, ettei hän itseänsä häpäisisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Älkööt he ajako paljaaksi päälakeansa älköötkä leikatko partansa reunaa älköötkä koristelko itseänsä ihopiirroksilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'He olkoot Jumalallensa pyhät älköötkä häväiskö Jumalansa nimeä, sillä he uhraavat Herran uhreja, Jumalansa leipää; sentähden he olkoot pyhät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Älkööt he ottako vaimoksi porttoa tai häväistyä naista älköötkä ottako miehensä hylkäämää vaimoa, sillä pappi on pyhä Jumalallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Sinun on pidettävä häntä pyhänä, koska hän uhraa sinun Jumalasi leipää; hän olkoon sinulle pyhä, sillä minä, Herra, joka pyhitän teidät, olen pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Jos papin tytär häpäisee itsensä haureudella, niin hän häpäisee isänsä; hänet poltettakoon tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Se pappi, joka on ylimmäinen veljiensä seassa, jonka pään päälle voiteluöljy on vuodatettu ja joka pyhiin vaatteisiin pukemalla on vihitty virkaansa, älköön päästäkö tukkaansa hajalle älköönkä reväiskö vaatteitansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Älköön hän myöskään menkö minkään kuolleen luo; isästänsäkään tai äidistänsä hän älköön saattako itseänsä saastaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Älköön hän lähtekö pyhäköstä, ettei hän häpäisisi Jumalansa pyhäkköä, sillä hänessä on hänen Jumalansa voiteluöljyn vihkimys. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Hän ottakoon vaimoksensa neitsyen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Leskeä tai hyljättyä vaimoa tai häväistyä naista tai porttoa hän älköön ottako, vaan neitsyen omasta suvustaan hän ottakoon vaimoksensa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'ettei hän häpäisisi jälkeläisiään suvussansa; sillä minä olen Herra, joka hänet pyhitän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, '\"Puhu Aaronille ja sano: jos jossakin sinun jälkeläisistäsi, tulevissa sukupolvissa, on joku vamma, älköön hän lähestykö uhraamaan Jumalansa leipää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Älköön lähestykö kukaan, jossa on joku vamma, älköön kukaan sokea tai ontuva, kukaan kasvoiltaan tahi jäseniltään muodoton,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'jalkansa tai kätensä taittanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'kyttyräselkäinen tai surkastunut, silmävikainen tai ihotautinen tai rupinen tai kuohittu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Pappi Aaronin jälkeläisistä älköön kukaan, jossa on joku vamma, lähestykö uhraamaan Herran uhreja; hänessä on vamma, sentähden hän älköön lähestykö uhraamaan Jumalansa leipää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Kuitenkin hän syököön Jumalansa leipää, sekä korkeasti-pyhää että pyhää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Mutta älköön hän tulko esiripun luo älköönkä lähestykö alttaria, koska hänessä on vamma, ettei hän häpäisisi minun pyhäkköäni; sillä minä olen Herra, joka pyhitän heidät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Ja Mooses sanoi tämän Aaronille ja hänen pojillensa ja kaikille israelilaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, '\"Käske Aaronia ja hänen poikiansa pyhästi pitelemään israelilaisten pyhiä lahjoja, heidän minulle pyhittämiänsä, etteivät he häpäisisi minun pyhää nimeäni. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Sano heille polvesta polveen: Jos kuka tahansa teidän jälkeläisistänne saastuneena ollessaan lähestyy niitä pyhiä lahjoja, joita israelilaiset pyhittävät Herralle, hänet hävitettäköön minun kasvojeni edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Minä olen Herra. Älköön kukaan Aaronin jälkeläinen, joka on pitalinen tai jolla on vuoto, syökö pyhistä lahjoista, ennenkuin hän on tullut puhtaaksi; ja joka koskee johonkin kuolleesta saastuneeseen tahi jolla on siemenvuoto,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'tahi joka koskee pikkueläimeen, mihin tahansa, josta saastuu, tai ihmiseen, josta saastuu, olipa sen saastaisuus mitä laatua tahansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'niin jokainen, joka koskee johonkin sellaiseen, olkoon saastainen iltaan asti älköönkä syökö pyhistä lahjoista, ellei hän ole pessyt ruumistaan vedessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Mutta kun aurinko on laskenut, on hän puhdas, ja sitten hän syököön pyhistä lahjoista, sillä se on hänen ruokansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Itsestään kuollutta tai kuoliaaksi raadeltua eläintä hän älköön syökö, ettei hän siten saastuisi. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'He noudattakoot minun määräyksiäni, etteivät joutuisi syynalaisiksi pyhitetyn tähden ja kuolisi, sentähden että häpäisevät pyhitetyn. Minä olen Herra, joka pyhitän heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Yksikään syrjäinen älköön syökö pyhästä lahjasta; papin loinen tai päiväpalkkalainen älköön syökö pyhästä lahjasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Mutta kun pappi ostaa rahallansa orjan, saakoon tämä siitä syödä; samoin hänen kodissaan syntyneet orjat syökööt hänen ruokaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Jos papin tytär tulee syrjäisen miehen vaimoksi, älköön hän syökö pyhistä antilahjoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Mutta jos papin tytär tulee leskeksi tai hyljätyksi ja on lapseton ja hän tulee takaisin isänsä taloon ja asuu siellä niinkuin nuoruudessaan, niin hän syököön isänsä ruokaa; mutta kukaan syrjäinen älköön sitä syökö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Ja jos joku erehdyksessä syö pyhästä lahjasta, korvatkoon papille pyhän lahjan ja pankoon siihen vielä lisäksi viidennen osan sen arvosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Älkööt papit häväiskö israelilaisten pyhiä lahjoja, joita nämä antavat Herralle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Älköötkä saattako heitä syynalaisiksi ja vikapäiksi sallimalla heidän syödä pyhiä lahjojansa; sillä minä olen Herra, joka pyhitän heidät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, '\"Puhu Aaronille ja hänen pojillensa ja kaikille israelilaisille ja sano heille: Kuka ikinä Israelin heimosta tai muukalaisista Israelissa tuo polttouhriksi uhrilahjansa, olipa se mikä hyvänsä lupausuhri tai vapaaehtoinen uhri, jonka he tuovat Herralle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'niin tuokaa sellainen uhri, että hänen mielisuosionsa tulee teidän osaksenne: virheetön urospuoli raavaista, lampaista tai vuohista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Mutta yhtään eläintä, jossa on vamma, älkää tuoko, sillä siitä hänen mielisuosionsa ei tule teidän osaksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Jos joku tuo Herralle yhteysuhrin raavaista tai lampaista, joko lupausta täyttääkseen tai vapaaehtoisena uhrina, olkoon eläin virheetön ollakseen otollinen; älköön siinä olko mitään vammaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Sokeata tai raajarikkoa tai silvottua tai paiseista tai ihotautista tai rupista älkää Herralle tuoko, älkääkä sellaisia asettako alttarille, uhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Härän tai lampaan, joka on jäseniltään muodoton tai vaivainen, sinä saat uhrata vapaaehtoisena uhrina, mutta lupausuhriksi se ei ole otollinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Älkää uhratko Herralle eläintä, joka on kuohittu puristamalla tai musertamalla tai repimällä tai leikkaamalla; älkää tehkö maassanne sellaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Älkää myöskään muukalaiselta ostako mitään sellaisia eläimiä tuodaksenne niitä Jumalanne ruuaksi, sillä ne ovat turmeltuja, niissä on vamma; niistä ei tule teidän osaksenne mielisuosio.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, '\"Kun vasikka tai karitsa tai vohla on syntynyt, olkoon se emänsä luona seitsemän päivää; mutta kahdeksannesta päivästä alkaen se on otollinen uhrilahjaksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Älkää raavaseläintä tai lammasta ja sen sikiötä teurastako samana päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Kun te uhraatte Herralle kiitosuhrin, uhratkaa se niin, että hänen mielisuosionsa tulee teidän osaksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Se syötäköön samana päivänä; älkää jättäkö siitä mitään seuraavaan aamuun. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Noudattakaa siis minun käskyjäni ja pitäkää ne. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Älkää häväiskö minun pyhää nimeäni: minä tahdon olla pyhä israelilaisten keskellä. Minä olen Herra, joka pyhitän teidät');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'ja joka vein teidät pois Egyptin maasta, ollakseni teidän Jumalanne. Minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, '\"Puhu israelilaisille ja sano heille: Herran juhla-ajat, joiksi teidän on kuulutettava pyhät kokoukset, minun juhla-aikani, ovat nämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Kuusi päivää tehtäköön työtä, mutta seitsemäntenä päivänä on sapatti, levon päivä, pyhä kokous; silloin älkää yhtäkään askaretta toimittako, se on Herran sapatti, missä asuttekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Nämä ovat Herran juhla-ajat, pyhät kokoukset, jotka teidän on kuulutettava määräajallansa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, iltahämärässä, on pääsiäinen Herran kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Ja saman kuukauden viidentenätoista päivänä on happamattoman leivän juhla Herran kunniaksi; syökää happamatonta leipää seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Ensimmäisenä päivänä olkoon teillä pyhä kokous, silloin älkää yhtäkään arkiaskaretta toimittako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Tuokaa Herralle uhri seitsemänä päivänä. Seitsemäntenä päivänä on pyhä kokous; silloin älkää yhtäkään arkiaskaretta toimittako.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, '\"Puhu israelilaisille ja sano heille: Kun te tulette siihen maahan, jonka minä teille annan, ja leikkaatte sen viljaa, niin viekää papille viljastanne uutislyhde.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Ja hän toimittakoon sen lyhteen heilutuksen Herran edessä, että hänen mielisuosionsa tulisi teidän osaksenne; sapatin jälkeisenä päivänä pappi toimittakoon sen heilutuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Ja sinä päivänä, jona teidän lyhteenne heilutus toimitetaan, uhratkaa virheetön, vuoden vanha karitsa polttouhriksi Herralle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'ja siihen kuuluvaksi ruokauhriksi kaksi kymmenennestä lestyjä jauhoja, öljyyn sekoitettuna, uhriksi, suloiseksi tuoksuksi Herralle, sekä siihen kuuluvaksi juomauhriksi neljännes hiin-mittaa viiniä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Älkääkä syökö uutisleipää, paahdettuja jyviä tai tuleentumatonta viljaa ennen sitä päivää, jona tuotte Jumalallenne uhrilahjan. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Sitten laskekaa sapatin jälkeisestä päivästä, siitä päivästä, jona toitte heilutuslyhteen, seitsemän täyttä viikkoa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'laskekaa viisikymmentä päivää seitsemännen sapatin jälkeiseen päivään asti; sitten tuokaa Herralle uusi ruokauhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Sieltä, missä asutte, tuokaa heilutusleiväksi kaksi kakkua, jotka on leivottava happamena kahdesta kymmenenneksestä lestyjä jauhoja, Herralle uutislahjaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Ja tuokaa leipänne ohella seitsemän virheetöntä, vuoden vanhaa karitsaa ja mullikka sekä kaksi oinasta; ruoka-ja juomauhreineen ne olkoot polttouhri Herralle, suloisesti tuoksuva uhri Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Ja uhratkaa kauris syntiuhriksi sekä kaksi vuoden vanhaa karitsaa yhteysuhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Ja pappi toimittakoon niiden ja uutisleivän ynnä kahden karitsan heilutuksen Herran edessä. Ne olkoot Herralle pyhät ja papin omat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Ja kuuluttakaa pyhä kokous juuri siksi päiväksi; silloin älkää yhtäkään arkiaskaretta toimittako. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Kun te korjaatte eloa maastanne, niin älä leikkaa viljaa pelloltasi reunoja myöten äläkä poimi tähkäpäitä leikkuun jälkeen, vaan jätä ne köyhälle ja muukalaiselle. Minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, '\"Puhu israelilaisille ja sano: Seitsemännessä kuussa, kuukauden ensimmäisenä päivänä, pitäkää sapatinlepo, muistojuhla pasunaa soittaen, pyhä kokous.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Älkää silloin yhtäkään arkiaskaretta toimittako, vaan tuokaa uhri Herralle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, '\"Tämän seitsemännen kuun kymmenentenä päivänä on sovituspäivä; pitäkää silloin pyhä kokous, kurittakaa itseänne paastolla ja tuokaa Herralle uhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Älkää toimittako yhtäkään askaretta sinä päivänä, sillä se on sovituspäivä, jolloin teille toimitetaan sovitus Herran, teidän Jumalanne, edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Sillä jokainen, joka ei sinä päivänä kurita itseänsä paastolla, hävitettäköön kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Ja jokaisen, joka sinä päivänä toimittaa jotakin askaretta, minä hävitän hänen kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Älkää silloin yhtäkään askaretta toimittako. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen, missä asuttekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Se on oleva teille levon päivä, kurittakaa itseänne paastolla. Kuukauden yhdeksäntenä päivänä illalla, illasta iltaan, pitäkää tämä sapatti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, '\"Puhu israelilaisille ja sano: Tämän seitsemännen kuun viidentenätoista päivänä on lehtimajanjuhla Herran kunniaksi; se kestää seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Ensimmäisenä päivänä pidettäköön pyhä kokous; älkää silloin yhtäkään arkiaskaretta toimittako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Seitsemänä päivänä tuokaa uhri Herralle. Kahdeksantena päivänä olkoon teillä pyhä kokous, ja tuokaa uhri Herralle; se on juhlakokous, älkää silloin yhtäkään arkiaskaretta toimittako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Nämä ovat Herran juhla-ajat, joiksi teidän on kuulutettava pyhät kokoukset, tuodaksenne Herralle uhreja: polttouhreja ja ruokauhreja, teurasuhreja ja juomauhreja, kunakin päivänä sen päivän uhrit;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'ja sitäpaitsi Herran sapatit ja teidän muut lahjanne ja kaikki lupausuhrinne ja kaikki vapaaehtoiset uhrinne, joita te Herralle annatte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Mutta seitsemännen kuukauden viidentenätoista päivänä, kun te olette korjanneet maan sadon, viettäkää Herran juhlaa seitsemän päivää; ensimmäinen päivä on levon päivä, ja kahdeksas päivä on myös levon päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Ensimmäisenä päivänä ottakaa ihania hedelmiä puista, palmunoksia ja tuuheiden puiden lehviä sekä pajuja purojen varsilta, ja pitäkää iloa seitsemän päivää Herran, Jumalanne edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Ja viettäkää sitä juhlana Herran kunniaksi seitsemän päivää vuodessa. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen; viettäkää se seitsemännessä kuussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'Seitsemän päivää asukaa lehtimajoissa; kaikki Israelissa syntyneet asukoot lehtimajoissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'että teidän jälkeläisenne tietäisivät, kuinka minä annoin israelilaisten asua lehtimajoissa, kun vein heidät pois Egyptin maasta. Minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Ja Mooses puhui näistä Herran juhla-ajoista israelilaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, '\"Käske israelilaisten tuoda sinulle puhdasta, survomalla saatua öljypuun öljyä seitsenhaaraista lamppua varten, että lamput aina voidaan nostaa paikoilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Ulkopuolella esirippua, joka on lain arkin edessä ilmestysmajassa, Aaron hoitakoon sitä niin, että se aina, ehtoosta aamuun asti, palaa Herran edessä. Se olkoon teille ikuinen säädös sukupolvesta sukupolveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Aitokultaisen seitsenhaaraisen lampun lamppuja hän hoitakoon niin, että ne aina palavat Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Ja ota lestyjä jauhoja ja leivo niistä kaksitoista kakkua; joka kakussa olkoon niitä kaksi kymmenennestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Ja lado ne päälletysten kahteen pinoon, kuusi pinoonsa, aitokultaiselle pöydälle Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Ja pane pinojen päälle puhdasta suitsuketta leipien alttariuhriosana uhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Sapatti sapatilta hän aina asettakoon ne Herran eteen israelilaisten antina; se on ikuinen liitto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Ne olkoot Aaronin ja hänen poikiensa omat, ja he syökööt ne pyhässä paikassa, sillä ne ovat korkeasti-pyhät; ne ovat hänen ikuinen osuutensa Herran uhreista.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Erään israelilaisen vaimon poika, jonka isä oli egyptiläinen mies, oli lähtenyt maasta israelilaisten mukana; ja tämän israelilaisen vaimon poika ja muuan israelilainen mies riitelivät keskenänsä leirissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Ja israelilaisen vaimon poika pilkkasi Herran nimeä ja kirosi sitä. Silloin he toivat hänet Mooseksen eteen. Ja hänen äitinsä nimi oli Selomit, Dibrin tytär, Daanin sukukunnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Ja he panivat hänet vankeuteen, kunnes heille ilmoitettaisiin Herran vastaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, '\"Vie kirooja leirin ulkopuolelle, ja kaikki, jotka kuulivat sen, laskekoot kätensä hänen päänsä päälle, ja koko kansa kivittäköön hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Ja puhu israelilaisille ja sano: Kuka ikinä Jumalaansa kiroaa, se joutuu syynalaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Ja joka Herran nimeä pilkkaa, rangaistakoon kuolemalla; koko kansa kivittäköön hänet kuoliaaksi. Olipa se muukalainen tai maassa syntynyt, joka pilkkaa Herran nimeä, hänet surmattakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Jos joku lyö kuoliaaksi ihmisen, kenen hyvänsä, hänet rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Mutta joka lyö kuoliaaksi kotieläimen, korvatkoon sen: henki hengestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Ja joka tuottaa lähimmäisellensä vamman, sille tehtäköön, niinkuin hänkin on tehnyt:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'ruhje ruhjeesta, silmä silmästä, hammas hampaasta; saman vamman, jonka hän on toiselle tuottanut, saakoon hän itsekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Joka lyö kuoliaaksi kotieläimen, korvatkoon sen; mutta joka lyö kuoliaaksi ihmisen, se surmattakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Sama laki olkoon teillä, niin muukalaisella kuin maassa syntyneelläkin; sillä minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Ja Mooses puhui näin israelilaisille; ja he veivät kiroojan leirin ulkopuolelle ja kivittivät hänet kuoliaaksi. Näin israelilaiset tekivät, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Ja Herra puhui Moosekselle Siinain vuorella sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, '\"Puhu israelilaisille ja sano heille: Kun te tulette siihen maahan, jonka minä teille annan, niin maa pitäköön sapattia Herran kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Kuutena vuotena kylvä peltosi ja kuutena vuotena leikkaa viinitarhasi ja korjaa niiden sato,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'mutta seitsemäntenä vuotena olkoon maalla levon aika, sapatti Herran kunniaksi; silloin älä kylvä peltoasi äläkä leikkaa viinitarhaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Leikatun viljasi jälkikasvua älä leikkaa, äläkä poimi viinirypäleitä, jotka ovat kasvaneet leikkaamattomissa viinipuissasi. Silloin olkoon maalla levon vuosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Mutta mitä itsestänsä kasvaa maan levätessä, olkoon teille ruuaksi, sinulle itsellesi, sinun palvelijallesi ja palvelijattarellesi, päiväpalkkalaisellesi ja loisellesi, jotka luonasi asuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Ja karjallesi ja metsäeläimille sinun maassasi olkoon kaikki sen sato ruuaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Ja laske seitsemän vuosiviikkoa: seitsemän kertaa seitsemän vuotta, niin että seitsemän vuosiviikon aika on neljäkymmentä yhdeksän vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Ja seitsemännessä kuussa, kuukauden kymmenentenä päivänä anna pasunan raikuen soida; sovituspäivänä antakaa pasunan soida koko maassanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Ja pyhittäkää viideskymmenes vuosi ja julistakaa vapautus maassa kaikille sen asukkaille. Se olkoon teille riemuvuosi; jokainen teistä saa silloin palata perintömaallensa ja sukunsa luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Riemuvuosi olkoon teille viideskymmenes vuosi; älkää silloin kylväkö älkääkä jälkikasvua leikatko, älkääkä poimiko, mitä leikkaamattomissa viinipuissa on kasvanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Sillä se on riemuvuosi, se olkoon teille pyhä; pellolta syökää sen sato.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'Riemuvuotena saa jokainen teistä palata perintömaallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Jos myyt jotakin lähimmäisellesi tai ostat jotakin lähimmäiseltäsi, niin älkää tehkö vääryyttä toinen toisellenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Vaan maksa lähimmäisellesi riemuvuoden jälkeisten vuosien luvun mukaan, satovuosien luvun mukaan hän saakoon maksun sinulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Kuta useampia vuosia on, maksa sitä suurempi hinta, ja kuta vähemmän vuosia on, maksa sitä pienempi hinta; sillä satomäärän hän myy sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Älköön teistä kukaan tehkö vääryyttä lähimmäisellensä, vaan pelkää Jumalaasi; sillä minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Sentähden pitäkää minun käskyni ja noudattakaa minun säädöksiäni ja pitäkää ne, niin te saatte turvallisesti asua maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Ja maa on antava hedelmänsä, ja teillä on kyllin syötävää, ja te saatte turvallisesti asua siinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Ja jos te sanotte: \'Mitä me syömme seitsemäntenä vuotena, kun meidän ei ole lupa kylvää eikä korjata satoamme?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'niin minä käsken siunaukseni kuudentena vuotena tulemaan teille, niin että se tuottaa teille kolmen vuoden sadon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Ja kun te kylvätte kahdeksantena vuotena, on teillä vielä vanhaa satoa syödä; siihen asti, kunnes yhdeksäntenä vuotena sen sato on saatu, on teillä vanhaa syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Älköön maata ainaiseksi myytäkö, sillä maa on minun ja te olette muukalaisia ja vieraita minun luonani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Ja kaikessa siinä maassa, jonka te saatte perintömaaksenne, antakaa oikeus maan sukulunastamiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Jos veljesi köyhtyy ja myy perintömaatansa, niin hänen lähin sukulunastajansa tulkoon ja lunastakoon sen, mitä hänen veljensä on myynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Mutta jos jollakin ei ole sukulunastajaa, mutta hän itse voi hankkia niin paljon, kuin lunastukseen tarvitaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'niin laskekoon, kuinka monta vuotta on kulunut myymisestä, ja maksakoon jäljellä olevasta ajasta miehelle, jolle hän myi, ja palatkoon perintömaallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Mutta jos hän ei voi hankkia niin paljoa, kuin maksamiseen tarvitaan, niin jääköön se, mitä hän on myynyt, ostajan haltuun riemuvuoteen asti. Mutta riemuvuotena se on vapaa, ja hän palatkoon perintömaallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Jos joku myy asuinrakennuksen muureilla varustetussa kaupungissa, olkoon hänellä oikeus lunastaa se vuoden kuluessa siitä, kun hän sen myi; sen ajan kestää hänen sukulunastusoikeutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Mutta jollei sitä lunasteta, ennenkuin vuosi on kulunut umpeen, niin jääköön talo muureilla varustetussa kaupungissa ainaiseksi ostajalle ja hänen suvullensa, riemuvuotena vapaaksi tulematta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Mutta talot kylissä, joiden ympärillä ei ole muuria, luettakoon peltomaahan; ne olkoot lunastettavissa, ja riemuvuotena ne tulevat vapaiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Kuitenkin olkoon leeviläisillä niissä kaupungeissa, jotka ovat heidän perintöomaisuuttaan, ikuinen oikeus talojen lunastamiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Jos joku leeviläinen käyttää lunastusoikeutta, niin myyty talo kaupungissa, joka on leeviläistä perintöomaisuutta, palautuu riemuvuotena vapaaksi; sillä talot leeviläiskaupungeissa ovat heidän perintöomaisuuttaan israelilaisten seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Ja heidän kaupunkeihinsa kuuluvaa laidunmaata älköön myytäkö, sillä se on heidän ikuista perintöomaisuuttansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Jos veljesi sinun luonasi köyhtyy eikä jaksa pysyä pystyssä, tue häntä samoinkuin muukalaista tai loista; hän eläköön luonasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Älä ota korkoa tai voittoa häneltä, vaan pelkää Jumalaasi ja anna veljesi elää luonasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Älä anna hänelle rahaasi korolle äläkä ota elintarpeista voittoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta antaakseni teille Kanaanin maan ja ollakseni teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Jos veljesi sinun luonasi köyhtyy ja myy itsensä sinulle, älä pane häntä orjan työhön,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'vaan hän olkoon päiväpalkkalaisena ja loisena sinun luonasi; riemuvuoteen asti hän palvelkoon sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Silloin hän lähteköön luotasi vapaana, hän ja hänen lapsensa hänen kanssaan, ja palatkoon sukunsa luo ja isiensä perintömaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Sillä he ovat minun palvelijoitani, jotka minä vein pois Egyptin maasta; sentähden älköön heitä orjan tavalla myytäkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Älä hallitse heitä kovuudella, vaan pelkää Jumalaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Mutta orjasi ja orjattaresi, jotka hankit itsellesi, ostakaa kansoista, jotka asuvat teidän ympärillänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Tahi ostakaa ne teidän luonanne asuvien loisten lapsista ja heidän sukulaisistaan, jotka ovat teidän luonanne ja jotka ovat heille syntyneet teidän maassanne; ja ne olkoot teidän perintöomaisuuttanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Ja jättäkää ne jälkeenne perinnöksi lapsillenne, pysyväksi perintöomaisuudeksi; niitä saatte pitää ainaisesti orjinanne. Mutta veljistänne, israelilaisista, älä ketään kovuudella hallitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Jos sinun luonasi asuva muukalainen tai loinen tulee varoihin, veljesi köyhtyessä hänen luonaan, niin että hän myy itsensä sinun luonasi asuvalle muukalaiselle tai loiselle tai jollekin muukalaisen suvun jäsenelle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'niin olkoon hän, sen jälkeen kuin hän myi itsensä, lunastettavissa; joku hänen veljistään lunastakoon hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Tahi lunastakoon hänet hänen setänsä tai setänsä poika tai joku veriheimolainen hänen suvustansa; tahi jos hän tulee varoihin, lunastakoon hän itse itsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Ja hänen on laskettava yhdessä ostajansa kanssa, kuinka pitkä aika on riemuvuoteen siitä vuodesta, jolloin hän myi itsensä hänelle; ja hänen myyntihintansa jaettakoon vuosien luvulla; hänen palvelusaikansa laskettakoon saman arvoiseksi kuin päiväpalkkalaisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Jos vielä on monta vuotta jäljellä, maksakoon hän takaisin lunastushintanaan niitä vastaavan osan siitä summasta, jolla hänet ostettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Mutta jos vain vähän vuosia on jäljellä riemuvuoteen, laskekoon ostaja nekin hänelle, ja hän maksakoon lunastushintansa sen mukaan, kuin hänellä on vuosia jäljellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Vuosikaupalla otetun päiväpalkkalaisen tavalla hän palvelkoon häntä, mutta älköön tämä kovuudella hallitko häntä sinun silmiesi edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Mutta jos häntä ei näin lunasteta, tulkoon hän riemuvuotena vapaaksi, hän itse ja hänen lapsensa hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Sillä israelilaiset ovat minun palvelijoitani; he ovat minun palvelijani, jotka minä vein pois Egyptin maasta. Minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, '\"Älkää tehkö itsellenne epäjumalia älkääkä pystyttäkö itsellenne jumalankuvia tai patsaita, älkää myöskään asettako maahanne kiviä, joissa on kuvia, kumartaaksenne niitä, sillä minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Pitäkää minun sapattini ja peljätkää minun pyhäkköäni. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Jos te vaellatte minun säädöksieni mukaan ja noudatatte minun käskyjäni ja pidätte ne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'annan minä teille sateen ajallansa, niin että maa antaa satonsa ja kedon puut kantavat hedelmänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Ja puiminen kestää teillä viininkorjuuseen asti, ja viininkorjuu kestää kylvöön asti, ja teillä on kyllin leipää syödäksenne, ja te saatte turvallisesti asua maassanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Ja minä annan rauhan teidän maallenne, ja te saatte levätä, kenenkään peljättämättä; ja minä hävitän pahat pedot teidän maastanne, eikä miekka käy teidän maanne ylitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Te ajatte pakoon vihollisenne, ja he kaatuvat miekkaan teidän edessänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Viisi teistä ajaa pakoon sata, ja sata teistä ajaa pakoon kymmenentuhatta, ja teidän vihollisenne kaatuvat miekkaan teidän edessänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Ja minä käännyn teidän puoleenne ja teen teidät hedelmällisiksi ja annan teidän lisääntyä ja pidän liittoni teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Ja te saatte syödä vanhaa, viime vuoden satoa, ja te joudutte viemään vanhan pois uuden tieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Ja minä panen asumukseni teidän keskellenne enkä viero teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Ja minä vaellan teidän keskellänne ja olen teidän Jumalanne, ja te olette minun kansani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta, olemasta heidän orjinansa; ja minä mursin rikki teidän ikeenne puut ja annoin teidän kulkea pää pystyssä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Mutta jos te ette kuule minua ettekä pidä kaikkia näitä käskyjä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'vaan hylkäätte halpana minun ohjeeni ja teidän sielunne vieroo minun säädöksiäni, niin ettette pidä kaikkia minun käskyjäni, vaan rikotte minun liittoni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'niin minäkin teen teille samoin ja rankaisen teitä hirmuisilla onnettomuuksilla, hivutustaudilla ja kuumeella, jotka sammuttavat teidän silmänne ja näännyttävät sielunne; ja te kylvätte siemenenne turhaan, sillä teidän vihollisenne syövät sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Ja minä käännän kasvoni teitä vastaan, ja teidän vihollisenne voittavat teidät; teidän vihamiehenne hallitsevat teitä, ja te pakenette, vaikka ei kukaan aja teitä takaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Jos ette sittenkään kuule minua, niin minä vielä kuritan teitä seitsenkertaisesti teidän syntienne tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Ja minä murran teidän ylpeän uhmanne; minä teen teidän taivaanne raudankovaksi ja maanne vasken kaltaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Ja teidän voimanne kuluu hukkaan, sillä teidän maanne ei anna satoansa eivätkä maan puut anna hedelmäänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Ja jos te sittenkin käytte minua vastaan ettekä tahdo kuulla minua, niin minä lyön teitä vielä seitsenkertaisesti, teidän syntienne mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Minä lähetän teidän sekaanne metsän pedot riistämään teiltä lapsenne, raatelemaan karjaanne ja vähentämään teidän lukuanne, niin että teidän tienne tulevat autioiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Jos te ette vielä tästäkään minun kurituksestani ota ojentuaksenne, vaan yhä käytte minua vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'niin minäkin käyn teitä vastaan ja lyön teitä seitsenkertaisesti teidän syntienne tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Minä saatan teidän kimppuunne miekan, joka kostaa rikotun liiton; ja kun te kokoonnutte kaupunkeihinne, niin minä lähetän teidän sekaanne ruttotaudin, ja teidän on antautuminen vihollisen valtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Kun minä murran teiltä leivän tuen, niin kymmenen vaimoa paistaa teidän leipänne yhdessä uunissa, ja he tuovat kotiin teidän leipänne vaa\'alla punnittuna; ja kun te syötte, ette tule ravituiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Ja jos te ette vielä sittenkään kuule minua, vaan yhä käytte minua vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'niin minäkin kiivastuksessani käyn teitä vastaan ja kuritan teitä seitsenkertaisesti teidän syntienne tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Ja te syötte poikienne lihaa, ja tyttärienne lihaa te syötte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Ja minä kukistan teidän uhrikukkulanne ja hävitän teidän auringonpatsaanne ja panen teidän ruumiinne teidän kivijumalienne ruumiiden päälle, ja minun sieluni inhoaa teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Ja minä muutan teidän kaupunkinne raunioiksi ja hävitän teidän pyhäkkönne enkä mielisty teidän uhrienne tuoksuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Ja minä hävitän maan, niin että teidän vihollisenne, jotka siinä asuvat, siitä tyrmistyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Mutta teidät minä hajotan kansojen sekaan ja ajan teitä takaa paljastetulla miekalla, ja teidän maanne tulee autioksi ja kaupunkinne raunioiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Silloin maa saa hyvityksen sapateistaan, niin kauan kuin se on autiona ja te olette vihollistenne maassa. Silloin maa lepää ja saa hyvityksen sapateistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Niin kauan kuin se on autiona, saa se levätä nauttien sitä lepoa, jota se ei saanut teidän sapatteinanne, asuessanne siinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Ja niille teistä, jotka jäävät jäljelle, minä annan pelokkaan sydämen heidän vihollistensa maassa, niin että lentävän lehden kahina ajaa heidät pakoon, ja he pakenevat, niinkuin pakenisivat miekkaa, ja kaatuvat, vaikka ei kukaan heitä aja takaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Ja he kompastuvat toinen toiseensa niinkuin miekkaa paeten, vaikka ei kukaan aja heitä takaa; ja te ette voi pitää puolianne vihollisianne vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Ja te häviätte kansojen sekaan, ja vihollistenne maa nielee teidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Ja ne teistä, jotka jäävät jäljelle, riutuvat teidän vihollistenne maassa syntivelkansa tähden; ja myös isiensä syntivelan tähden he riutuvat niinkuin nekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Silloin he tunnustavat syntivelkansa ja isiensä syntivelan, sen että ovat olleet minulle uskottomat ja käyneet minua vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'jonka tähden minäkin kävin heitä vastaan ja vein heidät heidän vihollistensa maahan. Silloin heidän ympärileikkaamaton sydämensä nöyrtyy, ja silloin he sovittavat syntivelkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Ja silloin minä muistan liittoni Jaakobin kanssa ja muistan liittoni Iisakin kanssa ja liittoni Aabrahamin kanssa, ja minä muistan myös maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Mutta ensin tulkoon maa tyhjäksi heistä ja saakoon hyvityksen sapateistansa olemalla autiona, niin kauan kuin he ovat poissa; ja he sovittakoot syntivelkansa sentähden, juuri sentähden, että he hylkäsivät minun säädökseni ja että heidän sielunsa vieroi minun käskyjäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Mutta sittenkään, vaikka he ovat vihollistensa maassa, en minä heitä hylkää enkä viero heitä niin, että lopettaisin heidät ja rikkoisin liittoni heidän kanssansa; sillä minä olen Herra, heidän Jumalansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Ja minä muistan heidän hyväksensä liiton heidän isiensä kanssa, jotka minä vein pois Egyptin maasta kansojen silmien edessä, ollakseni heidän Jumalansa. Minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Nämä ovat ne käskyt, säädökset ja lait, jotka Herra asetti itsensä ja israelilaisten välille Siinain vuorella, Mooseksen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, '\"Puhu israelilaisille ja sano heille: Jos jollakin on täytettävänä lupaus Herralle ja sinun on arvioitava luvatun ihmisen arvo,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'niin arvioitse mies, joka on kahdenkymmenen ja kuudenkymmenen vuoden välillä, viiteenkymmeneen hopeasekeliin pyhäkkösekelin painon mukaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'mutta jos se on nainen, arvioitse hänet kolmeenkymmeneen sekeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Viisivuotisesta kaksikymmenvuotiseen asti arvioitse miehenpuoli kahteenkymmeneen sekeliin ja vaimonpuoli kymmeneen sekeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Kuukauden vanhasta viisivuotiseen asti arvioitse miehenpuoli viiteen hopeasekeliin ja vaimonpuoli kolmeen hopeasekeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Kuusikymmenvuotinen ja sitä vanhempi miehenpuoli arvioitse viiteentoista sekeliin ja vaimonpuoli kymmeneen sekeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Jos joku on liian köyhä maksamaan arviohintaa, vietäköön hänet papin eteen, ja pappi arvioikoon hänet; lupauksen tekijän varojen mukaan arvioikoon pappi hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Mutta jos lupaus koskee karjaa, josta voidaan tuoda uhrilahja Herralle, olkoon kaikki, mikä siitä annetaan Herralle, pyhää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Sitä älköön vaihdettako älköönkä muutettako; ei hyvää huonoon eikä huonoa hyvään. Jos joku kuitenkin vaihtaa eläimen toiseen, olkoon sekä se että siihen vaihdettu pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Mutta jos se on saastainen eläin, mikä tahansa, joita ei saa tuoda uhrilahjaksi Herralle, niin vietäköön eläin papin eteen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'ja pappi arvioikoon sen tarkastaen, onko se hyvä vai huono. Olkoon sillä se arviohinta, jonka pappi määrää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Jos omistaja tahtoo sen lunastaa, antakoon arviohinnan lisäksi viidennen osan siitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Ja jos joku pyhittää talonsa pyhäksi lahjaksi Herralle, niin pappi arvioikoon sen tarkastaen, onko se hyvä vai huono. Olkoon sillä se arviohinta, jonka pappi määrää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'Mutta jos se, joka on talonsa pyhittänyt, tahtoo lunastaa sen, niin antakoon arviosumman lisäksi viidennen osan siitä; ja niin se on hänen omansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Jos joku pyhittää Herralle kappaleen perintömaatansa, niin arvioi se kylvön suuruuden mukaan; hoomer-mitta ohria vastatkoon viittäkymmentä hopeasekeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Jos hän pyhittää peltonsa riemuvuodesta alkaen, jääköön sille arvioimasi täysi hinta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Mutta jos hän pyhittää peltonsa riemuvuoden jälkeen, laskekoon pappi hänelle rahasumman niiden vuosien luvun mukaan, jotka ovat jäljellä seuraavaan riemuvuoteen; ja se vähennettäköön sinun arvioimastasi hinnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Ja jos se, joka pellon on pyhittänyt, tahtoo lunastaa sen, niin antakoon arvioimasi hinnan lisäksi viidennen osan siitä; ja niin se jää hänen omakseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Mutta jos hän ei lunasta peltoa, vaan myy sen toiselle, ei se enää ole lunastettavissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'vaan kun pelto riemuvuotena tulee vapaaksi, olkoon se Herralle pyhitetty, niinkuin vihitty pelto; se joutuu papin omaisuudeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Jos joku Herralle pyhittää ostamansa pellon, joka ei ole hänen perintömaatansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'laskekoon pappi hänelle arviohinnan riemuvuoteen asti; ja hän suorittakoon samana päivänä arvioimasi hinnan pyhänä lahjana Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Riemuvuotena pelto palautukoon sille, jolta se on ostettu ja jonka perintömaata se on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Ja kaikki sinun arvioimisesi tapahtukoon pyhäkkösekelin painon mukaan; sekelissä olkoon kaksikymmentä geeraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Mutta karjan esikoista, joka ensiksi syntyneenä jo on Herran oma, älköön kukaan pyhittäkö; olipa se härkä tai lammas, se on jo Herran oma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Jos se on saastaisia eläimiä, lunastakoon omistaja sen sinun arvioimastasi hinnasta ja pankoon lisäksi viidennen osan sen arvosta; jos sitä ei lunasteta, myytäköön se arvioimaasi hintaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Mitään vihittyä, mitä hyvänsä, jonka joku on vihkinyt Herralle omaisuudestansa, olipa se ihminen tai eläin tai perintömaa, älköön myytäkö älköönkä lunastettako; sillä kaikki vihitty on korkeasti-pyhää, Herran omaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Ihmistä, ketä hyvänsä, joka on tuhon omaksi vihitty, älköön lunastettako, vaan hänet surmattakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Kaikki maan kymmenykset, sekä pellon viljasta että puiden hedelmistä, ovat Herran omat, pyhä lahja Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Jos joku tahtoo lunastaa jotakin kymmenyksistänsä, antakoon hän siihen lisäksi viidennen osan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Ja kaikki kymmenykset raavaskarjasta ja pikkukarjasta, joka kymmenes eläin kaikesta, mikä kulkee paimenen sauvan alitse, olkoot pyhä lahja Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Älköön kysyttäkö, onko se hyvä vai huono, älköönkä sitä vaihdettako. Jos joku kuitenkin vaihtaa sen, niin olkoon sekä se että siihen vaihdettu pyhä; älköön niitä lunastettako.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Nämä ovat ne käskyt, jotka Herra Siinain vuorella antoi Moosekselle israelilaisia varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Ja Herra puhui Moosekselle Siinain erämaassa ilmestysmajassa toisen kuukauden ensimmäisenä päivänä, toisena vuotena siitä, kun he olivat lähteneet Egyptin maasta, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '\"Laskekaa koko Israelin kansan väkiluku suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaikki miehenpuolet, pääluvun mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Pitäkää katselmus, sinä ja Aaron, kaikista Israelin sotakelpoisista miehistä, kaksikymmenvuotisista ja sitä vanhemmista, osastoittain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Ja teidän apunanne olkoon yksi mies jokaisesta sukukunnasta, sen perhekuntien päämies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Ja nämä ovat niiden miesten nimet, jotka teitä avustakoot: Ruubenista Elisur, Sedeurin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Simeonista Selumiel, Suurisaddain poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Juudasta Nahson, Amminadabin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Isaskarista Netanel, Suuarin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Sebulonista Eliab, Heelonin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Joosefin pojista: Efraimista Elisama, Ammihudin poika ja Manassesta Gamliel, Pedasurin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Benjaminista Abidan, Gideonin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Daanista Ahieser, Ammisaddain poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Asserista Pagiel, Okranin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Gaadista Eljasaf, Deguelin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Naftalista Ahira, Eenanin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Nämä olkoot kansan edusmiehet, heidän isiensä sukukuntien ruhtinaat, Israelin heimojen päämiehet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Ja Mooses ja Aaron ottivat luoksensa nämä nimeltä mainitut miehet');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'ja kokosivat kaiken kansan toisen kuukauden ensimmäisenä päivänä, ja kansa pantiin luetteloihin suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotiset ja sitä vanhemmat, pääluvun mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'niinkuin Herra oli Moosekselle käskyn antanut. Niin hän piti heistä katselmuksen Siinain erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Ruubenin, Israelin esikoisen, jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän, pääluvun mukaan, kaikkiaan miehenpuolia, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'näitä Ruubenin sukukunnasta katselmuksessa olleita oli neljäkymmentäkuusi tuhatta viisisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Simeonin jälkeläisiä, katselmuksessa olleita, oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän, pääluvun mukaan, kaikkiaan miehenpuolia, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'näitä Simeonin sukukunnasta katselmuksessa olleita oli viisikymmentäyhdeksän tuhatta kolmesataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Gaadin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'näitä Gaadin sukukunnasta katselmuksessa olleita oli neljäkymmentäviisi tuhatta kuusisataa viisikymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Juudan jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'näitä Juudan sukukunnasta katselmuksessa olleita oli seitsemänkymmentäneljä tuhatta kuusisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Isaskarin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'näitä Isaskarin sukukunnasta katselmuksessa olleita oli viisikymmentäneljä tuhatta neljäsataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Sebulonin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'näitä Sebulonin sukukunnasta katselmuksessa olleita oli viisikymmentäseitsemän tuhatta neljäsataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Joosefin jälkeläisiä, Efraimin jälkeläisiä, oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'näitä Efraimin sukukunnasta katselmuksessa olleita oli neljäkymmentätuhatta viisisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Manassen jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'näitä Manassen sukukunnasta katselmuksessa olleita oli kolmekymmentäkaksi tuhatta kaksisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Benjaminin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'näitä Benjaminin sukukunnasta katselmuksessa olleita oli kolmekymmentäviisi tuhatta neljäsataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Daanin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'näitä Daanin sukukunnasta katselmuksessa olleita oli kuusikymmentäkaksi tuhatta seitsemänsataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Asserin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'näitä Asserin sukukunnasta katselmuksessa olleita oli neljäkymmentäyksi tuhatta viisisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Naftalin jälkeläisiä oli polveutumisensa mukaan, suvuittain ja perhekunnittain, nimien lukumäärän mukaan, kaksikymmenvuotisia ja sitä vanhempia, kaikkia sotakelpoisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'näitä Naftalin sukukunnasta katselmuksessa olleita oli viisikymmentäkolme tuhatta neljäsataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Nämä ovat ne katselmuksessa olleet, joista Mooses ja Aaron ja Israelin ruhtinaat, nuo kaksitoista miestä, perhekuntiansa edustaen, pitivät katselmuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Ja kaikkiaan katselmuksessa olleita israelilaisia oli perhekunnittain, kaksikymmenvuotisia ja sitä vanhempia, kaikkia Israelin sotakelpoisia miehiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'näitä katselmuksessa olleita oli yhteensä kuusisataakolme tuhatta viisisataa viisikymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Mutta leeviläisistä, heidän isiensä sukukunnasta, ei pidetty katselmusta yhdessä muiden kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Sillä Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, '\"Ainoastaan Leevin sukukunnasta älä pidä katselmusta äläkä laske heidän väkilukuansa yhdessä muiden israelilaisten kanssa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'vaan pane leeviläiset hoitamaan lain asumusta ja sen kaikkea kalustoa ja kaikkea, mitä siihen kuuluu. He kantakoot asumusta ja sen kaikkea kalustoa, ja he toimittakoot siinä palvelusta sekä leiriytykööt asumuksen ympärille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Kun asumus lähtee liikkeelle, purkakoot leeviläiset sen; ja kun asumus pysähtyy leiripaikkaan, pystyttäkööt leeviläiset sen. Syrjäinen, joka siihen ryhtyy, surmattakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Muut israelilaiset asettukoot kukin omaan leiriinsä ja kukin lippunsa luo, osastoittain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Mutta leeviläiset leiriytykööt lain asumuksen ympärille, ettei Herran viha kohtaisi Israelin kansaa, ja leeviläiset hoitakoot tehtäviä lain asumuksessa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Ja israelilaiset tekivät kaiken, niinkuin Herra oli Moosekselle käskyn antanut; niin he tekivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Ja Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, '\"Israelilaiset leiriytykööt kukin lippunsa luo, perhekuntiensa sotamerkkien kohdalle; he leiriytykööt taammas ilmestysmajan ympärille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Etupuolelle, itään päin, leiriytyköön Juudan leirin lippukunta osastoittain, ja Juudan jälkeläisten päämiehenä olkoon Nahson, Amminadabin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'hänen osastonsa, katselmuksessa olleet, on seitsemänkymmentäneljä tuhatta kuusisataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Hänen viereensä leiriytyköön Isaskarin sukukunta, ja Isaskarin jälkeläisten päämiehenä olkoon Netanel, Suuarin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'hänen osastonsa, katselmuksessa olleet, on viisikymmentäneljä tuhatta neljäsataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Sitten Sebulonin sukukunta, ja Sebulonin jälkeläisten päämiehenä olkoon Eliab, Heelonin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'hänen osastonsa, katselmuksessa olleet, on viisikymmentäseitsemän tuhatta neljäsataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Juudan leirin katselmuksessa olleita on siis kaikkiaan sata kahdeksankymmentäkuusi tuhatta neljäsataa miestä, osastoittain; he lähtekööt liikkeelle ensimmäisenä joukkona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Ruubenin leirin lippukunta leiriytyköön etelään päin osastoittain, ja Ruubenin jälkeläisten päämiehenä olkoon Elisur, Sedeurin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'hänen osastonsa, katselmuksessa olleet, on neljäkymmentäkuusi tuhatta viisisataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Hänen viereensä leiriytyköön Simeonin sukukunta, ja Simeonin jälkeläisten päämiehenä olkoon Selumiel, Suurisaddain poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'hänen osastonsa, katselmuksessa olleet, on viisikymmentäyhdeksän tuhatta kolmesataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Sitten Gaadin sukukunta, ja Gaadin jälkeläisten päämiehenä olkoon Eljasaf, Reguelin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'hänen osastonsa, katselmuksessa olleet, on neljäkymmentäviisi tuhatta kuusisataa viisikymmentä miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Ruubenin leirin katselmuksessa olleita on siis kaikkiaan sata viisikymmentäyksi tuhatta neljäsataa viisikymmentä miestä, osastoittain. He lähtekööt liikkeelle toisena joukkona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Sitten lähtee liikkeelle ilmestysmaja ja leeviläisten leiri toisten leirien keskellä. Niinkuin olivat leiriytyneet, niin lähteköötkin, kukin kohdallansa, lippukunnittain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Efraimin leirin lippukunta leiriytyköön länteen päin osastoittain, ja Efraimin jälkeläisten päämiehenä olkoon Elisama, Ammihudin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'hänen osastonsa, katselmuksessa olleet, on neljäkymmentä tuhatta viisisataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Hänen viereensä leiriytyköön Manassen sukukunta, ja Manassen jälkeläisten päämiehenä olkoon Gamliel, Pedasurin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'hänen osastonsa, katselmuksessa olleet, on kolmekymmentäkaksi tuhatta kaksisataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Sitten Benjaminin sukukunta, ja Benjaminin jälkeläisten päämiehenä olkoon Abidan, Gideonin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'hänen osastonsa, katselmuksessa olleet, on kolmekymmentäviisi tuhatta neljäsataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Efraimin leirin katselmuksessa olleita on siis kaikkiaan satakahdeksan tuhatta ja sata miestä, osastoittain. He lähtekööt liikkeelle kolmantena joukkona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Daanin leirin lippukunta leiriytyköön pohjoiseen päin osastoittain, ja Daanin jälkeläisten päämiehenä olkoon Ahieser, Ammisaddain poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'hänen osastonsa, katselmuksessa olleet, on kuusikymmentäkaksi tuhatta seitsemänsataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Hänen viereensä leiriytyköön Asserin sukukunta, ja Asserin jälkeläisten päämiehenä olkoon Pagiel, Okranin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'hänen osastonsa, katselmuksessa olleet, on neljäkymmentäyksi tuhatta viisisataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Sitten Naftalin sukukunta, ja Naftalin jälkeläisten päämiehenä olkoon Ahira, Eenanin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'hänen osastonsa, katselmuksessa olleet, on viisikymmentäkolme tuhatta neljäsataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Daanin leirin katselmuksessa olleita on siis kaikkiaan sata viisikymmentäseitsemän tuhatta kuusisataa miestä. He lähtekööt liikkeelle viimeisenä joukkona, lippukuntinensa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Nämä olivat israelilaisten katselmuksessa olleet, perhekunnittain; eri leirien katselmuksessa olleita oli osastoittain kaikkiaan kuusisataakolme tuhatta viisisataa viisikymmentä miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Mutta leeviläisten katselmusta ei pidetty samalla kuin muiden israelilaisten, sillä niin oli Herra Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Ja israelilaiset tekivät kaiken, niinkuin Herra oli Moosekselle käskyn antanut. Niin he leiriytyivät lippukunnittain, ja niin he lähtivät liikkeelle kukin suvuittain ja perhekunnittain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Tämä on kertomus Aaronin ja Mooseksen suvusta, siihen aikaan kun Herra puhui Moosekselle Siinain vuorella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Nämä ovat Aaronin poikien nimet: Naadab, esikoinen, Abihu, Eleasar ja Iitamar.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Nämä ovat Aaronin poikien, voideltujen pappien, nimet, niiden, jotka olivat vihityt papinvirkaa toimittamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Mutta Naadab ja Abihu kuolivat Herran edessä tuodessaan vierasta tulta Herran eteen Siinain erämaassa; ja heillä ei ollut poikia. Niin Eleasar ja Iitamar toimittivat papinvirkaa isänsä Aaronin edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, '\"Tuo Leevin sukukunta esille ja aseta se pappi Aaronin eteen palvelemaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Ja he hoitakoot sekä hänen että koko kansan tehtäviä ilmestysmajan edustalla, toimittakoot palvelusta asumuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Ja he hoitakoot kaikkea ilmestysmajan kalustoa ja israelilaisten tehtäviä, toimittakoot palvelusta asumuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Niin on sinun annettava leeviläiset Aaronille ja hänen pojilleen; antakoot israelilaiset heidät hänen haltuunsa, hänelle palvelijoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Mutta Aaronin ja hänen poikiensa käske hoitaa papinvirkansa. Syrjäinen, joka siihen ryhtyy, surmattakoon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, '\"Katso, minä itse olen ottanut leeviläiset israelilaisten keskuudesta israelilaisten kaikkien esikoisten sijaan, kaiken sijaan, joka avaa äidinkohdun; leeviläiset ovat siis tulleet minun omikseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Sillä minun omani on jokainen esikoinen. Sinä päivänä, jona minä surmasin kaikki Egyptin maan esikoiset, minä pyhitin itselleni kaikki Israelin esikoiset, sekä ihmisten että karjan; minun omani ne ovat. Minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Ja Herra puhui Moosekselle Siinain erämaassa sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, '\"Pidä leeviläisten katselmus perhekunnittain ja suvuittain; kaikista miehenpuolista, kuukauden ikäisistä ja sitä vanhemmista, pidä katselmus\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Ja Mooses piti heistä katselmuksen Herran käskyn mukaan, niinkuin hänelle oli määrätty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Ja nämä olivat Leevin poikien nimet: Geerson, Kehat ja Merari.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Ja nämä olivat Geersonin poikien nimet, suvuittain: Libni ja Siimei.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Ja Kehatin pojat olivat, suvuittain, Amram, Jishar, Hebron ja Ussiel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Ja Merarin pojat olivat, suvuittain, Mahli ja Muusi. Nämä olivat Leevin suvut perhekunnittain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Geersonista polveutuivat libniläisten suku ja siimeiläisten suku. Nämä olivat geersonilaisten suvut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Katselmuksessa olleita oli heitä, kaikkien miehenpuolten, kuukauden ikäisten ja sitä vanhempien, lukumäärän mukaan-näitä katselmuksessa olleita oli seitsemäntuhatta viisisataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Geersonilaisten suvut leiriytyivät asumuksen taakse länteen päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Ja geersonilaisten perhekunta-päämies oli Eljasaf, Laaelin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Geersonin poikien hoidettavana ilmestysmajassa oli asumus ja teltta, sen peite, ilmestysmajan oven uudin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'ja asumusta ja alttaria ympäröivän esipihan ympärysverhot ja sen portin uudin sekä sen köydet-kaikki ne palvelustehtävineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Kehatista polveutuivat amramilaisten suku, jisharilaisten suku, hebronilaisten suku ja ussielilaisten suku. Nämä olivat kehatilaisten suvut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Miehenpuolten, kuukauden ikäisten ja sitä vanhempien, lukumäärän mukaan oli heitä kaikkiaan kahdeksantuhatta kuusisataa, jotka hoitivat pyhäkössä suoritettavia tehtäviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Kehatilaisten suvut leiriytyivät asumuksen sivulle etelään päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Ja kehatilaisten sukujen perhekunta-päämies oli Elisafan, Ussielin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Heidän hoidettavanaan oli arkki, pöytä, seitsenhaarainen lamppu, alttarit ja pyhä kalusto, jota jumalanpalveluksessa käytettiin, ynnä esirippu-kaikkine palvelustehtävineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Ja leeviläisten päämiesten esimies oli Eleasar, pappi Aaronin poika; hän oli niiden päällysmies, jotka hoitivat tehtäviä pyhäkössä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Merarista polveutuivat mahlilaisten suku ja muusilaisten suku. Nämä olivat Merarin suvut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Katselmuksessa olleita oli heitä kaikkien miehenpuolten, kuukauden ikäisten ja sitä vanhempien, lukumäärän mukaan kuusituhatta kaksisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Ja Merarin sukujen perhekunta-päämies oli Suuriel, Abihailin poika. He leiriytyivät asumuksen sivulle pohjoiseen päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Ja Merarin poikien hoidettavaksi oli uskottu asumuksen laudat, poikkitangot, pylväät ja jalustat sekä kaikki sen kalusto-kaikki ne palvelustehtävineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'niinikään ympärillä olevan esipihan pylväät jalustoinensa, vaarnoinensa ja köysinensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Mutta asumuksen eteen, itään päin, ilmestysmajan eteen, auringon nousuun päin, leiriytyivät Mooses ja Aaron ynnä hänen poikansa; heidän hoidettavanaan oli pyhäkkö, se, mikä oli israelilaisten hoidettavana. Mutta syrjäinen, joka ryhtyi siihen, oli surmattava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Katselmuksessa olleita leeviläisiä, joista Mooses ja Aaron Herran käskyn mukaan pitivät katselmuksen suvuittain, kaikkia miehenpuolia, kuukauden ikäisiä ja sitä vanhempia, oli kaikkiaan kaksikymmentäkaksi tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Ja Herra sanoi Moosekselle: \"Katsasta kaikki israelilaisten miehenpuoliset esikoiset, kuukauden ikäisistä ja sitä vanhemmista, ja laske heidän nimiensä lukumäärä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Ja ota minulle-minä olen Herra-leeviläiset israelilaisten kaikkien esikoisten sijaan sekä myös leeviläisten karja israelilaisten karjan kaikkien esikoisten sijaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Ja Mooses katsasti, niinkuin Herra oli häntä käskenyt, kaikki israelilaisten esikoiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Ja katselmuksessa olleita oli heitä, kaikkia miehenpuolisia esikoisia, nimien lukumäärän mukaan, kuukauden ikäisiä ja sitä vanhempia, kaikkiaan kaksikymmentäkaksi tuhatta kaksisataa seitsemänkymmentä kolme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, '\"Ota leeviläiset israelilaisten kaikkien esikoisten sijaan ja leeviläisten karja heidän karjansa sijaan, ja niin leeviläiset tulevat minun omikseni. Minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Mutta lunastukseksi noista kahdestasadasta seitsemästäkymmenestä kolmesta, jonka verran israelilaisten esikoisia on yli leeviläisten määrän,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'ota miestä kohti viisi sekeliä, ota ne pyhäkkösekelin painon mukaan, kaksikymmentä geeraa laskettuna sekeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Ja anna se raha Aaronille ja hänen pojillensa lunastukseksi niistä, joita on yli leeviläisten määrän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Ja Mooses otti lunastushinnan niistä, joita oli yli leeviläisillä lunastettujen määrän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Israelilaisten esikoisista hän otti tämän rahan, tuhat kolmesataa kuusikymmentä viisi sekeliä pyhäkkösekelin painon mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Ja Mooses antoi sen lunastushinnan Aaronille ja hänen pojillensa Herran käskyn mukaan, niinkuin Herra oli Moosesta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Ja Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, '\"Laske Leevin jälkeläisten joukosta Kehatin jälkeläisten lukumäärä suvuittain ja perhekunnittain,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'kolmikymmenvuotiset ja sitä vanhemmat aina viisikymmenvuotisiin saakka, kaikki, joiden on palveltava toimittamalla askareita ilmestysmajassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Kehatin poikien palvelustehtävänä ilmestysmajassa olkoon tämä: huolenpito korkeasti-pyhistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Ja leirin liikkeelle lähtiessä menkööt Aaron ja hänen poikansa ja päästäkööt alas esiripun sekä peittäkööt sillä lain arkin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'sitten he pankoot sen päälle sireeninnahkapeitteen ja levittäkööt päällimmäiseksi vaatteen, kokonaan punasinisistä langoista tehdyn, ja asettakoot paikoilleen sen korennot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Ja näkyleipäpöydälle he levittäkööt punasinisen vaatteen ja pankoot sen päälle vadit ja kupit, maljat ja juomauhrikannut; ja ainainen leipä olkoon myös sen päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Sitten he levittäkööt näiden päälle helakanpunaisen vaatteen ja peittäkööt sen sireeninnahkapeitteellä ja asettakoot paikoilleen sen korennot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Ja he ottakoot punasinisen vaatteen ja peittäkööt seitsenhaaraisen lampun lamppuineen, lamppusaksineen, karstakuppeineen ja kaikkine öljyastioineen, joita sen hoitamisessa käytetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Ja he käärikööt sen ja kaiken sen kaluston sireeninnahkapeitteeseen ja pankoot kantopaareille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Ja kultaiselle alttarille he levittäkööt punasinisen vaatteen ja peittäkööt sen sireeninnahkapeitteellä ja asettakoot paikoilleen sen korennot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Ja he ottakoot kaiken jumalanpalveluskaluston, jota pyhäkössä käytetään, ja käärikööt sen punasiniseen vaatteeseen ja peittäkööt sen sireeninnahkapeitteellä ja pankoot kantopaareille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Ja he puhdistakoot tuhasta alttarin sekä levittäkööt sen päälle purppuranpunaisen vaatteen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'ja pankoot sen päälle kaiken kaluston, jota alttarilla käytetään: hiilipannut, haarukat, lapiot ja maljat, kaiken alttarikaluston; ja levittäkööt sen päälle sireeninnahkapeitteen ja asettakoot paikoilleen sen korennot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Ja kun leirin lähtiessä liikkeelle Aaron ja hänen poikansa ovat valmiiksi peittäneet pyhäkön ja pyhäkön kaiken kaluston, niin tulkoot Kehatin pojat kantamaan, mutta älkööt koskeko pyhäkköön, etteivät kuolisi. Tämä on ilmestysmajasta se, mikä on Kehatin poikien kannettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Ja Eleasar, pappi Aaronin poika, pitäköön huolen seitsenhaaraisen lampun öljystä, hyvänhajuisesta suitsukkeesta, jokapäiväisestä ruokauhrista ja voiteluöljystä; hän pitäköön huolen koko asumuksesta ja kaikesta, mitä siinä on, pyhäköstä ja sen kalustosta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Ja Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, '\"Älkää päästäkö kehatilaisten sukuhaaraa häviämään leeviläisten joukosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Näin siis tehkää heille, että he saisivat elää eivätkä kuolisi lähestyessään kaikkeinpyhintä: Aaron ja hänen poikansa menkööt ja asettakoot heidät jokaisen tekemään palvelustehtäväänsä ja kantamaan kannettavaansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'mutta älkööt nämä menkö katsomaan pyhiä esineitä, älkööt silmänräpäykseksikään, etteivät kuolisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, '\"Laske myöskin Geersonin jälkeläisten lukumäärä perhekunnittain ja suvuittain;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'pidä kolmikymmenvuotisten katselmus ja sitä vanhempien, viisikymmenvuotisiin asti, kaikkien, joiden on palveltava toimittamalla palvelusta ilmestysmajassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Geersonilaissukujen tehtävänä palveltaessa ja kannettaessa olkoon tämä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'he kantakoot asumuksen telttakankaan kaistat ja ilmestysmajan, sen peitteen ja sireeninnahkapeitteen, joka on sen päällä päällimmäisenä, sekä ilmestysmajan oven uutimen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'ja asumusta ja alttaria ympäröivän esipihan ympärysverhot ja sen portin uutimen sekä niiden köydet ja kaiken niiden hoitamiseen tarvittavan kaluston; he toimittakoot kaiken, mitä siinä on tehtävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Aaronin ja hänen poikiensa käskyn mukaisesti tapahtukoon kaikki geersonilaisten palvelus, mitä hyvänsä he kantavat ja toimittavatkin, ja antakaa heidän hoitoonsa kaikki heidän kannettavansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Tämä on geersonilaissukujen palvelustehtävä ilmestysmajassa; ja he hoitakoot toimensa Iitamarin, pappi Aaronin pojan, johdolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Pidä Merarin jälkeläisten katselmus suvuittain ja perhekunnittain;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'pidä kolmikymmenvuotisten katselmus ja sitä vanhempien, viisikymmenvuotisiin asti, kaikkien, joiden on palveltava toimittamalla palvelusta ilmestysmajassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Ja nämä ovat uskotut heille kannettaviksi heidän toimittaessaan palvelusta ilmestysmajassa: asumuksen laudat, sen poikkitangot, pylväät ja jalustat');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'sekä ympärillä olevan esipihan pylväät jalustoineen, vaarnoineen ja köysineen, kaikki niiden kalusto ja kaikki, mitä tarvitaan niiden hoitamiseen. Ja antakaa heidän hoitoonsa nimeltä mainittuina ne kalut, joiden kantaminen on heidän tehtävänään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Tämä on merarilaissukujen palvelustehtävä, mitä hyvänsä he toimittavatkin ilmestysmajassa Iitamarin, pappi Aaronin pojan, johdolla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Ja Mooses ja Aaron sekä kansan päämiehet pitivät Kehatin jälkeläisten katselmuksen suvuittain ja perhekunnittain,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'kolmikymmenvuotisten ja sitä vanhempien, aina viisikymmenvuotisiin asti, kaikkien, joiden oli palveltava toimittamalla palvelusta ilmestysmajassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Ja heitä, suvuittain katselmuksessa olleita, oli kaksituhatta seitsemänsataa viisikymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Näin paljon oli kehatilaissuvuista katselmuksessa olleita, kaikkia ilmestysmajassa palvelevia, joiden katselmuksen Mooses ja Aaron pitivät sen käskyn mukaisesti, jonka Herra oli Mooseksen kautta antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Ja Geersonin jälkeläisiä, joiden katselmus pidettiin suvuittain ja perhekunnittain,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'kolmikymmenvuotisia ja sitä vanhempia viisikymmenvuotisiin asti, kaikkia, joiden oli palveltava toimittamalla palvelusta ilmestysmajassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'näitä katselmuksessa olleita oli suvuittain ja perhekunnittain kaksituhatta kuusisataa kolmekymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Näin paljon oli geersonilaisten suvuista katselmuksessa olleita, kaikkia ilmestysmajassa palvelevia, joiden katselmuksen Mooses ja Aaron pitivät Herran käskyn mukaisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Ja merarilaisten suvuista oli niitä, joiden katselmus pidettiin suvuittain ja perhekunnittain,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'kolmikymmenvuotisia ja sitä vanhempia viisikymmenvuotisiin asti, kaikkia, joiden oli palveltava toimittamalla palvelusta ilmestysmajassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'näitä, suvuittain katselmuksessa olleita, oli kolmetuhatta kaksisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Näin paljon oli merarilaisten suvuista katselmuksessa olleita, joista Mooses ja Aaron pitivät katselmuksen sen käskyn mukaisesti, jonka Herra oli Mooseksen kautta antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Kaikkia katselmuksessa olleita leeviläisiä, joiden katselmuksen Mooses ja Aaron ja Israelin päämiehet pitivät suvuittain ja perhekunnittain,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'kolmikymmenvuotisia ja sitä vanhempia, viisikymmenvuotisiin asti, kaikkia, joiden oli palveltava toimittamalla palvelusta ja kantamistyötä ilmestysmajassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'näitä katselmuksessa olleita oli kahdeksantuhatta viisisataa kahdeksankymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Sen käskyn mukaisesti, jonka Herra oli Mooseksen kautta antanut, määrättiin jokaiselle heistä oma palvelustehtävänsä ja kantamistyönsä. Tämän katselmuksen Mooses piti, niinkuin Herra oli häntä käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, '\"Käske israelilaisten karkoittaa leiristä jokainen pitalinen ja jokainen vuotoa sairastava ja jokainen kuolleesta saastunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Karkoittakaa sellaiset, sekä miehet että naiset, leirin ulkopuolelle, etteivät he saastuttaisi leiriään, jossa minä asun heidän keskellänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Ja israelilaiset tekivät niin ja karkoittivat heidät leirin ulkopuolelle; niinkuin Herra oli puhunut Moosekselle, niin israelilaiset tekivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, '\"Puhu israelilaisille: Jos mies tai nainen tekee rikkomuksen minkä tahansa, jonka ihminen tekee menettelemällä uskottomasti Herraa kohtaan, ja niin joutuu vikapääksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'tunnustakoon hän rikkomuksensa, jonka on tehnyt, ja maksakoon velkansa täyteen määrään sekä pankoon siihen lisäksi viidennen osan sen arvosta ja antakoon sen sille, jolle hän on velkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Mutta jos hänellä ei ole sukulunastajaa, jolle velka olisi maksettava, maksettakoon velka Herralle, se on papille, ja sitä paitsi sovitus-oinas, jolla toimitetaan syynalaiselle sovitus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Ja jokainen anti, mikä hyvänsä israelilaisten papille tuomista pyhistä lahjoista, olkoon papin oma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Ja jokaisen pyhät lahjat olkoot papin omat; mitä joku antaa papille, se olkoon papin oma.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, '\"Puhu israelilaisille ja sano heille: jos jonkun miehen vaimo on pettänyt miehensä ja ollut hänelle uskoton');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'ja joku on maannut hänen kanssaan eikä hänen miehensä ole saanut sitä tietää ja vaimo on saanut sen salatuksi, vaikka hän on saastuttanut itsensä, eikä ole todistajaa häntä vastaan eikä häntä ole teosta tavattu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'mutta luulevaisuuden henki on vallannut miehen ja hän luulee vaimoansa, joka onkin saastuttanut itsensä, tahi jos luulevaisuuden henki on vallannut miehen ja hän luulee vaimoansa, vaikka tämä ei ole saastuttanut itseänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'niin tuokoon mies vaimonsa papin eteen ja uhrilahjana hänen puolestaan kymmenennen osan eefa-mittaa ohrajauhoja, mutta älköön hän sen päälle vuodattako öljyä älköönkä panko suitsuketta, sillä se on luulevaisuusuhri, muistutusuhri, joka johdattaa muistoon pahan teon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Ja pappi tuokoon vaimon ja asettakoon hänet Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Ja pappi ottakoon pyhää vettä saviastiaan, ja sitten pappi ottakoon tomua asumuksen lattialta ja pankoon veteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Ja pappi asettakoon vaimon Herran eteen, päästäköön vaimon tukan hajalle ja asettakoon hänen käsiinsä muistutusuhrin, se on luulevaisuusuhrin, ja papin kädessä olkoon katkera kirovesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Ja pappi vannottakoon vaimoa ja sanokoon hänelle: \'Jos ei kukaan ole maannut sinun kanssasi etkä ole pettänyt miestäsi saastuttamalla itseäsi, niin älköön tämä katkera kirovesi sinua vahingoittako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Mutta jos olet pettänyt miehesi ja saastuttanut itsesi ja joku muu kuin miehesi on maannut sinun kanssasi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'niin\' -pappi vannottakoon vaimoa kirovalalla ja pappi sanokoon vaimolle-\'tehköön Herra sinun nimesi kiroukseksi ja sadatukseksi sinun kansasi keskuudessa, kuihduttakoon Herra sinun lanteesi ja paisuttakoon vatsasi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'menköön tämä kirovesi sinun sisuksiisi, niin että vatsasi paisuu ja lanteesi kuihtuvat.\' Ja vaimo sanokoon: \'Amen, Amen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Ja pappi kirjoittakoon nämä kiroukset ja huuhtokoon kirjoituksen kiroveteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Sitten hän juottakoon vaimolla sen katkeran kiroveden, ja menköön kirovesi häneen, tuskaksi hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Ja pappi ottakoon vaimon kädestä luulevaisuusuhrin ja toimittakoon uhrin heilutuksen Herran edessä ja tuokoon sen alttarille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Ja pappi ottakoon uhrista kourallisen alttariuhriosaksi ja polttakoon sen alttarilla ja juottakoon sitten vaimolla veden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Ja kun hän on juottanut vaimolla veden, niin, jos hän on saastuttanut itsensä ja ollut miehelleen uskoton, menee kirovesi häneen, hänelle tuskaksi, ja hänen vatsansa paisuu ja lanteensa kuihtuvat, ja vaimon nimi tulee kiroukseksi hänen kansansa keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Mutta jos vaimo ei ole saastuttanut itseänsä, vaan on puhdas, ei hän vahingoitu, vaan pysyy hedelmällisenä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Tämä on laki luulevaisuudesta. Jos vaimo pettää miehensä ja saastuttaa itsensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'tai jos jonkun valtaa luulevaisuuden henki ja hän luulee vaimoansa, niin hän asettakoon vaimonsa Herran eteen, ja pappi tehköön vaimolle kaiken tämän lain mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Niin mies olkoon syyllisyydestä vapaa, mutta vaimo kantakoon syyllisyytensä.\" 6:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, '\"Puhu israelilaisille ja sano heille: Kun mies tai nainen tekee nasiirilupauksen vihkiytyäksensä Herralle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'niin pidättyköön hän viinistä ja väkijuomasta; älköön juoko hapanviiniä tai hapanta juomaa älköönkä mitään viinirypäleen mehua; älköön syökö tuoreita älköönkä kuivia rypäleitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Niin kauan kuin hänen nasiirilupauksensa kestää, älköön hän syökö mitään, mikä viiniköynnöksestä saadaan, älköön edes raakiloita tai köynnösten versoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Niin kauan kuin hänen nasiirilupauksensa kestää, älköön partaveitsi koskettako hänen päätänsä. Kunnes kuluu umpeen aika, joksi hän on vihkiytynyt Herralle, hän olkoon pyhä ja kasvattakoon päänsä hiukset pitkiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Niin kauan kuin hän on Herralle vihkiytynyt, älköön hän menkö kuolleen luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Älköön hän saastuko edes isästänsä tai äidistänsä, veljestänsä tai sisarestansa heidän kuoltuaan, sillä hänen päässään on Jumalalle-vihkiytymisen merkki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Niin kauan kuin hänen nasiirilupauksensa kestää, hän on pyhä Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Jos joku odottamatta, äkkiarvaamatta kuolee hänen läheisyydessään ja hän niin saastuttaa vihityn päänsä, niin hän ajattakoon hiuksensa puhdistuspäivänään, seitsemäntenä päivänä hän ajattakoon ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Ja kahdeksantena päivänä hän tuokoon kaksi metsäkyyhkystä tai kaksi kyyhkysenpoikaa papille ilmestysmajan ovelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Ja pappi uhratkoon toisen syntiuhriksi ja toisen polttouhriksi ja toimittakoon hänelle sovituksen kuolleen tähden tulleesta rikkomuksesta ja pyhittäköön uudelleen hänen päänsä sinä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Ja hän vihkiytyköön uudelleen Herralle nasiirilupauksensa ajaksi ja tuokoon vuoden vanhan karitsan vikauhriksi. Mutta kulunut aika jääköön lukuunottamatta, koska hän saastutti vihkimyksensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Ja tämä on nasiirilaki: Sinä päivänä, jona hänen nasiirilupauksensa aika on kulunut umpeen, tuotakoon hänet ilmestysmajan ovelle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'ja hän tuokoon uhrilahjanansa Herralle vuoden vanhan virheettömän karitsan polttouhriksi ja vuoden vanhan virheettömän uuhikaritsan syntiuhriksi sekä virheettömän oinaan yhteysuhriksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'ynnä korillisen lestyistä jauhoista leivottuja happamattomia leipiä, öljyyn leivottuja kakkuja ja öljyllä voideltuja happamattomia ohukaisia sekä niihin kuuluvan ruoka-ja juomauhrin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Ja pappi tuokoon ne Herran eteen ja toimittakoon hänen syntiuhrinsa ja polttouhrinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Mutta oinaan hän uhratkoon yhteysuhriksi Herralle ynnä korillisen happamattomia leipiä; ja pappi toimittakoon myös hänen ruoka-ja juomauhrinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Ja nasiiri ajattakoon hiuksensa, vihkiytymisensä merkin, ilmestysmajan ovella ja ottakoon päänsä hiukset, vihkiytymisensä merkin, ja pankoon ne tuleen, joka palaa yhteysuhrin alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Ja pappi ottakoon oinaan keitetyn lavan ja korista happamattoman kakun sekä happamattoman ohukaisen ja pankoon ne nasiirin käsiin, senjälkeen kuin tämä on ajattanut pois vihkiytymisensä merkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Ja pappi toimittakoon niiden heilutuksen Herran edessä. Se olkoon pyhä lahja papille, annettava heilutetun rintalihan ja anniksi annetun reiden lisäksi. Sen jälkeen nasiiri saakoon juoda viiniä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Tämä on laki nasiirista, joka tekee lupauksen, ja hänen uhrilahjastaan, jonka hän uhraa Herralle vihkiytymisensä tähden, sen lisäksi, mitä hän muuten saa hankituksi. Tekemänsä lupauksen mukaan hän menetelköön näin, noudattaen vihkiytymistään koskevaa lakia.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, '\"Puhu Aaronille ja hänen pojillensa ja sano: Siunatessanne israelilaisia sanokaa heille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Herra siunatkoon sinua ja varjelkoon sinua;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Herra valistakoon kasvonsa sinulle ja olkoon sinulle armollinen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Herra kääntäköön kasvonsa sinun puoleesi ja antakoon sinulle rauhan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Näin he laskekoot minun nimeni israelilaisten ylitse, ja minä siunaan heitä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Kun nyt Mooses oli saanut pystytetyksi asumuksen ja oli voidellut sen ja pyhittänyt sen kaikkine kalustoineen ynnä alttarin kaikkine kalustoineen sekä voidellut ja pyhittänyt ne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'niin Israelin ruhtinaat, perhekuntien päämiehet, nimittäin heimoruhtinaat, katselmuksessa olleiden esimiehet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'toivat lahjanansa Herran eteen kuudet katetut vaunut ja kaksitoista raavasta, kaksi ruhtinasta aina yhdet vaunut ja kukin ruhtinas härän; ne he toivat asumuksen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Ja Herra sanoi Moosekselle näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, '\"Ota ne heiltä ilmestysmajan palveluksessa käytettäviksi ja anna ne leeviläisille, kullekin hänen palvelustehtävänsä mukaisesti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Ja Mooses otti vastaan vaunut ja raavaat ja antoi ne leeviläisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Kahdet vaunut ja neljä raavasta hän antoi Geersonin pojille heidän palvelustehtävänsä mukaisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Ja neljät vaunut sekä kahdeksan raavasta hän antoi Merarin pojille sen palvelustehtävän mukaisesti, joka heidän oli suoritettava Iitamarin, pappi Aaronin pojan, johdolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Mutta Kehatin pojille hän ei antanut mitään, koska heidän hoidettavinaan oli pyhät esineet, joita heidän oli olallaan kannettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Ja ruhtinaat toivat vihkiäislahjoja alttaria varten sinä päivänä, jona se voideltiin; ja ruhtinaat toivat lahjansa alttarin eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Ja Herra sanoi Moosekselle: \"Ruhtinaat tuokoot yksitellen, kukin päivänänsä, uhrilahjansa alttarin vihkiäisiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Ensimmäisenä päivänä toi uhrilahjansa Nahson, Amminadabin poika, Juudan sukukunnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Ja hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, ja hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'kauris syntiuhriksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Nahsonin, Amminadabin pojan, uhrilahja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Toisena päivänä Netanel, Suuarin poika, Isaskarin ruhtinas, toi uhrilahjansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Hän toi uhrilahjanansa hopeavadin, sadan kolmenkymmenen sekelin painoisen, hopeamaljan, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'kymmenen sekelin painoisen kultakupin, täynnä suitsuketta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'mullikan, oinaan ja vuoden vanhan karitsan polttouhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'kauriin syntiuhriksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Netanelin, Suuarin pojan, uhrilahja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Kolmantena päivänä Sebulonin jälkeläisten ruhtinas Eliab, Heelonin poika:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,');
