INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'kauris syntiuhriksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Eliabin, Heelonin pojan, uhrilahja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Neljäntenä päivänä Ruubenin jälkeläisten ruhtinas Elisur, Sedeurin poika:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,');
