INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Seitsemäntenä päivänä Efraimin jälkeläisten ruhtinas Elisama, Ammihudin poika:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,');
