INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'kauris syntiuhriksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Gamlielin, Pedasurin pojan, uhrilahja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Yhdeksäntenä päivänä Benjaminin jälkeläisten ruhtinas Abidan, Gideonin poika:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,');
