INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'kauris syntiuhriksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Abidanin, Gideonin pojan, uhrilahja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Kymmenentenä päivänä Daanin jälkeläisten ruhtinas Ahieser, Ammisaddain poika:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'kauris syntiuhriksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Ahieserin, Ammisaddain pojan, uhrilahja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Yhdentenätoista päivänä Asserin jälkeläisten ruhtinas Pagiel, Okranin poika:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'kauris syntiuhriksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Pagielin, Okranin pojan, uhrilahja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Kahdentenatoista päivänä Naftalin jälkeläisten ruhtinas Ahira, Eenanin poika:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'hänen uhrilahjanansa oli hopeavati, sadan kolmenkymmenen sekelin painoinen, hopeamalja, joka painoi seitsemänkymmentä sekeliä pyhäkkösekelin painon mukaan, molemmat täynnä öljyllä sekoitettuja lestyjä jauhoja ruokauhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'kymmenen sekelin painoinen kultakuppi, täynnä suitsuketta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'mullikka, oinas ja vuoden vanha karitsa polttouhriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'kauris syntiuhriksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'ja yhteysuhriksi kaksi raavasta, viisi oinasta, viisi kaurista ja viisi vuoden vanhaa karitsaa. Tämä oli Ahiran, Eenanin pojan, uhrilahja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Nämä olivat ne vihkiäislahjat, jotka Israelin ruhtinaat antoivat alttaria varten sinä päivänä, jona se voideltiin: kaksitoista hopeavatia, kaksitoista maljaa, kaksitoista kultakuppia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'kukin hopeavati sadan kolmenkymmenen sekelin ja kukin malja seitsemänkymmenen sekelin painoinen; näissä astioissa oli siis hopeata yhteensä kaksituhatta neljäsataa sekeliä pyhäkkösekelin painon mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Kultakuppeja oli kaksitoista, täynnä suitsuketta, kukin kuppi kymmenen sekelin painoinen pyhäkkösekelin painon mukaan; kupeissa oli siis kultaa yhteensä sata kaksikymmentä sekeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Polttouhrieläimiä oli yhteensä: kaksitoista härkää, kaksitoista oinasta, kaksitoista vuoden vanhaa karitsaa ynnä niihin kuuluva ruokauhri; ja syntiuhrikauriita oli kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Yhteysuhrieläimiä oli yhteensä: kaksikymmentä neljä härkää, kuusikymmentä oinasta, kuusikymmentä kaurista ja kuusikymmentä vuoden vanhaa karitsaa. Nämä olivat ne vihkiäislahjat, jotka annettiin alttaria varten, sen jälkeen kuin se oli voideltu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Ja kun Mooses meni ilmestysmajaan puhumaan Herran kanssa, kuuli hän äänen, joka puhutteli häntä lain arkin päällä olevalta armoistuimelta, molempien kerubien väliltä; ja Herra puhui hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, '\"Puhu Aaronille ja sano hänelle: Kun nostat lamput paikoilleen, niin valaiskoot ne seitsemän lamppua seitsenhaaraisen lampun edustaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Ja Aaron teki niin; hän nosti lamput valaisemaan seitsenhaaraisen lampun edustaa, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Ja näin oli seitsenhaarainen lamppu tehty: se oli kullasta, kohotakoista tekoa; sen jalka ja kukkalehdetkin olivat kohotakoista tekoa. Aivan sen kaavan mukaan, jonka Herra oli Moosekselle näyttänyt, hän teki seitsenhaaraisen lampun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, '\"Ota leeviläiset israelilaisten keskuudesta ja puhdista heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Ja puhdistaaksesi heidät tee näin: Pirskoita heihin synnistä puhdistavaa vettä, ja ajattakoot he koko ruumiinsa partaveitsellä ja peskööt vaatteensa ja puhdistakoot itsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Ja sitten he ottakoot mullikan sekä siihen kuuluvana ruokauhrina öljyllä sekoitettuja lestyjä jauhoja; ja ota toinen mullikka syntiuhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Tuo sitten leeviläiset ilmestysmajan eteen sekä kokoa kaikki Israelin kansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Ja kun olet tuonut leeviläiset Herran eteen, laskekoot israelilaiset kätensä leeviläisten päälle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'ja Aaron toimittakoon leeviläisille israelilaisten puolesta heilutuksen Herran edessä, että he kelpaisivat Herran palvelukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Mutta leeviläiset laskekoot kätensä mullikkain pään päälle, ja valmista toinen syntiuhriksi ja toinen polttouhriksi Herralle, toimittaaksesi sovituksen leeviläisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Aseta sitten leeviläiset Aaronin ja hänen poikiensa eteen ja toimita heille heilutus Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Erota leeviläiset israelilaisten keskuudesta, että leeviläiset olisivat minun omani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Ja senjälkeen leeviläiset menkööt palvelemaan ilmestysmajaa, kun sinä olet puhdistanut heidät ja toimittanut heille heilutuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Sillä he ovat kokonaan annetut minun omikseni israelilaisten keskuudesta; kaiken sen sijaan, joka avaa äidinkohdun, israelilaisten kaikkien esikoisten sijaan, minä olen heidät ottanut omikseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Sillä jokainen esikoinen israelilaisten keskuudessa, niin ihmisten kuin karjankin, on minun omani; sinä päivänä, jona minä surmasin kaikki Egyptin maan esikoiset, minä pyhitin heidät itselleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Ja minä otin leeviläiset israelilaisten kaikkien esikoisten sijaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Ja minä annoin leeviläiset Aaronille ja hänen pojillensa palvelijoiksi, israelilaisten keskuudesta, suorittamaan israelilaisten puolesta palvelusta ilmestysmajassa ja toimittamaan israelilaisille sovitusta; ja niin israelilaisia ei kohtaa rangaistus siitä, että lähestyvät pyhäkköä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Mooses ja Aaron ja koko Israelin kansa tekivät leeviläisille kaiken, niinkuin Herra oli Moosekselle leeviläisistä käskyn antanut; niin israelilaiset heille tekivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Ja leeviläiset puhdistautuivat synnistä ja pesivät vaatteensa. Ja Aaron toimitti heille heilutuksen Herran edessä, ja Aaron toimitti heille sovituksen heidän puhdistamiseksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Ja senjälkeen leeviläiset menivät toimittamaan palvelustansa ilmestysmajassa Aaronin ja hänen poikiensa edessä. Niinkuin Herra oli Moosekselle leeviläisistä käskyn antanut, niin heille tehtiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, '\"Tämä olkoon voimassa leeviläisistä: Kahdenkymmenen viiden vuoden ikäiset ja sitä vanhemmat menkööt palvelemaan ja toimittamaan palvelusta ilmestysmajassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Mutta viidennestäkymmenennestä ikävuodesta alkaen leeviläinen olkoon palveluksesta vapaa älköönkä enää palvelko,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'vaan auttakoon veljiään ilmestysmajassa heidän tehtäviensä hoitamisessa, mutta palvelusta hän älköön enää toimittako. Järjestä näin leeviläisille heidän tehtävänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Ja Herra puhui Moosekselle Siinain erämaassa toisena vuotena siitä, kun he olivat lähteneet Egyptin maasta, sen vuoden ensimmäisessä kuussa, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, '\"Israelilaiset viettäkööt pääsiäisen määräaikanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Tämän kuukauden neljäntenätoista päivänä, iltahämärässä, viettäkää se määräaikanansa; kaikkien sitä koskevien käskyjen ja säädösten mukaan se viettäkää.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Ja Mooses käski israelilaisten viettää pääsiäistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Niin he viettivät pääsiäisen ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, iltahämärässä, Siinain erämaassa; israelilaiset tekivät kaiken, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Mutta siellä oli miehiä, jotka olivat saastuneet kuolleesta eivätkä voineet viettää pääsiäistä sinä päivänä. Niin he astuivat sinä päivänä Mooseksen ja Aaronin eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Ja miehet sanoivat hänelle: \"Me olemme saastuneet kuolleesta; miksi meidät estetään tuomasta Herralle uhrilahjaa määräaikanansa israelilaisten keskuudessa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Ja Mooses sanoi heille: \"Jääkää tähän, minä menen kuulemaan, mitä Herra teistä säätää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, '\"Puhu israelilaisille näin: Jos joku teistä tai teidän jälkeläisistänne on saastunut kuolleesta tai on kaukana matkalla, viettäköön kuitenkin pääsiäistä Herran kunniaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'viettäkööt sitä toisen kuukauden neljäntenätoista päivänä, iltahämärässä. Happamattoman leivän ja katkerain yrttien kanssa he syökööt pääsiäislampaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Älkööt he jättäkö siitä mitään seuraavaan aamuun älköötkä siitä luuta rikkoko. Kaikkien pääsiäistä koskevien käskyjen mukaan he viettäkööt sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Mutta se mies, joka on puhdas eikä ole matkoilla ja kuitenkin jättää pääsiäisen viettämättä, hävitettäköön kansastansa, koska hän ei tuonut uhrilahjaa Herralle määräaikanansa; se mies joutuu syynalaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Ja jos muukalainen asuu teidän luonanne ja tahtoo viettää pääsiäistä Herran kunniaksi, viettäköön sen pääsiäistä koskevien käskyjen ja säädösten mukaan; samat käskyt olkoot teillä, niin muukalaisella kuin maassa syntyneelläkin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Mutta sinä päivänä, jona asumus pystytettiin, peitti pilvi asumuksen, lain majan, ja illalla näkyi asumuksen päällä niinkuin tulenhohde, ja aina aamuun asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Niin oli aina: pilvi peitti sen päivällä ja tulenhohde yöllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Ja niin usein kuin pilvi kohosi majan päältä, lähtivät israelilaiset liikkeelle; ja mihin pilvi laskeutui, siihen israelilaiset leiriytyivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Herran käskyn mukaan israelilaiset lähtivät liikkeelle, ja Herran käskyn mukaan israelilaiset leiriytyivät. He olivat leiriytyneinä, niin kauan kuin pilvi pysyi asumuksen päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Ja kun pilvi viipyi asumuksen päällä useampia päiviä, noudattivat israelilaiset, mitä Herra oli käskenyt heidän noudattaa, eivätkä lähteneet liikkeelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Mutta joskus pilvi viipyi asumuksen päällä vain muutamia päiviä; silloinkin he Herran käskyn mukaan olivat leiriytyneinä ja lähtivät Herran käskyn mukaan liikkeelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Ja joskus pilvi pysyi paikallaan vain illasta aamuun ja kohosi aamulla; silloinkin he lähtivät liikkeelle. Tahi jos pilvi pysyi päivän ja yön ja sitten kohosi, niin he lähtivät liikkeelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Tahi kun pilvi viipyi pysyen asumuksen päällä pari päivää tai kuukauden tai vielä pitemmän ajan, niin olivat israelilaiset leiriytyneinä eivätkä lähteneet liikkeelle; mutta kun se kohosi, lähtivät he liikkeelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Herran käskyn mukaan he leiriytyivät ja Herran käskyn mukaan he lähtivät liikkeelle. He noudattivat, mitä Herra Mooseksen kautta oli käskenyt heidän noudattaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, '\"Tee itsellesi kaksi hopeatorvea, tee ne kohotakoista tekoa, käyttääksesi niitä kansan kokoonkutsumiseen ja leirien liikkeelle-panemiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Kun niihin molempiin puhalletaan, kokoontukoon sinun luoksesi koko kansa ilmestysmajan oven eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Mutta kun ainoastaan toiseen puhalletaan, kokoontukoot sinun luoksesi ruhtinaat, Israelin heimojen päämiehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Mutta kun puhallatte hälytyssoiton, silloin lähtekööt itään päin leiriytyneet leirit liikkeelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Ja kun toistamiseen puhallatte hälytyssoiton, lähtekööt etelään päin leiriytyneet leirit liikkeelle. Hälytyssoitto puhallettakoon liikkeelle lähdettäessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Mutta seurakuntaa kokoonkutsuttaessa puhaltakaa torveen, hälytyssoittoa soittamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Ja Aaronin pojat, papit, puhaltakoot näitä torvia. Tämä olkoon teille ikuinen säädös sukupolvesta sukupolveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Ja kun te maassanne lähdette taisteluun vihollista vastaan, joka teitä ahdistaa, niin soittakaa torvilla hälytys; silloin te muistutte Herran, teidän Jumalanne, mieleen ja pelastutte vihollisistanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Ja ilopäivinänne sekä juhlinanne ynnä uudenkuun päivinä puhaltakaa torviin uhratessanne poltto-ja yhteysuhrejanne, niin ne saattavat teidän Jumalanne muistamaan teitä. Minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Toisen vuoden toisen kuukauden kahdentenakymmenentenä päivänä pilvi kohosi lain asumuksen päältä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Silloin israelilaiset lähtivät liikkeelle, leiri leirin jälkeen, Siinain erämaasta; ja pilvi pysähtyi Paaranin erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Niin he ensi kerran lähtivät liikkeelle sillä tavoin, kuin Herra oli Mooseksen kautta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Juudan jälkeläisten leirin lippukunta lähti ensimmäisenä joukkona liikkeelle osastoittain, ja tätä osastoa johti Nahson, Amminadabin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Ja Isaskarin jälkeläisten sukukuntaosastoa johti Netanel, Suuarin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Ja Sebulonin jälkeläisten sukukuntaosastoa johti Eliab, Heelonin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Ja kun asumus oli purettu, niin lähtivät liikkeelle Geersonin pojat ja Merarin pojat, jotka kantoivat asumusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Sitten lähti Ruubenin leirin lippukunta liikkeelle osastoittain, ja tätä osastoa johti Elisur, Sedeurin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Ja Simeonin jälkeläisten sukukuntaosastoa johti Selumiel, Suurisaddain poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Ja Gaadin jälkeläisten sukukuntaosastoa johti Eljasaf, Deguelin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Sitten lähtivät kehatilaiset liikkeelle kantaen pyhiä esineitä. Ja asumus pantiin pystyyn, ennenkuin he saapuivat perille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Sitten lähti Efraimin jälkeläisten leirin lippukunta liikkeelle osastoittain, ja tätä osastoa johti Elisama, Ammihudin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Manassen jälkeläisten sukukuntaosastoa johti Gamliel, Pedasurin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Benjaminin jälkeläisten sukukuntaosastoa johti Abidan, Gideonin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Sitten lähti Daanin jälkeläisten leirin lippukunta liikkeelle kaikkien leirien jälkijoukkona, osastoittain, ja tätä osastoa johti Ahieser, Ammisaddain poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Asserin jälkeläisten sukukuntaosastoa johti Pagiel, Okranin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Ja Naftalin jälkeläisten sukukuntaosastoa johti Ahira, Eenanin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Tällainen oli israelilaisten liikkeellelähtö osastoittain; niin he lähtivät liikkeelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Ja Mooses puhui Hoobabille, midianilaisen Reguelin, Mooseksen apen, pojalle: \"Me lähdemme siihen paikkaan, josta Herra on sanonut: \'Sen minä annan teille\'. Lähde meidän kanssamme, niin me palkitsemme sinut hyvin, sillä Herra on luvannut hyvää Israelille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Mutta hän vastasi hänelle: \"En lähde, vaan minä menen omaan maahani ja sukuni luo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Niin Mooses sanoi: \"Älä jätä meitä, sillä sinähän tiedät, mihin meidän sopii leiriytyä erämaassa; rupea siis meille oppaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Jos lähdet meidän kanssamme, niin me annamme sinun saada osasi siitä hyvästä, minkä Herra meille suo.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Niin he lähtivät liikkeelle Herran vuoren luota ja vaelsivat kolme päivänmatkaa. Ja Herran liitonarkki kulki heidän edellänsä kolme päivänmatkaa etsimässä heille levähdyspaikkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Ja Herran pilvi oli heidän päällänsä päivällä, kun he lähtivät leiristä liikkeelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Ja kun arkki lähti liikkeelle, niin Mooses lausui: \"Nouse, Herra, hajaantukoot sinun vihollisesi, ja sinun vihamiehesi paetkoot sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Ja kun arkki laskettiin maahan, lausui hän: \"Palaja, Herra, Israelin heimojen kymmentuhansien tykö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Mutta kansa tuskitteli, ja se oli paha Herran korvissa. Kun Herra sen kuuli, vihastui hän, ja Herran tuli syttyi heidän keskellään, ja se kulutti ulommaisen osan leiriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Silloin kansa huusi Moosesta, ja Mooses rukoili Herraa; niin tuli alkoi sammua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Ja sen paikan nimeksi pantiin Tabeera, koska Herran tuli oli siellä syttynyt heidän keskellään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Mutta heidän keskuuteensa kerääntyneessä hylkyväessä heräsivät himot, ja niin israelilaisetkin rupesivat jälleen itkemään, sanoen: \"Voi jospa meillä olisi lihaa syödäksemme!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Me muistelemme kaloja, joita söimme Egyptissä ilmaiseksi, kurkkuja, melooneja, ruoholaukkaa, sipulia ja kynsilaukkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Mutta nyt me näännymme, sillä eihän täällä ole mitään; emme saa nähdäkään muuta kuin tuota mannaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Ja manna oli korianderin siemenen kaltaista ja bedellion-pihkan näköistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Kansa samoili sitä kokoamassa ja jauhoi sitä käsikivillä tai survoi huhmaressa; sitten he keittivät sitä padassa ja valmistivat siitä kaltiaisia. Ja sen maku oli samanlainen kuin öljyleivoksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Ja kasteen laskeutuessa yöllä leiriin laskeutui mannakin siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Ja Mooses kuuli, kuinka kansa, joka suku, itki, kukin majansa ovella; niin Herra vihastui kovin, ja myös Mooseksen silmissä se oli paha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Ja Mooses sanoi Herralle: \"Miksi olet tehnyt niin pahoin palvelijallesi, ja miksi en ole saanut armoa sinun silmiesi edessä, koska olet pannut kaiken tämän kansan minun taakakseni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Olenko minä kaiken tämän kansan äiti tai isä, koska käsket minua kantamaan sitä sylissäni, niinkuin hoitaja kantaa imeväistä lasta, siihen maahan, jonka olet valalla vannoen luvannut heidän isillensä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Mistä minulla on lihaa antaa kaikelle tälle kansalle, kun he ahdistavat minua itkullaan sanoen: \'Anna meille lihaa syödäksemme\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'En minä jaksa yksinäni kantaa koko tätä kansaa, sillä se on minulle liian raskas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Ja jos näin aiot kohdella minua, niin surmaa minut mieluummin, jos olen saanut armon sinun silmiesi edessä, ja päästä minut näkemästä tätä kurjuutta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Silloin Herra puhui Moosekselle: \"Kutsu kokoon minua varten seitsemänkymmentä miestä Israelin vanhimpia, jotka tiedät kansan vanhimmiksi ja päällysmiehiksi; tuo heidät ilmestysmajalle, ja he asettukoot sinne sinun kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Minä sitten astun alas ja puhun siellä sinun kanssasi ja otan henkeä, joka sinussa on, ja annan heille; siten he voivat auttaa sinua tuon kansataakan kantamisessa, ettei sinun tarvitse sitä yksinäsi kantaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Mutta kansalle sano: Pyhittäytykää huomiseksi, niin saatte syödä lihaa, koska itkitte Herran kuullen, sanoen: \'Voi, jospa meillä olisi lihaa syödäksemme! Egyptissä meidän oli hyvä olla.\' Herra antaa nyt teille lihaa syödäksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Eikä siinä ole teille syömistä ainoastaan päiväksi tai kahdeksi, tai viideksi tai kymmeneksi tai kahdeksikymmeneksi päiväksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'vaan kuukauden päiviksi, kunnes ette enää siedä sen hajua ja se iljettää teitä. Sillä te olette pitäneet halpana Herran, joka on teidän keskellänne, ja itkeneet hänen edessänsä sanoen: \'Miksi lähdimmekään Egyptistä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Mooses vastasi: \"Kuusisataa tuhatta jalkamiestä on sitä kansaa, jonka keskuudessa minä elän, ja kuitenkin sinä sanot: \'Minä annan heille lihaa, niin että heillä on sitä syödä kuukauden päivät\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Onko lampaita ja raavaita teurastettaviksi heille, niin että heille riittää, vai kootaanko heille kaikki meren kalat, niin että heille riittää?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Mutta Herra sanoi Moosekselle: \"Onko Herran käsi lyhyt? Nyt saat nähdä, toteutuuko sinulle minun sanani vai eikö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Niin Mooses meni ulos ja kertoi kansalle Herran sanat. Sitten hän kutsui kokoon seitsemänkymmentä miestä kansan vanhimpia ja asetti heidät majan ympärille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Silloin Herra astui alas pilvessä ja puhutteli häntä, otti henkeä, joka hänessä oli, ja antoi sitä niille seitsemällekymmenelle vanhimmalle. Kun henki laskeutui heihin, niin he joutuivat hurmoksiin, mutta sen jälkeen he eivät enää siihen joutuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Mutta leiriin oli heitä jäänyt kaksi miestä, toisen nimi oli Eldad ja toisen nimi Meedad. Heihinkin henki laskeutui, sillä hekin olivat luetteloon merkityt, vaikka eivät olleet lähteneet majalle; nämä joutuivat leirissä hurmoksiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Silloin riensi muuan nuorukainen ja ilmoitti Moosekselle sanoen: \"Eldad ja Meedad ovat joutuneet hurmoksiin leirissä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Mutta Joosua, Nuunin poika, joka oli ollut Mooseksen palvelija nuoruudestaan asti, puuttui puheeseen sanoen: \"Oi, herrani Mooses, kiellä heitä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Mutta Mooses vastasi hänelle: \"Oletko kateellinen minun puolestani? Oi, jospa koko Herran kansa olisi profeettoja, niin että Herra antaisi henkensä heihin!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Sitten Mooses siirtyi takaisin leiriin ja hänen kanssaan Israelin vanhimmat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Mutta Herran lähettämä tuuli nousi ja ajoi edellään viiriäisiä mereltä päin ja painoi niitä leiriin päivänmatkan laajuudelta joka suunnalle leiristä, lähes kahden kyynärän korkeuteen maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Silloin kansa ryhtyi kokoamaan viiriäisiä ja kokosi niitä koko sen päivän ja koko yön ja koko seuraavan päivän. Vähin määrä, jonka joku sai kootuksi, oli kymmenen hoomer-mittaa. Ja he levittivät niitä pitkin leiriä kuivamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Mutta lihan vielä ollessa heidän hampaissaan, ennenkuin se oli syöty loppuun, syttyi Herran viha kansaa kohtaan, ja Herra tuotti kansalle hyvin suuren surman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Ja sen paikan nimeksi pantiin Kibrot-Hattaava, koska sinne haudattiin kansasta ne, jotka olivat antautuneet halunsa valtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Kibrot-Hattaavasta kansa lähti liikkeelle Haserotia kohti ja pysähtyi Haserotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Mutta Mirjam ja Aaron parjasivat Moosesta etiopialaisen naisen tähden, jonka hän oli ottanut vaimokseen; sillä hän oli ottanut vaimokseen etiopialaisen naisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Ja he sanoivat: \"Ainoastaan Mooseksen kauttako Herra puhuu? Eikö hän puhu myös meidän kauttamme?\" Ja Herra kuuli sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Mutta Mooses oli sangen nöyrä mies, nöyrempi kuin kukaan muu ihminen maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Niin Herra sanoi äkisti Moosekselle ja Aaronille ja Mirjamille: \"Menkää te kaikki kolme ilmestysmajalle\". Ja he menivät kaikki kolme sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Silloin Herra astui alas pilvenpatsaassa, asettui majan ovelle ja kutsui Aaronia ja Mirjamia; molemmat menivät sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Ja Herra sanoi: \"Kuulkaa minun sanani. Jos keskuudessanne on profeetta, niin minä ilmestyn hänelle näyssä, puhun hänen kanssaan unessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Niin ei ole minun palvelijani Mooses, hän on uskollinen koko minun talossani;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'hänen kanssaan minä puhun suusta suuhun, avoimesti enkä peitetyin sanoin, ja hän saa katsella Herran muotoa. Miksi ette siis peljänneet puhua minun palvelijaani Moosesta vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Ja Herran viha syttyi heitä kohtaan, ja hän meni pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Kun pilvi oli poistunut majan päältä, niin katso, Mirjam oli lumivalkea pitalista; ja Aaron kääntyi Mirjamiin päin, ja katso, tämä oli pitalinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Silloin Aaron sanoi Moosekselle: \"Oi, herrani! Älä pane meidän päällemme syntiä, jonka olemme tyhmyydessä tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Älä anna hänen jäädä kuolleen sikiön kaltaiseksi, jonka ruumis on puoleksi mädännyt, kun se äitinsä kohdusta tulee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Silloin Mooses huusi Herran puoleen sanoen: \"Oi, Jumala! Paranna hänet!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Herra vastasi Moosekselle: \"Jos hänen isänsä olisi sylkenyt häntä silmille, eikö hänen olisi ollut hävettävä seitsemän päivää? Olkoon hän nyt suljettuna ulos leiristä seitsemän päivää, ja sitten hän pääsköön takaisin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Niin Mirjam oli suljettuna ulos leiristä seitsemän päivää, eikä kansa lähtenyt liikkeelle, ennenkuin Mirjam oli tuotu takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, '{13:1} Sen jälkeen kansa lähti liikkeelle Haserotista ja leiriytyi Paaranin erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, '\"Lähetä miehiä vakoilemaan Kanaanin maata, jonka minä annan israelilaisille; lähettäkää mies kustakin isien sukukunnasta, ainoastaan niitä, jotka ovat ruhtinaita heidän keskuudessaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Niin Mooses lähetti heidät Paaranin erämaasta Herran käskyn mukaan; kaikki ne miehet olivat israelilaisten päämiehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Ja nämä olivat heidän nimensä: Ruubenin sukukunnasta Sammua, Sakkurin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Simeonin sukukunnasta Saafat, Hoorin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Juudan sukukunnasta Kaaleb, Jefunnen poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Isaskarin sukukunnasta Jigal, Joosefin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Efraimin sukukunnasta Hoosea, Nuunin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Benjaminin sukukunnasta Palti, Raafun poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Sebulonin sukukunnasta Gaddiel, Soodin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Manassen sukukunnasta Joosefin sukukuntaa Gaddi, Suusin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Daanin sukukunnasta Ammiel, Gemallin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Asserin sukukunnasta Setur, Miikaelin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Naftalin sukukunnasta Nahbi, Vofsin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Gaadin sukukunnasta Genuel, Maakin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Nämä olivat niiden miesten nimet, jotka Mooses lähetti maata vakoilemaan. Mutta Mooses kutsui Hoosean, Nuunin pojan, Joosuaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Ja lähettäessään heidät vakoilemaan Kanaanin maata Mooses sanoi heille: \"Lähtekää nyt Etelämaahan ja nouskaa vuoristoon');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'ja katselkaa, minkälainen maa on ja minkälainen kansa, joka siinä asuu, onko se voimakas vai heikko, onko sitä vähän vai paljon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'ja minkälainen maa on, jossa se asuu, onko se hyvä vai huono, ja minkälaiset ne kaupungit ovat, joissa se asuu, avonaisia kyliäkö vai varustettuja kaupunkeja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'ja minkälaista on maa, lihavaa vai laihaa, onko siinä puita vai ei. Ja olkaa rohkealla mielellä ja ottakaa mukaanne sen maan hedelmiä.\" Oli näet se aika, jolloin ensimmäiset rypäleet kypsyivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Niin he lähtivät sinne ja vakoilivat maata Siinin erämaasta Rehobiin asti, josta mennään Hamatiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Ja he lähtivät Etelämaahan ja tulivat Hebroniin, jossa asuivat Ahiman, Seesai ja Talmai, Anakin jälkeläiset. Mutta Hebron oli rakennettu seitsemän vuotta ennen Egyptin Sooania.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Ja he tulivat Rypälelaaksoon; sieltä he leikkasivat viiniköynnöksen, jossa oli rypäleterttu, ja kahden miehen täytyi kantaa sitä korennolla; samoin he ottivat granaattiomenia ja viikunoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Se paikka nimitettiin Rypälelaaksoksi, rypäleen tähden, jonka israelilaiset sieltä leikkasivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Ja he palasivat maata vakoilemasta neljänkymmenen päivän kuluttua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'He vaelsivat ja tulivat Mooseksen, Aaronin ja kaiken Israelin kansan luo Paaranin erämaahan Kaadekseen. Ja he tekivät heille ja kaikelle kansalle selkoa matkastaan ja näyttivät heille sen maan hedelmiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Ja he kertoivat hänelle sanoen: \"Me menimme siihen maahan, jonne meidät lähetit. Ja se tosiaankin vuotaa maitoa ja mettä, ja tällaisia ovat sen hedelmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Mutta kansa, joka siinä maassa asuu, on voimallista, ja kaupungit ovat lujasti varustettuja ja hyvin suuria; näimmepä siellä Anakin jälkeläisiäkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalekilaiset asuvat Etelämaassa ja heettiläiset, jebusilaiset ja amorilaiset asuvat vuoristossa, ja kanaanilaiset asuvat meren rannalla ja Jordanin varsilla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Ja Kaaleb koitti tyynnyttää kansaa napisemasta Moosesta vastaan ja sanoi: \"Menkäämme sittenkin sinne ja ottakaamme se haltuumme, sillä varmasti me sen voitamme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Mutta ne miehet, jotka olivat käyneet hänen kanssaan siellä, sanoivat: \"Emme me kykene käymään sen kansan kimppuun, sillä se on meitä voimakkaampi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Niin he saattoivat israelilaisten keskuudessa pahaan huutoon sen maan, jota olivat olleet vakoilemassa, sanoessaan: \"Se maa, jota olemme kierrelleet ja vakoilleet, on maa, joka syö omat asukkaansa; ja kaikki kansa, jota me siellä näimme, oli kookasta väkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Näimmepä siellä jättiläisiäkin, Anakin jättiläisheimon jälkeläisiä, ja me olimme mielestämme kuin heinäsirkkoja; sellaisia me heistäkin olimme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Silloin koko kansa alkoi huutaa ja parkua, ja kansa itki sen yön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Ja kaikki israelilaiset napisivat Moosesta ja Aaronia vastaan, ja koko kansa sanoi heille: \"Jospa olisimme kuolleet Egyptin maahan tai tähän erämaahan! Jospa olisimme kuolleet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Ja miksi viekään Herra meitä tuohon maahan, jossa me kaadumme miekkaan ja vaimomme ja lapsemme joutuvat vihollisen saaliiksi! Eikö meidän olisi parempi palata Egyptiin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Ja he puhuivat toinen toiselleen: \"Valitkaamme johtaja ja palatkaamme Egyptiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Silloin Mooses ja Aaron lankesivat kasvoilleen Israelin kansan koko seurakunnan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Mutta Joosua, Nuunin poika, ja Kaaleb, Jefunnen poika, jotka olivat olleet mukana maata vakoilemassa, repäisivät vaatteensa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'ja puhuivat kaikelle israelilaisten seurakunnalle näin: \"Maa, jota kävimme vakoilemassa, on ylen ihana maa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Jos Herra on meille suosiollinen, niin hän vie meidät siihen maahan ja antaa sen meille, maan, joka vuotaa maitoa ja mettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Älkää vain kapinoiko Herraa vastaan älkääkä peljätkö sen maan kansaa, sillä heitä ei ole meille kuin suupalaksi. Heidän varjelijansa on väistynyt heistä, mutta meidän kanssamme on Herra. Älkää te heitä peljätkö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Silloin koko seurakunta vaati heitä kivitettäviksi, mutta Herran kirkkaus ilmestyi kaikille israelilaisille ilmestysmajassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Ja Herra sanoi Moosekselle: \"Kuinka kauan tämä kansa pitää minua pilkkanaan eikä usko minuun, huolimatta kaikista tunnusteoista, jotka minä olen tehnyt sen keskuudessa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Minä tuhoan sen rutolla ja hävitän sen perinjuurin, mutta sinusta minä teen suuremman ja väkevämmän kansan, kuin se on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Mutta Mooses sanoi Herralle: \"Ovathan egyptiläiset kuulleet, että sinä voimallasi olet vienyt tämän kansan heidän keskeltänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Ja he ovat puhuneet siitä sen maan asukkaille; hekin siis ovat kuulleet, että sinä, Herra, olet tämän kansan keskellä, sinä Herra, joka olet sille ilmestynyt silmästä silmään, ja että sinun pilvesi pysyy heidän päällänsä ja että sinä kuljet heidän edellänsä pilvenpatsaassa päivin ja tulenpatsaassa öin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Mutta jos sinä nyt surmaat tämän kansan, niinkuin yhden miehen, niin kansat, jotka saavat kuulla sitä kerrottavan sinusta, sanovat näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, '\'Koska Herra ei kyennyt viemään tätä kansaa siihen maahan, jonka hän oli heille valalla vannoen luvannut, tappoi hän heidät erämaahan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Osoittautukoon nyt sinun suuri voimasi, Herra, niinkuin olet puhunut sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, '\'Herra on pitkämielinen ja suuri armossa, hän antaa anteeksi pahat teot ja rikokset, mutta ei jätä niitä rankaisematta, vaan kostaa isien pahat teot lapsille kolmanteen ja neljänteen polveen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Anna siis anteeksi tämän kansan pahat teot suuressa armossasi, niinkuin sinä ennenkin olet anteeksi antanut tälle kansalle, Egyptistä tänne saakka.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Ja Herra vastasi: \"Minä annan anteeksi, niinkuin sinä olet anonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Mutta niin totta kuin minä elän, ja niin totta kuin Herran kirkkaus on täyttävä kaiken maan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'ei kukaan niistä miehistä, jotka ovat nähneet minun kirkkauteni ja minun tunnustekoni, jotka minä olen tehnyt Egyptissä ja tässä erämaassa, mutta kuitenkin nyt jo kymmenen kertaa ovat minua kiusanneet eivätkä ole kuulleet minun ääntäni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'ei yksikään heistä ole näkevä sitä maata, jonka minä valalla vannoen lupasin heidän isillensä; ei yksikään minun pilkkaajistani ole sitä näkevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Mutta koska minun palvelijassani Kaalebissa on toinen henki, niin että hän on minua uskollisesti seurannut, niin hänet minä vien siihen maahan, jossa hän kävi, ja hänen jälkeläisensä saavat sen omakseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Mutta koska amalekilaiset ja kanaanilaiset asuvat laaksoissa, niin kääntykää huomenna toisaanne päin ja painukaa erämaahan, Kaislameren tietä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Ja Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, '\"Kuinka kauan tämä häijy joukko napisee minua vastaan? Minä olen kuullut, kuinka israelilaiset napisevat minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Sano heille: Niin totta kuin minä elän, sanoo Herra, aivan niinkuin te olette minulle puhuneet, niin minä teille teen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Tähän erämaahan kaatuvat teidän ruumiinne, teidän kaikkien, jotka olette katselmuksessa olleet, niin monta kuin teitä on kaksikymmenvuotisia ja sitä vanhempia, jotka olette napisseet minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Totisesti, te ette pääse siihen maahan, jonka minä olen kättä kohottaen luvannut antaa teille asumasijaksi, ei kukaan teistä, paitsi Kaaleb, Jefunnen poika, ja Joosua, Nuunin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Mutta teidän lapsenne, joiden sanoitte joutuvan vihollisen saaliiksi, heidät minä vien sinne, ja he saavat tulla tuntemaan sen maan, jota te halveksitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Mutta teidän ruumiinne kaatuvat tähän erämaahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'ja teidän lastenne täytyy harhailla paimentolaisina tässä erämaassa neljäkymmentä vuotta ja kärsiä teidän uskottomuutenne tähden, kunnes teidän ruumiinne ovat maatuneet tähän erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Niinkuin te neljäkymmentä päivää vakoilitte maata, niin saatte nyt, päivä vuodeksi luettuna, neljäkymmentä vuotta kärsiä pahoista teoistanne ja tulla tuntemaan, mitä se on, että minä käännyn teistä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Minä, Herra, olen puhunut. Totisesti, niin minä teen tälle häijylle kansalle, joka on käynyt kapinoimaan minua vastaan: he hukkuvat tähän erämaahan, tänne he kuolevat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Mutta ne miehet, jotka Mooses oli lähettänyt maata vakoilemaan ja jotka palattuaan olivat saattaneet koko kansan napisemaan häntä vastaan, saattamalla sen maan pahaan huutoon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'ne miehet, jotka olivat saattaneet sen maan pahaan huutoon, kuolivat äkkikuolemalla Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Mutta Joosua, Nuunin poika, ja Kaaleb, Jefunnen poika, jäivät eloon niistä miehistä, jotka olivat käyneet maata vakoilemassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Ja Mooses puhui tämän kaikille israelilaisille. Niin kansa tuli kovin murheelliseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Ja he nousivat varhain seuraavana aamuna lähteäkseen ylös vuoristoon ja sanoivat: \"Katso, tässä me olemme; me lähdemme siihen paikkaan, josta Herra on puhunut, sillä me olemme syntiä tehneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Mutta Mooses sanoi: \"Minkätähden te nyt käytte rikkomaan Herran käskyä? Ei se onnistu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Älkää lähtekö sinne, sillä Herra ei ole teidän keskellänne; älkää lähtekö, etteivät vihollisenne voittaisi teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Sillä amalekilaiset ja kanaanilaiset ovat siellä teitä vastassa, ja niin te kaadutte miekkaan; sillä te olette kääntyneet pois Herrasta, eikä Herra ole teidän kanssanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Yhtäkaikki he lähtivät uppiniskaisuudessaan kulkemaan ylös vuoristoon; mutta ei Herran liitonarkki eikä Mooseskaan siirtynyt leiristä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Silloin amalekilaiset ja kanaanilaiset, jotka siinä vuoristossa asuivat, syöksyivät alas ja voittivat heidät ja hajottivat heidät, ajaen heitä aina Hormaan asti. 15:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, '\"Puhu israelilaisille ja sano heille: Kun te tulette siihen maahan, jonka minä annan teille asuinsijaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'ja uhraatte Herralle uhrin, poltto-tai teurasuhrin, joko lupausta täyttääksenne tai vapaaehtoisena lahjana tai juhlissanne, valmistaaksenne Herralle suloisen tuoksun raavaista tai lampaista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'niin se, joka tuo uhrin, tuokoon lahjanansa Herralle ruokauhriksi kymmenenneksen lestyjä jauhoja, sekoitettuna neljännekseen hiin-mittaa öljyä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'ja juomauhriksi, polttouhrin tai teurasuhrin lisäksi, uhraa neljännes hiin-mittaa viiniä kutakin karitsaa kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Mutta oinaan lisäksi uhraa ruokauhrina kaksi kymmenennestä lestyjä jauhoja, sekoitettuna kolmannekseen hiin-mittaa öljyä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'ja juomauhriksi tuo kolmannes hiin-mittaa viiniä suloiseksi tuoksuksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Mutta kun uhraat mullikan poltto-tai teurasuhriksi, joko lupausta täyttääksesi tai yhteysuhriksi Herralle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'niin tuotakoon mullikan lisäksi ruokauhrina kolme kymmenennestä lestyjä jauhoja, sekoitettuna puoleen hiin-mittaa öljyä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'ja juomauhriksi tuo puoli hiin-mittaa viiniä suloisesti tuoksuvaksi uhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Näin tehtäköön kutakin härkää tai oinasta tai karitsaa tai vohlaa uhrattaessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Niin monta kuin uhrieläimiä on, niin tehkää näin kullekin, niin monta kuin niitä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Jokainen maassa syntynyt tehköön näin, tuodessaan suloisesti tuoksuvan uhrin Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Ja jos muukalainen, joka asuu teidän luonanne tai on ainiaaksi asettunut teidän keskuuteenne, tahtoo uhrata suloisesti tuoksuvan uhrin Herralle, niin hän tehköön, niinkuin tekin teette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Seurakunnassa olkoon laki sama teillä kuin muukalaisellakin, joka asuu teidän luonanne. Tämä olkoon teille ikuinen säädös sukupolvesta sukupolveen. Se, mikä koskee teitä, koskekoon myös muukalaista Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Sama laki ja sama oikeus olkoon sekä teillä että muukalaisella, joka asuu teidän luonanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, '\"Puhu israelilaisille ja sano heille: Kun tulette siihen maahan, johon minä teidät vien,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'niin syödessänne sen maan leipää antakaa Herralle anti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Ensimmäisistä jyvärouheistanne antakaa kakku anniksi; antakaa se, niinkuin puimatantereelta annatte annin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Ensimmäisistä jyvärouheistanne antakaa Herralle anti sukupolvesta sukupolveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Mutta jos erehdyksestä jätätte täyttämättä jonkun näistä käskyistä, jotka Herra on Moosekselle puhunut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'mitä hyvänsä, mistä Herra Mooseksen kautta on teille käskyn antanut, siitä päivästä lähtien, jolloin Herra antoi käskynsä, ja edelleen sukupolvesta sukupolveen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'niin, jos rikkomus tapahtui seurakunnan tietämättä, erehdyksestä, uhratkoon koko seurakunta mullikan polttouhriksi, suloiseksi tuoksuksi Herralle, ynnä siihen kuuluvan ruoka-ja juomauhrin, niinkuin säädetty on, sekä kauriin syntiuhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Kun pappi sitten on toimittanut sovituksen kaikelle israelilaisten seurakunnalle, niin rikkomus annetaan heille anteeksi; sillä se on ollut erehdys ja he ovat tuoneet lahjansa uhriksi Herralle sekä syntiuhrinsa Herran eteen erehdyksensä vuoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Se annetaan silloin anteeksi kaikelle israelilaisten seurakunnalle samoinkuin muukalaiselle, joka asuu heidän keskellänsä; sillä koko kansa on vastuunalainen erehdyksestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Mutta jos joku yksityinen rikkoo erehdyksestä, tuokoon vuoden vanhan vuohen syntiuhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Kun pappi on toimittanut sovituksen sille, joka on erehdyksestä, tahtomattaan, rikkonut Herraa vastaan, kun hän on toimittanut hänelle sovituksen, niin hänelle annetaan anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Sama laki olkoon sekä maassa syntyneillä israelilaisilla että muukalaisella, joka asuu heidän keskellänsä, kun joku rikkoo erehdyksestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Mutta se, joka tahallisesti tekee syntiä, olipa hän maassa syntynyt tai muukalainen, pilkkaa Herraa, ja hänet hävitettäköön kansastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Sillä hän on pitänyt halpana Herran sanan ja rikkonut hänen käskynsä; hänet tuhottakoon, syntivelka painaa häntä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Israelilaisten oleskellessa erämaassa tavattiin mies kokoamassa puita sapatinpäivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Niin ne, jotka hänet tapasivat puita kokoamasta, toivat hänet Mooseksen ja Aaronin ja koko seurakunnan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Ja he panivat hänet vankeuteen, koska ei ollut vielä määrätty, mitä hänelle oli tehtävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Mutta Herra sanoi Moosekselle: \"Se mies rangaistakoon kuolemalla, koko seurakunta kivittäköön hänet leirin ulkopuolella\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Silloin koko seurakunta vei hänet leirin ulkopuolelle, ja he kivittivät hänet kuoliaaksi, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, '\"Puhu israelilaisille ja sano heille, että heidän on sukupolvesta sukupolveen tehtävä itsellensä tupsut viittojensa kulmiin ja sidottava kulmien tupsuihin punasininen lanka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Ne tupsut olkoon teillä, että te, kun ne näette, muistaisitte kaikki Herran käskyt ja ne täyttäisitte ettekä seuraisi sydämenne ettekä silmienne himoja, jotka houkuttelevat teitä haureuteen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'niin muistakaa ja täyttäkää kaikki minun käskyni ja olkaa pyhät Jumalallenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Minä olen Herra, teidän Jumalanne, joka vein teidät pois Egyptin maasta ollakseni teidän Jumalanne. Minä olen Herra, teidän Jumalanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Mutta Koorah, Jisharin poika, joka oli Leevin pojan Kehatin poika, otti Daatanin ja Abiramin, Eliabin pojat, ja Oonin, joka oli Ruubenin pojan Peletin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'ja he nousivat kapinaan Moosesta vastaan, ja heihin yhtyi israelilaisista kaksisataa viisikymmentä miestä, kansan päämiehiä, kansankokouksen jäseniä, arvokkaita miehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Ja he kokoontuivat Moosesta ja Aaronia vastaan ja sanoivat heille: \"Jo riittää! Koko seurakunta, he kaikki, ovat pyhät, ja Herra on heidän keskellänsä. Miksi te siis korotatte itsenne Herran seurakunnan yli?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Kun Mooses sen kuuli, lankesi hän kasvoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Sitten hän puhui Koorahille ja kaikelle hänen joukolleen sanoen: \"Huomenna Herra ilmoittaa, kuka on hänen omansa ja kuka on pyhä ja kenen hän sallii käydä tykönsä. Kenen hän valitsee, sen hän sallii käydä tykönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Tehkää näin: Ottakaa itsellenne hiilipannut, sinä Koorah ja kaikki sinun joukkosi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'ja virittäkää niihin tuli ja pankaa niihin huomenna suitsuketta Herran edessä, niin se mies, jonka Herra silloin valitsee, on pyhä. Riittäköön se teille, te leeviläiset!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Ja Mooses puhui Koorahille: \"Kuulkaa, te leeviläiset!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Eikö teille jo riitä se, että Israelin Jumala on erottanut teidät Israelin seurakunnasta, sallinut teidän käydä hänen tykönsä toimittamaan palvelusta Herran asumuksessa ja seisomaan seurakunnan edessä palvelemassa heitä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Hän salli käydä tykönsä sinun ja kaikkien veljiesi, leeviläisten, sinun kanssasi; ja nyt te tavoittelette pappeuttakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Niin siis sinä ja koko sinun joukkosi käytte kapinoimaan Herraa vastaan; sillä mikä on Aaron, että te häntä vastaan napisette!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Ja Mooses kutsutti Daatanin ja Abiramin, Eliabin pojat. Mutta he sanoivat: \"Emme tule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Eikö jo riitä, että olet tuonut meidät tänne maasta, joka vuotaa maitoa ja mettä, hukuttaaksesi meidät erämaahan? Pyritkö vielä meidän valtiaaksemme?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Oletpa totisesti tuonut meidät maahan, joka vuotaa maitoa ja mettä, ja antanut meille perintöosaksi vainioita ja viinitarhoja! Luuletko voivasi sokaista silmät näiltä ihmisiltä? Me emme tule.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Silloin Mooses vihastui kovin ja sanoi Herralle: \"Älä katso heidän uhrilahjansa puoleen. En ole keneltäkään heistä aasiakaan anastanut enkä kenellekään heistä mitään vääryyttä tehnyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Silloin Mooses sanoi Koorahille: \"Astukaa huomenna Herran eteen, sinä itse ja koko sinun joukkosi, sekä myöskin Aaron,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'ja ottakoon kukin teistä hiilipannunsa ja pankoon siihen suitsuketta sekä tuokoon Herran eteen hiilipannunsa, kaksisataa viisikymmentä hiilipannua; niin ikään sinä ja Aaron tuokaa kumpikin hiilipannunne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Niin he ottivat kukin hiilipannunsa, virittivät niihin tulen ja panivat niihin suitsuketta ja asettuivat ilmestysmajan ovelle; samoin myöskin Mooses ja Aaron.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Mutta Koorah kokosi heitä vastaan koko seurakunnan ilmestysmajan ovelle. Silloin Herran kirkkaus näkyi koko seurakunnalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Ja Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, '\"Erottautukaa te tästä joukosta, niin minä tuokiossa heidät tuhoan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Mutta he lankesivat kasvoillensa ja sanoivat: \"Oi Jumala, sinä Jumala, jonka vallassa on kaiken lihan henki: jos yksi mies rikkoo, vihastutko silloin koko seurakuntaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Niin Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, '\"Puhu seurakunnalle näin: Lähtekää pois Koorahin, Daatanin ja Abiramin asumuksen ympäriltä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Sitten Mooses nousi ja meni Daatanin ja Abiramin luo, ja Israelin vanhimmat seurasivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Ja hän puhui seurakunnalle sanoen: \"Siirtykää pois näiden jumalattomien miesten majoilta älkääkä koskeko mihinkään, mikä on heidän, ettette tuhoutuisi kaikkien heidän syntiensä tähden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Niin he lähtivät pois Koorahin, Daatanin ja Abiramin asumuksen ympäriltä. Mutta Daatan ja Abiram olivat tulleet ulos ja asettuneet majojensa ovelle vaimoinensa ja suurine ja pienine lapsinensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Ja Mooses puhui: \"Tästä te tietäkää, että Herra on minut lähettänyt tekemään kaikki nämä teot ja etteivät ne ole tapahtuneet minun omasta tahdostani:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'jos nämä kuolevat samalla tavalla, kuin muut ihmiset kuolevat, ja heidän käy, niinkuin kaikkien muiden ihmisten käy, niin ei Herra ole minua lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Mutta jos Herra antaa jotakin erikoista tapahtua ja maa avaa kitansa ja nielaisee heidät kaikkinensa, niin että he elävältä suistuvat tuonelaan, niin siitä tietäkää, että nämä miehet ovat pilkanneet Herraa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Tuskin oli hän saanut kaiken tämän sanotuksi, niin maa halkesi heidän altansa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'ja maa avasi kitansa ja nielaisi heidät, heidän asuntonsa, kaiken Koorahin väen ja kaikki heidän tavaransa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Ja he suistuivat kaikkinensa elävältä tuonelaan, ja maa peitti heidät; ja niin heidät hävitettiin seurakunnan keskeltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Ja koko Israel, joka oli heidän ympärillänsä, pakeni kuullessaan heidän huutonsa, sillä he pelkäsivät maan nielaisevan heidätkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Mutta tuli lähti Herran tyköä ja kulutti ne kaksisataa viisikymmentä miestä, jotka olivat tuoneet suitsutusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, '\"Käske Eleasaria, pappi Aaronin poikaa, korjaamaan nuo hiilipannut palosta, mutta pudistamaan tuli niistä kauas,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'sillä ne ovat tulleet pyhäkön omiksi. Noiden henkensä menettäneiden syntisten hiilipannuista takokaa ohuita levyjä alttarin päällystämiseksi; sillä he toivat ne Herran eteen, ja niin ne tulivat pyhäkön omiksi ja merkiksi israelilaisille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Niin pappi Eleasar otti ne vaskiset hiilipannut, jotka nuo tulen polttamat miehet olivat tuoneet, ja ne taottiin alttarin päällystykseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'muistuttamaan israelilaisille, ettei kukaan syrjäinen, joka ei ole Aaronin sukua, lähestyisi polttamaan suitsuketta Herran edessä, niin ettei hänen kävisi samoin kuin Koorahin ja hänen joukkonsa, niinkuin Herra oli hänelle Mooseksen kautta puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'Mutta seuraavana päivänä kaikki israelilaisten seurakunta napisi Moosesta ja Aaronia vastaan sanoen: \"Te olette surmanneet Herran kansaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'Mutta kun kansa kokoontui Moosesta ja Aaronia vastaan, niin he kääntyivät ilmestysmajaan päin, ja katso, pilvi peitti sen, ja Herran kirkkaus näkyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'Silloin Mooses ja Aaron menivät ilmestysmajan edustalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, '\"Poistukaa tämän joukon luota, niin minä tuokiossa heidät tuhoan\". Silloin he lankesivat kasvoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Ja Mooses sanoi Aaronille: \"Ota hiilipannu ja viritä siihen tuli alttarilta, pane siihen suitsuketta ja vie se nopeasti seurakunnan luo ja toimita heille sovitus, sillä viha on lähtenyt liikkeelle Herran tyköä, vitsaus on jo alkanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Ja Aaron teki, niinkuin Mooses oli käskenyt, ja riensi seurakunnan keskelle, ja katso, vitsaus oli jo alkanut kansan keskuudessa. Silloin hän suitsutti ja toimitti kansalle sovituksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'Ja hänen siinä seisoessaan kuolleitten ja elävien vaiheella vitsaus taukosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Mutta niitä, jotka vitsauksesta kuolivat, oli neljätoista tuhatta seitsemänsataa henkeä, paitsi niitä, jotka saivat surmansa Koorahin tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Sitten Aaron palasi takaisin Mooseksen luo ilmestysmajan ovelle, ja vitsaus oli tauonnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, '\"Puhu israelilaisille ja ota heiltä, kaikilta heidän ruhtinailtansa, sauva kutakin sukukuntaa kohti, heidän sukukuntiensa mukaan, kaksitoista sauvaa. Kirjoita kunkin nimi hänen sauvaansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'mutta Leevin sauvaan kirjoita Aaronin nimi, sillä tämänkin sukukunnan päämiehellä olkoon sauvansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Pane ne sitten ilmestysmajaan lain arkin eteen, missä minä teille ilmestyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Ja tapahtuu, että kenen minä valitsen, sen sauva versoo. Siten minä lopetan israelilaisten napinan, niin että pääsen kuulemasta heidän napinaansa teitä vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Ja Mooses puhui tämän israelilaisille, ja kaikki heidän ruhtinaansa antoivat hänelle kukin sauvansa sukukunnittain, yhteensä kaksitoista sauvaa, ja Aaronin sauva oli heidän sauvainsa joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Ja Mooses pani sauvat lain majaan, Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Kun Mooses seuraavana päivänä meni lain majaan, niin katso, Aaronin sauva, joka oli siinä Leevin sukukunnan puolesta, oli alkanut versoa, siihen oli ilmestynyt silmuja, puhjennut kukkia ja kasvanut kypsiä manteleita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Ja Mooses vei ulos kaikki sauvat Herran kasvojen edestä kaikkien israelilaisten tykö; ja he katselivat niitä ja ottivat kukin sauvansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Ja Herra sanoi Moosekselle: \"Vie Aaronin sauva takaisin lain arkin eteen säilytettäväksi merkkinä uppiniskaisille, ja lopeta heidän napinansa, niin että minä pääsen sitä kuulemasta, jotta he eivät kuolisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Ja Mooses teki sen; niinkuin Herra häntä käski, niin hän teki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Mutta israelilaiset sanoivat Moosekselle näin: \"Katso, me menehdymme, me hukumme, kaikki me hukumme!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Kuka vain lähestyy, kuka ikinä lähestyy Herran asumusta, se kuolee! Onko meidän kaikkien hukkuminen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Ja Herra sanoi Aaronille: \"Sinun ja sinun poikiesi, isäsi suvun sinun kanssasi, on kannettava pyhäkköä vastaan tehdyt rikkomukset; samoin sinun ja poikiesi sinun kanssasi on kannettava pappeutta vastaan tehdyt rikkomukset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Mutta salli myös veljiesi, Leevin sukukunnan, isäsi heimon, käydä sinun kanssasi sinne. He liittykööt sinuun ja palvelkoot sinua, kun sinä ja poikasi sinun kanssasi toimitatte palvelusta lain majan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Ja he hoitakoot sekä sinun tehtäviäsi että kaikkia majan tehtäviä, mutta älkööt lähestykö pyhiä esineitä tai alttaria, etteivät kuolisi, niin he kuin tekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Liittykööt he sinuun ja hoitakoot ilmestysmajan tehtävät, majan kaikki palvelustehtävät; mutta syrjäinen älköön teitä lähestykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Ja teidän on hoidettava tehtävät pyhäkössä ja alttarilla, ettei Herran viha enää kohtaisi israelilaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Ja katso, minä olen ottanut teidän veljenne, leeviläiset, israelilaisten keskuudesta teille lahjaksi, Herralle annettuina toimittamaan palvelusta ilmestysmajassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Mutta sinä ja poikasi sinun kanssasi hoitakaa papinvirkaanne, pitäen huolta kaikista alttarilla ja esiripun sisäpuolella suoritettavista tehtävistä, ja toimittakaa palvelusta siellä. Lahjana minä annan teille papinvirkanne; mutta syrjäinen, joka siihen ryhtyy, surmattakoon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Ja Herra puhui Aaronille: \"Katso, minä annan sinulle sen, mikä saamistani anneista on talteen otettava; kaikista israelilaisten pyhistä lahjoista minä annan sen sinulle osuudeksi ja sinun pojillesi ikuiseksi oikeudeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Korkeasti-pyhistä lahjoista olkoon sinun omasi tämä, jota ei tulessa polteta: kaikki ne heidän uhrilahjansa, jotka kuuluvat kaikkiin heidän ruokauhreihinsa, syntiuhreihinsa ja vikauhreihinsa, joita he suorittavat minulle korvauksena; se on korkeasti-pyhää ja olkoon sinun ja sinun poikiesi oma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Syökää se korkeasti-pyhässä paikassa; jokainen miehenpuoli saakoon syödä sitä. Olkoon se sinulle pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Ja antina heidän lahjoistansa olkoon sinun omasi tämä: kaiken sen, minkä israelilaiset uhraavat heilutusmenoin, minä annan sinulle, sinun pojillesi ja tyttärillesi ikuiseksi oikeudeksi; jokainen, joka on puhdas sinun perheessäsi, saakoon syödä sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Kaiken parhaan öljyn ja kaiken parhaan viinin ja viljan, minkä he uutisena antavat Herralle, sen minä annan sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Uutiset kaikesta, mitä heidän maassansa kasvaa ja minkä he tuovat Herralle, olkoot sinun omasi; jokainen, joka on puhdas sinun perheessäsi, saakoon syödä niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Kaikki, mitä Israelissa vihittyä on, olkoon sinun omaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Kaikki, mikä avaa äidinkohdun, mikä elollinen hyvänsä, joka tuodaan Herralle, ihmisistä tai karjasta, olkoon sinun omasi; lunastuta kuitenkin ihmisen esikoinen samoinkuin saastaisen eläimen esikoinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Ja mitä heidän lunastamiseensa tulee, niin lunastuta heidät kuukauden ikäisistä alkaen sinun asettamastasi viiden sekelin arviohinnasta pyhäkkösekelin painon mukaan, sekeli kaksikymmentä geeraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Mutta raavaan tai lampaan tai vuohen esikoista älä lunastuta; ne ovat pyhiä. Vihmo niiden veri alttarille ja polta niiden rasva uhriksi, suloiseksi tuoksuksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Mutta niiden liha olkoon sinun omasi; niinkuin heilutettu rintalihakin ja oikea reisi olkoon se sinun omasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Kaikki pyhät annit, joita israelilaiset antavat Herralle, minä annan sinulle, sinun pojillesi ja tyttärillesi ikuiseksi oikeudeksi. Se olkoon ikuinen suolaliitto Herran edessä sinulle ja sinun jälkeläisillesi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Ja Herra puhui Aaronille: \"Sinulla älköön olko perintöosaa heidän maassansa älköönkä osuutta heidän keskellänsä; minä itse olen sinun osuutesi ja perintöosasi israelilaisten keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Mutta leeviläisille minä annan kaikki kymmenykset Israelissa perintöosaksi, palkkana siitä palveluksesta, jonka he toimittavat ilmestysmajassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Älköötkä muut israelilaiset enää lähestykö ilmestysmajaa, että he eivät joutuisi syynalaisiksi ja kuolisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Ainoastaan leeviläiset toimittakoot palvelusta ilmestysmajassa ja kantakoot tehdyt rikkomukset; se olkoon teille ikuinen säädös sukupolvesta sukupolveen. Mutta heillä älköön olko perintöosaa israelilaisten keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Sillä israelilaisten kymmenykset, jotka he antavat Herralle anniksi, minä annan leeviläisille perintöosaksi; sentähden minä kiellän heiltä perintöosan israelilaisten keskuudessa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, '\"Puhu leeviläisille ja sano: Kun te israelilaisilta otatte ne kymmenykset, jotka minä olen määrännyt heidän teille annettavaksi perintöosaksenne, niin antakaa siitä Herralle anti, kymmenykset kymmenyksistä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'ja se katsotaan teidän anniksenne, niinkuin puimatantereelta annetut jyvät tai kuurnasta tullut mehu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Niin antakaa tekin Herralle anti kaikista kymmenyksistä, jotka te saatte israelilaisilta, ja tämä Herralle niistä tuleva anti antakaa pappi Aaronille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Kaikista saamistanne lahjoista antakaa Herralle täysi anti; kaikesta, mikä parasta on, antakaa pyhä lahja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Ja sano heille: Kun te siitä annatte parhaimman osan, niin se katsotaan leeviläisten anniksi niinkuin puimatantereen tai kuurnan sato.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Ja sen saatte te ja teidän perheenne syödä missä hyvänsä, sillä se on teille palkka palveluksestanne ilmestysmajassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Kun te näin annatte siitä anniksi parhaimman osan, ette joudu syynalaisiksi ettekä saastuta israelilaisten pyhiä lahjoja ettekä kuole.\" 19:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Ja Herra puhui Moosekselle ja Aaronille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, '\"Tämä on lakimääräys, jonka Herra sääsi sanoen: Käske israelilaisia tuomaan sinulle ruskeanpunainen, virheetön hieho, jossa ei ole mitään vammaa ja jonka päälle iestä ei vielä ole pantu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Antakaa se pappi Eleasarin haltuun, ja vietäköön se leiristä ulos ja teurastettakoon hänen edessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Sitten pappi Eleasar ottakoon sen verta sormeensa ja pirskoittakoon sen verta ilmestysmajan etupuolta kohti seitsemän kertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Ja hieho poltettakoon hänen nähtensä; nahkoinensa, lihoinensa ja verinensä ynnä rapoinensa se poltettakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Mutta pappi ottakoon setripuuta, isoppikorren ja helakanpunaista lankaa ja viskatkoon ne tuleen, missä hieho palaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Sitten pappi pesköön vaatteensa ja pesköön ruumiinsa vedessä; sitten menköön leiriin. Mutta pappi olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Sekin, joka hiehon poltti, pesköön vaatteensa vedessä ja pesköön ruumiinsa vedessä ja olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Sitten joku, joka on puhdas, kootkoon hiehon tuhan ja pankoon sen talteen leirin ulkopuolelle puhtaaseen paikkaan. Ja säilytettäköön se israelilaisten seurakunnalle puhdistusvettä varten. Tämä on syntiuhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Ja joka hiehon tuhan kokosi, pesköön vaatteensa ja olkoon saastainen iltaan asti. Tämä olkoon israelilaisille ja muukalaiselle, joka asuu heidän keskellänsä, ikuinen säädös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Joka koskee kuolleen ihmisen ruumiiseen, kenen hyvänsä, olkoon saastainen seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Hän puhdistakoon itsensä tällä vedellä kolmantena ja seitsemäntenä päivänä, niin hän tulee puhtaaksi. Mutta jos hän ei puhdistaudu kolmantena ja seitsemäntenä päivänä, niin hän ei tule puhtaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Jokainen, joka koskee kuolleeseen, kuolleen ihmisen ruumiiseen, eikä puhdistaudu, hän saastuttaa Herran asumuksen, ja hänet hävitettäköön Israelista, koska puhdistusvettä ei ole vihmottu häneen; hän on saastainen, hänen saastaisuutensa pysyy hänessä yhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Tämä on laki: Kun joku kuolee telttamajassa, niin jokainen, joka menee siihen majaan, ja jokainen, joka on siinä majassa, olkoon saastainen seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Ja jokainen avoin astia, johon ei ole peitettä sidottu, olkoon saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Ja jokainen, joka ulkona kedolla koskee miekalla surmattuun tai muulla tavoin kuolleeseen tai ihmisluuhun tai hautaan, olkoon saastainen seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Mutta näin saastunutta varten otettakoon poltetun syntiuhrin tuhkaa ja kaadettakoon sen päälle astiaan raikasta vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Ottakoon sitten joku, joka on puhdas, isoppikorren ja kastakoon sen siihen veteen ja pirskoittakoon sitä tuohon majaan ja kaikkiin sen esineihin ja ihmisiin, jotka siellä olivat, samoinkuin siihen, joka on koskenut luuhun tai surmattuun tai muulla tavoin kuolleeseen tai hautaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Ja se puhdas pirskoittakoon sitä saastuneeseen kolmantena ja seitsemäntenä päivänä ja puhdistakoon hänet seitsemäntenä päivänä. Sitten hän pesköön vaatteensa ja peseytyköön vedessä, niin hän tulee illalla puhtaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Mutta joka on saastunut eikä puhdistaudu, se hävitettäköön seurakunnasta, koska hän on saastuttanut Herran pyhäkön eikä puhdistusvettä ole vihmottu häneen; hän on saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Ja tämä olkoon heille ikuinen säädös. Mutta puhdistusveden pirskoittaja pesköön vaatteensa, ja se, joka koskee puhdistusveteen, olkoon saastainen iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Ja kaikki, mihin saastunut koskee, olkoon saastaista, ja se, joka koskee häneen, olkoon saastainen iltaan asti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Senjälkeen israelilaiset, koko seurakunta, tulivat Siinin erämaahan ensimmäisenä kuukautena, ja kansa asettui Kaadekseen. Siellä Mirjam kuoli, ja hänet haudattiin sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Mutta kansalla ei ollut vettä; niin he kokoontuivat Moosesta ja Aaronia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Ja kansa riiteli Moosesta vastaan ja sanoi näin: \"Jospa mekin olisimme hukkuneet silloin, kun veljemme hukkuivat Herran edessä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Minkätähden toitte Herran seurakunnan tähän erämaahan, kuollaksemme karjoinemme tänne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Ja minkätähden johdatitte meidät pois Egyptistä tuodaksenne meidät tähän pahaan paikkaan, jossa ei kasva viljaa eikä viikunoita, ei viiniköynnöksiä eikä granaattiomenia, ja jossa ei ole vettä juoda?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Mutta Mooses ja Aaron menivät seurakunnan luota ilmestysmajan ovelle ja lankesivat kasvoilleen. Silloin näkyi Herran kirkkaus heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, '\"Ota sauva ja kokoa seurakunta, sinä ja veljesi Aaron, ja puhukaa heidän silmiensä edessä kalliolle, niin se antaa vettä, ja sinä saat vettä tulemaan heille kalliosta ja juotat joukon ja sen karjan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Niin Mooses otti sauvan Herran kasvojen edestä, niinkuin hän oli häntä käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Ja Mooses ja Aaron kokosivat seurakunnan kallion eteen, ja hän sanoi heille: \"Kuulkaa nyt, te niskurit! Onko meidän saatava teille vettä tästä kalliosta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Niin Mooses nosti kätensä ja iski kalliota kahdesti sauvallansa, ja siitä lähti runsaasti vettä, niin että kansa ja sen karja saivat juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Mutta Herra sanoi Moosekselle ja Aaronille: \"Koska ette uskoneet minuun ettekä pitäneet minua pyhänä israelilaisten silmien edessä, niin te ette saa viedä tätä seurakuntaa siihen maahan, jonka minä heille annan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Tämä oli Meriban vesi, jonka luona israelilaiset riitelivät Herraa vastaan ja hän näytti heille pyhyytensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Mutta Mooses lähetti Kaadeksesta sanansaattajat Edomin kuninkaan tykö sanomaan: \"Näin sanoo veljesi Israel: Sinä tunnet kaiken vaivan, joka on meitä kohdannut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'kuinka isämme lähtivät Egyptiin, kuinka olemme asuneet Egyptissä kauan aikaa ja kuinka egyptiläiset kohtelivat pahoin meitä ja meidän isiämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Mutta me huusimme Herran puoleen, ja hän kuuli meidän huutomme ja lähetti enkelin, joka vei meidät pois Egyptistä. Ja katso, me olemme nyt Kaadeksessa, kaupungissa, joka on sinun maasi rajalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Salli meidän kulkea maasi läpi. Me emme kulje peltojen emmekä viinitarhojen poikki emmekä juo vettä kaivoista. Poikkeamatta oikealle tai vasemmalle me kuljemme valtatietä, kunnes olemme päässeet alueesi läpi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Mutta Edom vastasi hänelle: \"Älä kulje minun maani läpi; muutoin minä käyn miekka kädessä sinua vastaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Mutta israelilaiset sanoivat hänelle: \"Maantietä me kuljemme, ja jos juomme vettäsi, me tai meidän karjamme, niin me maksamme sen, kun vain saamme jalkaisin kulkea sinun maasi läpi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Mutta hän vastasi: \"Tästä et kulje!\" Ja Edom lähti häntä vastaan suurella sotajoukolla ja vahvasti varustettuna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Kun siis Edom kielsi Israelia kulkemasta maansa läpi, niin Israel väistyi sieltä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Ja he lähtivät liikkeelle Kaadeksesta. Ja israelilaiset, koko kansa, tulivat Hoorin vuorelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Mutta Herra sanoi Moosekselle ja Aaronille Hoorin vuorella, Edomin maan rajalla, näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, '\"Aaron otetaan nyt pois heimonsa tykö, sillä hän ei pääse siihen maahan, jonka minä annan israelilaisille, koska te niskoittelitte minun käskyäni vastaan Meriban veden luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Ota Aaron ja hänen poikansa Eleasar ja vie heidät Hoorin vuorelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Ja riisu Aaronilta vaatteet ja pue ne hänen poikansa Eleasarin ylle. Aaron otetaan pois ja kuolee siellä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Ja Mooses teki, niinkuin Herra oli käskenyt; ja he nousivat Hoorin vuorelle koko kansan silmien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Ja Mooses riisui Aaronilta vaatteet ja puki ne hänen poikansa Eleasarin ylle. Niin Aaron kuoli siellä vuoren huipulla, mutta Mooses ja Eleasar astuivat alas vuorelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Ja kun koko kansa sai tietää, että Aaron oli kuollut, niin he itkivät Aaronia kolmekymmentä päivää, koko Israelin heimo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Mutta kun Aradin kuningas, kanaanilainen, joka asui Etelämaassa, kuuli, että Israel oli tulossa Atarimin tietä, ryhtyi hän sotimaan Israelia vastaan ja otti muutamia heistä vangiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Silloin Israel teki lupauksen Herralle ja sanoi: \"Jos sinä annat tämän kansan minun käsiini, niin minä vihin sen kaupungit tuhon omiksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Ja Herra kuuli, mitä Israel lausui, ja jätti kanaanilaiset hänen käsiinsä. Niin Israel vihki heidät ja heidän kaupunkinsa tuhon omiksi. Ja sen paikan nimeksi pantiin Horma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Senjälkeen he lähtivät liikkeelle Hoorin vuorelta Kaislameren tietä kiertääksensä Edomin maan. Mutta matkalla kansa kävi kärsimättömäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Ja kansa puhui Jumalaa ja Moosesta vastaan: \"Minkätähden te johdatitte meidät pois Egyptistä kuolemaan erämaahan? Eihän täällä ole leipää eikä vettä, ja me olemme kyllästyneet tähän huonoon ruokaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Silloin Herra lähetti kansan sekaan myrkkykäärmeitä, jotka purivat kansaa, niin että paljon kansaa Israelista kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Niin kansa tuli Mooseksen luo, ja he sanoivat: \"Me teimme syntiä, kun puhuimme Herraa ja sinua vastaan. Rukoile Herraa, että hän poistaa käärmeet meidän kimpustamme.\" Ja Mooses rukoili kansan puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Silloin Herra sanoi Moosekselle: \"Tee itsellesi käärme ja pane se tangon päähän, niin jokainen purtu, joka siihen katsoo, jää eloon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Niin Mooses teki vaskikäärmeen ja pani sen tangon päähän; jos ketä käärmeet sitten purivat ja tämä katsoi vaskikäärmeeseen, niin hän jäi eloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Sitten israelilaiset lähtivät liikkeelle ja leiriytyivät Oobotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Ja he lähtivät liikkeelle Oobotista ja leiriytyivät Iije-Abarimiin siinä erämaassa, joka on Mooabista itään, auringon nousun puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Sieltä he lähtivät liikkeelle ja leiriytyivät Seredin laaksoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Sieltä he lähtivät liikkeelle ja leiriytyivät erämaahan tuolle puolelle Arnon-jokea, joka lähtee amorilaisten alueelta; sillä Arnon on Mooabin rajana Mooabin ja amorilaisten maan välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Sentähden sanotaan \"Herran sotien kirjassa\": \"Vaaheb Suufassa ja Arnonin laaksot');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'ja laaksojen rinteet, jotka ulottuvat Aarin tienoille ja kallistuvat Mooabin rajaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Ja sieltä he kulkivat Beeriin. Se oli se kaivo, josta Herra oli sanonut Moosekselle: \"Kokoa kansa, niin minä annan heille vettä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Silloin lauloi Israel tämän laulun: \"Kuohu, kaivo! -laulakaa sille laulu-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'kaivo, jonka ruhtinaat kaivoivat, kansan parhaat koversivat valtikallaan, sauvoillansa!\" Ja siitä erämaasta he kulkivat Mattanaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'ja Mattanasta Nahalieliin ja Nahalielista Baamotiin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'ja Baamotista siihen laaksoon, joka on Mooabin maassa, Pisgan huipun juurella, joka kohoaa yli erämaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Ja Israel lähetti sanansaattajat Siihonin, amorilaisten kuninkaan, tykö sanomaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, '\"Salli minun kulkea maasi läpi. Me emme poikkea pelloille emmekä viinitarhoihin emmekä juo vettä kaivoista. Valtatietä me kuljemme, kunnes olemme päässeet sinun alueesi läpi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Mutta Siihon ei sallinut Israelin kulkea alueensa läpi, vaan kokosi kaiken väkensä ja lähti Israelia vastaan erämaahan. Ja kun hän oli tullut Jahaaseen, ryhtyi hän taisteluun Israelia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Mutta Israel voitti hänet miekan terällä ja valloitti hänen maansa Arnonista Jabbokiin, aina ammonilaisten maahan asti, sillä ammonilaisten raja oli varustettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Ja Israel valtasi sieltä kaikki kaupungit; ja Israel asettui kaikkiin amorilaisten kaupunkeihin, Hesboniin ja kaikkiin sen tytärkaupunkeihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Sillä Hesbon oli amorilaisten kuninkaan Siihonin kaupunki; hän oli näet käynyt sotaa entistä Mooabin kuningasta vastaan sekä vallannut häneltä kaiken hänen maansa Arnoniin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Sentähden runosepät sanovat: \"Tulkaa Hesboniin! Rakennettakoon ja varustettakoon Siihonin kaupunki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Sillä tuli lähti Hesbonista, liekki Siihonin kaupungista; se kulutti Aar-Mooabin, Arnonin kukkulain valtiaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Voi sinua, Mooab! Sinä hukuit, Kemoksen kansa! Poikiensa hän salli tulla pakolaisiksi, tytärtensä amorilaisten kuninkaan Siihonin vangeiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Me ammuimme heidät, Hesbon kukistui Diibonia myöten; me hävitimme Noofahiin asti, aina Meedebaan saakka.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Niin Israel asettui amorilaisten maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Ja Mooses lähetti vakoilemaan Jaeseria, ja he valloittivat sen tytärkaupungit; ja hän karkoitti amorilaiset, jotka siellä olivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Sitten he kääntyivät toisaalle ja kulkivat Baasanin tietä. Silloin lähti Oog, Baasanin kuningas, heitä vastaan, hän ja kaikki hänen väkensä, Edreihin taistelemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Mutta Herra sanoi Moosekselle: \"Älä pelkää häntä, sillä minä annan sinun käteesi hänet ja kaiken hänen kansansa ja maansa. Ja tee hänelle, niinkuin teit Siihonille, amorilaisten kuninkaalle, joka asui Hesbonissa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Ja he voittivat hänet ja hänen poikansa ja kaiken hänen väkensä, päästämättä pakoon ainoatakaan. Niin he valloittivat hänen maansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Sitten israelilaiset lähtivät liikkeelle ja leiriytyivät Mooabin arolle, Jordanin tuolle puolelle, Jerikon kohdalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Mutta Baalak, Sipporin poika, näki kaiken, mitä Israel oli tehnyt amorilaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Ja Mooab pelkäsi tätä kansaa suuresti, kun sitä oli niin paljon; ja Mooab kauhistui israelilaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Mooab sanoi Midianin vanhimmille: \"Nyt tuo lauma syö puhtaaksi kaiken meidän ympäriltämme, niinkuin härkä syö kedon vihannuuden\". Ja Baalak, Sipporin poika, oli Mooabin kuninkaana siihen aikaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Hän lähetti sanansaattajat Bileamin, Beorin pojan, tykö Petoriin, joka on Eufrat-virran varrella, heimolaistensa maahan, kutsumaan häntä ja käski sanoa hänelle: \"Katso, Egyptistä on lähtenyt liikkeelle kansa; katso, se on tulvinut yli maan ja asettunut minua lähelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Tule siis ja kiroa minun puolestani tämä kansa, sillä se on minua väkevämpi; ehkä minä sitten saan sen voitetuksi ja karkoitetuksi maasta. Sillä minä tiedän, että jonka sinä siunaat, se on siunattu, ja jonka sinä kiroat, se on kirottu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Niin Mooabin vanhimmat ja Midianin vanhimmat lähtivät matkaan, tietäjänpalkka mukanansa. Ja kun he saapuivat Bileamin luo, puhuivat he hänelle Baalakin sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Hän vastasi heille: \"Viipykää täällä tämä yö, niin minä annan teille vastauksen sen mukaan, kuin Herra minulle puhuu\". Silloin jäivät mooabilaisten päämiehet Bileamin luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Niin Jumala tuli Bileamin tykö ja kysyi: \"Keitä ovat ne miehet, jotka ovat sinun luonasi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Bileam vastasi Jumalalle: \"Baalak, Sipporin poika, Mooabin kuningas, on lähettänyt heidät tuomaan minulle tämän sanan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, '\'Katso, kansa on lähtenyt Egyptistä ja on tulvinut yli maan; tule siis, kiroa se minun puolestani, ehkä sitten voin ryhtyä taisteluun sitä vastaan ja karkoittaa sen\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Mutta Jumala sanoi Bileamille: \"Älä mene heidän kanssaan äläkä kiroa sitä kansaa, sillä se on siunattu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Niin Bileam nousi aamulla ja sanoi Baalakin päämiehille: \"Menkää takaisin maahanne, sillä Herra ei ole sallinut minun lähteä teidän kanssanne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Silloin nousivat Mooabin päämiehet ja tulivat Baalakin luo ja sanoivat: \"Bileam ei suostunut lähtemään meidän kanssamme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Mutta Baalak lähetti uudestaan päämiehiä matkaan, vielä useampia ja arvokkaampia kuin edelliset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Ja he saapuivat Bileamin luo ja sanoivat hänelle: \"Näin sanoo Baalak, Sipporin poika: \'Älä kieltäydy tulemasta minun luokseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Sillä minä palkitsen sinut ylenpalttisesti ja teen kaiken, mitä minulta vaadit; tule siis ja kiroa minun puolestani tämä kansa.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Mutta Bileam vastasi ja sanoi Baalakin palvelijoille: \"Vaikka Baalak antaisi minulle talonsa täyden hopeata ja kultaa, en sittenkään voisi, en pienessä enkä suuressa, rikkoa Herran, minun Jumalani, käskyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Mutta jääkää nyt tänne tekin täksi yöksi, saadakseni tietää, mitä Herra vielä minulle sanoo.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Niin Jumala tuli Bileamin tykö yöllä ja sanoi hänelle: \"Jos nämä miehet ovat tulleet kutsumaan sinua, niin nouse ja lähde heidän kanssaan, mutta tee vain se, mitä minä sinulle sanon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Ja Bileam nousi aamulla, satuloi aasintammansa ja lähti matkaan Mooabin päämiesten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Mutta kun hän lähti, syttyi Jumalan viha, ja Herran enkeli asettui tielle estämään häntä, hänen ratsastaessaan aasintammallaan, kaksi palvelijaa mukanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Kun aasintamma näki Herran enkelin seisovan tiellä, paljastettu miekka kädessänsä, niin se poikkesi tieltä ja meni peltoon. Mutta Bileam löi aasintammaa palauttaaksensa sen tielle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Sitten Herran enkeli asettui solaan viinitarhojen välille, jossa oli kiviaita kummallakin puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Kun aasintamma näki Herran enkelin, niin se painautui aitaan ja likisti Bileamin jalkaa aitaa vasten. Ja hän löi sitä vielä kerran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Silloin Herran enkeli taas meni edemmäs ja asettui ahtaaseen paikkaan, jossa ei ollut tilaa väistyä oikealle eikä vasemmalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Kun aasintamma näki Herran enkelin, laskeutui se maahan Bileamin alla. Silloin Bileamin viha syttyi, ja hän löi aasintammaa sauvalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Niin Herra avasi aasintamman suun, ja se sanoi Bileamille: \"Mitä minä olen sinulle tehnyt, koska lyöt minua jo kolmannen kerran?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Bileam vastasi aasintammalle: \"Sinä olet pitänyt minua pilkkanasi. Olisipa minulla miekka kädessäni, niin nyt minä sinut tappaisin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Mutta aasintamma sanoi Bileamille: \"Enkö minä ole sinun aasintammasi, jolla olet ratsastanut kaiken aikasi tähän päivään asti? Onko minun ollut tapana tehdä sinulle näin?\" Hän vastasi: \"Ei\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Niin Herra avasi Bileamin silmät, niin että hän näki Herran enkelin seisovan tiellä, paljastettu miekka kädessänsä. Silloin hän kumartui ja heittäytyi kasvoilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Niin Herran enkeli sanoi hänelle: \"Minkätähden olet lyönyt aasintammaasi jo kolme kertaa? Katso, minä olen tullut sinua estämään, sillä ajattelemattomasti sinä olet lähtenyt tälle matkalle vastoin minun tahtoani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Mutta aasintamma näki minut ja on väistynyt minun edestäni jo kolme kertaa. Ja jos se ei olisi väistynyt minun edestäni, niin minä olisin surmannut sinut, mutta jättänyt sen elämään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Niin Bileam vastasi Herran enkelille: \"Minä olen tehnyt syntiä; sillä minä en tiennyt, että sinä olit asettunut minua vastaan tielle. Mutta jos tämä ei ole sinulle mieleen, niin minä nyt palaan takaisin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Mutta Herran enkeli sanoi Bileamille: \"Mene näiden miesten kanssa, mutta puhu ainoastaan se, minkä minä sinulle puhun\". Niin Bileam lähti Baalakin päämiesten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Kun Baalak kuuli, että Bileam oli tulossa, meni hän häntä vastaan Iir-Mooabiin, joka on Arnonia pitkin kulkevalla rajalla, uloimmalla rajalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Ja Baalak sanoi Bileamille: \"Enkö minä vartavasten lähettänyt kutsumaan sinua? Minkätähden et tahtonut tulla minun luokseni? Enkö minä muka voi sinua palkita?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Mutta Bileam vastasi Baalakille: \"Olenhan minä nyt tullut sinun luoksesi. Mutta onko minun vallassani puhua mitään? Minkä Jumala panee minun suuhuni, sen minä puhun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Niin Bileam lähti Baalakin kanssa, ja he saapuivat Kirjat-Husotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Ja Baalak teurasti raavaita ja lampaita ja lähetti ne Bileamille ja päämiehille, jotka olivat hänen luonansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Mutta seuraavana aamuna Baalak otti Bileamin mukaansa ja vei hänet Baamot-Baalin kukkulalle, josta hän näki reunimmaisen osan tuota kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Ja Bileam sanoi Baalakille: \"Rakenna minulle tähän seitsemän alttaria ja hanki minulle tänne seitsemän härkää ja seitsemän oinasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Niin Baalak teki, niinkuin Bileam käski. Ja Baalak ja Bileam uhrasivat härän ja oinaan kullakin alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Niin Bileam sanoi Baalakille: \"Asetu tähän polttouhrisi ääreen, minä menen tuonne; ehkä minä saan kohdata Herran. Minkä hän minulle näyttää, sen minä ilmoitan sinulle.\" Ja hän meni eräälle autiolle kukkulalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Ja Jumala tuli ja kohtasi Bileamin. Silloin tämä sanoi hänelle: \"Seitsemän alttaria minä olen pannut kuntoon ja olen uhrannut härän ja oinaan kullakin alttarilla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Ja Herra pani sanat Bileamin suuhun ja sanoi: \"Palaja Baalakin luo ja puhu hänelle näin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Niin hän palasi hänen luoksensa, ja hän seisoi siinä polttouhrinsa ääressä, hän ja kaikki Mooabin päämiehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Niin hän puhkesi lausumaan ja sanoi: \"Aramista nouti minut Baalak, idän vuorilta Mooabin kuningas: \'Tule, kiroa minun puolestani Jaakob, tule ja sadattele Israelia\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Kuinka minä kiroaisin sen, jota ei Jumala kiroa, kuinka sadattelisin sitä, jota ei Herra sadattele?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Minä näen sen kallioiden huipulta, minä katselen sitä kukkuloilta: katso, se on erillään asuva kansa, se ei lukeudu pakanakansojen joukkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Kuka mittaa Jaakobin hiekkajyväset, kuka Israelin tomuhiukkasten luvun? Suotakoon minun kuolla oikeamielisten kuolema, olkoon minun loppuni niinkuin heidän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Silloin Baalak sanoi Bileamille: \"Mitä oletkaan minulle tehnyt! Minä toin sinut tänne vihollisiani kiroamaan, ja katso, nyt sinä heidät siunaat!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Mutta hän vastasi ja sanoi: \"Eikö minun ole tarkoin puhuttava se, minkä Herra panee minun suuhuni?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Niin Baalak sanoi hänelle: \"Tule minun kanssani toiseen paikkaan, josta voit nähdä sen kansan, kuitenkin ainoastaan sen äärimmäisen reunan, et sitä kokonaisuudessaan, ja kiroa se minun puolestani sieltä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Ja hän vei hänet Vartijakedolle Pisga-vuoren huipulle ja rakensi siihen seitsemän alttaria ja uhrasi härän ja oinaan kullakin alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Sitten Bileam sanoi Baalakille: \"Asetu tähän polttouhrisi ääreen, ehkä hän kohtaa minua tuolla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Niin Herra tuli kohtaamaan Bileamia, pani sanat hänen suuhunsa ja sanoi: \"Palaja Baalakin luo ja puhu hänelle näin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Niin hän tuli hänen luoksensa, ja hän seisoi siinä polttouhrinsa ääressä, Mooabin päämiehet kanssansa. Baalak kysyi häneltä: \"Mitä Herra puhui?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Niin hän puhkesi lausumaan ja sanoi: \"Nouse, Baalak, ja kuule! Kuuntele minua, sinä Sipporin poika!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Ei Jumala ole ihminen, niin että hän valhettelisi, eikä ihmislapsi, että hän katuisi. Sanoisiko hän jotakin eikä sitä tekisi, puhuisiko jotakin eikä sitä täyttäisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Katso, minä olen saanut tehtäväkseni siunata: hän on siunannut, enkä minä voi sitä peruuttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Ei havaita vaivaa Jaakobissa eikä nähdä onnettomuutta Israelissa; Herra, hänen Jumalansa, on hänen kanssansa, riemuhuuto kuninkaalle kaikuu siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Jumala vei sen pois Egyptistä; sen sarvet ovat kuin villihärän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Sillä ei ole noituutta Jaakobissa eikä tavata taikuutta Israelissa. Aikanansa ilmoitetaan Jaakobille ja Israelille, mitä Jumala on tekevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Katso, se on kansa, joka nousee kuin naarasleijona, joka kohoaa kuin leijona. Ei se paneudu levolle, ennenkuin on saalista syönyt ja juonut surmattujen verta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Mutta Baalak sanoi Bileamille: \"Älä kiroa sitä äläkä siunaa sitä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Mutta Bileam vastasi ja sanoi Baalakille: \"Enkö minä puhunut sinulle näin: \'Kaikki, mitä Herra sanoo, on minun tehtävä\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Niin Baalak sanoi Bileamille: \"Tule, minä vien sinut toiseen paikkaan; ehkäpä on Jumalan silmissä otollista, että kiroat kansan minun puolestani sieltä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Ja Baalak vei Bileamin Peor-vuoren huipulle, joka kohoaa yli erämaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Sitten Bileam sanoi Baalakille: \"Rakenna minulle tähän seitsemän alttaria ja hanki minulle tänne seitsemän härkää ja seitsemän oinasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Ja Baalak teki, niinkuin Bileam käski, ja uhrasi härän ja oinaan kullakin alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Kun Bileam näki, että Israelin siunaaminen oli Herralle otollista, ei hän enää mennyt niinkuin aina ennen ennusmerkkejä etsimään, vaan käänsi kasvonsa erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Ja kun Bileam nosti silmänsä ja näki Israelin leiriytyneenä heimokunnittain, niin Jumalan Henki tuli häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Ja hän puhkesi lausumaan ja sanoi: \"Näin puhuu Bileam, Beorin poika, näin puhuu mies, jonka silmä on avattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Näin puhuu hän, joka kuulee Jumalan puheen, joka näkee Kaikkivaltiaan näkyjä, joka lankeaa loveen ja jonka silmät avataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Kuinka ihanat ovat sinun majasi, Jaakob, sinun asuinsijasi, Israel!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Niinkuin laajat purolaaksot, niinkuin puutarhat virran varrella, niinkuin aloepuut, Herran istuttamat, niinkuin setripuut vesien vierillä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Vettä läikkyy sen vesisangoista, ja sen laihot saavat runsaasti vettä. Agagia mahtavampi on sen kuningas, ylhäinen sen kuningasvalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Jumala vei sen pois Egyptistä; sen sarvet ovat kuin villihärän. Se syö suuhunsa viholliskansat, heidän luunsa se murskaa ja lävistää heidät nuolillansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Se on kyyristynyt, se on laskeutunut maahan kuin leijona, niinkuin naarasleijona-kuka uskaltaa sitä häiritä? Siunattu olkoon, joka sinua siunaa, kirottu, joka sinua kiroaa!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Silloin Baalak vihastui Bileamiin ja löi kätensä yhteen. Ja Baalak sanoi Bileamille: \"Minä kutsuin sinut vihollisiani kiroamaan, ja nyt sinä olet siunannut heidät jo kolme kertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Mene tiehesi! Minä aioin sinua runsaasti palkita, mutta katso, Herra on sinulta palkan kieltänyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Bileam vastasi Baalakille: \"Enkö minä jo sanonut sinun sanansaattajillesi, jotka lähetit luokseni:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, '\'Vaikka Baalak antaisi minulle talonsa täyden hopeata ja kultaa, en sittenkään voisi rikkoa Herran käskyä, en tehdä mitään oman mieleni mukaan, en hyvää, en pahaa\'. Minkä Herra puhuu, sen minäkin puhun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Ja nyt minä lähden kansani tykö, mutta sitä ennen minä ilmoitan sinulle, mitä tämä kansa on tekevä sinun kansallesi aikojen lopulla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Ja hän puhkesi lausumaan ja sanoi: \"Näin puhuu Bileam, Beorin poika, näin puhuu mies, jonka silmä on avattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Näin puhuu hän, joka kuulee Jumalan puheen ja saa tietonsa Korkeimmalta, joka näkee Kaikkivaltiaan näkyjä, joka lankeaa loveen ja jonka silmät avataan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Minä näen hänet, en kuitenkaan nyt, minä katselen häntä, en kuitenkaan läheltä. Tähti nousee Jaakobista, ja valtikka kohoaa Israelista. Se ruhjoo Mooabilta ohimot, päälaen kaikilta Seetin pojilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Ja Edomista tulee alusmaa, Seir joutuu vihollistensa omaksi; mutta Israel tekee väkeviä tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Ja Jaakobista tulee valtias, hän hävittää kaupungeista niihin pelastuneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Ja kun hän näki Amalekin, niin hän puhkesi lausumaan ja sanoi: \"Kansakunnista ensimmäinen on Amalek, mutta sen loppu on perikato\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Ja kun hän näki keeniläiset, niin hän puhkesi lausumaan ja sanoi: \"Järkkymätön on sinun asumuksesi, ja kalliolle on pesäsi pantu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Mutta sittenkin Kain hävitetään: ei aikaakaan, niin Assur vie sinut vangiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Ja hän puhkesi lausumaan ja sanoi: \"Voi! Kuka jää enää elämään, kun Jumala tämän tekee!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Laivoja saapuu kittiläisten suunnalta, ja ne kurittavat Assurin ja kurittavat Eeberin. Hänkin on perikadon oma.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Senjälkeen Bileam nousi, lähti matkaan ja palasi kotiinsa; ja myöskin Baalak lähti tiehensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Niin Israel asettui Sittimiin. Ja kansa rupesi irstailemaan Mooabin tyttärien kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Nämä kutsuivat kansaa jumaliensa uhreille, ja kansa söi ja kumarsi heidän jumaliansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Kun Israel näin antautui palvelemaan Baal-Peoria, syttyi Herran viha Israelia kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Ja Herra sanoi Moosekselle: \"Ota kansan kaikki päämiehet ja lävistä heidät paaluihin Herralle, vasten aurinkoa, että Herran vihan hehku kääntyisi pois Israelista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Niin Mooses sanoi Israelin tuomareille: \"Surmatkoon jokainen miehistään ne, jotka ovat antautuneet palvelemaan Baal-Peoria\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Ja katso, muuan mies israelilaisista tuli ja toi veljiensä luo midianilaisen naisen, Mooseksen ja kaiken israelilaisten seurakunnan nähden, kun nämä olivat itkemässä ilmestysmajan ovella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Kun Piinehas, pappi Aaronin pojan Eleasarin poika, näki sen, nousi hän kansan keskeltä ja otti keihään käteensä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'ja seurasi tuota Israelin miestä makuusuojaan ja lävisti heidät molemmat, Israelin miehen ja sen naisen, vatsan kohdalta. Silloin taukosi israelilaisilta vitsaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Ja niitä, jotka kuolivat tässä vitsauksessa, oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, '\"Piinehas, pappi Aaronin pojan Eleasarin poika, on kääntänyt minun vihani pois israelilaisista, kun hän on kiivaillut minun puolestani heidän keskuudessaan, niin ettei minun ole tarvinnut kiivaudessani tehdä loppua israelilaisista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Sano siis: Katso, minä teen hänen kanssansa liiton hänen menestymiseksensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Ja se tulee hänelle ja hänen jälkeläisillensä ikuiseksi pappeuden liitoksi, koska hän kiivaili Jumalansa puolesta ja toimitti sovituksen israelilaisille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Ja surmatun Israelin miehen nimi, sen, joka surmattiin midianilaisen naisen kanssa, oli Simri, simeonilaisen perhekunta-päämiehen Saalun poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Ja surmatun midianilais-naisen nimi oli Kosbi, Suurin, midianilaisen perhekunnan heimopäällikön, tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, '\"Ahdistakaa midianilaisia ja tuhotkaa heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Sillä he ahdistivat teitä viekkailla juonillansa, joilla he houkuttelivat teidät Peorin ja sisarensa Kosbin, midianilaisen päämiehen tyttären, ansaan, hänen, joka surmattiin Peorin vuoksi tapahtuneen vitsauksen päivänä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Tämän vitsauksen jälkeen Herra puhui Moosekselle ja Eleasarille, pappi Aaronin pojalle, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, '\"Laskekaa koko israelilaisten seurakunnan väkiluku, kaksikymmenvuotiset ja sitä vanhemmat, perhekunnittain, kaikki Israelin sotakelpoiset miehet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Ja Mooses ja pappi Eleasar puhuivat heille Mooabin arolla Jordanin luona, Jerikon kohdalla, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, '\"Kaksikymmenvuotiset ja sitä vanhemmat laskettakoon\", niinkuin Herra oli Moosekselle käskyn antanut. Ja israelilaiset, jotka olivat lähteneet Egyptin maasta, olivat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruuben, Israelin esikoinen; Ruubenin jälkeläisiä olivat: Hanokista hanokilaisten suku, Pallusta pallulaisten suku,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Hesronista hesronilaisten suku, Karmista karmilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Nämä olivat ruubenilaisten suvut. Ja katselmuksessa olleita oli heitä neljäkymmentäkolme tuhatta seitsemänsataa kolmekymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Ja Pallun poika oli Eliab.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Ja Eliabin pojat olivat Nemuel ja Daatan ja Abiram. Nämä olivat ne kansan edusmiehet Daatan ja Abiram, jotka taistelivat Moosesta ja Aaronia vastaan Koorahin joukossa ja taistelivat Herraa vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'jolloin maa avasi kitansa ja nielaisi heidät ja Koorahin, silloin kun hänen joukkonsa kuoli ja tuli kulutti kaksisataa viisikymmentä miestä; ja heistä tuli varoitusmerkki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Mutta Koorahin pojat eivät kuolleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Simeonin jälkeläisiä, sukujensa mukaan, olivat: Nemuelista nemuelilaisten suku, Jaaminista jaaminilaisten suku, Jaakinista jaakinilaisten suku,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Serahista serahilaisten suku, Saulista saulilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Nämä olivat simeonilaisten suvut, kaksikymmentäkaksi tuhatta kaksisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Gaadin jälkeläisiä, sukujensa mukaan, olivat: Sefonista sefonilaisten suku, Haggista haggilaisten suku, Suunista suunilaisten suku,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Osnista osnilaisten suku, Eeristä eeriläisten suku,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Arodista arodilaisten suku, Arelista arelilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Nämä olivat Gaadin jälkeläisten suvut; katselmuksessa olleita oli heitä neljäkymmentä tuhatta viisisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Juudan poikia olivat Eer ja Oonan, mutta Eer ja Oonan kuolivat Kanaanin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Ja Juudan jälkeläisiä, sukujensa mukaan, olivat: Seelasta seelalaisten suku, Pereksestä perekseläisten suku, Serahista serahilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Ja Pereksen jälkeläisiä olivat: Hesronista hesronilaisten suku, Haamulista haamulilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Nämä olivat Juudan suvut; katselmuksessa olleita oli heitä seitsemänkymmentäkuusi tuhatta viisisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Isaskarin jälkeläisiä, sukujensa mukaan, olivat: Toolasta toolalaisten suku, Puvvasta puunilaisten suku,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Jaasubista jaasubilaisten suku, Simronista simronilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Nämä olivat Isaskarin suvut; katselmuksessa olleita oli heitä kuusikymmentäneljä tuhatta kolmesataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Sebulonin jälkeläisiä, sukujensa mukaan, olivat: Seredistä serediläisten suku, Eelonista eelonilaisten suku, Jahlelista jahlelilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Nämä olivat sebulonilaisten suvut; katselmuksessa olleita oli heitä kuusikymmentä tuhatta viisisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Joosefin jälkeläisiä, sukujensa mukaan, olivat Manasse ja Efraim.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Manassen jälkeläisiä olivat: Maakirista maakirilaisten suku. Ja Maakirille syntyi Gilead; Gileadista on gileadilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Nämä olivat Gileadin jälkeläisiä: Iieseristä iieseriläisten suku, Helekistä helekiläisten suku;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Asrielista asrielilaisten suku, Sekemistä sekemiläisten suku;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Semidasta semidalaisten suku, Heeferistä heeferiläisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Mutta Selofhadilla, Heeferin pojalla, ei ollut poikia, vaan ainoastaan tyttäriä. Ja Selofhadin tyttärien nimet olivat: Mahla, Nooga, Hogla, Milka ja Tirsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Nämä olivat Manassen suvut; katselmuksessa olleita oli heitä viisikymmentäkaksi tuhatta seitsemänsataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Ja nämä olivat Efraimin jälkeläisiä, sukujensa mukaan: Suutelahista suutelahilaisten suku, Bekeristä bekeriläisten suku, Tahanista tahanilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Nämä olivat Suutelahin jälkeläisiä: Eeranista eeranilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Nämä olivat efraimilaisten suvut; katselmuksessa olleita oli heitä kolmekymmentäkaksi tuhatta viisisataa. Nämä olivat Joosefin jälkeläiset sukujensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Benjaminin jälkeläisiä, sukujensa mukaan, olivat: Belasta belalaisten suku, Asbelista asbelilaisten suku, Ahiramista ahiramilaisten suku,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Sefufamista suufamilaisten suku, Huufamista huufamilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Mutta Belan jälkeläisiä olivat Ard ja Naaman: Ardista ardilaisten suku, Naamanista naamilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Nämä olivat Benjaminin jälkeläiset sukujensa mukaan; ja katselmuksessa olleita oli heitä neljäkymmentäviisi tuhatta kuusisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Nämä olivat Daanin jälkeläisiä, sukujensa mukaan: Suuhamista suuhamilaisten suku. Nämä ovat Daanin suvut sukujensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Kaikista suuhamilaisten suvuista oli katselmuksessa olleita kuusikymmentäneljä tuhatta neljäsataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Asserin jälkeläisiä, sukujensa mukaan, olivat: Jimnasta jimnalaisten suku, Jisvistä jisviläisten suku, Beriasta berialaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Berian jälkeläisiä olivat: Heeberistä heeberiläisten suku, Malkielista malkielilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Mutta Asserin tyttären nimi oli Serah.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Nämä olivat asserilaisten suvut; katselmuksessa olleita oli heitä viisikymmentäkolme tuhatta neljäsataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Naftalin jälkeläisiä, sukujensa mukaan, olivat: Jahselista jahselilaisten suku, Guunista guunilaisten suku;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Jeeseristä jeeseriläisten suku, Sillemistä sillemiläisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Nämä olivat Naftalin suvut sukujensa mukaan; ja katselmuksessa olleita oli heitä neljäkymmentäviisi tuhatta neljäsataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Nämä olivat katselmuksessa olleet israelilaiset: kuusisataayksi tuhatta seitsemänsataa kolmekymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, '\"Näille jaettakoon maa perintöosiksi nimien lukumäärän mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Isommalle suvulle anna isompi perintöosa ja pienemmälle pienempi perintöosa; kullekin annettakoon perintöosa katselmuksessa olleiden määrän mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Mutta maa jaettakoon arvalla. Isiensä heimojen nimien mukaan he saakoot perintöosansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Arvan määräyksen mukaan jaettakoon perintöosat suurilukuisten ja vähälukuisten heimojen kesken.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Ja nämä olivat Leevin katselmuksessa olleet, sukujensa mukaan: Geersonista geersonilaisten suku, Kehatista kehatilaisten suku, Merarista merarilaisten suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Nämä olivat leeviläisten suvut: libniläisten suku, hebronilaisten suku, mahlilaisten suku, muusilaisten suku, koorahilaisten suku. Ja Kehatille oli syntynyt Amram.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Ja Amramin vaimon nimi oli Jookebed, Leevin tytär, joka oli Leeville syntynyt Egyptissä. Ja hän synnytti Amramille Aaronin ja Mooseksen sekä heidän sisarensa Mirjamin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Ja Aaronille syntyi Naadab ja Abihu, Eleasar ja Iitamar.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Mutta Naadab ja Abihu kuolivat, kun toivat vierasta tulta Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Ja katselmuksessa olleita oli heitä kaksikymmentäkolme tuhatta, kaikki miehenpuolia, kuukauden vanhoja ja sitä vanhempia. Sillä heistä ei pidetty katselmusta yhdessä muiden israelilaisten kanssa, koska heille ei annettu perintöosaa israelilaisten keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Nämä olivat siinä israelilaisten katselmuksessa, jonka Mooses ja pappi Eleasar pitivät Mooabin arolla lähellä Jordania, Jerikon kohdalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Eikä heidän joukossaan ollut ketään siinä israelilaisten katselmuksessa ollutta, jonka Mooses ja pappi Aaron olivat pitäneet Siinain erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Sillä Herra oli heille sanonut, että heidän oli kuoltava erämaassa. Eikä heistä jäänyt ketään, paitsi Kaaleb, Jefunnen poika, ja Joosua, Nuunin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Niin astuivat esiin Selofhadin tyttäret-Selofhadin, Heeferin pojan, Gileadin pojan, Maakirin pojan, Manassen pojan, tyttäret-jotka olivat Manassen, Joosefin pojan, suvuista ja joiden nimet olivat Mahla, Nooga, Hogla, Milka ja Tirsa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'ja he asettuivat Mooseksen ja pappi Eleasarin ja päämiesten ja kaiken kansan eteen ilmestysmajan ovelle ja sanoivat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, '\"Meidän isämme kuoli erämaassa, mutta hän ei ollut siinä joukossa, joka kävi kapinoimaan Herraa vastaan, Koorahin joukossa, vaan hän kuoli oman syntinsä tähden, eikä hänellä ollut poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Miksi häviäisi nyt meidän isämme nimi hänen sukunsa keskuudesta sentähden, että hänellä ei ollut poikaa? Anna meille perintöosuus isämme veljien keskuudessa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Ja Mooses saattoi heidän asiansa Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, '\"Selofhadin tyttäret puhuvat oikein. Anna heille perintöosuus heidän isänsä veljien keskuudessa ja siirrä heidän isänsä perintöosa heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Ja puhu israelilaisille sanoen: Jos joku kuolee pojatonna, niin siirtäkää hänen perintöosansa hänen tyttärellensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Mutta jos hänellä ei ole tytärtä, niin antakaa hänen perintöosansa hänen veljillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Mutta jos hänellä ei ole veljiä, niin antakaa hänen perintöosansa hänen isänsä veljille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Mutta jos hänen isällänsä ei ole veljiä, niin antakaa hänen perintöosansa sille hänen veriheimolaisellensa, joka hänen suvussansa on häntä lähin; tämä ottakoon sen haltuunsa. Ja tämä olkoon oikeussäädöksenä israelilaisilla, niinkuin Herra on Moosekselle käskyn antanut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Ja Herra sanoi Moosekselle: \"Nouse tälle Abarimin vuorelle ja katsele sitä maata, jonka minä annan israelilaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Ja kun olet sitä katsellut, niin sinutkin otetaan pois heimosi tykö, niinkuin veljesi Aaron otettiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'sentähden että te Siinin erämaassa, kansan riidellessä, niskoittelitte minun käskyjäni vastaan ettekä pitäneet minua pyhänä heidän silmiensä edessä, silloin kun vettä hankitte.\" Se oli Meriban vesi Kaadeksessa Siinin erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Ja Mooses puhui Herralle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, '\"Asettakoon Herra, Jumala, jonka vallassa on kaiken lihan henki, tämän seurakunnan johtoon miehen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'joka heidän edellänsä lähtee ja joka heidän edellänsä tulee, joka saattaa heidät lähtemään ja tulemaan, ettei Herran seurakunta olisi niinkuin lammaslauma, jolla ei ole paimenta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Ja Herra sanoi Moosekselle: \"Ota Joosua, Nuunin poika, mies, jossa on Henki, ja pane kätesi hänen päällensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Ja aseta hänet pappi Eleasarin ja kaiken kansan eteen ja aseta hänet virkaan heidän nähtensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Ja siirrä hänelle osa omaa arvoasi, että kaikki israelilaisten seurakunta häntä tottelisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Ja hän astukoon pappi Eleasarin eteen, ja tämä kysyköön hänen puolestaan uurimin kautta Jumalan vastausta Herran edessä. Hänen käskystänsä he lähtekööt ja hänen käskystänsä he tulkoot, hän ja kaikki israelilaiset hänen kanssansa, koko seurakunta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Ja Mooses teki, niinkuin Herra oli häntä käskenyt, ja otti Joosuan ja asetti hänet pappi Eleasarin ja kaiken seurakunnan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Ja hän pani kätensä hänen päällensä ja asetti hänet virkaan, niinkuin Herra oli puhunut Mooseksen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, '\"Käske israelilaisia ja sano heille: Pitäkää vaari siitä, että tuotte minulle minun uhrilahjani, ruokani, suloisesti tuoksuvat uhrini, määräaikanaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Ja sano heille: Tämä on se uhri, joka teidän on tuotava joka päivä Herralle: kaksi vuoden vanhaa virheetöntä karitsaa jokapäiväiseksi polttouhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Uhraa toinen karitsa aamulla, ja toinen karitsa uhraa iltahämärässä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'ja ruokauhriksi kymmenesosa eefa-mittaa lestyjä jauhoja, sekoitettuna neljännekseen hiin-mittaa survomalla saatua öljyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Tämä on jokapäiväinen polttouhri, joka toimitettiin Siinain vuorella suloisesti tuoksuvaksi uhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Ja siihen kuulukoon juomauhrina neljännes hiin-mittaa viiniä kumpaakin karitsaa kohti. Pyhäkössä vuodata Herralle höysteviiniuhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Ja toinen karitsa uhraa iltahämärässä ja toimita siihen kuuluva ruoka-ja juomauhri samalla tavoin kuin aamullakin, suloisesti tuoksuvaksi uhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Mutta sapatinpäivänä uhraa kaksi vuoden vanhaa virheetöntä karitsaa ynnä kaksi kymmenennestä lestyjä jauhoja, öljyyn sekoitettuna, ruokauhriksi, sekä siihen kuuluva juomauhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Tämä on sapatin polttouhri, joka uhrattakoon kunakin sapattina jokapäiväisen polttouhrin ja siihen kuuluvan juomauhrin ohella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Ja kuukausienne ensimmäisenä päivänä tuokaa polttouhriksi Herralle kaksi mullikkaa, oinas ja seitsemän virheetöntä vuoden vanhaa karitsaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'sekä kolme kymmenennestä lestyjä jauhoja, öljyyn sekoitettuna, ruokauhriksi kutakin mullikkaa kohti ynnä kaksi kymmenennestä lestyjä jauhoja, öljyyn sekoitettuna, ruokauhriksi oinasta kohti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'sekä yksi kymmenennes lestyjä jauhoja, öljyyn sekoitettuna, ruokauhriksi kutakin karitsaa kohti. Tämä on polttouhri, suloisesti tuoksuva uhri Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Ja niihin kuulukoon juomauhrina puoli hiin-mittaa viiniä kutakin mullikkaa kohti ja kolmannes hiin-mittaa oinasta kohti ja neljännes hiin-mittaa karitsaa kohti. Tämä on uudenkuun polttouhri, joka uhrattakoon kunakin uutenakuuna, vuoden kaikkina kuukausina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Ja sitäpaitsi uhratkaa yksi kauris syntiuhriksi Herralle. Se uhrattakoon jokapäiväisen polttouhrin ynnä siihen kuuluvan juomauhrin ohella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Ja ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, on pääsiäinen Herran kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Ja saman kuukauden viidentenätoista päivänä on juhla; seitsemän päivää syötäköön happamatonta leipää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Ensimmäisenä päivänä on pyhä kokous; älkää silloin yhtäkään arkiaskaretta toimittako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Ja tuokaa polttouhriksi Herralle kaksi mullikkaa, oinas ja seitsemän vuodenvanhaa karitsaa; ne olkoot virheettömät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Ja niihin kuuluvana ruokauhrina uhratkaa lestyjä jauhoja, öljyyn sekoitettuna, kolme kymmenennestä mullikkaa kohti ja kaksi kymmenennestä oinasta kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Kutakin kohti niistä seitsemästä karitsasta uhratkaa kymmenennes.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Ja vielä uhratkaa kauris syntiuhriksi, joka tuottaa teille sovituksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Paitsi aamupolttouhria, joka on jokapäiväinen polttouhri, uhratkaa nämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Samoin uhratkaa Herralle joka päivä seitsemän päivän aikana leipää suloisesti tuoksuvaksi uhriksi; uhratkaa tämä jokapäiväisen polttouhrin ynnä siihen kuuluvan juomauhrin ohella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Ja seitsemäntenä päivänä olkoon teillä pyhä kokous; älkää silloin yhtäkään arkiaskaretta toimittako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Mutta uutisen päivänä, kun tuotte uuden ruokauhrin Herralle viikkojuhlananne, olkoon teillä pyhä kokous; älkää silloin yhtäkään arkiaskaretta toimittako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Ja tuokaa suloisesti tuoksuvaksi polttouhriksi Herralle kaksi mullikkaa, oinas ja seitsemän vuodenvanhaa karitsaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'ja niihin kuuluvana ruokauhrina lestyjä jauhoja, öljyyn sekoitettuna, kolme kymmenennestä kutakin mullikkaa kohti, kaksi kymmenennestä oinasta kohti');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'ja yksi kymmenennes kutakin kohti niistä seitsemästä karitsasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'ja yksi kauris sovittamiseksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Paitsi jokapäiväistä polttouhria ja siihen kuuluvaa ruokauhria uhratkaa nämä ynnä niihin kuuluvat juomauhrit; eläimet olkoot virheettömät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, '\"Ja seitsemännessä kuussa, kuukauden ensimmäisenä päivänä, olkoon teillä pyhä kokous; älkää silloin yhtäkään arkiaskaretta toimittako. Olkoon se teille pasunansoiton päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Ja uhratkaa suloisesti tuoksuvaksi polttouhriksi Herralle mullikka, oinas ja seitsemän vuodenvanhaa virheetöntä karitsaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'ja niihin kuuluvana ruokauhrina lestyjä jauhoja, öljyyn sekoitettuna, kolme kymmenennestä mullikkaa kohti, kaksi kymmenennestä oinasta kohti');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'ja yksi kymmenennes kutakin kohti niistä seitsemästä karitsasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'ja kauris syntiuhriksi, teidän sovittamiseksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Paitsi uudenkuun polttouhria ynnä siihen kuuluvaa ruokauhria ja jokapäiväistä polttouhria ynnä siihen kuuluvaa ruokauhria ja niihin kuuluvia juomauhreja, niinkuin niistä on säädetty, uhratkaa kaikki tämä suloisesti tuoksuvaksi uhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Ja saman seitsemännen kuun kymmenentenä päivänä olkoon teillä pyhä kokous, ja silloin kurittakaa itseänne paastolla, älkääkä yhtäkään askaretta toimittako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Ja tuokaa suloisesti tuoksuvaksi polttouhriksi Herralle mullikka, oinas ja seitsemän vuodenvanhaa karitsaa; ne olkoot virheettömät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'Ja niihin kuulukoon ruokauhrina lestyjä jauhoja, öljyyn sekoitettuna, kolme kymmenennestä mullikkaa kohti, kaksi kymmenennestä oinasta kohti');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'ja yksi kymmenennes kutakin kohti niistä seitsemästä karitsasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'ja kauris syntiuhriksi, paitsi sovitusuhria ja jokapäiväistä polttouhria ynnä niihin kuuluvia ruoka-ja juomauhreja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Ja seitsemännen kuukauden viidentenätoista päivänä olkoon teillä pyhä kokous; älkää silloin yhtäkään arkiaskaretta toimittako, vaan viettäkää juhlaa Herran kunniaksi seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Ja tuokaa polttouhriksi, suloisesti tuoksuvaksi uhriksi Herralle, kolmetoista mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa karitsaa; olkoot ne virheettömät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Ja kuulukoon niihin ruokauhrina lestyjä jauhoja, öljyyn sekoitettuna, kolme kymmenennestä kutakin kohti niistä kolmestatoista mullikasta, kaksi kymmenennestä kumpaakin kohti niistä kahdesta oinaasta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'ja yksi kymmenennes kutakin kohti niistä neljästätoista karitsasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'ja kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka-ja juomauhria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Ja toisena päivänä: kaksitoista mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa, virheetöntä karitsaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'ja niihin kuuluvat ruoka-ja juomauhrit mullikkain, oinaiden ja karitsain luvun mukaan, niinkuin säädetty on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka-ja juomauhria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Ja kolmantena päivänä: yksitoista mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa, virheetöntä karitsaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'ja niihin kuuluvat ruoka-ja juomauhrit mullikkain, oinaiden ja karitsain luvun mukaan, niinkuin säädetty on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka-ja juomauhria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Ja neljäntenä päivänä: kymmenen mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa, virheetöntä karitsaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'ja niihin kuuluvat ruoka-ja juomauhrit mullikkain, oinaiden ja karitsain luvun mukaan, niinkuin säädetty on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka-ja juomauhria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Ja viidentenä päivänä: yhdeksän mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa, virheetöntä karitsaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'ja niihin kuuluvat ruoka-ja juomauhrit mullikkain, oinaiden ja karitsain luvun mukaan, niinkuin säädetty on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka-ja juomauhria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Ja kuudentena päivänä: kahdeksan mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa, virheetöntä karitsaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'ja niihin kuuluvat ruoka-ja juomauhrit mullikkain, oinaiden ja karitsain luvun mukaan, niinkuin säädetty on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka-ja juomauhria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Ja seitsemäntenä päivänä: seitsemän mullikkaa, kaksi oinasta ja neljätoista vuodenvanhaa, virheetöntä karitsaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'ja niihin kuuluvat ruoka-ja juomauhrit mullikkain, oinaiden ja karitsain luvun mukaan, niinkuin säädetty on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka-ja juomauhria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Ja kahdeksantena päivänä olkoon teillä juhlakokous; älkää silloin yhtäkään arkiaskaretta toimittako,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'vaan tuokaa suloisesti tuoksuvaksi polttouhriksi Herralle mullikka, oinas ja seitsemän vuodenvanhaa, virheetöntä karitsaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'ja niihin kuuluvat ruoka-ja juomauhrit mullikan, oinaan ja karitsain luvun mukaan, niinkuin säädetty on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'sekä kauris syntiuhriksi, paitsi jokapäiväistä polttouhria ynnä siihen kuuluvaa ruoka-ja juomauhria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Nämä uhratkaa Herralle juhla-aikoinanne, paitsi mitä lupausuhreinanne ja vapaaehtoisina lahjoinanne tuotte polttouhreiksi, ruokauhreiksi, juomauhreiksi ja yhteysuhreiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, '{30:1} Ja Mooses puhui israelilaisille kaiken, mitä Herra oli Mooseksen käskenyt puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, '{30:2} Ja Mooses puhui Israelin sukukuntien päämiehille sanoen: \"Näin on Herra käskenyt:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, '{30:3} Jos joku tekee lupauksen Herralle tahi valalla vannoen sitoutuu kieltäytymään jostakin, älköön hän rikkoko sanaansa, vaan tehköön kaiken, mitä hänen suunsa on sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, '{30:4} Ja jos nainen ollessaan nuorena tyttönä isänsä kodissa tekee lupauksen Herralle tahi sitoutuu kieltäytymään jostakin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, '{30:5} ja hänen isänsä kuulee hänen lupauksensa tai sitoumuksensa eikä hänen isänsä hänelle siitä mitään puhu, niin kaikki hänen lupauksensa ja kaikki hänen sitoumuksensa, joilla hän kieltäytyy jostakin, olkoot pätevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, '{30:6} Mutta jos hänen isänsä kieltää häntä sinä päivänä, jona hän ne kuulee, niin hänen lupauksensa ja sitoumuksensa, joilla hän kieltäytyy jostakin, älkööt olko pätevät, olivatpa ne mitkä hyvänsä, ja Herra antaa hänelle anteeksi, sentähden että hänen isänsä on häntä kieltänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, '{30:7} Ja jos hän joutuu miehelle ja hänellä on täytettävänä lupauksia tai ajattelemattomasti lausuttu sana, jolla hän on kieltäytynyt jostakin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, '{30:8} ja hänen miehensä saa sen kuulla, mutta ei puhu hänelle siitä mitään sinä päivänä, jona hän sen kuulee, niin hänen lupauksensa ja hänen sitoumuksensa, joilla hän on kieltäytynyt jostakin, olkoot pätevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, '{30:9} Mutta jos hänen miehensä sinä päivänä, jona hän sen kuulee, kieltää häntä, niin hän purkaa hänen lupauksensa, jonka täyttämiseen hän on sitoutunut, ja sen ajattelemattomasti lausutun sanan, jolla hän on kieltäytynyt jostakin, ja Herra antaa hänelle anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, '{30:10} Mutta lesken tai hyljätyn lupaus, mihin hyvänsä hän onkin sitoutunut, olkoon pätevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, '{30:11} Ja jos vaimo on miehensä kodissa tehnyt lupauksen tahi valalla sitoutunut kieltäytymään jostakin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, '{30:12} ja hänen miehensä saa sen kuulla, mutta ei puhu hänelle siitä mitään eikä kiellä häntä, niin kaikki hänen lupauksensa ja kaikki sitoumukset, joilla hän on kieltäytynyt jostakin, olkoot pätevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, '{30:13} Mutta jos hänen miehensä ne purkaa sinä päivänä, jona hän niistä kuulee, älköön yksikään hänen huuliltaan lähtenyt lupaus tai sitoumus olko pätevä. Hänen miehensä on ne purkanut, ja Herra antaa hänelle anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, '{30:14} Jokaisen lupauksen ja jokaisen valallisen sitoumuksen, jonka vaimo itsensä kurittamiseksi tekee, saakoon hänen miehensä joko vahvistaa tahi purkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, '{30:15} Mutta jos hänen miehensä ei puhu hänelle niistä mitään sen päivän kuluessa, niin hän on vahvistanut kaikki hänen lupauksensa ja kaikki hänen sitoumuksensa, jotka hänellä on täytettävinä. Hän on ne vahvistanut, koska hän ei niistä hänelle mitään puhunut sinä päivänä, jona hän niistä kuuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, '{30:16} Mutta jos hän ne purkaa vasta jonkun aikaa sen jälkeen, kuin on niistä kuullut, joutuu hän kantamaan vaimonsa syyllisyyden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, '{30:17} Nämä ovat ne säädökset, jotka Herra antoi Moosekselle, olemaan voimassa miehen ja hänen vaimonsa välillä sekä isän ja hänen tyttärensä välillä, tämän ollessa nuorena tyttönä isänsä kodissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, '\"Kosta israelilaisten puolesta midianilaisille. Senjälkeen sinut otetaan pois heimosi tykö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Niin Mooses puhui kansalle sanoen: \"Varustakaa joukostanne miehiä sotaan, ja lähtekööt he Midiania vastaan toimittamaan Herran koston Midianille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Tuhat miestä jokaisesta sukukunnasta, kaikista Israelin sukukunnista, lähettäkää sotaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Silloin annettiin Israelin heimoista tuhat miestä jokaisesta sukukunnasta, yhteensä kaksitoista tuhatta sotaan varustettua miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Ja Mooses lähetti heidät, tuhat miestä jokaisesta sukukunnasta, sotaan sekä heidän kanssaan Piinehaan, pappi Eleasarin pojan; tällä oli mukanaan pyhät esineet ja hälytystorvet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Niin he lähtivät sotimaan Midiania vastaan, niinkuin Herra oli Moosekselle käskyn antanut, ja surmasivat kaikki miehenpuolet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Muiden mukana, jotka kaatuivat, he surmasivat Midianin kuninkaat Evin, Rekemin, Suurin, Huurin ja Reban, Midianin viisi kuningasta. Myös Bileamin, Beorin pojan, he surmasivat miekalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Mutta israelilaiset ottivat vangiksi midianilaisten vaimot ja lapset ja ryöstivät kaikki heidän juhtansa ja kaiken heidän karjansa ja kaiken heidän tavaransa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Ja kaikki heidän asumansa kaupungit ja kaikki heidän leiripaikkansa he polttivat tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Ja he ottivat kaiken ryöstettävän ja kaiken otettavan, sekä ihmiset että karjan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Ja he toivat Moosekselle ja pappi Eleasarille sekä Israelin kansalle vangit ja ottamansa ja ryöstämänsä saaliin leiriin Mooabin arolle, joka on Jordanin luona, Jerikon kohdalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Silloin Mooses ja pappi Eleasar ja kaikki kansan päämiehet lähtivät heitä vastaan leirin ulkopuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Ja Mooses vihastui sotajoukon johtajiin, tuhannen-ja sadanpäämiehiin, kun he palasivat sotaretkeltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Ja Mooses sanoi heille: \"Oletteko siis jättäneet henkiin kaikki naiset?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Katso, nehän ne olivat, jotka Bileamin neuvosta saivat israelilaiset antautumaan uskottomuuteen Herraa vastaan Peorin vuoksi, niin että vitsaus kohtasi Herran seurakuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Niin surmatkaa siis kaikki poikalapset ja surmatkaa myös jokainen vaimo, joka on yhtynyt mieheen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Mutta jokainen tyttö, joka ei ole yhtynyt mieheen, jättäkää itsellenne henkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Mutta itse oleskelkaa leirin ulkopuolella seitsemän päivää. Jokainen teistä, joka on jonkun surmannut, ja jokainen teistä, joka on koskenut surmattuun, puhdistautukoon kolmantena ja seitsemäntenä päivänä, sekä te että teidän vankinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Ja puhdistettakoon jokainen vaate ja jokainen nahkaesine ja kaikki, mikä on tehty vuohen karvoista, ja jokainen puuesine.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Ja pappi Eleasar sanoi sotamiehille, jotka olivat menneet sotaan: \"Tämä on lakisäädös, jonka Herra antoi Moosekselle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Vain kulta, hopea, vaski, rauta, tina ja lyijy,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'kaikki, mikä tulta kestää, käyttäkää tulessa, niin se puhdistuu; puhdistettakoon se kuitenkin vielä puhdistusvedellä. Mutta mikä ei tulta kestä, käyttäkää se vedessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Ja peskää vaatteenne seitsemäntenä päivänä, niin te puhdistutte; ja sitten tulkaa leiriin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, '\"Laskekaa, sinä ja pappi Eleasar ja kansan perhekuntien päämiehet, otetun saaliin määrä, ihmiset ja karja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'Ja pane saalis kahtia soturien, sotaan lähteneiden, ja kaiken muun kansan kesken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Ja ota Herralle verona sotamiehiltä, sotaan lähteneiltä, yksi viidestäsadasta, ihmisiä, raavaita, aaseja ja lampaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Ota se heille tulevasta puoliskosta ja anna se pappi Eleasarille antina Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Ja israelilaisille tulevasta puoliskosta ota yksi viidestäkymmenestä, ihmisiä, raavaita, aaseja, lampaita ja kaikkia karjaeläimiä, ja anna ne leeviläisille, joiden on hoidettava tehtävät Herran asumuksessa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Ja Mooses ja pappi Eleasar tekivät, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Ja saalis, jäännös siitä, mitä sotajoukko oli ryöstänyt, oli: lampaita kuusisataa seitsemänkymmentäviisi tuhatta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'ja raavaita seitsemänkymmentäkaksi tuhatta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'ja aaseja kuusikymmentäyksi tuhatta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'ja ihmisiä, tyttöjä, jotka eivät olleet yhtyneet mieheen, kaikkiaan kolmekymmentäkaksi tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Ja puolet siitä eli se osa, joka tuli sotaan lähteneille, oli: lampaita kolmesataa kolmekymmentäseitsemän tuhatta viisisataa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'ja Herralle tuleva vero lampaista oli kuusisataa seitsemänkymmentä viisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'ja raavaita kolmekymmentäkuusi tuhatta sekä niistä Herralle tuleva vero seitsemänkymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'ja aaseja kolmekymmentä tuhatta viisisataa sekä niistä Herralle tuleva vero kuusikymmentä yksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'ja ihmisiä kuusitoista tuhatta sekä niistä Herralle tuleva vero kolmekymmentä kaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Ja Mooses antoi Herran antiveron pappi Eleasarille, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Ja israelilaisille tuleva puolisko, jonka Mooses oli erottanut sotamiesten osasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'tämä seurakunnalle tuleva puolisko oli: lampaita kolmesataa kolmekymmentäseitsemän tuhatta viisisataa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'ja raavaita kolmekymmentäkuusi tuhatta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'ja aaseja kolmekymmentä tuhatta viisisataa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'sekä ihmisiä kuusitoista tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Tästä israelilaisille tulevasta puoliskosta Mooses otti yhden viidestäkymmenestä, ihmisiä ja karjaa, sekä antoi ne leeviläisille, joiden oli hoidettava tehtävät Herran asumuksessa, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Silloin tulivat sotajoukon osastojen johtajat, tuhannen-ja sadanpäämiehet, Mooseksen luo');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'ja sanoivat Moosekselle: \"Palvelijasi ovat laskeneet niiden sotamiesten luvun, jotka ovat olleet hallussamme, eikä meistä puutu yhtäkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Sentähden me tuomme nyt Herralle lahjaksi, mitä kukin on saanut kultakaluja: käätyjä, rannerenkaita, sormuksia, korvarenkaita ja kaulakoristeita, saadaksemme itsellemme sovituksen Herran edessä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Niin Mooses ja pappi Eleasar ottivat heiltä kullan, kaikkinaiset taidokkaasti valmistetut esineet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Ja anniksi annettua kultaa, jonka he antoivat Herralle tuhannen-ja sadanpäämiesten puolesta, oli kaikkiaan kuusitoista tuhatta seitsemänsataa viisikymmentä sekeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Sotamiehet olivat ottaneet saalista kukin itselleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Ja Mooses ja pappi Eleasar ottivat kullan tuhannen-ja sadanpäämiehiltä ja veivät sen ilmestysmajaan, että se johdattaisi israelilaiset Herran muistoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Mutta ruubenilaisilla ja gaadilaisilla oli paljon, ylen runsaasti, karjaa. Kun he nyt katselivat Jaeserin maata ja Gileadin maata, niin he huomasivat, että seutu oli karjanhoitoon sopiva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Niin gaadilaiset ja ruubenilaiset tulivat ja puhuivat Moosekselle ja pappi Eleasarille ja seurakunnan päämiehille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, '\"Atarot, Diibon, Jaeser, Nimra, Hesbon, Elale, Sebam, Nebo ja Beon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'tämä maa, jonka Herra on vallannut Israelin seurakunnalle, on karjanhoitoon sopivaa maata, ja sinun palvelijoillasi on karjaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Ja he sanoivat vielä: \"Jos olemme saaneet armon sinun silmiesi edessä, niin annettakoon tämä maa palvelijoillesi omaksi, äläkä vie meitä Jordanin yli\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Mutta Mooses vastasi gaadilaisille ja ruubenilaisille: \"Onko teidän veljienne lähdettävä sotaan, ja te jäisitte tänne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Miksi viette israelilaisilta halun mennä siihen maahan, jonka Herra on heille antanut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Niin teidän isännekin tekivät, kun minä lähetin heidät Kaades-Barneasta katselemaan sitä maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Kun he olivat saapuneet Rypälelaaksoon asti ja katselleet sitä maata, veivät he israelilaisilta halun lähteä siihen maahan, jonka Herra oli heille antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Ja sinä päivänä syttyi Herran viha, ja hän vannoi sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, '\'Ne miehet, jotka lähtivät Egyptistä, kaksikymmenvuotiset ja sitä vanhemmat, eivät saa nähdä sitä maata, jonka minä vannoen lupasin Aabrahamille, Iisakille ja Jaakobille, sillä he eivät ole minua uskollisesti seuranneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'paitsi Kaaleb, kenissiläisen Jefunnen poika, ja Joosua, Nuunin poika; sillä nämä ovat uskollisesti seuranneet Herraa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Ja Herran viha syttyi Israelia kohtaan, ja hän antoi heidän harhailla erämaassa neljäkymmentä vuotta, kunnes koko se sukupolvi hävisi, joka oli tehnyt sitä, mikä oli pahaa Herran silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Mutta katso, te olette nyt astuneet isienne sijaan, te syntisten sikiöt, lisätäksenne vielä Herran vihan kiivautta Israelia kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Jos te nyt käännytte pois hänestä, niin hän jättää kansan vielä kauemmaksi aikaa tähän erämaahan, ja niin te tuotatte tuhon kaikelle tälle kansalle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Niin he lähestyivät häntä ja sanoivat: \"Karjatarhoja me vain rakentaisimme tänne laumoillemme ja kaupunkeja vaimojamme ja lapsiamme varten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'mutta itse me varustautuisimme ja rientäisimme israelilaisten etunenässä, kunnes saisimme viedyksi heidät määräpaikkoihinsa, mutta meidän vaimomme ja lapsemme asuisivat sillä aikaa varustetuissa kaupungeissa maan asukkailta rauhassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Emme me palaisi kotiimme, ennenkuin israelilaiset ovat saaneet haltuunsa kukin perintöosansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'sillä me emme tahdo perintöosaa heidän kanssansa tuolta puolen Jordanin emmekä kauempaa, vaan meidän perintöosamme on joutunut meille tältä puolelta Jordanin, itään päin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Niin Mooses vastasi heille: \"Jos näin teette, jos Herran edessä varustaudutte sotaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'ja teistä jokainen, sotaan varustettuna, menee Jordanin yli Herran edessä niin pitkäksi aikaa, kunnes on karkoittanut vihollisensa edestään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'ja te palaatte vasta senjälkeen, kuin se maa on tehty alamaiseksi Herralle, niin te olette vastuusta vapaat Herran ja Israelin edessä, ja tämä maa tulee teidän omaksenne Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Mutta jos ette näin tee, niin katso, te rikotte Herraa vastaan ja saatte tuntea syntinne palkan, joka kohtaa teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Rakentakaa siis itsellenne kaupunkeja vaimojanne ja lapsianne varten ja tarhoja karjallenne ja tehkää se, mitä suunne on sanonut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Niin gaadilaiset ja ruubenilaiset vastasivat Moosekselle sanoen: \"Sinun palvelijasi tekevät, niinkuin herramme käskee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Lapsemme, vaimomme, laumamme ja kaikki juhtamme jääkööt tänne Gileadin kaupunkeihin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'mutta sinun palvelijasi lähtevät, jokainen sotaan varustettuna, sinne taisteluun Herran edessä, niinkuin herramme sanoi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Niin Mooses antoi heistä käskyn pappi Eleasarille ja Joosualle, Nuunin pojalle, ja Israelin sukukuntien perhekuntain päämiehille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'ja Mooses sanoi heille: \"Jos gaadilaiset ja ruubenilaiset teidän kanssanne lähtevät Jordanin yli, jokainen varustettuna taisteluun Herran edessä, ja se maa tulee teille alamaiseksi, niin antakaa heille Gileadin maa omaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Mutta jolleivät he varustaudu ja lähde teidän kanssanne sinne, niin asettukoot teidän keskuuteenne Kanaanin maahan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Silloin gaadilaiset ja ruubenilaiset vastasivat sanoen: \"Mitä Herra on puhunut sinun palvelijoillesi, sen me teemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Me lähdemme varustettuina Herran edessä Kanaanin maahan, että saisimme omaksemme perintöosan tällä puolella Jordanin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Ja Mooses antoi heille, gaadilaisille ja ruubenilaisille sekä toiselle puolelle Manassen, Joosefin pojan, sukukuntaa, amorilaisten kuninkaan Siihonin valtakunnan ja Baasanin kuninkaan Oogin valtakunnan, maan ja sen kaupungit alueinensa, sen maan kaupungit yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Ja gaadilaiset rakensivat Diibonin, Atarotin, Aroerin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atrot-Soofanin, Jaeserin, Jogbehan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Beet-Nimran ja Beet-Haaranin varustetuiksi kaupungeiksi sekä karjatarhoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Ja ruubenilaiset rakensivat Hesbonin, Elalen ja Kirjataimin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebon ja Baal-Meonin, joiden nimet muutettiin, sekä Sibman. Ja he panivat nimet niille kaupungeille, jotka he rakensivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Mutta Maakir, Manassen poika, lähti Gileadiin ja valloitti sen ja karkoitti amorilaiset, jotka asuivat siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Ja Mooses antoi Gileadin Maakirille, Manassen pojalle, ja hän asettui sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Ja Jaair, Manassen poika, meni ja valloitti heidän leirikylänsä ja kutsui ne Jaairin leirikyliksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Ja Noobah meni ja valloitti Kenatin ynnä sen alueella olevat kylät ja kutsui sen, nimensä mukaan, Noobahiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Nämä olivat israelilaisten matkat, jotka he kulkivat Egyptistä osastoittain Mooseksen ja Aaronin johdolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Ja Mooses kirjoitti Herran käskyn mukaan muistiin ne paikat, joista he lähtivät liikkeelle matkoillansa. Ja nämä ovat heidän matkansa heidän lähtöpaikkojensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'He lähtivät liikkeelle Ramseksesta ensimmäisessä kuussa, ensimmäisen kuukauden viidentenätoista päivänä; pääsiäisen jälkeisenä päivänä israelilaiset lähtivät matkaan voimallisen käden suojassa, kaikkien egyptiläisten nähden,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'egyptiläisten haudatessa kaikkia esikoisiansa, jotka Herra heidän keskuudestaan oli surmannut, ja Herran antaessa tuomion kohdata heidän jumaliansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Niin israelilaiset lähtivät Ramseksesta ja leiriytyivät Sukkotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Sitten he lähtivät Sukkotista ja leiriytyivät Eetamiin, joka on erämaan reunassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Ja he lähtivät Eetamista ja kääntyivät takaisin Pii-Hahirotiin päin, joka on vastapäätä Baal-Sefonia, ja leiriytyivät Migdolin kohdalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Ja he lähtivät Pii-Hahirotista ja kulkivat meren keskitse erämaahan ja vaelsivat kolmen päivän matkan Eetamin erämaassa ja leiriytyivät Maaraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Sitten he lähtivät Maarasta ja tulivat Eelimiin. Eelimissä oli kaksitoista vesilähdettä ja seitsemänkymmentä palmupuuta, ja he leiriytyivät sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Ja he lähtivät Eelimistä ja leiriytyivät Kaislameren rannalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Ja he lähtivät Kaislameren rannalta ja leiriytyivät Siinin erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Ja he lähtivät Siinin erämaasta ja leiriytyivät Dofkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Ja he lähtivät Dofkasta ja leiriytyivät Aalukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Ja he lähtivät Aaluksesta ja leiriytyivät Refidimiin; siellä ei ollut vettä kansan juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Ja he lähtivät Refidimistä ja leiriytyivät Siinain erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Ja he lähtivät Siinain erämaasta ja leiriytyivät Kibrot-Hattaavaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Ja he lähtivät Kibrot-Hattaavasta ja leiriytyivät Haserotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Ja he lähtivät Haserotista ja leiriytyivät Ritmaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Ja he lähtivät Ritmasta ja leiriytyivät Rimmon-Perekseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Ja he lähtivät Rimmon-Pereksestä ja leiriytyivät Libnaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Ja he lähtivät Libnasta ja leiriytyivät Rissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Ja he lähtivät Rissasta ja leiriytyivät Kehelataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Ja he lähtivät Kehelatasta ja leiriytyivät Seferin vuoren juurelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Ja he lähtivät Seferin vuoren juurelta ja leiriytyivät Haradaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Ja he lähtivät Haradasta ja leiriytyivät Makhelotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Ja he lähtivät Makhelotista ja leiriytyivät Tahatiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Ja he lähtivät Tahatista ja leiriytyivät Tarahiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Ja he lähtivät Tarahista ja leiriytyivät Mitkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Ja he lähtivät Mitkasta ja leiriytyivät Hasmonaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Ja he lähtivät Hasmonasta ja leiriytyivät Mooserotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Ja he lähtivät Mooserotista ja leiriytyivät Bene-Jaakaniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Ja he lähtivät Bene-Jaakanista ja leiriytyivät Hoor-Gidgadiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Ja he lähtivät Hoor-Gidgadista ja leiriytyivät Jotbataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Ja he lähtivät Jotbatasta ja leiriytyivät Abronaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Ja he lähtivät Abronasta ja leiriytyivät Esjon-Geberiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Ja he lähtivät Esjon-Geberistä ja leiriytyivät Siinin erämaahan, se on Kaadekseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Ja he lähtivät Kaadeksesta ja leiriytyivät Hoorin vuoren juurelle, Edomin maan rajalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Ja pappi Aaron nousi Hoorin vuorelle Herran käskyn mukaan ja kuoli siellä neljäntenäkymmenentenä vuotena siitä, kun israelilaiset olivat lähteneet Egyptin maasta, viidennessä kuussa, kuukauden ensimmäisenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Ja Aaron oli sadan kahdenkymmenen kolmen vuoden vanha kuollessaan Hoorin vuorella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Mutta Aradin kuningas, kanaanilainen, joka asui Kanaanin maan eteläosassa, sai kuulla israelilaisten tulosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Ja he lähtivät Hoorin vuorelta ja leiriytyivät Salmonaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Ja he lähtivät Salmonasta ja leiriytyivät Puunoniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Ja he lähtivät Puunonista ja leiriytyivät Oobotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Ja he lähtivät Oobotista ja leiriytyivät Iije-Abarimiin Mooabin rajalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Ja he lähtivät Iijimistä ja leiriytyivät Diibon-Gaadiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Ja he lähtivät Diibon-Gaadista ja leiriytyivät Almon-Diblataimiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Ja he lähtivät Almon-Diblataimista ja leiriytyivät Abarimin vuoristoon vastapäätä Neboa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Ja he lähtivät Abarimin vuoristosta ja leiriytyivät Mooabin arolle Jordanin rantaan, Jerikon kohdalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Ja Jordanin rannalla heidän leirinsä ulottui Beet-Jesimotista aina Aabel-Sittimiin asti Mooabin arolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Ja Herra puhui Moosekselle Mooabin arolla Jordanin rannalla, Jerikon kohdalla, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, '\"Puhu israelilaisille ja sano heille: Kun olette kulkeneet Jordanin yli Kanaanin maahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'niin karkoittakaa tieltänne kaikki maan asukkaat ja hävittäkää kaikki heidän jumalankuvansa, hävittäkää kaikki heidän valetut kuvansa ja kukistakaa kaikki heidän uhrikukkulansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Ottakaa sitten maa haltuunne ja asukaa siinä, sillä teille minä annan omaksi sen maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Ja jakakaa maa keskenänne arvalla sukujenne mukaan; suuremmalle antakaa suurempi perintöosa ja pienemmälle pienempi perintöosa. Kukin saakoon perintöosansa siinä, mihin arpa sen hänelle määrää; isienne sukukuntien mukaan jakakaa maa keskenänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Mutta jos ette karkoita maan asukkaita tieltänne, niin ne, jotka te heistä jätätte jäljelle, tulevat teille okaiksi silmiinne ja tutkaimiksi kylkiinne, ja he ahdistavat teitä siinä maassa, jossa te asutte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Ja silloin minä teen teille, niinkuin aioin tehdä heille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, '\"Käske israelilaisia ja sano heille: Kun te tulette Kanaanin maahan-se on se maa, jonka te saatte perintöosaksenne, Kanaanin maa äärestä ääreen-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'niin teidän eteläinen rajanne kulkekoon Siinin erämaasta Edomia pitkin; eteläinen raja alkakoon idässä Suolameren päästä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'ja kääntyköön Skorpionisolasta etelään ja kulkekoon Siiniin, ja se päättyköön Kaades-Barneasta etelään. Sieltä raja lähteköön Hasar-Addariin, kulkekoon Asmoniin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'ja kääntyköön Asmonista Egyptin purolle ja päättyköön mereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Ja teidän läntisenä rajananne olkoon Suuri meri; tämä olkoon läntisenä rajananne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Ja teidän pohjoinen rajanne olkoon tämä: Suuresta merestä vetäkää raja Hoorin vuoreen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Hoorin vuoresta vetäkää raja siihen, mistä mennään Hamatiin, ja raja päättyköön Sedadiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Sieltä raja lähteköön Sifroniin ja päättyköön Hasar-Eenaniin. Tämä olkoon pohjoisena rajananne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Ja itäinen rajanne vetäkää Hasar-Eenanista Sefamiin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Sefamista raja painukoon Riblaan, Ainista itään, ja sieltä raja edelleen painukoon, kunnes se sattuu vuoriselänteeseen Kinneretin järven itäpuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Sitten raja yhtyköön Jordaniin ja päättyköön Suolamereen. Tämä on oleva teidän maanne rajoineen yltympäri.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Ja Mooses käski israelilaisia sanoen: \"Tämä on se maa, joka teidän on jaettava arvalla keskenänne ja jonka Herra määräsi annettavaksi yhdeksälle ja puolelle sukukunnalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Sillä ruubenilaisten sukukunta perhekunnittain ja gaadilaisten sukukunta perhekunnittain ja toinen puoli Manassen sukukuntaa ovat jo saaneet perintöosansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Nämä kaksi ja puoli sukukuntaa ovat jo saaneet perintöosansa tällä puolella Jordania Jerikon kohdalla, itään päin, auringonnousuun päin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, '\"Nämä ovat niiden miesten nimet, joiden on jaettava teille se maa: pappi Eleasar ja Joosua, Nuunin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'ja näiden lisäksi valitkaa päämies kustakin sukukunnasta maata jakamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Nämä ovat niiden miesten nimet: Juudan sukukunnasta Kaaleb, Jefunnen poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'simeonilaisten sukukunnasta Semuel, Ammihudin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Benjaminin sukukunnasta Elidad, Kislonin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'daanilaisten sukukunnasta päämies Bukki, Joglin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'joosefilaisista, manasselaisten sukukunnasta, päämies Hanniel, Eefodin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'efraimilaisten sukukunnasta päämies Kemuel, Siftanin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'sebulonilaisten sukukunnasta päämies Elisafan, Parnakin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'isaskarilaisten sukukunnasta päämies Paltiel, Assanin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'asserilaisten sukukunnasta päämies Ahihud, Selomin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'ja naftalilaisten sukukunnasta Pedahel, Ammihudin poika.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Nämä olivat ne, jotka Herra määräsi jakamaan israelilaisille Kanaanin maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Ja Herra puhui Moosekselle Mooabin arolla Jordanin rannalla, Jerikon kohdalla, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, '\"Käske israelilaisia antamaan omistamistaan perintöosista leeviläisille kaupunkeja heidän asuaksensa ja antamaan leeviläisille myöskin laidunmaata näiden kaupunkien ympäriltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Nämä kaupungit olkoot heillä asuntoina, ja niiden laidunmaat olkoot heidän juhtiansa, karjaansa ja kaikkia muita elukoitansa varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Ja näiden kaupunkien laidunmaat, jotka teidän on annettava leeviläisille, ulottukoot kaupungin muurista ulospäin tuhat kyynärää joka taholle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Ja mitatkaa kaupungin ulkopuolella itään päin kaksituhatta kyynärää ja etelään päin kaksituhatta kyynärää ja länteen päin kaksituhatta kyynärää ja pohjoiseen päin kaksituhatta kyynärää, ja kaupunki olkoon siinä keskellä. Tämä olkoon heillä kaupunkien laidunmaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Ja niistä kaupungeista, jotka teidän on annettava leeviläisille, olkoon kuusi turvakaupunkia, jotka teidän on annettava pakopaikaksi sille, joka on jonkun tappanut; ja niiden lisäksi antakaa neljäkymmentä kaksi kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Kaikkiaan olkoon kaupunkeja ja niiden laidunmaita, jotka teidän on annettava leeviläisille, neljäkymmentä kahdeksan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Ja niitä israelilaisten omistamia kaupunkeja, jotka teidän on annettava, otettakoon useampia siltä sukukunnalta, jolla niitä on paljon, ja vähemmän siltä, jolla niitä on vähemmän. Kukin sukukunta antakoon leeviläisille kaupunkejaan saamansa perintöosan mukaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Ja Herra puhui Moosekselle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, '\"Puhu israelilaisille ja sano heille: Kun te olette menneet Jordanin yli Kanaanin maahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'niin valitkaa itsellenne kaupunkeja turvakaupungeiksenne. Niihin paetkoon tappaja, joka tapaturmaisesti on jonkun surmannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Ja nämä kaupungit olkoot teillä turvapaikkoina verenkostajalta, niin ettei tappajan tarvitse kuolla, ennenkuin hän on ollut seurakunnan tuomittavana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Ja kaupunkeja, jotka teidän on määrättävä turvakaupungeiksi, olkoon teillä kuusi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Kolme kaupunkia teidän on määrättävä tältä puolelta Jordanin, ja kolme kaupunkia teidän on määrättävä Kanaanin maasta; ne olkoot turvakaupunkeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Israelilaisille ja teidän keskuudessanne asuvalle muukalaiselle ja loiselle olkoot ne kuusi kaupunkia turvapaikkoina, joihin voi paeta jokainen, joka tapaturmaisesti jonkun surmaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Mutta jos joku rauta-aseella lyö toista, niin että tämä kuolee, on hän tahallinen tappaja; sellainen tappaja rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Jos joku ottaa käteensä kiven, jolla voi lyödä kuoliaaksi, ja lyö toista, niin että tämä kuolee, on hän tahallinen tappaja; sellainen tappaja rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Tahi jos joku ottaa käteensä puuaseen, jolla voi lyödä kuoliaaksi, ja lyö toista, niin että tämä kuolee, on hän tahallinen tappaja; sellainen tappaja rangaistakoon kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Verenkostaja ottakoon sellaisen tappajan hengiltä; hän ottakoon hänet hengiltä, milloin vain hänet tapaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Ja jos joku vihassa iskee toista tahi heittää häntä jollakin murhaamisen tarkoituksessa, niin että tämä kuolee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'tahi vihaa kantaen lyö häntä kädellään, niin että hän kuolee, rangaistakoon lyöjä kuolemalla, sillä hän on tahallinen tappaja; verenkostaja ottakoon sellaisen tappajan hengiltä, milloin vain hänet tapaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Mutta jos joku vahingossa, vaan ei vihassa, satuttaa toista tai heittää häntä jollakin esineellä, millä hyvänsä, ilman murhaamisen tarkoitusta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'tahi jos hän kivellä, jolla voi lyödä kuoliaaksi, huomaamattansa satuttaa toista, niin että tämä kuolee, eikä hän ollut hänen vihamiehensä eikä tarkoittanut häntä vahingoittaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'niin seurakunta ratkaiskoon tappajan ja verenkostajan välin näiden säädösten mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Ja seurakunta päästäköön tappajan verenkostajan kädestä, ja seurakunta antakoon hänen palata turvakaupunkiin, johon hän oli paennut, ja siellä hän asukoon pyhällä öljyllä voidellun ylimmäisen papin kuolemaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Mutta jos tappaja menee sen turvakaupungin alueen ulkopuolelle, johon hän on paennut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'ja verenkostaja tapaa hänet ulkopuolella hänen turvakaupunkinsa aluetta ja verenkostaja surmaa tappajan, niin ei hän joudu verenvikaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'sillä hänen on asuttava turvakaupungissaan ylimmäisen papin kuolemaan asti. Mutta ylimmäisen papin kuoltua tappaja saa palata perintömaallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Ja tämä olkoon teillä oikeussäädöksenä sukupolvesta sukupolveen, missä asuttekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Jos joku lyö toisen kuoliaaksi, surmattakoon tappaja todistajien antaman todistuksen nojalla; mutta yhden todistajan todistuksen nojalla älköön ketään kuolemalla rangaistako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Älkää ottako lunastusmaksua sellaisen tappajan hengestä, joka on tehnyt hengenrikoksen, vaan rangaistakoon hänet kuolemalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Älkääkä ottako lunastusmaksua siltä, joka on paennut turvakaupunkiin, ettei hän ennen papin kuolemaa saisi palata asumaan omalle maallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Älkääkä saastuttako sitä maata, jossa te olette, sillä veri saastuttaa maan. Ja maalle ei voi toimittaa sovitusta verestä, joka siihen on vuodatettu, muulla kuin sen verellä, joka sen on vuodattanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Älkää siis saastuttako sitä maata, jossa te asutte ja jossa minäkin asun teidän keskellänne, sillä minä, Herra, asun israelilaisten keskellä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Silloin Gileadin, Maakirin pojan, Manassen pojanpojan, suvun perhekuntapäämiehet, jotka olivat Joosefin poikien sukua, astuivat esiin ja puhuivat Moosekselle ja ruhtinaille, israelilaisten perhekunta-päämiehille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'ja sanoivat: \"Herra käski herrani jakaa sen maan arvalla israelilaisille perintöosaksi, ja herrani sai käskyn Herralta antaa Selofhadin, meidän veljemme, perintöosan hänen tyttärillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Mutta jos he joutuvat vaimoiksi joillekin israelilaisten muiden heimojen pojista, niin heidän perintöosansa siirtyy pois meidän isiemme perintöosasta ja liitetään sen sukukunnan perintöosaan, johon he tulevat kuulumaan, mutta meidän perintöosamme vähenee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Ja kun israelilaisten riemuvuosi tulee, niin heidän perintöosansa lisätään sen sukukunnan perintöosaan, johon he tulevat kuulumaan, mutta meidän isiemme sukukunnan perintöosasta vähentyy heidän perintöosansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Silloin Mooses sääti israelilaisille Herran käskyn mukaan, sanoen: \"Joosefilaisten sukukunta puhuu oikein.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Näin Herra säätää Selofhadin tyttäristä: Menkööt he vaimoiksi kenelle tahtovat, kunhan vain menevät vaimoiksi johonkin isänsä sukukunnan sukuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Sillä älköön israelilaisilla perintöosa siirtykö sukukunnasta toiseen, vaan israelilaiset säilyttäkööt kukin isiensä sukukunnan perintöosan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Mutta jokainen tytär, joka saa perintöosan israelilaisten sukukunnissa, menköön vaimoksi johonkin isänsä sukukunnan sukuun, että israelilaiset saisivat periä kukin isiensä perintöosan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'ja ettei perintöosa siirtyisi sukukunnasta toiseen, vaan israelilaisten sukukunnat säilyttäisivät kukin perintöosansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Niinkuin Herra Moosekselle käskyn antoi, niin Selofhadin tyttäret tekivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Ja Mahla, Tirsa, Hogla, Milka ja Nooga, Selofhadin tyttäret, menivät vaimoiksi setiensä pojille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Joosefin pojan Manassen poikien sukuihin he menivät vaimoiksi; ja niin heidän perintöosansa jäi heidän isänsä suvun sukukuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Nämä ovat ne käskyt ja säädökset, jotka Herra Mooseksen kautta antoi israelilaisille Mooabin arolla Jordanin rannalla, Jerikon kohdalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Nämä ovat ne sanat, jotka Mooses puhui kaikelle Israelille, tuolla puolella Jordanin, erämaassa, Aromaassa, vastapäätä Suufia, Paaranin, Toofelin, Laabanin, Haserotin ja Dii-Saahabin välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Hoorebista on yksitoista päivänmatkaa, Seirin vuoriston tietä, Kaades-Barneaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Neljäntenäkymmenentenä vuotena, yhdennessätoista kuussa, kuukauden ensimmäisenä päivänä, Mooses puhui israelilaisille kaiken, mitä Herra oli käskenyt hänen heille puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Tämä tapahtui sen jälkeen, kuin hän oli voittanut Siihonin, amorilaisten kuninkaan, joka asui Hesbonissa, ja Oogin, Baasanin kuninkaan, joka asui Astarotissa, Edrein luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Tuolla puolella Jordanin, Mooabin maassa, Mooses alkoi selittää tätä lakia, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, '\"Herra, meidän Jumalamme, puhui meille Hoorebilla näin: \'Te olette jo tarpeeksi kauan olleet tämän vuoren vaiheilla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'kääntykää toisaalle, lähtekää liikkeelle ja menkää amorilaisten vuoristoon ja kaikkien heidän naapuriensa tykö Aromaahan, Vuoristoon, Alankomaahan, Etelämaahan ja Merenrannikolle, kanaanilaisten maahan ja Libanoniin, aina suureen virtaan, Eufrat-virtaan, saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Katso, minä annan maan teidän valtaanne; menkää ja ottakaa omaksenne se maa, jonka Herra teidän isillenne, Aabrahamille, Iisakille ja Jaakobille, vannotulla valalla on luvannut antaa heille ja heidän jälkeläisillensä.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Ja minä puhuin teille silloin sanoen: \'Minä en jaksa yksin kantaa teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Herra, teidän Jumalanne, on antanut teidän lisääntyä, ja katso, teidän lukunne on tänä päivänä niinkuin taivaan tähtien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Lisätköön Herra, teidän isienne Jumala, teitä vielä tuhatkertaisesti ja siunatkoon teitä, niinkuin hän on teille puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Mutta kuinka minä voin yksin kantaa sitä kuormaa ja taakkaa, joka minulla on teistä ja teidän riitelemisistänne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Tuokaa tänne viisaita, ymmärtäväisiä ja tunnettuja miehiä jokaisesta sukukunnastanne, niin minä asetan heidät teidän päämiehiksenne.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Te vastasitte minulle ja sanoitte: \'Se on hyvä, mitä sinä ehdotat tehtäväksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Silloin minä otin teidän sukukuntienne päämiehet, jotka olivat viisaita ja tunnettuja miehiä, ja asetin heidät teidän päämiehiksenne, tuhannen-,sadan-,viidenkymmenen-ja kymmenenjohtajiksi, ja päällysmiehiksi sukukuntiinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Ja silloin minä käskin teidän tuomareitanne sanoen: \'Kuulustelkaa veljiänne ja tuomitkaa oikein, jos jollakulla on riita-asia veljensä tai luonaan asuvan muukalaisen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Älkää katsoko henkilöön tuomitessanne, vaan kuulkaa pientä yhtä hyvin kuin suurtakin; älkää peljätkö ketään ihmistä, sillä tuomio on Jumalan. Mutta asia, joka on teistä liian vaikea, lykätkää minulle, kuullakseni sen.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Ja silloin minä annoin teille käskyt kaikesta, mitä teidän oli tehtävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Niin me lähdimme liikkeelle Hoorebilta ja kuljimme koko sen suuren ja peljättävän erämaan kautta, jonka te olette nähneet, amorilaisten vuoriston tietä, niinkuin Herra, meidän Jumalamme, oli käskenyt meitä, ja tulimme Kaades-Barneaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Silloin minä sanoin teille: \'Te olette tulleet amorilaisten vuoristoon, jonka Herra, meidän Jumalamme, meille antaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Katso, Herra, sinun Jumalasi, antaa maan sinun valtaasi. Mene ja ota se omaksesi, niinkuin Herra, sinun isiesi Jumala, on sinulle puhunut; älä pelkää äläkä arkaile.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Silloin te astuitte kaikki minun eteeni ja sanoitte: \'Lähettäkäämme miehiä edellämme tutkimaan maata ja antamaan meille tietoja tiestä, jota meidän on sinne mentävä, ja kaupungeista, joihin me tulemme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Tämä puhe oli minun silmissäni hyvä, ja minä otin kaksitoista miestä teidän keskuudestanne, yhden jokaisesta sukukunnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Nämä lähtivät ja nousivat vuoristoon ja tulivat Rypälelaaksoon ja vakoilivat maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Ja he ottivat mukaansa maan hedelmiä ja toivat meille ja antoivat meille tietoja ja sanoivat: \'Maa, jonka Herra, meidän Jumalamme, antaa meille, on hyvä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Mutta te ette tahtoneet mennä sinne, vaan niskoittelitte Herran, teidän Jumalanne, käskyä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Ja te napisitte teltoissanne ja sanoitte: \'Sentähden että Herra vihaa meitä, vei hän meidät pois Egyptin maasta, antaakseen meidät amorilaisten käsiin ja tuhotakseen meidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Mihin me menemme? Veljemme ovat saattaneet meidän rohkeutemme raukeamaan, sillä he sanovat: Siellä on meitä suurempi ja kookkaampi kansa, siellä on suuria, taivaan tasalle varustettuja kaupunkeja; näimmepä siellä anakilaisiakin.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Niin minä vastasin teille: \'Älkää säikähtykö älkääkä peljätkö heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Herra, teidän Jumalanne, joka käy teidän edellänne, taistelee itse teidän puolestanne, aivan niinkuin hän teki teille Egyptissä teidän silmienne edessä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'ja erämaassa, jossa sinä olet nähnyt, kuinka Herra, sinun Jumalasi, on kantanut sinua, niinkuin mies kantaa poikaansa, koko sen matkan, jonka te olette kulkeneet, kunnes tulitte tähän paikkaan.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Mutta sittenkään te ette uskoneet Herraan, teidän Jumalaanne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'joka kävi teidän edellänne tiellä katsoakseen teille leiripaikat: yöllä tulessa, valaistakseen teille tien, jota teidän oli kuljettava, ja päivällä pilvessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Kun Herra kuuli teidän puheenne, vihastui hän ja vannoi sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, '\'Totisesti, ei kukaan näistä miehistä, tästä pahasta sukupolvesta, saa nähdä sitä hyvää maata, jonka minä valalla vannoen olen luvannut antaa teidän isillenne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'ei kukaan, paitsi Kaaleb, Jefunnen poika; hän saa sen nähdä, ja hänelle ja hänen lapsillensa minä annan sen maan, johon hän on astunut, sentähden että hän on uskollisesti seurannut Herraa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Myöskin minuun Herra vihastui teidän tähtenne ja sanoi: \'Et sinäkään sinne pääse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Joosua, Nuunin poika, joka sinua palvelee, hän pääsee sinne; vahvista häntä, sillä hän on jakava maan Israelille perinnöksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Ja teidän lapsenne, joiden sanoitte joutuvan vihollisen saaliiksi, ja teidän poikanne, jotka eivät vielä tiedä, mikä on hyvä, mikä paha, ne pääsevät sinne; heille minä annan maan, ja he ottavat sen omaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Mutta te kääntykää takaisin ja lähtekää liikkeelle erämaahan, Kaislameren tietä.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Silloin te vastasitte ja sanoitte minulle: \'Me olemme tehneet syntiä Herraa vastaan. Me menemme ja taistelemme, aivan niinkuin Herra, meidän Jumalamme, on meitä käskenyt.\' Ja te vyöttäydyitte kaikki sota-aseisiinne ja lähditte kevytmielisesti nousemaan vuoristoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Mutta Herra sanoi minulle: \'Sano heille: Älkää nousko sinne älkääkä antautuko taisteluun, sillä minä en ole teidän keskellänne; älkää tehkö niin, etteivät vihollisenne voittaisi teitä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Ja minä puhuin teille, mutta te ette kuulleet, vaan niskoittelitte Herran käskyä vastaan ja lähditte ylimielisesti vuoristoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Ja amorilaiset, jotka asuvat siinä vuoristossa, lähtivät teitä vastaan ja ajoivat teitä takaa, niinkuin mehiläiset tekevät, ja hajottivat teidät Seirissä, ja aina Hormaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Niin te palasitte ja itkitte Herran edessä. Mutta Herra ei kuullut teidän huutoanne, ei kuunnellut teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Ja teidän täytyi viipyä Kaadeksessa se pitkä aika, minkä siellä viivyitte.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, '\"Sitten me käännyimme toisaalle ja lähdimme liikkeelle erämaahan, Kaislameren tietä, niinkuin Herra oli minulle puhunut, ja kiertelimme kauan aikaa Seirin vuoristossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Ja Herra sanoi minulle näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, '\'Te olette jo tarpeeksi kauan kierrelleet tässä vuoristossa; kääntykää nyt pohjoista kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Ja käske kansaa sanoen: Te tulette kulkemaan Seirissä asuvien veljienne, Eesaun jälkeläisten, alueen kautta. He pelkäävät teitä, mutta te pitäkää itsestänne tarkka vaari:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Älkää ryhtykö taisteluun heidän kanssansa, sillä minä en anna teille jalanleveyttäkään heidän maastansa, koska minä olen antanut Seirin vuoriston Eesaun omaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Rahalla te ostakaa heiltä ruokaa syödäksenne; vesikin hankkikaa heiltä rahalla juodaksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Sillä Herra, sinun Jumalasi, on siunannut sinua kaikissa kättesi töissä. Hän on pitänyt huolen sinun vaelluksestasi tässä suuressa erämaassa. Jo neljäkymmentä vuotta on Herra, sinun Jumalasi, ollut sinun kanssasi, eikä sinulta ole mitään puuttunut.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Niin me lähdimme pois veljiemme, Eesaun jälkeläisten, luota, jotka asuvat Seirissä, poiketen Aromaan tieltä, joka tulee Eelatista ja Esjon-Geberistä. Me käännyimme toisaalle ja lähdimme kulkemaan Mooabin erämaan tietä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Ja Herra sanoi minulle: \'Älä käy Mooabin kimppuun äläkä ryhdy taisteluun heidän kanssaan, sillä minä en anna heidän maastaan mitään sinun omaksesi, koska minä olen antanut Aarin Lootin jälkeläisten omaksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Eemiläiset asuivat muinoin siellä, suuri, lukuisa ja kookas kansa niinkuin anakilaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Ja samoin kuin anakilaiset luettiin heidätkin refalaisiin; mutta mooabilaiset kutsuivat heitä eemiläisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Hoorilaiset sitävastoin asuivat muinoin Seirissä, mutta Eesaun jälkeläiset karkoittivat heidät tieltään ja tuhosivat heidät ja asettuivat heidän sijaansa, samoin kuin Israel teki siinä maassa, jonka Herra oli antanut heidän omaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, '\'Nouskaa siis ja kulkekaa Seredin puron poikki.\' Ja me kuljimme Seredin puron poikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Ja aika, joka kului vaellukseemme Kaades-Barneasta siihen asti, että kuljimme Seredin puron yli, oli kolmekymmentä kahdeksan vuotta, kunnes hävisi koko se sukupolvi, kaikki sotakuntoiset miehet, leiristä, niinkuin Herra oli heille vannonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Myös oli Herran käsi heitä vastaan hävittämässä heitä leiristä, viimeiseen mieheen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Kun kaikki sotakuntoiset miehet olivat kuolleet pois kansasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'puhui Herra minulle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, '\'Sinä kuljet nyt Mooabin alueen kautta, Aarin kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'ja lähestyt ammonilaisia; mutta älä käy heidän kimppuunsa äläkä ryhdy taisteluun heidän kanssansa, sillä minä en anna ammonilaisten maasta mitään omaksesi, koska minä olen antanut sen Lootin jälkeläisten omaksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Tämäkin on luettu refalaisten maaksi; refalaiset asuivat muinoin siellä, mutta ammonilaiset kutsuivat heitä samsumilaisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Ne olivat niinkuin anakilaiset suuri, lukuisa ja kookas kansa. Mutta Herra tuhosi ne heidän tieltänsä; he karkoittivat ne ja asettuivat niiden sijaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Samoin hän on tehnyt Eesaun jälkeläisille, jotka asuvat Seirissä, kun hän tuhosi hoorilaiset heidän tieltänsä; he karkoittivat nämä ja asettuivat heidän sijaansa, ja siellä he asuvat vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Mutta avvilaisille, jotka asuivat maakylissä aina Gassaan asti, tuottivat tuhon kaftorilaiset, jotka olivat lähteneet Kaftorista, ja asettuivat heidän sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, '\'Nouskaa ja lähtekää liikkeelle ja kulkekaa Arnon-joen yli. Katso, minä annan sinun käsiisi amorilaisen Siihonin, Hesbonin kuninkaan, ja hänen maansa. Käy sitä valloittamaan ja ryhdy taisteluun häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Tästä päivästä alkaen minä saatan kauhuun ja pelkoon sinun edessäsi kansat kaiken taivaan alla, niin että, kun ne kuulevat sinusta kerrottavan, ne pelkäävät ja vapisevat sinun edessäsi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Ja minä lähetin sanansaattajat Kedemotin erämaasta Siihonille, Hesbonin kuninkaalle, viemään rauhan tervehdyksen ja sanomaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, '\'Salli minun kulkea maasi kautta. Aina tiellä pysyen minä kuljen, poikkeamatta oikealle tai vasemmalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Anna minun rahalla ostaa ruokaa syödäkseni ja anna minulle rahalla vettä juodakseni; salli vain minun jalkaisin kulkea maasi kautta-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'minkä minulle myönsivät Eesaun jälkeläiset, jotka asuvat Seirissä, ja mooabilaiset, jotka asuvat Aarissa-kunnes menen Jordanin yli siihen maahan, jonka Herra, meidän Jumalamme, meille antaa.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Mutta Siihon, Hesbonin kuningas, ei tahtonut antaa meidän kulkea maansa kautta, sillä Herra, sinun Jumalasi, paadutti hänen mielensä ja kovensi hänen sydämensä, antaakseen hänet sinun käsiisi, niinkuin nyt onkin tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Ja Herra sanoi minulle: \'Katso, minä annan nyt Siihonin ja hänen maansa sinun valtaasi. Ryhdy sitä valloittamaan ja ota hänen maansa omaksesi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Niin Siihon ja kaikki hänen sotaväkensä lähti Jahaaseen taistelemaan meitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Mutta Herra, meidän Jumalamme, antoi hänet meidän valtaamme, ja me voitimme hänet ja hänen poikansa ja kaiken hänen sotaväkensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Ja me valloitimme silloin kaikki hänen kaupunkinsa ja vihimme tuhon omiksi jokaisessa kaupungissa miehet, naiset ja lapset, päästämättä pakoon ainoatakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Ainoastaan karjan me ryöstimme itsellemme ynnä saaliin valloittamistamme kaupungeista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Aroerista, joka on Arnon-joen rannalla, ja jokilaaksossa olevasta kaupungista Gileadiin saakka ei ollut ainoatakaan kaupunkia, joka olisi ollut meille liian korkealla; Herra, meidän Jumalamme, antoi kaikki meidän valtaamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Ainoastaan ammonilaisten maahan sinä et astunut, et mihinkään, mikä on Jabbok-joen varrella, et vuoriston kaupunkeihin etkä mihinkään muuhun, josta Herra, meidän Jumalamme, oli niin määrännyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, '\"Sitten me käännyimme toisaalle ja kuljimme Baasanin tietä. Silloin lähti Oog, Baasanin kuningas, hän ja kaikki hänen sotaväkensä, Edreihin taistelemaan meitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Mutta Herra sanoi minulle: \'Älä pelkää häntä, sillä minä annan sinun käsiisi hänet ja kaiken hänen kansansa ja hänen maansa. Tee hänelle, niinkuin teit Siihonille, amorilaisten kuninkaalle, joka asui Hesbonissa.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Ja niin Herra, meidän Jumalamme, antoi meidän käsiimme myöskin Oogin, Baasanin kuninkaan, ja kaiken hänen sotaväkensä, ja me voitimme hänet, päästämättä pakoon ainoatakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Ja me valloitimme silloin kaikki hänen kaupunkinsa-ei ollut ainoatakaan kaupunkia, jota emme olisi heiltä ottaneet-kuusikymmentä kaupunkia, koko Argobin seudun, Oogin valtakunnan Baasanissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'kaikki nämä kaupungit korkeilla muureilla, porteilla ja salvoilla varustettuja, ja sen lisäksi vielä suuren joukon linnoittamattomia pikkukaupunkeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Ja me vihimme ne tuhon omiksi, niinkuin olimme tehneet Siihonille, Hesbonin kuninkaalle; me vihimme tuhon omiksi jokaisessa kaupungissa miehet, naiset ja lapset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Mutta kaiken karjan ynnä saaliin kaupungeista me ryöstimme itsellemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Niin me otimme silloin kahdelta amorilaisten kuninkaalta, jotka hallitsivat tuolla puolella Jordanin, heidän maansa Arnon-joesta aina Hermonin vuoreen asti-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, 'siidonilaiset kutsuvat Hermonia Sirjoniksi, mutta amorilaiset kutsuvat sitä Seniriksi-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'kaikki ylätasangon kaupungit ja koko Gileadin ja koko Baasanin aina Salkaan ja Edreihin, Baasanissa oleviin Oogin valtakunnan kaupunkeihin, saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Sillä Baasanin kuningas Oog oli yksin enää jäljellä viimeisistä refalaisista. Hänen basaltista tehty ruumisarkkunsa on vieläkin ammonilaisten kaupungissa Rabbassa; se on yhdeksää kyynärää pitkä ja neljää kyynärää leveä, mitattuna tavallisella kyynärämitalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Kun me silloin olimme ottaneet omaksemme tämän maan, annoin minä sen osan siitä, joka alkaa Aroerista, Arnon-joen varrelta, sekä puolet Gileadin vuoristoa kaupunkeineen ruubenilaisille ja gaadilaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Loput Gileadista ja koko Baasanin, Oogin valtakunnan, minä annoin toiselle puolelle Manassen sukukuntaa, koko Argobin seudun; koko tätä Baasania kutsutaan refalaisten maaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jaair, Manassen poika, valtasi koko Argobin seudun aina gesurilaisten ja maakatilaisten alueeseen saakka, ja hän kutsui nämä seudut, se on Baasanin, oman nimensä mukaan Jaairin leirikyliksi, niinkuin niitä kutsutaan vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Ja Maakirille minä annoin Gileadin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Ja ruubenilaisille ja gaadilaisille minä annoin maan Gileadista aina Arnon-jokeen, jokilaakson keskikohtaan saakka, joka on rajana, ja Jabbok-jokeen saakka, joka on ammonilaisten rajana;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'niin myös Aromaan, Jordan rajana, Kinneretistä aina Aromaan mereen, Suolamereen, saakka, Pisgan rinteiden juurelle, itään päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Ja silloin minä käskin teitä ja sanoin: \'Herra, teidän Jumalanne, on antanut teille tämän maan omaksenne. Mutta te, kaikki sotakuntoiset miehet, lähtekää asestettuina veljienne, israelilaisten, etunenässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Ainoastaan vaimonne, lapsenne ja karjanne-sillä minä tiedän teillä olevan paljon karjaa-jääkööt kaupunkeihinne, jotka minä olen teille antanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'kunnes Herra suo veljienne, samoinkuin teidänkin, päästä rauhaan, kun hekin ovat ottaneet omaksensa sen maan, jonka Herra, teidän Jumalanne, antaa teille Jordanin tuolta puolelta; sitten saatte palata takaisin, kukin omistamallensa maalle, jonka minä olen teille antanut.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Ja silloin minä käskin Joosuaa ja sanoin: \'Sinä olet omin silmin nähnyt kaiken, mitä Herra, teidän Jumalanne, on tehnyt näille kahdelle kuninkaalle. Samalla tavalla Herra on tekevä kaikille valtakunnille, joihin sinä menet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Älkää niitä peljätkö, sillä Herra, teidän Jumalanne, sotii itse teidän puolestanne.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Ja silloin minä anoin Herralta armoa sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, '\'Herra, Herra, sinä olet alkanut näyttää palvelijallesi valtasuuruuttasi ja väkevää kättäsi; sillä kuka on se jumala taivaassa tai maassa, joka voi tehdä sellaisia töitä ja niin voimallisia tekoja kuin sinä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Niin salli minun nyt mennä katsomaan sitä hyvää maata, joka on tuolla puolella Jordanin, tuota ihanaa vuoristoa ja Libanonia.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Mutta Herra oli julmistunut minuun teidän tähtenne eikä kuullut minua, vaan sanoi minulle: \'Riittää! Älä puhu minulle enempää tästä asiasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Nouse Pisgan huipulle ja kohota katseesi länteen ja pohjoiseen, etelään ja itään ja katsele silmilläsi; sillä tämän Jordanin yli sinä et mene.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Ja anna määräyksiä Joosualle, vahvista ja rohkaise häntä. Sillä hän menee sinne tämän kansan edellä, ja hän jakaa heille perinnöksi sen maan, jonka sinä näet.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Ja me jäimme laaksoon, vastapäätä Beet-Peoria.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, '\"Ja nyt, Israel, kuule ne käskyt ja säädökset, jotka minä teille opetan, että seuraisitte niitä, eläisitte ja ottaisitte omaksenne sen maan, jonka Herra, teidän isienne Jumala, teille antaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Älkää lisätkö mitään siihen, mitä minä teille määrään, älkääkä ottako siitä mitään pois, vaan noudattakaa Herran, teidän Jumalanne, käskyjä, jotka minä teille annan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Te olette omin silmin nähneet, mitä Herra teki Baal-Peorin asiassa, kuinka Herra, sinun Jumalasi, hävitti sinun keskuudestasi jokaisen, joka lähti kulkemaan Baal-Peorin perässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Mutta te, jotka riipuitte kiinni Herrassa, teidän Jumalassanne, te kaikki olette elossa vielä tänä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Katso, minä olen opettanut teille käskyt ja säädökset, niinkuin Herra, minun Jumalani, on minua käskenyt, että seuraisitte niitä siinä maassa, jota te menette ottamaan omaksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Noudattakaa ja seuratkaa niitä, sillä se on oleva teidän viisautenne ja ymmärryksenne kansojen silmissä. Kun he kuulevat kaikki nämä käskyt, sanovat he: \'Totisesti, viisas ja ymmärtäväinen kansa on tämä suuri kansa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Sillä onko toista suurta kansaa, jonka jumalat ovat sitä niin lähellä, kuin Herra, meidän Jumalamme, on lähellä meitä, niin usein kuin me häntä rukoilemme?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Ja onko toista suurta kansaa, jolla on niin vanhurskaat käskyt ja säädökset, kuin on koko tämä laki, jonka minä tänä päivänä teille annan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Ole vain varuillasi ja ota itsestäsi tarkka vaari, ettet unhota, mitä omin silmin olet nähnyt, ja ettei se lähde sinun sydämestäsi koko elinaikanasi, vaan että ilmoitat sen lapsillesi ja lastesi lapsille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'mitä tapahtui sinä päivänä, jona seisoit Herran, sinun Jumalasi, edessä Hoorebilla, kun Herra sanoi minulle: \'Kokoa kansa, niin minä julistan heille sanani, että he oppisivat pelkäämään minua, niin kauan kuin elävät maan päällä, ja opettaisivat lapsensakin siihen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Ja te astuitte esille ja jäitte seisomaan vuoren juurelle, ja vuori paloi tulena, joka loimusi sisimpään taivaaseen asti pimeyden ja synkkien pilvien keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Ja Herra puhui teille tulen keskeltä. Sanat te kuulitte, mutta ette nähneet hänen muotoansa, kuulitte vain äänen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Ja hän ilmoitti teille liittonsa, jonka hän käski teidän pitää, nimittäin ne kymmenen käskysanaa; ja hän kirjoitti ne kahteen kivitauluun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Ja minun Herra silloin käski opettaa teille käskyt ja säädökset, että te seuraisitte niitä siinä maassa, jota te menette ottamaan omaksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Ottakaa siis itsestänne tarkka vaari-sillä te ette sinä päivänä, jona Herra puhui teille tulen keskeltä Hoorebilla, nähneet hänestä minkäänkaltaista muotoa-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'ettette menettele kelvottomasti ettekä tee itsellenne jumalankuvaa, ette minkään muotoista patsasta, ette miehen tai naisen kuvaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'ette maan päällä liikkuvan nelijalkaisen eläimen kuvaa, ette taivaan alla lentävän siivekkään linnun kuvaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'ette maassa matelevaisen kuvaa ettekä vesissä maan alla olevan kalan kuvaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'ja ettet, kun nostat silmäsi taivasta kohti ja katselet aurinkoa ja kuuta ja tähtiä, kaikkea taivaan joukkoa, anna vietellä itseäsi kumartamaan ja palvelemaan niitä, sillä Herra, sinun Jumalasi, on jakanut ne kaikille muille kansoille koko taivaan alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Onhan Herra ottanut teidät ja vienyt pois rautapätsistä, Egyptistä, että teistä tulisi hänen perintökansansa, niinkuin nyt on tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Mutta Herra vihastui minuun teidän tähtenne ja vannoi, etten minä saa mennä Jordanin yli enkä tulla siihen hyvään maahan, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'vaan että minä kuolen tässä maassa enkä mene Jordanin yli. Mutta te menette sen yli ja otatte tuon hyvän maan omaksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Niin varokaa, ettette unhota Herran, teidän Jumalanne, liittoa, jonka hän on tehnyt teidän kanssanne, ettekä tee itsellenne jumalankuvaa, mitään sen muotoista kuvaa, jota Herra, sinun Jumalasi, on kieltänyt sinua tekemästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Sillä Herra, sinun Jumalasi, on kuluttava tuli, kiivas Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Kun sitten sinulle on syntynyt lapsia ja lasten lapsia ja te olette vanhentuneet maassa, ja jos te silloin menettelette kelvottomasti ja teette itsellenne jumalankuvan, minkämuotoisen kuvan hyvänsä, ja siten teette sitä, mikä on pahaa Herran, sinun Jumalasi, silmissä, ja vihoitatte hänet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'niin minä otan tänä päivänä taivaan ja maan todistajiksi teitä vastaan, että teidät äkkiä hävitetään siitä maasta, johon te menette Jordanin yli ottamaan sen omaksenne; te ette saa kauan elää siellä, vaan teidät tuhotaan kokonaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Ja Herra hajottaa teidät kansojen sekaan, ja ainoastaan vähäinen joukko teitä on jäävä niiden pakanakansojen keskelle, joiden tykö Herra teidät kuljettaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Ja siellä te palvelette jumalia, jotka ovat ihmiskätten tekoa, puuta ja kiveä, jotka eivät näe eivätkä kuule, eivät syö eivätkä hajua tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Mutta sitten sinä siellä etsit Herraa, sinun Jumalaasi, ja sinä löydät hänet, kun kysyt häntä kaikesta sydämestäsi ja kaikesta sielustasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Kun olet ahdistuksessa ja kaikki tämä kohtaa sinua aikojen lopussa, niin sinä palajat Herran, sinun Jumalasi, tykö ja kuulet hänen ääntänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Sillä Herra, sinun Jumalasi, on laupias Jumala. Hän ei jätä sinua eikä hukuta sinua; hän ei unhota sinun isiesi kanssa tekemäänsä liittoa, jonka hän on heille valalla vahvistanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Sillä kysy menneiltä ajoilta, jotka ovat olleet ennen sinua, alkaen siitä päivästä, jona Jumala loi ihmiset maan päälle, kysy taivaan äärestä toiseen: onko koskaan mitään näin suurta tapahtunut, tai onko mitään tällaista ikinä kuultu?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Onko mikään kansa kuullut Jumalan äänen puhuvan tulen keskeltä, niinkuin sinä olet kuullut, ja kuitenkin jäänyt elämään?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Tahi onko mikään jumala koettanut mennä ottamaan itsellensä kansaa toisen kansan keskuudesta koettelemuksilla, tunnusteoilla ja ihmeillä, sodalla, väkevällä kädellä ja ojennetulla käsivarrella ja suurilla, peljättävillä teoilla, minkä kaiken Herra, teidän Jumalanne, on tehnyt teille Egyptissä, sinun silmiesi edessä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Sinun on annettu se nähdä, tietääksesi, että Herra on Jumala, eikä muuta jumalaa ole kuin hän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Taivaasta hän antoi sinun kuulla äänensä opettaaksensa sinua, ja maan päällä hän antoi sinun nähdä suuren tulensa, ja sinä kuulit hänen sanansa tulen keskeltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Koska hän siis rakasti sinun isiäsi ja valitsi heidän jälkeläisensä itselleen ja itse suurella voimallaan vei sinut pois Egyptistä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'karkoittaen sinun tieltäsi kansoja, suurempia ja väkevämpiä kuin sinä, ja tuoden sinut heidän maahansa antaakseen sen sinulle perintöosaksi, niinkuin nyt on tapahtunut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'niin tiedä siis tänä päivänä ja paina se sydämeesi, että Herra on Jumala ylhäällä taivaassa ja alhaalla maan päällä, eikä muuta jumalaa ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Noudata hänen säädöksiänsä ja käskyjänsä, jotka minä tänä päivänä sinulle annan, että sinä ja sinun lapsesi sinun jälkeesi menestyisitte ja että eläisit kauan siinä maassa, jonka Herra, sinun Jumalasi, antaa sinulle ainiaaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Silloin Mooses erotti kolme kaupunkia tuolta puolelta Jordanin, auringon nousun puolelta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'että niihin voisi paeta tappaja, joka on tappanut toisen tahtomattaan ja häntä ennestään vihaamatta; paetkoon hän johonkin näistä kaupungeista, niin hän saa elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Ne olivat: ruubenilaisille Beser erämaassa, ylätasangolla; gaadilaisille Raamot Gileadissa ja manasselaisille Goolan Baasanissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Tämä on se laki, jonka Mooses antoi israelilaisille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'ja nämä ovat ne todistukset, käskyt ja oikeudet, jotka Mooses julisti israelilaisille, heidän lähdettyään Egyptistä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'tuolla puolella Jordanin, laaksossa, vastapäätä Beet-Peoria, Siihonin, amorilaisten kuninkaan, maassa, hänen, joka asui Hesbonissa ja jonka Mooses ja israelilaiset voittivat, lähdettyänsä Egyptistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Ja he ottivat omakseen hänen maansa ja Oogin, Baasanin kuninkaan, maan, kahden amorilaisten kuninkaan maat, jotka ovat tuolla puolella Jordanin, auringon nousuun päin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'alkaen Aroerista, joka on Arnonjoen rannalla, aina Sirjonin vuoreen, se on Hermoniin, saakka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'sekä koko Aromaan, tuolla puolella Jordanin, idän puolella, aina Aromaan mereen saakka, Pisgan rinteiden juurelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Ja Mooses kutsui kokoon kaiken Israelin ja sanoi heille: \"Kuule, Israel, nämä käskyt ja oikeudet, jotka minä tänä päivänä julistan teidän korvienne kuullen. Oppikaa ne ja noudattakaa niitä tarkoin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Herra, meidän Jumalamme, teki liiton meidän kanssamme Hoorebilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Herra ei tehnyt tätä liittoa meidän isiemme kanssa, vaan meidän kanssamme, jotka olemme tässä tänä päivänä, kaikkien meidän kanssamme, jotka nyt elämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Kasvoista kasvoihin Herra puhui teidän kanssanne vuorelta, tulen keskeltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Minä seisoin silloin Herran ja teidän välillänne ja ilmoitin teille Herran sanan, sillä te pelkäsitte tulta ettekä nousseet vuorelle. Hän sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, '\'Minä olen Herra, sinun Jumalasi, joka vein sinut pois Egyptin maasta, orjuuden pesästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Älä pidä muita jumalia minun rinnallani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Älä tee itsellesi jumalankuvaa, älä mitään kuvaa, älä niistä, jotka ovat ylhäällä taivaassa, älä niistä, jotka ovat alhaalla maan päällä, äläkä niistä, jotka ovat vesissä maan alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Älä kumarra niitä äläkä palvele niitä. Sillä minä, Herra, sinun Jumalasi, olen kiivas Jumala, joka kostan isien pahat teot lapsille kolmanteen ja neljänteen polveen, niille, jotka minua vihaavat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'mutta teen laupeuden tuhansille, jotka minua rakastavat ja pitävät minun käskyni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Älä turhaan lausu Herran, sinun Jumalasi, nimeä, sillä Herra ei jätä rankaisematta sitä, joka hänen nimensä turhaan lausuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Ota vaari lepopäivästä, niin että sen pyhität, niinkuin Herra, sinun Jumalasi, on sinua käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Kuusi päivää tee työtä ja toimita kaikki askareesi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'mutta seitsemäs päivä on Herran, sinun Jumalasi, sapatti; silloin älä mitään askaretta toimita, älä sinä älköönkä sinun poikasi tai tyttäresi, sinun palvelijasi tai palvelijattaresi, sinun härkäsi, aasisi tai muu juhtasi älköönkä muukalaisesi, joka sinun porteissasi on, että palvelijasi ja palvelijattaresi saisivat levätä niinkuin sinäkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Ja muista, että itse olit orjana Egyptin maassa ja että Herra, sinun Jumalasi, vei sinut sieltä pois väkevällä kädellä ja ojennetulla käsivarrella. Sentähden Herra, sinun Jumalasi, käski sinun viettää lepopäivän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Kunnioita isääsi ja äitiäsi, niinkuin Herra, sinun Jumalasi, on sinua käskenyt, että kauan eläisit ja menestyisit siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Älä tapa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Älä tee huorin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Älä varasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Älä sano väärää todistusta lähimmäisestäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Älä himoitse lähimmäisesi vaimoa. Älä halaja lähimmäisesi huonetta, älä hänen peltoansa, älä hänen palvelijaansa, palvelijatartansa, härkäänsä, aasiansa, äläkä mitään, mikä on lähimmäisesi omaa.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Nämä sanat Herra puhui koko teidän seurakunnallenne vuorelta, tulen ja synkkien pilvien keskeltä, suurella äänellä, eikä siihen enempää lisännyt. Ja hän kirjoitti ne kahteen kivitauluun ja antoi ne minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Kun te kuulitte äänen pimeyden keskeltä, vuoren palaessa tulena, niin te astuitte minun luokseni, kaikki teidän sukukuntienne päämiehet, niin myös teidän vanhimpanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Ja te sanoitte: \'Katso, Herra, meidän Jumalamme, on antanut meidän nähdä kirkkautensa ja valtasuuruutensa, ja me olemme kuulleet hänen äänensä tulen keskeltä. Tänä päivänä me olemme nähneet, että Jumala voi puhua ihmisen kanssa, ja tämä jää kuitenkin henkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Miksi on meidän siis kuoleminen? Sillä tämä suuri tuli kuluttaa meidät. Jos me vielä kuulemme Herran, meidän Jumalamme, äänen, niin me kuolemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Sillä kuka kaikesta lihasta on koskaan niinkuin me kuullut elävän Jumalan äänen puhuvan tulen keskeltä ja jäänyt henkiin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Astu siis esiin ja kuule kaikki, mitä Herra, meidän Jumalamme, sanoo; ja puhu sinä meille kaikki, mitä Herra, meidän Jumalamme, sinulle puhuu, niin me kuulemme ja teemme.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Ja Herra kuuli teidän puheenne, kun te puhuitte minulle, ja Herra sanoi minulle: \'Minä olen kuullut, mitä tämä kansa on puhunut sinulle. Kaikki, mitä he ovat puhuneet, on oikein puhuttu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Jospa heillä olisi sellainen sydän, että he alati pelkäisivät minua ja noudattaisivat kaikkia minun käskyjäni, niin että he ja heidän lapsensa menestyisivät iankaikkisesti!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Mene siis ja sano heille: Palatkaa majoillenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Mutta jää sinä tähän minun eteeni, niin minä puhun sinulle kaikki ne käskyt, säädökset ja oikeudet, jotka sinun on opetettava heille, että he seuraisivat niitä siinä maassa, jonka minä annan heille omaksi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Niin noudattakaa siis tarkoin niitä, niinkuin Herra, teidän Jumalanne, on teitä käskenyt; älkää poiketko oikealle älkääkä vasemmalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'vaan vaeltakaa aina sitä tietä, jota Herra, teidän Jumalanne, käski teidän vaeltaa, että eläisitte, menestyisitte ja elinpäivänne olisivat pitkät siinä maassa, jonka otatte omaksenne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, '\"Ja nämä ovat ne käskyt, säädökset ja oikeudet, jotka Herra, teidän Jumalanne, on käskenyt teille opettaa, että seuraisitte niitä siinä maassa, jota te menette ottamaan omaksenne');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, '-että sinä pelkäisit Herraa, sinun Jumalaasi, ja noudattaisit kaikkia hänen säädöksiänsä ja käskyjänsä, jotka minä sinulle annan, sekä sinä että sinun poikasi ja poikasi poika, kaikkena elinaikanasi, ja että saisit kauan elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Niin kuule siis, Israel, ja noudata tarkoin niitä, että, niinkuin Herra, sinun isiesi Jumala, on sinulle luvannut, menestyisit ja te lisääntyisitte suuresti siinä maassa, joka vuotaa maitoa ja mettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Kuule, Israel! Herra, meidän Jumalamme, Herra on yksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Ja rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta voimastasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Nämä sanat, jotka minä tänä päivänä sinulle annan, painukoot sydämeesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Ja teroita niitä lastesi mieleen ja puhu niistä kotona istuessasi ja tietä käydessäsi, maata pannessasi ja ylös noustessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Ja sido ne merkiksi käteesi, ja ne olkoot muistolauseena sinun otsallasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Ja kirjoita ne talosi pihtipieliin ja portteihisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Kun Herra, sinun Jumalasi, on vienyt sinut siihen maahan, jonka hän isillesi, Aabrahamille, Iisakille ja Jaakobille, vannotulla valalla on luvannut antaa sinulle-suuret ja kauniit kaupungit, joita sinä et ole rakentanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'ja talot, täynnä kaikkea hyvää, joita sinä et ole täyttänyt, ja kallioon hakatut vesisäiliöt, joita sinä et ole hakannut, viinitarhat ja öljypuut, joita sinä et ole istuttanut-ja kun sinä olet syönyt ja olet ravittu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'niin varo, ettet unhota Herraa, joka vei sinut pois Egyptin maasta, orjuuden pesästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Pelkää Herraa, sinun Jumalaasi, ja palvele häntä ja vanno hänen nimeensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Älkää kulkeko muiden jumalien perässä, niiden kansain jumalien, jotka asuvat teidän ympärillänne-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'sillä Herra, sinun Jumalasi, on kiivas Jumala sinun keskelläsi-ettei Herran, sinun Jumalasi, viha syttyisi sinua vastaan ja hän hävittäisi sinua maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Älkää kiusatko Herraa, teidän Jumalaanne, niinkuin kiusasitte häntä Massassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'vaan noudattakaa Herran, teidän Jumalanne, käskyjä ja niitä todistuksia ja säädöksiä, jotka hän on sinulle antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Ja tee, mikä on oikeata ja hyvää Herran silmissä, että menestyisit ja pääsisit siihen hyvään maahan, jonka Herra valalla vannoen on luvannut sinun isillesi, ja ottaisit sen omaksesi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'ja karkoittaisit tieltäsi kaikki vihollisesi, niinkuin Herra on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Kun poikasi vastaisuudessa kysyy sinulta ja sanoo: \'Mitä merkitsevät ne todistukset, säädökset ja oikeudet, jotka Herra, meidän Jumalamme, on teille antanut?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'niin vastaa pojallesi: \'Me olimme faraon orjia Egyptissä, mutta väkevällä kädellä Herra vei meidät pois Egyptistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Ja Herra teki suuria ja tuhoisia tunnustekoja ja ihmeitä Egyptissä faraolle ja kaikelle hänen hoviväellensä meidän silmiemme edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'mutta meidät hän vei sieltä pois ja johdatti meidät siihen maahan, jonka hän valalla vannoen oli luvannut meidän isillemme, ja antoi sen meille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Ja Herra käski meidän pitää kaikki nämä säädökset ja peljätä Herraa, meidän Jumalaamme, että me aina menestyisimme ja hän pitäisi meitä elossa, niinkuin tähän päivään saakka on tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Ja se on koituva meille vanhurskaudeksi, että tarkoin noudatamme kaikkia näitä käskyjä Herran, meidän Jumalamme, edessä, niinkuin hän on meitä käskenyt.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, '\"Kun Herra, sinun Jumalasi, vie sinut siihen maahan, jota menet ottamaan omaksesi, ja kun hän sinun tieltäsi karkoittaa suuret kansat, heettiläiset, girgasilaiset, amorilaiset, kanaanilaiset, perissiläiset, hivviläiset ja jebusilaiset, nuo seitsemän kansaa, jotka ovat sinua suuremmat ja väkevämmät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'ja kun Herra, sinun Jumalasi, antaa ne sinulle alttiiksi ja sinä voitat ne, niin vihi heidät tuhon omiksi; älä tee liittoa heidän kanssansa äläkä osoita heille armoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Älä lankoudu heidän kanssansa; älä anna tyttäriäsi heidän pojillensa äläkä ota heidän tyttäriänsä pojillesi vaimoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Sillä he viettelevät sinun poikasi luopumaan minusta ja palvelemaan muita jumalia; ja silloin Herran viha syttyy teitä kohtaan, ja hän hävittää sinut nopeasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Vaan tehkää heille näin: kukistakaa heidän alttarinsa, murskatkaa heidän patsaansa, hakatkaa maahan heidän aserakarsikkonsa ja polttakaa tulessa heidän jumalankuvansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Sillä sinä olet Herralle, Jumalallesi, pyhitetty kansa; Herra, sinun Jumalasi, on valinnut sinut omaisuuskansakseen ennen kaikkia muita kansoja, mitä maan päällä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Ei Herra sentähden ole mielistynyt teihin ja valinnut teitä, että olisitte lukuisammat kaikkia muita kansoja, sillä tehän olette kaikkia muita kansoja vähälukuisemmat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'vaan sen tähden, että Herra rakasti teitä ja tahtoi pitää valan, jonka hän oli vannonut teidän isillenne; niin Herra vei teidät pois väkevällä kädellä ja vapahti sinut orjuuden pesästä, faraon, Egyptin kuninkaan, käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Ja tiedä siis, että Herra, sinun Jumalasi, on Jumala, uskollinen Jumala, joka pitää liiton ja on laupias tuhansiin polviin asti niille, jotka häntä rakastavat ja pitävät hänen käskynsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'mutta kostaa sille, joka häntä vihaa, ja hukuttaa hänet. Hän ei vitkastele, vaan kostaa sille, joka häntä vihaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Noudata siis niitä käskyjä, säädöksiä ja oikeuksia, jotka minä tänä päivänä sinulle annan, ja pidä ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Jos te tottelette näitä säädöksiä, noudatatte ja seuraatte niitä, niin Herra, sinun Jumalasi, pitää liittonsa ja on laupias sinulle, niinkuin hän valalla vannoen on sinun isillesi luvannut. 7:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Ja hän rakastaa sinua, siunaa sinua ja antaa sinun lisääntyä; hän siunaa sinun kohtusi hedelmän ja maasi hedelmän, siunaa sinun viljasi, viinisi ja öljysi, sinun raavaittesi vasikat ja lampaittesi karitsat siinä maassa, jonka hän isillesi vannotulla valalla on luvannut antaa sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Siunattu olet sinä oleva yli kaikkien muitten kansojen. Hedelmätöntä miestä tai naista ei ole sinun keskuudessasi oleva, ei myöskään sinun karjassasi yhtään hedelmätöntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Ja Herra on poistava sinusta kaikki sairaudet; ei ainoatakaan Egyptin kovista taudeista, jotka sinä tunnet, hän ole paneva sinun kärsittäväksesi, vaan hän antaa niiden tulla kaikkiin niihin, jotka sinua vihaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Tuhoa kaikki kansat, jotka Herra, sinun Jumalasi, antaa sinulle; älä heitä sääli. Älä myöskään palvele heidän jumaliansa, sillä se tulee sinulle paulaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Vaikka ajatteletkin sydämessäsi: \'Nämä kansat ovat minua suuremmat, kuinka minä voisin ne karkoittaa?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'niin älä kuitenkaan pelkää niitä; muista, mitä Herra, sinun Jumalasi, teki faraolle ja kaikille egyptiläisille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'niitä suuria koettelemuksia, jotka sinä näit omin silmin, ja niitä tunnustekoja ja ihmeitä ja sitä väkevätä kättä ja ojennettua käsivartta, joilla Herra, sinun Jumalasi, vei sinut pois. Samoin on Herra, sinun Jumalasi, tekevä kaikille niille kansoille, joita sinä pelkäät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Niin, Herra, sinun Jumalasi, lähettää heidän kimppuunsa herhiläisiä, kunnes ne, jotka ovat jäljellä ja ovat sinulta piiloutuneet, ovat hävitetyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Älä heitä säikähdy, sillä Herra, sinun Jumalasi, on sinun keskelläsi, suuri ja peljättävä Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Ja Herra, sinun Jumalasi, karkoittaa nämä kansat sinun tieltäsi vähitellen. Älä lopeta heitä yhtäkkiä, etteivät metsän pedot lisääntyisi sinun vahingoksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Herra, sinun Jumalasi, antaa heidät sinulle alttiiksi ja saattaa heidät suureen hämminkiin, kunnes he tuhoutuvat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'ja hän antaa heidän kuninkaansa sinun käsiisi, ja sinä hävität heidän nimensä taivaan alta. Ei kukaan kestä sinun edessäsi, vaan sinä tuhoat heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Heidän jumaliensa kuvat polttakaa tulessa. Älä himoitse hopeata ja kultaa, joka niissä on, äläkä ota siitä itsellesi mitään, ettet joutuisi sen paulaan, sillä se on Herralle, sinun Jumalallesi, kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Äläkä vie sitä kauhistusta taloosi, ettet sinäkin samoin kuin se joutuisi vihittäväksi tuhon omaksi. Katso se inhottavaksi ja kauhistavaksi, sillä se on vihitty tuhon omaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, '\"Pitäkää tarkoin kaikki käskyt, jotka minä tänä päivänä sinulle annan, että eläisitte ja lisääntyisitte ja pääsisitte ottamaan omaksenne sen maan, jonka Herra valalla vannoen on luvannut teidän isillenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Ja muista kaikki, mitä on tapahtunut sillä tiellä, jota Herra, sinun Jumalasi, näinä neljänäkymmenenä vuotena on sinua kuljettanut erämaassa nöyryyttääksensä sinua ja koetellaksensa sinua ja tietääksensä, mitä sinun sydämessäsi on: tahdotko noudattaa hänen käskyjänsä vai etkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Hän nöyryytti sinua ja antoi sinun nähdä nälkää, ja hän antoi sinulle mannaa syödä, jota et ennen tuntenut ja jota eivät isäsikään tunteneet, opettaaksensa sinut ymmärtämään, että ihminen ei elä ainoastaan leivästä, vaan että hän elää jokaisesta sanasta, joka Herran suusta lähtee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Sinun vaatteesi eivät kuluneet yltäsi, eivätkä sinun jalkasi ajettuneet näinä neljänäkymmenenä vuotena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Tiedä siis sydämessäsi, että Herra, sinun Jumalasi, kasvattaa sinua, niinkuin isä kasvattaa poikaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Ja noudata Herran, sinun Jumalasi, käskyjä, vaella hänen teitänsä ja pelkää häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Sillä Herra, sinun Jumalasi, vie sinut hyvään maahan, laaksoissa ja vuorilla vuotavien purojen, lähteiden ja syvien vesien maahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'nisun ja ohran, viiniköynnöksen, viikunapuun ja granaattiomenapuun maahan, jalostetun öljypuun ja hunajan maahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'maahan, jossa sinun ei tarvitse puutteessa leipääsi syödä eikä mitään puutetta nähdä, maahan, jonka kivet ovat rautaa ja jonka vuorista voit louhia vaskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Kun sinä syöt ja tulet ravituksi, niin ylistä Herraa, sinun Jumalaasi, siitä hyvästä maasta, jonka hän on antanut sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Varo, ettet unhota Herraa, sinun Jumalaasi, ja muista noudattaa hänen käskyjänsä, oikeuksiansa ja säädöksiänsä, jotka minä tänä päivänä sinulle annan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Kun sinä syöt ja tulet ravituksi, kun rakennat kauniita taloja ja asut niissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'kun karjasi ja lampaasi lisääntyvät ja kun hopeasi ja kultasi lisääntyy ja kaikki, mitä sinulla on, lisääntyy,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'niin älköön sydämesi ylpistykö, äläkä unhota Herraa, sinun Jumalaasi, joka vei sinut pois Egyptin maasta, orjuuden pesästä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'kuljetti sinua suuressa ja hirmuisessa, myrkyllisten käärmeiden ja skorpionien ja kuivien, vedettömien maiden erämaassa, vuodatti sinulle vettä kovasta kalliosta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'ja antoi erämaassa sinulle mannaa syödä, jota sinun isäsi eivät tunteneet-nöyryyttääksensä ja koetellaksensa sinua ja lopuksi sinulle hyvää tehdäksensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Älä ajattele sydämessäsi: \'Oma voimani ja oman käteni väkevyys on hankkinut minulle tämän rikkauden\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'vaan muista, että Herra, sinun Jumalasi, antaa sinulle voiman hankkia rikkautta pitääkseen liittonsa, jonka hän valalla vannoen teki sinun isiesi kanssa, niinkuin tähän päivään saakka on tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Mutta jos sinä unhotat Herran, sinun Jumalasi, ja seuraat muita jumalia, palvelet niitä ja kumarrat niitä, niin minä vakuutan teille tänä päivänä, että te peräti hukutte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Niinkuin ne kansat, jotka Herra hukuttaa teidän tieltänne, niin tekin hukutte, kun ette kuulleet Herraa, teidän Jumalaanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, '\"Kuule, Israel! Sinä menet nyt Jordanin yli laskeaksesi valtasi alle kansoja, jotka ovat sinua suuremmat ja väkevämmät, ja suuria, taivaan tasalle varustettuja kaupunkeja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'anakilaisten suuren ja kookkaan kansan, jonka sinä tunnet ja josta olet kuullut sanottavan: \'Kuka kestää anakilaisten edessä?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Niin tiedä nyt, että Herra, sinun Jumalasi, käy sinun edelläsi niinkuin kuluttava tuli; hän hävittää heidät ja nöyryyttää heidät sinun edessäsi, ja sinä karkoitat heidät ja hukutat heidät nopeasti, niinkuin Herra on sinulle puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Kun Herra, sinun Jumalasi, työntää heidät sinun tieltäsi, niin älä ajattele sydämessäsi näin: \'Minun vanhurskauteni tähden Herra on tuonut minut ottamaan tämän maan omakseni\'. Sillä näiden kansojen jumalattomuuden tähden Herra karkoittaa heidät sinun tieltäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Et sinä vanhurskautesi ja oikeamielisyytesi tähden pääse ottamaan heidän maatansa omaksesi, vaan näiden kansojen jumalattomuuden tähden Herra, sinun Jumalasi, karkoittaa heidät sinun tieltäsi ja täyttääksensä, mitä Herra valalla vannoen on luvannut sinun isillesi, Aabrahamille, Iisakille ja Jaakobille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Tiedä siis, ettei Herra, sinun Jumalasi, sinun vanhurskautesi tähden anna sinulle tätä hyvää maata omaksesi; sillä sinä olet niskurikansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Muista äläkä unhota, kuinka sinä erämaassa vihoitit Herran, sinun Jumalasi. Siitä päivästä alkaen, jona sinä lähdit Egyptin maasta, aina siihen saakka, kun te tulitte tähän paikkaan, te olette niskoitelleet Herraa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Myöskin Hoorebilla te vihoititte Herran, ja Herra vihastui teihin, niin että hän aikoi tuhota teidät. 9:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Kun minä olin noussut vuorelle vastaanottamaan kivitaulut, sen liiton taulut, jonka Herra oli tehnyt teidän kanssanne, olin minä vuorella neljäkymmentä päivää ja neljäkymmentä yötä syömättä ja juomatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Ja Herra antoi minulle ne kaksi kivitaulua, joihin oli kirjoitettu Jumalan sormella, ja niissä oli kaikki ne sanat, jotka Herra oli puhunut teille vuorelta, tulen keskeltä, silloin kun seurakunta oli koolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Ja niiden neljänkymmenen päivän ja neljänkymmenen yön kuluttua Herra antoi minulle ne kaksi kivitaulua, liitontaulut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Ja Herra sanoi minulle: \'Nouse ja astu nopeasti täältä alas, sillä sinun kansasi, jonka sinä veit pois Egyptistä, on turmion tehnyt. Pian he poikkesivat siltä tieltä, jota minä käskin heidän vaeltaa; he tekivät itselleen valetun kuvan.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Ja Herra puhui minulle sanoen: \'Minä olen nähnyt, että tämä kansa on niskurikansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Anna minun olla, minä tuhoan heidät ja pyyhin pois heidän nimensä taivaan alta. Mutta sinusta minä teen väkevämmän ja lukuisamman kansan, kuin se on.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Silloin minä käännyin ja astuin alas vuorelta, vuoren palaessa tulena; ja minulla oli käsissäni ne kaksi liitontaulua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Ja niin minä näin, että te olitte rikkoneet Herraa, teidän Jumalaanne, vastaan: olitte tehneet itsellenne valetun vasikankuvan, pian poikenneet siltä tieltä, jota Herra oli käskenyt teidän vaeltaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Silloin minä tartuin molempiin tauluihin ja heitin ne käsistäni ja murskasin ne teidän silmienne edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Ja minä heittäydyin Herran eteen ja olin, niinkuin edelliselläkin kerralla, neljäkymmentä päivää ja neljäkymmentä yötä syömättä ja juomatta, kaiken sen synnin tähden, jota te olitte tehneet, kun teitte sitä, mikä on pahaa Herran silmissä, ja vihoititte hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Sillä minä pelkäsin sitä vihaa ja kiivautta teitä vastaan, joka oli vallannut Herran, niin että hän aikoi tuhota teidät. Ja Herra kuuli minua vielä silläkin kertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Myöskin Aaroniin Herra vihastui niin suuresti, että hän aikoi tuhota hänet, ja minä rukoilin silloin myöskin Aaronin puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Sitten minä otin teidän tekemänne syntikuvatuksen, vasikan, ja poltin sen tulessa, löin sen palasiksi ja rouhensin sen hienoksi, aivan kuin tuhaksi, ja sen tuhan minä heitin puroon, joka juoksi vuorelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Tabeerassa, Massassa ja Kibrot-Hattaavassa te vielä vihoititte Herran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Ja kun Herra tahtoi lähettää teidät Kaades-Barneasta ja sanoi: \'Menkää ja ottakaa omaksenne se maa, jonka minä teille annan\', niin te niskoittelitte Herran, teidän Jumalanne, käskyä vastaan ettekä uskoneet häneen ettekä kuulleet hänen ääntänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Te olette niskoitelleet Herraa, teidän Jumalaanne, vastaan aina siitä päivästä alkaen, jona minä opin teidät tuntemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Silloin minä heittäydyin Herran eteen ja olin siinä neljäkymmentä päivää ja neljäkymmentä yötä; sillä Herra oli sanonut aikovansa tuhota teidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Ja minä rukoilin Herraa ja sanoin: Herra, Herra, älä tuhoa kansaasi ja perintöosaasi, jonka sinä suuruudessasi vapahdit ja jonka sinä veit pois Egyptistä väkevällä kädellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Muista palvelijoitasi Aabrahamia, Iisakia ja Jaakobia, älä katso tämän kansan uppiniskaisuutta, jumalattomuutta ja syntiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'ettei sanottaisi siinä maassa, josta sinä veit meidät pois: \'Koska Herra ei kyennyt viemään heitä siihen maahan, jonka hän oli heille luvannut, ja koska hän vihasi heitä, vei hän heidät täältä pois surmatakseen heidät erämaassa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Ovathan he sinun kansasi ja perintöosasi, jonka sinä veit sieltä pois suurella voimallasi ja ojennetulla käsivarrellasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, '\"Silloin Herra sanoi minulle: \'Veistä itsellesi kaksi kivitaulua, entisten kaltaista, ja nouse vuorelle minun tyköni; tee myös itsellesi puusta arkki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Minä kirjoitan niihin tauluihin ne sanat, jotka olivat entisissä tauluissa, niissä, jotka sinä murskasit; pane ne arkkiin.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Niin minä tein arkin akasiapuusta ja veistin kaksi kivitaulua, entisten kaltaista. Ja minä nousin vuorelle, kädessäni ne kaksi taulua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Ja hän kirjoitti tauluihin saman, minkä edellisellä kerralla, ne kymmenen sanaa, jotka Herra oli puhunut teille vuorelta, tulen keskeltä, seurakunnan kokouspäivänä. Ja Herra antoi ne minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Sitten minä käännyin ja astuin alas vuorelta ja panin taulut tekemääni arkkiin, niinkuin Herra oli minua käskenyt, ja siinä ne ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Ja israelilaiset lähtivät liikkeelle Bene-Jaakanin kaivoilta ja vaelsivat Mooseraan. Siellä kuoli Aaron, ja hänet haudattiin sinne; ja hänen poikansa Eleasar tuli papiksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Sieltä he lähtivät liikkeelle Gudgodaan, ja Gudgodasta Jotbataan, seutuun, jossa on vesipuroja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Siihen aikaan Herra erotti Leevin sukukunnan kantamaan Herran liitonarkkia, seisomaan Herran edessä, palvelemaan häntä ja siunaamaan hänen nimeensä, niinkuin tähän päivään saakka on tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Sentähden Leevi ei saanut osuutta eikä perintöosaa veljiensä rinnalla, sillä Herra on hänen perintöosansa, niinkuin Herra, sinun Jumalasi, on hänelle puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Ja minä viivyin vuorella, niinkuin edelliselläkin kerralla, neljäkymmentä päivää ja neljäkymmentä yötä; ja Herra kuuli minua vielä silläkin kertaa, sillä Herra ei tahtonut tuhota sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Ja Herra sanoi minulle: \'Nouse ja lähde, kulje kansan edellä, että he menevät ja ottavat omakseen maan, jonka minä heidän isillensä vannotulla valalla olen luvannut antaa heille\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Ja nyt, Israel, mitä Herra, sinun Jumalasi, sinulta muuta vaatii, kuin että pelkäät Herraa, sinun Jumalaasi, että aina vaellat hänen teitänsä ja rakastat häntä, ja että palvelet Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'noudattaen Herran käskyjä ja säädöksiä, jotka minä sinulle tänä päivänä annan, että menestyisit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Katso, taivaat ja taivasten taivaat, maa ja kaikki, mitä siinä on, ovat Herran, sinun Jumalasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Mutta ainoastaan sinun isiisi Herra mielistyi ja rakasti heitä; ja hän valitsi omikseen heidän jälkeläisensä, hän valitsi teidät kaikista kansoista, niinkuin yhä vielä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Ympärileikatkaa sentähden sydämenne älkääkä olko enää niskureita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Sillä Herra, teidän Jumalanne, on jumalain Jumala ja herrain Herra, suuri, voimallinen ja peljättävä Jumala, joka ei katso henkilöön eikä ota lahjusta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'joka hankkii orvolle ja leskelle oikeuden ja joka rakastaa muukalaista ja antaa hänelle ruuan ja vaatteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Sentähden rakastakaa muukalaista, sillä te olette itse olleet muukalaisina Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Herraa, sinun Jumalaasi, pelkää, häntä palvele, hänessä riipu kiinni ja vanno hänen nimeensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Hän on sinun ylistyksesi, ja hän on sinun Jumalasi, joka on tehnyt sinulle ne suuret ja peljättävät teot, jotka sinun silmäsi ovat nähneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Seitsemänkymmentä henkeä oli sinun isiesi joukkoa, kun he menivät Egyptiin, mutta nyt Herra, sinun Jumalasi, on tehnyt sinun lukusi paljoksi niinkuin taivaan tähdet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, '\"Rakasta siis Herraa, sinun Jumalaasi, ja noudata alati hänen määräyksiänsä, säädöksiänsä, oikeuksiansa ja käskyjänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Ja huomatkaa tänä päivänä, etten minä nyt puhu teidän lapsillenne, jotka eivät ole kokeneet eivätkä nähneet Herran, teidän Jumalanne, kuritusta, hänen suuruuttansa, väkevää kättänsä ja ojennettua käsivarttansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'eivät hänen tunnustekojaan ja töitään, jotka hän teki Egyptissä faraolle, Egyptin kuninkaalle, ja koko hänen maalleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'eivätkä, mitä hän teki egyptiläisten sotajoukolle, heidän hevosillensa ja vaunuillensa, joiden päälle hän vyörytti Kaislameren vedet, kun he ajoivat teitä takaa, ja jotka Herra hukutti, niin ettei heitä enää ole,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'eivätkä, mitä hän teki teille erämaassa, aina siihen saakka, kunnes te tulitte tähän paikkaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'eivätkä, mitä hän teki Daatanille ja Abiramille, Eliabin, Ruubenin pojan, pojille, kun maa avasi kitansa ja koko Israelin keskeltä nielaisi heidät ja heidän perheensä ja majansa ja kaiken, mitä heillä oli mukanansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'vaan minä puhun teille, jotka olette omin silmin nähneet kaikki Herran suuret teot, jotka hän on tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Niin pitäkää kaikki käskyt, jotka minä tänä päivänä teille annan, että te tulisitte voimakkaiksi, menisitte ja ottaisitte omaksenne sen maan, jota nyt menette omaksenne ottamaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'ja että te kauan eläisitte siinä maassa, jonka Herra teidän isillenne vannotulla valalla on luvannut antaa heille ja heidän jälkeläisillensä, maan, joka vuotaa maitoa ja mettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Sillä se maa, jota sinä menet omaksesi ottamaan, ei ole niinkuin Egyptin maa, josta te olette lähteneet ja jota sinä, siemenesi siihen kylvettyäsi, jalalla polkien kastelit niinkuin vihannestarhaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Vaan se maa, jota te menette omaksenne ottamaan, on maa, jossa on vuoria ja laaksoja ja joka juo vettä taivaan sateesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'maa, josta Herra, sinun Jumalasi, pitää huolen ja jota Herran, sinun Jumalasi, silmät aina katsovat, vuoden alusta sen loppuun saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Ja jos nyt tottelette minun käskyjäni, jotka minä tänä päivänä teille annan, niin että rakastatte Herraa, teidän Jumalaanne, ja palvelette häntä kaikesta sydämestänne ja kaikesta sielustanne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'niin minä annan teidän maallenne sateen ajallansa, syyssateen ja kevätsateen, ja sinä saat korjata viljasi ja viinisi ja öljysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Ja minä annan sinun karjallesi ruohoa kedoillasi; ja sinä syöt ja tulet ravituksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Varokaa, ettei teidän sydämenne antaudu vieteltäväksi, niin että poikkeatte pois ja palvelette muita jumalia ja niitä kumarratte;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'muutoin Herran viha syttyy teitä kohtaan, ja hän sulkee taivaan, niin ettei tule sadetta eikä maa anna satoansa, ja te häviätte pian siitä hyvästä maasta, jonka Herra teille antaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Painakaa siis nämä minun sanani sydämeenne ja mieleenne ja sitokaa ne merkiksi käteenne, ja ne olkoot muistolauseena otsallanne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'ja opettakaa ne lapsillenne, niin että puhut niistä kotona istuessasi ja tietä käydessäsi, maata pannessasi ja ylös noustessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Ja kirjoita ne talosi pihtipieliin ja portteihisi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'että te ja teidän lapsenne kauan eläisitte siinä maassa, jonka Herra teidän isillenne vannotulla valalla lupasi antaa heille, niin kauan kuin taivas maan yli kaareutuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Sillä jos te pidätte kaikki nämä käskyt, jotka minä teille annan, ja seuraatte niitä, niin että rakastatte Herraa, teidän Jumalaanne, ja aina vaellatte hänen teitänsä ja riiputte hänessä kiinni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'niin Herra karkoittaa kaikki nämä kansat teidän tieltänne, ja te laskette valtanne alle kansoja, jotka ovat teitä suuremmat ja väkevämmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Mihin paikkaan te jalkanne astutte, se on oleva teidän. Erämaasta ja Libanonista, virrasta, Eufrat-virrasta, aina Länsimereen saakka on teidän alueenne ulottuva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Ei kukaan kestä teidän edessänne. Kauhuun ja peljästykseen teidän edessänne on Herra saattava koko sen maan, johon te astutte, niinkuin hän on teille puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Katso, minä asetan tänä päivänä teidän eteenne siunauksen ja kirouksen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'siunauksen, jos te tottelette Herran, teidän Jumalanne, käskyjä, jotka minä tänä päivänä teille annan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'mutta kirouksen, jos te ette tottele Herran, teidän Jumalanne, käskyjä, vaan poikkeatte siltä tieltä, jota minä tänä päivänä käsken teidän vaeltaa, ja seuraatte muita jumalia, joita te ette tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Ja kun Herra, sinun Jumalasi, on vienyt sinut siihen maahan, jota sinä nyt menet omaksesi ottamaan, niin tee Garissimin vuoresta siunauksen paikka ja Eebalin vuoresta kirouksen paikka.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Ne ovat toisella puolella Jordanin, länteen päin auringonlaskun tiestä, kanaanilaisten maassa, niiden, jotka asuvat Aromaassa, vastapäätä Gilgalia, Mooren tammiston luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, '\"Sillä te kuljette Jordanin yli ja menette ottamaan omaksenne sen maan, jonka Herra, teidän Jumalanne, teille antaa. Kun sitten olette ottaneet sen omaksenne ja asettuneet siihen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'niin noudattakaa tarkoin kaikkia niitä käskyjä ja oikeuksia, jotka minä tänä päivänä teille annan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, '\"Nämä ovat ne käskyt ja oikeudet, joita teidän on tarkoin noudatettava siinä maassa, jonka Herra, sinun isiesi Jumala, sinulle antaa, että ottaisit sen omaksesi-noudatettava niin kauan kuin elätte maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Hävittäkää perin pohjin kaikki ne paikat, missä karkoittamanne kansat ovat jumaliansa palvelleet, korkeilla vuorilla, kukkuloilla tai viheriäin puiden alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Kukistakaa heidän alttarinsa, murskatkaa heidän patsaansa, polttakaa tulessa heidän asera-karsikkonsa ja hakatkaa maahan heidän jumaliensa kuvat, ja hävittäkää heidän nimensä niistä paikoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Palvellessanne Herraa, teidän Jumalaanne, älkää tehkö niinkuin he,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'vaan se paikka, jonka Herra, teidän Jumalanne, valitsee teidän sukukuntienne alueelta ja johon hän asettaa nimensä asuaksensa siellä, se etsikää, ja mene sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Ja sinne viekää polttouhrinne ja teurasuhrinne, kymmenyksenne, kätenne anti, lupausuhrinne ja vapaaehtoiset uhrinne sekä raavaittenne ja lampaittenne esikoiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Ja siellä syökää Herran, teidän Jumalanne, edessä, ja iloitkaa perheinenne kaikesta, mitä kätenne on hankkinut, millä Herra, sinun Jumalasi, on sinua siunannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Älkää tehkö, niinkuin me tässä tänä päivänä teemme, jokainen sitä, mikä hänen omasta mielestään on oikein,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'sillä te ette vielä ole päässeet lepoon ettekä siihen perintömaahan, jonka Herra, sinun Jumalasi, on sinulle antava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Mutta kun olette menneet Jordanin yli ja asettuneet siihen maahan, jonka Herra, teidän Jumalanne, jakaa teille perinnöksi, ja kun hän on suonut teidän päästä rauhaan kaikista vihollisistanne joka taholta, niin että asutte turvassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'silloin viekää siihen paikkaan, jonka Herra, teidän Jumalanne, valitsee nimensä asuinsijaksi, kaikki, mitä minä käsken teidän viedä: polttouhrinne ja teurasuhrinne, kymmenyksenne, kätenne anti, niin myös kaikki parhaat lupausuhrinne, jotka te lupaatte Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Ja iloitkaa Herran, teidän Jumalanne, edessä, sekä te että teidän poikanne ja tyttärenne, palvelijanne ja palvelijattarenne, ja leeviläiset, jotka asuvat teidän porttienne sisäpuolella, sillä heillä ei ole osuutta eikä perintöosaa teidän rinnallanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Varo, ettet uhraa polttouhrejasi missä mieleisessäsi paikassa hyvänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Vaan siinä paikassa, jonka Herra valitsee jonkun sinun sukukuntasi alueelta, siinä uhraa polttouhrisi ja tee kaikki, mitä minä käsken sinun tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Kuitenkin saat kaikkialla porttiesi sisäpuolella teurastaa mielinmäärin ja syödä lihaa, sen mukaan kuin Herra, sinun Jumalasi, sinulle siunaa. Sekä saastainen että puhdas saakoon syödä sitä, niinkuin syödään gasellia tai peuraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Vain verta älkää syökö, vuodattakaa se maahan niinkuin vesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Sinä et saa omien porttiesi sisäpuolella syödä jyviesi, viinisi ja öljysi kymmenyksiä etkä myöskään raavaittesi ja lampaittesi esikoisia etkä mitään lupaamaasi lupausuhria tai vapaaehtoisia uhreja tai kätesi antia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'vaan syö niitä Herran, sinun Jumalasi, edessä siinä paikassa, jonka Herra, sinun Jumalasi, valitsee, sekä sinä että sinun poikasi ja tyttäresi, sinun palvelijasi ja palvelijattaresi ja leeviläinen, joka asuu sinun porttiesi sisäpuolella; ja iloitse näin Herran, sinun Jumalasi, edessä kaikesta, mitä kätesi on hankkinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Varo, ettet jätä osattomaksi leeviläistä, niin kauan kuin sinä elät maassasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Kun Herra, sinun Jumalasi, on laajentanut sinun alueesi, niinkuin hän on sinulle luvannut, ja sinä ajattelet: \'Minä tahdon syödä lihaa\' -koska haluat syödä lihaa-niin syö lihaa mielinmäärin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Jos se paikka, jonka Herra, sinun Jumalasi, valitsee asettaakseen siihen nimensä, on liian kaukana sinusta, niin teurasta, niinkuin minä olen sinua käskenyt, raavaitasi ja lampaitasi, joita Herra on sinulle antanut, ja syö niitä porttiesi sisäpuolella mielinmäärin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Mutta syö niitä, niinkuin syödään gasellia ja peuraa; niinhyvin saastainen kuin puhdas saakoon syödä niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Ole vain luja siinä, ettet syö verta; sillä veri on sielu, ja sielua sinun ei pidä syömän lihan kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Älä syö sitä; vuodata se maahan niinkuin vesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Älä syö sitä, että menestyisit, sinä ja sinun lapsesi sinun jälkeesi, kun teet, mikä oikeata on Herran silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Mutta pyhät lahjasi, jotka sinä tuot, sekä lupausuhrisi, ota ja vie siihen paikkaan, jonka Herra on valinnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Ja uhraa polttouhrisi, sekä liha että veri, Herran, sinun Jumalasi, alttarilla. Teurasuhreistasi vuodatettakoon veri Herran, sinun Jumalasi, alttarille, mutta lihan sinä saat syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Noudata ja tottele kaikkia näitä sanoja, jotka minä sinulle annan, että menestyisit, sinä ja sinun lapsesi sinun jälkeesi, ikuisesti, kun teet sitä, mikä on hyvää ja oikeata Herran, sinun Jumalasi, silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Kun Herra, sinun Jumalasi, on hävittänyt ne kansat, joita sinä menet karkoittamaan tieltäsi, ja kun olet karkoittanut heidät ja asettunut heidän maahansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'niin varo, sittenkuin he ovat hävitetyt sinun tieltäsi, ettet kietoudu heidän pauloihinsa, heitä seuraamaan, ja ettet etsi heidän jumaliansa ja kysy: \'Miten oli näiden kansojen tapana palvella jumaliansa, että minäkin tekisin niin?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Älä tee niin Herraa, sinun Jumalaasi, kohtaan, sillä kaikkea, mikä on Herralle kauhistus ja mitä hän vihaa, he ovat tehneet palvellessaan jumaliansa: omia poikiansakin ja tyttäriänsä he ovat jumalillensa polttaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Kaikkea, mitä minä käsken, noudattakaa tarkoin. Älkää siihen mitään lisätkö älkääkä siitä mitään ottako pois.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, '\"Jos teidän keskuuteenne ilmestyy profeetta tai unennäkijä ja lupaa sinulle jonkun tunnusteon tai ihmeen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'ja jos sitten todellakin tapahtuu se tunnusteko tai ihme, josta hän puhui sinulle sanoen: \'Lähtekäämme seuraamaan muita jumalia, joita te ette tunne, ja palvelkaamme niitä\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'niin älä kuuntele sen profeetan puhetta tai sitä unennäkijää, sillä Herra, teidän Jumalanne, ainoastaan koettelee teitä tietääksensä, rakastatteko Herraa, teidän Jumalaanne, kaikesta sydämestänne ja kaikesta sielustanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Seuratkaa Herraa, teidän Jumalaanne, häntä peljätkää ja pitäkää hänen käskynsä, häntä kuulkaa, häntä palvelkaa ja hänessä kiinni riippukaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Mutta se profeetta tai unennäkijä surmattakoon, sillä hän on julistanut luopumusta Herrasta, teidän Jumalastanne, joka vei teidät pois Egyptin maasta ja vapahti sinut orjuuden pesästä, ja on tahtonut vietellä sinut siltä tieltä, jota Herra, sinun Jumalasi, käski sinun vaeltaa. Poista paha keskuudestasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Jos sinun veljesi, sinun äitisi poika, tai sinun poikasi tai tyttäresi tai vaimo, joka on sylissäsi, tai ystäväsi, joka on sinulle kuin oma sielusi, salaa houkuttelisi sinua ja sanoisi: \'Käykäämme palvelemaan muita jumalia\', joita et sinä tunne eivätkä sinun isäsi tunteneet-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'niiden kansojen jumalia, jotka asuvat teidän ympärillänne, lähellä sinua tai kaukana sinusta, maan äärestä toiseen-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'niin älä noudata hänen mieltään äläkä kuule häntä; älä sääli äläkä armahda häntä äläkä salaa hänen rikostansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'vaan tapa hänet: oma kätesi kohotkoon ensimmäisenä häntä vastaan surmatakseen hänet, ja sitten koko kansan käsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Kivitä hänet kuoliaaksi, sillä hän koetti saada sinut luopumaan Herrasta, sinun Jumalastasi, joka vei sinut pois Egyptin maasta, orjuuden pesästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Ja koko Israel kuulkoon sen ja peljätköön, ettei kukaan enää tekisi senkaltaista pahaa sinun keskuudessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Jos sinä kuulet sanottavan, että jossakin kaupungeistasi, jotka Herra, sinun Jumalasi, antaa sinun asuttaviksesi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'sinun keskuudestasi on lähtenyt kelvottomia miehiä, jotka viettelevät kaupunkinsa asukkaita sanoen: \'Käykäämme palvelemaan muita jumalia\', joita te ette tunne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'niin tutki, tiedustele ja kysele tarkoin; ja jos on totta ja varmaa, että sellaista kauhistusta on harjoitettu sinun keskuudessasi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'niin surmaa sen kaupungin asukkaat miekan terällä ja vihi tuhon omaksi se ja kaikki, mitä siinä on, ja tapa sen karjakin miekan terällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'Ja kokoa kaikki siitä otettu saalis keskelle sen toria ja polta tulella sekä kaupunki että kaikki siitä otettu saalis kokonaisuhrina Herralle, sinun Jumalallesi; ja jääköön se rauniokummuksi iankaikkisesti, älköönkä sitä koskaan enää rakennettako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Älköön siitä tuhon omaksi vihitystä mitään tarttuko sinun käsiisi, että Herra kääntyisi pois vihansa hehkusta, antaisi sinulle armon ja armahtaisi sinua ja sallisi sinun lisääntyä, niinkuin hän on vannonut sinun isillesi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'jos sinä vain kuulet Herran, sinun Jumalasi ääntä ja pidät kaikki hänen käskynsä, jotka minä tänä päivänä sinulle annan, ja teet sitä, mikä on oikein Herran, sinun Jumalasi, silmissä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, '\"Te olette Herran, teidän Jumalanne, lapsia. Älkää viileskelkö ihoanne älkääkä ajako paljaaksi päätänne otsapuolelta vainajan tähden,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'sillä sinä olet Herralle, sinun Jumalallesi, pyhitetty kansa, ja Herra on valinnut sinut omaisuuskansakseen ennen kaikkia muita kansoja, mitä maan päällä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Älä syö mitään, mikä on kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Nämä ovat ne nelijalkaiset eläimet, joita saatte syödä: raavas, lammas ja vuohi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'peura, gaselli, metsäkauris, vuorikauris, musta antilooppi, keihäsantilooppi ja betsoari-vuohi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'kaikki ne nelijalkaiset eläimet, joilla on kokonansa halkinaiset, kaksivarpaiset sorkat ja jotka märehtivät; niitä saatte syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Näitä älkää kuitenkaan syökö niistä, jotka märehtivät, ja niistä, joilla on kokonansa halkinaiset sorkat: kamelia, jänistä ja tamaania, jotka kyllä märehtivät, mutta joilla ei ole sorkkia: ne olkoot teille saastaiset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'sikaa, jolla kyllä on sorkat, mutta joka ei märehdi: se olkoon teille saastainen. Näiden lihaa älkää syökö, ja niiden raatoihin älkää koskeko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Näitä te saatte syödä kaikista vesieläimistä: kaikkia, joilla on evät ja suomukset, te saatte syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Mutta kaikista niistä, joilla ei ole eviä eikä suomuksia, älkää syökö mitään: ne olkoot teille saastaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Kaikkia puhtaita lintuja te saatte syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Mutta nämä ovat linnuista ne, joita älkää syökö: kotka, partakorppikotka, harmaa korppikotka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'haarahaukka ja suohaukkalajit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'kaikki kaarnelajit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'kamelikurki, pääskynen, kalalokki, jalohaukkalajit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'huuhkaja, kissapöllö, sarvipöllö,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'pelikaani, likakorppikotka, kalasääksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'haikara, sirriäislajit, harjalintu ja yölepakko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Myöskin kaikki siivelliset pikkueläimet olkoot teille saastaiset, niitä älköön syötäkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Kaikkia puhtaita siivellisiä te saatte syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Älkää syökö mitään itsestään kuollutta. Muukalaiselle, joka sinun porteissasi on, sinä saat antaa sitä syötäväksi, tahi myy se vieraalle; sillä sinä olet Herralle, sinun Jumalallesi, pyhitetty kansa. Älä keitä vohlaa emänsä maidossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Kaikesta kylvösi sadosta, joka kasvaa pellollasi, anna joka vuosi kymmenykset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'ja syö ne Herran, sinun Jumalasi, edessä, siinä paikassa, jonka hän valitsee nimensä asuinsijaksi: kymmenykset jyvistäsi, viinistäsi ja öljystäsi, niin myös raavaittesi ja lampaittesi esikoiset, että oppisit pelkäämään Herraa, sinun Jumalaasi, kaikkena elinaikanasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Mutta jos tie on sinulle liian pitkä, niin ettet voi kantaa kannettavaasi, koska se paikka, jonka Herra, sinun Jumalasi, on valinnut asettaakseen siihen nimensä, on sinulle liian kaukana, -sillä Herra, sinun Jumalasi on sinua siunaava-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'niin muuta se rahaksi, pane raha kääröön, ota käteesi ja mene siihen paikkaan, jonka Herra, sinun Jumalasi, valitsee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'ja osta sillä rahalla kaikkea, mitä haluat, joko raavaita tai lampaita, viiniä tai väkijuomaa, kaikkea, mitä mielesi tekee, ja syö siellä Herran, sinun Jumalasi, edessä ja iloitse, sinä ja perheesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Äläkä jätä osattomaksi leeviläistä, joka asuu sinun porttiesi sisäpuolella, sillä hänellä ei ole osuutta eikä perintöosaa sinun rinnallasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Joka kolmas vuosi tuo kaikki kymmenykset sinä vuonna saamastasi sadosta ja pane ne talteen porttiesi sisäpuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Ja sitten tulkoon leeviläinen, jolla ei ole osuutta eikä perintöosaa sinun rinnallasi, niin myös muukalainen, orpo ja leski, jotka asuvat sinun porttiesi sisäpuolella, ja he syökööt ja tulkoot ravituiksi, että Herra, sinun Jumalasi, siunaisi sinua kaikissa kättesi töissä, joita teet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, '\"Joka seitsemäs vuosi pane toimeen vapautus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Ja näin on vapautuksesta määrätty: jokainen saamamies luopukoon siitä, minkä hän on lähimmäiselleen lainannut, älköönkä velkoko lähimmäistänsä ja veljeänsä, sillä silloin on Herran kunniaksi vapautus julistettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Vierasta saat velkoa, mutta luovu siitä, mitä sinulla on saamista veljeltäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Tosin ei köyhää sinun keskuudessasi tulisi ollakaan, sillä Herra on runsaasti siunaava sinua siinä maassa, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi ja jonka saat ottaa omaksesi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'jos vain kuulet Herran, sinun Jumalasi, ääntä ja tarkoin noudatat kaikkia näitä käskyjä, jotka minä tänä päivänä sinulle annan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Sillä Herra, sinun Jumalasi, on siunaava sinua, niinkuin hän on sinulle puhunut; ja sinä lainaat monelle kansalle, mutta sinun ei tarvitse lainaa ottaa, ja sinä vallitset monia kansoja, mutta he eivät vallitse sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Jos sinun keskuudessasi on joku köyhä, joku veljesi jossakin porttiesi sisäpuolella siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa, niin älä kovenna sydäntäsi äläkä sulje kättäsi köyhältä veljeltäsi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'vaan avaa auliisti kätesi hänelle ja lainaa mielelläsi, mitä hän puutteessansa tarvitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Varo, ettei sydämessäsi synny tämä paha ajatus: \'Seitsemäs vuosi, vapautusvuosi, on lähellä\', ja ettet sen tähden katso karsaasti köyhää veljeäsi etkä anna hänelle mitään. Jos hän silloin huutaa sinun tähtesi Herran puoleen, niin sinä joudut syyhyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Anna mielelläsi hänelle, älköönkä sydämesi olko vastahakoinen antaessasi, sillä lahjasi tähden on Herra, sinun Jumalasi, siunaava sinua kaikissa töissäsi, kaikessa, mihin ryhdyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Koska köyhiä ei koskaan puutu maasta, sentähden käsken minä sinua näin: Avaa auliisti kätesi veljellesi, kurjalle ja köyhälle, joita sinun maassasi on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Jos joku veljesi, hebrealainen mies tai nainen, on myynyt itsensä sinulle ja palvellut sinua kuusi vuotta, niin päästä hänet seitsemäntenä vuotena luotasi vapaaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'ja kun päästät hänet luotasi vapaaksi, niin älä lähetä häntä tyhjin käsin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Vaan sälytä hänen selkäänsä runsaasti lahjoja laumastasi, puimatantereeltasi ja kuurnastasi; anna hänellekin siitä, millä Herra, sinun Jumalasi, on sinua siunannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Muista, että itse olit orjana Egyptin maassa ja että Herra, sinun Jumalasi, vapahti sinut. Sentähden minä tänä päivänä annan sinulle tämän käskyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Mutta jos hän sanoo sinulle: \'En tahdo lähteä luotasi\', koska hän rakastaa sinua ja sinun perhettäsi ja koska hänen on ollut sinun luonasi hyvä olla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'niin ota naskali ja pistä se hänen korvansa läpi oveen; olkoon hän sitten sinun orjasi ainiaan. Samoin tee myös orjattarellesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Älköön sinusta olko vaikeata päästää häntä luotasi vapaaksi: onhan hänestä kuutena vuotena ollut sinulle kahta vertaa suurempi hyöty kuin palkkalaisesta. Ja Herra, sinun Jumalasi, on siunaava sinua kaikessa, mitä teet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Kaikki urospuoliset esikoiset, jotka syntyvät raavaskarjassasi ja pikkukarjassasi, pyhitä Herralle, Jumalallesi; raavaasi esikoisella älä työtä tee, älä myöskään keritse lampaasi esikoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Herran, sinun Jumalasi, edessä syö perheinesi se joka vuosi siinä paikassa, jonka Herra valitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Jos siinä on joku vamma, jos se ontuu tai on sokea tai jos sillä on joku muu paha vamma, mikä tahansa, niin älä uhraa sitä Herralle, sinun Jumalallesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'Syö se porttiesi sisäpuolella; niin hyvin saastainen kuin puhdas saakoon syödä sitä, niinkuin syödään gasellia tai peuraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Vain verta älä syö; vuodata se maahan niinkuin vesi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, '\"Ota vaari aabib-kuusta ja vietä pääsiäinen Herran, sinun Jumalasi, kunniaksi, sillä aabib-kuussa Herra, sinun Jumalasi, vei sinut pois Egyptistä, yöllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Ja teurasta Herralle, sinun Jumalallesi, pääsiäisuhri, lampaita ja raavaita, siinä paikassa, jonka Herra valitsee nimensä asuinsijaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Älä syö sen ohella hapanta. Syö seitsemänä päivänä sen ohella happamatonta leipää, kurjuuden leipää-sillä kiiruusti sinä lähdit pois Egyptin maasta-että alati muistaisit sitä päivää, jona lähdit Egyptin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Seitsemään päivään älköön hapanta taikinaa olko koko sinun maassasi; ja siitä, mitä teurastat ensimmäisen päivän ehtoona, älköön mitään lihaa jääkö yön yli seuraavaan aamuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Sinä et saa teurastaa pääsiäisuhria niiden kaupunkiesi porttien sisäpuolella, jotka Herra, sinun Jumalasi, sinulle antaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'vaan siinä paikassa, jonka Herra, sinun Jumalasi, valitsee nimensä asuinsijaksi, teurasta pääsiäisuhri, ehtoolla, auringon laskiessa, sinä määrähetkenä, jona Egyptistä lähdit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Ja keitä ja syö se siinä paikassa, jonka Herra, sinun Jumalasi, valitsee; aamulla saat sitten lähteä paluumatkalle ja mennä kotiisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Kuutena päivänä syö happamatonta leipää, ja seitsemäntenä päivänä olkoon juhlakokous Herran, sinun Jumalasi, kunniaksi; älä silloin yhtäkään askaretta toimita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Laske seitsemän viikkoa; siitä alkaen, kun sirppi ensi kerran olkeen pannaan, laske seitsemän viikkoa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'ja vietä viikkojuhla Herran, sinun Jumalasi, kunniaksi kätesi vapaaehtoisin lahjoin, joita sinä annat sen mukaan, kuin Herra, sinun Jumalasi, on sinulle siunausta antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Ja iloitse Herran, sinun Jumalasi, edessä, sinä ja sinun poikasi ja tyttäresi, palvelijasi ja palvelijattaresi, leeviläinen, joka asuu sinun porttiesi sisäpuolella, muukalainen, orpo ja leski, jotka sinun keskuudessasi ovat, siinä paikassa, jonka Herra, sinun Jumalasi, valitsee nimensä asuinsijaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Ja muista, että itse olit orjana Egyptissä, ja noudata tarkoin näitä käskyjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Lehtimajanjuhlaa vietä seitsemän päivää, korjatessasi satoa puimatantereeltasi ja kuurnastasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Ja iloitse tänä juhlanasi, sinä ja sinun poikasi ja tyttäresi, palvelijasi ja palvelijattaresi, leeviläinen, muukalainen, orpo ja leski, jotka asuvat sinun porttiesi sisäpuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Seitsemän päivää juhli Herran, sinun Jumalasi, kunniaksi siinä paikassa, jonka Herra valitsee; sillä Herra, sinun Jumalasi, on siunaava sinua kaikessa, minkä satona saat, ja kaikissa kättesi töissä; sentähden ole iloinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Kolme kertaa vuodessa tulkoon kaikki sinun miesväkesi Herran, sinun Jumalasi, kasvojen eteen siihen paikkaan, jonka hän valitsee: happamattoman leivän juhlana, viikkojuhlana ja lehtimajanjuhlana. Mutta tyhjin käsin älköön tultako Herran kasvojen eteen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'kukin tuokoon lahjana sen, minkä voi, sen siunauksen mukaan, minkä Herra, sinun Jumalasi, on sinulle antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Aseta tuomarit ja päällysmiehet eri sukukuntiasi varten kaikkien niiden kaupunkiesi portteihin, jotka Herra, sinun Jumalasi, sinulle antaa; he tuomitkoot kansaa oikein.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Älä vääristä oikeutta, älä katso henkilöön äläkä ota lahjusta, sillä lahjus sokaisee viisaiden silmät ja vääristää syyttömien asiat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Vanhurskautta, ainoastaan vanhurskautta harrasta, että eläisit ja ottaisit omaksesi sen maan, jonka Herra, sinun Jumalasi, sinulle antaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Älä pystytä itsellesi asera-karsikoita, älä mitään puuta, Herran, sinun Jumalasi, alttarin viereen, jonka itsellesi teet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Älä myöskään pystytä itsellesi patsasta, sillä niitä Herra, sinun Jumalasi, vihaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, '\"Älä uhraa Herralle, sinun Jumalallesi, raavasta tai lammasta, jossa on joku vamma, mikä paha vika tahansa, sillä se on kauhistus Herralle, sinun Jumalallesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Jos sinun keskuudessasi, niiden kaupunkiesi porttien sisäpuolella, jotka Herra, sinun Jumalasi, sinulle antaa, on mies tai nainen, joka tekee sitä, mikä on pahaa Herran, sinun Jumalasi, silmissä, rikkoo hänen liittonsa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'ja menee ja palvelee muita jumalia ja kumartaa niitä: aurinkoa, kuuta tai kaikkea taivaan joukkoa, minkä minä olen kieltänyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'ja siitä ilmoitetaan sinulle, niin että saat sen kuulla, niin tutki asia tarkoin, ja jos on totta ja varmaa, että sellaista kauhistusta on harjoitettu Israelissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'niin vie se mies tai se nainen, joka on sellaisen pahan tehnyt, porttiesi edustalle-se mies tai se nainen-ja kivitä heidät kuoliaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Kahden tai kolmen todistajan todistuksen nojalla kuolemaan tuomittu surmattakoon; yhden ainoan todistajan todistuksen nojalla älköön häntä surmattako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Todistajien käsi kohotkoon ensimmäisenä häntä vastaan surmatakseen hänet, ja sitten koko kansan käsi. Poista paha keskuudestasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Jos joku murhaa tai omaisuusriitaa tai pahoinpitelyä koskeva asia tai mikä muu asia hyvänsä, josta sinun porteissasi riidellään, näyttää sinusta liian vaikealta ratkaista, niin nouse ja lähde siihen paikkaan, jonka Herra, sinun Jumalasi, valitsee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'ja mene leeviläisten pappien luo ja sen luo, joka siihen aikaan on tuomarina; kysy heiltä, ja he ilmoittavat sinulle tuomion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Ja tee sen sanan mukaan, minkä he sinulle ilmoittavat siinä paikassa, jonka Herra valitsee; ja noudata tarkoin kaikkea, mitä he sinulle opettavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Tee sen lain mukaan, minkä he sinulle opettavat, ja sen tuomion mukaan, minkä he sinulle julistavat, poikkeamatta oikealle tai vasemmalle siitä, mitä he sinulle ilmoittavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Mutta jos joku menettelisi niin julkeasti, ettei kuulisi pappia, joka siellä seisoo palvelemassa Herraa, sinun Jumalaasi, tai tuomaria, niin se mies kuolkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Poista paha Israelista. Ja kaikki kansa kuulkoon sen ja peljätköön, niin ettei kukaan enää olisi niin julkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Kun tulet siihen maahan, jonka Herra, sinun Jumalasi, sinulle antaa, ja otat sen omaksesi ja asetut siihen ja ajattelet: \'Minä asetan itselleni kuninkaan, niinkuin on kaikilla kansoilla, jotka minun ympärilläni asuvat\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'niin aseta itsellesi kuninkaaksi se, jonka Herra, sinun Jumalasi, valitsee. Aseta joku veljistäsi kuninkaaksesi; älä korota hallitsijaksesi muukalaista miestä, joka ei ole sinun veljesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Mutta älköön hän hankkiko itselleen paljon hevosia älköönkä viekö kansaa takaisin Egyptiin hankkiakseen paljon hevosia, sillä Herra on teille sanonut: \'Älkää enää palatko tätä tietä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Älköönkä hän ottako itsellensä monta vaimoa, ettei hänen sydämensä luopuisi pois; älköönkä hän kootko itsellensä ylen paljon hopeata ja kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Ja kun hän on noussut valtaistuimellensa, kirjoituttakoon hän itsellensä kirjaan jäljennöksen tästä laista, joka on leeviläisten pappien huostassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Ja hän pitäköön sen luonaan ja lukekoon sitä, niin kauan kuin elää, oppiaksensa pelkäämään Herraa, Jumalaansa, ja noudattamaan tarkoin kaikkia tämän lain sanoja ja näitä käskyjä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'ettei hänen sydämensä ylpistyisi hänen veljiänsä kohtaan ja ettei hän poikkeaisi käskyistä, ei oikealle eikä vasemmalle-niin että hän ja hänen poikansa kauan hallitsisivat Israelin keskuudessa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, '\"Leeviläisillä papeilla, Leevin koko sukukunnalla, älköön olko osuutta tai perintöosaa muun Israelin rinnalla; Herran uhreista ja siitä, mikä hänen osakseen tulee, he saakoot elatuksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Heillä ei ole oleva perintöosaa veljiensä keskuudessa; Herra itse on heidän perintöosansa, niinkuin hän on heille puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Ja tämä olkoon papeilla oikeus saada kansalta, niiltä, jotka uhraavat teurasuhrin, raavaan tai lampaan: papille annettakoon lapa, leukaluut ja maha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Uutiset jyvistäsi, viinistäsi ja öljystäsi ja lammastesi ensimmäiset kerityt villat anna hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Sillä hänet Herra, sinun Jumalasi, on valinnut kaikista sukukunnistasi, että hän ja hänen poikansa alati seisoisivat ja palvelisivat Herran nimessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Ja jos leeviläinen tahtoo tulla jostakin sinun kaupungistasi, jonka porttien sisäpuolella hän muukalaisena asuu, missä hyvänsä Israelissa, niin tulkoon vapaasti, niinkuin hänen mielensä tekee, siihen paikkaan, jonka Herra valitsee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'ja saakoon palvella Herran, Jumalansa, nimessä, niinkuin kaikki muutkin hänen veljensä, leeviläiset, jotka seisovat siellä Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'He kaikki saakoot elatukseksensa yhtäläisen osuuden, lukuunottamatta sitä, mitä joku on saanut myymällä perheomaisuuttaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Kun tulet siihen maahan, jonka Herra, sinun Jumalasi, sinulle antaa, niin älä opettele jäljittelemään niiden kansojen kauhistavia tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Älköön keskuudessasi olko ketään, joka panee poikansa tai tyttärensä kulkemaan tulen läpi, tahi joka tekee taikoja, ennustelee merkeistä, harjoittaa noituutta tai velhoutta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'joka lukee loitsuja, kysyy vainaja-tai tietäjähengiltä tahi kääntyy vainajien puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Sillä jokainen, joka senkaltaista tekee, on kauhistus Herralle, ja sellaisten kauhistusten tähden Herra, sinun Jumalasi, karkoittaa heidät sinun tieltäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Ole siis nuhteeton Herran, sinun Jumalasi, edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Sillä nämä kansat, jotka sinä nyt karkoitat, kuuntelevat kyllä merkeistäennustajia ja taikureita, mutta sinulle ei Herra, sinun Jumalasi, sitä salli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Sinun keskuudestasi, veljiesi joukosta, Herra, sinun Jumalasi, herättää sinulle profeetan, minun kaltaiseni; häntä kuulkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'On tapahtuva aivan niin, kuin sinä Herralta, sinun Jumalaltasi, anoit Hoorebilla, silloin kun seurakunta oli koolla ja sanoit: \'Älköön minun enää suotako kuulla Herran, minun Jumalani, ääntä älköönkä nähdä tätä suurta tulta, etten kuolisi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Ja Herra sanoi minulle: \'Mitä he ovat puhuneet, on oikein puhuttu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Profeetan minä olen herättävä heille heidän veljiensä keskuudesta, sinun kaltaisesi, ja minä panen sanani hänen suuhunsa, ja hän puhuu heille kaikki, mitä minä käsken hänen puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Ja joka ei kuule minun sanojani, joita hän minun nimessäni puhuu, hänet minä itse vaadin tilille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Mutta profeetta, joka julkeaa puhua minun nimessäni jotakin, jota minä en ole käskenyt hänen puhua, tahi puhuu muiden jumalien nimessä, sellainen profeetta kuolkoon.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Ja jos sinä ajattelet sydämessäsi: \'Mistä me tiedämme, mikä sana ei ole Herran puhetta?\' niin huomaa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'kun profeetta puhuu Herran nimessä, ja kun se, mitä hän on puhunut, ei tapahdu eikä käy toteen, niin sitä sanaa Herra ei ole puhunut; julkeuttaan se profeetta on niin puhunut; älä pelkää häntä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, '\"Kun Herra, sinun Jumalasi, on hävittänyt ne kansat, joiden maan Herra, sinun Jumalasi, antaa sinulle, ja kun sinä olet karkoittanut heidät ja asettunut heidän kaupunkeihinsa ja heidän taloihinsa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'niin erota itsellesi kolme kaupunkia siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa, että ottaisit sen omaksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Mittaa matkat ja jaa kolmeen osaan sen maan alue, jonka Herra, sinun Jumalasi, antaa sinulle perinnöksi, että niihin voisi paeta jokainen tappaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Ja näin on määrätty tappajasta, joka pakenee niihin saadakseen elää: kun joku tappaa lähimmäisensä tahtomattaan ja häntä ennestään vihaamatta-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'niinkuin jos joku menee lähimmäisensä kanssa metsään puita hakkaamaan ja hänen kätensä heiluttaa kirvestä kaataakseen puun ja rauta lentää varresta ja sattuu toiseen, niin että tämä kuolee-niin paetkoon sellainen johonkin näistä kaupungeista saadakseen elää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'ettei verenkostaja, sydämensä kiihkossa tappajaa takaa ajaessaan, saavuttaisi häntä, jos tie on pitkä, ja surmaisi häntä, vaikka hän ei ole ansainnut kuolemaa, koska ei ennestään toista vihannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Sentähden minä käsken sinua sanoen: \'Erota itsellesi kolme kaupunkia\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Ja jos Herra, sinun Jumalasi, laajentaa sinun aluettasi, niinkuin hän on vannonut sinun isillesi, ja antaa sinulle kaiken sen maan, jonka hän on sinun isillesi sanonut antavansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'jos sinä noudatat tarkoin kaikkia näitä käskyjä, jotka minä tänä päivänä sinulle annan, niin että alati rakastat Herraa, sinun Jumalaasi, ja vaellat hänen teitänsä, lisää silloin vielä kolme kaupunkia näihin kolmeen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'ettei viatonta verta vuodatettaisi sinun maassasi, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi, ja ettet joutuisi verivelan alaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Mutta jos joku vihaa lähimmäistään ja asettuu häntä väijymään ja karkaa hänen kimppuunsa ja lyö hänet kuoliaaksi ja sitten pakenee johonkin näistä kaupungeista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'niin lähettäkööt hänen kaupunkinsa vanhimmat noutamaan hänet sieltä ja antakoot hänet verenkostajan käsiin, ja hän kuolkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Älä sääli häntä, vaan poista viattoman veren velka Israelista, että menestyisit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Älä siirrä lähimmäisesi rajaa, jonka entiset polvet ovat määränneet sinun perintöosallesi siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa, että ottaisit sen omaksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Yksi ainoa todistaja älköön olko pätevä ketään vastaan, olkoonpa mikä pahateko tai rikkomus, mikä synti tahansa, jonka joku tekee. Kahden tai kolmen todistajan sanalla on asia vahva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Jos väärä todistaja nousee jotakuta vastaan ja syyttää häntä jostakin rikkomuksesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'niin astukoot molemmat riitapuolet Herran eteen, pappien eteen ja niiden eteen, jotka siihen aikaan ovat tuomareina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Ja tuomarit tutkikoot tarkoin asian, ja jos todistaja on väärä todistaja, joka on tehnyt väärän syytöksen veljeänsä vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'niin tehkää hänelle samoin, kuin hän aikoi tehdä veljellensä. Poista paha keskuudestasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Ja muut kuulkoot sen ja peljätkööt, niin ettei kukaan enää tekisi sellaista pahaa sinun keskuudessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Älä sääli häntä: henki hengestä, silmä silmästä, hammas hampaasta, käsi kädestä, jalka jalasta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, '\"Jos lähdet sotaan vihollistasi vastaan ja näet hevosia ja sotavaunuja ja sotajoukon, joka on sinua suurempi, niin älä pelkää heitä, sillä Herra, sinun Jumalasi, on sinun kanssasi, hän, joka johdatti sinut Egyptin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Kun olette ryhtymässä taisteluun, astukoon pappi esiin puhumaan kansalle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'ja sanokoon heille: \'Kuule, Israel! Te ryhdytte nyt taisteluun vihollisianne vastaan. Älkää arkailko, älkää peljätkö älkääkä hätääntykö, älkää säikähtykö heitä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'sillä Herra, teidän Jumalanne, käy teidän kanssanne, sotii teidän puolestanne vihollisianne vastaan ja antaa teille voiton.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Ja päällysmiehet puhukoot kansalle ja sanokoot: \'Joka on rakentanut uuden talon, mutta ei vielä ole sitä vihkinyt, menköön ja palatkoon kotiinsa, ettei hän kaatuisi taistelussa ja joku toinen vihkisi sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Joka on istuttanut viinitarhan, mutta ei vielä ole korjannut sen ensi hedelmää, menköön ja palatkoon kotiinsa, ettei hän kaatuisi taistelussa ja joku toinen korjaisi sen ensi hedelmää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Joka on kihlannut naisen, mutta ei vielä ole ottanut häntä vaimoksensa, menköön ja palatkoon kotiinsa, ettei hän kaatuisi taistelussa ja joku toinen ottaisi hänen morsiantaan vaimoksensa.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Vielä puhukoot päällysmiehet kansalle ja sanokoot: \'Joka pelkää ja arkailee, menköön ja palatkoon kotiinsa, etteivät hänen veljensäkin menettäisi rohkeuttaan niinkuin hän\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Ja kun päällysmiehet ovat tämän kaiken kansalle puhuneet, asettakoot he osastopäälliköt väen johtoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Kun lähestyt jotakin kaupunkia sotiaksesi sitä vastaan, tarjoa sille ensin rauhaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Ja jos se suostuu tarjoamaasi rauhaan ja avaa sinulle porttinsa, suorittakoon kaikki siellä oleva kansa sinulle työveroa ja palvelkoon sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Mutta jos se ei tee rauhaa sinun kanssasi, vaan valmistautuu taistelemaan sinua vastaan, niin piiritä sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Ja jos Herra, sinun Jumalasi, antaa sen sinun käsiisi, niin surmaa kaikki sen miesväki miekan terällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Mutta naiset, lapset ja karja ja kaikki, mitä kaupungissa on, kaikki, mitä sieltä on saatavana saalista, ryöstä itsellesi, ja nauti vihollisiltasi saatu saalis, minkä Herra, sinun Jumalasi, sinulle antaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Tee näin kaikille niille kaupungeille, jotka ovat sinusta hyvin kaukana, jotka eivät ole näiden kansojen kaupunkeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Mutta näiden kansojen kaupungeissa, jotka Herra, sinun Jumalasi, antaa sinulle perintöosaksi, älä jätä ainoatakaan henkeä eloon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'vaan vihi ne tuhon omiksi: heettiläiset ja amorilaiset, kanaanilaiset ja perissiläiset, hivviläiset ja jebusilaiset, niinkuin Herra, sinun Jumalasi, on sinua käskenyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'etteivät he opettaisi teitä tekemään kaikkia niitä kauhistavia tekoja, joita he ovat tehneet palvellessaan jumaliansa, ja ettette te rikkoisi Herraa, teidän Jumalaanne, vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Jos joudut kauan piirittämään kaupunkia ja sotimaan sitä vastaan valloittaaksesi sen, niin älä hävitä sen puita äläkä heiluta kirvestäsi niitä vastaan. Niiden hedelmiä saat nauttia, mutta älä hakkaa niitä maahan, sillä eivät kedon puut ole ihmisiä joutuakseen sinun piiritettäviksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Ainoastaan ne puut, joista tiedät, että niissä ei ole mitään syötävää, saat hävittää ja hakata maahan, rakentaaksesi niistä varustuksia sinun kanssasi sotivaa kaupunkia vastaan, kunnes se kukistuu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, '\"Jos siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa, että ottaisit sen omaksesi, löydetään murhattu virumassa kedolla, eikä tiedetä, kuka hänet tappoi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'niin lähtekööt sinun vanhimpasi ja tuomarisi mittaamaan välimatkan niihin kaupunkeihin, jotka ovat murhatun ympärillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Sen kaupungin vanhimmat, joka on murhattua lähinnä, ottakoot hiehon, jolla ei ole työtä tehty ja joka ei ole ollut vetojuhtana ikeen alla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'ja sen kaupungin vanhimmat viekööt hiehon alas ehtymättömän puron notkoon, jossa ei ole kynnetty eikä kylvetty; ja he taittakoot hieholta niskan siinä notkossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Ja papit, leeviläiset, astukoot esiin, sillä heidät on Herra, sinun Jumalasi, valinnut palvelemaan häntä ja Herran nimeen siunaamaan, ja heidän sanansa mukaan ratkaistakoon jokainen riita ja pahoinpitely.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Ja kaikki sen kaupungin vanhimmat, he kun asuvat murhattua lähinnä, peskööt kätensä pitäen niitä hiehon päällä, jolta niska taitettiin siinä notkossa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'ja he lausukoot sanoen: \'Meidän kätemme eivät ole tätä verta vuodattaneet, eivätkä silmämme tapausta nähneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Anna anteeksi, Herra, kansallesi Israelille, jonka vapahdit, äläkä lue viatonta verta kansallesi Israelille.\' Ja niin se verivelka annetaan heille anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Poista keskuudestasi viattoman veren velka, sillä sinun on tehtävä se, mikä on oikeata Herran silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Kun lähdet sotaan vihollisiasi vastaan ja Herra, sinun Jumalasi, antaa heidät sinun käsiisi ja sinä otat heistä vankeja');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'ja vankien joukossa näet kaunisvartaloisen naisen ja mielistyt häneen ja tahdot ottaa hänet vaimoksesi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'niin vie hänet kotiisi, ja hän ajattakoon hiuksensa ja leikatkoon kyntensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'Ja hän riisukoon vaatteensa, joissa hänet vangittiin, ja asukoon sinun kodissasi ja saakoon itkeä kuukauden päivät isäänsä ja äitiänsä; sitten saat yhtyä häneen ja naida hänet, niin että hän tulee vaimoksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Mutta jos hän ei sitten enää sinua miellytä, niin päästä hänet menemään vapaana äläkä myy häntä rahasta. Älä kohtele häntä tylysti, koska olet häntä alentavasti kohdellut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Jos jollakin miehellä on kaksi vaimoa, toinen, jota hän rakastaa, ja toinen, jota hän hylkii, ja he synnyttävät hänelle lapsia, sekä se, jota hän rakastaa, että se, jota hän hylkii, ja esikoinen on hyljityn poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'Älköön hän, kun jakaa pojilleen omaisuutensa perinnöksi, antako esikoisoikeutta rakastetun pojalle syrjäyttämällä hyljityn vaimon pojan, joka on esikoinen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'vaan hän tunnustakoon esikoisekseen hyljityn vaimon pojan ja antakoon hänelle kaksinkertaisen osan kaikesta, minkä omistaa. Sillä hän on hänen miehuutensa parhain; hänen on esikoisoikeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Jos jollakin on uppiniskainen ja kovakorvainen poika, joka ei ota kuullakseen, mitä hänen isänsä ja äitinsä sanovat, eikä tottele heitä, vaikka he kurittavat häntä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'niin hänen isänsä ja äitinsä ottakoot hänet ja viekööt kaupunkinsa vanhinten eteen, asuinpaikkansa porttiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'ja sanokoot kaupunkinsa vanhimmille: \'Tämä meidän poikamme on uppiniskainen ja kovakorvainen, hän ei ota kuullakseen, mitä me sanomme, vaan on irstailija ja juomari\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Silloin kaikki hänen kaupunkinsa miehet kivittäkööt hänet kuoliaaksi. Poista paha keskuudestasi, ja koko Israel kuulkoon sen ja peljätköön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Jos joku on tehnyt itsensä syypääksi rikkomukseen, josta rangaistaan kuolemalla, ja hänet surmataan, ja sinä ripustat hänet hirteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'niin älköön hänen ruumiinsa jääkö hirteen yöksi, vaan hautaa hänet samana päivänä, sillä Jumalan kiroama on se, joka on hirteen ripustettu; älä saastuta sitä maata, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, '\"Jos näet veljesi härän tai lampaan eksyneen, älä jätä sitä siihen; vie se takaisin veljellesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Jos veljesi ei asu sinua lähellä tai jos et tiedä, kuka hän on, niin korjaa eksynyt taloosi, ja olkoon se sinun huostassasi, kunnes veljesi tiedustelee sitä; anna se silloin hänelle takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Tee samoin, jos veljeltäsi on kadonnut aasi, samoin, jos vaate, samoin, jos mitä muuta hyvänsä, jonka löydät; älä jätä sitä siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Jos näet veljesi aasin tai härän kaatuneen tielle, älä jätä sitä siihen; auta häntä nostamaan se jaloilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Nainen älköön käyttäkö miehen tamineita, älköönkä mies pukeutuko naisen vaatteisiin; sillä jokainen, joka niin tekee, on kauhistus Herralle, sinun Jumalallesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Jos kulkiessasi tapaat puusta tai maasta linnun pesän, jossa on pojat tai munat ja emo makaamassa poikien tai munien päällä, niin älä ota emoa poikineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'vaan päästä emo lentämään ja ota vain pojat, että menestyisit ja kauan eläisit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Kun rakennat uuden talon, tee kaide kattosi ympärille, ettet saattaisi verenvikaa taloosi, jos joku sieltä putoaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Älä kylvä viinitarhaasi kahdenlaista siementä, muutoin kaikki, mitä siinä on, sekä siemen, jonka kylvit, että viinitarhan sato, on oleva pyhäkölle pyhitetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Älä kynnä yhtaikaa härällä ja aasilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Älä pue yllesi vaatetta, joka on kudottu kahdenlaisista langoista, villaisista ja pellavaisista sekaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Tee itsellesi tupsut viittasi neljään kulmaan, johon verhoudut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Jos joku on ottanut vaimon ja yhtynyt häneen, mutta sitten hylkii häntä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'ja esittää häntä vastaan perättömiä syytöksiä ja saattaa hänet pahaan maineeseen ja sanoo: \'Minä otin tämän naisen vaimokseni, mutta kun ryhdyin häneen, en tavannut hänessä neitsyyden merkkiä\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'niin tytön isä ja äiti ottakoot ja tuokoot tytön neitsyyden merkin kaupungin vanhimmille, porttiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Ja tytön isä sanokoon vanhimmille: \'Minä annoin tyttäreni vaimoksi tälle miehelle, mutta hän hylkii häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'Ja katso, hän esittää häntä vastaan perättömiä syytöksiä sanoen: Minä en tavannut tyttäressäsi neitsyyden merkkiä. Mutta tässä on tyttäreni neitsyyden merkki.\' Ja he levittäkööt vaatteen kaupungin vanhinten eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Silloin kaupungin vanhimmat ottakoot sen miehen ja kurittakoot häntä. Ja he määrätkööt hänelle sakkoa sata hopeasekeliä annettavaksi tytön isälle, sentähden että hän saattoi Israelin neitsyen pahaan maineeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'Ja hän olkoon hänen vaimonsa; hän älköön hyljätkö häntä koko elinaikanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Mutta jos syytös on tosi, jos tytössä ei tavattu neitsyyden merkkiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'silloin vietäköön tyttö isänsä talon ovelle, ja kaupungin miehet kivittäkööt hänet kuoliaaksi, koska hän teki häpeällisen teon Israelissa, harjoittaen haureutta isänsä kodissa. Poista paha keskuudestasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Jos joku tavataan makaamasta naisen kanssa, joka on toisen miehen aviovaimo, niin kuolkoot molemmat, sekä mies, joka makasi vaimon kanssa, että vaimo. Poista paha Israelista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Jos joku neitsyt on kihloissa miehen kanssa ja toinen tapaa hänet kaupungissa ja makaa hänen kanssaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'niin viekää molemmat sen kaupungin portille ja kivittäkää heidät kuoliaaksi, tyttö siksi, että hän ei huutanut apua kaupungissa, ja mies siksi, että hän teki väkivaltaa lähimmäisensä morsiamelle. Poista paha keskuudestasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Mutta jos mies tapaa kihlatun tytön kedolla, käy häneen käsiksi ja makaa hänen kanssaan, niin mies, joka makasi hänen kanssaan, kuolkoon yksin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Mutta tytölle älä tee mitään, sillä tyttö ei ole tehnyt kuoleman rikosta; tässä on samanlainen tapaus, kuin jos mies karkaa toisen kimppuun ja tappaa hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Sillä hän tapasi hänet kedolla; kihlattu tyttö huusi, mutta hänellä ei ollut auttajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Jos joku tapaa neitsyen, joka ei ole kihlattu, ja ottaa hänet kiinni ja makaa hänen kanssaan ja heidät siitä tavataan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'niin mies, joka makasi hänen kanssaan, antakoon tytön isälle viisikymmentä hopeasekeliä, ja tyttö tulkoon hänen vaimokseen, koska hän raiskasi hänet; hän älköön hyljätkö häntä koko elinaikanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Älköön kukaan ottako vaimoksi äitipuoltaan älköönkä nostako isänsä peitettä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, '\"Älköön kukaan, joka on kuohittu musertamalla tai leikkaamalla, pääskö Herran seurakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Älköön kukaan sekasikiö pääskö Herran seurakuntaan; älköön sellaisen jälkeläinen edes kymmenennessä polvessa pääskö Herran seurakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Älköön ammonilainen ja mooabilainen pääskö Herran seurakuntaan; älkööt heidän jälkeläisensä edes kymmenennessä polvessa koskaan pääskö Herran seurakuntaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'sentähden että he eivät tulleet leipää ja vettä tuoden teitä vastaan matkalla, kun olitte lähteneet Egyptistä, ja sentähden että hän palkkasi sinua vastaan Bileamin, Beorin pojan, Mesopotamian Petorista, sinua kiroamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Mutta Herra, sinun Jumalasi, ei tahtonut kuulla Bileamia, vaan Herra, sinun Jumalasi, muutti kirouksen sinulle siunaukseksi, sillä Herra, sinun Jumalasi, rakasti sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Älä koskaan, älä koko elinaikanasi, harrasta heidän menestystään ja onneaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Edomilaista älä inhoa, sillä hän on sinun veljesi. Älä inhoa egyptiläistä, sillä sinä olet asunut muukalaisena hänen maassaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Lapset, jotka heille syntyvät kolmannessa polvessa, pääskööt Herran seurakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Kun lähdettyäsi vihollisiasi vastaan asetut leiriin, karta kaikkea siivotonta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Jos sinun keskuudessasi on joku, joka ei ole puhdas sen johdosta, mitä hänelle yöllä on tapahtunut, menköön hän leirin ulkopuolelle; hän älköön tulko leiriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Illan suussa hän peseytyköön vedessä, ja auringon laskettua hän tulkoon leiriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Leirin ulkopuolella olkoon sinulla syrjäinen paikka, johon sinun on mentävä tarpeellesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Ja sinulla olkoon aseittesi lisänä pieni lapio, ja kun siellä ulkona istut tarpeellesi, kaiva sillä kuoppa ja peitä sitten ulostuksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Sillä Herra, sinun Jumalasi, vaeltaa leirissä auttaaksensa sinua ja antaakseen vihollisesi sinulle alttiiksi; sentähden olkoon sinun leirisi pyhä, ettei hän näkisi sinun keskuudessasi mitään häpeällistä ja kääntyisi pois sinusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Älä luovuta orjaa, joka on paennut isäntänsä luota sinun luoksesi, hänen isännällensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Hän asukoon sinun luonasi, sinun keskuudessasi, valitsemassaan paikassa, jonkun kaupunkisi porttien sisäpuolella, missä hän viihtyy; älä sorra häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Älköön pyhäkköporttoa olko Israelin tyttärien joukossa älköönkä haureellista pyhäkköpoikaa Israelin poikien joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Älä tuo portonpalkkaa äläkä koiranpalkkaa Herran, sinun Jumalasi, huoneeseen lupauksen suoritukseksi, sillä molemmat ovat kauhistus Herralle, sinun Jumalallesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Älä pane veljeäsi maksamaan korkoa rahasta tai elintarpeista tai muusta, mitä korkoa vastaan lainataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Muukalaisen saat panna korkoa maksamaan, mutta et veljeäsi, että Herra, sinun Jumalasi, siunaisi sinua kaikessa, mihin ryhdyt, siinä maassa, jota menet ottamaan omaksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Kun teet lupauksen Herralle, sinun Jumalallesi, niin täytä se viivyttelemättä, sillä totisesti on Herra, sinun Jumalasi, sen vaativa sinulta, ja sinä joudut syyhyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Mutta jos jätät lupauksen tekemättä, et joudu syyhyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Pidä se, mikä on huuliltasi lähtenyt, ja tee, niinkuin vapaaehtoisesti olet luvannut Herralle, sinun Jumalallesi, niinkuin olet suullasi puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Kun tulet lähimmäisesi viinitarhaan, niin saat syödä rypäleitä, minkä mielesi tekee, kunnes olet saanut kylläsi, mutta älä pane mitään astiaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Kun tulet lähimmäisesi viljapellolle, niin saat kädelläsi katkoa tähkäpäitä, mutta sirppiä älä heiluta lähimmäisesi viljapellolla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, '\"Jos joku ottaa vaimon ja nai hänet ja vaimo ei häntä enää miellytä, sentähden että mies on tavannut hänessä jotakin häpeällistä, ja hän kirjoittaa hänelle erokirjan ja antaa sen hänen käteensä ja lähettää hänet pois talostaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'ja jos nainen sitten, lähdettyään hänen talostaan, menee ja joutuu toisen miehen vaimoksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'ja myöskin tämä toinen mies hylkii häntä ja kirjoittaa hänelle erokirjan ja antaa sen hänen käteensä ja lähettää hänet pois talostaan, tai jos tämä toinen mies, joka on ottanut hänet vaimokseen, kuolee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Älköön hänen ensimmäinen miehensä, joka lähetti hänet pois, ottako häntä uudestaan vaimokseen, sittenkuin tämä on tullut saastutetuksi, sillä se olisi kauhistus Herran edessä. Älä saata syynalaiseksi maata, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Jos joku äsken on ottanut vaimon, ei hänen tarvitse lähteä sotaan, älköönkä hänen päälleen pantako muutakaan rasitusta; olkoon hän vuoden ajan vapaa perhettään varten ja iloksi vaimolleen, jonka on ottanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Älköön pantiksi otettako käsikiviä, ei päällimmäistäkään kiveä, sillä se olisi hengen ottamista pantiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Jos joku tavataan siitä, että hän on varastanut jonkun veljistään, israelilaisista, ja kohdellut häntä tylysti tai myynyt hänet, niin varas kuolkoon. Poista paha keskuudestasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Ole varuillasi pitalitautia vastaan, niin että tarkoin noudatat kaikkea, mitä leeviläiset papit teille neuvovat. Noudattakaa tarkoin käskyjä, jotka minä olen heille antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Muista, mitä Herra, sinun Jumalasi, teki Mirjamille matkalla, kun te olitte lähteneet Egyptistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Jos lainaat jotakin lähimmäisellesi, älä mene hänen taloonsa ottamaan häneltä panttia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Jää ulos, ja se mies, jolle lainasit, tuokoon pantin sinulle ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Ja jos hän on köyhä mies, niin älä mene maata, pitäen hänen panttiansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'vaan anna hänelle takaisin hänen panttinsa auringon laskiessa, että hän voisi maata vaipassaan ja siunaisi sinua; se koituu sinulle vanhurskaudeksi Herran, sinun Jumalasi, edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Älä tee vääryyttä kurjalle ja köyhälle palkkalaiselle, olipa hän veljiäsi tai muukalaisia, joita asuu maassasi, sinun porttiesi sisäpuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Maksa hänelle hänen palkkansa samana päivänä, ennenkuin aurinko laskee, sillä hän on kurja ja halajaa palkkaansa-ettei hän huutaisi sinun tähtesi Herran puoleen ja ettet sinä joutuisi syyhyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Älköön isiä rangaistako kuolemalla lasten tähden älköönkä lapsia isien tähden; kukin rangaistakoon kuolemalla oman syntinsä tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Älä vääristä muukalaisen äläkä orvon oikeutta, äläkä ota lesken vaatteita pantiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Muista, että itse olit orjana Egyptissä ja että Herra, sinun Jumalasi, sinut sieltä vapahti; sentähden minä käsken sinua näin tekemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Jos korjatessasi eloa pelloltasi unhotat pellolle lyhteen, älä palaa sitä hakemaan; se olkoon muukalaisen, orvon ja lesken oma, että Herra, sinun Jumalasi, siunaisi sinua kaikissa kättesi töissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Kun olet pudistanut öljypuustasi hedelmät, älä enää jäännöstä oksilta poimi; se olkoon muukalaisen, orvon ja lesken oma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Kun olet korjannut sadon viinitarhastasi, älä enää jälkikorjuuta pidä; se jääköön muukalaiselle, orvolle ja leskelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Muista, että itse olit orjana Egyptin maassa; sentähden minä käsken sinua näin tekemään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, '\"Jos syntyy riita miesten välillä ja he astuvat oikeuden eteen ja heidät tuomitaan, syytön syyttömäksi ja syyllinen syylliseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'ja jos syyllinen tuomitaan raippoihin, niin käskeköön tuomari hänen laskeutua maahan ja annattakoon läsnä ollessaan hänelle hänen rikostaan vastaavan määräluvun raippoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Neljäkymmentä raippaa saa hän hänelle antaa, ei enempää, ettei veljeäsi häväistäisi sinun silmiesi edessä antamalla hänelle vielä useampia lyöntejä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Älä sido puivan härän suuta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Kun veljeksiä asuu yhdessä ja joku heistä kuolee eikä hänellä ole poikaa, niin älköön vainajan leski menkö naimisiin muuhun sukuun, syrjäisen miehen kanssa. Hänen lankonsa yhtyköön häneen, ottakoon hänet vaimokseen ja täyttäköön häntä kohtaan langon velvollisuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Ja esikoinen, jonka vaimo synnyttää, katsottakoon kuolleen veljen omaksi, ettei hänen nimeänsä pyyhittäisi pois Israelista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Mutta jos mies ei suostu ottamaan kälyänsä vaimoksi, niin menköön käly porttiin vanhinten eteen ja sanokoon: \'Minun lankoni kieltäytyy pysyttämästä veljensä nimeä Israelissa; hän ei tahdo täyttää langon velvollisuutta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Silloin hänen kaupunkinsa vanhimmat kutsukoot hänet ja puhutelkoot häntä. Ja jos hän pysyy päätöksessään ja sanoo: \'En suostu ottamaan häntä vaimokseni\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'niin hänen kälynsä astukoon hänen luoksensa vanhinten silmien eteen ja vetäköön kengän hänen jalastaan, sylkeköön häntä silmille ja lausukoon sanoen: \'Näin tehtäköön jokaiselle, joka ei veljensä huonetta rakenna\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Ja hänen perhettänsä nimitettäköön sitten Israelissa \'paljasjalan perheeksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Jos kaksi miestä tappelee keskenään ja toisen vaimo tulee auttamaan miestään sen käsistä, joka häntä lyö, ja ojentaa kätensä ja tarttuu tämän häpyyn,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'niin hakkaa poikki hänen kätensä säälimättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Älä pidä kukkarossasi kahdenlaisia punnuksia, suurempia ja pienempiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Älä pidä talossasi kahdenlaista eefa-mittaa, suurempaa ja pienempää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Olkoon sinulla täydet ja oikeat punnukset; olkoon sinulla täysi ja oikea eefa-mitta, että eläisit kauan siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Sillä jokainen, joka näitä tekee, on kauhistus Herralle, jokainen, joka vääryyttä tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Muista, mitä Amalek teki sinulle matkalla, kun olit lähtenyt Egyptistä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'kuinka hän, Jumalaa pelkäämättä, tuli sinua vastaan tiellä, kun sinä olit väsynyt ja uuvuksissa, ja eristi sinun yhteydestäsi kaikki heikommat, jotka kulkivat jälkipäässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Sentähden, kun Herra, sinun Jumalasi, antaa sinun päästä rauhaan kaikista ympärillä olevista vihollisistasi siinä maassa, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi, ottaaksesi sen omaksesi, niin pyyhi pois Amalekin muisto taivaan alta. Älä tätä unhota.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, '\"Kun tulet siihen maahan, jonka Herra, sinun Jumalasi, antaa sinulle perintöosaksi, ja sinä otat sen omaksesi ja asetut siihen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'niin ota uutiset kaikista maasi hedelmistä, mitä saat satona maastasi, jonka Herra, sinun Jumalasi, sinulle antaa, ja pane ne koriin ja lähde siihen paikkaan, jonka Herra, sinun Jumalasi, valitsee nimensä asuinsijaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Ja mene sen tykö, joka siihen aikaan on pappina, ja sano hänelle: \'Minä tunnustan tänä päivänä Herralle, sinun Jumalallesi, että minä olen tullut siihen maahan, jonka Herra meidän isillemme vannotulla valalla on luvannut antaa meille\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Ja pappi ottakoon korin sinun kädestäsi ja asettakoon sen Herran, sinun Jumalasi, alttarin eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Niin lausu Herran, Jumalasi, edessä sanoen: \'Minun isäni oli harhaileva aramilainen, joka meni Egyptiin, vähäinen joukko mukanaan, ja asui siellä muukalaisena ja tuli siellä suureksi, väkeväksi ja lukuisaksi kansaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Mutta egyptiläiset kohtelivat meitä pahoin ja rasittivat meitä ja teettivät meillä kovaa työtä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Silloin me huusimme Herran, isiemme Jumalan, puoleen, ja Herra kuuli meidän huutomme ja näki meidän kurjuutemme, vaivamme ja kärsimämme sorron.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Ja Herra vei meidät pois Egyptistä väkevällä kädellä ja ojennetulla käsivarrella, suurella peljätyksellä, tehden tunnustekoja ja ihmeitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'Ja hän toi meidät tähän paikkaan ja antoi meille tämän maan, maan, joka vuotaa maitoa ja mettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Ja katso, nyt minä tuon uutiset sen maan hedelmistä, jonka sinä, Herra, minulle annoit.\' Niin aseta ne Herran, sinun Jumalasi, eteen ja kumartaen rukoile Herran, sinun Jumalasi, edessä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'ja iloitse kaikesta hyvästä, minkä Herra, sinun Jumalasi, on antanut sinulle ja sinun perheellesi, sinä ja leeviläinen ja muukalainen, joka asuu sinun keskuudessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Kun kolmantena vuotena, kymmenysten vuotena, olet suorittanut loppuun kaikki kymmenykset saamastasi sadosta ja antanut ne leeviläiselle, muukalaiselle, orvolle ja leskelle, ja he ovat syöneet sinun porttiesi sisäpuolella ja tulleet ravituiksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'niin sano Herran, Jumalasi, edessä: \'Minä olen vienyt pois talostani sen, mikä on pyhäkölle pyhitettyä, ja olen antanut sen leeviläiselle ja muukalaiselle, orvolle ja leskelle, aivan sinun käskysi mukaan, jonka olet minulle antanut; en ole rikkonut sinun käskyjäsi enkä niitä unhottanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Minä en syönyt siitä mitään silloin, kun minulla oli suru, enkä vienyt siitä mitään pois silloin, kun olin saastunut, enkä antanut siitä mitään vainajalle. Olen kuullut Herran, minun Jumalani, ääntä; olen tehnyt aivan niin, kuin olet minun käskenyt tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Katso pyhästä asunnostasi, taivaasta, ja siunaa kansaasi Israelia ja sitä maata, jonka olet meille antanut, niinkuin valalla vannoen lupasit isillemme, maata, joka vuotaa maitoa ja mettä.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Tänä päivänä Herra, sinun Jumalasi, käskee sinun seurata näitä käskyjä ja oikeuksia; noudata ja seuraa niitä kaikesta sydämestäsi ja kaikesta sielustasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Sinä olet tänään kuullut Herran, sinun Jumalasi, julistavan, että hän tahtoo olla sinun Jumalasi ja että sinun on vaellettava hänen teitänsä ja noudatettava hänen käskyjänsä, säädöksiänsä ja oikeuksiansa sekä kuultava häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Ja Herra on kuullut sinun tänä päivänä julistavan, että sinä tahdot olla hänen omaisuuskansansa, niinkuin hän on sinulle puhunut, ja noudattaa kaikkia hänen käskyjänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'että hän asettaisi sinut korkeammaksi kaikkia luomiansa kansoja, ylistykseksi, kunniaksi ja kiitokseksi, ja että olisit Herralle, sinun Jumalallesi, pyhitetty kansa, niinkuin hän on puhunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Niin Mooses ja Israelin vanhimmat käskivät kansaa sanoen: \"Noudattakaa kaikkia niitä käskyjä, jotka minä tänä päivänä teille annan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Ja kun menette Jordanin yli siihen maahan, jonka Herra, sinun Jumalasi, sinulle antaa, pystytä itsellesi suuria kiviä ja sivele ne kalkilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'Ja kirjoita niihin kaikki tämän lain sanat, kun menet joen yli siihen maahan, jonka Herra, sinun Jumalasi, sinulle antaa, maahan, joka vuotaa maitoa ja mettä, niinkuin Herra, sinun isiesi Jumala, on sinulle puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Ja kun olette menneet Jordanin yli, niin pystyttäkää Eebalin vuorelle ne kivet, joista minä tänä päivänä annan teille käskyn, ja sivele ne kalkilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Ja rakenna siihen alttari Herralle, sinun Jumalallesi, alttari kivistä, joihin et saa rauta-aseella koskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Hakkaamattomista kivistä rakenna Herran, Jumalasi, alttari; uhraa sen päällä polttouhreja Herralle, Jumalallesi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'ja teurasta teuraita yhteysuhriksi ja syö siellä ja iloitse Herran, Jumalasi, edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Ja kirjoita kiviin kaikki tämän lain sanat hyvin selkeästi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Ja Mooses ja leeviläiset papit puhuivat kaikelle Israelille sanoen: \"Ole hiljaa ja kuule, Israel! Tänä päivänä on sinusta tullut Herran, Jumalasi, kansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Kuule siis Herraa, Jumalaasi, ja noudata hänen käskyjänsä ja ohjeitansa, jotka minä tänä päivänä sinulle annan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Ja Mooses käski kansaa sinä päivänä sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, '\"Kun te olette menneet Jordanin yli, asettukoot nämä Garissimin vuorelle siunaamaan kansaa: Simeon, Leevi, Juuda, Isaskar, Joosef ja Benjamin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Nämä taas asettukoot Eebalin vuorelle lausumaan kirouksen: Ruuben, Gaad, Asser, Sebulon, Daan ja Naftali.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Ja leeviläiset lausukoot ja sanokoot kovalla äänellä kaikille Israelin miehille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, '\'Kirottu olkoon se, joka tekee jumalankuvan, veistetyn tai valetun, taitajan käden tekemän, kauhistukseksi Herralle, ja joka salaa sen pystyttää\'. Ja kaikki kansa vastatkoon ja sanokoon: \'Amen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Kirottu olkoon se, joka häpäisee isäänsä tai äitiänsä. Ja kaikki kansa sanokoon: \'Amen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Kirottu olkoon se, joka siirtää lähimmäisensä rajan. Ja kaikki kansa sanokoon: \'Amen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Kirottu olkoon se, joka vie sokean harhaan tieltä. Ja kaikki kansa sanokoon: \'Amen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Kirottu olkoon se, joka vääristää muukalaisen, orvon tai lesken oikeuden. Ja kaikki kansa sanokoon: \'Amen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Kirottu olkoon se, joka makaa äitipuolensa kanssa, sillä hän nostaa isänsä peitteen. Ja kaikki kansa sanokoon: \'Amen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Kirottu olkoon se, joka sekaantuu eläimeen. Ja kaikki kansa sanokoon: \'Amen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Kirottu olkoon se, joka makaa sisarensa, isänsä tyttären tai äitinsä tyttären, kanssa. Ja kaikki kansa sanokoon: \'Amen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Kirottu olkoon se, joka makaa anoppinsa kanssa. Ja kaikki kansa sanokoon: \'Amen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Kirottu olkoon se, joka salaa murhaa lähimmäisensä. Ja kaikki kansa sanokoon: \'Amen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Kirottu olkoon se, joka ottaa lahjuksen surmatakseen viattoman. Ja kaikki kansa sanokoon: \'Amen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Kirottu olkoon se, joka ei pidä tämän lain sanoja eikä täytä niitä. Ja kaikki kansa sanokoon: \'Amen\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, '\"Jos kuulet Herran, sinun Jumalasi, ääntä ja pidät tarkoin kaikki hänen käskynsä, jotka minä tänä päivänä sinulle annan, niin Herra, sinun Jumalasi, asettaa sinut korkeammaksi kaikkia kansoja maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Ja kaikki nämä siunaukset tulevat sinun osaksesi ja saavuttavat sinut, jos kuulet Herran, sinun Jumalasi, ääntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Siunattu olet sinä kaupungissa ja siunattu olet kedolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Siunattu on sinun kohtusi hedelmä ja maasi hedelmä ja sinun karjasi hedelmä, raavaittesi vasikat ja lampaittesi karitsat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Siunattu on sinun korisi ja sinun taikinakaukalosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Siunattu olet tullessasi ja siunattu olet lähtiessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Herra antaa sinun voittaa vihollisesi, jotka nousevat sinua vastaan; yhtä tietä he lähtevät sinua vastaan, mutta seitsemää tietä he sinua pakenevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Herra käskee siunauksen seurata sinua jyväaitoissasi ja kaikessa, mihin ryhdyt; hän siunaa sinua siinä maassa, jonka Herra, sinun Jumalasi, sinulle antaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Herra korottaa sinut hänelle pyhitetyksi kansaksi, niinkuin hän valalla vannoen on sinulle luvannut, jos sinä noudatat Herran, sinun Jumalasi, käskyjä ja vaellat hänen teitänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Ja kaikki kansat maan päällä näkevät, että Herra on ottanut sinut nimiinsä; ja he pelkäävät sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Ja Herra antaa sinulle ylen runsaasti hyvää, tekee sinun kohtusi hedelmän, karjasi hedelmän ja maasi hedelmän ylen runsaaksi siinä maassa, jonka Herra sinun isillesi vannotulla valalla on luvannut antaa sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Herra avaa sinulle rikkaan aarrekammionsa, taivaan, antaakseen sinun maallesi sateen aikanansa ja siunatakseen kaikki sinun kättesi työt; ja sinä lainaat monelle kansalle, mutta sinun itsesi ei tarvitse lainaa ottaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Ja Herra tekee sinut pääksi eikä hännäksi; sinä aina vain ylenet etkä koskaan alene, jos tottelet Herran, sinun Jumalasi, käskyjä, jotka minä tänä päivänä sinulle annan, että ne tarkoin pitäisit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'etkä poikkea oikealle etkä vasemmalle yhdestäkään niistä sanoista, jotka minä tänä päivänä teille annan, et seuraa muita jumalia etkä palvele niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Mutta jos sinä et kuule Herran, sinun Jumalasi, ääntä etkä tarkoin pidä kaikkia hänen käskyjänsä ja säädöksiänsä, jotka minä tänä päivänä sinulle annan, niin kaikki nämä kiroukset tulevat sinun päällesi ja saavuttavat sinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Kirottu olet sinä kaupungissa ja kirottu olet kedolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Kirottu on sinun korisi ja sinun taikinakaukalosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Kirottu on sinun kohtusi hedelmä ja maasi hedelmä, kirotut sinun raavaittesi vasikat ja lampaittesi karitsat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Kirottu olet tullessasi ja kirottu olet lähtiessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Herra lähettää sinun sekaasi kirousta, hämminkiä ja uhkaa, mihin tahansa ryhdyt, kunnes äkisti tuhoudut ja hukut töittesi pahuuden tähden, kun olet minut hyljännyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Herra antaa ruttotaudin tarttua sinuun, kunnes se sukupuuttoon hävittää sinut siitä maasta, jota menet ottamaan omaksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Herra lyö sinua hivutustaudilla, kuumeella, poltteella ja tulehduksella, kuivuudella, nokitähkillä ja viljan ruosteella, ja ne vainoavat sinua, kunnes menehdyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Ja taivaasi, joka on sinun pääsi päällä, on niinkuin vaski, ja maa, joka on allasi, on niinkuin rauta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Herra muuttaa sinun maasi sateen tomuksi ja tuhaksi; taivaasta se tulee sinun päällesi, kunnes tuhoudut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Herra antaa sinun vihollistesi voittaa sinut; yhtä tietä sinä menet heitä vastaan, mutta seitsemää tietä sinä heitä pakenet; ja sinä tulet kauhistukseksi kaikille valtakunnille maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Ja ruumiisi joutuvat ruuaksi kaikille taivaan linnuille ja maan eläimille, eikä kukaan karkoita niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Herra lyö sinua Egyptin paiseilla ja ajoksilla, ihottumalla ja ruvella, joista et parannu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Herra lyö sinua hulluudella, sokeudella ja mielisairaudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Sinä haparoit keskellä päivää, niinkuin sokea haparoi pimeässä; sinä et menesty teilläsi, vaan kaiken elinaikasi sinä olet oleva sorrettu ja ryöstetty, eikä ole auttajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Sinä kihlaat naisen, mutta toinen makaa hänet; sinä rakennat talon, mutta et siinä asu; sinä istutat viinitarhan, mutta et korjaa sen hedelmää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Härkäsi teurastetaan sinun silmiesi edessä, mutta sinä et sitä syö; aasisi ryöstetään sinulta sinun nähtesi eikä sitä anneta sinulle takaisin; lampaasi joutuvat sinun vihollistesi valtaan, eikä sinulla ole auttajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Sinun poikasi ja tyttäresi joutuvat vieraan kansan valtaan, ja sinun silmäsi näkevät sen ja raukeavat heitä alinomaa ikävöidessäsi, mutta sinä et voi sille mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Sinun maasi hedelmän ja kaiken sinun vaivannäkösi kuluttaa kansa, jota sinä et tunne; kaiken elinaikasi sinä olet oleva sorrettu ja runneltu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Ja sinä tulet hulluksi siitä, mitä sinun silmäsi näkevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Herra lyö sinuun, sinun polviisi ja pohkeisiisi, pahoja paiseita, joista et parannu, kantapäästä kiireeseen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Herra vie sinut ja kuninkaan, jonka sinä itsellesi asetat, kansan luo, jota sinä et tunne ja jota sinun isäsi eivät tunteneet; ja siellä sinä palvelet muita jumalia, puu-ja kivijumalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Ja sinä tulet kauhistukseksi, sananparreksi ja pistopuheeksi kaikille niille kansoille, joiden keskuuteen Herra sinut kuljettaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Paljon siementä sinä viet pellollesi, mutta vähän sinä korjaat, sillä heinäsirkat hävittävät sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Viinitarhoja sinä istutat ja hoidat, mutta viiniä et saa juodaksesi etkä tallettaaksesi, sillä madot syövät sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Öljypuita sinulla on kaikkialla alueellasi, mutta öljyllä et sinä itseäsi voitele, sillä sinun öljymarjasi varisevat maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Poikia ja tyttäriä sinulle syntyy, mutta et saa niitä pitää, sillä he vaeltavat vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Tuhohyönteiset valtaavat kaikki sinun puusi ja sinun maasi hedelmän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Muukalainen, joka asuu keskuudessasi, kohoaa sinun ylitsesi yhä ylemmäksi, mutta sinä painut aina alemmaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Hän lainaa sinulle, mutta sinä et voi lainata hänelle. Hän tulee pääksi, mutta sinä hännäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Kaikki nämä kiroukset tulevat sinun päällesi, vainoavat sinua ja saavuttavat sinut, kunnes tuhoudut, koska et kuullut Herran, sinun Jumalasi ääntä etkä noudattanut hänen käskyjänsä ja säädöksiänsä, jotka hän on sinulle antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Ne jäävät merkkeinä ja ihmeinä sinuun ja sinun jälkeläisiisi iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Koska et palvellut Herraa, sinun Jumalaasi, ilolla ja sydämen halulla, kun sinulla oli yltäkyllin kaikkea,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'on sinun palveltava vihollisiasi, jotka Herra sinun kimppuusi lähettää, nälässä ja janossa ja alastomuudessa ja kaiken puutteessa. Ja hän panee sinun kaulallesi rautaisen ikeen, kunnes hän sinut tuhoaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Herra nostaa sinua vastaan kaukaisen kansan, joka tulee maan äärestä lentäen niinkuin kotka, kansan, jonka kieltä sinä et ymmärrä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'tuimakatseisen kansan, joka ei armahda vanhaa eikä sääli nuorta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Se syö sinun karjasi hedelmän ja maasi hedelmän, kunnes sinä tuhoudut; se ei jätä sinulle mitään, ei jyviä ei viiniä eikä öljyä, ei raavaittesi vasikoita eikä lampaittesi karitsoita, kunnes on tehnyt sinusta lopun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Ja se ahdistaa sinua kaikissa porteissasi, kunnes korkeat ja lujat muurisi, joihin sinä luotit, kukistuvat kaikkialla maassasi. Se ahdistaa sinua kaikissa porteissasi kaikkialla sinun maassasi, jonka Herra, sinun Jumalasi, on sinulle antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Siinä hädässä ja ahdistuksessa, johon sinun vihollisesi saattaa sinut, sinä syöt oman kohtusi hedelmän, syöt poikiesi ja tyttäriesi lihaa, jotka Herra, sinun Jumalasi, on sinulle antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Hempeästi ja hekumallisesti elänyt mies sinun keskuudessasi katselee silloin karsaasti veljeänsä ja vaimoaan, joka hänen sylissänsä on, ja jäljellä olevia lapsiaan, jotka hän on jättänyt henkiin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'kenellekään heistä hän ei anna lastensa lihaa, jota hän itse syö, kun hänellä ei ole mitään muuta jäljellä, siinä hädässä ja ahdistuksessa, johon vihollisesi saattaa sinut kaikissa sinun porteissasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Hempeästi ja hekumallisesti elänyt nainen sinun keskuudessasi, joka hekumassaan ja hempeydessään ei edes yrittänyt laskea jalkaansa maahan, katselee silloin karsaasti miestä, joka hänen sylissänsä on, ja poikaansa ja tytärtänsä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'eikä suo heille jälkeläisiä, jotka tulevat hänen kohdustansa, eikä lapsia, joita hän synnyttää, sillä kaiken muun puutteessa syö hän ne salaa itse siinä hädässä ja ahdistuksessa, johon vihollisesi saattaa sinut sinun porteissasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Jos et tarkoin noudata kaikkia tämän lain sanoja, jotka ovat kirjoitetut tähän kirjaan, niin että pelkäät tätä kunniallista ja peljättävää nimeä, Herraa, sinun Jumalaasi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'niin Herra panee sinun ja sinun jälkeläistesi kärsittäväksi erinomaisia vaivoja, suuria ja pitkällisiä vaivoja, pahoja ja pitkällisiä sairauksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Hän kääntää sinua vastaan kaikki Egyptin taudit, joita sinä pelkäät, ja ne tarttuvat sinuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Ja kaikkinaisia muita sairauksia ja vaivoja, joista ei ole kirjoitettu tässä lakikirjassa, Herra nostattaa sinua vastaan, kunnes sinä tuhoudut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Ja teistä, jotka ennen olitte monilukuiset kuin taivaan tähdet, jää jäljelle ainoastaan vähäinen joukko, koska et kuullut Herran, sinun Jumalasi, ääntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Ja niinkuin Herra ennen iloitsi teistä, siitä, että teki teille hyvää ja antoi teidän lisääntyä, niin Herra silloin iloitsee teistä, siitä, että hävittää ja tuhoaa teidät. Ja teidät temmataan irti siitä maasta, jota sinä menet ottamaan omaksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Ja Herra hajottaa sinut kaikkien kansojen sekaan maan äärestä toiseen, ja sinä palvelet siellä muita jumalia, joita sinä et tunne ja joita sinun isäsi eivät tunteneet, puuta ja kiveä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Ja niiden kansojen seassa sinä et saa rauhaa, eikä jalkasi löydä lepopaikkaa. Herra antaa sinulle siellä vapisevan sydämen, rauenneet silmät ja nääntyvän sielun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Ja sinun elämäsi näyttää sinusta olevan hiuskarvan varassa, yöt ja päivät sinä olet pelon vallassa etkä ole varma hengestäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Aamulla sinä sanot: \'Jospa olisi ilta!\' ja illalla sanot: \'Jospa olisi aamu!\' -sellaista pelkoa sinä tunnet sydämessäsi, ja sellaisia näkyjä sinä näet silmissäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Ja Herra vie sinut laivoilla takaisin Egyptiin samaa tietä, josta minä sanoin sinulle: \'Et ole sitä enää näkevä\'. Ja siellä teitä kaupitaan vihollisillenne orjiksi ja orjattariksi, mutta ostajaa ei ole.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Nämä ovat sen liiton sanat, jonka Herra käski Mooseksen tehdä israelilaisten kanssa Mooabin maassa, sen liiton lisäksi, jonka hän oli tehnyt heidän kanssaan Hoorebilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, '{29:1} Ja Mooses kutsui kokoon kaiken Israelin ja sanoi heille: \"Te olette nähneet kaiken, minkä Herra teki teidän silmienne edessä Egyptin maassa faraolle ja kaikille hänen palvelijoilleen ja koko hänen maalleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'ne suuret koettelemukset, jotka sinun silmäsi näkivät, ne suuret tunnusteot ja ihmeet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Mutta tähän päivään asti Herra ei vielä ole antanut teille sydäntä ymmärtääksenne ja silmiä nähdäksenne ja korvia kuullaksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Ja minä kuljetin teitä erämaassa neljäkymmentä vuotta: teidän vaatteenne eivät kuluneet yltänne, eivätkä kenkäsi kuluneet jalassasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Leipää ette saaneet syödäksenne ettekä viiniä ja väkijuomaa juodaksenne, jotta tietäisitte, että minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Ja kun te tulitte tähän paikkaan, niin lähtivät Siihon, Hesbonin kuningas, ja Oog, Baasanin kuningas, sotimaan meitä vastaan, mutta me voitimme heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Ja me valloitimme heidän maansa ja annoimme sen perintöosaksi ruubenilaisille ja gaadilaisille ja toiselle puolelle Manassen sukukuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Noudattakaa siis tämän liiton sanoja ja täyttäkää ne menestyäksenne kaikessa, mitä teette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Te seisotte tänä päivänä kaikki Herran, teidän Jumalanne, edessä: teidän päämiehenne, sukukuntanne, vanhimpanne ja päällysmiehenne, kaikki Israelin miehet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'teidän lapsenne ja vaimonne sekä muukalainen, joka on leirissäsi, jopa puunhakkaajasi ja vedenkantajasikin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'käydäksenne Herran, teidän Jumalanne, liittoon, siihen valaliittoon, jonka Herra, sinun Jumalasi, tänä päivänä tekee sinun kanssasi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'että hän tänä päivänä korottaisi sinut kansaksensa ja tulisi sinun Jumalaksesi, niinkuin hän on sinulle puhunut ja niinkuin hän on vannonut sinun isillesi, Aabrahamille, Iisakille ja Jaakobille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Enkä minä tee tätä liittoa, tätä valaliittoa, ainoastaan teidän kanssanne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'vaan niinhyvin niiden kanssa, jotka tänä päivänä ovat tässä meidän kanssamme seisomassa Herran, meidän Jumalamme, edessä, kuin niidenkin kanssa, jotka eivät ole tänä päivänä tässä meidän kanssamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Sillä te tiedätte, kuinka me asuimme Egyptin maassa ja kuinka me kuljimme niiden kansojen keskitse, joiden kautta te olette kulkeneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Ja te näitte heidän iljetyksensä, ne puu-,kivi-,hopea-ja kultajumalat, jotka heillä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Älköön siis teidän joukossanne olko ainoatakaan miestä tai naista, sukua tai sukukuntaa, jonka sydän tänä päivänä kääntyisi pois Herrasta, meidän Jumalastamme, mennäkseen palvelemaan noiden kansojen jumalia; älköön teidän keskuudessanne olko juurta, josta kasvaa koiruohoa ja marunaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'niin että se, joka kuulee tämän valan sanat, siunaisi itseänsä sydämessään sanoen: \'Minun käy hyvin, vaikka vaellankin sydämeni paatumuksessa\'. Siten hän hukuttaisi kaikki, sekä kostean että kuivan maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Herra ei tahdo antaa hänelle anteeksi, vaan silloin suitsuaa Herran viha ja kiivaus sitä miestä vastaan, ja kaikki se kirous, joka on kirjoitettu tähän kirjaan, laskeutuu hänen päällensä, ja Herra pyyhkii pois hänen nimensä taivaan alta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Ja Herra erottaa hänet kaikista Israelin sukukunnista, tuottaakseen hänelle onnettomuuden, kaikki ne kiroukset, jotka sisältyvät tähän lain kirjaan kirjoitettuun liittoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Ja tuleva sukupolvi, teidän lapsenne, jotka nousevat teidän jälkeenne, ja vieras, joka tulee kaukaisesta maasta, kysyvät, kun näkevät sen maan vaivat ja ne sairaudet, joilla Herra sitä rasittaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'tulikiven ja suolan, kun koko maa on poltettu, niin ettei siihen kylvetä eikä se kasva eikä siitä ruohonkortta nouse-niinkuin oli silloin, kun Sodoma ja Gomorra, Adma ja Seboim hävitettiin, kun Herra vihassaan ja kiivastuksessaan ne hävitti-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'silloin kaikki kansat kysyvät: \'Minkätähden Herra on näin tehnyt tälle maalle? Mistä tämä hänen suuri vihansa hehku?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Silloin vastataan: \'Siitä, että he hylkäsivät Herran, isiensä Jumalan, liiton, jonka hän teki heidän kanssansa viedessään heidät pois Egyptin maasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'ja menivät palvelemaan muita jumalia ja kumarsivat niitä, jumalia, joita he eivät tunteneet ja joita hän ei ollut heidän osalleen jakanut-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'siitä syttyi Herran viha tätä maata kohtaan, niin että hän antoi kohdata sitä kaiken sen kirouksen, joka on kirjoitettu tähän kirjaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Ja Herra tempasi heidät irti heidän maastaan vihassa ja kiivastuksessa ja suuressa suuttumuksessa ja heitti heidät toiseen maahan, niinkuin nyt on tapahtunut.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, '{29:28} Se, mikä on salassa, se on Herran, meidän Jumalamme; mutta mikä on ilmoitettu, se on meitä ja meidän lapsiamme varten ikuisesti, että me pitäisimme kaikki tämän lain sanat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, '\"Jos sinä silloin, kun tämä kaikki sinua kohtaa, siunaus tai kirous, jotka minä olen asettanut sinun valittavaksesi, painat sen sydämeesi kaikkien kansojen keskellä, joiden luo Herra, sinun Jumalasi, on sinut karkoittanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'ja palajat Herran, sinun Jumalasi, tykö ja kuulet hänen ääntänsä kaikesta sydämestäsi ja kaikesta sielustasi, sinä itse ja sinun lapsesi, kaikessa, niinkuin minä tänä päivänä sinua käsken,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'niin Herra, sinun Jumalasi, kääntää sinun kohtalosi ja armahtaa sinua; Herra, sinun Jumalasi, kokoaa sinut jälleen kaikista kansoista, joiden sekaan hän on sinut hajottanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Vaikka sinun karkoitettusi olisivat taivaan äärissä, niin Herra, sinun Jumalasi, kokoaa ja noutaa sinut sieltäkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Ja Herra, sinun Jumalasi, tuo sinut siihen maahan, jonka sinun isäsi ovat omistaneet, ja niin sinä otat sen omaksesi; ja hän tekee sinulle hyvää ja antaa sinun lisääntyä enemmän kuin isiesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Ja Herra, sinun Jumalasi, ympärileikkaa sinun sydämesi ja sinun jälkeläistesi sydämet, niin että rakastat Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi, että eläisit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Ja Herra, sinun Jumalasi, antaa kaikkien näiden kirousten kohdata sinun vihollisiasi ja vihamiehiäsi, jotka sinua vainosivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Ja sinä kuulet jälleen Herran ääntä ja pidät kaikki hänen käskynsä, jotka minä tänä päivänä sinulle annan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Herra, sinun Jumalasi, antaa sinulle ylen runsaasti hyvää kaikissa sinun kättesi töissä, hän tekee sinun kohtusi hedelmän, karjasi hedelmän ja maasi hedelmän ylen runsaaksi. Sillä niinkuin Herra iloitsi sinun isistäsi, hän jälleen iloitsee sinusta, siitä, että tekee sinulle hyvää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'kun sinä kuulet Herran, sinun Jumalasi, ääntä ja noudatat hänen käskyjänsä ja säädöksiänsä, jotka ovat kirjoitetut tähän lain kirjaan, ja kun sinä palajat Herran, sinun Jumalasi, tykö kaikesta sydämestäsi ja kaikesta sielustasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Sillä tämä käsky, jonka minä tänä päivänä sinulle annan, ei ole sinulle vaikea täyttää eikä liian kaukana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Se ei ole taivaassa, eikä sinun tarvitse sanoa: \'Kuka nousisi meidän puolestamme taivaaseen noutamaan sen meille ja julistaisi sen meille, että me sen täyttäisimme?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Se ei ole meren takana, eikä sinun tarvitse sanoa: \'Kuka menisi meidän puolestamme meren taakse noutamaan sen meille ja julistaisi sen meille, että me sen täyttäisimme?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Vaan sana on sinua aivan lähellä, sinun suussasi ja sydämessäsi, niin että voit sen täyttää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Katso, minä panen tänä päivänä sinun eteesi elämän ja hyvän, kuoleman ja pahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'kun minä tänä päivänä käsken sinua rakastamaan Herraa, sinun Jumalaasi, ja vaeltamaan hänen teitänsä ja noudattamaan hänen käskyjänsä, säädöksiänsä ja oikeuksiansa, että eläisit ja lisääntyisit ja että Herra, sinun Jumalasi, siunaisi sinua siinä maassa, jota menet ottamaan omaksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Mutta jos sinun sydämesi kääntyy pois etkä tottele, vaan annat vietellä itsesi kumartamaan muita jumalia ja palvelemaan niitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'niin minä julistan teille tänä päivänä, että te totisesti hukutte; te ette kauan elä siinä maassa, johon sinä menet Jordanin yli, ottamaan sen omaksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Minä otan tänä päivänä taivaan ja maan todistajiksi teitä vastaan, että minä olen pannut sinun eteesi elämän ja kuoleman, siunauksen ja kirouksen. Niin valitse siis elämä, että sinä ja sinun jälkeläisesi eläisitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Rakasta Herraa, sinun Jumalaasi, kuule hänen ääntänsä ja riipu hänessä kiinni, sillä siinä on sinun elämäsi ja pitkä ikäsi, ja niin sinä saat asua siinä maassa, jonka Herra sinun isillesi, Aabrahamille, Iisakille ja Jaakobille, vannotulla valalla on luvannut heille antaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Ja Mooses meni ja puhui kaikelle Israelille nämä sanat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'hän sanoi heille: \"Minä olen nyt sadan kahdenkymmenen vuoden vanha; en voi enää mennä ja tulla, ja Herra on sanonut minulle: \'Sinä et mene tämän Jordanin yli\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Mutta Herra, sinun Jumalasi, kulkee sinun edelläsi. Hän tuhoaa nämä kansat sinun tieltäsi, ja sinä lasket heidät valtasi alle. Joosua kulkee sinun edelläsi, niinkuin Herra on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Ja Herra tekee heille, niinkuin hän teki Siihonille ja Oogille, tuhoamillensa amorilaisten kuninkaille, ja heidän maallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Herra antaa heidät teille alttiiksi; tehkää heille aivan sen käskyn mukaan, jonka minä olen teille antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Olkaa lujat ja rohkeat, älkää peljätkö älkääkä säikähtykö heitä, sillä Herra, sinun Jumalasi, käy itse sinun kanssasi; hän ei jätä eikä hylkää sinua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Ja Mooses kutsui Joosuan ja sanoi hänelle koko Israelin läsnä ollessa: \"Ole luja ja rohkea, sillä sinä viet tämän kansan siihen maahan, jonka Herra heidän isillensä vannotulla valalla on luvannut antaa heille, ja sinä jaat sen heille perinnöksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Ja Herra itse käy sinun edelläsi, hän on sinun kanssasi, hän ei jätä sinua eikä hylkää sinua; älä pelkää äläkä arkaile.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Ja Mooses kirjoitti tämän lain ja antoi sen papeille, leeviläisille, jotka kantoivat Herran liitonarkkia, ja kaikille Israelin vanhimmille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Ja Mooses käski heitä sanoen: \"Joka seitsemäs vuosi, määrättynä aikana vapautusvuonna, lehtimajanjuhlassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'kun koko Israel tulee Herran, sinun Jumalasi, kasvojen eteen siinä paikassa, jonka hän valitsee, lue tämä laki koko Israelin läsnä ollessa, heidän kuultensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Kokoa kansa, miehet, naiset ja lapset sekä muukalaiset, jotka asuvat porttiesi sisäpuolella, että he kuulisivat sen ja oppisivat pelkäämään Herraa, teidän Jumalaanne, ja tarkoin pitämään kaikki tämän lain sanat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'ja että heidän lapsensa, jotka eivät vielä sitä tunne, kuulisivat sen ja oppisivat pelkäämään Herraa, teidän Jumalaanne, niin kauan kuin elätte siinä maassa, johon menette Jordanin yli, ottamaan sen omaksenne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Ja Herra sanoi Moosekselle: \"Katso, lähestyy aika, jolloin sinun on kuoltava. Kutsu Joosua, ja asettukaa ilmestysmajaan, niin minä asetan hänet virkaansa.\" Niin Mooses ja Joosua menivät ja asettuivat ilmestysmajaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Niin Herra ilmestyi majassa pilvenpatsaassa, ja pilvenpatsas seisahtui majan ovelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Ja Herra sanoi Moosekselle: \"Katso, sinä käyt lepäämään isiesi tykö; silloin tämä kansa nousee ja lähtee haureudessa kulkemaan vieraiden jumalien jäljessä, joita palvellaan siinä maassa, johon se menee, ja hylkää minut ja rikkoo liiton, jonka minä olen tehnyt sen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Sinä päivänä minun vihani syttyy sitä vastaan, ja minä hylkään heidät ja peitän kasvoni heiltä, niin että he joutuvat tuhon omiksi, ja suuret onnettomuudet ja ahdistukset kohtaavat sitä. Sinä päivänä se sanoo: \'Eivätkö nämä onnettomuudet ole kohdanneet minua sen tähden, ettei minun Jumalani ole minun keskelläni?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Mutta sinä päivänä minä kokonaan peitän kasvoni kaiken sen pahan tähden, mitä he ovat tehneet, kun ovat kääntyneet muiden jumalien puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Ja nyt kirjoittakaa itsellenne tämä virsi. Opeta se israelilaisille ja pane se heidän suuhunsa, että tämä laulu olisi minulle todistajana israelilaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Sillä minä vien heidät siihen maahan, jonka minä valalla vannoen olen luvannut heidän isillensä, maahan, joka vuotaa maitoa ja mettä, ja he syövät ja tulevat ravituiksi ja lihaviksi; mutta he kääntyvät muiden jumalien puoleen ja palvelevat niitä ja pitävät minua pilkkanaan ja rikkovat minun liittoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Ja kun suuret onnettomuudet ja ahdistukset kohtaavat heitä, niin tämä laulu on oleva todistajana heitä vastaan, eikä se ole unhottuva heidän jälkeläistensä suusta. Sillä minä tiedän heidän aikeensa, joita he hautovat jo ennenkuin minä olen vienyt heidät siihen maahan, josta minä olen valan vannonut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Ja Mooses kirjoitti tämän laulun sinä päivänä ja opetti sen israelilaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Ja hän asetti virkaan Joosuan, Nuunin pojan, ja sanoi: \"Ole luja ja rohkea, sillä sinä viet israelilaiset siihen maahan, jonka minä valalla vannoen olen heille luvannut, ja minä olen sinun kanssasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Ja kun Mooses oli kirjoittanut kirjaan tämän lain sanat, alusta loppuun asti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'käski hän leeviläisiä, jotka kantoivat Herran liitonarkkia, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, '\"Ottakaa tämä lain kirja ja pankaa se Herran, teidän Jumalanne, liitonarkin sivulle, olemaan siellä todistajana sinua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Sillä minä tunnen sinun tottelemattomuutesi ja uppiniskaisuutesi. Katso, minun vielä eläessäni teidän kanssanne te olette niskoitelleet Herraa vastaan; saati sitten minun kuoltuani!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Kootkaa minun luokseni kaikki sukukuntienne vanhimmat sekä päällysmiehenne, että minä heidän kuultensa puhuisin nämä sanat ja ottaisin taivaan ja maan todistajiksi heitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Sillä minä tiedän, että te minun kuoltuani vaellatte kelvottomasti ja poikkeatte siltä tieltä, jota minä käskin teidän vaeltaa. Sentähden on onnettomuus kohtaava teitä aikojen lopulla, kun te teette sitä, mikä on pahaa Herran silmissä, ja vihoitatte hänet kättenne teoilla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Ja Mooses lausui koko Israelin seurakunnan kuullen tämän virren sanat, alusta loppuun asti:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, '\"Kuunnelkaa, te taivaat, kun minä puhun, ja kuulkoon maa minun suuni sanat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Sateena pisaroikoon minun opetukseni, kasteena valukoon puheeni niinkuin vihma vihannalle, niinkuin sadekuuro ruohikolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Sillä minä julistan Herran nimeä; antakaa kunnia meidän Jumalallemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Hän on kallio; täydelliset ovat hänen tekonsa, sillä kaikki hänen tiensä ovat oikeat. Uskollinen Jumala ja ilman vääryyttä, vanhurskas ja vakaa hän on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Heidän menonsa oli paha häntä kohtaan, he eivät olleet hänen lapsiansa, vaan häpeäpilkku-tuo nurja ja kiero sukupolvi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Niinkö sinä maksat Herralle, sinä houkka ja tyhmä kansa? Eikö hän ole sinun isäsi, joka sinut loi? Hän sinut teki ja valmisti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Muistele muinaisia päiviä, ajattele menneiden sukupolvien vuosia. Kysy isältäsi, niin hän sen sinulle ilmoittaa, vanhimmiltasi, niin he sen sinulle sanovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Kun Korkein jakoi perinnöt kansoille, kun hän erotteli ihmisten lapset, silloin hän määräsi kansojen rajat israelilaisten luvun mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Sillä Herran kansa on hänen osuutensa, Jaakob on hänen perintöosansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Erämaasta hän löysi hänet, autiosta, ulvovasta korvesta; hän otti hänet suojaansa ja hoitoonsa, varjeli häntä kuin silmäteräänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Niinkuin kotka kiihoittaa pesuettaan lentoon ja liitelee poikastensa suojana, niin hän levitti siipensä, otti hänet ja kantoi häntä sulillansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Herra yksin johdatti häntä, eikä hänen kanssansa ollut ketään vierasta jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Hän kuljetti hänet maan kukkuloiden yli ja ruokki häntä pellon antimilla; hän antoi hänen imeä hunajaa kalliosta ja öljyä kovasta kivestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Hän antoi voita lehmistä ja maitoa lampaista sekä karitsain ja oinasten rasvaa, Baasanin härkiä ja kauriita ja parasta vehnän ydintä; ja sinä sait juoda rypäleen verta, tulista viiniä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Ja Jesurun lihoi ja alkoi potkia, sinä tulit lihavaksi, paksuksi ja aloit äksyillä. Niin hän hylkäsi Jumalan, joka oli tehnyt hänet, ja halveksui pelastuksensa kalliota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'He herättivät hänen kiivautensa vierailla jumalillaan, he vihoittivat hänet kauhistuksillansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'He uhrasivat riivaajille, epäjumalille, jumalille, joita he eivät tunteneet, uusille, äsken tulleille, joista teidän isänne eivät tienneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Kalliota, joka sinut synnytti, sinä et muistanut; sinä unhotit Jumalan, joka sinulle elämän antoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Herra näki sen ja hylkäsi heidät, sillä hän vihastui poikiinsa ja tyttäriinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Hän sanoi: \'Minä peitän heiltä kasvoni, minä katson, mikä heidän loppunsa on; sillä he ovat nurja suku, lapsia, joissa ei ole uskollisuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'He ovat herättäneet minun kiivauteni jumalilla, jotka eivät jumalia ole, ovat vihoittaneet minut turhilla jumalillansa; niin minäkin herätän heidän kiivautensa kansalla, joka ei ole kansa, vihoitan heidät houkalla pakanakansalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Sillä minun vihani tuli on syttynyt, ja se leimuaa tuonelan syvyyksiin saakka; se kuluttaa maan kasvuinensa ja polttaa vuorten perustukset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Minä kasaan onnettomuuksia heidän päällensä, kaikki nuoleni minä heihin ammun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'He nääntyvät nälkään ja menehtyvät ruttoon, kulkutautien poltteeseen; minä lähetän heidän kimppuunsa petojen hampaat ja tomussa matelevaisten myrkyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Ulkona surmaa miekka ja sisällä kauhu sekä nuorukaisen että neitosen, sekä imeväisen että harmaapään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Minä sanoisin: \'Minä puhallan heidät pois, hävitän heidän muistonsa ihmisten seasta\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'jollen varoisi, että vihollinen tuottaisi minulle mielipahaa, että heidän vastustajansa selittäisivät sen väärin, että he sanoisivat: \'Meidän kätemme oli korotettu, eikä Herra ole tästä kaikesta mitään tehnyt\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Sillä he ovat neuvoton kansa, eikä heissä ole ymmärrystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'Jos he viisaita olisivat, niin he käsittäisivät tämän, he ymmärtäisivät, mikä heidän loppunsa on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Kuinka yksi ajaisi tuhatta takaa, kuinka kaksi ajaisi pakoon kymmenentuhatta, jollei heidän kallionsa olisi heitä myynyt ja Herra luovuttanut heitä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Sillä heidän kallionsa ei ole niinkuin meidän kalliomme; niin vihollisemmekin päättelevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Sillä Sodoman viinipuita on heidän viinipuunsa, se on kotoisin Gomorran viinitarhoista; heidän rypäleensä ovat myrkkyrypäleitä, heidän viiniterttujensa maku on karvas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Heidän viininsä on lohikäärmeitten kähyä, kyykäärmeitten kauheata myrkkyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Eikö sitä ole talletettuna minun takanani, sinetillä lukittuna minun aitoissani?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Minun on kosto ja rankaiseminen, säästetty siksi ajaksi, jolloin heidän jalkansa horjuu. Sillä heidän onnettomuutensa päivä on lähellä, ja mikä heitä odottaa, se tulee rientäen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Sillä Herra hankkii oikeuden kansallensa ja armahtaa palvelijoitansa, koska hän näkee, että heidän voimansa on poissa ja että kaikki tyynni on lopussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Silloin hän kysyy: \'Missä ovat nyt niiden jumalat, missä kallio, johon he turvasivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'missä ne, jotka söivät heidän teurasuhriensa rasvan ja joivat heidän juomauhriensa viinin?\' Nouskoot ne auttamaan teitä, olkoot ne teidän suojananne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Katsokaa nyt, että minä, minä olen, eikä yhtäkään jumalaa ole minun rinnallani. Minä kuoletan ja minä teen eläväksi, minä lyön ja minä parannan; eikä ole sitä, joka pelastaisi minun käsistäni. 32:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Minä nostan käteni taivasta kohti ja sanon: Niin totta kuin minä elän iankaikkisesti, kun minä teroitan miekkani salaman,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'kun minun käteni ryhtyy tuomiota pitämään, niin minä kostan vastustajilleni ja maksan vihamiehilleni. Minä annan nuolteni juopua verestä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'ja minun miekkani syö lihaa-surmattujen ja vangittujen verestä, vihollispäällikköjen päistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Riemuiten ylistäkää, te pakanakansat, hänen kansaansa, sillä hän kostaa palvelijoittensa veren; hän antaa koston kohdata vastustajiansa ja toimittaa sovituksen maallensa, kansallensa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Ja Mooses tuli ja lausui kaikki tämän virren sanat kansan kuullen, hän itse ja Joosua, Nuunin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Ja kun Mooses oli puhunut loppuun kaikki nämä sanat koko Israelille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'sanoi hän heille: \"Painakaa sydämiinne kaikki ne sanat, jotka minä tänä päivänä teen todistajiksi teitä vastaan, niin että käskette lapsianne tarkoin täyttämään kaikki tämän lain sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Sillä ei ole se turha sana, joka ei koskisi teitä, vaan siinä on teidän elämänne; ja sen sanan varassa te elätte kauan siinä maassa, johon te menette Jordanin yli, ottamaan sen omaksenne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Ja Herra puhui Moosekselle sinä samana päivänä sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, '\"Nouse tänne Abarimin vuoristoon, Nebon vuorelle, joka on Mooabin maassa vastapäätä Jerikoa, ja katsele Kanaanin maata, jonka minä annan israelilaisten omaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Ja sinä kuolet sillä vuorella, jolle nouset, ja tulet otetuksi heimosi tykö, niinkuin sinun veljesi Aaron kuoli Hoorin vuorella ja tuli otetuksi heimonsa tykö,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'koska te lankesitte uskottomuuteen minua kohtaan israelilaisten keskellä Meriban veden ääressä Kaadeksessa, Siinin erämaassa, kun ette pitäneet minua pyhänä israelilaisten keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Niin, sinä saat katsella sitä maata matkan päästä, mutta sinne sinä et pääse, siihen maahan, jonka minä annan israelilaisille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Tämä on se siunaus, jolla Jumalan mies Mooses siunasi israelilaiset ennen kuolemaansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'hän sanoi: \"Herra tuli Siinailta, Seiristä hän nousi loistaen heille; hän ilmestyi kirkkaudessa Paaranin vuoristosta, hän tuli kymmentuhantisesta pyhien joukosta; hänen oikealla puolellansa liekitsi lain tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Hän rakastaa kansoja; kaikki niiden pyhät ovat sinun kädessäsi. He asettuvat sinun jalkojesi juureen, ottavat oppia sinun sanoistasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Mooses antoi meille lain, perintönä Jaakobin seurakunnalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Ja Herra tuli kuninkaaksi Jesurunissa, kun kansan päämiehet kokoontuivat, kaikki Israelin sukukunnat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Ruuben eläköön, älköön hän kuolko; mutta vähäiseksi jääköön hänen miestensä joukko.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Ja tämän hän sanoi Juudasta: \"Kuule, Herra, Juudan huuto ja tuo hänet kansansa luo. Hän sen puolesta käsillänsä taisteli; ole sinä apuna hänen vihollisiansa vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Ja Leevistä hän sanoi: \"Sinun tummimisi ja uurimisi olkoot sinun hurskaasi omat, sen miehen, jota sinä Massassa koettelit, jonka kanssa sinä riitelit Meriban veden luona,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'joka sanoi isästänsä ja äidistänsä: \'Minä en heitä nähnyt\', ja joka ei tunnustanut veljiään omiksensa eikä tuntenut omia lapsiansa. Sillä he noudattivat sinun sanaasi ja pysyivät sinun liitossasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'He opettavat sinun säädöksiäsi Jaakobille ja Israelille sinun lakiasi; he panevat suitsutusta sinun eteesi ja kokonaisuhreja sinun alttarillesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Siunaa, Herra, hänen voimansa, ja olkoon hänen kättensä työ sinulle otollinen. Ruhjo hänen vastustajiensa lanteet ja hänen vihamiehensä niin, että eivät enää nouse.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Benjaminista hän sanoi: \"Herran rakkaana hän asuu hänen turvissansa; Herra suojelee häntä aina ja asuu hänen kukkulainsa välissä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Ja Joosefista hän sanoi: \"Herra siunatkoon hänen maansa kalleimmalla, kasteella, joka tulee taivaasta, kalleimmalla, mikä tulee syvyydestä alhaalta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'kalleimmalla, minkä aurinko antaa, kalleimmalla, minkä kuun vaiheet tuottavat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'kalleimmalla, mikä tulee ikuisten vuorien huipuilta, kalleimmalla, mikä tulee ikikukkuloilta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'kalleimmalla, minkä maa kasvaa, ja kaikella, mitä siinä on, ja mielisuosiollaan, hän, joka pensaassa asui. Ne laskeutukoot Joosefin pään päälle, hänen päälaellensa, hänen, joka on ruhtinas veljiensä joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Uljas on hänen härkiensä esikoinen, sen sarvet ovat kuin villihärän sarvet; niillä se puskee kumoon kansat, kaikki tyynni maan ääriin saakka. Sellaisia ovat Efraimin kymmenet tuhannet, sellaisia Manassen tuhannet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Ja Sebulonista hän sanoi: \"Iloitse, Sebulon, kun liikkeelle lähdet, ja sinä, Isaskar, majoissasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'He kutsuvat kansoja vuorellensa, siellä he uhraavat oikeita uhreja. Sillä he imevät merten rikkauden ja hiekkaan kätketyt aarteet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Ja Gaadista hän sanoi: \"Kiitetty olkoon hän, joka on niin laajentanut Gaadin. Niinkuin naarasleijona hän asettuu leposijaansa ja raatelee sekä käsivarren että päälaen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Hän katsoi itsellensä parhaan osan maata, sillä siellä oli hänelle johtajan osa varattu. Mutta hän tuli kansan päämiesten kanssa, pani toimeen Herran vanhurskauden ja hänen tuomionsa yhdessä muun Israelin kanssa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Ja Daanista hän sanoi: \"Daan on nuori leijona, joka syöksyy esiin Baasanista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Ja Naftalista hän sanoi: \"Naftali on kylläinen mielisuosiosta ja täynnä Herran siunausta. Lännen ja etelän hän omaksensa ottakoon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Ja Asserista hän sanoi: \"Siunattu olkoon Asser poikien joukossa. Olkoon hän veljiensä lemmikki, ja kastakoon hän jalkansa öljyyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Rautaa ja vaskea olkoot sinun salpasi; ja niinkuin sinun päiväsi, niin olkoon sinun voimasikin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Ei kukaan ole niinkuin Jesurunin Jumala, joka kulkee taivasten yli sinun apunasi ja korkeudessaan pilvien päällitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Sinun turvasi on ikiaikojen Jumala, sinua kannattavat iankaikkiset käsivarret. Hän karkoitti viholliset sinun tieltäsi, hän sanoi: \'Hävitä!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Näin Israel asuu turvassa, Jaakobin lähde erillänsä viljan ja viinin maassa, jonka taivaskin tiukkuu kastetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Autuas olet sinä, Israel; kuka on sinun vertaisesi! Sinä olet kansa, jota Herra auttaa, hän, joka on sinun kilpesi ja suojasi, sinun miekkasi ja korkeutesi. Vihollisesi mielistelevät sinua, ja sinä astut heidän kukkuloillansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Ja Mooses nousi Mooabin arolta Nebon vuorelle, Pisgan huipulle, vastapäätä Jerikoa. Ja Herra näytti hänelle koko maan: Gileadin Daaniin asti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'koko Naftalin, Efraimin ja Manassen maan, koko Juudan maan aina Länsimereen asti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'Etelämaan sekä Lakeuden, se on Jerikon, Palmukaupungin, laakson, aina Sooariin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Ja Herra sanoi hänelle: \"Tämä on se maa, jonka minä valalla vannoen olen luvannut Aabrahamille, Iisakille ja Jaakobille, sanoen: \'Sinun jälkeläisillesi minä annan sen\'. Minä olen nyt antanut sinun omin silmin nähdä sen, mutta sinne sinä et mene.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Ja Herran palvelija Mooses kuoli siellä Mooabin maassa, Herran sanan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Ja hän hautasi hänet laaksoon Mooabin maahan, vastapäätä Beet-Peoria, mutta ei kukaan ole saanut tietää hänen hautaansa tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Ja Mooses oli kuollessaan sadan kahdenkymmenen vuoden vanha, mutta hänen silmänsä eivät olleet hämärtyneet, eikä hänen elinvoimansa ollut kadonnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Ja israelilaiset itkivät Moosesta Mooabin arolla kolmekymmentä päivää; sitten päättyi Mooseksen muistoksi vietetty itku-ja suruaika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Ja Joosua, Nuunin poika, oli täynnä viisauden henkeä, sillä Mooses oli pannut kätensä hänen päällensä; ja israelilaiset tottelivat häntä ja tekivät, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Mutta Israelissa ei enää noussut yhtäkään sellaista profeettaa kuin Mooses, jonka kanssa Herra seurusteli kasvoista kasvoihin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'ei ketään, joka olisi tehnyt sellaisia tunnustekoja ja ihmeitä, kuin hän Herran lähettämänä teki Egyptin maassa faraolle ja kaikille hänen palvelijoillensa, koko hänen maallensa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'ei ketään, jolla olisi ollut niin väkevä käsi ja joka olisi tehnyt niin suuria, peljättäviä tekoja, kuin hän teki koko Israelin silmien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Herran palvelijan Mooseksen kuoltua sanoi Herra Joosualle, Nuunin pojalle, Mooseksen palvelijalle, näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, '\"Minun palvelijani Mooses on kuollut; nouse siis ja mene tämän Jordanin yli, sinä ja kaikki tämä kansa, siihen maahan, jonka minä annan heille, israelilaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Jokaisen paikan, johon te jalkanne astutte, minä annan teille, niinkuin olen Moosekselle puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Maa erämaasta ja tuolta Libanonista aina suureen virtaan, Eufrat-virtaan, saakka-koko heettiläisten maa-ja aina Suureen mereen asti, auringonlaskuun päin, on oleva teidän aluettanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Ei kukaan kestä sinun edessäsi kaikkena elinaikanasi. Niinkuin minä olin Mooseksen kanssa, niin minä olen sinunkin kanssasi; minä en jätä sinua enkä hylkää sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Ole luja ja rohkea; sillä sinä jaat tälle kansalle perinnöksi sen maan, jonka minä heidän isillensä vannotulla valalla olen luvannut antaa heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Ole vain luja ja aivan rohkea ja noudata tarkoin kaikessa sitä lakia, jonka minun palvelijani Mooses on sinulle antanut; älä poikkea siitä oikealle äläkä vasemmalle, että menestyisit, missä ikinä kuljetkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Älköön tämä lain kirja sinun suustasi poistuko, vaan tutkiskele sitä päivät ja yöt, että tarkoin noudattaisit kaikkea, mitä siihen on kirjoitettu, sillä silloin sinä onnistut teilläsi ja silloin sinä menestyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Olenhan minä sinua käskenyt: Ole luja ja rohkea; älä säikähdy äläkä arkaile, sillä Herra, sinun Jumalasi, on sinun kanssasi, missä ikinä kuljetkin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Silloin Joosua käski kansan päällysmiehiä sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, '\"Kulkekaa halki leirin ja käskekää kansaa sanoen: \'Valmistakaa itsellenne evästä, sillä kolmen päivän kuluttua te kuljette tämän Jordanin yli mennäksenne ottamaan omaksenne sen maan, jonka Herra, teidän Jumalanne, teidän omaksenne antaa\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Mutta ruubenilaisille, gaadilaisille ja toiselle puolelle Manassen sukukuntaa Joosua sanoi näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, '\"Muistakaa sitä käskyä, jonka Herran palvelija Mooses teille antoi sanoen: \'Herra, teidän Jumalanne, suo teidän päästä rauhaan ja antaa teille tämän maan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Vaimonne, lapsenne ja karjanne jääkööt siihen maahan, jonka Mooses antoi teille tältä puolelta Jordanin. Mutta teidän itsenne, kaikkien sotaurhojen, on taisteluun valmiina lähdettävä veljienne etunenässä ja autettava heitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'kunnes Herra suo teidän veljienne päästä rauhaan niinkuin teidänkin, ja hekin ottavat omakseen sen maan, jonka Herra, teidän Jumalanne, heille antaa. Sitten saatte palata takaisin siihen maahan, joka on teidän omanne, ja ottaa omaksenne sen maan, jonka Herran palvelija Mooses antoi teille tältä puolelta Jordanin, auringonnousun puolelta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Niin he vastasivat Joosualle sanoen: \"Kaiken, minkä olet meidän käskenyt tehdä, me teemme, ja mihin ikinä meidät lähetät, sinne me menemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Niinkuin me olemme kaikessa totelleet Moosesta, niin me tottelemme sinuakin. Olkoon vain Herra, sinun Jumalasi, sinun kanssasi, niinkuin hän oli Mooseksen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Jokainen, joka niskoittelee sinun käskyjäsi vastaan eikä tottele sanojasi kaikessa, mitä hänelle käsket, surmattakoon. Ole vain luja ja rohkea.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Niin Joosua, Nuunin poika, lähetti salaa Sittimistä kaksi vakoojaa, sanoen: \"Menkää, katselkaa maata ja Jerikoa\". Ja he menivät ja tulivat Raahab nimisen porton taloon ja laskeutuivat siellä levolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Mutta Jerikon kuninkaalle kerrottiin näin: \"Katso, tänne on yöllä tullut miehiä israelilaisten joukosta vakoilemaan maata\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Silloin Jerikon kuningas lähetti sanan Raahabille: \"Tuo ulos ne miehet, jotka ovat tulleet luoksesi, jotka ovat tulleet sinun taloosi, sillä he ovat tulleet koko maata vakoilemaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Mutta vaimo otti molemmat miehet, piilotti heidät ja sanoi: \"Miehet kyllä tulivat minun luokseni, mutta en tiennyt, mistä he olivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Ja kun kaupungin portti pimeän tullen oli suljettava, niin miehet lähtivät ulos. En tiedä, minne miehet menivät; ajakaa nopeasti heitä takaa, niin te saavutatte heidät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Mutta hän oli vienyt heidät katolle ja kätkenyt heidät pellavanvarsien alle, joita oli asetellut katolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Niin miehet ajoivat heitä takaa Jordanin tietä kahlauspaikoille saakka, ja kaupungin portti suljettiin, niin pian kuin heidän takaa-ajajansa olivat menneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Mutta ennenkuin he olivat laskeutuneet levolle, nousi hän heidän luoksensa katolle ja sanoi miehille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, '\"Minä tiedän, että Herra antaa teille tämän maan ja että kauhu teitä kohtaan on vallannut meidät ja että kaikki maan asukkaat menehtyvät pelkoon teidän edessänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Sillä me olemme kuulleet, kuinka Herra kuivasi Kaislameren vedet teidän tieltänne, kun lähditte Egyptistä, ja mitä te teitte niille kahdelle amorilaisten kuninkaalle tuolla puolella Jordanin, Siihonille ja Oogille, jotka te vihitte tuhon omiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Kun me sen kuulimme, raukesi meidän sydämemme, eikä kenessäkään ole enää rohkeutta asettua teitä vastaan; sillä Herra, teidän Jumalanne, on Jumala ylhäällä taivaassa ja alhaalla maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Niin vannokaa nyt minulle Herran kautta, että niinkuin minä olen tehnyt teille laupeuden, tekin teette laupeuden minun isäni perheelle; ja antakaa minulle varma merkki siitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'että jätätte eloon minun isäni, äitini, veljeni, sisareni ja kaikki heidän omaisensa ja pelastatte meidät kuolemasta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Niin miehet sanoivat hänelle: \"Me vastaamme hengellämme teidän hengestänne, jos vain ette ilmaise tätä meidän asiaamme. Kun Herra antaa meille tämän maan, niin me osoitamme sinulle laupeutta ja uskollisuutta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Ja hän laski heidät köydellä alas ikkunasta, sillä hänen talonsa oli kiinni kaupungin muurissa, niin että hän asui muurissa kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Ja hän sanoi heille: \"Menkää vuoristoon, etteivät takaa-ajajat kohtaisi teitä, ja olkaa siellä piilossa kolme päivää, kunnes takaa-ajajat ovat palanneet; sitten voitte lähteä matkaanne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Niin miehet sanoivat hänelle: \"Me olemme vapaat siitä valasta, jonka meille vannotit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'jollet sinä, kun me tulemme tähän maahan, sido tätä punaista nauhaa siihen ikkunaan, josta laskit meidät alas, ja kokoa isääsi, äitiäsi, veljiäsi ja isäsi koko perhettä luoksesi taloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Ja kuka vain menee talosi ovesta ulos, sen veri tulkoon hänen oman päänsä päälle, ja me olemme vastuusta vapaat; mutta kuka vain on sinun kanssasi talossa, sen veri tulkoon meidän päämme päälle, jos kenen käsi sattuu häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Mutta jos sinä ilmaiset tämän meidän asiamme, niin me olemme vapaat valasta, jonka meillä vannotit.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Ja hän sanoi: \"Olkoon, niinkuin sanotte\", ja päästi heidät menemään, ja he lähtivät. Ja hän sitoi sen punaisen nauhan ikkunaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Niin he lähtivät ja tulivat vuoristoon ja viipyivät siellä kolme päivää, kunnes takaa-ajajat olivat palanneet. Ja takaa-ajajat etsivät heitä kaikkialta tien varrelta, mutta eivät löytäneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Sitten nuo kaksi miestä kääntyivät paluumatkalle. He laskeutuivat alas vuoristosta, menivät virran yli ja tulivat Joosuan, Nuunin pojan, luo ja kertoivat hänelle kaikki, mitä heille oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Ja he sanoivat Joosualle: \"Herra on antanut koko maan meidän käsiimme, ja kaikki maan asukkaat menehtyvät pelkoon meidän edessämme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Niin Joosua nousi varhain seuraavana aamuna, ja he lähtivät liikkeelle Sittimistä ja tulivat Jordanille, hän ja kaikki israelilaiset; ja he olivat siellä yötä, ennenkuin menivät virran yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Mutta kolmen päivän kuluttua kulkivat päällysmiehet halki leirin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'ja käskivät kansaa sanoen: \"Kun te näette Herran, teidän Jumalanne, liitonarkin ja leeviläiset papit sitä kantamassa, niin lähtekää tekin liikkeelle paikoiltanne ja seuratkaa sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Kuitenkin olkoon noin kahdentuhannen kyynärän välimatka teidän ja sen välillä-älkää menkö sitä lähelle-että tietäisitte tien, jota teidän on käytävä, sillä te ette ole ennen kulkeneet sitä tietä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Ja Joosua sanoi kansalle: \"Pyhittäytykää, sillä huomenna Herra on tekevä ihmeellisiä tekoja teidän keskuudessanne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Mutta papeille Joosua sanoi näin: \"Ottakaa liitonarkki ja kulkekaa kansan edellä\". Niin he ottivat liitonarkin ja kulkivat kansan edellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Silloin Herra sanoi Joosualle: \"Tästä päivästä alkaen minä teen sinut suureksi koko Israelin silmissä, jotta he tietäisivät, että niinkuin minä olin Mooseksen kanssa, niin minä olen sinunkin kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Käske pappeja, jotka kantavat liitonarkkia, ja sano: \'Kun tulette Jordanin veden ääreen, niin pysähtykää Jordanin rantaan\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Sitten Joosua sanoi israelilaisille: \"Tulkaa tänne ja kuulkaa Herran, teidän Jumalanne, sanat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Ja Joosua sanoi: \"Tästä saatte tietää, että elävä Jumala on teidän keskellänne ja karkoittaa teidän tieltänne kanaanilaiset, heettiläiset, hivviläiset, perissiläiset, girgasilaiset, amorilaiset ja jebusilaiset:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'katso, kaiken maan Herran liitonarkki kulkee teidän edellänne Jordanin poikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Ottakaa siis kaksitoista miestä Israelin sukukunnista, kustakin sukukunnasta yksi mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Niin pian kuin papit, jotka kantavat Herran, kaiken maan Herran, liitonarkkia, laskevat jalkansa Jordanin veteen, katkeaa Jordanin vesi, ylhäältä päin virtaava vesi, juoksussaan ja pysähtyy roukkioksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Kun kansa sitten lähti liikkeelle teltoistaan mennäksensä Jordanin poikki, liitonarkkia kantavien pappien käydessä kansan edellä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'ja niin pian kuin liitonarkin kantajat tulivat Jordanille ja liitonarkkia kantavien pappien jalat painuivat rantaveteen, niin vaikka Jordan koko elonleikkuuajan on tulvillaan yli kaikkien äyräidensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'pysähtyi ylhäältä päin virtaava vesi ja seisoi yhtenä roukkiona hyvin kaukana Aadamin luona, sen kaupungin, joka on Saaretanin vieressä; ja se vesi, joka virtasi alaspäin Aromereen, Suolamereen, hävisi kokonaan. Niin kansa kulki virran yli Jerikon kohdalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Ja Herran liitonarkkia kantavat papit seisoivat alallaan kuivalla pohjalla keskellä Jordania, kaiken Israelin kulkiessa kuivaa myöten, kunnes koko kansa oli ehtinyt kulkea Jordanin yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Ja kun koko kansa oli ehtinyt kulkea Jordanin yli, sanoi Herra Joosualle näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, '\"Ottakaa kansasta kaksitoista miestä, kustakin sukukunnasta yksi mies,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'ja käskekää heitä sanoen: \'Ottakaa itsellenne tästä, keskeltä Jordania, siltä kohdalta, missä papit seisovat alallaan, kaksitoista kiveä ja viekää ne mukananne ja asettakaa ne siihen paikkaan, mihin jäätte ensi yöksi\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Niin Joosua kutsui ne kaksitoista miestä, jotka hän oli määrännyt otettaviksi israelilaisista, yhden miehen kustakin sukukunnasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'ja Joosua sanoi heille: \"Menkää Herran, Jumalanne, arkin eteen keskelle Jordania, ja nostakoon kukin kiven olalleen israelilaisten sukukuntien luvun mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'että ne olisivat merkkinä teidän keskellänne. Kun lapsenne vastaisuudessa kysyvät ja sanovat: \'Mitä nämä kivet merkitsevät?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'niin vastatkaa heille: \'Sitä, että Jordanin vesi katkesi juoksussaan Herran liitonarkin edessä, kun se kulki Jordanin poikki; Jordanin vesi katkesi juoksussaan, ja siitä ovat nämä kivet muistona israelilaisille ikuisiksi ajoiksi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Ja israelilaiset tekivät, niinkuin Joosua oli käskenyt, ja ottivat israelilaisten sukukuntien luvun mukaan kaksitoista kiveä keskeltä Jordania, niinkuin Herra oli puhunut Joosualle, ja veivät ne mukanaan yöpaikkaan ja asettivat ne sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Ja Joosua pystytti kaksitoista kiveä keskelle Jordania sille kohdalle, jossa liitonarkkia kantavat papit seisoivat; ja ne ovat siellä vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Ja papit, jotka kantoivat arkkia, seisoivat keskellä Jordania, kunnes oli suoritettu kaikki, mitä Herra oli käskenyt Joosuan puhua kansalle, kaikki tyynni, mistä Mooses oli Joosualle käskyn antanut, ja kansa kulki nopeasti virran yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Ja kun koko kansa oli ehtinyt kulkea virran yli, menivät Herran arkki ja papit yli, kansan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Ja ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa kulkivat taisteluun valmiina israelilaisten etunenässä, niinkuin Mooses oli heille puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Noin nelikymmentuhantinen sotaan varustettu joukko heitä kulki Herran edellä taisteluun Jerikon arolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Sinä päivänä Herra teki Joosuan suureksi koko Israelin silmissä, ja he pelkäsivät häntä kaikkena hänen elinaikanansa, niinkuin olivat Moosesta peljänneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Ja Herra puhui Joosualle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, '\"Käske pappeja, jotka kantavat lain arkkia, astumaan ylös Jordanista.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Niin Joosua käski pappeja sanoen: \"Astukaa ylös Jordanista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Kun nyt Herran liitonarkkia kantavat papit astuivat ylös Jordanista, niin tuskin olivat pappien jalat nousseet kuivalle maalle, kun Jordanin vesi palasi paikoilleen ja juoksi niinkuin ennenkin yli kaikkien äyräidensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Kansa astui ylös Jordanista ensimmäisen kuun kymmenentenä päivänä. Ja he leiriytyivät Gilgaliin, Jerikon itäiselle rajalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Ja ne kaksitoista kiveä, jotka he olivat ottaneet Jordanista, Joosua pystytti Gilgaliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Ja hän sanoi israelilaisille näin: \"Kun lapsenne vastaisuudessa kysyvät isiltään ja sanovat: \'Mitä nämä kivet merkitsevät?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'niin ilmoittakaa se lapsillenne ja sanokaa: \'Israel kulki tämän Jordanin poikki kuivaa myöten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'koska Herra, teidän Jumalanne, kuivasi Jordanin veden teidän tieltänne, kunnes olitte kulkeneet virran poikki, samoinkuin Herra, teidän Jumalanne, teki Kaislamerelle, jonka hän kuivasi meidän tieltämme, kunnes olimme kulkeneet sen poikki,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'jotta kaikki maan kansat tulisivat tietämään, että Herran käsi on väkevä, ja jotta te pelkäisitte Herraa, teidän Jumalaanne, ainiaan\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Kun kaikki amorilaisten kuninkaat, jotka asuivat tällä puolella Jordanin, lännen puolella, ja kaikki kanaanilaisten kuninkaat, jotka asuivat meren rannalla, kuulivat, kuinka Herra oli kuivannut Jordanin veden israelilaisten tieltä, kunnes he olivat kulkeneet yli, niin raukesi heidän sydämensä, eikä heissä enää ollut rohkeutta asettua israelilaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Siihen aikaan Herra sanoi Joosualle: \"Tee itsellesi kiviveitsiä ja ympärileikkaa taas israelilaiset toistamiseen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Niin Joosua teki itselleen kiviveitsiä ja ympärileikkasi israelilaiset Esinahkakukkulan luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Ja syy siihen, että Joosua toimitti ympärileikkauksen, oli tämä: koko kansa, joka oli lähtenyt Egyptistä, miehenpuolet, kaikki sotakuntoiset miehet, olivat kuolleet matkalla erämaassa, heidän lähdettyään Egyptistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Sillä kaikki se kansa, joka oli lähtenyt, oli ollut ympärileikattu, mutta sitä kansaa, joka oli syntynyt matkalla erämaassa, heidän lähdettyään Egyptistä, ei oltu ympärileikattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Sillä neljäkymmentä vuotta olivat israelilaiset vaeltaneet erämaassa, kunnes oli hävinnyt koko se kansa, ne sotakuntoiset miehet, jotka olivat Egyptistä lähteneet, ne, jotka eivät olleet totelleet Herran ääntä ja joille Herra sentähden oli vannonut, ettei hän ollut salliva heidän nähdä sitä maata, jonka Herra heidän isillensä vannotulla valalla oli luvannut antaa meille, sitä maata, joka vuotaa maitoa ja mettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Mutta hän herätti heidän poikansa heidän sijaansa; ne Joosua ympärileikkasi, sillä he olivat ympärileikkaamattomia, koska ei heitä oltu ympärileikattu matkalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Kun koko kansa oli saatu ympärileikatuksi, pysyivät he paikallaan leirissä, kunnes olivat toipuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Niin Herra sanoi Joosualle: \"Tänä päivänä minä olen vierittänyt teidän päältänne Egyptin häväistyksen\". Sentähden kutsutaan paikkaa vielä tänäkin päivänä Gilgaliksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Kun israelilaiset olivat leiriytyneet Gilgaliin, viettivät he sen kuukauden neljäntenätoista päivänä, ehtoolla, pääsiäistä Jerikon arolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Ja pääsiäisen jälkeisenä päivänä he söivät sen maan tuotteista happamatonta leipää ja paahdettuja jyviä, juuri sinä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Mutta seuraavana päivänä lakkasi manna, koska he söivät sen maan tuotteita; eivätkä israelilaiset enää saaneet mannaa, vaan he söivät sinä vuonna Kanaanin maan satoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Ja tapahtui Joosuan ollessa Jerikon luona, että hän nosti silmänsä ja näki miehen seisovan edessään, paljastettu miekka kädessä. Ja Joosua meni hänen luokseen ja sanoi hänelle: \"Oletko sinä meikäläisiä vai vihollisiamme?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Niin hän sanoi: \"En, vaan minä olen Herran sotajoukon päämies ja olen juuri nyt tullut\". Niin Joosua heittäytyi kasvoilleen maahan, kumarsi ja sanoi hänelle: \"Mitä herrallani on sanottavana palvelijalleen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Ja Herran sotajoukon päämies sanoi Joosualle: \"Riisu kengät jalastasi, sillä paikka, jossa seisot, on pyhä\". Ja Joosua teki niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Mutta Jeriko sulki porttinsa ja oli suljettuna israelilaisilta: ei kukaan käynyt ulos, eikä kukaan käynyt sisälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Niin Herra sanoi Joosualle: \"Katso, minä annan sinun käsiisi Jerikon sekä sen kuninkaan ja sotaurhot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Kulkekaa siis, kaikki sotakuntoiset miehet, kaupungin ympäri, kiertäkää kerta kaupunki; tee niin kuutena päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Ja seitsemän pappia kantakoon seitsemää oinaansarvista pasunaa arkin edellä. Seitsemäntenä päivänä kulkekaa kaupungin ympäri seitsemän kertaa, ja papit puhaltakoot pasunoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Ja kun pitkä oinaansarven puhallus kuuluu, kun kuulette pasunan äänen, niin nostakoon koko kansa kovan sotahuudon; silloin kaupungin muuri kukistuu siihen paikkaansa, ja kansa voi rynnätä sinne ylös, kukin suoraan eteensä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Silloin Joosua, Nuunin poika, kutsui papit ja sanoi heille: \"Ottakaa liitonarkki, ja seitsemän pappia kantakoon seitsemää oinaansarvista pasunaa Herran arkin edellä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Sitten hän sanoi kansalle: \"Lähtekää ja kulkekaa kaupungin ympäri, ja aseväki käyköön Herran arkin edellä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Ja tapahtui, niinkuin Joosua oli kansalle sanonut. Ne seitsemän pappia, jotka kantoivat niitä seitsemää oinaansarvista pasunaa Herran edellä, lähtivät ja puhalsivat pasunoihin, ja Herran liitonarkki kulki heidän jäljessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Ja aseväki kulki pasunaa puhaltavien pappien edellä, mutta muu väki kulki arkin jäljessä, samalla kuin pasunoihin yhtenään puhallettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Ja Joosua käski kansaa sanoen: \"Älkää nostako sotahuutoa älkääkä antako äänenne kuulua, älköönkä sanaakaan pääskö teidän suustanne ennenkuin sinä päivänä, jona minä teille sanon: \'Nostakaa sotahuuto\', silloin se nostakaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Ja hän antoi Herran arkin kulkea yhden kierroksen kaupungin ympäri; sitten he menivät leiriin ja jäivät yöksi leiriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Joosua nousi varhain seuraavana aamuna, ja papit ottivat Herran arkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Ja ne seitsemän pappia, jotka kantoivat niitä seitsemää oinaansarvista pasunaa Herran arkin edellä, kulkivat puhaltaen yhtenään pasunoihin, ja aseväki kulki heidän edellään, mutta muu väki kulki Herran arkin jäljessä, samalla kuin pasunoihin yhtenään puhallettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Ja tänä toisenakin päivänä he kulkivat kerran kaupungin ympäri ja palasivat sitten leiriin. Niin he tekivät kuutena päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Mutta seitsemäntenä päivänä he nousivat varhain aamun sarastaessa ja kulkivat kaupungin ympäri samalla tavalla seitsemän kertaa. Ainoastaan sinä päivänä he kulkivat kaupungin ympäri seitsemän kertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Ja kun papit seitsemännellä kerralla puhalsivat pasunoihin, sanoi Joosua kansalle: \"Nostakaa sotahuuto, sillä Herra antaa teille kaupungin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Kaupunki ja kaikki, mitä siinä on, vihittäköön tuhon omaksi Herran kunniaksi; ainoastaan portto Raahab jääköön henkiin, hän ja kaikki, jotka ovat hänen kanssaan hänen talossansa, sillä hän piilotti tiedustelijat, jotka me lähetimme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Mutta karttakaa tuhon omaksi vihittyä, ettette vihi jotakin tuhon omaksi ja kuitenkin ota tuhon omaksi vihittyä ja niin tule vihkineiksi Israelin leiriä tuhon omaksi ja syökse sitä onnettomuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Ja kaikki hopea ja kulta sekä vaski-ja rautakalut olkoot pyhitetyt Herralle; ne joutukoot Herran aartehistoon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Silloin kansa nosti sotahuudon ja pasunoihin puhallettiin. Kun kansa kuuli pasunan äänen, niin se nosti kovan sotahuudon; silloin kukistui muuri siihen paikkaansa, ja kansa ryntäsi ylös kaupunkiin, kukin suoraan eteensä. Niin he valloittivat kaupungin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Ja he vihkivät miekan terällä tuhon omaksi kaiken, mitä kaupungissa oli, miehet ja naiset, nuoret ja vanhat, vieläpä härät, lampaat ja aasit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Mutta niille kahdelle miehelle, jotka olivat olleet vakoilemassa maata, Joosua sanoi: \"Menkää sen porton taloon ja tuokaa nainen ja kaikki hänen omaisensa sieltä ulos, niinkuin olette hänelle vannoneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Silloin ne nuoret miehet, jotka olivat olleet vakoilemassa, menivät ja toivat ulos Raahabin sekä hänen isänsä, äitinsä, veljensä ja kaikki hänen omaisensa; kaikki hänen sukulaisensa he toivat ulos ja jättivät heidät Israelin leirin ulkopuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Mutta kaupungin ja kaikki, mitä siinä oli, he polttivat tulella; ainoastaan hopean, kullan sekä vaski-ja rautakalut he panivat Herran huoneen aartehistoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Mutta portto Raahabin sekä hänen isänsä perheen ja kaikki hänen omaisensa Joosua jätti henkiin; ja hän jäi asumaan Israelin keskuuteen, aina tähän päivään asti, koska hän oli piilottanut ne tiedustelijat, jotka Joosua oli lähettänyt vakoilemaan Jerikoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Siihen aikaan Joosua vannotti tämän valan: \"Kirottu olkoon Herran edessä se mies, joka ryhtyy rakentamaan tätä Jerikon kaupunkia. Sen perustuksen laskemisesta hän menettäköön esikoisensa ja sen porttien pystyttämisestä nuorimpansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Ja Herra oli Joosuan kanssa, ja hänen maineensa levisi kautta maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Mutta israelilaiset menettelivät uskottomasti anastamalla itselleen tuhon omaksi vihittyä; sillä Aakan, Karmin poika, joka oli Sabdin poika, joka Serahin poika, Juudan sukukuntaa, otti itselleen tuhon omaksi vihittyä. Silloin syttyi Herran viha israelilaisia kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Ja Joosua lähetti miehiä Jerikosta Aihin, joka on lähellä Beet-Aavenia, itään päin Beetelistä, ja sanoi heille näin: \"Menkää vakoilemaan maata\". Niin miehet menivät ja vakoilivat Aita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Kun he palasivat Joosuan luo, sanoivat he hänelle: \"Älköön koko kansa menkö, vaan menköön noin kaksi tai kolme tuhatta miestä Aita valloittamaan; älä vaivaa koko kansaa sinne, sillä niitä on vähän\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Niin meni sinne kansasta noin kolme tuhatta miestä, mutta he kääntyivät pakoon Ain miesten edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Ja Ain miehet löivät heitä kuoliaaksi noin kolmekymmentä kuusi miestä, ajoivat heitä takaa kaupungin portilta Sebarimiin asti ja voittivat heidät rinteessä. Silloin kansan sydän raukesi ja tuli kuin vedeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Niin Joosua repäisi vaatteensa ja lankesi kasvoilleen maahan Herran arkin eteen ja oli siinä iltaan saakka, hän ja Israelin vanhimmat; ja he heittivät tomua päänsä päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Ja Joosua sanoi: \"Voi, Herra, Herra, minkätähden toit tämän kansan Jordanin yli antaaksesi meidät amorilaisten käsiin ja tuhotaksesi meidät? Oi, jospa olisimme päättäneet jäädä tuolle puolelle Jordanin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Oi, Herra, mitä sanoisinkaan, kun Israel on kääntynyt pakoon vihollistensa edestä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Kun kanaanilaiset ja kaikki muut maan asukkaat sen kuulevat, niin he saartavat meidät ja hävittävät meidän nimemme maan päältä. Mitä aiot tehdä suuren nimesi puolesta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Mutta Herra sanoi Joosualle: \"Nouse! Miksi makaat kasvoillasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israel on tehnyt syntiä, he ovat rikkoneet minun liittoni, jonka minä olen heille säätänyt; he ovat ottaneet sitä, mikä oli vihitty tuhon omaksi, he ovat varastaneet ja valhetelleet, he ovat panneet sen omain tavarainsa joukkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Sentähden israelilaiset eivät voi kestää vihollistensa edessä, vaan heidän täytyy kääntyä pakoon vihollistensa edestä, sillä he itse ovat vihityt tuhon omiksi. En minä enää ole teidän kanssanne, ellette hävitä keskuudestanne tuhon omaksi vihittyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Nouse, pyhitä kansa ja sano: Pyhittäytykää huomiseksi, sillä näin sanoo Herra, Israelin Jumala: Sinun keskuudessasi, Israel, on jotakin tuhon omaksi vihittyä; sinä et voi kestää vihollistesi edessä, ennenkuin olette poistaneet keskuudestanne tuhon omaksi vihityn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Astukaa siis huomenaamuna sukukunnittain esiin, ja se sukukunta, johon Herran arpa osuu, astukoon esiin suvuittain, ja se suku, johon Herran arpa osuu, astukoon esiin perhekunnittain, ja se perhekunta, johon Herran arpa osuu, astukoon esiin mies mieheltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Mutta se, jolta tavataan tuhon omaksi vihittyä, poltettakoon tulessa, hän ja kaikki, mitä hänellä on, sillä hän on rikkonut Herran liiton ja tehnyt häpeällisen teon Israelissa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Niin Joosua antoi varhain seuraavana aamuna Israelin sukukunnittain astua esiin; ja arpa osui Juudan sukukuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Silloin hän antoi Juudan sukukunnan astua esiin, ja arpa osui serahilaisten sukuun. Sitten hän antoi serahilaisten suvun astua esiin mies mieheltä, ja arpa osui Sabdiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Niin hän antoi hänen perhekuntansa mies mieheltä astua esiin, ja arpa osui Aakaniin, Karmin poikaan, joka oli Sabdin poika, joka Serahin poika, Juudan sukukuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Silloin Joosua sanoi Aakanille: \"Poikani, anna Herralle, Israelin Jumalalle, kunnia ja anna hänelle ylistys: tunnusta minulle, mitä olet tehnyt, äläkä salaa sitä minulta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Niin Aakan vastasi Joosualle ja sanoi: \"Minä todella olen tehnyt syntiä Herraa, Israelin Jumalaa, vastaan, sillä näin minä tein:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'kun minä näin saaliin joukossa kauniin sinearilaisen vaipan, kaksisataa sekeliä hopeata ja kultalevyn, viidenkymmenen sekelin painoisen, niin minussa syttyi niihin himo, ja minä otin ne; ne ovat kätkettyinä maahan keskelle minun telttaani, hopea alimpana\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Niin Joosua lähetti miehiä ottamaan selkoa, ja ne juoksivat telttaan. Siellä oli kätkö hänen teltassaan, hopea alimpana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Ja he ottivat ne teltasta, veivät ne Joosuan ja kaikkien israelilaisten luo ja panivat Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Niin Joosua yhdessä koko Israelin kanssa otti Aakanin, Serahin pojan, ja hopean, vaipan ja kultalevyn, sekä hänen poikansa, tyttärensä, härkänsä, aasinsa, lampaansa, telttansa ynnä kaikki, mitä hänellä oli, ja he veivät ne Aakorin laaksoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Ja Joosua sanoi: \"Miksi olet syössyt meidät onnettomuuteen? Herra syöksee sinut onnettomuuteen tänä päivänä.\" Silloin koko Israel kivitti hänet kuoliaaksi. He polttivat heidät tulessa ja kivittivät heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Ja he kasasivat hänen päällensä suuren kiviroukkion, joka vielä tänäkin päivänä on olemassa; ja niin Herra lauhtui vihansa hehkusta. Sentähden kutsutaan sitä paikkaa vielä tänäkin päivänä Aakorin laaksoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Ja Herra sanoi Joosualle: \"Älä pelkää äläkä arkaile. Ota mukaasi kaikki sotaväki ja lähde ja mene Aihin. Katso, minä annan sinun käsiisi Ain kuninkaan ja hänen kansansa, hänen kaupunkinsa ja maansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Ja tee Aille ja sen kuninkaalle, niinkuin teit Jerikolle ja sen kuninkaalle; kuitenkin saatte ryöstää itsellenne, mitä sieltä on saatavana saalista ja karjaa. Aseta väijytys kaupungin taa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Niin Joosua ynnä kaikki sotaväki lähti liikkeelle mennäkseen Aihin. Ja Joosua valitsi kolmekymmentä tuhatta miestä, sotaurhoa, ja lähetti heidät menemään yöllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Ja hän käski heitä sanoen: \"Asettukaa väijyksiin kaupungin taa, ei aivan kauas kaupungista; ja olkaa kaikki valmiina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Mutta minä ynnä kaikki se väki, joka on minun kanssani, lähenemme kaupunkia. Kun he sitten tulevat ulos meitä vastaan niinkuin ensi kerrallakin, niin me käännymme pakoon heidän edestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Ja he seuraavat meitä niin kauas, että eristämme heidät kaupungista, sillä he sanovat: \'He pakenevat meitä niinkuin ensi kerrallakin\'. Kun me näin pakenemme heitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'silloin nouskaa te väijytyksestä ja ottakaa kaupunki haltuunne, sillä Herra, teidän Jumalanne, antaa sen teidän käsiinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Ja kun olette saaneet kaupungin valtaanne, sytyttäkää kaupunki palamaan; tehkää Herran sanan mukaan. Huomatkaa, että minä käsken teidän tehdä sen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Sitten Joosua lähetti heidät menemään, ja he menivät ja asettuivat väijytyspaikkaan Beetelin ja Ain välille, länteen päin Aista. Mutta Joosua oli sen yön kansan kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Varhain seuraavana aamuna Joosua piti kansan katselmuksen ja lähti, hän ja Israelin vanhimmat, kansan etunenässä nousemaan Aihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Ja kaikki se sotaväki, joka oli hänen kanssaan, nousi, lähestyi ja tuli kaupungin edustalle; ja he leiriytyivät Ain pohjoispuolelle, niin että laakso oli heidän ja Ain välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Sitten hän otti noin viisituhatta miestä ja asetti heidät väijyksiin Beetelin ja Ain välille, länteen päin kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Niin kansa, koko leiri, joka oli kaupungin pohjoispuolella, ja kaupungin länsipuolella oleva jälkijoukko asetettiin asemiinsa. Mutta Joosua meni sinä yönä keskelle laaksoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Kun Ain kuningas näki sen, niin kaupungin miehet, kuningas ja kaikki hänen väkensä, lähtivät varhain aamulla nopeasti taisteluun Israelia vastaan määrättyyn paikkaan aromaan puolelle; hän ei näet tiennyt, että oli väijytys häntä vastaan kaupungin takana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Niin Joosua ja koko Israel olivat joutuvinaan tappiolle ja pakenivat erämaahan päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Silloin kaupungin koko väki kutsuttiin ajamaan heitä takaa; ja he ajoivat Joosuaa takaa, ja niin heidät eristettiin kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Eikä Aihin eikä Beeteliin jäänyt ainoatakaan miestä, joka ei lähtenyt Israelin jälkeen, vaan he jättivät kaupungin avoimeksi ja ajoivat takaa Israelia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Niin Herra sanoi Joosualle: \"Ojenna keihäs, joka on kädessäsi, Aita kohti, sillä minä annan sen sinun käsiisi\". Ja Joosua ojensi keihään, joka oli hänen kädessään, kaupunkia kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Silloin väijyksissä oleva joukko nousi kiiruusti paikaltaan ja riensi, niin pian kuin hän ojensi kätensä, ja tunkeutui kaupunkiin ja valloitti sen ja sytytti heti kaupungin palamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Kun Ain miehet kääntyivät ja katsoivat taaksensa, niin he näkivät kaupungista savun nousevan taivasta kohti; eivätkä he kyenneet pakenemaan, ei sinne eikä tänne, sillä se väki, joka pakeni erämaahan, kääntyi takaa-ajajia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Kun Joosua ja koko Israel näki, että väijyksissä ollut joukko oli valloittanut kaupungin ja että kaupungista nousi savu, niin he palasivat takaisin ja voittivat Ain miehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Ja myöskin ne toiset lähtivät kaupungista heitä vastaan, joten he joutuivat israelilaisten väliin, toisten ollessa edessä, toisten takana. Ja he voittivat heidät, päästämättä pakoon ja pelastumaan ainoatakaan heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Mutta Ain kuninkaan he ottivat kiinni elävänä ja toivat hänet Joosuan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Kun Israel oli surmannut kaikki Ain asukkaat kedolla, erämaassa, jonne he olivat heitä ajaneet takaa, ja he kaikki viimeiseen mieheen olivat kaatuneet miekan terään, palasi koko Israel Aihin, ja siellä olevat tapettiin miekan terällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Ja niitä, jotka sinä päivänä kaatuivat, miehiä ja naisia, oli kaikkiaan kaksitoista tuhatta, kaikki Ain asukkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Joosua ei vetänyt takaisin kättänsä, jossa hänellä oli keihäs ojennettuna, ennenkuin oli vihkinyt tuhon omiksi kaikki Ain asukkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Ainoastaan karjan, ja mitä kaupungista oli saatavana saalista, Israel ryösti itselleen sen määräyksen mukaan, jonka Herra oli Joosualle antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Ja Joosua poltti Ain ja teki siitä ikiajoiksi rauniokummun, aution aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Mutta Ain kuninkaan hän ripusti hirteen, jossa hän riippui iltaan asti. Mutta auringon laskiessa Joosua käski ottaa hänen ruumiinsa alas hirrestä, ja he heittivät sen kaupungin portin edustalle ja kasasivat sen päälle suuren kiviroukkion, joka on siellä vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Silloin Joosua rakensi Eebalin vuorelle alttarin Herralle, Israelin Jumalalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'niinkuin Herran palvelija Mooses oli käskenyt israelilaisten tehdä ja niinkuin on kirjoitettuna Mooseksen lain kirjassa: alttarin hakkaamattomista kivistä, joihin ei oltu rauta-aseella koskettu. Ja he uhrasivat sen päällä polttouhreja Herralle ja teurastivat teuraita yhteysuhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Ja hän kirjoitti siellä kiviin jäljennöksen Mooseksen laista, jonka tämä oli kirjoittanut israelilaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Ja koko Israel vanhimpineen, päällysmiehineen ja tuomareineen seisoi kummallakin puolella arkkia, päin leeviläisiä pappeja, jotka kantoivat Herran liitonarkkia, niin muukalaiset kuin maassasyntyneetkin, toinen puoli kääntyneenä Garissimin vuorta kohti, toinen puoli Eebalin vuorta kohti. Niin Israelin kansa ensiksi siunattiin, niinkuin Herran palvelija Mooses oli käskenyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'ja sen jälkeen hän luki kaikki lain sanat, siunauksen ja kirouksen, aivan niinkuin lain kirjassa on kirjoitettuna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Ei mitään siitä, mitä Mooses oli käskenyt, Joosua jättänyt lukematta kaiken Israelin seurakunnan läsnäollessa, niin myös naisten, lasten ja mukana kulkevien muukalaisten läsnäollessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Kun kaikki kuninkaat, jotka asuivat tällä puolella Jordanin, Vuoristossa, Alankomaassa ja pitkin Suuren meren koko rannikkoa Libanoniin päin, heettiläiset, amorilaiset, kanaanilaiset, perissiläiset, hivviläiset ja jebusilaiset, kuulivat, mitä oli tapahtunut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'niin he kokoontuivat yhteen sotiakseen yksimielisesti Joosuaa ja Israelia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Mutta kun Gibeonin asukkaat kuulivat, mitä Joosua oli tehnyt Jerikolle ja Aille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'niin hekin menettelivät viekkaasti: he menivät ja tekeytyivät lähettiläiksi, ottivat kuluneita säkkejä aasiensa selkään sekä kuluneita, repeytyneitä ja kiinnisolmeiltuja viinileilejä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'ja panivat kuluneet, paikatut kengät jalkaansa ja kuluneet vaatteet päällensä; ja kaikki heidän eväsleipänsä olivat kuivia ja murentuneita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Niin he menivät Joosuan luo Gilgalin leiriin ja sanoivat hänelle sekä Israelin miehille: \"Me olemme tulleet kaukaisesta maasta; tehkää siis liitto meidän kanssamme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Mutta Israelin miehet vastasivat hivviläisille: \"Kenties te asutte täällä meidän keskellämme; kuinka me tekisimme liiton teidän kanssanne?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Niin he sanoivat Joosualle: \"Me olemme sinun palvelijoitasi\". Joosua sanoi heille: \"Keitä te olette ja mistä tulette?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Niin he vastasivat hänelle: \"Palvelijasi tulevat hyvin kaukaisesta maasta Herran, sinun Jumalasi, nimen tähden. Sillä me olemme kuulleet hänestä kaiken, mitä hän teki Egyptissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'ja kaiken, mitä hän teki niille kahdelle amorilaisten kuninkaalle, jotka asuivat tuolla puolella Jordanin, Siihonille, Hesbonin kuninkaalle, ja Oogille, Baasanin kuninkaalle, joka asui Astarotissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Sentähden sanoivat meille meidän vanhimpamme ja kaikki maamme asukkaat näin: \'Ottakaa evästä mukaanne matkalle ja menkää heitä vastaan ja sanokaa heille: Me olemme teidän palvelijanne, tehkää siis liitto meidän kanssamme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Tämä leipämme oli vielä lämmintä, kun kotoa otimme sen evääksi lähtiessämme matkalle teidän luoksenne, ja katso, nyt se on kuivaa ja murentunutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Ja nämä viinileilit, jotka uusina täytimme, ovat nyt repeytyneitä; ja nämä vaatteemme ja kenkämme ovat kovin pitkällä matkalla kuluneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Niin miehet ottivat heidän evästänsä, mutta eivät kysyneet Herran mieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Niin Joosua takasi heille rauhan ja teki heidän kanssaan liiton, luvaten jättää heidät henkiin; ja kansan päämiehet vannoivat heille valan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Mutta kolmen päivän kuluttua, sen jälkeen kuin liitto heidän kanssaan oli tehty, saatiin kuulla, että he olivat lähiseuduilta ja asuivat heidän keskellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Niin israelilaiset lähtivät liikkeelle ja tulivat kolmantena päivänä heidän kaupunkeihinsa; ja heidän kaupunkinsa olivat Gibeon, Kefira, Beerot ja Kirjat-Jearim.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Mutta israelilaiset eivät surmanneet heitä, sillä kansan päämiehet olivat vannoneet heille valan Herran, Israelin Jumalan, kautta. Ja koko seurakunta napisi päämiehiä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Silloin kaikki päämiehet sanoivat koko seurakunnalle: \"Me olemme vannoneet heille valan Herran, Israelin Jumalan, kautta; sentähden me emme voi koskea heihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Mutta tämän me teemme heille, jättäessämme heidät henkiin, ettei viha kohtaisi meitä valan tähden, jonka olemme heille vannoneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Ja päämiehet sanoivat heistä: \"Jääkööt henkiin, mutta tulkoon heistä halonhakkaajia ja vedenkantajia kaikelle kansalle\". Näin päämiehet antoivat käskyn heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Silloin Joosua kutsui heidät ja puhui heille sanoen: \"Miksi olette pettäneet meidät ja sanoneet: \'Me asumme hyvin kaukana teistä\', vaikka asutte täällä meidän keskellämme?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Sentähden olkaa kirotut! Älköön ikinä ketään teistä päästettäkö olemasta minun Jumalani huoneen palvelijana, halonhakkaajana ja vedenkantajana.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'He vastasivat Joosualle ja sanoivat: \"Sinun palvelijoillesi oli kerrottu, että Herra, sinun Jumalasi, oli käskenyt palvelijaansa Moosesta antamaan teille koko tämän maan ja tuhoamaan kaikki maan asukkaat teidän tieltänne. Sentähden me suuresti pelkäsimme henkeämme teidän edessänne ja teimme tämän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Mutta katso, nyt me olemme sinun käsissäsi: tee meille, mikä mielestäsi on hyvin ja oikein.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Silloin hän teki heille näin: hän pelasti heidät israelilaisten käsistä, niin etteivät he heitä surmanneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Niin Joosua sinä päivänä määräsi heidät seurakunnan ja Herran alttarin halonhakkaajiksi ja vedenkantajiksi, aina tähän päivään asti, sitä paikkaa varten, jonka Herra oli valitseva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Kun Adonisedek, Jerusalemin kuningas, kuuli, että Joosua oli valloittanut Ain ja vihkinyt sen tuhon omaksi, tehden Aille ja sen kuninkaalle, niinkuin oli tehnyt Jerikolle ja sen kuninkaalle, ja että Gibeonin asukkaat olivat tehneet rauhan Israelin kanssa ja jääneet heidän keskuuteensa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'niin he peljästyivät suuresti, sillä Gibeon oli suuri kaupunki, niinkuin joku kuninkaankaupunki, ja suurempi kuin Ai, ja kaikki sen miehet olivat urhoollisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Ja Adonisedek, Jerusalemin kuningas, lähetti sanan Hoohamille, Hebronin kuninkaalle, Piramille, Jarmutin kuninkaalle, Jaafialle, Laakiin kuninkaalle, ja Debirille, Eglonin kuninkaalle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, '\"Tulkaa minun luokseni ja auttakaa minua, ja kukistakaamme Gibeon, koska se on tehnyt rauhan Joosuan ja israelilaisten kanssa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Niin nuo viisi amorilaisten kuningasta, Jerusalemin kuningas, Hebronin kuningas, Jarmutin kuningas, Laakiin kuningas ja Eglonin kuningas, kokoontuivat ja lähtivät liikkeelle kaikkine joukkoineen; ja he asettuivat leiriin Gibeonin edustalle ja ryhtyivät taisteluun sitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Silloin Gibeonin miehet lähettivät sanan Joosualle Gilgalin leiriin: \"Älköön sinun kätesi vetäytykö auttamasta palvelijoitasi. Tule nopeasti luoksemme, pelasta meidät ja auta meitä, sillä kaikki vuoristossa asuvien amorilaisten kuninkaat ovat kokoontuneet meitä vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Niin Joosua lähti Gilgalista, hän ja kaikki sotaväki hänen kanssaan ja kaikki sotaurhot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Silloin Herra sanoi Joosualle: \"Älä pelkää heitä, sillä minä annan heidät sinun käsiisi; ei kukaan heistä kestä sinun edessäsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Niin Joosua yllätti heidät, kuljettuaan kaiken yötä Gilgalista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Ja Herra saattoi heidät hämminkiin israelilaisten edessä, niin että nämä tuottivat heille suuren tappion Gibeonissa ja ajoivat heitä takaa Beet-Hooronin solatietä, surmaten heitä aina Asekaan ja Makkedaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Ja kun he paetessaan Israelia olivat Beet-Hooronin rinteessä, heitti Herra taivaasta heidän päällensä isoja kiviä, koko matkan Asekaan asti, niin että he kuolivat; niitä, jotka kuolivat raekivistä, oli useampia kuin niitä, jotka israelilaiset surmasivat miekalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Silloin puhui Joosua Herralle, sinä päivänä, jona Herra antoi amorilaiset israelilaisten valtaan, ja sanoi Israelin silmien edessä: \"Aurinko, seiso alallasi Gibeonissa, ja kuu Aijalonin laaksossa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Niin aurinko seisoi alallansa, ja kuu pysyi paikallansa, kunnes kansa oli kostanut vihollisilleen. Niinhän on kirjoitettuna \"Oikeamielisen kirjassa\". Niin aurinko pysyi paikallansa keskitaivaalla päiväkauden, kiirehtimättä laskemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Eikä ole ollut sen päivän vertaista, ei ennen eikä jälkeen, jona Herra näin kuuli ihmisen ääntä; sillä Herra soti Israelin puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Sen jälkeen Joosua ja koko Israel hänen kanssaan palasi Gilgalin leiriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Mutta nuo viisi kuningasta pakenivat ja piiloutuivat Makkedan luolaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Niin Joosualle ilmoitettiin: \"Ne viisi kuningasta on löydetty piiloutuneina Makkedan luolaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Silloin Joosua sanoi: \"Vierittäkää isoja kiviä luolan suulle ja asettakaa sen eteen miehiä vartioimaan heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Mutta te muut, älkää pysähtykö, vaan ajakaa takaa vihollisianne ja hakatkaa maahan heidän jälkijoukkonsa älkääkä päästäkö heitä menemään kaupunkeihinsa, sillä Herra, teidän Jumalanne, on antanut heidät teidän käsiinne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Kun sitten Joosua ja israelilaiset olivat tuottaneet heille hyvin suuren, perinpohjaisen tappion ja ne harvat, jotka olivat pelastuneet, olivat päässeet varustettuihin kaupunkeihin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'niin koko kansa palasi vahingoittumatonna takaisin Joosuan luo leiriin Makkedaan, eikä kukaan uskaltanut enää hiiskua sanaakaan israelilaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Silloin Joosua sanoi: \"Avatkaa luolan suu ja tuokaa ne viisi kuningasta minun eteeni luolasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Ja he tekivät niin ja toivat hänen eteensä ne viisi kuningasta luolasta: Jerusalemin kuninkaan, Hebronin kuninkaan, Jarmutin kuninkaan, Laakiin kuninkaan ja Eglonin kuninkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Ja kun he olivat tuoneet nämä kuninkaat Joosuan eteen, niin Joosua kutsui kaikki Israelin miehet ja sanoi sotaväen päälliköille, jotka olivat seuranneet häntä: \"Astukaa esiin ja pankaa jalkanne näiden kuninkaiden niskalle\". Niin he astuivat esiin ja panivat jalkansa heidän niskallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Silloin Joosua sanoi heille: \"Älkää peljätkö älkääkä arkailko, vaan olkaa lujat ja rohkeat, sillä näin on Herra tekevä kaikille teidän vihollisillenne, joita vastaan te joudutte sotimaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Sen jälkeen Joosua löi heidät kuoliaaksi ja ripusti heidät viiteen hirsipuuhun. Ja he riippuivat hirressä iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Mutta auringonlaskun aikaan Joosua käski ottaa heidät alas hirrestä ja heittää luolaan, johon he olivat piiloutuneet. Ja he panivat luolan suulle isoja kiviä, jotka ovat siinä vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Samana päivänä Joosua valloitti Makkedan ja surmasi miekan terällä sen asukkaat ja sen kuninkaan; hän vihki tuhon omiksi heidät ja jokaisen, joka siellä oli, päästämättä pakoon ainoatakaan. Ja hän teki Makkedan kuninkaalle, niinkuin oli tehnyt Jerikon kuninkaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Sitten Joosua ja koko Israel hänen kanssaan lähti Makkedasta Libnaan ja ryhtyi taisteluun Libnaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Ja Herra antoi senkin ja sen kuninkaan Israelin käsiin. Ja Joosua surmasi miekan terällä sen asukkaat, jokaisen, joka siellä oli, päästämättä sieltä pakoon ainoatakaan; ja hän teki sen kuninkaalle saman, minkä oli tehnyt Jerikon kuninkaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Sitten Joosua ja koko Israel hänen kanssaan lähti Libnasta Laakiiseen ja asettui leiriin sen edustalle ja ryhtyi taisteluun sitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Ja Herra antoi Laakiin Israelin käsiin, niin että hän valloitti sen toisena päivänä; ja hän surmasi miekan terällä sen asukkaat, jokaisen, joka siellä oli, samoin kuin oli tehnyt Libnalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Silloin Hooram, Geserin kuningas, tuli auttamaan Laakista; mutta Joosua voitti hänet ja hänen väkensä, päästämättä pakoon ainoatakaan heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Ja Laakiista Joosua ja koko Israel hänen kanssaan lähti Egloniin, ja he asettuivat leiriin sen edustalle ja ryhtyivät taisteluun sitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Ja he valloittivat sen samana päivänä ja surmasivat miekan terällä sen asukkaat, ja hän vihki sinä päivänä tuhon omaksi jokaisen, joka siellä oli, samoin kuin oli tehnyt Laakiille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Sen jälkeen Joosua ja koko Israel hänen kanssaan lähti Eglonista Hebroniin, ja he ryhtyivät taisteluun sitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Ja he valloittivat sen ja surmasivat miekan terällä sen asukkaat ja sen kuninkaan, ja samoin kaikki sen alaiset kaupungit ja jokaisen, joka siellä oli, päästämättä pakoon ainoatakaan, samoin kuin hän oli tehnyt Eglonille. Hän vihki tuhon omaksi sen ja jokaisen, joka siellä oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Sitten Joosua ja koko Israel hänen kanssaan kääntyi Debiriin ja ryhtyi taisteluun sitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Ja hän sai valtaansa sen ja sen kuninkaan ja kaikki sen alaiset kaupungit, ja he surmasivat miekan terällä niiden asukkaat ja vihkivät tuhon omaksi jokaisen, joka siellä oli, päästämättä pakoon ainoatakaan. Hän teki Debirille ja sen kuninkaalle saman, minkä oli tehnyt Hebronille ja minkä oli tehnyt Libnalle ja sen kuninkaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Sitten Joosua valtasi koko maan, Vuoriston, Etelämaan, Alankomaan ja Rinnemaat, ja surmasi kaikki niiden kuninkaat, päästämättä pakoon ainoatakaan, ja vihki tuhon omaksi joka hengen, niinkuin Herra, Israelin Jumala, oli käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Ja Joosua valtasi heidän alueensa Kaades-Barneasta Gassaan saakka ja koko Goosenin maakunnan Gibeoniin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Kaikki nämä kuninkaat ja heidän maansa Joosua sai valtaansa yhdellä otteella; sillä Herra, Israelin Jumala, soti Israelin puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Sitten Joosua ja koko Israel hänen kanssaan palasi Gilgalin leiriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Kun Jaabin, Haasorin kuningas, sen kuuli, lähetti hän sanan Joobabille, Maadonin kuninkaalle, ja Simronin kuninkaalle ja Aksafin kuninkaalle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'ja niille kuninkaille, jotka asuivat pohjoisessa, Vuoristossa, Aromaassa Kinarotista etelään päin, Alankomaassa ja Doorin kukkuloilla lännessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'kanaanilaisille itään ja länteen, amorilaisille, heettiläisille, perissiläisille ja jebusilaisille vuoristoon ja hivviläisille Hermonin juurelle Mispan maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Nämä lähtivät liikkeelle kaikkine joukkoineen; väkeä oli niin paljon kuin hiekkaa meren rannalla ja hevosia ja sotavaunuja ylen paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Ja kaikki nämä kuninkaat liittyivät yhteen, tulivat ja leiriytyivät yhdessä Meeromin veden rannalle sotiaksensa Israelia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Silloin Herra sanoi Joosualle: \"Älä pelkää heitä, sillä huomenna tähän aikaan minä annan heidät kaikki voitettuina Israelin valtaan; heidän ratsujensa vuohisjänteet sinä katkot, ja heidän vaununsa sinä poltat tulessa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Niin Joosua ja kaikki sotaväki hänen kanssaan yllätti heidät Meeromin veden rannalla ja hyökkäsi heidän kimppuunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Ja Herra antoi heidät Israelin käsiin, niin että he voittivat heidät ja ajoivat heitä takaa aina suureen Siidoniin, Misrefot-Majimiin ja itään päin Mispan laaksoon asti; ja he voittivat heidät, päästämättä pakoon ainoatakaan heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Ja Joosua teki heille, niinkuin Herra oli hänelle sanonut: heidän ratsujensa vuohisjänteet hän katkoi, ja heidän vaununsa hän poltti tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Sitten Joosua kääntyi takaisin ja valloitti Haasorin ja surmasi miekalla sen kuninkaan; Haasor oli näet muinoin kaikkien näiden kuningaskuntien pääkaupunki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Ja he surmasivat miekan terällä ja vihkivät tuhon omaksi jokaisen, joka siellä oli, niin ettei jäänyt jäljelle ainoatakaan henkeä; ja Haasorin hän poltti tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Kaikki nämä kuninkaankaupungit ja niiden kuninkaat Joosua sai valtaansa, ja hän surmasi miekan terällä niiden asukkaat, vihkien heidät tuhon omiksi, niinkuin Herran palvelija Mooses oli käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Mutta kukkuloilla olevista kaupungeista Israel ei polttanut ainoatakaan, paitsi Haasorin, jonka Joosua poltti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Ja kaiken, mitä näistä kaupungeista oli saatavana saalista, ynnä karjan israelilaiset ryöstivät itselleen; mutta kaikki ihmiset he surmasivat miekan terällä ja tuhosivat heidät, jättämättä eloon ainoatakaan henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Niinkuin Herra oli käskenyt palvelijaansa Moosesta, niin oli Mooses käskenyt Joosuaa, ja niin Joosua teki; eikä hän jättänyt tekemättä mitään kaikesta siitä, mistä Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Niin Joosua valloitti koko tämän maan, Vuoriston, koko Etelämaan ja koko Goosenin maakunnan, Alankomaan ja Aromaan, niin myös Israelin vuoriston ja sen alankomaan-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'maan Seiriin päin kohoavasta Sileästä vuoresta aina Baal-Gaadiin saakka, Libanonin laaksoon, Hermonin vuoren juurelle; kaikki heidän kuninkaansa hän sai valtaansa ja löi heidät kuoliaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Kauan aikaa Joosua kävi sotaa kaikkia näitä kuninkaita vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Eikä ollut ainoatakaan kaupunkia, joka olisi tehnyt rauhan Israelin kanssa, paitsi ne hivviläiset, jotka asuivat Gibeonissa; vaan kaikki valloitettiin asevoimalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Sillä Herralta tämä tuli; hän paadutti heidän sydämensä, niin että he kävivät taisteluun Israelia vastaan, jotta heidät armotta vihittäisiin tuhon omiksi ja hävitettäisiin, niinkuin Herra oli Moosekselle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Siihen aikaan Joosua tuli ja hävitti anakilaiset vuoristosta, Hebronista, Debiristä ja Anabista, koko Juudan vuoristosta ja koko Israelin vuoristosta; Joosua vihki heidät kaupunkeineen tuhon omiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Israelilaisten maahan ei jäänyt anakilaisia; ainoastaan Gassaan, Gatiin ja Asdodiin niitä jäi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Näin Joosua valloitti koko maan, aivan niinkuin Herra oli Moosekselle puhunut; ja Joosua antoi sen perintöosaksi Israelille, heidän sukukunnilleen heidän osastojensa mukaan. Ja maa pääsi rauhaan sodasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Nämä olivat ne maan kuninkaat, jotka israelilaiset voittivat ja joiden maan he ottivat omakseen tuolla puolella Jordanin, auringonnousun puolella, maan Arnon-joesta aina Hermonin vuoreen saakka ja koko itäpuolisen Aromaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Siihon, amorilaisten kuningas, joka asui Hesbonissa ja hallitsi maata Arnon-joen rannalla olevasta Aroerista ja jokilaakson keskikohdalta, ja puolta Gileadia, Jabbok-jokeen saakka, joka on ammonilaisten rajana,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'ja Aromaata aina Kinerotin järveen, sen itärantaan, saakka ja Aromaan mereen, Suolamereen, sen itärantaan, saakka, Beet-Jesimotin tienoille, ja etelään päin Pisgan rinteiden juurelle saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Ja he ottivat omakseen Oogin, Baasanin kuninkaan, alueen, hänen, joka oli viimeisiä refalaisia ja asui Astarotissa ja Edreissä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'ja hallitsi Hermonin vuorta, Salkaa ja koko Baasania gesurilaisten ja maakatilaisten alueeseen saakka ja toista puolta Gileadia, Hesbonin kuninkaan Siihonin alueeseen saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Herran palvelija Mooses ja israelilaiset olivat voittaneet heidät; ja Herran palvelija Mooses oli antanut maan omaksi ruubenilaisille ja gaadilaisille ja toiselle puolelle Manassen sukukuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Ja nämä olivat ne maan kuninkaat, jotka Joosua ja israelilaiset voittivat tällä puolella Jordanin, länsipuolella, Libanonin laaksossa olevasta Baal-Gaadista aina Seiriin päin kohoavaan Sileään vuoreen saakka, ja joiden maan Joosua antoi Israelin sukukuntien omaksi, heidän osastojensa mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Vuoristossa, Alankomaassa, Aromaassa, Rinnemaissa, Erämaassa ja Etelämaassa, heettiläisten, amorilaisten, kanaanilaisten, perissiläisten, hivviläisten ja jebusilaisten maan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Jerikon kuningas yksi, lähellä Beeteliä olevan Ain kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Jerusalemin kuningas yksi, Hebronin kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Jarmutin kuningas yksi, Laakiin kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Eglonin kuningas yksi, Geserin kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Debirin kuningas yksi, Gederin kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Horman kuningas yksi, Aradin kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Libnan kuningas yksi, Adullamin kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Makkedan kuningas yksi, Beetelin kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Tappuahin kuningas yksi, Heeferin kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Afekin kuningas yksi, Lassaronin kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Maadonin kuningas yksi, Haasorin kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Simron-Meronin kuningas yksi, Aksafin kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Taanakin kuningas yksi, Megiddon kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Kedeksen kuningas yksi, Karmelin juurella olevan Jokneamin kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'Doorin kukkuloilla olevan Doorin kuningas yksi, Gilgalin seudun pakanain kuningas yksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Tirsan kuningas yksi. Kaikkiaan kolmekymmentä yksi kuningasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Kun Joosua oli käynyt vanhaksi ja iäkkääksi, sanoi Herra hänelle: \"Sinä olet käynyt vanhaksi ja iäkkääksi, mutta vielä on hyvin paljon maata valtaamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Tämä on se maa, mikä vielä on jäljellä: kaikki filistealaisten alueet ja koko gesurilaisten maa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Siihorista alkaen, joka on itään päin Egyptistä, aina Ekronin alueeseen saakka pohjoiseen päin-se luetaan kanaanilaisten alueeseen-ne viisi filistealaista ruhtinasta, nimittäin Gassan, Asdodin, Askelonin, Gatin ja Ekronin ruhtinaat, niin myöskin avvilaiset');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'etelässä päin; koko kanaanilaisten maa ja Meara, joka on siidonilaisten, Afekiin saakka, amorilaisten alueeseen saakka;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'ja gebalilaisten maa ja koko Libanon, auringonnousun puolella, Hermonin vuoren juurella olevasta Baal-Gaadista siihen saakka, mistä mennään Hamatiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Kaikki vuoriston asukkaat Libanonista Misrefot-Majimiin saakka, kaikki siidonilaiset, minä karkoitan israelilaisten tieltä; arvo vain niiden maa Israelin kesken perintöosaksi, niinkuin minä olen sinulle käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Jaa siis tämä maa perintöosana yhdeksälle sukukunnalle ja toiselle puolelle Manassen sukukuntaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Samalla kuin sen toinen puoli olivat näet myöskin ruubenilaiset ja gaadilaiset saaneet perintöosansa, jonka Mooses antoi heille tuolta puolelta Jordanin, idän puolelta, niinkuin Herran palvelija Mooses sen heille antoi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'maan Arnon-joen rannalla olevasta Aroerista ja jokilaakson keskikohdalla olevasta kaupungista alkaen ja koko Meedeban ylätasangon Diiboniin saakka;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'ja kaikki Siihonin, amorilaisten kuninkaan, kaupungit, hänen, joka hallitsi Hesbonissa, aina ammonilaisten alueeseen saakka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'ja Gileadin sekä gesurilaisten ja maakatilaisten alueet ja koko Hermonin vuoren ja koko Baasanin Salkaan saakka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'koko Oogin valtakunnan Baasanissa, hänen, joka hallitsi Astarotissa ja Edreissä ja oli viimeisiä refalaisia; nämä Mooses voitti ja karkoitti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Mutta israelilaiset eivät karkoittaneet gesurilaisia ja maakatilaisia, vaan gesurilaiset ja maakatilaiset jäivät asumaan Israelin keskeen aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Ainoastaan Leevin sukukunnalle hän ei antanut perintöosaa. Herran, Israelin Jumalan, uhrit ovat sen perintöosa, niinkuin hän on sille puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Mooses antoi ruubenilaisten sukukunnalle, heidän suvuilleen, maata:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'heille tuli alue Arnon-joen rannalla olevasta Aroerista ja jokilaakson keskikohdalla olevasta kaupungista alkaen ja koko ylätasanko Meedeban luona;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon ynnä kaikki sen alaiset kaupungit, jotka ovat ylätasangolla, Diibon, Baamot-Baal, Beet-Baal-Meon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jahas, Kedemot, Meefaat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kirjataim, Sibma, Seret-Sahar Laaksovuorella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Beet-Peor ja Pisgan rinteet ja Beet-Jesimot;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'ja kaikki ylätasangon kaupungit ja Siihonin, amorilaisten kuninkaan, koko valtakunta, hänen, joka hallitsi Hesbonissa ja jonka Mooses voitti samalla kuin Midianin ruhtinaat Evin, Rekemin, Suurin, Huurin ja Reban, jotka olivat Siihonin aliruhtinaita ja asuivat siinä maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Muiden mukana, jotka kaatuivat, israelilaiset surmasivat miekalla myöskin Bileamin, Beorin pojan, tietäjän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Ruubenilaisten raja on Jordan; se on rajana. Tämä on ruubenilaisten, heidän sukujensa, perintöosa, kaupungit kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Mooses antoi Gaadin sukukunnalle, gaadilaisille, heidän suvuilleen, maata:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'heidän alueekseen tuli Jaeser, ja kaikki Gileadin kaupungit ja puolet ammonilaisten maata Aroeriin asti, joka on itään päin Rabbasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'ja maa Hesbonista Raamat-Mispeen ja Betonimiin saakka, ja Mahanaimista Lidebirin alueeseen saakka;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'ja laaksossa: Beet-Raam, Beet-Nimra, Sukkot ja Saafon, loput Siihonin, Hesbonin kuninkaan, valtakunnasta, rajana Jordan Kinneretin järven päähän saakka, tuolla puolella Jordanin, idän puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Tämä on gaadilaisten, heidän sukujensa, perintöosa, kaupungit kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Mooses antoi toiselle puolelle Manassen sukukuntaa maata, ja se tuli toiselle puolelle Manassen sukukuntaa, heidän suvuilleen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'heidän alueekseen tuli Mahanaimista alkaen koko Baasan, Oogin, Baasanin kuninkaan, koko valtakunta, kaikki Jaairin leirikylät Baasanissa, kuusikymmentä kaupunkia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'ja puolet Gileadia sekä Astarot ja Edrei, Oogin valtakunnan pääkaupungit Baasanissa; tämä tuli Maakirin, Manassen pojan, jälkeläisille, toiselle puolelle Maakirin jälkeläisiä, heidän suvuilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Nämä ovat ne alueet, jotka Mooses jakoi perintöosiksi Mooabin arolla, tuolla puolella Jordanin, Jerikon kohdalla, idän puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Mutta Leevin sukukunnalle Mooses ei antanut perintöosaa. Herra, Israelin Jumala, on heidän perintöosansa, niinkuin hän on heille puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Nämä ovat ne alueet, jotka israelilaiset saivat perintöosiksi Kanaanin maassa, ne, jotka pappi Eleasar ja Joosua, Nuunin poika, ja israelilaisten sukukuntien perhekunta-päämiehet jakoivat heille');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'arvalla perintöosiksi sen käskyn mukaisesti, jonka Herra oli yhdeksästä ja puolesta sukukunnasta antanut Mooseksen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Sillä Mooses oli antanut kahdelle ja puolelle sukukunnalle perintöosat tuolta puolelta Jordanin, mutta leeviläisille hän ei antanut perintöosaa heidän keskellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Sillä joosefilaisia oli kaksi sukukuntaa, Manasse ja Efraim; ja leeviläisille ei annettu osuutta maahan, vaan ainoastaan kaupunkeja heidän asuaksensa sekä niiden laidunmaat heidän karjaansa ja omaisuuttansa varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Niinkuin Herra oli Moosekselle käskyn antanut, niin israelilaiset tekivät ja jakoivat maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Silloin juudalaiset astuivat Joosuan eteen Gilgalissa, ja kenissiläinen Kaaleb, Jefunnen poika, sanoi hänelle: \"Sinä tunnet sen sanan, jonka Herra puhui Jumalan miehelle Moosekselle minusta ja sinusta Kaades-Barneassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Minä olin neljänkymmenen vuoden vanha, kun Herran palvelija Mooses lähetti minut Kaades-Barneasta vakoilemaan maata, ja minä annoin hänelle tietoja parhaan ymmärrykseni mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Mutta veljeni, jotka olivat käyneet siellä minun kanssani, saivat kansan sydämen raukeamaan, kun taas minä uskollisesti seurasin Herraa, Jumalaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Sinä päivänä Mooses vannoi sanoen: \'Totisesti, se maa, johon sinä olet jalkasi astunut, on tuleva sinulle ja sinun lapsillesi perintöosaksi ikiaikoihin asti, koska sinä olet uskollisesti seurannut Herraa, minun Jumalaani\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Ja nyt, katso, Herra on antanut minun elää, niinkuin hän oli sanonut, vielä neljäkymmentä viisi vuotta sen jälkeen, kuin Herra puhui tämän sanan Moosekselle, Israelin vaeltaessa erämaassa. Ja katso, minä olen nyt kahdeksankymmenen viiden vuoden vanha');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'ja olen vielä tänä päivänä yhtä voimakas, kuin olin sinä päivänä, jona Mooses minut lähetti; niinkuin voimani oli silloin, niin se on vielä nytkin: minä kykenen sotimaan, lähtemään ja tulemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Anna minulle siis tämä vuoristo, josta Herra puhui sinä päivänä. Sinähän kuulit sinä päivänä, että siellä asuu anakilaisia ja että siellä on suuria, varustettuja kaupunkeja. Kenties Herra on minun kanssani, niin että minä saan heidät karkoitetuksi, niinkuin Herra on puhunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Silloin Joosua siunasi Kaalebin, Jefunnen pojan, ja antoi hänelle perintöosaksi Hebronin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Niin Hebron tuli kenissiläisen Kaalebin, Jefunnen pojan, perintöosaksi, niinkuin se on tänäkin päivänä, sentähden että hän oli uskollisesti seurannut Herraa, Israelin Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Mutta Hebronin nimi oli muinoin Kirjat-Arba, Arban mukaan, joka oli mahtavin mies anakilaisten joukossa. Ja maa pääsi rauhaan sodasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Juudan jälkeläisten sukukunta, heidän sukunsa, saivat arpaosansa etelästä, Edomin rajaan ja Siinin erämaahan päin, etäisintä etelää myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Heidän eteläinen rajansa alkaa Suolameren päästä, sen eteläisimmästä pohjukasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'jatkuu Skorpionisolan eteläpuolitse, kulkee Siiniin, nousee Kaades-Barnean eteläpuolitse, kulkee Hesroniin, nousee Addariin ja kääntyy Karkaan päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Edelleen se kulkee Asmoniin ja jatkuu Egyptin puroon; sitten raja päättyy mereen. Tämä olkoon teidän eteläinen rajanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Itäisenä rajana on Suolameri Jordanin suuhun saakka. Pohjoinen raja alkaa siitä meren pohjukasta, jossa on Jordanin suu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Sieltä raja nousee Beet-Hoglaan ja kulkee Beet-Araban pohjoispuolitse; edelleen raja nousee Boohanin, Ruubenin pojan, kiveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Sitten raja nousee Debiriin Aakorin laaksosta ja kääntyy pohjoiseen päin Gilgalia kohti, joka on vastapäätä puron eteläpuolella olevaa Adummimin solaa; sitten raja kulkee Een-Semeksen veteen ja päättyy Roogelin lähteeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Edelleen raja nousee Ben-Hinnomin laaksoon, Jebusilaiskukkulan, se on Jerusalemin, eteläpuolitse. Sitten raja nousee sen vuoren laelle, joka on vastapäätä Hinnomin laaksoa, lännessä päin, Refaimin tasangon pohjoisessa laidassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Tämän vuoren laelta raja kaartuu Neftoahin veden lähteelle ja jatkuu Efronin vuoren kaupunkeihin, ja sitten raja kaartuu Baalaan, se on Kirjat-Jearimiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Baalasta raja kääntyy länteen päin Seirin vuoreen, kulkee Jearimin vuoren kukkulan, se on Kesalonin, pohjoispuolitse, laskeutuu Beet-Semekseen ja kulkee sitten Timnaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Edelleen raja jatkuu Ekronin kukkulaan, pohjoiseen päin; sitten raja kaartuu Sikkeroniin, kulkee Baala-vuoreen ja jatkuu Jabneeliin; sitten raja päättyy mereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Ja läntisenä rajana on Suuri meri; se on rajana. Nämä ovat Juudan jälkeläisten, heidän sukukuntiensa, rajat yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Mutta Kaalebille, Jefunnen pojalle, Joosua antoi, niinkuin Herra oli häntä käskenyt, osuuden Juudan jälkeläisten keskuudessa, Kirjat-Arban, anakilaisten isän Arban kaupungin, se on Hebronin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Ja Kaaleb karkoitti sieltä kolme anakilaista, Anakin jälkeläiset Seesain, Ahimanin ja Talmain,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'ja lähti sieltä Debirin asukkaita vastaan; mutta Debirin nimi oli muinoin Kirjat-Seefer.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Silloin Kaaleb sanoi: \"Joka voittaa ja valloittaa Kirjat-Seeferin, sille minä annan tyttäreni Aksan vaimoksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Niin Otniel, Kenaan, Kaalebin veljen, poika, valloitti sen; ja hän antoi tälle tyttärensä Aksan vaimoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Ja kun Aksa tuli, niin hän yllytti miestänsä, että tämä pyytäisi hänen isältänsä peltomaata; ja Aksa pudottautui aasin selästä maahan. Silloin Kaaleb sanoi hänelle: \"Mikä sinun on?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Niin hän vastasi: \"Anna minulle jäähyväislahja, sillä sinä olet naittanut minut kuivaan maahan; anna siis minulle vesilähteitä\". Silloin hän antoi hänelle Ylälähteet ja Alalähteet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Tämä on Juudan jälkeläisten sukukunnan, heidän sukujensa, perintöosa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Juudan jälkeläisten sukukunnan etäisimmät kaupungit Edomin rajalla Etelämaassa ovat: Kabseel, Eeder, Jaagur,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kiina, Diimona, Adada,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedes, Haasor, Jitnan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Siif, Telem, Bealot,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Haasor-Hadatta, Kerijot-Hesron, se on Haasor,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, Sema, Moolada,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Hasar-Gadda, Hesmon, Beet-Pelet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Hasar-Suual, Beerseba ja Bisjotja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, Ijjim, Esem,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltolad, Kesil, Horma,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Siklag, Madmanna, Sansanna,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaot, Silhim, Ain ja Rimmon-kaikkiaan kaksikymmentä yhdeksän kaupunkia kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'Alankomaassa: Estaol, Sora, Asna,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Saanoah, Een-Gannim, Tappuah, Eenam,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmut, Adullam, Sooko, Aseka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Saaraim, Aditaim, Gedera ja Gederotaim-neljätoista kaupunkia kylineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Senan, Hadasa, Migdal-Gaad,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilan, Mispe, Jokteel,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Laakis, Boskat, Eglon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Kabbon, Lahmas, Kitlis,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederot, Beet-Daagon, Naema ja Makkeda-kuusitoista kaupunkia kylineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Eter, Aasan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jiftah, Asna, Nesib,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Kegila, Aksib ja Maaresa-yhdeksän kaupunkia kylineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron ja sen tytärkaupungit ja kylät;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'koko se alue kylineen, joka on Asdodin puolella Ekronista mereen kulkevaa rajaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod ja sen tytärkaupungit ja kylät; Gassa ja sen tytärkaupungit ja kylät Egyptin puroon asti. Ja Suuri meri on rajana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Ja vuoristossa: Saamir, Jattir, Sooko,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Danna, Kirjat-Sanna, se on Debir;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab, Estemo, Aanim;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Goosen, Hoolon ja Giilo-yksitoista kaupunkia kylineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duuma, Esan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Jaanum, Beet-Tappuah, Afeka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Humta, Kirjat-Arba, se on Hebron, ja Siior-yhdeksän kaupunkia kylineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maaon, Karmel, Siif, Jutta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jisreel, Jokdeam ja Saanoah,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kain, Gibea, Timna-kymmenen kaupunkia kylineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Beet-Suur, Gedor,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarat, Beet-Anot ja Eltekon-kuusi kaupunkia kylineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjat-Baal, se on Kirjat-Jearim, ja Rabba-kaksi kaupunkia kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'Ja erämaassa: Beet-Araba, Middin, Sekaka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibsan, Iir-Melah ja Een-Gedi-kuusi kaupunkia kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Mutta jebusilaisia, jotka asuivat Jerusalemissa, eivät Juudan jälkeläiset kyenneet karkoittamaan, ja niin jebusilaiset jäivät asumaan Juudan jälkeläisten sekaan, Jerusalemiin, aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Joosefilaisille määräsi arpa rajan kulkemaan idästä päin, Jerikon Jordanista, Jerikon veteen ja sieltä erämaahan, joka kohoaa Jerikosta vuoristoon Beeteliä kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Beetelistä raja jatkuu Luusiin ja kulkee arkilaisten alueeseen, Atarotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Sitten se laskeutuu länteen päin jafletilaisten alueeseen, aina alisen Beet-Hooronin alueeseen ja Geseriin asti ja päättyy mereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Joosefilaiset, Manasse ja Efraim, saivat perintöosakseen tämän:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Efraimilaisille, heidän suvuilleen, tuli seuraava alue: heidän perintöosansa itäinen raja kulkee Aterot-Addarista yliseen Beet-Hooroniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Sitten raja päättyy mereen. Pohjoisessa on Mikmetat rajana. Sieltä raja kääntyy itään päin Taanat-Siiloon ja menee sen itäpuolitse Janohaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Janohasta se laskeutuu Atarotiin ja Naaraan, koskettaa Jerikoa ja päättyy Jordaniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Tappuahista raja kulkee länteen päin Kaana-puroon ja päättyy mereen. Tämä on efraimilaisten sukukunnan, heidän sukujensa, perintöosa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'ja lisäksi ne kaupungit, jotka erotettiin efraimilaisille keskeltä manasselaisten perintöosaa, kaikki ne kaupungit kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Mutta he eivät karkoittaneet kanaanilaisia, jotka asuivat Geserissä; niin kanaanilaiset jäivät asumaan Efraimin keskeen aina tähän päivään asti, mutta joutuivat työveron alaisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Manassen sukukunta sai sekin arpaosansa, sillä hän oli Joosefin esikoinen. Maakir, Manassen esikoinen, Gileadin isä, sai Gileadin ja Baasanin, sillä hän oli sotilas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Muutkin manasselaiset saivat osuutensa, suvuittain: abieserilaiset, heelekiläiset, asrielilaiset, sekemiläiset, heeferiläiset ja semidalaiset. Nämä ovat Manassen, Joosefin pojan, miespuoliset jälkeläiset, suvuittain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Mutta Selofhadilla, Heeferin pojalla, joka oli Gileadin poika, joka Maakirin poika, joka Manassen poika, ei ollut poikia, vaan ainoastaan tyttäriä; ja nämä olivat hänen tyttäriensä nimet: Mahla, Nooga, Hogla, Milka ja Tirsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Nämä astuivat pappi Eleasarin ja Joosuan, Nuunin pojan, ja päämiesten eteen ja sanoivat: \"Herra käski Mooseksen antaa meille perintöosan veljiemme keskuudessa\". Silloin Joosua antoi heille Herran käskyn mukaisesti perintöosan heidän isänsä veljien keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Niin tuli Manasselle, paitsi Gileadin maata ja Baasania tuolla puolella Jordanin, kymmenen osaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'koska Manassen tyttäret saivat perintöosan hänen poikiensa keskuudessa; mutta Gileadin maa joutui Manassen muille jälkeläisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Manassen raja kulkee Asserista Mikmetatiin, joka on Sikemin itäpuolella; sitten raja menee oikealle Een-Tappuahin asukkaiden tienoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Tappuahin maa joutui Manasselle, mutta Tappuah, Manassen rajalla, efraimilaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Sitten raja laskeutuu Kaana-puroon, puron eteläpuolelle; mutta siellä, Manassen kaupunkien keskellä, olevat kaupungit joutuivat Efraimille. Sitten Manassen raja kulkee puron pohjoispuolelle ja päättyy mereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Eteläpuolella oleva maa joutui Efraimille, mutta pohjoispuolella oleva maa joutui Manasselle, ja meri on sen rajana. Ja pohjoisessa sen raja koskettaa Asseria ja idässä Isaskaria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Isaskarista ja Asserista joutui Manasselle Beet-Sean ja sen tytärkaupungit, Jibleam ja sen tytärkaupungit, Doorin asukkaat ja sen tytärkaupungit, Een-Doorin asukkaat ja sen tytärkaupungit, Taanakin asukkaat ja sen tytärkaupungit, Megiddon asukkaat ja sen tytärkaupungit, kolme kukkulaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Mutta manasselaiset eivät kyenneet ottamaan haltuunsa näitä kaupunkeja, vaan kanaanilaisten onnistui jäädä asumaan siihen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Kun israelilaiset sitten voimistuivat, saattoivat he kanaanilaiset työveron alaisiksi, mutta eivät karkoittaneet heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Joosefilaiset puhuivat Joosualle sanoen: \"Miksi sinä olet antanut minulle perintöosaksi vain yhden arvan ja yhden osan, vaikka minä olen lukuisa kansa, kun Herra aina tähän asti on minua siunannut?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Silloin Joosua sanoi heille: \"Jos sinä olet niin lukuisa kansa, niin mene metsäseutuun ja raivaa itsellesi maata sieltä, perissiläisten ja refalaisten maasta, kun kerran Efraimin vuoristo on sinulle liian ahdas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Mutta joosefilaiset vastasivat: \"Ei vuoristo riitä meille; ja kaikilla kanaanilaisilla, jotka asuvat tasangoilla, on raudoitettuja sotavaunuja, sekä niillä, jotka asuvat Beet-Seanissa ja sen tytärkaupungeissa, että niillä, jotka asuvat Jisreelin tasangolla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Silloin Joosua sanoi Joosefin heimolle, Efraimille ja Manasselle, näin: \"Sinä olet lukuisa kansa ja sinun voimasi on suuri; sinua ei ole jätettävä yhdelle ainoalle arpaosalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'vaan vuoristo on tuleva sinun omaksesi. Koska se on metsäseutua, on sinun raivattava se, ja sen laitapuoletkin tulevat sinun omiksesi. Sillä sinun on karkoitettava kanaanilaiset, vaikka heillä on raudoitettuja sotavaunuja ja vaikka he ovat voimakkaat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Ja kaikki israelilaisten seurakunta kokoontui Siiloon, ja he pystyttivät sinne ilmestysmajan, sittenkuin maa oli tullut heille alamaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Mutta vielä oli israelilaisista jäljellä seitsemän sukukuntaa, joiden perintöosa oli jakamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Niin Joosua sanoi israelilaisille: \"Kuinka kauan hidastelette ettekä mene ottamaan omaksenne maata, jonka Herra, teidän isienne Jumala, on teille antanut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Tuokaa tänne jokaisesta sukukunnasta kolme miestä, niin minä lähetän heidät menemään ja kiertelemään maata ja panemaan sen kirjaan heidän perintöosiaan silmällä pitäen; ja tulkoot he sitten takaisin minun luokseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'He jakakoot maan seitsemään osaan. Juuda pysyköön alueellaan etelässä, ja Joosefin heimo pysyköön alueellaan pohjoisessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Pankaa maa, ne seitsemän osaa, kirjaan ja tuokaa kirja tänne minulle, niin minä heitän teidän puolestanne arpaa täällä Herran, meidän Jumalamme, edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Sillä leeviläisillä ei ole osuutta teidän keskuudessanne, vaan Herran pappeus on heidän perintöosansa; ja Gaad ja Ruuben ja toinen puoli Manassen sukukuntaa saivat tuolta puolelta Jordanin, idän puolelta, perintöosansa, jonka Herran palvelija Mooses heille antoi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Niin miehet nousivat ja lähtivät; ja Joosua käski lähtevien panna kirjaan maan, sanoen: \"Menkää ja kierrelkää maa ja pankaa se kirjaan ja palatkaa sitten minun luokseni, niin minä heitän teidän puolestanne arpaa täällä Herran edessä Siilossa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Ja miehet lähtivät, kulkivat kautta maan ja panivat sen kirjaan kaupunki kaupungilta, seitsemänä osana, ja tulivat takaisin Joosuan luo Siilon leiriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Ja Joosua heitti heidän puolestaan arpaa Siilossa Herran edessä, ja Joosua jakoi siellä maan israelilaisille, heidän osastojensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Ja arpa nousi benjaminilaisten sukukunnalle, heidän suvuilleen; ja heidän arvalla saamansa alue oli Juudan jälkeläisten ja joosefilaisten välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Heidän pohjoinen rajansa lähtee Jordanista, ja raja nousee Jerikon pohjoispuolella olevalle kukkulalle ja nousee vuoristoon, länteen päin, ja päättyy Beet-Aavenin erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Sieltä raja kulkee Luusiin, Luusin eteläpuolella olevaan kukkulaan, se on Beeteliin; sitten raja laskeutuu Aterot-Addariin vuoren yli, joka on alisen Beet-Hooronin eteläpuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Sitten raja kaartuu ja kääntyy läntisenä rajana etelään päin siitä vuoresta, joka on vastapäätä Beet-Hooronia, sen eteläpuolella, ja päättyy Kirjat-Baaliin, se on Kirjat-Jearimiin, Juudan jälkeläisten kaupunkiin. Tämä on läntinen raja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Mutta eteläinen raja lähtee Kirjat-Jearimin laidasta, lännen puolelta, ja jatkuu Neftoahin veden lähteelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Sitten raja laskeutuu sen vuoren päähän, joka on vastapäätä Ben-Hinnomin laaksoa, Refaimin tasangon pohjoisessa laidassa; sieltä se laskeutuu Hinnomin laaksoon Jebusilaiskukkulan eteläpuolitse ja edelleen Roogelin lähteelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Sitten se kaartuu pohjoiseen päin ja jatkuu Een-Semekseen ja edelleen kivitarhoille, jotka ovat vastapäätä Adummimin solaa, ja laskeutuu Boohanin, Ruubenin pojan, kiveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Edelleen se kulkee Aromaahan päin olevan kukkulan pohjoispuolitse ja laskeutuu Aromaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Sitten raja kulkee Beet-Hoglan kukkulan pohjoispuolitse, ja raja päättyy Suolameren pohjoiseen pohjukkaan, Jordanin eteläpäähän. Tämä on eteläinen raja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Mutta idän puolella on Jordan rajana. Tämä on benjaminilaisten, heidän sukujensa, perintöosa rajoineen yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Ja benjaminilaisten sukukunnan, heidän sukujensa, kaupungit ovat: Jeriko, Beet-Hogla, Eemek-Kesis,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Beet-Araba, Semaraim, Beetel,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avvim, Paara, Ofra,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Kefar-Ammoni, Ofni ja Geba-kaksitoista kaupunkia kylineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon, Raama, Beerot,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Mispe, Kefira, Moosa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Jirpeel, Tarala,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Seela, Elef, Jebus, se on Jerusalem, Gibeat ja Kirjat-neljätoista kaupunkia kylineen. Tämä on benjaminilaisten, heidän sukujensa, perintöosa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Toinen arpa tuli Simeonille, simeonilaisten sukukunnalle, heidän suvuillensa; ja heidän perintöosansa tuli olemaan keskellä Juudan jälkeläisten perintöosaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Heidän perintöosakseen tuli: Beerseba, Seba, Moolada,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Hasar-Suual, Baala, Esem,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolad, Betul, Horma,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Siklag, Beet-Markabot, Hasar-Suusa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Beet-Lebaot ja Saaruhen-kolmetoista kaupunkia kylineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Rimmon, Eeter ja Aasan-neljä kaupunkia kylineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'sitten kaikki ne kylät, jotka ovat näiden kaupunkien ympärillä, aina Baalat-Beeriin, Etelämaan Raamaan, saakka. Tämä on simeonilaisten sukukunnan, heidän sukujensa, perintöosa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Juudan jälkeläisten osasta saivat simeonilaiset perintöosansa, sillä Juudan jälkeläisille oli heidän osuutensa liian suuri; niin simeonilaiset saivat perintöosansa heidän perintöosansa keskeltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Kolmas arpa nousi sebulonilaisille, heidän suvuillensa, ja heidän perintöosansa alue tuli ulottumaan Saaridiin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Länteen päin nousee heidän rajansa Maralaan, koskettaa Dabbesetia ja sitä puroa, joka on Jokneamin itäpuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Itään päin, auringonnousuun päin, kääntyy raja Saaridista Kislot-Taaborin alueelle ja jatkuu Daberatiin ja nousee Jaafiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Sieltä se kulkee itään päin, auringonnousuun päin, Gat-Heeferiin ja Eet-Kasiniin ja jatkuu Rimmoniin, joka ulottuu Neegaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Sitten raja kääntyy sen pohjoispuolitse Hannatoniin ja päättyy Jiftah-Eelin laaksoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Kattat, Nahalal, Simron, Jidala ja Beetlehem-kaksitoista kaupunkia kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Tämä on sebulonilaisten, heidän sukujensa, perintöosa, nämä kaupungit kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Neljäs arpa tuli Isaskarille, isaskarilaisille, heidän suvuilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Ja heidän alueellaan tuli olemaan Jisreel, Kesullot, Suunem,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hafaraim, Siion, Anaharat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabbit, Kisjon, Ebes,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remet, Een-Gannim, Een-Hadda ja Beet-Passes;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'ja raja koskettaa Taaboria, Sahasimia, Beet-Semestä, ja heidän rajansa päättyy Jordaniin-kuusitoista kaupunkia kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Tämä on isaskarilaisten sukukunnan, heidän sukujensa, perintöosa, kaupungit kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Viides arpa tuli asserilaisten sukukunnalle, heidän suvuillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Ja heidän alueellaan tuli olemaan Helkat, Hali, Beten ja Aksaf,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alammelek, Amad ja Misal; ja lännessä raja koskettaa Karmelia ja Siihor-Libnatia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'kääntyy sitten auringonnousuun päin Beet-Daagoniin ja koskettaa Sebulonia ja Jiftah-Eelin laaksoa pohjoisessa, Beet-Eemekiä ja Negieliä ja jatkuu Kaabulin pohjoispuolitse');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Ebroniin, Rehobiin, Hammoniin ja Kaanaan, aina suureen Siidoniin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Sitten raja kääntyy Raamaan ja menee Tyyron varustettuun kaupunkiin saakka; sitten raja kääntyy Hoosaan ja päättyy mereen, Heebelistä Aksibiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Umma, Afek ja Rehob-kaksikymmentä kaksi kaupunkia kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Tämä on asserilaisten sukukunnan, heidän sukujensa, perintöosa, nämä kaupungit kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Kuudes arpa tuli naftalilaisille, naftalilaisten suvuille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Ja heidän rajansa tuli kulkemaan Heelefistä, Saanannimin tammesta, Adami-Nekebin ja Jabneelin kautta Lakkumiin asti ja päättyy Jordaniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Ja raja kääntyy länteen päin Asnot-Taaboriin ja jatkuu sieltä Hukkokiin ja koskettaa etelässä Sebulonia, lännessä Asseria ja idässä Juudaa Jordanin luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Varustettuja kaupunkeja ovat: Siddim, Seer, Hammat, Rakkat, Kinneret,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Raama, Haasor,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedes, Edrei, Een-Haasor,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Jireon, Migdal-Eel, Horem, Beet-Anat ja Beet-Semes-yhdeksäntoista kaupunkia kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Tämä on naftalilaisten sukukunnan, heidän sukujensa, perintöosa, kaupungit kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Seitsemäs arpa tuli daanilaisten sukukunnalle, heidän suvuilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Heidän perintöosansa alueella tuli olemaan Sora, Estaol, Iir-Semes,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Saalabbin, Aijalon, Jitla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Eelon, Timna, Ekron,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elteke, Gibbeton, Baalat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Bene-Berak, Gat-Rimmon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Mee-Jarkon ja Rakkon, ynnä Jaafoon päin oleva alue.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Mutta daanilaisten alue joutui heiltä pois. Niin daanilaiset lähtivät ja taistelivat Lesemiä vastaan ja valloittivat sen ja surmasivat miekan terällä sen asukkaat ja ottivat sen omaksensa ja asettuivat sinne. Ja he antoivat Lesemille nimen Daan, isänsä Daanin mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Tämä on daanilaisten sukukunnan, heidän sukujensa, perintöosa, nämä kaupungit kylineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Kun israelilaiset olivat saaneet jaetuksi maan sen rajoja myöten, antoivat he Joosualle, Nuunin pojalle, perintöosan keskuudessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Herran käskyn mukaisesti he antoivat hänelle sen kaupungin, jota hän pyysi, Timnat-Serahin Efraimin vuoristossa. Ja hän rakensi uudestaan kaupungin ja asettui sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Nämä ovat ne perintöosat, jotka pappi Eleasar ja Joosua, Nuunin poika, ja israelilaisten sukukuntien perhekunta-päämiehet jakoivat arvalla Siilossa Herran edessä, ilmestysmajan ovella. Niin he lopettivat maan jakamisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Silloin Herra puhui Joosualle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, '\"Puhu israelilaisille ja sano: Määrätkää itsellenne ne turvakaupungit, joista minä olen puhunut teille Mooseksen kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'että niihin voisi paeta tappaja, joka tapaturmaisesti, tahtomattaan, on jonkun surmannut; ja olkoot ne teillä turvapaikkoina verenkostajalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Ja kun joku pakenee johonkin näistä kaupungeista, pysähtyköön hän kaupungin portin ovelle ja kertokoon asiansa sen kaupungin vanhimmille; he korjatkoot hänet luoksensa kaupunkiin ja antakoot hänelle paikan, jossa hän saa asua heidän luonansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Ja jos verenkostaja ajaa häntä takaa, älkööt he luovuttako tappajaa hänen käsiinsä, koska hän tahtomattaan tappoi lähimmäisensä, häntä ennestään vihaamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Ja asukoon hän siinä kaupungissa, kunnes on ollut kansan tuomittavana, ja silloisen ylimmäisen papin kuolemaan saakka; sitten tappaja tulkoon taas takaisin omaan kaupunkiinsa ja kotiinsa, kaupunkiin, josta oli paennut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Niin he pyhittivät sitä varten Kedeksen Galileasta, Naftalin vuoristosta, Sikemin Efraimin vuoristosta ja Kirjat-Arban, se on Hebronin, Juudan vuoristosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Ja tuolta puolelta Jerikon Jordanin, idän puolelta, he määräsivät Ruubenin sukukunnasta Beserin erämaasta, ylätasangolta, ja Gaadin sukukunnasta Raamotin, Gileadista, ja Manassen sukukunnasta Goolanin, Baasanista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Nämä ovat ne kaupungit, jotka asetettiin kaikille israelilaisille ja heidän keskuudessaan asuville muukalaisille sitä varten, että niihin voisi paeta jokainen, joka tapaturmaisesti oli jonkun surmannut, eikä hänen tarvitsisi kuolla verenkostajan käden kautta, ennenkuin oli ollut kansan tuomittavana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Leeviläisten perhekunta-päämiehet astuivat pappi Eleasarin ja Joosuan, Nuunin pojan, eteen ja israelilaisten sukukuntien perhekunta-päämiesten eteen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'ja puhuivat heille Siilossa Kanaanin maassa, sanoen: \"Herra käski Mooseksen kautta antaa meille kaupunkeja asuaksemme ja niiden laidunmaat karjaamme varten\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Niin israelilaiset antoivat leeviläisille perintöosastaan Herran käskyn mukaan nämä kaupungit laidunmaineen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Arpa tuli kehatilaisten suvuille niin, että leeviläisistä pappi Aaronin jälkeläiset saivat arvalla Juudan sukukunnalta, Simeonin sukukunnalta ja Benjaminin sukukunnalta kolmetoista kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Mutta muut kehatilaiset saivat arvalla Efraimin sukukunnan suvuilta, Daanin sukukunnalta ja toiselta puolelta Manassen sukukuntaa kymmenen kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Geersonilaiset saivat arvalla Isaskarin sukukunnan suvuilta, Asserin sukukunnalta ja Naftalin sukukunnalta, sekä toiselta puolelta Manassen sukukuntaa Baasanista, kolmetoista kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Merarilaiset, heidän sukunsa, saivat Ruubenin sukukunnalta, Gaadin sukukunnalta ja Sebulonin sukukunnalta kaksitoista kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Israelilaiset antoivat arvalla leeviläisille nämä kaupungit laidunmaineen, niinkuin Herra oli Mooseksen kautta käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Juudan jälkeläisten sukukunnasta ja simeonilaisten sukukunnasta annettiin nämä nimeltä mainitut kaupungit:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Leevin jälkeläisiin, kehatilaisten sukuihin, kuuluville Aaronin jälkeläisille, sillä heille tuli arpa ensin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'annettiin Kirjat-Arba, anakilaisten kantaisän Arban kaupunki, se on Hebron, Juudan vuoristosta, ympärillä olevine laidunmaineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Mutta kaupungin peltomaat kylineen annettiin Kaalebille, Jefunnen pojalle, perintömaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Pappi Aaronin jälkeläisille annettiin tappajan turvakaupunki Hebron laidunmaineen, Libna laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Jattir laidunmaineen, Estemoa laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Hoolon laidunmaineen, Debir laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Ain laidunmaineen, Jutta laidunmaineen ja Beet-Semes laidunmaineen-yhdeksän kaupunkia näistä kahdesta sukukunnasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'ja Benjaminin sukukunnasta Gibeon laidunmaineen, Geba laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anatot laidunmaineen ja Almon laidunmaineen-neljä kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Aaronin jälkeläisten, pappien, kaupunkeja oli kaikkiaan kolmetoista kaupunkia laidunmaineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Muut leeviläisiin kuuluvat kehatilaisten suvut, muut kehatilaiset, saivat arvalla Efraimin sukukunnalta seuraavat kaupungit:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'heille annettiin tappajan turvakaupunki Sikem laidunmaineen Efraimin vuoristosta, Geser laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Kibsaim laidunmaineen, Beet-Hooron laidunmaineen-neljä kaupunkia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'ja Daanin sukukunnasta Elteke laidunmaineen, Gibbeton laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Aijalon laidunmaineen ja Gat-Rimmon laidunmaineen-neljä kaupunkia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'ja toisesta puolesta Manassen sukukuntaa Taanak laidunmaineen ja Gat-Rimmon laidunmaineen-kaksi kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Näiden muiden kehatilaisten sukujen kaupunkeja laidunmaineen oli kaikkiaan kymmenen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Leeviläisten sukuihin kuuluvat geersonilaiset saivat toiselta puolelta Manassen sukukuntaa tappajan turvakaupungin Goolanin laidunmaineen Baasanista ja Beesteran laidunmaineen-kaksi kaupunkia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'ja Isaskarin sukukunnalta Kisjonin laidunmaineen, Daberatin laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmutin laidunmaineen ja Een-Gannimin laidunmaineen-neljä kaupunkia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'ja Asserin sukukunnalta Misalin laidunmaineen, Abdonin laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkatin laidunmaineen ja Rehobin laidunmaineen-neljä kaupunkia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'ja Naftalin sukukunnalta tappajan turvakaupungin Kedeksen laidunmaineen Galileasta, Hammot-Doorin laidunmaineen ja Kartanin laidunmaineen-kolme kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Geersonilaisten, heidän sukujensa, kaupunkeja oli kaikkiaan kolmetoista kaupunkia laidunmaineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Muut leeviläisiin kuuluvat merarilaisten suvut saivat Sebulonin sukukunnalta Jokneamin laidunmaineen, Kartan laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimnan laidunmaineen, Nahalalin laidunmaineen-neljä kaupunkia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'ja Ruubenin sukukunnalta Beserin laidunmaineen, Jahaan laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemotin laidunmaineen ja Meefaatin laidunmaineen-neljä kaupunkia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'ja Gaadin sukukunnalta tappajan turvakaupungin Raamotin laidunmaineen Gileadista ja Mahanaimin laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesbonin laidunmaineen ja Jaeserin laidunmaineen-yhteensä neljä kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Niitä kaupunkeja, jotka nämä muut leeviläisten sukuihin kuuluvat merarilaiset, heidän sukunsa, saivat arvalla, oli kaikkiaan kaksitoista kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Kaikkiaan oli leeviläisten kaupunkeja israelilaisten perintömaassa neljäkymmentä kahdeksan kaupunkia laidunmaineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Näihin kaupunkeihin kuului kuhunkin itse kaupunki ja sen ympärillä olevat laidunmaat; sellaisia olivat kaikki nämä kaupungit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Niin Herra antoi Israelille koko sen maan, jonka hän oli vannonut antavansa heidän isilleen; ja he ottivat sen omaksensa ja asettuivat siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Ja Herra soi heidän päästä rauhaan kaikkialla, aivan niinkuin hän valalla vannoen oli luvannut heidän isillensä; eikä yksikään heidän vihollisistaan kestänyt heidän edessään, vaan kaikki heidän vihollisensa Herra antoi heidän käsiinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Ei jäänyt täyttämättä ainoakaan kaikista niistä lupauksista, jotka Herra oli antanut Israelin heimolle, vaan kaikki toteutui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Sitten Joosua kutsui ruubenilaiset, gaadilaiset ja toisen puolen Manassen sukukuntaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'ja sanoi heille: \"Te olette noudattaneet kaikkea, mitä Herran palvelija Mooses on käskenyt teidän noudattaa, ja olette kuulleet minua kaikessa, mitä minä olen käskenyt teidän tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Te ette ole hyljänneet veljiänne koko tämän pitkän ajan kuluessa aina tähän päivään asti, ja te olette noudattaneet, mitä Herra, teidän Jumalanne, on käskenyt noudattaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Ja nyt on Herra, teidän Jumalanne, suonut teidän veljienne päästä rauhaan, niinkuin hän heille puhui; kääntykää siis takaisin ja menkää majoillenne, siihen perintömaahanne, jonka Herran palvelija Mooses antoi teille tuolta puolelta Jordanin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Noudattakaa vain tarkoin niitä käskyjä ja sitä lakia, jotka Herran palvelija Mooses on teille antanut, rakastakaa Herraa, teidän Jumalaanne, vaeltakaa aina hänen teitänsä, noudattakaa hänen käskyjänsä, riippukaa hänessä kiinni ja palvelkaa häntä kaikesta sydämestänne ja kaikesta sielustanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Niin Joosua siunasi heidät ja päästi heidät menemään, ja he menivät majoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Toiselle puolelle Manassen sukukuntaa Mooses oli antanut maata Baasanista, ja toiselle puolelle Joosua oli antanut maata länsipuolelta Jordanin, heille samoin kuin heidän veljilleen. Ja kun Joosua päästi heidät menemään majoillensa ja siunasi heidät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'sanoi hän heille näin: \"Kun te palaatte majoillenne, mukananne suuret rikkaudet ja suuri karjan paljous, suuri hopean, kullan, vasken, raudan ja vaatteiden paljous, jakakaa veljienne kanssa vihollisiltanne saatu saalis.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Niin ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa palasivat takaisin ja lähtivät pois israelilaisten luota Siilosta, joka on Kanaanin maassa, mennäkseen Gileadin maahan, perintömaahansa, johon he olivat asettuneet sen käskyn mukaan, jonka Herra oli Mooseksen kautta antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Kun ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa tulivat Jordanin kivitarhoille, jotka ovat Kanaanin maan puolella, rakensivat he sinne Jordanin partaalle alttarin, valtavan alttarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Niin israelilaiset kuulivat sanottavan: \"Katso, ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa ovat rakentaneet alttarin, päin Kanaanin maata, Jordanin kivitarhojen luo, israelilaisten puolelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Kun israelilaiset sen kuulivat, kokoontui kaikki israelilaisten seurakunta Siiloon, lähteäkseen sotaan heitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Ja israelilaiset lähettivät ruubenilaisten ja gaadilaisten luo ja Manassen sukukunnan toisen puolen luo Gileadin maahan pappi Piinehaan, Eleasarin pojan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'ja hänen kanssaan kymmenen ruhtinasta, yhden ruhtinaan kustakin perhekunnasta, kaikista Israelin sukukunnista; kukin heistä oli perhekunta-päämies Israelin heimojen joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Ja he tulivat ruubenilaisten ja gaadilaisten luo ja Manassen sukukunnan toisen puolen luo Gileadin maahan, puhuivat heille ja sanoivat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, '\"Näin sanoo koko Herran seurakunta: Kuinka te menettelette näin uskottomasti Israelin Jumalaa kohtaan, että nyt käännytte pois Herrasta rakentamalla itsellenne alttarin ja niin nyt kapinoitte Herraa vastaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Eikö meille jo riitä Peorin vuoksi tehty rikos, josta emme ole päässeet puhdistumaan vielä tänäkään päivänä ja josta rangaistus kohtasi Herran seurakuntaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Ja kuitenkin te nytkin käännytte pois Herrasta! Kun te tänä päivänä kapinoitte Herraa vastaan, niin hän huomenna vihastuu koko Israelin seurakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Mutta jos teidän perintömaanne on saastainen, niin tulkaa Herran perintömaahan, jossa on Herran asumus, ja asettukaa meidän keskellemme. Älkää kapinoiko Herraa vastaan älkääkä kapinoiko meitä vastaan rakentamalla itsellenne alttaria, toista kuin Herran, meidän Jumalamme, alttari.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Eikö silloin, kun Aakan, Serahin poika, oli ollut uskoton ja anastanut itselleen sitä, mikä oli vihitty tuhon omaksi, viha kohdannut koko Israelin seurakuntaa, vaikka hän olikin vain yksi mies? Eikö hänen täytynyt hukkua rikoksensa tähden?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Silloin ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa vastasivat ja puhuivat Israelin heimojen päämiehille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, '\"Jumala, Herra Jumala, Jumala, Herra Jumala, hän tietää sen, ja Israel myöskin tietäköön sen: jos me olemme kapinamielessä tai uskottomuudesta Herraa kohtaan-älä meitä silloin tänä päivänä auta-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'rakentaneet alttarin kääntyäksemme pois Herrasta, uhrataksemme sen päällä polttouhria ja ruokauhria tai toimittaaksemme sen päällä yhteysuhreja, niin kostakoon Herra itse sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Totisesti, me olemme tehneet sen vain yhdestä huolestuneina, siitä, että teidän lapsenne vastaisuudessa voivat sanoa meidän lapsillemme näin: \'Mitä teillä on tekemistä Herran, Israelin Jumalan, kanssa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Onhan Herra pannut Jordanin välirajaksi meille ja teille, te ruubenilaiset ja gaadilaiset; teillä ei ole mitään osuutta Herraan.\' Ja niin teidän lapsenne voivat saada aikaan, että meidän lapsemme lakkaavat pelkäämästä Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Sentähden me sanoimme: Tehkäämme itsellemme alttari, rakentakaamme se, ei polttouhria eikä teurasuhria varten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'vaan olemaan meidän ja teidän sekä myös meidän jälkeläistemme välillä meidän jälkeemme todistajana siitä, että me tahdomme toimittaa Herran palvelusta hänen edessänsä, polttouhreja, teurasuhreja ja yhteysuhreja, etteivät teidän lapsenne vastaisuudessa sanoisi meidän lapsillemme: \'Teillä ei ole mitään osuutta Herraan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Ja me ajattelimme: Jos he vastaisuudessa sanovat näin meille ja meidän jälkeläisillemme, niin me voimme vastata: \'Katsokaa Herran alttarin kuvaa, jonka meidän esi-isämme ovat tehneet, ei polttouhria eikä teurasuhria varten, vaan olemaan todistajana meidän välillämme ja teidän\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Pois se, että me kapinoisimme Herraa vastaan ja kääntyisimme tänä päivänä pois Herrasta rakentamalla alttarin polttouhria, ruokauhria ja teurasuhria varten, toisen kuin Herran, meidän Jumalamme, alttari, joka on hänen asumuksensa edessä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Kun pappi Piinehas ja kansan ruhtinaat, Israelin heimojen päämiehet, jotka olivat hänen kanssaan, kuulivat, mitä ruubenilaiset, gaadilaiset ja manasselaiset puhuivat, oli se heille mieleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Ja pappi Piinehas, Eleasarin poika, sanoi ruubenilaisille, gaadilaisille ja manasselaisille: \"Nyt me tiedämme, että Herra on meidän keskellämme, koska ette olekaan menetelleet uskottomasti Herraa kohtaan; näin te pelastitte israelilaiset joutumasta Herran käsiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Sen jälkeen pappi Piinehas, Eleasarin poika, ja ruhtinaat palasivat Gileadin maasta, ruubenilaisten ja gaadilaisten luota, takaisin Kanaanin maahan israelilaisten luo ja antoivat heille nämä tiedot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Ja ne olivat israelilaisille mieleen, ja israelilaiset ylistivät Jumalaa; eivätkä he enää ajatelleet lähteä sotaan heitä vastaan, hävittämään sitä maata, jossa ruubenilaiset ja gaadilaiset asuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Ja ruubenilaiset ja gaadilaiset antoivat alttarille nimen, sanoen: \"Se on todistaja meidän välillämme siitä, että Herra on Jumala\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Pitkän ajan kuluttua, sitten kuin Herra oli suonut Israelin päästä rauhaan kaikilta sen ympärillä asuvilta vihollisilta, ja kun Joosua oli käynyt vanhaksi ja iäkkääksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'kutsui Joosua kaiken Israelin, sen vanhimmat, päämiehet, tuomarit ja päällysmiehet ja sanoi heille: \"Minä olen käynyt vanhaksi ja iäkkääksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Ja te olette itse nähneet kaiken, mitä Herra, teidän Jumalanne, on tehnyt kaikille näille kansoille, jotka hän on karkoittanut teidän tieltänne; sillä Herra, teidän Jumalanne, on itse sotinut teidän puolestanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Katsokaa, minä olen arponut teille, teidän sukukunnillenne, perintöosaksi nämä kansat, jotka vielä ovat jäljellä, ja kaikki kansat, jotka minä hävitin Jordanista Suureen mereen asti, auringonlaskuun päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Ja Herra, teidän Jumalanne, työntää itse ne pois teidän edestänne ja karkoittaa ne teidän tieltänne, niin että te otatte omaksenne heidän maansa, niinkuin Herra, teidän Jumalanne, on teille puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Olkaa siis aivan lujat ja noudattakaa tarkoin kaikkea, mitä Mooseksen lain kirjaan on kirjoitettu, poikkeamatta siitä oikealle tai vasemmalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'niin ettette yhdy näihin teidän keskuuteenne jääneisiin kansoihin, ette mainitse heidän jumaliensa nimiä ettekä vanno niiden nimeen, ette palvele niitä ettekä kumarra niitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'vaan että riiputte kiinni Herrassa, Jumalassanne, niinkuin olette tehneet aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Sentähden Herra on karkoittanut teidän tieltänne suuret ja mahtavat kansat, eikä ainoakaan ole kestänyt teidän edessänne aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Yksi ainoa mies teistä ajoi pakoon tuhat, sillä Herra, teidän Jumalanne, soti itse teidän puolestanne, niinkuin hän on teille puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Ottakaa siis henkenne tähden tarkka vaari siitä, että rakastatte Herraa, teidän Jumalaanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Sillä jos te käännytte hänestä pois ja liitytte näiden teidän keskuuteenne jääneiden kansojen tähteisiin ja lankoudutte heidän kanssansa ja yhdytte heihin ja he teihin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'niin tietäkää, ettei Herra, teidän Jumalanne, enää karkoita näitä kansoja teidän tieltänne, vaan ne tulevat teille paulaksi ja ansaksi, kylkienne ruoskaksi ja okaiksi silmiinne, kunnes te häviätte tästä hyvästä maasta, jonka Herra, teidän Jumalanne, on teille antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Katso, minä menen nyt kaiken maailman tietä. Koko sydämenne ja koko sielunne tietäköön, ettei ainoakaan kaikista niistä teitä koskevista lupauksista, jotka Herra, teidän Jumalanne, on antanut, ole jäänyt täyttämättä; kaikki ovat toteutuneet teille, ei ainoakaan niistä ole jäänyt täyttämättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Ja niinkuin kaikki teitä koskevat lupaukset, jotka Herra, teidän Jumalanne, on antanut, ovat toteutuneet teille, niin Herra myöskin antaa kaikkien uhkauksiensa toteutua teille, kunnes hän on hävittänyt teidät tästä hyvästä maasta, jonka Herra, teidän Jumalanne, on teille antanut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'jos te rikotte Herran, teidän Jumalanne, liiton, jonka hän on teille säätänyt, ja menette ja palvelette muita jumalia ja niitä kumarratte, niin Herran viha syttyy teitä kohtaan, ja te häviätte pian siitä hyvästä maasta, jonka hän on teille antanut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Sitten Joosua kokosi kaikki Israelin sukukunnat Sikemiin ja kutsui Israelin vanhimmat, sen päämiehet, tuomarit ja päällysmiehet, ja he asettuivat Jumalan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Ja Joosua sanoi koko kansalle: \"Näin sanoo Herra, Israelin Jumala: Tuolla puolella Eufrat-virran asuivat muinoin teidän isänne, myös Terah, Aabrahamin ja Naahorin isä, ja he palvelivat muita jumalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Mutta minä otin teidän isänne Aabrahamin tuolta puolelta virran ja kuljetin häntä kautta koko Kanaanin maan ja tein hänen jälkeläisensä lukuisiksi ja annoin hänelle Iisakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Ja Iisakille minä annoin Jaakobin ja Eesaun. Ja Eesaulle minä annoin Seirin vuoriston omaksi, mutta Jaakob ja hänen poikansa menivät Egyptiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Sitten minä lähetin Mooseksen ja Aaronin ja rankaisin Egyptiä sillä, mitä minä siellä tein, ja sen jälkeen minä vein teidät sieltä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Ja kun minä vein teidän isänne pois Egyptistä ja te olitte saapuneet meren rannalle, ajoivat egyptiläiset teidän isiänne takaa sotavaunuilla ja ratsumiehillä Kaislamereen saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Niin he huusivat Herraa, ja hän pani pimeyden teidän ja egyptiläisten välille ja antoi meren tulla heidän ylitsensä, ja se peitti heidät; omin silmin te näitte, mitä minä tein egyptiläisille. Kun te sitten olitte asuneet kauan aikaa erämaassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'toin minä teidät amorilaisten maahan, jotka asuivat tuolla puolella Jordanin, ja he taistelivat teitä vastaan; mutta minä annoin heidät teidän käsiinne, ja te otitte omaksenne heidän maansa, ja minä tuhosin heidät teidän tieltänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Silloin nousi Baalak, Sipporin poika, Mooabin kuningas ja taisteli Israelia vastaan; ja hän lähetti kutsumaan Bileamin, Beorin pojan, että hän kiroaisi teidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Mutta minä en tahtonut kuulla Bileamia, vaan hänen täytyi siunata teidät, ja minä pelastin teidät hänen käsistään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Ja kun te olitte menneet Jordanin yli ja tulleet Jerikoon, niin Jerikon miehet ja amorilaiset, perissiläiset, kanaanilaiset, heettiläiset, girgasilaiset, hivviläiset ja jebusilaiset taistelivat teitä vastaan, mutta minä annoin heidät teidän käsiinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Ja minä lähetin herhiläisiä teidän edellänne, ja ne karkoittivat heidät teidän tieltänne, ne kaksi amorilaisten kuningasta; sinä miekallasi ja jousellasi et sitä tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Ja minä annoin teille maan, josta sinä et ollut vaivaa nähnyt, ja kaupunkeja, joita te ette olleet rakentaneet, mutta joihin saitte asettua; viinitarhoista ja öljypuista, joita te ette olleet istuttaneet, te saitte syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Niin peljätkää nyt Herraa, palvelkaa häntä nuhteettomasti ja uskollisesti ja poistakaa ne jumalat, joita teidän isänne palvelivat tuolla puolella virran ja Egyptissä, ja palvelkaa Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Mutta jos pidätte pahana palvella Herraa, niin valitkaa tänä päivänä, ketä tahdotte palvella, niitäkö jumalia, joita teidän isänne palvelivat tuolla puolella virran, vai amorilaisten jumalia, niiden, joiden maassa te asutte. Mutta minä ja minun perheeni palvelemme Herraa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Silloin kansa vastasi ja sanoi: \"Pois se, että me hylkäisimme Herran ja palvelisimme muita jumalia!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Sillä Herra on meidän Jumalamme, hän, joka johdatti meidät ja meidän isämme pois Egyptin maasta, orjuuden pesästä, ja joka teki meidän silmiemme edessä suuret tunnusteot ja aina varjeli meitä sillä tiellä, jota me vaelsimme, ja kaikkien niiden kansojen keskellä, joiden kautta me kuljimme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Ja Herra karkoitti meidän tieltämme kaikki ne kansat, myös amorilaiset, jotka asuivat tässä maassa. Sentähden me palvelemme Herraa, sillä hän on meidän Jumalamme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Niin Joosua sanoi kansalle: \"Te ette voi palvella Herraa, sillä hän on pyhä Jumala; hän on kiivas Jumala, hän ei anna anteeksi teidän rikoksianne ja syntejänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Jos te hylkäätte Herran ja palvelette vieraita jumalia, niin hän kääntyy pois ja antaa teille käydä pahoin ja tekee lopun teistä, sen sijaan että hän on ennen antanut teille käydä hyvin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Mutta kansa sanoi Joosualle: \"Ei niin, vaan me palvelemme Herraa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Silloin Joosua sanoi kansalle: \"Te olette itse todistajina itseänne vastaan, että olette valinneet itsellenne Herran palvellaksenne häntä\". He vastasivat: \"Olemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Hän sanoi: \"Niin poistakaa nyt vieraat jumalat, joita on teidän keskuudessanne, ja taivuttakaa sydämenne Herran, Israelin Jumalan, puoleen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Kansa vastasi Joosualle: \"Herraa, meidän Jumalaamme, me palvelemme, ja hänen ääntänsä me kuulemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Niin Joosua teki sinä päivänä liiton kansan kanssa ja antoi heille Sikemissä käskyt ja oikeudet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Ja Joosua kirjoitti nämä puheet Jumalan lain kirjaan, ja hän otti suuren kiven ja pystytti sen sinne, tammen alle, joka oli Herran pyhäkössä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Ja Joosua sanoi kaikelle kansalle: \"Katso, tämä kivi on oleva todistajana meitä vastaan, sillä se on kuullut kaikki Herran sanat, jotka hän on meille puhunut, ja se on oleva todistajana teitä vastaan, ettette kieltäisi Jumalaanne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Sitten Joosua päästi kansan menemään, kunkin perintöosalleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Näiden tapausten jälkeen Herran palvelija Joosua, Nuunin poika, kuoli sadan kymmenen vuoden vanhana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Ja he hautasivat hänet hänen perintöosansa alueelle, Timnat-Serahiin, joka on Efraimin vuoristossa, pohjoispuolelle Gaas-vuorta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Ja Israel palveli Herraa Joosuan koko elinajan ja niiden vanhinten koko elinajan, jotka elivät vielä kauan Joosuan jälkeen ja tunsivat kaikki ne teot, jotka Herra oli Israelille tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Ja Joosefin luut, jotka israelilaiset olivat tuoneet Egyptistä, he hautasivat Sikemiin, siihen maapalstaan, jonka Jaakob oli ostanut Hamorin, Sikemin isän, pojilta sadalla kesitalla ja jonka joosefilaiset olivat saaneet perintöosaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Ja Eleasar, Aaronin poika, kuoli, ja he hautasivat hänet Gibeaan, hänen poikansa Piinehaan kaupunkiin, joka oli annettu hänelle Efraimin vuoristosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Joosuan kuoleman jälkeen israelilaiset kysyivät Herralta ja sanoivat: \"Kenen meistä on ensiksi lähdettävä kanaanilaisia vastaan, sotimaan heitä vastaan?\" Herra vastasi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, '\"Juuda lähteköön; katso, minä annan maan hänen käsiinsä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Niin Juuda sanoi veljellensä Simeonille: \"Lähde minun kanssani minun arpaosaani, ja sotikaamme kanaanilaisia vastaan, niin minäkin tulen sinun kanssasi sinun arpaosaasi\". Niin Simeon lähti hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Ja Juuda lähti, ja Herra antoi kanaanilaiset ja perissiläiset heidän käsiinsä; ja he voittivat heidät Besekissä-kymmenentuhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Ja he kohtasivat Adoni-Besekin Besekissä ja taistelivat häntä vastaan ja voittivat kanaanilaiset ja perissiläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Ja Adoni-Besek pakeni, mutta he ajoivat häntä takaa ja ottivat hänet kiinni ja hakkasivat häneltä peukalot ja isotvarpaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Silloin Adoni-Besek sanoi: \"Seitsemänkymmentä kuningasta, joilta oli hakattu peukalot ja isotvarpaat, kokosi muruja minun pöytäni alta; niinkuin minä olen tehnyt, niin on Jumala minulle maksanut\". Ja he veivät hänet Jerusalemiin, ja siellä hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Ja Juudan miehet ryhtyivät taisteluun Jerusalemia vastaan ja valloittivat sen ja surmasivat miekan terällä sen asukkaat ja pistivät kaupungin tuleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Sen jälkeen Juudan miehet laskeutuivat sotimaan niitä kanaanilaisia vastaan, jotka asuivat Vuoristossa, Etelämaassa ja Alankomaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Niin Juuda meni niitä kanaanilaisia vastaan, jotka asuivat Hebronissa-Hebronin nimi oli muinoin Kirjat-Arba-ja he voittivat Seesain, Ahimanin ja Talmain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Sieltä hän meni Debirin asukkaita vastaan-Debirin nimi oli muinoin Kirjat-Seefer-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'ja Kaaleb sanoi: \"Joka voittaa ja valloittaa Kirjat-Seeferin, sille minä annan tyttäreni Aksan vaimoksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Niin Otniel, Kenaan, Kaalebin nuoremman veljen, poika, valloitti sen; ja hän antoi tälle tyttärensä Aksan vaimoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Ja kun Aksa tuli, niin hän yllytti miestänsä, että tämä pyytäisi hänen isältänsä peltomaata; ja Aksa pudottautui aasin selästä maahan. Silloin Kaaleb sanoi hänelle: \"Mikä sinun on?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Niin hän vastasi hänelle: \"Anna minulle jäähyväislahja, sillä sinä olet naittanut minut kuivaan maahan, anna siis minulle vesilähteitä\". Silloin Kaaleb antoi hänelle Ylälähteet ja Alalähteet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Ja keeniläisen, Mooseksen apen, jälkeläiset olivat lähteneet Palmukaupungista Juudan jälkeläisten kanssa Juudan erämaahan, eteläpuolelle Aradia; he menivät ja asettuivat sikäläisen kansan sekaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Mutta Juuda meni veljensä Simeonin kanssa, ja he voittivat kanaanilaiset, jotka asuivat Sefatissa, ja he vihkivät kaupungin tuhon omaksi ja kutsuivat sen Hormaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Ja Juuda valloitti Gassan alueineen, Askelonin alueineen ja Ekronin alueineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Ja Herra oli Juudan kanssa, niin että hän sai haltuunsa vuoriston; sillä hän ei kyennyt karkoittamaan niitä, jotka asuivat tasangolla, koska heillä oli raudoitettuja sotavaunuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Ja he antoivat Kaalebille Hebronin, niinkuin Mooses oli puhunut; ja hän karkoitti sieltä ne kolme anakilaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Mutta benjaminilaiset eivät karkoittaneet jebusilaisia, jotka asuivat Jerusalemissa, ja niin jebusilaiset jäivät asumaan benjaminilaisten sekaan, Jerusalemiin, aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Myöskin Joosefin heimo lähti liikkeelle; se lähti Beeteliin, ja Herra oli heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Ja Joosefin heimo vakoilutti Beeteliä-kaupungin nimi oli muinoin Luus-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'ja vakoilijat näkivät miehen tulevan kaupungista ja sanoivat hänelle: \"Näytä meille, mistä päästään kaupunkiin, niin me teemme sinulle laupeuden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Niin hän näytti heille, mistä päästiin kaupunkiin, ja he surmasivat miekan terällä kaupungin asukkaat, mutta sen miehen ja koko hänen sukunsa he päästivät menemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Ja se mies meni heettiläisten maahan ja rakensi kaupungin ja antoi sille nimen Luus, ja se nimi sillä on vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Mutta Manasse ei saanut haltuunsa Beet-Seania ja sen tytärkaupunkeja, ei Taanakia ja sen tytärkaupunkeja, ei Doorin asukkaita ja sen tytärkaupunkeja, ei Jibleamin asukkaita ja sen tytärkaupunkeja eikä Megiddon asukkaita ja sen tytärkaupunkeja, vaan kanaanilaisten onnistui jäädä asumaan siihen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Kun Israel sitten voimistui, saattoi se kanaanilaiset työveron alaisiksi, mutta ei karkoittanut heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Efraim ei karkoittanut kanaanilaisia, jotka asuivat Geserissä, ja niin kanaanilaiset jäivät asumaan sen keskeen, Geseriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Sebulon ei karkoittanut Kidronin asukkaita eikä Nahalolin asukkaita, ja niin kanaanilaiset jäivät asumaan sen keskeen, mutta joutuivat työveron alaisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Asser ei karkoittanut Akkon asukkaita eikä Siidonin asukkaita eikä myöskään Ahlabin, Aksibin, Helban, Afekin ja Rehobin asukkaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Ja niin asserilaiset joutuivat asumaan maan asukkaiden, kanaanilaisten, keskeen, koska eivät karkoittaneet heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Naftali ei karkoittanut Beet-Semeksen asukkaita eikä Beet-Anatin asukkaita ja joutui niin asumaan maan asukkaiden, kanaanilaisten, keskeen; mutta Beet-Semeksen ja Beet-Anatin asukkaat joutuivat heille työveron alaisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Amorilaiset tunkivat daanilaiset vuoristoon, sillä he eivät sallineet heidän laskeutua tasangolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Ja amorilaisten onnistui jäädä asumaan Har-Herekseen, Aijaloniin ja Saalbimiin; mutta Joosefin heimon käsi kävi heille raskaaksi, ja he joutuivat työveron alaisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Ja amorilaisten alue ulottui Skorpionisolasta, Seelasta, ylöspäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Ja Herran enkeli tuli Gilgalista ylös Bookimiin. Ja hän sanoi: \"Minä johdatin teidät Egyptistä ja toin teidät maahan, jonka minä valalla vannoen olin luvannut teidän isillenne, ja sanoin: \'Minä en riko liittoani teidän kanssanne ikinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Te taas älkää tehkö liittoa tämän maan asukasten kanssa, vaan kukistakaa heidän alttarinsa.\' Mutta te ette ole kuulleet minun ääntäni. Mitä olettekaan tehneet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Niinpä minä nyt sanon teille: Minä en karkoita heitä teidän tieltänne, vaan heistä tulee teille ahdistajat, ja heidän jumalansa tulevat teille ansaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Ja kun Herran enkeli oli puhunut nämä sanat kaikille israelilaisille, korotti kansa äänensä ja itki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Ja he antoivat sille paikalle nimen Bookim; ja he uhrasivat siinä Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Kun Joosua oli päästänyt kansan menemään, menivät israelilaiset kukin perintöosallensa, ottaakseen maan omaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Ja kansa palveli Herraa Joosuan koko elinajan ja niiden vanhinten koko elinajan, jotka elivät vielä kauan Joosuan jälkeen ja jotka olivat nähneet kaikki ne suuret teot, jotka Herra oli Israelille tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Mutta Herran palvelija Joosua, Nuunin poika, kuoli sadan kymmenen vuoden vanhana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Ja he hautasivat hänet hänen perintöosansa alueelle Timnat-Herekseen, Efraimin vuoristoon, pohjoispuolelle Gaas-vuorta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Ja kun koko sekin sukupolvi oli tullut kootuksi isiensä tykö, nousi heidän jälkeensä toinen sukupolvi, joka ei tuntenut Herraa eikä niitä tekoja, jotka hän oli Israelille tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Niin israelilaiset tekivät sitä, mikä oli pahaa Herran silmissä, ja palvelivat baaleja');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'ja hylkäsivät Herran, isiensä Jumalan, joka oli vienyt heidät pois Egyptin maasta, ja lähtivät kulkemaan muiden jumalien jäljessä, niiden kansojen jumalien, jotka asuivat heidän ympärillänsä, kumarsivat niitä ja vihoittivat Herran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Mutta kun he hylkäsivät Herran ja palvelivat baalia ja astarteja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'niin Herran viha syttyi Israelia kohtaan, ja hän antoi heidät ryöstäjien käsiin, jotka ryöstivät heitä, ja myi heidät heidän ympärillään asuvien vihollisten käsiin, niin etteivät he enää voineet kestää vihollistensa edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Mihin ikinä he lähtivätkin, oli Herran käsi heitä vastaan, tuottaen onnettomuutta, niinkuin Herra oli puhunut ja niinkuin Herra oli heille vannonut; ja niin he joutuivat suureen ahdinkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Silloin Herra herätti tuomareita, jotka pelastivat heidät heidän ryöstäjäinsä käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Mutta he eivät totelleet tuomareitansakaan, vaan kulkivat haureudessa muiden jumalien jäljessä ja kumarsivat niitä. Pian he poikkesivat siltä tieltä, jota heidän isänsä, Herran käskyjä totellen, olivat kulkeneet; he eivät tehneet niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Kun siis Herra herätti heille tuomareita, niin Herra oli tuomarin kanssa ja pelasti heidät heidän vihollistensa käsistä niin kauaksi aikaa, kuin tuomari eli; sillä Herran tuli sääli, kun he voihkivat sortajainsa ja vaivaajainsa käsissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Mutta kun tuomari kuoli, vaelsivat he jälleen kelvottomasti, vielä pahemmin kuin heidän isänsä, kulkien muiden jumalien jäljessä, palvellen ja kumartaen niitä. He eivät lakanneet teoistansa eivätkä paatuneesta vaelluksestansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Niin Herran viha syttyi Israelia kohtaan, ja hän sanoi: \"Koska tämä kansa on rikkonut minun liittoni, jonka minä sääsin heidän isillensä, eivätkä he ole kuulleet minun ääntäni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'niin en minäkään enää karkoita heidän tieltänsä ainoatakaan niistä kansoista, jotka Joosua kuollessaan jätti jäljelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Minä tahdon näin heidän kauttansa koetella Israelia, noudattavatko he Herran tietä ja vaeltavatko sitä, niinkuin heidän isänsä tekivät, vai eivätkö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Niin Herra jätti nämä kansat paikoilleen, karkoittamatta niitä heti kohta; hän ei antanut niitä Joosuan käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Nämä ovat ne kansat, jotka Herra jätti paikoilleen koetellakseen niiden kautta Israelia, kaikkia niitä, jotka eivät olleet kokeneet mitään kaikista Kanaanin sodista-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'hän jätti ne ainoastaan sitä varten, että israelilaisten sukupolvet saisivat kokea sotaa, hänen opettaessaan heitä sotimaan, kuitenkin ainoastaan niitä, jotka eivät ennen olleet sotaa kokeneet-:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'filistealaisten viisi ruhtinasta ja kaikki kanaanilaiset ja siidonilaiset ja hivviläiset, jotka asuivat Libanonin vuoristossa, Baal-Hermonin vuoresta siihen saakka, mistä mennään Hamatiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Nämä jäivät, että hän niiden kautta koettelisi Israelia saadakseen tietää, tottelisivatko he Herran käskyjä, jotka hän Mooseksen kautta oli antanut heidän isillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Israelilaiset asuivat siis kanaanilaisten, heettiläisten, amorilaisten, perissiläisten, hivviläisten ja jebusilaisten keskellä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'ja he ottivat heidän tyttäriänsä vaimoikseen ja antoivat omia tyttäriänsä heidän pojillensa ja palvelivat heidän jumaliansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Näin israelilaiset tekivät sitä, mikä oli pahaa Herran silmissä, ja unhottivat Herran, Jumalansa, ja palvelivat baaleja ja aseroita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Silloin Herran viha syttyi Israelia kohtaan, ja hän myi heidät Kuusan-Risataimin, Mesopotamian kuninkaan, käsiin; ja israelilaiset palvelivat Kuusan-Risataimia kahdeksan vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Mutta israelilaiset huusivat Herraa, ja Herra herätti israelilaisille vapauttajan, joka heidät vapautti, Otnielin, Kenaan, Kaalebin nuoremman veljen, pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Ja Herran henki tuli häneen, ja hän oli tuomarina Israelissa; hän lähti sotaan, ja Herra antoi Kuusan-Risataimin, Aramin kuninkaan, hänen käsiinsä, ja Kuusan-Risataim sai tuntea hänen kätensä voimaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Ja maassa oli rauha neljäkymmentä vuotta; sitten Otniel, Kenaan poika, kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Mutta israelilaiset tekivät jälleen sitä, mikä oli pahaa Herran silmissä. Silloin Herra vahvisti Eglonin, Mooabin kuninkaan, Israelia väkevämmäksi, koska he tekivät sitä, mikä oli pahaa Herran silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Ja tämä kokosi luoksensa ammonilaiset ja amalekilaiset, lähti liikkeelle ja voitti Israelin, ja he valtasivat Palmukaupungin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Ja israelilaiset palvelivat Eglonia, mooabilaisten kuningasta, kahdeksantoista vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Ja israelilaiset huusivat Herraa, ja Herra herätti heille vapauttajan, benjaminilaisen Eehudin, Geeran pojan, vasenkätisen miehen. Kun israelilaiset lähettivät hänet viemään veroa Eglonille, Mooabin kuninkaalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'niin Eehud teki itsellensä kaksiteräisen miekan, jalan pituisen, ja sitoi sen takkinsa alle oikealle kupeelleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Ja hän toi veron Eglonille, Mooabin kuninkaalle. Mutta Eglon oli hyvin lihava mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Kun hän oli saanut tuoduksi veron, saattoi hän väen, joka oli verolahjoja kantanut, matkalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Mutta itse hän kääntyi takaisin Gilgalin luona olevilta jumalankuvilta ja käski sanoa: \"Minulla on salaista asiaa sinulle, kuningas\". Niin tämä sanoi: \"Hiljaa!\" Ja kaikki, jotka seisoivat hänen luonaan, menivät hänen luotaan ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Kun Eehud oli tullut hänen luoksensa, hänen istuessaan yksin viileässä yläsalissaan, sanoi Eehud: \"Minulla on sinulle sana Jumalalta\". Silloin hän nousi istuimeltaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'mutta Eehud ojensi vasemman kätensä ja tempasi miekan oikealta kupeeltaan ja pisti sen hänen vatsaansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'niin että kahvakin meni sisään terän mukana ja terä upposi kokonaan ihraan, sillä hän ei vetänyt ulos miekkaa hänen vatsastaan. Sitten hän meni ulos laakealle katolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Kun Eehud oli tullut pylväskäytävään, sulki hän yläsalin ovet jälkeensä ja lukitsi ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Hänen mentyään tulivat kuninkaan palvelijat, ja kun he näkivät, että yläsalin ovet olivat lukitut, niin he ajattelivat: \"Varmaankin hän on tarpeellaan viileässä kammiossa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Sitten he odottivat kyllästyksiin asti, mutta kun hän ei sittenkään avannut yläsalin ovia, ottivat he avaimen ja avasivat itse. Ja katso, heidän herransa makasi kuolleena lattialla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Mutta Eehud oli paennut heidän vitkastellessaan; hän oli jo päässyt jumalankuvien ohi ja pakeni Seiraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Ja sinne tultuaan hän puhalsi pasunaan Efraimin vuoristossa. Silloin israelilaiset laskeutuivat hänen kanssaan vuoristosta, ja hän heidän etunenässään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Ja hän sanoi heille: \"Seuratkaa minua, sillä Herra antaa teidän vihollisenne, mooabilaiset, teidän käsiinne\". Silloin he laskeutuivat hänen jäljessään alas, valtasivat mooabilaisten tieltä Jordanin kahlauspaikat eivätkä päästäneet ketään yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Ja he voittivat silloin Mooabin, lähes kymmenen tuhatta miestä, kaikki voimakkaita ja sotakuntoisia miehiä; eikä ainoakaan päässyt pakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Niin täytyi Mooabin silloin nöyrtyä Israelin käden alle. Ja maassa oli rauha kahdeksankymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Hänen jälkeensä tuli Samgar, Anatin poika. Hän surmasi filistealaisia kuusisataa miestä häränpistimellä; hänkin vapautti Israelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Mutta Eehudin kuoltua israelilaiset tekivät jälleen sitä, mikä oli pahaa Herran silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Silloin Herra myi heidät Jaabinin, Kanaanin kuninkaan, käsiin, joka hallitsi Haasorissa. Hänen sotapäällikkönsä oli Siisera, joka asui Haroset-Goojimissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Ja israelilaiset huusivat Herraa, sillä Siiseralla oli yhdeksätsadat raudoitetut sotavaunut, ja hän sorti ankarasti israelilaisia kaksikymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Mutta Debora, naisprofeetta, Lappidotin vaimo, oli siihen aikaan tuomarina Israelissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Hänen oli tapana istua Deboran-palmun alla, Raaman ja Beetelin välillä, Efraimin vuoristossa, ja israelilaiset menivät hänen luoksensa oikeutta saamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Hän lähetti kutsumaan Baarakin, Abinoamin pojan, Naftalin Kedeksestä, ja hän sanoi hänelle: \"Näin käskee Herra, Israelin Jumala: Lähde ja mene Taaborin vuorelle ja ota mukaasi kymmenentuhatta miestä naftalilaisia ja sebulonilaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Ja minä tuon sinun luoksesi Kiisonin purolle Siiseran, Jaabinin sotapäällikön, sotavaunuineen ja laumoineen ja annan hänet sinun käsiisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Niin Baarak sanoi hänelle: \"Jos sinä lähdet minun kanssani, niin minäkin lähden; mutta jos sinä et lähde minun kanssani, niin en minäkään lähde\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Hän vastasi: \"Minä lähden sinun kanssasi; mutta kunnia siitä retkestä, jolle lähdet, ei tule sinulle, vaan Herra on myyvä Siiseran naisen käsiin\". Niin Debora nousi ja lähti Baarakin kanssa Kedekseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Silloin Baarak kutsui Sebulonin ja Naftalin koolle Kedekseen; kymmenentuhatta miestä seurasi häntä, ja Debora lähti hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Mutta keeniläinen Heber oli eronnut keeniläisistä, Hoobabin, Mooseksen apen, jälkeläisistä; ja hän oli telttaansa pystytellen tullut aina Saanaimin tammelle asti, joka on Kedeksen luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Kun Siiseralle ilmoitettiin, että Baarak, Abinoamin poika, oli noussut Taaborin vuorelle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'niin Siisera kutsui koolle kaikki sotavaununsa, yhdeksätsadat raudoitetut sotavaunut, ja kaiken väen, mikä hänellä oli, Haroset-Goojimista Kiisonin purolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Silloin Debora sanoi Baarakille: \"Nouse, sillä tämä on se päivä, jona Herra antaa Siiseran sinun käsiisi; onhan Herra lähtenyt sinun edelläsi\". Niin Baarak laskeutui Taaborin vuorelta, ja kymmenentuhatta miestä hänen jäljessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Ja Herra saattoi Baarakin miekan terän edessä hämminkiin Siiseran ja kaikki hänen sotavaununsa ja koko hänen joukkonsa; ja Siisera astui alas vaunuistaan ja pakeni jalkaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Mutta Baarak ajoi takaa sotavaunuja ja sotajoukkoa Haroset-Goojimiin saakka. Ja koko Siiseran joukko kaatui miekan terään; ei ainoakaan pelastunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Mutta Siisera oli paennut jalkaisin Jaaelin, keeniläisen Heberin vaimon, teltalle; sillä Jaabinin, Haasorin kuninkaan, ja keeniläisen Heberin perheen välillä oli rauha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Ja Jaael meni Siiseraa vastaan ja sanoi hänelle: \"Poikkea, herrani, poikkea minun luokseni, älä pelkää\". Ja hän poikkesi hänen luoksensa telttaan, ja hän peitti hänet peitteellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Ja hän sanoi hänelle: \"Anna minulle vähän vettä juodakseni, sillä minun on jano\". Niin hän avasi maitoleilin ja antoi hänen juoda ja peitti hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Ja hän sanoi hänelle: \"Asetu teltan ovelle; ja jos joku tulee ja kysyy sinulta ja sanoo: \'Onko täällä ketään?\' niin vastaa: \'Ei ole\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Mutta Jaael, Heberin vaimo, tempasi telttavaarnan, otti vasaran käteensä, hiipi hänen luoksensa ja löi vaarnan hänen ohimoonsa, niin että se tunkeutui aina maahan asti; hän oli näet väsymyksestä vaipunut sikeään uneen, ja hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Ja katso, silloin Baarak tuli ajaen Siiseraa takaa; ja Jaael meni häntä vastaan ja sanoi hänelle: \"Tule, minä näytän sinulle miehen, jota etsit\". Ja hän tuli hänen luoksensa, ja katso, Siisera makasi kuolleena, vaarna ohimossaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Näin Jumala sinä päivänä nöyryytti Jaabinin, Kanaanin kuninkaan, israelilaisten edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Ja israelilaisten käsi painoi yhä raskaammin Jaabinia, Kanaanin kuningasta, kunnes he tuhosivat Jaabinin, Kanaanin kuninkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Sinä päivänä Debora ja Baarak, Abinoamin poika, lauloivat näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, '\"Johtajat johtivat Israelia, kansa oli altis-siitä te kiittäkää Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Kuulkaa, te kuninkaat, kuunnelkaa, te ruhtinaat. Herran kiitosta minä laulan, minä veisaan Herran, Israelin Jumalan, ylistystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Kun sinä, Herra, lähdit liikkeelle Seiristä, kun sinä tulit astuen Edomin maasta, niin maa järisi, ja taivaat vuotivat, pilvet vuotivat vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Vuoret järkkyivät Herran edessä, itse Siinai Herran, Israelin Jumalan, edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Samgarin, Anatin pojan, päivinä, Jaaelin päivinä tiet olivat tyhjinä, matkamiehet kiertelivät syrjäisiä polkuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Israel oli johtoa vailla, peräti vailla, kunnes sinä, Debora, nousit, sinä, Israelin äiti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'He valitsivat uusia jumalia; silloin oli sota porteilla asti, mutta ei näkynyt kilpeä, ei keihästä Israelin neljänkymmenen tuhannen joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Minun sydämeni on kiintynyt Israelin johtomiehiin. Te kansan joukossa alttiit, kiittäkää Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Te, jotka ratsastatte valkoisilla aasintammoilla, te, jotka istutte matoilla, ja te, jotka kuljette teillä, puhukaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Laulu kuuluu juotto-ojilta, siellä ylistetään Herran vanhurskaita tekoja, hänen johdatuksensa vanhurskautta Israelissa. Silloin Herran kansa laskeutui porteille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Heräjä, heräjä, Debora! Heräjä, heräjä, laula laulu! Nouse, Baarak! Ota vankeja saaliiksesi, sinä Abinoamin poika!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Silloin pakolaiset laskeutuivat näiden jalojen luo, Herran kansa laskeutui minun luokseni, sankarien joukko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Efraimista tulivat ne, jotka olivat juurtuneet Amalekiin, he seurasivat sinun joukkojesi mukana, Benjamin. Maakirista laskeutuivat johtomiehet, Sebulonista ne, jotka kantoivat päällikönsauvaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Ja Isaskarin ruhtinaat tulivat Deboran kanssa, ja niinkuin Baarak, niin Isaskar: hän kiiti tasangolle hänen jäljessänsä. Ruubenin suvuissa oli suuria neuvotteluja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Miksi sinä jäit istumaan karjatarhojen välille, kuuntelemaan paimenpillin soittoa? Ruubenin suvuissa oli suuria neuvonpitoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead pysyi alallaan tuolla puolella Jordanin, ja Daan-miksi hän viipyi vierailla laivoilla? Asser jäi istumaan meren rannalle ja pysyi alallaan lahtiensa luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Sebulon on kansa, joka antaa henkensä alttiiksi kuolemaan, samoin Naftali kedon kummuilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Kuninkaat tulivat ja taistelivat, silloin taistelivat Kanaanin kuninkaat Taanakissa, Megiddon vesien varsilla; mutta hopeata he eivät saaneet saaliiksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Tähdet taivaalta kävivät sotaa, radoiltaan ne sotivat Siiseraa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Kiisonin puro tempasi heidät mukaansa, taistelujen puro, Kiisonin puro. Astu esiin, minun sieluni, voimallisesti!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Silloin hevosten kaviot tömistivät maata, kun urhot laskivat, laskivat laukkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Kirotkaa Meeros, sanoo Herran enkeli, kiroamalla kirotkaa sen asukkaat, koska eivät tulleet Herran avuksi, Herran avuksi sankarien joukkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Siunattu olkoon vaimojen joukossa Jaael, keeniläisen Heberin vaimo, siunattu vaimojen joukossa, jotka teltoissa asuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Vettä toinen pyysi, maitoa hän antoi, toi juhlamaljassa kermaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Hän ojensi kätensä ottamaan vaarnaa, oikean kätensä työvasaraa; ja hän iski Siiseraa, löi murskaksi hänen päänsä, musersi ja lävisti hänen ohimonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Hänen jalkainsa juureen hän vaipui, kaatui, jäi siihen, hänen jalkainsa juureen hän vaipui, kaatui; jäi kuolleena makaamaan siihen, mihin vaipui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Siiseran äiti katselee ikkunasta ja huutaa ristikon läpi: \'Miksi viipyvät hänen sotavaununsa tulemasta? Miksi ovat hänen valjakkonsa askeleet niin hitaat?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Viisain hänen ruhtinattaristaan vastaa hänelle, ja hän kertaa itselleen hänen sanansa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '\'Varmaankin he ovat saaneet saalista ja jakavat sitä: tytön, kaksikin mieheen, kirjavaa kangasta saaliiksi Siiseralle, kirjavaa kangasta, kirjaeltua vaatetta saaliiksi, kaksi kirjaeltua, kirjavaa huivia saatujen saalisten kaulaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Niin häviävät kaikki sinun vihollisesi, Herra. Mutta ne, jotka häntä rakastavat, ovat niinkuin aurinko, kun se nousee voimassansa.\" Ja maassa oli rauha neljäkymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Mutta israelilaiset tekivät sitä, mikä oli pahaa Herran silmissä, ja Herra antoi heidät Midianin käsiin seitsemäksi vuodeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Ja Israel sai tuntea Midianin käden voimaa, ja israelilaiset tekivät suojakseen midianilaisia vastaan ne onkalot, joita on vuorissa, ja luolat ja vuorilinnat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Ja joka kerta kun israelilaiset olivat kylväneet, tulivat midianilaiset, amalekilaiset ja Idän miehet ja hyökkäsivät heidän kimppuunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'He leiriytyivät heitä vastaan ja hävittivät maan sadon aina Gassaa myöten eivätkä jättäneet mitään elintarpeita Israeliin, eivät myöskään lampaita, nautakarjaa eivätkä aaseja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Sillä he lähtivät liikkeelle laumoineen ja telttoineen, he tulivat monilukuisina kuin heinäsirkat, heillä ja heidän kameleillaan ei ollut määrää, ja he tulivat maahan sitä hävittämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Niin Israel joutui suureen kurjuuteen midianilaisten tähden; ja israelilaiset huusivat Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Ja kun israelilaiset huusivat Herraa Midianin tähden,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'lähetti Herra israelilaisten luo profeetan, joka sanoi heille: \"Näin sanoo Herra, Israelin Jumala: Minä johdatin teidät Egyptistä ja vein teidät pois orjuuden pesästä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'minä pelastin teidät egyptiläisten käsistä ja kaikkien teidän sortajainne käsistä; minä karkoitin heidät teidän tieltänne ja annoin teille heidän maansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Ja minä sanoin teille: Minä olen Herra, teidän Jumalanne, älkää peljätkö amorilaisten jumalia, joiden maassa te asutte. Mutta te ette kuulleet minun ääntäni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Ja Herran enkeli tuli ja istui Ofran tammen alle, joka oli abieserilaisen Jooaan oma, juuri kun tämän poika Gideon oli puimassa nisuja viinikuurnassa, korjatakseen ne talteen midianilaisilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Ja Herran enkeli ilmestyi hänelle ja sanoi hänelle: \"Herra olkoon sinun kanssasi, sinä sotaurho!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Niin Gideon vastasi hänelle: \"Oi, Herrani, jos Herra on meidän kanssamme, miksi sitten kaikki tämä on meitä kohdannut? Ja missä ovat kaikki hänen ihmeelliset tekonsa, joista isämme ovat meille kertoneet sanoen: \'Herra on johdattanut meidät tänne Egyptistä\'? Mutta nyt Herra on hyljännyt meidät ja antanut meidät Midianin kouriin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Silloin Herra kääntyi häneen ja sanoi: \"Mene tässä voimassasi ja vapauta Israel Midianin kourista; minä lähetän sinut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Hän vastasi hänelle: \"Oi, Herra, millä minä vapautan Israelin? Minun sukunihan on heikoin Manassessa, ja minä itse olen kaikkein vähäisin isäni perheessä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Herra sanoi hänelle: \"Minä olen sinun kanssasi, ja sinä voitat midianilaiset niinkuin yhden ainoan miehen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Mutta hän sanoi hänelle: \"Jos olen saanut armon sinun silmiesi edessä, niin osoita minulle tunnusteolla, että sinä itse puhut minun kanssani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Älä poistu täältä, ennenkuin minä tulen takaisin sinun luoksesi ja tuon uhrilahjani ja panen sen eteesi.\" Hän sanoi: \"Minä jään, kunnes sinä tulet takaisin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Gideon meni ja valmisti vohlan, ja eefa-mitan jauhoja happamattomiksi leiviksi, pani lihan koriin ja liemen pataan ja vei ne hänen luoksensa tammen alle ja pani ne tarjolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Mutta Jumalan enkeli sanoi hänelle: \"Ota liha ja happamattomat leivät ja pane ne tälle kalliolle ja vuodata liemi\". Ja hän teki niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Ja Herran enkeli ojensi sauvan, joka hänellä oli kädessään, ja kosketti sen kärjellä lihaa ja happamattomia leipiä; niin kalliosta nousi tuli, ja se kulutti lihan ja happamattomat leivät. Ja Herran enkeli katosi hänen silmistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Kun Gideon näki, että se oli Herran enkeli, sanoi Gideon: \"Voi minua, Herra, Herra, kun olen nähnyt Herran enkelin kasvoista kasvoihin!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Mutta Herra sanoi hänelle: \"Rauha sinulle! Älä pelkää, sinä et kuole.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Silloin Gideon rakensi siihen Herralle alttarin ja pani sen nimeksi: \"Herra on rauha\". Se on vielä tänäkin päivänä abieserilaisten Ofrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Ja sinä yönä Herra sanoi hänelle: \"Ota härkä, joka isälläsi on, ja toinen seitsenvuotias härkä ja hajota Baalin alttari, joka isälläsi on, ja hakkaa maahan asera-karsikko, joka on sen vieressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Ja rakenna ladotuista kivistä alttari Herralle, Jumalallesi, tämän vuorenkukkulan laelle; ota sitten se toinen härkä ja uhraa se polttouhriksi halkojen päällä, jotka saat hakkaamastasi asera-karsikosta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Niin Gideon otti palvelijoitaan kymmenen miestä ja teki, niinkuin Herra oli hänelle puhunut. Mutta kun hän isänsä perhettä ja kaupungin miehiä peljäten ei uskaltanut tehdä sitä päivällä, teki hän sen yöllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Kun kaupungin miehet varhain seuraavana aamuna nousivat, niin katso, Baalin alttari oli kukistettu ja asera-karsikko sen vierestä hakattu maahan, ja se toinen härkä oli uhrattu polttouhriksi vastarakennetulla alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Niin he sanoivat toinen toiselleen: \"Kuka on tämän tehnyt?\" Ja kun he tutkivat ja tiedustelivat, niin sanottiin: \"Gideon, Jooaan poika, on sen tehnyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Silloin kaupungin miehet sanoivat Jooaalle: \"Tuo tänne poikasi, hänen täytyy kuolla, sillä hän on kukistanut Baalin alttarin ja hakannut maahan asera-karsikon sen vierestä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Mutta Jooas vastasi kaikille, jotka seisoivat hänen ympärillään: \"Tekö ajatte Baalin asiaa, tekö autatte häntä? Se, joka ajaa hänen asiaansa, rangaistakoon kuolemalla ennen huomisaamua. Jos hän on jumala, ajakoon itse asiansa, koska kukistettu alttari oli hänen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Sinä päivänä Gideon sai nimekseen Jerubbaal, sillä sanottiin: \"Baal ajakoon itse asiansa häntä vastaan, koska hän on kukistanut hänen alttarinsa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Kaikki midianilaiset, amalekilaiset ja Idän miehet olivat kokoontuneet yhteen, tulleet virran yli ja leiriytyneet Jisreelin tasangolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Silloin Herran henki täytti Gideonin; hän puhalsi pasunaan, ja niin abieserilaiset kutsuttiin koolle seuraamaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Ja hän lähetti sanansaattajia koko Manasseen, niin että heidätkin kutsuttiin koolle seuraamaan häntä; samoin hän lähetti sanansaattajat Asseriin, Sebuloniin ja Naftaliin, ja nämä lähtivät vihollisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Silloin Gideon sanoi Jumalalle: \"Jos sinä aiot vapauttaa Israelin minun kädelläni, niinkuin olet puhunut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'niin katso, minä panen nämä kerityt villat puimatantereelle: jos kastetta tulee ainoastaan villoihin ja kaikki maa muuten jää kuivaksi, niin minä siitä tiedän, että sinä minun kädelläni vapautat Israelin, niinkuin olet puhunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Ja tapahtui niin. Sillä kun hän varhain seuraavana päivänä nousi ja puristi villoja, pusersi hän kastetta villoista koko vesimaljan täyden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Ja Gideon sanoi Jumalalle: \"Älköön vihasi syttykö minua kohtaan, jos minä vielä kerran puhun. Anna minun vielä kerta tehdä koetus villoilla. Anna ainoastaan villojen jäädä kuiviksi ja kastetta tulla kaikkialle muualle maahan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Ja Jumala teki niin sinä yönä; ainoastaan villat jäivät kuiviksi, ja kastetta tuli kaikkialle muualle maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Varhain seuraavana aamuna Jerubbaal, se on Gideon, ynnä kaikki väki, joka oli hänen kanssaan, leiriytyi Harodin lähteelle. Midianilaisten leiri taas oli siitä, Mooren kukkulasta, pohjoiseen päin, tasangolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Mutta Herra sanoi Gideonille: \"Sinulla on kanssasi liian paljon väkeä, antaakseni Midianin heidän käsiinsä; muuten Israel voisi kerskua minua vastaan ja sanoa: \'Oma käteni vapautti minut\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Julista siis kansan kuullen näin: \'Se, joka pelkää ja on arka, palatkoon takaisin ja väistyköön Gileadin vuorilta\'.\" Niin kansasta palasi takaisin kaksikymmentäkaksi tuhatta, ja kymmenentuhatta jäi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Ja Herra sanoi Gideonille: \"Vielä on väkeä liian paljon; vie heidät alas veden ääreen, niin minä siellä heidät sinulle tutkin. Se, josta minä sinulle sanon: \'Tämä lähteköön sinun kanssasi\', se lähteköön kanssasi; mutta jokainen, josta minä sinulle sanon: \'Tämä älköön lähtekö sinun kanssasi\', se älköön lähtekö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Niin hän vei väen alas veden ääreen. Ja Herra sanoi Gideonille: \"Aseta erikseen jokainen, joka latkii vettä kielellään, niinkuin koira latkii, ja samoin jokainen, joka laskeutuu polvilleen juodaksensa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Niiden luku, jotka latkivat kädestä suuhunsa, oli kolmesataa miestä; kaikki muu väki oli laskeutunut polvilleen juomaan vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Silloin Herra sanoi Gideonille: \"Niillä kolmellasadalla miehellä, jotka latkivat, minä vapautan teidät ja annan Midianin sinun käsiisi; kaikki muu väki menköön kukin kotiinsa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Sitten väki otti mukaansa eväät ja pasunansa, ja hän päästi kaikki Israelin miehet menemään kunkin majalleen, pidättäen ainoastaan ne kolmesataa miestä. Ja midianilaisten leiri oli hänen alapuolellaan tasangolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Sinä yönä Herra sanoi hänelle: \"Nouse ja käy leirin kimppuun, sillä minä annan sen sinun käsiisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Mutta jos sinä pelkäät käydä sen kimppuun, niin mene palvelijasi Puuran kanssa alas leiriin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'ja kuuntele, mitä siellä puhutaan. Sitten saat rohkeutta käydä leirin kimppuun.\" Niin hän meni palvelijansa Puuran kanssa alas aina leirin etuvartijoiden luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Midianilaisia, amalekilaisia ja kaikkia Idän miehiä oli asettunut tasangolle niin paljon kuin heinäsirkkoja; ja heidän kameleillaan ei ollut määrää, niitä oli niin paljon kuin hiekkaa meren rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Kun Gideon tuli, niin muuan mies kertoi untansa toiselle. Hän sanoi: \"Minä näin unta ja katso, ohraleipäkakku tuli pyörien midianilaisten leiriin. Se tuli teltalle saakka, iski siihen niin, että se kaatui, ja käänsi sen ylösalaisin, ja teltta jäi kumoon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Niin toinen vastasi ja sanoi: \"Se ei ole mikään muu kuin israelilaisen Gideonin, Jooaan pojan, miekka; Jumala antaa hänen käsiinsä Midianin ja koko leirin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Kun Gideon oli kuullut kertomuksen unesta ja sen selityksen, niin hän kumartaen rukoili, palasi sitten takaisin Israelin leiriin ja sanoi: \"Nouskaa, sillä Herra antaa midianilaisten leirin teidän käsiinne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Ja hän jakoi ne kolmesataa miestä kolmeen joukkoon ja antoi heille kullekin käteen pasunan ja tyhjän saviruukun, tulisoihtu ruukussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Ja hän sanoi heille: \"Tarkatkaa minua ja tehkää niinkuin minä; kun minä olen tullut leirin laitaan, niin tehkää, niinkuin minä teen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Kun minä ja kaikki, jotka ovat minun kanssani, puhallamme pasunoihin, niin puhaltakaa tekin pasunoihin kaikkialla leirin ympärillä ja huutakaa: \'Herran ja Gideonin puolesta!\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Niin Gideon ja ne sata miestä, jotka olivat hänen kanssansa, tulivat leirin laitaan keskimmäisen yövartion alussa; vartijat olivat juuri asetetut paikoilleen. Silloin he puhalsivat pasunoihin ja särkivät saviruukut, jotka heillä oli käsissään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Niin ne kolme joukkoa puhalsivat pasunoihin, murskasivat saviruukut, tempasivat vasempaan käteensä tulisoihdut ja oikeaan pasunat, puhalsivat niihin ja huusivat: \"Herran ja Gideonin miekka!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Ja he seisoivat kukin paikallaan leirin ympärillä. Mutta leirissä kaikki juoksivat sekaisin, kirkuivat ja pakenivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Ja kun he puhalsivat noihin kolmeensataan pasunaan, niin Herra käänsi toisen miekan toista vastaan koko leirissä, ja leiri pakeni Beet-Sittaan asti Sereraan päin, Tabbatin luona olevan Aabel-Meholan rantaan saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Ja Israelin miehet kutsuttiin koolle Naftalista, Asserista ja koko Manassesta, ja he ajoivat midianilaisia takaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Ja Gideon oli lähettänyt sanansaattajia koko Efraimin vuoristoon, sanomaan: \"Tulkaa alas midianilaisia vastaan ja vallatkaa heidän tieltään vedet aina Beet-Baaraan asti sekä Jordan\". Niin kaikki Efraimin miehet kutsuttiin koolle, ja he valtasivat vedet aina Beet-Baaraan asti sekä Jordanin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Ja he ottivat vangiksi kaksi midianilaisten ruhtinasta, Oorebin ja Seebin; Oorebin he surmasivat Oorebin kalliolla, ja Seebin he surmasivat Seebin viinikuurnan luona, ja he ajoivat midianilaisia takaa. Mutta Oorebin ja Seebin päät he toivat Gideonille tuolta puolelta Jordanin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Mutta Efraimin miehet sanoivat hänelle: \"Miksi teit meille sen, ettet kutsunut meitä, kun menit taistelemaan midianilaisia vastaan?\" Ja he riitelivät kovasti häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Niin hän sanoi heille: \"Mitä minä sitten olen tehnyt teihin verraten? Eikö Efraimin jälkikorjuu ole parempi kuin Abieserin viininkorjuu?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Teidän käsiinnehän Jumala antoi midianilaisten ruhtinaat Oorebin ja Seebin. Mitä minä olen voinut tehdä teihin verraten?\" Kun hän puhui näin, asettui heidän suuttumuksensa häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Kun Gideon tuli Jordanille, meni hän sen yli, hän ja ne kolmesataa miestä, jotka olivat hänen kanssaan. He olivat uuvuksissa takaa-ajamisesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Ja hän sanoi Sukkotin miehille: \"Antakaa joitakin leipäkakkuja väelle, joka seuraa minua, sillä he ovat uuvuksissa; minä olen ajamassa takaa midianilaisten kuninkaita Sebahia ja Salmunnaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Mutta Sukkotin päämiehet sanoivat: \"Onko sinulla sitten jo Sebahin ja Salmunnan nyrkki kädessäsi, että me antaisimme leipää sinun sotajoukollesi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Gideon vastasi: \"Hyvä! Kun Herra antaa Sebahin ja Salmunnan minun käsiini, puin minä teidän lihanne rikki erämaan orjantappuroilla ja orjanruoskilla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Ja hän nousi sieltä Penueliin ja puhui heille samalla tavalla. Ja Penuelin miehet vastasivat hänelle samoin, kuin Sukkotin miehet olivat vastanneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Niin hän sanoi myös Penuelin miehille: \"Jahka palaan voittajana, kukistan minä tämän tornin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Mutta Sebah ja Salmunna olivat Karkorissa ja heidän joukkonsa heidän kanssansa, noin viisitoista tuhatta miestä, kaikki, mitä oli jäljellä Idän miesten koko joukosta; kaatunut oli sata kaksikymmentä tuhatta miekkamiestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Ja Gideon kulki teltoissa-eläjien tietä Noobahin ja Jogbehan itäpuolitse ja voitti joukon, kun se oli huoletonna leirissään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Ja Sebah ja Salmunna pakenivat, mutta hän ajoi heitä takaa; ja hän otti molemmat midianilaisten kuninkaat, Sebahin ja Salmunnan, vangiksi, saatettuaan koko leirin pakokauhun valtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Ja Gideon, Jooaan poika, palasi taistelusta, Hereksen solalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Ja hän otti kiinni erään nuorukaisen, joka oli Sukkotin miehiä, ja kyseli häneltä, ja tämä kirjoitti hänelle Sukkotin päämiehet ja vanhimmat, seitsemänkymmentä seitsemän miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Kun hän sitten tuli Sukkotin miesten luo, sanoi hän: \"Tässä ovat nyt Sebah ja Salmunna, joilla te pilkkasitte minua sanoen: \'Onko sinulla sitten jo Sebahin ja Salmunnan nyrkki kädessäsi, että me antaisimme leipää sinun uupuneille miehillesi?\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Ja hän otti kiinni kaupungin vanhimmat; ja hän otti erämaan orjantappuroita ja orjanruoskia ja antoi Sukkotin miesten maistaa niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Ja hän kukisti Penuelin tornin ja surmasi kaupungin miehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Sitten hän sanoi Sebahille ja Salmunnalle: \"Minkä näköisiä ne miehet olivat, jotka te tapoitte Taaborilla?\" He vastasivat: \"Ne olivat niinkuin sinä; jokainen oli varreltaan kuin kuninkaan poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Hän sanoi: \"He olivat minun veljiäni, minun äitini poikia. Niin totta kuin Herra elää: jos te olisitte jättäneet heidät henkiin, en minä surmaisi teitä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Ja hän sanoi Jeterille, esikoiselleen: \"Nouse ja surmaa heidät\". Mutta nuorukainen ei paljastanut miekkaansa, sillä hän pelkäsi, koska oli vielä nuori.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Silloin sanoivat Sebah ja Salmunna: \"Nouse sinä ja pistä meidät kuoliaaksi, sillä miehellä on miehen voima\". Niin Gideon nousi ja surmasi Sebahin ja Salmunnan. Ja hän otti heidän kameliensa kaulasta puolikuukorut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Niin Israelin miehet sanoivat Gideonille: \"Hallitse sinä meitä, sekä sinä itse että sinun poikasi ja poikasi poika; sillä sinä olet vapauttanut meidät Midianin käsistä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Mutta Gideon vastasi heille: \"En minä hallitse teitä, eikä minun poikani ole hallitseva teitä; Herra on teitä hallitseva\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Ja Gideon sanoi heille: \"Yhtä minä pyydän teiltä: antakoon kukin minulle heiltä saaliiksi saamansa nenärenkaan\". Heikäläisillä näet on kultaiset nenärenkaat, koska ovat ismaelilaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Niin he vastasivat: \"Annamme mielellämme\". Ja he levittivät vaipan ja heittivät siihen kukin saaliiksi saamansa nenärenkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Ja hänen pyytämänsä kultaiset nenärenkaat painoivat tuhat seitsemänsataa kultasekeliä, lukuunottamatta niitä puolikuukoruja, korvarenkaita ja purppuravaatteita, joita midianilaisten kuninkaat olivat kantaneet, ja heidän kameliensa kaulavitjoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Ja Gideon valmisti niistä kasukan, jonka hän sijoitti kaupunkiinsa Ofraan, ja koko Israel kulki haureudessa siellä sen jäljessä. Ja se tuli ansaksi Gideonille ja hänen perheellensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Niin täytyi Midianin nöyrtyä israelilaisten edessä, eikä se enää nostanut päätänsä. Ja maassa oli rauha neljäkymmentä vuotta, niin kauan kuin Gideon eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Ja Jerubbaal, Jooaan poika, meni ja jäi asumaan taloonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Ja Gideonilla oli seitsemänkymmentä poikaa, jotka olivat lähteneet hänen kupeistansa; sillä hänellä oli monta vaimoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Ja myös hänen sivuvaimonsa, joka hänellä oli Sikemissä, synnytti hänelle pojan, ja hän antoi tälle nimen Abimelek.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Ja Gideon, Jooaan poika, kuoli päästyään korkeaan ikään, ja hänet haudattiin isänsä Jooaan hautaan abieserilaisten Ofraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Mutta kun Gideon oli kuollut, niin israelilaiset lähtivät jälleen haureudessa kulkemaan baalien jäljessä ja ottivat Baal-Beritin jumalaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Eivätkä israelilaiset enää muistaneet Herraa, Jumalaansa, joka oli pelastanut heidät kaikkien heidän vihollistensa käsistä, jotka asuivat heidän ympärillään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Eivät he myöskään tehneet Jerubbaalin, Gideonin, perheelle laupeutta kaiken sen hyvän tähden, mitä hän oli tehnyt Israelille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Mutta Abimelek, Jerubbaalin poika, meni Sikemiin äitinsä veljien luo ja puhui heille sekä kaikille, jotka olivat sukua hänen äitinsä isän perheelle, ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, '\"Puhukaa kaikkien Sikemin miesten kuullen: Kumpi teille on parempi, sekö, että teitä hallitsee seitsemänkymmentä miestä, kaikki Jerubbaalin pojat, vai että teitä hallitsee yksi mies? Ja muistakaa, että minä olen teidän luutanne ja lihaanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Niin hänen äitinsä veljet puhuivat hänen puolestaan kaikkien Sikemin miesten kuullen kaiken tämän. Ja heidän sydämensä taipui Abimelekin puolelle, sillä he sanoivat: \"Hän on meidän veljemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Ja he antoivat hänelle seitsemänkymmentä hopeasekeliä Baal-Beritin temppelistä. Niillä Abimelek palkkasi tyhjäntoimittajia ja huikentelijoita, ja ne seurasivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Sitten hän lähti isänsä taloon Ofraan ja surmasi veljensä, Jerubbaalin pojat, seitsemänkymmentä miestä, saman kiven päällä; mutta Jootam, Jerubbaalin nuorin poika, jäi henkiin, sillä hän oli piiloutunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Sen jälkeen kokoontuivat kaikki Sikemin miehet ja koko Millon väki, ja he menivät ja tekivät Abimelekin kuninkaaksi Muistomerkkitammen luona, joka on Sikemissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Kun se kerrottiin Jootamille, niin hän meni, asettui seisomaan Garissimin vuoren laelle ja korotti äänensä, huusi ja sanoi heille: \"Kuulkaa minua, te Sikemin miehet, että Jumalakin kuulisi teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Puut lähtivät voitelemaan itsellensä kuningasta. Ja he sanoivat öljypuulle: \'Ole sinä meidän kuninkaamme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Mutta öljypuu vastasi heille: \'Jättäisinkö lihavuuteni, josta jumalat ja ihmiset minua ylistävät, mennäkseni huojumaan ylempänä muita puita!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Niin puut sanoivat viikunapuulle: \'Tule sinä ja ole meidän kuninkaamme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Mutta viikunapuu vastasi heille: \'Jättäisinkö makeuteni ja hyvät antimeni, mennäkseni huojumaan ylempänä muita puita!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Niin puut sanoivat viinipuulle: \'Tule sinä ja ole meidän kuninkaamme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Mutta viinipuu vastasi heille: \'Jättäisinkö mehuni, joka saa jumalat ja ihmiset iloisiksi, mennäkseni huojumaan ylempänä muita puita!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Niin kaikki puut sanoivat orjantappuralle: \'Tule sinä ja ole meidän kuninkaamme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Ja orjantappura vastasi puille: \'Jos todella aiotte voidella minut kuninkaaksenne, niin tulkaa ja etsikää suojaa minun varjossani; mutta ellette, niin tuli lähtee orjantappurasta ja kuluttaa Libanonin setrit\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Jos te nyt olette menetelleet uskollisesti ja rehellisesti tehdessänne Abimelekin kuninkaaksi ja jos olette kohdelleet hyvin Jerubbaalia ja hänen perhettänsä ja jos olette palkinneet häntä siitä, mitä hänen kätensä ovat hyvää tehneet-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'sillä sotihan minun isäni teidän puolestanne ja pani alttiiksi henkensä ja pelasti teidät Midianin käsistä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'mutta te olette tänä päivänä nousseet minun isäni perhettä vastaan ja surmanneet hänen poikansa, seitsemänkymmentä miestä, saman kiven päällä ja tehneet Abimelekin, hänen orjattarensa pojan, Sikemin miesten kuninkaaksi, koska hän on teidän veljenne-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'jos te siis olette tänä päivänä menetelleet uskollisesti ja rehellisesti Jerubbaalia ja hänen perhettänsä kohtaan, niin olkoon teillä iloa Abimelekista ja myöskin hänellä olkoon iloa teistä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'mutta ellette ole, niin lähteköön tuli Abimelekista ja kuluttakoon Sikemin miehet sekä Millon väen; ja samoin lähteköön tuli Sikemin miehistä ja Millon väestä ja kuluttakoon Abimelekin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Sitten Jootam lähti pakoon ja pääsi pakenemaan Beeriin; hän asettui sinne suojaan veljeltään Abimelekilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Kun Abimelek oli hallinnut Israelia kolme vuotta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'lähetti Jumala pahan hengen Abimelekin ja Sikemin miesten väliin, niin että Sikemin miehet luopuivat Abimelekista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'jotta Jerubbaalin seitsemällekymmenelle pojalle tehty väkivalta tulisi kostetuksi ja heidän verensä tulisi Abimelekin, heidän veljensä, päälle, joka oli heidät surmannut, ja Sikemin miesten päälle, jotka olivat auttaneet häntä surmaamaan veljensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Ja Sikemin miehet asettivat vuorten kukkuloille väijyjiä, ja nämä ryöstivät jokaisen, joka kulki sitä tietä heidän ohitsensa. Se kerrottiin Abimelekille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Mutta Gaal, Ebedin poika, tuli veljineen, ja he poikkesivat Sikemiin; ja Sikemin miehet luottivat häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Ja he menivät kedolle ja korjasivat sadon viinitarhoistaan, polkivat rypäleet ja pitivät ilojuhlan; he menivät jumalansa huoneeseen ja söivät ja joivat ja kirosivat Abimelekia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Ja Gaal, Ebedin poika, sanoi: \"Mikä on Abimelek, ja mikä on Sikem, että me häntä palvelisimme? Eikö hän ole Jerubbaalin poika, eikö Sebul ole hänen käskynhaltijansa? Palvelkaa Hamorin, Sikemin isän, miehiä. Miksi me palvelisimme häntä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'Olisipa minulla tuo kansa vallassani, niin minä toimittaisin pois Abimelekin; ja Abimelekista hän sanoi: \'Lisää sotajoukkoasi ja tule!\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Mutta kun Sebul, kaupungin päällikkö, kuuli Gaalin, Ebedin pojan, sanat, syttyi hänen vihansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Ja hän lähetti salaa sanansaattajia Abimelekin luo sanomaan: \"Katso, Gaal, Ebedin poika, ja hänen veljensä ovat tulleet Sikemiin, ja nyt he yllyttävät kaupunkia sinua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Nouse siis yöllä, sinä ja väki, joka on sinun kanssasi, ja asetu kedolle väijyksiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Ja karkaa aamulla varhain, auringon noustessa, kaupungin kimppuun. Kun hän ja väki, joka on hänen kanssaan, silloin lähtee sinua vastaan, niin tee hänelle, minkä voit.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Silloin Abimelek ja kaikki väki, joka oli hänen kanssaan, lähti liikkeelle yöllä, ja he asettuivat väijyksiin Sikemiä vastaan neljässä joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Ja Gaal, Ebedin poika, tuli ulos ja asettui kaupungin portin ovelle; niin Abimelek ja väki, joka oli hänen kanssaan, nousi väijytyspaikasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Kun Gaal näki väen, sanoi hän Sebulille: \"Katso, väkeä tulee alas vuorten kukkuloilta\". Mutta Sebul vastasi hänelle: \"Vuorten varjot näyttävät sinusta miehiltä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Gaal puhui taas ja sanoi: \"Katso, väkeä tulee alas Maannavalta; ja toinen joukko tulee Tietäjätammelta päin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Silloin Sebul sanoi hänelle: \"Missä on nyt sinun suuri suusi, kun sanoit: \'Mikä on Abimelek, että me häntä palvelisimme?\' Siinä on nyt se väki, jota halveksit. Mene nyt ja taistele heitä vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Niin Gaal lähti Sikemin miesten etunenässä ja taisteli Abimelekia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Mutta Abimelek ajoi hänet pakoon, ja hän pääsi pakenemaan häntä; ja heitä kaatui paljon, aina portin ovelle asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Ja Abimelek jäi Arumaan; mutta Sebul karkoitti Gaalin ja hänen veljensä pois Sikemistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Seuraavana päivänä kansa lähti ulos kedolle, ja siitä ilmoitettiin Abimelekille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Silloin hän otti väkensä ja jakoi sen kolmeen joukkoon ja asettui väijyksiin kedolle. Ja kun hän näki kansan lähtevän kaupungista, hyökkäsi hän heidän kimppuunsa ja surmasi heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Abimelek ja ne joukot, jotka olivat hänen kanssaan, karkasivat näet esiin ja asettuivat kaupungin portin ovelle, samalla kuin muut kaksi joukkoa karkasivat kaikkien niiden kimppuun, jotka olivat kedolla, ja surmasivat heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Sitten Abimelek taisteli kaupunkia vastaan koko sen päivän, valloitti kaupungin ja surmasi kansan, joka siellä oli. Ja hän hävitti kaupungin ja kylvi suolaa sen paikalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Kun kaikki Sikemin tornin miehet sen kuulivat, menivät he Eel-Beritin temppelin holviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Mutta kun Abimelekille kerrottiin, että kaikki Sikemin tornin miehet olivat kokoontuneet sinne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'niin Abimelek nousi Salmonin vuorelle, hän ja kaikki väki, joka oli hänen kanssaan. Ja Abimelek otti kirveen käteensä ja löi poikki puunoksan, nosti ja pani sen olalleen ja sanoi väelle, joka oli hänen kanssaan: \"Mitä näitte minun tekevän, se tehkää tekin joutuin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Niin väestäkin löi poikki oksansa kukin; sitten he seurasivat Abimelekia, panivat oksat holvin päälle ja sytyttivät holvin heidän päällään palamaan. Niin saivat surmansa myöskin kaikki Sikemin tornin asukkaat, noin tuhat miestä ja naista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Sitten Abimelek meni Teebekseen, asettui leiriin Teebestä vastaan ja valloitti sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Mutta kaupungin keskellä oli luja torni, ja kaikki miehet ja naiset, kaikki kaupungin asukkaat, pakenivat siihen. He sulkivat jälkeensä oven ja nousivat tornin katolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Niin Abimelek tuli tornin ääreen ja ryhtyi taisteluun sitä vastaan; ja hän astui tornin ovelle polttaakseen sen tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Mutta eräs nainen heitti jauhinkiven Abimelekin päähän ja murskasi hänen pääkallonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Silloin hän heti huusi palvelijalle, joka kantoi hänen aseitansa, ja sanoi hänelle: \"Paljasta miekkasi ja surmaa minut, ettei minusta sanottaisi: \'Nainen tappoi hänet\'\". Ja hänen palvelijansa lävisti hänet, ja hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Kun Israelin miehet näkivät, että Abimelek oli kuollut, menivät he kukin kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Näin Jumala kosti Abimelekille sen pahan, minkä hän oli tehnyt isäänsä kohtaan surmatessaan seitsemänkymmentä veljeään;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'ja kaiken Sikemin miesten tekemän pahan Jumala käänsi heidän omaan päähänsä. Niin heidät saavutti Jootamin, Jerubbaalin pojan, kirous.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Abimelekin jälkeen nousi Israelia vapauttamaan isaskarilainen Toola, Doodon pojan Puuan poika, joka asui Saamirissa, Efraimin vuoristossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Hän oli tuomarina Israelissa kaksikymmentä kolme vuotta; sitten hän kuoli, ja hänet haudattiin Saamiriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Hänen jälkeensä nousi gileadilainen Jaair ja oli tuomarina Israelissa kaksikymmentä kaksi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Ja hänellä oli kolmekymmentä poikaa, jotka ratsastivat kolmellakymmenellä aasilla; ja heillä oli kolmekymmentä kaupunkia, joita vielä tänäkin päivänä kutsutaan Jaairin leirikyliksi ja jotka ovat Gileadin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Ja Jaair kuoli, ja hänet haudattiin Kaamoniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Mutta israelilaiset tekivät jälleen sitä, mikä oli pahaa Herran silmissä, ja palvelivat baaleja ja astarteja ja Aramin jumalia, Siidonin jumalia, Mooabin jumalia, ammonilaisten jumalia ja filistealaisten jumalia, ja he hylkäsivät Herran eivätkä palvelleet häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Niin Herran viha syttyi Israelia kohtaan, ja hän myi heidät filistealaisten ja ammonilaisten käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Nämä riistivät ja raastivat israelilaisia sen vuoden ja vielä kahdeksantoista vuotta, kaikkia israelilaisia, jotka asuivat tuolla puolella Jordanin amorilaisten maassa, Gileadissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Ja ammonilaiset menivät Jordanin yli taistelemaan myöskin Juudaa, Benjaminia ja Efraimin heimoa vastaan, ja niin Israel joutui suureen ahdinkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Silloin israelilaiset huusivat Herraa sanoen: \"Me olemme tehneet syntiä sinua vastaan, sillä me olemme hyljänneet oman Jumalamme ja palvelleet baaleja\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Ja Herra vastasi israelilaisille: \"Eivätkö egyptiläiset, amorilaiset, ammonilaiset, filistealaiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'siidonilaiset, amalekilaiset ja maaonilaiset sortaneet teitä, ja kun te huusitte minua, enkö minä pelastanut teitä heidän käsistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Mutta te hylkäsitte minut ja palvelitte muita jumalia; sentähden en minä enää teitä pelasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Menkää ja huutakaa avuksenne niitä jumalia, jotka olette valinneet; pelastakoot ne teidät ahdinkonne aikana.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Niin israelilaiset sanoivat Herralle: \"Me olemme syntiä tehneet; tee sinä meille aivan niinkuin hyväksi näet, kunhan vain tänä päivänä autat meitä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Ja he poistivat vieraat jumalat keskuudestaan ja palvelivat Herraa. Silloin hän ei enää kärsinyt, että Israelia vaivattiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Ja ammonilaiset kutsuttiin koolle, ja he leiriytyivät Gileadiin; mutta israelilaiset kokoontuivat ja leiriytyivät Mispaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Silloin kansa, Gileadin ruhtinaat, sanoivat toisillensa: \"Kuka on se mies, joka alkaa taistelun ammonilaisia vastaan? Hän on oleva kaikkien Gileadin asukasten päämies.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Gileadilainen Jefta oli sotaurho, mutta hän oli porton poika; Jeftan isä oli Gilead.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Mutta Gileadin vaimo synnytti hänelle poikia, ja kun tämän vaimon pojat kasvoivat suuriksi, niin he karkoittivat Jeftan ja sanoivat hänelle: \"Et sinä saa perintöosaa meidän isämme talossa, sillä sinä olet toisen naisen poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Niin Jefta lähti pakoon veljiänsä ja asettui Toobin maahan. Ja Jeftan luo kerääntyi tyhjäntoimittajia, ja ne retkeilivät yhdessä hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Jonkun ajan kuluttua ammonilaiset aloittivat sodan Israelia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Kun nyt ammonilaiset alottivat sodan Israelia vastaan, niin Gileadin vanhimmat lähtivät noutamaan Jeftaa Toobin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Ja he sanoivat Jeftalle: \"Tule ja rupea meidän päälliköksemme, sotiaksemme ammonilaisia vastaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Mutta Jefta vastasi Gileadin vanhimmille: \"Ettekö te vihanneet minua ja karkoittaneet minua isäni talosta? Minkätähden tulette minun luokseni nyt, kun teillä on hätä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Gileadin vanhimmat sanoivat Jeftalle: \"Juuri sentähden olemme nyt tulleet jälleen sinun luoksesi; ja jos sinä tulet meidän kanssamme ja ryhdyt taistelemaan ammonilaisia vastaan, niin sinä olet oleva meidän, kaikkien Gileadin asukasten, päämies\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Jefta vastasi Gileadin vanhimmille: \"Jos te viette minut takaisin, taistelemaan ammonilaisia vastaan, ja Herra antaa heidät minun valtaani, niin minä rupean teidän päämieheksenne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Silloin Gileadin vanhimmat sanoivat Jeftalle: \"Herra kuulee meidän välipuheemme; totisesti, me teemme kaiken, mitä sinä sanoit\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Niin Jefta lähti Gileadin vanhinten kanssa, ja kansa asetti hänet päämiehekseen ja päällikökseen. Ja Jefta lausui Herran edessä Mispassa kaiken, mitä oli puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Sitten Jefta lähetti ammonilaisten kuninkaan luo sanansaattajia sanomaan: \"Mitä sinulla on minun kanssani tekemistä, kun tulet minua vastaan, sotimaan minun maatani vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Niin ammonilaisten kuningas vastasi Jeftan sanansaattajille: \"Ottihan Israel tullessaan Egyptistä minun maani Arnonista Jabbokiin ja Jordaniin asti; anna se nyt hyvällä takaisin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Jefta lähetti taas sanansaattajia ammonilaisten kuninkaan luo');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'ja käski sanoa hänelle: \"Näin sanoo Jefta: Ei Israel ole ottanut Mooabin maata eikä ammonilaisten maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Sillä tullessaan Egyptistä Israel kulki erämaan kautta Kaislamerelle saakka ja tuli Kaadekseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Ja Israel lähetti sanansaattajia Edomin kuninkaan luo sanomaan: \'Salli minun kulkea maasi läpi\'. Mutta Edomin kuningas ei kuullut heitä. Ja he lähettivät sanan myöskin Mooabin kuninkaalle, mutta ei hänkään suostunut. Niin Israel asettui Kaadekseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Sitten he kulkivat erämaan kautta ja kiersivät Edomin maan ja Mooabin maan ja tulivat itäpuolelle Mooabin maata ja leiriytyivät Arnonin toiselle puolelle; he eivät tulleet Mooabin alueelle, sillä Arnon on Mooabin raja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Silloin Israel lähetti sanansaattajia Siihoniin, amorilaisten kuninkaan, Hesbonin kuninkaan, luo, ja Israel käski sanoa hänelle: \'Salli meidän kulkea maasi läpi määräpaikkaamme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Mutta Siihon ei uskonut Israelia, niin että olisi sallinut sen kulkea alueensa läpi, vaan Siihon kokosi kaiken väkensä, ja he leiriytyivät Jahaaseen, ja hän ryhtyi taisteluun Israelia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Mutta Herra, Israelin Jumala, antoi Siihonin ja kaiken hänen väkensä Israelin käsiin, niin että nämä voittivat heidät. Ja Israel valloitti koko amorilaisten maan, niiden, jotka asuivat siinä maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Ja he ottivat omakseen koko amorilaisten alueen Arnonista Jabbokiin asti ja erämaasta Jordaniin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Näin siis Herra, Israelin Jumala, karkoitti amorilaiset kansansa Israelin tieltä. Ja nyt sinä ottaisit omaksesi heidän maansa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Eikö ole niin: minkä sinun jumalasi Kemos antaa sinun omaksesi, sen sinä otat omaksesi; ja kenen hyvänsä Herra, meidän Jumalamme, karkoittaa meidän tieltämme, sen maan me otamme omaksemme?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Vai oletko sinä parempi kuin Baalak, Sipporin poika, Mooabin kuningas? Rakensiko hän riitaa Israelin kanssa, tahi ryhtyikö hän sotaan heitä vastaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Israel on nyt asunut Hesbonissa ja sen tytärkaupungeissa, Aroerissa ja sen tytärkaupungeissa ja kaikissa Arnonin varrella olevissa kaupungeissa kolmesataa vuotta. Miksi te ette sen ajan kuluessa ole ottaneet niitä pois?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Minä en ole rikkonut sinua vastaan, mutta sinä teet pahasti minua kohtaan, kun ryhdyt sotimaan minua vastaan. Herra, joka on tuomari, tuomitkoon tänä päivänä israelilaisten ja ammonilaisten välillä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Mutta ammonilaisten kuningas ei ottanut kuuloonsa, mitä Jefta lähetti hänelle sanomaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Silloin Herran henki tuli Jeftaan, ja hän kulki Gileadin ja Manassen läpi ja kulki edelleen Gileadin Mispeen, ja Gileadin Mispestä hän lähti ammonilaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Ja Jefta teki lupauksen Herralle ja sanoi: \"Jos sinä annat ammonilaiset minun käsiini,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'niin tulkoon kuka tulkoonkin minua vastaan taloni ovesta, kun minä voittajana palaan ammonilaisten luota, hän on oleva Herran, ja minä uhraan hänet polttouhriksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Sitten Jefta lähti ammonilaisia vastaan, sotimaan heitä vastaan, ja Herra antoi heidät hänen käsiinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Ja hän tuotti heille hyvin suuren tappion, valloittaen maan Aroerista Minnitiin ja Aabel-Keramimiin asti, kaksikymmentä kaupunkia. Niin täytyi ammonilaisten nöyrtyä israelilaisten edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Kun Jefta sitten tuli kotiinsa Mispaan, niin katso, hänen tyttärensä tuli ulos häntä vastaan vaskirumpua lyöden ja karkeloiden. Ja hän oli hänen ainoa lapsensa; paitsi tätä ei hänellä ollut poikaa eikä tytärtä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Nähdessään hänet hän repäisi vaatteensa ja sanoi: \"Voi, tyttäreni, nyt sinä masennat minut maahan, nyt sinä syökset minut onnettomuuteen! Sillä minä avasin suuni Herralle enkä voi sanaani peruuttaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Niin hän vastasi hänelle: \"Isäni, jos sinä avasit suusi Herralle, niin tee minulle, niinkuin suusi on puhunut, koska Herra on antanut sinun kostaa vihollisillesi, ammonilaisille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Sitten hän sanoi isällensä: \"Myönnettäköön minulle kuitenkin tämä: jätä minut vapauteeni kahdeksi kuukaudeksi, että minä yhdessä ystävättärieni kanssa menen vuorille itkemään neitsyyttäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Niin hän sanoi: \"Mene!\" ja päästi hänet menemään kahdeksi kuukaudeksi. Ja hän meni ystävättärineen ja itki neitsyyttänsä vuorilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Mutta kahden kuukauden kuluttua hän palasi isänsä luo, ja tämä pani hänessä täytäntöön lupauksensa, jonka oli tehnyt. Eikä hän miehestä tietänyt. Ja tuli tavaksi Israelissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'että Israelin tyttäret joka vuosi menivät lauluin ylistämään gileadilaisen Jeftan tytärtä-neljän päivän ajaksi joka vuosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Ja Efraimin miehet kutsuttiin koolle, ja he lähtivät pohjoiseen päin ja sanoivat Jeftalle: \"Miksi lähdit sotimaan ammonilaisia vastaan kutsumatta meitä tulemaan kanssasi? Me poltamme tulella sinun talosi pääsi päältä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Jefta vastasi heille: \"Minulla ja minun kansallani oli kova taistelu ammonilaisten kanssa; silloin minä kutsuin teitä, mutta te ette tulleet auttamaan minua heidän käsistään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Ja kun minä näin, ettette tulleet auttamaan minua, panin minä henkeni kämmenelleni ja lähdin ammonilaisia vastaan, ja Herra antoi heidät minun käsiini. Miksi te olette nyt lähteneet minua vastaan, sotimaan minua vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Ja Jefta kokosi kaikki Gileadin miehet ja ryhtyi taisteluun Efraimia vastaan; ja Gileadin miehet voittivat efraimilaiset, jotka olivat sanoneet: \"Te olette karkureita Efraimista; Gilead on Efraimin ja Manassen keskessä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Ja gileadilaiset valtasivat efraimilaisten tieltä Jordanin kahlauspaikat. Kun sitten Efraimin pakolaiset sanoivat: \"Antakaa minun mennä yli\", kysyivät Gileadin miehet kultakin: \"Oletko efraimilainen?\" Jos hän vastasi: \"En\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'niin he sanoivat hänelle: \"Sano \'shibbolet\'\". Jos hän sanoi \"sibbolet\", kun ei osannut ääntää oikein, ottivat he hänet kiinni ja tappoivat Jordanin kahlauspaikoilla. Niin kaatui silloin Efraimista neljäkymmentäkaksi tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Ja Jefta oli tuomarina Israelissa kuusi vuotta; sitten gileadilainen Jefta kuoli, ja hänet haudattiin erääseen Gileadin kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Hänen jälkeensä oli Ibsan, Beetlehemistä, tuomarina Israelissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Hänellä oli kolmekymmentä poikaa, ja hän naitti kolmekymmentä tytärtänsä muualle ja toi muualta kolmekymmentä tyttöä pojilleen vaimoiksi. Ja hän oli tuomarina Israelissa seitsemän vuotta. 12:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Sitten Ibsan kuoli, ja hänet haudattiin Beetlehemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Hänen jälkeensä oli sebulonilainen Eelon tuomarina Israelissa; hän oli tuomarina Israelissa kymmenen vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Sitten sebulonilainen Eelon kuoli, ja hänet haudattiin Aijaloniin, Sebulonin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Hänen jälkeensä oli piratonilainen Abdon, Hillelin poika, tuomarina Israelissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Hänellä oli neljäkymmentä poikaa ja kolmekymmentä pojanpoikaa, jotka ratsastivat seitsemälläkymmenellä aasilla; hän oli tuomarina Israelissa kahdeksan vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Sitten piratonilainen Abdon, Hillelin poika, kuoli, ja hänet haudattiin Piratoniin, Efraimin maahan, amalekilaisten vuoristoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Kun israelilaiset taas tekivät sitä, mikä oli pahaa Herran silmissä, niin Herra antoi heidät filistealaisten käsiin neljäksikymmeneksi vuodeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Sorassa oli mies, Daanin sukukuntaa, nimeltä Maanoah; hänen vaimonsa oli hedelmätön eikä ollut synnyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Silloin ilmestyi Herran enkeli vaimolle ja sanoi hänelle: \"Katso, sinä olet hedelmätön etkä ole synnyttänyt, mutta sinä tulet raskaaksi ja synnytät pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Varo siis, ettet juo viiniä ja väkijuomaa etkä syö mitään saastaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Sillä katso, sinä tulet raskaaksi ja synnytät pojan; partaveitsi älköön koskettako hänen päätänsä, sillä poika on oleva Jumalan nasiiri äitinsä kohdusta asti, ja hän on alottava Israelin vapauttamisen filistealaisten käsistä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Niin vaimo meni ja sanoi miehelleen näin: \"Jumalan mies tuli minun luokseni; hän oli näöltään niinkuin Jumalan enkeli, hyvin peljättävä. En kysynyt häneltä, mistä hän oli, eikä hän ilmaissut minulle nimeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Ja hän sanoi minulle: \'Katso, sinä tulet raskaaksi ja synnytät pojan; älä siis juo viiniä ja väkijuomaa äläkä syö mitään saastaista, sillä poika on oleva Jumalan nasiiri äitinsä kohdusta aina kuolinpäiväänsä asti\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Silloin Maanoah rukoili Herraa ja sanoi: \"Oi Herra, salli Jumalan miehen, jonka lähetit, vielä tulla luoksemme opettamaan meille, mitä meidän on tehtävä pojalle, joka on syntyvä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Ja Jumala kuuli Maanoahin rukouksen, ja Jumalan enkeli tuli jälleen vaimon tykö, kun tämä istui kedolla; ja Maanoah, hänen miehensä, ei ollut hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Niin vaimo juoksi nopeasti ilmoittamaan miehellensä ja sanoi hänelle: \"Katso, sama mies, joka äsken kävi luonani, ilmestyi minulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Niin Maanoah nousi ja seurasi vaimoaan. Ja kun hän tuli miehen luo, sanoi hän tälle: \"Sinäkö olet se mies, joka puhuttelit tätä vaimoa?\" Hän vastasi: \"Minä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Silloin Maanoah sanoi: \"Kun sanasi käy toteen, miten sitten on meneteltävä pojan kanssa ja mitä hänelle on tehtävä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Herran enkeli sanoi Maanoahille: \"Varokoon vaimo kaikkea, mistä minä olen hänelle puhunut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Älköön syökö mitään, mikä viiniköynnöksestä tulee, viiniä ja väkijuomaa hän älköön juoko älköönkä syökö mitään saastaista. Noudattakoon hän kaikkea, mitä minä olen käskenyt hänen noudattaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Ja Maanoah sanoi Herran enkelille: \"Salli meidän pidättää sinua valmistaaksemme sinulle vohlan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Mutta Herran enkeli vastasi Maanoahille: \"Vaikka sinä pidättäisitkin minut, en minä kuitenkaan söisi sinun ruokaasi; mutta jos tahdot valmistaa polttouhrin, niin uhraa se Herralle\". Sillä Maanoah ei tiennyt häntä Herran enkeliksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Niin Maanoah sanoi Herran enkelille: \"Mikä on sinun nimesi, kunnioittaaksemme sinua, kun sinun sanasi käy toteen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Herran enkeli vastasi hänelle: \"Minkätähden kysyt minun nimeäni? Se on ihmeellinen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Niin Maanoah otti vohlan ja ruokauhrin ja uhrasi sen kalliolla Herralle. Ja Herra teki ihmeen Maanoahin ja hänen vaimonsa nähden:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'liekin kohotessa alttarilta taivasta kohti kohosi Herran enkeli alttarin liekissä ylös Maanoahin ja hänen vaimonsa nähden, ja he heittäytyivät kasvoilleen maahan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'eikä Herran enkeli enää ilmestynyt Maanoahille ja hänen vaimollensa. Nyt Maanoah tiesi hänet Herran enkeliksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Niin Maanoah sanoi vaimolleen: \"Me olemme kuoleman omat, sillä olemme nähneet Jumalan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Mutta hänen vaimonsa vastasi hänelle: \"Jos Herra tahtoisi surmata meidät, ei hän olisi ottanut meiltä vastaan polttouhria ja ruokauhria eikä antanut meidän nähdä tätä kaikkea eikä antanut meidän juuri nyt tätä kuulla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Ja vaimo synnytti pojan ja antoi hänelle nimen Simson; ja poika kasvoi, ja Herra siunasi häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Ja Herran henki alkoi hänessä vaikuttaa Daanin leirissä, Soran ja Estaolin välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Ja Simson meni alas Timnaan ja näki Timnassa naisen, filistealaisten tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Niin hän tuli sieltä ja kertoi sen isälleen ja äidilleen ja sanoi: \"Minä näin Timnassa naisen, filistealaisten tyttäriä; ottakaa hänet nyt minulle vaimoksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Hänen isänsä ja äitinsä sanoivat hänelle: \"Eikö ole yhtään naista veljiesi tyttärien joukossa ja minun koko kansassani, kun aiot mennä ottamaan vaimon ympärileikkaamattomien filistealaisten joukosta?\" Mutta Simson sanoi isälleen: \"Ota hänet minulle, sillä hän on mieluinen minun silmissäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Mutta hänen isänsä ja äitinsä eivät tienneet, että se tuli Herralta, sillä hän etsi tilaisuutta filistealaisia vastaan. Filistealaiset näet hallitsivat siihen aikaan Israelia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Niin Simson meni isänsä ja äitinsä kanssa alas Timnaan. Mutta kun he saapuivat Timnan viinitarhoille, niin katso, nuori leijona tuli kiljuen häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Silloin Herran henki tuli häneen, niin että hän repäisi sen, niinkuin olisi reväissyt vohlan, sulin käsin. Eikä hän ilmoittanut isälleen eikä äidilleen, mitä oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Sitten hän meni sinne ja puhutteli naista, ja tämä oli mieluinen Simsonin silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Ja kun hän jonkun ajan kuluttua palasi sinne ottaakseen hänet, poikkesi hän katsomaan leijonan raatoa, ja katso, leijonan ruumiissa oli mehiläisparvi ja hunajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Ja hän kaapi hunajan kouriinsa ja kulki edelleen ja söi sitä. Niin hän tuli isänsä ja äitinsä luo ja antoi heille, ja he söivät. Mutta hän ei sanonut heille, että oli kaapinut hunajan leijonan ruumiista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Sitten hänen isänsä meni naisen luo, ja Simson laittoi siellä pidot, sillä niin oli nuorten miesten tapa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Mutta kun he näkivät hänet, valitsivat he kolmekymmentä sulhaspoikaa olemaan hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Niin Simson sanoi heille: \"Minä panen teille arvoituksen; jos selitätte sen minulle seitsemän pitopäivän kuluessa ja arvaatte oikein, niin minä annan teille kolmekymmentä aivinapaitaa ja kolmekymmentä juhlapukua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Mutta ellette voi sitä minulle selittää, niin te annatte minulle kolmekymmentä aivinapaitaa ja kolmekymmentä juhlapukua.\" Ja he sanoivat hänelle: \"Lausu arvoituksesi, että saamme sen kuulla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Silloin hän sanoi heille: \"Lähti syötävä syömäristä, lähti väkevästä makea\". Mutta he eivät voineet kolmeen päivään selittää arvoitusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Seitsemäntenä päivänä he sanoivat Simsonin vaimolle: \"Viekoittele miehesi selittämään meille arvoitus, muuten me poltamme sinut ja sinun isäsi talon tulella. Oletteko kutsuneet meidät tänne köyhdyttääksenne meitä, vai kuinka?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Niin Simsonin vaimo ahdisti häntä itkullaan ja sanoi: \"Sinähän vihaat minua etkä rakasta; sinä olet pannut arvoituksen minun kansalaisilleni etkä selitä sitä minulle\". Mutta hän vastasi hänelle: \"En ole selittänyt sitä edes isälleni enkä äidilleni, sinulleko sen selittäisin!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Niin hän ahdisti häntä itkullaan ne seitsemän päivää, jotka heidän pitonsa kestivät. Mutta seitsemäntenä päivänä Simson selitti hänelle, koska vaimo häntä ahdisti. Ja vaimo selitti arvoituksen kansalaisilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Niin kaupungin miehet sanoivat hänelle seitsemäntenä päivänä, ennenkuin aurinko laski: \"Mikä on makeampaa kuin hunaja, ja mikä leijonaa väkevämpi?\" Hän vastasi heille: \"Ellette olisi kyntäneet minun vasikallani, ette olisi arvoitustani arvanneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Silloin Herran Henki tuli häneen, ja hän meni Askeloniin, löi siellä kuoliaaksi kolmekymmentä miestä, otti heiltä vaatteet ja antoi juhlapuvut arvoituksen selittäjille. Ja hänen vihansa syttyi, ja hän meni isänsä kotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Mutta Simsonin vaimo joutui sille sulhaspojista, joka oli ollut yljän ystävänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Jonkun ajan kuluttua, nisunleikkuuaikana, tuli Simson katsomaan vaimoansa, tuomisinaan vohla, ja sanoi: \"Minä menen vaimoni luo sisähuoneeseen\". Mutta tämän isä ei sallinut hänen mennä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'vaan sanoi: \"Minä tosiaankin luulin, että olit ruvennut vihaamaan häntä, ja annoin hänet sinun sulhaspojallesi. Mutta onhan hänen nuorempi sisarensa häntä kauniimpi, sinä saat hänet toisen sijaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Mutta Simson vastasi heille: \"Nyt minä en tule syynalaiseksi filistealaisista, vaikka teenkin heille pahaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Niin Simson meni ja pyydysti kolmesataa kettua. Ja hän otti tulisoihtuja, sitoi aina kaksi häntää yhteen ja asetti tulisoihdun kunkin häntäparin väliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Sitten hän sytytti tulisoihdut ja päästi ketut menemään filistealaisten viljapeltoihin; näin hän sytytti palamaan sekä kuhilaat että kasvavan viljan, viinitarhat ja öljypuut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Niin filistealaiset kysyivät: \"Kuka tämän on tehnyt?\" Vastattiin: \"Simson, timnalaisen vävy, koska tämä otti hänen vaimonsa ja antoi sen hänen sulhaspojalleen\". Niin filistealaiset menivät ja polttivat sekä vaimon että hänen isänsä tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Mutta Simson sanoi heille: \"Koska te näin teette, niin totisesti minä en lakkaa, ennenkuin olen kostanut teille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Ja hän pieksi heitä pahasti kupeisiin jos kinttuihinkin. Sitten hän meni ja asettui asumaan Eetamin kallioluolaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Silloin filistealaiset lähtivät liikkeelle, leiriytyivät Juudaan ja levittäytyivät Lehin tienoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Ja Juudan miehet kysyivät: \"Miksi te olette tulleet meitä vastaan?\" He vastasivat: \"Me olemme tulleet sitomaan Simsonin tehdäksemme hänelle, niinkuin hän teki meille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Niin kolmetuhatta miestä Juudasta meni Eetamin kallioluolalle, ja he sanoivat Simsonille: \"Etkö tiedä, että filistealaiset hallitsevat meitä; mitä oletkaan meille tehnyt!\" Hän vastasi heille: \"Niinkuin he tekivät minulle, niin minäkin tein heille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'He sanoivat hänelle: \"Me tulimme sitomaan sinut antaaksemme sinut filistealaisten käsiin\". Mutta Simson sanoi heille: \"Vannokaa minulle, ettette itse lyö minua kuoliaaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Niin he vastasivat hänelle sanoen: \"Emme lyö; me ainoastaan sidomme sinut ja annamme sinut heidän käsiinsä, mutta emme sinua surmaa\". Ja he sitoivat hänet kahdella uudella köydellä ja veivät hänet pois kalliolta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Kun hän saapui Lehiin, niin filistealaiset riensivät riemuhuudoin häntä vastaan. Silloin Herran henki tuli häneen, ja samalla köydet hänen käsivarsissaan olivat kuin tulen polttamat aivinalangat, ja hänen siteensä sulivat pois hänen käsistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Ja hän huomasi tuoreen aasinleukaluun, ojensi kätensä, otti sen ja löi sillä kuoliaaksi tuhat miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Ja Simson sanoi: \"Aasinleukaluulla minä löin heitä läjään, löin kahteen, aasinleukaluulla löin heitä tuhannen miestä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Sen sanottuaan hän heitti leukaluun kädestänsä. Niin sen paikan nimeksi tuli Raamat-Lehi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Mutta kun hän oli kovin janoissaan, niin hän huusi Herraa ja sanoi: \"Sinä annoit palvelijasi käden kautta tämän suuren voiton; ja nyt minä kuolen janoon ja joudun ympärileikkaamattomien käsiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Silloin Jumala avasi hampaankolon leukaluussa, ja siitä vuoti vettä; hän joi, ja hänen henkensä elpyi, ja hän virkistyi. Siitä lähde sai nimekseen Een-Hakkore; se on vielä tänäkin päivänä Lehissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Ja hän oli filistealaisten aikana tuomarina Israelissa kaksikymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Niin Simson meni Gassaan, ja hän näki siellä porton ja meni sen luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Kun gassalaisille kerrottiin, että Simson oli tullut sinne, niin he piirittivät hänet ja väijyivät häntä koko yön kaupungin portilla. Mutta he olivat hiljaa koko yön, ajatellen: \"Kun aamu valkenee, surmaamme hänet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Ja Simson makasi siellä puoliyöhön asti. Mutta puoliyön aikana hän nousi, tarttui kaupungin portin oviin ja molempiin pihtipieliin, nosti ne salpoineen paikaltansa, asetti hartioilleen ja vei ne sen vuoren laelle, joka on vastapäätä Hebronia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Sen jälkeen hän rakastui erääseen Soorekin laaksossa asuvaan naiseen, jonka nimi oli Delila.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Niin filistealaisten ruhtinaat tulivat naisen luo ja sanoivat hänelle: \"Viekoittele hänet ja ota selko, missä hänen suuri voimansa on ja miten voisimme voittaa hänet, että saisimme hänet sidotuksi ja masennetuksi; niin me annamme sinulle kukin tuhat ja sata hopeasekeliä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Silloin Delila sanoi Simsonille: \"Ilmaise minulle, missä sinun suuri voimasi on ja miten sinut voidaan sitoa ja masentaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Simson vastasi hänelle: \"Jos minut sidotaan seitsemällä tuoreella jänteellä, jotka eivät ole kuivuneet, niin minä tulen heikoksi ja olen niinkuin muutkin ihmiset\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Niin filistealaisten ruhtinaat toivat naiselle seitsemän tuoretta jännettä, jotka eivät olleet kuivuneet, ja hän sitoi hänet niillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Mutta sisähuoneessa hänellä istui väijyjiä. Ja hän sanoi hänelle: \"Filistealaiset ovat kimpussasi, Simson!\" Silloin tämä katkaisi jänteet, niinkuin katkeaa tulen kärventämä rohdinlanka. Ei siis päästy hänen voimansa perille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Ja Delila sanoi Simsonille: \"Katso, sinä olet pettänyt minut ja valhetellut minulle. Ilmaise nyt minulle, miten sinut voidaan sitoa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Niin hän sanoi hänelle: \"Jos minut sidotaan uusilla köysillä, joilla ei ole tehty työtä, niin minä tulen heikoksi ja olen niinkuin muutkin ihmiset\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Niin Delila otti uudet köydet, sitoi hänet niillä ja sanoi hänelle: \"Filistealaiset ovat kimpussasi, Simson!\" Ja sisähuoneessa istui väijyjiä. Mutta hän katkaisi ne käsivarsistaan niinkuin langan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Niin Delila sanoi Simsonille: \"Sinä olet tähän asti minua pettänyt ja valhetellut minulle; ilmaise minulle, miten sinut voidaan sitoa\". Niin hän vastasi hänelle: \"Jos kudot minun pääni seitsemän palmikkoa kankaan loimiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Ja hän löi ne lujaan iskulastalla. Sitten hän sanoi hänelle: \"Filistealaiset ovat kimpussasi, Simson!\" Kun hän heräsi unestansa, repäisi hän irti iskulastan ja loimet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Niin nainen sanoi hänelle: \"Kuinka sinä saatat sanoa: \'Minä rakastan sinua\', vaikka sydämesi ei ole minun kanssani? Jo kolme kertaa olet pettänyt minut etkä ole minulle ilmaissut, missä sinun suuri voimasi on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Ja kun hän joka päivä ahdisti häntä sanoillansa ja vaivasi häntä, niin hän kiusautui kuollakseen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'ja paljasti hänelle koko sydämensä ja sanoi hänelle: \"Ei ole partaveitsi minun päätäni koskettanut, sillä minä olen Jumalan nasiiri äitini kohdusta asti; jos minun hiukseni ajetaan, niin voimani poistuu minusta, ja minä tulen heikoksi ja olen niinkuin kaikki muutkin ihmiset\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Kun Delila huomasi, että hän oli paljastanut hänelle koko sydämensä, niin hän lähetti kutsumaan filistealaisten ruhtinaat sanoen: \"Nyt tulkaa, sillä hän on paljastanut minulle koko sydämensä\". Niin filistealaisten ruhtinaat tulivat hänen luoksensa tuoden mukanaan rahat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Ja hän nukutti hänet polvilleen ja kutsui miehen, joka leikkasi hänen päänsä seitsemän palmikkoa. Niin hän alkoi saada hänet masennetuksi, ja hänen voimansa poistui hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Ja Delila sanoi: \"Filistealaiset ovat kimpussasi, Simson!\" Kun hän heräsi unestaan, niin hän ajatteli: \"Kyllä minä selviydyn niinkuin aina ennenkin ja pudistan itseni vapaaksi\". Eikä hän tiennyt, että Herra oli poistunut hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Silloin filistealaiset ottivat hänet kiinni ja puhkaisivat hänen silmänsä. Ja he veivät hänet Gassaan ja kytkivät hänet vaskikahleisiin, ja hänen täytyi jauhaa vankilassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Mutta hiukset rupesivat jälleen kasvamaan hänen päähänsä sen jälkeen, kuin ne olivat ajetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Niin filistealaisten ruhtinaat kokoontuivat uhraamaan suurta uhria jumalalleen Daagonille ja iloa pitämään, sillä he sanoivat: \"Meidän jumalamme on antanut vihollisemme Simsonin meidän käsiimme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Kun kansa näki hänet, niin he ylistivät jumalaansa, sillä he sanoivat: \"Meidän jumalamme on antanut käsiimme vihollisemme, maamme hävittäjän, sen, joka surmasi meistä niin monta\". 16:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Ja kun heidän sydämensä olivat tulleet iloisiksi, niin he sanoivat: \"Noutakaa Simson huvittamaan meitä\". Niin Simson noudettiin vankilasta huvittamaan heitä. Ja he asettivat hänet seisomaan pylvästen väliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Silloin Simson sanoi palvelijalle, joka piti kiinni hänen kädestään: \"Päästä minut tunnustelemaan pylväitä, joiden varassa rakennus on, nojatakseni niihin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Mutta huone oli täynnä miehiä ja naisia; myöskin kaikki filistealaisten ruhtinaat olivat siellä, ja katolla oli noin kolmetuhatta miestä ja naista katselemassa, kuinka Simson heitä huvitti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Silloin Simson huusi Herraa ja sanoi: \"Herra, Herra, muista minua ja vahvista minua ainoastaan tämä kerta, oi Jumala, niin että saisin filistealaisille yhdellä kertaa kostetuksi molemmat silmäni!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Sitten Simson kiersi käsivartensa molempien keskipylväiden ympäri, joiden varassa rakennus oli, toisen ympäri oikean ja toisen ympäri vasemman käsivartensa, ja painautui niitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Ja Simson sanoi: \"Menköön oma henkeni yhdessä filistealaisten kanssa!\" Ja hän taivuttautui eteenpäin niin rajusti, että rakennus luhistui ruhtinasten ja kaiken siinä olevan kansan päälle. Ja kuolleita, jotka hän surmasi kuollessaan, oli enemmän kuin niitä, jotka hän oli surmannut eläessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Niin hänen veljensä ja koko hänen isänsä perhe menivät ja ottivat hänet ja veivät ja hautasivat hänet Soran ja Estaolin välille, hänen isänsä Maanoahin hautaan. Hän oli ollut tuomarina Israelissa kaksikymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Efraimin vuoristossa oli mies, nimeltä Miika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Hän sanoi äidillensä: \"Ne tuhat ja sata hopeasekeliä, jotka sinulta otettiin ja joiden tähden sinä lausuit vannotuksen minunkin kuulteni, katso, ne rahat ovat minulla; minä ne otin\". Silloin sanoi hänen äitinsä: \"Herra siunatkoon sinua, poikani!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Niin hän antoi takaisin äidilleen ne tuhat ja sata hopeasekeliä. Mutta hänen äitinsä sanoi: \"Minä pyhitän nämä rahat Herralle ja luovutan ne pojalleni veistetyn ja valetun jumalankuvan teettämistä varten. Nyt minä annan ne sinulle takaisin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Mutta hän antoi rahat takaisin äidilleen. Ja hänen äitinsä otti kaksisataa hopeasekeliä ja antoi ne kultasepälle, joka niistä teki veistetyn ja valetun jumalankuvan. Se oli sitten Miikan talossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Sillä miehellä, Miikalla, oli siis jumalanhuone, ja hän teetti kasukan ja kotijumalien kuvia ja asetti yhden pojistaan itsellensä papiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'Siihen aikaan ei ollut kuningasta Israelissa, ja jokainen teki sitä, mikä hänen omasta mielestään oli oikein.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Juudan Beetlehemissä oli nuori mies, Juudan sukukuntaa; hän oli leeviläinen ja asui siellä muukalaisena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Tämä mies lähti siitä kaupungista, Juudan Beetlehemistä, asuaksensa muukalaisena, missä vain sopisi; ja vaeltaessaan tietänsä hän tuli Efraimin vuoristoon, Miikan talolle asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Miika kysyi häneltä: \"Mistä sinä tulet?\" Hän vastasi: \"Minä olen leeviläinen Juudan Beetlehemistä ja vaellan asuakseni muukalaisena, missä vain sopii\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Miika sanoi hänelle: \"Asetu minun luokseni ja tule minun isäkseni ja papikseni, niin minä annan sinulle vuosittain kymmenen hopeasekeliä ja vaatetuksen ja elatuksesi\". Niin leeviläinen tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Ja leeviläinen suostui asettumaan sen miehen luo, ja tämä piti sitä nuorta miestä kuin omaa poikaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Miika asetti leeviläisen virkaan, ja nuoresta miehestä tuli hänen pappinsa, ja hän jäi Miikan taloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Ja Miika sanoi: \"Nyt minä tiedän, että Herra tekee minulle hyvää, sillä minulla on pappina leeviläinen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'Siihen aikaan ei ollut kuningasta Israelissa; ja siihen aikaan daanilaisten sukukunta etsi itsellensä perintöosaa asuttavaksensa, sillä siihen päivään asti se ei ollut saanut perintöosaa Israelin sukukuntien kesken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Ja daanilaiset lähettivät sukukuntansa keskuudesta viisi miestä, sotakuntoisia miehiä Sorasta ja Estaolista, vakoilemaan maata ja tutkimaan sitä; he sanoivat heille: \"Menkää tutkimaan maata\". Ja nämä tulivat Efraimin vuoristoon, Miikan talolle asti, ja yöpyivät sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Ollessaan Miikan talon luona he tunsivat nuoren miehen hänen äänestään leeviläiseksi; niin he poikkesivat sinne ja kysyivät häneltä: \"Kuka on tuonut sinut tänne? Mitä sinä täällä toimitat, ja mitä sinulla on täällä tekemistä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Hän vastasi heille: \"Niin ja niin teki Miika minulle ja palkkasi minut papiksensa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Ja he sanoivat hänelle: \"Kysy Jumalalta, että saisimme tietää, onnistuuko matka, jolla me olemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Pappi vastasi heille: \"Menkää rauhassa. Matka, jolla olette, tapahtuu Herran edessä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Niin ne viisi miestä jatkoivat matkaansa ja tulivat Laikseen; ja he näkivät, että sikäläinen kansa asui huoleti siidonilaisten tavoin, rauhassa ja huoletonna; eikä kukaan tehnyt vahinkoa siinä maassa rikkauksia anastamalla. Myöskin olivat he kaukana siidonilaisista eivätkä olleet tekemisissä muitten ihmisten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Ja he tulivat veljiensä luo Soraan ja Estaoliin, ja heidän veljensä kysyivät heiltä: \"Mitä kuuluu?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'He sanoivat: \"Nouskaa, lähtekäämme heitä vastaan. Sillä me olemme katselleet maata, ja katso, se on hyvin hyvä. Ja tekö jäisitte toimettomiksi! Älkää viivytelkö, lähtekää liikkeelle, menkää sinne ja ottakaa omaksenne se maa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Kun tulette sinne, tulette huoletonna elävän kansan luo, ja maa on tilava joka suuntaan. Niin, Jumala antaa sen teidän käsiinne, paikan, jossa ei ole puutetta mistään, mitä maan päällä on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Niin lähti sieltä liikkeelle, daanilaisten sukukunnasta, Sorasta ja Estaolista, kuusisataa sota-aseilla varustettua miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'He nousivat Juudan Kirjat-Jearimiin ja leiriytyivät sinne. Sentähden kutsutaan sitä paikkaa vielä tänäkin päivänä \"Daanin leiriksi\"; se on Kirjat-Jearimin takana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Sieltä he kulkivat Efraimin vuoristoon ja tulivat Miikan talolle asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Niin ne viisi miestä, jotka olivat käyneet vakoilemassa Laiksen maata, rupesivat puhumaan ja sanoivat veljillensä: \"Tiedättekö, että noissa huoneissa on kasukka ja kotijumalia sekä veistetty ja valettu jumalankuva? Miettikää siis, mitä teidän on tehtävä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Niin he poikkesivat sinne ja tulivat sen nuoren leeviläisen miehen asunnolle, Miikan taloon, ja tervehtivät häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Ja ne kuusisataa sota-aseilla varustettua daanilaista asettuivat portin oven eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Ja ne viisi miestä, jotka olivat käyneet vakoilemassa maata, nousivat taloon, menivät sisään ja ottivat veistetyn jumalankuvan ja kasukan ja kotijumalat ja valetun jumalankuvan, mutta pappi ja ne kuusisataa sota-aseilla varustettua miestä seisoivat portin oven edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Kun he menivät Miikan taloon ja ottivat veistetyn jumalankuvan ja kasukan ja kotijumalat ja valetun jumalankuvan, niin pappi kysyi heiltä: \"Mitä te teette?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'He vastasivat hänelle: \"Vaikene, pidä suusi kiinni ja lähde meidän kanssamme ja tule meidän isäksemme ja papiksemme. Onko parempi ollaksesi pappina yhden miehen talossa kuin Israelin heimon ja sukukunnan pappina?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Silloin pappi tuli hyville mielin, ja hän otti kasukan ja kotijumalat ja veistetyn jumalankuvan ja meni väen keskeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Sitten he kääntyivät jatkamaan matkaansa ja panivat vaimot ja lapset sekä karjan ja kuormaston kulkemaan edellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'He olivat ehtineet vähän matkaa Miikan talosta, kun Miikan talon lähitalojen miehet kutsuttiin koolle, ja he pääsivät daanilaisten kintereille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Ja he huusivat daanilaisille; nämä kääntyivät ja kysyivät Miikalta: \"Mikä sinun on, kun väkesi on noin kutsuttu koolle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Hän vastasi: \"Te olette ottaneet minun jumalani, jotka minä olen teettänyt, ja papin, ja menette matkoihinne. Mitä on minulla enää jäljellä? Ja kuinka te vielä kysytte minulta: \'Mikä sinun on\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Mutta daanilaiset sanoivat hänelle: \"Herkeä huutamasta meille, muuten miehet ärtyvät ja käyvät kimppuunne, ja te menetätte henkenne, sekä sinä että sinun perheesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Niin daanilaiset jatkoivat matkaansa, ja kun Miika näki, että he olivat häntä voimakkaammat, kääntyi hän ja palasi kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Otettuaan siis sen, minkä Miika oli teettänyt, sekä hänen pappinsa, hyökkäsivät he Laiksen rauhassa ja huoletonna elävän kansan kimppuun ja surmasivat heidät miekan terällä ja polttivat kaupungin tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Eikä kukaan tullut avuksi, sillä se oli kaukana Siidonista eivätkä he olleet tekemisissä muitten ihmisten kanssa; se oli Beet-Rehobin tasangolla. Daanilaiset rakensivat kaupungin uudestaan ja asettuivat siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Ja he antoivat kaupungille nimen Daan, isänsä Daanin nimen mukaan, hänen, joka oli Israelille syntynyt; mutta ennen oli kaupungin nimi ollut Lais.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Sitten daanilaiset pystyttivät itsellensä sen veistetyn jumalankuvan; ja Joonatan, Manassen pojan Geersomin poika, ja hänen poikansa olivat daanilaisten sukukunnan pappeina, kunnes maan väestö vietiin pakkosiirtolaisuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'He pystyttivät itsellensä sen veistetyn jumalankuvan, jonka Miika oli teettänyt, ja se oli siinä koko ajan, minkä Jumalan huone oli Siilossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Siihen aikaan, kun ei ollut kuningasta Israelissa, asui eräs leeviläinen mies muukalaisena Efraimin vuoriston perukoilla, ja hän otti itselleen sivuvaimon Juudan Beetlehemistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Mutta hänen sivuvaimonsa oli hänelle uskoton ja meni hänen luotansa isänsä kotiin Juudan Beetlehemiin, ja hän oli siellä jonkun aikaa, neljä kuukautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Sitten hänen miehensä nousi ja lähti hänen jälkeensä viihdytelläkseen häntä ja palauttaakseen hänet luokseen; ja hänellä oli mukanaan palvelija ja aasipari. Ja nainen vei hänet isänsä kotiin; ja kun naisen isä näki hänet, riensi hän iloisena häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Ja hänen appensa, naisen isä, pidätteli häntä, niin että hän viipyi hänen luonaan kolme päivää; he söivät ja joivat ja olivat siellä yötä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Neljäntenä päivänä hän varhain aamulla nousi lähteäkseen; mutta naisen isä sanoi vävyllensä: \"Vahvista itseäsi leipäpalalla; sitten saatte lähteä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Niin he istuivat, söivät ja joivat molemmat yhdessä. Sitten naisen isä sanoi miehelle: \"Suostu jäämään yöksi, ja olkoon sydämesi iloinen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Mutta mies nousi lähteäksensä; silloin hänen appensa pyysi häntä pyytämällä, ja hän jäi sinne vielä yöksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Viidentenä päivänä hän varhain aamulla nousi lähteäksensä, mutta naisen isä sanoi hänelle: \"Vahvista itseäsi, ja viipykää iltapäivään asti\". Niin he söivät toistensa kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Ja mies nousi lähteäkseen sivuvaimonsa ja palvelijansa kanssa, mutta hänen appensa, naisen isä, sanoi hänelle: \"Katso, päivä kallistuu iltaan, jääkää yöksi; päivä on menemässä mailleen, jää tänne yöksi, ja olkoon sydämesi iloinen. Nouskaa huomenna varhain matkallenne, ja lähde sitten majallesi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Mutta mies ei tahtonut jäädä yöksi, vaan nousi ja lähti ja tuli Jebuksen, se on Jerusalemin, kohdalle, mukanaan satuloitu aasipari ja sivuvaimonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Kun he olivat Jebuksen luona ja päivä oli kohta laskemassa, sanoi palvelija isännälleen: \"Tule, poiketkaamme tuohon jebusilaisten kaupunkiin ja yöpykäämme sinne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Mutta hänen isäntänsä vastasi hänelle: \"Emme poikkea vieraitten kaupunkiin, jotka eivät ole israelilaisia, vaan menemme edelleen Gibeaan asti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Ja hän sanoi palvelijallensa: \"Tule, pyrkikäämme toiseen paikkaan, yöpykäämme Gibeaan tai Raamaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Niin he jatkoivat matkaansa, ja aurinko laski heiltä lähellä Gibeaa, joka on Benjaminissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Ja he poikkesivat Gibeaan yöpyäkseen sinne. Hän tuli sinne ja istuutui kaupungin torille, mutta ei kukaan ottanut heitä yöksi huoneeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Ja katso, illalla tuli vanha mies työstään kedolta; hän oli Efraimin vuoristosta ja asui muukalaisena Gibeassa. Mutta sen paikkakunnan miehet olivat benjaminilaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Ja kun hän nosti silmänsä, näki hän matkamiehen kaupungin torilla. Silloin vanha mies sanoi: \"Minne olet matkalla ja mistä tulet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Hän vastasi hänelle sanoen: \"Me olemme matkalla Juudan Beetlehemistä Efraimin vuoriston perukoille; sieltä minä olen kotoisin ja olen käynyt Juudan Beetlehemissä asti. Olen matkalla Herran huoneeseen, mutta ei kukaan ota minua huoneeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Meillä on sekä olkia että muuta rehua aaseillemme, niin myös leipää ja viiniä minulle itselleni ja palvelijattarellesi ja nuorelle miehelle, joka on palvelijasi kanssa, niin ettei meiltä mitään puutu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Vanha mies sanoi: \"Rauha sinulle! Minun asiani on, jos sinulta jotakin puuttuisi. Älä vain jää yöksi tähän torille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Ja hän vei hänet taloonsa ja teki aaseille appeen. Ja he pesivät jalkansa ja söivät ja joivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Ja kun he olivat ilahduttamassa sydäntänsä, niin katso, kaupungin miehet, kelvottomat miehet, piirittivät talon, kolkuttivat ovelle ja sanoivat vanhalle miehelle, talon isännälle, näin: \"Tuo tänne se mies, joka tuli sinun taloosi, ryhtyäksemme häneen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Mutta mies, talon isäntä, meni ulos heidän luokseen ja sanoi heille: \"Älkää, veljeni, älkää tehkö niin pahoin! Kun kerran tämä mies on tullut minun talooni, älkää tehkö sellaista häpeällistä tekoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Katso, täällä on minun tyttäreni, joka on neitsyt, ja tämän miehen sivuvaimo. Minä tuon heidät tänne; tehkää heille väkivaltaa, tehkää heille, mitä tahdotte, mutta tälle miehelle älkää tehkö sellaista häpeällistä tekoa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Mutta miehet eivät tahtoneet häntä kuulla. Silloin mies tarttui sivuvaimoonsa ja vei hänet heidän luoksensa kadulle, ja he yhtyivät häneen ja pitelivät häntä pahoin koko yön aina aamuun asti, ja vasta aamun sarastaessa he hänet päästivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Ja päivän koittaessa vaimo tuli ja kaatui sen miehen talon oven eteen, jonka talossa hänen isäntänsä oli, ja makasi siinä, kunnes päivä valkeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Kun hänen isäntänsä aamulla nousi ja avasi talon oven ja tuli ulos lähteäksensä matkalle, niin katso, hänen sivuvaimonsa makasi talon oven edessä, kädet kynnyksellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Hän sanoi hänelle: \"Nouse ja lähtekäämme!\" Mutta vastausta ei tullut. Silloin mies nosti hänet aasin selkään, nousi ja lähti kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Mutta kotiin tultuaan hän otti veitsen, tarttui sivuvaimoonsa ja paloitteli hänet luineen kaikkineen kahdeksitoista kappaleeksi ja lähetti ne kaikkialle Israelin alueelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Ja jokainen, joka sen näki, sanoi: \"Mitään sellaista ei ole tapahtunut eikä nähty siitä päivästä lähtien, jona israelilaiset tulivat Egyptin maasta, aina tähän päivään saakka. Harkitkaa tätä, neuvotelkaa ja puhukaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Ja kaikki israelilaiset lähtivät liikkeelle, ja kansa kokoontui yhtenä miehenä Daanista aina Beersebaan saakka, niin myös Gileadin maasta, Herran eteen Mispaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Ja koko kansan päämiehet ja kaikki Israelin sukukunnat astuivat esiin Jumalan kansan seurakunnassa: neljäsataa tuhatta miekalla varustettua jalkamiestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Ja benjaminilaiset saivat kuulla, että israelilaiset olivat menneet Mispaan. Ja israelilaiset sanoivat: \"Kertokaa, kuinka tämä pahateko tapahtui\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Niin se leeviläinen mies, murhatun vaimon mies, vastasi ja sanoi: \"Minä ja minun sivuvaimoni olimme tulleet Benjaminin Gibeaan yöpyäksemme sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Silloin Gibean miehet nousivat minua vastaan ja piirittivät yöllä talon, jossa minä olin. Minut he aikoivat tappaa, minun sivuvaimolleni he tekivät väkivaltaa, niin että hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Sitten minä tartuin sivuvaimooni ja paloittelin hänet ja lähetin kappaleet kaikkialle Israelin perintömaahan, koska he olivat tehneet ilkityön ja häpeällisen teon Israelissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Katso, nyt olette kaikki tässä, te israelilaiset. Keskustelkaa ja neuvotelkaa tässä paikassa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Silloin nousi kaikki kansa yhtenä miehenä ja sanoi: \"Älköön meistä kukaan menkö majallensa, älköön kukaan poistuko kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Tämän me nyt teemme Gibealle: me menemme sitä vastaan arvan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Ja me otamme kymmenen miestä sadasta, Israelin kaikista sukukunnista, ja sata tuhannesta ja tuhat kymmenestätuhannesta, hankkimaan muonaa kansalle, kun se menee kostamaan Benjaminin Gibealle sen häpeällisen teon, minkä se on tehnyt Israelissa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Niin kokoontuivat kaikki Israelin miehet kaupunkia vastaan, kuin yhdeksi mieheksi yhtyneinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Ja Israelin sukukunnat lähettivät miehiä kaikkiin Benjaminin sukuihin sanomaan: \"Mikä pahateko onkaan teidän keskuudessanne tehty!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Luovuttakaa nyt ne Gibean kelvottomat miehet, surmataksemme heidät ja poistaaksemme pahan Israelista.\" Mutta benjaminilaiset eivät tahtoneet kuulla veljiänsä, israelilaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Niin benjaminilaiset kokoontuivat kaupungeistaan Gibeaan lähteäksensä sotaan israelilaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Sinä päivänä pidettiin benjaminilaisten katselmus, ja heitä oli muista kaupungeista kaksikymmentäkuusi tuhatta miekkamiestä, paitsi Gibean asukkaita, joita katselmuksessa oli seitsemänsataa valiomiestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Kaikesta tästä väestä oli seitsemänsataa valiomiestä vasenkätistä; jokainen näistä osasi lingota kiven hiuskarvalleen, hairahtumatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Myös pidettiin Israelin miesten katselmus, ja heitä oli, paitsi benjaminilaisia, neljäsataa tuhatta miekkamiestä, kaikki sotilaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Ja he nousivat ja lähtivät Beeteliin ja kysyivät Jumalalta. Israelilaiset sanoivat: \"Kenen meistä on ensiksi lähdettävä taistelemaan benjaminilaisia vastaan?\" Herra vastasi: \"Juuda ensiksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Ja israelilaiset lähtivät liikkeelle seuraavana aamuna ja asettuivat leiriin Gibean edustalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Ja Israelin miehet lähtivät taistelemaan Benjaminia vastaan, ja Israelin miehet asettuivat sotarintaan heitä vastaan Gibean edustalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Mutta benjaminilaiset ryntäsivät ulos Gibeasta ja kaatoivat sinä päivänä Israelista kaksikymmentäkaksi tuhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Mutta kansa, Israelin miehet, rohkaisivat mielensä ja asettuivat jälleen sotarintaan samalle paikalle, mihin olivat asettuneet ensimmäisenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Sillä kun israelilaiset menivät ja itkivät Herran edessä iltaan asti ja kysyivät Herralta sanoen: \"Onko minun vielä ryhdyttävä taisteluun veljiäni, benjaminilaisia, vastaan?\" niin Herra vastasi: \"Menkää heitä vastaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Ja toisena päivänä israelilaiset lähenivät benjaminilaisia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'niin benjaminilaiset toisena päivänä ryntäsivät Gibeasta heitä vastaan ja kaatoivat israelilaisia vielä kahdeksantoista tuhatta miestä, kaikki miekkamiehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Silloin kaikki israelilaiset, koko kansa, lähtivät ja tulivat Beeteliin ja itkivät ja istuivat siellä Herran edessä ja paastosivat sen päivän aina iltaan asti; ja he uhrasivat polttouhreja ja yhteysuhreja Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Ja israelilaiset kysyivät Herralta-sillä Jumalan liitonarkki oli siihen aikaan siellä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'ja Piinehas, Aaronin pojan Eleasarin poika, seisoi siihen aikaan sen edessä-ja sanoivat: \"Onko minun vielä lähdettävä taisteluun veljiäni, benjaminilaisia, vastaan, vai onko minun siitä luovuttava?\" Herra vastasi: \"Lähtekää; sillä huomenna minä annan heidät sinun käsiisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Silloin Israel asetti väijytyksiä Gibean ympärille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Ja israelilaiset menivät kolmantena päivänä benjaminilaisia vastaan ja asettuivat sotarintaan Gibeaa vastaan niinkuin edellisilläkin kerroilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Ja benjaminilaiset ryntäsivät ulos kansaa vastaan, mutta tulivat eristetyiksi kaupungista; ja niinkuin edellisilläkin kerroilla he aluksi saivat lyödyksi kansaa kuoliaaksi niillä valtateillä, joista toinen vie Beeteliin, toinen kedon yli Gibeaan, noin kolmekymmentä Israelin miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Ja benjaminilaiset sanoivat: \"Me voitimme heidät nyt niinkuin ennenkin\"; mutta israelilaiset sanoivat: \"Paetkaamme ja eristäkäämme heidät kaupungista valtateille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Niin kaikki Israelin miehet nousivat, kukin paikaltaan, ja asettuivat sotarintaan Baal-Taamariin; ja väijyksissä oleva Israelin joukko syöksyi esiin paikaltaan Geban aukealta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Niin tuli kymmenentuhatta valiomiestä koko Israelista Gibean edustalle, ja syntyi ankara taistelu; eivätkä he huomanneet, että onnettomuus oli kohtaamassa heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Ja Herra antoi Israelin voittaa Benjaminin, ja israelilaiset kaatoivat sinä päivänä Benjaminista kaksikymmentäviisi tuhatta ja sata miestä, kaikki miekkamiehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Nyt benjaminilaiset näkivät olevansa voitetut. Mutta Israelin miehet väistyivät benjaminilaisten tieltä, sillä he luottivat väijytykseen, jonka olivat asettaneet Gibeaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Silloin väijyksissä ollut joukko riensi ja karkasi Gibeaan; väijyksissä ollut joukko meni ja surmasi kaikki kaupungin asukkaat miekan terällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Ja Israelin miehet olivat sopineet väijyksissä olevan joukon kanssa, että se panisi sakean savupilven nousemaan kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Kun siis Israelin miehet olivat kääntyneet pakosalle taistelussa, ja kun Benjaminin miehet aluksi olivat lyöneet kuoliaaksi Israelin miehiä noin kolmekymmentä miestä ja sanoneet: \"Varmasti me voitamme heidät niinkuin ensimmäisessäkin taistelussa\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'niin alkoi pilvi, savupatsas, nousta kaupungista. Ja kun benjaminilaiset kääntyivät taaksepäin, niin katso, koko kaupunki nousi savuna taivasta kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Israelin miehet kääntyivät takaisin, mutta Benjaminin miehet kauhistuivat, sillä he näkivät, että onnettomuus oli kohdannut heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Ja he kääntyivät pakoon Israelin miesten edestä erämaan tielle, mutta sota seurasi heitä kintereillä; ja sikäläisten kaupunkien asukkaat kaatoivat heitä heidän keskeltänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'He saartoivat Benjaminin, ajoivat heitä takaa ja tallasivat heitä maahan levähdyspaikassa ja aina Gibean kohdalle asti, auringonnousuun päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Niin kaatui Benjaminista kahdeksantoistatuhatta miestä, kaikki sotakuntoisia miehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'He kääntyivät ja pakenivat erämaahan päin, Rimmonin kalliolle; mutta israelilaiset tekivät heistä valtateillä vielä jälkikorjuun, surmaten viisituhatta miestä, ja seurasivat heitä kintereillä aina Gideomiin asti ja surmasivat heitä kaksituhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Kaikkiaan oli niitä, jotka sinä päivänä kaatuivat Benjaminista, kaksikymmentäviisi tuhatta miekkamiestä, kaikki sotakuntoisia miehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Ja heitä kääntyi pakoon erämaahan päin, Rimmonin kalliolle, kuusisataa miestä. Ja he jäivät Rimmonin kalliolle neljäksi kuukaudeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Mutta Israelin miehet palasivat takaisin benjaminilaisten luo ja surmasivat heidät miekan terällä, kaupungin sekä vahingoittumatta jääneet ihmiset että eläimet, kaiken, minkä tapasivat; myöskin pistivät he tuleen kaikki kaupungit, joihin tulivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Israelin miehet olivat vannoneet Mispassa ja sanoneet: \"Ei kukaan meistä anna tytärtään benjaminilaiselle vaimoksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Ja kansa tuli Beeteliin, ja he istuivat siellä aina iltaan asti Jumalan edessä, korottivat äänensä ja itkivät katkerasti');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'ja sanoivat: \"Miksi, oi Herra, Israelin Jumala, on Israelissa käynyt niin, että Israelista nyt puuttuu yksi sukukunta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Varhain seuraavana päivänä kansa nousi ja rakensi sinne alttarin ja uhrasi polttouhreja ja yhteysuhreja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Ja israelilaiset sanoivat: \"Onko yhdessäkään Israelin sukukunnassa ketään, joka ei ole tullut seurakunnan kanssa tänne Herran eteen?\" Sillä siitä, joka ei tulisi Herran luo Mispaan, oli vannottu ankara vala: \"Hän on kuolemalla rangaistava\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Ja israelilaisten tuli sääli veljeänsä Benjaminia, ja he sanoivat: \"Tänä päivänä on yksi sukukunta hakattu pois Israelista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Mitä meidän on tehtävä, että jäljelle jääneet saavat vaimoja? Sillä itse me olemme vannoneet Herran kautta, ettemme anna heille tyttäriämme vaimoiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Ja he kysyivät: \"Onko Israelin sukukunnissa ainoatakaan, joka ei ole tullut Herran eteen Mispaan?\" Ja katso, Gileadin Jaabeksesta ei ollut ketään tullut leiriin, seurakuntakokoukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Sillä kun kansasta pidettiin katselmus, niin katso, siellä ei ollut ketään Gileadin Jaabeksen asukkaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Niin kansa lähetti sinne kaksitoistatuhatta sotakuntoista miestä ja käski heitä sanoen: \"Menkää ja surmatkaa miekan terällä Gileadin Jaabeksen asukkaat vaimoineen ja lapsineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Tehkää näin: kaikki miehenpuolet ja kaikki naiset, jotka ovat yhtyneet mieheen, vihkikää tuhon omiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Ja Gileadin Jaabeksen asukkaista he löysivät neljäsataa nuorta naista, jotka olivat neitsyitä eivätkä olleet yhtyneet mieheen; ja he veivät nämä leiriin Siiloon, joka on Kanaanin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Sitten koko kansa lähetti sanansaattajia puhumaan benjaminilaisten kanssa, jotka olivat Rimmonin kalliolla, ja tarjosi heille rauhaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Silloin benjaminilaiset palasivat takaisin, ja heille annettiin ne naiset, jotka oli jätetty henkiin Gileadin Jaabeksen naisista. Mutta ne eivät riittäneet heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Niin kansan tuli sääli Benjaminia, koska Herra oli tehnyt aukon Israelin sukukuntiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Ja kansan vanhimmat sanoivat: \"Mitä meidän on tehtävä, että jäljelle jääneet saisivat vaimoja? Sillä ovathan naiset hävitetyt Benjaminista.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Ja he sanoivat: \"Pelastuneiden perintöomaisuus on jäävä Benjaminille, ettei yksikään sukukunta häviäisi Israelista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Mutta itse me emme voi antaa heille tyttäriämme vaimoiksi, sillä israelilaiset ovat vannoneet ja sanoneet: kirottu olkoon se, joka antaa vaimon benjaminilaiselle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Niin he sanoivat: \"Katso, joka vuosi vietetään Herran juhla Siilossa, joka on pohjoiseen päin Beetelistä, auringonnousuun päin siitä valtatiestä, joka vie Beetelistä Sikemiin, ja etelään päin Lebonasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Ja he käskivät benjaminilaisia sanoen: \"Menkää ja asettukaa väijyksiin viinitarhoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Kun näette Siilon tyttärien tulevan ulos karkeloimaan, niin rynnätkää viinitarhoista ja ryöstäkää jokainen itsellenne vaimo Siilon tyttäristä ja lähtekää Benjaminin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Ja kun heidän isänsä tai veljensä tulevat valittamaan meille, niin me sanomme heille: \'Lahjoittakaa heidät meille, sillä ei kukaan meistä ole ottanut sodassa vaimoa. Ettehän te ole itse antaneet niitä heille; muuten olisitte joutuneet vikapäiksi.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Benjaminilaiset tekivät niin ja ottivat lukumääränsä mukaan itselleen vaimoja karkeloivien joukosta, ryöstäen heidät. Sitten he palasivat perintöosaansa ja rakensivat uudestaan kaupungit ja asettuivat niihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Silloin israelilaisetkin vaelsivat sieltä, kukin sukukuntaansa ja sukuunsa, ja menivät sieltä kukin perintöosallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'Siihen aikaan ei ollut kuningasta Israelissa; jokainen teki sitä, mikä hänen omasta mielestään oli oikein.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'Siihen aikaan kun tuomarit hallitsivat, tuli nälänhätä maahan. Silloin muuan Juudan Beetlehemin mies lähti sieltä ja asettui vaimonsa ja kahden poikansa kanssa muukalaisena asumaan Mooabin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Miehen nimi oli Elimelek, hänen vaimonsa nimi oli Noomi ja hänen kahden poikansa nimet Mahlon ja Kiljon; he olivat efratilaisia Juudan Beetlehemistä. Niin he tulivat Mooabin maahan ja oleskelivat siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Ja Elimelek, Noomin mies, kuoli, ja Noomi jäi jälkeen kahden poikansa kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Nämä ottivat itselleen mooabilaiset vaimot; toisen nimi oli Orpa ja toisen nimi Ruut. Ja he asuivat siellä noin kymmenen vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Ja myös nuo molemmat, Mahlon ja Kiljon, kuolivat, niin että vaimo jäi yksin jälkeen kahdesta pojastaan ja miehestään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Silloin hän nousi miniöineen palataksensa takaisin Mooabin maasta, sillä hän oli kuullut Mooabin maassa, että Herra oli pitänyt kansastansa huolen ja antanut sille leipää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Niin hän lähti yhdessä molempien miniäinsä kanssa siitä paikasta, jossa oli oleskellut. Ja heidän tietä käydessään matkalla Juudan maahan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'sanoi Noomi molemmille miniöillensä: \"Menkää, palatkaa kumpikin äitinne kotiin. Herra tehköön teille laupeuden, niinkuin te olette vainajille ja minulle tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Herra suokoon, että saisitte turvan kumpikin miehenne kodissa.\" Ja hän suuteli heitä. Mutta he korottivat äänensä ja itkivät');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'ja sanoivat hänelle: \"Me seuraamme sinua sinun kansasi luo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Mutta Noomi vastasi: \"Kääntykää takaisin, tyttäreni; miksi te lähtisitte minun kanssani? Voinko minä enää saada poikia miehiksi teille?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Kääntykää takaisin, tyttäreni, menkää, sillä minä olen liian vanha joutuakseni miehelään. Vaikka ajattelisinkin: \'Minulla on vielä toivoa\', ja vaikka vielä tänä yönä joutuisin miehelään ja synnyttäisin poikia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'ette kai te kuitenkaan odottaisi, kunnes he kasvaisivat suuriksi, ette kai te kuitenkaan sulkeutuisi huoneeseen ja olisi miehelään menemättä. Ei, tyttäreni; minä olen hyvin murheissani teidän tähtenne, sillä Herran käsi on sattunut minuun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Niin he korottivat vielä äänensä ja itkivät. Silloin Orpa suuteli anoppiaan jäähyväisiksi, mutta Ruut riippui kiinni hänessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Ja Noomi sanoi: \"Katso, kälysi on kääntynyt takaisin oman kansansa ja jumalansa luo, käänny sinäkin kälysi kanssa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Mutta Ruut vastasi: \"Älä vaadi minua jättämään sinua ja kääntymään takaisin, pois sinun tyköäsi. Sillä mihin sinä menet, sinne minäkin menen, ja mihin sinä jäät, sinne minäkin jään; sinun kansasi on minun kansani, sinun Jumalasi on minun Jumalani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Missä sinä kuolet, siellä minäkin tahdon kuolla ja sinne tulla haudatuksi. Herra rangaiskoon minua nyt ja vasta, jos muu kuin kuolema erottaa meidät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Kun Noomi näki, että hän oli lujasti päättänyt seurata häntä, ei hän enää puhunut siitä hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'Niin he kulkivat molemmat yhdessä, kunnes tulivat Beetlehemiin. Ja kun he tulivat Beetlehemiin, joutui koko kaupunki liikkeelle heidän tähtensä, ja vaimot sanoivat: \"Onko tämä Noomi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Mutta hän vastasi heille: \"Älkää kutsuko minua Noomiksi, kutsukaa minua Maaraksi, sillä Kaikkivaltias on antanut minulle paljon katkerata murhetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Rikkaana minä lähdin, mutta tyhjänä Herra antaa minun palata. Miksi siis kutsutte minua Noomiksi, kun Herra on minua vastaan todistanut ja Kaikkivaltias on tuottanut minulle onnettomuutta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Niin Noomi palasi miniänsä, mooabilaisen Ruutin, kanssa, joka tuli Mooabin maasta; ja he saapuivat Beetlehemiin ohranleikkuun alussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Noomilla oli miehensä puolelta sukulainen, hyvin varakas mies, Elimelekin sukua, nimeltä Booas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'Ja mooabilainen Ruut sanoi Noomille: \"Anna minun mennä pellolle poimimaan tähkiä jonkun jäljessä, jonka silmien edessä saan armon\". Noomi vastasi hänelle: \"Mene, tyttäreni!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Niin hän lähti ja meni poimimaan eräälle pellolle leikkuuväen jäljessä; ja hänelle sattui niin, että se peltopalsta oli Booaan, joka oli Elimelekin sukua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'Ja katso, Booas tuli Beetlehemistä, ja hän sanoi leikkuuväelle: \"Herra olkoon teidän kanssanne!\" He vastasivat hänelle: \"Herra siunatkoon sinua!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Sitten Booas sanoi palvelijallensa, joka oli leikkuuväen päällysmiehenä: \"Kenen tuo nuori nainen on?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Palvelija, joka oli leikkuuväen päällysmiehenä, vastasi ja sanoi: \"Se on se nuori mooabitar, joka tuli Noomin mukana Mooabin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'Hän sanoi: \'Salli minun poimia ja koota tähkiä lyhteiden väliltä leikkuuväen jäljessä\'. Niin hän tuli ja on ahertanut aamusta varhain tähän saakka; vasta äsken hän hiukan levähti tuolla majassa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Niin Booas sanoi Ruutille: \"Kuules, tyttäreni! Älä mene muiden pelloille poimimaan äläkä lähde pois täältä, vaan pysyttele täällä minun palvelijattarieni mukana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Pidä silmällä, millä pellolla leikataan, ja kulje heidän jäljessään. Minä olen kieltänyt palvelijoitani koskemasta sinuun. Jos sinun tulee jano, niin mene astioille ja juo vettä, jota palvelijat ammentavat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Silloin Ruut heittäytyi kasvoilleen, kumartui maahan ja sanoi hänelle: \"Miten olen saanut armon sinun silmiesi edessä, niin että huolehdit minusta, vaikka olen vieras?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Booas vastasi ja sanoi hänelle: \"Minulle on kerrottu kaikki, mitä sinä olet tehnyt anopillesi miehesi kuoltua, kuinka jätit isäsi ja äitisi ja synnyinmaasi ja lähdit kansan luo, jota et ennen tuntenut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Herra palkitkoon sinulle tekosi; tulkoon sinulle täysi palkka Herralta, Israelin Jumalalta, jonka siipien alta olet tullut turvaa etsimään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'Ruut sanoi: \"Minä olen saanut armon sinun silmiesi edessä, herrani, sillä sinä olet lohduttanut minua ja puhutellut palvelijatartasi ystävällisesti, vaikka en ole yhdenkään sinun palvelijattaresi vertainen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'Ruoka-ajan tultua Booas sanoi hänelle: \"Käy tänne ruualle ja kasta palasesi hapanviiniin\". Niin Ruut istui leikkuuväen viereen; ja Booas pani hänen eteensä paahdettuja jyviä, niin että hän söi tarpeeksensa ja jäi tähteeksikin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Kun hän sitten nousi poimimaan, käski Booas palvelijoitaan sanoen: \"Hän saa poimia myöskin lyhteiden väliltä; ja te ette saa loukata häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Voittepa vetää sitomistakin joitakin tähkiä ja jättää ne hänen poimittavikseen; ja te ette saa nuhdella häntä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Niin Ruut poimi pellolla iltaan asti; sitten hän pui, mitä oli saanut poimituksi, ja siitä tuli noin eefa-mitan verta ohria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'Ja hän otti ne ja tuli kaupunkiin ja näytti anopillensa, mitä oli poiminut. Sen jälkeen Ruut otti esille tähteet ruuasta, josta oli syönyt tarpeekseen, ja antoi ne hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Silloin hänen anoppinsa sanoi hänelle: \"Missä olet tänään poiminut ja missä olet tehnyt työtä? Siunattu olkoon se, joka on sinusta huolehtinut.\" Sitten hän ilmoitti anopillensa, kenen luona hän oli ollut työssä, sanoen: \"Se mies, jonka luona olin tänä päivänä työssä, on nimeltään Booas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Noomi sanoi miniällensä: \"Siunatkoon häntä Herra, joka on osoittanut laupeutta eläviä ja kuolleita kohtaan\". Ja Noomi sanoi vielä: \"Hän on sukulaisemme ja meidän sukulunastajiamme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Silloin mooabilainen Ruut sanoi: \"Vielä hän sanoi minulle: \'Pysyttele vain minun palvelijaini mukana siihen asti, että he saavat kaiken minun leikkuuni lopetetuksi\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Niin Noomi sanoi miniällensä Ruutille: \"Hyvä on, tyttäreni, lähde hänen palvelijattariensa mukana, niin et joudu sysittäväksi muiden pelloilla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Ja hän pysytteli Booaan palvelijattarien seurassa poimien tähkiä, kunnes ohran-ja nisunleikkuu oli lopussa. Sitten hän jäi olemaan anoppinsa luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Niin Noomi, hänen anoppinsa, sanoi hänelle: \"Tyttäreni, minäpä hankin sinulle turvapaikan, että sinun kävisi hyvin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'Onhan Booas, jonka palvelijattarien kanssa olit, sukulaisemme; katso, hän viskaa tänä yönä ohria puimatantereella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Niin peseydy nyt ja voitele itsesi ja pukeudu ja mene puimatantereelle; mutta älä näyttäydy hänelle, ennenkuin hän on syönyt ja juonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'Kun hän panee maata, niin katso, mihin paikkaan hän panee maata, ja mene ja nosta peitettä hänen jalkojensa kohdalta ja pane siihen maata; hän sanoo sitten sinulle, mitä sinun on tehtävä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Ruut vastasi hänelle: \"Minä teen kaiken, mitä sanot\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'Niin hän meni alas puimatantereelle ja teki aivan niin, kuin hänen anoppinsa oli häntä käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Ja kun Booas oli syönyt ja juonut, tuli hänen sydämensä iloiseksi, ja hän meni maata viljakasan ääreen. Ja Ruut tuli hiljaa ja nosti peitettä hänen jalkojensa kohdalta ja pani siihen maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'Puoliyön aikana mies säikähti ja kumartui eteenpäin; ja katso, nainen makasi hänen jalkapohjissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'Ja hän kysyi: \"Kuka sinä olet?\" Hän vastasi: \"Minä olen Ruut, palvelijattaresi. Levitä liepeesi palvelijattaresi yli, sillä sinä olet minun sukulunastajani.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'Hän sanoi: \"Herra siunatkoon sinua, tyttäreni! Sinä olet osoittanut sukurakkauttasi nyt viimeksi vielä kauniimmin kuin aikaisemmin, kun et ole kulkenut nuorten miesten jäljessä, et köyhien etkä rikkaitten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Ja nyt, tyttäreni, älä pelkää; kaiken, mitä sanot, teen minä sinulle. Sillä minun kansani portissa jokainen tietää sinut kunnialliseksi naiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'Totta on, että minä olen sinun sukulunastajasi, mutta on vielä toinen sukulunastaja, joka on läheisempi kuin minä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Jää tähän yöksi; jos hän huomenna lunastaa sinut, niin hyvä; lunastakoon. Mutta jollei hän halua lunastaa sinua, niin minä lunastan sinut, niin totta kuin Herra elää. Lepää siinä aamuun asti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'Niin hän lepäsi hänen jalkapohjissaan aamuun asti, mutta nousi, ennenkuin kukaan vielä voi tuntea toisensa. Ja Booas ajatteli: \"Älköön tulko tunnetuksi, että tuo nainen on tullut tänne puimatantereelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Ja hän sanoi: \"Anna tänne vaippa, joka on ylläsi, ja pidä sitä\". Ja Ruut piti sitä. Silloin hän mittasi siihen kuusi mittaa ohria ja pani ne hänen selkäänsä. Ja hän meni kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'Ja Ruut tuli anoppinsa luo, joka sanoi: \"Kuinka kävi, tyttäreni?\" Niin hän kertoi hänelle kaikki, mitä mies oli hänelle tehnyt;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'ja hän sanoi: \"Nämä kuusi mittaa ohria hän antoi minulle, sanoen: \'Et saa mennä tyhjin käsin anoppisi luo\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Silloin Noomi sanoi: \"Pysy alallasi, tyttäreni, kunnes saat tietää, kuinka asia päättyy; sillä mies ei suo itselleen lepoa, ennenkuin hän tänä päivänä saattaa asian päätökseen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Mutta Booas meni kaupungin porttiin ja istuutui sinne. Ja katso, sukulunastaja, josta Booas oli puhunut, kulki siitä ohitse; ja Booas sanoi: \"Sinä siellä, poikkea tänne istumaan\". Hän poikkesi ja istui siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Senjälkeen Booas otti kaupungin vanhimpia kymmenen miestä ja sanoi: \"Istukaa tähän\". Ja he istuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Sitten Booas sanoi sukulunastajalle: \"Sen peltopalstan, joka oli veljellämme Elimelekillä, on Noomi, joka on palannut Mooabin maasta, myynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'Sentähden ajattelin: minä ilmoitan siitä sinulle ja sanon: osta se tässä saapuvilla olevien ja minun kansani vanhimpien läsnäollessa. Jos tahdot sen lunastaa sukuun, niin lunasta. Mutta ellet tahdo sitä lunastaa, niin ilmoita minulle, että saan sen tietää; sillä ei ole ketään muuta sukulunastajaa kuin sinä, ja sinun jälkeesi minä.\" Hän sanoi: \"Minä lunastan sen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Niin Booas sanoi: \"Ostaessasi pellon Noomilta ostat sen myöskin mooabilaiselta Ruutilta, vainajan leskeltä, ja sinun on pysytettävä vainajan nimi hänen perintöosassaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Silloin sanoi sukulunastaja: \"En voi lunastaa sitä itselleni, sillä siten minä turmelisin oman perintöosani. Lunasta sinä itsellesi, mitä minun olisi lunastettava; minä en voi sitä tehdä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Muinoin oli Israelissa lunastus-ja vaihtokauppoja vahvistettaessa tapa tällainen: riisuttiin kenkä ja annettiin toiselle; tätä käytettiin Israelissa todistuksena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Niin sukulunastaja sanoi Booaalle: \"Osta sinä se itsellesi\". Ja hän veti kengän jalastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Silloin sanoi Booas vanhimmille ja kaikelle kansalle: \"Te olette tänään todistajina, että minä ostan Noomilta kaiken Elimelekin ja kaiken Kiljonin ja Mahlonin omaisuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Samalla minä olen ostanut myös mooabilaisen Ruutin, Mahlonin lesken, vaimokseni, pysyttääkseni vainajan nimen hänen perintöosassaan, ettei vainajan nimi häviäisi hänen veljiensä keskuudesta eikä hänen kotipaikkansa portista; sen todistajat te olette tänä päivänä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'Niin kaikki kansa, joka oli portissa saapuvilla, ja vanhimmat sanoivat: \"Me olemme sen todistajat. Suokoon Herra, että vaimo, joka tulee taloosi, tulisi Raakelin ja Leean kaltaiseksi, jotka molemmat rakensivat Israelin huoneen. Tee väkeviä tekoja Efratassa ja saata nimesi kuuluisaksi Beetlehemissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Ja tulkoon niistä jälkeläisistä, jotka Herra antaa sinulle tästä nuoresta naisesta, sinulle suku, Pereksen suvun kaltainen, hänen, jonka Taamar synnytti Juudalle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Niin Booas otti Ruutin, ja tämä tuli hänen vaimokseen. Ja hän yhtyi häneen; ja Herra antoi hänen tulla raskaaksi, ja hän synnytti pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'Silloin vaimot sanoivat Noomille: \"Kiitetty olkoon Herra, joka tänä päivänä salli sinun saada sukulunastajan. Hänen nimensä tulee kuuluisaksi Israelissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Hän on virvoittava sinua, ja hänestä on tuleva sinun vanhuutesi tuki, sillä miniäsi, joka rakastaa sinua, on hänet synnyttänyt, hän, joka on sinulle parempi kuin seitsemän poikaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'Niin Noomi otti lapsen, pani sen helmaansa ja rupesi sen hoitajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'Ja naapurivaimot antoivat lapselle nimen, sanoen: \"Noomille on syntynyt poika\". Ja he panivat hänen nimekseen Oobed. Hänestä tuli Iisain, Daavidin isän, isä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Tämä on Pereksen sukuluettelo: Perekselle syntyi Hesron.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hesronille syntyi Raam, ja Raamille syntyi Amminadab.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Amminadabille syntyi Nahson, ja Nahsonille syntyi Salma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmalle syntyi Booas, ja Booaalle syntyi Oobed.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Oobedille syntyi Iisai, ja Iisaille syntyi Daavid.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Raamataim-Soofimissa, Efraimin vuoristossa, oli mies, nimeltä Elkana, Jerohamin poika, joka oli Elihun poika, joka Toohun poika, joka Suufin poika, efratilainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'Hänellä oli kaksi vaimoa; toisen nimi oli Hanna, ja toisen nimi oli Peninna. Ja Peninnalla oli lapsia, mutta Hanna oli lapseton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'Tämä mies meni joka vuosi kaupungistansa Siiloon rukoilemaan Herraa Sebaotia ja uhraamaan hänelle. Ja siellä oli kaksi Eelin poikaa, Hofni ja Piinehas, Herran pappeina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'Niin Elkana eräänä päivänä uhrasi. Ja hänellä oli tapana antaa vaimollensa Peninnalle ja kaikille tämän pojille ja tyttärille määräosat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Mutta Hannalle hän antoi kahdenkertaisen osan, sillä hän rakasti Hannaa, vaikka Herra oli sulkenut hänen kohtunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'Ja hänen kilpailijattarensa kiusasi häntä kiusaamistaan suututtaaksensa häntä, koska Herra oli sulkenut hänen kohtunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'Ja näin tapahtui joka vuosi, niin usein kuin hän meni Herran huoneeseen. Niinpä Peninna nytkin kiusasi häntä, ja hän itki eikä syönyt mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Silloin hänen miehensä Elkana sanoi hänelle: \"Hanna, mitä itket, miksi et syö ja miksi olet noin apealla mielellä? Enkö minä ole sinulle enempi kuin kymmenen poikaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Kun he sitten olivat syöneet ja juoneet Siilossa ja pappi Eeli istui istuimellaan Herran temppelin ovenpielessä, nousi Hanna');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'ja rukoili Herraa mieli murheellisena, itki katkerasti');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'ja teki lupauksen sanoen: \"Herra Sebaot, jos sinä katsot palvelijattaresi kurjuutta, muistat minua etkä unhota palvelijatartasi, vaan annat palvelijattarellesi miehisen perillisen, niin minä annan hänet Herralle koko hänen elinajaksensa, eikä partaveitsi ole koskettava hänen päätänsä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'Ja kun hän kauan rukoili Herran edessä, tarkkasi Eeli hänen suutansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'sillä Hanna puhui sydämessänsä ja ainoastaan hänen huulensa liikkuivat, mutta ääntä häneltä ei kuulunut; niin Eeli luuli, että hän oli juovuksissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Ja Eeli sanoi hänelle: \"Kuinka kauan sinä siinä olet juovuksissa? Haihduta humalasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Mutta Hanna vastasi ja sanoi: \"Ei, herrani, minä olen murheen raskauttama vaimo; viiniä ja väkijuomaa en ole juonut, vaan minä vuodatin sydämeni Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Älä pidä palvelijatartasi kelvottomana naisena, sillä tuskani ja suruni suuruuden tähden minä olen näin kauan puhunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Eeli vastasi ja sanoi: \"Mene rauhaan, Israelin Jumala antakoon sinulle, mitä olet häneltä pyytänyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Hän sanoi: \"Salli palvelijattaresi saada armo sinun silmiesi edessä\". Niin vaimo meni pois ja söi eikä enää näyttänyt murheelliselta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'Varhain seuraavana aamuna he nousivat ja kumartaen rukoilivat Herran edessä; sitten he palasivat ja tulivat kotiinsa Raamaan. Ja Elkana yhtyi vaimoonsa Hannaan, ja Herra muisti tätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'Ja Hanna tuli raskaaksi ja synnytti vuoden vaihteessa pojan ja antoi hänelle nimen Samuel, sanoen: \"Herralta olen minä hänet pyytänyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Sitten se mies, Elkana, ja koko hänen perheensä lähti uhraamaan Herralle jokavuotista teurasuhria ja lupausuhriaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'mutta Hanna ei lähtenyt, vaan sanoi miehellensä: \"Kun poika on vieroitettu, vien minä hänet sinne, niin että hän tulee Herran kasvojen eteen ja saa jäädä sinne ainiaaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Hänen miehensä Elkana sanoi hänelle: \"Tee, niinkuin hyväksi näet, jää kotiin, kunnes olet hänet vieroittanut; kunhan Herra vain täyttää sanansa\". Niin vaimo jäi kotiin ja imetti poikaansa, kunnes hän vieroitti tämän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'Mutta kun hän oli hänet vieroittanut, vei hän hänet kanssansa ottaen mukaansa kolme härkää, yhden eefa-mitan jauhoja ja leilin viiniä; niin hän toi hänet Herran huoneeseen Siiloon. Mutta poika oli vielä pieni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'Ja teurastettuaan härän he toivat pojan Eelin tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'Ja Hanna sanoi: \"Oi, herrani, niin totta kuin sinä elät, herrani, minä olen se vaimo, joka seisoin tässä sinun luonasi rukoillen Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Tätä poikaa minä rukoilin; Herra antoi minulle, mitä häneltä pyysin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Sentähden myös minä suostun antamaan hänet Herralle: kaikiksi elinpäiviksensä hän olkoon Herralle annettu.\" Ja Samuel rukoili siellä Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Ja Hanna rukoili ja sanoi: \"Minun sydämeni riemuitsee Herrassa; minun sarveni kohoaa korkealle Herrassa. Minun suuni on avartunut vihollisiani vastaan, sillä minä iloitsen sinun avustasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Ei kukaan ole pyhä niinkuin Herra; paitsi sinua ei ole yhtäkään, eikä ole kalliota meidän Jumalamme vertaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Älkää yhä ylpeitä puhuko, älköön suustanne lähtekö julkeita sanoja; sillä Herra on kaikkitietävä Jumala, hänen edessänsä punnitaan teot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Urhojen jouset ovat särjetyt, voipuneet vyöttäytyvät voimalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Kylläisinä olleet käyvät palvelukseen leipäpalkoilla, nälkää nähneet eivät enää nälkää näe. Hedelmätön synnyttää seitsemän lasta, lapsirikas kuihtuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Herra antaa kuoleman ja antaa elämän, hän vie alas tuonelaan ja tuo ylös jälleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Herra köyhdyttää ja rikastuttaa, hän alentaa ja ylentää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Hän tomusta nostaa halvan, hän loasta korottaa köyhän, pannaksensa heidät ruhtinasten rinnalle ja antaaksensa heidän periä kunniasijat. Sillä maan tukipylväät ovat Herran, hän on asettanut niiden päälle maanpiirin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Hän varjelee hurskastensa jalat, mutta jumalattomat hukkuvat pimeyteen; sillä mies ei omalla voimallaan mitään voi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Jotka taistelevat Herraa vastaan, ne joutuvat kauhun valtaan; hän jylisee taivaasta heidän ylitsensä. Herra tuomitsee maan ääret; hän antaa vallan kuninkaallensa ja korottaa korkealle voideltunsa sarven.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'Sitten Elkana meni kotiinsa Raamaan; mutta poikanen palveli Herraa pappi Eelin johdolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Mutta Eelin pojat olivat kelvottomia miehiä; he eivät välittäneet Herrasta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'eivätkä siitä, mitä papeilla oli oikeus kansalta saada. Niin usein kuin joku uhrasi teurasuhria, tuli papin palvelija lihan kiehuessa, kolmihaarainen haarukka kädessänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'ja pisti sen kattilaan tai ruukkuun tai pannuun tai pataan, ja kaikki, minkä haarukka toi mukanaan, sen pappi otti itselleen. Niin he tekivät kaikille israelilaisille, jotka tulivat sinne Siiloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Jo ennenkuin rasva oli poltettu, tuli papin palvelija ja sanoi miehelle, joka uhrasi: \"Anna liha paistettavaksi papille, sillä hän ei ota sinulta keitettyä lihaa, vaan raakaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Kun mies sanoi hänelle: \"Ensin poltettakoon rasva; ota sitten itsellesi, mitä haluat\", niin hän sanoi: \"Ei niin, vaan anna se nyt heti, muutoin minä otan väkisin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'Ja nuorten miesten synti oli kovin suuri Herran edessä, koska he pitivät Herran uhrilahjan halpana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Mutta Samuel palveli Herran edessä, puettuna, vaikka oli poikanen, pellavakasukkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'Ja hänen äitinsä teki hänelle joka vuosi pienen viitan ja toi sen hänelle, kun miehensä kanssa tuli uhraamaan vuotuista teurasuhria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'Silloin Eeli aina siunasi Elkanan ja hänen vaimonsa ja sanoi: \"Herra antakoon sinulle lapsen tästä vaimosta sen sijaan, jonka hän on suostunut antamaan Herralle\"; sitten he menivät kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Ja Herra piti Hannasta huolen, niin että hän tuli raskaaksi ja synnytti vielä kolme poikaa ja kaksi tytärtä. Mutta poikanen Samuel kasvoi Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Mutta Eeli oli käynyt hyvin vanhaksi; ja kun hän sai kuulla, mitä hänen poikansa tekivät kaikelle Israelille, ja että he makasivat niiden naisten kanssa, jotka toimittivat palvelusta ilmestysmajan ovella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'sanoi hän heille: \"Miksi te sellaista pahaa teette, mitä minä teistä kuulen kaikelta tältä kansalta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Ei niin, poikani! Ei ole hyvä se huhu, jonka minä kuulen kulkevan Herran kansan seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Jos ihminen rikkoo ihmistä vastaan, niin Jumala voi olla hänellä välittäjänä; mutta jos ihminen rikkoo Herraa vastaan, niin kuka voi ruveta hänelle välittäjäksi?\" Mutta he eivät kuulleet isäänsä, sillä Herra tahtoi surmata heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Mutta poikanen Samuel kasvoi kasvamistaan ja oli sekä Herralle että ihmisille otollinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Ja Eelin luo tuli Jumalan mies ja sanoi hänelle: \"Näin sanoo Herra: Enkö minä ilmestynyt sinun isäsi suvulle, kun he olivat Egyptissä faraon huoneen vallassa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'Ja minä valitsin heidät kaikista Israelin sukukunnista olemaan pappeinani, nousemaan minun alttarilleni, polttamaan suitsuketta ja kantamaan kasukkaa minun edessäni; ja minä annoin sinun isäsi suvulle kaikki israelilaisten uhrit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Miksi te häpäisette minun teurasuhrini ja ruokauhrini, jotka minä olen säätänyt asuntooni? Ja miksi sinä kunnioitat poikiasi enemmän kuin minua, niin että te lihotatte itseänne parhaalla osalla jokaisesta minun kansani Israelin uhrilahjasta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Sentähden Herra, Israelin Jumala, sanoo: Minä olen tosin sanonut: sinun sukusi ja sinun isäsi suku saavat vaeltaa minun edessäni iäti. Mutta nyt Herra sanoo: Pois se! Sillä minä kunnioitan niitä, jotka minua kunnioittavat; mutta jotka minut ylenkatsovat, ne tulevat halveksituiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Katso, päivät tulevat, jolloin minä katkaisen sinun käsivartesi ja sinun isäsi suvun käsivarren, niin ettei kukaan sinun suvussasi elä vanhaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'Ja sinä saat nähdä minun asuntoni olevan puutteessa huolimatta kaikesta siitä hyvästä, mikä tulee Israelille. Eikä kukaan sinun suvussasi ole koskaan elävä vanhaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Kuitenkaan minä en hävitä kaikkia sinun omaisiasi alttariltani, niin että sammuttaisin sinun silmäsi ja näännyttäisin sielusi; mutta kaikki sinun suvussasi kasvaneet kuolevat miehiksi tultuaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'Ja merkkinä tästä on sinulla oleva se, mitä kahdelle pojallesi, Hofnille ja Piinehaalle, tapahtuu: he kuolevat molemmat samana päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'Mutta minä herätän itselleni uskollisen papin, joka tekee minun sydämeni ja mieleni mukaan. Hänelle minä rakennan pysyväisen huoneen, ja hän on vaeltava minun voideltuni edessä kaiken elinaikansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'Ja jokainen, joka jää jäljelle sinun suvustasi, on tuleva kumartamaan häntä saadaksensa hopearahan ja leipäkakun ja sanovat: \'Päästä minutkin johonkin papintehtävään, että saisin palan leipää syödäkseni\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Ja poikanen Samuel palveli Herraa Eelin johdolla; mutta Herran sana oli harvinainen siihen aikaan, eivätkä näyt olleet tavallisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'Siihen aikaan tapahtui kerran, kun Eeli, jonka silmiä alkoi hämärtää, niin ettei hän voinut nähdä, makasi sijallansa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'eikä Jumalan lamppu ollut vielä sammunut ja Samuel makasi Herran temppelissä, jossa Jumalan arkki oli,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'että Herra kutsui Samuelia. Hän vastasi: \"Tässä olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'Ja hän riensi Eelin tykö ja sanoi: \"Tässä olen, sinä kutsuit minua\". Mutta hän vastasi: \"En minä kutsunut; pane jälleen maata\". Ja hän meni ja pani maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Mutta Herra kutsui taas Samuelia; ja Samuel nousi ja meni Eelin tykö ja sanoi: \"Tässä olen, sinä kutsuit minua\". Mutta tämä vastasi: \"En minä kutsunut, poikani; pane jälleen maata\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Mutta Samuel ei silloin vielä tuntenut Herraa, eikä Herran sana ollut vielä ilmestynyt hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Ja Herra kutsui Samuelia vielä kolmannen kerran; niin hän nousi ja meni Eelin tykö ja sanoi: \"Tässä olen, sinä kutsuit minua\". Silloin Eeli ymmärsi, että Herra oli kutsunut poikasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Ja Eeli sanoi Samuelille: \"Mene ja pane maata; ja jos sinua vielä kutsutaan, niin sano: \'Puhu, Herra; palvelijasi kuulee\'\". Samuel meni ja pani maata sijallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Niin Herra tuli ja seisoi ja huusi niinkuin edellisilläkin kerroilla: \"Samuel, Samuel!\" Samuel vastasi: \"Puhu, palvelijasi kuulee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Ja Herra sanoi Samuelille: \"Katso, minä teen Israelissa sellaisen teon, että joka sen kuulee, sen molemmat korvat soivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'Sinä päivänä minä annan toteutua Eelille kaiken, mitä olen hänen sukuansa vastaan puhunut, alusta loppuun asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Minä ilmoitan hänelle, että minä tuomitsen hänen sukunsa ikuisiksi ajoiksi sen rikoksen tähden, kun hän tiesi poikiensa pilkkaavan Jumalaa eikä pitänyt heitä kurissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'Sentähden minä olen vannonut Eelin suvusta: \'Totisesti, Eelin suvun rikosta ei koskaan soviteta, ei teurasuhrilla eikä ruokauhrilla\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'Ja Samuel makasi aamuun asti ja avasi sitten Herran huoneen ovet. Eikä Samuel uskaltanut kertoa Eelille sitä ilmestystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Mutta Eeli kutsui Samuelin ja sanoi: \"Samuel, poikani!\" Hän vastasi: \"Tässä olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'Hän sanoi: \"Mikä oli asia, josta hän sinulle puhui? Älä salaa sitä minulta. Jumala rangaiskoon sinua nyt ja vasta, jos salaat minulta mitään siitä, mitä hän sinulle puhui.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'Niin Samuel kertoi hänelle kaiken eikä salannut häneltä mitään. Mutta hän sanoi: \"Hän on Herra; hän tehköön, minkä hyväksi näkee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'Ja Samuel kasvoi, ja Herra oli hänen kanssansa eikä antanut yhdenkään sanoistansa varista maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Ja koko Israel Daanista Beersebaan asti tiesi, että Samuelille oli uskottu Herran profeetan tehtävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Ja Herra ilmestyi edelleenkin Siilossa; sillä Herra ilmestyi Samuelille Siilossa Herran sanan kautta. Ja Samuelin sana tuli koko Israelille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'Israel lähti sotaan filistealaisia vastaan ja leiriytyi Eben-Eserin luo, mutta filistealaiset olivat leiriytyneet Afekiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'Ja filistealaiset asettuivat sotarintaan Israelia vastaan, ja taistelu levisi laajalle, ja filistealaiset voittivat Israelin ja surmasivat taistelukentällä noin neljätuhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'Kun kansa tuli leiriin, sanoivat Israelin vanhimmat: \"Minkätähden Herra antoi tänä päivänä filistealaisten voittaa meidät? Ottakaamme Herran liitonarkki Siilosta luoksemme, tulkoon se keskellemme pelastamaan meidät vihollistemme käsistä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Ja kansa lähetti sanan Siiloon, ja sieltä tuotiin Herran Sebaotin liitonarkki, hänen, jonka valtaistuinta kerubit kannattavat; ja Eelin kaksi poikaa, Hofni ja Piinehas, seurasivat sieltä Jumalan liitonarkkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'Ja kun Herran liitonarkki tuli leiriin, nosti koko Israel suuren riemuhuudon, niin että maa jymisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Kun filistealaiset kuulivat sen riemuhuudon, sanoivat he: \"Mitä tuo suuri riemuhuuto on hebrealaisten leirissä?\" Ja he saivat tietää, että leiriin oli tullut Herran arkki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Silloin filistealaiset peljästyivät, sillä he ajattelivat: \"Jumala on tullut leiriin\". Ja he sanoivat: \"Voi meitä! Tällaista ei ole milloinkaan ennen tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Voi meitä! Kuka pelastaa meidät tämän voimallisen jumalan kädestä? Tämähän on se jumala, joka löi egyptiläisiä kaikkinaisilla vaivoilla erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Rohkaiskaa mielenne ja olkaa miehiä, filistealaiset, ettette te joutuisi palvelemaan hebrealaisia, niinkuin he ovat palvelleet teitä. Olkaa miehiä ja taistelkaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Ja filistealaiset ryhtyivät taisteluun; ja Israel voitettiin, niin että he pakenivat kukin majallensa, ja tappio oli sangen suuri: Israelista kaatui kolmekymmentä tuhatta jalkamiestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Ja Jumalan arkki ryöstettiin, ja Eelin kaksi poikaa, Hofni ja Piinehas, saivat surmansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'Eräs benjaminilainen mies juoksi sotarinnasta ja tuli samana päivänä Siiloon, takki reväistynä ja multaa pään päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'Ja kun hän tuli sinne, istui Eeli istuimellaan tien vieressä tähystellen, sillä hänen sydämensä oli levoton Jumalan arkin tähden. Ja kun mies tuli ja kertoi kaupungissa tapahtumasta, puhkesi koko kaupunki valittamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Kun Eeli kuuli valitushuudon, kysyi hän: \"Mikä meteli tämä on?\" Niin mies tuli rientäen sinne ja kertoi sen Eelille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Mutta Eeli oli yhdeksänkymmenen kahdeksan vuoden vanha, ja hänen silmissään oli kaihi, niin ettei hän voinut nähdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Ja mies sanoi Eelille: \"Minä tulen sotarinnasta; olen tänä päivänä paennut sotarinnasta\". Niin hän kysyi: \"Miten on asiat, poikani?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'Sanansaattaja vastasi ja sanoi: \"Israel on paennut filistealaisia, ja kansan mieshukka on suuri; myöskin sinun molemmat poikasi, Hofni ja Piinehas, ovat saaneet surmansa, ja Jumalan arkki on ryöstetty\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Kun hän mainitsi Jumalan arkin, kaatui Eeli istuimeltaan taapäin portin viereen, taittoi niskansa ja kuoli; sillä hän oli vanha ja raskas mies. Ja hän oli ollut tuomarina Israelissa neljäkymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Ja hänen miniänsä, Piinehaan vaimo, oli viimeisillänsä raskaana. Kun hän kuuli sanoman Jumalan arkin ryöstöstä ja appensa ja miehensä kuolemasta, vaipui hän maahan ja synnytti, sillä poltot yllättivät hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'Ja kun hän silloin oli kuolemaisillansa, sanoivat vaimot, jotka seisoivat hänen luonaan: \"Älä pelkää, sillä sinä olet synnyttänyt pojan\". Mutta hän ei vastannut mitään eikä välittänyt siitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'vaan nimitti pojan Iikabodiksi ja sanoi: \"Kunnia on mennyt Israelilta\" -hän tarkoitti Jumalan arkin ryöstöä ja appeansa ja miestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Hän sanoi: \"Kunnia on mennyt Israelilta\", koska Jumalan arkki oli ryöstetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Kun filistealaiset olivat ryöstäneet Jumalan arkin, veivät he sen Eben-Eseristä Asdodiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Ja filistealaiset ottivat Jumalan arkin ja veivät sen Daagonin temppeliin ja asettivat sen Daagonin rinnalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Kun asdodilaiset nousivat varhain seuraavana päivänä, niin katso: Daagon makasi kasvoillaan maassa Herran arkin edessä. Mutta he ottivat Daagonin ja asettivat sen takaisin paikoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Kun he taas nousivat varhain seuraavana aamuna, niin katso: Daagon makasi kasvoillaan maassa Herran arkin edessä, mutta Daagonin pää ja molemmat kädet olivat katkaistuina kynnyksellä, ja ainoastaan muu ruumis oli jäljellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Sentähden eivät Daagonin papit eikä kukaan, joka menee Daagonin temppeliin, astu Daagonin kynnykselle Asdodissa vielä tänäkään päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Mutta Herran käsi painoi asdodilaisia, ja hän tuhosi heitä: hän löi heitä ajoksilla, sekä Asdodia että sen aluetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'Kun Asdodin miehet näkivät, miten oli, sanoivat he: \"Älköön Israelin Jumalan arkki jääkö meidän luoksemme, sillä hänen kätensä on käynyt raskaaksi meille ja meidän jumalallemme Daagonille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'Ja he lähettivät sanan ja kokosivat kaikki filistealaisten ruhtinaat luoksensa ja sanoivat: \"Mitä me teemme Israelin Jumalan arkille?\" He vastasivat: \"Israelin Jumalan arkki siirtyköön Gatiin\". Ja he siirsivät Israelin Jumalan arkin sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Mutta kun he olivat siirtäneet sen sinne, kohtasi Herran käsi kaupunkia ja sai aikaan suuren hämmingin: hän löi kaupungin asukkaita, sekä pieniä että suuria, niin että heihin puhkesi ajoksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Silloin he lähettivät Jumalan arkin Ekroniin. Mutta kun Jumalan arkki tuli Ekroniin, huusivat ekronilaiset sanoen: \"He ovat siirtäneet Israelin Jumalan arkin tänne minun luokseni, surmaamaan minut ja minun kansani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Ja he lähettivät sanan ja kokosivat kaikki filistealaisten ruhtinaat ja sanoivat: \"Lähettäkää Israelin Jumalan arkki pois, ja palatkoon se kotiinsa älköönkä enää surmatko minua ja minun kansaani\". Sillä surma oli saattanut koko kaupungin hämminkiin; Jumalan käsi painoi sitä kovasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'Ne asukkaat, jotka eivät kuolleet, olivat ajoksilla lyödyt, ja huuto nousi kaupungista ylös taivaaseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'Herran arkki oli filistealaisten maassa seitsemän kuukautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Ja filistealaiset kutsuivat papit ja tietäjät ja sanoivat: \"Mitä me teemme Herran arkille? Antakaa meidän tietää, millä tavalla me lähettäisimme sen kotiinsa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'He vastasivat: \"Jos te lähetätte Israelin Jumalan arkin pois, niin älkää lähettäkö häntä tyhjin käsin, vaan antakaa hänelle hyvitys. Silloin te tulette terveiksi ja saatte tietää, minkätähden hänen kätensä ei heltiä teistä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'Mutta he kysyivät: \"Minkälainen hyvitys meidän on annettava hänelle?\" He vastasivat: \"Viisi kulta-ajosta ja viisi kultahiirtä, yhtä monta, kuin on filistealaisten ruhtinasta; sillä sama vitsaus on kohdannut kaikkia, myöskin teidän ruhtinaitanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Tehkää siis ajoksistanne kuvat, samoin hiiristänne, jotka hävittävät maata, ja antakaa kunnia Israelin Jumalalle. Kenties hän silloin hellittää kätensä teistä, teidän jumalistanne ja maastanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Miksi te paadutatte sydämenne, niinkuin egyptiläiset ja farao paaduttivat sydämensä? Eivätkö he, sittenkuin hän oli näyttänyt heille voimansa, päästäneet israelilaisia menemään?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Niin tehkää nyt uudet vaunut ja ottakaa kaksi imettävää lehmää, joiden niskassa ei ole iestä ollut, ja valjastakaa lehmät vaunujen eteen, mutta ajakaa vasikat kotiin, pois niiden jäljestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Ja ottakaa Herran arkki ja asettakaa se vaunuihin ja pankaa ne kultakalut, jotka annatte hänelle hyvitykseksi, lippaaseen sen viereen, ja lähettäkää se menemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'Ja sitten katsokaa: jos hän menee omaa aluettaan kohti, ylös Beet-Semekseen, niin on hän tuottanut meille tämän suuren onnettomuuden; mutta jos ei, niin tiedämme, ettei hänen kätensä ole meihin koskenut. Se on silloin tapahtunut meille sattumalta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'Miehet tekivät niin; he ottivat kaksi imettävää lehmää ja valjastivat ne vaunujen eteen, mutta niiden vasikat he jättivät kotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Ja he panivat Herran arkin vaunuihin ynnä lippaan, kultahiiret ja paiseittensa kuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'Ja lehmät menivät suoraan Beet-Semestä kohti; ne kulkivat koko ajan samaa tietä, poikkeamatta oikealle tai vasemmalle, ja ammuivat lakkaamatta. Ja filistealaisten ruhtinaat seurasivat niitä Beet-Semeksen alueelle asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Mutta Beet-Semeksessä oltiin leikkaamassa nisua laaksossa. Kun he nostivat silmänsä, näkivät he arkin; ja he ilostuivat nähdessään sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Vaunut tulivat beet-semekseläisen Joosuan pellolle ja pysähtyivät sinne; ja siellä oli suuri kivi. Ja he hakkasivat vaunut haloiksi ja uhrasivat lehmät polttouhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Ja leeviläiset nostivat maahan Herran arkin ja sen vieressä olevan lippaan, jossa kultakalut olivat, ja panivat ne sille suurelle kivelle. Ja Beet-Semeksen miehet uhrasivat sinä päivänä Herralle polttouhreja ja teurasuhreja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Katseltuaan tätä ne filistealaisten viisi ruhtinasta palasivat samana päivänä Ekroniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'Nämä ovat ne kultapaiseet, jotka filistealaiset antoivat Herralle hyvitykseksi: yksi Asdodin puolesta, yksi Gassan puolesta, yksi Askelonin puolesta, yksi Gatin puolesta ja yksi Ekronin puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Mutta kultahiiriä oli yhtä monta, kuin oli kaikkiaan filistealaisten kaupunkeja viidellä ruhtinaalla, niin hyvin varustettuja kaupunkeja kuin linnoittamattomia kyliä, suureen Aabel-kiveen asti, jolle he laskivat Herran arkin ja joka on vielä tänäkin päivänä beet-semekseläisen Joosuan pellolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Mutta Herra surmasi Beet-Semeksen miehiä sentähden, että he olivat katsoneet Herran arkkia; hän surmasi kansasta seitsemänkymmentä miestä, viisikymmentä tuhatta miestä; ja kansa suri sitä, että Herra oli surmannut niin paljon kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'Ja Beet-Semeksen miehet sanoivat: \"Kuka voi kestää Herran, tämän pyhän Jumalan, edessä? Ja kenen luo hän menee meidän luotamme?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'Ja he lähettivät sanansaattajat Kirjat-Jearimin asukasten luo sanomaan: \"Filistealaiset ovat tuoneet Herran arkin takaisin; tulkaa tänne ja viekää se luoksenne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Niin Kirjat-Jearimin miehet tulivat ja veivät Herran arkin sinne ja toivat sen Abinadabin taloon mäelle. Ja hänen poikansa Eleasarin he pyhittivät pitämään huolta Herran arkista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'Ja siitä päivästä, jona arkki oli asettunut Kirjat-Jearimiin, kului pitkä aika, kului kaksikymmentä vuotta; ja koko Israelin heimo huokaili Herran puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'Mutta Samuel sanoi koko Israelin heimolle näin: \"Jos te kaikesta sydämestänne käännytte Herran puoleen, niin poistakaa keskuudestanne vieraat jumalat ja astartet ja kiinnittäkää sydämenne Herraan ja palvelkaa ainoastaan häntä, niin hän pelastaa teidät filistealaisten käsistä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Niin israelilaiset poistivat baalit ja astartet ja palvelivat ainoastaan Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Ja Samuel sanoi: \"Kootkaa koko Israel Mispaan, ja minä rukoilen teidän puolestanne Herraa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'Niin he kokoontuivat Mispaan, ammensivat vettä ja vuodattivat sitä Herran eteen sekä paastosivat sen päivän; ja he sanoivat siellä: \"Me olemme tehneet syntiä Herraa vastaan\". Ja Samuel jakoi israelilaisille oikeutta Mispassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Kun filistealaiset kuulivat israelilaisten kokoontuneen Mispaan, lähtivät filistealaisten ruhtinaat Israelia vastaan. Kun israelilaiset kuulivat sen, pelkäsivät he filistealaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'Ja israelilaiset sanoivat Samuelille: \"Älä kieltäydy huutamasta meidän puolestamme Herraa, meidän Jumalaamme, että hän pelastaisi meidät filistealaisten käsistä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Niin Samuel otti imevän karitsan ja uhrasi sen polttouhriksi, kokonaisuhriksi, Herralle; ja Samuel huusi Herraa Israelin puolesta, ja Herra kuuli häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Sillä kun Samuelin uhratessa polttouhria filistealaiset lähestyivät käydäkseen taisteluun Israelia vastaan, niin sinä päivänä Herra jylisi kovalla ukkosen jylinällä filistealaisia vastaan ja saattoi heidät hämminkiin, niin että Israel voitti heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'Ja Israelin miehet lähtivät Mispasta ja ajoivat filistealaisia takaa, surmaten heitä aina Beet-Kaarin alapuolelle asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Ja Samuel otti kiven ja pani sen Mispan ja Seenin välille ja antoi sille nimen Eben-Eser ja sanoi: \"Tähän asti on Herra meitä auttanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Niin filistealaiset lannistettiin, eivätkä he enää tulleet Israelin alueelle. Ja Herran käsi oli filistealaisia vastaan Samuelin koko elinajan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Ja ne kaupungit, jotka filistealaiset olivat ottaneet Israelilta, joutuivat takaisin Israelille, Ekronista Gatiin saakka; ja myös niiden alueet Israel vapautti filistealaisten käsistä. Myöskin Israelin ja amorilaisten välillä oli rauha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'Samuel oli tuomarina Israelissa koko elinaikansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'Ja hän teki joka vuosi kiertomatkoja Beeteliin, Gilgaliin ja Mispaan, ja hän jakoi Israelille oikeutta kaikissa näissä paikoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Sitten hän palasi jälleen Raamaan, sillä siellä oli hänen kotinsa ja siellä hän jakoi oikeutta Israelille. Ja hän rakensi sinne alttarin Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Kun Samuel oli käynyt vanhaksi, pani hän poikansa Israelin tuomareiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Hänen esikoisensa nimi oli Jooel, ja hänen toisen poikansa nimi oli Abia; nämä olivat tuomareina Beersebassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Mutta hänen poikansa eivät vaeltaneet hänen teitänsä, vaan olivat väärän voiton pyytäjiä, ottivat lahjuksia ja vääristivät oikeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Niin kaikki Israelin vanhimmat kokoontuivat ja tulivat Samuelin tykö Raamaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'ja sanoivat hänelle: \"Katso, sinä olet käynyt vanhaksi, eivätkä poikasi vaella sinun teitäsi. Niin aseta nyt meille oikeutta jakamaan kuningas, jollainen kaikilla muillakin kansoilla on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Mutta Samuel pahastui siitä, että he sanoivat: \"Anna meille kuningas jakamaan meille oikeutta\". Ja Samuel rukoili Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Niin Herra sanoi Samuelille: \"Kuule kansan ääntä kaikessa, mitä he sinulle sanovat; sillä sinua he eivät ole pitäneet halpana, vaan minut he ovat pitäneet halpana olemaan heidän kuninkaanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Niinkuin he aina siitä päivästä, jona minä johdatin heidät tänne Egyptistä, tähän päivään asti ovat tehneet, kun ovat hyljänneet minut ja palvelleet muita jumalia, aivan niin he tekevät nyt sinullekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Kuule siis heidän ääntänsä. Kuitenkin varoita heitä vakavasti ja ilmoita heille, mitkä oikeudet on kuninkaalla, joka on heitä hallitseva.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'Niin Samuel puhui kaikki Herran sanat kansalle, joka häneltä pyysi kuningasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'Hän sanoi: \"Nämä oikeudet on kuninkaalla, joka on teitä hallitseva: Teidän poikanne hän ottaa ja panee heidät vaunumiehikseen ja ratsumiehikseen ja vaunujensa edelläjuoksijoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Myöskin hän panee heitä tuhannen-ja viidenkymmenenpäämiehiksi ja kyntämään hänen kyntöjänsä ja leikkaamaan hänen viljaansa sekä tekemään hänelle sotatarpeita ja vaunutarpeita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Ja teidän tyttärenne hän ottaa voiteiden tekijöiksi, keittäjiksi ja leipojiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Hän ottaa teidän parhaat peltonne, viinitarhanne ja öljypuunne ja antaa ne palvelijoillensa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'ja hän ottaa kymmenykset teidän kylvöstänne ja viinitarhojenne sadosta ja antaa ne hoviherroillensa ja palvelijoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Hän ottaa myös teidän palvelijanne ja palvelijattarenne ja parhaat nuoret miehenne sekä aasinne ja teettää niillä työnsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'ja hän ottaa kymmenykset teidän lampaistanne, ja te tulette hänen palvelijoiksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'Silloin te huudatte Herraa kuninkaanne tähden, jonka olette itsellenne valinneet, mutta hän ei silloin teitä kuule.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Mutta kansa ei tahtonut kuulla Samuelin puhetta, vaan sanoi: \"Ei, kuningas meillä pitää olla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Mekin tahdomme olla niinkuin kaikki muut kansat: kuningas jakakoon meille oikeutta ja johtakoon meitä ja käyköön sotiamme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'Kun Samuel kuuli kaikki kansan puheet, puhui hän ne Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Ja Herra sanoi Samuelille: \"Kuule heidän ääntänsä ja aseta heille kuningas\". Niin Samuel sanoi Israelin miehille: \"Menkää kukin kaupunkiinne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Benjaminissa oli mies, hyvin varakas, nimeltä Kiis, Abielin poika, joka oli Serorin poika, joka Bekoratin poika, joka Afiahin poika, joka erään benjaminilaisen miehen poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Hänellä oli poika, nimeltä Saul, nuori, kaunis mies. Israelilaisten joukossa ei ollut kauniimpaa miestä kuin hän: hän oli päätänsä pitempi kaikkea kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Ja Kiisiltä, Saulin isältä, olivat aasintammat joutuneet kateisiin, ja Kiis sanoi pojallensa Saulille: \"Ota palvelijoista joku mukaasi, nouse ja mene etsimään aasintammoja\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Niin hän kulki Efraimin vuoriston halki, ja hän kulki Salisan maan halki; mutta he eivät löytäneet niitä. Ja he kulkivat Saalimin maan halki, eikä niitä ollut sielläkään; sitten he kulkivat Benjaminin maan halki eivätkä löytäneet niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Kun he olivat tulleet Suufin maahan, sanoi Saul palvelijallensa, joka hänellä oli mukanaan: \"Tule, palatkaamme kotiin; muutoin isäni käy levottomaksi meidän tähtemme ja jättää mielestään aasintammat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Mutta palvelija sanoi hänelle: \"Katso, tässä kaupungissa on Jumalan mies, arvossa pidetty mies; kaikki, mitä hän sanoo, se varmasti toteutuu. Menkäämme nyt sinne; kenties hän ilmaisee meille jotakin matkasta, jolla olemme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Niin Saul sanoi palvelijallensa: \"Jos menemme sinne, niin mitä me viemme sille miehelle? Sillä leipä on loppunut repuistamme, eikä meillä ole muutakaan lahjaa vietäväksi Jumalan miehelle. Vai onko meillä mitään?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Palvelija vastasi vielä Saulille ja sanoi: \"Katso, tässä on minulla neljännes sekeliä hopeata; minä annan sen Jumalan miehelle, että hän ilmaisisi meille jotakin matkastamme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '-Muinoin sanottiin Israelissa, kun mentiin kysymään Jumalalta, näin: \"Tulkaa, menkäämme näkijän luo\". Sillä sitä, jota nyt sanotaan profeetaksi, kutsuttiin muinoin näkijäksi. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Saul vastasi palvelijallensa: \"Puheesi on hyvä; tule, menkäämme\". Ja he menivät kaupunkiin, jossa Jumalan mies oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Kun he nousivat rinnettä ylös kaupunkiin, kohtasivat he tyttöjä, jotka olivat menossa vettä ammentamaan. Näiltä he kysyivät: \"Onko näkijä täällä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Nämä vastasivat heille ja sanoivat: \"On, katso, hän on tuolla edessäpäin. Riennä, sillä hän on juuri nyt tullut kaupunkiin, koska kansalla tänä päivänä on teurasuhrit uhrikukkulalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Kun tulette kaupunkiin, tapaatte hänet, ennenkuin hän menee uhrikukkulalle aterioimaan; sillä kansa ei aterioi, ennenkuin hän tulee. Kun hän on siunannut uhrin, sitten vasta kutsuvieraat aterioivat. Menkää siis sinne, sillä juuri nyt te hänet tapaatte.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Ja he menivät kaupunkiin. Kun he tulivat kaupunkiin, niin katso, Samuel tuli heitä vastaan menossa uhrikukkulalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Mutta päivää ennen Saulin tuloa oli Herra ilmoittanut ja sanonut Samuelille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, '\"Huomenna tähän aikaan minä lähetän sinun tykösi miehen Benjaminin maasta. Voitele hänet minun kansani Israelin ruhtinaaksi. Hän on vapauttava minun kansani filistealaisten käsistä. Sillä minä olen katsonut kansani puoleen, sen huuto on tullut minun eteeni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'Kun Samuel näki Saulin, ilmoitti Herra hänelle: \"Katso, tässä on mies, josta minä olen sinulle sanonut: \'Tämä on vallitseva minun kansaani\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'Saul meni Samuelin tykö keskelle porttia ja sanoi: \"Sano minulle, missä on näkijän asunto?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel vastasi Saulille ja sanoi: \"Minä olen näkijä. Mene minun edelläni uhrikukkulalle. Aterioikaa tänä päivänä minun kanssani; huomenaamuna minä päästän sinut menemään, ja kaikki, mitä sinulla on sydämelläsi, minä selvitän sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'Äläkä enää ole huolissasi aasintammoista, jotka ovat olleet sinulta kateissa kolme päivää, sillä ne ovat löytyneet. Ja kenen on kaikki, mitä kallisarvoisinta Israelissa on, jollei sinun ja kaiken sinun isäsi perheen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Saul vastasi ja sanoi: \"Minähän olen benjaminilainen, olen sukukunnasta, joka on Israelin pienimpiä, ja minun sukuni on vähäisin kaikista Benjaminin sukukunnan suvuista. Miksi puhut minulle näin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Mutta Samuel otti Saulin palvelijoinensa ja vei heidät ruokailuhuoneeseen ja antoi heille ylimmän sijan kutsuvierasten joukossa, joita oli noin kolmekymmentä miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'Ja Samuel sanoi keittäjälle: \"Tuo tänne se kappale, jonka minä sinulle annoin ja josta minä sinulle sanoin: \'Pane se syrjään\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Niin keittäjä otti reiden, ja mitä siihen kuului, ja pani sen Saulin eteen. Ja Samuel sanoi: \"Katso, tässä pannaan sinun eteesi se, mikä on varattu; syö siitä. Sillä juuri täksi hetkeksi se säästettiin sinua varten, kun minä sanoin: \'Minä olen kutsunut kansan\'.\" Niin Saul aterioi Samuelin kanssa sinä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'Kun he sitten olivat tulleet uhrikukkulalta alas kaupunkiin, puhui hän Saulin kanssa katolla. Ja he nousivat varhain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Niin Samuel aamun sarastaessa kutsui Saulia katolta ja sanoi: \"Nouse, minä lähden saattamaan sinua\". Saul nousi, ja hän ja Samuel menivät yhdessä ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'Kun he tulivat alas kaupungin laitaan, sanoi Samuel Saulille: \"Sano palvelijalle, että hän menee meidän edellämme\" -ja tämä meni edelle-\"mutta pysähdy sinä hetkeksi tähän, niin minä julistan sinulle Jumalan sanan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Silloin Samuel otti öljyastian, vuodatti öljyä hänen päähänsä, suuteli häntä ja sanoi: \"Katso, Herra on voidellut sinut perintöosansa ruhtinaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Kun sinä tänä päivänä lähdet minun luotani, kohtaat sinä Raakelin haudan luona Selsahissa Benjaminin rajalla kaksi miestä; ne sanovat sinulle: \'Aasintammat, joita olet lähtenyt etsimään, ovat löytyneet; katso, isäsi on heittänyt mielestään aasintammat, kun on levoton teidän tähtenne ja sanoo: Mitä minä voisin tehdä poikani avuksi?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Ja kun menet siitä edemmäksi ja tulet Taaborin tammelle, tulee siellä sinua vastaan kolme miestä menossa Jumalan eteen Beeteliin. Yksi kantaa kolmea vohlaa, toinen kantaa kolmea leipäkakkua, ja kolmas kantaa viinileiliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Ne tervehtivät sinua ja antavat sinulle kaksi leipää; ota ne heiltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Senjälkeen sinä tulet Jumalan Gibeaan, jossa filistealaisten maaherrat ovat. Ja tullessasi sinne kaupunkiin sinä kohtaat joukon profeettoja, jotka tulevat alas uhrikukkulalta hurmoksissaan, harppu, vaskirumpu, huilu ja kannel edellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'Ja Herran henki tulee sinuun, ja sinäkin joudut hurmoksiin niinkuin hekin; ja sinä muutut toiseksi mieheksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'Ja kun nämä ennusmerkit käyvät toteen, niin tee, mikä tehtäväksesi tulee, sillä Jumala on sinun kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Mene sitten minun edelläni Gilgaliin, niin minä tulen sinne sinun luoksesi uhraamaan polttouhreja ja yhteysuhreja; odota seitsemän päivää, kunnes minä tulen sinun luoksesi ja ilmoitan sinulle, mitä sinun on tehtävä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'Ja kun hän käänsi selkänsä lähteäksensä Samuelin luota, muutti Jumala hänen sydämensä; ja kaikki nämä ennusmerkit kävivät sinä päivänä toteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Ja kun he tulivat sinne, Gibeaan, niin katso, joukko profeettoja tuli häntä vastaan. Silloin Jumalan henki tuli häneen, ja hänkin joutui hurmoksiin heidän keskellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Kun kaikki, jotka ennestään tunsivat hänet, näkivät hänet hurmoksissa niinkuin profeetatkin, sanoivat he toisillensa: \"Mikä Kiisin pojalle on tullut? Onko Saulkin profeettain joukossa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'Mutta eräs sikäläisistä miehistä vastasi ja sanoi: \"Kuka sitten heidän isänsä on?\" -Niin tuli sananlaskuksi: \"Onko Saulkin profeettain joukossa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'Päästyään hurmoksista hän meni uhrikukkulalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Ja Saulin setä kysyi häneltä ja hänen palvelijaltansa: \"Missä te olette käyneet?\" Hän vastasi: \"Aasintammoja etsimässä. Mutta kun emme niitä missään nähneet, menimme Samuelin tykö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Silloin Saulin setä sanoi: \"Kerro minulle, mitä Samuel teille sanoi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Saul vastasi sedällensä: \"Hän ilmoitti meille aasintammain löytyneen\". Mutta mitä Samuel oli sanonut kuninkuudesta, sitä hän ei hänelle kertonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Sitten Samuel kutsui kansan koolle Herran eteen Mispaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'Hän sanoi israelilaisille: \"Näin sanoo Herra, Israelin Jumala: Minä johdatin Israelin Egyptistä, ja minä vapautin teidät egyptiläisten käsistä sekä kaikkien niiden valtakuntien käsistä, jotka teitä sortivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Mutta nyt te olette pitäneet halpana Jumalanne, joka on auttanut teidät kaikista onnettomuuksistanne ja ahdingoistanne, ja olette sanoneet hänelle: \'Aseta meille kuningas\'. Asettukaa siis Herran eteen sukukunnittain ja suvuittain.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'Niin Samuel antoi kaikkien Israelin sukukuntien astua esiin; ja arpa osui Benjaminin sukukuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Kun hän sitten antoi Benjaminin sukukunnan astua esiin suvuittain, osui arpa Matrin sukuun; sen jälkeen osui arpa Sauliin, Kiisin poikaan. Mutta kun häntä etsittiin, ei häntä löydetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Silloin he kysyivät vielä kerran Herralta: \"Onko ketään muuta vielä tullut tänne?\" Herra vastasi: \"Katso, hän on piiloutunut kuormastoon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Niin he juoksivat ja toivat hänet sieltä, ja kun hän asettui kansan keskelle, niin hän oli päätänsä pitempi kaikkea kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'Ja Samuel sanoi kaikelle kansalle: \"Näettekö, kenen Herra on valinnut; sillä ei ole hänen vertaistansa koko kansan joukossa\". Niin koko kansa riemuitsi huutaen: \"Eläköön kuningas!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Ja Samuel julisti kansalle kuninkuuden oikeudet, kirjoitti ne kirjaan ja asetti sen Herran eteen. Sitten Samuel päästi kaiken kansan menemään, kunkin kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Ja myöskin Saul meni kotiinsa Gibeaan, ja hänen kanssaan meni sotaväki, ne, joiden sydämiä Jumala oli koskettanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Mutta kelvottomat miehet sanoivat: \"Mitä apua meille tästä on?\" Ja nämä halveksivat häntä eivätkä tuoneet hänelle mitään lahjoja; mutta hän ei virkkanut mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Ammonilainen Naahas lähti piirittämään Gileadin Jaabesta. Niin kaikki Jaabeksen miehet sanoivat Naahaalle: \"Tee liitto meidän kanssamme, niin me palvelemme sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Mutta ammonilainen Naahas vastasi heille: \"Sillä ehdolla minä teen liiton teidän kanssanne, että saan puhkaista jokaiselta teiltä oikean silmän; niin minä häpäisen koko Israelin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'Jaabeksen vanhimmat sanoivat hänelle: \"Jätä meidät rauhaan seitsemäksi päiväksi, niin me lähetämme sanansaattajia kaikkialle Israelin alueelle; jollei kukaan meitä auta, niin me antaudumme sinulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'Niin sanansaattajat tulivat Saulin Gibeaan ja puhuivat asian kansalle. Silloin kaikki kansa korotti äänensä ja itki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'Ja katso, Saul tuli käyden härkäin jäljessä pellolta. Ja Saul kysyi: \"Mikä kansalla on, kun he itkevät?\" Niin he kertoivat hänelle Jaabeksen miesten asian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Kun Saul kuuli tämän asian, tuli Jumalan henki häneen, ja hän vihastui kovin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'Ja hän otti härkäparin, paloitteli härät ja lähetti kappaleet kaikkialle Israelin alueelle sanansaattajain mukana ja käski sanoa: \"Näin tehdään jokaisen härjille, joka ei seuraa Saulia ja Samuelia\". Ja Herran kauhu valtasi kansan, niin että he lähtivät niinkuin yksi mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'Ja hän piti katselmuksen heistä Besekissä; ja israelilaisia oli kolmesataa tuhatta ja Juudan miehiä kolmekymmentä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'Ja he sanoivat sanansaattajille, jotka olivat tulleet: \"Sanokaa näin Gileadin Jaabeksen miehille: \'Huomenna, auringon ollessa polttavimmillaan, te saatte apua\'\". Niin sanansaattajat tulivat ja ilmoittivat sen Jaabeksen miehille; ja nämä ilostuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Niin Jaabeksen miehet sanoivat: \"Huomenna me antaudumme teille, ja te saatte tehdä meille, mitä tahdotte\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Seuraavana päivänä Saul jakoi kansan kolmeen joukkoon; ja he tunkeutuivat leiriin aamuvartion aikana ja voittivat ammonilaiset, surmaten heitä, kunnes päivä tuli palavimmilleen. Ja jäljelle jääneet hajaantuivat, niin ettei heistä kahta yhteen jäänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Silloin kansa sanoi Samuelille: \"Ketkä ne olivat, jotka sanoivat: \'Saulko tulisi meidän kuninkaaksemme?\' Antakaa tänne ne miehet, surmataksemme heidät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'Mutta Saul sanoi: \"Tänä päivänä ei ketään surmata, sillä tänä päivänä on Herra antanut voiton Israelille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Ja Samuel sanoi kansalle: \"Tulkaa, menkäämme Gilgaliin ja uudistakaamme siellä kuninkuus\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Niin kaikki kansa meni Gilgaliin ja teki Saulin kuninkaaksi siellä, Herran edessä Gilgalissa; ja he uhrasivat siellä yhteysuhreja Herran edessä. Ja Saul ja kaikki Israelin miehet iloitsivat siellä suuresti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Samuel sanoi kaikelle Israelille: \"Katso, minä olen kuullut teidän ääntänne kaikessa, mitä te olette minulta pyytäneet; minä olen asettanut kuninkaan teitä hallitsemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Ja nyt on teidän kuninkaanne käyvä teidän edellänne, kun minä olen tullut vanhaksi ja harmaaksi-ovathan jo minun poikani teidän keskellänne. Mutta minä olen käynyt teidän edellänne nuoruudestani tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Tässä minä olen; todistakaa minua vastaan Herran ja hänen voideltunsa edessä. Keneltä minä olen vienyt härän tai keneltä aasin? Kenelle minä olen tehnyt vääryyttä, kenelle väkivaltaa? Keneltä minä olen lahjuksia ottanut ummistaakseni silmäni hänen hyväksensä? Todistakaa, niin minä korvaan sen teille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'He vastasivat: \"Et ole tehnyt meille vääryyttä etkä väkivaltaa, et myös ole keneltäkään mitään ottanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Silloin hän sanoi heille: \"Herra on todistaja teitä vastaan, ja hänen voideltunsa on todistaja tänä päivänä, että te ette ole löytäneet mitään minun kädestäni\". He vastasivat: \"Hän on todistaja\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'Samuel sanoi kansalle: \"Todistaja on Herra, joka kutsui Mooseksen ja Aaronin ja johdatti teidän isänne Egyptin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Astukaa nyt esiin, minä haastan teidät tuomiolle Herran edessä kaikista Herran vanhurskaista teoista, jotka hän on teille ja teidän isillenne tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Kun Jaakob oli tullut Egyptiin, huusivat teidän isänne Herraa, ja Herra lähetti Mooseksen ja Aaronin viemään teidän isänne pois Egyptistä ja sijoittamaan heidät tähän paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Mutta he unhottivat Herran, Jumalansa. Silloin hän myi heidät Siiseran, Haasorin sotapäällikön, käsiin ja filistealaisten käsiin ja Mooabin kuninkaan käsiin, ja nämä sotivat heitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Niin he huusivat Herraa ja sanoivat: \'Me olemme syntiä tehneet, kun hylkäsimme Herran ja palvelimme baaleja ja astarteja; mutta vapauta nyt meidät vihollistemme käsistä, niin me palvelemme sinua\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Ja Herra lähetti Jerubbaalin, Bedanin, Jeftan ja Samuelin ja vapautti teidät ympärillä asuvain vihollistenne käsistä, niin että saitte asua turvassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Mutta kun te näitte Naahaan, ammonilaisten kuninkaan, hyökkäävän teitä vastaan, sanoitte te minulle: \'Ei, vaan kuningas hallitkoon meitä\', vaikka Herra, teidän Jumalanne, on kuninkaanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Tässä on nyt kuningas, jonka te valitsitte ja jota anoitte: katso, Herra on antanut teille kuninkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Jos te pelkäätte Herraa ja palvelette häntä, kuulette hänen ääntänsä ettekä niskoittele hänen käskyjänsä vastaan, niin te seuraatte Herraa, Jumalaanne, sekä te että kuningas, joka teitä hallitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Mutta jollette kuule Herran ääntä, vaan niskoittelette hänen käskyjänsä vastaan, niin Herran käsi on oleva teitä vastaan, niinkuin oli myös teidän isiänne vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Astukaa nyt esiin ja katsokaa tätä suurta tekoa, jonka Herra tekee teidän silmienne edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Nythän on nisunleikkuun aika; mutta minä huudan Herraa, että hän antaa ukkosenjylinän ja sateen, että ymmärtäisitte ja näkisitte, kuinka paha Herran silmissä on se, minkä olette tehneet anoessanne itsellenne kuningasta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Ja Samuel huusi Herraa, ja Herra antoi ukkosenjylinän ja sateen sinä päivänä. Ja kaikki kansa pelkäsi suuresti Herraa ja Samuelia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'Ja kaikki kansa sanoi Samuelille: \"Rukoile palvelijaisi puolesta Herraa, Jumalaasi, ettemme kuolisi; sillä me olemme tehneet kaikkien muiden syntiemme lisäksi senkin pahan, että anoimme itsellemme kuningasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Samuel sanoi kansalle: \"Älkää peljätkö. Te olette tosin tehneet kaiken tämän pahan, mutta älkää kuitenkaan poiketko pois seuraamasta Herraa, vaan palvelkaa Herraa kaikesta sydämestänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Älkää poiketko seuraamaan turhia jumalia, joista ei ole hyötyä eikä apua, sillä turhia ne ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Suuren nimensä tähden Herra ei hylkää kansaansa, koska Herra on tahtonut tehdä teidät omaksi kansaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Ja pois se minusta, että tekisin sen synnin Herraa vastaan, että lakkaisin rukoilemasta teidän puolestanne ja opettamasta teille hyvää ja oikeata tietä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Peljätkää vain Herraa ja palvelkaa häntä uskollisesti kaikesta sydämestänne. Sillä katsokaa, kuinka suuria hän on teille tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Mutta jos teette pahaa, niin hukutte, sekä te itse että teidän kuninkaanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul oli ollut vuoden kuninkaana ja hallitsi Israelia toista vuotta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'kun Saul valitsi itsellensä kolmetuhatta miestä Israelista, ja näistä oli kaksituhatta Saulin kanssa Mikmaassa ja Beetelin vuoristossa, ja tuhat Joonatanin kanssa Benjaminin Gibeassa. Mutta muun väen hän oli päästänyt menemään, kunkin majallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Mutta Joonatan, Saulin poika, löi kuoliaaksi filistealaisten maaherran, joka asui Gebassa, ja filistealaiset saivat sen kuulla. Silloin Saul puhallutti pasunaan kaikkialla maassa ja käski sanoa: \"Hebrealaiset kuulkoot tämän\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'Ja koko Israel kuuli sen sanoman, että Saul oli lyönyt kuoliaaksi filistealaisten maaherran ja että Israel oli joutunut filistealaisten vihoihin. Niin kansa kutsuttiin koolle Gilgaliin, seuraamaan Saulia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Sillä filistealaiset olivat kokoontuneet sotimaan Israelia vastaan: kolmetkymmenet tuhannet sotavaunut, kuusituhatta ratsumiestä ja muuta väkeä niin paljon kuin hiekkaa meren rannalla; ja he tulivat ylös ja leiriytyivät Mikmaaseen, vastapäätä Beet-Aavenia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Kun Israelin miehet näkivät joutuneensa hätään ja kansaa ahdistettavan, piiloutuivat he luoliin, onkaloihin, kallionrotkoihin, hautoihin ja kaivoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Hebrealaisia meni myös Jordanin yli Gaadiin ja Gileadin maahan. Mutta Saul oli vielä Gilgalissa, ja kaikki sotaväki seurasi häntä peloissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'Kun hän oli odottanut seitsemän päivää, sen ajan, jonka Samuel oli määrännyt, eikä Samuel tullutkaan Gilgaliin, alkoi kansa hajaantua pois hänen luotaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Silloin Saul sanoi: \"Tuokaa minulle polttouhri ja yhteysuhri\". Ja hän uhrasi polttouhrin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Mutta juuri kun hän oli saanut polttouhrin uhratuksi, niin katso, Samuel tuli. Ja Saul meni häntä vastaan tervehtimään häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Mutta Samuel sanoi: \"Mitä olet tehnyt?\" Saul vastasi: \"Kun näin, että kansa hajaantui pois minun luotani etkä sinä tullut määrättynä aikana, vaikka filistealaiset olivat kokoontuneet Mikmaaseen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'niin minä ajattelin: nyt filistealaiset hyökkäävät minua vastaan alas Gilgaliin, enkä minä ole etsinyt Herran mielisuosiota; ja minä rohkaisin itseni ja uhrasin polttouhrin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Samuel sanoi Saulille: \"Sinä olet tehnyt tyhmästi. Et ole noudattanut Herran, Jumalasi, käskyä, jonka hän antoi sinulle; muutoin olisi Herra vahvistanut sinun kuninkuutesi Israelissa ikuisiksi ajoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Mutta nyt sinun kuninkuutesi ei ole pysyvä. Herra on etsinyt itselleen mielensä mukaisen miehen, ja hänet on Herra määrännyt kansansa ruhtinaaksi, koska sinä et noudattanut käskyä, minkä Herra sinulle antoi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Sitten Samuel nousi ja meni Gilgalista Benjaminin Gibeaan. Ja Saul piti mukanansa olevan väen katselmuksen: noin kuusisataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Ja Saul ja hänen poikansa Joonatan ynnä väki, joka oli heidän kanssansa, jäivät Benjaminin Gebaan, mutta filistealaiset olivat leiriytyneet Mikmaaseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'Ja filistealaisten leiristä lähti ryöstöosasto kolmena joukkona: yksi joukko kääntyi Ofran tielle Suualin maahan päin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'toinen joukko kääntyi Beet-Hooronin tielle, ja kolmas joukko kääntyi sille tielle, joka vie Seboimin laakson yli kohoavalle alueelle, erämaahan päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Mutta ei yhtään seppää ollut löydettävissä koko Israelin maasta, sillä filistealaiset ajattelivat, että hebrealaiset muutoin teettäisivät miekkoja tai keihäitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Ja koko Israelin, joka miehen, oli mentävä filistealaisten luo teroituttamaan vannastansa, kuokkaansa, kirvestänsä tai muuta teräkaluansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'kun vannasten, kuokkien, tadikkojen tai kirvesten terät olivat tylsyneet, tahi kun häränpistimen tutkain oli oikaistava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Niinpä ei taistelupäivänä ollut yhtään miekkaa eikä keihästä kenelläkään siitä väestä, joka oli Saulin ja Joonatanin kanssa; ainoastaan Saulilla ja hänen pojallansa Joonatanilla oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'Mutta filistealaisten vartiosto lähti Mikmaan solatielle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'Ja tapahtui eräänä päivänä, että Joonatan, Saulin poika, sanoi palvelijalle, joka kantoi hänen aseitansa: \"Tule, menkäämme lähelle filistealaisten vartiostoa, joka on tuolla toisella puolella\". Mutta hän ei ilmoittanut sitä isällensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Saul istui silloin granaattiomenapuun juurella Migronissa Gibean rajalla, ja väkeä oli hänellä kanssansa noin kuusisataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'Ja kasukankantajana oli Ahia, Ahitubin, Iikabodin veljen, poika, joka oli Piinehaan poika, joka Eelin poika, sen, joka oli ollut Herran pappina Siilossa. Mutta kansa ei tiennyt, että Joonatan oli lähtenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Mutta kummallakin puolen solatietä, jota Joonatan koetti mennä lähelle filistealaisten vartiostoa, oli jyrkkä kallionkieleke; toisen nimi on Booses, toisen Sene.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Toinen kallionkieleke on kuin pylväs, pohjoisen puolella, Mikmaaseen päin, toinen on etelän puolella, Gebaan päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'Ja Joonatan sanoi palvelijalle, joka kantoi hänen aseitansa: \"Tule, menkäämme lähelle noiden ympärileikkaamattomain vartiostoa; ehkä Herra on tekevä jotakin meidän puolestamme, sillä ei mikään estä Herraa antamasta voittoa harvojen kautta yhtä hyvin kuin monien\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Hänen aseenkantajansa vastasi hänelle: \"Tee, mitä mielessäsi on. Lähde, minä seuraan sinua mielesi mukaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Niin Joonatan sanoi: \"Katso, me menemme tuonne, lähelle noita miehiä, ja näyttäydymme heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Jos he sanovat meille näin: \'Olkaa hiljaa, kunnes me tulemme teidän luoksenne\', niin me seisomme alallamme emmekä lähde nousemaan heidän luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Mutta jos he sanovat näin: \'Nouskaa tänne meidän luoksemme\', niin me nousemme, sillä silloin Herra on antanut heidät meidän käsiimme; tämä olkoon meillä merkkinä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Kun he sitten molemmat tulivat filistealaisten vartioston näkyviin, sanoivat filistealaiset: \"Katso, hebrealaiset tulevat esiin koloistansa, joihin ovat piiloutuneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'Ja vartioston miehet huusivat Joonatanille ja hänen aseenkantajalleen ja sanoivat: \"Nouskaa tänne meidän luoksemme, niin me ilmoitamme teille jotakin\". Silloin sanoi Joonatan aseenkantajallensa: \"Nouse minun perässäni, sillä Herra on antanut heidät Israelin käsiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Ja Joonatan kiipesi käsin ja jaloin ylöspäin, ja aseenkantaja hänen perässään. Ja he kaatuivat Joonatanin edessä, ja aseenkantaja löi heidät kuoliaaksi hänen jäljessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Tässä ensimmäisessä kahakassa surmasivat Joonatan ja hänen aseenkantajansa noin kaksikymmentä miestä, noin puolen auranalan suuruisella maa-alalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'Silloin syntyi kauhu leirissä ja sen ulkopuolella, koko sotaväessä; myös vartiosto ja ryöstöosasto joutuivat kauhun valtaan. Maakin järisi, ja niin syntyi Jumalan kauhu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'Ja Saulin tähystäjät Benjaminin Gibeassa huomasivat lauman hajoavan ja menevän sinne tänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Niin Saul sanoi väelle, joka oli hänen kanssansa: \"Pitäkää katselmus ja katsokaa, kuka on mennyt pois meidän luotamme\". Ja kun katselmus pidettiin, huomattiin, etteivät Joonatan ja hänen aseenkantajansa olleet läsnä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Ja Saul sanoi Ahialle: \"Tuo tänne Jumalan arkki\". Sillä Jumalan arkki oli siihen aikaan israelilaisten hallussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'Mutta Saulin vielä puhutellessa pappia kävi meteli filistealaisten leirissä yhä suuremmaksi. Niin Saul sanoi papille: \"Jätä sikseen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'Silloin Saul kutsutti koolle kaiken väen, joka oli hänen kanssaan, ja he tulivat taistelupaikalle, ja katso, toisen miekka oli toista vastaan, ja oli mitä suurin hämminki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Myös ne hebrealaiset, jotka ennestään olivat filistealaisten vallassa ja jotka olivat tulleet heidän kanssaan ja olivat leirissä, menivät niiden israelilaisten puolelle, jotka olivat Saulin ja Joonatanin kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Ja kun ne Israelin miehet, jotka olivat piiloutuneet Efraimin vuoristoon, kuulivat filistealaisten pakenevan, yhtyivät hekin kaikki ajamaan heitä takaa taistelussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Niin Herra antoi Israelille voiton sinä päivänä, ja taistelu levisi Beet-Aavenin toiselle puolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'Israelin miehet olivat sinä päivänä ylen rasitetut, mutta Saul vannotti kansan ja sanoi: \"Kirottu olkoon se mies, joka syö mitään ennen iltaa ja ennen kuin minä olen kostanut vihollisilleni\". Ja koko kansa oli ruokaa maistamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Ja kun he kaikki tulivat metsään, oli maassa hunajata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Kun kansa tuli kennokakkujen ääreen, niin katso, niistä vuoti hunajata, mutta ei kukaan vienyt kättään suuhun, sillä kansa pelkäsi valaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Mutta Joonatan ei ollut kuulemassa, kun hänen isänsä vannotti kansan; niin hän ojensi sauvan, joka oli hänen kädessään, pisti sen kärjen kennokakkuun ja vei sitten kätensä suuhunsa, ja silloin hänen silmänsä kirkastuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Mutta eräs mies väestä puhkesi puhumaan ja sanoi: \"Sinun isäsi vannotti väen ja sanoi: \'Kirottu olkoon se mies, joka tänä päivänä syö mitään\'\". Ja väki oli näännyksissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Joonatan vastasi: \"Isäni on syössyt maan onnettomuuteen. Katsokaa, kuinka minun silmäni kirkastuivat, kun vähän maistoin tätä hunajata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Jos myös väki olisi tänä päivänä saanut syödä vihollisiltaan ottamaansa saalista, niin eiköhän filistealaisten tappio olisi ollut vieläkin suurempi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Ja he voittivat sinä päivänä filistealaiset ja ajoivat heitä takaa Mikmaasta Aijaloniin asti; ja väki oli kovin näännyksissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Sentähden väki syöksyi saaliin kimppuun ja otti lampaita, raavaita ja vasikoita ja teurasti niitä paljaan maan päällä; ja väki söi lihan verinensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'Niin Saulille ilmoitettiin tämä: \"Katso, väki tekee syntiä Herraa vastaan, kun syö lihaa verinensä\". Hän sanoi: \"Te olette menetelleet uskottomasti; vierittäkää nyt tänne minun eteeni suuri kivi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Ja Saul sanoi: \"Menkää väen sekaan ja sanokaa heille: \'Tuokaa jokainen härkänne ja lampaanne minun luokseni ja teurastakaa ne täällä. Sitten syökää; älkääkä tehkö syntiä Herraa vastaan syömällä lihaa verinensä.\'\" Niin väestä jokainen silloin yöllä toi omin käsin härkänsä ja teurasti sen siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'Ja Saul rakensi alttarin Herralle; tämä oli ensimmäinen alttari, jonka hän Herralle rakensi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'Ja Saul sanoi: \"Lähtekäämme tänä yönä filistealaisten jälkeen ja ryöstäkäämme heitä, kunnes aamu valkenee, ja älkäämme jättäkö heistä jäljelle ainoatakaan\". He vastasivat: \"Tee kaikki, mitä hyväksi näet\". Mutta pappi sanoi: \"Astukaamme tänne Jumalan eteen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Silloin Saul kysyi Jumalalta: \"Lähdenkö minä filistealaisten jälkeen? Annatko sinä heidät Israelin käsiin?\" Mutta hän ei vastannut hänelle sinä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Niin Saul sanoi: \"Tulkaa tänne, kaikki kansan päämiehet, saadaksenne tietää ja nähdä, mikä synti nyt on tähän syynä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Sillä niin totta kuin Herra elää, hän, joka on antanut Israelille voiton: vaikka syy olisi minun poikani Joonatanin, niin hänen on kuoltava.\" Mutta ei kukaan koko kansasta vastannut hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Silloin hän sanoi koko Israelille: \"Olkaa te toisella puolella, niin minä ja minun poikani Joonatan olemme toisella puolella\". Kansa vastasi Saulille: \"Tee, niinkuin hyväksi näet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Ja Saul sanoi Herralle, Israelin Jumalalle: \"Anna oikea arpa\". Niin arpa osui Joonataniin ja Sauliin, ja kansa pääsi vapaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Saul sanoi: \"Heittäkää arpaa minun ja minun poikani Joonatanin välillä\". Niin arpa osui Joonataniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Ja Saul sanoi Joonatanille: \"Ilmaise minulle, mitä olet tehnyt\". Joonatan ilmaisi sen hänelle ja sanoi: \"Minä maistoin vähän hunajata sauvan kärjellä, joka oli kädessäni; katso, minä olen valmis kuolemaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Ja Saul sanoi: \"Jumala rangaiskoon minua nyt ja vasta: sinun on kuolemalla kuoltava, Joonatan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Mutta kansa sanoi Saulille: \"Onko Joonatanin kuoltava, hänen, joka on hankkinut tämän suuren voiton Israelille? Pois se! Niin totta kuin Herra elää: ei saa hiuskarvakaan pudota maahan hänen päästänsä; sillä Jumalan avulla hän on sen tänä päivänä tehnyt.\" Näin kansa vapahti Joonatanin kuolemasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Sitten Saul meni eikä ajanut filistealaisia takaa; ja filistealaiset menivät kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Kun nyt Saul oli saanut kuninkuuden Israelissa, soti hän kaikkia vihollisiansa vastaan joka taholla: mooabilaisia, ammonilaisia, edomilaisia, Sooban kuninkaita ja filistealaisia vastaan; ja minne tahansa hän kääntyi, siellä hän rankaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Ja hän teki väkeviä tekoja ja voitti amalekilaiset ja vapautti Israelin sen ryöstäjäin käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Saulin pojat olivat Joonatan, Jisvi ja Malkisua; ja hänen kahden tyttärensä nimet olivat: vanhemman nimi Meerab ja nuoremman nimi Miikal.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Ja Saulin vaimon nimi oli Ahinoam, Ahimaan tytär. Ja hänen sotapäällikkönsä nimi oli Abner, Neerin, Saulin sedän, poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Sillä Kiis, Saulin isä, ja Neer, Abnerin isä, olivat Abielin poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'Mutta filistealaisia vastaan käytiin kiivaasti sotaa, niin kauan kuin Saul eli. Ja kenen vain Saul tapasi urhoollisen ja sotakuntoisen miehen, sen hän otti luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Mutta Samuel sanoi Saulille: \"Minut Herra lähetti voitelemaan sinut kansansa Israelin kuninkaaksi. Kuule siis Herran ääntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Näin sanoo Herra Sebaot: Minä kostan Amalekille sen, mitä hän teki Israelille asettumalla hänen tielleen, kun hän tuli Egyptistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Mene siis ja voita amalekilaiset, ja vihkikää tuhon omaksi kaikki, mitä heillä on; äläkä säästä heitä, vaan surmaa miehet ja naiset, lapset ja imeväiset, raavaat ja lampaat, kamelit ja aasit.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Saul kuulutti kansan kokoon ja piti heistä katselmuksen Telaimissa: kaksisataa tuhatta jalkamiestä ynnä kymmenentuhatta Juudan miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Kun Saul tuli lähelle amalekilaisten kaupunkia, asettui hän laaksoon väijyksiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'Ja Saul sanoi keeniläisille: \"Tulkaa, erotkaa ja siirtykää pois amalekilaisten joukosta, etten minä hukuttaisi teitä heidän kanssansa; sillä te teitte laupeuden kaikille israelilaisille, kun he tulivat Egyptistä\". Niin keeniläiset erosivat amalekilaisista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'Ja Saul voitti amalekilaiset ja ajoi heitä takaa Havilasta Suuriin päin, joka on Egyptistä itään päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Ja hän otti Agagin, Amalekin kuninkaan, elävänä vangiksi, mutta kaiken kansan hän vihki tuhon omaksi miekan terällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Mutta Saul ja väki säästivät Agagin sekä parhaimmat lampaat, lihavimmat raavaat ja karitsat, kaiken, mikä oli arvokasta; sitä he eivät tahtoneet vihkiä tuhon omaksi. Mutta kaiken karjan, mikä oli halpaa ja arvotonta, he vihkivät tuhon omaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Silloin Samuelille tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, '\"Minä kadun, että tein Saulin kuninkaaksi, sillä hän on kääntynyt pois minusta eikä ole täyttänyt minun käskyjäni\". Samuel pahastui, ja hän huusi Herraa kaiken sen yön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'Varhain seuraavana aamuna Samuel lähti tapaamaan Saulia. Mutta Samuelille ilmoitettiin: \"Saul on mennyt Karmeliin ja pystyttänyt sinne itsellensä muistomerkin; sitten hän on palannut sieltä ja mennyt alas Gilgaliin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Kun Samuel tuli Saulin luo, sanoi Saul hänelle: \"Herra siunatkoon sinua! Minä olen täyttänyt Herran käskyn.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Mutta Samuel sanoi: \"Mitä tämä lammasten määkiminen sitten on, joka kuuluu minun korviini, ja tämä raavaiden ammuminen, jonka kuulen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Saul vastasi: \"Amalekilaisilta ne on tuotu; sillä kansa säästi parhaat lampaat ja raavaat uhrataksensa ne Herralle, sinun Jumalallesi; mutta muut me olemme vihkineet tuhon omiksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Silloin Samuel sanoi Saulille: \"Lopeta; minä ilmoitan sinulle, mitä Herra on minulle tänä yönä puhunut\". Hän sanoi hänelle: \"Puhu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'Samuel sanoi: \"Sinä olet Israelin sukukuntien päämies, vaikka oletkin vähäinen omissa silmissäsi: Herra on voidellut sinut Israelin kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Ja Herra lähetti sinut matkaan ja sanoi: \'Mene ja vihi tuhon omiksi nämä syntiset, amalekilaiset, ja sodi heitä vastaan, kunnes olet tehnyt heistä lopun\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Miksi et kuullut Herran ääntä, vaan syöksyit saaliin kimppuun ja teit sitä, mikä on pahaa Herran silmissä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Saul vastasi Samuelille: \"Minähän olen kuullut Herran ääntä ja tehnyt sen matkan, jolle Herra minut lähetti. Minä olen tuonut tänne Agagin, Amalekin kuninkaan, ja vihkinyt tuhon omiksi amalekilaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Mutta väki on ottanut saaliista lampaita ja raavaita, parhaan osan siitä, mikä oli vihitty tuhon omaksi, uhrataksensa ne Herralle, sinun Jumalallesi, Gilgalissa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Silloin Samuel sanoi: \"Haluaako Herra polttouhreja ja teurasuhreja yhtä hyvin kuin kuuliaisuutta Herran äänelle? Katso, kuuliaisuus on parempi kuin uhri ja tottelevaisuus parempi kuin oinasten rasva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Sillä tottelemattomuus on taikuuden syntiä, ja niskoittelu on valhetta ja kuin kotijumalain palvelusta. Koska sinä olet hyljännyt Herran sanan, on myös hän hyljännyt sinut, etkä sinä enää saa olla kuninkaana.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'Saul sanoi Samuelille: \"Minä olen tehnyt syntiä, kun olen rikkonut Herran käskyn ja sinun sanasi; sillä minä pelkäsin kansaa ja kuulin heidän ääntänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Anna nyt minulle syntini anteeksi ja palaja minun kanssani, niin minä kumartaen rukoilen Herraa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Samuel sanoi Saulille: \"Minä en palaja sinun kanssasi; sillä sinä olet hyljännyt Herran sanan, ja Herra on myös hyljännyt sinut, niin että et enää saa olla Israelin kuninkaana\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Kun sitten Samuel kääntyi menemään pois, tarttui Saul hänen viittansa liepeeseen, niin että se repesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Ja Samuel sanoi hänelle: \"Herra on tänä päivänä reväissyt Israelin kuninkuuden sinulta ja antanut sen toiselle, joka on sinua parempi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Ja hän, joka on Israelin kunnia, ei valhettele eikä kadu; sillä hän ei ole ihminen, että hän katuisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Hän vastasi: \"Minä olen syntiä tehnyt; mutta osoita minulle kuitenkin se kunnia kansani vanhimpien edessä ja Israelin edessä, että palajat minun kanssani, niin minä kumartaen rukoilisin Herraa, sinun Jumalaasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Niin Samuel palasi Saulin jäljessä; ja Saul kumartaen rukoili Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Ja Samuel sanoi: \"Tuokaa minun eteeni Agag, Amalekin kuningas\". Ja Agag tuli iloisesti hänen eteensä; ja Agag sanoi: \"Totisesti on katkera kuolema väistynyt pois\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Mutta Samuel sanoi: \"Niinkuin sinun miekkasi on tehnyt vaimoja lapsettomiksi, niin on myös sinun äitisi tuleva lapsettomaksi ennen muita vaimoja\". Ja Samuel hakkasi Agagin kappaleiksi Herran edessä Gilgalissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Sitten Samuel lähti Raamaan, mutta Saul meni kotiinsa Saulin Gibeaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'Eikä Samuel enää nähnyt Saulia kuolinpäiväänsä asti, ja Samuel suri Saulia. Mutta Herra katui, että oli tehnyt Saulin Israelin kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Ja Herra sanoi Samuelille: \"Kuinka kauan sinä suret Saulia? Minähän olen hyljännyt hänet, niin ettei hän enää saa olla Israelin kuninkaana. Täytä sarvesi öljyllä ja mene; minä lähetän sinut beetlehemiläisen Iisain luo, sillä hänen pojistansa minä olen katsonut itselleni kuninkaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Mutta Samuel sanoi: \"Kuinka minä voisin mennä sinne? Jos Saul saa sen kuulla, tappaa hän minut.\" Herra vastasi: \"Ota mukaasi vasikka ja sano: \'Minä tulin uhraamaan Herralle\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'Kutsu sitten Iisai uhrille, niin minä ilmoitan sinulle, mitä sinun on tehtävä; ja voitele minulle se, jonka minä sinulle osoitan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel teki, niinkuin Herra oli puhunut. Mutta kun hän tuli Beetlehemiin, tulivat kaupungin vanhimmat vavisten häntä vastaan ja kysyivät: \"Tietääkö tulosi rauhaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'Hän vastasi: \"Rauhaa. Minä olen tullut uhraamaan Herralle. Pyhittäytykää ja tulkaa minun kanssani uhrille.\" Ja hän pyhitti Iisain ja hänen poikansa ja kutsui heidät uhrille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'Kun he sitten tulivat ja hän näki Eliabin, ajatteli hän: \"Varmaan on nyt tässä Herran edessä hänen voideltunsa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Mutta Herra sanoi Samuelille: \"Älä katso hänen näköänsä äläkä kookasta vartaloansa, sillä minä olen hänet hyljännyt. Sillä ei ole, niinkuin ihminen näkee: ihminen näkee ulkomuodon, mutta Herra näkee sydämen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Niin Iisai kutsui Abinadabin ja toi hänet Samuelin eteen. Mutta hän sanoi: \"Ei ole Herra tätäkään valinnut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Silloin Iisai toi Samman esille. Mutta hän sanoi: \"Ei ole Herra tätäkään valinnut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Niin toi Iisai seitsemän poikaansa Samuelin eteen. Mutta Samuel sanoi Iisaille: \"Herra ei ole valinnut ketään näistä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Ja Samuel kysyi Iisailta: \"Siinäkö olivat kaikki nuorukaiset?\" Hän vastasi: \"Vielä on nuorin jäljellä, mutta hän on kaitsemassa lampaita\". Niin Samuel sanoi Iisaille: \"Lähetä noutamaan hänet, sillä me emme istu ruualle, ennenkuin hän tulee tänne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Silloin tämä noudatti hänet; ja hän oli verevä, kaunissilmäinen ja sorea nähdä. Ja Herra sanoi: \"Nouse ja voitele tämä, sillä hän se on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Niin Samuel otti öljysarven ja voiteli hänet hänen veljiensä keskellä. Ja Herran henki tuli Daavidiin, siitä päivästä ja yhä edelleen. Sitten Samuel nousi ja meni Raamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Mutta Herran henki poistui Saulista, ja Herran lähettämä paha henki vaivasi häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'Niin Saulin palvelijat sanoivat hänelle: \"Katso, Jumalan lähettämä paha henki vaivaa sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Käskeköön vain herramme, niin palvelijasi, jotka ovat edessäsi, etsivät miehen, joka taitaa soittaa kannelta, että hän, kun Jumalan lähettämä paha henki tulee sinuun, soittaisi sitä, ja sinun olisi parempi olla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Silloin Saul sanoi palvelijoillensa: \"Katsokaa minulle mies, joka on taitava soittaja, ja tuokaa hänet minun luokseni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Niin eräs nuorista miehistä vastasi ja sanoi: \"Katso, minä olen nähnyt beetlehemiläisellä Iisailla pojan, joka taitaa soittaa ja joka on kelpo mies ja sotilas sekä ymmärtäväinen puheiltaan ja komea mies, ja Herra on hänen kanssaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Niin Saul lähetti sanansaattajat Iisain luo ja käski sanoa: \"Lähetä minun luokseni poikasi Daavid, joka kaitsee lampaita\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Ja Iisai otti aasin sekä leipää, viinileilin ja vohlan ja lähetti ne poikansa Daavidin mukana Saulille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Ja Daavid tuli Saulin luo ja rupesi palvelemaan häntä; ja hän tuli hänelle hyvin rakkaaksi ja pääsi hänen aseenkantajakseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'Ja Saul lähetti sanan Iisaille ja käski sanoa: \"Anna Daavidin jäädä minua palvelemaan, sillä hän on saanut armon minun silmieni edessä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'Niin usein kuin Jumalan lähettämä henki tuli Sauliin, otti Daavid kanteleen ja soitti sitä; silloin Saulin oli helpompi ja parempi olla, ja paha henki väistyi hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Mutta filistealaiset kokosivat joukkonsa sotaan, ja he kokoontuivat lähelle Sookoa, joka on Juudassa. Ja he leiriytyivät Sookon ja Asekan välille, Efes-Dammimiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Saul ja Israelin miehet olivat myös kokoontuneet ja leiriytyneet Tammilaaksoon; ja he asettuivat sotarintaan filistealaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'Filistealaiset olivat vuorella, joka oli toisella puolella, ja israelilaiset olivat vuorella, joka oli toisella puolella, ja laakso oli heidän välillänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'Niin filistealaisten joukoista tuli kaksintaistelija nimeltä Goljat, kotoisin Gatista. Hän oli kuuden kyynärän ja vaaksan pituinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'Hänellä oli vaskikypäri päässänsä ja suomuspanssari yllänsä, ja rintahaarniska, joka painoi viisituhatta sekeliä, oli vaskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Ja hänellä oli säärissään vaskivarukset ja selässään vaskikeihäs.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'Hänen peitsensä varsi oli niinkuin kangastukki, ja hänen peitsensä kärki, joka painoi kuusisataa sekeliä, oli rautaa. Ja kilvenkantaja kävi hänen edellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'Hän astui esiin ja huusi Israelin taisteluriveille sanoen: \"Miksi te lähditte sotaan ja asetuitte sotarintaan? Minä olen filistealainen, ja te olette Saulin palvelijoita; valitkaa joukostanne mies, joka tulee tänne minun luokseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Jos hän kykenee taistelemaan minua vastaan ja surmaa minut, niin me olemme teidän palvelijanne; mutta jos minä voitan ja surmaan hänet, niin te olette meidän palvelijamme ja palvelette meitä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Ja filistealainen sanoi vielä: \"Minä olen tänä päivänä häväissyt Israelin taistelurivit. Antakaa tänne mies, niin me taistelemme keskenämme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'Kun Saul ja koko Israel kuuli nämä filistealaisen puheet, valtasi heidät kauhu, ja he pelkäsivät suuresti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'Mutta Daavid oli sen efratilaisen miehen poika Juudan Beetlehemistä, jonka nimi oli Iisai, ja tällä oli kahdeksan poikaa; hän oli Saulin aikana jo vanha, iäkäs mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'Ja Iisain kolme vanhinta poikaa oli seurannut Saulia sotaan; ja näiden hänen kolmen sotaan lähteneen poikansa nimet olivat: esikoisen Eliab, toisen Abinadab ja kolmannen Samma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'Daavid oli nuorin. Ja nuo kolme vanhinta olivat seuranneet Saulia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Mutta Daavid lähti tuontuostakin Saulin luota Beetlehemiin kaitsemaan isänsä lampaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Ja filistealainen astui esiin haastaen taisteluun joka aamu ja ilta, neljänäkymmenenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Ja Iisai sanoi pojallensa Daavidille: \"Ota veljillesi eefa-mitta näitä paahdettuja jyviä ja nämä kymmenen leipää, ja vie ne kiiruusti leiriin veljillesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'Ja vie nämä kymmenen juustoa tuhannenpäämiehelle. Tiedustele veljiesi vointia ja hanki varmuus, että lähetys on heille saapunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Saul ja he ynnä kaikki Israelin miehet ovat Tammilaaksossa sotimassa filistealaisia vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Varhain seuraavana aamuna Daavid jätti lampaat vartijan haltuun, otti kantamuksensa ja lähti matkalle, niinkuin Iisai oli häntä käskenyt. Kun hän tuli leiriin, lähti sotaväki taistelurintaan ja nosti sotahuudon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Ja Israel ja filistealaiset asettuivat sotarintaan toisiansa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Niin Daavid heitti tavarat selästänsä kuormaston vartijalle ja riensi sotarintaan; ja sinne tultuaan hän tervehti veljiänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'Kun hän puhutteli heitä, niin katso, kaksintaistelija, Goljat niminen filistealainen, kotoisin Gatista, tuli filistealaisten taisteluriveistä ja puhui niinkuin ennenkin; ja Daavid kuuli sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Ja kun israelilaiset näkivät tuon miehen, pakenivat he häntä kaikki ja pelkäsivät suuresti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'Ja Israelin miehet sanoivat: \"Katsokaa miestä, joka tuolla tulee! Hän tulee häpäisemään Israelia. Mutta sen miehen, joka surmaa hänet, kuningas tekee hyvin rikkaaksi ja antaa hänelle tyttärensä ja tekee hänen isänsä perheen veroista vapaaksi Israelissa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Niin Daavid sanoi miehille, jotka seisoivat siinä hänen kanssaan: \"Mitä saa se mies, joka surmaa tuon filistealaisen ja poistaa häväistyksen Israelista? Sillä mikä tuo ympärileikkaamaton filistealainen on häpäisemään elävän Jumalan taistelurivejä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'Väki sanoi hänelle saman, minkä ennenkin: sen ja sen saa se mies, joka surmaa hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Mutta kun hänen vanhin veljensä Eliab kuuli hänen puhuvan miesten kanssa, vihastui Eliab Daavidiin ja sanoi: \"Miksi sinä olet tullut tänne, ja kenelle olet jättänyt sen pienen lammaslauman siellä erämaassa? Minä tunnen sinun julkeutesi ja pahan sisusi; sinä olet tullut tänne katsomaan sotaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Daavid vastasi: \"Mitä minä sitten olen tehnyt? Saaneehan tuon verran kysyä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'Ja hän kääntyi hänen luotansa toisen puoleen ja kysyi niinkuin ennenkin; ja väki vastasi hänelle samoin kuin äsken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'Mutta tuli tunnetuksi, mitä Daavid oli puhunut; ja se kerrottiin Saulille, ja tämä noudatti hänet luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'Ja Daavid sanoi Saulille: \"Älköön kenenkään mieli masentuko hänen tähtensä. Palvelijasi käy taistelemaan tuota filistealaista vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Saul sanoi Daavidille: \"Et sinä voi mennä tuota filistealaista vastaan etkä taistella hänen kanssaan, sillä sinä olet nuorukainen, mutta hän on sotilas nuoruudestansa saakka\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'Mutta Daavid sanoi Saulille: \"Palvelijasi on ollut kaitsemassa isänsä lampaita. Jos leijona tai karhu tuli ja vei lampaan laumasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'niin minä hyökkäsin sen jälkeen, löin sen maahan ja tempasin saaliin sen suusta; ja jos se karkasi minua vastaan, niin minä tartuin sen partaan, löin sen maahan ja tapoin sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'Kun palvelijasi on lyönyt maahan sekä leijonan että karhun, niin tuolle ympärileikkaamattomalle filistealaiselle käy niinkuin niille; sillä hän on häväissyt elävän Jumalan taistelurivejä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Ja Daavid sanoi: \"Herra, joka on pelastanut minut leijonan ja karhun kynsistä, pelastaa minut myös tämän filistealaisen käsistä\". Silloin Saul sanoi Daavidille: \"Mene; Herra olkoon sinun kanssasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'Ja Saul puki takkinsa Daavidin ylle ja pani vaskikypärin hänen päähänsä sekä panssarin hänen yllensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Ja Daavid sitoi hänen miekkansa vyölleen takin päälle ja yritti käydä, sillä hän ei ollut koskaan sellaisia koettanut. Niin Daavid sanoi Saulille: \"En minä voi näissä käydä, sillä en ole koskaan tällaisia koettanut\". Ja Daavid riisui ne päältänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Ja hän otti sauvansa käteensä, valitsi purosta viisi sileätä kiveä, pani ne paimenlaukkuun, joka hänellä oli linkokivisäiliönä, otti lingon käteensä ja meni filistealaista vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Ja filistealainen tuli yhä lähemmäksi Daavidia, ja kilvenkantaja kulki hänen edellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'Kun filistealainen katsahti ja näki Daavidin, halveksi hän häntä; sillä hän oli vielä nuorukainen, verevä ja kaunis näöltään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Niin filistealainen sanoi Daavidille: \"Olenko minä koira, kun tulet sauva kädessä minua vastaan?\" Ja filistealainen kiroili Daavidia vannoen jumaliensa kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Sitten filistealainen sanoi Daavidille: \"Tule tänne minun luokseni, niin minä annan sinun lihasi taivaan linnuille ja metsän eläimille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Mutta Daavid sanoi filistealaiselle: \"Sinä tulet minua vastaan miekan, peitsen ja keihään voimalla, mutta minä tulen sinua vastaan Herran Sebaotin nimeen, Israelin sotajoukon Jumalan, jota sinä olet häväissyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Tänä päivänä Herra antaa sinut minun käsiini, ja minä surmaan sinut, katkaisen sinulta pään ja annan filistealaisten sotajoukon ruumiit tänä päivänä taivaan linnuille ja metsän pedoille; ja kaikki maat tulevat tietämään, että Israelilla on Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'Ja koko tämä suuri joukko tulee tietämään, ettei Herra anna voittoa miekan eikä keihään voimalla; sillä sota on Herran, ja hän antaa teidät meidän käsiimme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'Kun filistealainen lähti tulemaan ja lähestyi Daavidia, niin Daavid juoksi nopeasti sotarintaan filistealaista vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'Ja Daavid pisti kätensä reppuunsa ja otti sieltä kiven, linkosi ja satutti filistealaista otsaan, niin että kivi upposi hänen otsaansa, ja hän kaatui maahan kasvoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Niin sai Daavid voiton filistealaisesta lingolla ja kivellä ja löi filistealaisen kuoliaaksi, eikä Daavidilla ollut miekkaa kädessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'Sitten Daavid juoksi ja asettui filistealaisen ääreen, tarttui hänen miekkaansa, veti sen tupesta ja tappoi hänet ja löi sillä häneltä pään poikki. Kun filistealaiset näkivät, että heidän sankarinsa oli kuollut, pakenivat he.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Mutta Israelin ja Juudan miehet nousivat, nostivat sotahuudon ja ajoivat filistealaisia takaa laakson suulle ja Ekronin porteille saakka; ja filistealaisia kaatui surmattuina Saaraimin tiellä, aina Gatiin ja Ekroniin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'Sitten israelilaiset palasivat ajamasta filistealaisia takaa ja ryöstivät heidän leirinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Ja Daavid otti filistealaisen pään ja vei sen Jerusalemiin, mutta hänen aseensa hän asetti majaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Kun Saul näki Daavidin menevän filistealaista vastaan, kysyi hän sotapäälliköltään Abnerilta: \"Kenen poika tuo nuorukainen on, Abner?\" Abner vastasi: \"Niin totta kuin sinä, kuningas, elät, minä en sitä tiedä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Niin kuningas sanoi: \"Kysele sitten, kenen poika tuo nuori mies on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Ja kun Daavid palasi takaisin surmattuaan filistealaisen, otti Abner hänet ja vei hänet Saulin eteen, ja hänellä oli kädessään filistealaisen pää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'Niin Saul kysyi häneltä: \"Kenen poika sinä olet, nuorukainen?\" Daavid vastasi: \"Palvelijasi beetlehemiläisen Iisain poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'Kun hän oli lakannut puhumasta Saulin kanssa, kiintyi Joonatan kaikesta sielustaan Daavidiin, ja Joonatan rakasti häntä niinkuin omaa sieluansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'Ja Saul otti hänet sinä päivänä luoksensa eikä sallinut hänen enää palata isänsä kotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Ja Joonatan teki liiton Daavidin kanssa, sillä hän rakasti häntä niinkuin omaa sieluansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'Ja Joonatan riisui viitan, joka hänellä oli yllänsä, ja antoi sen Daavidille, ja samoin takkinsa, vieläpä miekkansa, jousensa ja vyönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'Daavid lähti, minne vain Saul hänet lähetti, ja hän menestyi. Niin Saul asetti hänet sotamiesten päälliköksi, ja se oli mieleen kaikelle kansalle ja myös Saulin palvelijoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Ja kun he olivat tulossa, silloin kun Daavid palasi takaisin surmattuansa filistealaisen, menivät naiset kaikista Israelin kaupungeista laulaen ja karkeloiden kuningas Saulia vastaan, riemuiten, vaskirumpuja ja kymbaaleja lyöden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'Ja karkeloivat naiset virittivät laulun ja sanoivat: \"Saul voitti tuhat, mutta Daavid kymmenen tuhatta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Silloin Saul vihastui kovin, sillä hän pani sen puheen pahakseen, ja hän sanoi: \"Daavidille he antavat kymmenen tuhatta, ja minulle he antavat tuhat; nyt puuttuu häneltä enää vain kuninkuus\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Ja Saul katsoi karsain silmin Daavidia siitä päivästä alkaen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'Seuraavana päivänä Jumalan lähettämä paha henki valtasi Saulin, niin että hän raivosi kotonansa; mutta Daavid soitteli, niinkuin muulloinkin joka päivä, ja Saulilla oli kädessänsä keihäs.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'Niin Saul heitti keihään ja ajatteli: \"Minä keihästän Daavidin seinään\". Mutta Daavid väisti häntä kaksi kertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'Ja Saul pelkäsi Daavidia, koska Herra oli hänen kanssansa, mutta oli poistunut Saulista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Sentähden Saul toimitti hänet pois luotansa ja teki hänet tuhannenpäämieheksi; ja hän lähti ja tuli väen edellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Ja Daavid menestyi kaikilla teillään, ja Herra oli hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Kun Saul näki, että hänellä oli niin suuri menestys, rupesi hän häntä kammomaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Mutta koko Israel ja Juuda rakasti Daavidia, koska hän lähti ja tuli heidän edellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'Ja Saul sanoi Daavidille: \"Katso, vanhimman tyttäreni, Meerabin, minä annan sinulle vaimoksi; ole vain urhoollinen ja käy Herran sotia\". Sillä Saul ajatteli: \"Minun käteni älköön sattuko häneen, vaan sattukoon häneen filistealaisten käsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Mutta Daavid vastasi Saulille: \"Mikä minä olen, mikä on minun elämäni ja mikä on isäni suku Israelissa, että minä tulisin kuninkaan vävyksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Kun aika tuli, että Saulin tytär Meerab oli annettava Daavidille, annettiinkin hänet vaimoksi meholalaiselle Adrielille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Mutta Saulin tytär Miikal rakasti Daavidia. Ja kun se ilmoitettiin Saulille, oli se hänelle mieleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Sillä Saul ajatteli: \"Minä annan hänet Daavidille, että hän tulisi hänelle ansaksi ja filistealaisten käsi sattuisi häneen\". Niin Saul sanoi Daavidille: \"Nyt voit toisen kerran tulla minun vävykseni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Ja Saul käski palvelijoitansa: \"Puhukaa salaa Daavidille näin: \'Katso, kuningas on mieltynyt sinuun, ja kaikki hänen palvelijansa rakastavat sinua; sinun on nyt tultava kuninkaan vävyksi\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'Niin Saulin palvelijat puhuivat nämä sanat Daavidille. Mutta Daavid sanoi: \"Onko teidän mielestänne niin pieni asia tulla kuninkaan vävyksi? Minähän olen köyhä ja halpa mies.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Saulin palvelijat ilmoittivat hänelle tämän, sanoen: \"Näin on Daavid puhunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Niin Saul sanoi: \"Sanokaa Daavidille näin: \'Kuningas ei halua muuta morsiamenhintaa kuin sata filistealaisten esinahkaa, että kuninkaan vihollisille kostettaisiin\'\". Sillä Saul ajatteli kaataa Daavidin filistealaisten käden kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Kun hänen palvelijansa ilmoittivat tämän Daavidille, miellytti Daavidia tulla näin kuninkaan vävyksi; ja ennenkuin määräaika oli kulunut umpeen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'nousi Daavid ja lähti miehineen ja kaatoi filistealaisia kaksisataa miestä. Ja Daavid toi heidän esinahkansa, täyden määrän, kuninkaalle, tullaksensa kuninkaan vävyksi. Silloin Saul antoi tyttärensä Miikalin hänelle vaimoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'Ja Saul näki ja ymmärsi, että Herra oli Daavidin kanssa, ja Saulin tytär Miikal rakasti häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Niin Saul pelkäsi vielä enemmän Daavidia, ja Saulista tuli koko elinajakseen Daavidin vihamies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'Mutta filistealaisten ruhtinaat lähtivät sotaan; ja niin usein kuin he lähtivät sotaan, oli Daavidilla suurempi menestys kuin kaikilla muilla Saulin palvelijoilla, niin että hänen nimensä tuli sangen kuuluisaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Ja Saul puhui pojallensa Joonatanille ja kaikille palvelijoillensa, että Daavid olisi surmattava. Mutta Saulin poika Joonatan oli suuresti mieltynyt Daavidiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'Sentähden Joonatan ilmaisi sen Daavidille ja sanoi: \"Minun isäni Saul koettaa saada sinut surmatuksi. Ole siis varuillasi huomenaamuna, kätkeydy ja pysy piilossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Mutta minä menen ja asetun isäni viereen kedolle, sinne, missä sinä olet, ja puhun sinusta isälleni; ja jos jotakin huomaan, niin minä ilmaisen sen sinulle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'Niin Joonatan puhui hyvää Daavidista isällensä Saulille ja sanoi hänelle: \"Älköön kuningas rikkoko palvelijaansa Daavidia vastaan, sillä hän ei ole rikkonut sinua vastaan, vaan hänen työnsä ovat olleet sinulle suureksi hyödyksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Hänhän pani henkensä kämmenelleen ja surmasi sen filistealaisen, ja niin Herra antoi suuren voiton koko Israelille; sinä olet itse nähnyt sen ja iloinnut. Miksi siis rikkoisit viatonta verta vastaan surmaamalla Daavidin syyttömästi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'Saul kuuli Joonatanin ääntä; ja Saul vannoi: \"Niin totta kuin Herra elää, häntä ei surmata\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'Niin Joonatan kutsui Daavidin, ja Joonatan ilmoitti hänelle kaiken tämän. Ja sitten Joonatan vei Daavidin Saulin tykö, ja hän palveli häntä niinkuin ennenkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'Kun sitten sota alkoi uudestaan, lähti Daavid taistelemaan filistealaisia vastaan ja tuotti heille suuren tappion, niin että he pakenivat hänen edestään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Mutta Herran lähettämä paha henki tuli Sauliin, kun hän istui kotonaan keihäs kädessä ja Daavid soitteli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'Niin Saul koetti keihästää Daavidin seinään; mutta hän väisti Saulia, ja tämä iski keihään seinään. Daavid pakeni ja pelastui sinä yönä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Niin Saul lähetti miehiä Daavidin kotiin vartioimaan häntä ja surmaamaan hänet aamulla. Mutta Daavidin vaimo Miikal ilmaisi sen hänelle ja sanoi: \"Jollet tänä yönä pelasta henkeäsi, niin sinä huomenna olet surman oma\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Ja Miikal laski Daavidin alas ikkunasta; ja hän lähti pakoon ja pelastui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Sitten Miikal otti kotijumalan ja asetti sen vuoteeseen, ja levitettyään vuohenkarvoista tehdyn kärpäsverkon sen pään yli hän peitti sen vaatteella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Ja kun Saul lähetti miehiä ottamaan Daavidia, sanoi hän: \"Hän on sairas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Niin Saul lähetti miehiä katsomaan Daavidia, sanoen: \"Tuokaa hänet vuoteessa tänne minun luokseni surmattavaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'Mutta kun miehet tulivat sisälle, niin katso, vuoteessa olikin kotijumala, vuohenkarvoista tehty kärpäsverkko pään päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'Niin Saul sanoi Miikalille: \"Miksi sinä olet minut näin pettänyt ja olet päästänyt minun vihamieheni pelastumaan?\" Miikal vastasi Saulille: \"Hän sanoi minulle: \'Päästä minut, muutoin minä surmaan sinut\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'Kun Daavid oli paennut ja pelastunut, meni hän Samuelin luo Raamaan ja kertoi hänelle kaikki, mitä Saul oli hänelle tehnyt. Ja hän ja Samuel menivät Naajotiin ja jäivät sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'Ja Saulille ilmoitettiin: \"Katso, Daavid on Raaman Naajotissa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Niin Saul lähetti miehiä ottamaan Daavidia. Mutta kun he näkivät profeettain joukon hurmoksissa ja Samuelin seisovan johtamassa heitä, tuli Jumalan henki Saulin miehiin, niin että hekin joutuivat hurmoksiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Kun se ilmoitettiin Saulille, lähetti hän toiset miehet; mutta hekin joutuivat hurmoksiin. Ja Saul lähetti vielä kolmannet miehet, mutta hekin joutuivat hurmoksiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Silloin hän itse lähti Raamaan. Ja kun hän tuli sen suuren vesisäiliön luo, joka on Seekussa, kysyi hän: \"Missä ovat Samuel ja Daavid?\" Hänelle vastattiin: \"He ovat Raaman Naajotissa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'Mutta kun hän oli menossa sinne, Raaman Naajotiin, tuli Jumalan henki häneenkin, niin että hän kulki hurmoksissa, kunnes tuli Raaman Naajotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'Silloin hänkin riisui vaatteensa ja joutui hurmoksiin Samuelin edessä; ja hän kaatui maahan ja makasi alastonna koko sen päivän ja koko sen yön. Sentähden on tapana sanoa: \"Onko Saulkin profeettain joukossa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Mutta Daavid pakeni Raaman Naajotista, tuli ja puhui Joonatanille: \"Mitä minä olen tehnyt? Mitä vääryyttä, mitä syntiä minä olen tehnyt sinun isääsi vastaan, kun hän väijyy henkeäni?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Tämä vastasi hänelle: \"Pois se! Et sinä kuole. Katso, isäni ei tee mitään, suurta eikä pientä, ilmoittamatta minulle. Miksi sitten isäni salaisi minulta tämän? Ei ole niin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'Mutta Daavid vielä vakuutti vannoen ja sanoi: \"Isäsi tietää, että minä olen saanut armon sinun silmiesi edessä; sentähden hän ajattelee: \'Älköön Joonatan saako tietää tätä, ettei hän tulisi murheelliseksi\'. Mutta niin totta kuin Herra elää ja niin totta kuin sinä itse elät: on vain askel minun ja kuoleman välillä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Niin Joonatan sanoi Daavidille: \"Mitä sinä vain lausut toivovasi, sen minä sinulle teen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Daavid sanoi Joonatanille: \"Katso, huomenna on uusikuu, ja minun pitäisi istua aterioimassa kuninkaan kanssa; mutta salli minun mennä ja kätkeytyä ulos kedolle ylihuomeniltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Jos isäsi kaipaa minua, niin sano: \'Daavid pyysi minulta, että saisi käväistä kaupungissaan Beetlehemissä, sillä koko suvulla on siellä jokavuotiset teurasuhrit\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Ja jos hän sanoo: \'Hyvä on\', niin voi palvelijasi olla rauhassa. Mutta jos hän vihastuu, niin tiedä, että hänellä on paha mielessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Tee siis laupeus palvelijallesi, koska olet ottanut palvelijasi Herran liittoon kanssasi. Mutta jos minussa on vääryys, niin surmaa sinä minut; sillä miksi sinä veisit minut isäsi eteen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'Joonatan sanoi: \"Pois se! Jos huomaan, että minun isälläni on paha mielessä sinua vastaan, niin minä sen varmasti sinulle ilmoitan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Mutta Daavid sanoi Joonatanille: \"Kunpa sitten joku ilmoittaisi minulle, antaako isäsi sinulle kovan vastauksen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Joonatan sanoi Daavidille: \"Tule, menkäämme ulos kedolle\". Niin he menivät molemmat ulos kedolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Ja Joonatan sanoi Daavidille: \"Minä vakuutan Herran, Israelin Jumalan, kautta, että koetan huomenna tai ylihuomenna tähän aikaan päästä selville isästäni; ja jos Daavidin asiat ovat hyvin, niin minä varmasti lähetän siitä tiedon ja ilmoitan sen sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Herra rangaiskoon Joonatania nyt ja vasta, jollen minä, jos isäni mielii tehdä sinulle pahaa, ilmoita sitä sinulle ja päästä sinua menemään rauhassa. Herra olkoon sinun kanssasi, niinkuin hän on ollut minun isäni kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Etkö sinäkin, jos minä silloin vielä elän, etkö sinäkin tee Herran laupeutta minulle, niin ettei minun tarvitse kuolla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Ethän koskaan kiellä laupeuttasi minun suvultani, et silloinkaan, kun Herra hävittää Daavidin vihamiehet kaikki tyynni maan päältä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Niin Joonatan teki liiton Daavidin suvun kanssa. Ja Herra vaati koston Daavidin vihamiehiltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Ja Joonatan vannotti vielä Daavidin heidän keskinäisen rakkautensa kautta, sillä hän rakasti häntä niinkuin omaa sieluansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Ja Joonatan sanoi hänelle: \"Huomenna on uusikuu, ja sinua kaivataan, kun paikkasi on tyhjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Mutta ylihuomenna mene nopeasti siihen paikkaan, johon kätkeydyit sinä päivänä, jona se teko tapahtui, ja istuudu Eselin kiven ääreen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Niin minä ammun kolme nuolta sen laitaa kohti, niinkuin ampuisin maaliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Sitten minä lähetän palvelijan sanoen: \'Mene ja hae nuolet\'. Jos minä silloin sanon palvelijalle: \'Katso, nuolet ovat takanasi, tännempänä, ota ne\', niin tule kotiin, sillä silloin voit olla rauhassa eikä mitään ole tekeillä; niin totta kuin Herra elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Mutta jos minä sanon sille nuorelle miehelle näin: \'Katso, nuolet ovat edessäsi, sinnempänä\', niin lähde, sillä Herra lähettää sinut pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Ja mitä minä ja sinä olemme keskenämme puhuneet, sen todistaja meidän välillämme, minun ja sinun, on Herra iankaikkisesti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'Niin Daavid kätkeytyi kedolle. Ja kun uusikuu tuli, istuutui kuningas aterialle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'Kuningas istui tavallisella istuimellansa, istuimella seinän vieressä. Ja Joonatan nousi seisomaan, ja Abner istuutui Saulin viereen. Mutta Daavidin paikka oli tyhjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Saul ei kuitenkaan sanonut mitään sinä päivänä, sillä hän ajatteli: \"Jotakin on hänelle tapahtunut: hän ei liene puhdas; varmaankaan hän ei ole puhdas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'Mutta kun Daavidin paikka oli tyhjä seuraavanakin päivänä, toisena uudenkuun päivänä, sanoi Saul pojallensa Joonatanille: \"Miksi ei Iisain poika ole eilen eikä tänään tullut aterialle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Joonatan vastasi Saulille: \"Daavid pyysi minulta, että saisi mennä Beetlehemiin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'hän sanoi: \'Salli minun mennä, sillä meillä on suvun teurasuhrit kaupungissa, ja veljeni itse on käskenyt minut sinne; jos minä siis olen saanut armon sinun silmiesi edessä, niin päästä minut katsomaan veljiäni\'. Sentähden hän ei ole tullut kuninkaan pöytään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Silloin Saul vihastui Joonataniin ja sanoi hänelle: \"Sinä säädyttömän naisen poika! Tiesinhän minä, että sinä olet mieltynyt Iisain poikaan, häpeäksi itsellesi ja häpeäksi äitisi hävylle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Sillä niin kauan kuin Iisain poika elää maan päällä, et sinä eikä sinun kuninkuutesi ole turvassa. Lähetä nyt noutamaan hänet minun luokseni, sillä hän on kuoleman oma.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Joonatan vastasi isälleen Saulille ja sanoi hänelle: \"Miksi hänet on surmattava? Mitä hän on tehnyt?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'Silloin Saul heitti keihään häntä kohti surmataksensa hänet. Niin Joonatan ymmärsi, että hänen isänsä oli päättänyt tappaa Daavidin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'Ja Joonatan nousi pöydästä, vihasta hehkuen, eikä syönyt mitään toisena uudenkuun päivänä, sillä hän oli murheissaan Daavidin tähden, koska hänen isänsä oli häväissyt tätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Seuraavana aamuna Joonatan lähti ulos kedolle, niinkuin hän oli sopinut Daavidin kanssa, ja hänellä oli mukanaan pieni poikanen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'Ja hän sanoi pojalle: \"Juokse noutamaan nuolet, jotka minä ammun\". Ja pojan juostessa hän ampui nuolen hänen ylitsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'Ja kun poika oli tulemassa siihen paikkaan, missä Joonatanin ampuma nuoli oli, huusi Joonatan pojalle ja sanoi: \"Nuoli on edessäsi, sinnempänä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Ja Joonatan huusi vielä pojalle: \"Riennä nopeasti, älä seisahtele!\" Niin Joonatanin poikanen otti nuolen ja tuli herransa luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'Eikä poika tiennyt asiasta mitään; ainoastaan Joonatan ja Daavid tiesivät sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Ja Joonatan antoi aseensa pojalle, joka hänellä oli mukanaan, ja sanoi hänelle: \"Mene ja vie nämä kaupunkiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Ja kun poika oli mennyt, nousi Daavid ylös etelän puolelta; ja hän lankesi kasvoilleen maahan ja kumartui kolme kertaa; ja he suutelivat toisiansa ja itkivät yhdessä; Daavid itki hillittömästi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'Ja Joonatan sanoi Daavidille: \"Mene rauhassa. Niin on, kuin me molemmat olemme vannoneet Herran nimeen ja sanoneet: \'Herra on todistaja meidän välillämme, minun ja sinun, ja minun jälkeläisteni ja sinun jälkeläistesi välillä iankaikkisesti\'. {20:43} Sitten Daavid nousi ja lähti, mutta Joonatan palasi kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Ja Daavid tuli pappi Ahimelekin luo Noobiin. Mutta Ahimelek tuli vavisten Daavidia vastaan ja kysyi häneltä: \"Miksi sinä tulet yksin, eikä ole ketään sinun kanssasi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'Daavid vastasi pappi Ahimelekille: \"Kuningas on käskenyt minut asialle ja sanoi minulle: \'Älköön kukaan saako tietää mitään siitä asiasta, jolle minä sinut lähetän, ja siitä käskystä, jonka minä olen sinulle antanut\'. Ja palvelijat minä olen määrännyt siihen ja siihen paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'Anna nyt minulle, mitä sinulla on, viisi leipää, tahi mitä muuta löytyy.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Pappi vastasi Daavidille ja sanoi: \"Tavallista leipää minulla ei ole; ainoastaan pyhää leipää on, jos vain palvelijat ovat karttaneet naisia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Daavid vastasi papille ja sanoi hänelle: \"Totisesti olivat naiset eristettyinä meistä niinkuin ennenkin, milloin minä olen retkelle lähtenyt; ovatpa palvelijain reputkin aina olleet pyhät, vaikka retki on ollutkin tavallinen retki. Sitä enemmän leipä repuissa nyt pysyy pyhänä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Niin pappi antoi hänelle pyhää leipää; sillä siellä ei ollut muuta leipää kuin näkyleipiä, jotka oli siirretty pois Herran edestä, että sinne samana päivänä, jona ne oli otettu pois, pantaisiin tuoreet leivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Mutta siellä oli sinä päivänä eristettynä Herran edessä eräs Saulin palvelija, nimeltä Dooeg, edomilainen, Saulin paimenten päämies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'Ja Daavid kysyi vielä Ahimelekiltä: \"Eikö sinulla ole täällä yhtään keihästä tai miekkaa? Sillä minä en ottanut mukaani, en miekkaani enkä muita aseitani, koska kuninkaan asia oli niin kiireellinen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Pappi vastasi: \"On, sen filistealaisen Goljatin miekka, jonka sinä surmasit Tammilaaksossa; katso, se on vaippaan käärittynä tuolla kasukan takana. Jos tahdot ottaa itsellesi sen, niin ota; sillä muuta kuin se ei täällä ole.\" Daavid sanoi: \"Ei ole toista sen vertaista; anna se minulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'Sitten Daavid nousi ja pakeni sinä päivänä Saulia ja tuli Aakiin, Gatin kuninkaan, luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Mutta Aakiin palvelijat sanoivat hänelle: \"Eikö tämä ole Daavid, sen maan kuningas? Eivätkö he karkeloiden virittäneet hänelle tätä laulua: \'Saul voitti tuhat, mutta Daavid kymmenentuhatta\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'Daavid pani mieleensä nämä sanat ja pelkäsi suuresti Aakista, Gatin kuningasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Niin hän tekeytyi mielipuoleksi heidän silmiensä edessä ja raivosi heidän käsissään ja piirusteli portin oviin ja valutti sylkeä partaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Silloin Aakis sanoi palvelijoilleen: \"Näettehän, että mies on hullu. Miksi toitte hänet minun luokseni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Puuttuuko minulta hulluja, kun toitte tämän hulluttelemaan minun eteeni? Tällainenko saisi tulla minun hoviini?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Niin Daavid lähti sieltä ja pääsi pakoon Adullamin luolaan. Ja kun hänen veljensä ja koko hänen isänsä perhe kuulivat sen, tulivat he sinne hänen luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'Ja hänen luoksensa kokoontui kaikenlaista ahdingossa olevaa, velkaantunutta ja katkeroitunutta väkeä, ja hän rupesi heidän päämiehekseen. Näin liittyi häneen noin neljäsataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'Sieltä Daavid meni Mooabin Mispeen. Ja hän sanoi Mooabin kuninkaalle: \"Salli minun isäni ja äitini tulla asumaan teidän luoksenne, kunnes saan tietää, mitä Jumala minulle tekee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'Ja hän vei heidät Mooabin kuninkaan eteen; ja he jäivät tämän luo kaikeksi aikaa, minkä Daavid oli vuorilinnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Mutta profeetta Gaad sanoi Daavidille: \"Älä jää vuorilinnaan; lähde täältä ja mene Juudan maahan\". Niin Daavid lähti ja tuli Jaar-Heretiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'Ja Saul kuuli, että oli saatu vihiä Daavidista ja niistä miehistä, jotka olivat hänen kanssaan; ja Saul istui Gibeassa tamariskipuun alla kummulla, keihäs kädessä, ja kaikki hänen palvelijansa seisoivat hänen luonaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Niin Saul sanoi palvelijoilleen, jotka seisoivat hänen luonaan: \"Kuulkaa, benjaminilaiset! Antaako Iisain poika teillekin kaikille pellot ja viinitarhat, ja tekeekö hän teidät kaikki tuhannen-ja sadanpäämiehiksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Tehän olette kaikki salaliitossa minua vastaan, eikä kukaan ole ilmaissut minulle, että oma poikani on tehnyt liiton Iisain pojan kanssa. Ei kukaan teistä välitä niin paljoa minusta, että olisi ilmaissut sen minulle. Sillä minun poikani on yllyttänyt palvelijani väijymään minua, niinkuin nyt tapahtuu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Niin edomilainen Dooeg, joka seisoi siinä Saulin palvelijain kanssa, vastasi ja sanoi: \"Minä näin Iisain pojan tulevan Noobiin, Ahimelekin, Ahitubin pojan, luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Tämä kysyi hänelle neuvoa Herralta ja evästi hänet ja antoi hänelle filistealaisen Goljatin miekan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Silloin kuningas lähetti kutsumaan pappi Ahimelekin, Ahitubin pojan, ja koko hänen isänsä suvun, Noobin papit. Ja he tulivat kaikki kuninkaan luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Niin Saul sanoi: \"Kuule, Ahitubin poika!\" Hän vastasi: \"Tässä olen, Herrani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'Saul sanoi hänelle: \"Miksi te olette salaliitossa minua vastaan, sinä ja Iisain poika, koska sinä olet antanut hänelle leipää ja miekan ja kysynyt hänelle Herralta neuvoa, että hän ryhtyisi väijymään minua, niinkuin nyt tapahtuu?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Ahimelek vastasi kuninkaalle ja sanoi: \"Kuka on kaikkien sinun palvelijaisi joukossa niin uskottu kuin Daavid, joka on kuninkaan vävy ja sinun henkivartiostosi päällikkö ja on korkeassa arvossa sinun hovissasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Enhän minä nyt ensi kertaa kysynyt hänelle Jumalalta neuvoa. Pois se! Älköön kuningas lukeko mitään viaksi minulle, palvelijalleen, älköönkä kaikelle minun isäni suvulle, sillä palvelijasi ei tietänyt kaikesta tästä vähän vähääkään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Mutta kuningas sanoi: \"Sinun on kuolemalla kuoltava, Ahimelek, sinun ja koko sinun isäsi suvun\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Ja kuningas sanoi henkivartijoille, jotka seisoivat hänen luonaan: \"Käykää tänne ja surmatkaa Herran papit, sillä hekin pitävät Daavidin puolta; ja vaikka tiesivät hänen paenneen, eivät he ilmoittaneet sitä minulle\". Mutta kuninkaan palvelijat eivät tahtoneet ojentaa kättään lyömään kuoliaaksi Herran pappeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Niin kuningas sanoi Dooegille: \"Käy sinä tänne ja lyö papit kuoliaaksi\". Ja edomilainen Dooeg astui esiin ja löi papit kuoliaaksi; ja hän tappoi sinä päivänä kahdeksankymmentä viisi pellavakasukkaa kantavaa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Myös pappiskaupungin Noobin asukkaat hän surmasi miekan terällä, sekä miehet että naiset, sekä lapset että imeväiset; jopa raavaat, aasit ja lampaatkin hän tappoi miekan terällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Ainoastaan yksi Ahimelekin, Ahitubin pojan, poika, nimeltä Ebjatar, pelastui ja pakeni Daavidin luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Ja Ebjatar kertoi Daavidille, että Saul oli tappanut Herran papit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'Niin Daavid sanoi Ebjatarille: \"Minä ymmärsin jo silloin, että edomilainen Dooeg, kun hän oli siellä, oli ilmaiseva sen Saulille. Minä olen syypää koko sinun isäsi suvun, joka hengen, kuolemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Jää minun luokseni, älä pelkää; sillä joka väijyy sinun henkeäsi, se väijyy minun henkeäni. Minun luonani sinä olet turvassa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Daavidille ilmoitettiin: \"Katso, filistealaiset ovat taistelemassa Kegilaa vastaan ja ryöstävät puimatantereita\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Niin Daavid kysyi Herralta: \"Menenkö minä ja lyönkö nämä filistealaiset maahan?\" Herra vastasi Daavidille: \"Mene, lyö filistealaiset maahan ja pelasta Kegila\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Mutta Daavidin miehet sanoivat hänelle: \"Mehän elämme pelossa jo täällä Juudassa. Menisimmekö vielä Kegilaan filistealaisten taistelurivejä vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Niin Daavid kysyi taas Herralta, ja Herra vastasi hänelle ja sanoi: \"Nouse ja mene alas Kegilaan; sillä minä annan filistealaiset sinun käsiisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Ja Daavid meni miehinensä Kegilaan ja ryhtyi taisteluun filistealaisia vastaan ja kuljetti heidän karjansa pois ja tuotti heille suuren tappion. Näin Daavid pelasti Kegilan asukkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Ja kun Ebjatar, Ahimelekin poika, pakeni Daavidin luo Kegilaan, seurasi kasukka hänen mukanaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Saulille ilmoitettiin, että Daavid oli mennyt Kegilaan. Niin Saul sanoi: \"Jumala on jättänyt hänet minun käsiini, sillä hän on itse sulkenut itsensä sisälle, kun on mennyt kaupunkiin, jossa on ovet ja salvat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'Sitten Saul kuulutti kaiken kansan sotaan, menemään alas Kegilaan, piirittämään Daavidia ja hänen miehiänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Kun Daavid sai tietää, että Saul hankki hänelle tuhoa, sanoi hän pappi Ebjatarille: \"Tuo tänne kasukka\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'Ja Daavid sanoi: \"Herra, Israelin Jumala! Sinun palvelijasi on kuullut, että Saul aikoo tulla Kegilaan hävittämään kaupungin minun tähteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Luovuttavatko Kegilan miehet minut hänen käsiinsä? Tuleeko Saul, niinkuin palvelijasi on kuullut? Herra, Israelin Jumala, ilmoita se palvelijallesi.\" Herra vastasi: \"Tulee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Ja Daavid kysyi vielä: \"Luovuttavatko Kegilan miehet minut ja minun mieheni Saulin käsiin?\" Herra vastasi: \"Luovuttavat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Niin Daavid nousi miehinensä, joita oli noin kuusisataa miestä, ja he lähtivät Kegilasta ja kuljeskelivat paikasta toiseen. Mutta kun Saulille kerrottiin, että Daavid oli päässyt pakoon Kegilasta, luopui hän retkestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'Ja Daavid oleskeli erämaassa vuorten huipuilla; hän oleskeli Siifin erämaan vuoristossa. Ja Saul etsi häntä kaiken aikaa, mutta Jumala ei antanut häntä tämän käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Daavid huomasi, että Saul oli lähtenyt väijymään hänen henkeänsä, ja Daavid oli Hooreksessa, Siifin erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Silloin Saulin poika Joonatan nousi ja meni Daavidin luo Hoorekseen ja rohkaisi häntä Jumalassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Hän sanoi hänelle: \"Älä pelkää; sillä minun isäni Saulin käsi ei ole tapaava sinua, vaan sinusta tulee Israelin kuningas, ja minä tulen olemaan lähinnä sinua. Myös minun isäni Saul tietää kyllä sen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'Sitten he molemmat tekivät liiton Herran edessä. Ja Daavid jäi Hoorekseen, mutta Joonatan palasi kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Mutta siifiläisiä meni Saulin luo Gibeaan, ja he sanoivat: \"Daavid piileksii meillä päin, vuorten huipuilla Hooreksessa, Gibeat-Hakilassa, joka on kallioerämaasta etelään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Niin tule nyt sinne, kuningas, milloin vain haluat tulla; me kyllä luovutamme hänet kuninkaan käsiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Saul sanoi: \"Herra siunatkoon teitä, kun te säälitte minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Menkää, pitäkää häntä vielä silmällä, tiedustelkaa ja katsokaa, missä paikassa hänen jalkansa liikkuu ja kuka hänet on siellä nähnyt; sillä minulle on sanottu, että hän on hyvin kavala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Katsokaa ja tiedustelkaa kaikki piilopaikat, joihin hän voi piiloutua. Palatkaa sitten minun luokseni ja tuokaa varmat tiedot, niin minä lähden teidän kanssanne. Ja jos hän on tässä maassa, niin minä etsin hänet kaikkien Juudan sukujen seasta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Ja he nousivat ja menivät Siifiin Saulin edellä. Mutta Daavid miehineen oli Maaonin erämaassa, aromaassa, kallioerämaasta etelään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Kun Saul miehineen meni etsimään Daavidia, ilmoitettiin se tälle, ja hän laskeutui eräälle kalliolle ja jäi Maaonin erämaahan. Kun Saul kuuli sen, lähti hän ajamaan Daavidia takaa Maaonin erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'Ja Saul kulki vuoren toista puolta ja Daavid miehineen vuoren toista puolta. Ja kun Daavid riensi pakoon Saulin tieltä ja Saul miehinensä oli kiertämässä Daavidia ja hänen miehiänsä, ottaaksensa heidät kiinni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'tuli sanansaattaja Saulin luo ja sanoi: \"Tule kiiruusti, sillä filistealaiset ovat hyökänneet maahan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Silloin Saul lakkasi ajamasta takaa Daavidia ja lähti filistealaisia vastaan. Siitä se paikka sai nimekseen Mahlekotkallio.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, '{24:1} Mutta Daavid lähti sieltä ja oleskeli Een-Gedin vuorten huipuilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, '{24:2} Ja kun Saul palasi ajamasta filistealaisia takaa, ilmoitettiin hänelle: \"Katso, Daavid on Een-Gedin erämaassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, '{24:3} Niin Saul otti kolmetuhatta valiomiestä koko Israelista ja meni etsimään Daavidia ja hänen miehiään Kauriskallioiden itäpuolelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, '{24:4} Ja kun hän tuli tien varrella oleville karjatarhoille, oli siellä luola; ja Saul meni luolaan tarpeelleen. Mutta Daavid ja hänen miehensä istuivat luolan perällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, '{24:5} Niin Daavidin miehet sanoivat hänelle: \"Katso, tämä on se päivä, josta Herra on sanonut sinulle: \'Minä annan vihamiehesi sinun käsiisi, tehdäksesi hänelle, mitä hyväksi näet\'\". Ja Daavid nousi ja leikkasi salaa kappaleen Saulin viitan liepeestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, '{24:6} Mutta sen jälkeen Daavidin omatunto soimasi häntä siitä, että hän oli leikannut Saulin viitan lievettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, '{24:7} Ja hän sanoi miehillensä: \"Pois se! Herra varjelkoon minua tekemästä sitä herralleni, Herran voidellulle, että satuttaisin käteni häneen; sillä hän on Herran voideltu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, '{24:8} Ja Daavid kovisti miehiänsä eikä sallinut heidän hyökätä Saulin kimppuun. Niin Saul nousi luolasta ja meni matkaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, '{24:9} Senjälkeen Daavid myös nousi, lähti luolasta ja huusi Saulin jälkeen: \"Minun herrani, kuningas!\" Kun Saul katsahti taaksensa, kumartui Daavid kasvoilleen maahan ja osoitti kunnioitusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, '{24:10} Ja Daavid sanoi Saulille: \"Miksi sinä kuuntelet ihmisten puhetta, jotka sanovat: \'Daavid hankkii sinulle onnettomuutta\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, '{24:11} Katso, näethän nyt omin silmin, kuinka Herra tänä päivänä antoi sinut minun käsiini luolassa, mutta minä säästin sinut, vaikka minua neuvottiin tappamaan sinut; sillä minä ajattelin: \'Minä en satuta kättäni herraani; sillä hän on Herran voideltu\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, '{24:12} Katso itse, isäni, katso tätä viittasi liepeen kappaletta, joka on minun kädessäni. Kun minä leikkasin sen sinun viittasi liepeestä enkä sinua tappanut, niin ymmärrä siitä ja näe, ettei minulla ole tekeillä mitään pahaa tai rikollista ja etten minä ole sinua vastaan rikkonut, vaikka sinä vainoat minua ottaaksesi minulta hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, '{24:13} Herra tuomitkoon meidän välillämme, minun ja sinun, ja Herra kostakoon sinulle minun puolestani, mutta minun käteni ei sinuun satu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, '{24:14} On, niinkuin vanha sananlasku sanoo: \'Jumalattomuus tulee jumalattomista\'; mutta minun käteni ei sinuun satu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, '{24:15} Kenen jälkeen Israelin kuningas on lähtenyt? Ketä sinä ajat takaa? Koiranraatoa, yhtä kirppua!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, '{24:16} Herra olkoon tuomari ja tuomitkoon meidän välillämme, minun ja sinun; hän nähköön ja ajakoon minun asiani ja auttakoon minut sinun käsistäsi oikeuteeni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, '{24:17} Kun Daavid oli päättänyt tämän puheensa Saulille, sanoi Saul: \"Eikö se ole sinun äänesi, poikani Daavid?\" Ja Saul korotti äänensä ja itki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, '{24:18} Ja hän sanoi Daavidille: \"Sinä olet minua vanhurskaampi, sillä sinä olet tehnyt minulle hyvää, vaikka minä olen tehnyt sinulle pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, '{24:19} Sinä olet tänä päivänä osoittanut hyvyyttäsi minua kohtaan, kun et tappanut minua, vaikka Herra oli antanut minut sinun käsiisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, '{24:20} Sillä kun joku kohtaa vihollisensa, päästääkö hän hänet menemään rauhassa? Herra palkitkoon sinulle runsaasti sen, mitä olet tänä päivänä tehnyt minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, '{24:21} Ja katso, nyt minä tiedän, että sinä tulet kuninkaaksi ja että Israelin kuninkuus on pysyvä sinun kädessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, '{24:22} Niin vanno nyt minulle Herran kautta, ettet hukuta minun jälkeläisiäni etkä hävitä minun nimeäni isäni suvusta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, '{24:23} Ja Daavid vannoi Saulille. Sitten Saul meni kotiinsa; mutta Daavid ja hänen miehensä nousivat vuorilinnaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'Ja Samuel kuoli, ja koko Israel kokoontui pitämään hänen valittajaisiaan, ja he hautasivat hänet hänen kotipaikkaansa Raamaan. Ja Daavid nousi ja meni Paaranin erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Ja Maaonissa oli mies, jolla oli karjataloutensa Karmelissa, ja se mies oli hyvin rikas: hänellä oli kolmetuhatta lammasta ja tuhat vuohta. Ja hän oli keritsemässä lampaitansa Karmelissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Miehen nimi oli Naabal, ja hänen vaimonsa nimi oli Abigail. Vaimo oli hyvin ymmärtäväinen ja vartaloltaan kaunis, mutta mies oli tyly ja menoissaan raaka; hän oli kaalebilainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Ja kun Daavid kuuli erämaassa, että Naabal keritsi lampaitansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'lähetti hän sinne kymmenen nuorta miestä, ja Daavid sanoi nuorille miehille: \"Menkää Karmeliin, ja kun tulette Naabalin luo, niin tervehtikää häntä minun nimessäni');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'ja sanokaa sille eläjälle: \'Sinä elät rauhassa; rauhassa elää myös sinun perheesi ja kaikki, mitä sinulla on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Minä olen nyt kuullut, että sinulla on lammasten keritsiäiset. Sinun paimenesi ovat olleet meidän läheisyydessämme; me emme ole heitä loukanneet, eikä heiltä ole mitään hävinnyt koko sinä aikana, minkä ovat olleet Karmelissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Kysy nuorilta miehiltäsi, niin he sanovat sen sinulle. Saakoot siis nämä miehet armon sinun silmiesi edessä, sillä mehän olemme tulleet juhlapäivänä. Anna sentähden palvelijoillesi ja pojallesi Daavidille sitä, mitä sinulla on käsillä.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'Kun Daavidin miehet tulivat sinne, puhuivat he Daavidin nimessä Naabalille tämän kaiken ja jäivät hiljaa odottamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Mutta Naabal vastasi Daavidin palvelijoille ja sanoi: \"Kuka Daavid on, kuka on Iisain poika? Tätä nykyä on paljon orjia, jotka karkaavat isäntäinsä luota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Ottaisinko minä ruokani ja juomani ja teuraani, jotka olen teurastanut keritsiäisiini, ja antaisin ne miehille, jotka ovat kotoisin ties mistä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Niin Daavidin miehet kääntyivät ja menivät pois, ja tultuaan takaisin he kertoivat hänelle tämän kaiken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Niin Daavid sanoi miehillensä: \"Jokainen sitokoon miekkansa vyölleen\". Ja jokainen sitoi miekkansa vyölleen; ja Daavid itsekin sitoi miekkansa vyölleen. Ja noin neljäsataa miestä lähti seuraamaan Daavidia, mutta kaksisataa jäi kuormaston luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Mutta eräs nuori mies toi sanan Abigailille, Naabalin vaimolle, ja sanoi: \"Katso, Daavid on lähettänyt sanansaattajia erämaasta tervehtimään meidän isäntäämme, mutta hän vain haukkui heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Ne miehet ovat kuitenkin olleet meille varsin hyviä: he eivät loukanneet meitä, eikä meiltä mitään hävinnyt koko sinä aikana, minkä kuljeskelimme heidän läheisyydessään ollessamme kedolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'He olivat muurina meidän ympärillämme yöllä ja päivällä koko sen ajan, minkä oleskelimme heidän läheisyydessään paimentaessamme lampaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Niin ajattele nyt sinä ja katso, mitä voit tehdä, sillä onnettomuus uhkaa meidän isäntäämme ja koko hänen taloansa. Hän itse on kelvoton mies, niin ettei hänelle auta puhua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Niin Abigail otti joutuin kaksisataa leipää, kaksi leiliä viiniä, viisi lampaanpaistia, viisi sea-mittaa paahdettuja jyviä, sata rusinakakkua ja kaksisataa viikunakakkua ja pani ne aasien selkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'Ja hän sanoi palvelijoillensa: \"Menkää minun edelläni, minä tulen jäljessänne\". Mutta miehellensä Naabalille hän ei sitä ilmoittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'Kun hän sitten ratsasti aasilla alas mäkeä vuoren suojassa, niin katso, Daavid miehinensä tuli toista mäkeä alas häntä vastaan, niin että hän joutui kohtaamaan heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'Mutta Daavid oli sanonut: \"Mitään saamatta minä olen suojellut kaikkea, mitä tällä miehellä oli erämaassa, niin ettei mitään ole hävinnyt kaikesta, mitä hänellä oli. Hän on palkinnut minulle hyvän pahalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'Jumala rangaiskoon Daavidin vihamiehiä nyt ja vasta: totisesti, minä en jätä kaikesta hänen väestänsä huomenaamuksi henkiin yhtään miehenpuolta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Mutta kun Abigail näki Daavidin, laskeutui hän kiiruusti aasin selästä maahan, lankesi kasvoilleen Daavidin eteen ja kumartui maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'Ja kun hän oli langennut hänen jalkainsa juureen, sanoi hän: \"Minun on syy, herrani. Mutta salli palvelijattaresi puhua sinulle ja kuule palvelijattaresi sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Älköön herrani välittäkö mitään tuosta kelvottomasta miehestä, Naabalista, sillä nimi on miestä myöten. Naabal on hänen nimensä, ja houkkamainen hän on. Mutta minä, sinun palvelijattaresi, en ole nähnyt niitä miehiä, jotka sinä, herrani, lähetit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Ja nyt, herrani, niin totta kuin Herra elää ja niin totta kuin sinä itse elät, jonka Herra on estänyt joutumasta verivelan alaiseksi ja auttamasta itseäsi omalla kädelläsi: käyköön nyt sinun vihamiehillesi ja kaikille, jotka hankkivat onnettomuutta minun herralleni, niinkuin Naabalille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Ja nyt annettakoon tämä tervehdyslahja, jonka palvelijattaresi on herralleni tuonut, niille miehille, jotka seuraavat herraani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Anna palvelijattaresi rikkomus anteeksi. Sillä Herra on rakentava minun herralleni pysyväisen huoneen, koska minun herrani käy Herran sotia; eikä mitään pahaa löydetä sinussa koko elinaikanasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'Ja jos joku nousee vainoamaan sinua ja väijymään sinun henkeäsi, niin herrani henki on tallella elävien kukkarossa Herran, sinun Jumalasi, tykönä; mutta sinun vihollistesi hengen hän lingolla linkoaa pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'Ja kun Herra tekee minun herralleni kaiken hyvän, josta hän on sinulle puhunut, ja määrää sinut Israelin ruhtinaaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'niin ei sinua kaada eikä herrani tuntoa vaivaa se, että olisit aiheettomasti vuodattanut verta ja että herrani olisi itse auttanut itseänsä. Mutta kun Herra on tekevä hyvää minun herralleni, niin muista palvelijatartasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Niin Daavid sanoi Abigailille: \"Kiitetty olkoon Herra, Israelin Jumala, joka tänä päivänä lähetti sinut minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Ja siunattu olkoon sinun ymmärtäväisyytesi, ja siunattu ole sinä itse, joka tänä päivänä estit minut joutumasta verivelan alaiseksi ja auttamasta itseäni omalla kädelläni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Mutta niin totta kuin Herra, Israelin Jumala, elää, hän, joka on pidättänyt minut tekemästä sinulle pahaa: jollet sinä joutuin olisi tullut minua vastaan, niin totisesti ei Naabalin väestä olisi huomenna aamun valjetessa ollut jäljellä yhtään miehenpuolta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'Sitten Daavid otti häneltä, mitä hän oli hänelle tuonut, ja sanoi hänelle: \"Mene rauhassa kotiisi. Katso, minä olen kuullut sinua ja tehnyt sinulle mieliksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Kun Abigail sitten tuli Naabalin luo, oli tällä talossansa pidot, niinkuin kuninkaan pidot; ja Naabalin sydän oli iloinen, ja hän oli kovin juovuksissa. Niin hän ei kertonut Naabalille mitään, ennenkuin aamu valkeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Mutta seuraavana aamuna, kun Naabalista humala oli haihtunut, kertoi hänen vaimonsa hänelle, mitä oli tapahtunut. Silloin hänen sydämensä kuoleutui hänen povessaan, ja hän ikäänkuin kivettyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'Ja noin kymmenen päivän kuluttua Herra löi Naabalia, niin että hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'Kun Daavid kuuli, että Naabal oli kuollut, sanoi hän: \"Kiitetty olkoon Herra, joka on kostanut Naabalille minun häväistykseni ja pidättänyt palvelijansa pahasta ja kääntänyt Naabalin pahuuden hänen oman päänsä päälle\". Senjälkeen Daavid lähetti sanomaan Abigailille, että hän halusi ottaa hänet vaimokseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'Ja kun Daavidin palvelijat tulivat Abigailin luo Karmeliin, puhuivat he hänelle ja sanoivat: \"Daavid lähetti meidät sinun luoksesi ottamaan sinut hänelle vaimoksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Niin hän nousi ylös, kumartui kasvoilleen maahan ja sanoi: \"Katso, palvelijattaresi on valmis rupeamaan orjattareksi ja pesemään herrani palvelijain jalat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Sitten Abigail nousi kiiruusti ylös ja istuutui aasin selkään, samoin hänen viisi palvelijatartansa, jotka olivat hänellä seuralaisina. Ja niin hän seurasi Daavidin sanansaattajia ja tuli hänen vaimoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Daavid oli nainut myös Ahinoamin Jisreelistä, niin että he molemmat tulivat hänen vaimoikseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Mutta Saul oli antanut tyttärensä Miikalin, Daavidin vaimon, Paltille, Laiksen pojalle, joka oli kotoisin Gallimista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Siifiläiset tulivat Saulin luo Gibeaan ja sanoivat: \"Daavid piileksii Gibeat-Hakilassa, kallioerämaan puolella\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Niin Saul nousi ja meni Siifin erämaahan, ja hänen kanssansa kolmetuhatta Israelin valiomiestä, etsimään Daavidia Siifin erämaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'Ja Saul leiriytyi Gibeat-Hakilaan, joka on kallioerämaan puolella tien varrella. Mutta Daavid oleskeli erämaassa. Ja kun Daavid huomasi, että Saul oli tullut hänen jäljessään erämaahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'lähetti hän vakoojia ja sai varman tiedon Saulin tulosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Niin Daavid nousi ja meni siihen paikkaan, johon Saul oli leiriytynyt; ja Daavid näki, missä paikassa Saul ja hänen sotapäällikkönsä Abner, Neerin poika, makasivat. Saul näet makasi leirissä, ja väki oli asettunut hänen ympärilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Ja Daavid puhui heettiläiselle Ahimelekille ja Abisaille, Serujan pojalle, Jooabin veljelle, ja sanoi: \"Kuka lähtee minun kanssani Saulin tykö leiriin?\" Abisai vastasi: \"Minä lähden sinun kanssasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Niin Daavid ja Abisai menivät yöllä väen luo ja näkivät, että Saul makasi ja nukkui leirissä, ja hänen keihäänsä oli pistettynä maahan hänen päänpohjiinsa; mutta Abner ja väki makasivat hänen ympärillänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Ja Abisai sanoi Daavidille: \"Jumala on tänä päivänä antanut vihamiehesi sinun käsiisi. Salli nyt minun keihästää hänet maahan; yksi isku vain, toista ei tarvita.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Mutta Daavid vastasi Abisaille: \"Älä surmaa häntä; sillä kuka on rankaisematta satuttanut kätensä Herran voideltuun?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Ja Daavid sanoi vielä: \"Niin totta kuin Herra elää: Herra itse lyö hänet, tahi hänen kuolinpäivänsä tulee, tahi hän menee sotaan ja tuhoutuu siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Mutta minä en satuta kättäni Herran voideltuun. Pois se, Herra varjelkoon! Vaan ota nyt keihäs hänen päänpohjistaan ja vesiastia, ja sitten menkäämme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Ja Daavid otti keihään ja vesiastian Saulin päänpohjista, ja sitten he menivät tiehensä. Eikä kukaan nähnyt tai huomannut sitä, eikä kukaan herännyt, vaan he nukkuivat kaikki; sillä Herran lähettämä raskas uni oli vallannut heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Kun sitten Daavid oli tullut toiselle puolelle, asettui hän kauas vuoren laelle, pitkän välimatkan päähän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'Ja Daavid huusi väelle ja Abnerille, Neerin pojalle, ja sanoi: \"Etkö vastaa, Abner?\" Abner vastasi ja sanoi: \"Kuka sinä olet, joka niin huudat kuninkaalle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'Daavid sanoi Abnerille: \"Sinähän olet mies, eikä sinun vertaistasi ole Israelissa. Miksi et sitten vartioinut herraasi, kuningasta? Sillä joku kansasta tuli surmaamaan kuningasta, sinun herraasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Ei ole hyvin tehty, mitä sinä olet tehnyt. Niin totta kuin Herra elää: te olette kuoleman omat, koska ette vartioineet herraanne, Herran voideltua. Katsohan nyt: missä ovat kuninkaan keihäs ja vesiastia, jotka olivat hänen päänpohjissaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Niin Saul tunsi Daavidin äänen ja sanoi: \"Sehän on sinun äänesi, poikani Daavid\". Daavid vastasi: \"Niin on, herrani, kuningas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Ja hän sanoi vielä: \"Miksi herrani vainoaa palvelijaansa? Mitä minä olen tehnyt, tahi mitä pahaa minulla on tekeillä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Kuulkoon nyt herrani, kuningas, mitä hänen palvelijansa sanoo: Jos Herra on yllyttänyt sinut minua vastaan, niin saakoon hän tuntea ruokauhrin hajua; mutta jos sen ovat tehneet ihmiset, niin olkoot he kirotut Herran edessä, koska tänä päivänä karkoittavat minut pois Herran perintöosasta, sanoen: \'Mene ja palvele muita jumalia\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Älköön kuitenkaan minun vereni vuotako maahan siellä kaukana Herran kasvoista. Niin, Israelin kuningas on lähtenyt liikkeelle etsimään yhtä kirppua, niinkuin ajetaan peltokanaa vuorilla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Niin Saul sanoi: \"Minä olen tehnyt syntiä. Tule takaisin, poikani Daavid; sillä minä en enää tee sinulle pahaa, koska minun henkeni tänä päivänä on ollut kallis sinun silmissäsi. Katso, minä olen tehnyt tyhmästi ja erehtynyt kovin pahoin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'Daavid vastasi ja sanoi: \"Tässä on kuninkaan keihäs; tulkoon joku miehistä tänne ottamaan sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Herra palkitsee jokaiselle hänen vanhurskautensa ja uskollisuutensa. Sillä Herra antoi sinut tänä päivänä minun käsiini, mutta minä en tahtonut satuttaa kättäni Herran voideltuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Katso, niinkuin sinun henkesi tänä päivänä on ollut suuriarvoinen minun silmissäni, niin on myös minun henkeni oleva suuriarvoinen Herran silmissä, ja hän on pelastava minut kaikesta hädästä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Saul sanoi Daavidille: \"Siunattu ole sinä, poikani Daavid! Mihin sinä ryhdyt, siihen sinä pystyt.\" Sitten Daavid meni pois, ja Saul palasi kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Mutta Daavid ajatteli mielessään: \"Kerran Saulin käsi kuitenkin tuhoaa minut. Minulla ei ole muuta neuvoa kuin pelastautua filistealaisten maahan. Silloin Saul huomaa turhaksi enää etsiä minua kaikkialta Israelin alueelta, ja niin minä pelastun hänen käsistänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Niin Daavid nousi ja meni, hän ja ne kuusisataa miestä, jotka olivat hänen kanssaan, Aakiin, Maaokin pojan, Gatin kuninkaan, luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'Ja Daavid asettui miehinensä Aakiin luo Gatiin. Jokaisella oli perheensä mukanaan, Daavidilla molemmat vaimonsa, jisreeliläinen Ahinoam ja karmelilainen Abigail, Naabalin vaimo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'Kun sitten Saulille ilmoitettiin, että Daavid oli paennut Gatiin, ei hän enää etsinyt häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'Ja Daavid sanoi Aakiille: \"Jos minä olen saanut armon sinun silmiesi edessä, niin annettakoon minulle paikka jossakin maaseutukaupungissa, asuakseni siellä. Sillä miksi sinun palvelijasi asuisi kuninkaan kaupungissa sinun luonasi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Niin Aakis antoi hänelle sinä päivänä Siklagin. Sentähden on Siklag Juudan kuningasten oma vielä tänä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'Aika, jonka Daavid asui filistealaisten maassa, oli vuosi ja neljä kuukautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'Daavid lähti miehinensä, ja he tekivät ryöstöretkiä gesurilaisten, geresiläisten ja amalekilaisten maahan. Sillä nämä asuivat siinä maassa, joka muinoin ulottui Suuriin päin ja Egyptin maahan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'Ja hävittäessään maata Daavid ei jättänyt yhtään miestä eikä naista henkiin, otti lampaat, raavaat, aasit, kamelit ja vaatteet ja palasi sitten takaisin ja tuli Aakiin luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'Ja kun Aakis kysyi: \"Ette kai ole tänään tehneet ryöstöretkeä?\" vastasi Daavid: \"Kyllä, Juudan Etelämaahan\", tahi: \"Jerahmeelilaisten Etelämaahan\", tahi: \"Keeniläisten Etelämaahan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Daavid ei jättänyt yhtään miestä eikä naista henkiin, vietäväksi Gatiin, sillä hän ajatteli: \"Ne voisivat kertoa meistä ja sanoa: \'Näin on Daavid tehnyt, tämä on ollut hänen tapansa kaiken aikaa, minkä hän asui filistealaisten maassa\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Ja Aakis luotti Daavidiin ja ajatteli: \"Hän on saattanut itsensä kansansa Israelin vihoihin ja tulee olemaan minun palvelijani ainiaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Siihen aikaan filistealaiset kokosivat joukkonsa sotaretkelle Israelia vastaan. Ja Aakis sanoi Daavidille: \"Tiedä, että sinun on miehinesi lähdettävä minun kanssani sotajoukon mukana\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'Daavid vastasi Aakiille: \"Hyvä! Sinä tulet tietämään, mitä palvelijasi saa aikaan.\" Aakis sanoi Daavidille: \"Siispä minä asetan sinut oman pääni vartijaksi koko täksi aikaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Samuel oli kuollut, ja koko Israel oli pitänyt hänelle valittajaiset; ja he olivat haudanneet hänet hänen kaupunkiinsa Raamaan. Ja Saul oli toimittanut pois maasta vainaja-ja tietäjähenkien manaajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Ja filistealaiset kokoontuivat, ja he tulivat ja leiriytyivät Suunemiin. Niin Saulkin kokosi koko Israelin, ja he leiriytyivät Gilboaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'Mutta kun Saul näki filistealaisten leirin, peljästyi hän, ja hänen sydämensä vapisi kovin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'Ja Saul kysyi Herralta, mutta Herra ei vastannut hänelle, ei unissa, ei uurimin eikä profeettain kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Niin Saul sanoi palvelijoillensa: \"Etsikää minulle joku vaimo, jolla on vallassaan vainajahenki, niin minä menen hänen luoksensa ja kysyn häneltä\". Hänen palvelijansa vastasivat hänelle: \"Katso, Een-Doorissa on vaimo, jolla on vallassaan vainajahenki\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Silloin Saul teki itsensä tuntemattomaksi, pukeutui toisiin vaatteisiin ja lähti matkalle, mukanansa kaksi miestä. He tulivat yöllä vaimon luo, ja hän sanoi: \"Ennusta minulle vainajahengen avulla ja nostata minulle se, jonka minä sinulle sanon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'Mutta vaimo vastasi hänelle: \"Sinä tiedät kyllä, mitä Saul on tehnyt, kuinka hän on hävittänyt vainaja-ja tietäjähenkien manaajat maasta. Miksi virität minulle ansan tuottaaksesi minulle kuoleman?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'Niin Saul vannoi hänelle Herran kautta ja sanoi: \"Niin totta kuin Herra elää: tästä asiasta ei sinulle tule mitään syytä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Vaimo kysyi: \"Kenen minä nostatan sinulle?\" Hän vastasi: \"Nostata minulle Samuel\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'Mutta kun vaimo näki Samuelin, huudahti hän kovalla äänellä. Ja vaimo sanoi Saulille: \"Miksi olet pettänyt minut? Sinähän olet Saul.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'Kuningas sanoi hänelle: \"Älä pelkää. Mitä sinä näet?\" Vaimo vastasi Saulille: \"Minä näen jumal\'olennon nousevan maasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Hän kysyi häneltä: \"Minkä näköinen hän on?\" Vaimo vastasi: \"Vanha mies nousee ylös, viittaan verhoutuneena\". Niin Saul ymmärsi, että se oli Samuel, ja kumartui kasvoilleen maahan ja osoitti kunnioitusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Ja Samuel sanoi Saulille: \"Miksi sinä olet häirinnyt minua ja nostattanut minut?\" Saul vastasi: \"Minä olen suuressa hädässä: filistealaiset sotivat minua vastaan, ja Jumala on poistunut minusta eikä vastaa minulle enää, ei profeettain kautta eikä unissa. Niin minä kutsutin sinut, että ilmoittaisit minulle, mitä minun on tehtävä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Mutta Samuel vastasi: \"Miksi sinä minulta kysyt, kun Herra on poistunut sinusta ja tullut vihamieheksesi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'Herra on tehnyt sen, minkä hän on minun kauttani puhunut: Herra on reväissyt kuninkuuden sinun kädestäsi ja on antanut sen toiselle, Daavidille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Kun sinä et kuullut Herran ääntä etkä tehnyt Amalekille, mitä hänen hehkuva vihansa vaati, sentähden Herra on tänä päivänä tehnyt sinulle tämän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Herra antaa myöskin Israelin yhdessä sinun kanssasi filistealaisten käsiin, ja huomenna olet sinä poikinesi minun tykönäni; myös Israelin leirin Herra antaa filistealaisten käsiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Niin Saul siinä tuokiossa kaatui pitkin koko pituuttaan maahan, sillä hän peljästyi kovin Samuelin puheesta; myös olivat häneltä voimat lopussa, sillä vuorokauteen hän ei ollut syönyt mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Mutta vaimo meni Saulin luo, ja kun hän näki, että tämä oli kauhun vallassa, sanoi hän hänelle: \"Katso, palvelijattaresi kuuli sinua, minä panin henkeni kämmenelleni ja tottelin käskyä, jonka sinä minulle lausuit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Niin kuule nyt sinäkin palvelijatartasi ja salli minun asettaa sinun eteesi palanen leipää, ja syö, että olisit voimissasi, kun lähdet matkalle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Hän epäsi ja sanoi: \"Minä en syö\". Mutta kun hänen palvelijansa yhdessä vaimon kanssa pyytämällä pyysivät häntä, kuuli hän heitä; ja hän nousi maasta ja istui vuoteelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Ja vaimolla oli juottovasikka kotonaan; sen hän teurasti joutuin. Sitten hän otti jauhoja, sotki ne ja leipoi niistä happamattomia leipiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Ja hän toi ruuan Saulin ja hänen palvelijainsa eteen, ja he söivät. Sitten he nousivat ja lähtivät samana yönä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Filistealaiset kokosivat kaikki joukkonsa Afekiin, ja israelilaiset olivat leiriytyneet lähteelle, joka on Jisreelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'Ja kun filistealaisten ruhtinaat tulivat satoineen ja tuhansineen, ja Daavid miehineen tuli viimeiseksi Aakiin kanssa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'sanoivat filistealaisten päälliköt: \"Mitä nuo hebrealaiset täällä tekevät?\" Aakis vastasi filistealaisten päälliköille: \"Tämähän on Daavid, Saulin, Israelin kuninkaan, palvelija, joka on ollut minun luonani toista vuotta, enkä minä ole havainnut hänessä mitään siitä päivästä alkaen, jona hän siirtyi minun luokseni, tähän päivään asti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Niin filistealaisten päälliköt vihastuivat häneen; ja filistealaisten päälliköt sanoivat hänelle: \"Toimita tämä mies takaisin; palatkoon hän siihen paikkaan, jonka sinä olet hänelle määrännyt. Älköön hän tulko meidän kanssamme taisteluun, ettei hän taistelussa tulisi meidän vastustajaksemme. Sillä miten hän voisi hankkia itselleen Herransa suosion paremmin kuin näiden miesten päillä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Eikö tämä ole se Daavid, jolle he karkeloiden virittivät tämän laulun: \'Saul voitti tuhat, mutta Daavid kymmenentuhatta\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Niin Aakis kutsui Daavidin ja sanoi hänelle: \"Niin totta kuin Herra elää: sinä olet rehellinen, ja minulle olisi mieleen, että olisit täällä leirissä, lähtisit ja tulisit minun kanssani; sillä minä en ole havainnut mitään pahaa sinussa siitä päivästä alkaen, jona tulit minun luokseni, tähän päivään asti. Mutta ruhtinaille sinä et ole mieluinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Lähde siis takaisin ja mene rauhassa, ettet tekisi mitään, joka ei olisi filistealaisten ruhtinaille mieleen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'Daavid sanoi Aakiille: \"Mitä minä olen tehnyt, ja mitä olet havainnut palvelijassasi siitä päivästä alkaen, jona minä tulin sinun palvelukseesi, tähän päivään asti, koska en saa tulla taistelemaan herrani, kuninkaan, vihollisia vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Aakis vastasi ja sanoi Daavidille: \"Minä tiedän, että sinä olet minulle mieluinen niinkuin Jumalan enkeli; mutta filistealaisten päälliköt sanovat: \'Hän ei saa lähteä meidän kanssamme taisteluun\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Nouse siis huomenaamuna varhain, sinä ja sinun herrasi palvelijat, jotka ovat tulleet kanssasi, ja lähtekää matkaan huomenaamuna varhain, kun päivä valkenee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Niin Daavid miehinensä lähti varhain seuraavana aamuna matkalle palatakseen filistealaisten maahan. Mutta filistealaiset menivät Jisreeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Kun Daavid miehinensä kolmantena päivänä tuli Siklagiin, olivat amalekilaiset tehneet ryöstöretken Etelämaahan ja Siklagiin, ja he olivat vallanneet Siklagin ja polttaneet sen tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'Naiset, mitä siellä oli, sekä pienet että suuret, he olivat ottaneet vangiksi, surmaamatta ketään; he olivat vieneet ne pois ja menneet matkoihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Kun Daavid miehinensä tuli kaupunkiin, niin katso, se oli tulella poltettu, ja heidän vaimonsa, poikansa ja tyttärensä oli otettu vangiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Silloin Daavid ja väki, joka oli hänen kanssaan, korottivat äänensä ja itkivät, kunnes eivät enää jaksaneet itkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Vangiksi oli otettu myös Daavidin molemmat vaimot, jisreeliläinen Ahinoam ja Abigail, karmelilaisen Naabalin vaimo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'Ja Daavid joutui suureen hätään, sillä kansa aikoi kivittää hänet: niin katkeroitunut oli koko kansa, kukin poikiensa ja tyttäriensä tähden. Mutta Daavid rohkaisi mielensä Herrassa, Jumalassansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Ja Daavid sanoi pappi Ebjatarille, Ahimelekin pojalle: \"Tuo minulle kasukka\". Niin Ebjatar toi kasukan Daavidille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'Ja Daavid kysyi Herralta: \"Ajanko takaa tuota rosvojoukkoa? Saavutanko minä sen?\" Hän vastasi hänelle: \"Aja, sillä sinä saavutat sen ja pelastat pelastettavat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Niin Daavid lähti, hän ja ne kuusisataa miestä, jotka olivat hänen kanssaan, ja he tulivat Besorin purolle; siihen pysähtyivät ne, jotka olivat jääneet muista jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Mutta Daavid jatkoi takaa-ajoa neljänsadan miehen kanssa; sillä niitä, jotka väsyneinä pysähtyivät eivätkä menneet Besorin puron poikki, oli kaksisataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'Ja he tapasivat kedolla egyptiläisen miehen ja toivat hänet Daavidin luo. He antoivat hänelle leipää syödä ja vettä juoda,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'ja he antoivat vielä hänelle viikunakakun ja kaksi rusinakakkua syödä. Silloin hän virkosi henkiin; sillä hän ei ollut syönyt eikä juonut kolmeen vuorokauteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'Ja Daavid kysyi häneltä: \"Kenen olet miehiä ja mistä tulet?\" Hän vastasi: \"Minä olen egyptiläinen nuorukainen, erään amalekilaisen miehen palvelija; mutta minun herrani jätti minut, sillä minä sairastuin kolme päivää sitten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Me teimme ryöstöretken kreettien, Juudan ja Kaalebin Etelämaahan ja poltimme Siklagin tulella.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'Daavid sanoi hänelle: \"Vietkö minut tuon rosvojoukon luo?\" Hän vastasi: \"Vanno minulle Jumalan kautta, ettet surmaa minua etkä luovuta minua herrani käsiin, niin minä vien sinut sen rosvojoukon luo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Ja hän vei hänet sinne; ja katso, heitä oli hajallaan maassa kaikkialla syömässä, juomassa ja juhlimassa kaikella sillä suurella saaliilla, jonka olivat ottaneet filistealaisten maasta ja Juudan maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Niin Daavid kaatoi heitä aamuhämärästä iltaan asti; eikä heistä pelastunut kuin neljäsataa nuorta miestä, jotka nousivat kamelien selkään ja pakenivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'Ja Daavid pelasti kaikki, mitä amalekilaiset olivat ottaneet; myös molemmat vaimonsa Daavid pelasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Ei ketään puuttunut, ei pientä eikä suurta, ei kenenkään poikaa eikä kenenkään tytärtä eikä saalista tai muuta, mitä he olivat ottaneet itsellensä; kaiken Daavid toi takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Daavid otti myös kaikki lampaat ja raavaat, ja niitä ajettiin muun karjan edellä ja huudettiin: \"Tämä on Daavidin saalis!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'Ja kun Daavid tuli niiden kahdensadan miehen luo, jotka olivat väsyneet, jaksamatta seurata Daavidia, ja jotka oli jätetty Besorin purolle, tulivat he Daavidia vastaan ja sitä väkeä, joka oli hänen kanssansa; ja kun Daavid väkineen lähestyi, tervehti hän heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Mutta kaikenlaiset huonot ja kelvottomat miehet niiden joukosta, jotka olivat kulkeneet Daavidin mukana, rupesivat sanomaan: \"Koska nämä eivät ole kulkeneet meidän mukanamme, emme me anna heille mitään saaliista, jonka pelastimme, paitsi kunkin vaimon ja lapset; viekööt ne ja menkööt matkoihinsa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Mutta Daavid sanoi: \"Älkää tehkö niin, veljeni, sen jälkeen, mitä Herra on meille suonut, kun hän varjeli meidät ja antoi meidän käsiimme rosvojoukon, joka hyökkäsi meidän kimppuumme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'Ja kukapa teitä kuulisi tässä asiassa? Sillä taisteluun menevällä ja kuormaston luo jäävällä on oleva yhtäläinen osuus; heidän on jaettava tasan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'Ja sillensä asia jäi silloin ja sen jälkeenkin: hän teki sen säännöksi ja tavaksi Israelissa, aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'Kun Daavid tuli Siklagiin, lähetti hän osan saaliista Juudan vanhimmille, ystävillensä, sanoen: \"Tässä on teille tervehdyslahja siitä saaliista, joka otettiin Herran vihollisilta\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'lahja niille, jotka olivat Beetelissä, Etelämaan Raamotissa, Jattirissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'Aroerissa, Sifmotissa, Estemoassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'Raakalissa, jerahmeelilaisten kaupungeissa, keeniläisten kaupungeissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'Hormassa, Boor-Aasanissa, Atakissa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'ja Hebronissa, ja samoin lahja kaikille muille paikkakunnille, joissa Daavid miehinensä oli kulkenut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Mutta filistealaiset taistelivat Israelia vastaan. Ja Israelin miehet pakenivat filistealaisia, ja heitä kaatui surmattuina Gilboan vuorella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'Ja filistealaiset pääsivät Saulin ja hänen poikiensa kintereille, ja filistealaiset surmasivat Joonatanin, Abinadabin ja Malkisuan, Saulin pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'Ja kun taistelu kiihtyi ankaraksi Saulia vastaan ja jousimiehet keksivät hänet, joutui hän suureen hätään jousimiesten ahdistaessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Ja Saul sanoi aseenkantajallensa: \"Paljasta miekkasi ja lävistä sillä minut, etteivät nuo ympärileikkaamattomat tulisi lävistämään minua ja pitämään minua pilkkanaan\". Mutta hänen aseenkantajansa ei tahtonut, sillä hän pelkäsi kovin. Niin Saul itse otti miekan ja heittäytyi siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Mutta kun hänen aseenkantajansa näki, että Saul oli kuollut, heittäytyi hänkin miekkaansa ja kuoli hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Niin kuolivat sinä päivänä yhdessä Saul, hänen kolme poikaansa ja hänen aseenkantajansa ynnä kaikki hänen miehensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Ja kun Israelin miehet, jotka asuivat tuolla puolella laakson ja tuolla puolella Jordanin, huomasivat, että Israelin miehet olivat paenneet ja että Saul poikinensa oli kuollut, jättivät he kaupungit ja pakenivat, ja filistealaiset tulivat ja asettuivat niihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'Seuraavana päivänä filistealaiset tulivat ryöstämään surmattuja ja löysivät Saulin ja hänen kolme poikaansa kaatuneina Gilboan vuorella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'Niin he löivät häneltä pään poikki, ryöstivät häneltä aseet ja lähettivät ne ympäri filistealaisten maata, julistaaksensa voitonsanomaa epäjumaliensa temppeleissä ja kansan seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'Ja he asettivat hänen aseensa Astarten temppeliin, mutta hänen ruumiinsa he kiinnittivät Beet-Seanin muurille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Kun Gileadin Jaabeksen asukkaat kuulivat, mitä filistealaiset olivat tehneet Saulille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'nousivat he, kaikki sotakuntoiset miehet, kulkivat kaiken yötä ja ottivat Saulin ja hänen poikiensa ruumiit alas Beet-Seanin muurilta, menivät Jaabekseen ja polttivat ne siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'Sitten he ottivat heidän luunsa, hautasivat ne tamariskipuun alle Jaabekseen ja paastosivat seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Saulin kuoleman jälkeen, kun Daavid, voitettuaan amalekilaiset, oli palannut takaisin ja ollut Siklagissa pari päivää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'tuli kolmantena päivänä eräs mies leiristä Saulin luota, vaatteet reväistyinä ja multaa pään päällä. Ja tullessaan Daavidin luo hän heittäytyi maahan ja osoitti kunnioitusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'Daavid kysyi häneltä: \"Mistä tulet?\" Hän vastasi hänelle: \"Minä olen päässyt pakoon Israelin leiristä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Niin Daavid sanoi hänelle: \"Miten on asiat? Kerro minulle.\" Hän vastasi: \"Väki on paennut taistelusta, paljon väkeä on kaatunut ja kuollut; myöskin Saul ja hänen poikansa Joonatan ovat kuolleet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Daavid kysyi nuorelta mieheltä, joka kertoi tämän hänelle: \"Mistä tiedät, että Saul ja hänen poikansa Joonatan ovat kuolleet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Nuori mies, joka oli kertonut hänelle tämän, vastasi: \"Minä tulin sattumalta Gilboan vuorelle, ja katso, Saul nojasi keihääseensä, ja sotavaunut ja ratsumiehet ahdistivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Hän kääntyi taakseen ja nähdessään minut hän huusi minua; minä vastasin: \'Tässä olen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'Niin hän kysyi minulta: \'Kuka olet?\' Minä vastasin hänelle: \'Olen amalekilainen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Sitten hän sanoi minulle: \'Astu luokseni ja surmaa minut, sillä minä olen kangistumassa, vaikka olenkin vielä täysin hengissä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Niin minä astuin hänen luoksensa ja surmasin hänet, sillä minä käsitin, ettei hän sortumisensa jälkeen jäisi henkiin. Ja minä otin kruunun, joka oli hänen päässänsä, ja rannerenkaan, joka oli hänen käsivarressaan, ja toin ne tänne herralleni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Niin Daavid tarttui vaatteisiinsa ja repäisi ne; samoin tekivät kaikki miehet, jotka olivat hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'Ja he pitivät valittajaisia ja itkivät ja paastosivat iltaan asti Saulin ja hänen poikansa Joonatanin tähden ja Herran kansan tähden ja Israelin heimon tähden, koska he olivat kaatuneet miekkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'Ja Daavid kysyi nuorelta mieheltä, joka oli hänelle kertonut tämän: \"Mistä sinä olet?\" Hän vastasi: \"Minä olen täällä muukalaisena elävän amalekilaisen miehen poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Daavid sanoi hänelle: \"Kuinka et peljännyt ojentaa kättäsi tuhotaksesi Herran voidellun?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Ja Daavid kutsui yhden palvelijoistaan ja sanoi: \"Käy tänne, lyö hänet kuoliaaksi\". Ja hän iski hänet kuoliaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'Mutta Daavid sanoi hänelle: \"Sinun veresi tulkoon oman pääsi päälle, sillä oma suusi on todistanut sinua vastaan, kun sanoit: \'Minä olen surmannut Herran voidellun\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Ja Daavid viritti tämän itkuvirren Saulista ja hänen pojastaan Joonatanista');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'ja käski opettaa sen, \"Jousilaulun\", Juudan pojille: katso, se on kirjoitettuna \"Oikeamielisen kirjassa\":');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, '\"Sinun kaunistuksesi, Israel, on surmattuna kukkuloillasi. Kuinka ovatkaan sankarit kaatuneet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Älkää ilmoittako sitä Gatissa, älkää julistako voitonsanomaa Askelonin kaduilla, etteivät filistealaisten tyttäret iloitsisi, etteivät ympärileikkaamattomain tyttäret riemuitsisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'Te Gilboan vuoret, älköön teille kastetta tulko, älköön sadetta, älköön peltoja, joista anteja uhrataan. Sillä siellä on poisviskattuna sankarien kilpi, Saulin kilpi, öljyllä voitelematonna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Kaatuneitten verta, sankarien ytimiä ei Joonatanin jousi väistänyt, eikä tyhjänä palannut Saulin miekka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul ja Joonatan, rakkaat ja armaat, olivat elämässä ja kuolemassa erottamattomat, olivat nopeammat kuin kotkat, leijonia väkevämmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Te Israelin tyttäret, itkekää Saulia, häntä, joka puetti teidät purppuraan ja koristeihin, joka kiinnitti pukuunne kultahelyjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Kuinka ovat sankarit taistelussa kaatuneet! Joonatan on surmattuna kukkuloillasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Minä suren sinua, veljeni Joonatan; sinä olit minulle ylen rakas. Rakkautesi oli minulle ihmeellisempi kuin naisen rakkaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Kuinka ovatkaan sankarit kaatuneet, kuinka ovat hukkuneet taisteluaseet!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'Sen jälkeen Daavid kysyi Herralta: \"Menenkö minä johonkin Juudan kaupunkiin?\" Herra vastasi hänelle: \"Mene\". Ja Daavid kysyi: \"Mihinkä minä menen?\" Hän vastasi: \"Hebroniin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Niin Daavid meni sinne, mukanaan molemmat vaimonsa, jisreeliläinen Ahinoam ja Abigail, karmelilaisen Naabalin vaimo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Ja Daavid vei sinne myös miehet, jotka olivat hänen kanssaan, kunkin perheinensä; ja he asettuivat Hebronin ympärillä oleviin kaupunkeihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Ja Juudan miehet tulivat ja voitelivat siellä Daavidin Juudan heimon kuninkaaksi. Kun Daavidille ilmoitettiin, että Gileadin Jaabeksen miehet olivat haudanneet Saulin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'lähetti Daavid lähettiläät Gileadin Jaabeksen miesten luo sanomaan heille: \"Herra siunatkoon teitä, koska olette osoittaneet herrallenne Saulille laupeutta hautaamalla hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Osoittakoon nyt Herra laupeutta ja uskollisuutta teitä kohtaan. Minäkin teen teille hyvää, koska tämän teitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Rohkaiskaa siis itsenne ja olkaa urhoolliset; teidän herranne Saul tosin on kuollut, mutta Juudan heimo on voidellut kuninkaaksensa minut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Mutta Abner, Neerin poika, Saulin sotapäällikkö, otti Saulin pojan Iisbosetin ja vei hänet Mahanaimiin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'ja asetti hänet Gileadin, Asurin, Jisreelin, Efraimin, Benjaminin ja koko Israelin kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Saulin poika Iisboset oli neljänkymmenen vuoden vanha tullessaan Israelin kuninkaaksi ja hallitsi kaksi vuotta. Ainoastaan Juudan heimo seurasi Daavidia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Ja aika, minkä Daavid oli Juudan heimon kuninkaana Hebronissa, oli seitsemän vuotta ja kuusi kuukautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Abner, Neerin poika, ja Saulin pojan Iisbosetin palvelijat lähtivät Mahanaimista Gibeoniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Ja Jooab, Serujan poika, ja Daavidin palvelijat lähtivät hekin liikkeelle, ja he kohtasivat toisensa Gibeonin lammikolla; he asettuivat toiset tälle, toiset tuolle puolelle lammikon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Ja Abner sanoi Jooabille: \"Nouskoon nuoria miehiä pitämään taistelukisaa meidän edessämme\". Jooab sanoi: \"Nouskoon vain\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Niin heitä nousi ja astui esiin sama määrä: kaksitoista Benjaminin ja Saulin pojan Iisbosetin puolelta sekä kaksitoista Daavidin palvelijaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Ja he tarttuivat kukin vastustajaansa päähän ja pistivät miekkansa toinen toisensa kylkeen ja kaatuivat yhdessä. Niin sen paikan nimeksi tuli Helkat-Suurim, ja se on Gibeonin luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'Ja sinä päivänä syntyi hyvin kova taistelu; mutta Daavidin palvelijat voittivat Abnerin ja Israelin miehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Ja siellä oli kolme Serujan poikaa: Jooab, Abisai ja Asael. Ja Asael oli nopeajalkainen kuin gaselli kedolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'Ja Asael ajoi takaa Abneria eikä poikennut oikealle eikä vasemmalle Abnerin jäljestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Niin Abner käännähti taaksensa ja sanoi: \"Sinäkö se olet, Asael?\" Hän vastasi: \"Minä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Ja Abner sanoi hänelle: \"Käänny oikealle tai vasemmalle ja ota joku noista nuorista miehistä kiinni ja riistä siltä sota-asu\". Mutta Asael ei tahtonut luopua hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Niin Abner vielä kerran sanoi Asaelille: \"Luovu minusta, muutoin lyön sinut maahan. Mutta kuinka minä sitten voisin katsoa sinun veljeäsi Jooabia silmiin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Mutta kun hän ei tahtonut luopua hänestä, pisti Abner häntä keihään varsipuolella vatsaan, niin että keihäs tuli takaapäin ulos; ja hän kaatui ja kuoli siihen paikkaan. Ja jokainen, joka tuli siihen paikkaan, mihin Asael oli kaatunut ja kuollut, pysähtyi siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Mutta Jooab ja Abisai ajoivat Abneria takaa ja tulivat, kun aurinko oli laskenut, Amman kukkulalle, joka on vastapäätä Giiahia, Gibeonin erämaahan päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Silloin benjaminilaiset kokoontuivat Abnerin taakse yhteen joukkoon ja asettuivat kukkulan laelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Ja Abner huusi Jooabille ja sanoi: \"Pitääkö miekan syödä ainiaan? Etkö sinä ymmärrä, että siitä tulee vain katkeruutta jäljestäpäin? Etkö jo käske väen lakata ajamasta takaa veljiänsä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Jooab vastasi: \"Niin totta kuin Jumala elää: jos sinä et olisi puhunut, niin varmasti väki vasta huomenaamuna olisi lähtenyt pois ajamasta takaa veljiänsä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Ja Jooab puhalsi pasunaan; niin kaikki väki pysähtyi eikä enää ajanut takaa Israelia. Ja he eivät enää taistelleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Mutta Abner ja hänen miehensä kulkivat koko sen yön Aromaata ja menivät Jordanin yli, kulkivat koko Bitronin läpi ja tulivat Mahanaimiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'Ja Jooab kokosi kaiken kansan, palattuaan ajamasta takaa Abneria. Ja Daavidin palvelijoista puuttui yhdeksäntoista miestä ja Asael.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Mutta Daavidin palvelijat olivat lyöneet benjaminilaisia ja Abnerin miehiä kuoliaaksi kolmesataa kuusikymmentä miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'Ja he ottivat Asaelin ja hautasivat hänet hänen isänsä hautaan Beetlehemiin. Ja Jooab ja hänen miehensä kulkivat koko sen yön ja tulivat päivän valjetessa Hebroniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'Sota Saulin suvun ja Daavidin suvun välillä tuli pitkälliseksi. Mutta Daavid vahvistui vahvistumistaan, Saulin suku heikontui heikontumistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'Ja Daavidille syntyi poikia Hebronissa. Hänen esikoisensa oli Amnon, jonka äiti oli jisreeliläinen Ahinoam.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Hänen toinen poikansa oli Kilab, jonka äiti oli Abigail, karmelilaisen Naabalin vaimo; kolmas oli Absalom, Gesurin kuninkaan Talmain tyttären, Maakan, poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'Neljäs oli Adonia, Haggitin poika, ja viides Sefatja, Abitalin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'Kuudes oli Jitream, Daavidin vaimon Eglan poika. Nämä syntyivät Daavidille Hebronissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'Niin kauan kuin oli sota Saulin suvun ja Daavidin suvun välillä, piti Abner voimakkaasti Saulin suvun puolta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Saulilla oli ollut sivuvaimo, nimeltä Rispa, Aijan tytär. Ja Iisboset sanoi Abnerille: \"Miksi olet mennyt minun isäni sivuvaimon tykö?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'Abner vihastui kovin Iisbosetin sanoista ja sanoi: \"Olenko minä koiranpää, Juudasta kotoisin? Kun minä nytkin osoitan laupeutta isäsi Saulin suvulle, hänen veljilleen ja ystävilleen enkä ole antanut sinun joutua Daavidin käsiin, niin sinä kuitenkin nyt syytät minua rikoksen teosta naiselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Jumala rangaiskoon Abneria nyt ja vasta, jos minä en tee Daavidille, niinkuin Herra on hänelle vannonut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'minä otan pois kuninkuuden Saulin suvulta ja pystytän Daavidille valtaistuimen Israeliin ja Juudaan, Daanista aina Beersebaan asti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'Eikä hän enää voinut vastata Abnerille sanaakaan, sillä hän pelkäsi häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'Mutta Abner lähetti paikalla sanansaattajat Daavidin luo sanomaan: \"Kenenkä on maa?\" ja vielä näin: \"Tee liitto minun kanssani; ja katso, minun käteni on oleva sinun kanssasi ja on kääntävä koko Israelin sinun puolellesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Hän vastasi: \"Hyvä, minä teen liiton sinun kanssasi. Yhtä minä kuitenkin vaadin sinulta: älä astu minun kasvojeni eteen tuomatta Miikalia, Saulin tytärtä, kun tulet astuaksesi minun kasvojeni eteen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Sitten Daavid lähetti sanansaattajat Iisbosetin, Saulin pojan, luo sanomaan: \"Anna minulle vaimoni Miikal, jonka minä olen kihlannut itselleni sadalla filistealaisten esinahalla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Iisboset lähetti ottamaan hänet hänen mieheltään Paltielilta, Laiksen pojalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Ja hänen miehensä lähti hänen mukanaan ja seurasi häntä aina Bahurimiin asti, itkien lakkaamatta. Niin Abner sanoi hänelle: \"Mene tiehesi, palaja takaisin\". Ja hän palasi takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Abner oli neuvotellut Israelin vanhinten kanssa sanoen: \"Jo kauan olette halunneet saada Daavidin kuninkaaksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Niin pankaa se nyt toimeen, sillä Herra on sanonut Daavidille näin: \'Palvelijani Daavidin kädellä minä vapautan kansani Israelin filistealaisten käsistä ja kaikkien heidän vihollistensa käsistä\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Abner puhui tämän myös benjaminilaisille, ja Abner meni ja puhui Daavidillekin Hebronissa, mitä mieltä Israel ja koko Benjaminin heimo olivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Kun Abner tuli Daavidin luo Hebroniin, mukanaan kaksikymmentä miestä, laittoi Daavid pidot Abnerille ja miehille, jotka olivat hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'Ja Abner sanoi Daavidille: \"Minä nousen ja menen kokoamaan kaiken Israelin herrani, kuninkaan, luo, että he tekisivät liiton sinun kanssasi ja sinä saisit hallittaviksesi kaikki, joita haluat\". Niin Daavid päästi Abnerin menemään, ja hän lähti rauhassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'Katso, silloin Daavidin palvelijat ja Jooab tulivat ryöstöretkeltä ja toivat mukanaan paljon saalista; mutta Abner ei ollut enää Daavidin luona Hebronissa, sillä tämä oli päästänyt hänet menemään, ja hän oli lähtenyt rauhassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Kun Jooab ja kaikki sotaväki, joka oli hänen kanssaan, tulivat, kerrottiin Jooabille: \"Abner, Neerin poika, tuli kuninkaan luo, ja hän päästi hänet menemään, ja hän lähti rauhassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Silloin Jooab meni kuninkaan luo ja sanoi: \"Mitä olet tehnyt? Katso, Abner tuli sinun luoksesi; miksi päästit hänet menemään menojansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Etkö ymmärrä, että Abner, Neerin poika, tuli pettämään sinua ja urkkimaan lähtöäsi ja tuloasi ja kaikkea, mitä teet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Sitten Jooab lähti Daavidin luota ja lähetti sanansaattajat Abnerin jälkeen, ja he palauttivat hänet takaisin Boor-Siirasta; eikä Daavid tiennyt siitä mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Kun Abner tuli takaisin Hebroniin, vei Jooab hänet syrjään porttiholvin keskelle, muka puhutellakseen häntä kahden kesken, ja pisti häntä siellä vatsaan, niin että hän kuoli-hänen veljensä Asaelin veren kostoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Kun Daavid sitten sai sen kuulla, sanoi hän: \"Abnerin, Neerin pojan, vereen olen viaton minä ja minun kuninkuuteni Herran edessä iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Tulkoon se Jooabin pään päälle ja kaiken hänen isänsä perheen päälle, älköötkä Jooabin suvusta loppuko vuotoa tai pitalia sairastavat, kainalosauvoilla kulkijat, miekkaan kaatuvat ja leivän puutteessa olijat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Näin Jooab ja hänen veljensä Abisai tappoivat Abnerin, sentähden että tämä oli surmannut heidän veljensä Asaelin taistelussa Gibeonin luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Mutta Daavid sanoi Jooabille ja kaikelle väelle, joka oli hänen kanssaan: \"Reväiskää vaatteenne ja kääriytykää säkkeihin ja pitäkää valittajaiset Abnerille\". Ja kuningas Daavid kulki paarien perässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'Ja he hautasivat Abnerin Hebroniin; ja kuningas korotti äänensä ja itki Abnerin haudalla, ja kaikki kansa itki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'Ja kuningas viritti itkuvirren Abnerista ja sanoi: \"Pitikö Abnerin kuolla, niinkuin kuolee houkka?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Eivät olleet sinun kätesi sidotut eivätkä jalkasi vaskikahleisiin pannut. Sinä kaaduit, niinkuin kaadutaan vilpillisten käden kautta.\" Niin kaikki kansa itki häntä vielä enemmän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Ja kaikki kansa tuli, kun vielä oli päivä, vaatimaan, että Daavid söisi jotakin; mutta Daavid vannoi ja sanoi: \"Jumala rangaiskoon minua nyt ja vasta, jos minä maistan leipää tai muuta, ennenkuin aurinko laskee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Kun kaikki kansa sai kuulla sen, miellytti se heitä, samoinkuin kaikki muu, mitä kuningas teki, oli kaikelle kansalle mieleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'Ja kaikki kansa ja koko Israel ymmärsivät sinä päivänä, että Abnerin, Neerin pojan, surma ei ollut lähtenyt kuninkaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'Ja kuningas sanoi palvelijoilleen: \"Ettekö tiedä, että ruhtinas ja suuri mies on tänä päivänä kaatunut Israelissa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Mutta minä olen vielä heikko, vaikka olen voideltu kuninkaaksi, ja nuo miehet, Serujan pojat, ovat liian väkivaltaiset minun hillitä. Herra maksakoon sille, joka tekee pahaa, hänen pahuutensa mukaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'Kun Saulin poika kuuli Abnerin kuolleen Hebronissa, herposivat hänen kätensä, ja koko Israel peljästyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Ja Saulin pojalla oli partiojoukkojen päämiehinä kaksi miestä, toisen nimi oli Baana ja toisen Reekab, beerotilaisen Rimmonin poikia, benjaminilaisia; sillä Beerotkin luetaan kuuluvaksi Benjaminiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Mutta beerotilaiset olivat paenneet Gittaimiin ja asuivat siellä muukalaisina, niinkuin asuvat vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Joonatanilla, Saulin pojalla, oli poika, joka oli rampa jaloistaan. Hän oli viiden vuoden vanha, kun sanoma Saulista ja Joonatanista tuli Jisreelistä; ja hänen hoitajansa otti hänet ja pakeni. Mutta kun tämä hätääntyneenä pakeni, putosi poika ja tuli ontuvaksi; ja hänen nimensä oli Mefiboset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Beerotilaisen Rimmonin pojat Reekab ja Baana lähtivät matkaan ja tulivat päivän ollessa palavimmillaan Iisbosetin taloon, kun hän oli puolipäivälevollansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Ja katso, he tulivat sisälle taloon muka ottamaan nisuja, mutta pistivät häntä vatsaan. Ja Reekab ja hänen veljensä Baana pääsivät pakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'He tulivat niinmuodoin taloon, kun hän lepäsi vuoteellansa makuuhuoneessaan, pistivät hänet kuoliaaksi, löivät häneltä pään poikki ja ottivat sen mukaansa. He kulkivat sitten Aromaan tietä koko yön,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'toivat Iisbosetin pään Daavidille Hebroniin ja sanoivat kuninkaalle: \"Katso, tässä on Iisbosetin, Saulin pojan, sinun vihamiehesi, pää, hänen, joka väijyi sinun henkeäsi. Herra on tänä päivänä kostanut Saulille ja hänen jälkeläisillensä herrani, kuninkaan, puolesta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Niin Daavid vastasi Reekabille ja hänen veljellensä Baanalle, beerotilaisen Rimmonin pojille, ja sanoi heille: \"Niin totta kuin Herra elää, joka on vapahtanut minut kaikesta hädästä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'sen, joka ilmoitti minulle ja sanoi: \'Katso, Saul on kuollut\', luullen tuovansa ilosanoman, minä otatin kiinni ja surmautin Siklagissa antaakseni hänelle sanansaattajan palkan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'eikö minun paljoa enemmän nyt, kun jumalattomat miehet ovat murhanneet syyttömän miehen hänen omassa kodissaan, hänen vuoteeseensa, ole vaadittava hänen verensä teidän kädestänne ja hävitettävä teidät maan päältä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'Ja Daavid käski nuorten miesten surmata heidät. Niin he hakkasivat poikki heidän kätensä ja jalkansa ja hirttivät heidät Hebronin lammikon rannalle. Mutta Iisbosetin pään he ottivat ja hautasivat sen Abnerin hautaan Hebroniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Sitten kaikki Israelin sukukunnat tulivat Daavidin luo Hebroniin ja sanoivat näin: \"Katso, me olemme sinun luutasi ja lihaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'Jo kauan sitten, Saulin vielä ollessa kuninkaanamme, sinä saatoit Israelin lähtemään ja tulemaan. Ja sinulle on Herra sanonut: \'Sinä olet kaitseva minun kansaani Israelia, ja sinä olet oleva Israelin ruhtinas\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Ja kaikki Israelin vanhimmat tulivat kuninkaan tykö Hebroniin, ja kuningas Daavid teki heidän kanssaan liiton Hebronissa, Herran edessä; ja sitten he voitelivat Daavidin Israelin kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Daavid oli kolmenkymmenen vuoden vanha tullessaan kuninkaaksi ja hallitsi neljäkymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'Hebronissa hän hallitsi Juudaa seitsemän vuotta ja kuusi kuukautta, ja Jerusalemissa hän hallitsi koko Israelia ja Juudaa kolmekymmentä kolme vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'Ja kuningas meni miehinensä Jerusalemiin jebusilaisia vastaan, jotka asuivat siinä maassa. He sanoivat Daavidille näin: \"Tänne sinä et tule, vaan sokeat ja ontuvat karkoittavat sinut sanomalla: \'Ei tule Daavid tänne\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Mutta Daavid valloitti Siionin vuorilinnan, se on Daavidin kaupungin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Ja Daavid sanoi sinä päivänä: \"Jokainen, joka surmaa jebusilaisen ja tunkeutuu vesijohdolle asti, hän voittaa ne sokeat ja ontuvat, joita Daavid vihaa\". Sentähden on tapana sanoa: \"Sokea ja ontuva älköön tulko taloon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'Sitten Daavid asettui vuorilinnaan ja kutsui sen Daavidin kaupungiksi. Ja Daavid rakenteli sitä yltympäri, Millosta sisälle päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'Ja Daavid tuli yhä mahtavammaksi, ja Herra, Jumala Sebaot, oli hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Hiiram, Tyyron kuningas, lähetti sanansaattajat Daavidin luo sekä setripuita, puuseppiä ja kivenhakkaajia; ja nämä rakensivat Daavidille palatsin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'Ja Daavid ymmärsi, että Herra oli vahvistanut hänet Israelin kuninkaaksi ja korottanut hänen kuninkuutensa kansansa Israelin tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'Ja Hebronista tultuaan Daavid otti Jerusalemista vielä useampia sivuvaimoja ja vaimoja. Ja Daavidille syntyi vielä poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Ja nämä ovat niiden poikien nimet, jotka syntyivät hänelle Jerusalemissa: Sammua, Soobab, Naatan, Salomo,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Jibhar, Elisua, Nefeg, Jaafia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'Elisama, Eljada ja Elifelet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Mutta kun filistealaiset kuulivat, että Daavid oli voideltu Israelin kuninkaaksi, lähtivät kaikki filistealaiset etsimään Daavidia. Kun Daavid sen kuuli, meni hän alas vuorilinnaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Kun filistealaiset olivat tulleet ja levittäytyneet Refaimin tasangolle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'kysyi Daavid Herralta: \"Menenkö minä filistealaisia vastaan? Annatko sinä heidät minun käsiini?\" Ja Herra sanoi Daavidille: \"Mene, sillä minä annan filistealaiset sinun käsiisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'Niin Daavid tuli Baal-Perasimiin. Ja siellä Daavid voitti heidät ja sanoi: \"Herra on murtanut viholliseni minun edessäni, niinkuin vedet murtavat\". Siitä sen paikan nimeksi tuli Baal-Perasim.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'He jättivät siihen epäjumalankuvansa, ja Daavid ja hänen miehensä veivät ne pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Mutta filistealaiset tulivat vielä kerran ja levittäytyivät Refaimin tasangolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'Niin Daavid kysyi Herralta, ja hän vastasi: \"Älä mene heitä vastaan, vaan kierrä heidät takaapäin ja hyökkää heidän kimppuunsa balsamipuiden puolelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'Ja kun kuulet astunnan kahinan balsamipuiden latvoista, niin ryntää nopeasti, sillä silloin Herra on käynyt sinun edelläsi tuhotakseen filistealaisten leirin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, '{5:24} Daavid teki, niinkuin Herra oli häntä käskenyt; ja hän voitti filistealaiset ja ajoi heitä takaa Gebasta aina Geseriin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Daavid kokosi jälleen kaikki valiomiehet Israelista, kolmekymmentä tuhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'Ja Daavid ja kaikki väki, joka oli hänen kanssaan, nousi ja lähti Juudan Baalasta, tuomaan sieltä Jumalan arkkia, jonka Herra Sebaot oli ottanut nimiinsä, hän, jonka istuinta kerubit kannattavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'Ja he panivat Jumalan arkin uusiin vaunuihin ja veivät sen pois Abinadabin talosta, joka oli mäellä; ja Ussa ja Ahjo, Abinadabin pojat, ohjasivat niitä uusia vaunuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'Niin he veivät Jumalan arkin pois Abinadabin talosta, joka oli mäellä, kulkien Jumalan arkin mukana, ja Ahjo kulki arkin edellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Ja Daavid ynnä koko Israelin heimo karkeloi kaikin voimin Herran edessä soittaen kaikenkaltaisilla kypressipuisilla soittimilla, kanteleilla, harpuilla, vaskirummuilla, helistimillä ja kymbaaleilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'Mutta kun he tulivat Naakonin puimatantereen luo, ojensi Ussa kätensä Jumalan arkkiin ja tarttui siihen, sillä härät kompastuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Silloin Herran viha syttyi Ussaa kohtaan, ja Jumala löi hänet siinä hänen hairahduksensa tähden, niin että hän kuoli siihen, Jumalan arkin ääreen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'Mutta Daavid pahastui siitä, että Herra niin oli murtanut Ussan. Siitä se paikka sai nimekseen Peres-Ussa, aina tähän päivään saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'Ja Daavid pelkäsi sinä päivänä Herraa, niin että hän sanoi: \"Kuinka Herran arkki voi tulla minun tyköni?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Eikä Daavid tahtonut siirtää Herran arkkia tykönsä Daavidin kaupunkiin, vaan Daavid toimitti sen syrjään, gatilaisen Oobed-Edomin taloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'Ja Herran arkki jäi kolmeksi kuukaudeksi gatilaisen Oobed-Edomin taloon. Ja Herra siunasi Oobed-Edomia ja koko hänen taloansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'Kun kuningas Daavidille kerrottiin, että Herra oli Jumalan arkin tähden siunannut Oobed-Edomin taloa ja kaikkea, mitä hänellä oli, niin Daavid meni ja toi riemuiten Jumalan arkin Oobed-Edomin talosta Daavidin kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'Kun Herran arkin kantajat olivat astuneet kuusi askelta, uhrasi hän härän ja juottovasikan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'Ja Daavid hyppi kaikin voimin Herran edessä, ja Daavid oli puettu pellavakasukkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Niin Daavid ja koko Israelin heimo toivat Herran arkin riemun raikuessa ja pasunain pauhatessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'Kun Herran arkki tuli Daavidin kaupunkiin, katseli Miikal, Saulin tytär, ikkunasta; ja nähdessään kuningas Daavidin karkeloivan ja hyppivän Herran edessä halveksi hän häntä sydämessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Ja kun he olivat tuoneet Herran arkin ja asettaneet sen paikalleen majaan, jonka Daavid oli sille pystyttänyt, uhrasi Daavid polttouhreja ja yhteysuhreja Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'Ja kun Daavid oli uhrannut polttouhrin ja yhteysuhrit, siunasi hän kansan Herran Sebaotin nimeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'Ja hän jakoi koko kansalle, kaikelle Israelin joukolle, sekä miehille että naisille, kullekin kakun, kappaleen lihaa ja rypälekakun. Sitten kaikki kansa lähti, kukin kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Mutta kun Daavid palasi takaisin tervehtimään perhettänsä, meni Miikal, Saulin tytär, ulos Daavidia vastaan ja sanoi: \"Kuinka arvokkaana onkaan Israelin kuningas nyt esiintynyt, kun on tänä päivänä paljastanut itsensä palvelijainsa palvelijattarien silmien edessä, niinkuin kevytmielinen ihminen paljastautuu!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Niin Daavid sanoi Miikalille: \"Herran edessä, joka on valinnut minut, sivu sinun isäsi ja koko hänen sukunsa, ja asettanut minut Herran kansan, Israelin, ruhtinaaksi-Herran edessä minä karkeloin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'ja tähänkin minä pidän itseni liian vähäisenä ja olen omissa silmissäni halpa; mutta ne palvelijattaret, joista sinä puhuit, tulevat minua kunnioittamaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Ja Miikal, Saulin tytär, ei saanut lasta kuolinpäiväänsä asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'Kerran, kun kuningas istui linnassaan, sittenkuin Herra oli suonut hänen päästä rauhaan kaikilta hänen ympärillään olevilta vihollisilta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'sanoi kuningas profeetta Naatanille: \"Katso, minä asun setripuisessa linnassa, mutta Jumalan arkki asuu telttakankaan suojassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Naatan sanoi kuninkaalle: \"Tee vain kaikki, mitä mielessäsi on, sillä Herra on sinun kanssasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Mutta sinä yönä tapahtui, että Naatanille tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, '\"Mene ja sano minun palvelijalleni Daavidille: Näin sanoo Herra: Sinäkö rakentaisit minulle huoneen asuakseni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Enhän minä ole asunut huoneessa siitä päivästä asti, jona johdatin israelilaiset Egyptistä, tähän päivään saakka, vaan minä olen vaeltanut asuen teltta-asumuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Olenko minä koskaan, missä olenkin vaeltanut kaikkien israelilaisten keskuudessa, millekään Israelin sukukunnalle, jonka olen asettanut kaitsemaan kansaani Israelia, sanonut näin: Miksi te ette ole rakentaneet minulle setripuista huonetta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Sano siis minun palvelijalleni Daavidille: Näin sanoo Herra Sebaot: Minä olen ottanut sinut laitumelta, lammasten jäljestä, kansani Israelin ruhtinaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'Ja minä olen ollut sinun kanssasi kaikkialla, missä sinä vaelsit, ja olen hävittänyt kaikki vihollisesi sinun tieltäsi. Ja minä teen sinulle suuren nimen, suurimpien nimien vertaisen maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'Ja minä valmistan sijan kansalleni Israelille ja istutan sen niin, että se asuu paikallansa eikä enää ole levoton, eivätkä vääryyden tekijät sitä enää sorra niinkuin ennen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'siitä ajasta saakka, jolloin minä asetin tuomareita kansalleni Israelille; minä annan sinun päästä rauhaan kaikista vihollisistasi. Ja Herra ilmoittaa sinulle, että Herra on tekevä sinulle huoneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Kun sinun päiväsi ovat päättyneet ja sinä lepäät isiesi tykönä, korotan minä sinun seuraajaksesi jälkeläisesi, joka lähtee sinun ruumiistasi; ja minä vahvistan hänen kuninkuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'Hän on rakentava huoneen minun nimelleni, ja minä vahvistan hänen valtaistuimensa ikuisiksi ajoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Minä olen oleva hänen isänsä ja hän minun poikani, niin että, jos hän tekee väärin, minä rankaisen häntä ihmisvitsalla ja niinkuin ihmislapsia lyödään;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'mutta minun armoni ei poistu hänestä, niinkuin minä poistin sen Saulista, jonka minä poistin sinun tieltäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Ja sinun sukusi ja kuninkuutesi pysyvät sinun edessäsi iäti, ja sinun valtaistuimesi on oleva iäti vahva.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Aivan näillä sanoilla ja tämän näyn mukaan Naatan puhui Daavidille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Niin kuningas Daavid meni ja asettui Herran eteen ja sanoi: \"Mikä olen minä, Herra, Herra, ja mikä on minun sukuni, että olet saattanut minut tähän asti?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Mutta tämäkin on ollut vähän sinun silmissäsi, Herra, Herra, ja niin olet sinä puhunut palvelijasi suvulle myöskin kaukaisista asioista, näin opettaen ihmisten tavalla, Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'Mitä Daavid enää sinulle puhuisi? Sinähän tunnet palvelijasi, Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Oman sanasi tähden ja mielesi mukaan sinä olet tehnyt sen, että ilmoitit palvelijallesi kaikki nämä suuret asiat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Sentähden olet sinä, Herra Jumala, suuri; sillä kaiken sen mukaan, mitä me olemme korvillamme kuulleet, ei ole sinun vertaistasi, eikä muuta jumalaa ole kuin sinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'Ja missä on maan päällä toista kansaa sinun kansasi Israelin vertaista, jota Jumala itse on käynyt lunastamaan kansaksensa, tehdäkseen sen nimen kuuluisaksi ja tehdäkseen teille, sinun maallesi, suuria ja peljättäviä tekoja kansasi edessä, jonka sinä lunastit itsellesi Egyptistä, pakanain ja heidän jumaliensa vallasta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'Ja sinä olet valmistanut itsellesi kansasi Israelin, omaksi kansaksesi ikuisiksi ajoiksi; ja sinä, Herra, olet tullut heidän Jumalaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Niin täytä nyt, Herra Jumala, ikuisiksi ajoiksi se, mitä olet puhunut palvelijastasi ja hänen suvustansa; tee, niinkuin olet puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Niin sinun nimesi tulee suureksi iankaikkisesti, ja se on oleva: Herra Sebaot, Israelin Jumala. Ja palvelijasi Daavidin suku on pysyvä sinun edessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Sillä sinä, Herra Sebaot, Israelin Jumala, olet ilmoittanut palvelijallesi ja sanonut: \'Minä rakennan sinulle huoneen\'. Siitä sinun palvelijasi on saanut rohkeuden rukoilla tämän rukouksen sinun kuullaksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Ja nyt, Herra, Herra, sinä olet Jumala, ja sinun sanasi ovat todet; ja kun olet luvannut palvelijallesi tämän hyvän,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'niin suvaitse nyt siunata palvelijasi sukua, että se pysyisi iäti sinun edessäsi. Sillä sinä, Herra, Herra, olet sen luvannut, ja sinun palvelijasi suku on oleva siunattu sinun siunauksellasi iankaikkisesti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'Sen jälkeen Daavid voitti filistealaiset ja nöyryytti heidät; ja Daavid otti vallan ohjat filistealaisten käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Hän voitti myös mooabilaiset ja mittasi heitä nuoralla, pantuaan heidät makaamaan maahan: aina kaksi nuoranpituutta hän mittasi surmattavaksi ja yhden nuoranpituuden henkiin jätettäväksi. Niin tulivat mooabilaiset Daavidin veronalaisiksi palvelijoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Samoin Daavid voitti Hadadeserin, Rehobin pojan, Sooban kuninkaan, kun tämä oli menossa ulottamaan valtaansa Eufrat-virtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'Ja Daavid otti häneltä vangiksi tuhat seitsemänsataa ratsumiestä ja kaksikymmentä tuhatta jalkamiestä ja katkoi kaikilta vaunuhevosilta vuohisjänteet; ainoastaan sata vaunuhevosta hän niistä säästi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Ja kun Damaskon aramilaiset tulivat auttamaan Hadadeseria, Sooban kuningasta, voitti Daavid kaksikymmentä kaksi tuhatta aramilaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'Ja Daavid asetti maaherroja Damaskon Aramiin; ja aramilaiset tulivat Daavidin veronalaisiksi palvelijoiksi. Näin Herra antoi Daavidille voiton, mihin tahansa hän meni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Ja Daavid otti ne kultavarustukset, jotka Hadadeserin palvelijoilla oli, ja vei ne Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Mutta Hadadeserin kaupungeista, Betahista ja Beerotaista, kuningas Daavid otti sangen paljon vaskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'Kun Tooi, Hamatin kuningas, kuuli, että Daavid oli voittanut Hadadeserin koko sotajoukon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'lähetti Tooi poikansa Jooramin kuningas Daavidin luo tervehtimään häntä ja onnittelemaan häntä siitä, että hän oli taistellut Hadadeserin kanssa ja voittanut hänet; sillä Hadadeser oli ollut Tooin vastustaja. Ja hänellä oli mukanaan hopea-,kulta-ja vaskikaluja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Nekin kuningas Daavid pyhitti Herralle, samoin kuin oli pyhittänyt sen hopean ja kullan, minkä oli ottanut kaikilta kukistamiltaan kansoilta:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'Aramilta, Mooabilta, ammonilaisilta, filistealaisilta ja Amalekilta, sekä sen saaliin, minkä hän oli ottanut Hadadeserilta, Rehobin pojalta, Sooban kuninkaalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'Ja Daavid teki nimensä kuuluisaksi, kun hän palasi takaisin, voitettuaan Suolalaaksossa edomilaiset, kahdeksantoista tuhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Sen jälkeen hän asetti maaherroja Edomiin, koko Edomiin hän asetti maaherrat, ja kaikki edomilaiset tulivat Daavidin palvelijoiksi. Näin Herra antoi Daavidille voiton, mihin tahansa tämä meni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'Ja Daavid hallitsi koko Israelia, ja Daavid teki kaikelle kansallensa sitä, mikä oikeus ja vanhurskaus on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Jooab, Serujan poika, oli sotajoukon ylipäällikkönä, ja Joosafat, Ahiludin poika, oli kanslerina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Saadok, Ahitubin poika, ja Ahimelek, Ebjatarin poika, olivat pappeina, ja Seraja oli kirjurina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Benaja, Joojadan poika, oli kreettien ja pleettien päällikkönä; Daavidin pojat olivat myös pappeina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Daavid kysyi: \"Onko Saulin suvusta enää jäljellä ketään, jolle minä voisin tehdä laupeuden Joonatanin tähden?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Saulin perheessä oli ollut palvelija nimeltä Siiba, ja hänet he kutsuivat Daavidin eteen. Ja kuningas sanoi hänelle: \"Oletko sinä Siiba?\" Hän vastasi: \"Palvelijasi on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Kuningas kysyi: \"Eikö Saulin suvusta ole enää jäljellä ketään, jolle minä voisin tehdä Jumalan laupeuden?\" Siiba vastasi kuninkaalle: \"Vielä on Joonatanin poika, joka on rampa jaloistaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'Kuningas kysyi häneltä: \"Missä hän on?\" Siiba vastasi kuninkaalle: \"Hän on Maakirin, Ammielin pojan, talossa Loodebarissa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Niin kuningas Daavid lähetti noutamaan hänet Maakirin, Ammielin pojan, talosta Loodebarista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'Kun Mefiboset, Saulin pojan Joonatanin poika, tuli Daavidin tykö, lankesi hän kasvoillensa ja osoitti kunnioitusta. Niin Daavid sanoi: \"Mefiboset!\" Hän vastasi: \"Tässä on palvelijasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'Daavid sanoi hänelle: \"Älä pelkää, sillä minä teen sinulle laupeuden isäsi Joonatanin tähden, ja minä palautan sinulle isoisäsi Saulin kaiken maaomaisuuden, ja sinä saat aina aterioida minun pöydässäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Niin tämä kumarsi ja sanoi: \"Mikä on palvelijasi, että sinä käännyt minunlaiseni koiranraadon puoleen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Sitten kuningas kutsui Siiban, Saulin palvelijan, ja sanoi hänelle: \"Kaiken, mikä on ollut Saulin ja koko hänen sukunsa omaa, minä annan sinun herrasi pojalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Ja sinä poikinesi ja palvelijoinesi viljele hänelle sitä maata ja korjaa sato, että sinun herrasi pojalla olisi leipää syödä; kuitenkin saa Mefiboset, sinun herrasi poika, aina aterioida minun pöydässäni.\" Ja Siiballa oli viisitoista poikaa ja kaksikymmentä palvelijaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Siiba sanoi kuninkaalle: \"Aivan niinkuin herrani, kuningas, käskee palvelijaansa, on palvelijasi tekevä\". -\"Niin, Mefiboset on syövä minun pöydässäni, niinkuin hän olisi kuninkaan poikia.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Ja Mefibosetilla oli pieni poika nimeltä Miika. Ja koko Siiban talonväki oli Mefibosetin palvelijoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'Ja Mefiboset asui Jerusalemissa, koska hän aina söi kuninkaan pöydässä. Ja hän ontui kumpaakin jalkaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'Senjälkeen ammonilaisten kuningas kuoli, ja hänen poikansa Haanun tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Niin Daavid sanoi: \"Minä osoitan laupeutta Haanunille, Naahaan pojalle, niinkuin hänen isänsä osoitti laupeutta minulle\". Ja Daavid lähetti palvelijoitaan lohduttamaan häntä hänen isänsä kuoleman johdosta. Kun Daavidin palvelijat tulivat ammonilaisten maahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'sanoivat ammonilaisten päämiehet herrallensa Haanunille: \"Luuletko sinä, että Daavid tahtoo kunnioittaa sinun isääsi, kun hän lähettää lohduttajia sinun luoksesi? Varmasti on Daavid lähettänyt palvelijansa sinun luoksesi tutkimaan kaupunkia ja vakoilemaan ja hävittämään sitä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Niin Haanun otatti kiinni Daavidin palvelijat, ajatti toisen puolen heidän partaansa ja leikkautti toisen puolen heidän vaatteistaan, peräpuolia myöten, ja päästi heidät sitten menemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Ja kun se ilmoitettiin Daavidille, lähetti hän sanan heitä vastaan, sillä miehiä oli pahasti häväisty. Ja kuningas käski sanoa: \"Jääkää Jerikoon, kunnes partanne on kasvanut, ja tulkaa sitten takaisin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Kun ammonilaiset näkivät joutuneensa Daavidin vihoihin, lähettivät ammonilaiset lähettiläitä ja palkkasivat Beet-Rehobin ja Sooban aramilaisia, kaksikymmentä tuhatta jalkamiestä, ja Maakan kuninkaalta tuhat miestä ja Toobin miehiä kaksitoista tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Kun Daavid sen kuuli, lähetti hän Jooabin ja koko sotajoukon, kaikki urhot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Niin ammonilaiset lähtivät ja asettuivat sotarintaan portin oven edustalle, mutta Sooban ja Rehobin aramilaiset ja Toobin ja Maakan miehet olivat eri joukkona kedolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Kun Jooab näki, että häntä uhkasi hyökkäys edestä ja takaa, valitsi hän miehiä kaikista Israelin valiomiehistä ja asettui sotarintaan aramilaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Mutta muun väen hän antoi veljensä Abisain johtoon, ja tämä asettui sotarintaan ammonilaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'Ja hän sanoi: \"Jos aramilaiset tulevat minulle ylivoimaisiksi, niin tule sinä minun avukseni; jos taas ammonilaiset tulevat sinulle ylivoimaisiksi, niin minä tulen sinua auttamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Ole luja, ja pysykäämme lujina kansamme puolesta ja meidän Jumalamme kaupunkien puolesta. Tehköön sitten Herra, minkä hyväksi näkee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Sitten Jooab ja väki, joka oli hänen kanssaan, ryhtyi taisteluun aramilaisia vastaan, ja nämä pakenivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Ja kun ammonilaiset näkivät aramilaisten pakenevan, pakenivat hekin Abisaita ja menivät kaupunkiin. Sitten Jooab palasi ahdistamasta ammonilaisia ja tuli Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'Kun aramilaiset näkivät, että Israel oli voittanut heidät, kokoontuivat he kaikki,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'ja Hadareser lähetti nostattamaan niitä aramilaisia, jotka asuivat tuolla puolella Eufrat-virran; ja he tulivat Heelamiin, ja Soobak, Hadareserin sotapäällikkö, johti heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'Kun se ilmoitettiin Daavidille, kokosi hän kaiken Israelin ja meni Jordanin yli ja tuli Heelamiin; ja aramilaiset asettuivat sotarintaan Daavidia vastaan ja taistelivat hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Mutta aramilaiset pakenivat Israelia, ja Daavid tappoi aramilaisilta seitsemän sataa vaunuhevosta ja neljäkymmentä tuhatta ratsumiestä, ja heidän sotapäällikkönsä Soobakin hän siellä löi kuoliaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'Kun kaikki Hadareserin alaiset kuninkaat näkivät, että Israel oli voittanut heidät, tekivät he Israelin kanssa rauhan ja palvelivat heitä. Sitten aramilaiset eivät enää uskaltaneet auttaa ammonilaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'Vuoden vaihteessa, kuningasten sotaanlähtöaikana, lähetti Daavid Jooabin ja hänen kanssaan palvelijansa ja koko Israelin sotaretkelle; ja he hävittivät ammonilaisten maata ja piirittivät Rabbaa. Mutta Daavid itse jäi Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'Niin tapahtui eräänä iltana, kun Daavid oli noussut vuoteeltansa ja käveli kuninkaan linnan katolla, että hän katolta näki naisen peseytymässä; ja nainen oli näöltään hyvin ihana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Daavid lähetti hankkimaan tietoja naisesta; ja sanottiin: \"Se on Batseba, Eliamin tytär, heettiläisen Uurian vaimo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Niin Daavid lähetti sanansaattajat häntä noutamaan, ja hän tuli hänen luoksensa. Ja Daavid makasi naisen kanssa, joka juuri oli puhdistautunut saastaisuudestaan. Sitten tämä palasi kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'Ja vaimo tuli raskaaksi; ja hän lähetti ilmoittamaan Daavidille: \"Minä olen raskaana\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'Silloin Daavid lähetti Jooabille sanan: \"Lähetä minun luokseni heettiläinen Uuria\". Ja Jooab lähetti Uurian Daavidin luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'Ja kun Uuria tuli Daavidin luo, kysyi tämä, kuinka Jooab ja väki voivat ja kuinka sota menestyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Ja Daavid sanoi Uurialle: \"Mene kotiisi ja pese jalkasi\". Uuria lähti kuninkaan linnasta, ja kuninkaan lahja seurasi häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Mutta Uuria panikin maata kuninkaan linnan oven eteen kaikkien muiden herransa palvelijain joukkoon eikä mennyt kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'Kun Daavidille ilmoitettiin: \"Uuria ei ole mennytkään kotiinsa\", sanoi Daavid Uurialle: \"Tulethan sinä matkalta, mikset mennyt kotiisi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Mutta Uuria sanoi Daavidille: \"Arkki ja Israel ja Juuda asuvat lehtimajoissa, minun herrani Jooab ja herrani palvelijat ovat leiriytyneinä kedolla; menisinkö minä kotiin syömään, juomaan ja makaamaan vaimoni kanssa? Niin totta kuin sinä elät ja sinun sielusi elää: sitä minä en tee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Niin Daavid sanoi Uurialle: \"Jää tänne vielä täksi päiväksi, niin minä huomenna päästän sinut menemään\". Niin Uuria jäi Jerusalemiin vielä siksi päiväksi. Seuraavana päivänä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Daavid kutsui hänet luoksensa syömään ja juomaan ja juotti hänet juovuksiin. Mutta illalla hän meni maata vuoteelleen herransa palvelijain joukkoon eikä mennyt kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Seuraavana aamuna Daavid kirjoitti kirjeen Jooabille ja lähetti sen Uurian mukana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'Ja kirjeessä hän kirjoitti näin: \"Pankaa Uuria eturintaan, kiivaimpaan taisteluun, ja vetäytykää takaisin hänen luotaan, että hänet lyötäisiin kuoliaaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Piirittäessään kaupunkia Jooab asetti Uurian siihen paikkaan, missä tiesi urhoollisimpien miesten olevan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'Kun sitten kaupungin miehet ryntäsivät ulos ja ryhtyivät taisteluun Jooabin kanssa, niin väkeä, Daavidin palvelijoita, kaatui, ja myöskin heettiläinen Uuria kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Sitten Jooab lähetti ilmoittamaan Daavidille kaikki, mitä taistelussa oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'Ja hän käski sanansaattajaa sanoen: \"Kun olet kertonut kuninkaalle kaikki, mitä sodassa on tapahtunut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'niin kuningas ehkä kiivastuu ja sanoo sinulle: \'Miksi menitte niin lähelle kaupunkia taistelemaan? Ettekö tienneet, että ne ampuvat muurilta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Kuka surmasi Abimelekin, Jerubbesetin pojan? Eikö nainen heittänyt muurilta jauhinkiviä hänen päällensä, niin että hän kuoli Teebeksessä? Miksi menitte niin lähelle muuria?\' Sano silloin: \'Myöskin sinun palvelijasi heettiläinen Uuria on kuollut\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Sanansaattaja lähti, ja tultuaan hän ilmoitti Daavidille kaiken, mitä Jooab oli lähettänyt hänet ilmoittamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'Ja sanansaattaja sanoi Daavidille: \"Ne miehet olivat meille ylivoimaiset ja ryntäsivät meitä vastaan ulos kedolle, mutta me työnsimme heidät takaisin portin ovelle saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Silloin ampujat ampuivat muurilta sinun palvelijoitasi, ja kuninkaan palvelijoita kuoli; myöskin palvelijasi heettiläinen Uuria kuoli.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Silloin Daavid sanoi sanansaattajalle: \"Sano näin Jooabille: \'Älä pane sitä pahaksesi, sillä miekka syö milloin yhden, milloin toisen; taistele urheasti kaupunkia vastaan ja hävitä se\'. Rohkaise häntä näin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Kun Uurian vaimo kuuli, että hänen miehensä Uuria oli kuollut, piti hän puolisolleen valittajaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'Mutta kun suruaika oli ohitse, lähetti Daavid ottamaan hänet linnaansa, ja hän tuli hänen vaimoksensa. Sitten hän synnytti hänelle pojan. Mutta se, minkä Daavid oli tehnyt, oli paha Herran silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Ja Herra lähetti Naatanin Daavidin tykö. Kun hän tuli hänen tykönsä, sanoi hän hänelle: \"Kaksi miestä oli samassa kaupungissa, toinen rikas ja toinen köyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Rikkaalla oli lampaita ja raavaita hyvin paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'Mutta köyhällä ei ollut muuta kuin yksi ainoa pieni karitsa, jonka hän oli ostanut. Hän elätti sitä, ja se kasvoi hänen luonansa yhdessä hänen lastensa kanssa: se söi hänen leipäpalastansa, joi hänen maljastansa, makasi hänen sylissään ja oli hänelle niinkuin tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Niin rikkaalle miehelle tuli vieras. Mutta hän ei raskinut ottaa omia lampaitansa eikä raavaitansa valmistaakseen ruokaa matkamiehelle, joka oli tullut hänen luoksensa; vaan hän otti köyhän miehen karitsan ja valmisti sen miehelle, joka oli tullut hänen luoksensa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Niin Daavid vihastui kovin siihen mieheen ja sanoi Naatanille: \"Niin totta kuin Herra elää: mies, joka tämän on tehnyt, on kuoleman oma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Ja karitsa hänen on korvattava nelinkertaisesti, koska hän teki näin ja koska hän ei sääliä tuntenut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Mutta Naatan sanoi Daavidille: \"Sinä olet se mies. Näin sanoo Herra, Israelin Jumala: \'Minä olen voidellut sinut Israelin kuninkaaksi ja pelastanut sinut Saulin käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'Minä olen antanut sinulle herrasi linnan ja antanut herrasi vaimot sinun syliisi; ja minä olen antanut sinulle Israelin ja Juudan heimot. Ja jos tämä olisi vähän, niin minä antaisin sinulle vielä sekä sitä että tätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Miksi sinä olet pitänyt halpana Herran sanan ja tehnyt sitä, mikä on pahaa hänen silmissään? Heettiläisen Uurian sinä olet surmannut miekalla, olet tappanut hänet ammonilaisten miekalla, ja hänen vaimonsa sinä olet ottanut vaimoksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Sentähden ei miekka ole milloinkaan väistyvä sinun suvustasi, koska olet pitänyt halpana minut ja ottanut vaimoksesi heettiläisen Uurian vaimon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Näin sanoo Herra: Katso, minä nostatan sinulle onnettomuuden sinun omasta perheestäsi, ja silmiesi edessä minä otan sinun vaimosi ja annan heidät toiselle, ja hän on makaava sinun vaimojesi kanssa tämän auringon nähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Sillä sinä olet tehnyt tekosi salassa, mutta minä teen tämän koko Israelin ja auringon nähden.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Niin Daavid sanoi Naatanille: \"Minä olen tehnyt syntiä Herraa vastaan\". Naatan sanoi Daavidille: \"Niin on myös Herra antanut sinun syntisi anteeksi; sinä et kuole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Mutta koska sinä tällä teolla olet saattanut Herran viholliset pilkkaamaan häntä, niin se poika, joka sinulle on syntynyt, on kuoleva.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Sitten Naatan meni kotiinsa. Ja Herra löi lasta, jonka Uurian vaimo oli Daavidille synnyttänyt, niin että se sairastui vaikeasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Silloin Daavid etsi Jumalaa pojan tähden, ja Daavid paastosi; ja aina kun hän tuli kotiinsa, makasi hän yötä paljaalla maalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Niin hänen hovinsa vanhimmat menivät hänen luokseen saadaksensa hänet nousemaan ylös maasta, mutta hän ei tahtonut; eikä hän syönyt mitään heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'Seitsemäntenä päivänä lapsi kuoli. Mutta Daavidin palvelijat eivät uskaltaneet ilmoittaa hänelle, että lapsi oli kuollut, sillä he ajattelivat: \"Katso, kun me puhuimme hänelle lapsen vielä eläessä, ei hän kuullut meitä. Kuinka voisimme sitten sanoa hänelle, että lapsi on kuollut? Hän voisi tehdä itselleen pahaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'Mutta kun Daavid näki, että hänen palvelijansa kuiskailivat keskenänsä, ymmärsi hän, että lapsi oli kuollut. Ja Daavid kysyi palvelijoiltansa: \"Onko lapsi kuollut?\" He vastasivat: \"On\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Niin Daavid nousi maasta, peseytyi ja voiteli itsensä, muutti vaatteensa, meni Herran huoneeseen ja rukoili. Ja kun hän tuli kotiinsa, pyysi hän ruokaa; ja he tarjosivat, ja hän söi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Mutta hänen palvelijansa sanoivat hänelle: \"Miksi teet näin? Lapsen eläessä sinä paastosit ja itkit, mutta lapsen kuoltua sinä nouset ja syöt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Hän vastasi: \"Kun lapsi vielä eli, paastosin minä ja itkin, sillä minä ajattelin: Kenties Herra on minulle armollinen, niin että lapsi jää eloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Mutta kun hän nyt on kuollut, niin mitä minä enää paastoaisin? Enhän minä enää voi palauttaa häntä. Minä menen hänen tykönsä, mutta hän ei enää palaja minun tyköni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'Daavid lohdutti vaimoansa Batsebaa ja meni hänen luoksensa ja makasi hänen kanssansa. Ja tämä synnytti pojan, ja hän antoi tälle nimen Salomo, ja Herra rakasti häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Ja Daavid laittoi hänet profeetta Naatanin hoitoon, ja tämä kutsui häntä Jedidjaksi Herran tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Mutta Jooab ryhtyi taistelemaan ammonilaisten Rabbaa vastaan ja valloitti kuninkaan kaupungin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'Ja Jooab lähetti sanansaattajat Daavidin luo ja käski sanoa: \"Minä olen ryhtynyt taisteluun Rabbaa vastaan ja olen jo valloittanut vesikaupungin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Niin kokoa nyt jäljellä oleva väki ja asetu leiriin kaupungin edustalle ja valloita se, etten minä sitä valloittaisi ja ottaisi sitä nimiini.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'Silloin Daavid kokosi kaiken väen ja lähti Rabbaan, ryhtyi taisteluun sitä vastaan ja valloitti sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Ja hän otti heidän kuninkaansa kruunun hänen päästänsä-se painoi talentin kultaa, ja siinä oli kallis kivi-ja se pantiin Daavidin päähän. Ja hän vei sangen paljon saalista kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Ja kansan, mitä siellä oli, hän vei pois ja asetti heitä kivisahojen ja rautahakkujen ja rautakirveiden ääreen ja pani heitä tiilentekoon. Näin hän teki kaikille ammonilaisten kaupungeille. Sitten Daavid ja kaikki väki palasi Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Sen jälkeen tapahtui tämä. Daavidin pojalla Absalomilla oli kaunis sisar nimeltä Taamar, ja Daavidin poika Amnon rakastui häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'Ja Amnon tuli aivan sairaaksi tuskasta sisarensa Taamarin tähden; sillä kun tämä oli neitsyt, näytti Amnonista mahdottomalta tehdä hänelle mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Mutta Amnonilla oli ystävä, nimeltä Joonadab, Daavidin veljen Simean poika; ja Joonadab oli hyvin ovela mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Tämä sanoi hänelle: \"Miksi sinä kuihdut noin päivä päivältä, kuninkaan poika? Etkö ilmaise minulle sitä?\" Amnon vastasi hänelle: \"Minä olen rakastunut veljeni Absalomin sisareen Taamariin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'Joonadab sanoi hänelle: \"Paneudu vuoteeseesi ja tekeydy sairaaksi. Ja kun isäsi tulee katsomaan sinua, niin sano hänelle: \'Salli minun sisareni Taamarin tulla antamaan minulle jotakin syötävää; jos hän valmistaisi ruuan minun silmieni edessä, että minä näkisin sen, niin minä söisin hänen kädestään\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Niin Amnon paneutui maata ja tekeytyi sairaaksi. Kun kuningas tuli katsomaan häntä, sanoi Amnon kuninkaalle: \"Salli minun sisareni Taamarin tulla tekemään kaksi kakkua minun silmieni edessä, niin minä syön hänen kädestään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Silloin Daavid lähetti sanan Taamarille linnaan ja käski sanoa hänelle: \"Mene veljesi Amnonin taloon ja valmista hänelle ruokaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Niin Taamar meni veljensä Amnonin taloon, jossa tämä makasi. Ja hän otti taikinaa, sotki ja teki kakkuja hänen silmiensä edessä ja paistoi kakut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'otti pannun ja kaatoi hänen eteensä; mutta tämä ei tahtonut syödä. Ja Amnon sanoi: \"Toimittakaa kaikki minun luotani ulos\". Niin menivät kaikki hänen luotaan ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Sitten Amnon sanoi Taamarille: \"Tuo ruoka tänne sisähuoneeseen, syödäkseni sinun kädestäsi\". Niin Taamar otti tekemänsä kakut ja toi ne sisähuoneeseen veljellensä Amnonille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'Mutta kun hän tarjosi niitä tälle syödä, tarttui tämä häneen ja sanoi hänelle: \"Tule, makaa minun kanssani, sisareni!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Mutta hän sanoi: \"Pois se, veljeni, älä tee minulle väkivaltaa; sillä semmoista ei saa tehdä Israelissa. Älä tee sellaista häpeällistä tekoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Mihin minä joutuisin häpeäni kanssa? Ja sinua pidettäisiin Israelissa houkkana. Puhu nyt kuninkaan kanssa; hän ei minua sinulta kiellä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Mutta tämä ei tahtonut kuulla häntä, vaan voitti hänet, teki hänelle väkivaltaa ja makasi hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Mutta sitten valtasi Amnonin ylen suuri vastenmielisyys häntä kohtaan: vastenmielisyys häntä kohtaan oli suurempi kuin rakkaus, jolla hän oli häntä rakastanut. Ja Amnon sanoi hänelle: \"Nouse, mene tiehesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Silloin hän sanoi hänelle: \"Eikö tämä rikos, että ajat minut pois, ole vielä suurempi kuin se toinen, jonka olet minulle tehnyt?\" Mutta hän ei tahtonut kuulla häntä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'vaan huusi nuoren miehen, joka häntä palveli, ja sanoi: \"Ajakaa ulos minun luotani tämä, ja lukitse ovi hänen jälkeensä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Ja tytöllä oli yllään pitkäliepeinen, hihallinen ihokas; sillä sellaisiin viittoihin olivat kuninkaan tyttäret puetut neitsyenä ollessaan. Ja kun palvelija oli vienyt hänet ulos ja lukinnut oven hänen jälkeensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'sirotteli Taamar tuhkaa päähänsä ja repäisi pitkäliepeisen, hihallisen ihokkaan, joka hänellä oli yllänsä, pani kätensä päänsä päälle ja meni huutaen lakkaamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'Hänen veljensä Absalom sanoi hänelle: \"Onko veljesi Amnon ollut sinun kanssasi? Vaikene nyt, sisareni, onhan hän veljesi. Älä pane tätä asiaa niin sydämellesi.\" Niin Taamar jäi hyljättynä veljensä Absalomin taloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Kun kuningas Daavid kuuli kaiken tämän, vihastui hän kovin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'Mutta Absalom ei puhunut Amnonille sanaakaan, ei pahaa eikä hyvää, sillä Absalom vihasi Amnonia, sentähden että tämä oli tehnyt väkivaltaa hänen sisarellensa Taamarille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'Kahden vuoden kuluttua tapahtui, että Absalomilla oli lammasten keritsiäiset Baal-Haasorissa, joka on Efraimin luona. Ja Absalom kutsui sinne kaikki kuninkaan pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Ja Absalom tuli kuninkaan tykö ja sanoi: \"Katso, palvelijallasi on lammasten keritsiäiset; jospa kuningaskin palvelijoineen tulisi palvelijansa luo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Mutta kuningas vastasi Absalomille: \"Ei niin, poikani, älkäämme tulko kaikki, ettemme olisi sinulle vaivaksi\". Ja vaikka hän pyytämällä pyysi häntä, ei hän kuitenkaan tahtonut mennä, vaan hyvästeli hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Silloin Absalom sanoi: \"Jollet itse tulekaan, salli kuitenkin veljeni Amnonin tulla meidän kanssamme\". Kuningas sanoi hänelle: \"Miksi juuri hänen olisi mentävä sinun kanssasi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'Mutta kun Absalom pyytämällä pyysi häntä, päästi hän Amnonin ja kaikki muut kuninkaan pojat menemään hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Ja Absalom käski palvelijoitaan ja sanoi: \"Pitäkää silmällä, milloin Amnonin sydän tulee iloiseksi viinistä, ja kun minä sanon teille: \'Surmatkaa Amnon\', niin tappakaa hänet älkääkä peljätkö; sillä minähän olen teitä käskenyt. Olkaa lujat ja urhoolliset.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'Absalomin palvelijat tekivät Amnonille, niinkuin Absalom oli käskenyt. Silloin kaikki kuninkaan pojat nousivat, istuivat kukin muulinsa selkään ja pakenivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Heidän vielä ollessaan matkalla tuli Daavidille sanoma: \"Absalom on surmannut kaikki kuninkaan pojat, niin ettei heistä ole jäänyt jäljelle ainoatakaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Silloin kuningas nousi, repäisi vaatteensa ja paneutui maahan maata; ja kaikki hänen palvelijansa seisoivat siinä reväistyin vaattein.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Niin Joonadab, Daavidin veljen Simean poika, puhkesi puhumaan ja sanoi: \"Älköön herrani luulko, että kaikki nuoret miehet, kuninkaan pojat, ovat tapetut; ainoastaan Amnon on kuollut. Sillä ilme Absalomin kasvoilla on tiennyt pahaa siitä päivästä lähtien, jona Amnon teki väkivaltaa hänen sisarellensa Taamarille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Älköön siis herrani, kuningas, panko sydämelleen sitä puhetta, että muka kaikki kuninkaan pojat olisivat kuolleet; sillä ainoastaan Amnon on kuollut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Mutta Absalom pakeni. Kun palvelija, joka oli tähystäjänä, nosti silmänsä ja katseli, niin katso, paljon väkeä tuli tietä, joka oli hänen takanansa, vuoren kuvetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'Silloin Joonadab sanoi kuninkaalle: \"Katso, kuninkaan pojat tulevat. On tapahtunut, niinkuin palvelijasi sanoi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'Juuri kun hän oli saanut sen sanotuksi, niin katso, kuninkaan pojat tulivat; ja he korottivat äänensä ja itkivät. Myöskin kuningas ja kaikki hänen palvelijansa itkivät hyvin katkerasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Mutta Absalom oli paennut ja mennyt Gesurin kuninkaan Talmain, Ammihudin pojan, luo. Ja Daavid suri poikaansa kaiken aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Kun Absalom oli paennut ja tullut Gesuriin, jäi hän sinne kolmeksi vuodeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'Ja kuningas Daavid ikävöi päästä Absalomin luo, sillä hän oli lohduttautunut Amnonin kuolemasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Kun Jooab, Serujan poika, huomasi, että kuninkaan sydän oli kääntynyt Absalomin puoleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'lähetti Jooab noutamaan Tekoasta taitavan vaimon ja sanoi hänelle: \"Ole surevinasi ja pukeudu suruvaatteisiin äläkä voitele itseäsi öljyllä, vaan ole niinkuin vaimo, joka jo kauan on surrut vainajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Mene sitten kuninkaan eteen ja puhu hänelle näin.\" Ja Jooab pani sanat hänen suuhunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Niin tekoalainen vaimo meni kuninkaan eteen, lankesi kasvoillensa maahan ja osoitti kunnioitusta ja sanoi: \"Auta, kuningas!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'Kuningas sanoi hänelle: \"Mikä sinun on?\" Hän vastasi: \"Totisesti, minä olen leskivaimo; mieheni on kuollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'Ja sinun palvelijattarellasi oli kaksi poikaa; he tulivat riitaan keskenänsä kedolla, eikä siellä ollut ketään, joka olisi sovittanut heidän välinsä, ja niin toinen löi toisen kuoliaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'Ja katso, koko suku on noussut palvelijatartasi vastaan, ja he sanovat: \'Anna tänne veljensä surmaaja, että me otamme häneltä hengen hänen tapetun veljensä hengestä ja niin hävitämme perillisenkin\'. Niin he sammuttaisivat kipinänkin, joka minulla vielä on jäljellä, ettei miehestäni jäisi nimeä eikä jälkeläistä maan päälle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Kuningas sanoi vaimolle: \"Mene kotiisi, minä annan käskyn sinusta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'Mutta tekoalainen vaimo sanoi kuninkaalle: \"Herrani, kuningas, tulkoon tämä rikos minun ja minun isäni perheen kannettavaksi, mutta kuningas ja hänen valtaistuimensa olkoon siitä vapaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'Kuningas sanoi: \"Tuo minun eteeni se, joka puhuu sinulle niin, ja hän ei enää sinuun koske\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Vaimo sanoi: \"Muistakoon kuningas Herraa Jumalaansa, ettei verenkostaja saisi tuottaa vielä suurempaa turmiota, ja ettei minun poikaani tuhottaisi\". Silloin hän sanoi: \"Niin totta kuin Herra elää: ei hiuskarvaakaan sinun poikasi päästä ole putoava maahan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Mutta vaimo sanoi: \"Salli palvelijattaresi puhua vielä sananen herralleni, kuninkaalle\". Hän vastasi: \"Puhu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Vaimo sanoi: \"Miksi sinä ajattelet tehdä juuri samoin Jumalan kansaa vastaan, koskapa kuningas ei salli oman hylkäämänsä tulla takaisin? Noin puhuessaanhan kuningas itse joutuu ikäänkuin syylliseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Mehän kuolemme ja olemme niinkuin maahan kaadettu vesi, jota ei voi koota takaisin. Mutta Jumala ei ota pois elämää, vaan sitä hän ajattelee, ettei vain hyljätty joutuisi hänestä erotetuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Sentähden minä tulin nyt puhumaan tätä herralleni, kuninkaalle, kun kansa sai minut pelkäämään; silloin ajatteli palvelijattaresi: minä puhun kuninkaalle, ehkä kuningas tekee palvelijattarensa sanan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Niin, kuningas on kuuleva ja pelastava palvelijattarensa sen miehen kourista, joka tahtoo hävittää sekä minut että minun poikani Jumalan perintöosasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Ja palvelijattaresi ajatteli: minun herrani, kuninkaan, sana on rauhoittava minut. Sillä herrani, kuningas, on Jumalan enkelin kaltainen, niin että hän kuulee, mikä hyvää on ja mikä pahaa. Ja Herra, sinun Jumalasi, olkoon sinun kanssasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Kuningas vastasi ja sanoi vaimolle: \"Älä salaa minulta mitään, mitä minä sinulta kysyn\". Vaimo sanoi: \"Herrani, kuningas, puhukoon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Kuningas kysyi: \"Eikö Jooabin käsi ole mukanasi kaikessa tässä?\" Vaimo vastasi ja sanoi: \"Niin totta kuin sinun sielusi, minun herrani, kuningas, elää: ei pääse oikeaan eikä vasempaan siitä, mitä herrani, kuningas, puhuu. Niin, sinun palvelijasi Jooab on käskenyt minua tähän ja pannut kaikki nämä sanat palvelijattaresi suuhun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Antaakseen asialle toisen muodon on palvelijasi Jooab näin tehnyt; mutta herrani on viisas niinkuin Jumalan enkeli ja tietää kaiken, mitä maan päällä tapahtuu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Silloin kuningas sanoi Jooabille: \"Katso, tämän minä teen: mene ja tuo takaisin nuorukainen Absalom\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'Niin Jooab lankesi kasvoilleen maahan, osoitti kunnioitusta ja siunasi kuningasta. Ja Jooab sanoi: \"Nyt palvelijasi tietää, että minä olen saanut armon sinun silmiesi edessä, herrani, kuningas, koska kuningas tekee palvelijansa sanan mukaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Sitten Jooab nousi ja meni Gesuriin ja toi Absalomin Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Mutta kuningas sanoi: \"Hän siirtyköön omaan taloonsa, mutta älköön tulko minun kasvojeni eteen\". Niin Absalom siirtyi omaan taloonsa, mutta ei tullut kuninkaan kasvojen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'Mutta koko Israelissa ei ollut yhtään niin kaunista miestä kuin Absalom, eikä ketään niin ylisteltyä: kantapäästä kiireeseen asti ei ollut hänessä yhtään virheä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'Ja kun hän ajatti hiuksensa-aina vuoden kuluttua hän ajatti ne, sillä ne tulivat hänelle niin raskaiksi, että hänen täytyi ne ajattaa-niin painoivat hänen hiuksensa kaksisataa sekeliä kuninkaan painoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'Ja Absalomille syntyi kolme poikaa ja tytär, jonka nimi oli Taamar; hän oli kaunis nainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'Absalom asui kaksi vuotta Jerusalemissa, tulematta kuninkaan kasvojen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Ja Absalom lähetti sanan Jooabille lähettääkseen hänet kuninkaan luo; mutta tämä ei tahtonut tulla hänen luokseen. Ja hän lähetti vielä toisen kerran, mutta hän ei tahtonut tulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Silloin hän sanoi palvelijoillensa: \"Katsokaa, Jooabin maapalsta on minun maapalstani vieressä, ja hänellä on siinä ohraa; menkää ja sytyttäkää se palamaan\". Ja Absalomin palvelijat sytyttivät maapalstan palamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Niin Jooab nousi ja meni Absalomin luo taloon ja sanoi hänelle: \"Miksi sinun palvelijasi ovat sytyttäneet palamaan maapalstan, joka on minun omani?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'Absalom vastasi Jooabille: \"Katso, minä lähetin sinulle sanan: Tule tänne, niin minä lähetän sinut kuninkaan luo sanomaan: Mitä varten minä olen tullut kotiin Gesurista? Olisi parempi, jos vielä olisin siellä. Nyt minä tahdon tulla kuninkaan kasvojen eteen; ja jos minussa on vääryys, niin surmatkoon hän minut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Silloin Jooab meni kuninkaan tykö ja kertoi hänelle tämän. Ja hän kutsui Absalomin, ja tämä tuli kuninkaan tykö ja kumartui kasvoilleen maahan kuninkaan eteen. Ja kuningas suuteli Absalomia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'Mutta sitten tapahtui, että Absalom hankki itsellensä vaunut ja hevoset sekä viisikymmentä miestä, jotka juoksivat hänen edellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'Ja Absalomilla oli tapana asettua varhain aamulla sen tien viereen, joka vei portille; ja kun joku oli tulossa kuninkaan eteen saamaan oikeutta riita-asiassaan, kutsui Absalom hänet ja kysyi: \"Mistä kaupungista sinä olet?\" Kun tämä vastasi: \"Palvelijasi on siitä tai siitä Israelin sukukunnasta\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'sanoi Absalom hänelle: \"Asiasi on kyllä hyvä ja oikea, mutta kuninkaan luona ei ole ketään, joka sinua kuulisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Ja Absalom sanoi vielä: \"Jospa minut asetettaisiin tuomariksi maahan! Silloin tulisi minun eteeni jokainen, jolla on riita-tai oikeusasia, ja minä antaisin hänelle oikeuden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'Ja kun joku lähestyi kumartaaksensa häntä, ojensi hän kätensä, tarttui häneen ja suuteli häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'Näin Absalom teki kaikille israelilaisille, jotka tulivat kuninkaan eteen saamaan oikeutta. Ja niin Absalom varasti Israelin miesten sydämet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'Neljän vuoden kuluttua sanoi Absalom kerran kuninkaalle: \"Salli minun mennä Hebroniin täyttämään lupaus, jonka olen Herralle tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Sillä asuessani Gesurissa, Aramissa, sinun palvelijasi teki lupauksen ja sanoi: \'Jos Herra antaa minun tulla takaisin Jerusalemiin, niin minä palvelen Herraa\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'Kuningas sanoi hänelle: \"Mene rauhassa\". Niin hän nousi ja meni Hebroniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Mutta Absalom lähetti vakoojia kaikkiin Israelin sukukuntiin ja sanoi: \"Kun kuulette pasunan äänen, niin sanokaa: \'Absalom on tullut kuninkaaksi Hebronissa\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Ja Absalomin kanssa oli Jerusalemista kutsuvieraina mennyt kaksisataa miestä, jotka menivät sinne aivan viattomina, tietämättä mitään koko asiasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Ja Absalom lähetti myös, sillä aikaa kun uhrasi teurasuhrejaan, noutamaan giilolaisen Ahitofelin, Daavidin neuvonantajan, hänen kaupungistaan Giilosta. Ja salaliitto vahvistui, ja yhä enemmän kansaa meni Absalomin puolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Niin tultiin Daavidin luo ja ilmoitettiin: \"Israelin miesten sydämet ovat kääntyneet Absalomin puolelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Silloin Daavid sanoi kaikille palvelijoillensa, jotka olivat hänen luonaan Jerusalemissa: \"Nouskaa, paetkaamme, sillä meillä ei ole muuta pelastusta Absalomin käsistä. Lähtekää kiiruusti, ettei hän äkkiä saavuttaisi meitä ja saattaisi onnettomuutta meille ja surmaisi kaupungin asukkaita miekan terällä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'Kuninkaan palvelijat vastasivat kuninkaalle: \"Tehtäköön aivan niinkuin herrani, kuningas, harkitsee parhaaksi. Me olemme sinun palvelijoitasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'Ja kuningas lähti, ja koko hänen hovinsa seurasi häntä; kuitenkin jätti kuningas kymmenen sivuvaimoaan jäljelle vartioimaan linnaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Niin kuningas lähti, ja kaikki väki seurasi häntä. He pysähtyivät kaukaisimman talon kohdalle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'kaikkien hänen palvelijainsa kulkiessa hänen ohitsensa. Myös kaikki kreetit ja pleetit sekä kaikki gatilaiset, kuusisataa miestä, jotka olivat tulleet hänen jäljessään Gatista, kulkivat kuninkaan ohitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Niin kuningas sanoi gatilaiselle Ittaille: \"Miksi sinäkin tulet meidän kanssamme? Käänny takaisin ja jää kuninkaan luo, sillä sinä olet vieras, vieläpä maanpaossa kotoasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Eilen sinä tulit; ottaisinko minä jo tänä päivänä sinut harhailemaan meidän kanssamme matkallamme, kun minä itsekin menen, minne menenkin? Käänny takaisin ja vie veljesi mukanasi. Armo ja uskollisuus sinulle!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Mutta Ittai vastasi kuninkaalle ja sanoi: \"Niin totta kuin Herra elää, ja niin totta kuin herrani, kuningas, elää: missä paikassa herrani, kuningas, on, siellä tahtoo myös palvelijasi olla, olkoonpa se elämäksi tai kuolemaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'Daavid sanoi Ittaille: \"Tule sitten ja kulje minun ohitseni\". Niin gatilainen Ittai kulki ohitse ja kaikki hänen miehensä ja kaikki vaimot ja lapset, jotka olivat hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Ja koko maa itki ääneen, kun kaikki väki kulki ohitse. Ja kun kuningas oli kulkemassa Kidronin laakson poikki, kaiken väen kulkiessa erämaan tielle päin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'niin katso, siinä oli myös Saadok ynnä hänen kanssaan kaikki leeviläiset, jotka kantoivat Jumalan liitonarkkia. Mutta he laskivat Jumalan arkin maahan, ja Ebjatar uhrasi, kunnes kaikki väki kaupungista oli ehtinyt kulkea ohitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Niin kuningas sanoi Saadokille: \"Vie Jumalan arkki takaisin kaupunkiin. Jos minä saan armon Herran silmien edessä, tuo hän minut takaisin ja antaa minun vielä nähdä hänet ja hänen asumuksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Mutta jos hän sanoo näin: \'Minä en ole mielistynyt sinuun\', niin katso, hän tehköön minulle, minkä hyväksi näkee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Ja kuningas sanoi pappi Saadokille: \"Sinähän olet näkijä; palaa rauhassa kaupunkiin, sinä ja sinun poikasi Ahimaas ja Ebjatarin poika Joonatan, molemmat poikanne, teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Katsokaa, minä viivyn kahlauspaikoissa erämaassa, kunnes teiltä tulee sana minun tiedokseni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Niin Saadok ja Ebjatar veivät Jumalan arkin takaisin Jerusalemiin ja jäivät sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Mutta Daavid kulki itkien Öljymäkeä ylös, pää peitettynä ja paljain jaloin. Ja kaikki väki, mikä oli hänen kanssansa, oli myös peittänyt päänsä, ja he kulkivat itkien lakkaamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Ja kun Daavidille kerrottiin, että myös Ahitofel oli salaliittolaisten joukossa Absalomin puolella, sanoi Daavid: \"Herra, käännä Ahitofelin neuvo hulluudeksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'Kun sitten Daavid oli tullut vuoren laelle, jossa Jumalaa rukoiltiin, tuli arkilainen Huusai häntä vastaan, ihokas reväistynä ja multaa pään päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'Daavid sanoi hänelle: \"Jos sinä tulet minun kanssani, niin olet minulle vain kuormaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Mutta jos palaat kaupunkiin ja sanot Absalomille: \'Minä tahdon olla sinun palvelijasi, kuningas. Minä olen ennen ollut sinun isäsi palvelija, mutta nyt tahdon olla sinun palvelijasi\', niin voit olla minulle avuksi tekemällä Ahitofelin neuvon tyhjäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Siellähän ovat sinun kanssasi myöskin papit, Saadok ja Ebjatar; kaikki, mitä kuulet kuninkaan linnasta, ilmoita papeille, Saadokille ja Ebjatarille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Katso, heillä on siellä mukanaan myös molemmat poikansa, Saadokilla Ahimaas ja Ebjatarilla Joonatan; näiden kautta voitte lähettää minulle tiedon kaikesta, mitä kuulette.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Niin Huusai, Daavidin ystävä, meni kaupunkiin, juuri kun Absalom tuli Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'Kun Daavid oli kulkenut vähän matkaa vuoren laelta, tuli häntä vastaan Siiba, Mefibosetin palvelija, mukanaan satuloitu aasipari, jonka selässä oli kaksisataa leipää, sata rusinakakkua, sata hedelmää ja leili viiniä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Niin kuningas sanoi Siiballe: \"Mitä sinä näillä teet?\" Siiba vastasi: \"Aasit ovat kuninkaan perheelle ratsastettaviksi, leipä ja hedelmät palvelijoille syötäviksi ja viini uupuneiden juotavaksi erämaassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'Kuningas sanoi: \"Mutta missä sinun herrasi poika on?\" Siiba vastasi kuninkaalle: \"Hän jäi Jerusalemiin; sillä hän ajatteli: \'Nyt Israelin heimo antaa minulle takaisin isäni kuninkuuden\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Niin kuningas sanoi Siiballe: \"Katso, kaikki, mitä Mefibosetilla on, tulee sinun omaksesi\". Siiba vastasi: \"Minä kumarran; suo minun saada armo sinun silmiesi edessä, herrani, kuningas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'Kun kuningas Daavid tuli Bahurimiin, niin katso, sieltä tuli mies, joka oli sukua Saulin perheelle, nimeltä Siimei, Geeran poika; hän tuli ja kiroili tullessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'Ja hän viskeli kivillä Daavidia ja kaikkia kuningas Daavidin palvelijoita, vaikka kaikki väki ja kaikki urhot olivat hänen oikealla ja vasemmalla puolellaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'Ja kiroillessaan häntä Siimei sanoi näin: \"Pois, pois, sinä murhamies, sinä kelvoton!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Herra kostaa sinulle kaiken Saulin perheen veren, hänen, jonka sijaan sinä olet tullut kuninkaaksi. Ja Herra antaa nyt kuninkuuden sinun poikasi Absalomin käteen. Ja katso, sinä olet itse joutunut onnettomuuteen, sillä murhamies sinä olet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Niin Abisai, Serujan poika, sanoi kuninkaalle: \"Miksi tuo koiranraato saa kiroilla herraani, kuningasta? Anna minun mennä ja lyödä häneltä pää poikki.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Mutta kuningas vastasi: \"Mitä teillä on minun kanssani tekemistä, te Serujan pojat? Jos hän kiroilee ja jos Herra on käskenyt häntä: \'Kiroile Daavidia\', niin kuka voi sanoa: \'Miksi teet niin?\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Ja Daavid sanoi vielä Abisaille ja kaikille palvelijoillensa: \"Katso, oma poikani, joka on lähtenyt minun ruumiistani, väijyy henkeäni; miksi ei sitten tämä benjaminilainen? Antakaa hänen olla, kiroilkoon vain; sillä Herra on häntä käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Ehkä Herra vielä näkee minun kurjuuteni, ja ehkä Herra maksaa minulle hyvällä sen kirouksen, joka tänä päivänä kohtaa minua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Ja Daavid kulki miehinensä tietä myöten, ja Siimei kulki pitkin vuoren kuvetta rinnan hänen kanssansa, kiroili kulkiessaan ja viskeli kiviä ja heitteli soraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Kun kuningas ja kaikki väki, joka oli hänen kanssansa, oli tullut Ajefimiin, hengähti hän siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Mutta Absalom ja kaikki kansa, Israelin miehet, olivat tulleet Jerusalemiin; ja Ahitofel oli hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'Kun arkilainen Huusai, Daavidin ystävä, tuli Absalomin luo, sanoi Huusai Absalomille: \"Eläköön kuningas! Eläköön kuningas!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Absalom sanoi Huusaille: \"Tällainenko on rakkautesi ystävääsi kohtaan? Miksi et mennyt ystäväsi kanssa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Huusai vastasi Absalomille: \"Ei, vaan kenen Herra ja tämä kansa ja kaikki Israelin miehet ovat valinneet, sen puolella minä olen, ja sen luokse minä jään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Ja toisekseen: ketä minä palvelisin? Enkö hänen poikaansa? Niinkuin olen palvellut sinun isääsi, niin tahdon palvella sinuakin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Sitten Absalom sanoi Ahitofelille: \"Antakaa nyt neuvo, mitä meidän on tehtävä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Ahitofel vastasi Absalomille: \"Mene isäsi sivuvaimojen tykö, jotka hän on jättänyt linnaa vartioimaan. Silloin koko Israel saa kuulla, että sinä olet saattanut itsesi isäsi vihoihin, ja kaikki, jotka ovat sinun kanssasi, saavat rohkeutta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Niin Absalomille pystytettiin teltta katolle; ja Absalom meni isänsä sivuvaimojen tykö koko Israelin nähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Ahitofelin antama neuvo oli siihen aikaan niinkuin Jumalalta saatu vastaus: sen arvoinen oli jokainen Ahitofelin neuvo sekä Daavidille että Absalomille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Ja Ahitofel sanoi Absalomille: \"Salli minun valita kaksitoista tuhatta miestä ja nousta tänä yönä ajamaan takaa Daavidia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'niin minä karkaan hänen kimppuunsa, kun hän on väsynyt ja hänen kätensä ovat herpoutuneet, ja saatan hänet kauhun valtaan, niin että kaikki väki, mitä hänen kanssansa on, pakenee. Sitten minä surmaan kuninkaan yksinänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'Ja minä palautan kaiken kansan sinun luoksesi. Kaikkien palaaminen riippuu siitä miehestä, jota sinä etsit; kaikki kansa saa rauhan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'Tämä miellytti Absalomia ja kaikkia Israelin vanhimpia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Kuitenkin sanoi Absalom: \"Kutsukaa myös arkilainen Huusai, kuullaksemme, mitä hänellä on sanottavana\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Ja kun Huusai tuli Absalomin tykö, sanoi Absalom hänelle: \"Niin ja niin puhui Ahitofel. Onko meidän tehtävä hänen sanansa mukaan? Jollei, niin puhu sinä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Huusai vastasi Absalomille: \"Ei ole hyvä se neuvo, jonka Ahitofel tällä kertaa on antanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Ja Huusai sanoi vielä: \"Sinä tiedät, että isäsi ja hänen miehensä ovat urhoja ja julmistuneita niinkuin karhu kedolla, jolta poikaset on riistetty; myöskin on isäsi sotilas, joka väkineen ei lepää yöllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Katso, hän on nyt piiloutunut johonkin onkaloon tai muuhun paikkaan. Jos jo alussa meikäläisiä kaatuisi ja se saataisiin kuulla, niin sanottaisiin: \'Väelle, joka seurasi Absalomia, on tullut tappio\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Silloin urhoollisinkin, jolla on sydän kuin leijonalla, menettäisi rohkeutensa; sillä koko Israel tietää, että sinun isäsi on sankari ja että ne, jotka ovat hänen kanssansa, ovat urhoollisia miehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Sentähden on minun neuvoni tämä: Koottakoon sinun luoksesi koko Israel Daanista aina Beersebaan asti, että niitä tulee niin paljon kuin hiekkaa meren rannalla; ja lähde sinä itsekin taisteluun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'Kun me sitten karkaamme hänen kimppuunsa, missä ikinä hänet tavataan, niin me painumme hänen päällensä, niinkuin kaste laskeutuu maahan. Eikä hänestä ja kaikista niistä miehistä, jotka ovat hänen kanssaan, jää jäljelle ainoatakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Ja jos hän vetäytyisi johonkin kaupunkiin, niin koko Israel asettaisi köydet sen kaupungin ympärille, ja me kiskoisimme sen alas laaksoon, kunnes siitä ei löytyisi kiveäkään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Silloin sanoivat Absalom ja kaikki Israelin miehet: \"Arkilaisen Huusain neuvo on parempi kuin Ahitofelin neuvo\". Sillä Herra oli säätänyt sen näin, tehdäkseen tyhjäksi Ahitofelin hyvän neuvon, että Herra saattaisi Absalomin onnettomuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Ja Huusai sanoi papeille, Saadokille ja Ebjatarille: \"Sen ja sen neuvon on Ahitofel antanut Absalomille ja Israelin vanhimmille, ja sen ja sen neuvon olen minä antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Niin lähettäkää nyt pian ja ilmoittakaa Daavidille tämä sana: \'Älä jää yöksi kahlauspaikkoihin erämaahan, vaan mene joen yli, ettei kuningas ja kaikki väki, joka on hänen kanssaan, joutuisi perikatoon\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Ja Joonatan ja Ahimaas olivat asettuneet Roogelin lähteelle, ja eräs palvelijatar kuljetti heille sinne sanaa; sitten he aina menivät ja veivät sanan kuningas Daavidille. Sillä he eivät uskaltaneet näyttäytyä menemällä kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Mutta eräs poikanen näki heidät ja ilmoitti Absalomille. Silloin he molemmat menivät kiiruusti pois ja tulivat erään miehen taloon Bahurimiin. Hänellä oli kaivo pihallaan, ja he laskeutuivat siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'Ja hänen vaimonsa otti peitteen ja levitti sen kaivon suulle ja sirotti jyviä sen päälle, niin ettei voitu huomata mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Kun Absalomin palvelijat tulivat vaimon luo taloon, kysyivät he: \"Missä ovat Ahimaas ja Joonatan?\" Vaimo vastasi heille: \"Tuosta he menivät vesilätäkön yli\". He etsivät, ja kun eivät heitä löytäneet, palasivat he takaisin Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'Ja niin pian kuin he olivat menneet, nousivat toiset kaivosta, menivät ja veivät sanan kuningas Daavidille; he sanoivat Daavidille: \"Nouskaa ja menkää joutuin veden yli, sillä sen ja sen neuvon on Ahitofel antanut teidän turmioksenne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Silloin Daavid ja kaikki väki, mikä oli hänen kanssaan, nousi, ja he menivät Jordanin yli. Ja kun aamu valkeni, ei ollut ainoatakaan, joka ei olisi tullut Jordanin yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Mutta kun Ahitofel näki, ettei hänen neuvoansa noudatettu, satuloi hän aasinsa, nousi ja lähti kotiinsa omaan kaupunkiinsa, ja kun hän oli toimittanut talonsa, hirttäytyi hän; niin hän kuoli, ja hänet haudattiin isänsä hautaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'Daavid oli tullut Mahanaimiin, kun Absalom ja kaikki Israelin miehet hänen kanssaan menivät Jordanin yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'Mutta Absalom oli asettanut Amasan Jooabin sijaan sotajoukon ylipäälliköksi. Ja Amasa oli Jitra nimisen jisreeliläisen miehen poika; tämä mies oli yhtynyt Abigailiin, Naahaan tyttäreen, Jooabin äidin Serujan sisareen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Ja Israel ja Absalom leiriytyivät Gileadin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'Kun Daavid tuli Mahanaimiin, niin Soobi, Naahaan poika, ammonilaisten Rabbasta, ja Maakir, Ammielin poika, Loodebarista, ja gileadilainen Barsillai, Roogelimista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'toivat sinne vuoteita, vateja ja saviastioita, nisuja, ohria, jauhoja ja paahdettuja jyviä, papuja, herneitä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'sekä hunajaa, voita, lampaita ja juustoja ruuaksi Daavidille ja väelle, mikä oli hänen kanssansa; sillä he ajattelivat: \"Väki on nälissään, uuvuksissa ja janoissaan erämaassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Ja Daavid piti mukanaan olevan väen katselmuksen, ja asetti sille tuhannen-ja sadanpäämiehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'Sitten Daavid lähetti väen liikkeelle: yhden kolmanneksen Jooabin johdolla, toisen kolmanneksen Abisain, Serujan pojan, Jooabin veljen, johdolla ja kolmannen kolmanneksen gatilaisen Ittain johdolla. Ja kuningas sanoi kansalle: \"Minä lähden myös itse teidän kanssanne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Mutta kansa vastasi: \"Älä lähde; sillä jos me pakenemme, ei meistä välitetä, ja jos puolet meistä saa surmansa, ei meistä silloinkaan välitetä, mutta sinä olet niinkuin kymmenen tuhatta meistä. Sentähden on nyt parempi, että sinä olet valmiina tulemaan meille avuksi kaupungista.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Niin kuningas sanoi heille: \"Minä teen, minkä te hyväksi näette\". Ja kuningas asettui portin pieleen, ja kaikki väki lähti liikkeelle sadan ja tuhannen joukkoina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'Mutta kuningas käski Jooabia, Abisaita ja Ittaita ja sanoi: \"Pidelkää minulle mieliksi hellävaroen nuorukaista Absalomia\". Ja kaikki kansa kuuli, kuinka kuningas antoi kaikille päälliköille käskyn Absalomista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Niin väki lähti kentälle Israelia vastaan, ja taistelu tapahtui Efraimin metsässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Siellä Daavidin palvelijat voittivat Israelin väen, ja siellä oli sinä päivänä suuri mieshukka: kaksikymmentä tuhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Ja taistelu levisi koko siihen seutuun; ja metsä söi sinä päivänä enemmän väkeä kuin miekka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Ja Absalom sattui yhteen Daavidin palvelijain kanssa. Absalom ratsasti muulilla; ja kun muuli tuli suuren, tiheäoksaisen tammen alle, tarttui hän päästään tammeen, niin että hän jäi riippumaan taivaan ja maan välille, kun muuli juoksi pois hänen altansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Sen näki eräs mies ja ilmoitti sen Jooabille ja sanoi: \"Katso, minä näin Absalomin riippuvan tammessa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Niin Jooab sanoi miehelle, joka ilmoitti hänelle tämän: \"Jos näit sen, miksi et lyönyt häntä siinä maahan? Minun olisi ollut annettava sinulle kymmenen hopeasekeliä ja vyö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Mutta mies vastasi Jooabille: \"Vaikka käsiini punnittaisiin tuhat hopeasekeliä, en sittenkään kävisi käsiksi kuninkaan poikaan, sillä kuningas käski meidän kuultemme sinua, Abisaita ja Ittaita sanoen: \'Pitäkää vaari nuorukaisesta Absalomista\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Vai kavaltaisinko minä oman henkeni? Sillä eihän mikään pysy salassa kuninkaalta, ja sinä pysyisit kyllä syrjässä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Niin Jooab sanoi: \"Minä en enää kuluta aikaa sinun kanssasi\". Sitten hän otti kolme keihästä käteensä ja pisti ne Absalomin rintaan, kun hän vielä eli tammessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'Ja kymmenen nuorta miestä, Jooabin aseenkantajaa, astui Absalomin luo, ja he löivät hänet kuoliaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Sitten Jooab puhalsi pasunaan; ja väki palasi ajamasta takaa Israelia, kun Jooab pysähdytti väen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'Ja he ottivat Absalomin ja heittivät hänet metsässä suureen kuoppaan ja pystyttivät sangen suuren kiviroukkion hänen päällensä. Mutta koko Israel pakeni, kukin majallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Mutta Absalom oli eläessään hankkinut ja pystyttänyt itsellensä patsaan, joka on Kuninkaanlaaksossa; sillä hän sanoi: \"Minulla ei ole poikaa, joka säilyttäisi minun nimeni muiston\". Patsaan hän oli kutsunut nimensä mukaan, ja sen nimi on vielä tänäkin päivänä Absalomin muistomerkki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Ja Ahimaas, Saadokin poika, sanoi: \"Minä juoksen saattamaan kuninkaalle sen ilosanoman, että Herra on auttanut hänet hänen vihollistensa käsistä oikeuteensa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Mutta Jooab sanoi hänelle: \"Tänä päivänä et ole ilosanoman saattaja; jonakin muuna päivänä saattanet ilosanoman, mutta tänä päivänä et saata ilosanomaa, sillä onhan kuninkaan poika kuollut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Sitten Jooab sanoi eräälle etiopialaiselle: \"Mene ja ilmoita kuninkaalle, mitä olet nähnyt\". Niin etiopialainen kumarsi Jooabille ja lähti juoksemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Mutta Ahimaas, Saadokin poika, sanoi taas Jooabille: \"Tulkoon mitä tahansa, mutta minä juoksen etiopialaisen jälkeen\". Jooab sanoi: \"Miksi sinä juoksisit, poikani, eihän sinulle siitä ilosanomansaattajan palkkaa tule?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, '\"Tulkoon mitä tahansa, mutta minä juoksen.\" Silloin hän sanoi hänelle: \"Juokse sitten\". Niin Ahimaas lähti juoksemaan Lakeuden tietä ja sivuutti etiopialaisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'Daavid istui molempien porttien välissä. Ja tähystäjä meni portin katolle muurin päälle; kun hän nosti silmänsä ja katseli, niin katso: mies tuli juosten yksinänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Tähystäjä huusi ja ilmoitti sen kuninkaalle. Niin kuningas sanoi: \"Jos hän on yksin, niin hänellä on ilosanoma\". Ja hän tuli yhä lähemmäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Sitten tähystäjä näki toisen miehen tulevan juosten; ja hän huusi porttiin sanoen: \"Minä näen vielä toisen miehen tulevan juosten yksinänsä\". Kuningas sanoi: \"Sekin saattaa ilosanomaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Ja tähystäjä sanoi: \"Sen ensimmäisen juoksu näyttää minusta Ahimaasin, Saadokin pojan, juoksulta\". Niin kuningas sanoi: \"Se on hyvä mies; hän tulee hyviä sanomia tuoden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Ja Ahimaas huusi ja sanoi kuninkaalle: \"Rauha!\" Sitten hän kumartui kasvoillensa maahan kuninkaan eteen ja sanoi: \"Kiitetty olkoon Herra, sinun Jumalasi, joka on antanut sinun käsiisi ne miehet, jotka nostivat kätensä herraani, kuningasta, vastaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'Niin kuningas kysyi: \"Voiko nuorukainen Absalom hyvin?\" Ahimaas vastasi: \"Minä näin suuren väkijoukon, kun kuninkaan palvelija Jooab lähetti minut, palvelijasi; mutta en tiedä, mitä se oli\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Kuningas sanoi: \"Astu syrjään ja asetu sinne\". Niin hän astui syrjään ja jäi seisomaan sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Ja katso, etiopialainen tuli perille, ja etiopialainen sanoi: \"Ilosanoma herralleni, kuninkaalle: Herra on tänä päivänä auttanut sinut oikeuteesi kaikkien niiden käsistä, jotka ovat nousseet sinua vastaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Kuningas kysyi etiopialaiselta: \"Voiko nuorukainen Absalom hyvin?\" Etiopialainen vastasi: \"Käyköön herrani kuninkaan vihollisille ja kaikille, jotka nousevat sinua vastaan tehdäksensä sinulle pahaa, niinkuin on käynyt sille nuorukaiselle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, '{19:1} Kuningas tuli kovin järkytetyksi, nousi portin päällä olevaan yläsaliin ja itki. Ja mennessänsä hän huusi näin: \"Poikani Absalom, minun poikani, oma poikani Absalom! Jospa minä olisin kuollut sinun sijastasi! Absalom, poikani, oma poikani!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'Jooabille ilmoitettiin: \"Katso, kuningas itkee ja suree Absalomia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, '{19:3} Ja voitto muuttui sinä päivänä suruksi kaikelle kansalle, koska kansa sinä päivänä kuuli sanottavan, että kuningas oli murheissaan poikansa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Ja kansa tuli sinä päivänä kaupunkiin ikäänkuin varkain, niinkuin tulee varkain väki, joka on häväissyt itsensä pakenemalla taistelusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Mutta kuningas oli peittänyt kasvonsa, ja hän huusi kovalla äänellä: \"Poikani Absalom! Absalom, poikani, oma poikani!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Niin Jooab meni sisälle kuninkaan luo ja sanoi: \"Sinä olet tänä päivänä nostanut häpeän kaikkien palvelijaisi kasvoille, vaikka he tänä päivänä ovat pelastaneet sekä sinun oman henkesi että sinun poikiesi, tyttäriesi, vaimojesi ja sivuvaimojesi hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Sinähän rakastat niitä, jotka sinua vihaavat, ja vihaat niitä, jotka sinua rakastavat. Sillä nyt sinä olet antanut tietää, ettei sinulla olekaan päälliköitä eikä palvelijoita; -niin, nyt minä tiedän, että jos Absalom olisi elossa ja me kaikki olisimme tänään kuolleet, se olisi sinulle mieleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Mutta nouse nyt ylös ja mene ulos ja puhuttele ystävällisesti palvelijoitasi. Sillä minä vannon Herran kautta: jollet mene ulos, niin ei totisesti yhtä ainoatakaan miestä jää luoksesi tänä yönä; ja tämä on oleva sinulle suurempi onnettomuus kuin mikään muu, joka on kohdannut sinua nuoruudestasi tähän päivään saakka.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Silloin kuningas nousi ja asettui istumaan porttiin. Ja kaikelle kansalle ilmoitettiin ja sanottiin: \"Kuningas istuu nyt portissa\". Silloin kaikki kansa tuli kuninkaan eteen. Mutta kun Israel oli paennut, kukin majallensa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'alkoi kaikki kansa kaikkien Israelin heimojen keskuudessa riidellä ja sanoa: \"Kuningas on pelastanut meidät vihollistemme kourista, hän on vapauttanut meidät filistealaisten kourista, ja nyt hän on Absalomia paossa, maasta poissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Mutta Absalom, jonka me olemme voidelleet kuninkaaksemme, on kuollut taistelussa. Miksi ette nyt ryhdy tuomaan kuningasta takaisin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Mutta kuningas Daavid lähetti sanan papeille Saadokille ja Ebjatarille ja käski sanoa: \"Puhukaa Juudan vanhimmille ja sanokaa: \'Miksi te olette viimeiset tuomaan kuningasta takaisin hänen linnaansa? Sillä se, mitä koko Israel puhuu, on tullut kuninkaan tietoon hänen olinpaikkaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Te olette minun veljiäni, minun luutani ja lihaani. Miksi te olisitte viimeiset tuomaan kuningasta takaisin?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Ja Amasalle sanokaa: \'Olethan sinä minun luutani ja lihaani. Jumala rangaiskoon minua nyt ja vasta, jollet sinä kaikkea elinaikaasi ole minun sotapäällikköni Jooabin sijassa.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'Näin hän taivutti kaikkien Juudan miesten sydämet, niin että he yhtenä miehenä lähettivät sanomaan kuninkaalle: \"Palaa takaisin, sinä ja kaikki sinun palvelijasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Niin kuningas palasi takaisin ja tuli Jordanille; mutta Juuda oli tullut Gilgaliin mennäkseen kuningasta vastaan ja tuodakseen kuninkaan Jordanin yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Myöskin Siimei, Geeran poika, benjaminilainen Bahurimista, lähti kiiruusti Juudan miesten kanssa kuningas Daavidia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'Ja hänen kanssansa oli tuhat miestä Benjaminista sekä Siiba, Saulin perheen palvelija, viidentoista poikansa ja kahdenkymmenen palvelijansa kanssa. Nämä olivat rientäneet Jordanille ennen kuningasta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'ja menneet yli kahlauspaikasta tuomaan kuninkaan perhettä ja toimittamaan, mitä hän näkisi hyväksi määrätä. Mutta Siimei, Geeran poika, heittäytyi kuninkaan eteen, kun hän oli lähtemässä Jordanin yli,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'ja sanoi kuninkaalle: \"Älköön herrani lukeko minulle pahaa tekoani älköönkä muistelko, kuinka väärin palvelijasi teki sinä päivänä, jona herrani, kuningas, lähti Jerusalemista; älköön kuningas panko sitä sydämellensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Sillä palvelijasi tuntee, että olen tehnyt synnin; sentähden minä olen tänä päivänä ensimmäisenä koko Joosefin heimosta tullut tänne herraani, kuningasta, vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Niin Abisai, Serujan poika, puuttui puheeseen ja sanoi: \"Eikö Siimei ole rangaistava kuolemalla siitä, että hän on kiroillut Herran voideltua?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Mutta Daavid vastasi: \"Mitä teillä on minun kanssani tekemistä, te Serujan pojat, kun tulette minulle tänä päivänä kiusaajaksi? Olisiko ketään Israelissa tänä päivänä kuolemalla rangaistava? Minä tiedän tulleeni tänä päivänä Israelin kuninkaaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'Ja kuningas sanoi Siimeille: \"Sinä et kuole\". Ja kuningas vannoi sen hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Mefiboset, Saulin pojanpoika, oli myös tullut kuningasta vastaan. Hän ei ollut siistinyt jalkojansa, ei siistinyt partaansa eikä pesettänyt vaatteitansa siitä päivästä, jona kuningas lähti, siihen päivään asti, jona hän rauhassa tuli takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'Kun hän nyt tuli Jerusalemista kuningasta vastaan, sanoi kuningas hänelle: \"Miksi sinä et tullut minun kanssani, Mefiboset?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'Hän vastasi: \"Herrani, kuningas, palvelijani petti minut. Sillä sinun palvelijasi sanoi hänelle: \'Satuloi minun aasini, ratsastaakseni sillä ja mennäkseni kuninkaan kanssa\' -sillä palvelijasihan on ontuva-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'mutta hän on panetellut palvelijaasi herralle kuninkaalle. Herrani, kuningas, on kuitenkin niinkuin Jumalan enkeli; tee siis, mitä hyväksi näet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Sillä koko minun isäni suku oli herrani, kuninkaan, edessä kuoleman oma, ja kuitenkin sinä asetit palvelijasi niiden joukkoon, jotka syövät sinun pöydässäsi. Mitäpä minulla on enää muuta oikeutta ja mitä valittamista kuninkaalle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Kuningas sanoi hänelle: \"Mitäs tuosta enää puhut? Minä sanon, että sinä ja Siiba saatte jakaa keskenänne maaomaisuuden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'Niin Mefiboset sanoi kuninkaalle: \"Ottakoon hän sen vaikka kokonaan, kun kerran herrani, kuningas, on palannut rauhassa kotiinsa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Gileadilainen Barsillai oli myös tullut Roogelimista ja meni kuninkaan kanssa Jordanille saattamaan häntä Jordanin yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Barsillai oli hyvin vanha, kahdeksankymmenen vuoden vanha. Hän oli elättänyt kuningasta tämän ollessa Mahanaimissa, sillä hän oli hyvin rikas mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'Kuningas sanoi nyt Barsillaille: \"Tule sinä minun mukanani, niin minä elätän sinut luonani Jerusalemissa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Mutta Barsillai vastasi kuninkaalle: \"Montakopa ikävuotta minulla enää lienee, että menisin kuninkaan kanssa Jerusalemiin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'minä olen nyt kahdeksankymmenen vuoden vanha; osaisinko minä enää erottaa hyvää pahasta, tahi maistuisiko palvelijastasi miltään se, mitä hän syö ja mitä juo? Tahi kuuluisiko minusta enää miltään laulajain ja laulajattarien laulu? Miksi palvelijasi vielä tulisi herralleni, kuninkaalle, kuormaksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Ainoastaan vähän matkaa seuraa palvelijasi kuningasta tuolle puolelle Jordanin. Miksi kuningas antaisi minulle sellaisen korvauksen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Salli palvelijasi palata takaisin, saadakseni kuolla omassa kaupungissani isäni ja äitini haudan ääressä. Mutta katso, tässä on palvelijasi Kimham, menköön hän herrani, kuninkaan, kanssa; ja tee hänelle, mitä hyväksi näet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'Niin kuningas sanoi: \"Kimham tulkoon minun kanssani, ja minä teen hänelle, mitä sinä hyväksi näet. Ja kaiken, mitä sinä minulta toivot, minä sinulle teen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'Sitten kaikki kansa meni Jordanin yli, ja myös kuningas itse meni. Ja kuningas suuteli Barsillaita ja hyvästeli hänet. Sitten tämä palasi takaisin kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Kuningas meni Gilgaliin, ja Kimham meni hänen mukanansa, samoin myös kaikki Juudan kansa. Ja he ja puolet Israelin kansasta veivät kuninkaan yli sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'Ja katso, silloin kaikki muut Israelin miehet tulivat kuninkaan tykö ja sanoivat kuninkaalle: \"Miksi ovat meidän veljemme, Juudan miehet, varkain tuoneet Jordanin yli kuninkaan ja hänen perheensä ynnä kaikki Daavidin miehet hänen kanssaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'Mutta kaikki Juudan miehet vastasivat Israelin miehille: \"Onhan kuningas meille läheisempi; miksi vihastut siitä? Olemmeko me syöneet kuningasta, tahi olemmeko vieneet hänet itsellemme?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, '{19:44} Israelin miehet vastasivat Juudan miehille ja sanoivat: \"Minulla on kymmenen kertaa suurempi osa kuninkaaseen, myös Daavidiin, kuin sinulla. Miksi olet siis ylenkatsonut minua? Ja enkö minä ensin puhunut kuninkaani takaisintuomisesta?\" Mutta Juudan miesten sanat olivat vielä ankarammat kuin Israelin miesten sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Ja siellä oli sattumalta kelvoton mies, nimeltä Seba, Bikrin poika, benjaminilainen. Hän puhalsi pasunaan ja sanoi: \"Meillä ei ole mitään osaa Daavidiin eikä perintöosaa Iisain poikaan. Kukin majallensa, Israel!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Silloin kaikki Israelin miehet luopuivat Daavidista ja seurasivat Sebaa, Bikrin poikaa; mutta Juudan miehet riippuivat kiinni kuninkaassansa ja seurasivat häntä Jordanilta aina Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'Niin Daavid tuli linnaansa Jerusalemiin. Ja kuningas otti ne kymmenen sivuvaimoa, jotka hän oli jättänyt palatsia vartioimaan, ja panetti heidät vartioituun taloon; ja hän elätti heitä, mutta ei mennyt heidän luoksensa. Siellä he olivat eristettyinä kuolinpäiväänsä asti, elävän miehen leskinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Ja kuningas sanoi Amasalle: \"Kutsu koolle Juudan miehet kolmen päivän kuluessa ja ole silloin itse paikallasi täällä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'Niin Amasa meni kutsumaan koolle Juudaa; mutta hän viipyi ohi sen ajan, jonka hän oli määrännyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Silloin sanoi Daavid Abisaille: \"Nyt Seba, Bikrin poika, tekee meille enemmän pahaa kuin Absalom. Ota sinä herrasi palvelijat ja aja häntä takaa, ettei hän saisi haltuunsa varustettuja kaupunkeja ja repisi meiltä silmiä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Niin Jooabin miehet sekä kreetit ja pleetit ja kaikki urhot lähtivät liikkeelle hänen jäljessään; he lähtivät Jerusalemista ajamaan takaa Sebaa, Bikrin poikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Mutta kun he olivat suuren kiven luona, joka on Gibeonissa, tuli Amasa heitä vastaan. Ja Jooab oli puettu takkiinsa, ja sen päällä oli miekanvyö, kiinnitettynä vyötäisille; miekka oli tupessaan, mutta kun hän lähti liikkeelle, niin se putosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'Ja Jooab sanoi Amasalle: \"Voitko hyvin, veljeni?\" Ja Jooab tarttui oikealla kädellään Amasaa partaan, muka suudellakseen häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Ja kun Amasa ei varonut miekkaa, joka Jooabilla oli kädessään, pisti tämä häntä sillä vatsaan, niin että hänen sisälmyksensä valuivat maahan; toista pistoa ei tarvittu: hän kuoli. Sitten Jooab ja hänen veljensä Abisai ajoivat takaa Sebaa, Bikrin poikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Mutta eräs Jooabin palvelijoista jäi seisomaan Amasan ääreen ja huusi: \"Jokainen, joka on Jooabille myötämielinen ja joka on Daavidin puolella, seuratkoon Jooabia!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Ja Amasa virui verissään keskellä tietä; mutta kun se mies näki, että kaikki väki pysähtyi siihen, vei hän Amasan tieltä syrjään pellolle ja heitti vaatteen hänen päällensä, nähdessään, että kaikki ohikulkijat pysähtyivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Ja kun hänet oli toimitettu pois tieltä, kulkivat kaikki ohi ja seurasivat Jooabia ajaakseen takaa Sebaa, Bikrin poikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Tämä kulki kaikkien Israelin sukukuntien kautta Aabeliin ja Beet-Maakaan, ja kaikki beeriläiset kokoontuivat ja seurasivat häntä sinne saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Mutta he tulivat ja piirittivät häntä Aabel-Beet-Maakassa ja loivat kaupunkia vastaan vallin, joka ulottui ulkomuuriin. Ja kaikki Jooabin väki teki hävitystyötä kukistaakseen muurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Silloin huusi viisas vaimo kaupungista: \"Kuulkaa! Kuulkaa! Sanokaa Jooabille, että hän tulee tänne lähelle puhutellakseni häntä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Ja kun tämä tuli häntä lähelle, sanoi vaimo: \"Oletko Jooab?\" Hän vastasi: \"Olen\". Vaimo sanoi hänelle: \"Kuule palvelijattaresi sanoja\". Hän vastasi: \"Minä kuulen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Silloin vaimo sanoi: \"Muinoin oli tapana sanoa: \'On kysyttävä neuvoa Aabelista\', ja niin tuli valmista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Minä olen rauhallisimpia ja uskollisimpia Israelissa, ja sinä koetat ottaa hengen kaupungilta, joka on äiti Israelissa. Miksi sinä tahdot hävittää Herran perintöosan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'Jooab vastasi ja sanoi: \"Pois se, pois se! En minä tahdo hävittää enkä tuhota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Niin ei ole asia, vaan eräs mies Efraimin vuoristosta, nimeltä Seba, Bikrin poika, on nostanut kätensä kuningas Daavidia vastaan; luovuttakaa hänet yksin, niin minä lähden pois kaupungin edustalta.\" Vaimo vastasi Jooabille: \"Katso, hänen päänsä heitetään sinulle muurin yli\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Sitten vaimo viisaudessaan meni kaiken kansan luo; niin he löivät Sebalta, Bikrin pojalta, pään poikki ja heittivät sen Jooabille. Silloin tämä puhalsi pasunaan, ja he hajaantuivat kaupungin edustalta, kukin majallensa. Mutta Jooab palasi kuninkaan luo Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Jooab oli Israelin koko sotajoukon ylipäällikkönä, ja Benaja, Joojadan poika, oli kreettien ja pleettien päällikkönä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adoram oli verotöiden valvojana, ja Joosafat, Ahiludin poika, oli kanslerina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Seja oli kirjurina, ja Saadok ja Ebjatar olivat pappeina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Myöskin jaairilainen Iira oli Daavidilla pappina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'Daavidin aikana oli nälänhätä, jota kesti kolme vuotta peräkkäin; silloin Daavid etsi Herran kasvoja. Herra vastasi: \"Saulin tähden, verivelan alaisen suvun tähden, koska hän surmasi gibeonilaiset\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Niin kuningas kutsui gibeonilaiset ja puhutteli heitä. Mutta gibeonilaiset eivät olleet israelilaisia, vaan amorilaisten jätteitä, ja israelilaiset olivat vannoneet heille valan, mutta Saul oli kiivaillessaan israelilaisten ja Juudan puolesta koettanut hävittää heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'Daavid sanoi gibeonilaisille: \"Mitä minun on tehtävä teidän hyväksenne, ja millä minun on teidät sovitettava, että siunaisitte Herran perintöosaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'Gibeonilaiset vastasivat hänelle: \"Ei ole meidän ja Saulin sekä hänen sukunsa välillä kysymys hopeasta eikä kullasta, eikä meillä ole valtaa surmata ketään Israelissa\". Hän sanoi: \"Mitä sitten vaaditte minua tekemään teidän hyväksenne?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'He vastasivat kuninkaalle: \"Sen miehen, joka tahtoi meidät lopettaa ja joka aikoi hävittää meidät, niin ettei meillä olisi missä olla koko Israelin alueella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'sen miehen jälkeläisistä luovutettakoon meille seitsemän miestä lävistääksemme heidät paaluihin Herralle Saulin, Herran valitun, Gibeassa\". Kuningas sanoi: \"Minä luovutan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Mefibosetin, Saulin pojan Joonatanin pojan, kuningas kuitenkin säästi Herran valan tähden, joka oli heidän välillänsä, Daavidin ja Joonatanin, Saulin pojan, välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Mutta kuningas otti Rispan, Aijan tyttären, kaksi poikaa, Armonin ja Mefibosetin, jotka tämä oli synnyttänyt Saulille, sekä Meerabin, Saulin tyttären, viisi poikaa, jotka tämä oli synnyttänyt Adrielille, meholalaisen Barsillain pojalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'ja luovutti heidät gibeonilaisten käsiin; ja nämä lävistivät heidät paaluihin vuorella Herran edessä, niin että ne seitsemän sortuivat kaikki yhdessä. Näin heidät surmattiin elonleikkuun ensimmäisinä päivinä, ohranleikkuun alussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'Silloin Rispa, Aijan tytär, otti säkin ja levitti sen kalliolle, ja se oli hänen vuoteenaan elonleikkuun alusta siihen asti, kunnes sade taivaasta vuoti heidän päällensä, eikä hän sallinut taivaan lintujen päivällä eikä metsän eläinten yöllä tulla heidän päällensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Kun Daavidille kerrottiin, mitä Rispa, Aijan tytär, Saulin sivuvaimo, oli tehnyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'meni Daavid ja otti Saulin ja hänen poikansa Joonatanin luut Gileadin Jaabeksen miehiltä, jotka olivat varkain ottaneet ne siltä torilta Beet-Seanista, jolle filistealaiset olivat heidät ripustaneet silloin, kun filistealaiset surmasivat Saulin Gilboassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'Ja hän toi sieltä Saulin ja hänen poikansa Joonatanin luut. Myös paaluihin lävistettyjen luut koottiin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'ja haudattiin yhdessä Saulin ja hänen poikansa Joonatanin luiden kanssa Benjaminin maahan Seelaan, Saulin isän, Kiisin, hautaan. Tehtiin kaikki, mitä kuningas oli käskenyt. Niin Jumala leppyi maalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'Taas syttyi sota filistealaisten ja Israelin välillä. Ja Daavid lähti palvelijoineen sotimaan filistealaisia vastaan. Ja Daavid väsyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Niin Jisbi-Benob, Raafan jälkeläisiä, jonka keihäs painoi kolmesataa sekeliä vaskea ja joka oli puettu uusiin tamineihin, aikoi surmata Daavidin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Mutta Abisai, Serujan poika, tuli hänen avukseen ja löi filistealaisen kuoliaaksi. Silloin Daavidin miehet vannottivat hänellä valan sanoen: \"Sinä et saa enää lähteä meidän kanssamme taisteluun, ettet sammuttaisi Israelin lamppua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'Sen jälkeen oli taas taistelu filistealaisten kanssa Goobissa: silloin huusalainen Sibbekai surmasi Safin, joka myös oli Raafan jälkeläisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Taas oli taistelu filistealaisia vastaan Goobissa. Elhanan, Jare-Ooregimin poika, beetlehemiläinen, surmasi gatilaisen Goljatin, jonka peitsen varsi oli niinkuin kangastukki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Taas oli taistelu Gatissa. Siellä oli kookas mies, jolla oli kuusi sormea kummassakin kädessä ja kuusi varvasta kummassakin jalassa, yhteensä kaksikymmentä neljä; hänkin polveutui Raafasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Ja kun hän häpäisi Israelia, surmasi hänet Joonatan, Daavidin veljen Simean poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Nämä neljä polveutuivat gatilaisesta Raafasta; he kaatuivat Daavidin ja hänen palvelijainsa käden kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'Ja Daavid puhui Herralle tämän laulun sanat sinä päivänä, jona Herra oli pelastanut hänet kaikkien hänen vihollistensa ja Saulin vallasta. Hän sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, '\"Herra, minun kallioni, linnani ja pelastajani!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Jumala, minun vuoreni, jonka turviin minä pakenen, minun kilpeni, autuuteni sarvi, varustukseni ja pakopaikkani, sinä pelastajani, joka pelastat minut väkivallasta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, '\'Ylistetty olkoon Herra\' -niin minä huudan, ja vihollisistani minä pelastun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Sillä kuoleman aallot piirittivät minut, turmion virrat peljästyttivät minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Tuonelan paulat kietoivat minut, kuoleman ansat yllättivät minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'Ahdistuksessani minä rukoilin Herraa, Jumalaani minä rukoilin; ja hän kuuli minun ääneni temppelistänsä, minun huutoni kohosi hänen korviinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Silloin maa huojui ja järisi, taivaan perustukset järkkyivät; ne horjuivat, sillä hänen vihansa syttyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Savu suitsusi hänen sieraimistaan, kuluttava tuli hänen suustansa, palavat hiilet hehkuivat hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Hän notkisti taivaan ja astui alas, synkkä pilvi jalkojensa alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'Hän ajoi kerubin kannattamana ja lensi, hän näkyi tuulen siipien päältä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Ja hän pani pimeyden majaksi ympärillensä, synkät vedet, paksut pilvet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Hohteesta, joka kävi hänen edellänsä, hehkuivat palavat hiilet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Herra jylisi taivaasta, Korkein antoi äänensä kaikua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Hän lennätti nuolia ja hajotti heidät, salamoita, ja kauhistutti heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Silloin meren syvyydet tulivat näkyviin, maanpiirin perustukset paljastuivat Herran nuhtelusta, hänen vihansa hengen puuskauksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Hän ojensi kätensä korkeudesta ja tarttui minuun, veti minut ylös suurista vesistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Hän pelasti minut voimallisesta vihollisestani, minun vihamiehistäni, sillä he olivat minua väkevämmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'He hyökkäsivät minun kimppuuni hätäni päivänä, mutta Herra tuli minun tuekseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'Hän toi minut avaraan paikkaan, hän vapautti minut, sillä hän oli mielistynyt minuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Herra tekee minulle minun vanhurskauteni mukaan; minun kätteni puhtauden mukaan hän minulle maksaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Sillä minä olen noudattanut Herran teitä enkä ole luopunut pois Jumalastani, jumalattomuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Kaikki hänen oikeutensa ovat minun silmieni edessä, enkä minä poikkea hänen käskyistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'Minä olen vilpitön häntä kohtaan ja varon itseni pahoista teoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Sentähden Herra palkitsee minulle vanhurskauteni mukaan, sen mukaan kuin olen puhdas hänen silmiensä edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Hurskasta kohtaan sinä olet hurskas, nuhteetonta sankaria kohtaan nuhteeton;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'puhdasta kohtaan sinä olet puhdas, mutta kieroa kohtaan nurja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Ja sinä pelastat nöyrän kansan, mutta sinun silmäsi ovat ylpeitä vastaan, sinä alennat heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Sillä sinä, Herra, olet minun lamppuni; Herra valaisee minun pimeyteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Sinun avullasi minä hyökkään rosvojoukkoa vastaan, Jumalani avulla minä ryntään ylitse muurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Jumalan tie on nuhteeton, Herran sana tulessa koeteltu. Hän on kaikkien kilpi, jotka häneen turvaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Sillä kuka muu on Jumala paitsi Herra, ja kuka muu on pelastuksen kallio paitsi meidän Jumalamme?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'se Jumala, joka on minun vahva turvani ja johdattaa nuhteetonta hänen tiellänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'tekee hänen jalkansa nopeiksi niinkuin peurat ja asettaa minut kukkuloilleni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'joka opettaa minun käteni sotimaan ja käsivarteni vaskijousta jännittämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Sinä annat minulle pelastuksen kilven; ja kun sinä kuulet minun rukoukseni, teet sinä minut suureksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Sinä annat minun askeleilleni avaran tilan, ja minun jalkani eivät horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Minä ajan vihollisiani takaa ja tuhoan heidät enkä palaja, ennenkuin teen heistä lopun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Minä lopetan heidät ja murskaan heidät, niin etteivät enää nouse; he sortuvat minun jalkojeni alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Sinä vyötät minut voimalla sotaan, sinä painat vastustajani minun alleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Sinä ajat minun viholliseni pakoon, vihamieheni minä hukutan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'He katselevat, mutta pelastajaa ei ole, katsovat Herran puoleen, mutta hän ei heille vastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Minä survon heidät maan tomuksi, kadun loaksi minä heidät poljen ja tallaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Sinä pelastat minut kansani riidoista, sinä varjelet minua, niin että tulen pakanain pääksi; kansat, joita minä en tunne, palvelevat minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Muukalaiset minua mielistelevät; jo korvan kuulemalta he tottelevat minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Muukalaiset masentuvat; he tulevat vyöttäytyneinä varustuksistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Herra elää! Kiitetty olkoon minun kallioni, ja ylistetty Jumala, minun pelastukseni kallio,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Jumala, joka hankkii minulle koston ja laskee kansat minun valtani alle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'sinä, joka vapahdat minut vihollisistani ja korotat minut vastustajaini ylitse ja päästät minut väkivaltaisesta miehestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Sentähden minä ylistän sinua, Herra, kansojen keskuudessa ja veisaan sinun nimesi kiitosta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'sinun, joka annat kuninkaallesi suuren avun ja osoitat armoa voidellullesi, Daavidille, ja hänen jälkeläisilleen, iankaikkisesti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Nämä olivat Daavidin viimeiset sanat: Näin puhuu Daavid, Iisain poika, näin puhuu korkealle korotettu mies, Jaakobin Jumalan voideltu, ihana Israelin ylistysvirsissä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, '\"Herran Henki on puhunut minulle, ja hänen sanansa on minun kielelläni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Israelin Jumala on sanonut, Israelin kallio on puhunut minulle: \'Joka hallitsee ihmisiä vanhurskaasti, joka hallitsee Jumalan pelossa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'hän on niinkuin huomenhohde auringon noustessa pilvettömänä aamuna, kun maa kirkkaassa valossa vihannoi sateen jälkeen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Eikö minun sukuni ole näin Jumalan edessä? Sillä hän on tehnyt minun kanssani iankaikkisen liiton, kaikin puolin taatun ja vakaan. Hän antaa versoa minulle kaiken autuuden ja kaiken ilon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Mutta kaikki kelvottomat ovat niinkuin poisviskatut orjantappurat, joihin ei käsin tartuta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Ja jos jonkun on koskettava niihin, varustautuu hän raudalla ja keihäänvarrella; sitten ne tulella poltetaan, siinä missä ovat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Nämä ovat Daavidin sankarien nimet: Jooseb-Bassebet, tahkemonilainen, vaunusoturien päällikkö, hän, joka heilutti keihästään kahdeksansadan kaatuneen yli yhdellä kertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'Hänen jälkeensä Eleasar, Doodin poika, joka oli erään ahohilaisen poika. Hän oli yksi niistä kolmesta urhosta, jotka olivat Daavidin kanssa silloin, kun he häpäisivät filistealaisia, jotka olivat kokoontuneet sinne sotimaan. Israelin miehet vetäytyivät silloin takaisin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'mutta hän jäi paikalleen ja surmasi filistealaisia, kunnes hänen kätensä uupui niin, että se kouristui kiinni miekkaan. Ja Herra antoi suuren voiton sinä päivänä; väki kääntyi vain hänen jälkeensä ryöstämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'Hänen jälkeensä Samma, Aagen poika, hararilainen. Kerran olivat filistealaiset kokoontuneet yhteen joukkoon, ja siellä oli peltopalsta, kokonaan hernettä kasvamassa. Ja väki pakeni filistealaisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'mutta hän asettui keskelle palstaa, sai sen pelastetuksi ja voitti filistealaiset; ja niin Herra antoi suuren voiton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Kerran lähti kolme niistä kolmestakymmenestä päälliköstä liikkeelle, ja he tulivat elonleikkuun aikana Daavidin luo Adullamin luolalle. Ja filistealaisten joukko oli leiriytynyt Refaimin tasangolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'Mutta Daavid oli silloin vuorilinnassa, ja filistealaisten vartiosto oli Beetlehemissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Ja Daavidin rupesi tekemään mieli vettä, ja hän sanoi: \"Jospa joku toisi minulle vettä juodakseni Beetlehemin kaivosta, joka on portin edustalla!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Silloin murtautuivat ne kolme urhoa filistealaisten leirin läpi ja ammensivat vettä Beetlehemin kaivosta portin edustalta, kantoivat ja toivat sen Daavidille. Mutta hän ei tahtonut sitä juoda, vaan vuodatti sen juomauhriksi Herralle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'ja sanoi: \"Pois se! Herra varjelkoon minut sitä tekemästä. Onhan se niiden miesten veri, jotka menivät sinne oman henkensä uhalla.\" Eikä hän tahtonut juoda sitä. Tämän tekivät ne kolme urhoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Abisai, Jooabin veli, Serujan poika, oli niiden kolmen päällikkö; hän heilutti keihästään kolmensadan kaatuneen yli. Ja hän oli kuulu niiden kolmen joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Hän oli arvossa pidetty niiden kolmen joukossa ja oli heidän päämiehensä, mutta ei hän vetänyt vertoja niille kolmelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Benaja, Joojadan poika, joka oli urhoollisen ja suurista teoistaan kuuluisan miehen poika, oli kotoisin Kabseelista. Hän surmasi ne kaksi mooabilaista sankaria, ja hän laskeutui alas ja tappoi lumituiskun aikana leijonan kaivoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Myöskin surmasi hän egyptiläisen miehen, sen uhkean miehen. Egyptiläisellä oli keihäs kädessä, mutta hän meni häntä vastaan ainoastaan sauva kädessä. Ja hän tempasi keihään egyptiläisen kädestä ja tappoi hänet hänen omalla keihäällään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Tällaisia teki Benaja, Joojadan poika. Ja hän oli kuulu niiden kolmen urhon joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Hän oli arvossa pidetty niiden kolmenkymmenen joukossa, mutta ei hän vetänyt vertoja niille kolmelle. Ja Daavid asetti hänet henkivartiostonsa päälliköksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Niiden kolmenkymmenen joukossa oli Asael, Jooabin veli; Elhanan, Doodon poika, Beetlehemistä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'harodilainen Samma; harodilainen Elika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'pleettiläinen Heles; tekoalainen Iira, Ikkeksen poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'anatotilainen Abieser; huusalainen Mebunnai;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'ahohilainen Salmon; netofalainen Maharai;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'netofalainen Heeleb, Baanan poika; Ittai, Riibain poika, benjaminilaisten Gibeasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'piratonilainen Benaja; Hiddai Nahale-Gaasista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'arabalainen Abi-Albon; barhumilainen Asmavet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'saalbonilainen Eljahba; Bene-Jaasen; Joonatan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'hararilainen Samma; ararilainen Ahiam, Sararin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifelet, Ahasbain poika, joka oli erään maakatilaisen poika; giilolainen Eliam, Ahitofelin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'karmelilainen Hesrai; arabilainen Paarai;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Jigal, Naatanin poika, Soobasta; gaadilainen Vaani;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'ammonilainen Selek; beerotilainen Naharai, Jooabin, Serujan pojan, aseenkantaja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'jeteriläinen Iira; jeteriläinen Gaareb;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'heettiläinen Uuria. Kaikkiaan kolmekymmentä seitsemän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Mutta Herran viha syttyi taas Israelia kohtaan, niin että hän yllytti Daavidin heitä vastaan, sanoen: \"Mene ja laske Israel ja Juuda\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'Niin kuningas sanoi Jooabille, sotajoukon päällikölle, joka oli hänen luonaan: \"Kiertele kaikki Israelin sukukunnat Daanista Beersebaan asti, ja pitäkää kansan katselmus, että minä saisin tietää kansan lukumäärän\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Jooab vastasi kuninkaalle: \"Herra, sinun Jumalasi, lisätköön kansan, olkoon se kuinka suuri tahansa, satakertaiseksi, ja saakoon herrani, kuningas, nähdä sen omin silmin. Mutta miksi herrani, kuningas, haluaa sellaista?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Kuitenkin kuninkaan sana velvoitti Jooabia ja sotapäällikköjä; niin Jooab ja sotapäälliköt lähtivät kuninkaan luota pitämään Israelin kansan katselmusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'Ja he menivät Jordanin yli ja leiriytyivät Aroeriin, oikealle puolelle jokilaakson keskikohdalla olevaa kaupunkia, Gaadiin ja Jaeseriin päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Sitten he tulivat Gileadiin ja Tahtim-Hodsin maahan; sitten he tulivat Daan-Jaaniin ja sieltä ympäri Siidoniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Sitten he tulivat Tyyron linnoitukseen ja kaikkiin hivviläisten ja kanaanilaisten kaupunkeihin ja menivät sieltä Juudan Etelämaahan Beersebaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'Ja kun he olivat kierrelleet koko maan, tulivat he yhdeksän kuukauden ja kahdenkymmenen päivän kuluttua takaisin Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'Ja Jooab ilmoitti kuninkaalle kansan lasketun lukumäärän: Israelissa oli kahdeksansataa tuhatta sotakuntoista miekkamiestä, ja Juudassa oli viisisataa tuhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Mutta Daavidin omatunto soimasi häntä, sittenkuin hän oli laskenut kansan, ja Daavid sanoi Herralle: \"Minä olen tehnyt suuren synnin tehdessäni tämän; mutta anna nyt, Herra, anteeksi palvelijasi rikos, sillä minä olen menetellyt ylen tyhmästi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'Ja kun Daavid aamulla nousi, oli profeetta Gaadille, Daavidin näkijälle, tullut tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, '\"Mene ja puhu Daavidille: Näin sanoo Herra: Kolme ehtoa minä asetan sinun eteesi; valitse yksi niistä, niin minä teen sen sinulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Niin Gaad meni Daavidin tykö, ilmoitti ja sanoi hänelle: \"Tuleeko nälkä seitsemäksi vuodeksi sinun maahasi, vai pakenetko sinä kolme kuukautta vihollisiasi, jotka ajavat sinua takaa, vai tuleeko rutto sinun maahasi kolmeksi päiväksi? Mieti nyt ja katso, mitä minä vastaan hänelle, joka minut lähetti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'Daavid vastasi Gaadille: \"Minä olen suuressa hädässä. Me tahdomme langeta Herran käsiin, sillä hänen laupeutensa on suuri; ihmisten käsiin minä en tahdo langeta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Niin Herra antoi ruton tulla Israeliin, aamusta alkaen määrättyyn aikaan asti; ja kansaa kuoli Daanista Beersebaan asti seitsemänkymmentä tuhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'Mutta kun enkeli ojensi kätensä Jerusalemia kohti tuhotaksensa sen, katui Herra sitä pahaa ja sanoi enkelille, joka kansaa tuhosi: \"Jo riittää; laske kätesi alas\". Ja Herran enkeli oli silloin jebusilaisen Araunan puimatantereen luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'Mutta nähdessään enkelin surmaavan kansaa sanoi Daavid Herralle: \"Katso, minä olen tehnyt syntiä, minä olen tehnyt väärin; mutta nämä minun lampaani, mitä he ovat tehneet? Sattukoon sinun kätesi minuun ja minun isäni perheeseen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Ja Gaad tuli Daavidin tykö samana päivänä ja sanoi hänelle: \"Mene ja pystytä Herralle alttari jebusilaisen Araunan puimatantereelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'Niin Daavid meni, Gaadin sanan ja Herran käskyn mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Mutta kun Arauna katsahti ulos ja näki kuninkaan palvelijoineen tulevan luoksensa, meni hän ulos ja kumartui kasvoillensa maahan kuninkaan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'Ja Arauna sanoi: \"Miksi herrani, kuningas, tulee palvelijansa luo?\" Daavid vastasi: \"Ostamaan sinulta puimatantereen, rakentaakseni Herralle alttarin, että vitsaus taukoaisi kansasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Arauna sanoi Daavidille: \"Herrani, kuningas, ottakoon ja uhratkoon, mitä hyväksi näkee. Katso, tässä on härät polttouhriksi ja puimaäkeet sekä härkien valjaat haloiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Tämän kaiken, kuningas, Arauna antaa kuninkaalle.\" Ja Arauna sanoi kuninkaalle: \"Olkoon Herra, sinun Jumalasi, sinulle suosiollinen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Mutta kuningas sanoi Araunalle: \"Ei niin, vaan minä ostan ne sinulta täydestä hinnasta, sillä minä en uhraa Herralleni, Jumalalleni, ilmaiseksi saatuja polttouhreja\". Niin Daavid osti puimatantereen ja härät viidelläkymmenellä hopeasekelillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Ja Daavid rakensi sinne alttarin Herralle ja uhrasi polttouhreja ja yhteysuhreja. Niin Herra leppyi maalle, ja vitsaus taukosi Israelista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'Kun kuningas Daavid oli käynyt vanhaksi ja iäkkääksi, ei hän enää voinut pysyä lämpimänä, vaikka häntä peitettiin peitteillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Silloin hänen palvelijansa sanoivat hänelle: \"Etsittäköön herralleni, kuninkaalle, tyttö, neitsyt, palvelemaan kuningasta ja olemaan hänen hoitajattarenaan. Jos hän makaa sinun sylissäsi, niin herrani, kuningas, pysyy lämpimänä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Ja he etsivät koko Israelin alueelta kaunista tyttöä ja löysivät suunemilaisen Abisagin ja veivät hänet kuninkaan tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Hän oli hyvin kaunis tyttö ja tuli kuninkaan hoitajattareksi ja palveli häntä. Mutta kuningas ei yhtynyt häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Mutta Adonia, Haggitin poika, korotti itsensä ja sanoi: \"Minä tahdon tulla kuninkaaksi\". Ja hän hankki itselleen sotavaunuja ja ratsumiehiä ja viisikymmentä miestä, jotka juoksivat hänen edellään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'Hänen isänsä ei koskaan elämässään ollut pahoittanut hänen mieltään sanomalla: \"Kuinka sinä noin teet?\" Hän oli myöskin hyvin kaunis mies; ja äiti oli synnyttänyt hänet Absalomin jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'Hän neuvotteli Jooabin, Serujan pojan, ja pappi Ebjatarin kanssa; ja he kannattivat Adonian puoluetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Mutta pappi Saadok ja Benaja, Joojadan poika, sekä profeetta Naatan, Siimei, Rei ja Daavidin urhot eivät olleet Adonian puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Ja Adonia teurasti lampaita, raavaita ja juottovasikoita Soohelet-kiven luona, joka on Roogelin lähteen ääressä. Ja hän kutsui kaikki veljensä, kuninkaan pojat, ja kaikki Juudan miehet, kuninkaan palvelijat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'mutta profeetta Naatanin, Benajan, urhot ja veljensä Salomon hän jätti kutsumatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Silloin Naatan sanoi Batseballe, Salomon äidille, näin: \"Etkö ole kuullut, että Adonia, Haggitin poika, on tullut kuninkaaksi, herramme Daavidin siitä mitään tietämättä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Niin tule nyt, minä annan sinulle neuvon, että pelastat oman henkesi ja poikasi Salomon hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Mene kuningas Daavidin tykö ja sano hänelle: Herrani, kuningas, etkö sinä itse ole vannonut palvelijattarellesi ja sanonut: Sinun poikasi Salomo on tuleva kuninkaaksi minun jälkeeni; hän on istuva minun valtaistuimellani? Miksi siis Adonia on tullut kuninkaaksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Ja katso, sinun vielä puhutellessasi kuningasta siellä, tulen minä sinun jälkeesi sisään ja vahvistan sinun sanasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'Niin Batseba meni kuninkaan tykö makuuhuoneeseen. Kuningas oli hyvin vanha; ja suunemilainen Abisag palveli kuningasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Ja Batseba kumarsi ja osoitti kuninkaalle kunnioitusta. Kuningas sanoi: \"Mikä sinun on?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Hän vastasi hänelle: \"Herrani, sinä olet itse vannonut palvelijattarellesi Herran, Jumalasi, kautta: \'Sinun poikasi Salomo on tuleva kuninkaaksi minun jälkeeni; hän on istuva minun valtaistuimellani\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'Mutta katso, nyt on Adonia tullut kuninkaaksi, ja sinä, herrani, kuningas, et tiedä siitä mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Hän on teurastanut paljon härkiä, juottovasikoita ja lampaita ja kutsunut kaikki kuninkaan pojat, pappi Ebjatarin ja sotapäällikkö Jooabin; mutta palvelijasi Salomon hän on jättänyt kutsumatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Sinua kohti, herrani, kuningas, ovat nyt koko Israelin silmät tähdätyt, että ilmoittaisit heille, kuka on istuva herrani, kuninkaan, valtaistuimella hänen jälkeensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Muuten käy niin, että kun herrani, kuningas, on mennyt lepoon isiensä tykö, minua ja minun poikaani Salomoa pidetään rikollisina.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'Ja katso, hänen vielä puhutellessaan kuningasta tuli profeetta Naatan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'Ja kuninkaalle ilmoitettiin: \"Katso, profeetta Naatan on täällä\". Ja tämä tuli kuninkaan eteen ja kumartui kasvoillensa maahan kuninkaan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Ja Naatan sanoi: \"Herrani, kuningas, sinäkö olet sanonut: \'Adonia on tuleva kuninkaaksi minun jälkeeni; hän on istuva minun valtaistuimellani\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Sillä hän on tänä päivänä mennyt ja teurastanut paljon härkiä, juottovasikoita ja lampaita ja kutsunut kaikki kuninkaan pojat, sotapäälliköt ja pappi Ebjatarin; ja katso, he syövät ja juovat hänen edessään, ja he huutavat: \'Eläköön kuningas Adonia!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Mutta minut, sinun palvelijasi, pappi Saadokin, Benajan, Joojadan pojan, ja sinun palvelijasi Salomon hän on jättänyt kutsumatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Onko tämä lähtenyt herrastani, kuninkaasta, sinun antamatta palvelijasi tietää, kuka on istuva herrani, kuninkaan, valtaistuimella hänen jälkeensä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Kuningas Daavid vastasi ja sanoi: \"Kutsukaa minun luokseni Batseba\". Kun hän tuli kuninkaan eteen ja seisoi kuninkaan edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'vannoi kuningas ja sanoi: \"Niin totta kuin Herra elää, joka on pelastanut minut kaikesta hädästä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'niinkuin minä vannoin sinulle Herran, Israelin Jumalan, kautta ja sanoin: \'Sinun poikasi Salomo on tuleva kuninkaaksi minun jälkeeni, hän on istuva minun valtaistuimellani minun sijassani\', niin minä tänä päivänä teen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Silloin Batseba kumartui kasvoillensa maahan ja osoitti kuninkaalle kunnioitusta ja sanoi: \"Herrani, kuningas Daavid, eläköön iankaikkisesti!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Ja kuningas Daavid sanoi: \"Kutsukaa minun luokseni pappi Saadok, profeetta Naatan ja Benaja, Joojadan poika\". Niin he tulivat kuninkaan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'Ja kuningas sanoi heille: \"Ottakaa mukaanne herranne palvelijat ja pankaa poikani Salomo minun oman muulini selkään ja viekää hänet alas Giihonille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'Siellä pappi Saadok ja profeetta Naatan voidelkoot hänet Israelin kuninkaaksi. Ja puhaltakaa pasunaan ja huutakaa: \'Eläköön kuningas Salomo!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Seuratkaa sitten häntä tänne, että hän tulisi ja istuisi minun valtaistuimelleni ja olisi kuninkaana minun sijassani. Sillä hänet minä olen määrännyt Israelin ja Juudan ruhtinaaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'Silloin Benaja, Joojadan poika, vastasi kuninkaalle ja sanoi: \"Amen! Niin sanokoon Herra, minun herrani, kuninkaan, Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Niinkuin Herra on ollut minun herrani, kuninkaan, kanssa, niin olkoon hän Salomon kanssa ja tehköön hänen valtaistuimensa vielä suuremmaksi kuin on herrani, kuningas Daavidin, valtaistuin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Niin pappi Saadok, profeetta Naatan ja Benaja, Joojadan poika, sekä kreetit ja pleetit menivät sinne. He panivat Salomon kuningas Daavidin muulin selkään ja saattoivat hänet Giihonille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Ja pappi Saadok otti öljysarven majasta ja voiteli Salomon. Ja he puhalsivat pasunaan, ja kaikki kansa huusi: \"Eläköön kuningas Salomo!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'Ja kaikki kansa seurasi häntä, ja kansa soitti huiluilla ja ratkesi niin suureen riemuun, että maa oli haljeta heidän huudostansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Mutta Adonia ja kaikki kutsuvieraat, jotka olivat hänen kanssaan, kuulivat sen, juuri kun olivat lopettaneet syöntinsä. Ja kun Jooab kuuli pasunan äänen, sanoi hän: \"Mitä tuo huuto ja pauhu kaupungissa tietää?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Hänen vielä puhuessaan tuli Joonatan, pappi Ebjatarin poika; ja Adonia sanoi: \"Tule tänne, sillä sinä olet kunnon mies ja tuot hyviä sanomia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Joonatan vastasi ja sanoi Adonialle: \"Päinvastoin! Herramme, kuningas Daavid, on tehnyt Salomon kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Kuningas lähetti hänen kanssaan pappi Saadokin, profeetta Naatanin ja Benajan, Joojadan pojan, sekä kreetit ja pleetit, ja he panivat hänet kuninkaan muulin selkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'Ja pappi Saadok ja profeetta Naatan voitelivat hänet Giihonilla kuninkaaksi, ja he tulivat sieltä riemuiten, ja koko kaupunki joutui liikkeelle. Sitä oli se huuto, jonka te kuulitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'Onpa Salomo jo istunut kuninkaan valtaistuimellekin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'ja kuninkaan palvelijat ovat tulleet onnittelemaan meidän herraamme, kuningas Daavidia, ja sanoneet: \'Antakoon sinun Jumalasi Salomon nimen tulla vielä mainehikkaammaksi kuin sinun nimesi ja tehköön hänen valtaistuimensa vielä suuremmaksi kuin on sinun valtaistuimesi\'. Ja kuningas on rukoillut vuoteessansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Ja vielä on kuningas puhunut näin: \'Kiitetty olkoon Herra, Israelin Jumala, joka tänä päivänä on asettanut jälkeläisen istumaan minun valtaistuimellani, niin että minä olen sen omin silmin nähnyt\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Silloin kaikki Adonian kutsuvieraat joutuivat kauhun valtaan ja nousivat ja menivät kukin tiehensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Mutta Adonia pelkäsi Salomoa, nousi, meni ja tarttui alttarin sarviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'Ja Salomolle ilmoitettiin: \"Katso, Adonia on peläten kuningas Salomoa tarttunut alttarin sarviin ja sanonut: \'Kuningas Salomo vannokoon minulle tänä päivänä, ettei hän miekalla surmaa palvelijaansa\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Silloin Salomo sanoi: \"Jos hän osoittautuu kunnon mieheksi, ei hiuskarvakaan hänen päästään ole putoava maahan; mutta jos hänessä huomataan jotakin pahaa, on hänen kuoltava\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Ja kuningas Salomo lähetti tuomaan hänet pois alttarilta; niin hän tuli ja kumarsi kuningas Salomoa. Ja Salomo sanoi hänelle: \"Mene kotiisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Kun lähestyi aika, jolloin Daavidin oli kuoltava, käski hän poikaansa Salomoa sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, '\"Minä menen kaiken maailman tietä; ole luja ja ole mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Ja noudata Herran, Jumalasi, määräyksiä, niin että vaellat hänen teitänsä ja noudatat hänen säädöksiänsä, käskyjänsä, oikeuksiansa ja todistuksiansa, niinkuin on kirjoitettuna Mooseksen laissa, että menestyisit kaikessa, mitä teet, ja kaikkialla, minne käännyt;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'että Herra täyttäisi tämän sanansa, jonka hän minusta puhui: \'Jos sinun poikasi pitävät vaarin teistänsä, niin että vaeltavat minun edessäni uskollisesti, kaikesta sydämestänsä ja kaikesta sielustansa, niin on mies sinun suvustasi aina oleva Israelin valtaistuimella\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Sinä tiedät myöskin, mitä Jooab, Serujan poika, on tehnyt minulle-tiedät, mitä hän teki kahdelle Israelin sotapäällikölle, Abnerille, Neerin pojalle, ja Amasalle, Jeterin pojalle: kuinka hän tappoi heidät, vuodattaen sotaverta rauhan aikana ja tahraten sotaverellä vyönsä, joka hänellä oli vyötäisillään, ja kenkänsä, jotka hänellä oli jalassaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Niin tee nyt viisautesi mukaan äläkä anna hänen harmaiden hapsiensa rauhassa mennä alas tuonelaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Mutta gileadilaisen Barsillain pojille osoita laupeutta, niin että he pääsevät niiden joukkoon, jotka syövät sinun pöydästäsi, sillä hekin tulivat minun avukseni, kun minä pakenin sinun veljeäsi Absalomia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Ja katso, vielä on sinun luonasi Siimei, Geeran poika, benjaminilainen Bahurimista, joka hirveillä kirouksilla kiroili minua, kun minä menin Mahanaimiin. Kun hän tuli minua vastaan alas Jordanille, vannoin minä hänelle Herran kautta ja sanoin: \'Minä en surmaa sinua miekalla\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Mutta älä sinä jätä häntä rankaisematta, sillä sinä olet viisas mies ja tiedät, mitä sinun on hänelle tehtävä, saattaaksesi hänen harmaat hapsensa verisinä alas tuonelaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Sitten Daavid meni lepoon isiensä tykö, ja hänet haudattiin Daavidin kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Ja aika, jonka Daavid hallitsi Israelia, oli neljäkymmentä vuotta: Hebronissa hän hallitsi seitsemän vuotta, ja Jerusalemissa hän hallitsi kolmekymmentä kolme vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'Ja Salomo istui isänsä Daavidin valtaistuimelle, ja hänen kuninkuutensa tuli hyvin vahvaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Mutta Adonia, Haggitin poika, tuli Batseban, Salomon äidin, luo. Tämä sanoi: \"Rauhaako sinun tulosi tietää?\" Hän vastasi: \"Rauhaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Sitten hän sanoi: \"Minulla on asiaa sinulle\". Batseba sanoi: \"Puhu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Silloin hän sanoi: \"Sinä tiedät, että kuninkuus oli minun, ja että koko Israel oli kääntänyt katseensa minuun, että minusta tulisi kuningas. Mutta sitten kuninkuus meni minulta pois ja joutui minun veljelleni, sillä Herralta se hänelle tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Yhtä minä nyt sinulta pyydän; älä sitä minulta kiellä.\" Hän sanoi hänelle: \"Puhu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Hän sanoi: \"Puhu kuningas Salomolle-sillä sinulta hän ei sitä kiellä-että hän antaisi minulle suunemilaisen Abisagin vaimoksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'Batseba vastasi: \"Hyvä. Minä puhun kuninkaalle sinun puolestasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Silloin Batseba meni kuningas Salomon tykö puhumaan hänelle Adonian puolesta. Niin kuningas nousi ja meni häntä vastaan ja kumarsi häntä ja istui valtaistuimelleen. Ja myös kuninkaan äidille asetettiin istuin, ja hän istui hänen oikealle puolellensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Sitten hän sanoi: \"Minulla on sinulle pieni pyyntö, älä sitä minulta kiellä\". Kuningas sanoi hänelle: \"Pyydä, äiti, minä en sinulta kiellä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Silloin hän sanoi: \"Annettakoon suunemilainen Abisag sinun veljellesi Adonialle vaimoksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Mutta kuningas Salomo vastasi ja sanoi äidillensä: \"Miksi pyydät vain suunemilaista Abisagia Adonialle? Pyydä myös kuninkuutta hänelle-hänhän on minun vanhin veljeni-hänelle ja pappi Ebjatarille ja Jooabille, Serujan pojalle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Ja kuningas Salomo vannoi Herran kautta, sanoen: \"Jumala rangaiskoon minua nyt ja vasta, jollei Adonia saa hengellään maksaa sitä, että on puhunut näin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Ja nyt, niin totta kuin Herra elää, joka on minut vahvistanut ja on asettanut minut isäni Daavidin valtaistuimelle ja joka lupauksensa mukaan on perustanut minun sukuni: Adonia on tänä päivänä kuolemalla rangaistava.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'Ja kuningas Salomo lähetti Benajan, Joojadan pojan, lyömään hänet kuoliaaksi; ja hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Ja pappi Ebjatarille kuningas sanoi: \"Mene maatilallesi Anatotiin, sillä sinä olet kuoleman oma. En minä sinua nyt surmaa, koska sinä olet kantanut Herran Jumalan arkkia minun isäni Daavidin edessä ja koska olet kärsinyt kaikkea, mitä isäni on kärsinyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'Niin Salomo karkoitti Ebjatarin olemasta Herran pappina ja täytti sen sanan, minkä Herra oli Siilossa puhunut Eelin suvusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Ja kun sanoma tästä tuli Jooabille-sillä Jooab oli liittynyt Adoniaan, vaikka hän ei ollut liittynyt Absalomiin-pakeni Jooab Herran majaan ja tarttui alttarin sarviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'Mutta kun kuningas Salomolle ilmoitettiin: \"Jooab on paennut Herran majaan ja on alttarin ääressä\", lähetti Salomo Benajan, Joojadan pojan, sanoen: \"Mene ja lyö hänet kuoliaaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'Benaja meni Herran majaan ja sanoi hänelle: \"Näin käskee kuningas: \'Tule ulos\'\". Mutta hän vastasi: \"En, tässä minä kuolen\". Silloin Benaja palasi kertomaan sitä kuninkaalle ja sanoi: \"Näin Jooab puhui, ja näin hän vastasi minulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'Kuningas sanoi hänelle: \"Tee, niinkuin hän on puhunut, lyö hänet kuoliaaksi ja hautaa hänet, että poistaisit minusta ja minun isäni perheestä sen viattoman veren, jonka Jooab on vuodattanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'Ja Herra antakoon hänen verensä tulla hänen oman päänsä päälle, koska hän löi kuoliaaksi kaksi miestä, jotka olivat häntä hurskaammat ja paremmat, ja tappoi heidät miekalla, minun isäni Daavidin siitä mitään tietämättä: Abnerin, Neerin pojan, Israelin sotapäällikön, ja Amasan, Jeterin pojan, Juudan sotapäällikön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Heidän verensä tulkoon Jooabin pään päälle ja hänen jälkeläistensä pään päälle, iankaikkisesti. Mutta Daavidilla ja hänen jälkeläisillään, hänen suvullansa ja hänen valtaistuimellansa olkoon rauha Herralta iankaikkisesti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Niin Benaja, Joojadan poika, meni ja löi hänet kuoliaaksi; ja hänet haudattiin omaan taloonsa erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'Ja kuningas asetti Benajan, Joojadan pojan, hänen sijaansa sotaväen päälliköksi; ja pappi Saadokin kuningas asetti Ebjatarin sijalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Sen jälkeen kuningas lähetti kutsumaan Siimein ja sanoi hänelle: \"Rakenna itsellesi talo Jerusalemiin ja asu siellä, menemättä sieltä sinne tai tänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Sillä jona päivänä sinä lähdet sieltä ja menet Kidronin laakson poikki, sinä päivänä on sinun, tiedä se, kuolemalla kuoltava; sinun veresi on tuleva oman pääsi päälle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Siimei sanoi kuninkaalle: \"Hyvä on; niinkuin herrani, kuningas, on puhunut, niin on sinun palvelijasi tekevä\". Ja Siimei asui Jerusalemissa kauan aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Mutta kolmen vuoden kuluttua tapahtui, että Siimeiltä karkasi kaksi palvelijaa Aakiin, Maakan pojan, Gatin kuninkaan, luo. Ja Siimeille ilmoitettiin: \"Katso, sinun palvelijasi ovat Gatissa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Niin Siimei nousi ja satuloi aasinsa ja lähti Aakiin luo Gatiin etsimään palvelijoitaan; ja Siimei meni ja toi palvelijansa Gatista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'Ja kun Salomolle ilmoitettiin, että Siimei oli mennyt Jerusalemista Gatiin ja palannut takaisin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'lähetti kuningas kutsumaan Siimein ja sanoi hänelle: \"Enkö minä ole vannottanut sinua Herran kautta ja varoittanut sinua sanoen: \'Jona päivänä sinä lähdet ja menet sinne tai tänne, sinä päivänä on sinun, tiedä se, kuolemalla kuoltava\'? Ja sinä sanoit minulle: \'Hyvä on; minä olen kuullut\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Miksi et ole pitänyt Herran valaa etkä sitä käskyä, jonka minä sinulle annoin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Ja kuningas sanoi vielä Siimeille: \"Sinä tiedät, tunnossasi tiedät, kaiken pahan, minkä olet tehnyt minun isälleni Daavidille; Herra kääntää tekemäsi pahan omaan päähäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Mutta kuningas Salomo on oleva siunattu, ja Daavidin valtaistuin on oleva iäti vahva Herran edessä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'Ja kuningas käski Benajaa, Joojadan poikaa; niin tämä meni ja löi hänet kuoliaaksi, ja hän kuoli. Niin kuninkuus vahvistui Salomon käsissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'Ja Salomo tuli faraon, Egyptin kuninkaan, vävyksi: hän otti faraon tyttären vaimokseen. Ja hän vei hänet Daavidin kaupunkiin, kunnes oli saanut rakennetuksi oman linnansa, Herran temppelin ja Jerusalemin ympärysmuurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Mutta kansa uhrasi uhrikukkuloilla, koska niihin aikoihin ei vielä oltu rakennettu temppeliä Herran nimelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'Ja Salomo rakasti Herraa ja vaelsi isänsä Daavidin käskyjen mukaan; kuitenkin hän uhrasi ja suitsutti uhrikukkuloilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Niin kuningas meni Gibeoniin, uhraamaan siellä, sillä se oli suurin uhrikukkula. Tuhat polttouhria Salomo uhrasi sillä alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'Gibeonissa Herra ilmestyi Salomolle yöllä unessa, ja Jumala sanoi: \"Ano, mitä tahdot, että minä sinulle antaisin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Salomo vastasi: \"Sinä olet tehnyt suuren laupeuden palvelijallesi, minun isälleni Daavidille, koska hän vaelsi sinun edessäsi totuudessa ja vanhurskaudessa sekä vilpittömällä sydämellä sinua kohtaan. Ja sinä olet säilyttänyt hänelle tämän suuren laupeuden ja antanut hänelle pojan, joka istuu hänen valtaistuimellansa, niinkuin on laita tänä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'Ja nyt, Herra, minun Jumalani, sinä olet tehnyt palvelijasi kuninkaaksi minun isäni Daavidin sijaan; mutta minä olen kuin pieni poikanen: en osaa lähteä enkä tulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'Ja palvelijasi on keskellä sinun kansaasi, jonka olet valinnut, niin monilukuista kansaa, että sitä ei voi laskea eikä lukea sen paljouden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Anna sentähden palvelijallesi kuuliainen sydän tuomitakseni sinun kansaasi ja erottaakseni hyvän pahasta; sillä kuka voi muuten tätä sinun suurta kansaasi tuomita?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'Herralle oli otollista, että Salomo tätä anoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Ja Jumala sanoi hänelle: \"Koska sinä anoit tätä etkä anonut itsellesi pitkää ikää, et rikkautta etkä vihamiestesi henkeä, vaan anoit itsellesi ymmärrystä kuullaksesi, mikä oikein on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'niin katso, minä teen, niinkuin sanot: katso, minä annan sinulle viisaan ja ymmärtäväisen sydämen, niin ettei sinun vertaistasi ole ollut ennen sinua eikä tule sinun jälkeesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Ja lisäksi minä annan sinulle, mitä et anonutkaan: sekä rikkautta että kunniaa, niin ettei koko elinaikanasi ole kuningasten joukossa oleva sinun vertaistasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'Ja jos sinä vaellat minun teitäni, noudattaen minun säädöksiäni ja käskyjäni, niinkuin sinun isäsi Daavid vaelsi, niin minä suon sinulle pitkän iän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'Siihen Salomo heräsi; ja katso, se oli unta. Ja kun hän tuli Jerusalemiin, astui hän Herran liitonarkin eteen, uhrasi polttouhreja ja toimitti yhteysuhrin ja laittoi pidot kaikille palvelijoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Siihen aikaan tuli kaksi porttoa kuninkaan luo, ja he astuivat hänen eteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'Ja toinen nainen sanoi: \"Oi herrani, minä ja tämä nainen asumme samassa huoneessa. Ja minä synnytin hänen luonansa siinä huoneessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'Ja kolmantena päivänä sen jälkeen, kun minä olin synnyttänyt, synnytti myös tämä nainen. Me olimme yhdessä, eikä ketään vierasta ollut meidän kanssamme huoneessa; ainoastaan me kahden olimme huoneessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'Mutta tämän naisen poika kuoli yöllä, sillä hän oli maannut sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'Niin hän nousi keskellä yötä ja otti minun poikani vierestäni palvelijattaresi nukkuessa ja pani sen povellensa, mutta oman kuolleen poikansa hän pani minun povelleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'Kun minä aamulla nousin imettämään poikaani, niin katso, se oli kuollut. Mutta kun minä tarkastin sitä aamulla, niin katso, se ei ollutkaan minun poikani, jonka minä olin synnyttänyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'Niin toinen nainen sanoi: \"Ei ole niin; vaan tuo elossa oleva on minun poikani, ja tämä kuollut on sinun poikasi\". Mutta edellinen vastasi: \"Ei ole niin; tuo kuollut on sinun poikasi, ja tämä elossa oleva on minun poikani\". Näin he riitelivät kuninkaan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Niin kuningas sanoi: \"Toinen sanoo: \'Elossa oleva on minun poikani, ja kuollut on sinun poikasi\'. Ja toinen sanoo: \'Ei ole niin; vaan kuollut on sinun poikasi, ja elossa oleva on minun poikani\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Sitten kuningas sanoi: \"Antakaa minulle miekka\". Ja kuninkaan eteen tuotiin miekka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Ja kuningas sanoi: \"Viiltäkää elossa oleva lapsi kahtia, ja antakaa toinen puoli toiselle ja toinen puoli toiselle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Mutta silloin sanoi kuninkaalle se nainen, jonka oma elossa oleva poika oli, sillä hänen sydämensä tuli liikutetuksi hänen poikansa tähden-hän sanoi: \"Oi herrani, antakaa tuolle elossa oleva lapsi; älkää surmatko sitä\". Mutta toinen sanoi: \"Ei minulle eikä sinulle; viiltäkää!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Niin kuningas vastasi ja sanoi: \"Antakaa tälle elossa oleva lapsi; älkää surmatko sitä. Hän on sen äiti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'Ja koko Israel kuuli tästä tuomiosta, jonka kuningas oli antanut, ja he pelkäsivät kuningasta; sillä he näkivät, että hänessä oli Jumalan viisaus oikeuden jakamiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'Kuningas Salomo oli koko Israelin kuningas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'Ja nämä olivat hänen ylimmät virkamiehensä: Asarja, Saadokin poika, oli ylipappina;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoref ja Ahia, Siisan pojat, olivat kirjureina; Joosafat, Ahiludin poika, oli kanslerina;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'Benaja, Joojadan poika, oli sotaväen ylipäällikkönä; Saadok ja Ebjatar olivat pappeina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Asarja, Naatanin poika, oli ylimaaherrana; Saabud, Naatanin poika, pappi, oli kuninkaan ystävänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Ahisar oli linnanpäällikkönä; Adoniram, Abdan poika, oli verotöiden valvojana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Ja Salomolla oli kaksitoista maaherraa, yli koko Israelin, joiden oli hankittava kuninkaan ja hänen hovinsa elintarpeet; yhtenä kuukautena vuodessa oli kunkin hankittava elintarpeet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'Nämä olivat heidän nimensä: Huurin poika Efraimin vuoristossa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Dekerin poika Maakaassa, Saalbimissa, Beet-Semeksessä, Eelonissa ja Beet-Haananissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Hesedin poika Arubbotissa; hänellä oli Sooko ja koko Heeferin maa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Abinadabin poika koko Doorin kukkula-alueella; hänellä oli vaimona Taafat, Salomon tytär;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, Ahiludin poika, Taanakissa ja Megiddossa ja koko Beet-Seanissa, joka on Saaretanin sivulla Jisreelin alapuolella, Beet-Seanista aina Aabel-Meholaan, tuolle puolelle Jokmeamin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Geberin poika Gileadin Raamotissa; hänellä oli Jaairin, Manassen pojan, leirikylät, jotka ovat Gileadissa; hänellä oli siis Argobin seutu, joka on Baasanissa, kuusikymmentä suurta, muureilla ja vaskisalvoilla varustettua kaupunkia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinadab, Iddon poika, Mahanaimissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimaas Naftalissa; hänkin oli ottanut vaimokseen Salomon tyttären, Baasematin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, Huusain poika, Asserissa ja Bealotissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Joosafat, Paaruahin poika, Isaskarissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Siimei, Eelan poika, Benjaminissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber, Uurin poika, Gileadin maassa, Siihonin, amorilaisten kuninkaan, ja Oogin, Baasanin kuninkaan, maassa; sillä siinä maassa oli yksi maaherra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Juudaa ja Israelia oli paljon, niin paljon kuin hiekkaa meren rannalla; he söivät ja joivat ja olivat iloisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'Ja Salomo hallitsi kaikkia valtakuntia Eufrat-virrasta aina filistealaisten maahan ja Egyptin rajaan asti. He toivat lahjoja ja palvelivat Salomoa, niin kauan kuin hän eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'Ja Salomon jokapäiväinen muona oli: kolmekymmentä koor-mittaa lestyjä jauhoja ja kuusikymmentä koor-mittaa muita jauhoja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'kymmenen syöttöraavasta, kaksikymmentä laitumella käyvää raavasta ja sata lammasta; näitten lisäksi peuroja, gaselleja, metsäkauriita ja syötettyjä hanhia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Sillä hän vallitsi kaikkea Eufrat-virran senpuoleista maata, Tifsahista aina Gassaan saakka, kaikkia Eufrat-virran senpuoleisia kuninkaita; ja hänellä oli rauha joka puolelta yltympäri,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'niin että Juuda ja Israel asuivat turvallisesti, itsekukin viinipuunsa ja viikunapuunsa alla, Daanista Beersebaan asti, niin kauan kuin Salomo eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Ja Salomolla oli neljäkymmentä tuhatta hevosvaljakkoa vaunujaan varten ja kaksitoista tuhatta ratsuhevosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'Ja maaherrat hankkivat, kukin kuukautenaan, elintarpeet kuningas Salomolle ja kaikille, joilla oli pääsy kuningas Salomon pöytään, antamatta minkään puuttua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Myöskin ohrat ja oljet hevosille ja juoksijoille he toivat, kukin vuorollaan, siihen paikkaan, missä hän oleskeli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Ja Jumala antoi Salomolle viisautta ja ymmärrystä ylen runsaasti ja älyä niin laajalti, kuin on hiekkaa meren rannalla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'niin että Salomon viisaus oli suurempi kuin kaikkien Idän miesten ja kaikkien egyptiläisten viisaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Hän oli viisaampi kaikkia ihmisiä, viisaampi kuin esrahilainen Eetan ja Heeman, Kalkol ja Darda, Maaholin pojat; ja hänen nimensä tuli kuuluksi kaikkien ympärillä olevien kansojen keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Ja Salomo sepitti kolmetuhatta sananlaskua, ja hänen laulujansa oli tuhatviisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Hän puhui puista, Libanonin setripuusta alkaen isoppiin asti, joka kasvaa seinän vieressä. Hän puhui myös karjaeläimistä, linnuista, matelijoista ja kaloista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Ja Salomon viisautta tultiin kuulemaan kaikista kansoista, kaikkien maan kuninkaiden luota, jotka olivat kuulleet hänen viisaudestansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'Hiiram, Tyyron kuningas, lähetti palvelijoitansa Salomon luo, kuultuaan, että hänet oli voideltu kuninkaaksi isänsä sijaan; sillä Hiiram oli aina ollut Daavidin likeinen ystävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Ja Salomo lähetti Hiiramille tämän sanan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, '\"Sinä tiedät, ettei minun isäni Daavid voinut rakentaa temppeliä Herran, Jumalansa, nimelle niiden sotien tähden, joilla häntä joka puolelta ahdistettiin, kunnes Herra oli laskenut viholliset hänen jalkojensa alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Mutta nyt Herra, minun Jumalani, on suonut minun päästä rauhaan joka taholla; ei ole vastustajaa eikä vaaran uhkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Sentähden minä aion rakentaa temppelin Herran, Jumalani, nimelle, niinkuin Herra puhui minun isälleni Daavidille, sanoen: \'Sinun poikasi, jonka minä asetan valtaistuimellesi sinun sijaasi, on rakentava minun nimelleni temppelin\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Niin käske nyt hakata minulle setripuita Libanonilta. Ja minun palvelijani olkoot sinun palvelijaisi kanssa. Ja minä annan sinulle palvelijaisi palkan, aivan niinkuin sinä määräät. Sillä sinä tiedät, ettei meillä ole ketään, joka osaisi niin hakata puita kuin siidonilaiset.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'Kun Hiiram kuuli Salomon sanat, tuli hän hyvin iloiseksi ja sanoi: \"Kiitetty olkoon tänä päivänä Herra, joka on antanut Daavidille viisaan pojan hallitsemaan tuota monilukuista kansaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'Ja Hiiram lähetti Salomolle tämän sanan: \"Minä olen kuullut sanan, jonka sinä minulle lähetit. Minä olen täyttävä kaikessa sinun toivomuksesi, mitä tulee setripuihin ja kypressipuihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Minun palvelijani vetäkööt ne Libanonilta alas mereen, ja minä panetan ne meressä lauttoihin kuljetettaviksi paikkaan, minkä sinä minulle määräät, ja hajotan ne siellä; sinä saat noutaa ne sieltä. Mutta täytä sinä minun toivomukseni ja anna minun hovilleni muonaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Niin Hiiram antoi Salomolle setripuita ja kypressipuita niin paljon, kuin tämä toivoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Mutta Salomo antoi Hiiramille kaksikymmentä tuhatta koor-mittaa nisuja, ravinnoksi hänen hovillensa, ja kaksikymmentä koor-mittaa survomalla saatua öljyä. Tämän Salomo antoi Hiiramille joka vuosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'Ja Herra oli antanut Salomolle viisautta, niinkuin hän oli hänelle luvannut. Ja rauha vallitsi Hiiramin ja Salomon välillä, ja he tekivät liiton keskenänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Ja kuningas Salomo otti verotyöläisiä koko Israelista, ja verotyöläisiä oli kolmekymmentä tuhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Nämä hän lähetti Libanonille vuorotellen, kymmenentuhatta kunakin kuukautena, niin että he olivat yhden kuukauden Libanonilla ja kaksi kuukautta kotonansa; ja Adoniram oli verotöiden valvojana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Ja Salomolla oli seitsemänkymmentä tuhatta taakankantajaa ja kahdeksankymmentä tuhatta kivenhakkaajaa vuoristossa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'sen lisäksi Salomon maaherrojen virkamiehiä, jotka valvoivat töitä, kolmetuhatta kolmesataa miestä, vallitsemassa väkeä, joka teki työtä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Ja kuningas käski louhia suuria kiviä, kallisarvoisia kiviä, laskeakseen temppelin perustuksen hakatuista kivistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Niin Salomon ja Hiiramin rakentajat ja gebalilaiset hakkasivat niitä ja valmistivat puut ja kivet temppelin rakentamiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'Neljäntenäsadantena kahdeksantenakymmenentenä vuotena siitä, kun israelilaiset olivat lähteneet Egyptin maasta, neljäntenä vuotena siitä, kun Salomo oli tullut Israelin kuninkaaksi, alkoi hän siiv-kuussa, joka on toinen kuukausi, rakentaa temppeliä Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'Temppeli, jonka kuningas Salomo Herralle rakensi, oli kuuttakymmentä kyynärää pitkä, kahtakymmentä kyynärää leveä ja kolmeakymmentä kyynärää korkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Temppelisalin eteinen, joka oli temppelin itäpäässä, oli kahtakymmentä kyynärää pitkä, ja sen leveys, temppelin itäiseen suuntaan, oli kymmenen kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'Ja hän teki temppeliin sisäänpäin avartuvat ikkuna-aukot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'Ja hän rakensi temppelin seinään kiinni kylkirakennuksen, ympäri temppelin seinien, sekä temppelisalin että kaikkeinpyhimmän ympäri, ja teki siihen sivukammioita yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Kylkirakennuksen alin kerros oli viittä kyynärää leveä, keskimmäinen kuutta kyynärää leveä ja kolmas seitsemää kyynärää leveä; sillä hän teki temppelin ulkomuurin ympärinsä penkerellisen, ettei vuoliaisia tarvinnut upottaa temppelin seiniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'Ja kun temppeli rakennettiin, tehtiin se kivistä, jotka tulivat valmiina louhimosta, niin ettei kuulunut vasaran, ei minkään rauta-aseen kalketta temppeliä rakennettaessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Alimman kerroksen ovi oli temppelin eteläsivussa; portaita myöten noustiin keskimmäiseen kerrokseen ja keskimmäisestä kolmanteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'Rakennettuaan temppelin valmiiksi hän laudoitti sen sisältä setripuisilla parruilla ja laudoilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Ja hän rakensi kauttaaltaan kiinni temppeliin kylkirakennuksen, jonka kerrokset olivat viiden kyynärän korkuiset ja joka oli kiinnitetty temppeliin setripalkeilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'Ja Salomolle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, '\"Tälle temppelille, jota sinä rakennat, on käyvä näin: jos sinä vaellat minun säädöksieni mukaan ja noudatat minun oikeuksiani, otat vaarin kaikista minun käskyistäni ja vaellat niiden mukaan, niin minä täytän sinulle sanani, jonka olen puhunut sinun isällesi Daavidille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'minä asun israelilaisten keskellä enkä hylkää kansaani Israelia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'Niin Salomo rakensi temppelin valmiiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'Hän laudoitti temppelin seinät sisäpuolelta setrilaudoilla; temppelin lattiasta kattopalkkeihin asti hän päällysti sen puulla sisäpuolelta. Temppelin lattian hän päällysti kypressilaudoilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Ja temppelin peräosan, kaksikymmentä kyynärää, hän laudoitti erilleen setrilaudoilla lattiasta kattopalkkeihin asti; niin hän rakensi siihen sisälle kuorin, kaikkeinpyhimmän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Ja temppeli, se on temppelisali kaikkeinpyhimmän edessä, oli neljääkymmentä kyynärää pitkä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'Ja temppeli oli sisäpuolelta setripuuta, koristettu metsäkurpitsi-ja kukkakiehkura-leikkauksilla; kaikki oli setripuuta, kiveä ei näkynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'Temppelin sisään hän laittoi kaikkeinpyhimmän, pannakseen sinne Herran liitonarkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Kaikkeinpyhin oli kahtakymmentä kyynärää pitkä, kahtakymmentä kyynärää leveä ja kahtakymmentä kyynärää korkea; ja hän päällysti sen sisältä puhtaalla kullalla, ja hän teki alttarin setripuusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'Ja Salomo päällysti temppelin sisäpuolelta puhtaalla kullalla. Ja hän sulki kultavitjoilla kaikkeinpyhimmän, jonka oli päällystänyt kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Koko temppelin hän päällysti sisältä kullalla, koko temppelin yltyleensä. Myöskin koko sen alttarin, joka oli kaikkeinpyhimmän edessä, hän päällysti kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Ja hän teki kaikkeinpyhimpään kaksi kerubia öljypuusta, kymmenen kyynärän korkuista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'ja kerubin toinen siipi oli viisikyynäräinen, ja kerubin toinen siipi oli myöskin viisikyynäräinen, niin että oli kymmenen kyynärää toisen siiven kärjestä toisen kärkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Toinen kerubi oli myöskin kymmenkyynäräinen. Molemmat kerubit olivat yhtä suuret ja yhdenmuotoiset:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'toinen kerubi oli kymmentä kyynärää korkea ja samoin myöskin toinen kerubi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'Ja hän pani kerubit temppelin sisimpään osaan, ja kerubit levittivät siipensä niin, että toisen siipi kosketti toista seinää ja toisen kerubin siipi kosketti toista seinää; ja temppelin keskikohdalla koskettivat niiden toiset siivet toisiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'Ja hän päällysti kerubit kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Ja kaikkiin temppelin seiniin yltympäri hän leikkautti veistoksia, kerubeja, palmuja ja kukkakiehkuroita sekä perä-että etuosaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'Ja temppelin lattian hän päällysti kullalla, sekä perä-että etuosan lattian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Ja kaikkeinpyhimmän oviaukkoon hän teki ovet öljypuusta; kamana ja pielet muodostivat viisikulmion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'Ja molempiin öljypuusta tehtyihin oviin hän leikkautti kerubeja, palmuja ja kukkakiehkuroita, ja päällysti ne kullalla; hän levitti kultaa kerubien ja palmujen päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Niin hän teki myös temppelisalin oviaukkoon öljypuusta pielet, nelikulmion muotoiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'ja kypressipuusta kaksi ovea; toisen oven molemmat laudat olivat kääntyviä, ja toisen oven molemmat laudat olivat kääntyviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'Ja hän leikkautti niihin kerubeja, palmuja ja kukkakiehkuroita ja päällysti ne kullalla, joka levitettiin veistosten päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Sitten hän rakensi sisemmän esipihan muurin, jossa oli aina rinnakkain kolme kivikertaa hakattuja kiviä ja yksi hirsikerta veistettyjä setrihirsiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Neljäntenä vuotena, siiv-kuussa, laskettiin Herran temppelin perustus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'Ja yhdentenätoista vuotena, buul-kuussa, joka on kahdeksas kuukausi, temppeli oli kokonaan ja kaikkineen valmis. Hän rakensi sitä seitsemän vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Mutta omaa linnaansa Salomo rakensi kolmetoista vuotta ja sai niin koko linnansa valmiiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Hän rakensi Libanoninmetsä-talon, sataa kyynärää pitkän, viittäkymmentä kyynärää leveän ja kolmeakymmentä kyynärää korkean, kolmen setripylväsrivin varaan, ja pylväiden päällä oli veistetyt setriansaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'Ja siinä oli setripuukatto sivukammioiden päällä, jotka olivat pylväiden varassa; pylväitä oli yhteensä neljäkymmentä viisi, viisitoista kussakin rivissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Ja siinä oli ikkunoita kolmessa rivissä, ja valoaukot olivat vastakkain, aina kolme ja kolme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'Kaikki oviaukot ja valoaukot olivat nelikulmaiset; ja oviaukot olivat vastakkain, aina kolme ja kolme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Vielä hän teki pylvässalin, viittäkymmentä kyynärää pitkän ja kolmeakymmentä kyynärää leveän, ja sen eteen eteisen pylväineen sekä pylväiden eteen porraskatoksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Sitten hän teki valtaistuinsalin, jossa hän jakoi oikeutta, oikeussalin; se oli laudoitettu sisältä setripuulla lattiasta kattoon asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Ja hänen linnansa, jossa hän itse asui, oli toisella esipihalla, salin takana, ja oli rakennettu samalla tavalla. Salomo teki myöskin faraon tyttärelle, jonka hän oli nainut, palatsin, samanlaisen kuin sali.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'Kaikki nämä olivat rakennetut kallisarvoisista, mitan mukaan hakatuista ja sisältä ja ulkoa sahalla sahatuista kivistä, perustuksesta räystäisiin asti; samoin ulkopuolella suureen esipihaan saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Ja perustus oli laskettu kallisarvoisista kivistä, suurista kivistä, kymmenkyynäräisistä ja kahdeksankyynäräisistä kivistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'Ja sen päällä oli kallisarvoisia, mitan mukaan hakattuja kiviä sekä setripuuta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Ja suuren esipihan muurissa oli yltympäri, aina rinnakkain, kolme kivikertaa hakattuja kiviä ja yksi hirsikerta veistettyjä setrihirsiä. Samoin oli Herran temppelin sisemmän esipihan muuri ja myöskin palatsin eteisen esipihan muuri rakennettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Ja kuningas Salomo lähetti noutamaan Hiiramin Tyyrosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'Hän oli leskivaimon poika Naftalin sukukunnasta, ja hänen isänsä oli ollut tyyrolainen, vaskiseppä. Hän oli täynnä taidollisuutta, ymmärrystä ja tietoa, niin että hän kykeni valmistamaan kaikkinaisia vaskitöitä. Ja hän tuli kuningas Salomon luo ja valmisti kaikki hänen työnsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Hän teki vaskesta kaksi pylvästä. Toinen pylväs oli kahdeksantoista kyynärän korkuinen, ja kahdentoista kyynärän pituinen nauha ulottui toisen pylvään ympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Hän teki myös kaksi pylväänpäätä, vaskesta valettua, pylväiden päähän pantavaksi. Kummankin pylväänpään korkeus oli viisi kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Verkon kaltaisia ristikkokoristeita, vitjan kaltaisia riippukoristeita, oli pylväänpäissä, jotka olivat pylväiden päässä, seitsemän kummassakin pylväänpäässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'Ja hän teki granaattiomenia kahteen riviin toisen ristikkokoristeen päälle yltympäri, peittämään pylväänpäät, jotka olivat pylväiden päässä; ja samoin hän teki niitä toiseen pylväänpäähän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'Ja pylväänpäät, jotka olivat pylväiden päässä eteisessä, olivat liljan muotoiset, nelikyynäräiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'Pylväänpäissä, ylhäällä kahden pylvään päässä, oli kupevat alaosat, joihin ristikkokoriste ei ulottunut. Ja granaattiomenia oli kaksisataa, rivittäin yltympäri toisen pylväänpään päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'Ja hän pystytti pylväät temppelin eteisen eteen. Pylväälle, jonka hän pystytti oikealle puolelle, hän antoi nimen Jaakin, ja pylväälle, jonka hän pystytti vasemmalle puolelle, hän antoi nimen Booas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'Ylinnä pylväiden päällä oli liljan muotoinen laite. Ja niin päättyi pylväiden valmistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Hän teki myös meren, valetun, kymmentä kyynärää leveän reunasta reunaan, ympärinsä pyöreän ja viittä kyynärää korkean; ja kolmenkymmenen kyynärän pituinen mittanuora ulottui sen ympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Sen reunan alla oli metsäkurpitsikoristeita, jotka kulkivat sen ympäri. Ne ympäröivät merta yltympäri, kymmenen jokaisella kyynärällä. Metsäkurpitsikoristeet olivat kahdessa rivissä, valettuina meren kanssa yhteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Ja se seisoi kahdentoista raavaan varassa, joista kolme oli käännettynä pohjoiseen, kolme länteen, kolme etelään ja kolme itään päin; meri oli niiden yläpuolella, niiden varassa, ja kaikkien niiden takapuolet olivat sisäänpäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'Se oli kämmenen paksuinen, ja sen reuna oli maljan reunan kaltainen, puhjenneen liljan muotoinen; se veti kaksituhatta bat-mittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Hän teki myös kymmenen telinettä vaskesta. Kukin teline oli neljää kyynärää pitkä, neljää kyynärää leveä ja kolmea kyynärää korkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'Ja telineet olivat rakenteeltaan tällaiset: niissä oli kehäpienat, ja myös poikkitankojen välissä oli kehäpienat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'Kehäpienain päällä, jotka olivat poikkitankojen välissä, oli leijonia, raavaita ja kerubeja, ja samoin poikkitankojen päällä, sekä ylhäällä että alhaalla. Leijonissa ja raavaissa oli takomalla tehtyjä punonnaiskoristeita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'Kussakin telineessä oli neljä vaskipyörää ja vaskiakselit; ja niiden neljässä jalkapylväässä oli olkapää. Olkapäät olivat valetut altaan alle; kunkin ulkopuolella oli punonnaiskoristeita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Telineen aukko oli olkapäiden sisäpuolella, ja sen reuna oli kyynärän korkuinen; aukko oli pyöreä, jalustan tapaan tehty, puolitoistakyynäräinen. Myöskin aukon reunassa oli leikkauksia. Kehäpienat olivat nelikulmaiset eivätkä pyöreät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'Ja ne neljä pyörää olivat kehäpienain alla, ja pyöräin pitimet olivat telineessä kiinni. Kukin pyörä oli puoltatoista kyynärää korkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'Pyörät olivat tehdyt niinkuin vaununpyörät; ja niiden pitimet, kehät, puolat ja navat olivat kaikki valetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Neljä olkapäätä oli kussakin telineessä, sen neljässä kulmassa; olkapäät olivat yhtä telineen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'Ylinnä telineen päällä oli puolen kyynärän korkuinen laite, ympärinsä pyöreä; ja telineen pitimet ja kehäpienat olivat yhtä sen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'Ja sen kehäpienojen pintoihin hän kaiversi kerubeja, leijonia ja palmuja, niin paljon kuin kussakin oli tilaa, sekä punonnaiskoristeita yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Näin hän teki ne kymmenen telinettä; ne olivat kaikki valetut samalla tavalla, yhtä suuret ja yhdenmuotoiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Hän teki myös kymmenen vaskiallasta; kukin allas veti neljäkymmentä bat-mittaa, ja kukin allas oli neljää kyynärää läpimitaten. Kullakin kymmenellä telineellä oli altaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Ja hän asetti viisi telinettä temppelin oikealle sivulle ja viisi temppelin vasemmalle sivulle; meren hän asetti temppelin oikealle sivulle, kaakkoa kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Hiiram teki myös kattilat, lapiot ja maljat. Ja niin Hiiram sai suoritetuksi kaiken työn, mikä hänen oli tehtävä kuningas Salomolle Herran temppeliin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'kaksi pylvästä ja ne kaksi pallonmuotoista pylväänpäätä, jotka olivat pylväiden päässä, ja ne kaksi ristikkokoristetta peittämään niitä kahta pallonmuotoista pylväänpäätä, jotka olivat pylväiden päässä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'ja ne neljäsataa granaattiomenaa kahteen ristikkokoristeeseen, kaksi riviä granaattiomenia kumpaankin ristikkokoristeeseen, peittämään niitä kahta pallonmuotoista pylväänpäätä, jotka olivat pylväiden päässä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'ja ne kymmenen telinettä ja ne kymmenen allasta telineiden päälle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'ja sen yhden meren, ja ne kaksitoista raavasta meren alle; ja kattilat, lapiot ja maljat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'Kaikki nämä kalut, jotka Hiiram teki kuningas Salomolle Herran temppeliin, olivat kiilloitetusta vaskesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'Jordanin lakeudella kuningas ne valatti savimuotteihin, Sukkotin ja Saaretanin välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Ja Salomo jätti kaikki kalut punnitsematta, koska niitä oli ylen paljon; vasken painoa ei määrätty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Salomo teetti myös kaikki muut kalut, mitä Herran temppelissä on: kulta-alttarin, pöydän, jolla näkyleivät ovat, kullasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'lampunjalat, viisi oikealle puolelle ja viisi vasemmalle puolelle kaikkeinpyhimmän eteen, puhtaasta kullasta, kultaisine kukkalehtineen, lamppuineen ja lamppusaksineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'vadit, veitset, maljat, kupit ja hiilipannut, puhtaasta kullasta, sekä kultasaranat niihin temppelin sisäosan oviin, jotka vievät kaikkeinpyhimpään, ja niihin temppelin oviin, jotka vievät temppelisaliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'Kun kaikki työ, minkä kuningas Salomo teetti Herran temppeliin, oli valmis, vei Salomo sinne isänsä Daavidin pyhät lahjat; hopean, kullan ja kalut hän pani Herran temppelin aarrekammioihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Sitten Salomo kokosi Israelin vanhimmat ja kaikki sukukuntien johtomiehet, israelilaisten perhekunta-päämiehet, kuningas Salomon luo Jerusalemiin, tuomaan Herran liitonarkkia Daavidin kaupungista, se on Siionista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'Niin kokoontuivat kuningas Salomon luo kaikki Israelin miehet juhlapäivänä eetanim-kuussa, joka on seitsemäs kuukausi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'Ja kun kaikki Israelin vanhimmat olivat tulleet saapuville, nostivat papit arkin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'ja he veivät Herran arkin ja ilmestysmajan sinne, sekä kaiken pyhän kaluston, joka oli majassa; papit ja leeviläiset veivät ne sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Ja kuningas Salomo seisoi arkin edessä ja hänen kanssaan koko Israelin kansa, joka oli kokoontunut hänen luoksensa; ja he uhrasivat lampaita ja raavaita niin paljon, että niitä ei voitu lukea, ei laskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Ja papit toivat Herran liitonarkin paikoilleen temppelin kuoriin, kaikkeinpyhimpään, kerubien siipien alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Sillä kerubit levittivät siipensä sen paikan yli, missä arkki oli, ja kerubit suojasivat ylhäältä päin arkkia ja sen korentoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Ja korennot olivat niin pitkät, että niiden päät voi nähdä kaikkeinpyhimmästä, kuorin edestä; mutta ulkoa niitä ei voinut nähdä. Ja ne jäivät sinne, tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Arkissa ei ollut muuta kuin ne kaksi kivitaulua, jotka Mooses oli pannut sinne Hoorebilla, kun Herra teki liiton israelilaisten kanssa, heidän lähdettyänsä Egyptin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'Ja kun papit lähtivät pyhäköstä, täytti pilvi Herran temppelin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'niin että papit eivät voineet astua toimittamaan virkaansa pilven tähden; sillä Herran kirkkaus täytti Herran temppelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Silloin Salomo sanoi: \"Herra on sanonut tahtovansa asua pimeässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Minä olen rakentanut huoneen sinulle asunnoksi, asuinsijan, asuaksesi siinä iäti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'Sitten kuningas käänsi kasvonsa ja siunasi koko Israelin seurakunnan; ja koko Israelin seurakunta seisoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'Hän sanoi: \"Kiitetty olkoon Herra, Israelin Jumala, joka kädellänsä on täyttänyt sen, mitä hän suullansa puhui minun isälleni Daavidille, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, '\'Siitä päivästä saakka, jona minä vein kansani Israelin pois Egyptistä, en ole mistään Israelin sukukunnasta valinnut yhtään kaupunkia, että siihen rakennettaisiin temppeli, missä minun nimeni asuisi; mutta minä olen valinnut Daavidin vallitsemaan kansaani Israelia\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Ja minun isäni Daavid aikoi rakentaa temppelin Herran, Israelin Jumalan, nimelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Mutta Herra sanoi minun isälleni Daavidille: \'Kun sinä aiot rakentaa temppelin minun nimelleni, niin tosin teet siinä hyvin, että sitä aiot;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'kuitenkaan et sinä ole sitä temppeliä rakentava, vaan sinun poikasi, joka lähtee sinun kupeistasi, hän on rakentava temppelin minun nimelleni\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'Ja Herra on täyttänyt sanansa, jonka hän puhui: minä olen noussut isäni Daavidin sijalle ja istun Israelin valtaistuimella, niinkuin Herra puhui, ja minä olen rakentanut temppelin Herran, Israelin Jumalan, nimelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'Ja minä olen valmistanut siihen sijan arkille, jossa on se Herran liitto, minkä hän teki meidän isiemme kanssa viedessään heidät pois Egyptin maasta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Sitten Salomo astui Herran alttarin eteen koko Israelin seurakunnan nähden, ojensi kätensä taivasta kohti');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'ja sanoi: \"Herra, Israelin Jumala, ei ole sinun vertaistasi jumalaa, ei ylhäällä taivaassa eikä alhaalla maan päällä, sinun, joka pidät liiton ja säilytät laupeuden palvelijoitasi kohtaan, jotka vaeltavat sinun edessäsi kaikesta sydämestänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'sinun, joka olet pitänyt, mitä puhuit palvelijallesi Daavidille, minun isälleni. Mitä suullasi puhuit, sen sinä kädelläsi täytit, niinkuin nyt on tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Niin pidä nytkin, Herra, Israelin Jumala, mitä puhuit palvelijallesi Daavidille, minun isälleni, sanoen: \'Aina on mies sinun suvustasi istuva minun edessäni Israelin valtaistuimella, jos vain sinun poikasi pitävät vaarin tiestänsä, niin että he vaeltavat minun edessäni, niinkuin sinä olet minun edessäni vaeltanut\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Niin toteutukoot nyt, Israelin Jumala, sinun sanasi, jotka puhuit palvelijallesi Daavidille, minun isälleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Mutta asuuko todella Jumala maan päällä? Katso, taivaisiin ja taivasten taivaisiin sinä et mahdu; kuinka sitten tähän temppeliin, jonka minä olen rakentanut!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Käänny kuitenkin palvelijasi rukouksen ja anomisen puoleen, Herra, minun Jumalani, niin että kuulet huudon ja rukouksen, jonka palvelijasi tänä päivänä rukoilee sinun edessäsi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'ja että silmäsi ovat yöt ja päivät avoinna tätä temppeliä kohti, tätä paikkaa kohti, josta sinä olet sanonut: \'Minun nimeni on asuva siellä\', niin että kuulet rukouksen, jonka palvelijasi tähän paikkaan päin kääntyneenä rukoilee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Kuule palvelijasi ja kansasi Israelin rukous, jonka he rukoilevat tähän paikkaan päin kääntyneinä; kuule asuinpaikastasi, taivaasta, ja kun kuulet, niin anna anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Jos joku rikkoo lähimmäistänsä vastaan ja hänet pannaan valalle ja vannotetaan, ja jos hän tulee ja vannoo sinun alttarisi edessä tässä temppelissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'niin kuule taivaasta ja auta palvelijasi oikeuteensa; tee niin, että tuomitset syyllisen syylliseksi ja annat hänen tekojensa tulla hänen päänsä päälle, mutta julistat syyttömän syyttömäksi ja annat hänelle hänen vanhurskautensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Jos vihollinen voittaa sinun kansasi, Israelin, sentähden että he ovat tehneet syntiä sinua vastaan, mutta he palajavat sinun tykösi, kiittävät sinun nimeäsi, rukoilevat sinua ja anovat sinulta armoa tässä temppelissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'niin kuule taivaasta ja anna anteeksi kansasi Israelin synti ja tuo heidät takaisin tähän maahan, jonka olet antanut heidän isillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Jos taivas suljetaan, niin ettei tule sadetta, koska he ovat tehneet syntiä sinua vastaan, mutta he rukoilevat kääntyneinä tähän paikkaan päin, ja kiittävät sinun nimeäsi ja kääntyvät synnistään, koska sinä kuulet heitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'niin kuule taivaasta ja anna anteeksi palvelijaisi ja kansasi Israelin synti-sillä sinä osoitat heille hyvän tien, jota heidän on vaeltaminen-ja suo sade maallesi, jonka olet antanut kansallesi perintöosaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Jos maahan tulee nälänhätä, rutto, jos tulee nokitähkä ja viljanruoste, jos tulevat heinäsirkat ja tuhosirkat, jos vihollinen ahdistaa sitä maassa, jossa sen portit ovat, jos tulee mikä tahansa vitsaus tai vaiva,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'ja jos silloin joku ihminen, kuka hyvänsä, tai koko sinun kansasi Israel rukoilee ja anoo armoa, kun he kukin tuntevat omantunnon vaivoja ja ojentavat kätensä tähän temppeliin päin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'niin kuule silloin taivaasta, asuinpaikastasi, ja anna anteeksi ja tee niin, että annat jokaiselle aivan hänen tekojensa mukaan, koska sinä tunnet hänen sydämensä-sillä sinä yksin tunnet kaikkien ihmislasten sydämet-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'jotta he sinua pelkäisivät niin kauan kuin he elävät tässä maassa, jonka sinä olet meidän isillemme antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Myös jos joku muukalainen, joka ei ole sinun kansaasi Israelia, tulee kaukaisesta maasta sinun nimesi tähden-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, 'sillä sielläkin kuullaan sinun suuresta nimestäsi, väkevästä kädestäsi ja ojennetusta käsivarrestasi-jos hän tulee ja rukoilee kääntyneenä tähän temppeliin päin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'niin kuule taivaasta, asuinpaikastasi, häntä ja tee kaikki, mitä muukalainen sinulta rukoilee, että kaikki maan kansat tuntisivat sinun nimesi ja pelkäisivät sinua, samoin kuin sinun kansasi Israel, ja tulisivat tietämään, että sinä olet ottanut nimiisi tämän temppelin, jonka minä olen rakentanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Jos sinun kansasi lähtee sotaan vihollistansa vastaan sitä tietä, jota sinä heidät lähetät, ja he rukoilevat Herraa kääntyneinä tähän kaupunkiin päin, jonka sinä olet valinnut, ja tähän temppeliin päin, jonka minä olen sinun nimellesi rakentanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'niin kuule taivaasta heidän rukouksensa ja anomisensa ja hanki heille oikeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Jos he tekevät syntiä sinua vastaan-sillä ei ole ihmistä, joka ei syntiä tee-ja sinä vihastut heihin ja annat heidät vihollisen valtaan, niin että heidän vangitsijansa vievät heidät vangeiksi vihollismaahan, kaukaiseen tai läheiseen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'mutta jos he sitten menevät itseensä siinä maassa, johon heidät on vangeiksi viety, kääntyvät ja anovat sinulta armoa vangitsijainsa maassa, sanoen: \'Me olemme tehneet syntiä, tehneet väärin ja olleet jumalattomat\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'ja palajavat sinun tykösi kaikesta sydämestään ja kaikesta sielustaan vihollistensa maassa, jotka veivät heidät vangeiksi, ja rukoilevat sinua kääntyneinä tähän maahan päin, jonka sinä olet antanut heidän isillensä, tähän kaupunkiin päin, jonka olet valinnut, ja tähän temppeliin päin, jonka minä olen sinun nimellesi rakentanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'niin kuule taivaasta, asuinsijastasi, heidän rukouksensa ja anomisensa, hanki heille oikeus');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'ja anna anteeksi kansallesi, mitä he ovat rikkoneet sinua vastaan, ja kaikki heidän syntinsä, jotka he ovat tehneet sinua vastaan; ja suo, että heidän vangitsijansa olisivat laupiaat heitä kohtaan ja armahtaisivat heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Sillä ovathan he sinun kansasi ja sinun perintöosasi, jonka olet vienyt pois Egyptistä, rautapätsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Olkoot siis sinun silmäsi avoinna palvelijasi ja sinun kansasi Israelin anomisen puoleen, niin että kuulet heitä kaikessa, mitä he sinulta rukoilevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Sillä sinä olet erottanut heidät perintöosaksesi kaikista maan kansoista, niinkuin sinä puhuit palvelijasi Mooseksen kautta, viedessäsi isämme pois Egyptistä, Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'Ja kun Salomo oli lakannut rukoilemasta ja anomasta Herralta kaikkea tätä, nousi hän Herran alttarin edestä, jossa hän oli ollut polvillaan kädet ojennettuina taivasta kohti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'astui esille ja siunasi koko Israelin seurakunnan suurella äänellä, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, '\"Kiitetty olkoon Herra, joka on antanut levon kansallensa Israelille, aivan niinkuin hän on puhunut. Ei ole jäänyt täyttämättä ainoakaan kaikista lupauksista, jotka Herra on antanut palvelijansa Mooseksen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Olkoon Herra, meidän Jumalamme, meidän kanssamme, niinkuin hän on ollut meidän isiemme kanssa. Älköön hän meitä jättäkö älköönkä hyljätkö,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'vaan kääntäköön meidän sydämemme puoleensa, niin että aina vaellamme hänen teitänsä ja noudatamme hänen käskyjänsä, säädöksiänsä ja oikeuksiansa, jotka hän on antanut meidän isillemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Ja olkoot nämä minun sanani, joilla minä olen armoa anonut Herran edessä, päivät ja yöt likellä Herraa, meidän Jumalaamme, että hän hankkisi oikeuden palvelijallensa ja kansallensa Israelille, kunkin päivän tarpeen mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'niin että kaikki maan kansat tulisivat tietämään, että Herra on Jumala eikä muuta jumalaa ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Ja antautukaa te ehyin sydämin Herralle, Jumalallenne, niin että vaellatte hänen säädöksiensä mukaan ja noudatatte hänen käskyjänsä samoin kuin nytkin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Sitten kuningas ja koko Israel hänen kanssansa uhrasivat teurasuhrin Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'Ja Salomo uhrasi yhteysuhrina, jonka hän Herralle uhrasi, kaksikymmentäkaksi tuhatta raavasta ja satakaksikymmentä tuhatta lammasta. Niin he, kuningas ja kaikki israelilaiset, vihkivät Herran temppelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Sinä päivänä kuningas pyhitti Herran temppelin edessä olevan esipihan keskiosan, sillä hänen oli siellä uhrattava polttouhri, ruokauhri ja yhteysuhrin rasvat. Vaskialttari, joka oli Herran edessä, oli näet liian pieni, että polttouhri, ruokauhri ja yhteysuhrin rasvat olisivat siihen mahtuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'Näin Salomo siihen aikaan vietti juhlaa, ja koko Israel hänen kanssansa, Herran, meidän Jumalamme, edessä seitsemän päivää ja vielä toiset seitsemän päivää, yhteensä neljätoista päivää. Se oli suuri kokous, johon kokoonnuttiin aina sieltä, mistä mennään Hamatiin, ja aina Egyptin purolta asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Kahdeksantena päivänä hän päästi kansan menemään, ja he hyvästelivät kuninkaan. Sitten he menivät majoillensa iloiten ja hyvillä mielin kaikesta hyvästä, mitä Herra oli tehnyt palvelijallensa Daavidille ja kansallensa Israelille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'Kun Salomo oli saanut rakennetuksi Herran temppelin ja kuninkaan linnan ja kaiken, mitä Salomo oli halunnut tehdä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'ilmestyi Herra Salomolle toisen kerran,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'niinkuin hän oli ilmestynyt hänelle Gibeonissa. Ja Herra sanoi hänelle: \"Minä olen kuullut sinun rukouksesi ja anomisesi, kun sinä anoit armoa minun edessäni. Minä olen pyhittänyt tämän temppelin, jonka sinä olet rakentanut sitä varten, että minä sijoittaisin nimeni siihen ainiaaksi; ja minun silmäni ja sydämeni tulevat alati olemaan siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Ja jos sinä vaellat minun edessäni, niinkuin sinun isäsi Daavid vaelsi, vilpittömällä sydämellä ja oikeamielisesti, niin että teet kaiken, mitä minä olen käskenyt sinun tehdä, ja noudatat minun käskyjäni ja oikeuksiani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'niin minä pidän pystyssä sinun kuninkaallisen valtaistuimesi Israelissa ikuisesti, niinkuin minä puhuin isällesi Daavidille sanoen: \'Aina on mies sinun suvustasi oleva Israelin valtaistuimella\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Mutta jos te käännytte pois minusta, te ja teidän lapsenne, ettekä noudata minun käskyjäni ja säädöksiäni, jotka minä olen teille antanut, vaan menette ja palvelette muita jumalia ja kumarratte niitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'niin minä hävitän Israelin siitä maasta, jonka olen antanut heille, ja temppelin, jonka minä olen pyhittänyt nimelleni, minä heitän pois kasvojeni edestä; ja Israel tulee sananparreksi ja pistopuheeksi kaikille kansoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'Ja tämä temppeli on tosin korkein, mutta jokainen, joka kulkee siitä ohi, on tyrmistyvä ja viheltävä; ja kun kysytään: \'Miksi on Herra tehnyt näin tälle maalle ja tälle temppelille?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'niin vastataan: \'Siksi, että he hylkäsivät Herran, Jumalansa, joka oli vienyt heidän isänsä pois Egyptin maasta, ja liittyivät muihin jumaliin ja kumarsivat niitä ja palvelivat niitä; sentähden Herra on antanut kaiken tämän pahan kohdata heitä\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'Kun olivat loppuun kuluneet ne kaksikymmentä vuotta, joiden kuluessa Salomo oli rakentanut ne kaksi rakennusta, Herran temppelin ja kuninkaan linnan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Hiiramin, Tyyron kuninkaan, avustaessa Salomoa setripuilla, kypressipuilla ja kullalla, niin paljolla kuin tämä halusi, silloin kuningas Salomo antoi Hiiramille kaksikymmentä kaupunkia Galilean maakunnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Niin Hiiram lähti Tyyrosta katsomaan niitä kaupunkeja, jotka Salomo oli antanut hänelle, mutta ne eivät miellyttäneet häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'Hän sanoi: \"Mitä kaupunkeja nämä ovat, jotka sinä olet antanut minulle, veljeni!\" Ja niin kutsutaan niitä Kaabulin maaksi vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Mutta Hiiram lähetti kuninkaalle sata kaksikymmentä talenttia kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'Ja näin on sen työveron laita, jonka kuningas Salomo otatti rakentaaksensa Herran temppeliä, omaa linnaansa, Milloa ja Jerusalemin muuria sekä Haasoria, Megiddoa ja Geseriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Farao, Egyptin kuningas, oli näet tullut ja valloittanut Geserin, polttanut sen tulella ja surmannut kanaanilaiset, jotka asuivat kaupungissa, ja antanut sen myötäjäisiksi tyttärellensä, Salomon puolisolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Ja Salomo linnoitti Geserin, alisen Beet-Hooronin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Baalatin ja Taamarin sen maan erämaassa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'ja kaikki varastokaupungit, jotka hänellä oli, ja kaikki vaunukaupungit ja ratsumiesten kaupungit ja mitä muuta Salomo oli tahtonut linnoittaa Jerusalemissa ja Libanonilla ja koko hallitsemassaan maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Kaiken kansan, mitä oli jäänyt jäljelle amorilaisista, heettiläisistä, perissiläisistä, hivviläisistä ja jebusilaisista, kaikki, jotka eivät olleet israelilaisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'ne niiden jälkeläiset, jotka vielä olivat jäljellä maassa ja joita israelilaiset eivät olleet kyenneet vihkimään tuhon omiksi, ne Salomo saattoi työveron alaisiksi, aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Mutta israelilaisista Salomo ei tehnyt ketään orjaksi, vaan heitä oli sotilaina, hänen palvelijoinaan, päällikköinään, vaunusotureinaan ja hänen sotavaunujensa ja ratsumiestensä päällikköinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Maaherrojen virkamiehiä, jotka valvoivat Salomon töitä, oli viisisataa viisikymmentä miestä, vallitsemassa väkeä, joka teki työtä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Heti kun faraon tytär oli muuttanut Daavidin kaupungista omaan linnaansa, jonka hän oli hänelle rakentanut, rakensi hän Millon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'Ja Salomo uhrasi kolme kertaa vuodessa polttouhreja ja yhteysuhreja alttarilla, jonka hän oli rakentanut Herralle, ja suitsutti alttarin ääressä, joka oli Herran edessä. Ja niin hän oli saanut temppelin valmiiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Kuningas Salomo rakensi myös laivaston Esjon-Geberissä, joka on lähellä Eelatia Kaislameren rannalla Edomin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'Tähän laivastoon Hiiram lähetti palvelijoitaan, meritaitoisia laivamiehiä, Salomon palvelijain mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'He menivät Oofiriin ja noutivat sieltä kultaa neljäsataa kaksikymmentä talenttia ja toivat sen kuningas Salomolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Kun Saban kuningatar kuuli, mitä Salomosta kerrottiin Herran nimen kunniaksi, tuli hän koettelemaan häntä arvoituksilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Hän tuli Jerusalemiin sangen suuren seurueen kanssa, mukanaan kameleja, jotka kantoivat hajuaineita, kultaa ylen paljon ja kalliita kiviä. Ja kun hän tuli Salomon luo, puhui hän tälle kaikki, mitä hänellä oli mielessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Mutta Salomo selitti hänelle kaikki hänen kysymyksensä; kuninkaalle ei mikään jäänyt ongelmaksi, jota hän ei olisi hänelle selittänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Kun Saban kuningatar näki kaiken Salomon viisauden, linnan, jonka hän oli rakentanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'ruuat hänen pöydällänsä, kuinka hänen palvelijansa asuivat ja hänen palvelusväkensä palveli ja kuinka he olivat puetut, ja näki hänen juomanlaskijansa ja hänen polttouhrinsa, jotka hän uhrasi Herran temppelissä, meni hän miltei hengettömäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'Sitten hän sanoi kuninkaalle: \"Totta oli se puhe, jonka minä kotimaahani sinusta ja sinun viisaudestasi kuulin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Minä en uskonut, mitä sanottiin, ennenkuin itse tulin ja sain omin silmin nähdä; ja katso, ei puoltakaan oltu minulle kerrottu. Sinulla on paljon enemmän viisautta ja rikkautta, kuin minä olin kuullut huhuttavan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Onnellisia ovat sinun miehesi, onnellisia nämä palvelijasi, jotka aina saavat olla sinun edessäsi ja kuulla sinun viisauttasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Kiitetty olkoon Herra, sinun Jumalasi, joka sinuun on niin mielistynyt, että on asettanut sinut Israelin valtaistuimelle. Sentähden, että Herra rakastaa Israelia ainiaan, hän on pannut sinut kuninkaaksi, tekemään sitä, mikä oikeus ja vanhurskaus on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'Ja hän antoi kuninkaalle sata kaksikymmentä talenttia kultaa, hyvin paljon hajuaineita ja kalliita kiviä. Niin paljon hajuaineita, kuin mitä Saban kuningatar antoi kuningas Salomolle, ei sinne ole sen jälkeen tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Myöskin Hiiramin laivat, jotka kuljettivat kultaa Oofirista, toivat Oofirista hyvin paljon santelipuuta ja kalliita kiviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'Ja kuningas teetti santelipuusta kalustoa Herran temppeliin ja kuninkaan linnaan ja kanteleita ja harppuja laulajille. Sellaista santelipuumäärää ei ole tuotu eikä nähty tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Kuningas Salomo taas antoi Saban kuningattarelle kaiken, mitä tämä halusi ja pyysi, ja sen lisäksi hän antoi muutakin kuninkaallisella anteliaisuudella. Sitten tämä lähti ja meni palvelijoineen omaan maahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Sen kullan paino, mikä yhtenä vuotena tuli Salomolle, oli kuusisataa kuusikymmentä kuusi talenttia kultaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'paitsi mitä tuli kauppamiehiltä ja kaupustelijain kaupanteosta ja kaikilta Erebin kuninkailta ja maan käskynhaltijoilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Ja kuningas Salomo teetti pakotetusta kullasta kaksisataa suurta kilpeä ja käytti jokaiseen kilpeen kuusisataa sekeliä kultaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'ja pakotetusta kullasta kolmesataa pienempää kilpeä, ja käytti jokaiseen kilpeen kolme miinaa kultaa. Ja kuningas asetti ne Libanoninmetsä-taloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Vielä kuningas teetti suuren norsunluisen valtaistuimen ja päällysti sen puhdistetulla kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Valtaistuimessa oli kuusi porrasta, ja valtaistuimen selusta oli ylhäältä pyöreä. Istuimen kummallakin puolella oli käsinoja, ja kaksi leijonaa seisoi käsinojain vieressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'Ja kaksitoista leijonaa seisoi siinä kuudella portaalla, kummallakin puolella. Senkaltaista ei ole tehty missään muussa valtakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Ja kaikki kuningas Salomon juoma-astiat olivat kultaa, ja kaikki Libanoninmetsä-talon astiat olivat puhdasta kultaa. Hopeata ei siellä ollut, eikä sitä Salomon päivinä pidetty minkään arvoisena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Kuninkaalla oli Tarsiin-laivasto merellä Hiiramin laivaston kanssa. Kerran kolmessa vuodessa Tarsiin-laivasto tuli ja toi kultaa ja hopeata, norsunluuta, apinoita ja riikinkukkoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'Ja kuningas Salomo oli kaikkia maan kuninkaita suurempi rikkaudessa ja viisaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Ja kaikki maa pyrki näkemään Salomoa kuullakseen hänen viisauttaan, jonka Jumala oli antanut hänen sydämeensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'Ja he toivat kukin lahjansa: hopea-ja kultakaluja, vaatteita, aseita, hajuaineita, hevosia ja muuleja, joka vuosi vuoden tarpeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Salomo kokosi sotavaunuja ja ratsumiehiä, niin että hänellä oli tuhannet neljätsadat sotavaunut ja kaksitoista tuhatta ratsumiestä; ne hän sijoitti vaunukaupunkeihin ja Jerusalemiin kuninkaan luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'Ja kuningas toimitti niin, että Jerusalemissa oli hopeata kuin kiviä, ja setripuuta niin paljon kuin metsäviikunapuita Alankomaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Ja hevoset, mitä Salomolla oli, tuotiin Egyptistä ja Kuvesta. Kuninkaan kauppiaat noutivat niitä Kuvesta maksua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Egyptistä tuodut vaunut maksoivat kuusisataa hopeasekeliä ja hevonen sata viisikymmentä. Samoin tuotiin niitä heidän välityksellään kaikille heettiläisten ja aramilaisten kuninkaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Mutta kuningas Salomolla oli paitsi faraon tytärtä monta muuta muukalaista vaimoa, joita hän rakasti: mooabilaisia, ammonilaisia, edomilaisia, siidonilaisia ja heettiläisiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'niiden kansain naisia, joista Herra oli sanonut israelilaisille: \"Älkää yhtykö heihin, älköötkä hekään yhtykö teihin; he varmasti taivuttavat teidän sydämenne seuraamaan heidän jumaliansa\". Näihin Salomo kiintyi rakkaudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Hänellä oli seitsemänsataa ruhtinaallista puolisoa ja kolmesataa sivuvaimoa; ja hänen vaimonsa taivuttivat hänen sydämensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'Ja kun Salomo vanheni, taivuttivat hänen vaimonsa hänen sydämensä seuraamaan muita jumalia, niin ettei hän antautunut ehyin sydämin Herralle, Jumalallensa, niinkuin hänen isänsä Daavidin sydän oli ollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Niin Salomo lähti seuraamaan Astartea, siidonilaisten jumalatarta, ja Milkomia, ammonilais-iljetystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'Ja Salomo teki sitä, mikä on pahaa Herran silmissä, eikä uskollisesti seurannut Herraa niinkuin hänen isänsä Daavid.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Silloin Salomo rakensi Kemokselle, mooabilais-iljetykselle, uhrikukkulan sille vuorelle, joka on itään päin Jerusalemista, ja samoin Moolokille, ammonilais-iljetykselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'Näin hän teki kaikkien muukalaisten vaimojen mieliksi, jotka suitsuttivat ja uhrasivat jumalilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'Niin Herra vihastui Salomoon, koska hänen sydämensä oli kääntynyt pois Herrasta, Israelin Jumalasta, joka kahdesti oli ilmestynyt hänelle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'ja nimenomaan kieltänyt häntä seuraamasta muita jumalia, ja koska hän ei ollut noudattanut Herran kieltoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Sentähden Herra sanoi Salomolle: \"Koska sinun on käynyt näin, ja koska et ole pitänyt minun liittoani etkä noudattanut minun käskyjäni, jotka minä sinulle annoin, niin minä repäisen valtakunnan sinulta ja annan sen sinun palvelijallesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Mutta isäsi Daavidin tähden minä en tee tätä sinun päivinäsi; sinun poikasi kädestä minä sen repäisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Kuitenkaan en minä repäise koko valtakuntaa: yhden sukukunnan minä annan sinun pojallesi palvelijani Daavidin tähden ja Jerusalemin tähden, jonka minä olen valinnut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Niin Herra nostatti Salomolle vastustajaksi edomilaisen Hadadin; tämä oli edomilaista kuningassukua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Kun Daavid oli sodassa Edomin kanssa ja sotapäällikkö Jooab meni hautaamaan kaatuneita ja surmasi kaikki miehenpuolet Edomissa-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, 'sillä Jooab ja koko Israel viipyi siellä kuusi kuukautta, kunnes olivat hävittäneet kaikki miehenpuolet Edomista-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'pakeni Hadad ja hänen kanssaan muutamat edomilaiset miehet, hänen isänsä palvelijat, Egyptiin päin; Hadad oli vielä pieni poikanen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'He lähtivät liikkeelle Midianista ja tulivat Paaraniin. Ja he ottivat mukaansa miehiä Paaranista ja tulivat Egyptiin faraon, Egyptin kuninkaan, luo. Tämä antoi hänelle talon ja määräsi hänelle elatuksen ja antoi hänelle myös maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'Ja Hadad pääsi faraon suureen suosioon, niin että hän antoi hänelle vaimoksi kälynsä, kuningatar Tahpeneen sisaren.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'Tahpeneen sisar synnytti hänelle hänen poikansa Genubatin, ja Tahpenes vieroitti hänet faraon palatsissa; ja niin jäi Genubat faraon palatsiin, faraon lasten joukkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'Kun Hadad Egyptissä kuuli, että Daavid oli mennyt lepoon isiensä tykö ja että sotapäällikkö Jooab oli kuollut, sanoi Hadad faraolle: \"Päästä minut menemään omaan maahani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Mutta farao sanoi hänelle: \"Mitä sinulta puuttuu minun luonani, koska haluat mennä omaan maahasi?\" Hän vastasi: \"Ei mitään, mutta päästä minut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Ja Jumala nostatti Salomolle vastustajaksi Resonin, Eljadan pojan, joka oli paennut herransa Hadadeserin, Sooban kuninkaan, luota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'Tämä kokosi miehiä ympärilleen ja oli partiojoukon päällikkönä silloin, kun Daavid surmasi heitä. He menivät sitten Damaskoon, asettuivat sinne ja hallitsivat Damaskossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'Ja hän oli Israelin vastustaja, niin kauan kuin Salomo eli, ja teki sille pahaa samoin kuin Hadadkin. Hän inhosi Israelia; ja hänestä tuli Aramin kuningas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Myöskin Salomon palvelija Jerobeam, Nebatin poika, efraimilainen Seredasta, jonka äiti oli nimeltään Serua ja oli leskivaimo, kohotti kätensä kuningasta vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'Hän joutui kohottamaan kätensä kuningasta vastaan seuraavalla tavalla. Salomo rakensi Milloa ja sulki siten aukon isänsä Daavidin kaupungissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Ja Jerobeam oli kelpo mies; ja kun Salomo näki, kuinka tämä nuori mies teki työtä, asetti hän hänet kaiken sen pakkotyön valvojaksi, mikä oli Joosefin heimon osalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Siihen aikaan tapahtui, kun Jerobeam kerran oli lähtenyt Jerusalemista, että siilolainen Ahia, profeetta, kohtasi hänet tiellä. Tämä oli puettuna uuteen vaippaan, ja he olivat kahdenkesken kedolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Silloin Ahia tarttui siihen uuteen vaippaan, joka hänellä oli yllään, ja repäisi sen kahdeksitoista kappaleeksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'ja sanoi Jerobeamille: \"Ota itsellesi kymmenen kappaletta, sillä näin sanoo Herra, Israelin Jumala: Katso, minä repäisen valtakunnan Salomon kädestä ja annan kymmenen sukukuntaa sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Yksi sukukunta jääköön hänelle minun palvelijani Daavidin tähden ja Jerusalemin kaupungin tähden, jonka minä olen valinnut kaikista Israelin sukukunnista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Näin on tapahtuva, koska he ovat hyljänneet minut ja kumartaneet Astartea, siidonilaisten jumalatarta, ja Kemosta, Mooabin jumalaa, ja Milkomia, ammonilaisten jumalaa, eivätkä ole vaeltaneet minun teitäni eivätkä tehneet sitä, mikä on oikein minun silmissäni, eivätkä noudattaneet minun käskyjäni ja oikeuksiani niinkuin Salomon isä Daavid.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Kuitenkaan en minä ota hänen kädestään koko valtakuntaa, vaan annan hänen olla ruhtinaana koko elinaikansa palvelijani Daavidin tähden, jonka minä valitsin, koska hän noudatti minun käskyjäni ja säädöksiäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Mutta hänen poikansa kädestä minä otan kuninkuuden ja annan sen sinulle, nimittäin ne kymmenen sukukuntaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'ja hänen pojallensa minä annan yhden sukukunnan, että minun palvelijallani Daavidilla aina olisi lamppu palamassa minun edessäni Jerusalemissa, siinä kaupungissa, jonka minä olen itselleni valinnut, asettaakseni nimeni siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Mutta sinut minä otan, ja sinä saat hallittavaksesi kaikki, joita haluat; sinusta tulee Israelin kuningas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Jos sinä olet kuuliainen kaikessa, mitä minä käsken sinun tehdä, ja vaellat minun tietäni ja teet sitä, mikä on oikein minun silmissäni, ja noudatat minun säädöksiäni ja käskyjäni, niinkuin minun palvelijani Daavid teki, niin minä olen sinun kanssasi ja rakennan sinulle pysyväisen huoneen, niinkuin minä Daavidille rakensin, ja annan Israelin sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'Siitä syystä minä nöyryytän Daavidin jälkeläiset, en kuitenkaan ainiaaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Salomo koetti saada surmatuksi Jerobeamin; mutta Jerobeam lähti ja pakeni Egyptiin, Suusakin, Egyptin kuninkaan, luo. Ja hän oli Egyptissä Salomon kuolemaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'Mitä muuta Salomosta on kerrottavaa, kaikesta, mitä hän teki, ja hänen viisaudestansa, se on kirjoitettuna Salomon historiassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Ja aika, minkä Salomo hallitsi Jerusalemissa koko Israelia, oli neljäkymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'Sitten Salomo meni lepoon isiensä tykö ja hänet haudattiin isänsä Daavidin kaupunkiin. Ja hänen poikansa Rehabeam tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Rehabeam meni Sikemiin, sillä koko Israel oli tullut Sikemiin tekemään häntä kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'Kun Jerobeam, Nebatin poika, kuuli sen-hän oli vielä Egyptissä, jonne hän oli paennut kuningas Salomoa, ja Jerobeam asui Egyptissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'mutta he lähettivät kutsumaan hänet-niin Jerobeam ja koko Israelin seurakunta tuli saapuville, ja he puhuivat Rehabeamille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, '\"Sinun isäsi teki meidän ikeemme raskaaksi; mutta huojenna sinä nyt se kova työ, jota isäsi teetti, ja se raskas ies, jonka hän pani meidän niskaamme, niin me palvelemme sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Hän vastasi heille: \"Menkää ja odottakaa kolme päivää ja tulkaa sitten takaisin minun tyköni\". Ja kansa meni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Kuningas Rehabeam neuvotteli vanhain kanssa, jotka olivat palvelleet hänen isäänsä Salomoa, kun tämä vielä eli, ja kysyi: \"Kuinka te neuvotte vastaamaan tälle kansalle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'He vastasivat hänelle ja sanoivat: \"Jos sinä tänä päivänä rupeat tämän kansan palvelijaksi ja palvelet heitä, jos kuulet heitä ja puhut heille hyviä sanoja, niin he ovat sinun palvelijoitasi kaiken elinaikasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Mutta hän hylkäsi tämän neuvon, jonka vanhat hänelle antoivat, ja neuvotteli nuorten miesten kanssa, jotka olivat kasvaneet hänen kanssaan ja jotka palvelivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'Hän kysyi heiltä: \"Kuinka te neuvotte meitä vastaamaan tälle kansalle, joka on puhunut minulle sanoen: \'Huojenna se ies, jonka sinun isäsi on pannut meidän niskaamme\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Niin nuoret miehet, jotka olivat kasvaneet hänen kanssaan, vastasivat hänelle sanoen: \"Sano näin tälle kansalle, joka on puhunut sinulle sanoen: \'Sinun isäsi teki meidän ikeemme raskaaksi, mutta huojenna sinä sitä meiltä\' -puhu heille näin: \'Minun pikkusormeni on paksumpi kuin minun isäni lantio.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Jos siis isäni on sälyttänyt teidän selkäänne raskaan ikeen, niin minä teen teidän ikeenne vielä raskaammaksi; jos isäni on kurittanut teitä raipoilla, niin minä kuritan teitä piikkiruoskilla.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Niin Jerobeam ja kaikki kansa tuli Rehabeamin tykö kolmantena päivänä, niinkuin kuningas oli käskenyt sanoen: \"Tulkaa takaisin minun tyköni kolmantena päivänä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'Ja kuningas antoi kansalle kovan vastauksen, hyljäten sen neuvon, jonka vanhat olivat hänelle antaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'Ja hän puhui heille nuorten miesten neuvon mukaan, sanoen: \"Jos minun isäni on tehnyt teidän ikeenne raskaaksi, niin minä teen ikeenne vielä raskaammaksi; jos minun isäni on kurittanut teitä raipoilla, niin minä kuritan teitä piikkiruoskilla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Kuningas ei siis kuullut kansaa; sillä Herra sen niin salli täyttääkseen sanansa, jonka Herra oli puhunut Jerobeamille, Nebatin pojalle, siilolaisen Ahian kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'Kun koko Israel huomasi, ettei kuningas heitä kuullut, vastasi kansa kuninkaalle näin: \"Mitä osaa meillä on Daavidiin? Ei meillä ole perintöosaa Iisain poikaan. Majoillesi, Israel! Valvo nyt huonettasi, Daavid!\" Ja Israel meni majoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Niin Rehabeam tuli ainoastaan niiden israelilaisten kuninkaaksi, jotka asuivat Juudan kaupungeissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Ja kun kuningas Rehabeam lähetti matkaan verotöiden valvojan Adoramin, kivitti koko Israel hänet kuoliaaksi. Silloin kuningas Rehabeam nousi nopeasti vaunuihinsa ja pakeni Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Näin Israel luopui Daavidin suvusta, aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'Mutta kun koko Israel kuuli, että Jerobeam oli tullut takaisin, lähettivät he kutsumaan hänet kansankokoukseen ja tekivät hänet koko Israelin kuninkaaksi. Daavidin sukua ei seurannut kukaan muu kuin Juudan sukukunta yksin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Ja kun Rehabeam tuli Jerusalemiin, kokosi hän koko Juudan heimon ja Benjaminin sukukunnan, satakahdeksankymmentä tuhatta sotakuntoista valiomiestä, sotimaan Israelin heimoa vastaan ja palauttamaan kuninkuutta Rehabeamille Salomon pojalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Mutta Jumalan miehelle Semajalle tuli tämä Jumalan sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, '\"Sano Rehabeamille, Salomon pojalle, Juudan kuninkaalle, ja koko Juudan ja Benjaminin heimoille sekä muulle kansalle näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, '\'Näin sanoo Herra: Älkää menkö sotimaan veljiänne, israelilaisia, vastaan. Palatkaa kukin kotiinne, sillä minä olen sallinut tämän tapahtua.\'\" Niin he kuulivat Herran sanaa, kääntyivät takaisin ja menivät pois Herran sanan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Mutta Jerobeam linnoitti Sikemin Efraimin vuoristossa ja asettui sinne. Sitten hän lähti sieltä ja linnoitti Penuelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Ja Jerobeam ajatteli sydämessänsä: \"Nyt valtakunta joutuu takaisin Daavidin suvulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Jos tämä kansa menee ja uhraa teurasuhreja Herran temppelissä Jerusalemissa, niin tämän kansan sydän kääntyy jälleen heidän herransa Rehabeamin, Juudan kuninkaan, puolelle; ja he tappavat minut ja palaavat takaisin Rehabeamin, Juudan kuninkaan, luo.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Mietittyään asiaa kuningas teetti kaksi kultaista vasikkaa ja sanoi heille: \"Te olette jo tarpeeksi kauan kulkeneet Jerusalemissa. Katso, Israel, tässä on sinun Jumalasi, joka on johdattanut sinut Egyptin maasta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'Ja hän pystytti toisen Beeteliin, ja toisen hän asetti Daaniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'Ja tämä koitui synniksi. Ja kansa kulki sen toisen kuvan luo Daaniin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Hän rakensi myös uhrikukkulatemppeleitä ja teki kansan keskuudesta papeiksi kaikenkaltaisia miehiä, jotka eivät olleet leeviläisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Ja Jerobeam laittoi juhlan kahdeksannessa kuussa, kuukauden viidentenätoista päivänä, sen juhlan kaltaisen, jota vietetään Juudassa, ja nousi silloin itse alttarille; niin hän teki Beetelissä ja uhrasi niille vasikoille, jotka hän oli teettänyt. Ja tekemiänsä uhrikukkulapappeja hän asetti virkaan Beeteliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'Hän nousi sille alttarille, jonka oli teettänyt Beeteliin, viidentenätoista päivänä kahdeksatta kuuta, jonka kuukauden hän oli omasta päästään keksinyt. Hän laittoi silloin juhlan israelilaisille ja nousi alttarille polttamaan uhreja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'Ja katso, Juudasta Beeteliin tuli Herran käskystä Jumalan mies, juuri kun Jerobeam seisoi alttarin ääressä polttamassa uhreja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'Ja hän huusi alttaria kohti Herran käskystä ja sanoi: \"Alttari, alttari, näin sanoo Herra: Katso, Daavidin suvusta on syntyvä poika, nimeltä Joosia. Hän on teurastava sinun päälläsi uhrikukkulapapit, jotka polttavat uhreja sinun päälläsi, ja sinun päälläsi tullaan polttamaan ihmisten luita.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'Ja hän antoi sinä päivänä ennusmerkin, sanoen: \"Ennusmerkki siitä, että Herra on puhunut, on tämä: alttari halkeaa, ja tuhka, joka on sen päällä, hajoaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'Kun kuningas Jerobeam kuuli Jumalan miehen sanan, jonka hän huusi alttaria kohti Beetelissä, ojensi hän kätensä alttarilta ja sanoi: \"Ottakaa hänet kiinni\". Silloin hänen kätensä, jonka hän oli ojentanut häntä vastaan, kuivettui, eikä hän enää voinut vetää sitä takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Ja alttari halkesi ja tuhka hajosi alttarilta, niinkuin Jumalan mies Herran käskystä oli ennusmerkin antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Silloin kuningas puhkesi puhumaan ja sanoi Jumalan miehelle: \"Lepytä Herraa, Jumalaasi, ja rukoile minun puolestani, että minä voisin vetää käteni takaisin\". Ja Jumalan mies lepytti Herraa; niin kuningas voi vetää kätensä takaisin, ja se tuli entiselleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Ja kuningas puhui Jumalan miehelle: \"Tule minun kanssani kotiini virkistämään itseäsi; minä annan sinulle lahjan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Mutta Jumalan mies sanoi kuninkaalle: \"Vaikka antaisit minulle puolet linnastasi, en minä tulisi sinun kanssasi. Tässä paikassa en minä syö leipää enkä juo vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Sillä niin käski minua Herra sanallansa, sanoen: Älä syö leipää, älä juo vettä äläkä palaa samaa tietä, jota olet tullut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Ja hän meni toista tietä eikä palannut samaa tietä, jota oli tullut Beeteliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Mutta Beetelissä asui vanha profeetta; ja hänen poikansa tuli ja kertoi hänelle kaiken, mitä Jumalan mies sinä päivänä oli tehnyt Beetelissä ja mitä hän oli puhunut kuninkaalle. Kun he olivat kertoneet sen isällensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'kysyi heidän isänsä heiltä, mitä tietä hän oli mennyt. Ja hänen poikansa olivat nähneet, mitä tietä Juudasta tullut Jumalan mies oli lähtenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Silloin hän sanoi pojilleen: \"Satuloikaa minulle aasi\". Ja kun he olivat satuloineet hänelle aasin, istui hän sen selkään');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'ja lähti Jumalan miehen jälkeen ja tapasi hänet istumassa tammen alla. Ja hän kysyi häneltä: \"Sinäkö olet se Juudasta tullut Jumalan mies?\" Hän vastasi: \"Minä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Hän sanoi hänelle: \"Tule kanssani minun kotiini syömään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Hän vastasi: \"En voi palata enkä tulla sinun kanssasi, en voi syödä leipää enkä juoda vettä sinun kanssasi tässä paikassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'sillä minulle on tullut sana, Herran sana: \'Älä syö leipää äläkä juo vettä siellä, älä myöskään tule takaisin samaa tietä, jota olet mennyt\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Hän sanoi hänelle: \"Minäkin olen profeetta niinkuin sinä, ja enkeli on puhunut minulle Herran käskystä, sanoen: \'Vie hänet kanssasi takaisin kotiisi syömään leipää ja juomaan vettä\'\". Mutta sen hän valhetteli hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Niin tämä palasi hänen kanssansa ja söi leipää ja joi vettä hänen kodissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Mutta heidän istuessaan pöydässä tuli Herran sana profeetalle, joka oli tuonut hänet takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'Ja hän huusi Juudasta tulleelle Jumalan miehelle, sanoen: \"Näin sanoo Herra: Koska sinä olet niskoitellut Herran käskyä vastaan etkä ole noudattanut sitä määräystä, jonka Herra, sinun Jumalasi, sinulle antoi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'vaan olet palannut syömään leipää ja juomaan vettä siinä paikassa, josta sinulle oli sanottu: \'Älä siellä syö leipää äläkä juo vettä\', niin älköön sinun ruumiisi tulko isiesi hautaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'Ja kun hän oli syönyt leipää ja juonut, satuloi hän aasin profeetalle, jonka hän oli tuonut takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'Kun tämä oli lähtenyt, kohtasi hänet leijona tiellä ja tappoi hänet. Ja hänen ruumiinsa oli pitkänään tiellä, ja aasi seisoi hänen vieressään, ja leijona seisoi ruumiin ääressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'Ja katso, siitä kulki ohitse miehiä, ja he näkivät ruumiin pitkänään tiellä ja leijonan seisomassa ruumiin ääressä. He menivät ja puhuivat siitä kaupungissa, jossa vanha profeetta asui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Kun profeetta, joka oli palauttanut hänet tieltä, kuuli sen, sanoi hän: \"Se on se Jumalan mies, joka niskoitteli Herran käskyä vastaan. Sentähden Herra on antanut hänet leijonalle, ja se on ruhjonut ja tappanut hänet sen Herran sanan mukaan, jonka hän oli hänelle puhunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Ja hän puhui pojilleen, sanoen: \"Satuloikaa minulle aasi\". Ja he satuloivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'Ja hän lähti ja löysi hänen ruumiinsa, joka oli pitkänään tiellä, ja aasin ja leijonan seisomasta ruumiin ääressä; leijona ei ollut syönyt ruumista eikä myöskään ruhjonut aasia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Niin profeetta otti Jumalan miehen ruumiin, pani sen aasin selkään ja vei sen takaisin; ja vanha profeetta tuli kaupunkiin pitämään valittajaisia ja hautaamaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'Ja hän pani ruumiin omaan hautaansa; ja he pitivät valittajaiset hänelle ja huusivat: \"Voi, minun veljeni!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'Ja kun hän oli haudannut hänet, sanoi hän pojilleen näin: \"Kun minä kuolen, niin haudatkaa minut siihen hautaan, johon Jumalan mies on haudattu, ja pankaa minun luuni hänen luittensa viereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Sillä toteutuva on sana, jonka hän Herran käskystä huusi Beetelissä olevaa alttaria vastaan ja kaikkia Samarian kaupungeissa olevia uhrikukkulatemppeleitä vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Ei tämänkään jälkeen Jerobeam kääntynyt pahalta tieltään, vaan teki taas uhrikukkulapapeiksi kaikenkaltaisia miehiä kansan keskuudesta. Kuka vain halusi, sen hän vihki papin virkaan, ja niin siitä tuli uhrikukkulapappi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'Ja tällä tavalla tämä tuli synniksi Jerobeamin suvulle ja syyksi siihen, että se hävitettiin ja hukutettiin maan päältä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Siihen aikaan sairastui Abia, Jerobeamin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'Niin Jerobeam sanoi vaimollensa: \"Nouse ja pukeudu niin, ettei sinua tunneta Jerobeamin vaimoksi, ja mene Siiloon. Katso, siellä on profeetta Ahia, joka ilmoitti, että minusta on tuleva tämän kansan kuningas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'Ja ota mukaasi kymmenen leipää sekä pieniä leivoksia ja ruukullinen hunajaa ja mene hänen luoksensa. Hän ilmaisee sinulle, kuinka pojan käy.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'Jerobeamin vaimo teki niin: hän nousi ja meni Siiloon ja tuli Ahian taloon. Ja Ahia ei voinut nähdä, sillä hänellä oli vanhuuttaan kaihi silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'Mutta Herra oli sanonut Ahialle: \"Katso, Jerobeamin vaimo tulee sinulta kysymään pojastaan, sillä hän on sairaana. Niin ja niin on sinun puhuttava hänelle.\" Ja kun hän tuli tekeytyen tuntemattomaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'ja kun Ahia kuuli hänen askeleensa hänen tullessaan ovessa, sanoi hän: \"Tule sisään, Jerobeamin vaimo; miksi sinä tekeydyt tuntemattomaksi? Minä olen saanut ilmoittaakseni sinulle kovan sanoman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Mene ja sano Jerobeamille: \'Näin sanoo Herra, Israelin Jumala: Minä olen korottanut sinut kansan seasta ja asettanut sinut kansani Israelin ruhtinaaksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'ja reväissyt valtakunnan Daavidin suvulta ja antanut sen sinulle. Mutta sinä et ole ollut niinkuin minun palvelijani Daavid, joka noudatti minun käskyjäni ja seurasi minua kaikesta sydämestänsä, niin että hän teki ainoastaan sitä, mikä oli oikeata minun silmissäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Vaan sinä olet tehnyt enemmän pahaa kuin kaikki sinun edeltäjäsi: sinä olet mennyt ja tehnyt itsellesi muita jumalia, valettuja kuvia, ja olet vihoittanut minut ja heittänyt minut selkäsi taakse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Katso, sentähden minä annan onnettomuuden kohdata Jerobeamin sukua ja hävitän Israelista Jerobeamin miespuoliset jälkeläiset, kaikki tyynni, ja minä lakaisen pois Jerobeamin suvun, niinkuin saasta lakaistaan, kunnes siitä on tullut loppu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Joka Jerobeamin jälkeläisistä kuolee kaupungissa, sen koirat syövät, ja joka kuolee kedolle, sen syövät taivaan linnut. Sillä Herra on puhunut.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Niin nouse nyt ja mene kotiisi. Kun sinun jalkasi astuu kaupunkiin, kuolee lapsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'Ja koko Israel on pitävä valittajaiset hänelle, ja hänet haudataan. Sillä Jerobeamin jälkeläisistä on hän yksin tuleva hautaan, koska Jerobeamin suvussa on vain hänessä havaittu jotakin Herralle, Israelin Jumalalle, otollista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Mutta Herra on herättävä itsellensä Israeliin kuninkaan, joka hävittää Jerobeamin suvun. Se on se päivä; ja mitä sitten?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'Herra on lyövä Israelia, niin että se tulee ruovon kaltaiseksi, joka häilyy vedessä. Ja hän kiskaisee Israelin irti tästä hyvästä maasta, jonka hän on antanut heidän isillensä, ja hajottaa heidät tuolle puolelle Eufrat-virran, koska he ovat tehneet itsellensä asera-karsikkoja ja siten vihoittaneet Herran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'Ja hän antaa alttiiksi Israelin niiden syntien tähden, jotka Jerobeam on tehnyt ja joilla hän on saattanut Israelin tekemään syntiä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Niin Jerobeamin vaimo nousi, meni matkaansa ja tuli Tirsaan. Juuri kun hän tuli huoneen kynnykselle, kuoli poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'Ja hänet haudattiin, ja koko Israel piti valittajaiset hänelle, sen sanan mukaan, jonka Herra oli puhunut palvelijansa, profeetta Ahian, kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Mitä muuta on kerrottavaa Jerobeamista, kuinka hän soti ja kuinka hän hallitsi, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Ja aika, minkä Jerobeam hallitsi, oli kaksikymmentä kaksi vuotta. Sitten hän meni lepoon isiensä tykö. Ja hänen poikansa Naadab tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Mutta Rehabeam, Salomon poika, tuli Juudan kuninkaaksi. Neljänkymmenen yhden vuoden vanha oli Rehabeam tullessaan kuninkaaksi, ja hän hallitsi seitsemäntoista vuotta Jerusalemissa, siinä kaupungissa, jonka Herra oli valinnut kaikista Israelin sukukunnista, asettaakseen nimensä siihen. Hänen äitinsä oli nimeltään Naema, ammonilainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'Ja Juuda teki sitä, mikä oli pahaa Herran silmissä. Synneillänsä, joita he tekivät, he vihoittivat Herraa paljon enemmän, kuin heidän isänsä olivat tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Hekin tekivät itsellensä uhrikukkuloita, patsaita ja asera-karsikkoja kaikille korkeille kukkuloille ja jokaisen viheriän puun alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Ja maassa oli myöskin haureellisia pyhäkköpoikia. He jäljittelivät niiden kansojen kaikkia kauhistavia tekoja, jotka Herra oli karkoittanut israelilaisten tieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'Mutta kuningas Rehabeamin viidentenä hallitusvuotena hyökkäsi Suusak, Egyptin kuningas, Jerusalemin kimppuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Ja hän otti Herran temppelin aarteet ja kuninkaan palatsin aarteet; otti kaikki tyynni. Hän otti myös kaikki ne kultakilvet, jotka Salomo oli teettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Kuningas Rehabeam teetti niiden sijaan vaskikilvet ja jätti ne henkivartijain päälliköiden haltuun, jotka vartioivat kuninkaan linnan ovella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'Ja niin usein kuin kuningas meni Herran temppeliin, kantoivat henkivartijat niitä ja veivät ne sitten takaisin henkivartijain huoneeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Mitä muuta on kerrottavaa Rehabeamista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Mutta Rehabeam ja Jerobeam olivat kaiken aikaa sodassa keskenään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'Sitten Rehabeam meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Hänen äitinsä oli nimeltään Naema, ammonilainen. Ja hänen poikansa Abiam tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Ja kuningas Jerobeamin, Nebatin pojan, kahdeksantenatoista hallitusvuotena tuli Abiam Juudan kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Hän hallitsi kolme vuotta Jerusalemissa. Hänen äitinsä oli nimeltään Maaka, Abisalomin tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Ja hän vaelsi kaikissa isänsä synneissä, joita tämä oli tehnyt ennen häntä, eikä hänen sydämensä ollut ehyesti antautunut Herralle, hänen Jumalallensa, niinkuin hänen isänsä Daavidin sydän oli ollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Mutta Daavidin tähden Herra, hänen Jumalansa, antoi hänen lamppunsa palaa Jerusalemissa, korottamalla hänen jälkeläisekseen hänen poikansa ja pitämällä Jerusalemia pystyssä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'koska Daavid oli tehnyt sitä, mikä on oikein Herran silmissä, eikä koko elinaikanaan ollut poikennut mistään, mitä hän on käskenyt, paitsi heettiläisen Uurian asiassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Ja Abiam oli koko elinaikansa sodassa Jerobeamin kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Mitä muuta on kerrottavaa Abiamista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa. Mutta Abiam ja Jerobeam olivat sodassa keskenään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'Ja Abiam meni lepoon isiensä tykö, ja hänet haudattiin Daavidin kaupunkiin. Ja Aasa, hänen poikansa, tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'Israelin kuninkaan Jerobeamin kahdentenakymmenentenä hallitusvuotena tuli Aasa Juudan kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Hän hallitsi neljäkymmentä yksi vuotta Jerusalemissa. Hänen äitinsä oli nimeltään Maaka, Abisalomin tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'Ja Aasa teki sitä, mikä oli oikein Herran silmissä, niinkuin hänen isänsä Daavid,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'ja toimitti haureelliset pyhäkköpojat pois maasta ja hävitti kaikki ne kivijumalat, jotka hänen isänsä olivat tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Jopa hän erotti äitinsä Maakan kuningattaren arvosta, koska tämä oli pystyttänyt inhotuksen Aseralle; ja Aasa kukisti inhotuksen ja poltti sen Kidronin laaksossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Mutta uhrikukkulat eivät hävinneet. Kuitenkin oli Aasan sydän ehyesti antautunut Herralle, niin kauan kuin hän eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'Ja hän vei Herran temppeliin isänsä pyhät lahjat ja omat pyhät lahjansa: hopeata, kultaa ja kaluja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Mutta Aasa ja Israelin kuningas Baesa olivat kaiken aikansa sodassa keskenään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Baesa, Israelin kuningas, lähti Juudaa vastaan ja linnoitti Raaman, estääkseen ketään pääsemästä Aasan, Juudan kuninkaan, luota tai hänen luokseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Ja Aasa otti kaiken hopean ja kullan, mikä vielä oli jäljellä Herran temppelin ja kuninkaan linnan aarrekammioissa, ja antoi sen palvelijainsa haltuun; ja kuningas Aasa lähetti heidät Benhadadin, Tabrimmonin pojan, Hesjonin pojanpojan, Aramin kuninkaan, luo, joka asui Damaskossa, ja käski sanoa hänelle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, '\"Onhan liitto meidän välillämme, minun ja sinun, niinkuin oli minun isäni ja sinun isäsi välillä. Katso, minä lähetän sinulle hopeata ja kultaa lahjaksi; mene ja riko Baesan, Israelin kuninkaan, kanssa tekemäsi liitto, että hän lähtisi pois minun kimpustani.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'Niin Benhadad kuuli kuningas Aasaa ja lähetti sotajoukkojensa päälliköt Israelin kaupunkeja vastaan ja valtasi Iijonin, Daanin, Aabel-Beet-Maakan ja koko Kinnerotin ynnä koko Naftalin maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Kun Baesa kuuli sen, lakkasi hän linnoittamasta Raamaa ja jäi Tirsaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Mutta kuningas Aasa kutsui kokoon kaiken Juudan, vapauttamatta ketään. Ja he veivät pois kivet ja puut, joilla Baesa oli linnoittanut Raamaa. Niillä kuningas Aasa linnoitti Geban, joka on Benjaminissa, ja Mispan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Mitä muuta kaikkea on kerrottavaa Aasasta, kaikista hänen urotöistään, kaikesta, mitä hän teki, ja kaupungeista, jotka hän rakensi, se on kirjoitettuna Juudan kuningasten aikakirjassa. Mutta vanhuutensa päivinä hän oli sairas jaloistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'Sitten Aasa meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen hänen isänsä Daavidin kaupunkiin. Ja hänen poikansa Joosafat tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Ja Naadab, Jerobeamin poika, tuli Israelin kuninkaaksi Aasan, Juudan kuninkaan, toisena hallitusvuotena, ja hän hallitsi Israelia kaksi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'Hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi isänsä teitä ja hänen synnissänsä, jolla hän oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Mutta Baesa, Ahian poika, Isaskarin sukua, teki salaliiton häntä vastaan, ja Baesa surmasi hänet Gibbetonin luona, joka oli filistealaisilla; sillä Naadab ja koko Israel piirittivät Gibbetonia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'Baesa tappoi hänet Juudan kuninkaan Aasan kolmantena hallitusvuotena ja tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Kuninkaaksi tultuaan hän surmasi koko Jerobeamin suvun jättämättä Jerobeamin jälkeläisistä eloon ainoatakaan henkeä: hän hävitti heidät Herran sanan mukaan, jonka hän oli puhunut palvelijansa, siilolaisen Ahian, kautta-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'niiden syntien tähden, jotka Jerobeam oli tehnyt ja joilla hän oli saattanut Israelin tekemään syntiä, siten vihoittaen Herran, Israelin Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Mitä muuta on kerrottavaa Naadabista ja kaikesta, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'Mutta Aasa ja Israelin kuningas Baesa olivat kaiken aikansa sodassa keskenään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Aasan, Juudan kuninkaan, kolmantena hallitusvuotena tuli Baesa, Ahian poika, koko Israelin kuninkaaksi Tirsassa, ja hän hallitsi kaksikymmentä neljä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'Hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi Jerobeamin teitä ja hänen synneissänsä, joilla hän oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'Ja Jeehulle, Hananin pojalle, tuli tämä Herran sana Baesaa vastaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, '\"Sentähden, että sinä, vaikka minä olen korottanut sinut tomusta ja pannut sinut kansani Israelin ruhtinaaksi, olet vaeltanut Jerobeamin teitä ja saattanut minun kansani Israelin tekemään syntiä, niin että he ovat vihoittaneet minut synneillänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'katso, minä lakaisen pois Baesan ja hänen sukunsa. Minä teen sinun suvullesi, niinkuin minä tein Jerobeamin, Nebatin pojan, suvulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Joka Baesan jälkeläisistä kuolee kaupungissa, sen koirat syövät, ja joka kuolee kedolle, sen syövät taivaan linnut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Mitä muuta on kerrottavaa Baesasta, siitä, mitä hän teki, ja hänen urotöistänsä, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'Ja Baesa meni lepoon isiensä tykö, ja hänet haudattiin Tirsaan. Ja hänen poikansa Eela tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Mutta profeetta Jeehun, Hananin pojan, kautta oli tullut Herran sana Baesaa ja hänen sukuansa vastaan kaiken sen tähden, mitä hän oli tehnyt ja mikä oli pahaa Herran silmissä, hänen kättensä tekojen tähden, joilla hän oli vihoittanut Herran, niin että hänen kävi niinkuin Jerobeamin suvun, kuin myöskin sen tähden, että hän oli surmannut tämän suvun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Aasan, Juudan kuninkaan, kahdentenakymmenentenä kuudentena hallitusvuotena tuli Eela, Baesan poika, Israelin kuninkaaksi Tirsassa, ja hän hallitsi kaksi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'Mutta hänen palvelijansa Simri, jolla oli johdossaan puolet sotavaunuista, teki salaliiton häntä vastaan. Ja kun hän Tirsassa kerran oli juonut itsensä juovuksiin Tirsassa olevan linnan päällikön Arsan talossa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'tuli Simri sinne ja löi hänet kuoliaaksi Juudan kuninkaan Aasan kahdentenakymmenentenä seitsemäntenä hallitusvuotena; ja hän tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'Ja kun hän oli tullut kuninkaaksi ja istunut valtaistuimelleen, surmasi hän koko Baesan suvun eikä jättänyt hänen jälkeläisistään eloon ainoatakaan miehenpuolta, ei sukulunastajaa eikä ystävää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Ja niin tuhosi Simri koko Baesan suvun, Herran sanan mukaan, jonka hän oli puhunut Baesaa vastaan profeetta Jeehun kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'kaikkien Baesan ja hänen poikansa Eelan syntien tähden, jotka nämä olivat tehneet ja joilla he olivat saattaneet Israelin tekemään syntiä; he olivat vihoittaneet Herran, Israelin Jumalan, turhilla jumalilla, joita he palvelivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Mitä muuta on kerrottavaa Eelasta ja kaikesta, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Juudan kuninkaan Aasan kahdentenakymmenentenä seitsemäntenä hallitusvuotena tuli Simri kuninkaaksi, ja hän hallitsi Tirsassa seitsemän päivää. Väki oli silloin asettuneena leiriin Gibbetonin edustalle, joka oli filistealaisilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Kun leiriin asettunut väki kuuli sanottavan: \"Simri on tehnyt salaliiton ja on myös surmannut kuninkaan\", niin koko Israel teki sinä päivänä leirissä Omrin, Israelin sotapäällikön, kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Ja Omri ja koko Israel hänen kanssaan lähti Gibbetonista, ja he saarsivat Tirsan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'Ja kun Simri näki, että kaupunki oli valloitettu, meni hän kuninkaan linnan palatsiin ja poltti kuninkaan linnan päänsä päältä tulella, ja niin hän kuoli,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'syntiensä tähden, jotka hän oli tehnyt, kun oli tehnyt sitä, mikä on pahaa Herran silmissä, vaeltamalla Jerobeamin teitä ja hänen synnissään, jota tämä oli tehnyt ja jolla hän oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Mitä muuta on kerrottavaa Simristä ja salaliitosta, jonka hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Silloin Israelin kansa jakaantui kahtia. Toinen puoli kansaa seurasi Tibniä, Giinatin poikaa, tehdäkseen hänet kuninkaaksi, toinen puoli seurasi Omria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Mutta se osa kansaa, joka seurasi Omria, sai voiton siitä osasta kansaa, joka seurasi Tibniä, Giinatin poikaa. Ja Tibni kuoli, ja Omri tuli kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Juudan kuninkaan Aasan kolmantenakymmenentenä ensimmäisenä hallitusvuotena tuli Omri Israelin kuninkaaksi, ja hän hallitsi kaksitoista vuotta; Tirsassa hän hallitsi kuusi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'Hän osti Samarian vuoren Semeriltä kahdella talentilla hopeata ja rakensi vuorelle kaupungin ja kutsui rakentamansa kaupungin Samariaksi Semerin, vuoren omistajan, nimen mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Ja Omri teki sitä, mikä on pahaa Herran silmissä, teki enemmän pahaa kuin kaikki hänen edeltäjänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Ja hän vaelsi kaikessa Jerobeamin, Nebatin pojan, tietä ja hänen synneissänsä, joilla hän oli saattanut Israelin tekemään syntiä, niin että he vihoittivat Herran, Israelin Jumalan, turhilla jumalillaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Mitä muuta on kerrottavaa Omrista, siitä, mitä hän teki, ja hänen tekemistään urotöistä, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'Omri meni lepoon isiensä tykö, ja hänet haudattiin Samariaan. Ja hänen poikansa Ahab tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Ahab, Omrin poika, tuli Israelin kuninkaaksi Aasan, Juudan kuninkaan, kolmantenakymmenentenä kahdeksantena hallitusvuotena; sitten Ahab, Omrin poika, hallitsi Israelia Samariassa kaksikymmentä kaksi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'Mutta Ahab, Omrin poika, teki sitä, mikä on pahaa Herran silmissä, enemmän kuin kaikki hänen edeltäjänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Ei ollut siinä kylliksi, että hän vaelsi Jerobeamin, Nebatin pojan, synneissä, vaan hän otti myös vaimokseen Iisebelin, siidonilaisten kuninkaan Etbaalin tyttären, ja rupesi palvelemaan Baalia ja kumartamaan sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'Ja hän pystytti alttarin Baalille Baalin temppeliin, jonka hän oli rakentanut Samariaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Ahab teki myös aseran. Ja Ahab teki vielä paljon muuta ja vihoitti Herraa, Israelin Jumalaa, enemmän kuin kukaan niistä Israelin kuninkaista, jotka olivat olleet ennen häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Hänen aikanansa beeteliläinen Hiiel rakensi uudelleen Jerikon. Sen perustuksen laskemisesta hän menetti esikoisensa Abiramin, ja sen ovien pystyttämisestä hän menetti nuorimpansa Segubin, Herran sanan mukaan, jonka hän oli puhunut Joosuan, Nuunin pojan, kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Tisbeläinen Elia, eräs Gileadiin asettuneita siirtolaisia, sanoi Ahabille: \"Niin totta kuin Herra, Israelin Jumala, elää, jonka edessä minä seison: näinä vuosina ei tule kastetta eikä sadetta muutoin kuin minun sanani kautta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'Ja hänelle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, '\"Mene pois täältä ja käänny itään päin ja kätkeydy Keritin purolle, joka on Jordanin itäpuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'Sinä saat juoda purosta, ja minä olen käskenyt kaarneiden elättää sinua siellä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Niin hän meni ja teki Herran sanan mukaan: hän meni ja asettui Keritin purolle, joka on Jordanin itäpuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Ja kaarneet toivat hänelle leipää ja lihaa aamuin sekä leipää ja lihaa illoin, ja hän joi purosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Mutta jonkun ajan kuluttua puro kuivui, koska siinä maassa ei ollut satanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'Ja hänelle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, '\"Nouse ja mene Sarpatiin, joka on Siidonin aluetta, ja asetu sinne. Katso, minä olen käskenyt leskivaimon elättää sinua siellä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Niin hän nousi ja meni Sarpatiin. Ja kun hän tuli kaupungin portille, niin katso, siellä oli leskivaimo keräilemässä puita. Hän huusi tälle ja sanoi: \"Tuo minulle vähän vettä astiassa juodakseni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Kun hän meni hakemaan, huusi hän hänelle ja sanoi: \"Tuo minulle myös palanen leipää kädessäsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Mutta hän vastasi: \"Niin totta kuin Herra, sinun Jumalasi, elää, minulla ei ole leipäkakkuakaan, vaan ainoastaan kourallinen jauhoja ruukussa ja vähän öljyä astiassa. Ja katso, kerättyäni pari puuta minä menen leipomaan itselleni ja pojalleni, syödäksemme ja sitten kuollaksemme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Niin Elia sanoi hänelle: \"Älä pelkää; mene ja tee, niinkuin olet sanonut. Mutta leivo minulle ensin pieni kaltiainen ja tuo se minulle. Leivo sitten itsellesi ja pojallesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Sillä näin sanoo Herra, Israelin Jumala: Jauhot eivät lopu ruukusta, eikä öljyä ole puuttuva astiasta siihen päivään asti, jona Herra antaa sateen maan päälle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'Niin hän meni ja teki, niinkuin Elia oli sanonut. Ja hänellä sekä myös Elialla ja vaimon perheellä oli syötävää pitkäksi aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Jauhot eivät loppuneet ruukusta, eikä öljyä puuttunut astiasta, sen Herran sanan mukaan, jonka hän oli Elian kautta puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Sen jälkeen vaimon, talon emännän, poika sairastui; ja hänen tautinsa kävi hyvin kovaksi, niin ettei hänessä enää ollut henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Silloin vaimo sanoi Elialle: \"Mitä minulla on tekemistä sinun kanssasi, Jumalan mies? Sinä olet tullut minun luokseni saattamaan minun pahat tekoni muistoon ja tuottamaan kuoleman minun pojalleni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'Mutta hän sanoi hänelle: \"Anna poikasi minulle\". Ja hän otti tämän hänen sylistään ja vei hänet yliskammioon, jossa asui, ja pani hänet vuoteellensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'Ja hän huusi Herraa ja sanoi: \"Herra, minun Jumalani, oletko tehnyt niin pahoin tätä leskeä kohtaan, jonka vieraana minä olen, että olet surmannut hänen poikansa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'Sitten hän ojentautui pojan yli kolme kertaa, huusi Herraa ja sanoi: \"Herra, minun Jumalani, anna tämän pojan sielun tulla häneen takaisin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'Ja Herra kuuli Eliaa, ja pojan sielu tuli häneen takaisin, ja hän virkosi henkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Ja Elia otti pojan ja toi hänet yliskammiosta alas huoneeseen ja antoi hänet hänen äidillensä. Ja Elia sanoi: \"Katso, poikasi elää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'Niin vaimo sanoi Elialle: \"Nyt minä tiedän, että sinä olet Jumalan mies ja että Herran sana sinun suussasi on tosi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Pitkän ajan kuluttua, kolmantena vuotena, tuli Elialle tämä Herran sana: \"Mene ja näyttäydy Ahabille, niin minä annan sateen maan päälle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Niin Elia meni näyttäytymään Ahabille. Mutta Samariassa oli kova nälänhätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'Ja Ahab kutsui Obadjan, joka oli palatsin päällikkönä. Mutta Obadja oli hyvin Herraa pelkääväinen mies;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'niinpä Obadja oli silloin, kun Iisebel hävitti Herran profeetat, ottanut sata profeettaa ja piilottanut heidät luolaan, viisikymmentä kerrallaan, ja elättänyt heitä leivällä ja vedellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'Ahab sanoi Obadjalle: \"Kulje maa, kaikki vesilähteet ja kaikki purot. Kenties me löydämme ruohoa pitääksemme hevoset ja muulit hengissä, niin ettei meidän tarvitse hävittää elukoita.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Ja he jakoivat keskenään kuljettavansa maan. Ahab kulki toista tietä yksinänsä, ja Obadja kulki toista tietä yksinänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'Kun nyt Obadja oli matkalla, niin katso, Elia tuli häntä vastaan. Tuntiessaan tämän hän heittäytyi kasvoillensa ja sanoi: \"Sinäkö se olet, herrani Elia?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'Tämä vastasi hänelle: \"Minä. Mene ja sano herrallesi: \'Katso, Elia on täällä\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Niin hän sanoi: \"Mitä minä olen rikkonut, koska annat palvelijasi Ahabin käsiin, hänen surmattavakseen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Niin totta kuin Herra, sinun Jumalasi, elää, ei ole sitä kansaa eikä sitä valtakuntaa, josta minun herrani ei olisi lähettänyt etsimään sinua, mutta kun on vastattu: \'Ei hän ole täällä\', on hän vannottanut sillä valtakunnalla ja sillä kansalla valan, ettei sinua ole löydetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'Ja nyt sinä sanot: \'Mene ja sano herrallesi: Katso, Elia on täällä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Kun minä lähden pois luotasi, niin Herran Henki kuljettaa sinut, en tiedä minne, ja kun minä menen ilmoittamaan Ahabille eikä hän löydä sinua, niin hän tappaa minut. Ja kuitenkin palvelijasi on peljännyt Herraa nuoruudestaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Eikö herralleni ole kerrottu, mitä minä tein, kun Iisebel tappoi Herran profeetat: kuinka minä piilotin luolaan sata Herran profeettaa, viisikymmentä kerrallaan, ja elätin heitä leivällä ja vedellä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'Ja nyt sinä sanot: \'Mene ja sano herrallesi: Katso, Elia on täällä\', ja niin hän tappaa minut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'Mutta Elia sanoi: \"Niin totta kuin Herra Sebaot elää, jonka edessä minä seison, minä näyttäydyn tänä päivänä hänelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Niin Obadja meni Ahabia vastaan ja ilmoitti hänelle tämän. Ahab meni silloin Eliaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'Ja nähdessään Elian Ahab sanoi hänelle: \"Siinäkö sinä olet, sinä, joka syökset Israelin onnettomuuteen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Tämä vastasi: \"En minä syökse Israelia onnettomuuteen, vaan sinä ja sinun isäsi suku, koska te hylkäätte Herran käskyt ja koska sinä seuraat baaleja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Mutta lähetä nyt kokoamaan kaikki Israel minun luokseni Karmel-vuorelle, sekä neljäsataa viisikymmentä Baalin profeettaa ja neljäsataa Aseran profeettaa, jotka syövät Iisebelin pöydästä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Niin Ahab lähetti sanan kaikille israelilaisille ja kokosi profeetat Karmel-vuorelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'Ja Elia astui kaiken kansan eteen ja sanoi: \"Kuinka kauan te onnutte molemmille puolille? Jos Herra on Jumala, seuratkaa häntä; mutta jos Baal on Jumala, seuratkaa häntä.\" Eikä kansa vastannut hänelle mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Niin Elia sanoi kansalle: \"Minä olen ainoa jäljelle jäänyt Herran profeetta, mutta Baalin profeettoja on neljäsataa viisikymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Antakaa meille kaksi mullikkaa, ja valitkoot he itselleen toisen mullikan, paloitelkoot sen ja pankoot kappaleet puiden päälle, mutta älkööt panko tulta; ja minä valmistan toisen mullikan ja asetan sen puiden päälle, mutta en pane tulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Sitten huutakaa te jumalanne nimeä, ja minä huudan Herran nimeä. Se jumala, joka vastaa tulella, on Jumala.\" Kaikki kansa vastasi ja sanoi: \"Niin on hyvä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Ja Elia sanoi Baalin profeetoille: \"Valitkaa itsellenne toinen mullikka ja valmistakaa se ensin, sillä teitä on enemmän. Huutakaa sitten jumalanne nimeä, mutta älkää panko tulta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'Niin he ottivat sen mullikan, jonka hän antoi heille, ja valmistivat sen. Sitten he huusivat Baalin nimeä aamusta puolipäivään asti, sanoen: \"Baal, vastaa meille!\" Mutta ei ääntä, ei vastausta! Ja he hyppelivät alttarin ääressä, joka oli tehty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'Puolipäivän aikana Elia pilkkasi heitä ja sanoi: \"Huutakaa kovemmin; hän on tosin jumala, mutta hänellä voi olla jotakin toimittamista, tahi hän on poistunut johonkin, tahi on matkalla; kenties hän nukkuu, mutta kyllä hän herää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'Niin he huusivat vielä kovemmin ja viileksivät itseään tapansa mukaan miekoilla ja keihäillä, niin että heistä vuoti verta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'Kun puolipäivä oli kulunut, joutuivat he hurmoksiin, aina siihen hetkeen asti, jolloin ruokauhri uhrataan. Mutta ei ääntä, ei vastausta, ei vaarinottoa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Niin Elia sanoi kaikelle kansalle: \"Astukaa minun luokseni\". Ja kaikki kansa astui hänen luoksensa. Niin hän korjasi Herran alttarin, joka oli hajotettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Ja Elia otti kaksitoista kiveä, yhtä monta kuin oli Jaakobin poikien sukukuntia, hänen, jolle oli tullut tämä Herran sana: \"Israel on oleva sinun nimesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'Ja hän rakensi kivistä alttarin Herran nimeen ja teki alttarin ympärille ojan, johon olisi mahtunut kaksi sea-mittaa jyviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Sitten hän latoi puut, paloitteli mullikan ja pani kappaleet puiden päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'Ja hän sanoi: \"Täyttäkää neljä ruukkua vedellä ja vuodattakaa se polttouhrin ja puiden päälle\". Ja hän sanoi: \"Tehkää se toinen kerta\". Ja he tekivät niin toisen kerran. Vielä hän sanoi: \"Tehkää se kolmas kerta\". Ja he tekivät niin kolmannen kerran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Niin vesi juoksi ympäri alttarin; ojankin hän täytti vedellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'Ja kun oli tullut hetki, jolloin ruokauhri uhrataan, astui profeetta Elia esille ja sanoi: \"Herra, Aabrahamin, Iisakin ja Israelin Jumala, tulkoon tänä päivänä tiettäväksi, että sinä olet Jumala Israelissa ja että minä olen sinun palvelijasi ja että minä olen sinun käskystäsi tehnyt kaiken tämän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Vastaa minulle, Herra, vastaa minulle, että tämä kansa tulisi näkemään, että sinä, Herra, olet Jumala ja että sinä käännät heidän sydämensä takaisin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Silloin Herran tuli iski alas ja kulutti polttouhrin, puut, kivet ja mullan sekä nuoli veden, joka oli ojassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Kun kaikki kansa näki tämän, lankesivat he kasvoillensa ja sanoivat: \"Herra on Jumala! Herra on Jumala!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Mutta Elia sanoi heille: \"Ottakaa Baalin profeetat kiinni; älköön yksikään heistä pääskö pakoon\". Ja he ottivat heidät kiinni. Ja Elia vei heidät Kiisonin purolle ja tappoi heidät siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Ja Elia sanoi Ahabille: \"Nouse, syö ja juo, sillä sateen kohina kuuluu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Niin Ahab nousi syömään ja juomaan. Mutta Elia nousi Karmelin huipulle, kumartui maahan ja painoi kasvonsa polviensa väliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Ja hän sanoi palvelijallensa: \"Nouse ja katso merelle päin\". Tämä nousi ja katsoi, mutta sanoi: \"Ei näy mitään\". Hän sanoi: \"Mene takaisin\". Näin seitsemän kertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'Seitsemännellä kerralla palvelija sanoi: \"Katso, pieni pilvi, miehen kämmenen kokoinen, nousee merestä\". Niin Elia sanoi: \"Nouse ja sano Ahabille: \'Valjasta ja lähde alas, ettei sade sinua pidättäisi\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'Ja tuossa tuokiossa taivas kävi mustaksi pilvistä ja myrskytuulesta, ja tuli ankara sade. Mutta Ahab nousi vaunuihinsa ja lähti Jisreeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Ja Herran käsi tuli Elian päälle, ja niin hän vyötti kupeensa ja juoksi Ahabin edellä Jisreeliin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Mutta kun Ahab kertoi Iisebelille kaiken, mitä Elia oli tehnyt ja kuinka hän oli tappanut miekalla kaikki profeetat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'lähetti Iisebel sanansaattajan Elian luo ja käski sanoa: \"Jumalat rangaiskoot minua nyt ja vasta, jollen minä huomenna tähän aikaan tee sinulle samaa, mikä jokaiselle näistä on tehty\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Kun tämä näki sen, nousi hän ja lähti matkaan pelastaakseen henkensä ja tuli Beersebaan, joka on Juudan aluetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Sinne hän jätti palvelijansa, mutta meni itse erämaahan päivänmatkan päähän. Hän tuli ja istuutui kinsteripensaan juureen. Ja hän toivotti itsellensä kuolemaa ja sanoi: \"Jo riittää, Herra; ota minun henkeni, sillä minä en ole isiäni parempi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'Ja hän paneutui maata ja nukkui kinsteripensaan juurelle. Mutta katso, enkeli kosketti häntä ja sanoi hänelle: \"Nouse ja syö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'Ja kun hän katsahti, niin katso, hänen päänsä pohjissa oli kuumennetuilla kivillä paistettu kaltiainen ja vesiastia. Niin hän söi ja joi ja paneutui jälleen maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Mutta Herran enkeli kosketti häntä vielä toisen kerran ja sanoi: \"Nouse ja syö, sillä muutoin käy matka sinulle liian pitkäksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'Niin hän nousi ja söi ja joi. Ja hän kulki sen ruuan voimalla neljäkymmentä päivää ja neljäkymmentä yötä Jumalan vuorelle, Hoorebille, asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'Siellä hän meni luolaan ja oli siinä yötä. Ja katso, Herran sana tuli hänelle; hän kysyi häneltä: \"Mitä sinä täällä teet, Elia?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Hän vastasi: \"Minä olen kiivailemalla kiivaillut Herran, Jumalan Sebaotin, puolesta. Sillä israelilaiset ovat hyljänneet sinun liittosi, hajottaneet sinun alttarisi ja tappaneet miekalla sinun profeettasi. Minä yksin olen jäänyt jäljelle, mutta minunkin henkeäni he väijyvät, ottaaksensa sen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Hän sanoi: \"Mene ulos ja asetu vuorelle Herran eteen\". Ja katso, Herra kulki ohitse, ja suuri ja raju myrsky, joka halkoi vuoret ja särki kalliot, kävi Herran edellä; mutta ei Herra ollut myrskyssä. Myrskyn jälkeen tuli maanjäristys; mutta ei Herra ollut maanjäristyksessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Maanjäristyksen jälkeen tuli tulta; mutta ei Herra ollut tulessa. Tulen jälkeen tuli hiljainen tuulen hyminä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Kun Elia sen kuuli, peitti hän kasvonsa vaipallansa, meni ulos ja asettui luolan suulle. Ja katso, hänelle puhui ääni ja sanoi: \"Mitä sinä täällä teet, Elia?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'Hän vastasi: \"Minä olen kiivailemalla kiivaillut Herran, Jumalan Sebaotin, puolesta. Sillä israelilaiset ovat hyljänneet sinun liittosi, hajottaneet sinun alttarisi ja tappaneet miekalla sinun profeettasi. Minä yksin olen jäänyt jäljelle, mutta minunkin henkeäni he väijyvät, ottaaksensa sen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Herra sanoi hänelle: \"Lähde takaisin samaa tietä, jota tulit, erämaan kautta Damaskoon. Mene ja voitele Hasael Aramin kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Ja voitele Jeehu, Nimsin poika, Israelin kuninkaaksi. Ja voitele sijaasi profeetaksi Elisa, Saafatin poika, Aabel-Meholasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'Ja on tapahtuva näin: joka välttää Hasaelin miekan, sen surmaa Jeehu, ja joka välttää Jeehun miekan, sen surmaa Elisa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Mutta minä jätän jäljelle Israeliin seitsemäntuhatta: kaikki polvet, jotka eivät ole notkistuneet Baalille, ja kaikki suut, jotka eivät ole hänelle suuta antaneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'Niin hän lähti sieltä ja kohtasi Elisan, Saafatin pojan, kun tämä oli kyntämässä; kaksitoista härkäparia kulki hänen edellänsä, ja itse hän ajoi kahdettatoista. Kulkiessaan hänen ohitsensa Elia heitti vaippansa hänen päällensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Niin hän jätti härät, riensi Elian jälkeen ja sanoi: \"Salli minun ensin antaa suuta isälleni ja äidilleni; sitten minä seuraan sinua\". Elia sanoi hänelle: \"Mene, mutta tule takaisin; tiedäthän, mitä minä olen sinulle tehnyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'Niin hän meni hänen luotaan takaisin, otti härkäparinsa ja teurasti sen, ja härkäin ikeellä hän keitti lihat; ne hän antoi väelle, ja he söivät. Sitten hän nousi ja seurasi Eliaa ja palveli häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Ja Benhadad, Aramin kuningas, kokosi kaiken sotajoukkonsa. Hänellä oli mukanaan kolmekymmentä kaksi kuningasta sekä hevosia ja sotavaunuja. Ja hän meni ja piiritti Samariaa ja ryhtyi taisteluun sitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'Ja hän lähetti sanansaattajat kaupunkiin Ahabin, Israelin kuninkaan, luo');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'ja käski sanoa hänelle: \"Näin sanoo Benhadad: \'Sinun hopeasi ja kultasi ovat minun, ja sinun kauneimmat vaimosi ja lapsesi ovat myöskin minun\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Israelin kuningas vastasi ja sanoi: \"Niinkuin sinä olet sanonut, herrani, kuningas, minä olen sinun, minä ja kaikki, mitä minulla on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'Mutta sanansaattajat tulivat takaisin ja sanoivat: \"Näin sanoo Benhadad: \'Minä olen lähettänyt sinulle tämän sanan: Anna minulle hopeasi ja kultasi, vaimosi ja lapsesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Totisesti minä lähetän huomenna tähän aikaan palvelijani sinun luoksesi tutkimaan sinun taloasi ja sinun palvelijaisi taloja; ja kaiken, mikä on sinun silmiesi ihastus, he ottavat haltuunsa ja vievät.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Silloin Israelin kuningas kutsui kaikki maan vanhimmat ja sanoi: \"Ymmärtäkää ja nähkää, että hän hankkii meille onnettomuutta; sillä kun hän lähetti vaatimaan minulta vaimojani ja lapsiani, hopeatani ja kultaani, en minä niitä häneltä kieltänyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'Kaikki vanhimmat ja kaikki kansa sanoivat hänelle: \"Älä kuule häntä äläkä suostu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Niin hän sanoi Benhadadin sanansaattajille: \"Sanokaa herralleni, kuninkaalle: \'Kaiken, mitä sinä ensi kerralla käskit palvelijasi tehdä, minä teen; mutta tätä minä en voi tehdä\'\". Ja sanansaattajat menivät ja veivät tämän vastauksen hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Niin Benhadad lähetti hänelle sanan: \"Jumalat rangaiskoot minua nyt ja vasta, jos Samarian tomu riittää täyttämään kaiken sen väen kourat, joka minua seuraa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Mutta Israelin kuningas vastasi ja sanoi: \"Sanokaa hänelle: \'Älköön se, joka vyöttäytyy miekkaan, kerskatko niinkuin se, joka sen riisuu\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'Kun hän, juodessaan kuninkaitten kanssa lehtimajoissa, kuuli tämän vastauksen, sanoi hän palvelijoilleen: \"Piiritys käyntiin!\" Ja he panivat piirityksen käyntiin kaupunkia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'Ja katso, eräs profeetta astui Ahabin, Israelin kuninkaan, eteen ja sanoi: \"Näin sanoo Herra: Näetkö kaiken tuon suuren lauman? Katso, minä annan sen tänä päivänä sinun käsiisi, että sinä tulisit tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Ahab kysyi: \"Kenen avulla?\" Hän vastasi: \"Näin sanoo Herra: Maaherrain palvelijoitten avulla\". Ahab kysyi vielä: \"Kuka alottaa taistelun?\" Hän vastasi: \"Sinä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Niin hän katsasti herrain palvelijat, ja niitä oli kaksisataa kolmekymmentä kaksi. Niitten jälkeen hän katsasti kaiken väen, kaikki israelilaiset, joita oli seitsemäntuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'Ja he tekivät hyökkäyksen puolenpäivän aikana, kun Benhadad oli juovuksissa ja joi lehtimajoissa, hän ja ne kolmekymmentä kaksi kuningasta, jotka olivat tulleet hänen avuksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'Maaherrain palvelijat hyökkäsivät ensimmäisinä. Silloin Benhadad lähetti tiedustelemaan, ja hänelle ilmoitettiin: \"Miehiä on lähtenyt liikkeelle Samariasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'Hän sanoi: \"Jos he ovat lähteneet liikkeelle rauha mielessä, niin ottakaa heidät kiinni elävinä; ja jos he ovat lähteneet taistellakseen, ottakaa heidät silloinkin kiinni elävinä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Mutta kun maaherrain palvelijat ja sotajoukko, joka seurasi heitä, olivat hyökänneet kaupungista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'surmasivat he miehen kukin. Niin aramilaiset pakenivat, ja Israel ajoi heitä takaa. Mutta Benhadad, Aramin kuningas, pääsi muutamien ratsumiesten kanssa pakoon hevosen selässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Mutta Israelin kuningas lähti liikkeelle ja valtasi hevoset ja sotavaunut; ja niin hän tuotti aramilaisille suuren tappion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Ja profeetta astui Israelin kuninkaan eteen ja sanoi hänelle: \"Vahvista itsesi, ymmärrä ja katso, mitä sinun on tehtävä, sillä vuoden vaihteessa hyökkää Aramin kuningas sinun kimppuusi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Aramin kuninkaan palvelijat sanoivat tälle: \"Heidän jumalansa on vuorijumala; sentähden he saivat meistä voiton. Mutta taistelkaamme heitä vastaan tasangolla, silloin me varmasti saamme heistä voiton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Ja tee näin: Pane pois kuninkaat, kukin paikaltaan, ja aseta käskynhaltijat heidän sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'Hanki sitten itsellesi sotajoukko, yhtä suuri kuin menettämäsi oli, yhtä monta hevosta ja yhtä monet sotavaunut; ja taistelkaamme heitä vastaan tasangolla, niin me varmasti saamme heistä voiton.\" Niin hän kuuli heitä ja teki niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'Vuoden vaihteessa Benhadad katsasti aramilaiset ja lähti Afekiin taistelemaan Israelia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Ja israelilaiset katsastettiin ja muonitettiin, ja he lähtivät heitä vastaan. Israelilaiset leiriytyivät heidän eteensä niinkuin kaksi pientä vuohilaumaa, mutta aramilaiset täyttivät maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Silloin Jumalan mies astui Israelin kuninkaan eteen ja sanoi: \"Näin sanoo Herra: Sentähden, että aramilaiset ovat sanoneet: \'Herra on vuorijumala eikä laaksojumala\', annan minä koko tämän suuren lauman sinun käsiisi, tullaksenne tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'Ja he olivat leiriytyneinä vastakkain seitsemän päivää. Seitsemäntenä päivänä sukeutui taistelu, ja israelilaiset surmasivat aramilaisia satatuhatta jalkamiestä yhtenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Jäljellejääneet pakenivat Afekiin, kaupunkiin. Ja muuri kaatui kahdenkymmenen seitsemän tuhannen jäljellejääneen miehen päälle. Mutta Benhadad pakeni, tuli kaupunkiin ja juoksi huoneesta huoneeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Silloin hänen palvelijansa sanoivat hänelle: \"Katso, me olemme kuulleet, että Israelin heimon kuninkaat ovat laupiaita kuninkaita. Pankaamme säkit lanteillemme ja nuorat päämme ympärille ja antautukaamme Israelin kuninkaalle; ehkä hän jättää sinut henkiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Ja he käärivät säkit lanteilleen ja panivat nuorat päänsä ympärille ja tulivat Israelin kuninkaan luo ja sanoivat: \"Palvelijasi Benhadad sanoo: \'Salli minun elää\'.\" Hän sanoi: \"Vieläkö hän elää? Hän on minun veljeni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'Niin miehet katsoivat sen hyväksi enteeksi, tarttuivat kiiruusti hänen sanaansa ja sanoivat: \"Benhadad on sinun veljesi\". Hän sanoi: \"Menkää ja noutakaa hänet\". Silloin Benhadad antautui hänelle, ja hän antoi hänen nousta vaunuihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'Ja Benhadad sanoi hänelle: \"Kaupungit, jotka minun isäni otti sinun isältäsi, minä annan takaisin. Laita itsellesi katumyymälöitä Damaskoon, niinkuin minun isäni laittoi Samariaan.\" Ahab vastasi: \"Minä päästän sinut menemään sillä välipuheella\". Ja hän teki liiton hänen kanssaan ja päästi hänet menemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Silloin eräs profeetanoppilaista sanoi Herran käskystä toverilleen: \"Lyö minua\". Mutta mies ei tahtonut lyödä häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Niin hän sanoi tälle: \"Koska et kuullut Herran ääntä, niin katso, leijona surmaa sinut, kun lähdet minun luotani\". Ja kun hän lähti hänen luotansa, kohtasi leijona hänet ja surmasi hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Sitten hän tapasi toisen miehen ja sanoi: \"Lyö minua\". Ja mies löi hänet haavoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Niin profeetta meni ja asettui tielle, jota kuninkaan oli kuljettava, ja teki itsensä tuntemattomaksi panemalla siteen silmilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'Kun kuningas kulki ohitse, huusi hän kuninkaalle ja sanoi: \"Palvelijasi oli lähtenyt keskelle taistelua; ja katso, sieltä tuli mies ja toi toisen miehen minun luokseni ja sanoi: \'Vartioitse tätä miestä. Jos hän katoaa, menee sinun henkesi hänen hengestään, tahi sinä maksat talentin hopeata.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Palvelijallasi oli tehtävää siellä ja täällä, ja sitten ei miestä enää ollut.\" Israelin kuningas sanoi hänelle: \"Tuomiosi on siis se; sinä olet itse julistanut sen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Silloin hän nopeasti poisti siteen silmiltään, ja Israelin kuningas tunsi hänet, että hän oli profeettoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Ja tämä sanoi hänelle: \"Näin sanoo Herra: Koska sinä päästit käsistäsi menemään minulle tuhon omaksi vihityn miehen, menee sinun henkesi hänen hengestänsä ja sinun kansasi hänen kansastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Niin Israelin kuningas meni kotiinsa pahastuneena ja alakuloisena ja tuli Samariaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'Näiden tapausten jälkeen tapahtui tämä. Jisreeliläisellä Naabotilla oli viinitarha, joka oli Jisreelissä Samarian kuninkaan Ahabin palatsin vieressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'Ja Ahab puhui Naabotille sanoen: \"Anna minulle viinitarhasi vihannestarhaksi, koska se on niin likellä minun linnaani; minä annan sinulle sen sijaan paremman viinitarhan, tahi, jos niin tahdot, minä annan sinulle sen hinnan rahana\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Mutta Naabot vastasi Ahabille: \"Pois se, Herra varjelkoon minua antamasta sinulle isieni perintöosaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Niin Ahab tuli kotiinsa pahastuneena ja alakuloisena vastauksesta, jonka jisreeliläinen Naabot oli hänelle antanut, kun tämä oli sanonut: \"En minä anna sinulle isieni perintöosaa\". Ja hän pani maata vuoteellensa, käänsi kasvonsa pois eikä syönyt mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Niin hänen vaimonsa Iisebel tuli hänen luokseen ja puhui hänelle: \"Miksi olet niin pahoilla mielin ja miksi et syö mitään?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'Ahab vastasi hänelle: \"Siksi, että puhuttelin jisreeliläistä Naabotia ja sanoin hänelle: \'Anna minulle viinitarhasi rahasta, tahi jos haluat, annan minä sinulle toisen viinitarhan sen sijaan\', mutta hän vastasi: \'En minä anna sinulle viinitarhaani\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Niin hänen vaimonsa Iisebel sanoi hänelle: \"Sinäkö olet käyttävinäsi kuninkaanvaltaa Israelissa? Nouse ja syö, ja olkoon sydämesi iloinen; minä kyllä toimitan sinulle jisreeliläisen Naabotin viinitarhan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Ja hän kirjoitti kirjeen Ahabin nimessä, sinetöi sen hänen sinetillään ja lähetti kirjeen vanhimmille ja ylimyksille, jotka olivat Naabotin kaupungissa ja asuivat siellä hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'Ja kirjeessä hän kirjoitti näin: \"Kuuluttakaa paasto ja asettakaa Naabot istumaan etumaiseksi kansan joukkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'Ja asettakaa kaksi kelvotonta miestä istumaan häntä vastapäätä, että he todistaisivat hänestä näin: \'Sinä olet kironnut Jumalaa ja kuningasta\'. Viekää hänet sitten ulos ja kivittäkää hänet kuoliaaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'Ja kaupungin miehet, vanhimmat ja ylimykset, jotka asuivat hänen kaupungissansa, tekivät, niinkuin Iisebel oli käskenyt heitä ja niinkuin oli kirjoitettu kirjeessä, jonka hän oli heille lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'He kuuluttivat paaston ja asettivat Naabotin istumaan etumaiseksi kansan joukkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Ja kaksi kelvotonta miestä tuli ja istui häntä vastapäätä. Ja ne kelvottomat miehet todistivat Naabotista kansan edessä sanoen: \"Naabot on kironnut Jumalaa ja kuningasta\". Silloin he veivät hänet kaupungin ulkopuolelle ja kivittivät hänet kuoliaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Sitten he lähettivät Iisebelille tämän sanan: \"Naabot on kivitetty kuoliaaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'Kun Iisebel kuuli, että Naabot oli kivitetty kuoliaaksi, sanoi Iisebel Ahabille: \"Nouse ja ota haltuusi jisreeliläisen Naabotin viinitarha, jota hän ei tahtonut antaa sinulle rahasta; sillä Naabot ei ole enää elossa, vaan on kuollut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'Kun Ahab kuuli, että Naabot oli kuollut, nousi hän ja lähti jisreeliläisen Naabotin viinitarhalle ottaakseen sen haltuunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Mutta tisbeläiselle Elialle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '\"Nouse ja mene tapaamaan Ahabia, Israelin kuningasta, joka asuu Samariassa. Katso, hän on Naabotin viinitarhassa, jota hän on mennyt ottamaan haltuunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'Ja puhu hänelle ja sano: \'Näin sanoo Herra: Oletko sinä sekä tappanut että anastanut perinnön?\' Ja puhu sitten hänelle ja sano: \'Näin sanoo Herra: Siinä paikassa, missä koirat nuoleskelivat Naabotin veren, tulevat koirat nuoleskelemaan sinunkin veresi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'Ahab sanoi Elialle: \"Joko löysit minut, sinä vihamieheni?\" Hän vastasi: \"Jo löysin. Koska sinä olet myynyt itsesi tekemään sitä, mikä on pahaa Herran silmissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'niin katso, minä annan onnettomuuden kohdata sinua ja lakaisen sinut pois ja hävitän Israelista Ahabin miespuoliset jälkeläiset, kaikki tyynni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'Ja minä teen sinun suvullesi niinkuin Jerobeamin, Nebatin pojan, suvulle ja niinkuin Baesan, Ahian pojan, suvulle, koska sinä olet vihoittanut minut ja saattanut Israelin tekemään syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Myöskin Iisebelistä on Herra puhunut sanoen: Koirat syövät Iisebelin Jisreelin muurin luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Joka Ahabin jälkeläisistä kuolee kaupungissa, sen koirat syövät, ja joka kuolee kedolle, sen syövät taivaan linnut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Totisesti ei ole ollut ketään, joka olisi niin myynyt itsensä tekemään sitä, mikä on pahaa Herran silmissä, kuin Ahab, kun hänen vaimonsa Iisebel vietteli häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Hän teki ylen kauhistavasti, kun lähti seuraamaan kivijumalia, aivan niinkuin amorilaiset tekivät, jotka Herra karkoitti israelilaisten tieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'Mutta kun Ahab kuuli nämä sanat, repäisi hän vaatteensa, pani paljaalle iholleen säkin ja paastosi. Ja hän makasi säkki yllänsä ja liikkui hiljaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Niin tisbeläiselle Elialle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '\"Oletko nähnyt, kuinka Ahab on nöyrtynyt minun edessäni? Koska hän on nöyrtynyt minun edessäni, en minä anna onnettomuuden tulla hänen aikanansa: hänen poikansa aikana minä annan onnettomuuden kohdata hänen sukuansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'He olivat alallaan kolme vuotta: ei ollut sotaa Aramin ja Israelin välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'Mutta kolmantena vuotena tuli Joosafat, Juudan kuningas, Israelin kuninkaan luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Ja Israelin kuningas sanoi palvelijoillensa: \"Tiedättehän, että Gileadin Raamot on meidän. Ja kuitenkin me olemme toimettomat emmekä ota sitä pois Aramin kuninkaan käsistä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Ja hän sanoi Joosafatille: \"Lähdetkö sinä minun kanssani sotaan Gileadin Raamotiin?\" Joosafat vastasi Israelin kuninkaalle: \"Minä niinkuin sinä, minun kansani niinkuin sinun kansasi, minun hevoseni niinkuin sinun hevosesi!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Mutta Joosafat sanoi Israelin kuninkaalle: \"Kysy kuitenkin ensin, mitä Herra sanoo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Niin Israelin kuningas kokosi profeetat, noin neljäsataa miestä, ja sanoi heille: \"Onko minun lähdettävä sotaan Gileadin Raamotia vastaan vai oltava lähtemättä?\" He vastasivat: \"Lähde; Herra antaa sen kuninkaan käsiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Mutta Joosafat sanoi: \"Eikö täällä ole enää ketään muuta Herran profeettaa, jolta voisimme kysyä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'Israelin kuningas vastasi Joosafatille: \"On täällä vielä mies, jolta voisimme kysyä Herran mieltä, mutta minä vihaan häntä, sillä hän ei koskaan ennusta minulle hyvää, vaan aina pahaa; se on Miika, Jimlan poika\". Joosafat sanoi: \"Älköön kuningas niin puhuko\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Niin Israelin kuningas kutsui erään hoviherran ja sanoi: \"Nouda kiiruusti Miika, Jimlan poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Mutta Israelin kuningas ja Joosafat, Juudan kuningas, istuivat kumpikin valtaistuimellansa, puettuina kuninkaallisiin pukuihinsa, puimatantereella Samarian portin ovella; ja kaikki profeetat olivat hurmoksissa heidän edessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'Ja Sidkia, Kenaanan poika, teki itsellensä rautasarvet ja sanoi: \"Näin sanoo Herra: Näillä sinä pusket aramilaisia, kunnes teet heistä lopun\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Ja kaikki profeetat ennustivat samalla tavalla, sanoen: \"Mene Gileadin Raamotiin, niin sinä saat voiton; Herra antaa sen kuninkaan käsiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Ja sanansaattaja, joka oli mennyt kutsumaan Miikaa, puhui hänelle sanoen: \"Katso, kaikki profeetat ovat yhdestä suusta luvanneet kuninkaalle hyvää; olkoon sinun sanasi heidän sanansa kaltainen, ja lupaa sinäkin hyvää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'Mutta Miika vastasi: \"Niin totta kuin Herra elää, sen minä puhun, minkä Herra minulle sanoo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'Kun hän tuli kuninkaan eteen, sanoi kuningas hänelle: \"Miika, onko meidän lähdettävä sotaan Gileadin Raamotiin vai oltava lähtemättä?\" Hän vastasi hänelle: \"Lähde, niin saat voiton; Herra antaa sen kuninkaan käsiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Mutta kuningas sanoi hänelle: \"Kuinka monta kertaa minun on vannotettava sinua, ettet puhu minulle muuta kuin totuutta Herran nimessä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Silloin hän sanoi: \"Minä näin koko Israelin hajallaan vuorilla niinkuin lampaat, joilla ei ole paimenta. Ja Herra sanoi: \'Näillä ei ole isäntää; palatkoot he kukin rauhassa kotiinsa\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Niin Israelin kuningas sanoi Joosafatille: \"Enkö minä sanonut sinulle, ettei tämä koskaan ennusta minulle hyvää, vaan aina pahaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'Mutta hän sanoi: \"Kuule siis Herran sana: Minä näin Herran istuvan istuimellansa ja kaiken taivaan joukon seisovan hänen edessään, hänen oikealla ja vasemmalla puolellansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'Ja Herra sanoi: \'Kuka viekoittelisi Ahabin lähtemään sotaan, että hän kaatuisi Gileadin Raamotissa?\' Mikä vastasi niin, mikä näin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Silloin tuli henki ja asettui Herran eteen ja sanoi: \'Minä viekoittelen hänet\'. Herra kysyi häneltä: \'Miten?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Hän vastasi: \'Minä menen valheen hengeksi kaikkien hänen profeettainsa suuhun\'. Silloin Herra sanoi: \'Saat viekoitella, siihen sinä pystyt; mene ja tee niin\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Katso, nyt Herra on pannut valheen hengen kaikkien näiden sinun profeettaisi suuhun, sillä Herra on päättänyt sinun osaksesi onnettomuuden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Silloin astui esille Sidkia, Kenaanan poika, löi Miikaa poskelle ja sanoi: \"Mitä tietä Herran henki on poistunut minusta puhuakseen sinun kanssasi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Miika vastasi: \"Sen saat nähdä sinä päivänä, jona kuljet huoneesta huoneeseen piiloutuaksesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Mutta Israelin kuningas sanoi: \"Ota Miika ja vie hänet takaisin Aamonin, kaupungin päällikön, ja Jooaan, kuninkaan pojan, luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'Ja sano: \'Näin sanoo kuningas: Pankaa tämä vankilaan ja elättäkää häntä vaivaisella vedellä ja leivällä, kunnes minä palaan voittajana takaisin\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Miika vastasi: \"Jos sinä palaat voittajana takaisin, niin ei Herra ole puhunut minun kauttani\". Ja hän sanoi vielä: \"Kuulkaa tämä, kaikki kansat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Niin Israelin kuningas ja Joosafat, Juudan kuningas, menivät Gileadin Raamotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'Ja Israelin kuningas sanoi Joosafatille: \"Täytyypä pukeutua tuntemattomaksi, kun käy taisteluun, mutta ole sinä omissa vaatteissasi\". Ja Israelin kuningas pukeutui tuntemattomaksi ja kävi taisteluun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Mutta Aramin kuningas oli käskenyt sotavaunujen päälliköitä, joita hänellä oli kolmekymmentä kaksi, sanoen: \"Älkää ryhtykö taisteluun kenenkään muun kanssa, olkoon alempi tai ylempi, kuin ainoastaan Israelin kuninkaan kanssa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Kun sotavaunujen päälliköt näkivät Joosafatin, ajattelivat he: \"Tuo on varmaankin Israelin kuningas\", ja kääntyivät hyökkäämään häntä vastaan. Silloin Joosafat huusi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Kun sotavaunujen päälliköt näkivät, ettei se ollutkaan Israelin kuningas, vetäytyivät he hänestä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Mutta eräs mies, joka oli jännittänyt jousensa ja ampui umpimähkään, satutti Israelin kuningasta vyöpanssarin ja rintahaarniskan väliin. Niin tämä sanoi vaunujensa ohjaajalle: \"Käännä vaunut ja vie minut pois sotarinnasta, sillä minä olen haavoittunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'Mutta kun taistelu sinä päivänä yltyi yltymistään, jäi kuningas seisomaan vaunuihinsa, päin aramilaisia. Illalla hän kuoli; ja verta oli vuotanut haavasta vaununpohjaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Ja auringon laskiessa kaikui kautta sotajoukon huuto: \"Joka mies kaupunkiinsa! Joka mies maahansa!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'Näin kuoli kuningas, ja hänet vietiin Samariaan; ja kuningas haudattiin Samariaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'Ja kun vaunut huuhdottiin Samarian lammikolla, nuoleskelivat koirat hänen vertansa, ja portot peseytyivät siinä, sen sanan mukaan, jonka Herra oli puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'Mitä muuta on kerrottavaa Ahabista ja kaikesta, mitä hän teki, siitä norsunluisesta palatsista, jonka hän rakensi, ja kaikista kaupungeista, jotka hän linnoitti, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Ja niin Ahab meni lepoon isiensä tykö. Ja hänen poikansa Ahasja tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'Joosafat, Aasan poika, tuli Juudan kuninkaaksi Ahabin, Israelin kuninkaan, neljäntenä hallitusvuotena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Joosafat oli kolmenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi kaksikymmentä viisi vuotta Jerusalemissa. Hänen äitinsä oli nimeltään Asuba, Silhin tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'Ja hän vaelsi kaikessa isänsä Aasan tietä, siltä poikkeamatta, ja teki sitä, mikä oli oikein Herran silmissä. {22:44} Mutta uhrikukkulat eivät hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, '{22:45} Ja Joosafat teki rauhan Israelin kuninkaan kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, '{22:46} Mitä muuta on kerrottavaa Joosafatista, hänen urotöistään ja hänen sodistaan, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, '{22:47} Hän hävitti maasta viimeiset niistä haureellisista pyhäkköpojista, jotka olivat jääneet jäljelle hänen isänsä Aasan ajoilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, '{22:48} Edomissa ei siihen aikaan ollut kuningasta; maaherra oli kuninkaana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, '{22:49} Ja Joosafat oli teettänyt Tarsiin-laivoja, joiden oli määrä kulkea Oofiriin kultaa noutamaan; mutta laivat eivät päässeet lähtemään, sillä ne särkyivät Esjon-Geberissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, '{22:50} Silloin Ahasja, Ahabin poika, sanoi Joosafatille: \"Anna minun palvelijaini kulkea sinun palvelijaisi kanssa laivoissa\". Mutta Joosafat ei tahtonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, '{22:51} Ja Joosafat meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen hänen isänsä Daavidin kaupunkiin. Ja hänen poikansa Jooram tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, '{22:52} Ahasja, Ahabin poika, tuli Israelin kuninkaaksi Samariassa Joosafatin, Juudan kuninkaan, seitsemäntenätoista hallitusvuotena, ja hän hallitsi Israelia kaksi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, '{22:53} Hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi isänsä ja äitinsä tietä ja Jerobeamin, Nebatin pojan, tietä, hänen, joka oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, '{22:54} Hän palveli Baalia ja kumarsi häntä ja vihoitti Herran, Israelin Jumalan, aivan niinkuin hänen isänsä oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'Ahabin kuoleman jälkeen Mooab luopui Israelista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'Ahasja putosi Samariassa yläsalinsa ristikon läpi ja makasi sairaana. Ja hän lähetti sanansaattajia ja sanoi heille: \"Menkää ja kysykää Baal-Sebubilta, Ekronin jumalalta, toivunko minä tästä taudista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Mutta Herran enkeli oli sanonut tisbeläiselle Elialle: \"Nouse ja mene Samarian kuninkaan sanansaattajia vastaan ja sano heille: \'Eikö ole Jumalaa Israelissa, koska menette kysymään neuvoa Baal-Sebubilta, Ekronin jumalalta?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Sentähden sanoo Herra näin: \'Vuoteesta, johon olet noussut, et sinä enää astu alas, sillä sinun on kuoltava\'.\" Ja Elia lähti tiehensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'Kun sanansaattajat sitten palasivat kuninkaan luo, kysyi hän heiltä: \"Minkätähden te tulette takaisin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'He vastasivat hänelle: \"Meitä vastaan tuli mies, joka sanoi meille: \'Menkää takaisin kuninkaan luo, joka on teidät lähettänyt, ja sanokaa hänelle: Näin sanoo Herra: Eikö ole Jumalaa Israelissa, koska sinä lähetät kysymään neuvoa Baal-Sebubilta, Ekronin jumalalta? Sentähden sinä et enää astu alas vuoteesta, johon olet noussut, sillä sinun on kuoltava.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'Hän kysyi heiltä: \"Minkä näköinen oli mies, joka tuli teitä vastaan ja puhui teille näitä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'He vastasivat hänelle: \"Hänellä oli yllään karvanahka ja nahkavyö vyötäisillä\". Silloin hän sanoi: \"Se oli tisbeläinen Elia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Ja hän lähetti hänen luokseen viidenkymmenenpäämiehen ja hänen viisikymmentä miestänsä. Ja kun tämä tuli hänen luoksensa, hänen istuessaan vuoren kukkulalla, sanoi hän hänelle: \"Sinä Jumalan mies, kuningas käskee: Tule alas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'Mutta Elia vastasi ja sanoi viidenkymmenenpäämiehelle: \"Jos minä olen Jumalan mies, niin tulkoon tuli taivaasta ja kuluttakoon sinut ja sinun viisikymmentä miestäsi\". Silloin tuli taivaasta tuli ja kulutti hänet ja hänen viisikymmentä miestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Hän lähetti taas hänen luoksensa toisen viidenkymmenenpäämiehen ja hänen viisikymmentä miestänsä. Tämä lausui ja sanoi hänelle: \"Sinä Jumalan mies, näin käskee kuningas: Tule kiiruusti alas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'Mutta Elia vastasi ja sanoi heille: \"Jos minä olen Jumalan mies, niin tulkoon tuli taivaasta ja kuluttakoon sinut ja sinun viisikymmentä miestäsi\". Silloin tuli taivaasta Jumalan tuli ja kulutti hänet ja hänen viisikymmentä miestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Hän lähetti vielä kolmannen viidenkymmenenpäämiehen ja hänen viisikymmentä miestänsä. Ja tämä kolmas viidenkymmenenpäämies meni sinne, ja kun hän tuli perille, polvistui hän Elian eteen ja anoi häneltä armoa ja sanoi hänelle: \"Sinä Jumalan mies, olkoon minun henkeni ja näiden viidenkymmenen palvelijasi henki kallis sinun silmissäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Katso, tuli on tullut taivaasta ja kuluttanut ne kaksi ensimmäistä viidenkymmenenpäämiestä ja heidän viisikymmentä miestänsä, mutta olkoon minun henkeni kallis sinun silmissäsi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'Ja Herran enkeli sanoi Elialle: \"Mene alas hänen kanssaan, älä pelkää häntä\". Niin hän nousi ja meni hänen kanssaan kuninkaan tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'Ja hän sanoi hänelle: \"Näin sanoo Herra: Koska lähetit sanansaattajia kysymään neuvoa Baal-Sebubilta, Ekronin jumalalta, ikäänkuin Israelissa ei olisi Jumalaa, jolta voisi kysyä neuvoa, sentähden sinä et astu alas vuoteesta, johon olet noussut, sillä sinun on kuoltava\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Niin hän kuoli, Herran sanan mukaan, jonka Elia oli puhunut. Ja Jooram tuli kuninkaaksi hänen sijaansa Jooramin, Joosafatin pojan, Juudan kuninkaan, toisena hallitusvuotena, sillä Ahasjalla ei ollut poikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Mitä muuta on kerrottavaa Ahasjasta, siitä, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Silloin, kun Herra oli vievä Elian tuulispäässä taivaaseen, kulkivat Elia ja Elisa Gilgalista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'Ja Elia sanoi Elisalle: \"Jää tähän, sillä Herra on lähettänyt minut Beeteliin asti\". Mutta Elisa vastasi: \"Niin totta kuin Herra elää, ja niin totta kuin sinun sielusi elää: minä en jätä sinua\". Ja he menivät Beeteliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Niin Beetelissä olevat profeetanoppilaat tulivat Elisan tykö ja sanoivat hänelle: \"Tiedätkö, että Herra tänä päivänä ottaa sinun herrasi pois sinun pääsi ylitse?\" Hän vastasi: \"Tiedän kyllä; olkaa vaiti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Ja Elia sanoi hänelle: \"Elisa, jää tähän, sillä Herra on lähettänyt minut Jerikoon\". Mutta hän vastasi: \"Niin totta kuin Herra elää, ja niin totta kuin sinun sielusi elää: minä en jätä sinua\". Ja he tulivat Jerikoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Niin Jerikossa olevat profeetanoppilaat astuivat Elisan tykö ja sanoivat hänelle: \"Tiedätkö, että Herra tänä päivänä ottaa herrasi pois sinun pääsi ylitse?\" Hän vastasi: \"Tiedän kyllä; olkaa vaiti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Ja Elia sanoi hänelle: \"Jää tähän, sillä Herra on lähettänyt minut Jordanille\". Mutta hän vastasi: \"Niin totta kuin Herra elää, ja niin totta kuin sinun sielusi elää: minä en jätä sinua\". Niin he kulkivat molemmat yhdessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'Mutta myös profeetanoppilaita lähti matkaan viisikymmentä miestä, ja he asettuivat syrjään jonkun matkan päähän näiden kahden pysähtyessä Jordanille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Niin Elia otti vaippansa, kääri sen kokoon ja löi veteen; ja vesi jakaantui kummallekin puolelle, ja he kävivät molemmat virran yli kuivaa myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'Kun he olivat tulleet yli, sanoi Elia Elisalle: \"Pyydä minua tekemään hyväksesi jotakin, ennenkuin minut otetaan pois sinun tyköäsi\". Elisa sanoi: \"Tulkoon minuun sinun hengestäsi kaksinkertainen osa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Hän vastasi: \"Pyyntösi on vaikea täyttää. Mutta jos näet, kuinka minut otetaan pois sinun tyköäsi, niin se täytetään; jollet, niin se jää täyttämättä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'Kun he niin kulkivat ja puhelivat, niin katso, äkkiä ilmestyivät tuliset vaunut ja tuliset hevoset, ja ne erottivat heidät toisistansa, ja Elia nousi tuulispäässä taivaaseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Kun Elisa sen näki, huusi hän: \"Isäni, isäni! Israelin sotavaunut ja ratsumiehet!\" Sitten hän ei enää nähnyt häntä. Ja hän tarttui vaatteisiinsa ja repäisi ne kahdeksi kappaleeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'Sitten hän otti maasta Elian vaipan, joka oli pudonnut hänen päältään, palasi takaisin ja pysähtyi Jordanin rannalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'Ja hän otti Elian vaipan, joka oli pudonnut tämän päältä, löi veteen ja sanoi: \"Missä on Herra, Elian Jumala?\" Kun hän siis löi veteen, jakaantui se kummallekin puolelle, ja Elisa kävi virran yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Kun Jerikosta tulleet profeetanoppilaat syrjästä näkivät sen, sanoivat he: \"Elian henki on laskeutunut Elisaan\". Niin he tulivat häntä vastaan ja kumartuivat hänen edessään maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'Ja he sanoivat hänelle: \"Katso, palvelijaisi joukossa on viisikymmentä urhoollista miestä; menkööt he etsimään sinun isäntääsi. Ehkä Herran Henki on vienyt hänet ja heittänyt jollekin vuorelle tai johonkin laaksoon.\" Hän vastasi: \"Älkää lähettäkö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Mutta he pyysivät häntä pyytämällä, kyllästyksiin asti, kunnes hän sanoi: \"Lähettäkää sitten\". Niin he lähettivät viisikymmentä miestä; ja nämä etsivät kolme päivää, mutta eivät löytäneet häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'Kun he tulivat takaisin hänen luoksensa, hänen ollessaan Jerikossa, sanoi hän heille: \"Enkö minä kieltänyt teitä menemästä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Ja kaupungin miehet sanoivat Elisalle: \"Katso, kaupungin asema on hyvä, niinkuin herrani näkee, mutta vesi on huonoa, ja maassa syntyy keskoisia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Hän sanoi: \"Tuokaa minulle uusi malja ja pankaa siihen suoloja\". Ja he toivat sen hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'Niin hän meni vesien lähteelle ja heitti siihen suolat, sanoen: \"Näin sanoo Herra: Minä olen parantanut tämän veden; siitä ei enää tule kuolemaa eikä keskenmenoa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'Niin vesi tuli terveelliseksi, aina tähän päivään asti, Elisan sanan mukaan, jonka hän puhui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Sieltä hän meni Beeteliin, ja hänen käydessään tietä tuli pieniä poikasia kaupungista, ja ne pilkkasivat häntä ja sanoivat hänelle: \"Tule ylös, kaljupää, tule ylös, kaljupää!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Ja kun hän kääntyi ja näki heidät, kirosi hän heidät Herran nimeen. Silloin tuli metsästä kaksi karhua ja raateli neljäkymmentä kaksi poikaa kuoliaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'Sieltä hän meni Karmel-vuorelle ja palasi sieltä Samariaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Jooram, Ahabin poika, tuli Israelin kuninkaaksi Samariassa Joosafatin, Juudan kuninkaan, kahdeksantenatoista hallitusvuotena, ja hän hallitsi kaksitoista vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'Hän teki sitä, mikä on pahaa Herran silmissä, ei kuitenkaan niinkuin hänen isänsä ja äitinsä, sillä hän poisti Baalin patsaan, jonka hänen isänsä oli teettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Kuitenkin hän riippui kiinni Jerobeamin, Nebatin pojan, synnissä, jolla tämä oli saattanut Israelin tekemään syntiä; siitä hän ei luopunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Meesa, Mooabin kuningas, omisti lammaslaumoja ja maksoi verona Israelin kuninkaalle satatuhatta karitsaa ja sadantuhannen oinaan villat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Mutta Ahabin kuoltua Mooabin kuningas luopui Israelin kuninkaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Siihen aikaan lähti kuningas Jooram Samariasta ja katsasti kaiken Israelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'Ja hän meni ja lähetti Joosafatille Juudan kuninkaalle sanan: \"Mooabin kuningas on luopunut minusta. Lähdetkö minun kanssani sotaan Mooabia vastaan?\" Hän vastasi: \"Lähden; minä niinkuin sinä, minun kansani niinkuin sinun kansasi, minun hevoseni niinkuin sinun hevosesi!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Ja Joosafat kysyi: \"Mitä tietä meidän on sinne mentävä?\" Hän vastasi: \"Edomin erämaan tietä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Niin Israelin kuningas, Juudan kuningas ja Edomin kuningas lähtivät liikkeelle. Mutta kun he olivat kierrellen kulkeneet seitsemän päivän matkan eikä ollut vettä sotajoukolle eikä juhdille, jotka seurasivat heitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'sanoi Israelin kuningas: \"Voi, Herra on kutsunut nämä kolme kuningasta kokoon antaakseen heidät Mooabin käsiin!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Mutta Joosafat sanoi: \"Eikö täällä ole ketään Herran profeettaa, kysyäksemme hänen kauttaan neuvoa Herralta?\" Silloin eräs Israelin kuninkaan palvelijoista vastasi ja sanoi: \"Täällä on Elisa, Saafatin poika, joka vuodatti vettä Elian käsille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Joosafat sanoi: \"Hänellä on Herran sana\". Niin Israelin kuningas, Joosafat ja Edomin kuningas menivät hänen tykönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'Ja Elisa sanoi Israelin kuninkaalle: \"Mitä minulla on tekemistä sinun kanssasi? Mene isäsi ja äitisi profeettain tykö.\" Israelin kuningas sanoi hänelle: \"Ei niin! Sillä Herra on kutsunut nämä kolme kuningasta kokoon antaakseen heidät Mooabin käsiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Elisa sanoi: \"Niin totta kuin Herra Sebaot elää, jonka edessä minä seison: jollen tahtoisi tehdä Joosafatille, Juudan kuninkaalle, mieliksi, niin minä tosiaankaan en katsoisi sinuun enkä huomaisi sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Mutta tuokaa minulle nyt kanteleensoittaja.\" Ja kun kanteleensoittaja soitti, niin Herran käsi laskeutui hänen päällensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'ja hän sanoi: \"Näin sanoo Herra: Tehkää tämä laakso kuoppia täyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Sillä näin sanoo Herra: Te ette tule näkemään tuulta ettekä sadetta, ja kuitenkin tämä laakso tulee vettä täyteen; ja te saatte juoda, sekä te että teidän karjanne ja juhtanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Mutta tämä on Herran silmissä pieni asia: hän antaa Mooabin teidän käsiinne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'ja niin te valloitatte kaikki varustetut kaupungit ja kaikki valitut kaupungit, kaadatte kaikki hedelmäpuut, tukitte kaikki vesilähteet ja turmelette kivillä kaikki hyvät peltopalstat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'Ja katso, seuraavana aamuna, sinä hetkenä, jona ruokauhri uhrataan, tuli vettä Edomista päin, niin että maa tuli vettä täyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Kun kaikki mooabilaiset kuulivat, että kuninkaat olivat lähteneet sotaan heitä vastaan, kutsuttiin koolle kaikki miekkaan vyöttäytyvät ja myös vanhemmat miehet, ja he asettuivat rajalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'Mutta varhain aamulla, kun aurinko nousi ja paistoi veteen, näkivät mooabilaiset, että vesi heidän edessään oli punaista kuin veri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'Ja he sanoivat: \"Se on verta; varmaan kuninkaat ovat joutuneet taisteluun keskenään ja surmanneet toisensa. Ja nyt saaliin ryöstöön, Mooab!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Mutta kun he tulivat Israelin leiriin, nousivat israelilaiset ja voittivat mooabilaiset, niin että nämä pakenivat heitä. Ja he hyökkäsivät maahan ja voittivat uudelleen mooabilaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'Ja he hävittivät kaupungit, kaikille hyville peltopalstoille heitti kukin heistä kiven, täyttäen ne; he tukkivat kaikki vesilähteet ja kaatoivat kaikki hedelmäpuut, niin että ainoastaan Kiir-Haresetissa jäivät kivet paikoilleen. Ja linkomiehet piirittivät kaupungin ja ampuivat sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Kun Mooabin kuningas näki joutuvansa tappiolle taistelussa, otti hän mukaansa seitsemänsataa miekkamiestä murtautuakseen Edomin kuninkaan luo; mutta he eivät voineet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Niin hän otti poikansa, esikoisensa, joka oli tuleva kuninkaaksi hänen sijaansa, ja uhrasi hänet polttouhriksi muurilla. Silloin suuri viha kohtasi Israelia, niin että he lähtivät sieltä ja palasivat omaan maahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Eräs nainen, profeetanoppilaan vaimo, huusi Elisalle sanoen: \"Minun mieheni, sinun palvelijasi, kuoli, ja sinä tiedät, että palvelijasi oli herraapelkääväinen mies. Nyt velkoja tulee ottamaan minun molemmat poikani orjikseen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elisa sanoi hänelle: \"Mitä minä voin tehdä sinun hyväksesi? Sano minulle, mitä sinulla on talossasi.\" Hän vastasi: \"Palvelijattarellasi ei ole talossa muuta kuin öljyä sen verran, kuin minä tarvitsen voidellakseni itseäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Silloin hän sanoi: \"Mene ja lainaa itsellesi astioita kylästä, kaikilta naapureiltasi, tyhjiä astioita, tarpeeksi paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'Mene sitten sisään, sulje ovi jälkeesi ja poikiesi jälkeen ja kaada kaikkiin niihin astioihin. Ja aina kun astia on täysi, nosta se syrjään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'Niin hän meni pois hänen tyköänsä ja sulki oven jälkeensä ja poikiensa jälkeen. Nämä toivat sitten hänelle astiat, ja hän kaatoi niihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'Ja kun astiat olivat täynnä, sanoi hän pojallensa: \"Tuo minulle vielä yksi astia\". Mutta hän vastasi hänelle: \"Ei ole enää astiata\". Silloin öljy tyrehtyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Ja hän meni ja kertoi sen Jumalan miehelle. Tämä sanoi: \"Mene ja myy öljy ja maksa velkasi. Sinä ja poikasi elätte siitä, mikä jää jäljelle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Eräänä päivänä Elisa meni Suunemiin, ja siellä oli arvossa pidetty vaimo, joka vaati häntä aterioimaan. Ja niin usein kuin hän kulki sen kautta, poikkesi hän sinne aterioimaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Niin vaimo sanoi miehellensä: \"Katso, minä olen huomannut, että hän, joka aina kulkee meidän kauttamme, on pyhä Jumalan mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Muurauttakaamme pieni yliskammio ja pankaamme hänelle sinne vuode, pöytä, tuoli ja lamppu, niin että hän tullessaan meidän luoksemme voi vetäytyä sinne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'Eräänä päivänä hän sitten tuli sinne, poikkesi yliskammioon ja pani sinne maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Ja hän sanoi palvelijallensa Geehasille: \"Kutsu se suunemilainen vaimo\". Ja hän kutsui tämän, ja hän astui hänen eteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Niin hän sanoi palvelijalle: \"Sano hänelle: \'Katso, sinä olet nähnyt kaiken tämän vaivan meidän tähtemme. Voisinko minä tehdä jotakin sinun hyväksesi? Onko sinulla jotakin esitettävää kuninkaalle tai sotapäällikölle?\'\" Mutta hän vastasi: \"Minähän asun heimoni keskellä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'Niin hän kysyi: \"Eikö siis voi tehdä mitään hänen hyväksensä?\" Geehasi vastasi: \"Voi kyllä: hänellä ei ole poikaa, ja hänen miehensä on vanha\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Hän sanoi: \"Kutsu hänet\". Niin tämä kutsui hänet, ja hän astui ovelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'Ja Elisa sanoi: \"Tähän aikaan tulevana vuonna on sinulla poika sylissäsi\". Hän vastasi: \"Ei, herrani; sinä Jumalan mies, älä petä palvelijatartasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'Mutta vaimo tuli raskaaksi ja synnytti pojan seuraavana vuonna juuri sinä aikana, jonka Elisa oli hänelle sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'Kun poika oli kasvanut isoksi, meni hän eräänä päivänä isänsä tykö, joka oli leikkuuväen luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Ja hän valitti isällensä: \"Voi minun päätäni, voi minun päätäni!\" Tämä sanoi palvelijalle: \"Kanna hänet äitinsä luo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Niin palvelija otti hänet ja vei hänen äitinsä luo. Ja poika istui hänen polvillansa puolipäivään asti; sitten hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Ja äiti meni ylös ja laski hänet Jumalan miehen vuoteeseen, sulki oven, niin että poika jäi yksin, ja lähti pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Sitten hän kutsui miehensä ja sanoi: \"Lähetä minulle palvelija ja aasintamma, niin minä riennän Jumalan miehen tykö ja tulen heti takaisin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Hän sanoi: \"Miksi menet hänen tykönsä tänä päivänä? Eihän nyt ole uusikuu eikä sapatti.\" Hän vastasi: \"Ole huoleti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'Ja hän satuloi aasintamman ja sanoi palvelijallensa: \"Aja yhä eteenpäin äläkä keskeytä minun matkaani, ennenkuin sanon sinulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Niin hän lähti ja tuli Jumalan miehen tykö Karmel-vuorelle. Kun Jumalan mies näki hänet kaukaa, sanoi hän palvelijalleen Geehasille: \"Katso, se on suunemilainen vaimo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Riennä nyt häntä vastaan ja kysy häneltä: \'Voitko sinä hyvin, voivatko miehesi ja poikasi hyvin?\'\" Hän vastasi: \"Hyvin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Tultuaan vuorelle Jumalan miehen tykö hän tarttui hänen jalkoihinsa. Niin Geehasi astui esiin työntääkseen hänet pois. Mutta Jumalan mies sanoi: \"Jätä hänet rauhaan, sillä hänen sielunsa on murheellinen, ja Herra on salannut sen minulta eikä ole ilmoittanut sitä minulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Hän sanoi: \"Pyysinkö minä poikaa herraltani? Enkö sanonut: \'Älä uskottele minulle\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Silloin Elisa sanoi Geehasille: \"Vyötä kupeesi ja ota minun sauvani käteesi ja mene. Jos kohtaat jonkun, älä tervehdi häntä, ja jos joku tervehtii sinua, älä vastaa. Ja pane minun sauvani pojan kasvoille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'Mutta pojan äiti sanoi: \"Niin totta kuin Herra elää, ja niin totta kuin sinun sielusi elää: minä en jätä sinua\". Ja Elisa nousi ja seurasi häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Mutta Geehasi oli mennyt heidän edellänsä ja pannut sauvan pojan kasvoille, mutta tämä ei ääntänyt eikä kuullut. Niin hän tuli takaisin häntä vastaan ja kertoi hänelle sanoen: \"Poika ei herännyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Ja kun Elisa tuli huoneeseen, niin katso, poika makasi hänen vuoteessaan kuolleena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'Tultuaan sisään hän sulki oven, niin että he jäivät kahden, ja rukoili Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Senjälkeen hän nousi vuoteelle ja laskeutui pojan yli, pannen suunsa hänen suunsa päälle, silmänsä hänen silmiensä päälle ja kätensä hänen kättensä päälle. Ja kun hän näin kumartui hänen ylitsensä, lämpeni pojan ruumis.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Sitten hän kulki huoneessa kerran edestakaisin ja nousi ja kumartui hänen ylitsensä. Silloin poika aivasti seitsemän kertaa, ja senjälkeen poika avasi silmänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Hän kutsui Geehasin ja sanoi: \"Kutsu se suunemilainen vaimo\". Niin hän kutsui vaimon, ja tämä tuli hänen luokseen. Hän sanoi: \"Ota poikasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Ja vaimo tuli ja lankesi hänen jalkainsa juureen, kumartui maahan ja otti poikansa ja meni ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Elisa palasi Gilgaliin, ja maassa oli nälänhätä. Ja kun profeetanoppilaat istuivat hänen edessänsä, sanoi hän palvelijallensa: \"Pane suuri pata liedelle ja keitä keitto profeetanoppilaille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Niin muuan heistä meni kedolle poimimaan yrttejä ja löysi villin köynnöskasvin ja poimi siitä villikurkkuja viittansa täyden. Tultuaan hän leikkeli ne keittopataan, sillä he eivät tunteneet niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'Ja he kaatoivat miesten syödä, mutta kun nämä maistoivat keittoa, huusivat he ja sanoivat: \"Jumalan mies, padassa on kuolema!\" Eivätkä he voineet syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'Silloin hän sanoi: \"Tuokaa jauhoja\". Ja hän heitti ne pataan. Sitten hän sanoi: \"Kaatakaa väen syödä\". Eikä padassa ollut mitään vahingollista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Ja eräs mies tuli Baal-Saalisasta ja toi Jumalan miehelle uutisleipää, kaksikymmentä ohraleipää ja tuleentumatonta viljaa repussansa. Silloin Elisa sanoi: \"Anna väelle syödä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Mutta hänen palvelijansa sanoi: \"Kuinka minä voin tarjota siitä sadalle miehelle?\" Hän sanoi: \"Anna väelle syödä; sillä näin sanoo Herra: He syövät, ja jää tähteeksikin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Ja hän tarjosi heille; ja he söivät, ja jäi tähteeksikin, Herran sanan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naeman, Aramin kuninkaan sotapäällikkö, oli herransa hyvin arvossa pitämä ja suurta kunnioitusta nauttiva mies, sillä hänen kauttansa Herra oli antanut Aramille voiton; ja hän oli sotaurho, mutta pitalitautinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Kerran olivat aramilaiset menneet ryöstöretkelle ja tuoneet Israelin maasta vankina pienen tytön, joka joutui palvelukseen Naemanin puolisolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Tyttö sanoi emännällensä: \"Oi, jospa herrani kävisi profeetan luona Samariassa! Hän kyllä päästäisi hänet hänen pitalistansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Niin Naeman meni ja kertoi tämän herrallensa, sanoen: \"Niin ja niin on tyttö, joka on Israelin maasta, puhunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Aramin kuningas vastasi: \"Mene vain sinne; minä lähetän kirjeen Israelin kuninkaalle\". Niin Naeman lähti sinne ja otti mukaansa kymmenen talenttia hopeata, kuusituhatta sekeliä kultaa ja kymmenen juhlapukua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'Ja hän vei Israelin kuninkaalle kirjeen, joka kuului näin: \"Kun tämä kirje tulee sinulle, niin katso, minä olen lähettänyt luoksesi palvelijani Naemanin, että sinä päästäisit hänet hänen pitalistansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Kun Israelin kuningas oli lukenut kirjeen, repäisi hän vaatteensa ja sanoi: \"Olenko minä Jumala, joka ottaa elämän ja antaa elämän, koska hän käskee minua päästämään miehen hänen pitalistansa? Ymmärtäkää ja nähkää, että hän etsii aihetta minua vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Mutta kun Jumalan mies Elisa kuuli, että Israelin kuningas oli reväissyt vaatteensa, lähetti hän kuninkaalle sanan: \"Miksi olet reväissyt vaatteesi? Anna hänen tulla minun luokseni, niin hän tulee tietämään, että Israelissa on profeetta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Niin Naeman tuli hevosineen ja vaunuineen ja pysähtyi Elisan talon oven eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Ja Elisa lähetti hänen luokseen sanansaattajan ja käski sanoa: \"Mene ja peseydy seitsemän kertaa Jordanissa, niin lihasi tulee entisellensä, ja sinä tulet puhtaaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Mutta Naeman vihastui ja meni matkaansa sanoen: \"Katso, minä luulin hänen edes tulevan ja astuvan esiin ja rukoilevan Herran, Jumalansa, nimeä, heiluttavan kättänsä sen paikan yli ja niin poistavan pitalin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Eivätkö Damaskon virrat, Abana ja Parpar, ole kaikkia Israelin vesiä paremmat? Voisinhan minä yhtä hyvin peseytyä niissä tullakseni puhtaaksi.\" Ja hän kääntyi ja meni tiehensä kiukustuneena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Mutta hänen palvelijansa astuivat esiin ja puhuttelivat häntä ja sanoivat: \"Isäni, jos profeetta olisi määrännyt sinulle jotakin erinomaista, etkö tekisi sitä? Saati sitten, kun hän sanoi sinulle ainoastaan: \'Peseydy, niin tulet puhtaaksi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Niin hän meni ja sukelsi Jordaniin seitsemän kertaa, niinkuin Jumalan mies oli sanonut; ja hänen lihansa tuli entisellensä, pienen pojan lihan kaltaiseksi, ja hän tuli puhtaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Sitten hän palasi Jumalan miehen luo, hän ja koko hänen joukkonsa, meni sisälle, astui hänen eteensä ja sanoi: \"Katso, nyt minä tiedän, ettei Jumalaa ole missään muualla maan päällä kuin Israelissa. Ota siis vastaan jäähyväislahja palvelijaltasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'Mutta hän vastasi: \"Niin totta kuin Herra elää, jonka edessä minä seison, en minä sitä ota\". Ja Naeman pyytämällä pyysi häntä ottamaan, mutta hän epäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Niin Naeman sanoi: \"Jos et tätä otakaan, salli kuitenkin palvelijasi saada sen verran maata, kuin muulipari voi kantaa. Sillä palvelijasi ei enää uhraa polttouhria eikä teurasuhria muille jumalille kuin Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Tämän antakoon kuitenkin Herra anteeksi palvelijallesi: kun minun herrani menee Rimmonin temppeliin rukoilemaan, nojaten minun käteeni, ja minäkin kumartaen rukoilen Rimmonin temppelissä, niin antakoon Herra palvelijallesi anteeksi sen, että minä kumartaen rukoilen Rimmonin temppelissä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'Elisa sanoi hänelle: \"Mene rauhassa\". Kun hän oli kulkenut hänen luotansa jonkun matkaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'ajatteli Geehasi, Jumalan miehen Elisan palvelija: \"Katso, minun herrani säästi tuota aramilaista Naemania, niin ettei ottanut häneltä, mitä hän oli tuonut. Niin totta kuin Herra elää, minä riennän hänen jälkeensä ja otan häneltä jotakin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Niin Geehasi juoksi Naemanin jälkeen. Kun Naeman näki hänen rientävän jäljessänsä, hyppäsi hän alas vaunuistaan, meni häntä vastaan ja kysyi: \"Onko kaikki hyvin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Hän vastasi: \"Hyvin on; mutta herrani on lähettänyt minut ja käskee sanoa: \'Nyt juuri tuli luokseni Efraimin vuoristosta kaksi nuorta miestä, profeetanoppilaita. Anna heille talentti hopeata ja kaksi juhlapukua.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Naeman vastasi: \"Suvaitse ottaa kaksi talenttia\". Ja hän pyytämällä pyysi häntä. Niin hän sitoi kaksi talenttia hopeata kahteen kukkaroon ja antoi ne ynnä kaksi juhlapukua kahdelle palvelijallensa, ja he kantoivat niitä hänen edellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'Mutta kun hän tuli kummulle, otti hän ne heidän käsistänsä ja kätki ne taloon; sitten hän päästi miehet menemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Ja hän meni sisälle ja astui herransa luo. Niin Elisa kysyi häneltä: \"Mistä tulet, Geehasi?\" Hän vastasi: \"Palvelijasi ei ole käynyt missään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Elisa sanoi hänelle: \"Eikö minun henkeni kulkenut sinun kanssasi, kun eräs mies kääntyi vaunuissansa sinua vastaan? Oliko nyt aika ottaa hopeata ja hankkia vaatteita, öljytarhoja, viinitarhoja, lampaita, raavaita, palvelijoita ja palvelijattaria?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Naemanin pitalitauti tarttuu sinuun ja sinun jälkeläisiisi ikiajoiksi.\" Ja Geehasi lähti hänen luotansa lumivalkeana pitalista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'Ja profeetanoppilaat sanoivat Elisalle: \"Katso, huone, jossa me istumme sinun edessäsi, on meille liian ahdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Menkäämme siis Jordanille, ja tuokaamme sieltä kukin yksi hirsi ja rakentakaamme sinne huone istuaksemme.\" Hän sanoi: \"Menkää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Eräs heistä sanoi: \"Suvaitse tulla palvelijasi kanssa\". Hän sanoi: \"Minä tulen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'Niin hän meni heidän kanssaan. Ja Jordanille tultuaan he hakkasivat puita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'Mutta erään heistä kaataessa hirttä kirposi kirves veteen. Niin hän huusi ja sanoi: \"Voi, herrani, se oli vielä lainattu!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Jumalan mies kysyi: \"Mihin se kirposi?\" Ja hän näytti hänelle paikan. Silloin hän veisti puukappaleen ja heitti sen siihen ja sai kirveen nousemaan pinnalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'Sitten hän sanoi: \"Nosta se ylös\". Ja mies ojensi kätensä ja otti sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Kun Aramin kuningas oli sodassa Israelia vastaan, neuvotteli hän palvelijainsa kanssa ja sanoi: \"Siihen ja siihen paikkaan minä asetun leiriin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Mutta Jumalan mies lähetti Israelin kuninkaalle sanan: \"Varo, ettet mene siihen paikkaan, sillä aramilaiset ovat asettuneet sinne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Niin Israelin kuningas lähetti sanan siihen paikkaan, jonka Jumalan mies oli hänelle sanonut. Näin tämä varoitti häntä, ja hän oli siellä varuillaan. Eikä se tapahtunut ainoastaan kerran tai kahdesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'Aramin kuninkaan sydän tuli tästä levottomaksi, ja hän kutsui palvelijansa ja sanoi heille: \"Ettekö voi ilmaista minulle, kuka meikäläisistä pitää Israelin kuninkaan puolta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Silloin eräs hänen palvelijoistaan sanoi: \"Ei niin, herrani, kuningas, vaan profeetta Elisa, joka on Israelissa, ilmaisee Israelin kuninkaalle nekin sanat, jotka sinä puhut makuuhuoneessasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Hän sanoi: \"Menkää ja katsokaa, missä hän on, niin minä lähetän ottamaan hänet kiinni\". Ja hänelle ilmoitettiin: \"Katso, hän on Dootanissa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Niin hän lähetti sinne hevosia ja sotavaunuja ja suuren sotajoukon. He tulivat sinne yöllä ja ympäröivät kaupungin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Kun Jumalan miehen palvelija nousi aamulla varhain ja meni ulos, niin katso, sotajoukko, hevoset ja sotavaunut piirittivät kaupunkia. Ja hänen palvelijansa sanoi hänelle: \"Voi, herrani, mitä me nyt teemme?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'Hän sanoi: \"Älä pelkää, sillä niitä, jotka ovat meidän kanssamme, on enemmän kuin niitä, jotka ovat heidän kanssansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Ja Elisa rukoili ja sanoi: \"Herra, avaa hänen silmänsä, että hän näkisi\". Ja Herra avasi palvelijan silmät, ja hän näki, ja katso: vuori oli täynnä tulisia hevosia ja tulisia vaunuja Elisan ympärillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'Kun viholliset sitten tulivat häntä vastaan, rukoili Elisa Herraa ja sanoi: \"Sokaise tämä väki\". Silloin hän sokaisi heidät Elisan pyynnön mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Ja Elisa sanoi heille: \"Ei tämä ole oikea tie, eikä tämä ole oikea kaupunki. Seuratkaa minua, niin minä vien teidät sen miehen luo, jota te etsitte.\" Ja hän vei heidät Samariaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Mutta kun he tulivat Samariaan, sanoi Elisa: \"Herra, avaa näiden silmät, että he näkisivät\". Silloin Herra avasi heidän silmänsä, ja he näkivät; ja katso: he olivat keskellä Samariaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'Ja kun Israelin kuningas näki heidät, sanoi hän Elisalle: \"Surmaanko minä heidät, isäni, surmaanko heidät?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Hän sanoi: \"Älä surmaa. Surmaatko sinä ne, jotka otat vangiksi miekallasi ja jousellasi? Pane heidän eteensä ruokaa ja juomaa heidän syödä ja juoda; menkööt sitten takaisin herransa luo.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'Niin tämä valmisti heille suuren aterian, ja kun he olivat syöneet ja juoneet, päästi hän heidät menemään; ja he menivät herransa luo. Eikä aramilaisia partiojoukkoja sitten enää tullut Israelin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Sen jälkeen Benhadad, Aramin kuningas, kokosi kaiken sotajoukkonsa ja tuli ja piiritti Samarian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Silloin syntyi Samariassa, heidän piirittäessään sitä, suuri nälänhätä, niin että aasinpää maksoi kahdeksankymmentä hopeasekeliä ja neljännes kab-mittaa kyyhkysensontaa viisi hopeasekeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'Ja kun Israelin kuningas käveli muurin päällä, huusi muuan vaimo hänelle ja sanoi: \"Auta, herrani, kuningas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Hän vastasi: \"Jollei Herra auta sinua, niin mistä minä hankin sinulle apua? Puimatantereeltako vai viinikuurnasta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Ja kuningas sanoi hänelle: \"Mikä sinun on?\" Hän vastasi: \"Tämä vaimo sanoi minulle: \'Anna tänne poikasi, syödäksemme hänet tänä päivänä, niin syömme huomenna minun poikani\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Ja me keitimme minun poikani ja söimme hänet. Ja minä sanoin toisena päivänä hänelle: \'Anna tänne poikasi, syödäksemme hänet\'. Mutta hän piilotti poikansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Kun kuningas kuuli vaimon sanat, repäisi hän vaatteensa, kävellessään muurin päällä. Niin kansa näki, että hänellä oli vaatteiden alla säkki, paljaalla iholla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Ja hän sanoi: \"Jumala rangaiskoon minua nyt ja vasta, jos Elisan, Saafatin pojan, pää tänä päivänä jää hänen hartioilleen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Elisa istui talossaan, ja vanhimmat istuivat hänen tykönänsä. Ja kuningas oli lähettänyt miehen edellänsä. Mutta ennenkuin sanansaattaja tuli hänen luokseen, sanoi hän vanhimmille: \"Näettekö, kuinka se murhamiehen poika lähettää hakkaamaan minulta päätä poikki? Mutta kun sanansaattaja tulee, katsokaa, että suljette oven ja pidätte oven kiinni häneltä. Eivätkö jo kuulu hänen herransa askeleet hänen jäljessään?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Hänen vielä puhuessaan heidän kanssansa, tuli sanansaattaja hänen luokseen ja sanoi: \"Katso, tämä onnettomuus tulee Herralta; mitä minä enää odottaisin Herraa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Mutta Elisa vastasi: \"Kuulkaa Herran sana; näin sanoo Herra: Huomenna tähän aikaan maksaa Samarian portissa sea-mitta lestyjä jauhoja sekelin ja kaksi sea-mittaa ohria sekelin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Niin vaunusoturi, jonka käsivarteen kuningas nojasi, vastasi Jumalan miehelle ja sanoi: \"Katso, vaikka Herra tekisi akkunat taivaaseen, kuinka voisi tämä tapahtua?\" Hän sanoi: \"Sinä olet näkevä sen omin silmin, mutta syödä siitä et saa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Ja kaupungin portin oven edustalla oleskeli neljä pitalitautista miestä. He sanoivat toisillensa: \"Mitä me istumme tässä, kunnes kuolemme?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Jos päätämme mennä kaupunkiin, jossa on nälänhätä, niin me kuolemme. Jos jäämme tähän, niin me kuolemme. Tulkaa, siirtykäämme nyt aramilaisten leiriin. Jos he jättävät meidät eloon, niin me jäämme eloon; jos he surmaavat meidät, niin me kuolemme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Niin he nousivat hämärissä mennäkseen aramilaisten leiriin. Kun he tulivat aramilaisten leirin laitaan, niin katso: siellä ei ollut ketään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Sillä Herra oli antanut aramilaisten sotajoukon kuulla sotavaunujen, hevosten ja suuren sotajoukon töminää; ja niin he olivat sanoneet toisilleen: \"Katso, Israelin kuningas on palkannut meitä vastaan heettiläisten kuninkaat ja egyptiläisten kuninkaat, että nämä hyökkäisivät meidän kimppuumme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Niin he olivat lähteneet liikkeelle ja paenneet hämärissä ja jättäneet telttansa, hevosensa, aasinsa ja leirinsä, niinkuin se oli; he olivat paenneet pelastaakseen henkensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Tultuaan leirin laitaan pitalitautiset menivät erääseen telttaan, söivät ja joivat, ottivat sieltä hopeata ja kultaa ja vaatteita, menivät pois ja kätkivät ne. Sitten he tulivat takaisin ja menivät toiseen telttaan ja ottivat sieltä saalista ja menivät pois ja kätkivät sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Mutta sitten he sanoivat toisilleen: \"Emme tee oikein. Tämä päivä on hyvän sanoman päivä. Jos olemme vaiti ja odotamme aamun valkenemiseen asti, niin me joudumme syyllisiksi. Tulkaa, menkäämme nyt ilmoittamaan tämä kuninkaan linnaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'Niin he tulivat ja kutsuivat kaupungin portinvartijat ja ilmoittivat heille sanoen: \"Me tulimme aramilaisten leiriin, ja katso, siellä ei ollut ketään eikä kuulunut ihmisääntä; siellä oli vain hevosia ja aaseja kytkettyinä kiinni, ja teltat olivat, niinkuin olivat olleet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Portinvartijat huusivat ja ilmoittivat tämän kuninkaan linnaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Silloin kuningas nousi yöllä ja sanoi palvelijoilleen: \"Minä sanon teille, minkä aramilaiset meille tekevät. He tietävät meidän kärsivän nälkää, ja sentähden he ovat poistuneet leiristä ja piiloutuneet kedolle, ajatellen: kun ne lähtevät kaupungista, niin me otamme heidät elävinä kiinni ja menemme kaupunkiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Mutta eräs hänen palvelijoistaan vastasi ja sanoi: \"Otettakoon viisi tähteeksi jääneistä hevosista, jotka ovat vielä täällä jäljellä-niidenhän käy kuitenkin samoin kuin kaiken Israelin joukon, joka on täällä jäljellä, ja samoin kuin kaiken Israelin joukon, joka on hukkunut-ja lähettäkäämme katsomaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Niin he ottivat kahdet sotavaunut hevosineen, ja kuningas lähetti ne aramilaisten sotajoukon jälkeen, sanoen: \"Menkää ja katsokaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'He menivät heidän jälkeensä aina Jordanille asti; ja katso: koko tie oli täynnä vaatteita ja aseita, jotka aramilaiset olivat heittäneet pois rientäessään pakoon. Niin sanansaattajat tulivat takaisin ja ilmoittivat sen kuninkaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Silloin kansa lähti ja ryösti aramilaisten leirin. Ja niin sea-mitta lestyjä jauhoja maksoi sekelin ja kaksi sea-mittaa ohria sekelin, Herran sanan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Kuningas oli asettanut sen vaunusoturin, jonka käsivarteen hän nojasi, porttiin valvomaan järjestystä. Mutta kansa tallasi hänet kuoliaaksi portissa, niinkuin Jumalan mies oli puhunut, silloin kun kuningas tuli hänen luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Sillä kun Jumalan mies oli puhunut kuninkaalle näin: \"Huomenna tähän aikaan maksaa kaksi sea-mittaa ohria Samarian portissa sekelin ja sea-mitta lestyjä jauhoja sekelin\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'oli vaunusoturi vastannut Jumalan miehelle ja sanonut: \"Katso, vaikka Herra tekisi akkunat taivaaseen, kuinka tämä voisi tapahtua?\" Silloin hän oli sanonut: \"Sinä olet näkevä sen omin silmin, mutta syödä siitä et saa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'Ja niin hänen myös kävi: kansa tallasi hänet kuoliaaksi portissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Ja Elisa puhui vaimolle, jonka pojan hän oli palauttanut henkiin, ja sanoi: \"Nouse ja lähde, sinä ja sinun perheesi, asumaan muukalaisena, missä vain voit asua, sillä Herra on käskenyt nälänhädän tulla, ja se myös tulee maahan seitsemäksi vuodeksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Niin vaimo nousi ja teki Jumalan miehen sanan mukaan: hän lähti ja asui perheinensä muukalaisena filistealaisten maassa seitsemän vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Mutta niiden seitsemän vuoden kuluttua vaimo palasi filistealaisten maasta; ja hän tuli anomaan kuninkaalta taloansa ja peltoansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Ja kuningas puhutteli juuri Geehasia, Jumalan miehen palvelijaa, ja sanoi: \"Kerro minulle kaikki ne suuret teot, jotka Elisa on tehnyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'Juuri kun hän kertoi kuninkaalle, kuinka Elisa oli palauttanut kuolleen henkiin, tuli vaimo, jonka pojan hän oli palauttanut henkiin, anomaan kuninkaalta taloansa ja peltoansa. Silloin Geehasi sanoi: \"Herrani, kuningas, tämä on se vaimo; ja tämä on se poika, jonka Elisa palautti henkiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'Ja kuningas kyseli vaimolta, ja tämä kertoi sen hänelle. Niin kuningas antoi hänen mukaansa hoviherran ja sanoi: \"Toimita tälle takaisin kaikki, mikä on hänen omaansa, ja lisäksi kaikki pellon sadot siitä päivästä alkaen, jona hän jätti maan, aina tähän asti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Ja Elisa tuli Damaskoon. Ja Aramin kuningas Benhadad oli sairaana. Kun hänelle ilmoitettiin: \"Jumalan mies on tullut tänne\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'sanoi kuningas Hasaelille: \"Ota mukaasi lahja ja mene Jumalan miestä vastaan ja kysy hänen kauttansa Herralta: \'Toivunko minä tästä taudista?\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Ja Hasael meni häntä vastaan ja otti mukaansa lahjaksi kaikkea, mitä Damaskossa oli parasta, neljäkymmentä kamelinkuormaa. Ja hän tuli ja astui hänen eteensä ja sanoi: \"Poikasi Benhadad, Aramin kuningas, lähetti minut sinun luoksesi ja käski kysyä: \'Toivunko minä tästä taudista?\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'Elisa sanoi: \"Mene ja sano hänelle: \'Toivut\'. Mutta Herra on ilmoittanut minulle, että hänen on kuoltava.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Ja hän tuijotti eteensä kauan ja liikahtamatta; sitten Jumalan mies alkoi itkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Niin Hasael sanoi: \"Minkätähden herrani itkee?\" Hän vastasi: \"Sentähden, että minä tiedän, kuinka paljon pahaa sinä olet tekevä israelilaisille: sinä pistät heidän varustetut kaupunkinsa tuleen, sinä surmaat miekalla heidän valiomiehensä, sinä murskaat heidän pienet lapsensa ja halkaiset heidän raskaat vaimonsa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Hasael sanoi: \"Mikä on palvelijasi, tällainen koira, tekemään näitä suuria asioita?\" Elisa vastasi: \"Herra on ilmoittanut minulle, että sinusta on tuleva Aramin kuningas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Niin hän meni Elisan tyköä, ja kun hän tuli herransa tykö, kysyi tämä häneltä: \"Mitä Elisa sanoi sinulle?\" Hän vastasi: \"Hän sanoi minulle, että sinä toivut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Mutta seuraavana päivänä hän otti peitteen ja kastoi sen veteen ja levitti sen hänen kasvoillensa; niin hän kuoli. Ja Hasael tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'Israelin kuninkaan Jooramin, Ahabin pojan, viidentenä hallitusvuotena tuli Jooram, Juudan kuninkaan Joosafatin poika, kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Hän oli kolmenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kahdeksan vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Mutta hän vaelsi Israelin kuningasten tietä, niinkuin Ahabin suku oli tehnyt, sillä hänellä oli puolisona Ahabin tytär. Ja niin hän teki sitä, mikä on pahaa Herran silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Mutta palvelijansa Daavidin tähden Herra ei tahtonut tuhota Juudaa, koska hän oli luvannut antaa hänelle ja hänen pojilleen lampun ainiaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Hänen aikanaan edomilaiset luopuivat Juudan vallanalaisuudesta ja asettivat itsellensä kuninkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Ja Jooram lähti Saairiin kaikkine sotavaunuinensa. Ja hän nousi yöllä ja voitti edomilaiset, jotka olivat saartaneet hänet, sekä sotavaunujen päälliköt. Mutta väki pakeni majoillensa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'ja edomilaiset luopuivat Juudan vallanalaisuudesta; niin aina tähän päivään asti. Siihen aikaan luopui myös Libna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'Mitä muuta on kerrottavaa Jooramista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'Sitten Jooram meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Ja hänen poikansa Ahasja tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Israelin kuninkaan Jooramin, Ahabin pojan, kahdentenatoista hallitusvuotena tuli Ahasja, Juudan kuninkaan Jooramin poika, kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Ja Ahasja oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa vuoden. Hänen äitinsä oli nimeltään Atalja, Israelin kuninkaan Omrin tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Ahasja vaelsi Ahabin suvun tietä ja teki sitä, mikä on pahaa Herran silmissä, samoin kuin Ahabin suku; sillä hän oli lankoutunut Ahabin suvun kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Ja hän lähti Jooramin, Ahabin pojan, kanssa sotimaan Hasaelia, Aramin kuningasta, vastaan Gileadin Raamotiin; mutta aramilaiset haavoittivat Jooramin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'Niin kuningas Jooram tuli takaisin parantuakseen Jisreelissä haavoista, joita aramilaiset olivat iskeneet häneen Raamassa hänen taistellessaan Hasaelia, Aramin kuningasta, vastaan. Ja Ahasja, Jooramin poika, Juudan kuningas, tuli Jisreeliin katsomaan Jooramia, Ahabin poikaa, koska tämä oli sairas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Profeetta Elisa kutsui erään profeetanoppilaan ja sanoi hänelle: \"Vyötä kupeesi ja ota tämä öljyastia mukaasi ja mene Gileadin Raamotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'Ja tultuasi sinne hae sieltä käsiisi Jeehu, Joosafatin poika, Nimsin pojanpoika; mene sisään, käske hänen nousta toveriensa keskeltä ja vie hänet sisimpään huoneeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Ota sitten öljyastia, vuodata öljyä hänen päähänsä ja sano: \'Näin sanoo Herra: Minä olen voidellut sinut Israelin kuninkaaksi\'. Avaa sitten ovi ja pakene viivyttelemättä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Niin nuorukainen, profeetan palvelija, meni Gileadin Raamotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'Ja kun hän tuli sinne, niin katso: sotaväen päälliköt istuivat siellä. Niin hän sanoi: \"Minulla on asiaa sinulle, päällikkö\". Jeehu kysyi: \"Kenelle meistä kaikista?\" Hän vastasi: \"Sinulle itsellesi, päällikkö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Silloin tämä nousi ja meni sisälle huoneeseen; ja hän vuodatti öljyä tämän päähän ja sanoi hänelle: \"Näin sanoo Herra, Israelin Jumala: Minä olen voidellut sinut Herran kansan, Israelin, kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'Ja sinä olet surmaava herrasi Ahabin suvun; sillä minä kostan Iisebelille palvelijaini, profeettain, veren ja kaikkien Herran palvelijain veren.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Ja koko Ahabin suku on hukkuva: minä hävitän Israelista Ahabin miespuoliset jälkeläiset, kaikki tyynni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'Ja minä teen Ahabin suvulle saman, minkä Jerobeamin, Nebatin pojan, suvulle ja saman, minkä Baesan, Ahian pojan, suvulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Ja koirat syövät Iisebelin Jisreelin vainiolla, eikä kukaan ole hautaava häntä.\" Sitten hän avasi oven ja pakeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Kun Jeehu tuli ulos herransa palvelijain luo, kysyttiin häneltä: \"Onko kaikki hyvin? Miksi tuo hullu kävi sinun luonasi?\" Hän vastasi heille: \"Tehän tunnette sen miehen ja hänen puheensa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Mutta he sanoivat: \"Valhetta! Sano meille totuus.\" Hän sanoi: \"Niin ja niin hän puhui minulle ja sanoi: \'Näin sanoo Herra: Minä olen voidellut sinut Israelin kuninkaaksi\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Silloin he ottivat kiiruusti kukin vaatteensa ja panivat ne hänen allensa paljaille portaille; ja he puhalsivat pasunaan ja huusivat: \"Jeehu on tullut kuninkaaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Niin Jeehu, Joosafatin poika, Nimsin pojanpoika, teki salaliiton Jooramia vastaan. Jooram oli ollut kaiken Israelin kanssa puolustamassa Gileadin Raamotia Hasaelia, Aramin kuningasta, vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Mutta kuningas Jooram oli tullut takaisin parantuakseen Jisreelissä haavoista, joita aramilaiset olivat iskeneet häneen hänen taistellessaan Hasaelia, Aramin kuningasta, vastaan. Ja Jeehu sanoi: \"Jos se teille kelpaa, niin älkää päästäkö pakoon kaupungista ketään, joka menisi ilmoittamaan tätä Jisreeliin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'Sitten Jeehu nousi vaunuihinsa ja lähti Jisreeliin, sillä Jooram makasi siellä; ja Ahasja, Juudan kuningas, oli tullut sinne katsomaan Jooramia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Mutta tähystäjä seisoi Jisreelin tornissa, ja kun hän näki Jeehun joukon tulevan, sanoi hän: \"Minä näen väkijoukon\". Niin Jooram sanoi: \"Otettakoon ratsumies ja lähetettäköön heitä vastaan kysymään, onko kaikki hyvin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'Ja ratsumies lähti häntä vastaan ja sanoi: \"Näin kysyy kuningas: \'Onko kaikki hyvin?\'\" Jeehu vastasi: \"Mitä se sinua liikuttaa, onko hyvin? Käänny ja seuraa minua.\" Niin tähystäjä ilmoitti sanoen: \"Sanansaattaja on tullut heidän luoksensa, mutta ei palaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Silloin hän lähetti toisen ratsumiehen. Kun tämä oli tullut heidän luoksensa, sanoi hän: \"Näin kysyy kuningas: \'Onko kaikki hyvin?\' Jeehu vastasi: \"Mitä se sinua liikuttaa, onko hyvin? Käänny ja seuraa minua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Niin tähystäjä ilmoitti sanoen: \"Hän on tullut heidän luoksensa, mutta ei palaa. Ja ajo on aivan kuin Jeehun, Nimsin pojan, ajoa; sillä hän ajaa niinkuin hurja.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Silloin Jooram sanoi: \"Valjastettakoon!\" Ja he valjastivat hänen sotavaununsa. Niin Jooram, Israelin kuningas, ja Ahasja, Juudan kuningas, lähtivät kumpikin sotavaunuissansa ja menivät Jeehua vastaan. He kohtasivat hänet jisreeliläisen Naabotin maapalstalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'Kun Jooram näki Jeehun, kysyi hän: \"Onko kaikki hyvin, Jeehu?\" Tämä vastasi: \"Kuinka kaikki voisi olla hyvin, kun sinun äitisi Iisebelin haureus ja hänen monet velhoutensa yhä vielä jatkuvat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Silloin Jooram käänsi vaununsa ja pakeni, huutaen Ahasjalle: \"Kavallus, Ahasja!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Mutta Jeehu sieppasi jousen käteensä ja ampui Jooramia hartioiden väliin, niin että nuoli meni sydämen lävitse, ja hän vaipui vaunuihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Sitten hän sanoi Bidkarille, vaunusoturille: \"Ota hänet ja heitä jisreeliläisen Naabotin maapalstalle; sillä muistathan, että Herra meidän ratsastaessamme rinnakkain hänen isänsä Ahabin jäljessä lausui hänestä tämän ennustuksen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, '\'Totisesti, minä näin eilen Naabotin ja hänen poikiensa veren, sanoo Herra; ja minä olen juuri tällä maapalstalla kostava sinulle, sanoo Herra\'. Ota siis hänet ja heitä tälle maapalstalle, Herran sanan mukaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Kun Ahasja, Juudan kuningas, sen näki, pakeni hän Beet-Gaaniin päin. Mutta Jeehu ajoi häntä takaa ja sanoi: \"Ampukaa hänetkin vaunuihinsa\". Ja he ampuivat häntä Guurin solassa, joka on Jibleamin luona; mutta hän pakeni Megiddoon ja kuoli siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'Ja hänen palvelijansa veivät hänet vaunuissa Jerusalemiin ja hautasivat hänet hänen omaan hautaansa, hänen isiensä viereen, Daavidin kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Ahasja oli tullut Juudan kuninkaaksi Jooramin, Ahabin pojan, yhdentenätoista hallitusvuotena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Sitten Jeehu tuli Jisreeliin. Kun Iisebel kuuli sen, maalasi hän ihomaalilla silmäluomensa, koristeli päänsä ja katseli ulos akkunasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'Ja kun Jeehu tuli portista sisään, kysyi Iisebel: \"Kävikö hyvin Simrille, herransa murhaajalle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'Hän käänsi kasvonsa akkunaa kohti ja sanoi: \"Kuka on minun puolellani? Kuka?\" Niin pari kolme hoviherraa katsoi alas häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Jeehu sanoi: \"Syöskää hänet alas\". Ja he syöksivät hänet alas, niin että hänen vertansa pirskui seinään ja hevosiin; ja nämä tallasivat hänet jalkoihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'Sitten Jeehu meni sisään, söi ja joi. Ja hän sanoi: \"Korjatkaa se kirottu ja haudatkaa hänet, sillä onhan hän kuninkaan tytär\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Mutta kun he menivät hautaamaan häntä, eivät he löytäneet hänestä muuta kuin pääkallon, jalat ja kädet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Ja he tulivat takaisin ja ilmoittivat sen Jeehulle. Niin hän sanoi: \"Tässä on toteutunut Herran sana, jonka hän puhui palvelijansa tisbeläisen Elian kautta: \'Jisreelin vainiolla koirat syövät Iisebelin lihan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'ja Iisebelin ruumis on oleva niinkuin pellon lanta Jisreelin vainiolla, niin ettei voida sanoa: Tämä on Iisebel\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Mutta Ahabilla oli seitsemänkymmentä poikaa Samariassa. Ja Jeehu kirjoitti kirjeet ja lähetti ne Samariaan, Jisreelin päämiehille, vanhimmille ja Ahabin poikien holhoojille; hän kirjoitti näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '\"Kun tämä kirje tulee teille, joiden hallussa herranne pojat ovat ja joiden hallussa ovat sotavaunut, hevoset, varustettu kaupunki ja aseet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'niin valitkaa herranne pojista paras ja oikeamielisin ja asettakaa hänet isänsä valtaistuimelle ja sotikaa herranne suvun puolesta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Mutta he peljästyivät kovin ja sanoivat: \"Katso, ne kaksi kuningasta eivät kestäneet hänen edessään, kuinka me kestäisimme?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'Niin linnan päällikkö ja kaupungin päällikkö sekä vanhimmat ja holhoojat lähettivät Jeehulle sanan: \"Me olemme sinun palvelijoitasi; me teemme kaiken, mitä sinä meille määräät. Emme me tee ketään kuninkaaksi; tee, mitä tahdot.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Silloin hän kirjoitti heille toisen kirjeen, näin kuuluvan: \"Jos te olette minun puolellani ja kuulette minua, niin ottakaa herranne poikien päät ja tulkaa huomenna tähän aikaan minun luokseni Jisreeliin\". Ne seitsemänkymmentä kuninkaan poikaa asuivat näet kaupungin ylimysten luona, jotka heitä kasvattivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Kun kirje tuli heille, ottivat he kuninkaan pojat ja tappoivat heidät, seitsemänkymmentä miestä, panivat heidän päänsä koreihin ja lähettivät ne Jeehulle Jisreeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'Ja sanansaattaja tuli ja ilmoitti hänelle sanoen: \"He ovat tuoneet kuninkaan poikien päät\". Hän sanoi: \"Pankaa ne kahteen roukkioon portin oven edustalle huomiseen saakka\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Ja aamulla hän meni ulos, asettui siihen ja sanoi kaikelle kansalle: \"Te olette syyttömät. Katso, minä olen tehnyt salaliiton herraani vastaan ja tappanut hänet; mutta kuka on surmannut kaikki nämä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Tietäkää siis, ettei ainoakaan Herran sana, jonka Herra on puhunut Ahabin sukua vastaan, varise maahan. Herra on tehnyt, minkä hän on puhunut palvelijansa Elian kautta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Sitten Jeehu surmasi kaikki, jotka olivat Ahabin suvusta jäljellä Jisreelissä, sekä kaikki hänen ylimyksensä, uskottunsa ja pappinsa, päästämättä pakoon ainoatakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Sitten hän nousi ja lähti Samariaan; mutta tullessaan paimenten Beet-Eekediin, joka on tien varrella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Jeehu kohtasi Ahasjan, Juudan kuninkaan, veljet ja kysyi: \"Keitä te olette?\" He vastasivat: \"Me olemme Ahasjan veljiä ja menemme tervehtimään kuninkaan poikia ja kuninkaan äidin poikia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Hän sanoi: \"Ottakaa nämä elävinä kiinni\". Ja he ottivat heidät elävinä kiinni ja tappoivat heidät ja heittivät Beet-Eekedin vesisäiliöön, neljäkymmentä kaksi miestä. Hän ei jättänyt heistä eloon ainoatakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Kun hän sitten lähti sieltä, kohtasi hän Joonadabin, Reekabin pojan, joka tuli häntä vastaan. Ja hän tervehti häntä ja sanoi hänelle: \"Onko sinun sydämesi yhtä vilpitön minua kohtaan, kuin minun sydämeni on sinua kohtaan?\" Joonadab vastasi: \"On\". -\"Jos niin on, niin lyö kättä minun kanssani.\" Ja hän löi kättä, ja hän otti hänet vaunuihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'Ja hän sanoi: \"Tule minun kanssani katsomaan minun kiivailuani Herran puolesta\". Niin hän sai ajaa hänen vaunuissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'Tultuaan Samariaan hän surmasi kaikki, jotka olivat Ahabin jälkeläisistä jäljellä Samariassa, kunnes hän oli hävittänyt hänen sukunsa, Herran sanan mukaan, jonka Herra oli puhunut Elialle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Sitten Jeehu kokosi kaiken kansan ja sanoi heille: \"Ahab on palvellut Baalia vähän; Jeehu on palveleva häntä paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Kutsukaa nyt minun luokseni kaikki Baalin profeetat, kaikki hänen palvelijansa ja kaikki hänen pappinsa, älköönkä kukaan jääkö pois; sillä minä aion uhrata suuret uhrit Baalille. Eloon ei jää kukaan, joka jää pois.\" Mutta Jeehu menetteli kavalasti, tuhotakseen Baalin palvelijat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Niin Jeehu sanoi: \"Kuuluttakaa pyhä juhlakokous Baalin kunniaksi\". Ja se kutsuttiin koolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Ja Jeehu lähetti sanan kaikkeen Israeliin, ja kaikki Baalin palvelijat tulivat; ei yksikään jäänyt tulematta. Niin he menivät Baalin temppeliin, ja Baalin temppeli täyttyi ääriään myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Ja hän sanoi vaatekammion hoitajalle: \"Tuo puvut kaikille Baalin palvelijoille\". Ja tämä toi heille puvut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Kun Jeehu Joonadabin, Reekabin pojan, kanssa tuli Baalin temppeliin, sanoi hän Baalin palvelijoille: \"Tutkikaa ja katsokaa, ettei täällä teidän joukossanne ole ketään Herran palvelijaa, vaan ainoastaan Baalin palvelijoita\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'Sitten he menivät uhraamaan teurasuhreja ja polttouhreja. Mutta Jeehu oli asettanut ulkopuolelle kahdeksankymmentä miestä ja sanonut: \"Jos kuka päästää pakoon yhdenkään niistä miehistä, jotka minä tuon teidän käsiinne, menee henki hengestä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'Ja päätettyänsä polttouhrin uhraamisen sanoi Jeehu henkivartijoille ja vaunusotureille: \"Menkää sisään ja surmatkaa heidät; älköön yksikään pääskö ulos\". Niin he surmasivat heidät miekan terällä, ja henkivartijat ja vaunusoturit heittivät ulos heidän ruumiinsa. Sitten he menivät Baalin temppelilinnaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'ja toivat ulos Baalin temppelin patsaat ja polttivat ne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'ja he kukistivat Baalin patsaan. He hävittivät Baalin temppelin ja tekivät siitä käymälöitä; niin aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Näin Jeehu hävitti Baalin Israelista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Mutta Jerobeamin, Nebatin pojan, synneistä, joilla hän oli saattanut Israelin tekemään syntiä, Beetelissä ja Daanissa olevista kultavasikoista, Jeehu ei luopunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Niin Herra sanoi Jeehulle: \"Koska olet hyvin toimittanut sen, mikä oli oikein minun silmissäni, ja koska teit Ahabin suvulle aivan minun mieleni mukaan, niin istukoot sinun poikasi Israelin valtaistuimella neljänteen polveen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Mutta Jeehu ei vaeltanut tarkoin, kaikesta sydämestänsä, Herran, Israelin Jumalan, lain mukaan; hän ei luopunut Jerobeamin synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'Niihin aikoihin Herra rupesi lohkomaan Israelia, sillä Hasael voitti heidät kaikkialla Israelin raja-alueella');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'ja valloitti Jordanista auringonnousuun päin koko Gileadin maan, gaadilaiset, ruubenilaiset ja manasselaiset, alkaen Aroerista, joka on Arnon-joen rannalla-sekä Gileadin että Baasanin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Mitä muuta on kerrottavaa Jeehusta ja kaikesta, mitä hän teki, ja kaikista hänen urotöistänsä, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'Sitten Jeehu meni lepoon isiensä tykö, ja hänet haudattiin Samariaan. Ja hänen poikansa Jooahas tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Ja aika, jonka Jeehu hallitsi Israelia Samariassa, oli kaksikymmentä kahdeksan vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Kun Atalja, Ahasjan äiti, näki, että hänen poikansa oli kuollut, nousi hän ja tuhosi koko kuningassuvun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Mutta kuningas Jooramin tytär Jooseba, Ahasjan sisar, otti surmattavien kuninkaan poikien joukosta Ahasjan pojan Jooaan ja vei hänet ja hänen imettäjänsä salaa makuuhuoneeseen. Täällä pidettiin Jooasta kätkettynä Ataljalta, niin ettei hän tullut surmatuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'Sitten poika oli Jooseban luona Herran temppeliin piilotettuna kuusi vuotta, Ataljan hallitessa maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Mutta seitsemäntenä vuotena Joojada lähetti hakemaan kaarilaisten ja henkivartijain sadanpäämiehiä ja tuotti heidät luoksensa Herran temppeliin. Ja sittenkuin hän oli tehnyt liiton heidän kanssansa ja vannottanut heidät siellä Herran temppelissä, näytti hän heille kuninkaan pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'Sitten hän käski heitä sanoen: \"Tehkää näin: kolmas osa teistä, joiden on mentävä vartionpitoon sapattina, vartioikoon kuninkaan palatsia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'kolmas osa olkoon sivuportilla ja kolmas osa henkivartijain takana olevalla portilla; vartioikaa palatsia, kukin vuorollanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'Mutta kaksi muuta teidän osastoanne, kaikki, jotka pääsevät vartionpidosta sapattina, vartioikoot Herran temppeliä, kuninkaan luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'Asettukaa kuninkaan ympärille, kullakin ase kädessä; ja joka tunkeutuu rivien läpi, se surmattakoon. Näin olkaa kuninkaan luona, menköön hän ulos tai sisään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'Sadanpäämiehet tekivät, aivan niinkuin pappi Joojada oli heitä käskenyt: kukin heistä otti miehensä, sekä ne, joiden oli mentävä vartionpitoon sapattina, että ne, jotka pääsivät vartionpidosta sapattina, ja he tulivat pappi Joojadan luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Ja pappi antoi sadanpäämiehille keihäät ja varustukset, jotka olivat olleet kuningas Daavidin omat ja olivat Herran temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'Ja henkivartijat asettuivat, kullakin ase kädessä, temppelin eteläsivulta aina sen pohjoissivulle saakka, päin alttaria ja temppeliä, kuninkaan ympärille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Sitten hän toi kuninkaan pojan esille, pani hänen päähänsä kruunun ja antoi hänelle lain kirjan, ja he tekivät hänet kuninkaaksi ja voitelivat hänet; ja he paukuttivat käsiänsä ja huusivat: \"Eläköön kuningas!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Kun Atalja kuuli henkivartijain ja kansan huudon, meni hän kansan luo Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'Hän näki kuninkaan seisovan pylvään vieressä, niinkuin tapa oli, ja päälliköt ja torvensoittajat kuninkaan luona, ja kaiken maan kansan, joka riemuitsi ja puhalsi torviin. Silloin Atalja repäisi vaatteensa ja huusi: \"Kapina! Kapina!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Mutta pappi Joojada käski sadanpäämiehiä, sotajoukon johtajia, ja sanoi heille: \"Viekää hänet pois rivien välitse, ja joka yrittää seurata häntä, se surmatkaa miekalla\". Sillä pappi oli sanonut: \"Älköön häntä surmattako Herran temppelissä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'Niin he kävivät häneen käsiksi, ja kun hän oli tullut tielle, jota myöten hevosia kuljetettiin kuninkaan palatsiin, surmattiin hänet siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Ja Joojada teki liiton Herran, kuninkaan ja kansan kesken, että he olisivat Herran kansa; niin myös kuninkaan ja kansan kesken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'Sitten kaikki maan kansa meni Baalin temppeliin, ja he hävittivät sen. Sen alttarit ja kuvat he löivät aivan murskaksi ja tappoivat alttarien edessä Mattanin, Baalin papin. Sitten pappi asetti vartijat vartioimaan Herran temppeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Ja hän otti mukaansa sadanpäämiehet sekä kaarilaiset ja henkivartijat ja kaiken maan kansan, ja he veivät kuninkaan Herran temppelistä ja tulivat henkivartijain portin kautta kuninkaan linnaan, ja hän istui kuninkaalliselle valtaistuimelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'Ja kaikki maan kansa iloitsi, ja kaupunki pysyi rauhallisena. Mutta Ataljan he surmasivat miekalla kuninkaan linnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Jooas oli seitsemän vuoden vanha tullessaan kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Jeehun seitsemäntenä hallitusvuotena tuli Jooas kuninkaaksi, ja hän hallitsi Jerusalemissa neljäkymmentä vuotta. Hänen äitinsä oli nimeltään Sibja Beersebasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'Ja Jooas teki sitä, mikä on oikein Herran silmissä, niin kauan kuin hän eli, sillä pappi Joojada oli opettanut häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Kuitenkaan eivät uhrikukkulat hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'Ja Jooas sanoi papeille: \"Kaiken rahan, joka pyhinä lahjoina tuodaan Herran temppeliin, käyvän rahan, kaiken arvion mukaan suoritettavan henkilörahan ja kaiken rahan, jonka joku sydämensä vaatimuksesta tuo Herran temppeliin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'sen ottakoot papit itselleen, kukin tuttavaltaan; mutta heidän on niillä korjattava, mitä on rappeutunutta Herran temppelissä, missä vain jotakin rappeutunutta on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Mutta vielä kuningas Jooaan kahdentenakymmenentenä kolmantena hallitusvuotena eivät papit olleet korjanneet mitään, mikä temppelissä oli rappeutunutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Silloin kuningas Jooas kutsui pappi Joojadan ja muut papit ja sanoi heille: \"Miksi te ette ole korjanneet mitään, mikä temppelissä on rappeutunutta? Nyt te ette enää saa ottaa rahaa tuttaviltanne, vaan teidän on annettava se siihen, mikä temppelissä on rappeutunutta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'Ja papit suostuivat siihen, etteivät ottaisi rahaa kansalta, mutta eivät myöskään korjaisi sitä, mikä temppelissä oli rappeutunutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Mutta pappi Joojada otti arkun ja kaivoi reiän sen kanteen ja asetti sen alttarin ääreen, oikealle puolelle, kun mennään Herran temppeliin. Ja papit, jotka vartioivat ovea, panivat siihen kaiken rahan, mikä Herran temppeliin tuotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'Kun he näkivät, että arkussa oli paljon rahaa, meni kuninkaan kirjuri sinne ylimmäisen papin kanssa, ja he sitoivat yhteen ja laskivat rahat, jotka olivat Herran temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'Sitten annettiin punnitut rahat työnteettäjille, jotka oli pantu valvomaan töitä Herran temppelissä; ja he maksoivat niillä puusepät ja rakentajat, jotka tekivät työtä Herran temppelissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'ynnä muurarit ja kivenhakkaajat, niin myös puutavarat ja hakatut kivet, jotka oli ostettava sen korjaamiseksi, mikä Herran temppelissä oli rappeutunutta, kaikki temppelin korjausmenot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Ei kuitenkaan teetetty Herran temppeliin hopeavateja, veitsiä, maljoja, torvia, ei mitään kulta-tai hopeakaluja, rahalla, joka tuotiin Herran temppeliin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'vaan se annettiin työmiehille, että he sillä korjaisivat Herran temppeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Eikä miehiltä, joille rahat luovutettiin työmiehille annettaviksi, vaadittu tilintekoa, vaan he toimivat luottamusmiehinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Vikauhri-ja syntiuhrirahoja ei tuotu Herran temppeliin; ne tulivat papeille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Siihen aikaan Hasael, Aramin kuningas, tuli ja ryhtyi sotimaan Gatia vastaan, ja hän valloitti sen. Sitten Hasael kävi hyökkäämään Jerusalemia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Silloin Jooas, Juudan kuningas, otti kaikki pyhät lahjat, jotka hänen isänsä, Juudan kuninkaat Joosafat, Jooram ja Ahasja, olivat pyhittäneet, ja omat pyhät lahjansa sekä kaiken kullan, mitä oli Herran temppelin aarrekammioissa ja kuninkaan linnassa, ja lähetti ne Hasaelille, Aramin kuninkaalle. Niin tämä lähti pois Jerusalemin kimpusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Mitä muuta on kerrottavaa Jooaasta ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Mutta hänen palvelijansa nousivat ja tekivät salaliiton ja surmasivat Jooaan Millo-rakennuksessa, siinä, mistä mennään alas Sillaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Hänen palvelijansa Joosakar, Simeatin poika, ja Joosabad, Soomerin poika, löivät hänet kuoliaaksi, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Ja hänen poikansa Amasja tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Juudan kuninkaan Jooaan, Ahasjan pojan, kahdentenakymmenentenä kolmantena hallitusvuotena tuli Jooahas, Jeehun poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa seitsemäntoista vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'Ja hän teki sitä, mikä on pahaa Herran silmissä, ja vaelsi Jerobeamin, Nebatin pojan, synneissä, joilla tämä oli saattanut Israelin tekemään syntiä; hän ei luopunut niistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'Niin Herran viha syttyi Israelia kohtaan, ja hän antoi heidät Hasaelin, Aramin kuninkaan, ja Benhadadin, Hasaelin pojan, käsiin koko siksi ajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Mutta Jooahas lepytti Herraa, ja Herra kuuli häntä, sillä hän näki Israelin sorron, kun Aramin kuningas sorti heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Ja Herra antoi Israelille vapauttajan, ja he pääsivät aramilaisten käsistä. Ja israelilaiset asuivat majoissansa niinkuin ennenkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Eivät he kuitenkaan luopuneet Jerobeamin suvun synneistä, joilla hän oli saattanut Israelin tekemään syntiä, vaan he vaelsivat niissä; aserakin jäi paikoilleen Samariaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Niin ei Herra jättänyt Jooahaalle väkeä enempää kuin viisikymmentä ratsumiestä, kymmenet sotavaunut ja kymmenentuhatta jalkamiestä; sillä Aramin kuningas oli hävittänyt ne ja pannut ne tomuksi, niinkuin puitaessa tulee tomua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Mitä muuta on kerrottavaa Jooahaasta, kaikesta, mitä hän teki, ja hänen urotöistänsä, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'Ja Jooahas meni lepoon isiensä tykö, ja hänet haudattiin Samariaan. Ja hänen poikansa Jooas tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Juudan kuninkaan Jooaan kolmantenakymmenentenä seitsemäntenä hallitusvuotena tuli Jooas, Jooahaan poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kuusitoista vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'Hän teki sitä, mikä on pahaa Herran silmissä: hän ei luopunut mistään Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä, vaan vaelsi niissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'Mitä muuta on kerrottavaa Jooaasta, kaikesta, mitä hän teki, ja hänen urotöistään, kuinka hän soti Juudan kuningasta Amasjaa vastaan, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'Ja Jooas meni lepoon isiensä tykö, ja Jerobeam istui hänen valtaistuimellensa. Ja Jooas haudattiin Samariaan Israelin kuningasten viereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Mutta kun Elisa sairasti kuolintautiansa, tuli Jooas, Israelin kuningas, hänen tykönsä. Ja kumartuneena hänen kasvojensa yli hän itki ja sanoi: \"Isäni, isäni! Israelin sotavaunut ja ratsumiehet!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Niin Elisa sanoi hänelle: \"Nouda jousi ja nuolia\". Ja hän nouti hänelle jousen ja nuolia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'Sitten hän sanoi Israelin kuninkaalle: \"Laske kätesi jouselle\". Ja kun hän oli laskenut kätensä, pani Elisa kätensä kuninkaan kätten päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'Ja hän sanoi: \"Avaa ikkuna itään päin\". Ja kun tämä oli avannut sen, sanoi Elisa: \"Ammu\". Ja hän ampui. Niin hän sanoi: \"Herran voitonnuoli, voitonnuoli Aramia vastaan! Sinä olet voittava aramilaiset Afekissa perinpohjin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Sitten hän sanoi: \"Ota nuolet\". Ja kun hän oli ne ottanut, sanoi hän Israelin kuninkaalle: \"Lyö maahan\". Niin hän löi kolme kertaa ja lakkasi sitten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Mutta Jumalan mies vihastui häneen ja sanoi: \"Sinun olisi pitänyt lyödä viisi tai kuusi kertaa: silloin olisit voittanut aramilaiset perinpohjin. Mutta nyt olet voittava aramilaiset ainoastaan kolme kertaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Sitten Elisa kuoli, ja hänet haudattiin. Ja mooabilaisten partiojoukkoja tuli maahan vuosi vuodelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'Ja kerran, kun he haudatessaan erästä miestä näkivät partiojoukon, heittivät he miehen Elisan hautaan ja menivät matkoihinsa. Kun mies kosketti Elisan luita, virkosi hän ja nousi jaloilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Hasael, Aramin kuningas, sorti Israelia, niin kauan kuin Jooahas eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Mutta Herra oli heille laupias, armahti heitä ja kääntyi heidän puoleensa liiton tähden, jonka hän oli tehnyt Aabrahamin, Iisakin ja Jaakobin kanssa. Sillä hän ei tahtonut tuhota heitä, eikä hän ollut vielä heittänyt heitä pois kasvojensa edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'Ja Hasael, Aramin kuningas, kuoli, ja hänen poikansa Benhadad tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Ja Jooas, Jooahaan poika, otti Benhadadilta, Hasaelin pojalta, takaisin ne kaupungit, jotka tämä oli asevoimalla ottanut hänen isältänsä Jooahaalta. Kolme kertaa Jooas voitti hänet ja otti takaisin Israelin kaupungit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Israelin kuninkaan Jooaan, Jooahaan pojan, toisena hallitusvuotena tuli Amasja, Jooaan poika, Juudan kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Jooaddin, Jerusalemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Hän teki sitä, mikä on oikein Herran silmissä, ei kuitenkaan niinkuin hänen isänsä Daavid. Kaikessa hän teki, niinkuin hänen isänsä Jooas oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Kuitenkaan eivät uhrikukkulat hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'Ja kun kuninkuus oli vahvistunut hänen käsissään, surmautti hän ne palvelijansa, jotka olivat murhanneet kuninkaan, hänen isänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Mutta murhaajain lapset hän jätti surmaamatta, niinkuin on kirjoitettu Mooseksen lain kirjaan, jossa Herra on käskenyt: \"Älköön isiä rangaistako kuolemalla lasten tähden älköönkä lapsia isien tähden; kukin rangaistakoon kuolemalla oman syntinsä tähden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Hän voitti edomilaiset Suolalaaksossa, kymmenentuhatta miestä, ja valloitti Seelan asevoimalla ja antoi sille nimen Jokteel, joka sillä tänäkin päivänä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Silloin Amasja lähetti sanansaattajat Israelin kuninkaan Jooaan, Jooahaan pojan, Jeehun pojanpojan luo ja käski sanoa hänelle: \"Tule, otelkaamme keskenämme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Mutta Jooas, Israelin kuningas, lähetti Amasjalle, Juudan kuninkaalle tämän sanan: \"Libanonilla kasvava ohdake lähetti setripuulle, joka kasvoi Libanonilla, sanan: \'Anna tyttäresi vaimoksi minun pojalleni\'. Mutta metsän eläimet Libanonilla kulkivat ohdakkeen ylitse ja tallasivat sen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Sinä olet voittanut Edomin, ja siitä olet käynyt ylpeäksi. Tyydy siihen kunniaan ja pysy kotonasi. Minkätähden tuotat onnettomuuden? Sinä kukistut itse ynnä Juuda sinun kanssasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Mutta Amasja ei totellut. Niin Jooas, Israelin kuningas, lähti liikkeelle, ja he, hän ja Amasja, Juudan kuningas, ottelivat keskenään Beet-Semeksessä, joka on Juudan aluetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'Ja israelilaiset voittivat Juudan miehet, ja nämä pakenivat kukin majallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Ja Jooas, Israelin kuningas, otti Juudan kuninkaan Amasjan, Jooaan pojan, Ahasjan pojanpojan, Beet-Semeksessä vangiksi. Kun hän tuli Jerusalemiin, revitti hän Jerusalemin muuria Efraimin portista Kulmaporttiin saakka, neljäsataa kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'Ja hän otti kaiken kullan ja hopean sekä kaikki kalut, mitä Herran temppelissä ja kuninkaan linnan aarrekammioissa oli, ynnä panttivankeja, ja palasi Samariaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Mitä muuta on kerrottavaa Jooaasta, siitä, mitä hän teki, ja hänen urotöistään, kuinka hän soti Amasjaa, Juudan kuningasta, vastaan, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'Ja Jooas meni lepoon isiensä tykö, ja hänet haudattiin Samariaan Israelin kuningasten viereen. Ja hänen poikansa Jerobeam tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Mutta Juudan kuningas Amasja, Jooaan poika, eli Israelin kuninkaan Jooaan, Jooahaan pojan, kuoleman jälkeen viisitoista vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Mitä muuta on kerrottavaa Amasjasta, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Ja häntä vastaan tehtiin Jerusalemissa salaliitto. Hän pakeni Laakiiseen, mutta Laakiiseen lähetettiin miehiä hänen jälkeensä, ja ne surmasivat hänet siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Hänet nostettiin hevosten selkään ja haudattiin Jerusalemiin isiensä viereen Daavidin kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'Mutta koko Juudan kansa otti Asarjan, joka oli kuudentoista vuoden vanha, ja teki hänet kuninkaaksi hänen isänsä Amasjan sijaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Hän linnoitti Eelatin ja palautti sen Juudalle, sittenkuin kuningas oli mennyt lepoon isiensä tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Juudan kuninkaan Amasjan, Jooaan pojan, viidentenätoista hallitusvuotena tuli Jerobeam, Jooaan poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa neljäkymmentä yksi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'Hän teki sitä, mikä on pahaa Herran silmissä; hän ei luopunut mistään Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Hän palautti entiselleen Israelin alueen, siitä, mistä mennään Hamatiin, aina Aromaan mereen saakka, sen sanan mukaan, jonka Herra, Israelin Jumala, oli puhunut palvelijansa, profeetta Joonan, Amittain pojan, kautta, joka oli kotoisin Gat-Heeferistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Sillä Herra oli nähnyt Israelin ylen katkeran kurjuuden, kuinka kaikki tyynni menehtyivät eikä Israelilla ollut auttajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'Herra ei ollut vielä sanonut, että hän oli pyyhkivä Israelin nimen pois taivaan alta, ja niin hän vapautti heidät Jerobeamin, Jooaan pojan, kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Mitä muuta on kerrottavaa Jerobeamista, kaikesta, mitä hän teki, ja hänen urotöistänsä, kuinka hän kävi sotaa ja kuinka hän palautti Israelille Damaskosta ja Hamatista sen, mikä oli ollut Juudan, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'Ja Jerobeam meni lepoon isiensä, Israelin kuningasten, tykö. Ja hänen poikansa Sakarja tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Jerobeamin, Israelin kuninkaan, kahdentenakymmenentenä seitsemäntenä hallitusvuotena tuli Asarja, Amasjan poika, Juudan kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Hän oli kuudentoista vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa viisikymmentä kaksi vuotta. Hänen äitinsä oli nimeltään Jekolja, Jerusalemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Ja hän teki sitä, mikä on oikein Herran silmissä, aivan niinkuin hänen isänsä Amasja oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Kuitenkaan eivät uhrikukkulat hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'Ja Herra löi kuningasta, niin että hän oli pitalitautinen kuolinpäiväänsä saakka. Hän asui eri talossa, mutta Jootam, kuninkaan poika, oli linnan päällikkönä ja tuomitsi maan kansaa. 15:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Mitä muuta on kerrottavaa Asarjasta ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'Ja Asarja meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Ja hänen poikansa Jootam tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Asarjan, Juudan kuninkaan, kolmantenakymmenentenä kahdeksantena hallitusvuotena tuli Sakarja, Jerobeamin poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kuusi kuukautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'Ja hän teki sitä, mikä on pahaa Herran silmissä, niinkuin hänen isänsäkin olivat tehneet; hän ei luopunut Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'Ja Sallum, Jaabeksen poika, teki salaliiton häntä vastaan ja löi hänet kuoliaaksi kansan nähden ja tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Mitä muuta on kerrottavaa Sakarjasta, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Näin toteutui Herran sana, jonka hän oli puhunut Jeehulle sanoen: \"Sinun poikasi istukoot Israelin valtaistuimella neljänteen polveen\": niin tapahtui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Sallum, Jaabeksen poika, tuli kuninkaaksi Ussian, Juudan kuninkaan, kolmantenakymmenentenä yhdeksäntenä hallitusvuotena, ja hän hallitsi Samariassa kuukauden päivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Mutta silloin Menahem, Gaadin poika, lähti liikkeelle Tirsasta, tuli Samariaan ja löi Sallumin, Jaabeksen pojan, kuoliaaksi Samariassa. Ja hän tuli kuninkaaksi tämän sijaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Mitä muuta on kerrottavaa Sallumista ja salaliitosta, jonka hän teki, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Siihen aikaan Menahem hävitti Tifsahin ja kaiken, mitä siellä oli, niin myös sen alueen Tirsasta lähtien, koska he eivät avanneet hänelle portteja; hän hävitti sen ja halkaisi kaikki raskaat vaimot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Juudan kuninkaan Asarjan kolmantenakymmenentenä yhdeksäntenä hallitusvuotena tuli Menahem, Gaadin poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kymmenen vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'Hän teki sitä, mikä on pahaa Herran edessä; hän ei luopunut koko elinaikanaan mistään Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'Puul, Assurin kuningas, hyökkäsi maahan; ja Menahem antoi Puulille tuhat talenttia hopeata, että tämä auttaisi häntä ja vahvistaisi kuninkuuden hänen käsiinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'Ja Menahem otti rahat verona Israelilta, kaikilta varakkailta miehiltä, niin että jokainen joutui maksamaan Assurin kuninkaalle viisikymmentä sekeliä hopeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Niin Assurin kuningas palasi takaisin eikä jäänyt siihen maahan. Mitä muuta on kerrottavaa Menahemista ja kaikesta, mitä hän teki, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'Ja Menahem meni lepoon isiensä tykö. Ja hänen poikansa Pekahja tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Juudan kuninkaan Asarjan viidentenäkymmenentenä hallitusvuotena tuli Pekahja, Menahemin poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kaksi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'Hän teki sitä, mikä on pahaa Herran silmissä; hän ei luopunut Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Ja Pekah, Remaljan poika, hänen vaunusoturinsa, teki salaliiton häntä vastaan ja tappoi hänet Samariassa kuninkaan linnan palatsissa, sekä hänet että Argobin ja Arjen, jolloin Pekahilla oli mukanaan viisikymmentä Gileadin miestä. Näin tämä surmasi hänet ja tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Mitä muuta on kerrottavaa Pekahjasta ja kaikesta, mitä hän teki, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Juudan kuninkaan Asarjan viidentenäkymmenentenä toisena hallitusvuotena tuli Pekah, Remaljan poika, Israelin kuninkaaksi, ja hän hallitsi Samariassa kaksikymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'Hän teki sitä, mikä on pahaa Herran silmissä; hän ei luopunut Jerobeamin, Nebatin pojan, synneistä, joilla tämä oli saattanut Israelin tekemään syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Israelin kuninkaan Pekahin aikana tuli Tiglat-Pileser, Assurin kuningas, ja valloitti Iijonin, Aabel-Beet-Maakan, Jaanoahin, Kedeksen, Haasorin, Gileadin ja Galilean, koko Naftalin maan, ja vei asukkaat pakkosiirtolaisuuteen Assuriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Mutta Hoosea, Eelan poika, teki salaliiton Pekahia, Remaljan poikaa, vastaan ja löi hänet kuoliaaksi ja tuli kuninkaaksi hänen sijaansa Jootamin, Ussian pojan, kahdentenakymmenentenä hallitusvuotena. 15:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Mitä muuta on kerrottavaa Pekahista ja kaikesta, mitä hän teki, katso, se on kirjoitettuna Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Israelin kuninkaan Pekahin, Remaljan pojan, toisena hallitusvuotena tuli Jootam, Juudan kuninkaan Ussian poika, kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi ja hallitsi Jerusalemissa kuusitoista vuotta. Hänen äitinsä oli nimeltään Jerusa, Saadokin tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'Hän teki sitä, mikä on oikein Herran silmissä, aivan niinkuin hänen isänsä Ussia oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Kuitenkaan uhrikukkulat eivät hävinneet, vaan kansa uhrasi ja suitsutti yhä edelleen uhrikukkuloilla. Hän rakennutti Yläportin Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Mitä muuta on kerrottavaa Jootamista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Niihin aikoihin alkoivat Resin, Aramin kuningas, ja Pekah, Remaljan poika, Herran lähettäminä käydä Juudan kimppuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'Ja Jootam meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen, isänsä Daavidin kaupunkiin. Ja hänen poikansa Aahas tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Pekahin, Remaljan pojan, seitsemäntenätoista hallitusvuotena tuli Aahas, Juudan kuninkaan Jootamin poika, kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Aahas oli kahdenkymmenen vuoden vanha tullessansa kuninkaaksi ja hallitsi Jerusalemissa kuusitoista vuotta. Hän ei tehnyt sitä, mikä oli oikein Herran, hänen Jumalansa, silmissä, niinkuin hänen isänsä Daavid,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'vaan vaelsi Israelin kuningasten tietä; jopa hän pani poikansakin kulkemaan tulen läpi, niiden kansain kauhistavien tekojen mukaan, jotka Herra oli karkoittanut israelilaisten tieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Ja hän uhrasi ja suitsutti uhrikukkuloilla ja kummuilla ja jokaisen viheriän puun alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Siihen aikaan Resin, Aramin kuningas, ja Pekah, Remaljan poika, Israelin kuningas, lähtivät Jerusalemiin sotimaan. Ja he saartoivat Aahaan, mutta eivät voineet valloittaa kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Samaan aikaan Resin, Aramin kuningas, palautti Eelatin Aramille ja karkoitti Juudan miehet Eelatista. Niin tulivat aramilaiset Eelatiin ja asettuivat sinne, ja siellä heitä on tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Mutta Aahas lähetti sanansaattajat Assurin kuninkaan Tiglat-Pileserin luo ja käski sanoa hänelle: \"Minä olen sinun palvelijasi ja sinun poikasi. Tule ja pelasta minut Aramin kuninkaan ja Israelin kuninkaan käsistä; he ovat hyökänneet minun kimppuuni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Ja Aahas otti hopean ja kullan, mitä Herran temppelissä ja kuninkaan palatsin aarrekammioissa oli, ja lähetti sen lahjaksi Assurin kuninkaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Ja Assurin kuningas kuuli häntä. Niin Assurin kuningas lähti Damaskoa vastaan ja valloitti sen, vei asukkaat pakkosiirtolaisuuteen Kiiriin ja surmasi Resinin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Silloin kuningas Aahas lähti Damaskoon kohtaamaan Assurin kuningasta Tiglat-Pileseriä. Ja kun kuningas Aahas näki Damaskossa olevan alttarin, lähetti hän pappi Uurialle kuvan alttarista ja sen mukaan tehdyn tarkan mallin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'Ja pappi Uuria rakensi alttarin; aivan sen määräyksen mukaan, jonka kuningas Aahas oli hänelle lähettänyt Damaskosta; aivan sen mukaan pappi Uuria teki, jo ennenkuin kuningas Aahas oli palannut Damaskosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'Ja kun kuningas palasi Damaskosta ja näki alttarin, astui hän alttarin ääreen ja nousi sen päälle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'poltti polttouhrinsa ja ruokauhrinsa, vuodatti juomauhrinsa ja vihmoi uhraamansa uhrin veren alttarille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Mutta vaskialttarin, joka oli Herran edessä, hän siirsi pois temppelin edustalta, alttarin ja Herran temppelin väliltä, ja pani sen alttarin pohjoissivulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'Ja kuningas Aahas käski pappi Uuriaa ja sanoi: \"Polta suuremmalla alttarilla aamu-polttouhri ja ehtoo-ruokauhri ja kuninkaan polttouhri sekä hänen ruokauhrinsa, niin myös koko maan kansan polttouhri sekä heidän ruoka-ja juomauhrinsa; ja vihmo kaikki sekä polttouhrin että teurasuhrin veri sen päälle. Mutta vaskialttarin käyttämistä minä vielä mietin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Ja pappi Uuria teki kaiken, mitä kuningas Aahas oli käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Kuningas Aahas leikkautti irti telineiden kehäpienat ja otti pois altaat niiden päältä; ja meren hän nostatti pois vaskiraavasten päältä, jotka olivat sen alla, ja panetti sen kivialustalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Ja katetun sapattikäytävän, joka oli rakennettu temppeliin, ja kuninkaan ulkopuolisen sisäänkäytävän hän muutti Herran temppelin sisään Assurin kuninkaan vuoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Mitä muuta on vielä kerrottavaa Aahaasta, siitä, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'Ja Aahas meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Ja hänen poikansa Hiskia tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Juudan kuninkaan Aahaan kahdentenatoista hallitusvuotena tuli Hoosea, Eelan poika, Israelin kuninkaaksi Samariaan, ja hän hallitsi yhdeksän vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'Hän teki sitä, mikä on pahaa Herran silmissä, ei kuitenkaan niinkuin ne Israelin kuninkaat, jotka olivat olleet ennen häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Hänen kimppuunsa hyökkäsi Salmaneser, Assurin kuningas; ja Hoosea tuli hänen palvelijakseen ja maksoi hänelle veroa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Mutta Assurin kuningas huomasi Hoosean olevan salahankkeissa, koska tämä lähetti sanansaattajat Soon, Egyptin kuninkaan, luo eikä suorittanut enää niinkuin ennen vuotuista veroa Assurin kuninkaalle. Niin Assurin kuningas vangitutti hänet ja piti häntä sidottuna vankilassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Ja Assurin kuningas hyökkäsi koko maan kimppuun ja meni Samariaan ja piiritti sitä kolme vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'Hoosean yhdeksäntenä hallitusvuotena Assurin kuningas valloitti Samarian ja vei Israelin pakkosiirtolaisuuteen Assuriin ja asetti heidät asumaan Halahiin ja Haaborin, Goosanin joen, rannoille sekä Meedian kaupunkeihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'Näin tapahtui, koska israelilaiset olivat tehneet syntiä Herraa, Jumalaansa, vastaan, joka oli johdattanut heidät Egyptin maasta, pois faraon, Egyptin kuninkaan, käsistä, ja koska he olivat peljänneet muita jumalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'He olivat myös vaeltaneet niiden kansain säädösten mukaan, jotka Herra oli karkoittanut israelilaisten tieltä, ja tehneet sitä, mitä Israelin kuninkaatkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Israelilaiset olivat tehneet Herraa, Jumalaansa, vastaan sellaista, mikä ei ole oikein: he olivat rakentaneet itsellensä uhrikukkuloita kaikkiin kaupunkeihinsa, sekä vartiotornien luo että varustettuihin kaupunkeihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'He olivat pystyttäneet itsellensä patsaita ja asera-karsikkoja jokaiselle korkealle kummulle ja jokaisen viheriän puun alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'He olivat polttaneet uhreja kaikilla uhrikukkuloilla, niinkuin ne kansat, jotka Herra oli karkoittanut heidän tieltänsä, olivat harjoittaneet pahuutta ja vihoittaneet Herran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'He olivat palvelleet kivijumalia, vaikka Herra oli heille sanonut: \"Älkää tehkö sitä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'Ja Herra oli varoittanut sekä Israelia että Juudaa kaikkien profeettainsa, kaikkien näkijäin, kautta ja sanonut: \"Palatkaa pahoilta teiltänne ja noudattakaa minun käskyjäni ja säädöksiäni, kaiken sen lain mukaan, jonka minä annoin teidän isillenne ja jonka minä olen teille ilmoittanut palvelijaini, profeettain, kautta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Mutta he eivät kuulleet, vaan olivat niskureita niinkuin heidän isänsäkin, jotka eivät uskoneet Herraan, Jumalaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'He hylkäsivät hänen käskynsä ja hänen liittonsa, jonka hän oli tehnyt heidän isiensä kanssa, ja todistukset, jotka hän oli heille antanut. He seurasivat turhia jumalia, ja turhanpäiväisiksi he tulivat, kun seurasivat pakanakansoja, jotka asuivat heidän ympärillänsä, vaikka Herra oli kieltänyt heitä tekemästä niinkuin ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'He hylkäsivät Herran, Jumalansa, kaikki käskyt ja tekivät itsellensä valettuja kuvia, kaksi vasikkaa. Ja he tekivät itsellensä myös asera-karsikkoja ja kumarsivat kaikkea taivaan joukkoa ja palvelivat Baalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Ja he panivat poikansa ja tyttärensä kulkemaan tulen läpi ja tekivät taikoja ja harjoittivat noituutta. He myivät itsensä tekemään sitä, mikä on pahaa Herran silmissä, ja vihoittivat hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Niin Herra vihastui suuresti Israeliin ja poisti heidät kasvojensa edestä, niin ettei muuta jäänyt jäljelle kuin Juudan sukukunta yksin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Ei myöskään Juuda pitänyt Herran, Jumalansa, käskyjä, vaan he vaelsivat niiden säädösten mukaan, jotka Israel itse oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Niin Herra hylkäsi koko Israelin heimon, nöyryytti heitä ja antoi heidät ryöstäjien käsiin ja heitti viimein heidät pois kasvojensa edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Sillä kun hän oli reväissyt Israelin Daavidin suvulta ja he olivat tehneet kuninkaaksi Jerobeamin, Nebatin pojan, käänsi Jerobeam Israelin pois Herrasta ja saattoi heidät tekemään suuren synnin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'Ja israelilaiset vaelsivat kaikissa synneissä, joita Jerobeam oli tehnyt; he eivät luopuneet niistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'Ja niin Herra viimein poisti Israelin kasvojensa edestä, niinkuin hän oli puhunut kaikkien palvelijainsa, profeettain, kautta. Ja Israel vietiin pois maastansa pakkosiirtolaisuuteen Assuriin, jossa he ovat tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Sen jälkeen Assurin kuningas antoi tuoda kansaa Baabelista, Kuutasta, Avvasta, Hamatista ja Sefarvaimista ja asetti heidät asumaan Samarian kaupunkeihin israelilaisten sijaan. Ja he ottivat Samarian omaksensa ja asettuivat sen kaupunkeihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'Ja kun he siellä olonsa ensi aikoina eivät peljänneet Herraa, lähetti Herra heidän sekaansa leijonia, jotka tappoivat heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Se ilmoitettiin Assurin kuninkaalle näin: \"Kansat, jotka sinä veit pakkosiirtolaisuuteen ja asetit asumaan Samarian kaupunkeihin, eivät tiedä, millä tavalla sen maan Jumalaa on palveltava. Sentähden hän on lähettänyt leijonia heidän sekaansa, ja katso, ne surmaavat heitä, koska he eivät tiedä, millä tavalla sen maan Jumalaa on palveltava.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Silloin Assurin kuningas käski sanoen: \"Viekää sinne joku niistä papeista, jotka toitte sieltä pakkosiirtolaisuuteen; joku heistä menköön sinne ja asukoon siellä ja opettakoon heille, millä tavalla sen maan Jumalaa on palveltava.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Ja niin eräs niistä papeista, jotka he olivat vieneet Samariasta pakkosiirtolaisuuteen, tuli ja asettui Beeteliin; ja hän opetti heille, kuinka heidän oli peljättävä Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Mutta kukin kansa teki itselleen omat jumalansa, ja he panivat ne samarialaisten rakentamiin uhrikukkula-temppeleihin, kukin kansa niissä kaupungeissa, joissa se asui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Baabelin miehet tekivät itselleen Sukkot-Benotin, Kuutin miehet tekivät Neergalin, Hamatin miehet Asiman,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'avvalaiset tekivät Nibhaan ja Tartakin, sefarvaimilaiset polttivat poikiansa tulessa Adrammelekille ja Annammelekille, Sefarvaimin jumalille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Mutta he pelkäsivät myöskin Herraa. Ja he asettivat itsellensä uhrikukkula-pappeja omasta keskuudestaan, ja nämä uhrasivat heidän puolestaan uhrikukkula-temppeleissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'He pelkäsivät tosin Herraa, mutta palvelivat myös omia jumaliansa samalla tavalla kuin ne kansat, joiden keskuudesta heidät oli tuotu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Ja vielä tänäkin päivänä he tekevät vanhan tapansa mukaan: he eivät pelkää Herraa eivätkä tee saamiensa säädösten ja oikeuksien mukaan, eivät sen lain ja niiden käskyjen mukaan, jotka Herra on antanut Jaakobin pojille, hänen, jolle hän antoi nimen Israel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Herra teki liiton näiden kanssa ja käski heitä sanoen: \"Älkää peljätkö muita jumalia, älkää kumartako ja palvelko niitä älkääkä uhratko niille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'vaan Herraa, joka johdatti teidät Egyptin maasta suurella voimalla ja ojennetulla käsivarrella, häntä te peljätkää, häntä kumartakaa ja hänelle uhratkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Ja niitä säädöksiä ja oikeuksia, sitä lakia ja niitä käskyjä, jotka hän on teille kirjoittanut, te alati tarkoin noudattakaa, mutta älkää peljätkö muita jumalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Liittoa, jonka minä tein teidän kanssanne, älkää unhottako. Älkääkä peljätkö muita jumalia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'vaan peljätkää ainoastaan Herraa, teidän Jumalaanne, niin hän pelastaa teidät kaikkien vihollistenne käsistä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Mutta he eivät totelleet, vaan tekivät vanhan tapansa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Niin nämä kansat pelkäsivät Herraa, mutta palvelivat samalla omia jumalankuviansa. Myöskin heidän lapsensa ja heidän lastensa lapset tekevät vielä tänä päivänä samoin, kuin heidän isänsä ovat tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Israelin kuninkaan Hoosean, Eelan pojan, kolmantena hallitusvuotena tuli Hiskia, Juudan kuninkaan Aahaan poika, kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Hän oli kahdenkymmenen viiden vuoden vanha tullessansa kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Abi, Sakarjan tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'Hän teki sitä, mikä on oikein Herran silmissä, aivan niinkuin hänen isänsä Daavid oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'Hän poisti uhrikukkulat, murskasi patsaat, hakkasi maahan asera-karsikon ja löi palasiksi vaskikäärmeen, jonka Mooses oli tehnyt; sillä niihin aikoihin asti israelilaiset olivat polttaneet uhreja sille; sitä kutsuttiin nimellä Nehustan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'Hän turvasi Herraan, Israelin Jumalaan, niin ettei kukaan ollut hänen kaltaisensa kaikista hänen jälkeläisistään Juudan kuninkaista eikä niistä, jotka olivat olleet ennen häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Hän riippui Herrassa kiinni eikä luopunut hänestä, vaan noudatti hänen käskyjänsä, jotka Herra oli antanut Moosekselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'Niin Herra oli hänen kanssansa; hän menestyi kaikessa, mihin ryhtyi. Hän kapinoi Assurin kuningasta vastaan eikä enää palvellut häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Hän voitti filistealaiset ja valtasi heidän alueensa aina Gassaan asti, sekä vartiotornit että varustetut kaupungit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Mutta kuningas Hiskian neljäntenä hallitusvuotena, joka oli Israelin kuninkaan Hoosean, Eelan pojan, seitsemäs hallitusvuosi, hyökkäsi Salmaneser, Assurin kuningas, Samarian kimppuun ja piiritti sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'Ja hän valloitti sen kolmen vuoden kuluttua. Hiskian kuudentena hallitusvuotena, joka oli Israelin kuninkaan Hoosean yhdeksäs hallitusvuosi, valloitettiin Samaria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Ja Assurin kuningas vei Israelin pakkosiirtolaisuuteen Assuriin ja sijoitti heidät Halahiin ja Haaborin, Goosanin joen, rannoille ja Meedian kaupunkeihin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'sentähden että he eivät olleet kuulleet Herran, Jumalansa, ääntä, vaan olivat rikkoneet hänen liittonsa, kaiken, mitä Mooses, Herran palvelija, oli käskenyt; he eivät olleet kuulleet sitä eivätkä tehneet sen mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Kuningas Hiskian neljäntenätoista hallitusvuotena hyökkäsi Sanherib, Assurin kuningas, kaikkien Juudan varustettujen kaupunkien kimppuun ja valloitti ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'Niin Hiskia, Juudan kuningas, lähetti Assurin kuninkaalle Laakiiseen sanan: \"Minä olen rikkonut, käänny pois minun kimpustani. Minä kannan, mitä panet kannettavakseni.\" Niin Assurin kuningas määräsi Hiskian, Juudan kuninkaan, maksettavaksi kolmesataa talenttia hopeata ja kolmekymmentä talenttia kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'Ja Hiskia antoi kaikki rahat, mitä Herran temppelissä ja kuninkaan linnan aarrekammioissa oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Siihen aikaan Hiskia leikkautti irti Herran temppelin ovista ja pihtipielistä sen päällystyksen, jolla Hiskia, Juudan kuningas, oli päällystänyt ne, ja antoi sen Assurin kuninkaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Mutta Assurin kuningas lähetti Laakiista Tartanin ja ylimmäisen hoviherran ja Rabsaken suuren sotajoukon kanssa kuningas Hiskiaa vastaan Jerusalemiin. Ja nämä lähtivät liikkeelle ja tulivat Jerusalemiin; ja lähdettyänsä liikkeelle ja tultuansa he pysähtyivät Ylälammikon vesijohdolle, joka on Vanuttajankedon tien varrella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'Kun he sitten kutsuivat kuningasta, menivät Eljakim, Hilkian poika, joka oli linnan päällikkönä, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, heidän luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'Ja Rabsake sanoi heille: \"Sanokaa Hiskialle: Näin sanoo suurkuningas, Assurin kuningas: \'Mitä on tuo luottamus, mikä sinulla on?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Arvelet kai, että pelkästä huulten puheesta tulee neuvo ja voima sodankäyntiin. Keneen sinä oikein luotat, kun kapinoit minua vastaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Katso, sinä luotat nyt Egyptiin, tuohon särkyneeseen ruokosauvaan, joka tunkeutuu sen käteen, joka siihen nojaa, ja lävistää sen. Sellainen on farao, Egyptin kuningas, kaikille, jotka häneen luottavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Vai sanotteko te ehkä minulle: Me luotamme Herraan, meidän Jumalaamme? Mutta eikö hän ole se, jonka uhrikukkulat ja alttarit Hiskia poisti, kun hän sanoi Juudalle ja Jerusalemille: Tämän alttarin edessä on teidän kumartaen rukoiltava, täällä Jerusalemissa?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Mutta lyö nyt vetoa minun herrani, Assurin kuninkaan, kanssa: minä annan sinulle kaksi tuhatta hevosta, jos sinä voit hankkia niille ratsastajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Kuinka sinä sitten voisit torjua ainoankaan käskynhaltijan, ainoankaan minun herrani vähimmän palvelijan, hyökkäyksen? Ja sinä vain luotat Egyptiin, sen vaunuihin ja ratsumiehiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Olenko minä siis Herran sallimatta hyökännyt tämän paikan kimppuun hävittämään sitä? Herra itse on sanonut minulle: \'Hyökkää tähän maahan ja hävitä se\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Niin Eljakim, Hilkian poika, ja Sebna ja Jooah sanoivat Rabsakelle: \"Puhu palvelijoillesi araminkieltä, sillä me ymmärrämme sitä; älä puhu meidän kanssamme juudankieltä kansan kuullen, jota on muurilla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Mutta Rabsake vastasi heille: \"Onko minun herrani lähettänyt minut puhumaan näitä sanoja sinun herrallesi ja sinulle? Eikö juuri niille miehille, jotka istuvat muurilla ja joutuvat teidän kanssanne syömään omaa likaansa ja juomaan omaa vettänsä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Sitten Rabsake astui esiin, huusi kovalla äänellä juudankielellä, puhui ja sanoi: \"Kuulkaa suurkuninkaan, Assurin kuninkaan, sana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Näin sanoo kuningas: \'Älkää antako Hiskian pettää itseänne, sillä hän ei voi pelastaa teitä minun käsistäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'Älköön Hiskia saako teitä luottamaan Herraan, kun hän sanoo: Herra on varmasti pelastava meidät, eikä tätä kaupunkia anneta Assurin kuninkaan käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Älkää kuulko Hiskiaa.\' Sillä Assurin kuningas sanoo näin: \'Tehkää sovinto minun kanssani ja antautukaa minulle, niin te saatte syödä kukin omasta viinipuustanne ja viikunapuustanne ja juoda kukin omasta kaivostanne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'kunnes minä tulen ja vien teidät maahan, joka on teidän maanne kaltainen, vilja-,viini-ja leipämaahan, viinitarhojen, jalon öljypuun ja hunajan maahan; ja niin te saatte elää ettekä kuole. Mutta älkää kuulko Hiskiaa; sillä hän viettelee teidät, kun sanoo: Herra pelastaa meidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Onko muidenkaan kansojen jumalista yksikään pelastanut maatansa Assurin kuninkaan käsistä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Missä ovat Hamatin ja Arpadin jumalat? Missä ovat Sefarvaimin, Heenan ja Ivvan jumalat? Ovatko ne pelastaneet Samariaa minun käsistäni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Onko muiden maiden kaikista jumalista ainoakaan pelastanut maatansa minun käsistäni? Kuinka sitten Herra pelastaisi Jerusalemin minun käsistäni?\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Mutta kansa oli vaiti, eivätkä he vastanneet hänelle mitään; sillä kuningas oli käskenyt niin ja sanonut: \"Älkää vastatko hänelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Sitten palatsin päällikkö Eljakim, Hilkian poika, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, tulivat Hiskian luo vaatteet reväistyinä ja kertoivat hänelle, mitä Rabsake oli sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'Kun kuningas Hiskia sen kuuli, repäisi hän vaatteensa, pukeutui säkkiin ja meni Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'Ja hän lähetti palatsin päällikön Eljakimin ja kirjuri Sebnan sekä pappien vanhimmat, säkkeihin puettuina, profeetta Jesajan, Aamoksen pojan, tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Ja he sanoivat hänelle: \"Näin sanoo Hiskia: \'Hädän, kurituksen ja häväistyksen päivä on tämä päivä, sillä lapset ovat tulleet kohdun suulle saakka, mutta ei ole voimaa synnyttää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Ehkä Herra, sinun Jumalasi, kuulee kaikki Rabsaken sanat, joilla hänen herransa, Assurin kuningas, on lähettänyt hänet herjaamaan elävää Jumalaa, ja rankaisee häntä näistä sanoista, jotka Herra, sinun Jumalasi, on kuullut. Niin kohota nyt rukous jäännöksen puolesta, joka vielä on olemassa.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Kun kuningas Hiskian palvelijat tulivat Jesajan tykö,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'sanoi Jesaja heille: \"Sanokaa näin herrallenne: \'Näin sanoo Herra: Älä pelkää niitä sanoja, jotka olet kuullut ja joilla Assurin kuninkaan poikaset ovat häväisseet minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Katso, minä annan häneen mennä sellaisen hengen, että hän kuultuaan sanoman palaa omaan maahansa. Ja minä annan hänen kaatua miekkaan omassa maassansa.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Ja Rabsake kääntyi takaisin ja tapasi Assurin kuninkaan sotimassa Libnaa vastaan; sillä hän oli kuullut, että tämä oli lähtenyt Laakiista pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'Mutta kun Sanherib kuuli Tirhakasta, Etiopian kuninkaasta, sanottavan: \"Katso, hän on lähtenyt liikkeelle sotiakseen sinua vastaan\", lähetti hän taas sanansaattajat Hiskian tykö ja käski sanoa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, '\"Sanokaa näin Hiskialle, Juudan kuninkaalle: \'Älä anna Jumalasi, johon sinä luotat, pettää itseäsi äläkä ajattele: Jerusalem ei joudu Assurin kuninkaan käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Olethan kuullut, mitä Assurin kuninkaat ovat tehneet kaikille maille, kuinka he ovat vihkineet ne tuhon omiksi. Ja sinäkö pelastuisit!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Ovatko kansain jumalat pelastaneet niitä, jotka minun isäni ovat tuhonneet: Goosania, Harrania, Resefiä ja Telassarin edeniläisiä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Missä on Hamatin kuningas ja Arpadin kuningas, Sefarvaimin kaupungin, Heenan ja Ivvan kuningas?\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Kun Hiskia oli ottanut kirjeen sanansaattajilta ja lukenut sen, meni hän Herran temppeliin; ja Hiskia levitti sen Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'Ja Hiskia rukoili Herran edessä ja sanoi: \"Herra, Israelin Jumala, jonka valtaistuinta kerubit kannattavat, sinä yksin olet maan kaikkien valtakuntain Jumala; sinä olet tehnyt taivaan ja maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Herra, kallista korvasi ja kuule; Herra, avaa silmäsi ja katso. Kuule Sanheribin sanat, kuinka hän lähetti tuon miehen herjaamaan elävää Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Se on totta, Herra, että Assurin kuninkaat ovat hävittäneet kansat ja heidän maansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'Ja he ovat heittäneet heidän jumalansa tuleen; sillä ne eivät olleet jumalia, vaan ihmiskätten tekoa, puuta ja kiveä, ja sentähden he voivat hävittää ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Mutta pelasta nyt meidät, Herra, meidän Jumalamme, hänen käsistänsä, että kaikki maan valtakunnat tulisivat tietämään, että sinä, Herra, yksin olet Jumala.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Niin Jesaja, Aamoksen poika, lähetti Hiskialle tämän sanan: \"Näin sanoo Herra, Israelin Jumala: Mitä sinä olet minulta Sanheribin, Assurin kuninkaan, tähden rukoillut, sen minä olen kuullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'Ja tämä on sana, jonka Herra on puhunut hänestä: Neitsyt, tytär Siion, halveksii ja pilkkaa sinua; tytär Jerusalem nyökyttää ilkkuen päätänsä sinun jälkeesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Ketä olet herjannut ja häväissyt, ja ketä vastaan olet korottanut äänesi? Korkealle olet kohottanut silmäsi Israelin Pyhää vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Sanansaattajaisi kautta sinä herjasit Herraa ja sanoit: \'Monilla vaunuillani minä nousin vuorten harjalle, Libanonin ääriin saakka; minä hakkasin maahan sen korkeat setrit, sen parhaat kypressit, ja tunkeuduin sen etäisimpään yöpaikkaan, sen rehevimpään metsään;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'minä kaivoin kaivoja ja join kuiviin muukalaisten vedet, ja jalkapohjallani minä kuivasin kaikki Egyptin virrat\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Etkö ole kuullut: kauan sitten minä olen tätä valmistanut, muinaisuudesta saakka tätä aivoitellut! Nyt minä olen sen toteuttanut, ja niin sinä sait hävittää varustetut kaupungit autioiksi kiviroukkioiksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'ja niiden asukkaat olivat voimattomat, he kauhistuivat ja joutuivat häpeään; heidän kävi niinkuin kedon ruohon ja niinkuin vihannan heinän, niinkuin katolla kasvavain kortten ja niinkuin laihon, joka kuivettuu ennen oljelle tulemistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Istuitpa sinä tai lähdit tai tulit, minä sen tiedän, niinkuin senkin, että sinä raivoat minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Koska sinä minua vastaan raivoat ja koska sinun ylpeytesi on tullut minun korviini, niin minä panen koukkuni sinun nenääsi ja suitseni sinun suuhusi ja vien sinut takaisin samaa tietä, jota tulitkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'Ja tämä on oleva sinulle merkkinä: tänä vuonna syödään jälkikasvua ja toisena vuonna kesanto-aaluvaa, mutta kolmantena vuonna te kylväkää ja leikatkaa, istuttakaa viinitarhoja ja syökää niiden hedelmää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Ja Juudan heimon pelastuneet, jotka ovat jäljelle jääneet, tekevät taas juurta alaspäin ja hedelmää ylöspäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Sillä Jerusalemista lähtee kasvamaan jäännös, pelastunut joukko Siionin vuorelta. Herran kiivaus on sen tekevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Sentähden, näin sanoo Herra Assurin kuninkaasta: Hän ei tule tähän kaupunkiin eikä siihen nuolta ammu, ei tuo sitä vastaan kilpeä eikä luo sitä vastaan vallia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Samaa tietä, jota hän tuli, hän palajaa, ja tähän kaupunkiin hän ei tule, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Sillä minä varjelen tämän kaupungin ja pelastan sen itseni tähden ja palvelijani Daavidin tähden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'Ja sinä yönä Herran enkeli lähti ja löi Assurin leirissä sata kahdeksankymmentä viisi tuhatta miestä, ja kun noustiin aamulla varhain, niin katso, ne olivat kaikki kuolleina ruumiina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Silloin Sanherib, Assurin kuningas, lähti liikkeelle ja meni pois; hän palasi takaisin ja jäi Niiniveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Mutta kun hän oli kerran rukoilemassa jumalansa Nisrokin temppelissä, surmasivat Adrammelek ja Sareser hänet miekalla; sitten he pakenivat Araratin maahan. Ja hänen poikansa Eesarhaddon tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'Niihin aikoihin Hiskia sairastui ja oli kuolemaisillansa; ja profeetta Jesaja, Aamoksen poika, tuli hänen tykönsä ja sanoi hänelle: \"Näin sanoo Herra: Toimita talosi; sillä sinä kuolet etkä enää parane\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Niin hän käänsi kasvonsa seinään päin ja rukoili Herraa sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, '\"Oi Herra, muista, kuinka minä olen vaeltanut sinun edessäsi uskollisesti ja ehyellä sydämellä ja tehnyt sitä, mikä on hyvää sinun silmissäsi!\" Ja Hiskia itki katkerasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Mutta Jesaja ei ollut vielä lähtenyt keskimmäiseltä esipihalta, kun hänelle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, '\"Palaja takaisin ja sano Hiskialle, minun kansani ruhtinaalle: \'Näin sanoo Herra, sinun isäsi Daavidin Jumala: Minä olen kuullut sinun rukouksesi, olen nähnyt sinun kyyneleesi. Katso, minä parannan sinut: jo kolmantena päivänä sinä menet Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'Ja minä lisään sinulle ikää viisitoista vuotta. Ja minä pelastan sinut ja tämän kaupungin Assurin kuninkaan käsistä. Minä varjelen tätä kaupunkia itseni tähden ja palvelijani Daavidin tähden.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Ja Jesaja sanoi: \"Toimittakaa tänne viikunakakkua\". Niin he toivat sitä ja panivat paiseen päälle; ja hän parani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Ja Hiskia sanoi Jesajalle: \"Mikä on merkkinä siitä, että Herra on parantava minut, niin että minä kolmantena päivänä voin mennä Herran temppeliin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Jesaja sanoi: \"Tämä on oleva sinulle merkkinä Herralta siitä, että Herra tekee, mitä hän on sanonut: varjo kulkee kymmenen astetta eteenpäin tahi siirtyy kymmenen astetta takaisin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Hiskia sanoi: \"Varjon on helppo pidetä kymmenen astetta. Ei, vaan siirtyköön varjo takaisin kymmenen astetta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Silloin profeetta Jesaja huusi Herraa, ja hän antoi varjon Aahaan aurinkokellossa siirtyä takaisin kymmenen astetta, jotka se oli jo laskeutunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Siihen aikaan Merodak-Baladan, Baladanin poika, Baabelin kuningas, lähetti kirjeen ja lahjoja Hiskialle, sillä hän oli kuullut, että Hiskia oli ollut sairaana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'Ja kuultuansa heitä Hiskia näytti heille koko varastohuoneensa, hopean ja kullan, hajuaineet ja kalliin öljyn ja koko asehuoneensa ja kaikki, mitä hänen aarrekammioissansa oli. Ei ollut mitään Hiskian talossa eikä koko hänen valtakunnassaan, mitä hän ei olisi heille näyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Mutta profeetta Jesaja tuli kuningas Hiskian tykö ja sanoi hänelle: \"Mitä nämä miehet ovat sanoneet, ja mistä he ovat tulleet sinun tykösi?\" Hiskia vastasi: \"He ovat tulleet kaukaisesta maasta, Baabelista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'Hän sanoi: \"Mitä he ovat nähneet sinun talossasi?\" Hiskia vastasi: \"Kaiken, mitä talossani on, he ovat nähneet; minun aarrekammioissani ei ole mitään, mitä en olisi heille näyttänyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Niin Jesaja sanoi Hiskialle: \"Kuule Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Katso, päivät tulevat, jolloin kaikki, mitä sinun talossasi on ja mitä sinun isäsi ovat koonneet tähän päivään asti, viedään pois Baabeliin; ei mitään jää jäljelle, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Ja sinun omia poikiasi, jotka sinusta polveutuvat, jotka sinulle syntyvät, viedään hovipalvelijoiksi Baabelin kuninkaan palatsiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Hiskia sanoi Jesajalle: \"Herran sana, jonka olet puhunut, on hyvä\". Sillä hän ajatteli: \"Onpahan rauha ja turvallisuus minun päivinäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Mitä muuta on kerrottavaa Hiskiasta ja kaikista hänen urotöistään, ja kuinka hän rakensi lammikon ja vesijohdon ja johti veden kaupunkiin, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'Ja Hiskia meni lepoon isiensä tykö. Ja hänen poikansa Manasse tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manasse oli kahdentoista vuoden vanha tullessansa kuninkaaksi, ja hän hallitsi Jerusalemissa viisikymmentä viisi vuotta. Hänen äitinsä oli nimeltään Hefsibah.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'Hän teki sitä, mikä on pahaa Herran silmissä, niiden kansain kauhistavien tekojen mukaan, jotka Herra oli karkoittanut israelilaisten tieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Hän rakensi jälleen uhrikukkulat, jotka hänen isänsä Hiskia oli hävittänyt, ja pystytti alttareja Baalille ja teki aseran, niinkuin Israelin kuningas Ahab oli tehnyt, kumarsi ja palveli kaikkea taivaan joukkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Hän rakensi alttareja myös Herran temppeliin, josta paikasta Herra oli sanonut: \"Jerusalemiin minä asetan nimeni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Hän rakensi alttareja kaikelle taivaan joukolle Herran temppelin molempiin esipihoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Myös pani hän poikansa kulkemaan tulen läpi, ennusteli merkeistä, harjoitti noituutta ja hankki itsellensä vainaja-ja tietäjähenkien manaajia; hän teki paljon sitä, mikä on pahaa Herran silmissä, ja vihoitti hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Ja teettämänsä Aseran kuvan hän asetti temppeliin, josta Herra oli sanonut Daavidille ja hänen pojallensa Salomolle: \"Tähän temppeliin ja Jerusalemiin, jonka minä olen valinnut kaikista Israelin sukukunnista, minä asetan nimeni ikiajoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'Enkä minä anna enää Israelin jalkojen harhailla pois siitä maasta, jonka minä olen antanut heidän isillensä, jos he vain kaikessa noudattavat sitä, mitä minä olen käskenyt heidän noudattaa-koko sitä lakia, jonka minun palvelijani Mooses on heille antanut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Mutta he eivät totelleet, ja Manasse eksytti heidät tekemään pahaa enemmän kuin ne kansat, jotka Herra oli hävittänyt israelilaisten tieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Niin Herra puhui palvelijainsa, profeettain, kautta ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, '\"Koska Manasse, Juudan kuningas, on tehnyt nämä kauhistavat teot ja siten tehnyt pahaa enemmän kuin amorilaiset, jotka olivat ennen häntä, ja on saattanut kivijumalillansa myös Juudan tekemään syntiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'sentähden sanoo Herra, Israelin Jumala, näin: Katso, minä annan sellaisen onnettomuuden kohdata Jerusalemia ja Juudaa, että joka sen kuulee, sen molemmat korvat soivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Ja minä mittaan Jerusalemin samalla mittanuoralla kuin Samarian ja punnitsen sen samalla vaa\'alla kuin Ahabin suvun. Ja minä huuhdon Jerusalemin, niinkuin vati huuhdotaan: se huuhdotaan ja käännetään kumollensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'Minä hylkään perintöosani jäännöksen ja annan heidät vihollistensa käsiin, niin että he joutuvat kaikkien vihollistensa saaliiksi ja ryöstettäviksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'koska ovat tehneet sitä, mikä on pahaa minun silmissäni, ja vihoittaneet minua siitä päivästä asti, jona heidän isänsä lähtivät Egyptin maasta, tähän päivään saakka.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Manasse vuodatti myös sangen paljon viatonta verta, niin että hän sillä täytti Jerusalemin ääriään myöten, sen syntinsä lisäksi, jolla hän saattoi Juudan tekemään syntiä, tekemään sitä, mikä on pahaa Herran silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Mitä muuta on kerrottavaa Manassesta ja kaikesta, mitä hän teki, ja synnistä, minkä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'Ja Manasse meni lepoon isiensä tykö, ja hänet haudattiin linnansa puutarhaan, Ussan puutarhaan. Ja hänen poikansa Aamon tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Aamon oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksi vuotta. Hänen äitinsä oli nimeltään Mesullemet, Haaruksen tytär, Jotbasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'Hän teki sitä, mikä on pahaa Herran silmissä, niinkuin hänen isänsä Manasse oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'Hän vaelsi kaikessa samaa tietä, mitä hänen isänsä oli vaeltanut: hän palveli niitä kivijumalia, joita hänen isänsä oli palvellut, ja kumarsi niitä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'hän hylkäsi Herran, isiensä Jumalan, eikä vaeltanut Herran tietä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Ja Aamonin palvelijat tekivät salaliiton häntä vastaan ja tappoivat kuninkaan hänen linnassansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Mutta maan kansa surmasi kaikki, jotka olivat tehneet salaliiton kuningas Aamonia vastaan. Ja maan kansa teki hänen poikansa Joosian kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Mitä muuta on kerrottavaa Aamonista, siitä, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'Ja hänet haudattiin omaan hautaansa Ussan puutarhaan. Ja hänen poikansa Joosia tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Joosia oli kahdeksan vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kolmekymmentä yksi vuotta. Hänen äitinsä oli nimeltään Jedida, Adajan tytär, Boskatista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'Hän teki sitä, mikä on oikein Herran silmissä, ja vaelsi kaikessa isänsä Daavidin tietä, poikkeamatta oikealle tai vasemmalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'Kahdeksantenatoista hallitusvuotenaan kuningas Joosia lähetti kirjuri Saafanin, Asaljan pojan, Mesullamin pojanpojan, Herran temppeliin ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, '\"Mene ylimmäisen papin Hilkian luo, että hän lukisi valmiiksi Herran temppeliin tuodut rahat, joita ovenvartijat ovat koonneet kansalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'Ja hän antakoon ne työnteettäjille, jotka on pantu valvomaan töitä Herran temppelissä, ja nämä maksakoot niillä työmiehet, jotka ovat Herran temppelissä korjaamassa sitä, mikä temppelissä on rappeutunutta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'puusepät, rakentajat ja muurarit, sekä temppelin korjaamista varten ostettavat puutavarat ja hakatut kivet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Älköön heiltä kuitenkaan vaadittako tilintekoa rahoista, jotka heille luovutetaan, vaan toimikoot he luottamusmiehinä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'Ja ylimmäinen pappi Hilkia sanoi kirjuri Saafanille: \"Minä löysin Herran temppelistä lain kirjan\". Ja Hilkia antoi kirjan Saafanille, ja tämä luki sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Sitten kirjuri Saafan meni kuninkaan tykö ja teki kuninkaalle selon asiasta, sanoen: \"Palvelijasi ovat ottaneet esille rahat, mitä temppelissä oli, ja ovat antaneet ne työnteettäjille, jotka on pantu valvomaan töitä Herran temppelissä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Ja kirjuri Saafan kertoi kuninkaalle sanoen: \"Pappi Hilkia antoi minulle erään kirjan\". Ja Saafan luki sen kuninkaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Kun kuningas kuuli lain kirjan sanat, repäisi hän vaatteensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'Ja kuningas käski pappi Hilkiaa, Ahikamia, Saafanin poikaa, Akboria, Miikajan poikaa, kirjuri Saafania ja Asajaa, kuninkaan palvelijaa, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, '\"Menkää ja kysykää minun ja kansan ja koko Juudan puolesta neuvoa Herralta tästä löydetystä kirjasta. Sillä suuri on Herran viha, joka on syttynyt meitä vastaan, koska meidän isämme eivät ole totelleet tämän kirjan sanoja eivätkä tehneet mitään kaikesta siitä, mitä siinä on meille kirjoitettuna.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Niin pappi Hilkia, Ahikam, Akbor, Saafan ja Asaja menivät naisprofeetta Huldan tykö, joka oli vaatevaraston hoitajan Sallumin, Tikvan pojan, Harhaan pojanpojan, vaimo ja asui Jerusalemissa, toisessa kaupunginosassa. He puhuivat hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Niin hän sanoi heille: \"Näin sanoo Herra, Israelin Jumala: Sanokaa sille miehelle, joka lähetti teidät minun tyköni:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, '\'Näin sanoo Herra: Katso, minä annan tätä paikkaa ja sen asukkaita kohdata onnettomuuden, kaiken, mitä sanotaan siinä kirjassa, jonka Juudan kuningas on lukenut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'sillä he ovat hyljänneet minut ja polttaneet uhreja muille jumalille ja vihoittaneet minut kaikilla kättensä teoilla; ja minussa on syttynyt viha tätä paikkaa kohtaan, eikä se sammu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Mutta Juudan kuninkaalle, joka on lähettänyt teidät kysymään neuvoa Herralta, sanokaa näin: Näin sanoo Herra, Israelin Jumala, niistä sanoista, jotka sinä olet kuullut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Koska sinun sydämesi on pehminnyt ja sinä olet nöyrtynyt Herran edessä, kuullessasi, mitä minä olen puhunut tätä paikkaa ja sen asukkaita vastaan, että he tulevat kauhistukseksi ja kiroussanaksi, ja koska sinä olet reväissyt vaatteesi ja itkenyt minun edessäni, niin minäkin olen kuullut sinua, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Sentähden minä korjaan sinut isiesi tykö, ja sinä saat rauhassa siirtyä hautaasi, ja sinun silmäsi pääsevät näkemästä kaikkea sitä onnettomuutta, minkä minä annan kohdata tätä paikkaa.\'\" Ja he toivat kuninkaalle tämän vastauksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Niin kuningas lähetti kokoamaan luoksensa kaikki Juudan ja Jerusalemin vanhimmat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Ja kuningas meni Herran temppeliin, ja hänen kanssaan kaikki Juudan miehet ja kaikki Jerusalemin asukkaat, myöskin papit ja profeetat, koko kansa pienimmästä suurimpaan. Ja hän luki heidän kuultensa kaikki Herran temppelistä löydetyn liitonkirjan sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Ja kuningas asettui pylvään viereen ja teki Herran edessä liiton, että heidän tuli seurata Herraa, noudattaa hänen käskyjänsä, todistuksiansa ja säädöksiänsä kaikesta sydämestään ja kaikesta sielustaan ja pitää liiton sanat, jotka olivat kirjoitettuina siinä kirjassa. Ja kaikki kansa yhtyi siihen liittoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'Sitten kuningas käski ylimmäistä pappia Hilkiaa ja häntä lähimpiä pappeja sekä ovenvartijoita viemään Herran temppelistä pois kaikki kalut, mitä oli tehty Baalille, Aseralle ja kaikelle taivaan joukolle. Ja hän poltatti ne Jerusalemin ulkopuolella Kidronin kedoilla, mutta vei niiden tuhan Beeteliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Hän pani myös viralta epäjumalain papit, jotka Juudan kuninkaat olivat asettaneet polttamaan uhreja uhrikukkuloilla Juudan kaupungeissa ja Jerusalemin ympäristössä ja jotka polttivat uhreja Baalille, auringolle, kuulle, eläinradan tähdille ja kaikelle taivaan joukolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Hän vei aseran pois Herran temppelistä Jerusalemin ulkopuolelle Kidronin laaksoon ja poltti sen Kidronin laaksossa, rouhensi sen tomuksi ja heitti tomun yhteiselle hautausmaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Ja hän kukisti haureellisten pyhäkköpoikien huoneet, jotka olivat Herran temppelissä ja joissa naiset kutoivat verhoja Aseralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Hän toi pois kaikki papit Juudan kaupungeista ja saastutti uhrikukkulat, joilla papit olivat polttaneet uhreja, Gebasta Beersebaan asti. Ja hän kukisti porteilla olevat uhrikukkulat, joita oli kaupungin päällikön Joosuan portin oven edustalla, vasemmalla puolella mentäessä sisään kaupungin portista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Uhrikukkulapapit eivät kuitenkaan saaneet nousta Herran alttarille Jerusalemissa; he saivat vain syödä happamatonta leipää veljiensä kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Hän saastutti myöskin polttopaikan Ben-Hinnomin laaksossa, ettei kukaan voisi panna poikaansa tai tytärtänsä kulkemaan tulen läpi Molokin kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Ja hän poisti ne hevoset, jotka Juudan kuninkaat olivat auringon kunniaksi asettaneet, siitä, mistä mennään Herran temppeliin, hoviherra Netan-Melekin kammion vierestä, joka oli Parvarimissa, ja poltti auringonvaunut tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Ja Aahaan yläsalin katolla olevat alttarit, jotka Juudan kuninkaat olivat teettäneet, ja ne alttarit, jotka Manasse oli teettänyt Herran temppelin molempiin esipihoihin, kuningas kukisti; sitten hän riensi sieltä ja heitti niiden tomun Kidronin laaksoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Ja ne uhrikukkulat, jotka olivat itään päin Jerusalemista, etelään päin Turmiovuoresta, ja jotka Salomo, Israelin kuningas, oli rakentanut Astartelle, siidonilais-iljetykselle, ja Kemokselle, Mooabin iljetykselle, ja Milkomille, ammonilais-kauhistukselle, ne kuningas saastutti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'Hän murskasi patsaat ja hakkasi maahan asera-karsikot ja täytti niiden sijan ihmisten luilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Myöskin Beetelissä olevan alttarin, sen uhrikukkulan, jonka oli teettänyt Jerobeam, Nebatin poika, joka saattoi Israelin tekemään syntiä, senkin alttarin uhrikukkuloineen hän kukisti; sitten hän poltti uhrikukkulan ja rouhensi sen tomuksi sekä poltti asera-karsikon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'Kun Joosia sitten kääntyi ja näki haudat, jotka olivat vuorella, lähetti hän ottamaan luut haudoista, poltti ne alttarilla ja saastutti näin alttarin, Herran sanan mukaan, jonka oli julistanut se Jumalan mies, joka nämä julisti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Ja hän kysyi: \"Mikä tuo hautamerkki on, jonka minä näen?\" Kaupungin miehet vastasivat hänelle: \"Se on sen Jumalan miehen hauta, joka tuli Juudasta ja julisti sen, minkä sinä nyt olet tehnyt Beetelin alttarille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'Hän sanoi: \"Antakaa hänen olla; älköön kukaan koskeko hänen luihinsa\". Niin he jättivät hänen luunsa rauhaan ja samoin sen profeetan luut, joka oli tullut Samariasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Myöskin Samarian kaupungeista Joosia poisti kaikki uhrikukkulatemppelit, jotka Israelin kuninkaat olivat rakentaneet ja niin vihoittaneet Herran; ja hän teki niille saman, minkä oli tehnyt Beetelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Ja kaikki siellä olevat uhrikukkulapapit hän teurasti alttareilla ja poltti ihmisten luita niiden päällä. Sitten hän palasi takaisin Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Ja kuningas käski kaikkea kansaa sanoen: \"Viettäkää pääsiäistä Herran, teidän Jumalanne, kunniaksi, niinkuin on kirjoitettuna tässä liitonkirjassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Sillä sellaista pääsiäistä ei oltu vietetty sen ajan jälkeen, jona tuomarit tuomitsivat Israelia, ei Israelin kuningasten eikä Juudan kuningasten koko aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Vasta kuningas Joosian kahdeksantenatoista hallitusvuotena vietettiin sellainen pääsiäinen Jerusalemissa Herran kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Myöskin vainaja-ja tietäjähenkien manaajat, kotijumalat ja kivijumalat ja kaikki iljetykset, joita oli nähty Juudan maassa ja Jerusalemissa, Joosia hävitti, täyttääkseen lain sanat, jotka olivat kirjoitettuina siinä kirjassa, minkä pappi Hilkia oli löytänyt Herran temppelistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'Ei ollut ennen häntä ollut hänen vertaistansa kuningasta, joka niin kaikesta sydämestänsä, kaikesta sielustansa ja kaikesta voimastansa olisi kääntynyt Herran puoleen, kaiken Mooseksen lain mukaan; eikä hänen jälkeensä tullut hänen vertaistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Kuitenkaan ei Herra kääntynyt suuren vihansa hehkusta, kun kerran hänen vihansa oli syttynyt Juudaa vastaan kaikesta siitä, millä Manasse oli vihoittanut hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Ja Herra sanoi: \"Minä toimitan myöskin Juudan pois kasvojeni edestä, niinkuin minä olen toimittanut pois Israelin; ja minä hylkään Jerusalemin, tämän kaupungin, jonka minä olin valinnut, ja temppelin, josta minä olin sanonut: \'Minun nimeni on oleva siinä\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Mitä muuta on kerrottavaa Joosiasta ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Hänen aikanansa farao Neko, Egyptin kuningas, lähti Assurin kuningasta vastaan Eufrat-virralle. Niin kuningas Joosia meni häntä vastaan, mutta farao surmasi hänet Megiddossa heti, kun näki hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'Ja hänen palvelijansa veivät hänet kuolleena vaunuissa Megiddosta, toivat hänet Jerusalemiin ja hautasivat hänet hänen omaan hautaansa. Mutta maan kansa otti Joosian pojan Jooahaan, voiteli hänet ja teki hänet kuninkaaksi hänen isänsä sijaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Jooahas oli kahdenkymmenen kolmen vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi kolme kuukautta Jerusalemissa. Hänen äitinsä oli nimeltään Hamutal, Jeremian tytär, Libnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'Ja hän teki sitä, mikä on pahaa Herran silmissä, aivan niinkuin hänen isänsä olivat tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'Mutta farao Neko vangitutti hänet Riblassa, Hamatin maassa, ettei hän hallitsisi Jerusalemissa, ja määräsi maan maksettavaksi pakkoveron: sata talenttia hopeata ja kymmenen talenttia kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'Ja farao Neko teki Eljakimin, Joosian pojan, kuninkaaksi hänen isänsä Joosian sijaan ja muutti hänen nimensä Joojakimiksi. Mutta Jooahaan hän otti vangiksi, ja tämä joutui Egyptiin; siellä hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'Hopean ja kullan Joojakim maksoi faraolle; mutta voidakseen maksaa rahat faraon käskyn mukaan hän veroitti maata, ottaen maan kansalta, sen mukaan kuin kukin oli verotettu, hopeata ja kultaa, antaakseen farao Nekolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Joojakim oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hänen äitinsä oli nimeltään Sebida, Pedajan tytär, Ruumasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'Hän teki sitä, mikä on pahaa Herran silmissä, aivan niinkuin hänen isänsä olivat tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Hänen aikanaan Nebukadnessar, Baabelin kuningas, lähti liikkeelle, ja Joojakim tuli hänen palvelijakseen. Kolmen vuoden kuluttua tämä jälleen kapinoi häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Ja Herra lähetti hänen kimppuunsa kaldealaisten, aramilaisten, mooabilaisten ja ammonilaisten partiojoukkoja; hän lähetti ne Juudan kimppuun sitä tuhoamaan, Herran sanan mukaan, jonka hän oli puhunut palvelijainsa, profeettain, kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Mutta tämä tapahtui Juudalle Herran käskystä; ja näin hän toimitti heidät pois kasvojensa edestä Manassen syntien tähden, kaiken tähden, mitä hän oli tehnyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'ja myöskin viattoman veren tähden, minkä hän oli vuodattanut täyttäessään Jerusalemin viattomalla verellä; sitä ei Herra tahtonut antaa anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Mitä muuta on kerrottavaa Joojakimista ja kaikesta, mitä hän teki, se on kirjoitettuna Juudan kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'Ja Joojakim meni lepoon isiensä tykö. Ja hänen poikansa Joojakin tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Egyptin kuningas ei enää lähtenyt maastansa, sillä Baabelin kuningas oli vallannut kaiken, mikä oli Egyptin kuninkaan omaa, Egyptin purosta aina Eufrat-virtaan saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Joojakin oli kahdeksantoista vuoden vanha tullessansa kuninkaaksi, ja hän hallitsi Jerusalemissa kolme kuukautta. Hänen äitinsä oli nimeltään Nehusta, Elnatanin tytär, Jerusalemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'Hän teki sitä, mikä on pahaa Herran silmissä, aivan niinkuin hänen isänsä oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Siihen aikaan Baabelin kuninkaan Nebukadnessarin palvelijat tulivat Jerusalemiin, ja kaupunki saarrettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Ja Nebukadnessar, Baabelin kuningas, ryntäsi kaupunkiin, hänen palvelijainsa saartaessa sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Niin Joojakin, Juudan kuningas, antautui Baabelin kuninkaalle äitineen ja palvelijoineen, päällikköineen ja hoviherroineen. Ja Baabelin kuningas otti hänet vangiksi kahdeksantena hallitusvuotenaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'Ja hän vei pois sieltä kaikki Herran temppelin ja kuninkaan linnan aarteet, ja hän rikkoi kaikki kultakalut, jotka Israelin kuningas Salomo oli teettänyt Herran temppeliin. Tapahtui, niinkuin Herra oli puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'Ja hän vei pakkosiirtolaisuuteen koko Jerusalemin, kaikki päälliköt ja kaikki sotaurhot, kymmenentuhatta pakkosiirtolaista, ja kaikki sepät ja lukkosepät; ei jäänyt jäljelle muita kuin maakansan köyhät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Hän siirsi Joojakinin vankina Baabeliin; samoin hän vei kuninkaan äidin, kuninkaan puolisot ja hänen hoviherransa sekä muut maan mahtavat pakkosiirtolaisina Jerusalemista Baabeliin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'niin myös kaikki sotilaat, luvultaan seitsemäntuhatta, sepät ja lukkosepät, luvultaan tuhat, kaikki sotaan harjaantuneita urhoja. Ne Baabelin kuningas vei pakkosiirtolaisina Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'Mutta Baabelin kuningas asetti hänen setänsä Mattanjan kuninkaaksi hänen sijaansa ja muutti hänen nimensä Sidkiaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Sidkia oli kahdenkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hänen äitinsä oli nimeltään Hamutal, Jeremian tytär, Libnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'Hän teki sitä, mikä on pahaa Herran silmissä, aivan samoin kuin Joojakim oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Sillä Herran vihan tähden kävi näin Jerusalemille ja Juudalle, kunnes hän vihdoin heitti heidät pois kasvojensa edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Sidkia kapinoi Baabelin kuningasta vastaan. Hänen yhdeksäntenä hallitusvuotenaan, sen kymmenennessä kuussa, kuukauden kymmenentenä päivänä, kävi Nebukadnessar, Baabelin kuningas, hän ja koko hänen sotajoukkonsa, Jerusalemin kimppuun ja asettui leiriin sitä vastaan. Ja he rakensivat saartovarusteet sitä vastaan yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'Näin kaupunkia piiritettiin kuningas Sidkian yhdenteentoista hallitusvuoteen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Mutta neljännen kuukauden yhdeksäntenä päivänä, kun nälänhätä ahdisti kaupunkia eikä ollut leipää maan kansalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'valloitettiin kaupunki, ja kaikki sotilaat pakenivat yöllä molempien muurien välistä porttitietä, joka oli kuninkaan puutarhan puolella, kaldealaisten ollessa kaupungin ympärillä, ja he kulkivat Aromaahan päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Mutta kaldealaisten sotajoukko ajoi kuningasta takaa, ja he saavuttivat hänet Jerikon aroilla; ja kaikki hänen sotaväkensä oli jättänyt hänet ja hajaantunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Ja he ottivat kuninkaan kiinni ja veivät hänet Baabelin kuninkaan eteen Riblaan; ja hänelle julistettiin tuomio:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'Sidkian pojat teurastettiin hänen silmiensä edessä, ja Sidkialta itseltään hän sokaisutti silmät ja kytketti hänet vaskikahleisiin, ja hänet vietiin Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Viidennessä kuussa, kuukauden seitsemäntenä päivänä, Baabelin kuninkaan Nebukadnessarin yhdeksäntenätoista hallitusvuotena, tuli Baabelin kuninkaan palvelija Nebusaradan, henkivartijain päällikkö, Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'Hän poltti Herran temppelin ja kuninkaan linnan ja kaikki Jerusalemin talot; kaikki ylhäisten talot hän poltti tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Ja koko kaldealaisten sotajoukko, joka henkivartijain päälliköllä oli mukanaan, repi maahan Jerusalemin muurit, yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Ja Nebusaradan, henkivartijain päällikkö, vei pakkosiirtolaisuuteen kansan tähteet, mitä oli jäljellä kaupungissa, sekä ne, jotka olivat menneet Baabelin kuninkaan puolelle, ja muun rahvaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Mutta osan maan köyhiä henkivartijain päällikkö jätti jäljelle viinitarhureiksi ja peltomiehiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Vaskipylväät, jotka olivat Herran temppelissä, altaiden telineet ja vaskimeren, jotka olivat Herran temppelissä, kaldealaiset särkivät ja veivät vasken Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Ja kattilat, lapiot, veitset, kupit ja kaikki vaskikalut, joita oli käytetty jumalanpalveluksessa, he ottivat pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Samoin otti henkivartijain päällikkö hiilipannut ja maljat, jotka olivat läpeensä kultaa tai hopeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Molempien pylväiden, meren ja telineiden, jotka Salomo oli teettänyt Herran temppeliin-näiden kaikkien esineiden vaski ei ollut punnittavissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Toisen pylvään korkeus oli kahdeksantoista kyynärää, ja sen päässä oli pylväänpää vaskesta; pylväänpään korkeus oli kolme kyynärää, ja pylväänpään päällä oli ristikkokoriste ja granaattiomenia yltympäri, kaikki vaskea; ja samanlaiset oli toisessa pylväässä ristikkokoristeen päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Henkivartijain päällikkö otti ylimmäisen papin Serajan ja häntä lähimmän papin Sefanjan sekä kolme ovenvartijaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'ja kaupungista hän otti yhden hoviherran, joka oli sotaväen tarkastaja, ja viisi kuninkaan lähintä miestä, jotka tavattiin kaupungista, sekä sotapäällikön kirjurin, jonka tehtävänä oli ottaa maan kansaa sotapalvelukseen, ja kuusikymmentä miestä maan kansasta, jotka tavattiin kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Nämä otti Nebusaradan, henkivartijain päällikkö, ja vei heidät Baabelin kuninkaan eteen Riblaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'Ja Baabelin kuningas antoi lyödä heidät kuoliaaksi Riblassa Hamatin maassa. Ja niin Juuda vietiin pois maastansa pakkosiirtolaisuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Mutta sen väen käskynhaltijaksi, joka jäi Juudan maahan, sen, jonka Nebukadnessar, Baabelin kuningas, jätti sinne, hän asetti Gedaljan, Ahikamin pojan, Saafanin pojanpojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Kun kaikki sotaväen päälliköt, he ja heidän miehensä, kuulivat, että Baabelin kuningas oli asettanut Gedaljan käskynhaltijaksi, tulivat he miehinensä Gedaljan luo Mispaan, nimittäin Ismael, Netanjan poika, Joohanan, Kaareahin poika, netofalainen Seraja, Tanhumetin poika, ja Jaasanja, maakatilaisen poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Ja Gedalja vannoi heille ja heidän miehillensä ja sanoi heille: \"Älkää peljätkö kaldealaisten palvelijoita. Jääkää maahan ja palvelkaa Baabelin kuningasta, niin te menestytte.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Mutta seitsemännessä kuussa tuli Ismael, Netanjan poika, Elisaman pojanpoika, joka oli kuninkaallista sukua, mukanaan kymmenen miestä, ja he löivät kuoliaaksi Gedaljan ja ne Juudan miehet ja kaldealaiset, jotka olivat hänen kanssansa Mispassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Silloin nousi kaikki kansa, pienimmästä suurimpaan, ja samoin sotaväen päälliköt, ja he menivät Egyptiin, sillä he pelkäsivät kaldealaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Mutta kolmantenakymmenentenä seitsemäntenä vuotena siitä, kun Joojakin, Juudan kuningas, oli viety pakkosiirtolaisuuteen, kahdennessatoista kuussa, kuukauden kahdentenakymmenentenä seitsemäntenä päivänä, korotti Evil-Merodak, Baabelin kuningas, samana vuonna, jona hän tuli kuninkaaksi, Juudan kuninkaan Joojakinin pään, vapauttaen hänet vankilasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'Ja hän puhutteli häntä ystävällisesti ja asetti hänen istuimensa ylemmäksi muitten kuningasten istuimia, jotka olivat hänen tykönänsä Baabelissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Hän sai panna pois vangin puvun ja aina aterioida hänen luonaan, niin kauan kuin eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Ja hän sai kuninkaalta elatuksensa, mitä kunakin päivänä tarvitsi, vakinaisen elatuksen, niin kauan kuin eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Aadam, Seet, Enos,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Keenan, Mahalalel, Jered,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Hanok, Metusalah, Lemek,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Nooa, Seem, Haam ja Jaafet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Jaafetin pojat olivat Goomer, Maagog, Maadai, Jaavan, Tuubal, Mesek ja Tiiras.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'Ja Goomerin pojat olivat Askenas, Diifat ja Toogarma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Ja Jaavanin pojat olivat Elisa ja Tarsisa, kittiläiset ja roodanilaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Haamin pojat olivat Kuus, Misraim, Puut ja Kanaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Ja Kuusin pojat olivat Seba, Havila, Sabta, Raema ja Sabteka. Ja Raeman pojat olivat Saba ja Dedan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Ja Kuusille syntyi Nimrod; hän oli ensimmäinen valtias maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Ja Misraimille syntyivät luudilaiset, anamilaiset, lehabilaiset, naftuhilaiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'patrokselaiset ja kasluhilaiset, joista filistealaiset ovat lähteneet, sekä kaftorilaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Ja Kanaanille syntyivät Siidon, hänen esikoisensa, ja Heet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'sekä jebusilaiset, amorilaiset, girgasilaiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'hivviläiset, arkilaiset, siiniläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'arvadilaiset, semarilaiset ja hamatilaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Seemin pojat olivat Eelam, Assur, Arpaksad, Luud, Aram, Uus, Huul, Geter ja Mesek.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'Ja Arpaksadille syntyi Selah, ja Selahille syntyi Eeber.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Ja Eeberille syntyi kaksi poikaa; toisen nimi oli Peleg, sillä hänen aikanansa jakaantuivat maan asukkaat, ja hänen veljensä nimi oli Joktan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'Ja Joktanille syntyivät Almodad, Selef, Hasarmavet, Jerah,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadoram, Uusal, Dikla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Eebal, Abimael, Saba,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Oofir, Havila ja Joobab. Kaikki nämä olivat Joktanin poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Seem, Arpaksad, Selah,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Eeber, Peleg, Regu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Naahor, Terah,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram, se on Aabraham.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Aabrahamin pojat olivat Iisak ja Ismael.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'Tämä on heidän sukuluettelonsa: Nebajot, Ismaelin esikoinen, Keedar, Adbeel, Mibsan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma, Duuma, Massa, Hadad, Teema,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Naafis ja Keedma. Nämä olivat Ismaelin pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Ja Keturan, Aabrahamin sivuvaimon, pojat, jotka tämä synnytti, olivat Simran, Joksan, Medan, Midian, Jisbak ja Suuah. Joksanin pojat olivat Saba ja Dedan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Ja Midianin pojat olivat Eefa, Eefer, Hanok, Abida ja Eldaa. Kaikki nämä olivat Keturan jälkeläisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'Ja Aabrahamille syntyi Iisak. Iisakin pojat olivat Eesau ja Israel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Eesaun pojat olivat Elifas, Reguel, Jeus, Jaelam ja Koorah.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Elifaan pojat olivat Teeman, Oomar, Sefi, Gaetam, Kenas, Timna ja Amalek.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Reguelin pojat olivat Nahat, Serah, Samma ja Missa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'Seirin pojat olivat Lootan, Soobal, Sibon, Ana, Diison, Eeser ja Diisan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'Lootanin pojat olivat Hoori ja Hoomam; ja Lootanin sisar oli Timna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Soobalin pojat olivat Aljan, Maanahat, Eebal, Sefi ja Oonan. Ja Sibonin pojat olivat Aija ja Ana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Anan pojat olivat Diison. Ja Diisonin pojat olivat Hamran, Esban, Jitran ja Keran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Eeserin pojat olivat Bilhan, Saavan ja Jaakan. Diisanin pojat olivat Uus ja Aran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Ja nämä olivat ne kuninkaat, jotka hallitsivat Edomin maassa, ennenkuin mikään kuningas oli hallinnut israelilaisia: Bela, Beorin poika; ja hänen kaupunkinsa nimi oli Dinhaba.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'Ja kun Bela kuoli, tuli Joobab, Serahin poika, Bosrasta, kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'Kun Joobab kuoli, tuli Huusam, teemanilaisten maasta, kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'Kun Huusam kuoli, tuli Hadad, Bedadin poika, kuninkaaksi hänen sijaansa, hän, joka voitti midianilaiset Mooabin maassa; ja hänen kaupunkinsa nimi oli Avit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'Kun Hadad kuoli, tuli Samla, Masrekasta, kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'Kun Samla kuoli, tuli Saul, virran rannalla olevasta Rehobotista, kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'Kun Saul kuoli, tuli Baal-Haanan, Akborin poika, kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'Kun Baal-Haanan kuoli, tuli Hadad kuninkaaksi hänen sijaansa, ja hänen kaupunkinsa nimi oli Paagi; ja hänen vaimonsa nimi oli Mehetabel, Matredin tytär, joka oli Mee-Saahabin tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'Ja Hadad kuoli; ja Edomin sukuruhtinaat olivat: ruhtinas Timna, ruhtinas Alva, ruhtinas Jetet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'ruhtinas Oholibama, ruhtinas Eela, ruhtinas Piinon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'ruhtinas Kenas, ruhtinas Teeman, ruhtinas Mibsar,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'ruhtinas Magdiel, ruhtinas Iiram. Nämä olivat Edomin sukuruhtinaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Nämä olivat Israelin pojat: Ruuben, Simeon, Leevi ja Juuda, Isaskar ja Sebulon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Daan, Joosef ja Benjamin, Naftali, Gaad ja Asser.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Juudan pojat olivat Eer, Oonan ja Seela; nämä kolme synnytti hänelle Suuahin tytär, kanaanilainen. Mutta Eer, Juudan esikoinen, ei ollut otollinen Herran silmissä; sentähden hän antoi hänen kuolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Ja Taamar, Juudan miniä, synnytti hänelle Pereksen ja Serahin. Juudan poikia oli kaikkiaan viisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Pereksen pojat olivat Hesron ja Haamul.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Ja Serahin pojat olivat Simri, Eetan, Heeman, Kalkol ja Daara; heitä oli kaikkiaan viisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Ja Karmin pojat olivat Aakar, joka syöksi Israelin onnettomuuteen, kun oli uskoton ja anasti tuhon omaksi vihittyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Ja Eetanin poika oli Asarja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'Ja Hesronin pojat, jotka hänelle syntyivät, olivat Jerahmeel, Raam ja Kelubai.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ja Raamille syntyi Amminadab, ja Amminadabille syntyi Nahson, Juudan jälkeläisten ruhtinas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'Ja Nahsonille syntyi Salma, ja Salmalle syntyi Booas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'Ja Booaalle syntyi Oobed, ja Oobedille syntyi Iisai.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'Ja Iisaille syntyi esikoisena Eliab, toisena Abinadab, kolmantena Simea,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'neljäntenä Netanel, viidentenä Raddai,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'kuudentena Oosem ja seitsemäntenä Daavid.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'Ja heidän sisarensa olivat Seruja ja Abigail. Ja Serujan pojat olivat Abisai, Jooab ja Asael, kaikkiaan kolme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'Ja Abigail synnytti Amasan; ja Amasan isä oli ismaelilainen Jeter.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Ja Kaalebille, Hesronin pojalle, syntyi lapsia Asubasta, hänen vaimostaan, ja Jeriotista; ja nämä olivat Asuban pojat: Jeeser, Soobab ja Ardon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'Ja kun Asuba kuoli, nai Kaaleb Efratin, ja tämä synnytti hänelle Huurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'Ja Huurille syntyi Uuri, ja Uurille syntyi Besalel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Senjälkeen meni Hesron Maakirin, Gileadin isän, tyttären tykö; ja hän nai tämän ollessaan kuudenkymmenen vuoden vanha. Ja tämä synnytti hänelle Segubin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'Ja Segubille syntyi Jaair; tällä oli kaksikymmentä kolme kaupunkia Gileadin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Mutta gesurilaiset ja aramilaiset ottivat heiltä Jaairin leirikylät ja Kenatin ynnä sen tytärkaupungit, kuusikymmentä kaupunkia. Kaikki nämä olivat Maakirin, Gileadin isän, poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'Kun Hesron oli kuollut Kaaleb-Efratassa, synnytti Abia-hän oli Hesronin vaimo-hänelle Ashurin, Tekoan isän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Ja Jerahmeelin, Hesronin esikoisen, pojat olivat Raam, esikoinen, ja Buuna, Ooren, Oosem ja Ahia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Ja Jerahmeelilla oli vielä toinen vaimo, jonka nimi oli Atara; hän oli Oonamin äiti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Ja Raamin, Jerahmeelin esikoisen, pojat olivat Maas, Jaamin ja Eeker.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Ja Oonamin pojat olivat Sammai ja Jaada; ja Sammain pojat olivat Naadab ja Abisur.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'Ja Abisurin vaimon nimi oli Abihail, ja tämä synnytti hänelle Ahbanin ja Moolidin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Ja Naadabin pojat olivat Seled ja Appaim. Ja Seled kuoli lapsetonna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'Ja Appaimin poika oli Jisi; ja Jisin poika oli Seesan; ja Seesanin poika oli Ahlai.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Ja Jaadan, Sammain veljen, pojat olivat Jeter ja Joonatan. Jeter kuoli lapsetonna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'Ja Joonatanin pojat olivat Pelet ja Saasa. Nämä olivat Jerahmeelin jälkeläisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Mutta Seesanilla ei ollut poikia, vaan ainoastaan tyttäriä. Ja Seesanilla oli egyptiläinen palvelija, jonka nimi oli Jarha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'Ja Seesan antoi tyttärensä vaimoksi palvelijallensa Jarhalle, ja hän synnytti tälle Attain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Ja Attaille syntyi Naatan, ja Naatanille syntyi Saabad.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'Ja Saabadille syntyi Eflal, ja Eflalille syntyi Oobed.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'Ja Oobedille syntyi Jeehu, ja Jeehulle syntyi Asarja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'Ja Asarjalle syntyi Heles, ja Helekselle syntyi Eleasa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Ja Eleasalle syntyi Sismai, ja Sismaille syntyi Sallum.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Ja Sallumille syntyi Jekamja, ja Jekamjalle syntyi Elisama.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'Ja Kaalebin, Jerahmeelin veljen, pojat olivat Meesa, hänen esikoisensa, joka oli Siifin isä, ja Maaresan, Hebronin isän, pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'Ja Hebronin pojat olivat Koorah, Tappuah, Rekem ja Sema.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'Ja Semalle syntyi Raham, Jorkeamin isä, ja Rekemille syntyi Sammai.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'Ja Sammain poika oli Maaon, ja Maaon oli Beet-Suurin isä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Ja Eefa, Kaalebin sivuvaimo, synnytti Haaranin, Moosan ja Gaaseksen; ja Haaranille syntyi Gaases.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'Ja Jahdain pojat olivat Regem, Jootam, Geesan, Pelet, Eefa ja Saaf.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Maaka, Kaalebin sivuvaimo, synnytti Seberin ja Tirhanan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Hän synnytti myös Saafin, Madmannan isän, Sevan, Makbenan isän ja Gibean isän. Ja Kaalebin tytär oli Aksa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Nämä olivat Kaalebin jälkeläisiä. Huurin, Efratan esikoisen, pojat olivat Soobal, Kirjat-Jearimin isä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, Beetlehemin isä, ja Haaref, Beet-Gaaderin isä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Soobalin, Kirjat-Jearimin isän, jälkeläiset olivat Rooe ja toinen puoli Menuhotia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'Kirjat-Jearimin suvut olivat jeteriläiset, puutilaiset, suumatilaiset ja misrailaiset. Heistä ovat soratilaiset ja estaolilaiset lähteneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Ja Salman jälkeläiset olivat Beetlehem ja netofalaiset, Atrot, Beet-Jooab ja toinen puoli manahtilaisia, sorilaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'Ja kirjanoppineiden suvut, jotka asuivat Jaebeksessa, olivat tiratilaiset, simatilaiset ja sukatilaiset. Nämä olivat ne keeniläiset, jotka polveutuvat Hammatista, Reekabin suvun isästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Nämä ovat ne Daavidin pojat, jotka syntyivät hänelle Hebronissa: esikoinen Amnon, jisreeliläisestä Ahinoamista; toinen Daniel, karmelilaisesta Abigailista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'kolmas Absalom, Maakan, Gesurin kuninkaan Talmain tyttären, poika; neljäs Adonia, Haggitin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'viides Sefatja, Abitalista; kuudes Jitream, hänen vaimostaan Eglasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Nämä kuusi syntyivät hänelle Hebronissa, jossa hän hallitsi seitsemän vuotta ja kuusi kuukautta. Mutta Jerusalemissa hän hallitsi kolmekymmentä kolme vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Ja nämä syntyivät hänelle Jerusalemissa: Simea, Soobab, Naatan ja Salomo, kaikkiaan neljä, Bat-Suuasta, Ammielin tyttärestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'sitten Jibhar, Elisama, Elifelet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Noogah, Nefeg, Jaafia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eljada ja Elifelet; kaikkiaan yhdeksän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Tässä ovat kaikki Daavidin pojat, lukuunottamatta sivuvaimojen poikia. Ja Taamar oli heidän sisarensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Ja Salomon poika oli Rehabeam; tämän poika Abia; tämän poika Aasa; tämän poika Joosafat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'tämän poika Jooram; tämän poika Ahasja; tämän poika Jooas;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'tämän poika Amasja; tämän poika Asarja; tämän poika Jootam;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'tämän poika Aahas; tämän poika Hiskia; tämän poika Manasse;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'tämän poika Aamon; tämän poika Joosia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'Ja Joosian pojat olivat esikoinen Joohanan, toinen Joojakim, kolmas Sidkia, neljäs Sallum.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Ja Joojakimin pojat olivat hänen poikansa Jekonja ja tämän poika Sidkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'Ja vangitun Jekonjan pojat olivat: hänen poikansa Sealtiel,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malkiram, Pedaja, Senassar, Jekamja, Hoosama ja Nedabja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'Ja Pedajan pojat olivat Serubbaabel ja Siimei. Ja Serubbaabelin pojat olivat Mesullam ja Hananja, ja heidän sisarensa oli Selomit;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'vielä Hasuba, Oohel, Berekja, Hasadja ja Juusab-Hesed, kaikkiaan viisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'Ja Hananjan pojat olivat Pelatja ja Jesaja, Refajan pojat, Arnanin pojat, Obadjan pojat ja Sekanjan pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'Ja Sekanjan poika oli Semaja; ja Semajan pojat olivat Hattus, Jigal, Baariah, Nearja ja Saafat, kaikkiaan kuusi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'Ja Nearjan pojat olivat Eljoenai, Hiskia, Asrikam, kaikkiaan kolme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'Ja Eljoenain pojat olivat Hoodavja, Eljasib, Pelaja, Akkub, Joohanan, Delaja ja Anani, kaikkiaan seitsemän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Juudan pojat olivat Peres, Hesron, Karmi, Huur ja Soobal.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Ja Reajalle, Soobalin pojalle, syntyi Jahat, ja Jahatille syntyivät Ahumai ja Lahad. Nämä ovat soratilaisten suvut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Ja nämä olivat Eetamin isän pojat: Jisreel, Jisma ja Jidbas; ja heidän sisarensa nimi oli Haslelponi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'vielä Penuel, Gedorin isä, ja Eeser, Huusan isä. Nämä olivat Huurin, Efratan esikoisen, Beetlehemin isän, pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Ja Ashurilla, Tekoan isällä, oli kaksi vaimoa, Hela ja Naara.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'Ja Naara synnytti hänelle Ahussamin, Heeferin, Teemenin ja ahastarilaiset. Nämä olivat Naaran pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Ja Helan pojat olivat Seret, Soohar ja Etnan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'Ja Koosille syntyivät Aanub ja Soobeba sekä Aharhelin, Haarumin pojan, suvut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'Mutta Jabes oli suuremmassa arvossa pidetty kuin hänen veljensä; ja hänen äitinsä oli antanut hänelle nimen Jabes sanoen: \"Olen synnyttänyt hänet kipuja kärsien\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'Ja Jabes huusi Israelin Jumalaa, sanoen: \"Jospa sinä siunaisit minua ja laajentaisit minun alueeni; jospa sinun kätesi olisi minun kanssani ja sinä varjelisit pahasta, niin että minä pääsisin kipuja kärsimästä!\" Ja Jumala antoi hänen pyyntönsä toteutua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'Ja Kelubille, Suuhan veljelle, syntyi Mehir; hän oli Estonin isä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'Ja Estonille syntyivät Beet-Raafa, Paaseah ja Tehinna, Naahaan kaupungin isä. Nämä olivat Reekan miehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'Ja Kenaan pojat olivat Otniel ja Seraja. Ja Otnielin pojat olivat: Hatat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'Ja Meonotaille syntyi Ofra. Ja Serajalle syntyi Jooab, Seppäinlaakson isä; sillä he olivat seppiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Ja Kaalebin, Jefunnen pojan, pojat olivat Iiru, Eela ja Naam sekä Eelan pojat ja Kenas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'Ja Jehallelelin pojat olivat Siif, Siifa, Tiireja ja Asarel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'Ja Esran pojat olivat Jeter, Mered, Eefer ja Jaalon. Ja vaimo tuli raskaaksi ja synnytti Mirjamin, Sammain ja Jisbahin, Estemoan isän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Ja hänen juudansukuinen vaimonsa synnytti Jeredin, Gedorin isän, Heberin, Sookon isän, ja Jekutielin, Saanoahin isän. Ja nämä olivat Bitjan, faraon tyttären, poikia, jonka Mered oli ottanut vaimokseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'Ja Hoodian vaimon, Nahamin sisaren, pojat olivat Kegilan isä, garmilainen, ja maakatilainen Estemoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Ja Siimonin pojat olivat Amnon ja Rinna, Ben-Haanan ja Tiilon. Ja Jisin pojat olivat Soohet ja Soohetin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Seelan, Juudan pojan, pojat olivat Eer, Leekan isä, Lada, Maaresan isä, ja pellavakankaiden kutojain suvut Beet-Asbeasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'vielä Jookim ja Kooseban miehet sekä Jooas ja Saaraf, jotka hallitsivat Mooabia, ja Jaasubi-Lehem. Mutta nämä ovat vanhoja asioita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'He olivat niitä savenvalajia, jotka asuvat Netaimissa ja Gederassa; he asuivat siellä kuninkaan luona ja olivat hänen työssään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Simeonin pojat olivat Nemuel ja Jaamin, Jaarib, Serah ja Saul;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'tämän poika oli Sallum, tämän poika Mibsam, tämän poika Misma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'Ja Misman pojat olivat: hänen poikansa Hammuel, tämän poika Sakkur ja tämän poika Siimei.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Ja Siimeillä oli kuusitoista poikaa ja kuusi tytärtä; mutta hänen veljillään ei ollut monta lasta, eikä koko heidän sukunsa lisääntynyt Juudan lasten määrään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'Ja he asuivat Beersebassa, Mooladassa ja Hasar-Suualissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'Bilhassa, Esemissä ja Tooladissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'Betuelissa, Hormassa ja Siklagissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'Beet-Markabotissa, Hasar-Suusimissa, Beet-Birissä ja Saaraimissa. Nämä olivat heidän kaupunkinsa Daavidin hallitukseen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'Ja heidän kylänsä olivat Eetam, Ain, Rimmon, Tooken ja Aasan-viisi kaupunkia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'siihen lisäksi kaikki heidän kylänsä, jotka olivat näiden kaupunkien ympärillä, aina Baaliin asti. Nämä olivat heidän asuinsijansa; ja heillä oli omat sukuluettelonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'Vielä: Mesobab, Jamlek, Joosa, Amasjan poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'Jooel, Jeehu, Joosibjan poika, joka oli Serajan poika, joka Asielin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'Eljoenai, Jaakoba, Jesohaja, Asaja, Adiel, Jesimiel, Benaja');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'ja Siisa, Sifin poika, joka oli Allonin poika, joka Jedajan poika, joka Simrin poika, joka Semajan poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Nämä nimeltä mainitut olivat sukujensa ruhtinaita, ja heidän perhekuntansa olivat levinneet ja lisääntyneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Ja he kulkivat Gedoriin päin, aina laakson itäiseen osaan saakka, hakeakseen laidunta lampailleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'Ja he löysivät lihavan ja hyvän laitumen, ja maa oli tilava joka suuntaan sekä rauhallinen ja levollinen, sillä ne, jotka olivat asuneet siellä ennen, olivat haamilaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Mutta nämä nimeltä luetellut tulivat Hiskian, Juudan kuninkaan, päivinä ja valtasivat heidän telttansa ja voittivat meunilaiset, jotka olivat siellä, ja vihkivät heidät tuhon omiksi, aina tähän päivään asti, ja asettuivat heidän sijaansa, sillä siellä oli laidunta heidän lampaillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'Ja heistä, simeonilaisista, meni viisisataa miestä Seirin vuoristoon, ja heidän etunenässään olivat Pelatja, Nearja, Refaja ja Ussiel, Jisin pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'Ja he surmasivat ne, jotka olivat jäljellä pelastuneista amalekilaisista, ja jäivät sinne asumaan aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'Ruubenin, Israelin esikoisen, pojat olivat-hän oli näet esikoinen, mutta koska hän saastutti isänsä vuoteen, annettiin hänen esikoisuutensa Joosefin, Israelin pojan, pojille, kuitenkin niin, ettei heitä merkitty sukuluetteloon esikoisina,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'sillä Juuda tuli voimallisimmaksi veljiensä joukossa, ja yhdestä hänen jälkeläisistään tuli ruhtinas, mutta esikoisuus joutui Joosefille-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Ruubenin, Israelin esikoisen, pojat olivat Hanok ja Pallu, Hesron ja Karmi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Jooelin pojat olivat: hänen poikansa Semaja, tämän poika Goog, tämän poika Siimei,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'tämän poika Miika, tämän poika Reaja, tämän poika Baal');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'ja tämän poika Beera, jonka Assurin kuningas Tillegat-Pilneser vei pakkosiirtolaisuuteen; hän oli ruubenilaisten ruhtinas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'Ja hänen veljensä olivat sukujensa mukaan, kun heidät merkittiin sukuluetteloon heidän polveutumisensa mukaan: Jegiel, päämies, Sakarja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'Bela, Aasaan poika, joka oli Seman poika, joka Jooelin poika; hän asui Aroerissa ja aina Neboon ja Baal-Meoniin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Ja idässä hän asui erämaahan saakka, joka alkaa Eufrat-virrasta; sillä heillä oli suuria karjalaumoja Gileadin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Mutta Saulin päivinä he kävivät sotaa hagrilaisia vastaan, ja kun nämä olivat joutuneet heidän käsiinsä, asettuivat he heidän telttoihinsa Gileadin koko itäistä rajaseutua myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'Gaadilaiset asuivat heidän kanssaan rajakkain Baasanin maassa Salkaan saakka:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Jooel päämiehenä ja Saafam toisena, sitten Janai ja Saafat Baasanissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'Ja heidän veljensä olivat, perhekuntiensa mukaan: Miikael, Mesullam, Seba, Joorai, Jakan, Siia ja Eeber, kaikkiaan seitsemän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Nämä olivat Abihailin pojat, joka oli Huurin poika, joka Jaaroahin poika, joka Gileadin poika, joka Miikaelin poika, joka Jesisain poika, joka Jahdon poika, joka Buusin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahi, Abdielin poika, joka oli Guunin poika, oli heidän perhekuntiensa päämies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'Ja he asuivat Gileadissa, Baasanissa ja sen tytärkaupungeissa sekä kaikilla Saaronin laidunmailla, niin kauas kuin ne ulottuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Kaikki nämä merkittiin sukuluetteloon Juudan kuninkaan Jootamin ja Israelin kuninkaan Jerobeamin päivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Ruubenilaiset, gaadilaiset ja toinen puoli Manassen sukukuntaa-sotakuntoisia miehiä, jotka kantoivat kilpeä ja miekkaa ja jännittivät jousta ja olivat taisteluun harjaantuneita, neljäkymmentäneljä tuhatta seitsemänsataa kuusikymmentä sotakelpoista miestä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'kävivät sotaa hagrilaisia, Jeturia, Naafista ja Noodabia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'Ja he saivat apua näitä vastaan, niin että hagrilaiset ja kaikki, jotka olivat heidän kanssaan, joutuivat heidän käsiinsä; sillä he huusivat taistelussa Jumalan puoleen, ja hän kuuli heidän rukouksensa, koska he turvasivat häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'Ja he veivät saaliinaan heidän karjansa, viisikymmentä tuhatta kamelia, kaksisataa viisikymmentä tuhatta lammasta ja kaksituhatta aasia, sekä satatuhatta ihmistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Paljon oli surmattuina kaatuneita, sillä sota oli Jumalan sota. Ja he asettuivat asumaan heidän sijaansa aina pakkosiirtolaisuuteen saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Toinen puoli Manassen sukukuntaa asui siinä maassa, Baasanista aina Baal-Hermoniin ja Seniriin ja Hermon-vuoreen saakka; heitä oli paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'Ja nämä olivat heidän perhekuntiensa päämiehet: Eefer, Jisi, Eliel, Asriel, Jeremia, Hoodavja ja Jahdiel, sotaurhoja, kuuluisia miehiä, perhekuntiensa päämiehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Mutta he tulivat uskottomiksi isiensä Jumalaa kohtaan ja juoksivat haureudessa maan kansojen jumalain jäljessä, niiden kansojen, jotka Jumala oli hävittänyt heidän edestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Niin Israelin Jumala herätti Puulin, Assurin kuninkaan, hengen ja Tillegat-Pilneserin, Assurin kuninkaan, hengen ja kuljetutti heidät, ruubenilaiset, gaadilaiset ja toisen puolen Manassen sukukuntaa, pakkosiirtolaisuuteen ja antoi viedä heidät Halahiin, Haaboriin, Haaraan ja Goosanin joen rannoille, missä he tänäkin päivänä ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Leevin pojat olivat Geerson, Kehat ja Merari.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'Ja Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'Ja Amramin lapset olivat Aaron, Mooses ja Mirjam. Ja Aaronin pojat olivat Naadab, Abihu, Eleasar ja Iitamar.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleasarille syntyi Piinehas; Piinehaalle syntyi Abisua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Ja Abisualle syntyi Bukki, ja Bukille syntyi Ussi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Ja Ussille syntyi Serahja, ja Serahjalle syntyi Merajot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Merajotille syntyi Amarja, ja Amarjalle syntyi Ahitub.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Ja Ahitubille syntyi Saadok, ja Saadokille syntyi Ahimaas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Ja Ahimaasille syntyi Asarja, ja Asarjalle syntyi Joohanan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'Ja Joohananille syntyi Asarja, hän joka toimitti papinvirkaa temppelissä, jonka Salomo rakennutti Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Ja Asarjalle syntyi Amarja, ja Amarjalle syntyi Ahitub.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'Ja Ahitubille syntyi Saadok, ja Saadokille syntyi Sallum.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Ja Sallumille syntyi Hilkia, ja Hilkialle syntyi Asarja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Ja Asarjalle syntyi Seraja, ja Serajalle syntyi Jehosadak.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Mutta Jehosadakin oli lähdettävä mukaan silloin, kun Herra antoi Nebukadnessarin viedä Juudan ja Jerusalemin pakkosiirtolaisuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Leevin pojat olivat Geersom, Kehat ja Merari.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'Ja nämä ovat Geersomin poikien nimet: Libni ja Siimei.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Ja Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Merarin pojat olivat Mahli ja Muusi. Nämä olivat leeviläisten suvut heidän isiensä mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Geersomista polveutuivat hänen poikansa Libni, tämän poika Jahat, tämän poika Simma,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'tämän poika Jooah, tämän poika Iddo, tämän Serah ja tämän poika Jeatrai.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Kehatin pojat olivat: hänen poikansa Amminadab, tämän poika Koorah, tämän poika Assir,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'tämän poika Elkana, tämän poika Ebjasaf, tämän poika Assir,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'tämän poika Tahat, tämän poika Uuriel, tämän poika Ussia ja tämän poika Saul.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'Ja Elkanan pojat olivat Amasai ja Ahimot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Elkana: Elkanan pojat, Suufai, tämän poika Nahat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'tämän poika Eliab, tämän poika Jeroham, tämän poika Elkana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'Ja Samuelin pojat olivat esikoinen Vasni ja Abia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Merarin pojat olivat: Mahli, tämän poika Libni, tämän poika Siimei, tämän poika Ussa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'tämän poika Simea, tämän poika Haggia ja tämän poika Asaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Ja nämä ovat ne, jotka Daavid asetti pitämään huolta laulusta Herran temppelissä, senjälkeen kuin arkki oli saanut leposijan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'He palvelivat veisaajina ilmestysmajan asumuksen edessä, kunnes Salomo rakensi Herran temppelin Jerusalemiin; he toimittivat virkaansa, niinkuin heille oli säädetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'Ja nämä ovat ne, jotka palvelivat, ja nämä heidän poikansa: Kehatilaisia: Heeman, veisaaja, Jooelin poika, joka oli Samuelin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'joka Elkanan poika, joka Jerohamin poika, joka Elielin poika, joka Tooahin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'joka Suufin poika, joka Elkanan poika, joka Mahatin poika, joka Amasain poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'joka Elkanan poika, joka Jooelin poika, joka Asarjan poika, joka Sefanjan poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'joka Tahatin poika, joka Assirin poika, joka Ebjasafin poika, joka Koorahin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'joka Jisharin poika, joka Kehatin poika, joka Leevin poika, joka Israelin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'Vielä hänen veljensä Aasaf, joka seisoi hänen oikealla puolellansa, Aasaf, Berekjan poika, joka oli Simean poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'joka Miikaelin poika, joka Baasejan poika, joka Malkian poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'joka Etnin poika, joka Serahin poika, joka Adajan poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'joka Eetanin poika, joka Simman poika, joka Siimein poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'joka Jahatin poika, joka Geersomin poika, joka Leevin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Ja heidän veljensä, Merarin pojat, vasemmalla puolella: Eetan, Kiisin poika, joka oli Abdin poika, joka Mallukin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'joka Hasabjan poika, joka Amasjan poika, joka Hilkian poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'joka Amsin poika, joka Baanin poika, joka Semerin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'joka Mahlin poika, joka Muusin poika, joka Merarin poika, joka Leevin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'Ja heidän veljensä, leeviläiset, olivat annetut toimittamaan kaikkinaista palvelusta Jumalan temppeli-asumuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Mutta Aaron ja hänen poikansa polttivat uhreja polttouhrialttarilla ja suitsutusalttarilla, toimittivat kaikki askareet kaikkeinpyhimmässä ja Israelin sovituksen, aivan niinkuin Jumalan palvelija Mooses oli käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'Ja nämä olivat Aaronin pojat: hänen poikansa Eleasar, tämän poika Piinehas, tämän poika Abisua,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'tämän poika Bukki, tämän poika Ussi, tämän poika Serahja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'tämän poika Merajot, tämän poika Amarja, tämän poika Ahitub,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'tämän poika Saadok, tämän poika Ahimaas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'Ja nämä olivat heidän asuinsijansa, heidän leiripaikkojensa mukaan, heidän alueellaan: Niille Aaronin jälkeläisille, jotka olivat kehatilaisten sukua, sillä he saivat arpaosan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'annettiin Hebron Juudan maasta, ympärillä olevine laidunmaineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Mutta kaupungin peltomaat kylineen annettiin Kaalebille, Jefunnen pojalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Aaronin jälkeläisille annettiin turvakaupungit Hebron, Libna laidunmaineen, Jattir, Estemoa laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Hiilen laidunmaineen, Debir laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Aasan laidunmaineen ja Beet-Semes laidunmaineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'Ja Benjaminin sukukunnasta Geba laidunmaineen, Aalemet laidunmaineen ja Anatot laidunmaineen. Heidän kaupunkejaan oli kaikkiaan kolmetoista kaupunkia, heidän sukujensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Ja muut kehatilaiset saivat arvalla sukujensa mukaan Efraimin sukukunnalta, Daanin sukukunnalta ja toiselta puolelta Manassen sukukuntaa kymmenen kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'Ja geersomilaiset saivat sukujensa mukaan Isaskarin sukukunnalta, Asserin sukukunnalta, Naftalin sukukunnalta ja Manassen sukukunnalta Baasanista kolmetoista kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Merarilaiset saivat arvalla sukujensa mukaan Ruubenin sukukunnalta, Gaadin sukukunnalta ja Sebulonin sukukunnalta kaksitoista kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Näin israelilaiset antoivat leeviläisille nämä kaupungit laidunmaineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'He antoivat arvalla Juudan lasten sukukunnasta, simeonilaisten sukukunnasta ja benjaminilaisten sukukunnasta nämä nimeltä mainitut kaupungit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'Kehatilaisten suvuista muutamat saivat arvalla Efraimin sukukunnalta alueekseen seuraavat kaupungit:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'heille annettiin turvakaupungit Sikem laidunmaineen Efraimin vuoristosta, Geser laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Jokmeam laidunmaineen, Beet-Hooron laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Aijalon laidunmaineen ja Gat-Rimmon laidunmaineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'ja toisesta puolesta Manassen sukukuntaa Aaner laidunmaineen ja Bileam laidunmaineen. Nämä tulivat muitten kehatilaisten suvuille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Geersomilaiset saivat sukujensa mukaan toiselta puolelta Manassen sukukuntaa Goolanin laidunmaineen Baasanista ja Astarotin laidunmaineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'ja Isaskarin sukukunnalta Kedeksen laidunmaineen, Dobratin laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Raamotin laidunmaineen ja Aanemin laidunmaineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'ja Asserin sukukunnalta Maasalin laidunmaineen, Abdonin laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Huukokin laidunmaineen ja Rehobin laidunmaineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'ja Naftalin sukukunnalta Kedeksen laidunmaineen Galileasta, Hammonin laidunmaineen ja Kirjataimin laidunmaineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Muut merarilaiset saivat Sebulonin sukukunnalta Rimmonin laidunmaineen ja Taaborin laidunmaineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'ja tuolta puolelta Jerikon Jordanin, Jordanista auringonnousuun päin, Ruubenin sukukunnalta Beserin laidunmaineen erämaasta, Jahaan laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Kedemotin laidunmaineen, Meefaatin laidunmaineen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'ja Gaadin sukukunnalta Raamotin laidunmaineen Gileadista, Mahanaimin laidunmaineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Hesbonin laidunmaineen ja Jaeserin laidunmaineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'Isaskarin pojat olivat Toola, Puua, Jaasub ja Simron, kaikkiaan neljä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'Ja Toolan pojat olivat Ussi, Refaja, Jeriel, Jahmai, Jibsam ja Samuel, jotka olivat perhekuntiensa päämiehiä, Toolan jälkeläisiä, sotaurhoja, polveutumisensa mukaan. Daavidin aikana oli heidän lukumääränsä kaksikymmentäkaksi tuhatta kuusisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'Ja Ussin poika oli Jisrahja, ja Jisrahjan pojat olivat Miikael, Obadja, Jooel ja Jissia, kaikkiaan viisi, kaikki päämiehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'Heitä seurasi polveutumisensa ja perhekuntiensa mukaan taisteluun valmiina sotajoukkoina kolmekymmentäkuusi tuhatta miestä, sillä heillä oli paljon vaimoja ja lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'Ja heidän veljensä, kaikissa Isaskarin suvuissa, olivat sotaurhoja. Sukuluetteloihin merkittyjä oli kaikkiaan kahdeksankymmentäseitsemän tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Benjaminia oli: Bela, Beker ja Jediael, kaikkiaan kolme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Ja Belan pojat olivat Esbon, Ussi, Ussiel, Jerimot ja Iiri, kaikkiaan viisi, perhekunta-päämiehiä, sotaurhoja. Ja sukuluetteloihin merkittyjä oli heitä kaksikymmentäkaksi tuhatta kolmekymmentä neljä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'Ja Bekerin pojat olivat Semira, Jooas, Elieser, Eljoenai, Omri, Jeremot, Abia, Anatot ja Aalemet; kaikki nämä olivat Bekerin poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'Ja sukuluetteloihin merkittyjä oli heitä polveutumisensa mukaan, perhekunta-päämiestensä, sotaurhojen, mukaan, kaksikymmentä tuhatta kaksisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'Ja Jediaelin poika oli Bilhan, ja Bilhanin pojat olivat Jeus, Benjamin, Eehud, Kenaana, Seetan, Tarsis ja Ahisahar.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Kaikki nämä olivat Jediaelin poikia perhekunta-päämiesten, sotaurhojen, mukaan; seitsemäntoista tuhatta kaksisataa sotakelpoista miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Ja Suppim ja Huppim olivat Iirin poikia; Huusim oli Aherin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Naftalin pojat olivat Jahasiel, Guuni, Jeeser ja Sallum, Bilhan jälkeläisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Manassen poika oli Asriel, jonka hänen aramilainen sivuvaimonsa synnytti; tämä synnytti Maakirin, Gileadin isän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Ja Maakir otti vaimon Huppimille ja Suppimille, ja hänen sisarensa nimi oli Maaka. Ja toisen nimi oli Selofhad; ja Selofhadilla oli tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'Ja Maaka, Maakirin vaimo, synnytti pojan, jolle hän antoi nimen Peres; hänen veljensä nimi oli Seres, ja hänen poikansa olivat Uulam ja Rekem.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'Uulamin poika oli Bedan. Nämä olivat Gileadin pojat, joka oli Maakirin poika, joka Manassen poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'Ja hänen sisarensa Mooleket synnytti Iishodin, Abieserin ja Mahlan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'Ja Semidan pojat olivat Ahjan, Sekem, Likhi ja Aniam.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'Efraimin pojat olivat: Suutelah, tämän poika Bered, tämän poika Tahat, tämän poika Elada, tämän poika Tahat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'tämän poika Saabad, tämän poika Suutelah, sekä Eser ja Elead. Ja Gatin miehet, siinä maassa syntyneet, tappoivat heidät, koska he olivat lähteneet ottamaan heidän karjaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Ja heidän isänsä Efraim suri pitkät ajat, ja hänen veljensä tulivat lohduttamaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Sitten hän yhtyi vaimoonsa, ja tämä tuli raskaaksi ja synnytti pojan; ja hän antoi tälle nimen Beria, koska se oli tapahtunut hänen perheensä onnettomuuden aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'Ja hänen tyttärensä oli Seera; tämä rakensi Ala-ja Ylä-Beet-Hooronin sekä Ussen-Seeran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'Ja Berian poika oli Refah, samoin Resef, tämän poika Telah, tämän poika Tahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'tämän poika Ladan, tämän poika Ammihud, tämän poika Elisama,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'tämän poika Nuun ja tämän poika Joosua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'Ja heidän perintömaansa ja asuinsijansa olivat Beetel ja sen tytärkaupungit, itään päin Naaran ja länteen päin Geser ja sen tytärkaupungit, sekä Sikem ja sen tytärkaupungit, aina Aijaan ja sen tytärkaupunkeihin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Ja manasselaisten hallussa olivat Beet-Sean ja sen tytärkaupungit, Taanak ja sen tytärkaupungit, Megiddo ja sen tytärkaupungit, Door ja sen tytärkaupungit. Näissä asuivat Joosefin, Israelin pojan, jälkeläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Asserin pojat olivat Jimna, Jisva, Jisvi ja Beria; heidän sisarensa oli Serah.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'Berian pojat olivat Heber ja Malkiel; tämä oli Birsaitin isä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'Ja Heberille syntyi Jaflet, Soomer, Hootam ja heidän sisarensa Suua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'Ja Jafletin pojat olivat Paasak, Bimhal ja Asva; nämä ovat Jafletin pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'Ja Semerin pojat olivat Ahi, Rohga, Hubba ja Aram.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Ja hänen veljensä Heelemin pojat olivat Soofah, Jimna, Seeles ja Aamal.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Soofahin pojat olivat Suuah, Harnefer, Suual, Beeri, Jimra,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Beser, Hood, Samma, Silsa, Jitran ja Beera.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'Ja Jeterin pojat olivat Jefunne, Fispa ja Ara.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Ja Ullan pojat olivat Aarah, Hanniel ja Risja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Kaikki nämä olivat Asserin jälkeläisiä, perhekunta-päämiehiä, valittuja sotaurhoja, ruhtinasten päämiehiä. Ja heidän sukuluetteloihin merkittyjen sotakelpoisten miestensä lukumäärä oli kaksikymmentäkuusi tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Benjaminille syntyi esikoisena Bela, toisena Asbel, kolmantena Ahrah,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'neljäntenä Nooha ja viidentenä Raafa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'Ja Belalla oli pojat: Addar, Geera, Abihud,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisua, Naaman, Ahoah,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Geera, Sefufan ja Huuram.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'Ja nämä olivat Eehudin pojat-nämä olivat Geban asukkaiden perhekunta-päämiehet. Heidät siirrettiin pois Manahatiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'niin myös Naaman, Ahia ja Geera; hän siirsi heidät pois. Hänelle syntyi Ussa ja Ahihud.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Ja Saharaimille syntyi Mooabin maassa, sittenkuin hän oli hyljännyt vaimonsa Huusimin ja Baaran,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'hänelle syntyi hänen vaimostaan Hoodeksesta Joobab, Sibja, Meesa, Malkam,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeus, Sokja ja Mirma; nämä olivat hänen poikiansa, perhekunta-päämiehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'Ja Huusimista oli hänelle syntynyt Abitub ja Elpaal.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'Ja Elpaalin pojat olivat Eeber, Misam ja Semed. Tämä rakensi Oonon ja Loodin ynnä sen tytärkaupungit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'Beria ja Sema olivat Aijalonin asukasten perhekunta-päämiehiä; ja he karkoittivat Gatin asukkaat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'he ja Ahjo, Saasak ja Jeremot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Ja Sebadja, Arad, Eder,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Miikael, Jispa ja Jooha olivat Berian poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'Ja Sebadja, Mesullam, Hiski, Heber,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Jismerai, Jislia ja Joobab olivat Elpaalin poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'Ja Jaakim, Sikri, Sabdi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elienai, Silletai, Eliel,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaja, Beraja ja Simrat olivat Siimein poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Ja Jispan, Eder, Eliel,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Sikri, Haanan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hananja, Eelam, Antotia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Jifdeja ja Penuel olivat Saasakin poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'Ja Samserai, Seharja, Atalja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaaresja, Elia ja Sikri olivat Jerohamin poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Nämä olivat perhekunta-päämiehiä, päämiehiä polveutumisensa mukaan; he asuivat Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'Gibeonissa asui Gibeonin isä, jonka vaimon nimi oli Maaka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'Ja hänen esikoispoikansa oli Abdon, sitten Suur, Kiis, Baal, Naadab,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Ahjo ja Seker.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Ja Miklotille syntyi Simea. Hekin asuivat veljinensä Jerusalemissa, rajakkain veljiensä kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'Ja Neerille syntyi Kiis, Kiisille syntyi Saul, ja Saulille syntyi Joonatan, Malkisua, Abinadab ja Esbaal.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'Ja Joonatanin poika oli Meribbaal, ja Meribbaalille syntyi Miika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'Ja Miikan pojat olivat Piiton, Melek, Tarea ja Aahas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'Ja Aahaalle syntyi Jooadda, Jooaddalle syntyi Aalemet, Asmavet ja Simri. Ja Simrille syntyi Moosa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Ja Moosalle syntyi Binea; hänen poikansa oli Raafa, tämän poika Elasa ja tämän poika Aasel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Ja Aaselilla oli kuusi poikaa, ja nämä ovat heidän nimensä: Asrikam, Bookeru, Jismael, Searja, Obadja ja Haanan. Nämä kaikki olivat Aaselin poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'Ja Eesekin, hänen veljensä, pojat olivat: hänen esikoisensa Uulam, toinen Jeus ja kolmas Elifelet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'Ja Uulamin pojat olivat sotaurhoja, jousen jännittäjiä, ja heillä oli paljon poikia ja poikien poikia, sataviisikymmentä. Nämä kaikki ovat benjaminilaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'Koko Israel merkittiin sukuluetteloon, ja katso, he ovat kirjoitetut Israelin kuningasten kirjaan. Ja Juuda vietiin Baabeliin pakkosiirtolaisuuteen uskottomuutensa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Entiset asukkaat, jotka elivät perintömaillaan, kaupungeissaan, olivat israelilaisia, pappeja, leeviläisiä ja temppelipalvelijoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'Jerusalemissa asui Juudan lapsia, benjaminilaisia, efraimilaisia ja manasselaisia, nimittäin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Uutai, Ammihudin poika, joka oli Omrin poika, joka Imrin poika, joka Baanin poika, Pereksen, Juudan pojan, jälkeläisiä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'ja seelalaisia: Asaja, esikoinen, ja hänen poikansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'serahilaisia: Jeguel ja hänen veljensä, kuusisataa yhdeksänkymmentä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'benjaminilaisia: Sallu, Mesullamin poika, joka oli Hoodavjan poika, joka Senuan poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'Jibneja, Jerohamin poika, Eela, Ussin poika, joka oli Mikrin poika, ja Mesullam, Sefatjan poika, joka oli Reguelin poika, joka Jibnean poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'sekä heidän veljensä, heidän polveutumisensa mukaan, yhdeksänsataa viisikymmentä kuusi. Kaikki nämä olivat perhekunta-päämiehiä perhekunnissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Ja pappeja: Jedaja, Joojarib, Jaakin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'Asarja, Hilkian poika, joka oli Mesullamin poika, joka Saadokin poika, joka Merajotin poika, joka Ahitubin poika, Jumalan temppelin esimies;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'Adaja, Jerohamin poika, joka oli Pashurin poika, joka Malkian poika, ja Maesai, Adielin poika, joka oli Jahseran poika, joka Mesullamin poika, joka Mesillemitin poika, joka Immerin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'sekä heidän veljensä, heidän perhekuntiensa päämiehet, tuhat seitsemänsataa kuusikymmentä miestä, kelvollisia toimittamaan palvelusta Jumalan temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'Ja leeviläisiä: Semaja, Hassubin poika, joka oli Asrikamin poika, joka Hasabjan poika, merarilaisia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'Bakbakkar, Heres, Gaalal, Mattanja, Miikan poika, joka oli Sikrin poika, joka Aasafin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Obadja, Semajan poika, joka oli Gaalalin poika, joka Jedutunin poika; ja Berekja, Aasan poika, joka oli Elkanan poika, hänen, joka asui netofalaisten kylissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'Ja ovenvartijat: Sallum, Akkub, Talmon ja Ahiman veljineen: Sallum oli päämies,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'ja tähän saakka hän on ollut vartijana Kuninkaan portilla, idän puolella. Nämä olivat ovenvartijoina leeviläisten leirissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Mutta Sallumilla, Kooren pojalla, joka oli Ebjasafin poika, joka Koorahin poika, ja hänen veljillään, jotka olivat hänen perhekuntaansa-koorahilaisilla, oli palvelustehtävänä majan kynnyksien vartioiminen; heidän isänsä olivat näet vartioineet sisäänkäytävää Herran leirissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Ja Piinehas, Eleasarin poika, oli muinoin heidän esimiehenään-Herra olkoon hänen kanssaan! -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Sakarja, Meselemjan poika, oli ovenvartijana ilmestysmajan ovella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Kaikkiaan oli kynnyksien ovenvartijoiksi valittuja kaksisataa kaksitoista; he olivat kylissään merkityt sukuluetteloon. Daavid ja Samuel, näkijä, olivat asettaneet heidät heidän luottamustoimeensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Niin he ja heidän poikansa olivat vartijoina Herran temppelin, telttapyhäkön, ovilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Ovenvartijat olivat asetetut neljälle ilmansuunnalle: idän, lännen, pohjoisen ja etelän puolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Ja heidän veljiensä, jotka asuivat kylissään, oli aina määräaikoina seitsemäksi päiväksi tultava toimittamaan palvelusta yhdessä heidän kanssaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'sillä ne neljä ylintä ovenvartijaa olivat pysyväisesti luottamustoimessaan. Nämä olivat leeviläiset. Heidän oli myöskin valvottava kammioita ja Jumalan temppelin aarteita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'ja he viettivät yönsä Jumalan temppelin ympärillä, sillä heidän tehtävänään oli vartioiminen ja heidän oli pidettävä huoli ovien avaamisesta joka aamu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'Muutamien heistä oli pidettävä huoli jumalanpalveluksessa tarvittavasta kalustosta, sillä heidän oli tuotava se sisään täysilukuisena ja vietävä se ulos täysilukuisena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Ja muutamat heistä olivat määrätyt pitämään huolta kaluista, kaikista pyhistä kaluista, sekä lestyistä jauhoista, viinistä, öljystä, suitsukkeista ja hajuaineista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'Ja muutamat pappien pojista valmistivat voiteita hajuaineista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Ja Mattitjalla, joka oli leeviläisiä ja oli koorahilaisen Sallumin esikoinen, oli luottamustoimena leivosten valmistaminen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'Ja muutamien kehatilaisista, heidän veljistään, oli pidettävä huoli näkyleivistä, valmistettava ne joka sapatiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Mutta veisaajat, leeviläisten perhekuntain päämiehet, oleskelivat kammioissa, muusta palveluksesta vapaina, sillä he olivat toimessa sekä päivällä että yöllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'He olivat leeviläisten perhekuntain päämiehiä, päämiehiä polveutumisensa mukaan; he asuivat Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'Gibeonissa asuivat Gibeonin isä, jonka vaimon nimi oli Maaka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'hänen esikoispoikansa Abdon, sitten Suur, Kiis, Baal, Neer, Naadab,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Ahjo, Sakarja ja Mikleot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'Ja Mikleotille syntyi Simeam. Hekin asuivat veljinensä Jerusalemissa, rajakkain veljiensä kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'Ja Neerille syntyi Kiis, Kiisille syntyi Saul, ja Saulille syntyi Joonatan, Malkisua, Abinadab ja Esbaal.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'Ja Joonatanin poika oli Meribbaal, ja Meribbaalille syntyi Miika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Ja Miikan pojat olivat Piiton, Melek ja Tahrea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Ja Aahaalle syntyi Jaera, Jaeralle syntyi Aalemet, Asmavet ja Simri. Ja Simrille syntyi Moosa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'ja Moosalle syntyi Binea; hänen poikansa oli Refaja, tämän poika Elasa ja tämän poika Aasel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Ja Aaselilla oli kuusi poikaa, ja nämä ovat heidän nimensä: Asrikam, Bookeru, Jismael, Searja, Obadja ja Haanan. Nämä olivat Aaselin pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Mutta filistealaiset taistelivat Israelia vastaan; ja Israelin miehet pakenivat filistealaisia, ja heitä kaatui surmattuina Gilboan vuorella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'Ja filistealaiset pääsivät Saulin ja hänen poikiensa kintereille, ja filistealaiset surmasivat Joonatanin, Abinadabin ja Malkisuan, Saulin pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'Ja kun taistelu kiihtyi ankaraksi Saulia vastaan ja jousimiehet keksivät hänet, joutui hän hätään jousimiesten ahdistaessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Ja Saul sanoi aseenkantajallensa: \"Paljasta miekkasi ja lävistä sillä minut, etteivät nuo ympärileikkaamattomat tulisi pitämään minua pilkkanaan\". Mutta hänen aseenkantajansa ei tahtonut, sillä hän pelkäsi kovin. Niin Saul itse otti miekan ja heittäytyi siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Mutta kun hänen aseenkantajansa näki, että Saul oli kuollut, heittäytyi hänkin miekkaansa ja kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Niin kuolivat Saul ja hänen kolme poikaansa ynnä koko hänen perheensä; he kuolivat yhdessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Ja kun kaikki Israelin miehet, jotka asuivat tasangolla, huomasivat, että he olivat paenneet ja että Saul poikinensa oli kuollut, jättivät he kaupunkinsa ja pakenivat, ja filistealaiset tulivat ja asettuivat niihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Seuraavana päivänä filistealaiset tulivat ryöstämään surmattuja ja löysivät Saulin ja hänen poikansa kaatuneina Gilboan vuorelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'Niin he ryöstivät hänet ja ottivat hänen päänsä ja hänen aseensa ja lähettivät ne ympäri filistealaisten maata, julistaaksensa voitonsanomaa epäjumalillensa ja kansalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'Ja he asettivat hänen aseensa jumalansa temppeliin, ja hänen pääkallonsa he kiinnittivät Daagonin temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Kun koko Gileadin Jaabes kuuli, mitä kaikkea filistealaiset olivat tehneet Saulille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'nousivat he, kaikki asekuntoiset miehet, ja ottivat Saulin ja hänen poikainsa ruumiit ja toivat ne Jaabekseen. Sitten he hautasivat heidän luunsa tammen alle Jaabekseen ja paastosivat seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'Niin kuoli Saul, koska hän oli ollut uskoton Herraa kohtaan eikä ollut ottanut vaaria Herran sanasta, ja myös sentähden, että hän oli kysynyt vainajahengeltä neuvoa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'mutta ei ollut kysynyt neuvoa Herralta. Sentähden Herra surmasi hänet ja siirsi kuninkuuden Daavidille, Iisain pojalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Sitten koko Israel kokoontui Daavidin tykö Hebroniin, ja he sanoivat: \"Katso, me olemme sinun luutasi ja lihaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Jo kauan sitten, Saulin vielä ollessa kuninkaana, sinä saatoit Israelin lähtemään ja tulemaan. Ja sinulle on Herra, sinun Jumalasi, sanonut: \'Sinä olet kaitseva minun kansaani Israelia, ja sinä olet oleva minun kansani Israelin ruhtinas\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Ja kaikki Israelin vanhimmat tulivat kuninkaan tykö Hebroniin, ja Daavid teki heidän kanssaan liiton Hebronissa Herran edessä. Ja sitten he voitelivat Daavidin Israelin kuninkaaksi sen sanan mukaan, jonka Herra oli puhunut Samuelin kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Ja Daavid ja koko Israel menivät Jerusalemiin, se on Jebukseen, ja siellä olivat jebusilaiset, jotka asuivat siinä maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'Jebuksen asukkaat sanoivat Daavidille: \"Tänne sinä et tule\". Mutta Daavid valloitti Siionin vuorilinnan, se on Daavidin kaupungin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Ja Daavid sanoi: \"Joka ensimmäisenä surmaa jebusilaisen, hän on oleva päämies ja päällikkö\". Jooab, Serujan poika, tuli ensimmäisenä sinne ylös, ja niin hänestä tuli päämies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'Sitten Daavid asettui vuorilinnaan; sentähden kutsuttiin sitä Daavidin kaupungiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'Ja hän rakensi kaupunkia yltympäri, Millosta reunoihin asti; ja Jooab rakensi entiselleen muun osan kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'Ja Daavid tuli yhä suuremmaksi, ja Herra Sebaot oli hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Nämä ovat ensimmäiset Daavidin urhoista, jotka voimakkaasti auttoivat häntä kuninkuuteen yhdessä koko Israelin kanssa, tehdäkseen hänet Israelin kuninkaaksi Herran sanan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'Tämä on Daavidin urhojen luettelo: Jaasobeam, hakmonilaisen poika, niiden kolmen päällikkö, hän, joka heilutti keihästään kolmensadan kaatuneen yli yhdellä kertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'Hänen jälkeensä Eleasar, Doodon poika, ahohilainen, yksi niistä kolmesta urhosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Hän oli Daavidin kanssa Pas-Dammimissa, kun filistealaiset olivat kokoontuneet sinne sotimaan. Ja siellä oli peltopalsta täynnä ohraa. Ja väki pakeni filistealaisia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'mutta he asettuivat keskelle palstaa, saivat sen pelastetuksi ja voittivat filistealaiset; ja niin Herra antoi suuren voiton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Kerran lähti kolme niistä kolmestakymmenestä päälliköstä Daavidin luo kalliolinnaan, Adullamin luolalle. Ja filistealaisten joukko oli leiriytynyt Refaimin tasangolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Mutta Daavid oli silloin vuorilinnassa, ja filistealaisten vartiosto oli Beetlehemissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Ja Daavidin rupesi tekemään mieli vettä, ja hän sanoi: \"Jospa joku toisi minulle vettä juodakseni Beetlehemin kaivosta, joka on portin edustalla!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Silloin murtautuivat nämä kolme filistealaisten leirin läpi ja ammensivat vettä Beetlehemin kaivosta portin edustalta, kantoivat ja toivat sen Daavidille. Mutta Daavid ei tahtonut sitä juoda, vaan vuodatti sen juomauhriksi Herralle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'ja sanoi: \"Pois se! Jumala varjelkoon minut sitä tekemästä. Joisinko minä näiden miesten verta, heidän henkeänsä, sillä henkensä uhalla he toivat sen.\" Eikä hän tahtonut juoda sitä. Tämän tekivät ne kolme urhoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'Absai, Jooabin veli, oli niiden kolmen päällikkö; hän heilutti keihästään kolmensadan kaatuneen yli. Ja hän oli kuulu niiden kolmen joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Hän oli kahdenkertaisessa arvossa pidetty niiden kolmen joukossa ja oli heidän päämiehensä, mutta hän ei vetänyt vertoja niille kolmelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja, Joojadan poika, joka oli urhoollisen ja suurista teoistaan kuuluisan miehen poika, oli kotoisin Kabseelista. Hän surmasi ne kaksi mooabilaista sankaria, ja hän laskeutui alas ja tappoi lumituiskun aikana leijonan kaivoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Myöskin surmasi hän egyptiläisen miehen, sen suurikasvuisen, viittä kyynärää pitkän miehen. Egyptiläisellä oli kädessä keihäs, joka oli niinkuin kangastukki, mutta hän meni häntä vastaan ainoastaan sauva kädessä. Ja hän tempasi keihään egyptiläisen kädestä ja tappoi hänet hänen omalla keihäällään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'Tällaisia teki Benaja, Joojadan poika. Ja hän oli kuulu niiden kolmen urhon joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Hän oli arvossa pidetty niiden kolmenkymmenen joukossa, mutta hän ei vetänyt vertoja niille kolmelle. Ja Daavid asetti hänet henkivartiostonsa päälliköksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'Sotaurhot olivat: Asael, Jooabin veli; Elhanan, Doodon poika, Beetlehemistä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'harorilainen Sammot; pelonilainen Heeles;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'tekoalainen Iira, Ikkeksen poika; anatotilainen Abieser;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'huusalainen Sibbekai; ahohilainen Iilai;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'netofalainen Maharai; netofalainen Heeled, Baanan poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Iitai, Riibain poika, benjaminilaisten Gibeasta, piratonilainen Benaja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Huurai Nahale-Gaasista; arabalainen Abiel;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'baharumilainen Asmavet; saalbonilainen Eljahba;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'gisonilainen Bene-Haasem; hararilainen Joonatan, Saagen poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'hararilainen Abiam, Saakarin poika; Elifal, Uurin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'mekeralainen Heefer; pelonilainen Ahia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'karmelilainen Hesro; Naarai, Esbain poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Jooel, Naatanin veli; Mibhar, Hagrin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'ammonilainen Selek; beerotilainen Nahrai, Jooabin, Serujan pojan aseenkantaja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'jeteriläinen Iira; jeteriläinen Gaareb;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'heettiläinen Uuria; Saabad, Ahlain poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'ruubenilainen Adina, Siisan poika, ruubenilaisten päämies, ja hänen kanssaan kolmekymmentä muuta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Haanan, Maakan poika, ja mitniläinen Joosafat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'astarotilainen Ussia; Saama ja Jegiel, aroerilaisen Hootamin pojat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, Simrin poika, ja hänen veljensä Jooha, tiisiläinen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel-Mahavim sekä Jeribai ja Joosavja, Elnaamin pojat, ja mooabilainen Jitma;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, Oobed ja Jaasiel-Mesobaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'Ja nämä olivat ne, jotka tulivat Daavidin luo Siklagiin, kun hän vielä piileskeli Saulia, Kiisin poikaa; ja he olivat niitä urhoja, jotka auttoivat häntä sodassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'He olivat asestetut jousella ja taitavia sekä oikealla että vasemmalla kädellä linkoamaan kiviä ja ampumaan jousella nuolia. Saulin heimolaisia, benjaminilaisia:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Ahieser, päämies, ja Jooas, gibealaisen Hassemaan pojat; Jesiel ja Pelet, Asmavetin pojat; Beraka; anatotilainen Jeehu;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'gibeonilainen Jismaja, urho niiden kolmenkymmenen joukossa ja niiden kolmenkymmenen päällikkö; Jeremia; Jahasiel; Joohanan; gederalainen Joosabad;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Elusai; Jerimot; Bealja; Semarja; harufilainen Sefatja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'koorahilaiset Elkana, Jissia, Asarel, Jooeser ja Jaasobeam;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'Jooela ja Sebadja, Jerohamin pojat, Gedorista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Gaadilaisista meni Daavidin puolelle vuorilinnaan, erämaahan, sotaurhoja, sotakelpoisia miehiä, kilpeä ja keihästä käyttäviä, jotka olivat näöltään kuin leijonat ja nopeat kuin gasellit vuorilla:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Eeser, päämies Obadja toinen, Eliab kolmas,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Masmanna neljäs, Jeremia viides,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Attai kuudes, Eliel seitsemäs,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Joohanan kahdeksas, Elsabad yhdeksäs,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jeremia kymmenes, Makbannai yhdestoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Nämä olivat gaadilaisia, sotajoukon päälliköitä, pienin sadan, suurin tuhannen miehen veroinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Nämä olivat ne, jotka ensimmäisessä kuussa menivät Jordanin poikki, kun se tulvi yli kaikkien äyräittensä, ja jotka karkoittivat kaikki tasangoilla-asujat itään ja länteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Myöskin benjaminilaisia ja Juudan miehiä tuli Daavidin vuorilinnaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'Silloin Daavid meni heitä vastaan, lausui ja sanoi heille: \"Jos te tulette minun luokseni rauha mielessä, auttaaksenne minua, niin minun sydämeni yhtyy teihin; mutta jos te tulette kavaltamaan minua vihollisilleni, vaikkei väkivalta minun käsiäni tahraa, niin nähköön meidän isiemme Jumala sen ja rangaiskoon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Mutta henki täytti Amasain, niiden kolmenkymmenen päällikön, ja hän sanoi: \"Sinun me olemme, Daavid, ja sinun puolellasi olemme, sinä Iisain poika. Rauha, rauha sinulle, ja rauha sinun auttajillesi, sillä sinun Jumalasi auttoi sinua!\" Niin Daavid otti heidät vastaan ja asetti heidät partiojoukon päälliköiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Manassesta siirtyi muutamia Daavidin puolelle, kun hän filistealaisten kanssa meni taistelemaan Saulia vastaan, vaikkeivät he joutuneetkaan auttamaan näitä, sillä filistealaisten ruhtinaat neuvoteltuaan lähettivät hänet pois sanoen: \"Hän voisi meidän päämme menoksi siirtyä herransa Saulin puolelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Kun hän siis lähti Siklagiin, siirtyivät hänen puolelleen Manassesta: Adna, Joosabad, Jediael, Miikael, Joosabad, Elihu ja Silletai, tuhannenpäämiehet Manassesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'Ja nämä auttoivat Daavidia rosvojoukkoa vastaan, sillä he olivat kaikki sotaurhoja, ja heistä tuli sotajoukon päälliköitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Sillä joka päivä tuli väkeä Daavidin luo auttamaan häntä, kunnes joukko oli suuri kuin Jumalan joukko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'Ja tämä on sotaan varustetun aseväen lukumäärä, niitten, jotka tulivat Daavidin luo Hebroniin siirtääkseen Saulin kuninkuuden hänelle Herran käskyn mukaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Juudan miehiä, jotka kantoivat kilpeä ja keihästä, kuusituhatta kahdeksansataa, sotaan varustettua;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'simeonilaisia, sotataitoisia urhoja, seitsemäntuhatta sata;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'leeviläisiä neljätuhatta kuusisataa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'sekä Joojada, Aaronin suvun ruhtinas, ynnä kolmetuhatta seitsemänsataa hänen kanssaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'ja Saadok, nuorukainen, sotaurho, perhekuntinensa, kaksikymmentä kaksi päällikköä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'benjaminilaisia, Saulin veljiä, kolmetuhatta, sillä vielä siihen aikaan suurin osa heistä palveli uskollisesti Saulin sukua;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'efraimilaisia kaksikymmentä tuhatta kahdeksansataa, sotaurhoja, kuuluisia miehiä perhekunnissaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'toisesta puolesta Manassen sukukuntaa kahdeksantoista tuhatta, jotka olivat nimeltä mainitut menemään ja tekemään Daavidin kuninkaaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'isaskarilaisia, jotka ymmärsivät ajan ja käsittivät, mitä Israelin oli tehtävä, kaksisataa päämiestä, ja kaikki heidän veljensä heidän johdollansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Sebulonista sotakelpoisia miehiä, kaikkinaisilla sota-aseilla sotaan varustettuja, viisikymmentä tuhatta, yksimielisiä sotarintaan järjestymään;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'Naftalista tuhat päällikköä, ja heidän kanssansa kolmekymmentäseitsemäntuhatta kilvellä ja keihäällä varustettua miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'daanilaisia kaksikymmentäkahdeksan tuhatta kuusisataa sotaan varustettua miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'Asserista sotakelpoisia miehiä, taisteluun valmiita, neljäkymmentä tuhatta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'tuolta puolelta Jordanin, ruubenilaisia, gaadilaisia ja manasselaisia sukukunnan toisesta puolesta, satakaksikymmentä tuhatta, kaikkinaisilla sota-aseilla varustettuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Kaikki nämä sotilaat, sotarintaan järjestyneinä, tulivat ehyellä sydämen halulla Hebroniin tehdäkseen Daavidin koko Israelin kuninkaaksi. Myöskin koko muu Israel oli yksimielinen tehdäkseen Daavidin kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'Ja he olivat siellä Daavidin luona kolme päivää ja söivät ja joivat, sillä heidän heimolaisensa olivat evästäneet heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Nekin, jotka asuivat lähellä heitä, aina Isaskariin, Sebuloniin ja Naftaliin saakka, toivat aasien, kamelien, muulien ja härkien selässä ruokatavaraa: jauhoja, viikunakakkuja ja rusinakakkuja, viiniä ja öljyä, raavaita ja pikkukarjaa viljalti; sillä Israelissa oli ilo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'Ja Daavid neuvotteli tuhannen-ja sadanpäämiesten, kaikkien ruhtinasten, kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'Ja Daavid sanoi kaikelle Israelin seurakunnalle: \"Jos se on teistä hyvä ja jos se tulee Herralta, meidän Jumalaltamme, niin lähettäkäämme joka taholle sana veljillemme, jotka ovat jääneet kaikkiin Israelin maakuntiin, ja papeille ja leeviläisille, jotka asuvat heidän luonaan laidunmaittensa kaupungeissa, että he kokoontuvat meidän luoksemme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'ja siirtäkäämme Jumalamme arkki luoksemme, sillä Saulin päivinä emme siitä välittäneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'Silloin koko seurakunta vastasi, että niin oli tehtävä, sillä se oli oikein koko kansan silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Niin Daavid kokosi kaiken Israelin, aina Egyptin Siihorista asti ja aina sieltä, mistä mennään Hamatiin, tuomaan Jumalan arkkia Kirjat-Jearimista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'Ja Daavid ja koko Israel meni Baalatiin, Kirjat-Jearimiin, joka on Juudassa, tuomaan sieltä Jumalan arkkia, jonka Herra oli ottanut nimiinsä, hän, jonka istuinta kerubit kannattavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'Ja he panivat Jumalan arkin uusiin vaunuihin ja veivät sen pois Abinadabin talosta, ja Ussa ja Ahjo ohjasivat vaunuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Ja Daavid ynnä koko Israel karkeloi kaikin voimin Jumalan edessä laulaen sekä soittaen kanteleita, harppuja, vaskirumpuja, kymbaaleja ja torvia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'Mutta kun he tulivat Kiidonin puimatantereen luo, ojensi Ussa kätensä tarttuaksensa arkkiin, sillä härät kompastuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'Silloin Herran viha syttyi Ussaa kohtaan, ja hän löi hänet sentähden, että hän oli ojentanut kätensä arkkiin, ja niin hän kuoli siihen, Jumalan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'Mutta Daavid pahastui siitä, että Herra niin oli murtanut Ussan. Siitä sen paikan nimenä on Peres-Ussa vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'Ja Daavid pelkäsi sinä päivänä Jumalaa, niin että hän sanoi: \"Kuinka minä voin tuoda Jumalan arkin tyköni?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Eikä Daavid siirtänyt arkkia luoksensa Daavidin kaupunkiin, vaan hän toimitti sen syrjään gatilaisen Oobed-Edomin taloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'Ja Jumalan arkki jäi kolmeksi kuukaudeksi Oobed-Edomin talon luo omaan majaansa. Ja Herra siunasi Oobed-Edomin taloa ja kaikkea, mitä hänellä oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Hiiram, Tyyron kuningas, lähetti sanansaattajat Daavidin luo, sekä setripuita ja puuseppiä ja kivenhakkaajia rakentamaan hänelle linnaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'Ja Daavid ymmärsi, että Herra oli vahvistanut hänet Israelin kuninkaaksi, koska hänen kuninkuutensa oli korotettu korkealle Herran kansan Israelin tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'Jerusalemissa Daavid vielä otti vaimoja, ja Daavidille syntyi vielä poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'Ja nämä ovat niiden poikien nimet, jotka syntyivät hänelle Jerusalemissa: Sammua, Soobab, Naatan, Salomo,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Jibhar, Elisua, Elpelet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Noogah, Nefeg, Jaafia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, Beeljada ja Elifelet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Mutta kun filistealaiset kuulivat, että Daavid oli voideltu koko Israelin kuninkaaksi, lähtivät kaikki filistealaiset etsimään Daavidia. Kun Daavid sen kuuli, lähti hän heitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Kun filistealaiset olivat tulleet ja tehneet ryöstöretken Refaimin tasangolle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'kysyi Daavid Jumalalta: \"Menenkö minä filistealaisia vastaan, ja annatko sinä heidät minun käsiini?\" Ja Herra sanoi hänelle: \"Mene; minä annan heidät sinun käsiisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Niin he menivät Baal-Perasimiin, ja siellä Daavid voitti heidät. Ja Daavid sanoi: \"Jumala on murtanut viholliseni minun kädelläni, niinkuin vedet murtavat\". Siitä sen paikan nimeksi tuli Baal-Perasim.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'He jättivät siihen jumalansa, ja Daavid käski polttaa ne tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Mutta filistealaiset tekivät vielä kerran ryöstöretken tasangolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Niin Daavid kysyi taas Jumalalta, ja Jumala vastasi hänelle: \"Älä mene heidän jälkeensä, vaan kierrä heidät ja hyökkää heidän kimppuunsa balsamipuiden puolelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'Ja kun kuulet astunnan kahinan balsamipuiden latvoista, niin käy taisteluun, sillä Jumala on käynyt sinun edelläsi tuhotakseen filistealaisten leirin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'Daavid teki, niinkuin Jumala oli häntä käskenyt, ja niin he voittivat filistealaisten sotajoukon ja ajoivat heitä takaa Gibeonista aina Geseriin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'Niin Daavidin maine levisi kaikkiin maihin, ja Herra nosti kaikissa kansoissa pelon häntä kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'Ja hän rakensi itsellensä taloja Daavidin kaupunkiin ja valmisti paikan Jumalan arkille ja pystytti sille majan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Silloin Daavid käski: \"Älkööt muut kuin leeviläiset kantako Jumalan arkkia; sillä heidät on Herra valinnut kantamaan Jumalan arkkia ja palvelemaan häntä ikuisesti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Ja Daavid kokosi kaiken Israelin Jerusalemiin, tuomaan Herran arkkia siihen paikkaan, jonka hän oli sille valmistanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'Daavid kokosi Aaronin jälkeläiset ja leeviläiset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Kehatin jälkeläisistä: Uurielin, päämiehen, ja hänen veljensä, sata kaksikymmentä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Merarin jälkeläisistä: Asajan, päämiehen, ja hänen veljensä, kaksisataa kaksikymmentä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Geersomin jälkeläisistä: Jooelin, päämiehen, ja hänen veljensä, sata kolmekymmentä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Elisafanin jälkeläisistä: Semajan, päämiehen, ja hänen veljensä, kaksisataa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Hebronin jälkeläisistä: Elielin, päämiehen, ja hänen veljensä, kahdeksankymmentä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Ussielin jälkeläisistä: Amminadabin, päämiehen, ja hänen veljensä, sata kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Ja Daavid kutsui papit Saadokin ja Ebjatarin sekä leeviläiset Uurielin, Asajan, Jooelin, Semajan, Elielin ja Amminadabin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'ja sanoi heille: \"Te olette leeviläisten perhekuntien päämiehet. Pyhittäkää itsenne ja veljenne ja tuokaa Herran, Israelin Jumalan, arkki siihen paikkaan, jonka minä olen sille valmistanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Sillä sentähden, ettette ensimmäisellä kerralla olleet läsnä, mursi Herra, meidän Jumalamme, meidät; sillä me emme etsineet häntä, niinkuin olisi pitänyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Silloin papit ja leeviläiset pyhittäytyivät tuomaan Herran, Israelin Jumalan, arkkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'Ja leeviläiset kantoivat Jumalan arkkia korennoilla olallansa, niinkuin Mooses oli Herran sanan mukaan käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'Ja Daavid käski leeviläisten päämiesten asettaa veljensä, veisaajat, soittimilla, harpuilla, kanteleilla ja kymbaaleilla kaiuttamaan riemuvirsiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Niin leeviläiset asettivat soittamaan Heemanin, Jooelin pojan, ja hänen heimolaisistaan Aasafin, Berekjan pojan, ja heidän heimolaisistaan, Merarin jälkeläisistä, Eetanin, Kuusajan pojan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'ja heidän kanssaan heidän arvossa lähinnä olevista heimolaisistaan: Sakarjan, Benin ja Jaasielin, Semiramotin, Jehielin, Unnin, Eliabin, Benajan, Maasejan, Mattitjan, Elifelehun, Miknejan, Oobed-Edomin ja Jegielin, ovenvartijat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'Ja veisaajista oli Heemanin, Aasafin ja Eetanin soitettava vaskikymbaaleilla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Sakarjan, Ussielin, Semiramotin, Jehielin, Unnin, Eliabin, Maasejan ja Benajan harpuilla korkeassa äänialassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Mattitjan, Elifelehun, Miknejan, Oobed-Edomin, Jegielin ja Asasjan kanteleilla matalassa äänialassa, veisuuta johtaaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'Kenanja, leeviläisten johtaja kantajatehtävässä, valvoi kantamista, sillä hän oli taitava siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Berekja ja Elkana olivat arkin ovenvartijat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'Ja papit Sebanja, Joosafat, Netanel, Amasai, Sakarja, Benaja ja Elieser puhalsivat torviin Jumalan arkin edellä, ja Oobed-Edom ja Jehia olivat arkin ovenvartijat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'Sitten Daavid, Israelin vanhimmat ja tuhannenpäämiehet menivät ja toivat riemuiten Herran liitonarkin Oobed-Edomin talosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'Ja kun Jumala auttoi leeviläisiä, jotka kantoivat Herran liitonarkkia, uhrattiin seitsemän härkää ja seitsemän oinasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'Daavid oli puettu hienosta pellavakankaasta tehtyyn viittaan ja samoin kaikki leeviläiset, jotka kantoivat arkkia, sekä veisaajat ja kantamisen johtaja Kenanja veisaajain kanssa; ja Daavidilla oli yllään pellavakasukka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Niin koko Israel toi Herran liitonarkin riemun raikuessa ja pasunain pauhatessa, torvien, kymbaalien, harppujen ja kannelten soidessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'Kun Herran liitonarkki tuli Daavidin kaupunkiin, katseli Miikal, Saulin tytär, ikkunasta, ja nähdessään kuningas Daavidin hyppivän ja karkeloivan halveksi hän häntä sydämessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'Kun he olivat tuoneet Jumalan arkin ja asettaneet sen majaan, jonka Daavid oli sille pystyttänyt, uhrasivat he polttouhreja ja yhteysuhreja Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'Ja kun Daavid oli uhrannut polttouhrin ja yhteysuhrit, siunasi hän kansan Herran nimeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'Ja hän jakoi kaikille israelilaisille, sekä miehille että naisille, kullekin leipäkakun, kappaleen lihaa ja rypälekakun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'Ja hän asetti Herran arkin eteen leeviläisiä palvelemaan ja kunnioittamaan, kiittämään ja ylistämään Herraa, Israelin Jumalaa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Aasafin johtajaksi, toiseksi Sakarjan, sitten Jegielin, Semiramotin, Jehielin, Mattitjan, Eliabin, Benajan, Oobed-Edomin ja Jegielin soittamaan harpuilla ja kanteleilla, Aasafin helistäessä kymbaaleja');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'ja pappien, Benajan ja Jahasielin, soittaessa yhtämittaa torvia Jumalan liitonarkin edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Silloin, sinä päivänä, ensi kerran Daavid asetti Aasafin ja hänen veljensä kiittämään Herraa näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, '\"Kiittäkää Herraa, julistakaa hänen nimeänsä, tehkää hänen suuret tekonsa tiettäviksi kansojen keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Laulakaa hänelle, veisatkaa hänelle, puhukaa kaikista hänen ihmeistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Hänen pyhä nimensä olkoon teidän kerskauksenne; iloitkoon niiden sydän, jotka etsivät Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Kysykää Herraa ja hänen voimaansa, etsikää alati hänen kasvojansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Muistakaa hänen ihmetöitänsä, jotka hän on tehnyt, hänen ihmeitänsä ja hänen suunsa tuomioita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'te Israelin, hänen palvelijansa, siemen, Jaakobin lapset, te hänen valittunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'Hän, Herra, on meidän Jumalamme; hänen tuomionsa käyvät yli kaiken maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Muistakaa hänen liittonsa iankaikkisesti, hamaan tuhansiin polviin, sana, jonka hän on säätänyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'liitto, jonka hän teki Aabrahamin kanssa, ja hänen lisakille vannomansa vala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'Hän vahvisti sen käskyksi Jaakobille, Israelille iankaikkiseksi liitoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Hän sanoi: \'Sinulle minä annan Kanaanin maan, se olkoon teidän perintöosanne\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Teitä oli vähäinen joukko, vain harvoja, ja te olitte muukalaisia siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'Ja he vaelsivat kansasta kansaan ja yhdestä valtakunnasta toiseen kansaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Hän ei sallinut kenenkään heitä vahingoittaa, ja hän rankaisi kuninkaita heidän tähtensä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, '\'Älkää koskeko minun voideltuihini, älkää tehkö pahaa minun profeetoilleni\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Veisatkaa Herralle, kaikki maa, julistakaa päivästä päivään hänen pelastustekojansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Ilmoittakaa pakanain seassa hänen kunniaansa, hänen ihmeitänsä kaikkien kansojen seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Sillä Herra on suuri ja sangen ylistettävä, hän on peljättävä yli kaikkien jumalain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Sillä kaikki kansojen jumalat ovat epäjumalia, mutta Herra on tehnyt taivaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Kirkkaus ja kunnia on hänen kasvojensa edessä, väkevyys ja riemu hänen asuinsijassaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Antakaa Herralle, te kansojen sukukunnat, antakaa Herralle kunnia ja väkevyys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Antakaa Herralle hänen nimensä kunnia, tuokaa lahjoja ja tulkaa hänen kasvojensa eteen, kumartakaa Herraa pyhässä kaunistuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Vaviskaa hänen kasvojensa edessä, kaikki maa. Maan piiri pysyy lujana, se ei horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Iloitkoot taivaat, ja riemuitkoon maa; ja sanottakoon pakanain seassa: \'Herra on kuningas!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Pauhatkoon meri ja kaikki, mitä siinä on; ihastukoot kedot ja kaikki, mitä niissä on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'riemuitkoot silloin metsän puut Herran edessä, sillä hän tulee tuomitsemaan maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'Ja sanokaa: \'Pelasta meidät, sinä pelastuksemme Jumala, kokoa ja vapahda meidät pakanain seasta, että me kiittäisimme sinun pyhää nimeäsi ja kerskaisimme sinun ylistyksestäsi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Ylistetty olkoon Herra, Israelin Jumala, iankaikkisesta iankaikkiseen.\" Ja kaikki kansa sanoi: \"Amen\", ja ylisti Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Ja hän asetti Aasafin ja hänen veljensä sinne Herran liitonarkin eteen tekemään vakituista palvelusta arkin edessä, kunakin päivänä sen päivän palveluksen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'mutta Oobed-Edomin ja heidän veljensä, yhteensä kuusikymmentä kahdeksan, nimittäin Oobed-Edomin, Jeditunin pojan, ja Hoosan, ovenvartijoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Ja pappi Saadokin ja hänen veljensä, papit, hän asetti Herran asumuksen eteen, uhrikukkulalle, joka on Gibeonissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'uhraamaan polttouhreja Herralle polttouhrialttarilla, aina aamuin ja illoin, kaikki niinkuin on kirjoitettuna Herran laissa, jonka hän on antanut Israelille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'Ja heidän kanssaan olivat Heeman ja Jedutun ynnä muut valitut, nimeltä mainitut, kiittämässä Herraa siitä, että hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'Näiden, Heemanin ja Jedutunin, hallussa oli torvet ja kymbaalit soittajia varten ynnä muut soittimet Jumalan virttä varten. Ja Jedutunin pojat vartioivat ovia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'Sitten kaikki kansa lähti kukin kotiinsa, ja Daavid kääntyi takaisin tervehtimään perhettänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'Kerran, kun Daavid istui linnassansa, sanoi Daavid profeetta Naatanille: \"Katso, minä asun setripuisessa palatsissa, mutta Herran liitonarkki on telttakankaan alla\". Naatan sanoi Daavidille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, '\"Tee vain kaikki, mitä mielessäsi on, sillä Jumala on sinun kanssasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Mutta sinä yönä tapahtui, että Naatanille tuli tämä Jumalan sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, '\"Mene ja sano minun palvelijalleni Daavidille: Näin sanoo Herra: Et sinä ole rakentava minulle huonetta asuakseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Minä en ole asunut huoneessa siitä päivästä asti, jona johdatin Israelin tänne, tähän päivään saakka, vaan minä olen muuttanut teltasta telttaan ja asumuksesta asumukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Olenko minä koskaan, missä olenkin vaeltanut kaikessa Israelissa, kenellekään Israelin tuomareista, joita olen asettanut kaitsemaan kansaani, sanonut näin: Miksi ette ole rakentaneet minulle setripuista huonetta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Sano siis minun palvelijalleni Daavidille: Näin sanoo Herra Sebaot: Minä olen ottanut sinut laitumelta, lammasten jäljestä, kansani Israelin ruhtinaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'Ja minä olen ollut sinun kanssasi kaikkialla, missä sinä vaelsit, ja olen hävittänyt kaikki vihollisesi sinun tieltäsi. Ja minä teen sinulle nimen, suurimpien nimien vertaisen maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'Ja minä valmistan sijan kansalleni Israelille ja istutan sen niin, että se asuu paikallansa eikä enää ole levoton eivätkä vääryyden tekijät sitä enää vaivaa niinkuin ennen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'siitä ajasta saakka, jolloin minä asetin tuomareita kansalleni Israelille. Ja minä nöyryytän kaikki sinun vihollisesi. Ja minä ilmoitan sinulle, että Herra on rakentava sinulle huoneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Kun sinun päiväsi ovat päättyneet ja sinä lähdet isiesi tykö, korotan minä sinun seuraajaksesi jälkeläisesi, joka on yksi sinun pojistasi; ja minä vahvistan hänen kuninkuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Hän on rakentava minulle huoneen, ja minä vahvistan hänen valtaistuimensa ikuisiksi ajoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Minä olen oleva hänen isänsä, ja hän on oleva minun poikani; ja armoani minä en ota häneltä pois, niinkuin otin siltä, joka oli sinun edelläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Ja minä pidän hänet pystyssä huoneessani ja valtakunnassani iäti, ja hänen valtaistuimensa on oleva iäti vahva.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Aivan näillä sanoilla ja tämän näyn mukaan Naatan puhui Daavidille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Niin kuningas Daavid meni ja asettui Herran eteen ja sanoi: \"Mikä olen minä, Herra Jumala, ja mikä on minun sukuni, että olet saattanut minut tähän asti?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Mutta tämäkin on ollut vähän sinun silmissäsi, Jumala, ja niin sinä olet puhunut palvelijasi suvulle myöskin kaukaisista asioista ja olet nähnyt minut nousevina ihmispolvina, Herra Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Mitä Daavid enää sinulle puhuisi kunniasta, jota olet osoittanut palvelijallesi? Sinähän tunnet palvelijasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Herra, palvelijasi tähden ja oman mielesi mukaan sinä olet tehnyt kaiken tämän suuren ja ilmoittanut kaikki nämä suuret asiat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Herra, kaiken sen mukaan, mitä me olemme korvillamme kuulleet, ei ole sinun vertaistasi, eikä ole muuta jumalaa kuin sinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'Ja missä on maan päällä toista kansaa sinun kansasi Israelin vertaista, jota Jumala itse on käynyt lunastamaan kansaksensa, ja niin sinä olet tehnyt itsellesi suuren ja peljättävän nimen karkoittamalla pakanat kansasi tieltä, jonka sinä Egyptistä lunastit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Ja sinä olet asettanut kansasi Israelin omaksi kansaksesi ikuisiksi ajoiksi, ja sinä, Herra, olet tullut heidän Jumalaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Niin olkoon nyt, Herra, se sana, jonka sinä olet puhunut palvelijastasi ja hänen suvustansa, vahva ikuisiksi ajoiksi. Tee, niinkuin olet puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Silloin sinun nimesi on oleva vahva ja tuleva suureksi ikuisiksi ajoiksi, ja se on oleva: Herra Sebaot, Israelin Jumala, Jumala Israelissa. Ja palvelijasi Daavidin suku on pysyvä sinun edessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Sillä sinä, minun Jumalani, olet ilmoittanut palvelijallesi rakentavasi hänelle huoneen. Siitä palvelijasi on saanut rohkeuden rukoilla sinun edessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'Ja nyt, Herra, sinä olet Jumala; ja kun olet luvannut palvelijallesi tämän hyvän,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'niin suvaitse nyt siunata palvelijasi sukua, että se pysyisi iäti sinun edessäsi. Sillä mitä sinä, Herra, siunaat, se on oleva siunattu iäti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'Sen jälkeen Daavid voitti filistealaiset ja nöyryytti heidät; ja hän otti Gatin ja sen tytärkaupungit filistealaisten käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Hän voitti myös mooabilaiset, ja niin mooabilaiset tulivat Daavidin veronalaisiksi palvelijoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Samoin Daavid voitti Hadareserin, Sooban kuninkaan, Hamatin suunnalla, kun tämä oli menossa lujittamaan valtaansa Eufrat-virran rannoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Ja Daavid otti häneltä tuhat vaunuhevosta, seitsemäntuhatta ratsumiestä ja kaksikymmentä tuhatta jalkamiestä, ja Daavid katkoi kaikilta vaunuhevosilta vuohisjänteet; ainoastaan sata vaunuhevosta hän niistä säästi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Ja kun Damaskon aramilaiset tulivat auttamaan Hadareseria, Sooban kuningasta, voitti Daavid kaksikymmentäkaksi tuhatta aramilaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Ja Daavid asetti maaherroja Damaskon Aramiin; ja aramilaiset tulivat Daavidin veronalaisiksi palvelijoiksi. Näin Herra antoi Daavidille voiton, mihin tahansa tämä meni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Ja Daavid otti ne kultavarustukset, jotka Hadareserin palvelijoilla oli yllään, ja vei ne Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Mutta Hadareserin kaupungeista, Tibhatista ja Kuunista, Daavid otti sangen paljon vaskea. Siitä Salomo teetti vaskimeren, pylväät ja vaskikalut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Kun Toou, Hamatin kuningas, kuuli, että Daavid oli voittanut Hadareserin, Sooban kuninkaan, koko sotajoukon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'lähetti hän poikansa Hadoramin kuningas Daavidin luo tervehtimään häntä ja onnittelemaan häntä siitä, että hän oli taistellut Hadareserin kanssa ja voittanut hänet; Hadareser oli näet ollut Tooun vastustaja. Ja hänellä oli mukanaan kaikkinaisia kulta-,hopea-ja vaskikaluja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Nekin kuningas Daavid pyhitti Herralle samoin kuin hopean ja kullan, minkä hän oli ottanut kaikilta kansoilta: Edomilta, Mooabilta, ammonilaisilta, filistealaisilta ja Amalekilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'Ja kun Abisai, Serujan poika, oli Suolalaaksossa voittanut edomilaiset, kahdeksantoista tuhatta miestä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'asetti hän maaherroja Edomiin, ja kaikki edomilaiset tulivat Daavidin palvelijoiksi. Näin Herra antoi Daavidille voiton, mihin tahansa tämä meni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'Ja Daavid hallitsi koko Israelia ja teki kaikelle kansallensa sitä, mikä oikeus ja vanhurskaus on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Jooab, Serujan poika, oli sotajoukon ylipäällikkönä, ja Joosafat, Ahiludin poika, oli kanslerina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'Saadok, Ahitubin poika, ja Abimelek, Ebjatarin poika, olivat pappeina, ja Savsa oli kirjurina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benaja, Joojadan poika, oli kreettien ja pleettien päällikkönä; mutta Daavidin pojat olivat ensimmäiset kuninkaan rinnalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'Sen jälkeen ammonilaisten kuningas Naahas kuoli, ja hänen poikansa tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Niin Daavid sanoi: \"Minä osoitan laupeutta Haanunille, Naahaan pojalle, sillä hänen isänsä osoitti laupeutta minulle\". Ja Daavid lähetti sanansaattajat lohduttamaan häntä hänen isänsä kuoleman johdosta. Kun Daavidin palvelijat tulivat ammonilaisten maahan Haanunin luo lohduttamaan häntä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'sanoivat ammonilaisten päämiehet Haanunille: \"Luuletko sinä, että Daavid tahtoo kunnioittaa sinun isääsi, kun hän lähettää lohduttajia sinun luoksesi? Varmaankin hänen palvelijansa ovat tulleet luoksesi tutkimaan ja hävittämään ja vakoilemaan maata.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Niin Haanun otatti kiinni Daavidin palvelijat, ajatti heidän partansa ja leikkautti toisen puolen heidän vaatteistaan, peräpuolia myöten, ja päästi heidät sitten menemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Kun tultiin kertomaan Daavidille miehistä, lähetti hän sanan heitä vastaan, sillä miehiä oli pahasti häväisty. Ja kuningas käski sanoa: \"Jääkää Jerikoon, kunnes partanne on kasvanut, ja tulkaa sitten takaisin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'Kun ammonilaiset huomasivat joutuneensa Daavidin vihoihin, lähettivät Haanun ja ammonilaiset tuhat talenttia hopeata palkatakseen itsellensä Mesopotamiasta, Maakan Aramista ja Soobasta sotavaunuja ja ratsumiehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Niin he palkkasivat itselleen kolmekymmentäkaksi tuhatta sotavaunua sekä Maakan kuninkaan ja hänen väkensä; nämä tulivat ja leiriytyivät Meedeban edustalle. Ja ammonilaiset kokoontuivat kaupungeistaan ja lähtivät sotaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Kun Daavid sen kuuli, lähetti hän Jooabin ja koko sotajoukon, urhot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'Niin ammonilaiset lähtivät ja asettuivat sotarintaan kaupungin portin edustalle, mutta kuninkaat, jotka olivat tulleet sinne, olivat eri joukkona kedolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Kun Jooab näki, että häntä uhkasi hyökkäys edestä ja takaa, valitsi hän miehiä kaikista Israelin valiomiehistä ja asettui sotarintaan aramilaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Mutta muun väen hän antoi veljensä Abisain johtoon, ja nämä asettuivat sotarintaan ammonilaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'Ja hän sanoi: \"Jos aramilaiset tulevat minulle ylivoimaisiksi, niin tule sinä minun avukseni: jos taas ammonilaiset tulevat sinulle ylivoimaisiksi, niin minä autan sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Ole luja, ja pysykäämme lujina kansamme puolesta ja meidän Jumalamme kaupunkien puolesta. Tehköön sitten Herra, minkä hyväksi näkee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Sitten Jooab ja väki, joka oli hänen kanssaan, ryhtyi taisteluun aramilaisia vastaan, ja nämä pakenivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Ja kun ammonilaiset näkivät aramilaisten pakenevan, pakenivat hekin hänen veljeänsä Abisaita ja menivät kaupunkiin. Mutta Jooab lähti Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'Kun aramilaiset näkivät, että Israel oli voittanut heidät, lähettivät he sanansaattajat nostattamaan niitä aramilaisia, jotka asuivat tuolla puolella Eufrat-virran ja joita johti Soofak, Hadareserin sotapäällikkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'Kun se ilmoitettiin Daavidille, kokosi hän kaiken Israelin ja meni Jordanin yli, ja tultuaan heitä lähelle hän asettui sotarintaan heitä vastaan. Ja kun Daavid oli asettunut sotarintaan aramilaisia vastaan, ryhtyivät nämä taisteluun hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Mutta aramilaiset pakenivat Israelia, ja Daavid tappoi aramilaisilta seitsemäntuhatta vaunuhevosta ja neljäkymmentä tuhatta jalkamiestä ja surmasi heidän sotapäällikkönsä Soofakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Kun Hadareserin palvelijat näkivät, että Israel oli voittanut heidät, tekivät he Daavidin kanssa rauhan ja palvelivat häntä. Sitten aramilaiset eivät enää tahtoneet auttaa ammonilaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'Vuoden vaihteessa, kuningasten sotaanlähtöaikana, vei Jooab sotajoukon sotaretkelle; ja hän hävitti ammonilaisten maata ja piiritti Rabbaa. Mutta Daavid itse jäi Jerusalemiin. Sitten Jooab valtasi Rabban ja hävitti sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'Ja Daavid otti heidän kuninkaansa kruunun hänen päästänsä ja havaitsi sen painavan talentin kultaa, ja siinä oli kallis kivi; se pantiin Daavidin päähän. Ja hän vei kaupungista hyvin paljon saalista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Ja kansan, joka siellä oli, hän vei pois ja pani sahaamaan kiviä, pani rautahakkujen ja kivisahojen ääreen. Näin Daavid teki kaikille ammonilaisten kaupungeille. Sitten Daavid ja kaikki väki palasi Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Sen jälkeen syttyi taistelu filistealaisia vastaan Geserissä. Silloin huusalainen Sibbekai surmasi Sippain, joka oli Raafan jälkeläisiä, ja niin heidät nöyryytettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Taas oli taistelu filistealaisia vastaan, ja Elhanan, Jaaorin poika, surmasi Lahmin, gatilaisen Goljatin veljen, jonka peitsen varsi oli niinkuin kangastukki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Taas oli taistelu Gatissa. Siellä oli suurikasvuinen mies, jolla oli kuusi sormea ja kuusi varvasta, yhteensä kaksikymmentä neljä; hänkin polveutui Raafasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Ja kun hän häpäisi Israelia, surmasi hänet Joonatan, Daavidin veljen Simean poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Nämä polveutuivat gatilaisesta Raafasta; he kaatuivat Daavidin ja hänen palvelijainsa käden kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Mutta saatana nousi Israelia vastaan ja yllytti Daavidin laskemaan Israelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Niin Daavid sanoi Jooabille ja kansan päämiehille: \"Menkää ja laskekaa Israel Beersebasta Daaniin asti ja ilmoittakaa minulle, että saan tietää heidän lukumääränsä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Jooab vastasi: \"Herra lisätköön kansansa, olkoon se kuinka suuri tahansa, satakertaiseksi. Ovathan he, herrani, kuningas, kaikki herrani palvelijoita. Miksi herrani pyytää tätä? Miksi Israel näin joutuisi vikapääksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Kuitenkin kuninkaan sana velvoitti Jooabia, ja niin Jooab lähti ja kierteli koko Israelin. Sitten hän tuli Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'Ja Jooab ilmoitti Daavidille kansan lasketun lukumäärän: koko Israelissa oli yksitoistasataa tuhatta sotakuntoista miekkamiestä, ja Juudassa oli neljäsataa seitsemänkymmentä tuhatta miekkamiestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Mutta Leevistä ja Benjaminista hän ei pitänyt katselmusta yhdessä muiden kanssa, sillä kuninkaan käsky oli Jooabille kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Mutta tämä asia oli Jumalan silmissä paha, ja hän löi Israelia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'Niin Daavid sanoi Jumalalle: \"Minä olen tehnyt suuren synnin tehdessäni tämän; mutta anna nyt anteeksi palvelijasi rikos, sillä minä olen menetellyt ylen tyhmästi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Ja Herra puhui Gaadille, Daavidin näkijälle, näin: \"Mene ja puhu Daavidille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Näin sanoo Herra: Kolme minä asetan sinun eteesi: valitse itsellesi yksi niistä, niin minä teen sen sinulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Niin Gaad meni Daavidin tykö ja sanoi hänelle: \"Näin sanoo Herra: Valitse itsellesi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'joko kolme nälkävuotta tahi kolme kuukautta hävitystä ahdistajaisi vainotessa, vihollistesi miekka kintereilläsi, tahi kolmeksi päiväksi Herran miekka ja ruttotauti maahan, Herran enkeli tuottamaan tuhoa koko Israelin alueelle. Katso nyt, mitä minä vastaan hänelle joka minut lähetti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'Daavid vastasi Gaadille: \"Minä olen suuressa hädässä. Tahdon langeta Herran käsiin, sillä hänen laupeutensa on sangen suuri; ihmisten käsiin minä en tahdo langeta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Niin Herra antoi ruton tulla Israeliin, ja Israelista kaatui seitsemänkymmentä tuhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Ja Jumala lähetti enkelin Jerusalemia vastaan tuhoamaan sitä; ja kun se sitä tuhosi, katsoi Herra siihen ja katui sitä pahaa ja sanoi tuhoojaenkelille: \"Jo riittää; laske kätesi alas\". Ja Herran enkeli seisoi silloin jebusilaisen Ornanin puimatantereen luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Kun Daavid nosti silmänsä ja näki Herran enkelin seisovan maan ja taivaan välillä, kädessänsä paljastettu miekka ojennettuna Jerusalemin yli, lankesivat Daavid ja vanhimmat, säkkeihin verhottuina, kasvoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Ja Daavid sanoi Jumalalle: \"Minähän käskin laskea kansan, ja minä siis olen se, joka olen tehnyt syntiä ja menetellyt pahoin. Mutta nämä minun lampaani, mitä he ovat tehneet? Herra, minun Jumalani, sattukoon sinun kätesi minuun ja minun isäni perheeseen, mutta ei sinun kansaasi, sille vitsaukseksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Silloin Herran enkeli käski Gaadin sanoa Daavidille, että Daavid menisi pystyttämään Herralle alttarin jebusilaisen Ornanin puimatantereelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'Ja Daavid meni sen sanan mukaan, jonka Gaad oli Herran nimeen puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Ja kun Ornan kääntyi, näki hän enkelin, ja hänen neljä poikaansa piiloutui; sillä Ornan oli puimassa nisuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Mutta Daavid meni Ornanin luo, ja kun Ornan katsahti ylös ja näki Daavidin, lähti hän puimatantereelta ja kumartui Daavidin eteen kasvoilleen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Ja Daavid sanoi Ornanille: \"Anna minulle puimatantereen paikka, rakentaakseni siihen Herralle alttarin; täydestä hinnasta anna se minulle, että vitsaus taukoaisi kansasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Ornan vastasi Daavidille: \"Ota se itsellesi, ja herrani, kuningas, tehköön, mitä hyväksi näkee. Katso, minä annan härät polttouhriksi ja puimaäkeet haloiksi sekä nisut ruokauhriksi; kaikki minä annan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'Mutta kuningas Daavid sanoi Ornanille: \"Ei niin, vaan minä ostan ne sinulta täydestä hinnasta; sillä minä en ota Herralle sitä, mikä on sinun, enkä uhraa ilmaiseksi saatua polttouhria\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Niin Daavid antoi Ornanille siitä paikasta kuudensadan sekelin painon kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'Ja Daavid rakensi sinne alttarin Herralle ja uhrasi polttouhreja ja yhteysuhreja, ja kun hän huusi Herraa, vastasi Herra tulella, jonka hän lähetti taivaasta polttouhrialttarille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'Ja Herra käski enkelin pistää miekkansa tuppeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Siihen aikaan kun Daavid näki, että Herra oli kuullut häntä jebusilaisen Ornanin puimatantereella, uhrasi hän siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Mutta Herran asumus, jonka Mooses oli teettänyt erämaassa, ja polttouhrialttari olivat siihen aikaan Gibeonin uhrikukkulalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'Eikä Daavid rohjennut mennä Jumalan eteen etsimään häntä, sillä hän oli peljästynyt Herran enkelin miekkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'Ja Daavid sanoi: \"Tässä olkoon Herran Jumalan temppeli ja tässä alttari Israelin polttouhria varten\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Niin Daavid käski koota muukalaiset, jotka olivat Israelin maassa. Ja hän asetti kivenhakkaajia hakkaamaan kiviä Jumalan temppelin rakentamiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Ja Daavid hankki paljon rautaa portinovien nauloiksi ja sinkilöiksi ja niin paljon vaskea, ettei se ollut punnittavissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'ja suunnattomat määrät setripuita, sillä siidonilaiset ja tyyrolaiset toivat paljon setripuita Daavidille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Sillä Daavid ajatteli: \"Minun poikani Salomo on nuori ja hento, ja Herralle rakennettava temppeli on tehtävä ylen suuri, niin että sitä mainitaan ja kiitetään kaikissa maissa. Minä siis hankin hänelle varastot.\" Niin Daavid hankki ennen kuolemaansa suuret varastot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Ja hän kutsui poikansa Salomon ja käski hänen rakentaa temppelin Herralle, Israelin Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'Ja Daavid sanoi Salomolle: \"Poikani, minä aioin itse rakentaa temppelin Herran, Jumalani, nimelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Mutta minulle tuli tämä Herran sana: \'Sinä olet vuodattanut paljon verta ja käynyt suuria sotia. Sinä et ole rakentava temppeliä minun nimelleni, koska olet vuodattanut niin paljon verta maahan minun edessäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Katso, sinulle on syntyvä poika; hänestä on tuleva rauhan mies, ja minä annan hänen päästä rauhaan kaikilta hänen ympärillään asuvilta vihollisilta, sillä Salomo on oleva hänen nimensä ja minä annan rauhan ja levon Israelille hänen päivinänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'Hän on rakentava temppelin minun nimelleni. Hän on oleva minun poikani, ja minä olen oleva hänen isänsä. Ja minä vahvistan hänen kuninkuutensa valtaistuimen ikuisiksi ajoiksi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Olkoon siis Herra sinun kanssasi, poikani, että menestyisit ja saisit rakennetuksi temppelin Herralle, Jumalallesi, niinkuin hän on sinusta puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Antakoon vain Herra sinulle älyä ja ymmärrystä ja asettakoon sinut Israelia hallitsemaan ja noudattamaan Herran, Jumalasi, lakia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Silloin sinä menestyt, jos tarkoin noudatat niitä käskyjä ja oikeuksia, jotka Herra antoi Moosekselle Israelia varten. Ole luja ja rohkea, älä pelkää äläkä arkaile.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'Katso, vaivanalaisenakin minä olen hankkinut Herran temppeliä varten satatuhatta talenttia kultaa ja tuhat kertaa tuhat talenttia hopeata sekä vaskea ja rautaa niin paljon, ettei se ole punnittavissa, sillä sitä on ylen paljon. Minä olen myös hankkinut hirsiä ja kiviä, ja sinä saat hankkia vielä lisää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Paljon on sinulla myöskin työmiehiä, kivenhakkaajia, muurareita, puuseppiä ja kaikkinaisen työn taitajia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Kullalla, hopealla, vaskella ja raudalla ei ole määrää. Nouse, ryhdy työhön, ja Herra olkoon sinun kanssasi!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'Ja Daavid käski kaikkia Israelin päämiehiä auttamaan poikaansa Salomoa, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '\"Onhan Herra, teidän Jumalanne, ollut teidän kanssanne ja suonut teidän päästä joka taholla rauhaan; sillä hän on antanut maan asukkaat minun käsiini ja maa on tehty alamaiseksi Herralle ja hänen kansallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Kääntäkää siis sydämenne ja sielunne etsimään Herraa, Jumalaanne; nouskaa ja rakentakaa Herran, Jumalan, pyhäkkö, että Herran liitonarkki ja Jumalan pyhät kalut voitaisiin viedä temppeliin, joka on rakennettava Herran nimelle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'Kun Daavid oli tullut vanhaksi ja saanut elämästä kyllänsä, teki hän poikansa Salomon Israelin kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'Ja hän kutsui kokoon kaikki Israelin päämiehet, papit ja leeviläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Ja leeviläiset luettiin, kolmikymmenvuotiset ja sitä vanhemmat, ja heidän lukumääränsä, pääluvun mukaan, oli kolmekymmentäkahdeksan tuhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, '\"Näistä olkoon kaksikymmentäneljä tuhatta johtamassa töitä Herran temppelissä ja kuusi tuhatta päällysmiehinä ja tuomareina;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'ja neljä tuhatta olkoon ovenvartijoina, ja neljä tuhatta ylistäköön Herraa soittimilla, jotka minä olen teettänyt ylistämistä varten.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'Ja Daavid jakoi heidät osastoihin Leevin poikien Geersonin, Kehatin ja Merarin mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Geersonilaisia olivat Ladan ja Siimei.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Ladanin pojat olivat Jehiel, päämies, Seetam ja Jooel, kaikkiaan kolme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Siimein pojat olivat Selomit, Hasiel ja Haaran, kaikkiaan kolme. Nämä olivat Ladanin perhekuntien päämiehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Ja Siimein pojat olivat Jahat, Siina, Jeus ja Beria. Nämä olivat Siimein pojat, kaikkiaan neljä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'Jahat oli päämies, Siisa toinen; mutta Jeuksella ja Berialla ei ollut monta poikaa, niin että heistä tuli yksi perhekunta, yksi palvelusvuoro.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Kehatin pojat olivat Amram, Jishar, Hebron ja Ussiel, kaikkiaan neljä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Amramin pojat olivat Aaron ja Mooses. Mutta Aaron poikinensa erotettiin olemaan ikuisesti pyhitetty, korkeasti-pyhä, ikuisesti suitsuttamaan Herran edessä, palvelemaan häntä ja siunaamaan hänen nimessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Jumalan miehen Mooseksen pojat luettiin Leevin sukukuntaan kuuluviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Mooseksen pojat olivat Geersom ja Elieser.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Geersomin poika oli Sebuel, päämies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'Elieserin poika oli Rehabja, päämies; Elieserillä ei ollut muita poikia. Mutta Rehabjan poikia oli ylen paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Jisharin poika oli Selomit, päämies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Hebronin pojat olivat Jeria, päämies, Amarja toinen, Jahasiel kolmas ja Jekamam neljäs.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Ussielin pojat olivat Miika, päämies, ja Jissia toinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Merarin pojat olivat Mahli ja Muusi. Mahlin pojat olivat Eleasar ja Kiis.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'Kun Eleasar kuoli, ei häneltä jäänyt poikia, vaan ainoastaan tyttäriä, jotka heidän serkkunsa, Kiisin pojat, ottivat vaimoiksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Muusin pojat olivat Mahli, Eeder ja Jeremot, kaikkiaan kolme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Nämä olivat Leevin pojat, heidän perhekuntiensa mukaan, perhekunta-päämiehet, niin monta kuin heitä oli ollut katselmuksessa, nimien lukumäärän mukaan, pääluvun mukaan, ne, jotka toimittivat palvelustehtäviä Herran temppelissä, kaksikymmenvuotiaat ja sitä vanhemmat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Sillä Daavid sanoi: \"Herra, Israelin Jumala, on suonut kansansa päästä lepoon ja on asuva Jerusalemissa ikuisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Niinpä ei leeviläistenkään tarvitse kantaa asumusta eikä mitään kaluja, joita tarvitaan siinä tehtävissä töissä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, '-Sillä Daavidin viimeisten määräysten mukaan laskettiin Leevin poikien lukuun kaksikymmenvuotiaat ja sitä vanhemmat. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Heidän tehtäväkseen tuli: olla Aaronin poikien apuna Herran temppelin töissä; pitää huoli esikartanoista ja kammioista, kaiken pyhän puhtaana pitämisestä ja Jumalan temppelin töistä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'näkyleivistä, ruokauhriin tarvittavista lestyistä jauhoista, happamattomista ohukaisista, leivinlevystä ja jauhosekoituksesta sekä astia-ja pituusmitoista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'seisoa joka aamu kiittämässä ja ylistämässä Herraa, ja samoin joka ilta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'ja uhrata kaikki polttouhrit Herralle sapatteina, uudenkuun päivinä ja juhlina, niin paljon kuin niitä oli säädetty aina uhrattavaksi Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'Niin heidän oli hoidettava ilmestysmajan ja pyhäkön tehtävät sekä ne tehtävät, jotka heidän veljillään Aaronin pojilla oli palvellessaan Herran temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Nämä olivat Aaronin poikien osastot: Aaronin pojat olivat Naadab, Abihu, Eleasar ja Iitamar.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Mutta Naadab ja Abihu kuolivat ennen isäänsä, eikä heillä ollut poikia. Niin palvelivat ainoastaan Eleasar ja Iitamar pappeina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'Ja Daavid yhdessä Saadokin kanssa, joka oli Eleasarin poikia, ja Ahimelekin kanssa, joka oli Iitamarin poikia, jakoi heidät osastoihin heidän palvelusvuorojensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'Kun Eleasarin pojilla havaittiin olevan enemmän päämiehiä kuin Iitamarin pojilla, jaettiin heidät niin, että Eleasarin pojat saivat kuusitoista päämiestä perhekunnilleen ja Iitamarin pojat kahdeksan päämiestä perhekunnilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Heidät jaettiin arvalla, toiset niinkuin toisetkin, sillä pyhäkköruhtinaat ja Jumalan ruhtinaat otettiin sekä Eleasarin pojista että Iitamarin pojista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'Ja Semaja, Netanelin poika, kirjuri, joka oli Leevin sukua, kirjoitti heidät muistiin kuninkaan, päämiesten, pappi Saadokin ja Ahimelekin, Ebjatarin pojan, sekä pappien ja leeviläisten perhekuntien päämiesten läsnäollessa. Yksi perhekunta otettiin vuorotellen Eleasarin ja Iitamarin suvusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Ensimmäinen arpa tuli Joojaribille, toinen Jedajalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'kolmas Haarimille, neljäs Seoromille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'viides Malkialle, kuudes Miijaminille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'seitsemäs Koosille, kahdeksas Abialle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'yhdeksäs Jeesualle, kymmenes Sekanjalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'yhdestoista Eljasibille, kahdestoista Jaakimille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'kolmastoista Huppalle, neljästoista Jesebabille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'viidestoista Bilgalle, kuudestoista Immerille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'seitsemästoista Heesirille, kahdeksastoista Pissekselle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'yhdeksästoista Petahjalle, kahdeskymmenes Hesekielille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'kahdeskymmenes yhdes Jaakinille, kahdeskymmenes kahdes Gaamulille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'kahdeskymmenes kolmas Delajalle, kahdeskymmenes neljäs Maasjalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Nämä ovat heidän palvelusvuoronsa, kun he menevät Herran temppeliin, niinkuin heidän isänsä Aaron oli heille säätänyt, sen mukaan, kuin Herra, Israelin Jumala, oli häntä käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Mitä tulee muihin Leevin jälkeläisiin, niin oli Amramin jälkeläisiä Suubael, Suubaelin jälkeläisiä Jehdeja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Rehabjan jälkeläisiä päämies Jissia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'jisharilaisia Selomot, Selomotin jälkeläisiä Jahat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'Ja Jerian jälkeläisiä olivat: Amarja toinen, Jahasiel kolmas, Jekamam neljäs.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Ussielin jälkeläisiä oli Miika, Miikan jälkeläisiä Saamir.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Miikan veli oli Jissia; Jissian jälkeläisiä oli Sakarja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Merarin jälkeläisiä olivat Mahli ja Muusi sekä hänen poikansa Jaasian jälkeläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Merarilla oli jälkeläisiä pojastaan Jaasiasta ynnä Sooham, Sakkur ja Ibri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Mahlista polveutui Eleasar, jolla ei ollut poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Kiisistä polveutui Jerahmeel, joka oli Kiisin jälkeläisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'Ja Muusin jälkeläisiä olivat Mahli, Eeder ja Jerimot. Nämä olivat leeviläisten jälkeläiset heidän perhekuntiensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Myöskin nämä, niinhyvin perhekuntapäämiehet kuin heidän nuoremmat veljensä, heittivät arpaa samoin kuin heidän veljensä, Aaronin pojat, kuningas Daavidin, Saadokin ja Ahimelekin sekä pappien ja leeviläisten perhekuntien päämiesten läsnäollessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'Ja Daavid ja sotapäälliköt erottivat palvelukseen Aasafin, Heemanin ja Jedutunin pojat, jotka hurmoksissa soittivat kanteleilla, harpuilla ja kymbaaleilla. Ja tämä on luettelo miehistä, jotka tätä palvelustaan toimittivat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Aasafin poikia oli Sakkur, Joosef, Netanja ja Asarela, Aasafin pojat, Aasafin johdolla, joka hurmoksissa soitti kuninkaan johdolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Jedutunista: Jedutunin pojat Gedalja, Seri, Jesaja, Hasabja ja Mattitja, kaikkiaan kuusi, isänsä Jedutunin johdolla, joka hurmoksissa soitti kanteleilla kiitosta ja ylistystä Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Heemanista: Heemanin pojat Bukkia, Mattanja, Ussiel, Sebuel ja Jerimot, Hananja, Hanani, Eliata, Giddalti ja Roomamti-Eser, Josbekasa, Malloti, Hootir ja Mahasiot;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'nämä ovat kaikki Heemanin, kuninkaan näkijän, poikia, sen Jumalan sanan mukaan, että hän on korottava korkealle hänen sarvensa: Jumala oli antanut Heemanille neljätoista poikaa ja kolme tytärtä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Nämä kaikki isänsä johdon alaisina veisasivat Herran temppelissä kymbaalien, harppujen ja kanteleitten säestäessä, Jumalan temppelipalveluksessa, kuninkaan, Aasafin, Jedutunin ja Heemanin johdolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'Ja heidän ja heidän veljiensä lukumäärä, jotka oli opetettu veisaamaan Herran kunniaksi, kaikkien taitajien, oli kaksisataa kahdeksankymmentä kahdeksan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'Ja he heittivät arpaa palvelusjärjestyksestä, nuoremmat niinkuin vanhemmatkin, taitajat yhdessä oppilasten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Ensimmäinen arpa, Aasafin arpa, tuli Joosefille. Toinen Gedaljalle, hänelle itselleen sekä hänen veljilleen ja pojilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Kolmas Sakkurille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Neljäs Jisrille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Viides Netanjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Kuudes Bukkialle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Seitsemäs Jesarelalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Kahdeksas Jesajalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Yhdeksäs Mattanjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Kymmenes Siimeille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Yhdestoista Asarelille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Kahdestoista Hasabjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Kolmastoista Suubaelille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Neljästoista Mattitjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Viidestoista Jeremotille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Kuudestoista Hananjalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Seitsemästoista Josbekasalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Kahdeksastoista Hananille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Yhdeksästoista Mallotille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Kahdeskymmenes Elijjatalle, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Kahdeskymmenes yhdes Hootirille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Kahdeskymmenes kahdes Giddaltille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Kahdeskymmenes kolmas Mahasiotille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Kahdeskymmenes neljäs Roomamti-Eserille, hänen pojilleen ja veljilleen, joita oli kaikkiaan kaksitoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Mitä tulee ovenvartijain osastoihin, niin oli koorahilaisia Meselemja, Kooren poika, Aasafin jälkeläisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'Meselemjalla oli pojat: esikoinen Sakarja, toinen Jediael, kolmas Sebadja, neljäs Jatniel,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'viides Eelam, kuudes Joohanan, seitsemäs Eljoenai.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'Oobed-Edomilla oli pojat: esikoinen Semaja, toinen Joosabad, kolmas Jooah, neljäs Saakar, viides Netanel,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'kuudes Ammiel, seitsemäs Isaskar, kahdeksas Peulletai; sillä Jumala oli siunannut häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Ja hänen pojallensa Semajalle syntyi poikia, jotka hallitsivat isänsä sukua, sillä he olivat kykeneviä miehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Semajan pojat olivat Otni, Refael, Oobed ja Elsabad ja hänen veljensä, kykeneviä miehiä, Elihu ja Semakja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Kaikki nämä olivat Oobed-Edomin jälkeläisiä, he sekä heidän poikansa ja veljensä, kykeneviä miehiä, tarmokkaita palveluksessaan, kaikkiaan kuusikymmentä kaksi Oobed-Edomin jälkeläistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'Meselemjalla oli poikia ja veljiä, kykeneviä miehiä, kaikkiaan kahdeksantoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Ja Hoosalla, joka oli Merarin jälkeläisiä, oli poikia: päämies Simri, jonka hänen isänsä, kun ei ollut esikoista, asetti päämieheksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'toinen Hilkia, kolmas Tebalja, neljäs Sakarja; Hoosan poikia ja veljiä oli kaikkiaan kolmetoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Näiden ovenvartijain osastojen, päämiesten, samoinkuin heidän veljiensä, tehtävänä oli vartiopalvelus; sillä heidän oli palveltava Herran temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Ja he heittivät arpaa joka ovesta, nuoremmat niinkuin vanhemmatkin, perhekuntiensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'Itäpuolen arpa lankesi Selemjalle; myöskin hänen pojallensa Sakarjalle, joka oli ymmärtäväinen neuvonantaja, heitettiin arpa, ja hänelle tuli pohjoispuolen arpa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Oobed-Edomille määräsi arpa etelän ja hänen pojilleen varastohuoneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Suppimille ja Hoosalle lännen, jossa on Salleket-portti ylöspäin kohoavan tien kohdalla: vartiopaikan toisen vartiopaikan viereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Idän puolella oli kuusi leeviläistä, pohjoisen puolella neljä joka päivä, etelän puolella neljä joka päivä ja varastohuoneen luona kaksi ja kaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Parparin luona, lännen puolella, oli neljä tiellä ja kaksi Parparin luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Nämä ovat ovenvartijain osastot, koorahilaisten jälkeläisten ja Merarin jälkeläisten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Leeviläisistä hoiti Ahia Jumalan temppelin aarrekammioita ja pyhien lahjojen aarteita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Ladanin pojat, geersonilaisten jälkeläiset, Ladanista polveutuvat geersonilaisen Ladanin perhekuntien päämiehet, jehieliläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'jehieliläisten jälkeläiset, olivat Seetam ja hänen veljensä Jooel; he hoitivat Herran temppelin aarrekammioita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Mitä tulee amramilaisiin, jisharilaisiin, hebronilaisiin ja ossielilaisiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'niin Sebuel, Geersomin poika, joka oli Mooseksen poika, oli aarrekammioiden esimies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Ja hänen Elieseristä polveutuvat veljensä olivat: tämän poika Rehabja, tämän poika Jesaja, tämän poika Jooram, tämän poika Sikri ja tämän poika Selomot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Tämä Selomot ja hänen veljensä hoitivat kaikkia niiden pyhien lahjojen aarteita, jotka kuningas Daavid, perhekunta-päämiehet, tuhannen-ja sadanpäämiehet ja sotapäälliköt olivat pyhittäneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Sodista ja saaliista he olivat ne pyhittäneet Herran temppelin voimassapitämiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'Samoin kaikki, mitä Samuel, näkijä, Saul, Kiisin poika, Abner, Neerin poika, ja Jooab, Serujan poika, olivat pyhittäneet, kaikki, mikä pyhitettiin, jätettiin Selomitin ja hänen veljiensä hoitoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Jisharilaisista määrättiin Kenanja ja hänen poikansa maallisiin toimiin Israelissa, päällysmiehiksi ja tuomareiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Hebronilaisista määrättiin Hasabja ja hänen veljensä, tuhat seitsemänsataa kykenevää miestä, Israelin hallinnon hoitoon Jordanin länsipuolella, kaikkinaisiin Herran toimiin ja kuninkaan palvelukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Hebronilaisia oli Jeria, hebronilaisten päämies, heidän polveutumisensa ja isiensä mukaan-Daavidin neljäntenäkymmenentenä hallitusvuotena heidät tutkittiin ja heidän joukostaan tavattiin kykeneviä miehiä Gileadin Jaeserissa-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'sekä hänen veljensä, kaksituhatta seitsemänsataa kykenevää miestä, perhekunta-päämiehiä. Heidät kuningas Daavid asetti johtamaan ruubenilaisia, gaadilaisia ja toista puolta manasselaisten sukukuntaa kaikissa Jumalan ja kuninkaan asioissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'Israelilaisia, lukumääränsä mukaan, ynnä perhekunta-päämiehiä, tuhannen-ja sadanpäämiehiä ja heidän päällysmiehiänsä, jotka palvelivat kuningasta kaikessa, mikä koski osastoja, jotka tulivat ja lähtivät kuukausi kuukaudelta, vuoden kaikkina kuukausina, oli kussakin osastossa kaksikymmentäneljä tuhatta miestä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Ensimmäisen osaston, ensimmäisen kuukauden osaston, johtajana oli Jaasobeam, Sabdielin poika, ja hänen osastossaan oli kaksikymmentäneljä tuhatta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'hän oli Pereksen jälkeläisiä ja oli kaikkien sotapäälliköitten ylipäällikkö, ensimmäisenä kuukautena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'Toisen kuukauden osaston johtajana oli ahohilainen Doodai; hänen osastonsa johdossa oli myös ruhtinas Miklot, ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Kolmas sotapäällikkö, kolmantena kuukautena, oli Benaja, pappi Joojadan poika, ylipäällikkö; ja hänen osastossaan oli kaksikymmentaneljätuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Tämä Benaja oli sankari niiden kolmenkymmenen joukossa ja niiden kolmenkymmenen johtaja; ja hänen osastossaan oli hänen poikansa Ammisabad.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Neljäs, neljäntenä kuukautena, oli Asahel, Jooabin veli, ja hänen jälkeensä hänen poikansa Sebadja; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Viides, viidentenä kuukautena, oli päällikkö Samhut, jisrahilainen; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Kuudes, kuudentena kuukautena, oli tekoalainen Iira, Ikkeksen poika; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Seitsemäs, seitsemäntenä kuukautena, oli pelonilainen Heeles, efraimilaisia; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Kahdeksas, kahdeksantena kuukautena, oli huusalainen Sibbekai, serahilaisia; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Yhdeksäs, yhdeksäntenä kuukautena, oli anatotilainen Abieser, benjaminilaisia; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Kymmenes, kymmenentenä kuukautena, oli netofalainen Mahrai, serahilaisia; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Yhdestoista, yhdentenätoista kuukautena, oli piratonilainen Benaja, efraimilaisia; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Kahdestoista, kahdentenatoista kuukautena, oli netofalainen Heldai, Otnielista polveutuva; ja hänen osastossaan oli kaksikymmentäneljä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Israelin sukukuntien johtajat olivat: ruubenilaisten ruhtinas oli Elieser, Sikrin poika; simeonilaisten Sefatja, Maakan poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Leevin oli Hasabja, Kemuelin poika; Aaronin Saadok;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Juudan oli Elihu, Daavidin veljiä; Isaskarin Omri, Miikaelin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Sebulonin oli Jismaja, Obadjan poika; Naftalin Jerimot, Asrielin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'efraimilaisten oli Hoosea, Asasjan poika; toisen puolen Manassen sukukuntaa Jooel, Pedajan poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'toisen puolen Manassea, Gileadissa, oli Jiddo, Sakarjan poika; Benjaminin Jaasiel, Abnerin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Daanin Asarel, Jerohamin poika. Nämä olivat Israelin sukukuntien ruhtinaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'Mutta Daavid ei ottanut luetteloon kaksikymmenvuotiaita ja sitä nuorempia, sillä Herra oli luvannut tehdä Israelin monilukuiseksi niinkuin taivaan tähdet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Jooab, Serujan poika, oli alottanut laskemisen, mutta ei sitä lopettanut, sillä siitä kohtasi viha Israelia; eikä se luku tullut kuningas Daavidin aikakirjaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'Kuninkaan varastojen hoitaja oli Asmavet, Adielin poika. Kedolla, kaupungeissa, kylissä ja torneissa olevien varastojen hoitaja oli Joonatan, Ussian poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'Maatöitä tekevien peltotyömiesten kaitsija oli Esri, Kelubin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'Viinitarhain hoitaja oli raamatilainen Siimei. Viinitarhoista koottujen viinivarastojen hoitaja oli sifmiläinen Sabdi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Öljypuiden ja Alankomaassa kasvavien metsäviikunapuiden hoitaja oli gaderilainen Baal-Haanan. Öljyvarastojen hoitaja oli Jooas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'Saaronissa laitumella käyvien raavasten kaitsija oli saaronilainen Sitrai, ja tasangoilla laitumella käyvien raavasten kaitsija Saafat, Adlain poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'Kamelien kaitsija oli ismaelilainen Oobil; aasintammojen meeronotilainen Jehdeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'Pikkukarjan kaitsija oli hagrilainen Jaasis. Nämä kaikki olivat kuningas Daavidin omaisuuden ylihoitajia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Ja Joonatan, Daavidin setä, joka oli ymmärtäväinen mies ja kirjanoppinut, oli neuvonantaja. Jehiel, Hakmonin poika, oli kuninkaan lasten luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Ahitofel oli kuninkaan neuvonantaja, ja arkilainen Huusai oli kuninkaan ystävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Ahitofelin jälkeen tulivat Joojada, Benajan poika, ja Ebjatar. Kuninkaan sotapäällikkö oli Jooab.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Ja Daavid kokosi Jerusalemiin kaikki Israelin päämiehet, sukukuntien päämiehet, osastojen päälliköt, jotka palvelivat kuningasta, tuhannen-ja sadanpäämiehet, kuninkaan ja hänen poikiensa kaiken omaisuuden ja karjan ylihoitajat, hovimiehet, sankarit ja kaikki sotaurhot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Ja kuningas Daavid nousi seisomaan ja sanoi: \"Kuulkaa minua, veljeni ja kansani. Minä olin aikonut rakentaa huoneen Herran liitonarkin leposijaksi ja meidän Jumalamme jalkojen astinlaudaksi ja olin valmistautunut rakentamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Mutta Jumala sanoi minulle: \'Älä sinä rakenna temppeliä minun nimelleni, sillä sinä olet sotilas ja olet vuodattanut verta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Kuitenkin valitsi Herra, Israelin Jumala, minut kaikesta isäni suvusta olemaan Israelin kuninkaana ikuisesti. Sillä Juudan hän valitsi ruhtinaaksi ja Juudan heimosta minun isäni suvun, ja isäni poikien joukossa olin minä hänelle otollinen, niin että hän teki minut koko Israelin kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'Ja kaikkien minun poikieni joukosta, sillä Herra on antanut minulle monta poikaa, hän valitsi poikani Salomon istumaan Herran valtakunnan valtaistuimella ja hallitsemaan Israelia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'Ja hän sanoi minulle: \'Sinun poikasi Salomo on rakentava minun temppelini ja esikartanoni; sillä minä olen valinnut hänet pojakseni ja minä olen oleva hänen isänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'Ja minä vahvistan hänen kuninkuutensa iankaikkisesti, jos hän on luja ja pitää minun käskyni ja oikeuteni, niinkuin hän nyt tekee.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Ja nyt minä sanon koko Israelin, Herran seurakunnan, läsnäollessa ja meidän Jumalamme kuullen: Noudattakaa ja tutkikaa kaikkia Herran, Jumalanne, käskyjä, että saisitte pitää omananne tämän hyvän maan ja jättäisitte sen perinnöksi lapsillenne teidän jälkeenne ikuisiksi ajoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Ja sinä, minun poikani Salomo, opi tuntemaan isäsi Jumala ja palvele häntä ehyellä sydämellä ja alttiilla mielellä, sillä Herra tutkii kaikki sydämet ja ymmärtää kaikki ajatukset ja aivoitukset. Jos häntä etsit, niin sinä löydät hänet, mutta jos luovut hänestä, niin hän hylkää sinut iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Katso siis eteesi, sillä Herra on valinnut sinut rakentamaan temppelipyhäkön. Ole luja ja ryhdy työhön.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Senjälkeen Daavid antoi pojallensa Salomolle temppelin eteisen, sen rakennusten, varastohuoneiden, yläsalien, sisähuoneiden ja armoistuimen huoneen mallin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'sekä määräykset kaikesta, mitä hänellä oli mielessään: Herran temppelin esikartanoista ja kaikista kammioista yltympäri, Jumalan temppelin ja pyhien lahjojen aarrekammioista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'kuin myös pappien ja leeviläisten osastoista, kaikesta Herran temppelissä toimitettavasta palveluksesta ja kaikista Herran temppelin palveluksessa tarvittavista kaluista: kullasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'jokaisen palveluksessa tarvittavan kultakalun painosta, kaikista hopeakaluista, jokaisen palveluksessa tarvittavan hopeakalun painosta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'kullasta tehtävien lampunjalkojen ja niiden kunkin lampun kullan painosta, jokaisen lampunjalan ja sen lamppujen painosta; samoin hopeasta tehtävien lampunjalkojen painosta, jokaisen lampunjalan ja sen lamppujen painosta, jokaisen lampunjalan käytön mukaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'edelleen näkyleipäpöytien kullan painosta, kunkin pöydän erikseen, samoin hopeasta tehtävien pöytien hopeasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'haarukkain, maljojen ja kannujen puhtaasta kullasta, samoin kultapikareista, kunkin pikarin painosta, ja hopeapikareista, kunkin pikarin painosta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'myöskin suitsutusalttarin puhdistetun kullan painosta ja vaunujen mallista, kultakerubeista, joitten tuli levittää siipensä ja peittää Herran liitonarkki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, '\"Tämä kaikki on kirjoituksessa, joka on lähtenyt Herran kädestä; hän on opettanut minulle kaikki tämän mallin mukaan tehtävät työt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'Ja Daavid sanoi pojallensa Salomolle: \"Ole luja ja rohkea ja ryhdy työhön, älä pelkää äläkä arkaile, sillä Herra Jumala, minun Jumalani, on oleva sinun kanssasi. Hän ei jätä sinua eikä hylkää sinua, kunnes olet saanut valmiiksi kaikki Herran temppelissä tehtävät työt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'Ja katso, pappien ja leeviläisten osastot ovat valmiit kaikkinaiseen palvelukseen Jumalan temppelissä, ja sinulla on kaikkiin töihin käytettävinäsi niitä, jotka alttiisti ja taidolla tekevät kaikkinaista palvelusta, niin myös päämiehet ja koko kansa kaikkiin tehtäviisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Sitten kuningas Daavid sanoi koko seurakunnalle: \"Minun poikani Salomo, ainoa Jumalan valittu, on nuori ja hento, ja työ on suuri, sillä tämä linna ei ole aiottu ihmiselle, vaan Herralle Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Sentähden minä olen kaikin voimin hankkinut Jumalani temppeliä varten kultaa kultaesineihin, hopeata hopeaesineihin, vaskea vaskiesineihin, rautaa rautaesineihin ja puuta puuesineihin, onykskiviä ja muita jalokiviä, mustankiiltävää ja kirjavaa kiveä, kaikkinaisia kalliita kiviä ja marmorikiveä suuret määrät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Koska minun Jumalani temppeli on minulle rakas, minä vielä luovutan omistamani kullan ja hopean Jumalani temppeliä varten, kaiken lisäksi, minkä olen pyhäkköä varten hankkinut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'kolmetuhatta talenttia kultaa, Oofirin kultaa, ja seitsemäntuhatta talenttia puhdistettua hopeata huoneitten seinien silaamiseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'kultaa kultaesineihin ja hopeata hopeaesineihin ja kaikkinaisiin taitomiesten kätten töihin. Tahtooko kukaan muu tänä päivänä tuoda vapaaehtoisesti, täysin käsin, lahjoja Herralle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Silloin tulivat vapaaehtoisesti perhekunta-päämiehet, Israelin sukukuntien ruhtinaat, tuhannen-ja sadanpäämiehet ja kuninkaan töiden ylivalvojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'Ja he antoivat Jumalan temppelissä tehtäviin töihin viisituhatta talenttia ja kymmenentuhatta dareikkia kultaa, kymmenentuhatta talenttia hopeata, kahdeksantoista tuhatta talenttia vaskea ja satatuhatta talenttia rautaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Ja jolla oli hallussaan jalokiviä, antoi ne Herran temppelin aarteisiin, geersonilaisen Jehielin huostaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Ja kansa iloitsi heidän alttiudestaan, sillä he antoivat ehyellä sydämellä vapaaehtoiset lahjansa Herralle; ja kuningas Daavid oli myös suuresti iloissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Ja Daavid kiitti Herraa koko seurakunnan läsnäollessa; Daavid sanoi: \"Ole kiitetty, Herra, meidän isämme Israelin Jumala, iankaikkisesta iankaikkiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Sinun, Herra, on suuruus ja väkevyys ja loisto ja kunnia ja kirkkaus, sillä sinun on kaikki taivaassa ja maan päällä. Sinun, Herra, on valtakunta, ja sinä olet korotettu kaiken pääksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Rikkaus ja kunnia tulevat sinulta, sinä hallitset kaikki, ja sinun kädessäsi on voima ja väkevyys. Sinun vallassasi on tehdä mikä tahansa suureksi ja väkeväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Me siis kiitämme sinua, meidän Jumalaamme; me ylistämme sinun ihanaa nimeäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Sillä mitä olen minä, ja mitä on minun kansani, kyetäksemme antamaan tällaisia vapaaehtoisia lahjoja? Vaan kaikki tulee sinulta, ja omasta kädestäsi olemme sen sinulle antaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Sillä me olemme muukalaisia ja vieraita sinun edessäsi, niinkuin kaikki meidän isämmekin; niinkuin varjo ovat meidän päivämme maan päällä eikä ole, mihin toivonsa panna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'Herra, meidän Jumalamme, kaikki tämä runsaus, jonka me olemme hankkineet rakentaaksemme temppelin sinulle, sinun pyhälle nimellesi, on sinun kädestäsi, ja sinun on kaikki tyynni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Ja minä tiedän, Jumalani, että sinä tutkit sydämen ja mielistyt vilpittömyyteen. Vilpittömällä sydämellä minä olen antanut kaikki nämä vapaaehtoiset lahjat, ja nyt minä olen ilolla nähnyt, kuinka sinun täällä oleva kansasi on antanut sinulle vapaaehtoiset lahjansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Herra, meidän isäimme Aabrahamin, Iisakin ja Israelin Jumala, säilytä tällaisina ainiaan kansasi sydämen ajatukset ja aivoitukset ja ohjaa heidän sydämensä puoleesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Ja anna minun pojalleni Salomolle ehyt sydän noudattamaan sinun käskyjäsi, todistuksiasi ja säädöksiäsi, toimittamaan kaikki tämä ja rakentamaan tämä linna, jota varten minä olen valmistuksia tehnyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Sitten Daavid sanoi kaikelle seurakunnalle: \"Kiittäkää Herraa, Jumalaanne\". Ja kaikki seurakunta kiitti Herraa, isiensä Jumalaa, ja he kumartuivat maahan ja osoittivat kunniaa Herralle ja kuninkaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'Ja seuraavana päivänä he teurastivat teuraita Herralle ja uhrasivat polttouhreja Herralle: tuhat härkää, tuhat oinasta ja tuhat karitsaa ja niihin kuuluvat juomauhrit sekä teurasuhreja suuren joukon koko Israelin puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'Niin he söivät ja joivat Herran edessä sinä päivänä suuresti iloiten ja tekivät toistamiseen Salomon, Daavidin pojan, kuninkaaksi ja voitelivat hänet Herralle ruhtinaaksi, ja Saadokin papiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'Ja Salomo istui Herran valtaistuimelle kuninkaaksi isänsä Daavidin sijaan, ja hän menestyi; ja koko Israel totteli häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'Samoin kaikki päämiehet, urhot ja myös kaikki kuningas Daavidin pojat kättä lyöden lupautuivat kuningas Salomon alamaisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'Herra teki Salomon ylen suureksi koko Israelin silmissä ja antoi hänelle kuninkuuden loiston, jonka kaltaista ei ollut yhdelläkään kuninkaalla Israelissa ollut ennen häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Daavid, Iisain poika, oli hallinnut koko Israelia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Ja aika, jonka hän hallitsi Israelia, oli neljäkymmentä vuotta; Hebronissa hän hallitsi seitsemän vuotta, ja Jerusalemissa hän hallitsi kolmekymmentä kolme vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'Ja hän kuoli päästyänsä korkeaan ikään, elämästä, rikkaudesta ja kunniasta kyllänsä saaneena, ja hänen poikansa Salomo tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Daavidin vaiheet, sekä aikaisemmat että myöhemmät, ovat kirjoitettuina näkijä Samuelin historiassa, profeetta Naatanin historiassa ja tietäjä Gaadin historiassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'samoin koko hänen hallituksensa ja hänen tekemänsä urotyöt sekä hänen, Israelin ja kaikkien maitten valtakuntain kohtalot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Salomo, Daavidin poika, vahvistui kuninkuudessansa, ja Herra, hänen Jumalansa, oli hänen kanssansa ja teki hänet ylen suureksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'Ja Salomo antoi kutsun koko Israelille, tuhannen-ja sadanpäämiehille, tuomareille ja kaikille ruhtinaille koko Israelissa, perhekunta-päämiehille;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'ja niin Salomo ja koko seurakunta hänen kanssaan menivät uhrikukkulalle, joka oli Gibeonissa, sillä siellä oli Jumalan ilmestysmaja, jonka Herran palvelija Mooses oli tehnyt erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Mutta Jumalan arkin oli Daavid tuonut Kirjat-Jearimista siihen paikkaan, jonka Daavid oli sille valmistanut; sillä hän oli pystyttänyt sille majan Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Ja vaskialttari, jonka Besalel, Uurin poika, Huurin pojanpoika, oli rakentanut, oli siellä Herran asumuksen edessä; Salomo ja seurakunta etsivät häntä siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'Ja Salomo uhrasi siellä Herran edessä ilmestysmajan vaskialttarilla; hän uhrasi sen päällä tuhat polttouhria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Sinä yönä Jumala ilmestyi Salomolle ja sanoi hänelle: \"Ano, mitä tahdot minun sinulle antavan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Salomo vastasi Jumalalle: \"Sinä olet tehnyt suuren laupeuden minun isälleni Daavidille ja tehnyt minut kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'Niin toteutukoon nyt, Herra Jumala, sinun isälleni Daavidille antamasi sana; sillä sinä olet pannut minut hallitsemaan kansaa, jota on paljon niinkuin tomua maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Anna siis minulle viisaus ja taito lähteä ja tulla tämän kansan edellä, sillä kuka voi muuten tätä sinun suurta kansaasi tuomita?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Ja Jumala sanoi Salomolle: \"Koska sinulla on tämä mieli etkä anonut rikkautta, tavaraa ja kunniaa, et vihamiestesi henkeä, etkä myöskään anonut pitkää ikää, vaan anoit itsellesi viisautta ja taitoa tuomitaksesi minun kansaani, jonka kuninkaaksi minä olen sinut tehnyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'niin annetaan sinulle viisaus ja taito; ja lisäksi minä annan sinulle rikkautta, tavaraa ja kunniaa, niin ettei sitä ole ollut niin paljoa kenelläkään kuninkaalla ennen sinua eikä tule olemaan sinun jälkeesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'Käytyään uhrikukkulalla, joka oli Gibeonissa, Salomo palasi ilmestysmajalta Jerusalemiin ja hallitsi Israelia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'Ja Salomo kokosi sotavaunuja ja ratsumiehiä, niin että hänellä oli tuhannet neljätsadat sotavaunut ja kaksitoista tuhatta ratsumiestä. Ne hän sijoitti vaunukaupunkeihin ja kuninkaan luo Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'Ja kuningas toimitti niin, että Jerusalemissa oli hopeata ja kultaa kuin kiviä, ja setripuuta niin paljon kuin metsäviikunapuita Alankomaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'Ja hevoset, mitä Salomolla oli, tuotiin Egyptistä ja Kuvesta; kuninkaan kauppiaat noutivat niitä Kuvesta maksua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'Egyptistä tuodut vaunut maksoivat kuusisataa hopeasekeliä ja hevonen sata viisikymmentä. Samoin tuotiin niitä heidän välityksellään kaikille heettiläisten ja aramilaisten kuninkaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Ja Salomo käski ryhtyä rakentamaan temppeliä Herran nimelle ja kuninkaallista linnaa itsellensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'Ja Salomo määräsi seitsemänkymmentä tuhatta miestä taakankantajiksi ja kahdeksankymmentä tuhatta miestä kivenhakkaajiksi vuoristoon ja niille kolmetuhatta kuusisataa työnjohtajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Sitten Salomo lähetti Huuramille, Tyyron kuninkaalle, sanan: \"Tee minulle sama, minkä teit isälleni Daavidille, jolle lähetit setripuita, että hän rakentaisi itsellensä linnan asuaksensa siinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Katso, minä rakennan temppelin Herran, Jumalani, nimelle, pyhittääkseni sen hänelle, että siinä poltettaisiin hyvänhajuista suitsutusta hänen edessänsä, pidettäisiin aina esillä näkyleipiä ja uhrattaisiin polttouhreja aamuin ja illoin, sapatteina, uudenkuun päivinä ja Herran, meidän Jumalamme, juhlina; tämä on Israelin ikuinen velvollisuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Ja temppeli, jonka minä rakennan, on oleva suuri; sillä meidän Jumalamme on suurin kaikista jumalista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Kuka kykenisi rakentamaan hänelle huoneen? Taivaisiin ja taivasten taivaisiin hän ei mahdu. Mikä siis olen minä rakentamaan hänelle temppeliä muuta varten kuin uhratakseni hänen edessänsä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Niin lähetä nyt minulle mies, joka on taitava tekemään kulta-,hopea-,vaski-ja rautatöitä, niin myös töitä purppuranpunaisista, helakanpunaisista ja punasinisistä langoista, ja joka osaa veistää veistoksia, työskentelemään yhdessä niiden taitajien kanssa, joita minulla on Juudassa ja Jerusalemissa ja jotka minun isäni Daavid on hankkinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Ja lähetä minulle setripuita, kypressipuita ja santelipuita Libanonilta, sillä minä tiedän, että sinun palvelijasi osaavat hakata Libanonin puita; ja katso, minun palvelijani olkoot sinun palvelijaisi kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Minulle on hankittava paljon puuta, sillä temppeli, jonka minä rakennan, on oleva suuri ja ihmeellinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'Ja katso, minä annan kirvesmiehille, puitten hakkaajille, kaksikymmentä tuhatta koor-mittaa nisuja, sinun palvelijaisi ravinnoksi, ja kaksikymmentä tuhatta koor-mittaa ohria, kaksikymmentä tuhatta bat-mittaa viiniä ja kaksikymmentä tuhatta bat-mittaa öljyä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Huuram, Tyyron kuningas, vastasi kirjeellä, jonka hän lähetti Salomolle: \"Sentähden, että Herra rakastaa kansaansa, on hän asettanut sinut heidän kuninkaakseen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Ja Huuram sanoi vielä: \"Kiitetty olkoon Herra, Israelin Jumala, joka on tehnyt taivaan ja maan, siitä että hän on antanut kuningas Daavidille viisaan pojan, jolla on älyä ja ymmärrystä rakentaa temppeli Herralle ja kuninkaallinen linna itsellensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Ja nyt minä lähetän taitavan, ymmärtäväisen miehen, Huuram-Aabin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'joka on daanilaisen vaimon poika ja jonka isä on tyyrolainen. Hän osaa tehdä kulta-ja hopea-,vaski-ja rauta-,kivi-ja puutöitä, niin myös töitä purppuranpunaisista ja punasinisistä langoista, valkoisista pellavalangoista ja helakanpunaisista langoista. Hän osaa veistää veistoksia ja sommitella kaikkinaisia taideteoksia, joita hänen tehtäväkseen annetaan, yhdessä sinun taitomiestesi ja herrani, sinun isäsi Daavidin, taitomiesten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Lähettäköön siis herrani palvelijoillensa nisut, ohrat, öljyn ja viinin, niinkuin on sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Silloin me hakkaamme puita Libanonilta niin paljon, kuin sinä tarvitset, ja me kuljetamme ne lautoissa meritse sinulle Jaafoon. Toimita sinä ne sitten ylös Jerusalemiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Ja Salomo luetti kaikki muukalaiset miehet Israelin maassa, senjälkeen kuin hänen isänsä Daavid oli heidät luettanut. Ja heitä huomattiin olevan sata viisikymmentäkolme tuhatta kuusisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'Näistä hän teki seitsemänkymmentä tuhatta taakankantajiksi, kahdeksankymmentä tuhatta kivenhakkaajiksi vuoristoon ja kolmetuhatta kuusisataa työnjohtajiksi, joiden oli pidettävä väki työssä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Sitten Salomo alkoi rakentaa Herran temppeliä Jerusalemiin, Moorian vuorelle, jossa Herra oli ilmestynyt hänen isällensä Daavidille, siihen paikkaan, jonka Daavid oli valmistanut, jebusilaisen Ornanin puimatantereelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Hän alkoi rakentaa toisen kuun toisena päivänä, neljäntenä hallitusvuotenansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Tällaisen perustuksen Salomo laski rakennettavalle Jumalan temppelille: pituus oli, vanhan mitan mukaan, kuusikymmentä kyynärää, leveys kaksikymmentä kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Eteinen, temppelin itäpäässä, oli yhtä pitkä kuin temppeli leveä, kahtakymmentä kyynärää, ja sen korkeus oli kaksikymmentä kyynärää; ja hän päällysti sen sisältä puhtaalla kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'Suuren huoneen hän laudoitti sisältä kypressipuulla, jonka hän silasi parhaalla kullalla ja johon hän laittoi palmuja ja vitjoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Ja hän koristi huoneen kalliilla kivillä. Ja kulta oli Parvaimin kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Ja hän silasi huoneen, palkit, kynnykset, seinät ja ovet, kullalla ja kaiverrutti kerubeja seiniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Ja hän teki kaikkeinpyhimmän huoneen. Se oli yhtä pitkä kuin temppeli leveä, kahtakymmentä kyynärää, ja myös kahtakymmentä kyynärää leveä. Ja hän silasi sen parhaalla kullalla, joka painoi kuusisataa talenttia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Ja kultanaulojen paino oli viisikymmentä sekeliä. Myöskin yläsalit hän silasi kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Kaikkein pyhimpään huoneeseen hän teki kaksi kerubia, taidollisesti tehtyä, ja päällysti ne kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'Kerubien siipien pituus oli yhteensä kaksikymmentä kyynärää. Toisen kerubin toinen siipi oli viittä kyynärää pitkä ja kosketti huoneen toista seinää, ja sen toinen siipi oli viittä kyynärää pitkä ja ulottui toisen kerubin siipeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Ja toisen kerubin toinen siipi oli viittä kyynärää pitkä ja ulottui huoneen toiseen seinään, ja sen toinen siipi oli viittä kyynärää pitkä ja oli kiinni toisen kerubin siivessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Näin nämä kerubit levittivät siipensä kahtakymmentä kyynärää laajalti; ja ne seisoivat jaloillaan, kasvot käännettyinä huoneeseen päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Ja hän teki esiripun punasinisistä, purppuranpunaisista ja helakanpunaisista langoista ja valkoisista pellavalangoista ja laittoi siihen kerubeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Ja hän teki temppelin eteen kaksi pylvästä, kolmenkymmenen viiden kyynärän korkuista; ja pylväänpää, joka oli niiden päässä, oli viittä kyynärää korkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Ja hän teki vitjoja kaikkeinpyhimpään, ja hän pani niitä pylväitten päähän; ja hän teki sata granaattiomenaa ja asetti ne vitjoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'Ja hän pystytti pylväät temppelin eteen, toisen oikealle puolelle ja toisen vasemmalle puolelle: oikeanpuoliselle hän antoi nimen Jaakin ja vasemmanpuoliselle nimen Booas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Hän teki alttarin vaskesta, kahtakymmentä kyynärää pitkän, kahtakymmentä kyynärää leveän ja kymmentä kyynärää korkean.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Hän teki myös meren, valetun, kymmentä kyynärää leveän reunasta reunaan, ympärinsä pyöreän, ja viittä kyynärää korkean; ja kolmenkymmenen kyynärän pituinen mittanuora ulottui sen ympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'Ja sen alaosassa oli yltympäri raavaankuvia, jotka kulkivat sen ympäri; ne ympäröivät merta yltympäri, kymmenen kullakin kyynärällä. Raavaita oli kahdessa rivissä, valettuina meren kanssa yhteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Ja se seisoi kahdentoista raavaan varassa, joista kolme oli käännettynä pohjoiseen, kolme länteen, kolme etelään ja kolme itään päin; meri oli niiden yläpuolella, niiden varassa, ja kaikkien niiden takapuolet olivat sisään päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'Se oli kämmenen paksuinen, ja sen reuna oli maljan reunan kaltainen, puhjenneen liljan muotoinen. Siihen mahtui, se veti kolmetuhatta bat-mittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Hän teki myös kymmenen allasta ja asetti viisi oikealle puolelle ja viisi vasemmalle puolelle pesemistä varten; sillä niissä huuhdottiin se, mikä kuului polttouhriin. Mutta meri oli pappien peseytymistä varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Hän teki myös kymmenen kultaista lampunjalkaa, niinkuin niistä oli säädetty, ja pani ne temppelisaliin, viisi oikealle puolelle ja viisi vasemmalle puolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Hän teki myös kymmenen pöytää ja asetti ne temppelisaliin, viisi oikealle puolelle ja viisi vasemmalle puolelle. Hän teki myös sata kultamaljaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Ja hän teki pappien esipihan ja suuren esikartanon sekä esikartanon ovet; ja ovet hän päällysti vaskella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'Ja meren hän asetti oikealle sivulle, kaakkoa kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Huuram teki myös kattilat, lapiot ja maljat. Ja niin Huuram sai suoritetuksi työn, mikä hänen oli tehtävä kuningas Salomolle Jumalan temppeliin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'kaksi pylvästä ja kaksi palloa, pylväänpäätä, pylväiden päähän, ja kaksi ristikkokoristetta peittämään kahta pallonmuotoista pylväänpäätä, jotka olivat pylväitten päässä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'ja neljäsataa granaattiomenaa kahteen ristikkokoristeeseen, kaksi riviä granaattiomenia kumpaankin ristikkokoristeeseen, peittämään kahta pallonmuotoista pylväänpäätä, jotka olivat pylväitten päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Ja hän teki telineet ja teki altaat telineitten päälle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Ja yhden meren ja kaksitoista raavasta sen alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Ja kattilat, lapiot ja haarukat ynnä kaikki niihin kuuluvat kalut Huuram-Aabiv teki kuningas Salomolle Herran temppeliin kiilloitetusta vaskesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Jordanin lakeudella kuningas ne valatti savimuotteihin, Sukkotin ja Seredan välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'Ja Salomo teetti kaikkia näitä kaluja ylen paljon, sillä vasken painoa ei määrätty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Salomo teetti myös kaikki kalut, joita tuli olla Herran temppelissä: kulta-alttarin, pöydät, joilla näkyleivät olivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'lampunjalat lamppuineen, jotka oli sytytettävä säädetyllä tavalla kaikkeinpyhimmän eteen, puhtaasta kullasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'kultaisine kukkalehtineen, lamppuineen ja lamppusaksineen-puhtainta kultaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'veitset, maljat, kupit ja hiilipannut puhtaasta kullasta; ja temppelin oviaukkojen sisemmät ovet, jotka veivät kaikkeinpyhimpään, sekä ne temppelin ovet, jotka veivät temppelisaliin, kullasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Kun kaikki työ, minkä Salomo teetti Herran temppeliin, oli valmis, vei Salomo sinne isänsä Daavidin pyhät lahjat. Hopean, kullan ja kaikki kalut hän pani Jumalan temppelin aarrekammioihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Sitten Salomo kokosi Israelin vanhimmat ja kaikki sukukuntien johtomiehet, israelilaisten perhekunta-päämiehet, Jerusalemiin, tuomaan Herran liitonarkkia Daavidin kaupungista, se on Siionista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'Niin kokoontuivat kuninkaan luo kaikki Israelin miehet juhlapäivänä, joka on seitsemännessä kuussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'Ja kun kaikki Israelin vanhimmat olivat tulleet saapuville, nostivat leeviläiset arkin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'ja he veivät arkin ja ilmestysmajan sinne, sekä kaiken pyhän kaluston, joka oli majassa; leeviläiset papit veivät ne sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Ja kuningas Salomo seisoi arkin edessä ynnä koko Israelin kansa, joka oli kokoontunut hänen luoksensa; ja he uhrasivat lampaita ja raavaita niin paljon, että niitä ei voitu luetella eikä laskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Ja papit toivat Herran liitonarkin paikoilleen temppelin kuoriin, kaikkeinpyhimpään, kerubien siipien alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Sillä kerubit levittivät siipensä sen paikan ylitse, missä arkki oli, ja niin kerubit peittivät ylhäältä päin arkin ja sen korennot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'Ja korennot olivat niin pitkät, että niiden arkista ulkonevat päät voi nähdä kaikkeinpyhimmän edustalta, mutta ulkoa niitä ei voinut nähdä. Ja ne jäivät sinne tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Arkissa ei ollut muuta kuin ne kaksi taulua, jotka Mooses oli pannut sinne Hoorebilla, kun Herra oli tehnyt liiton israelilaisten kanssa, heidän lähdettyänsä Egyptistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'Kun papit lähtivät pyhäköstä-sillä kaikki siellä olevat papit olivat pyhittäneet itsensä, osastoihin katsomatta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'ja kaikki leeviläiset veisaajat, Aasaf, Heeman ja Jedutun poikinensa ja veljinensä, seisoivat hienoihin pellavavaatteisiin puettuina kymbaaleineen, harppuineen ja kanteleineen itään päin alttarista, ja heidän kanssaan sata kaksikymmentä pappia, jotka puhalsivat torviin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'ja puhaltajien ja veisaajien oli yhdyttävä yhtaikaa ja yhteen ääneen ylistämään ja kiittämään Herraa-ja kun torvet, kymbaalit ja muut soittokoneet soivat ja viritettiin Herran ylistys: \"Sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti\", silloin pilvi täytti huoneen, Herran temppelin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'niin että papit eivät voineet astua toimittamaan virkaansa pilven tähden; sillä Herran kirkkaus täytti Jumalan temppelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Silloin Salomo sanoi: \"Herra on sanonut tahtovansa asua pimeässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'Mutta minä olen rakentanut huoneen sinulle asunnoksi, asuinsijan, asuaksesi siinä iäti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'Sitten kuningas käänsi kasvonsa ja siunasi koko Israelin seurakunnan; ja koko Israelin seurakunta seisoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'Hän sanoi: \"Kiitetty olkoon Herra, Israelin Jumala, joka kädellänsä on täyttänyt sen, mitä hän suullansa puhui minun isälleni Daavidille, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, '\'Siitä päivästä saakka, jona minä vein kansani Egyptistä, en minä ole mistään Israelin sukukunnasta valinnut yhtään kaupunkia, että siihen rakennettaisiin temppeli, missä minun nimeni asuisi, enkä myöskään ole valinnut ketään olemaan kansani Israelin ruhtinaana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Mutta Jerusalemin minä olen valinnut nimeni asuinsijaksi, ja Daavidin minä olen valinnut vallitsemaan kansaani Israelia.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Ja minun isäni Daavid aikoi rakentaa temppelin Herran, Israelin Jumalan, nimelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Mutta Herra sanoi minun isälleni Daavidille: \'Kun sinä aiot rakentaa temppelin minun nimelleni, niin tosin teet siinä hyvin, että sitä aiot;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'kuitenkaan et sinä ole sitä temppeliä rakentava, vaan sinun poikasi, joka lähtee sinun kupeistasi, hän on rakentava temppelin minun nimelleni\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'Ja Herra on täyttänyt sanansa, minkä hän puhui: minä olen noussut isäni Daavidin sijalle ja istun Israelin valtaistuimella, niinkuin Herra puhui, ja minä olen rakentanut temppelin Herran, Israelin Jumalan, nimelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Ja minä olen sijoittanut siihen arkin, jossa on se Herran liitto, minkä hän teki israelilaisten kanssa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Sitten hän astui Herran alttarin eteen koko Israelin seurakunnan nähden ja ojensi kätensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Salomo oli näet teettänyt lavan vaskesta, viittä kyynärää pitkän, viittä kyynärää leveän ja kolmea kyynärää korkean, ja asettanut sen esikartanon keskelle. Sille hän nousi, polvistui koko Israelin seurakunnan nähden, ojensi kätensä taivasta kohti');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'ja sanoi: \"Herra, Israelin Jumala, ei ole sinun vertaistasi Jumalaa, ei taivaassa eikä maan päällä, sinun, joka pidät liiton ja säilytät laupeuden palvelijoitasi kohtaan, jotka vaeltavat sinun edessäsi kaikesta sydämestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Sinä olet pitänyt, mitä puhuit palvelijallesi Daavidille, minun isälleni. Minkä sinä suullasi puhuit, sen sinä kädelläsi täytit, niinkuin nyt on tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Niin pidä nytkin, Herra, Israelin Jumala, mitä puhuit palvelijallesi Daavidille, minun isälleni, sanoen: \'Aina on mies sinun suvustasi oleva minun edessäni, istumassa Israelin valtaistuimella, jos vain sinun poikasi pitävät vaarin teistänsä, niin että he vaeltavat minun lakini mukaan, niinkuin sinä olet minun edessäni vaeltanut\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Niin toteutukoon nyt, Herra, Israelin Jumala, sinun sanasi, jonka puhuit palvelijallesi Daavidille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Mutta asuuko todella Jumala maan päällä ihmisten seassa? Katso, taivaisiin ja taivasten taivaisiin sinä et mahdu; kuinka sitten tähän temppeliin, jonka minä olen rakentanut!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Käänny kuitenkin palvelijasi rukouksen ja anomisen puoleen, Herra, minun Jumalani, niin että kuulet huudon ja rukouksen, jonka palvelijasi sinun edessäsi rukoilee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'ja että silmäsi ovat päivät ja yöt avoinna tätä temppeliä kohti, tätä paikkaa kohti, johon sinä olet sanonut asettavasi nimesi, niin että kuulet rukouksen, jonka palvelijasi tähän paikkaan päin kääntyneenä rukoilee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Kuule palvelijasi ja kansasi Israelin rukoukset, jotka he rukoilevat tähän paikkaan päin kääntyneinä; kuule asuinpaikastasi, taivaasta, ja kun kuulet, niin anna anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Jos joku rikkoo lähimmäistänsä vastaan ja hänet pannaan valalle ja vannotetaan, ja jos hän tulee ja vannoo sinun alttarisi edessä tässä temppelissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'niin kuule taivaasta ja auta palvelijasi oikeuteensa; tee niin, että kostat syylliselle ja annat hänen tekojensa tulla hänen päänsä päälle, mutta julistat syyttömän syyttömäksi ja annat hänelle hänen vanhurskautensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Jos vihollinen voittaa sinun kansasi Israelin, sentähden että he ovat tehneet syntiä sinua vastaan, mutta he kääntyvät ja kiittävät sinun nimeäsi, rukoilevat ja anovat armoa sinun kasvojesi edessä tässä temppelissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'niin kuule taivaasta ja anna anteeksi kansasi Israelin synti ja tuo heidät takaisin tähän maahan, jonka olet antanut heille ja heidän isillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Jos taivas suljetaan, niin ettei tule sadetta, koska he ovat tehneet syntiä sinua vastaan, mutta he rukoilevat kääntyneinä tähän paikkaan päin ja ylistävät sinun nimeäsi ja kääntyvät synnistänsä, koska sinä nöyryytät heitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'niin kuule taivaasta ja anna anteeksi palvelijaisi ja kansasi Israelin synti-sillä sinä osoitat heille hyvän tien, jota heidän on vaeltaminen-ja suo sade maallesi, jonka olet antanut kansallesi perintöosaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Jos maahan tulee nälänhätä, rutto, jos tulee nokitähkä ja viljanruoste, jos tulevat heinäsirkat ja tuhosirkat, jos sen viholliset ahdistavat sitä maassa, jossa sen portit ovat, jos tulee mikä tahansa vitsaus tai vaiva,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'ja jos silloin joku ihminen, kuka hyvänsä, tai koko sinun kansasi Israel, rukoilee ja anoo armoa, kun he kukin tuntevat vitsauksen ja tuskan, joka on kohdannut heitä, ja ojentavat kätensä tähän temppeliin päin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'niin kuule silloin taivaasta, asuinpaikastasi, ja anna anteeksi ja anna jokaiselle aivan hänen tekojensa mukaan, koska sinä tunnet hänen sydämensä-sillä sinä yksin tunnet ihmislasten sydämet-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'että he pelkäisivät sinua ja vaeltaisivat sinun teitäsi, niin kauan kuin he elävät tässä maassa, jonka sinä olet meidän isillemme antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Myös jos joku muukalainen, joka ei ole sinun kansaasi Israelia, tulee kaukaisesta maasta sinun suuren nimesi, väkevän kätesi ja ojennetun käsivartesi tähden-jos hän tulee ja rukoilee kääntyneenä tähän temppeliin päin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'niin kuule taivaasta, asuinpaikastasi, häntä ja tee kaikki, mitä muukalainen sinulta rukoilee, että kaikki maan kansat tuntisivat sinun nimesi ja pelkäisivät sinua, samoin kuin sinun kansasi Israel, ja tulisivat tietämään, että sinä olet ottanut nimiisi tämän temppelin, jonka minä olen rakentanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Jos sinun kansasi lähtee sotaan vihollisiansa vastaan sitä tietä, jota sinä heidät lähetät, ja he rukoilevat sinua kääntyneinä tähän kaupunkiin päin, jonka sinä olet valinnut, ja tähän temppeliin päin, jonka minä olen sinun nimellesi rakentanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'niin kuule taivaasta heidän rukouksensa ja anomisensa ja hanki heille oikeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Jos he tekevät syntiä sinua vastaan-sillä ei ole ihmistä, joka ei syntiä tee-ja sinä vihastut heihin ja annat heidät vihollisen valtaan, niin että heidän vangitsijansa vievät heidät vangeiksi kaukaiseen tai läheiseen maahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'mutta jos he sitten menevät itseensä siinä maassa, johon heidät on viety vangeiksi, kääntyvät ja anovat sinulta armoa vankeutensa maassa, sanoen: \'Me olemme tehneet syntiä, tehneet väärin ja olleet jumalattomat\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'ja palajavat sinun tykösi kaikesta sydämestään ja kaikesta sielustaan vankeutensa maassa, johon heidät on vangeiksi viety, ja rukoilevat kääntyneinä tähän maahan päin, jonka sinä olet heidän isillensä antanut, tähän kaupunkiin päin, jonka sinä olet valinnut, ja tähän temppeliin päin, jonka minä olen sinun nimellesi rakentanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'niin kuule taivaasta, asuinpaikastasi, heidän rukouksensa ja anomisensa, hanki heille oikeus ja anna anteeksi kansallesi, mitä he ovat rikkoneet sinua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Olkoot siis, minun Jumalani, sinun silmäsi avoinna, ja tarkatkoot sinun korvasi rukouksia tässä paikassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Ja nyt: Nouse, Herra Jumala, tule leposijaasi, sinä ja sinun voimasi arkki. Sinun pappisi, Herra Jumala, olkoot puetut autuuteen, ja sinun hurskaasi riemuitkoot siitä, mikä hyvä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'Herra Jumala, älä hylkää voideltuasi; muista armolupauksiasi, jotka annoit Daavidille, palvelijallesi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'Kun Salomo oli lakannut rukoilemasta, tuli taivaasta tuli ja kulutti polttouhrin ja teurasuhrit, ja Herran kirkkaus täytti temppelin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'niin että papit eivät voineet mennä Herran temppeliin; sillä Herran kirkkaus täytti Herran temppelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'Ja kun kaikki israelilaiset näkivät tulen tulevan alas ja näkivät temppelin päällä Herran kirkkauden, polvistuivat he kivillä lasketulla pihalla kasvoillensa maahan ja rukoilivat ja kiittivät Herraa siitä, että hän on hyvä, että hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'Sitten kuningas ja kaikki kansa uhrasivat teurasuhrin Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Ja kuningas Salomo uhrasi teurasuhrina kaksikymmentäkaksi tuhatta raavasta ja satakaksikymmentä tuhatta lammasta. Näin he, kuningas ja koko kansa, vihkivät Herran temppelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Papit seisoivat kukin virkatoimessaan. Ja leeviläiset, käsissään Herran soittimet, jotka kuningas Daavid oli teettänyt, seisoivat kiittämässä Herraa Daavidin ylistysvirsillä siitä, että hänen armonsa pysyy iankaikkisesti. Ja heitä vastapäätä papit soittivat torvia, kaiken Israelin seisoessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Ja Salomo pyhitti Herran temppelin edessä olevan esipihan keskiosan, sillä hänen oli siellä uhrattava polttouhri ja yhteysuhrin rasvat, koska polttouhri, ruokauhri ja rasvat eivät mahtuneet vaskialttarille, jonka Salomo oli teettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'Näin Salomo siihen aikaan vietti juhlaa seitsemän päivää, ja koko Israel hänen kanssansa. Se oli sangen suuri kokous, johon kokoonnuttiin aina sieltä, mistä mennään Hamatiin, ja aina Egyptin purolta asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'Kahdeksantena päivänä heillä oli juhlakokous. Sillä alttarin vihkimistä he viettivät seitsemän päivää ja juhlaa seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'Mutta seitsemännen kuun kahdentenakymmenentenä kolmantena päivänä hän päästi kansan menemään majoillensa. He iloitsivat ja olivat hyvillä mielin siitä hyvästä, minkä Herra oli tehnyt Daavidille ja Salomolle ja kansallensa Israelille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Kun Salomo oli saanut valmiiksi Herran temppelin ja kuninkaan linnan ja menestynyt kaikessa, mitä oli ajatellut tehdä Herran temppelissä ja omassa linnassaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'ilmestyi Herra Salomolle yöllä ja sanoi hänelle: \"Minä olen kuullut sinun rukouksesi ja valinnut tämän paikan uhripaikakseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Jos minä suljen taivaan, niin ettei tule sadetta, jos minä käsken heinäsirkkain syödä maan tahi jos minä lähetän ruton kansaani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'mutta minun kansani, joka on otettu minun nimiini, nöyrtyy, ja he rukoilevat ja etsivät minun kasvojani ja palajavat pahoilta teiltänsä, niin minä kuulen taivaasta ja annan anteeksi heidän syntinsä ja teen heidän maansa jälleen terveeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Nyt minun silmäni ovat avoinna, ja minun korvani tarkkaavat rukouksia tässä paikassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Ja nyt minä olen valinnut ja pyhittänyt tämän temppelin, että minun nimeni olisi siinä iäti; ja minun silmäni ja sydämeni tulevat aina olemaan siinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Ja jos sinä vaellat minun edessäni, niinkuin sinun isäsi Daavid vaelsi, ja teet kaiken, mitä minä olen käskenyt sinun tehdä, ja noudatat minun käskyjäni ja oikeuksiani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'niin minä pidän pystyssä sinun kuninkaallisen valtaistuimesi, niinkuin minä lupasin sinun isällesi Daavidille sanoen: \'Aina on mies sinun suvustasi hallitseva Israelia\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Mutta jos te käännytte pois ja hylkäätte minun käskyni ja säädökseni, jotka minä olen teille antanut, ja menette ja palvelette muita jumalia ja kumarratte niitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'niin minä kiskaisen sellaiset irti maastani, jonka minä olen heille antanut; ja tämän temppelin, jonka minä olen nimelleni pyhittänyt, minä heitän pois kasvojeni edestä, ja minä teen sen sananparreksi ja pistopuheeksi kaikille kansoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Ja tämän temppelin tähden, joka ennen oli korkein, on jokainen ohikulkija tyrmistyvä. Ja kun hän kysyy: \'Miksi on Herra näin tehnyt tälle maalle ja tälle temppelille?\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'niin vastataan: \'Siksi, että he hylkäsivät Herran, isiensä Jumalan, joka oli vienyt heidät pois Egyptin maasta, ja liittyivät muihin jumaliin, kumarsivat niitä ja palvelivat niitä; sentähden hän on antanut kaiken tämän pahan heitä kohdata\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'Niiden kahdenkymmenen vuoden kuluttua, joina Salomo oli rakentanut Herran temppelin ja oman linnansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'linnoitti Salomo ne kaupungit, jotka Huuram oli antanut hänelle, ja hän asetti israelilaisia niihin asumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Ja Salomo meni Hamat-Soobaan ja valloitti sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Hän linnoitti myös Tadmorin erämaassa ja kaikki varastokaupungit, jotka hän oli rakentanut Hamatiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Vielä hän linnoitti Ylä-Beet-Hooronin ja Ala-Beet-Hooronin muureilla, porteilla ja salvoilla varustetuiksi kaupungeiksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'samoin Baalatin ja kaikki varastokaupungit, jotka hänellä oli, ja kaikki vaunukaupungit ja ratsumiesten kaupungit ja kaikki muut paikat, mitkä hän tahtoi linnoittaa Jerusalemissa ja Libanonilla ja kaikessa hallitsemassaan maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Kaiken kansan, mitä oli jäänyt jäljelle heettiläisistä, amorilaisista, perissiläisistä, hivviläisistä ja jebusilaisista, kaikki, jotka eivät olleet israelilaisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'ne niiden jälkeläiset, jotka vielä olivat jäljellä maassa ja joita israelilaiset eivät olleet tuhonneet, ne Salomo saattoi työveron alaisiksi, aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Mutta israelilaisista Salomo ei tehnyt ketään työorjakseen, vaan heitä oli sotilaina, hänen vaunusoturiensa päällikköinä ja hänen sotavaunujensa ja ratsumiestensä päällikköinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Maaherrojen virkamiehiä oli Salomolla kaksisataa viisikymmentä, jotka vallitsivat väkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Ja Salomo toi faraon tyttären Daavidin kaupungista linnaan, jonka hän oli tälle rakentanut; sillä hän sanoi: \"Älköön nainen asuko Daavidin, Israelin kuninkaan, linnassa; sillä se on pyhäkkö, koska Herran arkki on tullut sinne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Siihen aikaan Salomo uhrasi polttouhreja Herralle Herran alttarilla, jonka hän oli rakentanut eteisen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Hän uhrasi kunakin päivänä sen päivän uhrit Mooseksen käskyn mukaan, sapatteina ja uudenkuun päivinä sekä juhlina kolme kertaa vuodessa: happamattoman leivän juhlana, viikkojuhlana ja lehtimajanjuhlana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'Ja hän asetti, niinkuin hänen isänsä Daavid oli säätänyt, pappien osastot toimittamaan virkaansa ja leeviläiset suorittamaan tehtäviänsä, veisaamaan ylistysvirsiä ja palvelemaan pappeja, kunakin päivänä sen päivän tehtävissä, sekä ovenvartijat osastoittain joka ovelle, sillä niin oli Jumalan mies Daavid käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'Eikä missään poikettu kuninkaan käskyistä, mitä tuli pappeihin, leeviläisiin ja aarrekammioihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'Ja niin suoritettiin Salomon kaikki työt, Herran temppelin perustamispäivään asti, sekä siihen saakka, kunnes se valmistui. Niin oli Herran temppeli valmis.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Siihen aikaan Salomo meni Esjon-Geberiin ja Elatiin, joka on meren rannalla Edomin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'Ja Huuram lähetti palvelijansa tuomaan hänelle laivoja. Palvelijat olivat meritaitoisia ja menivät yhdessä Salomon palvelijain kanssa Oofiriin ja noutivat sieltä kultaa neljäsataa viisikymmentä talenttia ja toivat sen kuningas Salomolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Kun Saban kuningatar kuuli Salomon maineen, tuli hän Jerusalemiin koettelemaan Salomoa arvoituksilla. Hän tuli sangen suuren seurueen kanssa, mukanaan kameleja, jotka kantoivat hajuaineita, kultaa ylen paljon ja kalliita kiviä. Ja kun hän tuli Salomon luo, puhui hän tälle kaikki, mitä hänellä oli mielessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Mutta Salomo selitti hänelle kaikki hänen kysymyksensä; Salomolle ei mikään jäänyt ongelmaksi, jota hän ei olisi hänelle selittänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Kun Saban kuningatar näki kaiken Salomon viisauden, linnan, jonka hän oli rakentanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'ruuat hänen pöydällänsä, kuinka hänen palvelijansa asuivat ja hänen palvelusväkensä palveli ja kuinka he olivat puetut, ja näki hänen juomanlaskijansa ja kuinka he olivat puetut, ja hänen yläsalinsa, josta hän nousi Herran temppeliin, meni hän miltei hengettömäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'Sitten hän sanoi kuninkaalle: \"Totta oli se puhe, jonka minä kotimaahani sinusta ja sinun viisaudestasi kuulin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Minä en uskonut, mitä sanottiin, ennenkuin itse tulin ja sain omin silmin nähdä; ja katso, ei puoltakaan sinun suuresta viisaudestasi oltu minulle kerrottu. Sinä olet paljon suurempi, kuin minä olin kuullut huhuttavan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Onnellisia ovat sinun miehesi, onnellisia nämä palvelijasi, jotka aina saavat olla sinun edessäsi ja kuulla sinun viisauttasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Kiitetty olkoon Herra, sinun Jumalasi, joka sinuun on niin mielistynyt, että on asettanut sinut valtaistuimellensa olemaan kuninkaana Herran, sinun Jumalasi, kunniaksi. Sentähden, että sinun Jumalasi rakastaa Israelia ja tahtoo pitää sen pystyssä ainiaan, on hän antanut sinut heille kuninkaaksi, tekemään sitä, mikä oikeus ja vanhurskaus on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'Ja hän antoi kuninkaalle sata kaksikymmentä talenttia kultaa, sangen paljon hajuaineita ja kalliita kiviä. Ei milloinkaan ole ollut moisia hajuaineita kuin ne, jotka Saban kuningatar antoi kuningas Salomolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Huuramin palvelijat ja Salomon palvelijat, jotka toivat kultaa Oofirista, toivat myöskin santelipuuta ja kalliita kiviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'Ja kuningas teetti santelipuusta portaat Herran temppeliin ja kuninkaan palatsiin ja kanteleita ja harppuja laulajille. Moisia ei oltu ennen nähty Juudan maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Kuningas Salomo taas antoi Saban kuningattarelle kaikki, mitä tämä halusi ja pyysi, antoi vielä enemmän, kuin mitä tämä oli tuonut kuninkaalle. Sitten hän lähti paluumatkalle ja meni palvelijoineen omaan maahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Kullan paino, mikä yhtenä vuotena tuli Salomolle, oli kuusisataa kuusikymmentä kuusi talenttia kultaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'paitsi mitä kauppamiehet ja kaupustelijat toivat. Sen lisäksi kaikki Arabian kuninkaat ja maan käskynhaltijat toivat Salomolle kultaa ja hopeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Ja kuningas Salomo teetti kaksisataa suurta kilpeä pakotetusta kullasta ja käytti jokaiseen kilpeen kuusisataa sekeliä pakotettua kultaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'samoin kolmesataa pienempää kilpeä pakotetusta kullasta, ja käytti jokaiseen kilpeen kolmesataa sekeliä kultaa. Ja kuningas asetti ne Libanoninmetsä-taloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Vielä kuningas teetti suuren norsunluisen valtaistuimen ja päällysti sen puhtaalla kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Valtaistuimessa oli kuusi porrasta ja astinlauta, kullalla kiinnitettyinä valtaistuimeen. Istuimen kummallakin puolella oli käsinoja, ja kaksi leijonaa seisoi käsinojan vieressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Ja kaksitoista leijonaa seisoi siinä kuudella portaalla, kummallakin puolella. Senkaltaista ei ole tehty missään muussa valtakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Ja kaikki kuningas Salomon juoma-astiat olivat kultaa, ja kaikki Libanoninmetsä-talon astiat olivat puhdasta kultaa. Hopeata ei Salomon päivinä pidetty minkään arvoisena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Kuninkaalla oli näet laivoja, jotka kulkivat Tarsiiseen Huuramin palvelijain kanssa; kerran kolmessa vuodessa Tarsiin-laivat tulivat ja toivat kultaa ja hopeata, norsunluuta, apinoita ja riikinkukkoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'Ja kuningas Salomo oli kaikkia maan kuninkaita suurempi rikkaudessa ja viisaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Ja kaikki maan kuninkaat pyrkivät näkemään Salomoa kuullaksensa hänen viisauttaan, jonka Jumala oli antanut hänen sydämeensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'Ja he toivat kukin lahjansa: hopea-ja kultakaluja, vaatteita, aseita, hajuaineita, hevosia ja muuleja, joka vuosi vuoden tarpeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'Salomolla oli neljätuhatta hevosvaljakkoa vaunuineen ja kaksitoista tuhatta ratsumiestä; ne hän sijoitti vaunukaupunkeihin ja kuninkaan luo Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'Ja hän vallitsi kaikkia kuninkaita Eufrat-virrasta aina filistealaisten maahan ja Egyptin rajaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'Ja kuningas toimitti niin, että Jerusalemissa oli hopeata kuin kiviä, ja setripuuta niin paljon kuin metsäviikunapuita Alankomaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Ja hevosia tuotiin Salomolle Egyptistä ja kaikista muista maista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'Mitä muuta Salomosta on kerrottavaa, hänen sekä aikaisemmista että myöhemmistä vaiheistaan, se on kirjoitettuna profeetta Naatanin historiassa, siilolaisen Ahian ennustuksessa ja näkijä Jeddon näyssä Jerobeamista, Nebatin pojasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'Salomo hallitsi Jerusalemissa koko Israelia neljäkymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Sitten Salomo meni lepoon isiensä tykö, ja hänet haudattiin isänsä Daavidin kaupunkiin. Ja hänen poikansa Rehabeam tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Rehabeam meni Sikemiin, sillä koko Israel oli tullut Sikemiin tekemään häntä kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'Kun Jerobeam, Nebatin poika, kuuli sen-hän oli Egyptissä, jonne oli paennut kuningas Salomoa-palasi Jerobeam Egyptistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Ja he lähettivät kutsumaan hänet. Niin Jerobeam ja koko Israel tuli saapuville, ja he puhuivat Rehabeamille sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, '\"Sinun isäsi teki meidän ikeemme raskaaksi; mutta huojenna sinä nyt se kova työ, jota isäsi teetti, ja se raskas ies, jonka hän pani meidän niskaamme, niin me palvelemme sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Hän vastasi heille: \"Odottakaa kolme päivää ja tulkaa sitten takaisin minun tyköni\". Ja kansa meni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Kuningas Rehabeam neuvotteli vanhain kanssa, jotka olivat palvelleet hänen isäänsä Salomoa, kun tämä vielä eli, ja kysyi: \"Kuinka te neuvotte vastaamaan tälle kansalle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'He vastasivat hänelle ja sanoivat: \"Jos sinä olet hyvä tätä kansaa kohtaan, olet armollinen heille ja puhut heille hyviä sanoja, niin he ovat sinun palvelijoitasi kaiken elinaikasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Mutta hän hylkäsi tämän neuvon, jonka vanhat hänelle antoivat, ja neuvotteli nuorten miesten kanssa, jotka olivat kasvaneet hänen kanssaan ja jotka palvelivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'Hän kysyi heiltä: \"Kuinka te neuvotte meitä vastaamaan tälle kansalle, joka on puhunut minulle sanoen: \'Huojenna se ies, jonka sinun isäsi on pannut meidän niskaamme\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Niin nuoret miehet, jotka olivat kasvaneet hänen kanssaan, vastasivat hänelle sanoen: \"Sano näin tälle kansalle, joka on puhunut sinulle sanoen: \'Sinun isäsi teki meidän ikeemme raskaaksi, mutta huojenna sinä se meiltä\' -sano heille näin: \'Minun pikkusormeni on paksumpi kuin minun isäni lantio.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Jos siis isäni on sälyttänyt teidän selkäänne raskaan ikeen, niin minä teen teidän ikeenne vielä raskaammaksi; jos isäni on kurittanut teitä raipoilla, niin minä kuritan teitä piikkiruoskilla.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Niin Jerobeam ja koko kansa tuli Rehabeamin tykö kolmantena päivänä, niinkuin kuningas oli käskenyt, sanoen: \"Tulkaa takaisin minun tyköni kolmantena päivänä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'Ja kuningas antoi heille kovan vastauksen. Sillä kuningas Rehabeam hylkäsi vanhain neuvon');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'ja puhui heille nuorten miesten neuvon mukaan, sanoen: \"Jos minun isäni on tehnyt teidän ikeenne raskaaksi, niin minä teen sen vielä raskaammaksi; jos minun isäni on kurittanut teitä raipoilla, niin minä kuritan teitä piikkiruoskilla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Kuningas ei siis kuullut kansaa; sillä Jumala sen niin salli täyttääkseen sanansa, jonka hän oli puhunut Jerobeamille, Nebatin pojalle, siilolaisen Ahian kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Kun koko Israel huomasi, ettei kuningas heitä kuullut, vastasi kansa kuninkaalle näin: \"Mitä osaa meillä on Daavidiin? Ei meillä ole perintöosaa Iisain poikaan. Majoillesi, Israel, joka mies! Valvo nyt huonettasi, Daavid!\" Ja koko Israel meni majoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Niin Rehabeam tuli ainoastaan niiden israelilaisten kuninkaaksi, jotka asuivat Juudan kaupungeissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Ja kun kuningas Rehabeam lähetti matkaan verotöiden valvojan Hadoramin, kivittivät israelilaiset hänet kuoliaaksi. Silloin kuningas Rehabeam nousi nopeasti vaunuihinsa ja pakeni Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Näin Israel luopui Daavidin suvusta, aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Kun Rehabeam tuli Jerusalemiin, kokosi hän Juudan heimon ja Benjaminin, sata kahdeksankymmentä tuhatta sotakuntoista valiomiestä, sotimaan Israelia vastaan ja palauttamaan kuninkuutta Rehabeamille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Mutta Jumalan miehelle Semajalle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, '\"Sano Rehabeamille, Salomon pojalle, Juudan kuninkaalle, ja koko Israelille Juudassa ja Benjaminissa näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, '\'Näin sanoo Herra: Älkää menkö sotimaan veljiänne vastaan. Palatkaa kukin kotiinne, sillä minä olen sallinut tämän tapahtua.\'\" Niin he kuulivat Herran sanoja, kääntyivät takaisin eivätkä menneet Jerobeamia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'Mutta Rehabeam asui Jerusalemissa ja linnoitti lujasti Juudan kaupunkeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Hän linnoitti Beetlehemin, Eetanin, Tekoan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Beet-Suurin, Sookon, Adullamin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gatin, Maaresan, Siifin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraimin, Laakiin, Asekan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Soran, Aijalonin ja Hebronin, jotka ovat Juudassa ja Benjaminissa; ne hän linnoitti lujiksi kaupungeiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'Hän varusti linnoitukset ja sijoitti niihin päämiehiä sekä muonavarastoja, öljyä ja viiniä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'ja jokaiseen kaupunkiin kilpiä ja keihäitä; hän varusti ne hyvin lujasti. Ja Juuda ja Benjamin olivat hänen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Ja papit ja leeviläiset, mitä koko Israelissa oli, tulivat kaikilta alueiltaan ja asettuivat palvelemaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Sillä leeviläiset jättivät laidunmaansa ja perintömaansa ja lähtivät Juudaan ja Jerusalemiin, koska Jerobeam ja hänen poikansa olivat hyljänneet heidät, niin etteivät he saaneet pappeina palvella Herraa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'Jerobeam kun oli asettanut itselleen pappeja uhrikukkuloita varten ja metsänpeikkoja varten ja vasikoita varten, jotka hän oli teettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'Ja heitä seurasivat kaikista Israelin sukukunnista Jerusalemiin ne, jotka sydämestään antautuivat etsimään Herraa, Israelin Jumalaa, uhratakseen Herralle, isiensä Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'Näin he vahvistivat Juudan valtakuntaa ja tukivat Rehabeamia, Salomon poikaa, kolme vuotta; sillä he vaelsivat Daavidin ja Salomon teitä kolme vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Ja Rehabeam otti vaimokseen Mahlatin, joka oli Daavidin pojan Jerimotin ja Iisain pojan Eliabin tyttären Abihailin tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Tämä synnytti hänelle pojat Jeuksen, Semarjan ja Saahamin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Hänen jälkeensä hän nai Maakan, Absalomin tyttären, joka synnytti hänelle Abian, Attain, Siisan ja Selomitin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Ja Rehabeam rakasti Maakaa, Absalomin tytärtä, enemmän kuin kaikkia muita vaimojaan ja sivuvaimojaan. Sillä hän oli ottanut kahdeksantoista vaimoa ja kuusikymmentä sivuvaimoa; ja hänelle syntyi kaksikymmentä kahdeksan poikaa ja kuusikymmentä tytärtä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'Ja Rehabeam asetti Abian, Maakan pojan, päämieheksi, ruhtinaaksi hänen veljiensä joukossa, sillä hän aikoi tehdä hänet kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'Ja viisaasti hän jakoi kaikki Juudan ja Benjaminin maakunnat ja kaikki varustetut kaupungit kaikkien poikiensa kesken ja antoi heille runsaasti elintarpeita ja hankki heille paljon vaimoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'Kun Rehabeamin kuninkuus oli vahvistunut ja hän oli voimistunut, hylkäsi hän Herran lain, hän ja koko Israel hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'Mutta kuningas Rehabeamin viidentenä hallitusvuotena hyökkäsi Siisak, Egyptin kuningas, Jerusalemin kimppuun, sillä he olivat tulleet uskottomiksi Herraa kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Hänellä oli mukanaan sotavaunuja tuhat kaksisataa ja ratsumiehiä kuusikymmentä tuhatta, ja lukematon oli väki, joka tuli hänen kanssaan Egyptistä: liibyalaisia, sukkilaisia ja etiopialaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'Ja hän valloitti Juudan varustetut kaupungit ja tuli aina Jerusalemiin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Niin profeetta Semaja tuli Rehabeamin ja Juudan päämiesten tykö, jotka olivat kokoontuneet Jerusalemiin Siisakia pakoon, ja hän sanoi heille: \"Näin sanoo Herra: Te olette hyljänneet minut, sentähden olen minäkin hyljännyt teidät Siisakin käsiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Silloin Israelin päämiehet ja kuningas nöyrtyivät ja sanoivat: \"Herra on vanhurskas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'Kun Herra näki heidän nöyrtyvän, tuli Semajalle tämä Herran sana: \"He ovat nöyrtyneet; minä en tuhoa heitä, vaan minä annan heidän hädin tuskin pelastua, eikä minun vihaani vuodateta Jerusalemin päälle Siisakin käden kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Kuitenkin heidän on tultava hänen palvelijoikseen, että he tulisivat tietämään, mitä on palvella minua ja mitä on palvella vieraitten maitten valtakuntia.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Niin Siisak, Egyptin kuningas, hyökkäsi Jerusalemin kimppuun ja otti Herran temppelin aarteet ja kuninkaan linnan aarteet, otti kaikki tyynni. Hän otti myös kaikki kultakilvet, jotka Salomo oli teettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'Kuningas Rehabeam teetti niiden sijaan vaskikilvet ja jätti ne henkivartijain päälliköitten haltuun, jotka vartioivat kuninkaan linnan ovella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'Ja niin usein kuin kuningas meni Herran temppeliin, menivät myöskin henkivartijat ja kantoivat niitä ja veivät ne sitten takaisin henkivartijain huoneeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'Sentähden, että Rehabeam nöyrtyi, kääntyi Herran viha hänestä pois, niin ettei tullut täydellistä tuhoa; ja olivathan asiat Juudassa vielä hyvin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Niin kuningas Rehabeam vahvistui Jerusalemissa ja hallitsi edelleen. Sillä Rehabeam oli neljänkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi seitsemäntoista vuotta Jerusalemissa, siinä kaupungissa, jonka Herra oli valinnut kaikista Israelin sukukunnista, sijoittaaksensa nimensä siihen. Hänen äitinsä oli nimeltään Naema, ammonilainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Ja hän teki sitä, mikä on pahaa, sillä hän ei kiinnittänyt sydäntänsä etsimään Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Rehabeamin vaiheet, sekä aikaisemmat että myöhemmät, ovat kirjoitetut profeetta Semajan ja näkijä Iddon historiaan, sukuluettelojen tapaan. Mutta Rehabeamin ja Jerobeamin väliset taistelut jatkuivat kaiken aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'Sitten Rehabeam meni lepoon isiensä tykö, ja hänet haudattiin Daavidin kaupunkiin. Ja hänen poikansa Abia tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Kuningas Jerobeamin kahdeksantenatoista hallitusvuotena tuli Abia Juudan kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Hän hallitsi kolme vuotta Jerusalemissa. Hänen äitinsä nimi oli Mikaja, Uurielin tytär, Gibeasta. Mutta Abia ja Jerobeam olivat sodassa keskenään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Abia alotti sodan urhoollisella sotajoukolla, neljälläsadalla tuhannella valiomiehellä, mutta Jerobeam asettui sotarintaan häntä vastaan kahdeksallasadalla tuhannella valiomiehellä, sotaurholla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Ja Abia nousi Semaraimin vuoren laelle Efraimin vuoristossa ja sanoi: \"Kuulkaa minua, Jerobeam ja koko Israel!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Täytyyhän teidän tietää, että Herra, Israelin Jumala, on antanut Daavidille ja hänen pojillensa ikuisiksi ajoiksi Israelin kuninkuuden, lujan kuin suolaliitto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Mutta Jerobeam, Nebatin poika, Daavidin pojan Salomon palvelija, nousi ja kapinoitsi herraansa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'Ja hänen luoksensa kokoontui tyhjäntoimittajia, kelvottomia miehiä, ja he pääsivät voitolle Rehabeamista, Salomon pojasta, sillä Rehabeam oli nuori ja arka eikä voinut heitä vastustaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Ja nyt te luulette voivanne vastustaa Herran kuninkuutta, joka on Daavidin poikien käsissä, koska teitä on suuri joukko ja teillä on kultavasikat, jotka Jerobeam on teettänyt teille jumaliksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Ettekö te ole karkoittaneet Herran pappeja, Aaronin poikia, ja leeviläisiä, ja itse tehneet itsellenne pappeja, niinkuin muiden maiden kansat tekevät? Ken tahansa tuli papinvirkaan vihittäväksi, mukanaan mullikka ja seitsemän oinasta, hänestä tuli epäjumalan pappi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Mutta meidän Jumalamme on Herra, ja häntä me emme ole hyljänneet. Ja pappeina palvelevat Herraa Aaronin pojat, ja leeviläiset toimittavat palvelustehtäviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'He polttavat Herralle polttouhreja joka aamu ja joka ilta ja hyvänhajuista suitsutusta, ja he latovat leivät päälletysten aitokultaiselle pöydälle ja sytyttävät joka ilta kultaisen seitsenhaaraisen lampun lamppuineen; sillä me hoidamme Herran, meidän Jumalamme, meille antamat tehtävät, mutta te olette hänet hyljänneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Ja katso, meidän kanssamme, meidän edellämme on Jumala ja ovat hänen pappinsa, ja hälytystorvet toitottamassa teitä vastaan. Te israelilaiset, älkää sotiko Herraa, isienne Jumalaa, vastaan, sillä se ei teille onnistu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Mutta Jerobeam oli pannut väkeä kiertämään heidän taaksensa väijyksiin, niin että toiset olivat Juudan miesten edessä ja toiset väijyksissä heidän takanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Kun Juudan miehet kääntyivät, niin katso, heillä oli sota edessä ja takana. Silloin he huusivat Herraa, ja papit puhalsivat torviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Ja Juudan miehet nostivat sotahuudon; ja kun Juudan miehet nostivat sotahuudon, antoi Jumala Abian ja Juudan voittaa Jerobeamin ja koko Israelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'Ja israelilaiset kääntyivät Juudan miehiä pakoon, ja Jumala antoi heidät näiden käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'Ja Abia väkinensä tuotti heille suuren tappion, niin että israelilaisia kaatui viisisataa tuhatta valiomiestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Näin israelilaiset siihen aikaan nöyryytettiin; mutta Juudan miehet voimistuivat, sillä he turvautuivat Herraan, isiensä Jumalaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'Ja Abia ajoi Jerobeamia takaa ja valloitti häneltä muutamia kaupunkeja: Beetelin ja sen tytärkaupungit, Jesanan ja sen tytärkaupungit ja Efronin ja sen tytärkaupungit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Eikä Jerobeam enää tullut voimiinsa Abian elinpäivinä, vaan Herra löi häntä, niin että hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Mutta Abia vahvistui. Ja hän otti itselleen neljätoista vaimoa, ja hänelle syntyi kaksikymmentä kaksi poikaa ja kuusitoista tytärtä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Mitä muuta on kerrottavaa Abiasta, hänen vaelluksestaan ja hänen puheistaan, se on kirjoitettuna profeetta Iddon selityskirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'Sitten Abia meni lepoon isiensä tykö, ja hänet haudattiin Daavidin kaupunkiin. Ja hänen poikansa Aasa tuli kuninkaaksi hänen sijaansa. Hänen aikanansa oli maassa rauha kymmenen vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'Ja Aasa teki sitä, mikä oli hyvää ja oikeata Herran, hänen Jumalansa, silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Hän poisti vieraat alttarit ja uhrikukkulat, murskasi patsaat ja hakkasi maahan asera-karsikot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'Ja hän kehoitti Juudaa etsimään Herraa, heidän isiensä Jumalaa, ja noudattamaan lakia ja käskyjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Ja kaikista Juudan kaupungeista hän poisti uhrikukkulat ja auringonpatsaat, ja valtakunnassa oli rauha hänen aikanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Ja hän rakensi varustettuja kaupunkeja Juudaan, koska maassa oli rauha eikä hänellä näinä vuosina ollut mitään sotaa; sillä Herra oli suonut hänen päästä rauhaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Hän sanoi Juudalle: \"Linnoittakaamme nämä kaupungit, ympäröikäämme ne muureilla ja torneilla, ovilla ja salvoilla. Vielä on maa meidän vallassamme, sentähden että me olemme etsineet Herraa, meidän Jumalaamme. Me olemme etsineet häntä, ja hän on suonut meidän päästä rauhaan joka taholla.\" Niin he rakensivat, ja se heille onnistui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'Ja Aasalla oli sotajoukko, joka oli varustettu kilvillä ja keihäillä: Juudasta oli kolmesataa tuhatta miestä ja Benjaminista kaksisataa kahdeksankymmentä tuhatta, jotka kantoivat kilpeä ja jännittivät jousta. Kaikki nämä olivat sotaurhoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Mutta etiopialainen Serah lähti heitä vastaan sotajoukolla, jossa oli miehiä tuhannen tuhatta ja sotavaunuja kolmesataa; ja hän tuli Maaresaan saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Ja Aasa lähti häntä vastaan, ja he asettuivat sotarintaan Sefatan laaksoon, Maaresaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Ja Aasa huusi Herraa, Jumalaansa, ja sanoi: \"Herra, sinä yksin voit auttaa taistelussa voimallisen ja voimattoman välillä. Auta meitä, Herra, meidän Jumalamme, sillä sinuun me turvaudumme ja sinun nimessäsi me olemme tulleet tätä suurta joukkoa vastaan. Herra, sinä olet meidän Jumalamme; älä salli ihmisen päästä voitolle sinusta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'Niin Herra antoi Aasan ja Juudan voittaa etiopialaiset, ja etiopialaiset pakenivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Ja Aasa ja väki, joka oli hänen kanssaan, ajoivat heitä takaa Gerariin saakka. Ja etiopialaisia kaatui niin paljon, ettei heistä jäänyt ketään henkiin, sillä Herra ja hänen sotajoukkonsa tuhosivat heidät. Ja he ottivat paljon saalista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'valloittivat kaikki kaupungit Gerarin ympäriltä, sillä Herran kauhu oli vallannut nämä, ja ryöstivät kaikki kaupungit, sillä niissä oli paljon ryöstettävää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Jopa karjamajatkin he valtasivat, veivät pois saaliinaan paljon lampaita ja kameleja ja palasivat Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Niin Jumalan henki tuli Asarjaan, Oodedin poikaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Hän meni Aasaa vastaan ja sanoi hänelle: \"Kuulkaa minua, Aasa ja koko Juuda ja Benjamin. Herra on teidän kanssanne, kun te olette hänen kanssansa; ja jos häntä etsitte, niin te löydätte hänet, mutta jos hylkäätte hänet, niin hän hylkää teidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Kauan aikaa Israel oli ilman oikeata Jumalaa, ilman opetusta antavaa pappia ja ilman lakia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Mutta kun he ahdistuksessansa palasivat Herran, Israelin Jumalan, tykö ja etsivät häntä, niin he löysivät hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Niinä aikoina ei ollut turvallisuutta niillä, jotka lähtivät ja tulivat, vaan suuri hämminki vallitsi kaikkien maakuntain asukasten keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'Ja kansa törmäsi kansaa vastaan ja kaupunki kaupunkia vastaan, sillä Jumala oli saattanut heidät hämminkiin lähettäen kaikkinaisia ahdistuksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Mutta te olkaa lujat älkääkä antako kättenne vaipua, sillä teidän työllänne on palkkansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'Kun Aasa kuuli nämä profeetta Oodedin sanat ja ennustuksen, rohkaisi hän mielensä ja toimitti pois iljetykset koko Juudan ja Benjaminin maasta ja niistä kaupungeista, jotka hän oli valloittanut Efraimin vuoristosta, ja uudisti Herran alttarin, joka oli Herran eteisen edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Ja hän kokosi koko Juudan ja Benjaminin ja myöskin heidän luonaan asuvat muukalaiset, jotka olivat tulleet Efraimista, Manassesta ja Simeonista, sillä monet olivat siirtyneet Israelista hänen luokseen nähtyänsä, että Herra, hänen Jumalansa, oli hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'Ja he kokoontuivat Jerusalemiin Aasan viidennentoista hallitusvuoden kolmannessa kuussa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'ja uhrasivat sinä päivänä Herralle saaliista, minkä he olivat tuoneet, seitsemänsataa raavasta ja seitsemäntuhatta lammasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'Ja he tekivät liiton, että etsisivät Herraa, isiensä Jumalaa, kaikesta sydämestään ja kaikesta sielustaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'ja että jokainen, joka ei etsinyt Herraa, Israelin Jumalaa, oli surmattava, olipa hän pieni tai suuri, mies tai nainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'Ja he vannoivat valan Herralle suurella äänellä riemun raikuessa ja torvien ja pasunain pauhatessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'Ja koko Juuda iloitsi siitä valasta, sillä he olivat vannoneet sen kaikesta sydämestään, ja he etsivät Herraa kaikella halullansa ja löysivät hänet; niin Herra soi heidän päästä rauhaan joka taholla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Kuningas Aasa erotti äitinsäkin Maakan kuningattaren arvosta, koska tämä oli pystyttänyt inhotuksen Aseralle; Aasa kukisti inhotuksen, rouhensi ja poltti sen Kidronin laaksossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Mutta uhrikukkulat eivät hävinneet Israelista. Kuitenkin Aasan sydän oli ehyesti Herralle antautunut, niin kauan kuin hän eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Ja hän vei Jumalan temppeliin isänsä pyhät lahjat ja omat pyhät lahjansa: hopeata, kultaa ja kalua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'Eikä ollut sotaa Aasan kolmanteenkymmenenteen viidenteen hallitusvuoteen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Aasan kolmantenakymmenentenä kuudentena hallitusvuotena lähti Baesa, Israelin kuningas, Juudaa vastaan ja linnoitti Raaman, estääkseen ketään pääsemästä Aasan, Juudan kuninkaan, luota tai hänen luokseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Ja Aasa toi hopeata ja kultaa Herran temppelin ja kuninkaan linnan aarrekammioista ja lähetti sen Benhadadille, Aramin kuninkaalle, joka asui Damaskossa, ja käski sanoa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, '\"Onhan liitto meidän välillämme, minun ja sinun, niinkuin oli minun isäni ja sinun isäsi välillä. Katso, minä lähetän sinulle hopeata ja kultaa; mene ja riko liittosi Baesan, Israelin kuninkaan, kanssa, että hän lähtisi pois minun kimpustani.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'Niin Benhadad kuuli kuningas Aasaa ja lähetti sotajoukkojensa päälliköt Israelin kaupunkeja vastaan, ja he valtasivat Iijonin, Daanin ja Aabel-Maimin sekä kaikki Naftalin kaupunkien varastohuoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'Kun Baesa kuuli sen, lakkasi hän linnoittamasta Raamaa ja keskeytti työnsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Mutta kuningas Aasa toi koko Juudan, ja he veivät pois Raamasta kivet ja puut, joilla Baesa oli sitä linnoittanut. Niillä hän linnoitti Geban ja Mispan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'Siihen aikaan tuli näkijä Hanani Aasan, Juudan kuninkaan, tykö ja sanoi hänelle: \"Koska sinä turvauduit Aramin kuninkaaseen etkä turvautunut Herraan, Jumalaasi, sentähden on Aramin kuninkaan sotajoukko päässyt sinun käsistäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Eikö etiopialaisia ja liibyalaisia ollut suuri sotajoukko, eikö heillä ollut hyvin paljon sotavaunuja ja ratsumiehiä? Mutta koska sinä turvauduit Herraan, antoi hän heidät sinun käsiisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Sillä Herran silmät tarkkaavat kaikkea maata, että hän voimakkaasti auttaisi niitä, jotka ovat ehyellä sydämellä antautuneet hänelle. Tässä sinä teit tyhmästi, sillä tästä lähtien on sinulla yhä oleva sotia.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Mutta Aasa vihastui näkijään ja panetti hänet vankilaan, sillä niin vihoissaan hän oli hänelle tästä. Myöskin muutamille muille kansasta Aasa siihen aikaan teki väkivaltaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Aasan vaiheet, sekä aikaisemmat että myöhemmät, katso, ne ovat kirjoitettuina Juudan ja Israelin kuningasten kirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Ja kolmantenakymmenentenä yhdeksäntenä hallitusvuotenaan Aasa sairastui jaloistaan, ja hänen tautinsa yltyi hyvin kovaksi. Mutta taudissaankaan hän ei etsinyt Herraa, vaan lääkäreitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'Sitten Aasa meni lepoon isiensä tykö ja kuoli neljäntenäkymmenentenä yhdentenä hallitusvuotenaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'Ja hänet haudattiin omaan hautaansa, jonka hän oli hakkauttanut itsellensä Daavidin kaupunkiin; ja hänet laskettiin vuoteelle, joka oli täytetty hajuaineilla ja erilaisilla, voiteeksi sekoitetuilla höysteillä, ja hänen kunniakseen poltettiin ylen runsas kuolinsuitsutus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Hänen poikansa Joosafat tuli kuninkaaksi hänen sijaansa. Hän vahvistautui Israelia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Hän sijoitti sotaväkeä kaikkiin Juudan varustettuihin kaupunkeihin ja asetti maaherroja Juudan maahan ja Efraimin kaupunkeihin, jotka hänen isänsä Aasa oli valloittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'Ja Herra oli Joosafatin kanssa, sillä hän vaelsi isänsä Daavidin aikaisempia teitä eikä etsinyt baaleja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'vaan hän etsi isänsä Jumalaa ja vaelsi hänen käskyjensä mukaan eikä tehnyt, niinkuin Israel teki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Niin Herra vahvisti kuninkuuden hänen käsissään, ja koko Juuda antoi lahjoja Joosafatille, niin että hänelle tuli paljon rikkautta ja kunniaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'Ja kun hänen rohkeutensa kasvoi Herran teillä, poisti hän vielä uhrikukkulatkin ja asera-karsikot Juudasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Ja kolmantena hallitusvuotenaan hän lähetti ylimmät virkamiehensä Benhailin, Obadjan, Sakarjan, Netanelin ja Miikajan Juudan kaupunkeihin antamaan opetusta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'ja heidän kanssansa leeviläiset Semajan, Netanjan, Sebadjan, Asahelin, Semiramotin, Joonatanin, Adonian, Tobian ja Toob-Adonian, leeviläiset; ja näillä oli kanssansa papit Elisama ja Jooram.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Nämä opettivat Juudassa, ja heillä oli mukanaan Herran lain kirja; he kiertelivät kaikissa Juudan kaupungeissa ja opettivat kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Ja Herran kauhu valtasi kaikki Juudaa ympäröivien maitten valtakunnat, niin etteivät ne sotineet Joosafatia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Ja osa filistealaisia toi Joosafatille lahjoja ja hopeata veroksi; myöskin arabialaiset toivat hänelle pikkukarjaa: seitsemäntuhatta seitsemänsataa oinasta ja seitsemäntuhatta seitsemänsataa pukkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Niin Joosafat tuli yhä mahtavammaksi, jopa ylen mahtavaksi, ja hän rakensi Juudaan linnoja ja varastokaupunkeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'Hänellä oli suuria varastoja Juudan kaupungeissa ja sotilaita, sotaurhoja, Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'Ja tämä oli heidän palvelusvuoronsa heidän perhekuntiensa mukaan: Juudan tuhanten päämiehet olivat: päämies Adna ja hänen kanssaan kolmesataa tuhatta sotaurhoa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'hänen rinnallaan päämies Joohanan ja hänen kanssaan kaksisataa kahdeksankymmentä tuhatta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'hänen rinnallaan Amasja, Sikrin poika, joka oli vapaaehtoisesti antautunut Herralle, ja hänen kanssaan kaksisataa tuhatta sotaurhoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Benjaminista: Eljada, sotaurho, ja hänen kanssaan kaksisataa tuhatta jousella ja kilvellä asestettua;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'hänen rinnallaan Joosabad ja hänen kanssaan sata kahdeksankymmentä tuhatta sotaan varustettua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Nämä palvelivat kuningasta, ja lisäksi ne, jotka kuningas oli sijoittanut varustettuihin kaupunkeihin koko Juudaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'Niin Joosafatille tuli paljon rikkautta ja kunniaa, ja hän lankoutui Ahabin kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'Ja muutamien vuosien kuluttua hän meni Ahabin luo Samariaan. Ahab teurastutti hänelle ja väelle, joka oli hänen kanssansa, paljon lampaita ja raavaita; ja Ahab yllytti häntä lähtemään sotaan Gileadin Raamotia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Israelin kuningas Ahab sanoi Juudan kuninkaalle Joosafatille: \"Lähdetkö minun kanssani Gileadin Raamotiin?\" Hän vastasi hänelle: \"Minä niinkuin sinä, minun kansani niinkuin sinun kansasi; minä tulen sinun kanssasi sotaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Mutta Joosafat sanoi Israelin kuninkaalle: \"Kysy kuitenkin ensin, mitä Herra sanoo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Niin Israelin kuningas kokosi profeetat, neljäsataa miestä, ja sanoi heille: \"Onko meidän lähdettävä sotaan Gileadin Raamotia vastaan, vai onko minun oltava lähtemättä?\" He vastasivat: \"Lähde; Jumala antaa sen kuninkaan käsiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Mutta Joosafat sanoi: \"Eikö täällä ole enää ketään muuta Herran profeettaa, jolta voisimme kysyä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'Israelin kuningas vastasi Joosafatille: \"On vielä mies, jolta voisimme kysyä Herran mieltä, mutta minä vihaan häntä, sillä hän ei koskaan ennusta minulle hyvää, vaan aina pahaa; se on Miika, Jimlan poika\". Joosafat sanoi: \"Älköön kuningas niin puhuko\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Niin Israelin kuningas kutsui erään hoviherran ja sanoi: \"Nouda kiiruusti Miika, Jimlan poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Mutta Israelin kuningas ja Joosafat, Juudan kuningas, istuivat kumpikin valtaistuimellansa puettuina kuninkaallisiin pukuihinsa; he istuivat puimatantereella Samarian portin ovella, ja kaikki profeetat olivat hurmoksissa heidän edessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'Ja Sidkia, Kenaanan poika, teki itsellensä rautasarvet ja sanoi: \"Näin sanoo Herra: Näillä sinä pusket aramilaisia, kunnes teet heistä lopun\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Ja kaikki profeetat ennustivat samalla tavalla, sanoen: \"Mene Gileadin Raamotiin, niin sinä saat voiton; Herra antaa sen kuninkaan käsiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Ja sanansaattaja, joka oli mennyt kutsumaan Miikaa, puhui hänelle sanoen: \"Katso, kaikki profeetat ovat yhdestä suusta luvanneet kuninkaalle hyvää. Olkoon sinun sanasi heidän sanansa kaltainen, ja lupaa sinäkin hyvää.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'Mutta Miika vastasi: \"Niin totta kuin Herra elää, sen minä puhun, minkä minun Jumalani sanoo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'Kun hän tuli kuninkaan eteen, sanoi kuningas hänelle: \"Miika, onko meidän lähdettävä sotaan Gileadin Raamotiin, vai onko minun oltava lähtemättä?\" Hän vastasi hänelle: \"Menkää, niin te saatte voiton; heidät annetaan teidän käsiinne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Mutta kuningas sanoi hänelle: \"Kuinka monta kertaa minun on vannotettava sinua, ettet puhu minulle muuta kuin totuutta Herran nimessä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Silloin hän sanoi: \"Minä näin koko Israelin hajallaan vuorilla, niinkuin lampaat, joilla ei ole paimenta. Ja Herra sanoi: \'Näillä ei ole isäntää; palatkoot he kukin rauhassa kotiinsa\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Niin Israelin kuningas sanoi Joosafatille: \"Enkö minä sanonut sinulle, ettei tämä koskaan ennusta minulle hyvää, vaan aina pahaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Mutta hän sanoi: \"Kuulkaa siis Herran sana: Minä näin Herran istuvan istuimellansa ja kaiken taivaan joukon seisovan hänen edessään, hänen oikealla ja vasemmalla puolellansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'Ja Herra sanoi: \'Kuka viekoittelisi Ahabin, Israelin kuninkaan, lähtemään sotaan, että hän kaatuisi Gileadin Raamotissa?\' Mikä vastasi niin, mikä näin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Silloin tuli henki ja asettui Herran eteen ja sanoi: \'Minä viekoittelen hänet\'. Herra kysyi häneltä: \'Miten?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Hän vastasi: \'Minä menen valheen hengeksi kaikkien hänen profeettainsa suuhun\'. Silloin Herra sanoi: \'Saat viekoitella, siihen sinä pystyt; mene ja tee niin\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Katso, nyt Herra on pannut valheen hengen näiden sinun profeettaisi suuhun, sillä Herra on päättänyt sinun osaksesi onnettomuuden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Silloin astui esille Sidkia, Kenaanan poika, löi Miikaa poskelle ja sanoi: \"Mitä tietä Herran Henki on poistunut minusta puhuakseen sinun kanssasi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Miika vastasi: \"Sen saat nähdä sinä päivänä, jona kuljet huoneesta huoneeseen piiloutuaksesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Mutta Israelin kuningas sanoi: \"Ottakaa Miika ja viekää hänet takaisin Aamonin, kaupungin päällikön, ja Jooaan, kuninkaan pojan, luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'Ja sanokaa: \'Näin sanoo kuningas: Pankaa tämä vankilaan ja elättäkää häntä vaivaisella vedellä ja leivällä, kunnes minä palaan voittajana takaisin\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Miika vastasi: \"Jos sinä palaat voittajana takaisin, niin ei Herra ole puhunut minun kauttani\". Ja hän sanoi vielä: \"Kuulkaa tämä, kaikki kansat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Niin Israelin kuningas ja Joosafat, Juudan kuningas, menivät Gileadin Raamotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'Ja Israelin kuningas sanoi Joosafatille: \"Täytyypä pukeutua tuntemattomaksi, kun käy taisteluun; mutta ole sinä omissa vaatteissasi\". Ja Israelin kuningas pukeutui tuntemattomaksi ja kävi taisteluun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Mutta Aramin kuningas oli käskenyt sotavaunujensa päälliköitä sanoen: \"Älkää ryhtykö taisteluun kenenkään muun kanssa, olkoon alempi tai ylempi, kuin ainoastaan Israelin kuninkaan kanssa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Kun sotavaunujen päälliköt näkivät Joosafatin, ajattelivat he: \"Tuo on Israelin kuningas\", ja ympäröivät hänet hyökätäkseen hänen kimppuunsa. Silloin Joosafat huusi, ja Herra auttoi häntä, ja Jumala houkutteli heidät pois hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Kun sotavaunujen päälliköt näkivät, ettei se ollutkaan Israelin kuningas, vetäytyivät he hänestä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Mutta eräs mies, joka oli jännittänyt jousensa ja ampui umpimähkään, satutti Israelin kuningasta vyöpanssarin ja rintahaarniskan väliin. Niin tämä sanoi vaunujensa ohjaajalle: \"Käännä vaunut ja vie minut pois sotarinnasta, sillä minä olen haavoittunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'Mutta kun taistelu sinä päivänä yltyi yltymistään, jäi Israelin kuningas seisomaan vaunuihinsa, päin aramilaisia, iltaan asti; auringonlaskun aikaan hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Mutta Joosafat, Juudan kuningas, palasi onnellisesti takaisin kotiinsa Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Silloin Jeehu, Hananin poika, näkijä, meni kuningas Joosafatia vastaan ja sanoi hänelle: \"Oliko sinun autettava jumalatonta, ja rakastatko sinä niitä, jotka vihaavat Herraa? Sentähden on sinun päälläsi Herran viha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Kuitenkin on sinussa löydetty myös hyvää, sillä sinä olet hävittänyt aserat maasta ja kiinnittänyt sydämesi Jumalan etsimiseen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'Niin Joosafat jäi Jerusalemiin. Sitten hän meni jälleen kansan keskeen, Beersebasta lähtien aina Efraimin vuoristoon saakka, ja palautti heidät takaisin Herran, heidän isiensä Jumalan, tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'Ja hän asetti tuomareita maahan, kaikkiin Juudan varustettuihin kaupunkeihin, kaupunki kaupungilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Ja hän sanoi tuomareille: \"Katsokaa, mitä teette, sillä te ette ole tekemässä ihmisten tuomioita, vaan Herran tuomioita, ja hän on teidän kanssanne, kun te tuomitsette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Hallitkoon siis teitä Herran pelko. Ottakaa vaari siitä, mitä teette, sillä Herrassa, meidän Jumalassamme, ei ole vääryyttä eikä puolueellisuutta, eikä hän ota lahjuksia.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Myöskin Jerusalemiin Joosafat asetti leeviläisiä, pappeja ja Israelin perhekunta-päämiehiä jakamaan Herran oikeutta ja ratkaisemaan riita-asioita. Ja he palasivat Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'Ja hän käski heitä sanoen: \"Tehkää Herraa peljäten, uskollisesti ja ehyellä sydämellä näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'Jokaisessa riita-asiassa, minkä veljenne, jotka asuvat kaupungeissansa, tuovat teidän eteenne, koskipa se murhaa tai lakia, käskyä, säädöksiä tai oikeuksia, varoittakaa heitä, etteivät saattaisi itseänsä vikapäiksi Herran edessä ja ettei viha kohtaisi teitä ja teidän veljiänne. Näin tehkää, ettette tulisi vikapäiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'Ja katso, ylimmäinen pappi Amarja olkoon teillä esimiehenä kaikissa Herran asioissa ja Sebadja, Ismaelin poika, Juudan heimoruhtinas, kaikissa kuninkaan asioissa, ja olkoot leeviläiset teillä virkamiehinä. Olkaa lujat ja ryhtykää työhön; ja Herra olkoon sen kanssa, joka hyvä on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'Senjälkeen tulivat mooabilaiset ja ammonilaiset, ja heidän kanssaan myös muita paitsi ammonilaisia, sotimaan Joosafatia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Niin tultiin ilmoittamaan tästä Joosafatille: \"Suuri joukko tulee sinua vastaan meren toiselta puolelta, Aramista, ja katso, he ovat jo Hasason-Taamarissa\"; se on Een-Gedissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'Silloin Joosafat peljästyi ja kääntyi kysymään Herralta ja kuulutti paaston koko Juudaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Niin Juuda kokoontui etsimään apua Herralta; myös kaikista Juudan kaupungeista tultiin etsimään Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'Ja Joosafat astui esiin Juudan ja Jerusalemin seurakunnassa, Herran temppelissä, uuden esipihan edessä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'ja sanoi: \"Herra, meidän isiemme Jumala, sinä olet Jumala taivaassa, ja sinä hallitset kaikkia pakanakansain valtakuntia. Sinun kädessäsi on voima ja väkevyys, eikä kukaan kestä sinun edessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Sinä, meidän Jumalamme, karkoitit tämän maan asukkaat kansasi Israelin tieltä ja annoit sen ystäväsi Aabrahamin jälkeläisille ikuisiksi ajoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'He asettuivat tänne ja rakensivat täällä sinulle, sinun nimellesi, pyhäkön sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, '\'Jos meitä kohtaa joku onnettomuus, miekka, rangaistustuomio, rutto tai nälänhätä, niin me astumme tämän temppelin eteen ja sinun eteesi, sillä sinun nimesi on tässä temppelissä; ja me huudamme sinua hädässämme, ja sinä kuulet ja autat\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Ja katso, siinä ovat nyt ammonilaiset ja mooabilaiset ja Seirin vuoristolaiset, joiden alueen kautta sinä et antanut israelilaisten kulkea, kun he tulivat Egyptin maasta, vaan nämä kääntyivät heistä pois eivätkä tuhonneet heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Katso, nyt he kostavat sen meille: he tulevat karkoittamaan meitä maasta, joka on sinun omasi ja jonka sinä olet antanut meidän omaksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'Meidän Jumalamme, etkö tuomitse heitä? Sillä me emme mahda mitään tätä suurta joukkoa vastaan, joka hyökkää meidän kimppuumme, emmekä itse tiedä mitä tehdä, vaan sinuun meidän silmämme katsovat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Kaikki Juudan miehet seisoivat siinä Herran edessä pikkulapsineen, vaimoineen ja poikineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Ja Herran Henki tuli seurakunnan keskellä Jahasieliin, Sakarjan poikaan, joka oli Benajan poika, joka Jegielin poika, joka Mattanjan poika, leeviläisen, joka oli Aasafin jälkeläisiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'ja hän sanoi: \"Kuunnelkaa, kaikki te Juudan miehet ja Jerusalemin asukkaat ja sinä kuningas Joosafat. Näin sanoo teille Herra: Älkää peljätkö älkääkä arkailko tätä suurta joukkoa, sillä sota ei ole teidän, vaan Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Menkää huomenna heitä vastaan. Katso, he nousevat silloin Siisin solaa pitkin, ja te kohtaatte heidät laakson päässä, itäänpäin Jeruelin erämaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Mutta silloin ei ole teidän asianne taistella. Astukaa esiin, seisokaa ja katsokaa, kuinka Herra pelastaa teidät, Juuda ja Jerusalem. Älkää peljätkö älkääkä arkailko; menkää huomenna heitä vastaan, ja Herra on oleva teidän kanssanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Silloin Joosafat kumartui kasvoillensa maahan, ja kaikki Juudan miehet ja Jerusalemin asukkaat lankesivat Herran eteen, rukoilemaan Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Ja ne leeviläiset, jotka olivat Kehatin ja Koorahin jälkeläisiä, nousivat ylistämään Herraa, Israelin Jumalaa, ylen korkealla äänellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Mutta varhain seuraavana aamuna he menivät Tekoan erämaahan. Ja heidän lähtiessänsä Joosafat astui esiin ja sanoi: \"Kuulkaa minua, te Juudan ja Jerusalemin asukkaat. Uskokaa Herraan, Jumalaanne, niin te olette hyvässä turvassa, ja uskokaa hänen profeettojansa, niin te menestytte.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'Ja neuvoteltuaan kansan kanssa hän asetti veisaajat veisaamaan Herralle ylistysvirsiä pyhässä kaunistuksessa ja kulkemaan aseväen edellä sanoen: \"Kiittäkää Herraa, sillä hänen armonsa pysyy iankaikkisesti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'Ja juuri kun he alottivat riemuhuudon ja ylistysvirren, antoi Herra väijyjiä tulla ammonilaisten, mooabilaisten ja Seirin vuoristolaisten selkään, jotka olivat hyökänneet Juudan kimppuun; ja heidät voitettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Sillä ammonilaiset ja mooabilaiset asettuivat Seirin vuoristolaisia vastaan tuhoamaan ja hävittämään heitä; ja kun he olivat lopettaneet Seirin asukkaat, auttoivat he toisiaan toistensa tuhoamisessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Kun Juudan miehet tulivat paikalle, josta voi tähystää erämaahan, ja kääntyivät joukkoon päin, niin katso, ruumiita makasi maassa, ei kukaan ollut pelastunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Niin Joosafat väkineen tuli ryöstämään heiltä saalista, ja he löysivät heidän seastaan paljon sekä tavaraa että ruumiita ja kalliita kaluja. Ja he ottivat itsellensä enemmän kuin saivat kannetuksi; he ryöstivät saalista kolme päivää, sillä sitä oli paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Neljäntenä päivänä he kokoontuivat Beraka-laaksoon; sillä siellä he kiittivät Herraa. Siitä on sen paikan nimenä Beraka-laakso vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Senjälkeen kaikki Juudan ja Jerusalemin miehet, ja Joosafat heidän etunenässään, kääntyivät iloiten paluumatkalle Jerusalemiin, sillä Herra oli antanut heille ilon heidän vihollisistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'Ja he tulivat soittaen harpuilla, kanteleilla ja torvilla Jerusalemiin, Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Ja Jumalan kauhu valtasi kaikkien maitten valtakunnat, kun he kuulivat Herran sotineen Israelin vihollisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'Sitten Joosafatin valtakunnalla oli rauha; hänen Jumalansa soi hänen päästä rauhaan joka taholla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Niin hallitsi Joosafat Juudaa. Hän oli kolmenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä viisi vuotta. Hänen äitinsä oli nimeltään Asuba, Silhin tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'Ja hän vaelsi isänsä Aasan tietä, siltä poikkeamatta, ja teki sitä, mikä on oikein Herran silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Mutta uhrikukkulat eivät hävinneet, eikä kansa vielä ollut kiinnittänyt sydäntänsä isiensä Jumalaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Mitä muuta on kerrottavaa Joosafatista, sekä hänen aikaisemmista että myöhemmistä vaiheistaan, katso, se on kirjoitettuna Jeehun, Hananin pojan, historiassa, joka on otettu Israelin kuningasten kirjaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Senjälkeen Joosafat, Juudan kuningas, liittoutui Ahasjan, Israelin kuninkaan, kanssa, joka oli jumalaton menoissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Hän liittoutui tämän kanssa rakentaakseen laivoja, joiden oli määrä kulkea Tarsiiseen; ja niin he rakensivat laivoja Esjon-Geberissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Mutta Elieser, Doodavahun poika, Maaresasta, ennusti Joosafatia vastaan sanoen: \"Koska olet liittoutunut Ahasjan kanssa, on Herra särkevä sinun työsi\". Niin laivat rikkoutuivat eivätkä kyenneet menemään Tarsiiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Sitten Joosafat meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen Daavidin kaupunkiin. Ja hänen poikansa Jooram tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Ja hänellä oli veljiä: Joosafatin pojat Asarja, Jehiel, Sakarja, Asarjahu, Miikael ja Sefatja. Nämä kaikki olivat Joosafatin, Israelin kuninkaan, poikia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Ja heidän isänsä oli antanut heille suuria lahjoja, hopeata, kultaa ja kalleuksia, sekä varustettuja kaupunkeja Juudassa; mutta kuninkuuden hän oli antanut Jooramille, sillä tämä oli esikoinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Kun Jooram oli noussut isänsä valtaistuimelle ja vahvistunut, tappoi hän miekalla kaikki veljensä, niin myös muutamia Israelin päämiehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Jooram oli kolmenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kahdeksan vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'Mutta hän vaelsi Israelin kuningasten tietä, niinkuin Ahabin suku oli tehnyt, sillä hänellä oli puolisona Ahabin tytär; ja niin hän teki sitä, mikä on pahaa Herran silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Mutta Herra ei tahtonut tuhota Daavidin sukua, koska hän oli tehnyt liiton Daavidin kanssa ja koska hän oli luvannut antaa hänelle ja hänen pojillensa lampun ainiaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Hänen aikanaan edomilaiset luopuivat Juudan vallanalaisuudesta ja asettivat itsellensä kuninkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Niin Jooram lähti sinne päällikköineen ja kaikkine sotavaunuineen. Ja hän nousi yöllä ja voitti edomilaiset, jotka olivat saartaneet hänet, ja sotavaunujen päälliköt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Niin edomilaiset luopuivat Juudan vallanalaisuudesta vapaiksi, aina tähän päivään asti. Siihen aikaan luopui hänen vallanalaisuudestaan myös Libna, koska hän oli hyljännyt Herran, isiensä Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Hänkin teetti uhrikukkuloita Juudan vuoristoon ja saattoi Jerusalemin asukkaat haureuteen ja vietteli Juudan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Mutta profeetta Elialta tuli hänelle tällainen kirjoitus: \"Näin sanoo Herra, sinun isäsi Daavidin Jumala: Koska et ole vaeltanut isäsi Joosafatin teitä etkä Aasan, Juudan kuninkaan, teitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'vaan olet vaeltanut Israelin kuningasten tietä ja saattanut Juudan ja Jerusalemin asukkaat haureuteen, niinkuin Ahabin suku saattoi heidät haureuteen; ja koska myös olet tappanut veljesi, jotka olivat sinun isäsi perhekuntaa ja paremmat kuin sinä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'katso, sentähden Herra rankaisee sinun kansaasi, poikiasi, vaimojasi ja kaikkea, mitä sinulla on, kovalla vitsauksella;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'ja sinä itse olet sairastava vaikeata tautia, sisusvaivaa, kunnes vuoden, parin kuluttua sisuksesi taudin voimasta tunkeutuvat ulos.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'Niin Herra herätti Jooramia vastaan filistealaisten hengen ja niiden arabialaisten hengen, jotka asuivat etiopialaisten naapureina,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'ja he menivät Juudaa vastaan, valloittivat sen ja veivät saaliinaan kaiken tavaran, mitä oli kuninkaan linnassa, niin myöskin hänen poikansa ja vaimonsa, niin ettei hänelle jäänyt muuta poikaa kuin Jooahas, hänen nuorin poikansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'Ja kaiken tämän jälkeen Herra rankaisi häntä parantumattomalla sisusvaivalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'Parin vuoden kuluttua, toisen vuoden lopulla, hänen sisuksensa taudin voimasta tunkeutuivat ulos, ja hän kuoli koviin tuskiin. Mutta hänen kansansa ei polttanut hänen kunniakseen kuolinsuitsutusta, niinkuin oli poltettu hänen isiensä kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Hän oli kolmenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kahdeksan vuotta. Ja hän meni pois kenenkään kaipaamatta, ja hänet haudattiin Daavidin kaupunkiin, mutta ei kuningasten hautoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Jerusalemin asukkaat tekivät Ahasjan, hänen nuorimman poikansa, kuninkaaksi hänen sijaansa; sillä kaikki vanhemmat oli tappanut se rosvojoukko, joka arabialaisten kanssa oli tullut leiriin. Niin tuli Ahasja, Jooramin poika, Juudan kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Ahasja oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa vuoden. Hänen äitinsä oli nimeltään Atalja, Omrin tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Hänkin vaelsi Ahabin suvun teitä, sillä hänen äitinsä oli häntä neuvomassa jumalattomuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Niin hän teki sitä, mikä on pahaa Herran silmissä, samoinkuin Ahabin suku; sillä he olivat hänen isänsä kuoleman jälkeen hänen neuvonantajiaan, hänen turmioksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Heidän neuvostansa hän myös lähti Israelin kuninkaan Jooramin, Ahabin pojan, kanssa taistelemaan Hasaelia, Aramin kuningasta, vastaan Gileadin Raamotiin; mutta aramilaiset haavoittivat Jooramin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'Niin hän tuli takaisin Jisreeliin parantuakseen, sillä hänessä oli haavat, jotka häneen oli isketty Raamassa hänen taistellessaan Hasaelia, Aramin kuningasta, vastaan. Ja Juudan kuningas Ahasja, Jooramin poika, tuli Jisreeliin katsomaan Jooramia, Ahabin poikaa, koska tämä oli sairaana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'Mutta Jumalalta tuli Ahasjan tuhoksi se, että hän meni Jooramin luo. Sillä sinne tultuaan hän meni Jooramin kanssa Jeehua, Nimsin poikaa, vastaan, jonka Herra oli voidellut hävittämään Ahabin sukua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'Ja kun Jeehu oli toimeenpanemassa Ahabin suvun tuomiota, tapasi hän Juudan ruhtinaat ja Ahasjan veljenpojat, jotka palvelivat Ahasjaa, ja tappoi heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Sitten hän etsi Ahasjaa; ja tämä saatiin kiinni Samariassa, jossa hän piileskeli. Niin hänet vietiin Jeehun eteen ja surmattiin. Ja he hautasivat hänet, sillä he sanoivat: \"Hän on Joosafatin poika, hänen, joka kaikesta sydämestänsä etsi Herraa\". Eikä Ahasjan perheessä ollut ketään, joka olisi kyennyt hallitsemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Kun Atalja, Ahasjan äiti, näki, että hänen poikansa oli kuollut, nousi hän ja tuhosi koko Juudan heimon kuningassuvun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Mutta kuninkaan tytär Joosabat otti surmattavain kuninkaan poikien joukosta salaa Ahasjan pojan Jooaan ja pani hänet imettäjineen makuuhuoneeseen. Näin pappi Joojadan vaimo Joosabat, joka oli kuningas Jooramin tytär ja Ahasjan sisar, sai hänet kätketyksi Ataljalta, niin ettei tämä voinut häntä surmauttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'Sitten poika oli heidän luonaan Jumalan temppeliin piilotettuna kuusi vuotta, Ataljan hallitessa maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'Mutta seitsemäntenä vuotena Joojada rohkaisi mielensä ja liittoutui sadanpäämiesten Asarjan, Jerohamin pojan, Ismaelin, Joohananin pojan, Asarjan, Oobedin pojan, Maasejan, Adajan pojan, ja Elisafatin, Sikrin pojan, kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Nämä kiertelivät Juudassa ja kokosivat leeviläiset kaikista Juudan kaupungeista sekä Israelin perhekunta-päämiehet; ja he tulivat Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'Ja koko seurakunta teki Jumalan temppelissä liiton kuninkaan kanssa. Joojada sanoi heille: \"Katso, kuninkaan poika on tuleva kuninkaaksi, niinkuin Herra on puhunut Daavidin pojista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Tehkää näin: Kolmas osa teistä, papeista ja leeviläisistä, joiden on mentävä vartionpitoon sapattina, olkoon ovenvartijoina kynnyksillä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'kolmas osa miehittäköön kuninkaan linnan ja kolmas osa Jesod-portin, ja koko kansa Herran temppelin esikartanot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'Älköön kukaan muu kuin papit ja palvelusta tekevät leeviläiset menkö Herran temppeliin. He saavat mennä sisään, sillä he ovat pyhät, mutta kaikki muu kansa noudattakoon Herran määräystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'Leeviläiset asettukoot kuninkaan ympärille, kullakin ase kädessä; ja joka tunkeutuu temppeliin, se surmattakoon. Näin olkaa kuninkaan luona, menköön hän ulos tai sisään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Leeviläiset ja koko Juuda tekivät kaiken, mitä pappi Joojada oli käskenyt heidän tehdä. Kukin heistä otti miehensä, sekä ne, joiden oli mentävä vartionpitoon sapattina, että ne, jotka pääsivät vartionpidosta sapattina, sillä pappi Joojada ei ollut vapauttanut osastoja palveluksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'Ja pappi Joojada antoi sadanpäämiehille keihäät, kilvet ja varustukset, jotka olivat olleet kuningas Daavidin omat ja olivat Jumalan temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Ja hän asetti koko kansan, kullakin peitsi kädessä, temppelin eteläsivulta aina sen pohjoissivulle saakka, päin alttaria ja temppeliä, kuninkaan ympärille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Sitten he toivat kuninkaan pojan esille, panivat hänen päähänsä kruunun ja antoivat hänelle lain kirjan ja tekivät hänet kuninkaaksi. Ja Joojada ja hänen poikansa voitelivat hänet ja huusivat: \"Eläköön kuningas!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Kun Atalja kuuli kansan huudon, sen juostessa ja huutaessa riemuhuutoja kuninkaalle, meni hän kansan luo Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'Hän näki kuninkaan seisovan korkealla paikallansa sisäänkäytävän luona, ja päälliköt ja torvensoittajat kuninkaan luona, ja kaiken maan kansan, joka riemuitsi ja puhalsi torviin, ja veisaajat, jotka soittimillaan johtivat ylistyslaulua. Silloin Atalja repäisi vaatteensa ja huusi: \"Kapina, kapina!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Mutta pappi Joojada antoi sadanpäämiesten, sotajoukon johtajien, astua esiin ja sanoi heille: \"Viekää hänet pois rivien välitse, ja joka yrittää seurata häntä, se surmattakoon miekalla\". Sillä pappi oli sanonut: \"Älkää surmatko häntä Herran temppelissä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'Niin he kävivät häneen käsiksi, ja kun hän oli tullut kuninkaan linnan Hevosportin sisäänkäytävän luo, surmasivat he hänet siinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Ja Joojada teki liiton hänen itsensä, koko kansan ja kuninkaan kesken, että he olisivat Herran kansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Sitten kaikki kansa meni Baalin temppeliin, ja he hävittivät sen. Sen alttarit ja kuvat he murskasivat, ja he tappoivat alttarien edessä Mattanin, Baalin papin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'Sitten Joojada asetti päällysmiehiä Herran temppeliin, leeviläisiä pappeja, jotka Daavid oli määrännyt Herran temppeliin, uhraamaan Herran polttouhreja, niinkuin on kirjoitettuna Mooseksen laissa, riemuhuudoin ja lauluin, Daavidin järjestelyn mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Ja hän asetti ovenvartijat Herran temppelin porteille, ettei pääsisi sisään kukaan, joka oli jollakin tavalla saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Ja hän otti mukaansa sadanpäämiehet, ylimykset ja kansan hallitusmiehet sekä kaiken maan kansan ja vei kuninkaan Herran temppelistä, ja he tulivat Yläportin kautta kuninkaan linnaan ja asettivat kuninkaan kuninkaalliselle valtaistuimelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'Ja kaikki maan kansa iloitsi, ja kaupunki pysyi rauhallisena. Mutta Ataljan he surmasivat miekalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Jooas oli seitsemän vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa neljäkymmentä vuotta. Hänen äitinsä nimi oli Sibja, Beersebasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'Ja Jooas teki sitä, mikä on oikein Herran silmissä, niin kauan kuin pappi Joojada eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'Ja Joojada otti hänelle kaksi vaimoa, ja hänelle syntyi poikia ja tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'Senjälkeen Jooas aikoi uudistaa Herran temppelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Ja hän kutsui kokoon papit ja leeviläiset ja sanoi heille: \"Menkää Juudan kaupunkeihin ja kootkaa kaikesta Israelista rahaa Jumalanne temppelin korjaamiseksi, vuodesta vuoteen, ja jouduttakaa tätä asiaa\". Mutta leeviläiset eivät jouduttaneet sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Silloin kuningas kutsui luokseen ylimmäisen papin Joojadan ja sanoi hänelle: \"Miksi et ole pitänyt huolta siitä, että leeviläiset toisivat Juudasta ja Jerusalemista Herran palvelijan Mooseksen määräämän Israelin seurakunnan veron lainmajaa varten?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Sillä jumalaton Atalja ja hänen poikansa ovat murtautuneet Jumalan temppeliin; he ovat myös käyttäneet baaleja varten kaikki Herran temppelin pyhät lahjat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Sitten tehtiin kuninkaan käskystä arkku, ja se asetettiin Herran temppelin portin ulkopuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'Ja Juudassa ja Jerusalemissa kuulutettiin, että vero, jonka Jumalan palvelija Mooses oli erämaassa määrännyt Israelille, oli tuotava Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'Kaikki päämiehet ja kaikki kansa toivat iloiten rahaa ja heittivät arkkuun, kunnes se täyttyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'Aina kun leeviläiset toivat arkun kuninkaan asettamien tarkastusmiesten luo, huomattuaan, että siinä oli paljon rahaa, tulivat kuninkaan kirjuri ja ylimmäisen papin käskyläinen tyhjentämään arkun, ja sitten he kantoivat sen takaisin paikoilleen. Niin he tekivät päivä päivältä ja kokosivat paljon rahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Sitten kuningas ja Joojada antoivat sen niille, jotka teettivät työt Herran temppelissä, ja nämä palkkasivat kivenhakkaajia ja puuseppiä uudistamaan Herran temppeliä, niin myös rauta-ja vaskiseppiä korjaamaan Herran temppeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'Ja työnteettäjät toimivat niin, että työ edistyi heidän käsissään, ja he asettivat Jumalan temppelin entiselleen sen määrämittojen mukaan ja panivat sen kuntoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'Ja kun he olivat päättäneet työnsä, veivät he rahan tähteet kuninkaalle ja Joojadalle; ja niillä teetettiin kaluja Herran temppeliin, jumalanpalvelus-ja uhraamiskaluja, kuppeja sekä kulta-ja hopeakaluja. Ja Herran temppelissä uhrattiin vakituisesti polttouhreja, niin kauan kuin Joojada eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Mutta Joojada kävi vanhaksi ja sai elämästä kyllänsä, ja hän kuoli. Sadan kolmenkymmenen vuoden vanha hän oli kuollessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'Ja hänet haudattiin Daavidin kaupunkiin kuningasten joukkoon, sillä hän oli tehnyt sitä, mikä hyvää on, Israelille ja Jumalalle ja hänen temppelilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Mutta Joojadan kuoleman jälkeen tulivat Juudan päämiehet ja kumarsivat kuningasta; ja kuningas kuuli heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Ja he hylkäsivät Herran, isiensä Jumalan, temppelin ja palvelivat aseroita ja jumalankuvia. Niin viha kohtasi Juudaa ja Jerusalemia tämän heidän rikoksensa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Hän lähetti heidän keskuuteensa profeettoja palauttamaan heitä Herran tykö, ja nämä varoittivat heitä, mutta he eivät kuulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Niin Jumalan Henki täytti Sakarjan, pappi Joojadan pojan, ja hän astui kansan eteen ja sanoi heille: \"Näin sanoo Jumala: Miksi te rikotte Herran käskyt omaksi onnettomuudeksenne? Koska te olette hyljänneet Herran, hylkää hänkin teidät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Mutta he tekivät salaliiton häntä vastaan ja kivittivät hänet kuoliaaksi kuninkaan käskystä Herran temppelin esipihalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'Sillä kuningas Jooas ei muistanut rakkautta, jota hänen isänsä Joojada oli hänelle osoittanut, vaan tappoi Joojadan pojan. Ja tämä sanoi kuollessaan: \"Herra nähköön ja kostakoon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'Vuoden vaihteessa kävi aramilaisten sotajoukko Jooaan kimppuun, ja he tunkeutuivat Juudaan ja Jerusalemiin asti ja tuhosivat kansasta kaikki kansan päämiehet. Ja kaiken saaliinsa he lähettivät Damaskon kuninkaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Sillä vaikka aramilaisten sotajoukko tuli vähälukuisena, antoi Herra näiden käsiin hyvin suuren sotajoukon, koska he olivat hyljänneet Herran, isiensä Jumalan. Ja niin nämä panivat toimeen rangaistustuomion Jooaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'Kun he sitten lähtivät häntä ahdistamasta-ja hän jäi heidän lähtiessään hyvin sairaaksi-tekivät hänen palvelijansa salaliiton häntä vastaan pappi Joojadan pojan murhan tähden ja tappoivat hänet hänen vuoteeseensa; ja niin hän kuoli. Ja hänet haudattiin Daavidin kaupunkiin; kuitenkaan ei häntä haudattu kuningasten hautoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'Ne, jotka tekivät salaliiton häntä vastaan, olivat Saabad, ammonilaisen vaimon Simeatin poika, ja Joosabad, mooabilaisen vaimon Simritin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Hänen pojistaan, monista häntä vastaan lausutuista ennustuksista ja Jumalan temppelin uudestaanrakentamisesta, katso, niistä on kirjoitettu Kuningasten kirjan selityskirjaan. Ja hänen poikansa Amasja tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amasja oli kahdenkymmenen viiden vuoden vanha tullessansa kuninkaaksi, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Jooaddan, Jerusalemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'Hän teki sitä, mikä on oikein Herran silmissä, ei kuitenkaan ehyellä sydämellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'Ja kun hänen kuninkuutensa oli vahvistunut, tappoi hän ne palvelijansa, jotka olivat murhanneet kuninkaan, hänen isänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Mutta heidän lapsensa hän jätti surmaamatta: hän teki, niinkuin on kirjoitettu laissa, Mooseksen kirjassa, jossa Herra on käskenyt sanoen: \"Älkööt isät kuolko lasten tähden älköötkä lapset isien tähden; kukin kuolkoon oman syntinsä tähden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Sitten Amasja kokosi Juudan miehet ja asetti heidät perhekunnittain, tuhannen-ja sadanpäämiesten mukaan, koko Juudan ja Benjaminin. Ja hän piti katselmuksen heistä, kaksikymmenvuotiaista ja sitä vanhemmista, ja huomasi heitä olevan kolmesataa tuhatta sotakelpoista, keihästä ja kilpeä käyttävää valiomiestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Lisäksi hän palkkasi Israelista sadalla hopeatalentilla satatuhatta sotaurhoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Mutta Jumalan mies tuli hänen luoksensa ja sanoi: \"Kuningas! Älköön Israelin sotajoukko lähtekö sinun kanssasi, sillä Herra ei ole Israelin, kaikkien näiden efraimilaisten, kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Vaan lähde sinä yksin, käy rohkeasti taisteluun; muutoin Jumala kaataa sinut vihollistesi eteen, sillä Jumalalla on valta auttaa ja kaataa.\" Amasja sanoi Jumalan miehelle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, '\"Mutta miten käy niiden sadan talentin, jotka minä olen antanut Israelin joukolle?\" Jumalan mies vastasi: \"Herra voi antaa sinulle paljon enemmän, kuin se on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Silloin Amasja erotti sen joukon, joka oli tullut hänen luoksensa Efraimista, palaamaan kotiinsa. Siitä he vihastuivat kovin Juudaan ja menivät kotiinsa vihasta hehkuen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Mutta Amasja rohkaisi mielensä, lähti ja vei väkensä Suolalaaksoon ja surmasi seiriläisiä kymmenen tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Ja toiset kymmenen tuhatta Juudan miehet ottivat elävinä vangeiksi. Nämä he veivät kallion laelle ja syöksivät heidät kallion laelta alas, niin että he kaikki ruhjoutuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Mutta ne, jotka kuuluivat Amasjan palauttamaan joukkoon ja jotka eivät olleet päässeet hänen kanssaan sotaan, hyökkäsivät Juudan kaupunkeihin, Samariaan ja aina Beet-Hooroniin saakka; ja he surmasivat asukkaista kolmetuhatta ja ottivat paljon saalista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Kun Amasja, voitettuaan edomilaiset, tuli takaisin, toi hän mukanaan seiriläisten jumalat ja asetti ne itselleen jumaliksi, ja hän kumarsi niitä ja poltti niille uhreja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Niin Herran viha syttyi Amasjaa kohtaan, ja hän lähetti hänen luokseen profeetan; tämä sanoi hänelle: \"Miksi sinä etsit tuon kansan jumalia, jotka eivät voineet pelastaa omaa kansaansa sinun käsistäsi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'Hänen näin hänelle puhuessaan Amasja sanoi hänelle: \"Olemmeko me asettaneet sinut kuninkaan neuvonantajaksi? Herkeä jo, muutoin sinut surmataan.\" Profeetta herkesi ja sanoi: \"Minä tiedän, että Jumala on päättänyt sinut tuhota, koska sinä teet näin etkä kuule minun neuvoani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Amasja, Juudan kuningas, lähetti neuvoteltuaan asiasta Jooaalle, Jooahaan pojalle, Jeehun pojanpojalle, Israelin kuninkaalle, tämän sanan: \"Tule, otelkaamme keskenämme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Mutta Jooas, Israelin kuningas, lähetti Amasjalle, Juudan kuninkaalle tämän sanan: \"Libanonilla kasvava ohdake lähetti setripuulle, joka kasvoi Libanonilla, tämän sanan: \'Anna tyttäresi vaimoksi minun pojalleni\'. Mutta metsän eläimet Libanonilla kulkivat ohdakkeen ylitse ja tallasivat sen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Sinä sanot: \'Katso, minä olen voittanut edomilaiset\', ja olet käynyt ylpeäksi saatuasi kunniaa. Mutta pysy kotonasi; minkätähden tahdot tuottaa onnettomuuden: sinä itse kukistut ja Juuda sinun kanssasi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Mutta Amasja ei totellut; sillä tämä tuli Jumalalta: hän tahtoi antaa heidät alttiiksi, koska he olivat etsineet Edomin jumalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Niin Jooas, Israelin kuningas, lähti liikkeelle, ja he ottelivat keskenään, hän ja Amasja, Juudan kuningas, Beet-Semeksessä, joka on Juudan aluetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'Ja israelilaiset voittivat Juudan miehet, ja nämä pakenivat kukin majallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Ja Jooas, Israelin kuningas, otti Juudan kuninkaan Amasjan, Jooaan pojan, Jooahaan pojanpojan, Beet-Semeksessä vangiksi ja toi hänet Jerusalemiin. Sitten hän revitti Jerusalemin muuria Efraimin portista Kulmaporttiin saakka, neljäsataa kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'Ja hän otti kaiken kullan ja hopean sekä kalut, mitä Herran temppelissä, Oobed-Edomin huostassa oli, ja kuninkaan linnan aarteet ynnä panttivankeja ja palasi Samariaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Mutta Amasja, Jooaan poika, Juudan kuningas, eli Jooaan, Jooahaan pojan, Israelin kuninkaan, kuoleman jälkeen viisitoista vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Mitä muuta on kerrottavaa Amasjan aikaisemmista ja myöhemmistä vaiheista, se on kirjoitettuna Juudan ja Israelin kuningasten kirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'Siitä ajasta alkaen, jolloin Amasja luopui Herrasta, punottiin Jerusalemissa salaliittoa häntä vastaan. Hän pakeni Laakiiseen, mutta Laakiiseen lähetettiin miehiä hänen jälkeensä, ja he surmasivat hänet siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'Hänet nostettiin hevosten selkään ja haudattiin isiensä viereen Juudan kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Mutta koko Juudan kansa otti Ussian, joka oli kuudentoista vuoden vanha, ja teki hänet kuninkaaksi hänen isänsä Amasjan sijaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Hän linnoitti Eelatin ja palautti sen Juudalle, sittenkuin kuningas oli mennyt lepoon isiensä tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Ussia oli kuudentoista vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa viisikymmentä kaksi vuotta. Hänen äitinsä oli nimeltään Jekolja, Jerusalemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Ja hän teki sitä, mikä on oikein Herran silmissä, aivan niinkuin hänen isänsä Amasja oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'Ja hän etsi Jumalaa, niin kauan kuin Sakarja eli, joka ymmärsi Jumalan näkyjä. Ja niin kauan kuin hän etsi Herraa, antoi Jumala hänen menestyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Hän lähti sotimaan filistealaisia vastaan ja revitti Gatin, Jabnen ja Asdodin muurit; ja hän rakennutti kaupunkeja Asdodin alueelle ja muualle filistealaisten maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Ja Jumala auttoi häntä filistealaisia vastaan ja niitä arabialaisia vastaan, jotka asuivat Guur-Baalissa, sekä meunilaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'Ja ammonilaiset maksoivat veroa Ussialle, ja hänen maineensa levisi aina Egyptiin saakka, sillä hän tuli ylen mahtavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'Ussia rakennutti Jerusalemiin tornit Kulmaportin ja Laaksoportin päälle ja Kulmauksen päälle ja varusti ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Hän rakennutti torneja myös erämaahan ja hakkautti paljon vesisäiliöitä, sillä hänellä oli paljon karjaa sekä Alankomaassa että ylätasangolla. Peltomiehiä ja viinitarhureita hänellä oli vuoristossa ja puutarhamailla, sillä hän harrasti maanviljelystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Ja Ussialla oli sotajoukko, joka teki sotapalvelusta ja lähti sotaan osastoittain, sen lukumäärän mukaan, mikä heitä oli katselmuksessa, jonka kirjuri Jegiel ja päällysmies Maaseja olivat toimittaneet Hananjan, kuninkaallisen päällikön, johdolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Perhekunta-päämiesten, sotaurhojen, koko lukumäärä oli kaksituhatta kuusisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'Heidän johdossaan oli kolmensadan seitsemän tuhannen viidensadan miehen suuruinen sotajoukko, joka teki väellä ja voimalla sotapalvelusta auttaakseen kuningasta vihollista vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'Ja Ussia varusti heidät, koko sotajoukon, kilvillä, keihäillä, kypäreillä, rintahaarniskoilla, jousilla ja linkokivillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Ja hän teetti Jerusalemiin taidokkaasti sommiteltuja sotakoneita, jotka asetettiin torneihin ja muurien kulmiin ja joilla ammuttiin nuolia ja suuria kiviä. Niin hänen maineensa levisi kauas, sillä hän sai ihmeteltävästi apua, kunnes hän tuli mahtavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Mutta kun hän oli tullut mahtavaksi, ylpistyi hänen sydämensä, niin että hän teki kelvottoman teon, hän tuli uskottomaksi Herraa, Jumalaansa, kohtaan ja meni Herran temppeliin, suitsutusalttarille, suitsuttamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'Niin pappi Asarja meni hänen jälkeensä sinne, mukanaan kahdeksankymmentä Herran pappia, rohkeita miehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'Nämä astuivat kuningas Ussiaa vastaan ja sanoivat hänelle: \"Ei ole sinun asiasi, Ussia, suitsuttaa Herralle, vaan pappien, Aaronin poikien, jotka ovat pyhitetyt suitsuttamaan. Mene ulos pyhäköstä, sillä sinä olet ollut uskoton, eikä siitä tule sinulle kunniaa Herralta Jumalalta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Niin Ussia vihastui, ja hän piti juuri suitsutusastiaa kädessään suitsuttaaksensa. Mutta kun hän vihastui pappeihin, puhkesi hänen otsaansa pitali pappien läsnäollessa Herran temppelissä, suitsutusalttarin ääressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'Ja kun ylimmäinen pappi Asarja ja kaikki muut papit kääntyivät hänen puoleensa, niin katso, hänellä oli pitali otsassa. Silloin he äkisti karkoittivat hänet sieltä, ja itsekin hän kiiruusti lähti pois, kun Herra oli häntä lyönyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'Niin kuningas Ussia tuli pitalitautiseksi kuolinpäiväänsä saakka ja asui pitalitautisena eri talossa, sillä hän oli eristetty Herran temppelistä. Hänen poikansa Jootam hallitsi kuninkaan linnaa ja tuomitsi maan kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'Mitä muuta on kerrottavaa Ussiasta, hänen aikaisemmista ja myöhemmistä vaiheistaan, sen on profeetta Jesaja, Aamoksen poika, pannut kirjaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'Ja Ussia meni lepoon isiensä tykö, ja hänet haudattiin isiensä viereen vainioon, kuningasten hautojen ääreen; sanottiin näet: \"Hän on pitalitautinen\". Ja hänen poikansa Jootam tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jootam oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kuusitoista vuotta. Hänen äitinsä nimi oli Jerusa, Saadokin tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'Hän teki sitä, mikä on oikein Herran silmissä, aivan niinkuin hänen isänsä Ussia oli tehnyt, paitsi ettei hän tunkeutunut Herran temppeliin. Mutta kansa yhä vaelsi kelvottomasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'Hän rakennutti Yläportin Herran temppeliin ja rakennutti paljon Oofelin muuria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Hän rakennutti myös kaupunkeja Juudan vuoristoon, ja metsiin hän rakennutti linnoja ja torneja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Hän kävi sotaa ammonilaisten kuningasta vastaan ja voitti heidät; ja ammonilaiset antoivat hänelle sinä vuonna sata talenttia hopeata, kymmenentuhatta koor-mittaa nisuja ja kymmenentuhatta koor-mittaa ohria. Tämän ammonilaiset suorittivat hänelle myöskin toisena ja kolmantena vuotena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Niin Jootam tuli yhä mahtavammaksi, koska hän vaelsi vakaasti Herran, Jumalansa, edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Mitä muuta on kerrottavaa Jootamista ja kaikista hänen sodistaan ja hänen vaelluksestansa, katso, se on kirjoitettuna Israelin ja Juudan kuningasten kirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Hän oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kuusitoista vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Ja Jootam meni lepoon isiensä tykö, ja hänet haudattiin Daavidin kaupunkiin. Ja hänen poikansa Aahas tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Aahas oli kahdenkymmenen vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kuusitoista vuotta. Hän ei tehnyt sitä, mikä on oikein Herran silmissä, niinkuin hänen isänsä Daavid,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'vaan vaelsi Israelin kuningasten teitä; jopa hän teki valettuja kuvia baaleille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Ja hän poltti uhreja Ben-Hinnomin laaksossa ja poltti poikansa tulessa, niiden kansain kauhistavien tekojen mukaan, jotka Herra oli karkoittanut israelilaisten tieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Ja hän teurasti ja poltti uhreja uhrikukkuloilla ja kummuilla ja jokaisen viheriän puun alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Sentähden Herra, hänen Jumalansa, antoi hänet Aramin kuninkaan käsiin. He voittivat hänet ja ottivat hänen väestään suuren joukon vangiksi ja veivät Damaskoon. Hänet annettiin myöskin Israelin kuninkaan käsiin, ja tämä tuotti hänelle suuren tappion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Pekah, Remaljan poika, surmasi Juudasta satakaksikymmentä tuhatta yhtenä päivänä, kaikki sotakuntoisia miehiä, koska he olivat hyljänneet Herran, isiensä Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Ja Sikri, efraimilainen urho, tappoi kuninkaan pojan Maasejan, linnan esimiehen Asrikamin ja kuninkaan lähimmän miehen Elkanan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Ja israelilaiset veivät veljiltään vangeiksi vaimoja, poikia ja tyttäriä kaksisataa tuhatta, ryöstivät heiltä myös paljon saalista ja veivät saaliin Samariaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Siellä oli Herran profeetta nimeltä Ooded; tämä meni sotajoukkoa vastaan, kun se oli tulossa Samariaan, ja sanoi heille: \"Katso, Herra, teidän isienne Jumala, on vihastunut Juudaan ja antanut heidät teidän käsiinne, ja te olette tappaneet heitä raivossa, joka ulottuu taivaaseen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'Ja nyt te ajattelette pakottaa tämän Juudan väen ja Jerusalemin orjiksenne ja orjattariksenne. Eikö teillä jo ole tunnollanne kyllin rikkomuksia Herraa, Jumalaanne, vastaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Niin kuulkaa nyt minua ja palauttakaa vangit, jotka olette ottaneet veljienne joukosta; sillä Herran vihan hehku on teidän päällänne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Silloin muutamat efraimilaisten päämiehistä, Asarja, Joohananin poika, Berekia, Mesillemotin poika, Hiskia, Sallumin poika, ja Amasa, Hadlain poika, nousivat sotaretkeltä tulevia vastaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'ja sanoivat heille: \"Älkää tuoko tänne noita vankeja, sillä te saatatte meidät syyllisiksi Herran edessä, kun ajattelette lisätä meidän syntejämme ja syyllisyyttämme. Onhan meidän syyllisyytemme jo suuri, ja vihan hehku on Israelin päällä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Silloin aseväki luopui vangeista ja saaliista päämiesten ja koko seurakunnan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'Ja nimeltä mainitut miehet nousivat ja ottivat huostaansa vangit ja antoivat saaliista vaatteita kaikille heidän joukossaan, jotka olivat alasti. He antoivat näille vaatteita ja kenkiä, ruokaa ja juomaa, voitelivat heitä ja toimittivat heille, kaikille uupuneille, aasit ja veivät heidät Jerikoon, Palmukaupunkiin, lähelle heidän veljiänsä. Sitten he palasivat Samariaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Siihen aikaan kuningas Aahas lähetti sanansaattajat Assurin kuningasten tykö saadaksensa apua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Sillä vielä edomilaisetkin olivat tulleet ja voittaneet Juudan ja ottaneet vankeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Ja filistealaiset olivat tehneet ryöstöretken Alankomaan ja Juudan Etelämaan kaupunkeihin ja valloittaneet Beet-Semeksen, Aijalonin ja Gederotin, niin myös Sookon ja sen tytärkaupungit, Timran ja sen tytärkaupungit ja Gimson ja sen tytärkaupungit, ja he olivat asettuneet niihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Sillä Herra nöyryytti Juudaa Aahaan, Israelin kuninkaan, tähden, koska tämä oli harjoittanut kurittomuutta Juudassa ja ollut uskoton Herraa kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'Niin Tillegat-Pilneser, Assurin kuningas, lähti häntä vastaan ja ahdisti häntä eikä tukenut häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Sillä vaikka Aahas ryösti Herran temppeliä ja kuninkaan ja päämiesten linnoja ja antoi kaiken Assurin kuninkaalle, ei hänellä ollut siitä apua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'Silloinkin kun häntä ahdistettiin, oli hän, kuningas Aahas, edelleen uskoton Herraa kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Sillä hän uhrasi Damaskon jumalille, jotka olivat voittaneet hänet; hän ajatteli: \"Koska Aramin kuningasten jumalat ovat auttaneet heitä, uhraan minäkin niille, että ne minuakin auttaisivat\". Mutta ne tulivatkin hänelle ja koko Israelille lankeemukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Ja Aahas kokosi Jumalan temppelin kalut ja hakkasi Jumalan temppelin kalut kappaleiksi. Hän sulki Herran temppelin ovet ja teetti itselleen alttareita Jerusalemin joka kolkkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Ja jokaiseen Juudan kaupunkiin hän teetti uhrikukkuloita polttaakseen uhreja muille jumalille; ja niin hän vihoitti Herran, isiensä Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Mitä muuta on kerrottavaa hänestä ja kaikesta hänen vaelluksestaan, sekä aikaisemmasta että myöhemmästä, katso, se on kirjoitettuna Juudan ja Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'Ja Aahas meni lepoon isiensä tykö, ja hänet haudattiin kaupunkiin, Jerusalemiin; sillä häntä ei viety Israelin kuningasten hautoihin. Ja hänen poikansa Hiskia tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Hiskia tuli kuninkaaksi kahdenkymmenen viiden vuoden vanhana, ja hän hallitsi Jerusalemissa kaksikymmentä yhdeksän vuotta. Hänen äitinsä oli nimeltään Abia, Sakarjan tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'Hän teki sitä, mikä on oikein Herran silmissä, aivan niinkuin hänen isänsä Daavid oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Ensimmäisenä hallitusvuotenansa, sen ensimmäisessä kuussa, hän avasi Herran temppelin ovet ja korjasi ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'Sitten hän tuotti papit ja leeviläiset ja kokosi ne idässäpäin olevalle aukealle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'Ja hän sanoi heille: \"Kuulkaa minua, te leeviläiset! Pyhittäytykää nyt ja pyhittäkää Herran, isienne Jumalan, temppeli ja toimittakaa saastaisuus pois pyhäköstä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Sillä meidän isämme ovat olleet uskottomia ja tehneet sitä, mikä on pahaa Herran, meidän Jumalamme, silmissä, ja hyljänneet hänet. He käänsivät kasvonsa pois Herran asumuksesta ja käänsivät sille selkänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'He myöskin sulkivat eteisen ovet, sammuttivat lamput, eivät polttaneet suitsuketta eivätkä uhranneet polttouhreja pyhäkössä Israelin Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Sentähden Herran viha on kohdannut Juudaa ja Jerusalemia, ja hän on tehnyt heidät kauhuksi, hämmästykseksi ja pilkaksi, niinkuin te omin silmin näette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Katso, meidän isämme ovat kaatuneet miekkaan, ja meidän poikamme, tyttäremme ja vaimomme ovat joutuneet vankeuteen tästä syystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Nyt minä aion tehdä liiton Herran, Israelin Jumalan, kanssa, että hänen vihansa hehku kääntyisi meistä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Älkää siis, lapseni, olko leväperäisiä, sillä teidät Herra on valinnut seisomaan hänen edessänsä ja palvelemaan häntä, olemaan hänen palvelijansa ja suitsuttamaan hänelle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Silloin nousivat leeviläiset: Mahat, Amasain poika, ja Jooel, Asarjan poika, Kehatin jälkeläisistä; Merarin jälkeläisistä Kiis, Abdin poika, ja Asarja, Jehallelelin poika; geersonilaisista Jooah, Simman poika, ja Eeden, Jooahin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'Elisafanin jälkeläisistä Simri ja Jegiel; Aasafin jälkeläisistä Sakarja ja Mattanja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'Heemanin jälkeläisistä Jehiel ja Siimei; ja Jedutunin jälkeläisistä Semaja ja Ussiel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'Nämä kokosivat veljensä, pyhittäytyivät ja menivät, niinkuin kuningas oli Herran sanan mukaan käskenyt, puhdistamaan Herran temppeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'Mutta papit menivät sisälle Herran temppeliin puhdistamaan sitä, ja kaiken saastaisuuden, minkä löysivät Herran temppelistä, he veivät Herran temppelin esipihalle; sieltä leeviläiset ottivat sen ja veivät sen ulos Kidronin laaksoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'He alkoivat pyhittämisen ensimmäisen kuun ensimmäisenä päivänä, ja kuukauden kahdeksantena päivänä he olivat ehtineet Herran eteiseen, ja he pyhittivät Herran temppeliä kahdeksan päivää; ensimmäisen kuun kuudentenatoista päivänä he lopettivat työnsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Silloin he menivät sisälle kuningas Hiskian tykö ja sanoivat: \"Me olemme puhdistaneet koko Herran temppelin, polttouhrialttarin ja kaikki sen kalut ja näkyleipäpöydän ja kaikki sen kalut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Kaikki kalut, jotka kuningas Aahas hallitusaikanansa uskottomuudessaan saastutti, me olemme panneet kuntoon ja pyhittäneet, ja katso, ne ovat Herran alttarin edessä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Kuningas Hiskia kokosi varhain aamulla kaupungin päämiehet ja meni Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'Ja he toivat seitsemän härkää, seitsemän oinasta ja seitsemän karitsaa sekä seitsemän kaurista syntiuhriksi valtakunnan puolesta, pyhäkön puolesta ja Juudan puolesta. Ja hän käski pappi Aaronin poikien, pappien, uhrata ne Herran alttarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Sitten he teurastivat raavaat, ja papit ottivat veren ja vihmoivat sen alttarille; ja he teurastivat oinaat ja vihmoivat veren alttarille; sitten he teurastivat karitsat ja vihmoivat veren alttarille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Senjälkeen he toivat syntiuhrikauriit kuninkaan ja seurakunnan eteen, ja nämä laskivat kätensä niiden päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'Ja papit teurastivat ne ja uhrasivat niiden veren syntiuhrina alttarilla, toimittaen koko Israelille sovituksen; sillä kuningas oli käskenyt uhrata polttouhrin ja syntiuhrin koko Israelin puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Ja hän asetti leeviläiset Herran temppeliin, kymbaalit, harput ja kanteleet käsissä, niinkuin Daavid ja kuninkaan näkijä Gaad ja profeetta Naatan olivat käskeneet; sillä käsky oli Herran antama hänen profeettainsa kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'Niin leeviläiset seisoivat siinä, Daavidin soittimet käsissä, ja papit, torvet käsissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'Ja Hiskia käski uhrata alttarilla polttouhrin; ja kun uhraaminen alkoi, alkoi myöskin Herran veisu ja torvien soitto Daavidin, Israelin kuninkaan, soittimien johtaessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Koko seurakunta kumartaen rukoili, veisu kaikui, ja torvet soivat-kaikkea tätä kesti, kunnes polttouhri oli uhrattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'Kun uhraaminen oli päättynyt, polvistuivat kuningas ja kaikki, jotka olivat hänen kanssaan saapuvilla, kumartaen rukoilemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Ja kuningas Hiskia ja päämiehet käskivät leeviläisten ylistää Herraa Daavidin ja näkijä Aasafin sanoilla; ja nämä ylistivät häntä iloiten, polvistuivat ja kumartaen rukoilivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Sitten Hiskia lausui ja sanoi: \"Nyt te olette tuoneet täysin käsin lahjoja Herralle; astukaa esille ja tuokaa teurasuhreja ja kiitosuhreja Herran temppeliin\". Silloin seurakunta toi teurasuhreja ja kiitosuhreja, ja jokainen, jonka sydän häntä siihen vaati, myöskin polttouhreja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'Ja seurakunnan tuomien polttouhrien lukumäärä oli seitsemänkymmentä raavasta, sata oinasta ja kaksisataa karitsaa, nämä kaikki polttouhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Ja pyhiä lahjoja oli kuusisataa raavasta ja kolmetuhatta lammasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Mutta pappeja oli niin vähän, etteivät he voineet nylkeä kaikkia polttouhriteuraita; sentähden heidän veljensä leeviläiset auttoivat heitä, kunnes tämä työ oli suoritettu ja kunnes papit olivat pyhittäytyneet, sillä leeviläiset pyrkivät vilpittömämmin kuin papit pyhittäytymään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Myöskin polttouhreja oli paljon ynnä yhteysuhrirasvoja ja polttouhriin kuuluvia juomauhreja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'Näin järjestettiin palvelus Herran temppelissä. Ja Hiskia ja kaikki kansa iloitsivat siitä, mitä Jumala oli kansalle valmistanut, sillä se oli tapahtunut äkisti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Hiskia lähetti sanansaattajat kaikkeen Israeliin ja Juudaan ja kirjoitti myös kirjeet Efraimiin ja Manasseen, että he tulisivat Herran temppeliin Jerusalemiin viettämään pääsiäistä Herran, Israelin Jumalan, kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Ja kuningas, hänen päämiehensä ja kaikki Jerusalemin seurakunta päättivät viettää pääsiäistä toisessa kuussa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'sillä he eivät voineet viettää sitä silloin heti, koska pappeja ei ollut pyhittäytynyt riittävää määrää eikä kansa ollut kokoontunut Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'Tämä kelpasi kuninkaalle ja kaikelle seurakunnalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'ja niin he päättivät kuuluttaa koko Israelissa Beersebasta Daaniin saakka, että oli tultava Jerusalemiin viettämään pääsiäistä Herran, Israelin Jumalan, kunniaksi. Sillä sitä ei oltu vietetty joukolla, niinkuin kirjoitettu oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Juoksijat kulkivat, mukanaan kuninkaan ja hänen päämiestensä kirjeet, halki koko Israelin ja Juudan ja julistivat kuninkaan käskystä: \"Te israelilaiset, palatkaa Herran, Aabrahamin, Iisakin ja Israelin Jumalan, tykö, että hän palajaisi niiden tykö, jotka teistä ovat säilyneet ja pelastuneet Assurin kuningasten käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'Älkää olko niinkuin teidän isänne ja veljenne, jotka olivat uskottomat Herralle, isiensä Jumalalle, niin että hän antoi teidät häviön omiksi, niinkuin te itse näette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Älkää siis olko niskureita niinkuin teidän isänne; ojentakaa kätenne Herralle ja tulkaa hänen pyhäkköönsä, jonka hän on pyhittänyt ikuisiksi ajoiksi, ja palvelkaa Herraa, teidän Jumalaanne, että hänen vihansa hehku kääntyisi teistä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Sillä jos te palajatte Herran tykö, saavat teidän veljenne ja poikanne osakseen laupeuden voittajiltaan ja voivat palata takaisin tähän maahan. Sillä Herra, teidän Jumalanne, on armollinen ja laupias, eikä hän käännä kasvojansa pois teistä, jos te palajatte hänen tykönsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'Ja juoksijat kulkivat kaupungista kaupunkiin Efraimin ja Manassen maassa ja aina Sebuloniin saakka. Mutta heille naurettiin ja heitä pilkattiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Kuitenkin Asserista, Manassesta ja Sebulonista muutamat nöyrtyivät ja tulivat Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Myöskin Juudassa vaikutti Jumalan käsi, ja hän antoi heille yksimielisen sydämen tekemään, mitä kuningas ja päämiehet olivat Herran sanan mukaan käskeneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Niin kokoontui paljon kansaa Jerusalemiin viettämään happamattoman leivän juhlaa toisessa kuussa. Se oli hyvin suuri kokous.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Ja he nousivat ja poistivat alttarit Jerusalemista. Myös kaikki suitsutusalttarit he poistivat ja heittivät Kidronin laaksoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Sitten he teurastivat pääsiäislampaan toisen kuun neljäntenätoista päivänä. Ja papit ja leeviläiset häpesivät ja pyhittäytyivät ja toivat polttouhreja Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'Ja he asettuivat paikoilleen, niinkuin heidän velvollisuutensa oli Jumalan miehen Mooseksen lain mukaan. Papit vihmoivat veren, otettuaan sen leeviläisten käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Sillä seurakunnassa oli monta, jotka eivät olleet pyhittäytyneet; niin leeviläiset huolehtivat pääsiäislammasten teurastamisesta kaikille, jotka eivät olleet puhtaita, ja niiden pyhittämisestä Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Sillä suurin osa kansasta, monet Efraimista ja Manassesta, Isaskarista ja Sebulonista, eivät olleet puhdistautuneet, vaan söivät pääsiäislampaan toisin, kuin kirjoitettu oli. Hiskia oli näet rukoillut heidän puolestaan sanoen: \"Herra, joka on hyvä, antakoon anteeksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'jokaiselle, joka on kiinnittänyt sydämensä Jumalan, Herran, isiensä Jumalan, etsimiseen, vaikka onkin pyhäkköpuhtautta vailla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'Ja Herra kuuli Hiskiaa ja säästi kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Niin israelilaiset, jotka olivat Jerusalemissa, viettivät seitsemän päivää happamattoman leivän juhlaa iloiten suuresti. Ja leeviläiset ja papit ylistivät joka päivä Herraa voimakkailla soittimilla, Herran kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'Ja Hiskia puhutteli ystävällisesti kaikkia leeviläisiä, jotka taitavasti suorittivat tehtävänsä Herran kunniaksi. Ja he söivät seitsemän päivää juhlauhreja ja uhrasivat yhteysuhreja ja ylistivät Herraa, isiensä Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Ja koko seurakunta päätti viettää juhlaa vielä toiset seitsemän päivää; ja niin vietettiin ilojuhlaa vielä seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Sillä Hiskia, Juudan kuningas, oli antanut seurakunnalle anniksi tuhat härkää ja seitsemän tuhatta lammasta, ja päämiehet olivat antaneet seurakunnalle anniksi tuhat härkää ja kymmenen tuhatta lammasta. Ja paljon pappeja pyhittäytyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'Niin koko Juudan seurakunta iloitsi ja samoin papit ja leeviläiset ja koko Israelista tullut seurakunta, niin myös muukalaiset, jotka olivat tulleet Israelin maasta tai asuivat Juudassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'Ja Jerusalemissa oli ilo suuri, sillä Israelin kuninkaan Salomon, Daavidin pojan, ajoista asti ei sellaista ollut tapahtunut Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Ja leeviläiset papit nousivat ja siunasivat kansan; ja heidän äänensä tuli kuulluksi, ja heidän rukouksensa tuli Herran pyhään asumukseen, taivaaseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'Kun kaikki tämä oli päättynyt, lähtivät kaikki saapuvilla olevat israelilaiset Juudan kaupunkeihin ja murskasivat patsaat, hakkasivat maahan asera-karsikot ja kukistivat uhrikukkulat ja alttarit perinpohjin koko Juudassa, Benjaminissa, Efraimissa ja Manassessa. Sitten kaikki israelilaiset palasivat kukin perintömaallensa, kaupunkeihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Ja Hiskia asetti pappien ja leeviläisten osastot, heidän osastojensa mukaan, kunkin hänen papillisen tai leeviläisen palvelustehtävänsä mukaan, polttouhreja ja yhteysuhreja toimitettaessa palvelemaan, kiittämään ja ylistämään Herran leirin porteissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Minkä kuningas antoi omaisuudestaan, se käytettiin polttouhreiksi, aamu-ja ehtoopolttouhreiksi sekä sapatteina, uudenkuun päivinä ja juhlina uhrattaviksi polttouhreiksi, niinkuin on kirjoitettuna Herran laissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Ja hän käski kansan, Jerusalemin asukasten, antaa papeille ja leeviläisille heidän osuutensa, että nämä pitäisivät kiinni Herran laista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'Kun tämä sana levisi, antoivat israelilaiset runsaat uutiset jyvistä, viinistä, öljystä ja hunajasta ja kaikesta pellon sadosta; he toivat runsaat kymmenykset kaikesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Ja ne israelilaiset ja Juudan miehet, jotka asuivat Juudan kaupungeissa, toivat hekin kymmenykset raavaista ja pikkukarjasta sekä kymmenykset Herralle, Jumalallensa, pyhitetyistä pyhistä lahjoista, ja panivat ne eri kasoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Kolmannessa kuussa he alkoivat panna kasoihin, ja seitsemännessä kuussa he sen lopettivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Kun Hiskia ja päämiehet tulivat ja näkivät kasat, kiittivät he Herraa ja hänen kansaansa Israelia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Ja kun Hiskia kysyi papeilta ja leeviläisiltä näistä kasoista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'vastasi hänelle ylimmäinen pappi Asarja, joka oli Saadokin sukua, ja sanoi: \"Siitä alkaen, kun ruvettiin tuomaan antia Herran temppeliin, me olemme syöneet ja tulleet ravituiksi, ja kuitenkin on jäänyt paljon tähteeksi; sillä Herra on siunannut kansaansa, ja niin on tämä paljous jäänyt tähteeksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Niin Hiskia käski laittaa kammioita Herran temppeliin. Ja kun ne oli laitettu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'tuotiin niihin tunnollisesti anti, kymmenys ja pyhät lahjat. Ja niiden esimiehenä oli leeviläinen Koonanja, ja hänen veljensä Siimei oli häntä lähinnä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Ja Jehiel, Asasja, Nahat, Asael, Jerimot, Joosabat, Eliel, Jismakja, Mahat ja Benaja olivat Koonanjan ja hänen veljensä Siimein käskyläisinä kuningas Hiskian ja Asarjan, Jumalan temppelin esimiehen, määräyksestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Ja leeviläinen Koore, Jimnan poika, joka oli ovenvartijana idän puolella, hoiti Jumalalle annetut vapaaehtoiset lahjat ja Herralle tulevan annin ja korkeasti-pyhäin lahjain suorituksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'Ja hänen johdossaan olivat Eedem, Minjamin, Jeesua, Semaja, Amarja ja Sekanja, joiden oli pappiskaupungeissa tunnollisesti suoritettava osuudet veljillensä, niin pienille kuin suurille, osastoittain,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'paitsi sukuluetteloihin merkityille miehenpuolille, kolmivuotiaille ja sitä vanhemmille, kaikille, jotka menivät Herran temppeliin tekemään palvelusta, kunakin päivänä sen päivän palveluksen, hoitamaan tehtäviään, osastoittain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'Papit merkittiin sukuluetteloihin perhekunnittain ja leeviläisistä kaksikymmenvuotiaat ja sitä vanhemmat, palvelustehtäviensä mukaan, osastoittain,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'nimittäin niin, että sukuluetteloihin merkittiin kaikki heidän pienet lapsensa, vaimonsa, poikansa ja tyttärensä, koko heidän joukkonsa, sillä he hoitivat sitä, mikä pyhää oli, tunnollisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Aaronin pojilla, papeilla, jotka asuivat kaupunkiensa laidunmailla, oli joka kaupungissa nimeltä mainitut miehet, joiden oli suoritettava osuudet kaikille miehenpuolille pappien joukossa ja kaikille sukuluetteloihin merkityille leeviläisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'Näin Hiskia teki koko Juudassa; hän teki sitä, mikä oli hyvää, oikeata ja totta Herran, hänen Jumalansa, edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'Ja kaiken, mihin hän ryhtyi etsiessään Jumalaansa, koskipa se palvelusta Jumalan temppelissä tai lakia ja käskyjä, sen hän teki kaikesta sydämestänsä, ja hän menestyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Näiden tapausten ja Hiskian vakaan vaelluksen jälkeen tuli Sanherib, Assurin kuningas, ja hyökkäsi Juudaan, piiritti sen varustettuja kaupunkeja ja aikoi valloittaa ne itsellensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'Kun Hiskia näki Sanheribin tulevan ja olevan aikeessa sotia Jerusalemia vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'neuvotteli hän päämiestensä ja urhojensa kanssa tukkiaksensa vesilähteet, jotka olivat kaupungin ulkopuolella; ja he kannattivat häntä siinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Niin kokoontui paljon kansaa, ja he tukkivat kaikki lähteet ja puron, joka juoksee sen seudun läpi; sillä he sanoivat: \"Miksi Assurin kuninkaat tultuansa löytäisivät vettä viljalti?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'Ja hän rohkaisi mielensä, rakensi koko revityn osan muuria ja korotti torneja ja teki sen ulkopuolelle toisen muurin, varusti Millon Daavidin kaupungissa ja teetti paljon heittoaseita ja kilpiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Ja hän asetti sotapäälliköitä kansalle ja kokosi heidät luoksensa aukealle kaupungin portin eteen ja puhui ystävällisesti heille ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '\"Olkaa lujat ja rohkeat, älkää peljätkö älkääkä arkailko Assurin kuningasta ja kaikkea joukkoa, joka on hänen kanssansa; sillä se, joka on meidän kanssamme, on suurempi kuin se, joka on hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Hänen kanssansa on lihan käsivarsi, mutta meidän kanssamme on Herra, meidän Jumalamme, meitä auttamassa ja meidän sotiamme sotimassa.\" Ja kansa luotti Hiskian, Juudan kuninkaan, sanoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Tämän jälkeen Sanherib, Assurin kuningas, ollessaan itse koko sotavoimansa kanssa Laakiin edustalla, lähetti palvelijoitansa Jerusalemiin Hiskian, Juudan kuninkaan, luo ja kaikkien Jerusalemissa olevien Juudan miesten luo ja käski sanoa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, '\"Näin sanoo Sanherib, Assurin kuningas: Mihin te luotatte, kun jäätte Jerusalemiin saarroksiin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Eikö Hiskia viettele teitä ja saata teitä kuolemaan nälkään ja janoon, kun hän sanoo: Herra, meidän Jumalamme, pelastaa meidät Assurin kuninkaan käsistä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Eikö tämä sama Hiskia ole poistanut hänen uhrikukkuloitansa ja alttareitansa ja sanonut Juudalle ja Jerusalemille näin: \'Yhden ainoan alttarin edessä on teidän kumartaen rukoiltava ja sillä uhreja poltettava\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Ettekö tiedä, mitä minä ja minun isäni olemme tehneet muiden maiden kaikille kansoille? Ovatko näiden maiden kansain jumalat voineet pelastaa maatansa minun käsistäni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Onko kukaan minun isieni tuhoamien kansojen kaikista jumalista voinut pelastaa kansaansa minun käsistäni? Kuinka sitten teidän Jumalanne voisi pelastaa teidät minun käsistäni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Älkää siis antako Hiskian näin pettää ja vietellä itseänne älkääkä uskoko häntä, sillä ei minkään kansan eikä minkään valtakunnan jumala ole voinut pelastaa kansaansa minun käsistäni tai minun isieni käsistä, saati sitten teidän Jumalanne: ei hän pelasta teitä minun käsistäni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Ja hänen palvelijansa puhuivat vielä enemmän Herraa Jumalaa ja hänen palvelijaansa Hiskiaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Hän kirjoitti myös kirjeen herjatakseen Herraa, Israelin Jumalaa, ja puhuakseen häntä vastaan; siinä sanottiin näin: \"Niinkuin muiden maiden kansain jumalat eivät ole pelastaneet kansojansa minun käsistäni, niin ei Hiskiankaan Jumala ole pelastava kansaansa minun käsistäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'Ja Jerusalemin kansalle, jota oli muurilla, he huusivat kovalla äänellä juudankielellä nostaakseen heissä pelon ja kauhun, että saisivat kaupungin valloitetuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'Ja he puhuivat Jerusalemin Jumalasta niinkuin muiden maiden kansain jumalista, jotka ovat ihmiskätten tekoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Mutta kuningas Hiskia ja profeetta Jesaja, Aamoksen poika, rukoilivat tämän tähden ja huusivat taivaan puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'Silloin Herra lähetti enkelin, joka tuhosi kaikki sotaurhot, ruhtinaat ja päälliköt Assurin kuninkaan leirissä, niin että hän häpeä kasvoillaan palasi takaisin maahansa. Ja kun hän kerran meni jumalansa temppeliin, kaatoivat hänet siellä miekalla ne, jotka olivat lähteneet hänen omasta ruumiistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Näin Herra vapahti Hiskian ja Jerusalemin asukkaat Sanheribin, Assurin kuninkaan, käsistä ja kaikkien käsistä, ja hän johdatti heitä joka taholla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Ja monet toivat Herralle lahjoja Jerusalemiin ja Hiskialle, Juudan kuninkaalle, kalleuksia; ja hän kohosi sen jälkeen kaikkien kansojen silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'Niihin aikoihin Hiskia sairastui ja oli kuolemaisillaan. Niin hän rukoili Herraa, ja hän vastasi hänelle ja antoi hänelle tapahtua ihmeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Mutta Hiskia ei palkinnut hyvää hyvällä, vaan hänen sydämensä ylpistyi; sentähden hänen ja Juudan ja Jerusalemin osaksi tuli viha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Mutta kun Hiskia nöyrtyi sydämensä ylpeydestä, hän ja Jerusalemin asukkaat, ei Herran viha kohdannut heitä Hiskian päivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'Hiskialle tuli ylen paljon rikkautta ja kunniaa; hän hankki itselleen aarrekammioita hopeata, kultaa, kalliita kiviä, hajuaineita, kilpiä ja kaikkinaisia kallisarvoisia kaluja varten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'varastohuoneita jyvä-,viini-ja öljysatoa varten ja talleja kaikenlaisille juhdille ja karjalaumoja tarhoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Myös rakennutti hän itsellensä kaupunkeja ja hankki suuret laumat pikkukarjaa ja raavaskarjaa, sillä Jumala oli antanut hänelle ylen suuren omaisuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Hiskia myös tukki Giihonin veden yläjuoksun ja johti veden alas, länteenpäin, Daavidin kaupunkiin. Ja Hiskia menestyi kaikessa, mitä hän teki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Niinpä Jumala ainoastaan koetellakseen häntä ja tullakseen tuntemaan kaiken, mitä hänen sydämessään oli, jätti hänet Baabelin ruhtinasten lähettiläiden valtaan, jotka olivat lähetetyt hänen luokseen tiedustelemaan ihmettä, joka oli tapahtunut maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Mitä muuta on kerrottavaa Hiskiasta ja hänen hurskaista teoistansa, katso, se on kirjoitettuna profeetta Jesajan, Aamoksen pojan, näyssä, Juudan ja Israelin kuningasten kirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'Ja Hiskia meni lepoon isiensä tykö, ja hänet haudattiin siihen, mistä noustaan Daavidin jälkeläisten haudoille. Ja koko Juuda ja Jerusalemin asukkaat osoittivat hänelle kunniaa, kun hän kuoli. Ja hänen poikansa Manasse tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manasse oli kahdentoista vuoden vanha tullessansa kuninkaaksi, ja hän hallitsi Jerusalemissa viisikymmentä viisi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Hän teki sitä, mikä on pahaa Herran silmissä, niiden kansain kauhistavien tekojen mukaan, jotka Herra oli karkoittanut israelilaisten tieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Hän rakensi jälleen uhrikukkulat, jotka hänen isänsä Hiskia oli kukistanut, pystytti alttareja baaleille, teki aseroja ja kumarsi ja palveli kaikkea taivaan joukkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Hän rakensi alttareja myös Herran temppeliin, josta Herra oli sanonut: \"Jerusalemissa on minun nimeni oleva iankaikkisesti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Hän rakensi alttareja kaikelle taivaan joukolle Herran temppelin molempiin esipihoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Myös pani hän poikansa kulkemaan tulen läpi Ben-Hinnomin laaksossa, ennusteli merkeistä, harjoitti noituutta ja velhoutta ja hankki itsellensä vainaja-ja tietäjähenkien manaajia; hän teki paljon sitä, mikä on pahaa Herran silmissä, ja vihoitti hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Ja teettämänsä veistetyn kuvapatsaan hän asetti Jumalan temppeliin, josta Jumala oli sanonut Daavidille ja hänen pojallensa Salomolle: \"Tähän temppeliin ja Jerusalemiin, jonka minä olen valinnut kaikista Israelin sukukunnista, minä asetan nimeni ikiajoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'Enkä minä enää kuljeta Israelin jalkoja pois siitä maasta, jonka olen määrännyt teidän isillenne, jos Israel vain tarkoin noudattaa kaikkea, mitä minä olen käskenyt heidän noudattaa, koko lakia ja käskyjä ja oikeuksia, jotka ovat Mooseksen kautta annetut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Mutta Manasse eksytti Juudan ja Jerusalemin asukkaat tekemään enemmän pahaa, kuin olivat tehneet ne kansat, jotka Herra oli hävittänyt israelilaisten tieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Ja Herra puhui Manasselle ja hänen kansallensa, mutta he eivät kuunnelleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Niin Herra toi Assurin kuninkaan sotapäälliköt heidän kimppuunsa. He ottivat Manassen kiinni koukuilla, kytkivät hänet vaskikahleisiin ja veivät hänet Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Mutta ahdingossa ollessaan hän etsi Herran, Jumalansa, mielisuosiota ja nöyrtyi syvästi isiensä Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'Ja kun hän näin rukoili häntä, niin Jumala taipui ja kuuli hänen rukouksensa ja toi hänet takaisin Jerusalemiin, hänen valtakuntaansa. Silloin Manasse tuli tietämään, että Herra on Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Sen jälkeen hän rakennutti Daavidin kaupungin ulomman muurin, länteen päin Giihonista, laaksoon, aina Kalaporttiin saakka, niin että se ympäröi Oofelin, ja hän teki siitä hyvin korkean. Ja hän asetti sotapäälliköitä kaikkiin Juudan varustettuihin kaupunkeihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Ja hän poisti vieraat jumalat ja kuvapatsaan Herran temppelistä sekä kaikki alttarit, jotka hän oli rakennuttanut Herran temppelin vuorelle ja Jerusalemiin, ja heitätti ne kaupungin ulkopuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Ja hän pani kuntoon Herran alttarin ja uhrasi sillä yhteys-ja kiitosuhreja ja kehoitti Juudaa palvelemaan Herraa, Israelin Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Mutta kansa uhrasi edelleen uhrikukkuloilla, kuitenkin ainoastaan Herralle, Jumalallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Mitä muuta on kerrottavaa Manassesta, ja kuinka hän rukoili Jumalaansa, ja näkijäin puheista, jotka puhuivat hänelle Herran, Israelin Jumalan, nimessä, katso, se on Israelin kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Ja hänen rukouksestaan ja kuinka hän tuli kuulluksi, ja kaikista hänen synneistään ja uskottomuudestaan ja niistä paikoista, joihin hän rakennutti uhrikukkuloita ja pystytti asera-karsikoita ja jumalankuvia, ennenkuin hän nöyrtyi, katso, niistä on kirjoitettu Hoosain aikakirjaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Ja Manasse meni lepoon isiensä tykö, ja hänet haudattiin linnaansa. Ja hänen poikansa Aamon tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Aamon oli kahdenkymmenen kahden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kaksi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'Hän teki sitä, mikä on pahaa Herran silmissä, niinkuin hänen isänsä Manasse oli tehnyt. Ja Aamon uhrasi kaikille niille jumalankuville, jotka hänen isänsä Manasse oli teettänyt, ja palveli niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'Mutta hän ei nöyrtynyt Herran edessä, niinkuin hänen isänsä Manasse oli nöyrtynyt, vaan hän, Aamon, sälytti päällensä suuren syntivelan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'Niin hänen palvelijansa tekivät salaliiton häntä vastaan ja tappoivat hänet hänen linnassansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Mutta maan kansa surmasi kaikki ne, jotka olivat tehneet salaliiton kuningas Aamonia vastaan; ja maan kansa teki hänen poikansa Joosian kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Joosia oli kahdeksan vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kolmekymmentä yksi vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Hän teki sitä, mikä on oikein Herran silmissä, ja vaelsi isänsä Daavidin teitä, poikkeamatta oikealle tai vasemmalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Kahdeksantena hallitusvuotenaan, ollessansa vielä nuorukainen, hän alkoi etsiä isänsä Daavidin Jumalaa; ja kahdentenatoista vuotena hän alkoi puhdistaa Juudaa ja Jerusalemia uhrikukkuloista ja asera-karsikoista sekä veistetyistä ja valetuista jumalankuvista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Baalin alttarit kukistettiin hänen läsnäollessaan, ja niiden yli kohoavat auringonpatsaat hän hakkasi maahan, ja asera-karsikot sekä veistetyt ja valetut jumalankuvat hän murskasi ja rouhensi ja sirotteli niiden haudoille, jotka olivat niille uhranneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Ja pappien luut hän poltti heidän alttareillaan. Niin hän puhdisti Juudan ja Jerusalemin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Manassen, Efraimin ja Simeonin kaupungeissa aina Naftaliin asti, yltympäri, hän heidän miekoillaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'kukisti alttarit, löi palasiksi ja rouhensi asera-karsikot ja jumalankuvat, ja hän hakkasi maahan kaikki auringonpatsaat koko Israelin maasta. Sitten hän palasi Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'Kahdeksantenatoista hallitusvuotenaan, puhdistaessaan maata ja temppeliä, hän lähetti Saafanin, Asaljan pojan, kaupungin päällikön Maasejan ja kansleri Jooahin, Jooahaan pojan, korjaamaan Herran, hänen Jumalansa, temppeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Ja he tulivat ylimmäisen papin Hilkian luo ja jättivät Jumalan temppeliin tuodut rahat, joita leeviläiset, ovenvartijat, olivat koonneet Manassesta, Efraimista ja koko muusta Israelista ja koko Juudasta, Benjaminista ja Jerusalemin asukkailta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'He antoivat ne työnteettäjille, jotka oli pantu valvomaan töitä Herran temppelissä, ja nämä maksoivat niillä työmiehet, jotka työskentelivät Herran temppelissä, laittoivat ja korjasivat temppeliä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'niistä annettiin myös puusepille ja rakentajille, että nämä ostaisivat hakattuja kiviä ja puutavaraa kiinnitysparruiksi ja kattohirsiksi niihin rakennuksiin, jotka Juudan kuninkaat olivat turmelleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'Nämä miehet toimivat siinä työssä luottamusmiehinä. Ja leeviläiset Jahat ja Obadja, Merarin jälkeläiset, ja Sakarja ja Mesullam, Kehatin jälkeläiset, oli pantu valvomaan ja johtamaan heitä, ja myös kaikki leeviläiset, jotka ymmärsivät soittimia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'He myöskin valvoivat taakankantajia ja johtivat kaikkia työmiehiä eri töissä. Leeviläisiä oli kirjureina, virkamiehinä ja ovenvartijoina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Kun he olivat viemässä ulos Herran temppeliin tuotuja rahoja, löysi pappi Hilkia Herran lain kirjan, joka oli annettu Mooseksen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Ja Hilkia lausui ja sanoi kirjuri Saafanille: \"Minä löysin Herran temppelistä lain kirjan\". Ja Hilkia antoi kirjan Saafanille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Saafan vei kirjan kuninkaalle ja teki lisäksi kuninkaalle selon asiasta, sanoen: \"Kaikki, mitä annettiin palvelijaisi tehtäväksi, he ovat tehneet:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'he ovat ottaneet esille rahat, jotka olivat Herran temppelissä, ja antaneet ne työnvalvojille ja työnteettäjille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Ja kirjuri Saafan kertoi kuninkaalle sanoen: \"Pappi Hilkia antoi minulle erään kirjan\". Ja Saafan luki siitä kuninkaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Kun kuningas kuuli lain sanat, repäisi hän vaatteensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'Ja kuningas käski Hilkiaa, Ahikamia, Saafanin poikaa, Abdonia, Miikan poikaa, kirjuri Saafania ja Asajaa, kuninkaan palvelijaa, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, '\"Menkää ja kysykää minun puolestani ja niiden puolesta, joita on jäljellä Israelista ja Juudasta, neuvoa Herralta tästä löydetystä kirjasta. Sillä suuri on Herran viha, joka on vuodatettu meidän ylitsemme, sentähden että meidän isämme eivät ole noudattaneet Herran sanaa eivätkä tehneet mitään kaikesta siitä, mikä on kirjoitettuna tässä kirjassa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Niin Hilkia ynnä ne muut, jotka kuningas määräsi, menivät naisprofeetta Huldan tykö, joka oli vaatevaraston hoitajan Sallumin, Tokhatin pojan, Hasran pojanpojan, vaimo ja asui Jerusalemissa, toisessa kaupunginosassa. Ja he puhuivat hänelle, niinkuin edellä mainittiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Niin hän sanoi heille: \"Näin sanoo Herra, Israelin Jumala: Sanokaa sille miehelle, joka lähetti teidät minun tyköni:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, '\'Näin sanoo Herra: Katso, minä annan onnettomuuden kohdata tätä paikkaa ja sen asukkaita, kaikkien kirousten, jotka on kirjoitettu siihen kirjaan, jota on luettu Juudan kuninkaalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'koska he ovat hyljänneet minut ja polttaneet uhreja muille jumalille ja vihoittaneet minut kaikilla kättensä teoilla; sillä minun vihani on vuodatettu tämän paikan yli, eikä se ole sammuva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Mutta Juudan kuninkaalle, joka on lähettänyt teidät kysymään neuvoa Herralta, sanokaa näin: Näin sanoo Herra, Israelin Jumala, niistä sanoista, jotka sinä olet kuullut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Koska sydämesi on pehminnyt ja sinä olet nöyrtynyt Jumalan edessä, kuullessasi, mitä hän on puhunut tätä paikkaa ja sen asukkaita vastaan, koska sinä olet nöyrtynyt minun edessäni ja reväissyt vaatteesi ja itkenyt minun edessäni, niin minä myös olen kuullut sinua, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Katso, minä korjaan sinut isiesi tykö, ja sinä saat rauhassa siirtyä hautaasi, ja sinun silmäsi pääsevät näkemästä kaikkea onnettomuutta, minkä minä annan kohdata tätä paikkaa ja sen asukkaita.\'\" Ja he toivat kuninkaalle tämän vastauksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Niin kuningas lähetti kokoamaan luoksensa kaikki Juudan ja Jerusalemin vanhimmat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'Ja kuningas meni Herran temppeliin, hän ja kaikki Juudan miehet ja Jerusalemin asukkaat, myöskin papit ja leeviläiset, kaikki kansa suurimmasta pienimpään asti, ja hän luki heidän kuultensa kaikki Herran temppelistä löydetyn liitonkirjan sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Ja kuningas asettui paikallensa ja teki Herran edessä liiton, että heidän tuli seurata Herraa, noudattaa hänen käskyjänsä, todistuksiansa ja säädöksiänsä kaikesta sydämestään ja kaikesta sielustansa ja täyttää liiton sanat, jotka ovat kirjoitetut siihen kirjaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'Ja hän otti siihen liittoon kaikki, jotka olivat Jerusalemissa ja Benjaminissa. Ja Jerusalemin asukkaat tekivät, niinkuin Jumalan, heidän isiensä Jumalan, liitto vaati.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Ja Joosia poisti kaikki kauhistukset israelilaisten kaikista maakunnista ja vaati jokaista, joka Israelissa oli, palvelemaan Herraa, heidän Jumalaansa. Niin kauan kuin hän eli, he eivät luopuneet pois Herrasta, isiensä Jumalasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Sitten Joosia vietti Jerusalemissa pääsiäistä Herran kunniaksi. Pääsiäislammas teurastettiin ensimmäisen kuun neljäntenätoista päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'Hän asetti papit heidän palvelustehtäviinsä ja rohkaisi heitä palvelemaan Herran temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'Ja hän sanoi leeviläisille, jotka opettivat kaikkea Israelia ja jotka olivat pyhitetyt Herralle: \"Pankaa pyhä arkki temppeliin, jonka Salomo, Daavidin poika, Israelin kuningas, on rakentanut; ei teidän enää tarvitse kantaa sitä olallanne. Palvelkaa nyt Herraa, Jumalaanne, ja hänen kansaansa Israelia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'Valmistautukaa perhekunnittain, osastojenne mukaan, Daavidin, Israelin kuninkaan, määräyksen ja hänen poikansa Salomon käskykirjan mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'ja asettukaa pyhäkköön veljienne, rahvaan, perhekuntaryhmien mukaan, niin että jokaista ryhmää kohden on yksi leeviläisten perhekuntaosasto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'Niin teurastakaa pääsiäislammas ja pyhittäytykää ja valmistakaa se veljillenne, tehdäksenne Herran sanan mukaan, joka on puhuttu Mooseksen kautta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Ja Joosia antoi rahvaalle anniksi pikkukarjaa, karitsoita ja vohlia, kolmekymmentä tuhatta luvultaan, kaikki pääsiäisuhreiksi kaikille saapuvilla oleville, ja kolmetuhatta raavasta, kaikki nämä kuninkaan omaisuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Ja hänen päämiehensä antoivat vapaaehtoisesti annin kansalle, papeille ja leeviläisille. Hilkia, Sakarja ja Jehiel, Jumalan temppelin esimiehet, antoivat papeille pääsiäisuhreiksi kaksituhatta kuusisataa karitsaa, niin myös kolmesataa raavasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Ja Koonanja, Semaja ja hänen veljensä Netanel, sekä Hasabja, Jegiel ja Joosabad, leeviläisten päämiehet, antoivat antina leeviläisille pääsiäisuhreiksi viisituhatta karitsaa ja viisisataa raavasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'Näin järjestettiin jumalanpalvelus. Ja papit asettuivat paikoilleen ja samoin leeviläiset osastoittain, niinkuin kuningas oli käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'Sitten teurastettiin pääsiäislammas, ja papit vihmoivat veren, jonka olivat ottaneet leeviläisten käsistä; ja leeviläiset nylkivät nahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'Mutta he panivat syrjään polttouhrikappaleet, antaakseen ne rahvaalle perhekuntaryhmittäin, uhrattaviksi Herralle, niinkuin on kirjoitettuna Mooseksen kirjassa; samoin he tekivät myös raavaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'Ja he paistoivat tulella pääsiäislampaan säädetyllä tavalla; mutta pyhät lahjat he keittivät padoissa, ruukuissa ja vadeissa ja veivät ne kiiruusti rahvaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Sitten he valmistivat itsellensä ja papeille, sillä papit, Aaronin pojat, olivat yöhön saakka uhraamassa polttouhria ja rasvoja; sentähden leeviläiset valmistivat itsellensä ja papeille, Aaronin pojille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Ja veisaajat, Aasafin pojat, olivat paikoillansa, niinkuin Daavid, Aasaf, Heeman ja Jedutun, kuninkaan näkijä, olivat määränneet, niin myös ovenvartijat jokaisella portilla; heidän ei ollut lupa lähteä palveluksestaan, vaan heidän leeviläiset veljensä valmistivat heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Näin järjestettiin kaikki Herran palvelus sinä päivänä, pääsiäisen vietto ja polttouhrien uhraaminen Herran alttarilla, niinkuin kuningas Joosia oli käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'Näin viettivät saapuvilla olevat israelilaiset sinä aikana pääsiäistä ja happamattoman leivän juhlaa seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'Sellaista pääsiäistä ei oltu vietetty Israelissa profeetta Samuelin ajoista asti; sillä ei kukaan Israelin kuninkaista ollut viettänyt semmoista pääsiäistä, kuin nyt viettivät Joosia, papit ja leeviläiset, koko Juuda ja saapuvilla olevat israelilaiset sekä Jerusalemin asukkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Joosian kahdeksantenatoista hallitusvuotena vietettiin tämä pääsiäinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Kaiken tämän jälkeen, sittenkuin Joosia oli pannut kuntoon temppelin, lähti Neko, Egyptin kuningas, sotimaan Karkemista vastaan, joka on Eufratin varrella; ja Joosia meni häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Niin Neko lähetti sanansaattajat hänen luokseen ja käski sanoa: \"Mitä sinulla on tekemistä minun kanssani, Juudan kuningas? Enhän minä nyt tule sinua vastaan, vaan sitä sukua vastaan, joka on sodassa minun kanssani, ja Jumala on käskenyt minua kiiruhtamaan. Jätä rauhaan Jumala, joka on minun kanssani, ettei hän tuhoaisi sinua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Mutta Joosia ei väistänyt häntä, vaan pukeutui tuntemattomaksi taistellakseen häntä vastaan, eikä kuullut Nekon sanoja, jotka kuitenkin tulivat Jumalan suusta. Niin hän meni taistelemaan Megiddon tasangolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'Mutta ampujat ampuivat kuningas Joosiaa; ja kuningas sanoi palvelijoillensa: \"Viekää minut pois, sillä minä olen pahasti haavoittunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Niin hänen palvelijansa siirsivät hänet sotavaunuista ja panivat hänet hänen toisiin vaunuihinsa ja kuljettivat hänet Jerusalemiin. Ja hän kuoli, ja hänet haudattiin isiensä hautoihin. Ja koko Juuda ja Jerusalem surivat Joosiaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Ja Jeremia sepitti itkuvirren Joosiasta. Ja kaikki laulajat ja laulajattaret ovat itkuvirsissään puhuneet Joosiasta aina tähän päivään asti; ja nämä ovat tulleet yleisiksi Israelissa. Katso, ne ovat kirjoitettuina \"Itkuvirsissä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Mitä muuta on kerrottavaa Joosiasta ja hänen hurskaista teoistansa, joita hän teki sen mukaan, kuin on kirjoitettuna Herran laissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'hänen sekä aikaisemmista että myöhemmistä vaiheistaan, katso, se on kirjoitettuna Israelin ja Juudan kuningasten kirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Maan kansa otti Joosian pojan Jooahaan ja teki hänet kuninkaaksi Jerusalemiin hänen isänsä jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Jooahas oli kahdenkymmenen kolmen vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa kolme kuukautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Mutta Egyptin kuningas pani hänet viralta Jerusalemissa ja otti maasta pakkoverona sata talenttia hopeata ja yhden talentin kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'Ja Egyptin kuningas teki hänen veljensä Eljakimin Juudan ja Jerusalemin kuninkaaksi ja muutti hänen nimensä Joojakimiksi. Mutta hänen veljensä Jooahaan Neko otti ja vei Egyptiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Joojakim oli kahdenkymmenen viiden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hän teki sitä, mikä oli pahaa Herran, hänen Jumalansa, silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Ja Nebukadnessar, Baabelin kuningas, lähti häntä vastaan ja kytki hänet vaskikahleisiin viedäkseen hänet Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Nebukadnessar vei Herran temppelin kaluja Baabeliin ja pani ne temppeliinsä Baabelissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Mitä muuta on kerrottavaa Joojakimista ja niistä kauhistuksista, joita hän teki, ja mitä hänessä havaittiin, katso, se on kirjoitettuna Israelin ja Juudan kuningasten kirjassa. Ja hänen poikansa Joojakin tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Joojakin oli kahdeksantoista vuoden vanha tullessansa kuninkaaksi, ja hän hallitsi Jerusalemissa kolme kuukautta ja kymmenen päivää. Hän teki sitä, mikä on pahaa Herran silmissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Vuoden vaihteessa kuningas Nebukadnessar lähetti noutamaan hänet Baabeliin, hänet ynnä Herran temppelin kallisarvoiset kalut. Ja hän teki hänen veljensä Sidkian Juudan ja Jerusalemin kuninkaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Sidkia oli kahdenkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'Hän teki sitä, mikä oli pahaa Herran, hänen Jumalansa, silmissä: hän ei nöyrtynyt profeetta Jeremian edessä, jonka sana tuli Herran suusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Myöskin hän kapinoi kuningas Nebukadnessaria vastaan, joka kuitenkin oli vannottanut hänet Jumalan kautta. Hän oli niskuri ja paadutti sydämensä, niin ettei hän kääntynyt Herran, Israelin Jumalan, puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Myös kaikki pappien päämiehet ja kansa harjoittivat paljon uskottomuutta jäljittelemällä pakanain kaikkia kauhistuksia, ja he saastuttivat Herran temppelin, jonka hän oli pyhittänyt Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'Ja Herra, heidän isiensä Jumala, lähetti, varhaisesta alkaen, vähän väliä heille varoituksia sanansaattajainsa kautta, sillä hän sääli kansaansa ja asumustansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Mutta he pilkkasivat Jumalan sanansaattajia ja halveksivat hänen sanaansa ja häpäisivät hänen profeettojansa, kunnes Herran viha hänen kansaansa kohtaan oli kasvanut niin, ettei apua enää ollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Niin hän toi heidän kimppuunsa kaldealaisten kuninkaan ja surmautti miekalla heidän nuoret miehensä heidän pyhäkössänsä eikä säästänyt nuorukaista eikä neitosta, ei vanhusta eikä harmaapäätä; kaikki hän antoi tämän käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Ja kaikki Jumalan temppelin kalut, sekä suuret että pienet, ja Herran temppelin aarteet sekä kuninkaan ja hänen päämiestensä aarteet, kaikki hän vei Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'Jumalan temppeli poltettiin, Jerusalemin muurit revittiin, kaikki sen palatsit poltettiin tulella, ja kaikki sen kallisarvoiset esineet hävitettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'Ja jotka olivat säilyneet miekalta, ne vietiin pakkosiirtolaisuuteen Baabeliin. Ja he olivat hänen ja hänen poikiensa palvelijoina, kunnes Persian valtakunta sai vallan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Ja niin toteutui Herran sana, jonka hän oli puhunut Jeremian suun kautta, kunnes maa oli saanut hyvityksen sapateistaan-niin kauan kuin se oli autiona, se lepäsi-kunnes seitsemänkymmentä vuotta oli kulunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Mutta Kooreksen, Persian kuninkaan, ensimmäisenä hallitusvuotena herätti Herra, että täyttyisi Herran sana, jonka hän oli puhunut Jeremian suun kautta, Kooreksen, Persian kuninkaan, hengen, niin että tämä koko valtakunnassansa kuulutti ja myös käskykirjassa julistutti näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, '\"Näin sanoo Koores, Persian kuningas: Kaikki maan valtakunnat on Herra, taivaan Jumala, antanut minulle, ja hän on käskenyt minun rakentaa itsellensä temppelin Jerusalemiin, joka on Juudassa. Kuka vain teidän joukossanne on hänen kansaansa, sen kanssa olkoon Herra, hänen Jumalansa, ja hän menköön sinne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Kooreksen, Persian kuninkaan, ensimmäisenä hallitusvuotena herätti Herra, että täyttyisi Herran sana, jonka hän oli puhunut Jeremian suun kautta, Kooreksen, Persian kuninkaan, hengen, niin että tämä koko valtakunnassansa kuulutti ja myös käskykirjassa julistutti näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, '\"Näin sanoo Koores, Persian kuningas: Kaikki maan valtakunnat on Herra, taivaan Jumala, antanut minulle, ja hän on käskenyt minun rakentaa itsellensä temppelin Jerusalemiin, joka on Juudassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Kuka vain teidän joukossanne on hänen kansaansa, sen kanssa olkoon hänen Jumalansa, ja hän menköön Jerusalemiin, joka on Juudassa, rakentamaan Herran, Israelin Jumalan, temppeliä. Hän on se Jumala, joka asuu Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Kuka vain on jäljellä, se saakoon, missä asuukin muukalaisena, paikkakuntansa miehiltä kannatukseksi hopeata ja kultaa, tavaraa ja karjaa ynnä vapaaehtoisia lahjoja Jumalan temppelin rakentamiseksi Jerusalemiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Silloin nousivat Juudan ja Benjaminin perhekunta-päämiehet sekä papit ja leeviläiset, kaikki, joiden hengen Jumala herätti menemään ja rakentamaan Herran temppeliä Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Ja kaikki, jotka asuivat heidän ympärillään, avustivat heitä hopeakaluilla, kullalla, tavaralla, karjalla ja kalleuksilla kaiken sen lisäksi, mitä annettiin vapaaehtoisina lahjoina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Ja kuningas Koores tuotatti esiin Herran temppelin kalut, jotka Nebukadnessar oli vienyt pois Jerusalemista ja pannut oman jumalansa temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'Ne Koores, Persian kuningas, tuotatti aarteistonvartijalle, Mitredatille, ja tämä laski niiden luvun Sesbassarille, Juudan ruhtinaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'Ja tämä oli niiden luku: kolmekymmentä kultamaljaa, tuhat hopeamaljaa, kaksikymmentä yhdeksän uhriastiaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'kolmekymmentä kultapikaria, niitä arvolta lähinnä neljäsataa kymmenen hopeapikaria, tuhat muuta kalua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Kulta-ja hopeakaluja oli kaikkiaan viisituhatta neljäsataa. Kaikki nämä Sesbassar toi, silloin kun pakkosiirtolaiset tuotiin Baabelista Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Ja nämä olivat ne tämän maakunnan asukkaat, jotka lähtivät pakkosiirtolaisten vankeudesta Baabelista, jonne Nebukadnessar, Baabelin kuningas, oli vienyt heidät pakkosiirtolaisuuteen, ja jotka palasivat Jerusalemiin ja Juudaan, kukin kaupunkiinsa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'ne, jotka tulivat Serubbaabelin, Jeesuan, Nehemian, Serajan, Reelajan, Mordekain, Bilsanin, Misparin, Bigvain, Rehumin ja Baanan kanssa. Israelin kansan miesten lukumäärä oli:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Paroksen jälkeläisiä kaksituhatta sata seitsemänkymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Sefatjan jälkeläisiä kolmesataa seitsemänkymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Aarahin jälkeläisiä seitsemänsataa seitsemänkymmentä viisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Pahat-Mooabin jälkeläisiä, nimittäin Jeesuan ja Jooabin jälkeläisiä, kaksituhatta kahdeksansataa kaksitoista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Eelamin jälkeläisiä tuhat kaksisataa viisikymmentä neljä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Sattun jälkeläisiä yhdeksänsataa neljäkymmentä viisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Sakkain jälkeläisiä seitsemänsataa kuusikymmentä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Baanin jälkeläisiä kuusisataa neljäkymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Beebain jälkeläisiä kuusisataa kaksikymmentä kolme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Asgadin jälkeläisiä tuhat kaksisataa kaksikymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Adonikamin jälkeläisiä kuusisataa kuusikymmentä kuusi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Bigvain jälkeläisiä kaksituhatta viisikymmentä kuusi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Aadinin jälkeläisiä neljäsataa viisikymmentä neljä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Aaterin, nimittäin Hiskian, jälkeläisiä yhdeksänkymmentä kahdeksan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Beesain jälkeläisiä kolmesataa kaksikymmentä kolme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Jooran jälkeläisiä sata kaksitoista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Haasumin jälkeläisiä kaksisataa kaksikymmentä kolme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Gibbarin jälkeläisiä yhdeksänkymmentä viisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'beetlehemiläisiä sata kaksikymmentä kolme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Netofan miehiä viisikymmentä kuusi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Anatotin miehiä sata kaksikymmentä kahdeksan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'asmavetilaisia neljäkymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'kirjat-aarimilaisia, kefiralaisia ja beerotilaisia seitsemänsataa neljäkymmentä kolme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'raamalaisia ja gebalaisia kuusisataa kaksikymmentä yksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Mikmaan miehiä sata kaksikymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Beetelin ja Ain miehiä kaksisataa kaksikymmentä kolme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'nebolaisia viisikymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Magbiin jälkeläisiä sata viisikymmentä kuusi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'toisen Eelamin jälkeläisiä tuhat kaksisataa viisikymmentä neljä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Haarimin jälkeläisiä kolmesataa kaksikymmentä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'loodilaisia, haadidilaisia ja oonolaisia seitsemänsataa kaksikymmentä viisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'jerikolaisia kolmesataa neljäkymmentä viisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'senaalaisia kolmetuhatta kuusisataa kolmekymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Pappeja oli: Jedajan jälkeläisiä, nimittäin Jeesuan sukua, yhdeksänsataa seitsemänkymmentä kolme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Immerin jälkeläisiä tuhat viisikymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Pashurin jälkeläisiä tuhat kaksisataa neljäkymmentä seitsemän;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Haarimin jälkeläisiä tuhat seitsemäntoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Leeviläisiä oli: Jeesuan ja Kadmielin jälkeläisiä, nimittäin Hoodavjan jälkeläisiä, seitsemänkymmentä neljä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Veisaajia oli: Aasafin jälkeläisiä sata kaksikymmentä kahdeksan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Ovenvartijain jälkeläisiä oli: Sallumin jälkeläisiä, Aaterin jälkeläisiä, Talmonin jälkeläisiä, Akkubin jälkeläisiä, Hatitan jälkeläisiä, Soobain jälkeläisiä, kaikkiaan sata kolmekymmentä yhdeksän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Temppelipalvelijoita oli: Siihan jälkeläiset, Hasufan jälkeläiset, Tabbaotin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Keeroksen jälkeläiset, Siiahan jälkeläiset, Paadonin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Lebanan jälkeläiset, Hagaban jälkeläiset, Akkubin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Haagabin jälkeläiset, Samlain jälkeläiset, Haananin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Giddelin jälkeläiset, Gaharin jälkeläiset, Reajan jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Resinin jälkeläiset, Nekodan jälkeläiset, Gassamin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Ussan jälkeläiset, Paaseahin jälkeläiset, Beesain jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Asnan jälkeläiset, Meunimin jälkeläiset, Nefusimin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Bakbukin jälkeläiset, Hakufan jälkeläiset, Harhurin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Baslutin jälkeläiset, Mehidan jälkeläiset, Harsan jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Barkoksen jälkeläiset, Siiseran jälkeläiset, Taamahin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Nesiahin jälkeläiset, Hatifan jälkeläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Salomon palvelijain jälkeläisiä oli: Sootain jälkeläiset, Sooferetin jälkeläiset, Perudan jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Jaalan jälkeläiset, Darkonin jälkeläiset, Giddelin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Sefatjan jälkeläiset, Hattilin jälkeläiset, Pookeret-Sebaimin jälkeläiset, Aamin jälkeläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Temppelipalvelijoita ja Salomon palvelijain jälkeläisiä oli kaikkiaan kolmesataa yhdeksänkymmentä kaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Nämä olivat ne, jotka lähtivät Teel-Melahista, Teel-Harsasta, Kerub-Addanista ja Immeristä, voimatta ilmoittaa perhekuntaansa ja syntyperäänsä, olivatko israelilaisia:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'Delajan jälkeläisiä, Tobian jälkeläisiä, Nedokan jälkeläisiä, kuusisataa viisikymmentä kaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Ja pappien poikain joukossa olivat Habaijan jälkeläiset, Koosin jälkeläiset ja Barsillain jälkeläiset, sen, joka oli ottanut vaimon gileadilaisen Barsillain tyttäristä ja jota kutsuttiin heidän nimellään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Nämä etsivät sukuluetteloitaan, niitä löytämättä, ja niin heidät julistettiin pappeuteen kelpaamattomiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Maaherra kielsi heitä syömästä korkeasti-pyhää, ennenkuin nousisi pappi, joka voi hoitaa uurimia ja tummimia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Koko seurakunta oli yhteensä neljäkymmentä kaksi tuhatta kolmesataa kuusikymmentä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'paitsi heidän palvelijoitansa ja palvelijattariansa, joita oli seitsemäntuhatta kolmesataa kolmekymmentä seitsemän. Lisäksi oli heillä kaksisataa mies-ja naisveisaajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Hevosia heillä oli seitsemänsataa kolmekymmentä kuusi, muuleja kaksisataa neljäkymmentä viisi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'kameleja neljäsataa kolmekymmentä viisi, aaseja kuusituhatta seitsemänsataa kaksikymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Perhekunta-päämiehistä muutamat, tullessansa Herran temppelin sijalle, joka on Jerusalemissa, antoivat vapaaehtoisia lahjoja Jumalan temppelille, sen pystyttämiseksi paikallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'He antoivat sen mukaan, kuin voivat, rakennusrahastoon: kuusikymmentä yksi tuhatta dareikkia kultaa, viisituhatta miinaa hopeata ja sata papinihokasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'Sitten papit, leeviläiset ja osa kansaa sekä veisaajat, ovenvartijat ja temppelipalvelijat asettuivat kaupunkeihinsa, ja kaikki muut israelilaiset kaupunkeihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'Kun seitsemäs kuukausi tuli ja israelilaiset jo olivat kaupungeissa, kokoontui kansa yhtenä miehenä Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Ja Jeesua, Joosadakin poika, ja hänen veljensä, papit, ja Serubbaabel, Sealtielin poika, ja hänen veljensä nousivat rakentamaan Israelin Jumalan alttaria uhrataksensa sen päällä polttouhreja, niinkuin on kirjoitettuna Jumalan miehen Mooseksen laissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'He pystyttivät paikallensa alttarin, sillä he olivat kauhuissaan maan kansojen tähden; ja he uhrasivat alttarilla polttouhreja Herralle, polttouhreja aamuin ja illoin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Ja he viettivät lehtimajanjuhlaa, niinkuin oli säädetty, ja uhrasivat polttouhreja joka päivä niin paljon, kuin oli säädetty, kunakin päivänä sen päivän uhrit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'ja sen jälkeen jokapäiväisen polttouhrin ja uudenkuun päivien ja kaikkien muiden Herran pyhien juhlien uhrit sekä kaikkien niiden uhrit, jotka toivat vapaaehtoisia lahjoja Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Seitsemännen kuun ensimmäisestä päivästä alkaen he uhrasivat polttouhreja Herralle, vaikka temppelin perustusta ei oltu vielä laskettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'Ja he antoivat rahaa kivenhakkaajille ja puusepille sekä ruoka-ja juomatavaroita ja öljyä siidonilaisille ja tyyrolaisille, että nämä kuljettaisivat setripuita Libanonilta meritse Jaafoon, sen valtuuden nojalla, jonka Koores, Persian kuningas, oli heille antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Ja toisena vuotena siitä, kun he olivat tulleet Jumalan temppelin sijalle Jerusalemiin, sen toisessa kuussa, ryhtyivät Serubbaabel, Sealtielin poika, ja Jeesua, Joosadakin poika, ja heidän muut veljensä, papit ja leeviläiset, ja kaikki, jotka vankeudesta olivat tulleet Jerusalemiin, työhön ja panivat kaksikymmenvuotiset ja sitä vanhemmat leeviläiset johtamaan Herran temppelin rakennustyötä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Ja Jeesua poikineen ja veljineen ja Kadmiel poikineen, Juudan jälkeläiset, astuivat yhdessä johtamaan niitä, jotka tekivät Herran temppelin rakennustyötä; samoin myöskin Heenadadin pojat poikineen ja veljineen, leeviläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'Ja kun rakentajat laskivat Herran temppelin perustusta, asetettiin papit virkapuvuissaan torvilla ja leeviläiset, Aasafin jälkeläiset, kymbaaleilla ylistämään Herraa, Israelin kuninkaan Daavidin järjestelyn mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'Ja he virittivät ylistys-ja kiitosvirren Herralle: \"Sillä hän on hyvä sillä hänen armonsa pysyy iankaikkisesti Israelia kohtaan\". Ja kaikki kansa nosti suuren riemuhuudon ylistäen Herraa siitä, että Herran temppelin perustus oli laskettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'Mutta monet papit, leeviläiset ja perhekunta-päämiehet, vanhukset, jotka olivat nähneet edellisen temppelin, itkivät suurella äänellä, kun tämän temppelin perustus laskettiin heidän nähtensä. Monet taas korottivat äänensä riemuiten ja iloiten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Eikä voitu erottaa raikuvaa riemuhuutoa kansan äänekkäästä itkusta; sillä kansa nosti suuren huudon, niin että huuto kuului kauas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Mutta kun Juudan ja Benjaminin vastustajat kuulivat, että pakkosiirtolaiset rakensivat temppeliä Herralle, Israelin Jumalalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'astuivat he Serubbaabelin ja perhekunta-päämiesten luo ja sanoivat heille: \"Me tahdomme rakentaa yhdessä teidän kanssanne, sillä me etsimme teidän Jumalaanne, niinkuin tekin, ja hänelle me olemme uhranneet Eesarhaddonin, Assurin kuninkaan, päivistä asti, hänen, joka toi meidät tänne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Mutta Serubbaabel ja Jeesua ja muut Israelin perhekunta-päämiehet sanoivat heille: \"Ei sovi teidän ja meidän yhdessä rakentaa temppeliä meidän Jumalallemme, vaan me yksin rakennamme Herralle, Israelin Jumalalle, niinkuin kuningas Koores, Persian kuningas, on meitä käskenyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Mutta maan kansa sai Juudan kansan kädet herpoamaan ja pelotti heidät rakentamasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Ja ne palkkasivat heitä vastaan neuvonantajia, jotka tekivät heidän hankkeensa tyhjäksi, niin kauan kuin Koores, Persian kuningas, eli, ja aina Daarejaveksen, Persian kuninkaan, hallitusaikaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Ahasveroksen hallituksen aikana, hänen hallituksensa alussa, he kirjoittivat syytöskirjan Juudan ja Jerusalemin asukkaita vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Ja Artahsastan aikana kirjoittivat Bislam, Mitredat ja Taabeel ynnä näiden muut virkatoverit Artahsastalle, Persian kuninkaalle. Kirje oli kirjoitettu aramin kirjoituksella ja käännetty araminkielelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Käskynhaltija Rehum ja kirjuri Simsai kirjoittivat kuningas Artahsastalle Jerusalemia vastaan kirjeen, joka kuului näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'Silloin ja silloin. \"Käskynhaltija Rehum ja kirjuri Simsai ynnä muut heidän virkatoverinsa, tuomarit, järjestysmiehet, tarpelilaiset, afarsilaiset, erekiläiset, babylonialaiset, suusanilaiset, dehavilaiset, eelamilaiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'ja muut kansat, jotka suuri ja mainehikas Aasenappar vei pakkosiirtolaisuuteen ja sijoitti Samarian kaupunkiin ja muualle, tälle puolelle Eufrat-virran,\" ja niin edespäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'Tämä on jäljennös kirjeestä, jonka he lähettivät hänelle: \"Kuningas Artahsastalle sinun palvelijasi, miehet tältä puolelta Eufrat-virran,\" ja niin edespäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, '\"Tietäköön kuningas, että ne juutalaiset, jotka lähtivät sinun luotasi meidän luoksemme, ovat tulleet Jerusalemiin. He ovat nyt rakentamassa tuota kapinallista ja pahaa kaupunkia ja panemassa kuntoon muureja ja korjaamassa perustuksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Niin tietäköön kuningas, että jos se kaupunki rakennetaan ja muurit pannaan kuntoon, he eivät suorita rahaveroa, eivät luonnontuotteita eivätkä tierahaa, ja siitä kärsivät kuningasten tulot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Koska kerran me syömme palatsin suolaa eikä meidän sovi nähdä kuninkaan häpäisemistä, sentähden me lähetämme ja ilmoitamme tämän kuninkaalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'että hän tutkituttaisi sinun isiesi aikakirjaa; sillä aikakirjasta sinä huomaat ja saat tietää, että se kaupunki on ollut kapinallinen kaupunki, joka on tuottanut kuninkaille ja maakunnille vahinkoa ja jossa ammoisista ajoista on pantu toimeen levottomuuksia. Sentähden se kaupunki on hävitetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Me ilmoitamme siis kuninkaalle, että jos se kaupunki rakennetaan ja muurit pannaan kuntoon, ei sinulla ole oleva mitään osaa tällä puolella Eufrat-virran olevaan maahan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Kuningas lähetti vastauksen käskynhaltija Rehumille ja kirjuri Simsaille ja muille heidän virkatovereilleen, jotka asuivat Samariassa ja muualla tällä puolella Eufrat-virran: \"Rauhaa\" ja niin edespäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, '\"Kirjelmä, jonka meille lähetitte, on minulle tarkkaan luettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Minä annoin käskyn tutkia asiaa, ja huomattiin, että se kaupunki ammoisista ajoista asti on noussut kuninkaita vastaan ja että siellä on pantu toimeen kapinoita ja levottomuuksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Jerusalemissa on ollut mahtavia kuninkaita, jotka ovat hallinneet kaikkea Eufrat-virran senpuoleista maata ja joille on suoritettu rahaveroa, luonnontuotteita ja tierahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Antakaa siis käsky, että ne miehet on estettävä työstään ja että se kaupunki on jätettävä rakentamatta, kunnes minulta tulee käsky.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Ja varokaa, ettette lyö laimin mitään tässä asiassa, etteivät kuninkaat kärsisi siitä suurta vahinkoa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'Niin pian kuin kuningas Artahsastan kirjelmän jäljennös oli luettu Rehumille, kirjuri Simsaille ja heidän virkatovereilleen, menivät he kiiruusti Jerusalemiin juutalaisten luo ja estivät väkivoimalla heidät työtä tekemästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Silloin pysähtyi Jumalan temppelin rakennustyö Jerusalemissa ja oli pysähdyksissä Daarejaveksen, Persian kuninkaan, toiseen hallitusvuoteen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Mutta profeetta Haggai ja Sakarja, Iddon poika, profeetat, ennustivat Juudassa ja Jerusalemissa oleville juutalaisille Israelin Jumalan nimeen, hänen, jonka nimiin he olivat otetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Niin Serubbaabel, Sealtielin poika, ja Jeesua, Joosadakin poika, nousivat ja alkoivat rakentaa Jumalan temppeliä Jerusalemissa, ja heidän kanssansa Jumalan profeetat, jotka tukivat heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Siihen aikaan tulivat heidän luoksensa Tattenai, Eufrat-virran tämänpuoleisen maan käskynhaltija, ja Setar-Boosenai sekä heidän virkatoverinsa ja sanoivat heille näin: \"Kuka on käskenyt teitä rakentamaan tätä temppeliä ja panemaan kuntoon tätä muuria?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Niin me sanoimme heille niiden miesten nimet, jotka tätä rakennusta rakensivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Ja juutalaisten vanhinten yllä oli heidän Jumalansa silmä, niin ettei heitä estetty työstä, vaan meni kertomus asiasta Daarejavekselle ja odotettiin sitä koskevan kirjoituksen tuloa sieltä takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Jäljennös kirjeestä, jonka Tattenai, Eufrat-virran tämänpuoleisen maan käskynhaltija, ja Setar-Boosenai sekä tämän virkatoverit, ne afarsakilaiset, jotka olivat tällä puolella Eufrat-virran, lähettivät kuningas Daarejavekselle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'he näet lähettivät hänelle kertomuksen, ja siihen oli kirjoitettu näin: \"Kuningas Daarejavekselle kaikkea rauhaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Tietäköön kuningas, että me menimme Juudan maakuntaan, suuren Jumalan temppelille. Sitä rakennetaan suurista kivistä, ja hirsiä pannaan seiniin. Työ tehdään tarkasti ja sujuu heidän käsissään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Sitten me kysyimme vanhimmilta ja sanoimme heille näin: \'Kuka on käskenyt teitä rakentamaan tätä temppeliä ja panemaan kuntoon tätä muuria?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Me kysyimme heiltä myöskin heidän nimiänsä ilmoittaaksemme ne sinulle ja kirjoitimme muistiin niiden miesten nimet, jotka ovat heitä johtamassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Ja he antoivat meille tämän vastauksen: \'Me olemme taivaan ja maan Jumalan palvelijoita, ja me rakennamme uudestaan temppeliä, joka oli rakennettu monta vuotta sitten. Suuri Israelin kuningas sen rakensi ja sai sen valmiiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Mutta koska meidän isämme vihoittivat taivaan Jumalan, antoi hän heidät kaldealaisen Nebukadnessarin, Baabelin kuninkaan, käsiin; ja hän hävitti tämän temppelin ja vei kansan pakkosiirtolaisuuteen Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Mutta Kooreksen, Baabelin kuninkaan, ensimmäisenä hallitusvuotena antoi kuningas Koores käskyn rakentaa uudestaan tämän Jumalan temppelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Kuningas Koores antoi myös tuoda Baabelin temppelistä esiin Jumalan temppelin kulta-ja hopeakalut, jotka Nebukadnessar oli vienyt pois Jerusalemin temppelistä ja tuonut Baabelin temppeliin; ja ne annettiin Sesbassar-nimiselle miehelle, jonka hän oli asettanut käskynhaltijaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'Ja hän sanoi tälle: Ota nämä kalut, mene ja pane ne Jerusalemin temppeliin. Ja Jumalan temppeli rakennettakoon entiselle paikallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Niin tämä Sesbassar tuli ja laski Jumalan temppelin perustuksen Jerusalemissa. Ja siitä ajasta alkaen tähän saakka sitä on rakennettu, eikä se vieläkään ole valmis.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Jos kuningas siis hyväksi näkee, niin tutkittakoon kuninkaan aarrekammiossa siellä Baabelissa, onko niin, että kuningas Koores on antanut käskyn rakentaa tämän Jumalan temppelin Jerusalemissa; ja lähettänee kuningas meille tiedon tahdostansa tässä asiassa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Niin kuningas Daarejaves antoi käskyn, että asiaa tutkittaisiin Baabelin arkistossa, jonne myös aarteet koottiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'Ja Ahmetan linnasta, Meedian maakunnasta, löydettiin kirjakäärö, johon oli kirjoitettu seuraavasti: \"Muistettava tapahtuma:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Kuningas Kooreksen ensimmäisenä hallitusvuotena kuningas Koores antoi käskyn: Jumalan temppeli Jerusalemissa, se temppeli rakennettakoon paikaksi, jossa uhreja uhrataan. Sen perustukset laskettakoon lujiksi, sen korkeus olkoon kuusikymmentä kyynärää ja leveys kuusikymmentä kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Siinä olkoon aina rinnakkain kolme kivikertaa suuria kiviä ja yksi hirsikerta uusia hirsiä; ja kustannukset suoritettakoon kuninkaan hovista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Ja myös Jumalan temppelin kulta-ja hopeakalut, jotka Nebukadnessar vei pois Jerusalemin temppelistä ja toi Baabeliin, annettakoon takaisin. Ne tulkoot paikoilleen Jerusalemin temppeliin, pantakoon ne Jumalan temppeliin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, '-\"Niinmuodoin on sinun, Tattenai, joka olet Eufrat-virran tuonpuoleisen maan käskynhaltija, sinun, Setar-Boosenai, ja teidän virkatoverienne, niiden afarsakilaisten, jotka ovat tuolla puolella Eufrat-virran, pysyttävä siitä erillänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Antakaa Jumalan temppelin rakennustyön olla rauhassa. Juutalaisten käskynhaltija ja juutalaisten vanhimmat rakentakoot Jumalan temppelin paikallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Ja minä annan käskyn, mitä teidän on tehtävä juutalaisten vanhimmille heidän rakentaessaan Jumalan temppeliä: tuolta puolelta Eufrat-virran tulevista kuninkaan verotuloista suoritettakoon niille miehille tarkasti ja viivyttelemättä kustannukset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'Ja mitä tarvitaan, mullikoita, oinaita ja karitsoita polttouhreiksi taivaan Jumalalle, nisuja, suolaa, viiniä ja öljyä, se annettakoon heille Jerusalemin pappien esityksestä joka päivä, laiminlyömättä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'että he uhraisivat suloisesti tuoksuvia uhreja taivaan Jumalalle ja rukoilisivat kuninkaan ja hänen poikiensa hengen puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Ja minä annan käskyn, että kuka ikinä rikkoo tämän määräyksen, hänen talostaan revittäköön hirsi, ja hänet ripustettakoon ja naulittakoon siihen, ja hänen talostaan tehtäköön siitä syystä soraläjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'Ja Jumala, joka on asettanut nimensä siihen, kukistakoon jokaisen kuninkaan ja kansan, joka ojentaa kätensä rikkomaan tätä määräystä hävittämällä Jumalan temppelin Jerusalemissa. Minä Daarejaves olen antanut tämän käskyn; se tarkoin täytettäköön.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Silloin Tattenai, Eufrat-virran tämänpuoleisen maan käskynhaltija, Setar-Boosenai ja heidän virkatoverinsa täyttivät tarkoin käskyn, jonka kuningas Daarejaves oli heille lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'Niin juutalaisten vanhimmat rakensivat, ja työ onnistui heille profeetta Haggain ja Sakarjan, Iddon pojan, ennustuksen tukemana. Ja he saivat sen valmiiksi Israelin Jumalan käskyn ja Kooreksen, Daarejaveksen ja Artahsastan, Persian kuninkaan, käskyn mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'Tämä temppeli valmistui adar-kuun kolmanneksi päiväksi, nimittäin kuningas Daarejaveksen kuudentena hallitusvuotena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Silloin israelilaiset, papit ja leeviläiset ja muut pakkosiirtolaiset, viettivät Jumalan temppelin vihkiäisiä iloiten');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'ja uhrasivat Jumalan temppelin vihkiäisissä sata härkää, kaksisataa oinasta ja neljäsataa karitsaa sekä syntiuhriksi koko Israelin puolesta kaksitoista kaurista, Israelin sukukuntien luvun mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'Ja he asettivat papit ryhmittäin ja leeviläiset osastoittain Jumalan palvelukseen Jerusalemissa, niinkuin on kirjoitettuna Mooseksen kirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Sitten pakkosiirtolaiset viettivät pääsiäistä ensimmäisen kuun neljäntenätoista päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Sillä papit ja leeviläiset olivat yhtenä miehenä puhdistautuneet, niin että he kaikki olivat puhtaat. Ja he teurastivat pääsiäislampaan kaikille pakkosiirtolaisille, veljillensä papeille ja itsellensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'Ja sitä söivät kaikki pakkosiirtolaisuudesta palanneet israelilaiset sekä kaikki, jotka olivat eristäytyneet maassa asuvien pakanain saastaisuudesta ja liittyneet heihin etsiäkseen Herraa, Israelin Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'Ja he viettivät happamattoman leivän juhlaa seitsemän päivää iloiten, sillä Herra oli ilahuttanut heitä, kun oli kääntänyt Assurin kuninkaan sydämen heidän puolellensa, niin että hän avusti heitä Jumalan, Israelin Jumalan, temppelin rakentamistyössä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'Näiden tapausten jälkeen, Persian kuninkaan Artahsastan hallituksen aikana, lähti Esra, Serajan poika, joka oli Asarjan poika, joka Hilkian poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'joka Sallumin poika, joka Saadokin poika, joka Ahitubin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'joka Amarjan poika, joka Asarjan poika, joka Merajotin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'joka Serahjan poika, joka Ussin poika, joka Bukkin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'joka Abisuan poika, joka Piinehaan poika, joka Eleasarin poika, joka Aaronin, ylimmäisen papin, poika-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'tämä Esra lähti Baabelista. Hän oli kirjanoppinut, perehtynyt Mooseksen lakiin, jonka Herra, Israelin Jumala, oli antanut. Ja kuningas antoi hänelle kaikki, mitä hän halusi, koska Esran päällä oli Herran, hänen Jumalansa, käsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'Myös israelilaisia ja pappeja, leeviläisiä, veisaajia, ovenvartijoita ja temppelipalvelijoita lähti Jerusalemiin kuningas Artahsastan seitsemäntenä hallitusvuotena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'Ja hän tuli Jerusalemiin viidennessä kuussa kuninkaan seitsemäntenä hallitusvuotena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Sillä ensimmäisen kuun ensimmäisenä päivänä alkoi lähtö Baabelista; ja viidennen kuun ensimmäisenä päivänä hän tuli Jerusalemiin, koska Jumalan hyvä käsi oli hänen päällänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Sillä Esra oli kiinnittänyt sydämensä Herran lain tutkimiseen, seuratakseen sitä ja opettaakseen Israelissa lakia ja oikeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'Tämä on jäljennös kirjeestä, jonka kuningas Artahsasta antoi pappi Esralle, kirjanoppineelle, joka oli Herran Israelille antamien käskyjen ja ohjeitten tuntija:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '\"Artahsasta, kuningasten kuningas, pappi Esralle, taivaan Jumalan lain tuntijalle\", ja niin edespäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, '\"Minä annan käskyn, että minun valtakunnassani jokainen Israelin kansan jäsen ja sen papit ja leeviläiset, jotka ovat halukkaat lähtemään Jerusalemiin, lähtekööt sinun kanssasi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'koska kuningas ja hänen seitsemän neuvonantajaansa ovat lähettäneet sinut tarkastamaan, ovatko olot Juudassa ja Jerusalemissa sinun Jumalasi lain mukaiset, joka on sinun kädessäsi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'ja viemään sinne hopean ja kullan, minkä kuningas ja hänen neuvonantajansa ovat antaneet vapaaehtoisena lahjana Israelin Jumalalle, jonka asumus on Jerusalemissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'ja myös kaiken hopean ja kullan, minkä saat koko Baabelin maakunnasta, sekä ne vapaaehtoiset lahjat, jotka kansa ja papit antavat Jumalansa temppeliin Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Osta siis näillä rahoilla mitä tunnollisimmin härkiä, oinaita ja karitsoita ynnä niihin kuuluvia ruoka-ja juomauhreja; ja uhraa ne teidän Jumalanne temppelin alttarilla Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'Ja mitä sinä ja sinun veljesi näette hyväksi tehdä hopean ja kullan tähteillä, se tehkää Jumalanne tahdon mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Ne kalut, jotka sinulle annetaan jumalanpalvelusta varten sinun Jumalasi temppelissä, jätä Jerusalemin Jumalan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Ja muut Jumalasi temppelin tarpeet, joita joudut suorittamaan, sinä saat suorittaa kuninkaan aarrekammiosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'Ja minä, kuningas Artahsasta, annan käskyn kaikille aarteistojen vartijoille tuolla puolella Eufrat-virran: \'Kaikki, mitä pappi Esra, taivaan Jumalan lain tuntija, teiltä pyytää, se tunnollisesti toimitettakoon:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'hopeata aina sataan talenttiin, nisuja sataan koor-mittaan, viiniä sataan bat-mittaan, öljyä sataan bat-mittaan saakka, niin myös suoloja ilman määrää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Kaikki, mitä taivaan Jumala käskee, tehtäköön taivaan Jumalan temppelille täsmällisesti, ettei viha kohtaisi kuninkaan ja hänen poikiensa valtakuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Vielä tehdään teille tiettäväksi, ettei kukaan ole oikeutettu vaatimaan rahaveroa, luonnontuotteita tai tierahoja yhdeltäkään papilta tai leeviläiseltä, veisaajalta, ovenvartijalta, temppelipalvelijalta tai muulta tämän Jumalan temppelin tehtäviä toimittavalta.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Ja sinä, Esra, aseta Jumalasi viisauden mukaan, joka on sinun kädessäsi, tuomareita ja lakimiehiä tuomitsemaan kaikkea kansaa tuolla puolella Eufrat-virran, kaikkia, jotka tuntevat sinun Jumalasi lain; ja niille, jotka eivät sitä tunne, opettakaa sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'Ja jokainen, joka ei seuraa sinun Jumalasi lakia ja kuninkaan lakia, tuomittakoon tarkoin harkiten joko kuolemaan tai karkoitukseen, rahasakkoon tai vankeuteen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Kiitetty olkoon Herra, meidän isiemme Jumala, joka on pannut kuninkaan sydämeen, että hänen on kaunistettava Herran temppeliä Jerusalemissa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'ja joka on suonut minun saavuttaa kuninkaan, hänen neuvonantajainsa ja kaikkien kuninkaan mahtavain ruhtinasten suosion. Ja minä rohkaisin mieleni, koska Herran, minun Jumalani, käsi oli minun päälläni, ja minä kokosin Israelista päämiehiä lähtemään kanssani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Nämä olivat ne heidän perhekunta-päämiehensä ja heidän sukuluetteloihinsa merkityt, jotka kuningas Artahsastan hallituksen aikana lähtivät minun kanssani Baabelista:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Piinehaan jälkeläisiä Geersom; Iitamarin jälkeläisiä Daniel; Daavidin jälkeläisiä Hattus;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Sekanjan jälkeläisiä, Paroksen jälkeläisiä, Sakarja ja hänen kanssaan sata viisikymmentä sukuluetteloihin merkittyä miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Pahat-Mooabin jälkeläisiä Eljoenai, Serahjan poika, ja hänen kanssaan kaksisataa miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Sekanjan jälkeläisiä Jahasielin poika ja hänen kanssaan kolmesataa miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Aadinin jälkeläisiä Ebed, Joonatanin poika, ja hänen kanssaan viisikymmentä miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Eelamin jälkeläisiä Jesaja, Ataljan poika, ja hänen kanssaan seitsemänkymmentä miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Sefatjan jälkeläisiä Sebadja, Miikaelin poika, ja hänen kanssaan kahdeksankymmentä miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Jooabin jälkeläisiä Obadja, Jehielin poika, ja hänen kanssaan kaksisataa kahdeksantoista miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Selomitin jälkeläisiä Joosifjan poika ja hänen kanssaan sata kuusikymmentä miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Beebain jälkeläisiä Sakarja, Beebain poika, ja hänen kanssaan kaksikymmentä kahdeksan miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Asgadin jälkeläisiä Joohanan, Hakkatanin poika, ja hänen kanssaan sata kymmenen miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Adonikamin jälkeläisiä myöhemmin tulleet, joiden nimet olivat Elifelet, Jeguel ja Semaja, ja heidän kanssaan kuusikymmentä miestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'Bigvain jälkeläisiä Uutai ja Sabbud ja heidän kanssaan seitsemänkymmentä miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'Ja minä kokosin heidät joelle, joka juoksee Ahavaan päin, ja me olimme siellä leiriytyneinä kolme päivää. Mutta kun minä tarkkasin kansaa ja pappeja, en löytänyt sieltä yhtään leeviläistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Silloin minä lähetin päämiehet Elieserin, Arielin, Semajan, Elnatanin, Jaaribin, Elnatanin, Naatanin, Sakarjan ja Mesullamin sekä opettajat Joojaribin ja Elnatanin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'ja käskin heidän mennä päämies Iddon luo Kaasifjan paikkakunnalle; ja minä panin heidän suuhunsa sanat, jotka heidän oli puhuttava veljilleen Iddolle ja temppelipalvelijoille, Kaasifjan paikkakunnalla, että he toisivat meille palvelijoita meidän Jumalamme temppeliä varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'Ja koska meidän Jumalamme hyvä käsi oli meidän päällämme, toivat he meille ymmärtäväisen miehen, joka oli Mahlin, Leevin pojan ja Israelin pojan pojan, jälkeläisiä, ja Seerebjan poikineen ja veljineen, kahdeksantoista miestä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'ja Hasabjan ja hänen kanssaan Jesajan, joka oli Merarin jälkeläisiä, veljineen ja poikineen, kaksikymmentä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'niin myös temppelipalvelijoista, jotka Daavid ja päämiehet olivat antaneet leeviläisille palvelemaan heitä, kaksisataa kaksikymmentä temppelipalvelijaa, kaikki nimeltä mainittuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Minä kuulutin siellä Ahava-joella paaston, että me nöyrtyisimme Jumalamme edessä ja anoisimme häneltä suotuisaa matkaa itsellemme, vaimoillemme ja lapsillemme ja kaikelle omaisuudellemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Sillä minua hävetti pyytää kuninkaalta sotaväkeä ja ratsumiehiä auttamaan meitä vihollisia vastaan matkalla, koska me olimme sanoneet kuninkaalle näin: \"Meidän Jumalamme käsi on kaikkien päällä, jotka etsivät häntä, heidän parhaakseen; mutta hänen voimansa ja vihansa on kaikkia vastaan, jotka hylkäävät hänet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Niin me paastosimme ja anoimme tätä Jumalaltamme, ja hän kuuli meidän rukouksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Ja minä valitsin pappien päämiehistä kaksitoista, nimittäin Seerebjan ja Hasabjan ja heidän kanssaan kymmenen heidän veljistään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'ja punnitsin heille hopean ja kullan ja kalut, sen antimen, jonka kuningas ja hänen neuvonantajansa ja ruhtinaansa ja kaikki siellä olevat israelilaiset olivat antaneet meidän Jumalamme temppeliä varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Minä punnitsin heille käteen hopeata kuusisataa viisikymmentä talenttia sekä hopeakaluja sata talenttia ja kultaa sata talenttia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'kaksikymmentä kultapikaria, arvoltaan tuhat dareikkia, sekä kaksi hienoa, kullankiiltävää vaskiastiaa, kallisarvoista kuin kulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Ja minä sanoin heille: \"Te olette pyhitetyt Herralle, ja kalut ovat pyhitetyt; ja hopea ja kulta on vapaaehtoinen lahja Herralle, teidän isienne Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Vartioikaa siis niitä ja säilyttäkää ne, kunnes punnitsette ne pappien päämiesten ja leeviläisten ja Israelin perhekunta-päämiesten edessä Jerusalemissa, Herran temppelin kammioissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Niin papit ja leeviläiset ottivat vastaan punnitun hopean ja kullan ja kalut viedäkseen ne Jerusalemiin, meidän Jumalamme temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Sitten me lähdimme liikkeelle Ahava-joelta ensimmäisen kuun kahdentenatoista päivänä mennäksemme Jerusalemiin. Ja meidän Jumalamme käsi oli meidän päällämme, ja hän pelasti meidät vihollisten käsistä ja väijytyksistä tiellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'Ja me tulimme Jerusalemiin ja olimme siellä alallamme kolme päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'Mutta neljäntenä päivänä punnittiin hopea ja kulta ja kalut meidän Jumalamme temppelissä pappi Meremotille, Uurian pojalle, käteen; ja hänen kanssaan oli Eleasar, Piinehaan poika, ja heidän kanssansa leeviläiset Joosabad, Jeesuan poika, ja Nooadja, Binnuin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Kaikki punnittiin lukumäärän ja painon mukaan, ja koko paino kirjoitettiin silloin muistiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Ja vankeudesta tulleet pakkosiirtolaiset uhrasivat polttouhreiksi Israelin Jumalalle kaksitoista härkää koko Israelin puolesta, yhdeksänkymmentä kuusi oinasta, seitsemänkymmentä seitsemän karitsaa ja kaksitoista syntiuhrikaurista, kaikki polttouhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'Ja he jättivät kuninkaan määräykset kuninkaan satraapeille ja käskynhaltijoille, jotka olivat tällä puolella Eufrat-virran, ja nämä avustivat kansaa ja Jumalan temppeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Kun tämä oli suoritettu loppuun, astuivat päämiehet minun tyköni ja sanoivat: \"Ei kansa, ei Israel eivätkä papit ja leeviläiset ole eristäytyneet maan kansoista ja niiden kauhistavista teoista-ei kanaanilaisista, heettiläisistä, perissiläisistä, jebusilaisista, ammonilaisista, mooabilaisista, egyptiläisistä eikä amorilaisista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Sillä näiden tyttäriä he ovat ottaneet itsellensä ja pojillensa vaimoiksi, ja niin on pyhä siemen sekaantunut maan kansoihin. Ja päämiesten ja esimiesten käsi on ollut ensimmäisenä tässä uskottomassa menossa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Kun minä tämän kuulin, repäisin minä vaatteeni ja viittani, revin pääni hiuksia ja partaani ja istuin tyrmistyneenä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Ja minun luokseni kokoontuivat kaikki, jotka pelkäsivät sitä, mitä Israelin Jumala oli puhunut pakkosiirtolaisten uskottomuudesta, ja minä jäin istumaan tyrmistyneenä ehtoouhriin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Mutta ehtoouhrin aikana minä nousin nöyryyttämästä itseäni ja polvistuin, repäisin vaatteeni ja viittani ja ojensin käteni Herran, Jumalani, puoleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'ja minä sanoin: \"Jumalani, minä olen häpeissäni enkä kehtaa kohottaa kasvojani sinun puoleesi, minun Jumalani; sillä meidän rikkomuksemme ovat nousseet päämme ylitse ja meidän syyllisyytemme on kohonnut taivaaseen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Isiemme päivistä aina tähän päivään asti on meidän syyllisyytemme ollut suuri; ja rikkomustemme tähden on meidät, meidän kuninkaamme ja pappimme annettu maan kuningasten käsiin miekan, vankeuden, ryöstön ja häpeän alaisiksi, niinkuin tähän päivään saakka on tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Mutta nyt on meille hetkiseksi tullut armo Herralta, meidän Jumalaltamme, koska hän on sallinut pelastuneen joukon meistä jäädä jäljelle ja antanut meille jalansijan pyhässä paikassansa, että hän, meidän Jumalamme, valaisisi meidän silmämme ja soisi meidän hiukan hengähtää orjuudessamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Sillä orjia me olemme; mutta orjuudessamme ei meidän Jumalamme ole meitä hyljännyt, vaan on suonut meidän saavuttaa Persian kuningasten suosion ja hengähtää, pystyttääksemme Jumalamme temppelin ja kohottaaksemme sen raunioistaan, ja on antanut meille suojatun paikan Juudassa ja Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Ja nyt, Jumalamme, mitä me sanomme kaiken tämän jälkeen? Mehän olemme hyljänneet sinun käskysi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'jotka sinä olet antanut palvelijaisi, profeettain, kautta, sanoen: \'Maa, jota te menette ottamaan omaksenne, se maa on saastainen maan kansojen saastaisuuden tähden ja niitten kauhistavien tekojen tähden, joilla he saastaisuudessansa ovat täyttäneet sen äärestä ääreen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Älkää siis antako tyttäriänne heidän pojillensa älkääkä ottako heidän tyttäriänsä pojillenne vaimoiksi. Älkää myös koskaan harrastako heidän menestystään ja onneansa, että te vahvistuisitte ja saisitte syödä parasta, mitä maassa on, ja jättäisitte sen perinnöksi lapsillenne ikuisiksi ajoiksi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Kaiken sen jälkeen, mikä on meitä kohdannut pahojen tekojemme ja suuren syyllisyytemme tähden-ja kuitenkin sinä, Jumalamme, olet jättänyt huomioon ottamatta meidän rikkomuksiamme ja olet sallinut meistä tämmöisen joukon pelastua-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'kävisimmekö me nyt jälleen rikkomaan sinun käskyjäsi ja lankoutumaan kansojen kanssa, joiden teot ovat kauhistavaiset? Etkö sinä silloin vihastuisi meihin siihen asti, että tekisit meistä lopun, niin ettei ketään jäisi jäljelle eikä kukaan pelastuisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'Herra, Israelin Jumala, sinä olet vanhurskas, sillä meistä on jäljellä pelastuneita vain sen verran, kuin tänä päivänä on. Katso, me olemme sinun edessäsi syyllisyydessämme; emmekä me tämän tähden voi sinun edessäsi kestää.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'Kun Esra näin rukoili ja tunnusti, itkien ja maahan langeten, Jumalan temppelin edustalla, kokoontui hänen luoksensa sangen suuri joukko Israelin miehiä, naisia ja lapsia; sillä kansakin itki katkerasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Ja Sekanja, Jehielin poika, Eelamin jälkeläisiä, puhkesi puhumaan ja sanoi Esralle: \"Me olemme olleet uskottomat Jumalaamme kohtaan, kun olemme ottaneet muukalaisia vaimoja maan kansoista. Mutta kuitenkin on Israelilla vielä toivoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Niin tehkäämme nyt Jumalamme kanssa liitto, että me Herran neuvon mukaan ja niiden neuvon mukaan, jotka pelkäävät meidän Jumalamme käskyä, toimitamme pois kaikki ne vaimot ja heistä syntyneet lapset; tehtäköön lain mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Nouse, sillä tämä on sinun asiasi, ja me olemme sinun kanssasi. Ole luja ja ryhdy toimeen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Niin Esra nousi ja vannotti pappien päämiehet, leeviläiset ja kaiken Israelin tekemään näin. Ja he vannoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'Niin Esra nousi Jumalan temppelin edustalta ja meni Joohananin, Eljasibin pojan, kammioon. Sinne tultuaan hän ei syönyt leipää eikä juonut vettä, sillä niin hän suri pakkosiirtolaisten uskottomuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Ja kaikille pakkosiirtolaisille kuulutettiin Juudassa ja Jerusalemissa, että heidän tuli kokoontua Jerusalemiin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'ja joka ei tullut kolmen päivän kuluessa, päämiesten ja vanhinten päätöksen mukaan, sen koko omaisuus oli vihittävä tuhon omaksi ja hän itse tuleva erotetuksi pakkosiirtolaisten seurakunnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Niin kaikki Juudan ja Benjaminin miehet kokoontuivat Jerusalemiin kolmanneksi päiväksi, joka oli yhdeksännen kuun kahdeskymmenes päivä. Ja kaikki kansa asettui Jumalan temppelin aukealle, vavisten sekä asian tähden että rankkasateen vuoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Ja pappi Esra nousi ja sanoi heille: \"Te olette olleet uskottomat, kun olette ottaneet muukalaisia vaimoja, ja niin te olette lisänneet Israelin syyllisyyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Mutta antakaa nyt Herralle, isienne Jumalalle, kunnia ja tehkää hänen tahtonsa: eristäytykää maan kansoista ja muukalaisista vaimoista.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'Niin koko seurakunta vastasi ja sanoi suurella äänellä: \"Niinkuin sinä olet puhunut, niin on meidän tehtävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Mutta kansaa on paljon, ja on sadeaika, niin ettei voida seisoa ulkona. Eikä tämä ole yhden tai kahden päivän toimitus, sillä me olemme paljon siinä asiassa rikkoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Käykööt meidän päämiehemme esiin koko seurakunnan puolesta, ja kaikki, jotka kaupungeissamme ovat ottaneet muukalaisia vaimoja, tulkoot tänne määrättyinä aikoina ja heidän kanssansa kunkin kaupungin vanhimmat ja tuomarit, kunnes meistä on käännetty pois Jumalan viha, joka on syttynyt tämän asian tähden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Ainoastaan Joonatan, Asaelin poika, ja Jahseja, Tikvan poika, nousivat tätä vastustamaan, ja Mesullam ja leeviläinen Sabbetai kannattivat heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Mutta pakkosiirtolaiset tekivät näin, ja valittiin pappi Esra sekä miehiä, perhekunta-päämiehiä, perhekuntien mukaan, kaikki nimeltään mainittuja. Kymmenennen kuun ensimmäisenä päivänä he istuivat tutkimaan asiaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'ja ensimmäisen kuun ensimmäiseen päivään he olivat selvillä kaikista miehistä, jotka olivat ottaneet muukalaisia vaimoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'Pappien poikia, jotka olivat ottaneet muukalaisia vaimoja, havaittiin olevan: Jeesuan, Joosadakin pojan, jälkeläisiä ja hänen veljiään: Maaseja, Elieser, Jaarib ja Gedalja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'jotka kättä lyöden lupasivat toimittaa pois vaimonsa ja syyllisinä uhrata oinaan syyllisyytensä sovittamiseksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'Immerin jälkeläisiä Hanani ja Sebadja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'Haarimin jälkeläisiä Maaseja, Elia, Semaja, Jehiel ja Ussia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'Pashurin jälkeläisiä Eljoenai, Maaseja, Ismael, Netanel, Joosabad ja Elasa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'Leeviläisiä: Joosabad, Siimei, Kelaja, se on Kelita, Petahja, Juuda ja Elieser.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'Veisaajia: Eljasib. Ovenvartijoita: Sallum, Telem ja Uuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'Israelilaisia: Paroksen jälkeläisiä Ramja, Jissia, Malkia, Miijamin, Elasar, Malkia ja Benaja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'Eelamin jälkeläisiä Mattanja, Sakarja, Jehiel, Abdi, Jeremot ja Elia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'Sattun jälkeläisiä Eljoenai, Eljasib, Mattanja, Jeremot, Saabad ja Asisa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'Beebain jälkeläisiä Joohanan, Hananja, Sabbai ja Atlai;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'Baanin jälkeläisiä Mesullam, Malluk, Adaja, Jaasub, Seal ja Jeramot;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'Pahat-Mooabin jälkeläisiä Adna, Kelal, Benaja, Maaseja, Mattanja, Besalel, Binnui ja Manasse;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'Haarimin jälkeläisiä Elieser, Jissia, Malkia, Semaja, Simeon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Malluk ja Semarja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Haasumin jälkeläisiä Mattenai, Mattatta, Saabad, Elifelet, Jeremai, Manasse ja Siimei;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Baanin jälkeläisiä Maadai, Amram, Uuel,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Beedja, Keluhu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vanja, Meremot, Eljasib,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattanja, Mattenai, Jaasai,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Baani, Binnui, Siimei,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemja, Naatan, Adaja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Maknadbai, Saasai, Saarai,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Asarel, Selemja, Semarja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amarja ja Joosef;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Nebon jälkeläisiä Jegiel, Mattitja, Saabad, Sebina, Jaddai, Jooel ja Benaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Nämä kaikki olivat ottaneet muukalaisia vaimoja; ja osa näistä vaimoista oli synnyttänyt lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Nehemian, Hakaljan pojan, kertomus. Kislev-kuussa, kahdentenakymmenentenä vuotena, minun ollessani Suusanin linnassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'tuli Hanani, eräs minun veljistäni, ja muita miehiä Juudasta. Ja minä kyselin heiltä juutalaisista, siitä pelastuneesta joukosta, joka vankeudesta palanneena oli jäljellä, ja Jerusalemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'Ja he sanoivat minulle: \"Jotka vankeudesta palanneina ovat jäljellä siinä maakunnassa, ne ovat suuressa kurjuudessa ja häväistyksen alaisina; ja Jerusalemin muuri on revitty maahan, ja sen portit ovat tulella poltetut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'Tämän kuultuani minä istuin monta päivää itkien ja murehtien, ja minä paastosin ja rukoilin taivaan Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'Minä sanoin: \"Oi Herra, taivaan Jumala, sinä suuri ja peljättävä Jumala, joka pidät liiton ja säilytät laupeuden niille, jotka sinua rakastavat ja noudattavat sinun käskyjäsi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'olkoon sinun korvasi tarkkaavainen ja silmäsi avoin kuullaksesi palvelijasi rukoukset, joita minä nyt päivät ja yöt rukoilen sinun edessäsi palvelijaisi, israelilaisten, puolesta, tunnustaen israelilaisten synnit, jotka me olemme tehneet sinua vastaan; sillä minäkin ja minun perhekuntani olemme syntiä tehneet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Me olemme pahoin tehneet sinua vastaan; emme ole noudattaneet käskyjä, säädöksiä ja oikeuksia, jotka sinä annoit palvelijallesi Moosekselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Muista sana, jonka sinä annoit palvelijallesi Moosekselle, sanoen: \'Jos te tulette uskottomiksi, niin minä hajotan teidät kansojen sekaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'mutta jos te palajatte minun tyköni, noudatatte minun käskyjäni ja seuraatte niitä, niin vaikka teidän karkoitettunne olisivat taivaan ääressä, minä heidät sieltäkin kokoan ja tuon heidät siihen paikkaan, jonka minä olen valinnut nimeni asuinsijaksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Ovathan he sinun palvelijasi ja sinun kansasi, jotka sinä vapahdit suurella voimallasi ja väkevällä kädelläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Oi Herra, tarkatkoon sinun korvasi palvelijasi rukousta ja niiden palvelijaisi rukousta, jotka tahtovat peljätä sinun nimeäsi! Anna tänä päivänä palvelijasi hankkeen menestyä ja suo hänen saada armo sen miehen edessä.\" Minä olin näet kuninkaan juomanlaskija.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Niisan-kuussa, kuningas Artahsastan kahdentenakymmenentenä hallitusvuotena, kun viini oli hänen edessään, otin minä viinin ja annoin sen kuninkaalle. Kun minä en ollut ennen ollut hänen edessään murheellisena,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'sanoi kuningas minulle: \"Minkätähden sinä olet niin murheellisen näköinen? Ethän ole sairas; sinulla on varmaan jokin sydämensuru.\" Silloin minä peljästyin kovin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'mutta minä sanoin kuninkaalle: \"Eläköön kuningas iankaikkisesti. Kuinka minä en olisi murheellisen näköinen, kun se kaupunki, jossa minun isieni haudat ovat, on autio ja sen portit tulella poltetut?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Kuningas sanoi minulle: \"Mitä sinä siis pyydät?\" Niin minä rukoilin taivaan Jumalaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'ja sanoin kuninkaalle: \"Jos kuningas hyväksi näkee ja jos olet mielistynyt palvelijaasi, niin lähetä minut Juudaan, siihen kaupunkiin, jossa minun isieni haudat ovat, rakentamaan sitä uudestaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Niin kuningas kysyi minulta, kuningattaren istuessa hänen vieressään: \"Kuinka kauan sinun matkasi kestäisi ja milloin voisit palata?\" Kun siis kuningas näki hyväksi lähettää minut, ilmoitin minä hänelle määrätyn ajan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Ja minä sanoin kuninkaalle: \"Jos kuningas hyväksi näkee, niin annettakoon minun mukaani kirjeet Eufrat-virran tuonpuoleisen maan käskynhaltijoille, että he sallivat minun kulkea sen kautta perille Juudaan asti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'samoin kirje Aasafille, kuninkaan puiston vartijalle, että hän antaa minulle hirsiä temppelilinnan porttien kattamista varten sekä kaupungin muuria ja sitä taloa varten, johon menen asumaan\". Ja kuningas myönsi minulle sen, koska minun Jumalani hyvä käsi oli minun päälläni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'Kun minä sitten tulin Eufrat-virran tämänpuoleisen maan käskynhaltijain luo, annoin minä heille kuninkaan kirjeet. Ja kuningas oli lähettänyt minun kanssani sotapäälliköitä ja ratsumiehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Mutta kun hooronilainen Sanballat ja ammonilainen virkamies Tobia sen kuulivat, pahastuivat he kovin siitä, että oli tullut joku, joka harrasti israelilaisten parasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Ja tultuani Jerusalemiin ja oltuani siellä kolme päivää');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'minä nousin yöllä, ja muutamat miehet minun kanssani, ilmoittamatta kenellekään, mitä Jumalani oli pannut minun sydämeeni ja määrännyt tehtäväksi Jerusalemille. Eikä minulla ollut mukanani muuta juhtaakaan kuin se juhta, jolla minä ratsastin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'Ja minä lähdin yöllä Laaksoportista Lohikäärmelähteelle päin ja Lantaportille ja tarkastelin Jerusalemin maahanrevittyjä muureja ja sen tulella poltettuja portteja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Ja minä kuljin eteenpäin Lähdeportille ja Kuninkaanlammikolle; mutta siellä ei ollut juhdalla, jonka selässä minä istuin, tilaa päästä eteenpäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Silloin minä menin yöllä laaksoa myöten ylöspäin ja tarkastin muuria. Sitten minä palasin taas Laaksoportin kautta ja tulin takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Mutta esimiehet eivät tietäneet, mihin minä olin mennyt ja mitä tein, sillä minä en ollut vielä ilmaissut mitään kenellekään, en juutalaisille, en papeille, ylimyksille, esimiehille enkä muille, joiden oli oltava mukana siinä työssä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Mutta nyt minä sanoin heille: \"Te näette, missä kurjuudessa me olemme, kun Jerusalem on autio ja sen portit tulella poltetut. Tulkaa, rakentakaamme uudestaan Jerusalemin muuri, ettemme enää olisi häväistyksen alaiset.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'Ja minä kerroin heille, kuinka minun Jumalani hyvä käsi oli ollut minun päälläni ja myös mitä kuningas oli minulle sanonut. Niin he sanoivat: \"Nouskaamme ja rakentakaamme\". Ja he saivat rohkeuden käydä käsiksi tähän hyvään työhön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Mutta kun hooronilainen Sanballat ja ammonilainen virkamies Tobia ja arabialainen Gesem sen kuulivat, pilkkasivat he meitä, osoittivat meille halveksumistaan ja sanoivat: \"Mitä te siinä teette? Kapinoitteko te kuningasta vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Silloin minä vastasin ja sanoin heille: \"Taivaan Jumala on antava meille menestystä, ja me, hänen palvelijansa, nousemme ja rakennamme. Mutta teillä ei ole mitään osuutta eikä oikeutta Jerusalemiin, eikä teidän muistonne ole siellä pysyvä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Ylimmäinen pappi Eljasib ja hänen veljensä, papit, nousivat ja rakensivat Lammasportin, jonka he pyhittivät ja jonka ovet he asettivat paikoilleen, edelleen Hammea-torniin asti, jonka he pyhittivät, ja edelleen Hananelin-torniin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'Heistä eteenpäin rakensivat Jerikon miehet; ja näistä eteenpäin rakensi Sakkur, Imrin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Ja Kalaportin rakensivat senaalaiset; he kattoivat sen ja asettivat paikoilleen sen ovet, teljet ja salvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Heistä eteenpäin korjasi muuria Meremot, Uurian poika, joka oli Koosin poika; hänestä eteenpäin korjasi Mesullam, Berekjan poika, joka oli Mesesabelin poika; ja hänestä eteenpäin korjasi Saadok, Baanan poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Hänestä eteenpäin korjasivat muuria tekoalaiset; mutta heidän ylhäisensä eivät notkistaneet niskaansa Herransa palvelukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'Vanhan portin korjasivat Joojada, Paaseahin poika, ja Mesullam, Besodjan poika; he kattoivat sen ja asettivat paikoilleen sen ovet, teljet ja salvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'Heistä eteenpäin korjasivat muuria gibeonilainen Melatja ja meeronotilainen Jaadon sekä Gibeonin ja Mispan miehet, jotka olivat Eufrat-virran tämänpuoleisen käskynhaltijan vallan alaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Heistä eteenpäin korjasi muuria Ussiel, Harhajan poika, yksi kultasepistä, ja hänestä eteenpäin korjasi Hananja, yksi voiteensekoittajista; he panivat kuntoon Jerusalemia Leveään muuriin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'Heistä eteenpäin korjasi muuria Refaja, Huurin poika, Jerusalemin piirin toisen puolen päällikkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'Hänestä eteenpäin korjasi Jedaja, Harumafin poika, oman talonsa kohdalta; hänestä eteenpäin korjasi Hattus, Hasabnejan poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Toisen osan korjasivat Malkia, Haarimin poika, ja Hassub, Pahat-Mooabin poika, sekä sen lisäksi Uunitornin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'Heistä eteenpäin korjasi Sallum, Looheksen poika, Jerusalemin piirin toisen puolen päällikkö, hän ja hänen tyttärensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Laaksoportin korjasivat Haanun ja Saanoahin asukkaat; he rakensivat sen ja asettivat paikoilleen sen ovet, teljet ja salvat. Sen lisäksi he korjasivat tuhat kyynärää muuria, Lantaporttiin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Lantaportin korjasi Malkia, Reekabin poika, Beet-Keremin piirin päällikkö; hän rakensi sen ja asetti paikoilleen sen ovet, teljet ja salvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Lähdeportin korjasi Sallum, Kolhoosen poika, Mispan piirin päällikkö; hän rakensi sen, teki siihen katon ja asetti paikoilleen sen ovet, teljet ja salvat. Sen lisäksi hän korjasi Vesijohtolammikon muurin, kuninkaan puutarhan luota, aina niihin portaisiin saakka, jotka laskeutuvat Daavidin kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Hänen jälkeensä korjasi Nehemia, Asbukin poika, Beet-Suurin piirin toisen puolen päällikkö, aina Daavidin hautojen kohdalle ja Tekolammikolle ja Urhojentalolle saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Hänen jälkeensä korjasivat muuria leeviläiset: Rehum, Baanin poika; hänestä eteenpäin korjasi Hasabja, Kegilan piirin toisen puolen päällikkö, piirinsä puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Hänen jälkeensä korjasivat heidän veljensä: Bavvai, Heenadadin poika, joka oli Kegilan piirin toisen puolen päällikkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'Hänestä eteenpäin korjasi Eeser, Jeesuan poika, Mispan päällikkö, toisen osan, siltä kohdalta, mistä noustaan asehuoneeseen, joka on Kulmauksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Hänen jälkeensä korjasi Baaruk, Sabbain poika, suurella innolla toisen osan, Kulmauksesta aina ylimmäisen papin Eljasibin talon oveen saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Hänen jälkeensä korjasi Meremot, Uurian poika, joka oli Koosin poika, toisen osan, Eljasibin talon ovesta Eljasibin talon päähän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'Hänen jälkeensä korjasivat papit, Lakeuden miehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Heidän jälkeensä korjasivat Benjamin ja Hassub oman talonsa kohdalta; heidän jälkeensä korjasi Asarja, Maasejan poika, joka oli Ananjan poika, talonsa viereltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Hänen jälkeensä korjasi Binnui, Heenadadin poika, toisen osan, Asarjan talosta aina Kulmaukseen ja kulmaan saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Paalal, Uusain poika, korjasi Kulmauksen ja Ylätornin kohdalta, joka ulkonee kuninkaan linnasta vankilan pihaan päin; hänen jälkeensä Pedaja, Paroksen poika');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, '-temppelipalvelijat asuivat Oofelilla-itäisen Vesiportin ja ulkonevan tornin kohdalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Hänen jälkeensä korjasivat tekoalaiset toisen osan, suuren, ulkonevan tornin kohdalta aina Oofelin muuriin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Hevosportin yläpuolelta korjasivat papit, kukin oman talonsa kohdalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Heidän jälkeensä korjasi Saadok, Immerin poika, oman talonsa kohdalta. Ja hänen jälkeensä korjasi Semaja, Sekanjan poika, Itäportin vartija.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Hänen jälkeensä korjasivat Hananja, Selemjan poika, ja Haanun, Saalafin kuudes poika, toisen osan; hänen jälkeensä korjasi Mesullam, Berekjan poika, yliskammionsa kohdalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Hänen jälkeensä korjasi Malkia, yksi kultasepistä, temppelipalvelijain ja kauppiasten taloon asti, Vartiotornin kohdalta, ja aina Kulmasaliin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'Kultasepät ja kauppiaat korjasivat muurin Kulmasalin ja Lammasportin väliltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'Kun Sanballat kuuli meidän rakentavan muuria, vihastui hän ja närkästyi kovin. Ja hän pilkkasi juutalaisia');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'ja puhui veljilleen ja Samarian sotaväelle ja sanoi: \"Mitä nuo viheliäiset juutalaiset tekevät? Jätetäänkö heidät omiin valtoihinsa? Tulevatko he uhraamaan? Saavatko he työnsä kohta valmiiksi? Voivatko he tehdä eläviksi poltetut kivet tuhkaläjissä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Ja ammonilainen Tobia seisoi hänen vieressään ja sanoi: \"Rakentakoot vain! Kettukin saa heidän kivimuurinsa hajoamaan, jos hyppää sen päälle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Kuule, Jumalamme, kuinka halveksitut me olemme. Käännä heidän häpäisynsä heidän omaan päähänsä. Saata heidät ryöstetyiksi vankeuden maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Älä peitä heidän rikkomustansa, älköönkä heidän syntiänsä pyyhittäkö pois sinun kasvojesi edestä, koska he ovat vihoittaneet sinut kohtelemalla noin rakentajia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Mutta me rakensimme muuria; ja koko muuri tuli valmiiksi puoleen korkeuteensa asti, ja siitä kansa sai rohkeutta työhön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Mutta kun Sanballat, Tobia, arabialaiset, ammonilaiset ja asdodilaiset kuulivat, että Jerusalemin muurien korjaus edistyi, niin että niiden aukot alkoivat täyttyä, vihastuivat he kovin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Ja he kaikki tekivät liiton keskenään käydäksensä taisteluun Jerusalemia vastaan ja tehdäkseen siellä häiriötä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Niin me rukoilimme Jumalaamme ja asetimme vartijat heitä vastaan, suojelemaan itseämme heiltä päivin ja öin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Mutta Juuda sanoi: \"Taakankantajain voima raukeaa, ja soraa on ylen paljon; me emme jaksa rakentaa muuria\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Ja meidän vastustajamme sanoivat: \"Ennenkuin he tietävät tai huomaavat, me tulemme heidän keskellensä ja tapamme heidät ja lopetamme työn\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Mutta kun heidän läheisyydessään asuvat juutalaiset tulivat ja sanoivat meille joka taholta kymmenenkin kertaa: \"Vetäytykää meidän luoksemme\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'silloin minä asetin kansan muurin taakse, alempiin ja suojattomiin paikkoihin, asetin heidät sukukunnittain asemiinsa miekkoineen, keihäineen ja jousineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'Ja katsastettuani kaiken minä nousin ja sanoin ylimyksille ja esimiehille ja muulle kansalle: \"Älkää peljätkö heitä; muistakaa suurta ja peljättävää Herraa, ja taistelkaa veljienne, poikienne ja tyttärienne, vaimojenne ja kotienne puolesta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Sitten kuin vihollisemme olivat kuulleet, että me olimme saaneet tietää asian ja että Jumala oli tehnyt heidän hankkeensa tyhjäksi, palasimme me kaikki takaisin muurille, itsekukin työhönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'Siitä päivästä alkaen teki toinen puoli minun palvelijoitani työtä, ja toinen puoli oli asestettuna keihäillä, kilvillä, jousilla ja rintahaarniskoilla; ja päämiehet seisoivat kaikkien niiden juutalaisten takana,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'jotka rakensivat muurilla. Nekin, jotka kantoivat taakkoja ja kuljettivat kuormia, tekivät toisella kädellänsä työtä ja toisessa pitivät keihästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'Ja rakentajilla oli kullakin miekka sidottuna vyöllensä heidän rakentaessaan; ja torvensoittaja seisoi minun vieressäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Minä sanoin ylimyksille, esimiehille ja muulle kansalle: \"Työ on suuri ja laaja, ja me olemme muurilla hajallamme, kaukana toisistamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'Missä kuulette torven soivan, sinne kokoontukaa meidän luoksemme. Meidän Jumalamme sotii meidän puolestamme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Näin me siis teimme työtä, ja toinen puoli väkeä oli asestettuna keihäillä päivänkoitosta siihen asti, kunnes tähdet tulivat näkyviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Siihen aikaan minä myös sanoin kansalle: \"Kukin jääköön palvelijoineen yöksi Jerusalemiin, että he olisivat meidän apunamme yöllä vartioimassa ja päivällä työssä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Emmekä me, en minä, eivät minun veljeni ja palvelijani eivätkä ne vartijat, jotka minua seurasivat, riisuneet vaatteitamme. Kullakin keihäs ja vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'Mutta rahvas ja heidän vaimonsa nostivat suuren huudon juutalaisia veljiänsä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Muutamat sanoivat: \"Meitä, meidän poikiamme ja tyttäriämme on paljon. Meidän täytyy saada viljaa, että meillä olisi mitä syödä pysyäksemme hengissä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Toiset sanoivat: \"Peltomme, viinitarhamme ja talomme meidän täytyy pantata saadaksemme viljaa nälkäämme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Toiset sanoivat: \"Meidän on täytynyt kuninkaan veroihin lainata rahaa peltojamme ja viinitarhojamme vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Ovathan meidän ruumiimme veljiemme ruumiitten veroiset ja lapsemme heidän lastensa veroiset; ja katso, kuitenkin meidän täytyy antaa poikamme ja tyttäremme orjiksi, ja tyttäriämme on jo annettukin orjuuteen, emmekä me voi sille mitään, koska peltomme ja viinitarhamme ovat toisten käsissä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Kun minä kuulin heidän valituksensa ja nämä puheet, vihastuin minä kovin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'Ja harkittuani mielessäni tätä asiaa minä nuhtelin ylimyksiä ja esimiehiä ja sanoin heille: \"Tehän kiskotte korkoa, kukin veljeltänne\". Sitten minä panin toimeen suuren kokouksen heitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'Ja minä sanoin heille: \"Me olemme, sen mukaan kuin olemme voineet, ostaneet vapaiksi juutalaisia veljiämme, jotka oli myyty pakanoille. Tekö nyt myytte veljiänne, ja täytyykö heidän myydä itsensä meille?\" He olivat vaiti eivätkä voineet vastata mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Ja minä sanoin: \"Ette te siinä tee hyvin. Teidänhän tulisi vaeltaa meidän Jumalamme pelossa jo pakanain, meidän vihollistemme, häväistyksen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Myöskin minä, minun veljeni ja palvelijani olemme lainanneet heille rahaa ja viljaa; luopukaamme tästä saatavasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Luovuttakaa heille jo tänä päivänä heidän peltonsa, viinitarhansa, öljypuunsa ja talonsa, ja luopukaa rahan korosta sekä viljasta, viinistä ja öljystä, jonka olette heille lainanneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'He vastasivat: \"Me luovutamme ne emmekä vaadi heiltä mitään; me teemme, niinkuin olet sanonut\". Ja minä kutsuin papit ja vannotin heidät tekemään näin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Minä myös pudistin helmukseni ja sanoin: \"Jokaisen, joka ei tätä sanaa täytä, pudistakoon Jumala näin pois hänen talostansa ja vaivannäkönsä hedelmistä; näin hän tulkoon pudistetuksi ja tyhjennetyksi\". Ja koko seurakunta sanoi: \"Amen\", ja ylisti Herraa. Ja kansa teki, niinkuin oli sanottu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Myöskään en minä eivätkä veljeni siitä päivästä asti, jona minut määrättiin olemaan heidän käskynhaltijanaan Juudan maassa, siis kuningas Artahsastan kahdennestakymmenennestä hallitusvuodesta aina hänen kolmanteenkymmenenteen toiseen hallitusvuoteensa saakka, eli kahtenatoista vuotena, syöneet käskynhaltijalle tulevaa ruokaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Sillä aikaisemmat käskynhaltijat, jotka olivat olleet ennen minua, olivat rasittaneet kansaa ja ottaneet siltä leipää ja viiniä sekä vielä neljäkymmentä hopeasekeliä. Myöskin heidän palvelijansa olivat sortaneet kansaa. Mutta minä en tehnyt niin, sillä minä pelkäsin Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Myöskin kävin minä itse käsiksi tämän muurin tekoon. Ja me emme ostaneet mitään peltoa. Ja kaikki minun palvelijani olivat kokoontuneet sinne työhön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Myös sata viisikymmentä miestä, juutalaisia ja esimiehiä, söi minun pöydässäni sekä ne, jotka ympärillämme olevista pakanakansoista tulivat meidän luoksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Ja mitä päivittäin valmistettiin ruuaksi, nimittäin härkä ja kuusi valiolammasta sekä lintuja, se valmistettiin minun kustannuksellani; ja joka kymmenes päivä hankittiin kaikenlaisia viinejä viljalti. Mutta siitä huolimatta minä en vaatinut itselleni käskynhaltijalle tulevaa ruokaa, koska työ painoi raskaasti tätä kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Muista, Jumalani, minun hyväkseni kaikki, mitä minä olen tehnyt tämän kansan puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Kun Sanballat, Tobia, arabialainen Gesem ja meidän muut vihollisemme kuulivat, että minä olin rakentanut muurin ja ettei siinä enää ollut aukkoa-vaikken minä ollutkaan vielä siihen aikaan asettanut ovia paikoilleen portteihin-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'niin Sanballat ja Gesem lähettivät minulle sanan: \"Tule, kohdatkaamme toisemme Kefirimissä, Oonon laaksossa\". He näet ajattelivat tehdä minulle pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Niin minä lähetin heidän luokseen sanansaattajat ja käskin sanoa: \"Minulla on suuri työ tekeillä, niin etten voi tulla. Keskeytyisihän työ, jos minä jättäisin sen ja tulisin teidän luoksenne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Ja he lähettivät minulle saman sanan neljä kertaa, mutta minä vastasin heille aina samalla tavalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Silloin Sanballat lähetti viidennen kerran palvelijansa minun luokseni samassa asiassa, ja tällä oli kädessään avoin kirje.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'Siihen oli kirjoitettu: \"Kansojen kesken huhuillaan, ja myös Gasmu sanoo, että sinä ja juutalaiset suunnittelette kapinaa. Sentähden sinä rakennat muuria, ja itse sinä pyrit heidän kuninkaaksensa-niin kerrotaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Myöskin olet hankkinut profeettoja julistamaan itsestäsi Jerusalemissa näin: \'Juudassa on kuningas\'. Tämän nyt kuningas saa kuulla; tule siis ja neuvotelkaamme keskenämme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Silloin minä lähetin hänelle sanan: \"Ei ole tapahtunut mitään semmoista, mistä puhut, vaan sinä olet keksinyt sen omasta päästäsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'He näet kaikki peloittelivat meitä arvellen: \"Heidän kätensä herpoavat työssä, ja se jää tekemättä\". Mutta vahvista sinä minun käteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'Minä menin Semajan, Delajan pojan, Mehetabelin pojanpojan, taloon, hänen ollessaan eristettynä. Hän sanoi: \"Menkäämme yhdessä Jumalan temppeliin, temppelisaliin, ja sulkekaamme temppelisalin ovet. Sillä he tulevat tappamaan sinua; yöllä he tulevat ja tappavat sinut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Mutta minä vastasin: \"Pakenisiko minunlaiseni mies? Tahi kuinka voisi minunlaiseni mies mennä temppeliin ja kuitenkin jäädä eloon? Minä en mene.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'Minä näet ymmärsin, ettei Jumala ollut häntä lähettänyt, vaan että hän oli lausunut minulle sen ennustuksen siitä syystä, että Tobia ja Sanballat olivat palkanneet hänet:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'hänet oli palkattu siinä tarkoituksessa, että minä peljästyisin ja menettelisin sillä tavalla ja niin tekisin syntiä; siitä he saisivat panettelun aiheen, häväistäkseen minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Muista, Jumalani, Tobiaa ja Sanballatia näiden heidän tekojensa mukaan, niin myös naisprofeetta Nooadjaa ja muita profeettoja, jotka minua peloittelivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'Muuri valmistui elul-kuun kahdentenakymmenentenä viidentenä päivänä, viidenkymmenen kahden päivän kuluttua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'Kun kaikki meidän vihollisemme sen kuulivat, ja kaikki ympärillämme asuvat kansat näkivät sen, havaitsivat he joutuneensa aivan alakynteen; sillä he tunsivat, että tämä työ oli suoritettu meidän Jumalamme avulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Niinä päivinä meni myös Juudan ylimyksiltä lukuisia kirjeitä Tobialle, ja Tobialta tuli kirjeitä heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Sillä Juudassa oli monta, jotka olivat valalla liittoutuneet hänen kanssansa; sillä hän oli Sekanjan, Aarahin pojan, vävy, ja hänen poikansa Joohanan oli ottanut vaimokseen Mesullamin, Berekjan pojan, tyttären.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'He myös puhuivat minulle hyvää hänestä ja veivät minun puheeni hänelle. Kirjeitäkin Tobia lähetti peloitellakseen minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'Kun muuri oli rakennettu, asetin minä ovet paikoillensa; ja niiden vartioimisen saivat ovenvartijat, veisaajat ja leeviläiset tehtäväkseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Ja Jerusalemin päämiehiksi minä asetin veljeni Hananin ja linnanpäällikön Hananjan, sillä hän oli luotettava mies ja pelkäsi Jumalaa enemmän kuin moni muu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'Ja minä sanoin heille: \"Jerusalemin portteja älköön avattako, ennenkuin aurinko on polttavimmillaan; ja vartijain vielä seisoessa paikoillaan on ovet suljettava ja salvoilla teljettävä. Ja Jerusalemin asukkaita pantakoon vartioimaan, kukin vartiopaikallensa, kukin oman talonsa kohdalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Kaupunki oli joka suuntaan tilava ja suuri, mutta väkeä siinä oli vähän, ja taloja oli vielä rakentamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Niin Jumala antoi minun sydämeeni, että minun oli koottava ylimykset, esimiehet ja kansa sukuluetteloon merkittäviksi. Silloin minä löysin niiden sukuluettelon, jotka ensin olivat tulleet sinne, ja huomasin siihen kirjoitetun:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, '\"Nämä ovat tämän maakunnan asukkaat, jotka lähtivät pakkosiirtolaisten vankeudesta, johon Nebukadnessar, Baabelin kuningas, oli heidät vienyt, ja palasivat Jerusalemiin ja Juudaan, kukin kaupunkiinsa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'ne, jotka tulivat Serubbaabelin, Jeesuan, Nehemian, Asarjan, Raamian, Nahamanin, Mordokain, Bilsanin, Misperetin, Bigvain, Nehumin ja Baanan kanssa. Israelin kansan miesten lukumäärä oli:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Paroksen jälkeläisiä kaksituhatta sata seitsemänkymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Sefatjan jälkeläisiä kolmesataa seitsemänkymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Aarahin jälkeläisiä kuusisataa viisikymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Pahat-Mooabin jälkeläisiä, nimittäin Jeesuan ja Jooabin jälkeläisiä, kaksituhatta kahdeksansataa kahdeksantoista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Eelamin jälkeläisiä tuhat kaksisataa viisikymmentä neljä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Sattun jälkeläisiä kahdeksansataa neljäkymmentä viisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Sakkain jälkeläisiä seitsemänsataa kuusikymmentä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Binnuin jälkeläisiä kuusisataa neljäkymmentä kahdeksan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Beebain jälkeläisiä kuusisataa kaksikymmentä kahdeksan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Asgadin jälkeläisiä kaksituhatta kolmesataa kaksikymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Adonikamin jälkeläisiä kuusisataa kuusikymmentä seitsemän;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Bigvain jälkeläisiä kaksituhatta kuusikymmentä seitsemän;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Aadinin jälkeläisiä kuusisataa viisikymmentä viisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Aaterin, nimittäin Hiskian, jälkeläisiä yhdeksänkymmentä kahdeksan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Haasumin jälkeläisiä kolmesataa kaksikymmentä kahdeksan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Beesain jälkeläisiä kolmesataa kaksikymmentäneljä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Haarifin jälkeläisiä sata kaksitoista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'gibeonilaisia yhdeksänkymmentä viisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Beetlehemin ja Netofan miehiä sata kahdeksankymmentä kahdeksan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Anatotin miehiä sata kaksikymmentä kahdeksan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Beet-Asmavetin miehiä neljäkymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Kirjat-Jearimin, Kefiran ja Beerotin miehiä seitsemänsataa neljäkymmentä kolme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Raaman ja Geban miehiä kuusisataa kaksikymmentä yksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Mikmaan miehiä sata kaksikymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Beetelin ja Ain miehiä sata kaksikymmentä kolme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'toisen Nebon miehiä viisikymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'toisen Eelamin jälkeläisiä tuhat kaksisataa viisikymmentä neljä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Haarimin jälkeläisiä kolmesataa kaksikymmentä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'jerikolaisia kolmesataa neljäkymmentä viisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'loodilaisia, haadidilaisia ja oonolaisia seitsemänsataa kaksikymmentä yksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'senaalaisia kolmetuhatta yhdeksänsataa kolmekymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Pappeja oli: Jedajan jälkeläisiä, nimittäin Jesuan sukua, yhdeksänsataa seitsemänkymmentä kolme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Immerin jälkeläisiä tuhat viisikymmentä kaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Pashurin jälkeläisiä tuhat kaksisataa neljäkymmentä seitsemän;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Haarimin jälkeläisiä tuhat seitsemäntoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Leeviläisiä oli: Jeesuan ja Kadmielin jälkeläisiä, nimittäin Hoodevan jälkeläisiä, seitsemänkymmentä neljä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Veisaajia oli: Aasafin jälkeläisiä sata neljäkymmentä kahdeksan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Ovenvartijoita oli: Sallumin jälkeläisiä, Aaterin jälkeläisiä, Talmonin jälkeläisiä, Akkubin jälkeläisiä, Hatitan jälkeläisiä, Soobain jälkeläisiä sata kolmekymmentä kahdeksan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Temppelipalvelijoita oli: Siihan jälkeläiset, Hasufan jälkeläiset, Tabbaotin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Keeroksen jälkeläiset, Siian jälkeläiset, Paadonin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Lebanan jälkeläiset, Hagaban jälkeläiset, Salmain jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Haananin jälkeläiset, Giddelin jälkeläiset, Gaharin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Reajan jälkeläiset, Resinin jälkeläiset, Nekodan jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Gassamin jälkeläiset, Ussan jälkeläiset, Paaseahin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Beesain jälkeläiset, Meunimin jälkeläiset, Nefusesimin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Bakbukin jälkeläiset, Hakufan jälkeläiset, Harhurin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Baslutin jälkeläiset, Mehidan jälkeläiset, Harsan jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Barkoksen jälkeläiset, Siiseran jälkeläiset, Taamahin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Nesiahin jälkeläiset, Hatifan jälkeläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Salomon palvelijain jälkeläisiä oli: Sootain jälkeläiset, Sooferetin jälkeläiset, Peridan jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Jaalan jälkeläiset, Darkonin jälkeläiset, Giddelin jälkeläiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Sefatjan jälkeläiset, Hattilin jälkeläiset, Kooferet-Sebaimin jälkeläiset, Aamonin jälkeläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Temppelipalvelijoita ja Salomon palvelijain jälkeläisiä oli kaikkiaan kolmesataa yhdeksänkymmentä kaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Nämä ovat ne, jotka lähtivät Teel-Melahista, Teel-Harsasta, Kerub-Addonista ja Immeristä, voimatta ilmoittaa perhekuntaansa ja syntyperäänsä, olivatko israelilaisia:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Delajan jälkeläiset, Tobian jälkeläiset, Nekodan jälkeläiset, kuusisataa neljäkymmentä kaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'Ja pappeja: Habaijan jälkeläiset, Koosin jälkeläiset, Barsillain jälkeläiset, sen, joka oli ottanut itsellensä vaimon gileadilaisen Barsillain tyttäristä ja jota kutsuttiin heidän nimellään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Nämä etsivät sukuluetteloitaan, niitä löytämättä, ja niin heidät julistettiin pappeuteen kelpaamattomiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'Maaherra kielsi heitä syömästä korkeasti-pyhää, ennenkuin nousisi pappi, joka voi käyttää uurimia ja tummimia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Koko seurakunta yhteenlaskettuna oli neljäkymmentäkaksi tuhatta kolmesataa kuusikymmentä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'paitsi heidän palvelijoitansa ja palvelijattariansa, joita oli seitsemäntuhatta kolmesataa kolmekymmentä seitsemän. Lisäksi oli heillä kaksisataa neljäkymmentä viisi mies-ja naisveisaajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, '{7:68} Kameleja heillä oli neljäsataa kolmekymmentä viisi, aaseja kuusituhatta seitsemänsataa kaksikymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, '{7:69} Osa perhekunta-päämiehistä antoi lahjoja rakennustyötä varten. Maaherra antoi rahastoon tuhat dareikkia kultaa, viisikymmentä maljaa ja viisisataa kolmekymmentä papin-ihokasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, '{7:70} Ja muutamat perhekunta-päämiehistä antoivat rakennusrahastoon kaksikymmentä tuhatta dareikkia kultaa ja kaksituhatta kaksisataa miinaa hopeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, '{7:71} Ja muu kansa antoi yhteensä kaksikymmentä tuhatta dareikkia kultaa ja kaksituhatta miinaa hopeata sekä kuusikymmentä seitsemän papin-ihokasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, '{7:72} Ja papit, leeviläiset, ovenvartijat, veisaajat ja osa kansasta sekä temppelipalvelijat, koko Israel, asettuivat kaupunkeihinsa. Ja niin tuli seitsemäs kuukausi, ja israelilaiset olivat jo kaupungeissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Silloin kokoontui kaikki kansa yhtenä miehenä Vesiportin edustalla olevalle aukealle; ja he pyysivät Esraa, kirjanoppinutta, tuomaan Mooseksen lain kirjan, jonka lain Herra oli antanut Israelille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Niin pappi Esra toi lain seurakunnan eteen, sekä miesten että naisten, kaikkien, jotka voivat ymmärtää, mitä kuulivat. Tämä tapahtui seitsemännen kuun ensimmäisenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'Ja hän luki sitä Vesiportin edustalla olevalla aukealla päivän koitosta puolipäivään saakka miehille ja naisille, niille, jotka voivat sitä ymmärtää, kaiken kansan kuunnellessa lain kirjan lukemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'Ja Esra, kirjanoppinut, seisoi korkealla puulavalla, joka oli tätä varten tehty. Ja hänen vieressään seisoivat: hänen oikealla puolellaan Mattitja, Sema, Anaja, Uuria, Hilkia ja Maaseja; ja hänen vasemmalla puolellaan Pedaja, Miisael, Malkia, Haasum, Hasbaddana, Sakarja ja Mesullam.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Ja Esra avasi kirjan kaiken kansan nähden, sillä hän seisoi ylempänä kaikkea kansaa; ja kun hän avasi sen, nousi kaikki kansa seisomaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'Ja Esra kiitti Herraa, suurta Jumalaa, ja kaikki kansa vastasi, kohottaen kätensä ylös: \"Amen, amen\"; ja he kumarsivat ja rukoilivat Herraa, heittäytyneinä kasvoilleen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Sitten Jeesua, Baani, Seerebja, Jaamin, Akkub, Sabbetai, Hoodia, Maaseja, Kelita, Asarja, Joosabad, Haanan, Pelaja ja muut leeviläiset opettivat kansalle lakia, kansan seisoessa alallansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Ja he lukivat Jumalan lain kirjaa kappale kappaleelta ja selittivät sen sisällyksen, niin että luettu ymmärrettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Ja Nehemia, maaherra, ja pappi Esra, kirjanoppinut, ja leeviläiset, jotka opettivat kansaa, sanoivat kaikelle kansalle: \"Tämä päivä on pyhitetty Herralle, teidän Jumalallenne, älkää murehtiko älkääkä itkekö\". Sillä kaikki kansa itki, kun he kuulivat lain sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Ja hän sanoi vielä heille: \"Menkää ja syökää rasvaisia ruokia ja juokaa makeita juomia ja lähettäkää maistiaisia niille, joilla ei ole mitään valmistettuna, sillä tämä päivä on pyhitetty meidän Herrallemme. Ja älkää olko murheelliset, sillä ilo Herrassa on teidän väkevyytenne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'Myöskin leeviläiset rauhoittivat kaikkea kansaa ja sanoivat: \"Olkaa hiljaa, sillä tämä päivä on pyhä; älkää olko murheelliset\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Ja kaikki kansa meni, söi ja joi, lähetti maistiaisia ja vietti suurta ilojuhlaa; sillä he olivat ymmärtäneet, mitä heille oli julistettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Seuraavana päivänä kokoontuivat kaiken kansan perhekunta-päämiehet, papit ja leeviläiset Esran, kirjanoppineen, tykö painamaan lain sanoja mieleensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'Niin he huomasivat lakiin kirjoitetun, että Herra oli Mooseksen kautta käskenyt israelilaisia asumaan lehtimajoissa juhlan aikana seitsemännessä kuussa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'ja että kaikissa heidän kaupungeissaan ja Jerusalemissa oli julistettava ja kuulutettava näin: \"Menkää vuorille ja tuokaa öljypuun lehviä tai metsäöljypuun lehviä sekä myrtin, palmupuun ja muiden tuuheiden puiden lehviä, ja tehkää lehtimajoja, niinkuin on säädetty\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Ja kansa meni ja toi niitä ja teki itselleen lehtimajoja kukin katollensa ja pihoihinsa ja Jumalan temppelin esipihoihin sekä Vesiportin aukealle ja Efraimin portin aukealle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'Ja koko seurakunta, kaikki vankeudesta palanneet, tekivät lehtimajoja ja asuivat lehtimajoissa. Sillä aina Joosuan, Nuunin pojan, ajoista siihen päivään saakka eivät israelilaiset olleet niin tehneet. Ja vallitsi hyvin suuri ilo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'Ja Jumalan lain kirjaa luettiin joka päivä, ensimmäisestä päivästä viimeiseen saakka. Ja he viettivät juhlaa seitsemän päivää, ja kahdeksantena päivänä pidettiin juhlakokous säädetyllä tavalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Mutta saman kuun kahdentenakymmenentenä neljäntenä päivänä israelilaiset kokoontuivat paastoten, säkit yllä ja multaa pään päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'Ja Israelin heimo eristäytyi kaikista muukalaisista, astui esiin ja tunnusti syntinsä ja isiensä rikkomukset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'Sitten he nousivat seisomaan, kukin paikallansa, ja heille luettiin Herran, heidän Jumalansa, lain kirjaa neljännes päivää; ja toisen neljänneksen aikana he tunnustivat syntinsä ja kumartaen rukoilivat Herraa, Jumalaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Ja Jeesua, Baani, Kadmiel, Sebanja, Bunni, Seerebja, Baani ja Kenani nousivat leeviläisten korokkeelle ja huusivat suurella äänellä Herraa, Jumalaansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'ja leeviläiset Jeesua, Kadmiel, Baani, Hasabneja, Seerebja, Hoodia, Sebanja ja Petahja sanoivat: \"Nouskaa ja kiittäkää Herraa, Jumalaanne, iankaikkisesta iankaikkiseen. Ja kiitettäköön sinun kunniallista nimeäsi, joka on korotettu yli kaiken kiitoksen ja ylistyksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Sinä yksin olet Herra. Sinä olet tehnyt taivaat ja taivasten taivaat kaikkine joukkoinensa, maan ja kaikki, mitä siinä on, meret ja kaikki, mitä niissä on. Sinä annat elämän niille kaikille, ja taivaan joukot kumartavat sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Sinä olet Herra Jumala, joka valitsit Abramin ja veit hänet pois Kaldean Uurista ja annoit hänelle nimen Aabraham.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'Ja sinä havaitsit hänen sydämensä uskolliseksi sinua kohtaan, ja niin sinä teit hänen kanssaan liiton antaaksesi hänen jälkeläisillensä kanaanilaisten, heettiläisten, amorilaisten, perissiläisten, jebusilaisten ja girgasilaisten maan. Ja lupauksesi sinä olet täyttänyt, sillä sinä olet vanhurskas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Ja sinä näit meidän isiemme kurjuuden Egyptissä ja kuulit heidän huutonsa Kaislameren rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'Sinä teit tunnustekoja ja ihmeitä rangaisten faraota ja kaikkia hänen palvelijoitansa ja kaikkea hänen maansa kansaa; sillä sinä tiesit näiden kohdelleen heitä ylimielisesti, ja sinä teit itsellesi nimen, niinkuin se tänäkin päivänä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Meren sinä halkaisit heidän edessänsä kahtia, niin että he kulkivat meren poikki kuivaa myöten; mutta heidän takaa-ajajansa sinä syöksit syvyyteen, niinkuin kiven valtaviin vesiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'Sinä johdatit heitä päivällä pilvenpatsaasta ja yöllä tulenpatsaasta, valaisten heille tien, jota heidän oli kuljettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Ja sinä astuit alas Siinain vuorelle ja puhuit heille taivaasta ja annoit heille oikeat tuomiot ja totiset lait, hyvät säädökset ja käskyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'Sinä ilmoitit heille pyhän sapattisi ja annoit heille käskyt, säädökset ja lain palvelijasi Mooseksen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Sinä annoit heille leipää taivaasta heidän nälkäänsä, ja sinä hankit heille vettä kalliosta heidän janoonsa. Ja sinä käskit heidän mennä ottamaan omaksensa maan, jonka sinä olit kättä kohottaen luvannut heille antaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Mutta he, meidän isämme, olivat ylimielisiä; he olivat niskureita eivätkä totelleet sinun käskyjäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'He eivät tahtoneet totella eivätkä muistaneet ihmeellisiä tekoja, jotka sinä olit heille tehnyt, vaan olivat niskureita ja valitsivat uppiniskaisuudessaan johtajan palatakseen takaisin orjuuteensa. Mutta sinä olet anteeksiantava Jumala, armahtavainen ja laupias, pitkämielinen ja suuri armossa: sinä et heitä hyljännyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Vaikka he tekivät itsellensä valetun vasikankuvan ja sanoivat: \'Tämä on sinun jumalasi, joka on johdattanut sinut Egyptistä\', ja vaikka he paljon pilkkasivat Jumalaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'niin sinä suuressa laupeudessasi et kuitenkaan hyljännyt heitä erämaassa. Pilvenpatsas ei väistynyt heidän luotansa päivällä, johtamasta heitä tiellä, eikä tulenpatsas yöllä, valaisemasta heille tietä, jota heidän oli kuljettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Hyvän Henkesi sinä annoit heitä opettamaan, mannaasi et kieltänyt heidän suustansa, ja vettä sinä annoit heille heidän janoonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Neljäkymmentä vuotta sinä elätit heitä erämaassa, niin ettei heiltä mitään puuttunut, eivät heidän vaatteensa kuluneet, eivätkä heidän jalkansa ajettuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'Sinä annoit heidän haltuunsa valtakuntia ja kansoja ja jaoit ne alue alueelta; ja he valloittivat Siihonin maan-Hesbonin kuninkaan maan-ja Oogin, Baasanin kuninkaan, maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'Ja heidän lastensa luvun sinä teit paljoksi kuin taivaan tähdet, ja sinä veit heidät siihen maahan, josta olit antanut heidän isillensä lupauksen, että he saavat mennä ottamaan sen omaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Ja lapset tulivat ja ottivat sen maan omaksensa, ja sinä nöyryytit heidän edessään maan asukkaat, kanaanilaiset, ja annoit nämä heidän käsiinsä, sekä heidän kuninkaansa että sen maan kansat, niin että he tekivät näille, mitä tahtoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Ja he valloittivat varustetut kaupungit ja lihavan maan ja ottivat omikseen talot, jotka olivat täynnä kaikkea hyvää, kallioon hakatut vesisäiliöt, viinitarhat, öljypuut ja hedelmäpuita suuret määrät. He söivät ja tulivat ravituiksi ja lihaviksi ja pitivät hyviä päiviä sinun antimiesi runsaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Mutta he niskoittelivat ja kapinoivat sinua vastaan, heittivät sinun lakisi selkänsä taa ja tappoivat sinun profeettasi, jotka heitä varoittivat palauttaakseen heidät sinun luoksesi; ja he pilkkasivat paljon Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Sentähden sinä annoit heidät heidän ahdistajainsa käsiin, ja nämä ahdistivat heitä. Mutta kun he ahdinkonsa aikana huusivat sinua, niin sinä taivaasta kuulit ja suuressa laupeudessasi annoit heille vapauttajia, jotka vapauttivat heidät heidän ahdistajainsa käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Mutta rauhaan päästyään he jälleen tekivät sitä, mikä on pahaa sinun edessäsi. Silloin sinä jätit heidät heidän vihollistensa käsiin, niin että nämä vallitsivat heitä. Mutta kun he jälleen huusivat sinua, kuulit sinä taivaasta ja pelastit heidät laupeudessasi monta kertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'Ja sinä varoitit heitä palauttaaksesi heidät seuraamaan sinun lakiasi, mutta he olivat ylimielisiä eivätkä totelleet sinun käskyjäsi, vaan he rikkoivat sinun oikeutesi-se ihminen, joka ne pitää, on niistä elävä-mutta he käänsivät uppiniskaisina selkänsä ja olivat niskureita eivätkä totelleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Sinä kärsit heitä monta vuotta ja varoitit heitä Hengelläsi profeettaisi kautta, mutta he eivät ottaneet sitä korviinsa. Niin sinä annoit heidät pakanallisten kansojen käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Mutta sinä suuressa laupeudessasi et tehnyt loppua heistä etkä hyljännyt heitä; sillä sinä olet armahtavainen ja laupias Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Ja nyt, Jumalamme, sinä suuri, väkevä ja peljättävä Jumala, joka pidät liiton ja säilytät laupeuden: älä katso vähäksi kaikkea sitä vaivaa, joka on kohdannut meitä, meidän kuninkaitamme, päämiehiämme, pappejamme, profeettojamme, isiämme ja koko sinun kansaasi, Assurin kuningasten ajoista aina tähän päivään saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Sinä olet vanhurskas kaikessa, mikä on meitä kohdannut; sillä sinä olet ollut uskollinen teoissasi, mutta me olemme olleet jumalattomat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'Meidän kuninkaamme, päämiehemme, pappimme ja isämme eivät ole seuranneet sinun lakiasi eivätkä tarkanneet sinun käskyjäsi ja säädöksiäsi, jotka sinä olit heille antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Ja vaikka he elivät omassa valtakunnassansa ja siinä antimien runsaudessa, jonka sinä olit heille antanut, ja avarassa ja lihavassa maassa, jonka sinä olit heille antanut, eivät he kuitenkaan palvelleet sinua eivätkä kääntyneet pois pahoista teoistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Katso, me olemme nyt orjia; siinä maassa, jonka sinä meidän isillemme annoit, että he söisivät sen hedelmiä ja antimia, siinä meidän täytyy orjina olla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Sen runsas sato tulee niille kuninkaille, jotka sinä meidän syntiemme tähden olet pannut meitä hallitsemaan; he vallitsevat meitä ja meidän karjaamme, niinkuin tahtovat, ja me olemme suuressa ahdistuksessa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, '{10:1} \"Kaiken tämän johdosta me teemme sitoumuksen ja kirjoitamme siihen nimemme; sinetöidyssä asiakirjassa ovat meidän päämiestemme, leeviläistemme ja pappiemme nimet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, '{10:2} Sinetöidyissä asiakirjoissa ovat nämä nimet: Nehemia, Hakaljan poika, maaherra, ja Sidkia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, '{10:3} Seraja, Asarja, Jeremia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pashur, Amarja, Malkia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hattus, Sebanja, Malluk,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Haarim, Meremot, Obadja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Ginneton, Baaruk,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mesullam, Abia, Miijamin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maasja, Bilgai ja Semaja-nämä ovat pappeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Leeviläisiä ovat: Jeesua, Asanjan poika, Binnui, Heenadadin jälkeläinen, Kadmiel');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'ja heidän veljensä Sebanja, Hoodia, Kelita, Pelaja, Haanan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Miika, Rehob, Hasabja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Sakkur, Seerebja, Sebanja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hoodia, Baani ja Beninu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Kansan päämiehiä ovat: Paros, Pahat-Mooab, Eelam, Sattu, Baani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunni, Asgad, Beebai,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonia, Bigvai, Aadin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Aater, Hiskia, Assur,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hoodia, Haasum, Beesai,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Haarif, Anatot, Nuubai,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpias, Mesullam, Heesir,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesesabel, Saadok, Jaddua,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatja, Haanan, Anaja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Hoosea, Hananja, Hassub,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Loohes, Pilha, Soobek,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rehum, Hasabna, Maaseja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'Ahia, Haanan, Aanan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Malluk, Haarim ja Baana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Ja muu kansa, papit, leeviläiset, ovenvartijat, veisaajat, temppelipalvelijat ja kaikki, jotka ovat eristäytyneet pakanallisista kansoista Jumalan lain puolelle, sekä heidän vaimonsa, poikansa ja tyttärensä, kaikki, jotka pystyvät sen ymmärtämään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'liittyvät ylhäisiin veljiinsä, tulevat valalle ja vannovat vaeltavansa Jumalan lain mukaan, joka on annettu Jumalan palvelijan Mooseksen kautta, ja noudattavansa ja seuraavansa kaikkia Herran, meidän Herramme, käskyjä, oikeuksia ja säädöksiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'Me emme anna tyttäriämme maan kansoille emmekä ota heidän tyttäriänsä pojillemme vaimoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Me emme osta sapattina tai pyhäpäivänä maan kansoilta, jos ne tuovat kauppatavaraa tai viljaa mitä tahansa kaupaksi sapattina. Me jätämme joka seitsemäntenä vuotena maan lepäämään ja kaikki saatavat velkomatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Me sitoudumme suorittamaan vuodessa kolmannes-sekelin palvelusta varten Jumalamme temppelissä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'näkyleipiin, jokapäiväiseen ruokauhriin ja jokapäiväiseen polttouhriin, uhreihin sapatteina ja uudenkuun päivinä, juhlauhreihin ja pyhiin lahjoihin, syntiuhreihin sovituksen toimittamiseksi Israelille ja kaikkeen, mikä meidän Jumalamme temppelissä toimitettava on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Me, papit, leeviläiset ja kansa, olemme heittäneet arpaa uhrilahjahalkojen tuomisesta perhekunnittain Jumalamme temppeliin määräaikoina joka vuosi, poltettaviksi Herran, meidän Jumalamme, alttarilla, niinkuin laissa on kirjoitettuna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Me sitoudumme tuomaan maamme uutiset ja kaikkinaisten hedelmäpuiden uutiset joka vuosi Herran temppeliin 10:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'sekä esikoiset pojistamme ja karjastamme, niinkuin laissa on kirjoitettuna, ja tuomaan raavaittemme ja lampaittemme esikoiset Jumalamme temppeliin, papeille, jotka toimittavat virkaansa meidän Jumalamme temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Me tuomme parhaat jyvärouheemme ja antimemme, parhaat kaikkinaisten puiden hedelmät, parhaan viinin ja öljyn papeille, Jumalamme temppelin kammioihin, ja maamme kymmenykset leeviläisille. Leeviläiset itse kantavat kymmenykset kaikista kaupungeista, missä meillä on maanviljelystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'Ja papin, Aaronin pojan, tulee olla leeviläisten kanssa, heidän kantaessaan kymmenyksiä, ja leeviläisten tulee viedä kymmenykset kymmenyksistä meidän Jumalamme temppeliin, varastohuoneen kammioihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, '{10:40} Sillä israelilaisten ja leeviläisten on vietävä anti jyvistä, viinistä ja öljystä näihin kammioihin, joissa pyhäkön kalut ja virkaansa toimittavat papit, ovenvartijat ja veisaajat ovat. Me emme laiminlyö Jumalamme temppeliä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Ja kansan päämiehet asettuivat Jerusalemiin, mutta muu kansa heitti arpaa saadakseen joka kymmenennen asettumaan Jerusalemiin, pyhään kaupunkiin, yhdeksän kymmenesosan jäädessä asumaan muihin kaupunkeihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'Ja kansa siunasi kaikkia niitä miehiä, jotka vapaaehtoisesti asettuivat Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Nämä olivat ne maakunnan päämiehet, jotka asettuivat Jerusalemiin ja Juudan kaupunkeihin; he asuivat kukin perintöosallaan, kaupungeissaan, Israel, papit, leeviläiset ja temppelipalvelijat sekä Salomon palvelijain jälkeläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'Jerusalemissa asuivat seuraavat Juudan ja Benjamin miehet: Juudan miehiä: Ataja, Ussian poika, joka oli Sakarjan poika, joka Amarjan poika, joka Sefatjan poika, joka Mahalalelin poika, Pereksen jälkeläisiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'ja Maaseja, Baarukin poika, joka oli Kolhoosen poika, joka Hasajan poika, joka Adajan poika, joka Joojaribin poika, joka Sakarjan poika, joka siilonilaisen poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Jerusalemissa asuvia Pereksen jälkeläisiä oli kaikkiaan neljäsataa kuusikymmentä kahdeksan sotakuntoista miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Benjaminilaiset olivat nämä: Sallu, Mesullamin poika, joka oli Jooedin poika, joka Pedajan poika, joka Koolajan poika, joka Maasejan poika, joka Iitielin poika, joka Jesajan poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'ja hänen jälkeensä Gabbai ja Sallai, yhdeksänsataa kaksikymmentä kahdeksan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'Jooel, Sikrin poika, oli heidän päällysmiehenään ja Juuda, Senuan poika, toisena kaupunginpäällikkönä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Pappeja: Jedaja, Joojaribin poika, Jaakin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraja, Hilkian poika, joka oli Mesullamin poika, joka Saadokin poika, joka Merajotin poika, joka Ahitubin poika, Jumalan temppelin esimies,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'sekä heidän veljensä, jotka toimittivat palvelusta temppelissä, kahdeksansataa kaksikymmentä kaksi miestä; ja Adaja, Jerohamin poika, joka oli Pelaljan poika, joka Amsin poika, joka Sakarjan poika, joka Pashurin poika, joka Malkian poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'sekä hänen veljensä, jotka olivat perhekunta-päämiehiä, kaksisataa neljäkymmentä kaksi miestä; ja Amassai, Asarelin poika, joka oli Ahsain poika, joka Mesillemotin poika, joka Immerin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'sekä heidän veljensä, jotka olivat sotaurhoja, sata kaksikymmentä kahdeksan miestä. Heidän päällysmiehenään oli Sabdiel, Gedolimin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'Ja leeviläisiä: Semaja, Hassubin poika, joka oli Asrikamin poika, joka Hasabjan poika, joka Bunnin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'ja Sabbetai ja Joosabad, jotka valvoivat maallisia toimia Jumalan temppelissä ja olivat leeviläisten päämiehiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'ja Mattanja, Miikan poika, joka oli Sabdin poika, joka Aasafin, ensimmäisen johtajan, poika, joka rukoiltaessa alotti kiitosvirren, ja Bakbukja, hänen veljistään toinen, ja Abda, Sammuan poika, joka oli Gaalalin poika, joka Jedutunin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Leeviläisiä oli pyhässä kaupungissa kaikkiaan kaksisataa kahdeksankymmentä neljä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Ovenvartijat olivat Akkub, Talmon sekä heidän veljensä, jotka vartioivat portteja, sata seitsemänkymmentä kaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Muut israelilaiset, papit ja leeviläiset asuivat kaikissa muissa Juudan kaupungeissa, kukin perintöosallaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Temppelipalvelijat asuivat Oofelilla; Siiha ja Gispa valvoivat temppelipalvelijoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'Ja leeviläisten päällysmiehenä Jerusalemissa Jumalan temppelin toimissa oli Ussi, Baanin poika, joka oli Hasabjan poika, joka Mattanjan poika, joka Miikan poika, Aasafin jälkeläisiä, veisaajia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Oli näet heitä koskeva kuninkaan käsky, joka vakuutti veisaajille heidän jokapäiväiset tarpeensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'Ja Petahja, Mesesabelin poika, Serahin, Juudan pojan, jälkeläisiä, oli kuninkaan edusmiehenä kaikissa kansaa koskevissa asioissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'Heidän peltomaillaan olevissa kylissä asui Juudan miehiä: Kirjat-Arbassa ja sen tytärkaupungeissa, Diibonissa ja sen tytärkaupungeissa, Jekabseelissa ja siihen kuuluvissa kylissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'Jeesuassa, Mooladassa, Beet-Peletissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'Hasar-Suualissa, Beersebassa ja sen tytärkaupungeissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'Siklagissa, Mekonassa ja sen tytärkaupungeissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'Een-Rimmonissa, Sorassa, Jarmutissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'Saanoahissa, Adullamissa ja niihin kuuluvissa kylissä, Laakiissa ja sen peltomailla, Asekassa ja sen tytärkaupungeissa; he sijoittuivat siis asumaan Beersebasta aina Hinnomin laaksoon saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Benjaminilaiset asuivat, Gebasta alkaen, Mikmaassa, Aijassa, Beetelissä ja sen tytärkaupungeissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'Anatotissa, Noobissa, Ananjassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Haasorissa, Raamassa, Gittaimissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Haadidissa, Seboimissa, Neballatissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Loodissa, Oonossa, Seppäinlaaksossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'Leeviläisistä asui eräitä Juudan osastoja Benjaminissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Nämä olivat ne papit ja leeviläiset, jotka lähtivät Serubbaabelin, Sealtielin pojan, ja Jeesuan kanssa: Seraja, Jeremia, Esra,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarja, Malluk, Hattus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sekanja, Rehum, Meremot,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginnetoi, Abia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Miijamin, Maadja, Bilga,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaja, Joojarib, Jedaja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Aamok, Hilkia ja Jedaja. Nämä olivat pappien ja veljiensä päämiehet Jeesuan aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Ja leeviläiset olivat: Jeesua, Binnui, Kadmiel, Seerebja, Juuda ja Mattanja, joka yhdessä veljiensä kanssa johti kiitosveisua;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'ja heidän veljensä Bakbukja ja Unni seisoivat vastapäätä heitä tehtäviään suorittamassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'Jeesualle syntyi Joojakim, Joojakimille syntyi Eljasib, Eljasibille syntyi Joojada,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Joojadalle syntyi Joonatan ja Joonatanille syntyi Jaddua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'Joojakimin aikana olivat seuraavat papit perhekunta-päämiehinä: Serajalla Meraja, Jeremialla Hananja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Esralla Mesullam, Amarjalla Joohanan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Mallukilla Joonatan, Sebanjalla Joosef,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Haarimilla Adna, Merajotilla Helkai,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Iddolla Sakarja, Ginnetonilla Mesullam,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Abialla Sikri, Minjaminilla, Mooadjalla Piltai,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Bilgalla Sammua, Semajalla Joonatan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Joojaribilla Mattenai, Jedajalla Ussi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Sallailla Kallai, Aamokilla Eeber,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Hilkialla Hasabja ja Jedajalla Netanel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'Leeviläisistä merkittiin Eljasibin, Joojadan, Joohananin ja Jadduan aikana perhekunta-päämiehet muistiin; ja samoin papit persialaisen Daarejaveksen hallitusaikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Leevin jälkeläisistä ovat perhekunta-päämiehet merkittyinä aikakirjaan Joohananin, Eljasibin pojan, aikaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Ja leeviläisten päämiehet olivat Hasabja, Seerebja ja Jeesua, Kadmielin poika, sekä heidän veljensä, jotka seisoivat heitä vastapäätä ylistämässä ja kiittämässä, niinkuin Jumalan mies Daavid oli käskenyt, osasto osaston vieressä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'ja Mattanja, Bakbukja, Obadja, Mesullam, Talmon ja Akkub, ovenvartijat, jotka vartioivat porttien varastohuoneita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Nämä olivat Joojakimin, Jeesuan pojan, Joosadakin pojanpojan, aikalaisia ja käskynhaltija Nehemian ja pappi Esran, kirjanoppineen, aikalaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'Kun Jerusalemin muuri oli vihittävä, haettiin leeviläiset kaikista heidän asuinpaikoistansa ja tuotiin Jerusalemiin viettämään vihkimäjuhlaa iloiten, kiitosvirsiä ja lauluja laulaen, kymbaaleja, harppuja ja kanteleita soittaen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Niin kokoontuivat veisaajain pojat Lakeudelta, Jerusalemin ympäristöstä, netofalaisten kylistä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Beet-Gilgalista ja Geban ja Asmavetin peltomailta, sillä veisaajat olivat rakentaneet itselleen kyliä Jerusalemin ympäristöön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'Papit ja leeviläiset puhdistautuivat ja puhdistivat kansan sekä portit ja muurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Sitten minä vein Juudan päämiehet rinteelle, muurin yläpuolelle, ja järjestin kaksi suurta laulukuntaa ja juhlakulkuetta muurin yläpuolelle, oikealle kädelle, Lantaportille päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'Ja heidän jäljessään kulkivat Hoosaja ja toinen puoli Juudan päämiehiä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'sekä Asarja, Esra, Mesullam,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juuda, Benjamin, Semaja ja Jeremia');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'sekä pappien poikia torvineen, ja Sakarja, Joonatanin poika, joka oli Semajan poika, joka Mattanjan poika, joka Miikajan poika, joka Sakkurin poika, joka Aasafin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'sekä hänen veljensä Semaja, Asarel, Milalai, Gilalai, Maai, Netanel, Juuda ja Hanani Daavidin, Jumalan miehen, soittimia kantaen; ja Esra, kirjanoppinut, kulki heidän edellään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'He menivät Lähdeportin ohi ja nousivat suoraan Daavidin kaupungin portaita sinne, mistä noustaan muurille, Daavidin palatsin yläpuolelle, aina Vesiportille asti idässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Toinen laulukunta kulki vastakkaiseen suuntaan, ja sen jäljessä minä ja toinen puoli kansaa, muurin yläpuolitse, Uunitornin yläpuolitse, aina Leveälle muurille asti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'ja Efraimin-portin yläpuolitse ja Vanhanportin, Kalaportin, Hananelin-tornin ja Hammea-tornin ohitse aina Lammasportille saakka; ja he asettuivat Vankilaportin luokse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Sitten molemmat laulukunnat asettuivat Jumalan temppeliin, ja samoin minä ja toinen puoli esimiehiä minun kanssani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'sekä papit Eljakim, Maaseja, Minjamin, Miikaja, Eljoenai, Sakarja ja Hananja torvineen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'ja Maaseja, Semaja, Eleasar, Ussi, Joohanan, Malkia, Eelam ja Eser. Veisaajat kaiuttivat virsiään, ja Jisrahja oli johtajana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Ja he uhrasivat sinä päivänä suuria uhreja ja iloitsivat, sillä Jumala oli suuresti ilahuttanut heitä; myöskin vaimot ja lapset iloitsivat. Ja ilo kuului Jerusalemista kauas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Sinä päivänä asetettiin miehiä valvomaan varastokammioita, joissa antimet, uutiset ja kymmenykset säilytettiin. Niihin oli koottava kaupunkien peltomailta papeille ja leeviläisille lain mukaan tulevat osuudet. Sillä Juuda iloitsi palvelusta toimittavista papeista ja leeviläisistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Ja nämä toimittivat tehtävänsä Jumalaansa palvellen ja puhdistuksia suorittaen, samoin veisaajat ja ovenvartijat, niinkuin Daavid ja hänen poikansa Salomo olivat käskeneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Sillä jo muinoin, Daavidin ja Aasafin aikana, oli veisaajain päämiehiä, ja veisattiin ylistys-ja kiitosvirsiä Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Ja koko Israel antoi Serubbaabelin ja Nehemian aikana veisaajille ja ovenvartijoille heidän osuutensa, heidän jokapäiväiset tarpeensa; he pyhittivät lahjoja myöskin leeviläisille, ja leeviläiset pyhittivät lahjoja Aaronin pojille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Sinä päivänä luettiin Mooseksen kirjaa kansan kuullen, ja siihen havaittiin kirjoitetun, ettei ammonilainen eikä mooabilainen koskaan pääse Jumalan seurakuntaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'sen tähden että he eivät tulleet leipää ja vettä tuoden israelilaisia vastaan ja koska hän palkkasi heitä vastaan Bileamin kiroamaan heidät, vaikka meidän Jumalamme muuttikin kirouksen siunaukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'Kuultuaan lain he erottivat kaiken sekakansan Israelista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Mutta sitä ennen oli pappi Eljasib, Tobian sukulainen, joka oli asetettu meidän Jumalamme temppelin kammionhoitajaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'sisustanut hänelle suuren kammion, johon ennen oli pantu ruokauhri, suitsuke, kalut ja jyvä-,viini-ja öljykymmenykset, jotka olivat määrätyt leeviläisille, veisaajille ja ovenvartijoille, sekä papeille tuleva anti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Tämän kaiken tapahtuessa en minä ollut Jerusalemissa; sillä Artahsastan, Baabelin kuninkaan, kolmantenakymmenentenä toisena hallitusvuotena minä olin mennyt kuninkaan luo. Mutta jonkun ajan kuluttua minä pyysin kuninkaalta lomaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'ja palasin Jerusalemiin. Ja kun minä tulin huomaamaan, minkä pahan Eljasib oli tehnyt Tobian eduksi, sisustaessaan hänelle kammion Jumalan temppelin esipihoissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'pahastuin minä suuresti, ja minä heitin kaikki Tobian huonekalut ulos kammiosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Ja minä käskin puhdistaa kammiot ja panetin niihin takaisin Jumalan temppelin kalut, ruokauhrin ja suitsukkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Vielä minä sain tietää, ettei leeviläisille oltu annettu heidän osuuksiaan, ja niin olivat leeviläiset ja veisaajat, joiden olisi ollut tehtävä palvelusta, vetäytyneet kukin maatilalleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Minä nuhtelin esimiehiä siitä ja sanoin: \"Minkätähden on Jumalan temppeli laiminlyöty?\" Ja minä kokosin leeviläiset ja veisaajat ja asetin heidät paikoilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Ja koko Juuda toi kymmenykset jyvistä, viinistä ja öljystä varastohuoneisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'Ja minä asetin Selemjan, papin, ja Saadokin, kirjanoppineen, ja Pedajan, leeviläisen, valvomaan varastohuoneita ja annoin heidän apulaisekseen Haananin, Sakkurin pojan, Mattanjan pojanpojan; sillä heitä pidettiin luotettavina, ja heidän tehtävänään oli toimittaa jako veljiensä kesken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Muista tämän tähden minua, Jumalani, äläkä pyyhi pois minun hurskaita tekojani, jotka minä olen tehnyt Jumalani temppelin ja siinä toimitettavan palveluksen hyväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Siihen aikaan minä näin Juudassa niitä, jotka sapattina polkivat viinikuurnaa ja jotka kuljettivat viljaa ja kuormittivat aaseja sillä sekä viinillä, rypäleillä, viikunoilla ja kaikenlaisella muulla kuormatavaralla. Ja he toivat niitä Jerusalemiin sapatinpäivänä; ja minä varoitin heitä, kun he myivät elintarpeita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Sinne oli myös asettunut tyyrolaisia, jotka toivat kalaa ja kaikenlaista kauppatavaraa ja myivät Juudan kansalle sapattina ja Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Ja minä nuhtelin Juudan ylimyksiä ja sanoin heille: \"Kuinka te teette näin pahasti ja rikotte sapatinpäivän?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Eikö Jumalamme juuri sen tähden, että teidän isänne näin tekivät, antanut kaiken tämän onnettomuuden kohdata meitä ja tätä kaupunkia? Ja te tuotatte nyt vielä suuremman vihan Israelin ylitse, kun rikotte sapatinpäivän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'Ja niin pian kuin oli tullut pimeä ennen sapattia Jerusalemin porteissa, käskin minä sulkea ovet ja kielsin avaamasta niitä ennen kuin sapatin jälkeen. Ja minä asetin palvelijoitani porteille, ettei yhtään kuormaa pääsisi kaupunkiin sapatinpäivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Kauppiaat ja kaikenlaisen tavaran myyjät jäivät yöksi Jerusalemin ulkopuolelle, kerran ja toisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Mutta minä varoitin heitä ja sanoin heille: \"Minkätähden te jäätte yöksi muurin edustalle? Jos vielä kerran teette sen, niin minä käyn teihin käsiksi.\" Sen jälkeen he eivät enää tulleet sapattina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'Ja minä käskin leeviläisten puhdistautua ja tulla vartioimaan portteja, että sapatinpäivä pyhitettäisiin. Muista minua, Jumalani, myös tämän tähden ja armahda minua suuressa laupeudessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Siihen aikaan minä näin myös juutalaisia, jotka olivat naineet asdodilaisia, ammonilaisia ja mooabilaisia vaimoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'Ja heidän lapsistaan puolet puhuivat asdodinkieltä tai jonkun muun kansan kieltä, eivätkä osanneet puhua juudankieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Silloin minä nuhtelin heitä ja kirosin heidät, jopa löin muutamia heistä ja revin heitä parrasta; ja minä vannotin heitä Jumalan kautta: \"Älkää antako tyttäriänne heidän pojillensa älkääkä ottako heidän tyttäriään vaimoiksi pojillenne tai itsellenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Eikö Salomo, Israelin kuningas, tehnyt juuri tuollaista syntiä? Ei yhdelläkään monien kansojen joukossa ollut hänen vertaistaan kuningasta; hän oli Jumalallensa rakas, ja Jumala asetti hänet koko Israelin kuninkaaksi. Kuitenkin muukalaiset vaimot saattoivat hänetkin tekemään syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'Ja nytkö meidän täytyy kuulla teistä, että te olette tehneet kaiken tämän suuren pahan ja olleet uskottomat meidän Jumalaamme kohtaan, kun olette naineet muukalaisia vaimoja?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Ja yksi ylimmäisen papin Eljasibin pojan Joojadan pojista oli hooronilaisen Sanballatin vävy; hänet minä karkoitin luotani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Muista heidät, Jumalani, sillä he ovat saastuttaneet pappeuden sekä sekä pappeuden sekä pappeus-ja leeviläisliiton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Niin minä puhdistin heidät kaikesta muukalaisuudesta. Ja minä järjestin virkatehtävät papeille ja leeviläisille, kullekin hänen toimensa mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'niin myös halko-uhrilahjan määräaikoina ja uutislahjat. Muista, Jumalani, tämä minun hyväkseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'Ahasveroksen aikana-sen Ahasveroksen, joka hallitsi Intiasta Etiopiaan saakka, sataa kahtakymmentä seitsemää maakuntaa-siihen aikaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'kun kuningas Ahasveros istui kuninkaallisella valtaistuimellansa, joka oli Suusanin linnassa, tapahtui tämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'Kolmantena hallitusvuotenaan hän laittoi pidot kaikille ruhtinaillensa ja palvelijoillensa. Persian ja Meedian voima, ylimykset ja maaherrat olivat hänen luonansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'ja hän näytti heille kuninkaallisen kunniansa rikkautta ja suuruutensa loistavaa komeutta monta päivää, sata kahdeksankymmentä päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'Ja kun ne päivät olivat kuluneet, laittoi kuningas kaikelle Suusanin linnan väelle, niin pienille kuin suurillekin, kuninkaan palatsin puutarhan esipihaan seitsenpäiväiset pidot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Pellava-,puuvilla-ja punasiniverhoja oli kiinnitetty valkoisilla pellavanauhoilla ja purppuranpunaisilla nauhoilla hopeatankoihin ja valkomarmoripylväisiin. Kultaisia ja hopeaisia lepovuoteita oli pihalla, joka oli laskettu vihreällä ja valkoisella marmorilla, helmiäisellä ja kirjavalla marmorilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'Juotavaa tarjottiin kulta-astioissa, ja astiat olivat erimuotoiset, ja kuninkaan viiniä oli viljalti, kuninkaalliseen tapaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Ja juomisessa oli lakina, ettei saanut olla mitään pakkoa, sillä niin oli kuningas käskenyt kaikkia hovimestareitansa, että oli tehtävä kunkin oman halun mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Myöskin kuningatar Vasti laittoi naisille pidot kuningas Ahasveroksen kuninkaalliseen palatsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'Seitsemäntenä päivänä, kun kuninkaan sydän oli viinistä iloinen, käski hän Mehumanin, Bistan, Harbonan, Bigtan, Abagtan, Seetarin ja Karkaan, niiden seitsemän hoviherran, jotka toimittivat palvelusta kuningas Ahasveroksen luona,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'tuoda kuningatar Vastin, kuninkaallinen kruunu päässä, kuninkaan eteen, että hän saisi näyttää kansoille ja ruhtinaille hänen kauneutensa, sillä hän oli näöltään ihana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Mutta kuningatar Vasti kieltäytyi tulemasta, vaikka kuningas hoviherrojen kautta oli käskenyt. Silloin kuningas suuttui kovin, ja hänessä syttyi viha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Ja kuningas puhui viisaille, ajantietäjille-sillä näin oli tapana esittää kuninkaan sana kaikille lain ja oikeuden tuntijoille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'ja hänen lähimpänsä olivat Karsena, Seetar, Admata, Tarsis, Meres, Marsena ja Memukan, seitsemän Persian ja Meedian ruhtinasta, jotka näkivät kuninkaan kasvot ja istuivat valtakunnan ensimmäisinä-:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, '\"Mitä on lain mukaan tehtävä kuningatar Vastille, koska hän ei ole noudattanut käskyä, jonka kuningas Ahasveros on antanut hoviherrojen kautta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Niin Memukan sanoi kuninkaan ja ruhtinasten edessä: \"Kuningatar Vasti ei ole rikkonut ainoastaan kuningasta vastaan, vaan myös kaikkia ruhtinaita vastaan ja kaikkia kansoja vastaan kuningas Ahasveroksen kaikissa maakunnissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Kun kuningattaren teko tulee kaikkien vaimojen tietoon, saattaa se heidät halveksimaan aviomiehiänsä, he kun voivat sanoa: \'Kuningas Ahasveros käski tuoda kuningatar Vastin eteensä, mutta tämä ei tullut\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Jo tänä päivänä voivat Persian ja Meedian ruhtinattaret, jotka kuulevat kuningattaren teon, puhua siitä kaikille kuninkaan ruhtinaille, ja siitä tulee halveksimista ja suuttumusta riittämään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Jos kuningas hyväksi näkee, julkaistakoon kuninkaallinen käsky ja kirjoitettakoon muuttumatonna Persian ja Meedian lakeihin, ettei Vasti enää saa tulla kuningas Ahasveroksen eteen ja että kuningas antaa hänen kuninkaallisen arvonsa toiselle, häntä paremmalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'Kuninkaan antama säädös tulee tunnetuksi koko hänen valtakunnassansa, vaikka se onkin suuri, ja kaikki vaimot, niin suuret kuin pienetkin, antavat kunnian aviomiehillensä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Tämä puhe miellytti kuningasta ja ruhtinaita, ja kuningas teki Memukanin sanan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'Hän lähetti kaikkiin kuninkaan maakuntiin-kuhunkin maakuntaan sen omalla kirjoituksella ja kullekin kansalle sen omalla kielellä-kirjeet, että joka mies olkoon herra talossaan ja saakoon puhua oman kansansa kieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Näiden tapausten jälkeen, kun kuningas Ahasveroksen viha oli asettunut, muisti hän Vastia ja mitä tämä oli tehnyt ja mitä hänestä oli päätetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Niin kuninkaan palvelijat, jotka toimittivat hänelle palvelusta, sanoivat: \"Etsittäköön kuninkaalle nuoria neitsyitä, näöltään ihania.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'Ja asettakoon kuningas kaikkiin valtakuntansa maakuntiin käskyläiset keräämään kaikki nuoret neitsyet, näöltään ihanat, Suusanin linnaan, vaimolaan, Heegain, kuninkaan hoviherran ja vaimojen vartijan, huostaan, ja annettakoon heille heidän kauneudenhoitonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'Ja neitsyt, johon kuningas mieltyy, tulkoon kuningattareksi Vastin sijaan.\" Ja tämä puhe miellytti kuningasta, ja hän teki niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Suusanin linnassa oli juutalainen mies, nimeltä Mordokai, Jaairin poika, joka oli Siimein poika, joka Kiisin poika, benjaminilainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'Hänet oli viety Jerusalemista pakkosiirtolaisuuteen niiden pakkosiirtolaisten joukossa, jotka vietiin samalla kuin Jekonja, Juudan kuningas, jonka Nebukadnessar, Baabelin kuningas, vei pakkosiirtolaisuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Hän oli setänsä tyttären Hadassan, se on Esterin, kasvatusisä, sillä tämä oli isätön ja äiditön. Tyttö oli vartaloltaan kaunis ja näöltään ihana, ja hänen isänsä ja äitinsä kuoltua oli Mordokai ottanut hänet tyttäreksensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'Ja kun kuninkaan käsky ja laki tuli tunnetuksi ja kun kerättiin paljon tyttöjä Suusanin linnaan Heegain huostaan, otettiin Esterkin kuninkaan palatsiin Heegain, vaimojen vartijan, huostaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'Tyttö miellytti häntä ja sai armon hänen edessään, ja hän antoi hänelle joutuin hänen kauneudenhoitonsa ja määrätyn ravinto-osansa sekä seitsemän valiopalvelijatarta kuninkaan palatsista ja siirsi hänet palvelijattarineen vaimolan parhaaseen paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Ester ei ilmaissut kansaansa eikä syntyperäänsä, sillä Mordokai oli häntä kieltänyt sitä ilmaisemasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Mutta Mordokai käyskenteli joka päivä vaimolan esipihan edustalla saadakseen tietää, voiko Ester hyvin ja mitä hänelle tapahtui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Kun jonkun tytön vuoro tuli mennä kuningas Ahasveroksen tykö, sittenkuin hänelle oli kaksitoista kuukautta tehty, niinkuin vaimoista oli määrätty-sillä niin pitkä aika kului heidän kauneudenhoitoonsa: kuusi kuukautta mirhaöljyllä, toiset kuusi kuukautta hajuaineilla sekä muilla naisten kauneudenhoitokeinoilla-meni tyttö kuninkaan tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Kaikki, mitä hän pyysi, annettiin hänelle mukaan vaimolasta kuninkaan palatsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Illalla hän meni, ja aamulla hän palasi toiseen vaimolaan kuninkaan hoviherran Saasgaan, sivuvaimojen vartijan, huostaan; ei hän enää mennyt kuninkaan tykö, paitsi jos kuningas oli häneen mieltynyt ja hänet nimeltään kutsuttiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Kun Esterille, Mordokain sedän Abihailin tyttärelle, jonka Mordokai oli ottanut tyttärekseen, tuli vuoro mennä kuninkaan tykö, ei hän halunnut mukaansa muuta, kuin mitä Heegai, kuninkaan hoviherra, vaimojen vartija, neuvoi. Ja Ester sai armon kaikkien niiden edessä, jotka näkivät hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Ester vietiin kuningas Ahasveroksen tykö hänen kuninkaalliseen palatsiinsa kymmenennessä kuussa, se on teebet-kuussa, hänen seitsemäntenä hallitusvuotenansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'Ja Ester tuli kuninkaalle kaikkia muita naisia rakkaammaksi ja sai hänen edessään armon ja suosion ennen kaikkia muita neitsyitä, niin että tämä pani kuninkaallisen kruunun hänen päähänsä ja teki hänet kuningattareksi Vastin sijaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Ja kuningas laittoi suuret pidot kaikille ruhtinailleen ja palvelijoilleen, pidot Esterin kunniaksi, ja myönsi maakunnille veronhuojennusta ja jakelutti lahjoja, kuninkaalliseen tapaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'Kun neitsyitä koottiin toinen kerta ja Mordokai istuskeli kuninkaan portissa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, '-eikä Ester ollut ilmaissut syntyperäänsä eikä kansaansa, sillä Mordokai oli häntä siitä kieltänyt; Ester näet teki, mitä Mordokai käski, samoin kuin ollessaan hänen kasvattinansa-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'niin siihen aikaan, Mordokain istuskellessa kuninkaan portissa, Bigtan ja Teres, kaksi kuninkaan hoviherraa, ovenvartijoita, suuttuivat ja etsivät tilaisuutta käydäkseen käsiksi kuningas Ahasverokseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Mutta se tuli Mordokain tietoon, ja hän ilmaisi sen kuningatar Esterille, ja Ester sanoi sen Mordokain nimessä kuninkaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'Ja asia tutkittiin, ja kun se havaittiin todeksi, ripustettiin ne molemmat hirsipuuhun. Ja se kirjoitettiin aikakirjaan kuningasta varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Näiden tapausten jälkeen kuningas Ahasveros korotti agagilaisen Haamanin, Hammedatan pojan, ylensi hänet ja antoi hänelle ylimmän sijan kaikkien ruhtinasten joukossa, jotka olivat hänen luonansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'Ja kaikki kuninkaan palvelijat, jotka olivat kuninkaan portissa, polvistuivat ja heittäytyivät maahan Haamanin edessä, sillä niin oli kuningas käskenyt häntä kohdella. Mutta Mordokai ei polvistunut eikä heittäytynyt maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Niin kuninkaan palvelijat, jotka olivat kuninkaan portissa, sanoivat Mordokaille: \"Miksi sinä rikot kuninkaan käskyn?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'Ja kun he joka päivä sanoivat hänelle näin, mutta hän ei heitä totellut, ilmoittivat he tämän Haamanille, nähdäksensä, oliko Mordokain sanoma syy pätevä; sillä hän oli ilmoittanut heille olevansa juutalainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'Kun Haaman näki, ettei Mordokai polvistunut eikä heittäytynyt maahan hänen edessään, tuli Haaman kiukkua täyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'Kun hänelle oli ilmoitettu, mitä kansaa Mordokai oli, vähäksyi hän käydä käsiksi yksin Mordokaihin: Haaman etsi tilaisuutta hävittääkseen kaikki juutalaiset, Mordokain kansan, Ahasveroksen koko valtakunnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'Ensimmäisessä kuussa, se on niisan-kuussa, kuningas Ahasveroksen kahdentenatoista vuotena, heitettiin Haamanin edessä puur\'ia, se on arpaa, jokaisesta päivästä ja jokaisesta kuukaudesta, kahdenteentoista kuukauteen, se on adar-kuuhun, asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Ja Haaman sanoi kuningas Ahasverokselle: \"On yksi kansa hajallaan ja erillään muiden kansojen seassa sinun valtakuntasi kaikissa maakunnissa. Heidän lakinsa ovat toisenlaiset kuin kaikkien muiden kansojen, he eivät noudata kuninkaan lakeja, eikä kuninkaan sovi jättää heitä rauhaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Jos kuningas hyväksi näkee, kirjoitettakoon määräys, että heidät on tuhottava; ja minä punnitsen kymmenentuhatta talenttia hopeata virkamiehille, vietäväksi kuninkaan aarrekammioihin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Niin kuningas otti kädestään sinettisormuksensa ja antoi sen agagilaiselle Haamanille, Hammedatan pojalle, juutalaisten vastustajalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'Ja kuningas sanoi Haamanille: \"Hopea olkoon annettu sinulle, ja samoin se kansa, tehdäksesi sille, mitä hyväksi näet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Niin kutsuttiin kuninkaan kirjurit ensimmäisessä kuussa, sen kolmantenatoista päivänä, ja kirjoitettiin, aivan niinkuin Haaman käski, määräys kuninkaan satraapeille ja jokaisen maakunnan käskynhaltijoille ja jokaisen kansan ruhtinaille, kuhunkin maakuntaan sen omalla kirjoituksella ja kullekin kansalle sen omalla kielellä. Kuningas Ahasveroksen nimessä se kirjoitettiin ja sinetöitiin kuninkaan sinettisormuksella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'Ja juoksijain mukana lähetettiin kaikkiin kuninkaan maakuntiin kirjeet, että oli hävitettävä, tapettava ja tuhottava kaikki juutalaiset, nuoret ja vanhat, lapset ja vaimot, samana päivänä, kahdennentoista kuun, se on adar-kuun, kolmantenatoista päivänä, ja että oli ryöstettävä, mitä heiltä oli saatavana saalista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'Kirjeen jäljennös oli julkaistava lakina jokaisessa maakunnassa, tiedoksi kaikille kansoille, että olisivat valmiit tuona päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Juoksijat lähtivät kuninkaan käskystä kiiruusti matkaan kohta, kun laki oli annettu Suusanin linnassa. Kuningas ja Haaman istuivat juomaan, mutta Suusanin kaupunki oli hämmästyksissään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Kun Mordokai sai tietää kaiken, mitä oli tapahtunut, repäisi Mordokai vaatteensa, pukeutui säkkiin ja tuhkaan ja meni keskelle kaupunkia ja huuteli kovia ja katkeria valitushuutoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'Ja hän meni kuninkaan portin edustalle asti, sillä sisälle kuninkaan porttiin ei saanut mennä säkkiin puettuna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'Jokaisessa maakunnassa, joka paikassa, mihin kuninkaan käsky ja hänen lakinsa tuli, syntyi juutalaisten keskuudessa suuri suru: paastottiin, itkettiin ja valitettiin; monet levittivät allensa säkin ja tuhkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Kun Esterin palvelijattaret ja hänen hoviherransa tulivat ja kertoivat hänelle tämän, joutui kuningatar suureen tuskaan, ja hän lähetti vaatteita, että Mordokai puettaisiin niihin ja että hän riisuisi säkin yltään, mutta hän ei ottanut niitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Niin Ester kutsui Hatakin, joka oli kuninkaan hoviherroja ja jonka tämä oli asettanut häntä palvelemaan, ja käski hänet Mordokain luo, saadakseen tietää, mitä ja mistä syystä tämä kaikki oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Niin Hatak meni Mordokain luo kaupungin torille, joka on kuninkaan portin edustalla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'ja Mordokai ilmoitti hänelle kaikki, mitä hänelle oli tapahtunut, ja myös tarkalleen, kuinka paljon hopeata Haaman oli luvannut punnita kuninkaan aarrekammioihin juutalaisten tuhoamisesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Myös jäljennöksen sen lain sanamuodosta, joka Suusanissa oli annettu heidän hävittämisekseen, hän antoi hänelle, että hän näyttäisi sen Esterille ja ilmoittaisi tälle asian sekä velvoittaisi häntä menemään kuninkaan luo anomaan armoa ja rukoilemaan häntä kansansa puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Niin Hatak meni ja kertoi Esterille Mordokain sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Mutta Ester puhui Hatakille ja käski hänen sanoa Mordokaille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, '\"Kaikki kuninkaan palvelijat ja kuninkaan maakuntien kansa tietävät, että kuka ikinä, mies tai nainen, kutsumatta menee kuninkaan luo sisempään esipihaan, on laki sama jokaiselle: hänet surmataan; ainoastaan se, jota kohti kuningas ojentaa kultavaltikkansa, jää eloon. Mutta minua ei ole kolmeenkymmeneen päivään kutsuttu tulemaan kuninkaan tykö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'Kun Mordokaille kerrottiin Esterin sanat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'käski Mordokai vastata Esterille: \"Älä luulekaan, että sinä, kun olet kuninkaan linnassa, yksin kaikista juutalaisista pelastut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Jos sinä tänä aikana olet vaiti, tulee apu ja pelastus juutalaisille muualta, mutta sinä ja sinun isäsi perhe tuhoudutte. Kuka tietää, etkö sinä juuri tällaista aikaa varten ole päässyt kuninkaalliseen arvoon?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Niin Ester käski vastata Mordokaille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, '\"Mene ja kokoa kaikki Suusanin juutalaiset, ja paastotkaa minun puolestani; olkaa syömättä ja juomatta kolme vuorokautta, yöt ja päivät. Myös minä palvelijattarineni samoin paastoan. Sitten minä menen kuninkaan tykö, vaikka se on vastoin lakia; ja jos tuhoudun, niin tuhoudun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Niin Mordokai meni ja teki, aivan niinkuin Ester oli häntä käskenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'Kolmantena päivänä Ester pukeutui kuninkaallisesti ja astui kuninkaan linnan sisempään esipihaan, vastapäätä kuninkaan linnaa; ja kuningas istui kuninkaallisella valtaistuimellaan kuninkaallisessa linnassa vastapäätä linnan ovea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'Kun kuningas näki kuningatar Esterin seisovan esipihassa, sai tämä armon hänen silmiensä edessä, ja kuningas ojensi Esteriä kohti kultavaltikan, joka hänellä oli kädessä. Ja Ester astui esiin ja kosketti valtikan päätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Kuningas sanoi hänelle: \"Mikä sinun on, kuningatar Ester, ja mitä pyydät? Se sinulle annetaan, olkoon vaikka puoli valtakuntaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'Niin Ester vastasi: \"Jos kuningas hyväksi näkee, tulkoon kuningas ja myös Haaman tänä päivänä pitoihin, jotka minä olen hänelle laittanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Kuningas sanoi: \"Noutakaa kiiruusti Haaman tehdäksemme Esterin toivomuksen mukaan\". Ja kun kuningas ja Haaman olivat tulleet pitoihin, jotka Ester oli laittanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'kysyi kuningas juominkien aikana Esteriltä: \"Mitä pyydät? Se sinulle annetaan. Ja mitä haluat? Se täytetään, olkoon vaikka puoli valtakuntaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Niin Ester vastasi sanoen: \"Tätä minä pyydän ja haluan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'jos olen saanut armon kuninkaan silmien edessä ja jos kuningas näkee hyväksi antaa minulle, mitä pyydän, ja täyttää, mitä haluan, niin tulkoot kuningas ja Haaman vielä pitoihin, jotka minä heille laitan; huomenna minä teen kuninkaan toivomuksen mukaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'Haaman lähti sieltä sinä päivänä iloisena ja hyvillä mielin; ja kun Haaman näki Mordokain kuninkaan portissa eikä tämä noussut ylös eikä näyttänyt pelkäävän häntä, täytti viha Mordokaita kohtaan Haamanin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Mutta Haaman hillitsi itsensä ja meni kotiinsa. Sitten hän lähetti noutamaan ystävänsä ja vaimonsa Sereksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'Ja Haaman kehuskeli heille rikkautensa loistoa ja poikiensa paljoutta, ja kuinka kuningas kaikessa oli korottanut hänet ja ylentänyt hänet ylemmäksi ruhtinaita ja kuninkaan palvelijoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Ja Haaman sanoi: \"Eipä kuningatar Esterkään antanut laittamiinsa pitoihin kuninkaan kanssa tulla kenenkään muun kuin minun. Ja huomiseksikin minä olen kuninkaan kanssa kutsuttu hänen luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Mutta tämä kaikki ei minua tyydytä, niin kauan kuin minä näen juutalaisen Mordokain istuvan kuninkaan portissa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Niin hänen vaimonsa Seres ja kaikki hänen ystävänsä sanoivat hänelle: \"Tehtäköön hirsipuu, viittäkymmentä kyynärää korkea, ja pyydä huomenaamuna kuninkaalta, että Mordokai ripustetaan siihen, niin voit mennä kuninkaan kanssa pitoihin iloisena\". Tämä puhe miellytti Haamania, ja hän teetti hirsipuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Sinä yönä uni pakeni kuningasta. Niin hän käski tuoda muistettavain tapahtumain kirjan, aikakirjan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'Ja kun sitä luettiin kuninkaalle, huomattiin kirjoitetun, kuinka Mordokai oli ilmaissut, että Bigtan ja Teres, kaksi kuninkaan hoviherraa, ovenvartijoita, oli etsinyt tilaisuutta käydäkseen käsiksi kuningas Ahasverokseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Niin kuningas kysyi: \"Mitä kunniaa ja korotusta on Mordokai tästä saanut?\" Kuninkaan palvelijat, jotka toimittivat hänelle palvelusta, vastasivat: \"Ei hän ole saanut mitään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'Kuningas kysyi: \"Kuka on esipihassa?\" Mutta Haaman oli tullut kuninkaan palatsin ulompaan esipihaan pyytämään kuninkaalta, että Mordokai ripustettaisiin hirsipuuhun, jonka hän oli pystyttänyt Mordokain varalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Niin kuninkaan palvelijat vastasivat hänelle: \"Katso, esipihassa seisoo Haaman\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'Kuningas sanoi: \"Tulkoon sisään\". Kun Haaman oli tullut, kysyi kuningas häneltä: \"Mitä on tehtävä miehelle, jota kuningas tahtoo kunnioittaa?\" Niin Haaman ajatteli sydämessään: \"Kenellepä muulle kuningas tahtoisi osoittaa kunniaa kuin minulle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'Ja Haaman vastasi kuninkaalle: \"Miehelle, jota kuningas tahtoo kunnioittaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'tuotakoon kuninkaallinen puku, johon kuningas on ollut puettuna, ja hevonen, jolla kuningas on ratsastanut ja jonka päähän on pantu kuninkaallinen kruunu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'Puku ja hevonen annettakoon jollekin kuninkaan ruhtinaista, ylimyksistä. Puettakoon siihen mies, jota kuningas tahtoo kunnioittaa, ja kuljetettakoon häntä sen hevosen selässä kaupungin torilla ja huudettakoon hänen edellänsä: \'Näin tehdään miehelle, jota kuningas tahtoo kunnioittaa\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Kuningas sanoi Haamanille: \"Hae joutuin puku ja hevonen, niinkuin sanoit, ja tee näin juutalaiselle Mordokaille, joka istuu kuninkaan portissa. Älä jätä tekemättä mitään kaikesta, mitä olet puhunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Niin Haaman otti puvun ja hevosen, puki Mordokain ja kuljetti häntä hevosen selässä kaupungin torilla ja huusi hänen edellänsä: \"Näin tehdään miehelle, jota kuningas tahtoo kunnioittaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Sitten Mordokai palasi takaisin kuninkaan porttiin, mutta Haaman kiiruhti kotiinsa murehtien ja pää peitettynä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'Kun Haaman kertoi vaimollensa Serekselle ja kaikille ystävilleen kaiken, mitä hänelle oli tapahtunut, sanoivat hänelle hänen viisaansa ja hänen vaimonsa Seres: \"Jos Mordokai, jonka edessä olet alkanut kaatua, on syntyjään juutalainen, et sinä voi hänelle mitään, vaan kaadut hänen eteensä maahan asti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Heidän vielä puhuessaan hänen kanssansa, tulivat kuninkaan hoviherrat ja veivät kiiruusti Haamanin pitoihin, jotka Ester oli laittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Kun kuningas ja Haaman olivat tulleet kuningatar Esterin luo juomaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'sanoi kuningas juominkien aikana Esterille nytkin, toisena päivänä: \"Mitä pyydät, kuningatar Ester? Se sinulle annetaan. Ja mitä haluat? Se täytetään, olkoon vaikka puoli valtakuntaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Niin kuningatar Ester vastasi ja sanoi: \"Jos olen saanut armon sinun silmiesi edessä, kuningas, ja jos kuningas hyväksi näkee, niin annettakoon minulle oma henkeni, kun sitä pyydän, ja kansani, kun sitä haluan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Sillä meidät on myyty, minut ja kansani, hävitettäviksi, tapettaviksi ja tuhottaviksi. Jos meidät olisi myyty vain orjiksi ja orjattariksi, olisin siitä vaiti, sillä sen vaivan takia ei kannattaisi kuningasta vaivata.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Niin sanoi kuningas Ahasveros ja kysyi kuningatar Esteriltä: \"Kuka se on, ja missä se on, joka on rohjennut tehdä sellaista?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Ester vastasi: \"Se vastustaja ja vihamies on tuo paha Haaman\". Niin Haaman peljästyi kuningasta ja kuningatarta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Kuningas nousi vihoissaan juomingeista ja meni linnan puutarhaan, mutta Haaman jäi siihen pyytääkseen henkeänsä kuningatar Esteriltä, sillä hän näki, että kuninkaalla oli paha mielessä häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Kun kuningas tuli linnan puutarhasta takaisin linnaan, jossa juomingit olivat, oli Haaman juuri heittäytymässä lepovuoteelle, jolla kuningatar Ester lepäsi. Niin kuningas sanoi: \"Vai tekee hän vielä väkivaltaa kuningattarelle linnassa, minun läsnäollessani!\" Tuskin oli tämä sana päässyt kuninkaan suusta, kun jo Haamanin kasvot peitettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Ja Harbona, yksi kuningasta palvelevista hoviherroista, sanoi: \"Katso, seisoohan Haamanin talon edessä hirsipuu, viittäkymmentä kyynärää korkea, se, minkä Haaman on teettänyt Mordokain varalle, jonka puhe kerran koitui kuninkaan hyväksi\". Kuningas sanoi: \"Ripustakaa hänet siihen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'Niin ripustettiin Haaman hirsipuuhun, jonka hän oli pystyttänyt Mordokain varalle. Sitten kuninkaan viha asettui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Sinä päivänä kuningas Ahasveros lahjoitti kuningatar Esterille Haamanin, juutalaisten vastustajan, talon. Ja Mordokai pääsi kuninkaan eteen, sillä Ester oli ilmoittanut, mikä Mordokai oli hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Ja kuningas otti kädestään sinettisormuksensa, jonka hän oli otattanut pois Haamanilta, ja antoi sen Mordokaille; ja Ester pani Mordokain Haamanin talon hoitajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Mutta Ester puhui vielä kuninkaan edessä ja lankesi hänen jalkainsa juureen, itki ja rukoili häntä torjumaan agagilaisen Haamanin pahuuden ja sen juonen, jonka tämä oli punonut juutalaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Niin kuningas ojensi Esteriä kohti kultavaltikan, ja Ester nousi ja seisoi kuninkaan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'Ja hän sanoi: \"Jos kuningas hyväksi näkee ja jos minä olen saanut armon hänen edessänsä ja kuningas sen soveliaaksi katsoo ja minä olen hänen silmissänsä otollinen, niin kirjoitettakoon määräys ja peruutettakoon agagilaisen Haamanin, Hammedatan pojan, juoni, ne kirjeet, jotka hän kirjoitutti tuhotaksensa juutalaiset kaikissa kuninkaan maakunnissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Sillä kuinka minä jaksaisin nähdä kansaani kohtaavan onnettomuuden, kuinka jaksaisin nähdä sukuni surman!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Niin kuningas Ahasveros sanoi kuningatar Esterille ja juutalaiselle Mordokaille: \"Katso, Haamanin talon minä olen lahjoittanut Esterille, ja hän itse on ripustettu hirsipuuhun, koska hän oli käynyt käsiksi juutalaisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Ja nyt kirjoittakaa kuninkaan nimessä sellainen juutalaisia koskeva määräys, kuin hyväksi näette, ja sinetöikää se kuninkaan sinettisormuksella; sillä kirjelmä, joka on kirjoitettu kuninkaan nimessä ja sinetöity kuninkaan sinettisormuksella, on peruuttamaton.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Niin kutsuttiin kuninkaan kirjurit silloin, kolmannessa kuussa, se on siivan-kuussa, sen kahdentenakymmenentenä kolmantena päivänä, ja kirjoitettiin, aivan niinkuin Mordokai käski, määräys juutalaisille sekä satraapeille, käskynhaltijoille ja maaherroille sataan kahteenkymmeneen seitsemään maakuntaan, Intiasta Etiopiaan saakka, kuhunkin maakuntaan sen omalla kirjoituksella ja kullekin kansalle sen omalla kielellä; myös juutalaisille heidän kirjoituksellaan ja kielellään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'Hän kirjoitutti kuningas Ahasveroksen nimessä ja sinetöi kuninkaan sinettisormuksella. Ja hän lähetti ratsulähettien mukana, jotka ratsastivat tammatarhoissa kasvatetuilla hovin hevosilla, kirjeet:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'että kuningas sallii juutalaisten jokaisessa kaupungissa, missä heitä onkin, kokoontua puolustamaan henkeänsä hävittämällä, tappamalla ja tuhoamalla kansan ja maakunnan kaiken aseväen, joka heitä ahdistaa, sekä myös lapset ja vaimot, ja ryöstämään, mitä heiltä on saatavana saalista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'samana päivänä kaikissa kuningas Ahasveroksen maakunnissa, kahdennentoista kuun, se on adar-kuun, kolmantenatoista päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Kirjeen jäljennös oli julkaistava lakina jokaisessa maakunnassa, tiedoksi kaikille kansoille, ja että juutalaiset olisivat valmiit sinä päivänä kostamaan vihollisillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Hovin hevosilla ratsastavat lähetit lähtivät kuninkaan käskystä kiiruusti ja nopeasti matkaan kohta, kun laki oli annettu Suusanin linnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'Mutta Mordokai lähti kuninkaan luota puettuna kuninkaalliseen punasiniseen purppuraan ja pellavapukuun, ja hänellä oli suuri kultakruunu ja viitta, tehty valkoisesta pellavakankaasta ja purppuranpunaisesta kankaasta. Ja Suusanin kaupunki riemuitsi ja oli iloissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Juutalaisille oli tullut onni, ilo, riemu ja kunnia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'ja jokaisessa maakunnassa ja kaupungissa, joka paikassa, mihin kuninkaan käsky ja hänen lakinsa tuli, oli juutalaisilla ilo ja riemu, pidot ja juhlat. Ja paljon oli maan kansoista niitä, jotka kääntyivät juutalaisiksi, sillä kauhu juutalaisia kohtaan oli vallannut heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Kahdennessatoista kuussa, se on adar-kuussa, sen kolmantenatoista päivänä, jona kuninkaan käsky ja hänen lakinsa oli toimeenpantava, sinä päivänä, jona juutalaisten viholliset olivat toivoneet saavansa heidät valtaansa, mutta jona päinvastoin juutalaiset saivat valtaansa vihamiehensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'kokoontuivat juutalaiset kaupungeissansa kaikissa kuningas Ahasveroksen maakunnissa käydäkseen käsiksi niihin, jotka hankkivat heille onnettomuutta, eikä kukaan kestänyt heidän edessänsä, sillä kauhu heitä kohtaan oli vallannut kaikki kansat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'Ja kaikki maaherrat, satraapit ja käskynhaltijat ja kuninkaan virkamiehet kannattivat juutalaisia, sillä kauhu Mordokaita kohtaan oli vallannut heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Sillä Mordokai oli mahtava kuninkaan palatsissa, ja hänen maineensa levisi kaikkiin maakuntiin, sillä se mies, Mordokai, tuli yhä mahtavammaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'Ja juutalaiset voittivat kaikki vihollisensa lyöden miekoilla, surmaten ja tuhoten, ja tekivät vihamiehillensä, mitä tahtoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Suusanin linnassa juutalaiset tappoivat ja tuhosivat viisisataa miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'Ja Parsandatan, Dalfonin, Aspatan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Pooratan, Adaljan, Aridatan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmastan, Arisain, Aridain ja Vaisatan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'kymmenen Haamanin, Hammedatan pojan, juutalaisten vastustajan, poikaa, he tappoivat; mutta saaliiseen he eivät käyneet käsiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Sinä päivänä tuli Suusanin linnassa tapettujen luku kuninkaan tietoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Ja kuningas sanoi kuningatar Esterille: \"Suusanin linnassa juutalaiset ovat tappaneet ja tuhonneet viisisataa miestä ja Haamanin kymmenen poikaa; muissa kuninkaan maakunnissa mitä lienevätkään tehneet! Mitä nyt pyydät? Se sinulle annetaan. Ja mitä vielä haluat? Se täytetään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Niin Ester sanoi: \"Jos kuningas hyväksi näkee, sallittakoon Suusanin juutalaisten huomennakin tehdä saman lain mukaan kuin tänä päivänä. Ja ripustettakoon Haamanin kymmenen poikaa hirsipuuhun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'Kuningas käski tehdä niin. Ja siitä annettiin laki Suusanissa. Ja Haamanin kymmenen poikaa ripustettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'Ja Suusanin juutalaiset kokoontuivat myös adar-kuun neljäntenätoista päivänä ja tappoivat Suusanissa kolmesataa miestä; mutta saaliiseen he eivät käyneet käsiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Myös muut juutalaiset, jotka olivat kuninkaan maakunnissa, olivat kokoontuneet puolustamaan henkeänsä ja päässeet rauhaan vihollisistansa, tapettuaan vihamiehiään seitsemänkymmentäviisi tuhatta-käymättä käsiksi saaliiseen-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'adar-kuun kolmantenatoista päivänä; ja he lepäsivät sen kuun neljännentoista päivän viettäen sen pito-ja ilopäivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Mutta Suusanin juutalaiset olivat kokoontuneet sen kuun kolmantenatoista ja neljäntenätoista päivänä, ja he lepäsivät sen kuun viidennentoista päivän viettäen sen pito-ja ilopäivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Sentähden maaseudun juutalaiset, jotka asuvat maaseutukaupungeissa, viettävät adar-kuun neljännentoista päivän ilo-,pito-ja juhlapäivänä ja lähettävät toisilleen maistiaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Ja Mordokai pani kirjaan nämä tapaukset. Ja hän lähetti kirjeet kaikille juutalaisille kuningas Ahasveroksen kaikkiin maakuntiin, lähellä ja kaukana oleville,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'säätäen heille, että heidän oli vietettävä adar-kuun neljättätoista päivää ja saman kuun viidettätoista päivää joka vuosi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'koska juutalaiset niinä päivinä olivat päässeet rauhaan vihollisistansa ja heille siinä kuussa murhe oli kääntynyt iloksi ja suru juhlaksi-että heidän oli vietettävä ne päivät pito-ja ilopäivinä ja lähetettävä toisilleen maistiaisia ja köyhille lahjoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'Ja juutalaiset ottivat pysyväksi tavaksi, mitä jo olivat alkaneet tehdä ja mitä Mordokai oli heille kirjoittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Koska agagilainen Haaman, Hammedatan poika, kaikkien juutalaisten vastustaja, oli punonut juonen juutalaisia vastaan tuhotakseen heidät ja oli heittänyt puur\'in, se on arvan, hävittääkseen ja tuhotakseen heidät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'ja koska sen tultua kuninkaan tietoon tämä oli kirjeellisesti määrännyt, että Haamanin pahan juonen, jonka hän oli punonut juutalaisia vastaan, tuli kääntyä hänen omaan päähänsä ja että hänet ja hänen poikansa oli ripustettava hirsipuuhun,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'sentähden antoivat he näille päiville nimeksi puurim, puur-sanan mukaan. Sentähden, tuon käskykirjeen koko sisällyksen johdosta ja sen johdosta, mitä he itse olivat näin nähneet ja mitä heille oli tapahtunut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'juutalaiset säätivät ja ottivat itsellensä ja jälkeläisillensä ja kaikille heihin liittyville muuttumattomaksi ja pysyväksi tavaksi, että näitä kahta päivää oli vietettävä määräyksen mukaisesti ja määräaikana joka vuosi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'ja että jokaisen sukupolven ja suvun oli näitä päiviä muistettava ja vietettävä joka maakunnassa ja kaupungissa sekä että näiden puurim-päivien tuli säilyä muuttumattomina juutalaisten keskuudessa eikä niiden muisto saanut hävitä heidän jälkeläisistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Ja kuningatar Ester, Abihailin tytär, ja juutalainen Mordokai kirjoittivat kaiken valtansa nojalla kirjoituksia saattaakseen säädöksenä voimaan tämän toisen puurim-käskykirjeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Mordokai lähetti kirjeet, ystävällisin ja vilpittömin sanoin, kaikille juutalaisille Ahasveroksen valtakunnan sataan kahteenkymmeneen seitsemään maakuntaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'saattaakseen säädöksenä voimaan nämä puurim-päivät niiden määräaikoina, niinkuin juutalainen Mordokai ja kuningatar Ester olivat niistä säätäneet ja niinkuin juutalaiset itse olivat säätäneet itselleen ja jälkeläisilleen määräykset niihin kuuluvista paastoista ja valitushuudoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'Näin säädettiin Esterin käskystä nämä puurim-määräykset ja kirjoitettiin kirjaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Kuningas Ahasveros saattoi työveron alaisiksi sekä mannermaan että merensaaret.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Ja kaikki hänen valta-ja urotyönsä ja kertomus Mordokain suuruudesta, johon kuningas hänet korotti, ne ovat kirjoitettuina Meedian ja Persian kuningasten aikakirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Sillä juutalainen Mordokai oli kuningas Ahasveroksen lähin mies ja oli suuri juutalaisten keskuudessa ja rakas lukuisille veljillensä, koska hän harrasti kansansa parasta ja puhui koko heimonsa onnen puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Uusin maassa oli mies, jonka nimi oli Job. Tämä mies oli nuhteeton ja rehellinen, pelkäsi Jumalaa ja karttoi pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'Hänelle syntyi seitsemän poikaa ja kolme tytärtä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'Ja karjaa hänellä oli seitsemäntuhatta lammasta, kolmetuhatta kamelia, viisisataa härkäparia ja viisisataa aasintammaa sekä ylen paljon palvelijoita. Tämä mies oli kaikista Idän miehistä mahtavin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'Hänen pojillansa oli tapana laittaa pitoja, kullakin oli pidot talossaan vuoropäivänänsä; he lähettivät silloin sanan ja kutsuivat kolme sisartansa syömään ja juomaan kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'Mutta kun pitopäivät olivat kiertonsa kiertäneet, lähetti Job sanan ja pyhitti heidät; hän nousi varhain aamulla ja uhrasi polttouhreja, yhtä monta kuin heitä oli. Sillä Job ajatteli: \"Ehkä poikani ovat tehneet syntiä ja sydämessään luopuneet Jumalasta\". Näin Job teki aina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'Mutta kun eräänä päivänä Jumalan pojat tulivat ja asettuivat Herran eteen, tuli myöskin saatana heidän joukossansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Niin Herra kysyi saatanalta: \"Mistä sinä tulet?\" Saatana vastasi Herralle ja sanoi: \"Maata kiertämästä ja siellä kuljeksimasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'Niin Herra sanoi saatanalle: \"Oletko pannut merkille palvelijaani Jobia? Sillä ei ole maan päällä hänen vertaistansa; hän on nuhteeton ja rehellinen mies, pelkää Jumalaa ja karttaa pahaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Saatana vastasi Herralle ja sanoi: \"Suottako Job pelkää Jumalaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Olethan itse kaikilta puolin suojannut hänet, hänen talonsa ja kaiken, mitä hänellä on; olet siunannut hänen kättensä työn, ja hänen karjalaumansa ovat levinneet ympäri maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Mutta ojennapa kätesi ja koske kaikkeen, mitä hänellä on: varmaan hän kiroaa sinua vasten kasvojasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Niin Herra sanoi saatanalle: \"Katso, kaikki, mitä hänellä on, olkoon sinun käsissäsi; älä vain koske kädelläsi häneen itseensä\". Ja saatana meni pois Herran edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Kun sitten eräänä päivänä hänen poikansa ja tyttärensä söivät ja joivat viiniä vanhimman veljensä talossa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'tuli sanansaattaja Jobin luo ja sanoi: \"Raavailla kynnettiin, ja aasintammat kävivät niiden vieressä laitumella;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'niin sabalaiset hyökkäsivät ja ryöstivät ne ja surmasivat palvelijat miekan terällä. Vain minä yksin pelastuin kertomaan tämän sinulle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Hänen vielä puhuessaan tuli toinen ja sanoi: \"Jumalan tuli iski alas taivaasta, sytytti palamaan lampaat ja palvelijat ja kulutti heidät. Vain minä yksin pelastuin kertomaan tämän sinulle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Hänen vielä puhuessaan tuli taas toinen ja sanoi: \"Kaldealaiset asettuivat kolmeen joukkoon ja karkasivat kamelien kimppuun, ryöstivät ne ja surmasivat palvelijat miekan terällä. Vain minä yksin pelastuin kertomaan tämän sinulle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Hänen vielä puhuessaan tuli taas toinen ja sanoi: \"Poikasi ja tyttäresi söivät ja joivat viiniä vanhimman veljensä talossa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'katso, silloin suuri tuulispää tuli tuolta puolen erämaan ja iski talon neljään nurkkaan, ja se luhistui nuorukaisten päälle, niin että he kuolivat. Vain minä yksin pelastuin kertomaan tämän sinulle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Silloin Job nousi, repäisi viittansa ja leikkasi hiuksensa, heittäytyi maahan ja rukoili.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'Ja hän sanoi: \"Alastonna minä tulin äitini kohdusta, ja alastonna minä sinne palajan. Herra antoi, ja Herra otti; kiitetty olkoon Herran nimi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Kaikessa tässä Job ei tehnyt syntiä eikä puhunut nurjasti Jumalaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Ja kun eräänä päivänä Jumalan pojat tulivat ja asettuivat Herran eteen, tuli myöskin saatana heidän joukossansa ja asettui Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Niin Herra kysyi saatanalta: \"Mistä sinä tulet?\" Saatana vastasi Herralle ja sanoi: \"Maata kiertämästä ja siellä kuljeksimasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Niin Herra sanoi saatanalle: \"Oletko pannut merkille palvelijaani Jobia? Sillä ei ole maan päällä hänen vertaistansa; hän on nuhteeton ja rehellinen mies, pelkää Jumalaa ja karttaa pahaa. Vielä hän pysyy hurskaudessansa, ja sinä olet yllyttänyt minut häntä vastaan, tuhoamaan hänet syyttömästi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'Saatana vastasi Herralle ja sanoi: \"Nahka nahasta; ja kaikki, mitä ihmisellä on, hän antaa hengestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Mutta ojennapa kätesi ja koske hänen luihinsa ja lihaansa: varmaan hän kiroaa sinua vasten kasvojasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Herra sanoi saatanalle: \"Katso, hän olkoon sinun käsissäsi; säästä kuitenkin hänen henkensä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Niin saatana meni pois Herran edestä ja löi Jobiin pahoja paiseita, kantapäästä kiireeseen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Ja tämä otti saviastian sirun, sillä kaapiakseen itseänsä, ja istui tuhkaläjään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Niin hänen vaimonsa sanoi hänelle: \"Vieläkö pysyt hurskaudessasi? Kiroa Jumala ja kuole.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'Mutta hän vastasi hänelle: \"Sinä puhut niinkuin mikäkin houkka nainen. Otammehan vastaan Jumalalta hyvää, emmekö ottaisi vastaan pahaakin?\" Kaikessa tässä Job ei tehnyt syntiä huulillansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Kun Jobin kolme ystävää kuuli kaiken onnettomuuden, joka häntä oli kohdannut, tulivat he kukin kotipaikastansa: teemanilainen Elifas, suuhilainen Bildad ja naemalainen Soofar; ja he sopivat keskenänsä ja menivät surkuttelemaan ja lohduttamaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'Mutta kun he jonkun matkan päässä nostivat silmänsä, eivät he enää voineet tuntea häntä; niin he korottivat äänensä ja itkivät, repäisivät kukin viittansa ja viskasivat tomua taivasta kohti päittensä päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'Sitten he istuivat hänen kanssaan maassa seitsemän päivää ja seitsemän yötä, eikä kukaan heistä puhunut sanaakaan hänelle, sillä he näkivät, että hänen tuskansa oli ylen suuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Senjälkeen Job avasi suunsa ja kirosi syntymäpäivänsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'Job lausui ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, '\"Kadotkoon se päivä, jona minä synnyin, ja se yö, joka sanoi: \'Poika on siinnyt\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Se päivä muuttukoon pimeydeksi; älköön Jumala korkeudessa sitä kysykö, älköönkä valonsäde sille paistako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Omistakoon sen pimeys ja pilkkopimeä, pilvi laskeutukoon sen päälle, peljästyttäkööt sitä päivänpimennykset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Sen yön ryöstäköön pimeys; älköön se iloitko vuoden päivien parissa, älköön tulko kuukausien lukuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Katso, hedelmätön olkoon se yö, älköön siinä riemuhuuto raikuko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Kirotkoot sen päivänmanaajat, ne, jotka saavat hereille Leviatanin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Pimentykööt sen kointähdet, odottakoon se valoa, joka ei tule, älköön se aamuruskon silmäripsiä nähkö,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'koska se ei sulkenut minulta kohdun ovia eikä kätkenyt vaivaa minun silmiltäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Miksi en kuollut heti äidin helmaan, miksi en menehtynyt kohdusta tullessani?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Miksi olivat minua vastaanottamassa polvet, minkätähden rinnat imeäkseni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Sillä makaisinhan rauhassa silloin, nukkuisin ja saisin levätä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'kuningasten ja maan neuvosmiesten kanssa, jotka ovat rakentaneet itselleen pyramiideja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'päämiesten kanssa, joilla on ollut kultaa, jotka ovat täyttäneet talonsa hopealla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'tahi olisin olematon niinkuin maahan kätketty keskoinen, niinkuin sikiöt, jotka eivät ole päivänvaloa nähneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Siellä lakkaavat jumalattomat raivoamasta, siellä saavat uupuneet levätä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'kaikki vangit ovat rauhassa, eivät kuule käskijän ääntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Yhtäläiset ovat siellä pieni ja suuri, orja on vapaa herrastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Miksi hän antaa vaivatulle valoa ja elämää murhemielisille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'jotka odottavat kuolemaa, eikä se tule, jotka etsivät sitä enemmän kuin aarretta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'jotka iloitsisivat riemastuksiin asti, riemuitsisivat, jos löytäisivät haudan-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'miehelle, jonka tie on ummessa, jonka Jumala on aitaukseen sulkenut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Sillä huokaukseni on tullut minun leiväkseni, valitukseni valuu kuin vesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Sillä mitä minä kauhistuin, se minua kohtasi, ja mitä minä pelkäsin, se minulle tapahtui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Ennenkuin tyynnyin, rauhan ja levon sain, tuli tuska jälleen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Silloin teemanilainen Elifas lausui ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, '\"Ethän pane pahaksesi, jos sinulle puhutaan? Kuka voi vaitikaan olla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Katso, monta sinä olet ojentanut, ja hervonneita käsiä olet vahvistanut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'sanasi ovat nostaneet kompastunutta, ja rauenneita polvia olet voimistanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'Mutta nyt, kun itseäsi kova kohtaa, sinä tuskastut, kun se sinuun sattuu, sinä kauhistut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Eikö jumalanpelkosi ole sinun uskalluksesi ja nuhteeton vaelluksesi sinun toivosi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Ajattele, kuka viaton on koskaan hukkunut, ja missä ovat rehelliset joutuneet perikatoon?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Minkä minä olen nähnyt, niin ne, jotka vääryyttä kyntävät ja turmiota kylvävät, ne sitä niittävätkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Jumalan henkäyksestä he hukkuvat, hänen vihansa hengestä he häviävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Leijonan ärjyntä, jalopeuran ääni vaiennetaan, ja nuorten leijonain hampaat murskataan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'jalopeura menehtyy saaliin puutteesta, ja naarasleijonan pennut hajaantuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Ja minulle tuli salaa sana, korvani kuuli kuiskauksen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'kun ajatukset liikkuivat öisissä näyissä, kun raskas uni oli vallannut ihmiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Pelko ja vavistus yllättivät minut, peljästyttivät kaikki minun luuni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'Tuulen henkäys hiveli kasvojani, ihoni karvat nousivat pystyyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Siinä seisoi-sen näköä en erottanut-haamu minun silmäini edessä; minä kuulin kuiskaavan äänen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '\'Onko ihminen vanhurskas Jumalan edessä, onko mies Luojansa edessä puhdas?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Katso, palvelijoihinsakaan hän ei luota, enkeleissäänkin hän havaitsee vikoja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'saati niissä, jotka savimajoissa asuvat, joiden perustus on maan tomussa! He rusentuvat kuin koiperhonen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'ennenkuin aamu ehtooksi muuttuu, heidät muserretaan. Kenenkään huomaamatta he hukkuvat ainiaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Eikö niin: heidän telttanuoransa irroitetaan, ja he kuolevat, viisaudesta osattomina.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, '\"Huuda vain! Onko ketään, joka sinulle vastaisi, ja kenenkä pyhän puoleen kääntyisit?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Mielettömän tappaa suuttumus, tyhmän surmaa kiivaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Minä näin mielettömän juurtuvan, mutta äkkiä sain huutaa hänen asuinsijansa kirousta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Hänen lapsensa ovat onnesta kaukana, heitä poljetaan portissa, eikä auttajaa ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Ja minkä he ovat leikanneet, syö nälkäinen-ottaa sen vaikka orjantappuroista-ja janoiset tavoittelevat heidän tavaraansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Sillä onnettomuus ei kasva tomusta, eikä vaiva verso maasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'vaan ihminen syntyy vaivaan, ja kipinät, liekin lapset, lentävät korkealle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Mutta minä ainakin etsisin Jumalaa ja asettaisin asiani Jumalan eteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'hänen, joka tekee suuria, tutkimattomia tekoja, ihmeitä ilman määrää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'joka antaa sateen maan päälle ja lähettää vettä vainioille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'että hän korottaisi alhaiset ja surevaiset kohoaisivat onneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Hän tekee kavalain hankkeet tyhjiksi, niin ettei mikään menesty heidän kättensä alla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'hän vangitsee viisaat heidän viekkauteensa; ovelain juonet raukeavat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'päivällä he joutuvat pimeään ja hapuilevat keskipäivällä niinkuin yöllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Mutta köyhän hän pelastaa heidän suunsa miekasta, auttaa väkevän kädestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Ja niin on vaivaisella toivo, mutta vääryyden täytyy sulkea suunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Katso, autuas se ihminen, jota Jumala rankaisee! Älä siis pidä halpana Kaikkivaltiaan kuritusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Sillä hän haavoittaa, ja hän sitoo; lyö murskaksi, mutta hänen kätensä myös parantavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Kuudesta hädästä hän sinut pelastaa, ja seitsemässä ei onnettomuus sinua kohtaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'Nälänhädässä hän vapahtaa sinut kuolemasta ja sodassa miekan terästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Kielen ruoskalta sinä olet turvassa, etkä pelkää, kun hävitys tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Hävitykselle ja kalliille ajalle sinä naurat, etkä metsän petoja pelkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Sillä kedon kivien kanssa sinä olet liitossa, ja metsän pedot elävät rauhassa sinun kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'Saat huomata, että majasi on rauhoitettu, ja kun tarkastat asuinsijaasi, et sieltä mitään kaipaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Ja saat huomata, että sinun sukusi on suuri ja vesasi runsaat kuin ruoho maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Ikäsi kypsyydessä sinä menet hautaan, niinkuin lyhde korjataan ajallansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Katso, tämän olemme tutkineet, ja niin se on; kuule se, ja ota sinäkin siitä vaari.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, '\"Oi, jospa minun suruni punnittaisiin ja kova onneni pantaisiin sen kanssa vaakaan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Sillä se on nyt raskaampi kuin meren hiekka; sentähden menevät sanani harhaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Sillä Kaikkivaltiaan nuolet ovat sattuneet minuun; minun henkeni juo niiden myrkkyä. Jumalan kauhut ahdistavat minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Huutaako villiaasi vihannassa ruohikossa, ammuuko härkä rehuviljansa ääressä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Käykö äitelää syöminen ilman suolaa, tahi onko makua munanvalkuaisessa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Sieluni ei tahdo koskea sellaiseen, se on minulle kuin saastainen ruoka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Oi, jospa minun pyyntöni täyttyisi ja Jumala toteuttaisi minun toivoni!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Jospa Jumala suvaitsisi musertaa minut, ojentaa kätensä ja katkaista elämäni langan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Niin olisi vielä lohdutuksenani-ja ilosta minä hypähtäisin säälimättömän tuskan alla-etten ole kieltänyt Pyhän sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Mikä on minun voimani, että enää toivoisin, ja mikä on loppuni, että tätä kärsisin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Onko minun voimani vahva kuin kivi, onko minun ruumiini vaskea?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Eikö minulla ole enää mitään apua, onko pelastus minusta karkonnut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Tuleehan ystävän olla laupias nääntyvälle, vaikka tämä olisikin hyljännyt Kaikkivaltiaan pelon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Minun veljeni ovat petolliset niinkuin vesipuro, niinkuin sadepurot, jotka juoksevat kuiviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Ne ovat jääsohjusta sameat, niihin kätkeytyy lumi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'auringon paahtaessa ne ehtyvät, ne häviävät paikastansa helteen tullen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Niiden juoksun urat mutkistuvat, ne haihtuvat tyhjiin ja katoavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Teeman karavaanit tähystelivät, Seban matkueet odottivat niitä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'he joutuivat häpeään, kun niihin luottivat, pettyivät perille tullessansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Niin te olette nyt tyhjän veroiset: te näette kauhun ja peljästytte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Olenko sanonut: \'Antakaa minulle ja suorittakaa tavaroistanne lahjus minun puolestani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'pelastakaa minut vihollisen vallasta ja lunastakaa minut väkivaltaisten käsistä\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Opettakaa minua, niin minä vaikenen; neuvokaa minulle, missä olen erehtynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Kuinka tehoaakaan oikea puhe! Mutta mitä merkitsee teidän nuhtelunne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Aiotteko nuhdella sanoja? Tuultahan ovat epätoivoisen sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Orvostakin te heittäisitte arpaa ja hieroisitte kauppaa ystävästänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Mutta suvaitkaa nyt kääntyä minuun; minä totisesti en valhettele vasten kasvojanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Palatkaa, älköön vääryyttä tapahtuko; palatkaa, vielä minä olen oikeassa siinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Olisiko minun kielelläni vääryys? Eikö suulakeni tuntisi, mikä turmioksi on?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, '\"Eikö ihmisen olo maan päällä ole sotapalvelusta, eivätkö hänen päivänsä ole niinkuin palkkalaisen päivät?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Hän on orjan kaltainen, joka halajaa varjoon, ja niinkuin palkkalainen, joka odottaa palkkaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Niin olen minä perinyt kurjuuden kuukaudet, ja vaivan yöt ovat minun osakseni tulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Maata mennessäni minä ajattelen: Milloinka saan nousta? Ilta venyy, ja minä kyllästyn kääntelehtiessäni aamuhämärään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Minun ruumiini verhoutuu matoihin ja tomukamaraan, minun ihoni kovettuu ja märkii.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Päiväni kiitävät nopeammin kuin sukkula, ne katoavat toivottomuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Muista, että minun elämäni on tuulen henkäys; minun silmäni ei enää saa onnea nähdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Ken minut näki, sen silmä ei minua enää näe; sinun silmäsi etsivät minua, mutta minua ei enää ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Pilvi häipyy ja menee menojaan; niin myös tuonelaan vaipunut ei sieltä nouse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Ei hän enää palaja taloonsa, eikä hänen asuinpaikkansa häntä enää tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Niin en minäkään hillitse suutani, minä puhun henkeni ahdistuksessa, minä valitan sieluni murheessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Olenko minä meri tai lohikäärme, että asetat vartioston minua vastaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Kun ajattelen: leposijani lohduttaa minua, vuoteeni huojentaa minun tuskaani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'niin sinä kauhistutat minua unilla ja peljästytät minua näyillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'Mieluummin tukehdun, mieluummin kuolen, kuin näin luurankona kidun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Olen kyllästynyt, en tahdo elää iankaiken; anna minun olla rauhassa, sillä tuulen henkäystä ovat minun päiväni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Mikä on ihminen, että hänestä niin suurta lukua pidät ja että kiinnität häneen huomiosi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'tarkastat häntä joka aamu, tutkit häntä joka hetki?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Etkö koskaan käännä pois katsettasi minusta, etkö hellitä minusta sen vertaa, että saan sylkeni nielaistuksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Jos olenkin syntiä tehnyt, niin mitä olen sillä sinulle tehnyt, sinä ihmisten vartioitsija? Minkätähden asetit minut maalitauluksesi, ja minkätähden tulin itselleni taakaksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Minkätähden et anna rikostani anteeksi etkä poista pahaa tekoani? Sillä nyt minä menen levolle maan tomuun, ja jos etsit minua, niin ei minua enää ole.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Sitten suuhilainen Bildad lausui ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, '\"Kuinka kauan sinä senkaltaisia haastat ja suusi puheet ovat kuin raju myrsky?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Jumalako vääristäisi oikeuden, Kaikkivaltiasko vääristäisi vanhurskauden?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Jos lapsesi tekivät syntiä häntä vastaan, niin hän hylkäsi heidät heidän rikoksensa valtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Jos sinä etsit Jumalaa ja anot Kaikkivaltiaalta armoa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'jos olet puhdas ja rehellinen, silloin hän varmasti heräjää sinun avuksesi ja asettaa entiselleen sinun vanhurskautesi asunnon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'Silloin sinun alkusi näyttää vähäiseltä, mutta loppuaikasi varttuu ylen suureksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Sillä kysypä aikaisemmalta sukupolvelta, tarkkaa, mitä heidän isänsä ovat tutkineet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, 'Mehän olemme eilispäivän lapsia emmekä mitään tiedä, päivämme ovat vain varjo maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'He sinua opettavat ja sanovat sinulle, tuovat ilmi sanat sydämestään:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, '\'Kasvaako kaisla siinä, missä ei ole rämettä? rehottaako ruoko siinä, missä ei ole vettä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Vielä vihreänä ollessaan, ennenaikaisena leikattavaksi, se kuivettuu ennen kuin mikään muu heinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Niin käy kaikkien niiden, jotka unhottavat Jumalan, ja jumalattoman toivo katoaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'hänen, jonka uskallus on langan varassa, jonka turvana on hämähäkinverkko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Hän nojaa taloonsa, mutta se ei seiso, hän tarttuu siihen, mutta se ei kestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Hän on rehevänä auringon paisteessa, ja hänen vesansa leviävät yli puutarhan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Hänen juurensa kietoutuvat kiviroukkioon, hän kiinnittää katseensa kivitaloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Mutta kun Jumala hävittää hänet hänen paikastansa, niin se kieltää hänet: En ole sinua koskaan nähnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Katso, siinä oli hänen vaelluksensa ilo, ja tomusta kasvaa toisia.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Katso, Jumala ei hylkää nuhteetonta eikä tartu pahantekijäin käteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Vielä hän täyttää sinun suusi naurulla ja huulesi riemulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Sinun vihamiehesi verhotaan häpeällä, ja jumalattomien majaa ei enää ole.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, '\"Totisesti minä tiedän, että niin on; kuinka voisi ihminen olla oikeassa Jumalaa vastaan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Jos ihminen tahtoisi riidellä hänen kanssaan, ei hän voisi vastata hänelle yhteen tuhannesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Hän on viisas mieleltään ja väkevä voimaltaan kuka on niskoitellut häntä vastaan ja jäänyt rankaisematta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'Hän siirtää vuoret äkkiarvaamatta, hän kukistaa ne vihassansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'hän järkyttää maan paikaltaan, ja sen patsaat vapisevat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'hän kieltää aurinkoa, ja se ei nouse, ja hän lukitsee tähdet sinetillään;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'hän yksinänsä levittää taivaat ja tallaa meren kuohun kukkuloita;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'hän loi Seulaset ja Kalevanmiekan, Otavan ja eteläiset tähtitarhat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'hän tekee suuria, tutkimattomia tekoja, ihmeitä ilman määrää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Katso, hän käy ohitseni, enkä minä häntä näe; hän liitää ohi, enkä minä häntä huomaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Katso, hän tempaa saaliinsa, kuka voi häntä estää, kuka sanoa hänelle: \'Mitä sinä teet?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Jumala ei taltu vihastansa; hänen allensa vaipuvat Rahabin auttajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Minäkö sitten voisin vastata hänelle, valita sanojani häntä vastaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Vaikka oikeassakin olisin, en saisi vastatuksi; minun täytyisi tuomariltani armoa anoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Jos minä huutaisin ja hän minulle vastaisikin, en usko, että hän ottaisi korviinsa huutoani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'hän, joka ajaa minua takaa myrskytuulessa ja lisää haavojeni lukua syyttömästi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'joka ei anna minun vetää henkeäni, vaan täyttää minut katkeralla tuskalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Jos väkevän voimaa kysytään, niin hän sanoo: \'Tässä olen!\' mutta jos oikeutta, niin: \'Kuka vetää minut tilille?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Vaikka olisin oikeassa, niin oma suuni tuomitsisi minut syylliseksi; vaikka olisin syytön, niin hän kuitenkin minut vääräksi tekisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Syytön minä olen. En välitä hengestäni, elämäni on minulle halpa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Yhdentekevää kaikki; sentähden minä sanon: hän lopettaa niin syyttömän kuin syyllisenkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Jos ruoska äkkiä surmaa, niin hän pilkkaa viattomain epätoivoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Maa on jätetty jumalattoman valtaan, hän peittää sen tuomarien kasvot-ellei hän, kuka sitten?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Minun päiväni rientävät juoksijata nopeammin, pakenevat onnea näkemättä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'ne kiitävät pois niinkuin ruokovenheet, niinkuin kotka, joka iskee saaliiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Jos ajattelen: tahdon unhottaa tuskani, muuttaa muotoni ja ilostua,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'niin minä kauhistun kaikkia kipujani, tiedän, ettet julista minua viattomaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Syyllisenä täytyy minun olla; miksi turhaan itseäni vaivaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Jos vaikka lumessa peseytyisin ja puhdistaisin käteni lipeällä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'silloinkin sinä upottaisit minut likakuoppaan, niin että omat vaatteeni minua inhoisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Sillä ei ole hän ihminen niinkuin minä, voidakseni vastata hänelle ja käydäksemme oikeutta keskenämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Ei ole meillä riidanratkaisijaa, joka laskisi kätensä meidän molempien päälle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'ja ottaisi hänen vitsansa pois minun päältäni, niin ettei hänen kauhunsa peljättäisi minua;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'silloin minä puhuisin enkä häntä pelkäisi, sillä ei ole mitään sellaista tunnollani.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, '\"Minun sieluni on kyllästynyt elämään; minä päästän valitukseni valloilleen ja puhun sieluni murheessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'minä sanon Jumalalle: \'Älä tuomitse minua syylliseksi; ilmaise minulle, miksi vaadit minua tilille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Onko sinulla hyötyä siitä, että teet väkivaltaa, että oman käsialasi hylkäät, mutta valaiset jumalattomain neuvoa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Onko sinulla lihan silmät, katsotko, niinkuin ihminen katsoo?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Ovatko sinun päiväsi niinkuin ihmisen päivät, ovatko vuotesi niinkuin miehen vuodet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'koska etsit vääryyttä minusta ja tutkit minun syntiäni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'vaikka tiedät, etten ole syyllinen ja ettei ole ketään, joka sinun käsistäsi auttaa?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Sinun kätesi ovat minut luoneet ja tehneet; yhtäkaikki minut perin juurin tuhoat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Muista, että sinä olet muovaillut minut niinkuin saven, ja nyt muutat minut tomuksi jälleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Etkö sinä valanut minua niinkuin maitoa ja juoksuttanut niinkuin juustoa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Sinä puetit minut nahalla ja lihalla ja kudoit minut luista ja jänteistä kokoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Elämän ja armon olet sinä minulle suonut, ja sinun huolenpitosi on varjellut minun henkeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'Mutta sinä kätkit sydämeesi tämän; minä tiedän, että tämä oli sinun mielessäsi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'jos minä syntiä tein, niin sinä vartioitsit minua, ja minun rikostani et antanut anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Jos olisin syyllinen, niin voi minua! Ja vaikka olisin oikeassa, en kuitenkaan voisi päätäni nostaa, häpeästä kylläisenä ja kurjuuttani katsellen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Jos minun pääni nousee, niin sinä ajat minua niinkuin leijona ja teet yhä ihmeitäsi minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Sinä hankit yhä uusia todistajia minua vastaan, ja vihasi minuun kasvaa, ja sinä tuot vereksiä joukkoja minun kimppuuni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Miksi toit minut ilmoille äitini kohdusta? Jospa olisin kuollut, ihmissilmän näkemätönnä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Niin minä olisin, niinkuin minua ei olisi ollutkaan; minut olisi kannettu äidin kohdusta hautaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Ovathan päiväni vähissä; hän antakoon minun olla rauhassa, hän kääntyköön minusta pois, että hiukkasen ilostuisin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'ennenkuin lähden, ikinä palajamatta, pimeyden ja synkeyden maahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'maahan, jonka pimeys on synkkä pilkkopimeä ja sekasorto ja jossa valkeneminenkin on pimeyttä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Sitten naemalainen Soofar lausui ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, '\"Jäisikö suulas puhe vastausta vaille, ja saisiko suupaltti olla oikeassa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Saattaisivatko jaarituksesi miehet vaikenemaan, niin että saisit pilkata, kenenkään sinua häpeään häätämättä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Sanoithan: \'Minun opetukseni on selkeä, ja minä olen puhdas sinun silmissäsi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Mutta jospa Jumala puhuisi ja avaisi huulensa sinua vastaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'ja ilmaisisi sinulle viisauden salaisuudet, että hänellä on ymmärrystä monin verroin! Silloin huomaisit, että Jumala on painanut unhoon montakin pahaa tekoasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Sinäkö käsittäisit Jumalan tutkimattomuuden tahi pääsisit Kaikkivaltiaan täydellisyydestä perille?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Se on korkea kuin taivas-mitä voit tehdä, syvempi kuin tuonela-mitä voit ymmärtää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Se on pitempi kuin maa ja laveampi kuin meri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Jos hän liitää paikalle ja vangitsee ja kutsuu oikeuden kokoon, niin kuka voi häntä estää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Sillä hän tuntee valheen miehet, vääryyden hän näkee tarkkaamattakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Onttopäinen mies voi viisastua ja villiaasin varsa ihmistyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Jos sinäkin valmistat sydämesi ja ojennat kätesi hänen puoleensa-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'mutta jos kädessäsi on vääryys, heitä se kauas äläkä anna petoksen asua majoissasi-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'silloin saat kohottaa kasvosi ilman häpeän tahraa, olet kuin vaskesta valettu etkä mitään pelkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Silloin unhotat onnettomuutesi, muistelet sitä kuin vettä, joka on virrannut pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'Elämäsi selkenee kirkkaammaksi keskipäivää, pimeänkin aika on niinkuin aamunkoitto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'Silloin olet turvassa, sillä sinulla on toivo; tähystelet-käyt turvallisesti levolle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'asetut makaamaan, kenenkään peljättämättä, ja monet etsivät sinun suosiotasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Mutta jumalattomain silmät raukeavat; turvapaikka on heiltä mennyt, ja heidän toivonsa on huokaus.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, '\"Totisesti, te yksin olette kansa, ja teidän mukananne kuolee viisaus!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Onhan minullakin ymmärrystä yhtä hyvin kuin teillä; en ole minä teitä huonompi, ja kuka ei moisia tietäisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Ystävänsä pilkkana on hän, jota Jumala kuuli, kun hän häntä huusi, hurskas, nuhteeton on pilkkana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Turvassa olevan mielestä sopii onnettomuudelle ylenkatse; se on valmiina niille, joiden jalka horjuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Ja rauhassa ovat väkivaltaisten majat, turvassa ne, jotka ärsyttävät Jumalaa, ne, jotka kantavat jumalansa kourassaan.\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, '\"Mutta kysypä eläimiltä, niin ne opettavat sinua, ja taivaan linnuilta, niin ne ilmoittavat sinulle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'tahi tutkistele maata, niin se opettaa sinua, ja meren kalat kertovat sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Kuka kaikista näistä ei tietäisi, että Herran käsi on tämän tehnyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'hänen, jonka kädessä on kaiken elävän sielu ja kaikkien ihmisolentojen henki?\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, '\"Eikö korva koettele sanoja ja suulaki maista ruuan makua?\" 12:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, '\"Vanhuksilla on viisautta, ja pitkä-ikäisillä ymmärrystä.\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, '\"Jumalalla on viisaus ja voima, hänellä neuvo ja ymmärrys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Jos hän repii maahan, niin ei rakenneta jälleen; kenen hän telkeää sisälle, sille ei avata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Katso, hän salpaa vedet, ja syntyy kuivuus; hän laskee ne irti, ja ne mullistavat maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Hänen on väkevyys ja ymmärrys; hänen on niin eksynyt kuin eksyttäjäkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Hän vie neuvosmiehet pois paljaiksi riistettyinä ja tekee tuomarit tyhmiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Kuningasten kurituksesta hän kirvoittaa ja köyttää köyden heidän omiin vyötäisiinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Hän vie papit pois paljaiksi riistettyinä, ja ikimahtavat hän kukistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Hän hämmentää luotettavain puheen ja ottaa pois vanhoilta taidon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Hän vuodattaa ylenkatsetta ruhtinasten päälle ja aukaisee virtojen padot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'Hän paljastaa syvyydet pimeyden peitosta ja tuo valoon pilkkopimeän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Hän korottaa kansat, ja hän hävittää ne, hän laajentaa kansakunnat, ja hän kuljettaa ne pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'Maan kansan päämiehiltä hän ottaa ymmärryksen ja panee heidät harhailemaan tiettömissä autioissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'He haparoivat pimeässä valoa vailla, ja hän panee heidät hoipertelemaan kuin juopuneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, '\"Katso, kaikkea tätä on silmäni nähnyt, korvani kuullut ja sitä tarkannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Mitä te tiedätte, sen tiedän minäkin; en ole minä teitä huonompi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Mutta minä mielin puhua Kaikkivaltiaalle, minä tahdon tuoda todistukseni Jumalaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Sillä te laastaroitte valheella, olette puoskareita kaikki tyynni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Jospa edes osaisitte visusti vaieta, niin se olisi teille viisaudeksi luettava!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Kuulkaa siis, mitä minä todistan, ja tarkatkaa, mitä huuleni väittävät vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Tahdotteko puolustaa Jumalaa väärällä puheella ja puhua vilppiä hänen puolestaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'tahdotteko olla puolueellisia hänen hyväksensä tahi ajaa Jumalan asiaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Koituuko siitä silloin hyvää, kun hän käy teitä tutkimaan; tahi voitteko pettää hänet, niinkuin ihminen petetään?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Hän teitä ankarasti rankaisee, jos salassa olette puolueellisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Eikö hänen korkeutensa peljästytä teitä ja hänen kauhunsa teitä valtaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Tuhkalauselmia ovat teidän mietelauseenne, savivarustuksia silloin teidän varustuksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Vaietkaa, antakaa minun olla, niin minä puhun, käyköön minun miten tahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Miksi minä otan lihani hampaisiini ja panen henkeni kämmenelleni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Katso, hän surmaa minut, en minä enää mitään toivo; tahdon vain vaellustani puolustaa häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Jo sekin on minulle voitoksi; sillä jumalaton ei voi käydä hänen kasvojensa eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Kuulkaa tarkasti minun puhettani, ja mitä minä lausun korvienne kuullen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Katso, olen ryhtynyt käymään oikeutta; minä tiedän, että olen oikeassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Kuka saattaa käräjöidä minua vastaan? Silloin minä vaikenen ja kuolen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Kahta vain älä minulle tee, niin en lymyä sinun kasvojesi edestä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'ota pois kätesi minun päältäni, ja älköön kauhusi minua peljättäkö;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'sitten haasta, niin minä vastaan, tahi minä puhun, ja vastaa sinä minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Mikä on minun pahain tekojeni ja syntieni luku? Ilmaise minulle rikkomukseni ja syntini.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Miksi peität kasvosi ja pidät minua vihollisenasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Lentävää lehteäkö peljätät, kuivunutta korttako vainoat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'koskapa määräät katkeruuden minun osakseni ja perinnökseni nuoruuteni pahat teot,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'koska panet jalkani jalkapuuhun, vartioitset kaikkia minun polkujani ja piirrät rajan jalkapohjieni ääreen?\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, '\"Hän hajoaa kuin lahopuu, kuin koinsyömä vaate.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, '\"Ihminen, vaimosta syntynyt, elää vähän aikaa ja on täynnä levottomuutta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'kasvaa kuin kukkanen ja lakastuu, pakenee kuin varjo eikä pysy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Ja sellaista sinä pidät silmällä ja viet minut käymään oikeutta kanssasi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Syntyisikö saastaisesta puhdasta? Ei yhden yhtäkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Hänen päivänsä ovat määrätyt, ja hänen kuukausiensa luku on sinun tiedossasi; sinä olet asettanut hänelle määrän, jonka ylitse hän ei pääse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Niin käännä katseesi pois hänestä, että hän pääsisi rauhaan ja että hän saisi iloita niinkuin palkkalainen päivän päätettyään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Onhan puullakin toivo: vaikka se maahan kaadetaan, kasvaa se uudelleen, eikä siltä vesaa puutu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Vaikka sen juuri vanhenee maassa ja sen kanto kuolee multaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'niin se veden tuoksusta versoo jälleen ja tekee oksia niinkuin istukas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Mutta mies kun kuolee, makaa hän martaana; kun ihminen on henkensä heittänyt, missä hän on sitten?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Vesi juoksee pois järvestä, ja joki tyhjenee ja kuivuu;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'niin ihminen lepoon mentyänsä ei enää nouse. Ennenkuin taivaat katoavat, eivät he heräjä eivätkä havahdu unestansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Oi, jospa kätkisit minut tuonelaan, piilottaisit minut, kunnes vihasi on asettunut, panisit minulle aikamäärän ja sitten muistaisit minua!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Kun mies kuolee, virkoaako hän jälleen henkiin? Minä vartoaisin kaikki sotapalvelukseni päivät, kunnes pääsyvuoroni joutuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Sinä kutsuisit, ja minä vastaisin sinulle, sinä ikävöitsisit kättesi tekoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Silloin sinä laskisit minun askeleeni, et pitäisi vaaria minun synnistäni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'rikokseni olisi sinetillä lukittuna kukkaroon, ja pahat tekoni sinä peittäisit piiloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Mutta vuorikin vyöryy ja hajoaa, ja kallio siirtyy sijaltansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'vesi kuluttaa kivet, ja rankkasade huuhtoo pois maan mullan; niin sinä hävität ihmisen toivon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Sinä masennat hänet iäksi, ja hän lähtee; sinä muutat hänen muotonsa ja lähetät hänet menemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Kohoavatko hänen lapsensa kunniaan-ei hän sitä tiedä, vaipuvatko vähäisiksi-ei hän heitä huomaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Hän tuntee vain oman ruumiinsa kivun, vain oman sielunsa murheen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Sitten teemanilainen Elifas lausui ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, '\"Vastaako viisas tuulta pieksämällä, täyttääkö hän rintansa itätuulella?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Puolustautuuko hän puheella, joka ei auta, ja sanoilla, joista ei ole hyötyä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Itse jumalanpelonkin sinä teet tyhjäksi ja rikot hartauden Jumalaa rukoilevilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Sillä sinun pahuutesi panee sanat suuhusi, ja sinä valitset viekasten kielen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Oma suusi julistaa sinut syylliseksi, enkä minä; omat huulesi todistavat sinua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Sinäkö synnyit ihmisistä ensimmäisenä, luotiinko sinut ennenkuin kukkulat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Oletko sinä kuulijana Jumalan neuvottelussa ja anastatko viisauden itsellesi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Mitä sinä tiedät, jota me emme tietäisi? Mitä sinä ymmärrät, jota me emme tuntisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Onpa meidänkin joukossamme harmaapää ja vanhus, isääsi iällisempi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Vähäksytkö Jumalan lohdutuksia ja sanaa, joka sinua piteli hellävaroin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Miksi sydämesi tempaa sinut mukaansa, miksi pyörivät silmäsi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'niin että käännät kiukkusi Jumalaa vastaan ja syydät suustasi sanoja?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Kuinka voisi ihminen olla puhdas, kuinka vaimosta syntynyt olla vanhurskas!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Katso, pyhiinsäkään hän ei luota, eivät taivaatkaan ole puhtaat hänen silmissänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'saati sitten ihminen, inhottava ja kelvoton, joka juo vääryyttä niinkuin vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Minä julistan sinulle, kuule minua, minä kerron, mitä olen nähnyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'mitä viisaat ilmoittavat, salaamatta, mitä olivat isiltänsä saaneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'niiltä, joille yksin maa oli annettuna ja joiden seassa ei muukalainen liikkunut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, '\'Jumalattomalla on tuska koko elämänsä ajan, ne vähät vuodet, jotka väkivaltaiselle on määrätty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Kauhun äänet kuuluvat hänen korvissansa, keskellä rauhaakin hänet yllättää hävittäjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Ei usko hän pääsevänsä pimeydestä, ja hän on miekalle määrätty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Hän harhailee leivän haussa: missä sitä on? Hän tuntee, että hänen vierellään on valmiina pimeyden päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Tuska ja ahdistus kauhistuttavat häntä, masentavat hänet niinkuin kuningas valmiina hyökkäykseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Koska hän ojensi kätensä Jumalaa vastaan ja pöyhkeili Kaikkivaltiasta vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'ryntäsi häntä vastaan niska jäykkänä, taajain kilvenkupurainsa suojassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'koska hän kasvatti ihraa kasvoihinsa ja teki lanteensa lihaviksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'asui hävitetyissä kaupungeissa, taloissa, joissa ei ollut lupa asua,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'jotka olivat määrätyt jäämään raunioiksi, sentähden hän ei rikastu, eikä hänen omaisuutensa ole pysyväistä, eikä hänen viljansa notkistu maata kohden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Ei hän pääse pimeydestä; tulen liekki kuivuttaa hänen vesansa, ja hän hukkuu hänen suunsa henkäyksestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Älköön hän turvatko turhuuteen-hän pettyy; sillä hänen voittonsa on oleva turhuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Mitta täyttyy ennen aikojaan, eikä hänen lehvänsä vihannoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Hän on niinkuin viinipuu, joka pudottaa raakaleensa, niinkuin öljypuu, joka varistaa kukkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Sillä jumalattoman joukkio on hedelmätön, ja tuli kuluttaa lahjustenottajan majat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'He kantavat tuhoa ja synnyttävät turmiota, ja heidän kohtunsa valmistaa petosta.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, '\"Tuonkaltaista olen kuullut paljon; kurjia lohduttajia olette kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Eikö tule jo loppu tuulen pieksämisestä, vai mikä yllyttää sinua vastaamaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Voisinhan minä myös puhua niinkuin tekin, jos te olisitte minun sijassani; voisin sommitella sanoja teitä vastaan ja ilkkuen nyökytellä teille päätäni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'rohkaista teitä suullani ja tuottaa huojennusta huulteni lohduttelulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Jos puhun, ei tuskani helpota, ja jos lakkaan, lähteekö se sillä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Mutta nyt hän on minut uuvuttanut. Sinä olet hävittänyt koko minun joukkoni');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'ja olet minut kukistanut-siitä muka tuli todistaja-ja raihnauteni nousi minua vastaan, syyttäen minua vasten silmiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Hänen vihansa raateli ja vainosi minua, hän kiristeli minulle hampaitansa. Viholliseni hiovat katseitaan minua vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'he avaavat minulle kitansa ja lyövät häväisten minua poskille; kaikki he yhtyvät minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Jumala jättää minut poikaheittiöiden valtaan ja syöksee minut jumalattomain käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Minä elin rauhassa, mutta hän peljätti minut, hän tarttui minua niskaan ja murskasi minut. Hän asetti minut maalitaulukseen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'hänen nuolensa viuhuvat minun ympärilläni. Hän halkaisee munuaiseni säälimättä, vuodattaa maahan minun sappeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Hän murtaa minuun aukon toisensa jälkeen ja ryntää kimppuuni kuin soturi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Minä ompelin säkin iholleni ja painoin sarveni tomuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Minun kasvoni punoittavat itkusta, ja silmäluomillani on pimeys,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'vaikkei ole vääryyttä minun käsissäni ja vaikka minun rukoukseni on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'Maa, älä peitä minun vertani, ja minun huudollani älköön olko lepopaikkaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Katso, nytkin on minun todistajani taivaassa ja puolustajani korkeudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Ystäväni pitävät minua pilkkanansa-Jumalaan minun silmäni kyynelöiden katsoo,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'että hän hankkisi miehelle oikeuden Jumalaa vastaan ja ihmislapselle hänen lähimmäistään vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Sillä vähän on vuosia edessäni enää, ja sitten menen tietä, jota en palaja.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, '\"Minun henkeni on rikki raastettu, minun päiväni sammuvat, kalmisto on minun osani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Totisesti, pilkka piirittää minua ja silmäni täytyy yhä katsella heidän ynseilyänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Aseta puolestani pantti talteesi; kuka muu rupeaisi kättä lyöden minun takaajakseni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Sillä sinä olet sulkenut ymmärrykseltä heidän sydämensä; sentähden sinä et päästä heitä voitolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Ystäviä kutsutaan osajaolle, mutta omilta lapsilta raukeavat silmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Minut on pantu kansoille sananlaskuksi; silmille syljettäväksi minä olen tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Minun silmäni on hämärtynyt surusta, ja kaikki minun jäseneni ovat kuin varjo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Tästä oikeamieliset hämmästyvät, ja viatonta kuohuttaa jumalattoman meno.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Mutta hurskas pysyy tiellänsä, ja se, jolla on puhtaat kädet, kasvaa voimassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Mutta te kaikki, tulkaa jälleen tänne; en löydä minä viisasta joukostanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Päiväni ovat menneet, rauenneet ovat aivoitukseni, mitä sydämeni ikävöitsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Yön he tekevät päiväksi; valo muka lähenee pimeydestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Jos kuinka toivon, on tuonela asuntoni; minä levitän vuoteeni pimeyteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'minä sanon haudalle: \'Sinä olet isäni\', ja madoille: \'Äitini ja sisareni\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Missä on silloin minun toivoni, ja kuka saa minun toivoani katsella?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Ne astuvat alas tuonelan salpojen taa, kun yhdessä lepäämme tomussa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Sitten suuhilainen Bildad lausui ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, '\"Kuinka kauan te asetatte sanoille ansoja? Tulkaa järkiinne, sitten puhelemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Miksi meitä pidetään elukkain veroisina, olemmeko teidän silmissänne tylsät?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Sinä, joka raivossasi raatelet itseäsi-sinunko tähtesi jätettäisiin maa autioksi ja kallio siirtyisi sijaltansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Ei, jumalattomain valo sammuu, eikä hänen tulensa liekki loista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Valo pimenee hänen majassansa, ja hänen lamppunsa sammuu hänen päänsä päältä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Hänen väkevät askeleensa supistuvat ahtaalle, ja hänen oma neuvonsa kaataa hänet maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Sillä hänen omat jalkansa vievät hänet verkkoon, hän käyskentelee katetun pyyntihaudan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Paula tarttuu hänen kantapäähänsä, ansa käy häneen kiinni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'hänelle on maahan kätketty pyydys, polulle häntä varten silmukka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Kauhut peljättävät häntä kaikkialta ja ajavat häntä kintereillä kiitäen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Nälkäiseksi käy hänen vaivansa, ja turmio vartoo hänen kaatumistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Hänen ruumiinsa jäseniä kalvaa, hänen jäseniänsä kalvaa kuoleman esikoinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Hänet temmataan pois majastansa, turvastansa; hänet pannaan astumaan kauhujen kuninkaan tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Hänen majassansa asuu outoja, hänen asuinpaikallensa sirotetaan tulikiveä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Alhaalta kuivuvat hänen juurensa, ylhäältä kuihtuvat hänen oksansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Hänen muistonsa katoaa maasta, eikä hänen nimeänsä kadulla mainita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Hänet sysätään valosta pimeyteen ja karkoitetaan maan piiristä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Ei sukua, ei jälkeläistä ole hänellä kansansa seassa, eikä ketään jää jäljelle hänen asuntoihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Lännen asujat hämmästyvät hänen tuhopäiväänsä, idän asujat valtaa vavistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Näin käy väärintekijän huoneelle, näin sen asuinpaikalle, joka ei Jumalasta välitä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, '\"Kuinka kauan te vaivaatte minun sieluani ja runtelette minua sanoillanne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Jo kymmenenkin kertaa olette minua häväisseet, häpeämättä te minua rääkkäätte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Olenko todella hairahtunut, yöpyykö hairahdukseni minun luonani?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Tahi voitteko todella ylvästellä minua vastaan ja todistaa minun ansainneen häpeäni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Tietäkää siis, että Jumala on tehnyt minulle vääryyttä ja on kietonut minut verkkoonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Katso, minä huudan: \'Väkivaltaa!\' enkä saa vastausta; huudan apua, mutta ei ole mitään oikeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Hän on aidannut tieni, niin etten pääse ylitse, ja on levittänyt pimeyden poluilleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Hän on riisunut minulta kunniani ja ottanut kruunun minun päästäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Hän repi minut maahan joka puolelta, niin että olen mennyttä, ja hän tempasi irti toivoni niinkuin puun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Hän päästi vihansa syttymään minua vastaan ja piti minua vihollisenansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Hänen sotajoukkonsa tulivat yhdessä ja tekivät tiensä minua vastaan ja leiriytyivät minun majani ympärille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Veljeni hän on minusta loitontanut; tuttavani ovat minusta aivan vieraantuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Läheiseni ovat minusta luopuneet, ja uskottuni ovat unhottaneet minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Ne, jotka talossani majailevat, ja palvelijattareni pitävät minua muukalaisena, minä olen tullut vieraaksi heidän silmissään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Minä kutsun palvelijaani, eikä hän vastaa; minun suuni täytyy nöyrästi rukoilla häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Hengitykseni on vastenmielinen vaimolleni, hajuni on äitini pojista ilkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Poikasetkin halveksivat minua; kun nousen, niin he puhuvat minusta pilkkojaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Kaikki seuratoverini inhoavat minua, ja ne, joita minä rakastin, ovat kääntyneet minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Luuni ovat tarttuneet nahkaani, ihooni, eikä minusta ole enää kuin ikenet jäljellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Armahtakaa minua, armahtakaa, te, minun ystäväni, sillä Jumalan käsi on minuun koskenut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Miksi vainoatte minua niinkuin Jumala, ettekä saa kylläänne minun lihastani?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Oi, jospa minun sanani kirjoitettaisiin muistiin, jospa ne piirrettäisiin kirjaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'rautataltalla ja lyijyllä hakattaisiin kallioon ikuisiksi ajoiksi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Mutta minä tiedän lunastajani elävän, ja viimeisenä hän on seisova multien päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'Ja sittenkuin tämä nahka on yltäni raastettu ja olen ruumiistani irti, saan minä nähdä Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Hänet olen minä näkevä apunani; minun silmäni saavat nähdä hänet-eikä vieraana. Munaskuuni hiukeavat sisimmässäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Kun sanotte: \'Kuinka vainoammekaan häntä!\' -minusta muka löydetään asian juuri-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'niin peljätkää miekkaa, sillä viha on kohtaava miekanalaisia pahoja töitä, tietääksenne, että tuomari on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Naemalainen Soofar lausui ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, '\"Tuohon minun ajatukseni tuovat vastauksen, moisesta minun mieleni kuohuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Häpäisevää nuhdetta täytyy minun kuulla, mutta minun ymmärrykseni henki antaa minulle vastauksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Tuoko on sinulla tietoa ikiajoista asti, siitä saakka, kun ihminen maan päälle pantiin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Ei, vaan jumalattomain riemu loppuu lyhyeen, ja riettaan ilo on vain silmänräpäys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Vaikka hänen kopeutensa kohoaa taivaaseen ja hänen päänsä ulottuu pilviin asti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'katoaa hän kuitenkin ainiaaksi oman likansa lailla; jotka näkivät hänet, kysyivät: Missä hän on?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Niinkuin uni hän lentää pois, eikä häntä enää löydetä, ja hän häipyy kuin öinen näky.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Silmä, joka häntä katseli, ei katsele häntä enää, eikä hänen paikkansa häntä enää näe.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Hänen poikiensa täytyy hyvittää köyhät, hänen kättensä on annettava pois hänen omaisuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Nuoruuden voimaa olivat täynnä hänen luunsa, mutta sen täytyi mennä maata multaan hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Vaikka paha onkin makeaa hänen suussaan, niin että hän kätkee sen kielensä alle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'säästää sitä eikä siitä luovu, vaan pidättää sitä keskellä suulakeansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'niin muuttuu tämä ruoka hänen sisässään, tulee kyykäärmeiden kähyiksi hänen sisälmyksissänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Hän nieli rikkautta, ja hänen täytyy se oksentaa pois, Jumala ajaa sen ulos hänen vatsastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Kyykäärmeiden myrkkyä hän imi, kyyn kieli hänet tappaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Ei hän saa ilokseen katsella puroja, ei hunaja-ja kermajokia ja-virtoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Hänen on annettava pois hankkimansa, eikä hän saa sitä itse niellä; ei ole hänen ilonsa hänen voittamansa rikkauden veroinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Sillä hän teki vaivaisille väkivaltaa ja heitti heidät siihen, hän ryösti itselleen talon, eikä saa siinä rakennella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Sillä hän ei tuntenut vatsansa ikinä tyytyvän, mutta ei pelastu hän himotulla tavarallaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Ei mikään säilynyt hänen ahmailultaan, sentähden hänen onnensa ei kestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Yltäkylläisyytensä runsaudessa on hänellä hätä, häneen iskevät kaikki kurjien kourat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Kun hän on täyttämässä vatsaansa, lähettää Jumala hänen kimppuunsa vihansa hehkun ja antaa sen sataa hänen päällensä hänen syödessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Jos hän pakenee rautavaruksia, niin lävistää hänet vaskijousi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'kun hän vetää ulos selästään nuolen, käy hänen sappensa lävitse miekan salama. Kauhut valtaavat hänet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'kaikki pimeys on varattu hänen aarteilleen. Hänet kuluttaa tuli, joka palaa lietsomatta, se syö, mitä on säilynyt hänen majassansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Taivas paljastaa hänen pahat tekonsa, maa nousee häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Minkä hänen talonsa tuotti, menee menojaan vihan päivänä niinkuin tulvavedet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Tämä on jumalattoman ihmisen osa Jumalalta, perintöosa, jonka Jumala hänelle määrää.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, '\"Kuulkaa, kuulkaa minun sanojani ja suokaa minulle se lohdutus!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Kärsikää minua, että saan puhua. Kun olen puhunut, pilkatkaa sitten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Ihmisiäkö vastaan minä valitan? Tahi kuinka en kävisi kärsimättömäksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Kääntykää minuun, niin tyrmistytte ja panette kätenne suullenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Kun käyn ajattelemaan, niin kauhistun, ja vavistus valtaa ruumiini:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Miksi jumalattomat saavat elää, vanheta, jopa voimassa vahvistua?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Heidän sukunsa on vankkana heidän edessään, heidän jälkeläisensä heidän silmäinsä alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Heidän kotinsa ovat rauhassa, kauhuista kaukana; ei satu heihin Jumalan vitsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Hänen sonninsa polkee eikä turhaan, hänen lehmänsä poikii eikä kesken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Poikansa he laskevat ulos niinkuin lammaslauman, heidän lapsensa hyppelevät leikiten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'He virittävät laulujaan vaskirummun ja kanteleen kaikuessa ja iloitsevat huilun soidessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'He viettävät päivänsä onnessa, mutta äkkiä heidät säikähytetään alas tuonelaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Ja kuitenkin he sanoivat Jumalalle: \'Mene pois meidän luotamme, sinun teistäsi emme tahdo tietää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Mikä on Kaikkivaltias, että häntä palvelisimme? Ja mitä hyötyä meillä on siitä, että häntä rukoilemme?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Katso, heidän onnensa ei ole heidän omassa kädessänsä. Jumalattomain neuvo olkoon minusta kaukana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Kuinkapa usein jumalattomain lamppu sammuu ja heidät yllättää heidän turmionsa? Kuinkapa usein hän jakelee arpaosat vihassansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Ovatko he niinkuin tuulen vietävät oljet, niinkuin akanat, jotka tuulispää tempaa mukaansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Jumala muka säästää hänen lapsilleen hänen onnettomuutensa. Kostakoon hän hänelle itselleen, niin että hän sen tuntee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Nähköön hän perikatonsa omin silmin, juokoon itse Kaikkivaltiaan vihan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Sillä mitä hän välittää perheestänsä, jälkeensä jäävistä, kun hänen kuukausiensa luku on täysi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Onko opetettava ymmärrystä Jumalalle, hänelle, joka taivaallisetkin tuomitsee?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Toinen kuolee täydessä onnessansa, kaikessa rauhassa ja levossa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'hänen astiansa ovat maitoa täynnä, ja hänen luunsa juotetaan ytimellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Toinen kuolee katkeralla mielellä, saamatta onnea maistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Yhdessä he panevat maata multaan, ja madot peittävät heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Katso, minä tunnen teidän ajatuksenne ja juonet, joilla mielitte sortaa minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Kun sanotte: \'Missä on nyt mahtimiehen talo, missä maja, jossa jumalattomat asuivat?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'niin ettekö ole kysyneet maita kulkeneilta? Ette voi kieltää, mitä he ovat todeksi nähneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'että paha säästetään onnettomuuden päivältä, vihan päivältä hänet saatetaan suojaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Kuka puhuu hänelle vasten kasvoja hänen vaelluksestaan, kuka kostaa hänelle, mitä hän on tehnyt?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Hänet saatetaan kalmistoon, ja hänen hautakumpuansa vaalitaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Kepeät ovat hänelle laakson turpeet. Kaikki ihmiset seuraavat hänen jäljessänsä, niinkuin epälukuiset ovat kulkeneet hänen edellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Kuinka tuotte minulle niin turhaa lohdutusta? Entä vastauksenne-niistä jää pelkkä petollisuus jäljelle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Teemanilainen Elifas lausui ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, '\"Taitaako ihminen hyödyttää Jumalaa? Ei, vaan ainoastaan itseään hyödyttää ymmärtäväinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Onko Kaikkivaltiaalla etua siitä, jos olet vanhurskas, tahi voittoa siitä, jos vaellat nuhteetonna?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Jumalanpelostasiko hän sinua rankaisee ja käy kanssasi oikeutta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Eikö pahuutesi ole suuri ja sinun pahat tekosi loppumattomat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Sillä otithan veljiltäsi pantin syyttä ja riistit vaatteet alastomilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Et antanut nääntyvälle vettä juoda, ja nälkäiseltä kielsit leivän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Kovakouraisen omaksi tuli maa, ja vain korkea-arvoinen sai siinä asua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Lesket sinä lähetit luotasi tyhjin käsin, ja orpojen käsivarret murskattiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Sentähden paulat nyt sinua ympäröivät, ja äkillinen peljästys kauhistuttaa sinut-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'vai etkö näe pimeyttä? -ja vesitulva peittää sinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Eikö Jumala ole korkea kuin taivas? Katso, kuinka korkealla on tähtien päälaki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Ja niin sinä sanot: \'Mitäpä Jumala tietää? Voiko hän tuomita synkkäin pilvien takaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Pilvet ovat hänellä verhona, niin ettei hän näe; ja taivaanrannalla hän käyskentelee.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Tahdotko seurata iänikuista polkua, jota pahantekijät vaelsivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'ne, jotka kukistettiin ennen aikojaan ja joiden perustuksen virta huuhtoi pois,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'jotka sanoivat Jumalalle: \'Poistu meistä. Mitä voisi Kaikkivaltias meille tehdä?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Ja kuitenkin hän oli täyttänyt heidän talonsa hyvyydellä. Mutta minusta on kaukana jumalattomain neuvo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Hurskaat näkevät sen ja iloitsevat, ja viaton pilkkaa heitä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, '\'Totisesti, vastustajamme ovat hävinneet, ja mitä heistä jäi, kulutti tuli\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Tee siis sovinto ja elä rauhassa hänen kanssaan, niin saavutat onnen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Ota opetusta hänen suustaan ja kätke hänen sanansa sydämeesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Kun palajat Kaikkivaltiaan tykö, niin tulet raketuksi, jos karkoitat vääryyden majastasi kauas,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'viskaat kulta-aarteesi tomuun ja Oofirin kullan joen kivien joukkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'Jos Kaikkivaltias tulee sinun kulta-aarteeksesi, sinun hopeaharkoiksesi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'silloin on ilosi oleva Kaikkivaltiaassa, ja sinä nostat kasvosi Jumalan puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Kun rukoilet häntä, niin hän kuulee sinua, ja sinä saat täyttää lupauksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Jos mitä päätät, niin se sinulle onnistuu, ja sinun teillesi loistaa valo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Jos tie painuu alaspäin, niin sinä sanot: \'Ylös!\' ja hän auttaa nöyrtyväistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Hän pelastaa senkin, joka ei ole viaton; sinun kättesi puhtauden tähden hän pelastuu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, '\"Tänäänkin on valitukseni niskoittelua! Minun käteni on raskas huokaukseni tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Oi, jospa tietäisin, kuinka löytää hänet, jospa pääsisin hänen asunnolleen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Minä esittäisin hänelle riita-asian ja täyttäisin suuni todisteilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Tahtoisinpa tietää, mitä hän minulle vastaisi, ja kuulla, mitä hän minulle sanoisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Riitelisikö hän kanssani suurella voimallansa? Ei, hän vain tarkkaisi minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Silloin käräjöisi hänen kanssaan rehellinen mies, ja minä pelastuisin tuomaristani ainiaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Katso, minä menen itään, mutta ei ole hän siellä; menen länteen, enkä häntä huomaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'jos hän pohjoisessa toimii, en häntä erota, jos hän kääntyy etelään, en häntä näe.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Sillä hän tietää, kussa minä kuljen. Jos hän tutkisi minut, kullan kaltaisena minä selviäisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Hänen askeleissaan on minun jalkani pysynyt, hänen tietänsä olen noudattanut siltä poikkeamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Hänen huultensa käskystä en ole luopunut, hänen suunsa sanat minä olen kätkenyt tarkemmin kuin omat päätökseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Mutta hän pysyy samana, kuka voi häntä estää? Mitä hän tahtoo, sen hän tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Niin, hän antaa täydellisesti minulle määrätyn osan, ja sellaista on hänellä vielä tallella paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Sentähden valtaa minut kauhu hänen kasvojensa edessä; kun sitä ajattelen, peljästyn häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Jumala on lannistanut minun rohkeuteni, Kaikkivaltias on minut kauhistuttanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Sillä en menehdy pimeän tähden, en oman itseni tähden, jonka pimeys peittää.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, '\"Miksi ei Kaikkivaltias ole varannut tuomion aikoja, ja miksi eivät saa ne, jotka hänet tuntevat, nähdä hänen päiviänsä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Jumalattomat siirtävät rajoja, ryöstävät laumoja ja laskevat ne laitumelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Orpojen aasin he vievät, ottavat pantiksi lesken lehmän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'He työntävät tieltä köyhät, kaikkien maan kurjain täytyy piileskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Katso, nämä ovat kuin villiaasit erämaassa: lähtevät työhönsä saalista etsien, aro on heidän lastensa leipä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Kedolta he korjaavat rehuviljaa ruuakseen, ja jumalattoman viinitarhasta he kärkkyvät tähteitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Alastomina, ilman vaatteita, he viettävät yönsä, eikä heillä ole peittoa kylmässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'He ovat likomärkiä vuorilla vuotavasta sateesta, ja vailla suojaa he syleilevät kalliota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'idin rinnoilta riistetään orpo, ja kurjalta otetaan pantti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'He kuljeskelevat alastomina, ilman vaatteita, ja nälkäisinä he kantavat lyhteitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'Jumalattomain muuritarhoissa he pusertavat öljyä, he polkevat viinikuurnaa ja ovat itse janoissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Kaupungista kuuluu miesten voihkina, ja haavoitettujen sielu huutaa; mutta Jumala ei piittaa nurjuudesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Nuo ovat valon vihaajia, eivät tunne sen teitä eivätkä pysy sen poluilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Ennen päivän valkenemista nousee murhaaja, tappaa kurjan ja köyhän; ja yöllä hän hiipii kuin varas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Avionrikkojan silmä tähyilee hämärää, hän arvelee: \'Ei yksikään silmä minua näe\', ja hän panee peiton kasvoillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'He murtautuvat pimeässä taloihin, päivällä he sulkeutuvat sisään, tahtomatta tietää valosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Sillä pimeys on heille kaikille aamun vertainen, koska pimeyden kauhut ovat heille tutut.\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, '\"Hän kiitää pois vetten viemänä, kirottu on hänen peltopalstansa maassa, hän ei enää poikkea viinimäkien tielle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Kuivuus ja kuumuus ahmaisevat lumiveden, samoin tuonela ne, jotka syntiä tekevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'idin kohtu unhottaa hänet, madot syövät hänet herkkunaan, ei häntä enää muisteta; niin murskataan vääryys kuin puu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Hän ryösti hedelmättömältä, joka ei synnytä, ja leskelle hän ei hyvää tehnyt.\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, '\"Väkivaltaiset Jumala ylläpitää voimallansa; he pysyvät pystyssä, vaikka jo olivat epätoivossa hengestään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Hän antaa heidän olla turvassa, ja heillä on vahva tuki; ja hänen silmänsä valvovat heidän teitänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'He ovat kohonneet korkealle-ei aikaakaan, niin ei heitä enää ole; he vaipuvat kokoon, kuolevat kuin kaikki muutkin, he taittuvat kuin vihneet tähkäpäästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Eikö ole niin? Kuka tekee minut valhettelijaksi ja saattaa sanani tyhjiksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'Sitten suuhilainen Bildad lausui ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, '\"Valta ja peljättävyys on hänen, joka luo rauhaa korkeuksissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Onko määrää hänen joukoillansa, ja kenelle ei hänen valonsa koita?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Kuinka siis ihminen olisi vanhurskas Jumalan edessä, ja kuinka vaimosta syntynyt olisi puhdas?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Katso, eipä kuukaan ole kirkas, eivät tähdetkään ole puhtaat hänen silmissänsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'saati sitten ihminen, tuo mato, ja ihmislapsi, tuo toukka!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Job vastasi ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, '\"Kuinka oletkaan auttanut voimatonta, tukenut heikkoa käsivartta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Kuinka oletkaan neuvonut taitamatonta ja ilmituonut paljon ymmärrystä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Kenelle oikein olet puheesi pitänyt, ja kenen henki on sinusta käynyt?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Haamut alhaalla värisevät, vetten ja niiden asukasten alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Paljaana on tuonela hänen edessänsä, eikä ole manalalla peitettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Pohjoisen hän kaarruttaa autiuden ylle, ripustaa maan tyhjyyden päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Hän sitoo vedet pilviinsä, eivätkä pilvet halkea niiden alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Hän peittää valtaistuimensa näkyvistä, levittää pilvensä sen ylitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Hän on vetänyt piirin vetten pinnalle, siihen missä valo päättyy pimeään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Taivaan patsaat huojuvat ja hämmästyvät hänen nuhtelustaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Voimallansa hän kuohutti meren, ja taidollansa hän ruhjoi Rahabin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Hänen henkäyksestään kirkastui taivas; hänen kätensä lävisti kiitävän lohikäärmeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Katso, nämä ovat ainoastaan hänen tekojensa äärten häämötystä, ja kuinka hiljainen onkaan kuiskaus, jonka hänestä kuulemme! Mutta kuka käsittää hänen väkevyytensä jylinän?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Job jatkoi lausuen julki mietelmiään ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, '\"Niin totta kuin Jumala elää, joka on ottanut minulta oikeuteni, ja Kaikkivaltias, joka on sieluni murehuttanut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'niin kauan kuin minussa vielä henkeä on ja Jumalan henkäystä sieramissani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'eivät minun huuleni puhu petosta, eikä kieleni vilppiä lausu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Pois se! En myönnä teidän oikeassa olevan. Siihen asti kunnes henkeni heitän, en luovu hurskaudestani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Minä pidän kiinni vanhurskaudestani, en hellitä; yhdestäkään elämäni päivästä omatuntoni ei minua soimaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Käyköön viholliseni niinkuin jumalattoman ja vastustajani niinkuin väärän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Mitä toivoa on riettaalla, kun Jumala katkaisee hänen elämänsä, kun hän tempaa pois hänen sielunsa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Kuuleeko Jumala hänen huutonsa, kun ahdistus häntä kohtaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Tahi saattaako hän iloita Kaikkivaltiaasta, huutaa Jumalaa joka aika?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Minä opetan teille, mitä tekee Jumalan käsi; en salaa, mitä Kaikkivaltiaalla on mielessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Katso, itse olette kaikki sen nähneet; miksi te turhia kuvittelette?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Tämä on jumalattoman ihmisen osa, Jumalan varaama, tämä on perintöosa, jonka väkivaltaiset Kaikkivaltiaalta saavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Jos hänellä on paljonkin lapsia, ovat ne miekan omia; eikä hänen jälkeläisillään ole leipää ravinnoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Jotka häneltä jäävät, ne saattaa rutto hautaan, eivätkä hänen leskensä pidä itkiäisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Jos hän kokoaa hopeata kuin multaa ja kasaa vaatteita kuin savea,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'kasatkoon: vanhurskas pukee ne päällensä, ja viaton perii hopean.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Hän rakentaa talonsa niinkuin kointoukka, se on kuin suojus, jonka vartija kyhää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Rikkaana hän menee levolle: \'Ei häviä mitään\'; hän avaa silmänsä, ja kaikki on mennyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Kauhut yllättävät hänet kuin tulvavedet, yöllä tempaa hänet mukaansa rajuilma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Itätuuli vie hänet, niin että hän menee menojaan, ja puhaltaa hänet pois paikaltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Jumala ampuu häneen nuolensa säälimättä; hänen täytyy paeta hänen kättänsä, minkä voi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Silloin paukutetaan hänelle kämmeniä ja vihelletään hänelle hänen asuinpaikaltansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, '\"Hopeallakin on suonensa ja löytöpaikkansa kullalla, joka puhdistetaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'rauta otetaan maasta, ja kivestä sulatetaan vaski.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Tehdään loppu pimeydestä, ja tutkitaan tyystin kivi, jonka synkkä pilkkopimeä peittää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Kaivos louhitaan syvälle maan asujain alle; unhotettuina he riippuvat siellä ilman jalan tukea, heiluvat kaukana ihmisten ilmoilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Maasta kasvaa leipä, mutta maan uumenet mullistetaan kuin tulen voimalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Sen kivissä on safiirilla sijansa, siellä on kultahiekkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Polkua sinne ei tiedä kotka, eikä haukan silmä sitä havaitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Sitä eivät astu ylväät eläimet, ei leijona sitä kulje.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Siellä käydään käsiksi kovaan kiveen, ja vuoret mullistetaan juuriaan myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Kallioihin murretaan käytäviä, ja silmä näkee kaikkinaiset kalleudet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Vesisuonet estetään tihkumasta, ja salatut saatetaan päivänvaloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Mutta viisaus-mistä se löytyy, ja missä on ymmärryksen asuinpaikka?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Ei tunne ihminen sille vertaa, eikä sitä löydy elävien maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Syvyys sanoo: \'Ei ole se minussa\', ja meri sanoo: \'Ei se ole minunkaan tykönäni\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Sitä ei voida ostaa puhtaalla kullalla, eikä sen hintaa punnita hopeassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Ei korvaa sitä Oofirin kulta, ei kallis onyks-kivi eikä safiiri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Ei vedä sille vertoja kulta eikä lasi, eivät riitä sen vaihtohinnaksi aitokultaiset kalut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Koralleja ja kristalleja ei sen rinnalla mainita, ja viisauden omistaminen on helmiä kalliimpi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Ei vedä sille vertoja Etiopian topaasi, ei korvaa sitä puhdas kulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Mistä siis tulee viisaus ja missä on ymmärryksen asuinpaikka?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Se on peitetty kaiken elävän silmiltä, salattu taivaan linnuiltakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Manala ja kuolema sanovat: \'Korvamme ovat kuulleet siitä vain kerrottavan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Jumala tietää tien sen luokse, hän tuntee sen asuinpaikan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Sillä hän katsoo maan ääriin saakka, hän näkee kaiken, mitä taivaan alla on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Kun hän antoi tuulelle voiman ja määräsi mitalla vedet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'kun hän sääti lain sateelle ja ukkospilvelle tien,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'silloin hän sen näki ja ilmoitti, toi sen esille ja sen myös tutki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Ja ihmiselle hän sanoi: \'Katso, Herran pelko-se on viisautta, ja pahan karttaminen on ymmärrystä\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Job jatkoi lausuen mietelmiään ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, '\"Oi, jospa olisin, niinkuin olin ammoin kuluneina kuukausina, niinkuin niinä päivinä, joina Jumala minua varjeli,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'jolloin hänen lamppunsa loisti pääni päällä ja minä hänen valossansa vaelsin pimeyden halki!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Jospa olisin niinkuin kukoistukseni päivinä, jolloin Jumalan ystävyys oli majani yllä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'jolloin Kaikkivaltias oli vielä minun kanssani ja poikani minua ympäröivät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'jolloin askeleeni kylpivät kermassa ja kallio minun vierelläni vuoti öljyvirtoja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Kun menin kaupunkiin porttiaukealle, kun asetin istuimeni torille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'niin nuorukaiset väistyivät nähdessään minut, vanhukset nousivat ja jäivät seisomaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'päämiehet lakkasivat puhumasta ja panivat kätensä suulleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Ruhtinasten ääni vaikeni, ja heidän kielensä tarttui suulakeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Sillä kenen korva minusta kuuli, hän ylisti minua onnelliseksi, kenen silmä minut näki, hän minusta todisti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'minä näet pelastin kurjan, joka apua huusi, ja orvon, jolla ei auttajaa ollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Menehtyväisen siunaus tuli minun osakseni, ja lesken sydämen minä saatoin riemuitsemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Vanhurskaudella minä vaatetin itseni, ja se verhosi minut; oikeus oli minulla viittana ja päähineenä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Minä olin sokean silmä ja ontuvan jalka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Minä olin köyhien isä, ja tuntemattoman asiaa minä tarkoin tutkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Minä särjin väärintekijän leukaluut ja tempasin saaliin hänen hampaistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Silloin ajattelin: \'Pesääni minä saan kuolla, ja minä lisään päiväni paljoiksi kuin hiekka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Onhan juureni vedelle avoinna, ja kaste yöpyy minun oksillani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Kunniani uudistuu alati, ja jouseni nuortuu minun kädessäni.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'He kuuntelivat minua ja odottivat, olivat vaiti ja vartoivat neuvoani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Puhuttuani eivät he enää sanaa sanoneet, vihmana vuoti puheeni heihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'He odottivat minua niinkuin sadetta ja avasivat suunsa niinkuin kevätkuurolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Minä hymyilin heille, kun he olivat toivottomat, ja minun kasvojeni loistaessa eivät he synkiksi jääneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Jos suvaitsin tulla heidän luokseen, niin minä istuin ylinnä, istuin kuin kuningas sotajoukkonsa keskellä, niinkuin se, joka murheelliset lohduttaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, '\"Mutta nyt nauravat minua elinpäiviltään nuoremmat, joiden isiä minä pidin liian halpoina pantaviksi paimenkoiraini pariin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Ja mitäpä hyödyttäisi minua heidän kättensä voima, koska heidän nuoruutensa tarmon on vienyt');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'puute ja kova nälänhätä! He kaluavat kuivaa maata, jo ennestään autiota erämaata;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'he poimivat suolaheiniä pensaiden ympäriltä, ja heidän ruokanaan ovat kinsteripensaan juuret.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Heidät karkoitetaan ihmisten parista; heitä vastaan nostetaan hälytys niinkuin varasta vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Heidän on asuttava kaameissa rotkoissa, maakoloissa ja kallioluolissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Pensaiden keskellä he ulisevat, nokkospehkojen suojaan he sulloutuvat-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'nuo houkkioiden ja kunniattomain sikiöt, jotka on hosuttu maasta pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Heille minä olen nyt tullut pilkkalauluksi, olen heidän jutuksensa joutunut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'he inhoavat minua, väistyvät minusta kauas eivätkä häikäile sylkeä silmilleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Sillä Jumala on höllentänyt jouseni jänteen ja nöyryyttänyt minut, eivätkä he enää suista julkeuttaan minun edessäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Oikealta puoleltani nousee tuo sikiöparvi; he lyövät jalat altani ja luovat turmateitänsä minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'He hävittävät minun polkuni, ovat apuna minua tuhottaessa, vaikka itse ovat ilman auttajaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'niinkuin leveästä muurinaukosta he tulevat, raunioiden alta he vyöryvät esiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Kauhut ovat kääntyneet minua vastaan; niinkuin tuuli sinä pyyhkäiset pois minun arvoni, ja minun onneni katoaa niinkuin pilvi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'Ja nyt minun sieluni vuotaa tyhjiin, kurjuuden päivät ovat saavuttaneet minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Yö kaivaa luut minun ruumiistani, ja kalvavat tuskani eivät lepää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Kaikkivallan voimasta on minun verhoni muodottomaksi muuttunut: se kiristyy ympärilleni niinkuin ihokkaani pääntie.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Hän on heittänyt minut lokaan, ja minä olen tullut tomun ja tuhan kaltaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Minä huudan sinua, mutta sinä et vastaa minulle; minä seison tässä, mutta sinä vain tuijotat minuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Sinä muutut tylyksi minulle, vainoat minua väkevällä kädelläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Sinä kohotat minut myrskytuuleen, kiidätät minut menemään ja annat minun menehtyä rajuilman pauhinassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Niin, minä tiedän: sinä viet minua kohti kuolemaa, majaan, kunne kaikki elävä kokoontuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Mutta eikö saisi hukkuessaan kättänsä ojentaa tahi onnettomuudessa apua huutaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Vai enkö minä itkenyt kovaosaisen kohtaloa, eikö sieluni säälinyt köyhää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Niin, minä odotin onnea, mutta tuli onnettomuus; minä vartosin valoa, mutta tuli pimeys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Sisukseni kuohuvat lakkaamatta, kurjuuden päivät ovat kohdanneet minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Minä käyn murheasussa, ilman päivänpaistetta; minä nousen ja huudan väkijoukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Minusta on tullut aavikkosutten veli ja kamelikurkien kumppani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Minun nahkani on mustunut ja lähtee päältäni, ja luuni ovat kuumuuden polttamat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Niin muuttui kanteleeni soitto valitukseksi ja huiluni sävel itkun ääneksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, '\"Minä olen tehnyt liiton silmäini kanssa: kuinka voisinkaan katsoa neitosen puoleen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Minkä osan antaisi silloin Jumala ylhäältä, minkä perintöosan Kaikkivaltias korkeudesta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Tuleehan väärälle turmio ja onnettomuus väärintekijöille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Eikö hän näkisi minun teitäni ja laskisi kaikkia minun askeleitani?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Jos minä ikinä valheessa vaelsin, jos jalkani kiiruhti petokseen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'punnitkoon minut Jumala oikealla vaa\'alla, ja hän on huomaava minun nuhteettomuuteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Jos minun askeleeni poikkesivat tieltä ja minun sydämeni seurasi silmiäni tahi tahra tarttui minun käsiini,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'niin syököön toinen, mitä minä kylvän, ja minun vesani revittäköön juurinensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Jos minun sydämeni hullaantui toisen vaimoon ja minä väijyin lähimmäiseni ovella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'niin jauhakoon oma vaimoni vieraalle, ja halailkoot häntä muut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'sillä se olisi ollut ilkityö ja raskaasti rangaistava rikos,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'tuli, joka kuluttaisi manalaan saakka ja hävittäisi kaiken saatuni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Jos minä pidin halpana palvelijani ja palvelijattareni oikeuden, kun heillä oli riita minun kanssani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'niin mitä minä tekisin, jos Jumala nousisi, ja mitä vastaisin hänelle, jos hän kävisi tutkimaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Eikö sama, joka äidin kohdussa loi minut, luonut häntäkin, eikö sama meitä äidin sydämen alla valmistanut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Olenko minä kieltänyt vaivaisilta heidän toivomuksensa ja saattanut lesken silmät sammumaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Olenko syönyt leipäpalani yksinäni, orvonkin saamatta syödä siitä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, 'En, vaan nuoruudestani saakka minä kasvatin häntä niinkuin oma isä ja äitini kohdusta asti minä holhosin häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Jos minä näin menehtyväisen vaatteetonna ja köyhän verhoa vailla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'jos hänen lanteensa eivät minua siunanneet eikä hän saanut lämmitellä minun karitsaini villoilla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'jos minä puin nyrkkiä orvolle, kun näin puoltani pidettävän portissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'niin irtautukoon olkapääni hartiastani, ja murtukoon käsivarteni sijoiltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Sillä silloin olisi minun peljättävä turmiota Jumalalta, enkä kestäisi hänen valtasuuruutensa edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Jos minä panin uskallukseni kultaan ja sanoin hienolle kullalle: \'Sinä olet minun turvani\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'jos iloitsin siitä, että rikkauteni oli suuri ja että käteni oli saanut paljon hankituksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'jos katsellessani aurinkoa, kuinka se loisti, ja kuuta, joka ylhänä vaelsi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'sydämeni antautui salaa vieteltäväksi ja käteni niille suudelmia heitti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'niin olisi sekin raskaasti rangaistava rikos, sillä minä olisin kieltänyt korkeuden Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Olenko iloinnut vihamieheni vahingosta, riemusta hykähtänyt, kun häntä onnettomuus kohtasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'En ole sallinut suuni syntiä tehdä, kiroten vaatia hänen henkeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Eikö täydy minun talonväkeni myöntää, että kukin on saanut lihaa yllin kyllin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Muukalaisen ei tarvinnut yötä ulkona viettää; minä pidin oveni auki tielle päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Olenko ihmisten tavoin peitellyt rikkomuksiani, kätkenyt poveeni pahat tekoni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'säikkyen suurta joukkoa ja kaiken heimon ylenkatsetta peljäten, niin että pysyin hiljaa, ovestani ulkonematta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Oi, jospa joku kuuntelisi minua! Katso, tuossa on puumerkkini! Kaikkivaltias vastatkoon minulle! Jospa saisin riitapuoleni kirjoittamaan syytekirjan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Totisesti, olkapäälläni sitä kantaisin, sitoisin sen päähäni seppeleeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Tekisin hänelle tilin kaikista askeleistani ja astuisin hänen eteensä niinkuin ruhtinas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Jos peltoni huusi minua vastaan ja sen vaot kaikki itkivät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'jos kulutin sen voiman maksamatta ja saatoin sen haltijat huokaamaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'niin kasvakoon nisun sijasta orjantappuroita ja ohran sijasta rikkaruohoa.\" Tähän päättyvät Jobin puheet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'Kun nuo kolme miestä eivät enää vastanneet Jobille, koska hän oli omissa silmissään vanhurskas,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'vihastui buusilainen Elihu, Baarakelin poika, joka oli Raamin sukua; Jobiin hän vihastui, koska tämä piti itseään Jumalaa vanhurskaampana,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'ja tämän kolmeen ystävään hän vihastui, koska he eivät keksineet vastausta, jolla olisivat osoittaneet Jobin olevan väärässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Elihu oli odottanut vuoroa puhuakseen Jobille, koska toiset olivat iältään häntä vanhemmat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Mutta kun Elihu näki, ettei noilla kolmella miehellä enää ollut sanaa suussa vastaukseksi, vihastui hän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'Niin buusilainen Elihu, Baarakelin poika, lausui ja sanoi: \"Nuori minä olen iältäni, ja te olette vanhat; sentähden minä arkailin ja pelkäsin ilmoittaa tietoani teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Minä ajattelin: \'Puhukoon ikä, ja vuosien paljous julistakoon viisautta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Mutta onhan ihmisissä henki, ja Kaikkivaltiaan henkäys antaa heille ymmärrystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Eivät iäkkäät ole viisaimmat, eivätkä vanhukset yksin ymmärrä, mikä on oikein.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Sentähden minä sanon: Kuule minua; minäkin ilmoitan, mitä tiedän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Katso, minä olen odottanut, mitä teillä olisi sanomista, olen kuunnellut teidän taitavia puheitanne, kunnes olisitte löytäneet osuvat sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'Niin, minä tarkkasin teitä; mutta katso, ei kukaan ole Jobin sanoja kumonnut, ei kukaan teistä voinut vastata hänen puheisiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Älkää sanoko: \'Meitä vastassa on ilmetty viisaus, vain Jumala voi hänet torjua, ei ihminen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Minua vastaan hän ei ole todisteita tuonut, enkä käy hänelle vastaamaan teidän puheillanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'He ovat kauhistuneet, eivät enää vastaa; sanat puuttuvat heiltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Odottaisinko minä, kun he eivät puhu, kun he siinä seisovat enää vastaamatta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Vastaanpa minäkin osaltani, minäkin ilmoitan, mitä tiedän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Sillä minä olen sanoja täynnä, henki rinnassani ahdistaa minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Katso, minun rintani on kuin viini, jolle ei reikää avata, se on pakahtumaisillaan niinkuin nuorella viinillä täytetyt leilit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Tahdon puhua, saadakseni helpotusta, avata huuleni ja vastata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'En pidä kenenkään puolta enkä ketään ihmistä imartele.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Sillä en osaa imarrella; silloin Luojani ottaisi minut kohta pois.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, '\"Mutta kuule nyt, Job, minun puhettani, ja ota korviisi kaikki minun sanani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Katso, minä olen avannut suuni, kieleni puhuu suulakeni alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Vilpittömästä sydämestä lähtevät sanani; mitä tietävät, sen huuleni suoraan sanovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Jumalan henki on minut luonut, ja Kaikkivaltiaan henkäys elävöittää minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Vastaa minulle, jos taidat; varustaudu minua vastaan, nouse taisteluun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Katso, Jumalan edessä minä olen samanlainen kuin sinä: hyppysellinen savea olen minäkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Katso, ei käy minusta kauhu, joka sinut peljästyttää, eikä minun painoni ole raskaana ylläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Mutta sinä olet sanonut korvieni kuullen, minä olen kuullut sinun sanojesi äänen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, '\'Puhdas minä olen, rikoksesta vapaa; olen viaton, eikä minussa ole vääryyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Katso, hän keksii vihan syitä minua vastaan, hän pitää minua vihollisenansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'hän panee minun jalkani jalkapuuhun, vartioitsee kaikkia minun polkujani.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Katso, sinä et ole oikeassa-niin minä vastaan sinulle-sillä Jumala on suurempi kuin ihminen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Miksi olet riidellyt häntä vastaan, jos hän ei vastaa kaikkiin ihmisen sanoihin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Sillä Jumala puhuu tavalla ja puhuu toisella; sitä vain ei huomata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'Unessa, öisessä näyssä, kun raskas uni valtaa ihmiset ja he nukkuvat vuoteillansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'silloin hän avaa ihmisten korvat ja sinetillä vahvistaa heidän saamansa kurituksen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'kääntääkseen ihmisen pois pahasta teosta ja varjellakseen miestä ylpeydestä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'säästääkseen hänen sielunsa haudasta ja hänen henkensä syöksymästä peitsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Myös kuritetaan häntä tuskalla vuoteessansa, kun hänen luissaan on lakkaamaton kapina,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'ja hänen henkensä inhoaa leipää ja hänen sielunsa herkkuruokaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Hänen lihansa kuihtuu näkymättömiin, ja hänen luunsa, ennen näkymättömät, paljastuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'Näin lähenee hänen sielunsa hautaa ja hänen henkensä kuolonvaltoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Jos silloin on hänen puolellansa enkeli, välittäjä, yksi tuhansista, todistamassa ihmisen puolesta hänen vilpittömyyttään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'niin Jumala armahtaa häntä ja sanoo: \'Vapauta hänet, ettei hän mene hautaan; minä olen saanut lunastusmaksun\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Silloin hänen ruumiinsa taas uhkuu nuoruuden voimaa, hän palajaa takaisin nuoruutensa päiviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Hän rukoilee Jumalaa, ja Jumala mielistyy häneen ja antaa hänen riemuiten katsella hänen kasvojaan; niin hän palauttaa ihmiselle hänen vanhurskautensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Hänpä nyt laulaa muille ihmisille ja sanoo: \'Minä olin tehnyt syntiä ja vääristänyt oikean, mutta ei sitä kostettu minulle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'hän pelasti minun sieluni joutumasta hautaan, ja minun henkeni saa iloiten katsella valkeutta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Katso, kaiken tämän tekee Jumala kahdesti ja kolmastikin ihmiselle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'palauttaakseen hänen sielunsa haudasta ja antaakseen elämän valkeuden hänelle loistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Tarkkaa, Job, kuule minua; vaikene ja anna minun puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Mutta jos sinulla on, mitä sanoa, niin vastaa minulle; puhu, sillä mielelläni soisin sinun olevan oikeassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Ellei, niin kuule minua; vaikene, niin minä opetan sinulle viisautta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Ja Elihu lausui ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, '\"Kuulkaa, te viisaat, minun sanojani, ja kuunnelkaa minua, te tietomiehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Sillä korva koettelee sanat, ja suulaki maistaa ruuan maun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Tutkikaamme, mikä oikein on, koettakaamme yhdessä ymmärtää, mikä hyvä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Sillä Job on sanonut: \'Olen oikeassa, mutta Jumala on ottanut minulta oikeuteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Vaikka minun puolellani on oikeus, pitäisi minun valhetella; kuolettava nuoli on minuun sattunut, vaikka olen rikoksesta vapaa.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Kuka mies on sellainen kuin Job, joka juo jumalanpilkkaa niinkuin vettä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'joka yhtyy väärintekijäin seuraan ja vaeltaa jumalattomain miesten parissa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Sillä hän sanoo: \'Ei hyödy mies siitä, että elää Jumalalle mieliksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Sentähden kuulkaa minua, te ymmärtäväiset miehet: Pois se! Ei Jumalassa ole jumalattomuutta eikä Kaikkivaltiaassa vääryyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Vaan hän kostaa ihmiselle hänen tekonsa ja maksaa miehelle hänen vaelluksensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Totisesti, Jumala ei tee väärin, Kaikkivaltias ei vääristä oikeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Kuka on pannut hänet vallitsemaan maata, ja kuka on perustanut koko maanpiirin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Jos hän ajattelisi vain itseänsä ja palauttaisi luokseen henkensä ja henkäyksensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'niin kaikki liha yhdessä menehtyisi, ja ihminen tulisi tomuksi jälleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Jos sinulla on ymmärrystä, niin kuule tätä, ota korviisi sanojeni ääni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Taitaisiko todella se hallita, joka vihaa oikeutta? Vai tuomitsetko sinä syylliseksi tuon Vanhurskaan, Voimallisen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'joka sanoo kuninkaalle: \'Sinä kelvoton\', ruhtinaille: \'Sinä jumalaton\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'joka ei pidä päämiesten puolta eikä aseta rikasta vaivaisen edelle, koska he kaikki ovat hänen kättensä tekoa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Tuossa tuokiossa he kuolevat, keskellä yötä; kansat järkkyvät ja häviävät, väkevä siirretään pois käden koskematta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Sillä hänen silmänsä valvovat ihmisen teitä, ja hän näkee kaikki hänen askeleensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Ei ole pimeyttä, ei pilkkopimeää, johon voisivat piiloutua väärintekijät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Sillä ei tarvitse Jumalan kauan ihmistä tarkata, ennenkuin tämän on astuttava tuomiolle hänen eteensä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'hän musertaa voimalliset tutkimatta ja asettaa toiset heidän sijallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Niinpä hän tuntee heidän tekonsa ja kukistaa heidät yöllä, ja he musertuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Niinkuin jumalattomia hän kurittaa heitä julkisella paikalla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'koska he luopuivat hänestä eivätkä ensinkään huolineet hänen teistään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'vaan saattoivat vaivaisten huudon kohoamaan hänen eteensä, ja hän kuuli kurjain huudon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Ja jos hän on hiljaa, kuka häntä siitä tuomitsee? Jos hän peittää kasvonsa, kuka voi häntä katsella? Niin kansaa kuin kutakin ihmistä hän valvoo,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'ettei pääse hallitsemaan jumalaton ihminen, ei kukaan niistä, jotka ovat kansalle paulana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Sillä onko tässä sanottu Jumalalle: \'Kyllä minä kärsin, en enää pahoin tee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Mitä en näe, neuvo minulle; jos olen tehnyt vääryyttä, en sitä enää tee.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Sinunko mielesi mukaan tulisi hänen kostaa, koska olet niin tyytymätön? Niin, sinun on tehtävä valinta eikä minun; puhu, mitä tiedät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Ymmärtäväiset miehet sanovat minulle, viisas mies, joka minua kuulee, virkkaa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, '\'Job puhuu taitamattomasti, ja hänen sanansa ovat ymmärrystä vailla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Jospa Jobia koeteltaisiin ainiaan, koska hän vastaa väärintekijäin tavalla!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Sillä hän lisää syntiä syntiin, lyö kämmentä keskellämme ja syytää sanoja Jumalaa vastaan.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Elihu lausui ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, '\"Pidätkö sitä oikeutena, sanotko sitä vanhurskaudeksi Jumalan edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'että kysyt, mitä se sinua hyödyttää: \'Hyödynkö siitä sen enempää, kuin jos syntiä teen?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Siihen minä vastaan sinulle sekä ystävillesi, jotka luonasi ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Luo silmäsi taivaalle ja näe, katsele pilviä, jotka ovat korkealla pääsi päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Jos sinä syntiä teet, mitä sillä hänelle teet; ja vaikka sinulla paljonkin rikoksia olisi, mitä sillä hänelle mahdat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Jos olet vanhurskas, mitä sillä hänelle annat, tahi ottaako hän mitään sinun kädestäsi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Ihmistä, kaltaistasi, koskee jumalattomuutesi ja ihmislasta sinun vanhurskautesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Sorron suuruutta valitetaan, huudetaan apua suurten käsivartta vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'ei kysytä: \'Missä on Jumala, minun Luojani, joka yöllä saa viriämään ylistysvirret,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'joka opettaa meille enemmän kuin metsän eläimille ja antaa meille viisautta enemmän kuin taivaan linnuille?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Valittakoot sitten pahojen ylpeyttä; ei hän vastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Ei, turhia ei Jumala kuule, eikä Kaikkivaltias niihin katso,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'saati jos sanot, ettet voi häntä nähdä; asia on hänen edessänsä: odota häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Mutta nyt, kun hänen vihansa ei kosta eikä hän ylvästelystä suuresti välitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'niin Job avaa suunsa joutaviin ja syytää suuria sanoja taitamattomasti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Elihu jatkoi puhettaan ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, '\"Maltahan vähän, niin julistan sinulle, sillä vielä on minulla Jumalan puolesta puhuttavaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Minä noudan tietoni kaukaa ja osoitan Luojani oikeuden;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'sillä totisesti, sanani eivät ole valhetta-mies, jolla on täydellinen tieto, on edessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Katso, Jumala on voimallinen, mutta ei halveksu ketään; väkevä on hänen ymmärryksensä voima.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Hän ei pidä jumalatonta elossa, vaan hankkii kurjille oikeuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Hän ei käännä silmiänsä pois hurskaista, vaan antaa heidän istua kuningasten kanssa valtaistuimella ikuisesti; he kohoavat korkealle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'Ja jos niinkin käy, että heidät kytketään kahleisiin, sidotaan kurjuuden köysillä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'niin hän sillä ilmaisee heille, mitä he ovat tehneet ja mitä rikkoneet pöyhkeilemisellään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'avaa heidän korvansa nuhtelulle ja käskee heitä kääntymään pois vääryydestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Jos he kuulevat ja alistuvat, niin saavat viettää päivänsä onnessa ja ikävuotensa ihanasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Mutta jos eivät kuule, niin he syöksyvät surman peitsiin ja menehtyvät ymmärtämättömyyteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Mutta jumalattomat pitävät vihaa, he eivät apua huuda, kun hän on heidät vanginnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Heidän sielunsa kuolee nuoruudessa, heidän elämänsä loppuu niinkuin haureellisten pyhäkköpoikain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Kurjan hän vapahtaa hänen kurjuutensa kautta ja avaa hänen korvansa ahdistuksella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Sinutkin houkutteli ahdingosta pois avara tila, jossa ei ahtautta ollut, ja lihavuudesta notkuvan ruokapöydän rauha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Ja niin kohtasi sinua kukkuramäärin jumalattoman tuomio; tuomio ja oikeus on käynyt sinuun kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Älköön kärsimyksen polte houkutelko sinua pilkkaamaan, älköönkä lunastusmaksun suuruus viekö sinua harhaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Voiko huutosi auttaa ahdingosta tahi kaikki voimasi ponnistukset?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Älä halaja yötä, joka siirtää kansat sijoiltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Varo, ettet käänny vääryyteen, sillä se on sinulle mieluisampi kuin kärsimys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Katso, Jumala on korkea, valliten voimassansa; kuka on hänen kaltaisensa opettaja?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Kuka määrää hänen tiensä, ja kuka sanoo: \'Sinä teit väärin\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Muista sinäkin ylistää hänen töitänsä, joiden kiitosta ihmiset veisaavat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'kaikki ihmiset ihailevat niitä, kuolevaiset katselevat niitä kaukaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Katso, Jumala on suuri, emme häntä käsitä, hänen vuottensa luku on ilman määrää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Hän kokoaa vedenpisarat; ne vihmovat virtanaan sadetta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'jota pilvet vuodattavat, valuttavat ihmisjoukkojen päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'Kuka ymmärtää pilvien leviämiset, kuka hänen majansa jyrinän?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Katso, hän levittää niiden päälle leimauksensa ja peittää meren pohjat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Sillä niin hän tuomitsee kansat, niin hän antaa runsaan ravinnon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Hän peittää molemmat kätensä leimauksilla ja lähettää ne ahdistajan kimppuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Hänet ilmoittaa hänen jylinänsä, jopa karjakin hänen tulonsa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, '\"Niin, siitä vapisee sydämeni ja hypähtää paikoiltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Kuulkaa, kuulkaa hänen äänensä pauhinaa ja kohinaa, joka käy hänen suustansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Hän laskee sen kaikumaan kaiken taivaan alla, lähettää leimauksensa maan ääriin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Sen kintereillä ärjyy ääni, hän korottaa väkevän äänensä jylinän, eikä hän säästä salamoitaan, äänensä raikuessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Ihmeellisesti Jumala korottaa äänensä jylinän, hän tekee suuria tekoja, joita emme käsittää taida.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Sillä hän sanoo lumelle: \'Putoa maahan\', samoin sadekuurolle, rankkasateittensa ryöpylle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Niin hän kytkee jokaiselta kädet, että kaikki ihmiset hänen tekonsa tietäisivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Pedot vetäytyvät piiloon ja pysyvät luolissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Tähtitarhasta tulee tuulispää, pohjan ilmalta pakkanen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Jumalan henkäyksestä syntyy jää, ja aavat vedet ahdistuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Hän myös kuormittaa pilvet kosteudella ja hajottaa välähtelevät ukkosvaarunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Ne vyöryvät sinne tänne hänen ohjauksestaan, tehdäkseen maanpiirin päällä kaiken, mitä hän niille määrää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Hän antaa niiden osua milloin maalle vitsaukseksi, milloin siunaukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Ota tämä korviisi, Job; pysähdy ja tarkkaa Jumalan ihmetöitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Tiedätkö, kuinka Jumala niillä tekonsa teettää ja kuinka hän antaa pilviensä leimausten loistaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Käsitätkö pilvien punnituksen, hänen ihmeensä, joka on kaikkitietävä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Sinä, jonka vaatteet kuumenevat, kun maa on raukeana etelän helletuulesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'kaarrutatko sinä hänen kanssansa taivaan, joka on vahva kuin valettu kuvastin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Neuvo, mitä meidän on hänelle sanottava; pimeydessämme emme voi tuoda esiin mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Olisiko hänelle ilmoitettava, että tahtoisin puhua? Kukapa vaatisi omaa tuhoansa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Ja nyt: ei voida katsella valoa, joka kirkkaana loistaa, kun tuuli on puhaltanut puhdistaen taivaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Pohjoisesta tulee kultainen hohde; Jumalan yllä on peljättävä valtasuuruus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Kaikkivaltiasta emme saata käsittää, häntä, joka on suuri voimassa, joka ei oikeutta ja täydellistä vanhurskautta polje.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Sentähden peljätkööt häntä ihmiset; hän ei katso keneenkään, joka on omasta mielestään viisas.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Silloin Herra vastasi Jobille tuulispäästä ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, '\"Kuka olet sinä, joka taitamattomilla puheilla pimennät minun aivoitukseni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Vyötä nyt kupeesi kuin mies; minä kysyn sinulta, opeta sinä minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Missä olit silloin, kun minä maan perustin? Ilmoita se, jos ymmärryksesi riittää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Kuka on määrännyt sen mitat-tottapa sen tiedät-tahi kuka on vetänyt mittanuoran sen ylitse?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Mihin upotettiin sen perustukset, tahi kuka laski sen kulmakiven,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'kun aamutähdet kaikki iloitsivat ja kaikki Jumalan pojat riemuitsivat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Ja kuka sulki ovilla meren, kun se puhkesi ja kohdusta lähti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'kun minä panin sille pilven vaatteeksi ja synkeyden kapaloksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'kun minä rakensin sille rajani, asetin sille teljet ja ovet');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'ja sanoin: \'Tähän asti saat tulla, mutta edemmäksi et; tässä täytyy sinun ylväiden aaltojesi asettua\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Oletko eläissäsi käskenyt päivän koittaa tahi osoittanut aamuruskolle paikkansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'että se tarttuisi maan liepeisiin ja pudistaisi jumalattomat siitä pois?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Silloin se muuttuu niinkuin savi sinetin alla, ja kaikki tulee kuin vaatetettuna esille;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'jumalattomilta riistetään heidän valonsa, ja kohonnut käsivarsi murskataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Oletko astunut alas meren lähdesuonille asti ja kulkenut syvyyden kuilut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Ovatko kuoleman portit sinulle paljastuneet, oletko nähnyt pimeyden portit?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Käsitätkö, kuinka avara maa on? Ilmoita se, jos kaiken tämän tiedät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Mikä on tie sinne, kussa asuu valo, ja missä on pimeyden asuinsija,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'että saattaisit sen alueellensa ja tuntisit polut sen majalle?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Kaiketi sen tiedät, sillä synnyithän jo silloin, ja onhan päiviesi luku ylen suuri!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Oletko käynyt lumen varastohuoneissa, ja oletko nähnyt rakeiden varastot,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'jotka minä olen säästänyt ahdingon ajaksi, sodan ja taistelun päiväksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Mitä tietä jakaantuu valo ja itätuuli leviää yli maan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Kuka on avannut kuurnan sadekuurolle ja ukkospilvelle tien,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'niin että sataa maahan, joka on asumaton, erämaahan, jossa ei ihmistä ole,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'niin että autio erämaa saa kylläksensä ja maa kasvaa vihannan ruohon?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Onko sateella isää, tahi kuka on synnyttänyt kastepisarat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Kenen kohdusta on jää tullut, ja kuka on synnyttänyt taivaan härmän?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Vesi tiivistyy kuin kiveksi, ja syvyyden pinta sulkeutuu kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Taidatko solmita Otavan siteet tahi irroittaa kahleista Kalevanmiekan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Voitko tuoda esiin eläinradan tähdet aikanansa ja johdattaa Seulaset lapsinensa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Tunnetko taivaan lait, tahi sinäkö säädät, miten se maata vallitsee?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Taidatko korottaa äänesi pilviin ja saada vesitulvan peittämään itsesi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Taidatko lähettää salamat menemään, niin että sanovat sinulle: \'Katso, tässä olemme\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Kuka on pannut viisautta pilvenlonkiin, tahi kuka antoi pilvenhattaroille ymmärrystä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Kuka on niin viisas, että laskee pilvien luvun, kuka kaataa tyhjiksi taivaan leilit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'kun multa on kuivunut kovaksi kuin valettu ja maakokkareet toisiinsa takeltuneet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, '{39:1} \"Sinäkö ajat saaliin naarasleijonalle ja tyydytät nuorten leijonain nälän,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, '{39:2} kun ne kyyristyvät luolissansa ja ovat väijyksissä tiheikössä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, '{39:3} Kuka hankkii ravinnon kaarneelle, kun sen poikaset huutavat Jumalan puoleen ja lentelevät sinne tänne ruokaa vailla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, '{39:4} Tiedätkö sinä vuorikauristen poikimisajat, valvotko peurojen synnytyskipuja?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, '{39:5} Lasketko, milloin niiden kuukaudet täyttyvät, ja tiedätkö ajan, milloin ne poikivat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, '{39:6} Ne painautuvat maahan, saavat ilmoille sikiönsä ja vapautuvat synnytystuskistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, '{39:7} Niiden vasikat vahvistuvat, kasvavat kedolla; ne lähtevät tiehensä eivätkä enää palaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, '{39:8} Kuka on laskenut villiaasin vapaaksi, kuka irroittanut metsäaasin siteet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, '{39:9} sen, jolle minä annoin aavikon asunnoksi ja suola-aron asuinsijaksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, '{39:10} Se nauraa kaupungin kohinalle, ajajan huutoa se ei kuule;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, '{39:11} se tähystelee vuorilta laiduntansa ja etsii kaikkea vihantaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, '{39:12} Taipuuko villihärkä sinua palvelemaan, ja yöpyykö se sinun seimesi ääreen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, '{39:13} Voitko ohjaksilla pakottaa villihärän vaolle, tahi äestääkö se laaksonpohjia sinua seuraten?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, '{39:14} Voitko siihen luottaa, siksi että sen voima on suuri, voitko jättää sen haltuun työsi hedelmät?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, '{39:15} Voitko uskoa, että se palajaa ja kokoaa viljasi sinun puimatantereellesi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, '{39:16} Kamelikurjen siipi lepattaa iloisesti, mutta asuuko sen sulissa ja höyhenissä haikaran hellyys?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, '{39:17} Se jättää munansa maahan, hiekalle helteen haudottaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, '{39:18} Ei se ajattele, että jalka voi ne särkeä ja metsän eläimet polkea ne rikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, '{39:19} Se on tyly poikasilleen, niinkuin ne eivät olisikaan sen omia; hukkaan menee sen vaiva, mutta ei se sitä pelkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, '{39:20} Sillä Jumala on jättänyt sen viisautta vaille ja tehnyt sen ymmärryksestä osattomaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, '{39:21} Kun se kiitää ilmaa piesten, nauraa se hevoselle ja ratsumiehelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, '{39:22} Sinäkö annat hevoselle voiman, puetat sen kaulan liehuvalla harjalla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, '{39:23} Sinäkö panet sen hyppimään kuin heinäsirkan? Sen uljas korskunta on peljättävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, '{39:24} Se kuopii lakeutta ja iloitsee, lähtee voimalla asevarustuksia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, '{39:25} Se nauraa pelolle, ei säiky eikä väisty miekan edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, '{39:26} Sen yllä kalisee viini, välkähtää keihäs ja peitsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, '{39:27} Käy jyrinä ja jytinä, kun se laukaten taivalta ahmii; ei mikään sitä pidätä sotatorven pauhatessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, '{39:28} Milloin ikinä sotatorvi soi, hirnuu se: iihaha! Jo kaukaa se vainuaa taistelun, päälliköiden jylisevän äänen ja sotahuudon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, '{39:29} Sinunko ymmärryksesi voimasta jalohaukka kohoaa korkealle, levittää siipensä kohti etelää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, '{39:30} Tahi sinunko käskystäsi kotka lentää ylhäälle ja tekee pesänsä korkeuteen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, '{39:31} Kalliolla se asuu ja yöpyy, kallion kärjellä, vuorilinnassaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, '{39:32} Sieltä se tähystelee saalista; kauas katsovat sen silmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, '{39:33} Sen poikaset särpivät verta, ja missä on kaatuneita, siellä on sekin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, '{39:34} Niin Herra vastasi Jobille ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, '{39:35} \"Tahtooko vikoilija riidellä Kaikkivaltiasta vastaan? Jumalan syyttäjä vastatkoon tähän!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, '{39:36} Silloin Job vastasi Herralle ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, '{39:37} \"Katso, minä olen siihen liian halpa; mitäpä sinulle vastaisin? Panen käteni suulleni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, '{39:38} kerran minä olen puhunut, enkä enää mitään virka, kahdesti, enkä enää sitä tee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, '{40:1} Silloin Herra vastasi Jobille tuulispäästä ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, '{40:2} \"Vyötä nyt kupeesi kuin mies; minä kysyn sinulta, opeta sinä minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, '{40:3} Sinäkö teet tyhjäksi minun oikeuteni, tuomitset minut syylliseksi, ollaksesi itse oikeassa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, '{40:4} Tahi onko sinun käsivartesi niinkuin Jumalan, ja voitko korottaa äänesi jylinän niinkuin hän?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, '{40:5} Kaunistaudu kunnialla ja korkeudella, pukeudu loistoon ja kirkkauteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, '{40:6} Anna vihasi kiivastuksen purkautua, ja masenna katseellasi kaikki ylpeät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, '{40:7} Nöyryytä katseellasi kaikki ylpeät, ja muserra jumalattomat siihen paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, '{40:8} Kätke heidät tomuun kaikki tyynni, sulje heidän kasvonsa salaiseen kätköön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, '{40:9} Silloin minäkin ylistän sinua, kun oikea kätesi on hankkinut sinulle voiton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, '{40:10} Katso Behemotia, jonka minä loin niinkuin sinutkin; se syö ruohoa niinkuin raavas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, '{40:11} Katso, sen voima on lanteissa, sen väkevyys vatsalihaksissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, '{40:12} Se ojentaa jäykäksi häntänsä kuin setripuun, sen reisijänteet ovat lujiksi punotut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, '{40:13} Sen luut ovat niinkuin vaskiputket, sen nikamat niinkuin raudasta taotut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, '{40:14} Se on Jumalan töiden esikoinen; sen luoja ojentaa sille miekan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, '{40:15} Sille kantavat satonsa vuoret, joilla kaikki metsän eläimet leikitsevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, '{40:16} Lootuspensaiden alla se makaa, ruovikon ja rämeen kätkössä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, '{40:17} Lootuspensaat peittävät sen varjoonsa, puron pajut ympäröivät sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, '{40:18} Jos virta hätyyttää, ei se säikähdy, se on huoleton, kuohukoon vaikka itse Jordan sen kitaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, '{40:19} Kukapa kävisi kiinni sen silmiin, lävistäisi heittoaseella sen turvan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, '{40:20} Voitko onkia koukulla Leviatanin ja siimaan kietoa sen kielen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, '{40:21} Voitko kiinnittää kaislaköyden sen kuonoon ja väkäraudalla lävistää siltä posken?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, '{40:22} Rukoileeko se sinua paljon, tahi puhutteleeko se sinua lempeästi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, '{40:23} Tekeekö se liiton sinun kanssasi, että saisit sen olemaan orjanasi ainaisesti?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, '{40:24} Voitko leikkiä sillä niinkuin lintusella tahi sitoa sen tyttöjesi pidellä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, '{40:25} Hierovatko pyyntikunnat siitä kauppaa, jakavatko sen kauppamiesten kesken?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, '{40:26} Voitko iskeä sen nahan täyteen ahinkaita ja sen pään kala-ahraimia?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, '{40:27} Laskehan vain kätesi sen päälle, niin muistat sen ottelun; et sitä toiste yritä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, '{40:28} Katso, siinä toivo pettää; jo sen näkemisestä sortuu maahan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, '{41:1} \"Ei ole niin rohkeata, joka sitä ärsyttäisi. Kuka sitten kestäisi minun edessäni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, '{41:2} Kuka on minulle ensin antanut jotakin, joka minun olisi korvattava? Mitä kaiken taivaan alla on, se on minun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, '{41:3} En saata olla puhumatta sen jäsenistä, en sen voimasta ja sorjasta rakenteesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, '{41:4} Kuka voi riisua siltä päällysvaatteen, kuka tunkeutua sen kaksinkertaisten purimien väliin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, '{41:5} Kuka on avannut sen kasvojen kaksoisoven? Sen hammasten ympärillä on kauhu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, '{41:6} Sen ylpeytenä ovat uurteiset selkäkilvet, kiinnitetyt lujalla sinetillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, '{41:7} Ne käyvät tarkoin toinen toiseensa, niin ettei ilma välitse pääse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, '{41:8} Ne ovat toisiinsa liitetyt, pysyvät kiinni erkanematta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, '{41:9} Sen aivastus on kuin valon välähdys, sen silmät ovat kuin aamuruskon silmäripset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, '{41:10} Sen kidasta lähtee tulisoihtuja, sinkoilee säkeniä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, '{41:11} Sen sieramista käy savu niinkuin kihisevästä kattilasta ja kaislatulesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, '{41:12} Sen puhallus polttaa kuin tuliset hiilet, ja sen suusta lähtee liekki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, '{41:13} Sen kaulassa asuu voima, ja sen edellä hyppii kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, '{41:14} Sen pahkuraiset lihat ovat kiinteät, ovat kuin valetut, järkkymättömät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, '{41:15} Sen sydän on valettu kovaksi kuin kivi, kovaksi valettu kuin alempi jauhinkivi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, '{41:16} Kun se nousee, peljästyvät sankarit, kauhusta he tyrmistyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, '{41:17} Jos sen kimppuun käydään miekoin, ei miekka kestä, ei keihäs, ei heittoase eikä panssari.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, '{41:18} Sille on rauta kuin oljenkorsi, vaski kuin lahopuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, '{41:19} Ei aja sitä pakoon nuoli, jousen poika, akanoiksi muuttuvat sille linkokivet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, '{41:20} Kuin oljenkorsi on sille nuija, keihästen ryskeelle se nauraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, '{41:21} Sen vatsapuolessa on terävät piikit, se kyntää mutaa leveälti kuin puimaäes.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, '{41:22} Se panee syvyyden kiehumaan kuin padan, tekee meren voidekattilan kaltaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, '{41:23} Sen jäljessä polku loistaa, syvyydellä on kuin hopeahapset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, '{41:24} Ei ole maan päällä sen vertaista; se on luotu pelottomaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, '{41:25} Se katsoo ylen kaikkea, mikä korkeata on; se on kaikkien ylväitten eläinten kuningas.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Silloin Job vastasi Herralle ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, '\"Minä tiedän, että sinä voit kaikki ja ettei mikään päätöksesi ole sinulle mahdoton toteuttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, '\'Kuka peittää minun aivoitukseni taitamattomasti?\' Siis on niin: minä puhuin ymmärtämättömästi, asioista, jotka ovat ylen ihmeelliset minun käsittää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Kuule siis, niin minä puhun; minä kysyn, opeta sinä minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Korvakuulolta vain olin sinusta kuullut, mutta nyt on silmäni sinut nähnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Sentähden minä peruutan puheeni ja kadun tomussa ja tuhassa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'Mutta senjälkeen kuin Herra oli puhunut Jobille nämä sanat, sanoi Herra teemanilaiselle Elifaalle: \"Minun vihani on syttynyt sinua ja sinun kahta ystävääsi kohtaan, koska ette ole puhuneet minusta oikein niinkuin minun palvelijani Job.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Ottakaa siis seitsemän mullikkaa ja seitsemän oinasta, käykää minun palvelijani Jobin luo ja uhratkaa puolestanne polttouhri, ja minun palvelijani Job rukoilkoon teidän puolestanne. Tehdäkseni hänelle mieliksi en saata teitä häpeälliseen rangaistukseen siitä, ettette puhuneet minusta oikein niinkuin minun palvelijani Job.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Niin teemanilainen Elifas, suuhilainen Bildad ja naemalainen Soofar menivät ja tekivät, niinkuin Herra oli heille puhunut; ja Herra teki Jobille mieliksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Ja kun Job rukoili ystäväinsä puolesta, käänsi Herra Jobin kohtalon, ja Herra antoi Jobille kaikkea kaksin verroin enemmän, kuin hänellä ennen oli ollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Ja kaikki hänen veljensä ja sisarensa ja kaikki hänen entiset tuttavansa tulivat hänen tykönsä ja aterioitsivat hänen kanssaan hänen talossansa, ja he surkuttelivat ja lohduttivat häntä kaikesta siitä onnettomuudesta, jonka Herra oli antanut kohdata häntä. Ja he antoivat kukin hänelle yhden kesitan ja yhden kultarenkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'Ja Herra siunasi Jobin elämän loppupuolta vielä enemmän kuin sen alkua, niin että hän sai neljätoista tuhatta lammasta, kuusi tuhatta kamelia, tuhat härkäparia ja tuhat aasintammaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Ja hän sai seitsemän poikaa ja kolme tytärtä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'Ensimmäiselle hän antoi nimen Jemima, toiselle nimen Kesia ja kolmannelle nimen Keren-Happuk.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'Eikä ollut koko maassa niin kauniita naisia kuin Jobin tyttäret; ja heidän isänsä antoi heille perintöosan heidän veljiensä rinnalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Tämän jälkeen Job eli vielä sataneljäkymmentä vuotta ja sai nähdä lapsensa ja lastensa lapset neljänteen polveen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'Sitten Job kuoli vanhana ja elämästä kyllänsä saaneena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Autuas se mies, joka ei vaella jumalattomain neuvossa eikä astu syntisten teitä eikä istu, kussa pilkkaajat istuvat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'vaan rakastaa Herran lakia ja tutkistelee hänen lakiansa päivät ja yöt!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Hän on niinkuin istutettu puu vesiojain tykönä, joka antaa hedelmänsä ajallaan ja jonka lehti ei lakastu; ja kaikki, mitä hän tekee, menestyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Niin eivät jumalattomat! Vaan he ovat kuin akanat, joita tuuli ajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Sentähden eivät jumalattomat kestä tuomiolla eivätkä syntiset vanhurskasten seurakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Sillä Herra tuntee vanhurskasten tien, mutta jumalattomain tie hukkuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Miksi pakanat pauhaavat ja kansat turhia ajattelevat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Maan kuninkaat nousevat, ruhtinaat yhdessä neuvottelevat Herraa ja hänen voideltuansa vastaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '\"Katkaiskaamme heidän kahleensa, heittäkäämme päältämme heidän köytensä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Hän, joka taivaassa asuu, nauraa; Herra pilkkaa heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Kerran hän on puhuva heille vihassansa, peljättävä heitä hirmuisuudessaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '\"Minä olen asettanut kuninkaani Siioniin, pyhälle vuorelleni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Minä ilmoitan, mitä Herra on säätänyt. Hän lausui minulle: \"Sinä olet minun poikani, tänä päivänä minä sinut synnytin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Ano minulta, niin minä annan pakanakansat sinun perinnöksesi ja maan ääret sinun omiksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Rautaisella valtikalla sinä heidät muserrat, niinkuin saviastian sinä särjet heidät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Tulkaa siis järkiinne, kuninkaat, maan tuomarit, ottakaa nuhteesta vaari.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Palvelkaa Herraa pelvolla ja iloitkaa vavistuksella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Antakaa suuta pojalle, ettei hän vihastuisi ettekä te hukkuisi tiellänne. Sillä hänen vihansa syttyy äkisti. Autuaat ovat kaikki, jotka häneen turvaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Daavidin virsi, hänen paetessaan poikaansa Absalomia. {3:2} Herra, kuinka paljon minulla on vihollisia, paljon niitä, jotka nousevat minua vastaan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, '{3:3} Monet sanovat minusta: \"Ei ole hänellä pelastusta Jumalassa\". Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, '{3:4} Mutta sinä, Herra, olet minun kilpeni, sinä olet minun kunniani, sinä kohotat minun pääni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, '{3:5} Ääneeni minä huudan Herraa, ja hän vastaa minulle pyhältä vuoreltansa. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, '{3:6} Minä käyn levolle ja nukun; minä herään, sillä Herra minua tukee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, '{3:7} En pelkää kymmentuhantista joukkoa, joka asettuu yltympäri minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, '{3:8} Nouse, Herra, pelasta minut, minun Jumalani! Sillä sinä lyöt poskelle kaikkia minun vihollisiani, sinä murskaat jumalattomain hampaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, '{3:9} Herrassa on pelastus; sinun siunauksesi tulkoon sinun kansallesi. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Veisuunjohtajalle; kielisoittimilla; Daavidin virsi. {4:2} Vastaa minulle, kun minä huudan, sinä minun vanhurskauteni Jumala, joka ahdingossa avarrat minun tilani. Armahda minua, kuule minun rukoukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, '{4:3} Te miehet, kuinka kauan minun kunniaani pidetään pilkkana, kuinka kauan te rakastatte turhuutta, etsitte valhetta? Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, '{4:4} Tietäkää: ihmeellinen on Herra hurskastansa kohtaan, Herra kuulee, kun minä häntä huudan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, '{4:5} Vaviskaa, älkääkä syntiä tehkö. Puhukaa sydämissänne vuoteillanne ja olkaa hiljaa. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, '{4:6} Uhratkaa vanhurskauden uhreja ja luottakaa Herraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, '{4:7} Moni sanoo: \"Kuka antaa meille sitä, mikä hyvä on?\" Herra, käännä sinä meihin kasvojesi valkeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, '{4:8} Sinä annat minun sydämeeni suuremman ilon, kuin heillä on runsaasta viljasta ja viinistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, '{4:9} Rauhassa minä käyn levolle ja nukun, sillä sinä, Herra, yksin annat minun turvassa asua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Veisuunjohtajalle; huilusoittimilla; Daavidin virsi. {5:2} Ota korviisi minun sanani, Herra, huomaa huokaukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, '{5:3} Kuuntele huutoni ääntä, minun kuninkaani ja Jumalani, sillä sinua minä rukoilen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, '{5:4} Herra, varhain sinä kuulet minun ääneni, varhain minä valmistan sinulle uhrin ja odotan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, '{5:5} Sillä sinä et ole se Jumala, jolle jumalattomuus kelpaa. Paha ei saa asua sinun tykönäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, '{5:6} Ylvästelijät eivät kestä sinun silmiesi edessä; sinä vihaat kaikkia väärintekijöitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, '{5:7} Sinä hukutat valheen puhujat; murhamiehet ja viekkaat ovat Herralle kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, '{5:8} Mutta minä saan sinun suuresta armostasi tulla sinun huoneeseesi, saan kumartaa sinun pyhään temppeliisi päin sinun pelvossasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, '{5:9} Herra, johdata minua vanhurskaudessasi minun vihamiesteni tähden, tasoita tiesi minun eteeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, '{5:10} Sillä heidän suussaan ei ole luotettavaa sanaa, heidän sisimpänsä on turmiota täynnä, heidän kurkkunsa on avoin hauta, kielellänsä he liukkaasti liehakoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, '{5:11} Tuomitse, Jumala, heidät syyllisiksi, rauetkoon heidän hankkeensa. Kukista heidät heidän rikostensa paljouden tähden, sillä he niskoittelevat sinua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, '{5:12} Ja iloitkoot kaikki, jotka sinuun turvaavat, ja riemuitkoot iankaikkisesti. Suojele heitä, että sinussa iloitsisivat ne, jotka rakastavat sinun nimeäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, '{5:13} Sillä sinä, Herra, siunaat vanhurskasta, sinä suojaat häntä armollasi niinkuin kilvellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Veisuunjohtajalle; kielisoittimilla; matalassa äänialassa; Daavidin virsi. {6:2} Herra, älä rankaise minua vihassasi, älä kiivastuksessasi minua kurita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, '{6:3} Herra, armahda minua, sillä minä olen näännyksissä; paranna minut, Herra, sillä minun luuni ovat peljästyneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, '{6:4} ja minun sieluni on kovin peljästynyt. Voi, Herra, kuinka kauan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, '{6:5} Käänny, Herra, vapahda minun sieluni, pelasta minut armosi tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, '{6:6} Sillä kuolemassa ei sinua muisteta; kuka ylistää sinua tuonelassa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, '{6:7} Minä olen uupunut huokaamisesta; joka yö minä itken vuoteeni vesille ja kastelen leposijani kyyneleilläni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, '{6:8} Minun silmäni ovat huienneet surusta, vanhenneet kaikkien vastustajaini tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, '{6:9} Väistykää minusta, kaikki väärintekijät, sillä Herra kuulee minun itkuni äänen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, '{6:10} Herra kuulee minun anomiseni, Herra ottaa minun rukoukseni vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, '{6:11} Kaikki minun viholliseni joutuvat häpeään ja suuren pelon valtaan; äkisti he joutuvat häpeään, kääntyvät pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Daavidin virsi, jonka hän veisasi Herralle benjaminilaisen Kuusin sanojen johdosta. {7:2} Herra, minun Jumalani, sinuun minä turvaan; pelasta minut kaikista vainoojistani ja vapahda minut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, '{7:3} etteivät he raatelisi minua niinkuin leijona ja tempaisi pois-eikä pelastajaa olisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, '{7:4} Herra, minun Jumalani, jos minä näin olen tehnyt, jos vääryys minun käsiäni tahraa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, '{7:5} jos olen tehnyt pahaa niille, jotka elivät rauhassa minun kanssani, tai jos olen ryöstänyt niiltä, jotka syyttä minua ahdistivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, '{7:6} niin vainotkoon vihollinen minun henkeäni, saakoon minut kiinni ja polkekoon maahan minun elämäni ja painakoon minun kunniani tomuun. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, '{7:7} Nouse, Herra, vihassasi. Kohoa minun vastustajaini raivoa vastaan ja heräjä avukseni sinä, joka sääsit tuomion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, '{7:8} Ympäröikööt sinua kansojen joukot, ja palaja heidän ylitsensä korkeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, '{7:9} Herra tuomitsee kansat; auta minut oikeuteeni, Herra, minun vanhurskauteni ja viattomuuteni mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, '{7:10} Loppukoon jumalattomain pahuus, ja vahvista vanhurskaita. Sillä sinä, joka tutkit sydämet ja munaskuut, olet vanhurskas Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, '{7:11} Minun kilpenäni on Jumala; hän on oikeamielisten pelastaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, '{7:12} Jumala on vanhurskas tuomari ja Jumala, joka vihastuu joka päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, '{7:13} Jos kääntymystä ei tule, niin hän teroittaa miekkansa, jännittää jousensa ja tähtää sillä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, '{7:14} hän valmistaa surma-aseet ja tekee nuolensa palaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, '{7:15} Katso, tuo hautoo turmiota, kantaa tuhoa kohdussaan, mutta hän synnyttää pettymyksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, '{7:16} Hän kaivoi haudan ja koversi sen, mutta itse hän kaatuu tekemäänsä kuoppaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, '{7:17} Hänen turmionhankkeensa kääntyy hänen omaan päähänsä, ja hänen vääryytensä lankeaa hänen päälaelleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, '{7:18} Minä kiitän Herraa hänen vanhurskaudestansa ja veisaan Herran, Korkeimman, nimen kiitosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Veisuunjohtajalle; veisataan kuin viininkorjuulaulu; Daavidin virsi. {8:2} Herra, meidän Herramme, kuinka korkea onkaan sinun nimesi kaikessa maassa, sinun, joka olet asettanut valtasuuruutesi taivaitten ylitse!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, '{8:3} Lasten ja imeväisten suusta sinä perustit voiman vastustajaisi tähden, että kukistaisit vihollisen ja kostonhimoisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, '{8:4} Kun minä katselen sinun taivastasi, sinun sormiesi tekoa, kuuta ja tähtiä, jotka sinä olet luonut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, '{8:5} niin mikä on ihminen, että sinä häntä muistat, tai ihmislapsi, että pidät hänestä huolen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, '{8:6} Ja kuitenkin sinä teit hänestä lähes jumal\'olennon, sinä seppelöitsit hänet kunnialla ja kirkkaudella;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, '{8:7} panit hänet hallitsemaan kättesi tekoja, asetit kaikki hänen jalkainsa alle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, '{8:8} lampaat ja karjan, ne kaikki, niin myös metsän eläimet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, '{8:9} taivaan linnut ja meren kalat ja kaiken, mikä meren polkuja kulkee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, '{8:10} Herra, meidän Herramme, kuinka korkea onkaan sinun nimesi kaikessa maassa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Veisuunjohtajalle; veisataan kuin: \"Kuole pojan puolesta\"; Daavidin virsi. {9:2} Minä ylistän Herraa kaikesta sydämestäni, ilmoitan kaikki sinun ihmetyösi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, '{9:3} Minä iloitsen ja riemuitsen sinussa, veisaan sinun nimesi kiitosta, sinä Korkein.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, '{9:4} Sillä minun viholliseni peräytyivät, kaatuivat maahan ja hukkuivat sinun kasvojesi edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, '{9:5} Sinä hankit minulle oikeuden ja ajoit minun asiani, sinä istuit valtaistuimelle, sinä vanhurskas tuomari.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, '{9:6} Sinä nuhtelit pakanoita, tuhosit jumalattomat; sinä pyyhit pois heidän nimensä iäksi ja ainiaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, '{9:7} Viholliset ovat tuhotut, ikuisiksi raunioiksi tulleet; kaupungit sinä kukistit, heidän muistonsa on kadonnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, '{9:8} Mutta Herra hallitsee iankaikkisesti; hän on pystyttänyt istuimensa tuomitaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, '{9:9} Hän tuomitsee maanpiirin vanhurskaasti, vallitsee kansoja oikeuden mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, '{9:10} Niin Herra on sorretun linna, linna ahdingon aikoina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, '{9:11} Ja sinuun turvaavat ne, jotka sinun nimesi tuntevat; sillä sinä et hylkää niitä, jotka sinua etsivät, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, '{9:12} Veisatkaa kiitosta Herralle, joka Siionissa asuu, julistakaa kansojen keskuudessa hänen suuria tekojaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, '{9:13} Sillä hän, verenkostaja, muistaa heitä eikä unhota kurjain huutoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, '{9:14} Armahda minua, Herra, katso, kuinka minun vihamieheni minua vaivaavat, sinä, joka nostat minut kuoleman porteista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, '{9:15} että minä julistaisin kaikki sinun ylistettävät tekosi, tytär Siionin porteissa, riemuitsisin sinun avustasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, '{9:16} Pakanat ovat vajonneet kaivamaansa hautaan; heidän jalkansa takertui verkkoon, jonka he virittivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, '{9:17} Herra on tehnyt itsensä tunnetuksi, on pitänyt tuomiot, kietonut jumalattoman hänen kättensä tekoihin. -Kanteleen välisoitto. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, '{9:18} Jumalattomat peräytyvät tuonelaan, kaikki pakanat, jotka unhottavat Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, '{9:19} Sillä ei köyhää unhoteta iäksi, eikä kurjien toivo huku ainiaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, '{9:20} Nouse, Herra, älä salli ihmisten uhitella. Tuomittakoon pakanat sinun kasvojesi edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, '{9:21} Saata, Herra, heidät pelkoon. Tietäkööt pakanat olevansa vain ihmisiä. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Miksi, Herra, seisot niin kaukana, miksi kätkeydyt ahdingon aikoina?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Jumalattomien ylpeyden tähden kurja kärsii, takertuu heidän punomiinsa juoniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Sillä jumalaton kerskaa omista himoistansa, ja kiskuri kiroaa, pilkkaa Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Jumalaton sanoo ylvästellen: \"Ei hän kosta\". \"Ei Jumalaa ole\" -siinä kaikki hänen ajatuksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Hänen hankkeensa menestyvät joka aika. Sinun tuomiosi ovat korkealla, kaukana hänestä; kaikille vastustajilleen hän hymähtää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Hän sanoo sydämessään: \"En horju minä, en ikinä joudu onnettomuuteen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Hänen suunsa on täynnä kirousta, petosta, sortoa; tuho ja turmio on hänen kielensä alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Kylien vaiheilla hän istuu väijyksissä, hän murhaa salaa syyttömän. Hänen silmänsä vaanivat onnetonta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Kätkössään hän väijyy, niinkuin leijona pensaikossa, hän väijyy hyökätäksensä kurjan kimppuun; hän saa kurjan kiinni, vetää hänet verkkoonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Hän kyyristyy, painautuu maahan, ja onnettomat joutuvat hänen kynsiinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Hän sanoo sydämessään: \"Jumala sen unhottaa, hän on peittänyt kasvonsa, hän ei sitä ikinä näe\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Nouse, Herra, kohota kätesi, Jumala! Älä unhota kurjia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Miksi jumalaton pilkkaa Jumalaa? Miksi hän sanoo sydämessään: \"Et sinä kosta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Sinä olet sen nähnyt, sillä sinä havaitset vaivan ja tuskan, ja sinä otat sen oman kätesi huomaan; sinulle onneton uskoo asiansa, sinä olet orpojen auttaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Murskaa jumalattoman käsivarsi ja kosta pahan jumalattomuus, niin ettei häntä enää löydetä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Herra on kuningas ainiaan ja iankaikkisesti; hävinneet ovat pakanat hänen maastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Sinä kuulet nöyrien halajamisen, Herra, sinä vahvistat heidän sydämensä, sinä teroitat korvasi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'auttaaksesi orvon ja sorretun oikeuteensa, ettei ihminen, joka maasta on, enää saisi kauhua aikaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Veisuunjohtajalle; Daavidin virsi. Herraan minä turvaan; kuinka te sanotte minulle: \"Paetkaa vuorellenne niinkuin linnut!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Sillä katso, jumalattomat jännittävät jousensa, ovat panneet nuolensa jänteelle oikeamielisiä pimeässä ampuaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Kun peruspylväät murretaan maahan, mitä voi vanhurskas tehdä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Herra pyhässä temppelissänsä, Herra, jonka istuin on taivaassa-hänen silmänsä näkevät, hänen katseensa tutkii ihmislapset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Herra tutkii vanhurskaat, mutta jumalattomia ja niitä, jotka vääryyttä rakastavat, hänen sielunsa vihaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Hän antaa sataa jumalattomien päälle pauloja, tulta ja tulikiveä; polttava tuuli on heidän maljansa osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Sillä Herra on vanhurskas ja rakastaa vanhurskautta; oikeamieliset saavat katsella hänen kasvojansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Veisuunjohtajalle; matalassa äänialassa; Daavidin virsi. {12:2} Auta, Herra, sillä hurskaat ovat hävinneet, uskolliset ovat kadonneet ihmislasten joukosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, '{12:3} He puhuvat valhetta toinen toisellensa, puhuvat liukkain huulin, kaksimielisin sydämin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, '{12:4} Hävittäköön Herra kaikki liukkaat huulet, kielen, joka kerskuen puhuu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, '{12:5} ne, jotka sanovat: \"Kielemme voimalla me olemme väkevät; huulemme ovat meidän tukemme; kuka on meille herra?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, '{12:6} \"Kurjien sorron tähden, köyhien huokausten tähden minä nyt nousen\", sanoo Herra, \"tuon pelastuksen sille, joka sitä huoaten ikävöitsee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, '{12:7} Herran sanat ovat selkeitä sanoja, hopeata, joka kirkkaana valuu sulattimesta maahan, seitsenkertaisesti puhdistettua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, '{12:8} Sinä, Herra, varjelet heitä, suojelet hänet iäti tältä sukukunnalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, '{12:9} Yltympäri jumalattomat rehentelevät, kun kataluus pääsee valtaan ihmislasten seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Veisuunjohtajalle; Daavidin virsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Kuinka kauan, Herra, minut yhä unhotat, kuinka kauan kätket minulta kasvosi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Kuinka kauan minun täytyy kantaa huolia sielussani, päivät päästään murhetta sydämessäni? Kuinka kauan saa vihollinen ylvästellä minua vastaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Katsahda tänne, vastaa minulle, Herra, minun Jumalani. Valaise silmäni, etten nukkuisi kuolemaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'ettei minun viholliseni sanoisi: \"Minä voitin hänet\", etteivät ahdistajani riemuitsisi, kun minä horjun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Mutta minä turvaan sinun armoosi; riemuitkoon minun sydämeni sinun avustasi. Minä veisaan Herralle, sillä hän on tehnyt minulle hyvin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Veisuunjohtajalle; Daavidin virsi. Hullu sanoo sydämessänsä: \"Ei ole Jumalaa\". Turmiollinen ja iljettävä on heidän menonsa; ei ole ketään, joka tekee, mikä hyvää on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Herra katsoo taivaasta ihmislapsiin nähdäksensä, onko ketään ymmärtäväistä, ketään, joka etsii Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Mutta kaikki ovat poikenneet pois, kaikki tyynni kelvottomiksi käyneet; ei ole ketään, joka tekee sitä, mikä hyvää on, ei yhden yhtäkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Eivätkö he mitään käsitä, kaikki nuo väärintekijät, jotka saavat leipänsä syömällä minun kansaani eivätkä avuksensa huuda Herraa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Siinä heidät valtaa kauhu, sillä Jumala on läsnä vanhurskasten sukukunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Te saatatte häpeään sorretun aikeet, mutta Herra on heidän turvansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Oi, että Israelin pelastus tulisi Siionista! Kun Herra kääntää kansansa kohtalon, silloin Jaakob riemuitsee, Israel iloitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Daavidin virsi. Herra, kuka saa vierailla sinun majassasi, kuka asua sinun pyhällä vuorellasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Se, joka vaeltaa nuhteettomasti, joka tekee vanhurskauden ja puhuu sydämessänsä totuutta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'joka ei panettele kielellänsä, joka ei tee toiselle pahaa eikä saata lähimmäistään häväistyksen alaiseksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'joka halveksuu hylkiötä, mutta kunnioittaa niitä, jotka pelkäävät Herraa; joka ei valaansa riko, vaikka on vannonut vahingokseen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'joka ei anna rahaansa korolle eikä ota lahjuksia viatonta vastaan. Joka näin tekee, hän ei ikinä horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Daavidin laulu. Varjele minua, Jumala, sillä sinuun minä turvaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Minä sanon Herralle: \"Sinä olet minun Herrani, paitsi sinua ei ole minulla mitään hyvää\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'ja pyhille, jotka maassa ovat: \"Nämä ovat ne jalot, joihin on koko minun mielisuosioni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Monta tuskaa on niillä, jotka ottavat vieraan jumalan; minä en uhraa niille verta juomauhriksi enkä päästä huulilleni niiden nimiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Herra on minun pelto-ja malja-osani; sinä hoidat minun arpani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Arpa lankesi minulle ihanasta maasta, ja kaunis on minun perintöosani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Minä kiitän Herraa, joka on minua neuvonut; yölläkin minua siihen sisimpäni kehoittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Minä pidän Herran aina edessäni; kun hän on minun oikealla puolellani, en minä horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Sentähden minun sydämeni iloitsee ja sieluni riemuitsee, ja myös minun ruumiini asuu turvassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Sillä sinä et hylkää minun sieluani tuonelaan etkä anna hurskaasi nähdä kuolemaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Sinä neuvot minulle elämän tien; ylenpalttisesti on iloa sinun kasvojesi edessä, ihanuutta sinun oikeassa kädessäsi iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Daavidin rukous. Kuule, Herra, minun oikeata asiaani, tarkkaa minun huutoani, ota korviisi minun rukoukseni, joka ei lähde petollisilta huulilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Sinulta tulee minulle oikeus, sinun silmäsi katsovat sitä, mikä oikein on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Sinä koettelet minun sydäntäni, tarkkaat sitä yöllä, sinä tutkit minua, mutta et mitään löydä. Jos minä pahaa ajattelen, ei se käy suustani ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Mitä ihmiset tehköötkin, sinun huultesi sanassa minä pysyn ja kavahdan väkivaltaisen teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Minun askeleeni pysyvät sinun poluillasi, minun jalkani eivät horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Minä huudan sinua avukseni, sillä sinä vastaat minulle, Jumala; kallista korvasi minun puoleeni, kuule minun puheeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Osoita ihmeellinen armosi, sinä, joka pelastat vihamiesten vallasta ne, jotka turvaavat sinun oikeaan käteesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Varjele minua niinkuin silmäterää, kätke minut siipiesi suojaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'jumalattomilta, jotka tahtovat minut tuhota, verivihollisiltani, jotka minua saartavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'He ovat sulkeneet tunnottomat sydämensä, heidän suunsa puhuu ylvästellen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'He ovat kintereillämme, he jo kiertävät meidät, he vaanivat silmillään, lyödäksensä maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Hän on niinkuin saalista himoitseva leijona, niinkuin nuori leijona, joka piilossa väijyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Nouse, Herra, astu hänen eteensä. Paiskaa hänet maahan. Vapahda miekallasi minun sieluni jumalattomista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'kädelläsi ihmisistä, Herra, tämän maailman ihmisistä, joiden osa on tässä elämässä, joiden vatsan sinä täytät antimillasi, joiden pojat tulevat ravituiksi ja jotka jättävät yltäkylläisyytensä lapsilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Mutta minä saan nähdä sinun kasvosi vanhurskaudessa, herätessäni ravita itseni sinun muotosi katselemisella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Veisuunjohtajalle; Herran palvelijan Daavidin virsi, jonka sanat hän puhui Herralle sinä päivänä, jona Herra oli pelastanut hänet kaikkien hänen vihollistensa vallasta ja Saulin kädestä. {18:2} Hän sanoi: Sydämestäni minä rakastan sinua, Herra, minun voimani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, '{18:3} Herra, minun kallioni, linnani ja pelastajani, minun Jumalani, vuoreni, jonka turviin minä pakenen, minun kilpeni, autuuteni sarvi ja varustukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, '{18:4} Ylistetty olkoon Herra! -niin minä huudan, ja vihollisistani minä pelastun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, '{18:5} Kuoleman paulat piirittivät minut, turmion virrat peljästyttivät minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, '{18:6} Tuonelan paulat kietoivat minut, kuoleman ansat yllättivät minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, '{18:7} Ahdistuksessani minä rukoilin Herraa ja huusin avuksi Jumalaani; hän kuuli minun ääneni temppelistänsä, ja minun huutoni hänen edessään kohosi hänen korviinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, '{18:8} Silloin maa huojui ja järisi, vuorten perustukset järkkyivät; ne horjuivat, sillä hänen vihansa syttyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, '{18:9} Savu suitsusi hänen sieraimistaan, kuluttava tuli hänen suustansa, palavat hiilet hehkuivat hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, '{18:10} Hän notkisti taivaat ja astui alas, synkkä pilvi jalkojensa alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, '{18:11} Ja hän ajoi kerubin kannattamana ja lensi, ja hän liiti tuulen siivillä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, '{18:12} hän pani pimeyden verhoksensa, majaksensa yltympäri: mustat vedet, paksut pilvet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, '{18:13} Hohteesta, joka kävi hänen edellänsä, purkautuivat pilvet rakeiksi ja palaviksi hiiliksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, '{18:14} Ja Herra jylisi taivaassa, Korkein antoi äänensä kaikua, tulla rakeita ja palavia hiiliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, '{18:15} Hän lennätti nuolensa ja hajotti heidät, paljon salamoita ja kauhistutti heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, '{18:16}. Silloin vetten syvyydet tulivat näkyviin, ja maanpiirin perustukset paljastuivat sinun nuhtelustasi, Herra, sinun vihasi hengen puuskauksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, '{18:17} Hän ojensi kätensä korkeudesta ja tarttui minuun, veti minut ylös suurista vesistä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, '{18:18} hän pelasti minut voimallisesta vihollisestani, minun vihamiehistäni, sillä he olivat minua väkevämmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, '{18:19} He hyökkäsivät minun kimppuuni hätäni päivänä, mutta Herra tuli minun tuekseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, '{18:20} Hän toi minut avaraan paikkaan, hän vapautti minut, sillä hän oli mielistynyt minuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, '{18:21} Herra tekee minulle minun vanhurskauteni mukaan, minun kätteni puhtauden mukaan hän minulle maksaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, '{18:22} Sillä minä olen noudattanut Herran teitä enkä ole luopunut pois Jumalastani, jumalattomuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, '{18:23} Kaikki hänen oikeutensa ovat minun silmieni edessä, enkä minä hänen käskyjänsä syrjään sysää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, '{18:24} Minä olen vilpitön häntä kohtaan ja varon itseni pahoista teoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, '{18:25} Sentähden Herra palkitsee minulle minun vanhurskauteni mukaan, sen mukaan kuin käteni ovat puhtaat hänen silmiensä edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, '{18:26} Hurskasta kohtaan sinä olet hurskas, nuhteetonta kohtaan nuhteeton;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, '{18:27} puhdasta kohtaan sinä olet puhdas, mutta kieroa kohtaan nurja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, '{18:28} Sillä sinä pelastat nöyrän kansan, mutta ylpeät silmät sinä painat alas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, '{18:29} Sillä sinä annat minun lamppuni loistaa; Herra, minun Jumalani, valaisee minun pimeyteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, '{18:30} Sinun avullasi minä hyökkään rosvojoukkoa vastaan; Jumalani avulla minä ryntään ylitse muurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, '{18:31} Jumalan tie on nuhteeton, Herran sana tulessa koeteltu. Hän on kaikkien kilpi, jotka häneen turvaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, '{18:32} Sillä kuka muu on Jumala kuin Herra, ja kuka pelastuksen kallio, paitsi meidän Jumalamme-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, '{18:33} se Jumala, joka minut voimalla vyöttää ja tekee minun tieni nuhteettomaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, '{18:34} tekee minun jalkani nopeiksi niinkuin peurat ja asettaa minut kukkuloilleni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, '{18:35} joka opettaa minun käteni sotimaan ja käsivarteni vaskijousta jännittämään!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, '{18:36} Sinä annat minulle pelastuksen kilven, ja sinun oikea kätesi minua tukee; sinun laupeutesi tekee minut suureksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, '{18:37} Sinä annat minun askeleilleni avaran tilan, ja minun jalkani eivät horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, '{18:38} Minä ajan vihollisiani takaa ja saavutan heidät enkä palaja, ennenkuin teen heistä lopun;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, '{18:39} minä murskaan heidät, niin etteivät voi nousta, he sortuvat minun jalkojeni alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, '{18:40} Sinä vyötät minut voimalla sotaan, sinä painat vastustajani minun alleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, '{18:41} Sinä ajat minun viholliseni pakoon, ja vihamieheni minä hukutan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, '{18:42} He huutavat, mutta pelastajaa ei ole, huutavat Herraa, mutta hän ei heille vastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, '{18:43} Minä survon heidät tomuksi tuuleen, viskaan heidät niinkuin loan kadulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, '{18:44} Sinä pelastat minut kansan riidoista, sinä asetat minut pakanain pääksi, kansat, joita minä en tunne, palvelevat minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, '{18:45} Jo korvan kuulemalta he minua tottelevat; muukalaiset matelevat minun edessäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, '{18:46} Muukalaiset masentuvat ja tulevat vavisten varustuksistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, '{18:47} Herra elää! Kiitetty olkoon minun kallioni ja ylistetty minun pelastukseni Jumala,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, '{18:48} Jumala, joka hankkii minulle koston ja saattaa kansat minun valtani alle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, '{18:49} sinä, joka pelastat minut vihollisistani ja korotat minut vastustajaini ylitse ja päästät minut väkivaltaisesta miehestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, '{18:50} Sentähden minä ylistän sinua, Herra, kansojen keskuudessa ja veisaan sinun nimesi kiitosta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, '{18:51} sinun, joka annat kuninkaallesi suuren avun ja teet laupeuden voidellullesi, Daavidille ja hänen jälkeläisilleen, iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Veisuunjohtajalle; Daavidin virsi. {19:2} Taivaat julistavat Jumalan kunniaa, taivaanvahvuus ilmoittaa hänen kättensä tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, '{19:3} Päivä sanoo päivälle, ja yö ilmoittaa yölle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, '{19:4} Se ei ole puhetta, se ei ole kieltä, jonka ääni ei kuuluisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, '{19:5} Niiden mittanuora ulottuu yli kaiken maan ja niiden sanat maanpiirin ääriin. Auringolle hän on tehnyt niihin majan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, '{19:6} Se on niinkuin ylkä, joka tulee kammiostaan, se riemuitsee kuin sankari rataansa juostessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, '{19:7} Se nousee taivasten ääristä ja kiertää niiden toisiin ääriin, eikä mikään voi lymytä sen helteeltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, '{19:8} Herran laki on täydellinen; se virvoittaa sielun. Herran todistus on vahva, se tekee tyhmästä viisaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, '{19:9} Herran asetukset ovat oikeat, ne ilahuttavat sydämen. Herran käskyt ovat selkeät, ne valaisevat silmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, '{19:10} Herran pelko on puhdas, se pysyy iäti. Herran oikeudet ovat todet, kaikki tyynni vanhurskaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, '{19:11} Ne ovat kalliimmat kultaa, puhtaan kullan paljoutta, makeammat hunajaa ja mehiläisen mettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, '{19:12} Myös sinun palvelijasi ottaa niistä vaarin, niiden noudattamisesta on suuri palkka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, '{19:13} Erhetykset kuka ymmärtää? Anna anteeksi minun salaiset syntini.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, '{19:14} Myös varjele palvelijasi julkeilta, älä anna heidän minua hallita. Niin minä pysyn nuhteetonna ja olen paljosta synnistä puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, '{19:15} Kelvatkoot sinulle minun suuni sanat ja minun sydämeni ajatukset sinun edessäsi, Herra, minun kallioni ja lunastajani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Veisuunjohtajalle; Daavidin virsi. {20:2} Kuulkoon Herra sinua hädän päivänä, varjelkoon sinua Jaakobin Jumalan nimi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, '{20:3} Hän lähettäköön sinulle avun pyhäköstä ja tukekoon sinua Siionista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, '{20:4} Muistakoon hän kaikki sinun uhrilahjasi, ja olkoon sinun polttouhrisi lihava hänen silmissään. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, '{20:5} Hän antakoon sinulle, mitä sydämesi halajaa, ja täyttäköön kaikki sinun aivoituksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, '{20:6} Suotakoon meidän riemuita sinun voitostasi ja nostaa lippumme Jumalamme nimeen. Täyttäköön Herra kaikki sinun pyyntösi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, '{20:7} Nyt minä tiedän, että Herra auttaa voideltuansa, vastaa hänelle pyhästä taivaastansa, auttaa häntä oikean kätensä voimallisilla teoilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, '{20:8} Toiset turvaavat vaunuihin, toiset hevosiin, mutta me tunnustamme Herran, Jumalamme, nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, '{20:9} He vaipuvat maahan ja kaatuvat, mutta me nousemme ja pysymme pystyssä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, '{20:10} Herra, auta! Vastatkoon kuningas meille, kun huudamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Veisuunjohtajalle; Daavidin virsi. {21:2} Herra, sinun voimastasi kuningas iloitsee; kuinka suuresti hän riemuitseekaan sinun avustasi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, '{21:3} Mitä hänen sydämensä halasi, sen sinä hänelle annoit, et kieltänyt, mitä hänen huulensa anoivat. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, '{21:4} Sinä suot hänelle onnen ja siunauksen, panet hänen päähänsä kultaisen kruunun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, '{21:5} Hän anoi sinulta elämää, sen sinä hänelle annoit: iän pitkän, ainaisen, iankaikkisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, '{21:6} Suuri on hänen kunniansa, kun sinä häntä autoit; sinä peität hänet loistolla ja kirkkaudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, '{21:7} Sillä sinä asetat hänet suureksi siunaukseksi ikuisiin aikoihin asti; sinä ilahutat häntä riemulla kasvojesi edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, '{21:8} Sillä kuningas luottaa Herraan, ja Korkeimman armo tekee hänet horjumattomaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, '{21:9} Sinun kätesi saavuttaa kaikki sinun vihollisesi, sinun oikea kätesi saavuttaa sinun vihamiehesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, '{21:10} Sinä panet heidät hehkumaan kuin pätsin, kun sinä kasvosi näytät; Herra nielee heidät vihassansa, tuli kuluttaa heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, '{21:11} Sinä hävität maan päältä heidän hedelmänsä ja heidän jälkeläisensä ihmislasten keskuudesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, '{21:12} Vaikka he hankkivat pahaa sinua vastaan, miettivät juonia, eivät he mitään voi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, '{21:13} sillä sinä ajat heidät pakoon, tähtäät heitä kasvoihin jousesi jänteellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, '{21:14} Nouse voimassasi, Herra! Laulaen ja veisaten me ylistämme sinun väkevyyttäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Veisuunjohtajalle; veisataan kuin: \"Aamuruskon peura\"; Daavidin virsi. {22:2} Jumalani, Jumalani, miksi minut hylkäsit? Miksi olet kaukana, et auta minua, et kuule valitukseni sanoja?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, '{22:3} Jumalani, minä huudan päivällä, mutta sinä et vastaa, ja yöllä, enkä voi vaieta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, '{22:4} Ja kuitenkin sinä olet Pyhä, jonka istuin on Israelin kiitosvirtten keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, '{22:5} Meidän isämme luottivat sinuun, he luottivat, ja sinä pelastit heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, '{22:6} He huusivat sinua ja pelastuivat; he luottivat sinuun eivätkä tulleet häpeään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, '{22:7} Mutta minä olen mato enkä ihminen, ihmisten pilkka ja kansan hylky.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, '{22:8} Kaikki, jotka minut näkevät, pilkkaavat minua, levittelevät suutansa, nyökyttävät ilkkuen päätään:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, '{22:9} \"Jätä asiasi Herran haltuun. Hän vapahtakoon hänet, hän pelastakoon hänet, koska on häneen mielistynyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, '{22:10} Sinähän vedit minut äitini kohdusta, sinä annoit minun olla turvassa äitini rinnoilla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, '{22:11} sinun huomaasi minä olen jätetty syntymästäni saakka, sinä olet minun Jumalani hamasta äitini kohdusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, '{22:12} Älä ole minusta kaukana, sillä ahdistus on läsnä, eikä auttajaa ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, '{22:13} Minua saartavat väkevät sonnit, Baasanin härät piirittävät minut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, '{22:14} avaavat kitansa minua vastaan, niinkuin raatelevat, kiljuvat leijonat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, '{22:15} Niinkuin vesi minä olen maahan vuodatettu; kaikki minun luuni ovat irti toisistansa; minun sydämeni on niinkuin vaha, se on sulanut minun rinnassani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, '{22:16} Minun voimani on kuivettunut kuin saviastian siru, ja kieleni tarttuu suuni lakeen, ja sinä lasket minut alas kuoleman tomuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, '{22:17} Sillä koirat minua piirittävät, pahain parvi saartaa minut, minun käteni ja jalkani, niinkuin jalopeurat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, '{22:18} Minä voin lukea kaikki luuni; he katselevat minua ilkkuen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, '{22:19} he jakavat keskenänsä minun vaatteeni ja heittävät minun puvustani arpaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, '{22:20} Mutta sinä, Herra, älä ole kaukana, sinä, minun väkevyyteni, riennä avukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, '{22:21} Vapahda minun sieluni miekasta, minun ainokaiseni koirain kynsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, '{22:22} Pelasta minut jalopeuran kidasta, villihärkäin sarvista-vastaa minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, '{22:23} Minä julistan sinun nimeäsi veljilleni, ylistän sinua seurakunnan keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, '{22:24} Te, jotka pelkäätte Herraa, ylistäkää häntä. Kunnioittakaa häntä, kaikki Jaakobin siemen, kaikki Israelin siemen, peljätkää häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, '{22:25} Sillä hän ei halveksi kurjan kärsimystä, ei katso sitä ylen, eikä kätke häneltä kasvojansa, vaan kuulee hänen avuksihuutonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, '{22:26} Sinusta on minun ylistyslauluni suuressa seurakunnassa; minä täytän lupaukseni häntä pelkääväisten edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, '{22:27} Nöyrät saavat syödä ja tulevat ravituiksi; ne, jotka etsivät Herraa, ylistävät häntä. Teidän sydämenne on elävä iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, '{22:28} Kaikki maan ääret muistavat tämän ja palajavat Herran tykö; kaikki pakanain sukukunnat kumartavat häntä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, '{22:29} sillä Herran on kuninkuus, ja hän on hallitseva pakanoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, '{22:30} Kaikki maan mahtavat syövät ja kumartavat; hänen edessään polvistuvat kaikki, jotka mullan alle astuvat eivätkä voi elossa pysyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, '{22:31} Jälkeentulevaiset palvelevat häntä, tuleville polville kerrotaan Herrasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, '{22:32} He tulevat ja julistavat vastedes syntyvälle kansalle hänen vanhurskauttaan, että hän on tämän tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Daavidin virsi. Herra on minun paimeneni, ei minulta mitään puutu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Viheriäisille niityille hän vie minut lepäämään; virvoittavien vetten tykö hän minut johdattaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Hän virvoittaa minun sieluni. Hän ohjaa minut oikealle tielle nimensä tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Vaikka minä vaeltaisin pimeässä laaksossa, en minä pelkäisi mitään pahaa, sillä sinä olet minun kanssani; sinun vitsasi ja sauvasi minua lohduttavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Sinä valmistat minulle pöydän minun vihollisteni silmien eteen. Sinä voitelet minun pääni öljyllä; minun maljani on ylitsevuotavainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Sula hyvyys ja laupeus seuraavat minua kaiken elinaikani; ja minä saan asua Herran huoneessa päivieni loppuun asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Daavidin virsi. Herran on maa ja kaikki, mitä siinä on, maanpiiri ja ne, jotka siinä asuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Sillä hän on sen perustanut merten päälle, vahvistanut sen virtojen päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Kuka saa astua Herran vuorelle, kuka seisoa hänen pyhässä paikassansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Se, jolla on viattomat kädet ja puhdas sydän, joka ei halaja turhuutta eikä vanno väärin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Hän saa siunauksen Herralta ja vanhurskauden pelastuksensa Jumalalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Tämä on se suku, joka häntä kysyy, joka etsii sinun kasvojasi, -tämä on Jaakob. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Nostakaa päänne, te portit, nostakaa päänne, te ikuiset ovet, kunnian kuninkaan käydä sisälle!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Kuka on se kunnian kuningas? Hän on Herra, väkevä ja voimallinen, Herra, voimallinen sodassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Nostakaa päänne, te portit, nostakaa päänne, te ikuiset ovet, kunnian kuninkaan käydä sisälle!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Kuka on se kunnian kuningas? Hän on Herra Sebaot, hän on kunnian kuningas. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Daavidin virsi. Sinun tykösi, Herra, minä ylennän sieluni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Jumalani, sinuun minä turvaan; älä salli minun joutua häpeään, älkööt viholliseni saako riemuita minusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Ei yksikään, joka sinua odottaa, joudu häpeään; häpeään joutuvat ne, jotka ovat syyttä uskottomat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Herra, neuvo minulle tiesi, opeta minulle polkusi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Johdata minua totuutesi tiellä ja opeta minua, sillä sinä olet minun pelastukseni Jumala. Sinua minä odotan kaiken päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Muista laupeuttasi, Herra, ja armoasi, sillä ne ovat olleet hamasta iankaikkisuudesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Älä muista minun nuoruuteni syntejä, älä minun rikoksiani; muista minua armosi mukaan, hyvyytesi tähden, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Hyvä ja vakaa on Herra; sentähden hän neuvoo syntiset tielle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Hän johdattaa nöyriä oikein, hän opettaa nöyrille tiensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Kaikki Herran polut ovat armo ja totuus niille, jotka pitävät hänen liittonsa ja todistuksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Nimesi tähden, Herra, anna anteeksi minun syntivelkani, sillä se on suuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Kuka on se mies, joka Herraa pelkää-sen hän neuvoo tielle, joka hänen on valittava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Hänen sielunsa saa nauttia hyvää, ja hänen jälkeläisensä perivät maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Herran neuvo on tunnettu niille, jotka häntä pelkäävät, ja hän ilmoittaa heille liittonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Minun silmäni katsovat alati Herraan, sillä hän päästää minun jalkani verkosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Käänny minun puoleeni, armahda minua, sillä minä olen yksinäinen ja kurja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Minun sydämeni pakahtuu tuskasta; päästä minut ahdistuksistani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Katso minun kurjuuttani ja vaivaani, anna kaikki minun syntini anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Katso minun vihollisiani, kuinka heitä on paljon, ja he vihaavat minua väkivaltaisella vihalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Varjele minun sieluni ja pelasta minut. Älä salli minun tulla häpeään, sillä sinuun minä turvaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Nuhteettomuus ja oikeamielisyys varjelkoon minua, sillä sinua minä odotan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Jumala, vapahda Israel kaikista ahdistuksistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Daavidin virsi. Auta minut oikeuteeni, Herra, sillä minä olen vaeltanut nuhteettomasti ja turvaan horjumatta Herraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Tutki minua, Herra, ja pane minut koetukselle, koettele minun munaskuuni ja sydämeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Sillä sinun armosi on minun silmäini edessä, ja minä olen vaeltanut sinun totuudessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'En minä istu valheen miesten seurassa enkä kulje salakavalain kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Minä vihaan pahojen seuraa enkä istu jumalattomien parissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Minä pesen käteni viattomuudessa, ja astun kulkueessa sinun alttarisi ympäri, Herra,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'antaakseni kuulua kiitokseni äänen ja julistaakseni kaikkia sinun ihmeitäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Herra, minä rakastan sinun huonettasi, sinun asuinsijaasi, sitä paikkaa, jossa sinun kirkkautesi asuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Älä tempaa pois minun sieluani syntisten kanssa äläkä minun henkeäni verenvuodattajain kanssa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'joiden käsiä ilkityö tahraa, joiden oikea käsi on lahjuksia täynnä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Mutta minä vaellan nuhteettomasti; vapahda minut ja ole minulle armollinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Minun jalkani seisoo tasaisella maalla; seurakunnan kokouksissa minä kiitän Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Daavidin virsi. Herra on minun valkeuteni ja autuuteni: ketä minä pelkään! Herra on minun elämäni turva: ketä minä vapisen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Kun pahat käyvät minun kimppuuni, syömään minun lihaani, niin he, minun ahdistajani ja vihamieheni, kompastuvat ja kaatuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Vaikka sotajoukko asettuisi minua vastaan, ei minun sydämeni pelkäisi; vaikka sota nousisi minua vastaan, siinäkin minä olisin turvassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Yhtä minä rukoilen Herralta, sitä minä pyydän: että saisin asua Herran huoneessa kaiken elinaikani, katsella Herran suloisuutta ja tutkistella hänen temppelissänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Sillä hän kätkee minut majaansa pahana päivänä, hän suojaa minua telttansa suojassa, korottaa minut kalliolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Niin kohoaa nyt minun pääni vihollisteni yli, jotka minua ympäröivät, ja minä uhraan riemu-uhreja hänen majassansa, Herralle minä veisaan ja soitan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Herra, kuule minun ääneni, kun minä huudan, armahda minua ja vastaa minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Minun sydämeni vetoaa sinun omaan sanaasi: \"Etsikää minun kasvojani\". Herra, minä etsin sinun kasvojasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Älä kätke minulta kasvojasi, älä työnnä vihassa pois palvelijaasi. Sinä olet minun apuni, älä minua jätä, älä minua hylkää, pelastukseni Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Vaikka minun isäni ja äitini minut hyljätkööt, niin Herra minut korjaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Neuvo, Herra, minulle tiesi ja johdata minua tasaista polkua minun vihamiesteni tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Älä anna minua alttiiksi ahdistajaini vimmalle, sillä väärät todistajat nousevat minua vastaan ja puuskuvat väkivaltaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Mutta minä totisesti uskon näkeväni Herran hyvyyden elävien maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Odota Herraa. Ole luja, ja vahva olkoon sinun sydämesi. Odota Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Daavidin virsi. Sinua, Herra, minä huudan; minun kallioni, älä ole minua kohtaan äänetön, etten minä, kun sinä vaiti olet, joutuisi niiden kaltaiseksi, jotka ovat hautaan vaipuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Kuule minun rukousteni ääni, kun minä sinua avuksi huudan, kun minä käteni nostan sinun kaikkeinpyhintäsi kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Älä tempaa minua pois jumalattomien kanssa, älä väärintekijäin kanssa, jotka puhuvat lähimmäisilleen rauhan puheita, vaikka heidän sydämessään on pahuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Anna heille heidän työnsä mukaan ja heidän tekojensa pahuuden mukaan; anna heille heidän kättensä tekojen mukaan, kosta heille, mitä he ovat tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Sillä eivät he ota vaaria Herran töistä eivätkä hänen kättensä teoista. Hän kukistakoon heidät, älköönkä heitä rakentako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Kiitetty olkoon Herra, sillä hän on kuullut minun rukousteni äänen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Herra on minun voimani ja kilpeni; häneen minun sydämeni turvasi, ja minä sain avun. Siitä minun sydämeni riemuitsee, ja veisuullani minä häntä ylistän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Herra on kansansa väkevyys, hän on voideltunsa pelastus ja turva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Pelasta kansasi ja siunaa perikuntasi; kaitse heitä ja kanna heitä iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Daavidin virsi. Antakaa Herralle, te Jumalan pojat, antakaa Herralle kunnia ja väkevyys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Antakaa Herralle hänen nimensä kunnia, kumartakaa Herraa pyhässä kaunistuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Herran ääni käy vetten päällä; kunnian Jumala jylisee, Herra suurten vetten päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Herran ääni käy voimallisesti, Herran ääni käy valtavasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Herran ääni särkee setrit, Herra särkee Libanonin setrit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Hän hypittää niitä niinkuin vasikkaa, Libanonia ja Sirjonia niinkuin nuorta villihärkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Herran ääni halkoo tulen liekit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Herran ääni vapisuttaa erämaan, Herra vapisuttaa Kaadeksen erämaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Herran ääni saattaa peurat poikimaan, se raastaa paljaiksi metsät. Ja kaikki hänen temppelissänsä sanoo: \"Kunnia!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Herra istui valtaistuimellaan, ja vedenpaisumus tuli. Herra istuu kuninkaana iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Herra antaa kansallensa väkevyyden, Herra siunaa kansaansa rauhalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Daavidin virsi; temppelin vihkimislaulu. {30:2} Minä ylistän sinua, Herra, sillä sinä pelastit minut etkä sallinut viholliseni iloita minusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, '{30:3} Herra, minun Jumalani, sinua minä huusin, ja sinä paransit minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, '{30:4} Herra, sinä nostit minun sieluni tuonelasta, sinä herätit minut henkiin hautaan vaipuvien joukosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, '{30:5} Veisatkaa kiitosta Herralle, te hänen hurskaansa, ylistäkää hänen pyhää nimeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, '{30:6} Sillä silmänräpäyksen kestää hänen vihansa, eliniän hänen armonsa; ehtoolla on itku vieraana, mutta aamulla ilo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, '{30:7} Minä sanoin menestykseni päivinä: \"En minä ikinä horju\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, '{30:8} Herra, sinä armossasi vahvistit minun vuoreni. Mutta kun sinä kätkit kasvosi, niin minä peljästyin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, '{30:9} Sinua, Herra, minä huusin ja Herraa minä rukoilin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, '{30:10} \"Mitä etua on minun verestäni, jos minä hautaan vaivun? Ylistääkö tomu sinua, julistaako se sinun uskollisuuttasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, '{30:11} Kuule, Herra, ja armahda minua, Herra, ole minun auttajani.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, '{30:12} Sinä muutit minun murheeni ilokarkeloksi, sinä riisuit minun surupukuni ja vyötit minut riemulla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, '{30:13} että minun sieluni veisaisi sinulle kiitosta, eikä vaikenisi. Herra, minun Jumalani, sinua minä ylistän iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Veisuunjohtajalle; Daavidin virsi. {31:2} Herra, sinuun minä turvaan. Älä salli minun ikinä häpeään tulla, vapahda minut vanhurskaudessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, '{31:3} Kallista korvasi minun puoleeni, riennä, pelasta minut. Ole minulle turvakallio, vuorilinna, johon minut pelastat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, '{31:4} Sillä sinä olet minun kallioni ja linnani, ja nimesi tähden sinä minua johdat ja talutat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, '{31:5} Sinä päästät minut verkosta, jonka he ovat eteeni virittäneet, sillä sinä olet minun turvani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, '{31:6} Sinun käteesi minä annan henkeni, sinä, Herra, lunastat minut, sinä uskollinen Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, '{31:7} Minä vihaan niitä, jotka seuraavat turhia epäjumalia, mutta minä turvaan Herraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, '{31:8} Minä iloitsen ja riemuitsen sinun armostasi, kun sinä katsoit minun kurjuuttani, tunsit minun sieluni ahdistukset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, '{31:9} etkä jättänyt minua vihollisen valtaan, vaan asetit minun jalkani aukealle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, '{31:10} Armahda minua, Herra, sillä minulla on ahdistus; minun silmäni on surusta riutunut, niin myös minun sieluni ja ruumiini.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, '{31:11}. Sillä minun elämäni kuluu murheessa ja minun vuoteni huokauksissa. Minun voimani on rauennut pahain tekojeni tähden, ja minun luuni ovat riutuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, '{31:12} Kaikkien ahdistajaini tähden minä olen pilkaksi tullut, ylenpalttiseksi pilkaksi naapureilleni, peljätykseksi tuttavilleni; jotka minut kadulla näkevät, pakenevat minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, '{31:13} Minä olen unhottunut ihmisten mielistä niinkuin kuollut, minä olen kuin rikottu astia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, '{31:14} Sillä minä kuulen monen parjaukset, kauhua kaikkialta, kun he keskenänsä pitävät neuvoa minua vastaan, aikovat ottaa minulta hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, '{31:15} Mutta sinuun, Herra, minä turvaan; minä sanon: \"Sinä olet minun Jumalani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, '{31:16} Minun aikani ovat sinun kädessäsi, pelasta minut vihollisteni kädestä ja vainoojistani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, '{31:17} Valista kasvosi palvelijallesi, pelasta minut armossasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, '{31:18} Herra, älä salli minun tulla häpeään, sillä sinua minä huudan avukseni. Jumalattomat tulkoot häpeään, vaietkoot ja vaipukoot tuonelaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, '{31:19} Mykistykööt valheen huulet, jotka puhuvat vanhurskasta vastaan röyhkeästi, ylpeästi ja ylenkatseellisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, '{31:20} Kuinka suuri on sinun hyvyytesi, jonka talletat pelkääväisillesi ja jota osoitat sinuun turvaaville ihmislasten edessä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, '{31:21} Sinä peität heidät kasvojesi suojaan ihmisten salavehkeiltä; sinä kätket heidät turvaan kielten riidalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, '{31:22} Kiitetty olkoon Herra, sillä hän osoitti minulle ihmeellisen armonsa piiritetyssä kaupungissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, '{31:23} Minä sanoin hädässäni: \"Minä olen sysätty pois sinun silmiesi edestä\". Kuitenkin sinä kuulit minun rukousteni äänen, kun minä sinua huusin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, '{31:24} Rakastakaa Herraa, kaikki hänen hurskaansa. Herra varjelee uskolliset, mutta ylpeileväisille hän kostaa monin kerroin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, '{31:25} Olkaa lujat, ja olkoon teidän sydämenne rohkea, te kaikki, jotka Herraa odotatte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Daavidin mietevirsi. Autuas se, jonka rikokset ovat anteeksi annetut, jonka synti on peitetty!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Autuas se ihminen, jolle Herra ei lue hänen pahoja tekojansa ja jonka hengessä ei ole vilppiä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Kun minä siitä vaikenin, riutuivat minun luuni jokapäiväisestä valituksestani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Sillä yötä päivää oli sinun kätesi raskaana minun päälläni; minun nesteeni kuivui niinkuin kesän helteessä. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Minä tunnustin sinulle syntini enkä peittänyt pahoja tekojani; minä sanoin: \"Minä tunnustan Herralle rikokseni\", ja sinä annoit anteeksi minun syntivelkani. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Sentähden rukoilkoot sinua kaikki hurskaat aikana, jona sinut löytää voidaan. Vaikka suuret vedet tulvisivat, eivät ne heihin ulotu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Sinä olet minun suojani, sinä varjelet minut hädästä, sinä ympäröitset minut pelastuksen riemulla. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, '\"Minä opetan sinua ja osoitan sinulle tien, jota sinun tulee vaeltaa; minä neuvon sinua, minun silmäni sinua vartioitsee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Älkää olko niinkuin järjettömät orhit ja muulit, joita suitsilla ja ohjaksilla, niiden valjailla, suistetaan; muutoin ne eivät sinua lähesty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Jumalattomalla on monta vaivaa, mutta joka Herraan turvaa, häntä ympäröitsee armo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Iloitkaa Herrassa ja riemuitkaa, te vanhurskaat, ja veisatkaa ilovirsiä, kaikki te oikeamieliset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Riemuitkaa Herrassa, te vanhurskaat. Oikeamielisten on soveliasta häntä kiittää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Ylistäkää Herraa kanteleilla, soittakaa hänelle kymmenkielisillä harpuilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Veisatkaa hänelle uusi virsi, helkyttäkää kieliä ihanasti ja riemullisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Sillä Herran sana on oikea, ja kaikki hänen tekonsa ovat tehdyt uskollisuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Hän rakastaa vanhurskautta ja oikeutta; maa on täynnänsä Herran armoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Herran sanalla ovat taivaat tehdyt, ja kaikki niiden joukot hänen suunsa hengellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Hän kokoaa meren vedet niinkuin roukkioksi, panee syvyydet säiliöihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Peljätköön Herraa kaikki maa, hänen edessänsä vaviskoot kaikki maanpiirin asukkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Sillä hän sanoi, ja tapahtui niin, hän käski, ja se oli tehty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Herra särkee pakanain neuvon, tekee turhiksi kansojen aikeet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Mutta Herran neuvo pysyy iankaikkisesti, hänen sydämensä aivoitukset suvusta sukuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Autuas se kansa, jonka Jumala Herra on, se kansa, jonka hän on perinnöksensä valinnut!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Herra katsoo alas taivaasta, näkee kaikki ihmislapset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'asumuksestaan, valtaistuimeltaan hän katselee kaikkia maan asukkaita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'hän, joka on luonut kaikkien heidän sydämensä, joka tarkkaa kaikkia heidän tekojansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Ei kuningas voita paljolla väellänsä, ei sankari pelastu suurella voimallansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Turha on sotaratsu auttajaksi, ei pelasta sen suuri väkevyys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Katso, Herran silmä valvoo niitä, jotka häntä pelkäävät ja panevat toivonsa hänen laupeuteensa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'pelastaaksensa heidän sielunsa kuolemasta, elättääksensä heitä nälän aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Meidän sielumme odottaa Herraa, hän on meidän apumme ja kilpemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Sillä hänessä iloitsee meidän sydämemme, me turvaamme hänen pyhään nimeensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Sinun armosi, Herra, olkoon meidän päällämme, niinkuin me panemme toivomme sinuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Daavidin virsi, kun hän tekeytyi mielipuoleksi Abimelekin edessä ja tämä karkoitti hänet luotansa ja hän meni pois. {34:2} Minä kiitän Herraa joka aika, hänen ylistyksensä on alati minun suussani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, '{34:3} Herra on minun sieluni kerskaus, nöyrät sen kuulevat ja iloitsevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, '{34:4} Ylistäkää minun kanssani Herraa, kiittäkäämme yhdessä hänen nimeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, '{34:5} Minä etsin Herraa, ja hän vastasi minulle, hän vapahti minut kaikista peljätyksistäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, '{34:6} Jotka häneen katsovat, ne säteilevät iloa, heidän kasvonsa eivät häpeästä punastu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, '{34:7} Tässä on kurja, joka huusi, ja Herra kuuli ja pelasti hänet kaikista hänen ahdistuksistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, '{34:8} Herran enkeli asettuu niiden ympärille, jotka häntä pelkäävät, ja pelastaa heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, '{34:9} Maistakaa ja katsokaa, kuinka Herra on hyvä. Autuas se mies, joka häneen turvaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, '{34:10} Peljätkää Herraa, te hänen pyhänsä, sillä häntä pelkääväisiltä ei mitään puutu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, '{34:11} Nuoret leijonat kärsivät puutetta ja näkevät nälkää, mutta Herraa etsiväisiltä ei mitään hyvää puutu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, '{34:12} Tulkaa, lapset, kuulkaa minua: Herran pelkoon minä teidät opetan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, '{34:13} Kuka oletkin, joka elää tahdot ja rakastat elämän päiviä, nauttiaksesi onnea:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, '{34:14} varjele kielesi pahasta ja huulesi vilppiä puhumasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, '{34:15} vältä pahaa ja tee hyvää, etsi rauhaa ja pyri siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, '{34:16} Herran silmät tarkkaavat vanhurskaita ja hänen korvansa heidän huutoansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, '{34:17} Herran kasvot ovat pahantekijöitä vastaan, hävittääksensä maasta heidän muistonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, '{34:18} Vanhurskaat huutavat, ja Herra kuulee ja vapahtaa heidät kaikista heidän ahdistuksistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, '{34:19} Lähellä on Herra niitä, joilla on särjetty sydän, ja hän pelastaa ne, joilla on murtunut mieli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, '{34:20} Monta on vanhurskaalla kärsimystä, mutta Herra vapahtaa hänet niistä kaikista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, '{34:21} Hän varjelee kaikki hänen luunsa: ei yksikään niistä murru.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, '{34:22} Pahuus tappaa jumalattoman, ja jotka vanhurskasta vihaavat, ne tulevat syynalaisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, '{34:23} Herra lunastaa palvelijainsa sielut, eikä yksikään, joka häneen turvaa, tule syynalaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Daavidin virsi. Riitele, Herra, minun riitaveljiäni vastaan; sodi niitä vastaan, jotka minua vastaan sotivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Tempaa pieni kilpi, suuri kilpi ja nouse minun avukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Sivalla keihäs ja salpaa tie minun vainoojiltani. Sano minun sielulleni: \"Minä olen sinun pelastuksesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Joutukoot häpeään ja pilkkaan, jotka minun henkeäni väijyvät; peräytykööt, punastukoot, jotka minulle pahaa aikovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Olkoot he niinkuin akanat tuulessa, ja Herran enkeli syösköön heidät maahan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'heidän tiensä olkoon pimeä ja liukas, ja Herran enkeli ajakoon heitä takaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Sillä syyttä he ovat virittäneet verkkonsa minun eteeni, syyttä he ovat kaivaneet minun sielulleni haudan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Tulkoon hänelle turmio aavistamatta, tarttukoon hän virittämäänsä verkkoon, langetkoon siihen surmaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Mutta minun sieluni iloitkoon Herrassa, riemuitkoon hänen avustansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Kaikki minun luuni sanokoot: \"Herra, kuka on sinun vertaisesi, sinun, joka vapahdat kurjan väkevämmästään, kurjan ja köyhän raatelijastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Väärät todistajat astuvat esiin, he minulta tutkivat, mitä minä en tiedä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'He palkitsevat minulle hyvän pahalla; minun sieluni on orpo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Mutta minä puin päälleni surupuvun, kun he sairastivat; minä vaivasin itseäni paastolla ja rukoilin pää painuksissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Niinkuin he olisivat olleet minun ystäviäni, minun omia veljiäni, niin minä kuljin; niinkuin äitiänsä sureva, niin minä kävin surupuvussa, kumarruksissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Mutta he iloitsevat minun kompastuksestani ja kokoontuvat-kokoontuvat minua vastaan, nuo lyöjät, joita minä en tunne; he herjaavat herkeämättä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'nuo konnat, jotka leipäkyrsää kärkkyen minua pilkkaavat, kiristelevät minulle hampaitansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Herra, kuinka kauan sinä tätä katselet? Päästä minun sieluni turmiosta, jota he hankitsevat, minun ainokaiseni nuorista leijonista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Niin minä kiitän sinua suuressa seurakunnassa, ylistän sinua paljon kansan keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Älkööt ne minusta iloitko, jotka syyttä ovat minun vihamiehiäni; älkööt silmää iskekö, jotka asiatta minua vihaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Sillä he eivät puhu rauhan puheita, vaan miettivät petoksen sanoja maan hiljaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'He avaavat suunsa ammolleen minua vastaan ja sanovat: \"Kas niin, kas niin! Nyt me sen omin silmin näemme!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Sinä, Herra, näet sen, älä ole vaiti! Herra, älä ole minusta kaukana!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Heräjä ja nouse, minun Jumalani ja Herrani, hankkimaan minulle oikeutta ja ajamaan minun asiaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Tuomitse minut vanhurskautesi mukaan, Herra, minun Jumalani, älä salli heidän minusta riemuita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Älä salli heidän sanoa sydämessänsä: \"Kas niin! Sitä me halusimmekin.\" Älä salli heidän sanoa: \"Me olemme hänet nielleet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Hävetkööt ja punastukoot kaikki, jotka minun onnettomuudestani iloitsevat, saakoot puvuksensa häpeän ja pilkan ne, jotka ylvästelevät minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Iloitkoot ja riemuitkoot ne, jotka suovat minulle minun oikeuteni, ja sanokoot aina: \"Ylistetty olkoon Herra, joka tahtoo palvelijansa parasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Ja minun kieleni julistakoon sinun vanhurskauttasi, sinun kiitostasi kaiken päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Veisuunjohtajalle; Herran palvelijan Daavidin virsi. {36:2} Synti sanoo jumalattomalle: minun sydämessäni ei ole Jumalan pelkoa hänen silmäinsä edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, '{36:3} Sillä se tekee kaiken sileäksi hänen silmissään, että hänen pahuutensa havaittaisiin ja häntä vihattaisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, '{36:4} Hänen suunsa sanat ovat vääryyttä ja petosta; hän on lakannut tekemästä sitä, mikä taidollista ja hyvää on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, '{36:5} Hän miettii turmiota vuoteessansa, hän pysyy tiellä, joka ei ole hyvä, hän ei kammo pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, '{36:6} Herra, sinun armosi ulottuu taivaisiin, sinun totuutesi pilviin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, '{36:7} Sinun vanhurskautesi on kuin Jumalan vuoret, sinun tuomiosi niinkuin suuri syvyys, ihmistä ja eläintä sinä autat, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, '{36:8} Kuinka kallis on sinun armosi, Jumala! Ihmislapset etsivät sinun siipiesi suojaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, '{36:9} Heidät ravitaan sinun huoneesi lihavuudella, sinä annat heidän juoda suloisuutesi virrasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, '{36:10} Sillä sinun tykönäsi on elämän lähde; sinun valkeudessasi me näemme valkeuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, '{36:11} Säilytä armosi niille, jotka sinut tuntevat, ja vanhurskautesi oikeamielisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, '{36:12} Älköön ylpeyden jalka minua tallatko, älköönkä jumalattomain käsi minua karkoittako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, '{36:13} Katso, pahantekijät kaatuvat, he suistuvat maahan, eivätkä voi nousta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Daavidin virsi. Älä vihastu pahain tähden, älä kadehdi väärintekijöitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Sillä niinkuin heinä heidät pian niitetään pois, ja he lakastuvat niinkuin vihanta ruoho.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Turvaa Herraan ja tee sitä, mikä hyvä on, asu maassa ja noudata totuutta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'silloin sinulla on ilo Herrassa, ja hän antaa sinulle, mitä sinun sydämesi halajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Anna tiesi Herran haltuun ja turvaa häneen, kyllä hän sen tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Ja hän antaa sinun vanhurskautesi nousta niinkuin valkeuden ja sinun oikeutesi niinkuin keskipäivän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Hiljenny Herran edessä ja odota häntä. Älä vihastu siihen, jonka tie menestyy, mieheen, joka juonia punoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Herkeä vihasta ja heitä kiukku, älä kiivastu, se on vain pahaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Sillä pahat hävitetään, mutta jotka Herraa odottavat, ne perivät maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Hetkinen vielä, niin jumalatonta ei enää ole; kun hänen sijaansa katsot, on hän jo poissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Mutta nöyrät perivät maan ja iloitsevat suuresta rauhasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Jumalaton miettii vanhurskaalle pahaa ja kiristelee hänelle hampaitansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'mutta Herra nauraa hänelle, sillä hän näkee hänen päivänsä joutuvan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Jumalattomat paljastavat miekkansa ja jännittävät jousensa, kaataaksensa kurjan ja köyhän, teurastaaksensa ne, jotka ovat oikealla tiellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Mutta heidän miekkansa käy heidän omaan sydämeensä, ja heidän jousensa särkyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Vanhurskaan vähä vara on parempi kuin monen jumalattoman tavarain paljous.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Sillä jumalattomain käsivarret särjetään, mutta Herra tukee vanhurskaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Herra tuntee nuhteettomain päivät, ja heidän perintönsä pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Pahana aikana he eivät joudu häpeään, ja nälän päivinä heillä on kyllin syötävää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Sillä jumalattomat hukkuvat, ja Herran viholliset ovat kuin niittyjen koreus: he katoavat, katoavat niinkuin savu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Jumalaton ottaa lainan eikä maksa, mutta vanhurskas on armahtavainen ja antelias.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Sillä hänen siunaamansa perivät maan, mutta hänen kiroamansa hävitetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Herra vahvistaa sen miehen askeleet, jonka tie hänelle kelpaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Jos hän lankeaa, ei hän maahan sorru, sillä Herra tukee hänen kättänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Olen ollut nuori ja olen vanhaksi tullut, mutta en ole nähnyt vanhurskasta hyljättynä enkä hänen lastensa kerjäävän leipää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Aina hän on armahtavainen ja antaa lainaksi, ja hänen lapsensa ovat siunaukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Karta pahaa ja tee hyvää, niin sinä pysyt iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Sillä Herra rakastaa oikeutta eikä hylkää hurskaitansa; heidät varjellaan iankaikkisesti, mutta jumalattomain siemen hävitetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Vanhurskaat perivät maan ja asuvat siinä iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Vanhurskaan suu lausuu viisautta, ja hänen kielensä puhuu oikeuden sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Hänen Jumalansa laki on hänen sydämessään, hänen askeleensa eivät horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Jumalaton väijyy vanhurskasta ja etsii häntä tappaaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Mutta Herra ei jätä häntä hänen käsiinsä eikä tuomitse häntä syylliseksi, kun hänen asiansa on oikeudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Odota Herraa ja ota vaari hänen tiestänsä, niin hän korottaa sinut, ja sinä perit maan ja näet, kuinka jumalattomat hävitetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Minä näin jumalattoman, väkivaltaisen, rehevänä kuin viheriöivä puu, juurtunut paikoilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Mutta kun ohi kuljettiin, katso, ei häntä enää ollut; minä etsin häntä, vaan häntä ei löytynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Ota nuhteettomasta vaari, katso rehellistä: rauhan miehellä on tulevaisuus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'mutta luopuneet hukkuvat kaikki, ja jumalattomain tulevaisuus leikataan pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Mutta vanhurskasten pelastus tulee Herralta, hän on heidän linnansa ahdingon aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Herra auttaa heitä ja vapahtaa heidät, vapahtaa jumalattomista ja pelastaa heidät; sillä he turvaavat häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Daavidin virsi; syntiä tunnustettaessa. {38:2} Herra, älä rankaise minua vihassasi, älä kiivastuksessasi kurita minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, '{38:3} Sillä sinun nuolesi ovat uponneet minuun, sinun kätesi painaa minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, '{38:4} Ei ole lihassani tervettä paikkaa sinun vihastuksesi tähden eikä luissani rauhaa minun syntieni tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, '{38:5} Sillä minun pahat tekoni käyvät pääni ylitse, niinkuin raskas kuorma ne ovat minulle liian raskaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, '{38:6} Minun haavani haisevat ja märkivät minun hulluuteni tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, '{38:7} Minä käyn kumarassa, aivan kyyryssä, kuljen murheellisena kaiken päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, '{38:8} Sillä minun lanteeni ovat polttoa täynnä, eikä ole lihassani tervettä paikkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, '{38:9} Minä olen voimaton ja peräti runneltu, minä parun sydämeni tuskassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, '{38:10} Herra, sinun edessäsi on kaikki minun halajamiseni, eikä minun huokaukseni ole sinulta salassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, '{38:11} Minun sydämeni värisee, minun voimani on minusta luopunut, minun silmieni valo-sekin on minulta mennyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, '{38:12} Minun ystäväni ja läheiseni pysyvät syrjässä minun vitsauksestani, ja minun omaiseni seisovat kaukana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, '{38:13} Jotka minun henkeäni etsivät, ne virittävät pauloja; ja jotka minulle pahaa suovat, ne puhuvat turmion puheita ja miettivät petosta kaiket päivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, '{38:14} Mutta minä olen kuin kuuro, en mitään kuule, kuin mykkä, joka ei suutansa avaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, '{38:15} Minä olen kuin mies, joka ei mitään kuule ja jonka suussa ei vastausta ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, '{38:16} Sillä sinua, Herra, minä odotan, sinä vastaat, Herra, minun Jumalani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, '{38:17} Minä sanon: älkööt iloitko minusta, älkööt ylvästelkö minua vastaan, kun jalkani horjuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, '{38:18} Sillä minä olen kaatumaisillani, ja minun tuskani on aina edessäni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, '{38:19} sillä minä tunnustan pahat tekoni, murehdin syntieni tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, '{38:20} Mutta minun viholliseni elävät ja ovat väkevät, ja paljon on niitä, jotka minua syyttä vihaavat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, '{38:21} jotka hyvän pahalla palkitsevat ja vihaavat minua, koska minä hyvään pyrin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, '{38:22} Älä hylkää minua, Herra, minun Jumalani, älä ole kaukana minusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, '{38:23} Riennä avukseni, Herra, minun pelastukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Veisuunjohtajalle; Jedutunin tapaan; Daavidin virsi. {39:2} Minä sanoin: \"Minä pidän vaelluksestani vaarin, etten kielelläni syntiä tekisi. Minä pidän suustani vaarin ja suistan sen, niin kauan kuin jumalaton on minun edessäni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, '{39:3} Minä olin vaiti, olin ääneti, en puhunut siitä, mikä hyvä on; mutta minun tuskani yltyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, '{39:4} Minun sydämeni hehkui minun rinnassani; kun minä huokailin, syttyi minussa tuli, ja niin minä kielelläni puhuin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, '{39:5} Herra, opeta minua ajattelemaan loppuani, ja mikä minun päivieni mitta on, että ymmärtäisin, kuinka katoavainen minä olen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, '{39:6} Katso, kämmenen leveydeksi sinä teit minun päiväni, ja minun elämäni on sinun edessäsi niinkuin ei mitään. Vain tuulen henkäys ovat kaikki ihmiset, kuinka lujina seisokootkin. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, '{39:7} Varjona vain ihminen vaeltaa, turhaan vain he touhuavat, kokoavat, eivätkä tiedä, kuka ne saa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, '{39:8} Ja nyt, mitä minä odotan, Herra? Sinuun minä panen toivoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, '{39:9} Päästä minut kaikista synneistäni, älä pane minua houkkain pilkaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, '{39:10} Minä vaikenen enkä suutani avaa; sillä sinä sen teit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, '{39:11} Käännä vitsauksesi minusta pois, sillä minä menehdyn sinun kätesi kuritukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, '{39:12} Kun sinä ihmistä synnin tähden rangaistuksilla kuritat, kulutat sinä hänen kauneutensa niinkuin koinsyömän. Vain tuulen henkäys ovat kaikki ihmiset. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, '{39:13} Kuule minun rukoukseni, Herra, ota korviisi minun huutoni. Älä ole kuuro minun kyyneleilleni; sillä minä olen muukalainen sinun tykönäsi, vieras, niinkuin kaikki minun isänikin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, '{39:14} Käännä pois katseesi minusta, että minä ilostuisin, ennenkuin menen pois eikä minua enää ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Veisuunjohtajalle; Daavidin virsi. {40:2} Hartaasti minä odotin Herraa, ja hän kumartui minun puoleeni ja kuuli minun huutoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, '{40:3} Ja hän nosti minut ylös turmion kuopasta, lokaisesta liejusta, ja asetti minun jalkani kalliolle, hän vahvisti minun askeleeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, '{40:4} Hän antoi minun suuhuni uuden virren, kiitoslaulun Jumalallemme. Sen näkevät monet ja pelkäävät ja turvaavat Herraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, '{40:5} Autuas se mies, joka panee turvansa Herraan eikä käänny ylpeiden puoleen eikä niitten, jotka valheeseen eksyvät!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, '{40:6} Herra, minun Jumalani, suuret ovat sinun ihmetekosi ja sinun aivoituksesi meitä kohtaan. Ei ole ketään sinun vertaistasi. Niitä minä tahdon julistaa, niistä puhua, niitten paljous on suurempi, kuin luetella taidan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, '{40:7} Teurasuhriin ja ruokauhriin et sinä mielisty; minun korvani sinä avasit, polttouhria ja syntiuhria sinä et vaadi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, '{40:8} Silloin minä sanoin: \"Katso, minä tulen; kirjakääröön on kirjoitettu, mitä minun on tehtävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, '{40:9} Sinun tahtosi, minun Jumalani, minä teen mielelläni, ja sinun lakisi on minun sydämessäni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, '{40:10} Minä julistan vanhurskautta suuressa seurakunnassa; katso, en minä sulje huuliani. Sinä, Herra, sen tiedät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, '{40:11} Minä en peitä sinun vanhurskauttasi omaan sydämeeni, vaan puhun sinun uskollisuudestasi ja avustasi; minä en salaa sinun armoasi ja totuuttasi suurelta seurakunnalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, '{40:12} Sinä, Herra, älä sulje minulta laupeuttasi, sinun armosi ja totuutesi varjelkoon minua aina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, '{40:13} Sillä lukemattomat vaivat minua saartavat, minun rikkomukseni ovat ottaneet minut kiinni, niin etten nähdä taida; ne ovat useammat kuin pääni hiukset, ja rohkeus on minulta mennyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, '{40:14} Kelvatkoon sinulle, Herra, pelastaa minut, Herra, riennä minun avukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, '{40:15} Hävetkööt ja punastukoot kaikki, jotka minun henkeäni etsivät, hukuttaaksensa sen; peräytykööt ja tulkoot häpeään ne, jotka tahtovat minulle onnettomuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, '{40:16} Tyrmistykööt häpeästänsä ne, jotka minulle sanovat: \"Kas niin, kas niin!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, '{40:17} Iloitkoot ja riemuitkoot sinussa kaikki, jotka sinua etsivät; ne, jotka sinun autuuttasi rakastavat, sanokoot aina: \"Ylistetty olkoon Herra!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, '{40:18} Minä olen kurja ja köyhä, mutta Herra pitää minusta huolen. Sinä olet minun apuni ja pelastajani; minun Jumalani, älä viivy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Veisuunjohtajalle; Daavidin virsi. {41:2} Autuas se, joka vaivaista holhoo! Hänet Herra pelastaa pahana päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, '{41:3} Herra varjelee häntä ja pitää hänet hengissä, ja maassa ylistetään hänen onneansa, etkä sinä anna häntä alttiiksi hänen vihollistensa raivolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, '{41:4} Herra tukee häntä tautivuoteessa; hänen sairasvuoteensa sinä peräti muutat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, '{41:5} Minä sanoin: \"Herra, ole minulle armollinen, paranna minun sieluni, sillä minä olen tehnyt syntiä sinua vastaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, '{41:6} Minun viholliseni puhuvat minusta pahaa: \"Milloinka hän kuolee ja hänen nimensä katoaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, '{41:7} Ja jos joku tulee minua katsomaan, puhuu hän petosta; hänen sydämensä kerää häijyyttä itseensä, hän menee ulos kadulle ja purkaa sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, '{41:8} Kaikki minun vihamieheni minusta keskenään kuiskuttelevat ja hankitsevat minulle pahaa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, '{41:9} \"Jokin parantumaton paha on häneen tarttunut, ja siitä, missä hän makaa, hän ei enää nouse\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, '{41:10} Ystävänikin, johon minä luotin, joka minun leipääni söi, nostaa kantapäänsä minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, '{41:11} Mutta sinä, Herra, armahda minua ja auta minut ylös, pystyyn, niin minä sen heille maksan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, '{41:12} Siitä minä tiedän sinun mielistyneen minuun, ettei minun viholliseni saa minusta riemuita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, '{41:13} Minun nuhteettomuuteni tähden sinä minua tuet ja annat minun seisoa kasvojesi edessä ainiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, '{41:14} Kiitetty olkoon Herra, Israelin Jumala, iankaikkisesta iankaikkiseen. Amen. Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Veisuunjohtajalle; koorahilaisten mietevirsi. {42:2} Niinkuin peura halajaa vesipuroille, niin minun sieluni halajaa sinua, Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, '{42:3} Minun sieluni janoo Jumalaa, elävää Jumalaa. Milloin saan minä tulla Jumalan kasvojen eteen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, '{42:4} Kyyneleeni ovat minun ruokani päivin ja öin, kun minulle joka päivä sanotaan: \"Missä on sinun Jumalasi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, '{42:5} Näitä minä muistelen ja vuodatan sydämeni: minä kuljin väentungoksessa, astuin sen kanssa Jumalan huoneeseen riemun ja kiitoksen raikuessa juhlivasta joukosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, '{42:6} Miksi murehdit, minun sieluni, ja olet minussa niin levoton? Odota Jumalaa. Sillä vielä minä saan häntä kiittää hänen kasvojensa avusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, '{42:7} Minun Jumalani, minun sieluni on murheellinen minussa, sentähden minä muistan sinua Jordanin maalla, Hermonin kukkuloilla ja Misarin vuorella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, '{42:8} Sinun koskiesi pauhussa syvyys syvyydelle huutaa, kaikki sinun kuohusi ja aaltosi käyvät minun ylitseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, '{42:9} Päivällä Herra säätää armonsa, ja yöllä minä hänelle veisaan ja rukoilen elämäni Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, '{42:10} Minä sanon Jumalalle, kalliolleni: \"Miksi olet minut unhottanut? Miksi minun täytyy käydä murhepuvussa, vihollisen ahdistamana?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, '{42:11} Minun luitani jäytää, kun viholliseni minua häpäisevät, sanoen minulle kaiken päivää: \"Missä on sinun Jumalasi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, '{42:12} Miksi murehdit, minun sieluni, ja miksi olet minussa niin levoton? Odota Jumalaa. Sillä vielä minä saan kiittää häntä, minun kasvojeni apua, minun Jumalaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Auta minut oikeuteeni, Jumala, ja aja minun asiani armotonta kansaa vastaan. Päästä minut kavaloista ja vääristä ihmisistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Sillä sinä olet minun Jumalani, minun linnani. Miksi olet minut hyljännyt? Miksi minun täytyy käydä murhepuvussa, vihollisen ahdistamana?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Lähetä valkeutesi ja totuutesi. Ne minua johdattakoot, viekööt minut sinun pyhälle vuorellesi, sinun asuntoihisi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'että minä saisin tulla Jumalan alttarin eteen, Jumalan eteen, joka on minun iloni ja riemuni, ja kiittäisin kanteleilla sinua, Jumala, minun Jumalani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Miksi murehdit, minun sieluni, ja miksi olet minussa niin levoton? Odota Jumalaa. Sillä vielä minä saan kiittää häntä, minun kasvojeni apua, minun Jumalaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Veisuunjohtajalle; koorahilaisten mietevirsi. {44:2} Jumala, me olemme omin korvin kuulleet, meidän isämme ovat meille kertoneet, minkä teon sinä teit heidän päivinänsä, muinaisina päivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, '{44:3} Sinä karkoitit kädelläsi pakanat, mutta heidät sinä istutit, sinä hävitit kansat, mutta heidät sinä levitit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, '{44:4} Sillä eivät he miekallansa valloittaneet maata, eikä heidän käsivartensa heitä auttanut, vaan sinun oikea kätesi, sinun käsivartesi ja sinun kasvojesi valkeus, koska sinä olit heihin mielistynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, '{44:5} Sinä, Jumala, sinä olet minun kuninkaani, toimita Jaakobille apu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, '{44:6} Sinun avullasi me syöksemme ahdistajamme maahan, sinun nimessäsi me tallaamme vastustajamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, '{44:7} Sillä en minä jouseeni luota, eikä miekkani minua auta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, '{44:8} vaan sinä pelastat meidät vihollisistamme, ja saatat vihamiehemme häpeään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, '{44:9} Jumala on meidän kerskauksemme kaikkina päivinä, ja sinun nimeäsi me ylistämme iankaikkisesti. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, '{44:10} Kuitenkin sinä meidät hylkäsit ja saatoit meidät häpeään, et lähtenyt sotaan meidän joukkojemme kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, '{44:11} Sinä käänsit meidät vihollista pakoon, ja meidän vihamiehemme ryöstivät saalista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, '{44:12} Sinä annoit meidät syötäviksi kuin lampaat, ja hajotit meidät pakanain sekaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, '{44:13} Sinä myit kansasi halvasta etkä heidän hinnastaan paljoa hyötynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, '{44:14} Sinä annat meidät naapuriemme häväistäviksi, ympärillämme asuvaisten pilkaksi ja ivaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, '{44:15} Sinä saatat meidät sananparreksi pakanoille, pään pudistukseksi kansoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, '{44:16} Joka päivä on häväistykseni minun edessäni, ja kasvojeni häpeä peittää minut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, '{44:17} herjaajan ja pilkkaajan puheen tähden, vihollisen ja kostonhimoisen katseitten tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, '{44:18} Tämä kaikki on meitä kohdannut, vaikka emme ole sinua unhottaneet emmekä sinun liittoasi rikkoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, '{44:19} Ei ole meidän sydämemme sinusta luopunut, eivät meidän askeleemme sinun polultasi poikenneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, '{44:20} Kuitenkin sinä runtelit meidät aavikkosutten asuinsijoilla ja peitit meidät synkeydellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, '{44:21} Jos me olisimme unhottaneet Jumalamme nimen ja ojentaneet kätemme vieraan jumalan puoleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, '{44:22} eikö Jumala olisi sitä tutkituksi saanut, sillä hän tuntee sydämen salaisuudet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, '{44:23} Ei, vaan sinun tähtesi meitä surmataan kaiken päivää, meitä pidetään teuraslampaina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, '{44:24} Heräjä, miksi nukut, Herra? Nouse, älä iäksi hylkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, '{44:25} Miksi peität kasvosi, unhotat meidän kurjuutemme ja ahdistuksemme?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, '{44:26} Sillä meidän sielumme on vaipunut tomuun, meidän ruumiimme painunut maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, '{44:27} Nouse, auta meitä ja lunasta meidät armosi tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Veisuunjohtajalle; veisataan kuin: \"Liljat\"; koorahilaisten mietevirsi; laulu rakkaudesta. {45:2} Minun sydämeni tulvii ihania sanoja; minä lausun: kuninkaasta on minun lauluni, minun kieleni on kerkeän kirjurin kynä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, '{45:3} Sinä olet ihmislapsista ihanin, suloisuus on vuodatettu sinun huulillesi, sentähden Jumala siunaa sinua iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, '{45:4} Vyötä miekka vyöllesi, sinä sankari, vyöttäydy kunniaasi ja korkeuteesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, '{45:5} Ole onnekas korkeudessasi. Nouse sotavaunuihisi totuuden, nöyryyden ja vanhurskauden puolesta, ja oikea kätesi opettakoon sinulle peljättäviä tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, '{45:6} Sinun nuolesi ovat terävät, kansat kaatuvat sinun allesi; kuninkaan vihollisten sydämet lävistetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, '{45:7} Jumala, sinun valtaistuimesi pysyy aina ja iankaikkisesti; sinun valtakuntasi valtikka on oikeuden valtikka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, '{45:8} Sinä rakastat vanhurskautta ja vihaat vääryyttä; sentähden on Jumala, sinun Jumalasi, voidellut sinua iloöljyllä enemmän kuin sinun osaveljiäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, '{45:9} Mirhaa, aloeta ja kassiaa tuoksuvat kaikki sinun vaatteesi, kanteleet helisevät sinun iloksesi norsunluisista palatseista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, '{45:10} Kuningasten tyttäriä on sinun kaunistuksenasi, kuningatar seisoo sinun oikealla puolellasi, Oofirin kullassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, '{45:11} Kuule, tytär, katso ja kallista korvasi, unhota kansasi ja isäsi huone,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, '{45:12} ja saakoon kuningas halun sinun kauneuteesi, sillä hän on sinun herrasi. Kumarra häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, '{45:13} Tytär Tyyro ja kansan rikkaimmat etsivät lahjoillaan sinun suosiotasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, '{45:14} Ylen ihana on kuninkaan tytär sisäkammiossa, kultakudosta on hänen pukunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, '{45:15} Kirjailluissa vaatteissa hänet saatetaan kuninkaan tykö. Neitsyet seuraavat häntä, hänen ystävättärensä tuodaan sinun tykösi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, '{45:16} Ilolla ja riemulla heitä saatetaan, he astuvat kuninkaan palatsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, '{45:17} Sinun poikasi tulkoot sinun isiesi sijaan; aseta heidät ruhtinaiksi kaikkeen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, '{45:18} Minä teen sinun nimesi kuuluksi suvusta sukuun; sentähden kansat sinua ylistävät aina ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Veisuunjohtajalle; koorahilaisten laulu, korkeassa äänialassa. {46:2} Jumala on meidän turvamme ja väkevyytemme, apumme hädässä aivan vahva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, '{46:3} Sentähden emme pelkää, vaikka maa järkkyisi ja vuoret meren pohjaan vajoaisivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, '{46:4} vaikka sen vedet pauhaisivat ja kuohuisivat ja vuoret vapisisivat sen raivosta. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, '{46:5} Virta lähteinensä ilahuttaa Jumalan kaupungin, Korkeimman pyhät asunnot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, '{46:6} Jumala on sen keskellä, ei se horju, Jumala auttaa sitä jo aamun koittaessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, '{46:7} Pakanat pauhaavat, valtakunnat horjuvat; kun hän jylisee, huojuu maa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, '{46:8} Herra Sebaot on meidän kanssamme, Jaakobin Jumala on meidän linnamme. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, '{46:9} Tulkaa, katsokaa Herran töitä, hänen, joka tekee hämmästyttäviä tekoja maan päällä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, '{46:10} hän lopettaa sodat maan ääriin saakka, hän särkee jousen, taittaa keihään, polttaa sotavaunut tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, '{46:11} \"Heretkää ja tietäkää, että minä olen Jumala, korkea kansojen keskellä, korkea maan päällä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, '{46:12} Herra Sebaot on meidän kanssamme, Jaakobin Jumala on meidän linnamme. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Veisuunjohtajalle; koorahilaisten virsi. {47:2} Paukuttakaa käsiänne, kaikki kansat, kohottakaa Jumalalle riemuhuuto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, '{47:3} Sillä Herra on korkein, peljättävä, kaiken maan suuri kuningas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, '{47:4} Hän kukistaa kansat meidän allemme ja kansakunnat jalkaimme alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, '{47:5} Hän on valinnut meille perintömaamme, joka on Jaakobin, hänen rakkaansa, kunnia. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, '{47:6} Jumala astuu ylös riemun raikuessa, Herra pasunain pauhatessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, '{47:7} Veisatkaa Jumalalle, veisatkaa, veisatkaa meidän kuninkaallemme, veisatkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, '{47:8} Sillä Jumala on kaiken maan kuningas. Veisatkaa hänelle virsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, '{47:9} Jumala on kansojen kuningas, Jumala istuu pyhällä istuimellansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, '{47:10} Kansojen päämiehet kokoontuvat Aabrahamin Jumalan kansaksi. Sillä maan kilvet ovat Jumalan; hän on ylen korkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Laulu, koorahilaisten virsi. {48:2} Suuri on Herra ja korkeasti ylistettävä meidän Jumalamme kaupungissa, pyhällä vuorellansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, '{48:3} Kauniina kohoaa, kaiken maan ilona, pohjan puolella Siionin vuori, suuren kuninkaan kaupunki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, '{48:4} Jumala on sen linnoissa turvaksi tunnettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, '{48:5} Sillä katso, kuninkaat kokoontuivat, hyökkäsivät yhdessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, '{48:6} Mutta he näkivät sen, hämmästyivät, peljästyivät ja pakenivat pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, '{48:7} Vavistus valtasi heidät siellä, tuska niinkuin synnyttäväisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, '{48:8} Itätuulella sinä särjet Tarsiin-laivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, '{48:9} Niinkuin me olimme kuulleet, niin me sen nyt näimme Herran Sebaotin kaupungissa, meidän Jumalamme kaupungissa: Jumala pitää sen lujana iankaikkisesti. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, '{48:10} Jumala, me tutkistelemme sinun armoasi sinun temppelissäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, '{48:11} Jumala, niinkuin sinun nimesi, niin ulottuu sinun ylistyksesi maan ääriin saakka; sinun oikea kätesi on vanhurskautta täynnä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, '{48:12} Siionin vuori iloitsee, Juudan tyttäret riemuitsevat sinun tuomioistasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, '{48:13} Kiertäkää Siion, käykää sen ympäri, lukekaa sen tornit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, '{48:14} Tarkatkaa sen muurit, kulkekaa sen linnat, kertoaksenne niistä tulevalle polvelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, '{48:15} Sillä tämä on Jumala, meidän Jumalamme, aina ja iankaikkisesti; hän johdattaa meitä kuolemaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Veisuunjohtajalle; koorahilaisten virsi. {49:2} Kuulkaa tämä, kaikki kansat, ottakaa korviinne, maailman asukkaat kaikki,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, '{49:3} sekä alhaiset että ylhäiset, niin rikkaat kuin köyhät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, '{49:4} Minun suuni puhuu viisautta, minun sydämeni ajatus on ymmärrystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, '{49:5} Minä kallistan korvani kuulemaan mietelauseita, minä selitän ongelmani kannelta soittaen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, '{49:6} Miksi minä pelkäisin pahoina päivinä, kun minun vainoojani vääryys piirittää minut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, '{49:7} He luottavat tavaroihinsa ja kerskaavat suuresta rikkaudestaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, '{49:8} Kukaan ei voi veljeänsä lunastaa eikä hänestä Jumalalle sovitusta maksaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, '{49:9} Sillä hänen sielunsa lunastus on ylen kallis ja jää iäti suorittamatta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, '{49:10} että hän saisi elää iankaikkisesti eikä kuolemaa näkisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, '{49:11} Vaan hänen täytyy nähdä, että viisaat kuolevat, että tyhmät ja järjettömät myös hukkuvat ja jättävät toisille tavaransa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, '{49:12} He luulevat, että heidän huoneensa pysyvät iäti ja heidän asuntonsa polvesta polveen; he nimittävät maatiloja nimensä mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, '{49:13} Mutta ihminen, mahtavinkaan, ei ole pysyväinen: hän on verrattava eläimiin, jotka hukkuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, '{49:14} Näin käy niiden, jotka itseensä luottavat, ja heidän perässään niiden, jotka mielistyvät heidän puheisiinsa. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, '{49:15} Kuin lammaslauma heidät viedään tuonelaan, kuolema heitä kaitsee, jo huomenna oikeamieliset astuvat heidän ylitsensä; tuonela kalvaa heidän hahmoansa, eikä heillä ole asuntoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, '{49:16} Mutta minun sieluni Jumala lunastaa tuonelan vallasta, sillä hän ottaa minut huomaansa. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, '{49:17} Älä pelkää, jos joku rikastuu, jos hänen talonsa komeus karttuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, '{49:18} Sillä kuollessaan ei hän ota mitään mukaansa, eikä hänen komeutensa astu alas hänen jäljessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, '{49:19} Vaikka hän eläissänsä kiittää itseään siunatuksi, vaikka sinua ylistetään, kun vietät hyviä päiviä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, '{49:20} täytyy sinun mennä isiesi suvun tykö, jotka eivät ikinä enää valoa näe.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, '{49:21} Ihminen, mahtavinkin, on ymmärrystä vailla, hän on verrattava eläimiin, jotka hukkuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Aasafin virsi. Jumala, Herra Jumala, puhuu ja kutsuu maan auringon noususta hamaan sen laskuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Siionista, jonka kauneus on täydellinen, Jumala ilmestyy kirkkaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Meidän Jumalamme tulee eikä vaikene, hänen edellänsä käy kuluttava tuli ja hänen ympärillänsä väkevä myrsky.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Hän kutsuu taivaat ylhäältä ja maan, tuomitakseen kansansa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '\"Kootkaa minun eteeni minun hurskaani, jotka uhreja uhraten ovat tehneet minun kanssani liiton\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Ja taivaat julistavat hänen vanhurskauttansa, sillä Jumala on tuomari. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, '\"Kuule, minun kansani, minä puhun; kuule, Israel, minä todistan sinua vastaan. Minä olen Jumala, sinun Jumalasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'En minä sinun teurasuhreistasi sinua nuhtele, ja sinun polttouhrisi ovat aina minun edessäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'En minä ota härkiä sinun talostasi enkä kauriita sinun tarhoistasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Sillä minun ovat kaikki metsän eläimet ja tuhansien vuorten karjat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Minä tunnen kaikki vuorten linnut, ja kaikki, mikä kedolla liikkuu, on minun edessäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Jos minä isoaisin, en minä sitä sinulle sanoisi; sillä minun on maanpiiri ja kaikki, mitä siinä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Minäkö söisin härkien lihaa tai joisin kauristen verta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Uhraa Jumalalle kiitos ja täytä lupauksesi Korkeimmalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Ja avuksesi huuda minua hädän päivänä, niin minä tahdon auttaa sinua, ja sinun pitää kunnioittaman minua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Mutta jumalattomalle Jumala sanoo: \"Mikä sinä olet puhumaan minun käskyistäni ja ottamaan minun liittoni suuhusi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Sinä, joka vihaat kuritusta ja heität minun sanani selkäsi taakse!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Jos sinä näet varkaan, niin sinä mielistyt häneen, ja sinä pidät yhtä avionrikkojain kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Sinä päästät suusi puhumaan pahaa, ja sinun kielesi punoo petosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Sinä istut ja puhut veljeäsi vastaan, sinä panettelet äitisi poikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Näitä sinä teet, ja minäkö olisin vaiti? Luuletko, että minä olen sinun kaltaisesi? Minä nuhtelen sinua ja asetan nämä sinun silmäisi eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Ymmärtäkää tämä te, jotka Jumalan unhotatte, etten minä raatelisi, eikä olisi pelastajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Joka kiitosta uhraa, se kunnioittaa minua; joka ottaa tiestänsä vaarin, sen minä annan nähdä Jumalan autuuden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Veisuunjohtajalle; Daavidin virsi,{51:2} kun profeetta Naatan tuli hänen luokseen, sen jälkeen kuin hän oli yhtynyt Batsebaan. {51:3} Jumala, ole minulle armollinen hyvyytesi tähden; pyyhi pois minun syntini suuren laupeutesi tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, '{51:4} Pese minut puhtaaksi rikoksestani, puhdista minut synnistäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, '{51:5} Sillä minä tunnen rikokseni, ja minun syntini on aina minun edessäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, '{51:6} Sinua ainoata vastaan minä olen syntiä tehnyt, tehnyt sitä, mikä on pahaa sinun silmissäsi; mutta sinä olet oikea puheessasi ja puhdas tuomitessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, '{51:7} Katso, minä olen synnissä syntynyt, ja äitini on minut synnissä siittänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, '{51:8} Katso, totuutta sinä tahdot salatuimpaan saakka, ja sisimmässäni sinä ilmoitat minulle viisauden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, '{51:9} Puhdista minut isopilla, että minä puhdistuisin, pese minut, että minä lunta valkeammaksi tulisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, '{51:10} Anna minun kuulla iloa ja riemua, että ihastuisivat ne luut, jotka särkenyt olet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, '{51:11} Peitä kasvosi näkemästä minun syntejäni, pyyhi pois kaikki minun pahat tekoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, '{51:12} Jumala, luo minuun puhdas sydän ja anna minulle uusi, vahva henki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, '{51:13} Älä heitä minua pois kasvojesi edestä, äläkä ota minulta pois Pyhää Henkeäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, '{51:14} Anna minulle jälleen autuutesi ilo, ja tue minua alttiuden hengellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, '{51:15} Minä tahdon opettaa väärille sinun tiesi, että syntiset sinun tykösi palajaisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, '{51:16} Päästä minut verenvioista, Jumala, minun autuuteni Jumala, että minun kieleni riemuitsisi sinun vanhurskaudestasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, '{51:17} Herra, avaa minun huuleni, että minun suuni julistaisi sinun kiitostasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, '{51:18} Sillä ei sinulle kelpaa teurasuhri, sen minä kyllä antaisin; polttouhri ei ole sinulle mieleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, '{51:19} Jumalalle kelpaava uhri on särjetty henki; särjettyä ja murtunutta sydäntä et sinä, Jumala, hylkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, '{51:20} Osoita armossasi hyvyyttä Siionille, rakenna Jerusalemin muurit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, '{51:21} Silloin sinulle kelpaavat oikeat teurasuhrit, polttouhrit ja kokonaisuhrit; silloin uhrataan härkiä sinun alttarillasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Veisuunjohtajalle; Daavidin mietevirsi,{52:2} kun edomilainen Dooeg tuli ja ilmoitti Saulille, sanoen hänelle: \"Daavid on mennyt Ahimelekin taloon\". {52:3} Miksi kerskaat pahuudestasi, sinä väkivaltainen? Jumalan armo pysyy alati.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, '{52:4} Sinun kielesi punoo turmiota, se on kuin terävä partaveitsi, sinä petoksen tekijä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, '{52:5} Sinä rakastat pahaa etkä hyvää, sinä puhut valhetta etkä totta. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, '{52:6} Sinä rakastat kaikkia surman sanoja, sinä kavala kieli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, '{52:7} Sentähden myös Jumala kukistaa sinut ainiaaksi, hän tarttuu sinuun ja raastaa sinut majastasi, repäisee sinut juurinesi elävien maasta. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, '{52:8} Ja vanhurskaat näkevät sen ja pelkäävät, ja he nauravat häntä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, '{52:9} \"Katso, siinä on mies, joka ei pitänyt Jumalaa turvanansa, vaan luotti suureen rikkauteensa ja röyhkeili häijyydessänsä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, '{52:10} Mutta minä olen kuin viheriöitsevä öljypuu Jumalan huoneessa, minä turvaan Jumalan armoon aina ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, '{52:11} Minä kiitän sinua iäti, että sen teit, ja minä odotan sinun hurskaittesi edessä sinun nimeäsi, sillä se on hyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Veisuunjohtajalle; veisataan kuin: \"Sairaus\"; Daavidin mietevirsi. {53:2} Hullu sanoo sydämessänsä: \"Ei ole Jumalaa\". Turmiollinen ja iljettävä on heidän väärä menonsa; ei ole ketään, joka tekee sitä, mikä hyvä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, '{53:3} Jumala katsoo taivaasta ihmislapsiin nähdäksensä, onko ketään ymmärtäväistä, ketään, joka etsii Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, '{53:4} Mutta kaikki he ovat poikenneet pois, kaikki tyynni kelvottomiksi käyneet; ei ole ketään, joka tekee sitä, mikä hyvä on, ei yhden yhtäkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, '{53:5} Eivätkö he mitään käsitä, nuo väärintekijät, jotka saavat leipänsä syömällä minun kansaani, eivätkä avuksensa huuda Jumalaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, '{53:6} Siinä heidät valtaa kauhu, missä ei kauhistavaa ole; sillä Jumala hajottaa niiden luut, jotka sinua saartavat. Sinä saatat heidät häpeään, sillä Jumala hylkää heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, '{53:7} Oi, että Israelille tulisi pelastus Siionista! Kun Jumala kääntää kansansa kohtalon, silloin Jaakob riemuitsee, Israel iloitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Veisuunjohtajalle; kielisoittimilla; Daavidin mietevirsi,{54:2} kun siifiläiset tulivat ja sanoivat Saulille: \"Daavid piileskelee meidän luonamme\". {54:3} Jumala, pelasta minut nimesi voimalla, aja minun asiani väkevyydelläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, '{54:4} Jumala, kuule minun rukoukseni, ota korviisi minun suuni sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, '{54:5} Sillä muukalaiset nousevat minua vastaan, ja väkivaltaiset väijyvät minun henkeäni, eivät he pidä Jumalaa silmäinsä edessä. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, '{54:6} Katso, Jumala on minun auttajani, Herra on minun sieluni tuki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, '{54:7} Kohdatkoon paha minun vihamiehiäni, hävitä heidät uskollisuudessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, '{54:8} Niin minä alttiisti sinulle uhraan, minä ylistän sinun nimeäsi, Herra, sillä se on hyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, '{54:9} Sillä hän pelastaa minut kaikesta hädästä, ja minun silmäni saa mielikseen katsella vihollisiani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Veisuunjohtajalle; kielisoittimilla; Daavidin mietevirsi. {55:2} Jumala, ota korviisi minun rukoukseni, älä kätkeydy, kun minä armoa anon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, '{55:3} Kuuntele minua ja vastaa minulle. Minä kuljen rauhatonna murheessani ja huokaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, '{55:4} koska vihamies huutaa ja jumalaton ahdistaa; sillä he vyöryttävät minun päälleni turmiota ja vihassa minua vainoavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, '{55:5} Sydämeni minun rinnassani vapisee, kuoleman kauhut lankeavat minun päälleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, '{55:6} Pelko ja vavistus valtaa minut, pöyristys peittää minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, '{55:7} Ja minä sanon: Olisipa minulla siivet kuin kyyhkysellä, niin minä lentäisin pois ja pääsisin lepoon!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, '{55:8} Katso, minä pakenisin kauas ja yöpyisin erämaassa. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, '{55:9} Minä rientäisin pakopaikkaani rajuilman ja myrskyn alta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, '{55:10} Sekoita, Herra, tee eripuraiseksi heidän kielensä, sillä minä näen väkivaltaa ja riitaa kaupungissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, '{55:11} Yötä päivää he sitä kiertävät, sen muureja pitkin, vääryys ja vaiva on sen keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, '{55:12} Sen keskellä on turmio, sorto ja petos ei väisty sen torilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, '{55:13} Sillä ei minua herjaa vihollinen-sen minä kestäisin-eikä minua vastaan ylvästele minun vihamieheni-hänen edestään minä voisin lymytä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, '{55:14} vaan sinä, minun vertaiseni, sinä, minun ystäväni ja uskottuni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, '{55:15} jonka kanssa me elimme suloisessa sovussa, yhdessä vaelsimme Jumalan huoneeseen juhlakansan kohinassa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, '{55:16} Karatkoon kuolema heidän kimppuunsa, menkööt he elävältä alas tuonelaan, sillä heidän asunnoissansa ja sydämissänsä vallitsee sula pahuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, '{55:17} Mutta minä huudan Jumalaa, ja Herra pelastaa minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, '{55:18} Illoin, aamuin ja keskipäivällä minä valitan ja huokaan, ja hän kuulee minun ääneni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, '{55:19} Hän päästää minun sieluni heistä rauhaan, etteivät he minua saavuta; sillä paljon on niitä, jotka ovat minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, '{55:20} Jumala kuulee sen ja vastaa heille, hän, joka hallitsee hamasta muinaisuudesta. Sela. Sillä he eivät muuta mieltänsä eivätkä pelkää Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, '{55:21} Tuo mies käy käsiksi niihin, jotka hänen kanssaan rauhassa elävät, hän rikkoo liittonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, '{55:22} Hänen suunsa on voita sulavampi, mutta hänellä on sota mielessä; hänen sanansa ovat öljyä lauhkeammat, mutta ovat kuin paljastetut miekat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, '{55:23} Heitä murheesi Herran huomaan, hän pitää sinusta huolen, ei hän salli vanhurskaan ikinä horjua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, '{55:24} Mutta heidät sinä, Jumala, syökset tuonelan syvyyteen; murhamiehet ja petturit eivät pääse puoleen ikäänsä. Mutta minä turvaan sinuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Veisuunjohtajalle; veisataan kuin: \"Mykkä kyyhkynen kaukaisessa maassa\". Daavidin laulu, kun filistealaiset ottivat hänet kiinni Gatissa. {56:2} Jumala, ole minulle armollinen, sillä ihmiset minua polkevat, joka päivä he sotivat minua vastaan, ahdistavat minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, '{56:3} Joka päivä minun vihamieheni minua polkevat; sillä paljon on niitä, jotka ylpeästi sotivat minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, '{56:4} Mutta sinä päivänä, jota minä pelkään, minä turvaan sinuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, '{56:5} Jumalaan minä luotan ja ylistän hänen sanaansa, Jumalaan minä turvaan enkä pelkää. Mitä liha minulle tekisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, '{56:6} Joka päivä he vääntelevät minun sanojani, kaikki heidän ajatuksensa tarkoittavat minulle pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, '{56:7} He ahdistavat, he väijyvät minua, he vakoilevat minun askeleitani, sillä he tavoittavat minun henkeäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, '{56:8} Hekö pahuudessaan pelastuisivat? Syökse, Jumala, vihassasi kansat maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, '{56:9} Sinä olet lukenut minun pakolaispäiväni; pane leiliisi minun kyyneleeni, ovathan ne sinun kirjassasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, '{56:10} Kerran väistyvät minun viholliseni, sinä päivänä, jona minä huudan; minä tiedän, että Jumala on minun puolellani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, '{56:11} Jumalaan minä luotan ja ylistän hänen sanaansa, Herraan minä luotan ja ylistän hänen sanaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, '{56:12} Jumalaan minä turvaan enkä pelkää. Mitä ihminen minulle tekisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, '{56:13} Minulla on lupaus täytettävänä sinulle, Jumala; minä maksan sinulle kiitosuhrit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, '{56:14} Sillä sinä pelastit minun sieluni kuolemasta, minun jalkani kompastumasta, että minä vaeltaisin Jumalan edessä, eläväin valkeudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Veisuunjohtajalle; veisataan kuin: \"Älä turmele\"; Daavidin laulu, kun hän pakeni Saulia luolaan. {57:2} Jumala, ole minulle armollinen, ole minulle armollinen; sillä sinuun minun sieluni turvaa. Minä turvaan sinun siipiesi suojaan, kunnes onnettomuudet ovat ohitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, '{57:3} Minä huudan Jumalaa, Korkeinta, avukseni, Jumalaa, joka vie minun asiani päätökseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, '{57:4} Hän lähettää taivaasta minulle pelastuksen, kun minua herjaavat minun polkijani. Sela. Jumala lähettää armonsa ja totuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, '{57:5} Minun sieluni on jalopeurain keskellä, minun täytyy maata tultasuitsevaisten seassa, ihmisten, joiden hampaat ovat keihäitä ja nuolia ja joiden kieli on terävä miekka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, '{57:6} Korota itsesi yli taivasten, Jumala, ja kunniasi yli kaiken maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, '{57:7} Verkon he virittivät minun askelteni tielle, painoivat minun sieluni maahan, kaivoivat eteeni kuopan, mutta itse he siihen suistuivat. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, '{57:8} Jumala, minun sydämeni on valmis, minun sydämeni on valmis: minä tahdon veisata ja soittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, '{57:9} Heräjä, minun sieluni; heräjä, harppu ja kannel. Minä tahdon herättää aamuruskon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, '{57:10} Herra, sinua minä kiitän kansojen joukossa, veisaan sinun kiitostasi kansakuntien keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, '{57:11} Sillä suuri on sinun armosi ja ulottuu hamaan taivaisiin, ja sinun totuutesi pilviin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, '{57:12} Korota itsesi yli taivasten, Jumala, ja kunniasi yli kaiken maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Veisuunjohtajalle; veisataan kuin: \"Älä turmele\"; Daavidin laulu. {58:2} Totisesti, onko vanhurskaus mykkä, ja te puhutte? Tekö tuomitsette oikein, te ihmislapset?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, '{58:3} Ei, vaan te hankitsette sydämessänne vääryyttä, teidän kätenne käyttävät maassa väkivallan vaakaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, '{58:4} Luopuneita ovat jumalattomat äidin kohdusta asti, eksyneitä valhettelijat hamasta äidin helmasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, '{58:5} Heidän myrkkynsä on niinkuin käärmeen myrkky, he ovat kuin kuuro kyy, joka korvansa tukitsee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, '{58:6} ettei se kuulisi lumoojan ääntä, taitavan taikojan loitsuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, '{58:7} Jumala, särje hampaat heidän suustansa, Herra, murra nuorten jalopeurain raateluhampaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, '{58:8} Haihtukoot he tyhjiin niinkuin vesi, joka valuu kuiviin. Kun he ampuvat nuolensa, olkoot ne kuin kärjettömät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, '{58:9} Olkoot he niinkuin etana, joka sulaa mataessaan, niinkuin vaimon keskoiset, jotka eivät aurinkoa näe.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, '{58:10} Ennenkuin teidän patanne tuntevat tulen altansa orjantappuroista, hän myrskyllään puhaltaa pois kaiken, niin raa\'an kuin kypsänkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, '{58:11} Vanhurskas iloitsee, kun hän näkee koston, hän pesee jalkansa jumalattoman veressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, '{58:12} Silloin ihmiset sanovat: \"Totisesti, vanhurskaalla on hedelmä; totisesti, on Jumala, joka tuomitsee maan päällä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Veisuunjohtajalle; veisataan kuin: \"Älä turmele\"; Daavidin laulu, kun Saul lähetti vartioimaan hänen taloansa, tappaakseen hänet. {59:2} Jumalani, pelasta minut vihollisistani, suojele minua niiltä, jotka nousevat minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, '{59:3} Pelasta minut pahantekijöistä, vapahda minut murhamiehistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, '{59:4} Sillä katso, he väijyvät minun henkeäni; julmurit kokoontuvat minua vastaan, vaikka en ole rikkonut enkä syntiä tehnyt, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, '{59:5} Ilman minun syytäni he juoksevat ja hankkiutuvat; heräjä, käy minua kohtaamaan ja katso.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, '{59:6} Ja sinä, Herra, Jumala Sebaot, Israelin Jumala, heräjä kostamaan kaikille pakanoille. Älä säästä ketään uskotonta väärintekijää. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, '{59:7} He tulevat ehtoolla, ulvovat kuin koirat ja kiertävät kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, '{59:8} Katso, he purkavat suustaan sisuansa, miekat ovat heidän huulillansa, sillä: \"Kuka sen kuulee?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, '{59:9} Mutta sinä, Herra, naurat heille, sinä pidät kaikkia pakanoita pilkkanasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, '{59:10} Sinä, minun väkevyyteni, sinusta minä otan vaarin, sillä Jumala on minun linnani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, '{59:11} Minun armollinen Jumalani käy minua kohden, Jumala antaa minun nähdä iloni vihollisistani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, '{59:12} Älä heitä tapa, ettei minun kansani sitä unhottaisi. Saata voimallasi heidät harhailemaan ja syökse heidät maahan, Herra, meidän kilpemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, '{59:13} Minkä he huulillaan puhuvat, sen he suullaan syntiä tekevät. Joutukoot he ylpeydessään kiinni kirousten ja valheiden tähden, joita he puhuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, '{59:14} Hävitä heidät vihassasi, hävitä olemattomiin, ja tietäkööt he, että Jumala hallitsee Jaakobissa, maan ääriin saakka. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, '{59:15} He tulevat ehtoolla, ulvovat kuin koirat ja kiertävät kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, '{59:16} He harhailevat ruuan haussa; elleivät tule ravituiksi, he murisevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, '{59:17} Mutta minä veisaan sinun väkevyydestäsi ja riemuitsen aamulla sinun armostasi, sillä sinä olet minun linnani ja pakopaikkani minun hätäni päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, '{59:18} Sinä, minun väkevyyteni, sinulle minä veisaan kiitosta, sillä Jumala on minun linnani ja minun armollinen Jumalani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Veisuunjohtajalle; veisataan kuin: \"Todistuksen lilja\"; Daavidin laulu, opetettavaksi,{60:2} kun hän taisteli Mesopotamian aramilaisia ja Sooban aramilaisia vastaan ja Jooab palasi ja voitti Suolalaaksossa edomilaiset, kaksitoista tuhatta miestä. {60:3} Jumala, sinä hylkäsit meidät, sinä hajotit meidät ja olit vihastunut. Auta meidät ennallemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, '{60:4} Sinä saatoit maan järkkymään ja halkeilemaan, korjaa sen repeämät, sillä se horjuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, '{60:5} Sinä olet antanut kansasi nähdä kovia päiviä; olet juottanut meitä päihdyttävällä viinillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, '{60:6} Mutta sinä olet antanut lipun niille, jotka sinua pelkäävät, että he kokoontuisivat sen turviin, jousta pakoon. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, '{60:7} Että sinun rakkaasi pelastetuiksi tulisivat, auta oikealla kädelläsi ja vastaa meille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, '{60:8} Jumala on puhunut pyhäkössänsä! Minä riemuitsen, minä jaan Sikemin ja mittaan Sukkotin laakson.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, '{60:9} Minun on Gilead, minun on Manasse, Efraim on minun pääni suojus, Juuda minun valtikkani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, '{60:10} Mooab on minun pesuastiani, Edomiin minä viskaan kenkäni; Filistea, nosta minulle riemuhuuto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, '{60:11} Kuka vie minut varustettuun kaupunkiin? Kuka saattaa minut Edomiin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, '{60:12} Etkö sinä, Jumala, hyljännyt meitä? Et lähtenyt, Jumala, meidän sotajoukkojemme kanssa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, '{60:13} Anna meille apu ahdistajaa vastaan, sillä turha on ihmisten apu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, '{60:14} Jumalan voimalla me teemme väkeviä tekoja; hän tallaa meidän vihollisemme maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Veisuunjohtajalle; kielisoittimilla; Daavidin virsi. {61:2} Kuule, Jumala, minun huutoni, huomaa minun rukoukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, '{61:3} Maan ääristä minä sinua huudan, kun sydämeni nääntyy. Saata minut kalliolle, joka on minulle liian korkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, '{61:4} Sillä sinä olet minun turvapaikkani, vahva torni vihollista vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, '{61:5} Suo minun asua sinun majassasi iankaikkisesti, turvautua sinun siipiesi suojaan. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, '{61:6} Sillä sinä, Jumala, kuulet minun lupaukseni, sinä annat perinnön niille, jotka sinun nimeäsi pelkäävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, '{61:7} Sinä lisäät kuninkaalle päiviä päiviin; hänen vuotensa jatkukoot polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, '{61:8} Hallitkoon hän iankaikkisesti Jumalan kasvojen edessä; säädä armo ja totuus häntä varjelemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, '{61:9} Niin minä veisaan iankaikkisesti sinun nimesi kiitosta, täytän lupaukseni päivästä päivään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Veisuunjohtajalle; Jedutunin tapaan; Daavidin virsi. {62:2} Jumalaa yksin minun sieluni hiljaisuudessa odottaa, häneltä tulee minulle apu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, '{62:3} Hän yksin on minun kallioni, minun apuni ja turvani: en minä suuresti horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, '{62:4} Kuinka kauan te yhtä miestä ahdistatte, hänet yhdessä surmataksenne, niinkuin hän olisi kaatuva seinä, niinkuin murrettu muuri?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, '{62:5} He vain pitävät neuvoa, miten syöstä hänet korkeudestaan. He rakastavat valhetta, he siunaavat suullansa ja kiroavat sydämessänsä. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, '{62:6} Odota yksin Jumalaa hiljaisuudessa, minun sieluni, sillä häneltä tulee minun toivoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, '{62:7} Hän yksin on minun kallioni, minun apuni ja turvani: en minä horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, '{62:8} Jumalassa on minun apuni ja kunniani. Minun väkevyyteni kallio, minun turvani on Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, '{62:9} Turvatkaa häneen joka aika, te kansa; vuodattakaa hänen eteensä sydämenne. Jumala on meidän turvamme. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, '{62:10} Vain tuulen henkäystä ovat ihmiset, vain valhetta ihmisten lapset: kaikki he nousevat vaa\'assa ylös köykäisempinä kuin tuulenhenkäys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, '{62:11} Älkää luottako väkivaltaan, älkää turhaan panko toivoanne ryöstettyyn tavaraan. Jos rikkautta karttuu, älkää siihen sydäntänne kiinnittäkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, '{62:12} Kerran on Jumala sanonut, kahdesti olen sen kuullut: väkevyys on Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, '{62:13} Ja sinun, Herra, on armo; sillä sinä maksat kullekin hänen tekojensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Daavidin virsi, kun hän oli Juudan erämaassa. {63:2} Jumala, sinä olet minun Jumalani, sinua minä etsin varhain; sinua minun sieluni janoaa, sinua halajaa minun ruumiini kuivassa ja nääntyvässä, vedettömässä maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, '{63:3} Niin minä katselin sinua pyhäkössä, nähdäkseni sinun voimasi ja kunniasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, '{63:4} Sillä sinun armosi on parempi kuin elämä, minun huuleni ylistäkööt sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, '{63:5} Niin minä kiitän sinua elinaikani, nostan käteni sinun nimeesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, '{63:6} Minun sieluni ravitaan niinkuin lihavuudella ja rasvalla, ja minun suuni ylistää sinua riemuitsevilla huulilla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, '{63:7} kun minä vuoteessani sinua muistan ja ajattelen sinua yön vartiohetkinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, '{63:8} Sillä sinä olet minun apuni, ja sinun siipiesi suojassa minä riemuitsen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, '{63:9} Minun sieluni riippuu sinussa kiinni, sinun oikea kätesi tukee minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, '{63:10} Mutta he etsivät minun henkeäni omaksi turmiokseen, he menevät maan syvyyksiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, '{63:11} Heidät annetaan miekalle alttiiksi, he joutuvat aavikkosutten osaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, '{63:12} Mutta kuningas on iloitseva Jumalassa; hän on jokaisen kerskaus, joka hänen kauttansa vannoo. Sillä valhettelijain suu tukitaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Veisuunjohtajalle; Daavidin virsi. {64:2} Kuule, Jumala, minun ääneni, kun minä valitan, varjele minun elämäni vihollisen pelosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, '{64:3} Kätke minut pahain seuralta, väärintekijäin riehuvalta joukolta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, '{64:4} jotka hiovat kielensä kuin miekan, jännittävät jousensa, nuolinaan karvaat sanat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, '{64:5} salaa ampuaksensa nuhteettoman. He ampuvat häntä äkisti eivätkä kavahda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, '{64:6} He pysyvät lujina pahoissa aikeissaan, he kehuvat, kuinka he virittävät pauloja, he sanovat: \"Kuka ne näkee?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, '{64:7} He miettivät vääryyksiä: \"Meillä on juoni valmiiksi mietittynä\". Syvä on miehen sisu ja sydän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, '{64:8} Mutta Jumala ampuu heidät nuolella, äkisti kohtaavat heitä iskut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, '{64:9} He joutuvat kompastukseen, heidän oma kielensä langettaa heidät; kaikki, jotka heidät näkevät, nyökyttävät ilkkuen päätään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, '{64:10} Ja kaikki ihmiset peljästyvät; he julistavat Jumalan töitä ja ottavat vaarin hänen teoistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, '{64:11} Vanhurskas iloitsee Herrassa ja turvaa häneen, ja kaikki oikeamieliset kerskaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Veisuunjohtajalle; Daavidin virsi, laulu. {65:2} Jumala, hiljaisuudessa kiitetään sinua Siionissa, ja sinulle täytetään lupaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, '{65:3} Sinä kuulet rukouksen: sinun tykösi tulee kaikki liha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, '{65:4} Minun syntivelkani ovat ylen raskaat, mutta sinä annat anteeksi meidän rikoksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, '{65:5} Autuas se, jonka sinä valitset ja otat tykösi, esikartanoissasi asumaan! Salli meidän tulla ravituiksi sinun huoneesi hyvyydellä, sinun temppelisi pyhyydellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, '{65:6} Ihmeellisillä teoilla sinä vastaat meille vanhurskaudessa, sinä, meidän autuutemme Jumala, sinä, kaikkien maan äärten ja kaukaisen meren turva,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, '{65:7} joka voimallasi vahvistat vuoret ja olet vyötetty väkevyydellä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, '{65:8} sinä, joka asetat merten pauhinan ja niiden aaltojen pauhinan ja kansojen metelin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, '{65:9} niin että ne, jotka niiden äärillä asuvat, hämmästyvät sinun ihmeitäsi; aamun ja ehtoon ääret sinä täytät riemulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, '{65:10} Sinä pidät maasta huolen, kastelet sen runsaasti, sinä teet sen ylen rikkaaksi. Jumalan virta on vettä täynnä. Sinä valmistat heidän viljansa, sillä niin sinä valmistat maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, '{65:11} Sinä kastelet sen vaot, sinä muhennat sen multapaakut, sadekuuroilla sinä sen pehmität ja siunaat sen laihon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, '{65:12} Sinä kaunistat vuoden hyvyydelläsi, ja sinun askeleesi tiukkuvat lihavuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, '{65:13} Erämaan laitumet tiukkuvat, ja kukkulat vyöttäytyvät riemuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, '{65:14} Kedot verhoutuvat lammaslaumoihin, ja vilja peittää laaksot. Riemuitaan ja lauletaan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Veisuunjohtajalle; laulu, virsi. Kohottakaa Jumalalle riemuhuuto, kaikki maa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'veisatkaa hänen nimensä kunniaa, antakaa hänelle kunnia ja ylistys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Sanokaa Jumalalle: \"Kuinka peljättävät ovat sinun tekosi!\" Sinun suuren voimasi tähden sinun vihollisesi matelevat sinun edessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Kaikki maa kumartakoon sinua ja veisatkoon sinun kiitostasi, veisatkoon sinun nimesi kiitosta. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Tulkaa ja katsokaa Jumalan töitä: hän on peljättävä teoissansa ihmisten lapsia kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Meren hän muutti kuivaksi maaksi, jalkaisin käytiin virran poikki; silloin me iloitsimme hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Hän hallitsee voimallansa iankaikkisesti, hänen silmänsä vartioitsevat kansoja; niskoittelijat älkööt nostako päätänsä. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Kiittäkää, te kansat, meidän Jumalaamme, korkealle kaiuttakaa hänen ylistystänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Hän antaa meidän sielullemme elämän eikä salli meidän jalkamme horjua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Sillä sinä, Jumala, olet koetellut meitä, olet sulattanut meitä, niinkuin hopea sulatetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Sinä veit meidät verkkoon, panit kuorman meidän lanteillemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Sinä annoit ihmisten ajaa päämme päällitse, me jouduimme tuleen ja veteen. Mutta sinä veit meidät yltäkylläisyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Minä tuon sinun huoneeseesi polttouhreja, täytän sinulle lupaukseni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'joihin minun huuleni avautuivat ja jotka minun suuni hädässäni lausui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Lihavat polttouhrit minä sinulle uhraan ynnä oinasten uhrituoksun; minä uhraan sinulle härkiä ja kauriita. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Tulkaa, kuulkaa, niin minä kerron teille, kaikki te Jumalaa pelkääväiset, mitä hän on minun sielulleni tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Häntä minä suullani huusin, ja ylistys tuli minun kielelleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Jos minulla olisi vääryys sydämessäni, ei Herra minua kuulisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Mutta Jumala kuuli minua ja otti vaarin minun rukoukseni äänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Kiitetty olkoon Jumala, joka ei hyljännyt minun rukoustani eikä ottanut minulta pois armoansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Veisuunjohtajalle; kielisoittimilla; virsi, laulu. {67:2} Jumala olkoon meille armollinen ja siunatkoon meitä, hän valistakoon kasvonsa meille, -Sela-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, '{67:3} että maan päällä tunnettaisiin sinun tiesi, kaikissa pakanakansoissa sinun apusi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, '{67:4} Sinua, Jumala, kansat kiittäkööt, sinua kaikki kansat kiittäkööt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, '{67:5} Iloitkoot ja riemuitkoot kansakunnat, sillä sinä tuomitset kansat oikein ja johdatat kansakunnat maan päällä. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, '{67:6} Sinua, Jumala, kansat kiittäkööt, sinua kaikki kansat kiittäkööt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, '{67:7} Maa on satonsa antanut. Siunatkoon meitä Jumala, meidän Jumalamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, '{67:8} Siunatkoon meitä Jumala, ja peljätkööt häntä kaikki maan ääret.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Veisuunjohtajalle; Daavidin virsi, laulu. {68:2} Jumala nousee, hänen vihollisensa hajaantuvat, hänen vihamiehensä pakenevat hänen kasvojensa edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, '{68:3} Sinä hajotat heidät, niinkuin savu hajoaa; niinkuin vaha sulaa tulen hohteessa, niin jumalattomat häviävät Jumalan kasvojen edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, '{68:4} Mutta vanhurskaat iloitsevat ja riemuitsevat Jumalan kasvojen edessä, he ihastuvat ilosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, '{68:5} Laulakaa Jumalalle, veisatkaa hänen nimensä kiitosta. Tehkää tie hänelle, joka kiitää halki arojen. Hänen nimensä on Herra, riemuitkaa hänen kasvojensa edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, '{68:6} Hän on orpojen isä ja leskien puolustaja, Jumala pyhässä asunnossansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, '{68:7} Jumala, joka antaa hyljätyille kodin ja johtaa vangitut onneen. Vain niskoittelijat asuvat kuivassa maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, '{68:8} Jumala, kun sinä kävit kansasi edellä, kun sinä kuljit erämaassa, -Sela-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, '{68:9} niin maa vapisi ja taivaat tiukkuivat Jumalan kasvojen edessä, Siinai vapisi Jumalan, Israelin Jumalan, kasvojen edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, '{68:10} Runsaalla sateella sinä, Jumala, kostutit perintömaasi; ja kun se oli näännyksissä, niin sinä virvoitit sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, '{68:11} Sinun laumasi asettui siihen; hyvyydessäsi, Jumala, sinä sen kurjille valmistit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, '{68:12} Herra antaa sanoman, suuri on voitonsanoman saattajatarten joukko:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, '{68:13} \"Sotajoukkojen kuninkaat pakenevat, he pakenevat, ja perheen emäntä jakaa saaliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, '{68:14} Jäättekö makailemaan karjatarhojen vaiheille? Kyyhkysen siivet ovat hopealla silatut, sen sulat keltaisella kullalla!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, '{68:15} Kun Kaikkivaltias siellä hajotti kuninkaat, satoi lunta Salmonilla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, '{68:16} Baasanin vuori on Jumalan vuori, Baasanin vuori on monihuippuinen vuori.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, '{68:17} Miksi te, monihuippuiset vuoret, karsaasti katsotte vuorta, jolla Jumala on mielistynyt asumaan? Totisesti, Herra asuu siellä iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, '{68:18} Jumalan sotavaunuja on kymmenet tuhannet, on tuhannen kertaa tuhannet; Herra on niiden keskellä, pyhyydessään niinkuin Siinai.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, '{68:19} Sinä astuit ylös korkeuteen, otit vankeja saaliiksesi, sait ihmisiä lahjaksesi: niskoittelijatkin joutuvat asumaan Herran Jumalan tykönä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, '{68:20} Kiitetty olkoon Herra joka päivä. Meitä kantaa Jumala, meidän apumme. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, '{68:21} Meillä on Jumala, Jumala, joka auttaa, ja Herra, Herra, joka kuolemasta vapahtaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, '{68:22} Mutta Jumala murskaa vihollistensa pään, niiden karvaisen päälaen, jotka synneissänsä vaeltavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, '{68:23} Herra sanoo: \"Baasanista minä heidät palautan, palautan meren syvyyksistä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, '{68:24} että sinä polkisit jalkasi vereen, että sinun koiriesi kieli saisi osansa vihollisista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, '{68:25} Julkinähtävät ovat sinun juhlasaattosi, Jumala, minun Jumalani, kuninkaani juhlasaatot pyhäkössä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, '{68:26} Laulajat käyvät edellä, kanteleensoittajat jäljessä, keskellä nuoret naiset vaskirumpuja lyöden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, '{68:27} Kiittäkää Jumalaa seurakunnan kokouksissa, kiittäkää Herraa te, jotka olette Israelin lähteestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, '{68:28} Tuolla on Benjamin, nuorin, heitä johtaen, Juudan ruhtinaat joukkoinensa, Sebulonin ruhtinaat, Naftalin ruhtinaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, '{68:29} Sinun Jumalasi on säätänyt sinulle vallan. Vahvista, Jumala, minkä olet hyväksemme tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, '{68:30} Sinun temppelisi tähden, joka kohoaa Jerusalemissa, kuninkaat tuovat sinulle lahjoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, '{68:31} Käske ankarasti ruovikon petoa, härkien laumaa ynnä vasikoita, kansoja, lankeamaan maahan hopeaharkkoinensa. Hän hajottaa kansat, jotka sotia rakastavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, '{68:32} Mahtavat saapuvat Egyptistä, Etiopia kiiruhtaa ojentamaan käsiänsä Jumalan puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, '{68:33} Te maan valtakunnat, laulakaa Jumalalle, veisatkaa Herran kiitosta, -Sela-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, '{68:34} hänen, joka kiitää ikuisten taivasten taivaissa! Katso, hän antaa äänellänsä väkevän jylinän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, '{68:35} Antakaa väkevyys Jumalalle! Hänen herrautensa on Israelin yllä ja hänen voimansa pilvien tasalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, '{68:36} Peljättävä on Jumala, joka ilmestyy sinun pyhäköstäsi, Israelin Jumala. Hän antaa kansallensa voiman ja väkevyyden. Kiitetty olkoon Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Veisuunjohtajalle; veisataan kuin: \"Liljat\"; Daavidin virsi. {69:2} Pelasta minut, Jumala, sillä vedet käyvät minun sieluuni asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, '{69:3} Minä olen vajonnut syvään, pohjattomaan liejuun, olen joutunut vetten syvyyksiin, ja virta tulvii minun ylitseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, '{69:4} Minä olen väsynyt huutamisesta, minun kurkkuni kuivettuu, minun silmäni ovat rauenneet odottaessani Jumalaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, '{69:5} Enemmän kuin hiuksia päässäni on niitä, jotka minua syyttömästi vihaavat; paljon on niitä, jotka tahtovat tuhota minut, jotka syyttä ovat vihollisiani; mitä en ole ryöstänyt, se täytyy minun maksaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, '{69:6} Jumala, sinä tunnet minun hulluuteni, eivätkä minun vikani ole sinulta salassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, '{69:7} Älä anna minussa häpeään joutua niiden, jotka odottavat sinua, Herra, Herra Sebaot. Älä salli minussa pettyä niiden, jotka etsivät sinua, Israelin Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, '{69:8} Sillä sinun tähtesi minä kärsin herjausta, pilkka peittää minun kasvoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, '{69:9} Veljilleni minä olen tullut vieraaksi, olen tullut oudoksi äitini lapsille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, '{69:10} Sillä kiivaus sinun huoneesi puolesta on minut kuluttanut, ja niiden herjaukset, jotka sinua herjaavat, ovat sattuneet minuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, '{69:11} Minä, minun sieluni itki ja paastosi, mutta siitä koitui minulle vain herjausta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, '{69:12} Minä pukeuduin säkkipukuun, mutta tulin sananparreksi heidän suussaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, '{69:13} Porteissa-istujat minusta jaarittelevat, ja väkijuomain juojat minusta laulavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, '{69:14} Mutta minä rukoilen sinua, Herra, otollisella ajalla, sinua, Jumala, sinun suuren laupeutesi turvin. Vastaa minulle pelastavan uskollisuutesi tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, '{69:15} Päästä minut loasta, etten siihen vajoa, auta, että pääsen vihollisistani ja syvistä vesistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, '{69:16} Älä anna vetten vuon minua upottaa, syvyyden minua niellä ja kuilun sulkea suutaan minun ylitseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, '{69:17} Vastaa minulle, Herra, sillä sinun armosi on hyvä, käänny minun puoleeni suuressa laupeudessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, '{69:18} Älä peitä kasvojasi palvelijaltasi, sillä minä olen ahdistuksessa; joudu, vastaa minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, '{69:19} Lähesty minun sieluani ja lunasta se, vapahda minut vihollisteni tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, '{69:20} Sinä tiedät minun häväistykseni, minun häpeäni ja pilkkani, sinun edessäsi ovat julki kaikki minun ahdistajani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, '{69:21} Häväistys on särkenyt minun sydämeni, minä olen käynyt heikoksi; minä odotin sääliä, mutta en saanut, ja lohduttajia, mutta en löytänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, '{69:22} Koiruohoa he antoivat minun syödäkseni ja juottivat minulle janooni hapanviiniä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, '{69:23} Tulkoon heidän pöytänsä heille paulaksi, ansaksi noille suruttomille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, '{69:24} Soetkoot heidän silmänsä, niin etteivät näe, ja saata heidän lanteensa alati horjumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, '{69:25} Vuodata vihastuksesi heidän päällensä, ja yllättäköön heidät sinun vihasi hehku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, '{69:26} Joutukoon heidän leiripaikkansa autioksi, älköön heidän majoissansa asukasta olko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, '{69:27} Sillä he vainoavat sitä, jota sinä olet lyönyt, he juttelevat niiden tuskista, joita sinä olet haavoittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, '{69:28} Lisää heille rikosta rikoksen päälle, ja sinun vanhurskauteesi he älkööt pääskö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, '{69:29} Pyyhittäköön heidät pois elämän kirjasta, älköönkä heitä kirjoitettako vanhurskasten lukuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, '{69:30} Mutta minä olen kurja ja vaivattu, suojatkoon minua sinun apusi, Jumala,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, '{69:31} niin minä veisuulla kiitän Jumalan nimeä ja ylistän häntä kiitosvirsillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, '{69:32} Se on Herralle otollisempi kuin härkä, kuin mulli, sarvipää ja sorkkajalka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, '{69:33} Nöyrät näkevät sen ja riemuitsevat; elpyköön teidän sydämenne, teidän, jotka etsitte Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, '{69:34} Sillä Herra kuulee köyhiä eikä halveksi vankejansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, '{69:35} Kiittäkööt häntä taivaat ja maa, meret ja kaikki, mitä niissä liikkuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, '{69:36} Sillä Jumala on pelastava Siionin ja rakentava Juudan kaupungit, niin että he asettuvat niihin ja omistavat ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, '{69:37} Hänen palvelijainsa jälkeläiset saavat sen perinnökseen, ja ne, jotka hänen nimeänsä rakastavat, saavat asua siinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Veisuunjohtajalle; Daavidin virsi; syntiä tunnustettaessa. {70:2} Jumala, riennä minua pelastamaan, riennä minun avukseni, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, '{70:3} Joutukoot häpeään ja punastukoot ne, jotka minun henkeäni väijyvät; peräytykööt ja saakoot häpeän ne, jotka tahtovat minulle onnettomuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, '{70:4} Kääntykööt takaisin häpeissänsä ne, jotka sanovat: \"Kas niin, kas niin!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, '{70:5} Iloitkoot ja riemuitkoot sinussa kaikki, jotka sinua etsivät; joille sinun apusi on rakas, ne sanokoot aina: \"Ylistetty olkoon Jumala!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, '{70:6} Mutta minä olen kurja ja köyhä; Jumala, riennä minun tyköni. Sinä olet minun apuni ja vapauttajani; Herra, älä viivy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Sinuun, Herra, minä turvaan, älä salli minun joutua häpeään iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Pelasta minut, vapahda minut vanhurskaudessasi, kallista korvasi minun puoleeni ja auta minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Ole minulle kallio, jolla saan asua ja jonne aina saan mennä, sinä, joka olet säätänyt minulle pelastuksen. Sillä sinä olet minun kallioni ja linnani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Jumalani, vapauta minut jumalattoman kädestä, väärän ja väkivaltaisen kourista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Sillä sinä olet minun toivoni, Herra, Herra, minun turvani hamasta nuoruudestani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Sinä olet minun tukeni syntymästäni saakka, sinä päästit minut äitini kohdusta; sinua minä alati ylistän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Monelle minä olen kuin kummitus, mutta sinä olet minun vahva suojani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Minun suuni on täynnä sinun kiitostasi, täynnä sinun ylistystäsi kaiken päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Älä heitä minua pois minun vanhalla iälläni, älä hylkää minua, kun voimani loppuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Sillä minun viholliseni puhuvat minusta; ne, jotka väijyvät minun henkeäni, neuvottelevat keskenänsä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, '\"Jumala on hänet hyljännyt; ajakaa häntä takaa ja ottakaa kiinni, sillä auttajaa ei ole\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Jumala, älä ole minusta kaukana, Jumalani, riennä minun avukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Joutukoot häpeään ja hukkukoot ne, jotka vainoavat minun sieluani; peittäköön häpeä ja pilkka ne, jotka hankkivat minulle onnettomuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Mutta minä odotan alati, ja yhäti minä sinua kiitän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Minun suuni on julistava sinun vanhurskauttasi, sinun pelastustekojasi kaiken päivää, sillä niiden määrää en minä tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Herran, Herran väkeviä tekoja minä tuon julki, minä ylistän sinun vanhurskauttasi, sinun ainoan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Jumala, sinä olet opettanut minua hamasta nuoruudestani, ja yhä vielä minä sinun ihmeitäsi julistan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Älä, Jumala, minua hylkää vanhaksi ja harmaaksi tultuani, niin minä julistan sinun käsivartesi voimaa nousevalle polvelle, sinun väkevyyttäsi kaikille vielä tuleville.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Jumala, sinun vanhurskautesi ulottuu hamaan korkeuksiin, sinun, joka teet niin suuria. Jumala, kuka on sinun vertaisesi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Sinä, joka olet antanut meidän kokea paljon ahdistusta ja onnettomuutta, sinä virvoitat meidät jälleen henkiin, ja maan syvyyksistä sinä tuot meidät takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Anna minun arvoni kasvaa ja lohduta minua jälleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Niin minä myös ylistän harpulla sinua, sinun uskollisuuttasi, minun Jumalani, soitan kanteleella kiitosta sinulle, sinä Israelin Pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Minun huuleni riemuitsevat, kun minä sinulle soitan, ja myös minun sieluni, jonka sinä olet lunastanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Minun kieleni julistaa sinun vanhurskauttasi kaiken päivää, sillä häpeään ja pilkkaan ovat joutuneet ne, jotka hankkivat minulle onnettomuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Salomon virsi. Jumala, anna kuninkaan tuomita, niinkuin sinä tuomitset, anna vanhurskautesi kuninkaan pojalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Tuomitkoon hän sinun kansaasi vanhurskaasti ja sinun kurjiasi oikeuden mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Vuoret kantakoot rauhaa kansalle, niin myös kukkulat, vanhurskauden voimasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Auttakoon hän kansan kurjat oikeuteen, pelastakoon köyhäin lapset ja musertakoon sortajan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Niin he pelkäävät sinua, niin kauan kuin aurinko paistaa ja kuu kumottaa, polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Hän olkoon niinkuin sade, joka nurmikolle vuotaa, niinkuin sadekuuro, joka kostuttaa maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Hänen päivinänsä vanhurskas kukoistaa, ja rauha on oleva runsas siihen saakka, kunnes kuuta ei enää ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Hallitkoon hän merestä mereen ja Eufrat-virrasta maan ääriin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Hänen edessänsä erämaan asujat polvistuvat, ja hänen vihollisensa nuolevat tomua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Tarsiin ja saarten kuninkaat tuovat lahjoja, Saban ja Seban kuninkaat veroa maksavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Häntä kumartavat kaikki kuninkaat, kaikki kansakunnat palvelevat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Sillä hän pelastaa köyhän, joka apua huutaa, kurjan ja sen, jolla ei auttajaa ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Hän armahtaa vaivaista ja köyhää ja pelastaa köyhäin sielun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Hän lunastaa heidän sielunsa sorrosta ja väkivallasta, ja heidän verensä on hänen silmissään kallis.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Hän eläköön, ja hänelle tuotakoon Saban kultaa; hänen puolestansa rukoiltakoon alati, ja siunattakoon häntä lakkaamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Maa kasvakoon runsaasti viljaa, vuorten huippuja myöten, sen hedelmä huojukoon niinkuin Libanon; ja kansaa nouskoon kaupungeista niinkuin kasveja maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Pysyköön hänen nimensä iankaikkisesti, ja versokoon hänen nimensä, niin kauan kuin aurinko paistaa. Hänessä he itseänsä siunatkoot, ja kaikki kansakunnat ylistäkööt häntä onnelliseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Kiitetty olkoon Herra Jumala, Israelin Jumala, ainoa, joka ihmeitä tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Kiitetty olkoon hänen kunniansa nimi iankaikkisesti, ja kaikki maa olkoon täynnä hänen kunniaansa. Amen, amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Daavidin, Iisain pojan, rukoukset päättyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Aasafin virsi. Totisesti, Jumala on hyvä Israelille, niille, joilla on puhdas sydän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Mutta minun jalkani olivat vähällä kompastua, askeleeni olivat aivan liukahtaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Sillä minussa nousi kateus ylvästelijöitä kohtaan, kun minä näin jumalattomien menestyvän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Sillä he ovat vaivoista vapaat kuolemaansa asti, he ovat voimakkaat ja lihavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Eivät he koe muitten kuolevaisten tuskia, eikä heitä vaivata niinkuin muita ihmisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Sentähden on ylpeys heillä kaulakoristeena, väkivalta on puku, joka heidät verhoaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Heidän silmänsä pullistuvat ulos heidän lihavuudestaan, heidän sydämensä kuvittelut kulkevat valtoimina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'He pilkkaavat ja puhuvat väkivallan puheita pahuudessansa, he puhuvat kuin korkeuksista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Heidän suunsa tavoittelee taivasta, ja heidän kielensä kulkee pitkin maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Sentähden heidän kansansa liittyy heihin ja särpii vettä kyllälti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Ja he sanovat: \"Kuinka Jumala sen tietäisi, onko tietoa Korkeimmalla?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Katso, nämä ovat jumalattomat; kuitenkin he elävät ainaisessa rauhassa ja rikastuvat yhäti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Turhaan minä olen pitänyt sydämeni puhtaana ja pessyt käteni viattomuudessa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'minua vaivataan joka aika, ja minä saan joka aamu kuritusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Jos olisin sanonut: \"Noin minäkin puhun\", katso, niin minä olisin ollut petollinen koko sinun lastesi sukua kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Minä mietin päästäkseni tästä selvyyteen; mutta se oli minulle ylen vaikeata,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'kunnes minä pääsin sisälle Jumalan pyhiin salaisuuksiin ja käsitin, mikä heidän loppunsa on oleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Totisesti, sinä panet heidät liukkaalle, perikatoon sinä heidät syökset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Kuinka he joutuvatkaan äkisti turmioon! He hukkuvat, heidän loppunsa on kauhistava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Niinkuin unen käy herätessä, niin sinä, Herra, kun heräjät, heidän valhekuvansa hylkäät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Kun minun sydämeni katkeroitui ja minun munaskuihini pisti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'silloin minä olin järjetön enkä mitään älynnyt, olin sinun edessäsi kuin nauta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Kuitenkin minä pysyn alati sinun tykönäsi, sinä pidät minua kiinni oikeasta kädestäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Sinä talutat minua neuvosi mukaan ja korjaat minut viimein kunniaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Ketä muuta minulla olisi taivaassa! Ja kun sinä olet minun kanssani, en minä mistään maan päällä huoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Vaikka minun ruumiini ja sieluni nääntyisi, Jumala on minun sydämeni kallio ja minun osani iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Sillä katso, jotka sinusta eriävät, ne hukkuvat, sinä tuhoat kaikki, jotka haureudessa sinusta luopuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Mutta minun onneni on olla Jumalaa lähellä, minä panen turvani Herraan, Herraan, kertoakseni kaikkia sinun tekojasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Aasafin mietevirsi. Miksi sinä, Jumala, hylkäsit meidät ainiaaksi, miksi suitsuaa sinun vihasi laitumesi lampaita vastaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Muista seurakuntaasi, jonka muinoin omaksesi otit, jonka lunastit perintösuvuksesi. Muista Siionin vuorta, jolla sinä asut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Ohjaa askeleesi ikuisille raunioille. Vihollinen on raiskannut kaiken pyhäkössä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Sinun vihollisesi huusivat kokoushuoneessasi, he pystyttivät omat merkkinsä merkeiksi sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Näytti, kuin olisi tiheässä metsässä kirveitä heilutettu korkealle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Niin he löivät kaikki sen veistokset kirveillä ja nuijilla rikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'He pistivät sinun pyhäkkösi tuleen, he häväisivät, panivat maan tasalle sinun nimesi asumuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'He sanoivat sydämessään: \"Me hävitämme heidät kaikki tyynni\". He polttivat kaikki jumalanpalvelushuoneet maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Merkkejämme me emme näe, ei ole enää profeettaa, eikä ole joukossamme ketään, joka tietäisi, kuinka kauan-.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Kuinka kauan, Jumala, vihollinen saa herjata, vihamies pilkata sinun nimeäsi lakkaamatta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Miksi pidätät kättäsi, oikeata kättäsi? Vedä se povestasi ja hävitä heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Jumala on minun kuninkaani ammoisista ajoista, hän toimittaa pelastuksen maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Sinä voimallasi halkaisit meren, sinä musersit lohikäärmeitten päät vetten päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Sinä ruhjoit rikki Leviatanin päät, sinä annoit hänet ruuaksi erämaan eläinten laumalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Sinä puhkaisit kuohumaan lähteen ja puron, sinä kuivasit väkevät virrat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Sinun on päivä, sinun on yö, sinä valmistit valon ja auringon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Sinä määräsit kaikki maan rajat, sinä asetit kesän ja talven.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Niin muista tämä: vihollinen herjaa Herraa, houkkiokansa pilkkaa sinun nimeäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Älä anna pedolle alttiiksi metsäkyyhkysesi sielua, älä iäksi unhota kurjiesi elämää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Katso liittoasi. Sillä maan pimennot ovat väkivallan pesiä täynnä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Älä salli sorretun kääntyä häväistynä takaisin. Kurja ja köyhä saakoot ylistää sinun nimeäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Nouse, Jumala, aja asiasi. Muista, miten houkat herjaavat sinua kaiken aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Älä unhota vihollistesi huutoa, älä vastustajaisi melua, joka kohoaa lakkaamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Veisuunjohtajalle; veisataan kuin: \"Älä turmele\"; virsi; Aasafin laulu. {75:2} Me kiitämme sinua, Jumala, me kiitämme sinua; lähellä on sinun nimesi, sinun ihmeitäsi kerrotaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, '{75:3} \"Vaikka minä valitsenkin ajan, minä tuomitsen oikein.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, '{75:4} Vaikka maa kaikkine asukkaineen menehtyy pelkoon, pidän minä pystyssä sen patsaat.\" Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, '{75:5} \"Ylvästelijöille minä sanon: älkää ylvästelkö, ja jumalattomille: älkää sarvea nostako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, '{75:6} Älkää nostako sarveanne korkealle, älkää puhuko niskoitellen, julkeasti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, '{75:7} Ei tule apua idästä, ei lännestä, ei vuorisesta erämaasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, '{75:8} vaan Jumala on se, joka tuomitsee: yhden hän alentaa, toisen ylentää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, '{75:9} Sillä Herran kädessä on malja, joka vaahtoaa täynnänsä höystettyä viiniä, ja siitä hän kaataa; kaikkien maan jumalattomien täytyy se juoda, särpiä pohjasakkaa myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, '{75:10} Mutta minä julistan iäti, veisaan kiitosta Jaakobin Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, '{75:11} Ja kaikki jumalattomien sarvet minä katkaisen; korkealle kohoavat vanhurskaan sarvet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Veisuunjohtajalle; kielisoittimilla; virsi; Aasafin laulu. {76:2} Jumala on tunnettu Juudassa, hänen nimensä on suuri Israelissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, '{76:3} Saalemissa on hänen majansa ja hänen asumuksensa Siionissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, '{76:4} Siellä hän mursi jousen salamat, kilven ja miekan ja sodan. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, '{76:5} Kirkkaudessa, valtasuuruudessa sinä tulit voittosaaliin vuorilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, '{76:6} Urhoollisilta ryöstettiin aseet, he uupuivat uneen; kaikkien sankarien kädet herposivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, '{76:7} Sinun nuhtelustasi, Jaakobin Jumala, vaipuivat raskaaseen uneen vaunut ja hevoset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, '{76:8} Sinä olet peljättävä, kuka kestää sinun edessäsi, kun sinä vihastut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, '{76:9} Taivaasta sinä annoit tuomiosi kuulua; maa peljästyi ja vaikeni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, '{76:10} kun Jumala nousi tuomiolle vapahtaakseen kaikki maan nöyrät. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, '{76:11} Sillä ihmisten viha tulee sinulle ylistykseksi: sinä vyöttäydyt vihan ylenpalttisuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, '{76:12} Tehkää lupauksia ja täyttäkää ne Herralle, Jumalallenne. Kaikki hänen ympärillään asuvaiset tuokoot lahjoja Peljättävälle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, '{76:13} joka nöyryyttää ruhtinaitten rohkeuden ja joka on peljättävä maan kuninkaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Veisuunjohtajalle; Jedutunin tapaan; Aasafin virsi. {77:2} Minä korotan ääneni Jumalan puoleen ja huudan; minä korotan ääneni Jumalan puoleen, että hän minua kuulisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, '{77:3} Ahdistukseni aikana minä etsin Herraa; minun käteni on yöllä ojennettuna eikä väsy; minun sieluni ei lohdutuksesta huoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, '{77:4} Minä muistan Jumalaa ja huokaan; minä tutkistelen, ja minun henkeni nääntyy. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, '{77:5} Sinä pidät minun silmäni valveilla; minä olen niin levoton, etten voi puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, '{77:6} Minä ajattelen muinaisia päiviä, ammoin menneitä vuosia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, '{77:7} Minä muistan yöllä kanteleeni, minä mietiskelen sydämessäni, ja minun henkeni tutkii:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, '{77:8} Hylkääkö Herra ikiajoiksi eikä enää osoita mielisuosiota?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, '{77:9} Onko hänen armonsa mennyt ainiaaksi, onko hänen lupauksensa lopussa polvesta polveen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, '{77:10} Onko Jumala unhottanut olla armollinen, onko hän vihassaan lukinnut laupeutensa? Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, '{77:11} Minä sanoin: tämä on minun kärsimykseni, että Korkeimman oikea käsi on muuttunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, '{77:12} Minä muistelen Herran tekoja, minä muistelen sinun entisiä ihmetöitäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, '{77:13} Minä tutkistelen kaikkia sinun töitäsi, minä mietin sinun suuria tekojasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, '{77:14} Jumala, sinun tiesi on pyhä; kuka on jumala, suuri niinkuin sinä, Jumala?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, '{77:15} Sinä olet Jumala, joka teet ihmeitä, sinä olet ilmoittanut voimasi kansojen seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, '{77:16} Käsivarrellasi sinä lunastit kansasi, Jaakobin ja Joosefin lapset. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, '{77:17} Vedet näkivät sinut, Jumala, vedet näkivät sinut ja vapisivat, ja syvyydet värisivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, '{77:18} Pilvet purkivat vettä, pilvet antoivat jylinänsä, sinun nuolesi lensivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, '{77:19} Sinun pauhinasi ääni vyöryi, salamat valaisivat maan piirin, maa vapisi ja järkkyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, '{77:20} Meren halki kävi sinun tiesi, sinun polkusi läpi suurten vetten, eivätkä sinun jälkesi tuntuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, '{77:21} Sinä kuljetit kansasi niinkuin lammaslauman Mooseksen ja Aaronin kädellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Aasafin mietevirsi. Kuuntele, kansani, minun opetustani, kallistakaa korvanne minun suuni sanoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Minä avaan suuni mietelmiin, tuon ilmi muinaisaikojen arvoituksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Mitä olemme kuulleet, minkä olemme saaneet tietää ja mitä isämme ovat meille kertoneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'sitä me emme heidän lapsiltansa salaa, vaan me kerromme tulevalle polvelle Herran ylistettävistä teoista, hänen voimastansa ja ihmeistänsä, jotka hän on tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Hän asetti todistuksen Jaakobiin, hän sääti Israeliin lain ja käski meidän isiemme julistaa ne lapsillensa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'että jälkipolvi saisi ne tietää, saisivat tietää vastedes syntyvät lapset, ja nekin nousisivat ja kertoisivat niistä lapsillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Niin nämä panisivat uskalluksensa Jumalaan eivätkä unhottaisi Jumalan tekoja, vaan ottaisivat hänen käskyistänsä vaarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Ja niin ei heistä tulisi, niinkuin heidän isistänsä, kapinoitseva ja niskoitteleva polvi, sukupolvi, jonka sydän ei pysynyt lujana ja jonka henki ei pysynyt uskollisena Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Efraimin lapset, asestetut jousimiehet, kääntyivät pakoon taistelun päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Eivät he pitäneet Jumalan liittoa, eivät tahtoneet vaeltaa hänen lakinsa mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'vaan he unhottivat hänen suuret tekonsa ja hänen ihmeensä, jotka hän heille näytti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Heidän isiensä nähden hän ihmeitä teki Egyptin maassa, Sooanin kedolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Hän halkaisi meren ja vei heidät sen läpi, hän seisotti vedet roukkioksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Hän johdatti heitä päivän aikaan pilvellä ja tulen valolla kaiket yöt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Hän halkoi kalliot erämaassa ja juotti heitä runsaasti, kuin syvistä vesistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Hän juoksutti puroja kalliosta ja vuodatti virtanaan vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Yhä he kuitenkin tekivät syntiä häntä vastaan ja olivat uppiniskaisia Korkeimmalle erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'He kiusasivat Jumalaa sydämessänsä, vaatien ruokaa himonsa tyydyttämiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Ja he puhuivat Jumalaa vastaan sanoen: \"Voikohan Jumala kattaa pöydän erämaassa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Katso, hän kyllä kallioon iski, ja vedet vuotivat ja purot tulvivat; mutta voiko hän antaa myös leipää tai hankkia kansallensa lihaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Sentähden Herra, kun hän sen kuuli, julmistui; ja tuli syttyi Jaakobissa, ja Israelia vastaan nousi viha,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'koska he eivät uskoneet Jumalaan eivätkä luottaneet hänen apuunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Hän käski pilviä korkeudessa ja avasi taivaan ovet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'hän satoi heille ruuaksi mannaa, hän antoi heille taivaan viljaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Ihmiset söivät enkelien leipää; hän lähetti heille evästä yllin kyllin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Hän nosti taivaalle itätuulen ja ajoi voimallaan esiin etelätuulen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'hän antoi sataa heille lihaa kuin tomua, siivekkäitä lintuja kuin meren hiekkaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'hän pudotti ne leirinsä keskeen, yltympäri asuntonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Niin he söivät ja tulivat kylläisiksi; mitä he olivat himoinneet, sitä hän salli heidän saada.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Eivät olleet he vielä himoansa tyydyttäneet, ja ruoka oli vielä heidän suussaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'kun heitä vastaan jo nousi Jumalan viha: hän tappoi heidän voimakkaimpansa ja kaatoi maahan Israelin nuoret miehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Mutta sittenkin he yhä vielä tekivät syntiä eivätkä uskoneet hänen ihmeitänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Sentähden hän lopetti heidän päivänsä niinkuin tuulahduksen, antoi heidän vuottensa päättyä äkilliseen perikatoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Kun hän surmasi heitä, kysyivät he häntä, kääntyivät ja etsivät Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'He muistivat, että Jumala oli heidän kallionsa, ja että Jumala, Korkein, oli heidän lunastajansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Mutta he pettivät häntä suullaan ja valhettelivat hänelle kielellänsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'sillä heidän sydämensä ei ollut vakaa häntä kohtaan, eivätkä he olleet uskolliset hänen liitossansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Mutta hän on laupias, antaa anteeksi rikkomukset eikä tahdo hukuttaa. Sentähden hän usein kääntyi vihastansa eikä antanut kaiken kiivautensa nousta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Sillä hän muisti, että he ovat liha, tuulahdus, joka menee eikä enää palaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Kuinka usein he niskoittelivat häntä vastaan korvessa ja murehduttivat hänen mielensä erämaassa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Ja yhä edelleen he kiusasivat Jumalaa ja vihoittivat Israelin Pyhän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'He eivät muistaneet hänen kättänsä, eivät sitä päivää, jona hän päästi heidät ahdistajasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'jona hän teki tunnustekonsa Egyptissä ja ihmeensä Sooanin kedolla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'muutti heidän virtansa vereksi, niin etteivät he voineet vesiojistaan juoda;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'lähetti heidän sekaansa paarmoja, jotka heitä söivät, ja sammakoita, jotka tuottivat heille häviötä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'antoi heidän satonsa tuhosirkoille ja heinäsirkoille heidän vaivannäkönsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'hävitti rakeilla heidän viiniköynnöksensä ja raekivillä heidän metsäviikunapuunsa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'antoi heidän karjansa alttiiksi rakeille ja heidän laumansa salamoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Hän lähetti heitä vastaan vihansa hehkun, kiivastuksen, vihastuksen ja ahdistuksen, parven pahoja enkeleitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Hän raivasi tien vihallensa, ei säästänyt heidän sielujansa kuolemasta, vaan antoi heidän henkensä ruton valtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Hän surmasi kaikki esikoiset Egyptistä, miehuuden ensimmäiset Haamin majoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Mutta kansansa hän pani liikkeelle kuin lampaat ja johdatti heitä erämaassa kuin laumaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Hän johti heitä turvallisesti, heidän ei tarvinnut peljätä; mutta heidän vihollisensa peitti meri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Ja hän vei heidät pyhälle alueellensa, vuorelle, jonka hänen oikea kätensä oli hankkinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Hän karkoitti pakanat pois heidän tieltänsä, jakoi ne heille arvalla perintöosaksi ja antoi Israelin sukukuntain asua niiden majoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Mutta niskoittelullaan he kiusasivat Jumalaa, Korkeinta, eivätkä ottaneet hänen todistuksistansa vaaria,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'vaan luopuivat pois ja olivat uskottomia isiensä lailla, kävivät kelvottomiksi kuin veltto jousi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'He vihoittivat hänet uhrikukkuloillansa ja herättivät hänen kiivautensa epäjumaliensa kuvilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Jumala kuuli sen ja julmistui, ja hän hylkäsi Israelin peräti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Hän hylkäsi asumuksensa Siilossa, majan, jonka hän oli pystyttänyt ihmisten keskelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Hän salli väkevyytensä joutua vankeuteen ja kunniansa vihollisten käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Hän antoi kansansa alttiiksi miekalle ja julmistui perintöosaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Heidän nuorukaisensa kulutti tuli, ja heidän neitsyensä jäivät häälauluja vaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Heidän pappinsa kaatuivat miekkaan, eivätkä heidän leskensä voineet itkuja itkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Silloin Herra heräsi niinkuin nukkuja, niinkuin viinin voittama sankari.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Hän löi vihollisensa pakoon, tuotti heille ikuisen häpeän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Hän hylkäsi myös Joosefin majan eikä valinnut Efraimin sukukuntaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'vaan valitsi Juudan sukukunnan, Siionin vuoren, jota hän rakastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Ja hän rakensi pyhäkkönsä korkeuksien tasalle, rakensi sen kuin maan, jonka hän on perustanut ikiajoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Hän valitsi Daavidin, palvelijansa, ja otti hänet lammastarhoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Hän toi hänet imettäväisten lammasten jäljestä kaitsemaan kansaansa, Jaakobia, ja Israelia, perintöosaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Ja Daavid kaitsi heitä vilpittömin sydämin ja johti heitä taitavalla kädellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Aasafin virsi. Jumala, pakanat ovat tunkeutuneet sinun perintöosaasi, he ovat saastuttaneet sinun pyhän temppelisi, ovat tehneet Jerusalemista kiviraunion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'He antoivat sinun palvelijaisi ruumiit taivaan linnuille ruuaksi, maan pedoille sinun hurskaittesi lihan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'He vuodattivat heidän vertansa kuin vettä ympäri Jerusalemia, eikä heitä kukaan haudannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Me olemme joutuneet naapuriemme häväistäviksi, niiden pilkattaviksi ja ivattaviksi, jotka ympärillämme asuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Kuinka kauan sinä, Herra, olet yhäti vihoissasi, kuinka kauan sinun kiivautesi tulena palaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Vuodata vihasi pakanain ylitse, jotka eivät sinua tunne, ja valtakuntien ylitse, jotka eivät sinun nimeäsi avukseen huuda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Sillä he ovat syöneet Jaakobin ja tehneet hänen asuinsijansa autioksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Älä lue meidän syyksemme isiemme rikoksia, anna armosi pian kohdata meitä, sillä me olemme sangen viheliäisiksi tulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Auta meitä sinä, pelastuksemme Jumala, nimesi kunnian tähden, pelasta meidät ja anna meidän syntimme anteeksi nimesi tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Miksi pakanat saisivat sanoa: \"Missä on heidän Jumalansa?\" Tulkoon tunnetuksi pakanain seassa, meidän silmäimme nähden, sinun palvelijaisi vuodatetun veren kosto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Tulkoon vankien huokaus sinun kasvojesi eteen; suuren käsivartesi voimalla pidä elossa kuoleman lapset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Ja maksa naapureillemme, heidän helmaansa, seitsenkertaisesti se herjaus, jolla he ovat herjanneet sinua, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Mutta me, sinun kansasi, sinun laitumesi lampaat, kiitämme sinua iankaikkisesti, julistamme sinun kiitostasi polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Veisuunjohtajalle; veisataan kuin: \"Liljat\"; Aasafin todistus; virsi. {80:2} Kuuntele, Israelin paimen. Sinä, joka johdat Joosefia niinkuin lammaslaumaa, sinä, jonka valtaistuinta kerubit kannattavat, ilmesty kirkkaudessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, '{80:3} Efraimin, Benjaminin ja Manassen edessä herätä voimasi, tule meidän avuksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, '{80:4} Jumala, saata meidät entisellemme, valista kasvosi, niin me autetuiksi tulemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, '{80:5} Herra, Jumala Sebaot, kuinka kauan sinä annat vihasi suitsuta, kun sinun kansasi rukoilee?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, '{80:6} Sinä olet syöttänyt heille kyynelten leipää, olet juottanut heille maljoittain kyyneleitä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, '{80:7} olet pannut meidät riidaksi naapureillemme, meidän vihollisemme pilkkaavat meitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, '{80:8} Jumala Sebaot, saata meidät entisellemme, valista kasvosi, niin me autetuiksi tulemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, '{80:9} Sinä siirsit viinipuun Egyptistä, sinä karkoitit pakanat ja istutit sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, '{80:10} Sinä raivasit sille sijan, ja se juurtui ja täytti maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, '{80:11} Se peitti vuoret varjollansa ja oksillansa Jumalan setrit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, '{80:12} Se levitti köynnöksensä mereen asti ja vesansa Eufrat-virtaan saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, '{80:13} Miksi sinä särjit aidan sen ympäriltä, niin että kaikki tienkulkijat sitä repivät?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, '{80:14} Metsäkarju sitä jyrsii, ja kedon eläimet sitä syövät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, '{80:15} Jumala Sebaot, käänny takaisin, katso alas taivaasta ja näe; ota hoitaaksesi tämä viinipuu');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, '{80:16} ja suojaa se, minkä sinun oikea kätesi istutti, tämä taimi, jonka kasvatit suureksi itseäsi varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, '{80:17} Se on tulen polttama, se on karsittu. He hukkuvat sinun kasvojesi uhkauksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, '{80:18} Kätesi suojelkoon sinun oikean kätesi miestä, ihmislasta, jonka kasvatit suureksi itseäsi varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, '{80:19} Silloin me emme sinusta luovu. Suo meidän elää, niin me huudamme sinun nimeäsi avuksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, '{80:20} Herra, Jumala Sebaot, saata meidät entisellemme, valista kasvosi, niin me autetuiksi tulemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Veisuunjohtajalle; veisataan kuin viininkorjuulaulu; Aasafin virsi. {81:2} Nostakaa ilohuuto Jumalalle, joka on meidän väkevyytemme; nostakaa riemuhuuto Jaakobin Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, '{81:3} Virittäkää kiitosvirsi, lyökää vaskirumpuja, soittakaa suloisesti kanteleita ynnä harppuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, '{81:4} Puhaltakaa pasunaa uudenkuun aikana, täyden kuun aikana, meidän juhlapäivämme kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, '{81:5} Sillä tämä on käsky Israelille, Jaakobin Jumalan säädös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, '{81:6} Hän asetti sen todistukseksi Joosefille käydessään Egyptin maata vastaan. Minä kuulen puheen, joka on minulle outo:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, '{81:7} \"Minä nostin taakan hänen hartioiltansa, hänen kätensä pääsivät kantokorin kuormasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, '{81:8} Hädässäsi sinä huusit, ja minä vapautin sinut; ukkospilven peitosta minä vastasin sinulle, minä koettelin sinua Meriban veden luona.\" Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, '{81:9} \"Kuule, kansani, minä varoitan sinua; Israel, jospa sinä minua kuulisit!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, '{81:10} Älköön sinulla olko muukalaista jumalaa, äläkä kumarra vierasta jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, '{81:11} Minä olen Herra, sinun Jumalasi, joka toin sinut Egyptin maasta; avaa suusi, niin minä sen täytän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, '{81:12} Mutta minun kansani ei kuullut minun ääntäni, eikä Israel noudattanut minun mieltäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, '{81:13} Niin minä annoin heidän mennä pois sydämensä paatumuksessa, he saivat vaeltaa omien neuvojensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, '{81:14} Oi, jospa minun kansani minua kuulisi ja Israel vaeltaisi minun teilläni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, '{81:15} niin minä pian masentaisin heidän vihollisensa ja kääntäisin käteni heidän vihamiehiänsä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, '{81:16} Ne, jotka Herraa vihaavat, matelisivat hänen edessään, ja heidän kohtalonsa kestäisi iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, '{81:17} Mutta kansaansa hän ruokkisi parhaalla nisulla; minä ravitsisin sinua hunajalla kalliosta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Aasafin virsi. Jumala seisoo jumalien kokouksessa, hän on tuomari jumalien keskellä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '\"Kuinka kauan te tuomitsette väärin ja pidätte jumalattomain puolta?\" Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, '\"Auttakaa oikeuteensa vaivainen ja orpo, antakaa kurjalle ja puutteenalaiselle oikeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Vapauttakaa vaivainen ja köyhä, pelastakaa hänet jumalattomain käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Ei ole heillä älyä, ei ymmärrystä, he vaeltavat pimeydessä: kaikki maan perustukset horjuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Minä sanon: Te olette jumalia ja kaikki tyynni Korkeimman poikia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'kuitenkin te kuolette, niinkuin ihmiset kuolevat, ja kaadutte niinkuin kuka ruhtinas tahansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Nouse, Jumala, tuomitse maa, sillä sinä perit kaikki pakanakansat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Laulu, Aasafin virsi. {83:2} Jumala, älä ole niin ääneti, älä ole vaiti, älä ole, Jumala, niin hiljaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, '{83:3} Sillä, katso, sinun vihollisesi pauhaavat, ja sinun vihaajasi nostavat päätänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, '{83:4} Heillä on kavalat hankkeet sinun kansaasi vastaan, ja he pitävät neuvoa sinun suojattejasi vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, '{83:5} He sanovat: \"Tulkaa, hävittäkäämme heidät olemasta kansa, niin ettei Israelin nimeä enää muisteta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, '{83:6} Sillä he neuvottelevat keskenään yksimielisesti, he tekevät liiton sinua vastaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, '{83:7} Edomin teltat ja ismaelilaiset, Mooab ja hagrilaiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, '{83:8} Gebal, Ammon ja Amalek, Filistea ynnä Tyyron asukkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, '{83:9} Myös Assur on liittynyt heihin, nämä ovat käsivartena Lootin lapsilla. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, '{83:10} Tee heille, niinkuin teit Midianille, niinkuin Siiseralle, niinkuin Jaabinille Kiison-joen rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, '{83:11} Heidät tuhottiin Eendorissa, he joutuivat lannaksi maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, '{83:12} Anna heidän ylhäisillensä käydä, niinkuin kävi Oorebille ja Seebille, ja kaikille heidän ruhtinaillensa niinkuin Seballe ja Salmunnalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, '{83:13} koska he sanovat: \"Anastakaamme itsellemme Jumalan asunnot\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, '{83:14} Jumalani, tee heidät lentäviksi lehdiksi, kuiviksi korsiksi tuulen viedä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, '{83:15} Niinkuin kulovalkea metsää polttaa, niinkuin liekit kärventävät vuoria,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, '{83:16} niin aja sinä heitä rajuilmallasi ja kauhistuta heitä tuulispäälläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, '{83:17} Täytä heidän kasvonsa häpeällä, että he etsisivät sinun nimeäsi, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, '{83:18} Joutukoot häpeään ja kauhistukoot ikuisesti, tulkoot häpeään ja hukkukoot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, '{83:19} Ja tulkoot tuntemaan, että sinun ainoan nimi on Herra, että sinä olet Korkein kaikessa maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Veisuunjohtajalle; veisataan kuin viininkorjuulaulu; koorahilaisten virsi. {84:2} Kuinka ihanat ovat sinun asuinsijasi, Herra Sebaot!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, '{84:3} Minun sieluni ikävöitsee ja halajaa Herran esikartanoihin, minun sydämeni ja ruumiini pyrkii riemuiten elävää Jumalaa kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, '{84:4} Löysihän lintunen majan ja pääskynen pesän, johon se poikasensa laskee: sinun alttarisi, Herra Sebaot, minun kuninkaani ja minun Jumalani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, '{84:5} Autuaat ne, jotka sinun huoneessasi asuvat! He kiittävät sinua alati. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, '{84:6} Autuaat ne ihmiset, joilla on voimansa sinussa, joilla on mielessänsä pyhät matkat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, '{84:7} Kun he käyvät Kyynellaakson kautta, he muuttavat sen lähteitten maaksi, ja syyssade peittää sen siunauksilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, '{84:8} He käyvät voimasta voimaan, he astuvat Jumalan eteen Siionissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, '{84:9} Herra, Jumala Sebaot, kuule minun rukoukseni, ota se korviisi, Jaakobin Jumala. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, '{84:10} Jumala, meidän kilpemme, käännä katseesi, katso voideltusi kasvoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, '{84:11} Sillä yksi päivä sinun esikartanoissasi on parempi kuin tuhat muualla; mieluummin minä olen vartijana Jumalani huoneen kynnyksellä, kuin asun jumalattomien majoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, '{84:12} Sillä Herra Jumala on aurinko ja kilpi; Herra antaa armon ja kunnian, ei hän kiellä hyvää niiltä, jotka nuhteettomasti vaeltavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, '{84:13} Herra Sebaot, autuas se ihminen, joka sinuun turvaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Veisuunjohtajalle; koorahilaisten virsi. {85:2} Herra, ennen sinä olit suosiollinen maallesi, sinä käänsit Jaakobin kohtalon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, '{85:3} Sinä annoit anteeksi kansasi pahat teot ja peitit kaikki heidän syntinsä. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, '{85:4} Sinä panit kaiken kiivastuksesi pois ja lauhduit vihasi hehkusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, '{85:5} Käänny taas meidän puoleemme, sinä pelastuksemme Jumala, älä ole enää tuimistunut meihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, '{85:6} Oletko ainiaaksi vihastunut meihin, pidätkö vihaa suvusta sukuun?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, '{85:7} Etkö virvoita meitä eloon jälleen, että sinun kansasi iloitsisi sinussa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, '{85:8} Herra, suo meidän nähdä sinun armosi, anna apusi meille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, '{85:9} Minä tahdon kuulla, mitä Jumala, Herra, puhuu: hän puhuu rauhaa kansallensa, hurskaillensa; älkööt he kääntykö jälleen tyhmyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, '{85:10} Totisesti, hänen apunsa on lähellä niitä, jotka häntä pelkäävät, ja niin meidän maassamme kunnia asuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, '{85:11} Armo ja totuus tapaavat toisensa täällä, vanhurskaus ja rauha antavat suuta toisillensa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, '{85:12} uskollisuus versoo maasta, ja vanhurskaus katsoo taivaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, '{85:13} Herra antaa meille kaikkea hyvää, ja meidän maamme antaa satonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, '{85:14} Vanhurskaus käy hänen edellänsä ja seuraa hänen askeltensa jälkiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Daavidin rukous. Kallista, Herra, korvasi minun puoleeni ja vastaa minulle, sillä minä olen kurja ja köyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Varjele minun sieluni, sillä minä olen hurskas; sinä, minun Jumalani, pelasta palvelijasi, joka sinuun turvaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Ole minulle armollinen, Herra, sillä sinua minä huudan kaiken päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Ilahuta palvelijasi sielu, sillä sinun puoleesi, Herra, minä ylennän sieluni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Sillä sinä, Herra, olet hyvä ja anteeksiantavainen, suuri armossa kaikille, jotka sinua avuksensa huutavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Ota, Herra, korviisi minun rukoukseni, tarkkaa minun anomiseni ääntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Hätäni päivänä minä sinua avukseni huudan, sillä sinä vastaat minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Ei ole sinun vertaistasi, Herra, jumalien joukossa, eikä ole vertaa sinun töillesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Kaikki kansat, jotka sinä tehnyt olet, tulevat ja kumartuvat sinun edessäsi, Herra, ja kunnioittavat sinun nimeäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Sillä sinä olet suuri ja teet ihmeitä, sinä ainoa olet Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Neuvo minulle tiesi, Herra, että minä vaeltaisin sinun totuudessasi. Kiinnitä minun sydämeni siihen yhteen, että minä sinun nimeäsi pelkäisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Kaikesta sydämestäni minä kiitän sinua, Herra, minun Jumalani, ja kunnioitan sinun nimeäsi iankaikkisesti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'sillä sinun armosi on suuri minua kohtaan, sinä olet pelastanut minun sieluni tuonelan syvyydestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'Jumala, julkeat ovat nousseet minua vastaan, väkivaltaisten joukko etsii minun henkeäni; eivät he pidä sinua silmäinsä edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Mutta sinä, Herra, olet laupias ja armahtavainen Jumala, pitkämielinen, suuri armossa ja totuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Käänny minun puoleeni, ole minulle armollinen, anna voimasi palvelijallesi, auta palvelijattaresi poikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Tee merkki minulle, minun hyväkseni. Häpeäksensä minun vihaajani nähkööt, että sinä, Herra, minua autat ja lohdutat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Koorahilaisten virsi, laulu. Pyhille vuorille perustamaansa kaupunkia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Siionin portteja, Herra rakastaa enemmän kuin Jaakobin kaikkia muita asuinsijoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'On kunniakasta, mitä sinusta sanotaan, sinä Jumalan kaupunki: -Sela. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, '\"Minä mainitsen tunnustajikseni Rahabin ja Baabelin; katso, Filisteasta, Tyyrosta ja Etiopiasta minä mainitsen: Sekin on syntynyt siellä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Mutta Siionista sanotaan: \"Joka-ainoa on syntynyt siellä\". Sitä Korkein itse vahvana pitää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Herra luettelee, kirjoittaessaan kirjaan kansat: \"Tämäkin on syntynyt siellä\". Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Veisaten, karkeloiden sanotaan: \"Kaikki minun lähteeni ovat sinussa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Koorahilaisten laulu, virsi; veisuunjohtajalle; veisataan kuin: \"Sairaus\"; esrahilaisen Heemanin mietevirsi. {88:2} Herra, minun pelastukseni Jumala, päivin ja öin minä huudan sinun edessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, '{88:3} Salli minun rukoukseni tulla kasvojesi eteen, kallista korvasi minun huutoni puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, '{88:4} Sillä minun sieluni on kärsimyksistä kylläinen, ja minun elämäni on lähellä tuonelaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, '{88:5} Minut luetaan hautaan menevien joukkoon, minä olen kuin mies, jolta voima on poissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, '{88:6} Minä olen jätetty kuolleitten joukkoon, olen kuin kaatuneet, jotka haudassa makaavat ja joita sinä et enää muista ja jotka ovat sinun kädestäsi erotetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, '{88:7} Sinä olet laskenut minut syvimpään hautaan, pimeyteen, syviin kuiluihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, '{88:8} Sinun vihasi painaa minua, ja kaikki kuohusi sinä vyörytät minun ylitseni. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, '{88:9} Sinä olet karkoittanut tuttavani minusta kauas, olet tehnyt minut heille inhoksi; minä olen suljettu sisään enkä pääse ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, '{88:10} Minun kasvoni ovat kuihtuneet kurjuudesta. Joka päivä minä huudan sinua, Herra, ja ojennan käteni sinun puoleesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, '{88:11} Teetkö sinä ihmeitä kuolleille, tai nousevatko haamut sinua kiittämään? Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, '{88:12} Kerrotaanko haudassa sinun armostasi, manalassa sinun uskollisuudestasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, '{88:13} Tunnetaanko sinun ihmeitäsi pimeydessä ja sinun vanhurskauttasi unhotuksen maassa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, '{88:14} Mutta minä huudan avukseni sinua, Herra, ja minun rukoukseni tulee varhain sinun eteesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, '{88:15} Miksi, Herra, hylkäät minun sieluni, miksi peität kasvosi minulta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, '{88:16} Minä olen kurja ja lähellä kuolemaa hamasta nuoruudestani, minä kärsin sinun kauhujasi, olen neuvoton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, '{88:17} Sinun vihasi vyöryy minun ylitseni, sinun hirmusi hukuttavat minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, '{88:18} Ne saartavat minua kaiken päivää kuin vedet, ne kaikki yhdessä piirittävät minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, '{88:19} Ystävät ja toverit sinä olet karkoittanut minusta kauas, pimeys on minun ainoa tuttavani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Esrahilaisen Eetanin mietevirsi. {89:2} Minä laulan Herran armoteoista lakkaamatta, julistan suullani sinun uskollisuuttasi polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, '{89:3} Minä sanon: ikiajoiksi on armo rakennettu, sinä olet perustanut uskollisuutesi taivaisiin. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, '{89:4} \"Minä olen tehnyt liiton valittuni kanssa, olen palvelijalleni Daavidille vannonut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, '{89:5} \'Minä vahvistan sinun jälkeläisesi ikiajoiksi ja rakennan sinulle valtaistuimen polvesta polveen\'\". Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, '{89:6} Ja taivaat ylistävät sinun ihmeitäsi, Herra, ja pyhäin seurakunta sinun uskollisuuttasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, '{89:7} Sillä kuka pilvissä on Herran vertainen, kuka Jumalan poikain joukossa on niinkuin Herra?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, '{89:8} Hän on Jumala, ylen hirmuinen pyhien kokouksessa, peljättävämpi kaikkia, jotka hänen ympärillänsä ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, '{89:9} Herra, Jumala Sebaot, kuka on voimassa sinun vertaisesi, Herra? Ja sinun uskollisuutesi ympäröitsee sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, '{89:10} Sinä hallitset meren raivon; kun sen aallot kohoavat, sinä ne asetat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, '{89:11} Sinä ruhjoit Rahabin kuin sodassa kaatuneen; väkevällä käsivarrellasi sinä ajoit vihollisesi hajalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, '{89:12} Sinun ovat taivaat, sinun on myös maa; maanpiirin täysinensä sinä olet perustanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, '{89:13} Sinä loit pohjoisen ja etelän; sinun nimestäsi riemuitsevat Taabor ja Hermon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, '{89:14} Sinulla on käsivarsi voimaa täynnä, väkevä on sinun kätesi, korotettu sinun oikea kätesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, '{89:15} Vanhurskaus ja oikeus on sinun valtaistuimesi perustus, armo ja totuus käy sinun kasvojesi edellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, '{89:16} Autuas se kansa, joka tuntee juhlariemun, ne, jotka vaeltavat sinun kasvojesi valkeudessa, Herra!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, '{89:17} He riemuitsevat sinun nimestäsi kaikkina päivinänsä, ja sinun vanhurskautesi voimasta heidät korotetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, '{89:18} Sillä sinä olet heidän väkevyytensä, heidän kaunistuksensa, ja sinä armossasi kohotat meidän sarvemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, '{89:19} Sillä meidän kilpemme on Herran huomassa, meidän kuninkaamme on Israelin Pyhän huomassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, '{89:20} Silloin sinä näyssä puhuit hurskaillesi ja sanoit: \"Minä olen pannut avun sankarin käteen, olen kansan keskeltä korottanut valittuni:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, '{89:21} minä olen löytänyt Daavidin, palvelijani, olen voidellut hänet pyhällä öljylläni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, '{89:22} Minun käteni on lujasti tukeva häntä, minun käsivarteni on häntä vahvistava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, '{89:23} Ei vihollinen yllätä häntä, eikä vääryyden mies häntä sorra;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, '{89:24} vaan minä hävitän hänen ahdistajansa hänen edestänsä ja lyön hänen vihamiehensä maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, '{89:25} Minun uskollisuuteni ja armoni on hänen kanssansa, ja minun nimessäni kohoaa hänen sarvensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, '{89:26} Minä asetan hänen kätensä vallitsemaan merta ja virtoja hänen oikean kätensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, '{89:27} Hän kutsuu minua: \'Sinä olet minun isäni, sinä minun Jumalani ja pelastukseni kallio\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, '{89:28} Ja minä asetan hänet esikoiseksi, maan kuninkaista korkeimmaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, '{89:29} Minä säilytän armoni hänelle iankaikkisesti, ja minun liittoni hänen kanssaan on luja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, '{89:30} Minä annan hänen jälkeläistensä säilyä iäti ja hänen valtaistuimensa niin kauan, kuin taivaat pysyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, '{89:31} Jos hänen poikansa hylkäävät minun lakini eivätkä vaella minun oikeuksieni mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, '{89:32} jos he minun säädökseni rikkovat eivätkä noudata minun käskyjäni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, '{89:33} niin minä rankaisen vitsalla heidän rikoksensa ja heidän pahat tekonsa vitsauksilla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, '{89:34} mutta armoani en minä ota häneltä pois enkä vilpistele uskollisuudestani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, '{89:35} En minä liittoani riko, enkä muuta sitä, mikä on minun huuliltani lähtenyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, '{89:36} Minä olen kerran vannonut pyhyyteni kautta, ja totisesti, minä en Daavidille valhettele:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, '{89:37} \'Hänen jälkeläisensä pysyvät iankaikkisesti, ja hänen valtaistuimensa on minun edessäni niinkuin aurinko,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, '{89:38} se pysyy lujana iankaikkisesti niinkuin kuu. Ja todistaja pilvissä on uskollinen\'.\" Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, '{89:39} Ja kuitenkin sinä hylkäsit voideltusi ja pidit häntä halpana ja olet vihastunut häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, '{89:40} Sinä olet purkanut palvelijasi liiton, olet häväissyt hänen kruununsa, olet heittänyt sen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, '{89:41} Sinä olet särkenyt kaikki hänen muurinsa, olet pannut raunioiksi hänen linnoituksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, '{89:42} Kaikki tien kulkijat ovat häntä ryöstäneet, hän on joutunut naapuriensa häväistäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, '{89:43} Sinä olet korottanut hänen vihollistensa oikean käden, olet tuottanut ilon kaikille hänen vihamiehillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, '{89:44} Sinä olet kääntänyt takaisin hänen miekkansa terän etkä ole sodassa pitänyt häntä pystyssä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, '{89:45} Sinä olet tehnyt hänen loistostansa lopun ja olet syössyt maahan hänen valtaistuimensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, '{89:46} Sinä olet lyhentänyt hänen nuoruutensa päivät, olet hänet häpeällä peittänyt. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, '{89:47} Kuinka kauan sinä, Herra, itsesi yhäti kätket? Kuinka kauan sinun vihasi tulena palaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, '{89:48} Muista, kuinka lyhyt minun elämäni on, kuinka katoavaisiksi sinä olet luonut kaikki ihmislapset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, '{89:49} Kuka on se mies, joka jää eloon eikä kuoloa näe, joka pelastaa sielunsa tuonelan kädestä? Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, '{89:50} Herra, missä ovat sinun entiset armotekosi, jotka sinä uskollisuudessasi vannoit Daavidille?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, '{89:51} Ajattele, Herra, palvelijaisi häpäisyä ja mitä minun kaikilta noilta monilta kansoilta täytyy povessani kestää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, '{89:52} kun, Herra, sinun vihollisesi herjaavat, herjaavat sinun voideltusi askeleita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, '{89:53} Kiitetty olkoon Herra iankaikkisesti. Amen, amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Mooseksen, Jumalan miehen, rukous. Herra, sinä olet meidän turvamme polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Ennenkuin vuoret syntyivät ja sinä loit maan ja maanpiirin, iankaikkisesta iankaikkiseen olet sinä, Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Sinä palautat ihmiset takaisin tomuun ja sanot: \"Palatkaa jälleen, te ihmisten lapset\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Sillä tuhat vuotta on sinun silmissäsi niinkuin eilinen päivä, joka meni ohitse, ja niinkuin öinen vartiohetki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Sinä huuhdot heidät pois; he ovat kuin uni, ovat kuin ruoho, joka aamulla kukoistaa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'aamulla se kasvaa ja kukoistaa, mutta illalla se leikataan ja kuivettuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Sillä me hukumme sinun vihasi voimasta, ja sinun kiivastuksesi voimasta me häviämme pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Meidän pahat tekomme sinä asetat eteesi, salaiset syntimme kasvojesi valkeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Niin kaikki meidän päivämme kuluvat sinun vihasi alla, vuotemme päättyvät meiltä kuin huokaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Meidän elinpäivämme ovat seitsemänkymmentä vuotta taikka enintään kahdeksankymmentä vuotta; ja parhaimmillaankin ne ovat vaiva ja turhuus, sillä ne kiitävät ohitse, niinkuin me lentäisimme pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Kuka ajattelee sinun vihasi ankaruutta, sinun kiivauttasi, niin että hän sinua pelkäisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Opeta meitä laskemaan päivämme oikein, että me saisimme viisaan sydämen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Herra, palaja jälleen. Voi, kuinka kauan? Armahda palvelijoitasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Ravitse aamulla meitä armollasi, suo meille iloa ja riemua kaikkina päivinämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Suo meidän iloita yhtä monta päivää, kuin olet nöyryyttänyt meitä, yhtä monta vuotta, kuin olemme kovaa kokeneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Saakoot palvelijasi nähdä sinun tekosi ja heidän lapsensa sinun kunniasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Ja tulkoon osaksemme Herran, meidän Jumalamme, laupeus. Suo menestyä meille kättemme työn; niin, suo menestyä meidän kättemme työn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Joka Korkeimman suojassa istuu ja Kaikkivaltiaan varjossa yöpyy,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'se sanoo: \"Herra on minun turvani ja linnani, hän on minun Jumalani, johon minä turvaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Sillä hän päästää sinut linnustajan paulasta, turmiollisesta rutosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Sulillansa hän sinua suojaa, ja sinä saat turvan hänen siipiensä alla; hänen uskollisuutensa on kilpi ja suojus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Et sinä pelkää yön kauhuja, et päivällä lentävää nuolta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'et ruttoa, joka pimeässä kulkee, et kulkutautia, joka päiväsydännä häviötä tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Vaikka tuhat kaatuisi sinun sivultasi, kymmenen tuhatta oikealta puoleltasi, ei se sinuun satu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Sinun silmäsi saavat vain katsella ja nähdä, kuinka jumalattomille kostetaan. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Sillä: \"Sinä, Herra, olet minun turvani\". -Korkeimman olet sinä ottanut suojaksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Ei kohtaa sinua onnettomuus, eikä vitsaus lähesty sinun majaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Sillä hän antaa enkeleilleen sinusta käskyn varjella sinua kaikilla teilläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'He kantavat sinua käsillänsä, ettet jalkaasi kiveen loukkaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Sinä kuljet leijonan ja kyykäärmeen ylitse, sinä tallaat nuorta jalopeuraa ja lohikäärmettä. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, '\"Koska hän riippuu minussa kiinni, niin minä hänet pelastan; minä suojelen hänet, koska hän tuntee minun nimeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Hän huutaa minua avuksensa, ja minä vastaan hänelle, minä olen hänen tykönänsä, kun hänellä on ahdistus, minä vapahdan hänet ja saatan hänet kunniaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Minä ravitsen hänet pitkällä iällä ja suon hänen nähdä antamani pelastuksen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Virsi, sapatinpäivä-laulu. {92:2} Hyvä on Herraa kiittää ja veisata kiitosta sinun nimellesi, sinä Korkein,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, '{92:3} aamulla julistaa sinun armoasi ja yön tullen sinun totuuttasi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, '{92:4} kymmenkielisillä soittimilla ja harpuilla, kannelta soittaen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, '{92:5} Sillä sinä ilahutat minua, Herra, töilläsi; minä riemuitsen sinun kättesi teoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, '{92:6} Kuinka suuret ovat sinun tekosi, Herra! Sinun ajatuksesi ovat ylen syvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, '{92:7} Järjetön mies ei tätä ymmärrä, eikä sitä älyä tomppeli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, '{92:8} Kun jumalattomat rehottavat niinkuin ruoho ja väärintekijät kaikki kukoistavat, on se heidän ikuiseksi häviöksensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, '{92:9} Mutta sinä, Herra, olet korkea iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, '{92:10} Sillä katso, sinun vihollisesi, Herra, katso, sinun vihollisesi hukkuvat, kaikki väärintekijät joutuvat hajallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, '{92:11} Mutta minun sarveni sinä kohotat kuin villihärän sarvet; minut voidellaan tuoreella öljyllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, '{92:12} Ja iloiten minun silmäni katsovat vainoojiani, minun korvani kuulevat noista pahoista, jotka ovat nousseet minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, '{92:13} Vanhurskas viheriöitsee kuin palmupuu, hän kasvaa kuin Libanonin setri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, '{92:14} He ovat istutetut Herran huoneeseen, he viheriöitsevät meidän Jumalamme kartanoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, '{92:15} Vielä vanhuudessaan he tekevät hedelmää, ovat mehevät ja vihannat');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, '{92:16} ja julistavat, että Herra on vanhurskas, hän, minun kallioni, ja ettei hänessä vääryyttä ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Herra on kuningas. Hän on pukenut itsensä korkeudella. Herra on pukeutunut, vyöttäytynyt voimaan. Niin pysyy maanpiiri lujana, se ei horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Sinun valtaistuimesi on vahva aikojen alusta, hamasta iankaikkisuudesta olet sinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Vesivirrat nostavat, Herra, vesivirrat nostavat pauhinansa, niin, vesivirrat nostavat kuohunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Mutta yli suurten, voimallisten vetten pauhinan, yli meren kuohujen on Herra korkeudessa voimallinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Sinun todistuksesi ovat aivan vahvat, pyhyys on sinun huoneellesi arvollinen, Herra, hamaan aikojen loppuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Sinä koston Jumala, Herra, sinä koston Jumala, ilmesty kirkkaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Nouse, maan tuomari, kosta ylpeille heidän tekonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Kuinka kauan jumalattomat, Herra, kuinka kauan jumalattomat saavat riemuita?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Ne syytävät suustaan julkeita sanoja, ne röyhkeilevät, kaikki nuo väärintekijät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Sinun kansaasi, Herra, he runtelevat, ja sinun perintöosaasi he rasittavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'He tappavat leskiä ja muukalaisia ja murhaavat orpoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Ja he sanovat: \"Ei Herra sitä näe, ei Jaakobin Jumala sitä huomaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Ymmärtäkää, te kansan järjettömät, ja te tomppelit-milloin te tulette järkiinne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Joka on korvan istuttanut, hänkö ei kuulisi? Joka on silmän luonut, hänkö ei näkisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Joka kansat kasvattaa, hänkö ei rankaisisi, hän, joka ihmisille opettaa tiedon?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Herra tuntee ihmisten ajatukset; sillä he ovat kuin tuulen henkäys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Autuas se mies, jota sinä, Herra, kuritat ja jolle sinä opetat lakisi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'antaaksesi hänelle rauhan pahoilta päiviltä, kunnes jumalattomalle on kaivettu hauta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Sillä Herra ei hylkää kansaansa eikä perintöosaansa heitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'vaan oikeus on vielä noudattava vanhurskautta, ja kaikki oikeamieliset seuraavat sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Kuka nousee minun puolelleni pahoja vastaan, kuka asettuu minun rinnalleni väärintekijöitä vastaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Ellei Herra olisi minun apuni, pian minun sieluni asuisi hiljaisuuden maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Kun minä ajattelen: \"Minun jalkani horjuu\", niin sinun armosi, Herra, minua tukee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Kun minulla on sydämessäni paljon murheita, niin sinun lohdutuksesi ilahuttaa minun sieluni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Onko yhteyttä sinun kanssasi turmion tuomioistuimella, jossa väkivaltaa tehdään lain varjolla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'ahdistetaan vanhurskaan sielua ja tuomitaan syylliseksi viaton veri?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Mutta Herra on minun linnani, Jumalani on minun suojakallioni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Hän kostaa heille heidän ilkityönsä ja hukuttaa heidät heidän pahuutensa tähden. Herra, meidän Jumalamme, hukuttaa heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Tulkaa, kohottakaamme ilohuuto Herralle, riemuhuuto pelastuksemme kalliolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Käykäämme kiittäen hänen kasvojensa eteen, veisatkaamme hänelle riemuvirsiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Sillä Herra on suuri Jumala, suuri kuningas yli kaikkien jumalien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'Maan syvyydet ovat hänen kädessänsä, ja hänen ovat vuorten kukkulat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Hänen on meri, sillä hän on sen tehnyt, ja kuiva maa, jonka hänen kätensä ovat valmistaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Tulkaa, kumartukaamme ja polvistukaamme, polvillemme langetkaamme Herran, meidän Luojamme, eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Sillä hän on meidän Jumalamme, ja me olemme kansa, jota hän paimentaa, lauma, jota hänen kätensä kaitsee. Jospa te tänä päivänä kuulisitte hänen äänensä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, '\"Älkää paaduttako sydäntänne, niinkuin Meribassa, niinkuin Massan päivänä erämaassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'jossa teidän isänne minua kiusasivat, jossa he koettelivat minua, vaikka olivat nähneet minun tekoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Neljäkymmentä vuotta minä olin kyllästynyt siihen sukuun ja sanoin: \'He ovat kansa, jonka sydän on eksynyt, eivätkä he tahdo tietää minun teistäni\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Ja niin minä vihassani vannoin: \'He eivät pääse minun lepooni\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Veisatkaa Herralle uusi virsi, veisatkaa Herralle, kaikki maa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Veisatkaa Herralle, ylistäkää hänen nimeänsä. Julistakaa päivästä päivään hänen pelastustekojansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'ilmoittakaa pakanain seassa hänen kunniaansa, hänen ihmeitänsä kaikkien kansojen seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Sillä Herra on suuri ja sangen ylistettävä, hän on peljättävä yli kaikkien jumalain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Sillä kaikki kansojen jumalat ovat epäjumalia, mutta Herra on tehnyt taivaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Herraus ja kunnia on hänen kasvojensa edessä, kiitos ja ylistys hänen pyhäkössänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Antakaa Herralle, te kansojen sukukunnat, antakaa Herralle kunnia ja väkevyys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Antakaa Herralle hänen nimensä kunnia, tuokaa lahjoja, tulkaa hänen esikartanoihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Kumartakaa Herraa pyhässä kaunistuksessa, vaviskaa hänen kasvojensa edessä, kaikki maa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Sanokaa pakanain seassa: \"Herra on kuningas\". Niin pysyy maanpiiri lujana, se ei horju. Hän tuomitsee kansat oikeuden mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Iloitkoot taivaat, ja riemuitkoon maa; pauhatkoon meri ja kaikki, mitä siinä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Ihastukoot kedot ja kaikki, mitä kedolla on, riemuitkoot silloin kaikki metsän puut');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Herran edessä, sillä hän tulee, sillä hän tulee tuomitsemaan maata: hän tuomitsee maanpiirin vanhurskaudessa ja kansat uskollisuudessansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Herra on kuningas! Riemuitkoon maa; iloitkoot saaret, niin monta kuin niitä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Pilvi ja pimeys on hänen ympärillänsä, vanhurskaus ja oikeus on hänen valtaistuimensa perustus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Tuli käy hänen edellänsä ja polttaa hänen vihollisensa, yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Hänen salamansa valaisevat maanpiirin; maa näkee sen ja vapisee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Vuoret sulavat niinkuin vaha Herran edessä, kaiken maan Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Taivaat julistavat hänen vanhurskauttansa, ja kaikki kansat näkevät hänen kunniansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Kaikki kuvain kumartajat joutuvat häpeään, kaikki, jotka epäjumalista kerskaavat. Kumartakaa häntä, kaikki jumalat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Siion kuulee sen ja iloitsee, ja Juudan tyttäret riemuitsevat sinun tuomioistasi, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Sillä sinä, Herra, olet Korkein yli kaiken maan, sinä olet ylen korkea, ylitse kaikkien jumalain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Te, jotka Herraa rakastatte, vihatkaa pahaa. Hän varjelee hurskasten sielut, jumalattomien kädestä hän heidät pelastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Vanhurskaalle koittaa valkeus ja oikeamielisille ilo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Iloitkaa Herrassa, te vanhurskaat; kiittäkää hänen pyhää nimeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Virsi. Veisatkaa Herralle uusi virsi, sillä hän on ihmeitä tehnyt. Hän on saanut voiton oikealla kädellänsä ja pyhällä käsivarrellansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Herra on tehnyt tiettäväksi pelastustekonsa, hän on ilmaissut vanhurskautensa pakanain silmien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Hän on muistanut armonsa ja uskollisuutensa Israelin heimoa kohtaan; kaikki maan ääret ovat nähneet meidän Jumalamme pelastusteot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Kohottakaa riemuhuuto Herralle, kaikki maa, iloitkaa ja riemuitkaa ja veisatkaa kiitosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Veisatkaa Herran kiitosta kanteleilla-kanteleilla ja ylistysvirren sävelillä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'vaskitorvilla ja pasunan äänellä. Kohottakaa riemuhuuto Herran, kuninkaan, edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Pauhatkoon meri ja kaikki, mitä siinä on, maanpiiri ja ne, jotka siinä asuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Paukuttakoot käsiänsä virrat, ja vuoret yhdessä riemuitkoot');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Herran edessä; sillä hän tulee tuomitsemaan maata. Hän tuomitsee maanpiirin vanhurskaasti ja kansat oikeuden mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Herra on kuningas, vaviskoot kansat-hän, jonka valtaistuinta kerubit kannattavat-huojukoon maa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Suuri on Herra Siionissa, hän on korkea yli kaikkien kansojen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'He ylistävät sinun suurta ja peljättävää nimeäsi. Hän on pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Se on kuninkaan voima, että hän rakastaa oikeutta. Sinä olet saattanut oikeuden voimaan, sinä toimitat oikeuden ja vanhurskauden Jaakobissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Ylistäkää Herraa, meidän Jumalaamme, kumartukaa hänen jalkainsa astinlaudan eteen. Hän on pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mooses ja Aaron hänen pappiensa joukossa ja Samuel niiden joukossa, jotka avuksi huusivat hänen nimeänsä, he huusivat Herraa, ja hän vastasi heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Hän puhui heille pilvenpatsaasta; he noudattivat hänen todistuksiansa ja käskyjä, jotka hän oli heille antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Herra, meidän Jumalamme, sinä vastasit heille, olit heille anteeksiantava Jumala, vaikka sinä heidän pahat tekonsa kostit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Ylistäkää Herraa, meidän Jumalaamme, rukoilkaa kumartuneina hänen pyhää vuortansa kohti; sillä Herra, meidän Jumalamme, on pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Kiitosuhri-virsi. Kohottakaa riemuhuuto Herralle, kaikki maa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Palvelkaa Herraa ilolla, tulkaa hänen kasvojensa eteen riemulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Tietäkää, että Herra on Jumala. Hän on meidät tehnyt, ja hänen me olemme, hänen kansansa ja hänen laitumensa lampaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Käykää hänen portteihinsa kiittäen, hänen esikartanoihinsa ylistystä veisaten. Ylistäkää häntä, kiittäkää hänen nimeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Sillä Herra on hyvä; hänen armonsa pysyy iankaikkisesti ja hänen uskollisuutensa polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Daavidin virsi. Minä veisaan armosta ja oikeudesta; sinun ylistystäsi, Herra, minä laulan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Minä tahdon noudattaa nuhteetonta vaellusta; milloin tulet sinä minun tyköni? Minä tahdon vaeltaa huoneessani vilpittömällä sydämellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'En kiinnitä silmääni siihen, mikä turmiollista on, eksyttäväistä menoa minä vihaan: ei saa se minuun tarttua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Nurja sydän väistyköön minusta; pahasta minä en tahdo tietää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Joka salaa panettelee lähimmäistänsä, sen minä hukutan; jolla on ylpeät silmät ja kopea sydän, sitä minä en siedä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Maan uskollisia minun silmäni etsivät, että he asuisivat minua lähellä; joka vaeltaa nuhteettomuuden tietä, se on oleva minun palvelijani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Vilpin tekijä älköön asuko minun huoneessani, valheen puhuja ei kestä minun silmäini edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Joka aamu minä hukutan kaikki jumalattomat maasta, lopettaakseni kaikki väärintekijät Herran kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Kurjan rukous, kun hän on näännyksissä ja vuodattaa valituksensa Herran eteen. {102:2} Herra, kuule minun rukoukseni, ja minun huutoni tulkoon sinun eteesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, '{102:3} Älä peitä minulta kasvojasi, kun minulla on ahdistus, kallista korvasi minun puoleeni. Kun minä huudan, riennä ja vastaa minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, '{102:4} Sillä minun päiväni ovat haihtuneet kuin savu, ja minun luitani polttaa niinkuin ahjossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, '{102:5} Sydämeni on paahtunut ja kuivunut kuin ruoho, sillä minä unhotan syödä leipääni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, '{102:6} Äänekkäästä vaikerruksestani minun luuni tarttuvat minun nahkaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, '{102:7} Minä olen kuin pelikaani erämaassa, olen kuin huuhkaja raunioissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, '{102:8} Minä olen uneton, olen kuin yksinäinen lintu katolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, '{102:9} Kaiken päivää viholliseni minua häpäisevät; ne, jotka riehuvat minua vastaan, kiroavat minun nimeni kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, '{102:10} Sillä minä syön tuhkaa kuin leipää ja sekoitan juomani kyyneleillä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, '{102:11} sinun vihasi ja kiivastuksesi tähden, sillä sinä olet nostanut minut ylös ja viskannut pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, '{102:12} Minun päiväni ovat kuin pitenevä varjo, ja minä kuivun kuin ruoho.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, '{102:13} Mutta sinä, Herra, hallitset iankaikkisesti, sinun muistosi pysyy polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, '{102:14} Nouse ja armahda Siionia, sillä aika on tehdä sille laupeus ja määrähetki on tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, '{102:15} Sillä sen kivet ovat sinun palvelijoillesi rakkaat, ja sen soraläjiä heidän on sääli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, '{102:16} Silloin pakanat pelkäävät Herran nimeä ja kaikki maan kuninkaat sinun kunniaasi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, '{102:17} kun Herra rakentaa Siionin ja ilmestyy kunniassansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, '{102:18} kun hän kääntyy niiden rukouksen puoleen, jotka ovat kaikkensa menettäneet, eikä enää heidän rukoustansa hylkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, '{102:19} Tämä kirjoitettakoon tulevalle polvelle, ja kansa, joka vastedes luodaan, on kiittävä Herraa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, '{102:20} että hän katseli pyhästä korkeudestaan, että Herra katsoi taivaasta maahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, '{102:21} kuullaksensa vankien huokaukset, vapauttaaksensa kuoleman lapset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, '{102:22} jotta Siionissa julistettaisiin Herran nimeä ja hänen ylistystänsä Jerusalemissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, '{102:23} kun kaikki kansat kokoontuvat yhteen, ja valtakunnat, palvelemaan Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, '{102:24} Hän on lannistanut matkalla minun voimani, on lyhentänyt minun päiväni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, '{102:25} Minä sanon: Jumalani, älä tempaa minua pois kesken ikääni; sinun vuotesi kestävät suvusta sukuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, '{102:26} Muinoin sinä perustit maan, ja taivaat ovat sinun käsialasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, '{102:27} Ne katoavat, mutta sinä pysyt, ne vanhenevat kaikki kuin vaate; sinä muutat ne, niinkuin vaatteet muutetaan, ja ne muuttuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, '{102:28} Mutta sinä pysyt samana, eivätkä sinun vuotesi lopu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, '{102:29} Sinun palvelijaisi lapset saavat asua turvassa, ja heidän jälkeläisensä pysyvät sinun edessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Daavidin virsi. Kiitä Herraa, minun sieluni, ja kaikki, mitä minussa on, hänen pyhää nimeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Kiitä Herraa, minun sieluni, äläkä unhota, mitä hyvää hän on sinulle tehnyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'hän, joka antaa kaikki sinun syntisi anteeksi ja parantaa kaikki sinun sairautesi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'joka lunastaa sinun henkesi tuonelasta ja kruunaa sinut armolla ja laupeudella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'joka sinun halajamisesi tyydyttää hyvyydellään, niin että sinun nuoruutesi uudistuu kuin kotkan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Herra tekee vanhurskauden ja hankkii oikeuden kaikille sorretuille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Hän on tehnyt Moosekselle tunnetuksi tiensä, Israelin lapsille suuret tekonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Laupias ja armahtavainen on Herra, pitkämielinen ja suuri armossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Ei hän aina riitele eikä pidä vihaa iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Ei hän tee meille syntiemme mukaan eikä kosta meille pahain tekojemme mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Sillä niin korkealla kuin taivas on maasta, niin voimallinen on hänen armonsa niitä kohtaan, jotka häntä pelkäävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Niin kaukana kuin itä on lännestä, niin kauas hän siirtää meistä rikkomuksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Niinkuin isä armahtaa lapsiansa, niin Herrakin armahtaa pelkääväisiänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Sillä hän tietää, minkäkaltaista tekoa me olemme: hän muistaa meidät tomuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Ihmisen elinpäivät ovat niinkuin ruoho, hän kukoistaa niinkuin kukkanen kedolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Kun tuuli käy hänen ylitsensä, ei häntä enää ole, eikä hänen asuinsijansa häntä enää tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Mutta Herran armo pysyy iankaikkisesta iankaikkiseen niille, jotka häntä pelkäävät, ja hänen vanhurskautensa lasten lapsille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'niille, jotka pitävät hänen liittonsa ja muistavat hänen käskynsä ja noudattavat niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Herra on pystyttänyt istuimensa taivaisiin, ja hänen kuninkuutensa hallitsee kaikkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Kiittäkää Herraa, te hänen enkelinsä, te väkevät sankarit, jotka hänen käskynsä täytätte, kun kuulette hänen sanansa äänen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Kiittäkää Herraa, kaikki hänen sotaväkensä, te hänen palvelijansa, jotka hänen tahtonsa teette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Kiittäkää Herraa, kaikki hänen tekonsa, hänen valtakuntansa kaikissa paikoissa. Kiitä, minun sieluni, Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Kiitä Herraa, minun sieluni, Herra, minun Jumalani, sinä olet ylen suuri; valkeus ja kirkkaus on sinun pukusi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Sinä verhoudut valoon niinkuin viittaan, sinä levität taivaat niinkuin teltan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'sinä rakennat salisi vetten päälle, teet pilvet vaunuiksesi ja kuljet tuulen siivillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Sinä teet tuulet sanasi saattajiksi, palvelijoiksesi tulen liekit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Sinä asetit maan perustuksillensa, niin että se pysyy horjumatta iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Sinä peitit sen syvyyden vesillä kuin vaatteella: vuoria ylempänä seisoivat vedet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Mutta ne pakenivat sinun nuhteluasi, sinun jylinääsi ne juoksivat pakoon;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'vuoret kohosivat ja laaksot laskeutuivat paikkoihin, jotka sinä olit niille valmistanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Sinä panit rajan, jonka yli vedet eivät käy eivätkä palaja peittämään maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Sinä kuohutit laaksoista lähteet, jotka vuorten välillä vuotavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Ne antavat juoman kaikille metsän eläimille, villiaasit niistä janonsa sammuttavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Niiden partailla asuvat taivaan linnut ja visertävät lehvien välissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Saleistasi sinä kastelet vuoret, sinun töittesi hedelmistä maa saa ravintonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Sinä kasvatat ruohon karjalle ja kasvit ihmisen tarpeeksi. Niin sinä tuotat maasta leivän');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'ja viinin, joka ilahuttaa ihmisen sydämen; niin sinä saatat kasvot öljystä kiiltäviksi, ja leipä vahvistaa ihmisen sydäntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Ravintonsa saavat myös Herran puut, Libanonin setrit, jotka hän on istuttanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Niissä lintuset pesivät, ja haikaroilla on majansa kypresseissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Korkeat vuoret ovat kauristen hallussa, kallionkolot ovat tamaanien suoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Kuun sinä olet tehnyt näyttämään aikoja; aurinko tietää laskunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Sinä teet pimeän, niin tulee yö; silloin lähtevät liikkeelle kaikki metsän eläimet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Nuoret jalopeurat kiljuvat saalista ja pyytävät Jumalalta elatustansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Aurinko nousee, ne vetäytyvät pois ja laskeutuvat luoliinsa maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Silloin ihminen menee töihinsä ja askaroitsee iltaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Kuinka moninaiset ovat sinun tekosi, Herra! Sinä olet ne kaikki viisaasti tehnyt, maa on täynnä sinun luotujasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Merikin, suuri ja aava-siinä vilisee lukemattomat laumat pieniä ja suuria eläviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Siellä kulkevat laivat, siellä Leviatan, jonka sinä olet luonut siinä leikitsemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Ne kaikki odottavat sinua, että antaisit heille ruuan ajallansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Sinä annat niille, ja ne kokoavat, sinä avaat kätesi, ja ne ravitaan hyvyydellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Sinä peität kasvosi, ja ne peljästyvät, sinä otat pois niiden hengen, ne kuolevat ja palajavat tomuun jälleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Sinä lähetät henkesi, ja ne luodaan; ja sinä uudistat maan muodon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Pysyköön Herran kunnia iankaikkisesti. Saakoon Herra teoistansa iloita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'hän, joka katsahtaa maahan, ja se vapisee, joka koskettaa vuoria, ja ne suitsuavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Kaiken ikäni minä ylistän Herraa, minä veisaan Jumalani kiitosta, niin kauan kuin elän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Olkoot minun tutkisteluni hänelle otolliset; minä iloitsen Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Hävitkööt syntiset maasta, älköön jumalattomia enää olko. Kiitä Herraa, minun sieluni. Halleluja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Kiittäkää Herraa, julistakaa hänen nimeänsä, tehkää hänen suuret tekonsa tiettäviksi kansojen keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Laulakaa hänelle, veisatkaa hänelle, puhukaa kaikista hänen ihmeistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Hänen pyhä nimensä olkoon teidän kerskauksenne; iloitkoon niiden sydän, jotka etsivät Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Kysykää Herraa ja hänen voimaansa, etsikää alati hänen kasvojansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Muistakaa hänen ihmetöitänsä, jotka hän on tehnyt, hänen ihmeitänsä ja hänen suunsa tuomioita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'te Aabrahamin, hänen palvelijansa, siemen, Jaakobin lapset, te hänen valittunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Hän, Herra, on meidän Jumalamme; hänen tuomionsa käyvät yli kaiken maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Hän muistaa liittonsa iankaikkisesti, säätämänsä sanan hamaan tuhansiin polviin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'liittonsa, jonka hän teki Aabrahamin kanssa, ja Iisakille vannomansa valan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Hän vahvisti sen käskyksi Jaakobille, Israelille iankaikkiseksi liitoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Hän sanoi: \"Sinulle minä annan Kanaanin maan, se olkoon teidän perintöosanne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Heitä oli vähäinen joukko, vain harvoja, ja he olivat muukalaisia siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Ja he vaelsivat kansasta kansaan ja yhdestä valtakunnasta toiseen kansaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Hän ei sallinut kenenkään heitä vahingoittaa, ja hän rankaisi kuninkaita heidän tähtensä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, '\"Älkää koskeko minun voideltuihini, älkää tehkö pahaa minun profeetoilleni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Ja kun hän kutsui nälänhädän maahan ja kokonaan mursi leivän tuen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'oli hän lähettänyt heidän edellänsä miehen: Joosef oli myyty orjaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Hänen jalkojansa vaivattiin kahleilla, hän joutui rautoihin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'siksi kunnes hänen sanansa kävi toteen ja Herran puhe osoitti hänet puhtaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Niin kuningas lähetti ja päästätti hänet, kansojen hallitsija laski hänet irti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Hän pani hänet talonsa herraksi ja kaiken omaisuutensa haltijaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'sitomaan mielensä mukaan hänen ruhtinaitansa ja opettamaan viisautta vanhimmille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Niin joutui Israel Egyptiin, Jaakob muukalaiseksi Haamin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Ja Herra teki kansansa hyvin hedelmälliseksi ja väkevämmäksi heidän vihamiehiänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Hän käänsi näitten sydämen vihaamaan hänen kansaansa, kavalasti kohtelemaan hänen palvelijoitaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Hän lähetti Mooseksen, palvelijansa, ja Aaronin, jonka hän oli valinnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Nämä tekivät hänen tunnustekonsa heidän keskellään, tekivät ihmeitä Haamin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Hän lähetti pimeyden ja pimensi kaiken, eivätkä he vastustaneet hänen sanojansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Hän muutti heidän vetensä vereksi ja kuoletti heiltä kalat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Heidän maansa vilisi sammakoita aina kuningasten kammioita myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Hän käski, ja paarmoja tuli ja sääskiä koko heidän alueellensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Hän antoi heille rakeita sateen sijaan, tulen leimauksia heidän maahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Ja hän hävitti heidän viini-ja viikunapuunsa ja murskasi puut heidän alueeltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Hän käski, ja heinäsirkkoja tuli ja tuhosirkkoja lukematon joukko;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'ne söivät kaiken ruohon heidän maastansa, söivät hedelmän heidän vainioiltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Ja hän surmasi kaikki heidän maansa esikoiset, kaikki heidän miehuutensa ensimmäiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Sitten hän vei Israelin sieltä varustettuna hopealla ja kullalla, eikä ollut hänen sukukunnissaan kompastuvaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Egypti iloitsi heidän lähdöstänsä, koska sen oli vallannut pelko heidän tähtensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Hän levitti suojaksi pilven ja tulen valaisemaan yötä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'He pyysivät, ja hän pani tulemaan viiriäiset, ja hän ravitsi heitä taivaan leivällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Hän avasi kallion, ja vettä vuoti; se juoksi virtana kautta erämaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Sillä hän muisti pyhän sanansa, muisti Aabrahamia, palvelijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Niin hän vei kansansa pois sen iloitessa, valittunsa heidän riemuitessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Ja hän antoi heille pakanain maat, ja he ottivat omaksensa kansojen vaivannäöt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'että he noudattaisivat hänen käskyjänsä ja ottaisivat hänen laeistansa vaarin. Halleluja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Halleluja! Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Kuka voi kertoa Herran voimalliset teot, julistaa kaiken hänen ylistyksensä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Autuaat ne, jotka noudattavat oikeutta, jotka aina tekevät vanhurskauden!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Muista minua, Herra, armolla, jota kansallesi osoitat, etsi minua avullasi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'että minä näkisin sinun valittujesi onnen, iloitsisin sinun kansasi ilolla, kerskaisin sinun perintöosasi kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Me olemme tehneet syntiä isäimme kanssa, me olemme pahoin tehneet ja olleet jumalattomat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Eivät meidän isämme Egyptissä painaneet mieleensä sinun ihmeitäsi, eivät muistaneet sinun monia armotekojasi, vaan niskoittelivat meren rannalla, Kaislameren rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Kuitenkin hän pelasti heidät nimensä tähden, tehdäkseen voimansa tiettäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Hän nuhteli Kaislamerta, ja se kuivui. Hän kuljetti heitä syvyyksissä niinkuin erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Hän pelasti heidät vihamiehen kädestä ja lunasti heidät vihollisen vallasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Vedet peittivät heidän ahdistajansa, ei yhtäkään niistä jäänyt jäljelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Silloin he uskoivat hänen sanansa, veisasivat hänen ylistystään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Mutta pian he unhottivat hänen tekonsa eivätkä odottaneet hänen neuvoansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Heissä syttyi himo erämaassa, ja he kiusasivat Jumalaa autiossa maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Ja hän antoi heille, mitä he pyysivät, mutta lähetti heihin hivuttavan taudin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Ja heissä syttyi leirissä kateus Moosesta vastaan ja Aaronia, Herran pyhää, vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Mutta maa aukeni ja nieli Daatanin ja peitti Abiramin joukkion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Ja heidän joukkiossaan syttyi tuli, liekki poltti jumalattomat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'He tekivät vasikan Hoorebin juurella ja kumarsivat valettua kuvaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'he vaihtoivat Kunniansa ruohoa syövän härän kuvaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'He unhottivat Jumalan, pelastajansa, joka oli tehnyt Egyptissä suuria tekoja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'ihmeitä Haamin maassa, peljättäviä tekoja Kaislameren rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Silloin hän aikoi hävittää heidät, mutta Mooses, hänen valittunsa, seisoi suojana hänen edessään ja käänsi pois hänen vihansa tuhoa tuottamasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'He pitivät halpana ihanan maan eivätkä uskoneet hänen sanaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'He napisivat teltoissansa eivätkä kuulleet Herran ääntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Silloin hän nosti kätensä heitä vastaan kaataakseen heidät erämaassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'kaataakseen heidän jälkeläisensä pakanain seassa ja hajottaakseen heidät pakanamaihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'He antautuivat palvelemaan Baal-Peoria ja söivät kuolleitten jumalien uhreja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'He vihoittivat hänet teoillansa, ja niin vitsaus alkoi riehua heidän keskuudessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Mutta Piinehas astui esiin ja pani tuomion toimeen, ja vitsaus taukosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Ja se luettiin hänelle vanhurskaudeksi, polvesta polveen, iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'He vihoittivat hänet Meriban vetten luona, ja Mooseksen kävi pahoin heidän tähtensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Sillä he niskoittelivat Jumalan Henkeä vastaan, ja hän puhui huulillaan ajattelemattomasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'He eivät hävittäneet niitä kansoja, jotka Herra oli käskenyt heidän hävittää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'vaan pitivät yhteyttä pakanain kanssa ja oppivat heidän tekonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'He palvelivat heidän jumalankuviansa, ja niistä tuli heille paula.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Ja he uhrasivat poikiansa ja tyttäriänsä riivaajille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'He vuodattivat viatonta verta, poikiensa ja tyttäriensä verta, uhraten heidät Kanaanin epäjumalille, ja maa saastui veriveloista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Näin he saastuttivat itsensä töillään ja olivat haureelliset teoissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Ja Herran viha syttyi hänen kansaansa vastaan, ja hän kyllästyi perintöosaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Ja hän jätti heidät pakanain käsiin, ja heidän vihamiehensä vallitsivat heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Heidän vihollisensa ahdistivat heitä, ja heidän täytyi painua niiden käden alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Monet kerrat hän pelasti heidät, mutta he olivat uppiniskaiset omassa neuvossaan ja sortuivat pahain tekojensa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Mutta hän katsoi heihin heidän ahdistuksessaan, kun hän kuuli heidän valitushuutonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Ja hän muisti heidän hyväkseen liittonsa ja armahti heitä suuressa laupeudessansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Ja hän salli heidän saada armon kaikilta, jotka olivat vieneet heidät vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Pelasta meidät, Herra, meidän Jumalamme, ja kokoa meidät pakanain seasta, että me kiittäisimme sinun pyhää nimeäsi ja kerskauksemme olisi, että me sinua ylistämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Kiitetty olkoon Herra, Israelin Jumala, iankaikkisesta iankaikkiseen. Ja kaikki kansa sanokoon: \"Amen. Halleluja!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Niin sanokoot Herran lunastetut, jotka hän on lunastanut ahdistuksen alta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'ja koonnut pakanamaista, idästä ja lännestä, pohjoisesta ja meren puolelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'He harhailivat erämaassa, autiossa, tiettömässä maassa, löytämättä asuttua kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Heidän oli nälkä ja jano, heidän sielunsa nääntyi heissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Mutta hädässänsä he huusivat Herraa, ja hän pelasti heidät heidän ahdistuksistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Ja hän ohjasi heidät oikealle tielle, niin että he pääsivät asuttuun kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Kiittäkööt he Herraa hänen armostansa, hänen ihmeellisistä teoistaan ihmislapsia kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Sillä hän ravitsee nääntyvän sielun ja täyttää nälkäisen sielun hyvyydellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'He istuivat pimeydessä ja synkeydessä, vangittuina kurjuuteen ja rautoihin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'koska olivat niskoitelleet Jumalan käskyjä vastaan ja katsoneet halvaksi Korkeimman neuvon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Hän masensi heidän sydämensä kärsimyksellä; he sortuivat, eikä ollut auttajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Mutta hädässänsä he huusivat Herraa, ja hän pelasti heidät heidän ahdistuksistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Hän vei heidät ulos pimeydestä ja synkeydestä, hän katkaisi heidän kahleensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Kiittäkööt he Herraa hänen armostansa ja hänen ihmeellisistä teoistaan ihmislapsia kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Sillä hän särkee vaskiset ovet ja rikkoo rautaiset salvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'He olivat hulluja, sillä heidän vaelluksensa oli syntinen, ja he kärsivät vaivaa pahojen tekojensa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Heidän sielunsa inhosi kaikkea ruokaa, ja he olivat lähellä kuoleman portteja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Mutta hädässänsä he huusivat Herraa, ja hän pelasti heidät heidän ahdistuksistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Hän lähetti sanansa ja paransi heidät ja pelasti heidät haudasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Kiittäkööt he Herraa hänen armostansa ja hänen ihmeellisistä teoistaan ihmislapsia kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Uhratkoot kiitosuhreja ja kertokoot riemuiten hänen töitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'He lähtivät laivoilla merelle ja kävivät kauppaa suurilla vesillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'He näkivät Herran työt ja hänen ihmeelliset tekonsa meren syvyyksissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Hän sanoi sanansa ja nosti myrskytuulen, joka kohotti korkealle sen aallot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'He kohosivat taivasta kohti, he vajosivat syvyyksiin; heidän sielunsa menehtyi tuskasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'He horjuivat ja hoippuivat kuin juopunut, ja kaikki heidän taitonsa hämmentyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Mutta hädässänsä he huusivat Herraa, ja hän päästi heidät heidän ahdistuksistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Hän tyynnytti myrskyn, ja meren aallot hiljenivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'He iloitsivat, kun tuli tyyni, ja hän vei heidät toivottuun satamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Kiittäkööt he Herraa hänen armostansa ja hänen ihmeellisistä teoistaan ihmislapsia kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Kunnioittakoot häntä kansan seurakunnassa ja vanhinten kokouksessa häntä ylistäkööt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Hän muutti virrat erämaaksi ja vesilähteet kuivaksi maaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'hedelmällisen maan suola-aroksi, sen asukasten pahuuden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Hän muutti erämaan vesilammikoiksi ja kuivan maan vesilähteiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Ja hän asetti nälkäiset sinne asumaan ja he rakensivat kaupungin asuaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Ja he kylvivät peltoja ja istuttivat viinitarhoja, jotka tuottivat satoisan hedelmän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Hän siunasi heitä, ja he lisääntyivät suuresti, ja hän antoi heille paljon karjaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Ja kun he vähentyivät ja vaipuivat onnettomuuden ja huolten painon alla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'niin hän, joka vuodattaa ylenkatsetta ruhtinasten päälle ja panee heidät harhailemaan tiettömissä autiomaissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'hän kohotti köyhän kurjuudesta ja teki suvut suuriksi kuin lammaslaumat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Oikeamieliset näkevät sen ja riemuitsevat, ja kaiken vääryyden täytyy tukkia suunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Joka viisas on, se ottakoon näistä vaarin ja ajatelkoon Herran armotekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Laulu; Daavidin virsi. {108:2} Minun sydämeni on valmis, Jumala, minä tahdon veisata ja soittaa; valmis on minun sieluni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, '{108:3} Heräjä, harppu ja kannel. Minä tahdon herättää aamuruskon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, '{108:4} Herra, sinua minä kiitän kansojen joukossa ja veisaan sinun kiitostasi kansakuntien keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, '{108:5} Sillä suuri on sinun armosi ja ulottuu ylitse taivasten ja sinun totuutesi hamaan pilviin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, '{108:6} Korota itsesi yli taivasten, Jumala, ja levitköön sinun kunniasi yli kaiken maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, '{108:7} Että sinun rakkaasi pelastetuiksi tulisivat, auta oikealla kädelläsi ja vastaa minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, '{108:8} Jumala on puhunut pyhäkössänsä. Minä riemuitsen, minä jaan Sikemin ja mittaan Sukkotin laakson.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, '{108:9} Minun on Gilead, ja minun on Manasse; Efraim on minun pääni suojus, Juuda minun valtikkani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, '{108:10} Mooab on minun pesuastiani, Edomiin minä viskaan kenkäni, minä riemuitsen Filistean maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, '{108:11} Kuka vie minut varustettuun kaupunkiin? Kuka saattaa minut Edomiin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, '{108:12} Etkö sinä, Jumala, hyljännyt meitä? Et lähtenyt, Jumala, meidän sotajoukkojemme kanssa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, '{108:13} Anna meille apu ahdistajaa vastaan, sillä turha on ihmisten apu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, '{108:14} Jumalan voimalla me teemme väkeviä tekoja; hän tallaa meidän vihollisemme maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Veisuunjohtajalle; Daavidin virsi. Jumala, minun ylistykseni, älä ole vaiti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Sillä he ovat avanneet minua vastaan jumalattoman ja petollisen suun, he puhuttelevat minua valheen kielellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Vihan sanoilla he ovat minut piirittäneet, ja syyttä he sotivat minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Rakkauteni palkaksi he minua vainoavat, mutta minä ainoastaan rukoilen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'He kostavat minulle hyvän pahalla ja rakkauteni vihalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Aseta jumalaton mies häntä vastaan, ja seisokoon syyttäjä hänen oikealla puolellansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Oikeuden edessä hän joutukoon syyhyn, ja hänen rukouksensa tulkoon synniksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Hänen päivänsä olkoot harvat, ottakoon toinen hänen kaitsijatoimensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Tulkoot hänen lapsensa orvoiksi ja hänen vaimonsa leskeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Kierrelkööt hänen lapsensa alati kerjäten, anelkoot kaukana kotinsa raunioilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Anastakoon koronkiskuri kaiken hänen omansa, ja riistäkööt vieraat hänen vaivannäkönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Älköön kukaan osoittako hänelle laupeutta, älköönkä kukaan armahtako hänen orpojansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Hänen jälkeläisensä hävitkööt sukupuuttoon, pyyhittäköön heidän nimensä pois toisessa polvessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Hänen isiensä rikkomukset pysykööt Herran muistossa, älköönkä hänen äitinsä syntiä pyyhittäkö pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Olkoot ne Herran edessä alati, ja hävittäköön hän heidän muistonsa maan päältä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Sillä se mies ei ajatellutkaan tehdä laupeutta, vaan vainosi kurjaa ja köyhää ja sydämen tuskassa olevaa, tappaaksensa hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Hän rakasti kirousta, ja se kohtasi häntä; hän ei huolinut siunauksesta, ja se väistyi hänestä kauas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Hän puki kirouksen yllensä niinkuin vaatteensa, ja se meni hänen sisuksiinsa niinkuin vesi ja hänen luihinsa niinkuin öljy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Se olkoon hänellä viittana, johon hän verhoutuu, ja vyönä, johon hän aina vyöttäytyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Tämä olkoon Herralta minun vainoojaini palkka ja niiden, jotka puhuvat pahaa minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Mutta sinä, Herra, Herra, auta minua nimesi tähden, sillä sinun armosi on hyvä, pelasta minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Sillä minä olen kurja ja köyhä, ja sydämeni on haavoitettu minun rinnassani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Minä katoan pois kuin pitenevä varjo, minut pudistetaan pois kuin heinäsirkka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Polveni horjuvat paastoamisesta, ja minun ruumiini on laihtunut lihattomaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Ja minä olen joutunut heidän herjattavakseen, minut nähdessään he nyökyttävät päätänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Auta minua, Herra, minun Jumalani, pelasta minut armosi jälkeen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'ja he saakoot tuta, että tämä on sinun kätesi, että sinä, Herra, sen teit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Jos he kiroavat, siunaa sinä, jos he nousevat, joutukoot häpeään, mutta palvelijasi saakoon iloita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Olkoon häväistys minun vainoojaini pukuna, ja verhotkoon heitä heidän häpeänsä niinkuin viitta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Minä suullani kiitän suuresti Herraa, ja monien keskellä minä ylistän häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Sillä hän seisoo köyhän oikealla puolella pelastaakseen hänet niistä, jotka hänet tuomitsevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Daavidin virsi. Herra sanoi minun herralleni: \"Istu minun oikealle puolelleni, kunnes minä panen sinun vihollisesi sinun jalkojesi astinlaudaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Herra ojentaa sinun valtasi valtikan Siionista; hallitse vihollistesi keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Altis on sinun kansasi sinun sotaanlähtösi päivänä: pyhässä asussa sinun nuori väkesi nousee eteesi, niinkuin kaste aamuruskon helmasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Herra on vannonut eikä sitä kadu: \"Sinä olet pappi iankaikkisesti, Melkisedekin järjestyksen mukaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Herra on sinun oikealla puolellasi, hän musertaa kuninkaat vihansa päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Hän tuomitsee pakanat: ruumiita viruu kaikkialla; hän murskaa päitä laajalti maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Hän juo purosta tien varrelta; sentähden hän kohottaa päänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Halleluja! Minä kiitän Herraa kaikesta sydämestäni hurskasten kokouksessa ja seurakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Suuret ovat Herran teot, kaikkien niiden tutkisteltavat, jotka niitä rakastavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Kunnialliset ja korkeat ovat hänen työnsä, ja hänen vanhurskautensa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Hän on säätänyt ihmeellisten tekojensa muiston; armollinen ja laupias on Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Hän antaa ruuan pelkääväisillensä, hän muistaa liittonsa iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Hän ilmoitti kansallensa tekojensa voiman, hän antoi heille pakanain perintöosan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Hänen kättensä teot ovat totiset ja oikeat; luotettavat ovat kaikki hänen asetuksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Ne pysyvät järkkymättä aina ja iankaikkisesti; ne ovat tehdyt totuudessa ja oikeudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Hän lähetti kansallensa lunastuksen, sääti liittonsa ikuisiksi ajoiksi; pyhä ja peljättävä on hänen nimensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Herran pelko on viisauden alku, hyvä ymmärrys kaikille, jotka sitä noudattavat. Hänen ylistyksensä pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Halleluja! Autuas se mies, joka Herraa pelkää ja suuresti halajaa hänen käskyjänsä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Hänen jälkeläisensä tulevat voimallisiksi maassa, oikeamielisten suku tulee siunatuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Varallisuus ja rikkaus on hänen huoneessansa, ja hänen vanhurskautensa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Oikeamielisille koittaa pimeydessä valkeus, armollinen, laupias ja vanhurskas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Hyvin käy sen miehen, joka on laupias ja antaa lainaksi, joka hoitaa asiansa oikeuden mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Sillä ei hän ikinä horju; vanhurskas säilyy ikuisessa muistossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Ei hän pelkää pahaa sanomaa, hänen sydämensä on vahva, sillä hän turvaa Herraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Hänen sydämensä on luja ja peloton, kunnes hän vihdoin ilolla katselee ahdistajiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Hän on runsaskätinen, hän antaa köyhille, hänen vanhurskautensa pysyy iankaikkisesti, hänen sarvensa kohoaa kunniassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Jumalaton näkee sen ja närkästyy, hän kiristelee hampaitaan ja pakahtuu. Jumalattomien halut raukeavat tyhjiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Halleluja! Ylistäkää, te Herran palvelijat, ylistäkää Herran nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Siunattu olkoon Herran nimi nyt ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Auringon noususta sen laskuun saakka olkoon Herran nimi ylistetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Herra on korkea yli kaikkien pakanakansain, yli taivasten kohoaa hänen kunniansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Kuka on niinkuin Herra, meidän Jumalamme, joka korkealla asuu');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'ja katsoo syvälle-taivaassa ja maassa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Hän, joka tomusta nostaa alhaisen, korottaa loasta köyhän');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'asettaaksensa hänet ruhtinasten rinnalle, hänen kansansa ruhtinasten rinnalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'joka antaa hedelmättömän asua kodissa, iloisena lasten äitinä! Halleluja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Kun Israel lähti Egyptistä, Jaakobin suku vieraskielisestä kansasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'silloin Juuda tuli hänen pyhäkökseen, Israel hänen valtakunnaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Sen näki meri ja pakeni, Jordan kääntyi takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Vuoret hyppivät niinkuin oinaat, kukkulat niinkuin lammasten karitsat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Mikä sinun on, meri, kun pakenet, mikä sinun, Jordan, kun käännyt takaisin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Te vuoret, miksi hypitte kuin oinaat, te kukkulat, kuin lammasten karitsat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Vapise, maa, Herran kasvojen edessä, Jaakobin Jumalan kasvojen edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'joka muuttaa kallion vesilammikoksi, kovan kiven vesilähteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Älä meille, Herra, älä meille, vaan omalle nimellesi anna kunnia armosi ja totuutesi tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Miksi pakanat saisivat sanoa: \"Missä on heidän Jumalansa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Meidän Jumalamme on taivaissa; mitä ikinä hän tahtoo, sen hän tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Mutta heidän epäjumalansa ovat hopeata ja kultaa, ihmiskätten tekoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Niillä on suu, mutta eivät ne puhu, niillä on silmät, mutta eivät näe.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Niillä on korvat, mutta eivät kuule, niillä on nenä, mutta eivät hajua tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Niiden kädet eivät koske, niiden jalat eivät astu, ei tule ääntä niiden kurkusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Niiden kaltaisia ovat niiden tekijät ja kaikki, jotka turvaavat niihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Israel, turvaa Herraan-hän on heidän apunsa ja kilpensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Te, Aaronin suku, turvatkaa Herraan-hän on heidän apunsa ja kilpensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Te, Herraa pelkääväiset, turvatkaa Herraan-hän on heidän apunsa ja kilpensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Herra muistaa meitä ja siunaa, hän siunaa Israelin sukua, hän siunaa Aaronin sukua,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'hän siunaa niitä, jotka Herraa pelkäävät, niin pieniä kuin suuriakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Herra lisätköön teitä, sekä teitä että teidän lapsianne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Te olette Herran siunatut, hänen, joka on tehnyt taivaan ja maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Taivas on Herran taivas, mutta maan hän on antanut ihmisten lapsille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Eivät kuolleet ylistä Herraa, ei kukaan hiljaisuuteen astuneista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Mutta me, me kiitämme Herraa, nyt ja iankaikkisesti. Halleluja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Minä rakastan Herraa, sillä hän kuulee minun ääneni ja rukoukseni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'sillä hän on kallistanut korvansa minun puoleeni, ja minä huudan häntä avuksi kaiken elinaikani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Kuoleman paulat piirittivät minut, tuonelan ahdistukset kohtasivat minua; minä jouduin hätään ja murheeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Mutta minä huusin avukseni Herran nimeä: \"Oi Herra, pelasta minun sieluni!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Herra on armollinen ja vanhurskas, meidän Jumalamme on laupias.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Herra varjelee yksinkertaiset; minä olin viheliäinen, mutta hän auttoi minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Palaja, sieluni, takaisin lepoosi, sillä Herra on tehnyt sinulle hyvin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Sillä sinä olet pelastanut minun sieluni kuolemasta, minun silmäni kyynelistä, jalkani kompastumasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Minä saan vaeltaa Herran kasvojen edessä elävien maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Minä uskon, sentähden minä puhun, minä, joka olin kovin vaivattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Minä sanoin hädässäni: \"Kaikki ihmiset ovat valhettelijoita\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Kuinka minä maksan Herralle kaikki hänen hyvät tekonsa minua kohtaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Minä kohotan pelastuksen maljan ja huudan avukseni Herran nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Minä täytän lupaukseni Herralle kaiken hänen kansansa edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Kallis on Herran silmissä hänen hurskaittensa kuolema.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'Oi Herra, minä olen sinun palvelijasi, sinun palvelijasi minä olen, sinun palvelijattaresi poika! Sinä päästit minun siteeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Sinulle minä uhraan kiitosuhrin ja huudan avukseni Herran nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Minä täytän lupaukseni Herralle kaiken hänen kansansa edessä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'Herran huoneen esikartanoissa, sinun keskelläsi, Jerusalem. Halleluja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Kiittäkää Herraa, kaikki pakanat, ylistäkää häntä, kaikki kansat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Sillä hänen armonsa meitä kohtaan on voimallinen, ja Herran uskollisuus pysyy iankaikkisesti. Halleluja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Kiittäkää Herraa, sillä hän on hyvä; sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Näin sanokoon Israel; sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Näin sanokoon Aaronin suku; sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Näin sanokoot ne, jotka Herraa pelkäävät; sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Ahdistuksessani minä huusin Herraa, Herra vastasi minulle ja asetti minut avaraan paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Herra on minun puolellani, en minä pelkää; mitä voivat ihmiset minulle tehdä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Herra on minun puolellani ja auttaa minua, ja minä saan ilolla katsella vihamiehiäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Parempi on luottaa Herraan, kuin turvata ihmisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Parempi on luottaa Herraan, kuin turvata ruhtinaihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Kaikki pakanat piirittivät minua-Herran nimessä minä lyön heidät maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'He piirittivät minua joka taholta-Herran nimessä minä lyön heidät maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Niinkuin mehiläiset he minua piirittivät-he sammuvat kuin tuli orjantappuroissa. Herran nimessä minä lyön heidät maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Sinä sysäsit minua kovasti, että kaatuisin, mutta Herra auttoi minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Herra on minun väkevyyteni ja ylistysvirteni, ja hän tuli minulle pelastajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Riemun ja pelastuksen huuto kuuluu vanhurskaitten majoissa: Herran oikea käsi tekee väkeviä tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Herran oikea käsi korottaa, Herran oikea käsi tekee väkeviä tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'En minä kuole, vaan elän ja julistan Herran töitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Herra minua kyllä kuritti, mutta kuolemalle hän ei minua antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Avatkaa minulle vanhurskauden portit, käydäkseni niistä sisälle kiittämään Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Tämä on Herran portti: vanhurskaat käyvät siitä sisälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Minä kiitän sinua siitä, että vastasit minulle ja tulit minulle pelastajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Herralta tämä on tullut; se on ihmeellistä meidän silmissämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Tämä on se päivä, jonka Herra on tehnyt; riemuitkaamme ja iloitkaamme siitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Oi Herra, auta, oi Herra, anna menestys!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Siunattu olkoon hän, joka tulee Herran nimeen; me siunaamme teitä Herran huoneesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Herra on Jumala, ja hän antoi valon meille loistaa. Sitokaa juhlauhrit köysillä alttarin sarviin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Sinä olet minun Jumalani, ja sinua minä kiitän. Minun Jumalani, sinua minä kunnioitan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Kiittäkää Herraa, sillä hän on hyvä; sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Autuaat ne, joiden tie on nuhteeton, jotka Herran laissa vaeltavat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Autuaat ne, jotka ottavat vaarin hänen todistuksistaan, jotka etsivät häntä kaikesta sydämestänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'jotka eivät vääryyttä tee, vaan vaeltavat hänen teillään!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Sinä olet asetuksesi säätänyt, että niitä tarkasti noudatettaisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Oi, jospa minun vaellukseni olisi vakaa, niin että noudattaisin sinun käskyjäsi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Silloin minä en joudu häpeään, kun katselen kaikkia sinun käskyjäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Minä kiitän sinua vilpittömällä sydämellä, kun opin sinun vanhurskautesi oikeudet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Minä noudatan sinun käskyjäsi, älä minua peräti hylkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Kuinka voi nuorukainen pitää tiensä puhtaana? Siten, että hän noudattaa sinun sanaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Minä etsin sinua kaikesta sydämestäni, älä salli minun eksyä pois sinun käskyistäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'Minä kätken sinun sanasi sydämeeni, etten tekisi syntiä sinua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Kiitetty ole sinä, Herra, opeta minulle käskysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Huulillani minä julistan kaikki sinun suusi oikeudet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Minä iloitsen sinun todistustesi tiestä, niinkuin kaikkinaisesta rikkaudesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Minä tutkistelen sinun asetuksiasi ja katselen sinun polkujasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'Minä iloitsen sinun käskyistäsi enkä sinun sanaasi unhota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Tee palvelijallesi hyvin, että minä eläisin ja noudattaisin sinun sanaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Avaa minun silmäni näkemään sinun lakisi ihmeitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Minä olen muukalainen maan päällä; älä salaa minulta käskyjäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Minun sieluni hiukeaa ikävöidessäni alati sinun oikeuksiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Sinä nuhtelet julkeita, kirotuita, jotka poikkeavat pois sinun käskyistäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Poista minun päältäni häväistys ja ylenkatse, sillä minä otan sinun todistuksistasi vaarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Ruhtinaatkin istuvat ja pitävät neuvoa minua vastaan, mutta palvelijasi tutkistelee sinun käskyjäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Sinun todistuksesi ovat minun iloni, ne ovat minun neuvonantajani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Minun sieluni on vaipunut tomuun; virvoita minua sanasi jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Minä kerron vaellukseni, ja sinä vastaat minulle; opeta minulle käskysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Saata minut ymmärtämään asetustesi tie, niin minä tutkistelen sinun ihmeitäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Minun sieluni itkee murheesta; vahvista minua sanasi jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Käännä minusta pois valheen tie, ja anna armostasi minulle lakisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Minä olen valinnut totuuden tien, olen asettanut eteeni sinun oikeutesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Minä riipun kiinni sinun todistuksissasi, Herra, älä anna minun joutua häpeään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Minä juoksen sinun käskyjesi tietä, sillä sinä avarrat minun sydämeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Opeta minulle, Herra, käskyjesi tie, niin minä seuraan sitä loppuun asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Anna minulle ymmärrys ottaakseni sinun laistasi vaarin ja noudattaakseni sitä kaikesta sydämestäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Anna minun vaeltaa sinun käskyjesi polkua, sillä sitä minä halajan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Anna minun sydämeni taipua sinun todistuksiisi, ei väärän voiton puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Käännä silmäni pois turhuutta katselemasta, anna minun saada virvoitus sinun teilläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Anna palvelijallesi toteutua lupauksesi, joka on annettu sinua pelkääville.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Poista minusta häväistys, jota pelkään, sillä sinun oikeutesi ovat hyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Katso, minä ikävöitsen sinun asetuksiasi; virvoita minua vanhurskaudellasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Tulkoon minulle sinun armosi, Herra, sinun apusi, sinun lupauksesi jälkeen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'että minä voisin vastata herjaajalleni; sillä sinun sanaasi minä turvaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Älä ota peräti pois minun suustani totuuden sanaa, sillä sinun oikeuteesi minä panen toivoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Minä tahdon alati noudattaa sinun lakiasi, aina ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Silloin minä vaellan avaralla paikalla; sillä sinun asetuksiasi minä kysyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Minä puhun sinun todistuksistasi kuningasten edessä, enkä häpeään joudu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Minä iloitsen sinun käskyistäsi, jotka ovat minulle rakkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Minä kohotan käteni sinun käskyjesi puoleen, jotka ovat minulle rakkaat, ja tutkistelen sinun säädöksiäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Muista sana, jonka olet palvelijallesi puhunut, sillä sinä olet antanut minulle toivon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Se on minun lohdutukseni kurjuudessani, että sinun lupauksesi minua virvoittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Julkeat pilkkaavat minua kovin, mutta sinun laistasi minä en poikkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Herra, minä ajattelen sinun tuomioitasi, tuomioitasi hamasta ikiajoista asti, ja minä saan lohdutuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Minut valtaa palava vihastus jumalattomien tähden, jotka hylkäävät sinun lakisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Sinun käskysi ovat minun ylistysvirteni minun muukalaisuuteni majassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Yöllä minä ajattelen sinun nimeäsi, Herra, ja minä noudatan sinun lakiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Tämä on minun osakseni suotu: että otan vaarin sinun asetuksistasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Herra on minun osani; minä olen päättänyt noudattaa sinun sanojasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Minä etsin sinun mielisuosiotasi kaikesta sydämestäni; ole minulle armollinen lupauksesi mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Minä tutkin teitäni, ja käännän askeleeni sinun todistustesi puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Minä riennän viivyttelemättä noudattamaan sinun käskyjäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Jumalattomain paulat piirittävät minua, mutta minä en unhota sinun lakiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Puoliyöstä minä nousen kiittämään sinua sinun vanhurskautesi oikeuksista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Minä olen kaikkien niiden ystävä, jotka sinua pelkäävät ja noudattavat sinun asetuksiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Maa on täynnä sinun laupeuttasi, Herra; opeta minulle käskysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Sinä osoitat palvelijallesi hyvyyttä sanasi jälkeen, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Opeta minulle hyvä ymmärrys ja tieto, sillä sinun käskyihisi minä panen uskallukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Ennenkuin minut nöyryytettiin, minä eksyin, mutta nyt minä noudatan sinun sanaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Sinä olet hyvä, ja hyvin sinä teet; opeta minulle käskysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Julkeat tahraavat minua valheillansa, mutta minä otan sinun asetuksistasi vaarin kaikesta sydämestäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Heidän sydämensä on turta kuin ihra, mutta minä iloitsen sinun laistasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Hyvä oli minulle, että minut nöyryytettiin: niin minä opin sinun käskysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Sinun suusi laki on minulle kalliimpi kuin tuhannet kappaleet kultaa ja hopeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Sinun kätesi ovat minut tehneet ja valmistaneet; anna minulle ymmärrys oppiakseni sinun käskysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Sinua pelkääväiset näkevät minut ja iloitsevat, sillä minä panen toivoni sinun sanaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Herra, minä tiedän, että sinun tuomiosi ovat vanhurskaat, ja uskollisuudessasi sinä olet minut nöyryyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Sinun armosi olkoon minun lohdutukseni, niinkuin sinä olet palvelijallesi luvannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Tulkoon minulle sinun laupeutesi, että minä eläisin; sillä sinun lakisi on minun iloni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Joutukoot julkeat häpeään, sillä he sortavat minua syyttä; minä tutkistelen sinun asetuksiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Kääntykööt minun puolelleni ne, jotka sinua pelkäävät ja jotka sinun todistuksesi tuntevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Pysyköön sydämeni vakaana sinun käskyissäsi, etten minä häpeään joutuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Sinun apuasi minun sieluni ikävöitsee, sinun sanaasi minä panen toivoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Minun silmäni ikävöitsevät sinun sanaasi; minä kysyn: \"Milloin lohdutat minua?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Sillä minä olen kuin nahkaleili savussa, mutta sinun käskyjäsi minä en unhota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Kuinka harvat ovat palvelijasi päivät! Milloin sinä tuomitset minun vainoojani?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Julkeat kaivavat minulle kuoppia, ne, jotka eivät elä sinun lakisi mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Kaikki sinun käskysi ovat todet; syyttä he minua vainoavat; auta minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'He ovat minut miltei tuhonneet tässä maassa, mutta minä en ole hyljännyt sinun asetuksiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Virvoita minua armosi jälkeen, niin minä noudatan sinun suusi todistuksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Iankaikkisesti pysyy sinun sanasi, Herra, vahvana taivaissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Sinun uskollisuutesi kestää polvesta polveen, sinä perustit maan, ja se pysyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Sinun järjestyksesi mukaan ne pysyvät vielä tänä päivänä, sillä ne kaikki ovat sinun palvelijoitasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Ellei sinun lakisi olisi ollut minun iloni, olisin menehtynyt kurjuuteeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'En minä ikinä unhota sinun asetuksiasi, sillä niillä sinä minua virvoitat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Sinun omasi minä olen, pelasta minut, sillä sinun asetuksiasi minä kysyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Jumalattomat väijyvät minua, tuhotakseen minut, mutta minä tarkkaan sinun todistuksiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Kaikella täydellisellä on rajansa-sen olen nähnyt-mutta sinun käskysi ovat ylen avarat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Kuinka sinun lakisi onkaan minulle rakas! Kaiken päivää minä sitä tutkistelen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Sinun käskysi tekevät minut vihollisiani viisaammaksi, sillä ne ovat minun omani iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Minä olen kaikkia opettajiani taitavampi, sillä minä tutkistelen sinun todistuksiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Minä olen ymmärtäväisempi kuin vanhat, sillä minä otan vaarin sinun asetuksistasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Minä pidätän jalkani kaikilta pahoilta teiltä, noudattaakseni sinun sanaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Minä en poikkea sinun oikeuksistasi, sillä sinä neuvot minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Kuinka makeat ovat minulle sinun lupauksesi! Ne ovat hunajaa makeammat minun suussani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Sinun asetuksistasi minä saan ymmärrystä; sentähden minä vihaan kaikkia valheen teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Sinun sanasi on minun jalkaini lamppu ja valkeus minun tielläni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Minä olen vannonut ja tahdon sen täyttää: noudattaa sinun vanhurskautesi oikeuksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Minä olen kovin vaivattu; Herra, virvoita minua sanasi jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Kelvatkoot sinulle, Herra, minun suuni vapaaehtoiset uhrit, ja opeta minulle oikeutesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Minun henkeni häälyy alati kämmenelläni, mutta sinun lakiasi minä en unhota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Jumalattomat virittävät pauloja minun eteeni, mutta sinun asetuksistasi minä en eksy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Sinun todistuksesi ovat minun ikuinen perintöosani, sillä ne ovat minun sydämeni ilo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Minä olen taivuttanut sydämeni pitämään sinun käskysi, aina ja loppuun asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Kaksimielisiä minä vihaan, mutta sinun lakiasi minä rakastan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Sinä olet minun suojani ja kilpeni, sinun sanaasi minä panen toivoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Luopukaa minusta, te pahantekijät, minä tahdon ottaa Jumalani käskyistä vaarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Tue minua lupauksesi jälkeen, että minä eläisin, äläkä anna minun joutua toivossani häpeään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Vahvista minua, että minä pelastuisin, niin minä katselen alati sinun käskyjäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Sinä hylkäät kaikki, jotka sinun käskyistäsi eksyvät, sillä heidän kavaluutensa on turha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Kaikki maan jumalattomat sinä heität pois niinkuin kuonan; sentähden minä rakastan sinun todistuksiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Sinun peljättävyytesi edessä minun ruumiini vapisee, ja minä pelkään sinun tuomioitasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Minä teen oikeuden ja vanhurskauden, älä jätä minua sortajaini käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Ole palvelijasi puolusmies hänen parhaaksensa, älä salli julkeain minua sortaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Minun silmäni hiueten halajavat sinun apuasi ja sinun vanhurskaita lupauksiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Tee palvelijallesi armosi jälkeen ja opeta minulle käskysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Minä olen sinun palvelijasi, anna minulle ymmärrys, että minä sinun todistuksesi tuntisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'On aika Herran tehdä tekonsa: he ovat rikkoneet sinun lakisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Sentähden minä rakastan sinun käskyjäsi enemmän kuin kultaa, enemmän kuin puhtainta kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Sentähden minä vaellan kaikessa suoraan, kaikkien sinun asetuksiesi mukaan; kaikkia valheen teitä minä vihaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Ihmeelliset ovat sinun todistuksesi, sentähden minun sieluni ottaa niistä vaarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Kun sinun sanasi avautuvat, niin ne valaisevat ja antavat yksinkertaiselle ymmärrystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Minä avaan suuni ja huohotan, sillä minä halajan sinun käskyjäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Käänny minun puoleeni, ole minulle armollinen, niinkuin on oikein niitä kohtaan, jotka sinun nimeäsi rakastavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Tee minun askeleeni vakaviksi sanallasi äläkä salli minkään vääryyden minua hallita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Päästä minut ihmisten sorrosta, niin minä noudatan sinun asetuksiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Kirkasta kasvosi palvelijallesi ja opeta minulle käskysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Minun silmistäni vuotavat kyynelvirrat, kun sinun lakiasi ei noudateta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Sinä olet vanhurskas, Herra, ja sinun tuomiosi ovat oikeat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Sinä olet säätänyt todistuksesi vanhurskaudessa ja suuressa uskollisuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Minun kiivauteni kuluttaa minut, sillä minun vihamieheni unhottavat sinun sanasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Sinun sanasi on hyvin koeteltu, ja sinun palvelijasi rakastaa sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Minä olen vähäinen ja halveksittu, mutta minä en unhota sinun asetuksiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Sinun vanhurskautesi on iankaikkinen vanhurskaus, ja sinun lakisi on totuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Hätä ja ahdistus ovat minut saavuttaneet, mutta sinun käskysi ovat minun iloni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Sinun todistuksesi ovat iankaikkisesti vanhurskaat; anna minulle ymmärrys, että minä eläisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Kaikesta sydämestäni minä huudan; vastaa minulle, Herra. Minä tahdon ottaa sinun käskyistäsi vaarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Minä huudan sinua, pelasta minut, niin minä noudatan sinun todistuksiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Jo ennen aamun valkenemista minä huudan, sinun sanoihisi minä panen toivoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Jo ennen yön vartiohetkiä minun silmäni tutkistelevat sinun puhettasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Kuule minun ääneni armosi jälkeen; Herra, virvoita minua oikeutesi mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Lähellä ovat ilkeät vainoojat, jotka ovat kaukana sinun laistasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Lähellä olet sinä, Herra, ja kaikki sinun käskysi ovat todet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Jo aikoja minä olen tiennyt sinun todistuksistasi, että sinä olet ne perustanut iäti pysyviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Katso minun kurjuuttani ja pelasta minut, sillä minä en unhota sinun lakiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Aja minun asiani ja lunasta minut, virvoita minua lupauksesi jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Kaukana on pelastus jumalattomista, sillä he eivät kysy sinun käskyjäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Herra, sinun armahtavaisuutesi on suuri, virvoita minua oikeutesi mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Monta on minulla vainoojaa ja vihamiestä, mutta sinun todistuksistasi minä en poikkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Minä näen uskottomat, ja minua iljettää, sillä he eivät noudata sinun sanaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Huomaa, että minä rakastan sinun asetuksiasi. Herra, virvoita minua armosi jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Sinun sanasi on kokonansa totuus, ja kaikki sinun vanhurskautesi oikeudet pysyvät iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Ruhtinaat vainoavat minua syyttä, mutta minun sydämeni pelkää sinun sanojasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Minä riemuitsen sinun puheestasi, niinkuin suuren saaliin saanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Valhetta minä vihaan ja inhoan, mutta sinun lakiasi minä rakastan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Seitsemästi päivässä minä ylistän sinua sinun vanhurskautesi oikeuksien tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Suuri rauha on niillä, jotka rakastavat sinun lakiasi, eikä heille kompastusta tule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Minä odotan sinulta pelastusta, Herra, ja täytän sinun käskysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Minun sieluni noudattaa sinun todistuksiasi, ja suuresti minä niitä rakastan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Minä noudatan sinun asetuksiasi ja sinun todistuksiasi, sillä kaikki minun tieni ovat sinun edessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Herra, suo minun valitukseni tulla sinun kasvojesi eteen, anna minulle ymmärrys sanasi jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Tulkoon minun anomiseni sinun kasvojesi eteen, pelasta minut lupauksesi mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Vuodattakoot minun huuleni ylistystä, sillä sinä opetat minulle käskysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Minun kieleni veisatkoon sinun lupauksistasi, sillä kaikki sinun käskysi ovat vanhurskaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Sinun kätesi olkoon minun apuni, sillä minä olen valinnut sinun asetuksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Minä ikävöitsen pelastusta sinulta, Herra, ja sinun lakisi on minun iloni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Saakoon minun sieluni elää ja ylistää sinua, ja sinun oikeutesi minua auttakoot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Minä olen eksyksissä kuin kadonnut lammas; etsi palvelijaasi, sillä minä en unhota sinun käskyjäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Matkalaulu. Ahdistuksessani minä huudan Herraa, ja hän vastaa minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Herra, pelasta minun sieluni valheellisista huulista, petollisesta kielestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Mitä hän sinulle antaa ja mitä siihen vielä lisää, sinä petollinen kieli?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Väkivaltaisen teräviä nuolia ynnä kinsteripensaan tulisia hiiliä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Voi minua, että minun täytyy oleskella muukalaisena Mesekissä, asua Keedarin majojen keskellä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Kauan on minun sieluni täytynyt asua niiden seurassa, jotka rauhaa vihaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Minä pidän rauhan, mutta jos sanan sanon, niin he ovat sotaan valmiit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Matkalaulu. Minä nostan silmäni vuoria kohti: mistä tulee minulle apu?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Apu minulle tulee Herralta, joka on tehnyt taivaan ja maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Hän ei salli sinun jalkasi horjua, sinun varjelijasi ei torku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Katso, hän, joka Israelia varjelee, ei torku eikä nuku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Herra on sinun varjelijasi, Herra on suojaava varjosi sinun oikealla puolellasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Ei polta sinua aurinko päivällä, eikä kuu yöllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Herra varjelee sinut kaikesta pahasta, hän varjelee sinun sielusi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Herra varjelee sinun lähtemisesi ja tulemisesi, nyt ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Matkalaulu; Daavidin virsi. Minä iloitsin, kun minulle sanottiin: \"Menkäämme Herran huoneeseen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Meidän jalkamme saavat seisoa sinun porteissasi, Jerusalem;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'sinä Jerusalem, rakennettu kaupungiksi, johon kokoonnutaan yhteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'jonne sukukunnat vaeltavat, Herran sukukunnat, niinkuin Israelille on säädetty, kiittämään Herran nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Sillä siellä ovat tuomioistuimet, Daavidin huoneen istuimet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Toivottakaa rauhaa Jerusalemille, menestykööt ne, jotka sinua rakastavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Rauha olkoon sinun muuriesi sisällä, olkoon onni sinun linnoissasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Veljieni ja ystävieni tähden minä sanon: olkoon sinulla rauha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Herran, meidän Jumalamme, huoneen tähden minä tahdon etsiä sinun parastasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Matkalaulu. Minä nostan silmäni sinun puoleesi, joka taivaissa asut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Katso, niinkuin palvelijain silmät katsovat heidän isäntäinsä käsiin, ja niinkuin palvelijattaren silmät katsovat hänen emäntänsä käsiin, niin meidän silmämme katsovat Herran, meidän Jumalamme, puoleen, kunnes hän armahtaa meitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Ole meille armollinen, Herra, ole meille armollinen. Sillä kylliksi olemme jo saaneet ylenkatsetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Sielumme on jo kyllänsä saanut suruttomien pilkasta, ylpeitten ylenkatseesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Matkalaulu; Daavidin virsi. Ellei Herra olisi meidän kanssamme-näin sanokoon Israel-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'ellei Herra olisi meidän kanssamme, kun ihmiset nousevat meitä vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'niin he meidät elävältä nielisivät, kun heidän vihansa syttyy meitä vastaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'niin vedet upottaisivat meidät, virta tulvisi meidän sielumme ylitse;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'niin tulvisivat kuohuvat vedet meidän sielumme ylitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Kiitetty olkoon Herra, joka ei antanut meitä heidän hammastensa raadeltaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Meidän sielumme pääsi kuin lintu pyydystäjäin paulasta: paula katkesi, ja me pääsimme pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Meidän apumme on Herran nimi, hänen, joka on tehnyt taivaan ja maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Matkalaulu. Jotka Herraan turvaavat, ovat kuin Siionin vuori: se ei horju, vaan pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Vuoret ympäröivät Jerusalemia, ja Herra ympäröitsee kansaansa, nyt ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Sillä jumalattomuuden valtikka ei saa vallita vanhurskasten arpaosaa, että vanhurskaat eivät ojentaisi käsiänsä vääryyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Anna hyvää hyville, Herra, ja oikeamielisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Mutta jotka poikkeavat mutkaisille teilleen, ne Herra hukuttakoon yhdessä väärintekijäin kanssa. Rauha Israelille!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Matkalaulu. Kun Herra käänsi Siionin kohtalon, niin me olimme kuin unta näkeväiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Silloin oli meidän suumme naurua täynnä, ja kielemme riemua täynnä; silloin sanottiin pakanain keskuudessa: \"Herra on tehnyt suuria heitä kohtaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Niin, Herra on tehnyt suuria meitä kohtaan; siitä me iloitsemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Herra, käännä meidän kohtalomme, niinkuin sadepurot Etelämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Jotka kyynelin kylvävät, ne riemuiten leikkaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'He menevät itkien, kun kylvösiemenen vievät; he palajavat riemuiten, kun lyhteensä tuovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Matkalaulu; Salomon virsi. Jos Herra ei huonetta rakenna, niin sen rakentajat turhaan vaivaa näkevät. Jos Herra ei kaupunkia varjele, niin turhaan vartija valvoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Turhaan te nousette varhain ja myöhään menette levolle ja syötte leipänne murheella: yhtä hyvin hän antaa ystävilleen heidän nukkuessansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Katso, lapset ovat Herran lahja, ja kohdun hedelmä on anti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Niinkuin nuolet sankarin kädessä, niin ovat nuoruudessa synnytetyt pojat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Onnellinen se mies, jonka viini on niitä täynnä! Eivät he joudu häpeään, kun portissa puhuttelevat vihamiehiänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Matkalaulu. Autuas on jokainen, joka pelkää Herraa, joka vaeltaa hänen teillänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Sinä saat nauttia kättesi ansion; onnellinen sinä, sinun käy hyvin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Niinkuin hedelmällinen viiniköynnös on sinun emäntäsi sinun huoneesi perällä, niinkuin öljypuun vesat ovat sinun lapsesi sinun pöytäsi ympärillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Sillä katso, näin siunataan mies, joka Herraa pelkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Siunatkoon Herra sinua Siionista, niin sinä saat kaikkina elinpäivinäsi nähdä Jerusalemin onnellisena,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'saat nähdä lastesi lapset. Rauha Israelille!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Matkalaulu. He ovat minua kovin ahdistaneet nuoruudestani asti-näin sanokoon Israel-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'he ovat minua kovin ahdistaneet nuoruudestani asti, mutta eivät he ole päässeet minusta voitolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Kyntäjät ovat minun selkääni kyntäneet ja vetäneet pitkät vaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Mutta Herra on vanhurskas, hän on katkonut jumalattomain köydet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Joutukoot häpeään ja kääntykööt takaisin kaikki Siionin vihamiehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Olkoot he niinkuin ruoho katoilla, joka kuivuu ennen korrelle puhkeamistaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'josta ei leikkaaja täytä kättänsä eikä lyhteen sitoja syliänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Älköötkä sanoko ohitsekulkijat: \"Herran siunaus tulkoon teille. Me siunaamme teitä Herran nimeen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Matkalaulu. Syvyydestä minä huudan sinua, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Herra, kuule minun ääneni. Tarkatkoot sinun korvasi minun rukousteni ääntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Jos sinä, Herra, pidät mielessäsi synnit, Herra, kuka silloin kestää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Mutta sinun tykönäsi on anteeksiantamus, että sinua peljättäisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Minä odotan Herraa, minun sieluni odottaa, ja minä panen toivoni hänen sanaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Minun sieluni odottaa Herraa hartaammin kuin vartijat aamua, kuin vartijat aamua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Pane toivosi Herraan, Israel. Sillä Herran tykönä on armo, runsas lunastus hänen tykönänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Ja hän lunastaa Israelin kaikista sen synneistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Matkalaulu; Daavidin virsi. Herra, minun sydämeni ei ole ylpeä, eivät minun silmäni ole korskeat, enkä minä tavoittele asioita, jotka ovat minulle ylen suuret ja käsittämättömät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Totisesti, minä olen sieluni viihdyttänyt ja tyynnyttänyt: niinkuin vieroitettu lapsi äidin helmassa, niinkuin vieroitettu lapsi, niin on sieluni minussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Pane toivosi Herraan, Israel, nyt ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Matkalaulu. Muista, Herra, Daavidin hyväksi kaikkia hänen vaivojansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'hänen, joka vannoi valan Herralle ja teki lupauksen Jaakobin Väkevälle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, '\"Minä en mene majaan, joka on minun kotini, enkä nouse vuoteeseeni, joka on minun leposijani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'minä en suo silmilleni unta enkä silmäluomilleni lepoa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'ennenkuin löydän sijan Herralle, asumuksen Jaakobin Väkevälle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Katso, me kuulimme sen olevan Efratassa, me löysimme sen Jaarin kedoilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Menkäämme hänen asumukseensa, kumartukaamme hänen jalkainsa astinlaudan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Nouse, Herra, leposijaasi, sinä ja sinun väkevyytesi arkki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Sinun pappisi olkoot puetut vanhurskaudella, ja sinun hurskaasi riemuitkoot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Palvelijasi Daavidin tähden älä torju pois voideltusi kasvoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Herra on vannonut Daavidille totisen valan, jota hän ei peruuta: \"Sinun ruumiisi hedelmän minä asetan sinun valtaistuimellesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Jos sinun poikasi pitävät minun liittoni ja minun todistukseni, jotka minä heille opetan, niin saavat heidänkin poikansa istua sinun valtaistuimellasi iankaikkisesti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Sillä Herra on valinnut Siionin, halunnut sen asunnoksensa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, '\"Tämä on minun leposijani iankaikkisesti; tässä minä asun, sillä tänne on minun haluni ollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Siionin ravinnon minä runsaasti siunaan, sen köyhät minä leivällä ruokin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Sen papit minä puetan autuudella, ja sen hurskaat riemuiten riemuitkoot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Siellä minä annan yletä Daavidille sarven, sytytän voidellulleni lampun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Hänen vihollisensa minä puetan häpeällä, mutta hänen päässänsä loistaa hänen kruununsa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Matkalaulu; Daavidin virsi. Katso, kuinka hyvää ja suloista on, että veljekset sovussa asuvat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Se on niinkuin kallis öljy pään päällä, jota tiukkuu partaan-Aaronin partaan, jota tiukkuu hänen viittansa liepeille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Se on niinkuin Hermonin kaste, joka tiukkuu Siionin vuorille. Sillä sinne on Herra säätänyt siunauksen, elämän, ikuisiksi ajoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Matkalaulu. Katso, kiittäkää Herraa, kaikki te Herran palvelijat, jotka öisin seisotte Herran huoneessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Kohottakaa kätenne pyhäkköön päin ja kiittäkää Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Herra siunatkoon sinua Siionista, hän, joka on tehnyt taivaan ja maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Halleluja! Ylistäkää Herran nimeä. Ylistäkää, te Herran palvelijat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'jotka seisotte Herran huoneessa, meidän Jumalamme huoneen esikartanoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Ylistäkää Herraa, sillä Herra on hyvä, veisatkaa kiitosta hänen nimellensä, sillä se on suloinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Sillä Herra on valinnut Jaakobin omaksensa, Israelin omaisuudeksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Sillä minä tiedän, että Herra on suuri, ja meidän Herramme korkeampi kaikkia jumalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Kaiken, mitä Herra tahtoo, hän tekee, sekä taivaassa että maassa, merissä ja kaikissa syvyyksissä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'hän, joka nostaa pilvet maan ääristä, tekee salamat ja sateen ja tuopi tuulen sen säilytyspaikoista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'hän, joka surmasi Egyptin esikoiset, niin ihmisten kuin eläinten;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'hän, joka lähetti tunnusteot ja ihmeet sinun keskellesi, Egypti, faraota ja kaikkia hänen palvelijoitansa vastaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'hän, joka kukisti suuret kansat ja tuotti surman väkeville kuninkaille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Siihonille, amorilaisten kuninkaalle, ja Oogille, Baasanin kuninkaalle, ja kaikille Kanaanin valtakunnille');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'ja antoi heidän maansa perintöosaksi, perintöosaksi kansallensa Israelille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Herra, sinun nimesi pysyy iankaikkisesti, Herra, sinun muistosi polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Sillä Herra hankkii oikeuden kansalleen ja armahtaa palvelijoitansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Pakanain epäjumalat ovat hopeata ja kultaa, ihmiskätten tekoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Niillä on suu, mutta eivät ne puhu, niillä on silmät, mutta eivät näe,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'niillä on korvat, mutta eivät kuule, eikä niillä ole henkeä suussansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Niiden kaltaisia ovat niiden tekijät ja kaikki, jotka niihin turvaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Te, Israelin suku, kiittäkää Herraa, te, Aaronin suku, kiittäkää Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Te, Leevin suku, kiittäkää Herraa, te, Herraa pelkääväiset, kiittäkää Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Kohotkoon Herralle kiitos Siionista, hänelle, joka Jerusalemissa asuu. Halleluja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Kiittäkää Herraa, sillä hän on hyvä, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Kiittäkää jumalien Jumalaa, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Kiittäkää herrain Herraa, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'häntä, joka yksin tekee suuria ihmeitä, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'häntä, joka on taidolla tehnyt taivaat, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'häntä, joka on vetten ylitse levittänyt maan, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'häntä, joka on tehnyt suuret valot, sillä hänen armonsa pysyy iankaikkisesti:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'auringon hallitsemaan päivää, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'kuun ja tähdet hallitsemaan yötä, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'häntä, joka löi Egyptiä surmaten sen esikoiset, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'ja vei Israelin pois heidän keskeltänsä, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'väkevällä kädellä ja ojennetulla käsivarrella, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'häntä, joka jakoi Kaislameren kahtia, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'ja kuljetti Israelin sen keskitse, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'ja syöksi faraon sotajoukkoineen Kaislamereen, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'häntä, joka johdatti kansaansa erämaassa, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'häntä, joka voitti suuret kuninkaat, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'ja surmasi mahtavat kuninkaat, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Siihonin, amorilaisten kuninkaan, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'ja Oogin, Baasanin kuninkaan, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'ja antoi heidän maansa perintöosaksi, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'perintöosaksi palvelijallensa Israelille, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'häntä, joka muisti meitä alennuksessamme, sillä hänen armonsa pysyy iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'ja kirvoitti meidät vihollisistamme, sillä hänen armonsa pysyy iankaikkisesti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'häntä, joka antaa ravinnon kaikelle lihalle, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Kiittäkää taivaan Jumalaa, sillä hänen armonsa pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Baabelin virtain vierillä-siellä me istuimme ja itkimme, kun Siionia muistelimme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Pajuihin, joita siellä oli, me ripustimme kanteleemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Sillä vangitsijamme vaativat meiltä siellä lauluja ja orjuuttajamme iloa: \"Veisatkaa meille Siionin virsiä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Kuinka me voisimme veisata Herran virsiä vieraalla maalla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Jos minä unhotan sinut, Jerusalem, niin unhota sinä minun oikea käteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Tarttukoon kieleni suuni lakeen, ellen minä sinua muista, ellen pidä Jerusalemia ylimpänä ilonani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Muista, Herra, Jerusalemin tuhopäivä, kosta se Edomin lapsille, jotka sanoivat: \"Hajottakaa se, hajottakaa perustuksia myöten!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Tytär Baabel, sinä häviön oma, autuas se, joka sinulle kostaa kaiken, minkä olet meille tehnyt!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Autuas se, joka ottaa sinun pienet lapsesi ja murskaa ne kallioon!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Daavidin virsi. Minä kiitän sinua kaikesta sydämestäni, veisaan sinun kiitostasi jumalien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Minä rukoilen sinua kumartuneena sinun pyhään temppeliisi päin ja kiitän sinun nimeäsi sinun armosi ja totuutesi tähden; sillä sinä olet osoittanut, että sinun lupauksesi on suuri yli kaiken, mitä sinun nimesi ilmoittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Sinä päivänä, jona minä huusin, sinä vastasit minulle; sinä rohkaisit minua: minun sieluni sai voiman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Herra, kaikki maan kuninkaat ylistävät sinua, kun kuulevat sinun suusi sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Ja he veisaavat Herran teistä, sillä suuri on Herran kunnia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Sillä Herra on korkea, mutta katsoo alhaiseen, ja hän tuntee ylpeän kaukaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Vaikka minä vaellan ahdistuksen keskellä, niin sinä virvoitat minut. Sinä ojennat kätesi minun vihamiesteni vihaa vastaan, ja sinun oikea kätesi auttaa minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Herra vie minun asiani päätökseen. Herra, sinun armosi pysyy iankaikkisesti; älä jätä kesken kättesi työtä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Veisuunjohtajalle; Daavidin virsi. Herra, sinä tutkit minua ja tunnet minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Istunpa minä tahi nousen, sinä sen tiedät; sinä ymmärrät minun ajatukseni kaukaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Käynpä tahi makaan, sinä sen havaitset, ja kaikki minun tieni ovat sinulle tutut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Sillä, katso, ei ole sanaa minun kielelläni, jota sinä, Herra, et täysin tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Sinä olet saartanut minut edestä ja takaa ja laskenut kätesi minun päälleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Senkaltainen tieto on minulle ylen ihmeellinen, ylen korkea käsittääkseni sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Minne minä voisin mennä, kussa ei sinun Henkesi olisi, minne paeta sinun kasvojesi edestä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Jos minä taivaaseen nousisin, niin sinä olet siellä; jos minä tuonelaan vuoteeni tekisin, niin katso, sinä olet siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Jos minä kohoaisin aamuruskon siivillä ja asettuisin asumaan meren ääriin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'sielläkin sinun kätesi minua taluttaisi, sinun oikea kätesi tarttuisi minuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Ja jos minä sanoisin: \"Peittäköön minut pimeys, ja valkeus minun ympärilläni tulkoon yöksi\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'niin ei pimeyskään olisi sinulle pimeä: yö valaisisi niinkuin päivä, pimeys olisi niinkuin valkeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Sillä sinä olet luonut minun munaskuuni, sinä kudoit minut kokoon äitini kohdussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Minä kiitän sinua siitä, että olen tehty ylen ihmeellisesti; ihmeelliset ovat sinun tekosi, sen minun sieluni kyllä tietää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Minun luuni eivät olleet sinulta salatut, kun minut salassa valmistettiin, kun minut taiten tehtiin maan syvyyksissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Sinun silmäsi näkivät minut jo idussani. Minun päiväni olivat määrätyt ja kirjoitetut kaikki sinun kirjaasi, ennenkuin ainoakaan niistä oli tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Mutta kuinka kalliit ovat minulle sinun ajatuksesi, Jumala, kuinka suuri on niitten luku!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Jos minä tahtoisin ne lukea, olisi niitä enemmän kuin hiekan jyväsiä. -Minä herään ja olen vielä sinun tykönäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Jumala, jospa sinä surmaisit jumalattomat! Ja te murhamiehet, väistykää minusta pois!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Sillä he puhuvat sinusta petollisesti ja lausuvat turhaan sinun nimesi-nuo sinun vihollisesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Herra, enkö minä vihaisi niitä, jotka sinua vihaavat, enkö inhoaisi niitä, jotka sinua vastustavat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Kaikella vihalla minä heitä vihaan, he ovat minun omia vihollisiani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Tutki minua, Jumala, ja tunne minun sydämeni, koettele minua ja tunne minun ajatukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Ja katso: jos minun tieni on vaivaan vievä, niin johdata minut iankaikkiselle tielle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Veisuunjohtajalle; Daavidin virsi. {140:2} Päästä minut, Herra, pahoista ihmisistä, varjele minut väkivaltaisilta miehiltä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, '{140:3} jotka ajattelevat sydämessään pahaa ja joka päivä yllyttävät sotaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, '{140:4} He hiovat kielensä niinkuin käärmeet, kyykäärmeen myrkkyä on heidän huultensa alla. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, '{140:5} Suojaa minut, Herra, jumalattomien käsiltä, varjele minut väkivaltaisilta miehiltä, jotka tahtovat saada minun jalkani lankeamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, '{140:6} Nuo ylpeät virittävät minulle ansoja ja pauloja, levittävät verkkoja minun tielleni, asettavat minulle pyydyksiä. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, '{140:7} Minä sanon Herralle: \"Sinä olet minun Jumalani\". Herra, ota korviisi minun rukousteni ääni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, '{140:8} Herra, Herra, sinä minun väkevä apuni, sinä suojaat minun pääni taistelun päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, '{140:9} Herra, älä salli, mitä jumalattomat haluavat, älä anna heidän aikeittensa onnistua; muutoin he ylvästelevät. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, '{140:10} Sattukoon minun saartajaini omaan päähän onnettomuus, jota heidän huulensa hankkivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, '{140:11} Tulkoon tulisia hiiliä heidän päällensä; hän syösköön heidät tuleen, vesivirtoihin, joista he älkööt nousko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, '{140:12} Kielevä mies ei ole pysyvä maassa; väkivaltaista ajaa onnettomuus ja iskee iskemistään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, '{140:13} Minä tiedän, että Herra ajaa kurjan asiaa, hankkii köyhille oikeuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, '{140:14} Totisesti, vanhurskaat saavat kiittää sinun nimeäsi, ja oikeamieliset saavat asua sinun kasvojesi edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Daavidin virsi. Herra, minä huudan sinua, riennä minun tyköni. Ota korviisi minun ääneni, kun minä sinua huudan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Minun rukoukseni olkoon suitsutusuhri sinun kasvojesi edessä, minun kätteni kohottaminen olkoon ehtoouhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Herra, pane minun suulleni vartija, vartioitse minun huulteni ovea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Älä salli minun sydämeni taipua pahaan, pitämään jumalatonta menoa väärintekijäin kanssa. Minä en tahdo maistaa heidän herkkupalojansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Lyököön minua vanhurskas: se on rakkautta; kurittakoon hän minua: se on öljyä minun päähäni, siitä minun pääni älköön kieltäytykö. Sillä vielä vähän aikaa, niin minun rukoukseni täyttyy, mutta heidän käy pahoin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'heidän päämiehensä syöstään kalliolta alas, ja silloin kuullaan minun sanani suloisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Niinkuin maa kynnetään ja kuokitaan, niin ovat meidän luumme hajotetut tuonelan kuilun suulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Mutta sinuun, Herra, Herra, minun silmäni katsovat, sinuun minä turvaan. Älä hylkää minun sieluani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Varjele minua niiden pauloista, jotka minua pyydystävät, väärintekijäin ansoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Kaatukoot kaikki jumalattomat omiin kuoppiinsa; mutta suo minun ne välttää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Daavidin mietevirsi, hänen ollessaan luolassa; rukous. {142:2} Minä korotan ääneni ja huudan Herraa, minä korotan ääneni ja rukoilen Herralta armoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, '{142:3} Minä vuodatan hänen eteensä valitukseni, kerron hänelle ahdistukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, '{142:4} Kun minun henkeni minussa nääntyy, niin sinä tunnet minun tieni. Polulle, jota minä käyn, he ovat virittäneet paulan minun eteeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, '{142:5} Katso minun oikealle puolelleni ja näe: ei kukaan minua tunne. Ei ole minulla pakopaikkaa, ei kukaan minun sielustani välitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, '{142:6} Minä huudan sinun puoleesi, Herra; minä sanon: Sinä olet minun turvani, minun osani elävien maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, '{142:7} Tarkkaa minun huutoani, sillä minä olen sangen viheliäinen, pelasta minut vainoojistani, sillä he ovat minua väkevämmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, '{142:8} Vie minun sieluni ulos vankeudesta kiittämään sinun nimeäsi. Vanhurskaat kokoontuvat minun ympärilleni, kun sinä minulle hyvin teet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Daavidin virsi. Herra, kuule minun rukoukseni, ota korviisi minun anomiseni. Vastaa minulle uskollisuudessasi ja vanhurskaudessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Älä käy tuomiolle palvelijasi kanssa, sillä ei yksikään elävä ole vanhurskas sinun edessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Sillä vihollinen vainoaa minun sieluani, hän on ruhjonut minun elämäni maahan ja pannut minut pimeään niinkuin ammoin kuolleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Minun henkeni nääntyy minussa, sydäntäni kouristaa minun rinnassani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Minä muistelen muinaisia päiviä, tutkistelen kaikkia sinun töitäsi ja ajattelen sinun kättesi tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Minä levitän käteni sinun puoleesi. Niinkuin janoinen maa, niin minun sieluni halajaa sinua. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Vastaa minulle pian, Herra, minun henkeni nääntyy. Älä peitä minulta kasvojasi, etten tulisi niiden kaltaiseksi, jotka hautaan vaipuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Suo minun varhain kuulla sinun armoasi, sillä sinuun minä turvaan. Osoita minulle tie, jota minun tulee käydä, sillä sinun tykösi minä ylennän sieluni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Pelasta minut vihollisistani, Herra. Sinun tykösi minä pyrin suojaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Opeta minut tekemään sitä, mikä sinulle kelpaa, sillä sinä olet minun Jumalani. Sinun hyvä Henkesi johdattakoon minua tasaista maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Herra, virvoita nimesi tähden, vanhurskaudessasi auta minun sieluni ahdistuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Tuhoa minun viholliseni armosi tähden ja hukuta kaikki, jotka minun sieluani ahdistavat, sillä minä olen sinun palvelijasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Daavidin virsi. Kiitetty olkoon Herra, minun kallioni, joka opettaa minun käteni taistelemaan, minun sormeni sotimaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'hän, joka antaa minulle armon; minun linnani, varustukseni ja pelastajani, minun kilpeni, jonka turviin minä pakenen, hän, joka laskee kansani minun valtani alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Herra, mikä on ihminen, että hänestä lukua pidät, mikä ihmislapsi, että häntä ajattelet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Ihminen on kuin tuulen henkäys, hänen päivänsä niinkuin pakeneva varjo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Herra, notkista taivaasi ja astu alas, kosketa vuoria, niin että ne suitsuavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Iske salamoita ja hajota heidät, lennätä nuolesi ja kauhistuta heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Ojenna kätesi korkeudesta, tempaa ja pelasta minut suurista vesistä, muukalaisten kädestä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'joiden suu puhuu vilppiä ja joiden oikea käsi on valheen käsi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Jumala, minä veisaan sinulle uuden virren, soitan sinulle kymmenkielisellä harpulla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'sinulle, joka annat kuninkaille voiton ja tempaat palvelijasi Daavidin turvaan pahalta miekalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Tempaa ja pelasta minut muukalaisten käsistä, joiden suu puhuu vilppiä ja joiden oikea käsi on valheen käsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Niin meidän poikamme ovat nuoruudessaan kuin korkealle kohoavat kasvit, tyttäremme kuin temppelin veistetyt kulmapatsaat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'meidän aittamme ovat täynnä, ja antavat kaikkinaista viljaa, meidän lampaamme lisääntyvät laitumillamme tuhansin ja kymmenin tuhansin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'meidän härkiemme kuormat ovat runsaat, ei ole aukkoa muurissa, ei ole pakolaista, ei kuulu valitushuutoa kaduillamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Autuas se kansa, jolle näin käy, autuas se kansa, jonka Jumala Herra on!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Daavidin ylistysvirsi. Minä kunnioitan sinua, Jumalani, sinä kuningas, ja kiitän sinun nimeäsi aina ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Joka päivä minä kiitän sinua ja ylistän sinun nimeäsi aina ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Suuri on Herra ja sangen ylistettävä, ja hänen suuruutensa on tutkimaton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Sukupolvi ylistää sukupolvelle sinun tekojasi, ja he julistavat sinun voimallisia töitäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Sinun valtasuuruutesi kirkkautta ja kunniaa ja sinun ihmeellisiä tekojasi minä tahdon tutkistella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Sinun peljättävien töittesi voimasta puhutaan, sinun suurista teoistasi minä kerron.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Julistettakoon sinun suuren hyvyytesi muistoa ja sinun vanhurskaudestasi riemuittakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Herra on armahtavainen ja laupias, pitkämielinen ja suuri armossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Herra on hyvä kaikille ja armahtaa kaikkia tekojansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Kaikki sinun tekosi ylistävät sinua, Herra, ja sinun hurskaasi kiittävät sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'He puhuvat sinun valtakuntasi kunniasta ja kertovat sinun voimastasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Niin he ilmoittavat ihmislapsille hänen voimalliset työnsä ja hänen valtakuntansa kirkkauden ja kunnian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Sinun valtakuntasi on iankaikkinen valtakunta, ja sinun herrautesi pysyy polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Herra tukee kaikkia kaatuvia, ja kaikki alaspainetut hän nostaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Kaikkien silmät vartioitsevat sinua, ja sinä annat heille heidän ruokansa ajallaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Sinä avaat kätesi ja ravitset suosiollasi kaikki, jotka elävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Herra on vanhurskas kaikissa teissään ja armollinen kaikissa teoissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Herra on lähellä kaikkia, jotka häntä avuksensa huutavat, kaikkia, jotka totuudessa häntä avuksensa huutavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Hän tekee, mitä häntä pelkääväiset halajavat, hän kuulee heidän huutonsa ja auttaa heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Herra varjelee kaikkia, jotka häntä rakastavat, mutta kaikki jumalattomat hän hukuttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Minun suuni lausukoon Herran ylistystä, ja kaikki liha kiittäköön hänen pyhää nimeänsä, aina ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Halleluja! Ylistä, minun sieluni, Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Minä ylistän Herraa kaiken ikäni, veisaan kiitosta Jumalalleni, niin kauan kuin elän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Älkää luottako ruhtinaihin älkääkä ihmislapseen, sillä ei hän voi auttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Kun hänen henkensä lähtee hänestä, niin hän tulee maaksi jälleen; sinä päivänä hänen hankkeensa raukeavat tyhjiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Autuas se, jonka apuna on Jaakobin Jumala, se, joka panee toivonsa Herraan, Jumalaansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'häneen, joka on tehnyt taivaan ja maan, meren ja kaiken, mitä niissä on, joka pysyy uskollisena iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'joka hankkii oikeuden sorretuille, joka antaa leivän nälkäisille. Herra vapauttaa vangitut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Herra avaa sokeain silmät, Herra nostaa alaspainetut, Herra rakastaa vanhurskaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Herra varjelee muukalaiset, holhoo orvot ja lesket, mutta jumalattomain tien hän tekee mutkaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Herra on kuningas iankaikkisesti, sinun Jumalasi, Siion, polvesta polveen. Halleluja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Halleluja! Hyvä on veisata kiitosta meidän Jumalallemme. Se on suloista; ylistäminen on soveliasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Herra rakentaa Jerusalemin, hän kokoaa Israelin karkoitetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Hän parantaa ne, joilla on särjetty sydän, ja sitoo heidän haavansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Hän on määrännyt tähtien luvun, hän kutsuu niitä kaikkia nimeltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Meidän Herramme on suuri, suuri voimassansa, hänen ymmärryksensä on mittaamaton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Herra pitää pystyssä nöyrät, mutta jumalattomat hän painaa maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Veisatkaa Herralle kiitosvirsi, soittakaa kanteleilla kiitosta meidän Jumalallemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Hän peittää pilvillä taivaan ja valmistaa sateen maalle; hän kasvattaa ruohon vuorille');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'ja antaa ruuan eläimille, kaarneen pojillekin, kun ne huutavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Ei kelpaa hänelle hevosen voima, ei hän mielisty miehen jalkojen nopeuteen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Herra mielistyy niihin, jotka häntä pelkäävät, jotka panevat toivonsa hänen armoonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Kiitä Herraa, Jerusalem. Ylistä Jumalaasi, Siion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Sillä hän tekee lujiksi sinun porttiesi salvat; hän siunaa sinun lapsesi sinun keskelläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Hän hankkii rauhan sinun rajojesi sisälle, ravitsee sinut parhaalla nisulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Hän lähettää sanansa maahan, nopeasti kiitää hänen käskynsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Hän antaa sataa lunta niinkuin villaa ja sirottaa härmää niinkuin tuhkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Hän viskaa rakeitansa niinkuin leivänmuruja; kuka voi kestää hänen pakkastansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Hän lähettää sanansa ja sulattaa rakeet; hän panee tuulensa puhaltamaan, ja vedet virtaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Hän ilmoittaa sanansa Jaakobille, käskynsä ja oikeutensa Israelille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Niin hän ei ole tehnyt yhdellekään pakanakansalle, ja hänen oikeuksiansa ne eivät tunne. Halleluja! 148 PSALMI.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Halleluja! Ylistäkää Herraa taivaista, ylistäkää häntä korkeuksissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Ylistäkää häntä, kaikki hänen enkelinsä, ylistäkää häntä, kaikki hänen sotajoukkonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Ylistäkää häntä, aurinko ja kuu, ylistäkää häntä, kaikki kirkkaat tähdet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Ylistäkää häntä, te taivasten taivaat, te vedet taivasten päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Ylistäkööt ne Herran nimeä, sillä hän käski, ja ne tulivat luoduiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Ja hän asetti ne olemaan aina ja iankaikkisesti, hän antoi niille lain, josta ne eivät poikkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Ylistäkää Herraa maasta, te merieläimet ja kaikki syvyydet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'tuli ja rakeet, lumi ja sumu, sinä myrskytuuli, joka panet hänen käskynsä toimeen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'te vuoret ja kaikki kukkulat, te hedelmäpuut ja kaikki setrit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'te pedot ja kaikki karja, te matelijat ja siivekkäät linnut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'te maan kuninkaat ja kaikki kansakunnat, te ruhtinaat ja kaikki maan tuomarit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'te nuorukaiset ynnä neitsyet, te vanhat yhdessä nuorten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Ylistäkööt he Herran nimeä, sillä hänen nimensä yksin on korkea, hänen valtasuuruutensa ulottuu yli maan ja taivaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Hän on korottanut sarven kansallensa, että häntä ylistäisivät kaikki hänen hurskaansa, Israelin lapset, kansa, joka on häntä lähellä. Halleluja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Halleluja! Veisatkaa Herralle uusi virsi: ylistysvirsi hänelle hurskasten seurakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Iloitkoon Israel tekijästänsä, Siionin lapset riemuitkoot kuninkaastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Ylistäkööt he karkeloiden hänen nimeänsä, soittakoot hänelle kiitosta vaskirummuilla ja kanteleilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Sillä Herra on mielistynyt kansaansa, hän kaunistaa nöyrät pelastuksella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Iloitkoot hurskaat, veisaten hänen kunniaansa, riemuitkoot he vuoteissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Jumalan ylistys on heidän suussansa, ja heidän kädessään kaksiteräinen miekka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'että he kostaisivat pakanoille, kurittaisivat kansakuntia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'panisivat kahleisiin heidän kuninkaansa ja jalkarautoihin heidän ylhäisensä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'ja täyttäisivät heissä tuomion, joka on kirjoitettu. Tämä on kaikkien hänen hurskaittensa kunnia. Halleluja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Halleluja! Ylistäkää Jumalaa hänen pyhäkössään, ylistäkää häntä hänen väkevyytensä taivaanvahvuuksissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Ylistäkää häntä hänen voimallisista teoistansa, ylistäkää häntä, sillä hänen herrautensa on suuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Ylistäkää häntä pasunan pauhulla, ylistäkää häntä harpuilla ja kanteleilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Ylistäkää häntä vaskirummuilla ja karkelolla, ylistäkää häntä kielisoittimilla ja huiluilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Ylistäkää häntä helisevillä kymbaaleilla, ylistäkää häntä kumisevilla kymbaaleilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Kaikki, joissa henki on, ylistäkää Herraa! Halleluja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Salomon, Daavidin pojan, Israelin kuninkaan, sananlaskut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'viisauden ja kurin oppimiseksi, ymmärryksen sanojen ymmärtämiseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'taitoa tuovan kurin, vanhurskauden, oikeuden ja vilpittömyyden saamiseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'mielevyyden antamiseksi yksinkertaisille, tiedon ja taidollisuuden nuorille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Viisas kuulkoon ja saakoon oppia lisää, ja ymmärtäväinen hankkikoon elämänohjetta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'ymmärtääkseen sananlaskuja ja vertauksia, viisasten sanoja ja heidän ongelmiansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Herran pelko on tiedon alku; hullut pitävät halpana viisauden ja kurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Kuule, poikani, isäsi kuritusta äläkä hylkää äitisi opetusta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'sillä ne ovat ihana seppele sinun päähäsi ja käädyt sinun kaulaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Poikani, jos synnintekijät sinua viekoittelevat, älä suostu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Jos he sanovat: \"Lähde mukaamme! Väijykäämme verta, vaanikaamme viatonta syyttömästi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'nielaiskaamme niinkuin tuonela heidät elävältä, ehyeltään, niinkuin hautaan vaipuvaiset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'me saamme kaikenlaista kallista tavaraa, täytämme talomme saaliilla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'heitä arpasi meidän kanssamme, yhteinen kukkaro olkoon meillä kaikilla\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Älä lähde, poikani, samalle tielle kuin he, pidätä jalkasi heidän poluiltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Sillä heidän jalkansa juoksevat pahuuteen, kiiruhtavat vuodattamaan verta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Sillä verkko on viritetty kaikille siivekkäille, niin että ne sen näkevät. -Mutta turhaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'omaa vertansa he väijyvät, vaanivat omaa henkeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Näin käy jokaiselle väärän voiton pyytäjälle: se ottaa haltijaltaan hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Viisaus huutaa kadulla, antaa äänensä kuulua toreilla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'meluisten katujen kulmissa se kutsuu, porttien ovilta kaupungissa sanansa sanoo:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Kuinka kauan te, yksinkertaiset, rakastatte yksinkertaisuutta, kuinka kauan pilkkaajilla on halu pilkkaan ja tyhmät vihaavat tietoa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Kääntykää minun nuhdeltavikseni. Katso, minä vuodatan teille henkeäni, saatan sanani tiedoksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Kun minä kutsuin ja te estelitte, kun ojensin kättäni eikä kenkään kuunnellut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'vaan te vieroksuitte kaikkia minun neuvojani, ette suostuneet minun nuhteisiini,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'niin minäkin nauran teidän hädällenne, pilkkaan, kun tulee se, mitä te kauhistutte;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'kun myrskynä tulee se, mitä te kauhistutte, kun hätänne saapuu tuulispäänä, kun päällenne tulee vaiva ja ahdistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Silloin he minua kutsuvat, mutta minä en vastaa, etsivät minua, mutta eivät löydä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Koska he vihasivat tietoa, eivät valinneet osaksensa Herran pelkoa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'eivätkä suostuneet minun neuvooni, vaan katsoivat kaiken minun nuhteluni halvaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'saavat he syödä oman vaelluksensa hedelmiä ja saavat kyllänsä omista hankkeistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Sillä yksinkertaiset tappaa heidän oma luopumuksensa, ja tyhmät tuhoaa heidän oma suruttomuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Mutta joka minua kuulee, saa asua turvassa ja olla rauhassa onnettomuuden kauhuilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Poikani, jos sinä otat minun sanani varteen ja kätket mieleesi minun käskyni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'niin että herkistät korvasi viisaudelle ja taivutat sydämesi taitoon-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'niin, jos kutsut ymmärrystä ja ääneesi huudat taitoa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'jos haet sitä kuin hopeata ja etsit sitä kuin aarretta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'silloin pääset ymmärtämään Herran pelon ja löydät Jumalan tuntemisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Sillä Herra antaa viisautta, hänen suustansa lähtee tieto ja taito.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'Oikeamielisille hänellä on tallella pelastus, kilpi nuhteettomasti vaeltaville,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'niin että hän suojaa oikeuden polut ja varjelee hurskaittensa tien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Silloin ymmärrät vanhurskauden ja oikeuden ja vilpittömyyden-hyvyyden tien kaiken;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'sillä viisaus tulee sydämeesi, ja tieto tulee sielullesi suloiseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'taidollisuus on sinua varjeleva ja ymmärrys suojeleva sinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Se pelastaa sinut pahojen tiestä, miehestä, joka kavalasti puhuu;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'niistä, jotka ovat hyljänneet oikeat polut vaeltaaksensa pimeyden teitä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'niistä, jotka iloitsevat pahanteosta, riemuitsevat häijystä kavaluudesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'joiden polut ovat mutkaiset ja jotka joutuvat väärään teillänsä. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Se pelastaa sinut irstaasta naisesta, vieraasta vaimosta, joka sanoillansa liehakoitsee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'joka on hyljännyt nuoruutensa ystävän ja unhottanut Jumalansa liiton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Sillä hänen huoneensa kallistuu kohti kuolemaa, hänen tiensä haamuja kohden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Ei palaja kenkään, joka hänen luoksensa menee, eikä saavu elämän poluille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Niin sinä vaellat hyvien tietä ja noudatat vanhurskasten polkuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Sillä oikeamieliset saavat asua maassa, ja nuhteettomat jäävät siihen jäljelle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'mutta jumalattomat hävitetään maasta, ja uskottomat siitä reväistään pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Poikani, älä unhota minun opetustani, vaan sinun sydämesi säilyttäköön minun käskyni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'sillä pitkää ikää, elinvuosia ja rauhaa ne sinulle kartuttavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Laupeus ja uskollisuus älkööt hyljätkö sinua. Sido ne kaulaasi, kirjoita ne sydämesi tauluun,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'niin saat armon ja hyvän ymmärryksen Jumalan ja ihmisten silmien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Turvaa Herraan kaikesta sydämestäsi äläkä nojaudu omaan ymmärrykseesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Tunne hänet kaikilla teilläsi, niin hän sinun polkusi tasoittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Älä ole viisas omissa silmissäsi. Pelkää Herraa ja karta pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'Se on terveellistä sinun ruumiillesi ja virkistävää sinun luillesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Kunnioita Herraa antamalla varoistasi ja kaiken satosi parhaimmasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'niin sinun jyväaittasi täyttyvät runsaudella, ja viini pursuu sinun kuurnistasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Poikani, älä pidä Herran kuritusta halpana äläkä kyllästy hänen rangaistukseensa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'sillä jota Herra rakastaa, sitä hän rankaisee, niinkuin isä poikaa, joka hänelle rakas on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Autuas se ihminen, joka on löytänyt viisauden, ihminen, joka on saanut taidon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Sillä parempi on hankkia sitä kuin hopeata, ja siitä saatu voitto on kultaa jalompi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Se on kalliimpi kuin helmet, eivät mitkään kalleutesi vedä sille vertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Pitkä ikä on sen oikeassa kädessä, vasemmassa rikkaus ja kunnia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Sen tiet ovat suloiset tiet, sen polut rauhaisat kaikki tyynni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Elämän puu on se niille, jotka siihen tarttuvat; onnelliset ne, jotka siitä pitävät kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Herra on viisaudella perustanut maan, taivaat taidolla vahvistanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Hänen toimestansa syvyydet kuohuivat esiin, ja pilvet pisaroivat kastetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Poikani, nämä älkööt häipykö näkyvistäsi, säilytä neuvokkuus ja taidollisuus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'niin ne ovat elämä sinun sielullesi ja kaunistus sinun kaulaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Silloin sinä kuljet tiesi turvallisesti etkä loukkaa jalkaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Kun menet maata, et pelkää mitään, ja maata mentyäsi on unesi makea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Pääset peljästymästä äkkikauhistuksia ja turmiota, joka jumalattomat yllättää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Sillä sinä saat luottaa Herraan, hän varjelee sinun jalkasi joutumasta kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Älä kiellä tarvitsevalta hyvää, milloin sitä tehdä voit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Älä sano lähimmäisellesi: \"Mene nyt ja tule toiste, huomenna minä annan\", kun sinulla kuitenkin on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Älä mieti pahaa lähimmäistäsi vastaan, kun hän luottavaisesti luonasi asuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Älä riitele kenenkään kanssa syyttä, kun ei toinen ole sinulle pahaa tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Älä kadehdi väkivallan miestä äläkä hänen teitänsä omiksesi valitse;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'sillä väärämielinen on Herralle kauhistus, mutta oikeamielisille hän on tuttava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Herran kirous on jumalattoman huoneessa, mutta vanhurskasten asuinsijaa hän siunaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Pilkkaajille hänkin on pilkallinen, mutta nöyrille hän antaa armon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Viisaat perivät kunnian, mutta tyhmäin osa on häpeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Kuulkaa, lapset, isän kuritusta ja kuunnelkaa oppiaksenne ymmärrystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Sillä minä annan teille hyvän neuvon, älkää hyljätkö minun opetustani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Olinhan minäkin isäni poika, hento ja äitini ainokainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'Ja isä minua opetti ja sanoi minulle: \"Pitäköön sydämesi minun sanoistani kiinni, noudata minun käskyjäni, niin sinä saat elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Hanki viisautta, hanki ymmärrystä, älä sitä unhota, älä väisty pois minun suuni sanoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Älä sitä hylkää, niin se varjelee sinua; rakasta sitä, niin se sinua suojaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Viisauden alku on: hanki viisautta, ja kaikella muulla hankkimallasi hanki ymmärrystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Anna sille korkea arvo, niin se sinut korottaa, se kunnioittaa sinua, jos sen syliisi suljet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'se panee päähäsi ihanan seppeleen ja lahjoittaa sinulle kauniin kruunun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Kuule, poikani, ja ota sanani varteen, niin elämäsi vuodet enentyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Minä neuvon sinut viisauden tielle, ohjaan sinut oikeille teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Käydessäsi eivät askeleesi ahtaalle joudu; juostessasi et kompastu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Tartu kiinni kuritukseen äläkä hellitä; säilytä se, sillä se on sinun elämäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Älä lähde jumalattomien polulle, älä astu pahojen tielle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Anna sen olla, älä mene sille, poikkea pois ja mene ohitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Sillä eivät he saa nukkua, elleivät pahaa tee; se riistää heiltä unen, elleivät ole ketään kaataneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Niin he syövät leipänään jumalattomuutta, juovat viininään väkivallan tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Mutta vanhurskasten polku on kuin aamurusko, joka kirkastuu kirkastumistaan sydänpäivään saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Jumalattomain tie on kuin pimeys: eivät he tiedä, mihin kompastuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Poikani, kuuntele minun puhettani, kallista korvasi minun sanoilleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Älkööt ne väistykö silmistäsi, kätke ne sydämesi sisimpään;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'sillä ne ovat elämä sille, joka ne löytää, ja lääke koko hänen ruumiillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Yli kaiken varottavan varjele sydämesi, sillä sieltä elämä lähtee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Poista itsestäsi suun kavaluus, ja karkoita luotasi huulten vääryys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Katsokoot sinun silmäsi suoraan, eteenpäin olkoon katseesi luotu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Tasoita polku jaloillesi, ja kaikki sinun tiesi olkoot vakaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Älä poikkea oikeaan, älä vasempaan, väistä jalkasi pahasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Poikani, kuuntele minun viisauttani, kallista korvasi minun taidolleni');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'ottaaksesi vaarin taidollisuudesta, ja huulesi säilyttäkööt tiedon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Sillä hunajaa tiukkuvat vieraan vaimon huulet, hänen suunsa on öljyä liukkaampi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Mutta lopulta hän on karvas kuin koiruoho, terävä kuin kaksiteräinen miekka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Hänen jalkansa kulkevat alas kuolemaan, tuonelaan vetävät hänen askeleensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Ei käy hän elämän tasaista polkua, hänen tiensä horjuvat hänen huomaamattaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Niinpä, lapset, kuulkaa minua, älkää väistykö minun suuni sanoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Pidä tiesi kaukana tuollaisesta äläkä lähesty hänen majansa ovea,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'ettet antaisi muille kunniaasi etkä vuosiasi armottomalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'ettei sinun tavarasi ravitsisi vieraita, sinun vaivannäkösi joutuisi toisen taloon');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'ja ettet lopulta päätyisi huokailemaan ruumiisi ja lihasi riutuessa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'ja sanomaan: \"Miksi minä kuritusta vihasin ja sydämeni halveksui nuhdetta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Miksi en kuullut neuvojaini ääntä, kallistanut korvaani opettajilleni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Olin joutua kokonaan turmion omaksi keskellä seurakunnan ja kansankokouksen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Juo vettä omasta säiliöstäsi, sitä, mikä omasta kaivostasi juoksee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Vuotaisivatko sinun lähteesi kadulle, toreille sinun vesiojasi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Olkoot ne sinun omasi yksin, älkööt vierasten sinun ohessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Olkoon sinun lähteesi siunattu, ja iloitse nuoruutesi vaimosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Armas peura, suloinen vuorikauris-hänen rintansa sinua aina riemulla ravitkoot, hurmautuos alati hänen rakkaudestaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Miksi, poikani, hurmautuisit irstaaseen naiseen ja syleilisit vieraan vaimon povea?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Sillä Herran silmien edessä ovat miehen tiet, ja hän tutkii kaikki hänen polkunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Jumalattoman vangitsevat hänen rikoksensa, ja hän tarttuu oman syntinsä pauloihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Kurittomuuteensa hän kuolee ja suistuu harhaan suuressa hulluudessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Poikani, jos olet ketä lähimmäisellesi taannut, lyönyt kättä vieraalle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'jos olet kietoutunut oman suusi sanoihin, joutunut suusi sanoista kiinni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'niin tee toki, poikani, pelastuaksesi tämä, koska olet joutunut lähimmäisesi kouriin: Mene, heittäydy maahan ja ahdista lähimmäistäsi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Älä suo silmillesi unta äläkä silmäluomillesi lepoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Pelastaudu käsistä niinkuin gaselli, niinkuin lintu pyydystäjän käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Mene, laiska, muurahaisen tykö, katso sen menoja ja viisastu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Vaikka sillä ei ole ruhtinasta, ei päällysmiestä eikä hallitsijaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'se kuitenkin hankkii leipänsä kesällä ja kokoaa varastoon ruokansa elonaikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Kuinka kauan sinä, laiska, makaat, milloinka nouset unestasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Nuku vielä vähän, torku vähän, makaa vähän ristissä käsin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'niin köyhyys käy päällesi niinkuin rosvo ja puute niinkuin asestettu mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Kelvoton ihminen, väärä mies on se, joka kulkee suu täynnä vilppiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'silmää iskee, jaloillaan merkkiä antaa, sormillansa viittoo,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'kavaluus mielessä, pahaa aina hankitsee, riitoja rakentaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Sentähden hänen turmionsa tulee yhtäkkiä, tuokiossa hänet rusennetaan, eikä apua ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Näitä kuutta Herra vihaa, ja seitsemää hänen sielunsa kauhistuu:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'ylpeitä silmiä, valheellista kieltä, käsiä, jotka vuodattavat viatonta verta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'sydäntä, joka häijyjä juonia miettii, jalkoja, jotka kiiruusti juoksevat pahaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'väärää todistajaa, joka valheita puhuu, ja riidan rakentajaa veljesten kesken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Säilytä, poikani, isäsi käsky äläkä hylkää äitisi opetusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Pidä ne aina sydämellesi sidottuina, kääri ne kaulasi ympärille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Kulkiessasi ne sinua taluttakoot, maatessasi sinua vartioikoot, herätessäsi sinua puhutelkoot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Sillä käsky on lamppu, opetus on valo, ja kurittava nuhde on elämän tie,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'että varjeltuisit pahasta naisesta, vieraan vaimon liukkaasta kielestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Älköön sydämesi himoitko hänen kauneuttaan, älköönkä hän sinua katseillaan vangitko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Sillä porttonaisen tähden menee leipäkakkukin, ja naitu nainen pyydystää kallista sielua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Voiko kukaan kuljettaa tulta helmassaan, puvun häneltä palamatta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Voiko kukaan kävellä hiilloksella, jalkain häneltä kärventymättä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Samoin käy sen, joka menee lähimmäisensä vaimon luo: ei jää rankaisematta kukaan, joka häneen kajoaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Eikö halveksita varasta, vaikka hän olisi nälissään varastanut hengenpiteikseen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Onhan hänen, jos tavataan, seitsenkertaisesti korvattava, annettava kaikki talonsa varat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Joka vaimon kanssa avion rikkoo, on mieletön; itsensä menettää, joka niin tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Hän saa vaivan ja häpeän, eikä hänen häväistystään pyyhitä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Sillä luulevaisuus nostaa miehen vihan, ja säälimätön on hän koston päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Ei hän huoli mistään lunastusmaksusta, ei suostu, vaikka kuinka lahjaasi lisäät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Poikani, noudata minun sanojani ja kätke mieleesi minun käskyni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Noudata minun käskyjäni, niin saat elää, säilytä opetukseni kuin silmäteräsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Sido ne kiinni sormiisi, kirjoita ne sydämesi tauluun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Sano viisaudelle: \"Sinä olet sisareni\", kutsu ymmärrystä sukulaiseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'että varjeltuisit irstaalta naiselta, vieraalta vaimolta, joka sanoillansa liehakoitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Sillä minä katselin taloni ikkunasta ristikon läpi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'ja minä näin yksinkertaisten joukossa, havaitsin poikain seassa nuorukaisen, joka oli mieltä vailla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Hän kulki katua erään naisen kulmaukseen ja asteli hänen majaansa päin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'päivän illaksi hämärtyessä, yön aikana, pimeässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'Ja katso, nainen tulee häntä vastaan, porton puvussa, kavala sydämeltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Hän on levoton ja hillitön, eivät pysy hänen jalkansa kotona;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'milloin hän on kadulla, milloin toreilla, ja väijyy joka kulmassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'Hän tarttui nuorukaiseen, suuteli häntä ja julkeasti katsoen sanoi hänelle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, '\"Minun oli uhrattava yhteysuhri, tänä päivänä olen täyttänyt lupaukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Sentähden läksin ulos sinua vastaan, etsiäkseni sinua, ja olen sinut löytänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Olen leposijalleni peitteitä levittänyt, kirjavaa Egyptin liinavaatetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Vuoteeseeni olen pirskoitellut mirhaa, aloeta ja kanelia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Tule, nauttikaamme lemmestä aamuun asti, riemuitkaamme rakkaudesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Sillä mieheni ei ole kotona, hän meni matkalle kauas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Rahakukkaron hän otti mukaansa ja tulee kotiin vasta täydenkuun päiväksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Hän taivutti hänet paljolla houkuttelullaan, vietteli liukkailla huulillansa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'kkiä hän lähti hänen jälkeensä, niinkuin härkä menee teuraaksi, niinkuin hullu jalkaraudoissa kuritettavaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'niinkuin lintu kiiruhtaa paulaan; eikä tiennyt, että oli henkeänsä kaupalla, kunnes nuoli lävisti hänen maksansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Sentähden, poikani, kuulkaa minua, kuunnelkaa minun suuni sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Älköön poiketko sydämesi tuon naisen teille, älä eksy hänen poluillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Sillä paljon on surmattuja, hänen kaatamiaan, lukuisasti niitä, jotka hän on kaikki tappanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Hänen majastaan käyvät tuonelan tiet, jotka vievät alas tuonelan kammioihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Eikö viisaus kutsu, eikö taito anna äänensä kuulua?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Ylös kummuille, tien viereen, polkujen risteyksiin hän on asettunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'Porttien pielissä, kaupungin portilla, oviaukoissa hän huutaa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, '\"Teitä minä kutsun, miehet, ja ihmislapsille kaikuu minun ääneni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Tulkaa, yksinkertaiset, mieleviksi; tulkaa järkeviksi, te tyhmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Kuulkaa, sillä jalosti minä puhun, ja avaan huuleni puhumaan, mikä oikein on;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'sillä totuutta minun suuni haastaa, ja jumalattomuus on minun huulilleni kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Vanhurskaat ovat minun suuni sanat kaikki, ei ole niissä mitään petollista, ei väärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Ne ovat kaikki oikeat ymmärtäväiselle, suorat niille, jotka löysivät tiedon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Ottakaa minun kuritukseni, älkääkä hopeata, ja tieto ennen valituinta kultaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Sillä parempi on viisaus kuin helmet, eivät mitkään kalleudet vedä sille vertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Minä, viisaus, olen perehtynyt mielevyyteen, olen löytänyt tiedon ja taidollisuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Herran pelko on pahan vihaamista. Kopeutta ja ylpeyttä, pahaa tietä ja kavalaa suuta minä vihaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Minulla on neuvo ja neuvokkuus; minä olen ymmärrys, minulla on voima.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Minun avullani kuninkaat hallitsevat, ruhtinaat säädöksensä vanhurskaasti säätävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Minun avullani päämiehet vallitsevat ja ylhäiset, maan tuomarit kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Minä rakastan niitä, jotka minua rakastavat, ja jotka minua varhain etsivät, ne löytävät minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Minun tykönäni on rikkaus ja kunnia, ikivanha varallisuus ja vanhurskaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Minun hedelmäni on parempi kuin kulta, kuin puhtain kulta, minun antamani voitto valituinta hopeata parempi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Minä vaellan vanhurskauden polkua, oikeuden teitten keskikohtaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'antaakseni niille, jotka minua rakastavat, pysyvän perinnön ja täyttääkseni heidän aarrekammionsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Herra loi minut töittensä esikoiseksi, ensimmäiseksi teoistaan, ennen aikojen alkua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Iankaikkisuudesta minä olen asetettu olemaan, alusta asti, hamasta maan ikiajoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Ennenkuin syvyyksiä oli, synnyin minä, ennenkuin oli lähteitä, vedestä rikkaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Ennenkuin vuoret upotettiin paikoilleen, ennen kukkuloita, synnyin minä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'kun hän ei vielä ollut tehnyt maata, ei mantua, ei maanpiirin tomujen alkuakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Kun hän taivaat valmisti, olin minä siinä, kun hän veti piirin syvyyden pinnalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'kun hän teki vahvoiksi pilvet korkeudessa, kun syvyyden lähteet saivat voiman,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'kun hän merelle asetti sen rajat, että vedet eivät kävisi hänen käskynsä yli, kun hän vahvisti maan perustukset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'silloin minä hänen sivullansa hoidokkina olin, ihastuksissani olin päivästä päivään ja leikitsin hänen edessänsä kaikin ajoin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'leikitsin hänen maanpiirinsä päällä, ja ihastukseni olivat ihmislapset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Siis te, lapset, kuulkaa minua; autuaat ne, jotka noudattavat minun teitäni!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Kuritusta kuulkaa, niin viisastutte; älkää sen antako mennä menojaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Autuas se ihminen, joka minua kuulee, valvoo minun ovillani päivästä päivään, vartioitsee minun ovieni pieliä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Sillä joka minut löytää, löytää elämän ja saa Herran mielisuosion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Mutta joka menee minusta harhaan, saa vahingon sielullensa; kaikki, jotka minua vihaavat, rakastavat kuolemaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Viisaus on talonsa rakentanut, veistänyt seitsemän pylvästänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Hän on teuraansa teurastanut, viininsä sekoittanut ja myöskin pöytänsä kattanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'Hän on palvelijattarensa lähettänyt kutsua kuuluttamaan kaupungin kumpujen rinteiltä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '\"Joka yksinkertainen on, poiketkoon tänne\". Sille, joka on mieltä vailla, hän sanoo:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '\"Tulkaa, syökää minun leipääni ja juokaa viiniä, minun sekoittamaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Hyljätkää yksinkertaisuus, niin saatte elää, ja astukaa ymmärryksen tielle.\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Joka pilkkaajaa ojentaa, saa itsellensä häpeän, ja häpeäpilkun se, joka jumalatonta nuhtelee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Älä nuhtele pilkkaajaa, ettei hän sinua vihaisi; nuhtele viisasta, niin hän sinua rakastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Anna viisaalle, niin hän yhä viisastuu; opeta vanhurskasta, niin hän saa oppia lisää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Herran pelko on viisauden alku, ja Pyhimmän tunteminen on ymmärrystä. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, '\"Sillä minun avullani päiväsi enenevät ja jatkuvat elämäsi vuodet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Jos olet viisas, olet omaksi hyväksesi viisas; ja jos olet pilkkaaja, saat sinä sen yksin kestää.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Tyhmyys on nainen, levoton ja yksinkertainen, eikä hän mistään mitään tiedä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'Hän istuu talonsa ovella, istuimella kaupungin kummuilla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'kutsumassa ohikulkijoita, jotka käyvät polkujansa suoraan eteenpäin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '\"Joka yksinkertainen on, poiketkoon tänne\". Ja sille, joka on mieltä vailla, hän sanoo:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '\"Varastettu vesi on makeata, ja salattu leipä on suloista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Eikä toinen tiedä, että haamuja on siellä, että hänen kutsuvieraansa ovat tuonelan laaksoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Salomon sananlaskut. Viisas poika on isällensä iloksi, mutta tyhmä poika on äidillensä murheeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Vääryyden aarteet eivät auta, mutta vanhurskaus vapahtaa kuolemasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Herra ei salli vanhurskaan nälkää nähdä, mutta jumalattomien himon hän luotansa työntää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Köyhtyy, joka laiskasti kättä käyttää, mutta ahkerain käsi rikastuttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Taitava poika kokoaa kesällä, kunnoton poika elonaikana nukkuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Siunaus on vanhurskaan pään päällä, mutta väkivaltaa kätkee jumalattomien suu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Vanhurskaan muistoa siunataan, mutta jumalattomien nimi lahoaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Viisassydäminen ottaa käskyt varteen, mutta hulluhuulinen kukistuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Joka nuhteettomasti vaeltaa, vaeltaa turvassa, jonka tiet ovat väärät, se joutuu ilmi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Joka silmää iskee, saa aikaan tuskaa, ja hulluhuulinen kukistuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Vanhurskaan suu on elämän lähde, mutta jumalattomien suu kätkee väkivaltaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Viha virittää riitoja, mutta rakkaus peittää rikkomukset kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Ymmärtäväisen huulilta löytyy viisaus, mutta joka on mieltä vailla, sille vitsa selkään!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Viisaat kätkevät, minkä tietävät, mutta hullun suu on läheinen turmio.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Rikkaan tavara on hänen vahva kaupunkinsa, mutta vaivaisten köyhyys on heidän turmionsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Vanhurskaan hankkima on elämäksi, jumalattoman saalis koituu synniksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Kuritusta noudattava on elämän tiellä, mutta nuhteet hylkäävä eksyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Joka salavihaa pitää, sen huulilla on valhe, ja joka parjausta levittää, on tyhmä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Missä on paljon sanoja, siinä ei syntiä puutu; mutta joka huulensa hillitsee, se on taitava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Vanhurskaan kieli on valituin hopea, jumalattomien äly on tyhjän veroinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Vanhurskaan huulet kaitsevat monia, mutta hullut kuolevat mielettömyyteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Herran siunaus rikkaaksi tekee, ei oma vaiva siihen mitään lisää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Tyhmälle on iloksi ilkityön teko, mutta ymmärtäväiselle miehelle viisaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Mitä jumalaton pelkää, se häntä kohtaa; mutta mitä vanhurskaat halajavat, se annetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Tuulispään käytyä ei jumalatonta enää ole, mutta vanhurskaan perustus pysyy iäti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Mitä hapan hampaille ja savu silmille, sitä laiska lähettäjillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Herran pelko elinpäiviä jatkaa, mutta jumalattomien vuodet lyhenevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Vanhurskasten odotus koituu iloksi, mutta jumalattomien toivo hukkuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Herran johdatus on nuhteettoman turva, mutta väärintekijäin turmio.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Vanhurskas ei ikinä horju, mutta jumalattomat eivät saa asua maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Vanhurskaan suu kasvaa viisauden hedelmän, mutta kavala kieli hävitetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Vanhurskaan huulet tietävät, mikä otollista on, mutta jumalattomien suu on sulaa kavaluutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Väärä vaaka on Herralle kauhistus, mutta täysi paino on hänelle otollinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Mihin ylpeys tulee, sinne tulee häpeäkin, mutta nöyräin tykönä on viisaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Oikeamielisiä ohjaa heidän nuhteettomuutensa, mutta uskottomat hävittää heidän vilppinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Ei auta tavara vihan päivänä, mutta vanhurskaus vapahtaa kuolemasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Nuhteettoman vanhurskaus tasoittaa hänen tiensä, mutta jumalaton sortuu jumalattomuuteensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Oikeamieliset vapahtaa heidän vanhurskautensa, mutta uskottomat vangitsee heidän oma himonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Jumalattoman ihmisen kuollessa hukkuu hänen toivonsa, ja vääräin odotus hukkuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Vanhurskas pelastetaan hädästä, ja jumalaton joutuu hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Rietas suullansa turmelee lähimmäisensä, mutta taito on vanhurskaitten pelastus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Vanhurskaitten onnesta kaupunki iloitsee, ja jumalattomain hukkumisesta syntyy riemu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Oikeamielisten siunauksesta kaupunki kohoaa, mutta jumalattomain suu sitä hajottaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Mieltä vailla on, joka lähimmäistänsä halveksii, mutta ymmärtäväinen mies on vaiti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Joka panettelijana käy, ilmaisee salaisuuden, mutta jolla luotettava henki on, se säilyttää asian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Missä ohjausta ei ole, sortuu kansa, mutta neuvonantajain runsaus tuo menestyksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Joka vierasta takaa, sen käy pahoin, mutta joka kädenlyöntiä vihaa, se on turvattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Suloinen nainen saa kunniaa, ja voimalliset saavat rikkautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Armelias mies tekee hyvää itsellensä, mutta armoton syöksee onnettomuuteen oman lihansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Jumalaton hankkii pettäväistä voittoa, mutta joka vanhurskautta kylvää, saa pysyvän palkan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Joka on vakaa vanhurskaudessa, saa elämän; mutta joka pahaa tavoittaa, saa kuoleman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Väärämieliset ovat Herralle kauhistus, mutta nuhteettomasti vaeltaviin hän mielistyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Totisesti: paha ei jää rankaisematta, mutta vanhurskasten jälkeläiset pelastuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Kultarengas sian kärsässä on kaunis nainen, älyä vailla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Vanhurskaitten halajaminen vie onneen, jumalattomien toivo vihaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Toinen on antelias ja saa yhä lisää, toinen säästää yli kohtuuden ja vain köyhtyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Hyväätekeväinen sielu tulee ravituksi, ja joka muita virvoittaa, se itse kostuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Joka viljan pitää takanaan, sitä kansa kiroaa, mutta joka viljan kaupaksi antaa, sen pään päälle tulee siunaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Joka hyvään pyrkii, etsii sitä, mikä otollista on, mutta joka pahaa etsii, sille se tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Joka rikkauteensa luottaa, se kukistuu, mutta vanhurskaat viheriöitsevät niinkuin lehvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Joka talonsa rappiolle saattaa, perii tuulta, ja hullu joutuu viisaan orjaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Vanhurskaan hedelmä on elämän puu, ja viisas voittaa sieluja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Katso, vanhurskas saa palkkansa maan päällä, saati sitten jumalaton ja syntinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Tietoa rakastaa, joka kuritusta rakastaa, mutta järjetön se, joka nuhdetta vihaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Hyvä saa Herran mielisuosion, mutta juonittelijan hän tuomitsee syylliseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Ei ihminen kestä jumalattomuuden varassa, mutta vanhurskasten juuri on horjumaton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Kelpo vaimo on puolisonsa kruunu, mutta kunnoton on kuin mätä hänen luissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Vanhurskasten aivoitukset ovat oikeat, jumalattomien hankkeet petolliset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Jumalattomien puheet väijyvät verta, mutta oikeamieliset pelastaa heidän suunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Jumalattomat kukistuvat olemattomiin, mutta vanhurskasten huone pysyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Ymmärryksensä mukaan miestä kiitetään, mutta nurjasydämistä halveksitaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Parempi halpa-arvoinen, jolla on palvelija, kuin rehentelijä, joka on vailla leipää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Vanhurskas tuntee, mitä hänen karjansa kaipaa, mutta jumalattomain sydän on armoton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Joka peltonsa viljelee, saa leipää kyllin, mutta tyhjän tavoittelija on mieltä vailla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Jumalaton himoitsee pahojen saalista, mutta vanhurskasten juuri on antoisa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'Huulten rikkomus on paha ansa, mutta vanhurskas pääsee hädästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Suunsa hedelmästä saa kyllälti hyvää, ja ihmisen eteen kiertyvät hänen kättensä työt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Hullun tie on hänen omissa silmissään oikea, mutta joka neuvoa kuulee, on viisas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Hullun suuttumus tulee kohta ilmi, mutta mielevä peittää kärsimänsä häpeän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Toden puhuja lausuu oikeuden, mutta väärä todistaja petoksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Moni viskoo sanoja kuin miekanpistoja, mutta viisasten kieli on lääke.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Totuuden huulet pysyvät iäti, mutta valheen kieli vain tuokion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Jotka pahaa miettivät, niillä on mielessä petos, mutta jotka rauhaan neuvovat, niille tulee ilo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Ei tule turmiota vanhurskaalle, mutta jumalattomat ovat onnettomuutta täynnä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Herralle kauhistus ovat valheelliset huulet, mutta teoissaan uskolliset ovat hänelle otolliset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Mielevä ihminen peittää tietonsa, mutta tyhmäin sydän huutaa julki hulluutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Ahkerain käsi saa hallita, mutta laiska joutuu työveron alaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Huoli painaa alas miehen mielen, mutta hyvä sana sen ilahuttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Vanhurskas opastaa lähimmäistänsä, mutta jumalattomat eksyttää heidän oma tiensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Laiska ei saa ajetuksi itselleen riistaa, mutta ahkeruus on ihmiselle kallis tavara.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Vanhurskauden polulla on elämä, ja sen tien kulku ei ole kuolemaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Viisas poika kuulee isän kuritusta, mutta pilkkaaja ei ota nuhdetta kuullaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Suunsa hedelmästä saa nauttia hyvää, mutta uskottomilla on halu väkivaltaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Joka suistaa suunsa, se säilyttää henkensä, mutta avosuinen joutuu turmioon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Laiskan sielu haluaa, saamatta mitään, mutta ahkerain sielu tulee ravituksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Vanhurskas vihaa valhepuhetta, mutta jumalattoman meno on iljettävä ja häpeällinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Vanhurskaus varjelee nuhteettomasti vaeltavan, mutta jumalattomuus syöksee syntisen kumoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Toinen on olevinaan rikas, omistamatta mitään, toinen olevinaan köyhä, vaikka on tavaraa paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Rikkautensa saa mies antaa henkensä lunnaiksi, mutta köyhän ei tarvitse uhkauksia kuunnella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Vanhurskasten valo loistaa iloisesti, mutta jumalattomien lamppu sammuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Ylpeys tuottaa pelkkää toraa, mutta jotka ottavat neuvon varteen, niillä on viisaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Tyhjällä saatu tavara vähenee, mutta joka vähin erin kokoaa, se saa karttumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Pitkä odotus tekee sydämen sairaaksi, mutta täyttynyt halu on elämän puu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Joka sanaa halveksii, joutuu sanan pantiksi; mutta joka käskyä pelkää, saa palkan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Viisaan opetus on elämän lähde kuoleman paulain välttämiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Hyvä ymmärrys tuottaa suosiota, mutta uskottomien tie on koleikkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Jokainen mielevä toimii taitavasti, mutta tyhmä levittää hulluutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Jumalaton sanansaattaja suistuu turmioon, mutta uskollinen lähetti on kuin lääke.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Köyhyys ja häpeä kuritusta vierovalle, kunnia nuhdetta noudattavalle!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Tyydytetty halu on sielulle suloinen, pahan karttaminen tyhmille kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Vaella viisasten kanssa, niin viisastut; tyhmäin seuratoverin käy pahoin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Syntisiä vainoaa onnettomuus, mutta vanhurskaat saavat onnen palkakseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Hyvä jättää perinnön lastensa lapsillekin, mutta syntisen tavara talletetaan vanhurskaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Köyhien uudiskyntö antaa runsaan ruuan; mutta moni tuhoutuu, joka ei oikeudessa pysy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Joka vitsaa säästää, se vihaa lastaan; mutta joka häntä rakastaa, se häntä ajoissa kurittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Vanhurskas saa syödä kylläksensä, mutta jumalattomain vatsa jää vajaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Vaimojen viisaus talon rakentaa, mutta hulluus sen omin käsin purkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Joka vaeltaa oikein, se pelkää Herraa, mutta jonka tiet ovat väärät, se hänet katsoo ylen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'Hullun suussa on ylpeydelle vitsa, mutta viisaita vartioivat heidän huulensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Missä raavaita puuttuu, on seimi tyhjä, mutta runsas sato saadaan härkien voimasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Uskollinen todistaja ei valhettele, mutta väärä todistaja puhuu valheita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Pilkkaaja etsii viisautta turhaan, mutta ymmärtäväisen on tietoa helppo saada.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Menet pois tyhmän miehen luota: et tullut tuntemaan tiedon huulia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Mielevän viisaus on, että hän vaelluksestaan vaarin pitää; tyhmien hulluus on petos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Hulluja pilkkaa vikauhri, mutta oikeamielisten kesken on mielisuosio.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Sydän tuntee oman surunsa, eikä sen iloon saa vieras sekaantua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Jumalattomain huone hävitetään, mutta oikeamielisten maja kukoistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Miehen mielestä on oikea monikin tie, joka lopulta on kuoleman tie.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Nauraessakin voi sydän kärsiä, ja ilon lopuksi tulee murhe.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Omista teistään saa kyllänsä se, jolla on luopunut sydän, mutta itsestään löytää tyydytyksen hyvä mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Yksinkertainen uskoo joka sanan, mutta mielevä ottaa askeleistansa vaarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Viisas pelkää ja karttaa pahaa, mutta tyhmä on huoleton ja suruton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Pikavihainen tekee hullun töitä, ja juonittelija joutuu vihatuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Yksinkertaiset saavat perinnökseen hulluuden, mutta mielevät tiedon kruunuksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Pahojen täytyy kumartua hyvien edessä ja jumalattomien seisoa vanhurskaan porteilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Köyhää vihaa hänen ystävänsäkin, mutta rikasta rakastavat monet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Syntiä tekee, joka lähimmäistään halveksii, mutta autuas se, joka kurjia armahtaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Eivätkö eksy ne, jotka hankitsevat pahaa? Mutta armo ja totuus niille, jotka hankitsevat hyvää!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'Kaikesta vaivannäöstä tulee hyötyä, mutta tyhjästä puheesta vain vahinkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Viisasten kruunu on heidän rikkautensa, mutta tyhmäin hulluus hulluudeksi jää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Uskollinen todistaja on hengen pelastaja, mutta joka valheita puhuu, on petosta täynnä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'Herran pelossa on vahva varmuus ja turva vielä lapsillekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Herran pelko on elämän lähde kuoleman paulain välttämiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'Kansan paljous on kuninkaan kunnia, väen vähyys ruhtinaan turmio.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Pitkämielisellä on paljon taitoa, mutta pikavihaisen osa on hulluus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Sävyisä sydän on ruumiin elämä, mutta luulevaisuus on mätä luissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Joka vaivaista sortaa, se herjaa hänen Luojaansa, mutta se häntä kunnioittaa, joka köyhää armahtaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Jumalaton sortuu omaan pahuuteensa, mutta vanhurskas on turvattu kuollessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'Ymmärtäväisen sydämeen ottaa majansa viisaus, ja tyhmien keskellä se itsensä tiettäväksi tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Vanhurskaus kansan korottaa, mutta synti on kansakuntien häpeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Taitava palvelija saa kuninkaan suosion, mutta kunnoton hänen vihansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Leppeä vastaus taltuttaa kiukun, mutta loukkaava sana nostaa vihan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Viisasten kieli puhuu tietoa taitavasti, mutta tyhmäin suu purkaa hulluutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Herran silmät ovat joka paikassa; ne vartioitsevat hyviä ja pahoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Sävyisä kieli on elämän puu, mutta vilpillinen kieli haavoittaa mielen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Hullu pitää halpana isänsä kurituksen, mutta joka nuhdetta noudattaa, tulee mieleväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Vanhurskaan huoneessa on suuret aarteet, mutta jumalattoman saalis on turmion oma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Viisasten huulet kylvävät tietoa, mutta tyhmäin sydän ei ole vakaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Jumalattomien uhri on Herralle kauhistus, mutta oikeamielisten rukous on hänelle otollinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Jumalattoman tie on Herralle kauhistus, mutta joka vanhurskauteen pyrkii, sitä hän rakastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Kova tulee kuritus sille, joka tien hylkää; joka nuhdetta vihaa, saa kuoleman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Tuonelan ja manalan Herra näkee, saati sitten ihmislasten sydämet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Pilkkaaja ei pidä siitä, että häntä nuhdellaan; viisasten luo hän ei mene.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Iloinen sydän kaunistaa kasvot, mutta sydämen tuskassa on mieli murtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Ymmärtäväisen sydän etsii tietoa, mutta tyhmien suu hulluutta suosii.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Kurjalle ovat pahoja kaikki päivät, mutta hyvä mieli on kuin alituiset pidot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Parempi vähä Herran pelossa kuin paljot varat levottomuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Parempi vihannesruoka rakkaudessa kuin syöttöhärkä vihassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Kiukkuinen mies nostaa riidan, mutta pitkämielinen asettaa toran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Laiskan tie on kuin orjantappurapehko, mutta oikeamielisten polku on raivattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Viisas poika on isällensä iloksi, mutta tyhmä ihminen halveksii äitiänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Hulluus on ilo sille, joka on mieltä vailla, mutta ymmärtäväinen mies kulkee suoraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Hankkeet sortuvat, missä neuvonpito puuttuu; mutta ne toteutuvat, missä on runsaasti neuvonantajia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Miehellä on ilo suunsa vastauksesta; ja kuinka hyvä onkaan sana aikanansa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Taitava käy elämän tietä ylöspäin, välttääkseen tuonelan, joka alhaalla on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Ylpeitten huoneen Herra hajottaa, mutta lesken rajan hän vahvistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Häijyt juonet ovat Herralle kauhistus, mutta lempeät sanat ovat puhtaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Väärän voiton pyytäjä hävittää huoneensa, mutta joka lahjuksia vihaa, saa elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Vanhurskaan sydän miettii, mitä vastata, mutta jumalattomien suu purkaa pahuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Jumalattomista on Herra kaukana, mutta vanhurskasten rukouksen hän kuulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Valoisa silmänluonti ilahuttaa sydämen; hyvä sanoma tuo ydintä luihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Korva, joka kuuntelee elämän nuhdetta, saa majailla viisaitten keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Joka kuritusta vieroo, pitää sielunsa halpana; mutta joka nuhdetta kuuntelee, se saa mieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Herran pelko on kuri viisauteen, ja kunnian edellä käy nöyryys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Ihmisen ovat mielen aivoittelut, mutta Herralta tulee kielen vastaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Kaikki miehen tiet ovat hänen omissa silmissään puhtaat, mutta Herra tutkii henget.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Heitä työsi Herran haltuun, niin sinun hankkeesi menestyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Kaiken on Herra tehnyt määrätarkoitukseen, niinpä jumalattomankin onnettomuuden päivän varalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Jokainen ylpeämielinen on Herralle kauhistus: totisesti, ei sellainen jää rankaisematta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Laupeudella ja uskollisuudella rikos sovitetaan, ja Herran pelolla paha vältetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Jos miehen tiet ovat Herralle otolliset, saattaa hän vihamiehetkin sovintoon hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Parempi vähä vanhurskaudessa kuin suuret voitot vääryydessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Ihmisen sydän aivoittelee hänen tiensä, mutta Herra ohjaa hänen askeleensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Kuninkaan huulilla on jumalallinen ratkaisu; hänen suunsa ei petä tuomitessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Puntari ja oikea vaaka ovat Herran, hänen tekoaan ovat kaikki painot kukkarossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Jumalattomuuden teko on kuninkaille kauhistus, sillä vanhurskaudesta valtaistuin vahvistuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Vanhurskaat huulet ovat kuninkaille mieleen, ja oikein puhuvaa he rakastavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Kuninkaan viha on kuoleman sanansaattaja, mutta sen lepyttää viisas mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'Kuninkaan kasvojen valo on elämäksi, ja hänen suosionsa on kuin keväinen sadepilvi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Parempi kultaa on hankkia viisautta, kalliimpi hopeata hankkia ymmärrystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Oikeamielisten tie välttää onnettomuuden; henkensä saa pitää, joka pitää vaelluksestansa vaarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Kopeus käy kukistumisen edellä, ylpeys lankeemuksen edellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Parempi alavana nöyrien parissa kuin jakamassa saalista ylpeitten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Joka painaa mieleensä sanan, se löytää onnen; ja autuas se, joka Herraan turvaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Jolla on viisas sydän, sitä ymmärtäväiseksi sanotaan, ja huulten suloisuus antaa opetukselle tehoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Ymmärrys on omistajalleen elämän lähde, mutta hulluus on hulluille kuritus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Viisaan sydän tekee taitavaksi hänen suunsa ja antaa tehoa hänen huultensa opetukselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Lempeät sanat ovat mesileipää; ne ovat makeat sielulle ja lääkitys luille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Miehen mielestä on oikea monikin tie, joka lopulta on kuoleman tie.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Työmiehen nälkä tekee työtä hänen hyväkseen, sillä oma suu panee hänelle pakon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Kelvoton mies kaivaa toiselle onnettomuutta; hänen huulillaan on kuin polttava tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Kavala mies rakentaa riitaa, ja panettelija erottaa ystävykset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Väkivallan mies viekoittelee lähimmäisensä ja vie hänet tielle, joka ei ole hyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Joka silmiänsä luimistelee, sillä on kavaluus mielessä; joka huulensa yhteen puristaa, sillä on paha valmiina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Harmaat hapset ovat kunnian kruunu; se saadaan vanhurskauden tiellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Pitkämielinen on parempi kuin sankari, ja mielensä hillitseväinen parempi kuin kaupungin valloittaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Helmassa pudistellen arpa heitetään, mutta Herralta tulee aina sen ratkaisu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Parempi kuiva kannikka rauhassa kuin talon täysi uhripaistia riidassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Taitava palvelija hallitsee kunnotonta poikaa ja pääsee perinnönjaolle veljesten rinnalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Hopealle sulatin, kullalle uuni, mutta sydämet koettelee Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Paha kuuntelee häijyjä huulia, petollisuus kuulee pahoja kieliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Joka köyhää pilkkaa, se herjaa hänen luojaansa; joka toisen onnettomuudesta iloitsee, ei jää rankaisematta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Vanhusten kruunu ovat lastenlapset, ja isät ovat lasten kunnia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Ei sovi houkalle ylevä puhe, saati sitten ruhtinaalle valhe.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Lahjus on käyttäjänsä silmissä kallis kivi: mihin vain hän kääntyy, hän menestyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Joka rikkeen peittää, se rakkautta harrastaa; mutta joka asioita kaivelee, se erottaa ystävykset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Nuhde pystyy paremmin ymmärtäväiseen kuin sata lyöntiä tyhmään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Pelkkää onnettomuutta hankkii kapinoitsija, mutta häntä vastaan lähetetään armoton sanansaattaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Kohdatkoon miestä karhu, jolta on riistetty poikaset, mutta älköön tyhmä hulluudessansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Joka hyvän pahalla palkitsee, sen kodista ei onnettomuus väisty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Alottaa tora on päästää vedet valloilleen; herkeä, ennenkuin riita syttyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Syyllisen syyttömäksi ja syyttömän syylliseksi tekijä ovat kumpikin Herralle kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Mitä hyötyä on rahasta tyhmän käsissä? Viisauden hankkimiseen ei ole ymmärrystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Ystävä rakastaa ainiaan ja veli syntyy varaksi hädässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Mieltä vailla on mies, joka kättä lyöpi, joka menee toista takaamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Joka toraa rakastaa, se rikkomusta rakastaa; joka ovensa korottaa, se hankkii kukistumistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Väärämielinen ei onnea löydä, ja kavalakielinen suistuu onnettomuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Tyhmä on murheeksi siittäjällensä, ja houkan isä on iloa vailla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Terveydeksi on iloinen sydän, mutta murtunut mieli kuivuttaa luut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Jumalaton ottaa lahjuksen vastaan toisen povelta vääristääksensä oikeuden tiet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Ymmärtäväisellä on viisaus kasvojensa edessä, mutta tyhmän silmät kiertävät maailman rantaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Tyhmä poika on isällensä suruksi ja synnyttäjällensä mielihaikeaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Paha jo sekin, jos syytöntä sakotetaan; kovin kohtuutonta, jos jaloja lyödään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Joka hillitsee sanansa, on taitava, ja mielensä malttava on ymmärtäväinen mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Hullukin käy viisaasta, jos vaiti on; joka huulensa sulkee, on ymmärtäväinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Eriseurainen noudattaa omia pyyteitään; kaikin neuvoin hän riitaa haastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Tyhmän halu ei ole ymmärrykseen, vaan tuomaan julki oma mielensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Kunne jumalaton tulee, tulee ylenkatsekin, ja häpeällisen menon mukana häväistys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Syviä vesiä ovat sanat miehen suusta, ovat virtaava puro ja viisauden lähde.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Ei ole hyvä pitää syyllisen puolta ja vääräksi vääntää syyttömän asiaa oikeudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Tyhmän huulet tuovat mukanaan riidan, ja hänen suunsa kutsuu lyöntejä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Oma suu on tyhmälle turmioksi ja omat huulet ansaksi hänelle itselleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Panettelijan puheet ovat kuin herkkupalat ja painuvat sisusten kammioihin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Joka on veltto toimessansa, se on jo tuhontekijän veli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Herran nimi on vahva torni; hurskas juoksee sinne ja saa turvan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Rikkaan tavara on hänen vahva kaupunkinsa, ja korkean muurin kaltainen hänen kuvitteluissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Kukistumisen edellä miehen sydän ylpistyy, mutta kunnian edellä käy nöyryys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Jos kuka vastaa, ennenkuin on kuullut, on se hulluutta ja koituu hänelle häpeäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Miehekäs mieli pitää sairaankin pystyssä, mutta kuka voi kantaa murtunutta mieltä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Tietoa hankkii ymmärtäväisen sydän, tietoa etsii viisasten korva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Lahja avartaa alat ihmiselle ja vie hänet isoisten pariin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Käräjissä on kukin ensiksi oikeassa, mutta sitten tulee hänen riitapuolensa ja ottaa hänestä selvän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Arpa riidat asettaa ja ratkaisee väkevien välit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Petetty veli on vaikeampi voittaa kuin vahva kaupunki, ja riidat ovat kuin linnan salvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Suunsa hedelmästä saa mies vatsansa kylläiseksi, saa kyllikseen huultensa satoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Kielellä on vallassansa kuolema ja elämä; jotka sitä rakastavat, saavat syödä sen hedelmää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Joka vaimon löysi, se onnen löysi, sai Herralta mielisuosion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Köyhä puhuu pyydellen, mutta rikas vastaa tylysti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Häviökseen mies on monien ystävä, mutta on myös ystäviä, veljiäkin uskollisempia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Parempi on köyhä, joka nuhteettomasti vaeltaa, kuin huuliltansa nurja, joka on vielä tyhmäkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Ilman taitoa ei ole intokaan hyväksi, ja kiirehtivän jalka astuu harhaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Ihmisen oma hulluus turmelee hänen tiensä, mutta Herralle hän sydämessään vihoittelee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Tavara tuo ystäviä paljon, mutta vaivainen joutuu ystävästänsä eroon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Väärä todistaja ei jää rankaisematta, ja joka valheita puhuu, se ei pelastu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Monet etsivät ylhäisen suosiota, ja kaikki ovat anteliaan ystäviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Köyhä on kaikkien veljiensä vihattu, vielä vierotumpi ystävilleen. Tyhjiä sanoja hän saa tavoitella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Joka mieltä hankkii, se sieluansa rakastaa; joka ymmärryksen säilyttää, se onnen löytää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Väärä todistaja ei jää rankaisematta, ja joka valheita puhuu, se hukkuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Ei sovi tyhmälle hyvät päivät, saati sitten palvelijalle hallita ruhtinaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Ymmärrys tekee ihmisen pitkämieliseksi, ja hänen kunniansa on antaa rikos anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Kuninkaan viha on kuin nuoren leijonan kiljunta, mutta hänen suosionsa on kuin kaste ruoholle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Tyhmä poika on isänsä turmio, ja vaimon tora on kuin räystäästä tippuva vesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Talo ja tavara peritään isiltä, mutta toimellinen vaimo tulee Herralta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Laiskuus vaivuttaa sikeään uneen, ja veltto joutuu näkemään nälkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Joka käskyt pitää, saa henkensä pitää; joka ei teistänsä välitä, on kuoleman oma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Joka vaivaista armahtaa, se lainaa Herralle, ja hän maksaa jälleen hänen hyvän tekonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Kurita poikaasi, kun vielä toivoa on; ethän halunne hänen kuolemaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Rajuluontoinen joutuu sakkoihin: vain yllytät, jos yrität apuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Kuule neuvoa, ota kuritus varteen, että olisit vasta viisaampi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Monet ovat miehen mielessä aivoitukset, mutta Herran neuvo on pysyväinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Ihaninta ihmisessä on hänen laupeutensa, ja köyhä on parempi kuin valhettelija.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Herran pelko on elämäksi: saa levätä yönsä ravittuna, eikä mikään paha kohtaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Laiska pistää kätensä vatiin, mutta ei saa sitä viedyksi suuhunsa jälleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Lyö pilkkaajaa, niin yksinkertainen saa mieltä, ja jos ymmärtäväistä nuhdellaan, niin hän käsittää tiedon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Joka isäänsä pahoin pitelee ja ajaa äitinsä pois, se on kunnoton ja rietas poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Jos herkeät, poikani, kuulemasta kuritusta, niin eksyt pois tiedon sanoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Kelvoton todistaja pitää oikeuden pilkkanaan, ja jumalattomien suu nielee vääryyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Tuomiot ovat valmiina pilkkaajille ja lyönnit tyhmien selkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Viini on pilkkaaja, väkijuoma remunpitäjä; eikä ole viisas kenkään, joka siitä hoipertelee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Kuninkaan peljättäväisyys on kuin nuoren leijonan kiljunta; joka hänet vihoittaa, se henkensä rikkoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'On kunniaksi miehelle riitaa karttaa, mutta kaikki hullut riitaa haastavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Syksyllä ei laiska kynnä; elonaikana hän tyhjää tapailee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Kuin syvät vedet ovat miehen sydämen aivoitukset, mutta ymmärtäväinen mies ne ammentaa esiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Monet huutavat hyvyyttänsä kukin, mutta kuka löytää luotettavan miehen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Vanhurskas vaeltaa nuhteettomasti, onnelliset ovat lapset hänen jälkeensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Kuningas istuu tuomioistuimella, hän silmillänsä perkaa kaiken pahan pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Kuka voi sanoa: \"Olen puhdistanut sydämeni, olen puhdas synnistäni\"?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Kahtalainen paino ja kahtalainen mitta-molemmat ovat Herralle kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Teoistansa tuntee jo poikasenkin, onko hänen menonsa puhdas ja oikea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Kuulevan korvan ja näkevän silmän-molemmat on Herra luonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Älä unta rakasta, ettet köyhtyisi; pidä silmäsi auki, niin saat leipää kyllin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, '\"Huonoa, huonoa\", sanoo ostaja, mutta mentyänsä pois hän kehuskelee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Olkoon kultaa, olkoon helmiä paljon, kallein kalu ovat taidolliset huulet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Ota siltä vaatteet, joka toista takasi, ja ota häneltä pantti vieraitten puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Makea on miehelle petoksella saatu leipä, mutta perästäpäin hän saa suunsa täyteen soraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Neuvotellen suunnitelmat vahvistuvat, ja sotaa on sinun käytävä neuvokkuudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Salaisuuden ilmaisee, joka panettelijana käy; älä siis antaudu avosuisen pariin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Joka isäänsä ja äitiänsä kiroaa, sen lamppu sammuu pilkkopimeään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Tavara, jota aluksi kiivaasti tavoitellaan, ei lopulta tuo siunausta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Älä sano: \"Minä kostan pahan\"; odota Herraa, hän auttaa sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Kahtalainen paino on Herralle kauhistus, ja väärä vaaka ei ole hyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Herralta tulevat miehen askeleet; mitäpä ymmärtäisi tiestänsä ihminen itse?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Ihmiselle on ansaksi luvata hätiköiden pyhä lahja ja vasta perästäpäin harkita lupauksiansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Viisas kuningas perkaa jumalattomat pois viskimellään ja antaa puimajyrän käydä heidän ylitsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Ihmisen henki on Herran lamppu: se tutkistelee sydämen kammiot kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Laupeus ja uskollisuus on kuninkaan turva, ja laupeudella hän valtaistuimensa tukee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Voima on nuorukaisen kunnia, ja harmaat hapset ovat vanhusten kaunistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Mustelmat ja haavat puhdistavat pahantekijän, lyönnit puhdistavat sydämen kammiot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Kuninkaan sydän on Herran kädessä kuin vesiojat: hän taivuttaa sen, kunne tahtoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Kaikki miehen tiet ovat hänen omissa silmissään oikeat, mutta Herra tutkii sydämet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Vanhurskauden ja oikeuden harjoittaminen on Herralle otollisempi kuin uhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Ylpeät silmät ja pöyhkeä sydän-jumalattomien lamppu-ovat syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Vain hyödyksi ovat ahkeran ajatukset, mutta kaikki touhuilijat saavat vain vahinkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Jotka hankkivat aarteita petollisin kielin, ovat haihtuva tuulahdus, hakevat kuolemaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Jumalattomat tempaa pois heidän väkivaltansa, sillä eivät he tahdo oikeutta tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Rikollisen tie on mutkainen, mutta puhtaan teot ovat oikeat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Parempi asua katon kulmalla kuin toraisan vaimon huonetoverina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Jumalattoman sielu himoitsee pahaa, lähimmäinen ei saa armoa hänen silmiensä edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Kun pilkkaajaa rangaistaan, viisastuu yksinkertainen; ja kun viisasta neuvotaan, ottaa hän sen opiksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Vanhurskas Jumala tarkkaa jumalattoman taloa, hän syöksee jumalattomat onnettomuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Joka tukkii korvansa vaivaisen huudolta, se joutuu itse huutamaan, vastausta saamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Salainen lahja lepyttää vihan ja poveen kätketty lahjus kiivaan kiukun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Vanhurskaalle on ilo, kun oikeutta tehdään, mutta väärintekijöille kauhu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Ihminen, joka eksyy taidon tieltä, joutuu lepäämään haamujen seuraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Puutteen mieheksi päätyy riemujen rakastaja, eikä rikastu se, joka viiniä ja öljyä rakastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Jumalaton joutuu lunastusmaksuksi vanhurskaan puolesta ja uskoton oikeamielisten sijaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Parempi asua autiossa maassa kuin toraisan vaimon vaivattavana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Kalliita aarteita ja öljyä on viisaan majassa, mutta tyhmä ihminen syö suuhunsa sellaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Joka vanhurskauteen ja laupeuteen pyrkii, se löytää elämän, vanhurskauden ja kunnian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Viisas ryntää sankarien kaupunkiin ja kukistaa varustuksen, joka oli sen turva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Joka suunsa ja kielensä varoo, se henkensä ahdistuksilta varoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Pilkkaajan nimen saa julkea röyhkeilijä, jonka meno on määrätöntä julkeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Oma halu laiskan tappaa, sillä hänen kätensä eivät tahdo työtä tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Aina on hartaasti haluavia, mutta vanhurskas antaa säästelemättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Jumalattomien uhri on kauhistus; saati sitten, jos se tuodaan ilkityön edestä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Valheellinen todistaja hukkuu, mutta kuunteleva mies saa aina puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Julkeiksi tekee jumalaton kasvonsa, vakaiksi tekee oikeamielinen tiensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Ei auta viisaus, ei ymmärrys, ei mikään neuvo Herraa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Hevonen on varustettu taistelun päiväksi, mutta voitto on Herran hallussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Nimi on kalliimpi suurta rikkautta, suosio hopeata ja kultaa parempi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Rikas ja köyhä kohtaavat toisensa; Herra on luonut kumpaisenkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Mielevä näkee vaaran ja kätkeytyy, mutta yksinkertaiset käyvät kohti ja saavat vahingon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Nöyryyden ja Herran pelon palkka on rikkaus, kunnia ja elämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Orjantappuroita ja pauloja on väärän tiellä; henkensä varjelee, joka niistä kaukana pysyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Totuta poikanen tiensä suuntaan, niin hän ei vanhanakaan siitä poikkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Rikas hallitsee köyhiä, ja velallinen joutuu velkojan orjaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Joka vääryyttä kylvää, se turmiota niittää, ja hänen vihansa vitsa häviää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Hyvänsuopa saa siunauksen, sillä hän antaa leivästään vaivaiselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Aja pois pilkkaaja, niin poistuu tora ja loppuu riita ja häväistys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Joka sydämen puhtautta rakastaa, jolla on suloiset huulet, sen ystävä on kuningas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Herran silmät suojelevat taitoa, mutta uskottoman sanat hän kääntää väärään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Laiska sanoo: \"Ulkona on leijona; tappavat vielä minut keskellä toria\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Irstaitten vaimojen suu on syvä kuoppa; Herran vihan alainen kaatuu siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Hulluus on kiertynyt kiinni poikasen sydämeen, mutta kurituksen vitsa sen hänestä kauas karkoittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Vaivaiselle on voitoksi, jos häntä sorretaan, rikkaalle tappioksi, jos hänelle annetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Kallista korvasi ja kuuntele viisaitten sanoja ja tarkkaa minun taitoani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Sillä suloista on, jos kätket ne sisimpääsi; olkoot ne kaikki huulillasi valmiina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Että Herra olisi sinun turvanasi, siksi olen minä nyt neuvonut juuri sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Olenhan ennenkin sinulle kirjoittanut, antanut neuvoja ja tietoa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'opettaakseni sinulle totuutta, vakaita sanoja, että voisit vakain sanoin vastata lähettäjällesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Älä raasta vaivaista, siksi että hän on vaivainen, äläkä polje kurjaa portissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'sillä Herra ajaa hänen asiansa ja riistää hänen riistäjiltään hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Älä rupea pikavihaisen ystäväksi äläkä seurustele kiukkuisen kanssa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'että et tottuisi hänen teihinsä ja saattaisi sieluasi ansaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Älä ole niitä, jotka kättä lyövät, jotka menevät takuuseen veloista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Jollei sinulla ole, millä maksaa, mitäs muuta, kuin viedään vuode altasi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Älä siirrä ikivanhaa rajaa, jonka esi-isäsi ovat asettaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Jos näet miehen, kerkeän toimissaan, hänen paikkansa on kuningasten, ei alhaisten, palveluksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Kun istut aterialle hallitsijan seurassa, niin pidä tarkoin mielessä, kuka edessäsi on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'ja pane veitsi kurkullesi, jos olet kovin nälkäinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Älä himoitse hänen herkkujansa, sillä ne ovat petollisia ruokia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Älä näe vaivaa rikastuaksesi, lakkaa käyttämästä ymmärrystäsi siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Kun silmäsi siihen lentävät, on rikkaus mennyttä; sillä se saa siivet kuin kotka, joka lentää taivaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Älä syö pahansuovan leipää äläkä himoitse hänen herkkujansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Sillä niinkuin hän mielessään laskee, niin hän menettelee: hän sanoo sinulle: \"Syö ja juo\", mutta hänen sydämensä ei ole sinun puolellasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Syömäsi palan sinä olet oksentava, ja suloiset sanasi sinä tuhlasit turhaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Älä puhu tyhmän kuullen, sillä hän katsoo ymmärtäväiset sanasi ylen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Älä siirrä ikivanhaa rajaa äläkä mene orpojen pelloille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Sillä heidän sukulunastajansa on väkevä, ja hän ajaa heidän asiansa sinua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Tuo sydämesi kuritettavaksi ja korvasi taidon sanojen ääreen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Älä kiellä poikaselta kuritusta, sillä jos lyöt häntä vitsalla, säästyy hän kuolemasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Vitsalla sinä häntä lyöt, tuonelasta hänen sielunsa pelastat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Poikani, jos sinun sydämesi viisastuu, niin minunkin sydämeni iloitsee;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'ja sisimpäni riemuitsee, jos sinun huulesi puhuvat sitä, mikä oikein on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Älköön sydämesi kadehtiko jumalattomia, mutta kiivaile aina Jumalan pelon puolesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'niin sinulla totisesti on tulevaisuus, ja toivosi ei mene turhaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Kuule, poikani, ja viisastu, ja ohjaa sydämesi oikealle tielle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Älä oleskele viininjuomarien parissa äläkä lihansyömärien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Sillä juomari ja syömäri köyhtyy, ja unteluus puettaa ryysyihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Kuule isääsi, joka on sinut siittänyt, äläkä äitiäsi halveksi, kun hän on vanhennut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Osta totuutta, älä myy, osta viisautta, kuria ja ymmärrystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'neen saa riemuita vanhurskaan isä; joka viisaan on siittänyt, sillä on ilo hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Olkoon sinun isälläsi ja äidilläsi ilo, sinun synnyttäjäsi riemuitkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Anna sydämesi, poikani, minulle, ja olkoot minun tieni sinun silmissäsi mieluiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Sillä portto on syvä kuoppa, ja vieras vaimo on ahdas kaivo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Vieläpä hän väijyy kuin rosvo, ja hän kartuttaa uskottomia ihmisten seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Kenellä on voivotus, kenellä vaikerrus? Kenellä torat, kenellä valitus? Kenellä haavat ilman syytä? Kenellä sameat silmät?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Niillä, jotka viinin ääressä viipyvät, jotka tulevat makujuomaa maistelemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Älä katsele viiniä, kuinka se punoittaa, kuinka se maljassa hohtaa ja helposti valahtaa alas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Lopulta se puree kuin käärme ja pistää kuin myrkkylisko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Silmäsi outoja näkevät, ja sydämesi haastelee sekavia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'Sinusta on kuin makaisit keskellä merta, on kuin maston huipussa makaisit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, '\"Löivät minua, mutta ei koskenut minuun; pieksivät minua, mutta en tiennyt mitään. Milloinkahan herännen? Tahdonpa taas hakea tätä samaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Älä kadehdi pahoja ihmisiä äläkä halua heidän seuraansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Sillä heidän mielensä miettii väkivaltaa, ja turmiota haastavat heidän huulensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Viisaudella talo rakennetaan ja ymmärryksellä vahvaksi varustetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Taidolla täytetään kammiot, kaikkea kallista ja ihanaa tavaraa täyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Viisas mies on väkevä, ja taidon mies on voipa voimaltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Neuvokkuudella näet on sinun käytävä sotaa, ja neuvonantajain runsaus tuo menestyksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Kovin on korkea hullulle viisaus, ei hän suutansa avaa portissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Jolla on pahanteko mielessä, sitä juonittelijaksi sanotaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Synti on hulluuden työ, ja pilkkaaja on ihmisille kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Jos olet ollut veltto, joutuu ahtaana aikana voimasi ahtaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Pelasta ne, joita kuolemaan viedään, pysäytä ne, jotka surmapaikalle hoippuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Jos sanot: \"Katso, emme tienneet siitä\", niin ymmärtäähän asian sydänten tutkija; sinun sielusi vartioitsija sen tietää, ja hän kostaa ihmiselle hänen tekojensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Syö hunajaa, poikani, sillä se on hyvää, ja mesi on makeaa suussasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Samankaltaiseksi tunne viisaus sielullesi; jos sen löydät, on sinulla tulevaisuus, ja toivosi ei mene turhaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Älä väijy, jumalaton, vanhurskaan majaa, älä hävitä hänen leposijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Sillä seitsemästi vanhurskas lankeaa ja nousee jälleen, mutta jumalattomat suistuvat onnettomuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Älä iloitse vihamiehesi langetessa, älköön sydämesi riemuitko hänen suistuessaan kumoon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'ettei Herra, kun sen näkee, sitä pahana pitäisi, ja kääntäisi vihaansa pois hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Älä vihastu pahantekijäin tähden, älä kadehdi jumalattomia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Sillä ei ole pahalla tulevaisuutta; jumalattomien lamppu sammuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Pelkää, poikani, Herraa ja kuningasta, älä sekaannu kapinallisten seuraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Sillä yhtäkkiä tulee heille onnettomuus, tuomio-kuka tietää milloin-toisille niinkuin toisillekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Nämäkin ovat viisaitten sanoja. Ei ole hyvä tuomitessa henkilöön katsoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Joka sanoo syylliselle: \"Sinä olet syytön\", sitä kansat kiroavat, kansakunnat sadattelevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Mutta jotka oikein tuomitsevat, niiden käy hyvin, ja heille tulee onnen siunaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Se huulille suutelee, joka oikean vastauksen antaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Toimita tehtäväsi ulkona ja tee valmista pellollasi; sitten perusta itsellesi perhe.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Älä ole syyttä todistajana lähimmäistäsi vastaan, vai petätkö sinä huulillasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Älä sano: \"Niinkuin hän teki minulle, niin teen minä hänelle, minä kostan miehelle hänen tekojensa mukaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Minä kuljin laiskurin pellon ohitse, mielettömän miehen viinitarhan vieritse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'Ja katso: se kasvoi yltänsä polttiaisia; sen pinta oli nokkosten peitossa ja sen kiviaita luhistunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Minä katselin ja painoin mieleeni, havaitsin ja otin opikseni:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Nuku vielä vähän, torku vähän, makaa vähän ristissä käsin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'niin köyhyys käy päällesi niinkuin rosvo ja puute niinkuin asestettu mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Nämäkin ovat Salomon sananlaskuja, Hiskian, Juudan kuninkaan, miesten kokoamia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Jumalan kunnia on salata asia, ja kuningasten kunnia on tutkia asia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Taivaan korkeus ja maan syvyys ja kuningasten sydän on tutkimaton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Kun hopeasta poistetaan kuona, kuontuu kultasepältä astia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Kun jumalaton poistetaan kuninkaan luota, vahvistuu hänen valtaistuimensa vanhurskaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Älä tavoittele kunniaa kuninkaan edessä äläkä asetu isoisten sijalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Sillä parempi on, jos sinulle sanotaan: \"Käy tänne ylös\", kuin että sinut alennetaan ylhäisen edessä, jonka silmäsi olivat nähneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Älä ole kärkäs käräjöimään; muutoin sinulla ei lopulta ole, mitä tehdä, kun vastapuolesi on saattanut sinut häpeään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Riitele oma riitasi vastapuolesi kanssa, mutta toisen salaisuutta älä ilmaise.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'Muutoin sinua häpäisee, kuka sen kuuleekin, eikä huono huuto sinusta lakkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Kultaomenia hopeamaljoissa ovat sanat, sanotut aikanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Kultainen korvarengas ja hienokultainen kaulakoru ovat viisas neuvoja ynnä kuuleva korva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Kuin lumen viileys elonaikana on luotettava lähetti lähettäjälleen: herransa sielun hän virvoittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Kuin pilvet ja tuuli, jotka eivät sadetta tuo, on mies, joka kerskuu lahjoilla, joita ei anna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Kärsivällisyydellä taivutetaan ruhtinas, ja leppeä kieli murskaa luut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Jos hunajata löydät, syö kohtuudella, ettet kyllästyisi siihen ja sitä oksentaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Astu jalallasi harvoin lähimmäisesi kotiin, ettei hän sinuun kyllästyisi ja alkaisi sinua vihata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Nuija ja miekka ja terävä nuoli on mies, joka väärin todistaa lähimmäistänsä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Kuin mureneva hammas ja horjuva jalka on uskottoman turva ahdingon päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Kuin se, joka riisuu vaatteet pakkaspäivänä, kuin etikka lipeän sekaan, on se, joka laulaa lauluja murheelliselle sydämelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Jos vihamiehelläsi on nälkä, anna hänelle leipää syödä, ja jos hänellä on jano, anna hänelle vettä juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Sillä niin sinä kokoat tulisia hiiliä hänen päänsä päälle, ja Herra sen sinulle palkitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Pohjatuuli saa aikaan sateen ja salainen kielittely vihaiset kasvot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Parempi on asua katon kulmalla kuin toraisan vaimon huonetoverina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Kuin nääntyväiselle raikas vesi on hyvä sanoma kaukaisesta maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Kuin sekoitettu lähde ja turmeltu kaivo on vanhurskas, joka horjuu jumalattoman edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Liika hunajan syönti ei ole hyväksi, ja raskaitten asiain tutkiminen on raskasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Kuin kaupunki, varustukset hajalla, muuria vailla, on mies, joka ei mieltänsä hillitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Yhtä vähän kuin lumi kesällä ja sade elonaikana soveltuu tyhmälle kunnia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Kuin liitävä lintu, kuin lentävä pääskynen on aiheeton kirous: ei se toteen käy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Hevoselle ruoska, aasille suitset, tyhmille vitsa selkään!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Älä vastaa tyhmälle hänen hulluutensa mukaan, ettet olisi hänen kaltaisensa sinäkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Vastaa tyhmälle hänen hulluutensa mukaan, ettei hän itseänsä viisaana pitäisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Jalat altaan katkaisee ja vääryyttä saa juoda, joka sanan lähettää tyhmän mukana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Velttoina riippuvat halvatun sääret; samoin sananlasku tyhmäin suussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Yhtä kuin sitoisi kiven linkoon kiinni, on antaa kunniaa tyhmälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Kuin ohdake, joka on osunut juopuneen käteen, on sananlasku tyhmäin suussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Kuin jousimies, joka kaikkia haavoittaa, on se, joka tyhmän pestaa, kulkureita pestaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Kuin koira, joka palajaa oksennuksilleen, on tyhmä, joka yhä uusii hulluuksiansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Näet miehen, viisaan omissa silmissään-enemmän on toivoa tyhmästä kuin hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Laiska sanoo: \"Tuolla tiellä on leijona, jalopeura torien vaiheilla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Ovi saranoillaan kääntyilee, laiska vuoteellansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Laiska pistää kätensä vatiin; ei viitsi sitä viedä suuhunsa jälleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Laiska on omissa silmissään viisaampi kuin seitsemän, jotka vastaavat taitavasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Kulkukoiraa korviin tarttuu se, joka syrjäisten riidasta suuttuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Kuin mieletön, joka ammuskelee tulisia surmannuolia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'on mies, joka pettää lähimmäisensä ja sanoo: \"Leikillähän minä sen tein\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Halkojen loppuessa sammuu tuli, ja panettelijan poistuessa taukoaa tora.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Hehkuksi hiilet, tuleksi halot, riidan lietsomiseksi toraisa mies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Panettelijan puheet ovat kuin herkkupalat ja painuvat sisusten kammioihin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Kuin hopeasilaus saviastian pinnalla ovat hehkuvat huulet ja paha sydän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Vihamies teeskentelee huulillaan, mutta hautoo petosta sydämessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Jos hän muuttaa suloiseksi äänensä, älä häntä usko, sillä seitsemän kauhistusta hänellä on sydämessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Vihamielisyys kätkeytyy kavalasti, mutta seurakunnan kokouksessa sen pahuus paljastuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Joka kuopan kaivaa, se itse siihen lankeaa; ja joka kiveä vierittää, sen päälle se takaisin vyörähtää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Valheellinen kieli vihaa omia ruhjomiansa, ja liukas suu saa turmiota aikaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Älä huomispäivästä kersku, sillä et tiedä, mitä mikin päivä synnyttää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Kehukoon sinua toinen, ei oma suusi; vieras, eikä omat huulesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Raskas on kivi ja painava hiekka, mutta molempia raskaampi hullun suuttumus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Kiukku on julma, viha on niinkuin tulva; mutta kuka voi kestää luulevaisuutta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Parempi julkinen nuhde kuin salattu rakkaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Ystävän lyönnit ovat luotettavat, mutta vihamiehen suutelot ylenpalttiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Kylläinen polkee hunajaakin, nälkäiselle on kaikki karvaskin makeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Kuin pesästään paennut lintu, on mies paossa kotipaikoiltaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Öljy ja suitsuke ilahuttavat sydämen; samoin ystävän hellyys, alttiisti neuvoja antavainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Ystävääsi ja isäsi ystävää älä hylkää, äläkä hätäpäivänäsi mene veljesi taloon: parempi läheinen naapuri kuin kaukainen veli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Viisastu, poikani, ja ilahuta minun sydämeni, niin minä voin antaa herjaajalleni vastauksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Mielevä näkee vaaran ja kätkeytyy, mutta yksinkertaiset käyvät kohti ja saavat vahingon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Ota siltä vaatteet, joka toista takasi, ja ota häneltä pantti vieraan naisen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Joka siunaa ystäväänsä isoäänisesti aamulla varhain, sille se luetaan kiroukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Räystäästä tippuva vesi sadepäivänä ja toraisa vaimo ovat yhdenveroiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Joka tahtoo hänet salassa pitää, se tuulta salassa pitää, se tavoittaa öljyä oikeaan käteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Rauta rautaa hioo, ja ihminen toistansa hioo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Joka viikunapuuta hoitaa, saa syödä sen hedelmää; ja joka isännästänsä vaarin pitää, se tulee kunniaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Niinkuin kasvot kuvastuvat vedessä, niin ihmisen sydän toisessa ihmisessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Tuonela ja horna eivät kylläänsä saa; eivät myös saa kylläänsä ihmisen silmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Hopealle sulatin, kullalle uuni; mies maineensa mukainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Survo hullua huhmaressa, petkelellä surveitten seassa: ei erkane hänestä hänen hulluutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Tiedä tarkoin, miltä pikkukarjasi näyttää; pidä huoli laumoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Sillä eivät aarteet säily iäti; ja pysyykö kruunukaan polvesta polveen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Kun heinä on mennyt ja tuore äpäre tulee näkyviin ja ruoho on koottu vuorilta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'on sinulla karitsoita puvuksesi ja vuohipukkeja pellon ostohinnaksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'ja vuohenmaitoa kyllin ravinnoksesi, perheesi ravinnoksi ja palvelijatartesi elatukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Jumalattomat pakenevat, vaikka ei kenkään aja takaa, mutta vanhurskaat ovat turvassa kuin nuori jalopeura.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Rikkomisensa tähden maa saa ruhtinaita paljon, mutta yhden ymmärtäväisen miehen taidolla järjestys kauan pysyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Köyhä mies, joka vaivaisia sortaa, on kuin sade, joka lyö lakoon eikä anna leipää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Lain hylkijät kehuvat jumalattomia, mutta lain noudattajat kauhistuvat heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Pahat ihmiset eivät ymmärrä, mikä oikein on, mutta Herraa etsiväiset ymmärtävät kaiken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Parempi on köyhä, joka nuhteettomasti vaeltaa, kuin kahdella tiellä mutkitteleva rikas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Joka laista ottaa vaarin, on ymmärtäväinen poika; mutta irstailijain seuratoveri saattaa isänsä häpeään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Joka kartuttaa varojaan korolla ja voitolla, kokoaa niitä sille, joka vaivaisia armahtaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Joka korvansa kääntää kuulemasta lakia, sen rukouskin on kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Joka eksyttää oikeamielisiä pahalle tielle, se lankeaa omaan kuoppaansa; mutta nuhteettomat perivät onnen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Rikas mies on omissa silmissään viisas, mutta ymmärtäväinen köyhä ottaa hänestä selvän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Kun vanhurskaat riemuitsevat, on ihanuus suuri; mutta kun jumalattomat nousevat, saa ihmisiä hakea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Joka rikkomuksensa salaa, se ei menesty; mutta joka ne tunnustaa ja hylkää, se saa armon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Onnellinen se ihminen, joka aina on aralla tunnolla; mutta joka sydämensä paaduttaa, se onnettomuuteen lankeaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Kuin muriseva leijona ja ahnas karhu on kurjan kansan jumalaton hallitsija.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Vähätaitoinen ruhtinas runsaasti kiskoo, mutta väärän voiton vihaaja saa elää kauan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Ihmisen, jota verivelka painaa, on pakoiltava hamaan hautaan asti; älköön häntä suojeltako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Nuhteettomasti vaeltavainen saa avun, mutta kahdella tiellä mutkittelija kerralla kaatuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Joka peltonsa viljelee, saa leipää kyllin, mutta tyhjän tavoittelija saa köyhyyttä kyllin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Luotettava mies saa runsaan siunauksen, mutta jolla on kiihko rikastua, se ei rankaisematta jää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Ei ole hyvä henkilöön katsoa, mutta leipäpalankin tähden rikkomus tehdään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Pahansuova haluaa kiihkeästi varallisuutta eikä tiedä, että hänet tapaa puute.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Joka toista nuhtelee, niinkuin minä neuvon, saa suosiota enemmän kuin se, joka kielellänsä liehakoitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Joka isältään ja äidiltään riistää ja sanoo: \"Ei tämä ole rikos\", se on tuhontekijän toveri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Tavaranahne nostaa riidan, mutta Herraan luottavainen tulee ravituksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Omaan sydämeensä luottavainen on tyhmä, mutta viisaudessa vaeltava pelastuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Joka köyhälle antaa, se ei puutteeseen joudu; mutta joka silmänsä häneltä sulkee, saa kirouksia paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Kun jumalattomat nousevat, piileksivät ihmiset; mutta kun he hukkuvat, niin hurskaat enentyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Kuritusta saanut mies, joka niskurina pysyy, rusennetaan äkisti, eikä apua ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Hurskaitten enentyessä kansa iloitsee, mutta jumalattoman hallitessa kansa huokaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Viisautta rakastavainen on isällensä iloksi, mutta porttojen seuratoveri hävittää varansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Oikeudella kuningas pitää maan pystyssä, mutta verojen kiskoja sen hävittää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Mies, joka lähimmäistään liehakoitsee, virittää verkon hänen askeleilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Pahalle miehelle on oma rikos paulaksi, mutta vanhurskas saa riemuita ja iloita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Vanhurskas tuntee vaivaisten asian, mutta jumalaton ei siitä mitään ymmärrä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Pilkkaajat kaupungin villitsevät, mutta viisaat hillitsevät vihan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Viisas mies kun käräjöi hullun miehen kanssa, niin tämä reutoo ja nauraa eikä asetu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Murhamiehet vihaavat nuhteetonta, oikeamielisten henkeä he väijyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Tyhmä purkaa kaiken sisunsa, mutta viisas sen viimein tyynnyttää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Hallitsija, joka kuuntelee valhepuheita, saa palvelijoikseen pelkkiä jumalattomia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Köyhä ja sortaja kohtaavat toisensa; kumpaisenkin silmille Herra antaa valon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Kuninkaalla, joka tuomitsee vaivaisia oikein, on valtaistuin iäti vahva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Vitsa ja nuhde antavat viisautta, mutta kuriton poika on äitinsä häpeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Kun jumalattomat lisääntyvät, lisääntyy rikos, mutta vanhurskaat saavat nähdä, kuinka he kukistuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Kurita poikaasi, niin hän sinua virvoittaa ja sielullesi herkkuja tarjoaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Missä ilmoitus puuttuu, siinä kansa käy kurittomaksi; autuas se, joka noudattaa lakia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Ei ota palvelija sanoista ojentuakseen: hän kyllä ymmärtää, mutta ei tottele.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Näet miehen, kärkkään puhumaan-enemmän on toivoa tyhmästä kuin hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Jos palvelijaansa nuoresta pitäen hemmottelee, tulee hänestä lopulta kiittämätön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Pikavihainen mies nostaa riidan, ja kiukkuinen tulee rikkoneeksi paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Ihmisen alentaa hänen oma ylpeytensä, mutta alavamielinen saa kunnian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Joka käy osille varkaan kanssa, se sieluansa vihaa; hän kuulee vannotuksen, mutta ei ilmaise mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Ihmispelko panee paulan, mutta Herraan luottavainen on turvattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Hallitsijan suosiota etsivät monet, mutta Herralta tulee miehelle oikeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Vääryyden mies on vanhurskaille kauhistus, ja oikean tien kulkija on kauhistus jumalattomalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Aagurin, Jaaken pojan, sanat; lauselma. Näin puhuu se mies: Minä olen väsyttänyt itseni, Jumala; olen väsyttänyt itseni, Jumala, ja menehdyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Sillä järjetön olen minä mieheksi, ei ole minulla ihmisymmärrystä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'enkä ole oppinut viisautta, tullakseni tuntemaan Pyhintä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Kuka on noussut taivaaseen ja astunut sieltä alas? Kuka on koonnut kouriinsa tuulen? Kuka on sitonut vedet vaipan sisään? Kuka on kohdalleen asettanut maan ääret kaikki? Mikä on hänen nimensä ja mikä hänen poikansa nimi, jos sen tiedät?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Jokainen Jumalan sana on taattu; hän on niiden kilpi, jotka häneen turvaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Älä lisää hänen sanoihinsa mitään, ettei hän vaatisi sinua tilille ja ettet valhettelijaksi joutuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Kahta minä sinulta pyydän, älä niitä minulta koskaan kiellä, kuolemaani saakka:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Vilppi ja valhepuhe pidä minusta kaukana. Älä köyhyyttä, älä rikkautta minulle anna; anna minulle ravinnoksi määräosani leipää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'etten kylläisenä tulisi kieltäjäksi ja sanoisi: \"Kuka on Herra?\" ja etten köyhtyneenä varastaisi ja rikkoisi Jumalani nimeä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Älä kieli palvelijasta hänen herrallensa; muutoin hän sinut kiroaa, ja sinä saat siitä kärsiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Voi sukua, joka isäänsä kiroaa eikä siunaa äitiänsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'sukua, joka on omissa silmissään puhdas, vaikka ei ole pesty liastansa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Voi sukua-kuinka ylpeät ovatkaan sen silmät ja kuinka korskea silmänluonti-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'sukua, jonka hampaat ovat miekkoja ja leukaluut veitsiä syödäksensä kurjat maasta pois ja köyhät ihmisten joukosta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Verenimijällä on kaksi tytärtä: Anna vielä! Anna vielä! Kolme on, jotka eivät kylläänsä saa, neljä, jotka eivät sano: \"Jo riittää\":');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'tuonela, hedelmätön kohtu, maa, joka ei saa kylläänsä vedestä, ja tuli, joka ei sano: \"Jo riittää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Joka isäänsä pilkkaa ja pitää halpana totella äitiänsä, häneltä korpit puron luona hakkaavat silmän, ja kotkan poikaset syövät sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Kolme on minusta ylen ihmeellistä, ja neljä on, joita en käsitä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'kotkan jäljet taivaalla, käärmeen jäljet kalliolla, laivan jäljet keskellä merta ja miehen jäljet nuoren naisen tykönä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Samoin ovat avionrikkoja-vaimon jäljet: hän syö, pyyhkii suunsa ja sanoo: \"En ole pahaa tehnyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Kolmen alla järkkyy maa, ja neljän alla ei se jaksa kestää:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'orjan alla, kun hän kuninkaaksi pääsee, houkan, kun hän saa kyllälti leipää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'hyljityn alla, kun hän miehen saa, ja palvelijattaren, kun hän emäntänsä syrjäyttää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Neljä on maassa vähäisintä, mutta viisaan viisasta silti:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Muurahaiset ovat voimaton kansa, mutta he hankkivat leipänsä kesällä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'tamaanit ovat heikko kansa, mutta he laittavat majansa kallioihin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'heinäsirkoilla ei ole kuningasta, mutta koko lauma lähtee järjestyksessä liikkeelle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'sisiliskoon voi tarttua käsin, mutta kuitenkin se oleskelee kuninkaan linnoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Kolmella on komea astunta, ja neljä komeasti kulkee:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'leijona, sankari eläinten joukossa, joka ei vääjää ketään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'hevonen, solakkakylki, tai kauris, ja kuningas joukkonsa johdossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Jos ylpeilit-olipa se houkkamaisuutta tai harkittua-niin laske käsi suullesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Sillä maitoa pusertamalla saa voin, nenää pusertamalla saa veren, ja vihoja pusertamalla saa riidan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Lemuelin, Massan kuninkaan, sanat, joilla hänen äitinsä kasvatti häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Mitä, poikani; mitä, kohtuni poika; mitä, lupausteni poika?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Älä anna voimaasi naisille, vaellustasi kuningasten turmelijatarten valtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Ei sovi kuningasten, Lemuel, ei sovi kuningasten viiniä juoda eikä ruhtinasten kysellä: \"Missä väkijuomaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Muutoin hän juodessaan unhottaa, mitä saädetty on, ja vääntelee kaikkien kurjuuden lasten oikeuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Antakaa väkevää juomaa menehtyvälle ja viiniä murhemielisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Sellainen juokoon ja unhottakoon köyhyytensä älköönkä enää vaivaansa muistelko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Avaa suusi mykän hyväksi, oikeuden hankkimiseksi kaikille sortuville.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Avaa suusi, tuomitse oikein, hanki kurjalle ja köyhälle oikeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Kelpo vaimon kuka löytää? Sellaisen arvo on helmiä paljon kalliimpi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Hänen miehensä sydän häneen luottaa, eikä siltä mieheltä riistaa puutu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Hän tekee miehellensä hyvää, ei pahaa, kaikkina elinpäivinänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Hän puuhaa villat ja pellavat ja halullisin käsin askartelee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Hän on kauppiaan laivojen kaltainen: leipänsä hän noutaa kaukaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'Kun yö vielä on, hän nousee ja antaa ravinnon perheellensä, piioilleen heidän osansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Hän haluaa peltoa ja hankkii sen, istuttaa viinitarhan kättensä hedelmällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Hän voimalla vyöttää kupeensa ja käsivartensa vahvistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Hankkeensa hän huomaa käyvän hyvin, ei sammu hänen lamppunsa yöllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Hän ojentaa kätensä kehrävarteen ja käyttelee värttinää kämmenissään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Hän avaa kätensä kurjalle, ojentaa köyhälle molemmat kätensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Ei pelkää hän perheensä puolesta lunta, sillä koko hänen perheensä on puettu purppuravillaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Hän valmistaa itsellensä peitteitä; hienoa pellavaa ja punapurppuraa on hänen pukunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Hänen miehensä on tunnettu porteissa, maanvanhinten seassa istuessansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Hän aivinapaitoja tekee ja myy, vöitä hän kauppiaalle toimittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Vallalla ja kunnialla hän on vaatetettu, ja hän nauraa tulevalle päivälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Suunsa hän avaa viisauden sanoihin, hänen kielellään on lempeä opetus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Hän tarkkaa talonsa menoa, eikä hän laiskan leipää syö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Hänen poikansa nousevat ja kiittävät hänen onneansa; hänen miehensä nousee ja ylistää häntä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, '\"Paljon on naisia, toimellisia menoissaan, mutta yli niitten kaikkien kohoat sinä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Pettävä on sulous, kauneus katoavainen; ylistetty se vaimo, joka Herraa pelkää!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Suokaa hänen nauttia kättensä hedelmiä, hänen tekonsa häntä porteissa ylistäkööt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Saarnaajan sanat, Daavidin pojan, joka oli kuninkaana Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Turhuuksien turhuus, sanoi saarnaaja, turhuuksien turhuus; kaikki on turhuutta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Mitä hyötyä on ihmiselle kaikesta vaivannäöstänsä, jolla hän vaivaa itseänsä auringon alla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Sukupolvi menee, ja sukupolvi tulee, mutta maa pysyy iäti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Ja aurinko nousee, ja aurinko laskee ja kiiruhtaa sille sijallensa, josta se jälleen nousee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Tuuli menee etelään ja kiertää pohjoiseen, kiertää yhä kiertämistään, ja samalle kierrollensa tuuli palajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Kaikki joet laskevat mereen, mutta meri ei siitänsä täyty; samaan paikkaan, johon joet ovat laskeneet, ne aina edelleen laskevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Kaikki tyynni itseänsä väsyttää, niin ettei kukaan sitä sanoa saata. Ei saa silmä kylläänsä näkemisestä eikä korva täyttänsä kuulemisesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Mitä on ollut, sitä vastakin on; ja mitä on tapahtunut, sitä vastakin tapahtuu. Ei ole mitään uutta auringon alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Jos jotakin on, josta sanotaan: \"Katso, tämä on uutta\", niin on sitä kuitenkin ollut jo ennen, ammoisina aikoina, jotka ovat olleet ennen meitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Ei jää muistoa esi-isistä; eikä jälkeläisistäkään, jotka tulevat, jää muistoa niille, jotka heidän jälkeensä tulevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Minä, saarnaaja, olin Israelin kuningas Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'Ja minä käänsin sydämeni viisaudella tutkimaan ja miettimään kaikkea, mitä auringon alla tapahtuu. Tämä on vaikea työ, jonka Jumala on antanut ihmislapsille, heidän sillä itseään rasittaaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Minä katselin kaikkia tekoja, mitä tehdään auringon alla, ja katso, se on kaikki turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Väärä ei voi suoristua, eikä vajaata voi täydeksi laskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Minä puhuin sydämessäni näin: Minä olen hankkinut suuren viisauden ja sitä yhä lisännyt, jopa yli kaikkien, jotka ovat ennen minua Jerusalemissa hallinneet, ja paljon on sydämeni nähnyt viisautta ja tietoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'Ja minä käänsin sydämeni tutkimaan viisautta ja tietoa, mielettömyyttä ja tyhmyyttä, ja minä tulin tietämään, että sekin oli tuulen tavoittelemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Sillä missä on paljon viisautta, siinä on paljon surua; ja joka tietoa lisää, se tuskaa lisää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Minä sanoin sydämessäni: Tule, minä tahdon koetella sinua ilolla, nauti hyvää. Mutta katso, sekin oli turhuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Naurusta minä sanoin: \"Mieletöntä!\" ja ilosta: \"Mitä se toimittaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Minä mietin mielessäni virkistää ruumistani viinillä-kuitenkin niin, että sydämeni harrastaisi viisautta-ja noudattaa tyhmyyttä, kunnes saisin nähdä, mikä olisi ihmislapsille hyvä, heidän tehdäksensä sitä taivaan alla lyhyinä elämänsä päivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Minä tein suuria töitä: rakensin itselleni taloja, istutin itselleni viinitarhoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Minä laitoin itselleni puutarhoja ja puistoja ja istutin niihin kaikkinaisia hedelmäpuita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Minä tein itselleni vesilammikoita kastellakseni niistä metsiköitä, joissa puita kasvoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Minä ostin orjia ja orjattaria, ja kotona syntyneitäkin minulla oli; myös oli minulla karjaa, raavaita ja lampaita, paljon enemmän kuin kenelläkään niistä, jotka olivat olleet ennen minua Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Minä kokosin itselleni myöskin hopeata ja kultaa ja kuninkaitten ja maakuntien aarteita ja hankin itselleni laulajia ja laulajattaria ja ihmislasten iloja, vaimon, jopa vaimoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Minä tulin suureksi ja yhä suuremmaksi, yli kaikkien, jotka olivat olleet ennen minua Jerusalemissa. Sen ohessa pysyi minussa viisauteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'Enkä minä pidättänyt silmiäni mistään, mitä ne pyysivät, enkä kieltänyt sydämeltäni mitään iloa, sillä minun sydämeni iloitsi kaikesta vaivannäöstäni, ja se oli minun osani kaikesta vaivannäöstäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Mutta kun minä käänsin huomioni kaikkiin töihin, joita minun käteni olivat tehneet, ja vaivannäköön, jolla olin vaivannut itseäni niitä tehdessäni, niin katso: se oli kaikki turhuutta ja tuulen tavoittelua; eikä ole hyötyä mistään auringon alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Kun minä käännyin katsomaan viisautta ja mielettömyyttä ja tyhmyyttä-sillä mitä taitaa ihminen, joka tulee kuninkaan jälkeen, muuta kuin tehdä, mitä jo ennen on tehty? -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'niin minä näin, että viisaus on hyödyllisempi tyhmyyttä, niinkuin valo on pimeyttä hyödyllisempi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Viisaalla on silmät päässänsä, tyhmä taas vaeltaa pimeässä; mutta minä tulin tietämään myös sen, että toisen käy niinkuin toisenkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Ja minä sanoin sydämessäni: Se, mikä kohtaa tyhmää, kohtaa minuakin; miksi olen sitten niin tuiki viisaaksi tullut? Ja minä sanoin sydämessäni: Tämäkin on turhuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Sillä ei jää viisaasta, niinkuin ei tyhmästäkään, ikuista muistoa, kun kerran tulevina päivinä kaikki unhotetaan; ja eikö kuole viisas niinkuin tyhmäkin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Niin minä kyllästyin elämään, sillä minusta oli pahaa se, mikä tapahtuu auringon alla, koskapa kaikki on turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Ja minä kyllästyin kaikkeen vaivannäkööni, jolla olin vaivannut itseäni auringon alla, koska minun täytyy se jättää ihmiselle, joka tulee minun jälkeeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'Ja kuka tietää, onko hän viisas vai tyhmä? Mutta hallitsemaan hän tulee kaikkia minun vaivannäköni hedelmiä, joiden tähden minä olen vaivannut itseäni ja ollut viisas auringon alla. Tämäkin on turhuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Niin minä annoin sydämeni vaipua epätoivoon kaikesta vaivannäöstäni, jolla olin vaivannut itseäni auringon alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Sillä niin on: ihmisen, joka on vaivaa nähnyt toimien viisaudella, tiedolla ja kunnolla, täytyy antaa kaikki ihmiselle, joka ei ole siitä vaivaa nähnyt, hänen osaksensa. Sekin on turhuutta ja on suuri onnettomuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Sillä mitä saa ihminen kaikesta vaivannäöstänsä ja sydämensä pyrkimyksestä, jolla hän vaivaa itseänsä auringon alla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Ovathan kaikki hänen päivänsä pelkkää tuskaa ja hänen työnsä surua, eikä yölläkään hänen sydämensä saa lepoa. Tämäkin on turhuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Ei ole ihmisellä muuta onnea kuin syödä ja juoda ja antaa sielunsa nauttia hyvää vaivannäkönsä ohessa; mutta minä tulin näkemään, että sekin tulee Jumalan kädestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, '-\"Sillä kuka voi syödä ja kuka nauttia ilman minua?\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Sillä hän antaa ihmiselle, joka on hänelle otollinen, viisautta, tietoa ja iloa; mutta syntiselle hän antaa työksi koota ja kartuttaa annettavaksi sille, joka on otollinen Jumalalle. Sekin on turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Kaikella on määräaika, ja aikansa on joka asialla taivaan alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Aika on syntyä ja aika kuolla. Aika on istuttaa ja aika repiä istutus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Aika on surmata ja aika parantaa. Aika on purkaa ja aika rakentaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Aika on itkeä ja aika nauraa. Aika on valittaa ja aika hypellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Aika on heitellä kiviä ja aika kerätä kivet. Aika on syleillä ja aika olla syleilemättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Aika on etsiä ja aika kadottaa. Aika on säilyttää ja aika viskata pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Aika on reväistä rikki ja aika ommella yhteen. Aika on olla vaiti ja aika puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Aika on rakastaa ja aika vihata. Aika on sodalla ja aika rauhalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Mitä hyötyä on työntekijällä siitä, mistä hän näkee vaivaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Minä olen katsonut sitä työtä, minkä Jumala on antanut ihmislapsille, heidän sillä itseään rasittaaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Kaiken hän on tehnyt kauniisti aikanansa, myös iankaikkisuuden hän on pannut heidän sydämeensä; mutta niin on, ettei ihminen käsitä tekoja, jotka Jumala on tehnyt, ei alkua eikä loppua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Minä tulin tietämään, ettei heillä ole muuta onnea kuin iloita ja tehdä hyvää eläessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Mutta jokaiselle ihmiselle on sekin, että hän syö ja juo ja nauttii hyvää kaiken vaivannäkönsä ohessa, Jumalan lahja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Minä tulin tietämään, että kaikki, mitä Jumala tekee, pysyy iäti. Ei ole siihen lisäämistä eikä siitä vähentämistä. Ja Jumala on sen niin tehnyt, että häntä peljättäisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Mitä nyt on, sitä on ollut jo ennenkin; ja mitä vasta on oleva, sitä on ollut jo ennenkin. Jumala etsii jälleen sen, mikä on mennyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Vielä minä näin auringon alla oikeuspaikan, ja siinä oli vääryys, ja vanhurskauden paikan, ja siinä oli vääryys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Minä sanoin sydämessäni: Vanhurskaan ja väärän tuomitsee Jumala, sillä siellä on jokaisella asialla ja jokaisella teolla aikansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Minä sanoin sydämessäni: Ihmislasten tähden se niin on, jotta Jumala heitä koettelisi ja he tulisivat näkemään, että he omassa olossaan ovat eläimiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Sillä ihmislasten käy niinkuin eläintenkin; sama on kumpienkin kohtalo. Niinkuin toiset kuolevat, niin toisetkin kuolevat; yhtäläinen henki on kaikilla. Ihmisillä ei ole mitään etua eläinten edellä, sillä kaikki on turhuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Kaikki menee samaan paikkaan. Kaikki on tomusta tullut, ja kaikki palajaa tomuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Kuka tietää ihmisen hengestä, kohoaako se ylös, ja eläimen hengestä, vajoaako se alas maahan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Niin minä tulin näkemään, että ei ole mitään parempaa, kuin että ihminen iloitsee teoistansa, sillä se on hänen osansa. Sillä kuka tuo hänet takaisin näkemään iloksensa sitä, mikä tulee hänen jälkeensä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Taas minä katselin kaikkea sortoa, jota harjoitetaan auringon alla, ja katso, siinä on sorrettujen kyyneleet, eikä ole heillä lohduttajaa; väkivaltaa tekee heidän sortajainsa käsi, eikä ole heillä lohduttajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Ja minä ylistin vainajia, jotka ovat jo kuolleet, onnellisemmiksi kuin eläviä, jotka vielä ovat elossa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'ja onnellisemmaksi kuin nämä kumpikaan sitä, joka ei vielä ole olemassa eikä ole nähnyt sitä pahaa, mikä tapahtuu auringon alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Ja minä näin kaikesta vaivannäöstä ja työn kunnollisuudesta, että se on toisen kateutta toista kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Sekin on turhuutta ja tuulen tavoittelua. Tyhmä panee kädet ristiin ja kalvaa omaa lihaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Parempi on pivollinen lepoa kuin kahmalollinen vaivannäköä ja tuulen tavoittelua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Taas minä näin turhuuden auringon alla:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Tuossa on yksinäinen, ei ole hänellä toista, ei poikaa, ei veljeäkään ole hänellä; mutta ei ole loppua kaikella hänen vaivannäöllänsä, eikä hänen silmänsä saa kylläänsä rikkaudesta. Ja kenen hyväksi minä sitten vaivaa näen ja pidätän itseni nautinnoista? Tämäkin on turhuutta ja on paha asia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Kahden on parempi kuin yksin, sillä heillä on vaivannäöstänsä hyvä palkka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Jos he lankeavat, niin toinen nostaa ylös toverinsa; mutta voi yksinäistä, jos hän lankeaa! Ei ole toista nostamassa häntä ylös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Myös, jos kaksi makaa yhdessä, on heillä lämmin; mutta kuinka voisi yksinäisellä olla lämmin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Ja yksinäisen kimppuun voi joku käydä, mutta kaksi pitää sille puolensa. Eikä kolmisäinen lanka pian katkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Parempi on köyhä, mutta viisas nuorukainen kuin vanha ja tyhmä kuningas, joka ei enää ymmärrä ottaa varoituksesta vaaria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Sillä vankilasta tuo toinen lähti tullaksensa kuninkaaksi, vaikka oli hänen kuninkaana ollessaan syntynyt köyhänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Minä näin kaikkien, jotka elivät ja vaelsivat auringon alla, olevan nuorukaisen puolella, tuon toisen, joka oli astuva hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Ei ollut loppua kaikella sillä väellä, niillä kaikilla, joita hän johti; mutta jälkipolvet eivät hänestä iloitse. Sillä sekin on turhuutta ja tuulen tavoittelemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Varo jalkasi, kun menet Jumalan huoneeseen. Tulo kuulemaan on parempi kuin tyhmäin teurasuhrin-anto, sillä he ovat tietämättömiä, ja niin he tekevät pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, '{5:1} Älä ole kerkeä suultasi, älköönkä sydämesi kiirehtikö lausumaan sanaa Jumalan edessä, sillä Jumala on taivaassa ja sinä olet maan päällä; sentähden olkoot sanasi harvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, '{5:2} Sillä paljosta työstä tulee unia, ja missä on paljon sanoja, siinä on tyhmä äänessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, '{5:3} Kun teet lupauksen Jumalalle, niin täytä se viivyttelemättä; sillä ei ole hänellä mielisuosiota tyhmiin: täytä, mitä lupaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, '{5:4} On parempi, ettet lupaa, kuin että lupaat etkä täytä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, '{5:5} Älä anna suusi saattaa ruumistasi syynalaiseksi, äläkä sano Jumalan sanansaattajan edessä: \"Se oli erehdys\"; miksi pitäisi Jumalan vihastua sinun puheestasi ja turmella sinun kättesi työt?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, '{5:6} Sillä paljot unet ovat pelkkää turhuutta; samoin paljot puheet. Mutta pelkää sinä Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, '{5:7} Jos näet köyhää sorrettavan sekä oikeutta ja vanhurskautta poljettavan maakunnassa, niin älä sitä asiaa ihmettele; sillä ylhäistä vartioitsee vielä ylhäisempi, ja sitäkin ylhäisemmät heitä molempia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, '{5:8} Ja maalle on kaikessa hyödyksi, että viljellyllä maalla on kuningas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, '{5:9} Joka rakastaa rahaa, ei saa rahaa kylläksensä, eikä voittoa se, joka rakastaa tavaran paljoutta. Sekin on turhuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, '{5:10} Omaisuuden karttuessa karttuvat sen syöjätkin; ja mitä muuta etua siitä on haltijallensa, kuin että silmillään sen näkee?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, '{5:11} Työntekijän uni on makea, söipä hän vähän tai paljon; mutta rikkaan ei hänen yltäkylläisyytensä salli nukkua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, '{5:12} On raskas onnettomuus, jonka minä näin auringon alla: rikkaus, joka on säilytetty onnettomuudeksi haltijallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, '{5:13} Se rikkaus katoaa onnettoman tapauksen kautta; ja jos hänelle on syntynyt poika, ei sen käsiin jää mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, '{5:14} Niinkuin hän tuli äitinsä kohdusta, niin on hänen alastonna jälleen mentävä pois, samoin kuin tulikin; eikä hän vaivannäöstänsä saa mitään, minkä veisi täältä kädessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, '{5:15} Raskas onnettomuus tämäkin on: aivan niinkuin hän tuli, on hänen mentävä; ja mitä hyötyä hänellä sitten on siitä, että on vaivaa nähnyt tuulen hyväksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, '{5:16} Myös kuluttaa hän kaikki päivänsä pimeydessä; ja surua on hänellä paljon, kärsimystä ja mielikarvautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, '{5:17} Katso, minkä minä olen tullut näkemään, on hyvää ja kaunista syödä ja juoda ja nauttia hyvää kaiken vaivannäkönsä ohessa, jolla ihminen itseänsä vaivaa auringon alla lyhyinä elämänsä päivinä, jotka Jumala on hänelle antanut; sillä se on hänen osansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, '{5:18} Sekin on Jumalan lahja, jos Jumala kenelle ihmiselle antaa rikkautta ja tavaraa ja sallii hänen syödä siitä ja saada osansa ja iloita vaivannäkönsä ohessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, '{5:19} Sillä hän ei tule niin paljon ajatelleeksi elämänsä päiviä, kun Jumala suostuu hänen sydämensä iloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'On onnettomuus tämäkin, jonka olen nähnyt auringon alla ja joka raskaasti painaa ihmistä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'että Jumala antaa miehelle rikkautta ja tavaraa ja kunniaa, niin ettei hänen sielultaan puutu mitään kaikesta siitä, mitä hän halajaa, mutta Jumala ei salli hänen nauttia sitä, vaan sen nauttii vieras. Se on turhuutta ja raskas kärsimys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Vaikka syntyisi miehelle sata lasta ja hän eläisi vuosia paljon ja paljot olisivat hänen vuottensa päivät, mutta hän ei saisi tyydyttää omaa haluaan omaisuudellansa eikä saisi edes hautaustakaan, niin minä sanon, että keskoinen olisi onnellisempi kuin hän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Sillä se turhaan tulee ja pimeyteen menee, ja pimeyteen peittyy sen nimi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Ei se ole aurinkoa nähnyt eikä tuntenut. Sen lepo on parempi kuin hänen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'Ja vaikka hän eläisi kaksi kertaa tuhannen vuotta, mutta ei saisi onnea nähdä-eikö kuitenkin kaikki mene samaan paikkaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Kaikki ihmisen vaivannäkö tapahtuu hänen oman suunsa hyväksi, ja kuitenkaan ei halu täyty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Sillä mitä etua on viisaalla tyhmän edellä, ja mitä kurjalla siitä, että hän osaa oikein vaeltaa elävitten edessä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Parempi silmän näkö kuin halun haihattelu. Tämäkin on turhuutta ja tuulen tavoittelua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Mitä olemassa on, sille on pantu nimi jo ammoin; ja edeltä tunnettua on ollut, mitä ihmisestä on tuleva. Ei voi hän riidellä väkevämpänsä kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Sillä niin on: puheen paljous enentää turhuutta. Mitä etua on ihmisellä siitä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, '{7:1} Sillä kuka tietää, mikä on ihmiselle hyvä elämässä, hänen elämänsä lyhyinä, turhina päivinä, jotka hän viettää kuin varjo; ja kuka ilmaisee ihmiselle, mitä on tuleva hänen jälkeensä auringon alla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, '{7:2} Hyvä nimi on parempi kuin kallis öljy, ja kuolinpäivä parempi kuin syntymäpäivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, '{7:3} Parempi kuin pitotaloon on mennä surutaloon, sillä siinä on kaikkien ihmisten loppu, ja elossa oleva painaa sen mieleensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, '{7:4} Suru on parempi kuin nauru, sillä sydämelle on hyväksi, että kasvot ovat murheelliset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, '{7:5} Viisaitten sydän on surutalossa, tyhmien sydän ilotalossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, '{7:6} Parempi on kuulla viisaan nuhdetta, kuin olla kuulemassa tyhmien laulua;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, '{7:7} sillä niinkuin orjantappurain rätinä padan alla, on tyhmän nauru. Ja sekin on turhuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, '{7:8} Sillä väärä voitto tekee viisaan hulluksi, ja lahja turmelee sydämen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, '{7:9} Asian loppu on parempi kuin sen alku, ja pitkämielinen on parempi kuin korkeamielinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, '{7:10} Älköön mielesi olko pikainen vihaan, sillä viha majautuu tyhmäin poveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, '{7:11} Älä sano: \"Mikä siinä on, että entiset ajat olivat paremmat kuin nykyiset?\" Sillä sitä et viisaudesta kysy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, '{7:12} Viisaus on yhtä hyvä kuin perintöosa ja on etu niille, jotka ovat näkemässä aurinkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, '{7:13} Sillä viisauden varjossa on kuin rahan varjossa, mutta tieto on hyödyllisempi: viisaus pitää haltijansa elossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, '{7:14} Katso Jumalan tekoja; sillä kuka voi sen suoristaa, minkä hän on vääräksi tehnyt?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, '{7:15} Hyvänä päivänä ole hyvillä mielin, ja pahana päivänä ymmärrä, että toisen niinkuin toisenkin on Jumala tehnyt, koskapa ihminen ei saa mitään siitä, mikä hänen jälkeensä tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, '{7:16} Kaikkea olen tullut näkemään turhina päivinäni: on vanhurskaita, jotka hukkuvat vanhurskaudessaan, ja on jumalattomia, jotka elävät kauan pahuudessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, '{7:17} Älä ole kovin vanhurskas äläkä esiinny ylen viisaana: miksi tuhoaisit itsesi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, '{7:18} Älä ole kovin jumalaton, äläkä ole tyhmä: miksi kuolisit ennen aikaasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, '{7:19} Hyvä on, että pidät kiinni toisesta etkä hellitä kättäsi toisestakaan, sillä Jumalaa pelkääväinen selviää näistä kaikista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, '{7:20} Viisaus auttaa viisasta voimakkaammin kuin kymmenen vallanpitäjää, jotka ovat kaupungissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, '{7:21} Sillä ei ole maan päällä ihmistä niin vanhurskasta, että hän tekisi vain hyvää eikä tekisi syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, '{7:22} Älä myöskään pane mieleesi kaikkia puheita, mitä puhutaan, ettet kuulisi palvelijasi sinua kiroilevan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, '{7:23} Sillä oma sydämesikin tietää, että myös sinä olet monta kertaa kiroillut muita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, '{7:24} Kaiken tämän olen viisaudella koetellut. Minä sanoin: \"Tahdon tulla viisaaksi\", mutta se pysyi minusta kaukana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, '{7:25} Kaukana on kaiken olemus ja syvällä, syvällä; kuka voi sen löytää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, '{7:26} Minä ryhdyin sydämessäni oppimaan, miettimään ja etsimään viisautta ja tutkistelun tuloksia, tullakseni tuntemaan jumalattomuuden typeryydeksi ja tyhmyyden mielettömyydeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, '{7:27} Ja minä löysin sen, mikä on kuolemaa katkerampi: naisen, joka on verkko, jonka sydän on paula ja jonka kädet ovat kahleet. Se, joka on otollinen Jumalan edessä, pelastuu hänestä, mutta synnintekijä häneen takertuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, '{7:28} Katso, tämän minä olen löytänyt, sanoi saarnaaja, pyrkiessäni asia asialta löytämään tutkistelun tulosta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, '{7:29} mitä sieluni on yhäti etsinyt, mutta mitä en ole löytänyt, on tämä: olen löytänyt tuhannesta yhden miehen, mutta koko siitä luvusta en ole löytänyt yhtäkään naista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, '{7:30} Katso, tämän ainoastaan olen löytänyt: että Jumala on tehnyt ihmiset suoriksi, mutta itse he etsivät monia mutkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Kuka on viisaan vertainen, ja kuka taitaa selittää asian? Ihmisen viisaus kirkastaa hänen kasvonsa, ja hänen kasvojensa kovuus muuttuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Minä sanon: Ota vaari kuninkaan käskystä, varsinkin Jumalan kautta vannotun valan tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Älä ole kerkeä luopumaan hänestä, äläkä asetu pahan asian puolelle, sillä hän tekee, mitä vain tahtoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Sillä kuninkaan sana on voimallinen, ja kuka voi sanoa hänelle: Mitäs teet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Joka käskyn pitää, ei tiedä pahasta asiasta; ja viisaan sydän tietää ajan ja tuomion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Sillä itsekullakin asialla on aikansa ja tuomionsa; ihmistä näet painaa raskaasti hänen pahuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Hän ei tiedä, mitä tuleva on; sillä kuka ilmaisee hänelle, miten se on tuleva?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Ei ole ihminen tuulen valtias, niin että hän voisi sulkea tuulen, ei hallitse kukaan kuoleman päivää, ei ole pääsyä sodasta, eikä jumalattomuus pelasta harjoittajaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Kaiken tämän minä tulin näkemään, kun käänsin sydämeni tarkkaamaan kaikkea, mitä auringon alla tapahtuu aikana, jolloin ihminen vallitsee toista ihmistä hänen onnettomuudekseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Sitten minä näin, kuinka jumalattomat haudattiin ja menivät lepoon, mutta ne, jotka olivat oikein tehneet, saivat lähteä pois pyhästä paikasta ja joutuivat unhotuksiin kaupungissa. Sekin on turhuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Milloin pahan teon tuomio ei tule pian, saavat ihmislapset rohkeutta tehdä pahaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'koskapa syntinen saa tehdä pahaa sata kertaa ja elää kauan; tosin minä tiedän, että Jumalaa pelkääväisille käy hyvin, sentähden että he häntä pelkäävät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'mutta että jumalattomalle ei käy hyvin eikä hän saa jatkaa päiviään pitkiksi kuin varjo, sentähden ettei hän pelkää Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'On turhuutta sekin, mitä tapahtuu maan päällä, kun vanhurskaita on, joiden käy, niinkuin olisivat jumalattomain tekoja tehneet, ja jumalattomia on, joiden käy, niinkuin olisivat vanhurskaitten tekoja tehneet. Minä sanoin: sekin on turhuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Ja minä ylistin iloa; koska ei ihmisellä auringon alla ole mitään parempaa kuin syödä ja juoda ja olla iloinen; se seuraa häntä hänen vaivannäkönsä ohessa hänen elämänsä päivinä, jotka Jumala on antanut hänelle auringon alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Kun minä käänsin sydämeni oppimaan viisautta ja katsomaan työtä, jota tehdään maan päällä saamatta untakaan silmiin päivällä tai yöllä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'niin minä tulin näkemään kaikista Jumalan teoista, että ihminen ei voi käsittää sitä, mitä tapahtuu auringon alla; sillä ihminen saa kyllä nähdä vaivaa etsiessään, mutta ei hän käsitä. Ja jos viisas luuleekin tietävänsä, ei hän kuitenkaan voi käsittää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Niin minä painoin mieleeni kaiken tämän ja pyrin saamaan kaikkea tätä selville, kuinka näet vanhurskaat ja viisaat ja heidän tekonsa ovat Jumalan kädessä. Ei rakkauskaan eikä viha ole ihmisen tiedettävissä; kaikkea voi hänellä olla edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Kaikkea voi tapahtua kaikille. Sama kohtalo on vanhurskaalla ja jumalattomalla, hyvällä, puhtaalla ja saastaisella, uhraajalla ja uhraamattomalla; hyvän käy niinkuin syntisenkin, vannojan niinkuin valaa pelkäävänkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'Se on onnettomuus kaikessa, mitä tapahtuu auringon alla, että kaikilla on sama kohtalo, ja myös se, että ihmislasten sydän on täynnä pahaa ja että mielettömyys on heillä sydämessä heidän elinaikansa; ja senjälkeen-vainajien tykö!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Onhan sillä, jonka vielä on suotu olla kaikkien eläväin seurassa, toivoa. Sillä elävä koira on parempi kuin kuollut leijona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Sillä elävät tietävät, että heidän on kuoltava, mutta kuolleet eivät tiedä mitään, eikä heillä ole paikkaa, vaan heidän muistonsa on unhotettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Myös heidän rakkautensa, vihansa ja intohimonsa on jo aikoja mennyt, eikä heillä ole milloinkaan enää osaa missään, mitä tapahtuu auringon alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Tule siis, syö leipäsi ilolla ja juo viinisi hyvillä mielin, sillä jo aikaa on Jumala hyväksynyt nuo tekosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Vaatteesi olkoot aina valkeat, ja öljy älköön puuttuko päästäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Nauti elämää vaimon kanssa, jota rakastat, kaikkina turhan elämäsi päivinä, jotka Jumala on sinulle antanut auringon alla-kaikkina turhina päivinäsi, sillä se on sinun osasi elämässä ja vaivannäössäsi, jolla vaivaat itseäsi auringon alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Tee kaikki, mitä voimallasi tehdyksi saat, sillä ei ole tekoa, ei ajatusta, ei tietoa eikä viisautta tuonelassa, jonne olet menevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Taas minä tulin näkemään auringon alla, että ei ole juoksu nopsain vallassa, ei sota urhojen, ei leipä viisaitten, ei rikkaus ymmärtäväisten eikä suosio taitavain vallassa, vaan aika ja kohtalo kohtaa kaikkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Sillä ei ihminen tiedä aikaansa, niinkuin eivät kalatkaan, jotka tarttuvat pahaan verkkoon, eivätkä linnut, jotka käyvät kiinni paulaan; niinkuin ne, niin pyydystetään ihmislapsetkin pahana aikana, joka yllättää heidät äkisti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Tämänkin minä tulin näkemään viisaudeksi auringon alla, ja se oli minusta suuri:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Oli pieni kaupunki ja siinä miehiä vähän. Ja suuri kuningas tuli sitä vastaan, saarsi sen ja rakensi sitä vastaan suuria piiritystorneja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'Mutta siellä oli köyhä, viisas mies, ja hän pelasti kaupungin viisaudellaan. Mutta ei kukaan ihminen muistanut sitä köyhää miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Niin minä sanoin: Viisaus on parempi kuin voima, mutta köyhän viisautta halveksitaan, eikä hänen sanojansa kuulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Viisaitten sanat, hiljaisuudessa kuullut, ovat paremmat kuin tyhmäin päämiehen huuto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Viisaus on parempi kuin sota-aseet, mutta yksi ainoa syntinen saattaa hukkaan paljon hyvää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Myrkkykärpäset saavat haisemaan ja käymään voiteentekijän voiteen. Pieni tyhmyys painaa enemmän kuin viisaus ja kunnia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Viisaan sydän vetää oikealle, tyhmän vasemmalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Tietä käydessäkin puuttuu tyhmältä mieltä: jokaiselle hän ilmaisee olevansa tyhmä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Jos hallitsijassa nousee viha sinua kohtaan, niin älä jätä paikkaasi; sillä sävyisyys pidättää suurista synneistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'On onnettomuus se, minkä olen nähnyt auringon alla, vallanpitäjästä lähtenyt erehdys:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'tyhmyys asetetaan arvon korkeuksiin, ja rikkaat saavat istua alhaalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Minä olen nähnyt palvelijat hevosten selässä ja ruhtinaat kävelemässä kuin palvelijat maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Joka kuopan kaivaa, se siihen putoaa; joka muuria purkaa, sitä puree käärme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Joka kiviä louhii, se niihin loukkaantuu; joka puita halkoo, se joutuu siinä vaaraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Jos rauta on tylsynyt eikä teränsuuta tahkota, täytyy ponnistaa voimia; mutta hyödyllinen kuntoonpano on viisautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Jos käärme puree silloin, kun sitä ei ole lumottu, ei lumoojalla ole hyötyä taidostaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Sanat viisaan suusta saavat suosiota, mutta tyhmän nielevät hänen omat huulensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Hänen suunsa sanain alku on tyhmyyttä, ja hänen puheensa loppu pahaa mielettömyyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Tyhmä puhuu paljon; mutta ihminen ei tiedä, mitä tuleva on. Ja kuka ilmaisee hänelle, mitä hänen jälkeensä tulee?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Oma vaivannäkö väsyttää tyhmän, joka ei osaa kaupunkiinkaan kulkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Voi sinua, maa, jolla on kuninkaana poikanen ja jonka ruhtinaat jo aamulla aterioita pitävät!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Onnellinen sinä, maa, jolla on jalosukuinen kuningas ja jonka ruhtinaat pitävät aterioita oikeaan aikaan, miehekkäästi eikä juopotellen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Missä laiskuus on, siinä vuoliaiset vaipuvat; ja missä kädet velttoina riippuvat, tippuu huoneeseen vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Hauskuudeksi ateria laitetaan, ja viini ilahuttaa elämän; mutta raha kaiken hankkii.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Älä ajatuksissasikaan kiroile kuningasta, äläkä makuukammiossasikaan kiroile rikasta, sillä taivaan linnut kuljettavat sinun äänesi ja siivelliset ilmaisevat sinun sanasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Lähetä leipäsi vetten yli, sillä ajan pitkään sinä saat sen jälleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Anna osa seitsemälle, kahdeksallekin, sillä et tiedä, mitä onnettomuutta voi tulla maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Jos pilvet tulevat täyteen sadetta, valavat ne sen maahan. Ja jos puu kaatuu etelää kohti tai pohjoista, niin mihin paikkaan puu kaatui, siihen se jää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Joka tuulta tarkkaa, ei kylvä; ja joka pilviä pälyy, ei leikkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Niinkuin et tiedä tuulen teitä etkä luitten rakentumista raskaana olevan kohdussa, niin et myöskään tiedä Jumalan tekoja, hänen, joka kaikki tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Kylvä siemenesi aamulla äläkä hellitä kättäsi ehtoollakaan; sillä et tiedä, tuoko onnistuu vai tämä vai onko kumpikin yhtä hyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Suloinen on valo, ja silmille tekee hyvää nähdä aurinkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Niin, jos ihminen elää vuosia paljonkin, iloitkoon hän niistä kaikista, mutta muistakoon pimeitä päiviä, sillä niitä tulee paljon. Kaikki, mikä tulee, on turhuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Iloitse, nuorukainen, nuoruudessasi, ja sydämesi ilahuttakoon sinua nuoruusikäsi päivinä. Vaella sydämesi teitä ja silmiesi halun mukaan; mutta tiedä: Jumala tuo sinut tuomiolle kaikesta tästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Karkoita suru sydämestäsi ja torju kärsimys ruumiistasi, sillä nuoruus ja aamurusko ovat turhuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Ja muista Luojaasi nuoruudessasi, ennenkuin pahat päivät tulevat ja joutuvat ne vuodet, joista olet sanova:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, '\"Nämä eivät minua miellytä\"; ennenkuin pimenee aurinko, päivänvalo, kuu ja tähdet, ja pilvet palajavat sateen jälkeenkin-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'jolloin huoneen vartijat vapisevat ja voiman miehet käyvät koukkuisiksi ja jauhajanaiset ovat joutilaina, kun ovat menneet vähiin, ja akkunoista-kurkistelijat jäävät pimeään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'ja kadulle vievät ovet sulkeutuvat ja myllyn ääni heikkenee ja noustaan linnun lauluun ja kaikki laulun tyttäret hiljentyvät;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'myös peljätään mäkiä, ja tiellä on kauhuja, ja mantelipuu kukkii, ja heinäsirkka kulkee kankeasti, ja kapriisinnuppu on tehoton; sillä ihminen menee iankaikkiseen majaansa, ja valittajat kiertelevät kaduilla-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'ennenkuin hopealanka katkeaa ja kultamalja särkyy ja vesiastia rikkoutuu lähteellä ja ammennuspyörä särkyneenä putoaa kaivoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'Ja tomu palajaa maahan, niinkuin on ollutkin, ja henki palajaa Jumalan tykö, joka sen on antanutkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Turhuuksien turhuus, sanoi saarnaaja; kaikki on turhuutta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'Sen lisäksi, että saarnaaja oli viisas, hän myös opetti kansalle tietoa, punnitsi, harkitsi ja sommitteli sananlaskuja paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Saarnaaja koki löytää kelvollisia sanoja, oikeassa mielessä kirjoitettuja, totuuden sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Viisaitten sanat ovat kuin tutkaimet ja kootut lauseet kuin isketyt naulat; ne ovat saman Paimenen antamia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Ja vielä näiden lisäksi: Poikani, ota varoituksesta vaari; paljolla kirjaintekemisellä ei ole loppua, ja paljo tutkistelu väsyttää ruumiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Loppusana kaikesta, mitä on kuultu, on tämä: Pelkää Jumalaa ja pidä hänen käskynsä, sillä niin tulee jokaisen ihmisen tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Sillä Jumala tuo kaikki teot tuomiolle, joka kohtaa kaikkea salassa olevaa, olkoon se hyvää tai pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Salomon korkea veisu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Hän suudelkoon minua suunsa suudelmilla. Sillä sinun rakkautesi on suloisempi kuin viini.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Suloinen on voiteittesi tuoksu, vuodatettu öljy on sinun nimesi; sentähden sinua nuoret naiset rakastavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Vedä minut mukaasi, rientäkäämme! Kuningas on tuonut minut kammioihinsa. Me riemuitsemme ja iloitsemme sinusta, me ylistämme sinun rakkauttasi enemmän kuin viiniä; syystä he sinua rakastavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, '\"Minä olen musta, mutta ihana, te Jerusalemin tyttäret, kuin Keedarin teltat, kuin Salomon seinäverhot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Älkää katsoko sitä, että minä olen musta, päivän paahtama. Äitini pojat vihastuivat minuun, panivat minut viinitarhain vartijaksi-omaa viinitarhaani en vartioinut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, '\"Sano minulle sinä, jota sieluni rakastaa, missä laumaasi paimennat, missä annat sen keskipäivällä levätä. Miksi minä hunnutettuna joutuisin sinun toveriesi laumain luo!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, '\"Jos et sitä tiedä, sinä naisista kaunein, käy lammasten jälkiä ja kaitse vohliasi paimenten telttapaikoilla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, '\"Tammaani, joka on faraon vaunujen edessä, sinut, armaani, vertaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Ihanat ovat sinun poskesi käätyinensä, kaulasi helminauhoinensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Me teemme sinulle kultakäädyt ynnä hopeasta niihin nastat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, '\"Kuninkaan istuessa pöydässään tuoksui minun nardukseni kaiken aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Rakkaani on minulle mirhakimppu, joka rintojeni välissä lepää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Rakkaani on kooferkukka-terttu Een-Gedin viinitarhoista.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, '\"Katso, kaunis sinä olet, armaani; katso, kaunis olet, silmäsi ovat kyyhkyläiset.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, '\"Katso, kaunis sinä olet, rakkaani; kuinka suloinen, kuinka vihanta on vuoteemme!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Huoneittemme seininä ovat setripuut, kattonamme kypressit.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, '\"Minä olen Saaronin kukkanen, olen laaksojen lilja.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, '\"Niinkuin lilja orjantappurain keskellä, niin on minun armaani neitosten keskellä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, '\"Niinkuin omenapuu metsäpuitten keskellä, niin on minun rakkaani nuorukaisten keskellä; minä halajan istua sen varjossa, ja sen hedelmä on minun suussani makea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Hän on vienyt minut viinimajaan; rakkaus on hänen lippunsa minun ylläni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Vahvistakaa minua rypälekakuilla, virvoittakaa minua omenilla, sillä minä olen rakkaudesta sairas.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Hänen vasen kätensä on minun pääni alla, ja hänen oikea kätensä halaa minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Minä vannotan teitä, te Jerusalemin tyttäret, gasellien tai kedon peurojen kautta: älkää herätelkö, älkää häiritkö rakkautta, ennenkuin se itse haluaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Kuule! Rakkaani tulee! Katso, tuolla hän tulee hyppien vuorilla, kiitäen kukkuloilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Rakkaani on gasellin kaltainen tai nuoren peuran. Katso, tuolla hän seisoo seinämme takana, katsellen ikkunasta sisään, kurkistellen ristikoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Rakkaani lausuu ja sanoo minulle: \"Nouse, armaani, sinä kaunoiseni, ja tule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Sillä katso, talvi on väistynyt, sateet ovat ohitse, ovat menneet menojaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Kukkaset ovat puhjenneet maahan, laulun aika on tullut, ja metsäkyyhkysen ääni kuuluu maassamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Viikunapuu tekee keväthedelmää, viiniköynnökset ovat kukassa ja tuoksuavat. Nouse, armaani, sinä kaunoiseni, ja tule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Kyyhkyseni, joka piilet kallionkoloissa, vuorenpengermillä anna minun nähdä kasvosi, anna minun kuulla äänesi, sillä suloinen on sinun äänesi ja ihanat ovat sinun kasvosi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Ottakaamme ketut kiinni, pienet ketut, jotka viinitarhoja turmelevat, sillä viinitarhamme ovat kukassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Rakkaani on minun, ja minä hänen-hänen, joka paimentaa liljojen keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Kunnes päivä viilenee ja varjot pakenevat, kiertele, rakkaani, kuin gaselli, kuin nuori peura tuoksuisilla vuorilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Yöllä minä vuoteellani etsin häntä, jota minun sieluni rakastaa, minä etsin, mutta en löytänyt häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, '\"Minä nousen ja kiertelen kaupunkia, katuja ja toreja, etsin häntä, jota minun sieluni rakastaa.\" Minä etsin, mutta en löytänyt häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Kohtasivat minut vartijat, jotka kaupunkia kiertävät. \"Oletteko nähneet häntä, jota minun sieluni rakastaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Tuskin olin kulkenut heidän ohitsensa, kun löysin hänet, jota minun sieluni rakastaa; minä tartuin häneen enkä hellittänyt hänestä, ennenkuin olin saattanut hänet äitini taloon, kantajani kammioon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Minä vannotan teitä, te Jerusalemin tyttäret, gasellien tai kedon peurojen kautta: älkää herätelkö, älkää häiritkö rakkautta, ennenkuin se itse haluaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Mikä tuolla tulee erämaasta kuin savupatsaat, tuoksuten mirhalta ja suitsukkeelta, kaikkinaisilta kauppiaan hajujauheilta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Katso, siinä on Salomon kantotuoli ja sen ympärillä kuusikymmentä urhoa, Israelin urhoja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'kaikki miekkamiehiä, sotaan harjoitettuja; jokaisella on miekka kupeellansa öitten kauhuja vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Kuningas Salomo teetti itsellensä kantotuolin Libanonin puista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Sen patsaat hän teetti hopeasta, sen selustan kullasta, sen istuimen purppurasta; sisältä sen koristeli Jerusalemin tyttärien rakkaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Tulkaa ulos, Siionin tyttäret, ja katsokaa kuningas Salomoa, katsokaa kruunua, jolla hänen äitinsä hänet kruunasi hänen hääpäivänänsä, hänen sydämensä ilonpäivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, '\"Katso, kaunis sinä olet, armaani; katso, kaunis sinä olet. Kyyhkyläiset ovat sinun silmäsi huntusi takana; sinun hiuksesi ovat kuin vuohilauma, joka laskeutuu Gileadin vuorilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Sinun hampaasi ovat kuin lauma kerittyjä lampaita, pesosta nousseita, kaikilla kaksoiset, ei yhtäkään karitsatonta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Kuin punainen nauha ovat sinun huulesi, ja suusi on suloinen; kuin granaattiomena, kypsyyttään halkeileva, on sinun ohimosi huntusi takana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Sinun kaulasi on niinkuin Daavidin torni, linnaksi rakennettu; tuhat kilpeä riippuu siinä, urhojen varustuksia kaikkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Sinun rintasi ovat kuin kaksi nuorta peuraa, kuin gasellin kaksoiset, jotka käyvät laitumella liljain keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Siksi kunnes päivä viilenee ja varjot pakenevat, minä käyn mirhavuorelle ja suitsukekukkulalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Kaikin olet kaunis, armaani, ei ole sinussa ainoatakaan virheä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, '\"Tule kanssani Libanonilta, sinä morsiameni, tule kanssani Libanonilta. Lähde pois Amanan huipulta, Senirin ja Hermonin huipuilta, leijonain leposijoilta ja pantterien vuorilta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, '\"Olet lumonnut minut, siskoni, morsiameni, lumonnut minut yhdellä ainoalla silmäykselläsi, yhdellä ainoalla kaulakoristeesi käädyllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Kuinka ihana onkaan sinun rakkautesi, siskoni, morsiameni! Kuinka paljon suloisempi viiniä on sinun rakkautesi, suloisempi kaikkia balsameja sinun voiteittesi tuoksu!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Sinun huulesi tiukkuvat hunajaa, morsiameni; mesi ja maito on sinun kielesi alla, ja sinun vaatteittesi tuoksu on kuin Libanonin tuoksu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, '\"Suljettu yrttitarha on siskoni, morsiameni, suljettu kaivo, lukittu lähde.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Sinä versot kuin paratiisi, jossa on granaattiomenia ynnä kalliita hedelmiä, koofer-kukkia ja narduksia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'nardusta ja sahramia, kalmoruokoa ja kanelia ynnä kaikkinaisia suitsukepuita, mirhaa ja aloeta ynnä kaikkinaisia parhaita balsamikasveja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Sinä olet yrttitarhojen lähde, elävien vetten kaivo, Libanonilta virtaavaisten.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, '\"Heräjä, pohjatuuli, tule, etelätuuli; puhalla yrttitarhaani, että sen balsamituoksut tulvahtaisivat. Tulkoon puutarhaansa rakkaani ja syököön sen kalliita hedelmiä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, '\"Minä tulen yrttitarhaani, siskoni, morsiameni; minä poimin mirhani ja balsamini, minä syön mesileipäni ja hunajani, juon viinini ja maitoni.\" Syökää, ystävät, juokaa ja juopukaa rakkaudesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Minä nukuin, mutta minun sydämeni valvoi. Kuule, rakkaani kolkuttaa: \"Avaa minulle, siskoseni, armaani, kyyhkyseni, puhtoiseni. Sillä pääni on kastetta täynnä, kiharani yön pisaroita.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, '\"Olen ihokkaani riisunut; pukisinko sen päälleni enää? Olen jalkani pessyt; tahraisinko ne taas?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Rakkaani pisti kätensä ovenreiästä sisään. Silloin minun sydämeni liikkui häntä kohden;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'minä nousin avaamaan rakkaalleni, ja minun käteni tiukkuivat mirhaa, sormeni sulaa mirhaa salvan kädensijoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Minä avasin rakkaalleni, mutta rakkaani oli kadonnut, mennyt menojaan. Hänen puhuessaan oli sieluni vallannut hämmennys. Minä etsin häntä, mutta en häntä löytänyt; minä huusin häntä, mutta ei hän minulle vastannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Kohtasivat minut vartijat, jotka kaupunkia kiertävät, he löivät minua ja haavoittivat minut; päällysharson riistivät yltäni muurien vartijat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, '\"Minä vannotan teitä, te Jerusalemin tyttäret: jos löydätte rakkaani, mitä hänelle sanotte? Sanokaa, että minä olen rakkaudesta sairas.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, '\"Mitä on sinun rakkaasi muita parempi, sinä naisista kaunein? Mitä on sinun rakkaasi muita parempi, ettäs meitä näin vannotat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, '\"Minun rakkaani on valkoinen ja punainen, kymmentä tuhatta jalompi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Hänen päänsä on kultaa, puhtainta kultaa, hänen kiharansa kuin palmunlehvät, mustat kuin kaarne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Hänen silmänsä ovat kuin kyyhkyset vesipurojen partaalla, jotka ovat maidossa kylpeneet ja istuvat runsauden ääressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Hänen poskensa ovat kuin balsamilava, kuin höystesäiliöt; hänen huulensa ovat liljat, ne tiukkuvat sulaa mirhaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Hänen käsivartensa ovat kultatangot, krysoliittejä täynnä. Hänen lantionsa on norsunluinen taideteos, safiireilla peitetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Hänen jalkansa ovat marmoripatsaat aitokultaisten jalustain nojassa. Hän on näöltänsä kuin Libanon, uhkea kuin setripuut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Hänen suunsa on sula makeus, hän on pelkkää suloisuutta. Sellainen on minun rakkaani, sellainen on ystäväni, te Jerusalemin tyttäret.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, '\"Minne on mennyt rakkaasi, sinä naisista kaunein? Kunne on kääntynyt rakkaasi? Etsikäämme häntä yhdessä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, '\"Rakkaani on mennyt yrttitarhaansa, balsamilavojen luo, paimentamaan yrttitarhoissa ja liljoja poimimaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Minä olen rakkaani oma, ja rakkaani on minun-hän, joka paimentaa liljojen keskellä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, '\"Kaunis kuin Tirsa olet sinä, armaani, suloinen kuin Jerusalem, peljättävä kuin sotajoukot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Käännä pois silmäsi minusta, sillä ne kiehtovat minut. Sinun hiuksesi ovat kuin vuohilauma, joka laskeutuu Gileadilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Sinun hampaasi ovat kuin lauma uuhia, pesosta nousseita, kaikilla kaksoiset, ei yhtäkään karitsatonta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Kuin granaattiomena, kypsyyttään halkeileva, on sinun ohimosi huntusi takana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Kuusikymmentä on kuningatarta ja kahdeksankymmentä sivuvaimoa ja nuoria naisia ilman määrää:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'yksi ainoa on minun kyyhkyseni, puhtoiseni, äitinsä ainokainen, synnyttäjänsä valio. Neitoset hänet nähdessään kiittävät hänen onneansa, kuningattaret ja sivuvaimot ylistävät häntä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, '\"Kuka on neito, joka ylenee kuin aamunkoi, kauniina kuin kuu, kirkkaana kuin päivänpaiste, peljättävänä kuin sotajoukot?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, '\"Pähkinätarhaan minä menin katselemaan laakson vihreyttä, katsomaan, joko viiniköynnös versoo, joko kukkivat granaattipuut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Aavistamattani asetti sieluni minut jalon kansani vaunuihin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, '\"Palaja, palaja, suulemitar! Palaja, palaja, ihaillaksemme sinua!\" \"Mitä ihailette suulemittaressa, katselette hänen asekarkelossaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, '{7:2} \"Kuinka kauniisti astelet kengissäsi, sinä ruhtinaan tytär! Sinun lanteesi kaartuvat kuin kaulakorut, taiturin kätten tekemät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, '{7:3} Sinun povesi on ympyriäinen malja, josta sekoviini älköön puuttuko; sinun uumasi on nisukeko, liljojen ympäröimä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Sinun rintasi ovat kuin kaksi nuorta peuraa, kuin gasellin kaksoiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Sinun kaulasi on kuin norsunluinen torni. Sinun silmäsi kuin Hesbonin lammikot Bat-Rabbimin portin luona; sinun nenäsi on kuin Libanonin torni, joka katsoo Damaskoon päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Sinun pääsi kohoaa kuin Karmel, sinun pääsi palmikot ovat kuin purppura; niihin pauloihin on kuningas kiedottu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, '\"Kuinka kaunis olet, kuinka suloinen, sinä rakkaus, riemuinesi! -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Sinun vartesi on kuin palmupuu, ja sinun rintasi niinkuin rypäleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Minä ajattelin: nousen palmupuuhun, tartun sen oksiin; olkoot silloin rintasi niinkuin viinirypäleet ja henkesi tuoksu kuin omenain tuoksu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'Ja olkoon suusi kuin jalo viini.\" \"Viini, joka helposti valahtaa rakkaaseeni ja kostuttaa nukkuvien huulet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Minä olen rakkaani oma, ja minuun on hänen halunsa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, '\"Tule, rakkaani, lähtekäämme maalle, kyliin yöpykäämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Käykäämme varhain viinitarhoihin katsomaan, joko viiniköynnös versoo ja ummut aukeavat, joko kukkivat granaattipuut. Siellä annan sinulle rakkauteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, '(/:14) Lemmenmarjat tuoksuavat, ja oviemme edessä kasvavat kaikkinaiset kalliit hedelmät, uudet ja vanhat: sinulle, rakkaani, olen ne säästänyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, '\"Olisitpa kuin oma veljeni, äitini rintoja imenyt! Tapaisin sinut ulkona, sinua suutelisin, eikä minua kukaan halveksuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Minä johdattaisin sinut, veisin äitini taloon, ja hän neuvoisi minua. Minä antaisin mausteviiniä juodaksesi, granaattiomenani mehua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Hänen vasen kätensä on minun pääni alla, ja hänen oikea kätensä halaa minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Minä vannotan teitä, te Jerusalemin tyttäret: älkää herätelkö, älkää häiritkö rakkautta, ennenkuin se itse haluaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Kuka tuolla tulee erämaasta rakkaaseensa nojaten? \"Omenapuun alla sinut herätin. Siellä sai sinut äitisi kerran, siellä sai sinut emosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Pane minut sinetiksi sydämellesi, sinetiksi käsivarrellesi. Sillä rakkaus on väkevä kuin kuolema, tuima kuin tuonela on sen kiivaus, sen hehku on tulen hehku, on Herran liekki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Eivät suuret vedet voi rakkautta sammuttaa, eivät virrat sitä tulvaansa upottaa. Jos joku tarjoaisi kaikki talonsa tavarat rakkauden hinnaksi, häntä vain halveksuttaisiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, '\"Meillä on pieni sisko, jolla ei vielä ole rintoja. Mitä teemme siskollemme sinä päivänä, jona häntä kysytään?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Jos hän on muuri, rakennamme sille hopeasta harjan; jos hän on ovi, sen setrilaudalla suljemme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, '\"Minä olen muuri, ja rintani ovat kuin tornit; vaan nyt olen hänen silmissään niinkuin antautuvainen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, '\"Salomolla on viinitarha Baal-Haamonissa; hän on jättänyt viinitarhan vartijoiden huostaan; sen hedelmistä saisi tuhat hopeasekeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Minun viinitarhani on minun omassa hallussani. Sinulle, Salomo, tulkoot ne tuhat, ja sen hedelmän vartijoille kaksisataa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, '\"Sinä yrttitarhain asujatar, toverit kuuntelevat ääntäsi; anna minun sitä kuulla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, '\"Riennä, rakkaani, kuin gaselli, kuin nuori peura balsamivuorille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Jesajan, Aamoksen pojan, näky, jonka hän näki Juudasta ja Jerusalemista Ussian, Jootamin, Aahaan ja Hiskian, Juudan kuningasten, päivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Kuulkaa, taivaat, ota korviisi, maa, sillä Herra puhuu: Minä kasvatin lapsia, sain heidät suuriksi, mutta he luopuivat minusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Härkä tuntee omistajansa ja aasi isäntänsä seimen; mutta Israel ei tunne, minun kansani ei ymmärrä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Voi syntistä sukua, raskaasti rikkonutta kansaa, pahantekijäin siementä, kelvottomia lapsia! He ovat hyljänneet Herran, pitäneet Israelin Pyhää pilkkanansa, he ovat kääntyneet pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Mihin pitäisi teitä vielä lyödä, kun yhä jatkatte luopumustanne? Koko pää on kipeä, koko sydän sairas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Kantapäästä kiireeseen asti ei ole tervettä paikkaa, ainoastaan haavoja, mustelmia ja vereksiä lyömiä, joita ei ole puserrettu, ei sidottu eikä öljyllä pehmitetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Teidän maanne on autiona, teidän kaupunkinne ovat tulella poltetut; teidän peltojanne syövät muukalaiset silmäinne edessä; ne ovat autioina niinkuin ainakin muukalaisten hävittämät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Jäljellä on tytär Siion yksinänsä niinkuin maja viinitarhassa, niinkuin lehvämaja kurkkumaassa, niinkuin saarrettu kaupunki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Ellei Herra Sebaot olisi jättänyt meistä jäännöstä, olisi meidän käynyt pian kuin Sodoman, olisimme tulleet Gomorran kaltaisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Kuulkaa Herran sana, te Sodoman päämiehet, ota korviisi meidän Jumalamme opetus, sinä Gomorran kansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Mitä ovat minulle teidän paljot teurasuhrinne? sanoo Herra. Minä olen kyllästynyt oinas-polttouhreihin ja juottovasikkain rasvaan. Mullikkain, karitsain ja kauristen vereen minä en mielisty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Kun te tulette minun kasvojeni eteen, kuka sitä teiltä vaatii-minun esikartanoitteni tallaamista?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Älkää enää tuoko minulle turhaa ruokauhria; suitsutus on minulle kauhistus. En kärsi uuttakuuta enkä sapattia, en kokouksen kuuluttamista, en vääryyttä ynnä juhlakokousta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Minun sieluni vihaa teidän uusiakuitanne ja juhla-aikojanne; ne ovat käyneet minulle kuormaksi, jota kantamaan olen väsynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Kun te ojennatte käsiänne, minä peitän silmäni teiltä; vaikka kuinka paljon rukoilisitte, minä en kuule: teidän kätenne ovat verta täynnä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Peseytykää, puhdistautukaa; pankaa pois pahat tekonne minun silmäini edestä, lakatkaa pahaa tekemästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Oppikaa tekemään hyvää; harrastakaa oikeutta, ojentakaa väkivaltaista, hankkikaa orvolle oikeus, ajakaa lesken asiaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Niin tulkaa, käykäämme oikeutta keskenämme, sanoo Herra. Vaikka teidän syntinne ovat veriruskeat, tulevat ne lumivalkeiksi; vaikka ne ovat purppuranpunaiset, tulevat ne villanvalkoisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Jos suostutte ja olette kuuliaiset, niin te saatte syödä maan hyvyyttä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'mutta jos vastustatte ja niskoittelette, niin miekka syö teidät. Sillä Herran suu on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Voi, kuinka onkaan portoksi tullut uskollinen kaupunki! Se oli täynnä oikeutta, siellä asui vanhurskaus, mutta nyt murhamiehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Sinun hopeasi on kuonaksi käynyt, jaloviinisi vedellä laimennettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Sinun päämiehesi ovat niskureita ja varkaiden tovereita; kaikki he lahjuksia rakastavat ja palkkoja tavoittelevat; eivät he hanki orvolle oikeutta, lesken asia ei pääse heidän eteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Sentähden sanoo Herra, Herra Sebaot, Israelin Väkevä: Voi! Minä viihdytän vihani vastustajissani, minä kostan vihollisilleni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'minä käännän käteni sinua vastaan ja puhdistan sinusta kuonan niinkuin lipeällä ja poistan sinusta kaiken lyijyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Ja minä palautan sinun tuomarisi muinaiselleen ja sinun neuvonantajasi sellaisiksi, kuin alkuaan olivat. Sitten sinua kutsutaan \"vanhurskauden linnaksi\", \"uskolliseksi kaupungiksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Siion lunastetaan oikeudella ja sen kääntyneet vanhurskaudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Mutta luopiot ja syntiset saavat kaikki turmion, ja ne, jotka hylkäävät Herran, hukkuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Sillä he saavat häpeän niistä tammista, joita te himoitsitte, ja pettymyksen puutarhoista, jotka te valitsitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Sillä teidän käy kuin tammen, jonka lehdet lakastuvat, ja kuin puutarhan, joka on vailla vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Ja mahtaja tulee rohtimeksi ja hänen tekonsa kipinäksi, ja molemmat palavat yhdessä, eikä ole sammuttajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Sana, jonka Jesaja, Aamoksen poika, näki Juudasta ja Jerusalemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Aikojen lopussa on Herran temppelin vuori seisova vahvana, ylimmäisenä vuorista, kukkuloista korkeimpana, ja kaikki pakanakansat virtaavat sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Monet kansat lähtevät liikkeelle sanoen: \"Tulkaa, nouskaamme Herran vuorelle, Jaakobin Jumalan temppeliin, että hän opettaisi meille teitänsä ja me vaeltaisimme hänen polkujansa; sillä Siionista lähtee laki, Jerusalemista Herran sana\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Ja hän tuomitsee pakanakansojen kesken, säätää oikeutta monille kansoille. Niin he takovat miekkansa vantaiksi ja keihäänsä vesureiksi; kansa ei nosta miekkaa kansaa vastaan, eivätkä he enää opettele sotimaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Jaakobin heimo, tulkaa, vaeltakaamme Herran valkeudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Sillä sinä olet hyljännyt kansasi, Jaakobin heimon, koska he ovat täynnä Idän menoa, täynnä ennustelijoita niinkuin filistealaiset, ja lyövät kättä muukalaisten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Heidän maansa tuli täyteen hopeata ja kultaa, eikä heidän aarteillaan ole määrää; heidän maansa tuli täyteen hevosia, eikä heidän vaunuillaan ole määrää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Heidän maansa tuli täyteen epäjumalia, he kumartavat kättensä tekoa, sitä, minkä heidän sormensa ovat tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Silloin ihminen masentuu ja mies painuu maahan, mutta älä anna heille anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Mene kallion kätköön, piiloudu maan peittoon Herran kauhua ja hänen valtansa kirkkautta pakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Ihmisten ylpeät silmät painuvat maahan, miesten korskeus masentuu, ja sinä päivänä Herra yksinänsä on korkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Sillä Herran Sebaotin päivä kohtaa kaikkea ylpeää ja korskeata ja kaikkea ylhäistä, niin että se maahan painuu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'kaikkia Libanonin setripuita, noita korkeita ja ylhäisiä, kaikkia Baasanin tammia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'kaikkia korkeita vuoria ja kaikkia ylhäisiä kukkuloita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'kaikkia korkeita torneja ja kaikkia vahvoja muureja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'kaikkia Tarsiin-laivoja ja kaikkea kallista ja ihanaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Silloin masentuu ihmisten ylpeys, ja miesten korskeus painuu maahan, ja sinä päivänä Herra yksinänsä on korkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Mutta epäjumalat katoavat kaikki tyynni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Silloin mennään kallioluoliin ja maakuoppiin Herran kauhua ja hänen valtansa kirkkautta pakoon, kun hän nousee maata kauhistuttamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Sinä päivänä ihmiset viskaavat pois myyrille ja yököille hopea-ja kultajumalansa, jotka he ovat tehneet kumarrettaviksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'Ja he menevät vuorenrotkoihin ja kallionkoloihin Herran kauhua ja hänen valtansa kirkkautta pakoon, kun hän nousee maata kauhistuttamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Luopukaa siis ihmisistä, joilla on vain henkäys sieraimissa, sillä minkä arvoiset he ovat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Sillä katso, Herra, Herra Sebaot ottaa pois Jerusalemilta ja Juudalta varan ja turvan, kaiken leivänvaran ja kaiken vedenvaran,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'sankarin ja soturin, tuomarin ja profeetan, tietäjän ja vanhimman,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'viidenkymmenenpäämiehen ja arvomiehen, neuvonantajan, taitoniekan ja taikurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Ja minä panen nuorukaiset heille päämiehiksi, ja pahankuriset hallitsevat heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Kansassa sortaa kukin toistaan, jokainen lähimmäistään; nuorukainen rehentelee vanhusta vastaan, halpa-arvoinen arvollista vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Kun veli tarttuu veljeensä isänsä talossa sanoen: \"Sinulla on vielä vaatteet, rupea ruhtinaaksemme ja ota huostaasi tämä raunioläjä\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'niin tämä sinä päivänä korottaa äänensä sanoen: \"Ei minusta ole haavoja sitomaan; ei ole minun talossani leipää, ei vaatetta, älkää panko minua kansan ruhtinaaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Sillä Jerusalem kaatuu ja Juuda kukistuu, koska heidän kielensä ja heidän tekonsa ovat Herraa vastaan ja he uhittelevat hänen kunniansa kasvoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Heidän kasvojensa hahmo todistaa heitä vastaan; syntinsä he tuovat julki niinkuin sodomalaiset, he eivät niitä salaa. Voi heitä! Itsellensä he pahaa tekevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Sanokaa hurskaasta, että hänen käy hyvin, sillä he saavat nauttia tekojensa hedelmiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Voi jumalatonta! Hänen käy pahoin, sillä hänen kättensä teot maksetaan hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Minun kansani käskijät ovat lapsia, ja naiset sitä hallitsevat. Kansani, sinun johtajasi ovat eksyttäjiä, he ovat hämmentäneet sinun polkujesi suunnan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Herra asettuu käymään oikeutta, nousee kansoja tuomitsemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Herra käy tuomiolle kansansa vanhinten ja sen päämiesten kanssa: Te olette raiskanneet viinitarhan; teidän taloissanne on kurjilta ryöstettyä tavaraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Kuinka saatatte runnella minun kansaani ja ruhjoa kurjien kasvot? sanoo Herra, Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Ja Herra sanoi: Koska Siionin tyttäret korskeilevat, kulkevat kaula kenossa ja silmillään vilkuillen, astua sipsuttelevat ja nilkkarenkaitaan kilistelevät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'tekee Herra Siionin tytärten päälaen rupiseksi, ja Herra paljastaa heidän häpynsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Sinä päivänä Herra poistaa koreat nilkkarenkaat, otsanauhat, puolikuukorut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'korvarenkaat, rannerenkaat, hunnut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'juhlapäähineet, jalkakäädyt, koruvyöt, hajupullot, taikahelyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'sormukset, nenärenkaat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'juhlavaatteet, kaavut, vaipat, kukkarot,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'kuvastimet, aivinapaidat, käärelakit ja päällysharsot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Silloin tulee tuoksun sijaan löyhkä, vyön sijaan nuora, käherretyn tukan sijaan kaljuus, korupuvun sijaan säkkiverho, kauneuden sijaan polttomerkki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Sinun miehesi kaatuvat miekkaan ja sinun sankarisi sotaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Ja Siionin portit valittavat ja vaikeroivat, ja typötyhjänä hän istuu maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Sinä päivänä seitsemän naista tarttuu yhteen mieheen sanoen: \"Me syömme omaa leipäämme ja vaatetamme itsemme omilla vaatteilla, kunhan vain meidät otetaan sinun nimiisi; poista meidän häpeämme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'Sinä päivänä on Herran vesa oleva Israelin pelastuneille kaunistus ja kunnia ja maan hedelmä heille korkeus ja loisto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Ja ne, jotka Siionissa ovat säilyneet ja Jerusalemissa jäljelle jääneet, kutsutaan pyhiksi, kaikki, jotka ovat kirjoitetut Jerusalemissa elävien lukuun-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'silloin kun Herra on pessyt pois Siionin tytärten saastan ja huuhtonut Jerusalemista sen verenviat tuomion ja puhdistuksen hengellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Ja Herra luo Siionin vuorelle koko asuinsijansa ylle ja sen juhlakokousten ylle pilven päivän ajaksi ja savun ynnä tulenliekin hohteen yöksi, sillä kaiken kirkkauden yllä on oleva peite');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'ja verho varjoamassa päivän helteeltä sekä turvaamassa ja suojaamassa rajuilmalta ja sateelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Minä laulan ystävästäni, laulan rakkaani laulun hänen viinitarhastaan. Ystävälläni oli viinitarha lihavalla vuorenrinteellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Hän kuokki ja kivesi sen ja istutti siihen jaloja köynnöksiä, rakensi sen keskelle tornin ja hakkasi sinne myös kuurnan. Ja hän odotti sen kasvavan rypäleitä, mutta se kasvoi villimarjoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Ja nyt, te Jerusalemin asukkaat ja Juudan miehet, tuomitkaa minun ja minun viinitarhani välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Mitä olisi viinitarhalleni vielä ollut tehtävä, jota en olisi sille tehnyt? Miksi se kasvoi villimarjoja, kun minä odotin sen kasvavan rypäleitä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Mutta nyt minä ilmoitan teille, mitä teen viinitarhalleni: minä poistan siitä aidan, niin että se jää hävitettäväksi, särjen siitä muurin, niin että se jää tallattavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Minä hävitän sen: ei sitä enää vesota eikä kuokita, vaan se on kasvava ohdaketta ja orjantappuraa, ja minä kiellän pilvet sille vettä satamasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Sillä Israelin heimo on Herran Sebaotin viinitarha, ja Juudan miehet ovat hänen ilo-istutuksensa. Ja hän odotti oikeutta, mutta katso, tuli oikeuttomuus, ja vanhurskautta, mutta katso, tuli vaikerrus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Voi niitä, jotka liittävät talon taloon, yhdistävät pellon peltoon, kunnes ei jää enää tilaa ja te yksin asutte maassa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Minun korviini kuului Herran Sebaotin sana: Totisesti, ne monet talot tulevat autioiksi, ne suuret ja kauniit asujattomiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Sillä kymmenen auranalaa viinitarhaa on antava yhden bat-mitan, ja hoomerin kylvö on antava eefan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Voi niitä, jotka aamuvarhaisesta väkijuoman jäljessä juoksevat ja iltamyöhään viipyvät viinistä hehkuvina!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Kanteleet, harput, vaskirummut, huilut ja viinit on heillä pidoissansa, mutta Herran tekoja he eivät tarkkaa, eivät näe hänen kättensä töitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Sentähden minun kansani siirretään maastansa äkkiarvaamatta, sen ylhäiset kärsivät nälkää, ja sen remuava joukko nääntyy janoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Sentähden tuonela levittää kitansa ammolleen, avaa suunsa suunnattomaksi; ja sinne menee sen loisto, sen remuava ja pauhaava joukko, kaikki sen ilonpitäjät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Silloin ihminen masentuu ja mies painuu maahan, maahan painuvat ylpeitten silmät;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'mutta Herra Sebaot on oleva korkea tuomiossa, pyhä Jumala on oleva pyhä vanhurskaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Ja karitsat käyvät siellä niinkuin laitumillansa, ja vieraat syöttävät rikkaitten rauniosijoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Voi niitä, jotka vetävät perässänsä rangaistusta turhuuden köysillä, synnin palkkaa kuin vaunujen valjailla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'niitä, jotka sanovat: \"Joutukoon pian hänen tekonsa, että me sen näemme; täyttyköön ja tapahtukoon Israelin Pyhän aivoitus, että me sen tiedämme!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Voi niitä, jotka sanovat pahan hyväksi ja hyvän pahaksi, jotka tekevät pimeyden valkeudeksi ja valkeuden pimeydeksi, jotka tekevät karvaan makeaksi ja makean karvaaksi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Voi niitä, jotka ovat viisaita omissa silmissään ja ymmärtäväisiä omasta mielestänsä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Voi niitä, jotka ovat urhoja viinin juonnissa ja aimomiehiä väkijuoman sekoittamisessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'jotka lahjuksesta julistavat syyllisen syyttömäksi ja ottavat oikeuden siltä, joka oikeassa on!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Sentähden, niinkuin tulen kieli syö oljet ja kuloheinä raukeaa liekkiin, niin heidän juurensa mätänee, ja heidän kukkansa hajoaa tomuna ilmaan, sillä he ovat ylenkatsoneet Herran Sebaotin lain ja pitäneet pilkkanansa Israelin Pyhän sanaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Sentähden syttyi Herran viha hänen kansaansa kohtaan: hän ojensi kätensä sitä vastaan ja löi sitä, niin että vuoret vapisivat ja heidän raatonsa olivat tunkiona keskellä katuja. Tästä kaikesta ei hänen vihansa asettunut, vaan hänen kätensä on vielä ojennettuna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Ja hän pystyttää viirin kaukaiselle kansalle ja viheltää sen luokseen maan äärestä. Ja katso, se tulee viipymättä, nopeasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Ei kukaan heistä väsy eikä kompastu, ei kukaan torku eikä nuku, ei vyö kupeilta aukene, eikä kengänpaula katkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Sen nuolet ovat teroitetut, sen jouset kaikki jännitetyt, sen orhien kaviot ovat kuin pii, ja sen rattaat kuin rajuilma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Sen kiljunta on kuin naarasleijonan, se kiljuu kuin nuoret jalopeurat, se ärjyy ja tempaa saaliin ja vie sen pois, eikä pelastajaa ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Se ärjyy sille sinä päivänä, niinkuin meri ärjyy. Silloin tähyillään maata, mutta katso, on pimeys, on ahdistus, ja valo on pimennyt sen synkeyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Kuningas Ussian kuolinvuotena minä näin Herran istuvan korkealla ja ylhäisellä istuimella, ja hänen vaatteensa liepeet täyttivät temppelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Serafit seisoivat hänen ympärillään; kullakin oli kuusi siipeä: kahdella he peittivät kasvonsa, kahdella he peittivät jalkansa, ja kahdella he lensivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Ja he huusivat toinen toisellensa ja sanoivat: \"Pyhä, pyhä, pyhä Herra Sebaot; kaikki maa on täynnä hänen kunniaansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Ja kynnysten perustukset vapisivat heidän huutonsa äänestä, ja huone täyttyi savulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Niin minä sanoin: \"Voi minua! Minä hukun, sillä minulla on saastaiset huulet, ja minä asun kansan keskellä, jolla on saastaiset huulet; sillä minun silmäni ovat nähneet kuninkaan, Herran Sebaotin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Silloin lensi minun luokseni yksi serafeista, kädessään hehkuva kivi, jonka hän oli pihdeillä ottanut alttarilta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'ja kosketti sillä minun suutani sanoen: \"Katso, tämä on koskettanut sinun huuliasi; niin on sinun velkasi poistettu ja syntisi sovitettu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Ja minä kuulin Herran äänen sanovan: \"Kenenkä minä lähetän? Kuka menee meidän puolestamme?\" Minä sanoin: \"Katso, tässä minä olen, lähetä minut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Niin hän sanoi: \"Mene ja sano tälle kansalle: \'Kuulemalla kuulkaa, älkääkä ymmärtäkö, näkemällä nähkää, älkääkä käsittäkö\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Paaduta tämän kansan sydän, koveta sen korvat, sokaise sen silmät, ettei se näkisi silmillään, ei kuulisi korvillaan, ei ymmärtäisi sydämellään eikä kääntyisi ja parannetuksi tulisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Mutta minä sanoin: \"Kuinka kauaksi aikaa, Herra?\" Hän vastasi: \"Siihen asti, kunnes kaupungit tulevat autioiksi, asumattomiksi, ja talot tyhjiksi ihmisistä ja pellot on hävitetty erämaaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'kunnes Herra on karkoittanut ihmiset kauas ja suuri autius tullut keskelle maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Ja jos siellä on jäljellä kymmenes osa, niin hävitetään vielä sekin. Mutta niinkuin tammesta ja rautatammesta jää kaadettaessa kanto, niin siitäkin: se kanto on pyhä siemen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Aahaan, Jootamin pojan, Ussian pojanpojan, Juudan kuninkaan, aikana lähtivät Resin, Aramin kuningas, ja Pekah, Remaljan poika, Israelin kuningas, sotimaan Jerusalemia vastaan, mutta he eivät voineet valloittaa sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Ja kun Daavidin huoneelle ilmoitettiin sanoma: \"Aram on leiriytynyt Efraimiin\", niin kuninkaan ja hänen kansansa sydän vapisi, niinkuin metsän puut vapisevat tuulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Silloin Herra sanoi Jesajalle: \"Mene Aahasta vastaan, sinä ja sinun poikasi Sear-Jaasub, Ylälammikon vesijohdon päähän, Vanuttajankedon tielle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'ja sano hänelle: Ole varuillasi ja pysy rauhallisena, älä pelkää, älköönkä sydämesi säikkykö noita kahta savuavaa kekäleenpätkää: Resinin ja Aramin ynnä Remaljan pojan vihanvimmaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Koska Aram, Efraim ja Remaljan poika ovat hankkineet pahaa sinua vastaan sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, '\'Lähtekäämme Juudaa vastaan, täyttäkäämme se kauhulla, vallatkaamme se itsellemme ja asettakaamme sinne kuninkaaksi Taabalin poika\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'niin sanoo Herra, Herra näin: Ei se onnistu, eikä se tapahdu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Sillä Aramin pää on Damasko, ja Damaskon pää on Resin-mutta kuusikymmentä viisi vuotta vielä, ja Efraim on muserrettu eikä ole enää kansa-ja Efraimin pää on Samaria,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'ja Samarian pää on Remaljan poika. Ellette usko, niin ette kestä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Ja Herra puhui jälleen Aahaalle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, '\"Pyydä itsellesi merkki Herralta, Jumalaltasi, pyydä alhaalta syvyydestä taikka ylhäältä korkeudesta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Mutta Aahas vastasi: \"En pyydä enkä kiusaa Herraa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Siihen hän lausui: \"Kuulkaa, te Daavidin suku, eikö se riitä, että te ihmiset väsytätte, kun vielä minun Jumalanikin itseenne väsytätte?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Sentähden Herra itse antaa teille merkin: Katso, neitsyt tulee raskaaksi ja synnyttää pojan ja antaa hänelle nimen Immanuel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Voita ja hunajaa hän syö siinä iässä, jolloin hän oppii hylkäämään pahan ja valitsemaan hyvän;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'sillä ennenkuin poika on oppinut hylkäämään pahan ja valitsemaan hyvän, tulee autioksi maa, jonka kahta kuningasta sinä kauhistut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Herra antaa tulla sinulle, sinun kansallesi ja isäsi suvulle ne päivät, joita ei ole ollut siitä asti, kun Efraim luopui Juudasta-antaa tulla Assurin kuninkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Ja sinä päivänä Herra viheltää kärpäset Egyptin virtain suulta ja mehiläiset Assurin maasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'ja ne tulevat ja laskeutuvat kaikki vuorenrotkoihin ja kallionkoloihin, kaikkiin orjantappurapensaisiin ja kaikille juottopaikoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Sinä päivänä Herra ajattaa virran tuolta puolen palkatulla partaveitsellä, Assurin kuninkaalla, pään ja häpykarvat; viepä se vielä parrankin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Siihen aikaan pitää mies lehmäsen ja pari lammasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'mutta runsaan maidon tulon tähden hän syö voita; sillä voita ja hunajaa syövät kaikki maahan jäljelle jääneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Ja siihen aikaan jokainen paikka, jossa kasvaa tuhat viinipuuta, arvoltaan tuhat hopeasekeliä, joutuu orjantappurain ja ohdakkeiden valtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Sinne on mentävä nuolet ja jousi mukana, sillä koko maa on pelkkää orjantappuraa ja ohdaketta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Ei yhdellekään niistä vuorista, joita nyt kuokalla kuokitaan, enää mennä orjantappurain ja ohdakkeiden pelosta; ne jäävät härkien laitumeksi ja lammasten tallattavaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Ja Herra sanoi minulle: \"Ota iso taulu ja kirjoita siihen selkeällä kirjoituksella: Maher-Saalal Haas-Bas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Ja minä otan itselleni luotettavat todistajat, pappi Uurian ja Sakarjan, Jeberekjan pojan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Sitten minä lähestyin profeetta-vaimoani, ja hän tuli raskaaksi ja synnytti pojan. Niin Herra sanoi minulle: \"Pane hänelle nimeksi Maher-Saalal Haas-Bas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Sillä ennenkuin poika oppii sanomaan: \'isä\' ja \'äiti\', viedään Damaskoon tavarat ja Samarian saalis Assurin kuninkaan eteen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Ja Herra puhui jälleen minulle ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, '\"Koska tämä kansa halveksii Siiloan hiljaa virtaavia vesiä ja iloitsee Resinin ja Remaljan pojan kanssa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'niin katso, sentähden Herra antaa tulla heidän ylitsensä virran vedet, valtavat ja suuret: Assurin kuninkaan ja kaiken hänen kunniansa; se nousee kaikkien uomiensa yli ja menee kaikkien äyräittensä yli,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'ja se tunkeutuu Juudaan, paisuu ja tulvii ja ulottuu kaulaan saakka. Ja levittäen siipensä se täyttää yliyltään sinun maasi, Immanuel.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Riehukaa, kansat, kuitenkin kukistutte; kuulkaa, kaikki kaukaiset maat: sonnustautukaa, kuitenkin kukistutte; sonnustautukaa, kuitenkin kukistutte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Pitäkää neuvoa: se raukeaa; sopikaa sopimus: ei se pysy. Sillä Jumala on meidän kanssamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Sillä näin sanoi minulle Herra, kun hänen kätensä valtasi minut ja hän varoitti minua vaeltamasta tämän kansan tietä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, '\"Älkää sanoko salaliitoksi kaikkea, mitä tämä kansa salaliitoksi sanoo; älkää peljätkö, mitä se pelkää, älkääkä kauhistuko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Herra Sebaot pitäkää pyhänä, häntä te peljätkää ja kauhistukaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Ja hän on oleva pyhäkkö, hän loukkauskivi ja kompastuksen kallio molemmille Israelin huonekunnille, paula ja ansa Jerusalemin asukkaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Monet heistä kompastuvat ja kaatuvat ja ruhjoutuvat, monet kiedotaan ja vangitaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Sido todistus talteen, lukitse laki sinetillä minun opetuslapsiini.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Niin minä odotan Herraa, joka kätkee kasvonsa Jaakobin heimolta, ja panen toivoni häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Katso, minä ja lapset, jotka Herra on minulle antanut, me olemme Herran Sebaotin merkkeinä ja ihmeinä Israelissa, hänen, joka asuu Siionin vuorella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Ja kun he sanovat teille: \"Kysykää vainaja-ja tietäjähengiltä, jotka supisevat ja mumisevat\", niin eikö kansa kysyisi Jumalaltansa? Kuolleiltako elävien puolesta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, '\"Pysykää laissa ja todistuksessa!\" Elleivät he näin sano, ei heillä aamunkoittoa ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Ja siellä he kuljeskelevat vaivattuina ja nälkäisinä, ja nälissään he vimmastuvat ja kiroavat kuninkaansa ja Jumalansa. He luovat silmänsä korkeuteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'he katsahtavat maan puoleen, mutta katso: ainoastaan ahdistusta ja pimeyttä; he ovat syöstyt tuskan synkeyteen ja pimeyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, '{8:23} Mutta ei jää pimeään se, mikä nyt on vaivan alla. Entiseen aikaan hän saattoi halveksituksi Sebulonin maan ja Naftalin maan, mutta tulevaisuudessa hän saattaa kunniaan merentien, Jordanin tuonpuoleisen maan, pakanain alueen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, '{9:1} Kansa, joka pimeydessä vaeltaa, näkee suuren valkeuden; jotka asuvat kuoleman varjon maassa, niille loistaa valkeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, '{9:2} Sinä lisäät kansan, annat sille suuren ilon; he iloitsevat sinun edessäsi, niinkuin elonaikana iloitaan, niinkuin saaliinjaossa riemuitaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, '{9:3} Sillä heidän kuormansa ikeen, heidän olkainsa vitsan ja heidän käskijänsä sauvan sinä särjet niinkuin Midianin päivänä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, '{9:4} ja kaikki taistelun pauhussa tallatut sotakengät ja verellä tahratut vaipat poltetaan ja tulella kulutetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, '{9:5} Sillä lapsi on meille syntynyt, poika on meille annettu, jonka hartioilla on herraus, ja hänen nimensä on: Ihmeellinen neuvonantaja, Väkevä Jumala, Iankaikkinen isä, Rauhanruhtinas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, '{9:6} Herraus on oleva suuri ja rauha loppumaton Daavidin valtaistuimella ja hänen valtakunnallansa; se perustetaan ja vahvistetaan tuomiolla ja vanhurskaudella nyt ja iankaikkisesti. Herran Sebaotin kiivaus on sen tekevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, '{9:7} Herra lähetti sanan Jaakobia vastaan, ja se iski Israeliin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, '{9:8} ja sen sai tuntea koko kansa, Efraim ja Samarian asukkaat, mutta he sanoivat ylpeydessään ja sydämensä kopeudessa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, '{9:9} \"Tiilikivet sortuivat maahan, mutta me rakennamme hakatuista kivistä; metsäviikunapuut lyötiin poikki, mutta me panemme setripuita sijaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, '{9:10} Silloin Herra nostatti sitä vastaan Resinin ahdistajat ja kiihoitti sen viholliset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, '{9:11} aramilaiset edestä ja filistealaiset takaa, ja he söivät Israelia suun täydeltä. Kaikesta tästä ei hänen vihansa ole asettunut, ja vielä on hänen kätensä ojennettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, '{9:12} Mutta kansa ei palannut kurittajansa tykö, eivätkä he etsineet Herraa Sebaotia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, '{9:13} Sentähden Herra katkaisi Israelilta pään ja hännän, palmunlehvän ja kaislan, yhtenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, '{9:14} Vanhin ja arvomies on pää, mutta profeetta, joka valhetta opettaa, on häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, '{9:15} Ja tämän kansan johtajat tulivat eksyttäjiksi, ja johdettavat joutuivat hämminkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, '{9:16} Sentähden Herra ei iloitse sen nuorista miehistä eikä armahda sen orpoja ja leskiä, sillä he ovat kaikki jumalattomia ja pahantekijöitä, ja jokainen suu puhuu hulluutta. Kaikesta tästä ei hänen vihansa ole asettunut, ja vielä on hänen kätensä ojennettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, '{9:17} Sillä jumalattomuus palaa tulena, kuluttaa orjantappurat ja ohdakkeet ja sytyttää sankan metsän, niin että se savuna tupruaa ilmaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, '{9:18} Herran Sebaotin vihasta maa syttyy palamaan, ja kansa on kuin tulen syötävänä; toinen ei sääli toistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, '{9:19} Ahmivat oikealta, mutta on yhä nälkä, syövät vasemmalta, mutta eivät saa kylläänsä; jokainen syö oman käsivartensa lihaa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, '{9:20} Manasse Efraimia ja Efraim Manassea, molemmat yhdessä käyvät Juudan kimppuun. Kaikesta tästä ei hänen vihansa ole asettunut, ja vielä on hänen kätensä ojennettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Voi niitä, jotka vääriä säädöksiä säätävät, jotka turmiollisia tuomioita kirjoittelevat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'vääntääksensä vaivaisten asian ja riistääksensä minun kansani kurjilta oikeuden, että lesket joutuisivat heidän saaliiksensa ja orvot heidän ryöstettäviksensä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Mutta mitä te teette koston päivänä, rajumyrskyssä, joka tulee kaukaa? Kenen turviin pakenette apua saamaan ja minne talletatte tavaranne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Ei muuta kuin vaipua vangittujen joukkoon tai kaatua surmattujen sekaan. Kaikesta tästä ei hänen vihansa ole asettunut, ja vielä on hänen kätensä ojennettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Voi Assuria, joka on minun vihani vitsa ja jolla on kädessään minun suuttumukseni sauva!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Minä lähetän hänet jumalattoman kansakunnan kimppuun, käsken hänet vihastukseni kansaa vastaan saalista saamaan ja ryöstöä ryöstämään ja tallaamaan sitä kuin katujen lokaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Mutta hän ei ajattele niin, se ei ole hänen sydämensä aivoitus, vaan hänen sydämensä halu on hävittää ja tuhota kansoja paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Sillä hän sanoo: \"Eivätkö minun päämieheni ole kaikki kuninkaita?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Eikö käynyt Kalnon niinkuin Karkemiin, eikö Hamatin niinkuin Arpadin ja Samarian niinkuin Damaskon?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Niinkuin minun käteni on saavuttanut epäjumalien valtakunnat, joiden jumalankuvat olivat paremmat kuin Jerusalemin ja Samarian-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'niin enkö minä tekisi Jerusalemille ja sen epäjumalankuville, samoin kuin minä tein Samarialle ja sen epäjumalille?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Mutta kun Herra on päättänyt kaiken työnsä Siionin vuorella ja Jerusalemissa, niin minä kostan Assurin kuninkaalle hänen sydämensä ylpeyden hedelmän ja hänen kopeitten silmiensä korskan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Sillä hän sanoo: \"Oman käteni voimalla minä sen tein ja viisaudellani, sillä minä olen ymmärtäväinen. Minä siirsin kansojen rajat ja ryöstin heidän aarteensa ja puskin kumoon kuin härkä valtaistuimella-istujat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Minun käteni tavoitti kansojen rikkaudet niinkuin linnun pesän; ja niinkuin hyljätyt munat kootaan, niin minä olen koonnut kaikki maat, eikä ketään ollut, joka olisi siipeä räpyttänyt tai nokkaa avannut ja piipittänyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Korskeileeko kirves hakkaajaansa vastaan, tai suurenteleeko saha heiluttajaansa vastaan? Ikäänkuin vitsa heiluttaisi kohottajaansa ja sauva saisi koholle sen, joka ei ole puuta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Sentähden Herra, Herra Sebaot, lähettää hänen lihavuuteensa näivetystaudin, ja hänen kunniansa alle syttyy tuli niinkuin tulipalo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Israelin valkeus on tuleva tuleksi ja hänen Pyhänsä liekiksi, joka polttaa ja kuluttaa hänen ohdakkeensa ja orjantappuransa yhtenä päivänä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'ja hänen metsänsä ja puutarhansa ihanuuden, hamaan luihin ja ytimiin, ja hän tulee riutuvan sairaan kaltaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'On helppo lukea ne puut, jotka jäävät hänen metsästänsä jäljelle; poikanen voi ne kirjoittaa muistiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Sinä päivänä ei Israelin jäännös eivätkä Jaakobin heimon pelastuneet enää turvaudu lyöjäänsä, vaan totuudessa he turvautuvat Herraan, Israelin Pyhään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Jäännös palajaa, Jaakobin jäännös, väkevän Jumalan tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Sillä vaikka sinun kansasi, Israel, olisi kuin meren hiekka, on siitä palajava ainoastaan jäännös. Päätetty on hävitys, joka tulee, vanhurskautta tulvillaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Sillä hävityksen ja tuomiopäätöksen panee Herra, Herra Sebaot, toimeen kaikessa maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Sentähden sanoo Herra, Herra Sebaot, näin: \"Älä pelkää, minun kansani, joka Siionissa asut, Assuria, kun hän sinua vitsalla lyö ja kohottaa sauvansa sinua vastaan Egyptin tavalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Sillä lyhyt hetki vielä, niin suuttumus täyttyy, ja minun vihani kääntyy hävittämään heidät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Ja Herra Sebaot heiluttaa ruoskaa häntä vastaan, niinkuin silloin, kun Midian lyötiin Oorebin kalliolla, ja hänen sauvansa on ojennettuna meren yli, ja hän kohottaa sen niinkuin muinoin Egyptiä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Sinä päivänä heltiää hänen kuormansa sinun hartioiltasi ja hänen ikeensä sinun niskaltasi, sillä ies särkyy lihavuuden pakosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Hän tulee Aijatiin, kulkee Migronin kautta, jättää kuormastonsa Mikmaaseen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'he kulkevat solatien poikki: \"Geba on yöpaikkamme\". Raama vapisee, Saulin Gibea pakenee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Huuda kimakasti, tytär Gallim! Kuuntele, Laisa! Poloinen Anatot!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena menee pakoon, Geebimin asukkaat saattavat tavaransa turviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Vielä samana päivänä hän pysähtyy Noobiin, hän kohottaa kätensä tytär Siionin vuorta, Jerusalemin kukkulaa, vastaan-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'katso, silloin Herra, Herra Sebaot, katkaisee hänen latvansa kauhistavalla voimalla, vartevat rungot kaadetaan, ja korkeat kukistuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Metsän tiheikkö hakataan kirveellä maahan, ja Libanon kaatuu Voimallisen edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Mutta Iisain kannosta puhkeaa virpi, ja vesa versoo hänen juuristansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Ja hänen päällänsä lepää Herran Henki, viisauden ja ymmärryksen henki, neuvon ja voiman henki, tiedon ja Herran pelon henki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Hän halajaa Herran pelkoa; ei hän tuomitse silmän näöltä eikä jaa oikeutta korvan kuulolta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'vaan tuomitsee vaivaiset vanhurskaasti ja jakaa oikein oikeutta maan nöyrille; suunsa sauvalla hän lyö maata, surmaa jumalattomat huultensa henkäyksellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Vanhurskaus on hänen kupeittensa vyö ja totuus hänen lanteittensa side.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Silloin susi asuu karitsan kanssa, ja pantteri makaa vohlan vieressä; vasikka ja nuori leijona ja syöttöhärkä ovat yhdessä, ja pieni poikanen niitä paimentaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Lehmä ja karhu käyvät laitumella, niiden vasikat ja pennut yhdessä makaavat, ja jalopeura syö rehua kuin raavas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Imeväinen leikittelee kyykäärmeen kololla, ja vieroitettu kurottaa kätensä myrkkyliskon luolaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Ei missään minun pyhällä vuorellani tehdä pahaa eikä vahinkoa, sillä maa on täynnä Herran tuntemusta, niinkuin vedet peittävät meren.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Sinä päivänä pakanat etsivät Iisain juurta, joka on kansojen lippuna, ja hänen asumuksensa on oleva kunniata täynnä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Ja sinä päivänä Herra vielä toisen kerran ojentaa kätensä hankkiakseen itselleen kansansa jäännöksen, joka on jäljellä Assurissa, Egyptissä, Patroksessa, Etiopiassa, Eelamissa, Sinearissa, Hamatissa ja merensaarilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Hän nostaa viirin pakanakansoille ja kokoaa Israelin karkoitetut miehet; ja Juudan hajoitetut naiset hän kerää maan neljästä äärestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Silloin katoaa Efraimin kateus, ja Juudan vihat häviävät. Efraim ei kadehdi Juudaa, eikä Juuda vihaa Efraimia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Ja he lentävät länteen päin filistealaisten niskaan, yhdessä he ryöstävät Idän miehiä. Edom ja Mooab joutuvat heidän käsiinsä, ammonilaiset heidän alamaisikseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Ja Herra vihkii tuhon omaksi Egyptin merenlahden ja vihansa hehkussa kohottaa kätensä Eufrat-virtaa vastaan, lyö sen hajalle seitsemäksi puroksi ja tekee sen kengin kuljettavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Siitä tulee valtatie hänen kansansa jäännökselle, joka on jäljellä Assurissa, niinkuin tuli Israelille silloin, kun se Egyptin maasta lähti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Sinä päivänä sinä sanot: \"Minä kiitän sinua, Herra, sillä sinä olit minuun vihastunut, mutta sinun vihasi asettui, ja sinä lohdutit minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Katso, Jumala on minun pelastukseni; minä olen turvassa enkä pelkää, sillä Herra, Herra on minun väkevyyteni ja ylistysvirteni, hän tuli minulle pelastukseksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Te saatte ilolla ammentaa vettä pelastuksen lähteistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Ja sinä päivänä te sanotte: \"Kiittäkää Herraa, julistakaa hänen nimeänsä, tehkää hänen suuret tekonsa tiettäviksi kansain keskuudessa, tunnustakaa, että hänen nimensä on korkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Veisatkaa ylistystä Herralle, sillä jaloja töitä hän on tehnyt; tulkoot ne tunnetuiksi kaikessa maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Huutakaa ja riemuitkaa, Siionin asukkaat, sillä suuri on teidän keskellänne Israelin Pyhä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Ennustus Baabelista, Jesajan, Aamoksen pojan, näkemä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Pystyttäkää viiri paljaalle vuoren laelle, korottakaa äänenne heille, viittokaa kädellä heitä menemään sisälle ruhtinasten porteista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Minä olen antanut käskyn vihkiytyneilleni ja kutsunut urhoni vihani työhön, ylvääni, riemuitsevaiseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Kuule, vuorilla käy kuin paljon väen pauhina; kuule valtakuntain, kokoontuneitten kansojen kohinaa: Herra Sebaot katsastaa sotajoukkoansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'He tulevat kaukaisesta maasta, taivaan ääristä, Herra ja hänen vihansa aseet, hävittämään kaiken maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Valittakaa, sillä Herran päivä on lähellä, se tulee kuin hävitys Kaikkivaltiaalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Sentähden herpoavat kaikki kädet, ja kaikki ihmissydämet raukeavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'He peljästyvät, kivut ja tuskat valtaavat heidät, he vääntelehtivät kuin synnyttäjä, tuijottavat toisiinsa tyrmistyneinä, kasvot tulenkarvaisina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Katso, Herran päivä tulee, tulee armottomana, tulee kiivaus ja vihan hehku, tekemään autioksi maan ja hävittämään siitä sen syntiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Sillä taivaan tähdet ja Kalevanmiekat eivät loista valollansa, aurinko on pimeä noustessansa, kuu ei kirkkaana kumota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Minä kostan maanpiirille sen pahuuden ja jumalattomille heidän pahat tekonsa; minä lopetan julkeitten kopeuden ja painan maahan väkivaltaisten ylpeyden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Minä teen kuolevaiset harvinaisemmiksi kuin puhdas kulta, ihmiset harvinaisemmiksi kuin Oofirin kulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Sentähden minä järisytän taivaat, ja maa järkkyy paikaltansa Herran Sebaotin kiivaudesta, hänen vihansa hehkun päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Ja niinkuin säikytetyt gasellit ja niinkuin lampaat, joilla ei ole kokoajaa, he kääntyvät kukin kansansa luo, pakenevat kukin omalle maallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Kuka ikinä tavataan, se lävistetään, kuka kiinni joutuu, se miekkaan kaatuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Heidän pienet lapsensa murskataan heidän silmäinsä edessä, heidän talonsa ryöstetään, ja heidän vaimonsa raiskataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Katso, minä herätän heitä vastaan meedialaiset, jotka eivät hopeasta huoli eivätkä kullasta välitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Heidän jousensa kaatavat nuoret miehet; he eivät armahda kohdun hedelmää eivätkä lapsia sääli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Ja Baabelin, valtakuntain kaunistuksen, kaldealaisten ylpeyden ja loiston, käy niinkuin Sodoman ja Gomorran, jotka Jumala hävitti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Ei sitä ikinä enää asuta, autioksi jää se polvesta polveen; ei arabialainen sinne telttaansa tee, eivätkä paimenet siellä laumaansa lepuuta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Erämaan eläimet lepäävät siellä, sen huoneet ovat täynnä huuhkajia, kamelikurjet asuvat siellä, ja metsänpeikot siellä hyppelevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Sakaalit ulvovat sen palatseissa, aavikkosudet huvilinnoissa. Sen aika on lähellä, tulemaisillaan, ei sen päiviä pidennetä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Sillä Herra armahtaa Jaakobia ja valitsee vielä Israelin ja sijoittaa heidät heidän omaan maahansa; muukalaiset liittyvät heihin ja yhtyvät Jaakobin heimoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Kansat ottavat heidät ja tuovat heidät heidän kotiinsa, ja Israelin heimo saa heidät Herran maassa omiksensa, orjiksi ja orjattariksi, ja he vangitsevat vangitsijansa ja vallitsevat käskijöitänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Ja sinä päivänä, jona Herra päästää sinut rauhaan vaivastasi, tuskastasi ja siitä kovasta työstä, jota sinulla teetettiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'sinä virität tämän pilkkalaulun Baabelin kuninkaasta ja sanot: \"Kuinka on käskijästä tullut loppu, tullut loppu ahdistuksesta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Herra on murtanut jumalattomain sauvan, valtiaitten vitsan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'joka kiukussa löi kansoja, löi lakkaamatta, joka vihassa vallitsi kansakuntia, vainosi säälimättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Kaikki maa on saanut levon ja rauhan, he puhkeavat riemuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Kypressitkin sinusta iloa pitävät sekä Libanonin setrit: \'Sinun maata mentyäsi ei nouse kukaan meitä hakkaamaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Tuonela tuolla alhaalla liikkuu sinun tähtesi, ottaaksensa sinut vastaan, kun tulet. Se herättää haamut sinun tähtesi, kaikki maan johtomiehet, nostattaa valtaistuimiltansa kaikki kansojen kuninkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Kaikki he lausuvat ja sanovat sinulle: \'Myös sinä olet riutunut niinkuin mekin, olet tullut meidän kaltaiseksemme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Alas tuonelaan on vaipunut sinun komeutesi, sinun harppujesi helinä; sinun allasi ovat vuoteena madot, toukat ovat peittonasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Kuinka olet taivaalta pudonnut, sinä kointähti, aamuruskon poika! Kuinka olet maahan syösty, sinä kansojen kukistaja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Sinä sanoit sydämessäsi: \'Minä nousen taivaaseen, korkeammalle Jumalan tähtiä minä istuimeni korotan ja istun ilmestysvuorelle, pohjimmaiseen Pohjolaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Minä nousen pilvien kukkuloille, teen itseni Korkeimman vertaiseksi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Mutta sinut heitettiin alas tuonelaan, pohjimmaiseen hautaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Jotka sinut näkevät, ne katsovat pitkään, tarkastavat sinua: \'Onko tämä se mies, joka järisytti maan, järkytti valtakunnat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'joka teki maanpiirin erämaaksi ja hävitti sen kaupungit, joka ei päästänyt vankejansa kotiin?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Kansojen kuninkaat kaikki lepäävät kunniassa, kukin kammiossansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Mutta sinä olet kaukana haudastasi, poisviskattuna niinkuin hylkyvesa, olet peittynyt surmattujen, miekalla lävistettyjen, kiviseen kuoppaan suistuneitten alle, olet kuin tallattu raato.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Et sinä saa yhtyä heidän kanssaan haudassa, sillä sinä olet maasi hävittänyt, kansasi tappanut. Ei ikinä enää mainita pahantekijäin sukua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Laittakaa hänen lapsillensa verilöyly heidän isiensä pahain tekojen tähden, etteivät he nousisi ottamaan omaksensa maata ja täyttäisi maanpiiriä kaupungeilla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Minä nousen heitä vastaan, sanoo Herra Sebaot, ja hävitän Baabelilta nimen ja jäännöksen, suvun ja jälkeläiset, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'Minä teen sen tuonenkurkien perinnöksi ja vesirämeeksi, minä lakaisen sen pois hävityksen luudalla, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Herra Sebaot on vannonut sanoen: Totisesti, mitä minä olen ajatellut, se tapahtuu, mitä minä olen päättänyt, se toteutuu:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'minä muserran Assurin maassani ja tallaan hänet vuorillani, niin että hänen ikeensä heltiää heidän päältään ja hänen kuormansa heltiää heidän hartioiltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Tämä on päätös, päätetty kaikesta maasta, tämä on käsi, ojennettu kaikkien kansojen yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Sillä Herra Sebaot on päättänyt, -kuka sen tyhjäksi tekee? Hänen kätensä on ojennettu, -kuka sen torjuu?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Kuningas Aahaan kuolinvuotena tuli tämä ennustus:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Älä iloitse, Filistea kaikkinesi, siitä että sauva, joka sinua löi, on murtunut. Sillä käärmeen juuresta kasvaa myrkkylisko, ja sen hedelmä on lentävä käärme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Vaivaisista kurjimmat löytävät laitumen, ja köyhät saavat turvassa levätä, mutta sinun juuresi minä tapan nälkään, ja sinun jäännöksesi surmataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Valita, portti, huuda, kaupunki; menehdy pelkoon, Filistea kaikkinesi, sillä pohjoisesta tulee savu; eikä yksikään erkane vihollisen riveistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Ja mitä vastataan pakanakansan sanansaattajille? \"Herra on perustanut Siionin, ja hänen kansansa kurjat saavat siinä turvan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Ennustus Mooabista. Hävityksen yönä tuhoutuu Aar-Mooab; hävityksen yönä tuhoutuu Kiir-Mooab.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Bait ja Diibon nousevat uhrikukkuloille itkemään, Nebolla ja Meedebassa Mooab valittaa; kaikki päät ovat paljaiksi ajellut, kaikki parrat ovat leikatut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Kaduilla he kääriytyvät säkkeihin, katoilla ja toreilla kaikki valittavat, menehtyvät itkuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Hesbon ja Elale huutavat; Jahaaseen asti kuuluu niiden parku. Sentähden Mooabin varustetut miehet vaikeroivat, sen sielu vapisee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Minun sydämeni huutaa Mooabin tähden; sen pakolaisia on aina Sooariin, aina Eglat-Selisijjaan asti. Luuhitin solatietä he nousevat itkien, Hooronaimin tiellä he puhkeavat parkuun hävityksen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Nimrimin vedet ehtyvät erämaaksi, heinä kuivuu, ruoho lakastuu, vihantaa ei ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Sentähden he kantavat hankkimansa säästön ja tallettamansa tavaran Pajupuron yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Parku kiertää Mooabin rajoja, valitus kuuluu Eglaimiin asti, valitus Beer-Eelimiin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Sillä Diimonin vedet ovat verta täynnä, ja vielä muutakin minä tuotan Diimonille: leijonan Mooabin pelastettujen ja maahan jääneitten kimppuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, '\"Lähettäkää maanhallitsijalle tulevat lampaat Selasta erämaan kautta tytär Siionin vuorelle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Ja niinkuin pakenevat linnut, säikytetty pesue, ovat Mooabin tyttäret Arnonin kahlauspaikoilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, '\"Anna neuvo, käy välittämään, tee varjosi yön kaltaiseksi keskellä päivää, kätke karkoitetut, älä ilmaise pakenevia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Salli minun karkoitettujeni asua tykönäsi, ole Mooabille suojana hävittäjää vastaan. Sillä sortajalle tulee loppu, hävitys lakkaa, ja polkija on maasta poissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'ja valtaistuin vahvistetaan laupeudella, ja sillä istuu vakaasti Daavidin majassa tuomari, joka harrastaa oikeutta ja vanhurskautta ahkeroitsee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, '\"Me olemme kuulleet Mooabin ylpeilyn, tuon ylen korskean, hänen kopeilunsa, ylpeilynsä ja vihansa, hänen väärät puheensa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Sentähden Mooab Mooabille valittaa, kaikki he valittavat; Kiir-Haresetin rypälekakkuja te huokailette, ratki murtuneina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Sillä kuihtuneet ovat Hesbonin viinitarhat, Sibman viiniköynnökset; niiden jalot rypäleet kaatoivat kansojen valtiaita, ne ulottuivat Jaeseriin asti, harhailivat halki erämaan, niiden vesat levisivät, menivät yli meren.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Sentähden minä itken Jaeserin kanssa, itken Sibman viiniköynnöksiä, kastelen kyyneleilläni sinua, Hesbon, ja sinua, Elale, sillä hedelmän-ja viininkorjuun keskeen on kajahtanut sotahuuto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Ilo ja riemu on tauonnut puutarhasta, viinitarhoissa ei riemuita, ei remahdella; ei poljeta viiniä viinikuurnissa. \"Minä olen vaientanut ilohuudon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Siksi väräjää minun sisimpäni Mooabin tähden niinkuin kannel, minun sydämeni Kiir-Hereksen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Ja vaikka Mooab kuinka astuisi uhrikukkulalle ja sillä itsensä uuvuttaisi ja vaikka kuinka menisi pyhäkköönsä rukoilemaan, ei se häntä auta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Tämä on sana, jonka Herra ennen puhui Mooabille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Mutta nyt Herra puhuu sanoen: Ennenkuin kolme vuotta on kulunut-kolme palkkalaisen vuotta-painuu halvaksi Mooabin kunnia, sen suuret laumat, ja jäännös on oleva pieni, vähäpätöinen, mitätön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Ennustus Damaskosta. Katso, Damasko poistetaan kaupunkien luvusta ja luhistuu raunioiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Autioiksi jäävät Aroerin kaupungit, karjalaumojen haltuun; ne lepäävät siellä, kenenkään peloittelematta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Efraimilta menee suojavarustus ja Damaskolta kuninkuus ja Aramista jäännöskin: niiden käy niinkuin israelilaisten kunnian, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Ja sinä päivänä Jaakobin kunnia köyhtyy, ja hänen ruumiinsa lihavuus laihtuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Ja käy niinkuin leikkaajan kouraistessa viljaa ja hänen käsivartensa leikatessa tähkäpäitä, käy niinkuin tähkäpäitä poimittaessa Refaimin tasangolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Se siinä jää jälkikorjuuta, mikä öljypuuta karistettaessa: pari, kolme marjaa korkealle latvaan, neljä, viisi hedelmäpuun oksiin, sanoo Herra, Israelin Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Sinä päivänä ihminen luo katseen Luojaansa, ja hänen silmänsä katsovat Israelin Pyhään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'eikä hän luo katsettaan alttareihin, omain kättensä tekoon, eikä katso niihin, mitä hänen sormensa ovat tehneet, ei asera-karsikkoihin, ei auringonpatsaisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'Sinä päivänä ovat hänen linnakaupunkinsa niinkuin autiopaikat metsissä ja kukkuloilla, jotka jätettiin autioiksi israelilaisten tullessa, ja maa muuttuu erämaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Sillä sinä unhotit pelastuksesi Jumalan etkä muistanut suojakalliotasi. Sentähden sinä istutat ihania istutuksia ja kylvät vieraita viiniköynnöksiä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'istuttamispäivänä sinä saat ne isonemaan, ja aamulla saat kylvösi kukoistamaan-mutta poissa on sato sairauden päivänä, ja parantumaton on kipu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Voi paljojen kansojen pauhua-ne pauhaavat, niinkuin meri pauhaa, ja kansakuntien kohinaa-ne kohisevat, niinkuin valtavat vedet kohisevat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Kansakunnat kohisevat, niinkuin suuret vedet kohisevat, mutta hän nuhtelee niitä, ja ne pakenevat kauas; ne karkoitetaan niinkuin akanat tuulessa vuorilla, niinkuin lentävät lehdet rajuilmassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Katso, ehtoolla on oleva kauhu, aamun tullen ei heitä enää ole. Tämä on riistäjäimme osa, ryöstäjäimme arpa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Voi siipien surinan maata, joka on tuolla puolen Etiopian jokien,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'joka lähettää sanansaattajat virralle, ruokovenheissä vesiä myöten! Lähtekää, te nopeat sanansaattajat, vartevan ja kiiltävä-ihoisen kansan luo, lähellä ja kaukana peljätyn kansan luo, väkevän sortajakansan luo, jonka maata joet halkovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Te kaikki maanpiirin asukkaat, te maata asuvaiset, katsokaa, milloin viiri nostetaan vuorille, ja kuunnelkaa, kun pasunaan puhalletaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Sillä näin on Herra minulle sanonut: \"Minä pysyn hiljaa ja katselen asunnostani, niinkuin hehkuva helle päivän paistaessa, niinkuin kastepilvi elonajan helteessä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Sillä ennen viininkorjuuta, kun kukinta on lopussa ja kukasta on tullut kypsyvä marja, hän hakkaa vesurilla köynnökset ja hävittää, katkoo varret.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Ne jätetään kaikki vuorten petolintujen ja maan eläinten haltuun. Petolinnut siellä kesää pitävät, ja kaikkinaiset maan eläimet siellä talvehtivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Siihen aikaan varteva ja kiiltävä-ihoinen kansa, lähellä ja kaukana peljätty kansa, väkevä sortajakansa, jonka maata joet halkovat, tuodaan lahjaksi Herralle Sebaotille siihen paikkaan, missä asuu Herran Sebaotin nimi: Siionin vuorelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Ennustus Egyptistä. Katso, Herra ajaa nopealla pilvellä ja tulee Egyptiin. Silloin vapisevat Egyptin epäjumalat hänen edessään, ja sydän raukeaa Egyptin rinnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Minä kiihoitan Egyptin Egyptiä vastaan, niin että he keskenänsä sotivat, ystävä ystävää vastaan, kaupunki kaupunkia vastaan, valtakunta valtakuntaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Egyptiltä katoaa rohkeus rinnasta, ja minä hämmennän hänen neuvonsa; ja he kysyvät epäjumalilta, henkienmanaajilta, vainaja-ja tietäjähengiltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Minä annan Egyptin tylyn herran käsiin, ja kova kuningas on hallitseva heitä, sanoo Herra, Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Vedet virrasta loppuvat, joki ehtyy ja kuivuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Joet levittävät löyhkää, Egyptin kanavat mataloituvat ja ehtyvät, ruoko ja kaisla lakastuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Ruohostot Niilivirran varsilla, virran suussa, ja kaikki Niilivirran kylvömaat kuivuvat, kuihtuvat ja häviävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Kalastajat valittavat ja murehtivat; kaikki, jotka heittävät onkea virtaan ja laskevat verkkoa veteen, nääntyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Häpeään joutuvat, jotka häkilöityjä pellavia pitelevät ja jotka kutovat pellavakankaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Maan peruspylväät murskataan, ja kaikki palkkalaiset ovat murheellisella mielellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Hulluina ovat Sooanin päämiehet kaikki, viisaimmat faraon neuvonantajista ovat neuvossaan tyhmistyneet. Kuinka voitte sanoa faraolle: \"Olen viisaitten poika, muinaisajan kuninkaitten jälkeläinen\"?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Missä ovat viisaasi? Ilmoittakoot sinulle-hehän sen tietävät-mitä Herra Sebaot on Egyptin osalle päättänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Sooanin päämiehet ovat typertyneet, Noofin päämiehet ovat pettyneet. Egyptiä horjuttavat sen sukukuntain kulmakivet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Herra on vuodattanut sen keskuuteen sekasorron hengen, ja niin he saattavat Egyptin horjumaan kaikissa menoissansa, niinkuin juopunut horjahtaa oksennukseensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Eikä menesty Egyptille mikään teko, tekipä sen pää tai häntä, palmunlehvä tai kaisla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'Sinä päivänä Egypti on oleva naisten kaltainen; se vapisee ja pelkää Herran Sebaotin käden heilutusta, kun hän heiluttaa kättään sitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Ja Juudan maa on oleva Egyptille kauhuksi; niin usein kuin sitä sille mainitaan, pelkää se Herran Sebaotin päätöstä, jonka hän siitä on päättänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'Sinä päivänä on viisi kaupunkia Egyptin maassa puhuva Kanaanin kieltä ja vannova valan Herralle Sebaotille. Yhtä mainitaan nimellä Iir-Heres.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'Sinä päivänä on oleva Herran alttari keskellä Egyptin maata ja sen rajalla Herran patsas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'Ja se on oleva merkkinä ja todistuksena Herralle Sebaotille Egyptin maassa; sillä he huutavat Herraa sortajain tähden, ja hän lähettää heille vapauttajan ja puolustajan, joka pelastaa heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Ja Herra tekee itsensä tunnetuksi egyptiläisille, ja egyptiläiset tuntevat Herran sinä päivänä ja palvelevat häntä teuras-ja ruokauhreilla, ja he tekevät Herralle lupauksia ja täyttävät ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Herra lyö egyptiläisiä, lyö ja parantaa; he palajavat Herran tykö, ja hän kuulee heidän rukouksensa ja parantaa heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'Sinä päivänä on oleva valtatie Egyptistä Assuriin, ja Assur yhtyy Egyptiin ja Egypti Assuriin, ja he, Egypti ynnä Assur, palvelevat Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'Sinä päivänä on Israel oleva kolmantena Egyptin ja Assurin rinnalla, siunauksena keskellä maata,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'sillä Herra Sebaot siunaa sitä sanoen: \"Siunattu olkoon Egypti, minun kansani, ja Assur, minun kätteni teko, ja Israel, minun perintöosani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Sinä vuonna, jona Tartan, Sargonin, Assurin kuninkaan, lähettämänä, tuli Asdodiin, ryhtyi taisteluun Asdodia vastaan ja valloitti sen-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'siihen aikaan Herra puhui Jesajan, Aamoksen pojan, kautta sanoen: \"Mene, riisu säkkipuku lanteiltasi ja vedä kengät jalastasi\". Hän teki niin: kulki vaipatta ja avojaloin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Sitten Herra sanoi: \"Niinkuin palvelijani Jesaja on kolme vuotta kulkenut vaipatta ja avojaloin, merkiksi ja enteeksi Egyptille ja Etiopialle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'niin on Assurin kuningas kuljettava Egyptin sotavankeja ja Etiopian pakkosiirtolaisia, sekä nuoria että vanhoja, vaipattomina ja avojaloin, takapuolet paljaina-Egyptin häpeä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Silloin he kauhistuvat ja saavat häpeän Etiopiasta, joka oli heidän toivonsa, ja Egyptistä, joka oli heidän ylpeytensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Ja tämän rantamaan asukkaat sanovat sinä päivänä: \'Katso, näin on käynyt meidän toivomme, jonka turviin me pakenimme apua saamaan, vapautuaksemme Assurin kuninkaasta. Kuinka me sitten itse pelastuisimme?\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Ennustus meren viereisestä erämaasta. Niinkuin myrskytuulet kiitävät Etelämaassa, niin tulee se erämaasta, peloittavasta maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Julma näky ilmoitettiin minulle: \"Ryöstäjä ryöstää, hävittäjä hävittää. Hyökkää, Eelam! Piiritä, Meedia! Kaiken huokailun minä lopetan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Sentähden minun lanteeni ovat täynnä vavistusta, minut valtaavat tuskat, niinkuin synnyttäjän tuskat; minua huimaa, niin etten kuule, kauhistuttaa, niin etten näe.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Minun sydämeni värisee, kauhu peljästyttää minut. Ikävöimäni iltahämärän se muuttaa minulle vavistukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Pöytä katetaan, matto levitetään, syödään, juodaan. Nouskaa, te ruhtinaat, voidelkaa kilvet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Sillä näin on Herra minulle sanonut: \"Mene, aseta tähystäjä; hän ilmoittakoon, mitä näkee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Ja kun hän näkee jonon ratsastajia parittain, jonon aaseja, jonon kameleja, niin kuunnelkoon tarkasti, hyvin tarkasti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Ja hän huusi kuin leijona: \"Tähystyspaikalla, Herra, minä seison alati, päivät pitkät, pysyn vartiopaikallani kaiket yöt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Ja katso, tuolla tulee jonossa miehiä, parivaljakoita.\" Ja hän lausui sanoen: \"Kukistunut, kukistunut on Baabel, ja kaikki sen jumalain kuvat hän on murskannut maahan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Maahan puitu kansani, puimatantereella poljettuni! Mitä olen kuullut Herralta Sebaotilta, Israelin Jumalalta, sen minä teille ilmoitan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Ennustus Duumasta. Minulle huudetaan Seiristä: \"Vartija, mikä hetki yöstä on? Vartija, mikä hetki yöstä on?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Vartija vastaa: \"Aamu on tullut, mutta silti on yö. Jos vielä kyselette, niin kyselkää; tulkaa uudelleen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Ennustus Arabiaa vastaan. Yöpykää Arabian viidakoissa, dedanilaiset matkueet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Menkää vastaan, viekää vettä janoaville. Teeman maan asukkaat ottavat pakolaiset vastaan, leipää tariten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Sillä he ovat miekkoja paossa, paljastettua miekkaa, jännitettyä jousta ja sodan tuimuutta paossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Sillä näin on Herra minulle sanonut: Vielä vuosi-sellainen kuin on palkkalaisen vuosi-niin kaikki Keedarin kunnia on kadonnut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'ja Keedarin urhojen jousiluvun jäännös on oleva vähäinen. Sillä Herra, Israelin Jumala, on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Ennustus Näkylaaksosta. Mikä sinun on, kun sinä kaikkinesi katoille nouset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'sinä humuavainen, pauhaava kaupunki, sinä remuava kylä? Surmattusi eivät ole miekan surmaamia, eivät sotaan kuolleita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Kaikki sinun päämiehesi yhdessä pakenivat, joutuivat vangiksi, jousta vailla; keitä ikinä sinun omiasi tavattiin, ne vangittiin kaikki tyynni, kuinka kauas pakenivatkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Sentähden minä sanon: \"Kääntäkää katseenne minusta pois: minä itken katkerasti; älkää tunkeilko minua lohduttamaan, kun tytär, minun kansani, tuhoutuu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Sillä hämmingin, hävityksen ja häiriön päivän on Herra, Herra Sebaot, pitävä Näkylaaksossa. Muurit murrettiin, vuorille kohosi huuto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Eelam nosti viinen, tullen vaunuineen, väkineen ja ratsumiehineen, ja Kiir paljasti kilven.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Ihanimmat laaksosi täyttyivät vaunuista, ratsumiehet asettuivat asemiin portin eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Hän riisui Juudalta verhon, ja sinä päivänä sinä loit katseesi Metsätalon asevarastoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Te huomasitte monta repeämää Daavidin kaupungin muurissa ja kokositte vedet Alalammikkoon;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'te luitte Jerusalemin talot ja hajotitte taloja vahvistaaksenne muurin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'ja te teitte molempien muurien välille paikan, johon Vanhan lammikon vedet koottiin. Mutta hänen puoleensa te ette katsoneet, joka tämän tuotti, häntä te ette nähneet, joka tämän kauan sitten valmisti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Ja sinä päivänä Herra, Herra Sebaot, kutsui itkuun ja valitukseen, pään paljaaksi ajamaan ja säkkiin vyöttäytymään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Mutta katso: on ilo ja riemu, raavaitten tappaminen ja lammasten teurastus, lihan syönti ja viinin juonti! \"Syökäämme ja juokaamme, sillä huomenna me kuolemme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Niin kuului minun korviini Herran Sebaotin ilmoitus: \"Totisesti, ei tämä teidän syntinne tule sovitetuksi, ei kuolemaanne saakka, sanoo Herra, Herra Sebaot\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Näin sanoo Herra, Herra Sebaot: Mene tuon huoneenhaltijan tykö, Sebnan tykö, joka on linnan päällikkönä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, '\"Mitä sinulla täällä on asiaa, ja keitä sinulla täällä on, kun tänne itsellesi haudan hakkautat, hakkautat hautasi korkeuteen, kallioon itsellesi asunnon koverrat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Katso, Herra heittää sinua, mies, rajusti: hän kouraisee sinut kokoon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'kääräisee sinut keräksi ja paiskaa pallona menemään maahan, jossa on laajuutta joka suuntaan. Sinne sinä kuolet, ja sinne jäävät sinun kunniavaunusi, sinä herrasi huoneen häpeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Minä syöksen sinut pois paikastasi; hän kukistaa sinut asemastasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Mutta sinä päivänä minä kutsun palvelijani Eljakimin, Hilkian pojan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'ja puetan hänen yllensä sinun ihokkaasi, vyötän hänet sinun vyölläsi ja panen sinun valtasi hänen käteensä, niin että hän on oleva isänä Jerusalemin asukkaille ja Juudan suvulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Ja minä panen Daavidin huoneen avaimen hänen olallensa; ja hän avaa, eikä kukaan sulje, ja hän sulkee, eikä kukaan avaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Minä lyön hänet vaarnaksi vahvaan paikkaan, ja hän tulee kunniaistuimeksi isänsä suvulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Hänen varaansa ripustautuu hänen isänsä suvun kaikki paljous, vesat ja versot, kaikki pienet astiat, maljat ja ruukut kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Sinä päivänä, sanoo Herra Sebaot, pettää vahvaan paikkaan lyöty vaarna, se katkeaa ja putoaa, ja kuorma, joka oli sen varassa, särkyy. Sillä Herra on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Ennustus Tyyrosta. Valittakaa, te Tarsiin-laivat, sillä se on hävitetty talottomaksi, käymättömäksi; kittiläisten maasta he saivat tämän tiedon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Mykistykää, te rantamaan asukkaat! Siidonin kauppamiehet, merenkulkijat, täyttivät sinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Ja suuria vesiä kulki Siihorin siemen, Niilivirran vilja; se oli Tyyron sato, ja siitä tuli kansojen kauppatavara.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Häpeä, Siidon, sillä näin sanoo meri, meren linnoitus: \"En ole kivuissa ollut, en ole synnyttänyt, en nuorukaisia kasvattanut, en neitoja vartuttanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Kun tämä kuullaan Egyptissä, niin vavistaan Tyyron kuulumisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Menkää Tarsiiseen; valittakaa, te rantamaan asukkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Onko tämä teidän remuava kaupunkinne, jonka alku on hamasta muinaisajasta, jonka jalat kuljettivat sen kauas muukalaisena asumaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Kuka on tämän päättänyt Tyyron osalle, kruunujen jakelijan, jonka kauppamiehet olivat ruhtinaita, kauppiaat maanmainioita?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Herra Sebaot on sen päättänyt, häväistäkseen kaiken koreuden korskan, saattaakseen kaikki maanmainiot halveksituiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Tulvi yli maasi, tytär Tarsis, niinkuin Niilivirta; ei ole patoa enää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Hän on ojentanut kätensä meren yli, järkyttänyt valtakunnat. Herra on antanut käskyn Kanaania vastaan, että sen linnoitukset hävitettäköön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Hän sanoo: \"Älä enää ilakoitse, sinä häväisty neitsyt, tytär Siidon. Nouse, mene kittiläisten maahan; et sinä sielläkään saa levätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Katso, kaldealaisten maa, kansa, jota ei ollut enää olemassa, jonka Assur oli valmistanut erämaan eläimille, -ne pystyttävät vartiotorninsa, ne kukistavat sen palatsit, tekevät sen raunioiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Valittakaa, te Tarsiin-laivat, sillä hävitetty on teidän linnoituksenne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Ja siihen aikaan Tyyro unhotetaan seitsemäksikymmeneksi vuodeksi, jotka ovat kuin saman kuninkaan aikaa. Seitsemänkymmenen vuoden kuluttua käy Tyyron, niinkuin porton laulussa sanotaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, '\"Ota kantele, kierrä kaupunkia, sinä unhotettu portto; soita kauniisti, laula vireästi, että sinut muistettaisiin!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Ja seitsemänkymmenen vuoden kuluttua Herra katsoo Tyyron puoleen, ja se pääsee jälleen portonpalkoilleen ja tekee huorin kaikkien maan valtakuntain kanssa, mitä maan päällä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Mutta sen voitto ja palkka on oleva Herralle pyhitetty; ei sitä koota eikä talleteta, vaan sen voitto on tuleva niille, jotka Herran edessä asuvat, runsaaksi ravinnoksi ja jaloksi vaatetukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Katso, Herra tekee maan tyhjäksi ja autioksi, mullistaa sen muodon ja hajottaa sen asukkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Ja niinkuin kansan käy, niin papinkin, niinkuin orjan, niin hänen herransa, niinkuin orjattaren, niin hänen emäntänsä, niinkuin ostajan, niin myyjän, niinkuin lainanottajan, niin lainanantajan, niinkuin velallisen, niin velkojankin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Maa tyhjentämällä tyhjennetään ja ryöstämällä ryöstetään. Sillä Herra on tämän sanan puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Maa murehtii ja lakastuu, maanpiiri nääntyy ja lakastuu; kansan ylhäiset maassa nääntyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Maa on saastunut asukkaittensa alla, sillä he ovat rikkoneet lait, muuttaneet käskyt, hyljänneet iankaikkisen liiton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Sentähden kirous kalvaa maata, ja sen asukkaat syystänsä kärsivät; sentähden maan asukkaat kuumuudesta korventuvat, ja vähän jää ihmisiä jäljelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Viini murehtii, viiniköynnös kuihtuu, kaikki ilomieliset huokaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Loppunut on vaskirumpujen riemu, lakannut remuavaisten melu, loppunut kanteleitten riemu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Ei laulaen viiniä juoda, väkijuoma käy karvaaksi juojillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Kukistettu on autio kaupunki, joka talo teljetty, sisään pääsemätön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Viinistä on kaduilla valitus, kaikki ilo on mennyt mailleen, riemu maasta paennut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Jäljellä on kaupungissa hävitys, portti on pirstaleiksi lyöty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Sillä niin on käyvä maan päällä, kansojen keskuudessa, kuin öljypuuta karistettaessa, kuin jälkikorjuussa, viininkorjuun päätyttyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Ne korottavat äänensä ja riemuitsevat, ne huutavat mereltä päin Herran valtasuuruutta:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, '\"Sentähden kunnioittakaa Herraa valon mailla, ja meren saarilla Herran, Israelin Jumalan, nimeä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Maan äärestä kuulemme ylistysvirret: \"Ihana on vanhurskaan osa!\" Mutta minä sanon: \"Riutumus, riutumus on minun osani, voi minua: ryöstäjät ryöstävät, raastaen ryöstäjät ryöstävät!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Kauhu ja kuoppa ja paula on edessäsi, sinä maan asukas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Joka pakenee kauhun ääntä, se putoaa kuoppaan, ja joka kuopasta nousee, se puuttuu paulaan. Sillä korkeuden akkunat aukenevat ja maan perustukset järkkyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Maa murskaksi musertuu, maa halkee ja hajoaa, maa horjuu ja huojuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Maa hoippuu ja hoipertelee niinkuin juopunut, huojuu niinkuin lehvämaja. Raskaana painaa sitä sen rikkomus, se kaatuu eikä enää nouse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Sinä päivänä Herra kostaa korkeuden sotajoukolle korkeudessa ja maan kuninkaille maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'Heidät kootaan sidottuina vankikuoppaan ja suljetaan vankeuteen; pitkän ajan kuluttua heitä etsiskellään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Ja kuu punastuu, ja aurinko häpeää, sillä Herra Sebaot on kuningas Siionin vuorella ja Jerusalemissa, ja hänen vanhintensa edessä loistaa kirkkaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Herra, sinä olet minun Jumalani; minä kunnioitan sinua, kiitän sinun nimeäsi, sillä sinä olet tehnyt ihmeitä, sinun aivoituksesi kaukaisilta päiviltä ovat todet ja vakaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Sillä sinä olet tehnyt kaupungin kiviroukkioksi, varustetun kaupungin raunioiksi; muukalaisten linna on kadonnut kaupunkien luvusta, ei sitä ikinä enää rakenneta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Sentähden sinua kunnioittaa väkevä kansa, väkivaltaisten pakanain kaupunki sinua pelkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Sillä sinä olit turvana vaivaiselle, turvana köyhälle hänen ahdingossansa, suojana rankkasateelta, varjona helteeltä; sillä väkivaltaisten kiukku on kuin rankkasade seinää vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Niinkuin helteen kuivassa maassa, niin sinä vaimensit muukalaisten melun. Niinkuin helle pilven varjossa vaipuu väkivaltaisten voittolaulu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Ja Herra Sebaot laittaa kaikille kansoille tällä vuorella pidot rasvasta, pidot voimaviinistä, ydinrasvasta, puhtaasta voimaviinistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Ja hän hävittää tällä vuorella verhon, joka verhoaa kaikki kansat, ja peiton, joka peittää kaikki kansakunnat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Hän hävittää kuoleman ainiaaksi, ja Herra, Herra pyyhkii kyyneleet kaikkien kasvoilta ja ottaa pois kansansa häväistyksen kaikesta maasta. Sillä Herra on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Ja sinä päivänä sanotaan: \"Katso, tämä on meidän Jumalamme, jota me odotimme meitä pelastamaan; tämä on Herra, jota me odotimme: iloitkaamme ja riemuitkaamme pelastuksesta, jonka hän toi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Sillä Herran käsi lepää tällä vuorella. Mutta Mooab tallataan siihen paikkaansa, niinkuin oljet tallautuvat lantaveteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Ja hän haroo siinä käsiään, niinkuin uija haroo uidessansa, mutta Herra painaa alas hänen ylpeytensä ynnä hänen kättensä rimpuilut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Sinun korkeitten muuriesi varustukset hän kukistaa, painaa alas, syöksee maahan, tomuun asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Sinä päivänä lauletaan Juudan maassa tämä laulu: \"Meillä on vahva kaupunki, pelastuksen hän asettaa muuriksi ja varustukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Avatkaa portit vanhurskaan kansan käydä sisälle, joka uskollisena pysyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Vakaamieliselle sinä talletat rauhan, rauhan, sillä hän turvaa sinuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Turvatkaa Herraan ainiaan, sillä Herra, Herra on iankaikkinen kallio.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Sillä hän on kukistanut korkealla asuvaiset, ylhäisen kaupungin, hän painoi sen alas, painoi maan tasalle, syöksi sen tomuun asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Sitä tallaa jalka, kurjan jalat, vaivaisten askeleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Vanhurskaan polku on suora, sinä teet vanhurskaan tien tasaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Niin, sinun tuomioittesi tiellä me odotamme sinua, Herra; sinun nimeäsi ja sinun muistoasi sielu ikävöitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Minun sieluni ikävöitsee sinua yöllä, minun henkeni sisimmässäni etsii sinua varhain; sillä kun sinun tuomiosi kohtaavat maata, oppivat maanpiirin asukkaat vanhurskautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Jos jumalaton saa armon, ei hän opi vanhurskautta; oikeuden maassa hän tekee vääryyttä eikä näe Herran korkeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Herra, sinun kätesi on kohotettu, mutta he eivät sitä näe. He saakoot häpeäksensä nähdä sinun kiivautesi kansan puolesta; kuluttakoon heidät tuli, joka sinun vihollisesi kuluttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Herra, sinä saatat meille rauhan, sillä myös kaikki meidän tekomme olet sinä tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Herra, meidän Jumalamme, meitä ovat vallinneet muut herrat, et sinä; sinua yksin me ylistämme, sinun nimeäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Kuolleet eivät virkoa eloon, vainajat eivät nouse: niin sinä olet heille kostanut, tuhonnut heidät ja hävittänyt kaiken heidän muistonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Sinä olet lisännyt kansan, Herra, olet lisännyt kansan, olet kunniasi näyttänyt, olet laajentanut kaikki maan rajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Herra, ahdistuksessa he etsivät sinua, vuodattivat hiljaisia rukouksia, kun sinä heitä kuritit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Niinkuin raskas vaimo, joka on synnyttämäisillään, vääntelehtii ja huutaa kivuissansa, niin me olimme sinun edessäsi, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Me olimme raskaina, vääntelehdimme, mutta oli niinkuin olisimme synnyttäneet tuulta: emme saaneet aikaan pelastusta maalle, maanpiirin asukkaat eivät ilmoille päässeet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Mutta sinun kuolleesi virkoavat eloon, minun ruumiini nousevat ylös. Herätkää ja riemuitkaa, te jotka tomussa lepäätte, sillä sinun kasteesi on valkeuksien kaste, ja maa tuo vainajat ilmoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Mene, kansani, kammioihisi ja sulje ovet jälkeesi, lymyä hetkinen, kunnes viha on ohitse mennyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Sillä katso, Herra lähtee asuinsijastaan kostamaan maan asukkaille heidän pahat tekonsa, ja maa paljastaa verivelkansa eikä surmattujansa enää peitä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Sinä päivänä Herra kostaa kovalla, suurella ja väkevällä miekallansa Leviatanille, kiitävälle käärmeelle, ja Leviatanille, kiemurtelevalle käärmeelle, ja tappaa lohikäärmeen, joka on meressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Sinä päivänä sanotaan: \"On viinitarha, tulisen viinin tarha; laulakaa siitä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, '\'Minä, Herra, olen sen vartija, minä kastelen sitä hetkestä hetkeen; minä vartioitsen sitä öin ja päivin, ettei sitä mikään vahingoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Vihaa minulla ei ole; olisipa vain orjantappuroita ja ohdakkeita, niiden kimppuun minä kävisin sodalla ja polttaisin ne kaikki tyynni-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'kaikki, jotka eivät antaudu minun turviini, eivät tee rauhaa minun kanssani, tee rauhaa minun kanssani.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Tulevina aikoina juurtuu Jaakob, Israel kukkii ja kukoistaa ja täyttää maanpiirin hedelmällänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Löikö hän sitä, niinkuin sen lyöjät lyötiin, tapettiinko se, niinkuin sen tappajat tapettiin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Karkoittamalla sen, lähettämällä sen pois sinä sitä rankaisit. Hän pyyhkäisi sen pois kovalla myrskyllänsä itätuulen päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Sentähden sovitetaan Jaakobin pahat teot sillä, ja se on hänen syntiensä poistamisen täysi hedelmä, että hän tekee kaikki alttarikivet rikottujen kalkkikivien kaltaisiksi: eivät kohoa enää asera-karsikot eivätkä auringonpatsaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Sillä varustettu kaupunki on autio, se on hyljätty maja, jätetty tyhjäksi kuin erämaa. Siellä vasikat käyvät laitumella, siellä makailevat ja kaluavat sieltä vesat kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Ja kun oksat kuivuvat, niin ne taitetaan; vaimot tulevat ja tekevät niillä tulta. Sillä se ei ole ymmärtäväistä kansaa; sentähden sen tekijä ei sitä armahda, sen Luoja ei sitä sääli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Sinä päivänä Herra karistaa hedelmät maahan, Eufrat-virrasta aina Egyptin puroon asti, ja teidät, te israelilaiset, poimitaan talteen yksitellen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Sinä päivänä puhalletaan suureen pasunaan, ja Assurin maahan hävinneet ja Egyptin maahan karkoitetut tulevat ja kumartavat Herraa Pyhällä vuorella Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Voi Efraimin juopuneitten ylvästä kruunua ja sen kunnian loisteen kuihtuvata kukkaa, joka on kukkulan laella, viinistä päihtyneitten lihavan laakson keskellä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Katso, Herralta tulee hän, joka on väkevä ja voimallinen, niinkuin raesade, rajumyrsky. Niinkuin rankkasade, väkeväin tulvavetten kuohu, hän voimalla maahan kaataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Jalkoihin tallataan Efraimin juopuneitten ylväs kruunu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Ja sen kunnian loisteen kuihtuvan kukan, joka on kukkulan laella, lihavan laakson keskellä, käy niinkuin varhaisviikunan ennen kesää: kuka vain sen näkee, tuskin se on hänen kourassaan, niin hän sen jo nielaisee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Sinä päivänä Herra Sebaot on oleva loistava kruunu ja kunnian seppele kansansa jäännökselle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'ja oikeuden henki sille, joka oikeutta istuu, ja väkevyys niille, jotka torjuvat hyökkäyksen takaisin porttia kohden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Ja nämäkin horjuvat viinistä ja hoipertelevat väkijuomasta. Väkijuomasta horjuu pappi ja profeetta; he ovat sekaisin viinistä, hoipertelevat väkijuomasta. He horjuvat näyissä, huojuvat tuomioissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Sillä täynnä oksennusta ja saastaa ovat kaikki pöydät-ei puhdasta paikkaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, '\"Keitähän tuokin luulee taitoon neuvovansa, keitä saarnalla opettavansa? Olemmeko me vasta maidolta vieroitettuja, äidin rinnoilta otettuja?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Käsky käskyn päälle, käsky käskyn päälle, läksy läksyn päälle, läksy läksyn päälle, milloin siellä, milloin täällä!\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Niin, sopertavin huulin ja vieraalla kielellä hän on puhuva tälle kansalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'hän, joka on sanonut heille: \"Tässä on lepo; antakaa väsyneen levätä, tässä on levähdyspaikka\". Mutta he eivät ole tahtoneet kuulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Niinpä on Herran sana oleva heille: \"Käsky käskyn päälle, käsky käskyn päälle, läksy läksyn päälle, läksy läksyn päälle, milloin siellä, milloin täällä\", niin että he kulkiessaan kaatuvat selälleen ja ruhjoutuvat, että heidät kiedotaan ja vangitaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Sentähden kuulkaa Herran sana, te pilkkaajat, te jotka hallitsette tätä kansaa Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Koska te sanotte: \"Me olemme tehneet liiton kuoleman kanssa ja tuonelan kanssa sopimuksen; tulkoon vitsaus kuin tulva, ei se meitä saavuta, sillä me olemme tehneet valheen turvaksemme ja piiloutuneet petokseen\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'sentähden, näin sanoo Herra, Herra: Katso, minä lasken Siioniin peruskiven, koetellun kiven, kalliin kulmakiven, lujasti perustetun; joka uskoo, se ei pakene.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Ja minä panen oikeuden mittanuoraksi ja vanhurskauden vaa\'aksi, ja rakeet hävittävät valheturvan, ja vedet huuhtovat pois piilopaikan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Teidän liittonne kuoleman kanssa pyyhkäistään pois, ja teidän sopimuksenne tuonelan kanssa ei kestä; kun vitsaus tulee niinkuin tulva, niin se teidät maahan tallaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Niin usein kuin se tulee, tempaa se teidät valtaansa, sillä aamu aamulta se tulee, tulee päivällä ja yöllä: totisesti, kauhuksi on tämän saarnan opetus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Sillä vuode on oleva liian lyhyt ojentautua ja peitto liian kaita kääriytyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Sillä Herra nousee niinkuin Perasimin vuorella, hän kiivastuu niinkuin Gibeonin laaksossa tehdäkseen työnsä, oudon työnsä, ja toimittaakseen tekonsa, kumman tekonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Älkää siis pilkatko, etteivät teidän siteenne vielä kiristyisi; sillä Herralta Sebaotilta minä olen kuullut hävitys-ja tuomiopäätöksen, joka on kohtaava kaikkea maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Kuunnelkaa ja kuulkaa minun ääntäni, tarkatkaa ja kuulkaa minun sanojani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Ainako kyntäjä vain kyntää, kun olisi kylväminen, ainako vakoaa ja äestää maatansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Eikö niin: kun hän on tasoittanut sen pinnan, hän kylvää mustaa kuminaa, sirottelee höystekuminaa, panee nisunjyvät riviin, ohran omaan paikkaansa ja kolmitahkoista vehnää vierelle?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Hänen Jumalansa on neuvonut hänelle oikean tavan ja opettaa häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Sillä ei mustaa kuminaa puida puimaäkeellä eikä puimajyrän tela pyöri höystekuminan yli, vaan musta kumina lyödään irti sauvalla ja höystekumina vitsalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Puidaankos leipävilja murskaksi? Ei sitä kukaan iankaiken pui eikä aina aja sen päällitse puimajyrällään ja hevosillaan; ei sitä murskaksi puida.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Tämäkin on tullut Herralta Sebaotilta; hänen neuvonsa on ihmeellinen ja ymmärryksensä ylen suuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Voi Arielia, Arielia, kaupunkia, jonne Daavid asetti leirinsä! Liittäkää vuosi vuoteen, kiertäkööt juhlat kiertonsa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'niin minä ahdistan Arielia, ja se on oleva täynnä valitusta ja vaikerrusta, oleva minulle kuin Jumalan uhriliesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Minä asetan leirini yltympäri sinua vastaan ja saarran sinut vartiostoilla ja luon vallit sinua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Silloin sinä puhut maasta matalalta, sanasi tulevat vaimeina tomusta, sinä uikutat kuin vainajahenki maasta, puheesi tulee supisten tomusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Mutta sinun vainolaistesi lauma on oleva niinkuin hieno pöly, ja väkivaltaisten lauma niinkuin lentävät akanat, ja tämä tapahtuu äkkiä, silmänräpäyksessä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Herra Sebaot etsiskelee sinua ukkosenjylinässä ja maanjäristyksessä, kovassa pauhinassa, myrskyssä ja rajuilmassa, kuluttavan tulen liekissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Niinkuin yöllinen uninäky on oleva kansain lauma, joka sotii Arielia vastaan, kaikki, jotka sotivat sitä ja sen varustuksia vastaan ja sitä ahdistavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Niinkuin nälkäinen on unissaan syövinänsä, mutta herää hiuka sydämessä, ja niinkuin janoinen on unissaan juovinansa, mutta herää, ja katso, hän on nääntynyt ja himoitsee juoda, niin on oleva kaikki kansain lauma, joka sotii Siionin vuorta vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Hämmästykää ja ihmetelkää, tuijottakaa sokeiksi itsenne ja sokeiksi jääkää! He ovat juovuksissa, vaikkeivät viinistä, hoipertelevat, vaikkeivät väkijuomasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Sillä Herra on vuodattanut teidän päällenne raskaan unen hengen ja sulkenut teidän silmänne-profeettanne, ja peittänyt teidän päänne-näkijänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Niin on kaikki ilmoitus teille niinkuin lukitun kirjan sanat; jos se annetaan kirjantaitavalle ja sanotaan: \"Lue tämä\", niin hän vastaa: \"Ei voi, sillä se on lukittu\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'ja jos kirja annetaan kirjantaitamattomalle ja sanotaan: \"Lue tämä\", niin hän vastaa: \"En osaa lukea\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Ja Herra sanoi: Koska tämä kansa lähestyy minua suullaan ja kunnioittaa minua huulillaan, mutta pitää sydämensä minusta kaukana, ja koska heidän jumalanpelkonsa on vain opittuja ihmiskäskyjä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'sentähden, katso, minä vielä teen tälle kansalle kummia tekoja-kummia ja ihmeitä, ja sen viisaitten viisaus häviää, ja sen ymmärtäväisten ymmärrys katoaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Voi niitä, jotka syvälle kätkevät hankkeensa Herralta, joiden teot tapahtuvat pimeässä ja jotka sanovat: \"Kuka meitä näkee, kuka meistä tietää?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Voi mielettömyyttänne! Onko savi savenvalajan veroinen? Ja sanooko työ tekijästään: \"Ei hän ole minua tehnyt\", tai sanooko kuva kuvaajastaan: \"Ei hän mitään ymmärrä\"?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Vain lyhyt hetki enää, niin Libanon muuttuu puutarhaksi, ja puutarha on metsän veroinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Sinä päivänä kuurot kuulevat kirjan sanat, ja sokeiden silmät näkevät vapaina synkeästä pimeydestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Nöyrät saavat yhä uutta iloa Herrassa, ja ihmisistä köyhimmätkin riemuitsevat Israelin Pyhästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Sillä väkivaltaisista on tullut loppu, pilkkaajat ovat hävinneet, ja kaikki vääryyteen valppaat ovat tuhotut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'ne, jotka sanallansa langettavat ihmisiä syyhyn ja virittävät pauloja sille, joka oikeutta puolustaa portissa, ja verukkeilla syyttömän asian vääräksi vääntävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Sentähden Herra, joka Aabrahamin vapahti, sanoo Jaakobin heimolle näin: Ei Jaakob enää joudu häpeään, eivätkä hänen kasvonsa enää kalpene.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Sillä kun hän näkee, kun hänen lapsensa näkevät keskellänsä minun kätteni työn, niin he pyhittävät minun nimeni, pitävät pyhänä Jaakobin Pyhän ja peljästyvät Israelin Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Ja hengessään eksyväiset käsittävät ymmärryksen, ja napisevaiset ottavat oppia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Voi uppiniskaisia lapsia, sanoo Herra, jotka pitävät neuvoa, mikä ei ole minusta, ja hierovat liittoa ilman minun henkeäni, kooten syntiä synnin päälle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'jotka menevät Egyptiin, kysymättä minulta, turvautuakseen faraon turviin ja etsiäkseen suojaa Egyptin varjossa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Faraon turva koituu teille häpeäksi ja suojan etsiminen Egyptin varjosta häväistykseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Sillä vaikka hänen ruhtinaansa ovat Sooanissa ja hänen sanansaattajansa saapuneet Haanekseen asti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'joutuvat kaikki häpeään kansan tähden, josta heillä ei ole hyötyä-ei apua, ei hyötyä, vaan häpeätä ja pilkkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Ennustus Eteläisen maan Behemotia vastaan. Halki ahdingon ja ahdistuksen maan, halki naarasleijonan ja jalopeuran maan, kyykäärmeen ja lentävän käärmeen maan he kuljettavat aasinvarsojen selässä rikkautensa ja kamelien kyttyrällä aarteensa kansan tykö, josta ei hyötyä ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Egyptin apu on turha ja tyhjä; sentähden minä annan sille nimen: \"Rahab, joka ei pääse paikaltansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Mene siis nyt ja kirjoita se tauluun heidän läsnäollessaan ja piirrä se kirjaan, että se säilyisi tuleviin aikoihin, ainiaan, iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Sillä he ovat niskoitteleva kansa, ovat vilpillisiä lapsia, lapsia, jotka eivät tahdo kuulla Herran lakia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'jotka sanovat näkijöille: \"Älkää nähkö\", ja ennustajille: \"Älkää ennustako meille tosia, puhukaa meille mieluisia, ennustakaa silmänlumeita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Poiketkaa tieltä, väistykää polulta; viekää pois silmistämme Israelin Pyhä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Sentähden, näin sanoo Israelin Pyhä: Koska te halveksitte tätä sanaa ja luotatte väkivaltaan ja vääryyteen ja siihen turvaudutte,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'niin tämä synti on oleva kuin repeämä korkeassa muurissa, joka uhkaa sortua ja pullistuu; se särkyy äkkiä, yhtäkkiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Se särkyy, niinkuin särkyy savenvalajan astia, joka lyödään rikki säälimättä, niin ettei sen sirpaleista löydy palasta, millä ottaa tulta liedestä tai ammentaa vettä altaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Sillä näin sanoo Herra, Herra, Israelin Pyhä: Kääntymällä ja pysymällä hiljaa te pelastutte, rauhallisuus ja luottamus on teidän väkevyytenne; mutta te ette tahtoneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'vaan sanoitte: \"Ei! Hevosilla me tahdomme kiitää\" -niinpä saatte kiitää pakoon. \"Nopean selässä me tahdomme ratsastaa\" -niinpä ovat vainoojanne nopeat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Tuhat pakenee yhden uhkaa; viiden uhkaa te pakenette, kunnes se, mikä teistä jää, on kuin merkkipuu vuoren huipulla, kuin lipputanko kukkulalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Sentähden Herra odottaa, että voisi olla teille armollinen, sentähden hän nousee armahtaaksensa teitä; sillä Herra on oikeuden Jumala. Autuaita kaikki, jotka häntä odottavat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Sinä kansa, joka asut Siionissa, Jerusalemissa, älä itke! Hän on sinulle totisesti armollinen, kun apua huudat; sen kuullessaan hän vastaa sinulle kohta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Vaikka Herra antaa teille hädän leipää ja ahdistuksen vettä, niin ei sinun opettajasi sitten enää kätkeydy, vaan sinun silmäsi saavat nähdä sinun opettajasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'Ja sinun korvasi kuulevat takaasi tämän sanan, milloin poikkeatte oikealle tai vasemmalle: \"Tässä on tie, sitä käykää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Silloin sinä havaitset saastaiseksi veistettyjen jumalankuviesi hopeapäällystyksen ja valettujen jumalankuviesi kultakuoren; sinä viskaat ne pois kuin inhotuksen, sinä sanot niille: \"Ulos!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Niin hän antaa sateen sinun siemenellesi, jonka maahan kylvät, ja maan sadosta leivän, joka on oleva mehevä ja lihava, ja sinun karjasi on sinä päivänä käyvä laajalla laitumella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Härät ja aasinvarsat, jotka peltotyötä tekevät, syövät suolaista rehuviljaa, joka on viskattu hangolla ja viskimellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Ja kaikilla korkeilla vuorilla ja kaikilla ylhäisillä kukkuloilla on oleva puroja, vesivirtoja, suuren surmaamisen päivänä, tornien sortuessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Ja kuun valo on oleva kuin auringon valo, ja auringon valo on oleva seitsenkertainen, oleva niinkuin seitsemän päivän valo, sinä päivänä, jona Herra sitoo kansansa vammat ja parantaa siihen isketyt haavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Katso, Herran nimi tulee kaukaa, hänen vihansa leimuaa, ja sankka savu tupruaa; hänen huulensa ovat täynnä hirmuisuutta, ja hänen kielensä on kuin kuluttava tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'Hänen hengityksensä on kuin virta, joka tulvii ja ulottuu kaulaan asti; se seuloo kansakuntia turmion seulassa ja panee eksyttäväiset suitset kansojen suupieliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Silloin te veisaatte niinkuin yöllä, kun pyhä juhla alkaa, ja sydämenne riemuitsee niinkuin sen, joka huilujen soidessa astuu vaeltaen Herran vuorelle, Israelin kallion tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Herra antaa kuulla äänensä voiman ja nähdä käsivartensa laskeutuvan alas vihan tuimuudessa ja kuluttavan tulen liekissä, pilvenpurkuna, rankkasateena ja raekivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Sillä Herran äänestä peljästyy Assur. Hän lyö vitsalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Ja jokaisella sallimuksen sauvan iskulla, jonka Herra häneen satuttaa, soivat vaskirummut ja kanteleet, ja hän sotii häntä vastaan, sotii kättä heiluttaen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Sillä aikoja sitten on polttopaikka valmistettu; kuninkaallekin se on varattu. Syvä ja leveä on sen liesi, tulta ja polttopuita paljon. Herran henkäys kuin tulikivi-virta sytyttää sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Voi niitä, jotka menevät alas Egyptiin apua etsimään ja turvautuvat hevosiin, luottavat sotavaunuihin, koska niitä on paljon, ja ratsumiehiin, koska niitten luku on ylen suuri, mutta eivät katso Israelin Pyhään, eivät kysy neuvoa Herralta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Mutta myös hän on viisas, ja hän tuottaa onnettomuuden; hän ei peruuta sanojansa, vaan nousee pahantekijäin sukua vastaan ja väärintekijäin apuuntuloa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Egypti on ihminen eikä Jumala, ja heidän hevosensa ovat lihaa eivätkä henkeä. Kun Herra ojentaa kätensä, suistuu auttaja, ja autettava kaatuu, ja yhdessä he kumpikin hukkuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Sillä näin on Herra minulle sanonut: Niinkuin leijona, nuori leijona, murisee saaliinsa ääressä, kun sitä vastaan hälytetään paimenten parvi, eikä peljästy heidän huutoansa, ei huoli heidän hälinästään, niin Herra Sebaot on astuva alas sotimaan Siionin vuorella ja sen kukkulalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Niinkuin liitelevät linnut, niin varjelee Herra Sebaot Jerusalemia-varjelee ja pelastaa, säästää ja vapahtaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Palatkaa, te israelilaiset, hänen tykönsä, josta olette niin kauas luopuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Sillä sinä päivänä jokainen hylkää hopeaiset ja kultaiset epäjumalansa, jotka kätenne ovat tehneet teille synniksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Ja Assur kaatuu miekkaan, joka ei ole miehen, ja hänet syö miekka, joka ei ole ihmisen; hän pakenee miekkaa, ja hänen nuorukaisensa joutuvat työorjuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Hänen kallionsa kukistuu kauhusta, ja hänen ruhtinaansa säikkyvät lipun luota pakoon, sanoo Herra, jonka tuli on Siionissa ja pätsi Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Katso, kuningas on hallitseva vanhurskaudessa, ja valtiaat vallitsevat oikeuden mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Silloin on jokainen heistä oleva turvana tuulelta ja suojana rankkasateelta, oleva kuin vesipurot kuivassa maassa, kuin korkean kallion varjo nääntyvässä maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Silloin eivät näkevien silmät ole soaistut, ja kuulevien korvat kuulevat tarkkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Ajattelemattomien sydän käsittää taidon, ja änkyttäväin kieli puhuu sujuvasti ja selkeästi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Ei houkkaa enää kutsuta jaloksi, eikä petollista enää sanota yleväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Sillä houkka puhuu houkan lailla, ja hänen sydämensä hankkii turmiota, ja niin hän harjoittaa riettautta ja puhuu eksyttäväisesti Herrasta, jättää tyhjäksi nälkäisen sielun ja janoavaisen juomaa vaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Ja pahat ovat petollisen aseet, hän miettii ilkitöitä, tuhotakseen kurjat valheen sanoilla, vaikka köyhä kuinka oikeata asiaa puhuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Mutta jalo jaloja miettii ja jaloudessa lujana pysyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Nouskaa, te suruttomat naiset, kuulkaa minun ääntäni; te huolettomat tyttäret, tarkatkaa minun sanojani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Vielä vuosi, ja päiviä päälle, niin vapisette, te huolettomat; sillä silloin on viininkorjuusta tullut loppu, hedelmänkorjuuta ei tule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Kauhistukaa, te suruttomat, vaviskaa, te huolettomat, riisuutukaa, paljastukaa, vyöttäkää säkki lanteillenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Silloin valitetaan ja lyödään rintoihin ihanien peltojen tähden ja hedelmällisten viiniköynnösten tähden,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'minun kansani maan tähden, joka kasvaa orjantappuraa ja ohdaketta, remuavan kaupungin kaikkien iloisten talojen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Sillä palatsi on hyljätty, kaupungin kohina lakannut, Oofel ja vartiotorni ovat jääneet luoliksi iankaikkisesti, villiaasien iloksi ja laumojen laitumeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Näin on hamaan siihen asti, kunnes meidän päällemme vuodatetaan Henki korkeudesta. Silloin erämaa muuttuu puutarhaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'ja puutarha on metsän veroinen. Ja erämaassa asuu oikeus, ja puutarhassa majailee vanhurskaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Silloin vanhurskauden hedelmä on rauha, vanhurskauden vaikutus lepo ja turvallisuus iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Ja minun kansani asuu rauhan majoissa, turvallisissa asunnoissa, huolettomissa lepopaikoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Mutta raesade tulee, metsä kaatuu, ja kaupunki alennetaan alhaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Onnelliset te, jotka kylvätte kaikkien vetten vierille ja laskette härän ja aasin jalat valtoimina kulkemaan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Voi sinua hävittäjää, joka itse olet hävittämättä, sinua ryöstäjää, jota ei kenkään ole ryöstänyt! Kun olet loppuun asti hävittänyt, hävitetään sinut, kun olet ryöstösi ryöstänyt, ryöstetään sinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Herra, armahda meitä, sinua me odotamme. Ole näitten käsivarsi joka aamu, ole meidän apumme hädän aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Kansat pakenevat sinun jylinäsi ääntä; kun sinä nouset, hajoavat kansakunnat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Teidän saaliinne viedään, niinkuin tuhosirkat vievät; niinkuin hyppysirkat hyökkäävät, niin sen kimppuun hyökätään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Herra on korkea, sillä hän asuu korkeudessa. Hän täyttää Siionin oikeudella ja vanhurskaudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Ja hän on sinun aikojesi vakuus, avun runsaus, viisaus ja ymmärrys; Herran pelko on oleva Siionin aarre.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Katso, sankarit huutavat ulkona, rauhan sanansaattajat itkevät katkerasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Tiet ovat autioina, polulta on kulkija poissa: hän on rikkonut liiton, ylenkatsonut kaupungit, ei ole ihmistä minäkään pitänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Maa murehtii ja nääntyy, Libanon kuihtuu häpeästä, Saaron on aromaaksi tullut, Baasan ja Karmel varistavat lehtensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Nyt minä nousen, sanoo Herra, nyt minä itseni korotan, nyt minä kohoan korkealle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Olkia te kannatte kohdussanne, akanoita synnytätte; teidän kiukkunne on tuli, joka kuluttaa teidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Ja kansat poltetaan kuin kalkki, kuin katkotut orjantappurat, jotka tulessa palavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Kuulkaa, te kaukaiset, mitä minä olen tehnyt; te lähelläolevat, tuntekaa minun voimani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Syntiset Siionissa peljästyvät, vavistus valtaa jumalattomat: \"Kuka meistä voi asua kuluttavassa tulessa, kuka asua iankaikkisessa hehkussa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Joka vanhurskaudessa vaeltaa ja puhuu sitä, mikä oikein on, joka halveksii väärää voittoa, jonka käsi torjuu lahjukset luotaan, joka tukkii korvansa kuulemasta veritöitä ja sulkee silmänsä näkemästä pahaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'hän on asuva kukkuloilla, kalliolinnat ovat hänen turvansa; hänelle annetaan hänen leipänsä, eikä vesi häneltä ehdy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Sinun silmäsi saavat katsoa kuningasta hänen ihanuudessaan, saavat nähdä avaran maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Sinun sydämesi muistelee kauhuja: missä on nyt veronlaskija, missä punnitsija, missä tornien lukija?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Et näe enää sitä röyhkeätä kansaa, kansaa, jolla on outo, käsittämätön puhe, jonka sopertavaa kieltä ei kukaan ymmärrä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Katso Siionia, juhliemme kaupunkia. Sinun silmäsi näkevät Jerusalemin, rauhaisan asuinsijan, telttamajan, jota ei muuteta, jonka vaarnoja ei ikinä reväistä irti, jonka köysistä ei yhtäkään katkaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Sillä voimallinen on meillä siellä Herra, siellä on joet, on virrat, leveät rannasta toiseen, joita ei kulje soutualus, joiden poikki ei pääse uljas laiva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Sillä Herra on meidän tuomarimme, Herra on johdattajamme, Herra on meidän kuninkaamme; hän pelastaa meidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Nyt ovat köytesi höltyneet, eivät pidä mastoa kannassaan kiinni, eivät vedä lippua liehumaan. Mutta silloin jaetaan riistosaalista runsaasti, rammatkin ryöstävät ja raastavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Eikä yksikään asukas sano: \"Minä olen vaivanalainen\". Kansa, joka siellä asuu, on saanut syntinsä anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Astukaa esiin, te kansat, ja kuulkaa; te kansakunnat, tarkatkaa. Kuulkoon maa ja kaikki, mitä siinä on, maanpiiri ja kaikki, mikä siitä kasvaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Sillä Herra on vihastunut kaikkiin kansoihin ja kiivastunut kaikkiin heidän joukkoihinsa; hän on vihkinyt heidät tuhon omiksi, jättänyt heidät teurastettaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Heidän surmattunsa viskataan pois, ja niitten raadoista nousee löyhkä, ja vuoret valuvat heidän vertansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Kaikki taivaan joukot menehtyvät, taivas kääritään kokoon niinkuin kirja, ja kaikki sen joukot varisevat alas, niinkuin lehdet varisevat viinipuusta, niinkuin viikunapuusta raakaleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Sillä minun miekkani taivaassa on juopunut vimmaan; katso, se iskee alas Edomiin, tuomioksi kansalle, jonka minä olen vihkinyt tuhoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Herran miekka on verta täynnä, rasvaa tiukkuva, karitsain ja kauristen verta, oinasten munuaisrasvaa. Sillä Herralla on uhri Bosrassa, suuri teurastus Edomin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Villihärkiä kaatuu yhteen joukkoon, mullikoita härkien mukana. Heidän maansa juopuu verestä, ja heidän multansa tiukkuu rasvaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Sillä Herralla on koston päivä, maksun vuosi Siionin asian puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Edomin purot muuttuvat pieksi ja sen multa tulikiveksi; sen maa tulee palavaksi pieksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Ei sammu se yöllä eikä päivällä, iäti nousee siitä savu; se on oleva raunioina polvesta polveen, ei kulje siellä kukaan, iankaikkisesta iankaikkiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Sen perivät pelikaanit ja tuonenkurjet, kissapöllöt ja kaarneet asuvat siellä; ja hän vetää sen ylitse autiuden mittanuoran ja tyhjyyden luotilangan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Ei ole siellä enää ylimyksiä huutamassa ketään kuninkaaksi, kaikki sen ruhtinaat ovat poissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Ja sen palatsit kasvavat orjantappuroita, sen linnat polttiaisia ja ohdakkeita; siitä tulee aavikkosutten asunto, kamelikurkien tyyssija.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Siellä erämaan ulvojat ja ulisijat yhtyvät, metsänpeikot toisiansa tapaavat. Siellä yksin öinen syöjätär saa rauhan ja löytää lepopaikan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Siellä nuolikäärme pesii ja laskee munansa, kuorii ne ja kiertyy kerälle pimentoonsa. Sinne haarahaukatkin kokoontuvat yhteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Etsikää Herran kirjasta ja lukekaa: ei yhtäkään näistä ole puuttuva, ei yksikään toistansa kaipaava. -\"Sillä minun suuni on niin käskenyt.\" -Hänen henkensä on ne yhteen koonnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Hän on heittänyt arpaa niitten kesken, ja hänen kätensä on sen niille mittanuoralla jakanut; ne perivät sen ikiajoiksi, asuvat siellä polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Erämaa ja hietikko iloitsee, aromaa riemuitsee ja kukoistaa kuin lilja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Se kauniisti kukoistaa ja iloitsee ilolla ja riemulla. Sille annetaan Libanonin kunnia, Karmelin ja Saaronin ihanuus. He saavat nähdä Herran kunnian, meidän Jumalamme ihanuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Vahvistakaa hervonneet kädet, voimistakaa horjuvat polvet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Sanokaa hätääntyneille sydämille: \"Olkaa lujat, älkää peljätkö. Katso, teidän Jumalanne! Kosto tulee, Jumalan rangaistus. Hän tulee ja pelastaa teidät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Silloin avautuvat sokeain silmät ja kuurojen korvat aukenevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Silloin rampa hyppii niinkuin peura ja mykän kieli riemuun ratkeaa; sillä vedet puhkeavat erämaahan ja aromaahan purot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Hehkuva hiekka tulee lammikoiksi ja kuiva maa vesilähteiksi. Aavikkosutten asunnossa, missä ne makasivat, kasvaa ruoho ynnä ruoko ja kaisla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Ja siellä on oleva valtatie, ja sen nimi on \"pyhä tie\": sitä ei kulje saastainen; se on heitä itseänsä varten. Joka sitä tietä kulkee, ei eksy-eivät hullutkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Ei ole siellä leijonaa, ei nouse sinne raateleva peto; ei sellaista siellä tavata: lunastetut sitä kulkevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Niin Herran vapahdetut palajavat ja tulevat Siioniin riemuiten, päänsä päällä iankaikkinen ilo. Riemu ja ilo saavuttavat heidät, mutta murhe ja huokaus pakenevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Kuningas Hiskian neljäntenätoista hallitusvuotena hyökkäsi Sanherib, Assurin kuningas, kaikkien Juudan varustettujen kaupunkien kimppuun ja valloitti ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Ja Assurin kuningas lähetti Laakiista Rabsaken suuren sotajoukon kanssa kuningas Hiskiaa vastaan Jerusalemiin, ja hän pysähtyi Ylälammikon vesijohdolle, joka on Vanuttajankedon tien varrella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Ja Eljakim, Hilkian poika, joka oli palatsin päällikkönä, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, menivät hänen luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Ja Rabsake sanoi heille: \"Sanokaa Hiskialle: Näin sanoo suurkuningas, Assurin kuningas: \'Mitä on tuo luottamus, mikä sinulla on?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Minä sanon: pelkkää huulten puhetta on moinen neuvo ja voima sodankäyntiin. Keneen sinä oikein luotat, kun kapinoit minua vastaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Katso, sinä luotat Egyptiin, tuohon särkyneeseen ruokosauvaan, joka tunkeutuu sen käteen, joka siihen nojaa, ja lävistää sen. Sellainen on farao, Egyptin kuningas, kaikille, jotka häneen luottavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Vai sanotko ehkä minulle: Me luotamme Herraan, meidän Jumalaamme? Mutta eikö hän ole se, jonka uhrikukkulat ja alttarit Hiskia poisti, kun hän sanoi Juudalle ja Jerusalemille: Tämän alttarin edessä on teidän kumartaen rukoiltava?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Mutta lyö nyt vetoa minun herrani, Assurin kuninkaan, kanssa: minä annan sinulle kaksi tuhatta hevosta, jos sinä voit hankkia niille ratsastajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Kuinka sinä sitten voisit torjua ainoankaan käskynhaltijan, ainoankaan minun herrani vähimmän palvelijan, hyökkäyksen? Ja sinä vain luotat Egyptiin, sen vaunuihin ja ratsumiehiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Olenko minä siis Herran sallimatta hyökännyt tähän maahan hävittämään sitä? Herra itse on sanonut minulle: \'Hyökkää tähän maahan ja hävitä se\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Niin Eljakim, Sebna ja Jooah sanoivat Rabsakelle: \"Puhu palvelijoillesi araminkieltä, sillä me ymmärrämme sitä; älä puhu meille juudankieltä kansan kuullen, jota on muurilla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Mutta Rabsake vastasi: \"Onko minun herrani lähettänyt minut puhumaan näitä sanoja sinun herrallesi ja sinulle? Eikö juuri niille miehille, jotka istuvat muurilla ja joutuvat teidän kanssanne syömään omaa likaansa ja juomaan omaa vettänsä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Sitten Rabsake astui esiin, huusi kovalla äänellä juudankielellä ja sanoi: \"Kuulkaa suurkuninkaan, Assurin kuninkaan, sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Näin sanoo kuningas: \'Älkää antako Hiskian pettää itseänne, sillä hän ei voi teitä pelastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Älköön Hiskia saako teitä luottamaan Herraan, kun hän sanoo: Herra on varmasti pelastava meidät; ei tätä kaupunkia anneta Assurin kuninkaan käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Älkää kuulko Hiskiaa.\' Sillä Assurin kuningas sanoo näin: \'Tehkää sovinto minun kanssani ja antautukaa minulle, niin saatte syödä kukin viinipuustanne ja viikunapuustanne ja juoda kukin kaivostanne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'kunnes minä tulen ja vien teidät maahan, joka on teidän maanne kaltainen, vilja-ja viinimaahan, leivän ja viinitarhojen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Älköön vain Hiskia saako vietellä teitä, sanoessaan: Herra pelastaa meidät. Onko muidenkaan kansojen jumalista kukaan pelastanut maatansa Assurin kuninkaan käsistä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Missä ovat Hamatin ja Arpadin jumalat? Missä ovat Sefarvaimin jumalat? Ovatko ne pelastaneet Samariaa minun käsistäni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Kuka näiden maiden kaikista jumalista on pelastanut maansa minun käsistäni? Kuinka sitten Herra pelastaisi Jerusalemin minun käsistäni?\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Mutta he olivat vaiti eivätkä vastanneet hänelle mitään, sillä kuningas oli käskenyt niin ja sanonut: \"Älkää vastatko hänelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Sitten palatsin päällikkö Eljakim, Hilkian poika, ja kirjuri Sebna ja kansleri Jooah, Aasafin poika, tulivat Hiskian luo vaatteet reväistyinä ja kertoivat hänelle, mitä Rabsake oli sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Kun kuningas Hiskia sen kuuli, repäisi hän vaatteensa, pukeutui säkkiin ja meni Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Ja hän lähetti palatsin päällikön Eljakimin ja kirjuri Sebnan sekä pappein vanhimmat, säkkeihin puettuina, profeetta Jesajan, Aamoksen pojan, tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Ja he sanoivat hänelle: \"Näin sanoo Hiskia: \'Hädän, kurituksen ja häväistyksen päivä on tämä päivä, sillä lapset ovat tulleet kohdun suulle saakka, mutta ei ole voimaa synnyttää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Ehkä Herra, sinun Jumalasi, kuulee Rabsaken sanat, joilla hänen Herransa, Assurin kuningas, on lähettänyt hänet herjaamaan elävää Jumalaa, ja rankaisee häntä näistä sanoista, jotka Herra, sinun Jumalasi, on kuullut. Niin kohota nyt rukous jäännöksen puolesta, joka vielä on olemassa.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Kun kuningas Hiskian palvelijat tulivat Jesajan tykö,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'sanoi Jesaja heille: \"Sanokaa näin herrallenne: \'Näin sanoo Herra: Älä pelkää niitä sanoja, jotka olet kuullut ja joilla Assurin kuninkaan poikaset ovat häväisseet minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Katso, minä annan häneen mennä sellaisen hengen, että hän kuultuaan sanoman palajaa omaan maahansa; ja minä annan hänen kaatua miekkaan omassa maassansa.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Ja Rabsake kääntyi takaisin ja tapasi Assurin kuninkaan sotimassa Libnaa vastaan; sillä hän oli kuullut, että tämä oli lähtenyt Laakiista pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Mutta kun Sanherib kuuli Tirhakasta, Etiopian kuninkaasta, sanottavan: \"Hän on lähtenyt liikkeelle sotiakseen sinua vastaan\", niin hän sen kuultuaan lähetti sanansaattajat Hiskian tykö ja käski sanoa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, '\"Sanokaa näin Hiskialle, Juudan kuninkaalle: \'Älä anna Jumalasi, johon sinä luotat, pettää itseäsi äläkä ajattele: Jerusalem ei joudu Assurin kuninkaan käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Olethan kuullut, mitä Assurin kuninkaat ovat tehneet kaikille maille, kuinka he ovat vihkineet ne tuhon omiksi. Ja sinäkö pelastuisit!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Ovatko kansain jumalat pelastaneet niitä, jotka minun isäni ovat tuhonneet: Goosania, Harrania, Resefiä ja Telassarin edeniläisiä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Missä on Hamatin kuningas ja Arpadin kuningas, Sefarvaimin kaupungin, Heenan ja Ivvan kuningas?\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Kun Hiskia oli ottanut kirjeen sanansaattajilta ja lukenut sen, meni hän Herran temppeliin; ja Hiskia levitti sen Herran eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Ja Hiskia rukoili Herraa ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, '\"Herra Sebaot, Israelin Jumala, jonka valtaistuinta kerubit kannattavat, sinä yksin olet maan kaikkien valtakuntain Jumala; sinä olet tehnyt taivaan ja maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Herra, kallista korvasi ja kuule; Herra, avaa silmäsi ja katso. Kuule kaikki Sanheribin sanat, jotka hän lähetti herjatakseen elävää Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Se on totta, Herra, että Assurin kuninkaat ovat hävittäneet kaikki maat ja omankin maansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'Ja he ovat heittäneet niiden jumalat tuleen; sillä ne eivät olleet jumalia, vaan ihmiskätten tekoa, puuta ja kiveä, ja sentähden he voivat hävittää ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Mutta pelasta nyt meidät, Herra, meidän Jumalamme, hänen käsistänsä, että kaikki maan valtakunnat tulisivat tietämään, että sinä, Herra, olet ainoa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Niin Jesaja, Aamoksen poika, lähetti Hiskialle tämän sanan: \"Näin sanoo Herra, Israelin Jumala: Koska sinä olet rukoillut minua avuksi Sanheribia, Assurin kuningasta, vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'niin tämä on se sana, jonka Herra on puhunut hänestä: Neitsyt, tytär Siion, halveksii ja pilkkaa sinua; tytär Jerusalem nyökyttää ilkkuen päätänsä sinun jälkeesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Ketä olet herjannut ja häväissyt, ja ketä vastaan olet korottanut äänesi? Korkealle olet kohottanut silmäsi Israelin Pyhää vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Palvelijaisi kautta sinä herjasit Herraa ja sanoit: \'Monilla vaunuillani minä nousin vuorten harjalle, Libanonin ääriin saakka; minä hakkasin maahan sen korkeat setrit, sen parhaat kypressit ja tunkeuduin sen etäisimmälle harjalle, sen rehevimpään metsään;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'minä kaivoin kaivoja ja join kuiviin vedet, ja jalkapohjallani minä kuivasin kaikki Egyptin virrat\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Etkö ole kuullut: kauan sitten minä olen tätä valmistanut, muinaisuudesta saakka tätä aivoitellut! Nyt minä olen sen toteuttanut, ja niin sinä sait hävittää varustetut kaupungit autioiksi kiviroukkioiksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'ja niiden asukkaat olivat voimattomat, he kauhistuivat ja joutuivat häpeään; heidän kävi niinkuin kedon ruohon ja niinkuin vihannan heinän, niinkuin katolla kasvavain kortten ja niinkuin laihon ennen oljelle tulemistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Istuitpa sinä tai lähdit tai tulit, minä sen tiedän, niinkuin senkin, että sinä raivoat minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Koska sinä minua vastaan raivoat ja koska sinun ylpeytesi on tullut minun korviini, niin minä panen koukkuni sinun nenääsi ja suitseni sinun suuhusi ja vien sinut takaisin samaa tietä, jota tulitkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Ja tämä on oleva sinulle merkkinä: tänä vuonna syödään jälkikasvua ja toisena vuonna kesanto-aaluvaa, mutta kolmantena vuonna te kylväkää ja leikatkaa, istuttakaa viinitarhoja ja syökää niiden hedelmää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Ja Juudan heimon pelastuneet, jotka ovat jäljelle jääneet, tekevät taas juurta alaspäin ja hedelmää ylöspäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Sillä Jerusalemista lähtee kasvamaan jäännös, pelastunut joukko Siionin vuorelta. Herran Sebaotin kiivaus on sen tekevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Sentähden, näin sanoo Herra Assurin kuninkaasta: Hän ei tule tähän kaupunkiin eikä siihen nuolta ammu, ei tuo sitä vastaan kilpeä eikä luo sitä vastaan vallia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Samaa tietä, jota hän tuli, hän palajaa, ja tähän kaupunkiin hän ei tule, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Sillä minä varjelen tämän kaupungin ja pelastan sen itseni tähden ja palvelijani Daavidin tähden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Niin Herran enkeli lähti ja löi Assurin leirissä sata kahdeksankymmentä viisi tuhatta miestä, ja kun noustiin aamulla varhain, niin katso, he olivat kaikki kuolleina ruumiina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Silloin Sanherib, Assurin kuningas, lähti liikkeelle ja meni pois; hän palasi maahansa ja jäi Niiniveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Mutta kun hän oli kerran rukoilemassa jumalansa Nisrokin temppelissä, surmasivat hänen poikansa Adrammelek ja Sareser hänet miekalla; sitten he pakenivat Araratin maahan. Ja hänen poikansa Eesarhaddon tuli kuninkaaksi hänen sijaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'Niihin aikoihin sairastui Hiskia ja oli kuolemaisillaan; ja profeetta Jesaja, Aamoksen poika, tuli hänen tykönsä ja sanoi hänelle: \"Näin sanoo Herra: Toimita talosi; sillä sinä kuolet etkä enää parane\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Niin Hiskia käänsi kasvonsa seinään päin ja rukoili Herraa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'ja sanoi: \"Oi Herra, muista, kuinka minä olen vaeltanut sinun edessäsi uskollisesti ja ehyellä sydämellä ja tehnyt sitä, mikä on hyvää sinun silmissäsi!\" Ja Hiskia itki katkerasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Mutta Jesajalle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, '\"Mene ja sano Hiskialle: \'Näin sanoo Herra, sinun isäsi Daavidin Jumala: Minä olen kuullut sinun rukouksesi, olen nähnyt sinun kyyneleesi. Katso, minä lisään sinulle ikää viisitoista vuotta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'ja minä pelastan sinut ja tämän kaupungin Assurin kuninkaan käsistä ja varjelen tätä kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Ja tämä on oleva sinulle merkkinä Herralta siitä, että Herra tekee, mitä on sanonut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'katso, minä annan aurinkokellon varjon siirtyä takaisin kymmenen astetta, jotka se jo on auringon mukana laskeutunut Aahaan aurinkokellossa.\'\" Ja aurinko siirtyi aurinkokellossa takaisin kymmenen astetta, jotka se jo oli laskeutunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Hiskian, Juudan kuninkaan, kirjoittama laulu, kun hän oli ollut sairaana ja toipunut taudistansa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, '\"Minä sanoin: Kesken rauhallisten päivieni minun on mentävä tuonelan porteista; jäljellä olevat vuoteni on minulta riistetty pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Minä sanoin: En saa minä enää nähdä Herraa, Herraa elävien maassa, en enää ihmisiä katsella manalan asukasten joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Minun majani puretaan ja viedään minulta pois niinkuin paimenen teltta; olen kutonut loppuun elämäni, niinkuin kankuri kankaansa, minut leikataan irti loimentutkaimista. Ennenkuin päivä yöksi muuttuu, sinä teet minusta lopun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Minä viihdyttelin itseäni aamuun asti-niinkuin leijona hän murskaa kaikki minun luuni; ennenkuin päivä yöksi muuttuu, sinä teet minusta lopun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Niinkuin pääskynen, niinkuin kurki minä kuikutan, minä kujerran kuin kyyhkynen; hiueten katsovat minun silmäni korkeuteen: Herra, minulla on ahdistus, puolusta minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Mitä nyt sanonkaan? Hän lupasi minulle ja täytti myös: minä vaellan hiljaisesti kaikki elämäni vuodet sieluni murheen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Herra, tämänkaltaiset ovat elämäksi, ja niissä on koko minun henkeni elämä. Sinä teet minut terveeksi; anna minun elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Katso, onneksi muuttui minulle katkera murhe: sinä rakastit minun sieluani, nostit sen kadotuksen kuopasta, sillä sinä heitit kaikki minun syntini selkäsi taa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Sillä ei tuonela sinua kiitä, ei kuolema sinua ylistä; eivät hautaan vaipuneet pane sinun totuuteesi toivoansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Elävät, elävät sinua kiittävät, niinkuin minä tänä päivänä; isä ilmoittaa lapsillensa sinun totuutesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Herra on minun auttajani. Minun kanteleeni soittoja soittakaamme kaikkina elinpäivinämme Herran temppelissä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Ja Jesaja käski tuoda viikunakakkua ja hautoa paisetta, että hän tulisi terveeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Niin Hiskia sanoi: \"Mikä on merkkinä siitä, että minä voin mennä Herran temppeliin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Siihen aikaan Merodak-Baladan, Baladanin poika, Baabelin kuningas, lähetti kirjeen ja lahjoja Hiskialle, kun oli kuullut hänen olleen sairaana ja parantuneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Ja Hiskia iloitsi lähettiläistä ja näytti heille varastohuoneensa, hopean ja kullan, hajuaineet ja kalliin öljyn ja koko asehuoneensa ja kaikki, mitä hänen aarrekammioissansa oli. Ei ollut mitään Hiskian talossa eikä koko hänen valtakunnassaan, mitä hän ei olisi heille näyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Mutta profeetta Jesaja tuli kuningas Hiskian tykö ja sanoi hänelle: \"Mitä nämä miehet ovat sanoneet, ja mistä he ovat tulleet sinun tykösi?\" Hiskia vastasi: \"He ovat tulleet minun tyköni kaukaisesta maasta, Baabelista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Hän sanoi: \"Mitä he ovat nähneet sinun talossasi?\" Hiskia vastasi: \"Kaiken, mitä talossani on, he ovat nähneet; aarrekammiossani ei ole mitään, mitä en olisi heille näyttänyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Niin Jesaja sanoi Hiskialle: \"Kuule Herran Sebaotin sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Katso, päivät tulevat, jolloin kaikki, mitä sinun talossasi on ja mitä sinun isäsi ovat koonneet tähän päivään asti, viedään pois Baabeliin; ei mitään jää jäljelle, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Ja sinun omia poikiasi, jotka sinusta polveutuvat, jotka sinulle syntyvät, viedään hovipalvelijoiksi Baabelin kuninkaan palatsiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Hiskia sanoi Jesajalle: \"Herran sana, jonka olet puhunut, on hyvä\". Sillä hän ajatteli: \"Onpahan rauha ja turvallisuus minun päivinäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, '\"Lohduttakaa, lohduttakaa minun kansaani\", sanoo teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, '\"Puhukaa suloisesti Jerusalemille ja julistakaa sille, että sen vaivanaika on päättynyt, että sen velka on sovitettu, sillä se on saanut Herran kädestä kaksinkertaisesti kaikista synneistänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Huutavan ääni kuuluu: \"Valmistakaa Herralle tie erämaahan, tehkää arolle tasaiset polut meidän Jumalallemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Kaikki laaksot korotettakoon, kaikki vuoret ja kukkulat alennettakoon; koleikot tulkoot tasangoksi ja kalliolouhut lakeaksi maaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Herran kunnia ilmestyy: kaikki liha saa sen nähdä. Sillä Herran suu on puhunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'ni sanoo: \"Julista!\" Toinen vastaa: \"Mitä minun pitää julistaman?\" Kaikki liha on kuin ruoho, ja kaikki sen kauneus kuin kedon kukkanen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'ruoho kuivuu, kukkanen lakastuu, kun Herran henkäys puhaltaa siihen. Totisesti, ruohoa on kansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Ruoho kuivuu, kukkanen lakastuu, mutta meidän Jumalamme sana pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Nouse korkealle vuorelle, Siion, sinä ilosanoman tuoja; korota voimakkaasti äänesi, Jerusalem, sinä ilosanoman tuoja. Korota, älä pelkää, sano Juudan kaupungeille: \"Katso, teidän Jumalanne!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Katso, Herra, Herra tulee voimallisena, hänen käsivartensa vallitsee. Katso, hänen palkkansa on hänen mukanansa, hänen työnsä ansio käy hänen edellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Niinkuin paimen hän kaitsee laumaansa, kokoaa karitsat käsivarrellensa ja kantaa niitä sylissään, johdattelee imettäviä lampaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Kuka on kourallaan mitannut vedet ja vaaksalla määrännyt taivaitten mitat? Kuka on kolmannesmittaan mahduttanut maan tomun, puntarilla punninnut vuoret, vaa\'alla kukkulat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Kuka on Herran Henkeä ohjannut, ollut hänen neuvonantajansa ja opettajansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Kenen kanssa hän on neuvotellut, joka olisi hänelle ymmärrystä antanut ja opettanut oikean polun, opettanut hänelle tiedon ja osoittanut hänelle ymmärryksen tien?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Katso, kansakunnat ovat kuin pisara vesisangon uurteessa, ovat kuin tomuhiukkanen vaa\'assa. Katso, merensaaret hän nostaa kuin hiekkajyvän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Ei Libanon riittäisi polttopuiksi eikä sen riista polttouhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Kaikki kansakunnat ovat niinkuin ei mitään hänen edessään, ne ovat hänelle kuin olematon ja tyhjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Keneenkä siis te vertaatte Jumalan, ja minkä muotoiseksi te hänet teette?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Jumalankuvanko? -Sen valaa valaja, ja kultaseppä kullalla päällystää, sepittää sille hopeaketjut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Kenellä ei ole varaa sellaiseen antimeen, se valitsee puun, joka ei lahoa, hakee taitavan tekijän pystyttämään jumalankuvan, joka ei horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Ettekö te tiedä, ettekö kuule, eikö teille ole alusta asti ilmoitettu, ettekö ole maan perustuksista vaaria ottaneet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Hän istuu korkealla maanpiirin päällä, kuin heinäsirkkoja ovat sen asukkaat; hän levittää taivaan niinkuin harson, pingoittaa sen niinkuin teltan asuttavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Hän tekee ruhtinaat olemattomiksi, saattaa maan tuomarit tyhjän veroisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Tuskin he ovat istutetut, tuskin kylvetyt, tuskin on heidän vartensa juurtunut maahan, niin hän puhaltaa heihin, ja he kuivettuvat; myrsky vie heidät kuin oljenkorret.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, '\"Keneenkä siis te vertaatte minut, jonka kaltainen minä olisin\", sanoo Pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Nostakaa silmänne korkeuteen ja katsokaa: kuka on nämä luonut? Hän, joka johdattaa esiin niitten joukot täysilukuisina, joka nimeltä kutsuu ne kaikki; suuri on hänen voimansa ja valtainen hänen väkensä: ei yksikään jää häneltä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Miksi sinä, Jaakob, sanot ja sinä, Israel, puhut: \"Minun tieni on Herralta salassa, minun oikeuteni on joutunut pois minun Jumalani huomasta\"?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Etkö tiedä, etkö ole kuullut: Herra on iankaikkinen Jumala, joka on luonut maan ääret? Ei hän väsy eikä näänny, hänen ymmärryksensä on tutkimaton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Hän antaa väsyneelle väkeä ja voimattomalle voimaa yltäkyllin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Nuorukaiset väsyvät ja nääntyvät, nuoret miehet kompastuvat ja kaatuvat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'mutta ne, jotka Herraa odottavat, saavat uuden voiman, he kohottavat siipensä kuin kotkat. He juoksevat eivätkä näänny, he vaeltavat eivätkä väsy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Vaietkaa minun edessäni, te merensaaret. Kansat verestäkööt voimansa, astukoot esiin ja puhukoot sitten; käykäämme oikeutta keskenämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Kuka herätti päivänkoiton maasta hänet, jota vanhurskaus seuraa joka askeleella? Kuka antaa kansat hänen valtaansa, kukistaa kuninkaat hänen jalkoihinsa? Kuka muuttaa heidän miekkansa tomuksi, heidän jousensa lentäviksi oljenkorsiksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Hän ajaa heitä takaa, samoaa vammatonna polkua, hänen jalkainsa ennen kulkematonta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Kuka on tämän tehnyt ja toimittanut? Hän, joka alusta asti kutsuu sukupolvet esiin: minä, Herra, joka olen ensimmäinen ja viimeisten luona vielä sama.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Merensaaret näkivät sen ja peljästyivät, maan ääret vapisivat. He lähestyivät, he tulivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'he auttoivat toinen toistaan ja sanoivat toisillensa: \"Ole luja!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Valaja rohkaisee kultaseppää, levyn vasaroitsija alasimen iskijää; hän sanoo juotoksesta: \"Se on hyvä\", ja vahvistaa sen nauloilla, niin ettei se horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Mutta sinä Israel, minun palvelijani, sinä Jaakob, jonka minä olen valinnut, Aabrahamin, minun ystäväni, siemen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'jonka minä olen ottanut maan ääristä ja kutsunut maan kaukaisimmilta periltä, jolle minä sanoin: \"Sinä olet minun palvelijani, sinut minä olen valinnut enkä sinua halpana pitänyt\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Älä pelkää, sillä minä olen sinun kanssasi; älä arkana pälyile, sillä minä olen sinun Jumalasi; minä vahvistan sinua, minä autan sinua, minä tuen sinua vanhurskauteni oikealla kädellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Katso, häpeän ja pilkan saavat kaikki, jotka palavat vihasta sinua vastaan; tyhjiin raukeavat ja hukkuvat, jotka sinun kanssasi riitelevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Hakemallakaan et löydä niitä, jotka sinua vastaan taistelivat; tyhjiin raukeavat ja lopun saavat, jotka sinun kanssasi sotivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Sillä minä, Herra, sinun Jumalasi, tartun sinun oikeaan käteesi, minä sanon sinulle: \"Älä pelkää, minä autan sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Älä pelkää, Jaakob, sinä mato, sinä Israelin vähäinen väki: minä autan sinua, sanoo Herra, ja sinun lunastajasi on Israelin Pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Katso, minä panen sinut raastavaksi puimaäkeeksi, uudeksi, monihampaiseksi. Sinä puit ja rouhennat vuoret, muutat kukkulat akanoiksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'sinä ne viskaat, ja tuuli ne vie ja myrsky ne hajottaa. Mutta sinä iloitset Herrassa, Israelin Pyhä on sinun kerskauksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Kurjat ja köyhät etsivät vettä, eikä sitä ole; heidän kielensä kuivuu janosta. Mutta minä, Herra, kuulen heitä, minä, Israelin Jumala, en heitä hylkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Minä puhkaisen purot kalliokukkuloihin, lähteet laaksojen pohjiin; minä muutan erämaan vesilammikoiksi ja hietikon hetteiköksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Minä kasvatan erämaahan setripuita, akasioita, myrttejä ja öljypuita; minä istutan arolle kypressejä, jalavia ynnä hopeakuusia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'jotta he näkisivät ja tietäisivät, huomaisivat ja myös ymmärtäisivät, että Herran käsi on tämän tehnyt, Israelin Pyhä sen luonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Tuokaa esiin riita-asianne, sanoo Herra, esittäkää todisteenne, sanoo Jaakobin kuningas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Esittäkööt ja ilmoittakoot meille, mitä tapahtuva on; ilmoittakaa entiset, mitä ne olivat, tarkataksemme ja tietääksemme, mitä niistä on tullut, tahi antakaa meidän kuulla tulevaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Ilmoittakaa, mitä vastedes tapahtuu, tietääksemme, oletteko te jumalia. Tehkää hyvää tai tehkää pahaa, niin me katsomme ja ihmettelemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Katso, te olette pelkkää tyhjää, ja teidän tekonne ovat turhat. Kauhistus se, joka teidät valitsee!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Minä herätin pohjoisesta hänet, ja hän tuli, päivänkoitosta hänet, joka rukoilee minun nimeäni, ja hän tallaa käskynhaltijoita kuin lokaa, niinkuin savenvalaja savea sotkee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Kuka on sen alunpitäen ilmoittanut, että olisimme sen tienneet, ja edeltäpäin, niin että voisimme sanoa: \"Hän oli oikeassa\"? Ei kukaan sitä ilmoittanut, ei kukaan sitä kuuluttanut, ei kukaan kuullut teiltä sanaakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Minä ensimmäisenä sanon Siionille: \"Katso, katso, siinä ne ovat!\" ja annan Jerusalemille ilosanomantuojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Minä katselen ympärilleni, mutta ei ole ketään; ei kenkään näistä voi antaa neuvoa, että kysyisin heiltä ja he vastaisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Katso, kaikki he ovat pelkkää petosta, turhat ovat heidän työnsä; tuulta ja tyhjää ovat heidän valetut kuvansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Katso, minun palvelijani, jota minä tuen, minun valittuni, johon minun sieluni mielistyi. Minä olen pannut Henkeni häneen, hän levittää kansakuntiin oikeuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Ei hän huuda eikä korota ääntään, ei anna sen kuulua kaduilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Särjettyä ruokoa hän ei muserra, ja suitsevaista kynttilänsydäntä hän ei sammuta. Hän levittää oikeutta uskollisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Hän itse ei sammu eikä murru, kunnes on saattanut oikeuden maan päälle, ja merensaaret odottavat hänen opetustansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Näin sanoo Jumala, Herra, joka on luonut taivaan ja levittänyt sen, joka on tehnyt maan laveuden ja mitä siinä kasvaa, antanut henkäyksensä kansalle, joka siinä on, ja hengen niille, jotka siellä vaeltavat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Minä, Herra, olen vanhurskaudessa kutsunut sinut, olen tarttunut sinun käteesi, varjellut sinut ja pannut sinut kansoille liitoksi, pakanoille valkeudeksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'avaamaan sokeat silmät, päästämään sidotut vankeudesta, pimeydessä istuvat vankihuoneesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Minä, Herra, se on minun nimeni, minä en anna kunniaani toiselle enkä ylistystäni epäjumalille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Katso, entiset ovat toteen käyneet, ja uusia minä ilmoitan; ennenkuin ne puhkeavat taimelle, annan minä teidän ne kuulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Veisatkaa Herralle uusi virsi, veisatkaa hänen ylistystänsä hamasta maan äärestä, te merenkulkijat ja meri täysinensä, te merensaaret ja niissä asuvaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Korottakoot äänensä erämaa ja sen kaupungit, kylät, joissa Keedar asuu. Riemuitkoot kallioilla asuvaiset, vuorten huipuilta huutakoot ilosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Antakoot Herralle kunnian ja julistakoot hänen ylistystään merensaarissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Herra lähtee sotaan niinkuin sankari, niinkuin soturi hän kiihoittaa kiivautensa; hän nostaa sotahuudon ja karjuu, uhittelee vihollisiansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Minä olen ollut vaiti ikiajoista asti, olen ollut hiljaa ja pidättänyt itseni. Mutta nyt minä huudan kuin lapsensynnyttäjä, puhallan ja puuskun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Minä teen autioiksi vuoret ja kukkulat, ja kuihdutan niiltä kaiken ruohon; minä muutan virrat saariksi ja kuivaan vesilammikot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Minä johdatan sokeat tietä, jota he eivät tunne; polkuja, joita he eivät tunne, minä kuljetan heidät. Minä muutan pimeyden heidän edellään valkeudeksi ja koleikot tasangoksi. Nämä minä teen enkä niitä tekemättä jätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Mutta ne peräytyvät ja joutuvat häpeään, jotka turvaavat veistettyyn kuvaan, jotka sanovat valetuille kuville: \"Te olette meidän jumalamme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Te kuurot, kuulkaa, ja te sokeat, katsokaa ja nähkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Kuka on sokea, ellei minun palvelijani, ja kuka niin kuuro kuin minun sanansaattajani, jonka minä lähetän? Kuka on niin sokea kuin minun palkkalaiseni, niin sokea kuin Herran palvelija?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Paljon sinä olet nähnyt, mutta et ole ottanut varteen; korvat avattiin, mutta ei kuulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Herra on nähnyt hyväksi vanhurskautensa tähden tehdä lain suureksi ja ihanaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Mutta tämä on raastettu ja ryöstetty kansa kaikki nuoret miehet ovat sidotut ja vankihuoneisiin kätketyt; he ovat joutuneet saaliiksi, eikä ole auttajaa, ryöstetyiksi, eikä ole, kuka sanoisi: \"Anna takaisin!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Kuka teistä ottaa tämän korviinsa, tarkkaa ja kuulee vastaisen varalta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Kuka on antanut Jaakobin ryöstettäväksi ja Israelin raastajain valtaan? Eikö Herra, jota vastaan me olemme syntiä tehneet, jonka teitä he eivät tahtoneet vaeltaa ja jonka lakia he eivät totelleet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Niin hän vuodatti Israelin päälle vihansa hehkun ja sodan tuimuuden. Se liekehti hänen ympärillään, mutta hän ei ollut tietääksensä; se poltti häntä, mutta hän ei siitä huolinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Mutta nyt, näin sanoo Herra, joka loi sinut, Jaakob, joka valmisti sinut, Israel: Älä pelkää, sillä minä olen lunastanut sinut, minä olen sinut nimeltä kutsunut; sinä olet minun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Jos vetten läpi kuljet, olen minä sinun kanssasi, jos virtojen läpi, eivät ne sinua upota; jos tulen läpi käyt, et sinä kärvenny, eikä liekki sinua polta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Sillä minä olen Herra, sinun Jumalasi, Israelin Pyhä, sinun vapahtajasi: minä annan sinun lunnaiksesi Egyptin, sinun sijastasi Etiopian ja Seban.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Koska sinä olet minun silmissäni kallis ja suuriarvoinen ja koska minä sinua rakastan, annan minä ihmisiä sinun sijastasi ja kansakuntia sinun hengestäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Älä pelkää, sillä minä olen sinun kanssasi; minä tuon sinun siemenesi päivänkoiton ääriltä, päivän laskemilta minä sinut kokoan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Minä sanon pohjoiselle: Anna tänne! ja etelälle: Älä pidätä! Tuo minun poikani kaukaa ja minun tyttäreni hamasta maan äärestä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'kaikki, jotka ovat otetut minun nimiini ja jotka minä olen kunniakseni luonut, jotka minä olen valmistanut ja tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Tuo esiin sokea kansa, jolla kuitenkin on silmät, ja kuurot, joilla kuitenkin on korvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Kaikki kansat ovat kokoontuneet yhteen ja kansakunnat tulleet kokoon. Kuka heistä voi ilmoittaa tämänkaltaista? Tai antakoot meidän kuulla entisiä; asettakoot todistajansa ja näyttäkööt, että ovat oikeassa: sittenpä kuullaan ja sanotaan: \"Se on totta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Te olette minun todistajani, sanoo Herra, minun palvelijani, jonka minä olen valinnut, jotta te tuntisitte minut ja uskoisitte minuun ja ymmärtäisitte, että minä se olen. Ennen minua ei ole luotu yhtäkään jumalaa, eikä minun jälkeeni toista tule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Minä, minä olen Herra, eikä ole muuta pelastajaa, kuin minä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Minä olen ilmoittanut, olen pelastanut ja julistanut, eikä ollut vierasta jumalaa teidän keskuudessanne. Te olette minun todistajani, sanoo Herra, ja minä olen Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Tästedeskin minä olen sama. Ei kukaan voi vapauttaa minun kädestäni; minkä minä teen, kuka sen peruuttaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Näin sanoo Herra, teidän lunastajanne, Israelin Pyhä: Teidän tähtenne minä lähetän sanan Baabeliin, minä syöksen heidät kaikki pakoon, syöksen kaldealaiset laivoihin, jotka olivat heidän ilonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Minä, Herra, olen teidän Pyhänne, minä, Israelin Luoja, olen teidän kuninkaanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Näin sanoo Herra, joka teki tien mereen ja polun valtaviin vesiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'joka vei sotaan vaunut ja hevoset, sotaväen ja sankarit kaikki; he vaipuivat eivätkä nousseet, he raukenivat, sammuivat niinkuin lampunsydän:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Älkää entisiä muistelko, älkää menneistä välittäkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Katso, minä teen uutta; nyt se puhkeaa taimelle, ettekö sitä huomaa? Niin, minä teen tien korpeen, virrat erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Minua kunnioittavat metsän eläimet, aavikkosudet ja kamelikurjet, koska minä johdan vedet korpeen, virrat erämaahan, antaakseni kansani, minun valittuni, juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Kansa, jonka minä olen itselleni valmistanut, on julistava minun kiitostani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Mutta et ole sinä, Jaakob, minua kutsunut, et ole sinä, Israel, itseäsi minun tähteni vaivannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Et ole tuonut minulle lampaitasi polttouhriksi, et teurasuhreillasi minua kunnioittanut; en ole minä vaivannut sinua ruokauhrilla enkä suitsutusuhrilla sinua rasittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Et ole minulle kalmoruokoa hopealla ostanut etkä minua teurasuhriesi rasvalla ravinnut-et, vaan sinä olet minua synneilläsi vaivannut, rasittanut minua pahoilla töilläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Minä, minä pyyhin pois sinun rikkomuksesi itseni tähden, enkä sinun syntejäsi muista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Muistuta sinä minua, käykäämme oikeutta keskenämme; puhu sinä ja näytä, että olet oikeassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Jo sinun esi-isäsi teki syntiä, sinun puolusmiehesi luopuivat minusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Niin minä annoin häväistä pyhät ruhtinaat, jätin Jaakobin tuhon omaksi, Israelin alttiiksi pilkalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Mutta nyt kuule, Jaakob, minun palvelijani, ja Israel, jonka minä olen valinnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Näin sanoo Herra, sinun Luojasi, joka on valmistanut sinut hamasta äidin kohdusta, joka sinua auttaa: Älä pelkää, minun palvelijani Jaakob, sinä Jesurun, jonka minä olen valinnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Sillä minä vuodatan vedet janoavaisen päälle ja virrat kuivan maan päälle. Minä vuodatan Henkeni sinun siemenesi päälle ja siunaukseni sinun vesojesi päälle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'niin että ne kasvavat nurmikossa kuin pajut vesipurojen partaalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Mikä sanoo: \"Minä olen Herran oma\", mikä nimittää itsensä Jaakobin nimellä, mikä piirtää käteensä: \"Herran oma\", ja ottaa Israelin kunnianimeksensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Näin sanoo Herra, Israelin kuningas, ja sen lunastaja, Herra Sebaot: Minä olen ensimmäinen, ja minä olen viimeinen, ja paitsi minua ei ole yhtäkään Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Kuka on minun kaltaiseni? Hän julistakoon ja ilmoittakoon ja osoittakoon sen minulle, siitä alkaen kuin minä perustin ikiaikojen kansan. He ilmoittakoot tulevaiset, ja mitä tapahtuva on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Älkää vavisko älkääkä peljätkö. Enkö minä aikoja sitten antanut sinun kuulla ja sinulle ilmoittanut, ja te olette minun todistajani: Onko muuta Jumalaa kuin minä? Ei ole muuta pelastuskalliota, minä en ketään tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Jumalankuvien tekijät ovat turhia kaikki tyynni, eivätkä nuo heidän rakkaansa mitään auta; niiden todistajat eivät näe eivätkä tiedä mitään, ja niin he joutuvat häpeään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Kuka hyvänsä muovatkoon jumalan ja valakoon kuvan, ei se mitään auta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Katso, kaikki sen seuraajat joutuvat häpeään, ja sen sepittäjät ovat vain ihmisiä. Tulkoot kokoon kaikki ja astukoot esiin: vaviskoot ja hävetkööt!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Rautaseppä ottaa työaseen ja työskentelee hiilten hehkussa, muodostelee kuvaa vasaralla ja takoo sitä käsivartensa väellä; hänen tulee nälkä, ja voima menee, hän ei saa vettä juodaksensa, ja hän nääntyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Puuseppä jännittää mittanuoran, kaavailee piirtimellä, vuolee kovertimella, mittailee harpilla ja tekee miehen kuvan, inhimillisen kauneuden mukaan, huoneeseen asumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Hän hakkaa itselleen setripuita, hän ottaa rautatammen ja tammen ja kasvattaa ne itselleen vahvoiksi metsän puitten seassa, istuttaa lehtikuusen, ja sade kasvattaa sen suureksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Se on ihmisillä polttopuuna; hän ottaa sitä lämmitelläkseen, sytyttää uunin ja paistaa leipää, vieläpä veistää siitä jumalan ja kumartaa sitä, tekee siitä jumalankuvan ja lankeaa maahan sen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Osan siitä hän polttaa tulessa, toisen osan ääressä hän syö lihaa, paistaa paistin ja tulee ravituksi; hän myöskin lämmittelee itseänsä ja sanoo: \"Hyvä, minun on lämmin, minä näen valkean\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Ja lopusta hän tekee jumalan, jumalankuvan, jonka eteen hän lankeaa maahan, jota hän kumartaa ja rukoilee sanoen: \"Pelasta minut, sillä sinä olet minun Jumalani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Eivät he tajua, eivät ymmärrä mitään, sillä suljetut ovat heidän silmänsä, niin etteivät he näe, ja heidän sydämensä, niin etteivät he käsitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Ei tule heidän mieleensä, ei ole heillä järkeä eikä ymmärrystä, että sanoisivat: \"Osan siitä olen polttanut tulessa, olen paistanut sen hiilillä leipää, paistanut lihaa ja syönyt; tekisinkö tähteestä kauhistuksen, lankeaisinko maahan puupölkyn eteen!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Joka tuhassa kiinni riippuu, sen on petetty sydän harhaan vienyt, ei hän pelasta sieluansa eikä sano: \"Eikö ole petosta se, mikä on oikeassa kädessäni?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Muista tämä, Jaakob, ja sinä, Israel, sillä sinä olet minun palvelijani. Minä olen sinut valmistanut, sinä olet minun palvelijani: en unhota minä sinua, Israel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Minä pyyhin pois sinun rikkomuksesi niinkuin pilven ja sinun syntisi niinkuin sumun. Palaja minun tyköni, sillä minä lunastan sinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Iloitkaa, te taivaat, sillä Herra sen tekee; riemuitkaa, te maan syvyydet, puhjetkaa riemuun, te vuoret, ynnä metsä ja kaikki sen puut; sillä Herra lunastaa Jaakobin, kirkastaa itsensä Israelissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Näin sanoo Herra, sinun lunastajasi, joka on valmistanut sinut hamasta äidin kohdusta: Minä olen Herra, joka teen kaiken, joka yksinäni jännitin taivaan, joka levitin maan-kuka oli minun kanssani? -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'joka teen tyhjäksi valhettelijain merkit, teen taikurit tyhmiksi, joka panen tietäjät peräytymään ja muutan heidän tietonsa typeryydeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Mutta palvelijani sanan minä toteutan ja saatan täyttymään sanansaattajaini neuvon. Minä olen se, joka Jerusalemille sanon: \"Sinussa asuttakoon!\" ja Juudan kaupungeille: \"Teidät rakennettakoon!\" Sen rauniot minä kohotan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Minä olen se, joka sanon syvyydelle: \"Kuivu; minä kuivutan sinun virtasi!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'joka sanon Koorekselle: \"Minun paimeneni!\" Hän täyttää kaiken minun tahtoni, hän sanoo Jerusalemille: \"Sinut rakennettakoon!\" ja temppelille: \"Sinut perustettakoon!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Näin sanoo Herra voidellulleen Koorekselle, jonka oikeaan käteen minä olen tarttunut kukistaakseni kansat hänen edestään ja riisuakseni kuninkaitten kupeilta vyöt, että ovet hänen edessään avautuisivat eivätkä portit sulkeutuisi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Minä käyn sinun edelläsi ja tasoitan kukkulat, minä murran vaskiovet ja rikon rautasalvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Minä annan sinulle aarteet pimeän peitosta, kalleudet kätköistänsä, tietääksesi, että minä, Herra, olen se, joka sinut nimeltä kutsuin, minä, Israelin Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Palvelijani Jaakobin ja valittuni Israelin tähden minä kutsuin sinut nimeltä ja annoin sinulle kunnianimen, vaikka sinä et minua tuntenut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Minä olen Herra, eikä toista ole, paitsi minua ei ole yhtään jumalaa. Minä vyötän sinut, vaikka sinä et minua tunne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'jotta tiedettäisiin auringon noususta sen laskemille asti, että paitsi minua ei ole yhtäkään: minä olen Herra, eikä toista ole,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'minä, joka teen valkeuden ja luon pimeyden, joka tuotan onnen ja luon onnettomuuden; minä, Herra, teen kaiken tämän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Tiukkukaa, te taivaat, ylhäältä, vuotakoot pilvet vanhurskautta. Avautukoon maa ja antakoon hedelmänänsä pelastuksen, versokoon se myös vanhurskautta. Minä, Herra, olen sen luonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Voi sitä, joka riitelee tekijänsä kanssa, saviastia saviastiain joukossa-maasta tehtyjä kaikki! Sanooko savi valajallensa: \"Mitä sinä kelpaat tekemään? Sinun työsi on kädettömän työtä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Voi sitä, joka sanoo isälleen: \"Mitä sinä kelpaat siittämään?\" ja äidilleen: \"Mitä sinä kelpaat synnyttämään?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Näin sanoo Herra, Israelin Pyhä, joka on hänet tehnyt: Kysykää tulevaisia minulta ja jättäkää minun haltuuni minun lapseni, minun kätteni teot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Minä olen tehnyt maan ja luonut ihmisen maan päälle; minun käteni ovat levittäneet taivaan, minä olen kutsunut koolle kaikki sen joukot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Minä herätin hänet vanhurskaudessa, ja minä tasoitin kaikki hänen tiensä. Hän rakentaa minun kaupunkini ja päästää vapaiksi minun pakkosiirtolaiseni ilman maksua ja ilman lahjusta, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Näin sanoo Herra: Egyptin työansio ja Etiopian kauppavoitto ja sebalaiset, suurikasvuiset miehet, tulevat sinun tykösi, tulevat sinun omiksesi. Sinun perässäsi he käyvät, kulkevat kahleissa, sinua kumartavat, sinua rukoilevat: \"Ainoastaan sinun tykönäsi on Jumala, ei ole toista, ei yhtään muuta jumalaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Totisesti, sinä olet salattu Jumala, sinä Israelin Jumala, sinä Vapahtaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Häpeän ja pilkan he saavat kaikki, pilkan alaisina he kulkevat kaikki, nuo kuvien tekijät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Mutta Israelin pelastaa Herra iankaikkisella pelastuksella, te ette joudu häpeään ettekä pilkan alaisiksi, ette ikinä, hamaan iankaikkisuuteen saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Sillä näin sanoo Herra, joka on luonut taivaan-hän on Jumala-joka on valmistanut maan ja tehnyt sen; hän on sen vahvistanut, ei hän sitä autioksi luonut, asuttavaksi hän sen valmisti: Minä olen Herra, eikä toista ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'En ole minä puhunut salassa, en pimeässä maan paikassa; en ole sanonut Jaakobin jälkeläisille: etsikää minua tyhjyydestä. Minä Herra puhun vanhurskautta, ilmoitan, mikä oikein on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Kokoontukaa ja tulkaa, lähestykää kaikki, te henkiinjääneet kansakunnista. Eivät ne mitään ymmärrä, jotka kantavat puukuviansa ja rukoilevat jumalaa, joka ei voi auttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Ilmoittakaa ja esiin tuokaa-neuvotelkoot keskenänsä-kuka on tämän julistanut hamasta muinaisuudesta, aikoja sitten ilmoittanut? Enkö minä, Herra! Paitsi minua ei ole yhtään jumalaa; ei ole vanhurskasta ja auttavaa jumalaa muuta kuin minä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Kääntykää minun tyköni ja antakaa pelastaa itsenne, te maan ääret kaikki, sillä minä olen Jumala, eikä toista ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Minä olen vannonut itse kauttani, minun suustani on lähtenyt totuus, peruuttamaton sana: Minun edessäni pitää kaikkien polvien notkistuman, minulle jokaisen kielen valansa vannoman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Ainoastaan Herrassa-niin pitää minusta sanottaman-on vanhurskaus ja voima. Hänen tykönsä tulevat häveten kaikki, jotka ovat palaneet vihasta häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'Herrassa tulee vanhurskaaksi kaikki Israelin siemen, ja hän on heidän kerskauksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Beel vaipuu, Nebo taipuu; heidän kuvansa joutuvat elukkain ja juhtain selkään; mitä te kulkueessa kannoitte, se sälytetään kuormaksi uupuville.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'He taipuvat, he vaipuvat molemmat; he eivät voi pelastaa kuormaa, ja itse he vaeltavat vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Kuulkaa minua, te Jaakobin heimo, te kaikki Israelin heimon tähteet, te, joita on pitänyt kantaa äidinkohdusta asti, nostaa hamasta äidinhelmasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Teidän vanhuuteenne asti minä olen sama, hamaan harmaantumiseenne saakka minä kannan; niin minä olen tehnyt, ja vastedeskin minä nostan, minä kannan ja pelastan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Keneenkä te vertaatte minut, kenenkä rinnalle minut asetatte, kenenkä kaltaiseksi te minut katsotte, että olisimme toistemme vertaiset?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'He kaatavat kultaa kukkarosta ja punnitsevat hopeata vaa\'alla; he palkkaavat kultasepän, ja hän tekee siitä jumalan, jonka eteen he lankeavat maahan ja jota he kumartavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'He nostavat sen olallensa, kantavat ja asettavat sen paikoilleen, ja se seisoo eikä liikahda paikaltansa. Sitä huudetaan avuksi, mutta se ei vastaa, hädästä se ei pelasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Muistakaa tämä ja olkaa vahvat. Menkää itseenne, te luopiot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Muistakaa entisiä ikiajoista asti, sillä minä olen Jumala, eikä toista ole; minä olen Jumala, eikä ole minun vertaistani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Minä ilmoitan alusta asti, mitä tuleva on, ammoisia aikoja ennen, mitä ei vielä ole tapahtunut; minä sanon: minun neuvoni pysyy, kaiken, mitä tahdon, minä teen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Minä olen kutsunut kotkan päivänkoitosta, kaukaisesta maasta neuvopäätökseni miehen. Minkä olen puhunut, sen minä myös toteutan; mitä olen aivoitellut, sen minä myös teen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Kuulkaa minua, te kovasydämiset, jotka olette kaukana vanhurskaudesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Minä olen antanut vanhurskauteni lähestyä, se ei ole kaukana; ei viivy pelastus, jonka minä tuon. Minä annan Siionissa pelastuksen, annan kirkkauteni Israelille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Astu alas ja istu tomuun, sinä neitsyt, tytär Baabel, istu maahan, valtaistuinta vailla, sinä Kaldean tytär; sillä ei sinua enää kutsuta hempeäksi ja hekumalliseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Tartu käsikiviin ja jauha jauhoja, riisu huntusi, nosta helmuksesi, paljasta sääresi, kahlaa jokien poikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Häpysi paljastuu, häpeäsi näkyy; minä kostan enkä ainoatakaan armahda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Meidän lunastajamme nimi on Herra Sebaot, Israelin Pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Istu äänetönnä ja väisty pimeään, sinä Kaldean tytär; sillä ei sinua enää kutsuta valtakuntien valtiattareksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Minä vihastuin kansaani, annoin häväistä perintöni, minä annoin heidät sinun käsiisi; et osoittanut sinä heille sääliä, vanhuksellekin sinä teit ikeesi ylen raskaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Ja sinä sanoit: \"Iäti minä olen valtiatar\", niin ettet näitä mieleesi pannut, et loppua ajatellut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Mutta nyt kuule tämä, sinä hekumassa-eläjä, joka istut turvallisena, joka sanot sydämessäsi: \"Minä, eikä ketään muuta! Minä en ole leskenä istuva enkä lapsettomuudesta tietävä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Mutta nämä molemmat tulevat sinun osaksesi äkisti, yhtenä päivänä: lapsettomuus ja leskeys; ne kohtaavat sinua täydeltänsä, huolimatta velhouksiesi paljoudesta, loitsujesi suuresta voimasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Sinä luotit pahuuteesi, sinä sanoit: \"Ei kukaan minua näe\". Sinun viisautesi ja tietosi, ne sinut eksyttivät, ja niin sinä sanoit sydämessäsi: \"Minä, eikä ketään muuta!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Sentähden kohtaa sinua onnettomuus, jota et osaa manata pois; sinut yllättää tuho, josta et lunnailla pääse, äkkiä kohtaa sinua perikato, aavistamattasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Astu esiin loitsuinesi ja paljoine velhouksinesi, joilla olet vaivannut itseäsi nuoruudestasi asti: ehkä hyvinkin saat avun, ehkä herätät pelkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Sinä olet väsyttänyt itsesi paljolla neuvottelullasi. Astukoot esiin ja auttakoot sinua taivaan mittaajat, tähtien tähystäjät, jotka kuu kuulta ilmoittavat, mitä sinulle tapahtuva on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Katso, he ovat kuin kuivat korret: tuli polttaa heidät; he eivät pelasta henkeään liekin vallasta. Se ei ole hiillos heidän lämmitelläkseen eikä valkea, jonka ääressä istutaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Tämän saat sinä niistä, joista olet vaivaa nähnyt: ne, joiden kanssa olet kauppaa käynyt hamasta nuoruudestasi asti, harhailevat kukin haarallensa, ei kukaan sinua pelasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Kuulkaa tämä, Jaakobin heimo, te, joita kutsutaan Israelin nimellä ja jotka olette lähteneet Juudan lähteestä, jotka vannotte Herran nimeen ja tunnustatte Israelin Jumalan, mutta ette totuudessa ettekä vanhurskaudessa-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'sillä heitä kutsutaan pyhän kaupungin mukaan ja he pitävät tukenansa Israelin Jumalaa, jonka nimi on Herra Sebaot:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Entiset minä olen aikoja ennen ilmoittanut, minun suustani ne ovat lähteneet, ja minä olen ne kuuluttanut. Äkkiä minä panin ne täytäntöön, ja ne tapahtuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Koska minä tiesin, että sinä olet paatunut, että sinun niskajänteesi on rautaa ja otsasi vaskea,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'niin minä ilmoitin ne sinulle aikoja ennen, kuulutin ne sinulle, ennenkuin ne tapahtuivat, ettet sanoisi: \"Epäjumalankuvani on ne tehnyt, veistetty kuvani ja valettu kuvani on niin säätänyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Sinä olet ne kuullut, katso nyt kaikkea: ettekö sitä tunnusta? Tästä lähtien minä kuulutan sinulle uusia, salatuita, joita et ole tietänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Ne ovat luodut nyt, eikä aikoja sitten, ennen tätä päivää et ole niistä kuullut, ettet saattaisi sanoa: \"Katso, jo minä ne tiesin!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Et ole sinä niistä kuullut etkä tietänyt, ei ole sinun korvasi niille aikaisemmin auennut; sillä minä tiesin, että sinä olet aivan uskoton ja luopioksi kutsuttu hamasta äidin kohdusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Oman nimeni tähden minä olen pitkämielinen, ylistykseni tähden minä hillitsen vihani, etten sinua tuhoaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Katso, minä olen sinua sulattanut, hopeata saamatta, minä olen sinua koetellut kärsimyksen pätsissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Itseni, itseni tähden minä sen teen; sillä kuinka onkaan minun nimeäni häväisty! Kunniaani en minä toiselle anna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Kuule minua, Jaakob, ja sinä, Israel, jonka minä olen kutsunut: Minä olen aina sama, minä olen ensimmäinen, minä olen myös viimeinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Minun käteni on perustanut maan, minun oikea käteni on levittänyt taivaan; minä kutsun ne, ja siinä ne ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Kokoontukaa kaikki ja kuulkaa-kuka niistä muista on ilmoittanut tämän: että hän, jota Herra rakastaa, tekee hänen tahtonsa Baabelia vastaan, on hänen käsivartenaan kaldealaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Minä, minä olen puhunut, minä olen hänet kutsunut, olen hänet tuonut, ja hän on menestynyt teillänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Lähestykää minua, kuulkaa tämä: Alkujaankaan minä en ole puhunut salassa; kun nämä tapahtuivat, olin minä jo siellä. Ja nyt Herra, Herra on lähettänyt minut ynnä oman Henkensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Näin sanoo Herra, sinun lunastajasi, Israelin Pyhä: Minä olen Herra, sinun Jumalasi, joka opetan sinulle, mikä hyödyllistä on, johdatan sinua sitä tietä, jota sinun tulee käydä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Jospa ottaisit minun käskyistäni vaarin, niin olisi sinun rauhasi niinkuin virta ja sinun vanhurskautesi niinkuin meren aallot;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'sinun lastesi paljous olisi niinkuin hiekka, sinun kohtusi hedelmä niinkuin hiekkajyväset, sen nimi ei häviäisi, ei katoaisi minun kasvojeni edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Lähtekää Baabelista, paetkaa Kaldeasta; riemuhuudoin ilmoittakaa, kuuluttakaa tämä, viekää tieto siitä maan ääriin asti, sanokaa: \"Herra on lunastanut palvelijansa Jaakobin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Eivät he janoa kärsineet, kun hän heitä kuljetti erämaitten halki; hän vuodatti heille vettä kalliosta, hän halkaisi kallion, ja vettä virtasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Jumalattomilla ei ole rauhaa, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Kuulkaa minua, te merensaaret, ja tarkatkaa, kaukaiset kansat. Herra on minut kutsunut hamasta äidinkohdusta saakka, hamasta äitini helmasta minun nimeni maininnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Hän teki minun suuni terävän miekan kaltaiseksi, kätki minut kätensä varjoon; hän teki minut hiotuksi nuoleksi, talletti minut viineensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Ja hän sanoi minulle: \"Sinä olet minun palvelijani, sinä Israel, jossa minä osoitan kirkkauteni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Mutta minä sanoin: \"Hukkaan minä olen itseäni vaivannut, kuluttanut voimani turhaan ja tyhjään; kuitenkin on minun oikeuteni Herran huomassa, minun palkkani on Jumalan tykönä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Ja nyt sanoo Herra, joka on minut palvelijakseen valmistanut hamasta äitini kohdusta, palauttamaan Jaakobin hänen tykönsä, niin että Israel koottaisiin hänen omaksensa-ja minä olen kallis Herran silmissä, minun Jumalani on tullut minun voimakseni-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'hän sanoo: Liian vähäistä on sinulle, joka olet minun palvelijani, kohottaa ennalleen Jaakobin sukukunnat ja tuoda takaisin Israelin säilyneet: minä panen sinut pakanain valkeudeksi, että minulta tulisi pelastus maan ääriin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Näin sanoo Herra, Israelin lunastaja, hänen Pyhänsä, syvästi halveksitulle, kansan inhoamalle, valtiaitten orjalle: Kuninkaat näkevät sen ja nousevat seisomaan, ruhtinaat näkevät ja kumartuvat maahan Herran tähden, joka on uskollinen, Israelin Pyhän tähden, joka on sinut valinnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Näin sanoo Herra: Otollisella ajalla minä olen sinua kuullut ja pelastuksen päivänä sinua auttanut; minä olen valmistanut sinut ja pannut sinut kansoille liitoksi, kohottamaan ennalleen maan, jakamaan hävitetyt perintöosat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'sanomaan vangituille: \"Käykää ulos!\" ja pimeässä oleville: \"Tulkaa esiin!\" Teiden varsilta he löytävät laitumen, kaikki kalliokukkulat ovat heillä laidunpaikkoina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Ei heidän tule nälkä eikä jano, ei hietikon helle eikä aurinko satu heihin, sillä heidän armahtajansa johdattaa heitä ja vie heidät vesilähteille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Minä teen kaikki vuoreni teiksi, ja minun valtatieni kulkevat korkealla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Katso heitä, he tulevat kaukaa! Katso, nuo pohjoisesta, nuo lännestä, nuo Siinimin maalta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Riemuitkaa, te taivaat, iloitse, sinä maa, puhjetkaa riemuun, te vuoret, sillä Herra lohduttaa kansaansa ja armahtaa kurjiansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Mutta Siion sanoo: \"Herra on minut hyljännyt, Herra on minut unhottanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Unhottaako vaimo rintalapsensa, niin ettei hän armahda kohtunsa poikaa? Ja vaikka he unhottaisivatkin, minä en sinua unhota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Katso, kätteni hipiään olen minä sinut piirtänyt, sinun muurisi ovat aina minun edessäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Sinun lapsesi tulevat rientäen; sinun hävittäjäsi ja raunioiksi-raastajasi menevät sinun luotasi pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Nosta silmäsi ja katso ympärillesi: he kokoontuvat, he tulevat sinun tykösi kaikki. Niin totta kuin minä elän, sanoo Herra, sinä puet heidät kaikki yllesi niinkuin koristeen ja sidot heidät vyöllesi niinkuin morsian vyönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Sillä sinä-sinun rauniosi ja autiot paikkasi, sinun hävitetty maasi-sinä käyt silloin ahtaaksi asukkaille, ja kaukana ovat ne, jotka sinua söivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Vielä saavat sinun lapsettomuutesi lapset sanoa korviesi kuullen: \"Paikka on minulle ahdas, tee tilaa, että voin asua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Silloin sinä sanot sydämessäsi: \"Kuka on nämä minulle synnyttänyt? Minä olin lapseton ja hedelmätön, karkoitettu ja hyljätty. Kuka on heidät kasvattanut? Katso, minä olin jätetty yksin. Missä nämä silloin olivat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Näin sanoo Herra, Herra: Katso, minä nostan käteni kansakuntien puoleen, kohotan lippuni kansoja kohti, niin he tuovat sinun poikasi sylissänsä ja kantavat sinun tyttäresi olkapäillään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Kuninkaista tulee sinulle lastenhoitajat, heidän ruhtinattaristaan sinulle imettäjät. Sinun edessäsi he kumartuvat maahan kasvoillensa ja nuolevat tomun sinun jaloistasi. Silloin sinä tiedät, että minä olen Herra ja että ne, jotka minua odottavat, eivät häpeään joudu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Otetaanko sankarilta saalis, tai riistetäänkö vangit vanhurskaalta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Sillä näin sanoo Herra: Vaikka vangit otettaisiinkin sankarilta ja saalis riistettäisiin väkevältä, niin minä kuitenkin taistelen sitä vastaan, joka sinua vastaan taistelee, ja minä pelastan sinun lapsesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Minä panen sinun sortajasi syömään omaa lihaansa, ja he juopuvat omasta verestään niinkuin rypälemehusta; ja kaikki liha on tietävä, että minä, Herra, olen sinun pelastajasi, että Jaakobin Väkevä on sinun lunastajasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Näin sanoo Herra: Missä on teidän äitinne erokirja, jolla olisin lähettänyt hänet pois? Tai kuka on minun velkojani, jolle minä olisin teidät myynyt? Katso, pahojen tekojenne tähden te olette myydyt, teidän rikkomustenne tähden on äitinne lähetetty pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Miksi ei ollut ketään, kun minä tulin, miksi ei kukaan vastannut, kun minä huusin? Onko minun käteni liian lyhyt vapahtamaan, olenko minä voimaton auttamaan? Katso, nuhtelullani minä kuivaan meren, minä teen virrat erämaaksi, niin että niitten kalat mätänevät, kun ei ole vettä; ne kuolevat janoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Minä puetan taivaat mustiin ja panen murhepuvun niitten verhoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Herra, Herra on minulle antanut opetuslasten kielen, niin että minä taidan sanalla virvoittaa väsynyttä; hän herättää aamu aamulta, herättää minun korvani kuulemaan opetuslasten tavalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Herra, Herra on avannut minun korvani; minä en ole niskoitellut, en vetäytynyt pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Selkäni minä annoin lyötäväksi, poskieni parran revittäväksi, en peittänyt kasvojani pilkalta ja syljeltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Herra, Herra auttaa minua; sentähden ei minuun pilkka koskenut, sentähden tein kasvoni koviksi kuin piikivi, sillä minä tiedän, etten häpeään joudu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Lähellä on hän, joka minut vanhurskaaksi tuomitsee. Kuka voi minun kanssani riidellä? Astukaamme yhdessä esiin! Kuka on minun vastapuoleni? Tulkoon tänne lähelleni!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Katso, Herra, Herra auttaa minua; kuka minut syylliseksi tuomitsee? Katso, kaikki he hajoavat kuin vaate; koi heidät syö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Kuka teistä pelkää Herraa ja kuulee hänen palvelijansa ääntä? Joka vaeltaa pimeydessä ja valoa vailla, se luottakoon Herran nimeen ja turvautukoon Jumalaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Mutta katso, te kaikki, jotka palon sytytätte, te palavilla nuolilla varustetut, suistukaa oman tulenne liekkeihin, niihin palaviin nuoliin, jotka olette sytyttäneet. Minun kädestäni tämä teille tulee; vaivassa täytyy teidän asua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Kuulkaa minua, te jotka vanhurskauteen pyritte, te jotka Herraa etsitte. Katsokaa kalliota, josta olette lohkaistut, ja kaivos-onkaloa, josta olette kaivetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Katsokaa Aabrahamia, isäänne, ja Saaraa, joka teidät synnytti. Sillä hän oli vain yksi, kun minä hänet kutsuin; mutta minä siunasin hänet ja enensin hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Niin Herra lohduttaa Siionin, lohduttaa kaikki sen rauniot, hän tekee sen erämaasta kuin Eedenin ja sen arosta kuin Herran puutarhan; siellä on oleva riemu ja ilo, kiitos ja ylistysvirren ääni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Kuuntele minua, kansani, kuule minua, kansakuntani, sillä minusta lähtee laki, ja minä panen oikeuteni valkeudeksi kansoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Lähellä on minun vanhurskauteni, minun autuuteni ilmestyy, minun käsivarteni tuomitsevat kansat; minua odottavat merensaaret ja panevat toivonsa minun käsivarteeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Nostakaa silmänne taivasta kohti ja katsokaa maata, joka alhaalla on, sillä taivaat katoavat kuin savu ja maa hajoaa kuin vaate ja sen asukkaat kuolevat kuin sääsket, mutta minun autuuteni pysyy iankaikkisesti, ja minun vanhurskauteni ei kukistu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Kuulkaa minua, te jotka vanhurskauden tunnette, kansa, jonka sydämessä on minun lakini: älkää peljätkö ihmisten pilkkaa älkääkä kauhistuko heidän herjauksiansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Sillä koi syö heidät niinkuin vaatteen, koiperhonen syö heidät niinkuin villan, mutta minun vanhurskauteni pysyy iankaikkisesti, minun autuuteni polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Heräjä, heräjä, pukeudu voimaan, sinä Herran käsivarsi; heräjä niinkuin muinaisina päivinä, ammoisten sukupolvien aikoina. Etkö sinä ole se, joka löit Rahabin kuoliaaksi, joka lävistit lohikäärmeen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Etkö sinä ole se, joka kuivasit meren, suuren syvyyden vedet, joka teit meren syvänteet tieksi lunastettujen kulkea?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Niin Herran vapahdetut palajavat ja tulevat Siioniin riemuiten, päänsä päällä iankaikkinen ilo. Riemu ja ilo saavuttavat heidät, mutta murhe ja huokaus pakenevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Minä, minä olen teidän lohduttajanne; mikä olet sinä, että pelkäät ihmistä, joka on kuolevainen, ihmislasta, jonka käy niinkuin ruohon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'ja unhotat Herran, joka on sinut tehnyt, joka on levittänyt taivaan ja perustanut maan, ja vapiset alati, kaiket päivät, sortajan vihaa, kun hän tähtää tuhotaksensa? Mutta missä on sortajan viha?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Pian päästetään kumaraan koukistunut vapaaksi kahleistaan: ei hän kuole, ei kuoppaan jää, eikä häneltä leipä puutu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Minä olen Herra, sinun Jumalasi, joka liikutan meren, niin että sen aallot pauhaavat, jonka nimi on Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Ja minä olen pannut sanani sinun suuhusi, minä olen kätkenyt sinut käteni varjoon, pystyttääkseni taivaan ja perustaakseni maan ja sanoakseni Siionille: \"Sinä olet minun kansani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Heräjä, heräjä, nouse, Jerusalem, sinä joka olet juonut Herran kädestä hänen vihansa maljan, joka olet päihdyttävän pikarin juonut, tyhjäksi särpinyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Ei kukaan kaikista lapsista, jotka hän oli synnyttänyt, ollut häntä taluttamassa; ei kukaan kaikista lapsista, jotka hän oli kasvattanut, hänen käteensä tarttunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Nämä kohtasivat sinua kaksittain-kuka sinua surkuttelee-tuho ja turmio, nälkä ja miekka; millä voin sinua lohduttaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Tajuttomina makasivat sinun poikasi joka kadun kulmassa, niinkuin antiloopit pyydyshaudassa, täynnä Herran vihaa, sinun Jumalasi nuhtelua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Sentähden kuule tätä, sinä poloinen, joka olet juopunut, vaikka et viinistä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Näin sanoo sinun Herrasi, Herra sinun Jumalasi, joka ajaa kansansa asian: Katso, minä otan sinun kädestäsi päihdyttävän maljan, vihani pikarin; ei tarvitse sinun siitä enää juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Ja minä panen sen sinun vaivaajaisi käteen, jotka sinulle sanoivat: \"Lankea maahan, kulkeaksemme sinun päällitsesi\"; ja sinä panit selkäsi maaksi ja kaduksi kulkijoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Heräjä, heräjä, pukeudu voimaasi, Siion; pukeudu juhlapukuusi, Jerusalem, sinä pyhä kaupunki. Sillä ei koskaan enää astu sinun sisällesi ympärileikkaamaton eikä saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Pudista päältäsi tomu, nouse istuimellesi, Jerusalem; irroita kahleet kaulastasi, sinä vangittu tytär Siion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Sillä näin sanoo Herra: Ilmaiseksi teidät myytiin, rahatta teidät lunastetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Sillä näin sanoo Herra, Herra: Minun kansani meni ensin alas Egyptiin asumaan siellä muukalaisena, ja sitten Assur sorti sitä ilman syytä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Ja nyt, mitä minulla on tekemistä täällä, sanoo Herra, kun minun kansani on viety pois ilmaiseksi? Sen valtiaat elämöivät, sanoo Herra, ja minun nimeäni pilkataan alati, kaiket päivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Sentähden minun kansani on tunteva minun nimeni, sentähden se on tunteva sinä päivänä, että minä olen se, joka sanon: \"Katso, tässä minä olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Kuinka suloiset ovat vuorilla ilosanoman tuojan jalat, hänen, joka julistaa rauhaa, ilmoittaa hyvän sanoman, joka julistaa pelastusta, sanoo Siionille: \"Sinun Jumalasi on kuningas!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Kuule! Vartijasi korottavat äänensä, kaikki he riemuitsevat, sillä he näkevät silmästä silmään, kuinka Herra palajaa Siioniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Huutakaa ilosta, riemuitkaa, kaikki te Jerusalemin rauniot, sillä Herra lohduttaa kansansa, lunastaa Jerusalemin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Herra paljastaa pyhän käsivartensa kaikkien kansojen nähden, ja kaikki maan ääret saavat nähdä meidän Jumalamme autuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Pois, pois! Lähtekää sieltä, älkää koskeko saastaiseen; lähtekää sen keskeltä, puhdistautukaa, te Herran aseenkantajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Sillä ei teidän tarvitse kiiruusti lähteä, ei paeten kulkea; sillä Herra käy teidän edellänne, Israelin Jumala seuraa suojananne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Katso, minun palvelijani menestyy, hän on nouseva, kohoava ja sangen korkea oleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Niinkuin monet kauhistuivat häntä-sillä niin runneltu, ei enää ihmisenkaltainen, oli hänen muotonsa, hänen hahmonsa ei ollut ihmislasten hahmo-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'niin hän on saattava ihmetyksiin monet kansat, hänen tähtensä kuninkaat sulkevat suunsa. Sillä mitä heille ei ikinä ole kerrottu, sen he saavat nähdä, mitä he eivät ole kuulleet, sen he saavat havaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Kuka uskoo meidän saarnamme, kenelle Herran käsivarsi ilmoitetaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Hän kasvoi Herran edessä niinkuin vesa, niinkuin juuri kuivasta maasta. Ei ollut hänellä vartta eikä kauneutta; me näimme hänet, mutta ei ollut hänellä muotoa, johon me olisimme mielistyneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Hän oli ylenkatsottu, ihmisten hylkäämä, kipujen mies ja sairauden tuttava, jota näkemästä kaikki kasvonsa peittivät, halveksittu, jota emme minäkään pitäneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Mutta totisesti, meidän sairautemme hän kantoi, meidän kipumme hän sälytti päällensä. Me pidimme häntä rangaistuna, Jumalan lyömänä ja vaivaamana,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'mutta hän on haavoitettu meidän rikkomustemme tähden, runneltu meidän pahain tekojemme tähden. Rangaistus oli hänen päällänsä, että meillä rauha olisi, ja hänen haavainsa kautta me olemme paratut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Me vaelsimme kaikki eksyksissä niinkuin lampaat, kukin meistä poikkesi omalle tielleen. Mutta Herra heitti hänen päällensä kaikkien meidän syntivelkamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Häntä piinattiin, ja hän alistui siihen eikä suutansa avannut; niinkuin karitsa, joka teuraaksi viedään, niinkuin lammas, joka on ääneti keritsijäinsä edessä, niin ei hän suutansa avannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Ahdistettuna ja tuomittuna hänet otettiin pois, mutta kuka hänen polvikunnastaan sitä ajatteli? Sillä hänet temmattiin pois elävien maasta; minun kansani rikkomuksen tähden kohtasi rangaistus häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Hänelle annettiin hauta jumalattomain joukossa; mutta rikkaan tykö hän tuli kuoltuansa, sillä hän ei ollut vääryyttä tehnyt eikä petosta ollut hänen suussansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Mutta Herra näki hyväksi runnella häntä, lyödä hänet sairaudella. Jos sinä panet hänen sielunsa vikauhriksi, saa hän nähdä jälkeläisiä ja elää kauan, ja Herran tahto toteutuu hänen kauttansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Sielunsa vaivan tähden hän saa nähdä sen ja tulee ravituksi. Tuntemuksensa kautta hän, minun vanhurskas palvelijani, vanhurskauttaa monet, sälyttäen päällensä heidän pahat tekonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Sentähden minä jaan hänelle osan suurten joukossa, ja väkevien kanssa hän saalista jakaa; sillä hän antoi sielunsa alttiiksi kuolemaan, ja hänet luettiin pahantekijäin joukkoon, hän kantoi monien synnit, ja hän rukoili pahantekijäin puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Riemuitse, sinä hedelmätön, joka et ole synnyttänyt, huuda ilosta ja riemahda, sinä, joka et ole synnytyskivuissa ollut. Sillä hyljätyllä on lapsia enemmän kuin aviovaimolla, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Tee avaraksi telttasi sija, levennettäköön sinun majojesi seinien kangas. Älä säästele! Pidennä telttaköytesi ja vahvista vaarnasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Sillä sinä olet leviävä oikealle ja vasemmalle, sinun jälkeläisesi ottavat omiksensa kansat ja tekevät autiot kaupungit asutuiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Älä pelkää, sillä et sinä häpeään joudu; älä ole häpeissäsi, sillä et sinä ole pettyvä. Nuoruutesi häpeän sinä olet unhottava, leskeytesi pilkkaa et ole enää muistava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Sillä hän, joka sinut teki, on sinun aviomiehesi, Herra Sebaot on hänen nimensä, sinun lunastajasi on Israelin Pyhä, hän joka kaiken maan Jumalaksi kutsutaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Sillä niinkuin hyljätyn, syvästi murheellisen vaimon on Herra sinut kutsunut-nuoruuden vaimon, joka on ollut halveksittu, sanoo sinun Jumalasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Vähäksi silmänräpäykseksi minä hylkäsin sinut, mutta minä kokoan sinut jälleen suurella laupeudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'Ylitsevuotavassa vihassani minä peitin sinulta kasvoni silmänräpäykseksi, mutta minä armahdan sinut iankaikkisella armolla, sanoo Herra, sinun lunastajasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Sillä tämä on minulle, niinkuin olivat Nooan vedet: niinkuin minä vannoin, etteivät Nooan vedet enää tulvi maan ylitse, niin minä vannon, etten enää vihastu sinuun enkä sinua nuhtele.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Sillä vuoret väistykööt ja kukkulat horjukoot, mutta minun armoni ei sinusta väisty, eikä minun rauhanliittoni horju, sanoo Herra, sinun armahtajasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Sinä kurja, myrskyn raastama, sinä lohduton! Katso, minä muuraan sinun kivesi kiiltokivellä, panen sinun perustuksesi safiireista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'minä teen sinun harjasi rubiineista ja sinun porttisi kristalleista ja koko sinun ympärysmuurisi jalokivistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Sinun lapsesi ovat kaikki Herran opetuslapsia, ja suuri rauha on sinun lapsillasi oleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Sinut vahvistetaan vanhurskaudella; sinä olet oleva kaukana väkivallasta, sillä ei sinulla ole pelkäämistä, ja kaukana hävityksestä, sillä ei se sinua lähesty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Jos sinun kimppuusi karataan, ei se ole minusta; joka kimppuusi karkaa, se eteesi kaatuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Katso, minä olen luonut sepän, joka lietsoo hiilivalkeata ja kuonnuttaa aseen käytäntöönsä; mutta minä olen myös luonut tuhontuottajan hävittämään sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Jokainen ase, joka valmistetaan sinun varallesi, on oleva tehoton; ja jokaisen kielen, joka nousee käymään sinun kanssasi oikeutta, sinä osoitat vääräksi. Tämä on Herran palvelijain perintöosa, tämä heidän vanhurskautensa, minulta saatu, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Kuulkaa, kaikki janoavaiset, tulkaa veden ääreen. Tekin, joilla ei ole rahaa, tulkaa, ostakaa ja syökää; tulkaa, ostakaa ilman rahatta, ilman hinnatta viiniä ja maitoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Miksi annatte rahan siitä, mikä ei ole leipää, ja työnne ansion siitä, mikä ei ravitse? Kuulkaa minua, niin saatte syödä hyvää, ja teidän sielunne virvoittuu lihavuuden ääressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Kallistakaa korvanne ja tulkaa minun tyköni; kuulkaa, niin teidän sielunne saa elää. Ja minä teen teidän kanssanne iankaikkisen liiton, annan lujat Daavidin armot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Katso, hänet minä asetin kansoille todistajaksi, kansojen ruhtinaaksi ja käskijäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Katso, sinä olet kutsuva pakanoita, joita sinä et tunne, ja pakanat, jotka eivät sinua tunne, rientävät sinun tykösi Herran, sinun Jumalasi, tähden, Israelin Pyhän tähden, sillä hän kirkastaa sinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Etsikää Herraa silloin, kun hänet löytää voidaan; huutakaa häntä avuksi, kun hän läsnä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Jumalaton hyljätköön tiensä ja väärintekijä ajatuksensa ja palatkoon Herran tykö, niin hän armahtaa häntä, ja meidän Jumalamme tykö, sillä hänellä on paljon anteeksiantamusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Sillä minun ajatukseni eivät ole teidän ajatuksianne, eivätkä teidän tienne ole minun teitäni, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Vaan niin paljon korkeampi kuin taivas on maata, ovat minun tieni korkeammat teidän teitänne ja minun ajatukseni teidän ajatuksianne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Sillä niinkuin sade ja lumi, joka taivaasta tulee, ei sinne palaja, vaan kostuttaa maan, tekee sen hedelmälliseksi ja kasvavaksi, antaa kylväjälle siemenen ja syöjälle leivän,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'niin on myös minun sanani, joka minun suustani lähtee: ei se minun tyköni tyhjänä palaja, vaan tekee sen, mikä minulle otollista on, ja saa menestymään sen, mitä varten minä sen lähetin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Sillä iloiten te lähdette, ja rauhassa teitä saatetaan; vuoret ja kukkulat puhkeavat riemuun teidän edessänne, ja kaikki kedon puut paukuttavat käsiänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Orjantappurain sijaan on kasvava kypressejä, nokkosten sijaan on kasvava myrttipuita; ja se tulee Herran kunniaksi, iankaikkiseksi merkiksi, joka ei häviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Näin sanoo Herra: Noudattakaa oikeutta ja tehkää vanhurskaus, sillä minun autuuteni on lähellä ja minun vanhurskauteni ilmestyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Autuas se ihminen, joka tämän tekee, se ihmislapsi, joka tässä pysyy, joka pitää sapatin eikä sitä riko, joka varoo kätensä tekemästä mitään pahaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Älköön sanoko muukalainen, joka on liittynyt Herraan: \"Herra erottaa minut peräti kansastansa\", älköönkä kuohittu sanoko: \"Minä olen kuiva puu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Sillä näin sanoo Herra: Kuohituille, jotka pitävät minun sapattini ja valitsevat sen, mikä minulle otollista on, ja pysyvät minun liitossani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'heille minä annan huoneessani ja muurieni sisällä muistomerkin ja nimen, joka on poikia ja tyttäriä parempi; minä annan heille iankaikkisen nimen, joka ei häviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Ja muukalaiset, jotka ovat liittyneet Herraan, palvellakseen häntä ja rakastaakseen Herran nimeä, ollakseen hänen palvelijoitansa, kaikki, jotka pitävät sapatin eivätkä sitä riko ja pysyvät minun liitossani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'ne minä tuon pyhälle vuorelleni ja ilahutan heitä rukoushuoneessani, ja heidän polttouhrinsa ja teurasuhrinsa ovat otolliset minun alttarillani, sillä minun huoneeni on kutsuttava kaikkien kansojen rukoushuoneeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Herra, Herra sanoo, hän, joka kokoaa Israelin karkoitetut: Minä kokoan vielä muitakin sen koottujen lisäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Kaikki kedon eläimet, tulkaa syömään, te metsän eläimet kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Israelin vartijat ovat kaikki sokeita, eivät he mitään käsitä; he ovat kaikki mykkiä koiria, jotka eivät osaa haukkua. He näkevät unta, makailevat ja nukkuvat mielellään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Ja näillä koirilla on vimmainen nälkä, ei niitä mikään täytä. Ja tällaisia ovat paimenet! Eivät pysty mitään huomaamaan, ovat kaikki kääntyneet omille teilleen, etsivät kukin omaa voittoansa, kaikki tyynni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, '\"Tulkaa, minä hankin viiniä, ryypätkäämme väkevätä; olkoon huomispäivä niinkuin tämäkin ylenpalttisen ihana.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Vanhurskas hukkuu, eikä kukaan pane sitä sydämelleen, hurskaat miehet otetaan pois kenenkään siitä välittämättä, sillä vanhurskas otetaan pois pahuutta näkemästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Hän menee rauhaan: jotka vakaasti vaeltavat, he saavat levätä kammioissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Mutta te tulkaa tänne, te velhottaren lapset, te avionrikkojamiehen ja porttovaimon sikiöt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Kenellä te iloanne pidätte? Kenelle avaatte suunne ammolleen ja kieltä pitkälle pistätte? Ettekö te ole rikoksen lapsia, valheen sikiöitä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Te, jotka hehkutte himosta tammien varjossa, jokaisen vihreän puun alla, te, jotka teurastatte lapsia laaksoissa, kallionrotkoissa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Laakson sileät paadet ovat sinun osasi, siinä se on, sinun arpasi; niille sinä olet juomauhrit vuodattanut, ruokauhrit uhrannut. Siihenkö minä tyytyisin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Korkealle ja valtavalle vuorelle sinä valmistit vuoteesi; sinne sinä myös nousit teurasuhria uhraamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Oven ja pihtipielen taakse sinä panit omat merkkisi. Sillä minusta luopuen sinä paljastit itsesi ja nousit vuoteellesi, teit sen tilavaksi; sinä sovit kaupoista heidän kanssaan, makasit heidän kanssaan mielelläsi, näit heidän häpynsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Sinä kuljit kuninkaan tykö öljyinesi, runsaine voiteinesi; sinä lähetit sanansaattajasi kauas, laskeuduit alas tuonelaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Sinä väsyit matkasi pituudesta, et kuitenkaan sanonut: \"Turha vaiva!\" Sinä sait elpynyttä voimaa, sentähden et heikoksi käynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Ketä sinä arkailit ja pelkäsit, koska vilpistelit etkä minua muistanut, et minusta välittänyt? Eikö niin: minä olen ollut vaiti aina ikiajoista asti, ja niin et sinä minua pelkää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Mutta minä ilmoitan, mitä on sinun vanhurskautesi ja sinun tekosi; ne eivät sinua auta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Kun sinä huudat, auttakoon sinua jumaliesi joukko! Mutta tuuli vie ne kaikki, henkäys ottaa ne pois. Mutta joka minuun turvaa, se perii maan ja ottaa omaksensa minun pyhän vuoreni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Hän sanoo: Tehkää, tehkää tie, tasoittakaa tie, poistakaa kompastuskivet minun kansani tieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Sillä näin sanoo Korkea ja Ylhäinen, jonka asumus on iankaikkinen ja jonka nimi on Pyhä: Minä asun korkeudessa ja pyhyydessä ja niitten tykönä, joilla on särjetty ja nöyrä henki, että minä virvoittaisin nöyrien hengen ja saattaisin särjettyjen sydämet eläviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Sillä en minä iankaiken riitele enkä vihastu ainiaaksi; muutoin henki nääntyisi minun kasvojeni edessä, ne sielut, jotka minä tehnyt olen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Hänen ahneutensa synnin tähden minä vihastuin; minä löin häntä, kätkin itseni ja olin vihastunut. Mutta hän luopui minusta ja kulki oman sydämensä tietä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Minä olen nähnyt hänen tiensä, mutta minä parannan hänet ja johdatan häntä ja annan jälleen lohdutuksen hänelle ja hänen surevillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Minä luon huulten hedelmän, rauhan, rauhan kaukaisille ja läheisille, sanoo Herra, ja minä parannan hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Mutta jumalattomat ovat kuin kuohuva meri, joka ei voi tyyntyä ja jonka aallot kuohuttavat muraa ja mutaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Jumalattomilla ei ole rauhaa, sanoo minun Jumalani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Huuda täyttä kurkkua, älä säästä, korota äänesi niinkuin pasuna, ilmoita minun kansalleni heidän rikoksensa ja Jaakobin huoneelle heidän syntinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Minua he muka etsivät joka päivä ja haluavat tietoa minun teistäni niinkuin kansa, joka tekee vanhurskautta eikä hylkää Jumalansa oikeutta. He vaativat minulta vanhurskaita tuomioita, haluavat, että Jumala heitä lähestyisi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, '\"Miksi me paastoamme, kun et sinä sitä näe, kuritamme itseämme, kun et sinä sitä huomaa?\" Katso, paastopäivänänne te ajatte omia asioitanne ja ahdistatte työhön kaiken työväkenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Katso, riidaksi ja toraksi te paastoatte, lyödäksenne jumalattomalla nyrkillä. Te ette nyt paastoa niin, että teidän äänenne kuultaisiin korkeudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Tällainenko on se paasto, johon minä mielistyn, se päivä, jona ihminen kurittaa itseänsä? Jos kallistaa päänsä kuin kaisla ja makaa säkissä ja tuhassa, sitäkö sinä sanot paastoksi ja päiväksi, joka on Herralle otollinen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Eikö tämä ole paasto, johon minä mielistyn: että avaatte vääryyden siteet, irroitatte ikeen nuorat, ja päästätte sorretut vapaiksi, että särjette kaikki ikeet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Eikö tämä: että taitat leipäsi isoavalle ja viet kurjat kulkijat huoneeseesi, kun näet alastoman, vaatetat hänet etkä kätkeydy siltä, joka on omaa lihaasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Silloin sinun valkeutesi puhkeaa esiin niinkuin aamurusko, ja haavasi kasvavat nopeasti umpeen; sinun vanhurskautesi käy sinun edelläsi, ja Jumalan kunnia seuraa suojanasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Silloin sinä rukoilet, ja Herra vastaa, sinä huudat, ja hän sanoo: \"Katso, tässä minä olen\". Jos sinä keskuudestasi poistat ikeen, sormella-osoittelun ja vääryyden puhumisen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'jos taritset elannostasi isoavalle ja ravitset vaivatun sielun, niin valkeus koittaa sinulle pimeydessä, ja sinun pilkkopimeäsi on oleva niinkuin keskipäivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Ja Herra johdattaa sinua alati ja ravitsee sinun sielusi kuivissa erämaissa; hän vahvistaa sinun luusi, ja sinä olet oleva niinkuin runsaasti kasteltu puutarha, niinkuin lähde, josta vesi ei koskaan puutu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Sinun jälkeläisesi rakentavat jälleen ikivanhat rauniot, sinä kohotat perusmuurit, muinaisten polvien laskemat; ja sinun nimesi on oleva: \"halkeamain umpeenmuuraaja\" ja \"teitten korjaaja maan asuttamiseksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Jos sinä pidätät jalkasi sapattia rikkomasta, niin ettet toimita omia asioitasi minun pyhäpäivänäni, vaan kutsut sapatin ilopäiväksi, Herran pyhäpäivän kunnioitettavaksi ja kunnioitat sitä, niin ettet toimita omia toimiasi, et aja omia asioitasi etkä puhu joutavia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'silloin on ilosi oleva Herrassa, ja minä kuljetan sinut maan kukkuloitten ylitse, ja minä annan sinun nauttia isäsi Jaakobin perintöosaa. Sillä Herran suu on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Katso, ei Herran käsi ole liian lyhyt auttamaan, eikä hänen korvansa kuuro kuulemaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'vaan teidän pahat tekonne erottavat teidät Jumalastanne, ja teidän syntinne peittävät teiltä hänen kasvonsa, niin ettei hän kuule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Sillä teidän kätenne ovat tahratut verellä ja sormenne vääryydellä; teidän huulenne puhuvat valhetta, teidän kielenne latelee petosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Ei kukaan vaadi oikeuteen vanhurskaasti, eikä kukaan käräjöi rehellisesti. He turvautuvat tyhjään ja puhuvat vilppiä, kantavat kohdussaan tuhoa ja synnyttävät turmion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Myrkkyliskon munia he hautovat, hämähäkin verkkoja he kutovat; joka niitä munia syö, se kuolee, rikkipoljetusta puhkeaa kyykäärme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Heidän verkkonsa eivät kelpaa vaatteeksi, heidän tekemäänsä ei voi verhoutua; heidän työnsä ovat vääryyden töitä, ja heidän kätensä ovat täynnä väkivallan tekoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Heidän jalkansa juoksevat pahuuteen, kiiruhtavat vuodattamaan viatonta verta; heidän ajatuksensa ovat vääryyden ajatuksia, tuho ja turmio on heidän teillänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Rauhan tietä he eivät tunne, oikeutta ei ole heidän askeleissansa; polkunsa he tekevät mutkaisiksi, ei kukaan, joka niitä käy, tunne rauhaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Sentähden on oikeus meistä kaukana, eikä vanhurskaus saavuta meitä; me odotamme valoa, mutta katso, on pimeä, aamunkoittoa, mutta vaellamme yön synkeydessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Me haparoimme seinää pitkin niinkuin sokeat, haparoimme niinkuin silmiä vailla; me kompastelemme sydänpäivällä niinkuin hämärässä, me olemme terveitten keskellä niinkuin kuolleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Me murisemme kaikki kuin karhut ja kujerramme kuin kyyhkyset; me odotamme oikeutta, mutta sitä ei tule, pelastusta, mutta se on kaukana meistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Sillä meidän rikoksemme ovat monilukuiset sinun edessäsi, ja meidän syntimme todistavat meitä vastaan; sillä meidän rikoksemme seuraavat meitä, ja pahat tekomme me tunnemme:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'me olemme luopuneet Herrasta ja kieltäneet hänet, vetäytyneet pois Jumalaamme seuraamasta, puhuneet sortoa ja kapinaa, kantaneet kohdussamme ja purkaneet sisimmästämme valheen sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Oikeus työnnetään takaperin, ja vanhurskaus seisoo kaukana, sillä totuus kompastelee torilla, suoruus ei voi sisälle tulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Niin oli totuus kadonnut, ja joka pahasta luopui, se ryöstettiin paljaaksi. Herra näki sen, ja se oli hänen silmissänsä paha, ettei ollut oikeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Ja hän näki, ettei ollut yhtäkään miestä, ja hän ihmetteli, ettei kukaan astunut väliin. Silloin hänen oma käsivartensa auttoi häntä, ja hänen vanhurskautensa häntä tuki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Ja hän puki yllensä vanhurskauden kuin rintahaarniskan ja pani pelastuksen kypärin päähänsä, hän puki koston vaatteet puvuksensa ja verhoutui kiivauteen niinkuin viittaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Tekojen mukaan hän maksaa palkan: vihan vastustajillensa, koston vihollisillensa; merensaarille hän kostaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Ja päivän laskun äärillä he pelkäävät Herran nimeä ja päivän koittamilla hänen kunniaansa. Sillä se tulee kuin padottu virta, jota Herran henki ajaa eteenpäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Mutta Siionille se tulee lunastajana, niille Jaakobissa, jotka synnistä kääntyvät, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Ja tämä on minun liittoni heidän kanssansa, sanoo Herra: minun Henkeni, joka on sinun päälläsi, ja minun sanani, jonka minä suuhusi panen, eivät väisty sinun suustasi, eivät lastesi suusta eivätkä lastesi lasten suusta, sanoo Herra, nyt ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Nouse, ole kirkas, sillä sinun valkeutesi tulee, ja Herran kunnia koittaa sinun ylitsesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Sillä katso, pimeys peittää maan ja synkeys kansat, mutta sinun ylitsesi koittaa Herra, ja sinun ylläsi näkyy hänen kunniansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Kansat vaeltavat sinun valkeuttasi kohti, kuninkaat sinun koitteesi kirkkautta kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Nosta silmäsi, katso ympärillesi: kaikki nämä ovat kokoontuneet, tulevat sinun tykösi; sinun poikasi tulevat kaukaa, sinun tyttäriäsi kainalossa kannetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Silloin sinä saat sen nähdä, ja sinä loistat ilosta, sinun sydämesi sykkii ja avartuu, kun meren aarteet kääntyvät sinun tykösi, kansojen rikkaudet tulevat sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Kamelien paljous peittää sinut, Midianin ja Eefan varsat; kaikki tulevat Sabasta, kantavat kultaa ja suitsutusta ja Herran ylistystä ilmoittavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Kaikki Keedarin laumat kokoontuvat sinun tykösi, Nebajotin oinaat palvelevat sinua; minulle otollisina ne nousevat minun alttarilleni, ja minä kirkastan kirkkauteni huoneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Keitä ovat nuo, jotka lentävät niinkuin pilvet ja niinkuin kyyhkyset lakkoihinsa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Merensaaret odottavat minua, ja etumaisina tulevat Tarsiin-laivat tuodakseen sinun lapsesi kaukaa; hopeansa ja kultansa heillä on mukanansa Herran, sinun Jumalasi, nimelle, Israelin Pyhälle, sillä hän kirkastaa sinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Ja muukalaiset rakentavat sinun muurisi, ja heidän kuninkaansa palvelevat sinua; sillä vihassani minä löin sinua, mutta mielisuosiossani minä sinua armahdan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Sinun porttisi pidetään aina auki, ei niitä suljeta päivällä eikä yöllä, että kansojen rikkaudet tuotaisiin ja heidän kuninkaansa saatettaisiin sinun tykösi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Sillä se kansa tai valtakunta, joka ei sinua palvele, hukkuu, ja ne kansat hävitetään perinjuurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Libanonin kunnia tulee sinun tykösi, kypressit, jalavat ynnä hopeakuuset, kaunistamaan minun pyhäkköni paikkaa, ja minä saatan jalkaini sijan kunniaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Ja kumarassa käyden tulevat sinun tykösi sinun sortajaisi pojat, ja kaikki sinun pilkkaajasi heittäytyvät sinun jalkaisi juureen. He nimittävät sinut \"Herran kaupungiksi\", \"Israelin Pyhän Siioniksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Sen sijaan, että sinä olet ollut hyljätty ja vihattu, niin ettei ollut kauttasi kulkijaa, teen minä sinut korkeaksi iankaikkisesti, iloksi polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Ja sinä saat imeä kansojen maidon, imeä kuningasten rintoja, saat tuntea, että minä, Herra, olen sinun auttajasi, että Jaakobin Väkevä on sinun lunastajasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Minä tuon vasken sijaan kultaa, ja raudan sijaan minä tuon hopeata, puun sijaan vaskea ja kiven sijaan rautaa. Ja minä panen sinulle esivallaksi rauhan ja käskijäksi vanhurskauden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Ei kuulu enää väkivaltaa sinun maassasi, ei tuhoa, ei turmiota sinun rajaisi sisällä, ja sinä kutsut pelastuksen muuriksesi ja kiitoksen portiksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Ei ole enää aurinko sinun valonasi päivällä, eikä valaise sinua kuun kumotus, vaan Herra on sinun iankaikkinen valkeutesi, ja sinun Jumalasi sinun kirkkautesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Ei sinun aurinkosi enää laske, eikä sinun kuusi vajene, sillä Herra on sinun iankaikkinen valkeutesi, ja päättyneet ovat sinun murheesi päivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Sinun kansassasi ovat kaikki vanhurskaita, he saavat periä maan iankaikkisesti, he, minun istutukseni vesa, minun kätteni teko, minun kirkkauteni ilmoitukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Pienimmästä kasvaa heimo, vähäisimmästä väkevä kansa. Minä, Herra, sen aikanansa nopeasti täytän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Herran, Herran Henki on minun päälläni, sillä hän on voidellut minut julistamaan ilosanomaa nöyrille, lähettänyt minut sitomaan särjettyjä sydämiä, julistamaan vangituille vapautusta ja kahlituille kirvoitusta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'julistamaan Herran otollista vuotta ja meidän Jumalamme kostonpäivää, lohduttamaan kaikkia murheellisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'panemaan Siionin murheellisten päähän-antamaan heille-juhlapäähineen tuhkan sijaan, iloöljyä murheen sijaan, ylistyksen vaipan masentuneen hengen sijaan; ja heidän nimensä on oleva \"vanhurskauden tammet\", \"Herran istutus\", hänen kirkkautensa ilmoitukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Ja he rakentavat jälleen ikivanhat rauniot, kohottavat ennalleen esi-isien autiot paikat; ja he uudistavat rauniokaupungit, jotka ovat olleet autiot polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Vieraat ovat teidän laumojenne paimenina, muukalaiset teidän peltomiehinänne ja viinitarhureinanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Mutta teitä kutsutaan Herran papeiksi, sanotaan meidän Jumalamme palvelijoiksi; te saatte nauttia kansain rikkaudet ja periä heidän kunniansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Häpeänne hyvitetään teille kaksin kerroin, ja pilkatut saavat riemuita osastansa. Niin he saavat kaksinkertaisen perinnön maassansa; heillä on oleva iankaikkinen ilo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Sillä minä, Herra, rakastan oikeutta, vihaan vääryyttä ja ryöstöä; ja minä annan heille palkan uskollisesti ja teen heidän kanssansa iankaikkisen liiton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Heidän siemenensä tulee tunnetuksi kansain keskuudessa ja heidän jälkeläisensä kansakuntien keskellä; kaikki, jotka näkevät heitä, tuntevat heidät Herran siunaamaksi siemeneksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Minä iloitsen suuresti Herrassa, minun sieluni riemuitsee minun Jumalassani, sillä hän pukee minun ylleni autuuden vaatteet ja verhoaa minut vanhurskauden viittaan, yljän kaltaiseksi, joka kantaa juhlapäähinettä niinkuin pappi, ja morsiamen kaltaiseksi, joka on koruillansa kaunistettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Sillä niinkuin maa tuottaa kasvunsa ja niinkuin kasvitarha saa siemenkylvönsä versomaan, niin saattaa Herra, Herra versomaan vanhurskauden ja kiitoksen kaikkien kansojen nähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Siionin tähden minä en voi vaieta, ja Jerusalemin tähden en lepoa saa, ennenkuin sen vanhurskaus nousee kuin aamunkoi ja sen autuus kuin palava tulisoihtu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Ja kansat näkevät sinun vanhurskautesi, kaikki kuninkaat sinun kunniasi; ja sinulle annetaan uusi nimi, jonka Herran suu säätää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Sinä tulet kauniiksi kruunuksi Herran kädessä ja kuninkaalliseksi päähineeksi Jumalasi kädessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Ei sinua enää sanota \"hyljätyksi\", eikä sinun maatasi enää sanota \"autioksi\"; vaan sinua kutsutaan \"minun rakkaakseni\" ja sinun maatasi \"aviovaimoksi\", sillä Herra rakastaa sinua, ja sinun maasi otetaan avioksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Sillä niinkuin nuori mies ottaa neitsyen avioksi, niin sinun lapsesi ottavat sinut omaksensa; ja niinkuin ylkä iloitsee morsiamesta, niin sinun Jumalasi iloitsee sinusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Sinun muureillesi, Jerusalem, minä asetan vartijat; älkööt he milloinkaan vaietko, ei päivällä eikä yöllä. Te, jotka ylistätte Herraa, älkää itsellenne lepoa suoko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Älkää antako hänelle lepoa, ennenkuin hän on asettanut ennallensa Jerusalemin, tehnyt sen ylistykseksi maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Herra on vannonut oikean kätensä ja väkevyytensä käsivarren kautta: En totisesti minä enää anna jyviäsi sinun vihollistesi ruuaksi, eivätkä juo enää muukalaiset sinun viiniäsi, josta sinä olet vaivan nähnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Vaan jotka viljan kokoavat, ne sen syövät ja ylistävät Herraa; ja jotka viinin korjaavat, ne sen juovat minun pyhissä esikartanoissani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Käykää, käykää ulos porteista, tasoittakaa kansalle tie, tehkää, tehkää valtatie, raivatkaa kivet pois, kohottakaa lippu kansoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Katso, Herra on kuuluttanut maan ääriin asti: Sanokaa tytär Siionille: Katso, sinun pelastuksesi tulee. Katso, hänen palkkansa on hänen mukanansa, hänen työnsä ansio käy hänen edellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Ja heitä kutsutaan \"pyhäksi kansaksi\", \"Herran lunastetuiksi\"; ja sinua kutsutaan \"halutuksi\", \"kaupungiksi, joka ei ole hyljätty\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Kuka tuolla tulee Edomista, tulipunaisissa vaatteissa Bosrasta, tuo puvultansa komea, joka uljaana astelee suuressa voimassansa? \"Minä, joka puhun vanhurskautta, joka olen voimallinen auttamaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Miksi on punaa sinun puvussasi, miksi ovat vaatteesi kuin viinikuurnan polkijan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, '\"Kuurnan minä poljin, minä yksinäni, ei ketään kansojen joukosta ollut minun kanssani; minä poljin heidät vihassani, tallasin heidät kiivaudessani, ja niin pirskui heidän vertansa vaatteilleni, ja minä tahrasin koko pukuni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Sillä koston päivä oli minun mielessäni ja minun lunastettujeni vuosi oli tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Ja minä katselin, mutta ei ollut auttajaa, ja minä ihmettelin, kun ei kukaan tueksi tullut. Silloin minun oma käsivarteni minua auttoi, ja minun vihani minua tuki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Ja minä tallasin kansat vihassani ja juovutin heidät kiivaudellani; minä vuodatin maahan heidän verensä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Herran armotöitä minä julistan, Herran ylistettäviä tekoja, kaikkea, mitä Herra on meille tehnyt, suurta hyvyyttä Israelin heimoa kohtaan, mitä hän on heille osoittanut laupeudessansa ja suuressa armossansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Ja hän sanoi: \"Ovathan he minun kansani, he ovat lapsia, joissa ei ole vilppiä\"; ja niin hän tuli heille vapahtajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'Kaikissa heidän ahdistuksissansa oli hänelläkin ahdistus, ja hänen kasvojensa enkeli vapahti heidät. Rakkaudessaan ja sääliväisyydessään hän lunasti heidät, nosti heitä ja kantoi heitä kaikkina muinaisina päivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Mutta he niskoittelivat ja saattoivat murheelliseksi hänen Pyhän Henkensä; ja niin hän muuttui heidän viholliseksensa, hän itse soti heitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Silloin hänen kansansa muisti muinaisia päiviä, muisti Moosesta: Missä on hän, joka toi heidät ylös merestä, heidät ynnä hänen laumansa paimenen? Missä on hän, joka pani tämän sydämeen Pyhän Henkensä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'hän, joka antoi kunniansa käsivarren kulkea Mooseksen oikealla puolella, joka halkaisi vedet heidän edestänsä tehdäkseen itsellensä iankaikkisen nimen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'hän, joka kuljetti heitä syvyyksissä niinkuin hevosia erämaassa, eivätkä he kompastelleet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Niinkuin karja astuu alas laaksoon, niin vei Herran Henki heidät lepoon. Niin sinä olet kansaasi johdattanut, tehdäksesi itsellesi kunniallisen nimen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Katsele taivaasta, katso pyhyytesi ja kirkkautesi asunnosta. Missä on sinun kiivautesi ja voimalliset tekosi? Sinun sydämesi sääli ja sinun armahtavaisuutesi ovat minulta sulkeutuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Sinähän olet meidän isämme, sillä Aabraham ei meistä tiedä eikä Israel meitä tunne: sinä, Herra, olet meidän isämme; \"meidän Lunastajamme\" on ikiajoista sinun nimesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Miksi sallit meidän eksyä pois sinun teiltäsi, Herra, ja annoit meidän sydämemme paatua, niin ettemme sinua pelkää? Palaja takaisin palvelijaisi tähden, perintöosasi sukukuntain tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Vähän aikaa vain sinun pyhä kansasi sai pitää perintönsä; meidän ahdistajamme ovat tallanneet sinun pyhäkkösi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Me olemme niinkuin ne, joita sinä et ole ikinä hallinnut, olemme, niinkuin ei meitä olisi otettu sinun nimiisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Oi, jospa sinä halkaisisit taivaat ja astuisit alas, niin että vuoret järkkyisivät sinun edessäsi, niinkuin risut leimahtavat tuleen, niinkuin vesi tulella kiehuu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'että tekisit nimesi tunnetuksi vastustajillesi ja kansat vapisisivat sinun kasvojesi edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'kun sinä teet peljättäviä tekoja, joita emme odottaa voineet! Oi, jospa astuisit alas, niin että vuoret järkkyisivät sinun edessäsi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Ei ole ikiajoista kuultu, ei ole korviin tullut, ei ole silmä nähnyt muuta Jumalaa, paitsi sinut, joka senkaltaisia tekisi häntä odottavalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Sinä käyt niitä kohden, jotka ilolla vanhurskautta tekevät ja jotka sinun teilläsi sinua muistavat. Katso, sinä vihastuit, ja me jouduimme synnin alaisiksi; niin on ollut ikiajoista asti-saammeko avun?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Kaikki me olimme kuin saastaiset, ja niinkuin tahrattu vaate oli kaikki meidän vanhurskautemme. Ja kaikki me olemme lakastuneet kuin lehdet, ja pahat tekomme heittelevät meitä niinkuin tuuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Ei ole ketään, joka avukseen huutaa sinun nimeäsi, joka herää pitämään sinusta kiinni; sillä sinä olet peittänyt kasvosi meiltä, jättänyt meidät menehtymään syntiemme valtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Mutta olethan sinä, Herra, meidän isämme; me olemme savi, ja sinä olet meidän valajamme, kaikki me olemme sinun kättesi tekoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Älä, Herra, vihastu ylenmäärin, äläkä ainiaan muistele pahoja tekoja. Katso ja huomaa, että me kaikki olemme sinun kansasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Sinun pyhät kaupunkisi ovat tulleet erämaaksi, Siion on erämaaksi tullut, Jerusalem autioksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Meidän pyhä ja ihana temppelimme, jossa isämme sinua ylistivät, on tulella poltettu, ja rauniona on kaikki meille kallisarvoinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Vaikka nämä näin ovat, voitko, Herra, pidättää itsesi, voitko olla vaiti ja vaivata meitä ylenmäärin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Minä olen suostunut niiden etsittäväksi, jotka eivät minua kysyneet, niiden löydettäväksi, jotka eivät minua etsineet; minä olen sanonut kansalle, joka ei ole otettu minun nimiini: Tässä minä olen, tässä minä olen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Koko päivän minä olen ojentanut käsiäni uppiniskaista kansaa kohden, joka vaeltaa tietä, mikä ei ole hyvä, omain ajatustensa mukaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'kansaa kohden, joka vihoittaa minua alinomaa, vasten kasvojani, uhraa puutarhoissa ja suitsuttaa tiilikivialttareilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'He asustavat haudoissa ja yöpyvät salaisiin paikkoihin; he syövät sianlihaa, ja saastaiset liemet on heillä astioissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'He sanovat: \"Pysy erilläsi, älä tule minua lähelle, sillä minä olen sinulle pyhä\". Nämä ovat savu minun sieramissani, tuli, joka palaa kaiken päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Katso, se on kirjoitettuna minun edessäni. En ole minä vaiti, vaan minä maksan, maksan heille helmaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'heidän pahat tekonsa ynnä teidän isienne pahat teot, sanoo Herra, niiden, jotka ovat vuorilla suitsuttaneet ja kukkuloilla minua häväisseet; ja ensiksi minä mittaan heille palkan heidän helmaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Näin sanoo Herra: Niinkuin sanotaan rypäleestä, jos siinä on mehua: \"Älä hävitä sitä, sillä siinä on siunaus\", niin teen minä palvelijaini tähden, etten kaikkea hävittäisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Minä tuotan Jaakobista siemenen ja Juudasta vuorteni perillisen; ja minun valittuni saavat periä maan, ja minun palvelijani saavat siinä asua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Ja Saaron on oleva lammasten laitumena ja Aakorin laakso karjan lepopaikkana minun kansallani, joka minua etsii.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Mutta te, jotka hylkäätte Herran ja unhotatte minun pyhän vuoreni, jotka valmistatte Gadille pöydän ja vuodatatte uhrijuomaa Menille-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'teidät minä määrään miekan omiksi, ja kaikki te kumarrutte teurastettaviksi, sentähden ettette vastanneet, kun minä kutsuin, ettekä kuulleet, kun minä puhuin, vaan teitte sitä, mikä on pahaa minun silmissäni, ja valitsitte sen, mikä ei ole minulle otollista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Sentähden, näin sanoo Herra, Herra: Katso, minun palvelijani syövät, mutta te näette nälkää; katso, minun palvelijani juovat, mutta te kärsitte janoa; katso, minun palvelijani iloitsevat, mutta te joudutte häpeään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Katso, minun palvelijani riemuitsevat sydämen onnesta, mutta te huudatte sydämen tuskasta ja voivotatte mielimurteissanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Ja te jätätte nimenne kirouslauseeksi minun valituilleni: \"Niin sinut surmatkoon Herra, Herra!\" Mutta palvelijoilleen hän on antava toisen nimen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Joka maassa itsensä siunaa, siunaa itsensä totisen Jumalan nimeen, ja joka maassa vannoo, vannoo totisen Jumalan nimeen; sillä entiset ahdistukset ovat unhotetut ja peitossa minun silmiltäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Sillä katso, minä luon uudet taivaat ja uuden maan. Entisiä ei enää muisteta, eivätkä ne enää ajatukseen astu;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'vaan te saatte iloita ja riemuita iankaikkisesti siitä, mitä minä luon. Sillä katso, iloksi luon minä Jerusalemin, riemuksi sen kansan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Minä iloitsen Jerusalemista ja riemuitsen kansastani; eikä siellä enää kuulla itkun ääntä eikä valituksen ääntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Ei siellä ole enää lasta, joka eläisi vain muutaman päivän, ei vanhusta, joka ei täyttäisi päiviensä määrää; sillä nuorin kuolee satavuotiaana, ja vasta satavuotiaana synnintekijä joutuu kiroukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'He rakentavat taloja ja asuvat niissä, he istuttavat viinitarhoja ja syövät niiden hedelmät;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'he eivät rakenna muitten asua, eivät istuta muitten syödä; sillä niinkuin puitten päivät ovat, niin ovat elinpäivät minun kansassani. Minun valittuni kuluttavat itse kättensä työn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'He eivät tee työtä turhaan eivätkä lapsia synnytä äkkikuoleman omiksi, sillä he ovat Herran siunattujen siemen, ja heidän vesansa ovat heidän tykönänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Ennenkuin he huutavat, minä vastaan, heidän vielä puhuessaan minä kuulen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Susi ja lammas käyvät yhdessä laitumella, ja leijona syö rehua niinkuin raavas, ja käärmeen ruokana on maan tomu; ei missään minun pyhällä vuorellani tehdä pahaa eikä vahinkoa, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Näin sanoo Herra: Taivas on minun valtaistuimeni, ja maa on minun jalkojeni astinlauta. Mikä olisi huone, jonka te minulle rakentaisitte, mikä paikka olisi minun leposijani?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Minun käteni on kaikki nämä tehnyt, ja niin ovat kaikki nämä syntyneet, sanoo Herra. Mutta minä katson sen puoleen, joka on nöyrä, jolla on särjetty henki ja arka tunto minun sanani edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Joka teurastaa härän, mutta myös tappaa miehen, joka uhraa lampaan, mutta myös taittaa koiralta niskan, joka uhraa ruokauhrin, mutta myös sian verta, joka polttaa suitsuketta, mutta myös ylistää epäjumalaa: nämä ovat valinneet omat tiensä. Ja niinkuin heidän sielunsa on mielistynyt heidän iljetyksiinsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'niin minäkin valitsen heidän vaivaamisensa ja annan heille tulla sen, mitä he pelkäävät, koska ei kukaan vastannut, kun minä kutsuin, koska he eivät kuulleet, kun minä puhuin, vaan tekivät sitä, mikä on pahaa minun silmissäni, ja valitsivat sen, mikä ei ole minulle otollista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Kuulkaa Herran sana, te, jotka olette aralla tunnolla hänen sanansa edessä: Teidän veljenne, jotka vihaavat teitä ja työntävät teidät luotaan minun nimeni tähden, sanovat: \"Osoittakoon Herra kunniansa, että me näemme teidän ilonne!\" Mutta he joutuvat häpeään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Metelin ääni kaupungista! Ääni temppelistä! Herran ääni: hän maksaa palkan vihollisillensa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Ennenkuin Siion kipuja tuntee, hän synnyttää; ennenkuin hänelle tuskat tulevat, hän saa poikalapsen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Kuka on sellaista kuullut, kuka senkaltaista nähnyt? Syntyykö maa yhden päivän kivulla, tahi synnytetäänkö kansa yhdellä haavaa? Siionhan tunsi kipuja ja samalla jo synnytti lapsensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Minäkö avaisin kohdun sallimatta synnyttää, sanoo Herra, tahi minäkö, joka saatan synnyttämään, sulkisin kohdun?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Iloitkaa Jerusalemin kanssa ja riemuitkaa hänestä kaikki, jotka häntä rakastatte; iloitsemalla iloitkaa hänen kanssaan, te, jotka olette hänen tähtensä surreet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'että imisitte ja tulisitte ravituiksi hänen lohdutuksensa rinnoista, että joisitte ja virkistyisitte hänen kunniansa runsaudesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Sillä näin sanoo Herra: Minä ohjaan hänen tykönsä rauhan niinkuin virran ja kansojen kunnian niinkuin tulvajoen. Ja te saatte imeä, kainalossa teitä kannetaan, ja polvilla pitäen teitä hyväillään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Niinkuin äiti lohduttaa lastansa, niin minä lohdutan teitä, ja Jerusalemissa te saatte lohdutuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Te näette sen, ja teidän sydämenne iloitsee, ja teidän luunne virkistyvät kuin vihanta ruoho; ja Herran käsi tulee tunnetuksi hänen palvelijoissansa, mutta vihollistensa hän antaa tuntea vihansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Sillä katso, Herra tulee tulessa, ja hänen vaununsa ovat kuin myrskytuuli; ja hän antaa vihansa purkautua hehkussa ja nuhtelunsa tulenliekeissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Herra käy tuomiolle kaiken lihan kanssa tulella ja miekallaan; ja Herran surmaamia on oleva paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Jotka pyhittäytyvät ja puhdistautuvat puutarha-menoja varten, seuraten miestä, joka on heidän keskellänsä, jotka syövät sianlihaa ja muuta inhottavaa sekä hiiriä, niistä kaikista tulee loppu, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Minä tunnen heidän tekonsa ja ajatuksensa. Aika tulee, että minä kokoan kaikki kansat ja kielet, ja he tulevat ja näkevät minun kunniani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Ja minä teen tunnusteon heidän keskellänsä ja lähetän pakoonpäässeitä heidän joukostansa pakanain tykö Tarsiiseen, Puuliin ja Luudiin, jousenjännittäjäin tykö, Tuubaliin ja Jaavaniin, kaukaisiin merensaariin, jotka eivät ole kuulleet minusta kerrottavan eivätkä nähneet minun kunniaani, ja he ilmoittavat minun kunniani pakanain keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Ja he tuovat kaikki teidän veljenne kaikista kansoista uhrilahjana Herralle hevosilla, vaunuilla, kantotuoleilla, muuleilla ja ratsukameleilla minun pyhälle vuorelleni Jerusalemiin, sanoo Herra, niinkuin israelilaiset tuovat ruokauhrin puhtaassa astiassa Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Ja heitäkin minä otan leeviläisiksi papeiksi, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Niinkuin uudet taivaat ja uusi maa, jotka minä teen, pysyvät minun kasvojeni edessä, sanoo Herra, niin pysyy teidän siemenenne ja teidän nimenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Joka kuukausi uudenkuun päivänä ja joka viikko sapattina tulee kaikki liha kumartaen rukoilemaan minua, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'Ja he käyvät ulos katselemaan niiden miesten ruumiita, jotka ovat luopuneet minusta; sillä heidän matonsa ei kuole, eikä heidän tulensa sammu, ja he ovat kauhistukseksi kaikelle lihalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Jeremian, Hilkian pojan, sanat. Tämä oli Anatotissa, Benjaminin maassa, asuvia pappeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'Hänelle tuli Herran sana Juudan kuninkaan Joosian, Aamonin pojan, päivinä, tämän kolmantenatoista hallitusvuotena,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'ja tuli vielä Juudan kuninkaan Joojakimin, Joosian pojan, päivinä ja aina Juudan kuninkaan Sidkian, Joosian pojan, yhdennentoista vuoden loppumiseen asti, jolloin Jerusalemin asukkaat viidentenä kuukautena vietiin pakkosiirtolaisuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, '\"Jo ennenkuin minä valmistin sinut äidin kohdussa, minä sinut tunsin, ja ennenkuin sinä äidistä synnyit, minä sinut pyhitin; minä asetin sinut kansojen profeetaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Mutta minä sanoin: \"Voi Herra, Herra! Katso, en minä kykene puhumaan, sillä minä olen nuori.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Niin Herra sanoi minulle: \"Älä sano: \'Minä olen nuori\', vaan mene, kunne ikinä minä sinut lähetän, ja puhu kaikki, mitä minä käsken sinun puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Älä pelkää heitä, sillä minä olen sinun kanssasi ja pelastan sinut, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Ja Herra ojensi kätensä ja kosketti minun suutani. Ja Herra sanoi minulle: \"Katso, minä panen sanani sinun suuhusi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Katso, minä asetan sinut tänä päivänä yli kansojen ja valtakuntain, repimään maasta ja hajottamaan, hävittämään ja kukistamaan, rakentamaan ja istuttamaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Minulle tuli tämä Herran sana: \"Mitä sinä näet, Jeremia?\" Minä vastasin: \"Minä näen mantelipuun oksan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Herra sanoi minulle: \"Sinä olet nähnyt oikein; sillä minä valvon sanaani toteuttaakseni sen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Minulle tuli toistamiseen Herran sana, näin kuuluva: \"Mitä sinä näet?\" Minä vastasin: \"Minä näen kiehuvan padan; se näkyy pohjoisen puolelta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Ja Herra sanoi minulle: \"Pohjoisesta on onnettomuus purkautuva kaikkien maan asukasten yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Sillä katso, minä kutsun kaikki pohjoisten valtakuntain kansanheimot, sanoo Herra, ja ne tulevat ja asettavat kukin valtaistuimensa Jerusalemin porttien oville ja kaikkia sen muureja vastaan, yltympäri, ja kaikkia Juudan kaupunkeja vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Sitten minä julistan heille tuomioni kaikesta heidän pahuudestaan, koska he ovat hyljänneet minut, polttaneet uhreja muille jumalille ja kumartaneet kättensä tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Mutta sinä, vyötä kupeesi, nouse ja puhu heille kaikki, mitä minä käsken sinun puhua. Älä heitä kauhistu, etten minä kauhistuttaisi sinua heidän edessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Sillä katso, minä teen sinusta tänä päivänä varustetun kaupungin, rautapatsaan ja vaskimuurin koko maata vastaan, Juudan kuninkaita, sen ruhtinaita, sen pappeja vastaan ja maan kansaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Ja he sotivat sinua vastaan, mutta eivät voita sinua, sillä minä olen sinun kanssasi, sanoo Herra, ja pelastan sinut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, '\"Mene ja julista Jerusalemin kuullen ja sano: Näin sanoo Herra: Minä muistan sinun nuoruutesi armauden, morsiusaikasi rakkauden, kuinka sinä seurasit minua erämaassa, maassa, jossa ei kylvöä tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Herralle pyhitetty oli Israel, hänen satonsa esikoinen. Kaikki, jotka sitä söivät, joutuivat syynalaisiksi; onnettomuus kohtasi heitä, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Kuulkaa Herran sana, Jaakobin heimo ja kaikki Israelin heimon sukukunnat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Näin sanoo Herra: Mitä vääryyttä teidän isänne minusta löysivät, koska he erkanivat kauas minusta ja lähtivät seuraamaan turhia jumalia ja turhanpäiväisiksi tulivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'He eivät kysyneet: \'Missä on Herra, joka toi meidät pois Egyptin maasta, joka johdatti meitä erämaassa, arojen ja kuilujen maassa, kuivuuden ja synkeyden maassa, maassa, jossa ei kukaan kulje eikä yksikään ihminen asu?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Minä toin teidät hedelmätarhojen maahan syömään sen hedelmää ja hyvyyttä, mutta sinne tultuanne te saastutitte minun maani ja teitte minun perintöosani kauhistukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Papit eivät kysyneet: \'Missä on Herra?\' Lainkäyttäjät eivät minua tunteneet, ja paimenet luopuivat minusta; profeetat ennustivat Baalin nimessä ja seurasivat niitä, joista ei apua ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Sentähden minä vielä käyn oikeutta teidän kanssanne, sanoo Herra, ja teidän lastenne lasten kanssa minä käyn oikeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Menkää kittiläisten saarille katsomaan ja lähettäkää Keedariin panemaan tarkoin merkille ja katsomaan, onko senkaltaista tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Onko mikään pakanakansa vaihtanut jumalia, vaikka ne eivät olekaan jumalia? Mutta minun kansani on vaihtanut kunniansa siihen, josta ei apua ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Hämmästykää tästä, te taivaat, kauhistukaa, peräti tyrmistykää, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Sillä minun kansani on tehnyt kaksinkertaisen synnin: minut, elävän veden lähteen, he ovat hyljänneet, ja ovat hakanneet itselleen vesisäiliöitä, särkyviä säiliöitä, jotka eivät vettä pidä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Onko Israel ostettu orja tai kotona syntynyt? Minkätähden hän on joutunut saaliiksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Häntä vastaan kiljuivat nuoret leijonat, antoivat äänensä kuulua; ne tekivät hänen maansa autioksi, hänen kaupunkinsa hävitettiin asujattomiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Myöskin noofilaiset ja tahpanheelaiset pitivät sinun päälakeasi laitumenansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Eikö tee tätä sinulle se, että sinä hylkäät Herran, sinun Jumalasi, silloin kun hän tahtoo sinua tiellä kuljettaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Ja nyt, mitä menemistä sinulla on Egyptiin juomaan Siihorin vettä? Ja mitä menemistä sinulla on Assuriin juomaan Eufrat-virran vettä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Sinun pahuutesi tuottaa sinulle kurituksen, ja luopumuksesi saattaa sinut rangaistukseen; niin tiedä ja näe, kuinka onnetonta ja katkeraa se on, että sinä hylkäät Herran, sinun Jumalasi, etkä minua pelkää, sanoo Herra, Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Sillä jo ammoisista ajoista sinä olet särkenyt ikeesi, katkaissut siteesi ja sanonut: \'En tahdo palvella\'. Sillä kaikilla korkeilla kukkuloilla ja kaikkien viheriäin puitten alla sinä porttona viruit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Minä olin istuttanut sinut jaloksi viiniköynnökseksi, puhtaimmasta siemenestä; kuinka olet muuttunut minulle vieraan viinipuun villiköynnöksiksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Vaikka pesisit itsesi saippualla ja käyttäisit paljon lipeätä, saastaiseksi jää sittenkin sinun syntisi minun edessäni, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Kuinka saatat sanoa: \'En ole saastuttanut itseäni, en ole baaleja seurannut\'! Katso menoasi laaksossa, huomaa, mitä olet tehnyt, sinä nopea, nuori naaraskameli, joka juokset sinne ja tänne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'sinä villiaasi, erämaahan tottunut, joka himossasi ilmaa ahmit! Kuka hillitsee sen kiiman? Joka sitä etsii, sen ei tarvitse väsyttää itseään; sen löytää, kun tulee sen kuukausi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Varo, ettet juokse jalkaasi anturattomaksi ja kurkkuasi janoiseksi. Mutta sinä sanot: \'Se on turhaa! Ei! Sillä minä rakastan vieraita ja niitä minä seuraan.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Niinkuin teosta tavattu varas on häpeissänsä, niin joutuu Israelin heimo häpeään, se ja sen kuninkaat, ruhtinaat, papit ja profeetat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'he, jotka sanovat puulle: \'Sinä olet minun isäni\' ja kivelle: \'Sinä olet minut synnyttänyt\'. Sillä he ovat kääntäneet minulle selkänsä eivätkä kasvojansa; mutta onnettomuutensa aikana he sanovat: \'Nouse ja pelasta meidät\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Mutta missä ovat sinun jumalasi, jotka olet itsellesi tehnyt? Nouskoot ne, jos voivat pelastaa sinut onnettomuutesi aikana. Sillä yhtä monta, kuin sinulla on kaupunkeja, on sinulla jumalia, Juuda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Miksi riitelette minua vastaan? Olettehan te kaikki luopuneet minusta, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Turhaan minä olen lyönyt teidän lapsianne; he eivät ole ottaneet kuritusta varteen. Teidän miekkanne on syönyt teidän profeettojanne, niinkuin hävittävä leijona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'Voi sukukuntaa-teitä! Katsokaa Herran sanaa: olenko minä ollut Israelille erämaa, pimeyden maa? Miksi sanoo minun kansani: \'Me juoksemme valtoimina, emme tule enää sinun tykösi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Unhottaako neitsyt koristeensa, morsian koruvyönsä? Mutta minun kansani on unhottanut minut epälukuisina päivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Kuinka ovelasti sinä kuljet lempeä etsiessäsi! Niinpä oletkin perehtynyt pahuuden teihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Vaatteesi liepeetkin ovat köyhien, viatonten veressä. Et tavannut heitä murtautumasta sisälle, mutta yhtäkaikki-!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Ja kuitenkin sinä sanot: \'Minä olen syytön; hänen vihansa on kaiketi kääntynyt minusta pois\'. Katso, minä käyn oikeutta sinun kanssasi, koska sinä sanot: \'En ole syntiä tehnyt\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Kuinka niin kovin kiiruhdat vaihtamaan tiesi! Egyptistäkin olet saava häpeän, niinkuin olet häpeän saanut Assurista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Senkin tyköä olet lähtevä kädet pääsi päällä, sillä Herra on hyljännyt ne, joihin sinä luotat, ja heistä ei sinulle menestystä tule.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Sanottu on: Jos mies lähettää pois vaimonsa ja tämä menee hänen luotansa ja joutuu toisen miehen vaimoksi, saako se mies enää tulla hänen luokseen? Eikö se maa tule saastutetuksi? Mutta sinä olet harjoittanut haureutta monen ystävän kanssa, ja sinäkö saisit palata minun luokseni! sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Nosta silmäsi kukkuloihin ja katso: missä ei olisi sinua maattu? Teitten vieressä sinä istuit heitä odotellen, niinkuin arabialainen erämaassa, ja saastutit maan haureellisella menollasi ja pahuudellasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Sadekuurot tyrehtyivät, kevätsade jäi tulematta, mutta sinulla oli porttonaisen otsa, et tahtonut hävetä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Kuitenkin sinä nyt huudat minulle: \"Isäni! -Sinä olet nuoruuteni ystävä! -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Pitääkö hän vihaa iankaikkisesti, kantaako hän sitä ainiaan?\" Katso, näin sinä puhut, mutta sinä teet pahaa, ja siihen sinä pystyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Ja Herra sanoi minulle kuningas Joosian päivinä: \"Oletko nähnyt, mitä tuo luopiovaimo, Israel, on tehnyt? Hän kuljeskeli kaikilla korkeilla vuorilla ja kaikkien viheriäin puitten alla ja harjoitti siellä haureutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Ja minä sanoin, sittenkuin hän oli kaiken tämän tehnyt: \'Palaja minun tyköni\'. Mutta hän ei palannut. Ja hänen sisarensa Juuda, tuo uskoton, näki sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Ja minä näin, että, vaikka minä olin lähettänyt pois tuon luopiovaimon, Israelin, juuri sen tähden, että hän oli tehnyt aviorikoksen, ja olin antanut hänelle erokirjan, ei kuitenkaan uskoton Juuda, hänen sisarensa, peljännyt, vaan meni ja harjoitti haureutta hänkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Ja haureutensa huudolla hän saastutti maan, ja hän teki aviorikoksen kiven ja puun kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Ja kaikesta tästäkään huolimatta hänen sisarensa Juuda, tuo uskoton, ei palannut minun tyköni kaikesta sydämestään, vaan petollisesti, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Ja Herra sanoi minulle: \"Luopiovaimo Israel on osoittautunut vanhurskaammaksi kuin Juuda, tuo uskoton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Mene ja julista nämä sanat pohjoiseen päin ja sano: Palaja, sinä luopiovaimo Israel, sanoo Herra; minä en enää synkistä teille kasvojani, sillä minä olen armollinen, sanoo Herra, enkä pidä vihaa iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Ainoastaan tunne rikoksesi, että olet luopunut Herrasta, Jumalastasi, ja juossut sinne ja tänne vieraitten jumalain tykö, kaikkien viheriäin puitten alle, ettekä ole kuulleet minun ääntäni, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Palatkaa takaisin, te luopuneet lapset, sanoo Herra, sillä minä olen ottanut teidät omikseni, ja minä noudan teidät, yhden ainoankin kaupungista ja kaksi sukukunnasta, ja tuon teidät Siioniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Ja minä annan teille paimenet oman sydämeni mukaan, ja he kaitsevat teitä ymmärryksellä ja taidolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Ja kun te lisäännytte ja tulette hedelmällisiksi maassa niinä päivinä, sanoo Herra, niin ei enää puhuta Herran liitonarkista, se ei enää ajatukseen astu, eikä sitä enää muisteta; ei sitä enää kaivata, eikä sellaista enää tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Siihen aikaan sanotaan Jerusalemia Herran valtaistuimeksi, ja kaikki kansat kokoontuvat sinne, Jerusalemiin, Herran nimen tähden eivätkä enää vaella pahan sydämensä paatumuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'Niinä päivinä on Juudan heimo kulkeva Israelin heimon kanssa, ja he tulevat yhdessä pohjoisesta maasta siihen maahan, jonka minä annoin teidän isillenne perinnöksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Minä ajattelin: Kuinka asetankaan sinut lasten joukkoon ja annan sinulle suloisen maan, ihanan perintöosan, ihanimman kansojen maista! Ja ajattelin: Sinä olet kutsuva minua isäksi etkä ole koskaan kääntyvä minusta pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Mutta niinkuin vaimo on uskoton puolisollensa, niin olette te, Israelin heimo, olleet uskottomat minulle, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Kuule! Kalliokukkuloilta kuuluu itku, israelilaisten rukous, sillä he ovat vaeltaneet väärää tietä, ovat unhottaneet Herran, Jumalansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Palatkaa takaisin, te luopuneet lapset, niin minä parannan teidän luopumuksenne.\" -\"Katso, me tulemme sinun tykösi, sillä sinä olet Herra, meidän Jumalamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Totisesti, petosta on, mitä kukkuloilta kuuluu, pauhina vuorilla. Totisesti, Herrassa, meidän Jumalassamme, on Israelin pelastus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Häpeäjumala on syönyt isiemme vaivannäön nuoruudestamme asti, heidän lampaansa ja raavaansa, poikansa ja tyttärensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Maatkaamme häpeässämme, ja häväistyksemme peittäköön meidät, sillä Herraa, meidän Jumalaamme, vastaan me olemme syntiä tehneet, me ja meidän isämme, hamasta nuoruudestamme tähän päivään asti, emmekä ole kuulleet Herran, meidän Jumalamme, ääntä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, '\"Jos sinä käännyt, Israel, sanoo Herra, niin käänny minun tyköni; ja jos sinä poistat iljetyksesi minun kasvojeni edestä, niin et häädy harhailemaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'jos sinä vannot: \'Niin totta kuin Herra elää\' uskollisesti, oikein ja vanhurskaasti, niin kansat siunaavat itsensä hänen nimeensä, ja hän on heidän kerskauksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Sillä näin sanoo Herra Juudan miehille ja Jerusalemille: Raivatkaa itsellenne uudispelto, älkääkä kylväkö orjantappurain sekaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Ympärileikatkaa itsenne Herralle ja poistakaa sydämenne esinahka, te Juudan miehet ja Jerusalemin asukkaat, ettei minun vihani syttyisi kuin tuli ja palaisi, eikä olisi sammuttajaa, teidän tekojenne pahuuden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Julistakaa Juudassa ja Jerusalemissa, kuuluttakaa ja sanokaa: Puhaltakaa pasunaan kautta maan; huutakaa täyttä kurkkua ja sanokaa: \'Kokoontukaa, ja menkäämme varustettuihin kaupunkeihin\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Nostakaa lippu Siionia kohti, paetkaa pysähtymättä; sillä minä annan tulla pohjoisesta onnettomuuden ja suuren hävityksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Leijona on noussut tiheiköstänsä, kansaintuhooja on lähtenyt liikkeelle, lähtenyt asuinpaikastansa, tekemään sinun maasi autioksi: sinun kaupunkisi hävitetään asujattomiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Sentähden kääriytykää säkkeihin, valittakaa ja parkukaa, sillä Herran vihan hehku ei ole kääntynyt meistä pois.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Sinä päivänä, sanoo Herra, katoaa rohkeus kuninkaalta ja päämiehiltä, papit tyrmistyvät ja profeetat hämmästyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Mutta minä sanoin: \"Voi, Herra, Herra! Totisesti, sinä saatoit tämän kansan ja Jerusalemin peräti pettymään, kun sanoit: \'Teillä on oleva rauha!\' Ja kuitenkin miekka koskee sieluun asti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Siihen aikaan sanotaan tälle kansalle ja Jerusalemille: Kuuma tuuli tulee erämaan kalliokukkuloilta tytärtä, minun kansaani, kohti-ei elon viskaamiseksi eikä puhdistamiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Tuuli, liian tuima sellaisiin, tulee minulta; nyt minä myös julistan heille tuomiot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Katso, hän nousee niinkuin pilvi, ja hänen vaununsa ovat kuin tuulispää, hänen hevosensa ovat kotkia nopeammat. Voi meitä, sillä me olemme tuhon omat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Pese sydämesi puhtaaksi pahuudesta, sinä Jerusalem, että pelastuisit. Kuinka kauan asuvat sinun sisimmässäsi väärät ajatuksesi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Sillä kuule! Sanansaattaja Daanista, onnettomuuden julistaja Efraimin vuorilta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Kehoittakaa kansoja. Katso, kuuluttakaa Jerusalemia vastaan: \"Piirittäjät tulevat kaukaisesta maasta ja kohottavat huutonsa Juudan kaupunkeja vastaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Niinkuin pellon vartijat he piirittävät sitä yltympäri, koska se niskoitteli minua vastaan, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Sinun vaelluksesi ja tekosi ovat tuottaneet sinulle tämän: tämän saat pahuudestasi; niin, se on katkerata, niin, se koskee sydämeesi asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Voi minun rintaani, voi minun rintaani! Minä vääntelehdin tuskasta. Voi sydämeni kammioita! Sydämeni väräjää minussa; en voi vaieta, sillä minä kuulen pasunan äänen, sotahuudon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Hävitys tulee hävityksen päälle, sillä koko maa on tuhottu; äkisti ovat minun majani tuhotut, silmänräpäyksessä minun telttani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Kuinka kauan minun täytyy nähdä sotalippua, kuulla pasunan ääntä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Sillä minun kansani on hullu; eivät he tunne minua. He ovat tyhmiä lapsia eivätkä ymmärtäväisiä; he ovat viisaita tekemään pahaa, mutta tehdä hyvää he eivät taida.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Minä katselin maata, ja katso, se oli autio ja tyhjä, ja taivasta, eikä siinä valoa ollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Minä katselin vuoria, ja katso, ne järkkyivät, ja kaikki kukkulat huojuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Minä katselin, ja katso, ei ollut yhtään ihmistä, ja kaikki taivaan linnut olivat paenneet pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Minä katselin, ja katso, hedelmätarha oli erämaana, ja kaikki sen kaupungit olivat kukistuneet Herran, hänen vihansa hehkun, edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Sillä näin sanoo Herra: Koko maa tulee autioksi, vaikka minä en siitä peräti loppua tee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Sentähden maa suree, ja taivaat ylhäällä pukeutuvat mustiin, sillä minä olen puhunut, olen päättänyt, enkä kadu, en siitä peräydy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Ratsu-ja jousimiesten huutoa pakenee koko kaupunki; he menevät metsäntiheikköihin ja nousevat kallioille. Jokainen kaupunki on hyljätty, eikä niissä kukaan asu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Ja sinä tuhon oma, mitä teet, kun pukeudut purppuraan, kun koristaudut kultakoristeilla, kun suurennat silmäsi ihomaalilla? Turhaan sinä itsesi kaunistat. Rakastajat ovat hyljänneet sinut, he etsivät sinun henkeäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Sillä minä kuulen huudon, niinkuin synnyttäjän tuskanhuudon, vaivan, niinkuin ensisynnyttäjän vaivan, tytär Siionin huudon; hän vaikeroitsee, levittää kätensä: \"Voi minua, minun sieluni menehtyy murhamiesten käsiin!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Kiertäkää Jerusalemin katuja, katsokaa ja tiedustelkaa, ja etsikää sen toreilta: jos löydätte yhdenkään, jos on ainoatakaan, joka tekee oikein, joka noudattaa uskollisuutta, niin minä annan anteeksi Jerusalemille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Mutta vaikka he sanovat: \"Niin totta kuin Herra elää\", he kuitenkin vannovat väärin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Herra, eivätkö sinun silmäsi katso uskollisuutta? Sinä olet lyönyt heitä, mutta he eivät tunteneet kipua; sinä olet lopen hävittänyt heidät, mutta he eivät tahtoneet ottaa kuritusta varteen. He ovat kovettaneet kasvonsa kalliota kovemmiksi, eivät ole tahtoneet kääntyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Silloin minä ajattelin: Sellaisia ovat vain alhaiset; he ovat tyhmiä, sillä he eivät tunne Herran tietä, Jumalansa oikeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Niinpä menen ylhäisten luo ja puhuttelen heitä, sillä he kyllä tuntevat Herran tien, Jumalansa oikeuden. Mutta he olivat kaikki särkeneet ikeen, katkaisseet siteet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Sentähden surmaa heidät metsän leijona, aavikon susi haaskaa heidät, pantteri väijyy heidän kaupunkejansa. Kuka ikinä niistä lähtee, se raadellaan, sillä paljot ovat heidän rikoksensa, suuri heidän luopumustensa luku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Kuinka minä antaisin sinulle anteeksi? Sinun lapsesi ovat hyljänneet minut ja vannoneet niiden kautta, jotka eivät jumalia ole. Minä ravitsin heitä, mutta he tekivät aviorikoksen, ja porton huoneeseen he kokoontuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'He ovat hyvinruokittuja, äleitä oriita; he hirnuvat kukin lähimmäisensä vaimoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Enkö minä tällaisista rankaisisi, sanoo Herra, eikö minun sieluni kostaisi tämänkaltaiselle kansalle?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Nouskaa sen tarhojen pengermille ja hävittäkää, älkää kuitenkaan siitä peräti loppua tehkö; ottakaa pois sen köynnökset, sillä ne eivät ole Herran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Sillä he ovat olleet minulle peräti uskottomat, sekä Israelin heimo että Juudan heimo, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'He ovat kieltäneet Herran ja sanoneet: \"Ei se ole hän! Ei meitä kohtaa onnettomuus, emme tule näkemään miekkaa emmekä nälkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Ja profeetat ovat pelkkää tuulta; Herra, joka puhuu, ei ole heissä-heidän itsensä käyköön niin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Sentähden sanoo Herra, Jumala Sebaot, näin: Koska te tällaisia olette puhuneet, niin katso, minä teen sanani sinun suussasi tuleksi ja tämän kansan polttopuiksi, ja se kuluttaa heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Katso minä tuon teitä vastaan, te Israelin heimo, kansan kaukaa, sanoo Herra; se on horjumaton kansa, se on ikivanha kansa, kansa, jonka kieltä sinä et ymmärrä ja jonka puhetta sinä et tajua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Heidän viinensä on kuin avoin hauta, he ovat kaikki sankareita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'He syövät sinun satosi ja leipäsi, he syövät sinun poikasi ja tyttäresi, syövät sinun lampaasi ja raavaasi, syövät sinun viinipuusi ja viikunapuusi; he miekalla hävittävät sinun varustetut kaupunkisi, joihin sinä luotat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Mutta niinäkään päivinä, sanoo Herra, en minä teistä peräti loppua tee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Ja kun he kysyvät: \"Miksi on Herra, meidän Jumalamme, tehnyt meille kaiken tämän?\" niin vastaa heille: \"Niinkuin te olette hyljänneet minut ja palvelleet vieraita jumalia maassanne, niin täytyy teidän palvella muukalaisia maassa, joka ei ole teidän\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Julistakaa tämä Jaakobin huoneessa ja kuuluttakaa se Juudassa sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Kuulkaa tämä, te tyhmä ja ymmärtämätön kansa, te, joilla on silmät, mutta ette näe, joilla on korvat, mutta ette kuule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Ettekö pelkää minua, sanoo Herra, ettekö vapise minun edessäni, joka olen pannut hiekan meren rajaksi, ikuiseksi määräksi, jonka ylitse se ei pääse; ja vaikka se kuohuu, ei se mitään voi, ja vaikka sen aallot pauhaavat, eivät ne sen ylitse pääse?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Mutta tällä kansalla on uppiniskainen ja tottelematon sydän; he ovat poikenneet ja menneet pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Eivätkä he sano sydämessänsä: \"Peljätkäämme Herraa, Jumalaamme, joka antaa sateen, syyssateen ja kevätsateen ajallansa, ja säilyttää meille elonkorjuun määräviikot\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Teidän pahat tekonne käänsivät nämä pois, ja teidän syntinne estivät teitä saamasta hyvää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Sillä minun kansassani on jumalattomia; he väijyvät, niinkuin linnunpyytäjät kyykistyvät, he asettavat ansoja, pyydystävät ihmisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Niinkuin häkki on täynnä lintuja, niin heidän huoneensa ovat petosta täynnä. Siitä he ovat tulleet suuriksi ja rikkaiksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'ovat tulleet lihaviksi ja kiiltäviksi. Myös käyvät heidän häijyt puheensa yli kaiken määrän; he eivät aja orpojen asiaa, niin että ne voittaisivat, eivätkä hanki köyhille oikeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Enkö minä näistä tällaisista rankaisisi, sanoo Herra, eikö minun sieluni kostaisi tämänkaltaiselle kansalle?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Kauheita ja pöyristyttäviä tapahtuu maassa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'profeetat ennustavat valhetta, ja papit hallitsevat yksissä neuvoin heidän kanssaan, ja sitä minun kansani rakastaa. Mutta mitä te teette, kun tästä tulee loppu?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Paetkaa, benjaminilaiset, Jerusalemista, puhaltakaa pasunaan Tekoassa ja nostakaa merkki Beet-Keremin kohdalle; sillä pohjoisesta nousee onnettomuus ja suuri hävitys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Tytär Siionin, suloisen ja hemmotellun, minä hukutan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Hänen tykönsä tulee paimenia laumoinensa, he pystyttävät telttansa häntä vastaan yltympäri, syöttävät alansa kukin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Julistakaa häntä vastaan pyhä sota. \"Nouskaa ja menkäämme puolipäivän aikaan! Voi meitä, sillä päivä painuu, sillä illan varjot pitenevät!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Nouskaa ja menkäämme yöllä ja hävittäkäämme hänen linnansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Sillä näin sanoo Herra Sebaot: Kaatakaa puita ja luokaa valli Jerusalemia vastaan. Se on kaupunki, jota on rangaistava; siinä on pelkkää väkivaltaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Niinkuin kaivo pitää vetensä tuoreena, niin sekin pitää pahuutensa tuoreena; sortoa, hävitystä kuuluu sieltä, minun edessäni on aina kipu ja haavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Ota ojentuaksesi, Jerusalem, ettei minun sieluni vieraannu sinusta, etten tee sinua autioksi, asumattomaksi maaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Näin sanoo Herra Sebaot: Israelin jäännöksestä pidetään jälkikorjuu niinkuin viinipuusta; ojenna kätesi köynnöksiä kohti niinkuin viininkorjaaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Kenelle minä puhuisin, ketä varoittaisin, että he kuulisivat? Katso, heidän korvansa ovat ympärileikkaamattomat, eivät he voi kuunnella. Katso, Herran sana on tullut heille pilkaksi, ei se heille kelpaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Minä olen täynnä Herran vihaa, en jaksa sitä pidättää; vuodata se lapsukaisiin kadulla, niin myös nuorukaisparveen. Sillä niin mies kuin vaimokin vangitaan, niin vanhus kuin ikäloppu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Heidän talonsa joutuvat vieraille, niin myös pellot ja vaimot; sillä minä ojennan käteni maan asukkaita vastaan, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Sillä kaikki, niin pienet kuin suuretkin, pyytävät väärää voittoa, kaikki, niin profeetat kuin papitkin, harjoittavat petosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'He parantavat minun kansani vamman kepeästi, sanoen: \"Rauha, rauha!\" vaikka ei rauhaa ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'He joutuvat häpeään, sillä he ovat tehneet kauhistuksia; mutta heillä ei ole hävyntuntoa, he eivät osaa hävetä. Sentähden he kaatuvat kaatuvien joukkoon, sortuvat, kun minä heitä rankaisen, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Näin on Herra sanonut: \"Astukaa teille ja katsokaa ja kysykää muinaisia polkuja, kysykää, mikä on hyvä tie, ja vaeltakaa sitä, niin te löydätte levon sieluillenne\". Mutta he vastasivat: \"Emme vaella\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Ja minä olen asettanut teille vartijat: \"Kuunnelkaa pasunan ääntä\". Mutta he vastasivat: \"Emme kuuntele\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Sentähden kuulkaa, te kansat, ja tiedä, seurakunta, mitä heille on tapahtuva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Kuule, maa! Katso, minä tuotan onnettomuuden tälle kansalle, heidän hankkeittensa hedelmän, sillä he eivät ole kuunnelleet minun sanojani, vaan ovat hyljänneet minun lakini.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Mitä on minulle suitsutus, joka tulee Sabasta, ja paras kalmoruoko kaukaisesta maasta? Teidän polttouhrinne eivät ole minulle otolliset, eivätkä teidän teurasuhrinne minulle kelpaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Sentähden, näin sanoo Herra: Katso, minä asetan tälle kansalle kompastuskiviä, joihin he kompastuvat, isät ja pojat yhdessä, ja naapuri naapurinsa kanssa hukkuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Näin sanoo Herra: Katso, kansa tulee pohjoisesta maasta, suuri kansa nousee maan perimmäisiltä ääriltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'He käyttävät jousta ja keihästä, ovat julmat ja armahtamattomat. Heidän pauhinansa on kuin pauhaava meri, ja he ratsastavat hevosilla, varustettuina kuin soturi taisteluun sinua vastaan, tytär Siion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Kun kuulemme siitä sanoman, niin meidän kätemme herpoavat; ahdistus valtaa meidät, tuska, niinkuin synnyttäväisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Älkää menkö vainiolle, älkää vaeltako tiellä, sillä vihollisen miekka-kauhistus on kaikkialla!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'Tytär, minun kansani! Kääriydy säkkiin, vieriskele tuhassa; pidä itkiäiset, niinkuin ainokaista poikaa itketään, katkerat valittajaiset, sillä äkkiarvaamatta käy kimppuumme hävittäjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Minä olen asettanut sinut kansani koettelijaksi, suojavarustukseksi, että oppisit tuntemaan ja koettelisit heidän vaelluksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Kaikki he ovat pääniskureita, liikkuvat panettelijoina; he ovat vaskea ja rautaa, ovat kelvottomia kaikki tyynni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Palkeet puhkuvat, tulesta lähtee vain lyijyä. Turhaan on sulatettu ja sulatettu: pahat eivät ole erottuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Hylkyhopeaksi heitä sanotaan, sillä Herra on heidät hyljännyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Tämä on sana, joka tuli Jeremialle Herralta:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, '\"Asetu Herran huoneen portille ja julista siellä tämä sana ja sano: Kuulkaa Herran sana, koko Juuda, te jotka tulette näistä porteista kumartaen rukoilemaan Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Näin sanoo Herra Sebaot, Israelin Jumala: Vaeltakaa hyvin ja tehkää hyviä tekoja, niin minä annan teidän asua tässä paikassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Älkää luottako valheen sanoihin, kun sanotaan: \'Tämä on Herran temppeli, Herran temppeli, Herran temppeli!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Vaan jos te todella parannatte vaelluksenne ja tekonne, jos te todella teette oikeuden niin toiselle kuin toisellekin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'ette sorra muukalaista, orpoa ja leskeä, ette vuodata viatonta verta tässä paikassa ettekä seuraa muita jumalia turmioksenne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'niin minä annan teidän asua tässä paikassa, maassa, jonka minä olen antanut teidän isillenne, iankaikkisesta iankaikkiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Mutta katso, te luotatte valheen sanoihin, joista ei ole hyötyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Miten on? Te varastatte, tapatte, rikotte avion, vannotte väärin, poltatte uhreja Baalille ja seuraatte vieraita jumalia, joita te ette tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Ja te tulette ja astutte minun eteeni tähän huoneeseen, joka on otettu minun nimiini, ja sanotte: \'Me kyllä pelastumme\' -tehdäksenne yhä kaikkia näitä kauhistuksia!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Ryövärien luolaksiko te katsotte tämän huoneen, joka on otettu minun nimiini? Katso, sellaiseksi minäkin olen sen havainnut, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Menkääpä minun asuinpaikkaani, joka oli Siilossa, jossa minä ensin annoin nimeni asua, ja katsokaa, mitä minä olen sille tehnyt kansani Israelin pahuuden tähden!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Ja koska te nyt olette kaikkia näitä tekoja tehneet, sanoo Herra, ettekä ole kuulleet, vaikka minä varhaisesta alkaen olen teille puhunut, koska ette vastanneet, vaikka minä teille huusin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'niin minä teen tälle huoneelle, joka on otettu minun nimiini, johon te luotatte, ja tälle paikalle, jonka minä olen antanut teille ja teidän isillenne, samoin kuin olen tehnyt Siilolle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'ja heitän teidät pois kasvojeni edestä, niinkuin olen heittänyt pois kaikki teidän veljenne, kaikki Efraimin jälkeläiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Mutta sinä älä rukoile tämän kansan puolesta, älä kohota heidän puolestaan huutoa ja rukousta äläkä niillä minua ahdista; sillä en minä sinua kuule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Etkö näe, mitä he tekevät Juudan kaupungeissa ja Jerusalemin kaduilla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Lapset kokoavat puita, isät sytyttävät tulen, ja vaimot sotkevat taikinaa valmistaaksensa uhrikakkuja taivaan kuningattarelle, ja he vuodattavat juomauhreja muille jumalille, minulle mielikarvaudeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Minulleko he tuottavat mielikarvautta, sanoo Herra, eivätkö pikemmin itselleen, omaksi häpeäksensä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Sentähden, näin sanoo Herra, Herra: Katso, minun vihani ja kiivauteni on vuotava tämän paikan ylitse, ihmisten, eläinten, kedon puitten ja maan hedelmän ylitse, ja se palaa sammumatta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Näin sanoo Herra Sebaot, Israelin Jumala: \"Lisätkää polttouhrinne teurasuhreihinne ja syökää lihaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Sillä en minä puhunut enkä antanut käskyä teidän isillenne poltto-ja teurasuhrista silloin, kun minä vein heidät pois Egyptin maasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'vaan näin minä käskin heitä ja sanoin: Kuulkaa minun ääntäni, niin minä olen teidän Jumalanne ja te olette minun kansani; ja vaeltakaa aina sitä tietä, jota minä käsken teidän vaeltaa, että menestyisitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Mutta he eivät kuulleet, eivät korvaansa kallistaneet, vaan vaelsivat oman neuvonsa mukaan, pahan sydämensä paatumuksessa, ja käänsivät minulle selkänsä eivätkä kasvojansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Siitä päivästä, jona teidän isänne lähtivät Egyptin maasta, aina tähän päivään asti olen minä lähettänyt teidän tykönne kaikki palvelijani, profeetat-lähettänyt varhaisesta alkaen, päivä päivältä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Mutta kukaan ei kuullut minua, ei kallistanut korvaansa, vaan he olivat niskureita, tekivät enemmän pahaa kuin heidän isänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Ja kun sinä puhut heille kaiken tämän, niin he eivät kuule sinua, ja kun sinä heille huudat, niin he eivät sinulle vastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Sentähden sano heille: Tämä on kansa, joka ei kuullut Herran, Jumalansa, ääntä eikä ottanut kuritusta varteen. Kadonnut on totuus ja hävinnyt heidän suustansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Leikkaa hiuksesi ja heitä ne pois ja viritä kalliokukkuloilla itkuvirsi, sillä Herra on hyljännyt ja sysännyt pois vihansa alaisen sukupolven.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Sillä Juudan miehet ovat tehneet sen, mikä on pahaa minun silmissäni, sanoo Herra. He ovat asettaneet iljetyksensä temppeliin, joka on otettu minun nimiini, ja saastuttaneet sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Ja he ovat rakentaneet Toofet-uhrikukkulat Ben-Hinnomin laaksoon, polttaakseen tulessa poikiansa ja tyttäriänsä, mitä minä en ole käskenyt ja mikä ei ole minun mieleeni tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Sentähden, katso, päivät tulevat, sanoo Herra, jolloin ei enää sanota \'Toofet\' ja \'Ben-Hinnomin laakso\', vaan \'Murha-laakso\', ja Toofetiin haudataan, kun ei ole muualla tilaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Ja tämän kansan ruumiit joutuvat taivaan lintujen ja maan eläinten ruuaksi, eikä näitä kukaan karkoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Ja minä lopetan Juudan kaupungeista ja Jerusalemin kaduilta riemun ja ilon huudon, huudon yljälle ja huudon morsiamelle, sillä maa on tuleva raunioiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, '\"Siihen aikaan, sanoo Herra, otetaan Juudan kuningasten ja sen ruhtinasten luut, pappien ja profeettain luut sekä Jerusalemin asukasten luut pois heidän haudoistansa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'ja hajotetaan auringon, kuun ja kaiken taivaan joukon eteen, joita he rakastivat ja palvelivat, joita he seurasivat, etsivät ja kumartaen rukoilivat; niitä ei koota eikä haudata, vaan ne tulevat maan lannaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Ja kuolema on oleva halutumpi kuin elämä koko sille jäännökselle, joka jää jäljelle tästä pahasta sukukunnasta, kaikissa paikoissa, mihin minä karkoitan nämä jäljelle jääneet, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Ja sano heille: Näin sanoo Herra: Eikö se, joka lankeaa, nouse jälleen? Eikö se, joka kääntyy pois, käänny takaisin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Miksi kääntyy tämä kansa, Jerusalem, pois ainaisessa luopumuksessa? Miksi he pitävät kiinni petoksesta eivätkä tahdo palata?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Minä olen tarkannut ja kuunnellut: he puhuvat sitä, mikä ei ole oikein; ei kukaan kadu pahuuttansa, ei ajattele: Mitä olen minä tehnyt! Kaikki he kääntyvät pois juosten juoksuansa, niinkuin orhi kiitää taistelussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Haikarakin taivaalla tietää aikansa; metsäkyyhkynen, pääskynen ja kurki pitävät vaarin tuloajastansa, mutta minun kansani ei tunne Herran oikeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Kuinka saatatte sanoa: \'Me olemme viisaita, ja meillä on Herran laki\'? Totisesti! Katso, valheen työtä on tehnyt kirjanoppineiden valhekynä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Viisaat saavat häpeän, kauhistuvat ja joutuvat kiinni. Katso, he ovat hyljänneet Herran sanan-mitä heillä on viisautta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Sentähden minä annan heidän vaimonsa vieraille, heidän peltonsa valloittajille. Sillä kaikki, niin pienet kuin suuretkin, pyytävät väärää voittoa, kaikki, niin profeetat kuin papitkin, harjoittavat petosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'He parantavat kepeästi tyttären, minun kansani, vamman, sanoen: \'Rauha, rauha!\' vaikka ei rauhaa ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'He joutuvat häpeään, sillä he ovat tehneet kauhistuksia; mutta heillä ei ole hävyntuntoa, he eivät osaa hävetä. Sentähden he kaatuvat kaatuvien joukkoon, sortuvat, kun heidän rangaistuksensa tulee, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Minä tempaan heidät peräti pois, sanoo Herra. Ei ole rypäleitä viinipuussa eikä viikunoita viikunapuussa, ja lehtikin lakastuu. Minä saatan hyökkääjät heidän kimppuunsa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, '\"Miksi istumme alallamme? Kokoontukaa! Menkäämme varustettuihin kaupunkeihin, ja siellä hukkukaamme! Sillä Herra, meidän Jumalamme, hukuttaa meidät ja juottaa meille myrkkyvettä, sillä me olemme syntiä tehneet Herraa vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, '\"Odotetaan rauhaa, mutta hyvää ei tule, paranemisen aikaa, mutta katso, tulee peljästys!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Daanista kuuluu hänen hevostensa korskunta, hänen orhiensa hirnunnasta vapisee koko maa. Ja he tulevat ja syövät maan ja kaiken, mikä siinä on, kaupungin ja siinä asuvaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Sillä katso, minä lähetän teidän sekaanne käärmeitä, myrkkyliskoja, joihin ei lumous tehoa, ja ne purevat teitä, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Missä on virvoitus minun murheeseeni? Minun sydämeni on sairas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Katso, tyttären, minun kansani, huuto kuuluu kaukaisesta maasta: \"Eikö Herra ole Siionissa, eikö ole siellä sen kuningas?\" Miksi he ovat vihoittaneet minut jumalankuvillansa, muukalaisten turhilla jumalilla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Ohi on elonaika, lopussa kesä, mutta ei ole meille apua tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Tyttären, minun kansani, murtumisen tähden olen minä murtunut, minä käyn murheasussa, kauhistus on minut vallannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Eikö Gileadissa ole palsamia, eikö siellä ole parantajaa? Vai miksi eivät tyttären, minun kansani, haavat kasva umpeen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Oi, jospa minun pääni olisi silkkaa vettä ja minun silmäni kyynellähde, niin minä itkisin päivät ja yöt tyttären, minun kansani, kaatuneita!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, '{9:1} Oi, jospa minulla olisi erämaassa matkamiehen yömaja, niin minä jättäisin kansani ja vaeltaisin pois heidän luotaan! Sillä he ovat kaikki avionrikkojia, ovat uskottomain joukkio.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'He jännittävät valheeseen kielensä jousen, eivätkä käytä totuuteen valtaansa maassa; sillä he menevät pahuudesta pahuuteen, mutta minua he eivät tunne, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Varokaa kukin lähimmäistänne, älkää yhteenkään veljeen luottako; sillä jokainen veli viekkaasti pettää ja jokainen lähimmäinen liikkuu panettelijana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'He pettävät toinen toisensa eivätkä puhu totta; he ovat totuttaneet kielensä puhumaan valhetta, ovat tehneet vääryyttä väsyksiin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Sinä asut keskellä vilppiä; vilpillisyydessään he eivät tahdo tuntea minua, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Sentähden, näin sanoo Herra Sebaot: Katso, minä sulatan heidät ja koettelen heitä; sillä mitä muuta minä voisin tehdä tyttären, minun kansani, tähden?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Tappava nuoli on heidän kielensä, vilppiä se puhuu; suullaan he puhuvat rauhaa lähimmäisensä kanssa, mutta sydämessään he juoniansa punovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Enkö minä näistä tällaisista rankaisisi heitä, sanoo Herra, eikö minun sieluni kostaisi tämänkaltaiselle kansalle?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Vuorten tähden minä puhkean itkuun ja valitukseen, erämaan laitumien tähden minä viritän itkuvirren. Sillä ne ovat poltetut, ei kukaan siellä kulje, eivätkä ne kuule karjan ääntä; paenneet ovat taivaan linnut ja eläimet, ovat menneet pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Ja minä teen Jerusalemin kiviroukkioksi, aavikkosutten asunnoksi, ja Juudan kaupungit minä teen autioiksi, asujattomiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Kuka on viisas mies, joka tämän ymmärtää ja jolle Herran suu on puhunut, että hän sen ilmoittaisi? Minkätähden on maa hävitetty, poltettu kuin erämaa, jossa ei kukaan kulje?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Ja Herra sanoi: \"Sentähden, että he ovat hyljänneet minun lakini, jonka minä heille annoin, eivätkä ole kuulleet minun ääntäni eivätkä vaeltaneet sen mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'vaan ovat vaeltaneet sydämensä paatumuksessa ja seuranneet baaleja, niinkuin heidän isänsä olivat heille opettaneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'sentähden sanoo Herra Sebaot, Israelin Jumala, näin: Katso, minä syötän heille, tälle kansalle, koiruohoa ja juotan heille myrkkyvettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Ja minä hajotan heidät kansojen sekaan, joita eivät he eivätkä heidän isänsä ole tunteneet, ja lähetän heidän jälkeensä miekan, kunnes minä heidät lopetan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Näin sanoo Herra Sebaot: Ottakaa vaari, kutsukaa itkijävaimoja tulemaan tänne. Lähettäkää hakemaan viisaita vaimoja, jotta he tulisivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'kiiruhtaisivat ja virittäisivät meistä valitusvirren, niin että silmämme vuotaisivat kyyneleitä ja silmäripsemme tiukkuisivat vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Sillä valitushuuto kuuluu Siionista: Kuinka olemmekaan hävitetyt! Me olemme peräti häpeään joutuneet, sillä meidän täytyy jättää maa, sillä kukistuneet ovat meidän asuntomme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Kuulkaa siis, te naiset, Herran sana, ottakoon korvanne vastaan hänen suunsa puheen; opettakaa tyttärillenne valitusvirsi ja toinen toisellenne itkuvirsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Sillä kuolema on noussut sisään ikkunoistamme, on tullut meidän palatseihimme, tuhotakseen kadulta lapset, toreilta nuorukaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Puhu: Näin sanoo Herra: Ihmisten ruumiita makaa maassa niinkuin lantaa vainiolla, niinkuin lyhteitä leikkaajan jäljessä, eikä ole niitten korjaajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Näin sanoo Herra: Älköön viisas kerskatko viisaudestansa, älköön väkevä kerskatko väkevyydestänsä, älköön rikas kerskatko rikkaudestansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'vaan joka kerskaa, kerskatkoon siitä, että hän on ymmärtäväinen ja tuntee minut: että minä, Herra, teen laupeuden, oikeuden ja vanhurskauden maan päällä. Sillä senkaltaisiin minä mielistyn, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Katso, päivät tulevat, sanoo Herra, jolloin minä rankaisen kaikkia, jotka ovat ympärileikattuja, mutta kuitenkin ympärileikkaamattomia:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, '{9:25} Egyptiä, Juudaa, Edomia, ammonilaisia, Mooabia ja kaikkia päälaen ympäriltä kerittyjä, jotka asuvat erämaassa; sillä kaikki pakanakansat ovat ympärileikkaamattomia, ja koko Israelin heimo on sydämeltään ympärileikkaamaton.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Kuulkaa sana, jonka Herra on puhunut teitä vastaan, te Israelin heimo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Näin sanoo Herra: \"Älkää totutelko itseänne pakanain menoon älkääkä kauhistuko taivaan merkkejä, sillä pakanat niitä kauhistuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Sillä kansat noudattavat turhia jumalia; sillä ne ovat puuta, joka hakataan metsästä, puusepän kätten tekemiä, työaseella tehtyjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Ne koristetaan hopealla ja kullalla sekä kiinnitetään nauloilla ja vasaroilla, niin etteivät ne horju.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Ne ovat kuin linnunpelätin kurkkumaalla, eivät ne voi puhua; kantamalla täytyy niitä kantaa, sillä eivät ne voi astua. Älkää peljätkö niitä, sillä eivät ne voi pahaa tehdä; mutta eivät ne myöskään voi tehdä hyvää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Ei ole ketään sinun vertaistasi, Herra; sinä olet suuri, ja suuri ja voimallinen on sinun nimesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Kuka ei sinua pelkäisi, sinä kansojen kuningas? Sillä siihen sinä olet arvollinen. Sillä kaikissa kansojen viisaissa ja kaikissa heidän valtakunnissansa ei ole yhtäkään sinun vertaistasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'He ovat kaikki tyynni järjettömiä, tyhmiä. Turhain jumalien opettamista! Ne ovat puuta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'ohueksi taottua hopeata, joka tuodaan Tarsiista, ja Uufaan kultaa, taiturin ja kultasepän kätten tekoa. Punasinistä ja punaista purppuraa on niiden puku. Taitajain tekoa ovat ne kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Mutta Herra on totinen Jumala; hän on elävä Jumala ja iankaikkinen kuningas. Hänen vihastansa vapisee maa, ja kansat eivät kestä hänen suuttumustansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Sanokaa heille näin: Jumalat, jotka eivät ole tehneet taivasta eikä maata, ne katoavat maan päältä ja taivaan alta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Hän on tehnyt maan voimallansa, vahvistanut maanpiirin viisaudellansa ja levittänyt taivaat taidollansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Kun hän jylisee, käy vetten pauhina taivaalla, ja hän nostaa pilvet maan ääristä, tekee salamat ja sateen ja tuo tuulen sen säilytyspaikoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Järjetön on jokainen ihminen, tietoa vailla, häpeän saa jokainen kultaseppä veistetystä kuvasta, petosta on hänen valamansa kuva, eikä niissä henkeä ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Turhuutta ne ovat, naurettavia tekeleitä; kun niiden rangaistus tulee, ne hukkuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Näiden kaltainen ei ole hän, joka on Jaakobin osa, sillä hän on kaiken Luoja, ja Israel on hänen perintösukunsa: Herra Sebaot on hänen nimensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Kokoa tavarasi maasta pois, sinä, joka piiritettynä istut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Sillä näin sanoo Herra: Katso, tällä haavaa minä linkoan pois maan asukkaat ja ahdistan heitä, niin että saavat tarpeeksensa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Voi minua minun vammani tähden! Kipeä on minun haavani; mutta minä sanon: Tämä on minun vaivani, minun on se kannettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Minun telttani on hävitetty, ja kaikki minun telttaköyteni ovat katkotut; minun lapseni ovat lähteneet luotani, eikä niitä enää ole. Ei ole enää, kuka telttani pystyttäisi ja nostaisi seinieni kankaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Sillä paimenet olivat järjettömät eivätkä etsineet Herraa; sentähden he eivät menestyneet, vaan koko heidän laumansa hajotettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'ni kuuluu! Katso, se tulee, suuri pauhina pohjoisesta maasta, tekemään Juudan kaupungit autioiksi, aavikkosutten asunnoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Minä tiedän, Herra, ettei ihmisen tie ole hänen vallassansa, eikä miehen vallassa, kuinka hän vaeltaa ja askeleensa ohjaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Kurita minua, Herra, mutta kohtuudella, äläkä vihassasi, ettet minua ylen vähäiseksi tekisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Vuodata vihasi pakanain ylitse, jotka eivät sinua tunne, ja sukukuntain ylitse, jotka eivät sinun nimeäsi avuksensa huuda. Sillä he ovat syöneet Jaakobin, ovat hänet syöneet ja lopettaneet, ja tehneet autioksi hänen asuinsijansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Sana, joka tuli Herralta Jeremialle ja kuului näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, '\"Kuulkaa tämän liiton sanat ja puhukaa ne Juudan miehille ja Jerusalemin asukkaille;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'sano heille: Näin sanoo Herra, Israelin Jumala: Kirottu olkoon se mies, joka ei kuule tämän liiton sanoja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'jonka minä sääsin teidän isillenne silloin, kun minä vein heidät pois Egyptin maasta, rautapätsistä, ja sanoin: Kuulkaa minun ääntäni ja tehkää aivan niin, kuin minä käsken teidän tehdä, niin te olette minun kansani ja minä olen teidän Jumalanne');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'ja pidän valan, jonka olen vannonut teidän isillenne luvaten antaa heille maan, joka vuotaa maitoa ja mettä, niinkuin se teillä tänäkin päivänä on.\" Ja minä vastasin ja sanoin: \"Amen, Herra!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Ja Herra sanoi minulle: \"Julista kaikki nämä sanat Juudan kaupungeissa ja Jerusalemin kaduilla ja sano: Kuulkaa tämän liiton sanat ja noudattakaa niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Sillä minä varoittamalla varoitin teidän isiänne silloin, kun minä johdatin heidät pois Egyptin maasta, ja olen varoittanut varhaisesta alkaen tähän päivään saakka sanoen: \'Kuulkaa minun ääntäni\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Mutta he eivät kuulleet eivätkä korvaansa kallistaneet, vaan vaelsivat kukin pahan sydämensä paatumuksessa. Niin minä tuotin heidän päällensä kaikki tämän liiton sanat, joita minä olin käskenyt heidän noudattaa, mutta joita he eivät noudattaneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Ja Herra sanoi minulle: \"Juudan miesten ja Jerusalemin asukasten keskuudessa on salaliitto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'He ovat kääntyneet takaisin ensimmäisten esi-isiensä pahoihin tekoihin, niiden, jotka eivät tahtoneet kuulla minun sanojani, ja he ovat seuranneet muita jumalia ja palvelleet niitä. Israelin heimo ja Juudan heimo ovat rikkoneet minun liittoni, jonka minä tein heidän isiensä kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Sentähden, näin sanoo Herra: Katso, minä tuotan heille onnettomuuden, josta heillä ei ole pääsyä; ja kun he minua huutavat, en minä kuule heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Ja jos Juudan kaupungit ja Jerusalemin asukkaat menevät ja huutavat niitä jumalia, joille he ovat uhreja polttaneet, niin ne eivät heitä pelasta heidän onnettomuutensa aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Sillä yhtä paljon kuin sinulla on kaupunkeja, on sinulla, Juuda, jumalia, ja yhtä paljon kuin Jerusalemissa on katuja, te olette pystyttäneet alttareja häpeäjumalalle, alttareja polttaaksenne uhreja Baalille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Mutta sinä älä rukoile tämän kansan puolesta, älä kohota heidän puolestaan huutoa ja rukousta, sillä en minä kuule, kun he minua avuksi huutavat onnettomuutensa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Mitä tekee minun rakkaani minun temppelissäni? Juoniako punoo? Ottavatko mahtimiehet, ottaako uhriliha sinusta pois pahuutesi-silloin sinä riemuitsisit!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, '\'Vihreä öljypuu, ihana, kaunishedelmäinen\' -sillä nimellä Herra sinua kutsui. Suuren jylinän pauhatessa hän sytytti sen tuleen, ja sen oksat turmeltuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Ja Herra Sebaot, joka sinut istutti, on päättänyt sinun osaksesi onnettomuuden Israelin heimon ja Juudan heimon pahuuden tähden, jota he ovat harjoittaneet ja jolla ovat vihoittaneet minut, polttamalla uhreja Baalille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Ja Herra ilmoitti minulle, ja minä sain tietää, sinä näytit minulle silloin heidän hankkeensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Ja minä olin kuin kesy karitsa, joka viedään teurastettavaksi, enkä tiennyt heidän pitäneen neuvoa minua vastaan: \"Tuhotkaamme puu hedelminensä, hävittäkäämme hänet elävien maasta, niin ettei hänen nimeänsä enää muisteta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Mutta Herra Sebaot on vanhurskas tuomari, joka tutkii munaskuut ja sydämen. Salli minun nähdä sinun kostavan heille, sillä sinun haltuusi minä olen uskonut asiani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Sentähden, näin sanoo Herra Anatotin miehistä, jotka väijyvät sinun henkeäsi sanoen: \"Älä ennusta Herran nimeen, ettet kuolisi meidän kättemme kautta\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'sentähden, näin sanoo Herra Sebaot: \"Katso, minä kostan heille; heidän nuoret miehensä kuolevat miekkaan, heidän poikansa ja tyttärensä kuolevat nälkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Heistä ei jäännöstä jää, sillä minä tuotan onnettomuuden Anatotin miehille heidän rangaistusvuotenansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Sinä, Herra, olet vanhurskas; voisinko minä riidellä sinua vastaan? Kuitenkin minä kysyn sinulta, mikä oikeus on. Miksi jumalattomain tie menestyy? Miksi kaikki uskottomat saavat elää rauhassa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Sinä heidät istutat, he myös juurtuvat; he kasvavat, kantavat myös hedelmää. Heidän suussansa sinä olet lähellä, mutta kaukana heidän sisimmästään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Mutta sinä, Herra, tunnet minut; sinä näet minut ja tutkit minun sydämeni, millainen se on sinun edessäsi. Tempaa heidät pois niinkuin lampaat teuraiksi ja vihi heidät tapon päivää varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Kuinka kauan täytyy maan surra ja kaiken kedon ruohon kuivettua? Eläimet ja linnut hukkuvat siinä asuvaisten pahuuden tähden; sillä nämä sanovat: \"Ei tule hän näkemään meidän loppuamme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, '\"Jos sinä jalkamiesten kanssa juokset ja ne sinut väsyttävät, kuinka sinä kävisit kilpaan hevosten kanssa? Ja jos sinä vaarattomalla maalla oletkin turvassa, kuinka käy sinun Jordanin rantatiheikössä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Sillä omat veljesikin ja isäsi huone ovat petolliset sinua kohtaan, hekin huutavat täyttä kurkkua selkäsi takana. Älä usko heitä, vaikka he sinua ystävällisesti puhuttelevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Minä olen jättänyt huoneeni, hyljännyt perintöosani; olen antanut sieluni rakkaimman hänen vihollistensa käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Hän, minun perintöosani, oli minulle kuin leijona metsässä, hän kiljui minua vastaan, sentähden minä vihastuin häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Onko minun perintöosani kirjava petolintu, jonka ympärillä on petolintuja? Menkää, kootkaa kaikki metsän eläimet, tuokaa ne ruualle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Monet paimenet ovat turmelleet minun viinitarhani, tallanneet minun peltopalstani, tehneet ihanan peltopalstani autioksi erämaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Se on tehty autioksi, se suree minun edessäni autiona. Koko maa on hävitetty, sillä ei ollut ketään, joka olisi pannut sitä sydämelleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Kaikkien erämaan kalliokukkulain ylitse tulivat hävittäjät, sillä Herran miekka syö maan toisesta äärestä hamaan toiseen; ei pelastu mikään, mikä lihaa on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'He ovat kylväneet nisuja ja niittäneet ohdakkeita; ovat nähneet vaivaa näännyksiin asti, saamatta hyötyä. Niinpä saakaa häpeä sadostanne Herran vihan hehkun tähden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Näin sanoo Herra kaikista minun pahoista naapureistani, jotka koskevat siihen perintöosaan, minkä minä olen antanut kansalleni Israelille: \"Katso, minä tempaan heidät pois heidän maastansa, ja Juudan heimon minä tempaan pois heidän keskeltänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Mutta senjälkeen kuin minä olen temmannut heidät pois, minä jälleen armahdan heitä ja palautan heidät, itsekunkin perintöosaansa ja itsekunkin maahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Ja jos he oppivat minun kansani tiet, niin että vannovat minun nimeeni: \'Niin totta kuin Herra elää\', niinkuin he opettivat minun kansaani vannomaan Baalin kautta, niin heidät rakennetaan minun kansani keskeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Mutta jos he eivät kuule, niin minä tempaan pois ja hukutan sen kansan, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Näin sanoi Herra minulle: \"Mene ja osta itsellesi liinainen vyö ja pane se kupeillesi, mutta älä anna sen tulla veteen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Ja minä ostin vyön Herran sanan mukaan ja panin sen kupeilleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Sitten Herran sana tuli minulle toisen kerran, tämä sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, '\"Ota vyö, jonka sinä ostit ja joka on kupeillasi, ja nouse, mene Eufratille ja kätke se siellä kallion koloon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Ja minä menin ja kätkin sen Eufratiin, niinkuin Herra oli käskenyt minun tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Ja pitkän ajan kuluttua Herra sanoi minulle: \"Nouse, mene Eufratille ja ota se vyö, jonka minä käskin sinun kätkeä sinne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Niin minä menin Eufratille, kaivoin ja otin vyön siitä paikasta, johon olin sen kätkenyt; ja katso, vyö oli turmeltunut eikä kelvannut mihinkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, '\"Näin sanoo Herra: Samalla tavoin minä tuotan turmion Juudan ja Jerusalemin suurelle ylpeydelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Tämä paha kansa, joka ei tahdo kuulla minun sanojani, joka vaeltaa sydämensä paatumuksessa, seuraa muita jumalia, palvelee ja kumartaa niitä, tulee tämän vyön kaltaiseksi, joka ei mihinkään kelpaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Sillä niinkuin vyö liittyy miehen kupeisiin, niin minä liitin koko Israelin heimon ja koko Juudan heimon itseeni, sanoo Herra, että se olisi minun kansani, minulle kunniaksi, ylistykseksi ja kirkkaudeksi; mutta he eivät totelleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Sentähden sano heille tämä sana: Näin sanoo Herra, Israelin Jumala: Jokainen leili täytetään viinillä. Ja jos he sanovat sinulle: \'Emmekö me tietäisi, että jokainen leili täytetään viinillä?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'niin sano heille: Näin sanoo Herra: Katso, minä täytän kaikki tämän maan asukkaat, kuninkaat, jotka istuvat Daavidin valtaistuimella, papit ja profeetat ja kaikki Jerusalemin asukkaat päihtymyksellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Ja minä murskaan heidät, toisen toistansa vastaan, sekä isät että lapset, sanoo Herra. Minä en sääli, en säästä enkä armahda, niin että jättäisin heidät hävittämättä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Kuulkaa, ottakaa korviinne, älkää ylpeilkö, sillä Herra on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Antakaa Herralle, teidän Jumalallenne, kunnia, ennenkuin tulee pimeä ja jalkanne loukkaantuvat vuoriin hämärissä. Silloin te odotatte valoa, mutta hän muuttaa sen pilkkopimeäksi, tekee sen synkeydeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Mutta ellette kuule tätä, niin minun sieluni salassa itkee sellaista ylpeyttä, itkee katkerasti, ja minun silmäni vuotavat kyyneleitä, kun Herran lauma viedään vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, '\"Sano kuninkaalle ja kuninkaan äidille: Istukaa alhaiselle sijalle, sillä pudonnut on päästänne teidän kunniankruununne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Etelämaan kaupungit ovat suljetut, eikä ole avaajaa; koko Juuda on viety pakkosiirtolaisuuteen, pakkosiirtolaisuuteen kaikki kansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Nostakaa silmänne ja katsokaa, kuinka ne tulevat pohjoisesta. Missä on lauma, joka oli sinun haltuusi annettu, nuo sinun lampaasi, sinun kunniasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Mitä sanot, kun hän panee sinulle päämiehiksi ne, jotka olit ystäviksesi totutellut? Eivätkö tuskat kourista sinua niinkuin synnyttävää vaimoa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Ja jos sanot sydämessäsi: \'Minkätähden on minulle näin käynyt?\' -suuren syntisi tähden sinun liepeesi kohotettiin, tehtiin väkivaltaa sinun kantapäillesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Voiko etiopialainen muuttaa ihonsa ja pantteri pilkkunsa? Yhtä vähän te voitte tehdä hyvää, te pahantekoon tottuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Ja minä hajotan heidät kuin oljenkorret, jotka lentävät erämaan tuulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Tämä on sinun arpasi, sinun mitattu osasi minulta, sanoo Herra, koska olet unhottanut minut ja luottanut valheeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Niinpä minäkin nostan sinulta liepeet kasvojen yli, ja sinun häpeäsi näkyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Sinun aviorikoksesi, hirnumisesi, riettaan haureutesi, sinun iljetyksesi kedon kukkuloilla minä olen nähnyt. Voi sinua, Jerusalem! Et sinä puhdistu, et vielä pitkään aikaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Herran sana, joka tuli Jeremialle suuren kuivuuden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, '\"Juuda murehtii, sen portit raukeavat, kallistuvat murheasussa maahan; ja Jerusalemista nousee valitushuuto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Heidän ylimyksensä lähettävät alaisiansa vedelle. Nämä tulevat kaivoille, eivät löydä vettä, palajavat astiat tyhjinä, ovat pettyneet ja häpeissänsä ja peittävät päänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Peltomaan tähden, joka pakahtuu, kun ei ole satanut maassa, ovat peltomiehet pettyneinä ja peittävät päänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Peurakin kedolla poikii ja hylkää vasikkansa, kun ei ole mitään vihantaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Ja villiaasit seisovat kalliokukkuloilla, haukkovat ilmaa niinkuin aavikkosudet; niiden silmät ovat riutuneet, kun ei ruohoa ole.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Vaikka pahat tekomme todistavat meitä vastaan, tee työsi, Herra, nimesi tähden; sillä meidän luopumuksemme ovat monet, sinua vastaan me olemme syntiä tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Sinä Israelin toivo, sen vapahtaja ahdingon aikana, minkätähden sinä olet kuin muukalainen maassa, kuin matkamies, joka poikkeaa majaan vain yöpyäksensä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Minkätähden sinä olet kuin tyrmistynyt mies, kuin sankari, joka ei voi auttaa? Ja kuitenkin sinä olet meidän keskellämme, Herra, ja me olemme otetut sinun nimiisi; älä meitä jätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Näin sanoo Herra tästä kansasta: Noin he mielellänsä harhailevat, eivät pidätä jalkojansa. Ei Herra mielisty heihin; hän muistaa nyt heidän pahat tekonsa ja rankaisee heidän syntinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Ja Herra sanoi minulle: \"Älä rukoile tämän kansan puolesta, sen hyväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Vaikka he paastoavat, en minä kuule heidän huutoansa, ja vaikka he uhraavat polttouhreja ja ruokauhreja, en minä heihin mielisty, vaan miekalla, nälällä ja rutolla minä heidät lopetan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Niin minä sanoin: \"Voi, Herra, Herra! Katso, profeetat sanovat heille: \'Ei teidän tarvitse nähdä miekkaa eikä kärsiä nälkää, vaan minä annan teille vakaan rauhan tässä paikassa\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Mutta Herra sanoi minulle: \"Valhetta ennustavat profeetat minun nimessäni; minä en ole lähettänyt heitä, en käskenyt heitä enkä puhunut heille. Valhenäkyjä, turhia ennustuksia ja oman sydämensä petosta he ennustavat teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Sentähden, näin sanoo Herra profeetoista, jotka ennustavat minun nimessäni, vaikka minä en ole heitä lähettänyt, ja jotka sanovat, että miekka ja nälkä ei tule tähän maahan: miekkaan ja nälkään hukkuvat nämä profeetat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Ja kansa, jolle he ennustavat, suistuu Jerusalemin kaduilla nälkään ja miekkaan, eikä kukaan heitä hautaa-ei heitä, ei heidän vaimojansa, poikiansa eikä tyttäriänsä. Minä vuodatan heidän pahuutensa heidän päällensä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Ja sano heille tämä sana: Minun silmistäni vuotavat kyyneleet yötä päivää, eivät lakkaa; sillä neitsyt, tytär, minun kansani, on raskaasti runneltu, ylen kipeällä iskulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Jos minä kedolle lähden, katso-miekan kaatamia! Jos tulen kaupunkiin, katso-kalvava nälkä! Sillä sekä profeetat että papit kiertävät maata eivätkä mitään tiedä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Oletko sinä kokonaan hyljännyt Juudan, vierooko sielusi Siionia? Minkätähden olet lyönyt meitä, niin ettemme voi parantua? Odotetaan rauhaa, mutta hyvää ei tule, paranemisen aikaa, mutta katso, tulee peljästys!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Me tunnemme, Herra, jumalattomuutemme, isiemme pahat teot, sillä sinua vastaan me olemme syntiä tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Älä hylkää, nimesi tähden! Älä anna kunniasi valtaistuinta häväistäväksi; muista, älä riko, liittoasi meidän kanssamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Onko pakanain turhista jumalista sateen antajiksi, tahi taivasko antaa sadekuurot? Etkö sinä ole Herra, meidän Jumalamme? Sinua me odotamme, sillä sinä olet tehnyt kaiken tämän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Ja Herra sanoi minulle: \"Vaikka Mooses ja Samuel seisoisivat minun edessäni, ei minun sieluni taipuisi tämän kansan puoleen. Aja heidät pois minun kasvojeni edestä, he menkööt!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Ja jos he kysyvät sinulta: \'Minne meidän on mentävä?\' niin vastaa heille: Näin sanoo Herra: Joka ruton oma, se ruttoon, joka miekan, se miekkaan, joka nälän, se nälkään, joka vankeuden, se vankeuteen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Ja minä asetan heille neljänkaltaiset käskijät, sanoo Herra: miekan surmaamaan, koirat raahaamaan, taivaan linnut ja maan eläimet syömään ja hävittämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Minä panen heidät kauhistukseksi kaikille valtakunnille maan päällä Manassen, Hiskian pojan, Juudan kuninkaan, tähden, kaiken tähden, mitä hän teki Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Kuka säälii sinua, Jerusalem, kuka surkuttelee sinua, kuka poikkeaa kysymään sinun vointiasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Sinä olet hyljännyt minut, sanoo Herra, olet kääntynyt pois; niinpä minä olen ojentanut käteni sinua vastaan, ja minä hävitän sinut. En jaksa enää armahtaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Minä viskaan viskimellä heidät maan porteilla; minä teen lapsettomaksi, minä hukutan kansani, kun he eivät ole teiltänsä kääntyneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Heidän leskiänsä on oleva enemmän kuin meren hiekkaa; minä tuon heidän nuorukaistensa äitien kimppuun hävittäjän keskellä päivää, langetan äkkiä heidän päällensä tuskan ja kauhun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Seitsemän pojan synnyttäjä menehtyy ja huokaisee henkensä pois; hänen aurinkonsa laski, kun vielä oli päivä, hän joutui häpeään, sai hävetä. Ja mitä heistä jää, sen minä annan miekalle alttiiksi heidän vihollistensa edessä, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Voi minua, äitini, kun minut synnytit riidan ja toran mieheksi koko maalle! En ole lainaksi antanut enkä lainaksi ottanut; kuitenkin kiroavat minua kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Herra sanoi: \"Totisesti, minä kirvoitan sinut, niin että sinun käy hyvin; totisesti, minä saatan viholliset pyytämään sinua avuksensa onnettomuuden ja ahdistuksen aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Murtuuko rauta, pohjoisesta tuotu rauta, ja vaski? -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Sinun tavarasi ja aarteesi minä annan ryöstettäviksi, ilman hintaa kaikkien sinun syntiesi tähden, kaikkia rajojasi myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Ja minä panen sinut vihollistesi kanssa kulkemaan maata, jota et tunne. Sillä minun vihani tuli on syttynyt; se leimuaa teitä vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Herra, sinä sen tiedät. Muista minua ja pidä minusta huoli ja kosta puolestani minun vainoojilleni; älä tempaa minua pois, sinä, joka olet pitkämielinen. Huomaa, kuinka minä kannan häväistystä sinun tähtesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Sinun sanasi tulivat, ja minä söin ne, ja sinun sanasi olivat minulle riemu ja minun sydämeni ilo; sillä minä olen otettu sinun nimiisi, Herra, Jumala Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'En ole minä istunut iloitsemassa ilonpitäjäin seurassa. Sinun kätesi tähden minä olen istunut yksinäni, sillä sinä olet täyttänyt minut vihallasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Miksi kestää minun kipuni ainiaan ja haavani on paha eikä tahdo parantua? Sinä olet minulle kuin ehtyvä puro, kuin vesi, joka ei pysy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Sentähden, näin sanoo Herra: \"Jos sinä käännyt, niin minä sallin sinun kääntyä, ja sinä saat seisoa minun edessäni. Ja jos sinä tuot esiin jaloa, et arvotonta, niin sinä saat olla minun suunani. He kääntyvät sinun tykösi, mutta sinä et käänny heidän tykönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Ja minä teen sinut vahvaksi vaskimuuriksi tätä kansaa vastaan, ja he sotivat sinua vastaan, mutta eivät voita sinua; sillä minä olen sinun kanssasi, minä vapahdan ja pelastan sinut, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Minä pelastan sinut pahain käsistä ja päästän sinut väkivaltaisten kourista.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, '\"Älä ota itsellesi vaimoa, älköönkä sinulle tulko poikia ja tyttäriä tässä paikassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Sillä näin sanoo Herra niistä pojista ja tyttäristä, jotka syntyvät tässä paikassa, ja heidän äideistänsä, jotka heidät synnyttävät, ja heidän isistänsä, jotka heidät siittävät tässä maassa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'He kuolevat tuskallisiin tauteihin, ei heille pidetä valittajaisia, ei heitä haudata; he tulevat maan lannaksi. He hukkuvat miekkaan ja nälkään, ja heidän ruumiinsa tulevat taivaan lintujen ja maan eläinten ruuaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Sillä näin sanoo Herra: Älä mene suruhuoneeseen, älä käy valittajaisiin äläkä heitä surkuttele, sillä minä otan rauhani pois tältä kansalta, sanoo Herra, armoni ja laupeuteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'He kuolevat, sekä suuret että pienet, tässä maassa; ei heitä haudata eikä heille valittajaisia pidetä, ei kukaan viileskele ihoansa eikä ajele päätänsä paljaaksi heidän tähtensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Ei taiteta heille leipää lohdutukseksi heidän surussansa kuolleen tähden, eikä heille anneta juotavaksi lohdutusmaljaa heidän isänsä ja äitinsä tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Älä mene pitotaloon istumaan heidän kanssansa, syömään ja juomaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä lopetan tästä paikasta teidän silmienne edessä ja teidän päivinänne riemun ja ilon huudon, huudon yljälle ja huudon morsiamelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Kun sinä ilmoitat tälle kansalle kaikki nämä sanat ja he sanovat sinulle: \'Minkätähden Herra uhkaa meitä kaikella tällä suurella onnettomuudella, ja mikä on rikoksemme, mikä syntimme, jonka olemme tehneet Herraa, meidän Jumalaamme, vastaan?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'niin sano heille: Sentähden että teidän isänne hylkäsivät minut, sanoo Herra, ja seurasivat muita jumalia, palvelivat niitä ja kumarsivat niitä, mutta hylkäsivät minut eivätkä noudattaneet minun lakiani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Ja te olette tehneet pahemmin kuin teidän isänne, ja katso, te vaellatte kukin pahan sydämenne paatumuksessa, kuulematta minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Niin minä heitän teidät pois tästä maasta maahan, jota te ette tunne eivätkä teidän isänne tunteneet, ja siellä te saatte palvella muita jumalia päivät ja yöt, sillä minä en teille armoa anna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Sentähden, katso, päivät tulevat, sanoo Herra, jolloin ei enää sanota: \'Niin totta kuin Herra elää, joka johdatti israelilaiset Egyptin maasta\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'vaan: \'Niin totta kuin Herra elää, joka johdatti israelilaiset pohjoisesta maasta ja kaikista muista maista, joihin hän oli heidät karkoittanut\'. Sillä minä palautan heidät heidän omaan maahansa, jonka minä annoin heidän isillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Katso, minä käsken tulemaan monta kalastajaa, sanoo Herra, ja ne heitä kalastavat, ja sen jälkeen minä käsken tulemaan monta metsästäjää, ja ne heitä metsästävät kaikilta vuorilta ja kaikilta kukkuloilta ja kallioiden rotkoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Sillä minun silmäni tarkkaavat kaikkia heidän teitänsä, ne eivät ole minulta salassa, eikä heidän rikoksensa ole kätketty minun silmäini edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Ja minä kostan ensin kaksinkertaisesti heidän rikoksensa ja syntinsä, koska he ovat saastuttaneet minun maani iljetystensä raadoilla ja täyttäneet minun perintöosani kauhistuksillansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Herra, minun voimani ja varustukseni, minun pakopaikkani hädän päivänä! Sinun tykösi tulevat pakanat maan ääristä ja sanovat: \"Petosta vain perivät meidän isämme, turhia jumalia, joista ei ainoakaan auttaa taida.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Voiko ihminen tehdä itsellensä jumalia? Eivät ne jumalia ole!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, '\"Sentähden, katso, minä saatan heidät tuntemaan-tuntemaan tällä haavaa-minun käteni ja minun voimani, ja he tulevat tietämään, että minun nimeni on Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, '\"Juudan synti on kirjoitettu rautapiirtimellä, timanttikärjellä, kaiverrettu heidän sydämensä tauluun ja teidän alttarienne sarviin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'ja niin heidän lapsensa muistavat alttarinsa ja asera-karsikkonsa viheriäin puitten vieressä, korkeilla kukkuloilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Oman vuoreni, joka on kedolla, niin myös sinun tavarasi, kaikki sinun aarteesi ja sinun uhrikukkulasi minä annan ryöstettäviksi synnin tähden kaikkia rajojasi myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Sinun on luovuttava perintöosastasi, jonka minä olen sinulle antanut; ja minä saatan sinut vihollistesi orjuuteen maassa, jota sinä et tunne. Sillä te olette sytyttäneet minun vihani tulen; se on palava iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Näin sanoo Herra: Kirottu on se mies, joka turvaa ihmisiin ja tekee lihan käsivarreksensa ja jonka sydän luopuu Herrasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Hän jää alastomaksi arolle eikä näe mitään onnea tulevan; hän asuu poudan polttamissa paikoissa erämaassa, asumattomassa suolamaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Siunattu on se mies, joka turvaa Herraan, jonka turvana Herra on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Hän on kuin veden partaalle istutettu puu, joka ojentaa juurensa puron puoleen; helteen tuloa se ei peljästy, vaan sen lehvä on vihanta, ei poutavuonnakaan sillä ole huolta, eikä se herkeä hedelmää tekemästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Petollinen on sydän ylitse kaiken ja pahanilkinen; kuka taitaa sen tuntea?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Minä, Herra, tutkin sydämen, koettelen munaskuut, ja annan jokaiselle hänen vaelluksensa mukaan, hänen töittensä hedelmän mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Peltokana, joka hautoo, mitä ei ole muninut, on se, joka hankkii rikkautta vääryydellä; päiviensä puolivälissä hänen täytyy se jättää, ja hänen loppunsa on houkan loppu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Kunnian valtaistuin, korkea ikiajoista, meidän pyhäkkömme paikka!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Israelin toivo, sinä Herra! Kaikki, jotka sinut hylkäävät, joutuvat häpeään. \"Jotka minusta luopuvat, ne kirjoitetaan tomuun. Sillä he ovat hyljänneet elävän veden lähteen, Herran.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Paranna minut, Herra, niin minä parannun, auta minua, niin olen autettu. Sillä sinä olet minun ylistykseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Katso, he sanovat minulle: \"Missä on Herran sana? Toteutukoon se!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Mutta minä en ole vetäytynyt pois olemasta paimenena, sinua seuraamasta, enkä toivonut turmion päivää; sinä tiedät sen. Mitä minun huuliltani on lähtenyt, se on sinun kasvojesi edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Älä tule minulle peljätykseksi, sinä, minun turvani onnettomuuden päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Joutukoot häpeään ne, jotka minua vainoavat, mutta älä anna minun häpeään tulla; peljästykööt he, mutta älä anna minun peljästyä. Tuota heille onnettomuuden päivä ja tuhoa heidät kaksinkertaisella tuholla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Näin sanoi Herra minulle: \"Mene ja seiso Kansanportissa, josta Juudan kuninkaat tulevat ja josta he menevät, ja kaikissa Jerusalemin porteissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Ja sano heille: Kuulkaa Herran sana, te Juudan kuninkaat ja koko Juuda ja kaikki Jerusalemin asukkaat, jotka tulette näistä porteista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Näin sanoo Herra: Ottakaa itsestänne tarkka vaari, älkää sapatinpäivänä mitään kantamusta kantako älkääkä mitään tuoko Jerusalemin porteista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Älkää viekö sapatinpäivänä mitään kantamusta taloistanne älkääkä tehkö mitään työtä, vaan pyhittäkää sapatinpäivä, niinkuin minä käskin teidän isienne tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Mutta he eivät kuulleet, eivät korvaansa kallistaneet, vaan olivat niskureita, niin etteivät kuulleet eivätkä ottaneet kuritusta varteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Jos kuulette minua, sanoo Herra, niin ettette tuo mitään kantamusta tämän kaupungin porteista sapatinpäivänä, vaan pyhitätte sapatinpäivän, niin ettette silloin tee mitään työtä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'niin tulee tämän kaupungin porteista sisälle, ajaen vaunuilla ja hevosilla, kuninkaita ja ruhtinaita, jotka istuvat Daavidin valtaistuimella, tulevat he ja heidän ruhtinaansa, Juudan miehet ja Jerusalemin asukkaat, ja tämä kaupunki on oleva asuttu iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Ja Juudan kaupungeista ja Jerusalemin ympäriltä, Benjaminin maasta ja Alankomaasta, Vuoristosta ja Etelämaasta tulee niitä, jotka tuovat polttouhreja ja teurasuhreja, ruokauhreja ja suitsutusuhreja, tuovat kiitosuhreja Herran huoneeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Mutta jos ette kuule minua ettekä pyhitä sapatinpäivää, vaan kannatte kantamuksia ja kuljette Jerusalemin porteista sapatinpäivänä, niin minä sytytän tuleen sen portit, ja tuli on kuluttava Jerusalemin palatsit, eikä se ole sammuva.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Sana, joka tuli Jeremialle Herralta ja kuului:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, '\"Nouse ja mene alas savenvalajan huoneeseen; siellä minä annan sinun kuulla sanani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Niin minä menin alas savenvalajan huoneeseen, ja katso, hän teki työtä pyöränsä ääressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Ja jos astia, jota hän valmisti, meni pilalle, niinkuin savi voi mennä savenvalajan käsissä, niin hän teki siitä taas toisen astian, miten vain savenvalaja näki parhaaksi tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Silloin tuli minulle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, '\"Enkö minä voi tehdä teille, te Israelin heimo, niinkuin tekee tuo savenvalaja, sanoo Herra. Katso, niinkuin savi on savenvalajan kädessä, niin te olette minun kädessäni, te Israelin heimo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Yhden kerran minä uhkaan temmata pois, hajottaa ja hävittää kansan ja valtakunnan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'mutta jos se kansa kääntyy pois pahuudestaan, josta minä sitä uhkasin, niin minä kadun sitä pahaa, jota ajattelin tehdä sille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Toisen kerran taas minä lupaan rakentaa ja istuttaa kansan ja valtakunnan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'mutta jos se tekee sitä, mikä on pahaa minun silmissäni, eikä kuule minun ääntäni, niin minä kadun sitä hyvää, jota olin luvannut tehdä sille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Sano siis nyt Juudan miehille ja Jerusalemin asukkaille: Näin sanoo Herra: Katso, minä hankin teille onnettomuutta ja pidän neuvoa teitä vastaan. Kääntykää siis kukin pahalta tieltänne ja parantakaa vaelluksenne ja tekonne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Mutta he vastaavat: \'Se on turhaa! Sillä me vaellamme omien neuvojemme mukaan, ja me teemme kukin oman pahan sydämensä paatumuksen mukaan.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Sentähden, näin sanoo Herra: \"Kysykää kansojen keskuudessa, kuka on tämänkaltaista kuullut? Ylen kauhistuttavia tekoja on tehnyt neitsyt Israel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Luopuuko aukealta kalliolta Libanonin lumi? Ehtyvätkö kaukaa virtaavat vedet, kylmät, kuohuvaiset?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Mutta minun kansani on unhottanut minut, he polttavat uhreja turhille jumalille. Nämä ovat saaneet heidät kompastumaan teillänsä, ikivanhoilla poluilla, niin että he ovat joutuneet kulkemaan syrjäpolkuja, raivaamatonta tietä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Niin he tekevät maansa kauhistukseksi, ikuiseksi ivan vihellykseksi. Jokainen, joka ohitse kulkee, kauhistuu ja pudistaa päätänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Niinkuin itätuuli minä hajotan heidät vihollisen edessä; minä näytän heille selkäni enkä kasvojani heidän hätänsä päivänä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Mutta he sanoivat: \"Tulkaa, pitäkäämme neuvoa Jeremiaa vastaan. Sillä ei laki lopu papilta, ei neuvo viisaalta eikä sana profeetalta. Tulkaa, lyökäämme hänet kielellä, älkäämme kuunnelko lainkaan hänen puheitansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Kuuntele sinä, Herra, minua ja kuule, mitä minun vastustajani puhuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Onko hyvä pahalla kostettava, sillä he ovat kaivaneet minulle kuopan? Muista, kuinka minä olen seisonut sinun edessäsi ja puhunut hyvää heidän puolestansa, kääntääkseni pois sinun vihasi heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Sentähden jätä heidän lapsensa nääntymään nälkään ja anna heidät alttiiksi miekalle, ja tulkoot heidän vaimonsa lapsettomiksi ja leskiksi, heidän miehensä surmatkoon rutto, ja heidän nuorukaisensa kaatakoon sodassa miekka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Kuulukoon huuto heidän huoneistansa, kun sinä äkkiä tuot heidän kimppuunsa rosvojoukon. Sillä he ovat kaivaneet kuopan pyydystääkseen minut ja virittäneet salaa pauloja minun jaloilleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Mutta sinä, Herra, tiedät kaikki heidän murha-aikeensa minua vastaan. Älä anna anteeksi heidän rikostansa äläkä pyyhi pois heidän syntiänsä kasvojesi edestä. Kaatukoot he sinun kasvojesi edessä. Tee tämä heille vihasi aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Herra sanoi näin: \"Mene ja osta savenvalajalta ruukku ja ota mukaasi kansan ja pappien vanhimpia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Lähde sitten Ben-Hinnomin laaksoon, joka on Sirpaleportin edustalla, ja julista siellä sanat, jotka minä sinulle puhun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Ja sano: Kuulkaa Herran sana, te Juudan kuninkaat ja Jerusalemin asukkaat: Näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä annan sellaisen onnettomuuden kohdata tätä paikkaa, että jokaisen korvat soivat, joka sen kuulee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'sentähden että he ovat hyljänneet minut ja muuttaneet vieraaksi tämän paikan, ovat polttaneet siinä uhreja muille jumalille, joita he eivät tunteneet, eivät he eivätkä heidän isänsä eivätkä Juudan kuninkaat, ja täyttäneet tämän paikan viattomain verellä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'ovat rakentaneet uhrikukkuloita Baalille ja polttaneet tulessa lapsiansa polttouhreiksi Baalille, mitä minä en ole käskenyt enkä puhunut ja mikä ei ole minun mieleeni tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Sentähden, katso, päivät tulevat, sanoo Herra, jolloin tätä paikkaa ei enää sanota Toofetiksi eikä Ben-Hinnomin laaksoksi, vaan \'Murhalaaksoksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Ja minä teen tyhjäksi Juudan ja Jerusalemin neuvon tässä paikassa ja annan heidän kaatua miekkaan vihollistensa edessä, annan heidät niiden käsiin, jotka etsivät heidän henkeänsä, ja annan heidän ruumiinsa ruuaksi taivaan linnuille ja maan eläimille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Ja minä teen tämän kaupungin kauhistukseksi ja ivan vihellykseksi. Jokainen, joka ohitse kulkee, kauhistuu ja viheltää kaikille sen haavoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Ja minä panen heidät syömään poikiensa ja tyttäriensä lihaa, ja he syövät toinen toisensa lihaa siinä hädässä ja ahdistuksessa, jolla heitä ahdistavat heidän vihollisensa, ne, jotka etsivät heidän henkeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Särje ruukku niiden miesten nähden, jotka ovat tulleet sinun kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'Ja sano heille: Näin sanoo Herra Sebaot: Niin minä särjen tämän kansan ja tämän kaupungin, kuin särjetään savenvalajan astia, ettei sitä enää eheäksi saa. Ja Toofetiin haudataan, kun ei ole muualla tilaa, minne haudata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Niin minä teen tälle paikalle, sanoo Herra, ja sen asukkaille: minä teen tämän kaupungin Toofetin kaltaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Jerusalemin talot ja Juudan kuningasten talot tulevat Toofetin paikan kaltaisiksi-nuo saastaiset talot kaikki tyynni, joiden katoilla he ovat polttaneet uhreja kaikelle taivaan joukolle ja vuodattaneet juomauhreja muille jumalille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Ja Jeremia tuli Toofetista, johon Herra oli lähettänyt hänet ennustamaan, ja asettui Herran huoneen esikartanoon ja sanoi kaikelle kansalle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, '\"Näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä tuotan tämän kaupungin ylitse ja kaikkien sen alaisten kaupunkien ylitse kaiken sen onnettomuuden, jolla minä olen sitä uhannut, koska ne ovat olleet niskureita eivätkä ole kuulleet minun sanojani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Mutta pappi Pashur, Immerin poika, joka oli Herran temppelin ylivalvoja, kuuli Jeremian ennustavan nämä sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Ja Pashur löi profeetta Jeremiaa ja pani hänet jalkapuuhun, joka oli Herran huoneeseen kuuluvassa Benjaminin yläportissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Kun Pashur seuraavana päivänä päästi Jeremian jalkapuusta, sanoi Jeremia hänelle: \"Herra ei kutsu sinua nimellä Pashur, vaan Maagor-Missabib.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Sillä näin sanoo Herra: Katso, minä teen sinut kauhistukseksi sekä itsellesi että kaikille ystävillesi; he kaatuvat vihollistensa miekkaan sinun silmiesi nähden, ja koko Juudan minä annan Baabelin kuninkaan käsiin, ja hän vie heidät Baabeliin pakkosiirtolaisuuteen ja surmaa heitä miekalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Ja minä annan kaikki tämän kaupungin rikkaudet, kaiken sen vaivannäön ja kaikki sen kalleudet, kaikki Juudan kuningasten aarteet minä annan heidän vihollistensa käsiin; nämä ryöstävät ne ja ottavat ne ja vievät ne Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Ja sinä, Pashur, ynnä kaikki, jotka talossasi asuvat, te saatte vaeltaa vankeuteen, ja sinä tulet Baabeliin; sinne sinä kuolet ja sinne sinut haudataan, sinut ja kaikki ystäväsi, joille olet valhetta ennustanut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Sinä olet taivutellut minua, Herra, ja minä olen taipunut; sinä olet tarttunut minuun ja voittanut. Minä olen ollut nauruna pitkin päivää, kaikki pilkkaavat minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Sillä niin usein kuin minä puhun, täytyy minun parkua, huutaa väkivaltaa ja sortoa; sillä Herran sana on tullut minulle häväistykseksi ja pilkaksi pitkin päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Mutta kun minä sanoin: \"En tahdo ajatella häntä enkä enää puhua hänen nimessään\", niin sydämessäni oli kuin polttava tuli, suljettuna minun luihini. Ja väsyksiin asti minä koetin sitä kestää, mutta en voinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Sillä monen minä kuulen parjaavan. Kauhistus yltympäri! \"Ilmiantakaa! Ilmiantakaamme hänet!\" Kaikki minun ystäväni vaanivat, milloin minä kompastuisin: \"Ehkäpä hän antaa viekoitella itsensä, niin että voitamme hänet ja saamme hänelle kostaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Mutta Herra on minun kanssani niinkuin väkevä sankari; sentähden minun vainoojani kompastuvat eivätkä mitään mahda. He saavat suuren häpeän, sillä he ovat olleet ymmärtämättömät, iankaikkisen pilkan, joka ei ole unhottuva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Herra Sebaot, sinä joka tutkit vanhurskaan, näet munaskuut ja sydämen, salli minun nähdä, että kostat heille, sillä sinun huomaasi minä olen jättänyt asiani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Veisatkaa Herralle, ylistäkää Herraa, sillä hän pelastaa köyhän pahantekijäin käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Kirottu olkoon se päivä, jona minä synnyin; älköön se päivä, jona äitini minut synnytti, olko siunattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Kirottu olkoon se mies, joka toi minun isälleni ilosanoman, sanoen: \"Sinulle on syntynyt poikalapsi\", ja saattoi hänelle suuren ilon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Käyköön sen miehen niinkuin niiden kaupunkien, jotka Herra kukisti armahtamatta. Hän kuulkoon huudon aamulla, sotahuudon keskipäivän aikana,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'koska ei surmannut minua äidinkohtuun, niin että äitini olisi ollut minun hautani ja hänen kohtunsa jäänyt iäti kantavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Miksi olen äitini kohdusta tullut näkemään tuskaa ja vaivaa, niin että minun päiväni päättyvät häpeässä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Sana, joka tuli Jeremialle Herralta, kun kuningas Sidkia lähetti hänen tykönsä Pashurin, Malkian pojan, ja pappi Sefanjan, Maasejan pojan, sanomaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, '\"Kysy neuvoa Herralta meidän puolestamme, sillä Nebukadressar, Baabelin kuningas, sotii meitä vastaan. Ehkäpä Herra tekee meille ihmeen, kaikkien ihmeittensä vertaisen, niin että tämä lähtee pois meidän kimpustamme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Jeremia vastasi heille: \"Sanokaa Sidkialle näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Näin sanoo Herra, Israelin Jumala: Katso, minä käännän takaisin sota-aseet, jotka ovat teidän käsissänne ja joilla te muurin ulkopuolella taistelette piirittäjiänne, Baabelin kuningasta ja kaldealaisia, vastaan, ja kokoan ne tämän kaupungin keskelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Ja minä itse sodin teitä vastaan ojennetulla kädellä ja väkevällä käsivarrella, vihassa ja kiivastuksessa ja suuressa suuttumuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Ja minä tuhoan tämän kaupungin asukkaat, ihmiset ja eläimet; he kuolevat suureen ruttoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Ja sen jälkeen, sanoo Herra, minä annan Sidkian, Juudan kuninkaan, ja hänen palvelijansa ja kansan ja ne, jotka ovat tähän kaupunkiin jääneet jäljelle rutolta, miekalta ja nälältä, Nebukadressarin, Baabelin kuninkaan, käsiin ja heidän vihollistensa käsiin, niiden, jotka etsivät heidän henkeänsä, ja hän surmaa heidät miekan terällä; ei hän säästä heitä, ei sääli eikä armahda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Ja sano tälle kansalle: Näin sanoo Herra: Katso, minä panen teidän eteenne elämän tien ja kuoleman tien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Joka jää tähän kaupunkiin, se kuolee miekkaan, nälkään ja ruttoon; mutta joka lähtee ulos ja menee kaldealaisten puolelle, jotka teitä piirittävät, se saa elää ja pitää henkensä saaliinansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Sillä minä olen kääntänyt kasvoni tätä kaupunkia vastaan, sen onnettomuudeksi eikä onneksi, sanoo Herra; Baabelin kuninkaan käsiin se annetaan, ja hän polttaa sen tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Ja sano Juudan kuninkaan huoneelle: Kuulkaa Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Daavidin huone! Näin sanoo Herra: Tuomitkaa joka aamu oikeat tuomiot ja pelastakaa ryöstetty sortajan kädestä, ettei minun vihani syttyisi kuin tuli ja palaisi, eikä olisi sammuttajaa, teidän tekojenne pahuuden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Katso, minä käyn sinun kimppuusi, sinä laakson asujatar, sinä tasangon kalliolinna, sanoo Herra, teidän kimppuunne, jotka sanotte: \'Kuka voi astua alas meitä vastaan, kuka tulla meidän asuntoihimme?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Minä rankaisen teitä teidän tekojenne hedelmän mukaan, sanoo Herra, ja sytytän tuleen sen kaupungin metsän, ja tuli kuluttaa kaiken, mitä sen ympärillä on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Näin sanoo Herra: \"Mene alas Juudan kuninkaan linnaan ja puhu siellä tämä sana;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'sano: Kuule Herran sana, sinä Juudan kuningas, joka istut Daavidin valtaistuimella, sinä ja sinun palvelijasi ja kansasi, jotka käytte sisälle näistä porteista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Näin sanoo Herra: Tehkää oikeus ja vanhurskaus ja pelastakaa ryöstetty sortajan kädestä; muukalaiselle, orvolle ja leskelle älkää tehkö vääryyttä ja väkivaltaa älkääkä vuodattako viatonta verta tässä paikassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Sillä jos te teette tämän sanan mukaan, niin tulee tämän linnan porteista sisälle, ajaen vaunuilla ja hevosilla, kuninkaita, jotka istuvat Daavidin valtaistuimella, tulee kuningas ynnä hänen palvelijansa ja kansansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Mutta jos te ette kuule näitä sanoja, niin minä vannon itse kauttani, sanoo Herra, että tämä linna on tuleva raunioiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Sillä näin sanoo Herra Juudan kuninkaan linnasta: Sinä olet minulle Gilead, olet Libanonin huippu; mutta totisesti, minä teen sinut erämaaksi, asumattomiksi kaupungeiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Minä vihin hävittäjät sinua vastaan, kunkin aseinensa, ja he hakkaavat maahan sinun valiosetrisi ja heittävät ne tuleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Monet kansat kulkevat tämän kaupungin ohitse ja kysyvät toinen toiseltansa: \'Miksi on Herra tehnyt näin tälle suurelle kaupungille?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Ja siihen vastataan: \'Siksi, että he hylkäsivät Herran, Jumalansa, liiton ja kumarsivat muita jumalia ja palvelivat niitä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Älkää kuollutta itkekö älkääkä häntä surkutelko, vaan itkekää tuota poiskulkevaa, sillä hän ei enää palaja eikä saa nähdä synnyinmaatansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Sillä näin sanoo Herra Sallumista, Joosian pojasta, Juudan kuninkaasta, joka tuli kuninkaaksi isänsä Joosian sijaan ja joka on vaeltanut pois tästä paikasta: Hän ei enää tänne palaja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'vaan mihin hänet on vangiksi viety, sinne hän kuolee eikä näe enää tätä maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Voi häntä, joka ei vanhurskaudella taloansa rakenna eikä yläsalejansa oikeudella; joka ilmaiseksi teettää työtä lähimmäisellään eikä anna hänelle hänen palkkaansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'joka sanoo: \'Minä rakennan itselleni tilavan talon ja avarat yläsalit\', joka hakkauttaa siihen ikkunat, laudoittaa sen setripuulla ja maalauttaa punavärillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Siksikö sinä olet kuningas, että sinulla on into setripuuhun? Eikö sinun isäsikin syönyt ja juonut ja kuitenkin ollut oikeuden ja vanhurskauden tekijä? Ja silloin hänen kävi hyvin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Hän hankki oikeuden kurjalle ja köyhälle; silloin kaikki kävi hyvin. Eikö tämä juuri ole minun tuntemistani, sanoo Herra?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Mutta sinun silmäsi ja sydämesi eivät pyydä muuta kuin omaa voittoasi, muuta kuin vuodattaa viatonta verta ja harjoittaa väkivaltaa ja sortoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Sentähden, näin sanoo Herra Joojakimista, Joosian pojasta, Juudan kuninkaasta: Ei hänelle pidetä valittajaisia eikä huudeta: \'Voi veljeni! Voi sisareni!\' Ei hänelle pidetä valittajaisia eikä huudeta: \'Voi herraamme! Voi hänen loistoansa!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Hänet haudataan niinkuin aasi haudataan: raahataan pois ja viskataan Jerusalemin porttien tuolle puolen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Nouse Libanonille ja huuda, korota äänesi Baasanissa. Huuda Abarimin vuorilta, sillä kaikki sinun rakastajasi ovat murskaksi muserretut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Minä puhuin sinulle onnesi päivinä. Sinä vastasit: \'En tahdo kuulla\'. Tämä on ollut sinun tapasi nuoruudestasi asti: et ole kuullut minun ääntäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Myrskytuuli on kaitseva kaikkia sinun kaitsijoitasi, ja sinun rakastajasi menevät vankeuteen; silloin sinä saat häpeän ja pilkan kaiken pahuutesi tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Sinä, joka asut Libanonissa, pidät pesääsi setripuissa: kuinka olet voihkiva, kun sinulle tuskat tulevat, kouristus niinkuin synnyttäväiselle!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Niin totta kuin minä elän, sanoo Herra: olkoon Konja, Joojakimin poika, Juudan kuningas, vaikka sinettisormus minun oikeassa kädessäni-siitäkin minä sinut repäisen irti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Ja minä annan sinut niiden käsiin, jotka etsivät sinun henkeäsi, niiden käsiin, joita sinä kauhistut: Nebukadressarin, Baabelin kuninkaan, ja kaldealaisten käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Ja minä heitän sinut ja sinun äitisi, joka on sinut synnyttänyt, vieraalle maalle, missä te ette ole syntyneet, ja sinne te kuolette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Mutta maahan, jonne heidän sielunsa halajaa palata, sinne he eivät palaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Onko sitten tämä mies, Konja, arvoton, rikottu astia, kelvoton kapine? Minkätähden on hänet ja hänen jälkeläisensä heitetty pois, viskattu pois-maahan, jota eivät tunne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'Maa, maa, maa! Kuule Herran sana!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Näin sanoo Herra: Merkitkää tämä mies lapsettomaksi, mieheksi, jolla ei elinpäivinänsä onnea ole. Sillä ei kenellekään hänen jälkeläisistänsä sitä onnea tule, että istuisi Daavidin valtaistuimella ja hallitsi vielä Juudaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, '\"Voi paimenia, jotka hukuttavat ja hajottavat minun laitumeni lampaat, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Sentähden näin sanoo Herra, Israelin Jumala, paimenista, jotka kaitsevat minun kansaani: Te olette hajottaneet minun lampaani ja karkoittaneet ne pois ettekä ole pitäneet niistä huolta. Katso, minä pidän huolen teidän pahain tekojenne rankaisemisesta, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Ja minä kokoan lampaitteni tähteet kaikista maista, joihin olen ne karkoittanut, ja tuon ne takaisin laitumelleen, ja ne ovat hedelmälliset ja lisääntyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Ja minä herätän heille paimenia, ja ne kaitsevat heitä; eivät he enää pelkää eivätkä säiky, eikä heistä yhtäkään puutu, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Katso, päivät tulevat, sanoo Herra, jolloin minä herätän Daavidille vanhurskaan vesan; hän on hallitseva kuninkaana ja menestyvä, ja hän on tekevä oikeuden ja vanhurskauden maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Hänen päivinänsä pelastetaan Juuda ja Israel asuu turvassa. Ja tämä on hänen nimensä, jolla häntä kutsutaan: \'Herra on meidän vanhurskautemme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Sentähden, katso, päivät tulevat, sanoo Herra, jolloin ei enää sanota: \'Niin totta kuin Herra elää, joka johdatti israelilaiset Egyptin maasta\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'vaan: \'Niin totta kuin Herra elää, joka johdatti ja toi Israelin heimon jälkeläiset pohjoisesta maasta ja kaikista muista maista, joihin minä olin heidät karkoittanut\'. Ja niin he saavat asua omassa maassansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Profeettoja vastaan. Minun sydämeni on murtunut rinnassani, kaikki luuni raukeavat. Minä olen kuin juopunut mies, kuin sankari, jonka viini on voittanut, Herran edessä ja hänen pyhien sanojensa edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, '\"Sillä maa on täynnä avionrikkojia, maa murehtii kirouksen tähden, erämaan laitumet kuivuvat; he rientävät pahuuteen, ja heidän väkevyytensä on väärä meno.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Sillä he ovat jumalattomia, niin profeetta kuin pappikin; omasta huoneestanikin minä olen tavannut heidän pahuutensa, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Sentähden heidän tiensä on oleva heille kuin liukas polku pimeässä, he suistuvat sillä ja kaatuvat; sillä minä tuotan heille onnettomuuden heidän rangaistusvuotenansa, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Samarian profeetoissa minä näin pahennuksen: he ennustivat Baalin nimessä ja eksyttivät minun kansani Israelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Mutta Jerusalemin profeetoissa minä olen nähnyt kauhistuksia: aviorikosta ja valheessa vaeltamista; he vahvistavat pahantekijäin käsiä, niin ettei kukaan käänny pois pahuudestansa. He ovat minun edessäni kaikki kuin Sodoma, ja kaupungin asukkaat kuin Gomorra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Sentähden, näin sanoo Herra Sebaot profeetoista: Katso, minä syötän heille koiruohoa ja juotan heille myrkkyvettä; sillä Jerusalemin profeetoista on jumalattomuus levinnyt koko maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Näin sanoo Herra Sebaot: Älkää kuulko profeettain sanoja, noiden, jotka teille ennustavat täyttäen teidät tyhjillä toiveilla: oman sydämensä näkyjä he puhuvat, mutta eivät sitä, mikä tulee Herran suusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'He hokevat minun halveksijoilleni: \'Herra on sen sanonut: Teillä on oleva rauha!\' Ja kaikille, jotka vaeltavat sydämensä paatumuksessa, he sanovat: \'Ei teitä kohtaa onnettomuus\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Mutta kuka on seisonut Herran neuvottelussa ja nähnyt ja kuullut hänen sanansa? Kuka on tarkannut ja kuullut hänen sanansa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Katso, Herran myrsky, kiivastus, puhkeaa, pyörremyrsky vyöryy kohti jumalattomien päätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Eikä Herran viha asetu, ennenkuin hän on toteuttanut ja täyttänyt sydämensä aivoitukset. Aikojen lopulla te tulette sen hyvin ymmärtämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, '\"Minä en ole lähettänyt noita profeettoja, mutta silti he juoksevat. Minä en ole puhunut heille, mutta kuitenkin he ennustavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Jos he olisivat seisoneet minun neuvottelussani, niin he julistaisivat minun sanani kansalleni ja kääntäisivät heidät pois heidän pahalta tieltään ja pahoista teoistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Olenko minä Jumala vain lyhyeltä matkalta, sanoo Herra; enkö ole Jumala myöskin kaukaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Saattaako joku niin piiloon piiloutua, etten minä häntä näe? sanoo Herra. Enkö minä täytä taivasta ja maata? sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Minä olen kuullut, mitä sanovat nuo profeetat, jotka ennustavat minun nimessäni valhetta sanoen: \'Minä olen nähnyt unta, olen nähnyt unta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Kuinka kauan? Mitä on mielessä noilla profeetoilla, jotka ennustavat valhetta, ennustavat oman sydämensä petosta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Aikovatko he unillaan, joita he kertovat toinen toisellensa, saattaa minun kansani unhottamaan minun nimeni, niinkuin heidän isänsä ovat unhottaneet minun nimeni Baalin tähden?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Se profeetta, jolla on uni, kertokoon unensa; mutta se, jolla on minun sanani, puhukoon minun sanani uskollisesti. Mitä tekevät oljet jyvien seassa? sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Eikö minun sanani ole niinkuin tuli, sanoo Herra, ja niinkuin vasara, joka kallion murtaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Katso, sentähden minä käyn niiden profeettain kimppuun, sanoo Herra, jotka varastavat minun sanani toinen toiseltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Katso, minä käyn niiden profeettain kimppuun, sanoo Herra, jotka ottavat sanansa omalta kieleltään, mutta sanovat: \'Se on Herran sana\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Katso, minä käyn niiden kimppuun, jotka ennustavat valheunia, sanoo Herra, ja kertovat niitä ja eksyttävät minun kansaani valheillansa ja kerskumisellansa, vaikka minä en ole heitä lähettänyt enkä käskenyt ja vaikka heistä ei ole mitään hyötyä tälle kansalle, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Ja kun tämä kansa tai profeetta tai pappi sinulta kysyy sanoen: \'Mikä on Herran ennustuksen kuorma?\' niin sano heille: \'Mikä kuorma? -Teidät minä heitän pois\', sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Ja sitä profeettaa, pappia ja kansaa, joka sanoo: \'Herran kuorma\' -sitä miestä ja hänen huonettansa minä rankaisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Näin sanokaa keskenänne, toinen toisellenne: \'Mitä on Herra vastannut?\' ja \'Mitä on Herra puhunut?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Mutta \'Herran kuormaa\' älkää enää mainitko; sillä kuormaksi on tuleva jokaiselle hänen oma sanansa. Te vääntelette elävän Jumalan, Herran Sebaotin, teidän Jumalanne, sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Näin sano profeetalle: \'Mitä on Herra sinulle vastannut? Mitä on Herra puhunut?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Mutta jos te sanotte: \'Herran kuorma\', silloin Herra sanoo näin: Koska te sanotte tämän sanan: \'Herran kuorma\', vaikka minä olen lähettänyt teidän tykönne sanomaan: Älkää sanoko: \'Herran kuorma\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'sentähden katso: minä kokonaan unhotan teidät ja heitän pois kasvojeni edestä teidät ja tämän kaupungin, jonka minä annoin teille ja teidän isillenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'Ja minä panen teidän päällenne iankaikkisen häpeän ja iankaikkisen pilkan, joka ei ole unhottuva.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Ja Herra näytti minulle näyn, ja katso, kaksi viikunakoria oli asetettu Herran temppelin edustalle, sen jälkeen kuin Nebukadressar, Baabelin kuningas, oli siirtänyt pois Jekonjan, Joojakimin pojan, Juudan kuninkaan, ja Juudan päämiehet sekä sepät ja lukkosepät Jerusalemista ja vienyt heidät Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Toisessa korissa oli ylen hyviä viikunoita, uudisviikunain kaltaisia, ja toisessa korissa oli ylen huonoja viikunoita, niin huonoja, ettei niitä voinut syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Ja Herra sanoi minulle: \"Mitä sinä näet, Jeremia?\" Minä vastasin: \"Viikunoita. Hyvät viikunat ovat ylen hyviä, mutta huonot ovat ylen huonoja, niin huonoja, ettei niitä voi syödä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, '\"Näin sanoo Herra, Israelin Jumala: Niinkuin näitä hyviä viikunoita, niin minä katselen hyvällä suosiolla Juudan pakkosiirtolaisia, jotka minä lähetin tästä paikasta kaldealaisten maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Ja minä käännän katseeni heihin, heidän hyväksensä, ja tuon heidät takaisin tähän maahan. Minä rakennan heidät enkä hajota, minä istutan heidät enkä revi pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Ja minä annan heille sydämen, heidän tunteakseen minut, että minä olen Herra; ja he saavat olla minun kansani, ja minä olen heidän Jumalansa; sillä he kääntyvät minun tyköni kaikesta sydämestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Mutta niinkuin tehdään huonoille viikunoille, joita ei voi syödä, kun ovat niin huonoja, niin minä, sanoo Herra, teen Sidkialle, Juudan kuninkaalle, ja hänen ruhtinailleen ja Jerusalemin jäännökselle, niille, jotka ovat jääneet jäljelle tähän maahan, ja niille, jotka asuvat Egyptin maassa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Minä teen heidät kauhistukseksi ja onnettomuudeksi kaikille valtakunnille maan päällä, häväistykseksi ja sananparreksi, pistopuheeksi ja kiroussanaksi kaikissa paikoissa, mihin minä heidät karkoitan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Ja minä lähetän heidän sekaansa miekan, nälän ja ruton, kunnes he ovat hävinneet siitä maasta, jonka minä olen antanut heille ja heidän isillensä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Sana, joka tuli Jeremialle, sana koko Juudan kansaa vastaan, Joojakimin, Joosian pojan, Juudan kuninkaan, neljäntenä vuotena, se on Nebukadressarin, Baabelin kuninkaan, ensimmäisenä vuotena-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'sana, jonka profeetta Jeremia lausui koko Juudan kansaa ja kaikkia Jerusalemin asukkaita vastaan sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Joosian, Aamonin pojan, Juudan kuninkaan, kolmannestatoista vuodesta alkaen tähän päivään saakka-kaksikymmentä kolme vuotta-on Herran sana tullut minulle, ja minä olen teille puhunut varhaisesta alkaen, mutta te ette ole kuulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Ja Herra on lähettänyt teidän tykönne kaikki palvelijansa, profeetat, varhaisesta alkaen, mutta te ette ole kuulleet, ette kallistaneet korvaanne kuullaksenne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'kun he sanoivat: \"Kääntykää itsekukin pahalta tieltänne ja pahoista teoistanne, niin saatte asua maassa, jonka Herra on antanut teille ja teidän isillenne, iankaikkisesta iankaikkiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Älkää seuratko muita jumalia, älkää palvelko ja kumartako niitä älkääkä vihoittako minua kättenne töillä, etten tuottaisi teille onnettomuutta.\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, '\"Mutta te ette kuulleet minua, sanoo Herra, ja niin te vihoititte minut kättenne töillä, omaksi onnettomuudeksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Sentähden näin sanoo Herra Sebaot: Koska te ette ole kuulleet minun sanojani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'niin katso, minä lähetän sanan, minä nostan kaikki pohjanpuolen kansanheimot, sanoo Herra, sanan Nebukadressarille, Baabelin kuninkaalle, palvelijalleni, ja tuon heidät tätä maata ja sen asukkaita vastaan ja kaikkia näitä ympärillä olevia kansoja vastaan. Ja nämä minä vihin tuhon omiksi ja teen heidät kauhistukseksi, ivan vihellykseksi ja ikuisiksi raunioiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Minä hävitän heidän keskuudestaan riemun ja ilon huudon, huudon yljälle ja huudon morsiamelle, käsikivien äänen ja lampun valon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Niin koko tämä maa tulee raunioiksi, autioksi, ja nämä kansat palvelevat Baabelin kuningasta seitsemänkymmentä vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Mutta kun seitsemänkymmentä vuotta on täyttynyt, niin minä kostan Baabelin kuninkaalle ja sille kansalle, sanoo Herra, heidän pahat tekonsa, kostan kaldealaisten maalle ja teen sen ikuiseksi erämaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Ja minä tuotan sen maan ylitse kaikki sanani, jotka minä olen puhunut sitä vastaan, kaiken, mitä tähän kirjaan on kirjoitettu, mitä Jeremia on ennustanut kaikkia niitä kansoja vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Sillä hekin joutuvat palvelemaan monia kansoja ja suuria kuninkaita, ja minä maksan heille heidän tekojensa ja kättensä töiden mukaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Sillä näin sanoi Herra, Israelin Jumala, minulle: \"Ota tämä vihan viinin malja minun kädestäni ja juota sillä kaikki kansat, joiden tykö minä sinut lähetän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'He juovat ja horjuvat ja tulevat mielettömiksi miekan edessä, jonka minä lähetän heidän keskellensä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Ja minä otin maljan Herran kädestä ja juotin kaikkia kansoja, joiden tykö Herra minut lähetti:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jerusalemia ja Juudan kaupunkeja, sen kuninkaita ja ruhtinaita, tehdäkseni heidät raunioiksi, kauhistukseksi, ivan vihellykseksi ja kiroukseksi, niinkuin tänä päivänä tapahtuu;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'faraota, Egyptin kuningasta, ja hänen palvelijoitansa ja ruhtinaitansa ja koko hänen kansaansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'kaikkea sekakansaa ja kaikkia Uusin maan kuninkaita ja kaikkia filistealaisten maan kuninkaita ja Askelonia ja Gassaa ja Ekronia ja Asdodin tähteitä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edomia, Mooabia ja ammonilaisia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'kaikkia Tyyron kuninkaita ja kaikkia Siidonin kuninkaita ja rantamaan kuninkaita, jotka ovat meren tuolla puolen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedania, Teemaa ja Buusia ja kaikkia päälaen ympäriltä kerittyjä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'kaikkia Arabian kuninkaita ja kaikkia sekakansan kuninkaita, jotka asuvat erämaassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'kaikkia Simrin kuninkaita ja kaikkia Eelamin kuninkaita ja kaikkia Meedian kuninkaita;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'kaikkia pohjanpuolen kuninkaita, läheisiä ja kaukaisia, toista toisensa jälkeen, ja kaikkia maan valtakuntia, mitä maan päällä on. Ja heidän jälkeensä on Seesakin kuningas juova.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, '\"Sano heille: Näin sanoo Herra Sebaot, Israelin Jumala: Juokaa ja juopukaa, oksentakaa ja kaatukaa, älkääkä enää nousko, -miekan edessä, jonka minä lähetän teidän keskellenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Mutta jos he eivät tahdo ottaa maljaa sinun kädestäsi ja juoda, niin sano heille: Näin sanoo Herra Sebaot: Teidän täytyy juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Sillä katso, siitä kaupungista alkaen, joka on otettu minun nimiini, minä alotan onnettomuuden tuottamisen; ja tekö jäisitte rankaisematta! Te ette jää rankaisematta, sillä minä kutsun miekan kaikkia maan asukkaita vastaan, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Mutta sinä, ennusta heille kaikki nämä sanat ja sano heille: Herra ärjyy korkeudesta, antaa äänensä kaikua pyhästä asunnostansa. Hän ärjyy väkevästi yli laitumensa. Hän nostaa kuin viinikuurnan polkijat huudon kaikkia maan asukkaita vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Pauhina käy maan ääriin asti, sillä Herralla on riita-asia kansoja vastaan, hän käy oikeutta kaiken lihan kanssa: jumalattomat hän antaa miekalle alttiiksi, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Näin sanoo Herra Sebaot: Katso, onnettomuus kulkee kansasta kansaan, ja suuri myrsky nousee maan perimmäisistä ääristä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Ja Herran surmaamia on oleva sinä päivänä maan äärestä maan ääreen. Ei heille pidetä valittajaisia, ei heitä koota eikä haudata; he tulevat maan lannaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Parkukaa, te paimenet, ja huutakaa, vieriskelkää tuhassa, te lauman valtiaat; sillä aika on tullut teidän joutua teurastettaviksi. Te hajoatte pirstoiksi, te kaadutte niinkuin kallisarvoinen astia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Mennyt on paimenilta pakopaikka ja pelastus lauman valtiailta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Kuule paimenten huutoa, lauman valtiaitten valitusta! Sillä Herra hävittää heidän laumansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'heidän rauhaisat laitumensa ovat tuhoutuneet Herran vihan hehkusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Hän on lähtenyt niinkuin nuori leijona pensaikostaan: heidän maansa on tullut autioksi hävittäjän vihan hehkusta, Herran vihan hehkusta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Joojakimin, Joosian pojan, Juudan kuninkaan, hallituksen alussa tuli Herralta tämä sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, '\"Näin sanoo Herra: Asetu Herran temppelin esipihaan ja puhu kaikkia Juudan kaupunkeja vastaan, jotka tulevat kumartaen rukoilemaan Herran temppeliin, kaikki ne sanat, jotka minä olen käskenyt sinun sanoa heille; älä jätä pois sanaakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Ehkäpä he kuulevat ja kääntyvät itsekukin pois pahalta tieltään, ja niin minä kadun sitä onnettomuutta, jonka minä olen aikonut heille tuottaa heidän pahojen tekojensa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Ja sano heille: Näin sanoo Herra: Jollette kuule minua ja vaella minun lakini mukaan, jonka minä olen teille antanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'ettekä kuule palvelijaini, profeettain, sanoja, niiden, jotka minä olen lähettänyt teidän tykönne, varhaisesta alkaen, vaikka ette ole kuulleet heitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'niin minä teen tälle temppelille niinkuin Siilolle, ja minä teen tämän kaupungin kiroussanaksi kaikille maan kansoille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Ja papit ja profeetat ja koko kansa kuulivat Jeremian puhuvan nämä sanat Herran temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Ja kun Jeremia oli puhunut loppuun kaiken, minkä Herra oli käskenyt hänen puhua kaikelle kansalle, niin papit ja profeetat ja koko kansa ottivat hänet kiinni sanoen: \"Sinun on kuolemalla kuoltava!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Miksi olet ennustanut Herran nimessä sanoen: Tälle temppelille on käyvä niinkuin Siilolle, ja tämä kaupunki on tuleva raunioiksi, asujattomaksi?\" Ja kaikki kansa kokoontui Jeremiaa vastaan Herran temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Kun Juudan päämiehet tämän kuulivat, menivät he kuninkaan palatsista Herran temppeliin ja istuivat Herran uuden portin ovelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Silloin papit ja profeetat sanoivat päämiehille ja kaikelle kansalle näin: \"Kuoleman tuomio tälle miehelle! Sillä hän on ennustanut tätä kaupunkia vastaan, niinkuin olette omin korvin kuulleet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Mutta Jeremia sanoi kaikille päämiehille ja kaikelle kansalle näin: \"Herra on lähettänyt minut ennustamaan tätä temppeliä ja tätä kaupunkia vastaan kaikki ne sanat, jotka olette kuulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Parantakaa siis nyt vaelluksenne ja tekonne ja kuulkaa Herran, teidän Jumalanne, ääntä, niin Herra katuu sitä onnettomuutta, jolla hän on teitä uhannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Mutta katso, minä olen teidän käsissänne; tehkää minulle, mitä katsotte hyväksi ja oikeaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Mutta se tietäkää, että te, jos minut surmaatte, saatatte viattoman veren päällenne ja tämän kaupungin ja sen asukasten päälle, sillä totisesti on Herra lähettänyt minut teidän tykönne puhumaan kaikki nämä sanat teidän korvienne kuullen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Silloin päämiehet ja kaikki kansa sanoivat papeille ja profeetoille: \"Ei kuoleman tuomiota tälle miehelle! Sillä hän on puhunut meille Herran, meidän Jumalamme, nimessä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Ja muutamat maan vanhimmista nousivat ja sanoivat kaikelle kansan joukolle näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, '\"Miika, mooresetilainen, ennusti Hiskian, Juudan kuninkaan, päivinä ja sanoi kaikelle Juudan kansalle näin: Näin sanoo Herra Sebaot: \'Siion kynnetään pelloksi, ja Jerusalem tulee kiviraunioksi ja temppelivuori metsäkukkulaksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Surmasivatko hänet silloin Hiskia, Juudan kuningas, ja koko Juuda? Eikö hän peljännyt Herraa ja lepyttänyt häntä, niin että Herra katui sitä onnettomuutta, jolla hän oli heitä uhannut? Mutta mekö tuottaisimme suuren onnettomuuden itsellemme?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Mutta oli toinenkin mies, joka ennusti Herran nimessä: Uuria, Semajan poika, Kirjat-Jearimista; hän ennusti tätä kaupunkia ja tätä maata vastaan aivan niinkuin Jeremia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Kun kuningas Joojakim ja kaikki hänen urhonsa ja kaikki päämiehet kuulivat hänen sanansa, niin kuningas etsi häntä tappaaksensa. Sen kuultuansa Uuria peljästyi, pakeni ja meni Egyptiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Mutta kuningas Joojakim lähetti miehiä Egyptiin: Elnatanin, Akborin pojan, ja muita hänen kanssansa Egyptiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Ja he toivat Uurian Egyptistä ja veivät hänet kuningas Joojakimin eteen. Tämä surmautti hänet miekalla ja heitätti hänen ruumiinsa rahvaan hautaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Mutta Ahikamin, Saafanin pojan, käsi oli Jeremian suojana, niin ettei häntä jätetty kansan käsiin surmattavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Joojakimin, Joosian pojan, Juudan kuninkaan, hallituksen alussa tuli Herralta tämä sana Jeremialle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Näin sanoi Herra minulle: \"Tee itsellesi ies siteinensä ja pane se kaulaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Lähetä se Edomin kuninkaalle, Mooabin kuninkaalle, ammonilaisten kuninkaalle, Tyyron kuninkaalle ja Siidonin kuninkaalle niiden lähettiläiden mukana, jotka ovat tulleet Jerusalemiin Sidkian, Juudan kuninkaan, tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Ja käske heidän sanoa herroillensa: Näin sanoo Herra Sebaot, Israelin Jumala: Näin sanokaa herroillenne:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Minä olen tehnyt maan sekä ihmiset ja eläimet, jotka maan päällä ovat, suurella voimallani ja ojennetulla käsivarrellani, ja minä annan sen, kenelle hyväksi näen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Ja nyt minä annan kaikki nämä maat Nebukadnessarin, Baabelin kuninkaan, palvelijani, käsiin, ja myöskin metsän eläimet minä annan hänelle, palvelemaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Ja kaikki kansat palvelevat häntä ja hänen poikaansa ja hänen poikansa poikaa, kunnes tulee hänenkin maansa aika ja monet kansat ja suuret kuninkaat tekevät hänet palvelijakseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Ja sitä kansaa ja sitä valtakuntaa, joka ei tahdo palvella häntä, Nebukadnessaria, Baabelin kuningasta, ja joka ei anna kaulaansa Baabelin kuninkaan ikeeseen, sitä kansaa minä rankaisen miekalla, nälällä ja rutolla, sanoo Herra, kunnes minä teen heistä lopun hänen kädellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Ja te, älkää kuulko profeettojanne, tietäjiänne, unianne, ennustelijoitanne ja velhojanne, jotka sanovat teille näin: \'Ette te joudu palvelemaan Baabelin kuningasta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Sillä valhetta he ennustavat teille ja toimittavat teidät kauas pois maastanne: minä karkoitan teidät, ja te hukutte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Mutta sen kansan, joka taivuttaa kaulansa Baabelin kuninkaan ikeen alle ja palvelee häntä, sen minä annan jäädä omaan maahansa, sanoo Herra; se saa sitä viljellä ja siinä asua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Sidkialle, Juudan kuninkaalle, minä puhuin aivan samalla tavalla, sanoen: Taivuttakaa kaulanne Baabelin kuninkaan ikeen alle ja palvelkaa häntä ja hänen kansaansa, niin te saatte elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Miksi pitäisi teidän kuolla, sinun ja sinun kansasi, miekkaan, nälkään ja ruttoon, niinkuin Herra on uhannut sitä kansaa, joka ei tahdo palvella Baabelin kuningasta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Ja älkää kuulko niiden profeettain sanoja, jotka sanovat teille näin: \"Ette te joudu palvelemaan Baabelin kuningasta\"; sillä valhetta he ennustavat teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Sillä minä en ole lähettänyt heitä, sanoo Herra, vaan he ennustavat minun nimessäni valhetta ja saattavat minut karkoittamaan teidät, ja te hukutte, te ja nuo profeetat, jotka teille ennustavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Ja papeille ja koko tälle kansalle minä puhuin sanoen: Näin sanoo Herra: Älkää kuulko profeettainne sanoja, niiden, jotka ennustavat teille sanoen: \"Katso, Herran temppelin astiat tuodaan nyt kohta takaisin Baabelista\"; sillä valhetta he ennustavat teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Älkää kuulko heitä. Palvelkaa Baabelin kuningasta, niin te saatte elää. Miksi pitäisi tämän kaupungin tulla raunioiksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Mutta jos he ovat profeettoja ja jos heillä on Herran sana, niin rukoilkoot Herraa Sebaotia, etteivät ne astiat, jotka vielä ovat jäljellä Herran temppelissä ja Juudan kuninkaan linnassa ja Jerusalemissa, joutuisi nekin Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Sillä näin sanoo Herra Sebaot pylväistä, vaskimerestä, altaiden telineistä ja muista kaluista, jotka vielä ovat jäljellä tässä kaupungissa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'ja joita Nebukadnessar, Baabelin kuningas, ei ottanut mukaansa, kun hän vei Jekonjan, Joojakimin pojan, Juudan kuninkaan, sekä kaikki Juudan ja Jerusalemin ylimykset Jerusalemista pakkosiirtolaisuuteen Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala, astioista, jotka vielä ovat jäljellä Herran temppelissä, Juudan kuninkaan linnassa ja Jerusalemissa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, '\"Baabeliin ne viedään, ja sinne ne jäävät siihen päivään asti, jolloin minä katson niiden puoleen, sanoo Herra, ja annan tuoda ja palautan ne tähän paikkaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Sinä vuonna, Sidkian, Juudan kuninkaan, hallituksen alussa, hänen neljäntenä hallitusvuotenaan, viidennessä kuussa, sanoi profeetta Hananja, Assurin poika, joka oli kotoisin Gibeonista, minulle Herran temppelissä pappien ja kaiken kansan silmien edessä näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, '\"Näin sanoo Herra Sebaot, Israelin Jumala: Minä särjen Baabelin kuninkaan ikeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Vielä kaksi vuotta, ja minä palautan tähän paikkaan kaikki Herran temppelin astiat, jotka Nebukadnessar, Baabelin kuningas, otti tästä paikasta ja vei Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Ja Jekonjan, Joojakimin pojan, Juudan kuninkaan, ja kaikki Juudan pakkosiirtolaiset, jotka menivät Baabeliin, minä palautan tähän paikkaan, sanoo Herra; sillä minä särjen Baabelin kuninkaan ikeen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Mutta profeetta Jeremia sanoi profeetta Hananjalle pappien ja kaiken Herran temppelissä seisovan kansan silmien edessä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'profeetta Jeremia sanoi: \"Amen. Niin Herra tehköön. Täyttäköön Herra sinun sanasi, jotka olet ennustanut, ja palauttakoon Herran temppelin astiat ja kaikki pakkosiirtolaiset Baabelista tähän paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Kuule kuitenkin tämä sana, jonka minä puhun sinun kuultesi ja kaiken kansan kuullen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Ne profeetat, jotka ovat olleet ennen minua ja ennen sinua muinaisuudesta asti, ovat ennustaneet sotaa, onnettomuutta ja ruttoa monia maita ja suuria valtakuntia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Mutta se profeetta, joka ennustaa rauhaa, tunnetaan siitä, että hänen sanansa toteutuu, profeetaksi, jonka Herra totisesti on lähettänyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Silloin profeetta Hananja otti ikeen profeetta Jeremian kaulasta ja särki sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Ja Hananja sanoi kaiken kansan silmien edessä: \"Näin sanoo Herra: Näin minä särjen Nebukadnessarin, Baabelin kuninkaan, ikeen kaikkien kansojen kaulasta, ennenkuin kaksi vuotta on kulunut\". Mutta profeetta Jeremia meni pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Ja tämä Herran sana tuli Jeremialle, sen jälkeen kuin profeetta Hananja oli särkenyt ikeen profeetta Jeremian kaulasta:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, '\"Mene ja sano Hananjalle: Näin sanoo Herra: Sinä olet särkenyt puisen ikeen, mutta tehnyt sen sijaan rautaisen ikeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: rautaisen ikeen olen minä pannut kaikkien näiden kansojen kaulaan, että ne palvelisivat Nebukadnessaria, Baabelin kuningasta; ja niiden on palveltava häntä. Metsän eläimetkin minä olen antanut hänelle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Ja profeetta Jeremia sanoi profeetta Hananjalle: \"Kuule, Hananja! Ei Herra ole sinua lähettänyt, vaan sinä olet saattanut tämän kansan turvaamaan valheeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Sentähden, näin sanoo Herra: Katso, minä toimitan sinut pois maan päältä: tänä vuonna sinä kuolet, sillä sinä olet julistanut luopumusta Herrasta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Ja profeetta Hananja kuoli sinä vuonna, seitsemännessä kuussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Nämä ovat sen kirjeen sanat, jonka profeetta Jeremia lähetti Jerusalemista pakkosiirtolaisten vanhimmille, mikä heitä vielä oli jäljellä, papeille ja profeetoille sekä kaikelle kansalle, jotka Nebukadnessar oli siirtänyt Jerusalemista pois Baabeliin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'sen jälkeen kuin kuningas Jekonja ja kuninkaan äiti, hoviherrat, Juudan ja Jerusalemin ruhtinaat sekä sepät ja lukkosepät olivat lähteneet Jerusalemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Hän lähetti kirjeen Elasan, Saafanin pojan, ja Gemarjan, Hilkian pojan, mukana, jotka Sidkia, Juudan kuningas, lähetti Nebukadnessarin, Baabelin kuninkaan, tykö Baabeliin; se kuului näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, '\"Näin sanoo Herra Sebaot, Israelin Jumala, kaikille pakkosiirtolaisille, jotka minä olen siirtänyt Jerusalemista pois Baabeliin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Rakentakaa taloja ja asukaa niissä, istuttakaa puutarhoja ja syökää niiden hedelmiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Ottakaa itsellenne vaimoja ja siittäkää poikia ja tyttäriä; ottakaa pojillenne vaimoja ja naittakaa tyttärenne, että he synnyttäisivät poikia ja tyttäriä. Lisääntykää siellä älkääkä vähentykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Ja harrastakaa sen kaupungin menestystä, johon minä olen teidät siirtänyt, ja rukoilkaa sen puolesta Herraa, sillä sen menestys on teidän menestyksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Älkää antako profeettainne, joita on keskuudessanne, ja tietäjäinne pettää itseänne, älkääkä totelko unianne, joita te uneksutte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Sillä valhetta he ennustavat teille minun nimessäni; minä en ole lähettänyt heitä, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Sillä näin sanoo Herra: Vasta kun ne seitsemänkymmentä Baabelin vuotta ovat täyttyneet, minä katson teidän puoleenne ja panen täytäntöön teitä kohtaan hyvän lupaukseni ja palautan teidät tähän paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Sillä minä tunnen ajatukseni, jotka minulla on teitä kohtaan, sanoo Herra: rauhan eikä turmion ajatukset; minä annan teille tulevaisuuden ja toivon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Silloin te huudatte minua avuksenne, tulette ja rukoilette minua, ja minä kuulen teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Te etsitte minua ja löydätte minut, kun te etsitte minua kaikesta sydämestänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Ja niin minä annan teidän löytää itseni, sanoo Herra, ja minä käännän teidän kohtalonne ja kokoan teidät kaikista kansoista ja kaikista paikoista, joihin olen teidät karkoittanut, sanoo Herra, ja palautan teidät tähän paikkaan, josta minä siirsin teidät pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Jos te sanotte: \'Herra on herättänyt meille profeettoja Baabelissa\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'niin sanoo Herra näin kuninkaasta, joka istuu Daavidin valtaistuimella, ja kaikesta kansasta, joka asuu tässä kaupungissa, teidän veljistänne, joiden ei täytynyt lähteä teidän kanssanne pakkosiirtolaisuuteen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Näin sanoo Herra Sebaot: Katso, minä lähetän heidän sekaansa miekan, nälän ja ruton ja teen heidät inhottaviksi kuin viikunat, jotka ovat niin huonoja, ettei niitä voi syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Ja minä ajan heitä takaa miekalla, nälällä ja rutolla ja teen heidät kauhuksi kaikille valtakunnille maan päällä, kiroukseksi ja kauhistukseksi, ivan vihellykseksi ja häväistykseksi kaikkien kansojen keskuudessa, mihin minä heidät karkoitan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'sentähden etteivät he kuulleet minun sanojani, sanoo Herra, kun minä lähetin heidän tykönsä palvelijoitani, profeettoja, varhaisesta alkaen. Te ette ole kuulleet, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Mutta kuulkaa te Herran sana, kaikki te pakkosiirtolaiset, jotka minä olen lähettänyt Jerusalemista Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Näin sanoo Herra Sebaot, Israelin Jumala, Ahabista, Koolajan pojasta, ja Sidkiasta, Maasejan pojasta, jotka ennustavat teille minun nimessäni valhetta: Katso, minä annan heidät Nebukadressarin, Baabelin kuninkaan, käsiin, ja hän lyö heidät kuoliaaksi teidän silmäinne edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Ja heistä tulee kiroussana kaikille Juudan pakkosiirtolaisille, jotka ovat Baabelissa; sanotaan: \'Herra tehköön sinulle niinkuin Sidkialle ja Ahabille, jotka Baabelin kuningas korvensi tulessa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Sillä he ovat tehneet häpeällisen teon Israelissa, ovat tehneet huorin lähimmäistensä vaimojen kanssa ja puhuneet minun nimessäni valhepuhetta, jota minä en ole käskenyt heidän puhua. Minä olen se, joka sen tiedän ja todistan, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Ja nehelamilaiselle Semajalle puhu, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, '\"Näin sanoo Herra Sebaot, Israelin Jumala: Sentähden että sinä olet lähettänyt omassa nimessäsi tämän kirjeen kaikelle kansalle, joka on Jerusalemissa, ja pappi Sefanjalle, Maasejan pojalle, ja kaikille papeille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Herra on asettanut sinut papiksi pappi Joojadan sijaan, että olisi järjestyksen valvojia Herran temppelissä kaikkien hullujen ja ennustajain varalle, ja niin sinä voit panna sellaiset jalkapuuhun ja kaularautaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Miksi et siis ole nuhdellut anatotilaista Jeremiaa, joka ennustaa teille?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Niinpä hän on saattanut lähettää meille Baabeliin tämän sanan: \'Se kestää vielä kauan. Rakentakaa taloja ja asukaa niissä, istuttakaa puutarhoja ja syökää niiden hedelmiä.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Ja pappi Sefanja luki tämän kirjeen profeetta Jeremian kuullen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Silloin tuli Jeremialle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, '\"Lähetä kaikille pakkosiirtolaisille tämä sana: Näin sanoo Herra nehelamilaisesta Semajasta: Koska Semaja on ennustanut teille, vaikka minä en ole lähettänyt häntä, ja saattanut teidät turvaamaan valheeseen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'sentähden, näin sanoo Herra: Katso, minä kostan nehelamilaiselle Semajalle ja hänen jälkeläisillensä. Hänellä ei ole oleva ketään, joka saa asua tämän kansan keskuudessa, eikä hän ole näkevä sitä hyvää, jonka minä teen kansalleni, sanoo Herra; sillä hän on julistanut luopumusta Herrasta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Sana, joka tuli Herralta Jeremialle ja kuului näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, '\"Näin sanoo Herra, Israelin Jumala: Kirjoita kaikki sanat, jotka minä olen sinulle puhunut, kirjaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Sillä katso, tulee aika, sanoo Herra, jolloin minä käännän kansani Israelin ja Juudan kohtalon, sanoo Herra, ja palautan heidät maahan, jonka olen antanut heidän isillensä, ja he saavat periä sen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Ja nämä ovat ne sanat, jotka Herra on puhunut Israelista ja Juudasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Näin sanoo Herra: \"Pelon huudon me kuulemme: on hirmu, ei rauha!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Kysykää ja katsokaa: synnyttääkö miehenpuoli? Miksi näen kaikkien miesten pitelevän käsin lanteitansa synnyttäväisten tavalla, ja miksi ovat kaikki kasvot käyneet valjuiksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Voi! Suuri on se päivä, ei ole sen kaltaista. Se on Jaakobille ahdistuksen aika, mutta hän on pelastuva siitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Ja sinä päivänä, sanoo Herra Sebaot, minä särjen ikeen sinun kaulastasi ja katkaisen sinun siteesi. Eivät tee enää muukalaiset heitä palvelijoikseen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'vaan he saavat palvella Herraa, Jumalaansa, ja Daavidia, kuningastansa, jonka minä heille herätän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Mutta sinä, minun palvelijani Jaakob, älä pelkää, sanoo Herra, älä säiky, Israel. Sillä katso, minä pelastan sinut kaukaisesta maasta, sinun jälkeläisesi heidän vankeutensa maasta. Ja Jaakob on palajava, elävä rauhassa ja turvassa, kenenkään peljättämättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Sillä minä olen sinun kanssasi, sanoo Herra, ja pelastan sinut. Minä teen lopun kaikista kansoista, joiden sekaan minä olen sinut hajottanut; ainoastaan sinusta minä en loppua tee: minä kuritan sinua kohtuudella, mutta rankaisematta minä en sinua jätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Sillä näin sanoo Herra: Paha on sinun vammasi, kipeä on saamasi isku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Ei kukaan aja sinun asiaasi; sinun haavaasi ei paranneta, se ei kasva umpeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Kaikki sinun rakastajasi ovat sinut unhottaneet, sinua he eivät kysy. Sillä niinkuin vihollista lyödään, olen minä sinua lyönyt, kovalla kurituksella, koska sinun rikoksesi on suuri, sinun syntisi monilukuiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Miksi valitat vammaasi, kipusi kovuutta? Koska sinun rikoksesi on suuri, sinun syntisi monilukuiset, olen minä sinulle tämän tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Niin myös kaikki sinun syöjäsi syödään, ja kaikki sinun ahdistajasi, kaikki tyynni, vaeltavat vankeuteen; sinun ryöstäjäsi joutuvat ryöstetyiksi, ja kaikki saalistajasi minä annan saaliiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Sillä minä kasvatan umpeen sinun haavasi ja parannan sinut saamistasi iskuista, sanoo Herra, sinut, Siion, jolla on nimenä \'hyljätty\', \'se, josta ei kukaan välitä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Näin sanoo Herra: Katso, minä käännän Jaakobin majojen kohtalon, minä armahdan hänen asuntojansa; kaupunki rakennetaan kukkulallensa, ja linna on oleva oikealla paikallansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Ja niistä on kaikuva ylistyslaulu ja iloitsevaisten ääni. Minä enennän heidät, eivätkä he vähene; minä saatan heidät kunniaan, eivätkä he halvoiksi jää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Silloin hänen poikansa ovat niinkuin muinoin, ja hänen seurakuntansa pysyy vahvana minun edessäni; minä rankaisen kaikki hänen sortajansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Ja hänen valtiaansa nousee hänestä itsestänsä, hänen hallitsijansa lähtee hänen keskeltänsä; ja minä sallin hänen käydä tyköni, niin että hän saattaa minua lähestyä. Sillä kuka panee henkensä alttiiksi minua lähestyäkseen? sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Ja niin te olette minun kansani, ja minä olen teidän Jumalanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Katso, Herran myrsky, kiivastus, puhkeaa, pyörremyrsky vyöryy kohti jumalattomien päätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Eikä Herran vihan hehku asetu, ennenkuin hän on toteuttanut ja täyttänyt sydämensä aivoitukset. Aikojen lopulla te tulette sen ymmärtämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, '\"Siihen aikaan, sanoo Herra, minä olen kaikkien Israelin sukukuntien Jumala, ja he ovat minun kansani.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Näin sanoo Herra: \"Kansa, miekalta säästynyt, löysi erämaassa armon; minä menen saattamaan sen, Israelin, rauhaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Kaukaa ilmestyy minulle Herra: \"Iankaikkisella rakkaudella minä olen sinua rakastanut, sentähden minä olen vetänyt sinua puoleeni armosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Minä rakennan sinut jälleen, ja sinä tulet rakennetuksi, neitsyt Israel. Sinä kaunistat itsesi jälleen käsirummuillasi ja lähdet iloitsevaisten karkeloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Sinä istutat jälleen viinitarhoja Samarian vuorille; ne, jotka istuttavat, saavat korjata hedelmätkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Sillä päivä on tuleva, jolloin vartijat huutavat Efraimin vuorella: \'Nouskaa, lähtekäämme Siioniin Herran, meidän Jumalamme, tykö\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Sillä näin sanoo Herra: Riemuitkaa iloiten Jaakobista, kohottakaa riemuhuuto hänelle, joka on kansojen pää; kuuluttakaa, kiittäkää ja sanokaa: \'Auta, Herra, kansaasi, Israelin jäännöstä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Katso, minä tuon heidät pohjoisesta maasta, kokoan heidät maan perimmäisiltä ääriltä. Heissä on sokeita ja rampoja ynnä raskaita ja synnyttäväisiä: suurena joukkona he palajavat tänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Itkien he tulevat, ja minä johdatan heitä, kun he kulkevat rukoillen. Minä vien heidät vesipuroille, tasaista tietä, jolla he eivät kompastu. Sillä minä olen Israelin isä, ja Efraim on minun esikoiseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Kuulkaa Herran sana, te kansat, ilmoittakaa kaukaisissa merensaarissa ja sanokaa: Hän, joka Israelin hajoitti, on sen kokoava ja varjeleva sitä niinkuin paimen laumaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Sillä Herra on lunastanut Jaakobin ja vapahtanut hänet häntä väkevämmän kädestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Ja he tulevat ja riemuitsevat Siionin kukkulalla, tulevat virtanaan Herran hyvyyden tykö, jyväin, viinin ja öljyn ääreen, karitsain ja karjan ääreen. Ja heidän sielunsa on oleva niinkuin runsaasti kasteltu puutarha, eivätkä he enää näänny.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Silloin neitsyt iloitsee karkelossa ja nuorukaiset ja vanhukset yhdessä. Minä muutan heidän surunsa riemuksi, annan heille lohdutuksen ja ilon heidän murheensa jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Ja minä virvoitan pappien sielut lihavuuden ääressä, ja minun kansani ravitaan minun hyvyydelläni, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Näin sanoo Herra: Kuule, Raamasta kuuluu valitus, katkera itku: Raakel itkee lapsiansa, hän ei lohdutuksesta huoli surussaan lastensa tähden, sillä niitä ei enää ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Näin sanoo Herra: Pidätä äänesi itkusta, silmäsi kyyneleistä, sillä sinun työstäsi on tuleva palkka, sanoo Herra, ja he palajavat vihollisen maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Sinulla on tulevaisuuden toivo, sanoo Herra: sinun lapsesi palajavat omalle maalleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Minä olen kyllä kuullut Efraimin valittavan: \'Sinä olet kurittanut minua, olen saanut kuritusta niinkuin vikuroiva vasikka. Palauta minut, niin minä palajan; sillä sinä olet Herra, minun Jumalani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Sillä käännyttyäni minä kadun, ja päästyäni ymmärrykseen minä lyön lanteeseeni. Minä häpeän, tunnen häpeätä, sillä minä kannan nuoruuteni pilkkaa.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Eikö Efraim ole minun kallis poikani, minun lempilapseni? Sillä niin usein kuin minä puhunkin häntä vastaan, alati minä häntä muistan. Siksi minun sisimpäni väräjää hänen tähtensä: minun täytyy armahtaa häntä, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Pystytä itsellesi kivimerkkejä, aseta itsellesi tienviittoja, paina mieleesi tie, polku, jota olet kulkenut. Palaja, neitsyt Israel, palaja näihin kaupunkeihisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Kuinka kauan sinä mutkistelet sinne ja tänne, sinä luopiotytär? Sillä Herra luo maahan uutta: nainen miestä piirittää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Näin sanoo Herra Sebaot, Israelin Jumala: Vielä kerran sanotaan Juudan maassa ja sen kaupungeissa, kun minä käännän heidän kohtalonsa, tämä sana: \'Herra siunatkoon sinua, sinä vanhurskauden asuinsija, sinä pyhä vuori\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Ja Juuda kaikkine kaupunkeineen asuu siellä yhdessä, peltomiehet ja ne, jotka vaeltavat laumoineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Sillä minä virvoitan väsyneen sielun, ja jokaisen nääntyvän sielun minä ravitsen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Siihen minä heräsin ja katselin, ja uneni oli minusta suloinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, '\"Katso, päivät tulevat, sanoo Herra, jolloin minä kylvän Israelin maahan ja Juudan maahan ihmisen siementä ja karjan siementä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Ja niinkuin minä olen valvonut repiäkseni ja kukistaakseni heitä, hajottaakseni ja hävittääkseni, tuottaakseni onnettomuutta, niin minä olen valvova rakentaakseni ja istuttaakseni heitä, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'Niinä päivinä ei enää sanota: \'Isät söivät raakoja rypäleitä, lasten hampaat heltyivät\';');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'vaan jokaisen on kuoltava oman syntivelkansa tähden. Jokaiselta ihmiseltä, joka syö raakoja rypäleitä, heltyvät hänen omat hampaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Katso, päivät tulevat, sanoo Herra, jolloin minä teen Israelin heimon ja Juudan heimon kanssa uuden liiton;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'en sellaista liittoa kuin se, jonka minä tein heidän isäinsä kanssa silloin, kun minä tartuin heidän käteensä ja vein heidät pois Egyptin maasta, ja jonka liittoni he ovat rikkoneet, vaikka minä olin ottanut heidät omikseni, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Vaan tämä on se liitto, jonka minä teen Israelin heimon kanssa niiden päivien tultua, sanoo Herra: Minä panen lakini heidän sisimpäänsä ja kirjoitan sen heidän sydämiinsä; ja niin minä olen heidän Jumalansa, ja he ovat minun kansani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Silloin ei enää toinen opeta toistansa eikä veli veljeänsä sanoen: \'Tuntekaa Herra\'. Sillä he kaikki tuntevat minut, pienimmästä suurimpaan, sanoo Herra; sillä minä annan anteeksi heidän rikoksensa enkä enää muista heidän syntejänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Näin sanoo Herra, joka on pannut auringon valaisemaan päivää, kuun ja tähdet lakiensa mukaan valaisemaan yötä, hän, joka liikuttaa meren, niin että sen aallot pauhaavat-Herra Sebaot on hänen nimensä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Jos väistyvät nämä lait minun kasvojeni edestä, silloin myös lakkaavat Israelin jälkeläiset olemasta kansa minun kasvojeni edessä ainiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Näin sanoo Herra: Jos voidaan mitata taivaat ylhäällä ja tutkia maan perustukset alhaalla, silloin vasta minä hylkään Israelin jälkeläiset kaikki, kaiken sen tähden, mitä he ovat tehneet, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Katso, päivät tulevat, sanoo Herra, jolloin Herran kaupunki rakennetaan jälleen Hananelin-tornista Kulmaporttiin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Ja edelleen mittanuora kulkee suoraan Gaarebin kukkulalle ja kääntyy sitten Gooaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Ja koko laakso, ruumiineen ja tuhkineen, ja kaikki keto Kidronin puroon asti, Hevosportin kulmaan saakka itään päin, on oleva Herralle pyhitetty. Ei sitä enää ikinä hävitetä eikä kukisteta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Sana, joka tuli Jeremialle Herralta Sidkian, Juudan kuninkaan, kymmenentenä vuotena, se on Nebukadressarin kahdeksantenatoista vuotena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Silloin Baabelin kuninkaan sotajoukko piiritti Jerusalemia, ja profeetta Jeremia oli suljettuna vankilan pihaan, joka on Juudan kuninkaan linnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Sinne oli Sidkia, Juudan kuningas, hänet sulkenut sanoen: \"Miksi sinä ennustat näin: Näin sanoo Herra: Katso, minä annan tämän kaupungin Baabelin kuninkaan käsiin, ja hän valloittaa sen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Ja Sidkia, Juudan kuningas, ei pääse kaldealaisten käsistä, vaan hänet annetaan Baabelin kuninkaan käsiin, ja hänen täytyy puhua hänen kanssaan suusta suuhun ja nähdä hänet silmästä silmään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'Ja hän kuljettaa Sidkian Baabeliin, ja sinne hän jää, kunnes minä katson hänen puoleensa, sanoo Herra. Kun te taistelette kaldealaisia vastaan, ei teillä ole menestystä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Ja Jeremia sanoi: \"Minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Katso, Hanamel, setäsi Sallumin poika, tulee sinun luoksesi ja sanoo: \'Osta minun peltoni, joka on Anatotissa, sillä sinulla on lunastusoikeus, niin että saat ostaa sen\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Ja Hanamel, setäni poika, tuli Herran sanan mukaan minun luokseni vankilan pihaan ja sanoi minulle: \"Osta minun peltoni, joka on Anatotissa, Benjaminin maassa, sillä sinulla on perintöoikeus ja sinulla on lunastusoikeus: osta se itsellesi\". Silloin minä ymmärsin, että se oli Herran sana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Ja minä ostin Hanamelilta, setäni pojalta, pellon, joka on Anatotissa, ja punnitsin hänelle rahat, seitsemäntoista sekeliä hopeata,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'kirjoitin kauppakirjan ja sinetöin sen, otin todistajat ja punnitsin rahat vaa\'alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Sitten minä otin sinetöidyn kauppakirjan, sopimuksen ja määräykset sekä avoimen kirjan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'ja annoin kauppakirjan Baarukille, Neerian, Mahsejan pojan, pojalle, serkkuni Hanamelin nähden ja todistajain nähden, jotka olivat kirjoittaneet kauppakirjan alle, ja kaikkien juutalaisten nähden, jotka istuivat vankilan pihassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'ja minä käskin Baarukia heidän nähtensä sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, '\"Näin sanoo Herra Sebaot, Israelin Jumala: Ota nämä kirjat, tämä kauppakirja, sekä sinetöity että tämä avoin kirja, ja pane ne saviastiaan, että ne säilyisivät kauan aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Vielä kerran ostetaan tässä maassa taloja ja peltoja ja viinitarhoja.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Ja annettuani kauppakirjan Baarukille, Neerian pojalle, minä rukoilin Herraa sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, '\"Oi Herra, Herra! Katso, sinä olet tehnyt taivaan ja maan suurella voimallasi ja ojennetulla käsivarrellasi: ei mikään ole sinulle mahdotonta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'sinä, joka teet laupeuden tuhansille, mutta kostat isäin pahat teot heidän jälkeensä heidän lastensa helmaan; sinä suuri, voimallinen Jumala, jonka nimi on Herra Sebaot,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'suuri neuvossa ja väkevä teossa, sinä, jonka silmät ovat avoimet tarkkaamaan kaikkia ihmislasten teitä, antaaksesi itsekullekin hänen vaelluksensa ja hänen töittensä hedelmän mukaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'sinä, joka teit tunnustekoja ja ihmeitä Egyptin maassa ja olet tehnyt niitä hamaan tähän päivään asti sekä Israelissa että muitten ihmisten seassa, ja joka olet tehnyt itsellesi nimen, senkaltaisen kuin se tänäkin päivänä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Sinä veit kansasi Israelin pois Egyptin maasta tunnusteoilla ja ihmeillä, väkevällä kädellä ja ojennetulla käsivarrella, suurella peljätyksellä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'ja annoit heille tämän maan, jonka sinä heidän isillensä vannotulla valalla olit luvannut antaa heille, maan, joka vuotaa maitoa ja mettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Mutta kun he olivat tulleet ja ottaneet sen omaksensa, eivät he kuulleet sinun ääntäsi eivätkä vaeltaneet sinun lakisi mukaan; he eivät tehneet mitään siitä, mitä sinä olit käskenyt heidän tehdä. Silloin sinä annoit kaiken tämän onnettomuuden kohdata heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Katso, piiritysvallit ovat edenneet aivan kaupunkiin asti, niin että se valloitetaan, ja kaupunki joutuu miekan, nälän ja ruton pakosta kaldealaisten valtaan, jotka sotivat sitä vastaan. Mitä sinä olet puhunut, on tapahtunut, ja katso, sinä näet sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Mutta kuitenkin sinä, Herra, Herra, sanoit minulle: \'Osta rahalla itsellesi pelto ja ota todistajat\', vaikka kaupunki joutuu kaldealaisten käsiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Ja Jeremialle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, '\"Katso, minä olen Herra, kaiken lihan Jumala; onko minulle mitään mahdotonta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Sentähden, näin sanoo Herra: Katso, minä annan tämän kaupungin kaldealaisten käsiin ja Nebukadressarin, Baabelin kuninkaan, käsiin, ja hän valloittaa sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Ja kaldealaiset, jotka sotivat tätä kaupunkia vastaan, tulevat ja sytyttävät tämän kaupungin tuleen ja polttavat sen niine taloineen, joiden katoilla on poltettu uhreja Baalille ja vuodatettu juomauhreja vieraille jumalille, minulle mielikarvaudeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Sillä Israelin ja Juudan miehet ovat hamasta nuoruudestaan tehneet vain sitä, mikä on pahaa minun silmissäni, sillä israelilaiset ovat tuottaneet minulle ainoastaan mielikarvautta kättensä teoilla, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Sillä tämä kaupunki on ollut minulle vihaksi ja kiivastukseksi hamasta siitä päivästä, jona he sen rakensivat, aina tähän päivään asti; ja niin minä heitän sen pois kasvojeni edestä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'kaiken sen pahan tähden, minkä israelilaiset ja Juudan miehet ovat tehneet minulle mielikarvaudeksi-he, heidän kuninkaansa, ruhtinaansa, pappinsa ja profeettansa sekä Juudan miehet ja Jerusalemin asukkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'He ovat kääntäneet minulle selkänsä eivätkä kasvojansa; ja vaikka minä olen opettanut heitä varhaisesta alkaen, he eivät ole kuulleet eivätkä ottaneet varteen kuritusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'He ovat asettaneet iljetyksensä temppeliin, joka on otettu minun nimiini, ja saastuttaneet sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Ja he ovat rakentaneet Baalille uhrikukkulat, jotka ovat Ben-Hinnomin laaksossa, polttaakseen poikiansa ja tyttäriänsä uhrina Molokille, mitä minä en ole käskenyt ja mikä ei ole minun mieleeni tullut. Tällaisia kauhistuksia he tekivät ja saivat Juudan syntiä tekemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Mutta nyt sanoo Herra, Israelin Jumala, näin tästä kaupungista, jonka te sanotte joutuvan Baabelin kuninkaan käsiin miekan, nälän ja ruton pakosta:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Katso, minä kokoan heidät jälleen kaikista maista, joihin minä heidät vihassani, kiivastuksessani ja suuressa suuttumuksessani karkoitan, ja palautan heidät tähän paikkaan ja annan heidän asua turvassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Silloin he ovat minun kansani, ja minä olen heidän Jumalansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Ja minä annan heille yhden sydämen ja yhden tien, niin että he pelkäävät minua kaiken elinaikansa, ja niin heidän käy hyvin ja heidän lastensa heidän jälkeensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Ja minä teen heidän kanssansa iankaikkisen liiton, niin etten käänny heistä pois, vaan teen heille hyvää; ja minä annan pelkoni heidän sydämiinsä, niin etteivät he minusta luovu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Ja minä iloitsen heistä, siitä että teen heille hyvää; minä istutan heidät tähän maahan uskollisesti, kaikesta sydämestäni ja kaikesta sielustani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Sillä näin sanoo Herra: Niinkuin minä olen tuottanut tälle kansalle kaiken tämän suuren onnettomuuden, niin minä myös tuotan heille kaiken sen hyvän, minkä minä heille lupaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Vielä ostetaan peltoja tässä maassa, josta te sanotte: \'Se on oleva autio, vailla ihmisiä ja eläimiä, kaldealaisten käsiin annettu\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Peltoja ostetaan rahalla, kauppakirjoja kirjoitetaan ja sinetöidään ja todistajia otetaan Benjaminin maassa, Jerusalemin ympäristössä ja Juudan kaupungeissa, Vuoriston, Alankomaan ja Etelämaan kaupungeissa, sillä minä käännän heidän kohtalonsa, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Herran sana tuli Jeremialle toistamiseen, kun hän vielä oli suljettuna vankilan pihaan; se kuului näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, '\"Näin sanoo Herra, joka sen myös tekee, Herra, joka valmistaa sen ja vahvistaa sen-Herra on hänen nimensä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Huuda minua avuksesi, niin minä vastaan sinulle ja ilmoitan sinulle suuria ja salattuja asioita, joita sinä et tiedä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Sillä näin sanoo Herra, Israelin Jumala, tämän kaupungin taloista ja Juudan kuningasten linnoista, jotka sortuvat piiritysvallien ja miekan edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'ja niistä, jotka ovat tulleet taistelemaan kaldealaisia vastaan, ja täyttämään talot ihmisten ruumiilla, jotka minä surmaan vihassani ja kiivastuksessani ja joiden kaiken pahuuden tähden minä olen kätkenyt kasvoni tältä kaupungilta:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Katso, minä kasvatan umpeen ja lääkitsen sen haavat, ja minä parannan heidät ja avaan heille rauhan ja totuuden runsauden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Minä käännän Juudan kohtalon ja Israelin kohtalon ja rakennan heidät muinaiselleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Ja minä puhdistan heidät kaikista heidän pahoista teoistansa, joilla he ovat rikkoneet minua vastaan, ja minä annan anteeksi kaikki heidän pahat tekonsa, joilla he ovat rikkoneet minua vastaan ja minusta luopuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Ja tämä kaupunki on oleva minulle kunniaksi ja iloksi, ylistykseksi ja kirkkaudeksi kaikkien maan kansojen edessä, jotka kuulevat kaiken sen hyvän, minkä minä sille teen; he peljästyvät ja vapisevat kaikkea sitä hyvää ja kaikkea sitä onnea, jonka minä sille annan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Näin sanoo Herra: Vielä kerran kuullaan tässä paikassa, josta te sanotte: \'Se on oleva rauniona, vailla ihmisiä ja eläimiä\'. Juudan kaupungeissa ja Jerusalemin autioilla kaduilla, joilla ei ihmistä, ei asukasta, ei eläintä ole,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'riemun ja ilon huuto, huuto yljälle ja huuto morsiamelle, niiden huuto, jotka sanovat: \'Kiittäkää Herraa Sebaotia, sillä Herra on hyvä, sillä hänen armonsa pysyy iankaikkisesti\', ja niiden, jotka tuovat Herran huoneeseen kiitosuhreja. Sillä minä käännän maan kohtalon muinaiselleen, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Näin sanoo Herra Sebaot: Vielä kerran on tässä paikassa, joka on rauniona, vailla ihmisiä ja eläimiä, ja kaikilla sen kaupungeilla oleva laitumia, joilla paimenet lepuuttavat lampaitansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'Vuoriston kaupungeissa, Alankomaan kaupungeissa ja Etelämaan kaupungeissa, Benjaminin maassa, Jerusalemin ympäristössä ja Juudan kaupungeissa on vielä kerran lampaita kulkeva laskijan kätten ohi, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Katso, päivät tulevat, sanoo Herra, jolloin minä täytän sen hyvän lupauksen, jonka minä olen lausunut Israelin heimosta ja Juudan heimosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'Niinä päivinä ja siihen aikaan minä kasvatan Daavidille vanhurskauden vesan, ja hän on tekevä oikeuden ja vanhurskauden maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'Niinä päivinä Juuda pelastetaan, ja Jerusalem asuu turvassa, ja tämä on se nimi, jolla sitä kutsutaan: \'Herra, meidän vanhurskautemme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Sillä näin sanoo Herra: Aina on mies Daavidin suvusta istuva Israelin heimon valtaistuimella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Ja aina on mies leeviläisten pappien suvusta oleva minun edessäni uhraamassa polttouhria ja sytyttämässä ruokauhria ja toimittamassa teurasuhria joka päivä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Ja Jeremialle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, '\"Näin sanoo Herra: Jos saatte rikotuksi minun liittoni päivän kanssa ja minun liittoni yön kanssa, niin että päivä ja yö eivät enää tule ajallansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'niin rikkoutuu myös minun liittoni palvelijani Daavidin kanssa, niin ettei hänellä enää ole poikaa, joka istuu kuninkaana hänen valtaistuimellansa, ja minun liittoni leeviläisten pappien, minun palvelijaini, kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Niinkuin taivaan joukkoa ei voida lukea eikä meren hiekkaa mitata, niin monilukuisiksi minä teen palvelijani Daavidin jälkeläiset ja leeviläiset, jotka minua palvelevat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Ja Jeremialle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, '\"Etkö ole huomannut, mitä tämä kansa puhuu sanoen: \'Ne kaksi sukukuntaa, jotka Herra valitsi, hän on hyljännyt\'? Ja he halveksivat minun kansaani, niinkuin se ei enää olisikaan kansa heidän silmissänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Näin sanoo Herra: Jos minun liittoni päivän ja yön kanssa on olematon, jos en ole säätänyt taivaan ja maan lakeja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'niin minä myös hylkään Jaakobin ja palvelijani Daavidin jälkeläiset, niin etten ota hänen jälkeläisistänsä hallitsijoita Aabrahamin, Iisakin ja Jaakobin jälkeläisille. Sillä minä käännän heidän kohtalonsa ja armahdan heitä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Sana, joka tuli Jeremialle Herralta, kun Nebukadnessar, Baabelin kuningas, ja koko hänen sotajoukkonsa ja kaikki hänen valtansa alaisen maan valtakunnat ja kaikki kansat sotivat Jerusalemia ja kaikkia sen alaisia kaupunkeja vastaan; se kuului näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, '\"Näin sanoo Herra, Israelin Jumala: Mene ja sano Sidkialle, Juudan kuninkaalle, sano hänelle: Näin sanoo Herra: Katso, minä annan tämän kaupungin Baabelin kuninkaan käsiin, ja hän polttaa sen tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Ja sinä et pääse hänen käsistään, vaan sinut otetaan kiinni ja annetaan hänen käsiinsä, ja sinun täytyy nähdä Baabelin kuningas silmästä silmään, ja hän puhuu sinun kanssasi suusta suuhun, ja sinä joudut Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Mutta kuule Herran sana, Sidkia, Juudan kuningas: Näin sanoo Herra sinusta: Sinä et ole kuoleva miekkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'Sinä saat kuolla rauhassa; ja niinkuin sinun isillesi, aikaisemmille kuninkaille, jotka olivat ennen sinua, niin poltetaan sinun kunniaksesi kuolinsuitsutus ja sinulle pidetään valittajaiset ja huudetaan: \'Voi herraamme!\' Sillä minä olen sen sanonut, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Ja profeetta Jeremia puhui Sidkialle, Juudan kuninkaalle, kaikki nämä sanat Jerusalemissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'kun Baabelin kuninkaan sotajoukko taisteli Jerusalemia vastaan ja kaikkia vielä jäljellä olevia Juudan kaupunkeja vastaan, Laakista ja Asekaa vastaan, sillä nämä olivat jääneet jäljelle Juudan kaupungeista, varustetuista kaupungeista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Sana, joka tuli Jeremialle Herralta, sen jälkeen kuin kuningas Sidkia oli tehnyt liiton kaiken kansan kanssa, joka oli Jerusalemissa, ja heille julistanut vapautuksen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'että jokaisen tuli päästää vapaaksi orjansa ja orjattarensa, hebrealainen mies ja hebrealainen nainen, niin etteivät heitä orjinansa pitäisi, ei kukaan juutalaista veljeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Ja sen kuulivat kaikki päämiehet ja kaikki kansa, jotka olivat menneet tähän liittoon, että jokaisen tuli päästää vapaaksi orjansa ja orjattarensa eikä enää pitää heitä orjinansa; ja he tottelivat ja päästivät heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Mutta jälkeenpäin he peräytyivät liitosta ja ottivat takaisin ne orjat ja orjattaret, jotka he olivat päästäneet vapaiksi, ja pakottivat heidät orjikseen ja orjattarikseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Silloin tuli Jeremialle Herralta tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, '\"Näin sanoo Herra, Israelin Jumala: Minä tein teidän isäinne kanssa liiton silloin, kun minä vein heidät pois Egyptin maasta, orjuuden pesästä, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Seitsemän vuoden kuluttua päästäkää veljenne, hebrealainen: joka on myynyt itsensä sinulle ja palvellut sinua kuusi vuotta, se päästä luotasi vapaaksi. Mutta teidän isänne eivät kuulleet minua, eivät korvaansa kallistaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Vaan nyt te olette kääntyneet ja tehneet teon, joka on oikea minun silmissäni, julistaessanne vapautuksen kukin lähimmäisellensä, ja olette tehneet liiton minun kasvojeni edessä temppelissä, joka on otettu minun nimiini.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Mutta sitten te olette jälleen kääntyneet pois ja häväisseet minun nimeni: olette ottaneet takaisin jokainen orjansa ja orjattarensa, jotka olitte päästäneet vapaiksi omiin valtoihinsa, ja olette pakottaneet heidät olemaan orjinanne ja orjattarinanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Sentähden näin sanoo Herra: Te ette kuulleet minua ettekä julistaneetkaan vapautusta kukin veljellensä ja lähimmäisellensä; katso, minä julistan teille vapautuksen, sanoo Herra: menon miekkaan, ruttoon ja nälkään. Ja minä teen teidät kauhistukseksi kaikille valtakunnille maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Ja minä annan ne miehet, jotka ovat rikkoneet minun liittoni, jotka eivät ole pitäneet sen liiton sanoja, jonka he tekivät minun edessäni halkaisten kahtia uhrivasikan ja käyden sen puolikkaiden välitse, nämä miehet-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Juudan ruhtinaat ja Jerusalemin ruhtinaat, hoviherrat ja papit sekä kaiken maan kansan, jotka kävivät vasikan puolikkaiden välitse-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'ne minä annan heidän vihollistensa käsiin, niiden käsiin, jotka etsivät heidän henkeänsä; ja heidän ruumiinsa joutuvat taivaan lintujen ja maan eläinten ruuaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Ja Sidkian, Juudan kuninkaan, ja hänen ruhtinaansa minä annan heidän vihollistensa käsiin, niiden käsiin, jotka etsivät heidän henkeänsä, Baabelin kuninkaan sotajoukon käsiin, joka on lähtenyt pois teidän kimpustanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Katso, minä käsken heitä, sanoo Herra, ja palautan heidät tämän kaupungin kimppuun, ja he sotivat sitä vastaan, valloittavat sen ja polttavat sen tulella; ja Juudan kaupungit minä teen autioiksi, asujattomiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Sana, joka tuli Jeremialle Herralta Juudan kuninkaan Joojakimin, Joosian pojan, päivinä; se kuului:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, '\"Mene reekabilaisten tykö ja puhuttele heitä ja vie heidät Herran temppeliin, yhteen sen kammioista, ja anna heille viiniä juoda\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Ja minä otin Jaasanjan, joka oli Jeremian, Habassinjan pojan, poika, sekä hänen veljensä ja kaikki hänen poikansa ja kaikki reekabilaiset');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'ja vein heidät Herran temppeliin, Jumalan miehen Haananin, Jigdaljan pojan, poikien kammioon, joka on päämiesten kammion vieressä, ovenvartija Maasejan, Sallumin pojan, kammion yläpuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Ja minä asetin reekabilaisten eteen täysiä viiniruukkuja ynnä maljoja ja sanoin heille: \"Juokaa viiniä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Mutta he vastasivat: \"Me emme juo viiniä; sillä meidän isämme Joonadab, Reekabin poika, on antanut meille tämän käskyn: Älkää, te ja teidän lapsenne, ikinä viiniä juoko;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Älkää rakentako taloja älkääkä kylväkö siementä; älkää istuttako viinitarhoja, älköönkä niitä teillä olko, vaan asukaa teltoissa kaikkina elämänne päivinä, että kauan eläisitte siinä maassa, jossa te olette muukalaisina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Ja me olemme kuuliaiset isällemme Joonadabille, Reekabin pojalle, kaikessa, mitä hän on käskenyt meidän tehdä, niin että emme koskaan juo viiniä elämämme päivinä, emme me eivätkä vaimomme, eivät poikamme eivätkä tyttäremme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'emmekä rakenna taloja asuaksemme, eikä meillä ole viinitarhoja, ei peltoa eikä kylvöä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Vaan me asumme teltoissa ja olemme kuuliaiset ja teemme kaiken, mitä isämme Joonadab on käskenyt meidän tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Mutta kun Nebukadressar, Baabelin kuningas, hyökkäsi maahan, niin me sanoimme: \'Tulkaa, menkäämme Jerusalemiin kaldealaisten sotajoukkoa ja aramilaisten sotajoukkoa pakoon\', ja me asetuimme Jerusalemiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Ja Jeremialle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, '\"Näin sanoo Herra Sebaot, Israelin Jumala: Mene ja sano Juudan miehille ja Jerusalemin asukkaille: Ettekö ota kuritusta varteen ja kuule minun sanojani? sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Joonadabin, Reekabin pojan, sanat, joilla hän kielsi poikiansa juomasta viiniä, pidetään voimassa, ja niin he eivät ole juoneet tähän päivään asti, sillä he ovat kuuliaiset isänsä käskylle. Mutta minä olen puhunut teille varhaisesta alkaen, ja te ette ole kuulleet minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Ja minä olen lähettänyt teidän tykönne kaikki palvelijani, profeetat, varhaisesta alkaen, sanoen: Kääntykää kukin pahalta tieltänne ja parantakaa tekonne, älkää seuratko muita jumalia älkääkä niitä palvelko, niin te saatte asua siinä maassa, jonka minä olen antanut teille ja teidän isillenne; mutta te ette ole kallistaneet korvaanne, ette ole kuulleet minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Joonadabin, Reekabin pojan, jälkeläiset ovat siis pitäneet voimassa isänsä käskyn, jonka hän heille antoi, mutta tämä kansa ei ole kuullut minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Sentähden, näin sanoo Herra, Jumala Sebaot, Israelin Jumala: Katso, minä annan tulla Juudalle ja kaikille Jerusalemin asukkaille kaiken sen onnettomuuden, jolla minä olen heitä uhannut, koska he eivät kuulleet, kun minä heille puhuin, eivät vastanneet, kun minä heitä kutsuin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Ja reekabilaisille sanoi Jeremia: \"Näin sanoo Herra Sebaot, Israelin Jumala: Koska te olette olleet kuuliaiset isänne Joonadabin käskylle ja noudattaneet kaikkia hänen käskyjänsä ja tehneet kaiken, mitä hän käski teidän tehdä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'sentähden, näin sanoo Herra Sebaot, Israelin Jumala: Joonadabin, Reekabin pojan, suvussa on aina oleva mies, joka seisoo minun kasvojeni edessä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Juudan kuninkaan Joojakimin, Joosian pojan, neljäntenä hallitusvuotena tuli tämä sana Jeremialle Herralta; se kuului:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, '\"Ota kirjakäärö ja kirjoita siihen kaikki ne sanat, jotka minä olen puhunut sinulle Israelista ja Juudasta ja kaikista pakanakansoista siitä päivästä asti, jolloin minä aloin sinulle puhua, Joosian päivistä, aina tähän päivään saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Ehkäpä Juudan heimo, kuultuaan kaiken sen onnettomuuden, jonka minä aion heille tuottaa, kääntyy, kukin pahalta tieltään, ja niin minä annan anteeksi heidän pahat tekonsa ja syntinsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Silloin Jeremia kutsui Baarukin, Neerian pojan, ja Baaruk kirjoitti kirjakääröön Jeremian suusta kaikki ne sanat, jotka Herra oli hänelle puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Sitten Jeremia käski Baarukia sanoen: \"Minä olen estetty, en voi mennä Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Mene sinä ja lue kirjakääröstä, jonka olet kirjoittanut suoraan minun suustani, Herran sanat kansan kuullen Herran temppelissä paastopäivänä; myöskin koko Juudan kuullen, kaikkien, jotka tulevat kaupungeistansa, on sinun ne luettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Ehkäpä he rukouksessa lankeavat alas Herran eteen ja kääntyvät kukin pahalta tieltään. Sillä suuri on viha ja kiivastus, jolla Herra on uhannut tätä kansaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Ja Baaruk, Neerian poika, teki kaikki, niinkuin profeetta Jeremia oli käskenyt hänen tehdä, ja luki kirjasta Herran sanat Herran temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Mutta Juudan kuninkaan Joojakimin, Joosian pojan, viidentenä hallitusvuotena, yhdeksännessä kuussa, oli kaikki Jerusalemin kansa ja kaikki se kansa, joka oli tullut Juudan kaupungeista Jerusalemiin, kutsuttu pitämään paastoa Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Silloin Baaruk luki kirjasta Jeremian sanat Herran temppelissä, kirjuri Gemarjan, Saafanin pojan, kammiossa, ylemmässä esipihassa, Herran temppelin uuden portin ovella, kaiken kansan kuullen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Kun Miika, Gemarjan, Saafanin pojan, poika, oli kuullut kaikki Herran sanat kirjasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'niin hän meni alas kuninkaan linnaan, kirjurin kammioon, ja katso, siellä istuivat kaikki päämiehet: kirjuri Elisama ja Delaja, Semajan poika, ja Elnatan, Akborin poika, ja Gemarja, Saafanin poika, ja Sidkia, Hananjan poika, ja kaikki muut päämiehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Heille Miika ilmoitti kaikki sanat, jotka hän oli kuullut Baarukin lukevan kirjasta kansan kuullen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Silloin kaikki päämiehet lähettivät Baarukin tykö Jehudin, joka oli Netanjan poika, joka Selemjan poika, joka Kuusin poika, ja käskivät sanoa: \"Ota käteesi kirjakäärö, josta luit kansan kuullen, ja tule tänne\". Ja Baaruk, Neerian poika, otti kirjakäärön käteensä ja meni heidän tykönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Ja he sanoivat hänelle: \"Istu ja lue meidän kuultemme\", ja Baaruk luki heidän kuultensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Mutta kun he olivat kuulleet kaikki sanat, katsoivat he toisiinsa peljästyneinä ja sanoivat Baarukille: \"Meidän täytyy ilmoittaa kuninkaalle kaikki nämä sanat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Ja he kysyivät Baarukilta sanoen: \"Ilmoita meille, kuinka sinä kirjoitit kaikki nämä sanat hänen suustansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Baaruk vastasi heille: \"Hän saneli minulle suustansa kaikki nämä sanat, ja minä kirjoitin ne musteella kirjaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Silloin päämiehet sanoivat Baarukille: \"Mene ja piiloudu, sinä ja Jeremia, älköönkä kukaan saako tietää, missä te olette\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Niin he menivät kuninkaan tykö esipihaan, mutta kirjakäärön he jättivät talteen kirjuri Elisaman kammioon. Ja he ilmoittivat kuninkaalle kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Silloin kuningas lähetti Jehudin hakemaan kirjakääröä, ja hän haki sen kirjuri Elisaman kammiosta. Sitten Jehudi luki sen kuninkaan kuullen ja kaikkien päämiesten kuullen, jotka seisoivat kuninkaan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Mutta kuningas istui talvihuoneessa-oli yhdeksäs kuukausi-ja hänen edessään oli palamassa hiilipannu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Ja aina kun Jehudi oli lukenut kolme tai neljä palstaa, leikkasi kuningas ne pois kirjurinveitsellä ja viskasi tuleen, joka oli hiilipannussa, kunnes koko kirjakäärö oli palanut loppuun tulessa, joka oli hiilipannussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Mutta ei kuningas eikä kukaan hänen palvelijoistaan, jotka kuulivat kaikki nämä sanat, peljästynyt eikä reväissyt vaatteitansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Ja vaikka Elnatan ja Delaja ja Gemarja pyysivät hartaasti kuningasta, ettei hän polttaisi kirjakääröä, ei hän heitä kuullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Ja kuningas käski Jerahmeelin, kuninkaan pojan, ja Serajan, Asrielin pojan, ja Selemjan, Abdeelin pojan, ottaa kiinni kirjuri Baarukin ja profeetta Jeremian; mutta Herra kätki heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Mutta sen jälkeen kuin kuningas oli polttanut kirjakäärön ynnä sanat, jotka Baaruk oli kirjoittanut Jeremian suusta, tuli Jeremialle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, '\"Ota taas itsellesi toinen kirjakäärö ja kirjoita siihen kaikki entiset sanat, jotka olivat edellisessäkin kirjakäärössä, jonka Juudan kuningas Joojakim poltti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Ja sano Juudan kuninkaasta Joojakimista: Näin sanoo Herra: Sinä olet polttanut tämän kirjakäärön sanoen: \'Miksi olet kirjoittanut siihen näin: Baabelin kuningas on tuleva ja hävittävä tämän maan ja lopettava siitä ihmiset ja eläimet?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Sentähden sanoo Herra Juudan kuninkaasta Joojakimista näin: Hänellä ei ole oleva jälkeläistä, joka istuisi Daavidin valtaistuimella; ja hänen ruumiinsa viskataan pois, virumaan päivän helteessä ja yön kylmässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Ja minä rankaisen häntä ja hänen jälkeläisiänsä ja hänen palvelijoitansa heidän pahojen tekojensa tähden. Ja minä annan tulla heille ja Jerusalemin asukkaille ja Juudan miehille kaiken sen onnettomuuden, jolla minä olen heitä uhannut, vaikka he eivät ole kuulleet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Sitten Jeremia otti toisen kirjakäärön ja antoi sen kirjuri Baarukille, Neerian pojalle; ja tämä kirjoitti siihen Jeremian suusta kaikki sen kirjan sanat, jonka Juudan kuningas Joojakim oli tulessa polttanut. Ja niihin lisättiin vielä paljon samankaltaisia sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Ja Sidkia, Joosian poika, tuli kuninkaaksi Konjan, Joojakimin pojan, sijaan; sillä Nebukadressar, Baabelin kuningas, asetti hänet kuninkaaksi Juudan maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Mutta ei hän eivätkä hänen palvelijansa eikä maan kansa totelleet Herran sanoja, jotka hän puhui profeetta Jeremian kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Ja kuningas Sidkia lähetti Juukalin, Selemjan pojan, ja pappi Sefanjan, Maasejan pojan, profeetta Jeremian tykö ja käski sanoa: \"Rukoile meidän puolestamme Herraa, meidän Jumalaamme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Silloin vielä Jeremia sai tulla ja mennä kansan keskellä, sillä häntä ei oltu pantu vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Mutta faraon sotajoukko oli lähtenyt liikkeelle Egyptistä; ja kun kaldealaiset, jotka piirittivät Jerusalemia, kuulivat siitä sanoman, lähtivät he pois Jerusalemin kimpusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Silloin tuli profeetta Jeremialle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, '\"Näin sanoo Herra, Israelin Jumala: Sanokaa näin Juudan kuninkaalle, joka on lähettänyt teidät minun tyköni kysymään minulta neuvoa: Katso, faraon sotajoukko, joka on lähtenyt teidän avuksenne, on palaava takaisin maahansa Egyptiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Sitten kaldealaiset tulevat takaisin ja sotivat tätä kaupunkia vastaan, valloittavat sen ja polttavat tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Näin sanoo Herra: Älkää pettäkö itseänne sanoen: \'Kaldealaiset lähtevät pois meidän kimpustamme\'. Sillä he eivät lähde.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Ja vaikka te voittaisitte koko kaldealaisten sotajoukon, joka sotii teitä vastaan, niin ettei heistä jäisi jäljelle kuin muutamia haavoitettuja miehiä, niin nämä nousisivat pystyyn, kukin teltassansa, ja tulella polttaisivat tämän kaupungin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Mutta kun kaldealaisten sotajoukko faraon sotajoukon tähden oli lähtenyt pois Jerusalemia piirittämästä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'yritti Jeremia lähteä Jerusalemista mennäkseen Benjaminin maahan ottamaan perintömaan jaossa osansa siellä, kansan keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Mutta kun hän oli tullut Benjaminin portille, niin siinä oleva vartionpäällikkö, jonka nimi oli Jiiria, Selemjan, Hananjan pojan, poika, otti kiinni profeetta Jeremian sanoen: \"Sinä aiot karata kaldealaisten puolelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Jeremia vastasi: \"Se on valhe! Minä en aio karata kaldealaisten puolelle.\" Mutta Jiiria ei kuunnellut häntä, vaan otti Jeremian kiinni ja vei hänet päämiesten tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Ja ruhtinaat vihastuivat Jeremiaan ja löivät häntä ja panivat hänet vankeuteen kirjuri Joonatanin taloon, sillä sen he olivat laittaneet vankilaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'Niin Jeremia joutui vankiluolaan ja holveihin, ja Jeremia jäi sinne kauaksi aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Sitten kuningas Sidkia lähetti hakemaan hänet, ja kuningas kysyi häneltä salaa linnassansa ja sanoi: \"Onko sanaa Herralta?\" Jeremia vastasi: \"On\". Ja hän sanoi: \"Sinut annetaan Baabelin kuninkaan käsiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Ja Jeremia sanoi kuningas Sidkialle: \"Mitä minä olen rikkonut sinua ja sinun palvelijoitasi vastaan ja tätä kansaa vastaan, koska te olette panneet minut vankeuteen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Ja missä ovat teidän profeettanne, jotka ennustivat teille sanoen: \'Ei tule Baabelin kuningas teidän kimppuunne eikä tämän maan kimppuun\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Ja kuule nyt, herrani, kuningas, salli minun rukoukseni langeta sinun eteesi äläkä lähetä minua takaisin kirjuri Joonatanin taloon, etten kuolisi siellä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Silloin kuningas Sidkia käski säilyttää Jeremiaa vankilan pihassa, ja hänelle annettiin leipäkakku päivässä Leipurienkadulta, kunnes kaikki leipä oli kaupungista loppunut. Ja Jeremia jäi vankilan pihaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Mutta Sefatja, Mattanin poika, ja Gedalja, Pashurin poika, ja Juukal, Selemjan poika, ja Pashur, Malkian poika, kuulivat ne sanat, jotka Jeremia puhui kaikelle kansalle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, '\"Näin sanoo Herra: Joka jää tähän kaupunkiin, se kuolee miekkaan, nälkään ja ruttoon; mutta joka menee kaldealaisten luo, se saa elää, pitää henkensä saaliinansa ja jää eloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Näin sanoo Herra: Tämä kaupunki annetaan Baabelin kuninkaan sotajoukon käsiin, ja hän valloittaa sen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Silloin päämiehet sanoivat kuninkaalle: \"Tämä mies on kuolemalla rangaistava, sillä hän herpaisee niiden sotamiesten kädet, jotka ovat jäljellä tässä kaupungissa, ja kaiken kansan kädet, kun hän heille puhuu tällaisia sanoja. Sillä ei tämä mies etsi tämän kansan menestystä, vaan onnettomuutta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Kuningas Sidkia vastasi: \"Katso, hän on teidän käsissänne. Sillä eihän kuningas voi mitään teitä vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Silloin he ottivat Jeremian ja heittivät hänet Malkian, kuninkaan pojan, kaivoon, joka oli vankilan pihassa; he laskivat Jeremian köysillä alas. Mutta kaivossa ei ollut vettä, vaan liejua, ja Jeremia vajosi liejuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Mutta etiopialainen Ebed-Melek, hoviherra, joka oli kuninkaan linnassa, kuuli, että he olivat panneet Jeremian kaivoon; mutta kuningas istui Benjaminin portissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Niin Ebed-Melek meni kuninkaan linnasta ja puhutteli kuningasta sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, '\"Herrani, kuningas! Nuo miehet ovat pahoin tehneet kaikessa, mitä ovat tehneet profeetta Jeremialle: he ovat heittäneet hänet kaivoon, kuolemaan nälkään siihen paikkaansa.\" Sillä kaupungissa ei ollut enää leipää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Silloin kuningas käski etiopialaista Ebed-Melekiä sanoen: \"Ota mukaasi täältä kolmekymmentä miestä ja nosta profeetta Jeremia kaivosta, ennenkuin hän kuolee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Ja Ebed-Melek otti miehet mukaansa ja meni kuninkaan linnaan, aarrekammion alla olevaan paikkaan, ja otti sieltä rikkinäisiä ja kuluneita vaateriepuja ja laski ne köysillä Jeremialle kaivoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Sitten etiopialainen Ebed-Melek sanoi Jeremialle: \"Pane nämä rikkinäiset ja kuluneet vaaterievut kainaloihisi köytten alle\", ja Jeremia teki niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Sitten he vetivät Jeremian köysillä ylös ja nostivat hänet kaivosta. Ja Jeremia jäi vankilan pihaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Mutta kuningas Sidkia lähetti hakemaan profeetta Jeremian tykönsä Herran temppelin kolmanteen sisäänkäytävään. Ja kuningas sanoi Jeremialle: \"Minä kysyn sinulta jotakin; älä salaa minulta mitään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Mutta Jeremia vastasi Sidkialle: \"Jos minä sinulle jotakin ilmoitan, niin sinähän surmautat minut. Ja jos minä sinua neuvon, et sinä minua kuule.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Silloin kuningas Sidkia vannoi salaa Jeremialle sanoen: \"Niin totta kuin Herra elää, joka on luonut tämän meidän elämämme: minä en sinua surmauta enkä jätä sinua näiden miesten käsiin, jotka etsivät sinun henkeäsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Silloin Jeremia sanoi Sidkialle: \"Näin sanoo Herra, Jumala Sebaot, Israelin Jumala: Jos sinä menet Baabelin kuninkaan päämiesten tykö, niin sinun henkesi säilyy, eikä tätä kaupunkia tulella polteta, ja sinä ja sinun huoneesi saatte elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Mutta jos sinä et mene Baabelin kuninkaan päämiesten tykö, niin tämä kaupunki annetaan kaldealaisten käsiin, ja he polttavat sen tulella, etkä sinäkään pelastu heidän käsistänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Silloin kuningas Sidkia sanoi Jeremialle: \"Minä pelkään niitä juutalaisia, jotka ovat menneet kaldealaisten puolelle, pelkään, että minut jätetään heidän käsiinsä ja he pitävät minua pilkkanansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Mutta Jeremia sanoi: \"Ei jätetä. Kuule vain Herran ääntä, kuule, mitä minä sinulle puhun, niin sinun käy hyvin, ja sinun henkesi säilyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Mutta jos sinä et tahdo mennä, niin tämä on se sana, jonka Herra on minulle näyttänyt:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Katso, kaikki naiset, jotka ovat jäljellä Juudan kuninkaan linnassa, viedään Baabelin kuninkaan päämiesten luokse, ja katso, he sanovat: \'Sinun ystäväsi ovat sinut viekoitelleet ja saaneet sinut valtaansa; sinun jalkasi vajosivat liejuun-he vetäytyivät pois\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Ja kaikki sinun vaimosi ja lapsesi viedään kaldealaisten luokse, etkä sinä pelastu näiden käsistä, vaan Baabelin kuninkaan käsi tarttuu sinuun, ja sinä saatat tämän kaupungin tulella poltettavaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Silloin Sidkia sanoi Jeremialle: \"Älköön kukaan saako tietää tästä puhelusta, muutoin sinä kuolet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Mutta jos päämiehet kuulevat, että minä olen puhunut sinun kanssasi, ja tulevat sinun luoksesi ja sanovat sinulle: \'Ilmoita meille, mitä olet puhunut kuninkaalle ja mitä kuningas on puhunut sinulle-älä salaa sitä meiltä, muutoin me surmaamme sinut\' -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'niin sano heille: \'Minä annoin rukoukseni langeta kuninkaan eteen, ettei hän lähettäisi minua takaisin Joonatanin taloon, kuolemaan sinne\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Ja kaikki ruhtinaat tulivat Jeremian tykö ja kysyivät häneltä, ja hän ilmoitti heille kaiken, mitä kuningas oli käskenyt hänen ilmoittaa. Niin he jättivät hänet rauhaan, sillä asiasta ei oltu mitään kuultu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Ja Jeremia jäi olemaan vankilan pihassa siihen päivään asti, jona Jerusalem valloitettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Kun Jerusalem oli valloitettu-sillä Juudan kuninkaan Sidkian yhdeksäntenä hallitusvuotena, kymmenennessä kuussa, oli Nebukadressar, Baabelin kuningas, kaikkine sotajoukkoineen hyökännyt Jerusalemin kimppuun ja saartanut sen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'ja Sidkian yhdentenätoista hallitusvuotena, neljännessä kuussa, kuukauden yhdeksäntenä päivänä, oli kaupunki vallattu');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, '-niin kaikki Baabelin kuninkaan päämiehet tulivat ja asettuivat Keskiporttiin: Neergal-Sareser, Samgar-Nebo, Sarsekim, ylimmäinen hoviherra, Neergal-Sareser, ylimmäinen tietäjä, ja kaikki muut Baabelin kuninkaan päämiehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Kun Sidkia, Juudan kuningas, ja kaikki sotilaat näkivät heidät, niin he pakenivat ja lähtivät yöllä kaupungista kuninkaan puutarhaa kohti molempain muurien välisestä portista, ja hän lähti Aromaahan päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Mutta kaldealaisten sotajoukko ajoi heitä takaa, ja he saavuttivat Sidkian Jerikon aroilla. Ja he ottivat hänet kiinni ja veivät hänet Nebukadressarin, Baabelin kuninkaan, eteen Riblaan, joka on Hamatin maassa, ja tämä julisti hänelle tuomion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Ja Baabelin kuningas teurastutti Sidkian pojat Riblassa hänen silmiensä edessä; ja kaikki Juudan ylimykset Baabelin kuningas teurastutti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Sitten hän sokaisutti Sidkian silmät ja kytketti hänet vaskikahleisiin viedäkseen hänet Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Kuninkaan linnan ja kansan talot kaldealaiset polttivat tulella, ja Jerusalemin muurit he repivät maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Ja loput kansasta, jotka olivat jäljellä kaupungissa, sekä ne, jotka olivat menneet hänen puolellensa-loput kansasta, jotka olivat jäljellä-vei Nebusaradan, henkivartijain päällikkö, pakkosiirtolaisuuteen Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Mutta köyhimmät kansasta, joilla ei ollut mitään, Nebusaradan, henkivartijain päällikkö, jätti Juudan maahan ja antoi heille sinä päivänä viinitarhoja ja peltoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Ja Nebukadressar, Baabelin kuningas, oli antanut Nebusaradanille, henkivartijain päällikölle, Jeremiasta tämän käskyn:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, '\"Ota hänet ja pidä hänestä huoli; älä tee hänelle mitään pahaa, vaan tee hänelle niin, kuin hän itse sinulle sanoo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Silloin lähettivät Nebusaradan, henkivartijain päällikkö, Nebusasban, ylimmäinen hoviherra, Neergal-Sareser, ylimmäinen tietäjä, ja kaikki muut Baabelin kuninkaan ylimmäiset');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, '-nämä lähettivät noutamaan Jeremian vankilan pihasta ja antoivat hänet Gedaljalle, Saafanin pojan Ahikamin pojalle, että tämä veisi hänet kotiin, ja niin hän jäi kansan keskuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Jeremialle oli tullut tämä Herran sana hänen ollessaan suljettuna vankilan pihaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, '\"Mene ja sano etiopialaiselle Ebed-Melekille näin: Näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä toteutan sanani tälle kaupungille onnettomuudeksi eikä onneksi; ja tämä tapahtuu sinun edessäsi sinä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Mutta sinut minä pelastan sinä päivänä, sanoo Herra, etkä sinä ole joutuva niiden miesten käsiin, joita sinä pelkäät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Sillä minä pelastan sinut, niin ettet kaadu miekkaan, vaan saat pitää henkesi saaliinasi, koska sinä turvasit minuun, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Sana, joka tuli Jeremialle Herralta, sen jälkeen kuin Nebusaradan, henkivartijain päällikkö, oli päästänyt hänet menemään Raamasta, jonne hän oli haettanut hänet, kun hän oli kahleilla sidottuna kaikkien Baabeliin vietävien Jerusalemin ja Juudan pakkosiirtolaisten joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Henkivartijain päällikkö haetti Jeremian ja sanoi hänelle: \"Herra, sinun Jumalasi, on uhannut tällä onnettomuudella tätä paikkaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'ja Herra on antanut sen tulla ja on tehnyt, niinkuin hän on puhunut; sillä te olette tehneet syntiä Herraa vastaan ettekä ole kuulleet hänen ääntänsä, ja niin on tämä tapahtunut teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Ja katso, nyt minä tänä päivänä päästän sinut kahleista, jotka ovat käsissäsi. Jos näet hyväksi tulla minun kanssani Baabeliin, niin tule, ja minä pidän sinusta huolen. Mutta jos et näe hyväksi tulla minun kanssani Baabeliin, niin älä tule. Katso, koko maa on edessäsi; minne näet hyväksi ja oikeaksi mennä, sinne mene.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Mutta kun tämä vielä viivytteli palaamistaan, sanoi hän: \"Palaa Gedaljan tykö, joka on Saafanin pojan Ahikamin poika, hänen, jonka Baabelin kuningas on asettanut Juudan kaupunkien käskynhaltijaksi, ja jää hänen luoksensa kansan keskuuteen; tahi mene, minne vain näet oikeaksi mennä\". Ja henkivartijain päällikkö antoi hänelle evästä ja lahjoja ja päästi hänet menemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Niin Jeremia meni Gedaljan, Ahikamin pojan, tykö Mispaan ja asui hänen luonaan maahan jääneen kansan keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Kun kaikki sotaväen päälliköt, jotka olivat maaseudulla, he ja heidän miehensä, kuulivat, että Baabelin kuningas oli asettanut Gedaljan, Ahikamin pojan, käskynhaltijaksi maahan ja jättänyt hänen haltuunsa ne miehet, vaimot ja lapset sekä ne maan köyhät, joita ei oltu siirretty Baabeliin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'niin he tulivat Gedaljan luo Mispaan: Ismael, Netanjan poika, Joohanan ja Joonatan, Kaareahin pojat, Seraja, Tanhumetin poika, netofalaisen Eefain pojat ja Jesanja, maakatilaisen poika, he ja heidän miehensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Ja Gedalja, Saafanin pojan Ahikamin poika, vannoi heille ja heidän miehilleen sanoen: \"Älkää peljätkö palvella kaldealaisia; asukaa maassa ja palvelkaa Baabelin kuningasta, niin teidän käy hyvin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Katso, minä itse asun Mispassa palvellakseni niitä kaldealaisia, jotka tulevat meidän luoksemme; mutta te kootkaa viiniä ja hedelmiä ja öljyä ja pankaa astioihinne ja asukaa kaupungeissanne, jotka olette ottaneet haltuunne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Ja kaikki nekin juutalaiset, jotka olivat Mooabissa ja ammonilaisten keskuudessa ja Edomissa sekä kaikissa muissa maissa, saivat kuulla, että Baabelin kuningas oli jättänyt Juudaan jäännöksen ja asettanut näille käskynhaltijaksi Gedaljan, joka oli Saafanin pojan Ahikamin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Ja niin kaikki juutalaiset palasivat takaisin kaikista paikoista, joihin heitä oli karkoitettu, ja tulivat Juudan maahan Mispaan, Gedaljan tykö, ja he korjasivat viiniä ja hedelmiä ylen runsaasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Mutta Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt, jotka olivat maaseudulla, tulivat Gedaljan tykö Mispaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'ja sanoivat hänelle: \"Tiedätkö, että ammonilaisten kuningas Baalis on lähettänyt Ismaelin, Netanjan pojan, lyömään sinut kuoliaaksi?\" Mutta Gedalja, Ahikamin poika, ei uskonut heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Silloin Joohanan, Kaareahin poika, sanoi Gedaljalle Mispassa salaa näin: \"Minäpä menen ja lyön kuoliaaksi Ismaelin, Netanjan pojan, kenenkään tietämättä! Miksi hän saa lyödä sinut kuoliaaksi, niin että kaikki juutalaiset, jotka ovat kokoontuneet sinun luoksesi, hajaantuvat ja Juudan jäännös hukkuu?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Mutta Gedalja, Ahikamin poika, vastasi Joohananille, Kaareahin pojalle: \"Älä tee sitä, sillä sinä puhut valhetta Ismaelista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Mutta seitsemännessä kuussa Ismael, Elisaman pojan Netanjan poika, joka oli kuninkaallista sukua ja kuninkaan ylimmäisiä, tuli Gedaljan, Ahikamin pojan, tykö Mispaan, mukanaan kymmenen miestä. Siellä Mispassa he sitten aterioivat yhdessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Silloin nousi Ismael, Netanjan poika, ynnä ne kymmenen miestä, jotka olivat hänen kanssaan, ja he löivät miekalla kuoliaaksi Gedaljan, joka oli Saafanin pojan Ahikamin poika. Niin Ismael surmasi hänet, jonka Baabelin kuningas oli asettanut käskynhaltijaksi maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Myöskin kaikki juutalaiset, jotka olivat Gedaljan luona Mispassa, sekä kaldealaiset, jotka sieltä tavattiin, sotamiehet, Ismael löi kuoliaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Toisena päivänä, sen jälkeen kuin hän oli surmannut Gedaljan, kun ei kukaan sitä vielä tietänyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'tuli Sikemistä, Siilosta ja Samariasta kahdeksankymmentä miestä, parta ajettuna, vaatteet revittyinä ja iho viileskeltynä, ja heillä oli käsissään ruokauhreja ja suitsutusta, vietäväksi Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Ja Ismael, Netanjan poika, meni Mispasta heitä vastaan, lakkaamatta itkien käydessänsä. Ja kun hän kohtasi heidät, sanoi hän heille: \"Tulkaa Gedaljan, Ahikamin pojan, tykö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Mutta kun he olivat tulleet keskelle kaupunkia, teurastivat heidät Ismael, Netanjan poika, ja ne miehet, jotka olivat hänen kanssaan, ja heittivät heidät kaivoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Mutta heidän joukossaan oli kymmenen miestä, jotka sanoivat Ismaelille: \"Älä surmaa meitä, sillä meillä on kedolla kätkössä nisuja, ohria, öljyä ja hunajaa\". Niin hän herkesi eikä surmannut heitä heidän veljiensä joukkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Ja kaivo, johon Ismael heitti kaikkien niiden miesten ruumiit, jotka hän oli lyönyt kuoliaaksi, samoin kuin Gedaljan, oli se, jonka kuningas Aasa oli teettänyt Baesan, Israelin kuninkaan, hyökkäyksen varalta; sen täytti nyt Ismael, Netanjan poika, murhatuilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Sitten Ismael otti vangeiksi kaikki kansan tähteet, mitä Mispassa oli, kuninkaan tyttäret ja kaiken Mispaan jäljelle jääneen kansan, jonka käskynhaltijaksi Nebusaradan, henkivartijain päällikkö, oli asettanut Gedaljan, Ahikamin pojan-ne Ismael, Netanjan poika, otti vangeiksi ja lähti kulkemaan pois ammonilaisten luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Mutta kun Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt, jotka olivat hänen kanssaan, saivat kuulla kaiken sen pahan, minkä Ismael, Netanjan poika, oli tehnyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'niin he ottivat kaikki miehensä ja lähtivät taistelemaan Ismaelia, Netanjan poikaa, vastaan; ja he tapasivat hänet suuren vesilammikon luona, joka on Gibeonissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Mutta kun kaikki kansa, joka oli Ismaelin mukana, näki Joohananin, Kaareahin pojan, ja kaikki sotaväen päälliköt, jotka olivat hänen kanssaan, niin he ihastuivat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'ja kaikki kansa, jonka Ismael oli ottanut vangiksi Mispasta, kääntyi takaisin ja meni Joohananin, Kaareahin pojan, puolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Mutta Ismael, Netanjan poika, pääsi kahdeksan miehen kanssa Joohanania pakoon ja lähti ammonilaisten luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Ja Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt, jotka olivat hänen kanssaan, ottivat kaikki kansan tähteet, jotka hän oli palauttanut Ismaelin, Netanjan pojan, tyköä Mispasta, sen jälkeen kuin tämä oli lyönyt Gedaljan, Ahikamin pojan, kuoliaaksi: miehiä, sotilaita, naisia ja lapsia ja hoviherroja, jotka hän oli palauttanut Gibeonista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Ja he kulkivat, mutta pysähtyivät Kimhamin majapaikkaan, joka on lähellä Beetlehemiä, lähteäkseen sitten Egyptiin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'kaldealaisia pakoon, sillä he pelkäsivät heitä, koska Ismael, Netanjan poika, oli lyönyt kuoliaaksi Gedaljan, Ahikamin pojan, jonka Baabelin kuningas oli asettanut käskynhaltijaksi maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Silloin astuivat esiin kaikki sotaväen päälliköt ja Joohanan, Kaareahin poika, ja Jesanja, Hoosajan poika, ynnä kaikki kansa, pienimmästä suurimpaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'ja sanoivat profeetta Jeremialle: \"Langetkoon rukouksemme sinun eteesi, ja rukoile puolestamme Herraa, Jumalaasi, kaiken tämän jäännöksen puolesta; sillä suuresta luvusta on meitä jäänyt jäljelle vähän, niinkuin omat silmäsi näkevät meitä olevan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Ja Herra, sinun Jumalasi, ilmoittakoon meille, mitä tietä meidän on kuljettava, ja mitä meidän on tehtävä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Silloin profeetta Jeremia vastasi heille: \"Minä kuulen. Katso, minä rukoilen Herraa, teidän Jumalaanne, niinkuin sanotte, ja kaiken sen, mitä Herra teille vastaa, minä ilmoitan teille; en salaa teiltä mitään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Ja he sanoivat Jeremialle: \"Olkoon Herra totinen ja luotettava todistaja meitä vastaan, jollemme tee aivan sen sanan mukaan, jonka Herra, sinun Jumalasi, lähettää sinut meille tuomaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Olkoon se hyvä tahi paha: Herran ääntä, meidän Jumalamme, jonka tykö me sinut lähetämme, me tottelemme, että meidän hyvin kävisi, kun tottelemme Herran, meidän Jumalamme, ääntä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Kymmenen päivän kuluttua tuli Herran sana Jeremialle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'ja hän kutsui Joohananin, Kaareahin pojan, ja kaikki sotaväen päälliköt, jotka olivat tämän kanssa, ynnä kaiken kansan, pienimmästä suurimpaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'Ja hän sanoi heille: \"Näin sanoo Herra, Israelin Jumala, jonka tykö te lähetitte minut laskemaan rukouksenne hänen eteensä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Jos te jäätte tähän maahan, niin minä rakennan teidät enkä hajota maahan, istutan teidät enkä revi pois, sillä minä kadun sitä onnettomuutta, jonka olen tuottanut teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Älkää peljätkö Baabelin kuningasta, jota te nyt pelkäätte. Älkää peljätkö häntä, sanoo Herra; sillä minä olen teidän kanssanne, minä autan teitä ja pelastan teidät hänen käsistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Ja minä annan teille armon, niin että hän teitä armahtaa ja antaa teidän palata takaisin maahanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Mutta jos te sanotte: \'Me emme jää tähän maahan\', ettekä tottele Herran, teidän Jumalanne, ääntä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'vaan sanotte: \'Ei! Me lähdemme Egyptiin, jossa meidän ei tarvitse nähdä sotaa, ei kuulla pasunan ääntä eikä kärsiä leivän nälkää, ja sinne me jäämme asumaan\' -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'niin kuulkaa siis nyt Herran sana, te Juudan tähteet: Näin sanoo Herra Sebaot, Israelin Jumala: Jos te todella käännätte kasvonne Egyptiä kohti ja menette sinne asumaan muukalaisina,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'niin miekka, jota te pelkäätte, on saavuttava teidät siellä Egyptin maassa, ja nälkä, joka teitä huolettaa, seuraa kintereillänne Egyptiin, ja sinne te kuolette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Ja kaikki ne miehet, jotka kääntävät kasvonsa Egyptiä kohti asuakseen siellä muukalaisina, kuolevat miekkaan, nälkään ja ruttoon, eikä ainoakaan heistä pääse pakoon eikä pelastu siitä onnettomuudesta, jonka minä annan heille tulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Niinkuin minun vihani ja kiivastukseni on vuodatettu Jerusalemin asukasten ylitse, niin minun kiivastukseni on vuotava teidän ylitsenne, jos te menette Egyptiin, ja te tulette kiroukseksi ja kauhistukseksi, kiroussanaksi ja häväistykseksi ettekä enää saa nähdä tätä paikkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Herra sanoo teille, te Juudan tähteet: Älkää menkö Egyptiin.\" Se tietäkää, että minä olen tänä päivänä teitä varoittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Te eksytitte itsenne, kun lähetitte minut Herran, teidän Jumalanne, tykö sanoen: \"Rukoile puolestamme Herraa, meidän Jumalaamme; ja kaikki, mitä Herra, meidän Jumalamme, sanoo, ilmoita meille, niin me teemme sen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Minä olen sen tänä päivänä teille ilmoittanut, mutta te olette tottelemattomat Herran, teidän Jumalanne, äänelle kaikessa, mitä varten hän on lähettänyt minut teidän tykönne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Nyt siis tietäkää, että te kuolette miekkaan, nälkään ja ruttoon siinä paikassa, johon te haluatte mennä, siellä muukalaisina asumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Mutta kun Jeremia oli loppuun asti puhunut kaikelle kansalle kaikki Herran, heidän Jumalansa, sanat, jotka Herra, heidän Jumalansa, oli lähettänyt hänet tuomaan heille-kaikki ne sanat, -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'niin Asarja, Hoosajan poika, ja Joohanan, Kaareahin poika, ja kaikki julkeat miehet sanoivat Jeremialle: \"Sinä puhut valhetta; Herra, meidän Jumalamme, ei ole lähettänyt sinua sanomaan: \'Älkää menkö Egyptiin, siellä muukalaisina asumaan\';');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'vaan Baaruk, Neerian poika, kiihoittaa sinua meitä vastaan antaakseen meidät kaldealaisten käsiin tapettaviksi tai vietäviksi pakkosiirtolaisuuteen Baabeliin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Ja Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt ja kaikki kansa olivat tottelemattomat Herran äänelle eivätkä jääneet Juudan maahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'niin Joohanan, Kaareahin poika, ja kaikki sotaväen päälliköt ottivat kaikki Juudan tähteet, jotka olivat kaikista kansakunnista, jonne heidät oli karkoitettu, palanneet asumaan Juudan maahan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'miehet, naiset ja lapset, kuninkaan tyttäret ja kaiken sen väen, jonka Nebusaradan, henkivartijain päällikkö, oli jättänyt Gedaljan huostaan, joka oli Saafanin pojan Ahikamin poika, sekä profeetta Jeremian ja Baarukin, Neerian pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'Ja he menivät Egyptin maahan, sillä he eivät kuulleet Herran ääntä. Ja niin he tulivat Tahpanheeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Ja tämä Herran sana tuli Jeremialle Tahpanheessa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, '\"Ota käsiisi suuria kiviä ja kätke ne muurilaastiin, tiilikivipenkereeseen, joka on faraon linnan oven edustalla Tahpanheessa, juutalaisten miesten nähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'Ja sano heille: Näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä lähetän hakemaan palvelijani Nebukadressarin, Baabelin kuninkaan, ja asetan hänen valtaistuimensa näiden kivien päälle, jotka minä olen kätkenyt, ja hän on levittävä loistomattonsa niiden yli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Ja hän tulee ja lyö Egyptin maata: joka ruton oma, se ruttoon, joka vankeuden, se vankeuteen, joka miekan, se miekkaan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Ja minä sytytän Egyptin jumalien temppelit tuleen, ja hän polttaa ne ja vie jumalat pois saaliinansa. Ja hän puhdistaa Egyptin maan syöpäläisistä, niinkuin paimen puhdistaa vaatteensa syöpäläisistä, ja lähtee sieltä vammatonna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Ja hän murskaa patsaat Egyptin maan Beet-Semeksestä, ja Egyptin jumalien temppelit hän polttaa tulella.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Sana, joka tuli Jeremialle kaikkia niitä juutalaisia vastaan, jotka asuivat Egyptin maassa, asuivat Migdolissa, Tahpanheessa, Noofissa ja Patroksen maakunnassa; se kuului:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, '\"Näin sanoo Herra Sebaot, Israelin Jumala: Te olette nähneet kaiken sen onnettomuuden, jonka minä olen antanut tulla Jerusalemille ja kaikille Juudan kaupungeille. Katso, ne ovat nyt raunioina, eikä niissä asukasta ole,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'heidän pahuutensa tähden, jota he tekivät, vihoittaen minut, kun menivät ja polttivat uhreja muille jumalille, palvelivat niitä, joita he eivät tunteneet, eivät he ettekä te eivätkä teidän isänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Ja varhaisesta alkaen minä lähetin teidän tykönne kaikki palvelijani, profeetat, sanomaan: \'Älkää tehkö näitä kauhistuksia, joita minä vihaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Mutta he eivät kuulleet, eivät korvaansa kallistaneet, niin että olisivat kääntyneet pois pahuudestansa ja lakanneet polttamasta uhreja muille jumalille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Ja niin vuoti minun kiivastukseni ja vihani alas ja paloi Juudan kaupungeissa ja Jerusalemin kaduilla, ja ne tulivat raunioiksi, autioiksi, niinkuin ne tänä päivänä ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Ja nyt sanoo Herra, Jumala Sebaot, Israelin Jumala, näin: Miksi tuotatte itsellenne suuren onnettomuuden, hävitätte miehet ja vaimot, lapset ja imeväiset Juudasta, niin ettette jätä itsestänne jäännöstäkään?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Te vihoitatte minut kättenne töillä, kun poltatte uhreja muille jumalille Egyptin maassa, johon te olette tulleet, täällä muukalaisina asumaan. Niin te tuotatte itsellenne häviön ja tulette kiroussanaksi ja häväistykseksi kaikissa maan kansoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Oletteko unhottaneet isäinne pahat teot ja Juudan kuningasten pahat teot ja heidän vaimojensa pahat teot, omat pahat tekonne ja vaimojenne pahat teot, mitä he ovat tehneet Juudan maassa ja Jerusalemin kaduilla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'He eivät ole murtuneet tähän päivään asti, eivät pelkää, eivät vaella minun lakini ja minun käskyjeni mukaan, jotka minä olen antanut teille ja teidän isillenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Sentähden, näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä käännän kasvoni teitä vastaan onnettomuudeksi, hävittääkseni koko Juudan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Ja minä tempaan pois Juudan jäännöksen, ne jotka käänsivät kasvonsa Egyptin maata kohti mennäkseen siellä muukalaisina asumaan, ja he hukkuvat kaikki. Egyptin maassa he kaatuvat miekkaan, hukkuvat nälkään, pienimmästä suurimpaan asti he kuolevat miekkaan ja nälkään; ja he tulevat kiroukseksi ja kauhistukseksi, kiroussanaksi ja häväistykseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Ja minä rankaisen niitä, jotka asuvat Egyptin maassa, niinkuin minä rankaisin Jerusalemia, miekalla, nälällä ja rutolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Ei jää pakoonpäässeitä, ei pelastuneita Juudan jäännöksestä, niistä, jotka ovat tulleet asumaan muukalaisina täällä Egyptin maassa, eivätkä he palaa Juudan maahan, jonne heidän sielunsa halajaa jälleen, heidän siellä asuaksensa; sillä sinne on palaava vain muutamia pakolaisia.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Mutta kaikki miehet, jotka tiesivät vaimojensa polttavan uhreja muille jumalille, ja kaikki naiset, jotka seisoivat siellä suurena joukkona, ja kaikki kansa, joka asui Egyptin maassa, Patroksessa, vastasivat Jeremialle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, '\"Mitä sinä olet Herran nimessä meille puhunut, siinä me emme sinua tottele;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'vaan me täytämme joka lupauksen, mikä suustamme on lähtenyt, poltamme uhreja taivaan kuningattarelle ja vuodatamme hänelle juomauhreja, niinkuin teimme me ja meidän isämme, meidän kuninkaamme ja ruhtinaamme Juudan kaupungeissa ja Jerusalemin kaduilla; ja silloin meillä oli leipää yltäkyllin, ja meidän oli hyvä olla emmekä nähneet onnettomuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Mutta siitä asti, kun me lakkasimme polttamasta uhreja taivaan kuningattarelle ja vuodattamasta hänelle juomauhreja, on osanamme ollut kaiken puute ja hukkuminen miekkaan ja nälkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Ja kun me poltamme uhreja taivaan kuningattarelle ja vuodatamme hänelle juomauhreja, niin miestemme luvattako teemme hänelle uhrikakkuja, hänen kuvansa muotoisia, ja vuodatamme hänelle juomauhreja?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Silloin Jeremia sanoi kaikelle kansalle, miehille ja naisille, kaikelle kansalle, joka oli hänelle näin vastannut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, '\"Eikö sitä uhrisavua, jota te olette suitsuttaneet Juudan kaupungeissa ja Jerusalemin kaduilla, te ja teidän isänne, teidän kuninkaanne ja ruhtinaanne ja maan kansa, Herra muista ja pidä mielessänsä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Eikä Herra voinut sitä enää kärsiä teidän tekojenne pahuuden tähden, kauhistusten tähden, joita te teitte, ja niin teidän maanne tuli raunioiksi ja autioksi ja kiroussanaksi, tuli asujattomaksi, niinkuin se tänä päivänä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Sentähden että te poltitte uhreja ja teitte syntiä Herraa vastaan, ette totelleet Herran ääntä ettekä vaeltaneet hänen lakinsa, käskyjensä ja säädöksiensä mukaan, sentähden tämä onnettomuus on kohdannut teitä, niinkuin nyt on tapahtunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Jeremia sanoi vielä kaikelle kansalle ja kaikille naisille: \"Kuulkaa Herran sana, kaikki Juuda, joka olet Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Näin sanoo Herra Sebaot, Israelin Jumala: Mitä te ja teidän vaimonne olette suullanne puhuneet, sen te panette käsillänne täytäntöön, sanoen: \'Me täytämme lupauksemme, joilla olemme luvanneet polttaa uhreja taivaan kuningattarelle ja vuodattaa hänelle juomauhreja\'. Niinpä pitäkää lupauksenne, pankaa lupauksenne täytäntöön!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Sentähden kuulkaa Herran sana, kaikki Juuda, te jotka asutte Egyptin maassa: Katso, minä vannon suuren nimeni kautta, sanoo Herra: Totisesti, ei ole ainoakaan Juudan mies enää mainitseva suullaan minun nimeäni, niin että sanoisi: \'Niin totta kuin Herra, Herra elää\' -ei koko Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Katso, minä valvon, mutta heille onnettomuudeksi, ei onneksi; ja jokainen Juudan mies, joka on Egyptin maassa, on hukkuva miekkaan ja nälkään, kunnes heistä on tullut loppu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Vain vähäinen joukko miekasta pelastuneita on palajava Egyptin maasta Juudan maahan; ja Juudan koko jäännös, ne jotka tulivat Egyptin maahan, siellä muukalaisina asumaan, tulevat tietämään, kumpaisenko sana toteutuu, minun vai heidän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Ja tämä on oleva sen merkkinä, sanoo Herra, että minä rankaisen teitä tässä paikassa, tietääksenne, että minun sanani teitä vastaan toteutuvat, teille onnettomuudeksi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Näin sanoo Herra: Katso, minä annan farao Hofran, Egyptin kuninkaan, hänen vihollistensa käsiin, niiden käsiin, jotka etsivät hänen henkeänsä, niinkuin minä olen antanut Sidkian, Juudan kuninkaan, Nebukadressarin, Baabelin kuninkaan, käsiin, joka oli hänen vihollisensa ja etsi hänen henkeänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Sana, jonka profeetta Jeremia puhui Baarukille, Neerian pojalle, kun tämä kirjoitti nämä sanat kirjaan Jeremian suusta Juudan kuninkaan Joojakimin, Joosian pojan, neljäntenä hallitusvuotena; se kuului:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, '\"Näin sanoo Herra, Israelin Jumala, sinusta, Baaruk:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Sinä sanot: \'Voi minua! Sillä Herra on antanut minulle murhetta kipuni lisäksi; minä olen uupunut huokaamisestani enkä lepoa löydä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Sano hänelle näin: Näin sanoo Herra: Katso, minkä olen rakentanut, sen minä hajotan, ja minkä olen istuttanut, sen minä revin irti; ja tämä kohtaa koko maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Sinä pyydät itsellesi suuria! Älä pyydä; sillä katso, minä tuotan onnettomuuden kaikelle lihalle, sanoo Herra. Mutta sinulle minä annan henkesi saaliiksi, mihin paikkaan sinä menetkin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Herran sana, joka tuli profeetta Jeremialle pakanakansoja vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Egyptiä vastaan: Farao Nekon, Egyptin kuninkaan, sotajoukkoa vastaan, joka oli Eufrat-virran rannalla Karkemiissa ja jonka Nebukadressar, Baabelin kuningas, voitti Juudan kuninkaan Joojakimin, Joosian pojan, neljäntenä hallitusvuotena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, '\"Varustakaa pienet ja suuret kilvet, käykää tänne taisteluun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Valjastakaa hevoset, nouskaa ratsujen selkään, käykää esiin kypärit päässä. Kiilloittakaa keihäät, pukekaa yllenne rintahaarniskat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Miksi minä näen heidän peljästyvän, peräytyvän? Heidän sankarinsa sortuvat. He syöksyvät pakoon eivätkä käänny; kauhistus on kaikkialla, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Ei pääse nopea pakoon, ei sankari pelastu; pohjan puolella, Eufrat-virran vierellä he kompastuvat ja kaatuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Kuka on tuo, joka nousee niinkuin Niilivirta, jonka vedet vyöryvät kuin virrat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Egypti nousee niinkuin Niilivirta, sen vedet vyöryvät kuin virrat; se sanoo: \'Minä nousen ja peitän maan, hävitän kaupungin ja siinä asuvaiset\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Hyökätkää, hevoset, ajakaa hurjasti, vaunut! Lähtekööt liikkeelle sankarit, etiopialaiset ja puutilaiset, kilven käyttäjät, ja luudilaiset, jousen käyttäjät, jousen jännittäjät!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Tämä päivä on Herran, Herran Sebaotin, päivä, koston päivä, jona hän kostaa vihollisillensa; miekka syö ja tulee kylläiseksi, juopuu heidän verestänsä, kun Herralla, Herralla Sebaotilla, on uhriteurastus pohjoisessa maassa, Eufrat-virran varrella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Mene Gileadiin, hae balsamia, sinä neitsyt, tytär Egypti-turhaan sinä paljon lääkkeitä hankit: ei kasva haavasi umpeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Kansat kuulevat sinun häpeäsi, ja sinun valitushuutosi täyttää maan, sillä sankari kompastuu sankariin, yhdessä he kaatuvat molemmat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Tämä on se sana, jonka Herra puhui profeetta Jeremialle, ilmoittaen Nebukadressarin, Baabelin kuninkaan, tulevan lyömään Egyptin maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, '\"Julistakaa Egyptissä ja kuuluttakaa Migdolissa, kuuluttakaa Noofissa ja Tahpanheessa, ja sanokaa: \'Astu esiin, ole valmis, sillä miekka syö sinun ympärilläsi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Miksi ovat sinun urhosi maahan syöstyt? He eivät pysyneet pystyssä, sillä Herra heidät nujersi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Hän saattoi monet kompastumaan, ja he kaatuivat toinen toisensa päälle ja sanoivat: \'Nouse! Palatkaamme kansamme luo ja synnyinmaahamme hävittäjän miekkaa pakoon.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Siellä huudetaan: \'Farao, Egyptin kuningas, on hukassa! Hän on lyönyt laimin aikansa.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Niin totta kuin minä elän, sanoo kuningas-Herra Sebaot on hänen nimensä: hän tulee, hän joka on kuin Taabor vuorten joukossa, kuin merestä ylenevä Karmel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Tee itsellesi matkavarusteet, sinä valtiatar, tytär Egypti; sillä Noof tulee autioksi, hävitetään asujattomaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Kaunis hieho on Egypti. Paarma tulee, tulee pohjoisesta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Palkkasoturitkin, jotka sillä on keskellänsä, nuo syöttövasikkain kaltaiset, nekin kääntyvät pakoon kaikki tyynni: he eivät kestä; sillä heidän hätänsä päivä on tullut heidän päällensä, heidän rangaistuksensa aika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Se sähisee kuin käärme mennessänsä, sillä ne tulevat sotavoimilla ja käyvät sen kimppuun kirveillä, niinkuin puiden hakkaajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'He kaatavat siltä metsän, sanoo Herra, tuon määrättömän suuren, sillä heitä on enemmän kuin heinäsirkkoja, he ovat lukemattomat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Häpeään joutuu tytär Egypti, hänet annetaan pohjoisen kansan käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Herra Sebaot, Israelin Jumala, sanoo: Katso, minä rankaisen Aamonia, joka on Noossa, niin myös faraota ja Egyptiä, sen jumalia ja sen kuninkaita, sekä faraota että niitä, jotka häneen turvaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Ja minä annan heidät niiden käsiin, jotka etsivät heidän henkeänsä, Nebukadressarin, Baabelin kuninkaan, käsiin ja hänen palvelijainsa käsiin. Mutta sen jälkeen siellä asutaan niinkuin muinaisina aikoina, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Mutta sinä, minun palvelijani Jaakob, älä pelkää, älä säiky, Israel. Sillä katso, minä pelastan sinut kaukaisesta maasta, sinun jälkeläisesi heidän vankeutensa maasta. Ja Jaakob on palajava, elävä rauhassa ja turvassa, kenenkään peljättämättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Sinä, minun palvelijani Jaakob, älä pelkää, sanoo Herra, sillä minä olen sinun kanssasi. Minä teen lopun kaikista kansoista, joiden sekaan minä olen sinut karkoittanut; mutta sinusta minä en loppua tee: minä kuritan sinua kohtuudella, mutta rankaisematta minä en sinua jätä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Herran sana filistealaisia vastaan, joka tuli profeetta Jeremialle, ennenkuin farao valloitti Gassan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, '\"Näin sanoo Herra: Katso, vedet nousevat pohjoisesta, ja niistä tulee tulvavirta; ne tulvivat yli maan ja kaiken, mitä siinä on, yli kaupungin ja siinä asuvaisten. Ja ihmiset huutavat, kaikki maan asukkaat valittavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Kun kuuluu hänen orhiensa kavioitten töminä, hänen vaunujensa jyrinä, hänen rattaittensa ryske, eivät isät käänny lapsiansa auttamaan, sillä hervottomat ovat heidän kätensä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'päivän tähden, joka tulee ja tuhoaa kaikki filistealaiset, hävittää Tyyrolta ja Siidonilta kaikki auttajat, mitä jäljellä on; sillä Herra on tuhoava filistealaiset, mitä on tähteenä Kaftorin saarelta tulleista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Kaljuksi tullut on Gassa, hävitetty on Askelon, se mitä oli jäljellä heidän laaksossansa. Kuinka kauan sinä ihoasi viileskelet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Voi, Herran miekka! Milloinka vihdoinkin lepäät? Mene takaisin tuppeesi, taltu ja ole hiljaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Mutta kuinka saisi se levätä, kun Herra on sille käskyn antanut? Askelonia ja meren rantaa vastaan hän on sen asettanut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Mooabia vastaan. Näin sanoo Herra Sebaot, Israelin Jumala: \"Voi Neboa, sillä se on hävitetty! Häpeään joutunut, valloitettu on Kirjataim, häpeään joutunut, kauhistunut on linnoitus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Mennyt on Mooabin maine, Hesbonissa hankitaan sille pahaa: \'Tulkaa, hävittäkäämme se kansojen luvusta\'. Myöskin sinä, Madmena, kukistut, miekka on sinun kintereilläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Kuule! Huuto Hooronaimista! Tuho ja suuri hävitys!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Hävitetty on Mooab, sen pienokaisten parku kuuluu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Luuhitin solatietä noustaan itkien, Hooronaimin rinteeltä kuuluu tuskan huuto hävityksen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Paetkaa, pelastakaa henkenne ja olkaa kuin alaston puu erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Sillä koska sinä turvaat omiin töihisi ja aarteisiisi, niin sinutkin valloitetaan, ja Kemos lähtee pakkosiirtolaisuuteen ja hänen pappinsa ja ruhtinaansa hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Hävittäjä tulee jokaiseen kaupunkiin, ei pelastu yksikään kaupunki; laakso hävitetään ja tasanko tuhotaan, niinkuin Herra on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Antakaa siivet Mooabille, sillä lentämällä on hänen lähdettävä pois. Hänen kaupunkinsa tulevat autioiksi, niin ettei niissä yhtään asukasta ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Kirottu olkoon se, joka Herran työn laiskasti tekee, kirottu olkoon se, joka pidättää miekkansa verestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Surutonna on Mooab ollut nuoruudestaan asti ja levännyt rauhassa sakkansa päällä; ei sitä ole tyhjennetty astiasta astiaan, eikä se ole pakkosiirtolaisuuteen vaeltanut. Sentähden siihen on jäänyt sen oma maku, eikä sen haju ole muuttunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Sentähden, katso, päivät tulevat, sanoo Herra, jolloin minä lähetän sille viininlaskijat, jotka sen laskevat ja tyhjentävät sen astiat ja rikkovat sen leilit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Ja Mooab joutuu häpeään Kemoksen tähden, niinkuin Israelin heimo joutui häpeään Beetelin tähden, johon se turvasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Kuinka te sanotte: \'Me olemme sankareita ja aimomiehiä taisteluun\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Mooab hävitetään, sen kaupunkeihin hyökätään, ja sen valionuorukaiset vaipuvat teurastettaviksi, sanoo kuningas-Herra Sebaot on hänen nimensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Lähellä, tulossa on Mooabin turmio, sen onnettomuus kiiruhtaa kovin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Surkutelkaa sitä, kaikki sen naapurit, kaikki, jotka tunnette sen nimen. Sanokaa: \'Voi, kuinka onkaan murrettu voiman valtikka, kunnian sauva!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Astu alas kunniasta ja istu janoiseen erämaahan, sinä valtiatar, tytär Diibon; sillä Mooabin hävittäjä hyökkää sinun kimppuusi, kukistaa sinun linnoituksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Seiso tiellä ja tähystele, sinä Aroerin asukas; kysy pakolaisilta ja pelastuneilta, sano: \'Mitä on tapahtunut?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Häpeään on joutunut Mooab, sillä se on kukistettu. Valittakaa ja huutakaa, julistakaa Arnonin äyräillä, että Mooab on hävitetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Tuomio on tullut tasangon maalle, Hoolonille, Jahaalle ja Meefaatille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'Diibonille, Nebolle ja Beet-Diblataimille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'Kirjataimille, Beet-Gaamulille ja Beet-Meonille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'Kerijotille, Bosralle ja kaikille Mooabin maan kaupungeille, kaukaisille ja läheisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Katkaistu on Mooabin sarvi ja murskattu hänen käsivartensa, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Juovuttakaa hänet, sillä hän on ylpeillyt Herraa vastaan, niin että Mooab suistuu omaan oksennukseensa ja tulee nauruksi hänkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Vai eikö Israel ollut sinulle nauruksi? Onko hänet tavattu varasten joukosta, koska sinä, milloin vain hänestä puhuit, pudistit päätäsi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Jättäkää kaupungit ja asukaa kallioilla, te Mooabin asukkaat, ja olkaa kuin kyyhkynen, joka tekee pesänsä ammottavan kuilun taakse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Me olemme kuulleet Mooabin ylpeilyn, tuon ylen ylpeän, hänen korskeutensa, ylpeilynsä ja kopeilunsa ja hänen sydämensä pöyhkeyden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Minä tunnen, sanoo Herra, hänen vihansa ja hänen väärät puheensa; väärin he ovat tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Siksi minä valitan Mooabin tähden, koko Mooabin tähden minä huudan; Kiir-Hereksen miesten tähden huokaillaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Enemmän kuin Jaeser itkee, itken minä sinua, Sibman viinipuu; sinun köynnöksesi menivät yli meren, ulottuivat Jaeserin mereen asti. Sinun hedelmän-ja viininkorjuusi keskeen on hävittäjä hyökännyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Ilo ja riemu on tauonnut hedelmätarhoista ja Mooabin maasta. Viinin minä olen lopettanut viinikuurnista; ei poljeta enää viiniä ilohuudoin, ilohuuto ei ole enää ilohuuto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Hesbonin parku kuuluu Elaleen, Jahaaseen asti, he antavat äänensä kuulua Sooarista Hooronaimiin, Eglat-Selisijjaan asti, sillä Nimrimin vedet ehtyvät erämaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Minä lopetan Mooabista, sanoo Herra, kukkuloilla-uhraajat, ne, jotka polttavat uhreja jumalillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Siksi minun sydämeni väräjää Mooabin tähden niinkuin huilu, minun sydämeni väräjää Kiir-Hereksen miesten tähden niinkuin huilu, sillä mennyttä on heidän hankkimansa säästö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Kaikki päät ovat paljaiksi ajellut ja kaikki parrat leikatut, kaikki kädet viileskellyt, ja lanteilla on säkit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Kaikilla Mooabin katoilla ja toreilla on pelkkää valitusta, sillä minä olen murskannut Mooabin kuin kelpaamattoman astian, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Kuinka se on kauhuissansa! Valittakaa! Kuinka Mooab kääntyikään selin ja häpesi! Mooab on tullut nauruksi ja kauhuksi kaikille naapureilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Sillä näin sanoo Herra: Katso, kotkan kaltainen liitää siivet levällään Mooabia kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kerijot valloitetaan ja vuorilinnoitukset vallataan; sinä päivänä on Mooabin sankarien sydän niinkuin synnytystuskissa olevan vaimon sydän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Ja Mooab hävitetään kansojen luvusta, sillä se on ylpeillyt Herraa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Kauhu ja kuoppa ja paula on edessäsi, sinä Mooabin asukas, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Joka pakenee kauhua, se putoaa kuoppaan, ja joka kuopasta nousee, se puuttuu paulaan; sillä minä tuotan Mooabille heidän rangaistusvuotensa, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Hesbonin varjossa seisovat pakolaiset voimaa vailla. Sillä tuli lähti Hesbonista, liekki Siihonin vaiheilta; ja se kulutti Mooabin ohimon ja melskeen miesten päälaen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Voi sinua, Mooab! Hukkunut on Kemoksen kansa, sillä sinun poikasi ovat vangeiksi otetut ja tyttäresi viedyt vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Mutta minä käännän Mooabin kohtalon aikojen lopulla, sanoo Herra.\" Tähän asti Mooabin tuomiosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Ammonilaisia vastaan. Näin sanoo Herra: \"Eikö Israelilla olekaan lapsia, tahi eikö hänellä ole perillistä? Miksi Malkam on perinyt Gaadin ja hänen kansansa asettunut sen kaupunkeihin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Sentähden, katso, päivät tulevat, sanoo Herra, jolloin minä annan sotahuudon kuulua ammonilaisten Rabbaa vastaan, ja siitä on tuleva rauniokumpu, autio, ja sen tytärkaupungit tulessa palavat. Silloin Israel on perivä perijänsä, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Valita, Hesbon, sillä Ai on hävitetty; huutakaa, te Rabban tyttäret, kääriytykää säkkeihin, pitäkää valittajaiset ja harhailkaa ympäri karjatarhoissa, sillä Malkam menee pakkosiirtolaisuuteen ja hänen pappinsa ja ruhtinaansa hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Miksi kerskaat laaksoistasi, laaksosi yltäkylläisyydestä, sinä luopiotytär, joka luotat aarteisiisi sanoen: \'Kuka käy minun kimppuuni?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Katso, minä tuotan sinulle peljätyksen joka taholta, sanoo Herra, Herra Sebaot, ja teidät karkoitetaan, mikä minnekin, eikä ole pakenevilla kokoajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Mutta sen jälkeen minä käännän ammonilaisten kohtalon, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Edomia vastaan. Näin sanoo Herra Sebaot: \"Eikö ole enää viisautta Teemanissa? Loppunut on ymmärtäväisiltä neuvo, rauennut heidän viisautensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Paetkaa, kääntykää, piiloutukaa syvälle, te Dedanin asukkaat; sillä minä tuotan Eesaulle turmion, hänen rangaistuksensa ajan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Jos viininkorjaajat käyvät kimppuusi, eivät he jälkikorjuuta jätä; jos varkaat tulevat yöllä, hävittävät he tarpeeksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Sillä minä paljastan Eesaun, tuon ilmi hänen kätkönsä, eikä hän voi lymytä; hänen lapsensa, veljensä ja naapurinsa hävitetään, niin ettei häntä enää ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Jätä orposi minun elätettävikseni, ja sinun leskesi turvatkoot minuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Sillä näin sanoo Herra: Katso, niidenkin, jotka eivät ole vikapäät siitä maljasta juomaan, täytyy siitä juoda; ja sinäkö jäisit rankaisematta? Sinä et jää rankaisematta, vaan sinun täytyy juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Sillä minä olen vannonut itse kauttani, sanoo Herra, että Bosra on tuleva kauhistukseksi, häpeäksi, tyrmistykseksi ja kiroussanaksi, ja kaikki sen tytärkaupungit tulevat ikuisiksi raunioiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Minä olen kuullut sanoman Herralta, ja sanansaattaja on lähetetty kansakuntiin: \"Kokoontukaa ja käykää sitä vastaan ja nouskaa sotaan\". -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, '\"Sillä katso, minä teen sinut vähäiseksi kansojen seassa, ylenkatsotuksi ihmisten kesken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Sinun peljättävyytesi, sinun sydämesi ylpeys on pettänyt sinut, joka asut kallionrotkoissa, vallitset kukkulain korkeudet. Vaikka tekisit pesäsi korkealle niinkuin kotka, minä syöksen sinut sieltä alas, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Ja Edom tulee kauhistukseksi; jokainen, joka ohitse kulkee, kauhistuu ja viheltää kaikille sen haavoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Niinkuin oli silloin, kun Sodoma ja Gomorra ja niiden naapurit hävitettiin, sanoo Herra, niin ei sielläkään ole kenkään asuva, ei yksikään ihmislapsi oleskeleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Katso, niinkuin leijona karkaa Jordanin rantatiheiköstä lakastumattomalle laitumelle, niin minä äkisti karkoitan heidät sieltä pois. Ja hänet, joka valittu on, minä asetan sinne kaitsijaksi. Sillä kuka on minun vertaiseni, ja kuka vetää minut tilille? Ja kuka on se paimen, joka voi kestää minun edessäni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Sentähden kuulkaa Herran päätös, jonka hän on päättänyt Edomia vastaan, ja hänen aivoituksensa, jotka hän on aivoitellut Teemanin asukkaita vastaan: Totisesti, ne raastetaan pois, nuo lauman vähäiset; totisesti, niiden laidun kauhistuu niiden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Heidän sortumisensa pauhusta vapisee maa; huudetaan, niin että ääni kuuluu Kaislamerelle asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Katso, kotkan kaltainen kohoaa ja liitää siivet levällään Bosraa kohti; sinä päivänä on Edomin sankarien sydän niinkuin synnytystuskissa olevan vaimon sydän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Damaskoa vastaan. \"Hamat ja Arpad joutuvat häpeään, sillä he kuulevat pahan sanoman, he menehtyvät pelkoon-levottomuus kuin meressä, joka ei voi tyyntyä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damasko lannistuu, kääntyy pakoon, hirmu on sen vallannut; sitä kouristaa ahdistus ja tuska niinkuin synnyttäväistä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Kuinka hyljätty onkaan ylistetty kaupunki, minun iloni kaupunki!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Sentähden sen nuorukaiset kaatuvat sen kaduilla, ja kaikki sotamiehet saavat surmansa sinä päivänä, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Ja minä sytytän Damaskon muurit tuleen, ja se on kuluttava Benhadadin palatsit.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Keedaria ja Haasorin valtakuntia vastaan, jotka Nebukadressar, Baabelin kuningas, voitti. Näin sanoo Herra: \"Nouskaa, käykää Keedarin kimppuun ja hävittäkää Idän miehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Heidän majansa ja lampaansa otetaan pois, heidän telttansa ja kaikki heidän tavaransa ja heidän kamelinsa viedään heiltä, ja heistä huudetaan: \'Kauhistus kaikkialta!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Lähtekää pakoon, paetkaa nopeasti, piiloutukaa syvälle, te Haasorin asukkaat, sanoo Herra, sillä Nebukadressar, Baabelin kuningas, on päättänyt teistä päätöksen, on pitänyt neuvoa teitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Nouskaa, käykää kansan kimppuun, joka asuu rauhassa ja turvallisena, sanoo Herra; ei ole sillä ovia eikä salpoja, he asuvat yksinänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Ja heidän kamelinsa joutuvat ryöstettäviksi ja heidän karjansa paljous saaliiksi; ja minä hajotan heidät kaikkiin tuuliin, nuo päälaen ympäriltä kerityt, ja joka puolelta minä tuotan heille turmion, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Ja Haasor tulee aavikkosutten asunnoksi, autioksi iankaikkisesti; ei kenkään ole siellä asuva, ei yksikään ihmislapsi siellä oleskeleva.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Herran sana, joka tuli profeetta Jeremialle Eelamia vastaan Juudan kuninkaan Sidkian hallituksen alussa; se kuului:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, '\"Näin sanoo Herra Sebaot: Katso, minä murran Eelamin jousen, heidän väkevyytensä parhaimmat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Ja minä tuotan Eelamia vastaan neljä tuulta taivaan neljältä ääreltä ja hajotan heidät kaikkiin näihin tuuliin; eikä ole oleva kansaa, johon ei tulisi Eelamin karkoitettuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Ja minä saatan Eelamin kauhistumaan vihollistensa edessä, niiden edessä, jotka etsivät heidän henkeänsä, ja minä annan onnettomuuden kohdata heitä, vihani hehkun, sanoo Herra, ja minä lähetän heidän jälkeensä miekan, kunnes minä heidät lopetan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Ja minä asetan valtaistuimeni Eelamiin ja hävitän sieltä kuninkaan ja ruhtinaat, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Mutta aikojen lopulla minä käännän Eelamin kohtalon, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Sana, jonka Herra puhui Baabelia vastaan, kaldealaisten maata vastaan, profeetta Jeremian kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, '\"Julistakaa kansojen keskuudessa ja kuuluttakaa, nostakaa lippu; kuuluttakaa, älkää salatko. Sanokaa: Baabel on valloitettu, Beel on joutunut häpeään, kauhistunut on Merodak; sen jumalankuvat ovat joutuneet häpeään, kauhistuneet ovat sen kivijumalat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Sillä sen kimppuun käy kansa pohjoisesta ja tekee sen maan autioksi, niin ettei siellä asukasta ole: niin ihmiset kuin eläimet pakenevat, menevät pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'Niinä päivinä ja siihen aikaan, sanoo Herra, tulevat israelilaiset yhdessä Juudan miesten kanssa; he kulkevat itkien lakkaamatta ja etsivät Herraa, Jumalaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Siionia he kysyvät, sitä kohden ovat heidän kasvonsa käännetyt. Tulkaa! He liittyvät Herran kanssa iankaikkiseen liittoon, jota ei pidä unhotettaman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Kadonnut lammaslauma oli minun kansani. Heidän paimenensa olivat vieneet heidät harhaan eksyttäville vuorille; he kulkivat vuorelta kukkulalle, unhottivat lepopaikkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Kaikki, jotka heitä tapasivat, söivät heitä, ja heidän vihollisensa sanoivat: \'Emme joudu syynalaisiksi\'. Sillä he olivat tehneet syntiä Herraa vastaan, vanhurskauden asumusta, Herraa, heidän isiensä toivoa, vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Paetkaa Baabelista, lähtekää pois kaldealaisten maasta, ja käykää kuin johtokauriit lauman edellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Sillä katso, minä herätän ja tuon Baabelia vastaan suurten kansojen joukon pohjoisesta maasta, ja ne asettuvat sotarintaan sitä vastaan. Sieltäkäsin se valloitetaan; heidän nuolensa ovat kuin voitollisen sankarin, joka ei tyhjänä palaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Ja Kaldea joutuu ryöstettäväksi, kaikki sen ryöstäjät saavat yltäkyllin, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Iloitkaa vain, riemuitkaa vain, te minun perintöosani riistäjät, hypelkää kuin puiva hieho, ja hirnukaa kuin orhit:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'kuitenkin joutuu äitinne suureen häpeään, synnyttäjänne saa hävetä. Katso, pakanakansoista vihoviimeinen! Erämaa, kuiva maa ja aromaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Herran vihan tähden se on oleva asumaton, aivan autio. Jokainen, joka kulkee Baabelin ohitse, kauhistuu ja viheltää kaikille sen haavoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Asettukaa sotarintaan Baabelia vastaan, yltympäri, kaikki jousenjännittäjät. Ampukaa sitä, älkää nuolia säästäkö; sillä se on tehnyt syntiä Herraa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Nostakaa sotahuuto sitä vastaan joka taholta. Se antautuu, sen pylväät kaatuvat, sen muurit sortuvat. Sillä tämä on Herran kosto. Kostakaa sille, tehkää sille, niinkuin sekin on tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Tuhotkaa kylväjät Baabelista ja ne, jotka elonaikana sirppiin tarttuvat. Hävittäjän miekkaa pakoon he kääntyvät kukin oman kansansa tykö, pakenevat kukin omaan maahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Eksynyt lammas on Israel, leijonat ovat sen eksyksiin saaneet. Ensiksi Assurin kuningas söi sen, ja nyt viimeksi Nebukadressar, Baabelin kuningas, kalusi sen luut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Sentähden, näin sanoo Herra Sebaot, Israelin Jumala: Katso, minä rankaisen Baabelin kuningasta ja hänen maatansa, niinkuin minä rankaisin Assurin kuningasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Ja minä tuon Israelin takaisin sen omille laidunmaille, ja se on käyvä laitumella Karmelilla ja Baasanissa ja tyydyttävä nälkänsä Efraimin vuorilla ja Gileadissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'Niinä päivinä ja siihen aikaan, sanoo Herra, etsitään Israelin rikkomusta, eikä sitä enää ole, ja Juudan syntiä, eikä sitä löydetä; sillä minä annan anteeksi niille, jotka minä jäännökseksi jätän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Käy Merataimin maan kimppuun ja Pekodin asukasten kimppuun. Aja heitä takaa, hävitä, vihi tuhon omaksi heidät, sanoo Herra, ja tee kaikki, mitä minä olen käskenyt sinun tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Sotahuuto kuuluu maassa, suuri hävityksen melske!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Kuinka rikottu ja särjetty onkaan se vasara, joka löi koko maanpiiriä! Kuinka onkaan Baabel tullut kauhistukseksi kansojen seassa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Minä viritin sinulle pyydyksen, ja niin sinut, Baabel, vangittiin tietämättäsi. Sinut tavattiin ja otettiin kiinni, sillä Herraa vastaan sinä ryhdyit taisteluun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Herra avasi asehuoneensa ja toi ulos vihansa aseet. Sillä Herra, Herra Sebaot, on tekevä työnsä kaldealaisten maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Käykää sen kimppuun kaikilta ääriltä, avatkaa sen aitat, heittäkää ulos, mitä siinä on, läjään niinkuin lyhteet. Vihkikää se tuhon omaksi, älköön siitä tähdettä jääkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Hävittäkää kaikki sen härät, astukoot ne teurastettaviksi. Voi heitä! Sillä heidän päivänsä on tullut, heidän rangaistuksensa aika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Kuule! Pakenevia ja pakolaisia tulee Baabelin maasta Siioniin ilmoittamaan Herran, meidän Jumalamme, kostoa, kostoa Hänen temppelinsä puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Kutsukaa ampujat kokoon Baabelia vastaan, kaikki jousenjännittäjät: leiriytykää sen ympärille, älköön pääskö pakoon ainoakaan. Maksakaa sille sen tekojen mukaan; kaiken sen mukaan, mitä se on tehnyt, tehkää sillekin. Sillä se on uhitellut Herraa, Israelin Pyhää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Sentähden sen nuorukaiset kaatuvat sen kaduilla, ja kaikki sotamiehet saavat surmansa sinä päivänä, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Katso, minä käyn sinun kimppuusi, sinä ylpeä, sanoo Herra, Herra Sebaot, sillä sinun päiväsi on tullut, sinun rangaistuksesi aika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Ylpeä kompastuu ja kaatuu, eikä ole hänen nostajaansa. Ja minä sytytän hänen kaupunkinsa tuleen, ja se kuluttaa ne ja kaiken, mitä hänen ympärillänsä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Näin sanoo Herra Sebaot: Sorrettuja ovat niin israelilaiset kuin Juudan miehet, ja kaikki heidän vangitsijansa pitävät heitä kiinni, he eivät tahdo päästää heitä irti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Mutta heidän lunastajansa on väkevä, Herra Sebaot on hänen nimensä. Hän ajaa heidän asiansa, tuo rauhan maan päälle, mutta Baabelin asukkaille vavistuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Miekka kaldealaisten kimppuun, sanoo Herra, ja Baabelin asukasten kimppuun, sen ruhtinasten ja tietäjäin kimppuun!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Miekka valhettelijain kimppuun, ja he typertyvät! Miekka sen sankarien kimppuun, ja he kauhistuvat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Miekka sen hevosten ja vaunujen kimppuun ja kaiken sekakansan kimppuun, joka on sen keskellä, ja he muuttuvat naisiksi! Miekka sen aarteiden kimppuun, ja ne ryöstetään!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Helle sen vetten kimppuun, ja ne kuivuvat! Sillä se on jumalankuvien maa, ja hirmujumaliinsa he uskaltavat mielettömästi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Sentähden tulevat sen asukkaiksi erämaan ulvojat ja ulisijat, ja kamelikurjet siellä asustavat. Ei sitä ikinä enää asuta, autioksi jää se polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Niinkuin oli silloin, kun Jumala hävitti Sodoman ja Gomorran ja niiden naapurit, sanoo Herra, niin ei sielläkään ole kenkään asuva, ei yksikään ihmislapsi oleskeleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Katso, kansa tulee pohjoisesta; suuri kansa ja monet kuninkaat nousevat maan perimmäisiltä ääriltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'He käyttävät jousta ja keihästä, ovat julmat ja armahtamattomat. Heidän pauhinansa on kuin pauhaava meri, ja he ratsastavat hevosilla, varustettuina kuin soturi taisteluun sinua vastaan, tytär Baabel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Kun Baabelin kuningas kuulee sanoman heistä, niin hänen kätensä herpoavat; ahdistus valtaa hänet, tuska, niinkuin synnyttäväisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Katso, niinkuin leijona karkaa Jordanin rantatiheiköstä lakastumattomalle laitumelle, niin minä äkisti karkoitan heidät sieltä pois. Ja hänet, joka valittu on, minä asetan sinne kaitsijaksi. Sillä kuka on minun vertaiseni, ja kuka vetää minut tilille? Ja kuka on se paimen, joka voi kestää minun edessäni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Sentähden kuulkaa Herran päätös, jonka hän on päättänyt Baabelia vastaan, ja hänen aivoituksensa, jotka hän on aivoitellut kaldealaisten maata vastaan: Totisesti, ne raastetaan pois, nuo lauman vähäiset; totisesti, laidun kauhistuu niiden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Huuto käy: \'Baabel on valloitettu!\' ja maa vapisee, parku kuuluu kansoissa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Näin sanoo Herra: \"Katso, minä herätän Baabelia vastaan, Leeb-Kaamain asukkaita vastaan hävittäjän hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Ja minä lähetän Baabeliin muukalaisia, jotka hajottavat sen ja tyhjentävät sen maan, sillä joka taholta he tulevat sitä vastaan onnettomuuden päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Jousimies jännittäköön jousensa sitä vastaan, joka jousen jännittää, ja sitä vastaan, joka uljastelee rintahaarniskassaan. Älkää säälikö sen nuorukaisia, vihkikää tuhon omaksi koko sen sotajoukko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Haavoitettuja kaatuu kaldealaisten maassa ja lävistettyjä sen kaduilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Sillä ei Israel eikä Juuda ole Jumalansa, Herran Sebaotin, hylkäämä, vaan noiden maa on täynnä syntivelkaa Israelin Pyhän edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Paetkaa Baabelista ja pelastakoon kukin henkensä, älkää hukkuko sen syntiin. Sillä tämä on Herran koston aika, hän maksaa sille, mitä se on ansainnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Baabel oli Herran kädessä kultainen malja, joka juovutti kaiken maan. Sen viinistä joivat kansat; sentähden kansat tulivat mielettömiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'kisti on Baabel kaatunut ja murskaantunut. Valittakaa hänen tähtensä! Hakekaa balsamia hänen kipuunsa, ehkä hän paranee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, '\'Me olemme koettaneet parantaa Baabelia, mutta ei hän ole parantunut. Jättäkää hänet ja menkäämme pois, kukin omaan maahansa; sillä hänen tuomionsa ulottuu taivaaseen asti, kohoaa pilviin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Herra on tuonut ilmi meidän vanhurskautemme; tulkaa, julistakaamme Siionissa Herran, meidän Jumalamme, tekoja.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Teroittakaa nuolet, täyttäkää viinet! Herra on herättänyt Meedian kuningasten hengen, sillä hänen ajatuksensa käy Baabelia vastaan, sen hävittämiseksi. Tämä on Herran kosto, kosto hänen temppelinsä puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Kohottakaa lippu Baabelin muureja vastaan, vahvistakaa vartiosto, asettakaa vartijat, valmistakaa väijytykset; sillä mitä Herra on ajatellut, sen hän tekeekin, sen minkä hän on puhunut Baabelin asukkaita vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Sinä, joka asut suurten vetten partailla, joka olet aarteista rikas, sinun loppusi on tullut, sinun väärän voittosi raja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Herra Sebaot on vannonut itse kauttansa: Totisesti, minä täytän sinut ihmisillä niinkuin heinäsirkoilla, ja he virittävät sinusta viininkorjuulaulun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Hän on tehnyt maan voimallansa, vahvistanut maanpiirin viisaudellansa ja levittänyt taivaat taidollansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Kun hän jylisee, käy vetten pauhina taivaalla, ja hän nostaa pilvet maan ääristä, tekee salamat ja sateen ja tuo tuulen sen säilytyspaikoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Järjetön on jokainen ihminen, tietoa vailla, häpeän saa jokainen kultaseppä veistetystä kuvasta, petosta on hänen valamansa kuva, eikä niissä henkeä ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Turhuutta ne ovat, naurettavia tekeleitä; kun niiden rangaistus tulee, ne hukkuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Näiden kaltainen ei ole hän, joka on Jaakobin osa, sillä hän on kaiken luoja, ja Jaakob on hänen perintösukunsa: Herra Sebaot on hänen nimensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Sinä olit minun vasarani, minun sota-aseeni, sinulla minä musersin kansoja, sinulla minä hävitin valtakuntia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Sinulla minä musersin hevosen ja ratsastajan, sinulla minä musersin vaunut ja ajajan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Sinulla minä musersin miehen ja vaimon, sinulla minä musersin vanhan ja nuoren, sinulla minä musersin nuorukaisen ja neitosen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Sinulla minä musersin paimenen ja hänen laumansa, sinulla minä musersin peltomiehen ja hänen juhtaparinsa, sinulla minä musersin käskynhaltijat ja päämiehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Minä maksan Baabelille ja kaikille Kaldean asukkaille kaiken sen pahan, minkä he ovat tehneet Siionille teidän silmäinne edessä, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Katso, minä käyn sinun kimppuusi, sinä hävityksen vuori, joka hävitit koko maan, sanoo Herra. Ja minä ojennan käteni sinua vastaan ja vieritän sinut alas kalliolta ja teen sinusta poltetun vuoren.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Eikä sinusta oteta enää kulmakiveä eikä perustuskiveä, vaan sinä jäät ikuiseksi erämaaksi, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Nostakaa lippu maassa, puhaltakaa pasunaan kansoissa, vihkikää kansat häntä vastaan, kutsukaa häntä vastaan Araratin, Minnin ja Askenaan valtakunnat, asettakaa päämies häntä vastaan, antakaa tulla hevosia kuin pörheitä heinäsirkkoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Vihkikää kansat häntä vastaan, Meedian kuninkaat, sen käskynhaltijat ja kaikki päämiehet ja koko sen vallan alainen maa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Ja maa vapisee ja vääntelehtii tuskasta, sillä Herran aivoitukset täyttyvät Baabelia vastaan: hän tekee Baabelin maasta asumattoman erämaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Baabelin sankarit lakkaavat taistelemasta, he istuvat linnoituksissaan, heidän voimansa on kuihtunut, he ovat naisiksi muuttuneet; sen asunnot ovat poltetut, sen salvat rikotut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Juoksija juoksee juoksijaa vastaan, sanansaattaja sanansaattajaa vastaan, ilmoittamaan Baabelin kuninkaalle, että hänen kaupunkinsa on valloitettu äärestä toiseen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'kahlauspaikat vallatut, linnoitukset tulella poltetut ja sotamiehet kauhun vallassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Sillä näin sanoo Herra Sebaot, Israelin Jumala: Tytär Baabel on kuin puimatanner poljettaessa; vielä vähän aikaa, niin hänen elonaikansa tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Nebukadressar, Baabelin kuningas, on minut syönyt, hävittänyt minut, pannut syrjään kuin tyhjän astian; hän on niellyt minut niinkuin lohikäärme, täyttänyt vatsansa minun herkuillani ja huuhtonut minut pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, '\'Kärsimäni väkivalta ja minun raadeltu lihani tulkoon Baabelin päälle\', sanoo Siionin asukas. \'Minun vereni tulkoon Kaldean asukasten päälle\', sanoo Jerusalem.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Sentähden näin sanoo Herra: Katso, minä ajan sinun asiasi ja kostan sinun kostosi. Minä kuivaan hänen virtansa ja ehdytän hänen lähteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Ja Baabel tulee kiviroukkioksi, aavikkosutten asunnoksi, kauhistukseksi ja ivan vihellykseksi, aivan asujattomaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'He kiljuvat kaikki kuin nuoret leijonat, murisevat kuin naarasleijonain pennut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Kun he ovat himossansa kiihkeimmillään, teen minä heille juomingit ja juovutan heidät, että he riemastuvat ja nukkuvat ikuiseen uneen eivätkä enää heräjä, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Minä vien heidät teurastettaviksi, niinkuin karitsat, niinkuin oinaat ja kauriit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Kuinka onkaan valloitettu Seesak, vallattu se, jota ylisti kaikki maa! Kuinka onkaan Baabelista tullut kauhistus kansojen seassa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Meri nousi Baabelin yli, sen aaltojen pauhuun se peittyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Sen kaupungit ovat tulleet autiomaaksi, kuivaksi maaksi ja aromaaksi, maaksi, jossa ei asu kenkään, jossa ei ihmislapsi kulje.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Minä kostan Beelille Baabelissa ja vedän ulos hänen kidastaan sen, mitä hän on niellyt; eivätkä kansat enää virtaa hänen tykönsä. Baabelin muurikin on kaatunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Lähde pois sen keskeltä, minun kansani, ja pelastakoon kukin henkensä Herran vihan hehkusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Älköön sydämenne säikkykö, älkää peljätkö sitä sanomaa, joka kuuluu maassa, kun tulee tänä vuonna tämä sanoma ja sitten toisena vuonna tuo sanoma, kun maassa on väkivalta ja hallitsija hallitsijaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Sentähden katso, päivät tulevat, jolloin minä kostan Baabelin jumalankuville, jolloin koko sen maa joutuu häpeään ja kaikki kaatuvat surmattuina sen keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Silloin riemuitsevat Baabelin kohtalosta taivas ja maa ja kaikki, mitä niissä on, kun pohjoisesta tulevat sen hävittäjät, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Baabelinkin on kaatuminen, te Israelin surmatut, niinkuin Baabelin tähden kaatui surmatuita kautta kaiken maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Te miekasta pelastuneet, menkää, älkää pysähtykö, muistakaa Herraa kaukaisella maalla ja pitäkää mielessänne Jerusalem.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, '\'Me häpeämme, sillä me kuulemme pilkkaa; häpeä peittää meidän kasvomme, sillä muukalaiset ovat käyneet Herran temppelin pyhyyksien kimppuun.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Sentähden katso, päivät tulevat, sanoo Herra, jolloin minä kostan sen jumalankuville ja sen maa on täynnä haavoitettujen voihkinaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Vaikka Baabel astuisi ylös taivaaseen, vaikka se korkeuteen linnansa vahvistaisi, sittenkin tulevat sille minulta hävittäjät, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Kuule, huuto Baabelista, suuri hävityksen melske kaldealaisten maasta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Sillä Herra hävittää Baabelin ja lopettaa sieltä suuren äänten melun. Heidän aaltonsa pauhaavat kuin suuret vedet, korkea on heidän äänensä kohina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Sillä hävittäjä käy Baabelin kimppuun, ja sen sankarit vangitaan, heidän jousensa murretaan; sillä Herra on koston Jumala: hän maksaa tarkoin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Minä juovutan sen ruhtinaat ja tietäjät, sen käskynhaltijat, päämiehet ja sankarit; ja he nukkuvat ikuiseen uneen eivätkä enää heräjä, sanoo Kuningas; Herra Sebaot on hänen nimensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Näin sanoo Herra Sebaot: Baabelin leveä muuri hajotetaan maahan, ja sen korkeat portit poltetaan tulella. Niin tekevät kansat työtä tyhjän tähden, kansakunnat tulen hyväksi, ja vaivaavat itsensä väsyksiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Asia, jonka profeetta Jeremia antoi Serajalle, Neerian, Mahsejan pojan, pojalle toimitettavaksi, kun tämä lähti Sidkian, Juudan kuninkaan, kanssa Baabeliin hänen neljäntenä hallitusvuotenansa. Seraja oli majoituspäällikkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Jeremia kirjoitti kaiken sen onnettomuuden, joka oli tuleva Baabelille, erityiseen kirjaan, kaikki nämä sanat, jotka ovat kirjoitetut Baabelia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Ja Jeremia sanoi Serajalle: \"Kun tulet Baabeliin, niin katso, että luet kaikki nämä sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Ja sano: Herra, sinä olet puhunut tätä paikkaa vastaan: sinä olet hävittävä sen, niin ettei siinä asukasta ole, ei ihmistä eikä eläintä, vaan että se jää ikuiseksi erämaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Ja kun olet lukenut tämän kirjan loppuun, sido siihen kivi ja viskaa se keskelle Eufratia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'ja sano: Näin uppoaa Baabel eikä nouse enää siitä onnettomuudesta, jonka minä sille tuotan, vaan he vaipuvat.\" Näin pitkälle Jeremian sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Sidkia oli kahdenkymmenen yhden vuoden vanha tullessaan kuninkaaksi, ja hän hallitsi Jerusalemissa yksitoista vuotta. Hänen äitinsä oli nimeltään Hamutal, Jeremian tytär, Libnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Hän teki sitä, mikä on pahaa Herran silmissä, aivan samoin kuin Joojakim oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Sillä Herran vihan tähden kävi näin Jerusalemille ja Juudalle, kunnes hän vihdoin heitti heidät pois kasvojensa edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Sidkia kapinoi Baabelin kuningasta vastaan. Hänen yhdeksäntenä hallitusvuotenaan, sen kymmenennessä kuussa, kuukauden kymmenentenä päivänä, hyökkäsi Nebukadressar, Baabelin kuningas, koko sotajoukollaan Jerusalemin kimppuun; ja he asettuivat leiriin sitä vastaan ja rakensivat saartovarusteet sitä vastaan yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Näin kaupunkia piiritettiin kuningas Sidkian yhdenteentoista hallitusvuoteen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Mutta neljännessä kuussa, kuukauden yhdeksäntenä päivänä, kun nälänhätä ahdisti kaupunkia eikä maakansallakaan ollut leipää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'valloitettiin kaupunki, ja kaikki sotilaat pakenivat ja lähtivät ulos kaupungista yöllä molempien muurien välitse vievää porttitietä, joka on kuninkaan puutarhan puolella, kaldealaisten ollessa kaupungin ympärillä, ja he kulkivat Aromaahan päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Mutta kaldealaisten sotajoukko ajoi kuningasta takaa, ja he saavuttivat Sidkian Jerikon aroilla; ja kaikki hänen sotaväkensä oli jättänyt hänet ja hajaantunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Ja he ottivat kuninkaan kiinni ja veivät hänet Baabelin kuninkaan eteen Riblaan, joka on Hamatin maassa, ja tämä julisti hänelle tuomion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Ja Baabelin kuningas teurastutti Sidkian pojat hänen silmiensä edessä, ja myöskin kaikki Juudan ruhtinaat hän teurastutti Riblassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Ja Sidkialta Baabelin kuningas sokaisutti silmät, kytketti hänet vaskikahleisiin ja vei hänet Baabeliin, ja hän pani hänet vankihuoneeseen, jossa hän oli kuolinpäiväänsä asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Viidennessä kuussa, kuukauden kymmenentenä päivänä, Baabelin kuninkaan Nebukadressarin yhdeksäntenätoista hallitusvuotena, tuli Nebusaradan, henkivartijain päällikkö, joka palveli Baabelin kuningasta, Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Hän poltti Herran temppelin ja kuninkaan linnan ja kaikki Jerusalemin talot; kaikki ylhäisten talot hän poltti tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Ja koko kaldealaisten sotajoukko, joka henkivartijain päälliköllä oli mukanaan, repi maahan kaikki Jerusalemin muurit, yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Ja Nebusaradan, henkivartijain päällikkö, siirsi maasta pois osan kansan köyhiä ja kansan tähteitä, mitä oli jäljellä kaupungissa, sekä ne, jotka olivat menneet Baabelin kuninkaan puolelle, ja loput käsityöläisistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Mutta osan maan köyhiä Nebusaradan, henkivartijain päällikkö, jätti jäljelle viinitarhureiksi ja peltomiehiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Vaskipylväät, jotka olivat Herran temppelissä, altaiden telineet ja vaskimeren, jotka olivat Herran temppelissä, kaldealaiset särkivät ja veivät kaiken niiden vasken Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Ja kattilat, lapiot, veitset, maljat, kupit ja kaikki vaskikalut, joita oli käytetty jumalanpalveluksessa, he ottivat pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Samoin otti henkivartijain päällikkö vadit, hiilipannut, maljat, kattilat, lampunjalat, kupit ja kulhot, jotka olivat läpeensä kultaa tai hopeata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Molempien pylväiden, meren ja niiden kahdentoista vaskiraavaan, jotka olivat telineiden alla-kaikkien niiden esineiden, jotka Salomo oli teettänyt Herran temppeliin-niiden vaski ei ollut punnittavissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Pylväistä oli toisen pylvään korkeus kahdeksantoista kyynärää, ja kahdentoista kyynärän pituinen nauha ulottui sen ympäri. Sen vahvuus oli neljä sormenleveyttä; se oli ontto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Ja sen päässä oli pylväänpää vaskesta; toisen pylväänpään korkeus oli viisi kyynärää, ja pylväänpään päällä oli ristikkokoriste ja granaattiomenia yltympäri, kaikki vaskea; ja samanlaiset oli toisessa pylväässä ynnä granaattiomenat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Granaattiomenia oli yhdeksänkymmentä kuusi ulospäin; kaikkiaan oli granaattiomenia sata ristikkokoristeen päällä yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Ja henkivartijain päällikkö otti ylimmäisen papin Serajan ja häntä lähimmän papin Sefanjan sekä kolme ovenvartijaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'ja kaupungista hän otti yhden hoviherran, joka oli sotaväen tarkastaja, ja seitsemän kuninkaan lähintä miestä, jotka tavattiin kaupungista, sekä sotapäällikön kirjurin, jonka tehtävänä oli ottaa maan kansaa sotapalvelukseen, ja kuusikymmentä miestä maakansasta, jotka tavattiin kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Nämä otti Nebusaradan, henkivartijain päällikkö, ja vei heidät Baabelin kuninkaan eteen Riblaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Ja Baabelin kuningas antoi lyödä heidät kuoliaaksi Riblassa Hamatin maassa. Ja niin Juuda siirrettiin pois maastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Tämä on se kansa, jonka Nebukadressar vei pakkosiirtolaisuuteen: seitsemäntenä vuotena kolmetuhatta kaksikymmentä kolme juutalaista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'Nebukadressarin kahdeksantenatoista hallitusvuotena kahdeksansataa kolmekymmentä kaksi henkeä Jerusalemista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'Nebukadressarin kahdentenakymmenentenä kolmantena hallitusvuotena vei Nebusaradan, henkivartijain päällikkö, seitsemänsataa neljäkymmentä viisi juutalaista pakkosiirtolaisuuteen-yhteensä neljätuhatta kuusisataa henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Mutta kolmantenakymmenentenä seitsemäntenä vuotena siitä, kun Joojakim, Juudan kuningas, oli viety pakkosiirtolaisuuteen, kahdennessatoista kuussa, kuukauden kahdentenakymmenentenä viidentenä päivänä, korotti Evil-Merodak, Baabelin kuningas, samana vuonna, jona hän tuli kuninkaaksi, Juudan kuninkaan Joojakinin pään ja päästi hänet pois vankilasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Ja hän puhutteli häntä ystävällisesti ja asetti hänen istuimensa ylemmäksi muitten kuningasten istuimia, jotka olivat hänen tykönänsä Baabelissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Hän sai panna pois vanginpuvun ja aina aterioida hänen luonaan, niin kauan kuin eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Ja hän sai Baabelin kuninkaalta elatuksensa, vakinaisen elatuksen, mitä kunakin päivänä tarvitsi, kuolinpäiväänsä asti, niin kauan kuin eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Kuinka istuukaan yksinänsä tuo väkirikas kaupunki! Kuinka onkaan lesken kaltaiseksi tullut se, joka oli suuri kansakuntien joukossa! Ruhtinatar maakuntien joukossa on tullut työveron alaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Se katkerasti itkee yössä, ja sillä on kyyneleet poskillansa. Ei ole sillä lohduttajaa kaikkien sen rakastajain seassa. Uskottomia ovat sille olleet kaikki sen ystävät, ovat sille vihamiehiksi tulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Juuda on siirtynyt maastansa kurjuutta ja työn kovuutta pakoon. Se istuu pakanakansain seassa eikä lepoa löydä. Kaikki sen vainoojat saavuttivat sen, kun se oli ahdistuksien keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Siionin tiet surevat, sillä juhlilletulijoita ei ole. Kaikki sen portit ovat autioina, sen papit huokailevat, sen neitsyet ovat murheissaan, ja sillä itsellään on katkera mieli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Sen viholliset ovat voitolle päässeet, sen vihamiehet menestyvät. Sillä Herra on saattanut sen murheelliseksi sen rikkomusten paljouden tähden. Sen pienet lapset ovat menneet vankeuteen vihollisen vieminä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Mennyt on tytär Siionilta kaikki hänen kauneutensa. Hänen ruhtinaansa ovat kuin peurat, jotka eivät laidunta löydä; he kulkivat voimattomina vainoojan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Jerusalem muistelee kurjuutensa päivinä ja kodittomuudessaan kaikkea kallisarvoista, mitä sillä oli muinaisista päivistä asti. Kun sen kansa sortui vihollisen käsiin eikä sillä ollut auttajaa, katsoivat viholliset sitä ja nauroivat sen turmiota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jerusalem on raskaasti syntiä tehnyt, sentähden se on saastaksi tullut. Kaikki, jotka sitä kunnioittivat, halveksivat sitä nyt, kun ovat nähneet sen alastomuuden. Itsekin se huokaa ja kääntyy poispäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Sen tahrat ovat sen liepeissä. Se ei ajatellut, mikä sille tuleva oli, ja niin se sortui hämmästyttävästi. Ei ole sillä lohduttajaa. Katso, Herra, minun kurjuuttani, sillä vihamies ylvästelee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Vihollinen levitti kätensä kaikkia sen kalleuksia kohti. Niin, sen täytyi nähdä, kuinka pakanat tunkeutuivat sen pyhäkköön, ne, jotka sinä olit kieltänyt tulemasta sinun seurakuntaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Kaikki sen kansa huokaa etsiessänsä leipää: he antavat, mitä heillä kallista on, ruuasta, saadakseen nälkänsä tyydytetyksi. Katso, Herra, ja näe, kuinka halveksittu minä olen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Eikö tämä koske teihin, kaikki ohikulkijat? Katsokaa ja nähkää: onko kipua, minun kipuni vertaista, joka on minun kannettavakseni pantu, jolla Herra on murehduttanut minut vihansa hehkun päivänä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Hän lähetti tulen korkeudesta minun luihini ja kuritti niitä. Hän viritti verkon minun jalkaini varalle, hän pani minut peräytymään, hän teki minut autioksi, ainiaan sairaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Hänen kätensä sitoi minun rikosteni ikeen: ne kiedottiin yhteen, tulivat minun niskalleni; hän saattoi horjumaan minun voimani. Herra antoi minut niiden käsiin, joita minä en voi vastustaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Herra hylkäsi kaikki minun urhoni, joita minun keskuudessani oli; hän kutsui kokoon juhlan minua vastaan murskatakseen minun nuorukaiseni. Herra polki viinikuurnan neitsyelle, tytär Juudalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Näitä minä itken, minun silmäni, silmäni vuotaa vettä; sillä kaukana on minusta lohduttaja, joka virvoittaisi minun sieluani. Hävitetyt ovat minun lapseni, sillä vihamies on väkevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Siion levittää käsiänsä: ei ole hänellä lohduttajaa. Herra on nostattanut Jaakobia vastaan sen viholliset joka taholta; Jerusalem on tullut saastaksi heidän keskellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Vanhurskas on hän, Herra; sillä hänen käskyänsä vastaan minä olen niskoitellut. Kuulkaa, te kansat kaikki, ja katsokaa minun kipuani: minun neitsyeni ja nuorukaiseni ovat vankeuteen menneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Minä kutsuin rakastajiani: ne pettivät minut. Minun pappini ja vanhimpani ovat kuolleet kaupungissa, kun he etsivät ruokaa tyydyttääkseen nälkäänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Katso, Herra, kuinka ahdistettu minä olen, minun sisukseni kuohuvat, sydämeni vääntyy rinnassani, sillä minä olen ollut ylen uppiniskainen. Ulkona on miekka minulta riistänyt lapset, sisällä rutto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'He ovat kuulleet, kuinka minä huokailen. Ei ole minulla lohduttajaa. Kaikki minun vihamieheni ovat kuulleet minun onnettomuuteni; he iloitsevat, kun sinä olet tämän tehnyt: sinä olet antanut tulla sen päivän, jonka olit ilmoittanut. Mutta käyköön heidän samoin kuin minun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Tulkoon kaikki heidän pahuutensa sinun kasvojesi eteen, ja pane heille kannettavaksi se, minkä olet minulle pannut kaikkien minun rikoksieni tähden. Sillä monet ovat minun huokaukseni, ja minun sydämeni on sairas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Kuinka onkaan Herra vihassaan pilvillä peittänyt tytär Siionin! Hän heitti taivaasta maahan Israelin kunnian eikä muistanut jalkainsa astinlautaa vihansa päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Herra on hävittänyt säälimättä kaikki Jaakobin majat, on hajottanut vihastuksissaan tytär Juudan linnoitukset, pannut ne maan tasalle. Hän on häväissyt valtakunnan ja sen ruhtinaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Hän on vihan hehkussa hakannut poikki Israelin sarven kokonansa. Hän veti oikean kätensä takaisin vihamiehen edestä ja poltti Jaakobia kuin liekitsevä tuli, joka kuluttaa kaiken yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Hän jännitti jousensa kuin vihamies, seisoi oikea käsi koholla kuin vihollinen ja tappoi kaiken, mihin silmä oli ihastunut. Tytär Siionin majaan hän vuodatti kiivautensa kuin tulen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Herra on ollut niinkuin vihamies, on hävittänyt Israelin: hän hävitti kaikki sen palatsit, turmeli sen linnoitukset ja antoi tytär Juudalle paljon valitusta ja vaikerrusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Hän särki aitauksensa niinkuin puutarhan aidan, hävitti juhlanviettopaikkansa. Herra on saattanut unhotuksiin Siionissa juhla-ajat ja sapatit ja on kiivaassa suuttumuksessaan pitänyt halpana kuninkaat ja papit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Herra on hyljännyt alttarinsa, syössyt häväistykseen pyhäkkönsä, luovuttanut vihamiehen käteen palatsiensa muurit. He nostivat huudon Herran huoneessa, huudon kuin juhlapäivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Herra oli päättänyt turmella tytär Siionin muurit: hän jännitti mittanuoran, ei pidättänyt kättänsä hävittämästä, saattoi murheeseen varustukset ja muurit; ne yhdessä nääntyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Sen portit ovat vajonneet maahan, hän poisti ja särki sen salvat. Sen kuningas ja ruhtinaat ovat pakanain seassa; lakia ei ole, eivätkä sen profeetat saa näkyjä Herralta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Maassa istuvat ääneti tytär Siionin vanhimmat. He ovat heittäneet tomua päänsä päälle, vyöttäytyneet säkkeihin; maata kohden ovat painaneet päänsä Jerusalemin neitsyet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Minun silmäni ovat itkusta hiuenneet, minun sisukseni kuohuvat, minun maksani on maahan vuodatettu tyttären, minun kansani, sortumisen tähden. Sillä lapset ja imeväiset nääntyvät kaupungin kaduilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'He sanovat äideillensä: \"Missä on leipää ja viiniä?\" kun he nääntyvät niinkuin kaatuneet kaupungin kaduilla, heittävät henkensä äitiensä syliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Minkä sinulle mainitsisin, mihin vertaisin sinua, tytär Jerusalem? Minkä asettaisin rinnallesi lohduttaakseni sinua, neitsyt, tytär Siion? Sillä suuri niinkuin meri on sinun sortumisesi; kuka voi sinut parantaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Profeettasi ovat sinulle nähneet petollisia, äiteliä näkyjä. Eivät he ole paljastaneet sinun syntiäsi, niin että olisivat kääntäneet sinun kohtalosi, vaan ovat nähneet sinulle petollisia, eksyttäväisiä ennustuksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Sinulle paukuttavat kämmeniänsä kaikki ohikulkijat, he viheltävät ja nyökyttävät ilkkuen päätänsä tytär Jerusalemille: \"Tämäkö on kaupunki, jota sanottiin kauneuden täydellisyydeksi, kaiken maan ihastukseksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Suu ammollaan sinua vastaan ovat kaikki sinun vihamiehesi. He viheltävät, kiristelevät hampaitaan ja sanovat: \"Me olemme sen hävittäneet. Tämä on juuri se päivä, jota olemme toivoneet; se on meille tullut, olemme sen nähneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Herra on tehnyt, mitä oli aikonut. Hän on täyttänyt sanansa, sen, mitä oli päättänyt muinaisista päivistä asti: hän on repinyt alas säälimättä, on antanut vihamiesten iloita sinusta ja kohottanut sinun vihollistesi sarven.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Heidän sydämensä huutaa Herran puoleen. Sinä, tytär Siionin muuri, anna kyyneltesi virtana vuotaa yötä päivää! Älä suo itsellesi lepoa, älköön silmäteräsi ummistuko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Nouse, kohota valitushuuto yöllä, kun alkavat yövartiot. Anna sydämesi vuotaa kuin vesi Herran kasvojen edessä. Kohota kätesi häntä kohden pienten lastesi elämän puolesta, kun ne nääntyvät nälkään kaikkien katujen kulmissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Katso, Herra, ja tarkkaa, ketä olet antanut tämän kohdata: pitäisikö vaimojen syödä oma hedelmänsä, vaalimansa pienet lapset; pitäisikö Herran pyhäkössä tapettaman papit ja profeetat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Maassa, kaduilla, makaa nuorta ja vanhaa; minun neitsyeni ja nuorukaiseni ovat kaatuneet miekkaan. Sinä olet surmannut vihasi päivänä, olet teurastanut säälimättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Sinä kutsuit kuin juhlapäivän viettoon minun peljättäjäni joka taholta; eikä jäänyt Herran vihan päivänä pelastunutta, ei pakoonpäässyttä. Jotka minä olin vaalinut ja isoiksi saanut, ne minun vihamieheni lopetti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Minä olen se mies, joka olen kurjuutta nähnyt hänen vihastuksensa vitsan alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Minut hän on johdattanut ja kuljettanut pimeyteen eikä valkeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Juuri minua vastaan hän kääntää kätensä, yhäti, kaiken päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Hän on kalvanut minun lihani ja nahkani, musertanut minun luuni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Hän on rakentanut varustukset minua vastaan ja piirittänyt minut myrkyllä ja vaivalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Hän on pannut minut asumaan pimeydessä niinkuin ikiaikojen kuolleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Hän on tehnyt muurin minun ympärilleni, niin etten pääse ulos, on pannut minut raskaisiin vaskikahleisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Vaikka minä huudan ja parun, hän vaientaa minun rukoukseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Hakatuista kivistä hän on tehnyt minun teilleni muurin, on mutkistanut minun polkuni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Vaaniva karhu on hän minulle, piilossa väijyvä leijona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Hän on vienyt harhaan minun tieni ja repinyt minut kappaleiksi, hän on minut autioksi tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Hän on jännittänyt jousensa ja asettanut minut nuoltensa maalitauluksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Hän on ampunut munuaisiini nuolet, viinensä lapset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Minä olen joutunut koko kansani nauruksi, heidän jokapäiväiseksi pilkkalauluksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Hän on ravinnut minua katkeruudella, juottanut minua koiruoholla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Hän on purettanut minulla hampaat rikki soraan, painanut minut alas tomuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Sinä olet syössyt minun sieluni ulos, rauhasta pois, minä olen unhottanut onnen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Ja minä sanon: mennyt on minulta kunnia ja Herran odotus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Muista minun kurjuuttani ja kodittomuuttani, koiruohoa ja myrkkyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Sinä kyllä muistat sen, että minun sieluni on alaspainettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Tämän minä painan sydämeeni, sentähden minä toivon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Herran armoa on, ettemme ole aivan hävinneet, sillä hänen laupeutensa ei ole loppunut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'se on joka aamu uusi, ja suuri on hänen uskollisuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Minun osani on Herra, sanoo minun sieluni; sentähden minä panen toivoni häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Hyvä on Herra häntä odottaville, sille sielulle, joka häntä etsii.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Hyvä on hiljaisuudessa toivoa Herran apua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Hyvä on miehelle, että hän kantaa iestä nuoruudessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Istukoon hän yksin ja hiljaa, kun Herra on sen hänen päällensä pannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Laskekoon suunsa tomuun-ehkä on vielä toivoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Ojentakoon hän posken sille, joka häntä lyö, saakoon kyllälti häväistystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Sillä ei Herra hylkää iankaikkisesti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'vaan jos hän on murheelliseksi saattanut, hän osoittaa laupeutta suuressa armossansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Sillä ei hän sydämensä halusta vaivaa eikä murehduta ihmislapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Kun jalkojen alle poljetaan kaikki vangit maassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'kun väännetään miehen oikeutta Korkeimman kasvojen edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'kun ihmiselle tehdään vääryyttä hänen riita-asiassaan-eikö Herra sitä näkisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Onko kukaan sanonut, ja se on tapahtunut, jos ei Herra ole käskenyt?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Eikö lähde Korkeimman suusta paha ja hyvä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Miksi tuskittelee ihminen eläessään, mies syntiensä palkkaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Koetelkaamme teitämme, tutkikaamme niitä ja palatkaamme Herran tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Kohottakaamme sydämemme ynnä kätemme Jumalan puoleen, joka on taivaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Me olemme luopuneet pois ja olleet kapinalliset; sinä et ole antanut anteeksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'olet peittänyt itsesi vihassasi, ajanut meitä takaa, surmannut säälimättä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'olet peittänyt itsesi pilvellä, niin ettei rukous pääse lävitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Tunkioksi ja hylyksi sinä olet meidät tehnyt kansojen seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Suut ammollaan meitä vastaan ovat kaikki meidän vihamiehemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Osaksemme on tullut kauhu ja kuoppa, turmio ja sortuminen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Vesipurot juoksevat minun silmistäni tyttären, minun kansani, sortumisen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Minun silmäni vuotaa lakkaamatta, hellittämättä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'siihen asti, kunnes katsoo, kunnes näkee Herra taivaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Silmäni tuottaa tuskaa minun sielulleni kaikkien minun kaupunkini tyttärien tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Kiihkeästi pyydystivät minua kuin lintua ne, jotka syyttä ovat vihamiehiäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'He sulkivat kuoppaan minun elämäni ja heittivät päälleni kiviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Vedet tulvivat minun pääni ylitse; minä sanoin: olen hukassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Minä huusin sinun nimeäsi, Herra, kuopan syvyydestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Sinä kuulit minun huutoni: \"Älä peitä korvaasi minun avunhuudoltani, että saisin hengähtää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Sinä olit läsnä silloin, kun minä sinua huusin; sinä sanoit: \"Älä pelkää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Sinä, Herra, ajoit minun riita-asiani, lunastit minun henkeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Olethan nähnyt, Herra, minun kärsimäni sorron: hanki minulle oikeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Olethan nähnyt kaiken heidän kostonhimonsa, kaikki heidän juonensa minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Sinä olet kuullut heidän häväistyksensä, Herra, kaikki heidän juonensa minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Minun vastustajaini huulet ja heidän aikeensa ovat minua vastaan kaiken päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Istuivatpa he tai nousivat, katso: minä olen heillä pilkkalauluna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Kosta heille, Herra, heidän kättensä teot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Paaduta heidän sydämensä, kohdatkoon heitä sinun kirouksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Aja heitä takaa vihassasi ja hävitä heidät Herran taivaan alta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Kuinka onkaan kulta tummunut, muuttunut hyvä kulta; kuinka ovat pyhät kivet viskeltyinä kaikkien katujen kulmiin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Siionin pojat, nuo kalliit, punnitut puhtaimman kullan arvoisiksi-kuinka he ovatkaan saviastiain arvossa, savenvalajan kätten tekojen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Aavikkosudetkin taritsevat nisiänsä, imettävät pentujansa; mutta tytär, minun kansani, on tullut tylyksi kuin kamelikurki erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Imeväisen kieli tarttuu suulakeen janon tähden. Lapsukaiset pyytävät leipää; ei ole, kuka sitä heille taittaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Jotka herkkuja söivät, ne nääntyvät kaduilla. Joita punapurppuran päällä kanneltiin, ne tunkioita syleilevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Tyttären, minun kansani, syntivelka on Sodoman syntiä suurempi; Sodoma hävitettiin yhtäkkiä kätten siellä riehumatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Siionin ruhtinaat olivat lunta puhtaammat, maitoa valkoisemmat, heidän ruumiinsa oli koralleja rusottavampi, heidän hahmonsa oli kuin safiiri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Nyt on heidän muotonsa nokea mustempi, ei voi heitä tuntea kaduilla. Rypyssä on heillä nahka luitten päällä, se on kuivettunut kuin puu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Parempi oli miekan kaatamien kuin nälän kaatamien, jotka menehtyivät, kuin lävitsepistetyt, pellon viljaa vailla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Armeliaat vaimot keittivät omin käsin lapsiansa: ne tulivat heille ruuaksi tyttären, minun kansani, sortuessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Herra on pannut täytäntöön kiivautensa, vuodattanut vihansa hehkun; hän on sytyttänyt Siioniin tulen, joka on kuluttanut sen perustukset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Eivät olisi uskoneet maan kuninkaat, ei maanpiirin asukkaista kenkään, että vihollinen ja vainomies hyökkää sisään Jerusalemin porteista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Sen profeettain syntien tähden kävi näin, sen pappien pahain tekojen tähden, niiden, jotka siellä olivat vuodattaneet vanhurskaitten verta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'He harhailivat sokeina kaduilla, verellä tahrattuina, niin ettei voinut koskea heidän vaatteisiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, '\"Väistykää! Saastainen!\" huudettiin heistä. \"Väistykää, väistykää, älkää koskeko!\" Paettuaankin he yhä harhailivat; pakanain seassa sanottiin: \"Eivät he saa kauemmin asustaa täällä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Herran kasvot ovat hajottaneet heidät, hän ei heihin enää katso. Papeista ei välitetty, vanhimpia ei armahdettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Vieläkin me, silmät rauenneina, turhaan odotimme apua; tähystyspaikastamme me tähyilimme kansaa, josta ei pelastusta tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Meidän askeleitamme vaanittiin, niin ettemme voineet kulkea kaduillamme. Meidän loppumme lähestyi, päivämme täyttyivät-niin, loppumme tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Meidän vainoojamme olivat nopeammat kuin kotkat taivaalla. Vuorilla he ajoivat meitä takaa, väijyivät meitä erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Hän, meidän elämänhenkemme, Herran voideltu, joutui vangiksi heidän kuoppiinsa, hän, josta me olimme sanoneet: hänen varjossaan me saamme elää pakanakansain seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Iloitse ja riemuitse, tytär Edom, joka asut Uusin maassa! Mutta malja on tuleva sinunkin kohdallesi: sinä juovut ja paljastat itsesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Sinun syntivelkasi, tytär Siion, on loppunut: ei Herra ole enää siirtävä sinua pois. Sinun syntivelkasi, tytär Edom, hän on etsiskelevä, on paljastava sinun syntisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Muista, Herra, mitä meille on tapahtunut; katso ja näe meidän häväistyksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Meidän perintöosamme on siirtynyt vieraille, meidän talomme muukalaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Me olemme tulleet orvoiksi, isättömiksi, meidän äitimme ovat kuin lesket.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Oman juomavetemme me ostamme rahalla; omat puumme saamme, jos maksamme hinnan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Vainoojamme ovat meidän niskassamme; kun uuvumme, ei meille lepoa suoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Egyptille me lyömme kättä ja Assurille saadaksemme leipää ravinnoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Meidän isämme ovat syntiä tehneet; heitä ei enää ole. Me kannamme heidän syntivelkaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Orjat hallitsevat meitä; ei ole sitä, joka tempaisi meidät heidän käsistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Henkemme kaupalla me noudamme leipämme, väistäen miekkaa erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Meidän ihomme halkeilee kuin uuni nälän poltteiden takia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Naisia raiskataan Siionissa, neitsyitä Juudan kaupungeissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Ruhtinaita heidän kätensä hirttävät, vanhinten kasvoja ei pidetä arvossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Nuorukaiset kantavat myllynkiviä, poikaset kompastelevat puutaakkojen alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Poissa ovat vanhukset porteista, nuorukaiset kielisoittimiensa äärestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Poissa on ilo sydämistämme, karkelomme on valitukseksi muuttunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Pudonnut on päästämme kruunu. Voi meitä, sillä me olemme syntiä tehneet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Tästä syystä on sydämemme tullut sairaaksi, näitten tähden ovat silmämme pimenneet-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Siionin vuoren tähden, joka on autiona, jolla ketut juoksentelevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Sinä, Herra, hallitset iankaikkisesti, sinun valtaistuimesi pysyy suvusta sukuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Miksi unhotat meidät ainiaaksi, hylkäät meidät ikipäiviksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Palauta meidät, Herra, tykösi, niin me palajamme; uudista meidän päivämme muinaiselleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Vai oletko meidät peräti hyljännyt, vihastunut meihin ylenmäärin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Kolmantenakymmenentenä vuotena, neljännessä kuussa, kuukauden viidentenä päivänä, kun minä olin pakkosiirtolaisten joukossa Kebar-joen varrella, aukenivat taivaat, ja minä näin Jumalan näkyjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Kuukauden viidentenä päivänä, kuningas Joojakinin pakkosiirtolaisuuden viidentenä vuotena,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'tuli Jumalan sana pappi Hesekielille, Buusin pojalle, Kaldean maassa Kebar-joen varrella, ja hänen päällensä tuli siellä Herran käsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Ja minä näin, ja katso: myrskytuuli tuli pohjoisesta, suuri pilvi ja leimahteleva tuli, ja pilveä ympäröitsi hohde, ja tulen keskeltä näkyi ikäänkuin hehkuvaa malmia, keskeltä tulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Ja sen keskeltä näkyivät neljän olennon hahmot. Ja näöltänsä ne olivat tällaiset: niillä oli ihmisen hahmo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Ja niillä oli neljät kasvot kullakin ja neljä siipeä kullakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Ja säärivarret niillä oli suorat ja jalkaterät kuin vasikansorkat, ja ne välkkyivät kuin kiiltävä vaski.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Ja siipiensä alla niillä oli, neljällä eri puolellansa, ihmiskädet. Kasvot ja siivet niillä neljällä olivat näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Niiden siivet koskettivat toisiansa. Kulkiessaan ne eivät kääntyneet: ne kulkivat kukin suoraan eteenpäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Ja niiden kasvot olivat ihmiskasvojen kaltaiset; mutta oikealla puolen oli niillä neljällä leijonankasvot, vasemmalla puolen oli niillä neljällä häränkasvot, myös oli niillä neljällä kotkankasvot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Niin niiden kasvot. Mutta siivet niillä oli levällään ylöspäin. Kullakin oli kaksi, jotka koskettivat toisen siipiä, ja kaksi, joilla ne peittivät ruumistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Ja ne kulkivat suoraan eteenpäin. Minne henki vaati kulkemaan, sinne ne kulkivat. Kulkiessaan ne eivät kääntyneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Ja olentojen hahmo oli näöltänsä kuin tuliset hiilet, jotka paloivat tulisoihtujen näköisinä. Tulta liekehti olentojen välissä, ja tuli hohti, ja tulesta lähti salamoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Ja olennot kiitivät edestakaisin ja olivat nähdä kuin salamanleimaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Mutta kun minä katselin olentoja, niin katso: yksi pyörä oli maassa olentojen kohdalla, kunkin niiden neljän etupuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Pyörät olivat näöltään ja teoltaan niinkuin krysoliitti, ja niillä neljällä oli sama muoto, ja ne olivat näöltään ja teoltaan, kuin olisi ollut sisäkkäin pyörä pyörässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Ne kulkivat neljään eri suuntaansa, kun kulkivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Kulkiessaan ne eivät kääntyneet. Ja niiden kehät olivat korkeat ja peljättävät; ja niiden kehät olivat täynnä silmiä, yltympäri, niissä neljässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Ja kun olennot kulkivat, kulkivat pyörät niiden ohella; ja kun olennot kohosivat ylös maasta, kohosivat myös pyörät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Minne henki vaati kulkemaan, sinne ne kulkivat-minne vain henki kulkemaan vaati. Ja pyörät kohosivat samalla kuin nekin, sillä olentojen henki oli pyörissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Kun olennot kulkivat, kulkivat nämäkin; kun ne seisoivat, seisoivat nämäkin; kun ne kohosivat ylös maasta, kohosivat pyörät samalla kuin nekin, sillä olentojen henki oli pyörissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Ja olentojen päitten ylle hahmottui taivaanvahvuus, niinkuin peljättävä kristalli, kaartuen ylös niiden päitten ylitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Ja taivaanvahvuuden alla oli niillä siivet suorina, toisen siipi toisen siipeä kohti. Kullakin oli kaksi, jotka sitä peittivät-kaksi, jotka peittivät sen ruumista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Ja minä kuulin niiden siipien kohinan niinkuin paljojen vetten kohinan, niinkuin Kaikkivaltiaan jylinän, kun ne kulkivat; pauhinan ääni oli niinkuin sotaleirin pauhu. Kun ne seisoivat, laskivat ne siipensä alas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Ja kuului ääni taivaanvahvuuden yläpuolelta, joka oli niitten pään päällä. -Kun ne seisoivat, laskivat ne siipensä alas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Ja taivaanvahvuuden yläpuolella, joka oli niitten pään päällä, oli valtaistuimen muotoinen, näöltään kuin safiirikiveä. Ja valtaistuimen muotoisella istui hahmo, ihmisen näköinen, kohoten korkealle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Ja minä näin ikäänkuin hehkuvaa malmia, tulen näköistä, jota ympäröi kehä ylöspäin siitä, mikä näytti hänen lanteiltansa; ja alaspäin siitä, mikä näytti hänen lanteiltansa, minä näin kuin tulen näköistä, ja sitä ympäröitsi hohde.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Kuin kaari, joka on pilvessä sadepäivänä, niin oli näöltään sitä ympäröivä hohde. Senkaltainen oli katsoa Herran kirkkauden hahmo. Ja kun minä sen näin, lankesin minä kasvoilleni. Ja minä kuulin äänen, kun joku puhui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Ja hän sanoi minulle: \"Ihmislapsi, nouse jaloillesi, niin minä puhuttelen sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Niin minuun tuli henki, kun hän puhui minulle, ja se nosti minut jaloilleni, ja minä kuulin hänen puhuvan minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Ja hän sanoi minulle: \"Ihmislapsi, minä lähetän sinut israelilaisten tykö, kapinallisten pakanain tykö, jotka ovat kapinoineet minua vastaan; he ja heidän isänsä ovat luopuneet minusta, hamaan tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Nuo lapset, joilla on kovat kasvot ja paatuneet sydämet-niitten luokse minä sinut lähetän, ja sinun on sanottava heille: Näin sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Kuulkoot tai olkoot kuulematta-sillä uppiniskainen suku he ovat-he tulevat kuitenkin tietämään, että profeetta on ollut heidän keskellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Mutta sinä, ihmislapsi, älä pelkää heitä, äläkä pelkää heidän sanojansa, vaikka edessäsi on ohdakkeita ja orjantappuroita ja sinä asut skorpionien seassa; älä pelkää heidän sanojansa äläkä arkaile heidän kasvojansa, sillä he ovat uppiniskainen suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Vaan puhu heille minun sanani, kuulkoot tai olkoot kuulematta; sillä uppiniskaisia he ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Mutta sinä, ihmislapsi, kuule, mitä minä sinulle sanon. Älä ole uppiniskainen, niinkuin uppiniskainen suku on. Avaa suusi ja syö, mitä minä sinulle annan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Niin minä näin, ja katso: käsi ojennettiin minua kohti, ja katso: siinä oli kirjakäärö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Ja hän levitti sen minun eteeni, ja katso: se oli kirjoitettu täyteen sisältä ja päältä. Ja siihen oli kirjoitettu itkuvirret ja huokaukset ja voi-huudot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Ja hän sanoi minulle: \"Ihmislapsi, syö, minkä tässä saat; syö tämä kirjakäärö, mene ja puhu Israelin heimolle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Niin minä avasin suuni, ja hän antoi tämän kirjakäärön minun syödäkseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Ja hän sanoi minulle: \"Ihmislapsi, ravitse vatsasi ja täytä sisälmyksesi tällä kirjakääröllä, jonka minä sinulle annan\". Niin minä söin, ja se oli minun suussani makea kuin hunaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Ja hän sanoi minulle: \"Ihmislapsi, mene nyt Israelin heimon tykö ja puhu heille minun sanani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Sillä ei sinua lähetetä outokielisen ja kankeapuheisen kansan tykö, vaan Israelin heimon tykö;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'ei monien kansojen tykö, outokielisten ja kankeapuheisten, joiden puhetta et ymmärrä. Jos niiden tykö lähettäisin sinut, he sinua kuulisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Mutta Israelin heimo ei tahdo sinua kuulla, koska he eivät tahdo minua kuulla. Sillä koko Israelin heimolla on kova otsa ja paatunut sydän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Katso, minä teen sinun kasvosi yhtä koviksi kuin heidän kasvonsa ja sinun otsasi yhtä kovaksi kuin heidän otsansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Timantin kaltaiseksi, kiveä kovemmaksi minä teen sinun otsasi. Älä pelkää heitä äläkä arkaile heidän kasvojansa, sillä he ovat uppiniskainen suku.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Ja hän sanoi minulle: \"Ihmislapsi, kaikki minun sanani, jotka minä sinulle puhun, ota sydämeesi ja kuule korvillasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Ja nyt mene pakkosiirtolaisten tykö, kansasi lasten tykö; puhu heille ja sano heille: Näin sanoo Herra, Herra-kuulkoot he tai olkoot kuulematta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Niin henki nosti minut, ja minä kuulin takaani suuren, jylisevän äänen: \"Kiitetty olkoon Herran kirkkaus, siinä kussa se on!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'ja olentojen siipien kohinan, kun ne löivät toisiinsa, samalla pyöräin jyrinän ja suuren, jylisevän äänen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Ja henki nosti minut ja otti minut, ja minä kuljin murheellisena henkeni kiivaudessa, ja Herran käsi oli väkevänä minun päälläni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Ja minä tulin Tell-Aabibiin pakkosiirtolaisten tykö, jotka asuivat Kebar-joen varrella; ja siellä, missä he asuivat, minä istuin jäykistyneenä heidän keskuudessaan seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Mutta seitsemän päivän kuluttua tuli minulle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, '\"Ihmislapsi, minä olen asettanut sinut Israelin heimolle vartijaksi. Kun kuulet sanan minun suustani, on sinun varoitettava heitä minun puolestani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Jos minä sanon jumalattomalle: sinun on kuolemalla kuoltava, mutta sinä et häntä varoita etkä puhu varoittaaksesi jumalatonta hänen jumalattomasta tiestänsä, että pelastaisit hänen henkensä, niin jumalaton kuolee synnissänsä, mutta hänen verensä minä vaadin sinun kädestäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Mutta jos sinä varoitat jumalatonta ja hän ei käänny jumalattomuudestansa eikä jumalattomalta tieltänsä, niin hän kuolee synnissänsä, mutta sinä olet sielusi pelastanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Ja jos vanhurskas kääntyy pois vanhurskaudestansa ja tekee vääryyttä ja minä panen kompastuksen hänen eteensä, niin hän kuolee-kun et sinä häntä varoittanut, niin hän synnissänsä kuolee, ja vanhurskautta, jota hän oli harjoittanut, ei muisteta-mutta hänen verensä minä vaadin sinun kädestäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Mutta jos sinä vanhurskasta varoitat, ettei vanhurskas tekisi syntiä, ja hän ei tee syntiä, niin hän totisesti saa elää, koska otti varoituksesta vaarin, ja sinä olet sielusi pelastanut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Herran käsi tuli siellä minun päälleni, ja hän sanoi minulle: \"Nouse ja mene laaksoon, niin minä siellä puhuttelen sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Niin minä nousin ja menin laaksoon, ja katso, siellä seisoi Herran kirkkaus, samankaltainen kuin kirkkaus, jonka minä olin nähnyt Kebar-joen varrella. Ja minä lankesin kasvoilleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Mutta minuun tuli henki ja nosti minut jaloilleni, ja hän puhutteli minua ja sanoi minulle: \"Mene, sulkeudu sisälle huoneeseesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Ja sinä, ihmislapsi! Katso, sinut pannaan köysiin ja sidotaan niillä, niin ettet voi mennä ulos heidän keskuuteensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Ja minä tartutan sinun kielesi suusi lakeen, niin että mykistyt etkä voi olla heille nuhtelijana, sillä he ovat uppiniskainen suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Mutta kun minä puhuttelen sinua, avaan minä sinun suusi, ja sinun on sanottava heille: Näin sanoo Herra, Herra. Kuulkoon, joka kuulee, ja olkoon kuulematta, joka ei kuule; sillä he ovat uppiniskainen suku.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, '\"Ja sinä, ihmislapsi, ota itsellesi tiilikivi ja aseta se eteesi ja piirrä siihen kaupunki, Jerusalem.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Ja pane se piirityksiin, rakenna sitä vastaan saartovarusteet, luo sitä vastaan valli, aseta sitä vastaan sotaleirejä ja pane sitä vastaan yltympäri muurinmurtajia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Ota sitten itsellesi rautainen leivinlevy ja aseta se rautamuuriksi itsesi ja kaupungin väliin ja suuntaa kasvosi kaupunkia kohti, niin että se tulee piirityksiin, ja piiritä sitä. Tämä on oleva merkki Israelin heimolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Ja sinä pane maata vasemmalle kyljellesi ja aseta sitä painamaan Israelin heimon syntivelka. Yhtä monta päivää, kuin sinä makaat sillä, on sinun kannettava heidän syntivelkaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Ja minä panen sinulle saman luvun päiviä, kuin on heidän syntivelkansa vuosia: kolmesataa yhdeksänkymmentä päivää; niin sinun on kannettava Israelin heimon syntivelkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Ja kun olet saanut ne päättymään, on sinun pantava maata toistamiseen, oikealle kyljellesi, ja kannettava Juudan heimon syntivelkaa neljäkymmentä päivää; päivän kutakin vuotta kohti minä olen sinulle pannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Ja suuntaa kasvosi ja paljastettu käsivartesi piiritettyä Jerusalemia kohti ja ennusta sitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Ja katso, minä panen sinut köysiin, niin ettet voi kääntyä kyljeltä toiselle, kunnes olet saanut päättymään piirityspäiväsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Ota sinä myös itsellesi nisuja, ohria, papuja, herneitä, hirssiä ja kolmitahkoista vehnää, pane ne samaan astiaan ja tee niistä itsellesi leipää. Yhtä monta päivää, kuin makaat kyljelläsi, kolmesataa yhdeksänkymmentä päivää, on sinun syötävä sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Ja ruoka, jota syöt, on sinun syötävä painon mukaan: kaksikymmentä sekeliä päivässä; sinun on syötävä se määräaikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Ja vettä sinun on juotava mitan mukaan: kuudennes hiin-mittaa; sinun on juotava määräaikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Ja ohrakaltiaisena on sinun se syötävä, ja ihmisulostuksella on sinun se paistettava heidän silmäinsä edessä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Ja Herra sanoi: \"Näin tulevat israelilaiset syömään leipänsä saastaisena pakanain joukossa, jonne minä heidät karkoitan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Mutta minä sanoin: \"Voi Herra, Herra! Katso, ei milloinkaan ole minun sieluni ollut saastutettu, minä en ole syönyt itsestään kuollutta enkä kuoliaaksi raadeltua nuoruudestani tähän asti, eikä ole mitään saastaista lihaa minun suuhuni tullut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Niin hän sanoi minulle: \"Katso, minä annan sinulle eläimen lannan ihmisen jäljen sijaan; valmista leipäsi sen päällä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Ja hän sanoi minulle: \"Ihmislapsi, katso, minä murran leivän tuen Jerusalemilta, ja he saavat syödä leipää painon mukaan ja huolissansa sekä juoda vettä mitan mukaan ja kauhuissansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'niin että he joutuvat leivän ja veden puutteeseen ja yhdessä nääntyvät ja riutuvat syntivelkansa tähden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, '\"Ja sinä, ihmislapsi, ota itsellesi terävä miekka; ota se partaveitseksesi, ja ajele sillä hiuksesi ja partasi. Ota sitten vaaka ja jaa ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Polta kolmannes tulessa keskellä kaupunkia, sittenkuin piirityspäivät ovat lopussa. Kolmannes ota ja lyö miekalla sen ympärillä. Kolmannes hajota tuuleen, ja minä ajan niitä takaa paljastetulla miekalla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'ota niistä sitten vähäinen määrä ja sido ne helmukseesi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'ja ota niistä vielä osa, viskaa ne tuleen ja polta ne tulessa. Siitä lähtee tuli koko Israelin heimoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Näin sanoo Herra, Herra: Tämä on Jerusalem; pakanain keskelle minä olen sen asettanut, ja niiden maat ovat sen ympärillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Mutta se on niskoitellut minun oikeuksiani vastaan jumalattomammin kuin pakanat ja minun käskyjäni vastaan jumalattomammin kuin maat, jotka ovat sen ympärillä; sillä minun oikeuteni he ovat pitäneet halpoina ja minun käskyjeni mukaan he eivät ole vaeltaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Sentähden, näin sanoo Herra, Herra: Koska teidän metelinne on ollut pahempi kuin pakanain, jotka ympärillänne ovat, ja koska te ette ole vaeltaneet minun käskyjeni mukaan, ette ole noudattaneet minun oikeuksiani ettekä ole tehneet niiden pakanainkaan oikeuksien mukaan, jotka ympärillänne ovat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'sentähden, näin sanoo Herra, Herra: Katso, myös minä käyn sinun kimppuusi ja teen tuomiot sinun keskelläsi pakanain silmien edessä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'ja teen sinulle kaikkien kauhistustesi tähden, mitä en ole ennen tehnyt ja minkäkaltaista en vasta ole tekevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Sentähden tulevat sinun keskelläsi isät syömään lapsiansa, ja lapset tulevat syömään isiänsä, ja minä teen sinussa tuomiot ja hajotan sinun jäännöksesi kaikkiin tuuliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Sentähden, niin totta kuin minä elän, sanoo Herra, Herra: Totisesti, koska olet saastuttanut minun pyhäkköni kaikilla iljetyksilläsi ja kaikilla kauhistuksillasi, käännyn minäkin pois, en sääli enkä armahda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Kolmannes sinusta kuolee ruttoon ja nääntyy nälkään sinun keskelläsi. Kolmannes kaatuu miekkaan sinun ympärilläsi. Kolmanneksen minä hajotan kaikkiin tuuliin, ja minä ajan niitä takaa paljastetulla miekalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Ja minun vihani täyttyy, ja minä tyydytän kiivauteni heissä ja kostan. Ja he tulevat tietämään, että minä, Herra, olen puhunut kiivaudessani, kun minä panen vihani täytäntöön heissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Ja minä teen sinut raunioksi ja häväistyksi pakanain kesken, jotka sinun ympärilläsi ovat, jokaisen ohikulkijan silmäin edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Ja se on oleva häväistys ja herjaus, varoitus ja peljätys pakanain seassa, jotka ympärilläsi ovat, kun minä teen sinussa tuomiot vihassa ja kiivaudessa ja kiivailla rangaistuksilla-minä, Herra, olen puhunut-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'kun minä lähetän heidän kimppuunsa nälän pahat nuolet, joista tulee tuhooja ja jotka minä lähetän teitä tuhoamaan; ja minä vielä lisään teille nälkää ja murran teiltä leivän tuen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Ja minä lähetän teidän kimppuunne nälän ja pahat petoeläimet, jotka riistävät sinulta lapset; rutto ja veri käyvät sinun ylitsesi, ja minä annan miekan tulla sinun ylitsesi. Minä, Herra, olen puhunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, '\"Ihmislapsi, käännä kasvosi Israelin vuoria kohti ja ennusta niitä vastaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'ja sano: Israelin vuoret, kuulkaa Herran, Herran sana. Näin sanoo Herra, Herra vuorille ja kukkuloille, puronotkoille ja laaksoille: Katso, minä annan miekan tulla teidän ylitsenne ja hävitän teidän uhrikukkulanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Teidän alttarinne jäävät autioiksi, auringonpatsaanne murskataan, ja teidän surmattujenne minä annan kaatua teidän kivijumalainne eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Minä panen israelilaisten ruumiit heidän kivijumalainsa eteen ja hajotan heidän luunsa heidän alttariensa ympärille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Kaikilla teidän asuinpaikoillanne tulevat kaupungit raunioiksi ja uhrikukkulat autioiksi; niin jäävät teidän alttarinne raunioiksi ja autioiksi, teidän kivijumalanne murskataan ja hävitetään, teidän auringonpatsaanne särjetään, ja teidän tekeleenne pyyhkäistään pois,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'surmattuja kaatuu teidän keskellänne, ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Mutta minä jätän jäännöksen: teillä on oleva miekasta pelastuneita pakanain seassa, kun teidät on hajotettu niiden maihin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'ja ne teistä, jotka pelastuvat, muistavat minut pakanain seassa, mihin ovat vangeiksi viedyt, sillä minä särjen heidän haureellisen sydämensä, joka poikkesi minusta pois, ja heidän silmänsä, jotka haureellisina kulkivat heidän kivijumalainsa jäljessä. Ja heitä kyllästyttää oma itsensä pahain töitten tähden, joita he ovat tehneet, kaikkien heidän kauhistustensa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Ja he tulevat tietämään, että minä olen Herra; en ole turhaan puhunut, että minä tuotan teille tämän onnettomuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Näin sanoo Herra, Herra: Paukuta käsiäsi ja polje jalkaasi ja sano: \'voi!\' kaikista Israelin heimon häijyistä kauhistuksista, heidän, jotka kaatuvat miekkaan, nälkään ja ruttoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Kaukainen kuolee ruttoon, läheinen kaatuu miekkaan, jäljellejäänyt ja säilynyt kuolee nälkään, ja minä panen vihani täytäntöön heissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Ja te tulette tietämään, että minä olen Herra, kun heitä on surmattuina heidän kivijumalainsa keskellä, heidän alttariensa ympärillä, jokaisella korkealla kukkulalla, kaikilla vuorten huipuilla, jokaisen viheriän puun alla ja jokaisen tuuhean tammen alla, missä paikassa vain he ovat tarinneet suloista tuoksua kaikille kivijumalillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Ja minä ojennan käteni heitä vastaan ja teen maan autiommaksi ja hävitetymmäksi, kuin on Diblatan erämaa, kaikilla heidän asuinpaikoillansa; ja he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, '\"Sinä, ihmislapsi, näin sanoo Herra, Herra Israelin maalle: Loppu! Maan neljälle äärelle tulee loppu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Nyt tulee sinulle loppu, ja minä lähetän vihani sinua vastaan, tuomitsen sinut vaelluksesi mukaan ja annan kaikkien kauhistustesi kohdata sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'En sääli sinua enkä armahda, vaan annan vaelluksesi kohdata sinua, ja kauhistuksesi tulevat sinun keskellesi, ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Näin sanoo Herra, Herra: Onnettomuus! Yksi ja ainoa onnettomuus! Katso, se tulee!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Loppu tulee, tulee loppu! Se heräjää sinua vastaan! Katso, se tulee!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Vuoro tulee sinulle, maan asuja. Aika tulee, päivä on lähellä: hämminki, ei ilohuuto vuorilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Nyt minä kohta vuodatan kiivauteni sinun ylitsesi, panen vihani täytäntöön sinussa, tuomitsen sinut vaelluksesi mukaan ja annan kaikkien kauhistustesi kohdata sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'En sääli enkä armahda; minä annan vaelluksesi kohdata sinua, ja kauhistuksesi tulevat sinun keskellesi, ja te tulette tietämään, että minä, Herra, olen se, joka lyön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Katso, päivä! Katso, se tulee! Vuoro on tullut, vitsa kukkii, julkeus versoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Väkivalta on noussut vitsaksi jumalattomuudelle, ei mitään jää heistä, ei heidän pauhaavasta joukostansa, ei heidän melustansa; poissa on heidän komeutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Tullut on aika, joutunut päivä, älköön ostaja iloitko, älköön myyjä murehtiko, sillä viha tulee kaiken siellä pauhaavan joukon ylitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Sillä myyjä ei enää palaja myynnöksillensä, vaikka he vielä jäisivätkin henkiin, sillä näky kaikkea sen pauhaavaa joukkoa vastaan ei peräydy, eikä kukaan synnillänsä vahvista elämäänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Puhalletaan torviin, varustetaan kaikki, mutta ei ole lähtijää sotaan, sillä minun vihani tulee kaiken siellä pauhaavan joukon ylitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Miekka on ulkona, sisällä rutto ja nälkä. Kedolla oleva kuolee miekkaan, kaupungissa olevan syö nälkä ja rutto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Ja jos heitä joitakin pelastuu ja pääsee pakoon, ovat he vuorilla kuin laaksojen kyyhkyset, ja he vaikertelevat kaikki, syntiänsä kukin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Kaikki kädet herpoavat, kaikki polvet käyvät veltoiksi kuin vesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'He kääriytyvät säkkeihin, heidät peittää vavistus, kaikilla kasvoilla on häpeä, ja kaikki päät ovat paljaiksi ajellut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Hopeansa he viskaavat kaduille, ja heidän kultansa tulee heille saastaksi. Heidän kultansa ja hopeansa eivät voi heitä pelastaa Herran vihan päivänä, eivät he sillä nälkäänsä tyydytä eivätkä vatsaansa täytä; sillä siitä tuli heille kompastus syntiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Siitä tehtyjen korujen loistolla he ylpeilivät, siitä he tekivät kauhistavat kuvansa, iljetyksensä; sentähden minä teen sen heille saastaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Ja minä annan sen vieraitten käsiin ryöstettäväksi ja maan jumalattomien saaliiksi, ja ne häpäisevät sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Minä käännän kasvoni heistä pois, niin että minun aarteeni häväistään: väkivaltaiset menevät sinne ja häpäisevät sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Valmista kahle, sillä maa on täynnä verivelkain tuomiota, ja kaupunki on täynnä väkivaltaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Ja minä tuon pakanoista pahimmat, ja ne ottavat omiksensa teidän talonne. Minä teen lopun voimallisten ylpeydestä, ja heidän pyhäkkönsä häväistään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Tulee hätä, ja he etsivät pelastusta, mutta sitä ei ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Häviö tulee häviön jälkeen, sanoma tulee sanoman jälkeen. He havittelevat näkyä profeetalta; papilta katoaa opetus ja vanhimmilta neuvo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Kuningas murehtii, päämies pukeutuu kauhuun, ja maan kansan kädet pelosta vapisevat. Minä teen heille heidän teittensä mukaan, ja tuomitsen heidät heidän tuomioittensa mukaan, ja he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Kuudentena vuotena, kuudennessa kuussa, kuukauden viidentenä päivänä minä istuin huoneessani, ja Juudan vanhimmat istuivat minun edessäni; silloin Herran, Herran käsi laskeutui siellä minun päälleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Ja minä näin, ja katso: tulennäköinen hahmo! Ja alaspäin siitä, mikä näytti sen lanteilta, oli tulta, ja ylöspäin sen lanteista näkyi loiste, joka oli nähdä niinkuin hehkuva malmi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Hän ojensi ikäänkuin käden ja otti minua pääni hiussuortuvasta, ja henki nosti minut maan ja taivaan välille ja vei minut Jerusalemiin Jumalan näyissä, sisemmän portin ovelle, joka on pohjoista kohden, sinne missä oli kiivauspatsas, joka oli herättänyt Herran kiivauden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Ja katso, siellä oli Israelin Jumalan kirkkaus, samankaltainen nähdä kuin se, minkä minä olin nähnyt laaksossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Hän sanoi minulle: \"Ihmislapsi, nosta silmäsi pohjoista kohti\". Niin minä nostin silmäni pohjoista kohti, ja katso: pohjoiseen päin alttariportista oli tuo kiivauspatsas sisäänkäytävässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Ja hän sanoi minulle: \"Ihmislapsi, näetkö sinä, mitä he tekevät-suuria kauhistuksia, joita Israelin heimo tekee täällä, että minä menisin kauas pois pyhäköstäni? Mutta sinä saat nähdä vielä suurempia kauhistuksia.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Ja hän vei minut esipihan ovelle, ja minä näin, ja katso: seinässä oli jokin aukko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Ja hän sanoi minulle: \"Ihmislapsi, murtaudu läpi seinän\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Niin minä murtauduin läpi seinän, ja katso: jokin ovi! Ja hän sanoi minulle: \"Mene ja katso häijyjä kauhistuksia, joita he täällä tekevät\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Niin minä menin ja näin, ja katso: kaikenkaltaisia inhottavia matelijain ja karjaeläinten kuvia ja kaikenkaltaisia Israelin heimon kivijumalia oli piirretty seinään yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Ja niiden edessä seisoi seitsemänkymmentä miestä, Israelin heimon vanhimpia, ja näiden keskellä seisoi Jaasanja, Saafanin poika; ja kullakin heillä oli suitsutusastiansa kädessään, ja suitsutuspilvestä nousi tuoksu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Niin hän sanoi minulle: \"Näetkö, ihmislapsi, mitä Israelin heimon vanhimmat tekevät pimeässä, itsekukin kuvakammiossansa? Sillä he sanovat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, '\'Ei Herra meitä näe; Herra on hyljännyt tämän maan\'.\" Ja hän sanoi minulle: \"Sinä saat nähdä vieläkin suurempia kauhistuksia, joita he tekevät\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Ja hän vei minut Herran huoneen portin ovelle, joka on pohjoista kohden, ja katso: siellä istui naisia itkemässä Tammusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Ja hän sanoi minulle: \"Näetkö, ihmislapsi? Vieläkin sinä saat nähdä kauhistuksia, vielä suurempia kuin nämä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Ja hän vei minut Herran huoneen sisemmälle esipihalle, ja katso: Herran temppelin ovella, eteisen ja alttarin välillä, oli noin kaksikymmentä viisi miestä. Heillä oli selät Herran temppeliin päin ja kasvot itään päin, ja päin itää he kumarsivat aurinkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Ja hän sanoi minulle: \"Näitkö, ihmislapsi? Eikö ole Juudan heimolle kylliksi, että he tekevät kauhistuksia, joita täällä on tehty, koska he täyttävät maan väkivallalla ja niin aina uudelleen vihoittavat minut? Katso, kuinka he vievät viiniköynnöksen lehvää nenänsä eteen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Mutta minäkin teen, minkä teen, vihassani: en sääli enkä armahda; ja vaikka he huutavat minun korviini suurella äänellä, minä en heitä kuule.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Sitten hän huusi suurella äänellä minun korviini ja sanoi: \"Tulkaa, kaupungin rankaisijat, ja kullakin olkoon tuhoaseensa kädessään!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Ja katso, kuusi miestä tuli Yläportilta päin, joka on pohjoista kohden, ja kullakin oli kädessä hävitysaseensa. Mutta yksi mies oli heidän keskellään, puettu pellavavaatteisiin ja vyöllänsä kirjoitusneuvot. Ja he tulivat ja asettuivat seisomaan vaskialttarin ääreen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Mutta Israelin Jumalan kirkkaus oli kohonnut yläpuolelta kerubin, jonka yllä se oli ollut, huoneen kynnykselle ja huusi pellavavaatteisiin puetulle miehelle, jolla oli kirjoitusneuvot vyöllänsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'ja Herra sanoi hänelle: \"Kierrä kaupungin, Jerusalemin, läpi ja tee merkki niitten miesten otsiin, jotka huokaavat ja valittavat kaikkia kauhistuksia, mitä sen keskuudessa tehdään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Ja niille toisille hän sanoi minun kuulteni: \"Kiertäkää kaupungin läpi hänen jäljessään ja surmatkaa. Älkää säälikö, älkää armahtako,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'tappakaa tyyten vanhukset, nuorukaiset, neitsyet, lapset ja vaimot, mutta älkää koskeko keneenkään, jolla on otsassaan merkki; ja alottakaa minun pyhäköstäni.\" Niin he alottivat niistä miehistä, vanhimmista, jotka olivat temppelin edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Ja hän sanoi heille: \"Saastuttakaa temppeli ja täyttäkää esipihat surmatuilla. Menkää!\" Niin he menivät ja surmasivat kaupungissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Mutta kun minä heidän surmatessaan olin jäänyt jäljelle, lankesin minä kasvoilleni, huusin ja sanoin: \"Voi Herra, Herra! Hävitätkö sinä Israelin koko jäännöksen, kun vuodatat vihasi Jerusalemin ylitse?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Niin hän sanoi minulle: \"Israelin ja Juudan heimon syntivelka on ylen suuri; maa on täynnä verivelkoja, ja kaupunki on täynnä oikeuden vääristelyä, sillä he sanovat: \'Herra on hyljännyt tämän maan, ei Herra näe\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Niinpä minäkään en sääli enkä armahda. Minä annan heidän vaelluksensa tulla heidän oman päänsä päälle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Ja katso, pellavavaatteisiin puettu mies, jolla oli kirjoitusneuvot vyöllänsä, toi tämän sanan: \"Minä olen tehnyt, niinkuin sinä käskit minun tehdä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Sitten minä näin, ja katso: taivaanvahvuuden yläpuolella, joka oli kerubien pään päällä, oli ikäänkuin safiirikivi, näöltään valtaistuimen kaltainen; se näkyi heidän yläpuolellansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Ja hän sanoi pellavavaatteisiin puetulle miehelle näin: \"Mene rattaiden väliin, kerubin alle ja täytä kahmalosi tulisilla hiilillä kerubien välistä ja sirottele ne yli kaupungin\". Niin hän meni minun silmäini edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Ja kerubit seisoivat temppelin oikealla puolella, kun mies meni; ja pilvi peitti sisemmän esipihan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Ja Herran kirkkaus kohosi kerubin yltä temppelin kynnykselle, ja pilvi täytti temppelin, ja esipiha tuli täyteen Herran kirkkauden hohdetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Ja kerubien siipien kohina kuului ulompaan esipihaan asti kuin kaikkivaltiaan Jumalan ääni, kun hän puhuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Ja kun hän käski pellavavaatteisiin puettua miestä sanoen: \"Ota tulta rattaiden välistä, kerubien välistä\", niin tämä meni ja seisahtui pyörän ääreen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Ja kerubi ojensi kätensä kerubien välitse tuleen, joka oli kerubien välissä, otti sitä ja antoi pellavavaatteisiin puetun kahmaloon. Tämä otti sen ja meni ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Silloin näkyi kerubeilla ikäänkuin ihmiskäsi heidän siipiensä alta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Ja minä näin, ja katso: kerubien kohdalla oli neljä pyörää, yksi pyörä aina yhden kerubin ohella, ja pyörät olivat näöltään niinkuin krysoliittikivi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Ja niillä neljällä näytti olevan sama muoto, niinkuin olisi ollut sisäkkäin pyörä pyörässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Ne kulkivat neljään eri suuntaansa, kun kulkivat. Kulkiessaan ne eivät kääntyneet, sillä minnepäin etumainen meni, sinne ne kulkivat sen jäljessä; ne eivät kääntyneet kulkiessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Ja niillä oli koko ruumis ja selät ja kädet ja siivet ja pyörät täynnä silmiä, yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Niillä neljällä oli pyöränsä; ja pyöriä nimitettiin minun kuulteni \"rattaiksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Ja kullakin oli neljät kasvot: yhdet kerubinkasvot, toiset ihmiskasvot, kolmannet leijonankasvot ja neljännet kotkankasvot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Ja kerubit kohosivat-ne olivat samat olennot, jotka minä olin nähnyt Kebar-joen varrella. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Kun kerubit kulkivat, kulkivat pyörät niiden ohella, ja kun kerubit nostivat siipensä kohotaksensa ylös maasta, eivät myöskään pyörät kääntyneet pois niiden ohelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Kun ne seisahtuivat, seisahtuivat nämäkin, ja kun ne kohosivat, kohosivat nämä niiden kanssa, sillä olentojen henki oli näissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Sitten Herran kirkkaus lähti temppelin kynnykseltä ja asettui kerubien ylle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Ja lähtiessään kerubit nostivat siipensä ja kohosivat maasta minun silmäini edessä, ja pyörät samalla kuin ne; ja ne seisahtuivat Herran huoneen itäportin ovelle, ja niiden yläpuolella oli Israelin Jumalan kirkkaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Nämä olivat samat olennot, jotka minä olin nähnyt Israelin Jumalan alla Kebar-joen varrella; ja minä tulin tietämään, että ne olivat kerubeja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Neljät kasvot oli kullakin ja neljä siipeä kullakin, ja niiden siipien alla oli ikäänkuin ihmiskädet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Ja niiden kasvot olivat muodoltaan samat, jotka minä olin nähnyt-sekä niiden näön että ne itsensä-Kebar-joen varrella. Ne kulkivat kukin suoraan eteenpäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Sitten Henki nosti minut ja vei minut Herran huoneen itäportille, joka on itään päin. Ja katso: portin ovella oli kaksikymmentä viisi miestä, ja minä näin niitten keskellä Jaasanjan, Assurin pojan, ja Pelatjan, Benajan pojan, kansan päämiehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Ja hän sanoi minulle: \"Ihmislapsi, nämä ovat ne miehet, jotka miettivät turmiota ja pitävät pahaa neuvoa tätä kaupunkia vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'jotka sanovat: \'Ei ole nyt kohta rakennettava taloja: se on pata, me olemme liha\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Sentähden ennusta heitä vastaan, ennusta, ihmislapsi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Niin Herran Henki laskeutui minun päälleni ja sanoi minulle: \"Sano: Näin sanoo Herra: Näin te, Israelin heimo, sanotte, ja minä tunnen, mitä teidän hengestänne nousee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Paljon on teidän surmaamianne tässä kaupungissa, ja sen kadut te olette surmatuilla täyttäneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Sentähden, näin sanoo Herra, Herra: Surmattunne, jotka te olette heittäneet sen keskelle, ne ovat liha, ja tämä kaupunki on pata, mutta teidät minä sen keskeltä vien pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Miekkaa te pelkäätte, mutta miekan minä annan tulla teidän päällenne, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Pois minä vien teidät sen keskeltä ja annan teidät muukalaisten käsiin ja teen teidän seassanne tuomiot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Te kaadutte miekkaan, Israelin rajalla minä teidät tuomitsen; ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Ei tämä tule teille padaksi ettekä te siihen lihaksi: Israelin rajalla minä teidät tuomitsen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Ja te tulette tietämään, että minä olen Herra-te, jotka ette ole vaeltaneet minun käskyjeni mukaan ettekä ole tehneet minun oikeuksieni mukaan, vaan olette tehneet niiden pakanain oikeuksien mukaan, jotka ovat teidän ympärillänne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Kun minä ennustin, niin Pelatja, Benajan poika, kuoli. Niin minä lankesin kasvoilleni, huusin kovalla äänellä ja sanoin: \"Voi Herra, Herra! Aivanko sinä teet lopun Israelin jäännöksestä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Sitten tuli minulle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, '\"Ihmislapsi, sinun veljesi, sinun veljesi, sukulaisesi ja koko Israelin heimo, kaikki, joille Jerusalemin asukkaat sanovat: \'Olkaa te vain kaukana Herrasta, meille on tämä maa annettu perinnöksi!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Sano sentähden: Näin sanoo Herra, Herra: Koska minä olen vienyt heidät kauas pakanain sekaan ja hajottanut heidät muihin maihin, olen minä ollut heille pyhäkkönä vähän aikaa niissä maissa, joihin he ovat joutuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Sano sentähden: Näin sanoo Herra, Herra: Minä kokoan teidät kansojen seasta ja kerään teidät maista, joihin teidät on hajotettu, ja annan teille Israelin maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Ja he tulevat sinne ja poistavat siitä kaikki sen iljetykset ja kaikki sen kauhistukset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Ja minä annan heille yhden sydämen, ja uuden hengen minä annan teidän sisimpäänne, ja minä poistan kivisydämen heidän ruumiistansa ja annan heille lihasydämen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'niin että he vaeltavat minun käskyjeni mukaan ja noudattavat minun oikeuksiani ja pitävät ne; ja he ovat minun kansani, ja minä olen heidän Jumalansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Mutta joitten sydän vaeltaa heidän iljetystensä ja kauhistustensa mieltä myöten, niitten vaelluksen minä annan tulla heidän oman päänsä päälle, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Sitten kerubit nostivat siipensä ja pyörät samalla kuin ne, ja Israelin Jumalan kirkkaus oli heidän yläpuolellansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'ja Herran kirkkaus kohosi ylös, pois kaupungin keskeltä, ja asettui vuorelle, joka on itään päin kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Mutta Henki nosti ja vei minut Kaldeaan pakkosiirtolaisten tykö, näyssä, Jumalan Hengen voimalla; ja näky, jonka olin nähnyt, katosi minulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Ja minä puhuin pakkosiirtolaisille kaikki Herran sanat, jotka hän oli minulle näyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, '\"Ihmislapsi, sinä asut uppiniskaisen suvun keskellä, niiden, joilla on silmät nähdä, mutta eivät näe, ja korvat kuulla, mutta eivät kuule; sillä he ovat uppiniskainen suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Sinä, ihmislapsi, tee itsellesi matkavarusteet ja mene päiväiseen aikaan heidän silmäinsä edessä pakkosiirtolaisuuteen; sinun on mentävä pakkosiirtolaisuuteen omalta paikkakunnaltasi toiseen paikkakuntaan heidän silmäinsä edessä. Ehkäpä he näkevät sen, sillä he ovat uppiniskainen suku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Ja vie ulos varusteesi, niinkuin pakkosiirtolaiset varusteensa, päiväiseen aikaan heidän silmäinsä edessä; mutta lähde itse illalla heidän silmäinsä edessä, niinkuin pakkosiirtolaiset lähtevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Murtaudu läpi seinän heidän silmäinsä edessä ja vie ne siitä ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Nosta ne hartioillesi heidän silmäinsä edessä ja vie ulos pilkkopimeässä; peitä kasvosi, niin ettet näe maata. Sillä ennusmerkiksi minä olen sinut pannut Israelin heimolle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Ja minä tein, niinkuin minua oli käsketty: minä vein ulos päiväiseen aikaan varusteeni, niinkuin pakkosiirtolaiset varusteensa, mutta illalla minä murtauduin käsin läpi seinän; pilkkopimeässä minä ne vein ulos, minä nostin ne hartioilleni heidän silmäinsä edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Mutta aamulla minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, '\"Ihmislapsi, eikö ole Israelin heimo, uppiniskainen suku, sinulle sanonut: \'Mitä sinä teet?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Sano heille: Näin sanoo Herra, Herra: Ruhtinasta, joka on Jerusalemissa, koskee tämä ennustus ja kaikkea Israelin heimoa, mikä on heidän keskuudessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Sano: Minä olen teille ennusmerkki: niinkuin minä tein, niin heille tehdään, pakkosiirtolaisuuteen, vankeuteen he menevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Ruhtinas, joka on heidän keskellänsä, nostaa nostettavansa hartioilleen ja lähtee ulos pilkkopimeässä; seinästä he murtautuvat läpi, viedäkseen siitä ulos vietävänsä. Kasvonsa hän peittää, koska hän ei ole silmillänsä näkevä maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Minä levitän verkkoni hänen ylitsensä, ja hän takertuu minun pyydykseeni; minä vien hänet Baabeliin, kaldealaisten maahan, mutta sitä hän ei saa nähdä, ja sinne hän kuolee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Ja kaikki, keitä hänellä on ympärillään apunansa, ja kaikki hänen sotajoukkonsa minä hajotan kaikkiin tuuliin, ja minä ajan niitä takaa paljastetulla miekalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Ja he tulevat tietämään, että minä olen Herra, kun minä hajotan heidät pakanain sekaan ja sirotan heidät muihin maihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Mutta vähäisen määrän heitä minä jätän miekasta, nälästä ja rutosta jäljelle kertomaan pakanain seassa, siellä, minne he joutuvat, kaikista kauhistuksistansa; ja ne tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, '\"Ihmislapsi, syö leipäsi vavisten, juo vetesi väristen ja huolenalaisena');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'ja sano maan kansalle: Näin sanoo Herra, Herra Jerusalemin asukkaista Israelin maassa: He tulevat syömään leipänsä huolenalaisina ja juomaan vetensä kauhun vallassa, ja sen maa tulee autioksi kaikesta, mitä siinä on, kaikkien siinä asuvaisten väkivaltaisuuden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Asutut kaupungit joutuvat raunioiksi, ja maa tulee autioksi; ja te tulette tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, '\"Ihmislapsi, miksi teillä on tämä pilkkalause Israelin maasta, kun sanotte: \'Aika venyy pitkälle, ja tyhjään raukeavat kaikki näyt?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Sentähden sano heille: Näin sanoo Herra, Herra: Minä teen lopun tästä pilkkalauseesta, niin ettei sitä enää lausuta Israelissa. Sano heille päinvastoin: Lähellä on aika ja kaikkien näkyjen täyttymys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Sillä ei ole oleva enää petollista näkyä, ei liukasta ennustelua Israelin heimon keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Sillä minä, Herra, minä puhun; ja minkä sanan minä puhun, se tapahtuu eikä enää viivy. Sillä teidän aikananne, uppiniskainen suku, minä sanan puhun ja sen myös täytän, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, '\"Ihmislapsi, katso, Israelin heimo sanoo: \'Niihin näkyihin, joita tämä näkee, on päiviä paljon, ja hän ennustaa kaukaisista ajoista\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Sentähden sano heille: Näin sanoo Herra, Herra: Ei viivy enää yksikään minun sanani: Minkä sanan minä puhun, se tapahtuu, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, '\"Ihmislapsi, ennusta Israelin ennustavista profeetoista ja sano noille, jotka ovat profeettoja oman sydämensä voimasta: Kuulkaa Herran sana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Näin sanoo Herra, Herra: Voi profeettahoukkia, jotka seuraavat omaa henkeänsä ja sitä, mitä eivät ole nähneet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Niinkuin ketut raunioissa ovat sinun profeettasi, Israel.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Te ette ole nousseet muurin aukkoihin ettekä korjanneet muuria Israelin heimon ympärillä, että se kestäisi sodassa, Herran päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Mitä he ovat nähneet, on petosta, ja heidän ennustelunsa on valhetta, kun he sanovat: \'Näin sanoo Herra\', vaikka Herra ei ole heitä lähettänyt; ja he muka odottavat, että hän toteuttaisi heidän sanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Ettekö ole petollisia näkyjä nähneet ja valhe-ennusteluja puhuneet, kun olette sanoneet: \'Näin sanoo Herra\', vaikka minä en ole puhunut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Sentähden, näin sanoo Herra, Herra: Koska te olette puhuneet petosta ja nähneet valhenäkyjä, niin sentähden, katso, minä käyn teidän kimppuunne, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Minun käteni on profeettoja vastaan, jotka petosnäkyjä näkevät ja valhetta ennustelevat. Ei pidä heidän oleman minun kansani yhteydessä, ei heitä kirjoiteta Israelin heimon kirjaan, eivätkä he tule Israelin maahan; ja te tulette tietämään, että minä olen Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Koska he, koska he vievät minun kansani harhaan, sanoen: \'rauha!\', vaikka ei rauhaa ole, ja katso, koska he, kun kansa rakentaa seinän, valkaisevat sen kalkilla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'niin sano noille kalkilla-valkaisijoille, että se kaatuu. Tulee kaatosade, te syöksytte alas, raekivet, ja sinä pusket puhki, myrskynpuuska,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'ja katso, seinä kaatuu! Eikö silloin teiltä kysytä: \'Missä on valkaisu, jonka olette sivelleet?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Sentähden, näin sanoo Herra, Herra: Minä kiivaudessani annan myrskynpuuskan puhjeta, kaatosade tulee minun vihastani ja raekivet minun kiivaudestani, niin että tulee loppu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Minä hajotan seinän, jonka te olitte kalkilla valkaisseet, ja syöksen sen maahan, niin että sen perustus paljastuu; niin se kaatuu, ja te saatte siinä lopun. Ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Niin minä panen kiivauteni täytäntöön seinässä ja niissä, jotka sen kalkilla valkaisivat, ja sanon teille: Ei ole enää seinää eikä sen valkaisijoita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Israelin profeettoja, jotka ennustivat Jerusalemista ja näkivät sille rauhan näkyjä, vaikka ei rauhaa ollut; sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Ja sinä, ihmislapsi, käännä kasvosi kansasi tyttäriä vastaan, jotka joutuvat hurmoksiin oman sydämensä voimasta, ja ennusta heitä vastaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'ja sano: Näin sanoo Herra, Herra: Voi niitä naisia, jotka sitovat taikasiteet kaikkiin ranteisiin ja tekevät hunnut kaikenkorkuisiin päihin pyydystääksensä sieluja! Toisia sieluja te pyydystätte minun kansaltani pois, toisten sielujen annatte elää omaksi eduksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Ja te häpäisette minut kansani edessä muutamista ohrakourallisista ja leipäpalasista, kun kuoletatte sieluja, joiden ei olisi kuoltava, ja annatte elää sielujen, jotka eivät saisi elää; kun valhettelette minun kansalleni, joka kuuntelee valhetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Sentähden, näin sanoo Herra, Herra: Minä käyn käsiksi teidän taikasiteisiinne, joilla olette pyydystäneet sieluja niinkuin lintuja, ja revin ne teidän käsivarsistanne ja lasken ne sielut irti-sielut, jotka te olette pyydystäneet-niinkuin linnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Ja minä revin teidän huntunne ja pelastan kansani teidän käsistänne, niin etteivät he enää joudu teidän kätenne saaliiksi; ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Koska olette valheella murehduttaneet vanhurskaan sydämen, vaikka minä en tahtonut häntä murehduttaa, ja olette vahvistaneet jumalattoman käsiä, ettei hän kääntyisi pahalta tieltänsä ja saisi elää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'sentähden ette enää saa petosnäkyjä nähdä ettekä ennustella ennustelujanne, vaan minä pelastan kansani teidän käsistänne; ja te tulette tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Minun luokseni tuli miehiä Israelin vanhinten joukosta, ja he istuivat minun eteeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Niin minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, '\"Ihmislapsi, nämä miehet ovat sulkeneet kivijumalansa sydämeensä ja asettaneet kasvojensa eteen sen, mikä heille oli kompastukseksi syntiin. Antaisinko minä heidän kysyä minulta neuvoa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Sentähden puhuttele heitä ja sano heille: Näin sanoo Herra, Herra: Kuka ikinä israelilainen sulkee kivijumalansa sydämeensä ja asettaa kasvojensa eteen sen, mikä hänelle oli kompastukseksi syntiin, ja sitten menee profeetan tykö, hänelle minä, Herra, kyllä annan vastauksen-hänelle ja hänen monille kivijumalilleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'ja tartun Israelin heimoa sydämeen, koska he ovat kääntyneet minusta pois kaikki tyynni seuraamalla kivijumaliansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Sentähden sano Israelin heimolle: Näin sanoo Herra, Herra: Kääntykää, ja kääntykää pois kivijumalistanne ja kääntäkää kasvonne pois kaikista kauhistuksistanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Sillä kuka ikinä israelilainen tai muukalainen, joka asuu Israelissa, luopuu minusta ja sulkee kivijumalansa sydämeensä ja asettaa kasvojensa eteen sen, mikä hänelle oli kompastukseksi syntiin, ja sitten menee profeetan tykö kysymään itsellensä neuvoa minulta, hänelle minä, Herra, itse annan vastauksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Minä käännän kasvoni sitä miestä vastaan, teen hänet merkiksi ja sananlaskuksi ja hävitän hänet kansastani; ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Mutta jos profeetta antaa viekoitella itsensä ja sanoo sanan, niin minä, Herra, olen sen profeetan viekoitellut; ja minä ojennan käteni häntä vastaan ja hävitän hänet kansastani Israelista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Heidän on kannettava syntinsä-niinkuin kysyjän synti, niin on profeetankin synti-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'etteivät he, Israelin heimo, enää eksyisi minusta pois eivätkä enää saastuttaisi itseänsä kaikilla rikkomuksillaan, vaan olisivat minun kansani ja minä olisin heidän Jumalansa; sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, '\"Ihmislapsi! Jos maa tekisi syntiä minua vastaan olemalla uskoton ja minä ojentaisin sitä vastaan käteni ja murtaisin siltä leivän tuen ja lähettäisin siihen nälän ja hävittäisin siitä ihmiset ja eläimet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'ja sen keskellä olisivat nämä kolme miestä: Nooa, Daniel ja Job, niin oman henkensä he vanhurskaudellaan pelastaisivat; sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Jos minä antaisin pahain petoeläinten käydä halki maan ja ne riistäisivät siltä lapset ja se tulisi autioksi, niin ettei kukaan siellä kulkisi petoeläinten tähden,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'niin nämä kolme miestä, jos olisivat sen keskellä, eivät voisi-niin totta kuin minä elän, sanoo Herra, Herra-pelastaa poikiansa eikä tyttäriänsä; ainoastaan he itse pelastuisivat, mutta maa tulisi autioksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Taikka jos minä antaisin miekan tulla tämän maan yli ja sanoisin: \'Miekka, käy halki maan!\' ja hävittäisin siitä ihmiset ja eläimet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'ja sen keskellä olisivat nämä kolme miestä, eivät he voisi-niin totta kuin minä elän, sanoo Herra, Herra-pelastaa poikiansa eikä tyttäriänsä, vaan ainoastaan he itse pelastuisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Taikka, jos minä lähettäisin ruton tähän maahan ja vuodattaisin vihani sen ylitse verenä, niin että hävittäisin siitä ihmiset ja eläimet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'ja Nooa ja Daniel ja Job olisivat sen keskellä, eivät he voisi-niin totta kuin minä elän, sanoo Herra, Herra-pelastaa poikaansa eikä tytärtänsä; vain itse he vanhurskaudellaan pelastaisivat henkensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Mutta näin sanoo Herra, Herra: Mitä sitten, kun minä lähetän Jerusalemin yli neljä kovaa tuomiotani: miekan, nälän, pahat petoeläimet ja ruton hävittämään siitä ihmiset ja eläimet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Mutta katso, sinne on jäävä jäljelle pelastuneita, poikia ja tyttäriä, jotka viedään pois. Katso, ne tulevat teidän luoksenne, ja te näette heidän vaelluksensa ja tekonsa ja tulette lohdutetuiksi siitä onnettomuudesta, jonka minä olen tuottanut Jerusalemille, kaikesta, minkä olen sille tuottanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'He lohduttavat teitä, kun näette heidän vaelluksensa ja tekonsa. Ja te tulette tietämään, etten minä syyttä ole tehnyt sitä kaikkea, minkä olen sille tehnyt; sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, '\"Ihmislapsi, mikä parempi on viinipuu kuin kaikki muut puut, tuo köynnös, joka on metsän puitten seassa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Otetaanko siitä puuta, josta tehdään tarviskalu? Otetaanko siitä vaarnaakaan, johon ripustetaan kaikkea tavaraa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Katso, se annetaan tulen kulutettavaksi. Sen molemmat päät on tuli kuluttanut, ja sen keskus on kärventynyt-kelpaako se tarviskaluksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Katso, silloinkaan, kun se eheä oli, ei siitä voinut tarviskalua tehdä, saati sitten, kun tuli on sen kuluttanut ja se on kärventynyt-silloinko siitä tehtäisiin tarviskalu?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Sentähden, näin sanoo Herra, Herra: Niinkuin metsän puitten seassa käy viinipuulle, jonka minä olen antanut tulen kulutettavaksi, niin minä annan käydä myös Jerusalemin asukkaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Minä käännän kasvoni heitä vastaan: tulesta he ovat päässeet, mutta tuli heidät kuluttaa; ja te tulette tietämään, että minä olen Herra, kun minä käännän kasvoni heitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Ja minä teen maan autioksi, koska he ovat olleet uskottomat; sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, '\"Ihmislapsi, ilmoita Jerusalemille sen kauhistukset');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'ja sano: Näin sanoo Jerusalemille Herra, Herra: Sinun sukusi ja syntysi on kanaanilaisten maasta; isäsi oli amorilainen ja äitisi heettiläinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Ja näin oli sinun syntymäsi: sinä päivänä, jona synnyit, sinulta ei leikattu napanuoraa, sinua ei pesty vedellä, että olisit puhdistunut, sinua ei hierottu suolalla eikä sinua kääritty kapaloihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Ei kenkään sinua säälinyt, niin että olisi tehnyt sinulle mitään tällaista ja armahtanut sinua, vaan sinut pantiin heitteille kedolle: niin halpana pidettiin sinun henkesi sinä päivänä, jona synnyit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Mutta minä kuljin ohitsesi ja näin sinut, kun sätkyttelit verissäsi. Ja minä sanoin sinulle, kun olit siinä verissäsi: \'Sinun pitää elämän\' -niin sanoin minä sinulle, kun olit siinä verissäsi: \'Sinun pitää elämän,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'minä teen sinut kymmentuhansiksi kuin pellon laihon\'. Sitten sinä vartuit, tulit isoksi ja ehdit kauneimpaan kukoistukseesi, rintasi paisuivat, ja hiuksesi kasvoivat; mutta vielä sinä olit alaston ja paljas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Niin minä kuljin ohitsesi ja näin sinut, ja katso, sinun aikasi oli lemmen aika. Ja minä levitin liepeeni sinun ylitsesi ja peitin häpysi. Ja minä vannoin sinulle ja menin liittoon sinun kanssasi, sanoo Herra, Herra; ja sinä tulit minun omakseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Minä pesin sinut vedellä, huuhtelin sinut verestäsi ja voitelin sinut öljyllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Minä puetin sinut kirjaeltuihin vaatteisiin, kengitsin sinut sireeninnahkakenkiin, sidoin päähäsi hienopellavaisen siteen ja hunnutin sinut silkillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Minä koristin sinut koruilla, panin rannerenkaat käsiisi ja käädyt kaulaasi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'panin nenärenkaan nenääsi, korvarenkaat korviisi ja päähäsi kauniin kruunun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Niin koristettiin sinut kullalla ja hopealla, sinun pukusi oli hienoa pellavaa, silkkiä ja kirjaeltua vaatetta, ja sinä sait syödä lestyjä jauhoja, hunajata ja öljyä. Sinusta tuli ylenmäärin kaunis, ja sinä kelpasit kuninkaalliseen arvoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Ja sinun maineesi kulki pakanakansoihin kauneutesi tähden, sillä se oli täydellinen niiden kaunistusten takia, jotka minä sinun yllesi panin; sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Mutta sinä luotit kauneuteesi ja harjoitit haureutta maineesi nojalla ja vuodatit haureuttasi jokaiselle ohikulkijalle: \'Saakoon tuokin!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Sinä otit vaatteitasi ja teit itsellesi kirjavia uhrikukkuloita ja harjoitit haureutta niiden päällä-moista ei ole tapahtunut eikä ole tapahtuva-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Sinä otit korukalujasi, minun kultaani ja hopeatani, jota minä olin sinulle antanut, ja teit itsellesi miehenkuvia ja harjoitit haureutta niiden kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Sinä otit kirjaeltuja vaatteitasi ja verhosit ne niillä; ja minun öljyni ja suitsukkeeni sinä panit niiden eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Ruokani, jota minä sinulle annoin-minähän syötin sinua lestyillä jauhoilla, öljyllä ja hunajalla-sinä panit niiden eteen suloiseksi tuoksuksi. Näin tapahtui, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Sinä otit poikasi ja tyttäresi, jotka olit minulle synnyttänyt, ja teurastit heidät niiden syödä. Eikö riittänyt sinulle haureutesi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'kun vielä teurastit minun poikani ja annoit heidät poltettaviksi uhrina niille?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Ja kaikkien kauhistustesi ja haureutesi ohessa sinä et muistanut nuoruutesi päiviä, jolloin olit alaston ja paljas ja sätkyttelit verissäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Ja kaiken muun pahuutesi lisäksi-voi, voi sinua! sanoo Herra, Herra-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'sinä rakensit itsellesi korokkeita ja teit itsellesi kumpuja kaikille toreille;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'kaikkiin kadunkulmiin sinä rakensit kumpujasi ja häpäisit kauneutesi, levitit sääresi jokaiselle ohikulkijalle ja yhä lisäsit haureuttasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Sinä harjoitit haureutta naapuriesi, Egyptin suurijäsenisten poikain, kanssa ja yhä lisäsit haureuttasi ja niin vihoitit minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Ja katso, minä ojensin käteni sinua vastaan ja vähensin sinun määräosasi ja jätin sinut vihollistesi, filistealaisten tyttärien, raivon valtaan, jotka häpesivät sinun iljettävää vaellustasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Sitten sinä harjoitit haureutta Assurin poikain kanssa, koska et voinut saada kyllääsi; ja vaikka harjoitit haureutta heidän kanssansa, et sittenkään kyllääsi saanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Sitten sinä yhä enensit haureuttasi kauppiasten maahan päin, Kaldeaan, mutta et siitäkään saanut kyllääsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Kuinka himosta hiukeava olikaan sinun sydämesi, sanoo Herra, Herra, kun teit tämän kaiken, niinkuin tekee itse pääportto;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'kun rakensit korokkeesi kaikkiin kadunkulmiin ja teit kumpusi kaikille toreille! Mutta siinä sinä olit erilainen kuin muut portot, että halveksuit portonpalkkaa-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'avionrikkoja-vaimo, joka miehensä sijaan ottaa vieraita!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Kaikille muille portoille annetaan lahja, mutta sinä annoit portonlahjojasi kaikille rakastajillesi ja haureudessasi lahjoit heitä tulemaan luoksesi joka taholta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Sinun oli haureudessasi laita päinvastoin kuin muitten naisten: sinun perässäsi ei juostu haureuteen, ja sinä maksoit portonpalkkaa, mutta sinulle portonpalkkaa ei maksettu; näin se oli päinvastoin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Sentähden, sinä portto, kuule Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Näin sanoo Herra, Herra: Koska olet antanut riettautesi vuotaa ja olet paljastanut häpysi haureudessasi kaikille rakastajillesi ja kaikille kauhistaville kivijumalillesi, sekä lastesi veren tähden, jonka olet niille antanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'sentähden, katso, minä kokoan kaikki sinun rakastajasi, jotka olivat sinulle mieleen, kaikki, joita sinä rakastit, ja kaikki, joihin kyllästyit, ne minä kokoan sinua vastaan joka taholta ja paljastan heille sinun häpysi, niin että he näkevät koko häpysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Minä tuomitsen sinut sen mukaan, mitä on säädetty avionrikkoja-ja verenvuodattaja-naisista, ja annan vihassa ja kiivaudessa sinun veresi vuotaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Ja minä annan sinut heidän käsiinsä, ja he hajottavat sinun korokkeesi, kukistavat sinun kumpusi, raastavat sinulta vaatteesi, ottavat korukalusi ja jättävät sinut alastomaksi ja paljaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'He nostattavat kansanjoukon sinua vastaan, ja ne kivittävät sinut, hakkaavat sinut maahan miekoillansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'polttavat tulella sinun talosi ja panevat sinussa toimeen tuomiot paljojen naisten silmäin edessä. Minä teen lopun sinun porttona-olostasi, etkä sinä enää sitten portonpalkkoja maksa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Niin minä tyydytän vihani sinussa, niin että minun kiivauteni sinusta väistyy, ja minä tyynnyn enkä enää ole vihastunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Koska et muistanut nuoruutesi päiviä, vaan ärsytit minut kaikilla näillä, niin katso: minäkin annan sinun vaelluksesi tulla oman pääsi päälle, sanoo Herra, Herra. Etkö sinä tehnyt näitä iljetyksiä kaikkien kauhistustesi lisäksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Katso, jokainen, joka sananlaskuja lausuu, on lausuva sinusta: \'Tytär tulee äitiinsä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Sinä olet äitisi tytär, hänen, joka vieroi miestään ja lapsiansa, ja olet sisartesi sisar, heidän, jotka vieroivat miehiään ja lapsiansa: teidän äitinne oli heettiläinen ja isänne amorilainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Isompi sisaresi oli Samaria tyttärineen, joka asui vasemmalla puolellasi, ja pienempi sisaresi, joka asui oikealla puolellasi, oli Sodoma tyttärineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Mutta sinä et vaeltanut heidän teitänsä etkä tehnyt kauhistuksia samalla tavoin kuin he: vähän aikaa vain, niin sinä jo teit kelvottomammin kuin he kaikilla teilläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Niin totta kuin minä elän, sanoo Herra, Herra: ei totisesti sisaresi Sodoma tyttärineen tehnyt sitä, mitä sinä tyttärinesi olet tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Katso, tämä oli sisaresi Sodoman synti: ylpeys, leivän yltäkylläisyys ja huoleton lepo hänellä ja hänen tyttärillään; mutta kurjaa ja köyhää hän ei kädestä ottanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'He korskeilivat ja tekivät kauhistuksia minun edessäni, ja minä, kun sen näin, toimitin heidät pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Ja Samaria ei tehnyt puoltakaan sinun syntiesi vertaa; mutta sinä olet tehnyt kauhistuksia paljon enemmän kuin he, niin että olet kaikilla kauhistuksillasi, joita olet tehnyt, saanut sisaresi näyttämään vanhurskailta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Niinpä kanna myös sinä häpeäsi, kun olet hankkinut moisen hyvityksen sisarillesi: sinun syntiesi takia, kun olet menetellyt vielä kauhistavammin kuin he, ovat he vanhurskaampia kuin sinä. Häpeä sinäkin ja kanna häpeäsi, kun olet saanut sisaresi näyttämään vanhurskailta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Ja minä tahdon kääntää heidän kohtalonsa: Sodoman ja hänen tyttäriensä kohtalon sekä Samarian ja hänen tyttäriensä kohtalon; ja minä tahdon kääntää sinun kohtalosi, sinun, joka olet heidän keskellänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'että kantaisit häpeäsi ja olisit häpeissäsi kaikesta, mitä teit, kun lohdutit heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Sinun sisaresi-Sodoma tyttärineen saa palata entisellensä, ja Samaria tyttärineen saa palata entisellensä. Ja sinä tyttärinesi saat palata entisellesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Eikö ollut sisaresi Sodoma huhupuheena sinun suussasi sinun ylpeytesi aikana,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'ennenkuin sinun oma pahuutesi paljastui, silloin kun jouduit Aramin tyttärien ja kaikkien heidän ympärillään asuvaisten, filistealaisten tyttärien, häväistäväksi, jotka joka taholta pilkkaavat sinua?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Sinä saat kantaa iljetyksesi ja kauhistuksesi, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Sillä näin sanoo Herra, Herra: Minä olen tehnyt sinulle sen mukaan, kuin sinä olet tehnyt, kun olet pitänyt valan halpana ja rikkonut liiton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Mutta minä muistan liittoni, jonka tein sinun kanssasi sinun nuoruutesi päivinä, ja minä teen sinun kanssasi iankaikkisen liiton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Ja sinä muistat vaelluksesi ja häpeät, kun otat vastaan sisaresi, ne, jotka ovat sinua isommat, ynnä ne, jotka ovat sinua pienemmät, ja minä annan heidät sinulle tyttäriksi; mutta en sinun liittosi voimasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Ja minä teen liittoni sinun kanssasi, ja sinä tulet tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Niin sinä muistat ja häpeät etkä voi häpeäsi tähden suutasi avata, kun minä annan sinulle anteeksi kaikki, mitä sinä tehnyt olet; sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, '\"Ihmislapsi, esitä arvoitus ja lausu vertaus Israelin heimolle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'ja sano: Näin sanoo Herra, Herra: Suuri kotka, suurisiipinen, pitkäsulkainen, täysihöyheninen, kirjava, tuli Libanonille ja otti latvuksen setripuusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Hän taittoi siitä latvalehvän ja vei sen kauppiasten maahan, asetti sen kauppurien kaupunkiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Sitten hän otti siitä maasta taimen ja pani sen kylvöpeltoon. Hän otti sen ja pani pajuksi runsaan veden ääreen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Se versoi, ja siitä tuli rehevä viinipuu, matalakasvuinen; sen oksien tuli kääntyä kotkaan päin ja sen juurten olla hänen allansa. Siitä tuli viinipuu, se teki haaroja, työnsi oksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Mutta oli toinen suuri kotka, suurisiipinen, runsashöyheninen; ja katso, tämä viinipuu ojensi juurensa sitä kotkaa kohti ja työnsi oksansa siihen päin, sen kasteltaviksi, siitä penkereestä, johon se oli istutettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Se oli istutettu hyvään peltoon, runsaan veden ääreen, että se tekisi lehviä, kantaisi hedelmää ja tulisi ihanaksi viinipuuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Sano: Näin sanoo Herra, Herra: Menestyyköhän se? Eiköhän kotka kisko ylös sen juuria ja raasta sen hedelmiä; niin että kaikki siitä versoneet lehdet kuivuvat ja puu kuivuu? Eikä tarvita suurta voimaa, ei paljoa väkeä sen nostamiseksi juuriltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Katso, istutettu se on-menestyyköhän se? Eiköhän se kuivu, kun siihen käy itätuuli, kuivu penkereessä, jossa se versoi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, '\"Sano uppiniskaiselle suvulle: Ettekö te tiedä, mitä tämä tarkoittaa? Sano: Katso, Baabelin kuningas tuli Jerusalemiin, otti sen kuninkaan ja päämiehet ja vei heidät luoksensa Baabeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Ja hän otti yhden kuninkaallisesta suvusta, teki hänen kanssansa liiton ja otti häneltä valan, mutta maan mahtavat hän vei mukanaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'että valtakunta tulisi vähäpätöiseksi eikä kohoaisi, että se pitäisi liittonsa ja liitto pysyisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Mutta hän kapinoi häntä vastaan ja laittoi lähettiläänsä Egyptiin, että hänelle annettaisiin hevosia ja paljon väkeä. Menestyyköhän se, pelastuukohan se, joka tällaista tekee? Pelastuuko se, joka liiton rikkoo?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Niin totta kuin minä elän, sanoo Herra, Herra: sen kuninkaan asuinpaikalla, joka hänet kuninkaaksi teki, jonka valan hän on halpana pitänyt ja jonka liiton hän on rikkonut, sen luona, keskellä Baabelia, hänen totisesti on kuoltava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Ja farao suurella sotajoukollaan ja paljolla väellään ei tee mitään hänen hyväkseen sodassa, kun luodaan valli ja rakennetaan saartovarusteet paljojen ihmisten hävittämiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Hän piti halpana valan ja rikkoi liiton; katso, vaikka oli kättä lyönyt, hän teki kaiken tämän-ei hän pelastu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Sentähden, näin sanoo Herra, Herra: Niin totta kuin minä elän, niin valani, jonka hän halpana piti, ja liittoni, jonka hän rikkoi, minä annan totisesti tulla hänen päänsä päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Minä levitän verkkoni hänen ylitsensä, ja hän takertuu minun pyydykseeni. Minä vien hänet Baabeliin ja käyn siellä oikeutta hänen kanssansa hänen uskottomuudestaan, jota hän on osoittanut minua kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Ja kaikki hänen pakolaisensa kaikista hänen sotajoukoistaan kaatuvat miekkaan, ja jäljellejääneet hajotetaan kaikkiin tuuliin. Ja te tulette tietämään, että minä, Herra, olen puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Näin sanoo Herra, Herra: Mutta minä otan yhden latvuksen siitä korkeasta setripuusta ja istutan sen; hennon latvalehvän minä siitä taitan ja istutan korkealle ja jyrkälle vuorelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Israelin vuoren korkeuteen minä sen istutan: ja se kantaa lehviä ja tekee hedelmää, ja siitä tulee mahtava setri. Ja sen alla asuvat kaikki linnut, kaikki, mitä siivekästä on; ne asuvat sen oksain varjossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Ja kaikki metsän puut tulevat tietämään, että minä olen Herra, joka teen korkean puun matalaksi ja matalan puun korkeaksi, tuoreen puun kuivaksi ja kuivan puun kukoistavaksi. Minä, Herra, Herra, olen puhunut, ja minä sen teen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, '\"Mikä teillä on, kun te lausutte tätä pilkkalausetta Israelin maasta: \'Isät söivät raakoja rypäleitä, lasten hampaat heltyivät\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Niin totta kuin minä elän, sanoo Herra, Herra, ei tule teidän enää lausua tätä pilkkalausetta Israelissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Katso, kaikki sielut ovat minun: niinkuin isän sielu, niin pojankin sielu-ne ovat minun. Se sielu, joka syntiä tekee-sen on kuoltava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Jos mies on vanhurskas ja tekee oikeuden ja vanhurskauden:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'ei syö uhrivuorilla, ei luo silmiänsä Israelin heimon kivijumaliin, ei saastuta lähimmäisensä vaimoa, ei ryhdy naiseen, joka on kuukautistilassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'ei sorra toista, vaan antaa takaisin velanpantin, ei riistä eikä raasta, vaan antaa leipäänsä nälkäiselle, verhoaa vaatteella alastonta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'ei anna rahaansa korolle, ei ota voittoa, vaan pidättää kätensä vääryydestä, tekee oikean tuomion miesten välillä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'vaeltaa minun käskyjeni mukaan ja noudattaa minun oikeuksiani, niin että tekee sitä, mikä oikein on-hän on vanhurskas, hän totisesti saa elää, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Mutta jos hänelle on syntynyt poika, väkivaltainen, verenvuodattaja, joka tekee yhtäkin näistä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'mitä hän itse ei ole tehnyt: syö uhrivuorilla, saastuttaa lähimmäisensä vaimon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'sortaa kurjaa ja köyhää, riistää ja raastaa, ei anna takaisin panttia, luo silmänsä kivijumaliin, tekee kauhistuksia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'antaa rahansa korolle ja ottaa voittoa-saisiko tämä elää? Ei hän saa elää: kaikkia näitä kauhistuksia hän on tehnyt, hänet on kuolemalla rangaistava; hän on verivelan alainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Mutta katso, jos tälle on syntynyt poika ja hän näkee kaikki isänsä synnit, jotka tämä on tehnyt-näkee ne eikä tee sellaisia:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'ei syö uhrivuorilla, ei luo silmiänsä Israelin heimon kivijumaliin, ei saastuta lähimmäisensä vaimoa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'ei sorra toista, ei ota panttia, ei riistä eikä raasta, vaan antaa leipäänsä nälkäiselle, verhoaa vaatteella alastonta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'pidättää kätensä kurjasta, ei ota korkoa eikä voittoa, vaan tekee minun oikeuksieni mukaan, vaeltaa käskyjeni mukaan-hänen ei ole kuoltava isänsä syntivelan tähden, hän totisesti saa elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Hänen isänsä taas kun teki väkivallan töitä, riisti ja raastoi veljeltänsä ja teki kansansa keskuudessa sitä, mikä ei ole hyvää, niin katso, hänen oli kuoltava syntivelkansa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Ja vielä te kysytte: \'Minkätähden ei poika kanna isän syntivelkaa?\' Kun poika on tehnyt oikeuden ja vanhurskauden, noudattanut kaikkia minun käskyjäni ja tehnyt niitten mukaan, hän totisesti saa elää. Se sielu, joka syntiä tekee-sen on kuoltava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Poika ei kanna isän syntivelkaa, eikä isä kanna pojan syntivelkaa. Vanhurskaan ylitse on tuleva hänen vanhurskautensa, ja jumalattoman ylitse on tuleva hänen jumalattomuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Ja jos jumalaton kääntyy pois kaikesta synnistänsä, mitä hän on tehnyt, ja noudattaa kaikkia minun käskyjäni ja tekee oikeuden ja vanhurskauden, hän totisesti saa elää; ei hänen ole kuoltava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Ei yhtäkään hänen synneistänsä, jotka hän on tehnyt, muisteta; vanhurskautensa tähden, jota hän on noudattanut, hän saa elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Olisiko minulle mieleen jumalattoman kuolema, sanoo Herra, Herra; eikö se, että hän kääntyy pois teiltänsä ja elää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Ja jos vanhurskas kääntyy pois vanhurskaudestansa ja tekee vääryyttä, tekee kaikkien niiden kauhistusten kaltaisia, joita jumalaton tekee-saisiko hän tehdä niin ja elää? Ei yhtäkään hänen vanhurskasta tekoansa, jonka hän on tehnyt, muisteta. Uskottomuutensa tähden, johon hän on langennut, ja syntinsä tähden, jota on tehnyt, niiden tähden hänen on kuoltava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Ja vielä te sanotte: \'Herran tie ei ole oikea\'. Kuulkaa siis, te Israelin heimo! Minunko tieni ei olisi oikea? Eikö niin: teidän omat tienne eivät ole oikeat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Jos vanhurskas kääntyy pois vanhurskaudestansa ja tekee vääryyttä, sentähden hänen on kuoltava; vääryytensä tähden, jota on tehnyt, hänen on kuoltava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Ja jos jumalaton kääntyy pois jumalattomuudestaan, jota on harjoittanut, ja tekee oikeuden ja vanhurskauden, hän säilyttää sielunsa elossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Koska hän näki ja kääntyi pois kaikista synneistänsä, joita oli tehnyt, hän totisesti saa elää; ei hänen ole kuoltava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Mutta Israelin heimo sanoo: \'Herran tie ei ole oikea\'. Minunko tieni eivät olisi oikeat, te Israelin heimo? Eikö niin: teidän omat tienne eivät ole oikeat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Niinpä minä tuomitsen teidät, te Israelin heimo, itsekunkin hänen teittensä mukaan, sanoo Herra, Herra. Kääntykää, palatkaa pois kaikista synneistänne, ja älköön syntivelka tulko teille lankeemukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Heittäkää pois päältänne kaikki syntinne, joilla te olette rikkoneet, ja tehkää itsellenne uusi sydän ja uusi henki. Ja minkätähden te kuolisitte, Israelin heimo?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Sillä ei ole minulle mieleen kuolevan kuolema, sanoo Herra, Herra. Siis kääntykää, niin te saatte elää.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, '\"Mutta sinä, viritä itkuvirsi Israelin ruhtinaista');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'ja sano: Mikä naarasleijona olikaan sinun äitisi leijonain joukossa! Se makasi nuorten jalopeurain keskellä, kasvatti poikasiansa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'ja sai ylenemään yhden poikasistaan: siitä tuli nuori jalopeura, se oppi saalista raatelemaan, se söi ihmisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Mutta kansat kuulivat siitä: se pyydystettiin heidän kuoppaansa ja vietiin turpakoukussa Egyptin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Kun emo näki, että viipyi, että hukkui hänen toivonsa, otti se toisen poikasistaan, sai sen nuoreksi jalopeuraksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Se käyskenteli leijonain keskellä, siitä tuli nuori jalopeura, se oppi saalista raatelemaan, se söi ihmisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Se ryhtyi heidän leskiinsä ja teki autioiksi heidän kaupunkinsa, ja maa ja kaikki, mitä siinä on, kauhistui sen ärjynnän äänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Silloin kansat maakunnista yltympäri asettivat ja virittivät sille verkkonsa; se pyydystettiin heidän kuoppaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Ja se pantiin häkkiin, turpakoukkuun ja vietiin Baabelin kuninkaan eteen. Se vietiin vuorilinnoihin, ettei sen ääni enää kuuluisi Israelin vuorille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Sinun äitisi oli sinulle kuin verevä viinipuu, veden ääreen istutettu. Se tuli runsaasta vedestä hedelmöitseväksi ja tuuhealehväiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Siihen tuli ylväitä oksia hallitsijain valtikoiksi, ja sen runko kohosi korkealle tiheän lehvistön keskellä ja näkyi kauas korkeana ja runsas-oksaisena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Mutta se temmattiin vihaisesti irti, viskattiin maahan, ja itätuuli kuivasi sen hedelmät, ne revittiin hajalleen, ja sen ylväät oksat kuivuivat, ne kulutti tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Nyt se on istutettuna erämaahan, kuivaan ja janoiseen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Ja sen valtaoksasta on lähtenyt tuli, se on kuluttanut sen hedelmät, ja ylvästä oksaa hallitusvaltikaksi ei siinä enää ole.\" Itkuvirsi tämä oli oleva, ja itkuvirsi siitä on tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Seitsemäntenä vuotena, viidennessä kuussa, kuukauden kymmenentenä päivänä tuli miehiä Juudan vanhinten joukosta kysymään neuvoa Herralta, ja he istuivat minun eteeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Niin minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, '\"Ihmislapsi, puhu Israelin vanhimmille ja sano heille: Näin sanoo Herra, Herra: Tekö tulette minulta neuvoa kysymään? Niin totta kuin minä elän, en anna minä teidän kysyä minulta neuvoa, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Etkö tuomitse heitä, etkö tuomitse, ihmislapsi? Tee heille tiettäviksi heidän isiensä kauhistukset');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'ja sano heille: Näin sanoo Herra, Herra: Sinä päivänä, jona minä Israelin valitsin, minä kättä kohottaen lupasin Jaakobin heimon jälkeläisille, minä tein itseni heille tunnetuksi Egyptin maassa ja kättä kohottaen lupasin heille sanoen: \'Minä olen Herra, teidän Jumalanne\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Sinä päivänä minä kättä kohottaen lupasin heille, että vien heidät pois Egyptin maasta siihen maahan, jonka olin heille katsonut ja joka vuotaa maitoa ja mettä-se on kaunistus kaikkien maitten joukossa. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Ja minä sanoin heille: \'Heittäkää, itsekukin, pois silmienne iljetykset älkääkä saastuttako itseänne Egyptin kivijumalilla: minä olen Herra, teidän Jumalanne\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Mutta he niskoittelivat minua vastaan eivätkä tahtoneet minua kuulla; eivät heittäneet pois itsekukin silmiensä iljetyksiä eivätkä hyljänneet Egyptin kivijumalia. Niin minä ajattelin vuodattaa kiivauteni heidän ylitsensä ja panna vihani täytäntöön heissä keskellä Egyptin maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Mutta minä tein, minkä tein, oman nimeni tähden, ettei se tulisi häväistyksi pakanain silmissä, joitten keskellä he olivat ja joitten silmäin edessä minä olin tehnyt itseni heille tunnetuksi viemällä heidät pois Egyptin maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Ja kun olin vienyt heidät pois Egyptin maasta ja tuonut heidät erämaahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'niin minä annoin heille käskyni ja tein heille tiettäviksi oikeuteni: se ihminen, joka ne pitää, on niistä elävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Myöskin sapattini minä annoin heille, olemaan merkkinä minun ja heidän välillään, että he tulisivat tietämään, että minä olen Herra, joka pyhitän heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Mutta Israelin heimo niskoitteli minua vastaan erämaassa: he eivät vaeltaneet minun käskyjeni mukaan, ylenkatsoivat minun oikeuteni, jotka ihmisen on pidettävä, että hän niistä eläisi, ja minun sapattini he kovin rikkoivat. Niin minä ajattelin vuodattaa kiivauteni heidän ylitsensä erämaassa ja lopettaa heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Mutta minä tein, minkä tein, oman nimeni tähden, ettei se tulisi häväistyksi pakanain silmissä, joitten silmäin edessä minä olin vienyt heidät pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Kuitenkin minä kättä kohottaen vannoin heille erämaassa, etten heitä tuo siihen maahan, jonka olin antanut heille, joka vuotaa maitoa ja mettä-se on kaunistus kaikkien maitten joukossa-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'koska he pitivät minun oikeuteni halpoina, eivät vaeltaneet minun käskyjeni mukaan, vaan rikkoivat minun sapattini; sillä heidän sydämensä vaelsi heidän kivijumalainsa jäljessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Mutta minä säälin heitä, niin etten heitä hävittänyt enkä tehnyt heistä loppua erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Sitten minä sanoin heidän lapsillensa erämaassa: Älkää vaeltako isäinne käskyjen mukaan, heidän oikeuksiansa älkää noudattako älkääkä saastuttako itseänne heidän kivijumalillansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Minä olen Herra, teidän Jumalanne; minun käskyjeni mukaan vaeltakaa, minun oikeuksiani noudattakaa, ne pitäkää');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'ja pyhittäkää minun sapattini; ne olkoot merkkinä välillämme, minun ja teidän, että tulisitte tietämään, että minä olen Herra, teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Mutta lapset niskoittelivat minua vastaan: he eivät vaeltaneet minun käskyjeni mukaan, eivät noudattaneet minun oikeuksiani, niin että olisivat ne pitäneet, -jotka ihmisen on pidettävä, että hän niistä eläisi-ja rikkoivat minun sapattini. Niin minä ajattelin vuodattaa kiivauteni heidän ylitsensä ja panna vihani heissä täytäntöön erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Mutta minä pidätin käteni ja tein, minkä tein, oman nimeni tähden, ettei se tulisi häväistyksi pakanain silmissä, joitten silmäin edessä minä olin vienyt heidät pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Kuitenkin minä kättä kohottaen vannoin heille erämaassa, että minä hajotan heidät pakanain sekaan ja sirotan heidät muihin maihin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'koska he eivät pitäneet minun käskyjäni, vaan ylenkatsoivat minun käskyni, rikkoivat minun sapattini ja heidän silmänsä pälyivät heidän isiensä kivijumalain perään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Niinpä minäkin annoin heille käskyjä, jotka eivät olleet hyviä, ja oikeuksia, joista he eivät voineet elää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'ja annoin heidän saastua lahjoistansa, siitä, että polttivat uhrina kaiken, mikä avasi äidinkohdun, jotta saattaisin heidät kauhun valtaan ja he tulisivat tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Sentähden puhu Israelin heimolle, ihmislapsi, ja sano heille: Näin sanoo Herra, Herra: Vielä niinkin ovat isänne minua herjanneet, että ovat olleet uskottomat minua kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Kun minä toin heidät maahan, jonka olin kättä kohottaen luvannut heille antaa, niin missä vain he näkivät korkean kukkulan tai tuuhean puun, siinä he uhrasivat teurasuhrinsa ja antoivat vihastuttavat uhrilahjansa, siinä panivat esiin suloisesti tuoksuvat uhrinsa ja siinä vuodattivat juomauhrinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Niin minä sanoin heille: \'Mikä tämä uhrikukkula on, jolle te menette?\' ja niin sai sellainen nimen uhrikukkula aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Sentähden sano Israelin heimolle: Näin sanoo Herra, Herra: Ettekö te saastuta itseänne isienne tiellä? Ettekö kulje uskottomina heidän iljetystensä jäljessä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Ettekö ole saastuttaneet itseänne kaikilla kivijumalillanne aina tähän päivään asti, kun tuotte lahjojanne ja panette lapsenne käymään tulen läpi? Ja minäkö antaisin teidän kysyä minulta neuvoa, te Israelin heimo? Niin totta kuin minä elän, sanoo Herra, Herra, en anna minä teidän kysyä minulta neuvoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Se, mikä on tullut teidän mieleenne, ei totisesti ole tapahtuva-se, mitä sanotte: \'Me tahdomme olla pakanain kaltaisia, muitten maitten sukukuntain kaltaisia, niin että palvelemme puuta ja kiveä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Niin totta kuin minä elän, sanoo Herra, Herra: totisesti minä olen hallitseva teitä väkevällä kädellä, ojennetulla käsivarrella ja vuodatetulla vihalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Ja minä vien teidät pois kansojen seasta ja kokoan teidät maista, joihin olitte hajotetut, väkevällä kädellä, ojennetulla käsivarrella ja vuodatetulla vihalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'Ja minä tuon teidät kansojen erämaahan, ja siellä minä käyn oikeutta teidän kanssanne kasvoista kasvoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Niinkuin minä kävin oikeutta isienne kanssa Egyptinmaan erämaassa, niin minä käyn oikeutta teidän kanssanne, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Minä panen teidät kulkemaan sauvan alitse ja saatan teidät liiton siteeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Ja minä erotan teistä ne, jotka kapinoivat minua vastaan ja luopuvat minusta: muukalaisuutensa maasta minä vien heidät pois, mutta Israelin maahan he eivät tule; ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Mutta te, Israelin heimo! Näin sanoo Herra, Herra: Menkää vain ja palvelkaa itsekukin omia kivijumalianne. Mutta vastedes te totisesti kuulette minua ettekä enää häpäise minun pyhää nimeäni lahjoillanne ynnä kivijumalillanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Sillä minun pyhällä vuorellani, Israelin korkealla vuorella, sanoo Herra, Herra, siellä he palvelevat minua, koko Israelin heimo, kaikki tyynni, mitä maassa on. Siellä minä heihin mielistyn, siellä minä halajan teidän antimianne, uutisverojanne, kaikkinaisia teidän pyhiä lahjojanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Niinkuin suloisesti tuoksuvaan uhriin minä teihin mielistyn, kun minä vien teidät pois kansojen seasta ja kokoan teidät maista, joihin olette hajotetut, ja osoitan teissä pyhyyteni pakanain silmien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Ja te tulette tietämään, että minä olen Herra, kun minä tuon teidät Israelin maahan, siihen maahan, jonka minä kättä kohottaen olin luvannut antaa teidän isillenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Ja te muistatte siellä vaelluksenne ja kaikki tekonne, joilla olette itsenne saastuttaneet, ja teitä kyllästyttää oma itsenne kaikkien pahain töittenne tähden, mitä olette tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Ja te tulette tietämään, että minä olen Herra, kun minä teen teille, minkä teen, oman nimeni tähden, en teidän pahan vaelluksenne enkä riettaiden tekojenne ansion mukaan, te Israelin heimo; sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, '\"Ihmislapsi, käännä kasvosi etelää kohti, vuodata sanasi etelää vastaan ja ennusta kedon metsikköä vastaan, joka on Etelämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'Ja sano Etelämaan metsikölle: Kuule Herran sana. Näin sanoo Herra, Herra: Katso, minä sytytän sinut tuleen, ja se kuluttaa kaikki sinun tuoreet puusi ja kuivat puusi. Ei sammu leimuava liekki, ja siitä kärventyvät kaikki kasvot, etelästä pohjoiseen asti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'ja kaikki liha on näkevä, että minä, Herra, olen sen sytyttänyt: se ei sammu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'Niin minä sanoin: \"Voi Herra, Herra! Ne sanovat minusta: \'Tämähän puhuu pelkkiä vertauksia\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, '\"Ihmislapsi, käännä kasvosi Jerusalemia kohti, vuodata sanasi pyhäköitä vastaan ja ennusta Israelin maata vastaan ja sano Israelin maalle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Näin sanoo Herra: Katso, minä käyn sinun kimppuusi, vedän miekkani tupestaan ja hävitän sinusta vanhurskaan ja jumalattoman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Koska minä tahdon hävittää sinusta vanhurskaan ja jumalattoman, sentähden lähtee tupestaan minun miekkani kaiken lihan kimppuun, etelästä pohjoiseen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Ja kaikki liha tulee tietämään, että minä, Herra, olen vetänyt miekkani tupestaan; eikä se siihen enää palaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Mutta sinä, ihmislapsi, huokaile! Lanteet murtuneina, katkerassa tuskassa huokaile heidän silmiensä edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Ja kun he sinulta kysyvät: \'Minkätähden sinä huokailet?\' niin sano: Sanoman tähden, sillä se saapuu, ja kaikki sydämet raukeavat, kaikki kädet herpoavat, kaikkien henki tyrmistyy, kaikki polvet käyvät veltoiksi kuin vesi. Katso, se tulee, se tapahtuu; sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, '\"Ihmislapsi, ennusta ja sano: Näin sanoo Herra. Sano: Miekka, miekka on teroitettu, on myös kirkkaaksi hiottu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Teurasta teurastamaan se on teroitettu, salamoitsevaksi se on hiottu. Vai iloitsisimmeko? Vitsa, joka lyö minun poikaani, pitää halpana kaiken, mikä puuta on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Ja hän on antanut sen hioa otettavaksi käteen; se miekka on teroitettu, on hiottu annettavaksi surmaajan käteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Huuda ja valita, ihmislapsi, sillä tämä tapahtuu minun kansaani vastaan, kaikkia Israelin ruhtinaita vastaan: he ovat annetut alttiiksi miekalle, he ynnä minun kansani; lyö sentähden lanteeseesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Sillä vitsaa on jo koeteltu. Mutta entäpä, jos vitsa pitääkin halpana tämän kaiken? Se ei tapahdu, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Mutta sinä, ihmislapsi, ennusta ja lyö käsiäsi yhteen; tulkoon miekasta kaksi miekkaa, tulkoon kolme; se on surmattujen surmamiekka, miekka, joka surmaa suuretkin, joka kiertää heitä yltympäri,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'että sydän pelkoon menehtyisi, että kompastuksia olisi paljon. Kaikille heidän porteillensa minä olen asettanut miekan välkkymään. Voi, se on tehty salamaksi, on hiottu teurastukseen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Lyö terävästi oikealle, ojennu vasemmalle, mihin vain teräsi suunnataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Minäkin lyön käsiäni yhteen ja tyydytän kiivauteni. Minä, Herra, olen puhunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, '\"Sinä, ihmislapsi, laita kaksi tietä, Baabelin kuninkaan miekan tulla. Samasta maasta lähtekööt molemmat. Ja veistä viitta; veistä se kaupunkiin vievän tien suuhun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Laita tie miekan tulla ammonilaisten Rabbaan sekä Juudaan, varustettuun Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Sillä Baabelin kuningas seisahtuu tien haaraan, molempain teitten suuhun, taikojansa taikomaan: hän pudistaa nuolia, kysyy kotijumalilta, tarkkaa maksaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Hänen oikeaan käteensä tulee Jerusalemin arpa: panna muurinmurtajia, avata suu ärjyntään, kohottaa sotahuuto, panna muurinmurtajia portteja vastaan, luoda valli, rakentaa saartovarusteet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Mutta Jerusalemin asukkaiden silmissä tämä on pettävää taikomista: heillähän on valojen valat; mutta hän saattaa muistoon syntivelan, että he joutuisivat kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Sentähden, näin sanoo Herra, Herra: Koska te olette saattaneet muistoon syntivelkanne, kun rikkomuksenne ovat tulleet julki, niin että teidän syntinne on näkyvissä kaikissa teidän teoissanne, niin-koska te olette saatetut muistoon-teidät otetaan käsin kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Ja sinä saastutettu, jumalaton, sinä Israelin ruhtinas, jonka päivä on silloin tullut, kun syntivelka on loppumäärässään!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Näin sanoo Herra, Herra: Ota pois käärelakki, nosta pois kruunu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Tämä ei jää tällensä: alhainen korotetaan, korkea alennetaan. Raunioiksi, raunioiksi, raunioiksi minä panen tämän; eikä tästä ole jäävä mitään, kunnes tulee hän, jolla on oikeus, ja minä annan sen hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Ja sinä, ihmislapsi, ennusta ja sano: Näin sanoo Herra, Herra ammonilaisia ja heidän herjauksiansa vastaan: Sano näin: Miekka, miekka on paljastettu, teurastukseen hiottu, saamaan kyllänsä, salamoitsemaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'vaikka sinulle petollisia näkyjä nähdään, valheita ennustellaan, että sinut muka pannaan tallaamaan saastaisten, jumalattomain niskaa, joitten päivä on silloin tullut, kun syntivelka on loppumäärässään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Pane se tuppeensa takaisin. Paikassa, jossa olet luotu, synnyinmaassasi, minä tahdon sinut tuomita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'Minä vuodatan sinun ylitsesi kiivastukseni, puhallan sinuun vihani tulen ja annan sinut raakain miesten käsiin, turmiontekijäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Tulen kulutettavaksi sinut annetaan, sinun veresi on oleva keskellä maata, ei sinua enää muisteta. Sillä minä, Herra, olen puhunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, '\"Sinä, ihmislapsi, etkö tuomitse, etkö tuomitse verivelkojen kaupunkia? Tee sille tiettäviksi kaikki sen kauhistukset');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'ja sano: Näin sanoo Herra, Herra: Voi kaupunkia, joka on vuodattanut keskuudessaan verta, että tulisi sen aika, ja tehnyt itselleen kivijumalia, että se siitä saastuisi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Verestäsi, jonka olet vuodattanut, sinä olet tullut vikapääksi, ja kivijumalistasi, jotka olet tehnyt, sinä olet saastunut; sinä olet jouduttanut päiviäsi ja olet vuottesi määrään päässyt. Sentähden minä annan sinut pakanain häväistäväksi ja kaikkien maitten pilkaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Läheiset ja kaukaiset pilkkaavat sinua, jonka nimi on saastutettu ja jossa on hämminkiä paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Katso, Israelin ruhtinaat sinussa luottavat kukin omaan käsivarteensa vuodattaaksensa verta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Isää ja äitiä sinussa ylenkatsotaan, muukalaiselle sinun keskelläsi tehdään väkivaltaa, orpoa ja leskeä sinussa sorretaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Mikä on minulle pyhitettyä, sitä sinä halveksit, minun sapattini sinä rikot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Sinussa on niitä, jotka panettelevat vuodattaaksensa verta. Uhrivuorilla sinussa syödään. Ilkitöitä sinun keskelläsi tehdään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Isän häpy sinussa paljastetaan. Naiselle, joka on saastainen kuukautistilansa tähden, tehdään sinussa väkivaltaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Toinen harjoittaa kauhistusta toisensa vaimon kanssa, mies saastuttaa sukurutsauksessa miniänsä, mies tekee sinussa väkivaltaa sisarelleen, isänsä tyttärelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Sinussa otetaan lahjuksia veren vuodattamiseksi, sinä otat korkoa ja voittoa, kiskot väkivaltaisesti lähimmäistäsi, mutta minut sinä unhotat, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Mutta katso, minä lyön käsiäni yhteen sinun väärän voittosi tähden, jota olet hankkinut, ja sinun verivelkojesi tähden, joita keskuudessasi on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Kestääköhän rohkeutesi, pysyvätköhän kätesi lujina niinä päivinä, joina minä sinulle teen, minkä teen? Minä, Herra, olen puhunut, ja minä teen sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Minä hajotan sinut pakanain sekaan ja sirotan sinut muihin maihin ja poistan sinusta saastaisuutesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Sinä tulit saastaiseksi oman itsesi tähden kansojen silmissä, mutta sinä tulet tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, '\"Ihmislapsi, Israelin heimo on kuonaksi tullut. He ovat kaikki tyynni vaskea, tinaa, rautaa ja lyijyä ahjossa; he ovat tulleet hopean kuonaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Sentähden, näin sanoo Herra, Herra: Koska te kaikki tyynni olette tulleet kuonaksi, sentähden, katso, minä kokoan teidät keskelle Jerusalemia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Niinkuin hopea, vaski, rauta, lyijy ja tina kootaan keskelle ahjoa, että niihin lietsottaisiin tulta ja ne sulatettaisiin, niin minä vihassani ja kiivaudessani teidät kokoan ja asetan ahjoon ja sulatan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Minä kerään teidät ja lietson teihin vihani tulta, ja te sulatte keskellä Jerusalemia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Niinkuin hopea sulatetaan keskellä ahjoa, niin sulatetaan teidät sen keskellä. Ja te tulette tietämään, että minä, Herra, olen vuodattanut kiivauteni teidän ylitsenne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, '\"Ihmislapsi, sano sille: Sinä olet maa, jota ei ole puhdistettu, joka ei ole saanut sadetta vihan päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Profeettain salaliitto sen keskellä on niinkuin ärjyvä, saalista raateleva leijona: he syövät sieluja, ottavat aarteet ja kalleudet ja lisäävät sen keskuudessa sen leskien lukua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Sen papit tekevät väkivaltaa minun lailleni ja häpäisevät sitä, mikä on minulle pyhitetty, eivät tee erotusta pyhän ja epäpyhän välillä, eivät tee tiettäväksi, mikä on saastaista, mikä puhdasta, ja sulkevat silmänsä minun sapateiltani, niin että minä tulen häväistyksi heidän keskellänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Sen päämiehet siellä ovat niinkuin saalista raatelevaiset sudet: he vuodattavat verta, hukuttavat sieluja kiskoaksensa väärää voittoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Sen profeetat valkaisevat heille kaiken kalkilla, kun näkevät petollisia näkyjä ja ennustelevat heille valheita sanoen: \'Näin sanoo Herra, Herra\', vaikka Herra ei ole puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Maan kansa harjoittaa väkivaltaa, riistää ja raastaa: kurjaa ja köyhää he sortavat, muukalaiselle tekevät väkivaltaa oikeudesta välittämättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Minä etsin heidän joukostansa miestä, joka korjaisi muurin ja seisoisi muurinaukossa minun edessäni maan puolesta, etten minä sitä hävittäisi, mutta en löytänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Sentähden minä vuodatan heidän ylitsensä kiivauteni, hukutan heidät vihani tulella ja annan heidän vaelluksensa tulla heidän päänsä päälle, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, '\"Ihmislapsi, oli kaksi naista, saman äidin tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'He harjoittivat haureutta Egyptissä; nuoruudessaan he haureutta harjoittivat. Siellä heidän rintojansa likisteltiin ja heidän neitsyellisiä nisiänsä puristeltiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Heidän nimensä olivat: vanhemman Ohola ja hänen sisarensa Oholiba. Sitten he tulivat minun omikseni ja synnyttivät poikia ja tyttäriä. -Heidän nimensä: Samaria on Ohola ja Jerusalem Oholiba.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Mutta Ohola harjoitti haureutta, vaikka oli minun, ja himoitsi rakastajiansa, assurilaisia, naapureita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'jotka olivat punasiniseen purppuraan puettuja ja olivat käskynhaltijoita ja päämiehiä, komeita nuorukaisia kaikki, ratsumiehiä, hevosen selässä ajajia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Ja hän antautui haureuteen näiden kanssa, jotka olivat Assurin valiopoikia kaikki; ja keitä vain hän himoitsi, niiden kaikkien kanssa hän saastutti itsensä kaikilla heidän kivijumalillaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Mutta Egyptin-aikaista haureuttansa hän ei jättänyt, sillä he olivat maanneet hänen kanssansa hänen nuoruudessaan, olivat puristelleet hänen neitsyellisiä nisiänsä ja vuodattaneet hänen ylitsensä haureuttaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Sentähden minä annoin hänet rakastajainsa käsiin, Assurin poikain käsiin, joita hän oli himoinnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'He paljastivat hänen häpynsä ja ottivat hänen poikansa ja tyttärensä ja tappoivat hänet itsensä miekalla, niin että hänestä tuli varoittava esimerkki muille naisille, ja panivat hänessä toimeen tuomiot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Mutta hänen sisarensa Oholiba, vaikka näki tämän, oli himossaan vielä häntäkin riettaampi ja oli haureudessaan vielä riettaampi, kuin hänen sisarensa oli ollut haureudessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Hän himoitsi Assurin poikia, jotka olivat käskynhaltijoita, päämiehiä, naapureita, pulskasti puettuja, ratsumiehiä, hevosen selässä ajajia, komeita nuorukaisia kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Silloin minä näin, että hän saastutti itsensä: sama oli tie kumpaisellakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Mutta hän meni vielä pitemmälle haureudessaan; kun hän näki seinään piirrettyjä miehiä, kaldealaisten kuvia, punavärillä piirrettyjä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'vyö vyötettynä kupeille, päässä muhkea päähine, sankarien näköisiä kaikki, Baabelin poikain muotoisia, joiden synnyinmaa on Kaldea,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'niin hän silmän näkemältä sai himon heihin ja lähetti lähettiläitä heidän luoksensa Kaldeaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Niin Baabelin pojat tulivat ja makasivat hänen kanssaan hekumassa ja saastuttivat hänet haureudellaan, niin että hän saastui heistä. Sitten hänen sielunsa vieraantui heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Mutta kun hän paljasti haureutensa ja paljasti häpynsä, niin minun sieluni vieraantui hänestä, niinkuin minun sieluni oli vieraantunut hänen sisarestansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Mutta hän yhä enensi haureuttaan, kun muisti nuoruutensa päivät, jolloin oli haureutta harjoittanut Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'Ja hän sai himon heidän hekumoitsijoihinsa, joilla on jäsen kuin aaseilla ja vuoto kuin orheilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Ja sinä etsit nuoruutesi iljettävyyttä, jolloin egyptiläiset puristelivat nisiäsi nuorekkaiden rintojesi tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Sentähden, Oholiba, näin sanoo Herra, Herra: Katso, minä nostatan sinun kimppuusi rakastajasi, joista sielusi on vieraantunut, ja tuon heidät sinun kimppuusi joka taholta:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Baabelin pojat ja kaikki kaldealaiset, Pekodin, Sooan ja Kooan ja heidän kanssaan kaikki Assurin pojat-komeita nuorukaisia, käskynhaltijoita ja päämiehiä kaikki, sankareita ja mainioita miehiä, ratsumiehiä, hevosten selässä ajajia kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'He tulevat sinun kimppuusi, mukanaan paljon vaunuja ja rattaita ja suuret joukot kansoja; suurine ja pienine kilpineen ja kypäreineen he käyvät sinua vastaan joka taholta. Minä annan heille tuomiovallan, ja he tuomitsevat sinut oikeuksiensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Minä osoitan sinussa kiivauteni, niin että he kohtelevat sinua tuimasti: he leikkaavat sinulta pois nenän ja korvat, ja sinun jälkeläisesi kaatuvat miekkaan. He ottavat sinun poikasi ja tyttäresi, ja sinun jälkeläisesi kuluttaa tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'He raastavat sinulta vaatteesi ja ottavat korukalusi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Niin minä teen lopun sinun iljettävyydestäsi, jo Egyptin-aikaisesta haureudestasi; etkä sinä sitten luo silmiäsi heihin etkä enää muistele Egyptiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Sillä näin sanoo Herra, Herra: Katso, minä annan sinut niitten käsiin, joita vihaat, niitten käsiin, joista sielusi on vieraantunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Ja he kohtelevat sinua vihamielisesti, ottavat kaiken vaivannäkösi ja jättävät sinut alastomaksi ja paljaaksi; ja sinun haureellinen häpysi ja iljettävyytesi ja haureutesi paljastuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Näin sinulle tehdään sentähden, että uskottomana juoksit pakanain perässä, että saastutit itsesi heidän kivijumalillansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Sinä vaelsit sisaresi tietä, ja minä annan hänen maljansa sinun käteesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Näin sanoo Herra, Herra: Sisaresi maljan sinä juot, syvän ja laajan ja paljon vetävän. Sinä tulet nauruksi ja pilkaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Tulet juopumusta ja murhetta täyteen: kauhun ja häviön malja on sinun sisaresi Samarian malja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Sen sinä juot ja särvit, sen sirpaleita sinä kaluat ja niillä rintasi revit. Sillä minä olen puhunut, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Sentähden, näin sanoo Herra, Herra: Koska sinä olet minut unhottanut, minut selkäsi taakse heittänyt, niin kanna myös iljettävyytesi ja haureutesi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Ja Herra sanoi minulle: \"Ihmislapsi, etkö tuomitse Oholaa ja Oholibaa? Ilmoita heille heidän kauhistuksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Sillä he ovat rikkoneet avion, ja heidän käsissään on verta; kivijumalainsa kanssa he ovat avion rikkoneet, ja myös lapsensa, jotka he olivat minulle synnyttäneet, he ovat polttaneet, ruuaksi niille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Vielä tämänkin he ovat minulle tehneet: ovat samana päivänä saastuttaneet minun pyhäkköni ja rikkoneet minun sapattini.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Teurastettuaan lapsiansa kivijumalilleen he samana päivänä tulivat minun pyhäkkööni ja niin häpäisivät sen. Katso, näin he ovat tehneet keskellä minun huonettani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Vieläpä he lähettivät sanan miehille, jotka tulivat kaukaa: katso, ne tulivat siinä samassa, kun sana oli lähetetty, nuo, joita varten sinä peseydyit ja maalasit silmäluomesi ja panit päällesi korut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Ja sinä istuit komealle vuoteelle, sen ääressä oli katettu pöytä, ja sille sinä panit minun suitsukkeeni ja öljyni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Sitten sieltä kuului suruton melu. Ihmisjoukosta otettujen miesten lisäksi tuotiin erämaasta juomareita, ja ne panivat noiden naisten käsiin rannerenkaat ja heidän päähänsä kauniit kruunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Mutta minä sanoin: \'Tuollekin kuihtuneelle kelpaa aviorikos! Hänen kanssaan nyt harjoitetaan haureutta-ja vielä hänkin!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Hänen luoksensa tultiin, aivan kuin tullaan porttonaisen luo: niin tultiin Oholan ja Oholiban luokse-noiden iljettävien naisten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Mutta vanhurskaat miehet tulevat tuomitsemaan heidät sen mukaan, mitä on säädetty avionrikkoja-naisista ja mitä on säädetty verenvuodattaja-naisista; sillä he ovat rikkoneet avion, ja heidän käsissään on verta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Sillä näin sanoo Herra, Herra: Nostatettakoon kansanjoukko heitä vastaan, ja heidät pantakoon kauhistukseksi ja ryöstettäköön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Ja kansanjoukko kivittäköön heidät ja hakatkoon kappaleiksi miekoillansa; tappakoot ne heidän poikansa ja tyttärensä ja polttakoot heidän talonsa tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Niin minä lopetan iljettävän menon maasta. Ja kaikki naiset ottavat siitä ojentuakseen, niin etteivät harjoita iljettävää menoa, niinkuin te.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Teidän iljettävyytenne pannaan teidän päällenne, ja te saatte kantaa kivijumalainne kanssa tehdyt syntinne. Ja te tulette tietämään, että minä olen Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Tämä Herran sana tuli minulle yhdeksäntenä vuotena, kymmenennessä kuussa, kuukauden kymmenentenä päivänä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, '\"Ihmislapsi, kirjoita muistiisi päivän nimi-juuri tämän päivän nimi: Baabelin kuningas rynnistää Jerusalemia vastaan juuri tänä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Lausu uppiniskaiselle suvulle vertaus ja sano heille: Näin sanoo Herra, Herra: Pane pata liedelle, pane. Kaada myös siihen vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Kokoile siihen lihakappaleet-kaikki hyvät kappaleet, reittä ja lapaa-ja täytä se valituilla luilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Ota valiolampaita, lado myös halkoja sen alle. Anna sen kiehumistaan kiehua, niin että siinä luutkin tulevat keitetyiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Sentähden, näin sanoo Herra, Herra: Voi verivelkojen kaupunkia, pataa, joka on ruostunut ja josta ei lähde sen ruoste! Tyhjennä se kappale kappaleelta: sille ei ole langennut arpaosaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Sillä sen vuodattama veri on sen keskellä, paljaalle kalliolle se on sen koonnut, ei ole vuodattanut sitä maahan, tomun peitettäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Nostattaakseni kiivauden, tuottaakseni koston minä olen pannut sen veren paljaalle kalliolle, ettei se peittyisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Sentähden, näin sanoo Herra, Herra: Voi verivelkojen kaupunkia! Minäkin suurennan liettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Lisää halkoja, viritä tulta, keitä liha loppuun, kiehuta liemi kuiviin, polta luut karreksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Anna sen sitten olla tyhjänä hiiltensä päällä, niin että se kuumenee, sen vaski hehkuu ja sen saastat siitä sulavat, sen ruosteesta tulee loppu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Siitä on ollut vaivaa väsymykseen asti, mutta ei ole lähtenyt siitä sen ruosteen paljous. Tuleen sen ruoste!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'Sinun iljettävän saastaisuutesi takia-koska minä tahdoin puhdistaa sinut, mutta sinä et puhdistunut saastaisuudestasi-sinä et enää puhdistu, ennenkuin minä olen tyydyttänyt kiivauteni sinussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Minä, Herra, olen puhunut. Se tapahtuu, ja minä teen sen. Minä en hellitä, en säästä enkä kadu: teittesi ja tekojesi mukaan sinut tuomitaan, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, '\"Ihmislapsi, katso, minä otan sinulta äkkikuolemalla pois silmiesi ihastuksen, mutta älä valita, älä itke, älköönkä tulko sinulta kyyneltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Huokaile hiljaa, mutta älä pane toimeen kuolleenvalittajaisia. Sido juhlapäähine päähäsi, pane kengät jalkaasi, älä peitä partaasi äläkä syö suruleipää.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Ja minä puhuin kansalle aamulla, mutta illalla kuoli minun vaimoni; sitten aamulla minä tein, niinkuin minun oli käsketty tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Niin kansa sanoi minulle: \"Etkö meille ilmoita, mitä se tietää meille, kun sinä noin teet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Minä sanoin heille: \"Minulle tuli tämä Herran sana: Sano Israelin heimolle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Näin sanoo Herra, Herra: Katso, minä häpäisen pyhäkköni, joka on teidän varustuksenne ja ylpeytenne, teidän silmienne ihastus ja sielujenne ikävä; ja teidän poikanne ja tyttärenne, jotka teidän on ollut jätettävä, kaatuvat miekkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Sitten te teette, niinkuin minä olen tehnyt: ette peitä partaanne ettekä syö suruleipää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'juhlapäähineen pidätte päässänne ja kengät jalassanne, ette valita ettekä itke, mutta te riudutte syntivelkanne tähden ja huokailette toinen toisellenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Hesekiel on oleva teille ennusmerkki: aivan niin, kuin hän on tehnyt, niin tekin teette. Kun tämä tapahtuu, te tulette tietämään, että minä olen Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Ja sinä, ihmislapsi! Sinä päivänä, jona minä otan heiltä heidän varustuksensa, ihanan ilonsa, silmiensä ihastuksen, sielujensa halajamisen, heidän poikansa ja tyttärensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'sinä päivänä tulee pakolainen sinun luoksesi ilmoittamaan tätä korvaisi kuullen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'Sinä päivänä avautuu sinun suusi yhtaikaa kuin pakolaisen, ja sinä puhut etkä enää ole mykkänä. Sinä olet oleva heille ennusmerkki, ja he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, '\"Ihmislapsi, käännä kasvosi ammonilaisia kohti ja ennusta heitä vastaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'ja sano ammonilaisille: Kuulkaa Herran, Herran sana: Näin sanoo Herra, Herra: Koska sinä sanoit: \'Kas niin!\' minun pyhäköstäni, kun se häväistiin, ja Israelin maasta, kun se hävitettiin, ja Juudan heimosta, kun he menivät pakkosiirtolaisuuteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'sentähden, katso, minä annan sinut Idän miehille omaksi, ja he laittavat sinuun leiripaikkansa ja asettavat sinuun asuntonsa. He syövät sinun hedelmäsi ja juovat maitosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Ja Rabban minä panen kamelien laitumeksi ja ammonilaisten maan lammaslaumojen leposijaksi. Ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Sillä näin sanoo Herra, Herra: Koska sinä käsiä taputit ja jalkaa poljit ja, sielu täynnä ylenkatsetta, pidit iloa Israelin maasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'sentähden, katso, minä ojennan käteni sinua vastaan ja annan sinut pakanain ryöstettäväksi ja hävitän sinut kansojen joukosta ja hukutan sinut maitten luvusta ja tuhoan sinut. Ja sinä tulet tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Näin sanoo Herra, Herra: Koska Mooab ja Seir ovat sanoneet: \'Katso, Juudan heimon käy samoin kuin kaikkien muitten kansain\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'sentähden, katso, minä teen avonaiseksi Mooabin vuoriselänteen, paljaaksi kaupungeista-kaupungeista sen rajasta toiseen-jotka ovat maan kaunistus: Beet-Jesimot, Baal-Meon ja Kirjataim.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Idän miehille omaksi minä annan sen ynnä ammonilaiset, niin ettei ammonilaisia enää muisteta kansojen seassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'ja Mooabissa minä panen toimeen tuomiot. Ja he tulevat tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Näin sanoo Herra, Herra: Koska Edom menetteli kovin kostonhimoisesti Juudan heimoa kohtaan ja tuli suuresti syynalaiseksi, kostaessansa heille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'sentähden, näin sanoo Herra, Herra: Minä ojennan käteni Edomia vastaan ja hävitän siitä ihmiset ja eläimet. Teemanista lähtien minä panen sen raunioiksi, ja Dedania myöten he kaatuvat miekkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Ja kostoni, joka Edomia kohtaa, minä annan kansani Israelin käteen, ja he tekevät Edomia kohtaan minun vihani ja kiivauteni mukaan. Ja Edom saa tuntea minun kostoni, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Näin sanoo Herra, Herra: Koska filistealaiset menettelivät kostonhimoisesti ja, ylenkatse sielussaan, kostivat kovasti, ikivihassa tuottaaksensa tuhon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'sentähden, näin sanoo Herra, Herra: Katso, minä ojennan käteni filistealaisia vastaan, hävitän kreetit, hukutan, mitä on jäljellä meren rannikolla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'ja teen heille suuret kostoteot, rangaisten kiivaudessa. Ja he tulevat tietämään, että minä olen Herra, kun minä annan kostoni heitä kohdata.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Yhdentenätoista vuotena, kuukauden ensimmäisenä päivänä, tuli minulle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, '\"Ihmislapsi, koska Tyyro sanoi Jerusalemista: \'Kas niin! Murrettu on kansojen ovi, minuun päin se on kääntynyt, minä tulen täyteen-se on rauniona!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'sentähden, näin sanoo Herra, Herra: Katso, minä käyn sinun kimppuusi, Tyyro, ja nostatan monet kansat sinua vastaan, niinkuin meri nostaa aaltonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Ne hävittävät Tyyron muurit, repivät maahan sen tornit, ja minä lakaisen siitä pois sen tomutkin ja panen sen paljaaksi kallioksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Siitä tulee verkkojen kuivauspaikka keskelle merta. Sillä minä olen puhunut, sanoo Herra, Herra; ja se joutuu kansojen ryöstettäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Sen tytärkaupungit, jotka ovat mantereella, surmataan miekalla, ja he tulevat tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Sillä näin sanoo Herra, Herra: Katso, minä tuon Tyyron kimppuun Nebukadressarin, Baabelin kuninkaan pohjoisesta, kuninkaitten kuninkaan, hevosten ja vaunujen ja ratsumiesten ja suuren väenpaljouden kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Sinun tytärkaupunkisi, jotka ovat mantereella, hän surmaa miekalla ja asettaa sinua vastaan saartovarusteet, luo sinua vastaan vallin, nostaa sinua vastaan kilpikatoksen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'suuntaa sinun muureihisi murtajansa iskut ja kukistaa tornisi rauta-aseillansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Hänen hevostensa paljous peittää sinut pölyyn. Ratsumiesten, pyöräin ja vaunujen ryskeestä sinun muurisi vapisevat, kun hän hyökkää sisälle sinun porteistasi, niinkuin valloitettuun kaupunkiin hyökätään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Hevostensa kavioilla hän tallaa rikki sinun katusi kaikki, surmaa miekalla sinun kansasi, ja sinun mahtavat patsaasi kaatuvat maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'He riistävät sinun rikkautesi ja ryöstävät kauppatavarasi, repivät muurisi maahan ja kukistavat kauniit talosi, ja kivesi, puusi, tomusi he heittävät meren syvyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Minä lakkautan laulujesi helinän, eikä kuulu enää kanneltesi soitto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Minä panen sinut paljaaksi kallioksi, sinusta tulee verkkojen kuivauspaikka, eikä sinua enää rakenneta. Sillä minä, Herra, olen puhunut, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Näin sanoo Herra, Herra Tyyrolle: Eivätkö sinun kukistumisesi pauhusta, kun haavoitetut voihkivat, kun surman omat surmataan sinun keskelläsi, saaret vapise?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Valtaistuimiltaan astuvat alas kaikki meren ruhtinaat. He heittävät pois viittansa ja riisuvat kirjaellut vaatteensa, he pukeutuvat kauhuun ja istuvat maahan, värisevät joka hetki, tyrmistyneinä sinun tähtesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'He virittävät sinusta itkuvirren ja sanovat sinulle: \'Kuinka olet sinä, joka olit asuttu, hävinnyt meriltä, sinä ylistetty kaupunki, väkevä merellä, sinä ja sinun asukkaasi, jotka levittivät kauhuansa kaikkiin siellä asuvaisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Nyt värisevät saaret sinun kukistumisesi päivänä, merensaaret kauhistuvat sinun loppuasi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Sillä näin sanoo Herra, Herra: Kun minä teen sinusta aution kaupungin, niinkuin asumattomat kaupungit ovat, kun minä annan syvyyden käydä sinun ylitsesi ja paljot vedet peittävät sinut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'silloin minä syöksen sinut alas hautaanvaipuneitten pariin, ikiaikojen kansan tykö, ja annan sinulle asunnon maan syvyyksissä, niinkuin siellä ovat ikiaikojen rauniot, hautaanvaipuneitten parissa, ettei sinussa asuttaisi; mutta ihanuuden minä annan elävien maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Sinut minä panen kauhuksi, sinua ei sitten enää ole; ja jos sinua etsitään, ei sinua enää löydy, hamaan ikiaikoihin asti, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, '\"Sinä, ihmislapsi! Viritä itkuvirsi Tyyrosta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'ja sano Tyyrolle, joka asuu meren porteilla ja käy kauppaa kansojen kanssa, monilukuisilla saarilla: Näin sanoo Herra, Herra: Tyyro, sinä sanot: \'Minä olen kauneuden täydellisyys!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Meren sydämessä on sinun alueesi, rakentajasi tekivät sinun kauneutesi täydelliseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Senirin kypresseistä he rakensivat sinuun kaiken, mikä laudoista on, ottivat Libanonin setrin tehdäkseen sinuun maston,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'tekivät Baasanin tammista airosi, kantesi tekivät norsunluusta ja Kittiläis-saarten hopeakuusesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Kirjaeltua Egyptin pellavaa oli purjeesi, ja se oli sinulla lippuna. Katoksesi oli punasinistä ja purppuranpunaista Elisa-saarten kangasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Siidonin ja Arvadin asukkaat olivat sinulla soutajina; omat viisaasi, Tyyro, olivat sinussa-he olivat laivureinasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Gebalin vanhimmat ja viisaat olivat sinussa vuotokohtain korjaajina. Meren kaikki laivat merimiehineen olivat sinussa tavaroitasi vaihtamassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Persia ja Luud ja Puut olivat sotajoukossasi, sinun sotureinasi. He ripustivat sinuun kypäreitä ja kilpiä; ne sinua koristivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Arvadilaiset ja muu sotajoukkosi olivat muureillasi yltympäri ja gammadilaiset torneissasi. He ripustivat varustuksensa sinun muureillesi yltympäri; ne tekivät sinun kauneutesi täydelliseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tarsis oli kauppatuttusi sinun kaikkinaisten rikkauksiesi runsauden takia: hopealla, raudalla, tinalla ja lyijyllä he maksoivat sinun tavarasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Jaavan, Tuubal ja Mesek kävivät kauppaa sinun kanssasi: orjilla ja vaskikaluilla he maksoivat sinun vaihtotavarasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Toogarman heimo maksoi sinun tavarasi hevosilla, sotaratsuilla ja muuleilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Dedanilaiset kävivät kauppaa sinun kanssasi. Monilukuiset saaret olivat kauppatuttujasi, sinun käskysi alaisia; norsunhampaita ja mustaa puuta ne toivat sinulle verona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Aram oli kauppatuttusi sinun tuotteittesi runsauden takia: rubiineilla, punapurppuralla, kirjaellulla kankaalla, valkopellavalla, koralleilla ja jaspiksella he maksoivat sinun tavarasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juuda ja Israelin maa kävivät kauppaa sinun kanssasi: Minnitin nisulla, leivoksilla, hunajalla, öljyllä ja balsamilla he maksoivat sinun vaihtotavarasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damasko oli kauppatuttusi sinun tuotteittesi runsauden ja kaikkinaisten rikkauksiesi runsauden takia: Helbonin viiniä ja Saharin villoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Vedan ja Jaavan maksoivat sinun tavarasi kehruuteoksilla; taottua rautaa, kassiaa ja kalmoruokoa tuli sinulle vaihtotavarana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan kävi kauppaa sinun kanssasi ratsastussatulain loimilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabia ja kaikki Keedarin ruhtinaat olivat kauppatuttaviasi, sinun käskysi alaisia: lampaita, oinaita ja vuohipukkeja he sinulle kauppasivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Saban ja Raman kauppiaat kävivät kauppaa sinun kanssasi: kaikkinaisilla parhailla balsameilla, kaikilla kalliilla kivillä ja kullalla he maksoivat sinun tavarasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Haaran ja Kanne ja Eden, Saban kauppiaat, Assur ja Kilmad kävivät kauppaa sinun kanssasi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'he kävivät kanssasi kauppaa sinun markkinoillasi kauniilla vaatteilla, punasinisillä ja kirjaelluilla vaipoilla, kirjavakuteisilla matoilla ja punotuilla, kestävillä köysillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Tarsiin-laivat kuljettivat sinun vaihtotavaroitasi. Niin sinä tulit täpötäyteen ja ylen raskaaseen lastiin merten sydämessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Soutajasi veivät sinut suurille vesille. -Itätuuli särkee sinut merten sydämessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Sinun rikkautesi, tavarasi, vaihtotavarasi, merimiehesi ja laivurisi, vuotokohtaisi korjaajat, tavaranvaihtajasi ja kaikki sotamiehesi, jotka ovat sinussa ja koko suuressa joukossasi, joka sinun keskelläsi on, vaipuvat merten sydämeen sinun kukistumisesi päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Laivuriesi parkunan äänestä vapisevat tantereet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Alas haaksistansa astuvat kaikki aironpitelijät, merimiehet ja kaikki meren laivurit astuvat maihin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'huutavat sinun tähtesi suurella äänellä ja parkuvat haikeasti, heittävät tomua päänsä päälle ja vieriskelevät tuhassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'He ajelevat sinun tähtesi päänsä paljaaksi, kääriytyvät säkkeihin ja itkevät sinun tähtesi, mieli murheellisena, valittaen haikeasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'He valittaessaan virittävät sinusta itkuvirren ja laulavat sinusta: \'Kuka oli Tyyron vertainen, hänen, joka nyt on niin hiljaa keskellä merta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Kun sinun tavarasi saapuivat meriltä, ravitsit sinä monet kansat. Rikkauksiesi ja vaihtotavaraisi runsaudella sinä teit rikkaiksi maan kuninkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Nyt, kun jouduit haaksirikkoon, pois meriltä, vetten syvyyksiin, vaipuivat sinun mukanasi sinne vaihtotavarasi ja koko sinun suuri joukkosi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Sinun tähtesi tyrmistyvät kaikki saarten asukkaat, ja heidän kuninkaansa ovat kauhun vallassa, vavistus kasvoillansa. 27:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Sinulle viheltävät kauppatutut kansojen joukossa. Kauhuksi olet sinä tullut, eikä sinua enää ole, hamaan ikiaikoihin asti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, '\"Ihmislapsi, sano Tyyron ruhtinaalle: Näin sanoo Herra, Herra: Koska sinun sydämesi on ylpistynyt ja sinä sanot: \'Minä olen jumala, jumalain istuimella minä istun merten sydämessä\', ja olet kuitenkin ihminen, et jumala, vaikka omasta mielestäsi olet jumalan vertainen-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'ja katso, viisaampi sinä oletkin kuin Daniel, ei mikään salaisuus ole sinulta pimitetty;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'viisaudessasi ja ymmärtäväisyydessäsi olet hankkinut itsellesi rikkautta, hankkinut kultaa ja hopeata aarreaittoihisi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'ja suuressa viisaudessasi olet kaupankäynnillä kartuttanut rikkautesi, ja niin sinun sydämesi on ylpistynyt rikkaudestasi-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'sentähden, näin sanoo Herra, Herra: Koska omasta mielestäsi olet jumalan vertainen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'sentähden, katso, minä tuon sinun kimppuusi muukalaiset, julmimmat pakanoista; he paljastavat miekkansa sinun viisautesi kauneutta vastaan ja häpäisevät sinun ihanuutesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'He syöksevät sinut alas kuoppaan, ja sinä kuolet, niinkuin kaadetut kuolevat, merten sydämessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Vieläköhän sanot surmaajasi edessä: \'Minä olen jumala\', kun kuitenkin olet ihminen, et jumala, kaatajaisi käsissä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Niinkuin kuolevat ympärileikkaamattomat, niin sinä kuolet muukalaisten käden kautta. Sillä minä olen puhunut, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, '\"Ihmislapsi, viritä itkuvirsi Tyyron kuninkaasta ja sano hänelle: Näin sanoo Herra, Herra: Sinä olet sopusuhtaisuuden sinetti, täynnä viisautta, täydellinen kauneudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Eedenissä, Jumalan puutarhassa, sinä olit. Peitteenäsi olivat kaikkinaiset kalliit kivet; karneolia, topaasia ja jaspista, krysoliittia, onyksia ja berylliä, safiiria, rubiinia ja smaragdia sekä kultaa olivat upotus-ja syvennystyöt sinussa, valmistetut sinä päivänä, jona sinut luotiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Sinä olit kerubi, laajalti suojaavainen, ja minä asetin sinut pyhälle vuorelle; sinä olit jumal\'olento ja käyskentelit säihkyväin kivien keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Nuhteeton sinä olit vaellukseltasi siitä päivästä, jona sinut luotiin, siihen saakka, kunnes sinussa löydettiin vääryys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Suuressa kaupankäynnissäsi tuli sydämesi täyteen väkivaltaa, ja sinä teit syntiä. Niin minä karkoitin sinut häväistynä Jumalan vuorelta ja hävitin sinut, suojaava kerubi, pois säihkyväin kivien keskeltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Sinun sydämesi ylpistyi sinun kauneudestasi, ihanuutesi tähden sinä kadotit viisautesi. Minä viskasin sinut maahan, annoin sinut alttiiksi kuninkaille, heidän silmänherkukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Paljoilla synneilläsi, tekemällä vääryyttä kaupoissasi, sinä olet häväissyt pyhäkkösi. Niin minä annoin sinun keskeltäsi puhjeta tulen; se kulutti sinut. Ja minä panin sinut tuhaksi maahan kaikkien silmäin edessä, jotka sinut näkivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Kaikki tuttavasi kansojen seassa ovat tyrmistyneet sinun tähtesi. Kauhuksi olet sinä tullut, eikä sinua enää ole, hamaan ikiaikoihin asti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, '\"Ihmislapsi, käännä kasvosi Siidonia kohti ja ennusta sitä vastaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'ja sano: Näin sanoo Herra, Herra: Katso, minä käyn sinun kimppuusi, Siidon, ja näytän kunniani sinun keskuudessasi. Ja he tulevat tietämään, että minä olen Herra, kun minä siinä panen toimeen tuomiot ja näytän siinä pyhyyteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Minä lähetän sinne ruton ja verta sen kaduille, ja kaatuneita on viruva sen keskellä, kaatuneita miekkaan, joka käy sen kimppuun joka taholta. Ja he tulevat tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Sitten ei Israelin heimolle enää ole pistävänä orjantappurana eikä vaivaavana ohdakkeena yksikään sen naapureista, jotka ovat heitä halveksineet. Ja he tulevat tietämään, että minä olen Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Näin sanoo Herra, Herra: Kun minä kokoan Israelin heimon kansoista, joitten sekaan he ovat hajotetut, silloin minä näytän pyhyyteni heissä pakanakansain silmien edessä, ja he saavat asua maassansa, jonka minä annoin palvelijalleni Jaakobille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'He asuvat siinä turvallisesti ja rakentavat taloja ja istuttavat viinitarhoja. Turvallisesti he asuvat, kun minä panen toimeen tuomiot kaikille heidän naapureillensa, jotka ovat heitä halveksineet. Ja he tulevat tietämään, että minä olen Herra, heidän Jumalansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Kymmenentenä vuotena, kymmenennessä kuussa, kuukauden kahdentenatoista päivänä tuli minulle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, '\"Ihmislapsi, käännä kasvosi faraota, Egyptin kuningasta, kohti ja ennusta häntä ja koko Egyptiä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Puhu ja sano: Näin sanoo Herra, Herra: Katso, minä käyn sinun kimppuusi, farao, Egyptin kuningas-suuri krokodiili, joka makaat virtojesi keskellä, joka sanot: \'Niilivirtani on minun, ja minä olen sen itselleni tehnyt\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Minä panen koukut sinun leukoihisi, tartutan virtojesi kalat sinun suomuihisi ja nostan sinut ylös virtojesi keskeltä sekä kaikki virtojesi kalat, jotka ovat suomuihisi tarttuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Minä viskaan erämaahan sinut ja kaikki virtojesi kalat. Sinä putoat kedolle, ei sinua korjata, ei koota. Metsän pedoille ja taivaan linnuille minä annan sinut ruuaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Ja kaikki Egyptin asukkaat tulevat tietämään, että minä olen Herra. Sillä he ovat ruokosauva Israelin heimolle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'kun he kädellä tarttuvat sinuun, niin sinä säryt ja lävistät heiltä olkapäät kaikki; ja kun he nojaavat sinuun, niin sinä murrut ja jäykistät heiltä lanteet kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Sentähden, näin sanoo Herra, Herra: Katso, minä tuon sinun kimppuusi miekan ja hävitän sinusta ihmiset ja eläimet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'ja Egyptin maa tulee autioksi ja raunioksi. Ja he tulevat tietämään, että minä olen Herra. Sillä hän on sanonut: \'Niilivirta on minun, ja minä olen sen tehnyt\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Sentähden, katso, minä käyn sinun ja sinun virtojesi kimppuun ja teen Egyptin maan raunioiksi, kuivaksi ja autioksi Migdolista Seveneen ja hamaan Etiopian rajaan saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Ei käy siellä ihmisjalka, ei käy siellä eläimen jalka, eikä asuta siellä neljäänkymmeneen vuoteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Autioksi minä teen Egyptin maan autioiksi tehtyjen maitten joukossa, ja sen kaupungit tulevat olemaan autioina raunioiksi pantujen kaupunkien joukossa neljäkymmentä vuotta, ja egyptiläiset minä hajotan kansojen sekaan ja sirotan heidät muihin maihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Sillä näin sanoo Herra, Herra: Neljänkymmenen vuoden kuluttua minä kokoan egyptiläiset kansoista, joiden sekaan he olivat hajotetut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'käännän Egyptin kohtalon ja tuon heidät takaisin Patroksen maahan, synnyinmaahansa. Siellä he tulevat olemaan vähäpätöisenä valtakuntana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'He tulevat olemaan vähäpätöisin valtakunnista, eivätkä enää kohoa kansakuntien ylitse. Minä vähennän heidät niin, etteivät he enää kansoja vallitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Eivätkä he enää kelpaa turvaksi Israelin heimolle: he saattavat muistoon Israelin syntivelan, jos se kääntyy heitä seuraamaan. Ja he tulevat tietämään, että minä olen Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Kahdentenakymmenentenä seitsemäntenä vuotena, ensimmäisessä kuussa, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, '\"Ihmislapsi, Baabelin kuningas Nebukadressar on teettänyt sotajoukoillansa raskasta työtä Tyyroa vastaan: kaikki päät ovat käyneet kaljuiksi ja kaikki olkapäät lyöpyneet; mutta palkkaa ei Tyyrosta ole tullut hänelle eikä hänen sotajoukoilleen työstä, jota ovat tehneet sitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Sentähden, näin sanoo Herra, Herra: Katso, minä annan Baabelin kuninkaalle Nebukadressarille Egyptin maan. Hän vie sen tavaran paljouden, saa sen saaliit, ryöstää sen ryöstökset: se on oleva hänen sotajoukkojensa palkka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Palkaksi, jonka toivossa hän on työtä tehnyt, minä annan hänelle Egyptin maan; sillä minun hyväkseni he ovat sitä tehneet, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Sinä päivänä minä annan puhjeta Israelin heimolle sarven, ja sinulle minä annan voiman avata suusi heidän keskellänsä. Ja he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, '\"Ihmislapsi, ennusta ja sano: Näin sanoo Herra, Herra: Valittakaa: \'Voi sitä päivää!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Sillä lähellä on päivä, lähellä Herran päivä; se on pilvinen päivä, pakanakansojen aika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Miekka yllättää Egyptin, ja Etiopialla on tuska, kun surmattuja kaatuu Egyptissä, kun siltä otetaan pois tavarain paljous ja revitään perustukset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Etiopia, Puut ja Luud, kaikki sekakansa, Kuub ja liittoutuneen maan miehet kaatuvat heidän kanssansa miekkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Näin sanoo Herra: Egyptin tuet kaatuvat, ja sen ylpeä uhma alenee. Migdolista Seveneen asti he siellä kaatuvat miekkaan, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Autioiksi he joutuvat autioiksi tehtyjen maitten joukossa, ja heidän kaupunkinsa tulevat olemaan raunioiksi pantujen kaupunkien joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'Ja he tulevat tietämään, että minä olen Herra, kun minä sytytän Egyptin tuleen ja kaikki sen auttajat murtuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Sinä päivänä lähtee minun tyköäni laivoilla lähettiläitä peljästyttämään levossa elävää Etiopiaa, ja heille tulee tuska niinkuin Egyptin päivänä; sillä katso, se tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Näin sanoo Herra, Herra: Minä teen lopun Egyptin meluavista joukoista Baabelin kuninkaan Nebukadressarin käden kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Hän ja hänen väkensä hänen kanssaan, julmimmat pakanoista, tuodaan hävittämään maata, ja he paljastavat miekkansa Egyptiä vastaan ja täyttävät maan surmatuilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Minä panen virrat kuiville ja myyn maan pahojen käsiin ja teen autioksi maan ja kaiken, mitä siinä on, muukalaisten käden kautta. Minä, Herra, olen puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Näin sanoo Herra, Herra: Minä tuhoan kivijumalat ja lopetan epäjumalat Noofista ja ruhtinaat Egyptistä: niitä ei ole enää oleva; ja minä saatan Egyptin maan pelon valtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Minä teen Patroksen autioksi, sytytän Sooanin tuleen ja panen toimeen tuomiot Noossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Minä vuodatan kiivauteni Siiniin, Egyptin linnoitukseen, hävitän Noon meluavat joukot');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'ja sytytän Egyptin tuleen. Siin kierii tuskassa, Noo valloitetaan, ja Noof-ahdistajia selvällä päivällä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Aavenin ja Piibesetin nuorukaiset kaatuvat miekkaan, ja ne itse menevät vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Tehafneheessa päivä pimenee, kun minä siellä särjen Egyptin ikeen, ja siinä saa lopun sen ylpeä uhma. Sen itsensä peittää pilvi, ja sen tyttäret menevät vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Niin minä panen tuomiot toimeen Egyptissä, ja he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Yhdentenätoista vuotena, ensimmäisessä kuussa, kuukauden seitsemäntenä päivänä tuli minulle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, '\"Ihmislapsi, minä olen murskannut faraon, Egyptin kuninkaan, käsivarren, ja katso, sitä ei sidota, ei parannella, ei panna kääreeseen, että se sidottuna vahvistuisi tarttuaksensa miekkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Sentähden, näin sanoo Herra, Herra: Katso, minä käyn faraon, Egyptin kuninkaan, kimppuun ja murskaan häneltä käsivarret, sekä voimakkaan että murskatun käden, ja pudotan miekan hänen kädestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Minä hajotan egyptiläiset kansojen sekaan ja sirotan heidät muihin maihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Baabelin kuninkaan käsivarret minä vahvistan ja annan miekkani hänen käteensä; mutta faraolta minä murskaan käsivarret, ja hän voihkii hänen edessänsä, niinkuin kaadettu voihkii.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Niin, minä vahvistan Baabelin kuninkaan käsivarret, mutta faraon käsivarret vaipuvat alas. Ja he tulevat tietämään, että minä olen Herra, kun minä annan miekkani Baabelin kuninkaan käteen, että hän ojentaa sen Egyptin maata vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Ja minä hajotan egyptiläiset kansojen sekaan ja sirotan heidät muihin maihin. Ja he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Yhdentenätoista vuotena, kolmannessa kuussa, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, '\"Ihmislapsi, sano faraolle, Egyptin kuninkaalle, ja hänen meluaville joukoillensa: Kenen kaltainen sinä olet suuruudessasi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Katso, Assur oli setri Libanonilla, kaunislehväinen, taajavarjoinen, korkeakasvuinen, ja sen latva oli tiheän lehvistön keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Vedet olivat sen suureksi kasvattaneet, korkeaksi oli sen saanut syvyys, joka virtoinensa kiersi sen istutusmaata ja lähetti ojiansa kaikille metsän puille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Sentähden siitä tuli korkeakasvuisin kaikista metsän puista, se sai haaroja paljon, ja oksat, joita se levitti, venyivät pitkiksi runsaista vesistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Sen lehvillä pesivät kaikki taivaan linnut, sen oksien alla synnyttivät kaikki metsän eläimet, ja sen varjossa asuivat kaikki suuret kansat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Kaunis se oli suuruudessaan, oksiensa pituudessa, sillä sen juuri oli runsasten vetten ääressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Eivät olleet setrit sen vertaiset Jumalan puutarhassa, eivät kypressit sen oksien veroiset, eivät plataanit niinkuin sen haarat. Ei yksikään puu Jumalan puutarhassa ollut sen veroinen kauneudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Minä tein sen niin kauniiksi oksarunsaudessaan, että kaikki Eedenin puut Jumalan puutarhassa sitä kadehtivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Sentähden, näin sanoo Herra, Herra: Koska se tuli korkeakasvuiseksi ja sen latva oli tiheän lehvistön keskellä ja sen sydän ylpistyi sen korkeudesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'annan minä sen pakanoista mahtavimman käsiin, ja hän tekee sille, minkä tekee; jumalattomuutensa tähden minä sen olen karkoittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Ja sen hakkasivat muukalaiset, julmimmat pakanoista, ja heittivät sen maahan. Vuorille ja kaikkiin laaksoihin kaatuivat sen haarat, ja sen oksat murskaantuivat kaikkiin maan puronotkoihin. Kaikki maan kansat laskeutuivat alas sen varjosta ja jättivät sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Sen kaatuneella rungolla asuvat kaikki taivaan linnut, ja sen oksien ääressä oleskelevat kaikki metsän eläimet-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'ettei yksikään puu vetten vierellä kasvaisi niin korkeaksi eikä ojentaisi latvaansa pilvien väliin ja etteivät mahtavimmatkaan niistä, ei mitkään, jotka vettä juovat, olisi pysyväisiä korkeudessaan, sillä ne ovat kaikki annetut alttiiksi kuolemalle, menemään maan syvyyteen, hautaanvaipuneitten pariin yhdessä ihmislasten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Näin sanoo Herra, Herra: Sinä päivänä, jona hän astui alas tuonelaan, minä verhosin syvyyden suruun hänen tähtensä, pidätin virrat, niin että paljot vedet pysähtyivät juoksussaan, ja puin Libanonin hänen tähtensä mustiin, ja kaikki metsän puut nääntyivät hänen tähtensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Hänen kaatumisensa ryskeestä minä panin kansakunnat vapisemaan, kun minä syöksin hänet alas tuonelaan, hautaanvaipuneitten pariin. Mutta lohdutetuiksi tulivat maan syvyydessä kaikki Eedenin puut, Libanonin valiot ja parhaat, kaikki, jotka vettä juovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Myöskin ne olivat hänen kanssansa astuneet alas tuonelaan, miekalla kaadettujen pariin; samoin hänen auttajansa, ne, jotka istuivat hänen varjossaan kansojen joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Oliko yhtään Eedenin puista sinun vertaistasi kunniassa ja suuruudessa? Mutta sinut on Eedenin puitten kanssa syösty alas maan syvyyteen; ympärileikkaamattomien keskellä sinä makaat miekallakaadettujen parissa. Näin käy faraon ja koko hänen meluavan joukkonsa, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Kahdentenatoista vuotena, kahdennessatoista kuussa, kuukauden ensimmäisenä päivänä tuli minulle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, '\"Ihmislapsi, viritä itkuvirsi faraosta, Egyptin kuninkaasta, ja sano hänelle: Nuori leijona kansojen seassa, sinä olet hukassa! Sinä olit kuin krokodiili virroissa: sinä kuohutit virtojasi, sotkit vettä jaloillasi ja hämmensit sen virtoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Näin sanoo Herra, Herra: Minä levitytän verkkoni sinun ylitsesi monien kansojen suurella joukolla, ja ne vetävät sinut ylös minun pyydykselläni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Minä viskaan sinut maalle, heitän sinut kedolle, panen asustamaan sinun ylläsi kaikki taivaan linnut ja syötän sinusta kylläisiksi kaiken maan eläimet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Minä jätän sinun lihasi vuorten hyviksi ja täytän raatokasallasi laaksot,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'juotan maan sillä, mikä sinusta valuu, sinun verelläsi aina vuorille asti, ja purojen uomat tulevat sinusta täyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Minä peitän taivaan, kun sinut sammutan, ja puen mustiin sen tähdet; auringon minä peitän pilviin, eikä kuu anna valonsa loistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Kaikki taivaan loistavat valot minä puen mustiin sinun tähtesi ja peitän sinun maasi pimeyteen, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Minä murehdutan monien kansain sydämet, kun saatan tiedoksi sinun perikatosi kansakunnille, maihin, joita sinä et tuntenut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'ja minä tyrmistytän sinun tähtesi monet kansat, ja heidän kuninkaansa kovin värisevät sinun tähtesi, kun minä heilutan miekkaani heidän nähtensä, ja he vapisevat joka hetki kukin omaa henkeänsä sinun kukistumisesi päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Sillä näin sanoo Herra, Herra: Baabelin kuninkaan miekka yllättää sinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Minä kaadan sinun meluisan joukkosi sankarien miekoilla; ne ovat julmimpia pakanoista kaikki tyynni. He kukistavat Egyptin komeuden, kaikki sen meluisa joukko tuhotaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Ja minä hävitän siitä kaiken karjan runsasten vetten ääriltä. Eikä niitä enää sotke ihmisen jalka, eivätkä sotke niitä karjan sorkat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Silloin minä annan sen vetten laskeutua kirkkaiksi, ja minä panen sen virrat juoksemaan kuin öljyn, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Kun minä teen Egyptin maan autioksi, kun maa tulee autioksi kaikesta, mitä siinä on, ja kun minä surmaan kaikki sen asukkaat, tulevat he tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Itkuvirsi tämä on, ja sitä kyllä viritetään. Pakanakansain tyttäret sitä virittävät-virittävät sitä Egyptistä ja kaikesta sen meluisasta joukosta, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Kahdentenatoista vuotena, kuukauden viidentenätoista päivänä tuli minulle tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, '\"Ihmislapsi, veisaa kuolinvalitus Egyptin meluisasta joukosta, saata se ja mahtavain pakanakansojen tyttäret alas maan syvyyksiin, hautaanvaipuneitten pariin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Oletko vielä kaikkia muita ihanampi? Astu alas ja anna laittaa makuusijasi ympärileikkaamattomien pariin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'He kaatuvat miekallasurmattujen joukkoon. Miekka on jo annettu! Temmatkaa pois Egypti kaikkine meluisine joukkoineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Mahtavimmat sankareista puhuvat tuonelan keskeltä sille ynnä sen auttajille: \'Alas ovat astuneet, siellä makaavat ympärileikkaamattomat, miekalla surmatut\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Siellä on Assur kaikkine joukkoinensa. Niitten haudat ovat hänen ympärillänsä. Kaikki tyynni ovat surmattuja, miekkaan kaatuneita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Hänen hautansa ovat pohjimmaisessa kuopassa, ja hänen joukkonsa on hänen hautansa ympärillä; ne ovat kaikki tyynni surmattuja, miekkaan kaatuneita, nuo, jotka levittivät kauhua elävien maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Siellä on Eelam, ja koko hänen meluisa joukkonsa on hänen hautansa ympärillä; kaikki tyynni surmattuja, miekkaan kaatuneita, jotka ympärileikkaamattomina astuivat alas maan syvyyksiin, nuo, jotka levittivät kauhuansa elävien maassa, mutta saavat kantaa häpeänsä hautaanvaipuneitten parissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Surmattujen keskellä on makuusija annettu hänelle ynnä kaikelle hänen meluisalle joukolleen. Niitten haudat ovat hänen ympärillänsä. Kaikki tyynni ne ovat ympärileikkaamattomia, miekalla surmattuja, sillä he olivat kauhuna elävien maassa, mutta saavat kantaa häpeänsä hautaanvaipuneitten parissa. Surmattujen keskelle on hänet pantu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Siellä on Mesek-Tuubal kaikkine meluisine joukkoineen. Niitten haudat ovat hänen ympärillänsä; ne ovat kaikki tyynni ympärileikkaamattomia, miekalla surmattuja, sillä ne levittivät kauhuansa elävien maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'He eivät makaa sankarien parissa, jotka ovat kaatuneet ympärileikkaamattomien joukosta, jotka ovat astuneet alas tuonelaan sota-aseinensa, joitten pään alle on pantu heidän miekkansa ja joitten luiden yllä on heidän syntivelkansa, sillä sankarien kauhu oli elävien maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Sinutkin muserretaan ympärileikkaamattomien joukossa, ja sinä saat maata miekallasurmattujen parissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Siellä on Edom, sen kuninkaat ja kaikki sen ruhtinaat, jotka sankaruudessaan pantiin miekallasurmattujen pariin. He makaavat ympärileikkaamattomien ja hautaanvaipuneitten parissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Siellä ovat kaikki pohjoisen maan ruhtinaat ja kaikki siidonilaiset, jotka ovat astuneet surmattujen pariin kauhistavaisuudessaan, ovat tulleet häpeään sankaruudessaan ja makaavat ympärileikkaamattomina miekallasurmattujen parissa ja saavat kantaa häpeänsä hautaanvaipuneitten parissa. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Ne on farao näkevä ja tuleva lohdutetuksi kaikesta meluisasta joukostansa. Miekalla on surmattu farao kaikkine sotaväkineen, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Sillä minä levitin hänen kauhuansa elävien maassa, mutta faraolle ynnä kaikelle hänen meluisalle joukolleen laitetaan makuusija ympärileikkaamattomien sekaan, miekallasurmattujen pariin, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, '\"Ihmislapsi, puhu kansasi lapsille ja sano heille: Jos minä annan miekan tulla maan kimppuun ja maan kansa on ottanut yhden miehen joukostansa ja asettanut hänet vartijakseen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'ja jos hän näkee miekan tulevan maan kimppuun ja puhaltaa pasunaan ja varoittaa kansaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'ja joku kuulee pasunan äänen, mutta ei ota varoituksesta vaaria, ja miekka tulee ja ottaa hänet pois, niin hänen verensä tulee hänen oman päänsä päälle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'hän kuuli pasunan äänen, mutta ei ottanut varoituksesta vaaria; hänen verensä tulee hänen päällensä. Jos olisi ottanut varoituksesta vaarin, olisi hän pelastanut sielunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Jos taas vartija näkee miekan tulevan, mutta ei puhalla pasunaan eikä kansa saa varoitusta, ja miekka tulee ja ottaa pois jonkun sielun heistä, on hän otettu pois synnissänsä, mutta hänen verensä minä vaadin vartijan kädestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Ja sinä, ihmislapsi! Minä olen asettanut sinut Israelin heimolle vartijaksi. Kun kuulet sanan minun suustani, on sinun varoitettava heitä minun puolestani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Jos minä sanon jumalattomalle: jumalaton, sinun on kuolemalla kuoltava, mutta sinä et puhu varoittaaksesi jumalatonta hänen tiestänsä, niin se jumalaton kuolee synnissänsä, mutta hänen verensä minä vaadin sinun kädestäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Mutta jos sinä varoitat jumalatonta hänen tiestänsä, että hän kääntyisi siltä pois, eikä hän tieltänsä käänny, niin hän kuolee synnissänsä, mutta sinä olet sielusi pelastanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Ja sinä, ihmislapsi! Sano Israelin heimolle: Näin te sanotte: \'Niin, rikoksemme ja syntimme ovat meidän päällämme, ja me riudumme niiden tähden. Kuinka me voisimme pysyä elossa?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Sano heille: Niin totta kuin minä elän, sanoo Herra, Herra, ei ole minulle mieleen jumalattoman kuolema, vaan se, että jumalaton kääntyy tieltänsä ja elää. Kääntykää, kääntykää pois pahoilta teiltänne; ja minkätähden te kuolisitte, Israelin heimo!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Ja sinä, ihmislapsi! Sano kansasi lapsille: Vanhurskasta ei pelasta hänen vanhurskautensa sinä päivänä, jona hän rikkoo, ja jumalaton pääsee suistumasta turmioon jumalattomuutensa tähden sinä päivänä, jona hän kääntyy pois jumalattomuudestaan, ja vanhurskas ei voi elää vanhurskautensa turvin sinä päivänä, jona hän syntiä tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Jos minä sanon vanhurskaalle, että hän totisesti saa elää, mutta hän sitten luottaa vanhurskauteensa ja tekee vääryyttä, niin hänen vanhurskauttansa ei ensinkään muisteta, vaan hän kuolee vääryydessään, jota on tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Ja jos minä sanon jumalattomalle, että hänen totisesti on kuoltava, mutta hän kääntyy pois synnistänsä ja tekee oikeuden ja vanhurskauden');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, '-antaa takaisin, tuo jumalaton, pantin, korvaa riistämänsä ja vaeltaa elämän käskyjen mukaan, niin ettei vääryyttä tee-niin totisesti hän saa elää; ei hänen ole kuoltava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Hänen syntejänsä, jotka hän on tehnyt, ei ensinkään muisteta: hän on tehnyt oikeuden ja vanhurskauden, hän totisesti saa elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Ja vielä sinun kansasi lapset sanovat: \'Herran tie ei ole oikea\'. Juuri heidän omat tiensä eivät ole oikeat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Jos vanhurskas kääntyy pois vanhurskaudestansa ja vääryyttä tekee, on hänen sentähden kuoltava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Ja jos jumalaton kääntyy pois jumalattomuudestansa ja tekee oikeuden ja vanhurskauden, saa hän sentähden elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Ja vielä te sanotte: \'Herran tie ei ole oikea\': minä tuomitsen teidät, te Israelin heimo, itsekunkin hänen teittensä mukaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Kahdentenatoista meidän pakkosiirtolaisuutemme vuotena, kymmenennessä kuussa, kuukauden viidentenä päivänä tuli minun luokseni pakolainen Jerusalemista ja sanoi: \"Kaupunki on valloitettu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Herran käsi oli tullut minun päälleni jo illalla, ennen pakolaisen tuloa, ja hän avasi minun suuni ennen tämän tuloa aamulla. Niin avautui minun suuni, enkä minä enää ollut mykkänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, '\"Ihmislapsi, ne, jotka asuvat noilla raunioilla Israelin maassa, sanovat näin: \'Aabraham oli vain yksi, ja hän peri maan; meitä on paljon, meille on maa perinnöksi annettu\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Sano sentähden heille: Näin sanoo Herra, Herra: Te syötte lihaa verinensä, luotte silmänne kivijumaliinne ja vuodatatte verta; ja tekö perisitte maan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Te seisotte miekkanne varassa, harjoitatte kauhistuksia ja saastutatte toistenne vaimoja; ja tekö perisitte maan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Näin on sinun heille sanottava: Näin sanoo Herra, Herra: Niin totta kuin minä elän, niin ne, jotka ovat raunioilla, kaatuvat miekkaan, ja ne, jotka ovat kedolla, minä annan petoeläimille syötäväksi, ja ne, jotka ovat vuorenhuipuilla ja luolissa, kuolevat ruttoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Ja minä teen maan autioksi ja hävitetyksi, ja heidän ylpeästä uhmastaan tulee loppu, ja Israelin vuoret joutuvat autioiksi, niin ettei siellä kenkään kulje.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Ja he tulevat tietämään, että minä olen Herra, kun minä teen maan autioksi ja hävitetyksi kaikkien kauhistusten tähden, joita he ovat harjoittaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Ja sinä, ihmislapsi! Sinun kansasi lapset puhuvat sinusta seinänvierustoilla ja talojen ovilla ja sanovat keskenään, toinen toisellensa, näin: \'Lähtekää kuulemaan, millainen sana nyt on tullut Herralta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'He tulevat sinun luoksesi joukoittain, istuvat edessäsi minun kansanani ja kuuntelevat sinun sanojasi, mutta he eivät tee niitten mukaan, sillä he osoittavat rakkautta suullansa, mutta heidän sydämensä kulkee väärän voiton perässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Ja katso, sinä olet heille kuin rakkauslaulu, kauniisti laulettu ja hyvin soitettu: he sanojasi kyllä kuuntelevat, mutta eivät tee niitten mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Mutta kun se toteutuu-ja katso, se toteutuu-silloin he tulevat tietämään, että heidän keskuudessansa on ollut profeetta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, '\"Ihmislapsi, ennusta Israelin paimenia vastaan, ennusta ja sano heille-paimenille: Näin sanoo Herra, Herra: Voi Israelin paimenia, jotka ovat itseänsä kainneet! Eikö paimenten ole kaittava lampaita?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Te olette syöneet rasvat, pukeneet päällenne villat, teurastaneet lihavat; mutta ette ole kainneet laumaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'ette ole vahvistaneet heikkoja, ette ole parantaneet sairaita, sitoneet haavoittuneita, tuoneet takaisin eksyneitä, etsineet kadonneita, vaan te olette vallinneet niitä tylysti ja väkivaltaisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Ja niin ne ovat hajaantuneet paimenta vailla ja joutuneet kaikkien metsän petojen syötäviksi-hajaantuneet ne ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Minun lampaani harhailevat kaikilla vuorilla ja kaikilla korkeilla kukkuloilla; pitkin koko maata ovat minun lampaani hajallaan, eikä kenkään niistä välitä eikä niitä etsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Sentähden, paimenet, kuulkaa Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Niin totta kuin minä elän, sanoo Herra, Herra, totisesti, koska minun lampaani ovat ryöstettävinä ja koska minun lampaani ovat kaikkien metsän petojen syötävinä, kun paimenta ei ole ja kun minun paimeneni eivät välitä minun lampaistani, vaan minun paimeneni kaitsevat itseänsä, eivätkä kaitse minun lampaitani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'sentähden, paimenet, kuulkaa Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Näin sanoo Herra, Herra: Katso, minä käyn paimenten kimppuun, vaadin lampaani heidän kädestänsä ja teen lopun heidän lammasten-kaitsennastaan, eivätkä paimenet saa enää kaita itseänsä. Minä pelastan lampaani heidän kidastansa, eivätkä ne sitten enää ole heidän syötävinänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Sillä näin sanoo Herra, Herra: Katso, minä itse etsin lampaani ja pidän niistä huolen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Niinkuin paimen pitää huolen laumastaan, kun hän on lampaittensa keskellä ja ne ovat hajallaan, niin minä pidän huolen lampaistani, ja minä pelastan ne joka paikasta, minne ne ovat hajaantuneet pilvisenä ja pimeänä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Minä vien ne pois kansojen seasta ja kokoan ne muista maista, tuon ne omaan maahansa ja kaitsen niitä Israelin vuorilla, puronotkoissa ja kaikissa maan asuttavissa paikoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Hyvillä ruokamailla minä niitä kaitsen, ja Israelin korkeilla vuorilla on niillä oleva laitumensa. Siellä ne saavat levätä hyvällä laitumella, ja lihava ruokamaa niillä on oleva Israelin vuorilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Minä itse kaitsen lampaani ja vien itse ne lepäämään, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Kadonneet minä tahdon etsiä, eksyneet tuoda takaisin, haavoittuneet sitoa, heikkoja vahvistaa; mutta lihavat ja väkevät minä hävitän. Minä kaitsen niitä niin, kuin oikein on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Mutta te, minun lampaani! Näin sanoo Herra, Herra: Katso, minä tahdon tuomita lampaan ja lampaan, oinasten ja vuohipukkien välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Eikö teille riitä, että olette hyvällä laitumella, kun vielä tallaatte jaloillanne loput laitumestanne, ja että saatte juoda kirkasta vettä, kun vielä hämmennätte jaloillanne loput?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Ja onko minun lampaitteni oltava laitumella siinä, mitä jalkanne ovat tallanneet, ja juotava sitä, mitä jalkanne ovat hämmentäneet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Sentähden sanoo Herra, Herra niille näin: Katso, minä, minä tuomitsen lihavan lampaan ja laihan lampaan välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Koska te olette kylki-ja niskavoimalla sysineet ja sarvillanne puskeneet kaikkia heikkoja, kunnes olette saaneet ne ajetuiksi ulos ja hajallensa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'niin minä tahdon vapauttaa lampaani, etteivät ne enää jää ryöstettäviksi; ja minä tahdon tuomita lampaan ja lampaan välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Ja minä herätän heille yhden paimenen heitä kaitsemaan, palvelijani Daavidin; hän on kaitseva heitä ja oleva heidän paimenensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Ja minä, Herra, olen heidän Jumalansa, ja minun palvelijani Daavid on ruhtinas heidän keskellänsä. Minä, Herra, olen puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Ja minä teen heidän kanssansa rauhan liiton; minä lopetan maasta pahat eläimet, niin että he asuvat turvallisesti erämaassa ja nukkuvat metsiköissä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'ja minä teen siunatuiksi heidät ja kaiken, mitä minun kukkulani ympärillä on, ja vuodatan sateen ajallansa-ne ovat siunauksen sateita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Ja kedon puut kantavat hedelmänsä, ja maa antaa satonsa, ja he saavat olla turvassa maassansa. Ja he tulevat tietämään, että minä olen Herra, kun minä särjen heidän ikeensä puut ja pelastan heidät heidän orjuuttajainsa käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Eivätkä he enää ole pakanain ryöstettävinä, eivätkä metsän pedot heitä syö, vaan he asuvat turvassa, kenenkään peloittelematta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Ja minä annan nousta heille istutuksen, joka on oleva kunniaksi, niin ettei heidän tarvitse siinä maassa menehtyä nälkään eikä enää kärsiä pakanain pilkkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Ja he tulevat tietämään, että minä, Herra, heidän Jumalansa, olen heidän kanssansa ja että he, Israelin heimo, ovat minun kansani, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Niin, te olette minun lampaani, minun laitumeni lampaat, te ihmiset; minä olen teidän Jumalanne, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, '\"Ihmislapsi, käännä kasvosi Seirin vuorta kohti ja ennusta sitä vastaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'ja sano sille: Näin sanoo Herra, Herra: Katso, minä käyn sinun kimppuusi, Seirin vuori, ojennan käteni sinua vastaan ja teen sinut autioksi ja hävitetyksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Sinun kaupunkisi minä teen raunioiksi ja sinä itse tulet autioksi. Ja sinä tulet tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Koska sinä pidit ikuista vihaa ja annoit israelilaiset alttiiksi miekalle heidän onnettomuutensa aikana, aikana, jolloin syntivelka tuli loppumääräänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'sentähden, niin totta kuin minä elän, sanoo Herra, Herra, minä teen sinut verivirraksi, ja veri on sinua vainoava: totisesti, vereen saakka sinä olet vihannut, ja veri on sinua vainoava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Minä teen Seirin vuoren tyhjäksi ja autioksi ja hävitän sieltä menijän ja tulijan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Sen vuoret minä täytän sen surmatuilla. Miekalla surmattuja kaatuu sinun kukkuloillasi ja laaksoissasi ja kaikissa puronotkoissasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Minä teen sinut ikiautioksi, ja sinun kaupunkisi jäävät asumattomiksi. Ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Koska sinä olet sanonut: \'Ne kaksi kansaa ja kaksi maata ovat minun, me otamme ne omiksemme\', vaikka siellä on Herra,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'sentähden, niin totta kuin minä elän, sanoo Herra, Herra, minä teen sinun kiukkusi ja kiivautesi mukaan, teen sen, minkä sinä vihassasi olet heille tehnyt. Ja minä teen itseni heille tunnetuksi, kun niin tuomitsen sinut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'ja sinä tulet tietämään, että minä olen Herra. Minä olen kuullut kaikki sinun pilkkasi, jotka olet puhunut Israelin vuoria vastaan, kun olet sanonut: \'Ne ovat autioina, ne ovat annetut meidän syötäviksemme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Te suurentelitte minua vastaan suullanne, ja ylenpalttiset olivat teidän puheenne minua vastaan: minä olen ne kuullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Näin sanoo Herra, Herra: Iloksi kaikelle maalle minä teen sinut autioksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Niinkuin sinä iloitsit Israelin heimon perintöosasta, kun se tuli autioksi, niin teen minäkin sinulle: autioksi tulet sinä, Seirin vuori, samoin koko Edom kaikkinensa. Ja niin he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, '\"Ja sinä, ihmislapsi, ennusta Israelin vuorista ja sano:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Israelin vuoret, kuulkaa Herran sana: Näin sanoo Herra, Herra: Koska vihollinen on sanonut teistä: \'Kas niin!\' ja: \'Ikuiset kukkulat ovat tulleet meille perinnöksi\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'sentähden ennusta ja sano: Näin sanoo Herra, Herra: Koska-niin, koska teitä on hävitetty ja poljettu joka taholta, että joutuisitte muiden kansain omaisuudeksi, ja koska te olette joutuneet pahain kielten ja kansan panettelun alaisiksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'sentähden, Israelin vuoret, kuulkaa Herran, Herran sana: Näin sanoo Herra, Herra vuorille ja kukkuloille, puronotkoille ja laaksoille, autioille raunioille ja hyljätyille kaupungeille, jotka ovat joutuneet saaliiksi ja pilkaksi muille kansoille, mitä ympärillä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Sentähden sanoo Herra, Herra näin: Totisesti, kiivauteni tulessa minä puhun muita kansoja vastaan ja koko Edomia vastaan, jotka ovat kaikesta sydämestään iloiten ja sielu täynnä ylenkatsetta ottaneet omakseen minun maani karkoittaaksensa siitä ihmiset ja ryöstääksensä sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Sentähden ennusta Israelin maasta ja sano vuorille ja kukkuloille, puronotkoille ja laaksoille: Näin sanoo Herra, Herra: Katso, kiivaudessani ja vihassani minä puhun, koska teidän täytyy kärsiä pakanakansain pilkkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Sentähden, näin sanoo Herra, Herra: Minä kohotan käteni: totisesti saavat pakanakansat, jotka teidän ympärillänne ovat, itse kärsiä oman pilkkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Mutta te, Israelin vuoret, teette lehvänne ja kannatte hedelmänne minun kansalleni Israelille, sillä he ovat aivan lähellä, ovat tulossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Sillä katso, minä tulen teidän tykönne ja käännyn teidän puoleenne, ja teidät viljellään ja teihin kylvetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Ja minä lisään teille ihmisiä runsaasti-kaiken Israelin heimon kokonansa-ja kaupungit asutetaan ja rauniot rakennetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Ja minä lisään teille ihmisiä ja karjaa runsaasti, ja ne lisääntyvät ja ovat hedelmälliset. Minä teen teidät asutuiksi, niinkuin olitte muinaisina päivinänne, ja teen hyvää vielä enemmän kuin alkuaikoinanne. Ja te tulette tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Minä annan teidän kukkuloillanne kulkea ihmisten, kansani Israelin; ja he ottavat sinut omaksensa, ja sinä tulet heille perintöosaksi, ja sinä et enää tästälähin riistä heidän lapsiansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Näin sanoo Herra, Herra: Koska teille on sanottu: \'Sinä olet ihmissyöjätär, oman kansasi lasten riistäjätär\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'sentähden et sinä ole enää syövä ihmisiä etkä enää riistävä lapsia omalta kansaltasi, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Enkä minä enää anna sinun joutua kuulemaan pakanakansojen pilkkaa, eikä tarvitse sinun enää kärsiä kansojen herjauksia, et myöskään sinä enää omaa kansaasi kaada, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, '\"Ihmislapsi, kun Israelin heimo asui maassansa, he saastuttivat sen vaelluksellaan ja teoillaan. Niinkuin kuukautistilan saastaisuus oli minun edessäni heidän vaelluksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Niin minä vuodatin kiivauteni heidän ylitsensä veren tähden, jota he olivat vuodattaneet maassa, ja heidän kivijumalainsa tähden, joilla he olivat sen saastuttaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Ja minä hajotin heidät pakanakansojen sekaan, ja heidät siroteltiin muihin maihin. Vaelluksensa ja tekojensa mukaan minä heidät tuomitsin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Niin he tulivat pakanakansain sekaan; minne tulivatkin, he häpäisivät minun pyhän nimeni, kun heistä sanottiin: \'Nämä ovat Herran kansa, mutta heidän on täytynyt lähteä pois hänen maastansa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Niin minun tuli sääli pyhää nimeäni, jonka Israelin heimo saastutti pakanakansain seassa, minne tulivatkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Sentähden sano Israelin heimolle: Näin sanoo Herra, Herra: En tee minä teidän tähtenne, Israelin heimo, sitä minkä teen, vaan oman pyhän nimeni tähden, jonka te olette häväisseet pakanakansain seassa, minne tulittekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Minä pyhitän suuren nimeni, joka on häväisty pakanakansain seassa, jonka te olette häväisseet heidän keskellänsä. Ja pakanakansat tulevat tietämään, että minä olen Herra, sanoo Herra, Herra, kun minä osoitan teissä pyhyyteni heidän silmäinsä edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Minä otan teidät pois pakanakansoista ja kokoan teidät kaikista maista ja tuon teidät omaan maahanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Ja minä vihmon teidän päällenne puhdasta vettä, niin että te puhdistutte; kaikista saastaisuuksistanne ja kaikista kivijumalistanne minä teidät puhdistan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Ja minä annan teille uuden sydämen, ja uuden hengen minä annan teidän sisimpäänne. Minä poistan teidän ruumiistanne kivisydämen ja annan teille lihasydämen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Henkeni minä annan teidän sisimpäänne ja vaikutan sen, että te vaellatte minun käskyjeni mukaan, noudatatte minun oikeuksiani ja pidätte ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Niin te saatte asua maassa, jonka minä annoin teidän isillenne; ja te olette minun kansani, ja minä olen teidän Jumalanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Minä vapahdan teidät kaikista saastaisuuksistanne. Ja minä kutsun esiin viljan ja teen sen runsaaksi enkä anna teille nälänhätää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Minä teen runsaaksi puitten hedelmän ja pellon sadon, niin ettette enää joudu kärsimään kansojen seassa herjausta nälän takia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Niin te muistatte huonon vaelluksenne ja tekonne, jotka eivät olleet hyvät, ja teitä kyllästyttää oma itsenne rikostenne ja kauhistustenne tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'En minä teidän tähtenne sitä tee, sanoo Herra, Herra: se olkoon teille tiettävä. Hävetkää ja tuntekaa häpeätä vaelluksenne tähden, te Israelin heimo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Näin sanoo Herra, Herra: Sinä päivänä, jona minä teidät puhdistan kaikista pahoista teoistanne, minä asutan kaupungit, ja rauniot rakennetaan jälleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'ja autiomaa viljellään, sen sijaan että se on ollut autiona jokaisen ohitsekulkijan silmäin edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'Silloin sanotaan: \'Tästä maasta, joka oli autiona, on tullut kuin Eedenin puutarha; ja raunioina olleet, autiot ja maahan revityt kaupungit ovat varustettuja ja asuttuja\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Niin tulevat pakanakansat, joita on jäljellä teidän ympärillänne, tietämään, että minä, Herra, rakennan jälleen alasrevityn ja istutan aution: minä, Herra, olen puhunut, ja minä teen sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Näin sanoo Herra, Herra: Vielä tätäkin annan Israelin heimon minulta anoa, että tekisin heille sen: minä lisään heille ihmisiä runsaasti kuin lammaslaumaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Niinkuin on pyhitettyjen uhrilammasten laumaa, niinkuin Jerusalemin lammaslaumaa sen juhlissa, niin tulevat raunioina olleet kaupungit täyteen ihmislaumaa. Ja niin he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Herran käsi tuli minun päälleni ja vei minut pois Herran hengessä ja laski minut keskelle laaksoa. Ja se oli täynnä luita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Ja hän kuljetti minua ympäri niitten ohitse; ja katso, niitä oli hyvin paljon laakson kamaralla, ja katso, ne olivat hyvin kuivia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Niin hän sanoi minulle: \"Ihmislapsi, voivatkohan nämä luut tulla eläviksi?\" Mutta minä sanoin: \"Herra, Herra, sinä sen tiedät\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Niin hän sanoi minulle: \"Ennusta näistä luista ja sano niille: Kuivat luut, kuulkaa Herran sana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Näin sanoo Herra, Herra näille luille: Katso, minä annan tulla teihin hengen, ja te tulette eläviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Minä panen teihin jänteet, kasvatan teihin lihan, vedän yllenne nahan ja annan teihin hengen, ja te tulette eläviksi. Ja te tulette tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Minä ennustin, niinkuin minua oli käsketty. Ja kävi humahdus, kun minä ennustin; ja katso, kuului kolina, ja luut lähenivät toisiaan, luu luutansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Minä näin, ja katso: niihin tulivat jänteet ja kasvoi liha, ja päälle vetäytyi niihin nahka; mutta henkeä niissä ei ollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Niin hän sanoi minulle: \"Ennusta hengestä, ennusta, ihmislapsi, ja sano hengelle: Näin sanoo Herra, Herra: Tule, henki, neljästä tuulesta ja puhalla näihin surmattuihin, että ne tulisivat eläviksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Minä ennustin, niinkuin hän oli minua käskenyt, ja niihin tuli henki, ja ne tulivat eläviksi ja nousivat ylös jaloillensa: ylenmäärin suuri joukko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Ja hän sanoi minulle: \"Ihmislapsi, nämä luut ovat koko Israelin heimo. Katso, he sanovat: \'Meidän luumme ovat kuivettuneet, toivomme on mennyttä, me olemme hukassa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Sentähden ennusta ja sano heille: Näin sanoo Herra, Herra: Katso, minä avaan teidän hautanne ja nostan teidät, minun kansani, ylös haudoistanne ja vien teidät Israelin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Ja siitä te tulette tietämään, että minä olen Herra, kun minä avaan teidän hautanne ja nostan teidät, minun kansani, ylös haudoistanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Ja minä annan teihin henkeni, niin että te tulette eläviksi, ja sijoitan teidät omaan maahanne. Ja te tulette tietämään, että minä olen Herra: minä olen puhunut, ja minä sen teen, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, '\"Sinä, ihmislapsi, ota puusauva ja kirjoita siihen: \'Juudalle ja häneen liittyneille israelilaisille\'. Ota sitten toinen puusauva ja kirjoita siihen: \'Joosefille; Efraimin ja kaiken häneen liittyneen Israelin heimon sauva\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Ja pane ne lähekkäin, pääksytysten, niin että ne tulevat yhdeksi sinun kädessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Kun sitten kansasi lapset sanovat sinulle näin: \'Etkö selitä meille, mitä sinä tällä tarkoitat?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'niin puhu heille: Näin sanoo Herra, Herra: Katso, minä otan Joosefin sauvan, joka on Efraimin kädessä, ja häneen liittyneet Israelin sukukunnat, ja minä asetan ne yhteen Juudan sauvan kanssa ja teen niistä yhden sauvan, niin että ne tulevat yhdeksi minun kädessäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Ja kun sauvat, joihin olet kirjoittanut, ovat sinun kädessäsi, heidän silmäinsä edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'niin puhu heille: Näin sanoo Herra, Herra: Katso, minä otan israelilaiset pois pakanakansojen keskuudesta, minne vain he ovat kulkeutuneet, kokoan heidät joka taholta ja tuon heidät omaan maahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Minä teen heidät yhdeksi kansaksi siinä maassa, Israelin vuorilla, ja yksi kuningas on oleva kuninkaana heillä kaikilla. Eivätkä he enää ole kahtena kansana eivätkä enää jakaantuneina kahdeksi valtakunnaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Eivät myöskään he enää saastuta itseänsä kivijumalillaan, iljetyksillään eivätkä millään rikkomuksillansa, vaan minä vapautan heidät kaikista asuinpaikoistaan, joissa ovat syntiä tehneet, ja puhdistan heidät. Ja he ovat minun kansani, ja minä olen heidän Jumalansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Minun palvelijani Daavid on oleva heidän kuninkaansa, ja heillä kaikilla on oleva yksi paimen. Ja he vaeltavat minun oikeuksieni mukaan ja noudattavat minun käskyjäni ja pitävät ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'He saavat asua maassa, jonka minä annoin palvelijalleni Jaakobille ja jossa teidän isänne ovat asuneet. Siinä saavat asua he, heidän lapsensa ja lastensa lapset iankaikkisesti, ja minun palvelijani Daavid on oleva heidän ruhtinaansa iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Minä teen heidän kanssansa rauhan liiton-se on oleva iankaikkinen liitto heidän kanssansa-istutan ja runsaasti kartutan heidät ja asetan pyhäkköni olemaan heidän keskellänsä iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Minun asumukseni on oleva heidän yllänsä, ja minä olen heidän Jumalansa, ja he ovat minun kansani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Ja pakanakansat tulevat tietämään, että minä olen Herra, joka pyhitän Israelin, kun minun pyhäkköni on heidän keskellänsä iankaikkisesti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, '\"Ihmislapsi, käännä kasvosi kohti Googia Maagogin maassa, Roosin, Mesekin ja Tuubalin ruhtinasta, ja ennusta häntä vastaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'ja sano: Näin sanoo Herra, Herra: Katso, minä käyn sinun kimppuusi, Goog, sinä Roosin, Mesekin ja Tuubalin ruhtinas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Minä kuljetan sinua, panen koukut sinun leukoihisi ja nostatan sotaan sinut ja kaiken sinun sotaväkesi: hevoset ja ratsumiehet, kaikki pulskasti puettuja, suuren joukon suurine ja pienine kilpineen, miekankantajia kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Persia, Etiopia ja Puut ovat heidän kanssansa, kilvet ja kypärit on heillä kaikilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Goomer ja kaikki sen sotalaumat, Toogarman heimo pohjan periltä ja kaikki sen sotalaumat-lukuisat kansat ovat sinun kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Ole valmis, varustaudu, sinä ja kaikki joukkosi, jotka ovat kokoontuneet sinun luoksesi, ja ole sinä varalla heitä varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Pitkien aikojen perästä sinä saat määräyksen, vuotten lopulla sinun on karattava maahan, joka on tointunut miekan jäljiltä, koottu monien kansain seasta, -mentävä Israelin vuorille, jotka kauan aikaa olivat olleet rauniomaana; se on tuotu pois kansojen seasta, ja he asuvat turvallisina kaikki tyynni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Sinä hyökkäät kuin rajuilma, tulet kuin pilvi, pettääksesi maan, sinä ja kaikki sotalaumasi ja lukuisat kansat, jotka ovat sinun kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Näin sanoo Herra, Herra: Mutta sinä päivänä tulee mieleesi jotakin, ja sinä mietit pahan juonen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'ja sanot: Minä hyökkään suojattomaan maahan, karkaan rauhallisten ihmisten kimppuun, jotka asuvat turvallisina-asuvat muuria vailla kaikki tyynni, ja joilla ei ole salpoja, ei ovia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Sinä aiot saalista saada, ryöstettävää ryöstää, ojentaa kätesi raunioita kohti, jotka on saatu asutuiksi, ja kansaa kohti, joka on koottu pakanakansain seasta, joka on hankkinut karjaa ja omaisuutta ja asuu maan navassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Saba ja Dedan ja Tarsiin kauppiaat ja kaikki heidän nuoret jalopeuransa kyselevät sinulta: \'Oletko sinä menossa saalista saamaan, ryöstettävää ryöstämään? Oletko koonnut joukkosi kantamaan hopeata ja kultaa, ottamaan karjaa ja omaisuutta, suurta saalista saamaan?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Sentähden ennusta, ihmislapsi, ja sano Googille: Näin sanoo Herra, Herra: Sinä päivänä sinä kyllä huomaat, että minun kansani Israel asuu turvallisena,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'ja lähdet asuinpaikastasi pohjan periltä, sinä ja sinun kanssasi lukuisat kansat, jotka kaikki ratsastavat hevosilla: suuri joukko, lukuisa sotaväki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Sinä hyökkäät minun kansani Israelin kimppuun kuin pilvi, peittääksesi maan. Päivien lopulla on tämä tapahtuva. Ja minä annan sinun karata maahani, että pakanakansat tulisivat tuntemaan minut, kun minä osoitan pyhyyteni sinussa, Goog, heidän silmäinsä edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Näin sanoo Herra, Herra: Etkö se ole sinä, josta minä muinaisina päivinä puhuin palvelijaini, Israelin profeettain, kautta, jotka niinä päivinä ennustivat, vuodesta vuoteen, että minä annan sinun karata heidän kimppuunsa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Mutta sinä päivänä, jona Goog karkaa Israelin maahan, sanoo Herra, Herra, nousee minun vihani hehku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Kiivaudessani, tuimuuteni tulessa minä sanon: Totisesti tulee sinä päivänä suuri maanjäristys Israelin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Ja minun edessäni vapisevat meren kalat ja taivaan linnut ja metsän eläimet ja kaikki maassa liikkuvat matelijat ja kaikki ihmiset, jotka maan pinnalla ovat; ja vuoret luhistuvat, ja vuorenpengermät sortuvat, ja kaikki muurit sortuvat maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Ja minä kutsun häntä vastaan kaikille vuorilleni miekan, sanoo Herra, Herra: toisen miekka on oleva toista vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Minä käyn oikeutta hänen kanssansa rutolla ja verellä. Ja minä annan sataa kaatosadetta, raekiviä, tulta ja tulikiveä hänen päällensä, hänen sotalaumojensa päälle ja lukuisain kansojen päälle, jotka hänen kanssansa ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Niin minä osoitan suuruuteni ja pyhyyteni sekä teen itseni tunnetuksi lukuisain pakanakansain silmien edessä. Ja he tulevat tietämään, että minä olen Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, '\"Ja sinä, ihmislapsi, ennusta Googia vastaan ja sano: Näin sanoo Herra, Herra: Katso, minä tulen sinun tykösi, Goog, sinä Roosin, Mesekin ja Tuubalin ruhtinas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Minä kuljetan sinua, talutan sinua, nostatan sinut pohjan periltä ja annan sinun hyökätä Israelin vuorille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Mutta minä lyön pois jousesi sinun vasemmasta kädestäsi ja pudotan nuolesi sinun oikeasta kädestäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Israelin vuorille sinä olet kaatuva, samoin kaikki sinun sotalaumasi ja kansat, jotka sinun kanssasi ovat: minä annan sinut petolinnuille, kaikille siivekkäille ja metsän eläimille ruuaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Kentälle sinä kaadut. Sillä minä olen puhunut, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Ja minä lähetän tulen Maagogiin ja rantamaalla turvassa asuvien keskeen. Ja he tulevat tietämään, että minä olen Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Ja pyhän nimeni minä teen tunnetuksi kansani Israelin keskuudessa enkä enää salli häväistävän pyhää nimeäni. Ja pakanakansat tulevat tietämään, että minä olen Herra, Israelin Pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Katso, se tulee, se tapahtuu, sanoo Herra, Herra: Tämä on se päivä, josta minä olen puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Israelin kaupunkien asukkaat menevät ulos ja sytyttävät ja polttavat aseita, pieniä ja suuria kilpiä, jousia, nuolia, käsikarttuja ja keihäitä. He pitävät niitä polttoaineina seitsemän vuotta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'eivät he kanna puita kedolta eivätkä hakkaa metsistä, vaan pitävät polttoaineina aseita. Näin he saalistavat saalistajiaan ja ryöstävät ryöstäjiään, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Sinä päivänä minä annan Googille siellä, Israelissa, hautasijan, \'Kulkijain laakson\', itää kohden merestä; se sulkee tien noilta kulkijoilta. Sinne haudataan Goog ja koko hänen meluisa joukkonsa, ja sille pannaan nimeksi: \'Googin meluisan joukon laakso\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Niitä hautaa Israelin heimo seitsemän kuukautta puhdistaaksensa maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Koko maan kansa hautaa heitä, ja se on koituva heille kiitokseksi sinä päivänä, jona minä näytän kunniani, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Valitaan vakinaiset miehet, jotka kulkevat maata ja hautaavat noita kulkijoita, mitä niitä vielä on jäljellä maan pinnalla, puhdistaaksensa sen; seitsemän kuukauden kuluttua he sen tutkivat läpikotaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Kun nämä kulkijat kulkevat maata ja joku heistä näkee ihmisen luut, laittaa hän niitten ääreen kivimerkin, siihen asti että haudankaivajat saavat ne haudatuiksi \'Googin meluisan joukon laaksoon\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Onpa eräällä kaupungillakin nimenä Hamona. -Niin he puhdistavat maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Ja sinä, ihmislapsi! Näin sanoo Herra, Herra: Käske lintuja, kaikkia siivekkäitä, ja kaikkia metsän eläimiä: Kokoontukaa, tulkaa, yhtykää joka taholta minun teurasuhrilleni jonka minä teitä varten uhraan, suurelle teurasuhrille Israelin vuorille; syökää lihaa ja juokaa verta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Syökää sankarien lihaa ja juokaa maan ruhtinaitten verta-oinaita, lampaita, kauriita ja härkiä, kaikki tyynni Baasanissa syötettyjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Syökää itsenne kylläisiksi rasvasta ja juokaa itsenne juovuksiin verestä, teurasuhrista, jonka minä teitä varten uhraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Tulkaa kylläisiksi minun pöydässäni ratsuista ja vaunuhevosista, sankareista ja kaikenkaltaisista sotamiehistä, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Minä asetan kunniani pakanakansojen keskeen, ja kaikki pakanakansat saavat nähdä minun tuomioni, jonka minä toimitan, ja käteni, jonka minä lasken heidän päällensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Mutta Israelin heimo tulee tietämään, että minä, Herra, olen heidän Jumalansa siitä päivästä lähtien ja aina eteenpäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Ja pakanakansat tulevat tietämään, että Israelin heimo joutui pakkosiirtolaisuuteen syntivelkansa tähden, koska olivat olleet minulle uskottomat, ja minä kätkin heiltä kasvoni, ja niin minä annoin heidät heidän vihollistensa käsiin, ja he kaatuivat miekkaan kaikki tyynni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Minä tein heille heidän saastaisuutensa ja rikkomustensa mukaan ja kätkin heiltä kasvoni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Sentähden, näin sanoo Herra, Herra: Nyt minä käännän Jaakobin kohtalon ja armahdan kaikkea Israelin heimoa ja kiivailen pyhän nimeni puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Ja häpeänsä ja kaiken uskottomuutensa, jota he ovat minulle osoittaneet, he unhottavat, asuessaan nyt maassansa turvallisina, kenenkään peloittelematta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Kun minä tuon heidät takaisin kansojen seasta ja kokoan heidät heidän vihamiestensä maista, niin minä osoitan heissä pyhyyteni lukuisain pakanakansain silmien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Ja he tulevat tietämään, että minä, Herra, olen heidän Jumalansa, kun minä, vietyäni heidät pakkosiirtolaisuuteen pakanakansojen luokse, kokoan heidät omaan maahansa enkä jätä sinne jäljelle ainoatakaan heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Enkä minä enää kätke heiltä kasvojani, sillä minä vuodatan Henkeni Israelin heimon päälle, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Meidän pakkosiirtolaisuutemme kahdentenakymmenentenä viidentenä vuotena, vuoden alussa, kuukauden kymmenentenä päivänä, neljäntenätoista vuotena kaupungin valloituksen jälkeen, juuri sinä päivänä tuli minun päälleni Herran käsi, ja hän vei minut sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'Jumalan näyissä hän vei minut Israelin maahan ja laski minut hyvin korkealle vuorelle, jolla oli ikäänkuin kaupunki rakennettuna, etelään päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Hän vei minut sinne. Ja katso, oli mies, näöltänsä vasken kaltainen, ja pellavanuora oli hänellä kädessänsä sekä mittaruoko, ja hän seisoi portilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Ja mies puhui minulle: \"Ihmislapsi, katso silmilläsi, kuule korvillasi ja ota huomioosi kaikki, mitä minä sinulle näytän; sillä sinut on tuotu tänne sitä varten, että nämä sinulle näytettäisiin. Ilmoita kaikki, mitä näet, Israelin heimolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Ja katso, oli muuri temppelin ulkopuolella, yltympäri sen. Ja miehen kädessä oli mittaruoko, kuusikyynäräinen, kyynärään luettuna kyynärä ja kämmenenleveys. Ja hän mittasi muurirakennuksen leveyden: yksi ruoko, ja korkeuden: yksi ruoko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Sitten hän meni portille, jonka etupuoli oli itää kohden, nousi ylös sen portaita ja mittasi portin kynnyksen: se oli yhden ruovon levyinen-ensimmäinen kynnys: yhden ruovon levyinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Sivuhuone oli aina yhden ruovon pituinen ja yhden ruovon levyinen, ja sivuhuoneitten väliä oli viisi kyynärää. Portin kynnys porttieteisen laidassa, sisäpuolella: yksi ruoko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Ja hän mittasi porttieteisen, joka oli sisäpuolella: yksi ruoko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Ja hän mittasi porttieteisen: kahdeksan kyynärää, ja sen seinäpatsaat: kaksi kyynärää. Ja porttieteinen oli sisemmällä puolen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Itää kohden antavan portin sivuhuoneita oli kolme kummallakin puolella. Ne kolme olivat yhtä suuria, ja niiden seinäpatsaat kummallakin puolella olivat yhtä suuria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Ja hän mittasi portin oviaukon leveyden: kymmenen kyynärää, ja portin pituuden: kolmetoista kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Mutta sivuhuoneitten edessä oli aitaus: yksi kyynärä, samoin toisella puolella oleva aitaus: yksi kyynärä; ja kukin sivuhuone kummallakin puolella: kuusi kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Ja hän mittasi portin, yhden sivuhuoneen katosta toisen kattoon: leveys oli kaksikymmentä viisi kyynärää, ovet vastatusten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Sitten hän otti mitan seinäpatsaista: kaksikymmentä kyynärää. Seinäpatsaisiin liittyi esipiha portin ympärillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Ja sisäänkäyntiportin edestä sisäportin eteisen eteen oli viisikymmentä kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Portissa yltympäri oli sisäänpäin, sivuhuoneisiin ja niitten seinäpatsaisiin päin, avartuvia ikkuna-aukkoja; samoin eteisissä. Ikkuna-aukot ympärinsä laajenivat sisäänpäin. Ja seinäpatsaissa oli palmukoristeita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Sitten hän vei minut ulompaan esipihaan. Ja katso: ympäri esipihan oli kammioita ja kivillä laskettu permanto. Kivillä lasketun permannon laidassa oli kolmekymmentä kammiota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Kivillä laskettu permanto oli porttien sivuseinämillä, porttien pituuden mukaisesti; tämä oli alempi kivillä laskettu permanto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Ja hän mittasi leveyden alemman portin edestä sisemmän esipihan edustalle, ulkopuolelle: sata kyynärää sekä itä-että pohjoispuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Sitten hän mittasi sen portin pituuden ja leveyden, jonka etupuoli oli pohjoista kohden ja joka vei ulompaan esipihaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Siinä oli kolme sivuhuonetta kummallakin puolella, ja sen seinäpatsaat ja eteinen olivat yhtä suuret kuin ensimmäisessä portissa. Sen pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Ja sen ikkuna-aukot, eteinen ja palmukoristeet olivat yhtä suuret kuin portin, jonka etupuoli oli itää kohden, ja sinne noustiin seitsemää porrasta, ja niistä eteenpäin oli sen eteinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Sisemmällä esipihalla oli portti porttia vastassa pohjoista ja itää kohden. Ja hän mittasi portista porttiin: sata kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Sitten hän kuljetti minua etelää kohden, ja katso, tuli portti, joka antoi etelää kohden. Ja hän mittasi sen seinäpatsaat ja eteisen: ne olivat yhtä suuret kuin nuo toiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Ja siinä ja sen eteisessä oli ikkuna-aukkoja ympärinsä, samanlaisia kuin nuo toiset ikkuna-aukot. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Sen ylöskäytävässä oli seitsemän porrasta, ja niistä eteenpäin oli sen eteinen. Ja siinä oli palmukoristeet, yksi kummallakin puolella, sen seinäpatsaissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Sisemmässä esipihassa oli portti etelää kohden. Ja hän mittasi portista porttiin etelää kohden: sata kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Sitten hän vei minut sisempään esipihaan eteläportin kautta. Ja hän mittasi eteläportin: se oli yhtä suuri kuin nuo toiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Ja sen sivuhuoneet, seinäpatsaat ja eteinen olivat yhtä suuret kuin nuo toiset. Ja siinä ja sen eteisessä oli ikkuna-aukkoja ympärinsä. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Ja eteisiä oli ympärinsä; pituus kaksikymmentä viisi kyynärää, leveys viisi kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Sen eteinen oli ulompaan esipihaan päin, ja sen seinäpatsaissa oli palmukoristeita. Sen portaissa oli kahdeksan porrasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Sitten hän vei minut sisempään esipihaan itää kohden. Ja hän mittasi portin: se oli yhtä suuri kuin nuo toiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Ja sen sivuhuoneet, seinäpatsaat ja eteinen olivat yhtä suuret kuin nuo toiset. Ja siinä ja sen eteisessä oli ikkuna-aukkoja ympärinsä. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Sen eteinen oli ulompaan esipihaan päin, ja sen seinäpatsaissa oli palmukoristeita kummallakin puolella. Sen portaissa oli kahdeksan porrasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Sitten hän vei minut pohjoisportille ja mittasi: yhtä suuret kuin nuo toiset');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'olivat sen sivuhuoneet, seinäpatsaat ja eteinen. Ja ikkuna-aukkoja oli siinä ympärinsä. Pituus oli viisikymmentä kyynärää ja leveys kaksikymmentä viisi kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Sen eteinen oli ulompaan esipihaan päin, ja sen seinäpatsaissa oli palmukoristeita kummallakin puolella. Sen portaissa oli kahdeksan porrasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Ja oli kammio, jonka ovi oli seinäpatsaissa, porteissa. Siellä oli polttouhri huuhdottava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Ja porttieteisessä oli kaksi pöytää kummallakin puolella; niillä oli polttouhri, syntiuhri ja vikauhri teurastettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Ja ulkopuolisella sivuseinämällä, portin ovelle noustessa, pohjoispuolella, oli kaksi pöytää; samoin porttieteisen toisella sivuseinämällä kaksi pöytää:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'neljä pöytää portin sivuseinämillä kummallakin puolella, siis kahdeksan pöytää. Niillä oli teurastettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Ja ylöskäytävän ääressä oli neljä pöytää hakatuista kivistä. Ne olivat puolentoista kyynärän pituisia, puolentoista kyynärän levyisiä ja yhden kyynärän korkuisia. Niille oli laskettava ne aseet, joilla teurastettiin polttouhri ja teurasuhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Ja haarukkakoukkuja, kämmenenleveyttä pitkiä, oli kiinnitetty ympäri huonetta, mutta uhriliha pantiin pöydille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Sisemmän portin ulkopuolella oli kaksi kammiota sisemmässä esipihassa, toinen pohjoisen portin sivuseinämällä, etupuoli etelää kohden, ja toinen eteläisen portin sivuseinämällä, etupuoli pohjoista kohden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Ja hän puhui minulle: \"Tämä kammio, jonka etupuoli on etelää kohden, on pappeja varten, jotka hoitavat temppelitehtäviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Ja kammio, jonka etupuoli on pohjoista kohden, on pappeja varten, jotka hoitavat alttaritehtäviä. Ne ovat Saadokin jälkeläiset, ne leeviläisistä, jotka saavat lähestyä Herraa häntä palvellakseen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Ja hän mittasi esipihan: pituus oli sata kyynärää ja leveys sata kyynärää; se oli neliön muotoinen. Ja alttari oli temppelin edustalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Sitten hän vei minut temppelin eteiseen ja mittasi eteisen seinäpatsaan: viisi kyynärää kummallakin puolella, ja portin leveyden: kolme kyynärää kummallakin puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Eteisen pituus oli kaksikymmentä kyynärää ja leveys yksitoista kyynärää. Sinne noustiin kymmentä porrasta. Ja seinäpatsaitten ääressä oli pylväät, yksi kummallakin puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Sitten hän vei minut temppelisaliin ja mittasi seinäpatsaat; ne olivat kuutta kyynärää leveitä kummallakin puolella: ilmestysmajan leveys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Ja oviaukko oli kymmentä kyynärää leveä, ja oviaukon sivuseinät kummallakin puolella olivat viisikyynäräiset. Hän mittasi temppelisalin pituuden: neljäkymmentä kyynärää, ja leveyden: kaksikymmentä kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Sitten hän meni sisimpään ja mittasi oviaukon seinäpatsaan: kaksi kyynärää, oviaukon: kuusi kyynärää, ja oviaukon leveyden: seitsemän kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Ja hän mittasi sen pituuden: kaksikymmentä kyynärää, ja leveyden: kaksikymmentä kyynärää temppelisalin puolelta. Ja hän sanoi minulle: \"Tämä on kaikkeinpyhin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Sitten hän mittasi temppelin seinän: kuusi kyynärää, ja sivukammion leveyden: neljä kyynärää, yltympäri temppelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Ja sivukammioita oli: kolme sivukammiota päällekkäin, kolmeenkymmeneen kertaan; ja ne kulkivat ympärinsä sen temppeliseinän varassa, joka oli sivukammioihin päin, niin että pysyivät siinä kiinni, mutta ne eivät olleet kiinnitetyt temppelinseinän sisään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Ja sivukammiot olivat aina sitä leveämpiä kiertäessään, mitä ylempänä olivat, sillä temppelin ympäryskammiot ulottuivat ylemmäksi ja ylemmäksi ympäri temppelin, ollen siten ylhäällä leveämmät sisäänpäin. Ja alakerrasta noustiin yläkertaan keskikerroksen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Ja minä näin, että temppelillä oli koroke ympärinsä: sivukammioitten perustukset, koko ruovon korkuiset, kuusi kyynärää, reunustaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Sivukammioitten ulkoseinän paksuus oli viisi kyynärää; yhtä leveä oli avoin tila sivukammiorakennuksen ääressä, joka temppeliin kuului.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Välimatkaa pihakammiorakennuksiin oli kahtakymmentä kyynärää leveälti ympäri temppelin-yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Ja sivukammioista vei ovi avoimeen tilaan: yksi ovi pohjoista kohden ja toinen ovi etelää kohden. Ja avoimen tilan leveys oli viisi kyynärää yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Ja rakennus, joka oli eristetyn alueen laidassa lännen puoleisella sivulla, oli seitsemääkymmentä kyynärää leveä. Rakennuksen seinän paksuus oli viisi kyynärää, ympärinsä, ja sen pituus oli yhdeksänkymmentä kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Sitten hän mittasi temppelin: pituus oli sata kyynärää, sekä eristetyn alueen ja rakennuksen seininensä: pituus sata kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Temppelin etupuolen ja eristetyn alueen leveys itään päin oli sata kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Sitten hän mittasi sen rakennuksen pituuden, joka oli eristetyn alueen laidassa, sen takana, ynnä sen käytävät, kummallakin puolella: sata kyynärää; ja sisemmän temppelisalin, esipihan eteiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'kynnykset, sisäänpäin avartuvat ikkuna-aukot, käytävät niitten kolmen ympärillä-kynnyksen edessä oli puulaudoitus yltympäri-ja välin maasta ikkuna-aukkoihin. Ja ikkuna-aukot olivat peitetyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Oviaukkojen yläpuolelta lähtien sekä sisempään temppeliin asti että ulos asti, koko seinällä yltympäri, sisä-ja ulkopuolella, oli mitatut alat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'ja niihin oli tehty kerubeja ja palmuja, palmu aina kahden kerubin väliin. Ja kullakin kerubilla oli kahdet kasvot:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'ihmisen kasvot palmuun päin toisaalle ja leijonan kasvot palmuun päin toisaalle. Niin oli tehty koko temppelissä yltympäri:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'maasta alkaen ja aina oviaukkojen yläpuolelle oli tehty kerubeja ja palmuja, samoin temppelisalin seinälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Temppelisalissa oli nelikulmaiset ovenpielet. Mutta pyhimmän edessä näkyi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'ikäänkuin alttari, puinen, kolmea kyynärää korkea, ja sen pituus oli kaksi kyynärää. Siinä oli nurkkaukset, ja sen jalusta ja seinät olivat puuta. Ja hän sanoi minulle: \"Tämä on pöytä, joka on Herran edessä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Sekä temppelisalissa että pyhimmässä oli kaksoisovet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Ja ovissa oli kaksi ovipuoliskoa, kaksi kääntyvää ovipuoliskoa: kumpaisessakin ovessa oli kaksi ovipuoliskoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Ja niihin, temppelisalin oviin, oli tehty kerubeja ja palmuja, samoin kuin oli tehty seiniin. Ulkona, eteisen edessä, oli puinen porraskatos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Ja eteisen sivuseinissä, kummallakin puolella, oli sisäänpäin avartuvia ikkuna-aukkoja ja palmuja; samoin temppelin sivukammioissa ja porraskatoksissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Sitten hän vei minut ulompaan esipihaan pohjoista kohden viepää tietä myöten, vei minut pihakammio-rakennuksen luo, joka oli eristettyä aluetta vastassa ja pohjoispuolista muurirakennusta vastassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'satakyynäräisen pitkänsivun edustalle, jossa oli oviaukko pohjoiseen päin; leveys taas oli viisikymmentä kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Sen kaksikymmenkyynäräisen paikan edustalla, joka kuului sisempään esipihaan, ja vastapäätä sitä kivillä laskettua permantoa, joka oli ulommassa esipihassa, oli käytävä käytävää vastassa, kolmessa kerroksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Kammioiden editse meni kulkutie, kymmentä kyynärää leveä, sisempään esipihaan, sataa kyynärää pitkä, ja oviaukot olivat pohjoiseen päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Mutta ylimmät kammiot olivat kapeimmat, sillä käytävät ottivat niiltä tilaa enemmän kuin alimmilta ja keskimmäisiltä kammioilta rakennuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Sillä nämä olivat kolmikertaiset, mutta niissä ei ollut pylväitä, niinkuin esipihoissa oli pylväät; sentähden ne tulivat olemaan kaitaisemmat kuin alimmat ja keskimmäiset, maasta lukien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Oli myös muuri, joka ulkopuolella kulki yhtä suuntaa kammioiden kanssa ulompaa esipihaa kohden kammioiden editse; sen pituus oli viisikymmentä kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Sillä niiden kammioiden pituus, jotka olivat ulompaan esipihaan päin, oli yhteensä viisikymmentä kyynärää; mutta, katso, temppelisalin puolella sata kyynärää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Ja näiden kammioiden alapuolella oli sisäänkäynti idästäpäin, kun tultiin niitten luokse ulommasta esipihasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'esipihaa ympäröivän muurin leveyspuolella. Etelää kohden, eristetyn alan edustalla ja rakennuksen edustalla, oli kammioita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'ja niiden editse kävi tie. Ne olivat samanmuotoisia kuin ne kammiot, jotka olivat pohjoista kohden: yhtä pitkiä ja leveitä. Samanlaisia olivat kaikki näitten uloskäytävät, laitteet ja oviaukot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Ja samoin kuin olivat niiden kammioiden oviaukot, jotka olivat etelää kohden, oli se oviaukko, joka oli tien päässä-tien, joka kulki senpuolisen muurin viertä itää kohden, sinne tultaessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Ja hän sanoi minulle: \"Pohjoiskammiot ja eteläkammiot, jotka ovat eristetyn alan edustalla, ne ovat pyhiä kammioita, joissa papit, jotka lähestyvät Herraa, syövät sitä, mikä on korkeasti-pyhää. Sinne he pankoot korkeasti-pyhän: ruokauhrin, syntiuhrin ja vikauhrin; sillä se paikka on pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Kun papit ovat tulleet, älkööt he menkö pyhäköstä ulos esipihaan muutoin, kuin että tänne panevat vaatteensa, joissa toimittavat virkaansa, sillä ne ovat pyhät, ja pukeutuvat toisiin vaatteisiin; sitten lähestykööt paikkaa, mikä on kansaa varten.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Kun hän oli saanut loppuun sisemmän temppelin mittaamisen, vei hän minut ulos sille portille, jonka etupuoli oli itää kohden. Ja hän mittasi sen ympärinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Hän mittasi itäilmalta mittaruovolla: viisi sataa ruokoa mittaruovon mukaan. Hän kääntyi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'ja mittasi pohjoisilmalta: viisisataa ruokoa mittaruovon mukaan. Hän kääntyi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'ja mittasi eteläilmalta: viisisataa ruokoa mittaruovon mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Hän kääntyi ja mittasi länsi-ilmalta: viisisataa ruokoa mittaruovon mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Neljältä ilmansuunnalta hän sen mittasi. Siinä oli muuri yltympäri; pituutta viisisataa ja leveyttä viisisataa. Sen tuli erottaa pyhä epäpyhästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Sitten hän kuljetti minut portille-sille portille, joka antoi itää kohden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Ja katso: Israelin Jumalan kunnia tuli idästä päin. Sen kohina oli niinkuin paljojen vetten kohina, ja maa kirkastui hänen kunniastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Ja näky, jonka minä näin, oli samanlainen kuin se näky, jonka olin nähnyt tullessani hävittämään kaupunkia; samanlaiset olivat näyt kuin se näky, jonka olin nähnyt Kebar-joen varrella. Niin minä lankesin kasvoilleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Ja Herran kunnia kulki temppeliin sen portin kautta, jonka etupuoli oli itää kohden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Ja henki nosti minut ja vei minut sisempään esipihaan. Ja katso: Herran kunnia täytti temppelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Ja minä kuulin jonkun puhuttelevan minua temppelistä; mutta mies seisoi minun vieressäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Se ääni sanoi minulle: \"Ihmislapsi, tämä on minun valtaistuimeni sija ja minun jalkapohjaini sija, jossa minä tahdon asua israelilaisten keskellä iankaikkisesti. Ja Israelin heimo ei ole enää saastuttava minun pyhää nimeäni-eivät he eivätkä heidän kuninkaansa-haureudellansa, kuninkaittensa ruumiilla ja uhrikukkuloillansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Kun he asettivat kynnyksensä minun kynnykseni ääreen, ovenpielensä minun ovenpielteni ääreen, niin että muuri vain oli minun ja heidän välillään, niin he saastuttivat minun pyhän nimeni kauhistuksillansa, joita harjoittivat, ja minä lopetin heidät vihassani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Nyt he vievät haureutensa ja kuninkaittensa ruumiit kauas minusta, ja minä asun heidän keskellänsä iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Sinä, ihmislapsi, saata Israelin heimolle sanoma tästä temppelistä, että he häpeäisivät rikkomuksiansa; ja he mitatkoot sen sopusuhtaisuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Ja jos he häpeävät kaikkea, mitä ovat tehneet, niin tee heille tiettäväksi temppelin muoto sekä sen sisustus, uloskäytävät, sisäänkäytävät, kaikki muodot, kaikki säädökset, kaikki muodot ja kaikki lait; kirjoita ne heidän silmiensä eteen, että he ottaisivat vaarin sen koko muodosta ja kaikista säädöksistä ja tekisivät niiden mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Tämä on temppelin laki: sen koko alue vuoren laella yltympäri on korkeastipyhä. Katso, tämä on temppelin laki.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Ja nämä olivat alttarin mitat kyynärissä, kyynärään luettuna kyynärä ja kämmenenleveys: sen alusta oli kyynärän korkuinen ja kyynärän levyinen, ja sen reunusta ympäri sen laidan oli yhden vaaksan mittainen. Tämä oli alttarin koroke.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Alustasta, joka oli maassa, alimmalle välireunalle: kaksi kyynärää sekä leveyttä yksi kyynärä; ja pienemmältä välireunalta suuremmalle välireunalle: neljä kyynärää sekä leveyttä kyynärä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Jumalan lieteen oli neljä kyynärää, ja Jumalan liedestä ylöspäin olivat ne neljä sarvea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Jumalan lieden pituus oli kaksitoista kyynärää ja leveys kaksitoista, niin että sen neljästä sivusta tuli neliö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Välireunan pituus oli neljätoista kyynärää ja leveys neljätoista, sen neljältä sivulta. Sitä ympäröivä reunusta oli puolikyynäräinen, ja sen alusta oli kyynäräinen ympärinsä. Ja sen portaat olivat itäisellä puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Ja hän sanoi minulle: \"Ihmislapsi, näin sanoo Herra, Herra: Nämä ovat alttaria koskevat säädökset: Sinä päivänä, jona se on saatu tehdyksi, niin että voidaan sillä uhrata polttouhria ja vihmoa sille verta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'anna papeille, leeviläisille, jotka ovat Saadokin jälkeläisiä ja saavat minua lähestyä palvellaksensa minua, sanoo Herra, Herra, mullikka syntiuhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Ota sen verta ja sivele alttarin neljään sarveen ja välireunan neljään kulmaan ja reunustaan yltympäri; niin on sinun puhdistettava se ja toimitettava sen sovitus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Ota sitten syntiuhri-mullikka ja polta se säädetyssä, temppelille kuuluvassa paikassa, pyhäkön ulkopuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Tuo toisena päivänä virheetön kauris syntiuhriksi; alttari on puhdistettava, samoin kuin se puhdistettiin mullikalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Suoritettuasi loppuun puhdistuksen tuo virheetön mullikka ja virheetön oinas pikkukarjasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Tuo ne Herran eteen, ja papit heittäkööt niiden päälle suolaa ja uhratkoot ne polttouhriksi Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Uhraa joka päivä, seitsemänä päivänä, syntiuhri-kauris; myös on uhrattava mullikka ja oinas pikkukarjasta, virheettömät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Seitsemänä päivänä toimitettakoon alttarin sovitus ja puhdistettakoon ja vihittäköön se.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Niiden päivien kuluttua papit kahdeksantena päivänä ja aina edelleen uhratkoot alttarilla polttouhrejansa ja yhteysuhrejansa. Ja niin minä teihin mielistyn, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Sitten hän vei minut takaisin pyhäkön ulommalle portille, sille, joka antoi itään päin; mutta se oli suljettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Niin Herra sanoi minulle: \"Tämä portti on oleva suljettuna: sitä ei saa avata, eikä kenkään saa käydä siitä sisälle, sillä Herra, Israelin Jumala, on käynyt siitä sisälle. Se on oleva suljettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Ruhtinas ainoastaan saakoon ruhtinaana istua siellä ja aterioida Herran edessä; käyköön hän sisään porttieteisen kautta ja tulkoon ulos samaa tietä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Sitten hän vei minut pohjoisportin kautta temppelin edustalle, ja minä näin, ja katso: Herran kunnia täytti Herran temppelin. Niin minä lankesin kasvoilleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Ja Herra sanoi minulle: \"Ihmislapsi, ota huomioosi, katso silmilläsi ja kuule korvillasi kaikki, mitä minä sinulle puhun kaikista Herran temppelin säädöksistä ja kaikista sen laeista, ja ota huomioosi, kuinka temppeliin on mentävä kustakin pyhäkön uloskäytävästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Ja sano niille uppiniskaisille, sano Israelin heimolle: Näin sanoo Herra, Herra: Jo riittävät kaikki teidän kauhistuksenne, te Israelin heimo,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'te kun olette tuoneet muukalaisia, sydämeltään ja ruumiiltaan ympärileikkaamattomia, minun pyhäkkööni olemaan siellä ja häpäisemään minun temppeliäni, samalla kuin olette uhranneet minun leipääni ja rasvaa ja verta; ja niin te olette rikkoneet minun liittoni-kaikkien muitten kauhistustenne lisäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Te ette ole itse hoitaneet minulle suoritettavia pyhiä tehtäviä, vaan olette panneet heitä puolestanne hoitamaan minulle pyhäkössäni suoritettavia tehtäviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Näin sanoo Herra, Herra: ei yksikään muukalainen, sydämeltään ja ruumiiltaan ympärileikkaamaton, saa tulla minun pyhäkkööni, olkoon se kuka tahansa muukalainen, joka israelilaisten keskuudessa on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Vaan ne leeviläiset, jotka menivät minun luotani kauas, silloin kun Israel oli joutunut eksyksiin, nuo, jotka eksyivät pois minusta kivijumalainsa jälkeen, kantakoot syntinsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'he toimittakoot minun pyhäkössäni vartioinnin temppelin porteilla ja toimittakoot temppelipalveluksen: he teurastakoot polttouhrit ja teurasuhrit kansalle ja seisokoot heidän edessään heitä palvelemassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Koska he ovat heitä palvelleet heidän kivijumalainsa edessä ja olleet Israelin heimolle kompastuksena syntiin, sentähden minä kättä kohottaen vakuutan heistä, sanoo Herra, Herra, että heidän on kannettava syntinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'He eivät saa lähestyä minua, niin että toimittaisivat minun edessäni papinvirkaa ja lähestyisivät mitään minulle pyhitettyä, mitään korkeasti-pyhää, vaan heidän on kannettava häpeänsä ja kauhistuksensa, joita ovat tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Ja minä panen heidät hoitamaan temppelissä suoritettavia tehtäviä, mitä siellä vain on palvelijantyötä ja toimitettavaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Mutta ne leeviläiset papit, Saadokin jälkeläiset, jotka hoitivat minun pyhäkössäni suoritettavat tehtävät silloin, kun israelilaiset olivat eksyneet minusta pois, he saavat lähestyä minua, palvella minua ja seisoa minun edessäni uhraamassa minulle rasvaa ja verta, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'He saavat tulla minun pyhäkkööni ja saavat lähestyä minun pöytääni, palvellen minua ja hoitaen minulle suoritettavat tehtävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Ja tullessaan sisemmän esipihan porteille he pukeutukoot pellavavaatteisiin älköötkä pitäkö yllänsä villaista toimittaessaan virkaansa sisemmän esipihan porteissa ja sisällä temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Pellavaiset juhlapäähineet olkoon heillä päässä ja pellavakaatiot lanteilla. Älkööt he panko vyötäisillensä mitään hiostuttavaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Kun he sitten menevät pois ulompaan esipihaan, kansan tykö ulompaan esipihaan, riisukoot vaatteensa, joissa ovat virkaa toimittaneet, jättäkööt ne pyhäkön kammioihin ja pukekoot yllensä toiset vaatteet, etteivät pyhittäisi kansaa vaatteillansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Älkööt he ajelko päätänsä, mutta älkööt myöskään antako tukkansa valtoinaan kasvaa: heidän on leikattava hiuksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Viiniä älköön kukaan pappi juoko tultuansa sisempään esipihaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Leskeä ja hyljättyä älkööt he ottako vaimoksensa, vaan ottakoot neitsyen Israelin heimon jälkeläisistä tai lesken, joka on leskenä papin jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Ja opettakoot he minun kansalleni erotuksen pyhän ja epäpyhän välillä sekä tehkööt heille tiettäväksi, mikä on saastaista, mikä puhdasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Riita-asioissa he seisokoot tuomitsemassa ja tuomitkoot niissä minun oikeuksieni mukaan. Minun lakejani ja käskyjäni he noudattakoot kaikkien minun juhlieni vietossa ja pyhittäkööt minun sapattini.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Älköön hän menkö kuolleen ihmisen luo ja siten tulko saastaiseksi; ainoastaan isästä ja äidistä, pojasta ja tyttärestä, veljestä ja sisaresta, jos tämä ei ollut naitu, hän saa näin saattaa itsensä saastaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Mutta puhdistuksensa jälkeen luettakoon hänelle vielä seitsemän päivää;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'ja sinä päivänä, jona hän tulee pyhäkköön, sisempään esipihaan, toimittamaan virkaansa pyhäkössä, hän uhratkoon syntiuhrinsa, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Ja tämä on oleva heidän perintöosansa: minä olen heidän perintöosansa. Teidän ei tule antaa heille perintömaata Israelissa: minä olen heidän perintömaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Ruokauhrin, syntiuhrin ja vikauhrin he saavat syödä, ja kaikki, mikä on tuhon omaksi vihittyä Israelissa, on tuleva heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Paras kaikesta uutisesta, kaikenlaatuisesta, ja kaikki annit, mitä laatua hyvänsä antinne ovatkin, tulevat papeille; ja parhaat jyvärouheistanne on teidän annettava papille, että sinä tuottaisit siunauksen huoneellesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Papit älkööt syökö mitään itsestään kuollutta tai kuoliaaksi raadeltua, ei lintua eikä raavasta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, '\"Kun te arvotte maata perintöosiksi, niin antakaa Herralle anti, pyhä osa maasta, kahtakymmentäviittä tuhatta pitkä ja kahtakymmentä tuhatta leveä. Se olkoon pyhä koko alueeltaan, yltympäri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Siitä tulkoon pyhäkölle neliö, viisisataa ja viisisataa joka taholta, ja sen lisäksi avointa tilaa viisikymmentä joka taholta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Ja mittaa tästä mitatusta alueesta kahtakymmentäviittä tuhatta pitkälti ja kymmentätuhatta leveälti, ja siinä olkoon pyhäkkö, korkeasti-pyhä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Se olkoon pyhä osa maasta papeille, jotka palvelevat pyhäkössä, jotka lähestyvät ja palvelevat Herraa; se olkoon talojen sijana heitä varten ja pyhänä paikkana pyhäkköä varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Kahtakymmentäviittä tuhatta pitkälti ja kymmentätuhatta leveälti on tuleva leeviläisille, jotka toimittavat palvelusta pyhäkössä, heille perintömaaksi-kaksikymmentä kammiota-.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Kaupungille antakaa perintömaata viittätuhatta leveälti ja kahtakymmentäviittä tuhatta pitkälti, pyhän antimaan viereltä; se olkoon kaiken Israelin heimon oma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Ja ruhtinaalle: molemmilta puolin pyhää antimaata ja kaupungin perintömaata, pyhän antimaan sivusta ja kaupungin perintömaan sivusta, lännen puolelta länteen päin ja idän puolelta itään päin, maata yhtä pitkälti kuin on yhden sukukuntaosan pituus länsirajasta itärajaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Se olkoon hänellä maana, perintömaana Israelissa; ja älkööt minun ruhtinaani enää sortako minun kansaani, vaan jättäkööt muun maan Israelin heimolle sukukunnittain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Näin sanoo Herra, Herra: Jo riittää, te Israelin ruhtinaat! Heittäkää pois väkivalta ja sorto, noudattakaa oikeutta ja vanhurskautta, heretkää häätämästä mailtansa minun kansaani, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Olkoon teillä oikea paino, oikea eefa-mitta ja oikea bat-mitta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Eefa-ja bat-mitta olkoot tarkoin yhtä suuret: bat vetäköön kymmenenneksen hoomer-mittaa ja eefa kymmenenneksen hoomer-mittaa; hoomerin mukaan määrättäköön kumpaisenkin suuruus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Sekelissä olkoon kaksikymmentä geeraa; miina olkoon teillä kaksikymmentä sekeliä, kaksikymmentäviisi sekeliä, viisitoista sekeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Tämä on anti, joka teidän on annettava: kuudennes eefaa nisuhoomerista ja kuudennes eefaa ohrahoomerista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'ljyn määrä bat-mitasta öljyä: kymmenennes batia koor-mitasta-kymmenestä batista, hoomerista-sillä hoomer on kymmenen batia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'pikkukarjasta: kahdestasadasta yksi lammas Israelin runsasvetisiltä laitumilta ruokauhriksi, polttouhriksi ja yhteysuhriksi, että voitaisiin toimittaa heille sovitus, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Kaikki maan kansa on velvoitettu tähän antiin Israelin ruhtinaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Mutta ruhtinas toimittakoon polttouhrit, ruokauhrin ja juomauhrin juhlina, uusinakuina ja sapatteina, kaikkina Israelin heimon juhla-aikoina; hän uhratkoon syntiuhrin, ruokauhrin, polttouhrin ja yhteysuhrin toimittaakseen sovituksen Israelin heimolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Näin sanoo Herra, Herra: Ota ensimmäisessä kuussa, kuukauden ensimmäisenä päivänä virheetön mullikka ja puhdista pyhäkkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Ja pappi ottakoon syntiuhrin verta ja sivelköön sitä temppelin ovenpieliin ja alttarin välireunan neljään kulmaan ja sisemmän esipihan portin ovenpieliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Samoin tee kuukauden seitsemäntenä päivänä sen varalta, että joku olisi erehdyksestä tai tietämättömyydestä rikkonut. Ja niin te toimitatte temppelin sovituksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Ensimmäisessä kuussa, kuukauden neljäntenätoista päivänä, on teillä pääsiäinen. Se on seitsenpäiväinen juhla. Syötäköön silloin happamatonta leipää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Sinä päivänä uhratkoon ruhtinas omasta puolestansa ja maan kaiken kansan puolesta mullikan syntiuhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Ja seitsemänä juhlapäivänä hän uhratkoon polttouhriksi Herralle seitsemän mullikkaa ja seitsemän oinasta, virheettömiä, joka päivä seitsemänä päivänä, ja syntiuhriksi kauriin joka päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Ja ruokauhriksi hän uhratkoon eefa-mitan mullikkaa ja eefa-mitan oinasta kohti sekä öljyä hiin-mitan eefaa kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Seitsemännessä kuussa, kuukauden viidentenätoista päivänä, juhlana, hän uhratkoon samalla tavoin-niin seitsemänä päivänä-samankaltaisen syntiuhrin, polttouhrin ja ruokauhrin sekä saman määrän öljyä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, '\"Näin sanoo Herra, Herra: Sisemmän esipihan portti, se, joka antaa itään päin, olkoon suljettuna kuusi työpäivää. Mutta sapatinpäivänä se avattakoon; myös avattakoon se uudenkuun päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Silloin tulkoon ruhtinas porttieteisen kautta ulkoa ja asettukoon portin ovenpieleen; ja kun papit uhraavat hänen polttouhriansa ja yhteysuhriansa, niin hän kumartaen rukoilkoon portin kynnyksellä ja menköön sitten ulos. Mutta porttia älköön suljettako ennen iltaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Ja maan kansa kumartaen rukoilkoon sen portin ovella sapatteina ja uusinakuina Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Ja polttouhrina, joka ruhtinaan on uhrattava Herralle sapatinpäivänä, olkoon: kuusi virheetöntä karitsaa ja virheetön oinas;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'ja ruokauhrina: eefa-mitta oinasta kohti, mutta ruokauhrina karitsoita kohti se, mitä hän voi ja tahtoo antaa, ynnä hiin-mitta öljyä eefaa kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Uudenkuun päivänä olkoon polttouhrina: virheetön mullikka, kuusi karitsaa ja oinas, virheettömiä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'ja ruokauhrina hän uhratkoon eefan mullikkaa kohti ja eefan oinasta kohti sekä karitsoita kohti sen, mitä hän saa hankituksi, ynnä öljyä hiin-mitan eefaa kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Ja kun ruhtinas tulee, niin tulkoon porttieteisen kautta ja menköön ulos samaa tietä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Mutta kun maan kansa tulee juhlina Herran eteen, niin se, joka pohjoisportin kautta tuli kumartaen rukoilemaan, menköön ulos eteläportin kautta, ja joka tuli eteläportin kautta, se menköön ulos pohjoisportin kautta; älköön kenkään palatko sen portin kautta, josta tuli, vaan menköön ulos vastakkaisesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Ja ruhtinas tulkoon heidän joukossansa, kun he tulevat, ja menköön ulos, kun he menevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Juhlina ja juhla-aikoina olkoon ruokauhri: eefa mullikkaa kohti ja eefa oinasta kohti sekä karitsoita kohti se, mitä mikin voi ja tahtoo antaa, ynnä öljyä hiin-mitta eefaa kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Milloin ruhtinas uhraa vapaaehtoisia lahjoja, polttouhrin tai yhteysuhrin vapaaehtoisena lahjana Herralle, avattakoon hänelle portti, joka antaa itään päin, ja hän uhratkoon polttouhrinsa sekä yhteysuhrinsa samoin, kuin hän uhraa sapatinpäivänä, ja menköön ulos; ja hänen mentyänsä suljettakoon portti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Uhraa vuoden vanha virheetön karitsa joka päivä polttouhriksi Herralle: uhraa se joka aamu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Ja sen lisäksi uhraa ruokauhriksi joka aamu kuudennes eefaa ynnä öljyä kolmannes hiin-mittaa lestyjen jauhojen kostuttamiseksi. Tämä on ruokauhri Herralle-ikuinen, pysyvä säädös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Niin uhratkaa joka aamu karitsa, ruokauhri ja öljy jokapäiväiseksi polttouhriksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Näin sanoo Herra, Herra: Jos ruhtinas antaa jollekin pojistansa lahjan, on se tämän perintöosa. Se on tuleva hänen pojillensa: se on perintöosana heidän omaisuuttansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Mutta jos hän antaa lahjan perintöosastaan jollekin palvelijoistansa, olkoon se tämän omana vapautusvuoteen saakka, mutta sitten tulkoon takaisin ruhtinaalle: sehän on hänen perintöosaansa ja on tuleva hänen pojilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Älköönkä ruhtinas ottako kansan perintöosia, niin että sortaisi heitä pois heidän perintömaaltansa. Omasta perintömaastaan hän antakoon perintöosia pojillensa, ettei kukaan minun kansastani tulisi häädetyksi pois omalta perintömaaltansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Sitten hän vei minut siitä sisäänkäytävästä, joka oli portin sivuseinämällä, niiden kammioiden luo, jotka olivat pyhitettyjä papeille ja jotka antoivat pohjoiseen päin. Ja katso, siellä oli eräs paikka kauimpana länttä kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Ja hän sanoi minulle: \"Tämä on paikka, missä pappien on keitettävä vikauhri ja syntiuhri sekä leivottava ruokauhri, etteivät veisi ulos sitä ulompaan esipihaan ja siten tulisi pyhittäneeksi kansaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Sitten hän vei minut ulompaan esipihaan ja johdatti minut esipihan neljän nurkkauksen ohitse, ja katso, esipihan joka nurkkauksessa oli piha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Esipihan neljässä nurkkauksessa oli suljetut pihat, neljänkymmenen pituiset ja kolmenkymmenen levyiset; nämä neljä nurkka-alaa olivat yhtä suuret.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Ja niissä neljässä oli ympärinsä kivikehä, ja alas kivikehään oli tehty keittoliesiä ympärinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Ja hän sanoi minulle: \"Nämä ovat keittäjäin suojat, joissa temppelipalvelijat keittävät kansan teurasuhrit\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Sitten hän vei minut takaisin temppelin ovelle. Ja katso, vettä kumpusi temppelin kynnyksen alta itään päin, sillä temppelin etusivu oli itää kohti. Ja vesi juoksi alas temppelin oikeanpuolisen sivuseinämän alitse, alttarin eteläpuolitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Sitten hän toi minut ulos pohjoisportin kautta ja kierrätti minut ulkopuolitse ulkoportille, joka antoi itää kohden; ja katso, vesi virtasi oikeanpuoliselta sivuseinämältä päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Mennessänsä itää kohti mies, mittanuora kädessään, mittasi tuhat kyynärää ja antoi minun käydä veden poikki: vettä oli nilkkoihin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Sitten hän mittasi tuhat ja antoi minun käydä veden poikki: vettä oli polviin asti. Sitten hän mittasi tuhat ja antoi minun käydä poikki: vettä oli lanteisiin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Sitten hän mittasi tuhat: tuli virta, jonka poikki minä en voinut käydä, sillä vesi nousi uimavedeksi, virraksi, josta ei voinut käydä poikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Niin hän kysyi minulta: \"Oletko nähnyt, ihmislapsi?\" ja kuljetti minua ja toi takaisin pitkin virran rantaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Mutta kun minä tulin takaisin, niin katso: virran rannalla kasvoi hyvin paljon puita molemmilla puolin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Ja hän sanoi minulle: \"Nämä vedet juoksevat itäiselle alueelle, virtaavat alas Aromaahan ja tulevat mereen; niiden jouduttua mereen vesi siinä paranee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Ja kaikki elolliset, kaikki, jotka liikkuvat, virkoavat elämään kaikkialla, mihin tämä kaksoisvirta tulee. Ja kaloja on oleva hyvin paljon; sillä kun nämä vedet sinne tulevat ja vesi paranee, niin kaikki virkoaa elämään, minne vain virta tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Ja kalastajia seisoo sen rannalla. Een-Gedistä Een-Eglaimiin asti se on oleva yhtä verkkoapajaa. Siinä on kaikenlaisia kaloja, aivan kuin suuren meren kaloja, hyvin paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Sen rämeet ja lätäköt eivät parane: ne jätetään suolan valtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Mutta virran varrella, sen molemmilla rannoilla, kasvaa kaikkinaisia hedelmäpuita. Niistä eivät lakastu lehdet eivätkä lopu hedelmät: joka kuukausi ne kantavat tuoreet hedelmät, sillä niitten vedet juoksevat pyhäköstä, ja niitten hedelmät ovat ravitsevaiset ja niitten lehdet parantavaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Näin sanoo Herra, Herra: Tämä on raja, jonka mukaan teidän on jaettava maa perintöosiksi kahdelletoista Israelin sukukunnalle-Joosef saakoon kaksi osaa-.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Ja te saatte siitä perintöosan jokainen kohdaltansa; sillä minä olen kättä kohottaen luvannut antaa sen teidän isillenne, ja niin tämä maa tulee teille perintöosaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Tämä on maan pohjoispuolinen raja: Suuresta merestä Hetlonin tietä siihen asti, mistä mennään Sedadiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Hamat, Beerota, Sibraim, joka on Damaskon alueen ja Hamatin alueen välissä, keskimmäinen Haaser, joka on Hauranin rajalla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'ja näin menee raja merestä Hasar-Eenoniin-Damaskon alue jää pohjoiseen ja pohjoiseen myös Hamatin alue. Tämä on pohjoispuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Sitten itäpuoli: Hauranin ja Damaskon välistä sekä Gileadin ja Israelin maan välistä, Jordania pitkin. Mitatkaa se rajasta Idänmereen. Tämä on itäpuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Sitten eteläpuoli, päivään päin: Taamarista Meriban veteen, joka on Kaadeksessa, Puroon ja Suureen mereen. Tämä on päivänpuoli, etelään päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Sitten länsipuoli: Suuri meri rajasta sen paikan kohdalle, mistä mennään Hamatiin. Tämä on länsipuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Jakakaa tämä maa keskenänne Israelin sukukuntien mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Ja arpokaa se perintöosiksi itsellenne ja muukalaisille, jotka asuvat teidän keskuudessanne ja ovat synnyttäneet lapsia teidän keskuudessanne. Olkoot he teille saman arvoisia kuin maassa syntyneet israelilaiset: he saakoot arvalla perintöosan Israelin sukukuntain keskuudessa teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Missä sukukunnassa muukalainen asuu, siinä antakaa hänelle perintöosa, sanoo Herra, Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, '\"Ja nämä ovat sukukuntien nimet: Pohjois-äärellä, pitkin Hetlonin tien vartta siihen asti, mistä mennään Hamatiin, ja siitä Hasar-Eenaniin-Damaskon alue jää pohjoiseen Hamatin sivulle-;tämä tulee hänelle idän puolelta lännen puolelle asti: Daan, yksi osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Daanin alueen sivussa, idän puolelta lännen puolelle asti: Asser, yksi osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Asserin alueen sivussa, idän puolelta lännen puolelle asti: Naftali, yksi osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Naftalin alueen sivussa, idän puolelta lännen puolelle asti: Manasse, yksi osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Manassen alueen sivussa, idän puolelta lännen puolelle asti: Efraim, yksi osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Efraimin alueen sivussa, idän puolelta lännen puolelle asti: Ruuben, yksi osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Ruubenin alueen sivussa, idän puolelta lännen puolelle asti: Juuda, yksi osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Juudan alueen sivussa, idän puolelta lännen puolelle asti, on oleva se antimaa, joka teidän on annettava, kahtakymmentäviittä tuhatta leveä ja niin pitkä kuin yksi sukukuntaosa idän puolelta lännen puolelle; ja pyhäkkö olkoon sen keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Antimaa, joka teidän on annettava Herralle, olkoon kahtakymmentäviittä tuhatta pitkä ja kahtakymmentä tuhatta leveä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Ja pyhää antimaata tulkoon seuraaville: papeille pohjoisesta kahtakymmentäviittä tuhatta, lännestä kymmentätuhatta leveälti, idästä kymmentätuhatta leveälti ja etelästä kahtakymmentäviittä tuhatta pitkälti; ja Herran pyhäkkö olkoon siinä keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Papeille, niille Saadokin jälkeläisistä, jotka ovat pyhitettyjä, jotka ovat hoitaneet minulle suoritettavat tehtävät ja jotka eivät eksyneet, niinkuin leeviläiset eksyivät, silloin kun israelilaiset joutuivat eksyksiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'heille se tulkoon verona antimaasta, korkeasti-pyhänä; tulkoon leeviläisten alueen vierestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Leeviläiset saakoot samanlaisen alueen kuin papit, kahtakymmentäviittä tuhatta pitkän ja kymmentätuhatta leveän. Koko pituus olkoon kaksikymmentäviisi tuhatta ja leveys kaksikymmentä tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Älkööt he myykö siitä mitään, älköönkä parasta maata vaihdettako tai luovutettako, sillä se on pyhitetty Herralle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Mutta viittätuhatta leveä maa, mikä jää yli kahdenkymmenenviiden tuhannen sivusta, on kaupungin yhteisomaisuutta asumuksia ja avointa tilaa varten; ja kaupunki olkoon sen keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Ja nämä olkoot sen mitat: pohjoispuoli neljätuhatta viisisataa, eteläpuoli neljätuhatta viisisataa, itäpuoli neljätuhatta viisisataa ja länsipuoli neljätuhatta viisisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Ja kaupungilla olkoon avoin tila: pohjoiseen päin kaksisataa viisikymmentä, etelään päin kaksisataa viisikymmentä, itään päin kaksisataa viisikymmentä ja länteen päin kaksisataa viisikymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Mutta niin pitkälti kuin jää yli pyhän antimaan viereltä, kymmenentuhatta itään päin ja kymmenentuhatta länteen päin, se olkoon pyhän antimaan vierellä, ja sen sato tulkoon leiväksi kaupungin työmiehille;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'ja sitä viljelkööt kaupungin työmiehet kaikista Israelin sukukunnista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Koko antimaa on kahtakymmentäviittä tuhatta ja kahtakymmentäviittä tuhatta. Neliönmuotoisena on teidän annettava pyhä antimaa ynnä kaupungin perintömaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Mikä jää yli, se tulkoon ruhtinaalle: molemmilta puolilta pyhää antimaata ja kaupungin perintömaata, niitten kahdenkymmenenviiden tuhannen-antimaan-sivusta itärajaan asti, ynnä länteen päin niitten kahdenkymmenen viiden tuhannen sivusta länsirajaan asti, on ruhtinaalle tuleva sukukuntaosia vastaava maa; ja pyhä antimaa sekä temppelipyhäkkö olkoot sen keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Leeviläisten perintömaasta ja kaupungin perintömaasta asti, jotka ovat ruhtinaalle tulevan maan keskellä, tulee ruhtinaalle se, mikä on Juudan alueen ja Benjaminin alueen välissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Sitten muut sukukunnat: Idän puolelta lännen puolelle asti: Benjamin, yksi osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Benjaminin alueen sivussa, idän puolelta lännen puolelle asti: Simeon, yksi osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Simeonin alueen sivussa, idän puolelta lännen puolelle asti: Isaskar, yksi osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Isaskarin alueen sivussa, idän puolelta lännen puolelle asti: Sebulon, yksi osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Sebulonin alueen sivussa, idän puolelta lännen puolelle asti: Gaad, yksi osa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Ja Gaadin alueen sivua, etelän puolella, päivään päin, menee raja Taamarista Meriban veteen, Kaadekseen, Puroon ja Suureen mereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Tämä on maa, joka teidän on arvottava perintöosiksi Israelin sukukunnille, ja nämä ovat heidän osuutensa, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Ja nämä ovat kaupungin uloskäytävät: Pohjoispuolella on mitta neljätuhatta viisisataa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Ja kaupungin portteja, jotka ovat nimitetyt Israelin sukukuntain mukaan, on pohjoisessa kolme: Ruubenin portti yksi, Juudan portti toinen ja Leevin portti kolmas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Itäpuolella: neljätuhatta viisisataa, ja portteja kolme: Joosefin portti yksi, Benjaminin portti toinen ja Daanin portti kolmas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Eteläpuolella on mitta neljätuhatta viisisataa, ja portteja kolme: Simeonin portti yksi, Isaskarin portti toinen ja Sebulonin portti kolmas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Länsipuolella: neljätuhatta viisisataa, ja portteja kolme: Gaadin portti yksi, Asserin portti toinen ja Naftalin portti kolmas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Ympärinsä: kahdeksantoista tuhatta. Ja kaupungin nimi on tästedes oleva: Herra on täällä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Joojakimin, Juudan kuninkaan, kolmantena hallitusvuotena tuli Nebukadnessar, Baabelin kuningas, Jerusalemin edustalle ja piiritti sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Ja Herra antoi hänen käsiinsä Joojakimin, Juudan kuninkaan, sekä osan Jumalan huoneen astioita, ja hän vei ne Sinearin maahan, jumalansa huoneeseen. Ja hän vei astiat jumalansa aarrekammioon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Ja kuningas käski ylimmäisen hoviherransa Aspenaan tuoda israelilaisia poikia, jotka olivat kuninkaallista sukua tai ylimysperheistä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'nuorukaisia, joissa ei ollut mitään virheä ja jotka olivat kaunismuotoisia, jotka kykenivät käsittämään kaikkea viisautta, olivat terävä-älyisiä ja hyväoppisia ja jotka olisivat kelvollisia palvelemaan kuninkaan hovissa; heille hänen tuli opettaa kaldealaisten kirjoitusta ja kieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Ja kuningas määräsi heille jokapäiväiseksi ravinnoksi ruokaa kuninkaan pöydästä ja viiniä, jota hän itse joi. Niin heitä oli kasvatettava kolme vuotta, ja niiden kuluttua heidän tuli astua kuninkaan palvelukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Heidän joukossaan olivat juutalaiset pojat Daniel, Hananja, Miisael ja Asarja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Ja hoviherrain päällikkö pani heille nimet: Danielille hän pani nimen Beltsassar, Hananjalle nimen Sadrak, Miisaelille nimen Meesak ja Asarjalle nimen Abednego.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Mutta Daniel päätti lujasti olla saastuttamatta itseään kuninkaan pöydän ruualla ja viinillä, jota tämä joi, ja anoi hoviherrain päälliköltä, ettei hänen tarvitsisi itseään saastuttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Ja Jumala salli Danielin saada suosion ja armon hoviherrain päällikön edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Mutta hoviherrain päällikkö sanoi Danielille: \"Minä pelkään, että jos herrani, kuningas, joka on määrännyt teidän ruokanne ja juomanne, huomaa teidän kasvonne laihemmiksi kuin muiden ikäistenne nuorukaisten, niin te saatatte minun pääni vaaraan kuninkaan edessä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Silloin Daniel sanoi katsastajalle, jonka hoviherrain päällikkö oli määrännyt pitämään silmällä Danielia, Hananjaa, Miisaelia ja Asarjaa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, '\"Koettele palvelijoitasi kymmenen päivää, ja annettakoon meille vihannesruokaa syödäksemme ja vettä juodaksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Sitten tarkastettakoon sinun edessäsi, miltä me näytämme ja miltä näyttävät ne nuorukaiset, jotka syövät kuninkaan pöydän ruokaa; ja tee sitten palvelijoillesi sen mukaan, mitä silloin havaitset.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Ja hän kuuli heitä tässä asiassa ja koetteli heitä kymmenen päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Mutta kymmenen päivän kuluttua havaittiin heidät muodoltaan kauniimmiksi ja ruumiiltaan lihavammiksi kuin yksikään niistä nuorukaisista, jotka söivät kuninkaan pöydän ruokaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Ja niin katsastaja jätti pois heille määrätyn ruuan ja heidän juotavansa viinin ja antoi heille vihannesruokaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Ja Jumala antoi näille neljälle nuorukaiselle taidon käsittää kaikki kirjoitukset ja kaiken viisauden; ja Daniel ymmärsi myös kaikkinaiset näyt ja unet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Kun sitten ne päivät olivat kuluneet, joiden jälkeen kuningas oli käskenyt tuoda heidät esiin, niin hoviherrain päällikkö toi heidät Nebukadnessarin eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Kun nyt kuningas keskusteli heidän kanssaan, ei ollut heidän joukossansa yhtäkään Danielin, Hananjan, Miisaelin ja Asarjan vertaista. Niin he tulivat kuninkaan palvelijoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Ja kaikissa viisautta ja ymmärrystä vaativissa asioissa, joita kuningas heiltä kyseli, hän havaitsi heidät kymmentä vertaa etevämmiksi kuin kaikki tietäjät ja noidat, mitä koko hänen valtakunnassaan oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Ja Daniel oli siellä kuningas Kooreksen ensimmäiseen vuoteen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Nebukadnessarin toisena hallitusvuotena näki Nebukadnessar unia, ja hänen mielensä oli levoton eikä hän enää saanut unta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Silloin kuningas käski kutsua tietäjät ja noidat, velhot ja kaldealaiset ilmoittamaan kuninkaalle hänen unensa; ja he tulivat ja astuivat kuninkaan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Ja kuningas sanoi heille: \"Minä olen nähnyt unen, ja mieleni on levoton, kunnes saan tietää sen unen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Silloin kaldealaiset puhuivat kuninkaalle araminkielellä: \"Eläköön kuningas iankaikkisesti! Sano uni palvelijoillesi, niin me ilmoitamme sen selityksen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Kuningas vastasi ja sanoi kaldealaisille: \"Tämä minun sanani on peruuttamaton: Ellette ilmoita minulle unta ja sen selitystä, niin teidät hakataan kappaleiksi ja teidän talonne tehdään soraläjiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Mutta jos te ilmoitatte minulle unen ja sen selityksen, niin te saatte minulta lahjoja ja antimia ja suuren kunnian. Sentähden ilmoittakaa minulle uni ja sen selitys.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'He vastasivat toistamiseen ja sanoivat: \"Kuningas sanokoon unen palvelijoilleen, niin me ilmoitamme sen selityksen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Kuningas vastasi ja sanoi: \"Minä huomaan selvästi, että te vain koetatte voittaa aikaa, koska näette peruuttamattomaksi tämän minun sanani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'että ellette ilmoita minulle unta, on teillä edessä vain yksi tuomio. Sillä te olette sopineet keskenänne, että puhutte minun edessäni valheellista ja turmiollista puhetta toivoen, että aika muuttuu. Sentähden sanokaa minulle uni; silloin minä tiedän, että te osaatte ilmoittaa minulle selityksen siihen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Kaldealaiset vastasivat kuninkaan edessä ja sanoivat: \"Ei ole maan päällä ihmistä, joka kykenisi selittämään sen, mitä kuningas sanoi. Eikä yksikään suuri ja voimallinen kuningas ole koskaan vaatinut tämänkaltaista asiaa keneltäkään tietäjältä, noidalta tai kaldealaiselta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Sillä asia, jota kuningas vaatii, on vaikea, eikä ole ketään, joka voisi sen kuninkaalle selittää, paitsi jumalat, joiden asuinsija ei ole ihmisten tykönä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Tästä kuningas suuttui ja julmistui kovin ja käski tappaa kaikki Baabelin viisaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Kun tästä oli käsky annettu ja viisaat piti tapettaman, etsittiin Danielia ja hänen tovereitaan tapettaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Silloin Daniel antoi viisaan ja taitavan vastauksen Arjokille, kuninkaan henkivartioväen päällikölle, joka oli lähtenyt tappamaan Baabelin viisaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Hän vastasi ja sanoi Arjokille, kuninkaan päällikölle: \"Miksi on kuningas antanut niin ankaran käskyn?\" Silloin Arjok kertoi Danielille asian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Niin Daniel meni palatsiin ja pyysi kuningasta antamaan hänelle aikaa, että hän saisi ilmoittaa kuninkaalle selityksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Sitten Daniel meni kotiinsa ja kertoi asian tovereillensa Hananjalle, Miisaelille ja Asarjalle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'kehoittaen heitä rukoilemaan armoa taivaan Jumalalta tämän salatun asian tähden, ettei Danielia ja hänen tovereitansa tapettaisi muiden Baabelin viisaitten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Silloin salaisuus ilmoitettiin Danielille yöllisessä näyssä. Niin Daniel kiitti taivaan Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel lausui ja sanoi: \"Olkoon Jumalan nimi kiitetty iankaikkisesta iankaikkiseen, sillä hänen on viisaus ja voima.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Hän muuttaa ajat ja hetket, hän syöksee kuninkaat vallasta ja korottaa kuninkaat valtaan, hän antaa viisaille viisauden ja taidollisille ymmärryksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Hän paljastaa syvät ja salatut asiat, hän tietää, mitä pimeydessä on, ja valkeus asuu hänen tykönänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Sinua, minun isieni Jumala, minä kiitän ja ylistän siitä, että olet antanut minulle viisauden ja voiman ja että nyt annoit minun tietää, mitä me sinulta rukoilimme. Sillä sinä annoit meidän tietää kuninkaan asian.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Sitten Daniel meni Arjokin tykö, jolla oli kuninkaan määräys tappaa Baabelin viisaat. Hän meni ja sanoi hänelle näin: \"Älä tapa Baabelin viisaita; vie minut kuninkaan eteen, niin minä ilmoitan kuninkaalle selityksen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Silloin Arjok vei kiiruusti Danielin kuninkaan eteen ja sanoi tälle näin: \"Minä olen löytänyt juutalaisten pakkosiirtolaisten joukosta miehen, joka ilmoittaa kuninkaalle selityksen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Kuningas vastasi ja sanoi Danielille, jonka nimenä oli Beltsassar: \"Voitko sinä ilmoittaa minulle unen, jonka minä näin, ja sen selityksen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel vastasi kuninkaalle ja sanoi: \"Salaisuutta, jonka kuningas tahtoo tietää, eivät viisaat, noidat, tietäjät eivätkä tähtienselittäjät voi ilmoittaa kuninkaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Mutta on Jumala taivaassa; hän paljastaa salaisuudet ja ilmoittaa kuningas Nebukadnessarille, mitä on tapahtuva aikojen lopussa. Tämä on sinun unesi, sinun pääsi näky, joka sinulla oli vuoteessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Kun sinä, kuningas, olit vuoteessasi, nousi mieleesi ajatus, mitä tämän jälkeen on tapahtuva; ja hän, joka paljastaa salaisuudet, ilmoitti sinulle, mitä tapahtuva on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Ja tämä salaisuus on paljastettu minulle, ei oman viisauteni voimasta, ikäänkuin minulla olisi sitä enemmän kuin kenelläkään muulla ihmisellä, vaan sentähden että selitys ilmoitettaisiin kuninkaalle ja sinä saisit selville sydämesi ajatukset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Sinä näit, kuningas, katso, oli iso kuvapatsas. Se kuvapatsas oli suuri, ja sen kirkkaus oli ylenpalttinen. Se seisoi sinun edessäsi, ja se oli hirvittävä nähdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Kuvan pää oli parasta kultaa, sen rinta ja käsivarret hopeata, sen vatsa ja lanteet vaskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Sen sääret olivat rautaa, sen jalat osaksi rautaa, osaksi savea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Sinun sitä katsellessasi irtautui kivilohkare-ei ihmiskäden voimasta-ja iski kuvapatsasta jalkoihin, jotka olivat rautaa ja savea, ja murskasi ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Silloin musertuivat yhdellä haavaa rauta, savi, vaski, hopea ja kulta, ja niiden kävi kuin akanain kesäisillä puimatantereilla: tuuli vei ne, eikä niistä löydetty jälkeäkään. Mutta kivestä, joka oli kuvapatsaan murskannut, tuli suuri vuori, ja se täytti koko maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Tämä oli se uni, ja nyt sanomme kuninkaalle sen selityksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Sinä, kuningas, olet kuningasten kuningas, jolle taivaan Jumala on antanut vallan, voiman, väkevyyden ja kunnian');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'ja jonka käteen hän on antanut ihmiset, missä ikinä heitä asuu, ja kedon eläimet ja taivaan linnut, asettaen sinut kaikkien niiden valtiaaksi: sinä olet se kultainen pää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Mutta sinun jälkeesi nousee toinen valtakunta, joka on halvempi kuin sinun; ja sitten kolmas valtakunta, joka on vaskea ja joka hallitsee kaikkea maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Ja neljäs valtakunta on tuleva, luja kuin rauta; niinkuin rauta musertaa ja särkee kaiken, niinkuin rauta murskaa, niin se on musertava ja murskaava ne kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Ja että sinä näit jalkain ja varvasten olevan osittain savenvalajan savea, osittain rautaa, se merkitsee, että se on oleva hajanainen valtakunta; kuitenkin on siinä oleva raudan lujuutta, niinkuin sinä näit rautaa olevan saven seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Ja että jalkojen varpaat olivat osaksi rautaa, osaksi savea, se merkitsee, että osa sitä valtakuntaa on oleva luja, osa sitä on oleva hauras.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Että sinä näit rautaa olevan saven seassa, se merkitsee, että vaikka ne sekaantuvat toisiinsa ihmissiemenellä, ne eivät yhdisty toinen toiseensa, niinkuin ei rautakaan sekaannu saveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Mutta niiden kuningasten päivinä on taivaan Jumala pystyttävä valtakunnan, joka on kukistumaton iankaikkisesti ja jonka valtaa ei toiselle kansalle anneta. Se on musertava kaikki ne muut valtakunnat ja tekevä niistä lopun, mutta se itse on pysyvä iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'niinkuin sinä näit, että kivilohkare irtautui vuoresta-ei ihmiskäden voimasta-ja murskasi raudan, vasken, saven, hopean ja kullan. Suuri Jumala on ilmoittanut kuninkaalle, mitä tämän jälkeen on tapahtuva. Ja uni on tosi ja sen selitys luotettava.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Silloin kuningas Nebukadnessar lankesi kasvoillensa ja kumartui maahan Danielin edessä ja käski uhrata hänelle ruokauhria ja suitsutusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Kuningas vastasi Danielille ja sanoi: \"Totisesti on teidän Jumalanne jumalien Jumala ja kuningasten herra ja se, joka paljastaa salaisuudet; sillä sinä olet voinut paljastaa tämän salaisuuden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Sitten kuningas korotti Danielin ja antoi hänelle paljon suuria lahjoja ja asetti hänet koko Baabelin maakunnan herraksi ja kaikkien Baabelin viisaitten ylimmäiseksi päämieheksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Ja Danielin anomuksesta kuningas antoi Sadrakin, Meesakin ja Abednegon hoitoon Baabelin maakunnan hallinnon. Mutta Daniel jäi kuninkaan hoviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Kuningas Nebukadnessar teetti kultaisen kuvapatsaan, jonka korkeus oli kuusikymmentä kyynärää ja leveys kuusi kyynärää, ja pystytti sen Duuran lakeudelle Baabelin maakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Ja kuningas Nebukadnessar lähetti kokoamaan satraapit, maaherrat, käskynhaltijat, neuvonantajat, aarteiden hoitajat, lainoppineet, tuomarit ja kaikki muut maakuntain virkamiehet, että he tulisivat sen kuvapatsaan vihkiäisiin, jonka kuningas Nebukadnessar oli pystyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Silloin kokoontuivat satraapit, maaherrat, käskynhaltijat, neuvonantajat, aarteiden hoitajat, lainoppineet, tuomarit ja kaikki muut maakuntain virkamiehet sen kuvapatsaan vihkiäisiin, jonka kuningas Nebukadnessar oli pystyttänyt, ja he asettuivat sen kuvapatsaan eteen, jonka Nebukadnessar oli pystyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Ja kuuluttaja huusi voimallisesti: \"Teille, kansat, sukukunnat ja kielet, julistetaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'heti kun te kuulette torvien, huilujen, kitarain, harppujen, psalttarien, säkkipillien ja kaikkinaisten muiden soittimien äänen, langetkaa maahan ja kumartaen rukoilkaa kultaista kuvapatsasta, jonka kuningas Nebukadnessar on pystyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Mutta joka ei lankea maahan ja kumarra, se heitetään sillä hetkellä tuliseen pätsiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Sentähden, heti kun kaikki kansat kuulivat torvien, huilujen, kitarain, harppujen, psalttarien, säkkipillien ja kaikkinaisten muiden soittimien äänen, lankesivat kaikki kansat, sukukunnat ja kielet maahan ja kumartaen rukoilivat kultaista kuvapatsasta, jonka kuningas Nebukadnessar oli pystyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Silloin astui heti kaldealaisia miehiä esiin syyttämään juutalaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'He lausuivat ja sanoivat kuningas Nebukadnessarille: \"Kuningas eläköön iankaikkisesti!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Sinä, kuningas, olet antanut käskyn, että jokainen, joka kuulee torvien, huilujen, kitarain, harppujen, psalttarien, säkkipillien ja kaikkinaisten muiden soittimien äänen, langetkoon maahan ja kumartaen rukoilkoon kultaista kuvapatsasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'ja että joka ei lankea maahan ja kumarra, se heitetään tuliseen pätsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'On juutalaisia miehiä, joiden hoitoon sinä olet antanut Baabelin maakunnan hallinnon, Sadrak, Meesak ja Abednego: nämä miehet eivät välitä sinun käskystäsi, kuningas; he eivät palvele sinun jumaliasi eivätkä kumartaen rukoile kultaista kuvapatsasta, jonka sinä olet pystyttänyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Silloin Nebukadnessar vihan vimmassa käski tuoda Sadrakin, Meesakin ja Abednegon. Kun nämä miehet oli tuotu kuninkaan eteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'lausui Nebukadnessar ja sanoi heille: \"Aivanko tahallanne te, Sadrak, Meesak ja Abednego, ette tahdo palvella minun jumalaani ettekä kumartaen rukoilla kultaista kuvapatsasta, jonka minä olen pystyttänyt?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Nyt, jos te siinä silmänräpäyksessä, kun kuulette torvien, huilujen, kitarain, harppujen, psalttarien, säkkipillien ja kaikkinaisten muiden soittimien äänen, olette valmiit lankeamaan maahan ja kumartaen rukoilemaan kuvapatsasta, jonka minä olen teettänyt, niin hyvä! Mutta ellette kumarra, niin teidät heti paikalla heitetään tuliseen pätsiin; ja kuka on se jumala, joka pelastaa teidät minun kädestäni?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Sadrak, Meesak ja Abednego vastasivat ja sanoivat kuninkaalle: \"Nebukadnessar! Ei ole tarpeellista meidän vastata sinulle tähän sanaakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Jos niin käy, voi meidän Jumalamme kyllä pelastaa meidät tulisesta pätsistä, ja hän pelastaa myös sinun kädestäsi, kuningas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Ja vaikka ei pelastaisikaan, niin tiedä se, kuningas, että me emme palvele sinun jumaliasi emmekä kumartaen rukoile kultaista kuvapatsasta, jonka sinä olet pystyttänyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Silloin Nebukadnessar tuli kiukkua täyteen Sadrakia, Meesakia ja Abednegoa kohtaan ja hänen hahmonsa muuttui. Ja hän käski ja sanoi, että pätsi oli kuumennettava seitsemän kertaa kuumemmaksi kuin tavallisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Ja hän käski sotajoukkonsa väkevimpien miesten sitoa Sadrakin, Meesakin ja Abednegon ja heittää heidät tuliseen pätsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Silloin nämä sidottiin vaippoineen, takkeineen, päähineineen ja muine vaatteineen ja heitettiin tuliseen pätsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Koska nyt kuninkaan sana oli niin ankara ja pätsi niin kovin kuumennettu, tappoi tulen liekki ne miehet, jotka veivät ylös Sadrakin, Meesakin ja Abednegon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Mutta nämä kolme miestä, Sadrak, Meesak ja Abednego, suistuivat sidottuina tuliseen pätsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Silloin kuningas Nebukadnessar hämmästyi ja nousi kiiruusti ylös ja lausui hallitusmiehilleen sanoen: \"Emmekö heittäneet kolme miestä sidottuina tuleen?\" He vastasivat ja sanoivat kuninkaalle: \"Totisesti, kuningas!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Hän vastasi ja sanoi: \"Katso, minä näen neljä miestä kävelevän vapaina tulessa, eivätkä he ole vahingoittuneet, ja neljäs on näöltänsä niinkuin jumalan poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Silloin Nebukadnessar meni tulisen pätsin aukolle, lausui ja sanoi: \"Sadrak, Meesak ja Abednego, te korkeimman Jumalan palvelijat, astukaa ulos ja tulkaa tänne\". Sadrak, Meesak ja Abednego astuivat silloin ulos tulesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Satraapit, maaherrat, käskynhaltijat ja kuninkaan hallitusmiehet kokoontuivat ja näkivät, ettei tuli ollut voinut mitään näiden miesten ruumiille, etteivät heidän päänsä hiukset olleet kärventyneet eivätkä heidän vaatteensa vioittuneet; eikä heissä tuntunut tulen käryä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Silloin Nebukadnessar lausui ja sanoi: \"Kiitetty olkoon Sadrakin, Meesakin ja Abednegon Jumala, joka lähetti enkelinsä ja pelasti palvelijansa, jotka häneen turvasivat eivätkä totelleet kuninkaan käskyä, vaan antoivat ruumiinsa alttiiksi, ennemmin kuin palvelivat kumartaen rukoilivat muuta jumalaa kuin omaa Jumalaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Ja minä annan käskyn, että jokainen, olkoon hän mitä kansaa, kansakuntaa ja kieltä tahansa, joka puhuu pilkaten Sadrakin, Meesakin ja Abednegon Jumalasta, hakattakoon kappaleiksi, ja hänen talonsa tehtäköön soraläjäksi; sillä ei ole muuta jumalaa, joka niin voi pelastaa kuin tämä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Sitten kuningas asetti Sadrakin, Meesakin ja Abednegon suureen valtaan Baabelin maakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, '{3:31} \"Kuningas Nebukadnessar kaikille kansoille, kansakunnille ja kielille, jotka asuvat kaiken maan päällä: suuri olkoon teidän rauhanne!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, '{3:32} Minä olen nähnyt hyväksi ilmoittaa ne tunnusteot ja ihmeet, jotka korkein Jumala on minulle tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, '{3:33} Kuinka suuret ovat hänen tunnustekonsa ja kuinka voimalliset hänen ihmeensä! Hänen valtakuntansa on iankaikkinen valtakunta ja hänen valtansa pysyy suvusta sukuun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, '{4:1} \"Minä Nebukadnessar elin rauhassa huoneessani ja onnellisena palatsissani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, '{4:2} Minä näin unen, ja se peljästytti minut; ja unikuvat, joita minulla oli vuoteessani, minun pääni näyt, kauhistuttivat minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, '{4:3} Niin minä annoin käskyn tuoda eteeni kaikki Baabelin viisaat, että he ilmoittaisivat minulle unen selityksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, '{4:4} Silloin tulivat tietäjät, noidat, kaldealaiset ja tähtienselittäjät, ja minä kerroin heille unen, mutta he eivät voineet ilmoittaa minulle sen selitystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, '{4:5} Mutta viimein tuli minun eteeni Daniel, jonka nimi on minun jumalani nimen mukaan Beltsassar ja jossa on pyhien jumalien henki; ja minä kerroin hänelle unen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, '{4:6} \'Beltsassar, sinä tietäjäin päämies, jossa minä tiedän olevan pyhien jumalien hengen ja jolle mikään salaisuus ei ole liian vaikea! Sano, mitä olivat ne näyt, jotka minä unessani näin, ja mikä on sen selitys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, '{4:7} Nämä olivat minun pääni näyt, jotka minulla oli vuoteessani. Minä näin: Katso, oli puu keskellä maata, ja sen korkeus oli suuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, '{4:8} Puu kasvoi ja vahvistui, niin että sen latva ulottui taivaaseen ja se näkyi kaiken maan ääriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, '{4:9} Sen lehvät olivat kauniit ja sen hedelmät suuret, ja siinä oli ravintoa kaikille. Sen alla etsivät varjoa kedon eläimet, ja sen oksilla asuivat taivaan linnut, ja kaikki liha sai siitä ravintonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, '{4:10} Minä näin pääni näyissä, joita minulla oli vuoteessani: katso, pyhä enkeli astui alas taivaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, '{4:11} Hän huusi voimallisesti ja sanoi näin: hakatkaa puu poikki ja karsikaa sen oksat, riipikää sen lehvät ja hajottakaa sen hedelmät. Paetkoot eläimet sen alta ja linnut sen oksilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, '{4:12} Mutta sen kanto juurineen jättäkää maahan, rauta-ja vaskikahleissa kedon ruohikkoon. Taivaan kasteesta hän kastukoon, ja niinkuin eläinten olkoon hänen osansa maan ruoho.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, '{4:13} Hänen sydämensä muutetaan, niin ettei se ole ihmisen sydän, ja hänelle annetaan eläimen sydän. Ja niin kulukoon häneltä seitsemän aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, '{4:14} Tämä on säädetty enkelien päätöksellä, ja niin ovat tästä asiasta pyhät sanoneet, että elävät tietäisivät Korkeimman hallitsevan ihmisten valtakuntaa ja antavan sen, kenelle hän tahtoo, ja asettavan sen päämieheksi ihmisistä halvimman.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, '{4:15} Tämän unen näin minä, kuningas Nebukadnessar. Ja sinä, Beltsassar, sano sen selitys, koska ei yksikään minun valtakuntani viisaista voi minulle ilmoittaa sen selitystä. Mutta sinä sen voit, sillä sinussa on pyhien jumalien henki.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, '{4:16} Silloin Daniel, jonka nimenä oli Beltsassar, hämmästyi hetkeksi, ja hänen ajatuksensa peljästyttivät häntä. Kuningas lausui ja sanoi: \"Beltsassar, älköön uni ja sen selitys sinua peljästyttäkö\". Beltsassar vastasi ja sanoi: \"Herrani, koskekoon uni sinun vihollisiasi ja sen selitys sinun vastustajiasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, '{4:17} Puu, jonka sinä näit ja joka kasvoi ja vahvistui, niin että sen latva ulottui taivaaseen ja se näkyi kaikkeen maahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, '{4:18} jonka lehvät olivat kauniit ja hedelmät suuret ja jossa oli ravintoa kaikille, jonka alla kedon eläimet asuivat ja jonka oksilla taivaan linnut oleskelivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, '{4:19} -se puu olet sinä, kuningas, joka olet kasvanut ja vahvistunut; sinun suuruutesi on kasvanut ja ulottuu taivaaseen ja sinun valtasi maan ääriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, '{4:20} Ja että kuningas näki pyhän enkelin astuvan alas taivaasta ja sanovan: \'Hakatkaa puu poikki ja turmelkaa se, mutta jättäkää sen kanto juurineen maahan, rauta-ja vaskikahleissa kedon ruohikkoon; taivaan kasteesta hän kastukoon, ja niinkuin kedon eläinten olkoon hänen osansa, kunnes häneltä on kulunut seitsemän aikaa\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, '{4:21} sen selitys, oi kuningas, ja Ylimmäisen päätös, joka on kohdannut minun herraani, kuningasta, on tämä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, '{4:22} Sinut ajetaan pois ihmisten seasta, ja kedon eläinten parissa on sinun asuinpaikkasi oleva; sinä joudut syömään ruohoa niinkuin raavaat, ja sinä olet kastuva taivaan kasteesta; ja niin on sinulta kuluva seitsemän aikaa, kunnes tulet tuntemaan, että Korkein hallitsee ihmisten valtakuntaa ja antaa sen, kenelle hän tahtoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, '{4:23} Mutta että käskettiin jättää maahan puun kanto juurineen, se tietää, että sinun valtakuntasi pysytetään sinulla, ja sinä saat sen, niin pian kuin tulet tuntemaan, että valta on taivaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, '{4:24} Sentähden, kuningas, kelvatkoon sinulle minun neuvoni: kirvoita synnit itsestäsi almuilla ja pahat tekosi vaivaisia armahtamalla; ehkäpä silloin onnesi kestäisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, '{4:25} Tämä kaikki kohtasi kuningas Nebukadnessaria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, '{4:26} Kaksitoista kuukautta tämän jälkeen, kun kuningas oli kävelemässä kuninkaallisen palatsinsa katolla Baabelissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, '{4:27} hän puhkesi puhumaan sanoen: \"Eikö tämä ole se suuri Baabel, jonka minä väkevällä voimallani olen rakentanut kuninkaalliseksi linnaksi, valtasuuruuteni kunniaksi!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, '{4:28} Vielä oli sana kuninkaan suussa, kun taivaasta tuli ääni: \"Sinulle, kuningas Nebukadnessar, julistetaan: Sinun valtakuntasi on otettu sinulta pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, '{4:29} Sinut ajetaan pois ihmisten seasta, ja kedon eläinten parissa on sinun asuinpaikkasi oleva; sinä joudut syömään ruohoa niinkuin raavaat, ja niin on sinulta kuluva seitsemän aikaa, kunnes tulet tuntemaan, että Korkein hallitsee ihmisten valtakuntaa ja antaa sen, kenelle hän tahtoo.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, '{4:30} Sillä hetkellä se sana toteutui Nebukadnessarissa: hänet ajettiin pois ihmisten seasta, ja hän söi ruohoa niinkuin raavaat, ja hänen ruumiinsa kastui taivaan kasteesta, kunnes hänen hiuksensa kasvoivat pitkiksi kuin kotkan sulat ja hänen kyntensä kuin lintujen kynnet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, '{4:31} \"Mutta sen ajan kuluttua minä, Nebukadnessar, nostin silmäni taivasta kohti, ja minun järkeni palasi. Ja minä kiitin Korkeinta, minä ylistin ja kunnioitin häntä, joka elää iankaikkisesti, jonka hallitus on iankaikkinen hallitus ja jonka valtakunta pysyy suvusta sukuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, '{4:32} Kaikki maan asukkaat ovat tyhjänveroiset; ja hän tekee, niinkuin hän tahtoo, taivaan joukoille ja maan asukkaille, eikä ole sitä, joka pidättää hänen kätensä ja sanoo hänelle: \'Mitäs teet?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, '{4:33} Siihen aikaan palasi minun järkeni, ja palasi minun valtasuuruuteni ja loistoni, minun valtakuntani kunniaksi. Ja minun hallitusmieheni ja ylimykseni etsivät minut, ja minut pantiin jälleen hallitsemaan valtakuntaani, ja minun valtani lisääntyi ylenpalttisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, '{4:34} Nyt minä, Nebukadnessar, kiitän, ylistän ja kunnioitan taivaan kuningasta; sillä kaikki hänen työnsä ovat totiset ja hänen tiensä oikeat. Ja hän voi nöyryyttää ne, jotka ylpeydessä vaeltavat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Kuningas Belsassar laittoi suuret pidot tuhannelle ylimyksellensä, ja hän joi viiniä näiden tuhannen edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Kun viini oli makeimmillaan, käski Belsassar tuoda ne kulta-ja hopea-astiat, jotka hänen isänsä Nebukadnessar oli ottanut Jerusalemin temppelistä, että kuningas ja hänen ylimyksensä, hänen puolisonsa ja sivuvaimonsa joisivat niistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Silloin tuotiin ne kulta-astiat, jotka oli otettu temppelistä, Jumalan huoneesta, Jerusalemista, ja niistä joivat kuningas ja hänen ylimyksensä, hänen puolisonsa ja sivuvaimonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'He joivat viiniä ja ylistivät kultaisia ja hopeisia, vaskisia, rautaisia, puisia ja kivisiä jumalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Sillä hetkellä ilmestyivät ihmiskäden sormet ja kirjoittivat kuninkaan palatsin kalkitulle seinälle, vastapäätä lampunjalkaa, ja kuningas näki käden, joka kirjoitti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Silloin kuninkaan kasvot kalpenivat, ja hänen ajatuksensa peljästyttivät hänet; hänen lanteittensa nivelet herposivat, ja hänen polvensa tutisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Kuningas huusi kovalla äänellä ja käski tuoda noidat, kaldealaiset ja tähtienselittäjät. Kuningas lausui ja sanoi Baabelin tietäjille: \"Kuka ikinä voi lukea tämän kirjoituksen ja ilmoittaa minulle sen selityksen, hänet puetaan purppuraan, ja hänen kaulaansa pannaan kultakäädyt, ja hän on oleva yksi valtakunnan kolmesta valtamiehestä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Silloin tulivat kaikki kuninkaan viisaat, mutta he eivät voineet lukea kirjoitusta eivätkä ilmoittaa kuninkaalle sen selitystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Kuningas Belsassar peljästyi silloin suuresti, ja hänen kasvonsa kalpenivat, ja hänen ylimyksensä tyrmistyivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Kuninkaan äiti tuli kuninkaan ja hänen ylimystensä puheen tähden pitohuoneeseen. Kuninkaan äiti lausui ja sanoi: \"Eläköön kuningas iankaikkisesti! Älkööt sinun ajatuksesi peljättäkö sinua, älköötkä kasvosi kalvetko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Sinun valtakunnassasi on mies, jossa on pyhien jumalien henki ja jolla sinun isäsi päivinä havaittiin olevan valistus ja ymmärrys ynnä viisaus, samankaltainen kuin jumalien; hänet asetti isäsi, kuningas Nebukadnessar, tietäjäin, noitien, kaldealaisten ja tähtienselittäjäin päämieheksi-sinun isäsi, kuningas-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'sentähden, että erinomainen henki ja tieto ynnä myös taito selittää unia, arvata arvoituksia ja ratkaista ongelmia havaittiin juuri hänessä, Danielissa, jolle kuningas oli antanut nimen Beltsassar. Kutsuttakoon nyt Daniel, niin hän ilmoittaa selityksen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Silloin Daniel tuotiin kuninkaan eteen. Kuningas lausui ja sanoi Danielille: \"Oletko sinä Daniel, joka on niitä juutalaisia pakkosiirtolaisia, mitkä minun isäni, kuningas, on tuonut Juudasta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Minä olen kuullut sinusta, että sinussa on jumalien henki ja että sinussa on havaittu valistus, taito ja erinomainen viisaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Ja nyt tuotiin minun eteeni viisaat ja noidat lukemaan tätä kirjoitusta ja ilmoittamaan minulle sen selitys, mutta he eivät voineet sen selitystä ilmoittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Mutta sinun minä olen kuullut voivan antaa selityksiä ja ratkaista ongelmia. Nyt siis, jos voit lukea kirjoituksen ja ilmoittaa minulle sen selityksen, niin sinut puetaan purppuraan, ja kultakäädyt pannaan sinun kaulaasi, ja sinä olet oleva yksi valtakunnan kolmesta valtamiehestä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Silloin Daniel vastasi ja sanoi kuninkaalle: \"Lahjasi pidä itse, ja antimesi anna toiselle. Mutta kirjoituksen minä luen kuninkaalle ja ilmoitan hänelle sen selityksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Sinä kuningas! Korkein Jumala antoi sinun isällesi Nebukadnessarille kuninkuuden, voiman, kunnian ja valtasuuruuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Ja sen voiman tähden, jonka hän oli hänelle antanut, vapisivat kaikki kansat, kansakunnat ja kielet ja pelkäsivät hänen edessään. Hän tappoi, kenen hän tahtoi, hän jätti henkiin, kenen hän tahtoi, hän ylensi, kenen hän tahtoi, hän alensi, kenen hän tahtoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Mutta kun hänen sydämensä paisui ja hänen henkensä kävi korskeaksi ja ylpeäksi, syöstiin hänet kuninkaalliselta valtaistuimeltansa, ja hänen kunniansa otettiin häneltä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Hänet ajettiin pois ihmisten seasta, ja hänen sydämensä tuli eläinten sydämen kaltaiseksi; hänen asuntonsa oli villiaasien parissa, ja hän joutui syömään ruohoa niinkuin raavaat; hänen ruumiinsa kastui taivaan kasteesta, kunnes hän tuli tuntemaan, että korkein Jumala hallitsee ihmisten valtakuntaa ja asettaa sen päämieheksi, kenen hän tahtoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Mutta sinä, hänen poikansa Belsassar, et ole nöyryyttänyt sydäntäsi, vaikka tämän kaiken tiesit;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'vaan sinä olet korottanut itsesi taivaan Herraa vastaan: hänen huoneensa astiat on tuotu sinun eteesi, ja sinä ja sinun ylimyksesi, sinun puolisosi ja sivuvaimosi olette juoneet niistä viiniä, ja sinä olet ylistänyt hopeisia ja kultaisia, vaskisia, rautaisia, puisia ja kivisiä jumalia, jotka eivät näe, eivät kuule eivätkä mitään tiedä. Mutta sitä Jumalaa, jonka kädessä on sinun henkesi ja kaikki sinun tiesi, sinä et ole kunnioittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Sentähden on tämä käsi lähetetty hänen tyköänsä ja tämä kirjoitus kirjoitettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Ja tämä on kirjoitus, joka on tuonne kirjoitettu: \'Mene, mene, tekel, ufarsin\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Ja tämä on sen selitys: mene merkitsee: Jumala on laskenut sinun valtakuntasi luvun ja on tehnyt siitä lopun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tekel: sinut on vaa\'alla punnittu ja köykäiseksi havaittu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres: sinun valtakuntasi on pirstottu ja annettu meedialaisille ja persialaisille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Silloin Belsassar antoi käskyn, että Daniel oli puettava purppuraan ja kultakäädyt pantava hänen kaulaansa ja julistettava, että hän oli oleva yksi valtakunnan kolmesta valtamiehestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Samana yönä tapettiin Belsassar, kaldealaisten kuningas,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'ja Daarejaves, meedialainen, sai haltuunsa valtakunnan ollessaan noin kuudenkymmenen kahden vuoden ikäinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Daarejaves näki hyväksi asettaa valtakuntaansa sata kaksikymmentä satraappia, että heitä olisi kaikkialla valtakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Ja heitä ylempänä oli kolme valtaherraa, joista Daniel oli yksi. Heille tuli satraappien tehdä tili, ettei kuningas kärsisi vahinkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Mutta Daniel oli etevämpi muita valtaherroja sekä satraappeja, sillä hänessä oli erinomainen henki; ja kuningas aikoi asettaa hänet koko valtakunnan päämieheksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Silloin toiset valtaherrat sekä satraapit etsivät Danielia vastaan syytä valtakunnan hallinnossa. Mutta he eivät voineet löytää mitään syytä eikä rikkomusta, sillä hän oli uskollinen, eikä hänestä laiminlyöntiä eikä rikkomusta löydetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Silloin nämä miehet sanoivat: \"Me emme löydä tuossa Danielissa mitään syytä-ellemme löydä sitä hänen jumalanpalveluksessaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Senjälkeen nämä valtaherrat ja satraapit riensivät kiiruusti kuninkaan tykö ja sanoivat hänelle näin: \"Kuningas Daarejaves eläköön iankaikkisesti!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Kaikki kuninkaalliset valtaherrat, maaherrat, satraapit, hallitusmiehet ja käskynhaltijat ovat keskenänsä neuvotelleet, että olisi annettava kuninkaallinen julistus ja vahvistettava kielto, että kuka ikinä kolmenkymmenen päivän kuluessa rukoilee jotakin yhdeltäkään jumalalta tai ihmiseltä, paitsi sinulta, kuningas, se heitettäköön jalopeurain luolaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Nyt, kuningas! Säädä kielto ja kirjoita kirjoitus, jota meedialaisten ja persialaisten peruuttamattoman lain mukaan ei voida muuttaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Niin kuningas Daarejaves kirjoitti kirjoituksen ja kiellon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Niin pian kuin Daniel oli saanut tietää, että kirjoitus oli kirjoitettu, meni hän taloonsa, jonka yläsalin ikkunat olivat avatut Jerusalemiin päin. Ja hän lankesi kolmena hetkenä päivässä polvillensa, rukoili ja kiitti Jumalaansa, aivan niinkuin hän ennenkin oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Silloin nuo miehet riensivät kiiruusti sinne ja tapasivat Danielin rukoilemasta ja avuksi huutamasta Jumalaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Sitten he astuivat kuninkaan eteen ja muistuttivat kuninkaan kiellosta: \"Etkö ole kirjoittanut kieltoa, että kuka ikinä kolmenkymmenen päivän kuluessa rukoilee jotakin yhdeltäkään jumalalta tai ihmiseltä, paitsi sinulta, kuningas, se heitettäköön jalopeurain luolaan?\" Kuningas vastasi ja sanoi: \"Kielto on luja, meedialaisten ja persialaisten peruuttamattoman lain mukaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Silloin he vastasivat ja sanoivat kuninkaalle: \"Daniel, joka on juutalaisia pakkosiirtolaisia, ei välitä sinusta, kuningas, eikä kiellosta, jonka olet kirjoittanut, vaan kolmena hetkenä päivässä hän toimittaa rukouksensa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Mutta kun kuningas sen kuuli, tuli hän sangen murheelliseksi, ja hän mietti, miten voisi pelastaa Danielin; auringon laskuun asti hän vaivasi itseään vapauttaaksensa hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Silloin ne miehet riensivät kiiruusti kuninkaan tykö ja sanoivat kuninkaalle: \"Tiedä, kuningas, meedialaisten ja persialaisten laki on, ettei mitään kuninkaan vahvistamaa kieltoa tai julistusta peruuteta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Silloin kuningas käski tuoda Danielin ja heittää hänet jalopeurain luolaan. Ja kuningas puhui Danielille ja sanoi: \"Sinun Jumalasi, jota sinä lakkaamatta palvelet, pelastakoon sinut\". Sitten tuotiin kivi ja pantiin luolan suulle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'ja kuningas sinetöi sen omallaan ja ylimystensä sineteillä, ettei Danielin asiassa muutosta tapahtuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Sitten kuningas meni palatsiinsa ja vietti yönsä paastoten eikä sallinut tuoda eteensä naisia, ja hänen unensa pakeni häneltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Aamun sarastaessa kuningas sitten nousi ja meni kiiruusti jalopeurain luolalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Ja lähestyessään luolaa hän huusi Danielille murheellisella äänellä, ja kuningas lausui ja sanoi Danielille: \"Daniel, sinä elävän Jumalan palvelija, onko sinun Jumalasi, jota lakkaamatta palvelet, voinut pelastaa sinut jalopeuroilta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Silloin Daniel vastasi kuninkaalle: \"Kuningas eläköön iankaikkisesti!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Minun Jumalani on lähettänyt enkelinsä ja sulkenut jalopeurain kidat, niin etteivät ne ole minua vahingoittaneet, sillä minut on havaittu nuhteettomaksi hänen edessänsä, enkä minä ole sinuakaan vastaan, kuningas, rikosta tehnyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Silloin kuningas ihastui suuresti ja käski ottaa Danielin ylös luolasta. Ja kun Daniel oli otettu ylös luolasta, ei hänessä havaittu mitään vammaa; sillä hän oli turvannut Jumalaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Ja kuningas käski tuoda ne miehet, jotka olivat syyttäneet Danielia, ja heittää heidät lapsineen ja vaimoineen jalopeurain luolaan; eivätkä he ehtineet luolan pohjaan, ennenkuin jalopeurat hyökkäsivät heidän kimppuunsa ja murskasivat kaikki heidän luunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Sitten kuningas Daarejaves kirjoitti kaikille kansoille, kansakunnille ja kielille, mitä koko maan päällä asuu: \"Suuri olkoon teidän rauhanne!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Minä olen antanut käskyn, että minun valtakuntani koko valtapiirissä vavistakoon ja peljättäköön Danielin Jumalaa. Sillä hän on elävä Jumala ja pysyy iankaikkisesti. Hänen valtakuntansa ei häviä, eikä hänen herrautensa lopu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Hän pelastaa ja vapahtaa, hän tekee tunnustekoja ja ihmeitä taivaassa ja maan päällä, hän, joka pelasti Danielin jalopeurain kynsistä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Ja tämä Daniel oli korkeassa arvossa ja kunniassa Daarejaveksen valtakunnassa sekä persialaisen Kooreksen valtakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Belsassarin, Baabelin kuninkaan, ensimmäisenä hallitusvuotena Daniel näki unen, päänsä näyn, vuoteessansa. Sitten hän kirjoitti tämän unen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Kertomuksen alku on tämä: Daniel lausui ja sanoi: Minä näin yöllä näyssäni, ja katso, taivaan neljä tuulta kuohutti suurta merta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Ja merestä nousi neljä suurta petoa, kukin erilainen kuin toinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Ensimmäinen oli kuin leijona, mutta sillä oli kotkan siivet. Minun sitä katsellessani reväistiin siltä siivet, ja se nostettiin maasta pystyyn ja asetettiin kahdelle jalalle niinkuin ihminen, ja sille annettiin ihmisen sydän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Ja katso, oli toinen peto, joka oli karhun näköinen. Se nostettiin toiselle kyljellensä, ja sillä oli suussa kolme kylkiluuta, hammasten välissä; ja sille sanottiin näin: \"Nouse ja syö paljon lihaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Tämän jälkeen minä näin, ja katso, oli taas toinen peto, pantterin kaltainen, ja sen selässä oli neljä linnunsiipeä. Sillä pedolla oli neljä päätä, ja sille annettiin valta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Sen jälkeen minä näin yöllisessä näyssäni, ja katso, oli neljäs peto, kauhea, hirmuinen ja ylen väkevä; sillä oli suuret rautaiset hampaat, ja se söi ja murskasi ja tallasi tähteet jalkoihinsa. Se oli erilainen kuin kaikki edelliset pedot, ja sillä oli kymmenen sarvea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Minä tarkkasin sarvea, ja katso, eräs muu pieni sarvi puhkesi niiden välistä, ja kolme edellisistä sarvista reväistiin pois sen edestä. Ja katso, sillä sarvella oli silmät kuin ihmisen silmät, ja suu, joka herjaten puhui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Minun sitä katsellessani valtaistuimet asetettiin, ja Vanhaikäinen istuutui. Hänen vaatteensa olivat valkeat kuin lumi ja hänen päänsä hiukset kuin puhdas villa. Hänen valtaistuimensa oli tulen liekkejä, ja sen pyörät olivat palavaa tulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Tulivirta vuoti, se kävi ulos hänestä; tuhannen tuhatta palveli häntä, ja kymmenen tuhatta kertaa kymmenen tuhatta seisoi hänen edessänsä. Oikeus istui tuomiolle, ja kirjat avattiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Minä katselin, ja silloin, niiden herjaavien sanojen tähden, joita sarvi puhui, minun katsellessani peto tapettiin, ja sen ruumis hävitettiin ja heitettiin tuleen palamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Ja muiltakin pedoilta otettiin valta pois; niiden elämän pituus oli määrätty aikaa ja hetkeä myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Minä näin yöllisessä näyssä, ja katso, taivaan pilvissä tuli Ihmisen Pojan kaltainen; ja hän saapui Vanhaikäisen tykö, ja hänet saatettiin tämän eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Ja hänelle annettiin valta, kunnia ja valtakunta, ja kaikki kansat, kansakunnat ja kielet palvelivat häntä. Hänen valtansa on iankaikkinen valta, joka ei lakkaa, ja hänen valtakuntansa on valtakunta, joka ei häviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Minä, Daniel, tunsin henkeni tulevan murheelliseksi ruumiissani, ja minun näkemäni näyt peljättivät minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Minä lähestyin yhtä siellä seisovista ja pyysin häneltä varmaa tietoa kaikista näistä asioista. Niin hän vastasi minulle ja ilmoitti minulle niiden selityksen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, '\"Nuo suuret pedot, joita on neljä, ovat neljä kuningasta, jotka nousevat maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Mutta Korkeimman pyhät saavat valtakunnan ja omistavat valtakunnan iankaikkisesti-iankaikkisesta iankaikkiseen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Senjälkeen minä tahdoin saada varmuuden neljännestä pedosta, joka oli erilainen kuin kaikki muut ja ylen hirmuinen; jolla oli rautaiset hampaat ja vaskiset kynnet, joka söi ja murskasi ja tallasi tähteet jalkoihinsa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'sekä pedon pään kymmenestä sarvesta ynnä siitä sarvesta, joka puhkesi ja jonka edestä kolme putosi; jolla sarvella oli silmät ja herjauksia puhuva suu ja joka näytti suuremmalta kuin ne muut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'se sarvi, jonka minä näin sotivan pyhiä vastaan ja voittavan heidät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'siihen asti kunnes Vanhaikäinen tuli ja oikeus annettiin Korkeimman pyhille ja aika joutui ja pyhät saivat omaksensa valtakunnan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Hän vastasi näin: \"Neljäs peto on neljäs valtakunta, joka syntyy maan päälle, erilainen kuin kaikki muut valtakunnat. Se syö kaiken maan ja tallaa ja murskaa sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Ja ne kymmenen sarvea ovat kymmenen kuningasta, jotka nousevat siitä valtakunnasta. Ja heidän jälkeensä nousee eräs muu, ja hän on erilainen kuin edelliset, ja hän kukistaa kolme kuningasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Hän puhuu sanoja Korkeinta vastaan ja hävittää Korkeimman pyhiä. Hän pyrkii muuttamaan ajat ja lain, ja ne annetaan hänen käteensä ajaksi ja kahdeksi ajaksi ja puoleksi ajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Sitten oikeus istuu tuomiolle, ja hänen valtansa otetaan pois ja hävitetään ja tuhotaan loppuun asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Ja valtakunta ja valta ja valtakuntien voima kaiken taivaan alla annetaan Korkeimman pyhien kansalle. Hänen valtakuntansa on iankaikkinen valtakunta, ja kaikki vallat palvelevat häntä ja ovat hänelle alamaiset.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Tähän loppuu kertomus. Minua, Danielia, peljättivät minun ajatukseni suuresti, ja minun kasvoni kalpenivat, ja minä kätkin asian sydämeeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Kuningas Belsassarin kolmantena hallitusvuotena näin minä, Daniel, näyn, senjälkeen kuin minulla jo ennen oli ollut näky.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Kun minä näyssä katselin, havaitsin minä olevani Suusanin linnassa, Eelamin maakunnassa; ja kun minä näyssä katselin, olin minä Uulai-joen rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Minä nostin silmäni ja katsoin. Ja katso, oinas seisoi päin jokea, ja sillä oli kaksi sarvea; ja sarvet olivat korkeat, ja toinen oli toista korkeampi; ja korkeampi puhkesi esiin myöhemmin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Minä näin oinaan puskevan länteen, pohjoiseen ja etelään päin, eikä yksikään eläin kestänyt sen edessä, eikä kukaan voinut pelastaa sen vallasta. Se teki, mitä tahtoi; ja se tuli suureksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Sitten minä tarkkasin, ja katso: tuli kauris päivän laskun puolelta, kulki koko maan ylitse eikä maata koskettanut; ja kauriilla oli keskellä otsaa uhkea sarvi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Ja se tuli aivan sen kaksisarvisen oinaan luokse, jonka minä olin nähnyt seisovan päin jokea, ja karkasi sen kimppuun vihansa väessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Ja minä näin sen käyvän kiinni oinaaseen ja kiukuissaan puskevan oinasta ja murskaavan sen molemmat sarvet. Eikä oinaalla ollut voimaa kestää sen edessä, vaan kauris heitti sen maahan ja tallasi sitä; eikä ollut ketään, joka olisi voinut pelastaa oinaan sen vallasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Ja kauris tuli ylen suureksi; mutta kun se oli väkevimmillään, särkyi suuri sarvi, ja sen sijalle kasvoi neljä uhkeata sarvea, taivaan neljää tuulta kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Ja yhdestä niistä puhkesi esiin sarvi, alussa vähäpätöinen. Se kasvoi suuresti etelään päin ja itään päin ja Ihanaan maahan päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Ja se kasvoi taivaan sotajoukkoon asti ja pudotti maahan osan siitä sotajoukosta ja tähdistä ja tallasi niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Hän ylpeili sotajoukon ruhtinastakin vastaan, ja tältä otettiin pois jokapäiväinen uhri, ja hänen pyhäkkönsä paikka kukistettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Myös sotajoukko jokapäiväisen uhrin lisäksi annettiin rikollisesti alttiiksi tuholle. Se sarvi heitti totuuden maahan, ja mitä se teki, siinä se menestyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Sitten minä kuulin yhden pyhän puhuvan, ja toinen pyhä sanoi sille, joka puhui: \"Kuinka pitkää aikaa tarkoittaa näky jokapäiväisestä uhrista ja kauhistavasta rikoksesta: pyhäkön ja sotajoukon alttiiksi antamisesta tallattavaksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Ja hän sanoi minulle: \"Kahtatuhatta kolmeasataa iltaa ja aamua; sitten pyhäkkö asetetaan jälleen oikeuteensa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Kun minä, Daniel, olin nähnyt tämän näyn ja koetin sitä ymmärtää, niin katso, minun edessäni seisoi miehen muotoinen olento.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Ja minä kuulin ihmisen äänen Uulain keskeltä, ja se huusi ja sanoi: \"Gabriel, selitä tälle se näky!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Silloin hän tuli aivan lähelle sitä paikkaa, jossa minä seisoin; ja hänen tullessansa minut valtasi pelko, ja minä lankesin kasvoilleni. Ja hän sanoi minulle: \"Tarkkaa, ihmislapsi, sillä näky tarkoittaa lopun aikaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Ja kun hän puhui minulle, olin minä horroksissa, kasvot maata vasten; mutta hän tarttui minuun ja nosti minut seisomaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Sitten hän sanoi: \"Katso, minä ilmoitan sinulle, mitä on tapahtuva viimeisenä vihan aikana; sillä lopun aikaa tämä tarkoittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Kaksisarvinen oinas, jonka sinä näit, on: Meedian ja Persian kuninkaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Ja kauris on Jaavanin kuningas, ja suuri sarvi, joka sillä oli keskellä otsaa, on ensimmäinen kuningas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Ja että se särkyi ja neljä nousi sen sijalle, se on: neljä valtakuntaa nousee siitä kansasta, ei kuitenkaan niin väkevää kuin hän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Ja heidän valtansa lopulla, kun luopiot ovat täyttäneet syntiensä mitan, nousee kuningas, kasvoilta röyhkeä ja juonissa taitava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Ja väkevä on hänen voimansa, vaikka ei tosin hänen omasta voimastaan, ja ihmeellisen paljon hän saa aikaan hävitystä; ja hän menestyy siinä, mitä hän tekee, ja hän tuottaa turmion väkeville ja pyhien kansalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Ja hänen oveluutensa tähden onnistuu petos hänen kädessään. Hän hautoo suuria sydämessään, ja keskellä rauhaa hän tuottaa turmion monille. Ruhtinasten ruhtinastakin vastaan hän nousee, mutta ilman ihmiskättä hänet muserretaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Ja näky illoista ja aamuista, josta oli puhe, on tosi. Mutta sinä lukitse näky, sillä se tarkoittaa kaukaista aikaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Ja minä, Daniel, olin raukea ja sairastin jonkin aikaa. Sitten minä nousin ja toimitin palvelusta kuninkaan tykönä; ja minä olin hämmästyksissäni näyn tähden enkä sitä ymmärtänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Daarejaveksen, Ahasveroksen pojan, ensimmäisenä hallitusvuotena, hänen, joka oli meedialaista sukua ja oli tullut kaldealaisten valtakunnan kuninkaaksi-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'hänen ensimmäisenä hallitusvuotenaan, minä, Daniel, kirjoituksista huomasin vuosien luvun, josta Herran sana oli tullut profeetta Jeremialle, että Jerusalem oli oleva raunioina seitsemänkymmentä vuotta. 9:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Ja minä käänsin kasvoni Herran Jumalan puoleen hartaassa rukouksessa ja anomisessa, paastossa, säkissä ja tuhassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Minä rukoilin Herraa, Jumalaani, tunnustin ja sanoin: \"Oi Herra, sinä suuri ja peljättävä Jumala, joka pidät liiton ja säilytät laupeuden niille, jotka sinua rakastavat ja noudattavat sinun käskyjäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Me olemme syntiä tehneet, olemme väärin tehneet, olleet jumalattomat ja uppiniskaiset; me olemme poikenneet pois sinun käskyistäsi ja oikeuksistasi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'emmekä ole kuulleet sinun palvelijoitasi, profeettoja, jotka puhuivat sinun nimessäsi kuninkaillemme, ruhtinaillemme ja isillemme ja kaikelle maan kansalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Sinun, Herra, on vanhurskaus, mutta meidän on häpeä, niinkuin se on tänä päivänä Juudan miesten ja Jerusalemin asukasten ja koko Israelin, läheisten ja kaukaisten, kaikissa maissa, joihin sinä olet heidät karkoittanut heidän uskottomuutensa tähden, jota he ovat sinulle osoittaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Herra, meidän on häpeä, meidän kuninkaittemme, ruhtinaittemme ja isiemme, koska me olemme tehneet syntiä sinua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Herran, meidän Jumalamme, on armo ja anteeksiantamus, sillä me olemme olleet hänelle uppiniskaiset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'me emme ole kuulleet Herran, meidän Jumalamme, ääntä emmekä vaeltaneet hänen laissansa, jonka hän asetti meidän eteemme palvelijainsa, profeettain, kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Vaan koko Israel rikkoi sinun lakisi ja poikkesi pois eikä kuullut sinun ääntäsi, ja niin vuodatettiin meidän päällemme se kirous ja vala, joka on kirjoitettu Mooseksen, Jumalan palvelijan, laissa; sillä me olimme tehneet syntiä häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Ja hän toteutti sanansa, jonka hän on puhunut meitä ja meidän tuomareitamme vastaan, jotka meitä tuomitsivat, ja antoi meidän päällemme tulla niin suuren onnettomuuden, ettei senkaltaista ole tapahtunut koko taivaan alla, kuin Jerusalemissa tapahtui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Niinkuin on kirjoitettu Mooseksen laissa, niin tuli kaikki tämä onnettomuus meidän päällemme. Mutta me emme koettaneet lepyttää Herraa, meidän Jumalaamme, niin että olisimme kääntyneet pois synneistämme ja ottaneet vaarin sinun totuudestasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Sentähden Herra valvoi ja antoi tämän onnettomuuden tulla meidän päällemme; sillä Herra, meidän Jumalamme, on vanhurskas kaikissa töissänsä, jotka hän tekee, mutta me emme ole kuulleet hänen ääntänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Ja nyt, Herra, meidän Jumalamme, joka toit kansasi pois Egyptin maasta väkevällä kädellä ja teit itsellesi nimen, niinkuin se vielä tänä päivänä on: me olemme syntiä tehneet ja olleet jumalattomat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Herra, kaiken vanhurskautesi tähden, kääntyköön sinun vihasi ja kiivastuksesi pois sinun kaupungistasi Jerusalemista, sinun pyhästä vuorestasi; sillä meidän syntiemme tähden ja meidän isäimme pahojen tekojen tähden on Jerusalem ja sinun kansasi tullut kaikkien häväistäväksi, jotka meidän ympärillämme ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Ja nyt, meidän Jumalamme, kuule palvelijasi rukous ja hänen anomisensa ja valista kasvosi pyhäkkösi ylitse, joka on autiona; Herran tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Minun Jumalani, kallista korvasi ja kuule, avaa silmäsi ja katso meidän hävitystämme ja sitä kaupunkia, joka on otettu sinun nimiisi; sillä me annamme rukouksiemme langeta sinun eteesi, emme omaan vanhurskauteemme, vaan sinun suureen armoosi luottaen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'Herra, kuule, Herra, anna anteeksi, Herra, huomaa ja tee tekosi itsesi tähden, älä viivyttele, minun Jumalani; sillä sinun kaupunkisi ja sinun kansasi ovat sinun nimiisi otetut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Ja vielä minä puhuin ja rukoilin ja tunnustin syntini ja kansani Israelin synnit ja annoin rukoukseni langeta Herran, Jumalani, eteen minun Jumalani pyhän vuoren puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Ja kun minä vielä puhuin rukouksessa, tuli se mies, Gabriel, jonka minä olin nähnyt ennen näyssä, kiiruusti kiitäen minun tyköni ehtoouhrin aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Ja hän opetti minua, puhui minulle ja sanoi: \"Daniel, nyt minä olen lähtenyt neuvomaan sinua ymmärrykseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Kun sinä aloit rukoilla, lähti liikkeelle sana, ja minä olen tullut sitä ilmoittamaan; sillä sinä olet otollinen. Käsitä siis se sana ja ymmärrä näky.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Seitsemänkymmentä viikkoa on säädetty sinun kansallesi ja pyhälle kaupungillesi; silloin luopumus päättyy, ja synti sinetillä lukitaan, ja pahat teot sovitetaan, ja iankaikkinen vanhurskaus tuodaan, ja näky ja profeetta sinetillä vahvistetaan, ja kaikkeinpyhin voidellaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Ja tiedä ja käsitä: siitä ajasta, jolloin tuli se sana, että Jerusalem on jälleen rakennettava, voideltuun, ruhtinaaseen, asti, on kuluva seitsemän vuosiviikkoa; ja kuusikymmentäkaksi vuosiviikkoa, niin se jälleen rakennetaan toreinensa ja vallihautoinensa, mutta keskellä ahtaita aikoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Ja kuudenkymmenen kahden vuosiviikon mentyä tuhotaan voideltu, eikä häneltä jää ketään. Ja kaupungin ja pyhäkön hävittää hyökkäävän ruhtinaan väki, mutta hän itse saa loppunsa tulvassa. Ja loppuun asti on oleva sota: hävitys on säädetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Ja hän tekee liiton raskaaksi monille yhden vuosiviikon ajaksi, ja puoleksi vuosiviikoksi hän lakkauttaa teurasuhrin ja ruokauhrin; ja hävittäjä tulee kauhistuksen siivillä. Tämä loppuu vasta, kun säädetty tuomio vuodatetaan hävittäjän ylitse.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Persian kuninkaan Kooreksen kolmantena hallitusvuotena ilmoitettiin sana Danielille, jota kutsuttiin Beltsassariksi; ja se sana on totuus ja merkitsee suurta vaivaa. Ja hän ymmärsi sanan, ja hän käsitti näyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'Niinä päivinä minä, Daniel, murehdin kolmen viikon päivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Herkullista ruokaa minä en syönyt, ei liha eikä viini tullut minun suuhuni, enkä minä voidellut itseäni öljyllä, ennenkuin kolmen viikon päivät olivat loppuun kuluneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Ensimmäisen kuun kahdentenakymmenentenä neljäntenä päivänä minä olin suuren virran, Hiddekelin, rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Minä nostin silmäni ja näin, ja katso: oli eräs mies, puettuna pellavavaatteisiin ja kupeet vyötettyinä Uufaan kullalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Hänen ruumiinsa oli kuin krysoliitti, hänen kasvonsa olivat kuin salaman leimaus, hänen silmänsä kuin tulisoihdut, hänen käsivartensa ja jalkansa kuin kiiltävän vasken välke; ja hänen sanojensa ääni oli kuin suuren kansanjoukon pauhina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Ja minä, Daniel, yksin näin sen näyn, mutta miehet, jotka olivat minun kanssani, eivät näkyä nähneet; kuitenkin valtasi heidät suuri pelko, ja he pakenivat ja lymysivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Ja minä jäin yksin. Ja kun minä näin tämän suuren näyn, meni minulta kaikki voima; minun verevä muotoni muuttui kaamean näköiseksi, eikä minussa ollut voimaa mihinkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Ja minä kuulin hänen sanainsa äänen; ja kuullessani hänen sanainsa äänen minä vaivuin horroksiin kasvoilleni, kasvot maata vasten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Ja katso, käsi kosketti minua ja ravisti minut hereille, polvieni ja kätteni varaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Ja hän sanoi minulle: \"Daniel, sinä otollinen mies, ota vaari niistä sanoista, jotka minä sinulle puhun, ja nouse seisomaan, sillä minut on nyt lähetetty sinun tykösi\". Ja hänen puhuessansa minulle tämän sanan minä nousin vavisten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Ja hän sanoi minulle: \"Älä pelkää, Daniel, sillä ensimmäisestä päivästä asti, jona sinä taivutit sydämesi ymmärrykseen ja nöyryyteen Jumalasi edessä, ovat sinun sanasi tulleet kuulluiksi; ja sinun sanojesi tähden minä olen tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Persian valtakunnan enkeliruhtinas seisoi vastustamassa minua kaksikymmentäyksi päivää, mutta katso, Miikael, yksi ensimmäisistä enkeliruhtinaista, tuli minun avukseni, sillä minä olin jäänyt yksin sinne, Persian kuningasten tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Ja minä tulin opettamaan sinulle, mitä on tapahtuva sinun kansallesi päivien lopulla; sillä vielä tämäkin näky koskee niitä päiviä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Ja hänen näitä minulle puhuessansa minä käänsin kasvoni maahan päin ja olin ääneti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Ja katso, olento, ihmislasten muotoinen, kosketti minun huuliani; silloin minä avasin suuni ja puhuin ja sanoin edessäni seisovalle: \"Herrani, nähdessäni näyn valtasi minut tuska, ja minulta meni kaikki voima.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Ja kuinka voi herrani palvelija, tällainen kuin minä, puhutella sellaista, kuin minun herrani on? Sillä siitä asti ei minussa ole voimaa, tuskin enää henkeäkään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Silloin kosketti minua jälleen se ihmisen muotoinen ja vahvisti minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Ja hän sanoi: \"Älä pelkää, sinä otollinen mies, rauha olkoon sinulle. Vahvistu! Vahvistu!\" Ja hänen puhuessaan minulle minä vahvistuin ja sanoin: \"Puhukoon herrani, sillä sinä olet minua vahvistanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Ja hän sanoi: \"Tiedätkö, mitä varten minä olen tullut sinun tykösi? Nyt minä käyn jälleen sotimaan Persian enkeliruhtinasta vastaan, ja kun minä olen päässyt hänestä, niin katso: tulee Jaavanin enkeliruhtinas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Mutta minä ilmoitan sinulle, mitä on kirjoitettuna totuuden kirjassa. Eikä ole ketään muuta vahvistamassa minua heitä vastaan paitsi teidän enkeliruhtinaanne Miikael.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Ja minä seisoin meedialaisen Daarejaveksen ensimmäisenä hallitusvuotena häntä vahvistamassa ja suojelemassa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Ja nyt minä ilmoitan sinulle totuuden: Katso, vielä nousee kolme kuningasta Persiassa, ja neljäs rikastuu kaikkia muita rikkaammaksi. Ja kun hän on vahvistunut rikkaudessaan, panee hän kaiken liikkeelle Jaavanin valtakuntaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Sitten nousee sankarikuningas; hän hallitsee suurella vallalla ja tekee, mitä tahtoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Mutta juuri kun hän on noussut, hajoaa hänen valtakuntansa ja jakautuu neljään taivaan tuuleen. Se ei joudu hänen jälkeläisilleen eikä ole niin mahtava kuin hänen hallitessaan. Sillä hänen valtakuntansa kukistuu ja joutuu muille, ei heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Ja Etelän kuningas on voimistuva sekä yksi hänen ruhtinaistaan; tämä on voimistuva vielä enemmän kuin hän, ja hänen valtansa on oleva suuri valta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Ja vuosien kuluttua he tekevät keskenään liiton, ja Etelän kuninkaan tytär menee Pohjan kuninkaan tykö saadakseen aikaan sopimuksen. Mutta häneltä menee hänen käsivartensa voima; eikä pysy Pohjan kuningas, ei hänen käsivartensa. Ja tytär itse annetaan alttiiksi ja ne, jotka olivat hänet tuoneet, ja hänen isänsä ja se, joka häntä aikoinaan auttoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Sitten hänen juurtensa vesoista nousee eräs hänen sijaansa ja tulee sotajoukkoa vastaan, tulee Pohjan kuninkaan linnoitukseen ja tekee heille mielensä mukaan ja on väkevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Myöskin heidän jumalansa ja valetut kuvansa ja kallisarvoiset astiansa, hopeat ja kullat hän vie saaliinansa Egyptiin; sitten hän muutamia vuosia pysyy Pohjan kuninkaasta erillään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Tämä hyökkää Etelän kuninkaan valtakuntaan, mutta palajaa takaisin maahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Ja hänen poikansa varustautuvat ja kokoavat suuret sotavoimat. Ja hän hyökkää ja kuohuu ja tulvii, hän tulee toistamiseen ja tunkeutuu hänen linnoitukseensa asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Silloin Etelän kuningas kiukustuu ja lähtee sotimaan häntä vastaan, Pohjan kuningasta vastaan. Tämä nostattaa suuren joukon, mutta se joukko joutuu hänen valtaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Ja kun se joukko on raivattu pois, paisuu hänen sydämensä. Hän kaataa kymmeniä tuhansia, mutta ei ole kyllin vahva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Pohjan kuningas nostattaa jälleen joukon, entistä suuremman, ja muutaman ajan, muutaman vuoden kuluttua hyökkää suurella sotavoimalla ja runsailla varustuksilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Niinä aikoina monet nousevat Etelän kuningasta vastaan; ja sinun omasta kansastasi nousee väkivallan miehiä, että näky kävisi toteen, mutta he itse lankeavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Ja Pohjan kuningas hyökkää ja luo vallin ja valloittaa varustetun kaupungin. Eivät kestä Etelän käsivarret, ei sen valioväki, ei ole sillä voimaa seisoa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Ja hän, joka hyökkää sitä vastaan, tekee, mitä tahtoo, eikä kukaan voi seisoa häntä vastaan. Hän asettuu Ihanaan maahan, ja hävitys tulee hänen kätensä kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Ja nyt hän aikoo hyökätä valtakuntansa koko voimalla; mutta sopimus on hänellä mielessä, ja hän saa sen aikaan. Hän antaa hänelle yhden tyttäristään, tälle turmioksi. Mutta siitä ei tule pysyväistä eikä ole hänelle etua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Sitten hän kääntyy rantamaita vastaan ja ottaa valtaansa monet. Mutta eräs sotapäällikkö tekee hänen herjauksistaan lopun ja kostaa hänelle hänen herjauksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Silloin hän kääntyy oman maansa linnoituksiin, mutta kompastuu ja kaatuu, eikä häntä enää ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Ja hänen sijaansa nousee eräs, joka antaa veronvaatijan käydä läpi valtakunnan ihanimman maan. Mutta muutamien päivien kuluttua hänet tuhotaan, ei kuitenkaan vihan väellä eikä sodalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Ja hänen sijaansa nousee kelvoton, joka ei ollut saapa kuninkaan arvoa. Hän tulee keskellä rauhaa ja anastaa juonilla kuninkuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Ja sotajoukkojen tulva huuhtoutuu pois hänen edestänsä ja menee murskaksi, niin myös liiton ruhtinas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Siitä saakka kun liittoudutaan hänen kanssansa, hän harjoittaa petosta. Hän lähtee liikkeelle ja saa ylivallan vähällä väellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Keskellä rauhaa hän hyökkää maakunnan lihavimpiin seutuihin ja tekee, mitä eivät hänen isänsä eivätkä hänen isiensä isät olleet tehneet: ryöstösaalista ja tavaraa hän jakelee omilleen; ja linnoituksia vastaan hän hankitsee juoniansa, säädettyyn aikaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Ja hän panee liikkeelle voimansa ja rohkeutensa Etelän kuningasta vastaan, hyökäten suurella sotajoukolla. Mutta Etelän kuningas varustautuu sotaan suurella ja ylen väkevällä sotajoukolla. Hän ei kuitenkaan kestä, sillä häntä vastaan hankitaan juonia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Ja ne, jotka syövät hänen pöydästään, tuhoavat hänet, ja hänen sotajoukkonsa huuhdotaan pois, ja on paljon kaatuneita ja haavoitettuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Ja kumpaisellakin kuninkaalla on paha mielessä toistansa vastaan. Samassa pöydässä he puhuvat valhetta; mutta se ei onnistu; sillä säädetty aika ei ole vielä lopussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Silloin hän palaa maahansa paljoine tavaroineen, miettien hankkeita pyhää liittoa vastaan; hän toteuttaa ne ja palaa maahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Määräaikana hän hyökkää jälleen Etelämaahan, mutta tällä viimeisellä retkellä ei käy niinkuin ensimmäisellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Häntä vastaan hyökkäävät kittiläisten laivat, ja hän menettää rohkeutensa, kääntyy takaisin ja purkaa kiukkunsa pyhää liittoa vastaan. Kotiin palattuaan hän suo huomiota niille, jotka hylkäävät pyhän liiton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Hänen lähettämänsä sotajoukot nousevat ja häväisevät pyhäkön linnoituksineen, poistavat jokapäiväisen uhrin ja asettavat sinne hävityksen kauhistuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Ja liitonrikkojat hän viettelee luopumukseen houkutuksillaan, mutta niitten joukko, jotka tuntevat Jumalansa, pysyy lujana ja tekee tehtävänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Ja taidolliset kansan seassa opettavat monta, mutta heitä sorretaan miekalla, tulella, vankeudella ja ryöstöllä, jonkun aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Ja keskellä sortoa heille suodaan pieni menestys, ja monet liittyvät heihin teeskennellen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Ja taidollisista jotkut kompastuvat, että heidän joukkonsa koeteltaisiin, seulottaisiin ja puhdistettaisiin lopun ajaksi, sillä vielä kestää, ennenkuin määräaika on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Ja kuningas tekee, mitä hän tahtoo, ja korottaa itsensä ja uhittelee jokaista jumalaa, itse jumalien Jumalaa vastaan hän puhuu kauheita. Ja hän menestyy, kunnes vihan aika on lopussa; sillä mikä on säädetty, se tapahtuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Hän ei välitä isäinsä jumalista, ei naisten lempijumalasta, eikä hän välitä mistään muustakaan jumalasta, sillä hän uhittelee niitä kaikkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Mutta sen sijaan hän kunnioittaa linnoitusten jumalaa. Sitä jumalaa, jota hänen isänsä eivät tunteneet, hän kunnioittaa kullalla ja hopealla, kalliilla kivillä ja muilla kalleuksilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Ja tätä hän tekee vahvoille linnoituksille-hän vieraine jumalineen. Niille, jotka hän omikseen tuntee, hän osoittaa suurta kunniaa ja panee heidät monien hallitsijaksi ja jakaa heille maata palkaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Mutta lopun ajalla Etelän kuningas iskee yhteen hänen kanssansa. Ja Pohjan kuningas käy tämän kimppuun vaunuilla ja ratsuilla ja monilla laivoilla, hyökkää hänen maihinsa, tulvana leviten niiden ylitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Hän hyökkää myös Ihanaan maahan, ja monta kaatuu. Mutta hänen kädestänsä pelastuvat nämä: Edom ja Mooab ja ammonilaisten pääosa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Ja hän ojentaa kätensä maita kohti; Egyptin maa ei ole säästyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Hän valtaa kulta-ja hopea-aarteet ja kaikki Egyptin kalleudet, ja liibyalaiset ja etiopialaiset liittyvät häntä seuraamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Mutta sanomat idästä ja pohjoisesta säikähdyttävät häntä, ja hän lähtee täynnä kiukkua hävittämään monia ja vihkimään heitä tuhon omiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Hän pystyttää hovitelttansa meren ja pyhäkön ihanan vuoren välille. Mutta hänen loppunsa tulee, eikä häntä kukaan auta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Siihen aikaan nousee Miikael, se suuri enkeliruhtinas, joka seisoo sinun kansasi lasten suojana. Ja se on oleva ahdistuksen aika, jonka kaltaista ei ole ollut siitä saakka, kuin kansoja on ollut, hamaan siihen aikaan asti. Mutta siihen aikaan pelastetaan sinun kansasi, kaikki, jotka kirjaan kirjoitetut ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Ja monet maan tomussa makaavista heräjävät, toiset iankaikkiseen elämään, toiset häpeään ja iankaikkiseen kauhistukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Ja taidolliset loistavat, niinkuin taivaanvahvuus loistaa, ja ne, jotka monta vanhurskauteen saattavat, niinkuin tähdet, aina ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Mutta sinä, Daniel, lukitse nämä sanat ja sinetöi tämä kirja lopun aikaan asti. Monet sitä tutkivat, ja ymmärrys lisääntyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Ja minä, Daniel, näin, ja katso, siellä seisoi kaksi muuta, toinen virran tällä rannalla, toinen virran tuolla rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Ja toinen sanoi pellavapukuiselle miehelle, joka oli virran vetten yläpuolella: \"Kuinka kauan on vielä näitten ihmeellisten asiain loppuun?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Ja minä kuuntelin pellavapukuista miestä, joka oli virran vetten yläpuolella, ja hän nosti oikean ja vasemman kätensä taivasta kohti ja vannoi hänen kauttansa, joka elää iankaikkisesti: \"Siihen on vielä aika, kaksi aikaa ja puoli aikaa. Ja kun pyhän kansan yhden osan hajotus on loppunut, silloin nämä kaikki täyttyvät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Ja minä kuulin, mutta en ymmärtänyt, ja minä sanoin: \"Herrani, mikä on oleva näitten päätös?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Niin hän sanoi: \"Mene, Daniel, sillä ne sanat pysyvät lukittuina ja sinetöityinä lopun aikaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Monet puhdistetaan, kirkastetaan ja koetellaan, mutta jumalattomat pysyvät jumalattomina, eikä yksikään jumalaton ymmärrä tätä, mutta taidolliset ymmärtävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Ja siitä ajasta, jolloin jokapäiväinen uhri poistetaan ja hävityksen kauhistus asetetaan, on oleva tuhat kaksisataa yhdeksänkymmentä päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Autuas se, joka odottaa ja saavuttaa tuhat kolmesataa kolmekymmentä viisi päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Mutta sinä, mene, siksi kunnes loppu tulee; ja lepää, ja nouse osaasi päivien lopussa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Herran sana, joka tuli Hoosealle, Beerin pojalle, Juudan kuningasten Ussian, Jootamin, Aahaan ja Hiskian päivinä ja Israelin kuninkaan Jerobeamin, Jooaan pojan, päivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Kun Herra alkoi Hoosealle puhua, sanoi Herra Hoosealle: \"Mene, ota itsellesi haureellinen vaimo ja haureudesta syntyneet lapset, sillä maa on peräti rikkonut avion luopumalla Herrasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Niin hän meni ja otti Goomerin, Diblaimin tyttären. Ja tämä tuli raskaaksi ja synnytti hänelle pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Ja Herra sanoi hänelle: \"Pane hänelle nimeksi Jisreel, sillä vähän aikaa vielä, ja minä kostan Jisreelin verivelat Jeehun suvulle ja teen lopun Israelin heimon kuningaskunnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Ja sinä päivänä minä särjen Israelin jousen Jisreelin laaksossa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Ja vaimo tuli jälleen raskaaksi ja synnytti tyttären, ja Herra sanoi Hoosealle: \"Pane hänelle nimeksi Loo-Ruhama, sillä en minä enää tästedes armahda Israelin heimoa, niin että antaisin heille anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Mutta Juudan heimoa minä armahdan: minä pelastan heidät Herran, heidän Jumalansa, avulla, mutta en pelasta heitä jousella, miekalla enkä sodalla, en hevosilla enkä ratsumiehillä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Kun vaimo oli vieroittanut Loo-Ruhaman, tuli hän raskaaksi ja synnytti pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Ja Herra sanoi: \"Pane hänelle nimeksi Loo-Ammi, sillä te ette ole minun kansani, enkä minä tahdo olla teidän omanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, '{2:1} Mutta israelilaisten luku on oleva niinkuin meren hiekka, jota ei voi mitata eikä lukea. Ja siinä paikassa, jossa heille on sanottu: \'Te ette ole minun kansani\', heille sanotaan: \'Elävän Jumalan lapset!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'Ja Juudan miehet ja Israelin miehet kokoontuvat yhteen ja asettavat itsellensä yhteisen pään; ja he lähtevät sotaan siitä maasta, sillä suuri on Jisreelin päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Sanokaa veljiänne Ammiksi ja sisarianne Ruhamaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, '\"Riidelkää äitinne kanssa, riidelkää, sillä ei hän ole minun vaimoni, enkä minä ole hänen miehensä. Poistakoon hän haureutensa kasvoistansa ja aviorikoksensa rintainsa välistä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, '{2:5} etten minä riisuisi häntä alasti ja asettaisi häntä, niinkuin hän oli syntymänsä päivänä, etten tekisi häntä erämaan kaltaiseksi, saattaisi häntä kuivan maan kaltaiseksi ja kuolettaisi häntä janoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Ja hänen lapsiansa minä en armahda, sillä he ovat haureudesta syntyneitä lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Sillä heidän äitinsä on harjoittanut haureutta, heidän kantajansa on häpeällisesti elänyt, hän on sanonut: \'Minä kuljen rakastajaini perässä, jotka antavat minulle leipäni ja veteni, villani ja pellavani, öljyni ja juomani\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Sentähden, katso, minä aitaan sinun tiesi orjantappuroilla, minä muuraan muurin hänen eteensä, niin ettei hän löydä polkujansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Ja hän ajaa takaa rakastajiansa, mutta ei heitä saavuta; etsii heitä, mutta ei löydä. Ja hän on sanova: \'Minä menen takaisin entisen mieheni luokse, sillä parempi oli minulla olo silloin kuin nyt\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Hän ei ole tajunnut, että minä olen hänelle antanut jyvät ja viinin ja öljyn, olen kartuttanut hänelle hopeata ja myös kultaa, joka on käytetty Baalin hyväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Sentähden minä otan takaisin jyväni ajallansa ja viinini määräaikanansa ja tempaan pois villani ja pellavani, jonka piti peittää hänen alastomuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Nyt minä paljastan hänen häpynsä hänen rakastajainsa silmäin eteen, eikä kukaan ole pelastava häntä minun kädestäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Minä teen lopun kaikesta hänen ilonpidostansa: hänen juhlistansa, uusistakuistansa ja sapateistansa ja kaikista hänen pyhäpäivistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Ja minä hävitän hänen viiniköynnöksensä ja viikunapuunsa, joista hän on sanonut: \'Ne ovat minun portonpalkkani, jonka rakastajani ovat minulle antaneet\'. Minä teen ne metsäksi, ja metsän eläimet syövät niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Ja minä kostan hänelle baalien päivät, joina hän niille poltti uhreja, koristi itsensä renkaillaan ja kaulakäädyillään ja kulki rakastajainsa jäljessä, mutta unhotti minut, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Sentähden, katso, minä taivuttelen hänet, kuljetan hänet erämaahan ja viihdyttelen häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Minä annan hänelle sieltä alkaen hänen viinimäkensä ynnä Aakorin laakson toivon oveksi, ja hän on oleva siellä kuuliainen niinkuin nuoruutensa päivinä, niinkuin sinä päivänä, jona hän Egyptin maasta läksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Sinä päivänä, sanoo Herra, sinä puhuttelet minua: \'Minun mieheni\', etkä enää puhuttele minua: \'Minun Baalini\';');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'ja minä poistan baalien nimet hänen suustansa, eikä niiden nimiä enää mainita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Ja sinä päivänä minä teen heidän hyväksensä liiton metsän eläinten ja taivaan lintujen kanssa ja maan matelevaisten kanssa; ja jousen ja miekan ja sodan minä särjen maasta ja annan heidän asua turvassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Ja minä kihlaan sinut itselleni ikiajoiksi, kihlaan sinut itselleni vanhurskaudella ja tuomiolla, armolla ja laupeudella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'kihlaan sinut itselleni uskollisuudella, ja sinä olet tunteva Herran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Sinä päivänä minä kuulen, sanoo Herra, minä kuulen taivasta, ja se kuulee maata,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'ja maa kuulee jyviä, viiniä ja öljyä, ja nämä kuulevat Jisreeliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, '{2:25} Ja minä kylvän hänet itselleni tähän maahan, minä armahdan Loo-Ruhamaa ja sanon Loo-Ammille: \'Sinä olet minun kansani\'; ja hän vastaa: \'Minun Jumalani\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Sitten sanoi Herra minulle: \"Mene vielä ja rakasta naista, jota hänen puolisonsa rakastaa, mutta joka rikkoo avion, niinkuin Herra rakastaa israelilaisia, mutta nämä kääntyvät muiden jumalien puoleen ja rakastavat rypälekakkuja\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Niin minä hankin hänet itselleni viidellätoista sekelillä hopeata ynnä hoomer-mitalla ja letek-mitalla ohria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Ja minä sanoin hänelle: \"Ole kauan aikaa minua varten; älä harjoita haureutta äläkä mene muille miehille. Minä myös teen samoin sinua kohtaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Sillä kauan aikaa saavat israelilaiset olla ilman kuningasta ja ruhtinasta, ilman uhria ja patsasta, ilman kasukkaa ja kotijumalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Senjälkeen israelilaiset kääntyvät ja etsivät Herraa, Jumalaansa, ja Daavidia, kuningastansa. Vavisten he lähestyvät Herraa ja hänen hyvyyttänsä päivien lopulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Kuulkaa Herran sana, te israelilaiset, sillä Herralla on oikeudenkäynti maan asukasten kanssa; sillä ei ole uskollisuutta, ei laupeutta eikä Jumalan tuntemusta maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Vannotaan ja valhetellaan, murhataan, varastetaan ja rikotaan aviot, murtaudutaan taloihin, ja verityö verityötä seuraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Sentähden maa murehtii, ja kaikki siinä asuvaiset nääntyvät, metsän eläimet ja taivaan linnut; myöskin kalat merestä katoavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Älköön vain kukaan nuhdelko, älköön kukaan ojentako, vaikka sinun kansasi on kuin pappien nuhtelijoita!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Niin sinä kompastut päivällä, myös profeetta kompastuu yhdessä sinun kanssasi yöllä; ja minä hävitän sinun äitisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Minun kansani joutuu häviöön, sillä se on taitoa vailla. Koska sinä olet hyljännyt taidon, hylkään minä sinut, niin ettet saa olla minun pappinani. Koska olet unhottanut Jumalasi lain, unhotan myös minä sinun lapsesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Niin paljon kuin heitä on, niin paljon he ovat tehneet syntiä minua vastaan. Minä muutan heidän kunniansa häpeäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Minun kansani synnistä he saavat ruokansa, heidän pahoja tekojansa heidän sielunsa himoitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Mutta papin on käyvä niinkuin kansankin: minä rankaisen häntä hänen vaelluksestansa ja kostan hänelle hänen tekonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'He syövät, mutta eivät tule ravituiksi, he harjoittavat haureutta, mutta eivät lisäänny, sillä he eivät ole tahtoneet ottaa vaaria Herrasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Haureus ja viini ja rypälemehu vievät järjen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Minun kansani kysyy puultansa, ja sen sauva sille vastaa; sillä haureuden henki on eksyttäväinen: haureudessa he ovat luopuneet tottelemasta Jumalaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Vuorten huipuilla he uhraavat, polttavat uhreja kukkuloilla, rautatammen, haavan ja tammen alla, sillä niiden varjo on suloinen. Sentähden tulee teidän tyttäristänne porttoja, ja teidän miniänne rikkovat avion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'En minä rankaise teidän tyttäriänne siitä, että he porttoja ovat, enkä miniöitänne siitä, että he avion rikkovat, sillä miehet itse poikkeavat syrjään porttojen kanssa ja uhraavat pyhäkköporttojen kanssa; ja ymmärtämätön kansa kukistuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Jos sinä, Israel, harjoitatkin haureutta, älköön Juuda saattako itseänsä syynalaiseksi: älkää lähtekö Gilgaliin, älkää menkö ylös Beet-Aaveniin älkääkä vannoko: \"Niin totta kuin Herra elää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Sillä niinkuin niskuri lehmä on Israel niskoitellut; nyt on Herra kaitseva heitä niinkuin karitsaa laajalla laitumella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Efraim on liitossa epäjumalain kanssa-anna hänen olla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Kun heidän juopottelunsa on lopussa, he harjoittavat törkeätä haureutta. Ne, jotka ovat hänen kilpensä, rakastavat häpeätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Tuuli siivillänsä ahdistaa häntä, he saavat häpeän uhriaterioistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Kuulkaa tämä, te papit, tarkatkaa, Israelin heimo, ja ottakaa korviinne, kuninkaan huone: teille on tämä tuomio; sillä te olette olleet paula Mispalle, verkko, joka on levitetty Taaborille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Luopiot ovat syvälle vajonneet turmiontekoon, mutta minä olen kuritus heille kaikille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Minä tunnen Efraimin, eikä Israel ole minulta kätkössä; sillä nyt sinä, Efraim, olet haureutta harjoittanut, Israel on saastuttanut itsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Heidän tekonsa eivät salli heidän kääntyä Jumalansa puoleen, sillä haureuden henki on heidän sisimmässänsä eivätkä he tunne Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Israelin ylpeys syyttää häntä vasten silmiä, ja Israel ja Efraim kompastuvat syntivelkaansa; myös Juuda kompastuu heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Lampainensa ja raavainensa he tulevat, etsiäksensä Herraa, mutta eivät löydä: hän on vetäytynyt heistä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'He ovat olleet uskottomat Herralle, sillä he ovat synnyttäneet vieraita lapsia. Nyt uudenkuun juhla syö heidät ja heidän peltonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Puhaltakaa pasunaan Gibeassa, vaskitorveen Raamassa, nostakaa sotahuuto Beet-Aavenissa. Ovat jo sinun kintereilläsi, Benjamin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efraim on tuleva autioksi kurituksen päivänä. Israelin heimokuntia vastaan minä ilmoitan, mikä totta on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Juudan ruhtinaat ovat tulleet rajan siirtäjäin kaltaisiksi. Minä vuodatan heidän päällensä vihani niinkuin vedet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Sorrettu on Efraim, loukattu hänen oikeutensa, sillä hän tahtoi vaeltaa ihmiskäskyjen mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Minä olen Efraimille kuin koi ja Juudan heimolle kuin mätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Mutta kun Efraim näki sairautensa ja Juuda paiseensa, meni Efraim Assuriin, lähetti sanan sotaiselle kuninkaalle; mutta tämä ei voinut teitä parantaa, ei tehdä terveeksi teidän paisettanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Sillä minä olen Efraimille kuin leijona, Juudan heimolle kuin nuori jalopeura: minä, minä raatelen, menen ja kannan pois, eikä pelastajaa ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Minä menen takaisin paikoilleni, kunnes he ovat syystänsä kärsineet ja etsivät minun kasvojani: ahdistuksessansa he minua etsivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Tulkaa, palatkaamme Herran tykö, sillä hän on raadellut meitä, ja parantaa meidät, hän on lyönyt meitä, ja sitoo meidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Hän tekee meidät eläviksi kahden päivän kuluttua, kolmantena päivänä hän meidät herättää, ja me saamme elää hänen edessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Niin tuntekaamme, pyrkikäämme tuntemaan Herra: hänen nousunsa on varma kuin aamurusko, hän tulee meille kuin sade, kuin kevätsade, joka kostuttaa maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Mitä on minun tehtävä sinulle, Efraim, mitä on minun tehtävä sinulle, Juuda, kun teidän rakkautenne on kuin aamun pilvi, kuin varhain haihtuva kaste?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Sentähden minä olen antanut heille iskuja profeettain kautta, olen kuolettanut heitä suuni sanoilla. Ja sinun tuomiosi nousevat kuin aamun valo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Sillä laupeutta minä haluan enkä uhria, ja Jumalan tuntemista enemmän kuin polttouhreja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'mutta he ovat ihmisten tavalla rikkoneet liiton: siinä he ovat olleet minulle uskottomat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gilead on pahantekijäin kaupunki, täynnä veren jälkiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Ja väijyväisten rosvojen kaltainen on pappien joukko: he murhaavat Sikemin tiellä; ilkitöitä he tekevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Israelin heimon keskuudessa minä olen nähnyt kauhistuttavia tekoja: siellä on Efraimin haureus, Israel on itsensä saastuttanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Myös sinun varallesi, Juuda, on asetettu elonleikkuu, silloin kun minä käännän kansani kohtalon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Kun minä Israelia parannan, silloin tulevat julki Efraimin rikokset ja Samarian pahuudet; sillä he harjoittavat petosta, varas tunkeutuu sisään, ja rosvojoukko ryöstää ulkona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Eivät he ajattele sydämessään, että minä muistan kaiken heidän pahuutensa. Nyt heidän tekonsa piirittävät heidät, ne ovat tulleet minun kasvojeni eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'He ilahuttavat pahuudellansa kuningasta ja valheillansa ruhtinaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Kaikki he ovat avionrikkojia; he ovat kuin leipojan sytyttämä uuni: hän jättää tulen kohentamatta taikinan sotkemisesta sen happanemiseen asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Meidän kuninkaamme päivänä ovat ruhtinaat sairaina viinin hehkusta. Hän lyö kättä pilkkaajain kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Sillä he ovat juonillaan saattaneet sydämensä kuumaksi kuin uuni; koko yön heidän leipojansa nukkuu, aamulla se palaa kuin liekitsevä tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'He ovat kaikki kuumia kuin uuni, he syövät tuomarinsa: kaikki heidän kuninkaansa ovat kaatuneet, ei yksikään niistä ole minua avuksi huutanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efraim sekaantuu kansojen joukkoon. Efraim on tullut leivän kaltaiseksi, jota ei ole käännetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Muukalaiset syövät hänen voimansa, mutta ei hän sitä ymmärrä. Hänen hiuksensakin ovat jo harmaiksi käyneet, mutta hän ei ymmärrä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Israelin ylpeys syyttää häntä vasten silmiä, eivätkä he palaja Herran, Jumalansa, tykö, eivät etsi häntä, vaikka kaikki näin on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Efraim on tullut kyyhkysen kaltaiseksi, joka on tyhmä ja taitamaton: he huutavat avuksi Egyptiä, he menevät Assuriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Juuri kun ovat menossa, minä levitän verkkoni heidän päällensä ja pudotan heidät alas kuin taivaan linnut; minä kuritan heitä, niinkuin on julistettu heidän seurakunnallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Voi heitä, sillä he ovat menneet minua pakoon! Häviö heille, sillä he ovat minusta luopuneet! Minä tahdoin lunastaa heidät, mutta he puhuivat minua vastaan valheita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Eivät he huuda minun puoleeni sydämestänsä, vaan ulvovat vuoteissansa. Jyvien ja viinin tähden he kokoontuvat. Minua vastaan he niskoittelevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Minä olen heitä kurittanut, minä olen vahvistanut heidän käsivartensa, mutta minua vastaan he ovat aikoneet pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'He kääntyvät, mutta eivät korkeutta kohti. He ovat kuin pettävä jousi. Heidän ruhtinaittensa pitää kaatuman miekkaan kieltensä kiukkuisuuden tähden. Tästä he saavat pilkan Egyptin maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Suuhusi pasuna! Kotkan lailla Herran temppeliä vastaan-sillä he ovat rikkoneet minun liittoni, ovat luopuneet minun laistani!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Minun puoleeni he huutavat: \"Minun Jumalani!\" -\"Me Israel, me tunnemme sinut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Israel on hyljännyt hyvän. Vihollinen sitä vainotkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'He ovat asettaneet kuninkaita, mutta ei se ole ollut minusta; ovat asettaneet ruhtinaita, mutta minä en ole siitä tiennyt. Hopeansa ja kultansa he ovat tehneet epäjumalikseen, että tulisi hävitys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Inhottava on sinun vasikkasi, Samaria; minun vihani on syttynyt heitä vastaan. Kuinka kauan? -Eivät he voi päästä rankaisematta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Sillä Israelista se on tullut: seppä sen on tehnyt, eikä se ole jumala, vaan pirstaleiksi on menevä Samarian vasikka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Sillä tuulta he kylvävät, ja myrskyä he leikkaavat. Ei se pääse korrelle, laiho ei tuota jauhoja; ja minkä ehkä tuottaa, sen muukalaiset nielevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Nielty on Israel. He ovat nyt pakanain seassa kelpaamattoman astian arvoiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Sillä Assuriin ovat he menneet-villiaasi, joka kulkee yksinänsä. Efraim ostelee lahjoilla rakasteluja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Ostelkoot vain pakanain seassa, minä heidät nyt kokoan, ja he alkavat käydä vähäpätöisiksi ruhtinasten kuninkaan verojen painosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Koska Efraim on rakentanut paljon alttareita tehdäkseen syntiä, ovat alttarit tulleetkin hänelle synniksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Kirjoitinpa minä hänelle lakejani vaikka kymmentuhansin, muukalaisina niitä pidetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Minun uhrilahjoikseni he uhraavat lihaa ja syövät. Ei Herra niihin mielisty. Nyt hän muistaa heidän rikoksensa ja rankaisee heidän syntinsä: Egyptiin on heidän palattava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Israel on unhottanut tekijänsä ja rakentanut palatseja, ja Juuda on rakentanut paljon varustettuja kaupunkeja; mutta minä lähetän tulen hänen kaupunkeihinsa, ja se kuluttaa niiden palatsit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Älä iloitse, Israel, älä riemuitse, niinkuin muut kansat, sillä sinä olet haureudessa luopunut Jumalastasi, olet rakastanut portonpalkkoja kaikilla viljan puimatanterilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Puimatanner ja viinikuurna eivät heitä elätä, rypälemehu hänet pettää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Eivät he saa asua Herran maassa, vaan Efraimin on palattava Egyptiin, ja Assurissa he syövät saastaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Eivät he vuodata viiniä juomauhriksi Herralle, eivätkä heidän teurasuhrinsa hänelle kelpaa. Ne ovat heille kuin murheen leipä: kaikki, jotka sitä syövät, saastuttavat itsensä; sillä heidän leipänsä tulee heidän omaan nälkäänsä, ei tule se Herran temppeliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Mitä teette, kun tulee juhla-aika, Herran juhlapäivä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Sillä katso, heidän on mentävä hävitystä pakoon: Egypti heidät kokoaa, Moof heidät hautaa. Orjantappurat valtaavat heidän hopeakalleutensa, ohdakkeita on oleva heidän majoissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Rangaistuksen päivät tulevat, koston päivät tulevat, Israel saa tuntea sen. Hulluna on oleva profeetta, mieletönnä hengen mies sinun paljojen rikoksiesi ja paljon vainoamisen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Efraim on väijyjä minun Jumalaani vastaan. Profeetta-hänen kaikilla teillään on pyydystäjän paula, vainoamista on hänen Jumalansa temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'He ovat syvälle vajonneet turmiontekoon niinkuin Gibean päivinä. Hän muistaa heidän rikoksensa, rankaisee heidän syntinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Niinkuin rypäleet erämaassa minä löysin Israelin; niinkuin varhaishedelmät viikunapuussa, sen alkurunsaudessa, minä näin teidän isänne. He tulivat Baal-Peoriin, vihkiytyivät häpeäjumalalle ja tulivat kauhistaviksi, niinkuin tuo heidän rakastettunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Efraim-lintuna lentää pois heidän kunniansa: ei synnyttämistä, ei raskautta, ei sikiämistä enää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Ja vaikka he saisivat lapsensa isoiksi, teen minä heidät lapsettomiksi, niin ettei ihmisiä jää. Voi heitä itseänsäkin, kun minä heistä luovun!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Efraim on, kun minä sitä katson Tyyroon päin, istutettu laidunmaalle; mutta Efraimin täytyy viedä lapsensa surmaajalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Anna heille, Herra-mitä antaisitkaan? -anna heille hedelmätön kohtu ja kuivettuneet rinnat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Kaikki heidän pahuutensa on Gilgalissa, sillä siellä minä rupesin heitä vihaamaan. Heidän tekojensa pahuuden tähden minä karkoitan heidät temppelistäni pois. En minä enää heitä rakasta: kaikki heidän ruhtinaansa ovat niskureita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Efraim on hakattu maahan, heidän juurensa on kuivettunut: hedelmää he eivät tee. Ja jos synnyttävätkin, kuoletan minä heidän kohtunsa kalleimmat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Minun Jumalani on hylkäävä heidät, sillä he eivät ole häntä totelleet. He joutuvat pakolaisiksi pakanain sekaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Israel oli rehevä viiniköynnös, joka teki hedelmiä. Mitä runsaampi sen hedelmä oli, sitä runsaammin se teki alttareita; mitä parempi sen maa oli, sitä parempia patsaita se pystytti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Liukas oli heidän sydämensä; nyt he saavat siitä kärsiä: hän särkee heidän alttarinsa, hävittää heidän patsaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Nyt he saavat sanoa: \"Ei ole meillä kuningasta, sillä me emme ole peljänneet Herraa; ja mitä hyvää kuningas meille tekisi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'He puheita pitävät, väärin vannovat, liittoja tekevät; mutta tuomio versoo kuin koiruoho pellon vaosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Beet-Aavenin vasikkain tähden joutuvat pelkoon Samarian asukkaat. Sillä vasikan tähden vaikeroi sen kansa, ja vasikan tähden sen papit vapisevat, sen kunnian tähden, kun se siltä vaeltaa pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Se itsekin viedään Assuriin lahjaksi sotaisalle kuninkaalle. Häpeän saa Efraim, ja häpeään joutuu Israel neuvonpiteistänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Hukassa on Samaria kuninkaineen, on kuin vaahto veden pinnalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Aavenin uhrikukkulat, Israelin synti, hävitetään; orjantappuraa ja ohdaketta on kasvava heidän alttareillansa. Ja he sanovat vuorille: \"Peittäkää meidät\", ja kukkuloille: \"Langetkaa meidän päällemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Gibean päivistä asti sinä olet syntiä tehnyt, Israel. Sinne he ovat asettuneet. Eikö saavuttaisi heitä Gibeassa sota, sota vääryyden miehiä vastaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Haluni mukaan minä olen heitä kurittava, ja heitä vastaan kokoontuvat kansat, kun minä kytken heidät kiinni heidän kahteen rikokseensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Efraim on lehmä, joka on totutettu mielellänsä puimaan, mutta minä käyn käsiksi hänen kauniiseen kaulaansa. Minä valjastan Efraimin: Juuda saa kyntää, Jaakob äestää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Kylväkää itsellenne vanhurskauden kylvö, niin saatte leikata laupeuden leikkuun. Raivatkaa itsellenne uudispelto, silloin kun on aika etsiä Herraa, kunnes hän tulee ja antaa sataa, teille vanhurskautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Te olette kyntäneet jumalattomuutta, leikanneet vääryyttä ja syöneet valheen hedelmää; sillä sinä olet luottanut omaan tiehesi, sankariesi paljouteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'On nouseva pauhina sinun kansojesi kesken, ja kaikki sinun linnoituksesi hävitetään, niinkuin Salman hävitti Beet-Arbelin sodan päivänä: äiti ruhjotaan lastensa päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Tämän tekee teille Beetel teidän ylenpalttisen pahuutenne tähden: aamunkoitossa Israelin kuningas tuhotaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Kun Israel oli nuori, rakastin minä sitä, ja Egyptistä minä kutsuin poikani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Aina kun kutsujat heitä kutsuivat, he menivät pois heidän kasvojensa edestä, uhrasivat baaleille ja polttivat uhreja epäjumalille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Minä opetin Efraimin kävelemään. -Hän otti heidät käsivarsillensa. -Mutta he eivät ymmärtäneet, että minä heidät paransin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Ihmissiteillä minä heitä vedin, rakkauden köysillä; minä ikäänkuin nostin ikeen heidän leukapieliltänsä, kumarruin heidän puoleensa ja syötin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Eivätkö he joutuisi jälleen Egyptin maahan, eikö Assur tulisi heille kuninkaaksi, koska he eivät ole tahtoneet kääntyä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Miekka on riehuva hänen kaupungeissansa, on hävittävä hänen salpansa, on syövä syötävänsä, heidän neuvonpiteittensä takia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Minun kansallani on halu kääntyä minusta pois; ja kun sitä kutsutaan korkeutta kohti, ei kenkään heistä ylenny.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Kuinka minä jättäisin sinut, Efraim, heittäisin sinut, Israel? Kuinka jättäisin sinut niinkuin Adman, tekisin sinulle niinkuin Seboimille? Minun sydämeni kääntyy, minun säälini herää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'En minä pane täytäntöön vihani hehkua, en enää hävitä Efraimia. Sillä minä olen Jumala enkä ihminen, olen Pyhä sinun keskelläsi; en tule minä vihan tuimuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Ja he vaeltavat Herran jäljessä. Hän ärjyy kuin leijona-niin, hän ärjyy, ja vavisten tulevat lapset mereltä päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Vavisten he tulevat Egyptistä kuin linnut, Assurin maasta kuin kyyhkyset, ja minä saatan heidät asumaan kodeissansa, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, '{12:1} Efraim on ympäröinyt minut valheella ja Israelin huone vilpillä. Juuda juoksee yhä valtoimena, välittämättä Jumalasta, Pyhästä, Totisesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, '{12:2} Efraim tavoittelee tuulta, ajaa takaa itätuulta ja kartuttaa kaiken aikaa valhetta ja hävitystä; tehdään liittoja Assurin kanssa, ja viedään öljyä Egyptiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, '{12:3} Mutta Herralla on oikeudenkäynti Juudan kanssa, ja hän tahtoo rangaista Jaakobia sen teitten mukaan, hän on kostava sille sen tekojen mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, '{12:4} Äidin kohdussa tämä petti veljensä, ja miehuutensa voimassa hän taisteli Jumalan kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, '{12:5} Hän taisteli enkelin kanssa ja voitti, hän itki ja rukoili tätä. Beetelissä tämä löysi hänet ja puhui siellä meidän kanssamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, '{12:6} Herra, Jumala Sebaot-Herra on hänen nimensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, '{12:7} Ja sinä-käänny Jumalasi tykö, noudata laupeutta ja oikeutta ja pane alati toivosi Jumalaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, '{12:8} Kanaan-hänen kädessänsä on petollinen vaaka, halusta hän tekee vääryyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, '{12:9} Efraim sanoo: \"Olenpas rikastunut, olen saanut itselleni omaisuutta; ei mikään minun työansioni tuota minulle syyllisyyttä, joka olisi syntiä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, '{12:10} Mutta minä, joka olen Herra, sinun Jumalasi, hamasta Egyptin maasta lähtien, minä saatan vielä sinut asumaan teltoissa niinkuin juhlapäivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, '{12:11} Minä olen puhunut profeetoille, olen antanut paljon näkyjä ja puhunut vertauksia profeettain kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, '{12:12} Jos Gilead on pelkkää petosta ollutkin, niin he pelkäksi turhuudeksi tulevatkin. Gilgalissa on uhrattu härkiä, niinpä tuleekin heidän alttareistansa kuin kiviröykkiöitä, joita on pellon vaoilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, '{12:13} Jaakob pakeni Aramin kedoille, ja Israel palveli naisen tähden, naisen tähden hän paimensi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, '{12:14} Mutta profeetan kautta vei Herra Israelin Egyptistä pois, ja profeetta sitä paimensi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, '{12:15} Efraim nosti katkeran mielikarvauden. Hänen Herransa on heittävä hänen verivelkansa hänen päällensä ja kääntävä hänen häpäisevän menonsa häneen itseensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Milloin Efraim puhui, syntyi kauhu: korkealle kohosi hän Israelissa. Mutta hän joutui syynalaiseksi Baalin takia, ja hän kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Nyt he jatkavat synnintekoa, tekevät itselleen valettuja kuvia hopeastansa, epäjumalankuvia ymmärryksensä mukaan, taitoniekkain tekemiä kaikki tyynni. Niille he puhuvat; ihmisiä teurastavat, vasikoita suutelevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Sentähden he ovat kuin aamupilvi, kuin kaste, joka varhain haihtuu, kuin akanat, jotka puimatantereelta lentävät, kuin savu, joka häipyy ikkunasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Mutta minä olen Herra, sinun Jumalasi, hamasta Egyptin maasta lähtien; muuta Jumalaa sinä et tunne kuin minut, eikä ole muuta auttajaa kuin minä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Minä tunsin sinut erämaassa, kuivassa maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Sen mukaan kuin heidän laitumensa olivat, he kylläisiksi tulivat. He tulivat kylläisiksi, ja heidän sydämensä tuli ylpeäksi; sentähden he unhottivat minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Niin minusta tuli heille ikäänkuin leijona, niinkuin pantteri tien ohessa minä heitä väijyin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Minä käyn heidän kimppuunsa kuin karhu, jolta on riistetty poikaset, revin heidän sydänkalvonsa ja syön heidät siinä paikassa kuin naarasleijona. Metsän pedot raatelevat heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Se on sinun turmiosi, Israel, että olet minua vastaan, joka olen sinun apusi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Missä on nyt sinun kuninkaasi, että hän auttaisi sinua kaikissa kaupungeissasi, ja sinun tuomarisi, joista olet sanonut: \"Anna minulle kuningas ja ruhtinaat\"?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Kuninkaan minä annan sinulle vihassani ja otan pois kiivastuksessani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Efraimin rikos on sidottu kokoon, talteen on pantu hänen syntinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Hänelle tulee synnyttäjän tuskat. Hän on älytön lapsi, sillä hän ei aikanansa tule esiin kohdusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Tuonelan kädestä minä heidät päästän, kuolemasta minä heidät lunastan. Missä on sinun ruttosi, kuolema, missä sinun surmasi, tuonela? Katumus on peitetty minun silmiltäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Vaikka hän veljien seassa on hedelmöitseväinen, on itätuuli tuleva, on nouseva Herran tuuli erämaasta, ja hänen kaivonsa kuivuu, ja hänen lähteensä ehtyy: se on ryöstävä hänen aarteensa, kaikki hänen kallisarvoiset kalunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, '{14:1} Samaria joutuu syystänsä kärsimään, koska se on niskoitellut Jumalaansa vastaan: he kaatuvat miekkaan, heidän pienet lapsensa ruhjotaan, ja heidän raskaat vaimonsa halkaistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, '{14:2} Palaja Israel, Herran, sinun Jumalasi tykö, sillä sinä olet kompastunut rikoksiisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, '{14:3} Ottakaa mukaanne sanoja ja palatkaa Herran tykö ja sanokaa hänelle: \"Anna anteeksi kaikki rikokset, ota armoihisi, niin me tuomme sinulle uhrimulleiksi huultemme uhrit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, '{14:4} Assur ei ole meitä auttava, hevosilla emme tahdo ratsastaa, emmekä enää sano kättemme teoille: \'Meidän jumalamme\'; sillä sinussa saa orpo armon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, '{14:5} Minä parannan teidän luopumuksenne, omasta halustani minä teitä rakastan; sillä minun vihani on kääntynyt hänestä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, '{14:6} Minä olen oleva Israelille kuin kaste, se on kukoistava kuin lilja ja juurtuva syvälle kuin Libanon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, '{14:7} Sen vesat leviävät, sen kauneus on oleva kuin öljypuun ja sen tuoksu kuin Libanonin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, '{14:8} Sen varjossa asuvaiset kasvattavat jälleen viljaa ja kukoistavat kuin viiniköynnös. Sen maine on oleva kuin Libanonin viinin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, '{14:9} Efraim! Mitä on minulla enää tekemistä epäjumalien kanssa? Minä kuulen häntä, minä katson hänen puoleensa, minä, joka olen kuin viheriöitsevä kypressi: minusta on sinun hedelmäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, '{14:10} Kuka on viisas ja ymmärtää nämä? Kuka taitava ja käsittää nämä? Sillä Herran tiet ovat suorat: vanhurskaat niillä vaeltavat, mutta luopiot niillä kompastuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Herran sana, joka tuli Jooelille, Petuelin pojalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Kuulkaa tämä, te vanhimmat, ja ottakaa korviinne, kaikki maan asukkaat. Onko tällaista tapahtunut teidän päivinänne taikka teidän isienne päivinä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Kertokaa tämä lapsillenne, ja teidän lapsenne kertokoot sen lapsillensa ja heidän lapsensa tulevalle polvelle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Mitä kalvajasirkalta jäi, sen söi heinäsirkka. Ja mitä heinäsirkalta jäi, sen söi syöjäsirkka. Ja mitä syöjäsirkalta jäi, sen söi tuhosirkka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Herätkää, te juopuneet, ja itkekää, valittakaa, kaikki viininjuojat, rypälemehun tähden, sillä se on otettu pois teidän suustanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Sillä minun maahani on hyökännyt kansa, väkevä ja epälukuinen. Sen hampaat ovat leijonan hampaat, ja sillä on naarasleijonan leukaluut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Se on raastanut minun viiniköynnökseni ja katkonut minun viikunapuuni, on ne paljaiksi kuorinut ja karsinut; niiden oksat ovat valjenneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Valita niinkuin neitsyt, joka on vyöttäytynyt säkkiin nuoruutensa yljän tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Pois on otettu ruokauhri ja juomauhri Herran huoneesta. Papit, jotka toimittavat Herran palvelusta, murehtivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Hävitetty on pelto, maa murehtii; sillä vilja on hävitetty, viinistä on tullut kato, öljy on kuivunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Peltomiehet ovat joutuneet häpeään, viinitarhurit valittavat nisun ja ohran tähden, sillä mennyt on pellon sato.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Viiniköynnöstä on kohdannut kato, viikunapuu on kuihtunut, granaattipuu ja myös palmu ja omenapuu; kaikki kedon puut ovat kuivettuneet. Niin, häpeään on joutunut ilo, ihmislasten joukosta pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Vyöttäytykää säkkiin, pitäkää valittajaiset, te papit; valittakaa, te jotka toimitatte palvelusta alttarilla. Käykää sisälle, viettäkää yö säkkeihin puettuina, te jotka toimitatte minun Jumalani palvelusta. Sillä poissa on teidän Jumalanne huoneesta ruokauhri ja juomauhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Kuuluttakaa pyhä paasto, kutsukaa koolle juhlakokous, kootkaa vanhimmat ja kaikki maan asukkaat Herran, teidän Jumalanne, huoneeseen ja huutakaa Herran puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Voi sitä päivää! Sillä lähellä on Herran päivä, ja se tulee niinkuin hävitys Kaikkivaltiaalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Eikö ole otettu meiltä ruoka silmäimme edestä sekä meidän Jumalamme huoneesta ilo ja riemu?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Surkastuneet ovat siemenjyvät multiensa alla, varastohuoneet autiot, aitat puretut, kun viljasta on kato.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Kuinka huokaa karja, kuinka hädissään ovat raavaslaumat, sillä ei ole niillä laidunta! Myös lammaslaumat joutuvat perikatoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Sinua, Herra, minä huudan, sillä tuli on kuluttanut erämaan laitumet ja liekki polttanut kaikki kedon puut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Metsän eläimetkin sinua ikävöivät, sillä vesipurot ovat kuivuneet ja tuli on kuluttanut erämaan laitumet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Puhaltakaa pasunaan Siionissa, toitottakaa torvia minun pyhällä vuorellani. Jokainen maan asukas on vapiseva, sillä Herran päivä tulee. Niin, se on lähellä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'pimeyden ja synkeyden päivä, pilvien ja pilkkopimeän päivä. Vuorille levinneenä niinkuin aamurusko on lukuisa ja väkevä kansa, jonka vertaista ei ole ollut ikiajoista asti eikä tämän jälkeen enää tule, tulevaisten polvien vuosiin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Sen edellä käy kuluttava tuli, sen jäljissä polttava liekki. Niinkuin Eedenin puutarha on maa sen edessä, sen jäljissä on autio erämaa, eikä jää ketään, joka olisi siltä pelastunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Ne ovat näöltänsä kuin hevoset, ja niinkuin ratsut ne juoksevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Ryskyen kuin sotavaunut ne hyppivät vuorten huipuilla, räiskyen kuin tulen liekki, joka kuluttaa oljet; ne ovat kuin väkevä kansa, sotarintaan asettunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Niitten edessä kansat vapisevat, kaikki kasvot kalpenevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Ne juoksevat kuin sankarit, kuin soturit ne nousevat muurille. Jokainen kulkee tietänsä suoraan, ei mutkittele polullansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Toinen ei sysi toistansa: jokainen kulkee omaa suuntaansa. Heittoaseitten välitse ne syöksyvät pysähtymättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Kaupunkiin ne hyökkäävät, ryntäävät muurille, nousevat taloihin, tulevat ikkunoista sisään kuin varas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Niitten edessä maa vapisee, ja taivaat järkkyvät; aurinko ja kuu käyvät mustiksi, ja tähdet kadottavat valonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Ja Herra antaa äänensä jylistä sotajoukkonsa edellä, sillä ylen lukuisa on hänen väkensä, sillä väkevä on hänen käskynsä täyttäjä, sillä suuri on Herran päivä ja sangen peljättävä; kuka voi sitä kestää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Mutta vielä nytkin, sanoo Herra, kääntykää minun tyköni kaikesta sydämestänne, paastoten, itkien ja valittaen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Reväiskää rikki sydämenne, älkää vaatteitanne, ja kääntykää Herran, teidän Jumalanne, tykö; sillä hän on armahtavainen ja laupias, pitkämielinen ja armosta rikas, ja hän katuu pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Ehkä hän vielä katuu ja jättää jälkeensä siunauksen: ruokauhrin ja juomauhrin Herralle, teidän Jumalallenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Puhaltakaa pasunaan Siionissa, kuuluttakaa pyhä paasto, kutsukaa koolle juhlakokous.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Kootkaa kansa, pitäkää pyhä seurakuntakokous, kerätkää vanhukset, kootkaa lapset ja rintoja imeväiset; lähteköön ylkä huoneestansa ja morsian kammiostansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Eteisen ja alttarin välillä itkekööt papit, jotka toimittavat Herran palvelusta, ja sanokoot: \"Säästä, Herra, kansaasi äläkä anna perintöosaasi häväistäväksi, pakanain pilkattavaksi. Miksi pitäisi sanottaman kansain seassa: \'Missä on heidän Jumalansa?\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Niin Herra kiivaili maansa puolesta ja sääli kansaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Ja Herra vastasi ja sanoi kansalleen: Katso, minä lähetän teille viljaa, viiniä ja öljyä, niin että te tulette niistä ravituiksi. Enkä minä anna enää häväistä teitä pakanain seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Ja mikä pohjoisesta tulee, sen minä karkoitan teistä kauas ja syöksen sen kuivaan ja autioon maahan, sen alkupään Idänmereen ja sen loppupään Länsimereen. Ja siitä nousee löyhkä, nousee katku. Sillä suuria se on yrittänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Älä pelkää, maa. Iloitse ja riemuitse, sillä Herra on tehnyt suuria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Älkää peljätkö, metsän eläimet, sillä erämaan laitumet viheriöivät, sillä puu kantaa hedelmänsä, viikunapuu ja viiniköynnös antavat voimansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Ja te, Siionin lapset, iloitkaa ja riemuitkaa Herrassa, teidän Jumalassanne, sillä hän antaa teille syyssateen, vanhurskauden mukaan, vuodattaa teille sateen, syyssateen ja kevätsateen, niinkuin entisaikaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Ja puimatantereet tulevat jyviä täyteen, ja kuurna-altaat pursuvat viiniä ja öljyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Ja minä korvaan teille ne vuodentulot, jotka heinäsirkka, syöjäsirkka, tuhosirkka ja kalvajasirkka söivät, minun suuri sotajoukkoni, jonka minä lähetin teitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Ja te syötte kyllälti ja tulette ravituiksi ja kiitätte Herran, teidän Jumalanne, nimeä, hänen, joka on tehnyt ihmeitä teitä kohtaan. Eikä minun kansani joudu häpeään, iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Ja te tulette tietämään, että Israelin keskellä olen minä. Ja minä olen Herra, teidän Jumalanne, eikä toista ole. Eikä minun kansani joudu häpeään, iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'Näitten jälkeen minä olen vuodattava Henkeni kaiken lihan päälle, ja teidän poikanne ja tyttärenne ennustavat, vanhuksenne unia uneksuvat, nuorukaisenne näkyjä näkevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Ja myös palvelijain ja palvelijattarien päälle minä niinä päivinä vuodatan Henkeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'Minä annan näkyä ihmeitä taivaalla ja maassa: verta ja tulta ja savupatsaita;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'aurinko muuttuu pimeydeksi ja kuu vereksi, ennenkuin Herran päivä tulee, se suuri ja peljättävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'Ja jokainen, joka huutaa avuksi Herran nimeä, pelastuu. Sillä Siionin vuorella ja Jerusalemissa ovat pelastuneet, niinkuin Herra on sanonut; ja pakoonpäässeitten joukossa ovat ne, jotka Herra kutsuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Sillä katso, niinä päivinä ja siihen aikaan, kun minä käännän Juudan ja Jerusalemin kohtalon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'minä kokoan kaikki pakanakansat, vien ne alas Joosafatin laaksoon ja käyn siellä oikeutta niitten kanssa kansani ja perintöosani, Israelin, tähden. Sillä he ovat hajottaneet sen pakanakansain sekaan, ovat jakaneet minun maani');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'ja heittäneet minun kansastani arpaa; ovat antaneet pojan porttoa vastaan sekä myyneet tytön viinistä, jonka ovat juoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Mitä on teillä sanomista minulle, teilläkin, Tyyro ja Siidon ja kaikki filistealaisten alueet? Tahdotteko te kostaa minulle, mitä minä olen tehnyt, vai itse tehdä minulle jotakin? Nopeasti, kiiruusti minä annan koston kohdata teidän päätänne siitä, mitä olette tehneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'te, jotka olette ottaneet minun hopeani ja kultani, vieneet minun ihanat kalleuteni temppeleihinne');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'sekä myyneet Juudan ja Jerusalemin lapsia jaavanilaisille, poistaaksenne heidät kauas omalta maaltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Katso, minä herätän heidät liikkeelle siitä paikasta, johon te olette heidät myyneet, ja annan koston teostanne kohdata teidän päätänne:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'minä myyn teidän poikianne ja tyttäriänne Juudan poikien käsiin, ja he myyvät ne sabalaisille, kaukaiselle kansalle. Sillä Herra on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Julistakaa tämä pakanakansain seassa, alkakaa pyhä sota, innostakaa sankareita, lähestykööt, hyökätkööt kaikki soturit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Takokaa vantaanne miekoiksi ja vesurinne keihäiksi. Sanokoon heikko: \"Minä olen sankari\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Käykää avuksi, tulkaa, kaikki kansakunnat joka taholta. He kokoontuvat sinne. Anna, Herra, sankariesi astua sinne alas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Lähtekööt liikkeelle, hyökätkööt kansakunnat Joosafatin laaksoon; sillä siellä hän istuu tuomitsemassa kaikkia pakanakansoja, joka taholta tulleita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Lähettäkää sirppi, sillä sato on kypsynyt. Tulkaa polkemaan, sillä kuurna on täynnä ja kuurna-altaat pursuvat ylitse; sillä heidän pahuutensa on suuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Meluavia joukkoja, meluavia joukkoja ratkaisulaaksossa! Sillä lähellä on Herran päivä ratkaisulaaksossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Aurinko ja kuu käyvät mustiksi, ja tähdet kadottavat valonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Herra ärjyy Siionista ja antaa äänensä kuulua Jerusalemista, ja taivaat ja maa järkkyvät; mutta Herra on kansansa suoja, Israelin lasten turva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'Ja te tulette tietämään, että minä olen Herra, teidän Jumalanne, joka asun Siionissa, pyhällä vuorellani. Ja Jerusalem on oleva pyhä, ja vieraat eivät enää kulje sen läpi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'Sinä päivänä vuoret tiukkuvat rypälemehua, ja kukkulat vuotavat maitoa; kaikissa Juudan puronotkoissa virtaa vettä, ja Herran huoneesta juoksee lähde, ja se kastelee Akasialaakson.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Egypti tulee autioksi, ja Edom tulee autioksi erämaaksi väkivallan tähden, jota ne ovat tehneet Juudan lapsille, kun ovat vuodattaneet viatonta verta heidän maassansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Mutta Juuda on oleva asuttu iankaikkisesti ja Jerusalem polvesta polveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Ja minä julistan heidät puhtaiksi verivelasta, josta en ole heitä puhtaiksi julistanut. Ja Herra on asuva Siionissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Aamoksen sanat, hänen, jolla oli lammaslaumoja Tekoassa; mitä hän näyssä näki Israelista Ussian, Juudan kuninkaan, päivinä ja Jerobeamin, Jooaan pojan, Israelin kuninkaan, päivinä, kaksi vuotta ennen maanjäristystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Ja hän sanoi: Herra ärjyy Siionista, hän jylisee Jerusalemista, ja paimenten laitumet lakastuvat, ja Karmelin laki kuivuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Näin sanoo Herra: Damaskon kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska he ovat puineet Gileadin rautaisilla puimaäkeillä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'sentähden minä lähetän tulen Hasaelin linnaa vastaan, ja se kuluttaa Benhadadin palatsit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Minä särjen Damaskon salvat, ja minä hävitän Bikat-Aavenin asukkaat ja Beet-Edenin valtikanpitäjät, ja Aramin kansa viedään pakkosiirtolaisuuteen Kiiriin, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Näin sanoo Herra: Gassan kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska he ovat vieneet pakkosiirtolaisuuteen ja luovuttaneet Edomille kaiken väen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'sentähden minä lähetän tulen Gassan muuria vastaan, ja se kuluttaa sen palatsit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Minä hävitän Asdodin asukkaat ja Askelonin valtikanpitäjät, ja minä käännän käteni Ekronia vastaan, ja filistealaisten tähteet hukkuvat, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Näin sanoo Herra: Tyyron kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska he ovat luovuttaneet kaiken väen pakkosiirtolaisina Edomille eivätkä ole muistaneet veljesliittoa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'sentähden minä lähetän tulen Tyyron muuria vastaan, ja se kuluttaa sen palatsit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Näin sanoo Herra: Edomin kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska se on vainonnut miekalla veljeänsä ja tukahduttanut kaiken armahtavaisuuden ja pitänyt ikuista vihaa ja säilyttänyt kiukkunsa ainaisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'sentähden minä lähetän tulen Teemania vastaan, ja se kuluttaa Bosran palatsit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Näin sanoo Herra: Ammonilaisten kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska he ovat halkaisseet Gileadin raskaat vaimot, laajentaakseen aluettansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'sentähden minä sytytän tulen Rabban muuria vastaan, ja se kuluttaa sen palatsit, sotahuudon kaikuessa sodan päivänä, myrskyn pauhatessa rajuilman päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Ja heidän kuninkaansa vaeltaa pakkosiirtolaisuuteen, hän ja hänen ruhtinaansa kaikki tyynni, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Näin sanoo Herra: Mooabin kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska se on polttanut Edomin kuninkaan luut kalkiksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'sentähden minä lähetän tulen Mooabia vastaan, ja se kuluttaa Kerijotin palatsit. Ja Mooab kuolee sodan melskeessä, sotahuudon ja pasunan pauhinassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Ja minä hävitän tuomarin sen keskeltä, ja kaikki sen päämiehet minä tapan yhdessä sen kanssa, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Näin sanoo Herra: Juudan kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Koska he ovat hyljänneet Herran lain eivätkä ole pitäneet hänen käskyjänsä, vaan heidän valhejumalansa, joiden perässä jo heidän isänsä kulkivat, ovat heidät vietelleet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'sentähden minä lähetän tulen Juudaa vastaan, ja se kuluttaa Jerusalemin palatsit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Näin sanoo Herra: Israelin kolmen rikoksen, neljän rikoksen tähden minun päätökseni on peruuttamaton. Sillä he myyvät hurskaan rahasta ja köyhän kenkäparista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'polkevat maan tomuun vaivaisten pään ja vääntävät mutkaiseksi nöyrien tien. Ja poika ja isä käyvät saman naisen pariin häväisten minun pyhän nimeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'He loikovat pantiksi otetuilla vaatteilla jokaisen alttarin ääressä ja juovat sakotettujen viiniä jumalansa huoneessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Ja kuitenkin minä hävitin heidän edestänsä amorilaiset, jotka olivat korkeakasvuiset kuin setrit ja vahvat kuin tammet, ja minä hävitin niiden hedelmän ylhäältä ja niiden juuret alhaalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Ja minä johdatin teidät Egyptin maasta ja kuljetin teitä erämaassa neljäkymmentä vuotta, että saisitte ottaa omaksenne amorilaisten maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Ja minä herätin teidän pojistanne profeettoja ja nuorukaisistanne nasiireja. Vai eikö niin ole, te israelilaiset? sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Mutta te juotitte nasiireille viiniä, ja profeettoja te kielsitte sanoen: \"Älkää ennustako\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Katso, minä rusennan teidät alallenne, niinkuin täyteen kuormattu puimajyrä rusentaa lyhteet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Silloin nopeakaan ei pääse pakoon, ei väkevällä ole apua voimastaan, eikä sankari pelasta henkeänsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'jousimies ei kestä paikallansa, nopeajalkainen ei pelastu, eikä ratsumies pelasta henkeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Ja sankareista rohkein pakenee alasti sinä päivänä, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Kuulkaa tämä sana, jonka Herra on puhunut teitä vastaan, te israelilaiset, koko sitä sukukuntaa vastaan, jonka minä olen johdattanut Egyptin maasta, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Ainoastaan teidät minä olen valinnut kaikista maan sukukunnista; sentähden minä kostan teille kaikki teidän pahat tekonne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Kulkeeko kaksi yhdessä, elleivät ole keskenänsä sopineet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'rjyykö leijona metsässä, ellei sillä ole raadeltavaa? Kiljuuko nuori leijona luolastansa, ellei se ole saalista saanut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Käykö lintu maassa paulaan, ellei sen varalle ole pyydystä pantu? Nouseeko paula maasta saaliin siihen tarttumatta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Puhalletaanko pasunaan kaupungissa, niin ettei kansa peljästy? Tahi tapahtuuko kaupungissa onnettomuutta, jota ei Herra ole tuottanut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Sillä ei Herra, Herra, tee mitään ilmoittamatta salaisuuttaan palvelijoillensa profeetoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Leijona ärjyy: kuka ei pelkäisi? Herra, Herra puhuu: kuka ei ennustaisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Julistakaa Asdodin palatseille ja Egyptin maan palatseille ja sanokaa: Kokoontukaa Samarian vuorille ja katsokaa, mikä suuri meteli on sen keskellä ja mikä sorto sen sisällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'He eivät ymmärrä tehdä sitä, mikä oikein on, sanoo Herra; he kokoovat väkivaltaa ja sortoa palatseihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Sentähden, näin sanoo Herra, Herra: Vihollinen on oleva kaikkialla maassa, ja hän kukistaa sinun linnoituksesi, ja sinun palatsisi ryöstetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Näin sanoo Herra: Niinkuin paimen saa pelastetuksi leijonan kidasta pari sääriluuta tai kappaleen korvaa, niin pelastuu israelilaisiakin, niitä, jotka istuvat Samariassa sohvankulmassa ja kirjosilkkisellä leposijalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Kuulkaa ja todistakaa Jaakobin heimoa vastaan, sanoo Herra, Herra, Jumala Sebaot:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Sinä päivänä, jona minä kostan Israelille hänen rikoksensa, minä kostan myös Beetelin alttareille, niin että alttarinsarvet hakataan irti ja putoavat maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Ja minä sorran maahan talvihuoneen ja kesähuoneen, ja norsunluuhuoneet kukistuvat, ja paljoista huoneista tulee loppu, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Kuulkaa tämä sana, te Baasanin lehmät, jotka olette Samarian vuorella, jotka sorratte vaivaisia ja runtelette köyhiä, jotka sanotte herroillenne: \"Tuokaa meille juomista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Herra, Herra on vannonut pyhyytensä kautta: Totisesti, katso, päivät tulevat teille, jolloin teidät temmataan ylös koukuilla ja viimeisetkin teistä kalaongilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Ja muurin halkeamista te lähdette ulos, kukin suorinta tietä, ja teidät heitetään Harmoniin päin, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Menkää Beeteliin ja tehkää syntiä, ja Gilgaliin ja tehkää vielä enemmän syntiä; tuokaa aamulla teurasuhrinne, kolmantena päivänä kymmenyksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Uhratkaa hapanta kiitosuhriksi, kuuluttakaa, julistakaa vapaaehtoisia lahjoja, sillä niinhän te haluatte, te israelilaiset, sanoo Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Minä kyllä tein teidän hampaanne joutilaiksi kaikissa teidän kaupungeissanne ja tuotin leivän puutteen kaikkiin teidän paikkakuntiinne. Mutta te ette kääntyneet minun tyköni, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Minä pidätin teiltä sateen, kun vielä oli kolme kuukautta elonkorjuuseen. Minä annoin sataa toiselle kaupungille, mutta toiselle kaupungille en antanut sataa; toinen pelto sai sadetta, ja toinen, jolle ei satanut, kuivui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Ja niin kaksi, kolme kaupunkia hoippui yhteen kaupunkiin vettä juomaan, saamatta kyllikseen. Mutta te ette kääntyneet minun tyköni, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Minä rankaisin teitä nokitähkillä ja viljanruosteella; teidän monet puutarhanne, viinimäkenne, viikunapuunne ja öljypuunne söi kalvajasirkka. Mutta te ette kääntyneet minun tyköni, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Minä lähetin teihin ruton niinkuin Egyptiin; minä tapoin miekalla teidän nuoret miehenne, ja teidän ratsunne otettiin saaliiksi; ja minä annoin löyhkän teidän leireistänne nousta teidän sieramiinne. Mutta te ette kääntyneet minun tyköni, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Minä panin toimeen hävityksen teidän seassanne, niinkuin Jumala hävitti Sodoman ja Gomorran, ja te olitte kuin tulesta temmattu kekäle. Mutta te ette kääntyneet minun tyköni, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Sentähden minä teen sinulle, Israel, näin. Koska minä tämän sinulle teen, niin valmistaudu, Israel, kohtaamaan Jumalaasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Sillä katso: hän on se, joka on tehnyt vuoret ja luonut tuulen, joka ilmoittaa ihmiselle, mikä hänen aivoituksensa on, joka tekee aamuruskon ja pimeyden ja joka kulkee maan kukkulain ylitse-Herra, Jumala Sebaot, on hänen nimensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Kuulkaa tämä Herran sana, itkuvirsi, jonka minä viritän teistä, te Israelin heimo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Kaatunut on neitsyt Israel eikä enää nouse; hän viruu kaadettuna maassansa, eikä ole, kuka hänet nostaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Sillä näin sanoo Herra, Herra: Kaupunkiin, josta ennen lähti tuhat, jää jäljelle sata; ja josta lähti sata, siihen jää kymmenen jäljelle, Israelin heimoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Sillä näin sanoo Herra Israelin heimolle: Etsikää minua, niin te saatte elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Älkää etsikö Beeteliä, älkää menkö Gilgaliin älkääkä vaeltako Beersebaan. Sillä Gilgal viedään pakkosiirtolaisuuteen, ja Beetel joutuu tuhon omaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Etsikää Herraa, niin te saatte elää, ettei hän tulena tunkeutuisi Joosefin huoneeseen ja kuluttaisi sitä eikä olisi sammuttajaa Beetelillä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'te, jotka muutatte oikeuden koiruohoksi ja vanhurskauden maahan kukistatte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Hän, joka on tehnyt Otavan ja Kalevanmiekan ja muuttaa synkeyden aamuksi ja pimentää päivän yöksi ja kutsuu kokoon meren vedet ja vuodattaa ne maan pinnalle-Herra on hänen nimensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'hänen, joka äkisti tuottaa väkevälle hävityksen, ja niin tulee hävitys linnoitukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'He vihaavat sitä, joka portissa oikeutta puoltaa, ja totuuden puhuja on heille kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Sentähden, koska te poljette vaivaista ja otatte häneltä viljaveroa, niin vaikka te rakennatte taloja hakatusta kivestä, te ette niissä asu; vaikka te istutatte ihania viinitarhoja, te ette niistä viiniä juo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Sillä minä tiedän, että teidän rikoksenne ovat monet ja teidän syntinne raskaat: te vainoatte vanhurskasta ja otatte lahjuksia ja väännätte vääräksi portissa köyhäin asian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Sentähden ymmärtäväinen vaikenee tänä aikana, sillä se on paha aika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Etsikää hyvää, älkääkä pahaa, että te eläisitte. Silloin Herra, Jumala Sebaot, on oleva teidän kanssanne, niinkuin te sanotte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Vihatkaa pahaa ja rakastakaa hyvää ja saattakaa oikeus voimaan portissa: ehkäpä Herra, Jumala Sebaot, armahtaa Joosefin jäännöstä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Sillä näin sanoo Herra, Jumala Sebaot, Herra: Kaikilla toreilla on valitus, kaikilla kaduilla sanotaan: \"Voi! Voi!\" Peltomiehiä kutsutaan surun viettoon ja itkuvirren taitajia valittajaisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Ja kaikissa viinitarhoissa on valitus, sillä minä käyn sinun keskitsesi, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Voi teitä, jotka toivotte Herran päivän tulemista. Miksi hyväksi on teille Herran päivä? Se on oleva pimeys, eikä valkeus-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'ikäänkuin jos joku pakenisi leijonaa ja häntä kohtaisi karhu, tahi joku tulisi kotiin ja nojaisi kätensä seinään ja häntä pistäisi käärme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Eikö Herran päivä ole pimeys, eikä valkeus, eikö se ole synkeys, jossa ei valoa ole?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Minä vihaan, minä halveksin teidän juhlianne enkä mielisty teidän juhlakokouksiinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Sillä vaikka te tuotte minulle polttouhreja ja ruokauhrejanne, eivät ne minulle kelpaa, enkä minä katso teidän yhteysuhrienne, syöttövasikkainne, puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Vie pois minun edestäni virttesi pauhina, en tahdo kuulla sinun harppujesi soittoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Mutta oikeus virratkoon kuin vesi ja vanhurskaus niinkuin ehtymätön puro.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Toitteko te teurasuhreja ja ruokauhreja minulle erämaassa neljänäkymmenenä vuotena, te Israelin heimo?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Te olette kantaneet kuningastanne Sikkutia ja Kijjunin-kuvianne, tähtijumalaanne, sitä, jonka te olette itsellenne tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Sentähden minä vien teidät pakkosiirtolaisuuteen tuolle puolelle Damaskon, sanoo Herra. Jumala Sebaot on hänen nimensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Voi suruttomia Siionissa, huolettomia Samarian vuorella, kansoista ensimmäisen ylimyksiä, joiden tykö Israelin heimo tulee!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Menkää Kalneen ja katsokaa, sieltä kulkekaa Suureen Hamatiin ja käykää filistealaisten Gatiin: ovatko ne paremmat kuin nämä valtakunnat, onko niiden alue suurempi kuin teidän alueenne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Voi teitä, jotka lykkäätte kauas pahan päivän, mutta vedätte luoksenne väkivallan, valtaistuimelle istumaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'jotka makaatte norsunluusohvilla ja venytte leposijoillanne, syötte karitsoita laumasta ja vasikoita navetasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'jotka sepustatte lauluja harpulla säestäen ja sommittelette soittimia kuin mikäkin Daavid;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'jotka juotte viiniä maljoista ja voitelette itsenne parhaalla öljyllä, mutta ette murehdi Joosefin sortumista!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Sentähden heidän nyt täytyy mennä pakkosiirtolaisuuteen pakkosiirtolaisten etunenässä. Silloin lakkaavat venyjäin ilohuudot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Herra, Herra on vannonut itse kauttansa, sanoo Herra, Jumala Sebaot: Jaakobin ylpeys on minulle kauhistus, minä vihaan hänen palatsejansa, ja minä jätän alttiiksi kaupungin kaikkinensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Ja jos silloin kymmenen miestä jää jäljelle yhteen taloon, niin he kuolevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Ja jos kuolleen korjaa hänen omaisensa ja polttajansa, viedäkseen luut pois talosta, ja jos hän kysyy joltakin, joka on talon perimmäisessä sopessa: \"Onko sinun tykönäsi vielä ketään?\" niin tämä vastaa: \"Ei ole\", ja toinen sanoo: \"Hiljaa!\" -sillä Herran nimeä ei saa mainita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Sillä katso, Herra antaa käskyn, ja hän lyö suuren talon kappaleiksi ja pienen talon pirstaleiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Juoksevatko hevoset kallionseinää, kynnetäänkö sitä härjillä? Sillä te muutatte oikeuden myrkyksi ja vanhurskauden hedelmän koiruohoksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'te, jotka iloitsette Loodabarista ja jotka sanotte: \"Emmekö omalla voimallamme valloittaneet Karnaimia?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Sillä katso, minä nostatan teitä vastaan, te Israelin heimo, sanoo Herra, Jumala Sebaot, kansan, joka on ahdistava teitä siitä asti, mistä mennään Hamatiin, hamaan Pajupuroon saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Tämän näytti minulle Herra, Herra: Katso, hän loi heinäsirkkoja, kun äpäreheinä alkoi nousta; ja katso, se oli äpäreheinä kuninkaan niitosten jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Ja kun ne olivat syöneet loppuun maan kasvit, sanoin minä: \"Herra, Herra, anna anteeksi. Kuinka voi Jaakob pysyä, sillä hän on vähäinen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Niin Herra katui sitä. \"Ei se ole tapahtuva\", sanoi Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Tämän näytti minulle Herra, Herra: Katso, Herra, Herra kutsui tulen toimittamaan tuomiota, ja se kulutti suuren syvyyden, ja se kulutti peltomaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Niin minä sanoin: \"Herra, Herra, lakkaa jo. Kuinka voi Jaakob pysyä, sillä hän on vähäinen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Niin Herra katui sitä. \"Ei sekään ole tapahtuva\", sanoi Herra, Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Tämän hän näytti minulle: Katso, Herra seisoi pystysuoralla muurilla, kädessänsä luotilanka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Ja Herra sanoi minulle: \"Mitä sinä näet, Aamos?\" Minä vastasin: \"Luotilangan\". Ja Herra sanoi minulle: \"Katso, minä olen laskenut luotilangan kansani Israelin keskelle. Minä en enää mene säästäen sen ohitse,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'vaan Iisakin uhrikukkulat tulevat autioiksi ja Israelin pyhäköt raunioiksi. Ja minä nousen ja nostan miekan Jerobeamin sukua vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Silloin Amasja, Beetelin pappi, lähetti Jerobeamille, Israelin kuninkaalle, tämän sanan: \"Aamos on tehnyt salaliiton sinua vastaan Israelin heimon keskuudessa. Ei maa kestä kaikkea, mitä hän puhuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Sillä näin on Aamos sanonut: \'Jerobeam kuolee miekkaan, ja Israel viedään pakkosiirtolaisuuteen, pois omasta maastansa\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Ja Amasja sanoi Aamokselle: \"Sinä näkijä, mene matkaasi ja pakene Juudan maahan, syö leipäsi siellä ja ennusta siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Mutta Beetelissä älä ennusta enää, sillä se on kuninkaan pyhäkkö ja valtakunnan temppeli.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Niin Aamos vastasi ja sanoi Amasjalle: \"En minä ole profeetta enkä profeetanoppilas, vaan minä olen paimen ja metsäviikunapuiden viljelijä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Ja Herra otti minut laumojeni äärestä, ja Herra sanoi minulle: \'Mene ja ennusta minun kansaani Israelia vastaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Kuule siis nyt Herran sana: Sinä sanot: \'Älä ennusta Israelia vastaan, äläkä saarnaa Iisakin heimoa vastaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Sentähden, näin sanoo Herra: Sinun vaimosi joutuu portoksi kaupungissa, sinun poikasi ja tyttäresi kaatuvat miekkaan, sinun maasi jaetaan mittanuoralla, sinä itse kuolet saastaisessa maassa, ja Israel viedään pakkosiirtolaisuuteen, pois omasta maastansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Tämän näytti minulle Herra, Herra: Katso, oli korillinen kypsiä hedelmiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Ja hän sanoi: \"Mitä sinä näet, Aamos?\" Minä vastasin: \"Korillisen kypsiä hedelmiä\". Ja Herra sanoi minulle: \"Minun kansani Israel on kypsä saamaan loppunsa: en minä enää mene säästäen sen ohitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Ja sinä päivänä palatsin laulut muuttuvat valitukseksi, sanoo Herra, Herra. Paljon on oleva ruumiita, joka paikkaan heitettyjä. Hiljaa!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Kuulkaa tämä, te jotka poljette köyhiä ja tahdotte tehdä lopun maan nöyristä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'sanoen: \"Milloin loppuu uusikuu, että saamme myydä viljaa, ja milloin sapatti, että saamme avata jyväaitan, pienentää eefa-mitan ja suurentaa painon ja pettää väärällä vaa\'alla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'että saamme ostaa vaivaiset rahasta ja köyhän kenkäparista ja myydä akanoita jyvinä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Herra on vannonut hänen kauttansa, joka on Jaakobin kunnia: Totisesti, minä en ikinä unhota yhtäkään heidän tekoansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Eikö senkaltaisesta maa jo vapise ja kaikki sen asukkaat murehdi? Eikö se nouse kaikkinensa niinkuin Niili, kuohu ja alene niinkuin Egyptin virta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'Ja on tapahtuva sinä päivänä, sanoo Herra, Herra, että minä annan auringon laskea sydänpäivällä ja teen maan pimeäksi keskellä kirkasta päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Minä muutan teidän juhlanne murheeksi ja kaikki teidän laulunne valitusvirsiksi. Minä panen kaikkien lanteille säkkipuvun ja teen kaljuksi jokaisen pään. Ja minä saatan teidät suremaan, niinkuin ainokaista poikaa surraan, ja se päättyy, niinkuin päättyy katkera päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Katso, päivät tulevat, sanoo Herra, Herra, jolloin minä lähetän nälän maahan: en leivän nälkää enkä veden janoa, vaan Herran sanojen kuulemisen nälän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Silloin he hoippuvat merestä mereen, pohjoisesta itään; he samoavat etsien Herran sanaa, mutta eivät löydä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Sinä päivänä nääntyvät janoon kauniit neitsyet ja nuorukaiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'ne, jotka vannovat sen nimeen, joka on Samarian syntivelka, ja sanovat: \"Niin totta kuin sinun jumalasi elää, Daan, ja niin totta kuin elävät Beerseban menot!\" -He kaatuvat eivätkä enää nouse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Minä näin Herran seisovan alttarin ääressä, ja hän sanoi: Lyö pylväänpäihin, niin että kynnykset vapisevat, lyö ne pirstaleiksi kaikkien heidän päähänsä. Sitten minä tapan miekalla heistä viimeisetkin. Ei yksikään heistä pääse pakoon, ei yksikään heistä pelastu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Vaikka he tuonelaan murtautuisivat, sieltäkin minun käteni heidät tempaa. Vaikka he taivaaseen nousisivat, sieltäkin minä syöksen heidät alas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Vaikka he Karmelin laelle kätkeytyisivät, sieltäkin minä etsin ja tempaan heidät. Ja vaikka he meren pohjaan lymyäisivät minun silmieni edestä, sielläkin minä käsken käärmeen heitä pistämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Ja vaikka he vankeuteen vaeltaisivat vihollistensa edessä, sielläkin minä käsken miekan heidät tappamaan. Sillä minä kiinnitän katseeni heihin, heille pahaksi, ei hyväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Herra, Herra Sebaot, hän, joka koskettaa maata, niin että se sulaa, että kaikki sen asukkaat murehtivat, että se nousee kaikkinensa niinkuin Niili ja alenee niinkuin Egyptin virta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'hän, joka rakentaa yliskammionsa taivaisiin ja perustaa holvinsa maan päälle, joka kutsuu meren vedet ja vuodattaa ne maan pinnalle-Herra on hänen nimensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Ettekö te, israelilaiset, ole minulle niinkuin etiopialaisetkin? sanoo Herra. Enkö minä johdattanut israelilaisia Egyptin maasta ja filistealaisia Kaftorista ja aramilaisia Kiiristä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Katso, Herran, Herran silmät ovat syntistä valtakuntaa vastaan, ja minä hävitän sen maan pinnalta; kuitenkaan en minä Jaakobin heimoa kokonaan hävitä, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Sillä katso, minä käsken seuloa Israelin heimoa kaikkien kansain seassa, niinkuin seulalla seulotaan: ei jyvääkään putoa maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Miekkaan kuolevat kaikki minun kansani syntiset, jotka sanovat: \"Ei saavuta, ei kohtaa meitä onnettomuus\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Sinä päivänä minä pystytän jälleen Daavidin sortuneen majan ja korjaan sen repeämät ja pystytän sen luhistumat, ja rakennan sen sellaiseksi, kuin se oli muinaisina päivinä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'niin että he saavat omiksensa Edomin jäännöksen ja kaikki pakanakansat, jotka minun nimiini otetaan, sanoo Herra, joka tämän tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Katso, päivät tulevat, sanoo Herra, jolloin kyntäjä tavoittaa leikkaajan ja rypäleitten polkija siemenenkylväjän, jolloin vuoret tiukkuvat rypälemehua ja kaikki kukkulat kuohkeiksi muuttuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Silloin minä käännän kansani Israelin kohtalon, ja he rakentavat jälleen autiot kaupungit ja asuvat niissä, he istuttavat viinitarhoja ja juovat niiden viiniä, he tekevät puutarhoja ja syövät niiden hedelmiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Minä istutan heidät omaan maahansa, eikä heitä enää revitä pois maastansa, jonka minä olen heille antanut, sanoo Herra, sinun Jumalasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Obadjan näky. Herra, Herra sanoo Edomista näin: Me olemme kuulleet sanoman Herralta, ja sanansaattaja on lähetetty kansakuntiin: \"Nouskaa, nouskaamme sotaan sitä vastaan!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Katso, vähäiseksi minä teen sinut kansojen seassa, ylen halveksittu olet sinä oleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Sinun sydämesi ylpeys on pettänyt sinut, joka asut kallionrotkoissa, istut korkealla ja sanot sydämessäsi: \"Kuka voi syöstä minut maahan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Vaikka tekisit pesäsi korkealle niinkuin kotka ja vaikka sen sija olisi tähtien välissä, minä syöksen sinut sieltä alas, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Jos varkaat tulisivat kimppuusi, jos yölliset rosvot, kuinka voisit tulla niin hävitetyksi: eivätkö he varastaisi vain sen, mitä tarvitsevat? Jos viininkorjaajat tulisivat luoksesi, eivätkö he jättäisi jälkikorjuuta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Mutta kuinka onkaan Eesau läpikotaisin etsitty, hänen kätkönsä pengotut!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Sinut on ajettu rajalle asti, kaikki liittolaisesi ovat sinut pettäneet. Ystäväsi ovat vieneet sinusta voiton, ovat panneet taritsemasi leivän paulaksi sinun eteesi. -Ei ole hänessä taitoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Totisesti, sinä päivänä, sanoo Herra, minä lopetan viisaat Edomista ja taidon Eesaun vuorelta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Ja sinun sankarisi, Teeman, kauhistuvat, niin että viimeinenkin mies häviää Eesaun vuorelta murhatöitten tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Väkivallan tähden veljeäsi Jaakobia kohtaan peittää sinut häpeä, ja sinut hävitetään ikiajoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Sinä päivänä, jona sinäkin olit läsnä, päivänä, jona vieraat veivät pois hänen rikkautensa, jona muukalaiset tunkeutuivat sisään hänen porteistaan ja heittivät Jerusalemista arpaa, olit myöskin sinä niinkuin yksi heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Mutta älä katso iloiten veljesi päivää, hänen onnettomuutensa päivää; älä ilku juutalaisia heidän turmionsa päivänä äläkä suullasi suurentele ahdistuksen päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Älä tunkeudu sisään minun kansani portista heidän hätäpäivänänsä. Älä katso iloiten, myös sinä, hänen onnettomuuttansa hänen hätäpäivänänsä. Älä ojenna kättäsi hänen rikkauteensa hänen hätäpäivänänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Älä seiso tienhaarassa hävittämässä hänen pelastuneitansa. Älä luovuta hänen pakoonpäässeitänsä ahdistuksen päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Sillä lähellä on Herran päivä kaikkia pakanakansoja: Niinkuin sinä olet tehnyt, niin sinulle tehdään; kosto sinun teostasi kohtaa sinun omaa päätäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Sillä niinkuin te olette juoneet minun pyhällä vuorellani, niin tulevat kaikki pakanakansat juomaan ainiaan: he juovat ja särpivät ja ovat, niinkuin ei heitä olisi ollutkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Mutta Siionin vuorella saavat olla pelastuneet, ja se on oleva pyhä, ja Jaakobin heimo on perivä perintönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Jaakobin heimo on oleva tuli ja Joosefin heimo liekki, mutta Eesaun heimo kuin olki, ja ne polttavat sen ja kuluttavat sen; eikä jää pakoonpäässyttä Eesaun heimosta. Sillä Herra on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Ja he ottavat perinnöksensä Etelämaan ynnä Eesaun vuoren, Alankomaan ynnä filistealaiset; he ottavat perinnöksensä Efraimin maan ja Samarian maan, Benjaminin ynnä Gileadin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Ja tästä väestä, israelilaisista, viedyt pakkosiirtolaiset ottavat perinnöksensä kanaanilaiset Sarpatiin asti. Ja Jerusalemin pakkosiirtolaiset, jotka ovat Sefaradissa, ottavat perinnöksensä Etelämaan kaupungit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Pelastajat nousevat Siionin vuorelle tuomitsemaan Eesaun vuorta. Ja kuninkuus on oleva Herran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Joonalle, Amittain pojalle, tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, '\"Nouse, mene Niiniveen, siihen suureen kaupunkiin, ja saarnaa sitä vastaan; sillä heidän pahuutensa on noussut minun kasvojeni eteen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Mutta Joona nousi paetaksensa Tarsiiseen Herran kasvojen edestä ja meni alas Jaafoon ja löysi laivan, joka oli lähtevä Tarsiiseen. Ja hän suoritti laivamaksun ja astui siihen mennäkseen heidän kanssansa Tarsiiseen, pois Herran kasvojen edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Mutta Herra heitti suuren tuulen merelle, niin että merellä nousi suuri myrsky ja laiva oli särkymäisillään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Niin merimiehet pelkäsivät ja huusivat avuksi itsekukin jumalaansa. Ja he heittivät mereen tavarat, mitä laivassa oli, keventääkseen sitä. Mutta Joona oli mennyt alas laivan pohjalle ja pannut maata, ja hän nukkui raskaasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Niin laivuri tuli hänen luoksensa ja sanoi hänelle: \"Mitäs nukut? Nouse ja huuda jumalaasi. Ehkäpä se jumala muistaa meitä, niin ettemme huku.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Ja he sanoivat toisillensa: \"Tulkaa, heittäkäämme arpaa, saadaksemme tietää, kenen tähden tämä onnettomuus on meille tullut\". Mutta kun he heittivät arpaa, lankesi arpa Joonalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Niin he sanoivat hänelle: \"Ilmoita meille, kenen tähden tämä onnettomuus on meille tullut. Mikä on toimesi ja mistä tulet? Mikä on sinun maasi ja mistä kansasta olet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Hän vastasi heille: \"Minä olen hebrealainen, ja minä pelkään Herraa, taivaan Jumalaa, joka on tehnyt meren ja kuivan maan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Niin miehet peljästyivät suuresti ja sanoivat hänelle: \"Miksi olet tehnyt näin?\" Sillä miehet tiesivät, että hän oli pakenemassa Herran kasvojen edestä; hän oli näet ilmaissut sen heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'He sanoivat hänelle: \"Mitä on meidän tehtävä sinulle, että meri tulisi meille tyveneksi?\" Sillä meri myrskysi myrskyämistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Hän vastasi heille: \"Ottakaa minut ja heittäkää minut mereen, niin meri teille tyventyy. Sillä minä tiedän, että tämä suuri myrsky on tullut teille minun tähteni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Miehet soutivat päästäkseen jälleen kuivalle maalle, mutta eivät voineet, sillä meri myrskysi vastaan myrskyämistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Ja he huusivat Herraa ja sanoivat: \"Voi, Herra, älä anna meidän hukkua tämän miehen hengen tähden äläkä lue syyksemme viatonta verta, sillä sinä, Herra, teet, niinkuin sinulle otollista on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Sitten he ottivat Joonan ja heittivät hänet mereen, ja meri asettui raivostansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Ja miehet pelkäsivät suuresti Herraa, uhrasivat Herralle teurasuhrin ja tekivät lupauksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, '{2:1} Mutta Herra toimitti suuren kalan nielaisemaan Joonan. Ja Joona oli kalan sisässä kolme päivää ja kolme yötä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, '{2:2} Ja Joona rukoili Herraa, Jumalaansa, kalan sisässä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, '{2:3} ja sanoi: \"Minä huusin ahdistuksessani Herraa, ja hän vastasi minulle. Tuonelan kohdussa minä huusin apua, ja sinä kuulit minun ääneni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, '{2:4} Sinä syöksit minut syvyyteen, merten sydämeen, ja virta ympäröitsi minut, kaikki sinun kuohusi ja aaltosi vyöryivät minun ylitseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, '{2:5} Minä ajattelin: Olen karkoitettu pois sinun silmiesi edestä. Kuitenkin minä saan vielä katsella sinun pyhää temppeliäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, '{2:6} Vedet piirittivät minut aina sieluun asti, syvyys ympäröitsi minut, kaisla kietoutui päähäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, '{2:7} Minä vajosin alas vuorten perustuksiin asti, maan salvat sulkeutuivat minun ylitseni iankaikkisesti. Mutta sinä nostit minun henkeni ylös haudasta, Herra, minun Jumalani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, '{2:8} Kun sieluni nääntyi minussa, minä muistin Herraa, ja minun rukoukseni tuli sinun tykösi, sinun pyhään temppeliisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, '{2:9} Ne, jotka kunnioittavat vääriä jumalia, hylkäävät armonantajansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, '{2:10} Mutta minä tahdon uhrata sinulle kiitoksen kaikuessa. Mitä olen luvannut, sen minä täytän. Herrassa on pelastus.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, '{2:11} Sitten Herra käski kalaa, ja se oksensi Joonan kuivalle maalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Joonalle tuli toistamiseen tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, '\"Nouse ja mene Niiniveen, siihen suureen kaupunkiin, ja saarnaa sille se saarna, minkä minä sinulle puhun\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Niin Joona nousi ja meni Niiniveen Herran sanan mukaan. Ja Niinive oli suuri kaupunki Jumalan edessä: kolme päivänmatkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Ja Joona käveli kaupungissa aluksi yhden päivänmatkan ja saarnasi sanoen: \"Vielä neljäkymmentä päivää, ja Niinive hävitetään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Niin Niiniven miehet uskoivat Jumalaan, kuuluttivat paaston ja pukeutuivat säkkeihin, niin suuret kuin pienet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Ja kun tieto tästä tuli Niiniven kuninkaalle, nousi hän valtaistuimeltaan, riisui yltään vaippansa, verhoutui säkkiin ja istui tuhkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Ja hän huudatti Niinivessä: \"Kuninkaan ja hänen ylimystensä määräys kuuluu: Älkööt ihmiset älköötkä eläimet-raavaat ja lampaat-maistako mitään, käykö laitumella tai vettä juoko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Verhoutukoot ihmiset ja eläimet säkkeihin, huutakoot väkevästi Jumalaa ja kääntykööt itsekukin pois pahalta tieltänsä sekä väkivallasta, mikä heidän käsiänsä tahraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Ehkäpä Jumala jälleen katuu ja kääntyy vihansa hehkusta, niin ettemme huku.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Kun Jumala näki heidän tekonsa, että he kääntyivät pois pahalta tieltänsä, niin Jumala katui sitä pahaa, minkä hän oli sanonut tekevänsä heille, eikä tehnyt sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Mutta Joona pahastui tästä kovin, ja hän vihastui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Ja hän rukoili Herraa ja sanoi: \"Voi Herra! Enkö minä sitä sanonut, kun olin vielä omassa maassani? Siksihän minä ehätin pakenemaan Tarsiiseen. Sillä minä tiesin, että sinä olet armahtavainen ja laupias Jumala, pitkämielinen ja armosta rikas, ja että sinä kadut pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Ja nyt, Herra, ota minun henkeni, sillä kuolema on minulle parempi kuin elämä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Mutta Herra sanoi: \"Onko vihastumisesi oikea?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Niin Joona lähti kaupungista ja asettui kaupungin itäpuolelle. Hän teki itsellensä sinne lehtimajan ja kävi istumaan sen alle varjoon, kunnes näkisi, miten kaupungin oli käyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Mutta Herra Jumala toimitti risiinikasvin kasvamaan Joonan pään ylitse, varjostamaan hänen päätänsä ja päästämään häntä hänen mielipahastaan. Ja Joona iloitsi suuresti risiinikasvista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Mutta seuraavana päivänä, aamun sarastaessa, Jumala toimitti madon kalvamaan risiinikasvia, niin että se kuivui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Ja auringon noustua Jumala toimitti tulikuuman itätuulen, ja aurinko paahtoi Joonaa päähän, niin että häntä näännytti. Niin hän toivotti itsellensä kuolemaa ja sanoi: \"Parempi on minulle kuolema kuin elämä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Mutta Jumala sanoi Joonalle: \"Onko vihastumisesi risiinikasvin tähden oikea?\" Tämä vastasi: \"Oikea on vihastumiseni kuolemaan asti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Niin Herra sanoi: \"Sinä armahdat risiinikasvia, josta et ole vaivaa nähnyt ja jota et ole kasvattanut, joka yhden yön lapsena syntyi ja yhden yön lapsena kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Enkö siis minä armahtaisi Niiniveä, sitä suurta kaupunkia, jossa on enemmän kuin sata kaksikymmentä tuhatta ihmistä, jotka eivät vielä tiedä, kumpi käsi on oikea, kumpi vasen, niin myös paljon eläimiä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Herran sana, joka tuli mooresetilaiselle Miikalle Jootamin, Aahaan ja Hiskian, Juudan kuningasten, päivinä; se, mitä hän näki Samariaa ja Jerusalemia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Kuulkaa, kaikki kansat; ota korviisi, maa, ja kaikki, mitä maassa on. Ja olkoon Herra, Herra todistaja teitä vastaan, Herra pyhästä temppelistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Sillä katso, Herra lähtee asumuksestaan, astuu alas ja polkee maan kukkuloita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Vuoret sulavat hänen allansa, ja laaksot halkeavat niinkuin vaha tulen hohteessa, niinkuin vedet, jotka syöksyvät jyrkännettä alas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Jaakobin rikoksen tähden tapahtuu tämä kaikki ja Israelin heimon syntien tähden. Mistä on Jaakobin rikos? Eikö Samariasta! Ja mistä Juudan uhrikukkulat? Eivätkö Jerusalemista!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Niinpä minä panen Samarian kiviraunioksi kedolle, viinitarhan istutusmaaksi, syöksen laaksoon sen kivet ja paljastan sen perustukset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Kaikki sen jumalankuvat särjetään, kaikki sen portonpalkat poltetaan tulessa, ja kaikki sen epäjumalankuvat minä hävitän; sillä portonpalkoista se on ne koonnut, ja portonpalkoiksi pitää niitten jälleen tuleman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Tämän tähden minä tahdon valittaa ja voivotella, käydä avojaloin ja vaipatta, virittää valituslaulun kuin aavikkosudet, suruhuudon kuin kamelikurjet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Sillä parantumaton on sen haava; se ulottuu Juudaan asti, se käy minun kansani porttiin saakka, aina Jerusalemiin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Älkää ilmoittako sitä Gatissa, älkää, älkää itkekö. Minä vieriskelen tuhassa Beet-Leafrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Käy matkaan, Saafirin asujatar, häpeällisesti paljastettuna! Saananin asujatar ei lähde. Beet-Eselin valitus riistää teiltä pysähdyspaikan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Onnea odottaa tuskaisesti Maarotin asujatar; mutta onnettomuus tulee Herralta Jerusalemin portille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Valjasta hevoset vaunujen eteen, Laakiin asujatar; sieltä on alku tytär Siionin syntiin, sillä sinussa tavattiin Israelin rikokset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Sentähden sinä annat eron Mooreset-Gatille. Aksibin talot tulevat olemaan pettymys Israelin kuninkaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Minä tuon vieläkin perijän sinulle, Maaresan asujatar. Adullamiin asti kulkee Israelin kunnia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Ajele ja keritse pääsi paljaaksi lasten tähden, jotka olivat sinun ilosi. Ajele pääsi leveälti paljaaksi, niinkuin on korppikotkalla, sillä he menevät luotasi pois pakkosiirtolaisuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Voi niitä, jotka miettivät turmiota ja valmistelevat pahaa vuoteillansa! Aamun valjettua he sen tekevät, sillä heillä on siihen valta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'He himoitsevat peltoja ja ryöstävät ne, taloja, ja ottavat ne; he sortavat miestä ja hänen taloansa, miestä ja hänen perintöosaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Sentähden, näin sanoo Herra: Katso, minä mietin tätä sukua vastaan onnettomuutta: siitä te ette saa kaulaanne irti ettekä voi ylpeästi astella; sillä se on oleva paha aika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Sinä päivänä viritetään teistä pilkkalaulu ja veisataan valitusvirsi. \"Se on tapahtunut\", sanotaan, \"me olemme perin hävitetyt, hän on vaihtanut pois minun kansani osan. Kuinka hän siirtää sen minulta pois! Hän jakaa meidän peltomme luopioille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Sentähden ei sinulla ole oleva ketään, joka heittäisi arpaa maaosuudesta Herran seurakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '\"Älkää saarnatko\", saarnaavat he, \"sellaisista ei pidä saarnata; eikö väisty pois häpäiseminen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Onko tämä Jaakobin heimon puhetta? Onko Herra pikavihainen? Ovatko sellaisia hänen tekonsa? Eivätkö hänen puheensa ole hyvät sitä kohtaan, joka oikein vaeltaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Mutta aikoja sitten on minun kansani asettunut viholliseksi; vaatteiden päältä te kiskotte vaipan niiltä, jotka huoleti kulkevat, jotka sotaa väistävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Minun kansani naiset te ajatte pois heidän kodeistansa, jotka ovat heidän ilonsa; heidän pieniltä lapsiltansa te otatte minun kunniani ainiaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Nouskaa ja menkää pois: ei tässä ole leposijaa saastutuksen tähden, joka on saanut aikaan turmion, parantumattoman turmion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Jos tulisi mies, joka tuulta tavoittelisi ja petollisuudessaan valhettelisi: \"Minä saarnaan sinulle viinistä ja väkijuomasta\", siinä olisi saarnaaja tälle kansalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Minä tahdon tarkoin koota sinut, Jaakob, kaikkinesi, visusti kerätä Israelin jääneet, saattaa heidät yhteen, niinkuin lampaat tarhaan, niinkuin lauman laitumellensa: on oleva ihmisten kohina!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Tien aukaisija käy heidän edellänsä; he aukaisevat tiensä, kulkevat portille ja lähtevät siitä ulos. Heidän kuninkaansa käy heidän edellään, ja Herra heitä johdattaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Ja minä sanoin: Kuulkaa, Jaakobin päämiehet ja Israelin heimon ruhtinaat! Eikö teidän tulisi tuntea oikeus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'teidän, jotka vihaatte hyvää ja rakastatte pahaa, jotka raastatte ihmisten nahan heidän päältänsä ja lihan irti heidän luistansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Ne, jotka syövät minun kansani lihan ja nylkevät nahan heidän päältänsä ja murskaavat heidän luunsa, paloittelevat niinkuin pataan, niinkuin lihan kattilaan-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'kerran he huutavat Herran puoleen, mutta hän ei vastaa heille, vaan kätkee heiltä kasvonsa sinä aikana, koska he ovat pahoja töitä tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Näin sanoo Herra niitä profeettoja vastaan, jotka eksyttävät minun kansaani, jotka huutavat: \"Rauha!\", kun heidän hampaissaan on purtavaa, mutta julistavat pyhän sodan sille, joka ei anna mitään heidän suuhunsa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Sentähden tulee teille yö, näkyjä vailla, teille tulee pimeys, ennustelua vailla. Aurinko laskee näiltä profeetoilta, ja päivä heiltä pimenee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Näkijät joutuvat häpeään, ja ennustelijat punastuvat. Kaikki he peittävät partansa, sillä Jumalan vastausta ei tule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Mutta minä olen täynnä voimaa, Herran Henkeä, oikeutta ja väkevyyttä ilmoittaakseni Jaakobille sen rikokset ja Israelille sen synnit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Kuulkaa tämä, Jaakobin heimon päämiehet ja Israelin heimon ruhtinaat, te, jotka halveksitte oikeutta ja vääristätte kaiken suoran,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'rakennatte Siionia veritöillä ja Jerusalemia vääryydellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Sen päämiehet jakavat oikeutta lahjuksia vastaan, sen papit opettavat maksusta, ja sen profeetat ennustelevat rahasta. Mutta Herraan he turvautuvat, sanoen: \"Eikö Herra ole meidän keskellämme? Ei tule meille onnettomuutta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Siitä syystä, teidän tähtenne, Siion kynnetään pelloksi, Jerusalem tulee kiviraunioksi ja temppelivuori metsäkukkulaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Aikojen lopussa on Herran temppelin vuori seisova vahvana, ylimmäisenä vuorista, ja se on oleva korkein kukkuloista, ja sinne virtaavat kansat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Monet pakanakansat lähtevät liikkeelle sanoen: \"Tulkaa, nouskaamme Herran vuorelle, Jaakobin Jumalan temppeliin, että hän opettaisi meille teitänsä ja me vaeltaisimme hänen polkujansa; sillä Siionista lähtee laki, Jerusalemista Herran sana.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Ja hän tuomitsee monien kansojen kesken, säätää oikeutta väkeville pakanakansoille, kaukaisiin maihin saakka. Niin he takovat miekkansa vantaiksi ja keihäänsä vesureiksi; kansa ei nosta miekkaa kansaa vastaan, eivätkä he enää opettele sotimaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'He istuvat kukin oman viinipuunsa ja viikunapuunsa alla kenenkään peljättämättä. Sillä Herran Sebaotin suu on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Sillä kaikki kansat vaeltavat jumalansa nimessä kukin, mutta me vaellamme Herran, meidän Jumalamme, nimessä aina ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'Sinä päivänä, sanoo Herra, minä tahdon koota ontuvat ja kerätä hajalleen-ajetut ja ne, joille minä olin tuottanut onnettomuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Minä teen ontuvista talteenjäävät ja kauasjoutuneista väkevän kansan. Ja Herra on oleva heidän kuninkaansa Siionin vuorella siitä alkaen ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Ja sinä Karjatorni, tytär Siionin kukkula! Sinun luoksesi on tuleva, on saapuva entinen hallitus, tytär Jerusalemia vallinnut kuninkuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Ja nyt-miksi sinä ääneen vaikeroit? Eikö sinulla ole kuningasta, onko sinun neuvonantajasi kadonnut, koska kipu on vallannut sinut niinkuin synnyttäväisen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Vääntelehdi vain kouristuksissasi, tytär Siion, niinkuin synnyttäjä, sillä nyt sinun on lähdettävä ulos kaupungista ja asuttava kedolla ja mentävä Baabeliin asti: siellä sinut pelastetaan; siellä lunastaa sinut Herra vihamiestesi käsistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Nyt kokoontuu sinua vastaan paljon pakanoita, jotka sanovat: \"Se saastutettakoon; katselkoot meidän silmämme iloksensa Siionia!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Mutta he eivät tunne Herran aivoituksia eivätkä ymmärrä hänen neuvoansa, sillä hän kokoaa heidät niinkuin lyhteet puimatantereelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Nouse ja pui, tytär Siion, sillä minä annan sinulle rautasarvet ja vaskisorkat minä sinulle annan, ja sinä survot murskaksi monet kansat. Ja minä vihin Herralle, tuhon omaksi, heidän väärän voittonsa, kaiken maan Herralle heidän rikkautensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Nyt yhdy laumaksi, sinä hyökkääjäin ahdistama tytär! Meitä piiritetään, he lyövät sauvalla poskelle Israelin tuomaria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, '{5:1} Mutta sinä, Beetlehem Efrata, joka olet vähäinen olemaan Juudan sukujen joukossa, sinusta minulle tulee se, joka on oleva hallitsija Israelissa, jonka alkuperä on muinaisuudesta, iankaikkisista ajoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, '{5:2} Sentähden Herra antaa heidät alttiiksi siihen aikaan asti, jolloin synnyttäjä on synnyttänyt; silloin jäljellejääneet hänen veljistänsä palajavat israelilaisten luokse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, '{5:3} Ja hän on astuva esiin ja kaitseva Herran voimassa, Herran, Jumalansa, nimen valtasuuruudessa. Ja he asuvat alallansa, sillä silloin on hän oleva suuri hamaan maan ääriin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, '{5:4} Ja hän on oleva rauha: jos Assur hyökkää maahamme, jos se astuu palatseihimme, niin me asetamme sitä vastaan seitsemän paimenta ja kahdeksan ruhtinasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, '{5:5} Nämä kaitsevat miekalla Assurin maata, Nimrodin maata sen omain ovien ääressä. Hän on pelastava meidät Assurin vallasta, jos se hyökkää meidän maahamme, jos se astuu meidän alueellemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, '{5:6} Ja ne, jotka ovat jäljellä Jaakobista monien kansain seassa, ovat niinkuin kaste, joka tulee Herralta, niinkuin sadekuuro ruohikolle; se ei odota miestä, ei varro ihmislapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, '{5:7} Ja ne, jotka ovat jäljellä Jaakobista, pakanain seassa, monien kansain keskellä, ovat niinkuin leijona metsäneläinten seassa, niinkuin nuori jalopeura lammaslaumain keskellä: jos se hyökkää, tallaa maahan ja raatelee, ei pelastajaa ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, '{5:8} Kohotkoon sinun kätesi vihollisiasi vastaan, ja sinun vihamiehesi hävitkööt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, '{5:9} Sinä päivänä, sanoo Herra, minä hävitän sinulta hevosesi ja teen lopun sinun vaunuistasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, '{5:10} Minä hävitän sinun maasi kaupungit ja hajotan maahan kaikki sinun varustuksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, '{5:11} Minä hävitän loitsut sinun käsistäsi, eikä sinulle enää jää ennustelijoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, '{5:12} Minä hävitän sinun jumalankuvasi ja patsaasi, etkä sinä enää kumarra kättesi tekoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, '{5:13} Minä kukistan asera-karsikkosi sinun keskuudestasi ja tuhoan sinun kaupunkisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, '{5:14} Ja minä kostan vihassa ja kiivaudessa pakanakansoille, jotka eivät olleet kuuliaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Kuulkaa, mitä Herra sanoo: Nouse ja käy oikeutta vuorten kanssa, ja kukkulat kuulkoot sinun äänesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Kuulkaa Herran oikeudenkäyntiä, vuoret, te iäti kestävät, maan perustukset; sillä oikeudenkäynti on Herralla kansaansa vastaan, ja Israelin kanssa hän käy tuomiolle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, '\"Minun kansani, mitä minä olen sinulle tehnyt, ja millä olen sinut väsyttänyt? Vastaa minulle!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Minähän olen johdattanut sinut Egyptin maasta, vapahtanut sinut orjuuden pesästä; ja minä lähetin Mooseksen, Aaronin ja Mirjamin käymään sinun edelläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Muista, kansani, mitä oli mielessä Baalakilla, Mooabin kuninkaalla, ja mitä Bileam, Beorin poika, hänelle vastasi, Sittimistä lähtien Gilgaliin asti, että käsittäisit Herran vanhurskaat teot.\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, '\"Mitä tuoden minä voisin käydä Herran eteen, kumartua korkeuden Jumalan eteen? Käynkö hänen eteensä tuoden polttouhreja, vuodenvanhoja vasikoita?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Ovatko Herralle mieleen tuhannet oinaat, kymmenettuhannet öljyvirrat? Annanko esikoiseni rikoksestani, ruumiini hedelmän sieluni syntiuhriksi?\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Hän on ilmoittanut sinulle, ihminen, mikä hyvä on; ja mitä muuta Herra sinulta vaatii, kuin että teet sitä, mikä oikein on, rakastat laupeutta ja vaellat nöyrästi Jumalasi edessä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Herran ääni huutaa kaupungille-ja ymmärtäväisyyttä on, että sinun nimestäsi otetaan vaari. Totelkaa vitsaa ja häntä, joka on sen määrännyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Vieläkö ovat jumalattoman talossa vääryyden aarteet ja vajaa, kirottu eefa-mitta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Olisinko minä puhdas, jos minulla olisi väärä vaaka ja kukkarossa petolliset punnuskivet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Sen rikkaat ovat täynnä väkivaltaa, sen asukkaat puhuvat valhetta, kieli heidän suussansa on pelkkää petosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Niinpä minäkin lyön sinut sairaaksi, teen sinut autioksi sinun syntiesi tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Sinä syöt, mutta et tule ravituksi, ja sinun vatsassasi on tyhjyys. Minkä viet pois, sitä et saa pelastetuksi; ja minkä pelastetuksi saat, sen minä annan alttiiksi miekalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Sinä kylvät, mutta et leikkaa. Sinä puserrat öljyä, mutta et öljyllä itseäsi voitele, ja rypälemehua, mutta et viiniä juo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Mutta Omrin ohjeita noudatetaan ja kaikkia Ahabin suvun tekoja; ja heidän neuvojensa mukaan te vaellatte, että minä saattaisin sinut autioksi ja sen asukkaat pilkaksi; ja te saatte kantaa minun kansani häväistyksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Voi minua, sillä minun käy niinkuin hedelmänkorjuussa, niinkuin viinisadon jälkikorjuussa: ei ole rypälettä syödäkseni, ei varhaisviikunaa, jota minun sieluni himoitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Poissa ovat hurskaat maasta, eikä oikeamielistä ole ihmisten seassa. Kaikki he väijyvät verta, pyydystävät verkolla toinen toistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Pahantekoon molemmin käsin! Sitä taidolla tekemään! Päämies vaatii, tuomari maksusta tuomitsee, ja mahtava puhuu julki sielunsa himon; senkaltaista he punovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Paras heistä on kuin orjantappura, oikeamielisin pahempi kuin teräväokainen aita. Sinun tähystäjäisi ilmoittama päivä, kosto sinulle, tulee. Silloin he joutuvat sekasortoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Älkää uskoko ystävää, älkää luottako uskottuun; vaimolta, joka sylissäsi lepää, varo suusi ovet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Sillä poika halveksii isää, tytär nousee äitiänsä vastaan, miniä anoppiansa vastaan; ihmisen vihamiehiä ovat hänen omat perhekuntalaisensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Mutta minä panen toivoni Herraan, odotan pelastukseni Jumalaa: minun Jumalani on minua kuuleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Älkää iloitko, minun viholliseni, minusta: jos minä olen langennut, niin minä nousen; jos istun pimeydessä, on Herra minun valkeuteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Minä tahdon kantaa Herran vihaa, sillä minä olen tehnyt syntiä häntä vastaan, siihen asti että hän minun asiani toimittaa ja hankkii minulle oikeuden. Hän tuo minut valkeuteen, minä saan nähdä hänen vanhurskautensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Minun viholliseni saavat nähdä sen, ja häpeä on peittävä heidät, jotka sanovat minulle: \"Missä on Herra, sinun Jumalasi?\" Minun silmäni saavat ilokseen katsoa heitä: silloin he joutuvat tallattaviksi kuin katujen loka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Tulee päivä, jolloin sinun muurisi rakennetaan; sinä päivänä on raja oleva kaukana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'sinä päivänä tullaan sinun tykösi Assurista ja Egyptin kaupungeista, kaikkialta, Egyptistä aina Eufrat-virtaan, merestä mereen, vuoresta vuoreen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Ja maa tulee autioksi asukkaittensa tähden, heidän töittensä hedelmäin takia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Kaitse kansaasi sauvallasi, perintölaumaasi, joka erillänsä asuu metsässä, keskellä Karmelia. Käykööt he laitumella Baasanissa ja Gileadissa niinkuin ikiaikoina ennen. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, '\"Niinkuin sinun lähtösi päivinä Egyptin maasta minä annan hänen nähdä ihmeitä\". -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Sen näkevät pakanakansat ja saavat häpeän kaikesta väkevyydestänsä. He panevat käden suullensa, heidän korvansa menevät lumpeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'He nuolevat tomua kuin käärme, kuin maan matelijat. Vavisten he tulevat varustuksistansa, lähestyvät väristen Herraa, meidän Jumalaamme; he pelkäävät sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Kuka on Jumala, niinkuin sinä olet, joka annat pahat teot anteeksi ja käyt ohitse perintösi jäännöksen rikosten? Ei hän pidä vihaa iäti, sillä hänellä on halu laupeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Hän armahtaa meitä jälleen, polkee maahan meidän pahat tekomme. Kaikki heidän syntinsä sinä heität meren syvyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Sinä osoitat Jaakobille uskollisuutta, Aabrahamille armoa, niinkuin olet vannonut meidän isillemme muinaisista päivistä asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Ennustus Niinivestä. Elkosilaisen Naahumin näyn kirja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Kiivas Jumala ja kostaja on Herra. Herra on kostaja ja vihastuvainen. Herra kostaa vihollisilleen ja pitää vihaa vihamiehillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Herra on pitkämielinen ja suuri voimassansa, mutta Herra ei jätä rankaisematta. Hänen tiensä käy tuulispäässä ja myrskyssä, ja pilvi on hänen jalkojensa tomu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Hän nuhtelee merta ja kuivaa sen, ja kaikki virrat hän ehdyttää. Baasan ja Karmel kuihtuvat, ja Libanonin kukoistus kuihtuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Vuoret järkkyvät hänen edessänsä ja kukkulat sulavat. Hänen kasvojensa voimasta kohoaa maa, maanpiiri ja kaikki sen asuvaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Kuka seisoo hänen tuimuutensa edessä, ja kuka kestää hänen vihansa hehkua? Hänen vihastuksensa vuotaa niinkuin tuli, ja kalliot halkeilevat hänen edessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Hyvä on Herra, turva ahdistuksen päivänä, ja hän tuntee ne, jotka häneen luottavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Mutta paisuvalla tulvalla hän tekee lopun sen paikasta; ja vihamiehiänsä hän ahdistaa pimeydellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Mitä teillä on mielessä Herraa vastaan? Lopun hän tekee: ei nouse ahdistus kahta kertaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Sillä vaikka he olisivat yhteenkietoutuneita kuin orjantappurat ja yhtä märkiä viinistä kuin itse heidän viininsä, heidät syö tuli niinkuin kuivat oljet-kokonansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Sinusta on lähtenyt se, jolla on paha mielessä Herraa vastaan, turmion hankitsija.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Näin sanoo Herra: Olkoot he kuinka täysissä voimissa, olkoon heitä miten paljon tahansa, heidät tuhotaan; mennyttä he ovat. Mutta jos minä olenkin vaivannut sinua en minä sinua enää vaivaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Nyt minä särjen hänen ikeensä painamasta sinua ja katkaisen sinun kahleesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Mutta sinusta on Herra antanut käskyn: Ei kasva enää sinun nimellesi siementä. Minä hävitän sinun jumalasi temppelistä veistetyt ja valetut jumalankuvat. Minä teen sinulle haudan, sillä sinä olet rauennut tyhjiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Katso, jo ovat vuorilla ilosanoman tuojan jalat, hänen, joka julistaa rauhaa: \"Juhli, Juuda, juhliasi, maksa lupauksesi; sillä ei tule enää sinun kimppuusi turmiontuoja, hän on hävitetty kokonansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Hajottaja hyökkää sinua vastaan! Vartioitse varustuksia, tähystä tietä, vahvista vyötäiset, kokoa kaikki voimasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Sillä Herra saattaa entiselleen Jaakobin korkeuden niinkuin myös Israelin korkeuden, sillä ryöstäjät ovat niitä ryöstäneet ja turmelleet niiden viiniköynnökset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Hänen sankariensa kilvet ovat punaiset, urhot purppurapukuiset, sotavaunut säihkyvät teräksen tulta hänen varustautumispäivänänsä, ja kypressikeihäät heiluvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Sotavaunut karkaavat hurjasti kaduilla, syöksyvät sekaisin toreilla; ne ovat nähdä kuin tulenliekit, ne kiitävät kuin salamat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Hän muistaa ylhäisensä. Ne tulevat niin, että kaatuilevat, kiiruhtavat sen muurille. Mutta suojakatos on pantu kuntoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Virranpuoleiset portit on aukaistu, palatsi menehtyy pelkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Päätös on tullut: se on paljastettu, viety pois; ja sen orjattaret huokailevat, kujertaen kuin kyyhkyset, lyöden rintoihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Niinive on ollut kuin vetten täyttämä lammikko päiviensä alusta asti. Nyt ne pakenevat! -\"Seis! Seiskää!\" Mutta yksikään ei käänny.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Ryöstäkää hopeata, ryöstäkää kultaa. Loppumattomat ovat varat, ylen paljon kaikkinaisia kalliita kaluja. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Tyhjänä kaikki, typötyhjänä, hävitettynä! Sydämet raukeavat, polvet tutisevat, kaikki lanteet vapisevat, ja kaikkien kasvot ovat kalpeat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Missä on nyt leijonain tyyssija, nuorten jalopeurain syöntipaikka, jossa leijona käyskenteli, naarasleijona ja leijonanpentu, kenenkään peloittelematta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Leijona raateli, mitä sen pennut tarvitsivat, ja surmasi naarasleijonillensa, täytti luolansa saaliilla ja tyyssijansa raatelemallaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Katso, minä käyn sinun kimppuusi, sanoo Herra Sebaot, poltan savuksi sinun sotavaunusi, ja sinun nuoret jalopeurasi syö miekka. Minä lopetan maan päältä sinun raatelusi, eikä kuulla enää sinun sanansaattajaisi ääntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Voi verivelkojen kaupunkia, joka on täpötäynnä valhetta ja raastosaalista; ei taukoa ryöstäminen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Kuule! Ruoskat läiskyvät, pyörät ryskyvät, hevoset kiitävät, vaunut hyppivät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'ratsut karkaavat pystyyn, miekat välkkyvät, keihäät salamoivat. Paljon kaatuneita, läjittäin ruumiita, loppumatta raatoja! Heidän raatoihinsa lankeillaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Kaikki tämä porton suuren haureuden tähden, tuon ihanan sulottaren, ovelan velhottaren, joka myi kansakunnat haureudellaan, sukukunnat velhouksillansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Katso, minä käyn sinun kimppuusi, sanoo Herra Sebaot, nostan sinun liepeesi kasvojesi yli ja näytän kansakunnille sinun alastomuutesi, valtakunnille sinun häpeäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Ja minä viskaan likaa sinun päällesi, häpäisen sinut ja panen sinut julkinähtäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Ja kaikki, jotka näkevät sinut, kaikkoavat sinusta kauas ja sanovat: \"Hävitetty on Niinive! Kuka sitä surkuttelisi, mistä minä etsisin sinulle lohduttajia?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Oletko sinä parempi, kuin oli Noo-Ammon, joka istui hallitsijana virtojen ääressä, vetten ympäröimänä, jolla oli virta varustuksena ja virta muurina?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Sen väkevyytenä oli Etiopia ja egyptiläiset, joilla ei ollut määrää. Auttajinasi olivat Puut ja liibyalaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Sekin meni pakkosiirtolaisuuteen, vankeuteen. Senkin pienet lapset murskattiin kaikkien katujen kulmissa, sen ylhäisistä heitettiin arpaa, ja kaikki sen suurmiehet pantiin kahleisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Myös sinä olet juopuva ja vaipuva pimeyteen; myös sinä olet etsivä suojaa vihamiehen uhatessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Kaikki sinun varustuksesi ovat viikunapuita, joissa on varhaisviikunoita: jos niitä pudistellaan, ne putoavat syöjän suuhun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Katso, sotaväkesi, mikä sinulla on, on naisia. Sinun maasi portit ovat selkoselällään sinun vihamiehillesi. Tuli kuluttaa sinun salpasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Ammenna itsellesi vettä piirityksen varalta, vahvista varustuksiasi, astu liejuun, polje savea, käy kiinni tiilenmuottiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Siinä on tuli sinut kuluttava, miekka on sinut tuhoava, se on syövä sinut niinkuin syöjäsirkat, vaikka lisääntyisit kuin syöjäsirkat, vaikka lisääntyisit heinäsirkkojen tavoin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Sinä olet lisännyt kauppiaasi lukuisammiksi kuin taivaan tähdet: syöjäsirkat ryöstävät ja lentävät pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Sinulla on ennusmiehiä kuin heinäsirkkoja, kirjureita kuin sirkkaparvea, joka asettuu aidoille kylmänä päivänä; kun aurinko on noussut, ne pakenevat, eikä kukaan tiedä paikkaa, missä ne ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Sinun paimenesi, Assurin kuningas, ovat nukkuneet, sinun ylhäisesi jääneet liikkumattomiksi. Sinun väkesi on hajaantunut vuorille, eikä ole kokoajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Auttamaton on sinun perikatosi, parantumaton sinun haavasi. Kaikki, jotka kuulevat sanoman sinusta, paukuttavat sinulle käsiänsä. Sillä ketä ei olisi yhäti kohdannut sinun pahuutesi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Ennustus, jonka profeetta Habakuk näki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Kuinka kauan, Herra, minun täytyy apua huutaa, ja sinä et kuule, parkua sinulle: \"Väkivaltaa!\" ja sinä et auta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Minkätähden sinä annat minun nähdä vääryyttä ja itse katselet turmiota? Minun edessäni on hävitys ja väkivalta; on syntynyt riita, ja on noussut tora.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Sentähden on laki heikko, ja oikeus ei tule milloinkaan voimaan. Sillä jumalaton saartaa vanhurskaan; sentähden oikeus vääristetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Katsokaa kansojen joukkoon, katselkaa ja kauhistukaa, sillä minä teen teidän päivinänne teon, jota ette uskoisi, jos siitä kerrottaisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Sillä katso, minä nostan kaldealaiset, tuiman ja rajun kansan, joka kulkee maata lavealti ja ottaa omaksensa asuinsijat, jotka eivät ole sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Se on hirmuinen ja peljättävä, siitä itsestään tulee sen oikeus ja sen korkeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Sen hevoset ovat nopeammat kuin pantterit, ne juoksevat kiivaammin kuin sudet illoin. Sen ratsumiehet kiidättävät-kaukaa tulevat sen ratsumiehet, ne lentävät, niinkuin kotka syöksyy syönnökselleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Se tulee kaikkinensa väkivallan tekoon, heidän kasvojensa suunta on suoraan eteenpäin; se kokoaa vankeja kuin hietaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Pilkkanaan pitää se kuninkaat ja naurunansa ruhtinaat. Se nauraa kaikille varustuksille, kasaa kokoon hiekkaa ja valloittaa ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Sitten se tuulena kiitää ja hyökkää, mutta joutuu syynalaiseksi, tuo, jolla oma voimansa on jumalana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Etkö sinä ole ikiajoista asti Herra, minun pyhä Jumalani? Me emme kuole! Sinä, Herra, olet pannut sen tuomioksi; sinä, kallio, olet asettanut sen kuritukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Sinun silmäsi ovat puhtaat, niin ettet voi katsoa pahaa etkä saata katsella turmiota. Minkätähden sinä katselet uskottomia, olet vaiti, kun jumalaton nielee hurskaampansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'teet ihmiset samankaltaisiksi kuin meren kalat, kuin matelevaiset, joilla ei ole hallitsijaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Se nostaa heidät kaikki ylös koukulla, vetää heidät pyydyksessään ja kokoaa heidät verkkoonsa. Sentähden se iloitsee ja riemuitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Sentähden se uhraa pyydykselleen ja polttaa uhreja verkollensa, sillä niitten turvin sen osa on rasvainen, sen ruoka lihava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Saako se sentähden tyhjentää pyydyksensä, aina surmata kansoja säälimättä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Minä seison vartiopaikallani, asetun varustukseen ja tähystän, nähdäkseni, mitä hän minulle puhuu, mitä hän valitukseeni vastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Ja Herra vastasi minulle ja sanoi: \"Kirjoita näky ja piirrä selvästi tauluihin, niin että sen voi juostessa lukea\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Sillä näky odottaa vielä aikaansa, mutta se rientää määränsä päähän, eikä se petä. Jos se viipyy, odota sitä; sillä varmasti se toteutuu, eikä se myöhästy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Katso, sen kansan sielu on kopea eikä ole suora; mutta vanhurskas on elävä uskostansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Ja vielä: viini on petollista, urho on röyhkeä; mutta hän ei ole pysyväinen, hän, joka levittää kitansa kuin tuonela ja on täyttymätön kuin kuolema, kokoaa itselleen kaikki kansakunnat ja kerää itselleen kaikki kansat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Mutta ne kaikki virittävät hänestä pilkkalaulun, ivarunon, arvoituslaulun; he sanovat: \"Voi sitä, joka hankkii paljon omaisuutta, mikä ei ole hänen-ja kuinkahan pitkäksi aikaa? -ja kasaa päällensä pantteja!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Eivätkö nouse äkisti sinun vaivaajasi, eivätkö heräjä sinun ravistajasi? Ja sinä joudut niiden ryöstettäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Sillä niinkuin sinä olet riistänyt monia kansakuntia, niin riistävät sinua kaikki jäljellejääneet kansat ihmisveren tähden ja väkivallan tähden, joka on tehty maalle, kaupungille ja kaikille sen asukkaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Voi sitä, joka kiskoo väärää voittoa huoneensa hyväksi laittaakseen pesänsä korkealle, pelastuakseen kovan onnen kourista!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Sinä olet neuvoillasi tuottanut häpeätä huoneellesi, tuhoamalla paljon kansoja, ja olet oman henkesi rikkonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Sillä kivi seinästä on huutava ja orsi katosta on vastaava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Voi sitä, joka rakentaa kaupungin verivelkojen varaan ja perustaa linnan vääryyden varaan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Katso, eikö tule se Herralta Sebaotilta, että kansat näkevät vaivaa tulen hyväksi ja kansakunnat väsyttävät itseänsä tyhjän hyväksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Sillä maa on oleva täynnä Herran kunnian tuntemusta, niinkuin vedet peittävät meren.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Voi sitä, joka juottaa lähimmäistänsä, joka sekoittaa juoman sinun vihallasi ja juovuttaa hänet nähdäkseen hänen alastomuutensa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Sinä ravitset itsesi häpeällä, et kunnialla: niinpä juo sinäkin ja paljasta ympärileikkaamattomuutesi. Sinun kohdallesi on kiertyvä Herran oikean käden malja ja häväistys kunnian sijaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Sillä sinut on peittävä Libanonille tekemäsi väkivalta ja eläimiä kohdannut hävitys, joka on ne säikyttänyt, ihmisveren tähden ja väkivallan tähden, joka on tehty maalle, kaupungille ja kaikille sen asukkaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Mitä hyötyä on veistetystä kuvasta, että sen valmistaja veistää sen, ja valetusta kuvasta ja valheen opettajasta, että sen valmistaja siihen luottaa ja tekee mykkiä epäjumalia?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Voi sitä, joka sanoo puulle: \'Heräjä!\' ja mykälle kivelle: \'Nouse!\' Sekö voisi opettaa? Katso, se on silattu kullalla ja hopealla, ja henkeä siinä ei ole, ei ensinkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Mutta Herra on pyhässä temppelissänsä, hänen edessään vaietkoon kaikki maa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Profeetta Habakukin rukous; virren tapaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Herra, minä olen kuullut sinulta sanoman, ja olen peljästynyt. Herra, herätä eloon tekosi jo kesken vuotten, tee se jo kesken vuotten tiettäväksi. Muista vihassasi laupeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Jumala tulee Teemanista, Pyhä Paaranin vuorelta. Sela. Hänen valtasuuruutensa peittää taivaat, hänen ylistystänsä on maa täynnä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Hänen hohteensa on kuin aurinko, hänestä käyvät säteet joka taholle; se on hänen voimansa verho.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Hänen edellänsä käy rutto ja polttotauti tulee hänen jäljessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Hän seisahtuu ja mittaa maan, hän katsahtaa ja saa kansat vapisemaan. Ikivuoret särkyvät, ikuiset kukkulat vaipuvat, hänen polkunsa ovat iankaikkiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Vaivan alaisina minä näen Kuusanin majat, Midianin maan telttavaatteet vapisevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Virtoihinko Herra on vihastunut? Kohtaako sinun vihasi virtoja, merta sinun kiivastuksesi, koska ajat hevosillasi, pelastuksesi vaunuilla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Paljas, paljastettu on sinun jousesi: valat, vitsat, sana. Sela. Virroilla sinä halkaiset maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Vuoret näkevät sinut ja järkkyvät, rankkasade purkaa vettä, syvyys antaa äänensä, kohottaa kätensä korkealle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Aurinko ja kuu astuvat majaansa sinun kiitävien nuoltesi valossa, sinun keihääsi salaman hohteessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Kiivastuksessa sinä astut maata, puit kansoja vihassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Sinä olet lähtenyt auttamaan kansaasi, auttamaan voideltuasi. Sinä murskaat pään jumalattoman huoneesta, paljastat perustukset kaulan tasalle. Sela.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Sinä lävistät heidän omilla keihäillään pään heidän johtajiltansa, jotka hyökkäävät hajottamaan minua-se on heidän ilonsa-aivan kuin pääsisivät syömään kurjaa salassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Sinä ajat hevosillasi merta, paljojen vetten kuohua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Minä kuulin tämän, ja minun ruumiini vapisee, minun huuleni värisevät huudosta, mätä menee minun luihini, minä seison paikallani ja tutisen, kun minun täytyy hiljaa odottaa ahdistuksen päivää, jolloin kansan kimppuun käy hyökkääjä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Sillä ei viikunapuu kukoista, eikä viiniköynnöksissä ole rypäleitä; öljypuun sato pettää, eivätkä pellot tuota syötävää. Lampaat ovat kadonneet tarhasta, eikä ole karjaa vajoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Mutta minä riemuitsen Herrassa, iloitsen autuuteni Jumalassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Herra, Herra on minun voimani. Hän tekee minun jalkani nopsiksi niinkuin peurat ja antaa minun käydä kukkuloillani. Veisuunjohtajalle; minun kielisoittimillani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Herran sana, joka tuli Sefanjalle, Kuusin pojalle, joka oli Gedaljan poika, joka Amarjan poika, joka Hiskian poika, Juudan kuninkaan Joosian, Aamonin pojan, päivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Totisesti minä otan kaiken pois maan pinnalta, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Minä otan pois ihmiset ja eläimet, otan pois taivaan linnut ja meren kalat, viettelykset ja jumalattomat. Minä hävitän ihmiset maan pinnalta, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Minä ojennan käteni Juudaa vastaan ja kaikkia Jerusalemin asukkaita vastaan, ja minä hävitän tästä paikasta Baalin jätteet, epäjumalain pappien nimet ynnä myös Herran papit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'ne, jotka katoilla kumartaen rukoilevat taivaan joukkoa, sekä ne, jotka kumartaen rukoilevat Herraa ja vannovat hänen kauttansa, mutta myös vannovat Melekinsä kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'ynnä ne, jotka ovat luopuneet seuraamasta Herraa, eivät etsi Herraa eivätkä häntä kysy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Vaiti Herran, Herran edessä! Sillä Herran päivä on lähellä; sillä Herra on laittanut teurasuhrin, on vihkinyt kutsuttunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Ja Herran teurasuhrin päivänä minä rankaisen päämiehiä ja kuninkaan poikia ja kaikkia muukalaispukuun puettuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Ja minä rankaisen sinä päivänä kaikkia kynnyksen yli hyppääjiä, jotka täyttävät herransa huoneen väkivallalla ja petoksella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'Sinä päivänä, sanoo Herra, kuuluu huuto Kalaportilta ja valitus toisesta kaupunginosasta ja suuri hävitys kukkuloilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Valittakaa, te Huhmaren asukkaat, sillä tuhottu on kaikki kauppaakäypä väki, hävitetty kaikki hopean punnitsijat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Siihen aikaan minä tutkin lampuilla Jerusalemin ja rankaisen ne miehet, jotka rauhassa makaavat pohjasakkansa päällä ja sanovat sydämessään: \"Ei Herra tee hyvää eikä pahaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Heidän rikkautensa joutuu ryöstettäväksi, ja heidän talonsa jäävät autioiksi. He ovat rakentaneet taloja, mutta eivät saa niissä asua; ovat istuttaneet viinitarhoja, mutta eivät saa niistä viiniä juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Lähellä on Herran suuri päivä, se on lähellä ja tulee sangen kiiruusti. Kuule, Herran päivä! Silloin sankarit haikeasti huutavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Vihan päivä on se päivä, tuskan ja ahdistuksen päivä, häviön ja hävityksen päivä, pimeyden ja synkeyden päivä, pilven ja sankan sumun päivä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'pasunan ja sotahuudon päivä varustettuja kaupunkeja ja korkeita muurinkulmia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Minä saatan ihmiset ahdistukseen, niin että he kulkevat kuin sokeat, sillä he ovat tehneet syntiä Herraa vastaan. Ja heidän verensä vuodatetaan niinkuin tomu, ja heidän elinnesteensä niinkuin saasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Eivätkä voi pelastaa heitä heidän hopeansa ja kultansa Herran vihan päivänä: hänen kiivautensa tulessa kuluu koko maa. Sillä lopun, äkkilopun, hän tekee kaikista maan asukkaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Menkää itseenne, kootkaa ajatuksenne, te häpeämätön kansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'ennenkuin neuvopäätös on synnyttänyt-päivä kiitää pois kuin akanat-ennenkuin teidän päällenne tulee Herran vihan hehku, ennenkuin teidän päällenne tulee Herran vihan päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Etsikää Herraa, kaikki maan nöyrät, te, jotka pidätte hänen oikeutensa. Etsikää vanhurskautta, etsikää nöyryyttä; ehkä te saatte suojan Herran vihan päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Sillä Gassa on oleva hyljätty ja Askelon autio, Asdod ajetaan pois keskipäivällä, ja Ekron hävitetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Voi meren rannikon asukkaita, kreettien kansaa! Herran sana on teitä vastaan, Kanaan, filistealaisten maa; ja minä hävitän sinut asujattomaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Ja meren rannikko on oleva laitumina, joilla on paimenten vesikuoppia ja lammastarhoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Ja rannikko joutuu Juudan heimon jäännökselle. Siellä he laiduntavat; Askelonin huoneisiin he asettuvat makaamaan illoin. Sillä Herra, heidän Jumalansa, on pitävä heistä huolen ja kääntävä heidän kohtalonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Minä olen kuullut Mooabin häväistykset ja ammonilaisten pilkat, joilla he ovat häväisseet minun kansaani ja ylvästelleet sen aluetta vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Sentähden, niin totta kuin minä elän, sanoo Herra Sebaot, Israelin Jumala, on Mooab tuleva Sodoman kaltaiseksi ja ammonilaiset Gomorran kaltaisiksi, nokkospehkojen maaksi, suolakuopaksi, autioksi iankaikkisesti. Jääneet minun kansastani ryöstävät heitä, ja minun kansakuntani jäännökset ottavat heidät perintöosaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Tämä tulee heille heidän ylpeydestään, siitä, että ovat herjanneet, ovat ylvästelleet Herran Sebaotin kansaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Peljättävä on Herra heille oleva, sillä hän tekee voimattomiksi kaikki maan jumalat; ja kaikki pakanain saaret, kukin paikastansa, tulevat häntä kumartaen rukoilemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Myöskin teidät, etiopialaiset, on minun miekkani kaatava-heidätkin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Ja hän on ojentava kätensä pohjoista kohden ja on hukuttava Assurin, tekevä Niiniven autioksi, kuivaksi kuin erämaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Sen keskellä makaa laumoja, kaikkia villieläimiä joukoittain. Pelikaani ja tuonenkurki yöpyvät sen patsaanpäissä. Kuule, kuinka ne laulavat akkuna-aukossa! Kynnyksellä on tyhjyys. Setrilaudoituksen hän on paljastanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Tämä oli se riemuisa kaupunki, joka asui turvallisena, joka sanoi sydämessään: \"Minä, eikä ketään muuta!\" Kuinka autioksi se on tullut, villieläinten makuusijaksi! Jokainen, joka käy siitä ohitse, viheltää ja huiskuttaa kättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Voi uppiniskaista ja saastutettua, voi väkivaltaista kaupunkia!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Se ei ole totellut ääntä, ei huolinut kurituksesta, ei luottanut Herraan, ei lähestynyt Jumalaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Sen päämiehet sen keskellä ovat ärjyviä leijonia. Sen tuomarit ovat kuin sudet illalla, jotka eivät säästä mitään aamuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Sen profeetat ovat huikentelijoita, uskottomia miehiä. Sen papit saastuttavat pyhän ja tekevät väkivaltaa laille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Herra on vanhurskas sen keskellä, hän ei tee väärin. Joka aamu hän tuo valoon oikeutensa, ei se tulematta jää. Mutta väärintekijä ei tunne häpeätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Minä olen hävittänyt pakanakansat, niiden muurinkulmat ovat autioina. Minä olen tehnyt niiden kadut raunioiksi, kulkijattomiksi; niiden kaupungit ovat hävitetyt ihmisettömiksi, asujattomiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Minä olen sanonut: Ainoastaan pelkää minua ja ota varteen kuritus, niin ei hävitetä tytär Siionin asumusta, ei mitään siitä, mitä minä olen hänelle säätänyt. Kuitenkin he varhaisesta alkaen ovat aina pahemmin tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Sentähden odottakaa minua, sanoo Herra, odottakaa sitä päivää, jona minä nousen saaliille. Sillä minun tuomioni on, että minä kokoan pakanakansat, saatan kokoon valtakunnat vuodattaakseni heidän päällensä tuimuuteni, vihani kaiken hehkun; sillä minun kiivauteni tuli kuluttaa koko maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Silloin minä muutan puhtaiksi kansain huulet, niin että ne kaikki rukoilevat Herran nimeä, palvelevat häntä yksimielisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Tuolta puolen Etiopian virtain tuovat minun rukoilijani-tytär, minun hajoitettu joukkoni-minulle ruokauhreja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Sinä päivänä ei sinun tarvitse hävetä yhtäkään niistä teoistasi, joilla olet rikkonut minua vastaan, sillä silloin minä poistan sinun keskuudestasi sinun ylvääsi, riemuitsevaisesi, etkä sinä sitten enää ylpeile minun pyhällä vuorellani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Mutta minä jätän jäljelle sinun keskuuteesi kurjan ja vaivaisen kansan, ja he luottavat Herran nimeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Israelin jäännökset eivät tee väärin, eivät puhu valhetta, eikä heidän suussaan tavata vilpillistä kieltä. Sillä he kaitsevat kaittaviansa ja makaavat kenenkään peloittelematta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Iloitse, tytär Siion, puhkea huutoon, Israel; ihastu ja ratkea riemuun kaikesta sydämestäsi, tytär Jerusalem.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Herra on poistanut sinun tuomiosi, kääntänyt pois sinun vihollisesi. Israelin kuningas, Herra, on sinun keskelläsi. Ei tarvitse sinun enää onnettomuutta nähdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'Sinä päivänä sanotaan Jerusalemille: \"Älä pelkää, Siion, älkööt kätesi hervotko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Herra, sinun Jumalasi, on sinun keskelläsi, sankari, joka auttaa. Hän ilolla iloitsee sinusta, hän on ääneti, sillä hän rakastaa sinua, hän sinusta riemulla riemuitsee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Jotka murehtivat, kaukana juhlakokouksista, ne minä kokoan: nehän ovat sinusta, niitä häväistys kuormana painaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Katso, siihen aikaan minä teen tekoni kaikille sinun nöyryyttäjillesi. Minä pelastan ontuvat ja kokoan karkoitetut ja teen heidät ylistetyiksi ja mainehikkaiksi jokaisessa maassa, jossa he olivat häpeänalaisina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Siihen aikaan minä tuon teidät takaisin-siihen aikaan, jona minä teidät kokoan. Sillä minä teen teidät mainehikkaiksi ja ylistetyiksi kaikissa maan kansoissa, kun minä käännän teidän kohtalonne teidän silmäinne nähden; sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Kuningas Daarejaveksen toisena vuotena, kuudennessa kuussa, kuukauden ensimmäisenä päivänä, tuli tämä Herran sana profeetta Haggain kautta Juudan käskynhaltijalle Serubbaabelille, Sealtielin pojalle, ja ylimmäiselle papille Joosualle, Joosadakin pojalle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, '\"Näin sanoo Herra Sebaot: Tämä kansa sanoo: Aika ei ole tullut rakentaa Herran huonetta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Mutta profeetta Haggain kautta tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, '\"Onko sitten aika teidän asua panelilla kaunistetuissa huoneissanne, kun tämä huone on rauniona?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Ja nyt sanoo Herra Sebaot näin: Ottakaa vaari teistänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Te kylvätte paljon, mutta saatte vähän. Te syötte, mutta ette tule ravituiksi. Te juotte, mutta jano ei sammu. Te vaatetatte itsenne, mutta ei tule lämmin. Ja palkkatyöläinen panee työpalkan reikäiseen kukkaroon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Näin sanoo Herra Sebaot: Ottakaa vaari teistänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Nouskaa vuorille, tuokaa puita ja rakentakaa temppeli, niin minä siihen mielistyn ja näytän kunniani, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Te odotatte paljoa, mutta se menee vähiin. Te tuotte kotiin, mutta minä puhallan sen pois. Minkätähden? sanoo Herra Sebaot. Minun huoneeni tähden, kun se on rauniona ja te juoksette kukin oman huoneenne hyväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Sentähden teiltä taivas pidättää kasteen ja maa pidättää satonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Ja minä olen kutsunut kuivuuden maahan ja vuorille, viljalle, viinille ja öljylle, ja mitä vain maa tuottaa, ja ihmisille ja eläimille ja kaikelle kätten vaivannäölle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Niin Serubbaabel, Sealtielin poika, ja ylimmäinen pappi Joosua, Joosadakin poika, ja kansan koko jäännös kuuli Herran, Jumalansa ääntä ja profeetta Haggain sanoja, jota varten Herra, heidän Jumalansa, oli hänet lähettänytkin, ja kansa pelkäsi Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Haggai, Herran sanansaattaja, sanoi, saattaen Herran sanan, kansalle näin: \"Minä olen teidän kanssanne, sanoo Herra\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Ja Herra herätti Juudan käskynhaltijan Serubbaabelin, Sealtielin pojan, hengen ja ylimmäisen papin Joosuan, Joosadakin pojan, hengen ja kansan koko jäännöksen hengen, ja he tulivat ja ryhtyivät rakentamaan Herran Sebaotin, heidän Jumalansa, temppeliä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'kahdentenakymmenentenä neljäntenä päivänä kuudennessa kuussa, kuningas Daarejaveksen toisena vuotena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Seitsemännessä kuussa, kuukauden kahdentenakymmenentenä ensimmäisenä päivänä tuli profeetta Haggain kautta tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, '\"Sano Juudan käskynhaltijalle Serubbaabelille, Sealtielin pojalle, ja ylimmäiselle papille Joosualle, Joosadakin pojalle, ja kansan jäännökselle näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Kuka teidän joukossanne on jäljelle jäänyt, joka on nähnyt tämän temppelin sen entisessä kunniassa? Ja miltä näyttää se teistä nyt? Eikö se ole tyhjän veroinen teidän silmissänne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Mutta nyt ole luja, Serubbaabel, sanoo Herra, ja ole luja, Joosua, Joosadakin poika, ylimmäinen pappi, ja ole luja, maan koko kansa, sanoo Herra, ja tehkää työtä; sillä minä olen teidän kanssanne, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Sen liiton sana, jonka minä tein teidän kanssanne, kun te läksitte Egyptistä, ja minun Henkeni pysyy teidän keskellänne. Älkää peljätkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Sillä näin sanoo Herra Sebaot: Vielä vähän aikaa, ja minä liikutan taivaat ja maan, meren ja kuivan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Ja minä liikutan kaikki pakanakansat, ja kaikkien pakanakansojen kalleudet tulevat, ja minä täytän tämän temppelin kunnialla, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Minun on hopea, ja minun on kulta, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Tämän temppelin myöhempi kunnia on oleva suurempi kuin aikaisempi, sanoo Herra Sebaot. Ja tässä paikassa minä annan vallita rauhan, sanoo Herra Sebaot.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Yhdeksännen kuun kahdentenakymmenentenä neljäntenä päivänä, Daarejaveksen toisena vuotena, tuli profeetta Haggain kautta tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, '\"Näin sanoo Herra Sebaot: Pyydä papeilta opetusta ja sano:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Katso, mies kantaa pyhää lihaa vaatteensa liepeessä ja koskettaa liepeellänsä leipää tai keittoa, viiniä, öljyä tai muuta ruokaa, mitä hyvänsä; tuleeko se siitä pyhäksi?\" Niin papit vastasivat ja sanoivat: \"Ei\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Ja Haggai sanoi: \"Jos joku, joka on kuolleesta saastunut, koskettaa jotakin näistä, tuleeko se saastaiseksi?\" Niin papit vastasivat: \"Tulee saastaiseksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Silloin Haggai lausui ja sanoi: \"Sellaista on tämä väki, sellaista tämä kansa minun edessäni, sanoo Herra. Sellaiset ovat kaikki heidän kättensä työt ja se, mitä he siellä uhriksi tuovat: se on saastaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Ja nyt ottakaa vaari, kuinka käy tästä päivästä lähtien eteenpäin. Kun ei vielä oltu pantu kiveä kiven päälle Herran temppelissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'sitä ennen, mentiin kahdenkymmenen mitan viljakasalle, mutta oli vain kymmenen; mentiin viinikuurnalle ammentamaan viisikymmentä mittaa, mutta oli kaksikymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Minä löin teitä, kaikkia teidän kättenne töitä, nokitähkällä ja viljanruosteella ja rakeilla, mutta ei kenkään teistä kääntynyt minun puoleeni, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Ottakaa vaari, kuinka käy tästä päivästä lähtien eteenpäin, yhdeksännen kuun kahdennestakymmenennestä neljännestä päivästä, Herran temppelin perustamispäivästä, lähtien. Ottakaa vaari!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Onko aitassa enää siementä? Ja viiniköynnös, viikunapuu, granaattiomenapuu ja öljypuu, nekään eivät ole kantaneet hedelmää. Tästä päivästä lähtien minä annan siunauksen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Ja Herran sana tuli toistamiseen Haggaille kuukauden kahdentenakymmenentenä neljäntenä päivänä; se kuului:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, '\"Sano Juudan käskynhaltijalle Serubbaabelille: Minä liikutan taivaat ja maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Ja minä kukistan kuningaskuntien valtaistuimet, hävitän pakanain kuningaskuntien väkevyyden ja kukistan vaunut ajajineen; ja hevoset ja niiden ratsastajat kaatuvat, mies toisensa miekkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'Sinä päivänä, sanoo Herra Sebaot, minä otan sinut, palvelijani Serubbaabel, Sealtielin poika, sanoo Herra, ja panen sinut ikäänkuin sinettisormukseksi. Sillä sinut minä olen valinnut, sanoo Herra Sebaot.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Kahdeksannessa kuussa Daarejaveksen toisena vuotena tuli profeetta Sakarjalle, Berekjan pojalle, joka oli Iddon poika, tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, '\"Herra on tuimasti vihastunut teidän isiinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Sano heille: Näin sanoo Herra Sebaot: Kääntykää minun tyköni, sanoo Herra Sebaot, niin minä käännyn teidän tykönne, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Älkää olko isienne kaltaiset, joille entiset profeetat ovat saarnanneet sanoen: Näin sanoo Herra Sebaot: Kääntykää pois pahoilta teiltänne ja pahoista teoistanne; mutta he eivät kuulleet, eivät kuunnelleet minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Teidän isänne-missä he ovat? Ja profeetat-ovatko he eläneet iäti?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Mutta minun sanani ja käskyni, jotka minä olen säätänyt palvelijoilleni profeetoille-eivätkö ne ole kohdanneet teidän isiänne: ja niin he kääntyivät ja sanoivat: \'Niinkuin Herra Sebaot aikoi meille tehdä, meidän vaelluksemme ja tekojemme mukaan, niin hän on meille tehnyt\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Kahdentenakymmenentenä neljäntenä päivänä yhdennessätoista kuussa, joka on sebat-kuu, Daarejaveksen toisena vuotena, tuli profeetta Sakarjalle, Berekjan pojalle, joka oli Iddon poika, tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Minä näin yöllä, katso, mies ratsasti punaisenruskealla hevosella, ja hän seisahtui myrttien keskelle laaksoon, ja hänen jäljessänsä oli punaisenruskeita ja punaisia ja valkeita hevosia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Niin minä kysyin: \"Mitä nämä ovat, Herra?\" Enkeli, joka puhutteli minua, vastasi minulle: \"Minä näytän sinulle, mitä ne ovat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Ja mies, joka seisoi myrttien keskellä, lausui ja sanoi: \"Nämä ovat ne, jotka Herra on lähettänyt maata kuljeksimaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Niin ne vastasivat Herran enkelille, joka seisoi myrttien keskellä, ja sanoivat: \"Me olemme kuljeksineet maata, ja katso, koko maa on alallansa ja rauhassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Ja Herran enkeli lausui ja sanoi: \"Herra Sebaot, kuinka kauan sinä viivyt etkä armahda Jerusalemia ja Juudan kaupunkeja, joille olet ollut vihainen nämä seitsemänkymmentä vuotta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Niin Herra vastasi enkelille, joka puhutteli minua, ja lausui hyviä, lohdullisia sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Ja enkeli, joka puhutteli minua, sanoi minulle: \"Saarnaa ja sano: Näin sanoo Herra Sebaot: Minä kiivailen Jerusalemin ja Siionin puolesta suurella kiivaudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Suurella vihalla minä olen vihastunut suruttomiin pakanoihin, jotka, kun minä vähän vihastuin, auttoivat onnettomuutta tapahtumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Sentähden sanoo Herra näin: Minä käännyn Jerusalemin puoleen armahtavaisuudessa. Minun temppelini siellä rakennetaan, sanoo Herra Sebaot, ja mittanuora jännitetään Jerusalemin ylitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Saarnaa vielä ja sano: Näin sanoo Herra Sebaot: Vielä minun kaupunkini ovat hyvyydestä ylitsevuotavaiset, ja vielä Herra lohduttaa Siionin ja valitsee vielä Jerusalemin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Ja minä nostin silmäni ja katsoin. Ja katso: neljä sarvea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'Ja minä sanoin enkelille, joka puhutteli minua: \"Mitä nämä ovat?\" Niin hän sanoi minulle: \"Nämä ovat ne sarvet, jotka ovat hajottaneet Juudan ja Israelin ja Jerusalemin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Sitten Herra näytti minulle neljä seppää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'Minä sanoin: \"Mitä nämä ovat tulleet tekemään?\" Ja hän vastasi näin: \"Nuo sarvet ovat ne, jotka ovat hajottaneet Juudan, niin ettei yksikään mies voi päätänsä nostaa; ja nämä ovat tulleet saattamaan ne pelkoon ja heittämään maahan niiden pakanakansain sarvet, jotka ovat nostaneet sarven Juudan maata vastaan hajottaaksensa sen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Ja minä nostin silmäni ja katsoin. Ja katso, oli mies ja hänen kädessänsä mittanuora.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Minä sanoin hänelle: \"Mihin sinä olet menossa?\" Ja hän vastasi minulle: \"Mittaamaan Jerusalemia, nähdäkseni, kuinka leveä ja kuinka pitkä se on oleva\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Ja katso, enkeli, joka puhutteli minua, lähti liikkeelle, ja toinen enkeli lähti häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Ja hän sanoi tälle: \"Juokse, puhu tälle nuorukaiselle ja sano: Jerusalem on oleva muuriton paikkakunta, sillä niin paljon siinä on ihmisiä ja eläimiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Mutta minä olen oleva, sanoo Herra, tulimuuri sen ympärillä ja kunnia sen keskellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Voi, voi, paetkaa pohjoisesta maasta, sanoo Herra! Sillä minä olen hajottanut teidät neljään taivaan tuuleen, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Voi, Siion, pelastaudu, sinä, joka asut tytär Baabelin luona!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Sillä näin sanoo Herra Sebaot: Kunniaksensa hän on lähettänyt minut pakanakansojen luokse, jotka ovat teitä saalistaneet. Sillä joka teihin koskee, se koskee hänen silmäteräänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Sillä katso, minä heilutan kättäni heitä vastaan, ja he joutuvat orjiensa saaliiksi. Ja te tulette tietämään, että Herra Sebaot on lähettänyt minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Riemuitse ja iloitse, tytär Siion! Sillä minä tulen ja asun sinun keskelläsi, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Sinä päivänä liittyy paljon pakanakansoja Herraan, ja he tulevat hänen kansaksensa, ja minä asun sinun keskelläsi, ja sinä tulet tietämään, että Herra Sebaot on lähettänyt minut sinun tykösi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Ja Herra ottaa Juudan perintöosaksensa pyhässä maassa ja valitsee vielä Jerusalemin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Vaiti Herran edessä, kaikki liha! Sillä hän on noussut pyhästä asuinsijastansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Ja hän näytti minulle ylimmäisen papin Joosuan seisomassa Herran enkelin edessä ja saatanan seisomassa hänen oikealla puolellaan, häntä syyttämässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Ja Herra sanoi saatanalle: \"Herra nuhdelkoon sinua, saatana. Nuhdelkoon sinua Herra, joka on valinnut Jerusalemin. Eikö tämä ole kekäle, joka on tulesta temmattu?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Ja Joosua oli puettu saastaisiin vaatteisiin, ja hän seisoi enkelin edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Niin tämä lausui ja sanoi näin niille, jotka seisoivat hänen edessänsä: \"Riisukaa pois saastaiset vaatteet hänen yltänsä\". Ja hän sanoi hänelle: \"Katso, minä olen ottanut sinulta pois pahat tekosi, ja minä puetan sinut juhlavaatteisiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Minä sanoin: \"Pantakoon puhdas käärelakki hänen päähänsä\". Niin he panivat puhtaan käärelakin hänen päähänsä ja pukivat hänet vaatteisiin. Ja Herran enkeli seisoi siinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Ja Herran enkeli todisti Joosualle sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, '\"Näin sanoo Herra Sebaot: Jos sinä vaellat minun teilläni ja hoidat minun säätämäni tehtävät, saat sinä myös tuomita minun huonettani ja vartioida minun esikartanoitani, ja minä annan sinulle pääsyn näiden joukkoon, jotka tässä seisovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Kuule, Joosua, ylimmäinen pappi, sinä ja sinun ystäväsi, jotka edessäsi istuvat. Sillä ennusmerkin miehiä he ovat; sillä katso, minä annan tulla palvelijani, Vesan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Sillä katso: kivi, jonka minä olen asettanut Joosuan eteen-siihen yhteen kiveen päin on seitsemän silmää! Katso, minä kaiverran kaiverrukset siihen, sanoo Herra Sebaot, ja otan pois tämän maan pahat teot yhtenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'Sinä päivänä te kutsutte, kukin ystävänsä, viinipuun ja viikunapuun alle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Ja Herran enkeli, joka puhutteli minua, palasi ja herätti minut, niinkuin joku herätetään unestansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Ja hän sanoi minulle: \"Mitä sinä näet?\" Minä vastasin: \"Minä näen, katso: lampunjalka, kokonansa kultaa, ja sen yläpuolella sen öljyastia, ja lampunjalassa sen seitsemän lamppua, ja seitsemän öljyputkea lamppuihin, jotka ovat siinä ylimpänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Ja kaksi öljypuuta sen ääressä, toinen öljyastian oikealla, toinen vasemmalla puolella.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Minä lausuin ja sanoin näin enkelille, joka puhutteli minua: \"Mitä nämä ovat, Herra?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Niin enkeli, joka puhutteli minua, vastasi ja sanoi minulle: \"Etkö tiedä, mitä ne ovat?\" Minä sanoin: \"En, Herra\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Ja hän lausui ja sanoi minulle näin: \"Tämä on Herran sana Serubbaabelille, näin kuuluva: Ei sotaväellä eikä voimalla, vaan minun Hengelläni, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Mikä olet sinä, suuri vuori, Serubbaabelin edessä? Lakeudeksi sinä! Hän on paneva paikoillensa huippukiven huutojen kaikuessa: \"Suosio, suosio sille!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Ja minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, '\"Serubbaabelin kädet ovat tämän temppelin perustaneet, ja hänen kätensä sen valmiiksi saattavat. Ja sinä tulet tietämään, että Herra Sebaot on lähettänyt minut teidän luoksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Sillä kuka pitää halpana pienten alkujen päivän, kun nuo seitsemän Herran silmää, jotka tarkastavat koko maata, iloitsevat nähdessään luotilangan Serubbaabelin kädessä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Ja minä lausuin ja sanoin hänelle: \"Mitä ovat nämä kaksi öljypuuta lampunjalan oikealla ja vasemmalla puolella?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Sitten minä toistamiseen lausuin ja sanoin hänelle: \"Mitä ovat nuo kaksi öljypuun terttua kahden kultaisen putken kohdalla, jotka vuodattavat sisästänsä öljynkultaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Niin hän sanoi minulle näin: \"Etkö tiedä, mitä ne ovat?\" Minä vastasin: \"En, Herra\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Hän sanoi: \"Nämä ovat ne molemmat öljyllä voidellut, jotka seisovat kaiken maan Herran edessä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Minä nostin jälleen silmäni, ja katso: oli lentävä kirjakäärö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Ja hän sanoi minulle: \"Mitä sinä näet?\" Minä vastasin: \"Minä näen lentävän kirjakäärön, kahtakymmentä kyynärää pitkän ja kymmentä kyynärää leveän\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Hän sanoi minulle: \"Tämä on kirous, joka käy yli kaiken maan. Sillä tämän kirouksen mukaisesti siitä puhdistetaan pois jokainen varas, ja jokainen vannoskelija puhdistetaan siitä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Minä lasken sen irti, sanoo Herra Sebaot, ja se menee varkaan kotiin ja sen kotiin, joka vannoo väärin minun nimeeni. Se jää sisälle hänen kotiinsa ja kalvaa sen loppuun asti, sekä sen puut että sen kivet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Sitten enkeli, joka puhutteli minua, lähti liikkeelle ja sanoi minulle: \"Nosta silmäsi ja katso: mikä tuo on, joka lähtee liikkeelle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Minä sanoin: \"Mikä se sitten on?\" Ja hän vastasi: \"Tämä on eefa-mitta, joka lähtee liikkeelle\". Ja hän sanoi: \"Tämän näköisiä ne ovat koko maan päällä\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'ja katso, lyijykansi kohosi, ja siinä istui eräs nainen eefa-mitan sisällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Ja hän sanoi: \"Tämä on jumalattomuus\". Ja hän paiskasi hänet sisälle eefa-mittaan ja paiskasi lyijypainon sen suulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Ja kun minä nostin silmäni, näin minä, katso, kaksi naista lähtevän liikkeelle, ja niillä oli tuulta siivissään, ja niiden siivet olivat kuin haikaran siivet; ja ne kantoivat eefa-mittaa taivaan ja maan välitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Niin minä sanoin enkelille, joka puhutteli minua: \"Mihin ne kuljettavat eefa-mittaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Ja hän vastasi minulle: \"Ne menevät rakentamaan hänelle huonetta Sinearin maahan. Ja kun se on valmis, lasketaan hänet sinne paikoillensa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Minä nostin jälleen silmäni ja näin, katso, neljät vaunut, jotka lähtivät liikkeelle kahden vuoren välistä; ja ne vuoret olivat vaskivuoria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Ensimmäisten vaunujen edessä oli punaisenruskeat hevoset, toisten vaunujen edessä oli mustat hevoset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'kolmansien vaunujen edessä oli valkeat hevoset, ja neljänsien vaunujen edessä oli täplikkäät, väkevät hevoset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Minä lausuin ja sanoin enkelille, joka puhutteli minua: \"Mitä nämä ovat, Herra?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Enkeli vastasi ja sanoi minulle: \"Ne ovat neljä taivaan tuulta, jotka lähtevät liikkeelle seisottuansa kaiken maan Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Ne, joitten edessä on mustat hevoset, lähtevät pohjoiseen maahan, ja valkeat lähtevät niiden jäljessä. Täplikkäät lähtevät eteläiseen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Ne väkevät lähtevät, ja menevät halusta, kuljeksimaan maata.\" Ja hän sanoi: \"Menkää, kuljeksikaa maata\". Ja ne kuljeksivat maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Sitten hän huusi minut ja sanoi minulle näin: \"Katso, ne, jotka lähtivät pohjoiseen maahan, saattavat minun Henkeni lepäämään pohjoisessa maassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Minulle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, '\"Ota vastaan siirtolaisuudessa eläviltä Heldailta, Tobialta ja Jedajalta-mene tänä päivänä, mene Joosian, Sefanjan pojan, taloon, johon he ovat tulleet Baabelista, -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'ja ota vastaan hopea ja kulta, tee kruunu ja pane se ylimmäisen papin Joosuan, Joosadakin pojan, päähän');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'ja sano hänelle näin: \"Näin sanoo Herra Sebaot: Katso, mies nimeltä Vesa! Omalta pohjaltansa hän on kasvava, ja hän on rakentava Herran temppelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Herran temppelin hän on rakentava, ja valtasuuruutta hän on kantava, ja hän on istuva ja hallitseva valtaistuimellansa; hän on oleva pappi valtaistuimellansa, ja rauhan neuvo on vallitseva niitten molempien välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Ja kruunu on oleva muistona Herran temppelissä Helemistä ja Tobiasta ja Jedajasta ja Sefanjan pojan suosiollisuudesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Ja kaukana asuvaiset tulevat ja rakentavat Herran temppeliä. Ja te tulette tietämään, että Herra Sebaot on lähettänyt minut teidän tykönne. Näin on tapahtuva, jos te hartaasti kuulette Herran, teidän Jumalanne, ääntä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Kuningas Daarejaveksen neljäntenä vuotena tuli Herran sana Sakarjalle, neljäntenä päivänä yhdeksännessä kuussa, kislev-kuussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Beetel oli lähettänyt Sareserin ja Regem-Melekin miehinensä etsimään Herran mielisuosiota');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'ja kysymään Herran Sebaotin temppelin papeilta ynnä profeetoilta näin: \"Onko minun viidennessä kuussa itkettävä ja noudatettava pidättyväisyyttä, niin kuin minä olen tehnyt jo kuinka monina vuosina?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Niin minulle tuli tämä Herran Sebaotin sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, '\"Sano kaikelle maan kansalle ja papeille näin: Kun te olette paastonneet ja valittaneet viidennessä ja seitsemännessä kuussa, ja jo seitsemänäkymmenenä vuotena, niin minulleko te olette paastonne paastonneet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Ja kun olette syöneet ja juoneet, niin ettekö te ole itsellenne syöneet ja juoneet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Eikö niin: pitäkää ne sanat, jotka Herra on julistanut entisten profeettain kautta, kun Jerusalem vielä oli asuttuna ja levossa, ympärillään alaisensa kaupungit, ja Etelämaa ja Alankomaa olivat asutut?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Ja Sakarjalle tuli tämä Herran sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, '\"Näin sanoo Herra Sebaot: Tuomitkaa oikea tuomio, tehkää laupeus ja olkaa armahtavaiset kukin veljellenne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'leskeä, orpoa, muukalaista ja kurjaa älkää sortako, älkääkä miettikö mielessänne pahaa, kukin veljeänsä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Mutta he eivät tahtoneet ottaa vaaria, vaan käänsivät uppiniskaisina selkänsä ja kovettivat korvansa, etteivät kuulisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Ja he tekivät sydämensä kovaksi kuin timantti, etteivät kuulisi lakia eikä niitä sanoja, mitkä Herra Sebaot on lähettänyt Henkensä voimalla entisten profeettain kautta; ja niin on Herralta Sebaotilta tullut suuri vihastus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Samoin kuin hän huusi, mutta he eivät kuulleet, samoin he huutavat, mutta minä en kuule, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Ja minä myrskynä karkoitan heidät kaikkien pakanakansojen sekaan, joita he eivät tunne, ja maa jää heidän jälkeensä autioksi menijöistä ja tulijoista. Ihanan maan he tekevät autioksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Sitten tuli tämä Herran Sebaotin sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, '\"Näin sanoo Herra Sebaot: Minä kiivailen Siionin puolesta suurella kiivaudella, suurella vihalla minä sen puolesta kiivailen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Näin sanoo Herra: Minä käännyn jälleen Siionin puoleen ja tulen asumaan Jerusalemin keskelle, ja Jerusalemia kutsutaan Uskolliseksi Kaupungiksi ja Herran Sebaotin vuorta Pyhäksi Vuoreksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Näin sanoo Herra Sebaot: Vielä on Jerusalemin toreilla istuva vanhuksia ja vanhoja vaimoja, sauvansa kädessään kullakin päivien paljouden vuoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Ja kaupungin torit tulevat olemaan täynnä poikasia ja tyttösiä, jotka leikkivät sen toreilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Näin sanoo Herra Sebaot: Jos tämä onkin ihmeellistä tämän kansan jäännöksen silmissä niinä päivinä, pitäisikö sen olla ihmeellistä myös minun silmissäni, sanoo Herra Sebaot?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Näin sanoo Herra Sebaot: Katso, minä olen vapauttava kansani auringon nousun maasta ja laskun maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'Ja minä tuon heidät asumaan Jerusalemin keskelle. Ja he ovat minun kansani, ja minä olen heidän Jumalansa, uskollinen ja vanhurskas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Näin sanoo Herra Sebaot: Olkoot lujat teidän kätenne, teidän, jotka tähän aikaan olette kuulleet nämä sanat profeettain suusta, sinä päivänä, jona laskettiin Herran Sebaotin huoneen, rakennettavan temppelin, perustus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Sillä ennen sitä aikaa ei saatu palkkaa ihmisen työstä, ei palkkaa juhdan työstä, eikä ollut menijällä, ei tulijalla rauhaa ahdistajalta, ja minä laskin irti kaikki ihmiset, toisen toisensa kimppuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Mutta nyt minä en ole tämän kansan jäännökselle samanlainen, kuin olin entisinä päivinä, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Sillä rauhan kylvö kylvetään, viiniköynnös antaa hedelmänsä, maa antaa satonsa, taivas antaa kasteensa, ja tämän kansan jäännökselle minä annan perintöosaksi kaiken tämän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Ja niinkuin te olette olleet kirouksena pakanakansain seassa, te Juudan heimo ja Israelin heimo, niin te, kun minä teidät vapahdan, tulette olemaan siunauksena. Älkää peljätkö, olkoot teidän kätenne lujat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Sillä näin sanoo Herra Sebaot: Niinkuin minulla oli mielessä tehdä teille pahaa, kun teidän isänne vihoittivat minut, sanoo Herra Sebaot, enkä minä sitä katunut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'niin on taas tähän aikaan minulla mielessä tehdä hyvää Jerusalemille ja Juudan heimolle. Älkää peljätkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Näitä te tehkää: Puhukaa totta toinen toisellenne. Tuomitkaa porteissanne oikein, tuomitkaa rauhan tuomio.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Älkää hautoko mielessänne pahaa toinen toisellenne, älkääkä rakastako väärää valaa. Sillä kaikkia näitä minä vihaan, sanoo Herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Ja minulle tuli tämä Herran Sebaotin sana:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, '\"Näin sanoo Herra Sebaot: Neljännen kuun paasto ja viidennen paasto ja seitsemännen paasto ja kymmenennen paasto on oleva Juudan heimolle ilo ja riemu ja mieluinen juhla. Mutta rakastakaa totuutta ja rauhaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Näin sanoo Herra Sebaot: Vielä tulee kansoja, monien kaupunkien asukkaita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'ja toisen asukkaat menevät toiseen ja sanovat: \'Lähtekäämme, käykäämme etsimään Herran mielisuosiota, etsimään Herraa Sebaotia\'. -\'Minäkin lähden.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Ja monet kansat, väkevät pakanakansat, tulevat Jerusalemiin etsimään Herraa Sebaotia, etsimään Herran mielisuosiota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Näin sanoo Herra Sebaot: Niinä päivinä tarttuu kymmenen miestä kaikista pakanakansain kielistä, tarttuu Juudan miestä liepeeseen sanoen: \'Me tahdomme käydä teidän kanssanne, sillä me olemme kuulleet, että Jumala on teidän kanssanne\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Ennustus, Herran sana, Hadrakin maata vastaan, ja Damaskoon se laskeutuu. Sillä Herran silmä katsoo ihmisiä, kaikkia Israelin sukukuntia');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'ja myös Hamatia, joka on sen kanssa rajatusten, sekä Tyyroa ja Siidonia, sillä ne ovat sangen viisaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Tyyro on rakentanut itsellensä linnoituksia ja kasannut kokoon hopeata kuin tomua ja kultaa kuin katujen lokaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Katso, Herra köyhdyttää sen ja syöksee mereen sen voiman, ja se itse poltetaan tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Sen näkee Askelon ja peljästyy, ja Gassa, ja vapisee kovin, ja Ekron, sillä sen toivo joutuu häpeään. Ja Gassasta hukkuu kuningas, eikä Askelonissa enää asuta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Asdodissa asuu sekasikiöitä, ja minä hävitän filistealaisten ylpeyden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Mutta minä poistan veret hänen suustansa ja heidän iljetyksensä hänen hampaittensa välistä, ja hänestäkin jää jäännös meidän Jumalallemme; hän on oleva niinkuin sukuruhtinas Juudassa, ja Ekron on oleva niinkuin jebusilainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Minä teen leirini temppelini suojaksi sotajoukoilta, jotka tulevat ja menevät, eikä tule käskijä enää heidän kimppuunsa, sillä nyt olen minä sen omin silmin nähnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Iloitse suuresti, tytär Siion, riemuitse, tytär Jerusalem, sillä sinun kuninkaasi tulee sinulle! Vanhurskas ja auttaja hän on, on nöyrä ja ratsastaa aasilla, aasintamman varsalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Ja minä hävitän vaunut Efraimista ja hevoset Jerusalemista. Sodan jousi hävitetään, ja hän julistaa rauhan kansoille. Ja hänen hallituksensa ulottuu merestä mereen, Eufrat-virrasta hamaan maan ääriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Ja myös sinun vankisi minä sinun liittosi veren tähden päästän pois vedettömästä kuopasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Tulkaa takaisin varustukseen, te vangit, joilla on toivo; myös tänä päivänä minä julistan: kaksin verroin minä sinulle korvaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Sillä minä jännitän Juudan jousekseni, panen siihen nuoleksi Efraimin ja nostan sinun poikasi, Siion, sinun poikiasi vastaan, Jaavan, ja teen sinut sankarin miekan kaltaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Herra on näkyvä heidän yllänsä, ja hänen nuolensa lähtee kuin salama. Herra, Herra puhaltaa pasunaan ja kulkee etelän myrskytuulissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Herra Sebaot on suojaava heitä, ja he syövät, ja he tallaavat linkokiviä, he juovat ja pauhaavat niinkuin viinistä ja ovat täynnä, niinkuin uhrimaljat, niinkuin alttarin kulmat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Ja Herra, heidän Jumalansa, on sinä päivänä auttava heitä, kansaansa, joka on kuin hänen lammaslaumansa; sillä he ovat kruunuun kiinnitettyjä kiviä, jotka kohoavat yli hänen maansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Sillä kuinka suuri onkaan oleva heidän onnensa, heidän ihanuutensa: vilja saa kasvamaan nuorukaiset ja rypälemehu neitsyet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Rukoilkaa Herralta sadetta kevätsateen aikana: Herra tekee ukkospilvet ja antaa heille sadekuurot, antaa kasvit joka miehen pellolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Sillä kotijumalat puhuvat tyhjiä, ja tietäjät näkevät petosnäkyjä, puhuvat valheunia, lohduttelevat turhilla. Sentähden he saavat lähteä matkaan kuin lammaslauma ja kärsivät vaivaa, kun ei ole paimenta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Paimenia kohtaan syttyy minun vihani, ja johtomiehiä minä rankaisen; sillä Herra Sebaot pitää huolen laumastansa, Juudan heimosta, ja asettaa sen ikäänkuin kunniaratsuksensa sodassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Siitä on lähtevä kulmakivi, siitä kiinnityspaalu, siitä sotajousi, siitä lähtevät käskijät kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Ja he ovat niinkuin sankarit, jotka polkevat katujen lokaa sodassa. He sotivat, sillä Herra on heidän kanssansa; ja häpeään joutuvat hevosilla-ratsastajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Minä teen väkeväksi Juudan heimon ja autan Joosefin heimoa. Minä saatan heidät kotiin, sillä minä armahdan heitä, ja he tulevat olemaan, niinkuin en minä olisi heitä hyljännytkään. Sillä minä olen Herra, heidän Jumalansa, ja kuulen heidän rukouksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Efraim on oleva niinkuin sankari, ja heidän sydämensä on iloitseva niinkuin viinistä. Heidän lapsensa näkevät sen ja iloitsevat; heidän sydämensä riemuitsee Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Minä olen viheltävä heille ja kokoava heidät, sillä minä lunastan heidät, ja he lisääntyvät, niinkuin lisääntyivät ennen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Kun minä sirotan heidät kansojen sekaan, muistavat he minua kaukaisissa maissa; ja he lastensa kanssa saavat elää ja palata takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Minä tuon heidät takaisin Egyptin maasta ja kokoan heidät Assurista; minä vien heidät Gileadin maahan ja Libanonille, eikä heille ole riittävästi tilaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Hän käy ahdistuksen meren lävitse, hän lyö meren aaltoja, ja kaikki Niilivirran syvyydet kuivuvat, Assurin ylpeys painuu alas, ja Egyptin valtikka väistyy pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Mutta heidät minä teen väkeviksi Herrassa, ja hänen nimensä on heidän kerskauksensa, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Avaa ovesi, Libanon! Tuli on kuluttava sinun setrisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Valittakoon kypressi, sillä setri on kaatunut, hävitetyt ovat nuo mahtavat. Valittakaa, te Baasanin tammet, sillä sankka metsä on sortunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Kuule paimenten valitusta, kun on hävitetty nuo heidän mahtavansa. Kuule nuorten leijonain ärjyntää, kun on hävitetty Jordanin rantatiheikkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Näin sanoi Herra, minun Jumalani:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, '\"Kaitse teuraslampaita, joita niiden ostajat teurastavat tuntematta syynalaisuutta, ja joista niiden myyjät sanovat: \'Kiitetty olkoon Herra, minä olen rikastunut\', ja joita niiden paimenet eivät sääli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Sillä minä en enää sääli maan asukkaita, sanoo Herra. Katso, minä annan ihmisten joutua toistensa käsiin ja kuninkaansa käsiin, ja he hävittävät maan, enkä minä pelasta ketään heidän käsistänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Niin minä siis kaitsin teuraslampaita, lampaista kurjimpia. Ja minä otin itselleni kaksi sauvaa; minä nimitin toisen \"Suloudeksi\", toisen minä nimitin \"Yhteydeksi\", ja niin minä kaitsin lampaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Ja minä hävitin kolme paimenta yhtenä kuukautena, mutta minä kävin kärsimättömäksi lampaille, ja hekin kyllästyivät minuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Niin minä sanoin: \"Minä en tahdo enää teitä kaita. Kuolkoon, joka kuolee; hävitköön, joka häviää; ja jäljellejäävät syökööt kukin toisensa lihaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Ja minä otin sauvani Sulouden ja katkaisin sen purkaakseni liittoni, jonka olin tehnyt kaikkien kansojen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Ja sinä päivänä se purkautui, ja niin lampaista kurjimmat, jotka ottivat minusta vaarin, tulivat tietämään, että se oli Herran sana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Sitten minä sanoin heille: \"Jos teille hyväksi näkyy, niin antakaa minulle palkkani; jollei, niin olkaa antamatta\". Niin he punnitsivat minun palkakseni kolmekymmentä hopearahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Ja Herra sanoi minulle: \"Viskaa se savenvalajalle, tuo kallis hinta, jonka arvoiseksi he ovat minut arvioineet\". Niin minä otin ne kolmekymmentä hopearahaa ja viskasin ne Herran huoneeseen savenvalajalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Sitten minä katkaisin toisen sauvani, Yhteyden, purkaakseni veljeyden Juudan ja Israelin väliltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Sitten Herra sanoi minulle: \"Ota vielä itsellesi hullun paimenen kapineet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Sillä katso, minä olen herättävä maahan paimenen: hukkaantuneista hän ei pidä huolta, hajaantunutta hän ei etsi, ruhjoutunutta hän ei paranna, pystyssäpysyvää hän ei tue; mutta hän syö lihavien lihaa ja halkaisee niiden sorkat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Voi hullua paimenta, joka lampaat hylkää! Käyköön miekka hänen käsivarteensa ja oikeaan silmäänsä. Hänen käsivartensa kuivettukoon, ja hänen oikea silmänsä soetkoon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Ennustus, Herran sana Israelista. Näin sanoo Herra, joka on jännittänyt taivaan ja perustanut maan ja joka on luonut ihmisen hengen hänen sisimpäänsä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Katso, minä teen Jerusalemin juovuttavaksi maljaksi kaikille kansoille yltympäri, ja myös Juudan kohdalle se on tuleva Jerusalemia piiritettäessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Ja sinä päivänä minä teen Jerusalemin väkikiveksi kaikille kansoille: kaikki, jotka sitä nostavat, repivät pahoin itsensä; ja kaikki maan kansakunnat kokoontuvat sitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'Sinä päivänä, sanoo Herra, minä lyön kaikki hevoset vauhkoudella ja niiden ratsastajat hulluudella. Mutta Juudan heimoa kohti minä avaan silmäni, ja kaikki kansojen hevoset minä lyön sokeudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Silloin Juudan sukuruhtinaat sanovat sydämessään: \"Minun väkevyyteni ovat Jerusalemin asukkaat Herrassa Sebaotissa, heidän Jumalassansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'Sinä päivänä minä teen Juudan sukuruhtinaat ikäänkuin tulipannuksi puitten sekaan ja ikäänkuin tulisoihduksi lyhteitten sekaan, ja he kuluttavat oikealta ja vasemmalta, kuluttavat kaikki kansat yltympäri. Ja Jerusalem saa yhäti asua paikoillansa-Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Ja Herra on ensiksi vapauttava Juudan majat, ettei Daavidin suvun kunnia ja Jerusalemin asukasten kunnia ylvästelisi Juudaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'Sinä päivänä on Herra suojaava Jerusalemin asukkaita; ja kompastuvainen heidän seassansa on sinä päivänä oleva niinkuin Daavid, ja Daavidin suku on oleva niinkuin jumal\'olento, niinkuin Herran enkeli heidän edessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Mutta sinä päivänä minä tahdon hävittää kaikki pakanakansat, jotka hyökkäävät Jerusalemia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Ja minä vuodatan Daavidin suvun päälle ja Jerusalemin asukasten päälle armon ja rukouksen hengen. He katsovat minuun, jonka he ovat lävistäneet. Ja he valittavat häntä, niinkuin valitetaan ainokaista, murehtivat häntä katkerasti, niinkuin murehditaan katkerasti esikoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'Sinä päivänä pidetään Jerusalemissa suuret valittajaiset, niinkuin olivat Hadadrimmonin valittajaiset Megiddon laaksossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Ja maa pitää valittajaisia, kukin sukukunta erikseen: Daavidin huoneen sukukunta erikseen ja heidän naisensa erikseen, Naatanin huoneen sukukunta erikseen ja heidän naisensa erikseen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'Leevin huoneen sukukunta erikseen ja heidän naisensa erikseen, siimeiläisten sukukunta erikseen ja heidän naisensa erikseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, '{12:13} Kaikki muut sukukunnat, kukin sukukunta erikseen ja heidän naisensa erikseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'Sinä päivänä on Daavidin suvulla ja Jerusalemin asukkailla oleva avoin lähde syntiä ja saastaisuutta vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Ja sinä päivänä, sanoo Herra Sebaot, minä hävitän epäjumalain nimet maasta, eikä niitä enää muisteta. Myöskin profeetat ja saastaisuuden hengen minä ajan maasta pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Ja jos joku vielä ennustaa, sanovat hänen isänsä ja äitinsä, hänen vanhempansa, hänelle: \"Sinä et saa elää, koska olet puhunut valhetta Herran nimeen\". Ja hänen isänsä ja äitinsä, hänen vanhempansa, lävistävät hänet hänen ennustamisensa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Sinä päivänä häpeävät profeetat itsekukin näkyään, kun he ennustavat, eivätkä he valhetellakseen pue yllensä karvaista vaippaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Hän sanoo: \"En ole profeetta, vaan peltomies, sillä eräs mies on ostanut minut orjaksi jo nuoruudessani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Ja jos häneltä kysytään: \"Mitä ovat nuo haavat sinun rinnassasi?\" vastaa hän: \"Ne lyötiin minun ystäväini huoneessa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Heräjä, miekka, minun paimentani vastaan ja minun lähintä miestäni vastaan, sanoo Herra Sebaot. Lyö paimenta, ja joutukoot lampaat hajallensa; mutta minä käännän jälleen käteni pienimpiä kohden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Ja näin on käyvä koko maassa, sanoo Herra: kaksi osaa siitä hävitetään ja saa surmansa, mutta kolmas osa siitä jää jäljelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Ja sen kolmannen osan minä vien tuleen; minä sulatan heidät, niinkuin hopea sulatetaan, ja koettelen heitä, niinkuin kulta koetellaan. He huutavat avuksi minun nimeäni, ja minä vastaan heille. Minä sanon: \"Se on minun kansani\", ja se sanoo: \"Herra, minun Jumalani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Katso, Herran päivä on tuleva, ja sinun saaliisi jaetaan sinun keskelläsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Minä kokoan kaikki pakanat sotaan Jerusalemia vastaan. Kaupunki valloitetaan, talot ryöstetään, naiset raiskataan, ja puoli kaupunkia lähtee pakkosiirtolaisuuteen, mutta jäljelle jäävää kansaa ei hävitetä kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Ja Herra on lähtevä liikkeelle ja sotiva näitä pakanoita vastaan, niinkuin sotimispäivänänsä, taistelun päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Hänen jalkansa seisovat sinä päivänä Öljymäellä, joka on Jerusalemin edustalla itää kohti. Ja Öljymäki halkeaa kahtia idästä länteen hyvin suureksi laaksoksi: toinen puoli mäkeä siirtyy pohjoiseen ja toinen puoli etelään päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Ja te pakenette minun mäkieni väliseen laaksoon, sillä mäkien välinen laakso on ulottuva Asaliin asti. Te pakenette, niinkuin pakenitte maanjäristystä Ussian, Juudan kuninkaan, päivinä. Ja Herra, minun Jumalani, tulee; kaikki pyhät sinun kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'Sinä päivänä ei ole valoa: loistavat tähdet sammuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Se on oleva yhtämittaista päivää-Herralle on se tunnettu-ei vaihdu päivä ja yö; ja ehtoolla on oleva valoisata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Sinä päivänä elävät vedet virtaavat Jerusalemista: toiset puolet niistä Idänmerta kohti, toiset puolet Länsimerta kohti. Niin on tapahtuva kesät ja talvet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Herra on oleva koko maan kuningas. Sinä päivänä on Herra oleva yksi ja hänen nimensä yksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Koko maa muuttuu tasaiseksi kuin Aromaa Gebasta Rimmoniin asti, Jerusalemin eteläpuolelle. Ja tämä on oleva korkea ja oleva asuttu, paikallansa, Benjaminin portista entisen portin sijaan asti, Kulmaporttiin ja Hananelin-torniin asti, kuninkaan viinikuurniin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'He asuvat siellä, eikä vihitä sitä enää tuhon omaksi, ja Jerusalem on oleva asuttu, oleva turvassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Ja tämä on oleva vitsaus, jolla Herra rankaisee niitä kansoja, jotka sotivat Jerusalemia vastaan: hän mädättää siltä kansalta lihan, kun se vielä seisoo jaloillaan, sen silmät mätänevät kuopissansa, ja sen kieli mätänee sen suussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Sinä päivänä on tuleva Herralta suuri hämminki heidän sekaansa, niin että he käyvät kiinni toinen toisensa käteen ja toisen käsi kohoaa toisen kättä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Myös Juuda on sotiva Jerusalemissa, ja kaikkien pakanakansojen rikkaudet kootaan joka taholta: kullat ja hopeat ja ylen paljon vaatteita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Samoin on vitsaus kohtaava hevosia ja muuleja ja kameleja ja aaseja ja kaikkea karjaa, mitä niissä leireissä on-samankaltainen vitsaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Mutta kaikki niiden pakanakansain tähteet, jotka ovat hyökänneet Jerusalemia vastaan, käyvät vuosi vuodelta sinne ylös kumartaen rukoilemaan kuningasta, Herraa Sebaotia, ja viettämään lehtimajanjuhlaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Ja mitkä maan sukukunnista eivät käy ylös Jerusalemiin kumartaen rukoilemaan kuningasta, Herraa Sebaotia, niille ei tule sadetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Ja jos egyptiläisten sukukunta ei käy eikä tule sinne ylös, ei tule sitä heillekään; vaan heitä on kohtaava se vitsaus, millä Herra rankaisee niitä pakanakansoja, jotka eivät tule sinne ylös viettämään lehtimajanjuhlaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Tämä on oleva egyptiläisten synnin palkka ja kaikkien niiden pakanakansojen synnin palkka, jotka eivät käy sinne ylös viettämään lehtimajanjuhlaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'Sinä päivänä on oleva hevosten kulkusissa kirjoitus: \"Pyhitetty Herralle\". Ja padat Herran temppelissä ovat uhrimaljain vertaisia, jotka ovat alttarin edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Ja jokainen pata Jerusalemissa ja Juudassa on oleva pyhitetty Herralle Sebaotille, ja kaikki uhraajat tulevat ja ottavat niitä ja keittävät niissä. Eikä ole enää sinä päivänä yhtään kaupustelijaa Herran Sebaotin temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Ennustus, Herran sana Israelille, Malakian kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Minä olen teitä rakastanut, sanoo Herra. Mutta te sanotte: \"Missä sinä olet osoittanut rakkautesi meihin?\" Eikö Eesau ollut Jaakobin veli, sanoo Herra, ja Jaakobia minä rakastin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'mutta Eesauta minä vihasin; ja minä tein hänen vuorensa autioiksi ja annoin hänen perintöosansa erämaan aavikkosusille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Jos Edom sanoo: \"Me olemme ruhjotut, mutta me rakennamme rauniot jälleen\", niin Herra Sebaot sanoo näin: He rakentakoot, mutta minä revin maahan; ja heidän nimensä olkoon: \"jumalattomuuden maa\" ja \"kansa, johon Herra on vihastunut iankaikkisesti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Ja teidän silmänne saavat nähdä sen, ja te sanotte: \"Herra on suuri Israelin rajojen ulkopuolellakin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Poika kunnioittakoon isää ja palvelija herraansa. Mutta jos minä olen isä, missä on minun kunnioitukseni? Ja jos minä olen Herra, missä on minun pelkoni? sanoo Herra Sebaot teille, te papit, jotka pidätte halpana minun nimeni. Mutta te sanotte: \"Miten me olemme pitäneet halpana sinun nimesi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Siten, että tuotte minun alttarilleni saastutettua leipää. Mutta te sanotte: \"Miten me olemme sinut saastuttaneet?\" Siten, että sanotte: \"Herran pöytä on halpana pidettävä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Ja kun te tuotte uhriksi sokean eläimen, niin se muka ei ole paha! Ja kun tuotte ontuvan ja sairaan, niin se muka ei ole paha! Vie se maaherrallesi: mielistyykö hän sinuun, ja onko hän sinulle suosiollinen? sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Ja nyt: lepyttäkää Jumalaa, että hän meitä armahtaisi. Tällaista on teidän kädestänne tullut: olisiko hän teille suosiollinen? sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Jospa olisi teidän joukossanne joku, joka sulkisi ovet, ettette pitäisi tulta minun alttarillani turhaan! Ei ole minulla mielisuosiota teihin, sanoo Herra Sebaot, enkä minä mielisty ruokauhriin, joka tulee teidän kädestänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Sillä auringon noususta hamaan sen laskuun on minun nimeni oleva suuri pakanain seassa, ja joka paikassa uhrataan ja tuodaan minun nimeni kunniaksi puhdas ruokauhri. Sillä minun nimeni on oleva suuri pakanain seassa, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Mutta te häpäisette sen, kun sanotte: \"Herran pöytä on saastutettu, ja sen hedelmän syönti on halpana pidettävä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Ja te sanotte: \"Mikä vaiva!\" ja ylenkatsotte sen, sanoo Herra Sebaot, ja tuotte ryöstettyä, ontuvaa ja sairasta-tuotte uhrilahjaksi. -Minäkö mielistyisin ottamaan sen teidän kädestänne? sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Kirottu olkoon pettäjä, jolla on laumassaan koiraspuoli ja joka on luvannut sen, mutta uhraakin Herralle viallisen. Sillä suuri kuningas olen minä, sanoo Herra Sebaot, ja minun nimeni on peljättävä pakanain seassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Ja nyt teille tämä käsky, te papit!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Jos ette kuule ja paina sydämeenne, niin että annatte kunnian minun nimelleni, sanoo Herra Sebaot, lähetän minä teitä vastaan kirouksen ja kiroan teille suodut siunaukset. Minä olenkin ne jo kironnut, sillä te ette ole painaneet tätä sydämeenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Minä kiellän teiltä jälkeläiset, ja minä viskelen rapaa teidän kasvoihinne, teidän juhlauhrienne rapaa, ja siihen teidät itsenne kannetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Ja te tulette tietämään, että minä olen lähettänyt teille tämän käskyn, jotta minun liittoni Leevin kanssa pysyisi, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Minun liittoni hänen kanssansa oli elämä ja rauha, ja minä annoin sen hänelle peloksi; ja hän pelkäsi minua, vapisi minun nimeni edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Oikea opetus oli hänen suussansa, eikä vääryyttä tavattu hänen huuliltansa. Rauhassa ja vakaasti hän vaelsi minun kanssani, ja monet hän käänsi pois pahoista töistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Sillä papin huulten pitää tallettaman tieto, ja hänen suustansa etsitään opetus; sillä hän on Herran Sebaotin sanansaattaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Mutta te olette poikenneet tieltä, olette opetuksellanne saattaneet monet kompastumaan, olette turmelleet Leevin liiton, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Niinpä minäkin teen teidät halpana pidetyiksi ja alhaisiksi kaiken kansan edessä, koska te ette ole pitäneet minun teitäni, vaan olette olleet puolueelliset opetuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Eikö meillä kaikilla ole sama Isä? Eikö sama Jumala ole meitä luonut? Miksi me olemme uskottomat toinen toisellemme ja rikomme isiemme liiton?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Juuda on ollut uskoton, Israelissa ja Jerusalemissa on tehty kauhistus. Sillä Juuda on häväissyt Herran pyhäkön, jota Herra rakastaa, ja on ottanut avioksi vieraan jumalan tyttäriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Hävittäköön Herra siltä mieheltä, joka tämän tekee, Jaakobin majoista valvojan ja vastaajan ja Herran Sebaotin uhrilahjan tuojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Ja toiseksi te olette tehneet tämän: olette saattaneet Herran alttarin peitetyksi kyynelillä ja itkulla ja huokauksilla, niin ettei hän enää käänny uhrilahjojen puoleen eikä mielisty ottamaan mitään teidän kädestänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Mutta te sanotte: \"Minkätähden niin?\" Sentähden, että Herra on todistaja sinun ja sinun nuoruutesi vaimon välillä, jolle sinä olet ollut uskoton, vaikka hän on sinun puolisosi, sinun aviovaimosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Niin ei tee yksikään, jolla on jäännöskään Hengestä. Mutta kuinkas se yksi? Hän pyrki saamaan Jumalan lupaamia jälkeläisiä. Ottakaa siis vaari hengestänne älkääkä olko uskottomat nuoruutenne vaimolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Sillä minä vihaan hylkäämistä, sanoo Herra, Israelin Jumala, ja sitä, joka verhoaa vaatteensa vääryydellä, sanoo Herra Sebaot. Siis ottakaa vaari hengestänne älkääkä olko uskottomat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Te väsytätte Herran puheillanne. Mutta te sanotte: \"Miten väsytämme?\" Siten, että sanotte: \"Jokainen, joka pahaa tekee, on hyvä Herran silmissä, ja niihin hänellä on mielisuosio\"; tahi: \"Missä on tuomion Jumala?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Katso, minä lähetän sanansaattajani, ja hän on valmistava tien minun eteeni. Ja äkisti on tuleva temppeliinsä Herra, jota te etsitte, ja liiton enkeli, jota te halajatte. Katso, hän tulee, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Mutta kuka kestää hänen tulemisensa päivän, ja kuka voi pysyä, kun hän ilmestyy? Sillä hän on niinkuin kultasepän tuli ja niinkuin pesijäin saippua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Ja hän istuu ja sulattaa ja puhdistaa hopean, hän puhdistaa Leevin pojat, saa ne puhtaiksi kuin kullan ja hopean ja sitten he tuovat Herralle uhrilahjoja vanhurskaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Ja Herralle ovat otollisia Juudan ja Jerusalemin uhrilahjat niinkuin ammoin menneinä päivinä ja muinaisina vuosina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Ja minä lähestyn teitä pitääkseni tuomion ja tulen kiiruusti todistajaksi velhoja ja avionrikkojia ja väärinvannojia vastaan ja niitä vastaan, jotka sortavat palkkalaista palkanmaksussa, leskeä ja orpoa ja vääntävät vääräksi muukalaisen asian eivätkä pelkää minua, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Sillä minä, Herra, en muutu, ettekä te, Jaakobin lapset, herkeä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'isienne päivistä asti te olette poikenneet minun käskyistäni ettekä noudata niitä. Kääntykää minun tyköni, niin minä käännyn teidän tykönne, sanoo Herra Sebaot. Mutta te sanotte: \"Missä asiassa meidän on käännyttävä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Riistääkö ihminen Jumalalta? Te kuitenkin riistätte minulta. Mutta te sanotte: \"Missä asiassa me sinulta riistämme?\" Kymmenyksissä ja antimissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Te olette kirouksella kirotut, kun te, koko kansa, riistätte minulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Tuokaa täydet kymmenykset varastohuoneeseen, että minun huoneessani olisi ravintoa, ja siten koetelkaa minua, sanoo Herra Sebaot: totisesti minä avaan teille taivaan akkunat ja vuodatan teille siunausta ylenpalttisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Ja minä karkoitan nuhtelullani teiltä syöjäsirkat turmelemasta teidän maanne hedelmää, eikä teidän viiniköynnöksenne kedolla ole hedelmätön, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Ja teidän onneanne kiittävät kaikki pakanat, sillä te tulette olemaan ihasteltu maa, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Ynseät ovat teidän puheenne minua vastaan, sanoo Herra. Mutta te sanotte: \"Mitä me olemme puhuneet sinua vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Te sanotte: \"Herran palveleminen on turha; ja mitä hyötyä siitä on ollut, että me olemme hänelle suorittaneet säädetyt tehtävät ja että olemme vaeltaneet murheellisina Herran Sebaotin kasvojen edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Nyt me kiitämme julkeitten onnea. Ne, jotka tekevät sitä, mikä jumalatonta on, ne tulevat raketuiksi. He kiusaavat Jumalaa, mutta pelastuvat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Silloin myös Herraa pelkääväiset puhuvat toinen toisensa kanssa, ja Herra tarkkaa ja kuulee; ja muistokirja kirjoitetaan hänen edessänsä niiden hyväksi, jotka Herraa pelkäävät ja hänen nimensä kunniassa pitävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Ja he ovat, sanoo Herra Sebaot, sinä päivänä, jonka minä teen, minun omaisuuteni. Ja minä olen heille laupias, niinkuin mies on laupias pojallensa, joka häntä palvelee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Ja te näette jälleen, mikä on ero vanhurskaan ja jumalattoman välillä, sen välillä, joka palvelee Jumalaa, ja sen, joka ei häntä palvele.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Sillä katso: se päivä on tuleva, joka palaa kuin pätsi. Ja kaikki julkeat ja kaikki, jotka tekevät sitä, mikä jumalatonta on, ovat oljenkorsia; ja heidät polttaa se päivä, joka tuleva on, sanoo Herra Sebaot, niin ettei se jätä heistä juurta eikä oksaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Mutta teille, jotka minun nimeäni pelkäätte, on koittava vanhurskauden aurinko ja parantuminen sen siipien alla, ja te käytte ulos ja hypitte kuin syöttövasikat');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'ja tallaatte jumalattomat; sillä he tulevat tomuksi teidän jalkapohjienne alle sinä päivänä, jonka minä teen, sanoo Herra Sebaot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Muistakaa minun palvelijani Mooseksen laki, jonka minä Hoorebilla hänelle säädin koko Israelia varten käskyiksi ja oikeuksiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Katso, minä lähetän teille profeetta Elian, ennenkuin tulee Herran päivä, se suuri ja peljättävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Ja hän on kääntävä jälleen isien sydämet lasten puoleen ja lasten sydämet heidän isiensä puoleen, etten minä tulisi ja löisi maata, vihkisi sitä tuhon omaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Tämä on kertomus Toobitista, Toobielin pojasta, joka oli Hananielin poika, joka Aduelin poika, joka Gabaelin poika, Asielin suvusta, Naftalin sukukunnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Hänet oli Assurin kuninkaan Enemessarin päivinä viety pois vankina Tisbestä, joka oli etelään Kydioksesta Naftalissa, Galileassa, Asserin yläpuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Minä, Toobit, vaelsin totuuden teillä ja vanhurskaudessa kaiken elinaikani. Ja minä annoin runsaasti almuja veljilleni ja kansalaisilleni, joiden oli täytynyt lähteä kanssani assyrialaisten maahan, Niiniveen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Minun nuoruudessani, ollessani kotiseudullani Israelin maassa, oli minun kantaisäni Naftalin koko sukukunta luopunut Jerusalemin temppelistä, sen kaupungin, joka oli valittu kaikista israelin sukukunnista, että kaikki heimot siellä uhraisivat; ja se temppeli, Korkeimman asumus, oli pyhitetty ja rakennettu ikuisiksi ajoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Ja kaikki sukukunnat, jotka olivat mukana luopumuksessa, uhrasivat Baalin vasikalle, niin myös minun kantaisäni Naftalin huonee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Minä yksin vaelsin usein Jerusalemiin juhlina, niinkuuin on määrätty koko Israelille ikuisella säädöksellä, ja vein mukanani uutiset ja kymmenykset maantuotteista ja esikoiset villoista');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'ja annoin ne papeille, Aaronin pojille, alttaria varten; kymmenykset maan tuotteista minä annoin Leevin pojille, jotka tekevät palvelusta Jerusalemissa; ja toisen kymmenyksen minä myin ja menin Jerusalemiin ja käytin sen siellä joka vuosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Ja kolmannen kymmenyksen minä annoin niille, joille se kuuluu, niinkuin Debora, minun isäni äiti, oli käskenyt minun tehdä; sillä minä olin jäänyt isästäni orvoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Sittenkuin minä olin tullut mieheksi, minä otin vaimokseni Hannan, joka kuului meidän omaan sukuumme, ja hän synnytti minulle Tobiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Kun meidät oli viety vankeina Niiniveen, söivät kaikki minun veljeni ja kansalaiseni pakanain ruokia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Mutta minä varoin niitä syömästä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'sillä minä ajattelin Jumalaa kaikesta sydämestäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Ja korkein antoi minun näyttää sorealta ja kauniilta Enemessarin silmissä, ja minä sain tehdä hänelle ostoksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Niin minä tein matkan Meediaan ja jätin säilytettäväksi kymmenen talenttia hopeaa Gabaelille, Gabriaan veljelle, Meedian Rageksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Ja Enemessarin kuoltua tuli hänen poikansa Sennakerim kuninkaaksi hänen jälkeensä. Hänen aikanaan olivat tiet epävarmat, niin etten minä enää voinut matkustaa Meediaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jo Enemessarin päivinä minä annoin runsaasti almuja veljilleni:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'leipääni minä annoin isoaville ja vaatteitani alastomille. Ja jos näin jonkun kansalaiseni kuolleen ja viskatun Niiniven muurin taakse, niin minä hautasin hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Ja jos kuningas Sennakerim, palattuaan pakolaisena Juudeasta, surmautti jonkin, niin minä salaa hautasin hänet. Sillä hän surmautti monta kiivaudessansa; ja jos kuningas etsi heidän ruumiitaan, ei niitä löydetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Mutta muuan Niiniveen asukas meni ja ilmiantoi kuninkaalle, että minä niitä hautasin; silloin minä lymysin. Ja kun sain tietää, että minua etsittiin tapettavaksi, niin minä peljästyin ja lähdin pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Ja kaikki minun omaisuuteni ryöstettiin, eikä minulle jätetty mitään paitsi minun vaimoni Hanna ja minun poikani Tobias.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Mutta ei ollut kulunut viittäkymmentä päivää, ennenkuin hänet murhasi kaksi hänen poikaansa, jotka pakenivat Araratin vuorille. Ja hänen poikansa Sakerdon tuli kuninkaaksi hänen jälkeensä, ja hän asetti Akiakarin, Hanaelin pojan, minun veljenpoikani, valtakuntansa kaikkien rahavarain hoitajaksi ja koko hallinnon johtajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Ja Akiakar rukoili minun puolestani, ja niin minä sain palata Niiniveen. Akiakar oli juomanlaskija ja sinetinvartija, valtiokansleri ja rahavarainhoitaja; ja Sakerdon oli asettanut hänet lähimmäksi mieheksensä. Ja hän oli minun veljenpoikani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Kun minä olin palannut jälleen kotiini ja saanut takaisin vaimoni Hannan ja poikani Tobiaan, niin minä helluntaijuhlana, joka on seitsemän viikon pyhä, valmistin juhlapöydän ja asetuin aterialle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Nähdessäni nyt paljot ruuat minä sanoin pojalleni: »mene, ja jos löydät veljiemme joukosta jonkun köyhän, joka ajattelee Herraa, niin tuo hänet tänne; katso, minä odotan sinua.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Ja hän tuli takaisin ja sanoi: »Isäni, muuan kansalaisemme on kuristettu ja viruu torilla».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Ja ennenkuin olin mitään nauttinut, minä nousin kiiruusti ja korjasin hänet suojaan, kunnes aurinko laskisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Sitten minä palasin takaisin ja peseydyin ja söin leipäni murheessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'Ja mieleeni johtui Aamoksen ennustus, kuinka hän sanoi: »Teidän juhlanne muuttuvat murheeksi ja kaikki teidän iloitsemisenne valitusvirreksi».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Ja minä purskahdin itkuun. Kun aurinko sitten oli laskenut, niin minä menin ja kaivoin haudan ja hautasin hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Muta naapurit pilkkasivat minua ja sanoivat: »Nyt hän ei enää pelkää, että hänet tapettaisiin tämän teon tähden; hänen oli pakko paeta, ja katso, nyt hän taas hautaa kuolleita!»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Samana yönä minä palasin takaisin toimitettuani hautauksen. Ja koska olin tullut saastaiseksi, minä paneuduin nukkumaan pihan muurin viereen, ja kasvoni olivat peittämättömät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Mutta minä en tietänyt, että muurissa oli varpusia. Ja silmieni ollessa auki laskivat varpuset lämmintä likaa minun silmiini; ja silloin tuli silmiini valkeita pilkkuja, ja minä menin lääkäriin, mutta lääkärit eivät voineet minua auttaa. Mutta Akiakar elätti minua, kunnes hän meni Elymaikseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Ja vaimoni Hanna teki palkasta naisten töitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'ja lähetti ne sitten työnantajilla, ja nämä maksoivat hänelle palkan ja antoivat lisäksi vohlan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Mutta kun hän tuli minun tyköni, niin se alkoi määkiä. Silloin minä kysyin häneltä: »Mistä on tämä vohla? Eihän se vain ole varastettu? Anna se takaisin sen omistajille, sillä ei ole luvallista syödä varastettua.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Hän vastasi:»Se on annettu minulle lahjaksi, palkkani lisäksi». Mutta minä en uskonut häntä, vaan käskin antaa sen omistajille takaisin, ja minä vihastuin häneen. Silloin hän vastasi ja sanoi minulle: »Missä ovat nyt sinun almusi ja vanhurskaat tekosi? Katso, nyt sen tietää, millainen sinä olet.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'Silloin minä tulin murheelliseksi ja purskahdin itkuun; ja minä rukoilin tuskassani ja sanoin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, '»Herra, sinä olet vanhurskas, ja kaikki sinun tekosi ja kaikki sinun tiesi ovat laupeus ja totuus; sinä tuomitset aina oikean ja vanhurskaan tuomion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Muista minua ja katso minun puoleeni. Älä rankaise minua syntieni mukaan, joita isäni ovat tehneet sinun edessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Sillä he olivat tottelemattomat sinun käskyillesi; ja niin sinä annoit meidät alttiiksi ryöstölle, vankeudelle ja kuolemalle ja sallit meidän tulla pilkaksi ja sananparreksi kaikille pakanakansoille, joiden keskuuteen me olemme hajotetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Niin ovat nyt sinun monet tuomiosi oikeat, kun sinä teet minulle minun ja isieni syntien mukaan, koska emme ole pitäneet sinun käskyjäsi; sillä me emme ole vaeltaneet totuudessa sinun edessäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'Tee nyt minulle, niinkuin sinulle on otollista. Käske ottaa pois minun henkeni, että minä saisin täältä erota ja tulla maaksi, sillä minulle on parempi kuolla kuin elää, koska minun on täytynyt kuulla valheellisia parjauksia. Minä olen suuren murheen vallassa. Käske, että jo nyt saisin päästä ahdistuksesta ja mennä iankaikkiseen asuntoon. Älä käännä minusta pois kasvojasi.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Tapahtui niin, että samana päivänä myös Raguelin tytär Saara Meedian Ekbatanassa sai kuulla herjauksia isänsä palvelusnaisilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Sillä hänet oli annettu seitsemälle miehelle, mutta paha henki, Asmodeus, oli tappanut heidät, ennenkuin he olivat yhtyneet häneen. Ja naiset sanoivat hänelle: »Oletko mieletön, kun surmaat miehesi? Sinulla on jo ollut seitsemän miestä, mutta sinua ei ole kutsuttu niistä yhdenkään nimen mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Miksi lyöt meitä? Jos he kuolivat, niin mene heidän perässänsä. Älköön meidän ikinä tarvitko nähdä sinun poikaasi tai tytärtäsi.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Kun hän tämän kuuli, tuli hän niin kovin murheelliseksi, että hän tahtoi hirttäytyä. Mutta hän sanoi: »Minä olen isäni ainoa lapsi. Jos minä sen teen, niin hänelle tulee häpeä, ja minä saatan hänen harmaat hapsensa vaipumaan murheella tuonelaan.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Ja hän rukoili ikkunan edessä ja sanoi: »Ole kiitetty sinä, Herra, minun Jumalani, ja olkoon kiitetty sinun pyhä ja kunnioitettu nimesi iankaikkisesti. Kiittäkööt sinua kaikki sinun tekosi ainiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Ja nyt, Herra, minä käännän silmäni ja kasvoni sinun puoleesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Käske minun erota tämän maan päältä, ettei minun enää tarvitsisi kuulla herjausta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Sinä tiedät, Herra, että minä olen puhdas kaikesta miehen kanssa tehdystä synnistä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'ja etten ole saastuttanut nimeäni enkä isäni nimeä siinä maassa, jossa minä elän vankina. Minä olen isäni ainoa lapsi, eikä hänellä ole muuta lasta, joka hänet perisi, eikä muuta läheistä omaista tai tämän poikaa, jolle minun pitäisi säilyttää itseni vaimoksi. Minulta on jo kuollut seitsemän miestä; mitä varten minä vielä eläisin? Mutta jos sinä et näe hyväksi surmata minua, niin käske, että saan kokea laupeutta ja armoa, ettei minun enää tarvitse kuulla herjausta.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Ja molempien rukous tuli kuulluksi Jumalan kirkkauden edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Ja Raafael lähetettiin parantamaan heidät molemmat: ottamaan pois Toobitin silmistä valkeat pilkut ja antamaan Saara, Raguelin tytär, vaimoksi Tobiaalle, Toobitin pojalle, koska Tobiaalla oli sukuoikeus saada hänet vaimoksi, sekä kahlehtimaan paha henki Asmodeus. Samaan aikaan palasi Toobit takaisin ja meni taloonsa, ja Saara, Raguelin tytär, astui alas yliskammiostansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Sinä päivänä muistui Toobitin mieleen rahat, jotka hän oli tallettanut Gabaelin haltuun Meedian Rageksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Ja hän sanoi itsekseen: »Minä olen pyytänyt saada kuolla;miksi en kutsu luokseni poikaani Tobiasta, ilmaistakseni asian hänelle, ennenkuin kuolen?»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Ja hän kutsui hänet ja sanoi: »Poikani, kun minä olen kuollut, niin hautaa minut ja pidä huoli äidistäsi. Kunnioita häntä kaikkina elämäsi päivinä ja tee sitä, mikä hänelle on mieleen, äläkä tuota hänelle murhetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Muista, poikani, että hän on nähnyt monta vaaraa sinun tähtesi, kun hän kantoi sinua kohdussansa. Ja kun hän on kuollut, hautaa hänet minun viereeni samaan hautaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Ajattele, poikani, joka päivä Herraa, meidän Jumalaamme, äläkä ole altis tekemään syntiä ja rikkomaan hänen käskyjänsä. Harjoita vanhurskautta kaikkina elämäsi päivinä, äläkä vaella vääryyden teillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'Sillä jos sinä teet totuuden, niin on sinulla oleva menestys töissäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Anna almuja omaisuudestasi kaikille, jotka harjoittavat vanhurskautta, ja kun almuja annat, älköön sinun silmäsi olko karsas. Älä käännä kasvojasi pois kenestäkään köyhästä, ja niin ei Jumalakaan käännä sinusta pois kasvojansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Jos sinulla on paljon, niin anna paljon almuja paljostasi; jos sinulla on vähän, niin älä arkaile antaa almuja vähästäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'Niin sinä keräät itsellesi hyvän aarteen hädän päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Sillä almut pelastavat kuolemasta eivätkä salli joutua pimeyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Almut ovat hyvä uhrilahja Korkeimman edessä kaikkien niitä antavien hyväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Kavahda, poikani, kaikkinaista haureutta; ja ennen kaikkea: ota vaimo isiesi suvusta. Älä ota avioksi vierasta naista, joka ei ole isiesi sukukuntaa, sillä me olemme profeettain poikia. Ajattele, poikani, kuinka Nooa, Aabraham, Iisak ja Jaakob, meidän isämme muinaisilta päiviltä, ottivat kaikki itselleen vaimot sukulaisistansa; he saivat siunauksen lapsissansa, ja heidän jälkeläisensä saavat periä maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Ja nyt, poikani, rakasta veljiäsi äläkä ylpisty sydämmessäsi, niin että halveksut veljiäsi ja kansasi poikia ja tyttäriä etkä ota itsellesi heistä vaimoa. Sillä ylpeydestä tulee turmio ja paljon onnettomuutta, kelvottomasta elämästä köyhyys ja suuri puute. Sillä kelvoton elämä on nälän äiti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Älä pidätä yön ylitse palkkaa keneltäkään, joka on sinun työssäsi, vaan maksa se hänelle kohta. Jos sinä palvelet Jumalaa, niin se sinulle korvataan, Poikani, ota vaari itsestäsi kaikissa teoissasi, ja käyttäydy soveliaasti kaikessa vaelluksessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Mitä itse vihaat, sitä älä tee kenellekkään muulle. Älä juo viiniä päihtymykseen asti, älköönkä päihtymys vaeltako sinun kanssasi tiellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Anna leipääsi nälkäiselle ja vaatteitasi alastomille. Kaikesta, mitä sinulla on yltäkyllin, anna almuja, älköönkä sinun silmäsi olko karsas almuja antaessasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Anna runsaasti leipääsi vanhurskasten hautajaisiin, mutta syntisille älä anna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Etsi neuvoa kaikilta ymmärtäväisiltä, äläkä mitään hyödyllistä neuvoa halveksu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Kiitä aina Herraa Jumalaa ja pyydä häneltä, että tiesi olisivat tasaiset ja kaikki polkusi ja neuvosi onnelliset. Sillä ihmiset ovat kaikki neuvottomia, mutta Herra itse antaa kaiken hyvän; ja kenen hän tahtoo, sen hän alentaa, niinkuin hyväksi näkee. Nyt siis, poikani, muista minun käskyjäni, älköötkä ne hävitkö sinun sydämmestäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Tahdon nyt kertoa sinulle niistä kymmenestä hopeatalentista, jotka minä talletin Gabaelin, Gabriaan veljen, haltuun Meedian Rageksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Älä pelkää, poikani, vaikka me olemme köyhtyneet; sinulla on paljon, jos pelkäät Jumalaa ja pysyt erilläsi kaikkinaisesta synnistä ja teet sitä, mikä on otollista hänen edessänsä.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Ja Tobias vastasi hänelle:»Isäni, minä teen kaiken, mitä olet käskenyt minun tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Mutta kuinka voin saada rahat, kun minä en tunne sitä miestä?»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Silloin hän antoi hänelle talletuskirjan ja sanoi hänelle: »Etsi itsellesi joku, joka matkustaa kanssasi; minä annan hänelle palkan, niin kauan kuin vielä elän. Lähde sitten matkalle ja hae rahat.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Ja hän lähti etsimään sellaista miestä ja löysi Raafaelin, joka oli enkeli, vaikka Tobias ei sitä tiennyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'ja sanoi hänelle: »Voinko matkustaa sinun kanssasi Meedian Ragekseen ja tunnetko ne seudut?»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Enkeli sanoi hänelle: »Matkustan mielelläni sinun kanssasi, minä tunnen tien ja olen majaillut veljemme Gabaelin tykönä.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Tobias sanoi hänelle: »Odota minua, minä ilmoitan sen isälleni».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Hän vastasi: »Mene, mutta älä viivy kauan».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Ja hän meni isänsä tykö ja sanoi hänelle: »Katso, minä olen löytänyt erään, joka tahtoo matkustaa kanssani». Isä sanoi: »Kutsu hänet luokseni, että saisin tietää, mistä sukukunnasta hän on ja onko hän luotettava matkatoveriksesi».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Silloin hän kutsui hänet, ja hän astui sisään, ja he tervehtivät toisiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Ja Toobit sanoi hänelle: »Mistä sukukunnasta ja mistä perheestä sinä olet, veljeni? Ilmoita se minulle.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Hän vastasi: »Etsitkö heimoa ja sukua vai palkkalaista, joka matkustaisi poikasi kanssa?» Toobit sanoi hänelle: »Tahtoisin, veljeni, tietää sukusi ja nimesi».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Hän vastasi: »Minä olen Asarias, suuren Ananiaan poika, sinun veljiäsi».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Silloi Toobit sanoi hänelle: »Ole tervetullut, veljeni; älä ole siitä minulle vihoissasi, että koetin saada tietää sukukuntasi ja perheesi. Satutkin olemaan, veljeni, hyvää ja jaloa sukua. Sillä minä opin tuntemaan Ananiaan ja Joonatanin, suure Semeaan pojat, kun yhdessä matkustimme Jerusalemiin siellä kumartaen rukoilemaan ja uhraamaan uutiset ja kymmenykset kylvön sadosta; he eivät olleet hairahtuneet samaan eksytykseen kuin muut veljemme. Olet hyvää juurta, veljeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Mutta sano minulle, mikä palkka minun tulee sinulle antaa? Ehkä drakma päivää kohti ja mitä muutoin on tarpeen itseäsi ja poikaani varten?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Ja palkan lisäksi minä annan sinulle vielä lahjan, jos tulette terveinä takaisin.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Näin he sopivatkin. Ja isä sanoi Tobiaalle: »Valmistaudu matkalle, ja olkoon matkanne onnellinen». Kun poika oli varustautunut matkalle, sanoi isä hänelle: »Lähde tämän miehen kanssa. Mutta Jumala, joka asuu taivaassa, antakoon teidän matkanne onnistua, ja hänen enkelinsä seuratkoon teitä.» Sitten he molemmat menivät ulos lähteäkseen matkalle, ja nuorukaisen koira lähti mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Mutta hänen äitinsä Hanna alkoi itkeä ja sanoi Toobitille: »Miksi olet lähettänyt pois poikamme? Eikö hän ole kuin sauva kädessämme, kun hän joka päivä tulee ja menee silmäimme edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Älköön raha tuljo rahan lisäksi, vaan olkoon se poikamme hengen lunastusraha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Sillä minkä Herra on antanut meille siitä elääkseemme, se meille riittää.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Mutta Toobit sanoi hänelle: »Älä ole huolissasi, sisareni. Hän on palaava terveenä takaisin, ja sinun silmäsi saavat nähdä hänet jälleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Sillä hyvä enkeli on saattava häntä, ja hänen matkansa on onnistuva, ja hän palaava terveenä takaisin.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Silloin hän taukosi itkemästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'He kulkivat nyt tietä ja tulivat illalla Tigris-virran rannalle ja yöpyivät siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Ja nuorukainen astui veteen kylpemään. Silloin hyppäsi kala ylös virrasta ja aikoi niellä nuorukaisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Mutta enkeli sanoi hänelle: »Tartu kiinni kalaan». Silloin nuorukainen tarttui kalaan ja viskasi sen maalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Ja enkeli sanoi hänelle: »Leikkaa kala auki ja ota sydän, maksa ja sappi ja säilytä ne huolellisesti.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Ja nuorukainen teki, niinkuin enkeli oli hähelle sanonut; mutta kalan he paistoivat ja söivät. Sitten molemmat kulkivat eteenpäin, kunnes tulivat Ekbatanan läheisyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Silloin sanoi nuorukainen enkelille: »Asarias, veljeni, mitä varten meillä on sen kalan maksa, sydän ja sappi?»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Hän vastasi hänelle: »Sydäntä ja maksaa on, jos jotakin ihmistä vaivaa riivaaja tai paha henki, savustettava sen ihmisen, miehen tai vaimon, edessä, ja niin vaiva lakkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Sapella taas on voideltava sitä, jonka silmissä on valkoisia pilkkuja, ja niin hän paranee.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Kun he lähestyivät Ragesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'sanoi enkeli nuorukaiselle: »Veljeni, tänään me jäämme yöksi Raguelin tykö; hän on sinun sukulaisesi, ja hänellä on Saara niminen tytär.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Minä puhun isälle hänestä, että hän antaa hänet sinulle vaimoksi, sillä sinulle kuuluu hänen perintönsä; sinähän olet ainoa mies hänen sukuansa. Tyttö on myös kaunis ja ymmärtäväinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Kuule siis minua, minä puhuttelen hänen isäänsä, ja kun me palaamme Rageksesta, vietämme häät. Sillä minä tiedän, että Raguel Mooseksen lain mukaan ei voi antaa häntä kenellekkään muulle miehelle tulematta kuolemaan vikapääksi; sillä sinulla on oikeus ennen ketään muuta miestä saada perintö.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Silloin nuorukainen sanoi enkelille: »Asarias, veljeni, minä olen kuullut, että tyttö on annettu seitsemälle miehelle, mutta että kaikki ovat kuolleet, morsiuskammiossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Ja minä olen isäni ainoa poika, ja minä pelkään, että kun menen hänen tykönsä, niin minä kuolen niinkuin nuo edellisetkin. Sillä häntä rakastaa paha henki, ja se ei tee kenellekkään muulle pahaa kuin niille, jotka häntä lähestyvät. Sentähden minä pelkään, että minäkin kuolen ja niin saatan isäni ja äitini vaipumaan hautaan minua murehtien; eikä heillä ole toista poikaa, joka heidät hautaisi.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Mutta enkeli sanoi hänelle: »Etkö muista käskyä, minkä isäsi sinulle antoi, että sinun tulee ottaa vaimo omasta suvustasi? Ja nyt, kuule minua, veljeni: hän on tuleva sinun vaimoksesi. Älä ole huolissasi pahan hengen tähden, sillä tänä yönä Saara annetaan sinulle vaimoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Kun sinä menet morsiuskammioon, tulee sinun ottaa hehkuvaa suitsutustuhkaa ja panna sen päälle kalan sydäntä ja maksaa ja savustaa sillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Kun paha henki tuntee käryn, niin se pakenee eikä enää ikinä tule takaisin. Ja kun sinä sitten tahdot lähestyä vaimoasi, nouskaa molemmat ylös ja huutakaa avuksenne armollista Jumalaa; hän on pelastava teidät ja oleva armollinen. Älä pelkää, sillä hänet on määrätty sinulle alusta alkaen, ja sinä olet pelastava hänet; hän on lähtevä sinun kanssasi, ja minä luulen, että sinä saat hänestä lapsia.» Kun Tobias tämän kuuli, syttyi hänessä rakkaus Saaraan, ja hänen sydämensä kiihtyi suuresti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Ja niin he tulivat Ekbatanaan, ja kun he saapuivat Raguelin taloon, tuli Saara heitä vastaan ja tervehti heitä ja he häntä. Ja hän vei heidät kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Ja Raguel sanoi vaimolleen Ednalle: »Kuinka samannäköinen onkaan tämä nuorukainen kuin sisareni poika Toobit!»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Ja Raguel kysyi häneltä: »Mistä olet veljeni?» He vastasivat hänelle: »Me olemme niitä naftalilaisia, jotka elävät pakkosiirtolaisina Niinivessä».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Silloin hän sanoi heille: »Tunnetteko veljemme Toobitin?»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'He vastasivat: »Kyllä tunnemme. Hän on elossa ja terveenä.» Ja Tobias lisäsi: »Hän on minun isäni».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Silloin Raguel nousi kiiruusti ylös ja suuteli häntä ja purskahti itkuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Ja hän siunasi häntä ja sanoi hänelle: »Sinä olet hyvän ja jalon miehen poika.» Ja kuultuaan, että Toobit oli menettänyt näkönsä, hän tuli murheelliseksi ja itki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Myös hänen vaimonsa Edna ja hänen tyttärensä Saara itkivät. Ja he ottivat heidät vastaan auliisti. Sitten he teurastivat oinaan ja panivat esille paljon ruokia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Mutta Tobias sanoi Raafaelille: »Asarias, veljeni, puhu nyt siitä, mistä mainitsit matkalla, että asia saataisiin päätökseen».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Silloin hän ilmoitti asian Raguelille ja Raguel sanoi Tobiaalle: »Syö, juo ja ole iloinen, sillä sinun tulee saada minun tyttäreni; kuitenkin minun on ilmoitettava sinulle totuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Olen antanut tyttäreni seitsemälle miehelle, mutta jokainen heistä, niin pian kuin meni hänen tykönsä, kuoli kohta yön tultua. Mutta ole nyt iloinen.» Mutta Tobias sanoi: »En maista täällä mitään, ennenkuin välillämme on tehty laillinen sopimus». Raguel sanoi: »Ota hänet tästä hetkestä, lain mukaan; sinä olet hänen sukulaisensa, ja hän on sinun. Armollinen Jumala antakoon teille ylimmän onnen.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Sitten hän kutsui tyttärensä Saaran, tarttui hänen käteensä ja antoi hänet Tobiaalle vaimoksi sanoen: »Katso, ota hänet Mooseksen lain mukaan ja vie hänet isäsi tykö». Ja hän siunasi heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Senjälkeen hän kutsui vaimonsa Ednan; ja hän otti lehden ja kirjoitti sille aviosopimuksen ja sinetöitsi sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Sitten he rupesivat aterioimaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Senjälkeen Raguel kutsui vaimonsa Ednan ja sanoi hänelle: »Sisareni, valmista toinen kammio ja vie Saara sinne».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Vaimo teki, niinkuin hän oli käskenyt, ja vei Saaran sinne; mutta tämä alkoi itkeä. Ja hän hyvin ymmärsi tyttärensä kyyneleet ja sanoi hänelle: »Lapseni, ole turvallisella mielellä. Taivaan ja maan Herra antakoon sinulle ilon tämän murheen sijasta. Ole rohkealla mielellä, tyttäreni.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Kun he olivat aterioineet, veivät he Tobiaan Saaran kammioon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Mutta kun hänen piti mennä sinne, muisti hän Raafaelin sanat ja otti kuumaa suitsuketuhkaa ja pani sen päälle kalan sydäntä ja maksaa ja savusti sillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Kun paha henki tunsi käryn, niin se pakeni hamaan Ylä-Egyptiin asti, ja enkeli sitoi sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Mutta kun ovi oli suljettu heidän molempien jälkeen, nousi Tobias ylös vuoteesta ja sanoi: »Nouse ylös, sisareni, ja rukoilkaamme, että Herra armahtaisi meitä».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Ja Tobias alkoi rukoilla ja sanoi: »Ole kiitetty sinä, isiemme Jumala, ja kiitetty olkoon sinun pyhä ja kunnioitettu nimesi iankaikkisesti. Sinua kiittäkööt taivaat ja kaikki sinun luotusi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'Sinä loit Aadamin ja annoit hänelle Eevan, hänen vaimonsa, avuksi ja tueksi. Heistä on ihmissuku saanut alkunsa. Sinä sanoit: \'Ei ole ihmisen hyvä olla yksinänsä, tehkäämme hänelle apu, joka on hänen kaltaisensa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Ja nyt, Herra: minä en ota tätä sisartani haureellisesta halusta, vaan puhtaasta mielestä. Käske, että saisin armon ja että hänen kanssaan vanhaksi eläisin.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Ja Saara sanoi hänen kanssaan: »Aamen!»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Ja he nukkuivat molemmat sen yön. Mutta Raguel nousi ylös, meni ja kaivoi haudan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Sillä hän ajatteli: »Kaiketi tämäkin kuolee.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Kun Raguel oli tullut takaisin kotiinsa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'sanoi hän vaimolleen Ednalle: »Lähetä yksi palvelusnaisista katsomaan, onko hän hengissä; jollei, niin me hautaamme hänet, eikä kukaan saa siitä mitään tietää».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Kun palvelusnainen avasi oven ja meni sisään, havaitsi hän heidän molempien nukkuvan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Hän meni silloin ulos ja ilmoitti isäntäväelleen, että ylkä eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Silloi Raguel kiitti Jumalaa sanoen: »Ole kiitetty sinä, Jumala, kaikella kiitoksella, ja sinua kiittäkööt sinun pyhäsi ja kaikki sinun luotusi; kaikki sinun enkelisi ja valittusi kiittäkööt sinua iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Ole kiitetty, sillä sinä olet valmistanut minulle ilon; minulle ei käynyt niinkuin minä luulin, vaan suuren laupeutesi mukaan sinä tämän meille teit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Ole kiitetty, sillä sinä olet armahtanut näitä kahta, jotka ovat vanhempansa ainoat lapset; tee heille, Herra, laupeus ja suo heidän elää elämänsä terveydessä, ilossa ja armossa.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Sitten hän käski palvelijainsa luoda haudan umpeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Ja hän laittoi heille häät, jotka kestivät neljätoista päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Mutta ennenkuin hääpäivät olivat loppuun kuluneet, vannotti Raguel häntä, ettei hän saisi lähteä pois, ennenkuin ne neljätoista hääpäivää olivat loppuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Silloin hän oli saava puolet hänen omaisuudestaan ja voisi terveenä mennä takaisin isänsä tykö. Ja hän lisäsi: »Loput saat, kun minä ja vaimoni olemme kuolleet.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Ja Tobias kutsui luoksensa Raafaelin ja sanoi hänelle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, '»Asarias, veljeni, ota mukaasi palvelija ja kaksi kamelia ja mene Meedian Ragekseen, Gabaelin luo, ja toimita minulle rahat ja tuo myös hänet itsensä häihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Sillä Raguel on vannonut, etten saa lähteä täältä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'ja isäni lukee päivät, niin että hän käy kovin levottomaksi, jos minä viivyn kauan.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Silloin Raafael lähti matkalle, ja hän yöpyi Gabaelin luo ja antoi hänelle talletuskirjan. Tämä taas toi esiin sinetöidyt kukkarot ja antoi ne hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Ja varhain aamulla he lähtivät yhdessä matkalle ja tulivat häihin. Ja Tobias ylisti vaimoansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Mutta hänen isänsä Toobit luki jokaisen kuluvan päivän. Ja kun matkaan tarvittavat päivät olivat kuluneet umpeen eikä häntä kuulunut kotiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'niin Toobit sanoi: »Kenties ei heitä ole otettu vastaan? Tai on Gabael ehkä kuollut, niin ettei kukaan anna hänelle rahoja?»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Ja hän oli kovin murheissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Mutta hänen vaimonsa sanoi hänelle: »Poika on joutunut tuhon omaksi, koska hän viipyy niin kauan». Ja hän alkoi itkeä häntä ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, '»Kuinka minua surettaakaan, lapseni, että päästin sinut, silmieni valon, menemään!»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Mutta Toobit sanoi hänelle: »Ole vaiti; älä ole huolissasi, hän on terveenä».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Vaimo vastasi hänelle: »Ole vaiti! Älä minua petä! Minun lapseni on joutunut tuhon omaksi.» Ja joka päivä hän meni tielle, jota pitkin poika oli lähtenyt matkalle; päivällä hän ei syönyt mitään, ja yökaudet hän itki lakkaamatta poikaansa Tobiasta, kunnes ne neljätoista hääpäivää, joiden ajaksi Raguel oli vannottanut hänet jäämään sinne, olivat loppuun kuluneet. Mutta Tobias sanoi Raguelille: »Päästä minut menemään, sillä isäni ja äitini eivät enää toivo näkevänsä minua».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Silloin hänen appensa vastasi hänelle: »Jää tänne luokseni; minä lähetän sinun isällesi tiedon voinnistasi».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Tobias sanoi: »Päästä minut isäni tykö».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Ja Raguel nousi ja antoi hänelle hänen vaimonsa Saaran ja puolet omaisuudesta: orjia, karjaa ja rahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Sitten hän siunasi heidät ja lähetti heidät matkalle sanoen: »Taivaan Jumala suokoon teille onnea, lapseni, ennenkuin minä kuolen».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Ja tyttärelleen hän sanoi: »Kunnioita appivanhempiasi; he ovat nyt sinun vanhempasi. Toivon kuulevani sinusta hyvää.» Ja hän suuteli häntä. Ja Edna sanoi Tobiaalle: »Rakas veljeni, vieköön taivaan Jumala sinut kotiin ja suokoon minun nähdä sinulla lapsia tyttärestäni Saarasta, että minä saisin riemuita Herran edessä. Katso, minä uskon tyttäreni sinun huomaasi; älä tuota hänelle murhetta.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Senjälkeen Tobias lähti matkalle, ja hän kiitti Jumalaa siitä, että hän oli tehnyt hänen matkansa onnelliseksi. Ja hän sanoi jäähyväiset Raguelille ja hänen vaimolleen Ednalle. Sitten hän kulki eteenpäin, kunnes saapui Niinivee läheisyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'SilloinRaafael sanoi Tobiaalle: »Etkö tiedä, veljeni, kuinka oli isäsi laita lähtiessäsi hänen luotansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Kiiruhtakaamme vaimosi edellä ja laittakaamme talo järjestykseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Ja ota kalan sappi käteesi.» Sitten he lähtivät matkalle, ja koira seurasi heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Mutta hHanna istui ja katsoi tietä pitkin nähdäkseen poikansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Ja kun hän huomasi hänen tulevan, sanoi hän hänen isälleen: »Katso, poikani tulee ja mies, joka lähti hänen kanssaan».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Ja Raafael sanoi: »Minä tiedän, että isäsi tulee avaamaan silmänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Voitele sapella hänen silmänsä; kun hän tuntee kirvelyä, niin hän hieroo niitä, ja valkeat pilkut putoavat pois, ja hän näkee sinut.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Mutta Hanna kiiruhti heitä vastaan ja lankesi poikansa kaulaan ja sanoi hänelle: »Minä olen nähnyt sinut, lapseni, nyt tahtoisin kuolla». Ja he molemmat purskahtivat itkuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Silloin Toobit meni ovelle ja oli loukata itsensä. Mutta poika riensi häntä vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'tarttui isäänsä ja siveli sapella isänsä silmiä sanoen: »Ole turvallisella mielellä, isä».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Kun nyt silmiä alkoi kirvellä, hieroi hän niitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Silloin lähtivät hänen silmistään valkoiset pilkut, ja hän näki poikansa ja lankesi hänen kaulaansa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'ja purskahti itkuun ja sanoi: »Ylistettävä olet sinä, Jumala, ylistettävä sinun nimesi iankaikkisesti, ja ylistettävät kaikki sinun pyhät enkelisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Sillä sinä olet kurittanut minua, mutta olet nyt minua armahtanut. Katso, minä näen poikani Tobiaan.» Silloin hänen poikansa meni riemuiten huoneeseen; ja hän kertoi isälleen, mitä suurta ja ihmeellistä hänelle oli tapahtunut Meediassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Senjälkeen Toobit meni ulos kohtaamaan miniänsä Niiniveen portille; ja hän iloitsi ja kiitti Jumalaa. Ja ne, jotka näkivät hänen käyvän, ihmettelivät sitä, että hän oli saanut näkönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'Mutta Toobit tunnusti heidän edessään, että Jumala oli armahtanut häntä. Ja kun Toobit lähesty miniäänsä Saaraa, tervehti hän häntä sanoen: »Ole tervetullut, tyttäreni; ylistetty olkoon Jumala, joka on tuonnut sinnut meidän tykömme, niin olkoot myös isäsi ja äitisi». Ja kaiken hänen veljiensä keskuudessa Niinivessä oli ilo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Myös Akiakar ja hänen veljensä poika Nasbas saapuivat häihin. Ja Tobiaan häitä vietettiin ilon vallitessa seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Ja Toobit kutsui luokseen poikansa Tobiaan ja sanoi hänelle: »Katso, poikani, että mies, joka oli sinun matkakumppanisi, saa palkkansa; hänen tulee saada vähän lisääkin».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Hän vastasi: »Isä, minä voin vahingoitta antaa hänelle puolet siitä, mitä olen tuonut mukanani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Sillä hän on tuonut minut terveenä sinun tykösi, on parantanut minun vaimoni, tuonut minun rahani ja samoin parantanut sinut.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Silloin vanhus sanoi: »Sen hän on ansainnut».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Sitten hän kutsui tykönsä enkelin ja sanoi hänelle: »Ota puolet kaikesta, minkä olette mukananne tuoneet».');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Mutta tämä kutsui heidät molemmat syrjään ja sanoi heille: »Ylistäkää Jumalaa ja kiittäkää häntä; antakaa hänelle kunnia ja kiittäkää häntä kaikkien elävien olentojen edessä siitä, mitä hän on teille tehnyt. Hyvä on ylistää Jumalaa ja korottaa hänen nimeänsä ja kunnioittaen julistaa Jumalan tekoja. Älkää olko hitaat häntä kiittämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'On hyvä pitää salassa kuninkaan salaisuus, mutta saattaa julki, kunniaan, Jumalan teot. Tehkää sitä, mikä hyvä on, niin paha ei teitä kohtaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Hyvä on rukous yhdessä paaston, almujenannon ja vanhurskauden kanssa. Parempi vähäisen vanhurskaudella kuin paljon vääryydellä. Parempi antaa almuja kuin kerätä kulta-aarteita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Almut pelastavat kuolemasta ja puhdistavat kaikesta synnistä. Jotka almuja antavat ja vanhurskautta harjoittavat, ne saavat kauan elää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'mutta synnintekijät ovat oman elämänsä vihollisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'En tahdo teiltä mitään salata. Minähän sanoin, että on hyvä pitää salassa kuninkaan salaisuus, mutta saattaa julki, kunniaan, Jumalan teot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Niinpä siis: kun sinä rukoilit ja niin myös sinun miniäsi Saara, niin minä vein teidän rukouksenne Pyhän eteen, että hän ne muistaisi; ja kun sinä hautasit kuolleita, niin minä samoin olin sinun rinnallasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Ja kun sinä viivyttelemättä nousit ylös ja jätit ateriasi mennäksesi hautaamaan kuolleen, silloin ei sinun hyvä tekosi jäänyt minulta salaan, vaan minä olin sinun kanssasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Ja nyt on Jumala lähettänyt minut parantamaan sinut ja sinun miniäsi Saaran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Minä olen Raafael, yksi niistä seitsemästä pyhästä enkelistä, jotka esiinkantavat pyhien rukoukset ja jotka astuvat Pyhän eteen hänen kirkkaudessaan.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Silloin molemmat kauhistuivat ja lankesivat kasvoilleen, sillä heidät valtasi pelko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Mutta hän sanoi heille: »Älkää peljätkö: teillä on oleva rauha; ylistäkää Jumalaa iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Sillä en minä ole tullut omasta suosiostani, vaan teidän Jumalanne tahdosta. Ylistäkää siis häntä iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Kaiken tämän ajan minä olen ollut teidän näkyvissänne, mutta minä en ole syönyt enkä juonut, te olette nähneet vain näyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Kiittäkää nyt siis Jumalaa, sillä minä nousen hänen tykönsä, joka on minut lähettänyt. Ja kirjoittakaa kirjaan kaikki, mitä on tapahtunut.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Ja kun he nousivat ylös, eivät he enää nähneet häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Ja he ylistivät hänen suuria ja ihmeellisiä tekojansa, kuinka Herran enkeli oli heille ilmestynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Ja Toobit kirjoitti rukouksen, riemuvirren, ja sanoi: Ylistetty olkoon Jumala, joka elää iankaikkisesti, ja hänen kuninkuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Sillä hän kurittaa ja armahtaa, hän vie alas tuonelaan ja sieltä jälleen ylös, eikä kukaan voi paeta hänen kädestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Kiittäkää häntä, te Israelin lapset, pakanain edessä, sillä heidän keskuuteensa hän on meidät hajottanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Julistkaa siellä hänen valtasuuruuttansa, korottakaa häntä kaikkien elävien edessä: Sillä hän on meidän Herramme, ja hän on Jumala, meidän isämme, hamaan kaikkiin iankaikkisuuksiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Ja jos hän meitä kurittaakin pahojen tekojemme tähden, niin hän meitä jälleen armahtaa ja kokoaa meidät kaikista pakanakansoista, minne ikinä teidät on hajotettu heidän keskuuteensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Jos te käännytte hänen puoleensa kaikesta sydämestänne ja kaikesta sielustanne, ja teette totuuden hänen edessänsä, silloin hän kääntyy teidän puoleenne eikä enää peitä teiltä kasvojansa. Katsokaa, mitä hän on teille tekevä, ja olkoon suunne täynnä hänen kiitostansa. Ylstäkää vanhurskauden Herraa ja korottakaa iankaikkista Kuningasta. Minä kiitän häntä vankeuteni maassa ja julistan hänen voimaansa ja valtasuuruuttansa synnintekijäin kansalle. Kääntykää, te synnintekijät, ja noudattakaa vanhurskautta hänen edessänsä. Kenties hän mielistyy teihin ja tekee laupeuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Jumalaani minä ylistän taivaan Kuningasta, se riemuitsee hänen valtasuuruudestaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Näin sanokoot kaikki ja kiittäkööt kaikki Jerusalemissa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, '»Jerusalem, sinä pyhä kaupunki, hän kyllä kurittaa sinua lapsiesi tekojen tähden, mutta hän armahtaa jälleen vanhurskasten lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Kiitä Herraa hyvästi ja ylistä iankaikkisuuksien Kuningasta, että jälleen rakennettaisiin hänen majansa ilolla sinun keskuuteesi ja hän ilahuttaisi vangittuja sinun keskuudessasi ja osoittaisi sinussa rakkautta vaivatuille sukupolvesta sukupolveen iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Monet kansat tulevat kaukaa Herran Jumalan nimen tykö, lahjat käsissänsä, lahjat taivaan Kuninkaalle. Sukukuntien sukukunnat sinua riemuiten kiittävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Kirotut olkoot kaikki, jotka sinua vihaavat; siunatut kaikki jotka sinua rakastavat, iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Iloitse ja riemuitse vanhurskasten lapsista, sillä heidät kootaan yhteen, ja he ylistävät vanhurskasten Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Autuaat ne, jotka sinua rakastavat! He saavat iloita sinun rauhastasi. Autuaat ovat kaikki, joille sinun lyöntisi tuottivat murhetta, sillä he saavat iloita sinusta nähdessään kaiken sinun kirkkautesi. Niin he saavat riemuita iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Kiitä, minun sieluni, Jumalaa, suurta Kuningasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Sillä Jerusalem rakennetaan safiirista ja smaragdista, ja kalliista kivestä sinun muurisi, ja sinun tornisi ja suojavarustuksesi puhtaasta kullasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Ja Jerusalemin kadut lasketaan beryllillä ja rubiinilla ja Suufirin kivellä. Ja kaikki sen kujat lausuvat hallelujaa ja kiitosta, sanoen: Ylistetty olkoon Jumala, joka on korottanut sinut, aina ja iankaikkisesti.»');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Ja Toobit lopetti kiitosvirtensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Toobit oli viidenkymmenen kahdeksan vuoden vanha, kun hän menetti näkönsä, ja kahdeksan vuoden perästä hän sai sen takaisin. Hän antoi almuja ja pelkäsi edelleenkin Herraa Jumalaa ja kiitti häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Hän eli hyvin vanhaksi. Ja hän kutsui tykönsä poikansa ja tämän pojat, ja hän sanoi hänelle: »Poikani, katso, minä olen nyt vanha ja valmis eromaan tästä elämästä: ota poikasi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'ja mene Meediaan, poikani. Sillä minä olen varma siitä, että niinive kukistuu, niinkuin profeetta Joonas on sanonut. Mutta Meediassa on jonkun aikaa oleva rauhallisempaa. Ja minä olen varma siitä, että kotimaassa olevat veljemme hajotetaan pois hyvästä maasta, ja Jerusalem tulee autioksi, ja Jumalan huone, joka siellä on, poltetaan poroksi ja jää joksikin aikaa autioksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Sitten Jumala jälleen armahtaa heitä ja vie heidät takaisin heidän omaan maahansa, ja he rakentavat temppelin - ei kuitenkaan edellisen vertaista - ja se pysyy, kunnes maailmanajat ovat täyttyneet. Senjälkeen he palaavat pakkosiirtolaisuutensa paikoista ja rakentavat Jerusalemin ihanaksi. Ja Jumalan huone, joka siellä on, rakennetaan ylen loistavaksi, niinkuin profeetat ovat siitä kaupungista puhuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Ja kaikki pakanat kääntyvät totuudessa pelkäämään Herraa Jumalaa, ja he kaivavat maahan epäjumalainsa kuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Ja kaikki pakanat ylistävät Herraa. Ja hänen oma kansansa kiittää Jumalaa, ja Herra korottaa kansansa. Ja niin saavat iloita kaikki, jotka totuudessa ja vanhurskaudessa rakastavat Herraa Jumalaa, osoittaen laupeutta veljillemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Ja nyt, lapseni, lähde pois Niinivestä, sillä on käyvä, juuri niinkuin profeetta Joonas on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Mutta sinä pidä laki ja käskyt ja ole armelias ja oikeamielinen, että menestyisit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Hautaa minut kunniallisesti, ja äitisi minun viereeni, mutta älkää sitten enää jääkö Niiniveen. Ajattela, poikani, mitä Naadab teki kasvatusisälleen Akiakarille, kuinka hän syöksi hänet valosta pimeyteen ja kuinka hän hänet palkitsi. Akiakar pelastui, mutta tuota toista kohtasi kosto, ja hänen täytyi astua alas pimeyteen. Akiakar antoi almuja, ja hän pelastui kuoleman paulasta, minkä Naadab oli hänelle virittänyt; mutta tämä lankesi siihen itse ja joutui tuhon omaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Katsokaa nyt siis, lapseni, mitä armeliaisuus vaikuttaa ja miten vanhurskaus pelastaa.» Näin sanoen hän vaipui kuolemaan vuoteellensa. Hän oli silloin sadan viidenkymmenen kahdeksan vuoden vanha. Ja Tobias hautasi hänet suurella kunnialla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Ja kun Hanna kuoli, hautasi hän hänet isän viereen. Sitten Tobias lähti vaimonsa ja poikiensa kanssa Ekbatanaan, appensa Raguelin tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Ja hän eli hyvin vanhaksi, kunnioitusta nauttien. Ja hän hautaasi appivanhempansa suurella kunnialla, ja hän peri heidän omaisuutensa, niin myös isänsä Toobitin omaisuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Hän kuoli Meedian Ekbatanassa sadan kahdenkymmenen seitsemän vuoden vanhana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Ja ennen kuin hän kuoli, sai hän kuulla Niiniven kukistuneen; sen valloittivat Nebukadnessar ja Averus, Niin hän ennen kuolemaansa sai iloita Niiniven häviöstä. Aamen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Kuningas Nebukadnessarin kahdentenatoista vuotena, hänen, joka hallitsi assurilaisia Niinivessä, siinäsuuressa kaupungissa, ja siihen aikaan, kuin Arpaksad hallitsi meedialaisia Ekbatanassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'rakensi jälkimmäinen Ekbatanan ympärille muurit hakatuista kivistä, joiden leveys oli kolme kyynä rääjapituus kuusi kyynärää. Ja hän teki muurin seitsemääkymmentä kyynärää korkeaksi ja viittäkymmentä kyynärää leveäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Muurin tornit hän sijoitti kaupungin porteille ja teki ne sadan kyynärän korkuisiksi sekä juuresta kuudenkymmenen kyynärän levyisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Ja kaupungin portit hän antoi valmistaa seitsemänkymmenen kyynärän korkuisiksi ja neljänkymmenen kyynärän levyisiksi, että hänen sankariensa joukot voisivat kulkea niistä ulos, samoin myös hänen jalkaväkensä järjestetyissä riveissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Siihen aikaan kuningas Nebukadnessar ryhtyi sotaan kuningas Arpaksadia vastaan Suurella tasangolla, se on Ragaun alueella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Ja häneen liityivät kaikki ne, jotka asuivat vuoristossa ja kaikki, jotka asuivat Eufratin ja Tigriin ja Hydespeen varsilla sekä ne, jotka asuivat Arjokin, elymaiolaisten kuninkaan, tasangolla. Niin kokoontui monia kansoja taistelemaan keleudilaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Niin Nebukadnessar, assyrialaisten kuningas, lähetti sanan kaikille Persiassa asuville ja kaikille niille, jotka asuivat lännessä, Kilikiassa ja Damaskossa, Libanonilla ja Antilibanonilla, ja kaikille, jotka asuivat meren rannikolla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'ja Karmelin ja Gileadin kansojen keskuudessa asuville ja niille, jotka asuivat Ylä-Galileassa ja suurella Esdrelonin tasangolla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'ja kaikille, jotka asuivat Samariassa ja sen kaupungeissa, ja Jordanin tuolla puolen aina Jerusalemiin, Beetaneen, Kelokseen, Kaadekseen ja Egyptin virtaan saakka, sekä niille, jotka asuivat Tafnessa, Ramessessa ja koko Gesemin maassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'aina yläpuolelle Tanista ja Memfistä, samoinkuin kaikille niille, jotka asuivat Egyptissä Etiopian rajoille saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Mutta kaikkien näiden maiden asukkaat halveksivat Nebukadnessarin, assurilaisten kuninkaan, sanaa eivätkä lähteneet hänen kanssansa sotaan, koska he eivät peljänneet häntä, vaan pitivät häntä vertaisenansa; ja he antoivat hänen lähettiläidensä palata luotaan häpeällisesti tyhjin toimin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Silloin Nebukadnessar vihastui ankarasti kaikkiin näihin maihin ja vannoi valtaistuimensa ja kuninkaanvaltansa kautta kostavansa kaikille Kilikian, Damaskon ja Syyrian maanäärille ja surmaavansa miekalla myöskin kaikki Mooabin asukkaat ja ammonialaiset ynnä koko Idumean ja kaikki ne, jotka asuivat Egyptissä aina kahden meren alueelle saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Seitsämäntenätoista hallitusvuotenansa hän sitten hyökkäsi sotavoimineen kuningas Arpaksadia vastaan, voitti hänet taistelussa ja ajoi pakoon Arpaksadin koko sotavoiman ja kaiken hänen ratsuväkensä ja kaikki hänen sotavaununsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Sitten hän valloitti hänen kaupunkinsa ja tunkeutui Ekbatanaan saakka, valtasi sen tornit, ryösti kadut ja muutti siten sen kauneuden häpeäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'Arpaksadin itsensä hän otti vangiksi Ragaun vuoristossa, lävisti hänet heittokeihäillään ja teki sinä päivänä perinpohjaisesti hänestä lopun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Sitten hän palasi takaisin Niiniveen, mukanaan kaikki, jotka olivat häneen liittyneet, suunnaton joukko sotaväkeä. Ja hän ja hänen sotajoukkonsa viipyivät siellä sata kaksikymmentä päivää viettäen huoletonta elämää ja kemuja pitäen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Kahdeksantenatoista vuotena, ensimmäisen kuukauden kahdentenakymmenentenä toisena päivänä alettiin Nebukadnessarin, assurilaisten kuninkaan, palatsissa huhuilla, että hän nyt aikoi kostaa kaikille noille maille, niinkuin oli sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Ja hän kutsui kokoon kaikki palvelijansa ja kaikki ruhtinaansa ja ilmoitti heille salaisen aikomuksensa ja lujan päätöksensä tuhota maat perinjuurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Ja nämä olivat sitä mieltä, että kaikki ne, jotka eivät olleet noudattaneet hänen käskyjänsä, oli tuhottava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Lopetettuaan neuvottelunsa Nebukadnessar, assurilaisten kuningas, kutsui Holoferneen, sotajoukkonsa ylimmän päälikön, joka oli toinen mies hänestä, ja sanoi hänelle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'sanoo suurkuningas, koko maan herra: Katso, sinun on lähdettävä minun tyköni ja otettava mukaasi miehiä, jotka luottavat voimaansa, jalkasotureita noin sata kaksikymmentä tuhatta ja hevosia ratsastajineen kahdentoista tuhannen suuruinen joukko,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'ja sinun on lähdettävä kaikkia läntisiä maita vastaan, koska ne eivät ole totelleet minun käskyjäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Ilmoita heille, että heidän on pidettävä valmiina maata ja vettä, sillä minä lähden vihassani heitä vastaan ja peitän koko maan pinnan sotajoukkoni jaloilla ja annan heidät sen saaliiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Heidän haavoitettunsa täyttävät heidän rotkonsa ja tulvapuronsa, ja virta täyttyy äyräitä myöten heidän kuolleistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Ja heidän vangittunsa minä vien kaiken maan ääriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Lähde siis nyt ja valtaa minulle edeltäpäin koko heidän alueensa; ja jos he antautuvat sinulle, niin pidä heitä vartioituina minua varten heidän rangaistuksensa päivään saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Mutta tottelemattomia älä sääli, vaan jätä ne surman ja ryöstön omiksi kaikissa valtaamissasi maissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Sillä niin totta kuin minä elän ja minun kuninkaanvaltani on luja: minä olen puhunut, ja minä teen sen kädelläni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Ja sinä älä jätä noudattamatta ainoatakaan herrasi sanaa, vaan täytä ne tarkoin, niinkuin minä olen sinua käskenyt, äläkä viivyttele niiden toimeenpanemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Niin Holofernes lähti herransa kasvojen edestä ja kutsui tykönsä kaikki ruhtinaat ja sotapääliköt ja Assurin sotavoiman johtajat');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'ja luetutti sotaan valitut miehet, niinkuin hänen herransa oli käskenyt hänen tehdä, jalkaväkeä sata kaksikymmentä tuhatta miestä ja kaksitoista tuhatta ratsastavaa jousella-ampujaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'ja järjesti ne, niinkuin sotajoukko järjestetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Vielä hän otti kameleja, aaseja ja muuleja kuormastoa varten suunnattoman joukon ja lukemattoman määrän lampaita ja nautoja ja vuohia heidän elatukseksensa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'samoin paljon viljaa jokaista miestä varten, sekä ylen runsaasti kultaa ja hopeaa kuninkaan palatsista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Sitten hän lähti liikkeelle kaikkine sotavoiminensa mennäkseen kuningas Nebukadnessarin edellä ja peittääkseen koko lännenpuoleisen maan vaunuilla ja ratsumiehillä ja valitulla jalkaväellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Ja heidän mukanansa lähti sekalaista väkeä, paljon niinkuin heinäsirkkoja ja niinkuin hiekkaa maassa; sitä ei voitu lukea sen paljouden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Kun he olivat kulkeneet Niinivestä kolmen päivän matkan ja saapuneet Bekteletin tasangolle, niin he pystyttivät leirin, joka ulottui Bekteletistä aina lähelle sitä vuorta, joka on Ylä-Kilikian pohjoispuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Ja hän otti kaiken sotavoimansa, jalkaväkensä, ratsumiehensä ja sotavaununsa, ja lähti sieltä vuoristoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Ja hän hävitti Fuudin ja Luudin ja ryösti kaikki rassilaiset ja ismaelilaiset, jotka asuivat erämaan laidassa, kaldealaisten maasta etelään päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Ja hän meni Eufratin yli ja kulki halki Mesopotamian ja jaotti maahan kaikki linnoitetut kaupungit Abronaan tulvapuron varrelta, aina mereen saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Ja hän valloitti Kilikian maanääret ja hakkasi maahan kaikki, jotka ryhtyivät häntä vastustamaan, ja tuli aina Jaafetin maanääriin saakka etelään päin, Arabian suuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Ja hän saartoi kaikki midianilaiset, poltti heidän telttansa ja ryösti heidän karjatarhansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Sitten hän meni alas Damaskon lakeudelle nisunleikkuun aikaan, poltti kaikki heidän peltonsa, tuhosi lammas- ja karjalaumat, ryösti heidän kaupunkinsa, hävitti heidän ketonsa ja surmasi kaikki heidän nuorukaisensa miekan terällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Silloin peljästyivät ja vapisivat häntä kaikki meren rannalla asuvaiset, jotka olivat Siidonissa ja Tyyrossa, sekä Suurin ja Okeinan asukkaat ja kaikki Jemnaanissa asuvaiset; myöskin Asdodin ja Askalonin asukkaat pelkäsivät häntä suuresti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Niin he lähettivät hänen tykönsä lähettiläitä tarjoamaan rauhaa näillä sanoilla:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Katso, me, Nebukadnessarin, suurkuninkaan, palvelijat, makaamme sinun edessäsi: tee meille, niinkuin hyväksi näet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Katso, meidän talomme ja kaikki meidän nisuvainiomme, lammas- ja karjalaumamme ja kaikki karjatarhat meidän telttakylissämme ovat sinun käytettävinäsi: tee meille mielesi mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Katso, sekä meidän kaupunkimme että niiden asukkaat ovat sinun orjiasi: tule ja kohtele heitä, niinkuin on hyvä sinun silmissäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Kun miehet saapuivat Holoferneen luokse, ilmoittivat he hänelle asian näiden sanojen mukaisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Silloin hän lähti sotavoiminensa alas rannikolle ja miehitti linnoitetut kaupungit ja otti niistä valittua miehistöä apujoukoiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Ja he ja koko heidän paikkakuntansa ottivat hänet vastaan seppeleillä, karkeloilla ja vaskirummuilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'Mutta hän hävitti koko heidän alueensa ja hakkautti maahan heidän pyhät lehtonsa. Ja hänen tehtäväksensä oli annettu tuhota maan kaikki jumalat, että kaikki kansat palvelisivat ainoastaan Nebukadnessaria ja kaikki kielet ja kaikki sukukunnat rukoilisivat häntä jumalanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Sitten hän meni Esdrelonia vastaan, Dootean läheisyyteen, joka on vastapäätä Juudean suurta vuoriharjannetta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'ja leiriytyi Gebain ja Skyytopolin välille. Siellä hän viipyi kuukauden päivät kootaksensa kaiken sotajoukolleen kuuluvan kuormaston.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Kun israelilaiset, jotka asuivat Juudeassa, saivat kuulla, mitä kaikkea Holofernes, assurilaisten kuninkaan Nebukadnessarin ylin sotapäälikkö, oli tehnyt muille kansoille ja kuinka hän oli ryöstänyt kaikki heidän pyhäkkönsä ja hävittänyt ne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'niin he peljästyivät häntä hirmuisesti ja joutuivat suureen hätään Jerusalemin ja Herran, heidän Jumalansa, temppelin tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Sillä he olivat juuri palanneet takaisin pakkosiirtolaisuudesta, ja vasta äsken oli koko Juudean kansa kokoontunut, ja pyhät astiat ja alttari ja Jumalan huone oli puhdistettu saastutuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Niin he lähettivät sanan koko Samarian alueelle, Koonaan, Beethooroniin, Beelmainiin, Jerikoon, Koobaan, Haasoriin ja Saalemin laaksoon');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'ja miehittivät edeltäkäsin kaikki korkeiden vuorten huiput, varustivat muureilla siellä olevat kylät ja keräsivät niihin ruokatarpeita sodan varalta; sillä heidän pelloiltaan oli sato juuri korjattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Mutta Joojakim, joka siihen aikaan oli ylimmäisenä pappina Jerusalemissa, kirjoitti Beetyluan asukkaille ja samoin Beetomestaimin, joka on vastapäätä Esdrelinia, Dootaimin läheisyydessä olevan tasangon laidassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'ja käski miehittämään vuoriston tiet, koska niiden kautta voitiin päästä Juudeaan, ja koska oli helppo estää pääsy sinne, kun sola oli niin ahdas, että siinä oli tilaa enintään kahdelle miehelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Ja israelilaiset tekivät, niinkuin ylimmäinen pappi Joojakim ja kaiken Israelin kansan vanhinten neuvosto käskivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Silloin jokainen Israelin mies huusi Jumalan puoleen suurella hartaudella, ja he nöyryyttivät sielunsa suurella hartaudella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'he ja heidän vaimonsa ja lapsensa ja juhtansa; vieläpä jokainen muukalainenkin, joka asui heidän keskuudessansa, ja jokainen heidän palkkalaisensa ja rahalla ostamansa orja pani säkkipuvun lanteillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Ja jokainen Israelin mies ja nainen sekä lapset, kaikki jotka Jerusalemissa asuivat, lankesivat kasvoillensa maahan temppelin eteen, sirottivat tuhkaa päänsä päälle ja levittivät säkkipukunsa Herran kasvojen edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'Alttarinkin he verhosivat säkkikankaalla ja huusivat avuksi Israelin Jumalaa yksimielisesti ja hartaasti, ettei hän antaisi heidän lastensa joutua ryöstetyiksi eikä heidän vaimojensa vihollisen saaliiksi eikä kaupunkien, heidän perintöosansa, hävitettäviksi eikä temppelin saastutettavaksi ja häväistäväksi, pilkkanauruksi pakanoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Ja Herra kuuli heidän äänensä ja katsoi heidän ahdistustansa. Ja kansa paastosi useita päiviä koko Juudeassa ja Jerusalemissa Herran, Kaikkivaltiaan, pyhäkön edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Ja ylimmäinen pappi Joojakim ja kaikki, jotka seisoivat Herran edessä, papit ja Herran palvelijat, uhrasivat säkkipuku kiedottuna lanteittensa ympärille, jokapäiväisen polttouhrin ja kansan lupausuhreja ja vapaaehtoisia lahjoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Ja heidän päähineittensä päällä oli tuhkaa; ja he huusivat avuksi Herraa kaikesta voimastansa, että hän armollisesti katsoisi koko Israelin huoneen puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Kun Holoferneelle, Assurin sotavoimain ylimmälle päälikölle, ilmoitettiin, että israelilaiset varustautuivat sotaan ja että he olivat sulkeneet vuoriston halki kulkevat tiet ja linnoittaneet kaikki korkeiden vuorten huiput ja asettaneet tasangoille esteitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'niin hän vihastui silmittömästi ja kutsui luoksensa kaikki Mooabin ruhtinaat ja Ammonin sotapääliköt sekä kaikki rannikkoseudun satraapit');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'ja sanoi heille: Ilmoittakaa minulle, te Kanaanin pojat, minkälainen on se kansa, joka asuu vuoristossa, ja minkälaiset ovat ne kaupungit, joissa he asuvat, ja kuinka suuri on heidän sotajoukkonsa ja mihin perustuu heidän voimansa ja väkevyytensä, ja kuka on pantu heidän kuninkaaksensa johtamaan heidän sotajoukkoaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'ja minkätähden he, päinvastoin kuin kaikki muut lännen maissa asuvat, ovat pitäneet minua liian halpana tullaksensa minua kohtaamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Silloin Akior, kaikkien Ammonin lasten päällikkö, vastasi hänelle: Kuulkoon minun herrani sanaa, jonka palvelijasi puhuu, niin minä tahdon ilmoittaa sinulle totuuden siitä kansasta, joka asuu tässä vuoristossa sinun läheisyydessäsi; eikä ole valhetta pääsevä sinun palvelijasi suusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Tämä kansa on kaldealaisten jälkeläisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'He asuivat ennen muukalaisina Mesopotamiassa. Koska he nimittäin eivät tahtoneet seurata Kaldean maassa asuvien isiensä jumalia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'niin he luopuivat isiensä tiestä ja rupesivat palvelemaan taivaan Jumalaa, jonka olivat oppineet tuntemaan. Mutta silloin heidän isänsä karkoittivat heidät pois jumaliensa kasvojen edestä, ja he pakenivat Mesopotamiaan ja asuivat siellä pitkän aikaa muukalaisina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Mutta heidän Jumalansa käski heitä lähtemään pois tästä heidän muukalaisuutensa maasta ja vaeltamaan Kanaanin maahan. Niin he asettuivat asumaan sinne ja saivat itsellensä ylen paljon kultaa ja hopeaa sekä runsaasti karjaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Sitten he menivät alas Egyptiin, kun nälänhätä oli levinnyt koko Kanaanin maahan, ja asuivat siellä muukalaisina niin kauan kuin elatusta heille riitti; ja he lisääntyivät siellä suureksi joukoksi, niin ettei heidän heimonsa paljoudella ollut määrää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Mutta Egyptin kuningas asettui heitä vastaan: heitä kohdeltiin vilpillisesti ja rasitettiin kovalla työllä ja tiilenteolla ja heidät tehtiin orjiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Niin he huusivat avuksi Jumalaansa, ja hän löi Egyptin maata vaivoilla, joihin ei mitään parannuskeinoa ollut. Silloin egyptiläiset ajoivat heidät pois tyköänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Ja Jumala kuivasi Punaisen meren heidän edessänsä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'ja kuljetti heidät Siinaille ja Kaades-Barneaan. Ja he karkoittivat pois kaikki, jotka asuivat erämaassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'ja asettuivat asumaan amorilaisten maahan ja tuhosivat sotavoimillaan kaikki hesbonilaiset. Sitten he menivät Jordanin ylitse ja ottivat haltuunsa koko vuoriston.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Ja he karkoittivat tieltänsä kanaanilaiset, perissiläiset, jebusilaiset, sikemiläiset ja kaikki girgasilaiset ja asettuivat asumaan sinne pitkäksi ajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Ja niin kauan kuin he olivat tekemättä syntiä Jumalaansa vastaan, kävi heidän hyvin; sillä heidän kanssansa on Jumala, joka vihaa vääryyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Mutta kun he kääntyivät pois siltä tieltä, jonka hän oli heille määrännyt, saivat he tuhonsa monissa pitkällisissä sodissa, ja heidät vietiin pakkosiirtolaisina maahan, joka ei ollut heidän omansa, ja heidän Jumalansa temppeli hävitettiin perustuksia myöten, ja viholliset valtasivat heidän kaupunkinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Mutta nyt, kun he ovat jälleen kääntyneet Jumalansa puoleen, ovat he palanneet takaisin hajaannuksesta, jonne heidät oli hajoitettu, ja ovat ottaneet haltuunsa Jerusalemin, jossa heidän pyhäkkönsä on, ja ovat asettuneet asumaan vuoristoon, koska se oli autio.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Ja nyt, valtias ja herra, jos tätä kansaa painaa joku rikos ja he tekevät syntiä Jumalaansa vastaan, niin me saamme nähdä, että se tuottaa heille turmion, ja silloin tahdomme käydä sotimaan heitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Mutta jos heidän kansassaan ei ole mitään laittomuutta, niin jättäköön herrani heidät rauhaan, sillä muutoin saattaa heidän Herransa ja Jumalansa tulla kilvellään suojaamaan heitä, ja me joudumme koko maailman pilkaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Kun Akior oli lopettanut tämän puheen, rupesi kaikki kansa, joka seisoi piirissä teltan ympärillä, nurisemaan; ja Holoferneen pääliköt ja kaikki rannikon ja Mooabin asukkaat huusivat, että hänet oli hakattava kappaleiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'Sillä, sanoivat he, me emme aio pelätä israelilaisia. Sehän on sellainen kansa, jolta puuttuu voimaa ja lujuutta ankaraan taisteluun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Menkäämme siis heitä vastaan, ja he ovat vain suupala koko sinun sotajoukollesi, mahtava Holofernes.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Kun neuvottelukokousta ympäröivien miesten melu oli tauonnut, sanoi Holofernes, Assurin sotavoimain ylipäälikkö, kaiken muukalaiskansan kuullen Akiorille ja kaikille mooabilaisille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Kuka sinä oikein olet, Akior, efraimilaisine palkkalaisinesi, kun ennustat meidän kaskuudessamme sellaista kuin tänään ja kiellät sotimasta Israelin kansaa vastaan, koska heidän Jumalansa muka suojaa heitä kilvellään? Ja kuka muu on Jumala kuin Nebukadnessar? Hän on lähettävä sotavoimansa ja hävittävä heidät maan päältä, eikä heidän Jumalansa voi heitä pelastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Vaan me, hänen palvelijansa, lyömme heidät niinkuin yhden ainoan miehen, eivätkä he kestä meidän hevostemme voimaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Sillä me, hävitämme heidät tulella, ja heidän vuorensa juopuvat heidän verestään, ja heidän ketonsa täyttyvät heidän kuolleistansa; he eivät voi meitä vastustaa, vaan tuhoutuvat täydellisesti, sanoo kuningas Nebukadnessar, koko maan herra. Sillä hän on sen sanonut, eivätkä hänen sanansa jää täyttymättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Mutta sinä, Akior, sinä Ammonin palkkalainen, joka olet puhunut nämä sanat vääryytesi päivänä, et ole enää näkevä minun kasvojani tästä päivästä alkaen siihen saakka, kunnes olen kostanut tuolle Egyptistä tulleelle kansalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Ja silloin minun sotilaiteni miekka ja palvelijoitteni keihäs on lävistävä sinun rintasi, ja sinä kaadut heidän lyötyjensä joukkoon, kun minä palaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Minun palvelijani vievät sinut vuoristoon ja jättävät sinut johonkin kaupunkiin vuoristotien varrelle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'ja sinä saat olla hengissä siihen asti, kunnes sinut surmataan yhdessä heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Mutta jos sinulla on sydämessäsi se toivo, ettei kaupunkeja valloiteta, niin älköön muotosi olko murheellinen. Olen puhunut, eikä yksikään minun sanoistani mene harhaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Silloin Holofernes käski palvelijoitaan, jotka olivat hänen teltassansa valmiina palvelukseen, ottamaan kiinni Akiorin ja viemään hänet Beetyluaan ja jättämään hänet israelilaisten käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Niin palvelijat ottivat hänet kiinni ja veivät hänet leirin ulkopuolelle kedolle; ja he menivät tasangolta vuoristoon ja tulivat niiden lähteiden luo, jotka olivat Beetyluan alapuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Mutta kun miehet kaupungista, vuoren huipulta, näkivät heidät, tarttuivat he aseisiinsa ja lähtivät ulos kaupungista vuoren huipulta. Ja kaikki linkomiehet miehittivät ylhäälle vievän tien ja heittivät kiviä heidän päällensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Silloin nämä vetäytyivät suojaan vuoren alapuolelle, sitoivat Akiorin, jättivät hänet virumaan vuoren juurelle ja lähtivät herransa luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Mutta israelilaiset menivät kaupungistaan sinne alas, astuivat hänen luoksensa ja irroittivat hänen siteensä. Sitten he veivät hänet Beetyluaan ja asettivat hänet kaupunkinsa johtajien eteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'joina siihen aikaan olivat Osias, Miikan poika, Simeonin sukukunnasta, ja Kabris, Gotomelin poika, ja Karmis, Melkielin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Nämä kutsuivat kokoon kaikki kaupungin vanhimmat; myöskin kaikki heidän nuorukaisensa ja vaimot riensivät kansankokoukseen. He panivat Akiorin kaiken väen keskelle, ja Osias kysyi häneltä mitä oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Niin hän vastasi ja ilmoitti heille, mitä Holoferneen neuvottelukokouksessa oli tapahtunut, ja kaiken, mitä hän oli puhunut assurilaisten päämiesten keskuudessa, ja kuinka pöyhkeitä puheita Holofernes oli puhunut Israelin huonetta vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Silloin kansa lankesi maahan kasvoillensa Jumalan eteen ja huusi sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Herra, taivaan Jumala, katso heidän röyhkeyttänsä ja armahda meidän nöyryytettyä sukuamme, ja katsahda niiden puoleen, jotka tänä päivänä ovat sinulle pyhitetyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Sitten he lohduttivat Akioria ja kiittivät häntä suuresti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Ja Osias otti hänet seurakunnan kokouksesta kotiinsa ja valmisti pidot vanhimmille. Ja he huusivat avuksensa Israelin Jumalaa koko sen yön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Seuraavana päivänä Holofernes käski koko sotajoukkonsa ja kaiken väen, joka oli tullut hänen tykönsä auttamaan häntä taistelussa, lähteä liikkeelle Beetyluaa vastaan ja miehittää ylös vuoristoon kulkevat tiet ja ryhtyä sotaan israelilaisia vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'Sinä päivänä lähtivät liikkeelle kaikki heidän sotakuntoiset miehensä; ja heidän sotavoimansa olivat vahvuudeltaan sata seitsemänkymmentä tuhatta jalka - ja kaksitoista tuhatta ratsumiestä, lukuunottamatta kuormastoa. Ja miesten luku, jotka seurasivat sitä jalan, oli ylen suuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Ja he pystyttivät leirinsä laaksoon lähelle Beetyluaa lähteen tykö, niin että se leveydeltään ulottui Dootaimin ohitse Beelbaimiin ja pituudeltaan Beetyluasta Kyamoniin, joka on vastapäätä Esdrelonia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'Mutta kun israelilaiset näkivät, kuinka paljon heitä oli, kauhistuivat he suuresti ja sanoivat toinen toisellensa: Nyt nämä kalvavat puhtaaksi koko maan pinnan, eivätkä korkeat vuoret, eivät laaksot eikä kukkulat voi kestää niiden painoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Ja he tarttuivat kukin sota-aseisiinsa ja sytyttivät tulet torneihinsa ja pysyivät vartiopaikoillaan koko sen yön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Mutta toisena päivänä Holofernes vei koko ratsuväkensä ulos Beetyluassa olevien israelilaisten nähden');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'ja tutki heidän kaupunkiinsa johtavat tiet ja etsi vesilähteet ja miehitti ne ja asetti sotilasvartiostot niitä vartioimaan, mutta itse hän palasi takaisin väkensä tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Silloin tulivat hänen luoksensa kaikki Eesaun lasten päämiehet ja kaikki Mooabin kansan johtajat ja rannikkoseudun sotapääliköt ja sanoivat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Kuulkoon herramme, mitä me sanomme, ettei sotajoukollesi tapahtuisi mitään vahinkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Sillä tämä israelilaisten kansa ei turvaa keihäisiinsä, vaan niiden vuorten korkeuteen, joilla he asuvat. Sillä ei ole helppo tunkeutua heidän vuortensa huipuille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Älä siis, herra, sodi heitä vastaan sillä tapaa, kuin taistelujärjestyksessä soditaan; silloin ei ainoakaan mies sinun väestäsi ole kaatuva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'Pysy leirissäsi ja pidä sotajoukkosi jokainen mies suojassa. Miehittäkööt sinun palvelijasi vain sen vesilähteen, joka pulppuaa vuoren juurelta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'sillä siitä noutavat vetensä kaikki Beetyluan asukkaat. Niin he menehtyvät janoon ja jättävät kaupunkinsa. Ja me menemme väkinemme ylös läheisille vuorten huipuille ja leiriydymme niille vartioidaksemme, ettei yksikään mies pääse ulos kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Silloin he ja heidän vaimonsa ja lapsensa nääntyvät nälkään, ja ennenkuin ainoakaan miekanisku on heihin sattunut, he makaavat kuolleina oman kaupunkinsa kaduilla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'niin sinä kostat heille ankarasti sen, että ovat nousseet sinua vastustamaan eivätkä ole rauhallisesti tulleet sinua kohtaamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Heidän sanansa mielyttivät Holofernesta ja kaikkia hänen palvelijoitansa; ja hän käski tehdä, niinkuin he olivat puhuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Niin ammonilaisten leiri lähti liikkeelle ja heidän mukanansa viisituhatta assurilaista, ja he leiriytyivät laaksoon ja miehittivät israelilaisten vesipaikat ja lähteet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Ja Eesaun lapset ja ammonilaiset nousivat vuoristoon ja leiriytyivät siellä vastapäätä Dootaimia ja lähettivät osastoja etelään ja itään päin Egrebelin vaiheille, joka on Kuusin läheisyydessä Mokmurin tulvapuron varrella. Mutta muu assurilaisten sotajoukko leiriytyi tasagolle ja peitti koko maan. Telttoineen ja kuormastoineen he muodostivat väkirikkaan leirin, ja heidän lukumääränsä oli ylen suuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Mutta israelilaiset huusivat avuksensa Herraa, Jumalaansa; sillä he olivat menettäneet rohkeutensa, koska kaikki heidän vihollisensa olivat piirittäneet heidät, niin ettei ollut mahdollista päästä pakoon niiden keskeltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Näin pysyi Assurin koko sotajoukko, heidän jalkaväkensä, sotavaununsa ja ratsumiehensä, leiriytyneenä heidän ympärillänsä kolmekymmentä neljä päivää, ja kaikilta Beetyluan asukkailta loppuivat kaikki heidän vesivarastonsa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'ja vesisäiliöt tyhjenivät, eivätkä he saaneet yhtenäkään päivänä juoda kyllikseen, koska heille annettiin vettä ainoastaan määrämitalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Niin heidän lapsensa ja vaimonsa menettivät rohkeutensa, ja heidän nuoret miehensä menehtyivät janosta ja kaatuivat kaupungin kaduille ja porttikäytäviin, eikä heissä enää ollut mitään voimaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Silloin kokoontui kaikki kansa Osiaan ja kaupungin muiden johtajien tykö, nuoret miehet, vaimot ja lapset, ja he huusivat suurella äänellä ja sanoivat vanhinten kuullen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Jumala tuomitkoon teidän ja meidän välillämme, koska te olette tehneet meille suuren vääryyden, kun ette ole ryhtyneet rauhanneuvotteluihin assurilaisten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Ja nyt ei ole ketään, joka voisi meitä auttaa, vaan Jumala on myynyt meidät heidän käsiinsä, niin että me näännymme heidän nähtensä janoon ja suureen kurjuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Kutsukaa siis heidät tänne ja luovuttakaa koko kaupunki Holoferneen väen ja kaiken hänen sotajoukkonsa ryöstettäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Sillä meille on parempi joutua heidän saaliiksensa. Meistä tosin tulee orjia, mutta me saamme kuitenkin jäädä henkiin, eikä meidän tarvitse omin silmin nähdä pienokaistemme kuolevan eikä naistemme ja lastemme menehtyvän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Me vannotamme teitä taivaan ja maan ja Jumalamme ja isiemme Herran kautta, hänen, joka kostaa meidän syntimme ja meidän isiemme syntien mukaan, ettei hän tekisi näiden sanojen mukaan, jotka tänä päivänä ovat puhutut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Ja koko seurakunta puhkesi yhtenä miehenä suureen itkuun ja huusi avuksi Herraa Jumalaa suurella äänellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Niin Osias sanoi heille: Olkaa rohkealla mielellä, veljet. Kestäkäämme vielä viisi päivää; niiden kuluessa on Herra, Meidän Jumalamme, kääntävä armonsa meidän puoleemme, sillä ei hän jätä meitä kokonansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Mutta jos näiden päiväin kuluttua apua ei ole meille tullut, niin minä teen teidän sanojenne mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Sitten hän päästi kansan hajaantumaan, kunkin omalle vartiopaikalleen. Niin he menivät kaupungin muureille ja torneihin, mutta naiset ja lapset hän lähetti heidät koteihinsa. Ja kaupungissa vallitsi suuri ahdistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Niinä päivinä sai Juudit, Merarin, Ooksin pojan, tytär, kuulla tämän. Ooks oli Joosefin poika, tämä taas Osielin, tämä Helkiaan, tämä Eliaan, tämä Kelkiaan, tämä Eliabin, tämä Natanaelin, tämä Salamielin, tämä Sarsadin, tämä Israelin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Ja hänen miehensä Manasse, joka oli hänen omaa sukukuntaansa ja sukuansa, oli kuollut ohranleikkuun aikaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Kun hän nimittäin kerran oli pellolla valvomassa lyhteiden sitojain työtä, kohtasi kuumuus hänen päätänsä, ja hän joutui vuoteeseen ja kuoli kaupungissansa Beetyluassa. Ja hänet haudattiin isiensä tykö Dootaimin ja Baalamonin väliselle pellolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Ja Juudit oli elänyt talossansa leskenä kolme vuotta ja neljä kuukautta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'ja oli rakentanut itsellensä majan talonsa katolle; ja hän oli pannut säkkipuvun lanteillensa, ja hänen yllänsä olivat hänen leskeysvaatteensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Ja hän paastosi leskeytensä aikana joka päivä, paitsi sapattien edellisenä päivänä ja sapatteina ja uusienkuiden edellisenä päivänä ja uusinakuina ja juhlina ja Israelin huoneen ilopäivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Ja hän oli kaunis vartaloltaan ja ylen ihana näöltään. Ja hänen miehensä Manasse oli jättänyt hänelle kultaa ja hopeaa ja palvelijoita ja palvelijattaria ja karjaa ja peltoja; ja ne olivat yhä hänen hallussansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Eikä ollut ainoatakaan, joka olisi sanonut hänestä pahaa sanaa, sillä hän oli hyvin jumalinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Kun Juudit sai kuulla, kuinka katkeria sanoja kansa oli puhunut kaupungin johtajan edessä, koska se oli menettänyt rohkeutensa vedenpuutteen tähden, ja kun hän myös sai kuulla, mitä kaikkea Osias oli kansalle vastannut, kuinka hän oli vannonut heille jättävänsä kaupungin viiden päivän perästä assurilaisille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'niin hän lähetti palvelusneitsyensä, jonka hoidossa koko hänen omaisuutensa oli, kutsumaan luokseen kaupunkinsa vanhimmat, Osiaan, Kabriksen ja Karmiksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Ja kun nämä tulivat hänen tykönsä, sanoi hän heille: Kuulkaa minua, te Beetyluan asukkaiden johtajat. Sillä ei ole oikea se puhe, jonka te tänään olette puhuneet kansan edessä, kun olette Jumalan edessä vannoneet ja vakuuttaneet jättävänne kaupungin meidän vihollisillemme, ellei Herra noiden määrättyjen päivien kuluessa lähetä teille apua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Ja nyt, keitä olette te, kun te tänä päivänä olette kiusanneet Jumalaa ja asettuneet Jumalan sijalle ihmisten lasten keskellä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Te koettelette nyt Herraa, Kaikkivaltiasta, mutta ette saa mitään tietää, ette milloinkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Kun te ette pääse tunkeutumaan ihmisen sydämen syvyyksiin ettekä käsitä hänen ajatuksiansa ja mieltänsä, niin kuinka te voitte tutkia Jumalan, joka nämä kaikki on tehnyt, ja kuinka voitte tietää hänen mielensä ja käsittää hänen ajatuksensa? Älkää, veljet, koskaan vihoittako Herraa, meidän Jumalaamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Sillä jos hän ei tahdo meitä auttaa noiden viiden päivän kuluessa, niin on hänellä valta suojella meitä, minä päivänä tahtoo, taikka myös tuhota meidät vihollistemme silmäin edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Mutta te, älkää pakottako Herraa, meidän Jumaalamme, tekemään päätöksiänsä, sillä Jumala ei ole niinkuin ihminen, että häntä voitaisiin uhata, eikä niinkuin ihmislapsi, että hänet saataisiin muuttamaan päätöksensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Odottakaamme siis häneltä pelastusta ja rukoilkaamme häntä avuksemme, ja hän kuulee meidän äänemme, jos se on hänelle otollista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Sillä ei ole miesmuistiin ollut, eikä ole tänä päivänä, meidän keskuudessamme sukukuntaa, ei sukua, ei kylää, ei kaupunkia, joka palvelisi käsintehtyjä jumalia, niinkuin on ollut entisinä aikoina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Siitä syystä meidän isämme annettiikin alttiiksi miekalle ja ryöstölle, ja he kärsivät suuren tappion vihollistemme edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'Mutta me emme tunne muuta Jumalaa kuin hänet; sentähden me toivomme, ettei hän ole meitä halveksiva, eikä ketään, joka kansaamme kuuluu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Sillä jos meidän kaupunkimme vallataan, niin koko Juudea kukistuu ja meidän pyhäkkömme ryöstetään, ja Herra vaatii meidän veremme sen hävittämisestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Ja sen, että veljemme surmataan ja maan asukkaat viedään vankeuteen ja perintöosammme tehdään autioksi, hän antaa tulla meidän päämme päälle, missä ikinä pakanakansojen keskuudessa olemmekin orjina, ja me joudumme isäntäimme loukkauksen ja pilkan alaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Sillä meidän orjuutemme ei käänny hyväksi, vaan Herra, meidän Jumalamme, antaa sen tulla häpeäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Ja nyt, veljet, osoittakaamme veljillemme, että heidän henkensä riippuu meistä, ja että pyhäkkö ja temppeli ja alttari on meidän varassamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Paitsi tätä kaikkea, kiittäkäämme Herraa, Jumalaamme, joka koettelee meitä, samoin kuin meidän isiämmekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Muistakaa, mitä hän teki Aabrahamille, ja kuinka hän koetteli Iisakia, ja mitä Jaakobille tapahtui Syyrian Mesopotamiassa, kun hän paimensi enonsa Laabanin lampaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Sillä niinkuin hän koetteli heitä ainoastaan tutkiakseen heidän sydämiänsä, niin hän ei myöskään ole rangaissut meitä; Herra ainoastaan varoitukseksi kurittaa niitä, jotka häntä lähestyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Niin Osias vastasi hänelle: Kaikki, mitä olet sanonut, sinä olet puhunut ymmärtäväisellä sydämellä. Eikä ole ketään, joka voi sanojasi vastustaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Sillä sinun viisautesi ei ole tullut julki vasta tänään, vaan niin kauan kuin olet elänyt, on kaikki kansa tuntenut sinun ymmärryksesi, kuinka viisasta on kaikki, mitä sydämesi ajattelee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Mutta kansa on kovin kärsinyt janosta, ja niin he ovat pakottaneet meidät tekemään, mitä olemme heille sanoneet, ja ottamaan päällemme valan, jota emme voi rikkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Rukoile siis nyt meidän puolestamme, koska sinä olet hurskas vaimo, niin Herra lähettää sateen täyttämään meidän vesisäiliömme, eikä meidän enää tarvitse nääntyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Silloin Juudit sanoi heille: Kuulkaa minua. Minä teen teon, josta kerrotaan sukupolvesta sukupolveen kansamme lasten keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Asettukaa te tänä yönä kaupungin portille: minä kuljen siitä ulos palvelusneitsyeni kanssa, ja niiden päivien kuluessa, joiden jälkeen te lupasitte jättää kaupungin vihollisillemme, on Herra pelastava Israelin minun käteni kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Mutta älkää tiedustelko, mitä aion tehdä, sillä en sano sitä teille, ennenkuin työni on suoritettu loppuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Niin Osias ja johtajat sanoivat hänelle: Mene rauhassa, Herra Jumala käyköön sinun edelläsi kostamaan vihollisillemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Sitten he palasivat takaisin majasta ja menivät asemilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Mutta Juudit lankesi kasvoilleen maahan, sirotti tuhkaa päänsä päälle ja riisui yltään säkkipuvun, johon hän oli pukeutuneena. Juuri silloin uhrattiin Jerusalemissa Jumalan huoneessa sen illan suitsutusuhri. Ja Juudit huusi suurella äänellä avuksi Herraa ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Herra, minun isäni Simeonin Jumala, hänen, jonka käteen sinä annoit miekan, että hän kostaisi muukalaisille, jotka riisuivat neitsyen sylin tehdäkseen hänelle väkivaltaa ja paljastivat hänen lanteensa häväistykselle ja häpeällisesti saastuttivat hänen kohtunsa! Sinähän olit sanonut: \'Ei näin saa tehdä\'. Mutta he tekivät kuitenkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Sentähden sinä annoit heidän päämiehensä surman omiksi ja vuoteen, joka häpesi heidän petollista irstailuaan, sinä annoit tahraantua vereen; sinä löit palvelijat yhdessä valtiaiden kanssa, löit valtiaat valtaistuimiltaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Ja sinä annoit heidän vaimonsa ryöstösaaliiksi ja heidän tyttärensä vankeuteen; kaiken saaliin jaettavaksi poikiesi kesken, joita sinä rakastat. Sillä he kiivailivat suuresti sinun puolestasi ja kauhistuivat oman verensä saastutusta ja huusivat sinua avuksensa. Jumala, minun Jumalani, kuule minua, leskivaimoa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Sillä sinä olet tehnyt, mitä ennen niitä oli, ne ja niiden jälkeiset asiat; nykyiset ja tulevaiset sinä olet aivoitellut. Ja minkä sinä aivoittelit, se tapahtui,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'ja mitkä sinä olit päättänyt, ne astuivat esiin ja sanoivat: \'Katso, tässä me olemme\'. Sillä kaikki sinun tiesi ovat valmiit, ja sinun tuomiosi on sinulle edeltä tunnettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Sillä, katso assurilaiset ovat kokoontuneet lukuisin sotajoukoin; he kerskaavat hevosista ja ratsumiehistä, ylpeilevät jalkaväen voimasta, he panevat toivonsa kilpiin ja keihäisiin, jousiin ja linkoihin, eivätkä tiedä, että sinä olet Herra, joka hävität sodat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, '\'Herra\' on sinun nimesi. Lyö maahan voimalla heidän väkensä ja murskaa vihallasi heidän väkevyytensä. Sillä he ovat päättäneet häväistä sinun pyhäkkösi ja saastuttaa sen majan, jossa sinun kunniasi nimi asuu, ja lyödä miekalla poikki sinun alttarisi sarven.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Katso heidän röyhkeyttänsä, lähetä vihasi heidän päätänsä kohti, anna minun, leskivaimon, käteen voima siihen, mitä olet aivoitellut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Lyö minun huulteni vilpin kautta palvelija yhdessä herransa kanssa ja herra yhdessä palvelijansa kanssa; murskaa heidän ylpeytensä naisen kädellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Sillä sinun voimasi ei riipu paljoudesta eikä sinun valtasi väkevistä miehistä, vaan sinä olet nöyrien Jumala ja alhaisten auttaja, heikkojen holhooja, hyljättyjen suojelija ja epätoivoisten pelastaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Niin, sinä, minun isäni Jumala ja Israelin perintöosan Jumala, taivaan ja maan valtias, vetten luoja ja kaiken luomakunnan kuningas, kuule minun rukoukseni');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'ja anna minun sanani ja viekkauteni tulla haavoiksi ja mustelmiksi niille, joilla on pahoja aikeita sinun liittoasi, sinun pyhää huonettasi ja Siionin kukkulaa ja sinun lastesi asuinsijaa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Ja anna kaiken kansasi ja jokaisen sukukunnan tuntea ja tietää, että sinä olet Jumala, jonka on kaikki valta ja voima, ja ettei ole toista, joka suojelee Israelin heimoa, paitsi sinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Kun hän oli lakannut huutamasta avuksi Israelin Jumalaa ja lopettanut kaikki nämä sanat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Nousi hän ylös maasta, kutsui luokseen palvelusneitsyensä ja astui alas siihen huoneeseen, jossa hänen oli tapana oleskella sapatteina ja juhlapäivinänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Ja hän pani pois säkkipuvun, johon hän oli ollut pukeutuneena, ja riisui yltään leskeysvaatteensa. Vielä hän pesi ruumiinsa vedellä ja voiteli sen kalliilla voiteella, järjesti päänsä hiukset ja pani siihen pääkoristeen ja pukeutui juhlavaatteisiinsa, joita hän miehensä Manassen eläessä oli kantanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Ja pani paula-anturat jalkaansa ja otti jalkakäädyt, rannerenkaat, sormukset, korvarenkaat ja kaikki muut koristuksensa. Näin hän koristautui ylen ihanaksi hurmatakseen kaikkien miesten silmät, jotka hänet näkivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Ja palvelusneitsyelleen hän antoi leilin viiniä ja ruukun öljyä, täytti laukun ohra - ja viikunakakuilla ja puhtailla leivillä ja kääri sitten kaikki astiansa huolellisesti vaatteeseen ja sälytti ne hänen kannettaviksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Sitten he lähtivät Beetyluan portille ja tapasivat Osiaan sekä kaupungin vanhimmat, Kabriksen ja Karmiksen, seisomassa siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Mutta kun he näkivät hänet - hänen kasvonsa olivat nimittäin muuttuneet ja hänen yllään oli toinen puku - niin he ihmettelivät suuresti hänen kauneuttansa ja sanoivat hänelle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'Isiemme Jumala antakoon sinulle armonsa, niin että voisit toteuttaa aikomuksesi Israelin lasten ylpeydeksi ja Jerusalemin korotukseksi. Ja hän rukoili Jumalaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'ja sanoi heille: Käskekää aukaisemaan minulle kaupungin portti, niin minä lähden ulos täyttämään sitä, mistä minun kanssani olette puhuneet. Ja he antoivat nuorille miehille käskyn aukaista hänelle, niinkuin hän oli sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Nämä tekivät niin. Sitten Juudit lähti, palvelijatar mukanansa. Mutta kaupungin miehet seurasivat katseillaan häntä siihen asti, kunnes hän oli tullut vuoren juurelle ja kulkenut halki laakson, jolloin he eivät enää häntä nähneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Niin he kulkivat suoraan laakson poikki, kunnes hänet kohtasi assurilaisten etuvartio.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Silloin nämä pidättivät hänet ja kysyivät: Kenen väkeä olet? Ja mistä tulet? Ja minnekä olet matkalla? Hän vastasi: Minä olen hebrealaisten tyttäriä, mutta olen karannut pois heidän tyköänsä, koska heidät annetaan teidän saaliiksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Ja minä aion mennä Holoferneen, teidän sotajoukkonne ylipäälikön, tykö ilmoittamaan hänelle totuuden: minä osoitan hänelle tien, jota hänen on kuljettava saadakseen haltuunsa koko vuoriston, menettämättä ainoatakaan sielua miehistöstään taikka yhtäkään, jossa elävä henki on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Kun miehet kuulivat hänen sanansa ja kun he tarkastelivat hänen kasvojansa, havaiten hänet ihmeteltävän kauniiksi, niin he sanoivat hänelle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Sinä olet pelastanut henkesi tulemalla kiiruusti meidän herramme luo. Mene siis nyt hänen telttaansa, me annamme sinulle saattajia, jotka jättävät sinut hänen käsiinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Ja kun tulet hänen eteensä, niin älä pelkää sydämessäsi, vaan ilmoita hänelle se, minkä sanoit, ja hän on osoittava sinulle hyvyyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Niin he valitsivat keskuudestaan sata miestä saattamaan häntä ja hänen palvelusneitsyttään, ja nämä veivät hänet Holoferneen teltalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Ja väki alkoi juosta kokoon leirissä, sillä tieto hänen saapumisestaan oli levinnyt telttoihin. Ja he tulivat ja asettuivat hänen ympärilleen, kun hän siinä seisoi Holoferneen teltan ulkopuolella, kunnes tälle oli ilmoitettu hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Ja he ihmettelivät hänen kauneuttansa ja ihmettelivät israelilaisia hänen tähtensä. Ja he sanoivat toinen toisellensa: Kuka voi halveksia tätä kansaa, jolla on keskuudessaan tämänkaltaisia naisia? Ei ole viisasta jättää heistä eloon ainoatakaan, sillä jos heidät päästetään vapaiksi, niin he voivat viekkaudella lumota koko maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Sitten tulivat Holoferneen henkivartijat ja kaikki hänen palvelijansa ulos ja veivät Juuditin sisälle telttaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Ja Holofernes oli lepäämässä vuoteellaan kärpäsverhon alla, joka oli valmistettu purppuraharsosta, mihin oli kudottu kultaa, smaragdeja ja jalokiviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Kun hänelle oli ilmoitettu Juuditin tulosta, meni hän teltan esihuoneeseen, ja hänen edellään kannettiin hopealamppuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Mutta kun Juudit tuli hänen ja hänen palvelijainsa eteen, ihmettelivät kaikki hänen kasvojensa kauneutta. Ja Juudit osoitti hänelle kunnioitusta langeten kasvoilleen maahan, mutta palvelijat nostivat hänet ylös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Sitten Holofernes sanoi hänelle: Ole rohkealla mielellä, nainen, älä pelkää sydämessäsi, sillä minä en koskaan tee pahaa yhdellekään, joka on halukas palvelemaan Nebukadnessaria, kaiken maan kuningasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'Ja mitä tulee kansaasi, joka asuu vuoristossa, niin en olisi nostanut keihästäni heitä vastaan, elleivät he olisi minua halveksineet. He ovat itse tehneet tämän itsellensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Sano siis nyt minulle, minkätähden olet karannut heidän tyköänsä ja tullut meidän luoksemme. Sillä omaksi pelastukseksesi olet tänne saapunut. Ole rohkealla mielellä. Sinä saat säilyttää henkesi tänä yönä ja vastedes.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Sillä ei kukaan tee sinulle pahaa, vaan sinua kohdellaan hyvin, niinkuin kaikkia minun herrani, kuningas Nebukadnessarin, palvelijoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Niin Juudit vastasi hänelle: Ota armollisesti vastaan palvelijattaresi sanat, ja saakoon sinun orjattaresi puhua sinun edessäsi. Valhepuhetta en tänä yönä lausu herralleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Ja jos sinä seuraat orjataresi sanoja, niin Jumala on vievä sinun asiasi päätökseen, eivätkä minun herrani aikomukset raukea tyhjiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Sillä niin totta kuin Nebukadnessar, kaiken maan kuningas, elää, ja niin totta kuin hänen valtansa kestää, hänen, joka on lähettänyt sinut saattamaan jokaisen elävän olennon oikealle kohdalleen: eivät ainoastaan ihmiset palvele häntä sinun tähtesi, vaan myöskin metsän eläimet ja karja ja taivaan linnut elävät sinun voimasi vaikutuksesta Nebukadnesarin ja koko hänen huonekuntansa hyväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Sillä me olemme kuulleet sinun viisaudestasi ja neuvokkuudestasi, ja koko maailma tietää, että sinä yksin koko valtakunnassa olet kunnollinen, olet terävä ymmärrykseltäsi ja ihmeteltävä sotatoimissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Ja mitä tulee siihen puheeseen, jonka Akior piti sinun neuvottelukokouksessasi, niin me olemme saaneet kuulla hänen sanansa, sillä Beetyluan miehet jättivät hänet henkiin, ja hän on kertonut heille kaiken, mitä hän sinun edessäsi on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Sentähden, valtias ja herra, älä halveksi hänen sanaansa, vaan paina se sydämeesi, sillä se on tosi. Meidän kansaamme ei näet voida rangaista, miekka ei voi heille mitään, elleivät he tee syntiä Jumalaansa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Mutta ettei herrani nyt joutuisi lähtemään pois tyhjin toimin, on kuolema karkaava heidän kimppuunsa. Sillä heidät on saanut valtoihinsa synti, jolla he vihoittavat Jumalansa, niin pian kuin tekevät sellaista, mitä ei sovi tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Sillä kun heiltä on loppunut ruoka ja kaikki vesi on vähissä, ovat he aikoneet käydä käsiksi eläimiin, ja ovat päättäneet käyttää ravinnoksi kaikkea sellaistakin, mitä Jumala laissaan on heitä kieltänyt syömästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Myöskin viljan uutiset sekä viini - ja öljykymmenykset, jotka on pyhitetty ja pantu talteen papeille, jotka Jerusalemissa seisovat meidän Jumalamme kasvojen edessä, he ovat päättäneet käyttää ravinnoksi, vaikka ei yhdenkään kansasta ole lupa edes käsillään niihin koskea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Ja he ovat lähettäneet lähettiläitä Jerusalemiin, jonka asukkaat myöskin ovat kerran tehneet samoin, hankkiakseen suuren neuvoston myöntymyksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Sinä päivänä, jona se heille ilmoitetaan ja he tekevät sen mukaan, annetaan heidät sinun tuhottaviksesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'Siitä syystä olen minä, sinun palvelijattaresi, kun sain tämän kaiken tietää, karannut heidän luotansa. Sillä Jumala on lähettänyt minut tekemään sinun kanssasi tekoja, joita koko maailma, kuka ikinä ne kuulee, kauhistuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Sillä sinun palvelijattaresi on jumalaapelkääväinen ja palvelee yötä päivää taivaan Jumalaa. Ja nyt minä, herrani, jään sinun luoksesi, mutta joka yö sinun palvelijattaresi menee laaksoon rukoilemaan Jumalaa, ja hän on minulle sanova, milloin he ovat syntiset tekonsa tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Ja sitten minä tulen ja ilmoitan sen sinulle, ja niin sinä lähdet liikkeelle kaikkine sotavoiminesi, eikä yksikään heistä voi sinua vastustaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Ja minä vien sinut halki Juudean aina Jerusalemin edustalle saakka ja asetan sinun istuimesi sen keskelle. Ja sinä ajat heidät pois niinkuin lampaat, joilla ei ole paimenta, eikä koirakaan murahda sinua vastaan. Sillä tämä on minulle edeltäpäin sanottu ja ilmoitettu, ja minut on lähetetty ilmoittamaan se sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Hänen sanansa mielyttivät Holofernesta ja kaikkia tämän palvelijoita, ja he ihmettelivät hänen viisauttansa ja sanoivat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Ei maan äärestä hamaan toiseen ääreen ole tälläista naista, niin kaunista muodoltaan ja niin viisasta sanoissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Ja Holofernes sanoi hänelle: Jumala on tehnyt hyvin lähettäessään sinut kansasi edellä, että meidän osaksemme tulisi voitto, mutta niille, jotka halveksivat minun herraani, tuho.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Ja nyt, ihana sinä olet näöltäsi ja viisas puheissasi. Jos sinä teet, niinkuin olet sanonut, on sinun Jumalasi oleva minun Jumalani, ja sinä saat asua kuningas Nebukadnesarin palatsissa, ja sinun nimeäsi mainitaan kautta kaiken maan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Sitten hän käski viedä Juuditin siihen huoneeseen, johon hänen hopeakalustonsa oli asetettu, ja määräsi, että Juuditille oli levitettävä matto ja annettava hänen syödä hänen ruokiansa ja juoda hänen viiniänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Mutta Juudit sanoi: En minä syö niitä, ettei tapahtuisi pahennusta, vaan tarjotkaa minulle sitä, mitä olen tuonut mukanani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Silloin Holofernes sanoi hänelle: Mutta jos se, mitä sinulla on mukanasi, loppuu, mistä voimme hankkia samankaltaista sinulle annettavaksi? Sillä meidän parissamme ei ole ketään sinun kansastasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Niin Juudit vastasi hänelle: Niin totta kuin sinä elät, herrani, sinun palvelijasi ei ole ehtinyt kuluttaa loppuun mukanansa olevia ruokavaroja, ennenkuin Herra minun käteni kautta on tehnyt, mitä hän on päättänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Sitten Holoferneen palvelijat veivät hänet telttaan, ja hän nukkui puoliyöhön saakka. Mutta aamuvartion lähetessä hän nousi vuoteesta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'ja lähetti sanomaan Holoferneelle: Antakoon herrani määräyksen, että sinun palvelijattaresi sallitaan lähteä ulos rukoilemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Niin Holofernes antoi henkivartijoillensa sen määräyksen, ettei heidän tullut estää Juuditia. Ja tämä viipyi leirissä kolme päivää; mutta joka yö hän meni Beetyluan laaksoon ja kylpi leirissä, vesilähteellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Ja kun hän oli noussut ylös kylvystään, rukoili hän Herraa, Israelin Jumalaa, tasoittamaan hänen tiensä hänen kansansa lasten koroitukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Sitten hän meni puhtaana telttaansa ja viipyi siellä siihen asti, kunnes illan suussa nautti ruokansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Neljäntenä päivänä Holofernes valmisti pidot yksinomaan palvelijoillensa eikä kutsunut ketään sotapäälikköään niihin osaa ottamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Ja hän sanoi kamaripalvelijalleen Bagoaalle, jonka hoidossa kaikki hänen omaisuutensa oli: Mene ja houkuttele tuo hebrealainen nainen, joka on tykönäsi, tulemaan meidän luoksemme ja syömään ja juomaan meidän kanssamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Sillä meille olisi häpeäksi, jos antaisimme tuollaisen naisen mennä pois luotamme seurustelematta hänen kanssansa. Sillä ellemme pidä yhteyttä hänen kanssansa, niin hän tekee meistä pilkkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Niin Bagoas lähti Holoferneen edestä ja meni Juuditin tykö ja sanoi: Älköön tämä kaunis neito viivytelkö tulemasta herrani luokse saadaksensa hänen edessään kunnioitusta ja juodaksensa meidän kanssamme viiniä mielensä iloksi ja ollaksensa tänä päivänä niinkuin joku assurilaisten tyttäristä, jotka ovat Nebukadnessarin palatsissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Juudit vastasi hänelle: Kuka olen minä sanomaan herraani vastaan? Kaiken, mikä on otollista hänen silmissänsä, minä teen nopeasti; ja se on oleva minun iloni aina kuolinpäivääni saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Sitten hän nousi ylös ja kaunisti itsensä vaatteilla ja kaikilla naisten koristuksilla. Ja hänen palvelijattarensa meni edeltäpäin ja levitti hänelle Holoferneen eteen maahan ne matot, jotka hän oli saanut Bagoaalta jokapäiväistä ruokailuaan varten, voidakseen syödessään olla niiden päällä nojallaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Niin Juudit tuli sisään ja asettui paikallensa. Silloin Holoferneen sydän hurmaantui häneen, hänen sielunsa joutui voimakkaaseen liikkeeseen, ja hänessä syntyi suuri halu saada olla yhdessä Juuditin kanssa. Jo siitä päivästä alkaen, jona hän hänet ensiksi näki, Holofernes oli odottanut sopivaa tilaisuutta vietelläkseen Juuditin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Ja Holofernes sanoi hänelle: Juo ja iloitse meidän kanssamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Juudit vastasi: Kyllä juon, herra, sillä tänään on minulle osoitettu suurempaa kunniaa kuin milloinkaan koko elämässäni, syntymästäni saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Ja hän otti, söi ja joi hänen edessään siitä, mitä hänen palvelijattarensa oli valmistanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Ja Holofernes iloitsi hänestä ja joi viiniä ylen paljon, enemmän kuin hän milloinkaan, syntymästään saakka, oli juonut yhtenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Mutta kun ilta oli tullut, lähtivät hänen palvelijansa kiiruusti pois. Ja Bagoas lukitsi teltan ulkoapäin ja esti palvelusta toimittavat pääsemästä herransa tykö. Nämä menivät silloin vuoteisiinsa, sillä olivat kaikki väsyneitä, koska pidot olivat kestäneet kauan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Juudit yksin jätettiin telttaan Holoferneen kanssa, joka oli kaatunut suin päin vuoteellensa, sillä viini oli hänet kovin uuvuttanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Ja Juudit oli käskenyt palvelijatartansa asettumaan hänen makuuhuoneensa ulkopuolelle ja odottamaan, kunnes hän lähtisi ulos, niinkuin oli tehnyt joka päivä. Hän oli nimittäin sanonut menevänsä toimittamaan rukoustansa. Samoin hän myös oli sanonut Bagoaalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Kun nyt kaikki olivat lähteneet pois Holoferneen tyköä eikä ketään ollut jäänyt hänen makuuhuoneeseensa, ei pientä eikä suurta, astui Juudit hänen vuoteensa ääreen ja sanoi sydämessään: Herra, kaiken voiman Jumala, katso tällä hetkellä armossasi sitä tekoa, jonka minun käteni on tekevä Jerusalemin korotukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Sillä nyt on aika sinun armahtaa perintöosaasi ja toteuttaa minun sydämeni aie meitä vastaan nousseiden vihollisten tuhoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Sitten hän meni vuodepylvään luo, joka oli Holoferneen pään puolella, ja irroitti siitä hänen miekkansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'ja lähestyen vuodetta tarttui hänen päänsä hiuksiin ja sanoi: Vahvista minua tänä päivänä, oi Israelin Jumala!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Sitten hän iski voimansa takaa kaksi kertaa hänen kaulaansa ja hakkasi hänen päänsä irti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Ja hän vieritti hänen ruumiinsa pois vuoteelta ja irroitti kärpäsverkon patsaista. Heti sen jälkeen hän meni ulos ja jätti Holoferneen pään palvelusneitsyelleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'joka pisti sen ruokalaukkuunsa. Sitten he lähtivät molemmat yhdessä tapansa mukaan toimittamaan rukoustansa. Ja kun he olivat kulkeneet leirin lävitse. kiersivät he laakson, suuntasivat sitten kulkunsa ylös Beetyluan vuorelle ja saapuivat niin kaupungin portille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Ja Juudit huusi kaukaa niille, jotka vartioivat porttia: Aukaiskaa, aukaiskaa portti! Jumala, meidän Jumalamme, on meidän kanssamme, ja hän tekee vielä voimallisia tekoja Israelissa ja osoittaa väkevyytensä meidän vihollisiamme vastaan, niinkuin hän tänäkin päivänä on tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Ja kun kaupungin miehet kuulivat hänen äänensä, riensivät he nopeasti alas kaupunkinsa portille ja kutsuivat kokoon kaupungin vanhimmat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Ja kaikki nuorimmasta vanhimpaan saakka kokoontuivat nopeasti sinne, sillä he eivät olleet uskoneet hänen tulevan. Ja he aukaisivat portin ja ottivat heidät vastaan. Sitten he sytyttivät tulen valaisemaan ja ympäröivät heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Mutta Juudit sanoi heille suurella äänellä: Ylistäkää, ylistäkää Jumalaa! Ylistäkää Jumalaa, joka ei ole kääntänyt laupeuttansa pois Israelin huoneesta, vaan on murskannut meidän vihollisemme minun käteni kautta tänä yönä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'Ja hän otti pään laukusta, näytti sitä ja sanoi heille: Tässä on Holoferneen, Assurin sotajoukon ylipäälikön. pää. ja tässä on kärpäsverkko, jonka alla hän makasi juovuspäissään. Herra löi hänet naisen kädellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'Niin totta kuin Herra elää, hän, joka on ollut minun varjelukseni sillä tiellä, jota olen kulkenut: minun kasvoni ovat vietelleet Holoferneen hänen tuhoksensa, mutta syntiä hän ei tehnyt minun kanssani, niin että olisi minut saastuttanut ja häväissyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Ja kaikki kansa hämmästyi suuresti, ja he kumartuivat ja rukoilivat Jumalaa ja lausuivat yhdestä suusta: Ylistetty ole sinä, meidän Jumalamme, joka tänä päivänä olet tuhonnut meidän vihollisemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Ja Osias sanoi Juuditille: Jumalan, Korkeimman, siunaus sinulle, tyttäreni, suurempi kuin kenellekään naiselle maan päällä! Ja ylistetty olkoon Herra, Jumala, taivaan ja maan luoja, joka on ohjannut sinut murskaamaan vihollistemme päämiehen pään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Sillä se toivo, mikä sinulla oli, ei milloinkaan unhotu niiden ihmisten sydämestä, jotka muistavat Jumalan voiman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Antakoon Jumala tämän tulla sinulle iankaikkiseksi kunniaksi, ja siunatkoon hän sinua hyvillä lahjoillansa palkaksi siitä, ettet sinä säästänyt henkeäsi tahtoessasi auttaa sorrettua kansaamme, vaan pelastit meidät lankeemuksestamme, kulkien suoraa tietä meidän Jumalamme edessä. Ja kaikki kansa sanoi: Tapahtukoon niin! Tapahtukoon niin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Silloin Juudit sanoi heille: Kuulkaa minua, veljet. Ottakaa tämä pää ja ripustakaa se muurinne harjalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Ja niin pian kuin aamu sarastaa ja aurinko nousee yli maan, ottakaa kukin sota-aseenne ja menkää, kaikki sotakelpoiset miehet, ulos kaupungista. Ja valitkaa itsellenne johtaja, ikäänkuin aikoisitte hyökätä alas tasangolle assurilaisten etuvartijoita vastaan; älkää kuitenkaan hyökätkö sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Silloin nämä ottavat kaikki sotavarustuksensa ja menevät leiriinsä ja herättävät Assurin sotajoukon pääliköt ja rientävät yhdessä Holoferneen teltalle, mutta eivät löydä häntä. Ja heidät valtaa pelko, niin että he pakenevat teidän kasvojenne edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Ja ajakaa te ja kaikki, jotka koko Israelin alueella asuvat, heitä takaa ja hakatkaa heidät maahan heidän teillänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Mutta ennenkuin tämän teette, kutsukaa ammonilainen Akior minun luokseni, että hän näkisi ja tuntisi sen, joka on halveksinut Israelin huonetta ja joka lähetti hänet meidän tykömme ikäänkuin kuolemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Niin he kutsuivat Akiorin Osiaan talosta. Kun hän tuli ja näki Holoferneen pään erään kansanjoukossa seisovan miehen kädessä, lankesi hän kasvoilleen ja meni tajuttomaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Mutta kun he olivat nostaneet hänet ylös, lankesi hän Juuditin jalkain eteen ja osoitti hänelle kunnioitusta ja sanoi: Ylistetty ole sinä kaikissa Juudan majoissa ja kaikkien kansojen keskuudessa. Kaikki, jotka kuulevat sinun nimesi, kauhistuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Kerro siis nyt minulle kaikki, mitä olet tehnyt näinä päivinä. Silloin Juudit kertoi hänelle kansan keskellä kaiken, mitä hän oli tehnyt, aina siitä päivästä alkaen, jolloin hän lähti, siihen saakka, kun hän nyt heille puhui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Kun hän oli lopettanut puheensa, puhkesi kansa äänekkääseen riemuun ja kohotti ilohuudon kaupungissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Mutta kun Akior oli nähnyt kaiken, mitä Israelin Jumala oli tehnyt, uskoi hän lujasti Jumalaan ja antoi ympärileikata esinahkansa lihan. Niin hänet liitettiin Israelin huonekuntaan, jonka yhteydessä hän on vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Kun sitten aamu sarasti, ripustivat he Holoferneen pään muurille, ja kaikki Israelin miehet tarttuivat aseisiinsa ja lähtivät osastoittain vuorensolia kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Mutta kun assurilaiset näkivät heidät, lähettivät he sanan joka taholle esimiehillensä. Nämä taas menivät sotapäälikköjen ja tuhannenpäämiesten ja kaikkien johtajainsa luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Ja kun he tulivat Holoferneen teltalle, sanoivat he hänen huoneenhaltijallensa: Herätä meidän herramme, sillä nuo orjat ovat rohjenneet hyökätä tänne alas meidän kimppuumme sotimaan, että heidät tuhottaisiin perinpohjin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Niin Bagoas meni sisälle ja kolkutti teltan oviverholle, sillä hän arveli Holoferneen nukkuvan Juuditin kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Mutta kun ei mitään kuulunut, työnsi hän verhon syrjään ja astui sisälle makuuhuoneeseen. Ja hän löysi hänet kuolleena virumassa vuoteen astinlaudalla; ja hänen päänsä oli otettu häneltä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Silloin hän huusi suurella äänellä itkien ja valittaen, huusi rajusti ja repäisi vaatteensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Sitten hän meni siihen telttaan, jossa Juudit asui, mutta kun hän ei löytänyt häntä, tuli hän juosten ulos väen luokse huutaen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Nuo orjat ovat menetelleet petollisesti: yksi ainoa hebrealainen nainen on tuottanut häpeän kuningas Nebukadnesarin huoneelle. Sillä katso, Holofernes makaa maassa, ja pää on häneltä poissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Mutta kun Assurin sotajoukon pääliköt kuulivat nämä sanat, repäisivät he viittansa ja peljästyivät suuresti; ja he alkoivat huutaa ja parkua suurella äänellä keskellä leiriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Kun ne, jotka olivat teltoissa, kuulivat tämän, kauhistuivat he sitä, mikä oli tapahtunut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'ja heidät valtasi pelko ja vavistus. Ei ainoakaan mies pysynyt enää toisensa rinnalla, vaan he hyökkäsivät koko joukko pakoon kaikille tasangon ja vuoriston teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Samoin nekin, jotka olivat leiriytyneet vuoristoon, Beetyluan ympärille, kääntyivät pakoon. Mutta silloin hyökkäsivät kaikki israelilaisten sotakuntoiset miehet heidän kimppuunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Ja Osias lähetti lähettiläitä Beetomastaimiin, Beebaihin, Koobaihin, Koolaan ja kaikkialle Israelin alueelle ilmoittamaan, mitä oli tapahtunut, ja kehoittamaan kaikkia hyökkäämään vihollisten kimppuun, heidän tuhoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Kun israelilaiset sen kuulivat, hyökkäsivät he kaikki yhtenä miehenä vihollisten kimppuun surmaten ja ajaen heitä takaa Koobaan saakka. Samoin saapui miehiä myöskin Jerusalemista ja kaikkialta vuoristosta, sillä heille oli ilmoitettu, mitä heidän vihollistensa leirissä oli tapahtunut. Ja Gileadin sekä Galilean asukkaat ahdistivat vihollisia sivuilta päin tuottaen heille suurta mieshukkaa siihen asti, kunnes nämä olivat kulkeneet Damaskon ja sen alueen ohi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Mutta ne Beetyluan asukkaat, jotka olivat jääneet kotiin, hyökkäsivät Assurin leiriin ja ryöstivät sen ja tulivat ylen rikkaiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Ja ne israelilaiset, jotka palasivat taistelusta, valtasivat tähteet. Samoin anastivat vuoristossa ja tasangolla olevien kylien ja talojen asukkaat paljon saalista, sillä sitä oli ylen runsaasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Niin ylimmäinen pappi Joojakim ja israelilaisten vanhintenneuvoston jäsenet, jotka asuivat Jerusalemissa, tulivat katsomaan niitä hyviä tekoja, jotka Herra oli tehnyt Israelille; he tahtoivat myös nähdä Juuditin ja puhutella häntä ystävällisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Kun he sitten olivat tulleet sisälle hänen tykönsä, ylistivät he kaikki häntä yhdestä suusta ja sanoivat hänelle: Sinä Jerusalemin ylpeys, sinä Israelin suuri kunnia, sinä meidän kansamme suuri kerskaus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'sinä olet tehnyt kaiken tämän kädelläsi, sinä olet tehnyt hyviä tekoja Israelille; mielistyköön Jumala niihin! Ole ylistetty Herran, Kaikkivaltiaan, edessä iankaikkisiin aikoihin! Ja kaikki kansa sanoi: Niin tapahtukoon!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Mutta koko kansa ryösti leiriä kolmekymmentä päivää, ja Juuditille annettiin Holoferneen teltta ja kaikki hänen hopeakalunsa ja vuoteensa ja maljansa ja koko muu kalustonsa. Ja hän otti ne ja sälytti ne muulinsa selkään, ja hän valjastutti vaununsa ja kasasi ne niihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Ja kaikki israelin miehet riensivät näkemään häntä, ja he ylistivät häntä ja esittivät keskenään hänen kunniaksensa karkelon. Niin Juudit otti käsiinsä oksia ja antoi myös niille naisille, jotka olivat hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Sitten he seppelöivät itsensä öljypuun lehvillä, hän ja ne naiset, jotka olivat hänen kanssansa. Ja Juudit kulki kaiken kansan edellä johtaen kaikkia naisia karkelossa. Ja kaikki Israelin miehet seurasivat asestettuina, seppeleet päässä ja kiitoslauluja laulaen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Ja Juudit alotti kiitoslaulun koko Israelin keskellä, ja kaikki kansa yhtyi tähän ylistysvirteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Ja Juudit sanoi: Helistäkää vaskirumpuja minun Jumalani kunniaksi, ylistäkää Herraa kympaaleilla. Virittäkää hänelle uusi virsi, korottakaa ja avuksi huutakaa hänen nimeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Sillä Herra on Jumala, joka lopettaa sodat. Hän pelasti minut leiriinsä kansan keskelle vainoojieni kädestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Assur tuli vuorilta pohjoisesta, tuli sotajoukkojensa kymmentuhansin. Niiden paljous tukkesi tulvapurot ja niiden ratsut peittivät kukkulat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Hän aikoi polttaa minun alueeni surmata minun nuorukaiseni miekalla ja maahan murskata minun imeväiseni, ottaa saaliiksi minun pienet lapseni ja ryöstää minun neitsyeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Herra, Kaikkivaltias, tuhosi heidät naisen kädellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Sillä ei heidän sankarinsa kaatunut nuorukaisten iskusta, eivät lyöneet häntä titaanien pojat, eivätkä kookkaat jättiläiset häneen käsiksi käyneet vaan Juudit, Merarin tytär, lamautti hänet kasvojensa kauneudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Sillä hän riisui yltään leskeytensä puvun korottaaksensa Israelin sorretut, hän voiteli kasvonsa hajuvoiteella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'kiinnitti hiuksensa pääkoristeella ja puki ylleen liinaisen puvun hurmataksensa hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Hänen paula-anturansa kiinnittivät itseensä miehen silmän, ja hänen kauneutensa vangitsi hänen sielunsa. Miekka katkaisi hänen kaulansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Persialaiset kauhistuivat hänen rohkeuttansa, ja hänen uljuutensa täytti meedialaiset pelolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Silloin minun sorrettuni puhkesivat riemuun, ja minun heikkoni suuresti iloitsivat. Mutta nuo toiset joutuivat pelon valtaan: he korottivat äänensä ja pakenivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Nuorten äitien pojat pistivät heidät kuoliaaksi, ja niinkuin karanneita orjia he heitä surmasivat. Minun Herrani sotajoukko tuhosi heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Minä veisaan Jumalalleni uuden virren: Herra, sinä olet suuri ja kunnioitettava, ihmeellinen väkevyydessä, voittamaton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Sinua palvelkoon kaikki sinun luomakuntasi; sillä sinä sanoit, ja se tapahtui, sinä lähetit henkesi, ja se rakensi; ei ole ketään, joka voi sinun ääntäsi vastustaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Sillä vuoret järkkyvät perustuksiltaan yhdessä vetten kanssa, ja kalliot sulavat niinkuin vaha sinun kasvojesi edessä. Mutta niille, jotka sinua pelkäävät, niille sinä olet armollinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Sillä pieni on jokainen uhri suloiseksi tuoksuksi, ja ylen halpa on kaikki rasva sinulle polttouhriksi; mutta joka Herraa pelkää, se on aina suuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Voi pakanoita, jotka nousevat minun kansaani vastaan! Herra, Kaikkivaltias, on rankaiseva heitä tuomion päivänä; hän antaa tulen ja matojen syödä heidän lihansa, niin että he tuskasta vaikeroitsevat iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'Mutta kun he olivat tulleet Jerusalemiin, rukoilivat he Jumalaa; ja sittenkuin kansa oli puhdistanut itsensä, uhrasi se polttouhrinsa ja vapaaehtoiset uhrinsa ja lahjansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Mutta Juudit lahjoitti temppelille kaikki Holoferneen astiat, jotka kansa oli hänelle antanut, ja myös kärpäsverkon, jonka hän oli ottanut itsellensä Holoferneen makuuhuoneesta, hän antoi lahjaksi Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Ja kansa piti juhlaa Jerusalemissa pyhäkön edustalla kolme kuukautta, ja Juudit viipyi heidän luonansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 21, 'Mutta tämän ajan kuluttua itsekukin palasi omaan kotiinsa; ja Juudit lähti Beetyluaan, jonne hän edelleen jäi omaisuuttansa hoitamaan. Ja hän oli kaiken loppuikänsä suuresti kunnioitettu koko maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 22, 'Ja monet halusivat häntä vaimoksensa, mutta siitä päivästä alkaen, jona hänen miehensä Manasse kuoli ja tuli otetuksi isiensä tykö, hän ei koko elinaikanansa yhtynyt ainoaankaan mieheen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 23, 'Hän saavutti hyvin korkean iän, sataviisi vuotta, ja eli vanhuutensa päivät miehensä talossa. Ja hän vapautti palvelusneitsyensä. Hän kuoli Beetyluassa, ja hänet haudattiin miehensä Manassen luolahautaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 24, 'Ja Israelin heimo suri häntä seitsemän päivää. Mutta ennen kuolemaansa hän jakoi omaisuutensa miehensä Manassen kaikille lähimmille sukulaisille ja omille lähimmille sukulaisillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 25, 'Ja niin kauan kuin Juudit eli, ei kukaan enää häirinnyt israelilaisia, eikä pitkään aikaan hänen kuoltuansakaan. Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, '[]');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, '');
