INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Herra, Kaikkivaltias, joka olet taivaissa, meidän isiemme Aabrahamin ja Iisakin ja Jaakobin ja heidän vanhurskaan siemenensä Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Sinä, joka olet tehnyt taivaan ja maan ja kaiken niiden kaunistuksen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'joka olet kahlinnut meren säätämälläsi sanalla, joka olet sulkenut syvyyden ja sinetöinyt sen peljättävällä ja ylistettävällä nimelläsi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'sinä, jonka voiman edessä kaikki värjyy ja vapisee;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'sillä sinun kunniasi valtasuuruutta ei voi kenkään kestää ja sinun vihasi edessä, jolla sinä syntisiä uhkaat, ei kukaan voi pysyväinen olla!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Mittaamaton ja tutkimaton on myös armo, jonka sinä luvannut olet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Sillä sinä, Herra, olet korkein, laupias, pitkämielinen ja suuri armossa, ja sinä kadut kärsimyksiä, jotka ihmisiä kohtaavat, Sinä olet, Herra, suuressa hyvyydessäsi luvannut parannuksen niille, jotka ovat tehneet syntiä sinua vastaan; ja suuressa armahtavaisuudessasi sinä olet säätänyt syntisille parannuksen, että he pelastuisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Niin et sinä, Herra, vanhurskasten Jumala, ole asettanut parannusta vanhurskaille, Aabrahamille ja Iisakille ja Jaakobille, jotka eivät ole syntiä tehneet sinua vastaan, vaan sinä olet asettanut parannuksen minulle, syntiselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Sillä minä olen tehnyt syntiä enemmän kuin on hiekkaa meressä, sillä lukuisat ovat minun laittomat tekoni, enkä minä ole mahdollinen katsomaan ylös ja näkemään taivaan korkeutta väärien tekojeni paljouden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'Minua painavat maahan monet rautakahleet, niin etten minä saa virvoitusta syntieni tähden; eikä ole minulla lepoa, sillä minä olen nostanut sinun vihasi kiivauden ja tehnyt sitä, mikä on pahaa sinun edessäsi, kun olen pystyttänyt kauhistavia epäjumalia ja tehnyt lukuisia iljetyksiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 11, 'Mutta nyt minä notkistan sydämeni polvet ja rukoilen sinun suurta hyvyyttäsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 12, 'Minä olen syntiä tehnyt, Herra, minä olen syntiä tehnyt, ja laittomat tekoni minä tunnen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 13, 'Minä anon ja rukoilen sinua: anna minulle anteeksi, Herra, anna minulle anteeksi; älä hukuta minua yhdessä laittomain tekojeni kanssa, älä vihastu iankaikkisesti, älä pidä tallella minun pahuuttani, äläkä tuomitse minua alas maan syvyyksiin; sillä sinä, Herra, olet katuvaisten Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 14, 'Näytä myös minussa hyvyytesi: pelasta minut, joka en ole mahdollinen, suuren armosi mukaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 15, 'niin minä alati kiitän sinua elämäni päivinä. Sillä sinulle veisaavat ylistystä kaikki taivaitten voimat, ja sinun on kunnia iankaikkisesti. Herran Jeesuksen armo olkoon kaikkien kanssa. Amen.');
