INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Jeesuksen Kristuksen, Daavidin pojan, Aabrahamin pojan, syntykirja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'Aabrahamille syntyi Iisak, Iisakille syntyi Jaakob, Jaakobille syntyi Juuda ja tämän veljet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Juudalle syntyi Faares ja Sera Taamarista, Faareelle syntyi Esrom, Esromille syntyi Aram;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Aramille syntyi Aminadab, Aminadabille syntyi Nahasson, Nahassonille syntyi Salmon;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Salmonille syntyi Booas Raahabista, Booaalle syntyi Oobed Ruutista, Oobedille syntyi Iisai;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Iisaille syntyi Daavid, kuningas. Daavidille syntyi Salomo Uurian vaimosta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Salomolle syntyi Rehabeam, Rehabeamille syntyi Abia, Abialle syntyi Aasa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Aasalle syntyi Joosafat, Joosafatille syntyi Jooram, Jooramille syntyi Ussia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Ussialle syntyi Jootam, Jootamille syntyi Aahas, Aahaalle syntyi Hiskia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Hiskialle syntyi Manasse, Manasselle syntyi Aamon, Aamonille syntyi Joosia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Joosialle syntyi Jekonja ja tämän veljet Babyloniin siirtämisen aikoina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Babyloniin siirtämisen jälkeen Jekonjalle syntyi Sealtiel, Sealtielille syntyi Serubbaabel;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Serubbaabelille syntyi Abiud, Abiudille syntyi Eljakim, Eljakimille syntyi Asor;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Asorille syntyi Saadok, Saadokille syntyi Akim, Akimille syntyi Eliud;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Eliudille syntyi Eleasar, Eleasarille syntyi Mattan, Mattanille syntyi Jaakob;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Jaakobille syntyi Joosef, Marian mies, hänen, josta syntyi Jeesus, jota kutsutaan Kristukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Näin on sukupolvia Aabrahamista Daavidiin kaikkiaan neljätoista polvea, ja Daavidista Babyloniin siirtämiseen neljätoista polvea, ja Babyloniin siirtämisestä Kristukseen asti neljätoista polvea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Jeesuksen Kristuksen syntyminen oli näin. Kun hänen äitinsä Maria oli kihlattu Joosefille, huomattiin hänen ennen heidän yhteenmenoaan olevan raskaana Pyhästä Hengestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Mutta kun Joosef, hänen miehensä, oli hurskas, ja koska hän ei tahtonut saattaa häntä häpeään, aikoi hän salaisesti hyljätä hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Mutta kun hän tätä ajatteli, niin katso, hänelle ilmestyi unessa Herran enkeli, joka sanoi: \"Joosef, Daavidin poika, älä pelkää ottaa tykösi Mariaa, vaimoasi; sillä se, mikä hänessä on siinnyt, on Pyhästä Hengestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Ja hän on synnyttävä pojan, ja sinun on annettava hänelle nimi Jeesus, sillä hän on vapahtava kansansa heidän synneistänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Tämä kaikki on tapahtunut, että kävisi toteen, minkä Herra on puhunut profeetan kautta, joka sanoo:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, '\"Katso, neitsyt tulee raskaaksi ja synnyttää pojan, ja tälle on annettava nimi Immanuel\", mikä käännettynä on: Jumala meidän kanssamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Herättyään unesta Joosef teki, niinkuin Herran enkeli oli käskenyt hänen tehdä, ja otti vaimonsa tykönsä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'eikä yhtynyt häneen, ennenkuin hän oli synnyttänyt pojan. Ja hän antoi hänelle nimen Jeesus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 1, 'Kun Jeesus oli syntynyt Juudean Beetlehemissä kuningas Herodeksen aikana, niin katso, tietäjiä tuli itäisiltä mailta Jerusalemiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 2, 'ja he sanoivat: \"Missä on se äsken syntynyt juutalaisten kuningas? Sillä me näimme hänen tähtensä itäisillä mailla ja olemme tulleet häntä kumartamaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 3, 'Kun kuningas Herodes sen kuuli, hämmästyi hän ja koko Jerusalem hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 4, 'Ja hän kokosi kaikki kansan ylipapit ja kirjanoppineet ja kyseli heiltä, missä Kristus oli syntyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 5, 'He sanoivat hänelle: \"Juudean Beetlehemissä; sillä näin on kirjoitettu profeetan kautta:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 6, '\'Ja sinä Beetlehem, sinä Juudan seutu, et suinkaan ole vähäisin Juudan ruhtinasten joukossa, sillä sinusta on lähtevä hallitsija, joka kaitsee minun kansaani Israelia\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 7, 'Silloin Herodes kutsui salaa tietäjät tykönsä ja tutkiskeli heiltä tarkoin, mihin aikaan tähti oli ilmestynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 8, 'Ja hän lähetti heidät Beetlehemiin sanoen: \"Menkää ja tiedustelkaa tarkasti lasta; ja kun sen löydätte, niin ilmoittakaa minulle, että minäkin tulisin häntä kumartamaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 9, 'Kuultuaan kuninkaan sanat he lähtivät matkalle; ja katso, tähti, jonka he olivat itäisillä mailla nähneet, kulki heidän edellään, kunnes se tuli sen paikan päälle, jossa lapsi oli, ja pysähtyi siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 10, 'Nähdessään tähden he ihastuivat ylen suuresti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 11, 'Niin he menivät huoneeseen ja näkivät lapsen ynnä Marian, hänen äitinsä. Ja he lankesivat maahan ja kumarsivat häntä, avasivat aarteensa ja antoivat hänelle lahjoja: kultaa ja suitsuketta ja mirhaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 12, 'Ja Jumala kielsi heitä unessa Herodeksen tykö palaamasta, ja he menivät toista tietä takaisin omaan maahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 13, 'Mutta kun he olivat menneet, niin katso, Herran enkeli ilmestyi Joosefille unessa ja sanoi: \"Nouse, ota lapsi ja hänen äitinsä ja pakene Egyptiin, ja ole siellä siihen asti, kuin minä sinulle sanon; sillä Herodes on etsivä lasta surmatakseen hänet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 14, 'Niin hän nousi, otti yöllä lapsen ja hänen äitinsä ja lähti Egyptiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 15, 'Ja hän oli siellä Herodeksen kuolemaan asti; että kävisi toteen, minkä Herra on puhunut profeetan kautta, joka sanoo: \"Egyptistä minä kutsuin poikani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 16, 'Silloin Herodes, nähtyään, että tietäjät olivat hänet pettäneet, vihastui kovin ja lähetti tappamaan kaikki poikalapset Beetlehemistä ja koko sen ympäristöstä, kaksivuotiaat ja nuoremmat, sen mukaan kuin hän oli aikaa tietäjiltä tarkoin tiedustellut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 17, 'Silloin kävi toteen, mikä on puhuttu profeetta Jeremiaan kautta, joka sanoo:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 18, '\"Ääni kuuluu Raamasta, itku ja iso parku; Raakel itkee lapsiansa eikä lohdutuksesta huoli, kun heitä ei enää ole\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 19, 'Mutta kun Herodes oli kuollut, niin katso, Herran enkeli ilmestyi unessa Joosefille Egyptissä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 20, 'ja sanoi: \"Nouse, ota lapsi ja hänen äitinsä ja mene Israelin maahan, sillä ne ovat kuolleet, jotka väijyivät lapsen henkeä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 21, 'Niin hän nousi, otti lapsen ja hänen äitinsä ja meni Israelin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 22, 'Mutta kun hän kuuli, että Arkelaus hallitsi Juudeaa isänsä Herodeksen jälkeen, niin hän pelkäsi mennä sinne. Ja hän sai unessa Jumalalta käskyn ja lähti Galilean alueelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 2, 23, 'Ja sinne tultuaan hän asettui asumaan kaupunkiin, jonka nimi on Nasaret; että kävisi toteen, mikä profeettain kautta on puhuttu: \"Hän on kutsuttava Nasaretilaiseksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 1, 'Niinä päivinä tuli Johannes Kastaja ja saarnasi Juudean erämaassa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 2, 'ja sanoi: \"Tehkää parannus, sillä taivasten valtakunta on tullut lähelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 3, 'Sillä hän on se, josta profeetta Esaias puhuu sanoen: \"Huutavan ääni kuuluu erämaassa: \'Valmistakaa Herralle tie, tehkää polut hänelle tasaisiksi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 4, 'Ja Johanneksella oli puku kamelinkarvoista ja vyötäisillään nahkavyö; ja hänen ruokanaan oli heinäsirkat ja metsähunaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 5, 'Silloin vaelsi hänen tykönsä Jerusalem ja koko Juudea ja kaikki Jordanin ympäristö,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 6, 'ja hän kastoi heidät Jordanin virrassa, kun he tunnustivat syntinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 7, 'Mutta nähdessään paljon fariseuksia ja saddukeuksia tulevan kasteelle hän sanoi heille: \"Te kyykäärmeitten sikiöt, kuka on neuvonut teitä pakenemaan tulevaista vihaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 8, 'Tehkää sentähden parannuksen soveliaita hedelmiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 9, 'Älkääkä luulko saattavanne sanoa mielessänne: \'Onhan meillä isänä Aabraham\'; sillä minä sanon teille, että Jumala voi näistä kivistä herättää lapsia Aabrahamille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 10, 'Jo on kirves pantu puitten juurelle; jokainen puu, joka ei tee hyvää hedelmää, siis hakataan pois ja heitetään tuleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 11, 'Minä kastan teidät vedellä parannukseen, mutta se, joka minun jäljessäni tulee, on minua väkevämpi, jonka kenkiäkään minä en ole kelvollinen kantamaan; hän kastaa teidät Pyhällä Hengellä ja tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 12, 'Hänellä on viskimensä kädessään, ja hän puhdistaa puimatanterensa ja kokoaa nisunsa aittaan, mutta ruumenet hän polttaa sammumattomassa tulessa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 13, 'Silloin Jeesus tuli Galileasta Jordanille Johanneksen tykö hänen kastettavakseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 14, 'Mutta tämä esteli häntä sanoen: \"Minun tarvitsee saada sinulta kaste, ja sinä tulet minun tyköni!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 15, 'Jeesus vastasi ja sanoi hänelle: \"Salli nyt; sillä näin meidän sopii täyttää kaikki vanhurskaus\". Silloin hän salli sen hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 16, 'Kun Jeesus oli kastettu, nousi hän kohta vedestä, ja katso, taivaat aukenivat, ja hän näki Jumalan Hengen tulevan alas niinkuin kyyhkysen ja laskeutuvan hänen päällensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 3, 17, 'Ja katso, taivaista kuului ääni, joka sanoi: \"Tämä on minun rakas Poikani, johon minä olen mielistynyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 1, 'Sitten Henki vei Jeesuksen ylös erämaahan perkeleen kiusattavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 2, 'Ja kun Jeesus oli paastonnut neljäkymmentä päivää ja neljäkymmentä yötä, tuli hänen lopulta nälkä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 3, 'Silloin kiusaaja tuli hänen luoksensa ja sanoi hänelle: \"Jos sinä olet Jumalan Poika, niin käske näiden kivien muuttua leiviksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 4, 'Mutta hän vastasi ja sanoi: \"Kirjoitettu on: \'Ei ihminen elä ainoastaan leivästä, vaan jokaisesta sanasta, joka Jumalan suusta lähtee\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 5, 'Silloin perkele otti hänet kanssansa pyhään kaupunkiin ja asetti hänet pyhäkön harjalle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 6, 'ja sanoi hänelle: \"Jos sinä olet Jumalan Poika, niin heittäydy tästä alas; sillä kirjoitettu on: \'Hän antaa enkeleilleen käskyn sinusta\', ja: \'He kantavat sinua käsillänsä, ettet jalkaasi kiveen loukkaisi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 7, 'Jeesus sanoi hänelle: \"Taas on kirjoitettu: \'Älä kiusaa Herraa, sinun Jumalaasi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 8, 'Taas perkele otti hänet kanssansa sangen korkealle vuorelle ja näytti hänelle kaikki maailman valtakunnat ja niiden loiston');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 9, 'ja sanoi hänelle: \"Tämän kaiken minä annan sinulle, jos lankeat maahan ja kumarrat minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 10, 'Silloin Jeesus sanoi hänelle: \"Mene pois, saatana; sillä kirjoitettu on: \'Herraa, sinun Jumalaasi, pitää sinun kumartaman ja häntä ainoata palveleman\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 11, 'Silloin perkele jätti hänet; ja katso, enkeleitä tuli hänen tykönsä, ja he tekivät hänelle palvelusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 12, 'Mutta kun Jeesus kuuli, että Johannes oli pantu vankeuteen, poistui hän Galileaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 13, 'Ja hän jätti Nasaretin ja meni asumaan Kapernaumiin, joka on meren rannalla, Sebulonin ja Naftalin alueella;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 14, 'että kävisi toteen, mikä on puhuttu profeetta Esaiaan kautta, joka sanoo:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 15, '\"Sebulonin maa ja Naftalin maa, meren tie, Jordanin tuonpuoleinen maa, pakanain Galilea-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 16, 'kansa, joka pimeydessä istui, näki suuren valkeuden, ja jotka istuivat kuoleman maassa ja varjossa, niille koitti valkeus\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 17, 'Siitä lähtien Jeesus rupesi saarnaamaan ja sanomaan: \"Tehkää parannus, sillä taivasten valtakunta on tullut lähelle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 18, 'Ja kulkiessaan Galilean järven rantaa hän näki kaksi veljestä, Simonin, jota kutsutaan Pietariksi, ja Andreaan, hänen veljensä, heittämässä verkkoa järveen; sillä he olivat kalastajia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 19, 'Ja hän sanoi heille: \"Seuratkaa minua, niin minä teen teistä ihmisten kalastajia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 20, 'Niin he jättivät kohta verkot ja seurasivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 21, 'Ja käydessään siitä eteenpäin hän näki toiset kaksi veljestä, Jaakobin, Sebedeuksen pojan, ja Johanneksen, hänen veljensä, venheessä isänsä Sebedeuksen kanssa laittamassa verkkojaan kuntoon; ja hän kutsui heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 22, 'Niin he jättivät kohta venheen ja isänsä ja seurasivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 23, 'Ja hän kierteli kautta koko Galilean ja opetti heidän synagoogissaan ja saarnasi valtakunnan evankeliumia ja paransi kaikkinaisia tauteja ja kaikkinaista raihnautta, mitä kansassa oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 24, 'Ja maine hänestä levisi koko Syyriaan, ja hänen luoksensa tuotiin kaikki sairastavaiset, monenlaisten tautien ja vaivojen rasittamat, riivatut, kuunvaihetautiset ja halvatut; ja hän paransi heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 4, 25, 'Ja häntä seurasi suuri kansan paljous Galileasta ja Dekapolista ja Jerusalemista ja Juudeasta ja Jordanin tuolta puolen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 1, 'Kun hän näki kansanjoukot, nousi hän vuorelle; ja kun hän oli istuutunut, tulivat hänen opetuslapsensa hänen tykönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 2, 'Niin hän avasi suunsa ja opetti heitä ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 3, '\"Autuaita ovat hengellisesti köyhät, sillä heidän on taivasten valtakunta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 4, 'Autuaita ovat murheelliset, sillä he saavat lohdutuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 5, 'Autuaita ovat hiljaiset, sillä he saavat maan periä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 6, 'Autuaita ovat ne, jotka isoavat ja janoavat vanhurskautta, sillä heidät ravitaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 7, 'Autuaita ovat laupiaat, sillä he saavat laupeuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 8, 'Autuaita ovat puhdassydämiset, sillä he saavat nähdä Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 9, 'Autuaita ovat rauhantekijät, sillä heidät pitää Jumalan lapsiksi kutsuttaman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 10, 'Autuaita ovat ne, joita vanhurskauden tähden vainotaan, sillä heidän on taivasten valtakunta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 11, 'Autuaita olette te, kun ihmiset minun tähteni teitä solvaavat ja vainoavat ja valhetellen puhuvat teistä kaikkinaista pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 12, 'Iloitkaa ja riemuitkaa, sillä teidän palkkanne on suuri taivaissa. Sillä samoin he vainosivat profeettoja, jotka olivat ennen teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 13, 'Te olette maan suola; mutta jos suola käy mauttomaksi, millä se saadaan suolaiseksi? Se ei enää kelpaa mihinkään muuhun kuin pois heitettäväksi ja ihmisten tallattavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 14, 'Te olette maailman valkeus. Ei voi ylhäällä vuorella oleva kaupunki olla kätkössä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 15, 'eikä lamppua sytytetä ja panna vakan alle, vaan lampunjalkaan, ja niin se loistaa kaikille huoneessa oleville.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 16, 'Niin loistakoon teidän valonne ihmisten edessä, että he näkisivät teidän hyvät tekonne ja ylistäisivät teidän Isäänne, joka on taivaissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 17, 'Älkää luulko, että minä olen tullut lakia tai profeettoja kumoamaan; en minä ole tullut kumoamaan, vaan täyttämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 18, 'Sillä totisesti minä sanon teille: kunnes taivas ja maa katoavat, ei laista katoa pieninkään kirjain, ei ainoakaan piirto, ennenkuin kaikki on tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 19, 'Sentähden, joka purkaa yhdenkään näistä pienimmistä käskyistä ja sillä tavalla opettaa ihmisiä, se pitää pienimmäksi taivasten valtakunnassa kutsuttaman; mutta joka niitä noudattaa ja niin opettaa, se pitää kutsuttaman suureksi taivasten valtakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 20, 'Sillä minä sanon teille: ellei teidän vanhurskautenne ole paljoa suurempi kuin kirjanoppineiden ja fariseusten, niin te ette pääse taivasten valtakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 21, 'Te olette kuulleet sanotuksi vanhoille: \'Älä tapa\', ja: \'Joka tappaa, se on ansainnut oikeuden tuomion\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 22, 'Mutta minä sanon teille: jokainen, joka vihastuu veljeensä, on ansainnut oikeuden tuomion; ja joka sanoo veljelleen: \'Sinä tyhjänpäiväinen\', on ansainnut suuren neuvoston tuomion; ja joka sanoo: \'Sinä hullu\', on ansainnut helvetin tulen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 23, 'Sentähden, jos tuot lahjaasi alttarille ja siellä muistat, että veljelläsi on jotakin sinua vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 24, 'niin jätä lahjasi siihen alttarin eteen, ja käy ensin sopimassa veljesi kanssa, ja tule sitten uhraamaan lahjasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 25, 'Suostu pian sopimaan riitapuolesi kanssa, niin kauan kuin vielä olet hänen kanssaan tiellä, ettei riitapuolesi vetäisi sinua tuomarin eteen ja tuomari antaisi sinua oikeudenpalvelijalle, ja ettei sinua pantaisi vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 26, 'Totisesti minä sanon sinulle: sieltä et pääse, ennenkuin maksat viimeisenkin rovon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 27, 'Te olette kuulleet sanotuksi: \'Älä tee huorin\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 28, 'Mutta minä sanon teille: jokainen, joka katsoo naista himoiten häntä, on jo sydämessään tehnyt huorin hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 29, 'Jos sinun oikea silmäsi viettelee sinua, repäise se pois ja heitä luotasi; sillä parempi on sinulle, että yksi jäsenistäsi joutuu hukkaan, kuin että koko ruumiisi heitetään helvettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 30, 'Ja jos sinun oikea kätesi viettelee sinua, hakkaa se poikki ja heitä luotasi; sillä parempi on sinulle, että yksi jäsenistäsi joutuu hukkaan, kuin että koko ruumiisi menee helvettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 31, 'On sanottu: \'Joka hylkää vaimonsa, antakoon hänelle erokirjan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 32, 'Mutta minä sanon teille: jokainen, joka hylkää vaimonsa muun kuin huoruuden tähden, saattaa hänet tekemään huorin, ja joka nai hyljätyn, tekee huorin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 33, 'Vielä olette kuulleet sanotuksi vanhoille: \'Älä vanno väärin\', ja: \'Täytä Herralle valasi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 34, 'Mutta minä sanon teille: älkää ensinkään vannoko, älkää taivaan kautta, sillä se on Jumalan valtaistuin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 35, 'Älkääkä maan kautta, sillä se on hänen jalkojensa astinlauta, älkää myöskään Jerusalemin kautta, sillä se on suuren Kuninkaan kaupunki;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 36, 'Äläkä vanno pääsi kautta, sillä et sinä voi yhtäkään hiusta tehdä valkeaksi etkä mustaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 37, 'vaan olkoon teidän puheenne: \'On, on\', tahi: \'ei, ei\'. Mitä siihen lisätään, se on pahasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 38, 'Te olette kuulleet sanotuksi: \'Silmä silmästä ja hammas hampaasta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 39, 'Mutta minä sanon teille: älkää tehkö pahalle vastarintaa; vaan jos joku lyö sinua oikealle poskelle, käännä hänelle toinenkin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 40, 'ja jos joku tahtoo sinun kanssasi käydä oikeutta ja ottaa ihokkaasi, anna hänen saada vaippasikin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 41, 'ja jos joku pakottaa sinua yhden virstan matkalle, kulje hänen kanssaan kaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 42, 'Anna sille, joka sinulta anoo, äläkä käännä selkääsi sille, joka sinulta lainaa pyytää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 43, 'Te olette kuulleet sanotuksi: \'Rakasta lähimmäistäsi ja vihaa vihollistasi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 44, 'Mutta minä sanon teille: rakastakaa vihollisianne ja rukoilkaa niiden puolesta, jotka teitä vainoavat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 45, 'että olisitte Isänne lapsia, joka on taivaissa; sillä hän antaa aurinkonsa koittaa niin pahoille kuin hyvillekin, ja antaa sataa niin väärille kuin vanhurskaillekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 46, 'Sillä jos te rakastatte niitä, jotka teitä rakastavat, mikä palkka teille siitä on tuleva? Eivätkö publikaanitkin tee samoin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 47, 'Ja jos te osoitatte ystävällisyyttä ainoastaan veljillenne, mitä erinomaista te siinä teette? Eivätkö pakanatkin tee samoin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 5, 48, 'Olkaa siis te täydelliset, niinkuin teidän taivaallinen Isänne täydellinen on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 1, '\"Kavahtakaa, ettette harjoita vanhurskauttanne ihmisten nähden, että he teitä katselisivat; muutoin ette saa palkkaa Isältänne, joka on taivaissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 2, 'Sentähden, kun annat almuja, älä soitata torvea edelläsi, niinkuin ulkokullatut tekevät synagoogissa ja kaduilla saadakseen ylistystä ihmisiltä. Totisesti minä sanon teille: he ovat saaneet palkkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 3, 'Vaan kun sinä almua annat, älköön vasen kätesi tietäkö, mitä oikea kätesi tekee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 4, 'että almusi olisi salassa; ja sinun Isäsi, joka salassa näkee, maksaa sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 5, 'Ja kun rukoilette, älkää olko niinkuin ulkokullatut; sillä he mielellään seisovat ja rukoilevat synagoogissa ja katujen kulmissa, että ihmiset heidät näkisivät. Totisesti minä sanon teille: he ovat saaneet palkkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 6, 'Vaan sinä, kun rukoilet, mene kammioosi ja sulje ovesi ja rukoile Isääsi, joka on salassa; ja sinun Isäsi, joka salassa näkee, maksaa sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 7, 'Ja kun rukoilette, niin älkää tyhjiä hokeko niinkuin pakanat, jotka luulevat, että heitä heidän monisanaisuutensa tähden kuullaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 8, 'Älkää siis olko heidän kaltaisiaan; sillä teidän Isänne kyllä tietää, mitä te tarvitsette, ennenkuin häneltä anottekaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 9, 'Rukoilkaa siis te näin: Isä meidän, joka olet taivaissa! Pyhitetty olkoon sinun nimesi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 10, 'tulkoon sinun valtakuntasi; tapahtukoon sinun tahtosi myös maan päällä niinkuin taivaassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 11, 'anna meille tänä päivänä meidän jokapäiväinen leipämme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 12, 'ja anna meille meidän velkamme anteeksi, niinkuin mekin annamme anteeksi meidän velallisillemme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 13, 'Äläkä saata meitä kiusaukseen; vaan päästä meidät pahasta, <FO>sillä sinun on valtakunta ja voima ja kunnia iankaikkisesti. Amen.<Fo>');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 14, 'Sillä jos te annatte anteeksi ihmisille heidän rikkomuksensa, niin teidän taivaallinen Isänne myös antaa teille anteeksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 15, 'mutta jos te ette anna ihmisille anteeksi, niin ei myöskään teidän Isänne anna anteeksi teidän rikkomuksianne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 16, 'Ja kun paastoatte, älkää olko synkännäköisiä niinkuin ulkokullatut; sillä he tekevät kasvonsa surkeiksi, että ihmiset näkisivät heidän paastoavan. Totisesti minä sanon teille: he ovat saaneet palkkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 17, 'Vaan kun sinä paastoat, niin voitele pääsi ja pese kasvosi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 18, 'etteivät paastoamistasi näkisi ihmiset, vaan sinun Isäsi, joka on salassa; ja sinun Isäsi, joka salassa näkee, maksaa sinulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 19, 'Älkää kootko itsellenne aarteita maan päälle, missä koi ja ruoste raiskaa ja missä varkaat murtautuvat sisään ja varastavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 20, 'Vaan kootkaa itsellenne aarteita taivaaseen, missä ei koi eikä ruoste raiskaa ja missä eivät varkaat murtaudu sisään eivätkä varasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 21, 'Sillä missä sinun aarteesi on, siellä on myös sinun sydämesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 22, 'Silmä on ruumiin lamppu. Jos siis silmäsi on terve, niin koko sinun ruumiisi on valaistu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 23, 'Mutta jos silmäsi on viallinen, niin koko ruumiisi on pimeä. Jos siis se valo, joka sinussa on, on pimeyttä, kuinka suuri onkaan pimeys!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 24, 'Ei kukaan voi palvella kahta herraa; sillä hän on joko tätä vihaava ja toista rakastava, taikka tähän liittyvä ja toista halveksiva. Ette voi palvella Jumalaa ja mammonaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 25, 'Sentähden minä sanon teille: älkää murehtiko hengestänne, mitä söisitte tai mitä joisitte, älkääkä ruumiistanne, mitä päällenne pukisitte. Eikö henki ole enemmän kuin ruoka ja ruumis enemmän kuin vaatteet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 26, 'Katsokaa taivaan lintuja: eivät ne kylvä eivätkä leikkaa eivätkä kokoa aittoihin, ja teidän taivaallinen Isänne ruokkii ne. Ettekö te ole paljoa suurempiarvoiset kuin ne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 27, 'Ja kuka teistä voi murehtimisellaan lisätä ikäänsä kyynäränkään vertaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 28, 'Ja mitä te murehditte vaatteista? Katselkaa kedon kukkia, kuinka ne kasvavat; eivät ne työtä tee eivätkä kehrää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 29, 'Kuitenkin minä sanon teille: ei Salomo kaikessa loistossansa ollut niin vaatetettu kuin yksi niistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 30, 'Jos siis Jumala näin vaatettaa kedon ruohon, joka tänään kasvaa ja huomenna uuniin heitetään, eikö paljoa ennemmin teitä, te vähäuskoiset?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 31, 'Älkää siis murehtiko sanoen: \'Mitä me syömme?\' tahi: \'Mitä me juomme?\' tahi: \'Millä me itsemme vaatetamme?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 32, 'Sillä tätä kaikkea pakanat tavoittelevat. Teidän taivaallinen Isänne kyllä tietää teidän kaikkea tätä tarvitsevan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 33, 'Vaan etsikää ensin Jumalan valtakuntaa ja hänen vanhurskauttansa, niin myös kaikki tämä teille annetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 6, 34, 'Älkää siis murehtiko huomisesta päivästä, sillä huominen päivä pitää murheen itsestään. Riittää kullekin päivälle oma vaivansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 1, '\"Älkää tuomitko, ettei teitä tuomittaisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 2, 'sillä millä tuomiolla te tuomitsette, sillä teidät tuomitaan; ja millä mitalla te mittaatte, sillä teille mitataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 3, 'Kuinka näet rikan, joka on veljesi silmässä, mutta et huomaa malkaa omassa silmässäsi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 4, 'Taikka kuinka saatat sanoa veljellesi: \'Annas, minä otan rikan silmästäsi\', ja katso, malka on omassa silmässäsi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 5, 'Sinä ulkokullattu, ota ensin malka omasta silmästäsi, ja sitten sinä näet ottaa rikan veljesi silmästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 6, 'Älkää antako pyhää koirille, älkääkä heittäkö helmiänne sikojen eteen, etteivät ne tallaisi niitä jalkoihinsa ja kääntyisi ja repisi teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 7, 'Anokaa, niin teille annetaan; etsikää, niin te löydätte; kolkuttakaa, niin teille avataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 8, 'Sillä jokainen anova saa, ja etsivä löytää, ja kolkuttavalle avataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 9, 'Vai kuka teistä on se ihminen, joka antaa pojallensa kiven, kun tämä pyytää häneltä leipää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 10, 'taikka, kun hän pyytää kalaa, antaa hänelle käärmeen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 11, 'Jos siis te, jotka olette pahoja, osaatte antaa lapsillenne hyviä lahjoja, kuinka paljoa ennemmin teidän Isänne, joka on taivaissa, antaa sitä, mikä hyvää on, niille, jotka sitä häneltä anovat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 12, 'Sentähden, kaikki, mitä te tahdotte ihmisten teille tekevän, tehkää myös te samoin heille; sillä tämä on laki ja profeetat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 13, 'Menkää ahtaasta portista sisälle. Sillä se portti on avara ja tie lavea, joka vie kadotukseen, ja monta on, jotka siitä sisälle menevät;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 14, 'mutta se portti on ahdas ja tie kaita, joka vie elämään, ja harvat ovat ne, jotka sen löytävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 15, 'Kavahtakaa vääriä profeettoja, jotka tulevat teidän luoksenne lammastenvaatteissa, mutta sisältä ovat raatelevaisia susia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 16, 'Heidän hedelmistään te tunnette heidät. Eihän orjantappuroista koota viinirypäleitä eikä ohdakkeista viikunoita?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 17, 'Näin jokainen hyvä puu tekee hyviä hedelmiä, mutta huono puu tekee pahoja hedelmiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 18, 'Ei saata hyvä puu kasvaa pahoja hedelmiä eikä huono puu kasvaa hyviä hedelmiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 19, 'Jokainen puu, joka ei tee hyvää hedelmää, hakataan pois ja heitetään tuleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 20, 'Niin te siis tunnette heidät heidän hedelmistään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 21, 'Ei jokainen, joka sanoo minulle: \'Herra, Herra!\', pääse taivasten valtakuntaan, vaan se, joka tekee minun taivaallisen Isäni tahdon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 22, 'Moni sanoo minulle sinä päivänä: \'Herra, Herra, emmekö me sinun nimesi kautta ennustaneet ja sinun nimesi kautta ajaneet ulos riivaajia ja sinun nimesi kautta tehneet monta voimallista tekoa?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 23, 'Ja silloin minä lausun heille julki: \'Minä en ole koskaan teitä tuntenut; menkää pois minun tyköäni, te laittomuuden tekijät\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 24, 'Sentähden on jokainen, joka kuulee nämä minun sanani ja tekee niiden mukaan, verrattava ymmärtäväiseen mieheen, joka huoneensa kalliolle rakensi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 25, 'Ja rankkasade lankesi, ja virrat tulvivat, ja tuulet puhalsivat ja syöksyivät sitä huonetta vastaan, mutta se ei sortunut, sillä se oli kalliolle perustettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 26, 'Ja jokainen, joka kuulee nämä minun sanani eikä tee niiden mukaan, on verrattava tyhmään mieheen, joka huoneensa hiekalle rakensi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 27, 'Ja rankkasade lankesi, ja virrat tulvivat, ja tuulet puhalsivat ja syöksähtivät sitä huonetta vastaan, ja se sortui, ja sen sortuminen oli suuri.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 28, 'Ja kun Jeesus lopetti nämä puheet, olivat kansanjoukot hämmästyksissään hänen opetuksestansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 7, 29, 'sillä hän opetti heitä niinkuin se, jolla valta on, eikä niinkuin heidän kirjanoppineensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 1, 'Kun hän astui alas vuorelta, seurasi häntä suuri kansan paljous.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 2, 'Ja katso, tuli pitalinen mies ja kumartui maahan hänen eteensä ja sanoi: \"Herra, jos tahdot, niin sinä voit minut puhdistaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 3, 'Niin hän ojensi kätensä, kosketti häntä ja sanoi: \"Minä tahdon; puhdistu\". Ja kohta hän puhdistui pitalistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 4, 'Ja Jeesus sanoi hänelle: \"Katso, ettet puhu tästä kenellekään; vaan mene ja näytä itsesi papille, ja uhraa lahja, jonka Mooses on säätänyt, todistukseksi heille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 5, 'Ja kun hän saapui Kapernaumiin, tuli hänen tykönsä sadanpäämies ja rukoili häntä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 6, 'ja sanoi: \"Herra, minun palvelijani makaa kotona halvattuna ja on kovissa vaivoissa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 7, 'Hän sanoi hänelle: \"Minä tulen ja parannan hänet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 8, 'Mutta sadanpäämies vastasi ja sanoi: \"Herra, en minä ole sen arvoinen, että tulisit minun kattoni alle; vaan sano ainoastaan sana, niin minun palvelijani paranee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 9, 'Sillä minä itsekin olen toisen vallan alainen, ja minulla on sotamiehiä käskyni alaisina, ja minä sanon tälle: \'Mene\', ja hän menee, ja toiselle: \'Tule\', ja hän tulee, ja palvelijalleni: \'Tee tämä\', ja hän tekee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 10, 'Tämän kuultuaan Jeesus ihmetteli ja sanoi niille, jotka häntä seurasivat: \"Totisesti minä sanon teille: en ole kenelläkään Israelissa löytänyt näin suurta uskoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 11, 'Ja minä sanon teille: monet tulevat idästä ja lännestä ja aterioitsevat Aabrahamin ja Iisakin ja Jaakobin kanssa taivasten valtakunnassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 12, 'mutta valtakunnan lapset heitetään ulos pimeyteen; siellä on oleva itku ja hammasten kiristys.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 13, 'Ja Jeesus sanoi sadanpäämiehelle: \"Mene. Niinkuin sinä uskot, niin sinulle tapahtukoon.\" Ja palvelija parani sillä hetkellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 14, 'Kun Jeesus tuli Pietarin kotiin, näki hän hänen anoppinsa makaavan sairaana kuumeessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 15, 'Niin hän koski tämän käteen, ja kuume lähti hänestä; ja hän nousi ja palveli häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 16, 'Mutta illan tultua tuotiin hänen tykönsä monta riivattua. Ja hän ajoi henget ulos sanalla, ja kaikki sairaat hän paransi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 17, 'että kävisi toteen, mikä on puhuttu profeetta Esaiaan kautta, joka sanoo: \"Hän otti päällensä meidän sairautemme ja kantoi meidän tautimme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 18, 'Mutta kun Jeesus näki paljon kansaa ympärillään, käski hän lähteä toiselle rannalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 19, 'Ja eräs kirjanoppinut tuli ja sanoi hänelle: \"Opettaja, minä seuraan sinua, mihin ikinä menet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 20, 'Niin Jeesus sanoi hänelle: \"Ketuilla on luolat ja taivaan linnuilla pesät, mutta Ihmisen Pojalla ei ole, mihin hän päänsä kallistaisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 21, 'Ja eräs toinen hänen opetuslapsistaan sanoi hänelle: \"Herra, salli minun ensin käydä hautaamassa isäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 22, 'Mutta Jeesus sanoi hänelle: \"Seuraa sinä minua, ja anna kuolleitten haudata kuolleensa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 23, 'Ja hän astui venheeseen, ja hänen opetuslapsensa seurasivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 24, 'Ja katso, järvellä nousi kova myrsky, niin että venhe peittyi aaltoihin; mutta hän nukkui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 25, 'Niin he menivät ja herättivät hänet sanoen: \"Herra, auta, me hukumme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 26, 'Hän sanoi heille: \"Te vähäuskoiset, miksi olette pelkureita?\" Silloin hän nousi ja nuhteli tuulia ja järveä, ja tuli aivan tyven.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 27, 'Ja ihmiset ihmettelivät ja sanoivat: \"Millainen tämä on, kun sekä tuulet että meri häntä tottelevat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 28, 'Kun hän tuli toiselle rannalle, gadaralaisten alueelle, tuli häntä vastaan kaksi riivattua, jotka olivat haudoista lähteneet ja olivat kovin raivoisia, niin ettei kukaan voinut sitä tietä kulkea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 29, 'Ja katso, he huusivat sanoen: \"Mitä sinulla on meidän kanssamme tekemistä, sinä Jumalan Poika? Oletko tullut tänne vaivaamaan meitä ennen aikaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 30, 'Ja etäällä heistä kävi suuri sikalauma laitumella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 31, 'Niin riivaajahenget pyysivät häntä sanoen: \"Jos ajat meidät pois, niin lähetä meidät sikalaumaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 32, 'Ja hän sanoi niille: \"Menkää\". Silloin ne lähtivät heistä ja menivät sikoihin. Ja katso, koko lauma syöksyi jyrkännettä alas järveen ja hukkui veteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 33, 'Mutta paimentajat pakenivat; ja he menivät kaupunkiin ja ilmoittivat kaikki, myöskin sen, miten riivattujen oli käynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 8, 34, 'Ja katso, koko kaupunki lähti Jeesusta vastaan; ja kun he hänet näkivät, pyysivät he häntä menemään pois heidän alueeltaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 1, 'Ja hän astui venheeseen, meni jälleen toiselle rannalle ja tuli omaan kaupunkiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 2, 'Ja katso, hänen tykönsä tuotiin halvattu mies, joka makasi vuoteella. Kun Jeesus näki heidän uskonsa, sanoi hän halvatulle: \"Poikani, ole turvallisella mielellä; sinun syntisi annetaan sinulle anteeksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 3, 'Ja katso, muutamat kirjanoppineista sanoivat mielessään: \"Tämä pilkkaa Jumalaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 4, 'Mutta Jeesus ymmärsi heidän ajatuksensa ja sanoi: \"Miksi te ajattelette pahaa sydämessänne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 5, 'Sillä kumpi on helpompaa, sanoako: \'Sinun syntisi annetaan sinulle anteeksi\', vai sanoa: \'Nouse ja käy\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 6, 'Mutta tietääksenne, että Ihmisen Pojalla on valta maan päällä antaa syntejä anteeksi, niin\" -hän sanoi halvatulle-\"nouse, ota vuoteesi ja mene kotiisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 7, 'Ja hän nousi ja lähti kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 8, 'Mutta kun kansanjoukot sen näkivät, peljästyivät he ja ylistivät Jumalaa, joka oli antanut senkaltaisen vallan ihmisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 9, 'Ja sieltä kulkiessaan ohi Jeesus näki miehen, jonka nimi oli Matteus, istumassa tulliasemalla ja sanoi hänelle: \"Seuraa minua\". Niin tämä nousi ja seurasi häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 10, 'Ja kun hän aterioi hänen kodissaan, niin katso, tuli monta publikaania ja syntistä, ja he aterioivat Jeesuksen ja hänen opetuslastensa kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 11, 'Ja kun fariseukset sen näkivät, sanoivat he hänen opetuslapsilleen: \"Miksi teidän opettajanne syö publikaanien ja syntisten kanssa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 12, 'Mutta kun Jeesus sen kuuli, sanoi hän: \"Eivät terveet tarvitse parantajaa, vaan sairaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 13, 'Mutta menkää ja oppikaa, mitä tämä on: \'Laupeutta minä tahdon enkä uhria\'. Sillä en minä ole tullut kutsumaan vanhurskaita, vaan syntisiä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 14, 'Silloin Johanneksen opetuslapset tulivat hänen tykönsä ja sanoivat: \"Me ja fariseukset paastoamme paljon; miksi sinun opetuslapsesi eivät paastoa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 15, 'Niin Jeesus sanoi heille: \"Eiväthän häävieraat voi surra, niinkauan kuin ylkä on heidän kanssaan? Mutta päivät tulevat, jolloin ylkä otetaan heiltä pois, ja silloin he paastoavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 16, 'Ei kukaan pane vanuttamattomasta kankaasta paikkaa vanhaan vaippaan, sillä semmoinen täytetilkku repii palasen vaipasta, ja reikä tulee pahemmaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 17, 'Eikä nuorta viiniä lasketa vanhoihin nahkaleileihin; muutoin leilit pakahtuvat, ja viini juoksee maahan, ja leilit turmeltuvat; vaan nuori viini lasketaan uusiin leileihin, ja niin molemmat säilyvät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 18, 'Kun hän tätä heille puhui, niin katso, eräs päämies tuli ja kumartui maahan hänen eteensä ja sanoi: \"Minun tyttäreni kuoli juuri ikään, mutta tule ja pane kätesi hänen päällensä, niin hän virkoaa eloon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 19, 'Niin Jeesus nousi ja seurasi häntä opetuslapsinensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 20, 'Ja katso, nainen, joka oli sairastanut verenjuoksua kaksitoista vuotta, tuli takaapäin ja kosketti hänen vaippansa tupsua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 21, 'Sillä hän sanoi itsekseen: \"Jos vain saan koskettaa hänen vaippaansa, niin minä tulen terveeksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 22, 'Silloin Jeesus kääntyi, näki hänet ja sanoi: \"Tyttäreni, ole turvallisella mielellä; sinun uskosi on tehnyt sinut terveeksi\". Ja sillä hetkellä nainen tuli terveeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 23, 'Ja kun Jeesus tuli päämiehen taloon ja näki huilunsoittajat ja hälisevän väkijoukon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 24, 'sanoi hän: \"Menkää pois, sillä tyttö ei ole kuollut, vaan nukkuu\". Niin he nauroivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 25, 'Mutta kun väkijoukko oli ajettu ulos, meni hän sisälle ja tarttui hänen käteensä; ja tyttö nousi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 26, 'Ja sanoma tästä levisi koko siihen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 27, 'Ja kun Jeesus kulki sieltä, seurasi häntä kaksi sokeaa huutaen ja sanoen: \"Daavidin poika, armahda meitä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 28, 'Ja hänen mentyänsä huoneeseen sokeat tulivat hänen tykönsä; ja Jeesus sanoi heille: \"Uskotteko, että minä voin sen tehdä?\" He sanoivat hänelle: \"Uskomme, Herra\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 29, 'Silloin hän kosketti heidän silmiänsä ja sanoi: \"Tapahtukoon teille uskonne mukaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 30, 'Ja heidän silmänsä aukenivat. Ja Jeesus varoitti heitä vakavasti sanoen: \"Katsokaa, ettei kukaan saa tästä tietää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 31, 'Mutta he menivät pois ja levittivät sanomaa hänestä koko siihen maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 32, 'Ja katso, näiden lähdettyä tuotiin hänen tykönsä mykkä mies, joka oli riivattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 33, 'Ja kun riivaaja oli ajettu ulos, niin mykkä puhui, ja kansa ihmetteli sanoen: \"Tällaista ei ole Israelissa ikinä nähty\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 34, 'Mutta fariseukset sanoivat: \"Riivaajain päämiehen voimalla hän ajaa ulos riivaajia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 35, 'Ja Jeesus vaelsi kaikki kaupungit ja kylät ja opetti heidän synagoogissaan ja saarnasi valtakunnan evankeliumia ja paransi kaikkinaisia tauteja ja kaikkinaista raihnautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 36, 'Ja nähdessään kansanjoukot hänen tuli heitä sääli, kun he olivat nääntyneet ja hyljätyt niinkuin lampaat, joilla ei ole paimenta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 37, 'Silloin hän sanoi opetuslapsillensa: \"Eloa on paljon, mutta työmiehiä vähän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 9, 38, 'Rukoilkaa siis elon Herraa, että hän lähettäisi työmiehiä elonkorjuuseensa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 1, 'Ja hän kutsui tykönsä ne kaksitoista opetuslastaan ja antoi heille vallan ajaa ulos saastaisia henkiä ja parantaa kaikkinaisia tauteja ja kaikkinaista raihnautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 2, 'Ja nämä ovat niiden kahdentoista apostolin nimet: ensimmäinen oli Simon, jota kutsuttiin Pietariksi, ja Andreas, hänen veljensä, sitten Jaakob Sebedeuksen poika, ja Johannes, hänen veljensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 3, 'Filippus ja Bartolomeus, Tuomas ja Matteus, publikaani, Jaakob, Alfeuksen poika, ja Lebbeus, lisänimeltä Taddeus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 4, 'Simon Kananeus ja Juudas Iskariot, sama, joka hänet kavalsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 5, 'Nämä kaksitoista Jeesus lähetti ja käski heitä sanoen: \"Älköön tienne viekö pakanain luokse, älkääkä menkö mihinkään samarialaisten kaupunkiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 6, 'vaan menkää ennemmin Israelin huoneen kadonneitten lammasten tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 7, 'Ja missä kuljette, saarnatkaa ja sanokaa: \'Taivasten valtakunta on tullut lähelle\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 8, 'Parantakaa sairaita, herättäkää kuolleita, puhdistakaa pitalisia, ajakaa ulos riivaajia. Lahjaksi olette saaneet, lahjaksi antakaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 9, 'Älkää varustako itsellenne kultaa, älkää hopeata älkääkä vaskea vyöhönne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 10, 'Älkää laukkua matkalle, älkää kahta ihokasta, älkää kenkiä, älkääkä sauvaa; sillä työmies on ruokansa ansainnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 11, 'Ja mihin kaupunkiin tai kylään te tulettekin, tiedustelkaa, kuka siellä on arvollinen, ja jääkää hänen luokseen, kunnes sieltä lähdette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 12, 'Ja tullessanne taloon tervehtikää sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 13, 'Ja jos talo on arvollinen, tulkoon sille teidän rauhanne; mutta jos se ei ole arvollinen, palatkoon teidän rauhanne teille takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 14, 'Ja missä teitä ei oteta vastaan eikä teidän sanojanne kuulla, lähtekää pois siitä talosta tai siitä kaupungista ja pudistakaa tomu jaloistanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 15, 'Totisesti minä sanon teille: Sodoman ja Gomorran maan on tuomiopäivänä oleva helpompi kuin sen kaupungin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 16, 'Katso, minä lähetän teidät niinkuin lampaat susien keskelle; olkaa siis älykkäät kuin käärmeet ja viattomat kuin kyyhkyset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 17, 'Kavahtakaa ihmisiä, sillä he vetävät teidät oikeuksiin, ja synagoogissaan he teitä ruoskivat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 18, 'ja teidät viedään maaherrain ja kuningasten eteen minun tähteni, todistukseksi heille ja pakanoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 19, 'Mutta kun he vetävät teitä oikeuteen, älkää huolehtiko siitä, miten tahi mitä puhuisitte, sillä teille annetaan sillä hetkellä, mitä teidän on puhuminen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 20, 'Sillä ette te itse puhu, vaan teidän Isänne Henki puhuu teissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 21, 'Ja veli antaa veljensä kuolemaan ja isä lapsensa, ja lapset nousevat vanhempiansa vastaan ja tappavat heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 22, 'Ja te joudutte kaikkien vihattaviksi minun nimeni tähden; mutta joka vahvana pysyy loppuun asti, se pelastuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 23, 'Ja kun teitä vainotaan yhdessä kaupungissa, paetkaa toiseen; sillä totisesti minä sanon teille: te ette ehdi loppuun käydä Israelin kaupunkeja, ennenkuin Ihmisen Poika tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 24, 'Ei ole opetuslapsi opettajaansa parempi, eikä palvelija parempi isäntäänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 25, 'Opetuslapselle riittää, että hänelle käy niinkuin hänen opettajalleen, ja palvelijalle, että hänelle käy niinkuin hänen isännälleen. Jos he perheenisäntää ovat sanoneet Beelsebuliksi, kuinka paljoa enemmän hänen perheväkeään!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 26, 'Älkää siis peljätkö heitä. Sillä ei ole mitään peitettyä, mitä ei tule paljastetuksi, eikä mitään salattua, mikä ei tule tunnetuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 27, 'Minkä minä sanon teille pimeässä, se puhukaa päivän valossa. Ja minkä kuulette kuiskattavan korvaanne, se julistakaa katoilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 28, 'Älkääkä peljätkö niitä, jotka tappavat ruumiin, mutta eivät voi tappaa sielua; vaan ennemmin peljätkää häntä, joka voi sekä sielun että ruumiin hukuttaa helvettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 29, 'Eikö kahta varpusta myydä yhteen ropoon? Eikä yksikään niistä putoa maahan teidän Isänne sallimatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 30, 'Ovatpa teidän päänne hiuksetkin kaikki luetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 31, 'Älkää siis peljätkö; te olette suurempiarvoiset kuin monta varpusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 32, 'Sentähden, jokaisen, joka tunnustaa minut ihmisten edessä, minäkin tunnustan Isäni edessä, joka on taivaissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 33, 'Mutta joka kieltää minut ihmisten edessä, sen minäkin kiellän Isäni edessä, joka on taivaissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 34, 'Älkää luulko, että minä olen tullut tuomaan rauhaa maan päälle; en ole tullut tuomaan rauhaa, vaan miekan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 35, 'Sillä minä olen tullut \'nostamaan pojan riitaan isäänsä vastaan ja tyttären äitiänsä vastaan ja miniän anoppiansa vastaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 36, 'ja ihmisen vihamiehiksi tulevat hänen omat perhekuntalaisensa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 37, 'Joka rakastaa isäänsä taikka äitiänsä enemmän kuin minua, se ei ole minulle sovelias; ja joka rakastaa poikaansa taikka tytärtänsä enemmän kuin minua, se ei ole minulle sovelias;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 38, 'ja joka ei ota ristiänsä ja seuraa minua, se ei ole minulle sovelias.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 39, 'Joka löytää elämänsä, kadottaa sen; ja joka kadottaa elämänsä minun tähteni, hän löytää sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 40, 'Joka ottaa tykönsä teidät, se ottaa tykönsä minut; ja joka ottaa minut tykönsä, ottaa tykönsä hänet, joka on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 41, 'Joka profeetan ottaa tykönsä profeetan nimen tähden, saa profeetan palkan; ja joka vanhurskaan ottaa tykönsä vanhurskaan nimen tähden, saa vanhurskaan palkan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 10, 42, 'Ja kuka hyvänsä antaa yhdelle näistä pienistä maljallisen kylmää vettä, hänen juodaksensa, opetuslapsen nimen tähden, totisesti minä sanon teille: hän ei jää palkkaansa vaille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 1, 'Ja kun Jeesus oli antanut kahdelletoista opetuslapselleen kaikki nämä käskyt, niin hän lähti sieltä opettamaan ja saarnaamaan heidän kaupunkeihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 2, 'Mutta kun Johannes vankilassa ollessaan kuuli Kristuksen teot, lähetti hän opetuslapsiansa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 3, 'sanomaan hänelle: \"Oletko sinä se tuleva, vai pitääkö meidän toista odottaman?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 4, 'Niin Jeesus vastasi ja sanoi heille: \"Menkää ja kertokaa Johannekselle, mitä kuulette ja näette:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 5, 'sokeat saavat näkönsä, ja rammat kävelevät, pitaliset puhdistuvat, ja kuurot kuulevat, ja kuolleet herätetään, ja köyhille julistetaan evankeliumia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 6, 'Ja autuas on se, joka ei loukkaannu minuun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 7, 'Kun he olivat menneet, rupesi Jeesus puhumaan kansalle Johanneksesta: \"Mitä te lähditte erämaahan katselemaan? Ruokoako, jota tuuli huojuttaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 8, 'Vai mitä lähditte katsomaan? Ihmistäkö, hienoihin vaatteisiin puettua? Katso, hienopukuiset ovat kuningasten kartanoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 9, 'Vai mitä te lähditte? Profeettaako katsomaan? Totisesti, minä sanon teille: hän on enemmän kuin profeetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 10, 'Tämä on se, josta on kirjoitettu: \'Katso, minä lähetän enkelini sinun edelläsi, ja hän on valmistava tiesi sinun eteesi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 11, 'Totisesti minä sanon teille: ei ole vaimoista syntyneitten joukosta noussut suurempaa kuin Johannes Kastaja; mutta vähäisin taivasten valtakunnassa on suurempi kuin hän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 12, 'Mutta Johannes Kastajan päivistä tähän asti hyökätään taivasten valtakuntaa vastaan, ja hyökkääjät tempaavat sen itselleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 13, 'Sillä kaikki profeetat ja laki ovat ennustaneet Johannekseen asti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 14, 'ja jos tahdotte ottaa vastaan: hän on Elias, joka oli tuleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 15, 'Jolla on korvat, se kuulkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 16, 'Mutta mihin minä vertaan tämän sukupolven? Se on lasten kaltainen, jotka istuvat toreilla ja huutavat toisilleen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 17, 'sanoen: \'Me soitimme teille huilua, ja te ette karkeloineet; me veisasimme itkuvirsiä, ja te ette valittaneet\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 18, 'Sillä Johannes tuli, hän ei syö eikä juo, ja he sanovat: \'Hänessä on riivaaja\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 19, 'Ihmisen Poika tuli, hän syö ja juo, ja he sanovat: \'Katso syömäriä ja viininjuojaa, publikaanien ja syntisten ystävää!\' Ja viisaus on oikeaksi näytetty teoissansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 20, 'Sitten hän rupesi nuhtelemaan niitä kaupunkeja, joissa useimmat hänen voimalliset tekonsa olivat tapahtuneet, siitä, etteivät ne olleet tehneet parannusta:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 21, '\"Voi sinua, Korasin! Voi sinua, Beetsaida! Sillä jos ne voimalliset teot, jotka ovat tapahtuneet teissä, olisivat tapahtuneet Tyyrossa ja Siidonissa, niin nämä jo aikaa sitten olisivat säkissä ja tuhassa tehneet parannuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 22, 'Mutta minä sanon teille: Tyyron ja Siidonin on tuomiopäivänä oleva helpompi kuin teidän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 23, 'Ja sinä, Kapernaum, korotetaankohan sinut hamaan taivaaseen? Hamaan tuonelaan on sinun astuttava alas. Sillä jos ne voimalliset teot, jotka ovat tapahtuneet sinussa, olisivat tapahtuneet Sodomassa, niin se seisoisi vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 24, 'Mutta minä sanon teille: Sodoman maan on tuomiopäivänä oleva helpompi kuin sinun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 25, 'Siihen aikaan Jeesus johtui puhumaan sanoen: \"Minä ylistän sinua, Isä, taivaan ja maan Herra, että olet salannut nämä viisailta ja ymmärtäväisiltä ja ilmoittanut ne lapsenmielisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 26, 'Niin, Isä, sillä näin on sinulle hyväksi näkynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 27, 'Kaikki on minun Isäni antanut minun haltuuni, eikä kukaan muu tunne Poikaa kuin Isä, eikä Isää tunne kukaan muu kuin Poika ja se, kenelle Poika tahtoo hänet ilmoittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 28, 'Tulkaa minun tyköni, kaikki työtätekeväiset ja raskautetut, niin minä annan teille levon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 29, 'Ottakaa minun ikeeni päällenne ja oppikaa minusta, sillä minä olen hiljainen ja nöyrä sydämeltä; niin te löydätte levon sielullenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 11, 30, 'Sillä minun ikeeni on sovelias, ja minun kuormani on keveä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 1, 'Siihen aikaan Jeesus kulki sapattina viljavainioiden halki; ja hänen opetuslastensa oli nälkä, ja he rupesivat katkomaan tähkäpäitä ja syömään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 2, 'Mutta kun fariseukset sen näkivät, sanoivat he hänelle: \"Katso, sinun opetuslapsesi tekevät, mitä ei ole lupa tehdä sapattina\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 3, 'Niin hän sanoi heille: \"Ettekö ole lukeneet, mitä Daavid teki, kun hänen ja hänen seuralaistensa oli nälkä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 4, 'kuinka hän meni Jumalan huoneeseen, ja kuinka he söivät näkyleivät, joita ei hänen eikä hänen seuralaistensa ollut lupa syödä, vaan ainoastaan pappien?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 5, 'Tai ettekö ole lukeneet laista, että papit sapattina pyhäkössä rikkovat sapatin ja ovat kuitenkin syyttömät?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 6, 'Mutta minä sanon teille: tässä on se, joka on pyhäkköä suurempi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 7, 'Mutta jos tietäisitte, mitä tämä on: \'Laupeutta minä tahdon enkä uhria\', niin te ette tuomitsisi syyttömiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 8, 'Sillä Ihmisen Poika on sapatin herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 9, 'Ja hän lähti sieltä ja tuli heidän synagoogaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 10, 'Ja katso, siellä oli mies, jonka käsi oli kuivettunut. Niin he kysyivät häneltä sanoen: \"Onko luvallista sapattina parantaa?\" voidaksensa nostaa syytteen häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 11, 'Niin hän sanoi heille: \"Kuka teistä on se mies, joka ei, jos hänen ainoa lampaansa putoaa sapattina kuoppaan, tartu siihen ja nosta sitä ylös?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 12, 'Kuinka paljon suurempiarvoinen onkaan ihminen kuin lammas! Sentähden on lupa tehdä sapattina hyvää.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 13, 'Sitten hän sanoi miehelle: \"Ojenna kätesi!\" Ja hän ojensi; ja se tuli entiselleen, terveeksi niinkuin toinenkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 14, 'Niin fariseukset lähtivät ulos ja pitivät neuvoa häntä vastaan, surmataksensa hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 15, 'Mutta kun Jeesus huomasi sen, väistyi hän sieltä pois. Ja monet seurasivat häntä, ja hän paransi heidät kaikki,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 16, 'ja hän varoitti vakavasti heitä saattamasta häntä julki;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 17, 'että kävisi toteen, mikä on puhuttu profeetta Esaiaan kautta, joka sanoo:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 18, '\"Katso, minun palvelijani, jonka minä olen valinnut, minun rakkaani, johon minun sieluni on mielistynyt; minä panen Henkeni häneen, ja hän on saattava oikeuden sanomaa pakanoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 19, 'Ei hän riitele eikä huuda, ei hänen ääntänsä kuule kukaan kaduilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 20, 'Särjettyä ruokoa hän ei muserra, ja suitsevaista kynttilänsydäntä hän ei sammuta, kunnes hän saattaa oikeuden voittoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 21, 'Ja hänen nimeensä pakanat panevat toivonsa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 22, 'Silloin tuotiin hänen tykönsä riivattu mies, joka oli sokea ja mykkä, ja hän paransi hänet, niin että mykkä puhui ja näki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 23, 'Ja kaikki kansa hämmästyi ja sanoi: \"Eiköhän tämä ole Daavidin poika?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 24, 'Mutta kun fariseukset sen kuulivat, sanoivat he: \"Tämä ei aja riivaajia ulos kenenkään muun kuin Beelsebulin, riivaajain päämiehen, voimalla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 25, 'Mutta hän tiesi heidän ajatuksensa ja sanoi heille: \"Jokainen valtakunta, joka riitautuu itsensä kanssa, joutuu autioksi, eikä mikään kaupunki tai talo, joka riitautuu itsensä kanssa, pysy pystyssä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 26, 'Jos nyt saatana ajaa ulos saatanan, niin hän on riitautunut itsensä kanssa; kuinka siis hänen valtakuntansa pysyy pystyssä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 27, 'Ja jos minä Beelsebulin voimalla ajan ulos riivaajia, kenenkä voimalla sitten teidän lapsenne ajavat niitä ulos? Niinpä he tulevat olemaan teidän tuomarinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 28, 'Mutta jos minä Jumalan Hengen voimalla ajan ulos riivaajia, niin on Jumalan valtakunta tullut teidän tykönne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 29, 'Taikka kuinka voi kukaan tunkeutua väkevän taloon ja ryöstää hänen tavaroitansa, ellei hän ensin sido sitä väkevää? Vasta sitten hän ryöstää tyhjäksi hänen talonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 30, 'Joka ei ole minun kanssani, se on minua vastaan; ja joka ei minun kanssani kokoa, se hajottaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 31, 'Sentähden minä sanon teille: jokainen synti ja pilkka annetaan ihmisille anteeksi, mutta Hengen pilkkaamista ei anteeksi anneta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 32, 'Ja jos joku sanoo sanan Ihmisen Poikaa vastaan, niin hänelle annetaan anteeksi; mutta jos joku sanoo jotakin Pyhää Henkeä vastaan, niin hänelle ei anteeksi anneta, ei tässä maailmassa eikä tulevassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 33, 'Joko tehkää puu hyväksi ja sen hedelmä hyväksi, tahi tehkää puu huonoksi ja sen hedelmä huonoksi; sillä hedelmästä puu tunnetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 34, 'Te kyykäärmeitten sikiöt, kuinka te saattaisitte hyvää puhua, kun itse olette pahoja? Sillä sydämen kyllyydestä suu puhuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 35, 'Hyvä ihminen tuo hyvän runsaudesta esille hyvää, ja paha ihminen tuo pahan runsaudesta esille pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 36, 'Mutta minä sanon teille: jokaisesta turhasta sanasta, minkä ihmiset puhuvat, pitää heidän tekemän tili tuomiopäivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 37, 'Sillä sanoistasi sinut julistetaan vanhurskaaksi, ja sanoistasi sinut tuomitaan syylliseksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 38, 'Silloin muutamat kirjanoppineista ja fariseuksista vastasivat hänelle sanoen: \"Opettaja, me tahdomme nähdä sinulta merkin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 39, 'Mutta hän vastasi heille ja sanoi: \"Tämä paha ja avionrikkoja sukupolvi tavoittelee merkkiä, mutta sille ei anneta muuta merkkiä kuin profeetta Joonaan merkki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 40, 'Sillä niinkuin Joonas oli meripedon vatsassa kolme päivää ja kolme yötä, niin on myös Ihmisen Poika oleva maan povessa kolme päivää ja kolme yötä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 41, 'Niiniven miehet nousevat tuomiolle yhdessä tämän sukupolven kanssa ja tulevat sille tuomioksi; sillä he tekivät parannuksen Joonaan saarnan vaikutuksesta, ja katso, tässä on enempi kuin Joonas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 42, 'Etelän kuningatar on heräjävä tuomiolle tämän sukupolven kanssa ja tuleva sille tuomioksi; sillä hän tuli maan ääristä kuulemaan Salomon viisautta, ja katso, tässä on enempi kuin Salomo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 43, 'Kun saastainen henki lähtee ihmisestä, kuljeksii se autioita paikkoja ja etsii lepoa, eikä löydä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 44, 'Silloin se sanoo: \'Minä palaan huoneeseeni, josta lähdin\'. Ja kun se tulee, tapaa se huoneen tyhjänä ja lakaistuna ja kaunistettuna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 45, 'Silloin se menee ja ottaa mukaansa seitsemän muuta henkeä, pahempaa kuin se itse, ja ne tulevat sisään ja asuvat siellä. Ja sen ihmisen viimeiset tulevat pahemmiksi kuin ensimmäiset. Niin käy myös tälle pahalle sukupolvelle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 46, 'Hänen vielä puhuessaan kansalle, katso, hänen äitinsä ja veljensä seisoivat ulkona, tahtoen häntä puhutella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 47, 'Niin joku sanoi hänelle: \"Katso, sinun äitisi ja veljesi seisovat ulkona ja tahtovat sinua puhutella\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 48, 'Mutta hän vastasi ja sanoi sille, joka sen hänelle ilmoitti: \"Kuka on minun äitini, ja ketkä ovat minun veljeni?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 49, 'Ja hän ojensi kätensä opetuslastensa puoleen ja sanoi: \"Katso, minun äitini ja veljeni!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 12, 50, 'Sillä jokainen, joka tekee minun taivaallisen Isäni tahdon, on minun veljeni ja sisareni ja äitini.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 1, 'Sinä päivänä Jeesus lähti asunnostaan ja istui järven rannalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 2, 'Ja hänen tykönsä kokoontui paljon kansaa, jonka tähden hän astui venheeseen ja istuutui, ja kaikki kansa seisoi rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 3, 'Ja hän puhui heille paljon vertauksilla ja sanoi: \"Katso, kylväjä meni kylvämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 4, 'Ja hänen kylväessään putosivat muutamat siemenet tien oheen, ja linnut tulivat ja söivät ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 5, 'Toiset putosivat kallioperälle, jossa niillä ei ollut paljon maata, ja ne nousivat kohta oraalle, kun niillä ei ollut syvää maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 6, 'Mutta auringon noustua ne paahtuivat, ja kun niillä ei ollut juurta, niin ne kuivettuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 7, 'Toiset taas putosivat orjantappuroihin, ja orjantappurat nousivat ja tukahuttivat ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 8, 'Ja toiset putosivat hyvään maahan ja antoivat sadon, mitkä sata, mitkä kuusikymmentä, mitkä kolmekymmentä jyvää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 9, 'Jolla on korvat, se kuulkoon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 10, 'Niin hänen opetuslapsensa tulivat ja sanoivat hänelle: \"Minkätähden sinä puhut heille vertauksilla?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 11, 'Hän vastasi ja sanoi: \"Sentähden, että teidän on annettu tuntea taivasten valtakunnan salaisuudet, mutta heidän ei ole annettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 12, 'Sillä sille, jolla on, annetaan, ja hänellä on oleva yltäkyllin; mutta siltä, jolla ei ole, otetaan pois sekin, mikä hänellä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 13, 'Sentähden minä puhun heille vertauksilla, että he näkevin silmin eivät näe ja kuulevin korvin eivät kuule, eivätkä ymmärrä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 14, 'Ja heissä käy toteen Esaiaan ennustus, joka sanoo: \'Kuulemalla kuulkaa, älkääkä ymmärtäkö, ja näkemällä nähkää, älkääkä käsittäkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 15, 'Sillä paatunut on tämän kansan sydän, ja korvillaan he työläästi kuulevat, ja silmänsä he ovat ummistaneet, etteivät he näkisi silmillään, eivät kuulisi korvillaan, eivät ymmärtäisi sydämellään eivätkä kääntyisi ja etten minä heitä parantaisi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 16, 'Mutta autuaat ovat teidän silmänne, koska ne näkevät, ja teidän korvanne, koska ne kuulevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 17, 'Sillä totisesti minä sanon teille: monet profeetat ja vanhurskaat ovat halunneet nähdä, mitä te näette, eivätkä ole nähneet, ja kuulla, mitä te kuulette, eivätkä ole kuulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 18, 'Kuulkaa siis te vertaus kylväjästä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 19, 'Kun joku kuulee valtakunnan sanan eikä ymmärrä, niin tulee paha ja tempaa pois sen, mikä hänen sydämeensä kylvettiin. Tämä on se, mikä kylvettiin tien oheen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 20, 'Mikä kallioperälle kylvettiin, on se, joka kuulee sanan ja heti ottaa sen ilolla vastaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 21, 'mutta hänellä ei ole juurta itsessään, vaan hän kestää ainoastaan jonkun aikaa, ja kun tulee ahdistus tai vaino sanan tähden, niin hän heti lankeaa pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 22, 'Mikä taas orjantappuroihin kylvettiin, on se, joka kuulee sanan, mutta tämän maailman huoli ja rikkauden viettelys tukahuttavat sanan, ja hän jää hedelmättömäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 23, 'Mutta mikä hyvään maahan kylvettiin, on se, joka kuulee sanan ja ymmärtää sen ja myös tuottaa hedelmän ja tekee, mikä sata jyvää, mikä kuusikymmentä, mikä kolmekymmentä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 24, 'Toisen vertauksen hän puhui heille sanoen: \"Taivasten valtakunta on verrattava mieheen, joka kylvi hyvän siemenen peltoonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 25, 'Mutta ihmisten nukkuessa hänen vihamiehensä tuli ja kylvi lustetta nisun sekaan ja meni pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 26, 'Ja kun laiho kasvoi ja teki hedelmää, silloin lustekin tuli näkyviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 27, 'Niin perheenisännän palvelijat tulivat ja sanoivat hänelle: \'Herra, etkö kylvänyt peltoosi hyvää siementä? Mistä siihen sitten on tullut lustetta?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 28, 'Hän sanoi heille: \'Sen on vihamies tehnyt\'. Niin palvelijat sanoivat hänelle: \'Tahdotko, että menemme ja kokoamme sen?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 29, 'Mutta hän sanoi: \'En, ettette lustetta kootessanne nyhtäisi sen mukana nisuakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 30, 'Antakaa molempain kasvaa yhdessä elonleikkuuseen asti; ja elonaikana minä sanon leikkuumiehille: Kootkaa ensin luste ja sitokaa se kimppuihin poltettavaksi, mutta nisu korjatkaa minun aittaani.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 31, 'Vielä toisen vertauksen hän puhui heille sanoen: \"Taivasten valtakunta on sinapinsiemenen kaltainen, jonka mies otti ja kylvi peltoonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 32, 'Se on kaikista siemenistä pienin, mutta kun se on kasvanut, on se suurin vihanneskasveista ja tulee puuksi, niin että taivaan linnut tulevat ja tekevät pesänsä sen oksille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 33, 'Taas toisen vertauksen hän puhui heille: \"Taivasten valtakunta on hapatuksen kaltainen, jonka nainen otti ja sekoitti kolmeen vakalliseen jauhoja, kunnes kaikki happani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 34, 'Tämän kaiken Jeesus puhui kansalle vertauksilla, ja ilman vertausta hän ei puhunut heille mitään;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 35, 'että kävisi toteen, mikä on puhuttu profeetan kautta, joka sanoo: \"Minä avaan suuni vertauksiin, minä tuon ilmi sen, mikä on ollut salassa maailman perustamisesta asti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 36, 'Sitten hän laski luotaan kansanjoukot ja meni asuntoonsa. Ja hänen opetuslapsensa tulivat hänen tykönsä ja sanoivat: \"Selitä meille vertaus pellon lusteesta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 37, 'Niin hän vastasi ja sanoi: \"Hyvän siemenen kylväjä on Ihmisen Poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 38, 'Pelto on maailma; hyvä siemen ovat valtakunnan lapset, mutta lusteet ovat pahan lapset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 39, 'Vihamies, joka ne kylvi, on perkele; elonaika on maailman loppu, ja leikkuumiehet ovat enkelit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 40, 'Niinkuin lusteet kootaan ja tulessa poltetaan, niin on tapahtuva maailman lopussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 41, 'Ihmisen Poika lähettää enkelinsä, ja he kokoavat hänen valtakunnastaan kaikki, jotka ovat pahennukseksi ja jotka tekevät laittomuutta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 42, 'ja heittävät heidät tuliseen pätsiin; siellä on oleva itku ja hammasten kiristys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 43, 'Silloin vanhurskaat loistavat Isänsä valtakunnassa niinkuin aurinko. Jolla on korvat, se kuulkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 44, 'Taivasten valtakunta on peltoon kätketyn aarteen kaltainen, jonka mies löysi ja kätki; ja siitä iloissaan hän meni ja myi kaikki, mitä hänellä oli, ja osti sen pellon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 45, 'Vielä taivasten valtakunta on kuin kauppias, joka etsi kalliita helmiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 46, 'ja löydettyään yhden kallisarvoisen helmen hän meni ja myi kaikki, mitä hänellä oli, ja osti sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 47, 'Vielä taivasten valtakunta on nuotan kaltainen, joka heitettiin mereen ja kokosi kaikkinaisia kaloja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 48, 'Ja kun se tuli täyteen, vetivät he sen rannalle, istuutuivat ja kokosivat hyvät astioihin, mutta kelvottomat he viskasivat pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 49, 'Näin on käyvä maailman lopussa; enkelit lähtevät ja erottavat pahat vanhurskaista');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 50, 'ja heittävät heidät tuliseen pätsiin; siellä on oleva itku ja hammasten kiristys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 51, 'Oletteko ymmärtäneet tämän kaiken?\" He vastasivat hänelle: \"Olemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 52, 'Ja hän sanoi heille: \"Niin on jokainen kirjanoppinut, joka on tullut taivasten valtakunnan opetuslapseksi, perheenisännän kaltainen, joka tuo aarrekammiostaan esille uutta ja vanhaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 53, 'Ja kun Jeesus oli lopettanut nämä vertaukset, lähti hän sieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 54, 'Ja hän tuli kotikaupunkiinsa ja opetti heitä heidän synagoogassaan, niin että he hämmästyivät ja sanoivat: \"Mistä hänellä on tämä viisaus ja nämä voimalliset teot?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 55, 'Eikö tämä ole se rakentajan poika? Eikö hänen äitinsä ole nimeltään Maria ja hänen veljensä Jaakob ja Joosef ja Simon ja Juudas?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 56, 'Ja eivätkö hänen sisarensa ole kaikki meidän parissamme? Mistä sitten hänellä on tämä kaikki?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 57, 'Ja he loukkaantuivat häneen. Mutta Jeesus sanoi heille: \"Ei ole profeetta halveksittu muualla kuin kotikaupungissaan ja kodissaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 13, 58, 'Ja heidän epäuskonsa tähden hän ei tehnyt siellä monta voimallista tekoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 1, 'Siihen aikaan neljännysruhtinas Herodes kuuli maineen Jeesuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 2, 'Ja hän sanoi palvelijoilleen: \"Se on Johannes Kastaja; hän on noussut kuolleista, ja sentähden nämä voimat hänessä vaikuttavat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 3, 'Sillä Herodes oli ottanut Johanneksen kiinni ja sitonut hänet ja pannut vankeuteen veljensä Filippuksen vaimon, Herodiaan, tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 4, 'Sillä Johannes oli sanonut hänelle: \"Sinun ei ole lupa pitää häntä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 5, 'Ja Herodes olisi tahtonut tappaa Johanneksen, mutta pelkäsi kansaa, sillä he pitivät häntä profeettana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 6, 'Mutta kun Herodeksen syntymäpäivä tuli, tanssi Herodiaan tytär heidän edessään, ja se miellytti Herodesta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 7, 'sentähden hän valalla vannoen lupasi antaa hänelle, mitä ikinä hän anoisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 8, 'Niin hän äitinsä yllytyksestä sanoi: \"Anna tuoda minulle tänne lautasella Johannes Kastajan pää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 9, 'Silloin kuningas tuli murheelliseksi, mutta valansa ja pöytävierasten tähden hän käski antaa sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 10, 'Ja hän lähetti lyömään Johannekselta pään poikki vankilassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 11, 'Ja hänen päänsä tuotiin lautasella ja annettiin tytölle; ja tämä vei sen äidilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 12, 'Ja hänen opetuslapsensa tulivat ja ottivat hänen ruumiinsa ja hautasivat hänet; ja he menivät ja ilmoittivat asian Jeesukselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 13, 'Kun Jeesus sen kuuli, lähti hän sieltä venheellä autioon paikkaan, yksinäisyyteen. Ja tämän kuultuaan kansa meni jalkaisin kaupungeista hänen jälkeensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 14, 'Ja astuessaan maihin Jeesus näki paljon kansaa, ja hänen kävi heitä sääliksi, ja hän paransi heidän sairaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 15, 'Mutta kun ilta tuli, menivät hänen opetuslapsensa hänen tykönsä ja sanoivat: \"Tämä paikka on autio, ja päivä on jo pitkälle kulunut; laske siis kansa luotasi, että he menisivät kyliin ostamaan itsellensä ruokaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 16, 'Mutta Jeesus sanoi heille: \"Ei heidän tarvitse mennä pois; antakaa te heille syödä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 17, 'He sanoivat hänelle: \"Meillä ei ole täällä muuta kuin viisi leipää ja kaksi kalaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 18, 'Mutta hän sanoi: \"Tuokaa ne tänne minulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 19, 'Ja hän käski kansan asettua ruohikkoon, otti ne viisi leipää ja kaksi kalaa, katsoi ylös taivaaseen ja siunasi, mursi ja antoi leivät opetuslapsillensa, ja opetuslapset antoivat kansalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 20, 'Ja kaikki söivät ja tulivat ravituiksi. Sitten he keräsivät jääneet palaset, kaksitoista täyttä vakallista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 21, 'Ja niitä, jotka aterioivat, oli noin viisituhatta miestä, paitsi naisia ja lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 22, 'Ja kohta hän vaati opetuslapsiansa astumaan venheeseen ja kulkemaan edeltä toiselle rannalle, sillä aikaa kuin hän laski kansan luotansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 23, 'Ja laskettuaan kansan hän nousi vuorelle yksinäisyyteen, rukoilemaan. Ja kun ilta tuli, oli hän siellä yksinänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 24, 'Mutta venhe oli jo monen vakomitan päässä maasta, aaltojen ahdistamana, sillä tuuli oli vastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 25, 'Ja neljännellä yövartiolla Jeesus tuli heidän tykönsä kävellen järven päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 26, 'Kun opetuslapset näkivät hänen kävelevän järven päällä, peljästyivät he ja sanoivat: \"Se on aave\", ja huusivat pelosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 27, 'Mutta Jeesus puhutteli heitä kohta ja sanoi: \"Olkaa turvallisella mielellä, minä se olen; älkää peljätkö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 28, 'Pietari vastasi hänelle ja sanoi: \"Jos se olet sinä, Herra, niin käske minun tulla tykösi vettä myöten\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 29, 'Hän sanoi: \"Tule\". Ja Pietari astui ulos venheestä ja käveli vetten päällä mennäkseen Jeesuksen tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 30, 'Mutta nähdessään, kuinka tuuli, hän peljästyi ja rupesi vajoamaan ja huusi sanoen: \"Herra, auta minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 31, 'Niin Jeesus kohta ojensi kätensä, tarttui häneen ja sanoi hänelle: \"Sinä vähäuskoinen, miksi epäilit?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 32, 'Ja kun he olivat astuneet venheeseen, asettui tuuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 33, 'Niin venheessä-olijat kumarsivat häntä ja sanoivat: \"Totisesti sinä olet Jumalan Poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 34, 'Ja kuljettuaan yli he tulivat maihin Gennesaretiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 35, 'Ja kun sen paikkakunnan miehet tunsivat hänet, lähettivät he sanan kaikkeen ympäristöön, ja hänen tykönsä tuotiin kaikki sairaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 14, 36, 'Ja he pyysivät häneltä, että vain saisivat koskea hänen vaippansa tupsuun; ja kaikki, jotka koskivat, paranivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 1, 'Silloin tuli fariseuksia ja kirjanoppineita Jerusalemista Jeesuksen luo, ja he sanoivat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 2, '\"Miksi sinun opetuslapsesi rikkovat vanhinten perinnäissääntöä? Sillä he eivät pese käsiään ruvetessaan aterialle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 3, 'Mutta hän vastasi ja sanoi heille: \"Miksi te itse rikotte Jumalan käskyn perinnäissääntönne tähden?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 4, 'Sillä Jumala on sanonut: \'Kunnioita isääsi ja äitiäsi\', ja: \'Joka kiroaa isäänsä tai äitiänsä, sen pitää kuolemalla kuoleman\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 5, 'Mutta te sanotte: Joka sanoo isälleen tai äidilleen: \'Se, minkä sinä olisit ollut minulta saapa, on annettu uhrilahjaksi\', sen ei tarvitse kunnioittaa isäänsä eikä äitiänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 6, 'Ja niin te olette tehneet Jumalan sanan tyhjäksi perinnäissääntönne tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 7, 'Te ulkokullatut, oikein teistä Esaias ennusti, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 8, '\'Tämä kansa kunnioittaa minua huulillaan, mutta heidän sydämensä on minusta kaukana,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 9, 'mutta turhaan he palvelevat minua opettaen oppeja, jotka ovat ihmiskäskyjä\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 10, 'Ja hän kutsui kansan tykönsä ja sanoi heille: \"Kuulkaa ja ymmärtäkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 11, 'Ei saastuta ihmistä se, mikä menee suusta sisään; vaan mikä suusta käy ulos, se saastuttaa ihmisen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 12, 'Silloin opetuslapset tulivat ja sanoivat hänelle: \"Tiedätkö, että fariseukset loukkaantuivat kuullessaan tuon puheen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 13, 'Mutta hän vastasi ja sanoi: \"Jokainen istutus, jota minun taivaallinen Isäni ei ole istuttanut, on juurineen revittävä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 14, 'Älkää heistä välittäkö: he ovat sokeita sokeain taluttajia; mutta jos sokea sokeaa taluttaa, niin he molemmat kuoppaan lankeavat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 15, 'Niin Pietari vastasi ja sanoi hänelle: \"Selitä meille tämä vertaus\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 16, 'Mutta Jeesus sanoi: \"Vieläkö tekin olette ymmärtämättömiä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 17, 'Ettekö käsitä, että kaikki, mikä käy suusta sisään, menee vatsaan ja ulostuu?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 18, 'Mutta mikä käy suusta ulos, se tulee sydämestä, ja se saastuttaa ihmisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 19, 'Sillä sydämestä lähtevät pahat ajatukset, murhat, aviorikokset, haureudet, varkaudet, väärät todistukset, jumalanpilkkaamiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 20, 'Nämä ihmisen saastuttavat; mutta pesemättömin käsin syöminen ei saastuta ihmistä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 21, 'Ja Jeesus lähti sieltä ja vetäytyi Tyyron ja Siidonin tienoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 22, 'Ja katso, kanaanilainen vaimo tuli niiltä seuduilta ja huusi sanoen: \"Herra, Daavidin poika, armahda minua. Riivaaja vaivaa kauheasti minun tytärtäni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 23, 'Mutta hän ei vastannut hänelle sanaakaan. Niin hänen opetuslapsensa tulivat ja rukoilivat häntä sanoen: \"Päästä hänet menemään, sillä hän huutaa meidän jälkeemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 24, 'Hän vastasi ja sanoi: \"Minua ei ole lähetetty muitten kuin Israelin huoneen kadonneitten lammasten tykö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 25, 'Mutta vaimo tuli ja kumarsi häntä ja sanoi: \"Herra, auta minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 26, 'Mutta hän vastasi ja sanoi: \"Ei ole soveliasta ottaa lasten leipää ja heittää penikoille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 27, 'Mutta vaimo sanoi: \"Niin, Herra; mutta syöväthän penikatkin niitä muruja, jotka heidän herrainsa pöydältä putoavat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 28, 'Silloin Jeesus vastasi ja sanoi hänelle: \"Oi vaimo, suuri on sinun uskosi, tapahtukoon sinulle, niinkuin tahdot\". Ja hänen tyttärensä oli siitä hetkestä terve.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 29, 'Ja Jeesus lähti sieltä ja tuli Galilean järven rannalle; ja hän nousi vuorelle ja istui sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 30, 'Ja hänen tykönsä tuli paljon kansaa, ja he toivat mukanaan rampoja, raajarikkoja, sokeita, mykkiä ja paljon muita, ja laskivat heidät hänen jalkojensa juureen; ja hän paransi heidät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 31, 'niin että kansa ihmetteli nähdessään mykkäin puhuvan, raajarikkojen olevan terveitä, rampojen kävelevän ja sokeain näkevän; ja he ylistivät Israelin Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 32, 'Ja Jeesus kutsui opetuslapsensa tykönsä ja sanoi: \"Minun käy sääliksi kansaa, sillä he ovat jo kolme päivää olleet minun tykönäni, eikä heillä ole mitään syötävää; enkä minä tahdo laskea heitä syömättä menemään, etteivät nääntyisi matkalla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 33, 'Niin opetuslapset sanoivat hänelle: \"Mistä me saamme täällä erämaassa niin paljon leipää, että voimme ravita noin suuren kansanjoukon?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 34, 'Jeesus sanoi heille: \"Montako leipää teillä on?\" He sanoivat: \"Seitsemän, ja muutamia kalasia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 35, 'Niin hän käski kansan asettua maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 36, 'Ja hän otti ne seitsemän leipää ja kalat, kiitti, mursi ja antoi opetuslapsillensa, ja opetuslapset antoivat kansalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 37, 'Ja kaikki söivät ja tulivat ravituiksi. Sitten he keräsivät jääneet palaset, seitsemän täyttä vasullista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 38, 'Ja niitä, jotka aterioivat, oli neljätuhatta miestä, paitsi naisia ja lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 15, 39, 'Ja laskettuaan kansan tyköänsä hän astui venheeseen ja meni Magadanin alueelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 1, 'Ja fariseukset ja saddukeukset tulivat hänen luoksensa ja kiusasivat häntä pyytäen häntä näyttämään heille merkin taivaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 2, 'Mutta hän vastasi ja sanoi heille: \"Kun ilta tulee, sanotte te: \'Tulee selkeä ilma, sillä taivas ruskottaa\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 3, 'ja aamulla: \'Tänään tulee rajuilma, sillä taivas ruskottaa ja on synkkä\'. Taivaan muodon te osaatte arvioida, mutta aikain merkkejä ette osaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 4, 'Tämä paha ja avionrikkoja sukupolvi tavoittelee merkkiä, mutta sille ei anneta muuta merkkiä kuin Joonaan merkki.\" Ja hän jätti heidät ja meni pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 5, 'Kun opetuslapset saapuivat toiselle rannalle, olivat he unhottaneet ottaa leipää mukaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 6, 'Ja Jeesus sanoi heille: \"Varokaa ja kavahtakaa fariseusten ja saddukeusten hapatusta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 7, 'Niin he puhuivat keskenään sanoen: \"Emme ottaneet leipää mukaamme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 8, 'Mutta kun Jeesus sen huomasi, sanoi hän: \"Te vähäuskoiset, mitä puhutte keskenänne siitä, ettei teillä ole leipää mukananne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 9, 'Ettekö vielä käsitä? Ja ettekö muista niitä viittä leipää viidelletuhannelle ja kuinka monta vakallista otitte talteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 10, 'ettekä niitä seitsemää leipää neljälletuhannelle ja kuinka monta vasullista otitte talteen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 11, 'Kuinka te ette käsitä, etten minä puhunut teille leivästä? Vaan kavahtakaa fariseusten ja saddukeusten hapatusta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 12, 'Silloin he ymmärsivät, ettei hän käskenyt kavahtamaan leivän hapatusta, vaan fariseusten ja saddukeusten oppia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 13, 'Kun Jeesus tuli Filippuksen Kesarean tienoille, kysyi hän opetuslapsiltaan sanoen: \"Kenen ihmiset sanovat Ihmisen Pojan olevan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 14, 'Niin he sanoivat: \"Muutamat Johannes Kastajan, toiset Eliaan, toiset taas Jeremiaan tahi jonkun muun profeetoista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 15, 'Hän sanoi heille: \"Kenenkä te sanotte minun olevan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 16, 'Simon Pietari vastasi ja sanoi: \"Sinä olet Kristus, elävän Jumalan Poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 17, 'Jeesus vastasi ja sanoi hänelle: \"Autuas olet sinä, Simon, Joonaan poika, sillä ei liha eikä veri ole sitä sinulle ilmoittanut, vaan minun Isäni, joka on taivaissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 18, 'Ja minä sanon sinulle: sinä olet Pietari, ja tälle kalliolle minä rakennan seurakuntani, ja tuonelan portit eivät sitä voita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 19, 'Minä olen antava sinulle taivasten valtakunnan avaimet, ja minkä sinä sidot maan päällä, se on oleva sidottu taivaissa, ja minkä sinä päästät maan päällä, se on oleva päästetty taivaissa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 20, 'Silloin hän varoitti vakavasti opetuslapsiaan kenellekään sanomasta, että hän on Kristus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 21, 'Siitä lähtien Jeesus alkoi ilmoittaa opetuslapsilleen, että hänen piti menemän Jerusalemiin ja kärsimän paljon vanhimmilta ja ylipapeilta ja kirjanoppineilta ja tuleman tapetuksi ja kolmantena päivänä nouseman ylös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 22, 'Silloin Pietari otti hänet erilleen ja rupesi nuhtelemaan häntä sanoen: \"Jumala varjelkoon, Herra, älköön se sinulle tapahtuko\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 23, 'Mutta hän kääntyi ja sanoi Pietarille: \"Mene pois minun edestäni, saatana; sinä olet minulle pahennukseksi, sillä sinä et ajattele sitä, mikä on Jumalan, vaan sitä, mikä on ihmisten\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 24, 'Silloin Jeesus sanoi opetuslapsillensa: \"Jos joku tahtoo minun perässäni kulkea, hän kieltäköön itsensä ja ottakoon ristinsä ja seuratkoon minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 25, 'Sillä joka tahtoo pelastaa elämänsä, hän kadottaa sen, mutta joka kadottaa elämänsä minun tähteni, hän löytää sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 26, 'Sillä mitä se hyödyttää ihmistä, vaikka hän voittaisi omaksensa koko maailman, mutta saisi sielullensa vahingon? Taikka mitä voi ihminen antaa sielunsa lunnaiksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 27, 'Sillä Ihmisen Poika on tuleva Isänsä kirkkaudessa enkeliensä kanssa, ja silloin hän maksaa kullekin hänen tekojensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 16, 28, 'Totisesti minä sanon teille: tässä seisovien joukossa on muutamia, jotka eivät maista kuolemaa, ennenkuin näkevät Ihmisen Pojan tulevan kuninkuudessaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 1, 'Ja kuuden päivän kuluttua Jeesus otti mukaansa Pietarin sekä Jaakobin ja hänen veljensä Johanneksen ja vei heidät korkealle vuorelle, yksinäisyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 2, 'Ja hänen muotonsa muuttui heidän edessään, ja hänen kasvonsa loistivat niinkuin aurinko, ja hänen vaatteensa tulivat valkoisiksi niinkuin valo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 3, 'Ja katso, heille ilmestyivät Mooses ja Elias, jotka puhuivat hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 4, 'Niin Pietari rupesi puhumaan ja sanoi Jeesukselle: \"Herra, meidän on tässä hyvä olla; jos tahdot, niin minä teen tähän kolme majaa, sinulle yhden ja Moosekselle yhden ja Eliaalle yhden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 5, 'Hänen vielä puhuessaan, katso, heidät varjosi valoisa pilvi; ja katso, pilvestä kuului ääni, joka sanoi: \"Tämä on minun rakas Poikani, johon minä olen mielistynyt; kuulkaa häntä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 6, 'Kun opetuslapset sen kuulivat, lankesivat he kasvoilleen ja peljästyivät kovin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 7, 'Niin Jeesus tuli heidän tykönsä, koski heihin ja sanoi: \"Nouskaa, älkääkä peljätkö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 8, 'Ja kun he nostivat silmänsä, eivät he nähneet ketään muuta kuin Jeesuksen yksinään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 9, 'Ja heidän kulkiessaan alas vuorelta Jeesus varoitti heitä sanoen: \"Älkää kenellekään kertoko tätä näkyä, ennenkuin Ihmisen Poika on noussut kuolleista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 10, 'Ja hänen opetuslapsensa kysyivät häneltä sanoen: \"Miksi sitten kirjanoppineet sanovat, että Eliaan pitää tulla ensin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 11, 'Jeesus vastasi ja sanoi: \"Elias tosin tulee ja asettaa kaikki kohdalleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 12, 'Mutta minä sanon teille, että Elias on jo tullut. Mutta he eivät tunteneet häntä, vaan tekivät hänelle, mitä tahtoivat. Samoin myös Ihmisen Poika saa kärsiä heiltä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 13, 'Silloin opetuslapset ymmärsivät hänen puhuneen heille Johannes Kastajasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 14, 'Ja kun he saapuivat kansan luo, tuli hänen tykönsä muuan mies, polvistui hänen eteensä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 15, 'ja sanoi: \"Herra, armahda minun poikaani, sillä hän on kuunvaihetautinen ja kärsii kovin; usein hän kaatuu, milloin tuleen, milloin veteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 16, 'Ja minä toin hänet sinun opetuslastesi tykö, mutta he eivät voineet häntä parantaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 17, 'Niin Jeesus vastasi ja sanoi: \"Voi sinä epäuskoinen ja nurja sukupolvi, kuinka kauan minun täytyy olla teidän kanssanne? Kuinka kauan kärsiä teitä? Tuokaa hänet tänne minun tyköni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 18, 'Ja Jeesus nuhteli riivaajaa, ja se lähti pojasta, ja poika oli siitä hetkestä terve.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 19, 'Sitten opetuslapset menivät Jeesuksen tykö eriksensä ja sanoivat: \"Miksi emme me voineet ajaa sitä ulos?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 20, 'Niin hän sanoi heille: \"Teidän epäuskonne tähden; sillä totisesti minä sanon teille: jos teillä olisi uskoa sinapinsiemenenkään verran, niin te voisitte sanoa tälle vuorelle: \'Siirry täältä tuonne\', ja se siirtyisi, eikä mikään olisi teille mahdotonta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 21, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 22, 'Ja kun he yhdessä vaelsivat Galileassa, sanoi Jeesus heille: \"Ihmisen Poika annetaan ihmisten käsiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 23, 'ja he tappavat hänet, ja kolmantena päivänä hän nousee ylös\". Ja he tulivat kovin murheellisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 24, 'Ja kun he saapuivat Kapernaumiin, tulivat temppeliveron kantajat Pietarin luo ja sanoivat: \"Eikö teidän opettajanne maksa temppeliveroa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 25, 'Hän sanoi: \"Maksaa\". Ja kun hän tuli huoneeseen, kysyi Jeesus häneltä ensi sanaksi: \"Mitä arvelet, Simon? Keiltä maan kuninkaat ottavat tullia tai veroa? Lapsiltaanko vai vierailta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 26, 'Ja kun hän vastasi: \"Vierailta\", sanoi Jeesus hänelle: \"Lapset ovat siis vapaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 17, 27, 'Mutta ettemme heitä loukkaisi, niin mene ja heitä onki järveen. Ota sitten ensiksi saamasi kala, ja kun avaat sen suun, löydät hopearahan. Ota se ja anna heille minun puolestani ja omasta puolestasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 1, 'Sillä hetkellä opetuslapset tulivat Jeesuksen tykö ja sanoivat: \"Kuka on suurin taivasten valtakunnassa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 2, 'Niin hän kutsui tykönsä lapsen, asetti sen heidän keskellensä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 3, 'ja sanoi: \"Totisesti minä sanon teille: ellette käänny ja tule lasten kaltaisiksi, ette pääse taivasten valtakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 4, 'Sentähden, joka nöyrtyy tämän lapsen kaltaiseksi, se on suurin taivasten valtakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 5, 'Ja joka ottaa tykönsä yhden tämänkaltaisen lapsen minun nimeeni, se ottaa tykönsä minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 6, 'Mutta joka viettelee yhden näistä pienistä, jotka uskovat minuun, sen olisi parempi, että myllynkivi ripustettaisiin hänen kaulaansa ja hänet upotettaisiin meren syvyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 7, 'Voi maailmaa viettelysten tähden! Viettelysten täytyy kyllä tulla; mutta voi sitä ihmistä, jonka kautta viettelys tulee!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 8, 'Mutta jos sinun kätesi tai jalkasi viettelee sinua, hakkaa se poikki ja heitä luotasi; parempi on sinulle, että käsipuolena tai jalkapuolena pääset elämään sisälle, kuin että sinut, molemmat kädet tai molemmat jalat tallella, heitetään iankaikkiseen tuleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 9, 'Ja jos sinun silmäsi viettelee sinua, repäise se pois ja heitä luotasi; parempi on sinun silmäpuolena mennä elämään sisälle, kuin että sinut, molemmat silmät tallella, heitetään helvetin tuleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 10, 'Katsokaa, ettette halveksu yhtäkään näistä pienistä; sillä minä sanon teille, että heidän enkelinsä taivaissa näkevät aina minun Isäni kasvot, joka on taivaissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 11, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 12, 'Mitä arvelette? Jos jollakin ihmisellä on sata lammasta ja yksi niistä eksyy, eikö hän jätä niitä yhdeksääkymmentä yhdeksää vuorille ja mene etsimään eksynyttä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 13, 'Ja jos hän sen löytää, totisesti minä sanon teille: hän iloitsee enemmän siitä kuin niistä yhdeksästäkymmenestä yhdeksästä, jotka eivät olleet eksyneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 14, 'Niin ei myöskään teidän taivaallisen Isänne tahto ole, että yksikään näistä pienistä joutuisi kadotukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 15, 'Mutta jos veljesi rikkoo sinua vastaan, niin mene ja nuhtele häntä kahdenkesken; jos hän sinua kuulee, niin olet voittanut veljesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 16, 'Mutta jos hän ei sinua kuule, niin ota vielä yksi tai kaksi kanssasi, \'että jokainen asia vahvistettaisiin kahden tai kolmen todistajan sanalla\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 17, 'Mutta jos hän ei kuule heitä, niin ilmoita seurakunnalle. Mutta jos hän ei seurakuntaakaan kuule, niin olkoon hän sinulle, niinkuin olisi pakana ja publikaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 18, 'Totisesti minä sanon teille: kaikki, minkä te sidotte maan päällä, on oleva sidottu taivaassa, ja kaikki, minkä te päästätte maan päällä, on oleva päästetty taivaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 19, 'Vielä minä sanon teille: jos kaksi teistä maan päällä keskenään sopii mistä asiasta tahansa, että he sitä anovat, niin he saavat sen minun Isältäni, joka on taivaissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 20, 'Sillä missä kaksi tahi kolme on kokoontunut minun nimeeni, siinä minä olen heidän keskellänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 21, 'Silloin Pietari meni hänen tykönsä ja sanoi hänelle: \"Herra, kuinka monta kertaa minun on annettava anteeksi veljelleni, joka rikkoo minua vastaan? Ihanko seitsemän kertaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 22, 'Jeesus vastasi hänelle: \"Minä sanon sinulle: ei seitsemän kertaa, vaan seitsemänkymmentä kertaa seitsemän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 23, 'Sentähden taivasten valtakunta on verrattava kuninkaaseen, joka vaati palvelijoiltansa tiliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 24, 'Ja kun hän rupesi tilintekoon, tuotiin hänen eteensä eräs, joka oli hänelle velkaa kymmenentuhatta leiviskää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 25, 'Mutta kun tällä ei ollut, millä maksaa, niin hänen herransa määräsi myytäväksi hänet ja hänen vaimonsa ja lapsensa ja kaikki, mitä hänellä oli, ja velan maksettavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 26, 'Silloin palvelija lankesi maahan ja rukoili häntä sanoen: \'Ole pitkämielinen minua kohtaan, niin minä maksan sinulle kaikki\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 27, 'Niin herran kävi sääliksi sitä palvelijaa, ja hän päästi hänet ja antoi hänelle velan anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 28, 'Mutta mentyään ulos se palvelija tapasi erään kanssapalvelijoistaan, joka oli hänelle velkaa sata denaria; ja hän tarttui häneen, kuristi häntä kurkusta ja sanoi: \'Maksa, minkä olet velkaa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 29, 'Niin hänen kanssapalvelijansa lankesi maahan ja pyysi häntä sanoen: \'Ole pitkämielinen minua kohtaan, niin minä maksan sinulle\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 30, 'Mutta hän ei tahtonut, vaan meni ja heitti hänet vankeuteen, kunnes hän maksaisi velkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 31, 'Kun nyt hänen kanssapalvelijansa näkivät, mitä tapahtui, tulivat he kovin murheellisiksi ja menivät ja ilmoittivat herrallensa kaiken, mitä oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 32, 'Silloin hänen herransa kutsui hänet eteensä ja sanoi hänelle: \'Sinä paha palvelija! Minä annoin sinulle anteeksi kaiken sen velan, koska sitä minulta pyysit;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 33, 'eikö sinunkin olisi pitänyt armahtaa kanssapalvelijaasi, niinkuin minäkin sinua armahdin?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 34, 'Ja hänen herransa vihastui ja antoi hänet vanginvartijan käsiin, kunnes hän maksaisi kaiken, minkä oli hänelle velkaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 18, 35, 'Näin myös minun taivaallinen Isäni tekee teille, ellette anna kukin veljellenne sydämestänne anteeksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 1, 'Ja kun Jeesus oli lopettanut nämä puheet, lähti hän Galileasta ja kulki Jordanin tuota puolta Juudean alueelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 2, 'Ja suuri kansan paljous seurasi häntä, ja hän paransi heitä siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 3, 'Ja fariseuksia tuli hänen luoksensa, ja he kiusasivat häntä sanoen: \"Onko miehen lupa hyljätä vaimonsa mistä syystä tahansa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 4, 'Hän vastasi ja sanoi: \"Ettekö ole lukeneet, että Luoja jo alussa \'loi heidät mieheksi ja naiseksi\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 5, 'ja sanoi: \'Sentähden mies luopukoon isästänsä ja äidistänsä ja liittyköön vaimoonsa, ja ne kaksi tulevat yhdeksi lihaksi\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 6, 'Niin eivät he enää ole kaksi, vaan yksi liha. Minkä siis Jumala on yhdistänyt, sitä älköön ihminen erottako.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 7, 'He sanoivat hänelle: \"Miksi sitten Mooses käski antaa erokirjan ja hyljätä hänet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 8, 'Hän sanoi heille: \"Teidän sydämenne kovuuden tähden Mooses salli teidän hyljätä vaimonne, mutta alusta ei niin ollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 9, 'Mutta minä sanon teille: joka hylkää vaimonsa muun kuin huoruuden tähden ja nai toisen, se tekee huorin; ja joka nai hyljätyn, se tekee huorin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 10, 'Opetuslapset sanoivat hänelle: \"Jos miehen on näin laita vaimoonsa nähden, niin ei ole hyvä naida\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 11, 'Mutta hän sanoi heille: \"Ei tämä sana kaikkiin sovellu, vaan ainoastaan niihin, joille se on suotu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 12, 'Sillä on niitä, jotka syntymästään, äitinsä kohdusta saakka, ovat avioon kelpaamattomia, ja on niitä, jotka ihmiset ovat tehneet avioon kelpaamattomiksi, ja niitä, jotka taivasten valtakunnan tähden ovat tehneet itsensä avioon kelpaamattomiksi. Joka voi sen itseensä sovittaa, se sovittakoon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 13, 'Silloin tuotiin hänen tykönsä lapsia, että hän panisi kätensä heidän päälleen ja rukoilisi; mutta opetuslapset nuhtelivat tuojia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 14, 'Niin Jeesus sanoi: \"Antakaa lasten olla, älkääkä estäkö heitä tulemasta minun tyköni, sillä senkaltaisten on taivasten valtakunta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 15, 'Ja hän pani kätensä heidän päälleen ja lähti sieltä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 16, 'Ja katso, eräs mies tuli ja sanoi hänelle: \"Opettaja, mitä hyvää minun pitää tekemän, että minä saisin iankaikkisen elämän?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 17, 'Niin hän sanoi hänelle: \"Miksi kysyt minulta, mikä on hyvää? On ainoastaan yksi, joka on hyvä. Mutta jos tahdot päästä elämään sisälle, niin pidä käskyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 18, 'Hän sanoi hänelle: \"Mitkä?\" Jeesus sanoi: \"Nämä: \'Älä tapa\', \'Älä tee huorin\', \'Älä varasta\', \'Älä sano väärää todistusta\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 19, '\'Kunnioita isääsi ja äitiäsi\', ja: \'Rakasta lähimmäistäsi niinkuin itseäsi\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 20, 'Nuorukainen sanoi hänelle: \"Kaikkia niitä minä olen noudattanut; mitä minulta vielä puuttuu?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 21, 'Jeesus sanoi hänelle: \"Jos tahdot olla täydellinen, niin mene, myy, mitä sinulla on, ja anna köyhille, niin sinulla on oleva aarre taivaissa; ja tule ja seuraa minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 22, 'Mutta kun nuorukainen kuuli tämän sanan, meni hän pois murheellisena, sillä hänellä oli paljon omaisuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 23, 'Silloin Jeesus sanoi opetuslapsillensa: \"Totisesti minä sanon teille: rikkaan on vaikea päästä taivasten valtakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 24, 'Ja vielä minä sanon teille: helpompi on kamelin käydä neulansilmän läpi kuin rikkaan päästä Jumalan valtakuntaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 25, 'Kun opetuslapset sen kuulivat, hämmästyivät he kovin ja sanoivat: \"Kuka sitten voi pelastua?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 26, 'Niin Jeesus katsoi heihin ja sanoi heille: \"Ihmisille se on mahdotonta, mutta Jumalalle on kaikki mahdollista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 27, 'Silloin Pietari vastasi ja sanoi hänelle: \"Katso, me olemme luopuneet kaikesta ja seuranneet sinua; mitä me siitä saamme?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 28, 'Niin Jeesus sanoi heille: \"Totisesti minä sanon teille: siinä uudestisyntymisessä, jolloin Ihmisen Poika istuu kirkkautensa valtaistuimella, saatte tekin, jotka olette minua seuranneet, istua kahdellatoista valtaistuimella ja tuomita Israelin kahtatoista sukukuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 29, 'Ja jokainen, joka on luopunut taloista tai veljistä tai sisarista tai isästä tai äidistä tai lapsista tai pelloista minun nimeni tähden, on saava monin verroin takaisin ja perivä iankaikkisen elämän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 19, 30, 'Mutta monet ensimmäiset tulevat viimeisiksi, ja monet viimeiset ensimmäisiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 1, '\"Sillä taivasten valtakunta on perheenisännän kaltainen, joka varhain aamulla lähti ulos palkkaamaan työmiehiä viinitarhaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 2, 'Ja kun hän oli sopinut työmiesten kanssa denarista päivältä, lähetti hän heidät viinitarhaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 3, 'Ja hän lähti ulos kolmannen hetken vaiheilla ja näki toisia seisomassa torilla joutilaina;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 4, 'ja hän sanoi heille: \'Menkää tekin minun viinitarhaani, ja mikä kohtuus on, sen minä annan teille\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 5, 'Niin he menivät. Taas hän lähti ulos kuudennen ja yhdeksännen hetken vaiheilla ja teki samoin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 6, 'Ja kun hän lähti ulos yhdennentoista hetken vaiheilla, tapasi hän vielä toisia siellä seisomassa; ja hän sanoi heille: \'Miksi seisotte täällä kaiken päivää joutilaina?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 7, 'He sanoivat hänelle: \'Kun ei kukaan ole meitä palkannut\'. Hän sanoi heille: \'Menkää tekin minun viinitarhaani\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 8, 'Mutta kun ilta tuli, sanoi viinitarhan herra tilansa hoitajalle: \'Kutsu työmiehet ja maksa heille palkka, viimeisistä alkaen ensimmäisiin asti\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 9, 'Kun nyt tulivat ne, jotka olivat saapuneet yhdennentoista hetken vaiheilla, saivat he kukin denarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 10, 'Ja kun ensimmäiset tulivat, luulivat he saavansa enemmän; mutta hekin saivat kukin denarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 11, 'Kun he sen saivat, napisivat he perheen isäntää vastaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 12, 'ja sanoivat: \'Nämä viimeiset ovat tehneet työtä vain yhden hetken, ja sinä teit heidät meidän vertaisiksemme, jotka olemme kantaneet päivän kuorman ja helteen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 13, 'Niin hän vastasi eräälle heistä ja sanoi: \'Ystäväni, en minä tee sinulle vääryyttä; etkö sopinut minun kanssani denarista?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 14, 'Ota omasi ja mene. Mutta minä tahdon tälle viimeiselle antaa saman verran kuin sinullekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 15, 'Enkö saa tehdä omallani, mitä tahdon? Vai onko silmäsi nurja sentähden, että minä olen hyvä?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 16, 'Näin viimeiset tulevat ensimmäisiksi ja ensimmäiset viimeisiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 17, 'Ja kun Jeesus lähti kulkemaan ylös Jerusalemiin, otti hän ne kaksitoista erilleen ja sanoi matkalla heille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 18, '\"Katso, me menemme ylös Jerusalemiin, ja Ihmisen Poika annetaan ylipappien ja kirjanoppineitten käsiin, ja he tuomitsevat hänet kuolemaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 19, 'ja antavat hänet pakanoille pilkattavaksi ja ruoskittavaksi ja ristiinnaulittavaksi, ja kolmantena päivänä hän on nouseva ylös\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 20, 'Silloin Sebedeuksen poikain äiti tuli poikineen hänen tykönsä ja kumarsi häntä, aikoen anoa häneltä jotakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 21, 'Niin hän sanoi vaimolle: \"Mitä tahdot?\" Tämä sanoi hänelle: \"Sano, että nämä minun kaksi poikaani saavat istua, toinen sinun oikealla ja toinen vasemmalla puolellasi, sinun valtakunnassasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 22, 'Mutta Jeesus vastasi ja sanoi: \"Te ette tiedä, mitä anotte. Voitteko juoda sen maljan, jonka minä olen juova?\" He sanoivat hänelle: \"Voimme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 23, 'Hän sanoi heille: \"Minun maljani te tosin juotte, mutta minun oikealla ja vasemmalla puolellani istuminen ei ole minun annettavissani, vaan se annetaan niille, joille minun Isäni on sen valmistanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 24, 'Kun ne kymmenen sen kuulivat, närkästyivät he näihin kahteen veljekseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 25, 'Mutta Jeesus kutsui heidät tykönsä ja sanoi: \"Te tiedätte, että kansojen ruhtinaat herroina niitä hallitsevat, ja että mahtavat käyttävät valtaansa niitä kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 26, 'Näin älköön olko teillä keskenänne, vaan joka teidän keskuudessanne tahtoo suureksi tulla, se olkoon teidän palvelijanne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 27, 'ja joka teidän keskuudessanne tahtoo olla ensimmäinen, se olkoon teidän orjanne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 28, 'niinkuin ei Ihmisen Poikakaan tullut palveltavaksi, vaan palvelemaan ja antamaan henkensä lunnaiksi monen edestä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 29, 'Ja heidän lähtiessään Jerikosta seurasi häntä suuri kansan paljous.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 30, 'Ja katso, kaksi sokeaa istui tien vieressä; ja kun he kuulivat, että Jeesus kulki ohitse, huusivat he sanoen: \"Herra, Daavidin poika, armahda meitä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 31, 'Niin kansa nuhteli heitä saadakseen heidät vaikenemaan; mutta he huusivat sitä enemmän sanoen: \"Herra, Daavidin poika, armahda meitä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 32, 'Silloin Jeesus seisahtui ja kutsui heidät tykönsä ja sanoi: \"Mitä tahdotte, että minä teille tekisin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 33, 'He sanoivat hänelle: \"Herra, että meidän silmämme aukenisivat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 20, 34, 'Niin Jeesuksen tuli heitä sääli, ja hän kosketti heidän silmiänsä, ja kohta he saivat näkönsä ja seurasivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 1, 'Ja kun he lähestyivät Jerusalemia ja saapuivat Beetfageen, Öljymäelle, silloin Jeesus lähetti kaksi opetuslasta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 2, 'ja sanoi heille: \"Menkää kylään, joka on edessänne, niin te kohta löydätte aasintamman sidottuna ja varsan sen kanssa; päästäkää ne ja tuokaa minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 3, 'Ja jos joku teille jotakin sanoo, niin vastatkaa: \'Herra tarvitsee niitä\'; ja kohta hän lähettää ne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 4, 'Mutta tämä tapahtui, että kävisi toteen, mikä on puhuttu profeetan kautta, joka sanoo:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 5, '\"Sanokaa tytär Siionille: \'Katso, sinun kuninkaasi tulee sinulle hiljaisena ja ratsastaen aasilla, ikeenalaisen aasin varsalla\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 6, 'Niin opetuslapset menivät ja tekivät, niinkuin Jeesus oli heitä käskenyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 7, 'ja toivat aasintamman varsoineen ja panivat niiden selkään vaatteensa, ja hän istuutui niiden päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 8, 'Ja suurin osa kansasta levitti vaatteensa tielle, ja toiset karsivat oksia puista ja hajottivat tielle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 9, 'Ja kansanjoukot, jotka kulkivat hänen edellään ja jotka seurasivat, huusivat sanoen: \"Hoosianna Daavidin pojalle! Siunattu olkoon hän, joka tulee Herran nimeen. Hoosianna korkeuksissa!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 10, 'Ja kun hän tuli Jerusalemiin, joutui koko kaupunki liikkeelle ja sanoi: \"Kuka tämä on?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 11, 'Niin kansa sanoi: \"Tämä on se profeetta, Jeesus, Galilean Nasaretista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 12, 'Ja Jeesus meni pyhäkköön; ja hän ajoi ulos kaikki, jotka myivät ja ostivat pyhäkössä, ja kaatoi kumoon rahanvaihtajain pöydät ja kyyhkysten myyjäin istuimet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 13, 'Ja hän sanoi heille: \"Kirjoitettu on: \'Minun huoneeni pitää kutsuttaman rukoushuoneeksi\', mutta te teette siitä ryövärien luolan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 14, 'Ja hänen tykönsä pyhäkössä tuli sokeita ja rampoja, ja hän paransi heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 15, 'Mutta kun ylipapit ja kirjanoppineet näkivät ne ihmeet, joita hän teki, ja lapset, jotka huusivat pyhäkössä ja sanoivat: \"Hoosianna Daavidin pojalle\", niin he närkästyivät');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 16, 'ja sanoivat hänelle: \"Kuuletko, mitä nämä sanovat?\" Niin Jeesus sanoi heille: \"Kuulen; ettekö ole koskaan lukeneet: \'Lasten ja imeväisten suusta sinä olet valmistanut itsellesi kiitoksen\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 17, 'Ja hän jätti heidät ja meni ulos kaupungista Betaniaan ja oli siellä yötä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 18, 'Kun hän varhain aamulla palasi kaupunkiin, oli hänen nälkä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 19, 'Ja nähdessään tien vieressä viikunapuun hän meni sen luo, mutta ei löytänyt siitä muuta kuin pelkkiä lehtiä; ja hän sanoi sille: \"Älköön sinusta ikinä enää hedelmää kasvako\". Ja kohta viikunapuu kuivettui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 20, 'Kun opetuslapset tämän näkivät, ihmettelivät he ja sanoivat: \"Kuinka viikunapuu niin äkisti kuivettui?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 21, 'Jeesus vastasi ja sanoi heille: \"Totisesti minä sanon teille: jos teillä olisi uskoa ettekä epäilisi, niin ette ainoastaan voisi tehdä sitä, mikä viikunapuussa tapahtui, vaan vieläpä, jos sanoisitte tälle vuorelle: \'Kohoa ja heittäydy mereen\', niin se tapahtuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 22, 'Ja kaiken, mitä te anotte rukouksessa, uskoen, te saatte.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 23, 'Ja kun hän oli mennyt pyhäkköön, tulivat hänen opettaessaan ylipapit ja kansan vanhimmat hänen luoksensa ja sanoivat: \"Millä vallalla sinä näitä teet? Ja kuka sinulle on antanut tämän vallan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 24, 'Jeesus vastasi ja sanoi heille: \"Minä myös teen teille yhden kysymyksen; jos te minulle siihen vastaatte, niin minäkin sanon teille, millä vallalla minä näitä teen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 25, 'Mistä Johanneksen kaste oli? Taivaastako vai ihmisistä?\" Niin he neuvottelivat keskenänsä sanoen: \"Jos sanomme: \'Taivaasta\', niin hän sanoo meille: \'Miksi ette siis uskoneet häntä?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 26, 'Mutta jos sanomme: \'Ihmisistä\', niin meidän täytyy peljätä kansaa, sillä kaikki pitävät Johannesta profeettana.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 27, 'Ja he vastasivat Jeesukselle ja sanoivat: \"Emme tiedä\". Niin hänkin sanoi heille: \"Niinpä en minäkään sano teille, millä vallalla minä näitä teen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 28, 'Mutta miten teistä on? Miehellä oli kaksi poikaa; ja hän meni ensimmäisen luo ja sanoi: \'Poikani, mene tänään tekemään työtä minun viinitarhaani\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 29, 'Tämä vastasi ja sanoi: \'En tahdo\'; mutta jäljestäpäin hän katui ja meni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 30, 'Niin hän meni toisen luo ja sanoi samoin. Tämä taas vastasi ja sanoi: \'Minä menen, herra\', mutta ei mennytkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 31, 'Kumpi näistä kahdesta teki isänsä tahdon?\" He sanoivat: \"Ensimmäinen\". Jeesus sanoi heille: \"Totisesti minä sanon teille: publikaanit ja portot menevät ennen teitä Jumalan valtakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 32, 'Sillä Johannes tuli teidän tykönne vanhurskauden tietä, ja te ette uskoneet häntä, mutta publikaanit ja portot uskoivat häntä; ja vaikka te sen näitte, ette jäljestäpäinkään katuneet, niin että olisitte häntä uskoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 33, 'Kuulkaa toinen vertaus: Oli perheenisäntä, joka istutti viinitarhan ja teki aidan sen ympärille ja kaivoi siihen viinikuurnan ja rakensi tornin; ja hän vuokrasi sen viinitarhureille ja matkusti muille maille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 34, 'Ja kun hedelmäin aika lähestyi, lähetti hän palvelijoitansa viinitarhurien luokse perimään hänelle tulevat hedelmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 35, 'Mutta viinitarhurit ottivat kiinni hänen palvelijansa; minkä he pieksivät, minkä tappoivat, minkä kivittivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 36, 'Vielä hän lähetti toisia palvelijoita, useampia kuin ensimmäiset; ja näille he tekivät samoin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 37, 'Mutta viimein hän lähetti heidän luokseen poikansa sanoen: \'Minun poikaani he kavahtavat\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 38, 'Mutta kun viinitarhurit näkivät pojan, sanoivat he keskenänsä: \'Tämä on perillinen; tulkaa, tappakaamme hänet, niin me saamme hänen perintönsä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 39, 'Ja he ottivat hänet kiinni ja heittivät ulos viinitarhasta ja tappoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 40, 'Kun viinitarhan herra tulee, mitä hän tekee noille viinitarhureille?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 41, 'He sanoivat hänelle: \"Nuo pahat hän pahoin tuhoaa ja vuokraa viinitarhan toisille viinitarhureille, jotka antavat hänelle hedelmät ajallansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 42, 'Jeesus sanoi heille: \"Ettekö ole koskaan lukeneet kirjoituksista: \'Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi; Herralta tämä on tullut ja on ihmeellinen meidän silmissämme\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 43, 'Sentähden minä sanon teille: Jumalan valtakunta otetaan teiltä pois ja annetaan kansalle, joka tekee sen hedelmiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 44, 'Ja joka tähän kiveen kaatuu, se ruhjoutuu, mutta jonka päälle se kaatuu, sen se murskaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 45, 'Kun ylipapit ja fariseukset kuulivat nämä hänen vertauksensa, ymmärsivät he, että hän puhui heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 21, 46, 'Ja he olisivat tahtoneet ottaa hänet kiinni, mutta pelkäsivät kansaa, koska se piti häntä profeettana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 1, 'Ja Jeesus rupesi taas puhumaan heille vertauksilla ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 2, '\"Taivasten valtakunta on verrattava kuninkaaseen, joka laittoi häät pojallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 3, 'Ja hän lähetti palvelijansa kutsumaan häihin kutsuvieraita, mutta nämä eivät tahtoneet tulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 4, 'Vielä hän lähetti toisia palvelijoita lausuen: \'Sanokaa kutsutuille: Katso, minä olen valmistanut ateriani, minun härkäni ja syöttilääni ovat teurastetut, ja kaikki on valmiina; tulkaa häihin\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 5, 'Mutta he eivät siitä välittäneet, vaan menivät pois, mikä pellolleen, mikä kaupoilleen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 6, 'ja toiset ottivat kiinni hänen palvelijansa, pitelivät pahoin ja tappoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 7, 'Mutta kuningas vihastui ja lähetti sotajoukkonsa ja tuhosi nuo murhamiehet ja poltti heidän kaupunkinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 8, 'Sitten hän sanoi palvelijoillensa: \'Häät ovat valmistetut, mutta kutsutut eivät olleet arvollisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 9, 'Menkää siis teiden risteyksiin ja kutsukaa häihin, keitä tapaatte.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 10, 'Ja palvelijat menivät ulos teille ja kokosivat kaikki, keitä vain tapasivat, sekä pahat että hyvät, ja häähuone tuli täyteen pöytävieraita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 11, 'Mutta kun kuningas meni katsomaan pöytävieraita, näki hän siellä miehen, joka ei ollut puettu häävaatteisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 12, 'Ja hän sanoi hänelle: \'Ystävä, kuinka sinä olet tullut tänne sisälle, vaikka sinulla ei ole häävaatteita?\' Mutta hän jäi sanattomaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 13, 'Silloin kuningas sanoi palvelijoille: \'Sitokaa hänen jalkansa ja kätensä ja heittäkää hänet ulos pimeyteen\'. Siellä on oleva itku ja hammasten kiristys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 14, 'Sillä monet ovat kutsutut, mutta harvat valitut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 15, 'Silloin fariseukset menivät ja neuvottelivat, kuinka saisivat hänet sanoissa solmituksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 16, 'Ja he lähettivät hänen luoksensa opetuslapsensa herodilaisten kanssa sanomaan: \"Opettaja, me tiedämme, että sinä olet totinen ja opetat Jumalan tietä totuudessa, kenestäkään välittämättä, sillä sinä et katso henkilöön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 17, 'Sano siis meille: miten arvelet? Onko luvallista antaa keisarille veroa vai ei?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 18, 'Mutta Jeesus ymmärsi heidän pahuutensa ja sanoi: \"Miksi kiusaatte minua, te ulkokullatut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 19, 'Näyttäkää minulle veroraha.\" Niin he toivat hänelle denarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 20, 'Hän sanoi heille: \"Kenen kuva ja päällekirjoitus tämä on?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 21, 'He vastasivat: \"Keisarin\". Silloin hän sanoi heille: \"Antakaa siis keisarille, mikä keisarin on, ja Jumalalle, mikä Jumalan on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 22, 'Kun he sen kuulivat, ihmettelivät he ja jättivät hänet ja menivät pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 23, 'Sinä päivänä tuli hänen luoksensa saddukeuksia, jotka sanovat, ettei ylösnousemusta ole, ja he kysyivät häneltä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 24, 'sanoen: \"Opettaja, Mooses on sanonut: \'Jos joku kuolee lapsetonna, niin hänen veljensä naikoon hänen vaimonsa ja herättäköön siemenen veljelleen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 25, 'Keskuudessamme oli seitsemän veljestä. Ensimmäinen otti vaimon ja kuoli; ja koska hänellä ei ollut jälkeläistä, jätti hän vaimonsa veljelleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 26, 'Niin myös toinen ja kolmas, ja samoin kaikki seitsemän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 27, 'Viimeiseksi kaikista kuoli vaimo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 28, 'Kenen vaimo noista seitsemästä hän siis ylösnousemuksessa on oleva? Sillä kaikkien vaimona hän on ollut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 29, 'Jeesus vastasi ja sanoi heille: \"Te eksytte, koska te ette tunne kirjoituksia ettekä Jumalan voimaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 30, 'Sillä ylösnousemuksessa ei naida eikä mennä miehelle; vaan he ovat niinkuin enkelit taivaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 31, 'Mutta mitä kuolleitten ylösnousemukseen tulee, ettekö ole lukeneet, mitä Jumala on puhunut teille, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 32, '\'Minä olen Aabrahamin Jumala ja Iisakin Jumala ja Jaakobin Jumala\'? Ei hän ole kuolleitten Jumala, vaan elävien.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 33, 'Ja sen kuullessaan kansa hämmästyi hänen oppiansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 34, 'Mutta kun fariseukset kuulivat, että hän oli tukkinut saddukeuksilta suun, kokoontuivat he yhteen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 35, 'ja eräs heistä, joka oli lainoppinut, kysyi häneltä kiusaten:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 36, '\"Opettaja, mikä on suurin käsky laissa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 37, 'Niin Jeesus sanoi hänelle: \"\'Rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta mielestäsi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 38, 'Tämä on suurin ja ensimmäinen käsky.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 39, 'Toinen, tämän vertainen, on: \'Rakasta lähimmäistäsi niinkuin itseäsi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 40, 'Näissä kahdessa käskyssä riippuu kaikki laki ja profeetat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 41, 'Ja fariseusten ollessa koolla Jeesus kysyi heiltä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 42, 'sanoen: \"Mitä arvelette Kristuksesta? Kenen poika hän on?\" He sanoivat hänelle: \"Daavidin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 43, 'Hän sanoi heille: \"Kuinka sitten Daavid Hengessä kutsuu häntä Herraksi, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 44, '\'Herra sanoi minun Herralleni: Istu minun oikealle puolelleni, kunnes minä panen sinun vihollisesi sinun jalkojesi alle\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 45, 'Jos siis Daavid kutsuu häntä Herraksi, kuinka hän on hänen poikansa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 22, 46, 'Ja kukaan ei voinut vastata hänelle sanaakaan; eikä siitä päivästä lähtien yksikään enää rohjennut kysyä häneltä mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 1, 'Silloin Jeesus puhui kansalle ja opetuslapsilleen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 2, 'sanoen: \"Mooseksen istuimella istuvat kirjanoppineet ja fariseukset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 3, 'Sentähden, kaikki, mitä he sanovat teille, se tehkää ja pitäkää; mutta heidän tekojensa mukaan älkää tehkö, sillä he sanovat, mutta eivät tee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 4, 'He sitovat kokoon raskaita ja vaikeasti kannettavia taakkoja ja panevat ne ihmisten hartioille, mutta itse he eivät tahdo niitä sormellaankaan liikuttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 5, 'Ja kaikki tekonsa he tekevät sitä varten, että ihmiset heitä katselisivat. He tekevät raamatunlausekotelonsa leveiksi ja vaippansa tupsut suuriksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 6, 'ja rakastavat ensimmäistä sijaa pidoissa ja etumaisia istuimia synagoogissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 7, 'ja tahtovat mielellään, että heitä tervehditään toreilla, ja että ihmiset kutsuvat heitä nimellä \'rabbi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 8, 'Mutta te älkää antako kutsua itseänne rabbiksi, sillä yksi on teidän opettajanne, ja te olette kaikki veljiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 9, 'Ja isäksenne älkää kutsuko ketään maan päällä, sillä yksi on teidän Isänne, hän, joka on taivaissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 10, 'Älkääkä antako kutsua itseänne mestareiksi, sillä yksi on teidän mestarinne, Kristus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 11, 'Vaan joka teistä on suurin, se olkoon teidän palvelijanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 12, 'Mutta joka itsensä ylentää, se alennetaan; ja joka itsensä alentaa, se ylennetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 13, 'Mutta voi teitä, kirjanoppineet ja fariseukset, te ulkokullatut, kun suljette taivasten valtakunnan ihmisiltä! Sillä itse te ette mene sisälle, ettekä salli meneväisten sisälle mennä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 14, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 15, 'Voi teitä, kirjanoppineet ja fariseukset, te ulkokullatut, kun te kierrätte meret ja mantereet tehdäksenne yhden käännynnäisen; ja kun joku on siksi tullut, niin teette hänestä helvetin lapsen, kahta vertaa pahemman, kuin te itse olette!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 16, 'Voi teitä, te sokeat taluttajat, jotka sanotte: \'Jos joku vannoo temppelin kautta, niin se ei ole mitään; mutta jos joku vannoo temppelin kullan kautta, niin hän on valaansa sidottu\'!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 17, 'Te tyhmät ja sokeat! Kumpi on suurempi, kultako vai temppeli, joka kullan pyhittää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 18, 'Ja: \'Jos joku vannoo alttarin kautta, niin se ei ole mitään; mutta jos joku vannoo sen päällä olevan uhrilahjan kautta, niin hän on valaansa sidottu\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 19, 'Te sokeat! Kumpi on suurempi, uhrilahjako vai alttari, joka uhrilahjan pyhittää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 20, 'Sentähden, joka vannoo alttarin kautta, vannoo sen kautta ja kaiken kautta, mitä sen päällä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 21, 'Ja joka vannoo temppelin kautta, vannoo sen kautta ja hänen kauttansa, joka siinä asuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 22, 'Ja joka vannoo taivaan kautta, vannoo Jumalan valtaistuimen kautta ja hänen kauttansa, joka sillä istuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 23, 'Voi teitä, kirjanoppineet ja fariseukset, te ulkokullatut, kun te annatte kymmenykset mintuista ja tilleistä ja kuminoista, mutta jätätte sikseen sen, mikä laissa on tärkeintä: oikeuden ja laupeuden ja uskollisuuden! Näitä tulisi noudattaa, eikä noitakaan sikseen jättää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 24, 'Te sokeat taluttajat, jotka siivilöitte hyttysen, mutta nielette kamelin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 25, 'Voi teitä, kirjanoppineet ja fariseukset, te ulkokullatut, kun te puhdistatte maljan ja vadin ulkopuolen, mutta sisältä ne ovat täynnä ryöstöä ja hillittömyyttä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 26, 'Sinä sokea fariseus, puhdista ensin maljan sisus, että sen ulkopuolikin tulisi puhtaaksi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 27, 'Voi teitä, kirjanoppineet ja fariseukset, te ulkokullatut, kun te olette valkeiksi kalkittujen hautojen kaltaisia: ulkoa ne kyllä näyttävät kauniilta, mutta ovat sisältä täynnä kuolleitten luita ja kaikkea saastaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 28, 'Samoin tekin ulkoa kyllä näytätte ihmisten silmissä hurskailta, mutta sisältä te olette täynnä ulkokultaisuutta ja laittomuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 29, 'Voi teitä, kirjanoppineet ja fariseukset, te ulkokullatut, kun te rakennatte profeettain hautoja ja kaunistatte vanhurskasten hautakammioita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 30, 'ja sanotte: \'Jos me olisimme eläneet isäimme päivinä, emme olisi olleet osallisia heidän kanssaan profeettain vereen\'!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 31, 'Niin te siis todistatte itsestänne, että olette niiden lapsia, jotka tappoivat profeetat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 32, 'Täyttäkää siis te isäinne mitta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 33, 'Te käärmeet, te kyykäärmeitten sikiöt, kuinka te pääsisitte helvetin tuomiota pakoon?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 34, 'Sentähden, katso, minä lähetän teidän tykönne profeettoja ja viisaita ja kirjanoppineita. Muutamat heistä te tapatte ja ristiinnaulitsette, ja toisia heistä te ruoskitte synagoogissanne ja vainoatte kaupungista kaupunkiin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 35, 'että teidän päällenne tulisi kaikki se vanhurskas veri, joka maan päällä on vuodatettu vanhurskaan Aabelin verestä Sakariaan, Barakiaan pojan, vereen asti, jonka te tapoitte temppelin ja alttarin välillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 36, 'Totisesti minä sanon teille: tämä kaikki on tuleva tämän sukupolven päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 37, 'Jerusalem, Jerusalem, sinä, joka tapat profeetat ja kivität ne, jotka ovat sinun tykösi lähetetyt, kuinka usein minä olenkaan tahtonut koota sinun lapsesi, niinkuin kana kokoaa poikansa siipiensä alle! Mutta te ette ole tahtoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 38, 'Katso, \'teidän huoneenne on jäävä hyljätyksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 23, 39, 'Sillä minä sanon teille: tästedes te ette näe minua, ennenkuin sanotte: \'Siunattu olkoon hän, joka tulee Herran nimeen\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 1, 'Ja Jeesus lähti ulos pyhäköstä ja meni pois; ja hänen opetuslapsensa tulivat hänen tykönsä näyttämään hänelle pyhäkön rakennuksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 2, 'Niin hän vastasi ja sanoi heille: \"Ettekö näe näitä kaikkia? Totisesti minä sanon teille: tähän ei ole jäävä kiveä kiven päälle, maahan jaottamatta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 3, 'Ja kun hän istui Öljymäellä, tulivat opetuslapset erikseen hänen tykönsä ja sanoivat: \"Sano meille: milloin se tapahtuu, ja mikä on sinun tulemuksesi ja maailman lopun merkki?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 4, 'Silloin Jeesus vastasi ja sanoi heille: \"Katsokaa, ettei kukaan teitä eksytä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 5, 'Sillä monta tulee minun nimessäni sanoen: \'Minä olen Kristus\', ja he eksyttävät monta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 6, 'Ja te saatte kuulla sotien melskettä ja sanomia sodista; katsokaa, ettette peljästy. Sillä näin täytyy tapahtua, mutta tämä ei ole vielä loppu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 7, 'Sillä kansa nousee kansaa vastaan ja valtakunta valtakuntaa vastaan, ja nälänhätää ja maanjäristyksiä tulee monin paikoin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 8, 'Mutta kaikki tämä on synnytystuskien alkua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 9, 'Silloin teidät annetaan vaivaan, ja teitä tapetaan, ja te joudutte kaikkien kansojen vihattaviksi minun nimeni tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 10, 'Ja silloin monet lankeavat pois, ja he antavat toisensa alttiiksi ja vihaavat toinen toistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 11, 'Ja monta väärää profeettaa nousee, ja he eksyttävät monta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 12, 'Ja sentähden, että laittomuus pääsee valtaan, kylmenee useimpien rakkaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 13, 'Mutta joka vahvana pysyy loppuun asti, se pelastuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 14, 'Ja tämä valtakunnan evankeliumi pitää saarnattaman kaikessa maailmassa, todistukseksi kaikille kansoille; ja sitten tulee loppu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 15, 'Kun te siis näette hävityksen kauhistuksen, josta on puhuttu profeetta Danielin kautta, seisovan pyhässä paikassa-joka tämän lukee, se tarkatkoon-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 16, 'silloin ne, jotka Juudeassa ovat, paetkoot vuorille;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 17, 'joka on katolla, älköön astuko alas noutamaan, mitä hänen huoneessansa on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 18, 'ja joka on pellolla, älköön palatko takaisin noutamaan vaippaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 19, 'Voi raskaita ja imettäväisiä niinä päivinä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 20, 'Mutta rukoilkaa, ettei teidän pakonne tapahtuisi talvella eikä sapattina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 21, 'Sillä silloin on oleva suuri ahdistus, jonka kaltaista ei ole ollut maailman alusta hamaan tähän asti eikä milloinkaan tule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 22, 'Ja ellei niitä päiviä olisi lyhennetty, ei mikään liha pelastuisi; mutta valittujen tähden ne päivät lyhennetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 23, 'Jos silloin joku sanoo teille: \'Katso, täällä on Kristus\', tahi: \'Tuolla\', niin älkää uskoko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 24, 'Sillä vääriä kristuksia ja vääriä profeettoja nousee, ja he tekevät suuria tunnustekoja ja ihmeitä, niin että eksyttävät, jos mahdollista, valitutkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 25, 'Katso, minä olen sen teille edeltä sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 26, 'Sentähden, jos teille sanotaan: \'Katso, hän on erämaassa\', niin älkää menkö sinne, tahi: \'Katso, hän on kammiossa\', niin älkää uskoko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 27, 'Sillä niinkuin salama leimahtaa idästä ja näkyy hamaan länteen, niin on oleva Ihmisen Pojan tulemus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 28, 'Missä raato on, sinne kotkat kokoontuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 29, 'Mutta kohta niiden päivien ahdistuksen jälkeen aurinko pimenee, eikä kuu anna valoansa, ja tähdet putoavat taivaalta, ja taivaitten voimat järkkyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 30, 'Ja silloin Ihmisen Pojan merkki näkyy taivaalla, ja silloin kaikki maan sukukunnat parkuvat; ja he näkevät Ihmisen Pojan tulevan taivaan pilvien päällä suurella voimalla ja kirkkaudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 31, 'Ja hän lähettää enkelinsä suuren pasunan pauhatessa, ja he kokoavat hänen valittunsa neljältä ilmalta, taivasten ääristä hamaan toisiin ääriin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 32, 'Mutta oppikaa viikunapuusta vertaus: kun sen oksa jo on tuore ja lehdet puhkeavat, niin te tiedätte, että kesä on lähellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 33, 'Samoin te myös, kun näette tämän kaiken, tietäkää, että se on lähellä, oven edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 34, 'Totisesti minä sanon teille: tämä sukupolvi ei katoa, ennenkuin kaikki nämä tapahtuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 35, 'Taivas ja maa katoavat, mutta minun sanani eivät koskaan katoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 36, 'Mutta siitä päivästä ja hetkestä ei tiedä kukaan, eivät taivasten enkelit, eikä myöskään Poika, vaan Isä yksin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 37, 'Sillä niinkuin oli Nooan päivinä, niin on Ihmisen Pojan tulemus oleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 38, 'Sillä niinkuin ihmiset olivat niinä päivinä ennen vedenpaisumusta: söivät ja joivat, naivat ja naittivat, aina siihen päivään asti, jona Nooa meni arkkiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 39, 'eivätkä tienneet, ennenkuin vedenpaisumus tuli ja vei heidät kaikki; niin on myös Ihmisen Pojan tulemus oleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 40, 'Silloin on kaksi miestä pellolla; toinen korjataan talteen, ja toinen jätetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 41, 'Kaksi naista on jauhamassa käsikivillä; toinen korjataan talteen, ja toinen jätetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 42, 'Valvokaa siis, sillä ette tiedä, minä päivänä teidän Herranne tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 43, 'Mutta se tietäkää: jos perheenisäntä tietäisi, millä yövartiolla varas tulee, totta hän valvoisi, eikä sallisi taloonsa murtauduttavan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 44, 'Sentähden olkaa tekin valmiit, sillä sinä hetkenä, jona ette luule, Ihmisen Poika tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 45, 'Kuka siis on se uskollinen ja ymmärtäväinen palvelija, jonka hänen herransa on asettanut pitämään huolta palvelusväestään, antamaan heille ruokaa ajallansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 46, 'Autuas se palvelija, jonka hänen herransa tullessaan havaitsee näin tekevän!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 47, 'Totisesti minä sanon teille: hän asettaa hänet kaiken omaisuutensa hoitajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 48, 'Mutta jos paha palvelija sanoo sydämessään: \'Minun herrani viipyy\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 49, 'ja rupeaa lyömään kanssapalvelijoitaan ja syö ja juo juopuneiden kanssa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 50, 'niin sen palvelijan herra tulee päivänä, jona hän ei odota, ja hetkenä, jota hän ei arvaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 24, 51, 'ja hakkaa hänet kappaleiksi ja määrää hänelle saman osan kuin ulkokullatuille. Siellä on oleva itku ja hammasten kiristys.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 1, '\"Silloin on taivasten valtakunta oleva kymmenen neitsyen kaltainen, jotka ottivat lamppunsa ja lähtivät ylkää vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 2, 'Mutta viisi heistä oli tyhmää ja viisi ymmärtäväistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 3, 'Tyhmät ottivat lamppunsa, mutta eivät ottaneet öljyä mukaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 4, 'Mutta ymmärtäväiset ottivat öljyä astioihinsa ynnä lamppunsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 5, 'Yljän viipyessä tuli heille kaikille uni, ja he nukkuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 6, 'Mutta yösydännä kuului huuto: \'Katso, ylkä tulee! Menkää häntä vastaan.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 7, 'Silloin kaikki nämä neitsyet nousivat ja laittoivat lamppunsa kuntoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 8, 'Ja tyhmät sanoivat ymmärtäväisille: \'Antakaa meille öljyänne, sillä meidän lamppumme sammuvat\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 9, 'Mutta ymmärtäväiset vastasivat ja sanoivat: \'Emme voi, se ei riitä meille ja teille. Menkää ennemmin myyjäin luo ostamaan itsellenne.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 10, 'Mutta heidän lähdettyään ostamaan ylkä tuli; ja ne, jotka olivat valmiit, menivät hänen kanssansa häihin, ja ovi suljettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 11, 'Ja myöhemmin toisetkin neitsyet tulivat ja sanoivat: \'Herra, Herra, avaa meille!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 12, 'Mutta hän vastasi ja sanoi: \'Totisesti minä sanon teille: minä en tunne teitä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 13, 'Valvokaa siis, sillä ette tiedä päivää ettekä hetkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 14, 'Sillä tapahtuu, niinkuin tapahtui, kun mies matkusti muille maille: hän kutsui palvelijansa ja uskoi heille omaisuutensa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 15, 'yhdelle hän antoi viisi leiviskää, toiselle kaksi ja kolmannelle yhden, kullekin hänen kykynsä mukaan, ja lähti muille maille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 16, 'Se, joka oli saanut viisi leiviskää, meni kohta ja asioitsi niillä ja voitti toiset viisi leiviskää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 17, 'Samoin kaksi leiviskää saanut voitti toiset kaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 18, 'Mutta yhden leiviskän saanut meni pois ja kaivoi kuopan maahan ja kätki siihen herransa rahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 19, 'Pitkän ajan kuluttua näiden palvelijain herra palasi ja ryhtyi tilintekoon heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 20, 'Silloin tuli se, joka oli saanut viisi leiviskää, ja toi toiset viisi leiviskää ja sanoi: \'Herra, viisi leiviskää sinä minulle uskoit, katso, toiset viisi leiviskää minä olen voittanut\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 21, 'Hänen herransa sanoi hänelle: \'Hyvä on, sinä hyvä ja uskollinen palvelija. Vähässä sinä olet ollut uskollinen, minä panen sinut paljon haltijaksi. Mene herrasi iloon.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 22, 'Myös se, joka oli saanut kaksi leiviskää, tuli ja sanoi: \'Herra, kaksi leiviskää sinä minulle uskoit, katso, toiset kaksi leiviskää minä olen voittanut\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 23, 'Hänen herransa sanoi hänelle: \'Hyvä on, sinä hyvä ja uskollinen palvelija. Vähässä sinä olet ollut uskollinen, minä panen sinut paljon haltijaksi. Mene herrasi iloon.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 24, 'Sitten myös se, joka oli saanut yhden leiviskän, tuli ja sanoi: \'Herra, minä tiesin sinut kovaksi mieheksi; sinä leikkaat sieltä, mihin et ole kylvänyt, ja kokoat sieltä, missä et ole eloa viskannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 25, 'Ja peloissani minä menin ja kätkin sinun leiviskäsi maahan; katso, tässä on omasi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 26, 'Mutta hänen herransa vastasi ja sanoi hänelle: \'Sinä paha ja laiska palvelija! Sinä tiesit minun leikkaavan sieltä, mihin en ole kylvänyt, ja kokoavan sieltä, missä en ole viskannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 27, 'Sinun olisi siis pitänyt jättää minun rahani rahanvaihtajille, niin minä tultuani olisin saanut omani takaisin korkoineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 28, 'Ottakaa sentähden leiviskä häneltä pois ja antakaa sille, jolla on kymmenen leiviskää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 29, 'Sillä jokaiselle, jolla on, annetaan, ja hänellä on oleva yltäkyllin; mutta jolla ei ole, siltä otetaan pois sekin, mikä hänellä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 30, 'Ja heittäkää tuo kelvoton palvelija ulos pimeyteen; siellä on oleva itku ja hammasten kiristys.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 31, 'Mutta kun Ihmisen Poika tulee kirkkaudessaan ja kaikki enkelit hänen kanssaan, silloin hän istuu kirkkautensa valtaistuimelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 32, 'Ja hänen eteensä kootaan kaikki kansat, ja hän erottaa toiset toisista, niinkuin paimen erottaa lampaat vuohista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 33, 'Ja hän asettaa lampaat oikealle puolelleen, mutta vuohet vasemmalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 34, 'Silloin Kuningas sanoo oikealla puolellaan oleville: \'Tulkaa, minun Isäni siunatut, ja omistakaa se valtakunta, joka on ollut teille valmistettuna maailman perustamisesta asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 35, 'Sillä minun oli nälkä, ja te annoitte minulle syödä; minun oli jano, ja te annoitte minulle juoda; minä olin outo, ja te otitte minut huoneeseenne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 36, 'minä olin alaston, ja te vaatetitte minut; minä sairastin, ja te kävitte minua katsomassa; minä olin vankeudessa, ja te tulitte minun tyköni.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 37, 'Silloin vanhurskaat vastaavat hänelle sanoen: \'Herra, milloin me näimme sinut nälkäisenä ja ruokimme sinua, tai janoisena ja annoimme sinulle juoda?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 38, 'Ja milloin me näimme sinut outona ja otimme sinut huoneeseemme, tai alastonna ja vaatetimme sinut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 39, 'Ja milloin me näimme sinun sairastavan tai olevan vankeudessa ja tulimme sinun tykösi?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 40, 'Niin Kuningas vastaa ja sanoo heille: \'Totisesti minä sanon teille: kaikki, mitä olette tehneet yhdelle näistä minun vähimmistä veljistäni, sen te olette tehneet minulle\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 41, 'Sitten hän myös sanoo vasemmalla puolellaan oleville: \'Menkää pois minun tyköäni, te kirotut, siihen iankaikkiseen tuleen, joka on valmistettu perkeleelle ja hänen enkeleillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 42, 'Sillä minun oli nälkä, ja te ette antaneet minulle syödä; minun oli jano, ja te ette antaneet minulle juoda;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 43, 'minä olin outo, ja te ette ottaneet minua huoneeseenne; minä olin alaston, ja te ette vaatettaneet minua; sairaana ja vankeudessa, ja te ette käyneet minua katsomassa.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 44, 'Silloin hekin vastaavat sanoen: \'Herra, milloin me näimme sinut nälkäisenä tai janoisena tai outona tai alastonna tai sairaana tai vankeudessa, emmekä sinua palvelleet?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 45, 'Silloin hän vastaa heille ja sanoo: \'Totisesti minä sanon teille: kaiken, minkä olette jättäneet tekemättä yhdelle näistä vähimmistä, sen te olette jättäneet tekemättä minulle\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 25, 46, 'Ja nämä menevät pois iankaikkiseen rangaistukseen, mutta vanhurskaat iankaikkiseen elämään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 1, 'Ja kun Jeesus oli lopettanut kaikki nämä puheet, sanoi hän opetuslapsillensa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 2, '\"Te tiedätte, että kahden päivän perästä on pääsiäinen; silloin Ihmisen Poika annetaan ristiinnaulittavaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 3, 'Silloin ylipapit ja kansan vanhimmat kokoontuivat Kaifas nimisen ylimmäisen papin palatsiin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 4, 'ja neuvottelivat, kuinka ottaisivat Jeesuksen kiinni kavaluudella ja tappaisivat hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 5, 'Mutta he sanoivat: \"Ei juhlan aikana, ettei syntyisi meteliä kansassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 6, 'Kun Jeesus oli Betaniassa pitalisen Simonin asunnossa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 7, 'tuli hänen luoksensa nainen, mukanaan alabasteripullo täynnä kallisarvoista voidetta, minkä hän vuodatti Jeesuksen päähän hänen ollessaan aterialla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 8, 'Mutta sen nähdessään hänen opetuslapsensa närkästyivät ja sanoivat: \"Mitä varten tämä haaskaus?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 9, 'Olisihan sen voinut myydä kalliista hinnasta ja antaa rahat köyhille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 10, 'Kun Jeesus sen huomasi, sanoi hän heille: \"Miksi pahoitatte tämän naisen mieltä? Sillä hän teki hyvän työn minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 11, 'Köyhät teillä on aina keskuudessanne, mutta minua teillä ei ole aina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 12, 'Sillä kun hän valoi tämän voiteen minun ruumiilleni, teki hän sen minun hautaamistani varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 13, 'Totisesti minä sanon teille: missä ikinä kaikessa maailmassa tätä evankeliumia saarnataan, siellä sekin, minkä hän teki, on mainittava hänen muistoksensa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 14, 'Silloin meni yksi niistä kahdestatoista, nimeltä Juudas Iskariot, ylipappien luo');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 15, 'ja sanoi: \"Mitä tahdotte antaa minulle, niin minä saatan hänet teidän käsiinne?\" Ja he maksoivat hänelle kolmekymmentä hopearahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 16, 'Ja siitä hetkestä hän etsi sopivaa tilaisuutta kavaltaaksensa hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 17, 'Mutta ensimmäisenä happamattoman leivän päivänä opetuslapset tulivat Jeesuksen tykö ja sanoivat: \"Mihin tahdot, että valmistamme pääsiäislampaan sinun syödäksesi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 18, 'Niin hän sanoi: \"Menkää kaupunkiin sen ja sen luo ja sanokaa hänelle: \'Opettaja sanoo: Minun aikani on lähellä; sinun luonasi minä syön pääsiäisaterian opetuslasteni kanssa\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 19, 'Ja opetuslapset tekivät, niinkuin Jeesus oli heitä käskenyt, ja valmistivat pääsiäislampaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 20, 'Ja kun ehtoo tuli, asettui hän aterialle kahdentoista opetuslapsensa kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 21, 'Ja heidän syödessään hän sanoi: \"Totisesti minä sanon teille: yksi teistä kavaltaa minut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 22, 'Silloin he tulivat kovin murheellisiksi ja rupesivat toinen toisensa perästä sanomaan hänelle: \"Herra, en kai minä ole se?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 23, 'Hän vastasi ja sanoi: \"Joka minun kanssani pisti kätensä vatiin, se kavaltaa minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 24, 'Ihmisen Poika tosin menee pois, niinkuin hänestä on kirjoitettu, mutta voi sitä ihmistä, jonka kautta Ihmisen Poika kavalletaan! Parempi olisi sille ihmiselle, että hän ei olisi syntynyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 25, 'Niin Juudas, joka hänet kavalsi, vastasi ja sanoi: \"Rabbi, en kai minä ole se?\" Hän sanoi hänelle: \"Sinäpä sen sanoit\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 26, 'Ja heidän syödessään Jeesus otti leivän, siunasi, mursi ja antoi opetuslapsillensa ja sanoi: \"Ottakaa ja syökää; tämä on minun ruumiini\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 27, 'Ja hän otti maljan, kiitti ja antoi heille ja sanoi: \"Juokaa tästä kaikki;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 28, 'sillä tämä on minun vereni, liiton veri, joka monen edestä vuodatetaan syntien anteeksiantamiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 29, 'Ja minä sanon teille: tästedes minä en juo tätä viinipuun antia, ennenkuin sinä päivänä, jona juon sitä uutena teidän kanssanne Isäni valtakunnassa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 30, 'Ja veisattuaan kiitosvirren he lähtivät Öljymäelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 31, 'Silloin Jeesus sanoi heille: \"Tänä yönä te kaikki loukkaannutte minuun; sillä kirjoitettu on: \'Minä lyön paimenta, ja lauman lampaat hajotetaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 32, 'Mutta ylösnoustuani minä menen teidän edellänne Galileaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 33, 'Niin Pietari vastasi ja sanoi hänelle: \"Vaikka kaikki loukkaantuisivat sinuun, niin minä en koskaan loukkaannu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 34, 'Jeesus sanoi hänelle: \"Totisesti minä sanon sinulle: tänä yönä, ennenkuin kukko laulaa, sinä kolmesti minut kiellät\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 35, 'Pietari sanoi hänelle: \"Vaikka minun pitäisi kuolla sinun kanssasi, en sittenkään minä sinua kiellä\". Samoin sanoivat myös kaikki muut opetuslapset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 36, 'Sitten Jeesus tuli heidän kanssaan Getsemane nimiselle maatilalle; ja hän sanoi opetuslapsillensa: \"Istukaa tässä, sillä aikaa kuin minä menen ja rukoilen tuolla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 37, 'Ja hän otti mukaansa Pietarin ja ne kaksi Sebedeuksen poikaa; ja hän alkoi murehtia ja tulla tuskaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 38, 'Silloin hän sanoi heille: \"Minun sieluni on syvästi murheellinen, kuolemaan asti; olkaa tässä ja valvokaa minun kanssani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 39, 'Ja hän meni vähän edemmäksi, lankesi kasvoilleen ja rukoili sanoen: \"Isäni, jos mahdollista on, niin menköön minulta pois tämä malja; ei kuitenkaan niinkuin minä tahdon, vaan niinkuin sinä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 40, 'Ja hän tuli opetuslasten tykö ja tapasi heidät nukkumasta ja sanoi Pietarille: \"Niin ette siis jaksaneet yhtä hetkeä valvoa minun kanssani!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 41, 'Valvokaa ja rukoilkaa, ettette joutuisi kiusaukseen; henki tosin on altis, mutta liha on heikko.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 42, 'Taas hän meni pois toisen kerran ja rukoili sanoen: \"Isäni, jos tämä malja ei voi mennä minun ohitseni, minun sitä juomattani, niin tapahtukoon sinun tahtosi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 43, 'Ja tullessaan hän taas tapasi heidät nukkumasta, sillä heidän silmänsä olivat käyneet raukeiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 44, 'Ja hän jätti heidät, meni taas ja rukoili kolmannen kerran ja sanoi samat sanat uudestaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 45, 'Sitten hän tuli opetuslasten tykö ja sanoi heille: \"Te nukutte vielä ja lepäätte! Katso, hetki on lähellä, ja Ihmisen Poika annetaan syntisten käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 46, 'Nouskaa, lähtekäämme; katso, se on lähellä, joka minut kavaltaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 47, 'Ja katso, hänen vielä puhuessaan tuli Juudas, yksi niistä kahdestatoista, ja hänen kanssaan lukuisa joukko ylipappien ja kansan vanhinten luota miekat ja seipäät käsissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 48, 'Ja se, joka hänet kavalsi, oli antanut heille merkin sanoen: \"Se, jolle minä suuta annan, hän se on; ottakaa hänet kiinni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 49, 'Ja kohta hän meni Jeesuksen luo ja sanoi: \"Terve, rabbi!\" ja antoi hänelle suuta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 50, 'Niin Jeesus sanoi hänelle: \"Ystäväni, mitä varten sinä tänne tulit?\" Silloin he tulivat Jeesuksen luo, kävivät häneen käsiksi ja ottivat hänet kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 51, 'Ja katso, eräs niistä, jotka olivat Jeesuksen kanssa, ojensi kätensä, veti miekkansa ja iski ylimmäisen papin palvelijaa ja sivalsi häneltä pois korvan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 52, 'Silloin Jeesus sanoi hänelle: \"Pistä miekkasi tuppeen; sillä kaikki, jotka miekkaan tarttuvat, ne miekkaan hukkuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 53, 'Vai luuletko, etten voisi rukoilla Isääni, niin että hän lähettäisi heti minulle enemmän kuin kaksitoista legionaa enkeleitä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 54, 'Mutta kuinka silloin kävisivät toteen kirjoitukset, jotka sanovat, että näin pitää tapahtuman?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 55, 'Sillä hetkellä Jeesus sanoi joukolle: \"Niinkuin ryöväriä vastaan te olette lähteneet minua miekoilla ja seipäillä vangitsemaan. Joka päivä minä olen istunut pyhäkössä opettamassa, ettekä ole ottaneet minua kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 56, 'Mutta tämä kaikki on tapahtunut, että profeettain kirjoitukset kävisivät toteen.\" Silloin kaikki opetuslapset jättivät hänet ja pakenivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 57, 'Mutta Jeesuksen kiinniottajat veivät hänet ylimmäisen papin, Kaifaan, eteen, jonne kirjanoppineet ja vanhimmat olivat kokoontuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 58, 'Ja Pietari seurasi häntä taampana ylimmäisen papin esipihaan asti; ja hän meni sinne ja istui palvelijain joukkoon nähdäksensä, kuinka lopulta kävisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 59, 'Mutta ylipapit ja koko neuvosto etsivät väärää todistusta Jeesusta vastaan tappaaksensa hänet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 60, 'mutta eivät löytäneet, vaikka monta väärää todistajaa oli tullut esille. Mutta vihdoin tuli kaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 61, 'ja he sanoivat: \"Tämä on sanonut: \'Minä voin hajottaa maahan Jumalan temppelin ja kolmessa päivässä sen rakentaa\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 62, 'Silloin ylimmäinen pappi nousi ja sanoi hänelle: \"Etkö vastaa mitään siihen, mitä nämä todistavat sinua vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 63, 'Mutta Jeesus oli vaiti. Niin ylimmäinen pappi sanoi hänelle: \"Minä vannotan sinua elävän Jumalan kautta, että sanot meille, oletko sinä Kristus, Jumalan Poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 64, 'Jeesus sanoi hänelle: \"Sinäpä sen sanoit. Mutta minä sanon teille: tästedes te saatte nähdä Ihmisen Pojan istuvan Voiman oikealla puolella ja tulevan taivaan pilvien päällä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 65, 'Silloin ylimmäinen pappi repäisi vaatteensa ja sanoi: \"Hän on pilkannut Jumalaa. Mitä me enää todistajia tarvitsemme? Katso, nyt kuulitte hänen pilkkaamisensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 66, 'Miten teistä on?\" He vastasivat sanoen: \"Hän on vikapää kuolemaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 67, 'Silloin he sylkivät häntä silmille ja löivät häntä nyrkillä kasvoihin; ja toiset sivalsivat häntä poskelle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 68, 'ja sanoivat: \"Profetoi meille, Kristus, kuka se on, joka sinua löi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 69, 'Mutta Pietari istui ulkopuolella esipihassa. Ja hänen luoksensa tuli muuan palvelijatar ja sanoi: \"Sinäkin olit Jeesuksen, galilealaisen, seurassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 70, 'Mutta hän kielsi kaikkien kuullen ja sanoi: \"En ymmärrä, mitä sanot\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 71, 'Ja kun hän oli mennyt ulos portille, näki hänet toinen nainen ja sanoi sielläoleville: \"Tämäkin oli Jeesuksen, Nasaretilaisen, seurassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 72, 'Ja taas hän kielsi valalla vannoen: \"En tunne sitä miestä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 73, 'Vähän sen jälkeen tulivat ne, jotka siinä seisoivat, ja sanoivat Pietarille: \"Totisesti, sinä myös olet yksi heistä, sillä kielimurteesikin ilmaisee sinut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 74, 'Silloin hän rupesi sadattelemaan ja vannomaan: \"En tunne sitä miestä\". Ja samassa lauloi kukko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 26, 75, 'Niin Pietari muisti Jeesuksen sanat, jotka hän oli sanonut: \"Ennenkuin kukko laulaa, sinä kolmesti minut kiellät\". Ja hän meni ulos ja itki katkerasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 1, 'Mutta aamun koittaessa kaikki ylipapit ja kansan vanhimmat pitivät neuvoa Jeesusta vastaan tappaaksensa hänet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 2, 'ja he sitoivat hänet ja veivät pois ja antoivat hänet maaherran, Pilatuksen, käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 3, 'Kun Juudas, hänen kavaltajansa, näki, että hänet oli tuomittu, silloin hän katui ja toi takaisin ne kolmekymmentä hopearahaa ylipapeille ja vanhimmille');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 4, 'ja sanoi: \"Minä tein synnin, kun kavalsin viattoman veren\". Mutta he sanoivat: \"Mitä se meihin koskee? Katso itse eteesi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 5, 'Ja hän viskasi hopearahat temppeliin, lähti sieltä, meni pois ja hirttäytyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 6, 'Niin ylipapit ottivat hopearahat ja sanoivat: \"Ei ole luvallista panna näitä temppelirahastoon, koska ne ovat veren hinta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 7, 'Ja neuvoteltuaan he ostivat niillä savenvalajan pellon muukalaisten hautausmaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 8, 'Sentähden sitä peltoa vielä tänäkin päivänä kutsutaan Veripelloksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 9, 'Silloin kävi toteen, mikä on puhuttu profeetta Jeremiaan kautta, joka sanoo: \"Ja he ottivat ne kolmekymmentä hopearahaa, hinnan siitä arvioidusta miehestä, jonka he olivat israelilaisten puolesta arvioineet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 10, 'ja antoivat ne savenvalajan pellosta, niinkuin Herra oli minun kauttani käskenyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 11, 'Mutta Jeesus seisoi maaherran edessä. Ja maaherra kysyi häneltä sanoen: \"Oletko sinä juutalaisten kuningas?\" Niin Jeesus sanoi: \"Sinäpä sen sanot\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 12, 'Ja kun ylipapit ja vanhimmat häntä syyttivät, ei hän mitään vastannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 13, 'Silloin Pilatus sanoi hänelle: \"Etkö kuule, kuinka paljon he todistavat sinua vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 14, 'Mutta hän ei vastannut yhteenkään hänen kysymykseensä, niin että maaherra suuresti ihmetteli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 15, 'Oli tapana, että maaherra juhlan aikana päästi kansalle yhden vangin irti, kenenkä he tahtoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 16, 'Ja heillä oli silloin kuuluisa vanki, jota sanottiin Barabbaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 17, 'Kun he nyt olivat koolla, sanoi Pilatus heille: \"Kummanko tahdotte, että minä teille päästän, Barabbaanko vai Jeesuksen, jota sanotaan Kristukseksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 18, 'Sillä hän tiesi, että he kateudesta olivat antaneet hänet hänen käsiinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 19, 'Mutta kun hän istui tuomarinistuimella, lähetti hänen vaimonsa hänelle sanan: \"Älä puutu siihen vanhurskaaseen mieheen, sillä minä olen tänä yönä unessa paljon kärsinyt hänen tähtensä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 20, 'Mutta ylipapit ja vanhimmat yllyttivät kansaa anomaan Barabbasta, mutta surmauttamaan Jeesuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 21, 'Ja maaherra puhui heille ja sanoi: \"Kummanko näistä kahdesta tahdotte, että minä teille päästän?\" Niin he sanoivat: \"Barabbaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 22, 'Pilatus sanoi heille: \"Mitä minun sitten on tehtävä Jeesukselle, jota sanotaan Kristukseksi?\" He sanoivat kaikki: \"Ristiinnaulittakoon!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 23, 'Niin maaherra sanoi: \"Mitä pahaa hän sitten on tehnyt?\" Mutta he huusivat vielä kovemmin sanoen: \"Ristiinnaulittakoon!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 24, 'Ja kun Pilatus näki, ettei mikään auttanut, vaan että meteli yhä yltyi, otti hän vettä ja pesi kätensä kansan nähden ja sanoi: \"Viaton olen minä tämän miehen vereen. Katsokaa itse eteenne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 25, 'Niin kaikki kansa vastasi ja sanoi: \"Tulkoon hänen verensä meidän päällemme ja meidän lastemme päälle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 26, 'Silloin hän päästi heille Barabbaan, mutta Jeesuksen hän ruoskitti ja luovutti ristiinnaulittavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 27, 'Silloin maaherran sotamiehet veivät Jeesuksen mukanaan palatsiin ja keräsivät hänen ympärilleen koko sotilasjoukon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 28, 'Ja he riisuivat hänet ja panivat hänen päällensä tulipunaisen vaipan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 29, 'ja väänsivät orjantappuroista kruunun, panivat sen hänen päähänsä ja ruovon hänen oikeaan käteensä, polvistuivat hänen eteensä ja pilkkasivat häntä ja sanoivat: \"Terve, juutalaisten kuningas!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 30, 'Ja he sylkivät häntä, ottivat ruovon ja löivät häntä päähän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 31, 'Ja kun he olivat häntä pilkanneet, riisuivat he häneltä vaipan, pukivat hänet hänen omiin vaatteisiinsa ja veivät hänet pois ristiinnaulittavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 32, 'Ja matkalla he tapasivat kyreneläisen miehen, jonka nimi oli Simon. Hänet he pakottivat kantamaan hänen ristiänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 33, 'Ja tultuaan paikalle, jota sanotaan Golgataksi-se on: pääkallon paikaksi-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 34, 'he tarjosivat hänelle juotavaksi katkeralla nesteellä sekoitettua viiniä; mutta maistettuaan hän ei tahtonut sitä juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 35, 'Ja kun he olivat hänet ristiinnaulinneet, jakoivat he keskenään hänen vaatteensa heittäen niistä arpaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 36, 'Sitten he istuutuivat ja vartioivat häntä siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 37, 'Ja he olivat panneet hänen päänsä yläpuolelle hänen syynsä julki, näin kirjoitettuna: \"Tämä on Jeesus, juutalaisten kuningas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 38, 'Silloin ristiinnaulittiin hänen kanssansa kaksi ryöväriä, toinen oikealle ja toinen vasemmalle puolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 39, 'Ja ne, jotka kulkivat ohitse, herjasivat häntä, nyökyttivät päätänsä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 40, 'ja sanoivat: \"Sinä, joka hajotat maahan temppelin ja kolmessa päivässä sen rakennat, auta itseäsi, jos olet Jumalan Poika, ja astu alas ristiltä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 41, 'Samoin ylipapit ja kirjanoppineet ja vanhimmat pilkkasivat häntä ja sanoivat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 42, '\"Muita hän on auttanut, itseään ei voi auttaa. Onhan hän Israelin kuningas; astukoon nyt alas ristiltä, niin me uskomme häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 43, 'Hän on luottanut Jumalaan; vapahtakoon nyt Jumala hänet, jos on häneen mielistynyt; sillä hän on sanonut: \'Minä olen Jumalan Poika\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 44, 'Ja samalla tavalla herjasivat häntä ryöväritkin, jotka olivat ristiinnaulitut hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 45, 'Mutta kuudennesta hetkestä alkaen tuli pimeys yli kaiken maan, ja sitä kesti hamaan yhdeksänteen hetkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 46, 'Ja yhdeksännen hetken vaiheilla Jeesus huusi suurella äänellä sanoen: \"Eeli, Eeli, lama sabaktani?\" Se on: Jumalani, Jumalani, miksi minut hylkäsit?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 47, 'Sen kuullessaan sanoivat muutamat niistä, jotka siinä seisoivat: \"Hän huutaa Eliasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 48, 'Ja kohta muuan heistä juoksi ja otti sienen, täytti sen hapanviinillä, pani sen ruovon päähän ja antoi hänelle juoda.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 49, 'Mutta muut sanoivat: \"Annas, katsokaamme, tuleeko Elias häntä pelastamaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 50, 'Niin Jeesus taas huusi suurella äänellä ja antoi henkensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 51, 'Ja katso, temppelin esirippu repesi kahtia ylhäältä alas asti, ja maa järisi, ja kalliot halkesivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 52, 'ja haudat aukenivat, ja monta nukkuneiden pyhien ruumista nousi ylös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 53, 'Ja he lähtivät haudoistaan ja tulivat hänen ylösnousemisensa jälkeen pyhään kaupunkiin ja ilmestyivät monelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 54, 'Mutta kun sadanpäämies ja ne, jotka hänen kanssaan vartioitsivat Jeesusta, näkivät maanjäristyksen ja mitä muuta tapahtui, peljästyivät he suuresti ja sanoivat: \"Totisesti tämä oli Jumalan Poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 55, 'Ja siellä oli monta naista, jotka olivat Galileasta seuranneet Jeesusta ja palvelleet häntä; he seisoivat taampana katselemassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 56, 'Heidän joukossaan oli Maria Magdaleena ja Maria, Jaakobin ja Joosefin äiti, ja Sebedeuksen poikain äiti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 57, 'Mutta illan tultua saapui rikas mies, Arimatiasta kotoisin, nimeltä Joosef, joka hänkin oli Jeesuksen opetuslapsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 58, 'Hän meni Pilatuksen luo ja pyysi Jeesuksen ruumista. Silloin Pilatus käski antaa sen hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 59, 'Ja Joosef otti ruumiin, kääri sen puhtaaseen liinavaatteeseen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 60, 'ja pani sen uuteen hautakammioonsa, jonka oli hakkauttanut kallioon. Ja hän vieritti suuren kiven hautakammion ovelle ja lähti pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 61, 'Ja siellä olivat Maria Magdaleena ja toinen Maria, jotka istuivat vastapäätä hautaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 62, 'Seuraavana päivänä, joka oli valmistuspäivän jälkeinen, ylipapit ja fariseukset kokoontuivat Pilatuksen luo');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 63, 'ja sanoivat: \"Herra, me muistamme sen villitsijän vielä eläessään sanoneen: \'Kolmen päivän kuluttua minä nousen ylös\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 64, 'Käske siis tarkasti vartioida hautaa kolmanteen päivään asti, etteivät hänen opetuslapsensa tulisi ja varastaisi häntä ja sanoisi kansalle: \'Hän nousi kuolleista\', ja niin viimeinen villitys olisi pahempi kuin ensimmäinen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 65, 'Niin Pilatus sanoi heille: \"Tuossa on vartijaväkeä, menkää, vartioikaa niin hyvin kuin taidatte\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 27, 66, 'Niin he menivät ja turvasivat haudan lukitsemalla kiven sinetillä ja asettamalla vartijat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 1, 'Ja kun sapatti oli päättynyt ja viikon ensimmäisen päivän aamu koitti, tulivat Maria Magdaleena ja se toinen Maria katsomaan hautaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 2, 'Ja katso, tapahtui suuri maanjäristys, sillä Herran enkeli astui alas taivaasta, tuli ja vieritti kiven pois ja istui sille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 3, 'Hän oli näöltään niinkuin salama, ja hänen vaatteensa olivat valkeat kuin lumi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 4, 'Ja häntä peljästyen vartijat vapisivat ja kävivät ikäänkuin kuolleiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 5, 'Mutta enkeli puhutteli naisia ja sanoi heille: \"Älkää te peljätkö; sillä minä tiedän teidän etsivän Jeesusta, joka oli ristiinnaulittu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 6, 'Ei hän ole täällä, sillä hän on noussut ylös, niinkuin hän sanoi. Tulkaa, katsokaa paikkaa, jossa hän on maannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 7, 'Ja menkää kiiruusti ja sanokaa hänen opetuslapsillensa, että hän on noussut kuolleista. Ja katso, hän menee teidän edellänne Galileaan; siellä te saatte hänet nähdä. Katso, minä olen sen teille sanonut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 8, 'Ja he menivät kiiruusti haudalta peloissaan ja suuresti iloiten ja juoksivat viemään sanaa hänen opetuslapsillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 9, 'Mutta katso, Jeesus tuli heitä vastaan ja sanoi: \"Terve teille!\" Ja he menivät hänen tykönsä, syleilivät hänen jalkojaan ja kumartaen rukoilivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 10, 'Silloin Jeesus sanoi heille: \"Älkää peljätkö; menkää ja viekää sana minun veljilleni, että he menisivät Galileaan: siellä he saavat minut nähdä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 11, 'Mutta heidän mennessään, katso, muutamat vartijaväestä tulivat kaupunkiin ja ilmoittivat ylipapeille kaikki, mitä oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 12, 'Ja nämä kokoontuivat vanhinten kanssa ja pitivät neuvoa ja antoivat sotamiehille runsaat rahat');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 13, 'ja sanoivat: \"Sanokaa, että hänen opetuslapsensa tulivat yöllä ja veivät hänet varkain meidän nukkuessamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 14, 'Ja jos tämä tulee maaherran korviin, niin me lepytämme hänet ja toimitamme niin, että saatte olla huoletta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 15, 'Niin he ottivat rahat ja tekivät, niinkuin heitä oli neuvottu. Ja tätä puhetta on levitetty juutalaisten kesken, ja sitä kerrotaan vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 16, 'Ja ne yksitoista opetuslasta vaelsivat Galileaan sille vuorelle, jonne Jeesus oli käskenyt heidän mennä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 17, 'Ja kun he näkivät hänet, niin he kumartaen rukoilivat häntä, mutta muutamat epäilivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 18, 'Ja Jeesus tuli heidän tykönsä ja puhui heille ja sanoi: \"Minulle on annettu kaikki valta taivaassa ja maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 19, 'Menkää siis ja tehkää kaikki kansat minun opetuslapsikseni, kastamalla heitä Isän ja Pojan ja Pyhän Hengen nimeen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 28, 20, 'ja opettamalla heitä pitämään kaikki, mitä minä olen käskenyt teidän pitää. Ja katso, minä olen teidän kanssanne joka päivä maailman loppuun asti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Jeesuksen Kristuksen, Jumalan Pojan, evankeliumin alku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'Niinkuin on kirjoitettuna profeetta Esaiaan kirjassa: \"Katso, minä lähetän enkelini sinun edelläsi, ja hän on valmistava sinun tiesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, '\"Huutavan ääni kuuluu erämaassa: \'Valmistakaa Herralle tie, tehkää polut hänelle tasaisiksi\'\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'niin Johannes Kastaja saarnasi erämaassa parannuksen kastetta syntien anteeksisaamiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Ja koko Juudean maa ja kaikki jerusalemilaiset vaelsivat hänen tykönsä, ja hän kastoi heidät Jordanin virrassa, kun he tunnustivat syntinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Ja Johanneksella oli puku kamelinkarvoista ja vyötäisillään nahkavyö; ja hän söi heinäsirkkoja ja metsähunajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Ja hän saarnasi sanoen: \"Minun jälkeeni tulee minua väkevämpi, jonka kengänpaulaa minä en ole kelvollinen maahan kumartuneena päästämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Minä kastan teidät vedellä, mutta hän kastaa teidät Pyhällä Hengellä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Ja niinä päivinä Jeesus tuli Galilean Nasaretista, ja Johannes kastoi hänet Jordanissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Ja heti, vedestä noustessaan, hän näki taivasten aukeavan ja Hengen niinkuin kyyhkysen laskeutuvan häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Ja taivaista tuli ääni: \"Sinä olet minun rakas Poikani; sinuun minä olen mielistynyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Kohta sen jälkeen Henki ajoi hänet erämaahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Ja hän oli erämaassa neljäkymmentä päivää, ja saatana kiusasi häntä, ja hän oli petojen seassa; ja enkelit tekivät hänelle palvelusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Mutta sittenkuin Johannes oli pantu vankeuteen, meni Jeesus Galileaan ja saarnasi Jumalan evankeliumia');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 15, 'ja sanoi: \"Aika on täyttynyt, ja Jumalan valtakunta on tullut lähelle; tehkää parannus ja uskokaa evankeliumi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 16, 'Ja kulkiessaan Galilean järven rantaa hän näki Simonin ja Andreaan, Simonin veljen, heittävän verkkoa järveen; sillä he olivat kalastajia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 17, 'Ja Jeesus sanoi heille: \"Seuratkaa minua, niin minä teen teistä ihmisten kalastajia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 18, 'Kohta he jättivät verkot ja seurasivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 19, 'Ja käytyään siitä vähän eteenpäin hän näki Jaakobin, Sebedeuksen pojan, ja Johanneksen, hänen veljensä, heidätkin venheessä, laittamassa verkkojaan kuntoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 20, 'Ja kohta hän kutsui heidät; ja he jättivät isänsä, Sebedeuksen, palkkalaisineen venheeseen ja lähtivät seuraamaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 21, 'Ja he saapuivat Kapernaumiin; ja hän meni kohta sapattina synagoogaan ja opetti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 22, 'Ja he olivat hämmästyksissään hänen opetuksestansa, sillä hän opetti heitä niinkuin se, jolla valta on, eikä niinkuin kirjanoppineet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 23, 'Ja heidän synagoogassaan oli juuri silloin mies, jossa oli saastainen henki; ja se huusi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 24, 'sanoen: \"Mitä sinulla on meidän kanssamme tekemistä, Jeesus Nasaretilainen? Oletko tullut meitä tuhoamaan? Minä tunnen sinut, kuka olet, sinä Jumalan Pyhä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 25, 'Niin Jeesus nuhteli sitä sanoen: \"Vaikene ja lähde hänestä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 26, 'Ja saastainen henki kouristi häntä ja lähti hänestä huutaen suurella äänellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 27, 'Ja he hämmästyivät kaikki, niin että kyselivät toisiltaan sanoen: \"Mitä tämä on? Uusi, voimallinen oppi! Hän käskee saastaisia henkiäkin, ja ne tottelevat häntä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 28, 'Ja hänen maineensa levisi kohta koko ympäristöön, kaikkialle Galileaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 29, 'Ja tultuaan ulos synagoogasta he menivät kohta Simonin ja Andreaan taloon Jaakobin ja Johanneksen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 30, 'Ja Simonin anoppi makasi sairaana kuumeessa, ja kohta he puhuivat hänestä Jeesukselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 31, 'Ja hän meni hänen luoksensa ja nosti hänet ylös, tarttuen hänen käteensä; ja kuume lähti hänestä, ja hän palveli heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 32, 'Mutta illan tultua, kun aurinko oli laskenut, tuotiin hänen tykönsä kaikki sairaat ja riivatut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 33, 'ja koko kaupunki oli koolla oven edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 34, 'Ja hän paransi monta, jotka sairastivat moninaisia tauteja, ja paljon riivaajia hän ajoi ulos eikä sallinut riivaajien puhua, koska ne tunsivat hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 35, 'Ja varhain aamulla, kun vielä oli pimeä, hän nousi, lähti ulos ja meni autioon paikkaan; ja siellä hän rukoili.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 36, 'Mutta Simon ja ne, jotka olivat hänen kanssaan, riensivät hänen jälkeensä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 37, 'ja löydettyään hänet he sanoivat hänelle: \"Kaikki etsivät sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 38, 'Ja hän sanoi heille: \"Menkäämme muualle, läheisiin kyliin, että minä sielläkin saarnaisin, sillä sitä varten minä olen tullut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 39, 'Ja hän meni ja saarnasi heidän synagoogissaan koko Galileassa ja ajoi ulos riivaajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 40, 'Ja hänen tykönsä tuli pitalinen mies, rukoili häntä, polvistui ja sanoi hänelle: \"Jos tahdot, niin sinä voit minut puhdistaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 41, 'Niin Jeesuksen kävi häntä sääliksi, ja ojentaen kätensä hän kosketti häntä ja sanoi hänelle: \"Minä tahdon; puhdistu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 42, 'Ja kohta pitali lähti hänestä, ja hän puhdistui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 43, 'Ja varoittaen häntä ankarasti hän laski hänet heti menemään');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 44, 'ja sanoi hänelle: \"Katso, ettet puhu tästä kenellekään mitään, vaan mene ja näytä itsesi papille ja uhraa puhdistumisestasi se, minkä Mooses on säätänyt, todistukseksi heille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 45, 'Mutta mentyään pois tämä rupesi laajalti julistamaan ja asiasta tietoa levittämään, niin ettei Jeesus enää saattanut julkisesti mennä kaupunkeihin, vaan oleskeli niiden ulkopuolella autioissa paikoissa; ja kaikkialta tultiin hänen tykönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Ja muutamien päivien perästä hän taas meni Kapernaumiin; ja kun kuultiin hänen olevan kotona,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'kokoontui paljon väkeä, niin etteivät he enää mahtuneet oven edustallekaan. Ja hän puhui heille sanaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Ja he tulivat tuoden hänen tykönsä halvattua, jota kantamassa oli neljä miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Ja kun he väentungokselta eivät päässeet häntä tuomaan hänen tykönsä, purkivat he katon siltä kohdalta, missä hän oli, ja kaivettuaan aukon laskivat alas vuoteen, jossa halvattu makasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Kun Jeesus näki heidän uskonsa, sanoi hän halvatulle: \"Poikani, sinun syntisi annetaan anteeksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Mutta siellä istui muutamia kirjanoppineita, ja he ajattelivat sydämessään:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, '\"Kuinka tämä näin puhuu? Hän pilkkaa Jumalaa. Kuka voi antaa syntejä anteeksi paitsi Jumala yksin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Ja heti Jeesus tunsi hengessänsä, että he mielessään niin ajattelivat, ja sanoi heille: \"Miksi ajattelette sellaista sydämessänne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Kumpi on helpompaa, sanoako halvatulle: \'Sinun syntisi annetaan anteeksi\', vai sanoa: \'Nouse, ota vuoteesi ja käy\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Mutta tietääksenne, että Ihmisen Pojalla on valta maan päällä antaa syntejä anteeksi, niin\" -hän sanoi halvatulle-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, '\"minä sanon sinulle: nouse, ota vuoteesi ja mene kotiisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Silloin hän nousi, otti kohta vuoteensa ja meni ulos kaikkien nähden, niin että kaikki hämmästyivät ja ylistivät Jumalaa sanoen: \"Tämänkaltaista emme ole ikinä nähneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Ja taas hän lähti pois ja kulki järven rantaa. Ja kaikki kansa tuli hänen tykönsä, ja hän opetti heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Ja ohi kulkiessaan hän näki Leevin, Alfeuksen pojan, istumassa tulliasemalla ja sanoi hänelle: \"Seuraa minua\". Niin tämä nousi ja seurasi häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'Ja kun hän aterioi hänen kodissaan, aterioi myös monta publikaania ja syntistä Jeesuksen ja hänen opetuslastensa kanssa; sillä heitä oli paljon häntä seuraamassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Kun fariseusten kirjanoppineet näkivät, että hän söi syntisten ja publikaanien kanssa, sanoivat he hänen opetuslapsilleen: \"Publikaanien ja syntistenkö kanssa hän syö?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Sen kuullessaan Jeesus sanoi heille: \"Eivät terveet tarvitse parantajaa, vaan sairaat. En minä ole tullut kutsumaan vanhurskaita, vaan syntisiä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Ja Johanneksen opetuslapset ja fariseukset pitivät paastoa. Niin tultiin ja sanottiin hänelle: \"Johanneksen opetuslapset ja fariseusten opetuslapset paastoavat; miksi sinun opetuslapsesi eivät paastoa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 19, 'Jeesus sanoi heille: \"Eiväthän häävieraat voi paastota silloin, kun ylkä on heidän kanssaan? Niin kauan kuin heillä on ylkä seurassaan, eivät he voi paastota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 20, 'Mutta päivät tulevat, jolloin ylkä otetaan heiltä pois, ja silloin, sinä päivänä, he paastoavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 21, 'Ei kukaan ompele vanuttamattomasta kankaasta paikkaa vanhaan vaippaan; muutoin uusi täytetilkku repii palasen vanhasta vaipasta, ja reikä tulee pahemmaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 22, 'Eikä kukaan laske nuorta viiniä vanhoihin nahkaleileihin; muutoin viini pakahuttaa leilit, ja viini menee hukkaan, ja leilit turmeltuvat; vaan nuori viini on laskettava uusiin leileihin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 23, 'Ja tapahtui, että hän sapattina kulki viljavainioiden halki, ja hänen opetuslapsensa rupesivat kulkiessaan katkomaan tähkäpäitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 24, 'Niin fariseukset sanoivat hänelle: \"Katso, miksi he tekevät sapattina sitä, mikä ei ole luvallista?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 25, 'Hän sanoi heille: \"Ettekö ole koskaan lukeneet, mitä Daavid teki, kun hän ja hänen seuralaisensa olivat puutteessa ja heidän oli nälkä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 26, 'kuinka hän meni Jumalan huoneeseen ylimmäisen papin Abjatarin aikana ja söi näkyleivät, joita ei ollut lupa syödä muiden kuin pappien, ja antoi myös niille, jotka hänen kanssansa olivat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 27, 'Ja hän sanoi heille: \"Sapatti on asetettu ihmistä varten eikä ihminen sapattia varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 28, 'Niin Ihmisen Poika siis on sapatinkin herra.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Ja hän meni taas synagoogaan, ja siellä oli mies, jonka käsi oli kuivettunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Ja voidakseen nostaa syytteen häntä vastaan he pitivät häntä silmällä, parantaisiko hän miehen sapattina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Niin hän sanoi miehelle, jonka käsi oli kuivettunut: \"Nouse ja astu esille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Ja hän sanoi heille: \"Kumpiko on luvallista sapattina: hyvääkö tehdä vai pahaa, pelastaako henki vai tappaa se?\" Mutta he olivat vaiti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Silloin hän katsahtaen ympärilleen loi vihassa silmänsä heihin, murheellisena heidän sydämensä paatumuksesta, ja sanoi sille miehelle: \"Ojenna kätesi\". Ja hän ojensi, ja hänen kätensä tuli jälleen terveeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Ja fariseukset lähtivät ulos ja pitivät kohta herodilaisten kanssa neuvoa häntä vastaan, surmataksensa hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Mutta Jeesus vetäytyi opetuslapsineen järven rannalle, ja häntä seurasi suuri joukko kansaa Galileasta. Ja Juudeasta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'ja Jerusalemista ja Idumeasta ja Jordanin tuolta puolen ja Tyyron ja Siidonin ympäristöltä tuli paljon kansaa hänen tykönsä, kun he kuulivat, kuinka suuria tekoja hän teki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Ja hän sanoi opetuslapsillensa, että hänelle oli pidettävä venhe varalla väentungoksen tähden, etteivät he ahdistaisi häntä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'sillä hän paransi monta, jonka tähden kaikki, joilla oli vaivoja, tunkeutuivat hänen päälleen koskettaaksensa häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Ja kun saastaiset henget näkivät hänet, lankesivat he maahan hänen eteensä ja huusivat sanoen: \"Sinä olet Jumalan Poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Ja hän varoitti ankarasti heitä saattamasta häntä julki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Ja hän nousi vuorelle ja kutsui tykönsä ne, jotka hän itse tahtoi, ja he menivät hänen tykönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Niin hän asetti kaksitoista olemaan kanssansa ja lähettääksensä heidät saarnaamaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'ja heillä oli oleva valta ajaa ulos riivaajia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Ja nämä kaksitoista hän asetti: Pietarin-tämän nimen hän antoi Simonille-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'ja Jaakobin, Sebedeuksen pojan, ja Johanneksen, Jaakobin veljen, joille hän antoi nimen Boanerges, se on: ukkosenjylinän pojat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'ja Andreaan ja Filippuksen ja Bartolomeuksen ja Matteuksen ja Tuomaan ja Jaakobin, Alfeuksen pojan, ja Taddeuksen ja Simon Kananeuksen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'ja Juudas Iskariotin, saman, joka hänet kavalsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 20, 'Ja hän tuli kotiin. Ja taas kokoontui kansaa, niin etteivät he päässeet syömäänkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 21, 'Kun hänen omaisensa sen kuulivat, menivät he ottamaan häntä huostaansa; sillä he sanoivat: \"Hän on poissa suunniltaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 22, 'Ja kirjanoppineet, jotka olivat tulleet Jerusalemista, sanoivat: \"Hänessä on Beelsebul\", ja: \"Riivaajien päämiehen voimalla hän ajaa ulos riivaajia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 23, 'Niin hän kutsui heidät luoksensa ja sanoi heille vertauksilla: \"Kuinka saatana voi ajaa ulos saatanan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 24, 'Ja jos jokin valtakunta riitautuu itsensä kanssa, ei se valtakunta voi pysyä pystyssä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 25, 'Ja jos jokin talo riitautuu itsensä kanssa, ei se talo voi pysyä pystyssä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 26, 'Ja jos saatana nousee itseänsä vastaan ja riitautuu itsensä kanssa, ei hän voi pysyä, vaan hänen loppunsa on tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 27, 'Eihän kukaan voi tunkeutua väkevän taloon ja ryöstää hänen tavaraansa, ellei hän ensin sido sitä väkevää; vasta sitten hän ryöstää tyhjäksi hänen talonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 28, 'Totisesti minä sanon teille: kaikki synnit annetaan ihmisten lapsille anteeksi, pilkkaamisetkin, kuinka paljon pilkannevatkin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 29, 'mutta joka pilkkaa Pyhää Henkeä, se ei saa ikinä anteeksi, vaan on vikapää iankaikkiseen syntiin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 30, 'Sillä he sanoivat: \"Hänessä on saastainen henki\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 31, 'Ja hänen äitinsä ja veljensä tulivat, seisahtuivat ulkopuolelle ja lähettivät hänen luoksensa kutsumaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 32, 'Ja kansanjoukko istui hänen ympärillään, ja he sanoivat hänelle: \"Katso, sinun äitisi ja veljesi tuolla ulkona kysyvät sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 33, 'Hän vastasi heille ja sanoi: \"Kuka on minun äitini, ja ketkä ovat minun veljeni?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 34, 'Ja katsellen ympärilleen niihin, jotka istuivat hänen ympärillään, hän sanoi: \"Katso, minun äitini ja veljeni!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 35, 'Sillä joka tekee Jumalan tahdon, se on minun veljeni ja sisareni ja äitini.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Ja hän rupesi taas opettamaan järven rannalla. Ja hänen luoksensa kokoontui hyvin paljon kansaa, jonka tähden hän astui venheeseen ja istui siinä järvellä, ja kaikki kansa oli maalla järven rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Ja hän opetti heitä paljon vertauksilla ja sanoi heille opettaessaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, '\"Kuulkaa! Katso, kylväjä lähti kylvämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Ja hänen kylväessään osa putosi tien oheen, ja linnut tulivat ja söivät sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Ja osa putosi kallioperälle, jossa sillä ei ollut paljon maata, ja se nousi kohta oraalle, kun sillä ei ollut syvää maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Mutta auringon noustua se paahtui, ja kun sillä ei ollut juurta, niin se kuivettui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Ja osa putosi orjantappuroihin; ja orjantappurat nousivat ja tukahuttivat sen, eikä se tehnyt hedelmää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Ja osa putosi hyvään maahan; ja se nousi oraalle, kasvoi ja antoi sadon ja kantoi kolmeenkymmeneen ja kuuteenkymmeneen ja sataan jyvään asti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Ja hän sanoi: \"Jolla on korvat kuulla, se kuulkoon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Ja kun hän oli jäänyt yksin, niin ne, jotka olivat hänen ympärillään, ynnä ne kaksitoista kysyivät häneltä näitä vertauksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Niin hän sanoi heille: \"Teille on annettu Jumalan valtakunnan salaisuus, mutta noille ulkopuolella oleville kaikki tulee vertauksissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'että he näkemällä näkisivät, eivätkä huomaisi, ja kuulemalla kuulisivat, eivätkä ymmärtäisi, niin etteivät kääntyisi ja saisi anteeksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Ja hän sanoi heille: \"Ette käsitä tätä vertausta; kuinka sitten voitte ymmärtää kaikki muut vertaukset?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Kylväjä kylvää sanan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Mitkä tien oheen putosivat, ovat ne, joihin sana kylvetään, mutta kun he sen kuulevat, niin saatana heti tulee ja ottaa pois heihin kylvetyn sanan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Ja mitkä kallioperälle kylvettiin, ovat niinikään ne, jotka, kun kuulevat sanan, heti ottavat sen ilolla vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 17, 'mutta heillä ei ole juurta itsessään, vaan he kestävät ainoastaan jonkun aikaa; kun sitten tulee ahdistus tai vaino sanan tähden, niin he kohta lankeavat pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 18, 'Ja toisia ovat orjantappuroihin kylvetyt; nämä ovat ne, jotka kuulevat sanan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 19, 'mutta maailman huolet ja rikkauden viettelys ja muut himot pääsevät valtaan ja tukahuttavat sanan, ja se jää hedelmättömäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 20, 'Ja mitkä hyvään maahan kylvettiin, ovat ne, jotka kuulevat sanan ja ottavat sen vastaan ja kantavat hedelmän, mikä kolmikymmen-,mikä kuusikymmen-,mikä satakertaisen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 21, 'Ja hän sanoi heille: \"Eihän lamppua oteta esiin, pantavaksi vakan alle tai vuoteen alle? Eiköhän lampunjalkaan pantavaksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 22, 'Sillä ei mikään ole salattuna muuta varten, kuin että se tulisi ilmi, eikä kätkettynä muuta varten, kuin tullakseen julki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 23, 'Jos jollakin on korvat kuulla, hän kuulkoon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 24, 'Ja hän sanoi heille: \"Ottakaa vaari siitä, mitä kuulette; millä mitalla te mittaatte, sillä teille mitataan, vieläpä teille lisätäänkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 25, 'Sillä sille jolla on, sille annetaan; mutta siltä, jolla ei ole, otetaan pois sekin, mikä hänellä on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 26, 'Ja hän sanoi: \"Niin on Jumalan valtakunta, kuin jos mies kylvää siemenen maahan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 27, 'ja hän nukkuu, ja hän nousee, öin ja päivin; ja siemen orastaa ja kasvaa, hän ei itse tiedä, miten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 28, 'Sillä itsestään maa tuottaa viljan: ensin korren, sitten tähkän, sitten täyden jyvän tähkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 29, 'Mutta kun hedelmä on kypsynyt, lähettää hän kohta sinne sirpin, sillä elonaika on käsissä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 30, 'Ja hän sanoi: \"Mihin vertaamme Jumalan valtakunnan, eli mitä vertausta siitä käytämme?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 31, 'Se on niinkuin sinapinsiemen, joka, kun se kylvetään maahan, on pienin kaikista siemenistä maan päällä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 32, 'mutta kun se on kylvetty, niin se nousee ja tulee suurimmaksi kaikista vihanneskasveista ja tekee suuria oksia, niin että taivaan linnut voivat tehdä pesänsä sen varjoon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 33, 'Monilla tämänkaltaisilla vertauksilla hän puhui heille sanaa, sen mukaan kuin he kykenivät kuulemaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 34, 'ja ilman vertausta hän ei puhunut heille. Mutta opetuslapsillensa hän selitti kaikki, kun he olivat yksikseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 35, 'Ja sinä päivänä hän illan tultua sanoi heille: \"Lähtekäämme yli toiselle rannalle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 36, 'Niin he laskivat kansan luotaan ja ottivat hänet mukaansa, niinkuin hän venheessä oli; ja muitakin venheitä oli hänen seurassaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 37, 'Ja nousi kova myrskytuuli, ja aallot syöksyivät venheeseen, niin että venhe jo täyttyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 38, 'Ja itse hän oli peräkeulassa ja nukkui nojaten päänaluseen. Ja he herättivät hänet ja sanoivat hänelle: \"Opettaja, etkö välitä siitä, että me hukumme?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 39, 'Ja herättyään hän nuhteli tuulta ja sanoi järvelle: \"Vaikene, ole hiljaa\". Niin tuuli asettui, ja tuli aivan tyven.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 40, 'Ja hän sanoi heille: \"Miksi olette niin pelkureita? Kuinka teillä ei ole uskoa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 41, 'Ja suuri pelko valtasi heidät, ja he sanoivat toisillensa: \"Kuka onkaan tämä, kun sekä tuuli että meri häntä tottelevat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Ja he tulivat toiselle puolelle järveä gerasalaisten alueelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Ja kohta kun hän lähti venheestä, tuli häntä vastaan haudoista mies, joka oli saastaisen hengen vallassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Hän asusti haudoissa, eikä kukaan enää voinut häntä kahleillakaan sitoa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'sillä hän oli monta kertaa ollut sidottuna jalkanuoriin ja kahleisiin, mutta oli särkenyt kahleet ja katkonut jalkanuorat, eikä kukaan kyennyt häntä hillitsemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Ja hän oleskeli aina, yötä ja päivää, haudoissa ja vuorilla, huutaen ja runnellen itseään kivillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Kun hän kaukaa näki Jeesuksen, juoksi hän ja kumartui maahan hänen eteensä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'ja huutaen suurella äänellä sanoi: \"Mitä sinulla on minun kanssani tekemistä, Jeesus, Jumalan, Korkeimman, Poika? Minä vannotan sinua Jumalan kautta, älä vaivaa minua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Sillä hän oli sanomaisillaan sille: \"Lähde ulos miehestä, sinä saastainen henki\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'Ja Jeesus kysyi siltä: \"Mikä on nimesi?\" Niin se sanoi hänelle: \"Legio on minun nimeni, sillä meitä on monta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Ja se pyysi pyytämällä häntä, ettei hän lähettäisi niitä pois siitä seudusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Niin siellä oli lähellä vuorta suuri sikalauma laitumella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Ja ne pyysivät häntä sanoen: \"Lähetä meidät sikoihin, että menisimme niihin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Ja hän antoi niille luvan. Niin saastaiset henget lähtivät miehestä ja menivät sikoihin. Silloin lauma, noin kaksituhatta sikaa, syöksyi jyrkännettä alas järveen; ja ne hukkuivat järveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Ja niiden paimentajat pakenivat ja kertoivat siitä kaupungissa ja maataloissa. Ja kansa lähti katsomaan, mitä oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 15, 'Ja he tulivat Jeesuksen luo ja näkivät riivatun, jossa legio oli ollut, istuvan puettuna ja täydessä ymmärryksessään; ja he peljästyivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 16, 'Näille kertoivat näkijät, mitä oli tapahtunut riivatulle ja kuinka sikojen oli käynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 17, 'Ja he alkoivat pyytää häntä poistumaan heidän alueeltaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 18, 'Ja hänen astuessaan venheeseen se riivattuna ollut pyysi häneltä saada olla hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 19, 'Mutta hän ei sitä sallinut, vaan sanoi hänelle: \"Mene kotiisi omaistesi luo ja kerro heille, kuinka suuria tekoja Herra on sinulle tehnyt ja kuinka hän on sinua armahtanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 20, 'Niin hän lähti ja rupesi Dekapolin alueella julistamaan, kuinka suuria tekoja Jeesus oli hänelle tehnyt; ja kaikki ihmettelivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 21, 'Kun Jeesus oli venheellä kulkenut takaisin toiselle puolelle, kokoontui paljon kansaa hänen luoksensa, ja hän oli järven rannalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 22, 'Niin tuli muuan synagoogan esimies, nimeltä Jairus, ja lankesi hänet nähdessään hänen jalkojensa juureen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 23, 'pyysi häntä hartaasti ja sanoi: \"Pieni tyttäreni on kuolemaisillaan; tule ja pane kätesi hänen päällensä, että hän tulisi terveeksi ja jäisi eloon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 24, 'Niin hän lähti hänen kanssansa. Ja häntä seurasi suuri kansan paljous, ja he tunkeutuivat hänen ympärilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 25, 'Ja siellä oli nainen, joka oli sairastanut verenjuoksua kaksitoista vuotta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 26, 'ja paljon kärsinyt monen lääkärin käsissä ja kuluttanut kaiken omaisuutensa saamatta mitään apua, pikemminkin käyden huonommaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 27, 'Tämä oli kuullut Jeesuksesta ja tuli kansanjoukossa takaapäin ja koski hänen vaippaansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 28, 'sillä hän sanoi: \"Kunhan vain saan koskettaa edes hänen vaatteitaan, niin tulen terveeksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 29, 'Ja heti hänen verensä lähde kuivui, ja hän tunsi ruumiissansa, että oli parantunut vaivastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 30, 'Ja heti kun Jeesus itsessään tunsi, että voimaa oli hänestä lähtenyt, kääntyi hän väkijoukossa ja sanoi: \"Kuka koski minun vaatteisiini?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 31, 'Niin hänen opetuslapsensa sanoivat hänelle: \"Sinä näet kansanjoukon tungeskelevan ympärilläsi ja sanot: \'Kuka minuun koski?\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 32, 'Mutta hän katseli ympärilleen nähdäksensä, kuka sen oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 33, 'Niin nainen pelkäsi ja vapisi, koska hän tiesi, mitä hänelle oli tapahtunut, ja tuli ja lankesi maahan hänen eteensä ja sanoi hänelle koko totuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 34, 'Mutta Jeesus sanoi hänelle: \"Tyttäreni, sinun uskosi on tehnyt sinut terveeksi. Mene rauhaan ja ole terve vaivastasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 35, 'Hänen vielä puhuessaan tultiin synagoogan esimiehen kotoa sanomaan: \"Tyttäresi kuoli; miksi enää opettajaa vaivaat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 36, 'Mutta Jeesus ei ottanut kuullakseen, mitä puhuttiin, vaan sanoi synagoogan esimiehelle: \"Älä pelkää, usko ainoastaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 37, 'Ja hän ei sallinut kenenkään muun seurata mukanansa kuin Pietarin ja Jaakobin ja Johanneksen, Jaakobin veljen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 38, 'Ja he tulivat synagoogan esimiehen taloon; ja hän näki hälisevän joukon ja ääneensä itkeviä ja vaikeroivia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 39, 'Ja käydessään sisään hän sanoi heille: \"Mitä te hälisette ja itkette? Lapsi ei ole kuollut, vaan nukkuu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 40, 'Niin he nauroivat häntä. Mutta hän ajoi kaikki ulos ja otti mukaansa lapsen isän ja äidin sekä ne, jotka olivat hänen kanssaan, ja meni sisälle sinne, missä lapsi makasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 41, 'Ja hän tarttui lapsen käteen ja sanoi hänelle: \"Talita kuum!\" Se on käännettynä: Tyttö, minä sanon sinulle, nouse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 42, 'Ja heti tyttö nousi ja käveli. Sillä hän oli kaksitoistavuotias. Ja he joutuivat suuren hämmästyksen valtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 43, 'Ja hän kielsi ankarasti heitä antamasta kenellekään tietoa tästä ja käski antaa tytölle syötävää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Ja hän lähti sieltä ja meni kotikaupunkiinsa, ja hänen opetuslapsensa seurasivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Ja kun tuli sapatti, rupesi hän opettamaan synagoogassa; ja häntä kuullessaan monet hämmästyivät ja sanoivat: \"Mistä tällä on kaikki tämä, ja mikä on se viisaus, joka on hänelle annettu? Ja mitä senkaltaiset voimalliset teot, jotka tapahtuvat hänen kättensä kautta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Eikö tämä ole se rakentaja, Marian poika ja Jaakobin ja Jooseen ja Juudaan ja Simonin veli? Ja eivätkö hänen sisarensa ole täällä meidän parissamme?\" Ja he loukkaantuivat häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Niin Jeesus sanoi heille: \"Ei ole profeetta halveksittu muualla kuin kotikaupungissaan ja sukulaistensa kesken ja kodissaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'Ja hän ei voinut siellä tehdä mitään voimallista tekoa, paitsi että paransi joitakuita sairaita panemalla kätensä heidän päälleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'Ja hän ihmetteli heidän epäuskoansa. Ja hän vaelsi ympäristössä, kulkien kylästä kylään, ja opetti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Ja hän kutsui tykönsä ne kaksitoista ja alkoi lähettää heitä kaksittain ja antoi heille vallan saastaisia henkiä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Ja hän sääti heille, etteivät saaneet ottaa matkalle muuta kuin ainoastaan sauvan; ei leipää, ei laukkua, ei rahaa vyöhönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'He saivat kuitenkin sitoa paula-anturat jalkaansa; \"mutta älkää pukeko kahta ihokasta yllenne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Ja hän sanoi heille: \"Missä tulette taloon, jääkää siihen, kunnes lähdette pois siltä paikkakunnalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Ja missä paikassa teitä ei oteta vastaan eikä teitä kuulla, sieltä menkää pois ja pudistakaa tomu jalkojenne alta, todistukseksi heille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Niin he lähtivät ja saarnasivat, että oli tehtävä parannus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Ja he ajoivat ulos monta riivaajaa ja voitelivat monta sairasta öljyllä ja paransivat heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Ja kuningas Herodes sai kuulla hänestä, sillä hänen nimensä oli tullut tunnetuksi, ja ihmiset sanoivat: \"Johannes Kastaja on noussut kuolleista, ja sentähden nämä voimat hänessä vaikuttavat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Mutta toiset sanoivat: \"Se on Elias\"; toiset taas sanoivat: \"Se on profeetta, niinkuin joku muukin profeetoista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Mutta kun Herodes sen kuuli, sanoi hän: \"Johannes, jonka minä mestautin, on noussut kuolleista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Sillä hän, Herodes, oli lähettänyt ottamaan kiinni Johanneksen, sitonut ja pannut hänet vankeuteen veljensä Filippuksen vaimon, Herodiaan, tähden. Sillä Herodes oli nainut hänet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'ja Johannes oli sanonut Herodekselle: \"Sinun ei ole lupa pitää veljesi vaimoa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Ja Herodias piti vihaa häntä vastaan ja tahtoi tappaa hänet, mutta ei voinut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Sillä Herodes pelkäsi Johannesta, koska tiesi hänet vanhurskaaksi ja pyhäksi mieheksi, ja suojeli häntä. Ja kun hän kuunteli häntä, tuli hän epäröivälle mielelle monesta asiasta; ja hän kuunteli häntä mielellään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 21, 'Niin tuli sopiva päivä, kun Herodes syntymäpäivänään piti pitoja ylimyksilleen ja sotapäälliköille ja Galilean ensimmäisille miehille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 22, 'Ja Herodiaan tytär tuli sisälle ja tanssi, ja se miellytti Herodesta ja hänen pöytävieraitaan. Niin kuningas sanoi tytölle: \"Ano minulta, mitä ikinä tahdot, niin minä annan sinulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 23, 'Ja hän vannoi tytölle: \"Mitä ikinä minulta anot, sen minä annan sinulle, vaikka puolet valtakuntaani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 24, 'Niin hän meni ulos ja sanoi äidilleen: \"Mitä minä anon?\" Tämä sanoi: \"Johannes Kastajan päätä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 25, 'Ja hän meni kohta kiiruusti sisälle kuninkaan luo, pyysi ja sanoi: \"Minä tahdon, että nyt heti annat minulle lautasella Johannes Kastajan pään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 26, 'Silloin kuningas tuli hyvin murheelliseksi, mutta valansa ja pöytävierasten tähden hän ei tahtonut hyljätä hänen pyyntöään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 27, 'Ja kohta kuningas lähetti henkivartijan ja käski tuoda Johanneksen pään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 28, 'Niin vartija meni ja löi häneltä pään poikki vankilassa ja toi hänen päänsä lautasella ja antoi sen tytölle, ja tyttö antoi sen äidillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 29, 'Kun hänen opetuslapsensa sen kuulivat, tulivat he ja ottivat hänen ruumiinsa ja panivat sen hautaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 30, 'Ja apostolit kokoontuivat Jeesuksen tykö ja kertoivat hänelle kaikki, mitä olivat tehneet ja mitä olivat opettaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 31, 'Niin hän sanoi heille: \"Tulkaa te yksinäisyyteen, autioon paikkaan, ja levähtäkää vähän\". Sillä tulijoita ja menijöitä oli paljon, ja heillä ei ollut aikaa syödäkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 32, 'Ja he lähtivät venheellä autioon paikkaan, yksinäisyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 33, 'Ja he näkivät heidän lähtevän, ja monet saivat siitä tiedon ja riensivät sinne jalkaisin kaikista kaupungeista ja saapuivat ennen heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 34, 'Ja astuessaan maihin hän näki paljon kansaa, ja hänen kävi heitä sääliksi, koska he olivat niinkuin lampaat, joilla ei ole paimenta, ja hän rupesi opettamaan heille moninaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 35, 'Ja kun päivä jo oli pitkälle kulunut, menivät hänen opetuslapsensa hänen tykönsä ja sanoivat: \"Tämä paikka on autio, ja aika on jo myöhäinen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 36, 'laske heidät luotasi, että he menisivät ympäristöllä oleviin maataloihin ja kyliin ostamaan itsellensä syötävää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 37, 'Mutta hän vastasi heille ja sanoi: \"Antakaa te heille syödä\". Niin he sanoivat hänelle: \"Lähdemmekö ostamaan leipää kahdellasadalla denarilla antaaksemme heille syödä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 38, 'Mutta hän sanoi heille: \"Montako leipää teillä on? Menkää katsomaan.\" Otettuaan siitä selvän he sanoivat: \"Viisi, ja kaksi kalaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 39, 'Niin hän määräsi heille, että kaikkien oli asetuttava ruokakunnittain vihantaan ruohikkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 40, 'Ja he laskeutuivat ryhmä ryhmän viereen, toisiin sata, toisiin viisikymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 41, 'Ja hän otti ne viisi leipää ja kaksi kalaa, katsoi ylös taivaaseen ja siunasi ja mursi leivät ja antoi ne opetuslapsilleen kansan eteen pantaviksi; myöskin ne kaksi kalaa hän jakoi kaikille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 42, 'Ja kaikki söivät ja tulivat ravituiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 43, 'Sitten he keräsivät palaset, kaksitoista täyttä vakallista, ja tähteet kaloista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 44, 'Ja niitä, jotka olivat syöneet näitä leipiä, oli viisituhatta miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 45, 'Ja kohta hän vaati opetuslapsiansa astumaan venheeseen ja kulkemaan edeltä toiselle rannalle, Beetsaidaan, sillä aikaa kuin hän laski kansan luotansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 46, 'Ja sanottuaan heille jäähyväiset hän meni pois vuorelle rukoilemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 47, 'Ja kun ilta tuli, oli venhe keskellä järveä, ja hän oli yksinään maalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 48, 'Ja kun hän näki heidän soutaessaan olevan hädässä, sillä tuuli oli heille vastainen, tuli hän neljännen yövartion vaiheilla heidän luoksensa kävellen järven päällä ja aikoi kulkea heidän ohitsensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 49, 'Mutta nähdessään hänen kävelevän järven päällä he luulivat häntä aaveeksi ja rupesivat huutamaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 50, 'sillä kaikki näkivät hänet ja peljästyivät. Mutta heti hän puhutteli heitä ja sanoi heille: \"Olkaa turvallisella mielellä, minä se olen; älkää peljätkö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 51, 'Ja hän astui venheeseen heidän tykönsä, ja tuuli asettui. Niin he hämmästyivät ylen suuresti sydämessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 52, 'Sillä he eivät olleet noista leivistäkään päässeet ymmärrykseen, vaan heidän sydämensä oli paatunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 53, 'Ja kuljettuaan yli toiselle rannalle he tulivat Gennesaretiin ja laskivat maihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 54, 'Ja heidän noustessaan venheestä kansa heti tunsi hänet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 55, 'ja he riensivät kiertämään koko sitä paikkakuntaa ja rupesivat vuoteilla kantamaan sairaita sinne, missä kuulivat hänen olevan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 56, 'Ja missä vain hän meni kyliin tai kaupunkeihin tai maataloihin, asetettiin sairaat aukeille paikoille ja pyydettiin häneltä, että he saisivat koskea edes hänen vaippansa tupsuun. Ja kaikki, jotka koskivat häneen, tulivat terveiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Ja fariseukset ja muutamat kirjanoppineet, jotka olivat tulleet Jerusalemista, kokoontuivat hänen luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Ja he näkivät, että muutamat hänen opetuslapsistaan söivät leipää epäpuhtailla, se on pesemättömillä, käsillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Sillä eivät fariseukset eivätkä ketkään juutalaiset syö, ennenkuin ovat tarkoin pesseet kätensä, noudattaen vanhinten perinnäissääntöä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'ja torilta tultuaan he eivät syö, ennenkuin ovat itseään vedellä vihmoneet; ja paljon muuta on, mitä he ovat ottaneet noudattaakseen, niinkuin maljain ja kiviastiain ja vaskiastiain pesemisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Niin fariseukset ja kirjanoppineet kysyivät häneltä: \"Miksi sinun opetuslapsesi eivät vaella vanhinten perinnäissäännön mukaan, vaan syövät leipää epäpuhtailla käsillä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Mutta hän sanoi heille: \"Oikein Esaias on ennustanut teistä, ulkokullatuista, niinkuin kirjoitettu on: \'Tämä kansa kunnioittaa minua huulillaan, mutta heidän sydämensä on minusta kaukana;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'mutta turhaan he palvelevat minua opettaen oppeja, jotka ovat ihmiskäskyjä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Te hylkäätte Jumalan käskyn ja noudatatte ihmisten perinnäissääntöä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Ja hän sanoi heille: \"Hyvin te kumoatte Jumalan käskyn noudattaaksenne omaa perinnäissääntöänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Sillä Mooses on sanonut: \'Kunnioita isääsi ja äitiäsi\', ja: \'Joka kiroaa isäänsä tai äitiänsä, sen pitää kuolemalla kuoleman\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Mutta te sanotte, että jos ihminen sanoo isälleen tai äidilleen: \'Se, minkä sinä olisit saava minulta hyväksesi, on korban\' -se on uhrilahja--');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'ja niin te ette enää salli hänen antaa mitään avustusta isälleen tai äidilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Te teette Jumalan sanan tyhjäksi perinnäissäännöllänne, jonka olette säätäneet. Ja paljon muuta samankaltaista te teette.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Ja hän kutsui taas kansan tykönsä ja sanoi heille: \"Kuulkaa minua kaikki ja ymmärtäkää:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'ei mikään, mikä ihmisen ulkopuolelta menee hänen sisäänsä, voi häntä saastuttaa, vaan mikä ihmisestä lähtee ulos, se saastuttaa ihmisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'Jos jollakin on korvat kuulla, hän kuulkoon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Ja kun hän kansasta erottuaan oli mennyt erääseen taloon, kysyivät hänen opetuslapsensa häneltä sitä vertausta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Ja hän sanoi heille: \"Niinkö ymmärtämättömiä tekin olette? Ettekö käsitä, ettei mikään, mikä ulkoapäin menee ihmiseen, voi häntä saastuttaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Sillä se ei mene hänen sydämeensä, vaan vatsaan, ja ulostuu.\" Näin hän sanoi kaikki ruuat puhtaiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Ja hän sanoi: \"Mikä ihmisestä lähtee ulos, se saastuttaa ihmisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'Sillä sisästä, ihmisten sydämestä, lähtevät pahat ajatukset, haureudet, varkaudet, murhat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'aviorikokset, ahneus, häijyys, petollisuus, irstaus, pahansuonti, jumalanpilkka, ylpeys, mielettömyys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Kaikki tämä paha lähtee sisästä ulos ja saastuttaa ihmisen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Ja hän nousi ja lähti sieltä Tyyron ja Siidonin alueelle. Ja hän meni erääseen taloon eikä tahtonut, että kukaan saisi sitä tietää; mutta hän ei saanut olla salassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'vaan heti kun eräs vaimo, jonka pienessä tyttäressä oli saastainen henki, kuuli hänestä, tuli hän ja lankesi hänen jalkojensa juureen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Ja se vaimo oli kreikatar, syntyään syyrofoinikialainen; ja hän pyysi häntä ajamaan ulos riivaajan hänen tyttärestään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Niin Jeesus sanoi hänelle: \"Anna ensin lasten tulla ravituiksi; sillä ei ole soveliasta ottaa lasten leipää ja heittää penikoille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Mutta hän vastasi ja sanoi hänelle: \"Niin, Herra; mutta syöväthän penikatkin pöydän alla lasten muruja\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 29, 'Ja hän sanoi vaimolle: \"Tämän sanan tähden, mene; riivaaja on lähtenyt sinun tyttärestäsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 30, 'Ja vaimo meni kotiinsa ja havaitsi lapsen makaavan vuoteella ja riivaajan lähteneen hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 31, 'Ja hän lähti jälleen Tyyron alueelta ja kulkien Siidonin kautta tuli Galilean järven ääreen Dekapolin alueen keskitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 32, 'Ja hänen tykönsä tuotiin kuuro, joka oli melkein mykkä, ja he pyysivät häntä panemaan kätensä hänen päälleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 33, 'Niin hän otti hänet erilleen kansasta, pisti sormensa hänen korviinsa, sylki ja koski hänen kieleensä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 34, 'ja katsahti ylös taivaaseen, huokasi ja sanoi hänelle: \"Effata\", se on: aukene.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 35, 'Niin hänen korvansa aukenivat, ja hänen kielensä side irtautui, ja hän puhui selkeästi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 36, 'Ja Jeesus kielsi heitä sitä kenellekään sanomasta; mutta mitä enemmän hän heitä kielsi, sitä enemmän he julistivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 37, 'Ja ihmiset hämmästyivät ylenmäärin ja sanoivat: \"Hyvin hän on kaikki tehnyt: kuurot hän saa kuulemaan ja mykät puhumaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Niinä päivinä, kun paljon kansaa taas oli koolla eikä heillä ollut mitään syötävää, kutsui hän opetuslapsensa tykönsä ja sanoi heille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, '\"Minun käy sääliksi kansaa, sillä he ovat jo kolme päivää olleet minun tykönäni, eikä heillä ole mitään syötävää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Ja jos minä lasken heidät menemään syömättä kotiinsa, niin he nääntyvät matkalla; sillä muutamat heistä ovat tulleet kaukaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Niin hänen opetuslapsensa vastasivat hänelle: \"Mistä täällä erämaassa kukaan voi saada leipää näiden ravitsemiseksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Hän kysyi heiltä: \"Montako leipää teillä on?\" He sanoivat: \"Seitsemän\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Silloin hän käski kansan asettua maahan. Ja hän otti ne seitsemän leipää, kiitti, mursi ja antoi opetuslapsillensa, että he panisivat ne kansan eteen. Ja he panivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Heillä oli myös joitakuita kalasia; ja siunattuaan ne hän käski panna nekin kansan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Niin he söivät ja tulivat ravituiksi. Sitten he keräsivät jääneet palaset, seitsemän vasullista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Ja heitä oli noin neljätuhatta. Ja hän laski heidät luotansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Ja kohta hän astui opetuslapsineen venheeseen ja meni Dalmanutan seuduille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Ja fariseukset lähtivät sinne ja rupesivat väittelemään hänen kanssaan ja vaativat häneltä merkkiä taivaasta, kiusaten häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Niin hän huokasi hengessään ja sanoi: \"Miksi tämä sukupolvi vaatii merkkiä? Totisesti minä sanon teille: tälle sukupolvelle ei anneta merkkiä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Ja hän jätti heidät ja astui taas venheeseen ja lähti pois toiselle rannalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 14, 'Ja he olivat unhottaneet ottaa mukaansa leipää, eikä heillä ollut muassaan venheessä enempää kuin yksi leipä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 15, 'Ja hän käski heitä sanoen: \"Varokaa ja kavahtakaa fariseusten hapatusta ja Herodeksen hapatusta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 16, 'Niin he puhuivat keskenään siitä, ettei heillä ollut leipää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 17, 'Kun Jeesus huomasi sen, sanoi hän heille: \"Mitä puhutte siitä, ettei teillä ole leipää? Ettekö vielä käsitä ettekä ymmärrä? Onko teidän sydämenne paatunut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 18, 'Silmät teillä on, ettekö näe? Ja korvat teillä on, ettekö kuule? Ja ettekö muista:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 19, 'kun minä mursin ne viisi leipää viidelletuhannelle, kuinka monta vakan täyttä palasia te keräsitte?\" He sanoivat hänelle: \"Kaksitoista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 20, '\"Ja kun minä mursin ne seitsemän leipää neljälletuhannelle, kuinka monta vasun täyttä palasia te keräsitte?\" He sanoivat: \"Seitsemän\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 21, 'Niin hän sanoi heille: \"Ettekö vieläkään ymmärrä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 22, 'Ja he tulivat Beetsaidaan. Ja hänen tykönsä tuotiin sokea, ja he pyysivät, että hän koskisi häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 23, 'Niin hän tarttui sokean käteen, talutti hänet kylän ulkopuolelle, sylki hänen silmiinsä ja pani kätensä hänen päälleen ja kysyi häneltä: \"Näetkö mitään?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 24, 'Tämä katsahti ylös ja sanoi: \"Näen ihmiset, sillä minä erotan käveleviä, ne ovat puiden näköisiä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 25, 'Sitten hän taas pani kätensä hänen silmilleen; ja nyt mies näki tarkkaan ja oli parantunut ja näki kaikki aivan selvästi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 26, 'Ja hän lähetti hänet hänen kotiinsa sanoen: \"Älä edes poikkea kylään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 27, 'Ja Jeesus lähti opetuslapsinensa Filippuksen Kesarean kyliin. Ja tiellä hän kysyi opetuslapsiltaan ja sanoi heille: \"Kenen ihmiset sanovat minun olevan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 28, 'He vastasivat hänelle sanoen: \"Johannes Kastajan, ja toiset Eliaan, toiset taas jonkun profeetoista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 29, 'Niin hän kysyi heiltä: \"Kenenkä te sanotte minun olevan?\" Pietari vastasi ja sanoi hänelle: \"Sinä olet Kristus\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 30, 'Ja hän varoitti vakavasti heitä puhumasta kenellekään hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 31, 'Ja hän alkoi opettaa heille, että Ihmisen Pojan piti kärsimän paljon ja joutuman vanhinten ja ylipappien ja kirjanoppineiden hyljittäväksi ja tuleman tapetuksi, ja kolmen päivän perästä nouseman ylös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 32, 'Ja tämän hän puhui peittelemättä. Silloin Pietari otti hänet erilleen ja rupesi häntä nuhtelemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 33, 'Mutta hän kääntyi, katsoi opetuslapsiinsa ja nuhteli Pietaria sanoen: \"Mene pois minun edestäni, saatana, sillä sinä et ajattele sitä, mikä on Jumalan, vaan sitä, mikä on ihmisten\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 34, 'Ja hän kutsui tykönsä kansan ynnä opetuslapsensa ja sanoi heille: \"Jos joku tahtoo minun perässäni kulkea, hän kieltäköön itsensä ja ottakoon ristinsä ja seuratkoon minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 35, 'Sillä joka tahtoo pelastaa elämänsä, hän kadottaa sen, mutta joka kadottaa elämänsä minun ja evankeliumin tähden, hän pelastaa sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 36, 'Sillä mitä se hyödyttää ihmistä, vaikka hän voittaisi omaksensa koko maailman, mutta saisi vahingon sielullensa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 37, 'Sillä mitä voi ihminen antaa sielunsa lunnaiksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 38, 'Sillä joka häpeää minua ja minun sanojani tässä avionrikkojassa ja syntisessä sukupolvessa, sitä myös Ihmisen Poika on häpeävä, kun hän tulee Isänsä kirkkaudessa pyhien enkelien kanssa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Ja hän sanoi heille: \"Totisesti minä sanon teille: tässä seisovien joukossa on muutamia, jotka eivät maista kuolemaa, ennenkuin näkevät Jumalan valtakunnan tulevan voimassansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Ja kuuden päivän kuluttua Jeesus otti mukaansa Pietarin ja Jaakobin ja Johanneksen ja vei heidät erilleen muista korkealle vuorelle, yksinäisyyteen. Ja hänen muotonsa muuttui heidän edessään;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'ja hänen vaatteensa tulivat hohtaviksi, niin ylen valkoisiksi, ettei kukaan vaatteenvalkaisija maan päällä taida semmoiseksi valkaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Ja heille ilmestyivät Elias ynnä Mooses, ja nämä puhuivat Jeesuksen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Niin Pietari rupesi puhumaan ja sanoi Jeesukselle: \"Rabbi, meidän on tässä hyvä olla; tehkäämme siis kolme majaa, sinulle yksi ja Moosekselle yksi ja Eliaalle yksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Sillä hän ei tiennyt, mitä sanoa, koska he olivat peljästyksissään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Ja tuli pilvi, joka peitti heidät varjoonsa, ja pilvestä kuului ääni: \"Tämä on minun rakas Poikani; kuulkaa häntä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Ja yhtäkkiä, kun he katsahtivat ympärilleen, eivät he enää nähneet ketään muuta kuin Jeesuksen, joka yksinänsä oli heidän kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Ja heidän kulkiessaan alas vuorelta hän teroitti heille, etteivät kenellekään kertoisi, mitä olivat nähneet, ennenkuin vasta sitten, kun Ihmisen Poika oli noussut kuolleista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Ja he pitivät mielessään sen sanan ja tutkistelivat keskenään, mitä kuolleista nouseminen oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Ja he kysyivät häneltä sanoen: \"Kirjanoppineethan sanovat, että Eliaan pitää tuleman ensin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Niin hän sanoi heille: \"Elias tosin tulee ensin ja asettaa kaikki kohdalleen. Mutta kuinka sitten on kirjoitettu Ihmisen Pojasta, että hän on paljon kärsivä ja tuleva halveksituksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Mutta minä sanon teille: Elias onkin tullut, ja he tekivät hänelle, mitä tahtoivat, niinkuin hänestä on kirjoitettu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'Ja kun he tulivat opetuslasten luo, näkivät he paljon kansaa heidän ympärillään ja kirjanoppineita väittelemässä heidän kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Ja kohta kun kaikki kansa hänet näki, hämmästyivät he ja riensivät hänen luoksensa ja tervehtivät häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Ja hän kysyi heiltä: \"Mitä te väittelette heidän kanssaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Silloin vastasi eräs mies kansanjoukosta hänelle: \"Opettaja, minä toin sinun tykösi poikani, jossa on mykkä henki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Ja missä vain se käy hänen kimppuunsa, riuhtoo se häntä, ja hänestä lähtee vaahto, ja hän kiristelee hampaitaan; ja hän kuihtuu. Ja minä sanoin sinun opetuslapsillesi, että he ajaisivat sen ulos, mutta he eivät kyenneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Hän vastasi heille sanoen: \"Voi, sinä epäuskoinen sukupolvi, kuinka kauan minun täytyy olla teidän luonanne? Kuinka kauan kärsiä teitä? Tuokaa hänet minun tyköni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Niin he toivat hänet hänen tykönsä. Ja heti kun hän näki Jeesuksen, kouristi henki häntä, ja hän kaatui maahan, kieritteli itseään, ja hänestä lähti vaahto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Ja Jeesus kysyi hänen isältään: \"Kuinka kauan aikaa tätä on hänessä ollut?\" Niin hän sanoi: \"Pienestä pitäen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Ja monesti se on heittänyt hänet milloin tuleen, milloin veteen, tuhotakseen hänet. Mutta jos sinä jotakin voit, niin armahda meitä ja auta meitä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Niin Jeesus sanoi hänelle: \"\'Jos voit!\' Kaikki on mahdollista sille, joka uskoo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Ja heti lapsen isä huusi ja sanoi: \"Minä uskon; auta minun epäuskoani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Mutta kun Jeesus näki, että kansaa riensi sinne, nuhteli hän saastaista henkeä ja sanoi sille: \"Sinä mykkä ja kuuro henki, minä käsken sinua: lähde ulos hänestä, äläkä enää häneen mene\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Niin se huusi ja kouristi häntä kovasti ja lähti ulos. Ja hän kävi ikäänkuin kuolleeksi, niin että monet sanoivat: \"Hän kuoli\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Mutta Jeesus tarttui hänen käteensä ja nosti hänet ylös. Ja hän nousi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'Ja kun Jeesus oli mennyt huoneeseen, niin hänen opetuslapsensa kysyivät häneltä eriksensä: \"Miksi emme me voineet ajaa sitä ulos?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 29, 'Hän sanoi heille: \"Tätä lajia ei saa lähtemään ulos muulla kuin rukouksella ja paastolla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 30, 'Ja he lähtivät sieltä ja kulkivat Galilean läpi; ja hän ei tahtonut, että kukaan saisi sitä tietää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 31, 'Sillä hän opetti opetuslapsiaan ja sanoi heille: \"Ihmisen Poika annetaan ihmisten käsiin, ja he tappavat hänet; ja kun hän on tapettu, nousee hän kolmen päivän perästä ylös\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 32, 'Mutta he eivät käsittäneet sitä puhetta ja pelkäsivät häneltä kysyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 33, 'Ja he saapuivat Kapernaumiin. Ja kotiin tultuaan hän kysyi heiltä: \"Mistä te tiellä keskustelitte?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 34, 'Mutta he olivat vaiti; sillä he olivat tiellä keskustelleet toistensa kanssa siitä, kuka oli suurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 35, 'Ja hän istuutui, kutsui ne kaksitoista ja sanoi heille: \"Jos joku tahtoo olla ensimmäinen, on hänen oltava kaikista viimeinen ja kaikkien palvelija\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 36, 'Ja hän otti lapsen ja asetti sen heidän keskellensä; ja otettuaan sen syliinsä hän sanoi heille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 37, '\"Joka ottaa tykönsä yhden tämänkaltaisen lapsen minun nimeeni, se ottaa tykönsä minut; ja joka minut ottaa tykönsä, se ei ota tykönsä minua, vaan hänet, joka on minut lähettänyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 38, 'Johannes sanoi hänelle: \"Opettaja, me näimme erään, joka ei seuraa meitä, sinun nimessäsi ajavan ulos riivaajia; ja me kielsimme häntä, koska hän ei seurannut meitä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 39, 'Mutta Jeesus sanoi: \"Älkää häntä kieltäkö; sillä ei kukaan, joka tekee voimallisen teon minun nimeeni, voi kohta sen jälkeen puhua minusta pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 40, 'Sillä joka ei ole meitä vastaan, se on meidän puolellamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 41, 'Sillä joka antaa teille juodaksenne maljallisen vettä siinä nimessä, että te olette Kristuksen omia, totisesti minä sanon teille: se ei jää palkkaansa vaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 42, 'Ja joka viettelee yhden näistä pienistä, jotka uskovat, sen olisi parempi, että myllynkivi olisi pantu hänen kaulaansa ja hänet olisi heitetty mereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 43, 'Ja jos sinun kätesi viettelee sinua, hakkaa se poikki. Parempi on sinulle, että käsipuolena menet elämään sisälle, kuin että, molemmat kädet tallella, joudut helvettiin, sammumattomaan tuleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 44, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 45, 'Ja jos sinun jalkasi viettelee sinua, hakkaa se poikki. Parempi on sinulle, että jalkapuolena menet elämään sisälle, kuin että sinut, molemmat jalat tallella, heitetään helvettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 46, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 47, 'Ja jos sinun silmäsi viettelee sinua, heitä se pois. Parempi on sinulle, että silmäpuolena menet sisälle Jumalan valtakuntaan, kuin että sinut, molemmat silmät tallella, heitetään helvettiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 48, 'jossa heidän matonsa ei kuole eikä tuli sammu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 49, 'Sillä jokainen ihminen on tulella suolattava, ja jokainen uhri on suolalla suolattava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 50, 'Suola on hyvä; mutta jos suola käy suolattomaksi, millä te sen maustatte? Olkoon teillä suola itsessänne, ja pitäkää keskenänne rauha.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Ja hän nousi sieltä ja tuli Juudean alueelle, kulkien Jordanin toista puolta. Ja taas kokoontui paljon kansaa hänen luoksensa, ja tapansa mukaan hän taas opetti heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Ja fariseuksia tuli hänen luoksensa, ja kiusaten häntä he kysyivät häneltä, oliko miehen lupa hyljätä vaimonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Hän vastasi ja sanoi heille: \"Mitä Mooses on teille säätänyt?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'He sanoivat: \"Mooses salli kirjoittaa erokirjan ja hyljätä vaimon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Niin Jeesus sanoi heille: \"Teidän sydämenne kovuuden tähden hän kirjoitti teille tämän säädöksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Mutta luomakunnan alusta Jumala \'on luonut heidät mieheksi ja naiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Sentähden mies luopukoon isästänsä ja äidistänsä ja liittyköön vaimoonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Ja ne kaksi tulevat yhdeksi lihaksi.\' Niin eivät he enää ole kaksi, vaan yksi liha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Minkä siis Jumala on yhdistänyt, sitä älköön ihminen erottako.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Ja heidän mentyään huoneeseen opetuslapset taas kysyivät häneltä tätä asiaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Ja hän sanoi heille: \"Joka hylkää vaimonsa ja nai toisen, se tekee huorin häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Ja jos vaimo hylkää miehensä ja menee naimisiin toisen kanssa, niin hän tekee huorin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Ja he toivat hänen tykönsä lapsia, että hän koskisi heihin; mutta opetuslapset nuhtelivat tuojia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Mutta kun Jeesus sen näki, närkästyi hän ja sanoi heille: \"Sallikaa lasten tulla minun tyköni, älkääkä estäkö heitä, sillä senkaltaisten on Jumalan valtakunta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Totisesti minä sanon teille: joka ei ota vastaan Jumalan valtakuntaa niinkuin lapsi, se ei pääse sinne sisälle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Ja hän otti heitä syliinsä, pani kätensä heidän päällensä ja siunasi heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Ja hänen sieltä tielle mennessään juoksi muuan hänen luoksensa, polvistui hänen eteensä ja kysyi häneltä: \"Hyvä opettaja, mitä minun pitää tekemän, että minä iankaikkisen elämän perisin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Mutta Jeesus sanoi hänelle: \"Miksi sanot minua hyväksi? Ei kukaan ole hyvä paitsi Jumala yksin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Käskyt sinä tiedät: \'Älä tapa\', \'Älä tee huorin\', \'Älä varasta\', \'Älä sano väärää todistusta\', \'Älä toiselta anasta\', \'Kunnioita isääsi ja äitiäsi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Mutta hän sanoi hänelle: \"Opettaja, niitä kaikkia minä olen noudattanut nuoruudestani asti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'Niin Jeesus katsoi häneen ja rakasti häntä ja sanoi hänelle: \"Yksi sinulta puuttuu: mene, myy kaikki, mitä sinulla on, ja anna köyhille, niin sinulla on oleva aarre taivaassa; ja tule ja seuraa minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Mutta hän synkistyi siitä puheesta ja meni pois murheellisena, sillä hänellä oli paljon omaisuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Silloin Jeesus katsoi ympärilleen ja sanoi opetuslapsillensa: \"Kuinka vaikea onkaan niiden, joilla on tavaraa, päästä Jumalan valtakuntaan!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Niin opetuslapset hämmästyivät hänen sanoistaan. Mutta Jeesus rupesi taas puhumaan ja sanoi heille: \"Lapset, kuinka vaikea onkaan niiden, jotka luottavat tavaraansa, päästä Jumalan valtakuntaan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Helpompi on kamelin käydä neulansilmän läpi kuin rikkaan päästä Jumalan valtakuntaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Niin he hämmästyivät yhä enemmän ja sanoivat toisillensa: \"Kuka sitten voi pelastua?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Jeesus katsoi heihin ja sanoi: \"Ihmisille se on mahdotonta, mutta ei Jumalalle; sillä Jumalalle on kaikki mahdollista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Niin Pietari rupesi puhumaan sanoen hänelle: \"Katso, me olemme luopuneet kaikesta ja seuranneet sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Jeesus sanoi: \"Totisesti minä sanon teille: ei ole ketään, joka minun tähteni ja evankeliumin tähden on luopunut talosta tai veljistä tai sisarista tai äidistä tai isästä tai lapsista tai pelloista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'ja joka ei saisi satakertaisesti: nyt tässä ajassa taloja ja veljiä ja sisaria ja äitejä ja lapsia ja peltoja, vainojen keskellä, ja tulevassa maailmassa iankaikkista elämää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Mutta monet ensimmäiset tulevat viimeisiksi ja viimeiset ensimmäisiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Ja he olivat matkalla, menossa ylös Jerusalemiin, ja Jeesus kulki heidän edellään; ja heidät valtasi hämmästys, ja ne, jotka seurasivat, olivat peloissaan. Ja hän otti taas tykönsä ne kaksitoista ja rupesi heille puhumaan, mitä hänelle oli tapahtuva:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, '\"Katso, me menemme ylös Jerusalemiin, ja Ihmisen Poika annetaan ylipappien ja kirjanoppineitten käsiin, ja he tuomitsevat hänet kuolemaan ja antavat hänet pakanain käsiin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'ja ne pilkkaavat häntä ja sylkevät häntä ja ruoskivat häntä ja tappavat hänet; ja kolmen päivän perästä hän on nouseva ylös\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Ja Jaakob ja Johannes, Sebedeuksen pojat, menivät hänen luoksensa ja sanoivat hänelle: \"Opettaja, me tahtoisimme, että tekisit meille, mitä sinulta anomme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Hän sanoi heille: \"Mitä tahdotte, että minä teille tekisin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Niin he sanoivat hänelle: \"Anna meidän istua, toisen oikealla ja toisen vasemmalla puolellasi, sinun kirkkaudessasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Mutta Jeesus sanoi heille: \"Te ette tiedä, mitä anotte. Voitteko juoda sen maljan, jonka minä juon, tahi tulla kastetuiksi sillä kasteella, jolla minut kastetaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'He sanoivat hänelle: \"Voimme\". Niin Jeesus sanoi heille: \"Sen maljan, jonka minä juon, te tosin juotte, ja sillä kasteella, jolla minut kastetaan, kastetaan teidätkin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 40, 'mutta minun oikealla tai vasemmalla puolellani istuminen ei ole minun annettavissani, vaan se annetaan niille, joille se on valmistettu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 41, 'Kun ne kymmenen sen kuulivat, alkoivat he närkästyä Jaakobiin ja Johannekseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 42, 'Mutta Jeesus kutsui heidät tykönsä ja sanoi heille: \"Te tiedätte, että ne, joita kansojen ruhtinaiksi katsotaan, herroina niitä hallitsevat, ja että kansojen mahtavat käyttävät valtaansa niitä kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 43, 'Mutta näin ei ole teidän kesken, vaan joka teidän keskuudessanne tahtoo suureksi tulla, se olkoon teidän palvelijanne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 44, 'ja joka teidän keskuudessanne tahtoo olla ensimmäinen, se olkoon kaikkien orja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 45, 'Sillä ei Ihmisen Poikakaan tullut palveltavaksi, vaan palvelemaan ja antamaan henkensä lunnaiksi monen edestä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 46, 'Ja he tulivat Jerikoon. Ja kun hän vaelsi Jerikosta opetuslastensa ja suuren väkijoukon seuraamana, istui sokea kerjäläinen, Bartimeus, Timeuksen poika, tien vieressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 47, 'Ja kun hän kuuli, että se oli Jeesus Nasaretilainen, rupesi hän huutamaan ja sanomaan: \"Jeesus, Daavidin poika, armahda minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 48, 'Ja monet nuhtelivat häntä saadakseen hänet vaikenemaan. Mutta hän huusi vielä enemmän: \"Daavidin poika, armahda minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 49, 'Silloin Jeesus seisahtui ja sanoi: \"Kutsukaa hänet tänne\". Ja he kutsuivat sokean, sanoen hänelle: \"Ole turvallisella mielellä, nouse; hän kutsuu sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 50, 'Niin hän heitti vaippansa päältään, kavahti seisomaan ja tuli Jeesuksen tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 51, 'Ja Jeesus puhutteli häntä sanoen: \"Mitä tahdot, että minä sinulle tekisin?\" Niin sokea sanoi hänelle: \"Rabbuuni, että saisin näköni jälleen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 52, 'Niin Jeesus sanoi hänelle: \"Mene, sinun uskosi on sinut pelastanut\". Ja kohta hän sai näkönsä ja seurasi häntä tiellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Ja kun he lähestyivät Jerusalemia, tullen Beetfageen ja Betaniaan Öljymäelle, lähetti hän kaksi opetuslastaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'ja sanoi heille: \"Menkää kylään, joka on edessänne, niin te kohta, kun sinne tulette, löydätte sidottuna varsan, jonka selässä ei yksikään ihminen vielä ole istunut; päästäkää se ja tuokaa tänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Ja jos joku teille sanoo: \'Miksi te noin teette?\', niin sanokaa: \'Herra tarvitsee sitä ja lähettää sen kohta tänne takaisin\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Niin he menivät ja löysivät oven eteen ulos kujalle sidotun varsan ja päästivät sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Ja muutamat niistä, jotka siellä seisoivat, sanoivat heille: \"Mitä te teette, kun päästätte varsan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Niin he sanoivat heille, niinkuin Jeesus oli käskenyt; ja he antoivat heidän mennä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Ja he toivat varsan Jeesuksen luo ja heittivät vaatteensa sen päälle, ja hän istui sen selkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Ja monet levittivät vaatteensa tielle, ja toiset lehviä, joita katkoivat kedoilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Ja ne, jotka kulkivat edellä, ja jotka seurasivat, huusivat: \"Hoosianna, siunattu olkoon hän, joka tulee Herran nimeen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Siunattu olkoon isämme Daavidin valtakunta, joka tulee. Hoosianna korkeuksissa!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Ja hän kulki sisälle Jerusalemiin ja meni pyhäkköön; ja katseltuaan kaikkea hän lähti niiden kahdentoista kanssa Betaniaan, sillä aika oli jo myöhäinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Kun he seuraavana päivänä lähtivät Betaniasta, oli hänen nälkä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Ja kun hän kaukaa näki viikunapuun, jossa oli lehtiä, meni hän katsomaan, löytäisikö ehkä jotakin siitä; mutta tultuaan sen luo hän ei löytänyt muuta kuin lehtiä. Sillä silloin ei ollut viikunain aika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Niin hän puhui ja sanoi sille: \"Älköön ikinä enää kukaan sinusta hedelmää syökö\". Ja hänen opetuslapsensa kuulivat sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Ja he tulivat Jerusalemiin. Ja hän meni pyhäkköön ja rupesi ajamaan ulos niitä, jotka myivät ja ostivat pyhäkössä, ja kaatoi kumoon rahanvaihtajain pöydät ja kyyhkysten myyjäin istuimet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'eikä sallinut kenenkään kantaa mitään astiaa pyhäkön kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Ja hän opetti ja sanoi heille: \"Eikö ole kirjoitettu: \'Minun huoneeni on kutsuttava kaikkien kansojen rukoushuoneeksi\'? Mutta te olette tehneet siitä ryövärien luolan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'Ja ylipapit ja kirjanoppineet kuulivat sen ja miettivät, kuinka saisivat hänet surmatuksi; sillä he pelkäsivät häntä, koska kaikki kansa oli hämmästyksissään hänen opetuksestansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Illan tultua he menivät kaupungin ulkopuolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Ja kun he varhain aamulla kulkivat ohi, näkivät he viikunapuun kuivettuneen juuria myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Silloin Pietari muisti Jeesuksen sanat ja sanoi hänelle: \"Rabbi, katso, viikunapuu, jonka sinä kirosit, on kuivettunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Jeesus vastasi ja sanoi heille: \"Pitäkää usko Jumalaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Totisesti minä sanon teille: jos joku sanoisi tälle vuorelle: \'Kohoa ja heittäydy mereen\', eikä epäilisi sydämessään, vaan uskoisi sen tapahtuvan, minkä hän sanoo, niin se hänelle tapahtuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Sentähden minä sanon teille: kaikki, mitä te rukoilette ja anotte, uskokaa saaneenne, niin se on teille tuleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Ja kun te seisotte ja rukoilette, niin antakaa anteeksi, jos kenellä teistä on jotakin toistansa vastaan, että myös teidän Isänne, joka on taivaissa, antaisi teille anteeksi teidän rikkomuksenne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Ja he tulivat taas Jerusalemiin. Ja kun hän käveli pyhäkössä, tulivat ylipapit ja kirjanoppineet ja vanhimmat hänen luoksensa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'ja sanoivat hänelle: \"Millä vallalla sinä näitä teet? Tahi kuka sinulle on antanut vallan näitä tehdä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Mutta Jeesus vastasi heille: \"Minä myös teen teille yhden kysymyksen; vastatkaa te minulle, niin minä sanon teille, millä vallalla minä näitä teen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Oliko Johanneksen kaste taivaasta vai ihmisistä? Vastatkaa minulle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Niin he neuvottelivat keskenään sanoen: \"Jos sanomme: \'Taivaasta\', niin hän sanoo: \'Miksi ette siis uskoneet häntä?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Vai sanommeko: \'Ihmisistä\'?\" -sitä he kansan tähden pelkäsivät sanoa, sillä kaikkien mielestä Johannes totisesti oli profeetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Ja he vastasivat ja sanoivat Jeesukselle: \"Emme tiedä\". Silloin Jeesus sanoi heille: \"Niinpä en minäkään sano teille, millä vallalla minä näitä teen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Ja hän rupesi puhumaan heille vertauksilla: \"Mies istutti viinitarhan ja teki aidan sen ympärille ja kaivoi viinikuurnan ja rakensi tornin; ja hän vuokrasi sen viinitarhureille ja matkusti muille maille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Ja kun aika tuli, lähetti hän palvelijan viinitarhurien luo perimään tarhureilta viinitarhan hedelmiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Mutta he ottivat hänet kiinni, pieksivät ja lähettivät tyhjin käsin pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Ja vielä hän lähetti heidän luoksensa toisen palvelijan. Ja häntä he löivät päähän ja häpäisivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'Ja hän lähetti vielä toisen, ja sen he tappoivat; ja samoin useita muita: toisia he pieksivät, toisia tappoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Vielä hänellä oli ainoa rakas poikansa. Hänet hän lähetti viimeiseksi heidän luoksensa sanoen: \'Kavahtavat kaiketi minun poikaani\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Mutta viinitarhurit sanoivat toisilleen: \'Tämä on perillinen; tulkaa, tappakaamme hänet, niin perintö jää meille\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Ja he ottivat hänet kiinni, tappoivat ja heittivät hänet ulos viinitarhasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Mitä nyt viinitarhan herra on tekevä? Hän tulee ja tuhoaa viinitarhurit ja antaa viinitarhan muille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Ettekö ole lukeneet tätä kirjoitusta: \'Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Herralta tämä on tullut ja on ihmeellinen meidän silmissämme\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Silloin he olisivat tahtoneet ottaa hänet kiinni, mutta pelkäsivät kansaa; sillä he ymmärsivät, että hän oli puhunut tämän vertauksen heistä. Ja he jättivät hänet ja menivät pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'Ja he lähettivät hänen luoksensa muutamia fariseuksia ja herodilaisia kietomaan häntä sanoilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Nämä tulivat ja sanoivat hänelle: \"Opettaja, me tiedämme, että sinä olet totinen etkä välitä kenestäkään, sillä sinä et katso henkilöön, vaan opetat Jumalan tietä totuudessa. Onko luvallista antaa keisarille veroa vai ei? Tuleeko meidän antaa vai ei?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Mutta hän tiesi heidän ulkokultaisuutensa ja sanoi heille: \"Miksi kiusaatte minua? Tuokaa denari minun nähdäkseni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Niin he toivat. Ja hän sanoi heille: \"Kenen kuva ja päällekirjoitus tämä on?\" He vastasivat hänelle: \"Keisarin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Jeesus sanoi heille: \"Antakaa keisarille, mikä keisarin on, ja Jumalalle, mikä Jumalan on\". Ja he ihmettelivät häntä suuresti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Ja hänen luoksensa tuli saddukeuksia, jotka sanovat, ettei ylösnousemusta ole; ja he kysyivät häneltä sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, '\"Opettaja, Mooses on säätänyt meille: \'Jos joltakin kuolee veli, joka jättää jälkeensä vaimon, mutta ei jätä lasta, niin ottakoon hän veljensä lesken ja herättäköön veljellensä siemenen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Oli seitsemän veljestä. Ensimmäinen otti vaimon, ja kun hän kuoli, ei häneltä jäänyt jälkeläistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Silloin toinen otti hänet, ja hänkin kuoli jättämättä jälkeläistä. Niin myös kolmas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Samoin kävi kaikille seitsemälle: heiltä ei jäänyt jälkeläistä. Viimeiseksi kaikista vaimokin kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Ylösnousemuksessa siis, kun he nousevat ylös, kenelle heistä hän joutuu vaimoksi, sillä hän oli ollut kaikkien noiden seitsemän vaimona?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'Jeesus sanoi heille: \"Ettekö te siitä syystä eksy, kun ette tunne kirjoituksia ettekä Jumalan voimaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Sillä kun kuolleista noustaan, ei naida eikä mennä miehelle; vaan he ovat niinkuin enkelit taivaissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Mutta mitä siihen tulee, että kuolleet nousevat ylös, ettekö ole lukeneet Mooseksen kirjasta, kertomuksessa orjantappurapensaasta, kuinka Jumala puhui hänelle sanoen: \'Minä olen Aabrahamin Jumala ja Iisakin Jumala ja Jaakobin Jumala\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Ei hän ole kuolleitten Jumala, vaan elävien. Suuresti te eksytte.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Silloin tuli hänen luoksensa eräs kirjanoppinut, joka oli kuullut heidän keskustelunsa ja huomannut hänen hyvin vastanneen heille, ja kysyi häneltä: \"Mikä on ensimmäinen kaikista käskyistä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Jeesus vastasi: \"Ensimmäinen on tämä: \'Kuule, Israel: Herra, meidän Jumalamme, Herra on yksi ainoa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 30, 'ja rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta mielestäsi ja kaikesta voimastasi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 31, 'Toinen on tämä: \'Rakasta lähimmäistäsi niinkuin itseäsi\'. Ei ole mitään käskyä, suurempaa kuin nämä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 32, 'Niin kirjanoppinut sanoi hänelle: \"Oikein sanoit, opettaja, totuuden mukaan, että yksi hän on, ja ettei ketään muuta ole, paitsi hän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 33, 'Ja rakastaa häntä kaikesta sydämestään ja kaikesta ymmärryksestään ja kaikesta voimastaan, ja rakastaa lähimmäistään niinkuin itseänsä, se on enemmän kuin kaikki polttouhrit ja muut uhrit.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 34, 'Kun Jeesus näki, että hän vastasi ymmärtäväisesti, sanoi hän hänelle: \"Sinä et ole kaukana Jumalan valtakunnasta\". Eikä kukaan enää rohjennut häneltä kysyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 35, 'Ja opettaessaan pyhäkössä Jeesus puhui edelleen ja sanoi: \"Kuinka kirjanoppineet sanovat, että Kristus on Daavidin poika?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 36, 'Onhan Daavid itse sanonut Pyhässä Hengessä: \'Herra sanoi minun Herralleni: Istu minun oikealle puolelleni, kunnes minä panen sinun vihollisesi sinun jalkojesi alle\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 37, 'Daavid itse sanoo häntä Herraksi; kuinka hän sitten on hänen poikansa?\" Ja suuri kansanjoukko kuunteli häntä mielellään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 38, 'Ja opettaessaan hän sanoi: \"Varokaa kirjanoppineita, jotka mielellään käyskelevät pitkissä vaipoissa ja haluavat tervehdyksiä toreilla');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 39, 'ja etumaisia istuimia synagoogissa ja ensimmäisiä sijoja pidoissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 40, 'noita, jotka syövät leskien huoneet ja näön vuoksi pitävät pitkiä rukouksia; he saavat sitä kovemman tuomion\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 41, 'Ja hän istui vastapäätä uhriarkkua ja katseli, kuinka kansa pani rahaa uhriarkkuun. Ja monet rikkaat panivat paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 42, 'Niin tuli köyhä leski ja pani kaksi ropoa, yhteensä muutamia pennejä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 43, 'Ja hän kutsui opetuslapsensa tykönsä ja sanoi heille: \"Totisesti minä sanon teille: tämä köyhä leski pani enemmän kuin kaikki muut, jotka panivat uhriarkkuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 44, 'Sillä he kaikki panivat liiastaan, mutta tämä pani puutteestaan kaiken, mitä hänellä oli, koko elämisensä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Ja kun hän meni ulos pyhäköstä, sanoi eräs hänen opetuslapsistaan hänelle: \"Opettaja, katso, millaiset kivet ja millaiset rakennukset!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Jeesus vastasi hänelle: \"Sinä näet nämä suuret rakennukset. Niistä ei ole jäävä kiveä kiven päälle maahan jaottamatta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Ja kun hän istui Öljymäellä, vastapäätä pyhäkköä, kysyivät Pietari ja Jaakob ja Johannes ja Andreas häneltä eriksensä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, '\"Sano meille: milloin tämä tapahtuu, ja mikä on merkki siitä, että kaikki tämä alkaa lopullisesti toteutua?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Niin Jeesus rupesi puhumaan heille: \"Katsokaa, ettei kukaan teitä eksytä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Monta tulee minun nimessäni sanoen: \'Minä se olen\', ja he eksyttävät monta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Ja kun te kuulette sotien melskettä ja sanomia sodista, älkää peljästykö. Näin täytyy tapahtua, mutta se ei ole vielä loppu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Sillä kansa nousee kansaa vastaan ja valtakunta valtakuntaa vastaan, tulee maanjäristyksiä monin paikoin, tulee nälänhätää. Tämä on synnytystuskien alkua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Mutta pitäkää te vaari itsestänne. Teidät vedetään oikeuksiin, ja teitä piestään synagoogissa, ja teidät asetetaan maaherrain ja kuningasten eteen, minun tähteni, todistukseksi heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Ja sitä ennen pitää evankeliumi saarnattaman kaikille kansoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Ja kun he vievät teitä ja vetävät oikeuteen, älkää edeltäpäin huolehtiko siitä, mitä puhuisitte; vaan mitä teille sillä hetkellä annetaan, se puhukaa. Sillä ette te ole puhumassa, vaan Pyhä Henki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Ja veli antaa veljensä kuolemaan ja isä lapsensa, ja lapset nousevat vanhempiansa vastaan ja tappavat heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Ja te joudutte kaikkien vihattaviksi minun nimeni tähden; mutta joka vahvana pysyy loppuun asti, se pelastuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Mutta kun näette hävityksen kauhistuksen seisovan siinä, missä ei tulisi-joka tämän lukee, se tarkatkoon-silloin ne, jotka Juudeassa ovat, paetkoot vuorille;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'joka on katolla, älköön astuko alas älköönkä menkö sisään noutamaan mitään huoneestansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'ja joka on mennyt pellolle, älköön palatko takaisin noutamaan vaippaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Voi raskaita ja imettäväisiä niinä päivinä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Mutta rukoilkaa, ettei se tapahtuisi talvella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Sillä niinä päivinä on oleva ahdistus, jonka kaltaista ei ole ollut hamasta luomakunnan alusta, jonka Jumala on luonut, tähän asti, eikä milloinkaan tule.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Ja ellei Herra lyhentäisi niitä päiviä, ei mikään liha pelastuisi; mutta valittujen tähden, jotka hän on valinnut, hän on lyhentänyt ne päivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Ja jos silloin joku sanoo teille: \'Katso, täällä on Kristus\', tai: \'Katso, tuolla\', niin älkää uskoko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Sillä vääriä kristuksia ja vääriä profeettoja nousee, ja he tekevät tunnustekoja ja ihmeitä, eksyttääkseen, jos mahdollista, valitut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Mutta olkaa te varuillanne. Minä olen edeltä sanonut teille kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Mutta niinä päivinä, sen ahdistuksen jälkeen, aurinko pimenee, eikä kuu anna valoansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'ja tähdet putoilevat taivaalta, ja voimat, jotka taivaissa ovat, järkkyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 26, 'Ja silloin he näkevät Ihmisen Pojan tulevan pilvissä suurella voimalla ja kirkkaudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 27, 'Ja silloin hän lähettää enkelinsä ja kokoaa valittunsa neljältä ilmalta, maan äärestä hamaan taivaan ääreen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 28, 'Mutta oppikaa viikunapuusta vertaus: Kun sen oksa jo on tuore ja lehdet puhkeavat, niin te tiedätte, että kesä on lähellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 29, 'Samoin te myös, kun näette tämän tapahtuvan, tietäkää, että se on lähellä, oven edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 30, 'Totisesti minä sanon teille: tämä sukupolvi ei katoa, ennenkuin nämä kaikki tapahtuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 31, 'Taivas ja maa katoavat, mutta minun sanani eivät katoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 32, 'Mutta siitä päivästä tai hetkestä ei tiedä kukaan, eivät enkelit taivaassa, eikä myöskään Poika, vaan ainoastaan Isä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 33, 'Olkaa varuillanne, valvokaa ja rukoilkaa, sillä ette tiedä, milloin se aika tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 34, 'On niinkuin muille maille matkustaneen miehen: kun hän jätti talonsa ja antoi palvelijoilleen vallan, kullekin oman tehtävänsä, käski hän myös ovenvartijan valvoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 35, 'Valvokaa siis, sillä ette tiedä, milloin talon herra tulee, iltamyöhälläkö vai yösydännä vai kukonlaulun aikaan vai varhain aamulla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 36, 'ettei hän, äkkiarvaamatta tullessaan, tapaisi teitä nukkumasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 37, 'Mutta minkä minä teille sanon, sen minä sanon kaikille: valvokaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 1, 'Niin oli kahden päivän perästä pääsiäinen ja happamattoman leivän juhla, ja ylipapit ja kirjanoppineet miettivät, kuinka saisivat hänet otetuksi kavaluudella kiinni ja tapetuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 2, 'Sillä he sanoivat: \"Ei juhlan aikana, ettei syntyisi meteliä kansassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 3, 'Ja kun hän oli Betaniassa, pitalisen Simonin asunnossa, tuli hänen aterialla ollessaan nainen, mukanaan alabasteripullo täynnä oikeata, kallista nardusvoidetta. Hän rikkoi alabasteripullon ja vuodatti voiteen hänen päähänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 4, 'Niin oli muutamia, jotka närkästyivät ja sanoivat keskenään: \"Mitä varten tämä voiteen haaskaus?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 5, 'Olisihan voinut myydä tämän voiteen enempään kuin kolmeensataan denariin ja antaa ne köyhille.\" Ja he toruivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 6, 'Mutta Jeesus sanoi: \"Antakaa hänen olla. Miksi pahoitatte hänen mieltään? Hän teki hyvän työn minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 7, 'Köyhät teillä on aina keskuudessanne, ja milloin tahdotte, voitte heille tehdä hyvää, mutta minua teillä ei ole aina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 8, 'Hän teki, minkä voi. Edeltäkäsin hän voiteli minun ruumiini hautaamista varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 9, 'Totisesti minä sanon teille: missä ikinä kaikessa maailmassa evankeliumia saarnataan, siellä sekin, minkä tämä teki, on mainittava hänen muistoksensa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 10, 'Ja Juudas Iskariot, yksi niistä kahdestatoista, meni ylipappien luo kavaltaakseen hänet heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 11, 'Kun nämä sen kuulivat, ihastuivat he ja lupasivat antaa hänelle rahaa. Ja hän mietti, kuinka hänet sopivassa tilaisuudessa kavaltaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 12, 'Ja ensimmäisenä happamattoman leivän päivänä, kun pääsiäislammas teurastettiin, hänen opetuslapsensa sanoivat hänelle: \"Mihin tahdot, että menemme valmistamaan pääsiäislampaan sinun syödäksesi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 13, 'Niin hän lähetti kaksi opetuslastaan ja sanoi heille: \"Menkää kaupunkiin, niin teitä vastaan tulee mies kantaen vesiastiaa; seuratkaa häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 14, 'Ja mihin hän menee, sen talon isännälle sanokaa: \'Opettaja sanoo: Missä on minun vierashuoneeni, syödäkseni siinä pääsiäislampaan opetuslasteni kanssa?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 15, 'Ja hän näyttää teille suuren huoneen yläkerrassa, valmiiksi laitetun; valmistakaa meille sinne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 16, 'Niin opetuslapset lähtivät ja tulivat kaupunkiin ja havaitsivat niin olevan, kuin Jeesus oli heille sanonut, ja valmistivat pääsiäislampaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 17, 'Ja kun ehtoo tuli, saapui hän sinne niiden kahdentoista kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 18, 'Ja kun he olivat aterialla ja söivät, sanoi Jeesus: \"Totisesti minä sanon teille: yksi teistä kavaltaa minut, yksi, joka syö minun kanssani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 19, 'He tulivat murheellisiksi ja rupesivat toinen toisensa perästä sanomaan hänelle: \"En kaiketi minä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 20, 'Hän sanoi heille: \"Yksi teistä kahdestatoista, se, joka kastaa vatiin minun kanssani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 21, 'Niin, Ihmisen Poika tosin menee pois, niinkuin hänestä on kirjoitettu, mutta voi sitä ihmistä, jonka kautta Ihmisen Poika kavalletaan! Parempi olisi sille ihmiselle, että hän ei olisi syntynyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 22, 'Ja heidän syödessään Jeesus otti leivän, siunasi, mursi ja antoi heille ja sanoi: \"Ottakaa, tämä on minun ruumiini\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 23, 'Ja hän otti maljan, kiitti ja antoi heille; ja he kaikki joivat siitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 24, 'Ja hän sanoi heille: \"Tämä on minun vereni, liiton veri, joka vuodatetaan monen edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 25, 'Totisesti minä sanon teille: minä en juo enää viinipuun antia, ennenkuin sinä päivänä, jona juon sitä uutena Jumalan valtakunnassa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 26, 'Ja veisattuaan kiitosvirren he lähtivät Öljymäelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 27, 'Ja Jeesus sanoi heille: \"Kaikki te loukkaannutte, sillä kirjoitettu on: \'Minä lyön paimenta, ja lampaat hajotetaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 28, 'Mutta ylösnoustuani minä menen teidän edellänne Galileaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 29, 'Niin Pietari sanoi hänelle: \"Vaikka kaikki loukkaantuisivat, en kuitenkaan minä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 30, 'Jeesus sanoi hänelle: \"Totisesti minä sanon sinulle: tänään, tänä yönä, ennenkuin kukko kahdesti laulaa, sinä kolmesti minut kiellät\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 31, 'Mutta hän vakuutti vielä lujemmin: \"Vaikka minun pitäisi kuolla sinun kanssasi, en sittenkään minä sinua kiellä\". Ja samoin sanoivat kaikki muutkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 32, 'Ja he tulivat maatilalle, jonka nimi on Getsemane; ja hän sanoi opetuslapsillensa: \"Istukaa tässä, sillä aikaa kuin minä rukoilen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 33, 'Ja hän otti mukaansa Pietarin ja Jaakobin ja Johanneksen; ja hän alkoi kauhistua ja tulla tuskaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 34, 'Ja hän sanoi heille: \"Minun sieluni on syvästi murheellinen, kuolemaan asti; olkaa tässä ja valvokaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 35, 'Ja hän meni vähän edemmäksi, lankesi maahan ja rukoili, että, jos mahdollista, se hetki menisi häneltä ohi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 36, 'ja sanoi: \"Abba, Isä, kaikki on mahdollista sinulle; ota pois minulta tämä malja. Mutta ei, mitä minä tahdon, vaan mitä sinä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 37, 'Ja hän tuli ja tapasi heidät nukkumasta ja sanoi Pietarille: \"Simon, nukutko? Etkö jaksanut yhtä hetkeä valvoa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 38, 'Valvokaa ja rukoilkaa, ettette joutuisi kiusaukseen; henki tosin on altis, mutta liha on heikko.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 39, 'Ja taas hän meni pois ja rukoili sanoen samat sanat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 40, 'Ja tullessaan hän taas tapasi heidät nukkumasta, sillä heidän silmänsä olivat käyneet kovin raukeiksi; ja he eivät tienneet, mitä hänelle vastaisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 41, 'Ja hän tuli kolmannen kerran ja sanoi heille: \"Te nukutte vielä ja lepäätte! Jo riittää! Hetki on tullut; katso, Ihmisen Poika annetaan syntisten käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 42, 'Nouskaa, lähtekäämme; katso, se, joka kavaltaa minut, on lähellä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 43, 'Ja heti, hänen vielä puhuessaan, Juudas, yksi niistä kahdestatoista, saapui, ja hänen mukanaan joukko ylipappien ja kirjanoppineiden ja vanhinten luota, miekat ja seipäät käsissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 44, 'Mutta se, joka hänet kavalsi, oli sopinut heidän kanssaan merkistä, sanoen: \"Se, jolle minä suuta annan, hän se on; ottakaa hänet kiinni ja viekää tarkasti vartioituna pois\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 45, 'Ja tultuaan hän kohta astui hänen luoksensa ja sanoi: \"Rabbi!\" ja antoi hänelle suuta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 46, 'Silloin he kävivät häneen käsiksi ja ottivat hänet kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 47, 'Mutta eräs niistä, jotka lähellä seisoivat, veti miekkansa, iski ylimmäisen papin palvelijaa ja sivalsi häneltä pois korvan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 48, 'Niin Jeesus puhui heille ja sanoi: \"Niinkuin ryöväriä vastaan te olette lähteneet minua miekoilla ja seipäillä vangitsemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 49, 'Joka päivä minä olen ollut teidän luonanne opettaen pyhäkössä, ettekä ole ottaneet minua kiinni. Mutta tämä tapahtuu, että kirjoitukset kävisivät toteen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 50, 'Niin he kaikki jättivät hänet ja pakenivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 51, 'Ja häntä seurasi eräs nuorukainen, jolla oli ympärillään liinavaate paljaalle iholle heitettynä; ja he ottivat hänet kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 52, 'Mutta hän jätti liinavaatteen ja pakeni alastonna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 53, 'Ja he veivät Jeesuksen ylimmäisen papin eteen, jonne kaikki ylipapit ja vanhimmat ja kirjanoppineet kokoontuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 54, 'Ja Pietari seurasi häntä taampana ylimmäisen papin palatsin esipihaan asti ja istui palvelijain joukkoon ja lämmitteli tulen ääressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 55, 'Mutta ylipapit ja koko neuvosto etsivät todistusta Jeesusta vastaan tappaaksensa hänet, mutta eivät löytäneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 56, 'Useat kyllä todistivat väärin häntä vastaan, mutta todistukset eivät olleet yhtäpitäviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 57, 'Niin muutamat nousivat ja todistivat väärin häntä vastaan, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 58, '\"Me olemme kuulleet hänen sanovan: \'Minä hajotan maahan tämän käsillä tehdyn temppelin ja rakennan kolmessa päivässä toisen, joka ei ole käsillä tehty\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 59, 'Mutta eivät näinkään heidän todistuksensa olleet yhtäpitäviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 60, 'Silloin ylimmäinen pappi nousi ja astui esille ja kysyi Jeesukselta sanoen: \"Etkö vastaa mitään? Mitä nämä todistavat sinua vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 61, 'Mutta hän oli vaiti eikä vastannut mitään. Taas ylimmäinen pappi kysyi häneltä ja sanoi hänelle: \"Oletko sinä Kristus, sen Ylistetyn Poika?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 62, 'Jeesus sanoi: \"Olen; ja te saatte nähdä Ihmisen Pojan istuvan Voiman oikealla puolella ja tulevan taivaan pilvissä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 63, 'Niin ylimmäinen pappi repäisi vaatteensa ja sanoi: \"Mitä me enää todistajia tarvitsemme?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 64, 'Te kuulitte hänen pilkkaamisensa. Mitä arvelette?\" Niin he kaikki tuomitsivat hänet vikapääksi kuolemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 65, 'Ja muutamat rupesivat sylkemään häntä ja peittivät hänen kasvonsa ja löivät häntä nyrkillä ja sanoivat hänelle: \"Profetoi!\" Oikeudenpalvelijatkin löivät häntä poskelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 66, 'Kun nyt Pietari oli alhaalla esipihassa, tuli sinne muuan ylimmäisen papin palvelijattarista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 67, 'ja nähdessään Pietarin lämmittelevän hän katsoi häneen ja sanoi: \"Sinäkin olit Nasaretilaisen, tuon Jeesuksen, kanssa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 68, 'Mutta hän kielsi sanoen: \"En tiedä enkä käsitä, mitä sanot\". Ja hän meni ulos pihalle. Ja kukko lauloi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 69, 'Ja nähdessään hänet siellä palvelijatar rupesi taas sanomaan lähellä seisoville: \"Tämä on yksi niistä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 70, 'Mutta hän kielsi uudestaan. Ja vähän sen jälkeen lähellä seisovat taas sanoivat Pietarille: \"Totisesti, sinä olet yksi niistä, sillä olethan sinä galilealainenkin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 71, 'Mutta hän rupesi sadattelemaan itseänsä ja vannomaan: \"En tunne sitä miestä, josta te puhutte\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 14, 72, 'Ja samassa kukko lauloi toisen kerran. Niin Pietari muisti Jeesuksen sanat, jotka hän oli sanonut hänelle: \"Ennenkuin kukko kahdesti laulaa, sinä kolmesti minut kiellät\". Ja hän ratkesi itkuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 1, 'Ja heti aamulla ylipapit ynnä vanhimmat ja kirjanoppineet ja koko neuvosto tekivät päätöksen, sitoivat Jeesuksen, veivät hänet pois ja antoivat Pilatuksen käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 2, 'Niin Pilatus kysyi häneltä: \"Oletko sinä juutalaisten kuningas?\" Hän vastasi ja sanoi hänelle: \"Sinäpä sen sanot\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 3, 'Ja ylipapit tekivät monta syytöstä häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 4, 'Niin Pilatus taas kysyi häneltä sanoen: \"Etkö vastaa mitään? Katso, kuinka paljon syytöksiä he tekevät sinua vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 5, 'Mutta Jeesus ei enää vastannut mitään, niin että Pilatus ihmetteli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 6, 'Mutta juhlan aikana hän tavallisesti päästi heille yhden vangin irti, sen, jota he anoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 7, 'Niin siellä oli eräs mies, jota sanottiin Barabbaaksi, vangittu muiden kapinoitsijain kanssa, jotka kapinassa olivat tehneet murhan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 8, 'Ja kansa meni sinne ylös ja rupesi pyytämään, että hän tekisi heille, niinkuin hänen tapansa oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 9, 'Pilatus vastasi heille sanoen: \"Tahdotteko, että päästän teille juutalaisten kuninkaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 10, 'Sillä hän tiesi, että ylipapit kateudesta olivat antaneet hänet hänen käsiinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 11, 'Mutta ylipapit kiihoittivat kansaa anomaan, että hän ennemmin päästäisi heille Barabbaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 12, 'Ja Pilatus puhui taas heille ja sanoi: \"Mitä minun sitten on tehtävä hänelle, jota te sanotte juutalaisten kuninkaaksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 13, 'Niin he taas huusivat: \"Ristiinnaulitse hänet!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 14, 'Mutta Pilatus sanoi heille: \"Mitä pahaa hän sitten on tehnyt?\" Mutta he huusivat vielä kovemmin: \"Ristiinnaulitse hänet!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 15, 'Ja kun Pilatus tahtoi tehdä kansalle mieliksi, päästi hän heille Barabbaan, mutta Jeesuksen hän ruoskitti ja luovutti ristiinnaulittavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 16, 'Niin sotamiehet veivät hänet sisälle linnaan, se on palatsiin, ja kutsuivat siihen koko sotilasjoukon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 17, 'Ja he pukivat hänen yllensä purppuravaipan, väänsivät orjantappuroista kruunun ja panivat sen hänen päähänsä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 18, 'ja rupesivat tervehtimään häntä: \"Terve, juutalaisten kuningas!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 19, 'Ja he löivät häntä päähän ruovolla, sylkivät häntä ja laskeutuen polvilleen kumarsivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 20, 'Ja kun he olivat häntä pilkanneet, riisuivat he häneltä purppuravaipan ja pukivat hänet hänen omiin vaatteisiinsa. Ja he veivät hänet pois, ristiinnaulitakseen hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 21, 'Ja he pakottivat erään ohikulkevan miehen, Simonin, kyreneläisen, joka tuli vainiolta, Aleksanterin ja Rufuksen isän, kantamaan hänen ristiänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 22, 'Ja he veivät hänet paikalle, jonka nimi on Golgata, se on käännettynä: pääkallonpaikka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 23, 'Ja he tarjosivat hänelle mirhalla sekoitettua viiniä, mutta hän ei sitä ottanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 24, 'Ja he ristiinnaulitsivat hänet ja jakoivat keskenään hänen vaatteensa heittäen niistä arpaa, mitä kukin oli saava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 25, 'Oli kolmas hetki, kun he hänet ristiinnaulitsivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 26, 'Ja päällekirjoitukseksi oli merkitty hänen syynsä: \"Juutalaisten kuningas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 27, 'Ja he ristiinnaulitsivat hänen kanssaan kaksi ryöväriä, toisen hänen oikealle ja toisen hänen vasemmalle puolellensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 28, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 29, 'Ja ne, jotka kulkivat ohitse, herjasivat häntä ja nyökyttivät päätään ja sanoivat: \"Voi sinua, joka hajotat maahan temppelin ja kolmessa päivässä sen rakennat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 30, 'Auta itseäsi ja astu alas ristiltä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 31, 'Samoin ylipapitkin ynnä kirjanoppineet keskenään pilkkasivat häntä ja sanoivat: \"Muita hän on auttanut, itseään ei voi auttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 32, 'Astukoon hän, Kristus, Israelin kuningas, nyt alas ristiltä, että me näkisimme ja uskoisimme.\" Myöskin ne, jotka olivat ristiinnaulitut hänen kanssaan, herjasivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 33, 'Ja kuudennella hetkellä tuli pimeys yli kaiken maan, ja sitä kesti hamaan yhdeksänteen hetkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 34, 'Ja yhdeksännellä hetkellä Jeesus huusi suurella äänellä: \"Eeli, Eeli, lama sabaktani?\" Se on käännettynä: Jumalani, Jumalani, miksi minut hylkäsit?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 35, 'Sen kuullessaan sanoivat muutamat niistä, jotka siinä seisoivat: \"Katso, hän huutaa Eliasta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 36, 'Ja muuan juoksi ja täytti sienen hapanviinillä, pani sen ruovon päähän ja antoi hänelle juoda sanoen: \"Annas, katsokaamme, tuleeko Elias ottamaan hänet alas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 37, 'Mutta Jeesus huusi suurella äänellä ja antoi henkensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 38, 'Ja temppelin esirippu repesi kahtia ylhäältä alas asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 39, 'Mutta kun sadanpäämies, joka seisoi häntä vastapäätä, näki hänen näin antavan henkensä, sanoi hän: \"Totisesti tämä ihminen oli Jumalan Poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 40, 'Ja siellä oli myös naisia taampaa katselemassa. Näiden joukossa olivat Maria Magdaleena ja Maria, Jaakob nuoremman ja Jooseen äiti, ja Salome,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 41, 'jotka hänen ollessaan Galileassa olivat seuranneet ja palvelleet häntä, sekä useita muita, jotka olivat tulleet hänen kanssaan ylös Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 42, 'Ja kun jo oli tullut ilta, ja koska oli valmistuspäivä, se on sapatin aattopäivä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 43, 'tuli Joosef, arimatialainen, arvossapidetty neuvoston jäsen, joka hänkin odotti Jumalan valtakuntaa, rohkaisi mielensä ja meni sisälle Pilatuksen luo ja pyysi Jeesuksen ruumista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 44, 'Niin Pilatus ihmetteli, oliko hän jo kuollut, ja kutsuttuaan luoksensa sadanpäämiehen kysyi tältä, oliko hän jo kauan sitten kuollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 45, 'Ja saatuaan sadanpäämieheltä siitä tiedon hän lahjoitti ruumiin Joosefille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 46, 'Tämä osti liinavaatteen ja otti hänet alas, kääri hänet liinavaatteeseen ja pani hautaan, joka oli hakattu kallioon, ja vieritti kiven hautakammion ovelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 15, 47, 'Ja Maria Magdaleena ja Maria, Jooseen äiti, katselivat, mihin hänet pantiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 1, 'Ja kun sapatti oli ohi, ostivat Maria Magdaleena ja Maria, Jaakobin äiti, ja Salome hyvänhajuisia yrttejä mennäkseen voitelemaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 2, 'Ja viikon ensimmäisenä päivänä he tulivat haudalle ani varhain, auringon noustessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 3, 'Ja he sanoivat toisilleen: \"Kuka meille vierittää kiven hautakammion ovelta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 4, 'Ja katsahtaessaan ylös he näkivät kiven poisvieritetyksi; se oli näet hyvin suuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 5, 'Ja mentyään hautakammion sisään he näkivät nuorukaisen istuvan oikealla puolella, puettuna pitkään, valkeaan vaatteeseen; ja he peljästyivät suuresti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 6, 'Mutta hän sanoi heille: \"Älkää peljästykö; te etsitte Jeesusta, Nasaretilaista, joka oli ristiinnaulittu. Hän on noussut ylös; ei hän ole täällä. Katso, tässä on paikka, johon he hänet panivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 7, 'Mutta menkää ja sanokaa hänen opetuslapsillensa ja Pietarille: \'Hän menee teidän edellänne Galileaan; siellä te saatte hänet nähdä, niinkuin hän teille sanoi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 8, 'Niin he tulivat ulos ja pakenivat haudalta, sillä heidät oli vallannut vavistus ja hämmästys, eivätkä sanoneet kenellekään mitään, sillä he pelkäsivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 9, 'Mutta ylösnousemisensa jälkeen hän varhain aamulla viikon ensimmäisenä päivänä ilmestyi ensiksi Maria Magdaleenalle, josta hän oli ajanut ulos seitsemän riivaajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 10, 'Tämä meni ja vei sanan niille, jotka olivat olleet Jeesuksen kanssa ja jotka nyt murehtivat ja itkivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 11, 'Mutta kun he kuulivat, että hän eli ja että Maria oli hänet nähnyt, eivät he uskoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 12, 'Ja sen jälkeen hän toisenmuotoisena ilmestyi kahdelle heistä, heidän kävellessään, matkalla maakylään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 13, 'Hekin menivät ja veivät sanan toisille; mutta nämä eivät uskoneet heitäkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 14, 'Vihdoin hän ilmestyi myöskin niille yhdelletoista heidän ollessaan aterialla; ja hän nuhteli heidän epäuskoaan ja heidän sydämensä kovuutta, kun he eivät olleet uskoneet niitä, jotka olivat nähneet hänet ylösnousseeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 15, 'Ja hän sanoi heille: \"Menkää kaikkeen maailmaan ja saarnatkaa evankeliumia kaikille luoduille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 16, 'Joka uskoo ja kastetaan, se pelastuu; mutta joka ei usko, se tuomitaan kadotukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 17, 'Ja nämä merkit seuraavat niitä, jotka uskovat: minun nimessäni he ajavat ulos riivaajia, puhuvat uusilla kielillä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 18, 'nostavat käsin käärmeitä, ja jos he juovat jotakin kuolettavaa, ei se heitä vahingoita; he panevat kätensä sairasten päälle, ja ne tulevat terveiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 19, 'Kun nyt Herra Jeesus oli puhunut heille, otettiin hänet ylös taivaaseen, ja hän istui Jumalan oikealle puolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 16, 20, 'Mutta he lähtivät ja saarnasivat kaikkialla, ja Herra vaikutti heidän kanssansa ja vahvisti sanan sitä seuraavien merkkien kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Koska monet ovat ryhtyneet tekemään kertomusta meidän keskuudessamme tosiksi tunnetuista tapahtumista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'sen mukaisesti kuin meille ovat kertoneet ne, jotka alusta asti ovat omin silmin ne nähneet ja olleet sanan palvelijoita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'niin olen minäkin, tarkkaan tutkittuani alusta alkaen kaikki, päättänyt kirjoittaa ne järjestyksessään sinulle, korkea-arvoinen Teofilus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'että oppisit tuntemaan, kuinka varmat ne asiat ovat, jotka sinulle on opetettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Herodeksen, Juudean kuninkaan, aikana oli pappi, nimeltä Sakarias, Abian osastoa. Ja hänen vaimonsa oli Aaronin tyttäriä, ja tämän nimi oli Elisabet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'He olivat molemmat hurskaita Jumalan edessä, vaeltaen kaikissa Herran käskyissä ja säädöksissä nuhteettomina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Mutta heillä ei ollut lasta, sillä Elisabet oli hedelmätön; ja he olivat molemmat tulleet iällisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Niin tapahtui, kun hänen osastonsa palvelusvuoro tuli ja hän toimitti papillisia tehtäviä Jumalan edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'että hän tavanmukaisessa pappistehtävien arpomisessa sai osaksensa mennä Herran temppeliin suitsuttamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'Ja kaikki kansa oli suitsuttamisen aikana ulkopuolella rukoilemassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Silloin ilmestyi hänelle Herran enkeli seisoen suitsutusalttarin oikealla puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Ja hänet nähdessään Sakarias hämmästyi, ja hänet valtasi pelko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Mutta enkeli sanoi hänelle: \"Älä pelkää, Sakarias; sillä sinun rukouksesi on kuultu, ja vaimosi Elisabet on synnyttävä sinulle pojan, ja sinun on annettava hänelle nimi Johannes.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Ja hän on oleva sinulle iloksi ja riemuksi, ja monet iloitsevat hänen syntymisestään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Sillä hän on oleva suuri Herran edessä; viiniä ja väkijuomaa hän ei juo, ja hän on oleva täytetty Pyhällä Hengellä hamasta äitinsä kohdusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Ja hän kääntää monta Israelin lapsista Herran, heidän Jumalansa, tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Ja hän käy hänen edellään Eliaan hengessä ja voimassa, kääntääksensä isien sydämet lasten puoleen ja tottelemattomat vanhurskasten mielenlaatuun, näin Herralle toimittaaksensa valmistetun kansan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Niin Sakarias sanoi enkelille: \"Kuinka minä tämän käsittäisin? Sillä minä olen vanha, ja minun vaimoni on iälliseksi tullut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Enkeli vastasi ja sanoi hänelle: \"Minä olen Gabriel, joka seison Jumalan edessä, ja minä olen lähetetty puhumaan sinulle ja julistamaan sinulle tämän ilosanoman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Ja katso, sinä tulet mykäksi etkä kykene mitään puhumaan siihen päivään saakka, jona tämä tapahtuu, sentähden ettet uskonut minun sanojani, jotka käyvät aikanansa toteen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Ja kansa oli odottamassa Sakariasta, ja he ihmettelivät, että hän niin kauan viipyi temppelissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Mutta ulos tullessaan hän ei kyennyt puhumaan heille; silloin he ymmärsivät, että hän oli nähnyt näyn temppelissä. Ja hän viittoi heille ja jäi mykäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Ja kun hänen virkatoimensa päivät olivat päättyneet, meni hän kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Ja niiden päiväin perästä Elisabet, hänen vaimonsa, tuli raskaaksi ja pysytteli salassa viisi kuukautta, sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, '\"Näin on Herra tehnyt minulle niinä päivinä, jolloin hän katsoi minun puoleeni poistaaksensa minusta ihmisten ylenkatseen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Kuudentena kuukautena sen jälkeen Jumala lähetti enkeli Gabrielin Galilean kaupunkiin, jonka nimi on Nasaret,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'neitsyen tykö, joka oli kihlattu Joosef nimiselle miehelle Daavidin suvusta; ja neitsyen nimi oli Maria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 28, 'Ja tullessaan sisälle hänen tykönsä enkeli sanoi: \"Terve, armoitettu! Herra olkoon sinun kanssasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 29, 'Mutta hän hämmästyi suuresti siitä puheesta ja mietti, mitä tämä tervehdys mahtoi tarkoittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 30, 'Niin enkeli sanoi hänelle: \"Älä pelkää, Maria; sillä sinä olet saanut armon Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 31, 'Ja katso, sinä tulet raskaaksi ja synnytät pojan, ja sinun on annettava hänelle nimi Jeesus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 32, 'Hän on oleva suuri, ja hänet pitää kutsuttaman Korkeimman Pojaksi, ja Herra Jumala antaa hänelle Daavidin, hänen isänsä, valtaistuimen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 33, 'ja hän on oleva Jaakobin huoneen kuningas iankaikkisesti, ja hänen valtakunnallansa ei pidä loppua oleman.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 34, 'Niin Maria sanoi enkelille: \"Kuinka tämä voi tapahtua, kun minä en miehestä mitään tiedä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 35, 'Enkeli vastasi ja sanoi hänelle: \"Pyhä Henki tulee sinun päällesi, ja Korkeimman voima varjoaa sinut; sentähden myös se pyhä, mikä syntyy, pitää kutsuttaman Jumalan Pojaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 36, 'Ja katso, sinun sukulaisesi Elisabet, hänkin kantaa kohdussaan poikaa vanhalla iällään, ja tämä on kuudes kuukausi hänellä, jota sanottiin hedelmättömäksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 37, 'sillä Jumalalle ei mikään ole mahdotonta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 38, 'Silloin Maria sanoi: \"Katso, minä olen Herran palvelijatar; tapahtukoon minulle sinun sanasi mukaan\". Ja enkeli lähti hänen tyköänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 39, 'Niinä päivinä Maria nousi ja kulki kiiruusti vuorimaahan erääseen Juudan kaupunkiin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 40, 'ja meni Sakariaan kotiin ja tervehti Elisabetia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 41, 'Ja kun Elisabet kuuli Marian tervehdyksen, hypähti lapsi hänen kohdussansa; ja Elisabet täytettiin Pyhällä Hengellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 42, 'Ja hän puhkesi puhumaan suurella äänellä ja sanoi: \"Siunattu sinä vaimojen joukossa, ja siunattu sinun kohtusi hedelmä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 43, 'Ja kuinka minulle tapahtuu tämä, että minun Herrani äiti tulee minun tyköni?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 44, 'Sillä katso, kun sinun tervehdyksesi ääni tuli minun korviini, hypähti lapsi ilosta minun kohdussani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 45, 'Ja autuas se, joka uskoi, sillä se sana on täyttyvä, mikä hänelle on tullut Herralta!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 46, 'Ja Maria sanoi: \"Minun sieluni suuresti ylistää Herraa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 47, 'ja minun henkeni riemuitsee Jumalasta, vapahtajastani;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 48, 'sillä hän on katsonut palvelijattarensa alhaisuuteen. Katso, tästedes kaikki sukupolvet ylistävät minua autuaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 49, 'Sillä Voimallinen on tehnyt minulle suuria, ja hänen nimensä on pyhä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 50, 'ja hänen laupeutensa pysyy polvesta polveen niille, jotka häntä pelkäävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 51, 'Hän on osoittanut voimansa käsivarrellaan; hän on hajottanut ne, joilla oli ylpeät ajatukset sydämessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 52, 'Hän on kukistanut valtiaat valtaistuimilta ja korottanut alhaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 53, 'Nälkäiset hän on täyttänyt hyvyyksillä, ja rikkaat hän on lähettänyt tyhjinä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 54, 'Hän on ottanut huomaansa palvelijansa Israelin, muistaaksensa laupeuttaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 55, 'Aabrahamia ja hänen siementänsä kohtaan iankaikkisesti, niinkuin hän on meidän isillemme puhunut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 56, 'Ja Maria oli hänen tykönänsä noin kolme kuukautta ja palasi jälleen kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 57, 'Mutta Elisabetin synnyttämisen aika tuli; ja hän synnytti pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 58, 'Ja kun hänen naapurinsa ja sukulaisensa kuulivat, että Herra oli tehnyt hänelle suuren laupeuden, iloitsivat he hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 59, 'Ja kahdeksantena päivänä he tulivat ympärileikkaamaan lasta ja tahtoivat antaa hänelle hänen isänsä mukaan nimen Sakarias.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 60, 'Mutta hänen äitinsä vastasi ja sanoi: \"Ei suinkaan, vaan hänen nimensä on oleva Johannes\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 61, 'Niin he sanoivat hänelle: \"Eihän sinun suvussasi ole ketään, jolla on se nimi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 62, 'Ja he kysyivät viittomalla lapsen isältä, minkä nimen hän tahtoi hänelle annettavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 63, 'Niin hän pyysi taulun ja kirjoitti siihen nämä sanat: \"Johannes on hänen nimensä\". Ja kaikki ihmettelivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 64, 'Ja kohta hänen suunsa aukeni, ja hänen kielensä vapautui, ja hän puhui kiittäen Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 65, 'Ja tuli pelko kaikille heidän ympärillään asuvaisille, ja koko Juudean vuorimaassa puhuttiin kaikista näistä tapahtumista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 66, 'ja kaikki, jotka niistä kuulivat, panivat ne mieleensä ja sanoivat: \"Mikähän tästä lapsesta tulee?\" Sillä Herran käsi oli hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 67, 'Ja Sakarias, hänen isänsä, täytettiin Pyhällä Hengellä, ja hän ennusti sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 68, '\"Kiitetty olkoon Herra, Israelin Jumala, sillä hän on katsonut kansansa puoleen ja valmistanut sille lunastuksen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 69, 'ja kohottanut meille pelastuksen sarven palvelijansa Daavidin huoneesta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 70, '-niinkuin hän on puhunut hamasta ikiajoista pyhäin profeettainsa suun kautta-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 71, 'pelastukseksi vihollisistamme ja kaikkien niiden kädestä, jotka meitä vihaavat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 72, 'tehdäkseen laupeuden meidän isillemme ja muistaakseen pyhän liittonsa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 73, 'sen valan, jonka hän vannoi Aabrahamille, meidän isällemme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 74, 'suodakseen meidän, vapahdettuina vihollistemme kädestä, pelkäämättä palvella häntä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 75, 'pyhyydessä ja vanhurskaudessa hänen edessään kaikkina elinpäivinämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 76, 'Ja sinä, lapsukainen, olet kutsuttava Korkeimman profeetaksi, sillä sinä olet käyvä Herran edellä valmistaaksesi hänen teitään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 77, 'antaaksesi hänen kansalleen pelastuksen tuntemisen heidän syntiensä anteeksisaamisessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 78, 'meidän Jumalamme sydämellisen laupeuden tähden, jonka kautta meidän puoleemme katsoo aamun koitto korkeudesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 79, 'loistaen meille, jotka istumme pimeydessä ja kuoleman varjossa, ja ohjaten meidän jalkamme rauhan tielle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 80, 'Ja lapsi kasvoi ja vahvistui hengessä. Ja hän oli erämaassa siihen päivään asti, jona hän oli astuva Israelin eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Ja tapahtui niinä päivinä, että keisari Augustukselta kävi käsky, että kaikki maailma oli verolle pantava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Tämä verollepano oli ensimmäinen ja tapahtui Kyreniuksen ollessa Syyrian maaherrana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Ja kaikki menivät verolle pantaviksi, kukin omaan kaupunkiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Niin Joosefkin lähti Galileasta, Nasaretin kaupungista, ylös Juudeaan, Daavidin kaupunkiin, jonka nimi on Beetlehem, hän kun oli Daavidin huonetta ja sukua,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'verolle pantavaksi Marian, kihlattunsa, kanssa, joka oli raskaana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Niin tapahtui heidän siellä ollessaan, että Marian synnyttämisen aika tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Ja hän synnytti pojan, esikoisensa, ja kapaloi hänet ja pani hänet seimeen, koska heille ei ollut sijaa majatalossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Ja sillä seudulla oli paimenia kedolla vartioimassa yöllä laumaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Niin heidän edessään seisoi Herran enkeli, ja Herran kirkkaus loisti heidän ympärillään, ja he peljästyivät suuresti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Mutta enkeli sanoi heille: \"Älkää peljätkö; sillä katso, minä ilmoitan teille suuren ilon, joka on tuleva kaikelle kansalle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'teille on tänä päivänä syntynyt Vapahtaja, joka on Kristus, Herra, Daavidin kaupungissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Ja tämä on teille merkkinä: te löydätte lapsen kapaloituna ja seimessä makaamassa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Ja yhtäkkiä oli enkelin kanssa suuri joukko taivaallista sotaväkeä, ja he ylistivät Jumalaa ja sanoivat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, '\"Kunnia Jumalalle korkeuksissa, ja maassa rauha ihmisten kesken, joita kohtaan hänellä on hyvä tahto!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Ja kun enkelit olivat menneet paimenten luota taivaaseen, niin nämä puhuivat toisillensa: \"Menkäämme nyt Beetlehemiin katsomaan sitä, mikä on tapahtunut ja minkä Herra meille ilmoitti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'Ja he menivät kiiruhtaen ja löysivät Marian ja Joosefin ja lapsen, joka makasi seimessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Ja kun he tämän olivat nähneet, ilmoittivat he sen sanan, joka oli puhuttu heille tästä lapsesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Ja kaikki, jotka sen kuulivat, ihmettelivät sitä, mitä paimenet heille puhuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Mutta Maria kätki kaikki nämä sanat ja tutkisteli niitä sydämessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Ja paimenet palasivat kiittäen ja ylistäen Jumalaa kaikesta, minkä olivat kuulleet ja nähneet, sen mukaan kuin heille oli puhuttu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Kun sitten kahdeksan päivää oli kulunut ja lapsi oli ympärileikattava, annettiin hänelle nimi Jeesus, jonka enkeli oli hänelle antanut, ennenkuin hän sikisi äitinsä kohdussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Ja kun heidän puhdistuspäivänsä, Mooseksen lain mukaan, olivat täyttyneet, veivät he hänet ylös Jerusalemiin asettaaksensa hänet Herran eteen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, '-niinkuin on kirjoitettuna Herran laissa: \"Jokainen miehenpuoli, joka avaa äidinkohdun, luettakoon Herralle pyhitetyksi\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'ja uhrataksensa, niinkuin Herran laissa on säädetty, parin metsäkyyhkysiä tai kaksi kyyhkysenpoikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Ja katso, Jerusalemissa oli mies, nimeltä Simeon; hän oli hurskas ja jumalinen mies, joka odotti Israelin lohdutusta, ja Pyhä Henki oli hänen päällänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Ja Pyhä Henki oli hänelle ilmoittanut, ettei hän ollut näkevä kuolemaa, ennenkuin oli nähnyt Herran Voidellun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 27, 'Ja hän tuli Hengen vaikutuksesta pyhäkköön. Ja kun vanhemmat toivat Jeesus-lasta sisälle tehdäkseen hänelle, niinkuin tapa oli lain mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 28, 'otti hänkin hänet syliinsä ja kiitti Jumalaa ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 29, '\"Herra, nyt sinä lasket palvelijasi rauhaan menemään, sanasi mukaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 30, 'sillä minun silmäni ovat nähneet sinun autuutesi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 31, 'jonka sinä olet valmistanut kaikkien kansojen nähdä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 32, 'valkeudeksi, joka on ilmestyvä pakanoille, ja kirkkaudeksi kansallesi Israelille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 33, 'Ja hänen isänsä ja äitinsä ihmettelivät sitä, mitä hänestä sanottiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 34, 'Ja Simeon siunasi heitä ja sanoi Marialle, hänen äidilleen: \"Katso, tämä on pantu lankeemukseksi ja nousemukseksi monelle Israelissa ja merkiksi, jota vastaan sanotaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 35, '-ja myös sinun sielusi lävitse on miekka käyvä-että monen sydämen ajatukset tulisivat ilmi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 36, 'Ja oli naisprofeetta, Hanna, Fanuelin tytär, Asserin sukukuntaa. Hän oli jo tullut iälliseksi. Mentyään neitsyenä naimisiin hän oli elänyt miehensä kanssa seitsemän vuotta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 37, 'ja oli nyt leski, kahdeksankymmenen neljän vuoden ikäinen. Hän ei poistunut pyhäköstä, vaan palveli siellä Jumalaa paastoilla ja rukouksilla yötä ja päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 38, 'Ja juuri sillä hetkellä hän tuli siihen, ylisti Jumalaa ja puhui lapsesta kaikille, jotka odottivat Jerusalemin lunastusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 39, 'Ja täytettyään kaiken, mikä Herran lain mukaan oli tehtävä, he palasivat Galileaan, kaupunkiinsa Nasaretiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 40, 'Ja lapsi kasvoi ja vahvistui ja täyttyi viisaudella, ja Jumalan armo oli hänen päällänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 41, 'Ja hänen vanhempansa matkustivat joka vuosi Jerusalemiin pääsiäisjuhlille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 42, 'Hänen ollessaan kaksitoistavuotias he niinikään vaelsivat ylös sinne juhlan tavan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 43, 'Ja kun ne päivät olivat kuluneet ja he lähtivät kotiin, jäi poikanen Jeesus Jerusalemiin, eivätkä hänen vanhempansa sitä huomanneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 44, 'He luulivat hänen olevan matkaseurueessa ja kulkivat päivänmatkan ja etsivät häntä sukulaisten ja tuttavien joukosta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 45, 'mutta kun eivät löytäneet, palasivat he Jerusalemiin etsien häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 46, 'Ja kolmen päivän kuluttua he löysivät hänet pyhäköstä, jossa hän istui opettajain keskellä kuunnellen heitä ja kysellen heiltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 47, 'Ja kaikki, jotka häntä kuulivat, ihmettelivät hänen ymmärrystänsä ja vastauksiansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 48, 'Ja hänet nähdessään hänen vanhempansa hämmästyivät, ja hänen äitinsä sanoi hänelle: \"Poikani, miksi meille näin teit? Katso, sinun isäsi ja minä olemme huolestuneina etsineet sinua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 49, 'Niin hän sanoi heille: \"Mitä te minua etsitte? Ettekö tienneet, että minun pitää niissä oleman, mitkä minun Isäni ovat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 50, 'Mutta he eivät ymmärtäneet sitä sanaa, jonka hän heille puhui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 51, 'Ja hän lähti heidän kanssansa ja tuli Nasaretiin ja oli heille alamainen. Ja hänen äitinsä kätki kaikki nämä sanat sydämeensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 52, 'Ja Jeesus varttui viisaudessa ja iässä ja armossa Jumalan ja ihmisten edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Viidentenätoista keisari Tiberiuksen hallitusvuotena, kun Pontius Pilatus oli Juudean maaherrana ja Herodes Galilean neljännysruhtinaana ja hänen veljensä Filippus Iturean ja Trakonitiinmaan neljännysruhtinaana ja Lysanias Abilenen neljännysruhtinaana,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'siihen aikaan kun Hannas oli ylimmäisenä pappina, ynnä myös Kaifas, tuli Jumalan sana Johannekselle, Sakariaan pojalle, erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Ja hän vaelsi kaikissa seuduissa Jordanin varrella ja saarnasi parannuksen kastetta syntien anteeksisaamiseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'niinkuin on kirjoitettuna profeetta Esaiaan sanojen kirjassa: \"Huutavan ääni kuuluu erämaassa: \'Valmistakaa Herralle tie, tehkää polut hänelle tasaisiksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Kaikki laaksot täytettäköön, ja kaikki vuoret ja kukkulat alennettakoon, ja mutkat tulkoot suoriksi ja koleikot tasaisiksi teiksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'ja kaikki liha on näkevä Jumalan autuuden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Niin hän sanoi kansalle, joka vaelsi hänen kastettavakseen: \"Te kyykäärmeitten sikiöt, kuka on teitä neuvonut pakenemaan tulevaista vihaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Tehkää sentähden parannuksen soveliaita hedelmiä, älkääkä ruvetko sanomaan mielessänne: \'Onhan meillä isänä Aabraham\', sillä minä sanon teille, että Jumala voi näistä kivistä herättää lapsia Aabrahamille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Jo on myös kirves pantu puitten juurelle; jokainen puu, joka ei tee hyvää hedelmää, siis hakataan pois ja heitetään tuleen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Ja kansa kysyi häneltä sanoen: \"Mitä meidän siis pitää tekemän?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Hän vastasi ja sanoi heille: \"Jolla on kaksi ihokasta, antakoon toisen sille, joka on ilman; ja jolla on ruokaa, tehköön samoin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Niin tuli myös publikaaneja kastettaviksi, ja he sanoivat hänelle: \"Opettaja, mitä meidän pitää tekemän?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Hän sanoi heille: \"Älkää vaatiko enempää, kuin mikä teille on säädetty\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Myös sotamiehet kysyivät häneltä sanoen: \"Mitäs meidän pitää tekemän?\" Ja hän sanoi heille: \"Älkää kiskoko keneltäkään älkääkä kiristäkö, vaan tyytykää palkkaanne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Mutta kun kansa yhä odotti ja kaikki ajattelivat sydämessään Johanneksesta, eikö hän itse ehkä ollut Kristus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'niin Johannes vastasi kaikille sanoen: \"Minä kastan teidät vedellä, mutta on tuleva minua väkevämpi, jonka kengänpaulaakaan minä en ole kelvollinen päästämään; hän kastaa teidät Pyhällä Hengellä ja tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Hänellä on viskimensä kädessään, ja hän puhdistaa puimatanterensa ja kokoaa nisut aittaansa, mutta ruumenet hän polttaa sammumattomassa tulessa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Antaen myös monia muita kehoituksia hän julisti kansalle evankeliumia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 19, 'Mutta kun Herodes, neljännysruhtinas, sai häneltä nuhteita veljensä vaimon, Herodiaan, tähden ja kaiken sen pahan tähden, mitä hän, Herodes, oli tehnyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 20, 'niin hän kaiken muun lisäksi teki senkin, että sulki Johanneksen vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 21, 'Kun siis kaikkea kansaa kastettiin ja myöskin Jeesus oli saanut kasteen ja rukoili, niin tapahtui, että taivas aukeni');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 22, 'ja Pyhä Henki laskeutui hänen päällensä ruumiillisessa muodossa, niinkuin kyyhkynen, ja taivaasta tuli ääni: \"Sinä olet minun rakas Poikani; sinuun minä olen mielistynyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 23, 'Ja hän, Jeesus, oli alottaessaan vaikutuksensa noin kolmenkymmenen vuoden vanha, ja oli, niinkuin luultiin, Joosefin poika. Joosef oli Eelin poika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 24, 'Eeli Mattatin, tämä Leevin, tämä Melkin, tämä Jannain, tämä Joosefin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 25, 'tämä Mattatiaan, tämä Aamoksen, tämä Naahumin, tämä Eslin, tämä Naggain,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 26, 'tämä Maahatin, tämä Mattatiaan, tämä Semeinin, tämä Joosekin, tämä Joodan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 27, 'tämä Johananin, tämä Reesan, tämä Serubbaabelin, tämä Sealtielin, tämä Neerin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 28, 'tämä Melkin, tämä Addin, tämä Koosamin, tämä Elmadamin, tämä Eerin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 29, 'tämä Jeesuksen, tämä Elieserin, tämä Joorimin, tämä Mattatin, tämä Leevin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 30, 'tämä Simeonin, tämä Juudan, tämä Joosefin, tämä Joonamin, tämä Eliakimin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 31, 'tämä Melean, tämä Mennan, tämä Mattatan, tämä Naatanin, tämä Daavidin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 32, 'tämä Iisain, tämä Oobedin, tämä Booaan, tämä Saalan, tämä Nahassonin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 33, 'tämä Aminadabin, tämä Adminin, tämä Arnin, tämä Esromin, tämä Faareen, tämä Juudan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 34, 'tämä Jaakobin, tämä Iisakin, tämä Aabrahamin, tämä Taaran, tämä Naahorin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 35, 'tämä Serukin, tämä Ragaun, tämä Faalekin, tämä Eberin, tämä Saalan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 36, 'tämä Kainamin, tämä Arfaksadin, tämä Seemin, tämä Nooan, tämä Laamekin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 37, 'tämä Metusalan, tämä Eenokin, tämä Jaaretin, tämä Mahalalelin, tämä Keenanin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 38, 'tämä Enoksen, tämä Seetin, tämä Aadamin, tämä Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Sitten Jeesus täynnä Pyhää Henkeä palasi Jordanilta; ja Henki kuljetti häntä erämaassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'ja perkele kiusasi häntä neljäkymmentä päivää. Eikä hän syönyt mitään niinä päivinä, mutta kun ne olivat päättyneet, tuli hänen nälkä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Niin perkele sanoi hänelle: \"Jos sinä olet Jumalan Poika, niin sano tälle kivelle, että se muuttuu leiväksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Jeesus vastasi hänelle: \"Kirjoitettu on: \'Ei ihminen elä ainoastaan leivästä\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Ja perkele vei hänet korkealle vuorelle ja näytti hänelle yhdessä tuokiossa kaikki maailman valtakunnat');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'ja sanoi hänelle: \"Sinulle minä annan kaiken tämän valtapiirin ja sen loiston, sillä minun haltuuni se on annettu, ja minä annan sen, kenelle tahdon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Jos sinä siis kumarrut minun eteeni, niin tämä kaikki on oleva sinun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Jeesus vastasi ja sanoi hänelle: \"Kirjoitettu on: \'Sinun pitää kumartaman Herraa, sinun Jumalaasi, ja häntä ainoata palveleman\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Niin hän vei hänet Jerusalemiin ja asetti hänet pyhäkön harjalle ja sanoi hänelle: \"Jos sinä olet Jumalan Poika, niin heittäydy tästä alas;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'sillä kirjoitettu on: \'Hän antaa enkeleilleen käskyn sinusta, että he varjelevat sinua\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'ja: \'He kantavat sinua käsillänsä, ettet jalkaasi kiveen loukkaisi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Jeesus vastasi ja sanoi hänelle: \"Sanottu on: \'Älä kiusaa Herraa, sinun Jumalaasi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Ja kun oli kaiken kiusattavansa kiusannut, poistui perkele hänen luotaan ajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Ja Jeesus palasi Hengen voimassa Galileaan; ja sanoma hänestä levisi kaikkiin ympärillä oleviin seutuihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Ja hän opetti heidän synagoogissaan, ja kaikki ylistivät häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Ja hän saapui Nasaretiin, jossa hänet oli kasvatettu, ja meni tapansa mukaan sapatinpäivänä synagoogaan ja nousi lukemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Niin hänelle annettiin profeetta Esaiaan kirja, ja kun hän avasi kirjan, löysi hän sen paikan, jossa oli kirjoitettuna:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 18, '\"Herran Henki on minun päälläni, sillä hän on voidellut minut julistamaan evankeliumia köyhille; hän on lähettänyt minut saarnaamaan vangituille vapautusta ja sokeille näkönsä saamista, päästämään sorretut vapauteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 19, 'saarnaamaan Herran otollista vuotta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 20, 'Ja käärittyään kirjan kokoon hän antoi sen palvelijalle ja istuutui; ja kaikkien synagoogassa olevien silmät olivat häneen kiinnitetyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 21, 'Niin hän rupesi puhumaan heille: \"Tänä päivänä tämä kirjoitus on käynyt toteen teidän korvainne kuullen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 22, 'Ja kaikki lausuivat hänestä hyvän todistuksen ja ihmettelivät niitä armon sanoja, jotka hänen suustansa lähtivät; ja he sanoivat: \"Eikö tämä ole Joosefin poika?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 23, 'Niin hän sanoi heille: \"Kaiketi aiotte sanoa minulle tämän sananlaskun: \'Parantaja, paranna itsesi\'; \'tee täälläkin, kotikaupungissasi, niitä suuria tekoja, joita olemme kuulleet tapahtuneen Kapernaumissa\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 24, 'Ja hän sanoi: \"Totisesti minä sanon teille: ei kukaan profeetta ole otollinen kotikaupungissaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 25, 'Minä sanon teille totuudessa: monta leskeä oli Eliaan aikana Israelissa, kun taivas oli suljettuna kolme vuotta ja kuusi kuukautta ja suuri nälkä tuli kaikkeen maahan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 26, 'eikä Eliasta lähetetty kenenkään tykö heistä, vaan ainoastaan leskivaimon tykö Siidonin-maan Sareptaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 27, 'Ja monta pitalista miestä oli Israelissa profeetta Elisan aikana, eikä kukaan heistä tullut puhdistetuksi, vaan ainoastaan Naiman, syyrialainen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 28, 'Tämän kuullessaan kaikki, jotka olivat synagoogassa, tulivat kiukkua täyteen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 29, 'ja nousivat ja ajoivat hänet ulos kaupungista ja veivät hänet sen vuoren jyrkänteelle asti, jolle heidän kaupunkinsa oli rakennettu, syöstäkseen hänet alas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 30, 'Mutta hän lähti pois käyden heidän keskitsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 31, 'Ja hän meni alas Kapernaumiin, Galilean kaupunkiin, ja opetti kansaa sapattina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 32, 'Ja he olivat hämmästyksissään hänen opetuksestansa, sillä hänen puheessansa oli voima.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 33, 'Ja synagoogassa oli mies, jossa oli saastaisen riivaajan henki. Tämä huusi suurella äänellä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 34, '\"Voi, mitä sinulla on meidän kanssamme tekemistä, Jeesus Nasaretilainen? Oletko tullut meitä tuhoamaan? Minä tunnen sinut, kuka olet, sinä Jumalan Pyhä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 35, 'Niin Jeesus nuhteli häntä sanoen: \"Vaikene ja lähde hänestä\". Ja riivaaja viskasi hänet maahan heidän keskelleen ja lähti hänestä, häntä ollenkaan vahingoittamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 36, 'Ja heidät kaikki valtasi hämmästys, ja he puhuivat keskenään sanoen: \"Mitä tämä puhe on, sillä hän käskee vallalla ja voimalla saastaisia henkiä, ja ne lähtevät ulos?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 37, 'Ja maine hänestä levisi kaikkialle ympäristön seutuihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 38, 'Niin hän nousi ja meni synagoogasta Simonin kotiin. Ja Simonin anoppi sairasti kovaa kuumetta, ja he rukoilivat Jeesusta hänen puolestansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 39, 'Niin hän meni ja kumartui hänen ylitsensä ja nuhteli kuumetta, ja se lähti hänestä; ja heti vaimo nousi ja palveli heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 40, 'Auringon laskiessa kaikki, joilla oli sairaita, mikä missäkin taudissa, veivät ne hänen tykönsä. Ja hän pani kätensä heidän itsekunkin päälle ja paransi heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 41, 'Myös lähtivät riivaajat ulos monesta, huutaen ja sanoen: \"Sinä olet Jumalan Poika!\" Mutta hän nuhteli niitä eikä sallinut niiden puhua, koska ne tiesivät hänen olevan Kristuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 42, 'Ja päivän tultua hän lähti pois ja meni autioon paikkaan; mutta kansa etsi häntä, ja saavuttuaan hänen luokseen he pidättelivät häntä lähtemästä heidän luotansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 43, 'Mutta hän sanoi heille: \"Minun tulee muillekin kaupungeille julistaa Jumalan valtakunnan evankeliumia, sillä sitä varten minä olen lähetetty\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 44, 'Ja hän saarnasi Galilean synagoogissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Kun kansa tunkeutui hänen ympärilleen kuulemaan Jumalan sanaa ja hän seisoi Gennesaretin järven rannalla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'niin hän näki järven rannassa kaksi venhettä; mutta kalastajat olivat niistä lähteneet ja huuhtoivat verkkojaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Ja hän astui toiseen niistä, joka oli Simonin, ja pyysi häntä viemään sen vähän matkaa maasta; ja hän istui ja opetti kansaa venheestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Mutta puhumasta lakattuaan hän sanoi Simonille: \"Vie venhe syvälle ja heittäkää verkkonne apajalle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Niin Simon vastasi ja sanoi hänelle: \"Mestari, koko yön me olemme tehneet työtä emmekä ole mitään saaneet; mutta sinun käskystäsi minä heitän verkot\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Ja sen tehtyään he saivat kierretyksi suuren joukon kaloja, ja heidän verkkonsa repeilivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Niin he viittasivat toisessa venheessä oleville tovereilleen, että nämä tulisivat auttamaan heitä; ja he tulivat. Ja he täyttivät molemmat venheet, niin että ne olivat uppoamaisillaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Kun Simon Pietari sen näki, lankesi hän Jeesuksen polvien eteen ja sanoi: \"Mene pois minun tyköäni, Herra, sillä minä olen syntinen ihminen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Sillä kalansaaliin tähden, jonka he olivat saaneet, oli hämmästys vallannut hänet ja kaikki ne, jotka olivat hänen kanssaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'ja samoin myös Simonin kalastuskumppanit, Jaakobin ja Johanneksen, Sebedeuksen pojat. Mutta Jeesus sanoi Simonille: \"Älä pelkää, tästedes sinä saat saaliiksi ihmisiä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Ja he veivät venheet maihin, jättivät kaikki ja seurasivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Ja kun hän oli eräässä kaupungissa, niin katso, siellä oli mies, yltänsä pitalissa. Ja nähdessään Jeesuksen hän lankesi kasvoilleen ja rukoili häntä sanoen: \"Herra, jos tahdot, niin sinä voit minut puhdistaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Niin hän ojensi kätensä, kosketti häntä ja sanoi: \"Minä tahdon; puhdistu\". Ja kohta pitali lähti hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Ja hän kielsi häntä siitä kenellekään puhumasta ja sanoi: \"Mene, näytä itsesi papille, ja uhraa puhdistumisestasi, niinkuin Mooses on säätänyt, todistukseksi heille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Mutta sanoma hänestä levisi vielä enemmän; ja paljon kansaa kokoontui kuulemaan häntä ja parantuakseen vaivoistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Mutta hän vetäytyi pois ja oleskeli erämaassa ja rukoili.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Ja eräänä päivänä, kun hän opetti, istui siinä fariseuksia ja lainopettajia, joita oli tullut kaikista Galilean ja Juudean kylistä ja Jerusalemista; ja Herran voima vaikutti, niin että hän paransi sairaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Ja katso, muutamat miehet kantoivat vuoteella miestä, joka oli halvattu; ja he koettivat viedä hänet sisään ja asettaa Jeesuksen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Ja kun he väentungokselta eivät saaneet viedyksi häntä sisään muuta tietä, nousivat he katolle ja laskivat hänet vuoteineen tiilikaton läpi heidän keskellensä Jeesuksen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Ja nähdessään heidän uskonsa hän sanoi: \"Ihminen, sinun syntisi ovat sinulle anteeksi annetut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 21, 'Niin kirjanoppineet ja fariseukset rupesivat ajattelemaan ja sanomaan: \"Kuka tämä on, joka puhuu Jumalan pilkkaa? Kuka voi antaa syntejä anteeksi, paitsi Jumala yksin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 22, 'Mutta kun Jeesus tiesi heidän ajatuksensa, vastasi hän ja sanoi heille: \"Mitä te ajattelette sydämessänne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 23, 'Kumpi on helpompaa, sanoako: \'Sinun syntisi ovat sinulle anteeksi annetut\', vai sanoa: \'Nouse ja käy\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 24, 'Mutta tietääksenne, että Ihmisen Pojalla on valta maan päällä antaa syntejä anteeksi,\" -hän sanoi halvatulle-\"minä sanon sinulle: nouse, ota vuoteesi ja mene kotiisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 25, 'Ja kohta hän nousi heidän nähtensä, otti vuoteen, jolla oli maannut, ja lähti kotiinsa ylistäen Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 26, 'Ja heidät kaikki valtasi hämmästys, ja he ylistivät Jumalaa; ja pelkoa täynnä he sanoivat: \"Me olemme tänään nähneet ihmeellisiä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 27, 'Ja sen jälkeen hän lähti sieltä ja näki tulliasemalla istumassa publikaanin, jonka nimi oli Leevi, ja sanoi hänelle: \"Seuraa minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 28, 'Niin tämä jätti kaikki, nousi ja seurasi häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 29, 'Ja Leevi valmisti hänelle suuret pidot kodissaan; ja siellä oli suuri joukko publikaaneja ja muita aterioimassa heidän kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 30, 'Niin fariseukset ja heidän kirjanoppineensa napisivat hänen opetuslapsiansa vastaan ja sanoivat: \"Miksi te syötte ja juotte publikaanien ja syntisten kanssa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 31, 'Jeesus vastasi ja sanoi heille: \"Eivät terveet tarvitse parantajaa, vaan sairaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 32, 'En minä ole tullut kutsumaan vanhurskaita, vaan syntisiä parannukseen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 33, 'Niin he sanoivat hänelle: \"Johanneksen opetuslapset paastoavat usein ja pitävät rukouksia, samoin fariseustenkin, mutta sinun opetuslapsesi syövät ja juovat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 34, 'Jeesus sanoi heille: \"Ettehän voi vaatia häävieraita paastoamaan silloin, kun ylkä on heidän kanssaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 35, 'Mutta päivät tulevat, jolloin ylkä otetaan heiltä pois, ja silloin, niinä päivinä, he paastoavat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 36, 'Ja hän sanoi heille myös vertauksen: \"Ei kukaan leikkaa uudesta vaipasta paikkaa ja pane vanhaan vaippaan; muutoin hän rikkoo uuden vaipan, eikä uudesta vaipasta otettu paikka vanhaan sovi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 37, 'Eikä kukaan laske nuorta viiniä vanhoihin nahkaleileihin; muutoin nuori viini pakahuttaa leilit, ja viini juoksee maahan, ja leilit turmeltuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 38, 'Vaan nuori viini on laskettava uusiin leileihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 39, 'Eikä kukaan, joka juo vanhaa viiniä, halua nuorta, sillä hän sanoo: \'Vanha on hyvää\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 1, 'Niin tapahtui eräänä sapattina, että hän kulki viljavainioiden halki, ja hänen opetuslapsensa katkoivat tähkäpäitä, hiersivät niitä käsissään ja söivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 2, 'Silloin muutamat fariseuksista sanoivat: \"Miksi teette, mitä ei ole lupa tehdä sapattina?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 3, 'Mutta Jeesus vastasi heille ja sanoi: \"Ettekö ole lukeneet, mitä Daavid teki, kun hänen ja hänen seuralaistensa oli nälkä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 4, 'kuinka hän meni Jumalan huoneeseen, otti näkyleivät ja söi ja antoi seuralaisilleenkin, vaikkei niitä ollut lupa syödä muiden kuin ainoastaan pappien?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 5, 'Ja hän sanoi heille: \"Ihmisen Poika on sapatin herra\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 6, 'Ja toisena sapattina hän meni synagoogaan ja opetti; ja siellä oli mies, jonka oikea käsi oli kuivettunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 7, 'Ja keksiäkseen jotakin, mistä häntä syyttäisivät, kirjanoppineet ja fariseukset pitivät häntä silmällä, parantaisiko hän sapattina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 8, 'Mutta hän tiesi heidän ajatuksensa ja sanoi miehelle, jonka käsi oli kuivettunut: \"Nouse ja astu esille\". Ja hän nousi ja astui esille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 9, 'Niin Jeesus sanoi heille: \"Minä kysyn teiltä: kumpi on luvallista sapattina: hyvääkö tehdä, vai tehdä pahaa, pelastaako henki, vai hukuttaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 10, 'Ja hän katsoi ympärilleen heihin kaikkiin ja sanoi miehelle: \"Ojenna kätesi\". Mies teki niin, ja hänen kätensä tuli jälleen terveeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 11, 'Mutta he vimmastuivat kovin ja puhelivat keskenään, mitä heidän olisi tehtävä Jeesukselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 12, 'Niin tapahtui niinä päivinä, että hän lähti vuorelle rukoilemaan; ja hän oli siellä kaiken yötä rukoillen Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 13, 'Ja päivän tultua hän kutsui tykönsä opetuslapsensa ja valitsi heistä kaksitoista, joille hän myös antoi apostolin nimen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 14, 'Simonin, jolle hän myös antoi nimen Pietari, ja Andreaan, hänen veljensä, ja Jaakobin ja Johanneksen, ja Filippuksen ja Bartolomeuksen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 15, 'ja Matteuksen ja Tuomaan, ja Jaakobin, Alfeuksen pojan, ja Simonin, jota kutsuttiin Kiivailijaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 16, 'ja Juudaan, Jaakobin pojan, sekä Juudas Iskariotin, josta tuli kavaltaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 17, 'Ja hän astui alas heidän kanssaan ja seisahtui lakealle paikalle; ja siellä oli suuri joukko hänen opetuslapsiaan ja paljon kansaa kaikesta Juudeasta ja Jerusalemista ja Tyyron ja Siidonin rantamaasta. Nämä olivat saapuneet kuulemaan häntä ja parantuakseen taudeistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 18, 'Ja myös ne, jotka olivat saastaisten henkien vaivaamia, tulivat terveiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 19, 'Ja kaikki kansa tahtoi päästä koskettamaan häntä, koska hänestä lähti voima, joka paransi kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 20, 'Ja hän nosti silmänsä opetuslastensa puoleen ja sanoi: \"Autuaita olette te, köyhät, sillä teidän on Jumalan valtakunta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 21, 'Autuaita te, jotka nyt isoatte, sillä teidät ravitaan! Autuaita te, jotka nyt itkette, sillä te saatte nauraa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 22, 'Autuaita olette te, kun ihmiset vihaavat teitä ja erottavat teidät yhteydestään ja herjaavat teitä ja pyyhkivät pois teidän nimenne ikäänkuin jonkin pahan-Ihmisen Pojan tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 23, 'Iloitkaa sinä päivänä, riemuun ratketkaa; sillä katso, teidän palkkanne on suuri taivaassa; sillä näin tekivät heidän isänsä profeetoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 24, 'Mutta voi teitä, te rikkaat, sillä te olette jo saaneet lohdutuksenne!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 25, 'Voi teitä, jotka nyt olette kylläiset, sillä teidän on oleva nälkä! Voi teitä, jotka nyt nauratte, sillä te saatte murehtia ja itkeä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 26, 'Voi teitä, kun kaikki ihmiset puhuvat teistä hyvää! Sillä niin tekivät heidän isänsä väärille profeetoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 27, 'Mutta teille, jotka kuulette, minä sanon: rakastakaa vihollisianne, tehkää hyvää niille, jotka teitä vihaavat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 28, 'siunatkaa niitä, jotka teitä kiroavat, rukoilkaa niiden edestä, jotka teitä parjaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 29, 'Jos joku lyö sinua poskelle, tarjoa hänelle toinenkin, ja jos joku ottaa sinulta vaipan, älä häneltä kiellä ihokastasikaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 30, 'Anna jokaiselle, joka sinulta anoo, äläkä vaadi takaisin siltä, joka sinun omaasi ottaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 31, 'Ja niinkuin te tahdotte ihmisten teille tekevän, niin tehkää tekin heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 32, 'Ja jos te rakastatte niitä, jotka teitä rakastavat, mitä kiitosta teille siitä tulee? Rakastavathan syntisetkin niitä, jotka heitä rakastavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 33, 'Ja jos teette hyvää niille, jotka teille hyvää tekevät, mitä kiitosta teille siitä tulee? Niinhän syntisetkin tekevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 34, 'Ja jos te lainaatte niille, joilta toivotte saavanne takaisin, mitä kiitosta teille siitä tulee? Syntisetkin lainaavat syntisille saadakseen saman verran takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 35, 'Vaan rakastakaa vihollisianne ja tehkää hyvää ja lainatkaa, toivomatta saavanne mitään takaisin; niin teidän palkkanne on oleva suuri, ja te tulette Korkeimman lapsiksi, sillä hän on hyvä kiittämättömille ja pahoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 36, 'Olkaa armahtavaiset, niinkuin teidän Isänne on armahtavainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 37, 'Älkääkä tuomiko, niin ei teitäkään tuomita; älkää kadotustuomiota lausuko, niin ei teillekään kadotustuomiota lausuta. Antakaa anteeksi, niin teillekin anteeksi annetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 38, 'Antakaa, niin teille annetaan. Hyvä mitta, sullottu, pudistettu ja kukkurainen, annetaan teidän helmaanne; sillä millä mitalla te mittaatte, sillä mitataan teille takaisin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 39, 'Hän sanoi heille myös vertauksen: \"Eihän sokea voi sokeaa taluttaa? Eivätkö molemmat lankea kuoppaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 40, 'Ei ole opetuslapsi opettajaansa parempi; täysin oppineena jokainen on oleva niinkuin hänen opettajansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 41, 'Kuinka näet rikan, joka on veljesi silmässä, mutta et huomaa malkaa omassa silmässäsi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 42, 'Kuinka saatat sanoa veljellesi: \'Veljeni, annas, minä otan pois rikan, joka on silmässäsi\', sinä, joka et näe malkaa omassa silmässäsi? Sinä ulkokullattu, ota ensin malka omasta silmästäsi, sitten sinä näet ottaa pois rikan, joka on veljesi silmässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 43, 'Sillä ei ole hyvää puuta, joka tekee huonon hedelmän, eikä taas huonoa puuta, joka tekee hyvän hedelmän;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 44, 'sillä jokainen puu tunnetaan hedelmästään. Eihän viikunoita koota orjantappuroista, eikä viinirypäleitä korjata orjanruusupensaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 45, 'Hyvä ihminen tuo sydämensä hyvän runsaudesta esiin hyvää, ja paha tuo pahastansa esiin pahaa; sillä sydämen kyllyydestä suu puhuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 46, 'Miksi te huudatte minulle: \'Herra, Herra!\' ettekä tee, mitä minä sanon?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 47, 'Jokainen, joka tulee minun tyköni ja kuulee minun sanani ja tekee niiden mukaan-minä osoitan teille, kenen kaltainen hän on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 48, 'Hän on miehen kaltainen, joka huonetta rakentaessaan kaivoi syvään ja laski perustuksen kalliolle; kun sitten tulva tuli, syöksähti virta sitä huonetta vastaan, mutta ei voinut sitä horjuttaa, sillä se oli hyvästi rakennettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 6, 49, 'Mutta joka kuulee eikä tee, se on miehen kaltainen, joka perustusta panematta rakensi huoneensa maan pinnalle; ja virta syöksähti sitä vastaan, ja heti se sortui, ja sen huoneen kukistuminen oli suuri.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 1, 'Kun hän oli kansan kuullen kaikki nämä puheensa puhunut, meni hän Kapernaumiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 2, 'Ja eräällä sadanpäämiehellä oli palvelija, joka sairasti ja oli kuolemaisillaan ja jota hän piti suuressa arvossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 3, 'Ja kuultuaan Jeesuksesta hän lähetti juutalaisten vanhimpia hänen tykönsä ja pyysi, että hän tulisi parantamaan hänen palvelijansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 4, 'Kun nämä saapuivat Jeesuksen tykö, pyysivät he häntä hartaasti ja sanoivat: \"Hän ansaitsee, että teet hänelle tämän;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 5, 'sillä hän rakastaa meidän kansaamme, ja hän on rakentanut meille synagoogan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 6, 'Niin Jeesus lähti heidän kanssansa. Mutta kun hän ei enää ollut kaukana talosta, lähetti sadanpäämies ystäviänsä sanomaan hänelle: \"Herra, älä vaivaa itseäsi, sillä en minä ole sen arvoinen, että tulisit minun kattoni alle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 7, 'sentähden en katsonutkaan itseäni arvolliseksi tulemaan sinun luoksesi; vaan sano sana, niin minun palvelijani paranee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 8, 'Sillä minä itsekin olen toisen vallan alaiseksi asetettu, ja minulla on sotamiehiä käskettävinäni, ja minä sanon tälle: \'Mene\', ja hän menee, ja toiselle: \'Tule\', ja hän tulee, ja palvelijalleni: \'Tee tämä\', ja hän tekee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 9, 'Tämän kuultuaan Jeesus ihmetteli häntä, kääntyi ja sanoi kansalle, joka häntä seurasi: \"Minä sanon teille: en ole Israelissakaan löytänyt näin suurta uskoa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 10, 'Ja taloon palatessaan lähettiläät tapasivat palvelijan terveenä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 11, 'Sen jälkeen hän vaelsi Nain nimiseen kaupunkiin, ja hänen kanssaan vaelsivat hänen opetuslapsensa ynnä suuri kansanjoukko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 12, 'Kun hän nyt lähestyi kaupungin porttia, katso, silloin kannettiin ulos kuollutta, äitinsä ainokaista poikaa. Ja äiti oli leski, ja hänen kanssaan kulki paljon kaupungin kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 13, 'Ja hänet nähdessään Herra armahti häntä ja sanoi hänelle: \"Älä itke\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 14, 'Ja hän meni ja kosketti paareja; niin kantajat seisahtuivat. Ja hän sanoi: \"Nuorukainen, minä sanon sinulle: nouse.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 15, 'Niin kuollut nousi istualleen ja rupesi puhumaan. Ja hän antoi hänet hänen äidillensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 16, 'Ja heidät kaikki valtasi pelko, ja he ylistivät Jumalaa sanoen: \"Suuri profeetta on noussut meidän keskellemme\", ja: \"Jumala on katsonut kansansa puoleen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 17, 'Ja tämä puhe hänestä levisi koko Juudeaan ja kaikkiin ympärillä oleviin seutuihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 18, 'Ja Johannekselle kertoivat hänen opetuslapsensa tästä kaikesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 19, 'Niin Johannes kutsui luoksensa opetuslapsistaan kaksi ja lähetti heidät Herran tykö kysymään: \"Oletko sinä se tuleva, vai pitääkö meidän toista odottaman?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 20, 'Miehet saapuivat hänen tykönsä ja sanoivat: \"Johannes Kastaja on lähettänyt meidät sinun tykösi ja kysyy: \'Oletko sinä se tuleva, vai pitääkö meidän toista odottaman?\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 21, 'Sillä hetkellä hän juuri paransi useita taudeista ja vitsauksista ja pahoista hengistä, ja monelle sokealle hän antoi näön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 22, 'Niin hän vastasi ja sanoi heille: \"Menkää ja kertokaa Johannekselle, mitä olette nähneet ja kuulleet: sokeat saavat näkönsä, rammat kävelevät, pitaliset puhdistuvat, kuurot kuulevat, kuolleet herätetään, köyhille julistetaan evankeliumia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 23, 'Ja autuas on se, joka ei loukkaannu minuun.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 24, 'Kun Johanneksen lähettiläät olivat menneet, rupesi hän puhumaan kansalle Johanneksesta: \"Mitä te lähditte erämaahan katselemaan? Ruokoako, jota tuuli huojuttaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 25, 'Vai mitä lähditte katsomaan? Ihmistäkö, hienoihin vaatteisiin puettua? Katso, ne jotka koreissa vaatteissa käyvät ja herkullisesti elävät, ne ovat kuningasten linnoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 26, 'Vai mitä lähditte katsomaan? Profeettaako? Totisesti, minä sanon teille: hän on enemmän kuin profeetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 27, 'Tämä on se, josta on kirjoitettu: \'Katso, minä lähetän enkelini sinun edelläsi, ja hän on valmistava tiesi sinun eteesi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 28, 'Minä sanon teille: ei ole vaimoista syntyneitten joukossa yhtäkään suurempaa kuin Johannes; mutta vähäisin Jumalan valtakunnassa on suurempi kuin hän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 29, 'Ja kaikki kansa, joka häntä kuuli, publikaanitkin, tunnustivat Jumalan vanhurskaaksi ja antoivat kastaa itsensä Johanneksen kasteella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 30, 'Mutta fariseukset ja lainoppineet tekivät turhaksi Jumalan aivoituksen heitä kohtaan eivätkä ottaneet Johannekselta kastetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 31, 'Mihin minä siis vertaan tämän sukupolven ihmiset, ja kenen kaltaisia he ovat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 32, 'He ovat lasten kaltaisia, jotka istuvat torilla ja huutavat toisilleen ja sanovat: \'Me soitimme teille huilua, ja te ette karkeloineet; me veisasimme itkuvirsiä, ja te ette itkeneet\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 33, 'Sillä Johannes Kastaja on tullut, ei syö leipää eikä juo viiniä, ja te sanotte: \'Hänessä on riivaaja\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 34, 'Ihmisen Poika on tullut, syö ja juo, ja te sanotte: \'Katso syömäriä ja viininjuojaa, publikaanien ja syntisten ystävää!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 35, 'Ja viisaus on kaikkien lastensa puolelta oikeaksi näytetty.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 36, 'Niin eräs fariseuksista pyysi häntä ruualle kanssaan; ja hän meni fariseuksen taloon ja asettui aterialle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 37, 'Ja katso, siinä kaupungissa oli nainen, joka eli syntisesti; ja kun hän sai tietää, että Jeesus oli aterialla fariseuksen talossa, toi hän alabasteripullon täynnä hajuvoidetta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 38, 'ja asettui hänen taakseen hänen jalkojensa kohdalle, itki ja rupesi kastelemaan hänen jalkojansa kyynelillään ja kuivasi ne päänsä hiuksilla ja suuteli hänen jalkojaan ja voiteli ne hajuvoiteella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 39, 'Mutta kun fariseus, joka oli hänet kutsunut, sen näki, ajatteli hän mielessään näin: \"Jos tämä olisi profeetta, tietäisi hän, mikä ja millainen tuo nainen on, joka häneen koskee: että hän on syntinen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 40, 'Niin Jeesus vastasi ja sanoi hänelle: \"Simon, minulla on jotakin sanomista sinulle\". Hän virkkoi: \"Opettaja, sano\". -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 41, '\"Lainanantajalla oli kaksi velallista; toinen oli velkaa viisisataa denaria, toinen viisikymmentä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 42, 'Kun heillä ei ollut, millä maksaa, antoi hän molemmille velan anteeksi. Kumpi heistä siis rakastaa häntä enemmän?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 43, 'Simon vastasi ja sanoi: \"Minun mielestäni se, jolle hän antoi enemmän anteeksi\". Hän sanoi hänelle: \"Oikein sinä ratkaisit\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 44, 'Ja naiseen kääntyen hän sanoi Simonille: \"Näetkö tämän naisen? Minä tulin sinun taloosi; et sinä antanut vettä minun jaloilleni, mutta tämä kasteli kyynelillään minun jalkani ja kuivasi ne hiuksillaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 45, 'Et sinä antanut minulle suudelmaa, mutta tämä ei ole lakannut suutelemasta minun jalkojani siitä asti, kuin tulin sisään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 46, 'Et sinä voidellut öljyllä minun päätäni, mutta tämä voiteli hajuvoiteella minun jalkani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 47, 'Sentähden minä sanon sinulle: tämän paljot synnit ovat anteeksi annetut: hänhän näet rakasti paljon; mutta jolle vähän anteeksi annetaan, se rakastaa vähän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 48, 'Sitten hän sanoi naiselle: \"Sinun syntisi ovat anteeksi annetut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 49, 'Niin ateriakumppanit rupesivat ajattelemaan mielessänsä: \"Kuka tämä on, joka synnitkin anteeksi antaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 7, 50, 'Mutta hän sanoi naiselle: \"Sinun uskosi on sinut pelastanut; mene rauhaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 1, 'Ja sen jälkeen hän vaelsi kaupungista kaupunkiin ja kylästä kylään ja saarnasi ja julisti Jumalan valtakunnan evankeliumia; ja ne kaksitoista olivat hänen kanssansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 2, 'niin myös muutamia naisia, jotka olivat parannetut pahoista hengistä ja taudeista: Maria, Magdaleenaksi kutsuttu, josta seitsemän riivaajaa oli lähtenyt ulos,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 3, 'ja Johanna, Herodeksen taloudenhoitajan Kuusaan vaimo, ja Susanna ja useita muita, jotka palvelivat heitä varoillansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 4, 'Kun paljon kansaa kokoontui ja ihmisiä kulki joka kaupungista hänen tykönsä, puhui hän vertauksella:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 5, '\"Kylväjä meni kylvämään siementänsä. Ja hänen kylväessään putosi osa tien oheen ja tallautui, ja taivaan linnut söivät sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 6, 'Ja osa putosi kalliolle, ja oraalle noustuaan se kuivettui, kun sillä ei ollut kosteutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 7, 'Ja osa putosi orjantappurain sekaan, ja orjantappurat kasvoivat mukana ja tukahuttivat sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 8, 'Ja osa putosi hyvään maahan, kasvoi ja teki satakertaisen hedelmän.\" Tämän sanottuaan hän lausui suurella äänellä: \"Jolla on korvat kuulla, se kuulkoon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 9, 'Niin hänen opetuslapsensa kysyivät häneltä, mitä tämä vertaus merkitsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 10, 'Hän sanoi: \"Teidän on annettu tuntea Jumalan valtakunnan salaisuudet, mutta muille ne esitetään vertauksissa, että he, vaikka näkevät, eivät näkisi, ja vaikka kuulevat, eivät ymmärtäisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 11, 'Vertaus on tämä: siemen on Jumalan sana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 12, 'Mitkä tien oheen putosivat, ovat ne, jotka kuulevat, mutta sitten perkele tulee ja ottaa sanan pois heidän sydämestään, etteivät he uskoisi ja pelastuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 13, 'Ja mitkä kalliolle putosivat, ovat ne, jotka kuullessaan sanan ottavat sen ilolla vastaan, mutta joilla ei ole juurta: ainoastaan ajaksi he uskovat ja kiusauksen hetkellä luopuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 14, 'Mikä taas orjantappuroihin putosi, ne ovat ne, jotka kuulevat, mutta vaeltaessaan tukehtuvat tämän elämän huoliin, rikkauteen ja hekumoihin, eivätkä tuota kypsää hedelmää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 15, 'Mutta mikä hyvään maahan putosi, ne ovat ne, jotka sanan kuultuansa säilyttävät sen vilpittömässä ja hyvässä sydämessä ja tuottavat hedelmän kärsivällisyydessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 16, 'Ei kukaan joka sytyttää lampun, peitä sitä astialla tai pane vuoteen alle, vaan panee sen lampunjalkaan, että sisälletulijat näkisivät valon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 17, 'Sillä ei ole mitään salattua, mikä ei tule ilmi, eikä kätkettyä, mikä ei tule tunnetuksi ja joudu päivän valoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 18, 'Katsokaa siis, miten kuulette; sillä sille, jolla on, annetaan, mutta siltä, jolla ei ole, otetaan pois sekin, minkä hän luulee itsellään olevan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 19, 'Ja hänen äitinsä ja veljensä tulivat häntä tapaamaan, mutta eivät väentungokselta päässeet hänen tykönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 20, 'Niin hänelle ilmoitettiin: \"Sinun äitisi ja veljesi seisovat ulkona ja tahtovat nähdä sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 21, 'Mutta hän vastasi ja sanoi heille: \"Minun äitini ja veljeni ovat nämä, jotka kuulevat Jumalan sanan ja sen mukaan tekevät\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 22, 'Niin tapahtui eräänä päivänä, että hän astui opetuslapsinensa venheeseen ja sanoi heille: \"Menkäämme järven tuolle puolen\". Ja he lähtivät vesille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 23, 'Ja heidän purjehtiessaan hän nukkui. Mutta alas järvelle syöksyi myrskytuuli, ja venhe tuli vettä täyteen, ja he olivat vaarassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 24, 'Niin he menivät ja herättivät hänet sanoen: \"Mestari, mestari, me hukumme!\" Ja herättyään hän nuhteli tuulta ja veden aallokkoa; ja ne asettuivat, ja tuli tyven.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 25, 'Ja hän sanoi heille: \"Missä on teidän uskonne?\" Mutta pelko oli vallannut heidät, ja he ihmettelivät, sanoen toisilleen: \"Kuka onkaan tämä, kun hän käskee sekä tuulia että vettä, ja ne tottelevat häntä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 26, 'Ja he purjehtivat gerasalaisten alueelle, joka on vastapäätä Galileaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 27, 'Ja kun hän oli noussut maihin, tuli häntä vastaan kaupungista mies, jossa oli riivaajia; ja hän ei ollut pitkään aikaan pukenut vaatteita ylleen eikä asunut huoneessa, vaan haudoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 28, 'Kun hän näki Jeesuksen, parkaisi hän ja lankesi maahan hänen eteensä ja huusi suurella äänellä: \"Mitä sinulla on minun kanssani tekemistä, Jeesus, Jumalan, Korkeimman, Poika? Minä rukoilen sinua: älä minua vaivaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 29, 'Sillä hän oli käskemäisillään saastaista henkeä menemään ulos siitä miehestä. Sillä pitkät ajat se oli temponut häntä mukaansa; hänet oli sidottu kahleisiin ja jalkanuoriin, ja häntä oli vartioitu, mutta hän oli katkaissut siteet ja kulkeutunut riivaajan ajamana erämaihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 30, 'Niin Jeesus kysyi siltä sanoen: \"Mikä on nimesi?\" Hän vastasi: \"Legio\"; sillä monta riivaajaa oli mennyt häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 31, 'Ja ne pyysivät häntä, ettei hän käskisi heidän mennä syvyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 32, 'Niin siellä oli vuorella suuri sikalauma laitumella; ja ne pyysivät häntä, että hän antaisi heille luvan mennä sikoihin. Ja hän antoi niille luvan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 33, 'Niin riivaajat lähtivät ulos miehestä ja menivät sikoihin. Silloin lauma syöksyi jyrkännettä alas järveen ja hukkui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 34, 'Mutta nähtyään, mitä oli tapahtunut, paimentajat pakenivat ja kertoivat siitä kaupungissa ja maataloissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 35, 'Niin kansa lähti katsomaan, mitä oli tapahtunut, ja he tulivat Jeesuksen luo ja tapasivat miehen, josta riivaajat olivat lähteneet, istumassa Jeesuksen jalkojen juuressa puettuna ja täydessä ymmärryksessä; ja he peljästyivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 36, 'Mutta silminnäkijät kertoivat heille, kuinka riivattu oli tullut terveeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 37, 'Ja koko gerasalaisten seutukunnan kansa pyysi häntä poistumaan heidän luotansa, sillä suuri pelko oli vallannut heidät; niin hän astui venheeseen ja palasi takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 38, 'Ja mies, josta riivaajat olivat lähteneet, pyysi häneltä saada olla hänen kanssaan. Mutta Jeesus lähetti hänet luotansa sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 39, '\"Palaja kotiisi ja kerro, kuinka suuria töitä Jumala on sinulle tehnyt\". Ja hän meni ja julisti kaikkialla kaupungissa, kuinka suuria töitä Jeesus oli hänelle tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 40, 'Kun Jeesus palasi, oli kansa häntä vastassa; sillä kaikki odottivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 41, 'Ja katso, silloin tuli mies, nimeltä Jairus, joka oli synagoogan esimies. Ja hän lankesi Jeesuksen jalkojen juureen ja pyysi häntä tulemaan kotiinsa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 42, 'sillä hänellä oli tytär, ainoa lapsi, noin kaksitoistavuotias, ja se oli kuolemaisillaan. Mutta hänen sinne mennessään väentungos ahdisti häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 43, 'Ja siellä oli nainen, joka kaksitoista vuotta oli sairastanut verenjuoksua ja lääkäreille kuluttanut kaiken omaisuutensa, eikä kukaan ollut voinut häntä parantaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 44, 'Tämä lähestyi takaapäin ja kosketti hänen vaippansa tupsua, ja heti hänen verenjuoksunsa asettui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 45, 'Ja Jeesus sanoi: \"Kuka minuun koski?\" Mutta kun kaikki kielsivät, sanoi Pietari ja ne, jotka olivat hänen kanssaan: \"Mestari, väentungos ahdistaa ja pusertaa sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 46, 'Mutta Jeesus sanoi: \"Joku minuun koski; sillä minä tunsin, että voimaa lähti minusta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 47, 'Kun nainen näki, ettei hän pysynyt salassa, tuli hän vavisten, lankesi hänen eteensä ja ilmoitti kaiken kansan kuullen, mistä syystä hän oli koskenut häneen ja kuinka hän oli kohta tullut terveeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 48, 'Niin hän sanoi hänelle: \"Tyttäreni, uskosi on sinut pelastanut; mene rauhaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 49, 'Hänen vielä puhuessaan tuli joku synagoogan esimiehen kotoa ja sanoi: \"Tyttäresi on kuollut; älä enää opettajaa vaivaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 50, 'Mutta sen kuultuaan Jeesus sanoi hänelle: \"Älä pelkää; usko ainoastaan, niin hän paranee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 51, 'Ja kun hän tuli taloon, ei hän sallinut kenenkään muun käydä sisälle kanssaan kuin Pietarin ja Johanneksen ja Jaakobin sekä lapsen isän ja äidin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 52, 'Ja kaikki itkivät ja vaikeroivat tyttöä. Mutta Jeesus sanoi: \"Älkää itkekö, sillä hän ei ole kuollut, vaan nukkuu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 53, 'Niin he nauroivat häntä, tietäen tytön kuolleeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 54, 'Mutta hän tarttui hänen käteensä ja huusi sanoen: \"Lapsi, nouse!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 55, 'Niin hänen henkensä palasi, ja hän nousi heti ylös; ja Jeesus käski antaa hänelle syötävää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 8, 56, 'Ja hänen vanhempansa hämmästyivät; mutta Jeesus kielsi heitä kenellekään sanomasta, mitä oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 1, 'Niin hän kutsui kokoon ne kaksitoista ja antoi heille voiman ja vallan kaikkia riivaajia vastaan ja voiman parantaa tauteja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 2, 'Ja hän lähetti heidät julistamaan Jumalan valtakuntaa ja parantamaan sairaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 3, 'Ja hän sanoi heille: \"Älkää ottako mitään matkalle, ei sauvaa, ei laukkua, ei leipää, ei rahaa, älköön myös kenelläkään olko kahta ihokasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 4, 'Ja mihin taloon tulette, siihen jääkää, ja siitä lähtekää matkallenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 5, 'Ja missä eivät ota teitä vastaan, siitä kaupungista lähtekää pois, ja pudistakaa tomu jaloistanne, todistukseksi heitä vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 6, 'Niin he lähtivät ja kulkivat kylästä kylään julistaen evankeliumia ja parantaen sairaita kaikkialla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 7, 'Ja neljännysruhtinas Herodes sai kuulla kaikki, mitä tapahtui, eikä tiennyt, mitä ajatella; sillä muutamat sanoivat: \"Johannes on noussut kuolleista\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 8, 'mutta toiset: \"Elias on ilmestynyt\", toiset taas: \"Joku vanhoista profeetoista on noussut ylös\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 9, 'Ja Herodes sanoi: \"Johanneksen minä olen mestauttanut; mutta kuka tämä on, josta minä tuollaista kuulen?\" Ja hän etsi tilaisuutta saadakseen nähdä hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 10, 'Ja apostolit palasivat ja kertoivat Jeesukselle kaikki, mitä olivat tehneet. Niin hän otti heidät mukaansa ja vetäytyi yksinäisyyteen lähelle Beetsaida nimistä kaupunkia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 11, 'Mutta kun kansa sai sen tietää, seurasivat he häntä; ja hän otti heidät vastaan ja puhui heille Jumalan valtakunnasta ja teki terveiksi ne, jotka parantamista tarvitsivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 12, 'Ja päivä alkoi laskea. Niin ne kaksitoista tulivat ja sanoivat hänelle: \"Laske kansa luotasi, että he menisivät ympärillä oleviin kyliin ja maataloihin majoittumaan ja saamaan ravintoa, sillä täällä me olemme autiossa paikassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 13, 'Mutta hän sanoi heille: \"Antakaa te heille syödä\". Niin he sanoivat: \"Meillä ei ole enempää kuin viisi leipää ja kaksi kalaa, ellemme lähde ostamaan ruokaa kaikelle tälle kansalle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 14, 'Sillä heitä oli noin viisituhatta miestä. Niin hän sanoi opetuslapsilleen: \"Asettakaa heidät aterioimaan ruokakunnittain, noin viisikymmentä kuhunkin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 15, 'Ja he tekivät niin ja asettivat kaikki aterioimaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 16, 'Niin hän otti ne viisi leipää ja kaksi kalaa, katsoi ylös taivaaseen ja siunasi ne ja mursi ja antoi opetuslapsilleen kansan eteen pantaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 17, 'Ja kaikki söivät ja tulivat ravituiksi; ja heiltä jääneet tähteet kerättiin, kaksitoista vakallista palasia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 18, 'Ja tapahtui, kun hän oli yksinäisessä paikassa rukoilemassa ja hänen opetuslapsensa olivat hänen kanssaan, että hän kysyi heiltä ja sanoi: \"Kenen kansa sanoo minun olevan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 19, 'He vastasivat sanoen: \"Johannes Kastajan, mutta toiset Eliaan, toiset taas sanovat, että joku vanhoista profeetoista on noussut ylös\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 20, 'Niin hän sanoi heille: \"Kenenkä te sanotte minun olevan?\" Pietari vastasi ja sanoi: \"Sinä olet Jumalan Kristus\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 21, 'Niin hän vakavasti varoittaen kielsi heitä kenellekään tästä puhumasta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 22, 'ja sanoi: \"Ihmisen Pojan pitää kärsimän paljon ja joutuman vanhinten ja ylipappien ja kirjanoppineiden hyljittäväksi ja tuleman tapetuksi ja kolmantena päivänä nouseman ylös\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 23, 'Ja hän sanoi kaikille: \"Jos joku tahtoo minun perässäni kulkea, hän kieltäköön itsensä ja ottakoon joka päivä ristinsä ja seuratkoon minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 24, 'Sillä joka tahtoo pelastaa elämänsä, hän kadottaa sen, mutta joka kadottaa elämänsä minun tähteni, hän pelastaa sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 25, 'Sillä mitä se hyödyttää ihmistä, vaikka hän voittaisi omaksensa koko maailman, mutta saattaisi itsensä kadotukseen tai turmioon?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 26, 'Sillä joka häpeää minua ja minun sanojani, sitä Ihmisen Poika on häpeävä, kun hän tulee omassa ja Isänsä ja pyhäin enkelien kirkkaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 27, 'Totisesti minä sanon teille: tässä seisovien joukossa on muutamia, jotka eivät maista kuolemaa, ennenkuin näkevät Jumalan valtakunnan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 28, 'Noin kahdeksan päivää sen jälkeen kuin hän oli tämän puhunut, hän otti mukaansa Pietarin ja Johanneksen ja Jaakobin ja nousi vuorelle rukoilemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 29, 'Ja hänen rukoillessaan hänen kasvojensa näkö muuttui, ja hänen vaatteensa tulivat säteilevän valkoisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 30, 'Ja katso, hänen kanssaan puhui kaksi miestä, ja ne olivat Mooses ja Elias.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 31, 'He näkyivät kirkkaudessa ja puhuivat hänen poismenostansa, jonka hän oli saattava täytäntöön Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 32, 'Mutta Pietari ja ne, jotka olivat hänen kanssansa, olivat unen raskauttamia; mutta kun he siitä heräsivät, näkivät he hänen kirkkautensa ja ne kaksi miestä, jotka seisoivat hänen luonansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 33, 'Ja kun nämä olivat eroamassa hänestä, sanoi Pietari Jeesukselle: \"Mestari, meidän on tässä hyvä olla; tehkäämme kolme majaa, sinulle yksi ja Moosekselle yksi ja Elialle yksi\". Mutta hän ei tiennyt, mitä sanoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 34, 'Ja hänen tätä sanoessaan tuli pilvi ja peitti heidät varjoonsa; ja he peljästyivät joutuessaan pilveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 35, 'Ja pilvestä kuului ääni, joka sanoi: \"Tämä on minun Poikani, se valittu; kuulkaa häntä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 36, 'Ja äänen kuuluessa he huomasivat Jeesuksen olevan yksin. Ja he olivat siitä vaiti eivätkä niinä päivinä ilmoittaneet kenellekään mitään siitä, mitä olivat nähneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 37, 'Kun he seuraavana päivänä menivät alas vuorelta, tuli paljon kansaa häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 38, 'Ja katso, kansanjoukosta huusi eräs mies sanoen: \"Opettaja, minä rukoilen sinua, katsahda minun poikani puoleen, sillä hän on minun ainokaiseni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 39, 'ja katso, hänen kimppuunsa käy henki, ja heti hän parkaisee, ja se kouristaa häntä, niin että vaahto lähtee; ja vaivoin se hänestä poistuu, runnellen häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 40, 'Ja minä pyysin sinun opetuslapsiasi ajamaan sitä ulos, mutta he eivät voineet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 41, 'Jeesus vastasi ja sanoi: \"Voi, sinä epäuskoinen ja nurja sukupolvi; kuinka kauan minun täytyy olla teidän luonanne ja kärsiä teitä? Tuo poikasi tänne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 42, 'Ja vielä pojan tullessakin riivaaja repi häntä ja kouristi kovin. Mutta Jeesus nuhteli saastaista henkeä ja paransi pojan ja antoi hänet takaisin hänen isällensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 43, 'Ja kaikki hämmästyivät Jumalan valtasuuruutta. Mutta kun kaikki ihmettelivät kaikkea sitä, mitä Jeesus teki, sanoi hän opetuslapsillensa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 44, '\"Ottakaa korviinne nämä sanat: Ihmisen Poika annetaan ihmisten käsiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 45, 'Mutta he eivät käsittäneet tätä puhetta, ja se oli heiltä peitetty, niin etteivät he sitä ymmärtäneet, ja he pelkäsivät kysyä häneltä, mitä se puhe oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 46, 'Ja heidän mieleensä tuli ajatus, kuka heistä mahtoi olla suurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 47, 'Mutta kun Jeesus tiesi heidän sydämensä ajatuksen, otti hän lapsen ja asetti sen viereensä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 48, 'ja sanoi heille: \"Joka ottaa tykönsä tämän lapsen minun nimeeni, se ottaa tykönsä minut; ja joka ottaa tykönsä minut, ottaa tykönsä hänet, joka on minut lähettänyt. Sillä joka teistä kaikista on pienin, se on suuri.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 49, 'Silloin Johannes rupesi puhumaan ja sanoi: \"Mestari, me näimme erään miehen sinun nimessäsi ajavan ulos riivaajia, ja me kielsimme häntä, koska hän ei seuraa meidän mukanamme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 50, 'Mutta Jeesus sanoi hänelle: \"Älkää kieltäkö; sillä joka ei ole teitä vastaan, se on teidän puolellanne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 51, 'Ja kun hänen ylösottamisensa aika oli täyttymässä, käänsi hän kasvonsa Jerusalemia kohti, vaeltaaksensa sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 52, 'Ja hän lähetti edellänsä sanansaattajia; ja he lähtivät matkalle ja menivät erääseen samarialaisten kylään valmistaakseen hänelle majaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 53, 'Mutta siellä ei otettu häntä vastaan, koska hän oli vaeltamassa kohti Jerusalemia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 54, 'Kun hänen opetuslapsensa Jaakob ja Johannes sen näkivät, sanoivat he: \"Herra, tahdotko, niin sanomme, että tuli taivaasta tulkoon alas ja hävittäköön heidät?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 55, 'Mutta hän kääntyi ja nuhteli heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 56, 'Ja he vaelsivat toiseen kylään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 57, 'Ja heidän tietä vaeltaessaan eräs mies sanoi hänelle: \"Minä seuraan sinua, mihin ikinä menet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 58, 'Niin Jeesus sanoi hänelle: \"Ketuilla on luolat ja taivaan linnuilla pesät, mutta Ihmisen Pojalla ei ole, mihin hän päänsä kallistaisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 59, 'Toiselle hän sanoi: \"Seuraa minua\". Mutta tämä sanoi: \"Herra, salli minun ensin käydä hautaamassa isäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 60, 'Mutta Jeesus sanoi hänelle: \"Anna kuolleitten haudata kuolleensa, mutta mene sinä ja julista Jumalan valtakuntaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 61, 'Vielä eräs toinen sanoi: \"Minä tahdon seurata sinua, Herra; mutta salli minun ensin käydä ottamassa jäähyväiset kotiväeltäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 9, 62, 'Mutta Jeesus sanoi hänelle: \"Ei kukaan, joka laskee kätensä auraan ja katsoo taaksensa, ole sovelias Jumalan valtakuntaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 1, 'Sen jälkeen Herra valitsi seitsemänkymmentä muuta ja lähetti heidät kaksittain edellänsä jokaiseen kaupunkiin ja paikkaan, jonne hän itse aikoi mennä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 2, 'Ja hän sanoi heille: \"Eloa on paljon, mutta työmiehiä vähän. Rukoilkaa siis elon Herraa, että hän lähettäisi työmiehiä elonkorjuuseensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 3, 'Menkää; katso, minä lähetän teidät niinkuin lampaat susien keskelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 4, 'Älkää ottako mukaanne rahakukkaroa, älkää laukkua, älkää kenkiä, älkääkä tervehtikö ketään tiellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 5, 'Kun tulette johonkin taloon, niin sanokaa ensiksi: \'Rauha tälle talolle!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 6, 'Ja jos siellä on rauhan lapsi, niin teidän rauhanne on lepäävä hänen päällänsä; mutta jos ei ole, niin se palajaa teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 7, 'Ja olkaa siinä talossa ja syökää ja juokaa, mitä heillä on tarjota, sillä työmies on palkkansa ansainnut. Älkää siirtykö talosta taloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 8, 'Ja mihin kaupunkiin te tulettekin, missä teidät otetaan vastaan, syökää, mitä eteenne pannaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 9, 'ja parantakaa sairaat siellä ja sanokaa heille: \'Jumalan valtakunta on tullut teitä lähelle\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 10, 'Mutta kun tulette kaupunkiin, jossa teitä ei oteta vastaan, niin menkää sen kaduille ja sanokaa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 11, '\'Tomunkin, joka teidän kaupungistanne on jalkoihimme tarttunut, me pudistamme teille takaisin; mutta se tietäkää, että Jumalan valtakunta on tullut lähelle\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 12, 'Minä sanon teille: Sodoman on oleva sinä päivänä helpompi kuin sen kaupungin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 13, 'Voi sinua, Korasin! Voi sinua, Beetsaida! Sillä jos ne voimalliset teot, jotka teissä ovat tapahtuneet, olisivat tapahtuneet Tyyrossa ja Siidonissa, niin nämä jo aikaa sitten olisivat säkissä ja tuhassa istuen tehneet parannuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 14, 'Mutta Tyyron ja Siidonin on oleva tuomiolla helpompi kuin teidän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 15, 'Ja sinä, Kapernaum, korotetaankohan sinut hamaan taivaaseen? Hamaan tuonelaan on sinun astuttava alas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 16, 'Joka kuulee teitä, se kuulee minua, ja joka hylkää teidät, hylkää minut; mutta joka minut hylkää, hylkää hänet, joka on minut lähettänyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 17, 'Niin ne seitsemänkymmentä palasivat iloiten ja sanoivat: \"Herra, riivaajatkin ovat meille alamaiset sinun nimesi tähden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 18, 'Silloin hän sanoi heille: \"Minä näin saatanan lankeavan taivaasta niinkuin salaman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 19, 'Katso, minä olen antanut teille vallan tallata käärmeitä ja skorpioneja ja kaikkea vihollisen voimaa, eikä mikään ole teitä vahingoittava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 20, 'Älkää kuitenkaan siitä iloitko, että henget ovat teille alamaiset, vaan iloitkaa siitä, että teidän nimenne ovat kirjoitettuina taivaissa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 21, 'Sillä hetkellä hän riemuitsi Pyhässä Hengessä ja sanoi: \"Minä ylistän sinua, Isä, taivaan ja maan Herra, että olet salannut nämä viisailta ja ymmärtäväisiltä ja ilmoittanut ne lapsenmielisille. Niin, Isä, sillä näin on sinulle hyväksi näkynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 22, 'Kaikki on minun Isäni antanut minun haltuuni, eikä kukaan muu tunne, kuka Poika on, kuin Isä; eikä kukaan muu tunne, kuka Isä on, kuin Poika ja se, kenelle Poika tahtoo hänet ilmoittaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 23, 'Ja hän kääntyi opetuslapsiinsa erikseen ja sanoi: \"Autuaat ovat ne silmät, jotka näkevät, mitä te näette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 24, 'Sillä minä sanon teille: monet profeetat ja kuninkaat ovat tahtoneet nähdä, mitä te näette, eivätkä ole nähneet, ja kuulla, mitä te kuulette, eivätkä ole kuulleet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 25, 'Ja katso, eräs lainoppinut nousi ja kysyi kiusaten häntä: \"Opettaja, mitä minun pitää tekemän, että minä iankaikkisen elämän perisin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 26, 'Niin hän sanoi hänelle: \"Mitä laissa on kirjoitettuna? Kuinkas luet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 27, 'Hän vastasi ja sanoi: \"Rakasta Herraa, sinun Jumalaasi, kaikesta sydämestäsi ja kaikesta sielustasi ja kaikesta voimastasi ja kaikesta mielestäsi, ja lähimmäistäsi niinkuin itseäsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 28, 'Hän sanoi hänelle: \"Oikein vastasit; tee se, niin sinä saat elää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 29, 'Mutta hän tahtoi näyttää olevansa vanhurskas ja sanoi Jeesukselle: \"Kuka sitten on minun lähimmäiseni?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 30, 'Jeesus vastasi ja sanoi: \"Eräs mies vaelsi Jerusalemista alas Jerikoon ja joutui ryövärien käsiin, jotka riisuivat hänet alasti ja löivät haavoille ja menivät pois jättäen hänet puolikuolleeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 31, 'Niin vaelsi sattumalta eräs pappi sitä tietä ja näki hänet ja meni ohitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 32, 'Samoin leeviläinenkin: kun hän tuli sille paikalle ja näki hänet, meni hän ohitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 33, 'Mutta kun eräs samarialainen, joka matkusti sitä tietä, tuli hänen kohdalleen ja näki hänet, niin hän armahti häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 34, 'Ja hän meni hänen luokseen ja sitoi hänen haavansa ja vuodatti niihin öljyä ja viiniä, pani hänet juhtansa selkään ja vei hänet majataloon ja hoiti häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 35, 'Ja seuraavana aamuna hän otti esiin kaksi denaria ja antoi majatalon isännälle ja sanoi: \'Hoida häntä, ja mitä sinulta lisää kuluu, sen minä palatessani sinulle maksan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 36, 'Kuka näistä kolmesta sinun mielestäsi osoitti olevansa sen lähimmäinen, joka oli joutunut ryövärien käsiin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 37, 'Hän sanoi: \"Se, joka osoitti hänelle laupeutta\". Niin Jeesus sanoi hänelle: \"Mene ja tee sinä samoin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 38, 'Ja heidän vaeltaessaan hän meni muutamaan kylään. Niin eräs nainen, nimeltä Martta, otti hänet kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 39, 'Ja hänellä oli sisar, Maria niminen, joka asettui istumaan Herran jalkojen juureen ja kuunteli hänen puhettansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 40, 'Mutta Martta puuhasi monissa palvelustoimissa; ja hän tuli ja sanoi: \"Herra, etkö sinä välitä mitään siitä, että sisareni on jättänyt minut yksinäni palvelemaan? Sano siis hänelle, että hän minua auttaisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 41, 'Herra vastasi ja sanoi hänelle: \"Martta, Martta, moninaisista sinä huolehdit ja hätäilet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 10, 42, 'mutta tarpeellisia on vähän, tahi yksi ainoa. Maria on valinnut hyvän osan, jota ei häneltä oteta pois.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 1, 'Ja kun hän oli eräässä paikassa rukoilemassa ja oli lakannut, sanoi eräs hänen opetuslapsistansa hänelle: \"Herra, opeta meitä rukoilemaan, niinkuin Johanneskin opetti opetuslapsiansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 2, 'Niin hän sanoi heille: \"Kun rukoilette, sanokaa: Isä, pyhitetty olkoon sinun nimesi; tulkoon sinun valtakuntasi; (tapahtukoon sinun tahtosi myös maan päällä niinkuin taivaassa;)');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 3, 'anna meille joka päivä meidän jokapäiväinen leipämme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 4, 'ja anna meille meidän syntimme anteeksi, sillä mekin annamme anteeksi jokaiselle velallisellemme; äläkä saata meitä kiusaukseen; (vaan päästä meidät pahasta).\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 5, 'Ja hän sanoi heille: \"Jos jollakin teistä on ystävä ja hän menee hänen luoksensa yösydännä ja sanoo hänelle: \'Ystäväni, lainaa minulle kolme leipää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 6, 'sillä eräs ystäväni on matkallaan tullut minun luokseni, eikä minulla ole, mitä panna hänen eteensä\';');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 7, 'ja toinen sisältä vastaa ja sanoo: \'Älä minua vaivaa; ovi on jo suljettu, ja lapseni ovat minun kanssani vuoteessa; en minä voi nousta antamaan sinulle\' -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 8, 'minä sanon teille: vaikka hän ei nousekaan antamaan hänelle sentähden, että hän on hänen ystävänsä, nousee hän kuitenkin sentähden, että toinen ei hellitä, ja antaa hänelle niin paljon, kuin hän tarvitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 9, 'Niinpä minäkin sanon teille: anokaa, niin teille annetaan; etsikää, niin te löydätte; kolkuttakaa, niin teille avataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 10, 'Sillä jokainen anova saa, ja etsivä löytää, ja kolkuttavalle avataan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 11, 'Ja kuka teistä on se isä, joka poikansa häneltä pyytäessä kalaa antaa hänelle kalan sijasta käärmeen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 12, 'taikka joka hänen pyytäessään munaa antaa hänelle skorpionin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 13, 'Jos siis te, jotka olette pahoja, osaatte antaa lapsillenne hyviä lahjoja, kuinka paljoa ennemmin taivaallinen Isä antaa Pyhän Hengen niille, jotka sitä häneltä anovat!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 14, 'Ja hän ajoi ulos riivaajan, ja se oli mykkä; ja kun riivaaja oli lähtenyt, niin tapahtui, että mykkä mies puhui; ja kansa ihmetteli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 15, 'Mutta muutamat heistä sanoivat: \"Beelsebulin, riivaajain päämiehen, voimalla hän ajaa ulos riivaajia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 16, 'Toiset taas kiusasivat häntä ja pyysivät häneltä merkkiä taivaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 17, 'Mutta hän tiesi heidän ajatuksensa ja sanoi heille: \"Jokainen valtakunta, joka riitautuu itsensä kanssa, joutuu autioksi, ja talo kaatuu talon päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 18, 'Jos nyt saatanakin on riitautunut itsensä kanssa, kuinka hänen valtakuntansa pysyy pystyssä? Tehän sanotte minun Beelsebulin voimalla ajavan ulos riivaajia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 19, 'Mutta jos minä Beelsebulin voimalla ajan ulos riivaajia, kenenkä voimalla sitten teidän lapsenne ajavat niitä ulos? Sentähden he tulevat olemaan teidän tuomarinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 20, 'Mutta jos minä Jumalan sormella ajan ulos riivaajia, niin onhan Jumalan valtakunta tullut teidän tykönne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 21, 'Kun väkevä aseellisena vartioitsee kartanoaan, on hänen omaisuutensa turvassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 22, 'Mutta kun häntä väkevämpi karkaa hänen päällensä ja voittaa hänet, ottaa hän häneltä kaikki aseet, joihin hän luotti, ja jakaa häneltä riistämänsä saaliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 23, 'Joka ei ole minun kanssani, se on minua vastaan, ja joka ei minun kanssani kokoa, se hajottaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 24, 'Kun saastainen henki lähtee ihmisestä, kuljeksii se autioita paikkoja ja etsii lepoa; ja kun ei löydä, sanoo se: \'Minä palaan huoneeseeni, josta lähdin\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 25, 'Ja kun se tulee, tapaa se sen lakaistuna ja kaunistettuna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 26, 'Silloin se menee ja ottaa mukaansa seitsemän muuta henkeä, pahempaa kuin se itse, ja ne tulevat sisään ja asuvat siellä. Ja sen ihmisen viimeiset tulevat pahemmiksi kuin ensimmäiset.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 27, 'Niin hänen tätä puhuessaan eräs nainen kansanjoukosta korotti äänensä ja sanoi hänelle: \"Autuas on se kohtu, joka on kantanut sinut, ja ne rinnat, joita olet imenyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 28, 'Mutta hän sanoi: \"Niin, autuaat ovat ne, jotka kuulevat Jumalan sanan ja sitä noudattavat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 29, 'Kun kansaa yhä kokoontui, rupesi hän puhumaan: \"Tämä sukupolvi on paha sukupolvi: se tavoittelee merkkiä, mutta sille ei anneta muuta merkkiä kuin Joonaan merkki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 30, 'Sillä niinkuin Joonas tuli niiniveläisille merkiksi, niin Ihmisen Poikakin on oleva merkkinä tälle sukupolvelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 31, 'Etelän kuningatar on heräjävä tuomiolle yhdessä tämän sukupolven miesten kanssa ja tuleva heille tuomioksi; sillä hän tuli maan ääristä kuulemaan Salomon viisautta, ja katso, tässä on enempi kuin Salomo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 32, 'Niiniven miehet nousevat tuomiolle yhdessä tämän sukupolven kanssa ja tulevat sille tuomioksi; sillä he tekivät parannuksen Joonaan saarnan vaikutuksesta, ja katso, tässä on enempi kuin Joonas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 33, 'Ei kukaan, joka sytyttää lampun, pane sitä kätköön eikä vakan alle, vaan panee sen lampunjalkaan, että sisälletulijat näkisivät valon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 34, 'Sinun silmäsi on ruumiin lamppu. Kun silmäsi on terve, on koko sinun ruumiisi valaistu, mutta kun se on viallinen, on myös sinun ruumiisi pimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 35, 'Katso siis, ettei valo, joka sinussa on, ole pimeyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 36, 'Jos siis koko sinun ruumiisi on valoisa eikä miltään osaltaan pimeä, on se oleva kokonaan valoisa, niinkuin lampun valaistessa sinua kirkkaalla loisteellaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 37, 'Hänen näin puhuessaan pyysi eräs fariseus häntä luoksensa aterioimaan; niin hän meni sinne ja asettui aterialle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 38, 'Mutta kun fariseus näki, ettei hän peseytynyt ennen ateriaa, ihmetteli hän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 39, 'Silloin Herra sanoi hänelle: \"Kyllä te, fariseukset, puhdistatte maljan ja vadin ulkopuolen, mutta sisäpuoli teissä on täynnä ryöstöä ja pahuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 40, 'Te mielettömät, eikö se, joka on tehnyt ulkopuolen, ole tehnyt sisäpuoltakin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 41, 'Mutta antakaa almuksi se, mikä sisällä on; katso, silloin kaikki on teille puhdasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 42, 'Mutta voi teitä, te fariseukset, kun te annatte kymmenykset mintuista ja ruuduista ja kaikenlaisista vihanneksista, mutta sivuutatte oikeuden ja Jumalan rakkauden! Näitä olisi tullut noudattaa eikä noitakaan laiminlyödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 43, 'Voi teitä, te fariseukset, kun te rakastatte etumaista istuinta synagoogissa ja tervehdyksiä toreilla!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 44, 'Voi teitä, kun te olette niinkuin merkittömät haudat, joiden päällitse ihmiset kävelevät niistä tietämättä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 45, 'Silloin eräs lainoppineista rupesi puhumaan ja sanoi hänelle: \"Opettaja, kun noin puhut, niin sinä häpäiset myös meitä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 46, 'Mutta hän sanoi: \"Voi teitäkin, te lainoppineet, kun te sälytätte ihmisten päälle vaikeasti kannettavia taakkoja ettekä itse sormellannekaan koske niihin taakkoihin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 47, 'Voi teitä, kun te rakennatte profeettain hautakammioita, ja teidän isänne ovat heidät tappaneet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 48, 'Näin te siis olette isäinne tekojen todistajia ja suostutte niihin: sillä he tappoivat profeetat, ja te rakennatte niille hautakammioita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 49, 'Sentähden Jumalan viisaus sanookin: \'Minä lähetän heille profeettoja ja apostoleja, ja muutamat niistä he tappavat ja toisia vainoavat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 50, 'että tältä sukukunnalta vaadittaisiin kaikkien profeettain veri, mikä on vuodatettu maailman perustamisesta asti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 51, 'hamasta Aabelin verestä Sakariaan vereen saakka, hänen, joka surmattiin alttarin ja temppelin välillä\'. Niin, minä sanon teille, se pitää tältä sukukunnalta vaadittaman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 52, 'Voi teitä, te lainoppineet, kun te olette vieneet tiedon avaimen! Itse te ette ole menneet sisälle, ja sisälle meneviä te olette estäneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 53, 'Ja hänen sieltä lähtiessään kirjanoppineet ja fariseukset rupesivat kovasti ahdistamaan häntä ja urkkimaan häneltä moninaisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 11, 54, 'väijyen, miten saisivat hänet hänen sanoistaan ansaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 1, 'Kun sillä välin kansaa oli kokoontunut tuhatmäärin, niin että he polkivat toisiaan, rupesi hän puhumaan opetuslapsillensa: \"Ennen kaikkea kavahtakaa fariseusten hapatusta, se on: ulkokultaisuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 2, 'Ei ole mitään peitettyä, mikä ei tule paljastetuksi, eikä mitään salattua, mikä ei tule tunnetuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 3, 'Sentähden, kaikki, mitä te pimeässä sanotte, joutuu päivänvalossa kuultavaksi, ja mitä korvaan puhutte kammioissa, se katoilta julistetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 4, 'Mutta minä sanon teille, ystävilleni: älkää peljätkö niitä, jotka tappavat ruumiin, eivätkä sen jälkeen voi mitään enempää tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 5, 'Vaan minä osoitan teille, ketä teidän on pelkääminen: peljätkää häntä, jolla on valta tapettuansa syöstä helvettiin. Niin, minä sanon teille, häntä te peljätkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 6, 'Eikö viittä varpusta myydä kahteen ropoon? Eikä Jumala ole yhtäkään niistä unhottanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 7, 'Ovatpa teidän päänne hiuksetkin kaikki luetut. Älkää peljätkö; te olette suurempiarvoiset kuin monta varpusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 8, 'Mutta minä sanon teille: jokaisen, joka tunnustaa minut ihmisten edessä, myös Ihmisen Poika tunnustaa Jumalan enkelien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 9, 'Mutta joka kieltää minut ihmisten edessä, se kielletään Jumalan enkelien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 10, 'Ja jokaiselle, joka sanoo sanan Ihmisen Poikaa vastaan, annetaan anteeksi; mutta sille, joka Pyhää Henkeä pilkkaa, ei anteeksi anneta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 11, 'Mutta kun he vievät teitä synagoogain ja hallitusten ja esivaltojen eteen, älkää huolehtiko siitä, miten tai mitä vastaisitte puolestanne tahi mitä sanoisitte;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 12, 'sillä Pyhä Henki opettaa teille sillä hetkellä, mitä teidän on sanottava.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 13, 'Niin muuan mies kansanjoukosta sanoi hänelle: \"Opettaja, sano minun veljelleni, että hän jakaisi kanssani perinnön\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 14, 'Mutta hän vastasi hänelle: \"Ihminen, kuka on minut asettanut teille tuomariksi tai jakomieheksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 15, 'Ja hän sanoi heille: \"Katsokaa eteenne ja kavahtakaa kaikkea ahneutta, sillä ei ihmisen elämä riipu hänen omaisuudestaan, vaikka sitä ylenpalttisesti olisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 16, 'Ja hän puhui heille vertauksen sanoen: \"Rikkaan miehen maa kasvoi hyvin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 17, 'Niin hän mietti mielessään ja sanoi: \'Mitä minä teen, kun ei minulla ole, mihin viljani kokoaisin?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 18, 'Ja hän sanoi: \'Tämän minä teen: minä revin maahan aittani ja rakennan suuremmat ja kokoan niihin kaiken eloni ja hyvyyteni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 19, 'ja sanon sielulleni: sielu, sinulla on paljon hyvää tallessa moneksi vuodeksi; nauti lepoa, syö, juo ja iloitse\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 20, 'Mutta Jumala sanoi hänelle: \'Sinä mieletön, tänä yönä sinun sielusi vaaditaan sinulta pois; kenelle sitten joutuu se, minkä sinä olet hankkinut?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 21, 'Näin käy sen, joka kokoaa aarteita itselleen, mutta jolla ei ole rikkautta Jumalan tykönä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 22, 'Ja hän sanoi opetuslapsillensa: \"Sentähden minä sanon teille: älkää murehtiko hengestänne, mitä söisitte, älkääkä ruumiistanne, mitä päällenne pukisitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 23, 'Sillä henki on enemmän kuin ruoka, ja ruumis enemmän kuin vaatteet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 24, 'Katselkaa kaarneita: eivät ne kylvä eivätkä leikkaa, eikä niillä ole säilytyshuonetta eikä aittaa; ja Jumala ruokkii ne. Kuinka paljoa suurempiarvoiset te olette kuin linnut!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 25, 'Ja kuka teistä voi murehtimisellaan lisätä ikäänsä kyynäränkään vertaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 26, 'Jos siis ette voi sitäkään, mikä vähintä on, mitä te murehditte muusta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 27, 'Katselkaa kukkia, kuinka ne kasvavat: eivät ne työtä tee eivätkä kehrää. Kuitenkin minä sanon teille: ei Salomo kaikessa loistossansa ollut niin vaatetettu kuin yksi niistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 28, 'Jos siis Jumala näin vaatettaa kedon ruohon, joka tänään kasvaa ja huomenna uuniin heitetään, kuinka paljoa ennemmin teidät, te vähäuskoiset!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 29, 'Älkää siis tekään etsikö, mitä söisitte ja mitä joisitte, älkääkä korkeita tavoitelko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 30, 'Sillä näitä kaikkia maailman pakanakansat tavoittelevat; mutta teidän Isänne kyllä tietää teidän näitä tarvitsevan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 31, 'Vaan etsikää Jumalan valtakuntaa, niin myös nämä teille annetaan sen ohessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 32, 'Älä pelkää, sinä piskuinen lauma; sillä teidän Isänne on nähnyt hyväksi antaa teille valtakunnan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 33, 'Myykää, mitä teillä on, ja antakaa almuja; hankkikaa itsellenne kulumattomat kukkarot, loppumaton aarre taivaisiin, mihin ei varas ulotu ja missä koi ei turmele.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 34, 'Sillä missä teidän aarteenne on, siellä on myös teidän sydämenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 35, 'Olkoot teidän kupeenne vyötetyt ja lamppunne palamassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 36, 'ja olkaa te niiden ihmisten kaltaiset, jotka herraansa odottavat, milloin hän palajaa häistä, että he hänen tullessaan ja kolkuttaessaan heti avaisivat hänelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 37, 'Autuaat ne palvelijat, jotka heidän herransa tullessaan tapaa valvomasta! Totisesti minä sanon teille: hän vyöttäytyy ja asettaa heidät aterioimaan ja menee ja palvelee heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 38, 'Ja jos hän tulee toisella yövartiolla tai kolmannella ja havaitsee heidän näin tekevän, niin autuaat ovat ne palvelijat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 39, 'Mutta se tietäkää: jos perheenisäntä tietäisi, millä hetkellä varas tulee, hän ei sallisi taloonsa murtauduttavan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 40, 'Niin olkaa tekin valmiit, sillä sinä hetkenä, jona ette luule, Ihmisen Poika tulee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 41, 'Niin Pietari sanoi: \"Herra, meistäkö sinä sanot tämän vertauksen vai myös kaikista muista?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 42, 'Ja Herra sanoi: \"Kuka siis on se uskollinen ja ymmärtäväinen huoneenhaltija, jonka hänen herransa asettaa pitämään huolta hänen palvelusväestään, antamaan heille ajallaan heidän ruokaosansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 43, 'Autuas se palvelija, jonka hänen herransa tullessaan havaitsee näin tekevän!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 44, 'Totisesti minä sanon teille: hän asettaa hänet kaiken omaisuutensa hoitajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 45, 'Mutta jos palvelija sanoo sydämessään: \'Herrani tulo viivästyy\', ja rupeaa lyömään palvelijoita ja palvelijattaria sekä syömään ja juomaan ja päihdyttämään itseänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 46, 'niin sen palvelijan herra tulee päivänä, jona hän ei odota, ja hetkenä, jota hän ei arvaa, ja hakkaa hänet kappaleiksi ja määrää hänelle saman osan kuin uskottomille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 47, 'Ja sitä palvelijaa, joka tiesi herransa tahdon, mutta ei tehnyt valmistuksia eikä toiminut hänen tahtonsa mukaan, rangaistaan monilla lyönneillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 48, 'Sitä taas, joka ei tiennyt, mutta teki semmoista, mikä lyöntejä ansaitsee, rangaistaan vain muutamilla lyönneillä. Sillä jokaiselta, jolle on paljon annettu, myös paljon vaaditaan; ja jolle on paljon uskottu, siltä sitä enemmän kysytään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 49, 'Tulta minä olen tullut heittämään maan päälle; ja kuinka minä tahtoisinkaan, että se jo olisi syttynyt!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 50, 'Mutta minä olen kasteella kastettava, ja kuinka minä olenkaan ahdistettu, kunnes se on täytetty!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 51, 'Luuletteko, että minä olen tullut tuomaan maan päälle rauhaa? Ei, sanon minä teille, vaan eripuraisuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 52, 'Sillä tästedes riitautuu viisi samassa talossa keskenään, kolme joutuu riitaan kahta vastaan ja kaksi kolmea vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 53, 'isä poikaansa vastaan ja poika isäänsä vastaan, äiti tytärtänsä vastaan ja tytär äitiänsä vastaan, anoppi miniäänsä vastaan ja miniä anoppiansa vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 54, 'Ja hän sanoi myöskin kansalle: \"Kun näette pilven nousevan lännestä, sanotte kohta: \'Tulee sade\'; ja niin tuleekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 55, 'Ja kun näette etelätuulen puhaltavan, sanotte: \'Tulee helle\'; ja niin tuleekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 56, 'Te ulkokullatut, maan ja taivaan muodon te osaatte arvioida; mutta kuinka ette arvioitse tätä aikaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 57, 'Miksi ette jo itsestänne päätä, mikä oikeata on?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 58, 'Kun kuljet riitapuolesi kanssa hallitusmiehen eteen, niin tee matkalla voitavasi päästäksesi hänestä sovussa eroon, ettei hän raastaisi sinua tuomarin eteen ja tuomari antaisi sinua oikeudenpalvelijalle, ja ettei oikeudenpalvelija heittäisi sinua vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 12, 59, 'Minä sanon sinulle: sieltä et pääse, ennenkuin maksat viimeisenkin rovon.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 1, 'Samaan aikaan oli saapuvilla muutamia, jotka kertoivat hänelle niistä galilealaisista, joiden veren Pilatus oli sekoittanut heidän uhriensa vereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 2, 'Niin Jeesus vastasi ja sanoi heille: \"Luuletteko, että nämä galilealaiset olivat syntisemmät kuin kaikki muut galilealaiset, koska he saivat kärsiä tämän?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 3, 'Eivät olleet, sanon minä teille, mutta ellette tee parannusta, niin samoin te kaikki hukutte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 4, 'Taikka ne kahdeksantoista, jotka saivat surmansa, kun torni Siloassa kaatui heidän päällensä, luuletteko, että he olivat syyllisemmät kuin kaikki muut ihmiset, jotka Jerusalemissa asuvat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 5, 'Eivät olleet, sanon minä teille, mutta ellette tee parannusta, niin samoin te kaikki hukutte.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 6, 'Ja hän puhui tämän vertauksen: \"Eräällä miehellä oli viikunapuu istutettuna viinitarhassaan; ja hän tuli etsimään hedelmää siitä, mutta ei löytänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 7, 'Niin hän sanoi viinitarhurille: \'Katso, kolmena vuotena minä olen käynyt etsimässä hedelmää tästä viikunapuusta, mutta en ole löytänyt. Hakkaa se pois; mitä varten se vielä maata laihduttaa?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 8, 'Mutta tämä vastasi ja sanoi hänelle: \'Herra, anna sen olla vielä tämä vuosi; sillä aikaa minä kuokin ja lannoitan maan sen ympäriltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 9, 'Ehkä se ensi vuonna tekee hedelmää; mutta jos ei, niin hakkaa se pois\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 10, 'Ja hän oli opettamassa eräässä synagoogassa sapattina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 11, 'Ja katso, siellä oli nainen, jossa oli ollut heikkouden henki kahdeksantoista vuotta, ja hän oli koukistunut ja täydelleen kykenemätön oikaisemaan itseänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 12, 'Hänet nähdessään Jeesus kutsui hänet luoksensa ja sanoi hänelle: \"Nainen, sinä olet päässyt heikkoudestasi\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 13, 'ja pani kätensä hänen päälleen. Ja heti hän oikaisi itsensä suoraksi ja ylisti Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 14, 'Mutta synagoogan esimies, joka närkästyi siitä, että Jeesus paransi sapattina, rupesi puhumaan ja sanoi kansalle: \"Kuusi päivää on, joina tulee työtä tehdä; tulkaa siis niinä päivinä parannuttamaan itseänne, älkääkä sapatinpäivänä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 15, 'Mutta Herra vastasi hänelle ja sanoi: \"Te ulkokullatut, eikö jokainen teistä sapattina päästä härkäänsä tai aasiansa seimestä ja vie sitä juomaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 16, 'Ja tätä naista, joka on Aabrahamin tytär ja jota saatana on pitänyt sidottuna, katso, jo kahdeksantoista vuotta, tätäkö ei olisi pitänyt päästää siitä siteestä sapatinpäivänä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 17, 'Ja hänen näin sanoessaan kaikki hänen vastustajansa häpesivät, ja kaikki kansa iloitsi kaikista niistä ihmeellisistä teoista, joita hän teki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 18, 'Niin hän sanoi: \"Minkä kaltainen on Jumalan valtakunta, ja mihin minä sen vertaisin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 19, 'Se on sinapinsiemenen kaltainen, jonka mies otti ja kylvi puutarhaansa; ja se kasvoi, ja siitä tuli puu, ja taivaan linnut tekivät pesänsä sen oksille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 20, 'Ja taas hän sanoi: \"Mihin minä vertaisin Jumalan valtakunnan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 21, 'Se on hapatuksen kaltainen, jonka nainen otti ja sekoitti kolmeen vakalliseen jauhoja, kunnes kaikki happani.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 22, 'Ja hän vaelsi kaupungista kaupunkiin ja kylästä kylään ja opetti, kulkien Jerusalemia kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 23, 'Ja joku kysyi häneltä: \"Herra, onko niitä vähän, jotka pelastuvat? Niin hän sanoi heille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 24, '\"Kilvoitelkaa päästäksenne sisälle ahtaasta ovesta, sillä monet, sanon minä teille, koettavat päästä sisälle, mutta eivät voi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 25, 'Sen jälkeen kuin perheenisäntä on noussut ja sulkenut oven ja te rupeatte seisomaan ulkona ja kolkuttamaan ovea sanoen: \'Herra, avaa meille\', vastaa hän ja sanoo teille: \'En minä tunne teitä enkä tiedä, mistä te olette\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 26, 'Silloin te rupeatte sanomaan: \'Mehän söimme ja joimme sinun seurassasi, ja meidän kaduillamme sinä opetit\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 27, 'Mutta hän on lausuva: \'Minä sanon teille: en tiedä, mistä te olette. Menkää pois minun tyköäni, kaikki te vääryyden tekijät.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 28, 'Siellä on oleva itku ja hammasten kiristys, kun näette Aabrahamin ja Iisakin ja Jaakobin ja kaikkien profeettain olevan Jumalan valtakunnassa, mutta huomaatte itsenne heitetyiksi ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 29, 'Ja tulijoita saapuu idästä ja lännestä ja pohjoisesta ja etelästä, ja he aterioitsevat Jumalan valtakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 30, 'Ja katso, on viimeisiä, jotka tulevat ensimmäisiksi, ja on ensimmäisiä, jotka tulevat viimeisiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 31, 'Samalla hetkellä tuli hänen luoksensa muutamia fariseuksia, ja he sanoivat hänelle: \"Lähde ja mene täältä pois, sillä Herodes tahtoo tappaa sinut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 32, 'Niin hän sanoi heille: \"Menkää ja sanokaa sille ketulle: \'Katso, minä ajan ulos riivaajia ja parannan sairaita tänään ja huomenna, ja kolmantena päivänä minä pääsen määräni päähän\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 33, 'Kuitenkin minun pitää vaeltaman tänään ja huomenna ja ylihuomenna, sillä ei sovi, että profeetta saa surmansa muualla kuin Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 34, 'Jerusalem, Jerusalem, sinä, joka tapat profeetat ja kivität ne, jotka ovat sinun tykösi lähetetyt, kuinka usein minä olenkaan tahtonut koota sinun lapsesi, niinkuin kana kokoaa poikansa siipiensä alle! Mutta te ette ole tahtoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 13, 35, 'Katso, \'teidän huoneenne on jäävä hyljätyksi\'. Mutta minä sanon teille: te ette näe minua, ennenkuin se aika tulee, jolloin te sanotte: \'Siunattu olkoon hän, joka tulee Herran nimeen\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 1, 'Ja kun hän sapattina tuli erään fariseusten johtomiehen taloon aterialle, pitivät he häntä silmällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 2, 'Ja katso, siellä oli vesitautinen mies hänen edessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 3, 'Niin Jeesus rupesi puhumaan lainoppineille ja fariseuksille ja sanoi: \"Onko luvallista parantaa sapattina, vai eikö?\" Mutta he olivat vaiti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 4, 'Ja hän koski mieheen, paransi hänet ja laski menemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 5, 'Ja hän sanoi heille: \"Jos joltakin teistä putoaa poika tai härkä kaivoon, eikö hän heti vedä sitä ylös sapatinpäivänäkin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 6, 'Eivätkä he kyenneet vastaamaan tähän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 7, 'Ja huomatessaan, kuinka kutsutut valitsivat itselleen ensimmäisiä sijoja, hän puhui heille vertauksen ja sanoi heille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 8, '\"Kun joku on kutsunut sinut häihin, älä asetu aterioimaan ensimmäiselle sijalle; sillä, jos hän on kutsunut jonkun sinua arvollisemman,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 9, 'niin hän, joka on sinut ja hänet kutsunut, ehkä tulee ja sanoo sinulle: \'Anna tälle sija\', ja silloin sinä saat häveten siirtyä viimeiselle paikalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 10, 'Vaan kun olet kutsuttu, mene ja asetu viimeiselle sijalle, ja niin on se, joka on sinut kutsunut, sisään tullessaan sanova sinulle: \'Ystäväni, astu ylemmäksi\'. Silloin tulee sinulle kunnia kaikkien pöytäkumppaniesi edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 11, 'Sillä jokainen, joka itsensä ylentää, alennetaan, ja joka itsensä alentaa, se ylennetään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 12, 'Ja hän sanoi myös sille, joka oli hänet kutsunut: \"Kun laitat päivälliset tai illalliset, älä kutsu ystäviäsi, älä veljiäsi, älä sukulaisiasi äläkä rikkaita naapureita, etteivät hekin vuorostaan kutsuisi sinua, ja ettet sinä siten saisi maksua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 13, 'Vaan kun laitat pidot, kutsu köyhiä, raajarikkoja, rampoja, sokeita;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 14, 'niin sinä olet oleva autuas, koska he eivät voi maksaa sinulle; sillä sinulle maksetaan vanhurskasten ylösnousemuksessa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 15, 'Tämän kuullessaan eräs pöytäkumppaneista sanoi hänelle: \"Autuas se, joka saa olla aterialla Jumalan valtakunnassa!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 16, 'Niin hän sanoi hänelle: \"Eräs mies laittoi suuret illalliset ja kutsui monta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 17, 'Ja illallisajan tullessa hän lähetti palvelijansa sanomaan kutsutuille: \'Tulkaa, sillä kaikki on jo valmiina\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 18, 'Mutta he rupesivat kaikki järjestään estelemään. Ensimmäinen sanoi hänelle: \'Minä ostin pellon, ja minun täytyy lähteä sitä katsomaan; pyydän sinua, pidä minut estettynä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 19, 'Toinen sanoi: \'Minä ostin viisi paria härkiä ja menen niitä koettelemaan; pyydän sinua, pidä minut estettynä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 20, 'Vielä toinen sanoi: \'Minä otin vaimon, ja sentähden en voi tulla\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 21, 'Ja palvelija tuli takaisin ja ilmoitti herralleen tämän. Silloin isäntä vihastui ja sanoi palvelijalleen: \'Mene kiiruusti kaupungin kaduille ja kujille ja tuo köyhät ja raajarikot, sokeat ja rammat tänne sisälle\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 22, 'Ja palvelija sanoi: \'Herra, on tehty, minkä käskit, ja vielä on tilaa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 23, 'Niin Herra sanoi palvelijalle: \'Mene teille ja aitovierille ja pakota heitä tulemaan sisälle, että minun taloni täyttyisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 24, 'sillä minä sanon teille, ettei yksikään niistä miehistä, jotka olivat kutsutut, ole maistava minun illallisiani\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 25, 'Ja hänen mukanaan kulki paljon kansaa; ja hän kääntyi ja sanoi heille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 26, '\"Jos joku tulee minun tyköni eikä vihaa isäänsä ja äitiänsä ja vaimoaan ja lapsiaan ja veljiään ja sisariaan, vieläpä omaa elämäänsäkin, hän ei voi olla minun opetuslapseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 27, 'Ja joka ei kanna ristiänsä ja seuraa minua, se ei voi olla minun opetuslapseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 28, 'Sillä jos joku teistä tahtoo rakentaa tornin, eikö hän ensin istu laskemaan kustannuksia, nähdäkseen, onko hänellä varoja rakentaa se valmiiksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 29, 'etteivät, kun hän on pannut perustuksen, mutta ei kykene saamaan rakennusta valmiiksi, kaikki, jotka sen näkevät, rupeaisi pilkkaamaan häntä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 30, 'sanoen: \'Tuo mies ryhtyi rakentamaan, mutta ei kyennyt saamaan valmiiksi\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 31, 'Tahi jos joku kuningas tahtoo lähteä sotimaan toista kuningasta vastaan, eikö hän ensin istu ja pidä neuvoa, kykeneekö hän kymmenellä tuhannella kohtaamaan sitä, joka tulee häntä vastaan kahdellakymmenellä tuhannella?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 32, 'Ja ellei kykene, niin hän, toisen vielä ollessa kaukana, lähettää hänen luoksensa lähettiläät hieromaan rauhaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 33, 'Niin ei myös teistä yksikään, joka ei luovu kaikesta, mitä hänellä on, voi olla minun opetuslapseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 34, 'Suola on hyvä; mutta jos suolakin käy mauttomaksi, millä se saadaan suolaiseksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 14, 35, 'Ei se kelpaa maahan eikä lantaan; se heitetään pois. Jolla on korvat kuulla, se kuulkoon!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 1, 'Ja kaikki publikaanit ja syntiset tulivat hänen tykönsä kuulemaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 2, 'Mutta fariseukset ja kirjanoppineet nurisivat ja sanoivat: \"Tämä ottaa vastaan syntisiä ja syö heidän kanssaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 3, 'Niin hän puhui heille tämän vertauksen sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 4, '\"Jos jollakin teistä on sata lammasta ja hän kadottaa yhden niistä, eikö hän jätä niitä yhdeksääkymmentä yhdeksää erämaahan ja mene etsimään kadonnutta, kunnes hän sen löytää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 5, 'Ja löydettyään hän panee sen hartioillensa iloiten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 6, 'Ja kun hän tulee kotiin, kutsuu hän kokoon ystävänsä ja naapurinsa ja sanoo heille: \'Iloitkaa minun kanssani, sillä minä löysin lampaani, joka oli kadonnut\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 7, 'Minä sanon teille: samoin on ilo taivaassa suurempi yhdestä syntisestä, joka tekee parannuksen, kuin yhdeksästäkymmenestä yhdeksästä vanhurskaasta, jotka eivät parannusta tarvitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 8, 'Tahi jos jollakin naisella on kymmenen hopearahaa ja hän kadottaa yhden niistä, eikö hän sytytä lamppua ja lakaise huonetta ja etsi visusti, kunnes hän sen löytää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 9, 'Ja löydettyään hän kutsuu kokoon ystävättärensä ja naapurinaiset ja sanoo: \'Iloitkaa minun kanssani, sillä minä löysin rahan, jonka olin kadottanut\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 10, 'Niin myös, sanon minä teille, on ilo Jumalan enkeleillä yhdestä syntisestä, joka tekee parannuksen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 11, 'Vielä hän sanoi: \"Eräällä miehellä oli kaksi poikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 12, 'Ja nuorempi heistä sanoi isälleen: \'Isä, anna minulle se osa tavaroista, mikä minulle on tuleva\'. Niin hän jakoi heille omaisuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 13, 'Eikä kulunut montakaan päivää, niin nuorempi poika kokosi kaiken omansa ja matkusti pois kaukaiseen maahan; ja siellä hän hävitti tavaransa eläen irstaasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 14, 'Mutta kun hän oli kaikki tuhlannut, tuli kova nälkä koko siihen maahan, ja hän alkoi kärsiä puutetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 15, 'Ja hän meni ja yhtyi erääseen sen maan kansalaiseen, ja tämä lähetti hänet tiluksilleen kaitsemaan sikoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 16, 'Ja hän halusi täyttää vatsansa niillä palkohedelmillä, joita siat söivät, mutta niitäkään ei kukaan hänelle antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 17, 'Niin hän meni itseensä ja sanoi: \'Kuinka monella minun isäni palkkalaisella on yltäkyllin leipää, mutta minä kuolen täällä nälkään!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 18, 'Minä nousen ja menen isäni tykö ja sanon hänelle: Isä, minä olen tehnyt syntiä taivasta vastaan ja sinun edessäsi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 19, 'enkä enää ansaitse, että minua sinun pojaksesi kutsutaan; tee minut yhdeksi palkkalaisistasi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 20, 'Ja hän nousi ja meni isänsä tykö. Mutta kun hän vielä oli kaukana, näki hänen isänsä hänet ja armahti häntä, juoksi häntä vastaan ja lankesi hänen kaulaansa ja suuteli häntä hellästi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 21, 'Mutta poika sanoi hänelle: \'Isä, minä olen tehnyt syntiä taivasta vastaan ja sinun edessäsi enkä enää ansaitse, että minua sinun pojaksesi kutsutaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 22, 'Silloin isä sanoi palvelijoilleen: \'Tuokaa pian parhaat vaatteet ja pukekaa hänet niihin, ja pankaa sormus hänen sormeensa ja kengät hänen jalkaansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 23, 'ja noutakaa syötetty vasikka ja teurastakaa. Ja syökäämme ja pitäkäämme iloa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 24, 'sillä tämä minun poikani oli kuollut ja virkosi eloon, hän oli kadonnut ja on jälleen löytynyt.\' Ja he rupesivat iloa pitämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 25, 'Mutta hänen vanhempi poikansa oli pellolla. Ja kun hän tuli ja lähestyi kotia, kuuli hän laulun ja karkelon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 26, 'Ja hän kutsui luoksensa yhden palvelijoista ja tiedusteli, mitä se oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 27, 'Tämä sanoi hänelle: \'Sinun veljesi on tullut, ja isäsi teurastutti syötetyn vasikan, kun sai hänet terveenä takaisin\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 28, 'Niin hän vihastui eikä tahtonut mennä sisälle; mutta hänen isänsä tuli ulos ja puhutteli häntä leppeästi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 29, 'Mutta hän vastasi ja sanoi isälleen: \'Katso, niin monta vuotta minä olen sinua palvellut enkä ole milloinkaan sinun käskyäsi laiminlyönyt, ja kuitenkaan et ole minulle koskaan antanut vohlaakaan, pitääkseni iloa ystävieni kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 30, 'Mutta kun tämä sinun poikasi tuli, joka on tuhlannut sinun omaisuutesi porttojen kanssa, niin hänelle sinä teurastit syötetyn vasikan.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 31, 'Niin hän sanoi hänelle: \'Poikani, sinä olet aina minun tykönäni, ja kaikki, mikä on minun omaani, on sinun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 15, 32, 'Mutta pitihän nyt riemuita ja iloita, sillä tämä sinun veljesi oli kuollut ja virkosi eloon, hän oli kadonnut ja on jälleen löytynyt.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 1, 'Ja hän puhui myös opetuslapsilleen: \"Oli rikas mies, jolla oli huoneenhaltija, ja hänelle kanneltiin, että tämä hävitti hänen omaisuuttansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 2, 'Ja hän kutsui hänet eteensä ja sanoi hänelle: \'Mitä minä kuulenkaan sinusta? Tee tili huoneenhallituksestasi; sillä sinä et saa enää minun huonettani hallita.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 3, 'Niin huoneenhaltija sanoi mielessään: \'Mitä minä teen, kun isäntäni ottaa minulta pois huoneenhallituksen? Kaivaa minä en jaksa, kerjuuta häpeän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 4, 'Minä tiedän, mitä teen, että ottaisivat minut taloihinsa, kun minut pannaan pois huoneenhallituksesta.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 5, 'Ja hän kutsui luoksensa jokaisen herransa velallisista ja sanoi ensimmäiselle: \'Paljonko sinä olet velkaa minun herralleni?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 6, 'Tämä sanoi: \'Sata astiaa öljyä\'. Niin hän sanoi hänelle: \'Tässä on velkakirjasi, istu ja kirjoita pian viisikymmentä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 7, 'Sitten hän sanoi toiselle: \'Entä sinä, paljonko sinä olet velkaa?\' Tämä sanoi: \'Sata tynnyriä nisuja\'. Hän sanoi hänelle: \'Tässä on velkakirjasi, kirjoita kahdeksankymmentä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 8, 'Ja herra kehui väärää huoneenhaltijaa siitä, että hän oli menetellyt ovelasti. Sillä tämän maailman lapset ovat omaa sukukuntaansa kohtaan ovelampia kuin valkeuden lapset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 9, 'Ja minä sanon teille: tehkää itsellenne ystäviä väärällä mammonalla, että he, kun se loppuu, ottaisivat teidät iäisiin majoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 10, 'Joka vähimmässä on uskollinen, on paljossakin uskollinen, ja joka vähimmässä on väärä, on paljossakin väärä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 11, 'Jos siis ette ole olleet uskolliset väärässä mammonassa, kuka teille uskoo sitä, mikä oikeata on?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 12, 'Ja jos ette ole olleet uskolliset siinä, mikä on toisen omaa, kuka teille antaa sitä, mikä teidän omaanne on?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 13, 'Ei kukaan palvelija voi palvella kahta herraa; sillä hän on joko tätä vihaava ja toista rakastava, taikka tähän liittyvä ja toista halveksiva. Ette voi palvella Jumalaa ja mammonaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 14, 'Tämän kaiken kuulivat fariseukset, jotka olivat rahanahneita, ja he ivasivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 15, 'Ja hän sanoi heille: \"Te juuri olette ne, jotka teette itsenne vanhurskaiksi ihmisten edessä, mutta Jumala tuntee teidän sydämenne; sillä mikä ihmisten kesken on korkeata, se on Jumalan edessä kauhistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 16, 'Laki ja profeetat olivat Johannekseen asti; siitä lähtien julistetaan Jumalan valtakuntaa, ja jokainen tunkeutuu sinne väkisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 17, 'Mutta ennemmin taivas ja maa katoavat, kuin yksikään lain piirto häviää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 18, 'Jokainen, joka hylkää vaimonsa ja nai toisen, tekee huorin; ja joka nai miehensä hylkäämän, tekee huorin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 19, 'Oli rikas mies, joka pukeutui purppuraan ja hienoihin pellavavaatteisiin ja eli joka päivä ilossa loisteliaasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 20, 'Mutta eräs köyhä, nimeltä Lasarus, makasi hänen ovensa edessä täynnä paiseita');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 21, 'ja halusi ravita itseään niillä muruilla, jotka putosivat rikkaan pöydältä. Ja koiratkin tulivat ja nuolivat hänen paiseitansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 22, 'Niin tapahtui, että köyhä kuoli, ja enkelit veivät hänet Aabrahamin helmaan. Ja rikaskin kuoli, ja hänet haudattiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 23, 'Ja kun hän nosti silmänsä tuonelassa, vaivoissa ollessaan, näki hän kaukana Aabrahamin ja Lasaruksen hänen helmassaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 24, 'Ja hän huusi sanoen: \'Isä Aabraham, armahda minua ja lähetä Lasarus kastamaan sormensa pää veteen ja jäähdyttämään minun kieltäni, sillä minulla on kova tuska tässä liekissä!\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 25, 'Mutta Aabraham sanoi: \'Poikani, muista, että sinä eläessäsi sait hyväsi, ja Lasarus samoin sai pahaa; mutta nyt hän täällä saa lohdutusta, sinä taas kärsit tuskaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 26, 'Ja kaiken tämän lisäksi on meidän välillemme ja teidän vahvistettu suuri juopa, että ne, jotka tahtovat mennä täältä teidän luoksenne, eivät voisi, eivätkä ne, jotka siellä ovat, pääsisi yli meidän luoksemme.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 27, 'Hän sanoi: \'Niin minä siis rukoilen sinua, isä, että lähetät hänet isäni taloon');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 28, '-sillä minulla on viisi veljeä-todistamaan heille, etteivät hekin joutuisi tähän vaivan paikkaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 29, 'Mutta Aabraham sanoi: \'Heillä on Mooses ja profeetat; kuulkoot niitä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 30, 'Niin hän sanoi: \'Ei, isä Aabraham; vaan jos joku kuolleista menisi heidän tykönsä, niin he tekisivät parannuksen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 16, 31, 'Mutta Aabraham sanoi hänelle: \'Jos he eivät kuule Moosesta ja profeettoja, niin eivät he usko, vaikka joku kuolleistakin nousisi ylös\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 1, 'Ja hän sanoi opetuslapsillensa: \"Mahdotonta on, että viettelykset jäisivät tulematta; mutta voi sitä, jonka kautta ne tulevat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 2, 'Hänen olisi parempi, että myllynkivi pantaisiin hänen kaulaansa ja hänet heitettäisiin mereen, kuin että hän viettelee yhden näistä pienistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 3, 'Pitäkää itsestänne vaari! Jos sinun veljesi tekee syntiä, niin nuhtele häntä, ja jos hän katuu, anna hänelle anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 4, 'Ja jos hän seitsemän kertaa päivässä tekee syntiä sinua vastaan ja seitsemän kertaa kääntyy sinun puoleesi ja sanoo: \'Minä kadun\', niin anna hänelle anteeksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 5, 'Ja apostolit sanoivat Herralle: \"Lisää meille uskoa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 6, 'Niin Herra sanoi: \"Jos teillä olisi uskoa sinapinsiemenenkään verran, niin te voisitte sanoa tälle silkkiäispuulle: \'Nouse juurinesi ja istuta itsesi mereen\', ja se tottelisi teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 7, 'Jos jollakin teistä on palvelija kyntämässä tai paimentamassa, sanooko hän tälle tämän tullessa pellolta: \'Käy heti aterialle\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 8, 'Eikö hän pikemminkin sano hänelle: \'Valmista minulle ateria, vyöttäydy ja palvele minua, sillä aikaa kuin minä syön ja juon; ja sitten syö ja juo sinä\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 9, 'Ei kaiketi hän kiitä palvelijaa siitä, että tämä teki, mitä oli käsketty?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 10, 'Niin myös te, kun olette tehneet kaiken, mitä teidän on käsketty tehdä, sanokaa: \'Me olemme ansiottomia palvelijoita; olemme tehneet vain sen, minkä olimme velvolliset tekemään\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 11, 'Ja kun hän oli matkalla Jerusalemiin, kulki hän Samarian ja Galilean välistä rajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 12, 'Ja hänen mennessään erääseen kylään kohtasi häntä kymmenen pitalista miestä, jotka jäivät seisomaan loitommaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 13, 'ja he korottivat äänensä ja sanoivat: \"Jeesus, mestari, armahda meitä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 14, 'Ja heidät nähdessään hän sanoi heille: \"Menkää ja näyttäkää itsenne papeille\". Ja tapahtui heidän mennessään, että he puhdistuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 15, 'Mutta yksi heistä, kun näki olevansa parannettu, palasi takaisin ja ylisti Jumalaa suurella äänellä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 16, 'ja lankesi kasvoilleen hänen jalkojensa juureen ja kiitti häntä; ja se mies oli samarialainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 17, 'Niin Jeesus vastasi ja sanoi: \"Eivätkö kaikki kymmenen puhdistuneet? Missä ne yhdeksän ovat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 18, 'Eikö ollut muita, jotka olisivat palanneet Jumalaa ylistämään, kuin tämä muukalainen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 19, 'Ja hän sanoi hänelle: \"Nouse ja mene; sinun uskosi on sinut pelastanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 20, 'Ja kun fariseukset kysyivät häneltä, milloin Jumalan valtakunta oli tuleva, vastasi hän heille ja sanoi: \"Ei Jumalan valtakunta tule nähtävällä tavalla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 21, 'eikä voida sanoa: \'Katso, täällä se on\', tahi: \'Tuolla\'; sillä katso, Jumalan valtakunta on sisällisesti teissä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 22, 'Ja hän sanoi opetuslapsillensa: \"Tulee aika, jolloin te halajaisitte nähdä edes yhtä Ihmisen Pojan päivää, mutta ette saa nähdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 23, 'Ja teille sanotaan: \'Katso, tuolla hän on!\' \'Katso, täällä!\' Älkää menkö sinne älkääkä juosko perässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 24, 'Sillä niinkuin salaman leimaus loistaa taivaan äärestä taivaan ääreen, niin on Ihmisen Poika päivänänsä oleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 25, 'Mutta sitä ennen pitää hänen kärsimän paljon ja joutuman tämän sukupolven hyljittäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 26, 'Ja niinkuin kävi Nooan päivinä, niin käy myöskin Ihmisen Pojan päivinä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 27, 'he söivät, joivat, naivat ja menivät miehelle, aina siihen päivään asti, jona Nooa meni arkkiin; ja vedenpaisumus tuli ja hukutti heidät kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 28, 'Niin myös, samoin kuin kävi Lootin päivinä: he söivät, joivat, ostivat, myivät, istuttivat ja rakensivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 29, 'mutta sinä päivänä, jona Loot lähti Sodomasta, satoi tulta ja tulikiveä taivaasta, ja se hukutti heidät kaikki,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 30, 'samoin käy sinä päivänä, jona Ihmisen Poika ilmestyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 31, 'Sinä päivänä älköön se, joka katolla on ja jolla on tavaransa huoneessa, astuko alas niitä noutamaan; ja älköön myös se, joka pellolla on, palatko takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 32, 'Muistakaa Lootin vaimoa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 33, 'Joka tahtoo tallettaa elämänsä itselleen, hän kadottaa sen; mutta joka sen kadottaa, pelastaa sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 34, 'Minä sanon teille: sinä yönä on kaksi miestä yhdellä vuoteella; toinen korjataan talteen, ja toinen jätetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 35, 'Kaksi naista jauhaa yhdessä; toinen korjataan talteen, mutta toinen jätetään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 36, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 17, 37, 'Ja he vastasivat ja sanoivat hänelle: \"Missä, Herra?\" Niin hän sanoi heille: \"Missä raato on, sinne myös kotkat kokoontuvat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 1, 'Ja hän puhui heille vertauksen siitä, että heidän tuli aina rukoilla eikä väsyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 2, 'Hän sanoi: \"Eräässä kaupungissa oli tuomari, joka ei peljännyt Jumalaa eikä hävennyt ihmisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 3, 'Ja siinä kaupungissa oli leskivaimo, joka vähän väliä tuli hänen luoksensa ja sanoi: \'Auta minut oikeuteeni riitapuoltani vastaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 4, 'Mutta pitkään aikaan hän ei tahtonut. Vaan sitten hän sanoi mielessään: \'Vaikka en pelkää Jumalaa enkä häpeä ihmisiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 5, 'niin kuitenkin, koska tämä leski tuottaa minulle vaivaa, minä autan hänet oikeuteensa, ettei hän lopulta tulisi ja kävisi minun silmilleni\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 6, 'Niin Herra sanoi: \"Kuulkaa, mitä tuo väärä tuomari sanoo!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 7, 'Eikö sitten Jumala toimittaisi oikeutta valituillensa, jotka häntä yötä päivää avuksi huutavat, ja viivyttäisikö hän heiltä apuansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 8, 'Minä sanon teille: hän toimittaa heille oikeuden pian. Kuitenkin, kun Ihmisen Poika tulee, löytäneekö hän uskoa maan päältä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 9, 'Niin hän puhui vielä muutamille, jotka luottivat itseensä, luullen olevansa vanhurskaita, ja ylenkatsoivat muita, tämän vertauksen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 10, '\"Kaksi miestä meni ylös pyhäkköön rukoilemaan, toinen fariseus ja toinen publikaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 11, 'Fariseus seisoi ja rukoili itsekseen näin: \'Jumala, minä kiitän sinua, etten minä ole niinkuin muut ihmiset, riistäjät, väärämieliset, huorintekijät, enkä myöskään niinkuin tuo publikaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 12, 'Minä paastoan kahdesti viikossa; minä annan kymmenykset kaikista tuloistani.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 13, 'Mutta publikaani seisoi taampana eikä edes tahtonut nostaa silmiään taivasta kohti, vaan löi rintaansa ja sanoi: \'Jumala, ole minulle syntiselle armollinen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 14, 'Minä sanon teille: tämä meni kotiinsa vanhurskaampana kuin se toinen; sillä jokainen, joka itsensä ylentää, alennetaan, mutta joka itsensä alentaa, se ylennetään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 15, 'Ja he toivat hänen tykönsä myös pieniä lapsia, että hän koskisi heihin; mutta sen nähdessään opetuslapset nuhtelivat tuojia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 16, 'Mutta Jeesus kutsui lapset tykönsä ja sanoi: \"Sallikaa lasten tulla minun tyköni älkääkä estäkö heitä, sillä senkaltaisten on Jumalan valtakunta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 17, 'Totisesti minä sanon teille: joka ei ota vastaan Jumalan valtakuntaa niinkuin lapsi, se ei pääse sinne sisälle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 18, 'Ja eräs hallitusmies kysyi häneltä sanoen: \"Hyvä opettaja, mitä minun pitää tekemän, että minä iankaikkisen elämän perisin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 19, 'Jeesus sanoi hänelle: \"Miksi sanot minua hyväksi? Ei kukaan ole hyvä, paitsi Jumala yksin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 20, 'Käskyt sinä tiedät: \'Älä tee huorin\', \'Älä tapa\', \'Älä varasta\', \'Älä sano väärää todistusta\', \'Kunnioita isääsi ja äitiäsi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 21, 'Mutta hän sanoi: \"Tätä kaikkea minä olen noudattanut nuoruudestani asti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 22, 'Kun Jeesus sen kuuli, sanoi hän hänelle: \"Yksi sinulta vielä puuttuu: myy kaikki, mitä sinulla on, ja jakele köyhille, niin sinulla on oleva aarre taivaissa; ja tule ja seuraa minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 23, 'Mutta tämän kuullessaan hän tuli kovin murheelliseksi, sillä hän oli sangen rikas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 24, 'Kun Jeesus näki hänen olevan murheissaan, sanoi hän: \"Kuinka vaikea onkaan niiden, joilla on tavaraa, päästä Jumalan valtakuntaan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 25, 'Helpompi on kamelin käydä neulansilmän läpi kuin rikkaan päästä Jumalan valtakuntaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 26, 'Niin ne, jotka sen kuulivat, sanoivat: \"Kuka sitten voi pelastua?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 27, 'Mutta hän sanoi: \"Mikä ihmisille on mahdotonta, se on Jumalalle mahdollista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 28, 'Silloin Pietari sanoi: \"Katso, me olemme luopuneet siitä, mitä meillä oli, ja seuranneet sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 29, 'Niin hän sanoi heille: \"Totisesti minä sanon teille: ei ole ketään, joka Jumalan valtakunnan tähden on luopunut talosta tai vaimosta tai veljistä tai vanhemmista tai lapsista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 30, 'ja joka ei saisi monin verroin takaisin tässä ajassa, ja tulevassa maailmassa iankaikkista elämää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 31, 'Ja hän otti tykönsä ne kaksitoista ja sanoi heille: \"Katso, me menemme ylös Jerusalemiin, ja kaikki on täysin toteutuva, mitä profeettain kautta on kirjoitettu Ihmisen Pojasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 32, 'Sillä hänet annetaan pakanain käsiin, ja häntä pilkataan ja häväistään ja syljetään;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 33, 'ja ruoskittuaan he tappavat hänet, ja kolmantena päivänä hän nousee ylös.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 34, 'Mutta he eivät ymmärtäneet tästä mitään, ja tämä puhe oli heiltä niin salattu, etteivät he käsittäneet, mitä sanottiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 35, 'Ja hänen lähestyessään Jerikoa eräs sokea istui tien vieressä kerjäten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 36, 'Ja kuullessaan, että siitä kulki kansaa ohi, hän kyseli, mitä se oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 37, 'He ilmoittivat hänelle Jeesuksen, Nasaretilaisen, menevän ohitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 38, 'Niin hän huusi sanoen: \"Jeesus, Daavidin poika, armahda minua!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 39, 'Ja edelläkulkijat nuhtelivat häntä saadakseen hänet vaikenemaan; mutta hän huusi vielä enemmän: \"Daavidin poika, armahda minua!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 40, 'Silloin Jeesus seisahtui ja käski taluttaa hänet tykönsä. Ja hänen tultuaan lähelle Jeesus kysyi häneltä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 41, '\"Mitä tahdot, että minä sinulle tekisin?\" Hän sanoi: \"Herra, että saisin näköni jälleen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 42, 'Niin Jeesus sanoi hänelle: \"Saa näkösi; sinun uskosi on sinut pelastanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 18, 43, 'Ja heti hän sai näkönsä ja seurasi häntä ylistäen Jumalaa. Ja sen nähdessään kaikki kansa kiitti Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 1, 'Ja hän tuli Jerikon kaupunkiin ja kulki sen läpi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 2, 'Ja katso, siellä oli mies, nimeltä Sakkeus; ja hän oli publikaanien päämies ja oli rikas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 3, 'Ja hän koetti saada nähdä Jeesusta, kuka hän oli, mutta ei voinut kansalta, kun oli varreltansa vähäinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 4, 'Niin hän juoksi edelle ja nousi metsäviikunapuuhun nähdäkseen hänet, sillä Jeesus oli kulkeva siitä ohitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 5, 'Ja tultuaan sille paikalle Jeesus katsahti ylös ja sanoi hänelle: \"Sakkeus, tule nopeasti alas, sillä tänään minun pitää oleman sinun huoneessasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 6, 'Ja hän tuli nopeasti alas ja otti hänet iloiten vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 7, 'Ja sen nähdessään kaikki nurisivat sanoen: \"Syntisen miehen luokse hän meni majailemaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 8, 'Mutta Sakkeus astui esiin ja sanoi Herralle: \"Katso, Herra, puolet omaisuudestani minä annan köyhille, ja jos joltakulta olen jotakin petoksella ottanut, niin annan nelinkertaisesti takaisin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 9, 'Niin Jeesus sanoi hänestä: \"Tänään on pelastus tullut tälle huoneelle, koska hänkin on Aabrahamin poika;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 10, 'sillä Ihmisen Poika on tullut etsimään ja pelastamaan sitä, mikä kadonnut on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 11, 'Ja heidän tätä kuunnellessaan hän puhui vielä vertauksen, koska hän oli lähellä Jerusalemia ja he luulivat, että Jumalan valtakunta oli kohta ilmestyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 12, 'Hän sanoi näin: \"Eräs jalosukuinen mies lähti matkalle kaukaiseen maahan saadakseen itsellensä kuninkuuden ja sitten palatakseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 13, 'Ja hän kutsui luoksensa kymmenen palvelijaansa, antoi heille kymmenen leiviskää ja sanoi heille: \'Asioikaa näillä, kunnes minä tulen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 14, 'Mutta hänen kansalaisensa vihasivat häntä ja lähettivät lähettiläät hänen jälkeensä sanomaan: \'Emme tahdo tätä kuninkaaksemme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 15, 'Ja saatuansa kuninkuuden ja palattuansa hän käski kutsua eteensä ne palvelijat, joille hän oli antanut rahat, saadakseen tietää, mitä kukin oli asioimisellaan ansainnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 16, 'Niin ensimmäinen tuli esiin ja sanoi: \'Herra, sinun leiviskäsi on tuottanut kymmenen leiviskää\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 17, 'Ja hän sanoi hänelle: \'Hyvä on, sinä hyvä palvelija; koska vähimmässä olet ollut uskollinen, niin saat vallita kymmentä kaupunkia\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 18, 'Ja toinen tuli ja sanoi: \'Herra, sinun leiviskäsi on tuottanut viisi leiviskää\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 19, 'Niin hän sanoi tällekin: \'Sinä, vallitse sinä viittä kaupunkia\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 20, 'Vielä tuli yksi ja sanoi: \'Herra, katso, tässä on sinun leiviskäsi, jota olen säilyttänyt liinasessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 21, 'Sillä minä pelkäsin sinua, koska olet ankara mies: sinä otat, mitä et ole talteen pannut, ja leikkaat, mitä et ole kylvänyt.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 22, 'Hän sanoi hänelle: \'Oman sanasi mukaan minä sinut tuomitsen, sinä paha palvelija. Sinä tiesit minut ankaraksi mieheksi, joka otan, mitä en ole talteen pannut, ja leikkaan, mitä en ole kylvänyt;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 23, 'miksi et siis antanut rahojani rahanvaihtajan pöytään, että minä tultuani olisin saanut periä ne korkoineen?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 24, 'Ja hän sanoi vieressä seisoville: \'Ottakaa häneltä pois se leiviskä ja antakaa sille, jolla on kymmenen leiviskää\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 25, '-Niin he sanoivat hänelle: \'Herra, hänellä on jo kymmenen leiviskää\'. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 26, '\'Minä sanon teille: jokaiselle, jolla on, annetaan; mutta jolla ei ole, siltä otetaan pois sekin, mikä hänellä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 27, 'Mutta viholliseni, jotka eivät tahtoneet minua kuninkaaksensa, tuokaa tänne ja teloittakaa minun edessäni.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 28, 'Ja tämän sanottuaan hän kulki edellä vaeltaen ylös Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 29, 'Ja tapahtui, kun hän tuli lähelle Beetfagea ja Betaniaa, sille vuorelle, jota kutsutaan Öljymäeksi, että hän lähetti kaksi opetuslastaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 30, 'sanoen: \"Menkää edessä olevaan kylään, niin sinne tullessanne te löydätte sidottuna varsan, jonka selässä ei vielä yksikään ihminen ole istunut; päästäkää se ja tuokaa tänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 31, 'Ja jos joku kysyy teiltä: \'Miksi te sen päästätte?\' niin sanokaa näin: \'Herra tarvitsee sitä\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 32, 'Ja lähetetyt menivät ja havaitsivat niin olevan, kuin hän oli heille sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 33, 'Ja heidän päästäessään varsaa sen omistajat sanoivat heille: \"Miksi te päästätte varsan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 34, 'Niin he sanoivat: \"Herra tarvitsee sitä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 35, 'Ja he veivät sen Jeesuksen luo ja heittivät vaatteensa varsan selkään ja istuttivat Jeesuksen niiden päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 36, 'Ja hänen kulkiessaan kansa levitti vaatteensa tielle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 37, 'Ja kun hän jo oli lähellä, laskeutuen Öljymäen rinnettä, rupesi koko opetuslasten joukko iloiten kiittämään Jumalaa suurella äänellä kaikista voimallisista teoista, jotka he olivat nähneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 38, 'sanoen: \"Siunattu olkoon hän, joka tulee, Kuningas Herran nimessä; rauha taivaassa ja kunnia korkeuksissa!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 39, 'Ja muutamat fariseukset kansanjoukosta sanoivat hänelle: \"Opettaja, nuhtele opetuslapsiasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 40, 'Mutta hän vastasi ja sanoi: \"Minä sanon teille: jos nämä olisivat vaiti, niin kivet huutaisivat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 41, 'Ja kun hän tuli lähemmäksi ja näki kaupungin, itki hän sitä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 42, 'ja sanoi: \"Jospa tietäisit sinäkin tänä päivänä, mikä rauhaasi sopii! Mutta nyt se on sinun silmiltäsi salattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 43, 'Sillä sinulle tulevat ne päivät, jolloin sinun vihollisesi sinut vallilla saartavat ja piirittävät sinut ja ahdistavat sinua joka puolelta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 44, 'ja he kukistavat sinut maan tasalle ja surmaavat lapsesi, jotka sinussa ovat, eivätkä jätä sinuun kiveä kiven päälle, sentähden ettet etsikkoaikaasi tuntenut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 45, 'Ja hän meni pyhäkköön ja rupesi ajamaan myyjiä ulos');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 46, 'ja sanoi heille: \"Kirjoitettu on: \'Minun huoneeni on oleva rukoushuone\', mutta te olette tehneet siitä ryövärien luolan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 47, 'Ja hän opetti joka päivä pyhäkössä. Mutta ylipapit ja kirjanoppineet sekä kansan ensimmäiset miettivät, miten saisivat hänet surmatuksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 19, 48, 'mutta he eivät keksineet, mitä tekisivät, sillä kaikki kansa riippui hänessä ja kuunteli häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 1, 'Ja tapahtui eräänä päivänä, kun hän opetti kansaa pyhäkössä ja julisti evankeliumia, että ylipapit ja kirjanoppineet astuivat yhdessä vanhinten kanssa esiin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 2, 'ja puhuivat hänelle sanoen: \"Sano meille, millä vallalla sinä näitä teet, tahi kuka on se, joka on antanut sinulle tämän vallan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 3, 'Hän vastasi ja sanoi heille: \"Minä myös teen teille kysymyksen; sanokaa minulle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 4, 'oliko Johanneksen kaste taivaasta vai ihmisistä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 5, 'Niin he neuvottelivat keskenänsä sanoen: \"Jos sanomme: \'Taivaasta\', niin hän sanoo: \'Miksi ette siis uskoneet häntä?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 6, 'Mutta jos sanomme: \'Ihmisistä\', niin kaikki kansa kivittää meidät, sillä se uskoo vahvasti, että Johannes oli profeetta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 7, 'Ja he vastasivat, etteivät tienneet, mistä se oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 8, 'Niin Jeesus sanoi heille: \"Niinpä en minäkään sano teille, millä vallalla minä näitä teen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 9, 'Ja hän rupesi puhumaan kansalle ja puhui tämän vertauksen: \"Mies istutti viinitarhan ja vuokrasi sen viinitarhureille ja matkusti muille maille kauaksi aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 10, 'Ja ajan tullen hän lähetti palvelijan viinitarhurien luokse, että he antaisivat tälle osan viinitarhan hedelmistä; mutta viinitarhurit pieksivät hänet ja lähettivät tyhjin käsin pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 11, 'Ja hän lähetti vielä toisen palvelijan; mutta hänetkin he pieksivät ja häpäisivät ja lähettivät tyhjin käsin pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 12, 'Ja hän lähetti vielä kolmannen; mutta tämänkin he haavoittivat ja heittivät ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 13, 'Niin viinitarhan herra sanoi: \'Mitä minä teen? Minä lähetän rakkaan poikani; häntä he kaiketi kavahtavat.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 14, 'Mutta kun viinitarhurit näkivät hänet, neuvottelivat he keskenään ja sanoivat: \'Tämä on perillinen; tappakaamme hänet, että perintö tulisi meidän omaksemme\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 15, 'Ja he heittivät hänet ulos viinitarhasta ja tappoivat. Mitä nyt viinitarhan herra on tekevä heille?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 16, 'Hän tulee ja tuhoaa nämä viinitarhurit ja antaa viinitarhan muille.\" Niin he sen kuullessaan sanoivat: \"Pois se!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 17, 'Mutta hän katsahti heihin ja sanoi: \"Mitä siis on tämä kirjoitus: \'Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 18, 'Jokainen, joka kaatuu siihen kiveen, ruhjoutuu, mutta jonka päälle se kaatuu, sen se murskaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 19, 'Ja kirjanoppineet ja ylipapit tahtoivat ottaa hänet sillä hetkellä kiinni, mutta he pelkäsivät kansaa; sillä he ymmärsivät, että hän oli puhunut sen vertauksen heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 20, 'Ja he vartioivat häntä ja lähettivät hänen luokseen hurskaiksi tekeytyviä urkkijoita, saadakseen hänet kiinni jostakin sanasta, niin että voisivat antaa hänet esivallalle ja maaherran käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 21, 'Ja ne kysyivät häneltä sanoen: \"Opettaja, me tiedämme, että sinä puhut ja opetat oikein etkä katso henkilöön, vaan opetat Jumalan tietä totuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 22, 'Onko meidän lupa antaa keisarille veroa vai eikö?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 23, 'Mutta hän havaitsi heidän kavaluutensa ja sanoi heille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 24, '\"Näyttäkää minulle denari. Kenen kuva ja päällekirjoitus siinä on?\" He vastasivat: \"Keisarin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 25, 'Niin hän sanoi heille: \"Antakaa siis keisarille, mikä keisarin on, ja Jumalalle, mikä Jumalan on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 26, 'Ja he eivät kyenneet saamaan häntä hänen puheestaan kiinni kansan edessä; ja he ihmettelivät hänen vastaustaan ja vaikenivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 27, 'Niin astui esiin muutamia saddukeuksia, jotka väittävät, ettei ylösnousemusta ole, ja he kysyivät häneltä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 28, 'sanoen: \"Opettaja, Mooses on säätänyt meille: \'Jos joltakin kuolee veli, jolla on vaimo, mutta ei ole lapsia, niin ottakoon hän veljensä vaimon ja herättäköön siemenen veljelleen\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 29, 'Nyt oli seitsemän veljestä. Ensimmäinen otti vaimon ja kuoli lapsetonna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 30, 'Niin toinen otti sen vaimon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 31, 'ja sitten kolmas, ja samoin kaikki seitsemän; ja he kuolivat jättämättä lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 32, 'Viimeiseksi vaimokin kuoli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 33, 'Kenelle heistä siis tämä vaimo ylösnousemuksessa joutuu vaimoksi? Sillä kaikkien seitsemän vaimona hän oli ollut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 34, 'Niin Jeesus sanoi heille: \"Tämän maailmanajan lapset naivat ja menevät miehelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 35, 'Mutta ne, jotka on arvollisiksi nähty pääsemään toiseen maailmaan ja ylösnousemukseen kuolleista, eivät nai eivätkä mene miehelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 36, 'Sillä he eivät enää voi kuolla, kun ovat enkelien kaltaisia; ja he ovat Jumalan lapsia, koska ovat ylösnousemuksen lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 37, 'Mutta että kuolleet nousevat ylös, sen Mooseskin on osoittanut kertomuksessa orjantappurapensaasta, kun hän sanoo Herraa Aabrahamin Jumalaksi ja Iisakin Jumalaksi ja Jaakobin Jumalaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 38, 'Mutta hän ei ole kuolleitten Jumala, vaan elävien; sillä kaikki hänelle elävät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 39, 'Niin muutamat kirjanoppineista vastasivat ja sanoivat: \"Opettaja, oikein sinä sanoit\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 40, 'Ja he eivät enää rohjenneet kysyä häneltä mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 41, 'Niin hän sanoi heille: \"Kuinka he voivat sanoa, että Kristus on Daavidin poika?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 42, 'Sanoohan Daavid itse psalmien kirjassa: \'Herra sanoi minun Herralleni: Istu minun oikealle puolelleni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 43, 'kunnes minä panen sinun vihollisesi sinun jalkojesi astinlaudaksi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 44, 'Daavid siis kutsuu häntä Herraksi; kuinka hän sitten on hänen poikansa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 45, 'Ja kaiken kansan kuullen hän sanoi opetuslapsillensa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 46, '\"Kavahtakaa kirjanoppineita, jotka mielellään käyskelevät pitkissä vaipoissa ja haluavat tervehdyksiä toreilla ja etumaisia istuimia synagoogissa ja ensimmäisiä sijoja pidoissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 20, 47, 'noita, jotka syövät leskien huoneet ja näön vuoksi pitävät pitkiä rukouksia; he saavat sitä kovemman tuomion\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 1, 'Ja hän katsahti ja näki rikkaiden panevan lahjoja uhriarkkuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 2, 'Niin hän näki myös köyhän lesken panevan siihen kaksi ropoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 3, 'Silloin hän sanoi: \"Totisesti minä sanon teille: tämä köyhä leski pani enemmän kuin kaikki muut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 4, 'Sillä kaikki nuo panivat lahjansa liiastaan, mutta tämä pani puutteestaan, koko elämisensä, mikä hänellä oli.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 5, 'Ja kun muutamat puhuivat pyhäköstä, kuinka se oli kauniilla kivillä ja temppelilahjoilla kaunistettu, sanoi hän:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 6, '\"Päivät tulevat, jolloin tästä, mitä katselette, ei ole jäävä kiveä kiven päälle, maahan jaottamatta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 7, 'Niin he kysyivät häneltä sanoen: \"Opettaja, milloin tämä sitten tapahtuu? Ja mikä on oleva merkki tämän tulemisesta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 8, 'Niin hän sanoi: \"Katsokaa, ettei teitä eksytetä. Sillä monta tulee minun nimessäni sanoen: \'Minä olen se\', ja: \'Aika on lähellä\'. Mutta älkää menkö heidän perässään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 9, 'Ja kun kuulette sotien ja kapinain melskettä, älkää peljästykö. Sillä näitten täytyy ensin tapahtua, mutta loppu ei tule vielä heti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 10, 'Sitten hän sanoi heille: \"Kansa nousee kansaa vastaan ja valtakunta valtakuntaa vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 11, 'ja tulee suuria maanjäristyksiä, tulee ruttoa ja nälänhätää monin paikoin, ja taivaalla on oleva peljättäviä näkyjä ja suuria merkkejä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 12, 'Mutta ennen tätä kaikkea he käyvät teihin käsiksi ja vainoavat teitä ja vetävät teidät synagoogiin ja heittävät vankiloihin ja vievät teidät kuningasten ja maaherrain eteen minun nimeni tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 13, 'Ja näin te joudutte todistamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 14, 'Pankaa siis sydämellenne, ettette edeltäpäin huolehdi, miten te vastaatte puolestanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 15, 'Sillä minä annan teille suun ja viisauden, jota vastaan eivät ketkään teidän vastustajanne kykene asettumaan tai väittämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 16, 'Omat vanhemmatkin ja veljet ja sukulaiset ja ystävät antavat teidät alttiiksi; ja muutamia teistä tapetaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 17, 'ja te joudutte kaikkien vihattaviksi minun nimeni tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 18, 'Mutta ei hiuskarvaakaan teidän päästänne katoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 19, 'Kestäväisyydellänne te voitatte omaksenne elämän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 20, 'Mutta kun te näette Jerusalemin sotajoukkojen ympäröimänä, silloin tietäkää, että sen hävitys on lähellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 21, 'Silloin ne, jotka Juudeassa ovat, paetkoot vuorille, ja jotka ovat kaupungissa, lähtekööt sieltä pois, ja jotka maalla ovat, älkööt sinne menkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 22, 'Sillä ne ovat koston päiviä, että kaikki täyttyisi, mikä kirjoitettu on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 23, 'Voi raskaita ja imettäväisiä niinä päivinä! Sillä suuri hätä on oleva maan päällä ja viha tätä kansaa vastaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 24, 'ja he kaatuvat miekan terään, heidät viedään vangeiksi kaikkien kansojen sekaan, ja Jerusalem on oleva pakanain tallattavana, kunnes pakanain ajat täyttyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 25, 'Ja on oleva merkit auringossa ja kuussa ja tähdissä, ja ahdistus kansoilla maan päällä ja epätoivo, kun meri ja aallot pauhaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 26, 'Ja ihmiset menehtyvät peljätessään ja odottaessaan sitä, mikä maanpiiriä kohtaa; sillä taivaitten voimat järkkyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 27, 'Ja silloin he näkevät Ihmisen Pojan tulevan pilvessä suurella voimalla ja kirkkaudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 28, 'Mutta kun nämä alkavat tapahtua, niin rohkaiskaa itsenne ja nostakaa päänne, sillä teidän vapautuksenne on lähellä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 29, 'Ja hän puhui heille vertauksen: \"Katsokaa viikunapuuta ja kaikkia puita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 30, 'Kun ne jo puhkeavat lehteen, niin siitä te näette ja itsestänne ymmärrätte, että kesä jo on lähellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 31, 'Samoin te myös, kun näette tämän tapahtuvan, tietäkää, että Jumalan valtakunta on lähellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 32, 'Totisesti minä sanon teille: tämä sukupolvi ei katoa, ennenkuin kaikki tapahtuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 33, 'Taivas ja maa katoavat, mutta minun sanani eivät katoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 34, 'Mutta pitäkää vaari itsestänne, ettei teidän sydämiänne raskauta päihtymys ja juoppous eikä elatuksen murheet, niin että se päivä yllättää teidät äkkiarvaamatta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 35, 'niinkuin paula; sillä se on saavuttava kaikki, jotka koko maan päällä asuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 36, 'Valvokaa siis joka aika ja rukoilkaa, että saisitte voimaa paetaksenne tätä kaikkea, mikä tuleva on, ja seisoaksenne Ihmisen Pojan edessä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 37, 'Ja hän opetti päivät pyhäkössä, mutta öiksi hän lähti pois ja vietti ne vuorella, jota kutsutaan Öljymäeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 21, 38, 'Ja kaikki kansa tuli varhain aamuisin hänen tykönsä pyhäkköön kuulemaan häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 1, 'Mutta happamattoman leivän juhla, jota pääsiäiseksi sanotaan, oli lähellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 2, 'Ja ylipapit ja kirjanoppineet miettivät, kuinka saisivat hänet surmatuksi; sillä he pelkäsivät kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 3, 'Niin saatana meni Juudaaseen, jota kutsuttiin Iskariotiksi ja joka oli yksi niistä kahdestatoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 4, 'Ja tämä meni ja puhui ylipappien ja pyhäkön vartioston päällikköjen kanssa, miten hän saattaisi hänet heidän käsiinsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 5, 'Ja he ihastuivat ja sitoutuivat antamaan hänelle rahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 6, 'Ja hän lupautui ja etsi sopivaa tilaisuutta kavaltaakseen hänet heille ilman melua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 7, 'Niin tuli se happamattoman leivän päivistä, jona pääsiäislammas oli teurastettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 8, 'Ja hän lähetti Pietarin ja Johanneksen sanoen: \"Menkää ja valmistakaa meille pääsiäislammas syödäksemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 9, 'Niin he kysyivät häneltä: \"Mihin tahdot, että valmistamme sen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 10, 'Hän vastasi heille: \"Katso, saapuessanne kaupunkiin tulee teitä vastaan mies kantaen vesiastiaa; seuratkaa häntä siihen taloon, johon hän menee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 11, 'ja sanokaa talon isännälle: \'Opettaja sanoo sinulle: Missä on vierashuone, syödäkseni siinä pääsiäislampaan opetuslasteni kanssa?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 12, 'Niin hän näyttää teille suuren, aterioiville varustetun huoneen yläkerrassa; sinne valmistakaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 13, 'Ja he menivät ja havaitsivat niin olevan, kuin Jeesus oli heille sanonut, ja valmistivat pääsiäislampaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 14, 'Ja kun hetki tuli, asettui hän aterialle ja apostolit hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 15, 'Ja hän sanoi heille: \"Minä olen halajamalla halannut syödä tämän pääsiäislampaan teidän kanssanne, ennenkuin minä kärsin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 16, 'sillä minä sanon teille, etten minä sitä enää syö, ennenkuin sen täyttymys tapahtuu Jumalan valtakunnassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 17, 'Ja hän otti maljan, kiitti ja sanoi: \"Ottakaa tämä ja jakakaa keskenänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 18, 'Sillä minä sanon teille: tästedes minä en juo viinipuun antia, ennenkuin Jumalan valtakunta tulee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 19, 'Ja hän otti leivän, kiitti, mursi ja antoi heille ja sanoi: \"Tämä on minun ruumiini, joka teidän edestänne annetaan. Tehkää se minun muistokseni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 20, 'Samoin myös maljan, aterian jälkeen, ja sanoi: \"Tämä malja on uusi liitto minun veressäni, joka teidän edestänne vuodatetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 21, 'Mutta, katso, minun kavaltajani käsi on minun kanssani pöydällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 22, 'Sillä Ihmisen Poika tosin menee pois, niinkuin säädetty on; mutta voi sitä ihmistä, jonka kautta hänet kavalletaan!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 23, 'Ja he rupesivat keskenänsä kyselemään, kuka heistä mahtoi olla se, joka oli tämän tekevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 24, 'Ja heidän välillään syntyi myös kiista siitä, kuka heistä oli katsottava suurimmaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 25, 'Niin hän sanoi heille: \"Kansojen kuninkaat herroina niitä hallitsevat, ja niiden valtiaita sanotaan hyväntekijöiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 26, 'Mutta älkää te niin; vaan joka teidän keskuudessanne on suurin, se olkoon niinkuin nuorin, ja johtaja niinkuin se, joka palvelee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 27, 'Sillä kumpi on suurempi, sekö, joka aterioi, vai se, joka palvelee? Eikö se, joka aterioi? Mutta minä olen teidän keskellänne niinkuin se, joka palvelee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 28, 'Mutta te olette pysyneet minun kanssani minun kiusauksissani;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 29, 'ja minä säädän teille, niinkuin minun Isäni on minulle säätänyt, kuninkaallisen vallan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 30, 'niin että te saatte syödä ja juoda minun pöydässäni minun valtakunnassani ja istua valtaistuimilla ja tuomita Israelin kahtatoista sukukuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 31, 'Simon, Simon, katso, saatana on tavoitellut teitä valtaansa, seuloakseen teitä niinkuin nisuja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 32, 'mutta minä olen rukoillut sinun puolestasi, ettei sinun uskosi raukeaisi tyhjään. Ja kun sinä kerran palajat, niin vahvista veljiäsi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 33, 'Niin Simon sanoi hänelle: \"Herra, sinun kanssasi minä olen valmis menemään sekä vankeuteen että kuolemaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 34, 'Mutta hän sanoi: \"Minä sanon sinulle, Pietari: ei laula tänään kukko, ennenkuin sinä kolmesti kiellät tuntevasi minua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 35, 'Ja hän sanoi heille: \"Kun minä lähetin teidät ilman rahakukkaroa ja laukkua ja kenkiä, puuttuiko teiltä mitään?\" He vastasivat: \"Ei mitään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 36, 'Niin hän sanoi heille: \"Mutta nyt, jolla on kukkaro, ottakoon sen mukaansa; niin myös laukun. Ja jolla ei ole, myyköön vaippansa ja ostakoon miekan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 37, 'Sillä minä sanon teille, että minussa pitää käymän toteen tämän, mikä kirjoitettu on: \'Ja hänet luettiin pahantekijäin joukkoon\'. Sillä se, mikä minusta on sanottu, on täyttynyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 38, 'Niin he sanoivat: \"Herra, katso, tässä on kaksi miekkaa\". Mutta hän vastasi heille: \"Riittää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 39, 'Ja hän meni ulos ja lähti tapansa mukaan Öljymäelle, ja hänen opetuslapsensa seurasivat häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 40, 'Ja tultuaan siihen paikkaan hän sanoi heille: \"Rukoilkaa, ettette joutuisi kiusaukseen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 41, 'Ja hän vetäytyi heistä noin kivenheiton päähän, laskeutui polvilleen ja rukoili');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 42, 'sanoen: \"Isä, jos sinä tahdot, niin ota pois minulta tämä malja; älköön kuitenkaan tapahtuko minun tahtoni, vaan sinun\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 43, 'Niin hänelle ilmestyi taivaasta enkeli, joka vahvisti häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 44, 'Ja kun hän oli suuressa tuskassa, rukoili hän yhä hartaammin. Ja hänen hikensä oli niinkuin veripisarat, jotka putosivat maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 45, 'Ja kun hän nousi rukoilemasta ja meni opetuslastensa tykö, tapasi hän heidät murheen tähden nukkumasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 46, 'Niin hän sanoi heille: \"Miksi te nukutte? Nouskaa ja rukoilkaa, ettette joutuisi kiusaukseen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 47, 'Ja katso, hänen vielä puhuessaan tuli joukko kansaa, ja yksi niistä kahdestatoista, se, jonka nimi oli Juudas, kulki heidän edellään. Ja hän tuli Jeesuksen luo antamaan hänelle suuta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 48, 'Mutta Jeesus sanoi hänelle: \"Juudas, suunantamisellako sinä Ihmisen Pojan kavallat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 49, 'Kun nyt ne, jotka olivat hänen ympärillään, näkivät, mitä oli tulossa, sanoivat he: \"Herra, iskemmekö miekalla?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 50, 'Ja eräs heistä iski ylimmäisen papin palvelijaa ja sivalsi häneltä pois oikean korvan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 51, 'Mutta Jeesus vastasi sanoen: \"Sallikaa vielä tämäkin\". Ja hän koski hänen korvaansa ja paransi hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 52, 'Niin Jeesus sanoi ylipapeille ja pyhäkön vartioston päälliköille ja vanhimmille, jotka olivat tulleet häntä vastaan: \"Niinkuin ryöväriä vastaan te olette lähteneet miekat ja seipäät käsissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 53, 'Minä olen joka päivä ollut teidän kanssanne pyhäkössä, ettekä ole ojentaneet käsiänne minua vastaan. Mutta tämä on teidän hetkenne ja pimeyden valta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 54, 'Niin he ottivat hänet kiinni ja kuljettivat pois ja veivät hänet ylimmäisen papin taloon. Ja Pietari seurasi taampana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 55, 'Ja he virittivät valkean keskelle esipihaa ja asettuivat yhdessä istumaan, ja Pietari istui heidän joukkoonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 56, 'Niin eräs palvelijatar, nähdessään hänen istuvan tulen ääressä, katseli häntä kiinteästi ja sanoi: \"Tämäkin oli hänen kanssaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 57, 'Mutta hän kielsi sanoen: \"Nainen, en tunne häntä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 58, 'Ja hetkisen perästä näki hänet toinen, eräs mies, ja sanoi: \"Sinäkin olet yksi niistä\". Mutta Pietari sanoi: \"Mies, en ole\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 59, 'Ja noin yhden hetken kuluttua vakuutti vielä toinen sanoen: \"Totisesti, tämä oli myös hänen kanssaan; sillä onhan hän galilealainenkin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 60, 'Mutta Pietari sanoi: \"En ymmärrä, mies, mitä sanot\". Ja samassa, hänen vielä puhuessaan, lauloi kukko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 61, 'Ja Herra kääntyi ja katsoi Pietariin; ja Pietari muisti Herran sanat, kuinka hän oli hänelle sanonut: \"Ennenkuin kukko tänään laulaa, sinä kolmesti minut kiellät\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 62, 'Ja hän meni ulos ja itki katkerasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 63, 'Ja miehet, jotka pitivät Jeesusta kiinni, pilkkasivat häntä ja pieksivät häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 64, 'Ja he peittivät hänen kasvonsa ja kysyivät häneltä sanoen: \"Profetoi, kuka se on, joka sinua löi!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 65, 'Ja paljon muita herjaussanoja he puhuivat häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 66, 'Ja päivän valjetessa kansan vanhimmat ja ylipapit ja kirjanoppineet kokoontuivat ja veivät hänet neuvostonsa eteen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 67, 'ja sanoivat: \"Jos sinä olet Kristus, niin sano se meille\". Hän vastasi heille: \"Jos minä teille sanon, niin te ette usko;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 68, 'ja jos kysyn, ette vastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 69, 'Mutta tästedes Ihmisen Poika on istuva Jumalan voiman oikealla puolella.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 70, 'Silloin he kaikki sanoivat: \"Sinä siis olet Jumalan Poika?\" Hän vastasi heille: \"Tepä sen sanotte, että minä olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 22, 71, 'Niin he sanoivat: \"Mitä me enää todistusta tarvitsemme? Sillä me itse olemme kuulleet sen hänen omasta suustansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 1, 'Ja he nousivat, koko joukko, ja veivät hänet Pilatuksen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 2, 'Ja he alkoivat syyttää häntä sanoen: \"Tämän me olemme havainneet villitsevän kansaamme, kieltävän antamasta veroja keisarille ja sanovan itseään Kristukseksi, kuninkaaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 3, 'Niin Pilatus kysyi häneltä sanoen: \"Oletko sinä juutalaisten kuningas?\" Hän vastasi hänelle ja sanoi: \"Sinäpä sen sanot\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 4, 'Pilatus sanoi ylipapeille ja kansalle: \"En minä löydä mitään syytä tässä miehessä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 5, 'Mutta he ahdistivat yhä enemmän ja sanoivat: \"Hän yllyttää kansaa opettaen kaikkialla Juudeassa, Galileasta alkaen tänne asti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 6, 'Mutta kun Pilatus sen kuuli, kysyi hän, oliko mies galilealainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 7, 'Ja saatuaan tietää hänen olevan Herodeksen hallintoalueelta hän lähetti hänet Herodeksen eteen, joka hänkin niinä päivinä oli Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 8, 'Kun Herodes näki Jeesuksen, ihastui hän suuresti; sillä hän oli jo kauan aikaa halunnut nähdä häntä, koska oli kuullut hänestä, ja hän toivoi saavansa nähdä häneltä jonkin ihmeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 9, 'Ja hän teki Jeesukselle monia kysymyksiä; mutta tämä ei vastannut hänelle mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 10, 'Ja ylipapit ja kirjanoppineet seisoivat siinä ja syyttivät häntä kiivaasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 11, 'Mutta Herodes joukkoineen kohteli häntä halveksivasti ja pilkkasi häntä; ja puetettuaan hänet loistavaan pukuun hän lähetti hänet takaisin Pilatuksen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 12, 'Ja Herodes ja Pilatus tulivat sinä päivänä ystäviksi keskenään; he olivat näet ennen olleet toistensa vihamiehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 13, 'Niin Pilatus kutsui kokoon ylipapit ja hallitusmiehet ja kansan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 14, 'ja sanoi heille: \"Te olette tuoneet minulle tämän miehen kansan yllyttäjänä; ja katso, minä olen teidän läsnäollessanne häntä tutkinut enkä ole havainnut tätä miestä syylliseksi mihinkään, mistä te häntä syytätte,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 15, 'eikä Herodeskaan, sillä hän lähetti hänet takaisin meille. Ja katso, hän ei ole tehnyt mitään, mikä ansaitsee kuoleman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 16, 'Kuritettuani häntä minä siis hänet päästän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 17, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 18, 'Niin he huusivat kaikki yhdessä, sanoen: \"Vie pois tämä, mutta päästä meille Barabbas!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 19, 'Tämä oli heitetty vankeuteen kaupungissa tehdystä kapinasta sekä murhasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 20, 'Niin Pilatus taas puhui heille, koska hän tahtoi päästää Jeesuksen irti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 21, 'Mutta he huusivat vastaan ja sanoivat: \"Ristiinnaulitse, ristiinnaulitse hänet!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 22, 'Niin hän puhui heille kolmannen kerran: \"Mitä pahaa hän sitten on tehnyt? En ole havainnut hänessä mitään, mistä hän ansaitsisi kuoleman. Kuritettuani häntä minä siis hänet päästän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 23, 'Mutta he ahdistivat häntä suurilla huudoilla, vaatien Jeesusta ristiinnaulittavaksi; ja heidän huutonsa pääsivät voitolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 24, 'Niin Pilatus tuomitsi heidän vaatimuksensa täytettäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 25, 'Ja hän päästi irti sen, joka kapinasta ja murhasta oli vankeuteen heitetty ja jota he vaativat, mutta Jeesuksen hän antoi alttiiksi heidän mielivallallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 26, 'Ja viedessään häntä pois he saivat käsiinsä Simonin, erään kyreneläisen, joka tuli vainiolta; ja hänen olalleen he panivat ristin kannettavaksi Jeesuksen jäljessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 27, 'Ja häntä seurasi suuri joukko kansaa, myös naisia, jotka valittivat ja itkivät häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 28, 'Niin Jeesus kääntyi heihin ja sanoi: \"Jerusalemin tyttäret, älkää minua itkekö, vaan itkekää itseänne ja lapsianne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 29, 'Sillä katso, päivät tulevat, jolloin sanotaan: \'Autuaita ovat hedelmättömät ja ne kohdut, jotka eivät ole synnyttäneet, ja rinnat, jotka eivät ole imettäneet\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 30, 'Silloin ruvetaan sanomaan vuorille: \'Langetkaa meidän päällemme\', ja kukkuloille: \'Peittäkää meidät\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 31, 'Sillä jos tämä tehdään tuoreelle puulle, mitä sitten kuivalle tapahtuu?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 32, 'Myös kaksi muuta, kaksi pahantekijää, vietiin hänen kanssaan surmattaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 33, 'Ja kun saavuttiin paikalle, jota sanotaan Pääkallonpaikaksi, niin siellä he ristiinnaulitsivat hänet sekä pahantekijät, toisen oikealle ja toisen vasemmalle puolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 34, 'Mutta Jeesus sanoi: \"Isä, anna heille anteeksi, sillä he eivät tiedä, mitä he tekevät\". Ja he jakoivat keskenään hänen vaatteensa ja heittivät niistä arpaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 35, 'Ja kansa seisoi ja katseli. Ja hallitusmiehetkin ivasivat häntä ja sanoivat: \"Muita hän on auttanut; auttakoon itseänsä, jos hän on Jumalan Kristus, se valittu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 36, 'Myös sotamiehet pilkkasivat häntä, menivät hänen luoksensa ja tarjosivat hänelle hapanviiniä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 37, 'ja sanoivat: \"Jos sinä olet juutalaisten kuningas, niin auta itseäsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 38, 'Oli myös hänen päänsä päällä kirjoitus: \"Tämä on juutalaisten kuningas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 39, 'Niin toinen pahantekijöistä, jotka siinä riippuivat, herjasi häntä: \"Etkö sinä ole Kristus? Auta itseäsi ja meitä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 40, 'Mutta toinen vastasi ja nuhteli häntä sanoen: \"Etkö sinä edes pelkää Jumalaa, sinä, joka olet saman rangaistuksen alainen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 41, 'Me tosin kärsimme oikeuden mukaan, sillä me saamme, mitä meidän tekomme ansaitsevat; mutta tämä ei ole mitään pahaa tehnyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 42, 'Ja hän sanoi: \"Jeesus, muista minua, kun tulet valtakuntaasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 43, 'Niin Jeesus sanoi hänelle: \"Totisesti minä sanon sinulle: tänä päivänä pitää sinun oleman minun kanssani paratiisissa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 44, 'Ja oli jo noin kuudes hetki. Niin yli kaiken maan tuli pimeys, jota kesti hamaan yhdeksänteen hetkeen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 45, 'sillä aurinko oli pimentynyt. Ja temppelin esirippu repesi keskeltä kahtia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 46, 'Ja Jeesus huusi suurella äänellä ja sanoi: \"Isä, sinun käsiisi minä annan henkeni\". Ja sen sanottuaan hän antoi henkensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 47, 'Mutta kun sadanpäämies näki, mitä tapahtui, kunnioitti hän Jumalaa ja sanoi: \"Totisesti, tämä oli vanhurskas mies\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 48, 'Ja kun kaikki kansa, ne, jotka olivat kokoontuneet tätä katselemaan, näkivät, mitä tapahtui, löivät he rintoihinsa ja palasivat kukin kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 49, 'Mutta kaikki hänen tuttavansa seisoivat taampana, myöskin naiset, jotka olivat seuranneet häntä Galileasta, ja katselivat tätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 50, 'Ja katso, oli neuvoston jäsen, nimeltä Joosef, hyvä ja hurskas mies, joka ei ollut suostunut heidän neuvoonsa ja tekoonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 51, 'Tämä oli kotoisin juutalaisten kaupungista Arimatiasta, ja hän odotti Jumalan valtakuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 52, 'Hän meni Pilatuksen luo ja pyysi Jeesuksen ruumista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 53, 'Ja otettuaan sen alas hän kääri sen liinavaatteeseen. Ja hän pani hänet hautaan, joka oli hakattu kallioon ja johon ei oltu vielä ketään pantu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 54, 'Ja silloin oli valmistuspäivä, ja sapatti oli alkamaisillaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 55, 'Ja naiset, jotka olivat tulleet hänen kanssaan Galileasta, seurasivat jäljessä ja katselivat hautaa ja kuinka hänen ruumiinsa sinne pantiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 23, 56, 'Ja palattuaan kotiinsa he valmistivat hyvänhajuisia yrttejä ja voiteita; mutta sapatin he viettivät hiljaisuudessa lain käskyn mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 1, 'Mutta viikon ensimmäisenä päivänä ani varhain he tulivat haudalle, tuoden mukanaan valmistamansa hyvänhajuiset yrtit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 2, 'Ja he havaitsivat kiven vieritetyksi pois haudalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 3, 'Niin he menivät sisään, mutta eivät löytäneet Herran Jeesuksen ruumista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 4, 'Ja kun he olivat tästä ymmällä, niin katso, kaksi miestä seisoi heidän edessään säteilevissä vaatteissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 5, 'Ja he peljästyivät ja kumartuivat kasvoillensa maahan. Niin miehet sanoivat heille: \"Miksi te etsitte elävää kuolleitten joukosta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 6, 'Ei hän ole täällä, hän on noussut ylös. Muistakaa, kuinka hän puhui teille vielä ollessaan Galileassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 7, 'sanoen: \'Ihmisen Poika pitää annettaman syntisten ihmisten käsiin ja ristiinnaulittaman, ja hänen pitää kolmantena päivänä nouseman ylös\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 8, 'Niin he muistivat hänen sanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 9, 'Ja he palasivat haudalta ja veivät sanan tästä kaikesta niille yhdelletoista ja kaikille muille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 10, 'Ja ne, jotka kertoivat tämän apostoleille, olivat Maria Magdaleena ja Johanna ja Maria, Jaakobin äiti, ja muut naiset heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 11, 'Mutta näiden puheet näyttivät heistä turhilta, eivätkä he uskoneet heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 12, 'Mutta Pietari nousi ja juoksi haudalle; ja kun hän kurkisti sisään, näki hän siellä ainoastaan käärinliinat. Ja hän meni pois ihmetellen itsekseen sitä, mikä oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 13, 'Ja katso, kaksi heistä kulki sinä päivänä Emmaus nimiseen kylään, joka on kuudenkymmenen vakomitan päässä Jerusalemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 14, 'Ja he puhelivat keskenään kaikesta tästä, mikä oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 15, 'Ja heidän keskustellessaan ja tutkistellessaan tapahtui, että Jeesus itse lähestyi heitä ja kulki heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 16, 'Mutta heidän silmänsä olivat pimitetyt, niin etteivät he tunteneet häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 17, 'Ja hän sanoi heille: \"Mistä te siinä kävellessänne puhutte keskenänne?\" Niin he seisahtuivat murheellisina muodoltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 18, 'Ja toinen heistä, nimeltä Kleopas, vastasi ja sanoi hänelle: \"Oletko sinä ainoa muukalainen Jerusalemissa, joka et tiedä, mitä siellä näinä päivinä on tapahtunut?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 19, 'Hän sanoi heille: \"Mitä?\" Niin he sanoivat hänelle: \"Sitä, mikä tapahtui Jeesukselle, Nasaretilaiselle, joka oli profeetta, voimallinen teossa ja sanassa Jumalan ja kaiken kansan edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 20, 'kuinka meidän ylipappimme ja hallitusmiehemme antoivat hänet tuomittavaksi kuolemaan ja ristiinnaulitsivat hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 21, 'Mutta me toivoimme hänen olevan sen, joka oli lunastava Israelin. Ja onhan kaiken tämän lisäksi nyt jo kolmas päivä siitä, kuin nämä tapahtuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 22, 'Ovatpa vielä muutamat naiset joukostamme saattaneet meidät hämmästyksiin. He kävivät aamulla varhain haudalla');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 23, 'eivätkä löytäneet hänen ruumistaan, ja tulivat ja sanoivat myös nähneensä enkelinäyn, ja enkelit olivat sanoneet hänen elävän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 24, 'Ja muutamat niistä, jotka olivat meidän kanssamme, menivät haudalle ja havaitsivat niin olevan, kuin naiset olivat sanoneet; mutta häntä he eivät nähneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 25, 'Niin hän sanoi heille: \"Oi, te ymmärtämättömät ja hitaat sydämeltä uskomaan kaikkea sitä, minkä profeetat ovat puhuneet!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 26, 'Eikö Kristuksen pitänyt tätä kärsimän ja sitten menemän kirkkauteensa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 27, 'Ja hän alkoi Mooseksesta ja kaikista profeetoista ja selitti heille, mitä hänestä oli kaikissa kirjoituksissa sanottu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 28, 'Ja kun he lähestyivät kylää, johon olivat menossa, niin hän oli aikovinaan kulkea edemmäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 29, 'Mutta he vaativat häntä sanoen: \"Jää meidän luoksemme, sillä ilta joutuu ja päivä on jo laskemassa\". Ja hän meni sisään ja jäi heidän luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 30, 'Ja tapahtui, kun hän oli aterialla heidän kanssaan, että hän otti leivän, siunasi, mursi ja antoi heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 31, 'Silloin heidän silmänsä aukenivat, ja he tunsivat hänet. Ja hän katosi heidän näkyvistään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 32, 'Ja he sanoivat toisillensa: \"Eikö sydämemme ollut meissä palava, kun hän puhui meille tiellä ja selitti meille kirjoitukset?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 33, 'Ja he nousivat sillä hetkellä ja palasivat Jerusalemiin ja tapasivat ne yksitoista kokoontuneina ja ne, jotka olivat heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 34, 'Ja nämä sanoivat: \"Herra on totisesti noussut ylös ja on ilmestynyt Simonille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 35, 'Ja itse he kertoivat, mitä oli tapahtunut tiellä ja kuinka he olivat hänet tunteneet, kun hän mursi leivän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 36, 'Mutta heidän tätä puhuessaan Jeesus itse seisoi heidän keskellään ja sanoi heille: \"Rauha teille!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 37, 'Niin heidät valtasi säikähdys ja pelko, ja he luulivat näkevänsä hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 38, 'Mutta hän sanoi heille: \"Miksi olette hämmästyneet, ja miksi nousee sellaisia ajatuksia teidän sydämeenne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 39, 'Katsokaa minun käsiäni ja jalkojani ja nähkää, että minä itse tässä olen. Kosketelkaa minua ja katsokaa, sillä ei hengellä ole lihaa eikä luita, niinkuin te näette minulla olevan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 40, 'Ja tämän sanottuaan hän näytti heille kätensä ja jalkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 41, 'Mutta kun he eivät vielä uskoneet, ilon tähden, vaan ihmettelivät, sanoi hän heille: \"Onko teillä täällä jotakin syötävää?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 42, 'Niin he antoivat hänelle palasen paistettua kalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 43, 'Ja hän otti ja söi heidän nähtensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 44, 'Ja hän sanoi heille: \"Tätä tarkoittivat minun sanani, kun minä puhuin teille ollessani vielä teidän kanssanne, että kaiken pitää käymän toteen, mikä minusta on kirjoitettu Mooseksen laissa ja profeetoissa ja psalmeissa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 45, 'Silloin hän avasi heidän ymmärryksensä käsittämään kirjoitukset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 46, 'Ja hän sanoi heille: \"Niin on kirjoitettu, että Kristus oli kärsivä ja kolmantena päivänä nouseva kuolleista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 47, 'ja että parannusta syntien anteeksisaamiseksi on saarnattava hänen nimessänsä kaikille kansoille, alkaen Jerusalemista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 48, 'Te olette tämän todistajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 49, 'Ja katso, minä lähetän teille sen, jonka minun Isäni on luvannut; mutta te pysykää tässä kaupungissa, kunnes teidän päällenne puetaan voima korkeudesta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 50, 'Sitten hän vei heidät pois, lähes Betaniaan asti, ja nosti kätensä ja siunasi heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 51, 'Ja tapahtui, että hän siunatessaan heitä erkani heistä, ja hänet otettiin ylös taivaaseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 52, 'Ja he kumarsivat häntä ja palasivat Jerusalemiin suuresti iloiten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 24, 53, 'Ja he olivat alati pyhäkössä ja ylistivät Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Alussa oli Sana, ja Sana oli Jumalan tykönä, ja Sana oli Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Hän oli alussa Jumalan tykönä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Kaikki on saanut syntynsä hänen kauttaan, ja ilman häntä ei ole syntynyt mitään, mikä syntynyt on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'Hänessä oli elämä, ja elämä oli ihmisten valkeus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Ja valkeus loistaa pimeydessä, ja pimeys ei sitä käsittänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Oli mies, Jumalan lähettämä; hänen nimensä oli Johannes.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Hän tuli todistamaan, todistaaksensa valkeudesta, että kaikki uskoisivat hänen kauttansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Ei hän ollut se valkeus, mutta hän tuli valkeudesta todistamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Totinen valkeus, joka valistaa jokaisen ihmisen, oli tulossa maailmaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Maailmassa hän oli, ja maailma on hänen kauttaan saanut syntynsä, ja maailma ei häntä tuntenut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Hän tuli omiensa tykö, ja hänen omansa eivät ottaneet häntä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Mutta kaikille, jotka ottivat hänet vastaan, hän antoi voiman tulla Jumalan lapsiksi, niille, jotka uskovat hänen nimeensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'jotka eivät ole syntyneet verestä eikä lihan tahdosta eikä miehen tahdosta, vaan Jumalasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Ja Sana tuli lihaksi ja asui meidän keskellämme, ja me katselimme hänen kirkkauttansa, senkaltaista kirkkautta, kuin ainokaisella Pojalla on Isältä; ja hän oli täynnä armoa ja totuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Johannes todisti hänestä ja huusi sanoen: \"Tämä on se, josta minä sanoin: se, joka minun jälkeeni tulee, on ollut minun edelläni, sillä hän on ollut ennen kuin minä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Ja hänen täyteydestään me kaikki olemme saaneet, ja armoa armon päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Sillä laki on annettu Mooseksen kautta; armo ja totuus on tullut Jeesuksen Kristuksen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Ei kukaan ole Jumalaa milloinkaan nähnyt; ainokainen Poika, joka on Isän helmassa, on hänet ilmoittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Ja tämä on Johanneksen todistus, kun juutalaiset lähettivät hänen luoksensa Jerusalemista pappeja ja leeviläisiä kysymään häneltä: \"Kuka sinä olet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Ja hän tunnusti eikä kieltänyt; ja hän tunnusti: \"Minä en ole Kristus\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Ja he kysyivät häneltä: \"Mikä sitten? Oletko sinä Elias?\" Hän sanoi: \"En ole\". \"Se profeettako olet?\" Hän vastasi: \"En\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Niin he sanoivat hänelle: \"Kuka olet, että voisimme antaa vastauksen niille, jotka meidät lähettivät? Mitä sanot itsestäsi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Hän sanoi: \"Minä olen huutavan ääni erämaassa: \'Tehkää tie tasaiseksi Herralle\', niinkuin profeetta Esaias on sanonut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Ja lähetetyt olivat fariseuksia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'ja he kysyivät häneltä ja sanoivat hänelle: \"Miksi sitten kastat, jos et ole Kristus etkä Elias etkä se profeetta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 26, 'Johannes vastasi heille sanoen: \"Minä kastan vedellä; mutta teidän keskellänne seisoo hän, jota te ette tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 27, 'Hän on se, joka tulee minun jälkeeni ja jonka kengänpaulaa minä en ole arvollinen päästämään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 28, 'Tämä tapahtui Betaniassa, Jordanin tuolla puolella, jossa Johannes oli kastamassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 29, 'Seuraavana päivänä hän näki Jeesuksen tulevan tykönsä ja sanoi: \"Katso, Jumalan Karitsa, joka ottaa pois maailman synnin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 30, 'Tämä on se, josta minä sanoin: \'Minun jälkeeni tulee mies, joka on ollut minun edelläni, sillä hän on ollut ennen kuin minä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 31, 'Ja minä en tuntenut häntä; mutta sitä varten, että hän tulisi julki Israelille, minä olen tullut vedellä kastamaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 32, 'Ja Johannes todisti sanoen: \"Minä näin Hengen laskeutuvan taivaasta alas niinkuin kyyhkysen, ja se jäi hänen päällensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 33, 'Ja minä en tuntenut häntä; mutta hän, joka lähetti minut vedellä kastamaan, sanoi minulle: \'Se, jonka päälle sinä näet Hengen laskeutuvan ja jäävän, hän on se, joka kastaa Pyhällä Hengellä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 34, 'Ja minä olen sen nähnyt ja olen todistanut, että tämä on Jumalan Poika.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 35, 'Seuraavana päivänä Johannes taas seisoi siellä ja kaksi hänen opetuslapsistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 36, 'Ja kiinnittäen katseensa Jeesukseen, joka siellä käveli, hän sanoi: \"Katso, Jumalan Karitsa!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 37, 'Ja ne kaksi opetuslasta kuulivat hänen näin puhuvan ja seurasivat Jeesusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 38, 'Niin Jeesus kääntyi ja nähdessään heidän seuraavan sanoi heille: \"Mitä te etsitte?\" He vastasivat hänelle: \"Rabbi\" -se on käännettynä: opettaja-\"missä sinä majailet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 39, 'Hän sanoi heille: \"Tulkaa ja katsokaa\". Niin he menivät ja näkivät, missä hän majaili, ja viipyivät hänen tykönään sen päivän. Silloin oli noin kymmenes hetki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 40, 'Andreas, Simon Pietarin veli, oli toinen niistä kahdesta, jotka olivat kuulleet, mitä Johannes sanoi, ja seuranneet Jeesusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 41, 'Hän tapasi ensin veljensä Simonin ja sanoi hänelle: \"Me olemme löytäneet Messiaan\", se on käännettynä: Kristus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 42, 'Ja hän vei hänet Jeesuksen tykö. Jeesus kiinnitti katseensa häneen ja sanoi: \"Sinä olet Simon, Johanneksen poika; sinun nimesi on oleva Keefas\", joka käännettynä on Pietari.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 43, 'Seuraavana päivänä Jeesus tahtoi lähteä Galileaan; ja hän tapasi Filippuksen ja sanoi hänelle: \"Seuraa minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 44, 'Ja Filippus oli Beetsaidasta, Andreaan ja Pietarin kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 45, 'Filippus tapasi Natanaelin ja sanoi hänelle: \"Me olemme löytäneet sen, josta Mooses laissa ja profeetat ovat kirjoittaneet, Jeesuksen, Joosefin pojan, Nasaretista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 46, 'Natanael sanoi hänelle: \"Voiko Nasaretista tulla mitään hyvää?\" Filippus sanoi hänelle: \"Tule ja katso\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 47, 'Jeesus näki Natanaelin tulevan tykönsä ja sanoi hänestä: \"Katso, oikea israelilainen, jossa ei vilppiä ole!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 48, 'Natanael sanoi hänelle: \"Mistä minut tunnet?\" Jeesus vastasi ja sanoi hänelle: \"Ennenkuin Filippus sinua kutsui, kun olit viikunapuun alla, näin minä sinut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 49, 'Natanael vastasi ja sanoi hänelle: \"Rabbi, sinä olet Jumalan Poika, sinä olet Israelin kuningas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 50, 'Jeesus vastasi ja sanoi hänelle: \"Sentähden, että minä sanoin sinulle: \'minä näin sinut viikunapuun alla\', sinä uskot. Sinä saat nähdä suurempia, kuin nämä ovat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 51, 'Ja hän sanoi hänelle: \"Totisesti, totisesti minä sanon teille: te saatte nähdä taivaan avoinna ja Jumalan enkelien nousevan ylös ja laskeutuvan alas Ihmisen Pojan päälle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Ja kolmantena päivänä oli häät Galilean Kaanassa, ja Jeesuksen äiti oli siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Ja myös Jeesus ja hänen opetuslapsensa olivat kutsutut häihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Ja kun viini loppui, sanoi Jeesuksen äiti hänelle: \"Heillä ei ole viiniä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Jeesus sanoi hänelle: \"Mitä sinä tahdot minusta, vaimo? Minun aikani ei ole vielä tullut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Hänen äitinsä sanoi palvelijoille: \"Mitä hän teille sanoo, se tehkää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Niin oli siinä juutalaisten puhdistamistavan mukaan kuusi kivistä vesiastiaa, kukin kahden tai kolmen mitan vetoinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Jeesus sanoi heille: \"Täyttäkää astiat vedellä\". Ja he täyttivät ne reunoja myöten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'Ja hän sanoi heille: \"Ammentakaa nyt ja viekää edeskäyvälle\". Ja he veivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Mutta kun edeskäypä maistoi vettä, joka oli muuttunut viiniksi, eikä tiennyt, mistä se oli tullut-mutta palvelijat, jotka veden olivat ammentaneet, tiesivät sen-kutsui edeskäypä yljän');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'ja sanoi hänelle: \"Jokainen panee ensin esille hyvän viinin ja sitten, kun juopuvat, huonomman. Sinä olet säästänyt hyvän viinin tähän asti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Tämän ensimmäisen tunnustekonsa Jeesus teki Galilean Kaanassa ja ilmoitti kirkkautensa; ja hänen opetuslapsensa uskoivat häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Sen jälkeen hän meni alas Kapernaumiin, hän ja hänen äitinsä ja veljensä ja opetuslapsensa; ja siellä he eivät viipyneet monta päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Ja juutalaisten pääsiäinen oli lähellä, ja Jeesus meni ylös Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Niin hän tapasi pyhäkössä ne, jotka myivät härkiä ja lampaita ja kyyhkysiä, ja rahanvaihtajat istumassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Ja hän teki nuorista ruoskan ja ajoi ulos pyhäköstä heidät kaikki lampaineen ja härkineen ja kaasi vaihtajain rahat maahan ja työnsi heidän pöytänsä kumoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Ja hän sanoi kyyhkysten myyjille: \"Viekää pois nämä täältä. Älkää tehkö minun Isäni huonetta markkinahuoneeksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Silloin hänen opetuslapsensa muistivat, että on kirjoitettu: \"Kiivaus sinun huoneesi puolesta kuluttaa minut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Niin juutalaiset vastasivat ja sanoivat hänelle: \"Minkä merkin sinä näytät meille, koska näitä teet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Jeesus vastasi ja sanoi heille: \"Hajottakaa maahan tämä temppeli, niin minä pystytän sen kolmessa päivässä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Niin juutalaiset sanoivat: \"Neljäkymmentä kuusi vuotta on tätä temppeliä rakennettu, ja sinäkö pystytät sen kolmessa päivässä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Mutta hän puhui ruumiinsa temppelistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Kun hän sitten oli noussut kuolleista, muistivat hänen opetuslapsensa, että hän oli tämän sanonut; ja he uskoivat Raamatun ja sen sanan, jonka Jeesus oli sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Mutta kun hän oli Jerusalemissa pääsiäisenä, juhlan aikana, uskoivat monet hänen nimeensä, nähdessään hänen tunnustekonsa, jotka hän teki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Mutta Jeesus itse ei uskonut itseänsä heille, sentähden että hän tunsi kaikki');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'eikä tarvinnut kenenkään todistusta ihmisestä, sillä hän tiesi itse, mitä ihmisessä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Mutta oli mies, fariseusten joukosta, nimeltä Nikodeemus, juutalaisten hallitusmiehiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Hän tuli Jeesuksen tykö yöllä ja sanoi hänelle: \"Rabbi, me tiedämme, että sinun opettajaksi tulemisesi on Jumalasta, sillä ei kukaan voi tehdä niitä tunnustekoja, joita sinä teet, ellei Jumala ole hänen kanssansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Jeesus vastasi ja sanoi hänelle: \"Totisesti, totisesti minä sanon sinulle: joka ei synny uudesti, ylhäältä, se ei voi nähdä Jumalan valtakuntaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Nikodeemus sanoi hänelle: \"Kuinka voi ihminen vanhana syntyä? Eihän hän voi jälleen mennä äitinsä kohtuun ja syntyä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Jeesus vastasi: \"Totisesti, totisesti minä sanon sinulle: jos joku ei synny vedestä ja Hengestä, ei hän voi päästä sisälle Jumalan valtakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Mikä lihasta on syntynyt, on liha; ja mikä Hengestä on syntynyt, on henki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Älä ihmettele, että minä sanoin sinulle: teidän täytyy syntyä uudesti, ylhäältä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Tuuli puhaltaa, missä tahtoo, ja sinä kuulet sen huminan, mutta et tiedä, mistä se tulee ja minne se menee; niin on jokaisen, joka on Hengestä syntynyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Nikodeemus vastasi ja sanoi hänelle: \"Kuinka tämä voi tapahtua?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Jeesus vastasi ja sanoi hänelle: \"Sinä olet Israelin opettaja etkä tätä tiedä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Totisesti, totisesti minä sanon sinulle: me puhumme, mitä tiedämme, ja todistamme, mitä olemme nähneet, ettekä te ota vastaan meidän todistustamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Jos ette usko, kun minä puhun teille maallisista, kuinka te uskoisitte, jos minä puhun teille taivaallisista?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Ei kukaan ole noussut ylös taivaaseen, paitsi hän, joka taivaasta tuli alas, Ihmisen Poika, joka on taivaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Ja niinkuin Mooses ylensi käärmeen erämaassa, niin pitää Ihmisen Poika ylennettämän,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'että jokaisella, joka häneen uskoo, olisi iankaikkinen elämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Sillä niin on Jumala maailmaa rakastanut, että hän antoi ainokaisen Poikansa, ettei yksikään, joka häneen uskoo, hukkuisi, vaan hänellä olisi iankaikkinen elämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Sillä ei Jumala lähettänyt Poikaansa maailmaan tuomitsemaan maailmaa, vaan sitä varten, että maailma hänen kauttansa pelastuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Joka uskoo häneen, sitä ei tuomita; mutta joka ei usko, se on jo tuomittu, koska hän ei ole uskonut Jumalan ainokaisen Pojan nimeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Mutta tämä on tuomio, että valkeus on tullut maailmaan, ja ihmiset rakastivat pimeyttä enemmän kuin valkeutta; sillä heidän tekonsa olivat pahat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Sillä jokainen, joka pahaa tekee, vihaa valkeutta eikä tule valkeuteen, ettei hänen tekojansa nuhdeltaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Mutta joka totuuden tekee, se tulee valkeuteen, että hänen tekonsa tulisivat julki, sillä ne ovat Jumalassa tehdyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Sen jälkeen Jeesus meni opetuslapsineen Juudean maaseudulle ja oleskeli siellä heidän kanssaan ja kastoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 23, 'Mutta Johanneskin kastoi Ainonissa lähellä Salimia, koska siellä oli paljon vettä; ja ihmiset tulivat ja antoivat kastaa itsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 24, 'Sillä Johannesta ei vielä oltu heitetty vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 25, 'Niin Johanneksen opetuslapset rupesivat väittelemään erään juutalaisen kanssa puhdistuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 26, 'Ja he tulivat Johanneksen luo ja sanoivat hänelle: \"Rabbi, se, joka oli sinun kanssasi Jordanin tuolla puolella ja josta sinä olet todistanut, katso, hän kastaa, ja kaikki menevät hänen tykönsä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 27, 'Johannes vastasi ja sanoi: \"Ei ihminen voi ottaa mitään, ellei hänelle anneta taivaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 28, 'Te olette itse minun todistajani, että minä sanoin: en minä ole Kristus, vaan minä olen hänen edellänsä lähetetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 29, 'Jolla on morsian, se on ylkä; mutta yljän ystävä, joka seisoo ja kuuntelee häntä, iloitsee suuresti yljän äänestä. Tämä minun iloni on nyt tullut täydelliseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 30, 'Hänen tulee kasvaa, mutta minun vähetä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 31, 'Hän, joka ylhäältä tulee, on yli kaikkien. Joka on syntyisin maasta, se on maasta, ja maasta on, mitä hän puhuu; hän, joka taivaasta tulee, on yli kaikkien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 32, 'Ja mitä hän on nähnyt ja kuullut, sitä hän todistaa; ja hänen todistustansa ei kukaan ota vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 33, 'Joka ottaa vastaan hänen todistuksensa, se sinetillä vahvistaa, että Jumala on totinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 34, 'Sillä hän, jonka Jumala on lähettänyt, puhuu Jumalan sanoja; sillä ei Jumala anna Henkeä mitalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 35, 'Isä rakastaa Poikaa ja on antanut kaikki hänen käteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 36, 'Joka uskoo Poikaan, sillä on iankaikkinen elämä; mutta joka ei ole kuuliainen Pojalle, se ei ole elämää näkevä, vaan Jumalan viha pysyy hänen päällänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Kun nyt Herra sai tietää fariseusten kuulleen, että Jeesus teki opetuslapsiksi ja kastoi useampia kuin Johannes');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, '-vaikka Jeesus ei itse kastanut, vaan hänen opetuslapsensa-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'jätti hän Juudean ja meni taas Galileaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Mutta hänen oli kuljettava Samarian kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Niin hän tuli Sykar nimiseen Samarian kaupunkiin, joka on lähellä sitä maa-aluetta, minkä Jaakob oli antanut pojalleen Joosefille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Ja siellä oli Jaakobin lähde. Kun nyt Jeesus oli matkasta väsynyt, istui hän lähteen reunalle. Ja oli noin kuudes hetki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Niin tuli eräs Samarian nainen ammentamaan vettä. Jeesus sanoi hänelle: \"Anna minulle juoda\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Sillä hänen opetuslapsensa olivat lähteneet kaupunkiin ruokaa ostamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Niin Samarian nainen sanoi hänelle: \"Kuinka sinä, joka olet juutalainen, pyydät juotavaa minulta, samarialaiselta naiselta?\" Sillä juutalaiset eivät seurustele samarialaisten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Jeesus vastasi ja sanoi hänelle: \"Jos sinä tietäisit Jumalan lahjan, ja kuka se on, joka sinulle sanoo: \'Anna minulle juoda\', niin sinä pyytäisit häneltä, ja hän antaisi sinulle elävää vettä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Nainen sanoi hänelle: \"Herra, eipä sinulla ole ammennusastiaa, ja kaivo on syvä; mistä sinulla sitten on se elävä vesi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Et kai sinä ole suurempi kuin meidän isämme Jaakob, joka antoi meille tämän kaivon ja joi siitä, hän itse sekä hänen poikansa ja karjansa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Jeesus vastasi ja sanoi hänelle: \"Jokainen, joka juo tätä vettä, janoaa jälleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'mutta joka juo sitä vettä, jota minä hänelle annan, se ei ikinä janoa; vaan se vesi, jonka minä hänelle annan, tulee hänessä sen veden lähteeksi, joka kumpuaa iankaikkiseen elämään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Nainen sanoi hänelle: \"Herra, anna minulle sitä vettä, ettei minun tulisi jano eikä minun tarvitsisi käydä täällä ammentamassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Jeesus sanoi hänelle: \"Mene, kutsu miehesi ja tule tänne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Nainen vastasi ja sanoi: \"Ei minulla ole miestä\". Jeesus sanoi hänelle: \"Oikein sinä sanoit: \'Ei minulla ole miestä\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'sillä viisi miestä sinulla on ollut, ja se, joka sinulla nyt on, ei ole sinun miehesi; siinä sanoit totuuden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Nainen sanoi hänelle: \"Herra, minä näen, että sinä olet profeetta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 20, 'Meidän isämme ovat kumartaen rukoilleet tällä vuorella; ja te sanotte, että Jerusalemissa on se paikka, jossa tulee kumartaen rukoilla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 21, 'Jeesus sanoi hänelle: \"Vaimo, usko minua! Tulee aika, jolloin ette rukoile Isää tällä vuorella ettekä Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 22, 'Te kumarratte sitä, mitä ette tunne; me kumarramme sitä, minkä me tunnemme. Sillä pelastus on juutalaisista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 23, 'Mutta tulee aika ja on jo, jolloin totiset rukoilijat rukoilevat Isää hengessä ja totuudessa; sillä senkaltaisia rukoilijoita myös Isä tahtoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 24, 'Jumala on Henki; ja jotka häntä rukoilevat, niiden tulee rukoilla hengessä ja totuudessa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 25, 'Nainen sanoi hänelle: \"Minä tiedän, että Messias on tuleva, hän, jota sanotaan Kristukseksi; kun hän tulee, ilmoittaa hän meille kaikki\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 26, 'Jeesus sanoi hänelle: \"Minä olen se, minä, joka puhun sinun kanssasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 27, 'Samassa hänen opetuslapsensa tulivat; ja he ihmettelivät, että hän puhui naisen kanssa. Kuitenkaan ei kukaan sanonut: \"Mitä pyydät?\" tai: \"Mitä puhelet hänen kanssaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 28, 'Niin nainen jätti vesiastiansa ja meni kaupunkiin ja sanoi ihmisille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 29, '\"Tulkaa katsomaan miestä, joka on sanonut minulle kaikki, mitä minä olen tehnyt. Eihän se vain liene Kristus?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 30, 'Niin he lähtivät kaupungista ja menivät hänen luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 31, 'Sillävälin opetuslapset pyysivät häntä sanoen: \"Rabbi, syö!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 32, 'Mutta hän sanoi heille: \"Minulla on syötävänä ruokaa, josta te ette tiedä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 33, 'Niin opetuslapset sanoivat keskenään: \"Lieneekö joku tuonut hänelle syötävää?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 34, 'Jeesus sanoi heille: \"Minun ruokani on se, että minä teen lähettäjäni tahdon ja täytän hänen tekonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 35, 'Ettekö sano: \'Vielä on neljä kuukautta, niin elonleikkuu joutuu\'? Katso, minä sanon teille: nostakaa silmänne ja katselkaa vainioita, kuinka ne ovat valjenneet leikattaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 36, 'Jo nyt saa leikkaaja palkan ja kokoaa hedelmää iankaikkiseen elämään, että kylväjä ja leikkaaja saisivat yhdessä iloita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 37, 'Sillä tässä on se sana tosi, että toinen on kylväjä, ja leikkaaja toinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 38, 'Minä olen lähettänyt teidät leikkaamaan sitä, josta te ette ole vaivaa nähneet; toiset ovat vaivan nähneet, ja te olette päässeet heidän vaivansa hedelmille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 39, 'Ja monet samarialaiset siitä kaupungista uskoivat häneen naisen puheen tähden, kun tämä todisti: \"Hän on sanonut minulle kaikki, mitä minä olen tehnyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 40, 'Kun nyt samarialaiset tulivat hänen luoksensa, pyysivät he häntä viipymään heidän luonaan; ja hän viipyi siellä kaksi päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 41, 'Ja vielä paljoa useammat uskoivat hänen sanansa tähden,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 42, 'ja he sanoivat naiselle: \"Emme enää usko sinun puheesi tähden, sillä me itse olemme kuulleet ja tiedämme, että tämä totisesti on maailman Vapahtaja\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 43, 'Mutta niiden kahden päivän kuluttua hän lähti sieltä Galileaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 44, 'Sillä Jeesus itse todisti, ettei profeetalla ole arvoa omassa isiensä maassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 45, 'Kun hän siis tuli Galileaan, ottivat galilealaiset hänet vastaan, koska olivat nähneet kaikki, mitä hän oli tehnyt Jerusalemissa juhlan aikana; sillä hekin olivat tulleet juhlille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 46, 'Niin hän tuli taas Galilean Kaanaan, jossa hän oli tehnyt veden viiniksi. Ja Kapernaumissa oli eräs kuninkaan virkamies, jonka poika sairasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 47, 'Kun hän kuuli Jeesuksen tulleen Juudeasta Galileaan, meni hän hänen luoksensa ja pyysi häntä tulemaan ja parantamaan hänen poikansa; sillä tämä oli kuolemaisillaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 48, 'Niin Jeesus sanoi hänelle: \"Ellette näe merkkejä ja ihmeitä, te ette usko\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 49, 'Kuninkaan virkamies sanoi hänelle: \"Herra, tule, ennenkuin minun lapseni kuolee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 50, 'Jeesus sanoi hänelle: \"Mene, sinun poikasi elää\". Ja mies uskoi sanan, jonka Jeesus sanoi hänelle, ja meni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 51, 'Ja jo hänen ollessaan paluumatkalla hänen palvelijansa kohtasivat hänet ja sanoivat, että hänen poikansa eli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 52, 'Niin hän tiedusteli heiltä, millä hetkellä hän oli alkanut toipua. Ja he sanoivat hänelle: \"Eilen seitsemännellä hetkellä kuume lähti hänestä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 53, 'Niin isä ymmärsi, että se oli tapahtunut sillä hetkellä, jolloin Jeesus oli sanonut hänelle: \"Sinun poikasi elää\". Ja hän uskoi, hän ja koko hänen huonekuntansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 54, 'Tämä oli taas tunnusteko, toinen, jonka Jeesus teki, tultuaan Juudeasta Galileaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Sen jälkeen oli juutalaisten juhla, ja Jeesus meni ylös Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Ja Jerusalemissa on Lammasportin luona lammikko, jonka nimi hebreankielellä on Betesda, ja sen reunalla on viisi pylväskäytävää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Niissä makasi suuri joukko sairaita, sokeita, rampoja ja näivetystautisia, jotka odottivat veden liikuttamista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Ja siellä oli mies, joka oli sairastanut kolmekymmentä kahdeksan vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Kun Jeesus näki hänen siinä makaavan ja tiesi hänen jo kauan aikaa sairastaneen, sanoi hän hänelle: \"Tahdotko tulla terveeksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Sairas vastasi hänelle: \"Herra, minulla ei ole ketään, joka veisi minut lammikkoon, kun vesi on kuohutettu; ja kun minä olen menemässä, astuu toinen sinne ennen minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Jeesus sanoi hänelle: \"Nouse, ota vuoteesi ja käy\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Ja mies tuli kohta terveeksi ja otti vuoteensa ja kävi. Mutta se päivä oli sapatti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Sentähden juutalaiset sanoivat parannetulle: \"Nyt on sapatti, eikä sinun ole lupa kantaa vuodetta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Hän vastasi heille: \"Se, joka teki minut terveeksi, sanoi minulle: \'Ota vuoteesi ja käy\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'He kysyivät häneltä: \"Kuka on se mies, joka sanoi sinulle: \'Ota vuoteesi ja käy\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Mutta parannettu ei tiennyt, kuka se oli; sillä Jeesus oli poistunut, kun siinä paikassa oli paljon kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Sen jälkeen Jeesus tapasi hänet pyhäkössä ja sanoi hänelle: \"Katso, sinä olet tullut terveeksi; älä enää syntiä tee, ettei sinulle jotakin pahempaa tapahtuisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 15, 'Niin mies meni ja ilmoitti juutalaisille, että Jeesus oli hänet terveeksi tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 16, 'Ja sentähden juutalaiset vainosivat Jeesusta, koska hän semmoista teki sapattina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 17, 'Mutta Jeesus vastasi heille: \"Minun Isäni tekee yhäti työtä, ja minä myös teen työtä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 18, 'Sentähden juutalaiset vielä enemmän tavoittelivat häntä tappaaksensa, kun hän ei ainoastaan kumonnut sapattia, vaan myös sanoi Jumalaa Isäksensä, tehden itsensä Jumalan vertaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 19, 'Niin Jeesus vastasi ja sanoi heille: \"Totisesti, totisesti minä sanon teille: Poika ei voi itsestänsä mitään tehdä, vaan ainoastaan sen, minkä hän näkee Isän tekevän; sillä mitä Isä tekee, sitä myös Poika samoin tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 20, 'Sillä Isä rakastaa Poikaa ja näyttää hänelle kaikki, mitä hän itse tekee; ja hän on näyttävä hänelle suurempia tekoja kuin nämä, niin että te ihmettelette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 21, 'Sillä niinkuin Isä herättää kuolleita ja tekee eläviksi, niin myös Poika tekee eläviksi, ketkä hän tahtoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 22, 'Sillä Isä ei myöskään tuomitse ketään, vaan hän on antanut kaiken tuomion Pojalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 23, 'että kaikki kunnioittaisivat Poikaa, niinkuin he kunnioittavat Isää. Joka ei kunnioita Poikaa, se ei kunnioita Isää, joka on hänet lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 24, 'Totisesti, totisesti minä sanon teille: joka kuulee minun sanani ja uskoo häneen, joka on minut lähettänyt, sillä on iankaikkinen elämä, eikä hän joudu tuomittavaksi, vaan on siirtynyt kuolemasta elämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 25, 'Totisesti, totisesti minä sanon teille: aika tulee ja on jo, jolloin kuolleet kuulevat Jumalan Pojan äänen, ja jotka sen kuulevat ne saavat elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 26, 'Sillä niinkuin Isällä on elämä itsessänsä, niin hän on antanut elämän myös Pojalle, niin että myös hänellä on elämä itsessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 27, 'Ja hän on antanut hänelle vallan tuomita, koska hän on Ihmisen Poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 28, 'Älkää ihmetelkö tätä, sillä hetki tulee, jolloin kaikki, jotka haudoissa ovat, kuulevat hänen äänensä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 29, 'ja tulevat esiin, ne, jotka ovat hyvää tehneet, elämän ylösnousemukseen, mutta ne, jotka ovat pahaa tehneet, tuomion ylösnousemukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 30, 'En minä itsestäni voi mitään tehdä. Niinkuin minä kuulen, niin minä tuomitsen; ja minun tuomioni on oikea, sillä minä en kysy omaa tahtoani, vaan hänen tahtoaan, joka on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 31, 'Jos minä itsestäni todistan, ei minun todistukseni ole pätevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 32, 'On toinen, joka todistaa minusta, ja minä tiedän, että se todistus, jonka hän minusta todistaa, on pätevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 33, 'Te lähetitte lähettiläät Johanneksen luo, ja hän todisti sen, mikä totta on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 34, 'Mutta minä en ota ihmiseltä todistusta, vaan puhun tämän, että te pelastuisitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 35, 'Hän oli palava ja loistava lamppu, mutta te tahdoitte ainoastaan hetken iloitella hänen valossansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 36, 'Mutta minulla on todistus, joka on suurempi kuin Johanneksen; sillä ne teot, jotka Isä on antanut minun täytettävikseni, ne teot, jotka minä teen, todistavat minusta, että Isä on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 37, 'Ja Isä, joka on minut lähettänyt, hän on todistanut minusta. Te ette ole koskaan kuulleet hänen ääntänsä ettekä nähneet hänen muotoansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 38, 'eikä teillä ole hänen sanaansa teissä pysyväisenä; sillä te ette usko sitä, jonka hän on lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 39, 'Te tutkitte kirjoituksia, sillä teillä on mielestänne niissä iankaikkinen elämä, ja ne juuri todistavat minusta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 40, 'ja te ette tahdo tulla minun tyköni, että saisitte elämän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 41, 'En minä ota vastaan kunniaa ihmisiltä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 42, 'mutta minä tunnen teidät, ettei teillä ole Jumalan rakkautta itsessänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 43, 'Minä olen tullut Isäni nimessä, ja te ette ota minua vastaan; jos toinen tulee omassa nimessään, niin hänet te otatte vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 44, 'Kuinka te voisitte uskoa, te, jotka otatte vastaan kunniaa toinen toiseltanne, ettekä etsi sitä kunniaa, mikä tulee häneltä, joka yksin on Jumala?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 45, 'Älkää luulko, että minä olen syyttävä teitä Isän tykönä; teillä on syyttäjänne, Mooses, johon te panette toivonne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 46, 'Sillä jos te Moosesta uskoisitte, niin te uskoisitte minua; sillä minusta hän on kirjoittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 47, 'Mutta jos te ette usko hänen kirjoituksiaan, kuinka te uskoisitte minun sanojani?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 1, 'Sen jälkeen Jeesus meni Galileaan, se on Tiberiaan, järven tuolle puolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 2, 'Ja häntä seurasi paljon kansaa, koska he näkivät ne tunnusteot, joita hän teki sairaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 3, 'Ja Jeesus nousi vuorelle ja istui sinne opetuslapsinensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 4, 'Ja pääsiäinen, juutalaisten juhla, oli lähellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 5, 'Kun Jeesus nosti silmänsä ja näki paljon kansaa tulevan tykönsä, sanoi hän Filippukselle: \"Mistä ostamme leipää näiden syödä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 6, 'Mutta sen hän sanoi koetellakseen häntä, sillä itse hän tiesi, mitä aikoi tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 7, 'Filippus vastasi hänelle: \"Eivät kahdensadan denarin leivät heille riittäisi, niin että kukin saisi edes vähän\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 8, 'Niin toinen hänen opetuslapsistansa, Andreas, Simon Pietarin veli, sanoi hänelle:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 9, '\"Täällä on poikanen, jolla on viisi ohraleipää ja kaksi kalaa, mutta mitä ne ovat näin monelle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 10, 'Jeesus sanoi: \"Asettakaa kansa aterioimaan\". Ja siinä paikassa oli paljon ruohoa. Niin miehet, luvultaan noin viisituhatta, laskeutuivat maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 11, 'Ja Jeesus otti leivät ja kiitti ja jakeli istuville; samoin kaloistakin, niin paljon kuin he tahtoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 12, 'Mutta kun he olivat ravitut, sanoi hän opetuslapsillensa: \"Kootkaa tähteeksi jääneet palaset, ettei mitään joutuisi hukkaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 13, 'Niin he kokosivat ne ja täyttivät kaksitoista vakkaa palasilla, mitkä olivat viidestä ohraleivästä jääneet tähteeksi niiltä, jotka olivat aterioineet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 14, 'Kun nyt ihmiset näkivät sen tunnusteon, jonka Jeesus oli tehnyt, sanoivat he: \"Tämä on totisesti se profeetta, joka oli maailmaan tuleva\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 15, 'Kun nyt Jeesus huomasi, että he aikoivat tulla ja väkisin ottaa hänet, tehdäkseen hänet kuninkaaksi, väistyi hän taas pois vuorelle, hän yksinänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 16, 'Mutta kun ilta tuli, menivät hänen opetuslapsensa alas järven rantaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 17, 'astuivat venheeseen ja lähtivät menemään järven toiselle puolelle, Kapernaumiin. Ja oli jo tullut pimeä, eikä Jeesus ollut vielä saapunut heidän luokseen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 18, 'ja järvi aaltoili ankarasti kovan tuulen puhaltaessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 19, 'Kun he olivat soutaneet noin viisikolmatta tai kolmekymmentä vakomittaa, näkivät he Jeesuksen kävelevän järven päällä ja tulevan lähelle venhettä; ja he peljästyivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 20, 'Mutta hän sanoi heille: \"Minä se olen; älkää peljätkö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 21, 'Niin he tahtoivat ottaa hänet venheeseen, ja kohta venhe saapui sen maan rantaan, jonne he olivat matkalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 22, 'Seuraavana päivänä kansa yhä vielä oli järven toisella puolella, sillä he olivat nähneet, ettei siellä ollut muuta venhettä kuin se yksi ja ettei Jeesus mennyt opetuslastensa kanssa venheeseen, vaan että hänen opetuslapsensa lähtivät yksinään pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 23, 'Kuitenkin oli muita venheitä tullut Tiberiaasta lähelle sitä paikkaa, jossa he olivat syöneet leipää, sittenkuin Herra oli lausunut kiitoksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 24, 'Kun siis kansa näki, ettei Jeesus ollut siellä eivätkä hänen opetuslapsensa, astuivat hekin venheisiin ja menivät Kapernaumiin ja etsivät Jeesusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 25, 'Ja kun he löysivät hänet järven toiselta puolelta, sanoivat he hänelle: \"Rabbi, milloin tulit tänne?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 26, 'Jeesus vastasi heille ja sanoi: \"Totisesti, totisesti minä sanon teille: ette te minua sentähden etsi, että olette nähneet tunnustekoja, vaan sentähden, että saitte syödä niitä leipiä ja tulitte ravituiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 27, 'Älkää hankkiko sitä ruokaa, joka katoaa, vaan sitä ruokaa, joka pysyy hamaan iankaikkiseen elämään ja jonka Ihmisen Poika on teille antava; sillä häneen on Isä, Jumala itse, sinettinsä painanut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 28, 'Niin he sanoivat hänelle: \"Mitä meidän pitää tekemän, että me Jumalan tekoja tekisimme?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 29, 'Jeesus vastasi ja sanoi heille: \"Se on Jumalan teko, että te uskotte häneen, jonka Jumala on lähettänyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 30, 'He sanoivat hänelle: \"Minkä tunnusteon sinä sitten teet, että me näkisimme sen ja uskoisimme sinua? Minkä teon sinä teet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 31, 'Meidän isämme söivät mannaa erämaassa, niinkuin kirjoitettu on: \'Hän antoi leipää taivaasta heille syötäväksi\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 32, 'Niin Jeesus sanoi heille: \"Totisesti, totisesti minä sanon teille: ei Mooses antanut teille sitä leipää taivaasta, vaan minun Isäni antaa teille taivaasta totisen leivän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 33, 'Sillä Jumalan leipä on se, joka tulee alas taivaasta ja antaa maailmalle elämän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 34, 'Niin he sanoivat hänelle: \"Herra, anna meille aina sitä leipää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 35, 'Jeesus sanoi heille: \"Minä olen elämän leipä; joka tulee minun tyköni, se ei koskaan isoa, ja joka uskoo minuun, se ei koskaan janoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 36, 'Mutta minä olen sanonut teille, että te olette nähneet minut, ettekä kuitenkaan usko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 37, 'Kaikki, minkä Isä antaa minulle, tulee minun tyköni; ja sitä, joka minun tyköni tulee, minä en heitä ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 38, 'Sillä minä olen tullut taivaasta, en tekemään omaa tahtoani, vaan hänen tahtonsa, joka on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 39, 'Ja minun lähettäjäni tahto on se, että minä kaikista niistä, jotka hän on minulle antanut, en kadota yhtäkään, vaan herätän heidät viimeisenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 40, 'Sillä minun Isäni tahto on se, että jokaisella, joka näkee Pojan ja uskoo häneen, on iankaikkinen elämä; ja minä herätän hänet viimeisenä päivänä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 41, 'Niin juutalaiset nurisivat häntä vastaan, koska hän sanoi: \"Minä olen se leipä, joka on tullut alas taivaasta\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 42, 'ja he sanoivat: \"Eikö tämä ole Jeesus, Joosefin poika, jonka isän ja äidin me tunnemme? Kuinka hän sitten sanoo: \'Minä olen tullut alas taivaasta\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 43, 'Jeesus vastasi ja sanoi heille: \"Älkää nurisko keskenänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 44, 'Ei kukaan voi tulla minun tyköni, ellei Isä, joka on minut lähettänyt, häntä vedä; ja minä herätän hänet viimeisenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 45, 'Profeetoissa on kirjoitettuna: \'Ja he tulevat kaikki Jumalan opettamiksi\'. Jokainen, joka on Isältä kuullut ja oppinut, tulee minun tyköni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 46, 'Ei niin, että kukaan olisi Isää nähnyt; ainoastaan hän, joka on Jumalasta, on nähnyt Isän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 47, 'Totisesti, totisesti minä sanon teille: joka uskoo, sillä on iankaikkinen elämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 48, 'Minä olen elämän leipä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 49, 'Teidän isänne söivät mannaa erämaassa, ja he kuolivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 50, 'Mutta tämä on se leipä, joka tulee alas taivaasta, että se, joka sitä syö, ei kuolisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 51, 'Minä olen se elävä leipä, joka on tullut alas taivaasta. Jos joku syö tätä leipää, hän elää iankaikkisesti. Ja se leipä, jonka minä annan, on minun lihani, maailman elämän puolesta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 52, 'Silloin juutalaiset riitelivät keskenään sanoen: \"Kuinka tämä voi antaa lihansa meille syötäväksi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 53, 'Niin Jeesus sanoi heille: \"Totisesti, totisesti minä sanon teille: ellette syö Ihmisen Pojan lihaa ja juo hänen vertansa, ei teillä ole elämää itsessänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 54, 'Joka syö minun lihani ja juo minun vereni, sillä on iankaikkinen elämä, ja minä herätän hänet viimeisenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 55, 'Sillä minun lihani on totinen ruoka, ja minun vereni on totinen juoma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 56, 'Joka syö minun lihani ja juo minun vereni, se pysyy minussa, ja minä hänessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 57, 'Niinkuin Isä, joka elää, on minut lähettänyt, ja minä elän Isän kautta, niin myös se, joka minua syö, elää minun kauttani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 58, 'Tämä on se leipä, joka tuli alas taivaasta. Ei ole, niinkuin oli teidän isienne: he söivät ja kuolivat; joka tätä leipää syö, se elää iankaikkisesti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 59, 'Tämän hän puhui synagoogassa opettaessaan Kapernaumissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 60, 'Niin monet hänen opetuslapsistansa, sen kuultuaan, sanoivat: \"Tämä on kova puhe, kuka voi sitä kuulla?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 61, 'Mutta kun Jeesus sydämessään tiesi, että hänen opetuslapsensa siitä nurisivat, sanoi hän heille: \"Loukkaako tämä teitä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 62, 'Mitä sitten, jos saatte nähdä Ihmisen Pojan nousevan sinne, missä hän oli ennen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 63, 'Henki on se, joka eläväksi tekee; ei liha mitään hyödytä. Ne sanat, jotka minä olen teille puhunut, ovat henki ja ovat elämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 64, 'Mutta teissä on muutamia, jotka eivät usko.\" Sillä Jeesus tiesi alusta asti, ketkä ne olivat, jotka eivät uskoneet, ja kuka se oli, joka oli kavaltava hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 65, 'Ja hän sanoi: \"Sentähden minä olen sanonut teille, ettei kukaan voi tulla minun tyköni, ellei minun Isäni sitä hänelle anna\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 66, 'Tämän tähden monet hänen opetuslapsistaan vetäytyivät pois eivätkä enää vaeltaneet hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 67, 'Niin Jeesus sanoi niille kahdelletoista: \"Tahdotteko tekin mennä pois?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 68, 'Simon Pietari vastasi hänelle: \"Herra, kenen tykö me menisimme? Sinulla on iankaikkisen elämän sanat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 69, 'ja me uskomme ja ymmärrämme, että sinä olet Jumalan Pyhä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 70, 'Jeesus vastasi heille: \"Enkö minä ole valinnut teitä, te kaksitoista? Ja yksi teistä on perkele.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 6, 71, 'Mutta sen hän sanoi Juudaasta, Simon Iskariotin pojasta; sillä tämä oli hänet kavaltava ja oli yksi niistä kahdestatoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 1, 'Ja sen jälkeen Jeesus vaelsi ympäri Galileassa; sillä hän ei tahtonut vaeltaa Juudeassa, koska juutalaiset tavoittelivat häntä tappaaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 2, 'Ja juutalaisten juhla, lehtimajanjuhla, oli lähellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 3, 'Niin hänen veljensä sanoivat hänelle: \"Lähde täältä ja mene Juudeaan, että myös sinun opetuslapsesi näkisivät sinun tekosi, joita sinä teet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 4, 'sillä ei kukaan, joka itse tahtoo tulla julki, tee mitään salassa. Koska sinä näitä tekoja teet, niin ilmoita itsesi maailmalle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 5, 'Sillä hänen veljensäkään eivät häneen uskoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 6, 'Niin Jeesus sanoi heille: \"Minun aikani ei ole vielä tullut; mutta teille aika on aina sovelias.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 7, 'Teitä ei maailma voi vihata, mutta minua se vihaa, sillä minä todistan siitä, että sen teot ovat pahat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 8, 'Menkää te ylös juhlille; minä en vielä mene näille juhlille, sillä minun aikani ei ole vielä täyttynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 9, 'Tämän hän sanoi heille ja jäi Galileaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 10, 'Mutta kun hänen veljensä olivat menneet juhlille, silloin hänkin meni sinne, ei julki, vaan ikäänkuin salaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 11, 'Niin juutalaiset etsivät häntä juhlan aikana ja sanoivat: \"Missä hän on?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 12, 'Ja hänestä oli paljon kiistelyä kansassa; muutamat sanoivat: \"Hän on hyvä\", mutta toiset sanoivat: \"Ei ole, vaan hän villitsee kansan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 13, 'Ei kuitenkaan kukaan puhunut hänestä julkisesti, koska he pelkäsivät juutalaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 14, 'Mutta kun jo puoli juhlaa oli kulunut, meni Jeesus ylös pyhäkköön ja opetti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 15, 'Niin juutalaiset ihmettelivät ja sanoivat: \"Kuinka tämä osaa kirjoituksia, vaikkei ole oppia saanut?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 16, 'Jeesus vastasi heille ja sanoi: \"Minun oppini ei ole minun, vaan hänen, joka on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 17, 'Jos joku tahtoo tehdä hänen tahtonsa, tulee hän tuntemaan, onko tämä oppi Jumalasta, vai puhunko minä omiani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 18, 'Joka omiaan puhuu, se pyytää omaa kunniaansa, mutta joka pyytää lähettäjänsä kunniaa, se on totinen, eikä hänessä ole vääryyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 19, 'Eikö Mooses ole antanut teille lakia? Ja kukaan teistä ei lakia täytä. Miksi tavoittelette minua tappaaksenne?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 20, 'Kansa vastasi: \"Sinussa on riivaaja; kuka sinua tavoittelee tappaaksensa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 21, 'Jeesus vastasi ja sanoi heille: \"Yhden teon minä tein, ja te kaikki kummastelette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 22, 'Mooses antoi teille ympärileikkauksen-ei niin, että se olisi Moosekselta, vaan se on isiltä-ja sapattinakin te ympärileikkaatte ihmisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 23, 'Sentähden: jos ihminen saa ympärileikkauksen sapattina, ettei Mooseksen lakia rikottaisi, miksi te olette vihoissanne minulle siitä, että minä tein koko ihmisen terveeksi sapattina?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 24, 'Älkää tuomitko näön mukaan, vaan tuomitkaa oikea tuomio.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 25, 'Niin muutamat jerusalemilaisista sanoivat: \"Eikö tämä ole se, jota he tavoittelevat tappaaksensa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 26, 'Ja katso, hän puhuu vapaasti, eivätkä he sano hänelle mitään. Olisivatko hallitusmiehet tosiaan saaneet tietoonsa, että tämä on Kristus?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 27, 'Kuitenkin, me tiedämme, mistä tämä on; mutta kun Kristus tulee, niin ei kukaan tiedä, mistä hän on.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 28, 'Niin Jeesus puhui pyhäkössä suurella äänellä, opetti ja sanoi: \"Te tunnette minut ja tiedätte, mistä minä olen; ja itsestäni minä en ole tullut, vaan hän, joka minut on lähettänyt, on oikea lähettäjä, ja häntä te ette tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 29, 'Minä tunnen hänet, sillä hänestä minä olen, ja hän on minut lähettänyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 30, 'Niin heillä oli halu ottaa hänet kiinni; mutta ei kukaan käynyt häneen käsiksi, sillä hänen hetkensä ei ollut vielä tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 31, 'Mutta monet kansasta uskoivat häneen ja sanoivat: \"Kun Kristus tulee, tehneekö hän enemmän tunnustekoja, kuin tämä on tehnyt?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 32, 'Fariseukset kuulivat kansan näin kiistelevän hänestä; niin ylipapit ja fariseukset lähettivät palvelijoita ottamaan häntä kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 33, 'Mutta Jeesus sanoi: \"Minä olen vielä vähän aikaa teidän kanssanne, ja sitten minä menen pois hänen tykönsä, joka on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 34, 'Silloin te etsitte minua, mutta ette löydä; ja missä minä olen, sinne te ette voi tulla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 35, 'Niin juutalaiset sanoivat keskenään: \"Minne tämä aikoo mennä, koska emme voi löytää häntä? Eihän vain aikone mennä niiden luo, jotka asuvat hajallaan kreikkalaisten keskellä, ja opettaa kreikkalaisia?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 36, 'Mitä tämä sana on, jonka hän sanoi: \'Te etsitte minua, mutta ette löydä\', ja: \'Missä minä olen, sinne te ette voi tulla\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 37, 'Mutta juhlan viimeisenä, suurena päivänä Jeesus seisoi ja huusi ja sanoi: \"Jos joku janoaa, niin tulkoon minun tyköni ja juokoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 38, 'Joka uskoo minuun, hänen sisimmästään on, niinkuin Raamattu sanoo, juokseva elävän veden virrat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 39, 'Mutta sen hän sanoi Hengestä, joka niiden piti saaman, jotka uskoivat häneen; sillä Henki ei ollut vielä tullut, koska Jeesus ei vielä ollut kirkastettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 40, 'Niin muutamat kansasta, kuultuaan nämä sanat, sanoivat: \"Tämä on totisesti se profeetta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 41, 'Toiset sanoivat: \"Tämä on Kristus\". Mutta toiset sanoivat: \"Ei suinkaan Kristus tule Galileasta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 42, 'Eikö Raamattu sano, että Kristus on oleva Daavidin jälkeläisiä ja tuleva pienestä Beetlehemin kaupungista, jossa Daavid oli?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 43, 'Niin syntyi kansassa eripuraisuutta hänen tähtensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 44, 'Ja muutamat heistä tahtoivat ottaa hänet kiinni. Mutta ei kukaan käynyt häneen käsiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 45, 'Niin palvelijat palasivat ylipappien ja fariseusten luo, ja nämä sanoivat heille: \"Miksi ette tuoneet häntä tänne?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 46, 'Palvelijat vastasivat: \"Ei ole koskaan ihminen puhunut niin, kuin se mies puhuu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 47, 'Niin fariseukset vastasivat heille: \"Oletteko tekin eksytetyt?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 48, 'Onko kukaan hallitusmiehistä uskonut häneen tai kukaan fariseuksista?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 49, 'Mutta tuo kansa, joka ei lakia tunne, on kirottu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 50, 'Niin Nikodeemus, joka ennen oli käynyt Jeesuksen luona ja joka oli yksi heistä, sanoi heille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 51, '\"Tuomitseeko lakimme ketään, ennenkuin häntä on kuulusteltu ja saatu tietää, mitä hän on tehnyt?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 52, 'He vastasivat ja sanoivat hänelle: \"Oletko sinäkin Galileasta? Tutki ja näe, ettei Galileasta nouse profeettaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 7, 53, 'Ja he menivät kukin kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 1, 'Mutta Jeesus meni Öljymäelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 2, 'Ja varhain aamulla hän taas saapui pyhäkköön, ja kaikki kansa tuli hänen luoksensa; ja hän istuutui ja opetti heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 3, 'Silloin kirjanoppineet ja fariseukset toivat hänen luoksensa aviorikoksesta kiinniotetun naisen, asettivat hänet keskelle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 4, 'ja sanoivat Jeesukselle: \"Opettaja, tämä nainen on tavattu itse teosta, aviorikosta tekemästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 5, 'Ja Mooses on laissa antanut meille käskyn, että tuommoiset on kivitettävä. Mitäs sinä sanot?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 6, 'Mutta sen he sanoivat kiusaten häntä, päästäkseen häntä syyttämään. Silloin Jeesus kumartui alas ja kirjoitti sormellaan maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 7, 'Mutta kun he yhä edelleen kysyivät häneltä, ojensi hän itsensä ja sanoi heille: \"Joka teistä on synnitön, se heittäköön häntä ensimmäisenä kivellä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 8, 'Ja taas hän kumartui alas ja kirjoitti maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 9, 'Kun he tämän kuulivat ja heidän omatuntonsa todisti heidät syyllisiksi, menivät he pois, toinen toisensa perästä, vanhimmista alkaen viimeisiin asti; ja siihen jäi ainoastaan Jeesus sekä nainen, joka seisoi hänen edessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 10, 'Ja kun Jeesus ojensi itsensä eikä nähnyt ketään muuta kuin naisen, sanoi hän hänelle: \"Nainen, missä ne ovat, sinun syyttäjäsi? Eikö kukaan ole sinua tuominnut?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 11, 'Hän vastasi: \"Herra, ei kukaan\". Niin Jeesus sanoi hänelle: \"En minäkään sinua tuomitse; mene, äläkä tästedes enää syntiä tee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 12, 'Niin Jeesus taas puhui heille sanoen: \"Minä olen maailman valkeus; joka minua seuraa, se ei pimeydessä vaella, vaan hänellä on oleva elämän valkeus\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 13, 'Niin fariseukset sanoivat hänelle: \"Sinä todistat itsestäsi; sinun todistuksesi ei ole pätevä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 14, 'Jeesus vastasi ja sanoi heille: \"Vaikka minä todistankin itsestäni, on todistukseni pätevä, sillä minä tiedän, mistä minä olen tullut ja mihin minä menen; mutta te ette tiedä, mistä minä tulen, ettekä, mihin minä menen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 15, 'Te tuomitsette lihan mukaan; minä en tuomitse ketään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 16, 'Ja vaikka minä tuomitsisinkin, niin minun tuomioni olisi oikea, sillä minä en ole yksinäni, vaan minä ja hän, joka on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 17, 'Onhan teidän laissannekin kirjoitettuna, että kahden ihmisen todistus on pätevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 18, 'Minä olen se, joka todistan itsestäni, ja minusta todistaa myös Isä, joka on minut lähettänyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 19, 'Niin he sanoivat hänelle: \"Missä sinun isäsi on?\" Jeesus vastasi: \"Te ette tunne minua ettekä minun Isääni; jos te tuntisitte minut, niin te tuntisitte myös minun Isäni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 20, 'Nämä sanat Jeesus puhui uhriarkun ääressä, opettaessaan pyhäkössä; eikä kukaan ottanut häntä kiinni, sillä hänen hetkensä ei ollut vielä tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 21, 'Niin Jeesus taas sanoi heille: \"Minä menen pois, ja te etsitte minua, ja te kuolette syntiinne. Mihin minä menen, sinne te ette voi tulla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 22, 'Niin juutalaiset sanoivat: \"Ei kai hän aikone tappaa itseänsä, koska sanoo: \'Mihin minä menen, sinne te ette voi tulla\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 23, 'Ja hän sanoi heille: \"Te olette alhaalta, minä olen ylhäältä; te olette tästä maailmasta, minä en ole tästä maailmasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 24, 'Sentähden minä sanoin teille, että te kuolette synteihinne; sillä ellette usko minua siksi, joka minä olen, niin te kuolette synteihinne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 25, 'Niin he sanoivat hänelle: \"Kuka sinä olet?\" Jeesus sanoi heille: \"Juuri se, mitä minä puhunkin teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 26, 'Paljon on minulla teistä puhuttavaa ja teissä tuomittavaa; mutta hän, joka on minut lähettänyt, on totinen, ja minkä minä olen kuullut häneltä, sen minä puhun maailman kuulla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 27, 'Mutta he eivät ymmärtäneet, että hän puhui heille Isästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 28, 'Niin Jeesus sanoi heille: \"Kun olette ylentäneet Ihmisen Pojan, silloin te ymmärrätte, että minä olen se, joka minä olen, ja etten minä itsestäni tee mitään, vaan puhun tätä sen mukaan, kuin minun Isäni on minulle opettanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 29, 'Ja hän, joka on minut lähettänyt, on minun kanssani; hän ei ole jättänyt minua yksinäni, koska minä aina teen sitä, mikä hänelle on otollista.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 30, 'Kun hän näin puhui, uskoivat monet häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 31, 'Niin Jeesus sanoi niille juutalaisille, jotka uskoivat häneen: \"Jos te pysytte minun sanassani, niin te totisesti olette minun opetuslapsiani;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 32, 'ja te tulette tuntemaan totuuden, ja totuus on tekevä teidät vapaiksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 33, 'He vastasivat hänelle: \"Me olemme Aabrahamin jälkeläisiä emmekä ole koskaan olleet kenenkään orjia. Kuinka sinä sitten sanot: \'Te tulette vapaiksi\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 34, 'Jeesus vastasi heille: \"Totisesti, totisesti minä sanon teille: jokainen, joka tekee syntiä, on synnin orja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 35, 'Mutta orja ei pysy talossa iäti; Poika pysyy iäti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 36, 'Jos siis Poika tekee teidät vapaiksi, niin te tulette todellisesti vapaiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 37, 'Minä tiedän, että te olette Aabrahamin jälkeläisiä; mutta te tavoittelette minua tappaaksenne, koska minun sanani ei saa tilaa teissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 38, 'Minä puhun, mitä minä olen nähnyt Isäni tykönä; niin tekin teette, mitä olette kuulleet omalta isältänne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 39, 'He vastasivat ja sanoivat hänelle: \"Aabraham on meidän isämme\". Jeesus sanoi heille: \"Jos olisitte Aabrahamin lapsia, niin te tekisitte Aabrahamin tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 40, 'Mutta nyt te tavoittelette minua tappaaksenne, miestä, joka on puhunut teille totuuden, jonka hän on kuullut Jumalalta. Niin ei Aabraham tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 41, 'Te teette isänne tekoja.\" He sanoivat hänelle: \"Me emme ole aviorikoksesta syntyneitä; meillä on yksi Isä, Jumala\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 42, 'Jeesus sanoi heille: \"Jos Jumala olisi teidän Isänne, niin te rakastaisitte minua, sillä minä olen Jumalasta lähtenyt ja tullut; en minä ole itsestäni tullut, vaan hän on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 43, 'Minkätähden te ette ymmärrä minun puhettani? Sentähden, että te ette kärsi kuulla minun sanaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 44, 'Te olette isästä perkeleestä, ja isänne himoja te tahdotte noudattaa. Hän on ollut murhaaja alusta asti, ja totuudessa hän ei pysy, koska hänessä ei totuutta ole. Kun hän puhuu valhetta, niin hän puhuu omaansa, sillä hän on valhettelija ja sen isä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 45, 'Mutta minua te ette usko, sentähden että minä sanon totuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 46, 'Kuka teistä voi näyttää minut syypääksi syntiin? Jos minä totuutta puhun, miksi ette minua usko?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 47, 'Joka on Jumalasta, se kuulee Jumalan sanat. Sentähden te ette kuule, koska ette ole Jumalasta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 48, 'Niin juutalaiset vastasivat ja sanoivat hänelle: \"Emmekö ole oikeassa, kun sanomme, että sinä olet samarialainen ja että sinussa on riivaaja?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 49, 'Jeesus vastasi: \"Minussa ei ole riivaajaa, vaan minä kunnioitan Isääni, ja te häpäisette minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 50, 'Mutta minä en etsi omaa kunniaani; yksi on, joka etsii ja tuomitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 51, 'Totisesti, totisesti minä sanon teille: jos joku pitää minun sanani, hän ei ikinä näe kuolemaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 52, 'Juutalaiset sanoivat hänelle: \"Nyt me ymmärrämme, että sinussa on riivaaja. Aabraham on kuollut ja profeetat, ja sinä sanot: \'Jos joku pitää minun sanani, hän ei ikinä maista kuolemaa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 53, 'Oletko sinä suurempi kuin isämme Aabraham, joka on kuollut? Ja profeetat ovat kuolleet; keneksi sinä itsesi teet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 54, 'Jeesus vastasi: \"Jos minä itse itselleni otan kunnian, niin minun kunniani ei ole mitään. Minun Isäni on se, joka minulle kunnian antaa, hän, josta te sanotte: \'Hän on meidän Jumalamme\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 55, 'ettekä tunne häntä; mutta minä tunnen hänet. Ja jos sanoisin, etten tunne häntä, niin minä olisin valhettelija niinkuin tekin; mutta minä tunnen hänet ja pidän hänen sanansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 56, 'Aabraham, teidän isänne, riemuitsi siitä, että hän oli näkevä minun päiväni; ja hän näki sen ja iloitsi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 57, 'Niin juutalaiset sanoivat hänelle: \"Et ole vielä viidenkymmenen vuoden vanha, ja olet nähnyt Aabrahamin!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 58, 'Jeesus sanoi heille: \"Totisesti, totisesti minä sanon teille: ennenkuin Aabraham syntyi, olen minä ollut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 8, 59, 'Silloin he poimivat kiviä heittääksensä häntä niillä; mutta Jeesus lymysi ja lähti pyhäköstä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 1, 'Ja ohi kulkiessaan hän näki miehen, joka syntymästään saakka oli ollut sokea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 2, 'Ja hänen opetuslapsensa kysyivät häneltä sanoen: \"Rabbi, kuka teki syntiä, tämäkö vai hänen vanhempansa, että hänen piti sokeana syntymän?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 3, 'Jeesus vastasi: \"Ei tämä tehnyt syntiä eivätkä hänen vanhempansa, vaan Jumalan tekojen piti tuleman hänessä julki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 4, 'Niin kauan kuin päivä on, tulee meidän tehdä hänen tekojansa, joka on minut lähettänyt; tulee yö, jolloin ei kukaan voi työtä tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 5, 'Niin kauan kuin minä maailmassa olen, olen minä maailman valkeus.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 6, 'Tämän sanottuaan hän sylki maahan ja teki syljestä tahtaan ja siveli tahtaan hänen silmilleen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 7, 'ja sanoi hänelle: \"Mene ja peseydy Siiloan lammikossa\" -se on käännettynä: lähetetty. -Niin hän meni ja peseytyi ja palasi näkevänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 8, 'Silloin naapurit ja ne, jotka ennen olivat nähneet hänet kerjääjänä, sanoivat: \"Eikö tämä ole se, joka istui ja kerjäsi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 9, 'Toiset sanoivat: \"Hän se on\", toiset sanoivat: \"Ei ole, vaan hän on hänen näköisensä\". Hän itse sanoi: \"Minä se olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 10, 'Niin he sanoivat hänelle: \"Miten sinun silmäsi ovat auenneet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 11, 'Hän vastasi: \"Se mies, jota kutsutaan Jeesukseksi, teki tahtaan ja voiteli minun silmäni ja sanoi minulle: \'Mene ja peseydy Siiloan lammikossa\'; niin minä menin ja peseydyin ja sain näköni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 12, 'He sanoivat hänelle: \"Missä hän on?\" Hän vastasi: \"En tiedä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 13, 'Niin he veivät hänet, joka ennen oli ollut sokea, fariseusten luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 14, 'Ja se päivä, jona Jeesus teki tahtaan ja avasi hänen silmänsä, oli sapatti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 15, 'Niin myöskin fariseukset kysyivät häneltä, miten hän oli saanut näkönsä. Ja hän sanoi heille: \"Hän siveli tahtaan minun silmilleni, ja minä peseydyin, ja nyt minä näen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 16, 'Niin muutamat fariseuksista sanoivat: \"Se mies ei ole Jumalasta, koska hän ei pidä sapattia\". Toiset sanoivat: \"Kuinka voi syntinen ihminen tehdä senkaltaisia tunnustekoja?\" Ja he olivat keskenänsä eri mieltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 17, 'Niin he taas sanoivat sokealle: \"Mitä sinä sanot hänestä, koskapa hän avasi sinun silmäsi?\" Ja hän sanoi: \"Hän on profeetta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 18, 'Mutta juutalaiset eivät uskoneet hänestä, että hän oli ollut sokea ja saanut näkönsä, ennenkuin kutsuivat sen näkönsä saaneen vanhemmat');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 19, 'ja kysyivät heiltä sanoen: \"Onko tämä teidän poikanne, jonka sanotte sokeana syntyneen? Kuinka hän sitten nyt näkee?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 20, 'Hänen vanhempansa vastasivat ja sanoivat: \"Me tiedämme, että tämä on meidän poikamme ja että hän on sokeana syntynyt;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 21, 'mutta kuinka hän nyt näkee, emme tiedä; emme myöskään tiedä, kuka on avannut hänen silmänsä. Kysykää häneltä; hänellä on kyllin ikää, puhukoon itse puolestansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 22, 'Näin hänen vanhempansa sanoivat, koska pelkäsivät juutalaisia. Sillä juutalaiset olivat jo sopineet keskenään, että se, joka tunnusti hänet Kristukseksi, oli erotettava synagoogasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 23, 'Sentähden hänen vanhempansa sanoivat: \"Hänellä on kyllin ikää, kysykää häneltä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 24, 'Niin he kutsuivat toistamiseen miehen, joka oli ollut sokea, ja sanoivat hänelle: \"Anna kunnia Jumalalle; me tiedämme, että se mies on syntinen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 25, 'Hän vastasi: \"Onko hän syntinen, sitä en tiedä; sen vain tiedän, että minä, joka olin sokea, nyt näen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 26, 'Niin he sanoivat hänelle: \"Mitä hän sinulle teki? Miten hän avasi sinun silmäsi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 27, 'Hän vastasi heille: \"Johan minä teille sanoin, ettekä te kuulleet. Miksi taas tahdotte sitä kuulla? Tahdotteko tekin ruveta hänen opetuslapsiksensa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 28, 'Niin he herjasivat häntä ja sanoivat: \"Sinä olet hänen opetuslapsensa, mutta me olemme Mooseksen opetuslapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 29, 'Me tiedämme Jumalan puhuneen Moosekselle, mutta mistä tämä on, sitä emme tiedä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 30, 'Mies vastasi ja sanoi heille: \"Sehän tässä on ihmeellistä, että te ette tiedä, mistä hän on, ja kuitenkin hän on avannut minun silmäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 31, 'Me tiedämme, ettei Jumala kuule syntisiä; vaan joka on jumalaapelkääväinen ja tekee hänen tahtonsa, sitä hän kuulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 32, 'Ei ole maailman alusta kuultu, että kukaan on avannut sokeana syntyneen silmät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 33, 'Jos hän ei olisi Jumalasta, ei hän voisi mitään tehdä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 34, 'He vastasivat ja sanoivat hänelle: \"Sinä olet kokonaan synneissä syntynyt, ja sinä tahdot opettaa meitä!\" Ja he ajoivat hänet ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 35, 'Ja Jeesus sai kuulla heidän ajaneen hänet ulos; ja hänet tavatessaan hän sanoi hänelle: \"Uskotko sinä Jumalan Poikaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 36, 'Hän vastasi ja sanoi: \"Herra, kuka hän on, että minä häneen uskoisin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 37, 'Jeesus sanoi hänelle: \"Sinä olet hänet nähnyt, ja hän on se, joka sinun kanssasi puhuu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 38, 'Niin hän sanoi: \"Herra, minä uskon\"; ja hän kumartaen rukoili häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 39, 'Ja Jeesus sanoi: \"Tuomioksi minä olen tullut tähän maailmaan, että ne, jotka eivät näe, näkisivät, ja ne, jotka näkevät, tulisivat sokeiksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 40, 'Ja muutamat fariseukset, jotka olivat siinä häntä lähellä, kuulivat tämän ja sanoivat hänelle: \"Olemmeko mekin sokeat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 9, 41, 'Jeesus sanoi heille: \"Jos te olisitte sokeat, ei teillä olisi syntiä; mutta nyt te sanotte: \'Me näemme\'; sentähden teidän syntinne pysyy\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 1, '\"Totisesti, totisesti minä sanon teille: joka ei mene ovesta lammastarhaan, vaan nousee sinne muualta, se on varas ja ryöväri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 2, 'Mutta joka menee ovesta sisälle, se on lammasten paimen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 3, 'Hänelle ovenvartija avaa, ja lampaat kuulevat hänen ääntänsä; ja hän kutsuu omat lampaansa nimeltä ja vie heidät ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 4, 'Ja laskettuaan kaikki omansa ulos hän kulkee niiden edellä, ja lampaat seuraavat häntä, sillä ne tuntevat hänen äänensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 5, 'Mutta vierasta ne eivät seuraa, vaan pakenevat häntä, koska eivät tunne vierasten ääntä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 6, 'Tämän kuvauksen Jeesus puhui heille; mutta he eivät ymmärtäneet, mitä hänen puheensa tarkoitti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 7, 'Niin Jeesus vielä sanoi heille: \"Totisesti, totisesti minä sanon teille: minä olen lammasten ovi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 8, 'Kaikki, jotka ovat tulleet ennen minua, ovat varkaita ja ryöväreitä; mutta lampaat eivät ole heitä kuulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 9, 'Minä olen ovi; jos joku minun kauttani menee sisälle, niin hän pelastuu, ja hän on käyvä sisälle ja käyvä ulos ja löytävä laitumen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 10, 'Varas ei tule muuta kuin varastamaan ja tappamaan ja tuhoamaan. Minä olen tullut, että heillä olisi elämä ja olisi yltäkylläisyys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 11, 'Minä olen se hyvä paimen. Hyvä paimen antaa henkensä lammasten edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 12, 'Mutta palkkalainen, joka ei ole paimen ja jonka omia lampaat eivät ole, kun hän näkee suden tulevan, niin hän jättää lampaat ja pakenee; ja susi ryöstää ja hajottaa ne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 13, 'Hän pakenee, sillä hän on palkattu eikä välitä lampaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 14, 'Minä olen se hyvä paimen, ja minä tunnen omani, ja minun omani tuntevat minut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 15, 'niinkuin Isä tuntee minut ja minä tunnen Isän; ja minä annan henkeni lammasten edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 16, 'Minulla on myös muita lampaita, jotka eivät ole tästä lammastarhasta; myös niitä tulee minun johdattaa, ja ne saavat kuulla minun ääneni, ja on oleva yksi lauma ja yksi paimen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 17, 'Sentähden Isä minua rakastaa, koska minä annan henkeni, että minä sen jälleen ottaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 18, 'Ei kukaan sitä minulta ota, vaan minä annan sen itsestäni. Minulla on valta antaa se, ja minulla on valta ottaa se jälleen; sen käskyn minä olen saanut Isältäni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 19, 'Niin syntyi taas erimielisyys juutalaisten kesken näiden sanain tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 20, 'Ja useat heistä sanoivat: \"Hänessä on riivaaja, ja hän on järjiltään; mitä te häntä kuuntelette?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 21, 'Toiset sanoivat: \"Nämä eivät ole riivatun sanoja; eihän riivaaja voi avata sokeain silmiä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 22, 'Sitten oli temppelin vihkimisen muistojuhla Jerusalemissa, ja oli talvi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 23, 'Ja Jeesus käyskeli pyhäkössä, Salomon pylväskäytävässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 24, 'Niin juutalaiset ympäröivät hänet ja sanoivat hänelle: \"Kuinka kauan sinä pidät meidän mieltämme kiihdyksissä? Jos sinä olet Kristus, niin sano se meille suoraan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 25, 'Jeesus vastasi heille: \"Minä olen sanonut sen teille, ja te ette usko. Ne teot, joita minä teen Isäni nimessä, ne todistavat minusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 26, 'Mutta te ette usko, sillä te ette ole minun lampaitani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 27, 'Minun lampaani kuulevat minun ääntäni, ja minä tunnen ne, ja ne seuraavat minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 28, 'Ja minä annan heille iankaikkisen elämän, ja he eivät ikinä huku, eikä kukaan ryöstä heitä minun kädestäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 29, 'Minun Isäni, joka on heidät minulle antanut, on suurempi kaikkia, eikä kukaan voi ryöstää heitä minun Isäni kädestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 30, 'Minä ja Isä olemme yhtä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 31, 'Niin juutalaiset ottivat taas kiviä maasta kivittääksensä hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 32, 'Jeesus vastasi heille: \"Minä olen näyttänyt teille monta hyvää tekoa, jotka ovat Isästä; mikä niistä on se, jonka tähden te tahdotte minut kivittää?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 33, 'Juutalaiset vastasivat hänelle: \"Hyvän teon tähden me emme sinua kivitä, vaan jumalanpilkan tähden, ja koska sinä, joka olet ihminen, teet itsesi Jumalaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 34, 'Jeesus vastasi heille: \"Eikö teidän laissanne ole kirjoitettuna: \'Minä sanoin: te olette jumalia\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 35, 'Jos hän sanoo jumaliksi niitä, joille Jumalan sana tuli-ja Raamattu ei voi raueta tyhjiin-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 36, 'niin kuinka te sanotte sille, jonka Isä on pyhittänyt ja lähettänyt maailmaan: \'Sinä pilkkaat Jumalaa\', sentähden että minä sanoin: \'Minä olen Jumalan Poika\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 37, 'Jos minä en tee Isäni tekoja, älkää uskoko minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 38, 'Mutta jos minä niitä teen, niin, vaikka ette uskoisikaan minua, uskokaa minun tekojani, että tulisitte tuntemaan ja ymmärtäisitte Isän olevan minussa ja minun olevan Isässä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 39, 'Niin he taas tahtoivat ottaa hänet kiinni, mutta hän lähti pois heidän käsistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 40, 'Ja hän meni taas Jordanin tuolle puolelle siihen paikkaan, missä Johannes ensin kastoi, ja viipyi siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 41, 'Ja monet tulivat hänen tykönsä ja sanoivat: \"Johannes ei tehnyt yhtäkään tunnustekoa; mutta kaikki, mitä Johannes sanoi tästä, on totta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 10, 42, 'Ja monet siellä uskoivat häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 1, 'Ja eräs mies, Lasarus, Betaniasta, Marian ja hänen sisarensa Martan kylästä, oli sairaana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 2, 'Ja tämä Maria oli se, joka hajuvoiteella voiteli Herran ja pyyhki hiuksillaan hänen jalkansa; ja Lasarus, joka sairasti, oli hänen veljensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 3, 'Niin sisaret lähettivät Jeesukselle tämän sanan: \"Herra, katso, se, joka on sinulle rakas, sairastaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 4, 'Mutta sen kuultuaan Jeesus sanoi: \"Ei tämä tauti ole kuolemaksi, vaan Jumalan kunniaksi, että Jumalan Poika sen kautta kirkastuisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 5, 'Ja Jeesus rakasti Marttaa ja hänen sisartaan ja Lasarusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 6, 'Kun hän siis kuuli hänen sairastavan, viipyi hän siinä paikassa, missä hän oli, vielä kaksi päivää;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 7, 'mutta niiden kuluttua hän sanoi opetuslapsilleen: \"Menkäämme taas Juudeaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 8, 'Opetuslapset sanoivat hänelle: \"Rabbi, äsken juutalaiset yrittivät kivittää sinut, ja taas sinä menet sinne!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 9, 'Jeesus vastasi: \"Eikö päivässä ole kaksitoista hetkeä? Joka vaeltaa päivällä, se ei loukkaa itseänsä, sillä hän näkee tämän maailman valon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 10, 'Mutta joka vaeltaa yöllä, se loukkaa itsensä, sillä ei hänessä ole valoa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 11, 'Näin hän puhui, ja sitten hän sanoi heille: \"Ystävämme Lasarus nukkuu, mutta minä menen herättämään hänet unesta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 12, 'Niin opetuslapset sanoivat hänelle: \"Herra, jos hän nukkuu, niin hän tulee terveeksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 13, 'Mutta Jeesus puhui hänen kuolemastaan; he taas luulivat hänen puhuneen unessa-nukkumisesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 14, 'Silloin Jeesus sanoi heille suoraan: \"Lasarus on kuollut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 15, 'ja minä iloitsen teidän tähtenne siitä, etten ollut siellä, jotta te uskoisitte; mutta menkäämme hänen tykönsä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 16, 'Niin Tuomas, jota sanottiin Didymukseksi, sanoi toisille opetuslapsille: \"Menkäämme mekin sinne, kuollaksemme hänen kanssansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 17, 'Niin Jeesus tuli ja sai tietää, että hän jo neljä päivää oli ollut haudassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 18, 'Ja Betania oli lähellä Jerusalemia, noin viidentoista vakomitan päässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 19, 'Ja useita juutalaisia oli tullut Martan ja Marian luokse lohduttamaan heitä heidän veljensä kuolemasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 20, 'Kun Martta kuuli, että Jeesus oli tulossa, meni hän häntä vastaan; mutta Maria istui kotona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 21, 'Ja Martta sanoi Jeesukselle: \"Herra, jos sinä olisit ollut täällä, niin minun veljeni ei olisi kuollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 22, 'Mutta nytkin minä tiedän, että Jumala antaa sinulle kaiken, mitä sinä Jumalalta anot.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 23, 'Jeesus sanoi hänelle: \"Sinun veljesi on nouseva ylös\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 24, 'Martta sanoi hänelle: \"Minä tiedän hänen nousevan ylösnousemuksessa, viimeisenä päivänä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 25, 'Jeesus sanoi hänelle: \"Minä olen ylösnousemus ja elämä; joka uskoo minuun, se elää, vaikka olisi kuollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 26, 'Eikä yksikään, joka elää ja uskoo minuun, ikinä kuole. Uskotko sen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 27, 'Hän sanoi hänelle: \"Uskon, Herra; minä uskon, että sinä olet Kristus, Jumalan Poika, se, joka oli tuleva maailmaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 28, 'Ja tämän sanottuaan hän meni ja kutsui salaa sisarensa Marian sanoen: \"Opettaja on täällä ja kutsuu sinua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 29, 'Kun Maria sen kuuli, nousi hän nopeasti ja meni hänen luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 30, 'Mutta Jeesus ei ollut vielä saapunut kylään, vaan oli yhä siinä paikassa, missä Martta oli hänet kohdannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 31, 'Kun nyt juutalaiset, jotka olivat Marian kanssa huoneessa häntä lohduttamassa, näkivät hänen nopeasti nousevan ja lähtevän ulos, seurasivat he häntä, luullen hänen menevän haudalle, itkemään siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 32, 'Kun siis Maria saapui sinne, missä Jeesus oli, ja näki hänet, lankesi hän hänen jalkojensa eteen ja sanoi hänelle: \"Herra, jos sinä olisit ollut täällä, ei minun veljeni olisi kuollut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 33, 'Kun Jeesus näki hänen itkevän ja hänen kanssaan tulleiden juutalaisten itkevän, joutui hän hengessään syvän liikutuksen valtaan ja vapisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 34, 'ja hän sanoi: \"Mihin te panitte hänet?\" He sanoivat hänelle: \"Herra, tule ja katso\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 35, 'Ja Jeesus itki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 36, 'Niin juutalaiset sanoivat: \"Katso, kuinka rakas hän oli hänelle!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 37, 'Mutta muutamat heistä sanoivat: \"Eikö hän, joka avasi sokean silmät, olisi voinut tehdä sitäkin, ettei tämä olisi kuollut?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 38, 'Niin Jeesus joutui taas liikutuksen valtaan ja meni haudalle; ja se oli luola, ja sen suulla oli kivi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 39, 'Jeesus sanoi: \"Ottakaa kivi pois\". Martta, kuolleen sisar, sanoi hänelle: \"Herra, hän haisee jo, sillä hän on ollut haudassa neljättä päivää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 40, 'Jeesus sanoi hänelle: \"Enkö minä sanonut sinulle, että jos uskoisit, niin sinä näkisit Jumalan kirkkauden?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 41, 'Niin he ottivat kiven pois. Ja Jeesus loi silmänsä ylös ja sanoi: \"Isä, minä kiitän sinua, että olet minua kuullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 42, 'Minä kyllä tiesin, että sinä minua aina kuulet; mutta kansan tähden, joka seisoo tässä ympärillä, minä tämän sanon, että he uskoisivat sinun lähettäneen minut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 43, 'Ja sen sanottuansa hän huusi suurella äänellä: \"Lasarus, tule ulos!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 44, 'Ja kuollut tuli ulos, jalat ja kädet siteisiin käärittyinä, ja hänen kasvojensa ympärille oli kääritty hikiliina. Jeesus sanoi heille: \"Päästäkää hänet ja antakaa hänen mennä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 45, 'Niin useat juutalaisista, jotka olivat tulleet Marian luokse ja nähneet, mitä Jeesus teki, uskoivat häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 46, 'Mutta muutamat heistä menivät fariseusten luo ja puhuivat heille, mitä Jeesus oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 47, 'Niin ylipapit ja fariseukset kokosivat neuvoston ja sanoivat: \"Mitä me teemme, sillä tuo mies tekee paljon tunnustekoja?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 48, 'Jos annamme hänen näin olla, niin kaikki uskovat häneen, ja roomalaiset tulevat ja ottavat meiltä sekä maan että kansan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 49, 'Mutta eräs heistä, Kaifas, joka sinä vuonna oli ylimmäinen pappi, sanoi heille: \"Te ette tiedä mitään');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 50, 'ettekä ajattele, että teille on parempi, että yksi ihminen kuolee kansan edestä, kuin että koko kansa hukkuu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 51, 'Mutta sitä hän ei sanonut itsestään, vaan koska hän oli sinä vuonna ylimmäinen pappi, hän ennusti, että Jeesus oli kuoleva kansan edestä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 52, 'eikä ainoastaan tämän kansan edestä, vaan myös kootakseen yhdeksi hajalla olevat Jumalan lapset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 53, 'Siitä päivästä lähtien oli heillä siis tehtynä päätös tappaa hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 54, 'Sentähden Jeesus ei enää vaeltanut julkisesti juutalaisten keskellä, vaan lähti sieltä lähellä erämaata olevaan paikkaan, Efraim nimiseen kaupunkiin; ja siellä hän oleskeli opetuslapsineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 55, 'Mutta juutalaisten pääsiäinen oli lähellä, ja monet menivät maaseudulta ylös Jerusalemiin ennen pääsiäisjuhlaa, puhdistamaan itsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 56, 'Ja he etsivät Jeesusta ja sanoivat toisilleen seisoessaan pyhäkössä: \"Mitä arvelette? Eikö hän tullekaan juhlille?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 11, 57, 'Mutta ylipapit ja fariseukset olivat antaneet käskyjä, että jos joku tietäisi, missä hän oli, hänen oli annettava se ilmi, jotta he ottaisivat hänet kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 1, 'Kuusi päivää ennen pääsiäistä Jeesus saapui Betaniaan, jossa Lasarus asui, hän, jonka Jeesus oli herättänyt kuolleista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 2, 'Siellä valmistettiin hänelle ateria, ja Martta palveli, mutta Lasarus oli yksi niistä, jotka olivat aterialla hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 3, 'Niin Maria otti naulan oikeata, kallisarvoista nardusvoidetta ja voiteli Jeesuksen jalat ja pyyhki ne hiuksillaan; ja huone tuli täyteen voiteen tuoksua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 4, 'Silloin sanoi yksi hänen opetuslapsistaan, Juudas Iskariot, joka oli hänet kavaltava:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 5, '\"Miksi ei tätä voidetta myyty kolmeensataan denariin ja niitä annettu köyhille?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 6, 'Mutta tätä hän ei sanonut sentähden, että olisi pitänyt huolta köyhistä, vaan sentähden, että hän oli varas ja että hän rahakukkaron hoitajana otti itselleen, mitä siihen oli pantu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 7, 'Niin Jeesus sanoi: \"Anna hänen olla, että hän saisi toimittaa tämän minun hautaamispäiväni varalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 8, 'Sillä köyhät teillä aina on keskuudessanne, mutta minua teillä ei ole aina.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 9, 'Silloin suuri joukko juutalaisia sai tietää, että hän oli siellä; ja he menivät sinne, ei ainoastaan Jeesuksen tähden, vaan myöskin nähdäkseen Lasaruksen, jonka hän oli herättänyt kuolleista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 10, 'Mutta ylipapit päättivät tappaa Lasaruksenkin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 11, 'koska monet juutalaiset hänen tähtensä menivät sinne ja uskoivat Jeesukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 12, 'Seuraavana päivänä, kun suuri kansanjoukko, joka oli saapunut juhlille, kuuli, että Jeesus oli tulossa Jerusalemiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 13, 'ottivat he palmupuiden oksia ja menivät häntä vastaan ja huusivat: \"Hoosianna, siunattu olkoon hän, joka tulee Herran nimeen, Israelin kuningas!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 14, 'Ja saatuansa nuoren aasin Jeesus istui sen selkään, niinkuin kirjoitettu on:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 15, '\"Älä pelkää, tytär Siion; katso, sinun kuninkaasi tulee istuen aasin varsan selässä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 16, 'Tätä hänen opetuslapsensa eivät aluksi ymmärtäneet; mutta kun Jeesus oli kirkastettu, silloin he muistivat, että tämä oli hänestä kirjoitettu ja että he olivat tämän hänelle tehneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 17, 'Niin kansa, joka oli ollut hänen kanssansa, kun hän kutsui Lasaruksen haudasta ja herätti hänet kuolleista, todisti hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 18, 'Sentähden kansa menikin häntä vastaan, koska he kuulivat, että hän oli tehnyt sen tunnusteon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 19, 'Niin fariseukset sanoivat keskenään: \"Te näette, ettette saa mitään aikaan; katso, koko maailma juoksee hänen perässään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 20, 'Ja oli muutamia kreikkalaisia niiden joukosta, jotka tulivat ylös juhlaan rukoilemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 21, 'Nämä menivät Filippuksen luo, joka oli Galilean Beetsaidasta, ja pyysivät häntä sanoen: \"Herra, me haluamme nähdä Jeesuksen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 22, 'Filippus meni ja sanoi sen Andreaalle; Andreas ja Filippus menivät ja sanoivat Jeesukselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 23, 'Mutta Jeesus vastasi heille sanoen: \"Hetki on tullut, että Ihmisen Poika kirkastetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 24, 'Totisesti, totisesti minä sanon teille: jos ei nisun jyvä putoa maahan ja kuole, niin se jää yksin; mutta jos se kuolee, niin se tuottaa paljon hedelmää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 25, 'Joka elämäänsä rakastaa, kadottaa sen; mutta joka vihaa elämäänsä tässä maailmassa, hän on säilyttävä sen iankaikkiseen elämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 26, 'Jos joku minua palvelee, seuratkoon hän minua; ja missä minä olen, siellä on myös minun palvelijani oleva. Ja jos joku minua palvelee, niin Isä on kunnioittava häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 27, 'Nyt minun sieluni on järkytetty; ja mitä pitäisi minun sanoman? Isä, pelasta minut tästä hetkestä. Kuitenkin: sitä varten minä olen tähän hetkeen tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 28, 'Isä, kirkasta nimesi!\" Niin taivaasta tuli ääni: \"Minä olen sen kirkastanut, ja olen sen vielä kirkastava\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 29, 'Niin kansa, joka seisoi ja kuuli sen, sanoi ukkosen jylisseen. Toiset sanoivat: \"Häntä puhutteli enkeli\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 30, 'Jeesus vastasi ja sanoi: \"Ei tämä ääni tullut minun tähteni, vaan teidän tähtenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 31, 'Nyt käy tuomio tämän maailman ylitse; nyt tämän maailman ruhtinas pitää heitettämän ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 32, 'Ja kun minut ylennetään maasta, niin minä vedän kaikki tyköni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 33, 'Mutta sen hän sanoi antaen tietää, minkäkaltaisella kuolemalla hän oli kuoleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 34, 'Kansa vastasi hänelle: \"Me olemme laista kuulleet, että Kristus pysyy iankaikkisesti; kuinka sinä sitten sanot, että Ihmisen Poika pitää ylennettämän? Kuka on se Ihmisen Poika?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 35, 'Niin Jeesus sanoi heille: \"Vielä vähän aikaa valkeus on teidän keskuudessanne. Vaeltakaa, niin kauan kuin teillä valkeus on, ettei pimeys saisi teitä valtaansa. Joka pimeässä vaeltaa, se ei tiedä, mihin hän menee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 36, 'Niin kauan kuin teillä valkeus on, uskokaa valkeuteen, että te valkeuden lapsiksi tulisitte.\" Tämän Jeesus puhui ja meni pois ja kätkeytyi heiltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 37, 'Ja vaikka hän oli tehnyt niin monta tunnustekoa heidän nähtensä, eivät he uskoneet häneen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 38, 'että kävisi toteen profeetta Esaiaan sana, jonka hän on sanonut: \"Herra, kuka uskoo meidän saarnamme, ja kenelle Herran käsivarsi ilmoitetaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 39, 'Sentähden he eivät voineet uskoa, koska Esaias on vielä sanonut:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 40, '\"Hän on sokaissut heidän silmänsä ja paaduttanut heidän sydämensä, että he eivät näkisi silmillään eivätkä ymmärtäisi sydämellään eivätkä kääntyisi ja etten minä heitä parantaisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 41, 'Tämän Esaias sanoi, kun hän näki hänen kirkkautensa ja puhui hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 42, 'Kuitenkin useat hallitusmiehistäkin uskoivat häneen, mutta fariseusten tähden he eivät sitä tunnustaneet, etteivät joutuisi synagoogasta erotetuiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 43, 'Sillä he rakastivat ihmiskunniaa enemmän kuin Jumalan kunniaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 44, 'Mutta Jeesus huusi ja sanoi: \"Joka uskoo minuun, se ei usko minuun, vaan häneen, joka on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 45, 'Ja joka näkee minut, näkee hänet, joka on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 46, 'Minä olen tullut valkeudeksi maailmaan, ettei yksikään, joka minuun uskoo, jäisi pimeyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 47, 'Ja jos joku kuulee minun sanani eikä niitä noudata, niin häntä en minä tuomitse; sillä en minä ole tullut maailmaa tuomitsemaan, vaan pelastamaan maailman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 48, 'Joka katsoo minut ylen eikä ota vastaan minun sanojani, hänellä on tuomitsijansa: se sana, jonka minä olen puhunut, se on tuomitseva hänet viimeisenä päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 49, 'Sillä en minä itsestäni ole puhunut, vaan Isä, joka on minut lähettänyt, on itse antanut minulle käskyn, mitä minun pitää sanoman ja mitä puhuman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 12, 50, 'Ja minä tiedän, että hänen käskynsä on iankaikkinen elämä. Sentähden, minkä minä puhun, sen minä puhun niin, kuin Isä on minulle sanonut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 1, 'Mutta ennen pääsiäisjuhlaa, kun Jeesus tiesi hetkensä tulleen, että hän oli siirtyvä tästä maailmasta Isän tykö, niin hän, joka oli rakastanut omiansa, jotka maailmassa olivat, osoitti heille rakkautta loppuun asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 2, 'Ja ehtoollisella oltaessa, kun perkele jo oli pannut Juudas Iskariotin, Simonin pojan, sydämeen, että hän kavaltaisi Jeesuksen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 3, 'niin Jeesus, tietäen, että Isä oli antanut kaikki hänen käsiinsä ja että hän oli lähtenyt Jumalan tyköä ja oli menevä Jumalan tykö,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 4, 'nousi ehtoolliselta ja riisui vaippansa, otti liinavaatteen ja vyötti sillä itsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 5, 'Sitten hän kaatoi vettä pesumaljaan ja rupesi pesemään opetuslastensa jalkoja ja pyyhkimään niitä liinavaatteella, jolla oli vyöttäytynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 6, 'Niin hän tuli Simon Pietarin kohdalle, ja tämä sanoi hänelle: \"Herra, sinäkö peset minun jalkani?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 7, 'Jeesus vastasi ja sanoi hänelle: \"Mitä minä teen, sitä et nyt käsitä, mutta vastedes sinä sen ymmärrät\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 8, 'Pietari sanoi hänelle: \"Et ikinä sinä saa pestä minun jalkojani\". Jeesus vastasi hänelle: \"Ellen minä sinua pese, ei sinulla ole osuutta minun kanssani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 9, 'Simon Pietari sanoi hänelle: \"Herra, älä pese ainoastaan minun jalkojani, vaan myös kädet ja pää\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 10, 'Jeesus sanoi hänelle: \"Joka on kylpenyt, ei tarvitse muuta, kuin että jalat pestään, ja niin hän on kokonaan puhdas; ja te olette puhtaat, ette kuitenkaan kaikki\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 11, 'Sillä hän tiesi kavaltajansa; sentähden hän sanoi: \"Ette kaikki ole puhtaat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 12, 'Kun hän siis oli pessyt heidän jalkansa ja ottanut vaippansa ja taas asettunut aterialle, sanoi hän heille: \"Ymmärrättekö, mitä minä olen teille tehnyt?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 13, 'Te puhuttelette minua opettajaksi ja Herraksi, ja oikein te sanotte, sillä se minä olen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 14, 'Jos siis minä, teidän Herranne ja opettajanne, olen pessyt teidän jalkanne, olette tekin velvolliset pesemään toistenne jalat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 15, 'Sillä minä annoin teille esikuvan, että myös te niin tekisitte, kuin minä olen teille tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 16, 'Totisesti, totisesti minä sanon teille: ei ole palvelija herraansa suurempi eikä lähettiläs lähettäjäänsä suurempi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 17, 'Jos te tämän tiedätte, niin olette autuaat, jos te sen teette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 18, 'En minä puhu teistä kaikista: minä tiedän, ketkä olen valinnut; mutta tämän kirjoituksen piti käymän toteen: \'Joka minun leipääni syö, on nostanut kantapäänsä minua vastaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 19, 'Jo nyt minä sanon sen teille, ennenkuin se tapahtuu, että te, kun se tapahtuu, uskoisitte, että minä olen se.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 20, 'Totisesti, totisesti minä sanon teille: joka ottaa vastaan sen, jonka minä lähetän, se ottaa vastaan minut; mutta joka ottaa vastaan minut, se ottaa vastaan hänet, joka on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 21, 'Tämän sanottuaan Jeesus tuli järkytetyksi hengessään ja todisti ja sanoi: \"Totisesti, totisesti minä sanon teille: yksi teistä on minut kavaltava\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 22, 'Niin opetuslapset katsoivat toisiinsa epätietoisina, kenestä hän puhui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 23, 'Ja eräs hänen opetuslapsistaan, se, jota Jeesus rakasti, lepäsi aterioitaessa Jeesuksen syliä vasten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 24, 'Simon Pietari nyökäytti hänelle päätään ja sanoi hänelle: \"Sano, kuka se on, josta hän puhuu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 25, 'Niin tämä, nojautuen Jeesuksen rintaa vasten, sanoi hänelle: \"Herra, kuka se on?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 26, 'Jeesus vastasi: \"Se on se, jolle minä kastan ja annan tämän palan\". Niin hän otti palan, kastoi sen ja antoi Juudaalle, Simon Iskariotin pojalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 27, 'Ja silloin, sen palan jälkeen, meni häneen saatana. Niin Jeesus sanoi hänelle: \"Minkä teet, se tee pian\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 28, 'Mutta ei kukaan aterioivista ymmärtänyt, mitä varten hän sen hänelle sanoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 29, 'Sillä muutamat luulivat, koska rahakukkaro oli Juudaalla, Jeesuksen sanoneen hänelle: \"Osta, mitä tarvitsemme juhlaksi\", tai että hän antaisi jotakin köyhille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 30, 'Niin hän, otettuaan sen palan, meni kohta ulos; ja oli yö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 31, 'Kun hän oli mennyt ulos, sanoi Jeesus: \"Nyt Ihmisen Poika on kirkastettu, ja Jumala on kirkastettu hänessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 32, 'Jos Jumala on kirkastettu hänessä, niin kirkastaa myös Jumala hänet itsessään ja kirkastaa hänet pian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 33, 'Lapsukaiset, vielä vähän aikaa minä olen teidän kanssanne. Te tulette minua etsimään, ja niinkuin sanoin juutalaisille: \'Mihin minä menen, sinne te ette voi tulla\', niin minä sanon nyt myös teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 34, 'Uuden käskyn minä annan teille, että rakastatte toisianne, niinkuin minä olen teitä rakastanut-että tekin niin rakastatte toisianne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 35, 'Siitä kaikki tuntevat teidät minun opetuslapsikseni, jos teillä on keskinäinen rakkaus.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 36, 'Simon Pietari sanoi hänelle: \"Herra, mihin sinä menet?\" Jeesus vastasi hänelle: \"Mihin minä menen, sinne sinä et voi nyt minua seurata, mutta vastedes olet minua seuraava\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 37, 'Pietari sanoi hänelle: \"Herra, miksi en nyt voi seurata sinua? Henkeni minä annan sinun edestäsi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 13, 38, 'Jeesus vastasi: \"Sinäkö annat henkesi minun edestäni? Totisesti, totisesti minä sanon sinulle: ei laula kukko, ennenkuin sinä minut kolmesti kiellät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 1, '\"Älköön teidän sydämenne olko murheellinen. Uskokaa Jumalaan, ja uskokaa minuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 2, 'Minun Isäni kodissa on monta asuinsijaa. Jos ei niin olisi, sanoisinko minä teille, että minä menen valmistamaan teille sijaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 3, 'Ja vaikka minä menen valmistamaan teille sijaa, tulen minä takaisin ja otan teidät tyköni, että tekin olisitte siellä, missä minä olen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 4, 'Ja mihin minä menen-tien sinne te tiedätte.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 5, 'Tuomas sanoi hänelle: \"Herra, me emme tiedä, mihin sinä menet; kuinka sitten tietäisimme tien?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 6, 'Jeesus sanoi hänelle: \"Minä olen tie ja totuus ja elämä; ei kukaan tule Isän tykö muutoin kuin minun kauttani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 7, 'Jos te olisitte tunteneet minut, niin te tuntisitte myös minun Isäni; tästälähin te tunnette hänet, ja te olette nähneet hänet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 8, 'Filippus sanoi hänelle: \"Herra, näytä meille Isä, niin me tyydymme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 9, 'Jeesus sanoi hänelle: \"Niin kauan aikaa minä olen ollut teidän kanssanne, etkä sinä tunne minua, Filippus! Joka on nähnyt minut, on nähnyt Isän; kuinka sinä sitten sanot: \'Näytä meille Isä\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 10, 'Etkö usko, että minä olen Isässä, ja että Isä on minussa? Niitä sanoja, jotka minä teille puhun, minä en puhu itsestäni; ja Isä, joka minussa asuu, tekee teot, jotka ovat hänen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 11, 'Uskokaa minua, että minä olen Isässä, ja että Isä on minussa; mutta jos ette, niin uskokaa itse tekojen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 12, 'Totisesti, totisesti minä sanon teille: joka uskoo minuun, myös hän on tekevä niitä tekoja, joita minä teen, ja suurempiakin, kuin ne ovat, hän on tekevä; sillä minä menen Isän tykö,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 13, 'ja mitä hyvänsä te anotte minun nimessäni, sen minä teen, että Isä kirkastettaisiin Pojassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 14, 'Jos te anotte minulta jotakin minun nimessäni, niin minä sen teen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 15, 'Jos te minua rakastatte, niin te pidätte minun käskyni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 16, 'Ja minä olen rukoileva Isää, ja hän antaa teille toisen Puolustajan olemaan teidän kanssanne iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 17, 'totuuden Hengen, jota maailma ei voi ottaa vastaan, koska se ei näe häntä eikä tunne häntä; mutta te tunnette hänet, sillä hän pysyy teidän tykönänne ja on teissä oleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 18, 'En minä jätä teitä orvoiksi; minä tulen teidän tykönne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 19, 'Vielä vähän aikaa, niin maailma ei enää minua näe, mutta te näette minut; koska minä elän, niin tekin saatte elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 20, 'Sinä päivänä te ymmärrätte, että minä olen Isässäni, ja että te olette minussa ja minä teissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 21, 'Jolla on minun käskyni ja joka ne pitää, hän on se, joka minua rakastaa; mutta joka minua rakastaa, häntä minun Isäni rakastaa, ja minä rakastan häntä ja ilmoitan itseni hänelle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 22, 'Juudas, ei se Iskariot, sanoi hänelle: \"Herra, mistä syystä sinä aiot ilmoittaa itsesi meille etkä maailmalle?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 23, 'Jeesus vastasi ja sanoi hänelle: \"Jos joku rakastaa minua, niin hän pitää minun sanani, ja minun Isäni rakastaa häntä, ja me tulemme hänen tykönsä ja jäämme hänen tykönsä asumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 24, 'Joka ei minua rakasta, se ei pidä minun sanojani; ja se sana, jonka te kuulette, ei ole minun, vaan Isän, joka on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 25, 'Tämän minä olen teille puhunut ollessani teidän tykönänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 26, 'Mutta Puolustaja, Pyhä Henki, jonka Isä on lähettävä minun nimessäni, hän opettaa teille kaikki ja muistuttaa teitä kaikesta, minkä minä olen teille sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 27, 'Rauhan minä jätän teille: minun rauhani-sen minä annan teille. En minä anna teille, niinkuin maailma antaa. Älköön teidän sydämenne olko murheellinen älköönkä peljätkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 28, 'Te kuulitte minun sanovan teille: \'Minä menen pois ja palajan jälleen teidän tykönne\'. Jos te minua rakastaisitte, niin te iloitsisitte siitä, että minä menen Isän tykö, sillä Isä on minua suurempi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 29, 'Ja nyt minä olen sanonut sen teille, ennenkuin se on tapahtunut, että te uskoisitte, kun se tapahtuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 30, 'En minä enää puhu paljoa teidän kanssanne, sillä maailman ruhtinas tulee, ja minussa hänellä ei ole mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 14, 31, 'Mutta että maailma ymmärtäisi minun rakastavan Isää ja tekevän, niinkuin Isä on minua käskenyt: nouskaa, lähtekäämme täältä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 1, '\"Minä olen totinen viinipuu, ja minun Isäni on viinitarhuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 2, 'Jokaisen oksan minussa, joka ei kanna hedelmää, hän karsii pois; ja jokaisen, joka kantaa hedelmää, hän puhdistaa, että se kantaisi runsaamman hedelmän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 3, 'Te olette jo puhtaat sen sanan tähden, jonka minä olen teille puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 4, 'Pysykää minussa, niin minä pysyn teissä. Niinkuin oksa ei voi kantaa hedelmää itsestään, ellei se pysy viinipuussa, niin ette tekään, ellette pysy minussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 5, 'Minä olen viinipuu, te olette oksat. Joka pysyy minussa ja jossa minä pysyn, se kantaa paljon hedelmää; sillä ilman minua te ette voi mitään tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 6, 'Jos joku ei pysy minussa, niin hänet heitetään pois niinkuin oksa, ja hän kuivettuu; ja ne kootaan yhteen ja heitetään tuleen, ja ne palavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 7, 'Jos te pysytte minussa ja minun sanani pysyvät teissä, niin anokaa, mitä ikinä tahdotte, ja te saatte sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 8, 'Siinä minun Isäni kirkastetaan, että te kannatte paljon hedelmää ja tulette minun opetuslapsikseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 9, 'Niinkuin Isä on minua rakastanut, niin minäkin olen rakastanut teitä; pysykää minun rakkaudessani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 10, 'Jos te pidätte minun käskyni, niin te pysytte minun rakkaudessani, niinkuin minä olen pitänyt Isäni käskyt ja pysyn hänen rakkaudessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 11, 'Tämän minä olen teille puhunut, että minun iloni olisi teissä ja teidän ilonne tulisi täydelliseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 12, 'Tämä on minun käskyni, että te rakastatte toisianne, niinkuin minä olen teitä rakastanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 13, 'Sen suurempaa rakkautta ei ole kenelläkään, kuin että hän antaa henkensä ystäväinsä edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 14, 'Te olette minun ystäväni, jos teette, mitä minä käsken teidän tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 15, 'En minä enää sano teitä palvelijoiksi, sillä palvelija ei tiedä, mitä hänen herransa tekee; vaan ystäviksi minä sanon teitä, sillä minä olen ilmoittanut teille kaikki, mitä minä olen kuullut Isältäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 16, 'Te ette valinneet minua, vaan minä valitsin teidät ja asetin teidät, että te menisitte ja kantaisitte hedelmää ja että teidän hedelmänne pysyisi: että mitä ikinä te anotte Isältä minun nimessäni, hän sen teille antaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 17, 'Sen käskyn minä teille annan, että rakastatte toisianne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 18, 'Jos maailma teitä vihaa, niin tietäkää, että se on vihannut minua ennen kuin teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 19, 'Jos te maailmasta olisitte, niin maailma omaansa rakastaisi; mutta koska te ette ole maailmasta, vaan minä olen teidät maailmasta valinnut, sentähden maailma teitä vihaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 20, 'Muistakaa se sana, jonka minä teille sanoin: \'Ei ole palvelija herraansa suurempi\'. Jos he ovat minua vainonneet, niin he teitäkin vainoavat; jos he ovat ottaneet vaarin minun sanastani, niin he ottavat vaarin teidänkin sanastanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 21, 'Mutta kaiken tämän he tekevät teille minun nimeni tähden, koska he eivät tunne häntä, joka on minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 22, 'Jos minä en olisi tullut ja puhunut heille, ei heillä olisi syntiä; mutta nyt heillä ei ole, millä syntiänsä puolustaisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 23, 'Joka vihaa minua, se vihaa myös minun Isääni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 24, 'Jos minä en olisi tehnyt heidän keskuudessaan niitä tekoja, joita ei kukaan muu ole tehnyt, ei heillä olisi syntiä; mutta nyt he ovat nähneet ja ovat vihanneet sekä minua että minun Isääni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 25, 'Mutta se sana oli käyvä toteen, joka on kirjoitettuna heidän laissaan: \'He ovat vihanneet minua syyttä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 26, 'Mutta kun Puolustaja tulee, jonka minä lähetän teille Isän tyköä, totuuden Henki, joka lähtee Isän tyköä, niin hän on todistava minusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 15, 27, 'Ja te myös todistatte, sillä te olette alusta asti olleet minun kanssani.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 1, '\"Tämän minä olen teille puhunut, ettette loukkaantuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 2, 'He erottavat teidät synagoogasta; ja tulee aika, jolloin jokainen, joka tappaa teitä, luulee tekevänsä uhripalveluksen Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 3, 'Ja sen he tekevät teille, koska he eivät tunne Isää eivätkä minua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 4, 'Mutta tämän minä olen puhunut teille, että, kun se aika tulee, te muistaisitte minun sen teille sanoneen. Tätä minä en ole sanonut teille alusta, koska minä olin teidän kansanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 5, 'Mutta nyt minä menen hänen tykönsä, joka on minut lähettänyt, eikä kukaan teistä kysy minulta: \'Mihin sinä menet?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 6, 'Mutta koska minä olen tämän teille puhunut, täyttää murhe teidän sydämenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 7, 'Kuitenkin minä sanon teille totuuden: teille on hyväksi, että minä menen pois. Sillä ellen minä mene pois, ei Puolustaja tule teidän tykönne; mutta jos minä menen, niin minä hänet teille lähetän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 8, 'Ja kun hän tulee, niin hän näyttää maailmalle todeksi synnin ja vanhurskauden ja tuomion:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 9, 'synnin, koska he eivät usko minuun;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 10, 'vanhurskauden, koska minä menen Isän tykö, ettekä te enää minua näe;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 11, 'ja tuomion, koska tämän maailman ruhtinas on tuomittu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 12, 'Minulla on vielä paljon sanottavaa teille, mutta te ette voi nyt sitä kantaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 13, 'Mutta kun hän tulee, totuuden Henki, johdattaa hän teidät kaikkeen totuuteen. Sillä se, mitä hän puhuu, ei ole hänestä itsestään; vaan minkä hän kuulee, sen hän puhuu, ja tulevaiset hän teille julistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 14, 'Hän on minut kirkastava, sillä hän ottaa minun omastani ja julistaa teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 15, 'Kaikki, mitä Isällä on, on minun; sentähden minä sanoin, että hän ottaa minun omastani ja julistaa teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 16, 'Vähän aikaa, niin te ette enää minua näe, ja taas vähän aikaa, niin te näette minut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 17, 'Silloin muutamat hänen opetuslapsistansa sanoivat toisilleen: \"Mitä se tarkoittaa, kun hän sanoo meille: \'Vähän aikaa, niin te ette minua näe, ja taas vähän aikaa, niin te näette minut\', ja: \'Minä menen Isän tykö\'?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 18, 'Niin he sanoivat: \"Mitä se tarkoittaa, kun hän sanoo: \'Vähän aikaa\'? Emme ymmärrä, mitä hän puhuu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 19, 'Jeesus huomasi heidän tahtovan kysyä häneltä ja sanoi heille: \"Sitäkö te kyselette keskenänne, että minä sanoin: \'Vähän aikaa, niin te ette minua näe, ja taas vähän aikaa, niin te näette minut\'?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 20, 'Totisesti, totisesti minä sanon teille: te joudutte itkemään ja valittamaan, mutta maailma on iloitseva; te tulette murheellisiksi, mutta teidän murheenne on muuttuva iloksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 21, 'Kun vaimo synnyttää, on hänellä murhe, koska hänen hetkensä on tullut; mutta kun hän on synnyttänyt lapsen, ei hän enää muista ahdistustaan sen ilon tähden, että ihminen on syntynyt maailmaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 22, 'Niin on myös teillä nyt murhe; mutta minä olen taas näkevä teidät, ja teidän sydämenne on iloitseva, eikä kukaan ota teiltä pois teidän iloanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 23, 'Ja sinä päivänä te ette minulta mitään kysy. Totisesti, totisesti minä sanon teille: jos te anotte jotakin Isältä, on hän sen teille antava minun nimessäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 24, 'Tähän asti te ette ole anoneet mitään minun nimessäni; anokaa, niin te saatte, että teidän ilonne olisi täydellinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 25, 'Tämän minä olen puhunut teille kuvauksilla; mutta tulee aika, jolloin minä en puhu teille enää kuvauksilla, vaan avonaisesti julistan teille sanomaa Isästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 26, 'Sinä päivänä te anotte minun nimessäni; enkä minä sano teille, että minä olen rukoileva Isää teidän edestänne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 27, 'sillä Isä itse rakastaa teitä, sentähden että te olette minua rakastaneet ja uskoneet minun lähteneen Jumalan tyköä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 28, 'Minä olen lähtenyt Isästä ja tullut maailmaan; jälleen minä jätän maailman ja menen Isän tykö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 29, 'Hänen opetuslapsensa sanoivat: \"Katso, nyt sinä puhut avonaisesti etkä käytä mitään kuvausta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 30, 'Nyt me tiedämme, että sinä tiedät kaikki, etkä tarvitse, että kukaan sinulta kysyy; sentähden me uskomme sinun Jumalan tyköä lähteneen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 31, 'Jeesus vastasi heille: \"Nyt te uskotte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 32, 'Katso, tulee hetki ja on jo tullut, jona teidät hajotetaan kukin tahollensa ja te jätätte minut yksin; en minä kuitenkaan yksin ole, sillä Isä on minun kanssani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 16, 33, 'Tämän minä olen teille puhunut, että teillä olisi minussa rauha. Maailmassa teillä on ahdistus; mutta olkaa turvallisella mielellä: minä olen voittanut maailman.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 1, 'Tämän Jeesus puhui ja nosti silmänsä taivasta kohti ja sanoi: \"Isä, hetki on tullut, kirkasta Poikasi, että Poikasi kirkastaisi sinut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 2, 'koska sinä olet antanut hänen valtaansa kaiken lihan, että hän antaisi iankaikkisen elämän kaikille, jotka sinä olet hänelle antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 3, 'Mutta tämä on iankaikkinen elämä, että he tuntevat sinut, joka yksin olet totinen Jumala, ja hänet, jonka sinä olet lähettänyt, Jeesuksen Kristuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 4, 'Minä olen kirkastanut sinut maan päällä: minä olen täyttänyt sen työn, jonka sinä annoit minun tehtäväkseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 5, 'Ja nyt, Isä, kirkasta sinä minut tykönäsi sillä kirkkaudella, joka minulla oli sinun tykönäsi, ennenkuin maailma olikaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 6, 'Minä olen ilmoittanut sinun nimesi ihmisille, jotka sinä annoit minulle maailmasta. He olivat sinun, ja sinä annoit heidät minulle, ja he ovat ottaneet sinun sanastasi vaarin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 7, 'Nyt he tietävät, että kaikki, minkä olet minulle antanut, on sinulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 8, 'Sillä ne sanat, jotka sinä minulle annoit, minä olen antanut heille; ja he ovat ottaneet ne vastaan ja tietävät totisesti minun lähteneen sinun tyköäsi ja uskovat, että sinä olet minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 9, 'Minä rukoilen heidän edestänsä; en minä maailman edestä rukoile, vaan niiden edestä, jotka sinä olet minulle antanut, koska he ovat sinun-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 10, 'ja kaikki minun omani ovat sinun, ja sinun omasi ovat minun-ja minä olen kirkastettu heissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 11, 'Ja minä en enää ole maailmassa, mutta he ovat maailmassa, ja minä tulen sinun tykösi. Pyhä Isä, varjele heidät nimessäsi, jonka sinä olet minulle antanut, että he olisivat yhtä niinkuin mekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 12, 'Kun minä olin heidän kanssansa, varjelin minä heidät sinun nimessäsi, jonka sinä olet minulle antanut, ja suojelin heitä, eikä heistä joutunut kadotetuksi yksikään muu kuin se kadotuksen lapsi, että kirjoitus kävisi toteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 13, 'Mutta nyt minä tulen sinun tykösi ja puhun tätä maailmassa, että heillä olisi minun iloni täydellisenä heissä itsessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 14, 'Minä olen antanut heille sinun sanasi, ja maailma vihaa heitä, koska he eivät ole maailmasta, niinkuin en minäkään maailmasta ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 15, 'En minä rukoile, että ottaisit heidät pois maailmasta, vaan että sinä varjelisit heidät pahasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 16, 'He eivät ole maailmasta, niinkuin en minäkään maailmasta ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 17, 'Pyhitä heidät totuudessa; sinun sanasi on totuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 18, 'Niinkuin sinä olet lähettänyt minut maailmaan, niin olen minäkin lähettänyt heidät maailmaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 19, 'ja minä pyhitän itseni heidän tähtensä, että myös he olisivat pyhitetyt totuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 20, 'Mutta en minä rukoile ainoastaan näiden edestä, vaan myös niiden edestä, jotka heidän sanansa kautta uskovat minuun,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 21, 'että he kaikki olisivat yhtä, niinkuin sinä, Isä, olet minussa ja minä sinussa, että hekin meissä olisivat, niin että maailma uskoisi, että sinä olet minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 22, 'Ja sen kirkkauden, jonka sinä minulle annoit, minä olen antanut heille, että he olisivat yhtä, niinkuin me olemme yhtä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 23, 'minä heissä, ja sinä minussa-että he olisivat täydellisesti yhtä, niin että maailma ymmärtäisi, että sinä olet minut lähettänyt ja rakastanut heitä, niinkuin sinä olet minua rakastanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 24, 'Isä, minä tahdon, että missä minä olen, siellä nekin, jotka sinä olet minulle antanut, olisivat minun kanssani, että he näkisivät minun kirkkauteni, jonka sinä olet minulle antanut, koska olet rakastanut minua jo ennen maailman perustamista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 25, 'Vanhurskas Isä, maailma ei ole sinua tuntenut, mutta minä tunnen sinut, ja nämä ovat tulleet tuntemaan, että sinä olet minut lähettänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 17, 26, 'Ja minä olen tehnyt sinun nimesi heille tunnetuksi ja teen vastakin, että se rakkaus, jolla sinä olet minua rakastanut, olisi heissä ja minä olisin heissä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 1, 'Kun Jeesus oli tämän puhunut, lähti hän pois opetuslastensa kanssa Kedronin puron tuolle puolelle; siellä oli puutarha, johon hän meni opetuslapsinensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 2, 'Mutta myös Juudas, joka hänet kavalsi, tiesi sen paikan, koska Jeesus ja hänen opetuslapsensa usein olivat kokoontuneet sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 3, 'Niin Juudas otti sotilasjoukon sekä ylipappien ja fariseusten palvelijoita ja tuli sinne soihdut ja lamput ja aseet mukanaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 4, 'Silloin Jeesus, joka tiesi kaiken, mikä oli häntä kohtaava, astui esiin ja sanoi heille: \"Ketä te etsitte?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 5, 'He vastasivat hänelle: \"Jeesusta, Nasaretilaista\". Jeesus sanoi heille: \"Minä se olen\". Ja Juudas, joka hänet kavalsi, seisoi myös heidän kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 6, 'Kun hän siis sanoi heille: \"Minä se olen\", peräytyivät he ja kaatuivat maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 7, 'Niin hän taas kysyi heiltä: \"Ketä te etsitte?\" He sanoivat: \"Jeesusta, Nasaretilaista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 8, 'Jeesus vastasi: \"Minähän sanoin teille, että minä se olen. Jos te siis minua etsitte, niin antakaa näiden mennä\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 9, 'että se sana kävisi toteen, jonka hän oli sanonut: \"En minä ole kadottanut ketään niistä, jotka sinä olet minulle antanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 10, 'Niin Simon Pietari, jolla oli miekka, veti sen ja iski ylimmäisen papin palvelijaa ja sivalsi häneltä pois oikean korvan; ja palvelijan nimi oli Malkus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 11, 'Niin Jeesus sanoi Pietarille: \"Pistä miekkasi tuppeen. Enkö minä joisi sitä maljaa, jonka Isä on minulle antanut?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 12, 'Niin sotilasjoukko ja päällikkö ja juutalaisten palvelijat ottivat Jeesuksen kiinni ja sitoivat hänet');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 13, 'ja veivät ensin Hannaan luo, sillä hän oli Kaifaan appi, ja Kaifas oli sinä vuonna ylimmäisenä pappina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 14, 'Ja Kaifas oli se, joka neuvottelussa oli juutalaisille sanonut: \"On hyödyllistä, että yksi ihminen kuolee kansan edestä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 15, 'Ja Jeesusta seurasi Simon Pietari ja eräs toinen opetuslapsi. Tämä opetuslapsi oli ylimmäisen papin tuttava ja meni Jeesuksen kanssa sisälle ylimmäisen papin kartanoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 16, 'Mutta Pietari seisoi portilla ulkona. Niin se toinen opetuslapsi, joka oli ylimmäisen papin tuttava, meni ulos ja puhutteli portinvartijatarta ja toi Pietarin sisälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 17, 'Niin palvelijatar, joka vartioi porttia, sanoi Pietarille: \"Etkö sinäkin ole tuon miehen opetuslapsia?\" Hän sanoi: \"En ole\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 18, 'Mutta palvelijat ja käskyläiset olivat tehneet hiilivalkean, koska oli kylmä, ja seisoivat ja lämmittelivät. Ja myös Pietari seisoi heidän kanssaan lämmittelemässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 19, 'Niin ylimmäinen pappi kysyi Jeesukselta hänen opetuslapsistaan ja opistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 20, 'Jeesus vastasi hänelle: \"Minä olen julkisesti puhunut maailmalle; minä olen aina opettanut synagoogissa ja pyhäkössä, joihin kaikki juutalaiset kokoontuvat, enkä ole salassa puhunut mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 21, 'Miksi minulta kysyt? Kysy niiltä, jotka ovat kuulleet, mitä minä olen heille puhunut; katso, he tietävät, mitä minä olen sanonut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 22, 'Mutta kun Jeesus oli tämän sanonut, antoi eräs palvelija, joka seisoi vieressä, hänelle korvapuustin sanoen: \"Niinkö sinä vastaat ylimmäiselle papille?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 23, 'Jeesus vastasi hänelle: \"Jos minä pahasti puhuin, niin näytä toteen, että se on pahaa; mutta jos minä puhuin oikein, miksi minua lyöt?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 24, 'Niin Hannas lähetti hänet sidottuna ylimmäisen papin Kaifaan luo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 25, 'Mutta Simon Pietari seisoi lämmittelemässä. Niin he sanoivat hänelle: \"Etkö sinäkin ole hänen opetuslapsiaan?\" Hän kielsi ja sanoi: \"En ole\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 26, 'Silloin eräs ylimmäisen papin palvelijoista, sen sukulainen, jolta Pietari oli sivaltanut korvan pois, sanoi: \"Enkö minä nähnyt sinua puutarhassa hänen kanssaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 27, 'Niin Pietari taas kielsi, ja samassa lauloi kukko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 28, 'Niin he veivät Jeesuksen Kaifaan luota palatsiin; ja oli varhainen aamu. Ja itse he eivät menneet sisälle palatsiin, etteivät saastuisi, vaan saattaisivat syödä pääsiäislammasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 29, 'Niin Pilatus meni ulos heidän luokseen ja sanoi: \"Mikä syytös ja kanne teillä on tätä miestä vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 30, 'He vastasivat ja sanoivat hänelle: \"Jos tämä ei olisi pahantekijä, emme olisi antaneet häntä sinun käsiisi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 31, 'Niin Pilatus sanoi heille: \"Ottakaa te hänet ja tuomitkaa hänet lakinne mukaan\". Juutalaiset sanoivat hänelle: \"Meidän ei ole lupa ketään tappaa\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 32, 'että Jeesuksen sana kävisi toteen, jonka hän oli sanonut, antaen tietää, minkälaisella kuolemalla hän oli kuoleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 33, 'Niin Pilatus meni taas sisälle palatsiin ja kutsui Jeesuksen ja sanoi hänelle: \"Oletko sinä juutalaisten kuningas?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 34, 'Jeesus vastasi hänelle: \"Itsestäsikö sen sanot, vai ovatko muut sen sinulle minusta sanoneet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 35, 'Pilatus vastasi: \"Olenko minä juutalainen? Oma kansasi ja ylipapit ovat antaneet sinut minun käsiini. Mitä olet tehnyt?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 36, 'Jeesus vastasi: \"Minun kuninkuuteni ei ole tästä maailmasta; jos minun kuninkuuteni olisi tästä maailmasta, niin minun palvelijani olisivat taistelleet, ettei minua olisi annettu juutalaisten käsiin; mutta nyt minun kuninkuuteni ei ole täältä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 37, 'Niin Pilatus sanoi hänelle: \"Sinä siis kuitenkin olet kuningas?\" Jeesus vastasi: \"Sinäpä sen sanot, että minä olen kuningas. Sitä varten minä olen syntynyt ja sitä varten maailmaan tullut, että minä todistaisin totuuden puolesta. Jokainen, joka on totuudesta, kuulee minun ääneni.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 38, 'Pilatus sanoi hänelle: \"Mikä on totuus?\" Ja sen sanottuaan hän taas meni ulos juutalaisten luo ja sanoi heille: \"Minä en löydä hänessä yhtäkään syytä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 39, 'Mutta te olette tottuneet siihen, että minä päästän teille yhden vangin irti pääsiäisenä; tahdotteko siis, että päästän teille juutalaisten kuninkaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 18, 40, 'Niin he taas huusivat sanoen: \"Älä häntä, vaan Barabbas!\" Mutta Barabbas oli ryöväri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 1, 'Silloin Pilatus otti Jeesuksen ja ruoskitti hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 2, 'Ja sotamiehet väänsivät kruunun orjantappuroista, panivat sen hänen päähänsä ja pukivat hänen ylleen purppuraisen vaipan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 3, 'ja tulivat hänen luoksensa ja sanoivat: \"Terve, juutalaisten kuningas\"; ja he antoivat hänelle korvapuusteja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 4, 'Pilatus meni taas ulos ja sanoi heille: \"Katso, minä tuon hänet ulos teille, tietääksenne, etten minä löydä hänessä yhtäkään syytä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 5, 'Niin Jeesus tuli ulos, orjantappurakruunu päässään ja purppurainen vaippa yllään. Ja Pilatus sanoi heille: \"Katso ihmistä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 6, 'Kun siis ylipapit ja palvelijat näkivät hänet, huusivat he sanoen: \"Ristiinnaulitse, ristiinnaulitse!\" Pilatus sanoi heille: \"Ottakaa te hänet ja ristiinnaulitkaa, sillä minä en löydä hänessä mitään syytä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 7, 'Juutalaiset vastasivat hänelle: \"Meillä on laki, ja lain mukaan hänen pitää kuoleman, koska hän on tehnyt itsensä Jumalan Pojaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 8, 'Kun nyt Pilatus kuuli tämän sanan, pelkäsi hän vielä enemmän');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 9, 'ja meni taas sisälle palatsiin ja sanoi Jeesukselle: \"Mistä sinä olet?\" Mutta Jeesus ei hänelle vastannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 10, 'Niin Pilatus sanoi hänelle: \"Etkö puhu minulle? Etkö tiedä, että minulla on valta sinut päästää ja minulla on valta sinut ristiinnaulita?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 11, 'Jeesus vastasi: \"Sinulla ei olisi mitään valtaa minuun, ellei sitä olisi annettu sinulle ylhäältä. Sentähden on sen synti suurempi, joka jätti minut sinun käsiisi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 12, 'Tämän tähden Pilatus koetti päästää hänet irti. Mutta juutalaiset huusivat sanoen: \"Jos päästät hänet, et ole keisarin ystävä; jokainen, joka tekee itsensä kuninkaaksi, asettuu keisaria vastaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 13, 'Kun Pilatus kuuli nämä sanat, antoi hän viedä Jeesuksen ulos ja istui tuomarinistuimelle, paikalle, jonka nimi on Litostroton, hebreaksi Gabbata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 14, 'Ja oli pääsiäisen valmistuspäivä, noin kuudes hetki. Ja hän sanoi juutalaisille: \"Katso, teidän kuninkaanne!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 15, 'Niin he huusivat: \"Vie pois, vie pois, ristiinnaulitse hänet!\" Pilatus sanoi heille: \"Onko minun ristiinnaulittava teidän kuninkaanne?\" Ylipapit vastasivat: \"Ei meillä ole kuningasta, vaan keisari\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 16, 'Silloin hän luovutti hänet heille ja antoi ristiinnaulittavaksi. Ja he ottivat Jeesuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 17, 'Ja kantaen itse omaa ristiänsä hän meni ulos niin sanotulle Pääkallonpaikalle, jota kutsutaan hebreankielellä Golgataksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 18, 'Siellä he hänet ristiinnaulitsivat ja hänen kanssaan kaksi muuta, yhden kummallekin puolelle, ja Jeesuksen keskelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 19, 'Ja Pilatus kirjoitti myös päällekirjoituksen ja kiinnitti sen ristiin; ja se oli näin kirjoitettu: \"Jeesus Nasaretilainen, juutalaisten kuningas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 20, 'Tämän päällekirjoituksen lukivat monet juutalaiset, sillä paikka, jossa Jeesus ristiinnaulittiin, oli lähellä kaupunkia; ja se oli kirjoitettu hebreaksi, latinaksi ja kreikaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 21, 'Niin juutalaisten ylipapit sanoivat Pilatukselle: \"Älä kirjoita: \'Juutalaisten kuningas\', vaan että hän on sanonut: \'Minä olen juutalaisten kuningas\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 22, 'Pilatus vastasi: \"Minkä minä kirjoitin, sen minä kirjoitin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 23, 'Kun sotamiehet olivat ristiinnaulinneet Jeesuksen, ottivat he hänen vaatteensa ja jakoivat ne neljään osaan, kullekin sotamiehelle osansa, sekä ihokkaan. Mutta ihokas oli saumaton, kauttaaltaan ylhäältä asti kudottu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 24, 'Sentähden he sanoivat toisillensa: \"Älkäämme leikatko sitä rikki, vaan heittäkäämme siitä arpaa, kenen se on oleva\"; että tämä kirjoitus kävisi toteen: \"He jakoivat keskenänsä minun vaatteeni ja heittivät minun puvustani arpaa\". Ja sotamiehet tekivät niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 25, 'Mutta Jeesuksen ristin ääressä seisoivat hänen äitinsä ja hänen äitinsä sisar ja Maria, Kloopaan vaimo, ja Maria Magdaleena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 26, 'Kun Jeesus näki äitinsä ja sen opetuslapsen, jota hän rakasti, seisovan siinä vieressä, sanoi hän äidillensä: \"Vaimo, katso, poikasi!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 27, 'Sitten hän sanoi opetuslapselle: \"Katso, äitisi!\" Ja siitä hetkestä opetuslapsi otti hänet kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 28, 'Sen jälkeen, kun Jeesus tiesi, että kaikki jo oli täytetty, sanoi hän, että kirjoitus kävisi toteen: \"Minun on jano\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 29, 'Siinä oli astia, hapanviiniä täynnä; niin he täyttivät sillä hapanviinillä sienen ja panivat sen isoppikorren päähän ja ojensivat sen hänen suunsa eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 30, 'Kun nyt Jeesus oli ottanut hapanviinin, sanoi hän: \"Se on täytetty\", ja kallisti päänsä ja antoi henkensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 31, 'Koska silloin oli valmistuspäivä, niin-etteivät ruumiit jäisi ristille sapatiksi, sillä se sapatinpäivä oli suuri-juutalaiset pyysivät Pilatukselta, että ristiinnaulittujen sääriluut rikottaisiin ja ruumiit otettaisiin alas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 32, 'Niin sotamiehet tulivat ja rikkoivat sääriluut ensin toiselta ja sitten toiselta hänen kanssaan ristiinnaulitulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 33, 'Mutta kun he tulivat Jeesuksen luo ja näkivät hänet jo kuolleeksi, eivät he rikkoneet hänen luitaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 34, 'vaan yksi sotamiehistä puhkaisi keihäällä hänen kylkensä, ja heti vuoti siitä verta ja vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 35, 'Ja joka sen näki, on sen todistanut, ja hänen todistuksensa on tosi, ja hän tietää totta puhuvansa, että tekin uskoisitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 36, 'Sillä tämä tapahtui, että kirjoitus kävisi toteen: \"Älköön häneltä luuta rikottako\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 37, 'Ja vielä sanoo toinen kirjoitus: \"He luovat katseensa häneen, jonka he ovat lävistäneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 38, 'Mutta sen jälkeen Joosef, arimatialainen, joka oli Jeesuksen opetuslapsi, vaikka salaa, juutalaisten pelosta, pyysi Pilatukselta saada ottaa Jeesuksen ruumiin; ja Pilatus myöntyi siihen. Niin hän tuli ja otti Jeesuksen ruumiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 39, 'Tuli myös Nikodeemus, joka ensi kerran oli yöllä tullut Jeesuksen tykö, ja toi mirhan ja aloen seosta noin sata naulaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 40, 'Niin he ottivat Jeesuksen ruumiin ja käärivät sen hyvänhajuisten yrttien kanssa käärinliinoihin, niinkuin juutalaisilla on tapana haudata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 41, 'Ja sillä paikalla, missä hänet ristiinnaulittiin, oli puutarha, ja puutarhassa uusi hauta, johon ei vielä oltu ketään pantu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 19, 42, 'Siihen he nyt panivat Jeesuksen, koska oli juutalaisten valmistuspäivä ja se hauta oli lähellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 1, 'Mutta viikon ensimmäisenä päivänä Maria Magdaleena meni varhain, kun vielä oli pimeä, haudalle ja näki kiven otetuksi pois haudan suulta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 2, 'Niin hän riensi pois ja tuli Simon Pietarin luo ja sen toisen opetuslapsen luo, joka oli Jeesukselle rakas, ja sanoi heille: \"Ovat ottaneet Herran pois haudasta, emmekä tiedä, mihin ovat hänet panneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 3, 'Niin Pietari ja se toinen opetuslapsi lähtivät ja menivät haudalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 4, 'Ja he juoksivat molemmat yhdessä; mutta se toinen opetuslapsi juoksi edellä, nopeammin kuin Pietari, ja saapui ensin haudalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 5, 'Ja kun hän kurkisti sisään, näki hän käärinliinat siellä; kuitenkaan hän ei mennyt sisälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 6, 'Niin Simon Pietarikin tuli hänen perässään ja meni sisälle hautaan ja näki käärinliinat siellä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 7, 'ja hikiliinan, joka oli ollut hänen päässään, ei pantuna yhteen käärinliinojen kanssa, vaan toiseen paikkaan erikseen kokoonkäärittynä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 8, 'Silloin toinenkin opetuslapsi, joka ensimmäisenä oli tullut haudalle, meni sisään ja näki ja uskoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 9, 'Sillä he eivät vielä ymmärtäneet Raamattua, että hän oli kuolleista nouseva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 10, 'Niin opetuslapset menivät takaisin kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 11, 'Mutta Maria seisoi haudan edessä ulkopuolella ja itki. Kun hän näin itki, kurkisti hän hautaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 12, 'ja näki kaksi enkeliä valkeissa vaatteissa istuvan, toisen pääpuolessa ja toisen jalkapuolessa, siinä, missä Jeesuksen ruumis oli maannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 13, 'Nämä sanoivat hänelle: \"Vaimo, mitä itket?\" Hän sanoi heille: \"Ovat ottaneet pois minun Herrani, enkä tiedä, mihin ovat hänet panneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 14, 'Tämän sanottuaan hän kääntyi taaksepäin ja näki Jeesuksen siinä seisovan, eikä tiennyt, että se oli Jeesus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 15, 'Jeesus sanoi hänelle: \"Vaimo, mitä itket? Ketä etsit?\" Tämä luuli häntä puutarhuriksi ja sanoi hänelle: \"Herra, jos sinä olet kantanut hänet pois, sano minulle, mihin olet hänet pannut, niin minä otan hänet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 16, 'Jeesus sanoi hänelle: \"Maria!\" Tämä kääntyi ja sanoi hänelle hebreankielellä: \"Rabbuuni!\" se on: opettaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 17, 'Jeesus sanoi hänelle: \"Älä minuun koske, sillä en minä ole vielä mennyt ylös Isäni tykö; mutta mene minun veljieni tykö ja sano heille, että minä menen ylös, minun Isäni tykö ja teidän Isänne tykö, ja minun Jumalani tykö ja teidän Jumalanne tykö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 18, 'Maria Magdaleena meni ja ilmoitti opetuslapsille, että hän oli nähnyt Herran ja että Herra oli hänelle näin sanonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 19, 'Samana päivänä, viikon ensimmäisenä, myöhään illalla, kun opetuslapset olivat koolla lukittujen ovien takana, juutalaisten pelosta, tuli Jeesus ja seisoi heidän keskellään ja sanoi heille: \"Rauha teille!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 20, 'Ja sen sanottuaan hän näytti heille kätensä ja kylkensä. Niin opetuslapset iloitsivat nähdessään Herran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 21, 'Niin Jeesus sanoi heille jälleen: \"Rauha teille! Niinkuin Isä on lähettänyt minut, niin lähetän minäkin teidät.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 22, 'Ja tämän sanottuaan hän puhalsi heidän päällensä ja sanoi heille: \"Ottakaa Pyhä Henki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 23, 'Joiden synnit te anteeksi annatte, niille ne ovat anteeksi annetut; joiden synnit te pidätätte, niille ne ovat pidätetyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 24, 'Mutta Tuomas, jota sanottiin Didymukseksi, yksi niistä kahdestatoista, ei ollut heidän kanssansa, kun Jeesus tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 25, 'Niin muut opetuslapset sanoivat hänelle: \"Me näimme Herran\". Mutta hän sanoi heille: \"Ellen näe hänen käsissään naulojen jälkiä ja pistä sormeani naulojen sijoihin ja pistä kättäni hänen kylkeensä, en minä usko\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 26, 'Ja kahdeksan päivän perästä hänen opetuslapsensa taas olivat huoneessa, ja Tuomas oli heidän kanssansa. Niin Jeesus tuli, ovien ollessa lukittuina, ja seisoi heidän keskellään ja sanoi: \"Rauha teille!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 27, 'Sitten hän sanoi Tuomaalle: \"Ojenna sormesi tänne ja katso minun käsiäni, ja ojenna kätesi ja pistä se minun kylkeeni, äläkä ole epäuskoinen, vaan uskovainen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 28, 'Tuomas vastasi ja sanoi hänelle: \"Minun Herrani ja minun Jumalani!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 29, 'Jeesus sanoi hänelle: \"Sentähden, että minut näit, sinä uskot. Autuaat ne, jotka eivät näe ja kuitenkin uskovat!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 30, 'Paljon muitakin tunnustekoja, joita ei ole kirjoitettu tähän kirjaan, Jeesus teki opetuslastensa nähden;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 20, 31, 'mutta nämä ovat kirjoitetut, että te uskoisitte, että Jeesus on Kristus, Jumalan Poika, ja että teillä uskon kautta olisi elämä hänen nimessänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 1, 'Sen jälkeen Jeesus taas ilmestyi opetuslapsilleen Tiberiaan järven rannalla; ja hän ilmestyi näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 2, 'Simon Pietari ja Tuomas, jota sanottiin Didymukseksi, ja Natanael, joka oli Galilean Kaanasta, ja Sebedeuksen pojat sekä kaksi muuta hänen opetuslapsistaan olivat yhdessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 3, 'Simon Pietari sanoi heille: \"Minä menen kalaan\". He sanoivat hänelle: \"Me lähdemme myös sinun kanssasi\". Niin he lähtivät ja astuivat venheeseen; mutta eivät sinä yönä saaneet mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 4, 'Ja kun jo oli aamu, seisoi Jeesus rannalla. Opetuslapset eivät kuitenkaan tienneet, että se oli Jeesus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 5, 'Niin Jeesus sanoi heille: \"Lapset, onko teillä mitään syötävää?\" He vastasivat hänelle: \"Ei ole\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 6, 'Hän sanoi heille: \"Heittäkää verkko oikealle puolelle venhettä, niin saatte\". He heittivät verkon, mutta eivät jaksaneet vetää sitä ylös kalojen paljouden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 7, 'Silloin se opetuslapsi, jota Jeesus rakasti, sanoi Pietarille: \"Se on Herra\". Kun Simon Pietari kuuli, että se oli Herra, vyötti hän vaippansa ympärilleen, sillä hän oli ilman vaatteita, ja heittäytyi järveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 8, 'Mutta muut opetuslapset tulivat venheellä ja vetivät perässään verkkoa kaloineen, sillä he eivät olleet maasta kauempana kuin noin kahdensadan kyynärän päässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 9, 'Kun he astuivat maalle, näkivät he siellä hiilloksen ja kalan pantuna sen päälle, sekä leipää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 10, 'Jeesus sanoi heille: \"Tuokaa tänne niitä kaloja, joita nyt saitte\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 11, 'Niin Simon Pietari astui venheeseen ja veti maalle verkon, täynnä suuria kaloja, sata viisikymmentä kolme. Ja vaikka niitä oli niin paljon, ei verkko revennyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 12, 'Jeesus sanoi heille: \"Tulkaa einehtimään\". Mutta ei kukaan opetuslapsista uskaltanut kysyä häneltä: \"Kuka sinä olet?\", koska he tiesivät, että se oli Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 13, 'Niin Jeesus meni ja otti leivän ja antoi heille, ja samoin kalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 14, 'Tämä oli jo kolmas kerta, jolloin Jeesus noustuaan kuolleista ilmestyi opetuslapsillensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 15, 'Kun he olivat einehtineet, sanoi Jeesus Simon Pietarille: \"Simon, Johanneksen poika, rakastatko sinä minua enemmän kuin nämä?\" Hän vastasi hänelle: \"Rakastan, Herra; sinä tiedät, että olet minulle rakas\". Hän sanoi hänelle: \"Ruoki minun karitsoitani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 16, 'Hän sanoi hänelle taas toistamiseen: \"Simon, Johanneksen poika, rakastatko minua?\" Hän vastasi hänelle: \"Rakastan, Herra; sinä tiedät, että olet minulle rakas\". Hän sanoi hänelle: \"Kaitse minun lampaitani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 17, 'Hän sanoi hänelle kolmannen kerran: \"Simon, Johanneksen poika, olenko minä sinulle rakas?\" Pietari tuli murheelliseksi siitä, että hän kolmannen kerran sanoi hänelle: \"Olenko minä sinulle rakas?\" ja vastasi hänelle: \"Herra, sinä tiedät kaikki; sinä tiedät, että olet minulle rakas\". Jeesus sanoi hänelle: \"Ruoki minun lampaitani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 18, 'Totisesti, totisesti minä sanon sinulle: kun olit nuori, niin sinä vyötit itsesi ja kuljit, minne tahdoit; mutta kun vanhenet, niin sinä ojennat kätesi, ja sinut vyöttää toinen ja vie sinut, minne et tahdo.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 19, 'Mutta sen hän sanoi antaakseen tietää, minkäkaltaisella kuolemalla Pietari oli kirkastava Jumalaa. Ja tämän sanottuaan hän lausui hänelle: \"Seuraa minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 20, 'Niin Pietari kääntyi ja näki sen opetuslapsen seuraavan, jota Jeesus rakasti ja joka myös oli aterioitaessa nojannut hänen rintaansa vasten ja sanonut: \"Herra, kuka on sinun kavaltajasi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 21, 'Kun Pietari hänet näki, sanoi hän Jeesukselle: \"Herra, kuinka sitten tämän käy?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 22, 'Jeesus sanoi hänelle: \"Jos minä tahtoisin, että hän jää tänne siihen asti, kunnes minä tulen, mitä se sinuun koskee? Seuraa sinä minua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 23, 'Niin semmoinen puhe levisi veljien keskuuteen, ettei se opetuslapsi kuole; mutta ei Jeesus sanonut hänelle, ettei hän kuole, vaan: \"Jos minä tahtoisin, että hän jää tänne siihen asti, kunnes minä tulen, mitä se sinuun koskee?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 24, 'Tämä on se opetuslapsi, joka todistaa näistä ja on nämä kirjoittanut; ja me tiedämme, että hänen todistuksensa on tosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 21, 25, 'On paljon muutakin, mitä Jeesus teki; ja jos se kohta kohdalta kirjoitettaisiin. luulen, etteivät koko maailmaan mahtuisi ne kirjat, jotka pitäisi kirjoittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Edellisessä kertomuksessani kirjoitin, oi Teofilus, kaikesta, mitä Jeesus alkoi tehdä ja opettaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'hamaan siihen päivään asti, jona hänet otettiin ylös, sittenkun hän Pyhän Hengen kautta oli antanut käskynsä apostoleille, jotka hän oli valinnut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'ja joille hän myös kärsimisensä jälkeen moninaisten epäämättömien todistusten kautta osoitti elävänsä, ilmestyen heille neljänkymmenen päivän aikana ja puhuen Jumalan valtakunnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Ja kun hän oli yhdessä heidän kanssansa, käski hän heitä ja sanoi: \"Älkää lähtekö Jerusalemista, vaan odottakaa Isältä sen lupauksen täyttymistä, jonka te olette minulta kuulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Sillä Johannes kastoi vedellä, mutta teidät kastetaan Pyhällä Hengellä, ei kauan näitten päivien jälkeen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'Niin he ollessansa koolla kysyivät häneltä sanoen: \"Herra, tälläkö ajalla sinä jälleen rakennat Israelille valtakunnan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'Hän sanoi heille: \"Ei ole teidän asianne tietää aikoja eikä hetkiä, jotka Isä oman valtansa voimalla on asettanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'vaan, kun Pyhä Henki tulee teihin, niin te saatte voiman, ja te tulette olemaan minun todistajani sekä Jerusalemissa että koko Juudeassa ja Samariassa ja aina maan ääriin saakka\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Kun hän oli tämän sanonut, kohotettiin hänet ylös heidän nähtensä, ja pilvi vei hänet pois heidän näkyvistään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Ja kun he katselivat taivaalle hänen mennessään, niin katso, heidän tykönänsä seisoi kaksi miestä valkeissa vaatteissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'ja nämä sanoivat: \"Galilean miehet, mitä te seisotte ja katsotte taivaalle? Tämä Jeesus, joka otettiin teiltä ylös taivaaseen, on tuleva samalla tavalla, kuin te näitte hänen taivaaseen menevän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Silloin he palasivat Jerusalemiin vuorelta, jota kutsutaan Öljymäeksi ja joka on lähellä Jerusalemia, sapatinmatkan päässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Ja kun he olivat tulleet kaupunkiin, menivät he siihen yläsaliin, jossa he tavallisesti oleskelivat: Pietari ja Johannes ja Jaakob ja Andreas, Filippus ja Tuomas, Bartolomeus ja Matteus, Jaakob Alfeuksen poika ja Simon, kiivailija, ja Juudas Jaakobin poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Nämä kaikki pysyivät yksimielisesti rukouksessa vaimojen kanssa ja Marian, Jeesuksen äidin, kanssa ja Jeesuksen veljien kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Ja niinä päivinä Pietari nousi veljien keskellä, kun oli väkeä koolla noin sata kaksikymmentä henkeä, ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, '\"Miehet, veljet, sen raamatunsanan piti käymän toteen, jonka Pyhä Henki on Daavidin suun kautta edeltä puhunut Juudaasta, joka rupesi niiden oppaaksi, jotka ottivat kiinni Jeesuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Sillä hän oli meidän joukkoomme luettu ja oli saanut osalleen tämän viran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Hän hankki itsellensä pellon väärintekonsa palkalla, ja hän suistui alas ja pakahtui keskeltä, niin että kaikki hänen sisälmyksensä valuivat ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Ja se tuli kaikkien Jerusalemin asukasten tietoon; ja niin sitä peltoa kutsutaan heidän kielellään Akeldamaksi, se on: Veripelloksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Sillä psalmien kirjassa on kirjoitettuna: \'Tulkoon hänen talonsa autioksi, älköönkä siinä asukasta olko\', ja: Ottakoon toinen hänen kaitsijatoimensa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Niin pitää siis yhden niistä miehistä, jotka ovat vaeltaneet meidän kanssamme kaiken sen ajan, jona Herra Jeesus kävi sisälle ja ulos meidän tykönämme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 22, 'Johanneksen kasteesta alkaen hamaan siihen päivään, jona hänet meiltä otettiin ylös, tuleman hänen ylösnousemisensa todistajaksi meidän kanssamme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 23, 'Ja he asettivat ehdolle kaksi, Joosefin, jota kutsuttiin Barsabbaaksi, lisänimeltä Justukseksi, ja Mattiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 24, 'Ja he rukoilivat ja sanoivat: \"Herra, sinä, joka kaikkien sydämet tunnet, osoita, kummanko näistä kahdesta sinä olet valinnut');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 25, 'ottamaan sen paikan tässä palveluksessa ja apostolinvirassa, josta Juudas vilpistyi pois, mennäkseen omaan paikkaansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 26, 'Ja he heittivät heistä arpaa, ja arpa lankesi Mattiaalle, ja hänet luettiin niiden yhdentoista kanssa apostolien joukkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Ja kun helluntaipäivä oli tullut, olivat he kaikki yhdessä koolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Ja tuli yhtäkkiä humaus taivaasta, niinkuin olisi käynyt väkevä tuulispää, ja täytti koko huoneen, jossa he istuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Ja he näkivät ikäänkuin tulisia kieliä, jotka jakaantuivat ja asettuivat heidän itsekunkin päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Ja he tulivat kaikki Pyhällä Hengellä täytetyiksi ja alkoivat puhua muilla kielillä, sen mukaan mitä Henki heille puhuttavaksi antoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Ja Jerusalemissa asui juutalaisia, jumalaapelkääväisiä miehiä, kaikkinaisista kansoista, mitä taivaan alla on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Ja kun tämä ääni kuului, niin kokoontui paljon kansaa; ja he tulivat ymmälle, sillä kukin kuuli heidän puhuvan hänen omaa kieltänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'Ja he hämmästyivät ja ihmettelivät sanoen: \"Katso, eivätkö nämä kaikki, jotka puhuvat, ole galilealaisia?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Kuinka me sitten kuulemme kukin sen maan kieltä, jossa olemme syntyneet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Me parttilaiset ja meedialaiset ja eelamilaiset ja me, jotka asumme Mesopotamiassa, Juudeassa ja Kappadokiassa, Pontossa ja Aasiassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'Frygiassa ja Pamfyliassa, Egyptissä ja Kyrenen puoleisen Liibyan alueilla, ja täällä oleskelevat roomalaiset, juutalaiset ja käännynnäiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'kreetalaiset ja arabialaiset, me kuulemme kukin heidän puhuvan omalla kielellämme Jumalan suuria tekoja.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Ja he olivat kaikki hämmästyksissään eivätkä tienneet, mitä ajatella, ja sanoivat toinen toisellensa: \"Mitä tämä mahtaakaan olla?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Mutta toiset pilkkasivat heitä ja sanoivat: \"He ovat täynnä makeata viiniä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Niin Pietari astui esiin niiden yhdentoista kanssa, korotti äänensä ja puhui heille: \"Miehet, juutalaiset ja kaikki Jerusalemissa asuvaiset, olkoon tämä teille tiettävä, ja ottakaa minun sanani korviinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Eivät nämä ole juovuksissa, niinkuin te luulette; sillä nyt on vasta kolmas hetki päivästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Vaan tämä on se, mikä on sanottu profeetta Jooelin kautta:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, '\'Ja on tapahtuva viimeisinä päivinä, sanoo Jumala, että minä vuodatan Henkeni kaiken lihan päälle, ja teidän poikanne ja tyttärenne ennustavat, ja nuorukaisenne näkyjä näkevät, ja vanhuksenne unia uneksuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Ja myös palvelijaini ja palvelijattarieni päälle minä niinä päivinä vuodatan Henkeni, ja he ennustavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Ja minä annan näkyä ihmeitä ylhäällä taivaalla ja merkkejä alhaalla maan päällä, verta ja tulta ja savupatsaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Aurinko muuttuu pimeydeksi ja kuu vereksi, ennenkuin Herran päivä tulee, se suuri ja julkinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Ja on tapahtuva, että jokainen, joka huutaa avuksi Herran nimeä, pelastuu.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Te Israelin miehet, kuulkaa nämä sanat: Jeesuksen, Nasaretilaisen, sen miehen, josta Jumala todisti teille voimallisilla teoilla ja ihmeillä ja merkeillä, joita Jumala hänen kauttansa teki teidän keskellänne, niinkuin te itse tiedätte,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 23, 'hänet, joka teille luovutettiin, Jumalan ennaltamäärätyn päätöksen ja edeltätietämyksen mukaan, te laista tietämättömien miesten kätten kautta naulitsitte ristille ja tapoitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 24, 'Hänet Jumala herätti ja päästi kuoleman kivuista, niinkuin ei ollutkaan mahdollista, että kuolema olisi voinut hänet pitää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 25, 'Sillä Daavid sanoo hänestä: \'Minä näen alati edessäni Herran, sillä hän on minun oikealla puolellani, etten horjahtaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 26, 'Sentähden minun sydämeni iloitsee ja kieleni riemuitsee, ja myös minun ruumiini on lepäävä toivossa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 27, 'sillä sinä et hylkää minun sieluani tuonelaan etkä salli Pyhäsi nähdä katoavaisuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 28, 'Sinä teet minulle tiettäviksi elämän tiet, sinä täytät minut ilolla kasvojesi edessä.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 29, 'Te miehet, veljet, on lupa teille rohkeasti sanoa, mitä kantaisäämme Daavidiin tulee, että hän on sekä kuollut että haudattu; onhan hänen hautansa meidän keskellämme vielä tänäkin päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 30, 'Koska hän nyt oli profeetta ja tiesi, että Jumala oli valalla vannoen hänelle luvannut asettavansa hänen kupeittensa hedelmän hänen valtaistuimelleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 31, 'niin hän edeltä nähden puhui Kristuksen ylösnousemuksesta, sanoen, ettei Kristus ollut jäävä hyljätyksi tuonelaan eikä hänen ruumiinsa näkevä katoavaisuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 32, 'Tämän Jeesuksen on Jumala herättänyt, minkä todistajia me kaikki olemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 33, 'Koska hän siis on Jumalan oikean käden voimalla korotettu ja on Isältä saanut Pyhän Hengen lupauksen, on hän vuodattanut sen, minkä te nyt näette ja kuulette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 34, 'Sillä ei Daavid ole astunut ylös taivaisiin, vaan hän sanoo itse: \'Herra sanoi minun Herralleni: Istu minun oikealle puolelleni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 35, 'kunnes minä panen sinun vihollisesi sinun jalkojesi astinlaudaksi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 36, 'Varmasti tietäköön siis koko Israelin huone, että Jumala on hänet Herraksi ja Kristukseksi tehnyt, tämän Jeesuksen, jonka te ristiinnaulitsitte.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 37, 'Kun he tämän kuulivat, saivat he piston sydämeensä ja sanoivat Pietarille ja muille apostoleille: \"Miehet, veljet, mitä meidän pitää tekemän?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 38, 'Niin Pietari sanoi heille: \"Tehkää parannus ja ottakoon kukin teistä kasteen Jeesuksen Kristuksen nimeen syntienne anteeksisaamiseksi, niin te saatte Pyhän Hengen lahjan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 39, 'Sillä teille ja teidän lapsillenne tämä lupaus on annettu ja kaikille, jotka kaukana ovat, ketkä ikinä Herra, meidän Jumalamme, kutsuu.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 40, 'Ja monilla muillakin sanoilla hän vakaasti todisti; ja hän kehoitti heitä sanoen: \"Antakaa pelastaa itsenne tästä nurjasta sukupolvesta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 41, 'Jotka nyt ottivat hänen sanansa vastaan, ne kastettiin, ja niin heitä lisääntyi sinä päivänä noin kolmetuhatta sielua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 42, 'Ja he pysyivät apostolien opetuksessa ja keskinäisessä yhteydessä ja leivän murtamisessa ja rukouksissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 43, 'Ja jokaiselle sielulle tuli pelko; ja monta ihmettä ja tunnustekoa tapahtui apostolien kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 44, 'Ja kaikki, jotka uskoivat, olivat yhdessä ja pitivät kaikkea yhteisenä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 45, 'ja he myivät maansa ja tavaransa ja jakelivat kaikille, sen mukaan kuin kukin tarvitsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 46, 'Ja he olivat alati, joka päivä, yksimielisesti pyhäkössä ja mursivat kodeissa leipää ja nauttivat ruokansa riemulla ja sydämen yksinkertaisuudella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 47, 'kiittäen Jumalaa ja ollen kaiken kansan suosiossa. Ja Herra lisäsi heidän yhteyteensä joka päivä niitä, jotka saivat pelastuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Ja Pietari ja Johannes menivät pyhäkköön yhdeksännellä hetkellä, rukoushetkellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Silloin kannettiin esille miestä, joka oli ollut rampa hamasta äitinsä kohdusta ja jonka he joka päivä panivat pyhäkön niin kutsutun Kauniin portin pieleen anomaan almua pyhäkköön meneviltä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Nähdessään Pietarin ja Johanneksen, kun he olivat menossa pyhäkköön, hän pyysi heiltä almua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'Niin Pietari ja Johannes katsoivat häneen kiinteästi, ja Pietari sanoi: \"Katso meihin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Ja hän tarkkasi heitä odottaen heiltä jotakin saavansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Niin Pietari sanoi: \"Hopeaa ja kultaa ei minulla ole, mutta mitä minulla on, sitä minä sinulle annan: Jeesuksen Kristuksen, Nasaretilaisen, nimessä, nouse ja käy.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Ja hän tarttui hänen oikeaan käteensä ja nosti hänet ylös; ja heti hänen jalkansa ja nilkkansa vahvistuivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'ja hän hypähti pystyyn, seisoi ja käveli; ja hän meni heidän kanssansa pyhäkköön, käyden ja hypellen ja ylistäen Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Ja kaikki kansa näki hänen kävelevän ja ylistävän Jumalaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'ja he tunsivat hänet siksi, joka almuja saadakseen oli istunut pyhäkön Kauniin portin pielessä, ja he olivat täynnä hämmästystä ja ihmettelyä siitä, mikä hänelle oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Ja kun hän yhä pysyttäytyi Pietarin ja Johanneksen seurassa, riensi kaikki kansa hämmästyksen vallassa heidän luoksensa niin sanottuun Salomon pylväskäytävään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Sen nähdessään Pietari rupesi puhumaan kansalle ja sanoi: \"Israelin miehet, mitä te tätä ihmettelette, tai mitä te meitä noin katselette, ikäänkuin me omalla voimallamme tai hurskaudellamme olisimme saaneet hänet kävelemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Aabrahamin ja Iisakin ja Jaakobin Jumala, meidän isiemme Jumala, on kirkastanut Poikansa Jeesuksen, jonka te annoitte alttiiksi ja kielsitte Pilatuksen edessä, kun tämä oli päättänyt hänet päästää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Te kielsitte Pyhän ja Vanhurskaan ja anoitte, että teille annettaisiin murhamies,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'mutta elämän ruhtinaan te tapoitte; hänet Jumala on herättänyt kuolleista, ja me olemme sen todistajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Ja uskon kautta hänen nimeensä on hänen nimensä vahvistanut tämän miehen, jonka te näette ja tunnette, ja usko, jonka Jeesus vaikuttaa, on hänelle antanut hänen jäsentensä terveyden kaikkien teidän nähtenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Ja nyt, veljet, minä tiedän, että te olette tietämättömyydestä sen tehneet, te niinkuin teidän hallitusmiehennekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Mutta näin on Jumala täyttänyt sen, minkä hän oli edeltä ilmoittanut kaikkien profeettain suun kautta, että nimittäin hänen Voideltunsa piti kärsimän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 19, 'Tehkää siis parannus ja kääntykää, että teidän syntinne pyyhittäisiin pois,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 20, 'että virvoituksen ajat tulisivat Herran kasvoista ja hän lähettäisi hänet, joka on teille edeltämäärätty, Kristuksen Jeesuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 21, 'Taivaan piti omistaman hänet niihin aikoihin asti, jolloin kaikki jälleen kohdallensa asetetaan, mistä Jumala on ikiajoista saakka puhunut pyhäin profeettainsa suun kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 22, 'Sillä Mooses on sanonut: \'Profeetan, minun kaltaiseni, Herra Jumala on teille herättävä veljienne joukosta; häntä kuulkaa kaikessa, mitä hän teille puhuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 23, 'Ja on tapahtuva, että jokainen, joka ei sitä profeettaa kuule, hävitetään kansasta.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 24, 'Ja kaikki profeetat Samuelista alkaen ja kaikki järjestään, jotka puhuneet ovat, ovat myös ennustaneet näitä päiviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 25, 'Te olette profeettain ja sen liiton lapsia, jonka Jumala teki meidän isiemme kanssa sanoen Aabrahamille: \'Ja sinun siemenessäsi tulevat siunatuiksi kaikki maan sukukunnat\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 26, 'Teille ensiksi Jumala on herättänyt Poikansa ja lähettänyt hänet siunaamaan teitä, kun käännytte itsekukin pois pahuudestanne.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 1, 'Mutta kun he puhuivat kansalle, astuivat papit ja pyhäkön vartioston päällikkö ja saddukeukset heidän eteensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 2, 'närkästyneinä siitä, että he opettivat kansaa ja julistivat Jeesuksessa ylösnousemusta kuolleista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 3, 'Ja he kävivät heihin käsiksi ja panivat heidät vankeuteen seuraavaan päivään asti, sillä oli jo ehtoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 4, 'Mutta monet niistä, jotka olivat kuulleet sanan, uskoivat, ja miesten luku nousi noin viiteentuhanteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 5, 'Seuraavana päivänä heidän hallitusmiehensä ja vanhimpansa ja kirjanoppineensa kokoontuivat Jerusalemissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 6, 'niin myös ylimmäinen pappi Hannas ja Kaifas ja Johannes ja Aleksander sekä kaikki, jotka olivat ylimmäispapillista sukua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 7, 'Ja he asettivat heidät eteensä ja kysyivät: \"Millä voimalla tai kenen nimeen te tämän teitte?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 8, 'Silloin Pietari, Pyhää Henkeä täynnä, sanoi heille: \"Kansan hallitusmiehet ja vanhimmat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 9, 'Jos meitä tänään kuulustellaan sairaalle miehelle tehdystä hyvästä työstä ja siitä, kenen kautta hän on parantunut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 10, 'niin olkoon teille kaikille ja koko Israelin kansalle tiettävä, että Jeesuksen Kristuksen, Nasaretilaisen, nimen kautta, hänen, jonka te ristiinnaulitsitte, mutta jonka Jumala kuolleista herätti, hänen nimensä kautta tämä seisoo terveenä teidän edessänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 11, 'Hän on \'se kivi, jonka te, rakentajat, hylkäsitte, mutta joka on kulmakiveksi tullut\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 12, 'Eikä ole pelastusta yhdessäkään toisessa; sillä ei ole taivaan alla muuta nimeä ihmisille annettu, jossa meidän pitäisi pelastuman.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 13, 'Mutta kun he näkivät Pietarin ja Johanneksen rohkeuden ja havaitsivat heidän olevan koulunkäymättömiä ja oppimattomia miehiä, he ihmettelivät; ja he tunsivat heidät niiksi, jotka olivat olleet Jeesuksen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 14, 'Ja nähdessään parannetun miehen seisovan heidän kanssansa he eivät voineet mitään vastaansanoa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 15, 'vaan käskettyään heidän astua ulos neuvostosta he pitivät keskenänsä neuvoa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 16, 'ja sanoivat: \"Mitä me teemme näille miehille? Sillä että heidän kauttansa on tapahtunut ilmeinen ihme, sen kaikki Jerusalemin asukkaat tietävät, emmekä me voi sitä kieltää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 17, 'Mutta ettei se leviäisi laajemmalle kansaan, niin kieltäkäämme ankarasti heitä enää tähän nimeen puhumasta yhdellekään ihmiselle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 18, 'Niin he kutsuivat heidät ja kielsivät heitä mitään puhumasta ja opettamasta Jeesuksen nimeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 19, 'Mutta Pietari ja Johannes vastasivat heille ja sanoivat: \"Päättäkää itse, onko oikein Jumalan edessä kuulla teitä enemmän kuin Jumalaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 20, 'mutta me emme voi olla puhumatta siitä, mitä olemme nähneet ja kuulleet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 21, 'Niin he uhkasivat heitä vielä enemmän ja päästivät heidät, koska eivät kansan tähden keksineet, miten rangaista heitä, sillä kaikki ylistivät Jumalaa siitä, mitä tapahtunut oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 22, 'Sillä sivu neljänkymmenen oli jo vuosiltaan se mies, jossa tämä parantumisen ihme oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 23, 'Ja päästyään vapaiksi he menivät omiensa tykö ja kertoivat kaiken, mitä ylipapit ja vanhimmat olivat heille sanoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 24, 'Sen kuultuansa he yksimielisesti korottivat äänensä Jumalan puoleen ja sanoivat: \"Herra, sinä, joka olet tehnyt taivaan ja maan ja meren ja kaikki, mitä niissä on!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 25, 'Sinä, joka Pyhän Hengen kautta, isämme Daavidin, sinun palvelijasi, suun kautta, olet puhunut: \'Miksi pakanat pauhaavat ja kansat turhia ajattelevat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 26, 'Maan kuninkaat nousevat, ja ruhtinaat kokoontuvat yhteen Herraa ja hänen Voideltuansa vastaan.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 27, 'Sillä totisesti, tässä kaupungissa kokoontuivat sinun pyhää Poikaasi Jeesusta vastaan, jonka sinä olet voidellut, sekä Herodes että Pontius Pilatus pakanain ja Israelin sukukuntain kanssa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 28, 'tekemään kaiken, minkä sinun kätesi ja päätöksesi oli edeltämäärännyt tapahtuvaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 29, 'Ja nyt, Herra, katso heidän uhkauksiansa ja anna palvelijaisi kaikella rohkeudella puhua sinun sanaasi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 30, 'ja ojenna kätesi, niin että sairaat parantuvat ja tunnustekoja ja ihmeitä tapahtuu sinun pyhän Poikasi Jeesuksen nimen kautta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 31, 'Ja kun he olivat rukoilleet, vapisi se paikka, jossa he olivat koolla, ja he tulivat kaikki Pyhällä Hengellä täytetyiksi ja puhuivat Jumalan sanaa rohkeasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 32, 'Ja uskovaisten suuressa joukossa oli yksi sydän ja yksi sielu; eikä kenkään heistä sanonut omaksensa mitään siitä, mitä hänellä oli, vaan kaikki oli heillä yhteistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 33, 'Ja apostolit todistivat suurella voimalla Herran Jeesuksen ylösnousemuksesta, ja suuri armo oli heillä kaikilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 34, 'Ei myöskään ollut heidän seassaan ketään puutteenalaista; sillä kaikki, joilla oli maatiloja tai taloja, myivät ne ja toivat myytyjen hinnan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 35, 'ja panivat apostolien jalkojen juureen; ja jokaiselle jaettiin sen mukaan, kuin hän tarvitsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 36, 'Niinpä Joosef, jota apostolit kutsuivat Barnabaaksi-se on käännettynä: kehoittaja-leeviläinen, syntyisin Kyprosta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 4, 37, 'myi omistamansa pellon, toi rahat ja pani ne apostolien jalkojen juureen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 1, 'Mutta eräs mies, nimeltä Ananias, ja hänen vaimonsa Safiira myivät maatilan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 2, 'ja mies kätki vaimonsa tieten osan hinnasta, ja osan hän toi ja pani apostolien jalkojen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 3, 'Mutta Pietari sanoi: \"Ananias, miksi on saatana täyttänyt sinun sydämesi, niin että koetit pettää Pyhää Henkeä ja kätkit osan maatilan hinnasta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 4, 'Eikö se myymätönnä ollut sinun omasi, ja eikö myynnin jälkeenkin sen hinta ollut sinun? Miksi päätit sydämessäsi tämän tehdä? Et sinä ole valhetellut ihmisille, vaan Jumalalle.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 5, 'Kun Ananias kuuli nämä sanat, kaatui hän maahan ja heitti henkensä. Ja suuri pelko valtasi kaikki, jotka sen kuulivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 6, 'Ja nuoret miehet nousivat ja korjasivat hänet ja kantoivat hänet pois ja hautasivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 7, 'Noin kolmen hetken kuluttua hänen vaimonsa tuli sisään eikä tiennyt, mitä oli tapahtunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 8, 'Niin Pietari kysyi häneltä: \"Sano minulle: siihenkö hintaan te myitte maatilan?\" Hän vastasi: \"Kyllä, juuri siihen hintaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 9, 'Mutta Pietari sanoi hänelle: \"Miksi olette yksissä neuvoin käyneet kiusaamaan Herran Henkeä? Katso, niiden jalat, jotka hautasivat sinun miehesi, ovat oven takana, ja he kantavat sinutkin pois.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 10, 'Niin hän heti kaatui hänen jalkojensa eteen ja heitti henkensä; ja kun nuorukaiset tulivat sisään, tapasivat he hänet kuolleena, kantoivat pois ja hautasivat hänet hänen miehensä viereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 11, 'Ja suuri pelko valtasi koko seurakunnan ja kaikki ne, jotka tämän kuulivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 12, 'Ja apostolien kätten kautta tapahtui kansassa monta tunnustekoa ja ihmettä; ja he olivat kaikki yksimielisesti koolla Salomon pylväskäytävässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 13, 'Eikä muista kukaan uskaltanut heihin liittyä, mutta kansa piti heitä suuressa kunniassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 14, 'Ja yhä enemmän karttui niitä, jotka uskoivat Herraan, sekä miehiä että naisia suuret joukot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 15, 'Kannettiinpa sairaita kaduillekin ja pantiin vuoteille ja paareille, että Pietarin kulkiessa edes hänen varjonsa sattuisi johonkuhun heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 16, 'Myöskin kaupungeista Jerusalemin ympäriltä tuli paljon kansaa, ja he toivat sairaita ja saastaisten henkien vaivaamia, ja ne kaikki tulivat parannetuiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 17, 'Silloin nousi ylimmäinen pappi ja kaikki, jotka olivat hänen puolellansa, saddukeusten lahko, ja he tulivat kiihkoa täyteen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 18, 'ja kävivät käsiksi apostoleihin ja panivat heidät yleiseen vankihuoneeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 19, 'Mutta yöllä avasi Herran enkeli vankilan ovet ja vei heidät ulos ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 20, '\"Menkää ja astukaa esiin ja puhukaa pyhäkössä kansalle kaikki tämän elämän sanat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 21, 'Sen kuultuansa he menivät päivän koittaessa pyhäkköön ja opettivat. Niin saapui ylimmäinen pappi ja ne, jotka olivat hänen puolellansa, ja he kutsuivat koolle neuvoston ja israelilaisten vanhinten kokouksen; ja he lähettivät noutamaan heitä vankilasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 22, 'Mutta kun oikeudenpalvelijat tulivat vankilaan, eivät he löytäneet heitä sieltä, vaan palasivat takaisin ja kertoivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 23, 'sanoen: \"Vankilan me kyllä huomasimme hyvin tarkasti suljetuksi ja vartijat seisomassa ovien edessä; mutta kun avasimme, emme sisältä ketään löytäneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 24, 'Kun pyhäkön vartioston päällikkö ja ylipapit kuulivat nämä sanat, eivät he tienneet, mitä heistä ajatella ja mitä tästä tulisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 25, 'Niin tuli joku ja kertoi heille: \"Katso, ne miehet, jotka te panitte vankilaan, seisovat pyhäkössä ja opettavat kansaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 26, 'Silloin päällikkö meni oikeudenpalvelijain kanssa ja nouti heidät; ei kuitenkaan väkisin, sillä he pelkäsivät, että kansa heidät kivittäisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 27, 'Ja he toivat heidät ja asettivat neuvoston eteen. Ja ylimmäinen pappi kuulusteli heitä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 28, 'ja sanoi: \"Me olemme kieltämällä kieltäneet teitä opettamasta tähän nimeen; ja katso, te olette täyttäneet Jerusalemin opetuksellanne ja tahdotte saattaa meidän päällemme tuon miehen veren\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 29, 'Mutta Pietari ja muut apostolit vastasivat ja sanoivat: \"Enemmän tulee totella Jumalaa kuin ihmisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 30, 'Meidän isiemme Jumala on herättänyt Jeesuksen, jonka te ripustitte puuhun ja surmasitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 31, 'Hänet on Jumala oikealla kädellänsä korottanut Päämieheksi ja Vapahtajaksi, antamaan Israelille parannusta ja syntien anteeksiantamusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 32, 'Ja me olemme kaiken tämän todistajat, niin myös Pyhä Henki, jonka Jumala on antanut niille, jotka häntä tottelevat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 33, 'Kun he sen kuulivat, viilsi se heidän sydäntänsä, ja he tahtoivat tappaa heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 34, 'Mutta neuvostossa nousi eräs fariseus, nimeltä Gamaliel, lainopettaja, jota koko kansa piti arvossa, ja hän käski viedä miehet vähäksi aikaa ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 35, 'Sitten hän sanoi neuvostolle: \"Israelin miehet, kavahtakaa, mitä aiotte tehdä näille miehille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 36, 'Sillä ennen näitä päiviä nousi Teudas, sanoen jokin olevansa, ja häneen liittyi noin neljäsataa miestä; hänet tapettiin, ja kaikki, jotka olivat häneen suostuneet, hajotettiin, ja he joutuivat häviöön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 37, 'Hänen jälkeensä nousi Juudas, galilealainen, verollepanon päivinä ja vietteli kansaa luopumaan puolellensa; hänkin hukkui, ja kaikki, jotka olivat suostuneet häneen, hajotettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 38, 'Ja nyt minä sanon teille: pysykää erillänne näistä miehistä ja antakaa heidän olla; sillä jos tämä hanke eli tämä teko on ihmisistä, niin se tyhjään raukeaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 39, 'mutta jos se on Jumalasta, niin te ette voi heitä kukistaa. Varokaa, ettei teitä ehkä havaittaisi sotiviksi itse Jumalaa vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 40, 'Niin he noudattivat hänen neuvoansa. Ja he kutsuivat apostolit sisään ja pieksättivät heitä ja kielsivät heitä puhumasta Jeesuksen nimeen ja päästivät heidät menemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 41, 'Niin he lähtivät pois neuvostosta iloissaan siitä, että olivat katsotut arvollisiksi kärsimään häväistystä Jeesuksen nimen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 5, 42, 'Eivätkä he lakanneet, vaan opettivat joka päivä pyhäkössä ja kodeissa ja julistivat evankeliumia Kristuksesta Jeesuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 1, 'Niinä päivinä, kun opetuslasten luku lisääntyi, syntyi hellenisteissä nurinaa hebrealaisia vastaan siitä, että heidän leskiänsä syrjäytettiin jokapäiväisessä avunannossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 2, 'Niin ne kaksitoista kutsuivat kokoon opetuslasten joukon ja sanoivat: \"Ei ole soveliasta, että me laiminlyömme Jumalan sanan toimittaaksemme pöytäpalvelusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 3, 'Valitkaa sentähden, veljet, keskuudestanne seitsemän miestä, joista on hyvä todistus ja jotka ovat Henkeä ja viisautta täynnä, niin me asetamme heidät tähän toimeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 4, 'Mutta me tahdomme pysyä rukouksessa ja sanan palveluksessa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 5, 'Ja se puhe kelpasi kaikelle joukolle; ja he valitsivat Stefanuksen, miehen, joka oli täynnä uskoa ja Pyhää Henkeä, ja Filippuksen ja Prokoruksen ja Nikanorin ja Timonin ja Parmenaan ja Nikolauksen, antiokialaisen käännynnäisen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 6, 'ja asettivat heidät apostolien eteen, ja nämä rukoilivat ja panivat kätensä heidän päällensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 7, 'Ja Jumalan sana menestyi, ja opetuslasten luku lisääntyi suuresti Jerusalemissa. Ja lukuisa joukko pappeja tuli uskolle kuuliaisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 8, 'Ja Stefanus, täynnä armoa ja voimaa, teki suuria ihmeitä ja tunnustekoja kansassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 9, 'Niin nousi muutamia niin kutsutusta libertiinien ja kyreniläisten ja aleksandrialaisten synagoogasta sekä niiden joukosta, jotka olivat Kilikiasta ja Aasiasta, väittelemään Stefanuksen kanssa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 10, 'mutta he eivät kyenneet pitämään puoliaan sitä viisautta ja henkeä vastaan, jolla hän puhui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 11, 'Silloin he salaa hankkivat miehiä sanomaan: \"Me olemme kuulleet hänen puhuvan pilkkasanoja Moosesta ja Jumalaa vastaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 12, 'Ja he yllyttivät kansan ja vanhimmat ja kirjanoppineet ja astuivat esiin, raastoivat hänet mukaansa ja veivät neuvoston eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 13, 'Ja he toivat esiin vääriä todistajia, jotka sanoivat: \"Tämä mies ei lakkaa puhumasta tätä pyhää paikkaa vastaan ja lakia vastaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 14, 'sillä me olemme kuulleet hänen sanovan, että Jeesus, tuo Nasaretilainen, on hajottava maahan tämän paikan ja muuttava ne säädökset, jotka Mooses on meille antanut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 6, 15, 'Ja kaikki, jotka neuvostossa istuivat, loivat katseensa häneen, ja hänen kasvonsa olivat heistä niinkuin enkelin kasvot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 1, 'Niin ylimmäinen pappi sanoi: \"Onko niin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 2, 'Stefanus sanoi: \"Miehet, veljet ja isät, kuulkaa! Kirkkauden Jumala ilmestyi meidän isällemme Aabrahamille hänen ollessaan Mesopotamiassa, ennenkuin hän oli asettunut asumaan Harraniin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 3, 'ja sanoi hänelle: \'Lähde maastasi ja suvustasi ja mene siihen maahan, jonka minä sinulle osoitan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 4, 'Silloin hän lähti kaldealaisten maasta ja asettui asumaan Harraniin. Ja kun hänen isänsä oli kuollut, siirsi Jumala hänet tähän maahan, jossa te nyt asutte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 5, 'Eikä hän antanut hänelle siinä perintöosaa, ei jalan leveyttäkään, vaan lupasi, Aabrahamin vielä lapsetonna ollessa, antaa sen hänelle ja hänen siemenelleen hänen jälkeensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 6, 'Ja Jumala puhui näin: \'Hänen jälkeläisensä tulevat olemaan muukalaisina vieraalla maalla, ja siellä ne tekevät heidät orjiksensa ja sortavat heitä neljäsataa vuotta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 7, 'ja sen kansan, jonka orjiksi he tulevat, minä olen tuomitseva\', sanoi Jumala, \'ja sen jälkeen he lähtevät sieltä ja palvelevat minua tässä paikassa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 8, 'Ja hän antoi hänelle ympärileikkauksen liiton; ja niin Aabrahamille syntyi Iisak, ja hän ympärileikkasi hänet kahdeksantena päivänä, ja Iisakille syntyi Jaakob, ja Jaakobille ne kaksitoista kantaisää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 9, 'Ja kantaisät kadehtivat Joosefia ja myivät hänet Egyptiin. Mutta Jumala oli hänen kanssansa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 10, 'ja pelasti hänet kaikista hänen ahdistuksistansa. Ja hän antoi hänelle armon ja viisauden faraon, Egyptin kuninkaan, edessä; ja tämä pani hänet Egyptin ja kaiken huoneensa haltijaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 11, 'Ja tuli nälänhätä koko Egyptiin ja Kanaaniin ja suuri vaiva, eivätkä meidän isämme saaneet mistään ravintoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 12, 'Mutta kun Jaakob kuuli Egyptissä olevan viljaa, lähetti hän meidän isämme sinne ensimmäisen kerran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 13, 'Ja toisella kerralla veljet tunsivat Joosefin, ja farao sai tietää Joosefin sukuperän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 14, 'Niin Joosef lähetti kutsumaan luokseen isänsä Jaakobin ja koko sukunsa, seitsemänkymmentä viisi henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 15, 'Ja Jaakob meni Egyptiin ja kuoli siellä, niin myös kuolivat isämme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 16, 'ja heidät siirrettiin Sikemiin ja pantiin siihen hautaan, jonka Aabraham oli rahalla ostanut Emmorin lapsilta Sikemissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 17, 'Mutta sitä mukaa kuin lähestyi sen lupauksen aika, jonka Jumala oli Aabrahamille antanut, kasvoi kansa ja lisääntyi Egyptissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 18, 'kunnes Egyptiä hallitsemaan nousi toinen kuningas, joka ei Joosefista mitään tiennyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 19, 'Tämä kohteli kavalasti meidän kansaamme ja sorti meidän isiämme ja pakotti heidät panemaan heitteille pienet lapsensa, etteivät ne jäisi eloon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 20, 'Siihen aikaan syntyi Mooses, ja hän oli Jumalalle otollinen. Häntä elätettiin kolme kuukautta isänsä kodissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 21, 'Mutta kun hänet oli pantu heitteille, otti faraon tytär hänet ja kasvatti hänet pojaksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 22, 'Ja Mooses kasvatettiin kaikkeen egyptiläisten viisauteen, ja hän oli voimallinen sanoissa ja teoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 23, 'Mutta kun hän oli täyttänyt neljäkymmentä vuotta, heräsi hänen sydämessään ajatus mennä katsomaan veljiänsä, israelilaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 24, 'Ja nähdessään eräälle heistä vääryyttä tehtävän hän puolusti häntä ja kosti pahoinpidellyn puolesta ja löi egyptiläisen kuoliaaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 25, 'Ja hän luuli veljiensä ymmärtävän, että Jumala hänen kätensä kautta oli antava heille pelastuksen; mutta he eivät sitä ymmärtäneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 26, 'Seuraavana päivänä hän ilmestyi heidän luoksensa, heidän riidellessään, ja koetti saada heitä sopimaan sanoen: \'Tehän olette veljiä, miehet; miksi teette vääryyttä toisillenne?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 27, 'Mutta se, joka teki lähimmäisellensä vääryyttä, työnsi hänet pois ja sanoi: \'Kuka on asettanut sinut meidän päämieheksemme ja tuomariksemme?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 28, 'Aiotko tappaa minutkin, niinkuin eilen tapoit egyptiläisen?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 29, 'Tämän puheen tähden Mooses pakeni ja oli muukalaisena Midianin maassa, ja siellä hänelle syntyi kaksi poikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 30, 'Ja kun neljäkymmentä vuotta oli kulunut, ilmestyi hänelle Siinain vuoren erämaassa enkeli palavan orjantappurapensaan liekissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 31, 'Kun Mooses sen näki, ihmetteli hän tätä näkyä; ja kun hän meni tarkemmin katsomaan, kuului Herran ääni, joka sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 32, '\'Minä olen sinun isiesi Jumala, Aabrahamin ja Iisakin ja Jaakobin Jumala\'. Niin Mooses alkoi vapista eikä tohtinut katsoa sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 33, 'Mutta Herra sanoi hänelle: \'Riisu kengät jalastasi; sillä paikka, jossa seisot, on pyhä maa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 34, 'Minä olen nähnyt kansani kurjuuden Egyptissä ja kuullut heidän huokauksensa, ja minä olen astunut alas vapauttamaan heidät. Ja nyt, tule tänne, minä lähetän sinut Egyptiin.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 35, 'Tämän Mooseksen, jonka he kielsivät sanoen: \'Kuka sinut on asettanut päämieheksi ja tuomariksi?\', hänet Jumala lähetti päämieheksi ja lunastajaksi sen enkelin kautta, joka hänelle orjantappurapensaassa oli ilmestynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 36, 'Hän johdatti heidät sieltä pois, tehden ihmeitä ja tunnustekoja Egyptin maassa ja Punaisessa meressä ja erämaassa neljänäkymmenenä vuotena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 37, 'Tämä on se Mooses, joka sanoi israelilaisille: \'Profeetan, minun kaltaiseni, Jumala on teille herättävä teidän veljienne joukosta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 38, 'Hän on se, joka seurakunnassa, erämaassa, oli enkelin kanssa, joka puhui hänelle Siinain vuorella, ja oli myös isiemme kanssa; ja hän sai eläviä sanoja meille annettaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 39, 'Mutta häntä meidän isämme eivät tahtoneet totella, vaan työnsivät hänet pois ja kääntyivät sydämessänsä jälleen Egyptiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 40, 'sanoen Aaronille: \'Tee meille jumalia, jotka käyvät meidän edellämme, sillä me emme tiedä, mitä on tapahtunut Moosekselle, hänelle, joka johdatti meidät Egyptin maasta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 41, 'Ja he tekivät niinä päivinä vasikan ja toivat uhreja epäjumalalleen ja riemuitsivat kättensä töistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 42, 'Mutta Jumala kääntyi heistä pois ja hylkäsi heidät palvelemaan taivaan sotajoukkoa, niinkuin on kirjoitettu profeettain kirjassa: \'Toitteko te teurasuhreja ja muita uhreja minulle erämaassa neljänäkymmenenä vuotena, te, Israelin heimo?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 43, 'Ette; vaan te kannoitte Molokin majaa ja Romfa jumalan tähteä, niitä kuvia, jotka te olitte tehneet kumarrettaviksenne. Sentähden minä siirrän teidät toiselle puolelle Babylonin.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 44, 'Todistuksen maja oli meidän isillämme erämaassa, niinkuin hän, joka puhui Moosekselle, oli määrännyt sen tehtäväksi, sen kaavan mukaan, minkä Mooses oli nähnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 45, 'Ja meidän isämme ottivat sen perintönä vastaan ja toivat sen Joosuan johdolla maahan, minkä he valtasivat pakanoilta, jotka Jumala karkoitti meidän isiemme tieltä. Näin oli Daavidin päiviin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 46, 'Hän sai armon Jumalan edessä ja anoi, että hän saisi valmistaa majan Jaakobin Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 47, 'Mutta Salomo hänelle huoneen rakensi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 48, 'Korkein ei kuitenkaan asu käsillä tehdyissä huoneissa; sillä näin sanoo profeetta:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 49, '\'Taivas on minun valtaistuimeni ja maa minun jalkojeni astinlauta; minkäkaltaisen huoneen te minulle rakentaisitte, sanoo Herra, tai mikä paikka olisi minun leposijani?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 50, 'Eikö minun käteni ole tätä kaikkea tehnyt?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 51, 'Te niskurit ja ympärileikkaamattomat sydämeltä ja korvilta, aina te vastustatte Pyhää Henkeä-niinkuin teidän isänne, niin tekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 52, 'Ketä profeetoista eivät teidän isänne vainonneet? He tappoivat ne, jotka ennustivat sen Vanhurskaan tulemista, jonka kavaltajiksi ja murhaajiksi te nyt olette tulleet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 53, 'te, jotka enkelien toimen kautta saitte lain, mutta ette sitä pitäneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 54, 'Mutta kun he tämän kuulivat, viilsi se heidän sydäntänsä, ja he kiristelivät hänelle hampaitansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 55, 'Mutta täynnä Pyhää Henkeä hän loi katseensa taivaaseen päin ja näki Jumalan kirkkauden ja Jeesuksen seisovan Jumalan oikealla puolella');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 56, 'ja sanoi: \"Katso, minä näen taivaat auenneina ja Ihmisen Pojan seisovan Jumalan oikealla puolella\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 57, 'Niin he huusivat suurella äänellä ja tukkivat korvansa ja karkasivat kaikki yhdessä hänen päällensä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 58, 'ja ajoivat hänet ulos kaupungista ja kivittivät. Ja todistajat riisuivat vaippansa Saulus nimisen nuorukaisen jalkojen juureen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 59, 'Ja niin he kivittivät Stefanuksen, joka rukoili ja sanoi: \"Herra Jeesus, ota minun henkeni!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 7, 60, 'Ja hän laskeutui polvilleen ja huusi suurella äänellä: \"Herra, älä lue heille syyksi tätä syntiä!\" Ja sen sanottuaan hän nukkui pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 1, 'Myös Saulus hyväksyi Stefanuksen surmaamisen. Ja sinä päivänä nousi suuri vaino Jerusalemin seurakuntaa vastaan; ja kaikki hajaantuivat ympäri Juudean ja Samarian paikkakuntia, paitsi apostolit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 2, 'Ja muutamat jumalaapelkääväiset miehet hautasivat Stefanuksen ja pitivät hänelle suuret valittajaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 3, 'Mutta Saulus raateli seurakuntaa, kulki talosta taloon ja raastoi ulos miehiä ja naisia ja panetti heidät vankeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 4, 'Ne, jotka näin olivat hajaantuneet, vaelsivat paikasta toiseen ja julistivat evankeliumin sanaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 5, 'Ja Filippus meni Samarian kaupunkiin ja saarnasi heille Kristusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 6, 'Ja kansa otti yksimielisesti vaarin siitä, mitä Filippus puhui, kun he kuulivat hänen sanansa ja näkivät ne tunnusteot, jotka hän teki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 7, 'Sillä monista, joissa oli saastaisia henkiä, ne lähtivät pois huutaen suurella äänellä; ja moni halvattu ja rampa parani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 8, 'Ja syntyi suuri ilo siinä kaupungissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 9, 'Mutta ennestään oli kaupungissa muuan mies, nimeltä Simon, joka harjoitti noituutta ja hämmästytti Samarian kansaa sanoen olevansa jokin suuri;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 10, 'ja häntä kuuntelivat kaikki, pienet ja suuret, ja sanoivat: \"Tämä mies on se Jumalan voima, jota kutsutaan \'suureksi\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 11, 'Ja he kuuntelivat häntä sentähden, että hän kauan aikaa oli noituuksillaan heitä hämmästyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 12, 'Mutta kun he nyt uskoivat Filippusta, joka julisti evankeliumia Jumalan valtakunnasta ja Jeesuksen Kristuksen nimestä, niin he ottivat kasteen, sekä miehet että naiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 13, 'Ja Simon itsekin uskoi, ja kasteen saatuansa hän pysytteli Filippuksen seurassa; ja nähdessään ihmeitä ja suuria, voimallisia tekoja hän hämmästyi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 14, 'Mutta kun apostolit, jotka olivat Jerusalemissa, kuulivat, että Samaria oli ottanut vastaan Jumalan sanan, lähettivät he heidän tykönsä Pietarin ja Johanneksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 15, 'Ja tultuaan sinne nämä rukoilivat heidän edestänsä, että he saisivat Pyhän Hengen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 16, 'sillä hän ei ollut vielä tullut yhteenkään heistä, vaan he olivat ainoastaan kastetut Herran Jeesuksen nimeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 17, 'Silloin he panivat kätensä heidän päällensä, ja he saivat Pyhän Hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 18, 'Mutta kun Simon näki, että Henki annettiin sille, jonka päälle apostolit panivat kätensä, toi hän heille rahaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 19, 'ja sanoi: \"Antakaa minullekin se valta, että kenen päälle minä käteni panen, se saa Pyhän Hengen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 20, 'Mutta Pietari sanoi hänelle: \"Menkööt rahasi sinun kanssasi kadotukseen, koska luulet Jumalan lahjan olevan rahalla saatavissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 21, 'Ei sinulla ole osaa eikä arpaa tähän sanaan, sillä sinun sydämesi ei ole oikea Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 22, 'Tee siis parannus ja käänny tästä pahuudestasi ja rukoile Herraa-jos ehkä vielä sinun sydämesi ajatus sinulle anteeksi annetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 23, 'Sillä minä näen sinun olevan täynnä katkeruuden sappea ja kiinni vääryyden siteissä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 24, 'Niin Simon vastasi ja sanoi: \"Rukoilkaa te minun edestäni Herraa, ettei minulle tapahtuisi mitään siitä, mitä te olette sanoneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 25, 'Ja kun he olivat todistaneet ja Herran sanaa puhuneet, palasivat he Jerusalemiin ja julistivat evankeliumia monessa Samarian kylässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 26, 'Mutta Filippukselle puhui Herran enkeli sanoen: \"Nouse ja mene puolipäivään päin sille tielle, joka vie Jerusalemista alas Gassaan ja on autio\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 27, 'Ja hän nousi ja lähti. Ja katso, siellä kulki etiopialainen mies, Etiopian kuningattaren Kandaken hoviherra, mahtava mies ja koko hänen aarteistonsa hoitaja; hän oli tullut Jerusalemiin rukoilemaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 28, 'ja oli nyt paluumatkalla ja istui vaunuissaan ja luki profeetta Esaiasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 29, 'Niin Henki sanoi Filippukselle: \"Käy luo ja pysyttele lähellä noita vaunuja\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 30, 'Niin Filippus juoksi luo ja kuuli hänen lukevan profeetta Esaiasta ja sanoi: \"Ymmärrätkö myös, mitä luet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 31, 'Niin hän sanoi: \"Kuinka minä voisin ymmärtää, ellei kukaan minua opasta?\" Ja hän pyysi Filippusta nousemaan ja istumaan viereensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 32, 'Ja se kirjoitus, jota hän luki, oli tämä: \"Niinkuin lammas hänet viedään teuraaksi; ja niinkuin karitsa on ääneti keritsijänsä edessä, niin ei hänkään suutansa avaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 33, 'Hänen alentumisensa kautta hänen tuomionsa otetaan pois. Kuka kertoo hänen syntyperänsä? Sillä hänen elämänsä otetaan pois maan päältä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 34, 'Ja hoviherra kysyi Filippukselta sanoen: \"Minä pyydän sinua: sano, kenestä profeetta puhuu näin, itsestäänkö vai jostakin toisesta?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 35, 'Niin Filippus avasi suunsa ja lähtien tästä kirjoituksesta julisti hänelle evankeliumia Jeesuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 36, 'Ja kulkiessaan tietä he tulivat veden ääreen; ja hoviherra sanoi: \"Katso, tässä on vettä. Mikä estää kastamasta minua?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 37, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 38, 'Ja hän käski pysäyttää vaunut, ja he astuivat kumpikin veteen, sekä Filippus että hoviherra, ja Filippus kastoi hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 39, 'Ja kun he olivat astuneet ylös vedestä, tempasi Herran Henki Filippuksen pois, eikä hoviherra häntä enää nähnyt. Ja hän jatkoi matkaansa iloiten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 8, 40, 'Mutta Filippus tavattiin Asdodissa; ja hän vaelsi ympäri ja julisti evankeliumia kaikissa kaupungeissa, kunnes tuli Kesareaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 1, 'Mutta Saulus puuskui yhä uhkaa ja murhaa Herran opetuslapsia vastaan ja meni ylimmäisen papin luo');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 2, 'ja pyysi häneltä kirjeitä Damaskon synagoogille, että keitä hän vain löytäisi sen tien vaeltajia, miehiä tai naisia, ne hän saisi tuoda sidottuina Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 3, 'Ja kun hän oli matkalla, tapahtui hänen lähestyessään Damaskoa, että yhtäkkiä valo taivaasta leimahti hänen ympärillänsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 4, 'ja hän kaatui maahan ja kuuli äänen, joka sanoi hänelle: \"Saul, Saul, miksi vainoat minua?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 5, 'Hän sanoi: \"Kuka olet, herra?\" Hän vastasi: \"Minä olen Jeesus, jota sinä vainoat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 6, 'Mutta nouse ja mene kaupunkiin, niin sinulle sanotaan, mitä sinun pitää tekemän.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 7, 'Ja miehet, jotka matkustivat hänen kanssansa, seisoivat mykistyneinä: he kuulivat kyllä äänen, mutta eivät ketään nähneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 8, 'Niin Saulus nousi maasta; mutta kun hän avasi silmänsä, ei hän nähnyt mitään, vaan he taluttivat häntä kädestä ja veivät hänet Damaskoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 9, 'Ja hän oli kolme päivää näkemätönnä, ei syönyt eikä juonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 10, 'Ja Damaskossa oli eräs opetuslapsi, nimeltä Ananias. Hänelle Herra sanoi näyssä: \"Ananias!\" Hän vastasi: \"Katso, tässä olen, Herra\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 11, 'Niin Herra sanoi hänelle: \"Nouse ja mene sille kadulle, jota sanotaan Suoraksi kaduksi, ja kysy Juudaan talosta Saulus nimistä tarsolaista miestä. Sillä katso, hän rukoilee;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 12, 'ja hän on nähnyt näyssä miehen, Ananias nimisen, tulevan sisälle ja panevan kätensä hänen päällensä, että hän saisi näkönsä jälleen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 13, 'Mutta Ananias vastasi: \"Herra, minä olen monelta kuullut siitä miehestä, kuinka paljon pahaa hän on tehnyt sinun pyhillesi Jerusalemissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 14, 'ja täälläkin hänellä on ylipapeilta valtuus vangita kaikki, jotka sinun nimeäsi avuksi huutavat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 15, 'Mutta Herra sanoi hänelle: \"Mene; sillä hän on minulle valittu ase, kantamaan minun nimeäni pakanain ja kuningasten ja Israelin lasten eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 16, 'Sillä minä tahdon näyttää hänelle, kuinka paljon hänen pitää kärsimän minun nimeni tähden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 17, 'Niin Ananias meni ja astui huoneeseen, pani molemmat kätensä hänen päälleen ja sanoi: \"Veljeni Saul, Herra lähetti minut-Jeesus, joka ilmestyi sinulle tiellä, jota tulit-että saisit näkösi jälleen ja tulisit täytetyksi Pyhällä Hengellä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 18, 'Ja heti putosivat hänen silmistään ikäänkuin suomukset, ja hän sai näkönsä ja nousi ja otti kasteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 19, 'Ja kun hän nautti ruokaa, niin hän vahvistui. Ja hän oli opetuslasten seurassa Damaskossa jonkun aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 20, 'Ja kohta hän saarnasi synagoogissa Jeesusta, julistaen, että hän on Jumalan Poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 21, 'Ja kaikki, jotka kuulivat, hämmästyivät ja sanoivat: \"Eikö tämä ole se, joka Jerusalemissa tuhosi ne, jotka tätä nimeä avuksi huutavat? Ja eikö hän ole tullut tänne viedäksensä ne vangittuina ylipappien käsiin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 22, 'Mutta Saulus sai yhä enemmän voimaa ja saattoi Damaskossa asuvat juutalaiset ymmälle näyttäen toteen, että Jeesus on Kristus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 23, 'Ja pitkän ajan kuluttua juutalaiset pitivät keskenään neuvoa tappaaksensa hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 24, 'Mutta heidän salahankkeensa tuli Sauluksen tietoon. Ja he vartioivat porttejakin yöt päivät, saadakseen hänet tapetuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 25, 'Mutta hänen opetuslapsensa ottivat hänet yöllä, päästivät hänet muurin aukosta ja laskivat alas vasussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 26, 'Ja kun hän oli tullut Jerusalemiin, yritti hän liittyä opetuslapsiin; mutta he kaikki pelkäsivät häntä, koska eivät uskoneet, että hän oli opetuslapsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 27, 'Mutta Barnabas otti hänet turviinsa ja vei hänet apostolien tykö ja kertoi heille, kuinka Saulus tiellä oli nähnyt Herran, ja että Herra oli puhunut hänelle, ja kuinka hän Damaskossa oli rohkeasti julistanut Jeesuksen nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 28, 'Ja niin hän kävi heidän keskuudessaan sisälle ja ulos Jerusalemissa ja julisti rohkeasti Herran nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 29, 'Ja hän puhui ja väitteli hellenistien kanssa; mutta he koettivat tappaa hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 30, 'Kun veljet sen huomasivat, veivät he hänet Kesareaan ja lähettivät hänet sieltä Tarsoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 31, 'Niin oli nyt seurakunnalla koko Juudeassa ja Galileassa ja Samariassa rauha; ja se rakentui ja vaelsi Herran pelossa ja lisääntyi Pyhän Hengen virvoittavasta vaikutuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 32, 'Ja tapahtui, että Pietari, kiertäessään kaikkien luona, tuli myöskin niiden pyhien tykö, jotka asuivat Lyddassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 33, 'Siellä hän tapasi Aineas nimisen miehen, joka kahdeksan vuotta oli maannut vuoteessaan ja oli halvattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 34, 'Ja Pietari sanoi hänelle: \"Aineas, Jeesus Kristus parantaa sinut; nouse ja korjaa vuoteesi\". Ja kohta hän nousi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 35, 'Ja kaikki Lyddan ja Saaronin asukkaat näkivät hänet; ja he kääntyivät Herran tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 36, 'Mutta Joppessa oli naisopetuslapsi, nimeltä Tabita, mikä kreikaksi käännettynä on: Dorkas; hän teki paljon hyviä töitä ja antoi runsaasti almuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 37, 'Ja tapahtui niinä päivinä, että hän sairastui ja kuoli; ja he pesivät hänet ja panivat yläsaliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 38, 'Ja koska Lydda oli lähellä Joppea, niin opetuslapset, kun kuulivat Pietarin olevan siellä, lähettivät kaksi miestä hänen luoksensa pyytämään: \"Tule viipymättä meidän tykömme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 39, 'Niin Pietari nousi ja meni heidän kanssansa. Ja hänen sinne saavuttuaan he veivät hänet yläsaliin, ja kaikki lesket tulivat hänen luoksensa itkien ja näytellen hänelle ihokkaita ja vaippoja, joita Dorkas oli tehnyt, ollessaan heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 40, 'Mutta Pietari toimitti kaikki ulos ja laskeutui polvilleen ja rukoili; ja hän kääntyi ruumiin puoleen ja sanoi: \"Tabita, nouse ylös!\" Niin tämä avasi silmänsä, ja nähdessään Pietarin hän nousi istumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 41, 'Ja Pietari ojensi hänelle kätensä ja nosti hänet seisomaan ja kutsui sisään pyhät ja lesket ja asetti hänet elävänä heidän eteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 42, 'Ja se tuli tiedoksi koko Joppessa, ja monet uskoivat Herraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 9, 43, 'Ja Pietari viipyi Joppessa jonkun aikaa erään nahkuri Simonin luona.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 1, 'Ja Kesareassa oli mies, nimeltä Kornelius, sadanpäämies niin kutsutussa italialaisessa sotaväenosastossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 2, 'Hän oli hurskas ja Jumalaa pelkääväinen, niinkuin koko hänen perhekuntansakin, ja antoi paljon almuja kansalle ja rukoili alati Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 3, 'Hän näki selvästi näyssä, noin yhdeksännellä hetkellä päivästä, Jumalan enkelin, joka tuli sisään hänen tykönsä ja sanoi hänelle: \"Kornelius!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 4, 'Tämä loi katseensa häneen ja sanoi peljästyneenä: \"Mikä on, Herra?\" Enkeli sanoi hänelle: \"Sinun rukouksesi ja almusi ovat tulleet muistoon Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 5, 'Niin lähetä nyt miehiä Joppeen noutamaan eräs Simon, jota myös Pietariksi kutsutaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 6, 'hän majailee nahkuri Simonin luona, jonka talo on meren rannalla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 7, 'Ja kun enkeli, joka Korneliusta puhutteli, oli mennyt pois, kutsui tämä kaksi palvelijaansa ja hurskaan sotamiehen uskollisimpiensa joukosta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 8, 'ja kertoi heille kaikki ja lähetti heidät Joppeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 9, 'Ja seuraavana päivänä, kun he olivat matkalla ja lähestyivät kaupunkia, nousi Pietari noin kuudennen hetken vaiheilla katolle rukoilemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 10, 'Ja hänen tuli nälkä, ja hän halusi ruokaa. Mutta sitä valmistettaessa hän joutui hurmoksiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 11, 'Ja hän näki taivaan avoinna ja tulevan alas astian, ikäänkuin suuren liinavaatteen, joka neljästä kulmastaan laskettiin maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 12, 'Ja siinä oli kaikkinaisia maan nelijalkaisia ja matelijoita ja taivaan lintuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 13, 'Ja tuli ääni, joka sanoi hänelle: \"Nouse, Pietari, teurasta ja syö\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 14, 'Mutta Pietari sanoi: \"En suinkaan, Herra; sillä en minä ole ikinä syönyt mitään epäpyhää enkä saastaista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 15, 'Ja taas ääni sanoi hänelle toistamiseen: \"Minkä Jumala on puhdistanut, sitä älä sinä sano epäpyhäksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 16, 'Tämä tapahtui kolme kertaa; sitten astia otettiin kohta ylös taivaaseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 17, 'Ja kun Pietari oli epätietoinen siitä, mitä hänen näkemänsä näky mahtoi merkitä, niin katso, ne miehet, jotka Kornelius oli lähettänyt ja jotka kyselemällä olivat löytäneet Simonin talon, seisoivat portilla');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 18, 'ja tiedustelivat kuuluvalla äänellä, majailiko siellä Simon, jota myös Pietariksi kutsuttiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 19, 'Kun Pietari yhä mietti tuota näkyä, sanoi Henki hänelle: \"Katso, kaksi miestä etsii sinua;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 20, 'niin nouse nyt, astu alas ja mene arvelematta heidän kanssaan, sillä minä olen heidät lähettänyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 21, 'Niin Pietari meni alas miesten tykö ja sanoi: \"Katso, minä olen se, jota te etsitte; mitä varten te olette tulleet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 22, 'He sanoivat: \"Sadanpäämies Kornelius, hurskas ja Jumalaa pelkääväinen mies, josta koko Juudan kansa todistaa hyvää, on pyhältä enkeliltä ilmestyksessä saanut käskyn haettaa sinut kotiinsa ja kuulla, mitä sinulla on sanottavaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 23, 'Niin hän kutsui heidät sisään ja piti heitä vierainansa. Seuraavana päivänä Pietari nousi ja lähti heidän kanssaan, ja muutamat veljet Joppesta seurasivat hänen mukanaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 24, 'Ja sen jälkeisenä päivänä he saapuivat Kesareaan; ja Kornelius odotti heitä ja oli kutsunut koolle sukulaisensa ja lähimmät ystävänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 25, 'Ja kun Pietari oli astumassa sisään, meni Kornelius häntä vastaan, lankesi hänen jalkojensa juureen ja kumartui maahan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 26, 'Mutta Pietari nosti hänet ylös sanoen: \"Nouse; minäkin olen ihminen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 27, 'Ja puhellen hänen kanssaan hän meni sisään ja tapasi monta koolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 28, 'Ja hän sanoi heille: \"Te tiedätte, että on luvatonta juutalaisen miehen seurustella vierasheimoisen kanssa tai mennä hänen tykönsä; mutta minulle Jumala on osoittanut, etten saa sanoa ketään ihmistä epäpyhäksi enkä saastaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 29, 'Sentähden minä vastaansanomatta tulinkin, kun minua noudettiin. Ja nyt minä kysyn: mitä varten te olette minut noutaneet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 30, 'Ja Kornelius sanoi: \"Neljä päivää sitten, juuri tähän aikaan päivästä, minä kotonani rukoilin tällä yhdeksännellä hetkellä, ja katso, edessäni seisoi mies loistavissa vaatteissa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 31, 'ja sanoi: \'Kornelius, sinun rukouksesi on kuultu, ja sinun almusi ovat tulleet muistoon Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 32, 'Niin lähetä nyt Joppeen ja kutsu tykösi Simon, jota myös Pietariksi kutsutaan; hän majailee nahkuri Simonin talossa meren rannalla.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 33, 'Sentähden minä lähetin heti sinulle sanan, ja sinä teit hyvin, kun tulit. Nyt olemme siis tässä kaikki Jumalan edessä, kuullaksemme kaiken, mitä Herra on käskenyt sinun puhua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 34, 'Niin Pietari avasi suunsa ja sanoi: \"Nyt minä totisesti käsitän, ettei Jumala katso henkilöön,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 35, 'vaan että jokaisessa kansassa se, joka häntä pelkää ja tekee vanhurskautta, on hänelle otollinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 36, 'Sen sanan, jonka hän lähetti Israelin lapsille, julistaen evankeliumia rauhasta Jeesuksessa Kristuksessa, joka on kaikkien Herra,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 37, 'sen sanan, joka lähtien Galileasta on levinnyt koko Juudeaan, sen kasteen jälkeen, jota Johannes saarnasi, sen te tiedätte;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 38, 'te tiedätte, kuinka Jumala Pyhällä Hengellä ja voimalla oli voidellut Jeesuksen Nasaretilaisen, hänet, joka vaelsi ympäri ja teki hyvää ja paransi kaikki perkeleen valtaan joutuneet; sillä Jumala oli hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 39, 'Ja me olemme kaiken sen todistajat, mitä hän teki juutalaisten maassa ja Jerusalemissa; ja hänet he ripustivat puuhun ja tappoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 40, 'Hänet Jumala herätti kolmantena päivänä ja antoi hänen ilmestyä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 41, 'ei kaikelle kansalle, vaan Jumalan ennen valitsemille todistajille, meille, jotka söimme ja joimme hänen kanssaan sen jälkeen, kuin hän oli kuolleista noussut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 42, 'Ja hän käski meidän saarnata kansalle ja todistaa, että hän on se, jonka Jumala on asettanut elävien ja kuolleitten tuomariksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 43, 'Hänestä kaikki profeetat todistavat, että jokainen, joka uskoo häneen, saa synnit anteeksi hänen nimensä kautta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 44, 'Kun Pietari vielä näitä puhui, tuli Pyhä Henki kaikkien päälle, jotka puheen kuulivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 45, 'Ja kaikki ne uskovaiset, jotka olivat ympärileikatut ja olivat tulleet Pietarin mukana, hämmästyivät sitä, että Pyhän Hengen lahja vuodatettiin pakanoihinkin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 46, 'sillä he kuulivat heidän puhuvan kielillä ja ylistävän Jumalaa. Silloin Pietari vastasi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 47, '\"Ei kaiketi kukaan voi kieltää kastamasta vedellä näitä, jotka ovat saaneet Pyhän Hengen niinkuin mekin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 10, 48, 'Ja hän käski kastaa heidät Jeesuksen Kristuksen nimeen. Silloin he pyysivät häntä viipymään siellä muutamia päiviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 1, 'Ja apostolit ja veljet ympäri Juudeaa kuulivat, että pakanatkin olivat ottaneet vastaan Jumalan sanan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 2, 'Ja kun Pietari tuli Jerusalemiin, ahdistelivat ympärileikatut häntä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 3, 'sanoen: \"Sinä olet käynyt ympärileikkaamattomien miesten luona ja syönyt heidän kanssansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 4, 'Niin Pietari selitti heille alusta alkaen asiat järjestänsä ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 5, '\"Minä olin Joppen kaupungissa ja rukoilin; silloin minä näin hurmoksissa näyn: tuli alas astia, ikäänkuin suuri liinavaate, joka neljästä kulmastaan laskettiin taivaasta, ja se tuli aivan minun eteeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 6, 'Ja kun minä katsoin sitä tarkasti, näin minä siinä maan nelijalkaisia ja petoja ja matelijoita ja taivaan lintuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 7, 'Ja minä kuulin myös äänen, joka sanoi minulle: \'Nouse, Pietari, teurasta ja syö\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 8, 'Mutta minä sanoin: \'En suinkaan, Herra; sillä ei mitään epäpyhää eikä saastaista ole koskaan minun suuhuni tullut\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 9, 'Niin vastasi ääni taivaasta toistamiseen ja sanoi: \'Minkä Jumala on puhdistanut, sitä älä sinä sano epäpyhäksi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 10, 'Ja tämä tapahtui kolme kertaa; sitten vedettiin kaikki taas ylös taivaaseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 11, 'Ja katso, samassa seisoi sen talon edessä, jossa me olimme, kolme miestä, jotka Kesareasta oli lähetetty minun luokseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 12, 'Ja Henki käski minun mennä arvelematta heidän kanssansa; ja myös nämä kuusi veljeä lähtivät minun kanssani. Me menimme sen miehen taloon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 13, 'ja hän kertoi meille, kuinka hän oli nähnyt enkelin seisovan hänen huoneessaan ja sanovan: \'Lähetä Joppeen noutamaan Simon, jota myös Pietariksi kutsutaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 14, 'hän on puhuva sinulle sanoja, joiden kautta sinä pelastut, ja koko sinun perhekuntasi\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 15, 'Ja kun minä rupesin puhumaan, tuli Pyhä Henki heidän päällensä, niinkuin alussa meidänkin päällemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 16, 'Silloin minä muistin Herran sanan, jonka hän sanoi: \'Johannes kastoi vedellä, mutta teidät kastetaan Pyhällä Hengellä\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 17, 'Koska siis Jumala antoi yhtäläisen lahjan heille kuin meillekin, kun olimme uskoneet Herraan Jeesukseen Kristukseen, niin mikä olin minä voidakseni estää Jumalaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 18, 'Tämän kuultuansa he rauhoittuivat ja ylistivät Jumalaa sanoen: \"Niin on siis Jumala pakanoillekin antanut parannuksen elämäksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 19, 'Ne, jotka olivat hajaantuneet sen ahdingon vuoksi, joka oli syntynyt Stefanuksen tähden, vaelsivat ympäri hamaan Foinikiaan ja Kyproon ja Antiokiaan saakka, mutta eivät puhuneet sanaa muille kuin ainoastaan juutalaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 20, 'Heidän joukossaan oli kuitenkin muutamia kyprolaisia ja kyreneläisiä miehiä, jotka, tultuaan Antiokiaan, puhuivat kreikkalaisillekin ja julistivat evankeliumia Herrasta Jeesuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 21, 'Ja Herran käsi oli heidän kanssansa, ja suuri oli se joukko, joka uskoi ja kääntyi Herran puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 22, 'Ja sanoma heistä tuli Jerusalemin seurakunnan korviin, ja he lähettivät Barnabaan Antiokiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 23, 'Ja kun hän saapui sinne ja näki Jumalan armon, niin hän iloitsi ja kehoitti kaikkia vakaalla sydämellä pysymään Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 24, 'Sillä hän oli hyvä mies ja täynnä Pyhää Henkeä ja uskoa. Ja Herralle lisääntyi paljon kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 25, 'Niin hän lähti Tarsoon etsimään Saulusta, ja kun hän oli hänet löytänyt, toi hän hänet Antiokiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 26, 'Ja he vaikuttivat yhdessä kokonaisen vuoden seurakunnassa, ja niitä oli paljon, jotka saivat heiltä opetusta; ja Antiokiassa ruvettiin opetuslapsia ensiksi nimittämään kristityiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 27, 'Siihen aikaan tuli profeettoja Jerusalemista Antiokiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 28, 'Ja eräs heistä, nimeltä Agabus, nousi ja antoi Hengen vaikutuksesta tiedoksi, että oli tuleva suuri nälkä kaikkeen maailmaan; ja se tulikin Klaudiuksen aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 29, 'Niin opetuslapset päättivät kukin varojensa mukaan lähettää avustusta Juudeassa asuville veljille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 11, 30, 'Ja niin he tekivätkin ja lähettivät sen vanhimmille Barnabaan ja Sauluksen kätten kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 1, 'Siihen aikaan kuningas Herodes otatti muutamia seurakunnan jäseniä kiinni kiduttaaksensa heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 2, 'Ja hän mestautti miekalla Jaakobin, Johanneksen veljen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 3, 'Ja kun hän näki sen olevan juutalaisille mieleen, niin hän sen lisäksi vangitutti Pietarinkin. Silloin olivat happamattoman leivän päivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 4, 'Ja otettuaan hänet kiinni hän pani hänet vankeuteen ja jätti neljän nelimiehisen sotilasvartioston vartioitavaksi, aikoen pääsiäisen jälkeen asettaa hänet kansan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 5, 'Niin pidettiin siis Pietaria vankeudessa; mutta seurakunta rukoili lakkaamatta Jumalaa hänen edestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 6, 'Ja yöllä sitä päivää vasten, jona Herodeksella oli aikomus viedä hänet oikeuden eteen, Pietari nukkui kahden sotamiehen välissä, sidottuna kaksilla kahleilla; ja vartijat vartioitsivat oven edessä vankilaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 7, 'Ja katso, hänen edessään seisoi Herran enkeli, ja huoneessa loisti valo, ja enkeli sysäsi Pietaria kylkeen ja herätti hänet sanoen: \"Nouse nopeasti!\" Ja kahleet putosivat hänen käsistään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 8, 'Ja enkeli sanoi hänelle: \"Vyötä itsesi ja sido paula-anturat jalkaasi\". Ja hän teki niin. Vielä enkeli sanoi hänelle: \"Heitä vaippa yllesi ja seuraa minua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 9, 'Ja Pietari lähti ja seurasi häntä, mutta ei tiennyt, että se, mikä enkelin vaikutuksesta tapahtui, oli totta, vaan luuli näkevänsä näyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 10, 'Ja he kulkivat läpi ensimmäisen vartion ja toisen ja tulivat rautaportille, joka vei kaupunkiin. Se aukeni heille itsestään, ja he menivät ulos ja kulkivat eteenpäin muutamaa katua; ja yhtäkkiä enkeli erkani hänestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 11, 'Kun Pietari tointui, sanoi hän: \"Nyt minä totisesti tiedän, että Herra on lähettänyt enkelinsä ja pelastanut minut Herodeksen käsistä ja kaikesta, mitä Juudan kansa odotti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 12, 'Ja päästyään siitä selville hän kulki kohti Marian, Johanneksen äidin, taloa, sen Johanneksen, jota myös Markukseksi kutsuttiin. Siellä oli monta koolla rukoilemassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 13, 'Ja kun Pietari kolkutti eteisen ovea, tuli siihen palvelijatar, nimeltä Rode, kuulostamaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 14, 'ja tunnettuaan Pietarin äänen hän ilossansa ei avannut eteistä vaan juoksi sisään ja kertoi Pietarin seisovan portin takana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 15, 'He sanoivat hänelle: \"Sinä hourit\". Mutta hän vakuutti puheensa todeksi. Niin he sanoivat: \"Se on hänen enkelinsä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 16, 'Mutta Pietari kolkutti yhä; ja kun he avasivat, näkivät he hänet ja hämmästyivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 17, 'Niin hän viittasi kädellään heitä vaikenemaan ja kertoi heille, kuinka Herra oli vienyt hänet ulos vankeudesta, ja sanoi: \"Ilmoittakaa tämä Jaakobille ja veljille\". Ja hän lähti pois ja meni toiseen paikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 18, 'Mutta kun päivä koitti, tuli sotamiehille kova hätä siitä, mihin Pietari oli joutunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 19, 'Ja kun Herodes oli haettanut häntä eikä löytänyt, tutki hän vartijoita ja käski viedä heidät rangaistaviksi. Sitten hän meni Juudeasta Kesareaan ja oleskeli siellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 20, 'Ja Herodes oli vihoissansa tyyrolaisille ja siidonilaisille. Mutta nämä tulivat yksissä neuvoin hänen luoksensa, ja suostutettuaan puolelleen Blastuksen, kuninkaan kamaripalvelijan, he anoivat rauhaa; sillä heidän maakuntansa sai elatuksensa kuninkaan maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 21, 'Niin Herodes määrättynä päivänä pukeutui kuninkaalliseen pukuun, istui istuimelleen ja piti heille puheen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 22, 'siihen kansa huusi: \"Jumalan ääni, eikä ihmisen!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 23, 'Mutta heti löi häntä Herran enkeli, sentähden ettei hän antanut kunniaa Jumalalle; ja madot söivät hänet, ja hän heitti henkensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 24, 'Mutta Jumalan sana menestyi ja levisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 12, 25, 'Ja Barnabas ja Saulus palasivat Jerusalemista toimitettuansa avustustehtävän ja toivat sieltä mukanaan Johanneksen, jota myös Markukseksi kutsuttiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 1, 'Ja Antiokian seurakunnassa oli profeettoja ja opettajia: Barnabas ja Simeon, jota kutsuttiin Nigeriksi, ja Lukius, kyreneläinen, ja Manaen, neljännysruhtinas Herodeksen kasvinkumppani, ja Saulus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 2, 'Ja heidän toimittaessaan palvelusta Herralle ja paastotessaan Pyhä Henki sanoi: \"Erottakaa minulle Barnabas ja Saulus siihen työhön, johon minä olen heidät kutsunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 3, 'Silloin he paastosivat ja rukoilivat ja panivat kätensä heidän päällensä ja laskivat heidät menemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 4, 'Niin he Pyhän Hengen lähettäminä menivät Seleukiaan ja purjehtivat sieltä Kyproon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 5, 'Ja tultuaan Salamiiseen he julistivat Jumalan sanaa juutalaisten synagoogissa, ja heillä oli mukanaan myös Johannes, palvelijana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 6, 'Ja kun he olivat vaeltaneet kautta koko saaren Pafoon asti, tapasivat he erään juutalaisen miehen, noidan ja väärän profeetan, jonka nimi oli Barjeesus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 7, 'Hän oleskeli käskynhaltijan, Sergius Pauluksen, luona, joka oli ymmärtäväinen mies. Tämä kutsui luoksensa Barnabaan ja Sauluksen ja halusi kuulla Jumalan sanaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 8, 'Mutta Elymas, noita-sillä niin tulkitaan hänen nimensä-vastusti heitä, koettaen kääntää käskynhaltijaa pois uskosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 9, 'Niin Saulus, myös Paavaliksi kutsuttu, täynnä Pyhää Henkeä loi katseensa häneen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 10, 'ja sanoi: \"Voi sinua, joka olet kaikkea vilppiä ja kavaluutta täynnä, sinä perkeleen sikiö, kaiken vanhurskauden vihollinen, etkö lakkaa vääristelemästä Herran suoria teitä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 11, 'Ja nyt, katso, Herran käsi on sinun päälläsi, ja sinä tulet sokeaksi etkä aurinkoa näe säädettyyn aikaan asti.\" Ja heti lankesi hänen päällensä synkeys ja pimeys, ja hän kävi ympäri ja etsi taluttajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 12, 'Kun nyt käskynhaltija näki, mitä oli tapahtunut, niin hän uskoi, ihmetellen Herran oppia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 13, 'Ja kun Paavali seuralaisineen oli purjehtinut Pafosta, tulivat he Pamfylian Pergeen; siellä Johannes erosi heistä ja palasi Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 14, 'Mutta he vaelsivat Pergestä eteenpäin ja saapuivat Pisidian Antiokiaan; ja he menivät synagoogaan sapatinpäivänä ja istuutuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 15, 'Ja sittenkuin lakia ja profeettoja oli luettu, lähettivät synagoogan esimiehet sanomaan heille: \"Miehet, veljet, jos teillä on jokin kehoituksen sana kansalle, niin puhukaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 16, 'Niin Paavali nousi ja viittasi kädellään ja sanoi: \"Te Israelin miehet ja te, jotka Jumalaa pelkäätte, kuulkaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 17, 'Tämän Israelin kansan Jumala valitsi meidän isämme ja korotti tämän kansan, heidän muukalaisina ollessaan Egyptin maassa, ja vei heidät sieltä ulos kohotetulla käsivarrella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 18, 'ja hän kärsi heidän tapojansa noin neljäkymmentä vuotta erämaassa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 19, 'ja hävitti seitsemän kansaa Kanaanin maasta ja jakoi niiden maan heille perinnöksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 20, 'Näin kului noin neljäsataa viisikymmentä vuotta. Sen jälkeen hän antoi heille tuomareita profeetta Samueliin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 21, 'Ja sitten he anoivat kuningasta, ja Jumala antoi heille Saulin, Kiisin pojan, miehen Benjaminin sukukunnasta, neljäksikymmeneksi vuodeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 22, 'Mutta hän pani hänet viralta ja herätti heille kuninkaaksi Daavidin, josta hän myös todisti ja sanoi: \'Minä olen löytänyt Daavidin, Iisain pojan, sydämeni mukaisen miehen, joka on tekevä kaikessa minun tahtoni\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 23, 'Tämän jälkeläisistä on Jumala lupauksensa mukaan antanut tulla Jeesuksen Israelille Vapahtajaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 24, 'sittenkuin Johannes ennen hänen tuloansa oli saarnannut parannuksen kastetta kaikelle Israelin kansalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 25, 'Mutta kun Johannes oli juoksunsa päättävä, sanoi hän: \'En minä ole se, joksi minua luulette; mutta katso, minun jälkeeni tulee se, jonka kenkiä minä en ole arvollinen jaloista riisumaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 26, 'Miehet, veljet, te Aabrahamin suvun lapset, ja te, jotka Jumalaa pelkäätte, meille on tämän pelastuksen sana lähetetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 27, 'Sillä koska Jerusalemin asukkaat ja heidän hallitusmiehensä eivät Jeesusta tunteneet, niin he tuomitessaan hänet myös toteuttivat profeettain sanat, joita kunakin sapattina luetaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 28, 'ja vaikka he eivät löytäneet mitään, mistä hän olisi kuoleman ansainnut, anoivat he Pilatukselta, että hänet surmattaisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 29, 'Ja kun he olivat täyttäneet kaiken, mikä hänestä on kirjoitettu, ottivat he hänet alas puusta ja panivat hautaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 30, 'Mutta Jumala herätti hänet kuolleista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 31, 'Ja hän ilmestyi useina päivinä niille, jotka olivat tulleet hänen kanssansa Galileasta Jerusalemiin ja jotka nyt ovat hänen todistajansa kansan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 32, 'Ja me julistamme teille sen hyvän sanoman, että Jumala on isille annetun lupauksen täyttänyt meidän lapsillemme, herättäen Jeesuksen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 33, 'niinkuin myös toisessa psalmissa on kirjoitettu: \'Sinä olet minun Poikani, tänä päivänä minä olen sinut synnyttänyt\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 34, 'Ja että hän herätti hänet kuolleista, niin ettei hän enää palaja katoavaisuuteen, siitä hän on sanonut näin: \'Minä annan teille pyhät ja lujat Daavidin armot\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 35, 'Sentähden hän myös toisessa paikassa sanoo: \'Sinä et salli Pyhäsi nähdä katoavaisuutta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 36, 'Sillä kun Daavid oli aikanansa Jumalan tahtoa palvellut, nukkui hän ja tuli otetuksi isiensä tykö ja näki katoavaisuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 37, 'Mutta hän, jonka Jumala herätti, ei nähnyt katoavaisuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 38, 'Olkoon siis teille tiettävä, miehet ja veljet, että hänen kauttansa julistetaan teille syntien anteeksiantamus');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 39, 'ja että jokainen, joka uskoo, tulee hänessä vanhurskaaksi, vapaaksi kaikesta, mistä te ette voineet Mooseksen lain kautta vanhurskaiksi tulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 40, 'Kavahtakaa siis, ettei teitä kohtaa se, mikä on puhuttu profeetoissa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 41, '\'Katsokaa, te halveksijat, ja ihmetelkää ja hukkukaa; sillä minä teen teidän päivinänne teon, teon, jota ette uskoisi, jos joku sen kertoisi teille\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 42, 'Kun he lähtivät ulos, pyydettiin heitä puhumaan näitä asioita tulevanakin sapattina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 43, 'Kun synagoogasta hajaannuttiin, seurasivat monet juutalaiset ja jumalaapelkääväiset käännynnäiset Paavalia ja Barnabasta, jotka puhuivat heille ja kehoittivat heitä pysymään Jumalan armossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 44, 'Seuraavana sapattina kokoontui lähes koko kaupunki kuulemaan Jumalan sanaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 45, 'Mutta nähdessään kansanjoukot juutalaiset tulivat kiihkoa täyteen ja väittelivät Paavalin puheita vastaan ja herjasivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 46, 'Silloin Paavali ja Barnabas puhuivat rohkeasti ja sanoivat: \"Teille oli Jumalan sana ensiksi puhuttava; mutta koska te työnnätte sen luotanne ettekä katso itseänne mahdollisiksi iankaikkiseen elämään, niin katso, me käännymme pakanain puoleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 47, 'Sillä näin on Herra meitä käskenyt: \'Minä olen pannut sinut pakanain valkeudeksi, että sinä olisit pelastukseksi maan ääriin asti\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 48, 'Sen kuullessansa pakanat iloitsivat ja ylistivät Herran sanaa ja uskoivat, kaikki, jotka olivat säädetyt iankaikkiseen elämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 49, 'Ja Herran sanaa levitettiin kaikkeen siihen maakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 50, 'Mutta juutalaiset yllyttivät jumalaapelkääväisiä ylhäisiä naisia ja kaupungin ensimmäisiä miehiä ja nostivat vainon Paavalia ja Barnabasta vastaan, ja ne ajoivat heidät pois alueiltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 51, 'Niin he pudistivat tomun jaloistansa heitä vastaan ja menivät Ikonioniin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 13, 52, 'Ja opetuslapset tulivat täytetyiksi ilolla ja Pyhällä Hengellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 1, 'Ikonionissa he samoin menivät juutalaisten synagoogaan ja puhuivat niin, että suuri joukko sekä juutalaisia että kreikkalaisia uskoi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 2, 'Mutta ne juutalaiset, jotka eivät uskoneet, yllyttivät ja kiihdyttivät pakanain mieltä veljiä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 3, 'Niin he oleskelivat siellä kauan aikaa ja puhuivat rohkeasti, luottaen Herraan, joka armonsa sanan todistukseksi antoi tapahtua tunnustekoja ja ihmeitä heidän kättensä kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 4, 'Ja kaupungin väestö jakaantui: toiset olivat juutalaisten puolella, toiset taas apostolien puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 5, 'Mutta kun pakanat ja juutalaiset ynnä heidän hallitusmiehensä mielivät ryhtyä pahoinpitelemään ja kivittämään heitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 6, 'ja he sen huomasivat, pakenivat he Lykaonian kaupunkeihin, Lystraan ja Derbeen, ja niiden ympäristöön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 7, 'Ja siellä he julistivat evankeliumia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 8, 'Ja Lystrassa oli mies, joka istui siellä, hervoton jaloistaan ja rampa äitinsä kohdusta saakka, eikä ollut koskaan kävellyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 9, 'Hän kuunteli Paavalin puhetta. Ja kun Paavali loi katseensa häneen ja näki hänellä olevan uskon, että hän voi tulla terveeksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 10, 'sanoi hän suurella äänellä: \"Nouse pystyyn jaloillesi\". Ja hän kavahti ylös ja käveli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 11, 'Kun kansa näki, mitä Paavali oli tehnyt, korottivat he äänensä ja sanoivat lykaoniankielellä: \"Jumalat ovat ihmishahmossa astuneet alas meidän luoksemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 12, 'Ja he sanoivat Barnabasta Zeukseksi ja Paavalia Hermeeksi, koska hän oli se, joka puhui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 13, 'Ja kaupungin edustalla olevan Zeuksen temppelin pappi toi härkiä ja seppeleitä porttien eteen ja tahtoi väkijoukon kanssa uhrata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 14, 'Mutta kun apostolit Barnabas ja Paavali sen kuulivat, repäisivät he vaatteensa ja juoksivat ulos kansanjoukkoon, huusivat');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 15, 'ja sanoivat: \"Miehet, miksi te näin teette? Mekin olemme ihmisiä, yhtä vajavaisia kuin te, ja julistamme teille evankeliumia, että te kääntyisitte noista turhista jumalista elävän Jumalan puoleen, joka on tehnyt taivaan ja maan ja meren ja kaikki, mitä niissä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 16, 'Menneitten sukupolvien aikoina hän on sallinut kaikkien pakanain vaeltaa omia teitänsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 17, 'ja kuitenkaan hän ei ole ollut antamatta todistusta itsestään, sillä hän on tehnyt teille hyvää, antaen teille taivaasta sateita ja hedelmällisiä aikoja ja raviten teidän sydämenne ruualla ja ilolla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 18, 'Näin puhuen he vaivoin saivat kansan hillityksi uhraamasta heille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 19, 'Mutta sinne tuli Antiokiasta ja Ikonionista juutalaisia, ja he suostuttivat kansan puolellensa ja kivittivät Paavalia ja raastoivat hänet kaupungin ulkopuolelle, luullen hänet kuolleeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 20, 'Mutta kun opetuslapset olivat kokoontuneet hänen ympärilleen, nousi hän ja meni kaupunkiin. Ja seuraavana päivänä hän lähti Barnabaan kanssa Derbeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 21, 'Ja julistettuaan evankeliumia siinä kaupungissa ja tehtyään monta opetuslapsiksi he palasivat Lystraan ja Ikonioniin ja Antiokiaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 22, 'ja vahvistivat opetuslasten sieluja ja kehoittivat heitä pysymään uskossa ja sanoivat: \"Monen ahdistuksen kautta meidän pitää menemän sisälle Jumalan valtakuntaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 23, 'Ja kun he olivat valinneet heille vanhimmat jokaisessa seurakunnassa, niin he rukoillen ja paastoten jättivät heidät Herran haltuun, johon he nyt uskoivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 24, 'Ja he kulkivat läpi Pisidian ja tulivat Pamfyliaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 25, 'ja julistettuaan sanaa Pergessä he menivät Attaliaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 26, 'Ja sieltä he purjehtivat Antiokiaan, josta he olivat lähteneet, annettuina Jumalan armon haltuun sitä työtä varten, jonka he nyt olivat suorittaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 27, 'Ja sinne saavuttuaan he kutsuivat seurakunnan koolle ja kertoivat, kuinka Jumala oli ollut heidän kanssansa ja tehnyt suuria ja kuinka hän oli avannut pakanoille uskon oven.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 14, 28, 'Ja he viipyivät pitkän aikaa opetuslasten tykönä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 1, 'Ja Juudeasta tuli sinne muutamia, jotka opettivat veljiä: \"Ellette ympärileikkauta itseänne, niinkuin Mooses on säätänyt, ette voi pelastua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 2, 'Kun siitä syntyi riita ja kun Paavali ja Barnabas kiivaasti väittelivät heitä vastaan, niin päätettiin, että Paavalin ja Barnabaan ja muutamien muiden heistä tuli mennä tämän riitakysymyksen tähden apostolien ja vanhinten tykö Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 3, 'Niin seurakunta varusti heidät matkalle, ja he kulkivat Foinikian ja Samarian kautta ja kertoivat pakanain kääntymyksestä ja ilahuttivat sillä suuresti kaikkia veljiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 4, 'Ja kun he saapuivat Jerusalemiin, niin seurakunta ja apostolit ja vanhimmat ottivat heidät vastaan; ja he kertoivat, kuinka Jumala oli ollut heidän kanssansa ja tehnyt suuria.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 5, 'Mutta fariseusten lahkosta nousivat muutamat, jotka olivat tulleet uskoon, ja sanoivat: \"Heidät on ympärileikattava ja heitä on käskettävä noudattamaan Mooseksen lakia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 6, 'Niin apostolit ja vanhimmat kokoontuivat tutkimaan tätä asiaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 7, 'Ja kun oli paljon väitelty, nousi Pietari ja sanoi heille: \"Miehet, veljet, te tiedätte, että Jumala jo kauan aikaa sitten teki teidän keskuudessanne sen valinnan, että pakanat minun suustani saisivat kuulla evankeliumin sanan ja tulisivat uskoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 8, 'Ja Jumala, sydänten tuntija, todisti heidän puolestansa, antaen heille Pyhän Hengen samoinkuin meillekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 9, 'eikä tehnyt mitään erotusta meidän ja heidän kesken, sillä hän puhdisti heidän sydämensä uskolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 10, 'Miksi te siis nyt kiusaatte Jumalaa ja tahdotte panna opetuslasten niskaan ikeen, jota eivät meidän isämme emmekä mekään ole jaksaneet kantaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 11, 'Mutta me uskomme Herran Jeesuksen armon kautta pelastuvamme, samalla tapaa kuin hekin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 12, 'Niin koko joukko vaikeni, ja he kuuntelivat Barnabasta ja Paavalia, jotka kertoivat, kuinka suuria tunnustekoja ja ihmeitä Jumala oli tehnyt pakanain keskuudessa heidän kauttansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 13, 'Kun he olivat lakanneet puhumasta, lausui Jaakob: \"Miehet, veljet, kuulkaa minua!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 14, 'Simeon on kertonut, kuinka Jumala ensi kerran katsoi pakanain puoleen ottaakseen heistä kansan omalle nimellensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 15, 'Ja tämän kanssa pitävät yhtä profeettain sanat, sillä näin on kirjoitettu:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 16, '\'Sen jälkeen minä palajan ja pystytän jälleen Daavidin sortuneen majan; minä korjaan sen repeämät ja nostan sen jälleen pystyyn,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 17, 'että jäljelle jääneet ihmiset etsisivät Herraa, ynnä kaikki pakanat, jotka ovat minun nimiini otetut, sanoo Herra, joka tämän tekee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 18, 'mikä on ollut tunnettua hamasta ikiajoista\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 19, 'Sentähden minä olen sitä mieltä, ettei tule rasittaa niitä, jotka pakanuudesta kääntyvät Jumalan puoleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 20, 'vaan heille kirjoitettakoon, että heidän pitää karttaman epäjumalien saastuttamaa ja haureutta ja lihaa, josta ei veri ole laskettu, sekä verta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 21, 'Sillä Mooseksella on ammoisista ajoista asti joka kaupungissa julistajansa; luetaanhan häntä synagoogissa jokaisena sapattina.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 22, 'Silloin apostolit ja vanhimmat ja koko seurakunta näkivät hyväksi valita keskuudestaan muutamia miehiä ja lähettää heidät Antiokiaan Paavalin ja Barnabaan mukana, nimittäin Juudaan, jota kutsuttiin Barsabbaaksi, ja Silaan, jotka olivat johtavia miehiä veljien joukossa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 23, 'ja kirjoittivat heidän mukaansa näin kuuluvan kirjeen: \"Me apostolit ja vanhimmat, teidän veljenne, lähetämme teille, pakanuudesta kääntyneille veljille Antiokiassa ja Syyriassa ja Kilikiassa, tervehdyksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 24, 'Koska olemme kuulleet, että muutamat meistä lähteneet, joille emme ole mitään käskyä antaneet, ovat puheillaan tehneet teidät levottomiksi ja saattaneet teidän sielunne hämmennyksiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 25, 'niin me olemme yksimielisesti nähneet hyväksi valita miehiä ja lähettää heidät teidän tykönne rakkaiden veljiemme Barnabaan ja Paavalin kanssa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 26, 'jotka ovat panneet henkensä alttiiksi meidän Herramme Jeesuksen Kristuksen nimen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 27, 'Me lähetämme siis Juudaan ja Silaan, jotka myös suusanalla ilmoittavat teille saman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 28, 'Sillä Pyhä Henki ja me olemme nähneet hyväksi, ettei teidän päällenne ole pantava enempää kuormaa kuin nämä välttämättömät:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 29, 'että kartatte epäjumalille uhrattua ja verta ja lihaa, josta ei veri ole laskettu, ja haureutta. Jos te näitä vältätte, niin teidän käy hyvin. Jääkää hyvästi!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 30, 'Niin heidät lähetettiin matkalle, ja he tulivat Antiokiaan; siellä he kutsuivat koolle seurakunnan ja antoivat heille kirjeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 31, 'Ja kun he olivat sen lukeneet, iloitsivat he tästä lohdutuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 32, 'Ja Juudas ja Silas, jotka itsekin olivat profeettoja, kehoittivat veljiä monin sanoin ja vahvistivat heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 33, 'Ja heidän viivyttyään siellä jonkin aikaa veljet laskivat heidät rauhassa palaamaan niiden tykö, jotka olivat heidät lähettäneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 34, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 35, 'Ja Paavali ja Barnabas viipyivät Antiokiassa opettaen ja julistaen useiden muidenkin kanssa Herran sanaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 36, 'Mutta muutamien päivien kuluttua Paavali sanoi Barnabaalle: \"Lähtekäämme takaisin kaikkiin niihin kaupunkeihin, joissa olemme julistaneet Herran sanaa, katsomaan veljiä, miten heidän on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 37, 'Niin Barnabas tahtoi ottaa mukaan Johanneksenkin, jota kutsuttiin Markukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 38, 'Mutta Paavali katsoi oikeaksi olla ottamatta häntä mukaan, koska hän oli luopunut heistä Pamfyliassa eikä ollut heidän kanssaan lähtenyt työhön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 39, 'Ja he kiivastuivat niin, että erkanivat toisistaan, ja Barnabas otti mukaansa Markuksen ja purjehti Kyproon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 40, 'Mutta Paavali valitsi Silaan, ja veljet jättivät hänet Herran armon haltuun, ja hän lähti matkalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 15, 41, 'Ja hän vaelsi läpi Syyrian ja Kilikian vahvistaen seurakuntia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 1, 'Niin hän saapui myös Derbeen ja Lystraan. Ja katso, siellä oli eräs opetuslapsi, nimeltä Timoteus, joka oli uskovaisen juutalaisvaimon poika, mutta isä oli kreikkalainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 2, 'Hänestä veljet, jotka olivat Lystrassa ja Ikonionissa, todistivat hyvää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 3, 'Paavali tahtoi häntä mukaansa matkalle ja otti hänet ja ympärileikkasi hänet juutalaisten tähden, joita oli niillä paikkakunnilla; sillä kaikki tiesivät, että hänen isänsä oli kreikkalainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 4, 'Ja sitä mukaa kuin he vaelsivat kaupungista kaupunkiin, antoivat he heille noudatettaviksi ne säädökset, jotka apostolit ja Jerusalemin vanhimmat olivat hyväksyneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 5, 'Niin seurakunnat vahvistuivat uskossa ja saivat päivä päivältä yhä enemmän jäseniä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 6, 'Ja he kulkivat Frygian ja Galatian maan kautta, sillä Pyhä Henki esti heitä julistamasta sanaa Aasiassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 7, 'Ja tultuaan Mysian kohdalle he yrittivät lähteä Bityniaan, mutta Jeesuksen Henki ei sallinut heidän sitä tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 8, 'Niin he vaelsivat ohi Mysian ja menivät Trooaaseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 9, 'Ja Paavali näki yöllä näyn: makedonialainen mies seisoi ja pyysi häntä sanoen: \"Tule yli Makedoniaan ja auta meitä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 10, 'Ja kun hän oli nähnyt sen näyn, niin me kohta tahdoimme päästä lähtemään Makedoniaan, sillä me käsitimme, että Jumala oli kutsunut meitä julistamaan heille evankeliumia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 11, 'Kun nyt olimme purjehtineet Trooaasta, kuljimme suoraan Samotrakeen, ja seuraavana päivänä Neapoliin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 12, 'ja sieltä Filippiin, joka on ensimmäinen kaupunki siinä osassa Makedoniaa, siirtokunta. Siinä kaupungissa me viivyimme muutamia päiviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 13, 'Ja sapatinpäivänä me menimme kaupungin portin ulkopuolelle, joen rannalle, jossa arvelimme olevan rukouspaikan, ja istuimme sinne ja puhuimme kokoontuneille naisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 14, 'Ja eräs Lyydia niminen purppuranmyyjä Tyatiran kaupungista, jumalaapelkääväinen nainen, oli kuulemassa; ja Herra avasi hänen sydämensä ottamaan vaarin siitä, mitä Paavali puhui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 15, 'Ja kun hänet ja hänen perhekuntansa oli kastettu, pyysi hän meitä sanoen: \"Jos te pidätte minua Herraan uskovaisena, niin tulkaa minun kotiini ja majailkaa siellä\". Ja hän vaati meitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 16, 'Ja tapahtui meidän mennessämme rukouspaikkaan, että meitä vastaan tuli eräs palvelijatar, jossa oli tietäjähenki ja joka tuotti paljon tuloja isännilleen ennustamisellaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 17, 'Hän seurasi Paavalia ja meitä ja huusi sanoen: \"Nämä miehet ovat korkeimman Jumalan palvelijoita, jotka julistavat teille pelastuksen tien\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 18, 'Ja tätä hän teki monta päivää. Mutta se vaivasi Paavalia, ja hän kääntyi ja sanoi hengelle: \"Jeesuksen Kristuksen nimessä minä käsken sinun lähteä hänestä\". Ja se lähti sillä hetkellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 19, 'Mutta kun hänen isäntänsä näkivät, että tulojen toivo oli heiltä kadonnut, ottivat he Paavalin ja Silaan kiinni ja vetivät heidät torille hallitusmiesten eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 20, 'Ja vietyänsä heidät päällikköjen eteen he sanoivat: \"Nämä miehet häiritsevät meidän kaupunkimme rauhaa; he ovat juutalaisia');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 21, 'ja opettavat tapoja, joita meidän ei ole lupa omaksua eikä noudattaa, koska me olemme roomalaisia\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 22, 'Ja kansakin nousi heitä vastaan, ja päälliköt revittivät heiltä vaatteet ja käskivät lyödä heitä raipoilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 23, 'Ja kun olivat heitä paljon pieksättäneet, heittivät he heidät vankeuteen ja käskivät vanginvartijan tarkasti vartioida heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 24, 'Sellaisen käskyn saatuaan tämä heitti heidät sisimpään vankihuoneeseen ja pani heidät jalkapuuhun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 25, 'Mutta keskiyön aikaan Paavali ja Silas olivat rukouksissa ja veisasivat ylistystä Jumalalle; ja vangit kuuntelivat heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 26, 'Silloin tapahtui yhtäkkiä suuri maanjäristys, niin että vankilan perustukset järkkyivät, ja samassa kaikki ovet aukenivat, ja kaikkien kahleet irtautuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 27, 'Kun vanginvartija heräsi ja näki vankilan ovien olevan auki, veti hän miekkansa ja aikoi surmata itsensä, luullen vankien karanneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 28, 'Mutta Paavali huusi suurella äänellä sanoen: \"Älä tee itsellesi mitään pahaa, sillä me kaikki olemme täällä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 29, 'Niin hän pyysi valoa, juoksi sisälle ja lankesi vavisten Paavalin ja Silaan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 30, 'Ja hän vei heidät ulos ja sanoi: \"Herrat, mitä minun pitää tekemän, että minä pelastuisin?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 31, 'Niin he sanoivat: \"Usko Herraan Jeesukseen, niin sinä pelastut, niin myös sinun perhekuntasi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 32, 'Ja he puhuivat Jumalan sanaa hänelle ynnä kaikille, jotka hänen kodissansa olivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 33, 'Ja hän otti heidät mukaansa samalla yön hetkellä ja pesi heidän haavansa, ja hänet ja kaikki hänen omaisensa kastettiin kohta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 34, 'Ja hän vei heidät ylös asuntoonsa, laittoi heille aterian ja riemuitsi siitä, että hän ja koko hänen perheensä oli tullut Jumalaan uskovaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 35, 'Päivän tultua päälliköt lähettivät oikeudenpalvelijat sanomaan: \"Päästä irti ne miehet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 36, 'Niin vanginvartija ilmoitti tämän Paavalille sanoen: \"Päälliköt ovat lähettäneet sanan, että teidät on päästettävä irti; lähtekää siis nyt ulos ja menkää rauhassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 37, 'Mutta Paavali sanoi heille: \"He ovat julkisesti, vieläpä ilman tuomiota, ruoskineet meitä, jotka olemme Rooman kansalaisia, ja ovat heittäneet meidät vankeuteen; ja nytkö he salaa ajaisivat meidät tiehemme! Ei niin, vaan tulkoot itse ja viekööt meidät ulos.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 38, 'Ja oikeudenpalvelijat kertoivat ne sanat päälliköille; niin nämä peljästyivät kuullessaan heidän olevan roomalaisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 39, 'ja he tulivat ja suostuttelivat heitä ja veivät heidät ulos ja pyysivät heitä lähtemään pois kaupungista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 16, 40, 'Niin he lähtivät vankilasta ja menivät Lyydian tykö; ja nähtyään veljet ja rohkaistuaan heitä he lähtivät pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 1, 'Ja he matkustivat Amfipolin ja Apollonian kautta ja tulivat Tessalonikaan, jossa oli juutalaisten synagooga.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 2, 'Ja tapansa mukaan Paavali meni sisälle heidän luoksensa ja keskusteli kolmena sapattina heidän kanssansa, lähtien kirjoituksista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 3, 'selitti ne ja osoitti, että Kristuksen piti kärsimän ja nouseman kuolleista, ja sanoi: \"Tämä Jeesus, jota minä teille julistan, on Kristus\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 4, 'Ja muutamat heistä tulivat uskoon ja liittyivät Paavaliin ja Silaaseen, niin myös suuri joukko jumalaapelkääväisiä kreikkalaisia sekä useat ylhäiset naiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 5, 'Mutta juutalaiset joutuivat kiihkoon ja ottivat avukseen muutamia pahanilkisiä miehiä joutoväestä, haalivat kansaa kokoon ja nostivat kaupungissa metelin. He asettuivat Jaasonin talon edustalle ja hakivat Paavalia ja Silasta viedäkseen heidät kansan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 6, 'Mutta kun he eivät heitä löytäneet, raastoivat he Jaasonin ja muutamia veljiä kaupungin hallitusmiesten eteen ja huusivat: \"Nuo koko maailman villitsijät ovat tännekin tulleet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 7, 'ja heidät Jaason on ottanut vastaan; ja nämä kaikki tekevät vastoin keisarin asetuksia, sanoen erään toisen, Jeesuksen, olevan kuninkaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 8, 'Kun kansa ja hallitusmiehet tämän kuulivat, tulivat he levottomiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 9, 'Ja nämä ottivat takauksen Jaasonilta ja muilta ja päästivät heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 10, 'Mutta veljet lähettivät heti yötä myöten Paavalin ja Silaan Bereaan. Ja kun he olivat saapuneet sinne, menivät he juutalaisten synagoogaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 11, 'Nämä olivat jalompia kuin Tessalonikan juutalaiset; he ottivat sanan vastaan hyvin halukkaasti ja tutkivat joka päivä kirjoituksia, oliko asia niin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 12, 'Ja monet heistä uskoivat, niin myös useat ylhäiset kreikkalaiset naiset ja miehet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 13, 'Mutta kun Tessalonikan juutalaiset saivat tietää, että Paavali Bereassakin julisti Jumalan sanaa, tulivat he sinnekin yllyttämään ja kiihoittamaan kansaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 14, 'Silloin veljet heti lähettivät Paavalin menemään meren rantaan; mutta sekä Silas että Timoteus jäivät Bereaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 15, 'Ja Paavalin saattajat veivät hänet Ateenaan saakka, ja saatuaan vietäväksi Silaalle ja Timoteukselle käskyn mitä pikimmin tulla hänen luoksensa, he lähtivät sieltä pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 16, 'Mutta Paavalin odottaessa heitä Ateenassa hänen henkensä hänessä kiivastui, kun hän näki, että kaupunki oli täynnä epäjumalankuvia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 17, 'Niin hän keskusteli synagoogassa juutalaisten ja jumalaapelkääväisten kanssa ja torilla joka päivä niiden kanssa, joita hän siellä tapasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 18, 'Ja muutamat epikurolaiset ja stoalaiset filosofit väittelivät hänen kanssansa; ja toiset sanoivat: \"Mitähän tuo lavertelija oikein tahtoo sanoa?\" Toiset taas sanoivat: \"Näkyy olevan vieraiden jumalien julistaja\", koska hän julisti heille evankeliumia Jeesuksesta ja ylösnousemuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 19, 'Ja he ottivat hänet ja veivät Areiopagille ja sanoivat: \"Voimmeko saada tietää, mikä se uusi oppi on, jota sinä ilmoitat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 20, 'Sillä outoja asioita sinä tuot meidän korvaimme kuulla. Me siis tahdomme tietää, mitä ne oikein ovat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 21, 'Sillä ateenalaisilla ja siellä oleskelevilla muukalaisilla ei kenelläkään ollut aikaa muuhun kuin uutta puhumaan ja uutta kuulemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 22, 'Niin Paavali astui keskelle Areiopagia ja sanoi: \"Ateenan miehet, minä näen kaikesta, että te suuresti kunnioitatte jumalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 23, 'Sillä kävellessäni ympäri ja katsellessani teidän pyhiä paikkojanne minä löysin myös alttarin, johon oli kirjoitettu: \'Tuntemattomalle jumalalle\'. Mitä te siis tuntemattanne palvelette, sen minä teille ilmoitan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 24, 'Jumala, joka on tehnyt maailman ja kaikki, mitä siinä on, hän, joka on taivaan ja maan Herra, ei asu käsillä tehdyissä temppeleissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 25, 'eikä häntä voida ihmisten käsillä palvella, ikäänkuin hän jotakin tarvitsisi, hän, joka itse antaa kaikille elämän ja hengen ja kaiken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 26, 'Ja hän on tehnyt koko ihmissuvun yhdestä ainoasta asumaan kaikkea maanpiiriä ja on säätänyt heille määrätyt ajat ja heidän asumisensa rajat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 27, 'että he etsisivät Jumalaa, jos ehkä voisivat hapuilemalla hänet löytää-hänet, joka kuitenkaan ei ole kaukana yhdestäkään meistä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 28, 'sillä hänessä me elämme ja liikumme ja olemme, niinkuin myös muutamat teidän runoilijoistanne ovat sanoneet: \'Sillä me olemme myös hänen sukuansa\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 29, 'Koska me siis olemme Jumalan sukua, emme saa luulla, että jumaluus on samankaltainen kuin kulta tai hopea tai kivi, sellainen kuin inhimillisen taiteen ja ajatuksen kuvailema.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 30, 'Noita tietämättömyyden aikoja Jumala on kärsinyt, mutta nyt hän tekee tiettäväksi, että kaikkien ihmisten kaikkialla on tehtävä parannus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 31, 'Sillä hän on säätänyt päivän, jona hän on tuomitseva maanpiirin vanhurskaudessa sen miehen kautta, jonka hän siihen on määrännyt; ja hän on antanut kaikille siitä vakuuden, herättämällä hänet kuolleista.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 32, 'Kuullessaan kuolleitten ylösnousemuksesta toiset ivasivat, toiset taas sanoivat: \"Me tahdomme kuulla sinulta tästä vielä toistekin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 33, 'Ja niin Paavali lähti heidän keskeltänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 17, 34, 'Mutta muutamat liittyivät häneen ja uskoivat; niiden joukossa oli Dionysius, Areiopagin jäsen, ja eräs nainen, nimeltä Damaris, sekä muita heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 1, 'Sen jälkeen Paavali lähti Ateenasta ja meni Korinttoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 2, 'Siellä hän tapasi erään Akylas nimisen juutalaisen, joka oli Pontosta syntyisin ja äsken tullut Italiasta, ja hänen vaimonsa Priskillan. Klaudius oli näet käskenyt kaikkien juutalaisten poistua Roomasta. Ja Paavali meni heidän luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 3, 'Ja kun hänellä oli sama ammatti kuin heillä, jäi hän heidän luoksensa, ja he tekivät työtä yhdessä; sillä he olivat ammatiltaan teltantekijöitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 4, 'Ja hän keskusteli synagoogassa jokaisena sapattina ja sai sekä juutalaisia että kreikkalaisia uskomaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 5, 'Ja kun Silas ja Timoteus tulivat Makedoniasta, oli Paavali kokonaan antautunut sanan julistamiseen ja todisti juutalaisille, että Jeesus on Kristus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 6, 'Mutta kun he vastustivat ja herjasivat, pudisti hän vaatteitansa ja sanoi heille: \"Tulkoon teidän verenne oman päänne päälle! Viaton olen minä; tästedes minä menen pakanain tykö.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 7, 'Ja hän lähti sieltä ja meni erään Titius Justus nimisen jumalaapelkääväisen miehen tykö, jonka talo oli aivan synagoogan vieressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 8, 'Mutta synagoogan esimies Krispus ja koko hänen perhekuntansa uskoivat Herraan; ja myöskin monet korinttolaiset, jotka olivat kuulemassa, uskoivat, ja heidät kastettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 9, 'Ja Herra sanoi yöllä näyssä Paavalille: \"Älä pelkää, vaan puhu, äläkä vaikene,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 10, 'sillä minä olen sinun kanssasi, eikä kukaan ole ryhtyvä sinuun tehdäkseen sinulle pahaa, sillä minulla on paljon kansaa tässä kaupungissa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 11, 'Niin hän viipyi siellä vuoden ja kuusi kuukautta opettaen heidän keskuudessaan Jumalan sanaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 12, 'Mutta Gallionin ollessa Akaian käskynhaltijana juutalaiset yksimielisesti nousivat Paavalia vastaan ja veivät hänet tuomioistuimen eteen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 13, 'ja sanoivat: \"Tämä viettelee ihmisiä palvelemaan Jumalaa lainvastaisella tavalla\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 14, 'Ja kun Paavali aikoi avata suunsa, sanoi Gallion juutalaisille: \"Jos olisi tehty rikos tai häijy ilkityö, olisi kohtuullista, että minä kärsivällisesti kuuntelisin teitä, juutalaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 15, 'Mutta jos teillä on riitakysymyksiä opista ja nimistä ja teidän laistanne, olkoot ne teidän huolenanne; niiden tuomari minä en tahdo olla.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 16, 'Ja hän ajoi heidät pois tuomioistuimen edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 17, 'Niin he kaikki ottivat kiinni Soosteneen, synagoogan esimiehen, ja löivät häntä tuomioistuimen edessä, eikä Gallion välittänyt siitä mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 18, 'Mutta Paavali viipyi siellä vielä jonkun aikaa; sitten hän sanoi veljille jäähyväiset ja purjehti Syyriaan, mukanansa Priskilla ja Akylas; hän oli leikkauttanut tukkansa Kenkreassa, sillä hän oli tehnyt lupauksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 19, 'Ja he saapuivat Efesoon; sinne hän jätti heidät. Ja hän meni synagoogaan ja keskusteli juutalaisten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 20, 'Ja he pyysivät häntä viipymään kauemmin, mutta hän ei suostunut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 21, 'vaan sanoi heille jäähyväiset ja lausui: \"Minä palaan jälleen teidän tykönne, jos Jumala suo\". Ja hän lähti purjehtimaan Efesosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 22, 'Ja noustuaan maihin Kesareassa hän vaelsi ylös Jerusalemiin ja tervehti seurakuntaa ja meni sitten alas Antiokiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 23, 'Kun hän oli viettänyt siellä jonkun aikaa, lähti hän matkalle ja kulki järjestään kautta Galatian maakunnan ja Frygian, vahvistaen kaikkia opetuslapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 24, 'Ja Efesoon saapui eräs juutalainen, nimeltä Apollos, syntyisin Aleksandriasta, puhetaitoinen mies ja väkevä raamatuissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 25, 'Tälle oli opetettu Herran tie, ja hän puhui palavana hengessä ja opetti tarkoin Jeesuksesta, mutta tunsi ainoastaan Johanneksen kasteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 26, 'Hän rupesi rohkeasti puhumaan synagoogassa. Mutta kun Priskilla ja Akylas olivat häntä kuunnelleet, ottivat he hänet luokseen ja selvittivät hänelle tarkemmin Jumalan tien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 27, 'Ja kun hän tahtoi mennä Akaiaan, niin veljet kehoittivat häntä siihen ja kirjoittivat opetuslapsille, että nämä ottaisivat hänet vastaan. Ja sinne saavuttuaan hän armon kautta oli suureksi hyödyksi uskoon tulleille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 18, 28, 'Sillä hän kumosi suurella voimalla julkisesti juutalaisten väitteet ja näytti kirjoituksista toteen, että Jeesus on Kristus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 1, 'Kun Apollos oli Korintossa, tuli Paavali, kuljettuaan läpi ylämaakuntien, Efesoon ja tapasi siellä muutamia opetuslapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 2, 'Ja hän sanoi heille: \"Saitteko Pyhän Hengen silloin, kun te tulitte uskoon?\" Niin he sanoivat hänelle: \"Emme ole edes kuulleet, että Pyhää Henkeä on olemassakaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 3, 'Ja hän sanoi: \"Millä kasteella te sitten olette kastetut?\" He vastasivat: \"Johanneksen kasteella\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 4, 'Niin Paavali sanoi: \"Johannes kastoi parannuksen kasteella, kehoittaen kansaa uskomaan häneen, joka oli tuleva hänen jälkeensä, se on, Jeesukseen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 5, 'Sen kuultuaan he ottivat kasteen Herran Jeesuksen nimeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 6, 'Ja kun Paavali pani kätensä heidän päälleen, tuli heidän päällensä Pyhä Henki, ja he puhuivat kielillä ja ennustivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 7, 'Heitä oli kaikkiaan noin kaksitoista miestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 8, 'Ja hän meni synagoogaan, ja kolmen kuukauden ajan hän puhui heidän kanssansa rohkeasti ja vakuuttavasti Jumalan valtakunnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 9, 'Mutta kun muutamat paaduttivat itsensä eivätkä uskoneet, vaan puhuivat pahaa Herran tiestä kansan edessä, niin hän meni pois heidän luotaan ja erotti opetuslapset heistä ja piti joka päivä keskusteluja Tyrannuksen koulussa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 10, 'Ja sitä kesti kaksi vuotta, niin että kaikki Aasian asukkaat, sekä juutalaiset että kreikkalaiset, saivat kuulla Herran sanan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 11, 'Ja Jumala teki ylen voimallisia tekoja Paavalin kätten kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 12, 'niin että vieläpä hikiliinoja ja esivaatteita hänen iholtansa vietiin sairasten päälle, ja taudit lähtivät heistä ja pahat henget pakenivat pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 13, 'Myöskin muutamat kuljeksivat juutalaiset loitsijat rupesivat lausumaan Herran Jeesuksen nimeä niiden ylitse, joissa oli pahoja henkiä, sanoen: \"Minä vannotan teitä sen Jeesuksen kautta, jota Paavali julistaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 14, 'Ja niiden joukossa, jotka näin tekivät, oli myös erään juutalaisen ylipapin, Skeuaan, seitsemän poikaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 15, 'mutta paha henki vastasi heille sanoen: \"Jeesuksen minä tunnen, ja Paavalin minä tiedän, mutta keitä te olette?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 16, 'Ja se mies, jossa paha henki oli, karkasi heidän kimppuunsa, voitti heidät toisen toisensa perästä ja runteli heitä, niin että he alastomina ja haavoitettuina pakenivat siitä huoneesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 17, 'Ja tämän saivat tietää kaikki Efeson asukkaat, sekä juutalaiset että kreikkalaiset; ja heidät kaikki valtasi pelko, ja Herran Jeesuksen nimeä ylistettiin suuresti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 18, 'Ja monet niistä, jotka olivat tulleet uskoon, menivät ja tunnustivat ja ilmoittivat tekonsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 19, 'Ja useat niistä, jotka olivat taikuutta harjoittaneet, kantoivat kirjansa kokoon ja polttivat ne kaikkien nähden; ja kun niiden arvo laskettiin yhteen, huomattiin sen olevan viisikymmentä tuhatta hopearahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 20, 'Näin Herran sana voimallisesti kasvoi ja vahvistui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 21, 'Kun kaikki tämä oli tapahtunut, niin Paavali hengessä päätti kulkea Makedonian ja Akaian kautta ja matkustaa Jerusalemiin ja sanoi: \"Käytyäni siellä minun pitää nähdä myös Rooma\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 22, 'Ja hän lähetti Makedoniaan kaksi apumiehistänsä, Timoteuksen ja Erastuksen, mutta jäi itse joksikin aikaa Aasiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 23, 'Tähän aikaan syntyi sangen suuri melu siitä tiestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 24, 'Sillä eräs hopeaseppä, nimeltä Demetrius, joka valmisti hopeaisia Artemiin temppeleitä, hankki sillä ammattilaisille melkoisia tuloja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 25, 'Hän kutsui kokoon nämä sekä muut, jotka sellaista työtä tekivät, ja sanoi: \"Miehet, te tiedätte, että meillä on hyvä toimeentulomme tästä työstä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 26, 'mutta nyt te näette ja kuulette, että tuo Paavali on, ei ainoastaan Efesossa, vaan melkein koko Aasiassa, uskotellut ja vietellyt paljon kansaa, sanoen, etteivät ne ole jumalia, jotka käsillä tehdään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 27, 'Ja nyt uhkaa se vaara, että ei ainoastaan tämä meidän elinkeinomme joudu halveksituksi, vaan myöskin, että suuren Artemis jumalattaren temppeliä ei pidetä minäkään ja että hän menettää mahtavuutensa, hän, jota koko Aasia ja koko maanpiiri palvelee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 28, 'Kun he sen kuulivat, tulivat he vihaa täyteen ja huusivat sanoen: \"Suuri on efesolaisten Artemis!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 29, 'Ja koko kaupunki joutui sekasortoon, ja he ryntäsivät kaikki yhdessä näytelmäpaikkaan ja tempasivat mukaansa Gaiuksen ja Aristarkuksen, kaksi makedonialaista, jotka olivat Paavalin matkatovereita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 30, 'Ja kun Paavali tahtoi mennä kansanjoukkoon, eivät opetuslapset sitä sallineet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 31, 'Ja myös muutamat Aasian hallitusmiehistä, jotka olivat hänen ystäviään, lähettivät hänelle sanan ja pyysivät, ettei hän menisi näytelmäpaikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 32, 'Ja he huusivat, mikä mitäkin; sillä kokous oli sekasortoinen, ja useimmat eivät tienneet, minkätähden he olivat tulleet kokoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 33, 'Silloin vedettiin joukosta esille Aleksander, jota juutalaiset työnsivät esiin; niin Aleksander viittasi kädellään merkiksi, että hän tahtoi pitää puolustuspuheen kansan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 34, 'Mutta kun he huomasivat, että hän oli juutalainen, rupesivat he kaikki yhteen ääneen huutamaan ja kirkuivat noin kaksi hetkeä: \"Suuri on efesolaisten Artemis!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 35, 'Mutta kun kaupungin kansleri oli saanut kansan rauhoittumaan, sanoi hän: \"Efeson miehet, onko ketään, joka ei tiedä, että efesolaisten kaupunki on suuren Artemiin temppelin ja hänen taivaasta pudonneen kuvansa vaalija?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 36, 'Koska ei kukaan voi tätä kieltää, tulee teidän siis pysyä rauhallisina eikä tehdä mitään harkitsematonta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 37, 'Te olette kuitenkin tuoneet tänne nämä miehet, jotka eivät ole temppelin ryöstäjiä eivätkä ole meidän jumalatartamme pilkanneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 38, 'Jos siis Demetriuksella ja hänen ammattiveljillänsä on riita-asiaa jotakuta vastaan, niin pidetäänhän oikeudenistuntoja ja onhan käskynhaltijoita; vetäkööt toisensa oikeuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 39, 'Ja jos teillä on vielä jotakin muuta vaadittavaa, niin ratkaistakoon asia laillisessa kansankokouksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 40, 'Sillä tämänpäiväisen tapahtuman tähden me olemme vaarassa joutua syytteeseen jopa kapinasta, vaikkei mitään aihetta olekaan; ja silloin me emme voi vastata tästä mellakasta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 19, 41, '{19:40} Näin puhuen hän sai kokouksen hajaantumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 1, 'Kun meteli oli asettunut, kutsui Paavali opetuslapset luoksensa; ja rohkaistuaan heitä hän jätti heidät hyvästi ja lähti matkustamaan Makedoniaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 2, 'Ja kuljettuaan niiden paikkakuntien läpi ja puhuttuaan siellä monta kehoituksen sanaa hän tuli Kreikkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 3, 'Siellä hän oleskeli kolme kuukautta. Ja kun juutalaiset olivat tehneet häntä vastaan salahankkeen hänen aikoessaan lähteä meritse Syyriaan, päätti hän tehdä paluumatkansa Makedonian kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 4, 'Ja häntä seurasivat berealainen Soopater, Pyrruksen poika, ja tessalonikalaisista Aristarkus ja Sekundus, derbeläinen Gaius, Timoteus sekä aasialaiset Tykikus ja Trofimus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 5, 'Nämä menivät edeltä ja odottivat meitä Trooaassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 6, 'mutta me purjehdimme happamattoman leivän juhlan jälkeen Filippistä ja tulimme viidentenä päivänä heidän luoksensa Trooaaseen ja viivyimme siellä seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 7, 'Ja kun viikon ensimmäisenä päivänä olimme kokoontuneet murtamaan leipää, niin Paavali, joka seuraavana päivänä aikoi matkustaa pois, keskusteli heidän kanssansa ja pitkitti puhettaan puoliyöhön saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 8, 'Ja monta lamppua oli palamassa yläsalissa, jossa me olimme koolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 9, 'Niin eräs nuorukainen, nimeltä Eutykus, istui ikkunalla, ja kun Paavalin puhe kesti niin kauan, vaipui hän sikeään uneen ja putosi unen vallassa kolmannesta kerroksesta maahan; ja hänet nostettiin ylös kuolleena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 10, 'Mutta Paavali meni alas, heittäytyi hänen ylitsensä, kiersi kätensä hänen ympärilleen ja sanoi: \"Älkää hätäilkö, sillä hänessä on vielä henki\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 11, 'Niin hän meni jälleen ylös, mursi leipää ja söi; ja hän puhui kauan heidän kanssansa, päivän koittoon asti, ja lähti sitten matkalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 12, 'Ja he veivät pojan sieltä elävänä ja tulivat suuresti lohdutetuiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 13, 'Mutta me menimme edeltäpäin ja astuimme laivaan ja purjehdimme Assoon. Sieltä aioimme ottaa Paavalin laivaan, sillä hän oli niin määrännyt, aikoen itse kulkea maitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 14, 'Ja kun hän yhtyi meihin Assossa, otimme hänet laivaan ja kuljimme Mityleneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 15, 'Sieltä me purjehdimme ja saavuimme toisena päivänä Kion kohdalle; seuraavana päivänä laskimme Samoon ja tulimme sen jälkeisenä päivänä Miletoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 16, 'Sillä Paavali oli päättänyt purjehtia Efeson ohitse, ettei häneltä kuluisi aikaa Aasiassa; sillä hän kiiruhti joutuakseen, jos suinkin mahdollista, helluntaiksi Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 17, 'Mutta Miletosta hän lähetti sanan Efesoon ja kutsui tykönsä seurakunnan vanhimmat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 18, 'Ja kun he saapuivat hänen tykönsä, sanoi hän heille: \"Te tiedätte ensimmäisestä päivästä asti, kun minä Aasiaan tulin, miten minä kaiken aikaa olen ollut teidän kanssanne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 19, 'kuinka minä olen palvellut Herraa kaikella nöyryydellä ja kyynelillä, koettelemuksissa, jotka ovat kohdanneet minua juutalaisten salahankkeiden tähden;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 20, 'kuinka minä en ole vetäytynyt pois julistamasta teille sitä, mikä hyödyllistä on, ja opettamasta teitä sekä julkisesti että huone huoneelta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 21, 'vaan olen todistanut sekä juutalaisille että kreikkalaisille parannusta kääntymyksessä Jumalan puoleen ja uskoa meidän Herraamme Jeesukseen Kristukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 22, 'Ja nyt, katso, minä matkustan, sidottuna hengessä, Jerusalemiin, enkä tiedä, mikä minua siellä kohtaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 23, 'Sen vain tiedän, että Pyhä Henki jokaisessa kaupungissa todistaa minulle ja sanoo, että kahleet ja ahdistukset minua odottavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 24, 'En minä kuitenkaan pidä henkeäni itselleni minkään arvoisena, kunhan vain täytän juoksuni ja sen viran, jonka minä Herralta Jeesukselta olen saanut: Jumalan armon evankeliumin todistamisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 25, 'Ja nyt, katso, minä tiedän, ettette enää saa nähdä minun kasvojani, ei kukaan teistä, joiden keskuudessa minä olen vaeltanut ja saarnannut valtakuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 26, 'Sentähden minä todistan teille tänä päivänä, että minä olen viaton kaikkien vereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 27, 'Sillä minä en ole vetäytynyt pois julistamasta teille kaikkea Jumalan tahtoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 28, 'Ottakaa siis itsestänne vaari ja kaikesta laumasta, johon Pyhä Henki on teidät pannut kaitsijoiksi, paimentamaan Herran seurakuntaa, jonka hän omalla verellänsä on itselleen ansainnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 29, 'Minä tiedän, että minun lähtöni jälkeen teidän keskuuteenne tulee julmia susia, jotka eivät laumaa säästä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 30, 'ja teidän omasta joukostanne nousee miehiä, jotka väärää puhetta puhuvat, vetääkseen opetuslapset mukaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 31, 'Valvokaa sentähden ja muistakaa, että minä olen kolme vuotta lakkaamatta yötä ja päivää kyynelin neuvonut teitä itsekutakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 32, 'Ja nyt minä uskon teidät Jumalan ja hänen armonsa sanan haltuun, hänen, joka on voimallinen rakentamaan teitä ja antamaan teille perintöosan kaikkien pyhitettyjen joukossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 33, 'En minä ole halunnut kenenkään hopeata tai kultaa tai vaatteita;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 34, 'te tiedätte itse, että nämä minun käteni ovat työllänsä hankkineet, mitä minä ja seuralaiseni olemme tarvinneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 35, 'Kaikessa minä olen osoittanut teille, että näin työtä tehden tulee huolehtia heikoista ja muistaa nämä Herran Jeesuksen sanat, jotka hän itse sanoi: \'Autuaampi on antaa kuin ottaa\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 36, 'Ja tämän sanottuaan hän polvistui ja rukoili kaikkien heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 37, 'Ja he ratkesivat kaikki haikeasti itkemään ja lankesivat Paavalin kaulaan ja suutelivat häntä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 20, 38, 'ja enimmän suretti heitä se sana, jonka hän oli sanonut, etteivät he enää saisi nähdä hänen kasvojansa. Ja he saattoivat hänet laivaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 1, 'Kun olimme eronneet heistä ja lähteneet purjehtimaan, laskimme suoraan Koossaareen ja seuraavana päivänä Rodoon ja sieltä Pataraan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 2, 'Siellä tapasimme Foinikiaan menevän laivan, astuimme siihen ja lähdimme purjehtimaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 3, 'Ja kun Kypro rupesi näkymään ja oli jäänyt meistä vasemmalle, purjehdimme Syyriaan ja nousimme maihin Tyyrossa; siellä näet laivan oli määrä purkaa lastinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 4, 'Ja tavattuamme opetuslapset me viivyimme siellä seitsemän päivää. Ja Hengen vaikutuksesta he varoittivat Paavalia menemästä Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 5, 'Mutta kun olimme viettäneet loppuun ne päivät, lähdimme matkalle, ja kaikki saattoivat vaimoineen ja lapsineen meitä kaupungin ulkopuolelle saakka. Ja me laskeuduimme rannalla polvillemme ja rukoilimme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 6, 'ja sanottuamme jäähyväiset toisillemme astuimme laivaan, ja he palasivat kotiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 7, 'Tyyrosta me saavuimme Ptolemaikseen, ja siihen päättyi purjehduksemme. Ja me tervehdimme veljiä siellä ja viivyimme päivän heidän luonansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 8, 'Mutta seuraavana päivänä me lähdimme sieltä ja tulimme Kesareaan, jossa menimme evankelista Filippuksen tykö, joka oli yksi niistä seitsemästä, ja jäimme hänen tykönsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 9, 'Ja hänellä oli neljä tytärtä, neitsyttä, joilla oli profetoimisen lahja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 10, 'Siellä me viivyimme useita päiviä. Niin tuli sinne Juudeasta eräs profeetta, nimeltä Agabus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 11, 'Ja tultuaan meidän luoksemme hän otti Paavalin vyön, sitoi sillä jalkansa ja kätensä ja lausui: \"Näin sanoo Pyhä Henki: \'Sen miehen, jonka vyö tämä on, juutalaiset näin sitovat Jerusalemissa ja antavat pakanain käsiin\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 12, 'Kun sen kuulimme, pyysimme, sekä me että ne, jotka siellä asuivat, ettei hän menisi Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 13, 'Silloin Paavali vastasi ja sanoi: \"Mitä te teette, kun itkette ja särjette minun sydäntäni. Sillä minä olen valmis, en ainoastaan käymään sidottavaksi vaan myöskin kuolemaan Jerusalemissa Herran Jeesuksen nimen tähden.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 14, 'Ja kun hän ei taipunut, niin me rauhoituimme ja sanoimme: \"Tapahtukoon Herran tahto\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 15, 'Niiden päivien kuluttua me hankkiuduimme ja menimme ylös Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 16, 'Ja meidän kanssamme tuli myös opetuslapsia Kesareasta, jotka veivät meidät majapaikkaamme, erään vanhan opetuslapsen, kyprolaisen Mnasonin, tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 17, 'Ja saavuttuamme Jerusalemiin veljet ottivat meidät iloiten vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 18, 'Seuraavana päivänä Paavali meni meidän kanssamme Jaakobin tykö, ja kaikki vanhimmat tulivat sinne saapuville.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 19, 'Ja kun hän oli heitä tervehtinyt, kertoi hän kohta kohdalta kaikki, mitä Jumala hänen palveluksensa kautta oli tehnyt pakanain keskuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 20, 'Sen kuultuaan he ylistivät Jumalaa ja sanoivat Paavalille: \"Sinä näet, veli, kuinka monta tuhatta juutalaista on tullut uskoon, ja he ovat kaikki lainkiivailijoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 21, 'Mutta heille on kerrottu sinusta, että sinä opetat kaikkia pakanain seassa asuvia juutalaisia luopumaan Mooseksesta ja kiellät heitä ympärileikkaamasta lapsiaan ja vaeltamasta säädettyjen tapojen mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 22, 'Mitä siis on tehtävä? Varmaankin on suuri joukko kokoontuva, sillä he saavat kuulla sinun tulleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 23, 'Tee siis tämä, minkä me nyt sinulle sanomme. Meillä on täällä neljä miestä, joilla on lupaus täytettävänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 24, 'Ota ne luoksesi ja puhdista itsesi heidän kanssansa ja maksa kulut heidän puolestaan, että he saisivat leikkauttaa tukkansa; siitä kaikki huomaavat, ettei ole mitään perää siinä, mitä heille on kerrottu sinusta, vaan että sinäkin vaellat lain mukaan ja noudatat sitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 25, 'Mutta uskoon tulleista pakanoista me olemme päättäneet ja kirjoittaneet, että heidän on välttäminen epäjumalille uhrattua ja verta ja lihaa, josta ei veri ole laskettu, ja haureutta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 26, 'Silloin Paavali otti ne miehet luokseen, ja kun hän seuraavana päivänä oli puhdistanut itsensä heidän kanssaan, meni hän pyhäkköön ja ilmoitti, milloin heidän puhdistumispäivänsä tulisivat päättymään, jota ennen heidän kunkin edestä oli tuotava uhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 27, 'Mutta kun ne seitsemän päivää olivat päättymässä, näkivät Aasiasta tulleet juutalaiset hänet pyhäkössä, kiihoittivat kaiken kansan ja kävivät häneen käsiksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 28, 'ja huusivat: \"Israelin miehet, auttakaa! Tämä on se mies, joka kaikkialla opettaa kaikkia ihmisiä meidän kansaamme ja lakiamme ja tätä paikkaa vastaan, onpa vielä tuonut kreikkalaisia pyhäkköönkin ja saastuttanut tämän pyhän paikan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 29, 'Sillä he olivat ennen nähneet efesolaisen Trofimuksen kaupungilla hänen kanssaan ja luulivat, että Paavali oli tuonut hänet pyhäkköön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 30, 'Ja koko kaupunki tuli liikkeelle, ja väkeä juoksi kokoon; ja he ottivat Paavalin kiinni, raastoivat hänet ulos pyhäköstä, ja heti portit suljettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 31, 'Ja kun he tahtoivat hänet tappaa, sai sotaväenosaston päällikkö sanan, että koko Jerusalem oli kuohuksissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 32, 'Tämä otti heti paikalla mukaansa sotilaita ja sadanpäämiehiä ja riensi alas heidän luoksensa. Kun he näkivät päällikön ja sotilaat, lakkasivat he lyömästä Paavalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 33, 'Silloin päällikkö astui esiin, otatti hänet kiinni ja käski sitoa hänet kaksilla kahleilla ja kysyi, kuka hän oli ja mitä hän oli tehnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 34, 'Mutta kansanjoukosta huusivat toiset sitä, toiset tätä. Ja koska hän melun tähden ei voinut saada varmaa selkoa, käski hän viedä hänet kasarmiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 35, 'Ja kun Paavali tuli portaille, täytyi sotamiesten kantaa häntä kansan väkivallan tähden;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 36, 'sillä suuri kansanpaljous seurasi perässä ja huusi: \"Vie pois hänet!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 37, 'Ja kun oltiin kuljettamassa Paavalia sisälle kasarmiin, sanoi hän päällikölle: \"Onko minun lupa sanoa sinulle jotakin?\" Niin tämä sanoi: \"Osaatko sinä siis kreikkaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 38, 'Etkö sitten olekaan se egyptiläinen, joka hiljakkoin villitsi ne neljätuhatta murhamiestä ja vei heidät erämaahan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 39, 'Niin Paavali sanoi: \"Minä olen juutalainen mies, Tarson, tunnetun Kilikian kaupungin, kansalainen; pyydän sinua, salli minun puhua kansalle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 21, 40, 'Ja kun hän sen salli, niin Paavali, seisoen portailla, viittasi kädellään kansalle; ja kun oli syntynyt syvä hiljaisuus, puhui hän heille hebreankielellä ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 1, '\"Miehet, veljet ja isät, kuulkaa, mitä minä nyt teille puolustuksekseni puhun\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 2, 'Kun he kuulivat hänen puhuvan heille hebreankielellä, syntyi vielä suurempi hiljaisuus. Ja hän sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 3, '\"Minä olen juutalainen, syntynyt Kilikian Tarsossa, mutta kasvatettu tässä kaupungissa ja Gamalielin jalkojen juuressa opetettu tarkkaan noudattamaan isien lakia; ja minä kiivailin Jumalan puolesta, niinkuin te kaikki tänä päivänä kiivailette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 4, 'Ja minä vainosin tätä tietä aina kuolemaan asti, sitoen ja heittäen vankeuteen sekä miehiä että naisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 5, 'niinkuin myös ylimmäinen pappi voi minusta todistaa, ja kaikki vanhimmat. Minä sain heiltä myös kirjeitä veljille Damaskoon, ja minä matkustin sinne tuodakseni nekin, jotka siellä olivat, sidottuina Jerusalemiin rangaistaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 6, 'Niin tapahtui, kun minä matkalla ollessani lähestyin Damaskoa, että keskipäivän aikaan yhtäkkiä taivaasta leimahti suuri valo minun ympärilläni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 7, 'ja minä kaaduin maahan ja kuulin äänen sanovan minulle: \'Saul, Saul, miksi vainoat minua?\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 8, 'Niin minä vastasin: \'Kuka olet, herra?\' Ja hän sanoi minulle: \'Minä olen Jeesus Nasaretilainen, jota sinä vainoat\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 9, 'Ja minun seuralaiseni näkivät kyllä valon, mutta eivät kuulleet sen ääntä, joka minulle puhui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 10, 'Ja minä sanoin: \'Herra, mitä minun pitää tekemän?\' Herra sanoi minulle: \'Nouse ja mene Damaskoon, niin siellä sinulle sanotaan kaikki, mikä sinulle on tehtäväksi asetettu\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 11, 'Ja kun minä sen valon kirkkaudesta tulin näkemättömäksi, taluttivat seuralaiseni minua kädestä, ja niin minä tulin Damaskoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 12, 'Ja eräs mies, hurskas lain mukaan, nimeltä Ananias, josta kaikki siellä asuvat juutalaiset todistivat hyvää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 13, 'tuli minun tyköni, astui eteeni ja sanoi minulle: \'Saul, veljeni, saa näkösi jälleen\'. Ja sillä hetkellä minä sain näköni ja katsoin häneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 14, 'Niin hän sanoi: \'Meidän isiemme Jumala on valinnut sinut tuntemaan hänen tahtonsa ja näkemään Vanhurskaan ja kuulemaan hänen suunsa äänen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 15, 'sillä sinä olet oleva hänen todistajansa kaikkien ihmisten edessä, sen todistaja, mitä olet nähnyt ja kuullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 16, 'Ja nyt, mitä viivyttelet? Nouse, huuda avuksi hänen nimeänsä ja anna kastaa itsesi ja pestä pois syntisi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 17, 'Kun olin palannut Jerusalemiin, tapahtui minun rukoillessani pyhäkössä, että minä jouduin hurmoksiin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 18, 'ja näin hänet. Ja hän sanoi minulle: \'Riennä ja lähde pian pois Jerusalemista, sillä he eivät ota vastaan sinun todistustasi minusta\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 19, 'Ja minä sanoin: \'Herra, he tietävät itse, että minä panin vankeuteen ja ruoskitin jokaisessa synagoogassa niitä, jotka uskoivat sinuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 20, 'Ja kun Stefanuksen, sinun todistajasi, veri vuodatettiin, olin minäkin läsnä, hyväksyin sen ja vartioin hänen surmaajainsa vaatteita.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 21, 'Ja hän sanoi minulle: \'Mene, sillä minä lähetän sinut kauas pakanain tykö\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 22, 'Tähän sanaan asti he kuuntelivat häntä; mutta silloin he korottivat äänensä ja sanoivat: \"Pois maan päältä tuommoinen! Sillä ei hän saa elää.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 23, 'Ja kun he huusivat ja heittelivät vaatteitaan ja viskoivat tomua ilmaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 24, 'käski päällikkö viedä hänet kasarmiin, ja saadakseen tietää, mistä syystä he niin hänelle huusivat, hän määräsi hänet ruoskimalla tutkittavaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 25, 'Mutta kun he olivat oikaisseet hänet ruoskittavaksi, sanoi Paavali siinä seisovalle sadanpäämiehelle: \"Onko teidän lupa ruoskia Rooman kansalaista, vieläpä ilman tuomiota?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 26, 'Kun sadanpäämies sen kuuli, meni hän päällikölle ilmoittamaan ja sanoi: \"Mitä aiot tehdä? Tämä mies on Rooman kansalainen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 27, 'Niin päällikkö meni Paavalin luo ja sanoi hänelle: \"Sano minulle: oletko sinä Rooman kansalainen?\" Hän vastasi: \"Olen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 28, 'Niin päällikkö sanoi: \"Minä olen paljolla rahalla hankkinut itselleni tämän kansalaisoikeuden\". Paavali sanoi: \"Mutta minulla se on syntymästäni asti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 29, 'Silloin ne, joiden piti häntä tutkia, lähtivät heti hänen luotaan. Ja myös päällikkö peljästyi saatuaan tietää, että Paavali oli Rooman kansalainen, kun oli sidottanut hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 22, 30, 'Mutta seuraavana päivänä, koska hän tahtoi saada varman tiedon, mistä juutalaiset häntä syyttivät, päästi hän hänet siteistä ja käski ylipappien ja koko neuvoston kokoontua, vei Paavalin alas ja asetti hänet heidän eteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 1, 'Niin Paavali loi katseensa neuvostoon ja sanoi: \"Miehet, veljet, minä olen kaikessa hyvällä omallatunnolla vaeltanut Jumalan edessä tähän päivään asti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 2, 'Mutta ylimmäinen pappi Ananias käski lähellä seisovia lyömään häntä vasten suuta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 3, 'Silloin Paavali sanoi hänelle: \"Jumala on lyövä sinua, sinä valkeaksi kalkittu seinä; istutko sinä tuomitsemassa minua lain mukaan ja käsket vastoin lakia lyödä minua?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 4, 'Niin ne, jotka seisoivat lähellä, sanoivat: \"Herjaatko sinä Jumalan ylimmäistä pappia?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 5, 'Ja Paavali sanoi: \"En tiennyt, veljet, että hän on ylimmäinen pappi; sillä kirjoitettu on: \'Kansasi ruhtinasta älä kiroa\'\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 6, 'Mutta koska Paavali tiesi osan heistä olevan saddukeuksia ja toisen osan fariseuksia, huusi hän neuvoston edessä: \"Miehet, veljet, minä olen fariseus, fariseusten jälkeläinen; toivon ja kuolleitten ylösnousemuksen tähden minä olen tuomittavana\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 7, 'Tuskin hän oli tämän sanonut, niin nousi riita fariseusten ja saddukeusten kesken, ja kokous jakautui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 8, 'Sillä saddukeukset sanovat, ettei ylösnousemusta ole, ei enkeliä eikä henkeä, mutta fariseukset tunnustavat kumpaisetkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 9, 'Ja syntyi suuri huuto, ja muutamat kirjanoppineet fariseusten puolueesta nousivat ja väittelivät kiivaasti ja sanoivat: \"Emme löydä mitään pahaa tässä miehessä; entäpä jos henki tai enkeli on hänelle puhunut?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 10, 'Ja kun riita yhä kiihtyi, pelkäsi päällikkö, että he repisivät Paavalin kappaleiksi, ja käski sotaväen tulla alas ja temmata hänet heidän keskeltään ja viedä hänet kasarmiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 11, 'Mutta seuraavana yönä Herra seisoi Paavalin tykönä ja sanoi: \"Ole turvallisella mielellä, sillä niinkuin sinä olet todistanut minusta Jerusalemissa, niin sinun pitää todistaman minusta myös Roomassa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 12, 'Mutta päivän tultua juutalaiset tekivät salaliiton ja vannoivat valan, etteivät söisi eivätkä joisi, ennenkuin olivat tappaneet Paavalin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 13, 'Ja niitä oli viidettäkymmentä miestä, jotka yhtyivät tähän valaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 14, 'He menivät ylipappien ja vanhinten luo ja sanoivat: \"Me olemme kirouksen uhalla vannoneet, ettemme mitään maista, ennenkuin olemme tappaneet Paavalin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 15, 'Pyytäkää te siis nyt yhdessä neuvoston kanssa päälliköltä, että hän toisi hänet alas teidän luoksenne, ikäänkuin aikoisitte tarkemmin tutkia hänen asiaansa. Mutta me olemme valmiit tappamaan hänet, ennenkuin hän pääsee perille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 16, 'Mutta Paavalin sisarenpoika, joka oli saanut kuulla väijytyksestä, saapui kasarmille, meni sisälle ja ilmoitti sen Paavalille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 17, 'Niin Paavali kutsui luoksensa erään sadanpäämiehen ja sanoi: \"Vie tämä nuorukainen päällikön luo, sillä hänellä on jotakin hänelle ilmoitettavaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 18, 'Niin hän otti hänet mukaansa, vei hänet päällikön luo ja sanoi: \"Vanki Paavali kutsui minut luokseen ja pyysi tuomaan sinun luoksesi tämän nuorukaisen, jolla on jotakin puhuttavaa sinulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 19, 'Niin päällikkö tarttui hänen käteensä, vei hänet erikseen ja kysyi: \"Mitä sinulla on minulle ilmoitettavaa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 20, 'Hän sanoi: \"Juutalaiset ovat päättäneet anoa sinulta, että huomenna veisit Paavalin alas neuvostoon, ikäänkuin aikoisit vielä tarkemmin tutkia hänen asiaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 21, 'Mutta älä sinä siihen suostu, sillä viidettäkymmentä miestä heidän joukostaan on häntä väijymässä, ja he ovat vannoneet valan, etteivät syö eivätkä juo, ennenkuin ovat tappaneet hänet. Ja nyt he ovat valmiina ja odottavat sinun suostumustasi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 22, 'Niin päällikkö päästi nuorukaisen menemään ja sanoi hänelle: \"Älä virka kenellekään, että olet ilmaissut tämän minulle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 23, 'Sitten hän kutsui luoksensa kaksi sadanpäämiestä ja sanoi heille: \"Pitäkää yön kolmannesta hetkestä lähtien kaksisataa sotamiestä valmiina lähtemään Kesareaan ja seitsemänkymmentä ratsumiestä ja kaksisataa keihäsmiestä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 24, 'ja varatkaa ratsuja pannaksenne Paavalin ratsaille ja viedäksenne hänet vahingoittumatonna maaherra Feeliksin luo\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 25, 'Ja hän kirjoitti kirjeen, joka kuului näin:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 26, '\"Klaudius Lysias lausuu tervehdyksen korkea-arvoiselle maaherralle Feeliksille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 27, 'Tämän miehen ottivat juutalaiset kiinni ja olivat vähällä hänet tappaa; silloin minä tulin saapuville sotaväen kanssa ja pelastin hänet, saatuani tietää, että hän on Rooman kansalainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 28, 'Ja koska tahdoin tietää, mistä asiasta he häntä syyttivät, vein hänet heidän neuvostoonsa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 29, 'ja havaitsin, että häntä syytettiin heidän lakiaan koskevista riitakysymyksistä, mutta ettei ollut kannetta mistään, mikä ansaitsisi kuoleman tai kahleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 30, 'Mutta kun minulle on annettu ilmi, että miestä vastaan on tekeillä salahanke, lähetän hänet nyt heti sinun luoksesi; olen myös kehoittanut hänen syyttäjiään sanomaan sanottavansa häntä vastaan sinun edessäsi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 31, 'Niin sotamiehet, saamansa käskyn mukaan, ottivat Paavalin ja veivät hänet yötä myöten Antipatrikseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 32, 'Seuraavana päivänä he antoivat ratsumiesten jatkaa hänen kanssaan matkaa, mutta itse he palasivat kasarmiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 33, 'Kun ratsumiehet tulivat Kesareaan, antoivat he kirjeen maaherralle ja veivät myös Paavalin hänen eteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 34, 'Luettuaan kirjeen hän kysyi, mistä maakunnasta Paavali oli; ja saatuaan tietää, että hän oli Kilikiasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 23, 35, 'hän sanoi: \"Minä kuulustelen sinua, kun syyttäjäsikin saapuvat\". Ja hän käski vartioida häntä Herodeksen linnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 1, 'Viiden päivän kuluttua ylimmäinen pappi Ananias meni sinne alas muutamien vanhinten ja erään asianajajan, Tertulluksen, kanssa, ja he ilmoittivat maaherralle syyttävänsä Paavalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 2, 'Ja kun Paavali oli kutsuttu esille, rupesi Tertullus syyttämään ja sanoi:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 3, '\"Runsasta rauhaa me olemme sinun kauttasi, korkea-arvoinen Feeliks, saaneet nauttia, ja sinun huolenpidostasi on parannuksia aikaansaatu tämän kansan hyväksi, sen me kaikin puolin ja kaikkialla ja kaikella kiitollisuudella tunnustamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 4, 'Mutta etten aivan kauan sinua viivyttäisi, pyydän sinua hetkisen meitä suosiollisesti kuulemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 5, 'Me olemme havainneet, että tämä mies on ruttotauti ja metelinnostaja kaikkien koko maailman juutalaisten keskuudessa ja nasaretilaisten lahkon päämies,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 6, 'ja hän on koettanut pyhäkönkin saastuttaa. Sentähden me otimme hänet kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 7, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 8, 'Voit itse häntä tutkimalla saada tietää kaiken, mistä me häntä syytämme.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 9, 'Ja myös juutalaiset yhtyivät syyttämään häntä ja väittivät asian niin olevan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 10, 'Paavali vastasi, kun maaherra oli viitannut, että hän sai puhua: \"Koska tiedän sinun monta vuotta olleen tämän kansan tuomarina, puhun luottamuksella asiani puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 11, 'Niinkuin voit saada tietää, ei ole kuin kaksitoista päivää siitä, kun menin Jerusalemiin rukoilemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 12, 'Eivät he ole tavanneet minua kenenkään kanssa väittelemästä eikä väentungoksia aikaansaamasta, ei pyhäkössä, ei synagoogissa eikä kaupungilla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 13, 'eivätkä myöskään voi näyttää sinulle toteen sitä, mistä he nyt minua syyttävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 14, 'Mutta sen minä sinulle tunnustan, että minä sitä tietä vaeltaen, jota he lahkoksi sanovat, niin palvelen isieni Jumalaa, että minä uskon kaiken, mitä on kirjoitettuna laissa ja profeetoissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 15, 'ja pidän sen toivon Jumalaan, että on oleva ylösnousemus, jota nämä itsekin odottavat, sekä vanhurskasten että vääräin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 16, 'Sentähden minä myös ahkeroitsen, että minulla aina olisi loukkaamaton omatunto Jumalan ja ihmisten edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 17, 'Niin minä nyt useampien vuosien kuluttua tulin tuomaan almuja kansalleni ja toimittamaan uhreja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 18, 'Näitä toimittaessani muutamat Aasiasta tulleet juutalaiset tapasivat minut puhdistautuneena pyhäkössä, eikä ollut mitään väentungosta tai meteliä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 19, 'heidän tulisi nyt olla saapuvilla sinun edessäsi ja syyttää, jos heillä olisi jotakin minua vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 20, 'Tai sanokoot nämä läsnäolevat, mitä rikollista he minussa huomasivat, kun minä seisoin neuvoston edessä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 21, 'jollei siksi luettane tätä ainoata lausetta, jonka huusin seisoessani heidän keskellään: \'Kuolleitten ylösnousemuksen tähden minä tänään olen teidän tuomittavananne\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 22, 'Mutta Feeliks, jolla oli hyvin tarkka tieto tästä tiestä, lykkäsi heidän asiansa toistaiseksi, sanoen: \"Kun päällikkö Lysias tulee tänne, tutkin minä teidän asianne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 23, 'Ja hän käski sadanpäämiehen pitää Paavalia vartioituna, mutta lievässä vankeudessa, estämättä ketään hänen omaisistaan tekemästä hänelle palvelusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 24, 'Muutamien päivien kuluttua Feeliks tuli vaimonsa Drusillan kanssa, joka oli juutalainen, haetti Paavalin ja kuunteli hänen puhettaan uskosta Kristukseen Jeesukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 25, 'Mutta kun Paavali puhui vanhurskaudesta ja itsensähillitsemisestä ja tulevasta tuomiosta, peljästyi Feeliks ja sanoi: \"Mene tällä haavaa pois, mutta kun minulle sopii, kutsutan sinut taas\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 26, 'Sen ohessa hän myös toivoi saavansa Paavalilta rahaa, jonka tähden hän useita kertoja haetti hänet luokseen ja puheli hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 24, 27, 'Mutta kahden vuoden kuluttua Porkius Festus tuli Feeliksin sijaan; ja kun Feeliks tavoitteli juutalaisten suosiota, jätti hän Paavalin kahleisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 1, 'Kun nyt Festus oli astunut maaherranvirkaan, meni hän kolmen päivän kuluttua Kesareasta ylös Jerusalemiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 2, 'Niin ylipapit ja juutalaisten ensimmäiset miehet ilmoittivat hänelle syyttävänsä Paavalia ja pyysivät häneltä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 3, 'ja anoivat sitä suosionosoitusta itsellensä, Paavalia vastaan, että hän haettaisi hänet Jerusalemiin; sillä he valmistivat väijytystä tappaakseen hänet tiellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 4, 'Mutta Festus vastasi, että Paavalia pidettiin vartioituna Kesareassa ja että hän itse aikoi piakkoin lähteä sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 5, 'Ja hän lisäsi: \"Tulkoot siis teidän johtomiehenne minun mukanani sinne alas, ja jos siinä miehessä on jotakin väärää, syyttäkööt häntä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 6, 'Ja viivyttyään heidän luonansa ainoastaan kahdeksan tai kymmenen päivää hän meni alas Kesareaan. Seuraavana päivänä hän istui tuomarinistuimelle ja käski tuoda Paavalin eteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 7, 'Ja kun hän oli saapunut, asettuivat ne juutalaiset, jotka olivat tulleet Jerusalemista, hänen ympärilleen ja tekivät useita ja raskaita syytöksiä, joita he eivät kuitenkaan kyenneet näyttämään toteen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 8, 'sillä Paavali torjui syytökset ja sanoi: \"Minä en ole mitään rikkonut juutalaisten lakia enkä pyhäkköä enkä keisaria vastaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 9, 'Niin Festus, joka tavoitteli juutalaisten suosiota, vastasi Paavalille ja sanoi: \"Tahdotko lähteä Jerusalemiin ja siellä vastata näihin syytöksiin minun edessäni?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 10, 'Mutta Paavali sanoi: \"Minä seison keisarin tuomioistuimen edessä, ja sen edessä minut tuomittakoon. Juutalaisia vastaan en ole mitään rikkonut, niinkuin sinäkin aivan hyvin tiedät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 11, 'Vaan jos muuten olen rikkonut ja tehnyt jotakin, mikä ansaitsee kuoleman, en pyri pääsemään kuolemasta; mutta jos se, mistä nämä minua syyttävät, on perätöntä, niin ei kukaan voi luovuttaa minua heille. Minä vetoan keisariin.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 12, 'Silloin Festus, neuvoteltuaan neuvoskuntansa kanssa, vastasi: \"Keisariin sinä olet vedonnut, niinpä mene keisarin eteen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 13, 'Muutamien päivien kuluttua kuningas Agrippa ja Bernike saapuivat Kesareaan tervehtimään Festusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 14, 'Ja kun he viipyivät siellä useampia päiviä, kertoi Festus Paavalin asian kuninkaalle ja sanoi: \"Täällä on eräs mies, jonka Feeliks on jättänyt vankeuteen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 15, 'käydessäni Jerusalemissa juutalaisten ylipapit ja vanhimmat ilmoittivat syyttävänsä häntä ja pyysivät, että hänet tuomittaisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 16, 'Mutta minä vastasin heille: \'Ei ole roomalaisten tapa antaa ketään alttiiksi, ennenkuin syytetty on asetettu vastakkain syyttäjäinsä kanssa ja on saanut puolustautua syytöstä vastaan\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 17, 'Kun he olivat kokoontuneet tänne, niin minä viivyttelemättä seuraavana päivänä istuin tuomarinistuimelle ja käskin tuoda miehen eteeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 18, 'Mutta kun hänen syyttäjänsä seisoivat hänen ympärillään, eivät he syyttäneet häntä mistään sellaisesta rikoksesta, kuin minä olin odottanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 19, 'vaan heillä oli häntä vastaan riitaa joistakin heidän uskonasioistaan ja jostakin Jeesuksesta, joka oli kuollut, mutta jonka Paavali väitti elävän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 20, 'Ja kun olin epätietoinen, miten tällainen asia oli tutkittava, kysyin, tahtoiko hän mennä Jerusalemiin ja siellä vastata näihin syytöksiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 21, 'Mutta kun Paavali vetosi ja vaati, että hänet oli säilytettävä majesteetin tutkittavaksi, käskin minä vartioida häntä, kunnes lähetän hänet keisarin eteen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 22, 'Niin Agrippa sanoi Festukselle: \"Minäkin tahtoisin kuulla sitä miestä\". Tämä sanoi: \"Huomenna saat kuulla häntä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 23, 'Seuraavana päivänä Agrippa ja Bernike tulivat suurella komeudella ja menivät oikeussaliin päällikköjen ja kaupungin ylhäisten miesten kanssa; ja Paavali tuotiin Festuksen käskystä sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 24, 'Ja Festus sanoi: \"Kuningas Agrippa ja kaikki muut, jotka meidän kanssamme olette läsnä, tässä näette sen miehen, jonka tähden koko juutalaisten joukko sekä Jerusalemissa että täällä on ahdistanut minua huutaen, ettei hänen pidä enää saaman elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 25, 'Minä kuitenkin huomasin, ettei hän ole tehnyt mitään, mikä ansaitsisi kuoleman; mutta kun hän itse vetosi majesteettiin, niin minä päätin lähettää hänet sinne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 26, 'Mitään varmaa minulla ei kuitenkaan ole, mitä hänestä herralleni kirjoittaisin. Sen vuoksi tuotin hänet teidän eteenne ja varsinkin sinun eteesi, kuningas Agrippa, että minulla tutkinnon tapahduttua olisi, mitä kirjoittaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 25, 27, 'Sillä mielettömältä näyttää minusta lähettää vanki, antamatta samalla tietää häntä vastaan tehtyjä syytöksiä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 1, 'Niin Agrippa sanoi Paavalille: \"Sinun on lupa puhua puolestasi\". Silloin Paavali ojensi kätensä ja lausui puolustuksekseen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 2, '\"Pidän itseäni onnellisena, kuningas Agrippa, kun sinun edessäsi tänä päivänä saan puolustautua kaikesta siitä, mistä juutalaiset minua syyttävät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 3, 'olletikin, koska sinä tarkkaan tunnet kaikki juutalaisten tavat ja riitakysymykset. Sentähden pyydän sinua kärsivällisesti minua kuulemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 4, 'Kaikki juutalaiset tuntevat minun elämäni nuoruudestani asti, koska alusta alkaen olen elänyt kansani keskuudessa ja Jerusalemissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 5, 'He tuntevat minut jo entuudestaan, jos tahtovat sen todistaa, että minä meidän uskontomme ankarimman lahkon mukaan olen elänyt fariseuksena.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 6, 'Ja nyt minä seison oikeuden edessä sentähden, että panen toivoni siihen lupaukseen, jonka Jumala on meidän isillemme antanut');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 7, 'ja jonka meidän kaksitoista sukukuntaamme, yötä ja päivää herkeämättä palvellen Jumalaa, toivovat heille toteutuvan; tämän toivon tähden, kuningas, juutalaiset minua syyttävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 8, 'Miksi on teistä uskomatonta, että Jumala herättää kuolleet?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 9, 'Luulin minäkin, että minun tuli paljon taistella Jeesuksen, Nasaretilaisen, nimeä vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 10, 'ja niin minä teinkin Jerusalemissa. Paljon pyhiä minä suljin vankiloihin, saatuani ylipapeilta siihen valtuuden, ja kun heitä tapettiin, annoin minä ääneni sen puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 11, 'Ja kaikkialla synagoogissa minä usein koetin rankaisemalla pakottaa heitä herjaamaan Jeesusta, ja menin niin pitkälle vimmassani heitä vastaan, että vainosin heitä aina ulkomaan kaupunkeihin saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 12, 'Kun näissä asioissa matkustin Damaskoon ylipappien valtuudella ja suostumuksella,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 13, 'näin minä, oi kuningas, tiellä keskellä päivää taivaasta valon, auringon paistetta kirkkaamman, leimahtavan minun ja matkatoverieni ympärillä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 14, 'ja me kaaduimme kaikki maahan, ja minä kuulin äänen sanovan minulle hebreankielellä: \'Saul, Saul, miksi vainoat minua? Työläs on sinun potkia tutkainta vastaan.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 15, 'Niin minä sanoin: \'Kuka olet, herra?\' Ja Herra sanoi: \'Minä olen Jeesus, jota sinä vainoat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 16, 'Mutta nouse ja seiso jaloillasi; sillä sitä varten minä olen sinulle ilmestynyt, että asettaisin sinut palvelijakseni ja sen todistajaksi, mitä varten sinä olet minut nähnyt, niin myös sen, mitä varten minä sinulle vastedes ilmestyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 17, 'Ja minä pelastan sinut sekä oman kansasi että pakanain käsistä, joitten tykö minä sinut lähetän');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 18, 'avaamaan heidän silmänsä, että he kääntyisivät pimeydestä valkeuteen ja saatanan vallasta Jumalan tykö ja saisivat uskomalla minuun synnit anteeksi ja perintöosan pyhitettyjen joukossa.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 19, 'Sentähden, kuningas Agrippa, minä en voinut olla tottelematta taivaallista näkyä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 20, 'vaan saarnasin ensin sekä Damaskon että Jerusalemin asukkaille, ja sitten koko Juudean maalle ja pakanoille parannusta ja kääntymystä Jumalan puoleen, ja että he tekisivät parannuksen soveliaita tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 21, 'Tämän tähden juutalaiset ottivat minut kiinni pyhäkössä ja yrittivät surmata minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 22, 'Mutta Jumalan avulla, jota olen saanut tähän päivään asti, minä seison ja todistan sekä pienille että suurille, enkä puhu mitään muuta, kuin minkä profeetat ja Mooses ovat sanoneet tulevan tapahtumaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 23, 'että nimittäin Kristuksen piti kärsimän ja kuolleitten ylösnousemuksen esikoisena julistaman valkeutta sekä tälle kansalle että pakanoille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 24, 'Mutta kun hän näin puolustautui, sanoi Festus suurella äänellä: \"Sinä olet hullu, Paavali, suuri oppi hulluttaa sinut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 25, 'Mutta Paavali sanoi: \"En ole hullu, korkea-arvoinen Festus, vaan puhun totuuden ja toimen sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 26, 'Kuningas kyllä nämä tietää, jonka tähden minä puhunkin hänelle rohkeasti. Sillä minä en usko minkään näistä asioista olevan häneltä salassa; eiväthän nämä ole missään syrjäsopessa tapahtuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 27, 'Uskotko, kuningas Agrippa, profeettoja? Minä tiedän, että uskot.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 28, 'Niin Agrippa sanoi Paavalille: \"Vähälläpä luulet taivuttavasi minut kristityksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 29, 'Mutta Paavali sanoi: \"Toivoisin Jumalalta, että, olipa vähällä tai paljolla, et ainoastaan sinä, vaan myös kaikki te, jotka minua tänään kuulette, tulisitte semmoisiksi, kuin minä olen, näitä kahleita lukuunottamatta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 30, 'Niin kuningas nousi ja maaherra ja Bernike sekä ne, jotka istuivat heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 31, 'Ja mennessään he puhuivat keskenänsä sanoen: \"Tämä mies ei ole tehnyt mitään, mikä ansaitsisi kuoleman tai kahleet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 26, 32, 'Ja Agrippa sanoi Festukselle: \"Tämän miehen olisi voinut päästää irti, jos hän ei olisi vedonnut keisariin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 1, 'Kun oli päätetty, että meidän oli purjehtiminen Italiaan, annettiin Paavali ja muutamat muut vangit erään Julius nimisen, keisarilliseen sotaväenosastoon kuuluvan sadanpäämiehen haltuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 2, 'Ja me astuimme adramyttiläiseen laivaan, jonka oli määrä purjehtia Aasian rannikkopaikkoihin, ja lähdimme merelle, ja seurassamme oli Aristarkus, makedonialainen Tessalonikasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 3, 'Seuraavana päivänä laskimme Siidoniin. Ja Julius kohteli Paavalia ystävällisesti ja salli hänen mennä ystäviensä luo hoitoa saamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 4, 'Ja sieltä laskettuamme merelle purjehdimme Kypron suojaan, koska tuulet olivat vastaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 5, 'Ja kun olimme merta purjehtien sivuuttaneet Kilikian ja Pamfylian, tulimme Myrraan, joka on Lykiassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 6, 'Siellä sadanpäämies tapasi aleksandrialaisen laivan, jonka oli määrä purjehtia Italiaan, ja siirsi meidät siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 7, 'Ja monta päivää me purjehdimme hitaasti ja pääsimme vaivoin Knidon kohdalle. Ja kun tuulelta emme päässeet sinne, purjehdimme Salmonen nenitse Kreetan suojaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 8, 'Ja vaivoin kuljettuamme liki sen rantaa saavuimme erääseen paikkaan, jonka nimi oli Kauniit Satamat ja jonka lähellä Lasaian kaupunki oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 9, 'Mutta kun paljon aikaa oli kulunut ja purjehtiminen jo oli vaarallista, sillä paastonaikakin oli jo ohi, varoitti Paavali heitä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 10, 'ja sanoi: \"Miehet, minä näen, että purjehtiminen käy vaivalloiseksi ja vaaralliseksi, ei ainoastaan lastille ja laivalle, vaan myös meidän hengellemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 11, 'Mutta sadanpäämies uskoi enemmän perämiestä ja laivanisäntää kuin Paavalin sanoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 12, 'Ja koska satama oli sopimaton talvehtimiseen, olivat useimmat sitä mieltä, että heidän oli sieltä lähdettävä, voidakseen ehkä päästä talvehtimaan Foiniksiin, erääseen Kreetan satamaan, joka antaa lounaaseen ja luoteeseen päin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 13, 'Ja kun etelätuuli alkoi puhaltaa, luulivat he pääsevänsä tarkoituksensa perille, nostivat ankkurin ja kulkivat aivan likitse Kreetaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 14, 'Mutta ennen pitkää syöksyi saaren päällitse raju tuuli, niin sanottu koillismyrsky.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 15, 'Kun laiva ryöstäytyi sen mukaan eikä voinut nousta tuuleen, jätimme sen valtoihinsa ja jouduimme tuuliajolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 16, 'Ja päästyämme erään pienen, Klauda nimisen saaren suojaan me töintuskin saimme venheen korjuuseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 17, 'Vedettyään sen ylös he ryhtyivät varokeinoihin ja sitoivat laivan ympäri köysiä, ja kun pelkäsivät ajautuvansa Syrtteihin, laskivat he purjeet alas, ja niin he ajelehtivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 18, 'Mutta kun rajuilma ankarasti ahdisti meitä, heittivät he seuraavana päivänä lastia mereen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 19, 'ja kolmantena päivänä he omin käsin viskasivat mereen laivan kaluston.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 20, 'Mutta kun ei aurinkoa eikä tähtiä näkynyt moneen päivään ja kova myrsky painoi, katosi meiltä viimein kaikki pelastumisen toivo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 21, 'Kun oli oltu kauan syömättä, niin Paavali nousi heidän keskellään ja sanoi: \"Miehet, teidän olisi pitänyt noudattaa minun neuvoani eikä lähteä Kreetasta; siten olisitte säästyneet tästä vaivasta ja vahingosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 22, 'Mutta nyt minä kehoitan teitä olemaan rohkealla mielellä, sillä ei yksikään teistä huku, ainoastaan laiva hukkuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 23, 'Sillä tänä yönä seisoi minun tykönäni sen Jumalan enkeli, jonka oma minä olen ja jota minä myös palvelen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 24, 'ja sanoi: \'Älä pelkää, Paavali, keisarin eteen sinun pitää menemän; ja katso, Jumala on lahjoittanut sinulle kaikki, jotka sinun kanssasi purjehtivat\'.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 25, 'Olkaa sentähden rohkealla mielellä, miehet; sillä minulla on se usko Jumalaan, että niin käy, kuin minulle on puhuttu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 26, 'Mutta jollekin saarelle meidän täytyy viskautua.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 27, 'Ja kun tuli neljästoista yö meidän ajelehtiessamme Adrianmerellä, tuntui merimiehistä keskiyön aikaan, että lähestyttiin jotakin maata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 28, 'Ja luodattuaan he huomasivat syvyyden olevan kaksikymmentä syltä, ja vähän matkaa kuljettuaan he taas luotasivat ja huomasivat syvyyden viideksitoista syleksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 29, 'Ja kun he pelkäsivät meidän viskautuvan karille, laskivat he laivan perästä neljä ankkuria ja odottivat ikävöiden päivän tuloa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 30, 'Mutta merimiehet yrittivät paeta laivasta ja laskivat venheen mereen sillä tekosyyllä, että muka aikoivat keulapuolesta viedä ulos ankkureita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 31, 'Silloin Paavali sanoi sadanpäämiehelle ja sotilaille: \"Jos nuo eivät pysy laivassa, niin te ette voi pelastua\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 32, 'Silloin sotamiehet hakkasivat poikki venheen köydet ja päästivät sen menemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 33, 'Vähää ennen päivän tuloa Paavali kehoitti kaikkia nauttimaan ruokaa, sanoen: \"Tänään olette jo neljättätoista päivää odottaneet ja olleet syömättä ettekä ole mitään ravintoa ottaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 34, 'Sentähden minä kehoitan teitä nauttimaan ruokaa, sillä se on tarpeen meidän pelastuaksemme; sillä ei yhdeltäkään teistä ole hiuskarvaakaan päästä katoava.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 35, 'Tämän sanottuaan hän otti leivän ja kiitti Jumalaa kaikkien nähden, mursi ja rupesi syömään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 36, 'Silloin kaikki tulivat rohkealle mielelle ja ottivat hekin ruokaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 37, 'Ja meitä oli laivassa kaikkiaan kaksisataa seitsemänkymmentä kuusi henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 38, 'Ja kun he olivat tulleet ravituiksi, kevensivät he laivaa heittämällä viljan mereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 39, 'Päivän tultua he eivät tunteneet maata, mutta huomasivat lahden, jossa oli sopiva ranta; siihen he päättivät, jos mahdollista, laskea laivan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 40, 'Ja he hakkasivat ankkuriköydet poikki ja jättivät ankkurit mereen; samalla he päästivät peräsinten nuorat, nostivat keulapurjeen tuuleen ja ohjasivat rantaa kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 41, 'Mutta he joutuivat riutalle ja antoivat laivan törmätä siihen; keulapuoli tarttui kiinni ja jäi liikkumattomaksi, mutta peräpuoli hajosi aaltojen voimasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 42, 'Niin sotamiehillä oli aikomus tappaa vangit, ettei kukaan pääsisi uimalla karkuun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 43, 'Mutta sadanpäämies, joka tahtoi pelastaa Paavalin, esti heidät siitä aikeesta ja käski uimataitoisten ensiksi heittäytyä veteen ja lähteä maihin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 27, 44, 'ja sitten muiden, minkä laudoilla, minkä laivankappaleilla. Ja näin kaikki pelastuivat maalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 1, 'Kun olimme pelastuneet, niin me sitten saimme tietää, että saaren nimi oli Melite.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 2, 'Ja sen asukkaat osoittivat meille suurta ystävällisyyttä: he sytyttivät nuotion ja ottivat meidät kaikki sen ääreen, kun oli ruvennut satamaan ja oli kylmä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 3, 'Mutta Paavali kokosi kasan risuja, ja kun hän pani ne nuotioon, tuli kyykäärme kuumuuden tähden esiin ja kävi kiinni hänen käteensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 4, 'Kun asukkaat näkivät tuon elukan riippuvan kiinni hänen kädessään, sanoivat he toisilleen: \"Varmaan tuo mies on murhaaja, koska kostotar ei sallinut hänen elää, vaikka hän pelastuikin merestä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 5, 'Mutta hän pudisti elukan tuleen, eikä hänelle tullut mitään vahinkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 6, 'Ja he odottivat hänen ajettuvan tai äkisti kaatuvan kuolleena maahan. Mutta kun he olivat kauan odottaneet ja näkivät, ettei hänelle mitään pahaa tapahtunut, muuttivat he mielensä ja sanoivat hänen olevan jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 7, 'Lähellä sitä paikkaa oli saaren ensimmäisellä miehellä, jonka nimi oli Publius, maatiloja. Hän otti meidät vastaan ja piti meitä ystävällisesti kolme päivää vierainansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 8, 'Ja Publiuksen isä makasi sairaana kuumeessa ja punataudissa; ja Paavali meni hänen luoksensa, rukoili ja pani kätensä hänen päälleen ja paransi hänet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 9, 'Kun tämä oli tapahtunut, tulivat muutkin sairaat, mitä saarella oli, ja heidät parannettiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 10, 'He osoittivat meille myös monin tavoin kunniaa, ja lähtiessämme merelle he panivat mukaan, mitä tarvitsimme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 11, 'Kolmen kuukauden kuluttua me purjehdimme sieltä aleksandrialaisessa laivassa, joka oli talvehtinut saarella ja jolla oli merkkinä Kastorin ja Polluksin kuva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 12, 'Ja me laskimme maihin Syrakuusassa ja viivyimme siellä kolme päivää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 13, 'ja sieltä me kierrettyämme saavuimme Reegioniin, ja kun yhden päivän perästä nousi etelätuuli, tulimme seuraavana päivänä Puteoliin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 14, 'Siellä tapasimme veljiä, jotka pyysivät meitä viipymään heidän tykönänsä seitsemän päivää. Ja sitten me lähdimme Roomaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 15, 'Ja kun veljet siellä saivat kuulla meistä, tulivat he meitä vastaan Appii Forumiin ja Tres Tabernaen kohdalle saakka; ja heidät nähdessään Paavali kiitti Jumalaa ja sai rohkeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 16, 'Ja kun tulimme Roomaan, sallittiin Paavalin asua erikseen häntä vartioivan sotamiehen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 17, 'Kolmen päivän kuluttua Paavali kutsui kokoon juutalaisten ensimmäiset. Ja kun he olivat kokoontuneet, sanoi hän heille: \"Miehet, veljet! Vaikka en ole mitään tehnyt kansaamme tai isiemme tapoja vastaan, annettiin minut kuitenkin Jerusalemista vankina roomalaisten käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 18, 'Ja kun he olivat minua tutkineet, tahtoivat he päästää minut irti, koska en ollut tehnyt mitään kuoleman rikosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 19, 'Mutta kun juutalaiset sitä vastustivat, oli minun pakko vedota keisariin; ei kuitenkaan niin, että minulla olisi mitään kannetta kansaani vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 20, 'Tästä syystä minä nyt olen kutsunut teidät, saadakseni nähdä ja puhutella teitä; sillä Israelin toivon tähden minä kannan tätä kahletta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 21, 'Niin he sanoivat hänelle: \"Emme ole saaneet kirjeitä sinusta Juudean maalta, eikä kukaan tänne saapunut veli ole ilmoittanut eikä puhunut sinusta mitään pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 22, 'Katsomme kuitenkin syytä olevan kuulla sinulta, mitä sinun mielessäsi on; sillä tästä lahkosta on meillä tiedossamme, että sitä vastaan kaikkialla kiistetään.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 23, 'Ja he määräsivät hänelle päivän, ja silloin tuli heitä vielä useampia hänen luoksensa majapaikkaan. Ja näille hän aamuvarhaisesta iltaan saakka selitti ja todisti Jumalan valtakunnasta, lähtien Mooseksen laista ja profeetoista, saadakseen heidät vakuutetuiksi Jeesuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 24, 'Niin se, mitä sanottiin, sai toiset vakuutetuiksi, mutta toiset eivät uskoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 25, 'Ja kun he olivat keskenään erimielisiä, erosivat he toisistaan, Paavalin sanoessa ainoastaan nämä sanat: \"Oikein on Pyhä Henki puhunut profeetta Esaiaan kautta teidän isillenne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 26, 'sanoen: \'Mene tämän kansan luo ja sano: Kuulemalla kuulkaa älkääkä ymmärtäkö, näkemällä nähkää älkääkä käsittäkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 27, 'Sillä paatunut on tämän kansan sydän, ja korvillaan he työläästi kuulevat, ja silmänsä he ovat ummistaneet, että he eivät näkisi silmillään, eivät kuulisi korvillaan, eivät ymmärtäisi sydämellään eivätkä kääntyisi ja etten minä heitä parantaisi.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 28, 'Olkoon siis teille tiettävä, että tämä Jumalan pelastussanoma on lähetetty pakanoille; ja he kuulevat sen.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 29, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 30, 'Ja Paavali asui omassa vuokra-asunnossaan kaksi täyttä vuotta ja otti vastaan kaikki, jotka hänen tykönsä tulivat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 28, 31, 'ja hän julisti Jumalan valtakuntaa ja opetti Herran Jeesuksen Kristuksen tuntemista kaikella rohkeudella, kenenkään estämättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Paavali, Jeesuksen Kristuksen palvelija, kutsuttu apostoli, erotettu julistamaan Jumalan evankeliumia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'jonka Jumala on edeltä luvannut profeettainsa kautta pyhissä kirjoituksissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'hänen Pojastansa-joka lihan puolesta on syntynyt Daavidin siemenestä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'ja pyhyyden hengen puolesta kuolleistanousemisen kautta asetettu Jumalan Pojaksi voimassa-Jeesuksesta Kristuksesta, meidän Herrastamme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'jonka kautta me olemme saaneet armon ja apostolinviran, että syntyisi uskon kuuliaisuus hänen nimeänsä kohtaan kaikissa pakanakansoissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'joihin tekin, Jeesuksen Kristuksen kutsumat, kuulutte:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'kaikille Roomassa oleville Jumalan rakkaille, kutsutuille pyhille. Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Ensiksikin minä kiitän Jumalaani Jeesuksen Kristuksen kautta teidän kaikkien tähden, koska teidän uskoanne mainitaan kaikessa maailmassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Sillä Jumala, jota minä hengessäni palvelen julistaen hänen Poikansa evankeliumia, on minun todistajani, kuinka minä teitä lakkaamatta muistan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'aina rukouksissani anoen, että minä jo vihdoinkin, jos Jumala tahtoo, pääsisin tulemaan teidän tykönne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 11, 'Sillä minä ikävöitsen teitä nähdä, voidakseni antaa teille jonkun hengellisen lahjan, että te vahvistuisitte,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 12, 'se on, että me yhdessä ollessamme virkistyisimme yhteisestä uskostamme, teidän ja minun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 13, 'Ja minä en tahdo, veljet, teiltä salata, että jo monesti olen päättänyt tulla teidän tykönne saadakseni jonkin hedelmän teidänkin keskuudestanne, niinkuin muidenkin pakanain, mutta olen ollut estetty tähän saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 14, 'Kreikkalaisille ja barbaareille, viisaille ja tyhmille minä olen velassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 15, 'omasta puolestani minä siis olen altis teillekin, Roomassa asuvaisille, julistamaan evankeliumia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 16, 'Sillä minä en häpeä evankeliumia; sillä se on Jumalan voima, itsekullekin uskovalle pelastukseksi, juutalaiselle ensin, sitten myös kreikkalaiselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 17, 'Sillä siinä Jumalan vanhurskaus ilmestyy uskosta uskoon, niinkuin kirjoitettu on: \"Vanhurskas on elävä uskosta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 18, 'Sillä Jumalan viha ilmestyy taivaasta kaikkea ihmisten jumalattomuutta ja vääryyttä vastaan, niiden, jotka pitävät totuutta vääryyden vallassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 19, 'sentähden että se, mikä Jumalasta voidaan tietää, on ilmeistä heidän keskuudessaan; sillä Jumala on sen heille ilmoittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 20, 'Sillä hänen näkymätön olemuksensa, hänen iankaikkinen voimansa ja jumalallisuutensa, ovat, kun niitä hänen teoissansa tarkataan, maailman luomisesta asti nähtävinä, niin etteivät he voi millään itseänsä puolustaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 21, 'koska he, vaikka ovat tunteneet Jumalan, eivät ole häntä Jumalana kunnioittaneet eivätkä kiittäneet, vaan ovat ajatuksiltansa turhistuneet, ja heidän ymmärtämätön sydämensä on pimentynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 22, 'Kehuessaan viisaita olevansa he ovat tyhmiksi tulleet');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 23, 'ja ovat katoamattoman Jumalan kirkkauden muuttaneet katoavaisen ihmisen ja lintujen ja nelijalkaisten ja matelevaisten kuvan kaltaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 24, 'Sentähden Jumala on heidät, heidän sydämensä himoissa, hyljännyt saastaisuuteen, häpäisemään itse omat ruumiinsa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 25, 'nuo, jotka ovat vaihtaneet Jumalan totuuden valheeseen ja kunnioittaneet ja palvelleet luotua enemmän kuin Luojaa, joka on ylistetty iankaikkisesti, amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 26, 'Sentähden Jumala on hyljännyt heidät häpeällisiin himoihin; sillä heidän naispuolensa ovat vaihtaneet luonnollisen yhteyden luonnonvastaiseen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 27, 'samoin miespuoletkin, luopuen luonnollisesta yhteydestä naispuolen kanssa, ovat kiimoissaan syttyneet toisiinsa ja harjoittaneet, miespuolet miespuolten kanssa, riettautta ja villiintymisestään saaneet itseensä sen palkan, mikä saada piti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 28, 'Ja niinkuin heille ei kelvannut pitää kiinni Jumalan tuntemisesta, niin Jumala hylkäsi heidät heidän kelvottoman mielensä valtaan, tekemään sopimattomia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 29, 'He ovat täynnänsä kaikkea vääryyttä, pahuutta, ahneutta, häijyyttä, täynnä kateutta, murhaa, riitaa, petosta, pahanilkisyyttä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 30, 'ovat korvaankuiskuttelijoita, panettelijoita, Jumalaa vihaavaisia, väkivaltaisia, ylpeitä, kerskailijoita, pahankeksijöitä, vanhemmilleen tottelemattomia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 31, 'vailla ymmärrystä, luotettavuutta, rakkautta ja laupeutta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 32, 'jotka, vaikka tuntevat Jumalan vanhurskaan säädöksen, että ne, jotka senkaltaisia tekevät, ovat kuoleman ansainneet, eivät ainoastaan itse niitä tee, vaan vieläpä osoittavat hyväksymistä niille, jotka niitä tekevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Sentähden sinä, oi ihminen, et voi millään itseäsi puolustaa, olitpa kuka hyvänsä, joka tuomitset. Sillä mistä toista tuomitset, siihen sinä itsesi syypääksi tuomitset, koska sinä, joka tuomitset, teet samoja tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Ja me tiedämme, että Jumalan tuomio on totuuden mukainen niille, jotka senkaltaista tekevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Vai luuletko, ihminen, sinä, joka tuomitset niitä, jotka senkaltaisia tekevät, ja itse samoja teet, että sinä vältät Jumalan tuomion?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Vai halveksitko hänen hyvyytensä ja kärsivällisyytensä ja pitkämielisyytensä runsautta, etkä tiedä, että Jumalan hyvyys vetää sinua parannukseen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Kovuudellasi ja sydämesi katumattomuudella sinä kartutat päällesi vihaa vihan ja Jumalan vanhurskaan tuomion ilmestymisen päiväksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'hänen, \"joka antaa kullekin hänen tekojensa mukaan\":');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'niille, jotka hyvässä työssä kestävinä etsivät kirkkautta ja kunniaa ja katoamattomuutta, iankaikkisen elämän,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'mutta niiden osaksi, jotka ovat itsekkäitä eivätkä tottele totuutta, vaan tottelevat vääryyttä, tulee viha ja kiivastus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Tuska ja ahdistus jokaisen ihmisen sielulle, joka pahaa tekee, juutalaisen ensin, sitten myös kreikkalaisen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'mutta kirkkaus ja kunnia ja rauha jokaiselle, joka tekee sitä, mikä hyvä on, juutalaiselle ensin, sitten myös kreikkalaiselle!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Sillä Jumala ei katso henkilöön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Sillä kaikki, jotka ilman lakia ovat syntiä tehneet, ne myös ilman lakia hukkuvat, ja kaikki, jotka lain alaisina ovat syntiä tehneet, ne lain mukaan tuomitaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'sillä eivät lain kuulijat ole vanhurskaita Jumalan edessä, vaan lain noudattajat vanhurskautetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Sillä kun pakanat, joilla ei lakia ole, luonnostansa tekevät, mitä laki vaatii, niin he, vaikka heillä ei lakia ole, ovat itse itsellensä laki');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'ja osoittavat, että lain teot ovat kirjoitetut heidän sydämiinsä, kun heidän omatuntonsa myötä-todistaa ja heidän ajatuksensa keskenään syyttävät tai myös puolustavat heitä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'sinä päivänä, jona Jumala on tuomitseva ihmisten salaisuudet Kristuksen Jeesuksen kautta, minun evankeliumini mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Mutta jos sinä kutsut itseäsi juutalaiseksi ja luotat lakiin ja Jumala on sinun kerskauksesi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'ja tunnet hänen tahtonsa ja, opetettuna laissa, tutkit, mikä parasta on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'ja luulet kykeneväsi olemaan sokeain taluttaja, pimeydessä olevien valkeus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'ymmärtämättömien kasvattaja, alaikäisten opettaja, sinulla kun laissa on tiedon ja totuuden muoto:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'niin sinäkö, joka toista opetat, et itseäsi opeta; joka julistat, ettei saa varastaa, itse varastat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'joka sanot, ettei saa tehdä huorin, itse teet huorin; joka kauhistut epäjumalia, kuitenkin olet temppelin ryöstäjä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'joka laista kerskaat, häväiset lainrikkomisella Jumalaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Sillä \"teidän tähtenne Jumalan nimi tulee pilkatuksi pakanain seassa\", niinkuin kirjoitettu on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Ympärileikkaus kyllä on hyödyllinen, jos sinä lakia noudatat; mutta jos olet lainrikkoja, niin sinun ympärileikkauksesi on tullut ympärileikkaamattomuudeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Jos siis ympärileikkaamaton noudattaa lain säädöksiä, eikö hänen ympärileikkaamattomuutensa ole luettava ympärileikkaukseksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Ja luonnostaan ympärileikkaamaton, joka täyttää lain, on tuomitseva sinut, joka lainkirjaiminesi ja ympärileikkauksinesi olet lainrikkoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Sillä ei se ole juutalainen, joka vain ulkonaisesti on juutalainen, eikä ympärileikkaus se, joka ulkonaisesti lihassa tapahtuu;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'vaan se on juutalainen, joka sisällisesti on juutalainen, ja oikea ympärileikkaus on sydämen ympärileikkaus Hengessä, ei kirjaimessa; ja hän saa kiitoksensa, ei ihmisiltä, vaan Jumalalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Mitä etuuksia on siis juutalaisilla, tai mitä hyötyä ympärileikkauksesta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Paljonkin, kaikin tavoin; ennen kaikkea se, että heille on uskottu, mitä Jumala on puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Mutta kuinka? Jos jotkut ovat olleet epäuskoisia, ei kaiketi heidän epäuskonsa ole Jumalan uskollisuutta tyhjäksi tekevä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Pois se! Olkoon Jumala totinen, mutta jokainen ihminen valhettelija, niinkuin kirjoitettu on: \"Että sinut havaittaisiin vanhurskaaksi sanoissasi ja että voittaisit, kun sinun kanssasi oikeutta käydään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Mutta jos meidän vääryytemme tuo ilmi Jumalan vanhurskauden, mitä me siihen sanomme? Ei kaiketi Jumala ole väärä, kun hän rankaisee vihassansa? Minä puhun ihmisten tavalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Pois se! Sillä kuinka Jumala silloin voisi tuomita maailman?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Sillä jos Jumalan totuus tulee minun valheeni kautta selvemmin julki hänen kirkkaudekseen, miksi sitten minutkin vielä syntisenä tuomitaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Ja miksi emme tekisi, niinkuin herjaten syyttävät meidän tekevän ja niinkuin muutamat väittävät meidän sanovan: \"Tehkäämme pahaa, että siitä hyvää tulisi\"? Niiden tuomio on oikea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Miten siis on? Olemmeko me parempia? Emme suinkaan. Mehän olemme edellä osoittaneet, että kaikki, niin hyvin juutalaiset kuin kreikkalaiset, ovat synnin alla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'niinkuin kirjoitettu on: \"Ei ole ketään vanhurskasta, ei ainoatakaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'ei ole ketään ymmärtäväistä, ei ketään, joka etsii Jumalaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'kaikki ovat poikenneet pois, kaikki tyynni kelvottomiksi käyneet; ei ole ketään, joka tekee sitä, mikä hyvä on, ei yhden yhtäkään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Heidän kurkkunsa on avoin hauta, kielellänsä he pettävät, kyykäärmeen myrkkyä on heidän huultensa alla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'heidän suunsa on täynnä kirousta ja katkeruutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Heidän jalkansa ovat nopeat vuodattamaan verta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'hävitys ja kurjuus on heidän teillänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'ja rauhan tietä he eivät tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Ei ole Jumalan pelko heidän silmäinsä edessä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Mutta me tiedämme, että kaiken, minkä laki sanoo, sen se puhuu lain alaisille, että jokainen suu tukittaisiin ja koko maailma tulisi syylliseksi Jumalan edessä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'sentähden, ettei mikään liha tule hänen edessään vanhurskaaksi lain teoista; sillä lain kautta tulee synnin tunto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Mutta nyt Jumalan vanhurskaus, josta laki ja profeetat todistavat, on ilmoitettu ilman lakia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'se Jumalan vanhurskaus, joka uskon kautta Jeesukseen Kristukseen tulee kaikkiin ja kaikille, jotka uskovat; sillä ei ole yhtään erotusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Sillä kaikki ovat syntiä tehneet ja ovat Jumalan kirkkautta vailla');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'ja saavat lahjaksi vanhurskauden hänen armostaan sen lunastuksen kautta, joka on Kristuksessa Jeesuksessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 25, 'jonka Jumala on asettanut armoistuimeksi uskon kautta hänen vereensä, osoittaaksensa vanhurskauttaan, koska hän oli jättänyt rankaisematta ennen tehdyt synnit');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 26, 'jumalallisessa kärsivällisyydessään, osoittaaksensa vanhurskauttaan nykyajassa, sitä, että hän itse on vanhurskas ja vanhurskauttaa sen, jolla on usko Jeesukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 27, 'Missä siis on kerskaaminen? Se on suljettu pois. Minkä lain kautta? Tekojenko lain? Ei, vaan uskon lain kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 28, 'Niin päätämme siis, että ihminen vanhurskautetaan uskon kautta, ilman lain tekoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 29, 'Vai onko Jumala yksistään juutalaisten Jumala? Eikö pakanainkin? On pakanainkin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 30, 'koskapa Jumala on yksi, joka vanhurskauttaa ympärileikatut uskosta ja ympärileikkaamattomat uskon kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 31, 'Teemmekö siis lain mitättömäksi uskon kautta? Pois se! Vaan me vahvistamme lain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Mitä me siis sanomme esi-isämme Aabrahamin saavuttaneen lihan mukaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Sillä jos Aabraham on teoista vanhurskautettu, on hänellä kerskaamista, mutta ei Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Sillä mitä Raamattu sanoo? \"Aabraham uskoi Jumalaa, ja se luettiin hänelle vanhurskaudeksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Mutta töitä tekevälle ei lueta palkkaa armosta, vaan ansiosta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'mutta joka ei töitä tee, vaan uskoo häneen, joka vanhurskauttaa jumalattoman, sille luetaan hänen uskonsa vanhurskaudeksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'niinkuin myös Daavid ylistää autuaaksi sitä ihmistä, jolle Jumala lukee vanhurskauden ilman tekoja:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, '\"Autuaat ne, joiden rikokset ovat anteeksi annetut ja joiden synnit ovat peitetyt!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Autuas se mies, jolle Herra ei lue syntiä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Koskeeko sitten tämä autuaaksi ylistäminen ainoastaan ympärileikattuja, vai eikö ympärileikkaamattomiakin? Sanommehan: \"Aabrahamille luettiin usko vanhurskaudeksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Kuinka se sitten siksi luettiin? Hänen ollessaanko ympärileikattuna vai ympärileikkaamatonna? Ei ympärileikattuna, vaan ympärileikkaamatonna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Ja hän sai ympärileikkauksen merkin sen uskonvanhurskauden sinetiksi, joka hänellä oli ympärileikkaamatonna, että hänestä tulisi kaikkien isä, jotka ympärileikkaamattomina uskovat, niin että vanhurskaus heillekin luettaisiin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'ja että hänestä tulisi myöskin ympärileikattujen isä, niiden, jotka eivät ainoastaan ole ympärileikattuja, vaan myös vaeltavat sen uskon jälkiä, mikä meidän isällämme Aabrahamilla oli jo ympärileikkaamatonna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Sillä se lupaus, että Aabraham oli perivä maailman, ei tullut hänelle eikä hänen siemenelleen lain kautta, vaan uskonvanhurskauden kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Sillä jos ne, jotka pitäytyvät lakiin, ovat perillisiä, niin usko on tyhjäksi tehty ja lupaus käynyt mitättömäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Sillä laki saa aikaan vihaa; mutta missä lakia ei ole, siellä ei ole rikkomustakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Sentähden se on uskosta, että se olisi armosta; että lupaus pysyisi lujana kaikelle siemenelle, ei ainoastaan sille, joka pitäytyy lakiin, vaan myös sille, jolla on Aabrahamin usko, hänen, joka on meidän kaikkien isä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, '-niinkuin kirjoitettu on: \"Monen kansan isäksi minä olen sinut asettanut\" -sen Jumalan edessä, johon hän uskoi ja joka kuolleet eläviksi tekee ja kutsuu olemattomat, ikäänkuin ne olisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Ja Aabraham toivoi, vaikka ei toivoa ollut, ja uskoi tulevansa monen kansan isäksi, tämän sanan mukaan: \"Niin on sinun jälkeläistesi luku oleva\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'eikä hän heikontunut uskossansa, vaikka näki, että hänen ruumiinsa oli kuolettunut-sillä hän oli jo noin satavuotias-ja että Saaran kohtu oli kuolettunut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'mutta Jumalan lupausta hän ei epäuskossa epäillyt, vaan vahvistui uskossa, antaen kunnian Jumalalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'ja oli täysin varma siitä, että minkä Jumala on luvannut, sen hän voi myös täyttää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 22, 'Sentähden se luettiinkin hänelle vanhurskaudeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 23, 'Mutta ei ainoastaan hänen tähtensä ole kirjoitettu, että se hänelle luettiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 24, 'vaan myös meidän tähtemme, joille se on luettava, kun uskomme häneen, joka kuolleista herätti Jeesuksen, meidän Herramme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 25, 'joka on alttiiksi annettu meidän rikostemme tähden ja kuolleista herätetty meidän vanhurskauttamisemme tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Koska me siis olemme uskosta vanhurskaiksi tulleet, niin meillä on rauha Jumalan kanssa meidän Herramme Jeesuksen Kristuksen kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'jonka kautta myös olemme uskossa saaneet pääsyn tähän armoon, jossa me nyt olemme, ja meidän kerskauksemme on Jumalan kirkkauden toivo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Eikä ainoastaan se, vaan meidän kerskauksenamme ovat myös ahdistukset, sillä me tiedämme, että ahdistus saa aikaan kärsivällisyyttä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'mutta kärsivällisyys koettelemuksen kestämistä, ja koettelemuksen kestäminen toivoa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'mutta toivo ei saata häpeään; sillä Jumalan rakkaus on vuodatettu meidän sydämiimme Pyhän Hengen kautta, joka on meille annettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Sillä meidän vielä ollessamme heikot kuoli Kristus oikeaan aikaan jumalattomien edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Tuskinpa kukaan käy kuolemaan jonkun vanhurskaan edestä; hyvän edestä joku mahdollisesti uskaltaa kuolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Mutta Jumala osoittaa rakkautensa meitä kohtaan siinä, että Kristus, kun me vielä olimme syntisiä, kuoli meidän edestämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Paljoa ennemmin me siis nyt, kun olemme vanhurskautetut hänen veressään, pelastumme hänen kauttansa vihasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Sillä jos me silloin, kun vielä olimme Jumalan vihollisia, tulimme sovitetuiksi hänen kanssaan hänen Poikansa kuoleman kautta, paljoa ennemmin me pelastumme hänen elämänsä kautta nyt, kun olemme sovitetut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'emmekä ainoastaan sovitetut, vaan vieläpä on Jumala meidän kerskauksemme meidän Herramme Jeesuksen Kristuksen kautta, jonka kautta me nyt olemme sovituksen saaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Sentähden, niinkuin yhden ihmisen kautta synti tuli maailmaan, ja synnin kautta kuolema, niin kuolema on tullut kaikkien ihmisten osaksi, koska kaikki ovat syntiä tehneet-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'sillä jo ennen lakiakin oli synti maailmassa, mutta syntiä ei lueta, missä lakia ei ole;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'kuitenkin kuolema hallitsi Aadamista Moosekseen asti niitäkin, jotka eivät olleet syntiä tehneet samankaltaisella rikkomuksella kuin Aadam, joka on sen esikuva, joka oli tuleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Mutta armolahjan laita ei ole sama kuin lankeemuksen; sillä joskin yhden lankeemuksesta monet ovat kuolleet, niin paljoa enemmän on Jumalan armo ja lahja yhden ihmisen, Jeesuksen Kristuksen, armon kautta ylenpalttisesti tullut monien osaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Eikä lahjan laita ole, niinkuin on sen, mikä tuli yhden synnintekijän kautta; sillä tuomio tuli yhdestä ihmisestä kadotukseksi, mutta armolahja tulee monesta rikkomuksesta vanhurskauttamiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Ja jos yhden ihmisen lankeemuksen tähden kuolema on hallinnut yhden kautta, niin paljoa enemmän ne, jotka saavat armon ja vanhurskauden lahjan runsauden, tulevat elämässä hallitsemaan yhden, Jeesuksen Kristuksen, kautta. -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Niinpä siis, samoin kuin yhden ihmisen lankeemus on koitunut kaikille ihmisille kadotukseksi, niin myös yhden ihmisen vanhurskauden teko koituu kaikille ihmisille elämän vanhurskauttamiseksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'sillä niinkuin yhden ihmisen tottelemattomuuden kautta monet ovat joutuneet syntisiksi, niin myös yhden kuuliaisuuden kautta monet tulevat vanhurskaiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Mutta laki tuli väliin, että rikkomus suureksi tulisi; mutta missä synti on suureksi tullut, siinä armo on tullut ylenpalttiseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'että niinkuin synti on hallinnut kuolemassa, samoin armokin hallitsisi vanhurskauden kautta iankaikkiseksi elämäksi Jeesuksen Kristuksen, meidän Herramme, kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 1, 'Mitä siis sanomme? Onko meidän pysyttävä synnissä, että armo suureksi tulisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 2, 'Pois se! Me, jotka olemme kuolleet pois synnistä, kuinka me vielä eläisimme siinä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 3, 'Vai ettekö tiedä, että me kaikki, jotka olemme kastetut Kristukseen Jeesukseen, olemme hänen kuolemaansa kastetut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 4, 'Niin olemme siis yhdessä hänen kanssaan haudatut kasteen kautta kuolemaan, että niinkuin Kristus herätettiin kuolleista Isän kirkkauden kautta, samoin pitää meidänkin uudessa elämässä vaeltaman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 5, 'Sillä jos me olemme hänen kanssaan yhteenkasvaneita yhtäläisessä kuolemassa, niin olemme samoin myös yhtäläisessä ylösnousemuksessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 6, 'kun tiedämme sen, että meidän vanha ihmisemme on hänen kanssaan ristiinnaulittu, että synnin ruumis kukistettaisiin, niin ettemme enää syntiä palvelisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 7, 'sillä joka on kuollut, se on vanhurskautunut pois synnistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 8, 'Mutta jos olemme kuolleet Kristuksen kanssa, niin me uskomme saavamme myös elää hänen kanssaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 9, 'tietäen, että Kristus, sittenkuin hänet kuolleista herätettiin, ei enää kuole: kuolema ei enää häntä vallitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 10, 'Sillä minkä hän kuoli, sen hän kerta kaikkiaan kuoli pois synnistä; mutta minkä hän elää, sen hän elää Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 11, 'Niin tekin pitäkää itsenne synnille kuolleina, mutta Jumalalle elävinä Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 12, 'Älköön siis synti hallitko teidän kuolevaisessa ruumiissanne, niin että olette kuuliaiset sen himoille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 13, 'Älkääkä antako jäseniänne vääryyden aseiksi synnille, vaan antakaa itsenne, kuolleista eläviksi tulleina, Jumalalle, ja jäsenenne vanhurskauden aseiksi Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 14, 'Sillä synnin ei pidä teitä vallitseman, koska ette ole lain alla, vaan armon alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 15, 'Kuinka siis on? Saammeko tehdä syntiä, koska emme ole lain alla, vaan armon alla? Pois se!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 16, 'Ettekö tiedä, että kenen palvelijoiksi, ketä tottelemaan, te antaudutte, sen palvelijoita te olette, jota te tottelette, joko synnin palvelijoita, kuolemaksi, tahi kuuliaisuuden, vanhurskaudeksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 17, 'Mutta kiitos Jumalalle, että te, jotka ennen olitte synnin palvelijoita, nyt olette tulleet sydämestänne kuuliaisiksi sille opin muodolle, jonka johtoon te olette annetut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 18, 'ja että te synnistä vapautettuina olette tulleet vanhurskauden palvelijoiksi!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 19, 'Minä puhun ihmisten tavalla teidän lihanne heikkouden tähden. Sillä niinkuin te ennen annoitte jäsenenne saastaisuuden ja laittomuuden palvelijoiksi laittomuuteen, niin antakaa nyt jäsenenne vanhurskauden palvelijoiksi pyhitykseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 20, 'Sillä kun olitte synnin palvelijoita, niin te olitte vapaat vanhurskaudesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 21, 'Minkä hedelmän te siitä silloin saitte? Sen, jota te nyt häpeätte. Sillä sen loppu on kuolema.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 22, 'Mutta nyt, kun olette synnistä vapautetut ja Jumalan palvelijoiksi tulleet, on teidän hedelmänne pyhitys, ja sen loppu on iankaikkinen elämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 6, 23, 'Sillä synnin palkka on kuolema, mutta Jumalan armolahja on iankaikkinen elämä Kristuksessa Jeesuksessa, meidän Herrassamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 1, 'Vai ettekö tiedä, veljet-minä puhun lain tunteville-että laki vallitsee ihmistä, niin kauan kuin hän elää?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 2, 'Niinpä sitoo laki naidun vaimon hänen elossa olevaan mieheensä; mutta jos mies kuolee, on vaimo irti tästä miehen laista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 3, 'Sentähden hän saa avionrikkojan nimen, jos miehensä eläessä antautuu toiselle miehelle; mutta jos mies kuolee, on hän vapaa siitä laista, niin ettei hän ole avionrikkoja, jos menee toiselle miehelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 4, 'Niin, veljeni, teidätkin on kuoletettu laista Kristuksen ruumiin kautta, tullaksenne toisen omiksi, hänen, joka on kuolleista herätetty, että me kantaisimme hedelmää Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 5, 'Sillä kun olimme lihan vallassa, niin synnin himot, jotka laki herättää, vaikuttivat meidän jäsenissämme, niin että me kannoimme hedelmää kuolemalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 6, 'mutta nyt me olemme irti laista ja kuolleet pois siitä, mikä meidät piti vankeina, niin että me palvelemme Jumalaa Hengen uudessa tilassa emmekä kirjaimen vanhassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 7, 'Mitä siis sanomme? Onko laki syntiä? Pois se! Mutta syntiä en olisi tullut tuntemaan muuten kuin lain kautta; sillä en minä olisi tiennyt himosta, ellei laki olisi sanonut: \"Älä himoitse\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 8, 'Mutta kun synti otti käskysanasta aiheen, herätti se minussa kaikkinaisia himoja; sillä ilman lakia on synti kuollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 9, 'Minä elin ennen ilman lakia; mutta kun käskysana tuli, niin synti virkosi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 10, 'ja minä kuolin. Niin kävi ilmi, että käskysana, joka oli oleva minulle elämäksi, olikin minulle kuolemaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 11, 'Sillä kun synti otti käskysanasta aiheen, petti se minut ja kuoletti minut käskysanan kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 12, 'Niin, laki on kuitenkin pyhä ja käskysana pyhä, vanhurskas ja hyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 13, 'Onko siis hyvä tullut minulle kuolemaksi? Pois se! Vaan synti, että se synniksi nähtäisiin, on hyvän kautta tuottanut minulle kuoleman, että synti tulisi ylenmäärin synnilliseksi käskysanan kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 14, 'Sillä me tiedämme, että laki on hengellinen, mutta minä olen lihallinen, myyty synnin alaisuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 15, 'Sillä minä en tunne omakseni sitä, mitä teen; sillä minä en toteuta sitä, mitä tahdon, vaan mitä minä vihaan, sitä minä teen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 16, 'Mutta jos minä teen sitä, mitä en tahdo, niin minä myönnän, että laki on hyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 17, 'Niin en nyt enää tee sitä minä, vaan synti, joka minussa asuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 18, 'Sillä minä tiedän, ettei minussa, se on minun lihassani, asu mitään hyvää. Tahto minulla kyllä on, mutta voimaa hyvän toteuttamiseen ei;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 19, 'sillä sitä hyvää, mitä minä tahdon, minä en tee, vaan sitä pahaa, mitä en tahdo, minä teen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 20, 'Jos minä siis teen sitä, mitä en tahdo, niin sen tekijä en enää ole minä, vaan synti, joka minussa asuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 21, 'Niin huomaan siis itsessäni, minä, joka tahdon hyvää tehdä, sen lain, että paha riippuu minussa kiinni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 22, 'sillä sisällisen ihmiseni puolesta minä ilolla yhdyn Jumalan lakiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 23, 'mutta jäsenissäni minä näen toisen lain, joka sotii minun mieleni lakia vastaan ja pitää minut vangittuna synnin laissa, joka minun jäsenissäni on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 24, 'Minä viheliäinen ihminen, kuka pelastaa minut tästä kuoleman ruumiista?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 7, 25, 'Kiitos Jumalalle Jeesuksen Kristuksen, meidän Herramme, kautta! Niin minä siis tämmöisenäni palvelen mielellä Jumalan lakia, mutta lihalla synnin lakia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 1, 'Niin ei nyt siis ole mitään kadotustuomiota niille, jotka Kristuksessa Jeesuksessa ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 2, 'Sillä elämän hengen laki Kristuksessa Jeesuksessa on vapauttanut sinut synnin ja kuoleman laista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 3, 'Sillä mikä laille oli mahdotonta, koska se oli lihan kautta heikoksi tullut, sen Jumala teki, lähettämällä oman Poikansa syntisen lihan kaltaisuudessa ja synnin tähden ja tuomitsemalla synnin lihassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 4, 'että lain vanhurskaus täytettäisiin meissä, jotka emme vaella lihan mukaan, vaan Hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 5, 'Sillä niillä, jotka elävät lihan mukaan, on lihan mieli, mutta niillä, jotka elävät Hengen mukaan, on Hengen mieli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 6, 'Sillä lihan mieli on kuolema, mutta hengen mieli on elämä ja rauha;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 7, 'sentähden että lihan mieli on vihollisuus Jumalaa vastaan, sillä se ei alistu Jumalan lain alle, eikä se voikaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 8, 'Jotka lihan vallassa ovat, ne eivät voi olla Jumalalle otolliset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 9, 'Mutta te ette ole lihan vallassa, vaan Hengen, jos kerran Jumalan Henki teissä asuu. Mutta jolla ei ole Kristuksen Henkeä, se ei ole hänen omansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 10, 'Mutta jos Kristus on teissä, niin ruumis tosin on kuollut synnin tähden, mutta henki on elämä vanhurskauden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 11, 'Jos nyt hänen Henkensä, hänen, joka herätti Jeesuksen kuolleista, asuu teissä, niin hän, joka herätti kuolleista Kristuksen Jeesuksen, on eläväksitekevä myös teidän kuolevaiset ruumiinne Henkensä kautta, joka teissä asuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 12, 'Niin me siis, veljet, olemme velassa, mutta emme lihalle, lihan mukaan elääksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 13, 'Sillä jos te lihan mukaan elätte, pitää teidän kuoleman; mutta jos te Hengellä kuoletatte ruumiin teot, niin saatte elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 14, 'Sillä kaikki, joita Jumalan Henki kuljettaa, ovat Jumalan lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 15, 'Sillä te ette ole saaneet orjuuden henkeä ollaksenne jälleen pelossa, vaan te olette saaneet lapseuden hengen, jossa me huudamme: \"Abba! Isä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 16, 'Henki itse todistaa meidän henkemme kanssa, että me olemme Jumalan lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 17, 'Mutta jos olemme lapsia, niin olemme myöskin perillisiä, Jumalan perillisiä ja Kristuksen kanssaperillisiä, jos kerran yhdessä hänen kanssaan kärsimme, että me yhdessä myös kirkastuisimme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 18, 'Sillä minä päätän, että tämän nykyisen ajan kärsimykset eivät ole verrattavat siihen kirkkauteen, joka on ilmestyvä meihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 19, 'Sillä luomakunnan harras ikävöitseminen odottaa Jumalan lasten ilmestymistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 20, 'Sillä luomakunta on alistettu katoavaisuuden alle-ei omasta tahdostaan, vaan alistajan-kuitenkin toivon varaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 21, 'koska itse luomakuntakin on tuleva vapautetuksi turmeluksen orjuudesta Jumalan lasten kirkkauden vapauteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 22, 'Sillä me tiedämme, että koko luomakunta yhdessä huokaa ja on synnytystuskissa hamaan tähän asti;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 23, 'eikä ainoastaan se, vaan myös me, joilla on Hengen esikoislahja, mekin huokaamme sisimmässämme, odottaen lapseksi-ottamista, meidän ruumiimme lunastusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 24, 'Sillä toivossa me olemme pelastetut, mutta toivo, jonka näkee täyttyneen, ei ole mikään toivo; kuinka kukaan sitä toivoo, minkä näkee?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 25, 'Mutta jos toivomme, mitä emme näe, niin me odotamme sitä kärsivällisyydellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 26, 'Samoin myös Henki auttaa meidän heikkouttamme. Sillä me emme tiedä, mitä meidän pitää rukoileman, niinkuin rukoilla tulisi, mutta Henki itse rukoilee meidän puolestamme sanomattomilla huokauksilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 27, 'Mutta sydänten tutkija tietää, mikä Hengen mieli on, sillä Henki rukoilee Jumalan tahdon mukaan pyhien edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 28, 'Mutta me tiedämme, että kaikki yhdessä vaikuttaa niiden parhaaksi, jotka Jumalaa rakastavat, niiden, jotka hänen aivoituksensa mukaan ovat kutsutut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 29, 'Sillä ne, jotka hän on edeltätuntenut, hän on myös edeltämäärännyt Poikansa kuvan kaltaisiksi, että hän olisi esikoinen monien veljien joukossa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 30, 'mutta jotka hän on edeltämäärännyt, ne hän on myös kutsunut; ja jotka hän on kutsunut, ne hän on myös vanhurskauttanut; mutta jotka hän on vanhurskauttanut, ne hän on myös kirkastanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 31, 'Mitä me siis tähän sanomme? Jos Jumala on meidän puolellamme, kuka voi olla meitä vastaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 32, 'Hän, joka ei säästänyt omaa Poikaansakaan, vaan antoi hänet alttiiksi kaikkien meidän edestämme, kuinka hän ei lahjoittaisi meille kaikkea muutakin hänen kanssansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 33, 'Kuka voi syyttää Jumalan valittuja? Jumala on se, joka vanhurskauttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 34, 'Kuka voi tuomita kadotukseen? Kristus Jeesus on se, joka on kuollut, onpa vielä herätettykin, ja hän on Jumalan oikealla puolella, ja hän myös rukoilee meidän edestämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 35, 'Kuka voi meidät erottaa Kristuksen rakkaudesta? Tuskako, vai ahdistus, vai vaino, vai nälkä, vai alastomuus, vai vaara, vai miekka?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 36, 'Niinkuin kirjoitettu on: \"Sinun tähtesi meitä surmataan kaiken päivää; meitä pidetään teuraslampaina\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 37, 'Mutta näissä kaikissa me saamme jalon voiton hänen kauttansa, joka meitä on rakastanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 38, 'Sillä minä olen varma siitä, ettei kuolema eikä elämä, ei enkelit eikä henkivallat, ei nykyiset eikä tulevaiset, ei voimat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 8, 39, 'ei korkeus eikä syvyys, eikä mikään muu luotu voi meitä erottaa Jumalan rakkaudesta, joka on Kristuksessa Jeesuksessa, meidän Herrassamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 1, 'Minä sanon totuuden Kristuksessa, en valhettele-sen todistaa minulle omatuntoni Pyhässä Hengessä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 2, 'että minulla on suuri murhe ja ainainen kipu sydämessäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 3, 'Sillä minä soisin itse olevani kirottu pois Kristuksesta veljieni hyväksi, jotka ovat minun sukulaisiani lihan puolesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 4, 'ovat israelilaisia: heidän on lapseus ja kirkkaus ja liitot ja lain antaminen ja jumalanpalvelus ja lupaukset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 5, 'heidän ovat isät, ja heistä on Kristus lihan puolesta, hän, joka on yli kaiken, Jumala, ylistetty iankaikkisesti, amen!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 6, 'Mutta ei niin, että Jumalan sana olisi harhaan mennyt. Sillä eivät kaikki ne, jotka ovat Israelista, ole silti Israel,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 7, 'eivät kaikki ole lapsia sentähden, että ovat Aabrahamin siementä, vaan: \"Iisakista sinä saat nimellesi jälkeläiset\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 8, 'se on: eivät ne, jotka lihan puolesta ovat lapsia, ole Jumalan lapsia, vaan lupauksen lapset, ne luetaan siemeneksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 9, 'Sillä lupauksen sana oli tämä: \"Minä palaan tulevana vuonna tähän aikaan, ja silloin Saaralla on oleva poika\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 10, 'Eikä ainoastaan hänelle näin käynyt, vaan samoin kävi Rebekallekin, joka oli tullut raskaaksi yhdestä, meidän isästämme Iisakista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 11, 'ja ennenkuin kaksoset olivat syntyneetkään ja ennenkuin olivat tehneet mitään, hyvää tai pahaa, niin-että Jumalan valinnan mukainen aivoitus pysyisi, ei tekojen tähden, vaan kutsujan tähden-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 12, 'sanottiin hänelle: \"Vanhempi on palveleva nuorempaa\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 13, 'niinkuin kirjoitettu on: \"Jaakobia minä rakastin, mutta Eesauta minä vihasin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 14, 'Mitä siis sanomme? Ei kaiketi Jumalassa ole vääryyttä? Pois se!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 15, 'Sillä Moosekselle hän sanoo: \"Minä olen armollinen, kenelle olen armollinen, ja armahdan, ketä armahdan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 16, 'Niin se ei siis ole sen vallassa, joka tahtoo, eikä sen, joka juoksee, vaan Jumalan, joka on armollinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 17, 'Sillä Raamattu sanoo faraolle: \"Juuri sitä varten minä nostin sinut esiin, että näyttäisin sinussa voimani ja että minun nimeni julistettaisiin kaiken maan päällä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 18, 'Niin hän siis on armollinen, kenelle tahtoo, ja paaduttaa, kenen tahtoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 19, 'Sinä kaiketi sanot minulle: \"Miksi hän sitten vielä soimaa? Sillä kuka voi vastustaa hänen tahtoansa?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 20, 'Niinpä niin, oi ihminen, mutta mikä sinä olet riitelemään Jumalaa vastaan? Ei kaiketi tehty sano tekijälleen: \"Miksi minusta tällaisen teit?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 21, 'Vai eikö savenvalajalla ole valta tehdä samasta savensa seoksesta toinen astia jaloa, toinen halpaa käyttöä varten?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 22, 'Entä jos Jumala, vaikka hän tahtoo näyttää vihansa ja tehdä voimansa tiettäväksi, on suurella pitkämielisyydellä kärsinyt vihan astioita, jotka olivat valmiit häviöön,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 23, 'ja on tehnyt sen saattaakseen kirkkautensa runsauden ilmi laupeuden astioissa, jotka hän on edeltävalmistanut kirkkauteen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 24, 'Ja sellaisiksi hän myös on kutsunut meidät, ei ainoastaan juutalaisista, vaan myös pakanoista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 25, 'niinkuin hän myös Hoosean kirjassa sanoo: \"Minä olen kutsuva kansakseni sen, joka ei ollut minun kansani, ja rakkaakseni sen, joka ei ollut minun rakkaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 26, 'Ja on tapahtuva, että siinä paikassa, jossa heille on sanottu: \'Te ette ole minun kansani\', siinä heitä kutsutaan elävän Jumalan lapsiksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 27, 'Mutta Esaias huudahtaa Israelista: \"Vaikka Israelin lapset olisivat luvultaan kuin meren hiekka, niin pelastuu heistä vain jäännös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 28, 'Sillä sanansa on Herra toteuttava maan päällä lopullisesti ja rutosti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 29, 'Niinkuin Esaias myös on ennustanut: \"Ellei Herra Sebaot olisi jättänyt meille siementä, niin meidän olisi käynyt niinkuin Sodoman, ja me olisimme tulleet Gomorran kaltaisiksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 30, 'Mitä me siis sanomme? Että pakanat, jotka eivät tavoitelleet vanhurskautta, ovat saavuttaneet vanhurskauden, mutta sen vanhurskauden, joka tulee uskosta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 31, 'mutta Israel, joka tavoitteli vanhurskauden lakia, ei ole sitä lakia saavuttanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 32, 'Minkätähden? Sentähden, ettei se tapahtunut uskosta, vaan ikäänkuin teoista; sillä he loukkautuivat loukkauskiveen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 9, 33, 'niinkuin kirjoitettu on: \"Katso, minä panen Siioniin loukkauskiven ja kompastuksen kallion, ja joka häneen uskoo, se ei häpeään joudu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 1, 'Veljet, minä toivon sydämestäni ja rukoilen Jumalaa heidän edestänsä, että he pelastuisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 2, 'Sillä minä todistan heistä, että heillä on kiivaus Jumalan puolesta, mutta ei taidon mukaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 3, 'sillä kun he eivät tunne Jumalan vanhurskautta, vaan koettavat pystyttää omaa vanhurskauttaan, eivät he ole alistuneet Jumalan vanhurskauden alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 4, 'Sillä Kristus on lain loppu, vanhurskaudeksi jokaiselle, joka uskoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 5, 'Kirjoittaahan Mooses siitä vanhurskaudesta, joka laista tulee, että ihminen, joka sen täyttää, on siitä elävä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 6, 'Mutta se vanhurskaus, joka uskosta tulee, sanoo näin: \"Älä sano sydämessäsi: Kuka nousee taivaaseen?\" se on: tuomaan Kristusta alas,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 7, 'tahi: \"Kuka astuu alas syvyyteen?\" se on: nostamaan Kristusta kuolleista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 8, 'Mutta mitä se sanoo? \"Sana on sinua lähellä, sinun suussasi ja sinun sydämessäsi\"; se on se uskon sana, jota me saarnaamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 9, 'Sillä jos sinä tunnustat suullasi Jeesuksen Herraksi ja uskot sydämessäsi, että Jumala on hänet kuolleista herättänyt, niin sinä pelastut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 10, 'sillä sydämen uskolla tullaan vanhurskaaksi ja suun tunnustuksella pelastutaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 11, 'Sanoohan Raamattu: \"Ei yksikään, joka häneen uskoo, joudu häpeään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 12, 'Tässä ei ole erotusta juutalaisen eikä kreikkalaisen välillä; sillä yksi ja sama on kaikkien Herra, rikas antaja kaikille, jotka häntä avuksi huutavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 13, 'Sillä \"jokainen, joka huutaa avuksi Herran nimeä, pelastuu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 14, 'Mutta kuinka he huutavat avuksensa sitä, johon eivät usko? Ja kuinka he voivat uskoa siihen, josta eivät ole kuulleet? Ja kuinka he voivat kuulla, ellei ole julistajaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 15, 'Ja kuinka kukaan voi julistaa, ellei ketään lähetetä? Niinkuin kirjoitettu on: \"Kuinka suloiset ovat niiden jalat, jotka hyvää sanomaa julistavat!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 16, 'Mutta eivät kaikki ole olleet kuuliaisia evankeliumille. Sillä Esaias sanoo: \"Herra, kuka uskoo meidän saarnamme?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 17, 'Usko tulee siis kuulemisesta, mutta kuuleminen Kristuksen sanan kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 18, 'Mutta minä kysyn: eivätkö he ole kuulleet? Kyllä ovat: \"Heidän äänensä on kulkenut kaikkiin maihin, ja heidän sanansa maan piirin ääriin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 19, 'Minä kysyn: eikö Israelilla ole ollut siitä tietoa? Ensiksi jo Mooses sanoo: \"Minä herätän teidän kiivautenne kansan kautta, joka ei ole kansa, ymmärtämättömän kansan kautta minä teitä kiihoitan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 20, 'Ja Esaias on rohkea ja sanoo: \"Minut ovat löytäneet ne, jotka eivät minua etsineet; minä olen ilmestynyt niille, jotka eivät minua kysyneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 10, 21, 'Mutta Israelista hän sanoo: \"Koko päivän minä olen ojentanut käsiäni tottelematonta ja uppiniskaista kansaa kohden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 1, 'Minä sanon siis: ei kaiketi Jumala ole hyljännyt kansaansa? Pois se! Sillä olenhan minäkin israelilainen, Aabrahamin siementä, Benjaminin sukukuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 2, 'Ei Jumala ole hyljännyt kansaansa, jonka hän on edeltätuntenut. Vai ettekö tiedä, mitä Raamattu sanoo kertomuksessa Eliaasta, kuinka hän Jumalan edessä syyttää Israelia:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 3, '\"Herra, he ovat tappaneet sinun profeettasi ja hajottaneet sinun alttarisi, ja minä yksin olen jäänyt jäljelle, ja he väijyvät minun henkeäni\"?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 4, 'Mutta mitä sanoo hänelle Jumalan vastaus? \"Minä olen jättänyt itselleni seitsemäntuhatta miestä, jotka eivät ole notkistaneet polvea Baalille.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 5, 'Samoin on nyt tänäkin aikana olemassa jäännös armon valinnan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 6, 'Mutta jos valinta on armosta, niin se ei ole enää teoista, sillä silloin armo ei enää olisikaan armo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 7, 'Miten siis on? Mitä Israel tavoittelee, sitä se ei ole saavuttanut, mutta valitut ovat sen saavuttaneet; muut ovat paatuneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 8, 'niinkuin kirjoitettu on: \"Jumala on antanut heille uneliaisuuden hengen, silmät, etteivät he näkisi, ja korvat, etteivät he kuulisi, tähän päivään asti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 9, 'Ja Daavid sanoo: \"Tulkoon heidän pöytänsä heille paulaksi ja ansaksi ja lankeemukseksi ja kostoksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 10, 'soetkoot heidän silmänsä, etteivät he näkisi; ja paina yhäti heidän selkänsä kumaraan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 11, 'Minä siis sanon: eivät kaiketi he ole sitä varten kompastuneet, että lankeaisivat? Pois se! Vaan heidän lankeemuksensa kautta tuli pelastus pakanoille, että he itse syttyisivät kiivauteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 12, 'Mutta jos heidän lankeemuksensa on maailmalle rikkaudeksi ja heidän vajautensa pakanoille rikkaudeksi, kuinka paljoa enemmän heidän täyteytensä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 13, 'Teille, pakanoille, minä sanon: Koska olen pakanain apostoli, pidän minä virkaani kunniassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 14, 'sytyttääkseni, jos mahdollista, kiivauteen niitä, jotka ovat minun heimolaisiani, ja pelastaakseni edes muutamia heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 15, 'Sillä jos heidän hylkäämisensä on maailmalle sovitukseksi, mitä heidän armoihin-ottamisensa on muuta kuin elämä kuolleista?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 16, 'Mutta jos uutisleipä on pyhä, niin on myös koko taikina, ja jos juuri on pyhä, niin ovat myös oksat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 17, 'Mutta jos muutamat oksista ovat taitetut pois ja sinä, joka olet metsäöljypuu, olet oksastettu oikeiden oksien joukkoon ja olet päässyt niiden kanssa osalliseksi öljypuun mehevästä juuresta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 18, 'niin älä ylpeile oksien rinnalla; mutta jos ylpeilet, niin et sinä kuitenkaan kannata juurta, vaan juuri kannattaa sinua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 19, 'Sinä kaiketi sanonet: \"Ne oksat taitettiin pois, että minut oksastettaisiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 20, 'Oikein; epäuskonsa tähden ne taitettiin pois, mutta sinä pysyt uskosi kautta. Älä ole ylpeä, vaan pelkää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 21, 'Sillä jos Jumala ei ole säästänyt luonnollisia oksia, ei hän ole säästävä sinuakaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 22, 'Katso siis Jumalan hyvyyttä ja ankaruutta: Jumalan ankaruutta langenneita kohtaan, mutta hänen hyvyyttänsä sinua kohtaan, jos hänen hyvyydessänsä pysyt; muutoin sinutkin hakataan pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 23, 'Mutta nuo toisetkin, jos eivät jää epäuskoonsa, tulevat oksastettaviksi, sillä Jumala on voimallinen oksastamaan ne jälleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 24, 'Sillä jos sinä olet leikattu luonnollisesta metsäöljypuusta ja vasten luontoa oksastettu jaloon öljypuuhun, kuinka paljoa ennemmin nämä luonnolliset oksat tulevat oksastettaviksi omaan öljypuuhunsa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 25, 'Sillä minä en tahdo, veljet-ettette olisi oman viisautenne varassa-pitää teitä tietämättöminä tästä salaisuudesta, että Israelia on osaksi kohdannut paatumus-hamaan siihen asti, kunnes pakanain täysi luku on sisälle tullut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 26, 'ja niin kaikki Israel on pelastuva, niinkuin kirjoitettu on: \"Siionista on tuleva pelastaja, hän poistaa jumalattoman menon Jaakobista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 27, 'Ja tämä on oleva minun liittoni heidän kanssaan, kun minä otan pois heidän syntinsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 28, 'Evankeliumin kannalta he kyllä ovat vihollisia teidän tähtenne, mutta valinnan kannalta he ovat rakastettuja isien tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 29, 'Sillä ei Jumala armolahjojansa ja kutsumistansa kadu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 30, 'Samoin kuin te ennen olitte Jumalalle tottelemattomia, mutta nyt olette saaneet laupeuden näiden tottelemattomuuden kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 31, 'samoin nämäkin nyt ovat olleet tottelemattomia, että myös he teille tulleen armahtamisen kautta nyt saisivat laupeuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 32, 'Sillä Jumala on sulkenut kaikki tottelemattomuuteen, että hän kaikkia armahtaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 33, 'Oi sitä Jumalan rikkauden ja viisauden ja tiedon syvyyttä! Kuinka tutkimattomat ovat hänen tuomionsa ja käsittämättömät hänen tiensä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 34, 'Sillä kuka on tuntenut Herran mielen? Tai kuka on ollut hänen neuvonantajansa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 35, 'Tai kuka on ensin antanut hänelle jotakin, joka olisi tälle korvattava?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 11, 36, 'Sillä hänestä ja hänen kauttansa ja häneen on kaikki; hänelle kunnia iankaikkisesti! Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 1, 'Niin minä Jumalan armahtavan laupeuden kautta kehoitan teitä, veljet, antamaan ruumiinne eläväksi, pyhäksi, Jumalalle otolliseksi uhriksi; tämä on teidän järjellinen jumalanpalveluksenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 2, 'Älkääkä mukautuko tämän maailmanajan mukaan, vaan muuttukaa mielenne uudistuksen kautta, tutkiaksenne, mikä on Jumalan tahto, mikä hyvää ja otollista ja täydellistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 3, 'Sillä sen armon kautta, mikä minulle on annettu, minä sanon teille jokaiselle, ettei tule ajatella itsestänsä enempää, kuin ajatella sopii, vaan ajatella kohtuullisesti, sen uskonmäärän mukaan, minkä Jumala on kullekin suonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 4, 'Sillä niinkuin meillä yhdessä ruumiissa on monta jäsentä, mutta kaikilla jäsenillä ei ole sama tehtävä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 5, 'niin me, vaikka meitä on monta, olemme yksi ruumis Kristuksessa, mutta itsekukin olemme toistemme jäseniä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 6, 'ja meillä on erilaisia armolahjoja sen armon mukaan, mikä meille on annettu; jos jollakin on profetoimisen lahja, käyttäköön sitä sen mukaan, kuin hänellä uskoa on;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 7, 'Jos virka, pitäköön virastaan vaarin; jos joku opettaa, olkoon uskollinen opettamisessaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 8, 'jos kehoittaa, niin kehoittamisessaan; joka antaa, antakoon vakaasta sydämestä; joka on johtaja, johtakoon toimellisesti; joka laupeutta harjoittaa, tehköön sen iloiten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 9, 'Olkoon rakkaus vilpitön, kammokaa pahaa, riippukaa hyvässä kiinni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 10, 'Olkaa veljellisessä rakkaudessa helläsydämiset toisianne kohtaan; toinen toisenne kunnioittamisessa kilpailkaa keskenänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 11, 'Älkää harrastuksessanne olko veltot; olkaa hengessä palavat; palvelkaa Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 12, 'Olkaa toivossa iloiset, ahdistuksessa kärsivälliset, rukouksessa kestävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 13, 'Pitäkää pyhien tarpeet ominanne; harrastakaa vieraanvaraisuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 14, 'Siunatkaa vainoojianne, siunatkaa, älkääkä kirotko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 15, 'Iloitkaa iloitsevien kanssa, itkekää itkevien kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 16, 'Olkaa keskenänne yksimieliset. Älkää korkeita mielitelkö, vaan tyytykää alhaisiin oloihin. Älkää olko itsemielestänne viisaita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 17, 'Älkää kenellekään pahaa pahalla kostako. Ahkeroikaa sitä, mikä on hyvää kaikkien ihmisten edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 18, 'Jos mahdollista on ja mikäli teistä riippuu, eläkää rauhassa kaikkien ihmisten kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 19, 'Älkää itse kostako, rakkaani, vaan antakaa sijaa Jumalan vihalle, sillä kirjoitettu on: \"Minun on kosto, minä olen maksava, sanoo Herra\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 20, 'Vaan \"jos vihamiehelläsi on nälkä, ruoki häntä, jos hänellä on jano, juota häntä, sillä näin tehden sinä kokoat tulisia hiiliä hänen päänsä päälle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 12, 21, 'Älä anna pahan itseäsi voittaa, vaan voita sinä paha hyvällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 1, 'Jokainen olkoon alamainen sille esivallalle, jonka vallan alla hän on. Sillä ei ole esivaltaa muutoin kuin Jumalalta; ne, jotka ovat, ovat Jumalan asettamat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 2, 'Sentähden, joka asettuu esivaltaa vastaan, se nousee Jumalan säätämystä vastaan; mutta jotka nousevat vastaan, tuottavat itsellensä tuomion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 3, 'Sillä hallitusmiehet eivät ole niiden pelkona, jotka tekevät hyvää, vaan niiden, jotka tekevät pahaa. Jos siis tahdot olla esivaltaa pelkäämättä, niin tee sitä, mikä hyvää on, ja sinä saat siltä kiitoksen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 4, 'sillä se on Jumalan palvelija, sinulle hyväksi. Mutta jos pahaa teet, niin pelkää; sillä se ei miekkaa turhaan kanna, koska se on Jumalan palvelija, kostaja sen rankaisemiseksi, joka pahaa tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 5, 'Siksi tulee olla alamainen, ei ainoastaan rangaistuksen tähden, vaan myös omantunnon tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 6, 'Sentähdenhän te verojakin maksatte. Sillä he ovat Jumalan palvelusmiehiä, ahkeroiden virassansa juuri sitä varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 7, 'Antakaa kaikille, mitä annettava on: kenelle vero, sille vero, kenelle tulli, sille tulli, kenelle pelko, sille pelko, kenelle kunnia, sille kunnia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 8, 'Älkää olko kenellekään mitään velkaa, muuta kuin että toisianne rakastatte; sillä joka toistansa rakastaa, se on lain täyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 9, 'Sillä nämä: \"Älä tee huorin, älä tapa, älä varasta, älä himoitse\", ja mikä muu käsky tahansa, ne sisältyvät kaikki tähän sanaan: \"Rakasta lähimmäistäsi niinkuin itseäsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 10, 'Rakkaus ei tee lähimmäiselle mitään pahaa. Sentähden on rakkaus lain täyttämys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 11, 'Ja tehkää tämä, koska tunnette tämän ajan, että jo on hetki teidän unesta nousta; sillä pelastus on nyt meitä lähempänä kuin silloin, kun uskoon tulimme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 12, 'Yö on pitkälle kulunut, ja päivä on lähellä. Pankaamme sentähden pois pimeyden teot, ja pukeutukaamme valkeuden varuksiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 13, 'Vaeltakaamme säädyllisesti, niin kuin päivällä, ei mässäyksissä ja juomingeissa, ei haureudessa ja irstaudessa, ei riidassa ja kateudessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 13, 14, 'vaan pukekaa päällenne Herra Jeesus Kristus, älkääkä niin pitäkö lihastanne huolta, että himot heräävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 1, 'Heikkouskoista hoivatkaa, rupeamatta väittelemään mielipiteistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 2, 'Toinen uskoo saavansa syödä kaikkea, mutta toinen, joka on heikko, syö vihanneksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 3, 'Joka syö, älköön halveksiko sitä, joka ei syö; ja joka ei syö, älköön tuomitko sitä, joka syö, sillä Jumala on ottanut hänet hoivaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 4, 'Mikä sinä olet tuomitsemaan toisen palvelijaa? Oman isäntänsä edessä hän seisoo tai kaatuu; mutta hän on pysyvä pystyssä, sillä Herra on voimallinen hänet pystyssä pitämään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 5, 'Toinen pitää yhden päivän toista parempana, toinen pitää kaikki päivät yhtä hyvinä; kukin olkoon omassa mielessään täysin varma.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 6, 'Joka valikoi päiviä, se valikoi Herran tähden; ja joka syö, se syö Herran tähden, sillä hän kiittää Jumalaa; ja joka ei syö, se on Herran tähden syömättä ja kiittää Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 7, 'Sillä ei kukaan meistä elä itsellensä, eikä kukaan kuole itsellensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 8, 'Jos me elämme, niin elämme Herralle, ja jos kuolemme, niin kuolemme Herralle. Sentähden, elimmepä tai kuolimme, niin me olemme Herran omat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 9, 'Sillä sitä varten Kristus kuoli ja heräsi eloon, että hän olisi sekä kuolleitten että elävien Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 10, 'Mutta sinä, minkätähden sinä tuomitset veljeäsi? Taikka sinä toinen, minkätähden sinä halveksit veljeäsi? Sillä kaikki meidät asetetaan Jumalan tuomioistuimen eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 11, 'Sillä kirjoitettu on: \"Niin totta kuin minä elän, sanoo Herra, minun edessäni pitää jokaisen polven notkistuman ja jokaisen kielen ylistämän Jumalaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 12, 'Niin on siis meidän jokaisen tehtävä Jumalalle tili itsestämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 13, 'Älkäämme siis enää toisiamme tuomitko, vaan päättäkää pikemmin olla panematta veljenne eteen loukkauskiveä tai langetusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 14, 'Minä tiedän ja olen varma Herrassa Jeesuksessa, ettei mikään ole epäpyhää itsessään; vaan ainoastaan sille, joka pitää jotakin epäpyhänä, sille se on epäpyhää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 15, 'Mutta jos veljesi tulee murheelliseksi ruokasi tähden, niin sinä et enää vaella rakkauden mukaan. Älä saata ruuallasi turmioon sitä, jonka edestä Kristus on kuollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 16, 'Älkää siis antako sen hyvän, mikä teillä on, joutua herjattavaksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 17, 'sillä ei Jumalan valtakunta ole syömistä ja juomista, vaan vanhurskautta ja rauhaa ja iloa Pyhässä Hengessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 18, 'Joka tässä kohden palvelee Kristusta, se on Jumalalle otollinen ja ihmisille kelvollinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 19, 'Niin tavoitelkaamme siis sitä, mikä edistää rauhaa ja keskinäistä rakentumistamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 20, 'Älä ruuan tähden turmele Jumalan työtä. Kaikki tosin on puhdasta, mutta sille ihmiselle, joka syö tuntoansa loukaten, se on pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 21, 'Hyvä on olla lihaa syömättä ja viiniä juomatta ja karttaa sitä, mistä veljesi loukkaantuu tai joutuu lankeemukseen tai heikoksi tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 22, 'Pidä sinä itselläsi Jumalan edessä se usko, mikä sinulla on. Onnellinen on se, joka ei tuomitse itseään siitä, minkä hän oikeaksi havaitsee;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 14, 23, 'mutta joka epäröi ja kuitenkin syö, on tuomittu, koska se ei tapahdu uskosta; sillä kaikki, mikä ei ole uskosta, on syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 1, 'Mutta meidän, vahvojen, tulee kantaa heikkojen vajavaisuuksia, eikä elää itsellemme mieliksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 2, 'Olkoon kukin meistä lähimmäiselleen mieliksi hänen parhaaksensa, että hän rakentuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 3, 'Sillä ei Kristuskaan elänyt itsellensä mieliksi, vaan niinkuin kirjoitettu on: \"Niiden herjaukset, jotka sinua herjaavat, ovat sattuneet minuun\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 4, 'Sillä kaikki, mikä ennen on kirjoitettu, on kirjoitettu meille opiksi, että meillä kärsivällisyyden ja Raamatun lohdutuksen kautta olisi toivo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 5, 'Mutta kärsivällisyyden ja lohdutuksen Jumala suokoon teille, että olisitte yksimieliset keskenänne, Kristuksen Jeesuksen mielen mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 6, 'niin että te yksimielisesti ja yhdestä suusta ylistäisitte Jumalaa ja meidän Herramme Jeesuksen Kristuksen isää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 7, 'Hoivatkaa sentähden toinen toistanne, niinkuin Kristuskin on teidät hoivaansa ottanut Jumalan kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 8, 'Sillä minä sanon, että Kristus on tullut ympärileikattujen palvelijaksi Jumalan totuuden tähden, vahvistaaksensa isille annetut lupaukset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 9, 'mutta että pakanat laupeuden tähden ovat ylistäneet Jumalaa, niinkuin kirjoitettu on: \"Sentähden minä ylistän sinua pakanain seassa ja veisaan kiitosta sinun nimellesi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 10, 'Ja vielä on sanottu: \"Riemuitkaa, te pakanat, hänen kansansa kanssa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 11, 'Ja taas: \"Kiittäkää Herraa, kaikki pakanat, ja ylistäkööt häntä kaikki kansat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 12, 'Ja myös Esaias sanoo: \"On tuleva Iisain juurivesa, hän, joka nousee hallitsemaan pakanoita; häneen pakanat panevat toivonsa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 13, 'Mutta toivon Jumala täyttäköön teidät kaikella ilolla ja rauhalla uskossa, niin että teillä olisi runsas toivo Pyhän Hengen voiman kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 14, 'Veljeni, minä kyllä olen varma teistä, että te jo ilmankin olette täynnä hyvyyttä ja kaikkinaista tietoa, niin että myös kykenette neuvomaan toinen toistanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 15, 'Kuitenkin olen paikka paikoin jotenkin rohkeasti teille kirjoittanut, uudestaan muistuttaakseni teille näitä asioita, sen armon kautta, jonka Jumala on minulle antanut');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 16, 'sitä varten, että minä olisin Kristuksen Jeesuksen palvelija pakanain keskuudessa, papillisesti toimittaakseni Jumalan evankeliumin palvelusta, niin että pakanakansoista tulisi otollinen ja Pyhässä Hengessä pyhitetty uhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 17, 'Minulla on siis kerskaukseni Kristuksessa Jeesuksessa palvellessani Jumalaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 18, 'sillä minä en rohkene puhua mistään muusta kuin siitä, mitä Kristus, saattaakseen pakanat kuuliaisiksi, on minun kauttani vaikuttanut sanalla ja teolla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 19, 'tunnustekojen ja ihmeiden voimalla, Pyhän Hengen voimalla, niin että minä Jerusalemista ja sen ympäristöstä alkaen Illyrikoniin saakka olen suorittanut Kristuksen evankeliumin julistamisen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 20, 'ja sillä tavoin, että olen pitänyt kunnianani olla julistamatta evankeliumia siellä, missä Kristuksen nimi jo on mainittu, etten rakentaisi toisen laskemalle perustukselle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 21, 'vaan niinkuin kirjoitettu on: \"Ne, joille ei ole julistettu hänestä, saavat hänet nähdä, ja jotka eivät ole kuulleet, ne ymmärtävät\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 22, 'Sentähden olenkin niin usein ollut estetty tulemasta teidän tykönne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 23, 'Mutta koska minulla nyt ei enää ole tilaa näissä paikkakunnissa ja kun jo monta vuotta olen halunnut tulla teidän tykönne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 24, 'niin minä, jos milloin Hispaniaan matkustan, tulen luoksenne, sillä minä toivon sieltä kautta matkustaessani näkeväni teidät ja teidän avullanne pääseväni sinne, kunhan ensin olen vähän saanut iloita teidän seurastanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 25, 'Mutta nyt minä matkustan Jerusalemiin viemään pyhille avustusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 26, 'Sillä Makedonia ja Akaia ovat halunneet kerätä yhteisen lahjan niille Jerusalemin pyhille, jotka ovat köyhyydessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 27, 'Niin he ovat halunneet, ja he ovatkin sen heille velkaa; sillä jos pakanat ovat tulleet osallisiksi heidän hengellisistä aarteistaan, niin he puolestaan ovat velvolliset auttamaan heitä maallisilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 28, 'Kun olen tehtäväni suorittanut ja heille tämän hedelmän perille vienyt, lähden teidän kauttanne Hispaniaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 29, 'ja minä tiedän, että tullessani teidän tykönne tulen Kristuksen täydellinen siunaus mukanani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 30, 'Mutta minä kehoitan teitä, veljet, Herramme Jeesuksen Kristuksen kautta ja Hengen rakkauden kautta auttamaan minua taistelussani, rukoilemalla minun puolestani Jumalaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 31, 'että minä pelastuisin joutumasta Juudean uskottomien käsiin ja että Jerusalemia varten tuomani avustus olisi pyhille otollinen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 32, 'niin että minä, jos Jumala niin tahtoo, ilolla saapuisin teidän tykönne ja virkistyisin teidän seurassanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 15, 33, 'Rauhan Jumala olkoon kaikkien teidän kanssanne. Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 1, 'Minä suljen teidän suosioonne sisaremme Foiben, joka on Kenkrean seurakunnan palvelija,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 2, 'että otatte hänet vastaan Herrassa, niinkuin pyhien sopii, ja autatte häntä kaikessa, missä hän teitä tarvitsee; sillä hän on ollut monelle avuksi ja myöskin minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 3, 'Tervehdys Priskalle ja Akylaalle, työkumppaneilleni Kristuksessa Jeesuksessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 4, 'jotka minun henkeni puolesta ovat panneet oman kaulansa alttiiksi ja joita en ainoastaan minä kiitä, vaan myös kaikki pakanain seurakunnat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 5, 'ja seurakunnalle, joka kokoontuu heidän kodissansa. Tervehdys Epainetukselle, rakkaalleni, joka on Aasian ensi hedelmä Kristukselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 6, 'Tervehdys Marialle, joka on nähnyt paljon vaivaa teidän tähtenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 7, 'Tervehdys Andronikukselle ja Juniaalle, heimolaisilleni ja vankeustovereilleni, joilla on suuri arvo apostolien joukossa ja jotka jo ennen minua ovat olleet Kristuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 8, 'Tervehdys Ampliatukselle, rakkaalleni Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 9, 'Tervehdys Urbanukselle, meidän työtoverillemme Kristuksessa, ja Stakykselle, rakkaalleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 10, 'Tervehdys Apelleelle, koetuksenkestäneelle Kristuksessa. Tervehdys Aristobuluksen perhekuntalaisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 11, 'Tervehdys Herodionille, heimolaiselleni. Tervehdys Narkissuksen perhekuntalaisille, jotka ovat Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 12, 'Tervehdys Tryfainalle ja Tryfosalle, jotka ovat nähneet vaivaa Herrassa. Tervehdys Persikselle, rakkaalle sisarelle, joka on nähnyt paljon vaivaa Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 13, 'Tervehdys Rufukselle, valitulle Herrassa, ja hänen äidilleen, joka on kuin äiti minullekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 14, 'Tervehdys Asynkritukselle, Flegonille, Hermeelle, Patrobaalle, Hermaalle ja veljille, jotka ovat heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 15, 'Tervehdys Filologukselle ja Julialle, Nereukselle ja hänen sisarelleen ja Olympaalle ja kaikille pyhille, jotka ovat heidän kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 16, 'Tervehtikää toisianne pyhällä suunannolla. Kaikki Kristuksen seurakunnat tervehtivät teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 17, 'Mutta minä kehoitan teitä, veljet, pitämään silmällä niitä, jotka saavat aikaan erimielisyyttä ja pahennusta vastoin sitä oppia, jonka te olette saaneet; vetäytykää pois heistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 18, 'Sillä sellaiset eivät palvele meidän Herraamme Kristusta, vaan omaa vatsaansa, ja he pettävät suloisilla sanoilla ja kauniilla puheilla vilpittömien sydämet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 19, 'Onhan teidän kuuliaisuutenne tullut kaikkien tietoon; sentähden minä iloitsen teistä, mutta minä tahtoisin teidän olevan viisaita hyvään, mutta taitamattomia pahaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 20, 'Ja rauhan Jumala on pian musertava saatanan teidän jalkojenne alle. Herramme Jeesuksen armo olkoon teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 21, 'Teitä tervehtivät Timoteus, minun työtoverini, ja heimolaiseni Lukius, Jaason ja Soosipater.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 22, 'Minä Tertius, joka olen kirjoittanut tämän kirjeen, sanon teille tervehdyksen Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 23, 'Gaius, minun ja koko seurakunnan majanantaja, tervehtii teitä. Erastus, kaupungin rahainhoitaja, ja veli Kvartus tervehtivät teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 24, 'Herramme Jeesuksen Kristuksen armo olkoon teidän kanssanne. Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 25, 'Mutta hänen, joka voi teitä vahvistaa minun evankeliumini ja Jeesuksen Kristuksen saarnan mukaan, sen ilmoitetun salaisuuden mukaan, joka kautta ikuisten aikojen on ollut ilmoittamatta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 26, 'mutta joka nyt on julkisaatettu ja profeetallisten kirjoitusten kautta iankaikkisen Jumalan käskystä tiettäväksi tehty kaikille kansoille uskon kuuliaisuuden aikaansaamiseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 16, 27, 'Jumalan, ainoan viisaan, olkoon kunnia Jeesuksen Kristuksen kautta, aina ja iankaikkisesti. Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Paavali, Kristuksen Jeesuksen kutsuttu apostoli Jumalan tahdosta, ja veli Soostenes');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'Korintossa olevalle Jumalan seurakunnalle, Kristuksessa Jeesuksessa pyhitetyille, jotka ovat kutsutut ja pyhät, ynnä kaikille, jotka avuksi huutavat meidän Herramme Jeesuksen Kristuksen nimeä kaikissa paikkakunnissa, niin omissaan kuin meidänkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Minä kiitän Jumalaani aina teidän tähtenne siitä Jumalan armosta, joka on annettu teille Kristuksessa Jeesuksessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'että kaikessa olette rikastuneet hänessä, kaikessa puheessa ja kaikessa tiedossa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'sen mukaan kuin todistus Kristuksesta on teissä vahvistettu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'niin ettei teiltä mitään puutu missään armolahjassa, teidän odottaessanne meidän Herramme Jeesuksen Kristuksen ilmestystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Hän on myös vahvistava teitä loppuun asti, niin että te olette nuhteettomat meidän Herramme Jeesuksen Kristuksen päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Jumala on uskollinen, hän, jonka kautta te olette kutsutut hänen Poikansa Jeesuksen Kristuksen, meidän Herramme, yhteyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Mutta minä kehoitan teitä, veljet, meidän Herramme Jeesuksen Kristuksen nimeen, että kaikki olisitte puheessa yksimieliset ettekä suvaitsisi riitaisuuksia keskuudessanne, vaan pysyisitte sovinnossa ja teillä olisi sama mieli ja sama ajatus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Sillä Kloen perheväeltä olen saanut teistä kuulla, veljeni, että teillä on riitoja keskuudessanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Tarkoitan sitä, että yksi teistä sanoo: \"Minä olen Paavalin puolta\", toinen: \"Minä Apolloksen\", joku taas: \"Minä Keefaan\", joku vielä: \"Minä Kristuksen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Onko Kristus jaettu? Ei kaiketi Paavali ole ristiinnaulittu teidän edestänne? Vai oletteko te kastetut Paavalin nimeen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 14, 'Minä kiitän Jumalaa, etten ole kastanut teistä ketään muita kuin Krispuksen ja Gaiuksen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 15, 'niin ettei kukaan saata sanoa, että te olette minun nimeeni kastetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 16, 'Kastoinhan tosin Stefanaankin perhekunnan; sitten en tiedä, olenko ketään muuta kastanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 17, 'Sillä Kristus ei lähettänyt minua kastamaan, vaan evankeliumia julistamaan-ei puheen viisaudella, ettei Kristuksen risti menisi mitättömäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 18, 'Sillä sana rististä on hullutus niille, jotka kadotukseen joutuvat, mutta meille, jotka pelastumme, se on Jumalan voima.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 19, 'Onhan kirjoitettu: \"Minä hävitän viisasten viisauden, ja ymmärtäväisten ymmärryksen minä teen mitättömäksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 20, 'Missä ovat viisaat? Missä kirjanoppineet? Missä tämän maailman älyniekat? Eikö Jumala ole tehnyt maailman viisautta hullutukseksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 21, 'Sillä kun, Jumalan viisaudesta, maailma ei oppinut viisauden avulla tuntemaan Jumalaa, niin Jumala näki hyväksi saarnauttamansa hullutuksen kautta pelastaa ne, jotka uskovat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 22, 'koskapa juutalaiset vaativat tunnustekoja ja kreikkalaiset etsivät viisautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 23, 'me taas saarnaamme ristiinnaulittua Kristusta, joka on juutalaisille pahennus ja pakanoille hullutus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 24, 'mutta joka niille, jotka ovat kutsutut, olkootpa juutalaisia tai kreikkalaisia, on Kristus, Jumalan voima ja Jumalan viisaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 25, 'Sillä Jumalan hulluus on viisaampi kuin ihmiset, ja Jumalan heikkous on väkevämpi kuin ihmiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 26, 'Sillä katsokaa, veljet, omaa kutsumistanne: ei ole monta inhimillisesti viisasta, ei monta mahtavaa, ei monta jalosukuista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 27, 'vaan sen, mikä on hulluutta maailmalle, sen Jumala valitsi saattaaksensa viisaat häpeään, ja sen, mikä on heikkoa maailmassa, sen Jumala valitsi saattaaksensa sen, mikä väkevää on, häpeään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 28, 'ja sen, mikä maailmassa on halpasukuista ja halveksittua, sen Jumala valitsi, sen, joka ei mitään ole, tehdäksensä mitättömäksi sen, joka jotakin on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 29, 'ettei mikään liha voisi kerskata Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 30, 'Mutta hänestä on teidän olemisenne Kristuksessa Jeesuksessa, joka on tullut meille viisaudeksi Jumalalta ja vanhurskaudeksi ja pyhitykseksi ja lunastukseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 31, 'että kävisi, niinkuin kirjoitettu on: \"Joka kerskaa, sen kerskauksena olkoon Herra\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 1, 'Niinpä, kun minä tulin teidän tykönne, veljet, en tullut puheen tai viisauden loistolla teille Jumalan todistusta julistamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 2, 'Sillä minä olin päättänyt olla teidän tykönänne tuntematta mitään muuta paitsi Jeesuksen Kristuksen, ja hänet ristiinnaulittuna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 3, 'Ja ollessani teidän tykönänne minä olin heikkouden vallassa ja pelossa ja suuressa vavistuksessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 4, 'ja minun puheeni ja saarnani ei ollut kiehtovia viisauden sanoja, vaan Hengen ja voiman osoittamista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 5, 'ettei teidän uskonne perustuisi ihmisten viisauteen, vaan Jumalan voimaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 6, 'Kuitenkin me puhumme viisautta täydellisten seurassa, mutta emme tämän maailman viisautta emmekä tämän maailman valtiasten, jotka kukistuvat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 7, 'vaan me puhumme salattua Jumalan viisautta, sitä kätkettyä, jonka Jumala on edeltämäärännyt ennen maailmanaikoja meidän kirkkaudeksemme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 8, 'sitä, jota ei kukaan tämän maailman valtiaista ole tuntenut-sillä jos he olisivat sen tunteneet, eivät he olisi kirkkauden Herraa ristiinnaulinneet-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 9, 'vaan, niinkuin kirjoitettu on: \"mitä silmä ei ole nähnyt eikä korva kuullut, mikä ei ole ihmisen sydämeen noussut ja minkä Jumala on valmistanut niille, jotka häntä rakastavat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 10, 'Mutta meille Jumala on sen ilmoittanut Henkensä kautta, sillä Henki tutkii kaikki, Jumalan syvyydetkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 11, 'Sillä kuka ihminen tietää, mitä ihmisessä on, paitsi ihmisen henki, joka hänessä on? Samoin ei myös kukaan tiedä, mitä Jumalassa on, paitsi Jumalan Henki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 12, 'Mutta me emme ole saaneet maailman henkeä, vaan sen Hengen, joka on Jumalasta, että tietäisimme, mitä Jumala on meille lahjoittanut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 13, 'ja siitä me myös puhumme, emme inhimillisen viisauden opettamilla sanoilla, vaan Hengen opettamilla, selittäen hengelliset hengellisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 14, 'Mutta luonnollinen ihminen ei ota vastaan sitä, mikä Jumalan Hengen on; sillä se on hänelle hullutus, eikä hän voi sitä ymmärtää, koska se on tutkisteltava hengellisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 15, 'Hengellinen ihminen sitä vastoin tutkistelee kaiken, mutta häntä itseään ei kukaan kykene tutkistelemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 2, 16, 'Sillä: \"kuka on tullut tuntemaan Herran mielen, niin että voisi neuvoa häntä?\" Mutta meillä on Kristuksen mieli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 1, 'Niinpä, veljet, minun ei käynyt puhuminen teille niinkuin hengellisille, vaan niinkuin lihallisille, niinkuin pienille lapsille Kristuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 2, 'Maitoa minä juotin teille, en antanut ruokaa, sillä sitä ette silloin sietäneet, ettekä vielä nytkään siedä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 3, 'olettehan vielä lihallisia. Sillä kun keskuudessanne on kateutta ja riitaa, ettekö silloin ole lihallisia ja vaella ihmisten tavoin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 4, 'Kun toinen sanoo: \"Minä olen Paavalin puolta\", ja toinen: \"Minä olen Apolloksen\", ettekö silloin ole niinkuin ihmiset ainakin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 5, 'Mikä Apollos sitten on? Ja mikä Paavali on? Palvelijoita, joiden kautta te olette tulleet uskoviksi, palvelijoita sen kykynsä mukaan, minkä Herra on heille kullekin antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 6, 'Minä istutin, Apollos kasteli, mutta Jumala on antanut kasvun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 7, 'Niin ei siis istuttaja ole mitään, eikä kastelijakaan, vaan Jumala, joka kasvun antaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 8, 'Mutta istuttaja ja kastelija ovat yhtä; kuitenkin on kumpikin saava oman palkkansa oman työnsä mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 9, 'Sillä me olemme Jumalan työtovereita; te olette Jumalan viljelysmaa, olette Jumalan rakennus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 10, 'Sen Jumalan armon mukaan, joka on minulle annettu, minä olen taitavan rakentajan tavoin pannut perustuksen, ja toinen sille rakentaa, mutta katsokoon kukin, kuinka hän sille rakentaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 11, 'Sillä muuta perustusta ei kukaan voi panna, kuin mikä pantu on, ja se on Jeesus Kristus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 12, 'Mutta jos joku rakentaa tälle perustukselle, rakensipa kullasta, hopeasta, jalokivistä, puusta, heinistä tai oljista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 13, 'niin kunkin teko on tuleva näkyviin; sillä sen on saattava ilmi se päivä, joka tulessa ilmestyy, ja tuli on koetteleva, minkälainen kunkin teko on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 14, 'Jos jonkun tekemä rakennus kestää, on hän saava palkan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 15, 'mutta jos jonkun tekemä palaa, joutuu hän vahinkoon; mutta hän itse on pelastuva, kuitenkin ikäänkuin tulen läpi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 16, 'Ettekö tiedä, että te olette Jumalan temppeli ja että Jumalan Henki asuu teissä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 17, 'Jos joku turmelee Jumalan temppelin, on Jumala turmeleva hänet; sillä Jumalan temppeli on pyhä, ja sellaisia te olette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 18, 'Älköön kukaan pettäkö itseään. Jos joku teidän joukossanne luulee olevansa viisas tässä maailmassa, tulkoon hän tyhmäksi, että hänestä tulisi viisas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 19, 'Sillä tämän maailman viisaus on hullutus Jumalan silmissä. Sillä kirjoitettu on: \"Hän vangitsee viisaat heidän viekkauteensa\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 20, 'ja vielä: \"Herra tuntee viisasten ajatukset, hän tietää ne turhiksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 21, 'Älköön siis kukaan kerskatko ihmisistä; sillä kaikki on teidän,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 22, 'teidän on Paavali ja Apollos ja Keefas, teidän on maailma ja elämä ja kuolema, nykyiset ja tulevaiset, kaikki on teidän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 3, 23, 'Mutta te olette Kristuksen, ja Kristus on Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 1, 'Niin pitäköön jokainen meitä Kristuksen käskyläisinä ja Jumalan salaisuuksien huoneenhaltijoina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 2, 'Sitä tässä huoneenhaltijoilta ennen muuta vaaditaan, että heidät havaitaan uskollisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 3, 'Mutta siitä minä hyvin vähän välitän, että te minua tuomitsette tai joku inhimillinen oikeus; en minä itsekään tuomitse itseäni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 4, 'sillä ei minulla ole mitään tunnollani, mutta en minä silti ole vanhurskautettu, vaan minun tuomitsijani on Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 5, 'Älkää sentähden lausuko mitään tuomiota, ennenkuin aika on, ennenkuin Herra tulee, joka myös on saattava valoon pimeyden kätköt ja tuova ilmi sydänten aivoitukset; ja silloin kukin saa kiitoksensa Jumalalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 6, 'Tämän olen, veljet, sovittanut itseeni ja Apollokseen, teidän tähtenne, että meistä oppisitte tämän: \"Ei yli sen, mikä kirjoitettu on\", ettette pöyhkeillen asettuisi mikä minkin puolelle toista vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 7, 'Sillä kuka antaa sinulle etusijan? Ja mitä sinulla on, jota et ole lahjaksi saanut? Mutta jos olet sen saanut, niin miksi kerskaat, ikäänkuin se ei olisi saatua?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 8, 'Te olette jo ravitut, teistä on tullut jo rikkaita, ilman meitä teistä on tullut kuninkaita! Kunpa teistä olisikin tullut kuninkaita, niin että mekin pääsisimme kuninkaiksi teidän kanssanne!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 9, 'Sillä minusta näyttää, että Jumala on asettanut meidät apostolit vihoviimeisiksi, ikäänkuin kuolemaan tuomituiksi; meistä on tullut kaiken maailman katseltava, sekä enkelien että ihmisten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 10, 'me olemme houkkia Kristuksen tähden, mutta te älykkäitä Kristuksessa, me olemme heikkoja, mutta te väkeviä; te kunnioitettuja, mutta me halveksittuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 11, 'Vielä tänäkin hetkenä me kärsimme sekä nälkää että janoa, olemme alasti, meitä piestään, ja me kuljemme kodittomina,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 12, 'me näemme vaivaa tehden työtä omin käsin. Meitä herjataan, mutta me siunaamme; meitä vainotaan, mutta me kestämme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 13, 'meitä parjataan, mutta me puhumme leppeästi; meistä on tullut kuin mikäkin maailman tunkio, kaikkien hylkimiä, aina tähän päivään asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 14, 'En kirjoita tätä häväistäkseni teitä, vaan niinkuin rakkaita lapsiani neuvoen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 15, 'Sillä vaikka teillä olisi kymmenentuhatta kasvattajaa Kristuksessa, niin ei teillä kuitenkaan ole monta isää; sillä minä teidät synnytin evankeliumin kautta Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 16, 'Kehoitan siis teitä: olkaa minun seuraajiani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 17, 'Juuri sentähden minä lähetin teille Timoteuksen, joka on minun rakas ja uskollinen poikani Herrassa; hän on muistuttava teitä minun vaelluksestani Kristuksessa Jeesuksessa, sen mukaan kuin minä kaikkialla, joka seurakunnassa, opetan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 18, 'Muutamat teistä ovat paisuneet pöyhkeiksi, aivan niinkuin minä en tulisikaan teidän tykönne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 19, 'Mutta minä tulen pian teidän tykönne, jos Herra tahtoo, ja silloin minä otan selon, en noiden pöyhkeiden sanoista, vaan voimasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 20, 'Sillä Jumalan valtakunta ei ole sanoissa, vaan voimassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 4, 21, 'Kummanko tahdotte? Tulenko luoksenne vitsa kädessä vaiko rakkaudessa ja sävyisyyden hengessä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 1, 'Yleensä kuuluu, että teidän keskuudessanne harjoitetaan haureutta, jopa semmoista haureutta, jota ei ole pakanainkaan keskuudessa, että eräskin pitää isänsä vaimoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 2, 'Ja te olette paisuneet pöyhkeiksi! Eikö teidän pikemminkin olisi pitänyt tulla murheellisiksi, että se, joka on tuommoisen teon tehnyt, poistettaisiin teidän keskuudestanne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 3, 'Sillä minä, joka tosin ruumiillisesti olen poissa, mutta hengessä kuitenkin läsnä, olen jo, niinkuin läsnäollen, puolestani päättänyt, että se, joka tuommoisen teon on tehnyt, on');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 4, '-sittenkuin olemme, te ja minun henkeni ynnä meidän Herramme Jeesuksen voima, tulleet yhteen-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 5, 'Herran Jeesuksen nimessä hyljättävä saatanan haltuun lihan turmioksi, että hänen henkensä pelastuisi Herran päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 6, 'Ei ole hyvä, että kerskaatte. Ettekö tiedä, että vähäinen hapatus hapattaa koko taikinan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 7, 'Peratkaa pois vanha hapatus, että teistä tulisi uusi taikina, niinkuin te olettekin happamattomat; sillä onhan meidän pääsiäislampaamme, Kristus, teurastettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 8, 'Viettäkäämme siis juhlaa, ei vanhassa hapatuksessa eikä ilkeyden ja pahuuden hapatuksessa, vaan puhtauden ja totuuden happamattomuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 9, 'Minä kirjoitin teille kirjeessäni, ettette seurustelisi huorintekijäin kanssa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 10, 'en tarkoittanut yleensä tämän maailman huorintekijöitä tai ahneita tai anastajia tai epäjumalanpalvelijoita, sillä silloinhan teidän täytyisi lähteä pois maailmasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 11, 'Vaan minä kirjoitin teille, että jos joku, jota kutsutaan veljeksi, on huorintekijä tai ahne tai epäjumalanpalvelija tai pilkkaaja tai juomari tai anastaja, te ette seurustelisi ettekä söisikään semmoisen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 12, 'Sillä onko minun asiani tuomita niitä, jotka ovat ulkopuolella? Ettekö tekin tuomitse vain niitä, jotka ovat sisäpuolella?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 5, 13, 'Mutta ulkopuolella olevat tuomitsee Jumala. \"Poistakaa keskuudestanne se, joka on paha.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 1, 'Kuinka rohkenee kukaan teistä, jolla on riita-asia toisen kanssa, käydä oikeutta vääräin edessä? Miksei pyhien edessä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 2, 'Vai ettekö tiedä, että pyhät tulevat maailman tuomitsemaan? Ja jos te tuomitsette maailman, niin ettekö kelpaa ratkaisemaan aivan vähäpätöisiä asioita?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 3, 'Ettekö tiedä, että me tulemme tuomitsemaan enkeleitä, emmekö sitten maallisia asioita?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 4, 'Jos teillä siis on maallisia asioita ratkaistavina, nekö te asetatte tuomareiksi, jotka ovat halveksittuja seurakunnassa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 5, 'Teidän häpeäksenne minä tämän sanon. Eikö teidän joukossanne sitten ole yhtäkään viisasta, joka voisi ratkaista veljien välin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 6, 'Vaan veli käy oikeutta veljen kanssa, vieläpä uskottomain edessä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 7, 'Teille on jo yleensä vaurioksi, että käräjöitte keskenänne. Miksi ette ennemmin salli tehdä vääryyttä itsellenne? Miksi ette ennemmin anna riistää omaanne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 8, 'Sen sijaan te itse teette vääryyttä ja riistätte toisen omaa, vieläpä veljien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 9, 'Vai ettekö tiedä, etteivät väärät saa periä Jumalan valtakuntaa? Älkää eksykö. Eivät huorintekijät, ei epäjumalanpalvelijat, ei avionrikkojat, ei hekumoitsijat eikä miehimykset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 10, 'eivät varkaat, ei ahneet, ei juomarit, ei pilkkaajat eivätkä anastajat saa periä Jumalan valtakuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 11, 'Ja tuommoisia te olitte, jotkut teistä; mutta te olette vastaanottaneet peson, te olette pyhitetyt, te olette vanhurskautetut meidän Herramme Jeesuksen Kristuksen nimessä ja meidän Jumalamme Hengessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 12, 'Kaikki on minulle luvallista, mutta ei kaikki ole hyödyksi; kaikki on minulle luvallista, mutta minä en saa antaa minkään itseäni vallita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 13, 'Ruoka on vatsaa varten ja vatsa ruokaa varten; ja Jumala on tekevä lopun niin toisesta kuin toisestakin. Mutta ruumis ei ole haureutta varten, vaan Herraa varten, ja Herra ruumista varten;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 14, 'ja Jumala, joka herätti kuolleista Herran, on herättävä meidätkin voimallansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 15, 'Ettekö tiedä, että teidän ruumiinne ovat Kristuksen jäseniä? Ottaisinko siis Kristuksen jäsenet ja tekisin ne porton jäseniksi? Pois se!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 16, 'Vai ettekö tiedä, että joka yhtyy porttoon, tulee yhdeksi ruumiiksi hänen kanssaan? Onhan sanottu: \"Ne kaksi tulevat yhdeksi lihaksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 17, 'Mutta joka yhtyy Herraan, on yksi henki hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 18, 'Paetkaa haureutta. Kaikki muu synti, mitä ikinä ihminen tekee, on ruumiin ulkopuolella; mutta haureuden harjoittaja tekee syntiä omaa ruumistansa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 19, 'Vai ettekö tiedä, että teidän ruumiinne on Pyhän Hengen temppeli, joka Henki teissä on ja jonka te olette saaneet Jumalalta, ja ettette ole itsenne omat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 6, 20, 'Sillä te olette kalliisti ostetut. Kirkastakaa siis Jumala ruumiissanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 1, 'Mutta mitä siihen tulee, mistä kirjoititte, niin hyvä on miehelle olla naiseen ryhtymättä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 2, 'mutta haureuden syntien välttämiseksi olkoon kullakin miehellä oma vaimonsa, ja kullakin naisella aviomiehensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 3, 'Täyttäköön mies velvollisuutensa vaimoansa kohtaan, ja samoin vaimo miestänsä kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 4, 'Vaimon ruumis ei ole hänen omassa, vaan hänen miehensä vallassa; samoin ei miehenkään ruumis ole hänen omassa, vaan vaimon vallassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 5, 'Älkää vetäytykö pois toisistanne, paitsi ehkä keskinäisestä sopimuksesta joksikin ajaksi, niin että olisitte vapaat rukoukseen ja sitten taas tulisitte yhteen, ettei saatana teitä kiusaisi teidän hillittömyytenne tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 6, 'Mutta tämän minä sanon myönnytyksenä, en käskynä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 7, 'Soisin kaikkien ihmisten olevan niinkuin minäkin; mutta kullakin on oma lahjansa Jumalalta, yhdellä yksi, toisella toinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 8, 'Naimattomille ja leskille minä taas sanon: heille on hyvä, jos pysyvät sellaisina kuin minäkin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 9, 'mutta jos eivät voi itseään hillitä, niin menkööt naimisiin; sillä parempi on naida kuin palaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 10, 'Mutta naimisissa oleville minä julistan, en kuitenkaan minä, vaan Herra, ettei vaimo saa erota miehestään;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 11, 'mutta jos hän eroaa, niin pysyköön naimatonna tai sopikoon miehensä kanssa; eikä mies saa hyljätä vaimoansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 12, 'Mutta muille sanon minä, eikä Herra: jos jollakin veljellä on vaimo, joka ei usko, ja tämä suostuu asumaan hänen kanssaan, niin älköön mies häntä hyljätkö;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 13, 'samoin älköön vaimokaan, jos hänellä on mies, joka ei usko, ja tämä suostuu asumaan hänen kanssaan, hyljätkö miestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 14, 'Sillä mies, joka ei usko, on pyhitetty vaimonsa kautta, ja vaimo, joka ei usko, on pyhitetty miehensä, uskonveljen, kautta; muutoinhan teidän lapsenne olisivat saastaisia, mutta nyt he ovat pyhiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 15, 'Mutta jos se, joka ei usko, eroaa, niin erotkoon; veli ja sisar eivät ole semmoisissa tapauksissa orjuutetut; sillä rauhaan on Jumala teidät kutsunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 16, 'Sillä mistä tiedät, vaimo, voitko pelastaa miehesi? Tai mistä tiedät, mies, voitko pelastaa vaimosi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 17, 'Vaeltakoon vain kukin sen mukaan, kuin Herra on hänelle hänen osansa antanut, ja siinä asemassa, missä hänet Jumala on kutsunut; näin minä säädän kaikissa seurakunnissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 18, 'Jos joku on kutsuttu ympärileikattuna, älköön hän pyrkikö ympärileikkaamattomaksi; jos joku on kutsuttu ympärileikkaamatonna, älköön ympärileikkauttako itseään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 19, 'Ei ympärileikkaus ole mitään, eikä ympärileikkaamattomuus ole mitään, vaan Jumalan käskyjen pitäminen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 20, 'Pysyköön kukin siinä asemassa, missä hänet on kutsuttu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 21, 'Jos olet kutsuttu orjana, älä siitä murehdi; mutta vaikka voisitkin päästä vapaaksi, niin ole ennemmin siinä osassasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 22, 'Sillä joka orjana on kutsuttu Herrassa, on Herran vapaa; samoin vapaana kutsuttu on Kristuksen orja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 23, 'Te olette kalliisti ostetut; älkää olko ihmisten orjia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 24, 'Pysyköön kukin, veljet, Jumalan edessä siinä asemassa, missä hänet on kutsuttu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 25, 'Mutta neitsyistä minulla ei ole Herran käskyä, vaan minä sanon ajatukseni niinkuin se, joka on Herralta saanut sen laupeuden, että hän on luotettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 26, 'Olen siis sitä mieltä, että lähestyvän ahdingon tähden jokaisen on hyvä pysyä entisellään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 27, 'Jos olet sidottu vaimoon, älä pyydä eroa; jos et ole sidottu vaimoon, älä pyydä itsellesi vaimoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 28, 'Mutta jos menetkin naimisiin, et syntiä tee; ja jos neitsyt menee naimisiin, ei hänkään tee syntiä; mutta ne, jotka niin tekevät, joutuvat kärsimään ruumiillista vaivaa, ja siitä minä tahtoisin teidät säästää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 29, 'Mutta sen minä sanon, veljet: aika on lyhyt; olkoot tästedes nekin, joilla on vaimot, niinkuin ei heillä niitä olisikaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 30, 'ja ne, jotka itkevät, niinkuin eivät itkisi, ja ne, jotka iloitsevat, niinkuin eivät iloitsisi, ja ne, jotka ostavat, niinkuin eivät saisi omanansa pitää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 31, 'ja ne, jotka tätä maailmaa hyödyksensä käyttävät, niinkuin eivät sitä käyttäisi; sillä tämän maailman muoto on katoamassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 32, 'Soisin, ettei teillä olisi huolia. Naimaton mies huolehtii siitä, mikä on Herran, kuinka olisi Herralle mieliksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 33, 'mutta nainut huolehtii maailmallisista, kuinka olisi vaimolleen mieliksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 34, 'ja hänen harrastuksensa käy kahtaanne. Samoin vaimo, jolla ei enää ole miestä, ja neitsyt huolehtivat siitä, mikä on Herran, että olisivat pyhät sekä ruumiin että hengen puolesta; mutta naimisissa oleva huolehtii maailmallisista, kuinka olisi mieliksi miehellensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 35, 'Tämän minä sanon teidän omaksi hyödyksenne, en pannakseni kytkyttä kaulaanne, vaan sitä varten, että eläisitte säädyllisesti ja häiriytymättä pysyisitte Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 36, 'Mutta jos joku arvelee tekevänsä väärin tytärtänsä kohtaan, joka on täydessä naima-iässä, ja jos kerran sen pitää tapahtua, niin tehköön, niinkuin tahtoo; ei hän syntiä tee: menkööt naimisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 37, 'Joka taas pysyy sydämessään lujana eikä ole minkään pakon alainen, vaan voi noudattaa omaa tahtoansa ja on sydämessään päättänyt pitää tyttärensä naimattomana, se tekee hyvin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 38, 'Siis, joka naittaa tyttärensä, tekee hyvin, ja joka ei naita, tekee paremmin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 39, 'Vaimo on sidottu, niin kauan kuin hänen miehensä elää, mutta jos mies kuolee, on hän vapaa menemään naimisiin, kenen kanssa tahtoo, kunhan se vain tapahtuu Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 7, 40, 'Mutta hän on onnellisempi, jos pysyy entisellään; se on minun mielipiteeni, ja minä luulen, että minullakin on Jumalan Henki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 1, 'Mitä sitten epäjumalille uhrattuun lihaan tulee, niin tiedämme, että meillä kaikilla on tieto. Tieto paisuttaa, mutta rakkaus rakentaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 2, 'Jos joku luulee jotakin tietävänsä, ei hän vielä tiedä, niinkuin tietää tulee;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 3, 'mutta joka rakastaa Jumalaa, sen Jumala tuntee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 4, 'Mitä nyt epäjumalille uhratun lihan syömiseen tulee, niin tiedämme, ettei maailmassa ole yhtään epäjumalaa ja ettei ole muuta Jumalaa kuin yksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 5, 'Sillä vaikka olisikin niin sanottuja jumalia, olipa heitä sitten taivaassa tai maassa, ja niitä on paljon semmoisia jumalia ja herroja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 6, 'niin on meillä kuitenkin ainoastaan yksi Jumala, Isä, josta kaikki on ja johon me olemme luodut, ja yksi Herra, Jeesus Kristus, jonka kautta kaikki on, niin myös me hänen kauttansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 7, 'Mutta ei ole kaikilla tätä tietoa, vaan tottumuksesta epäjumaliin muutamat vielä nytkin syövät uhrilihaa ikäänkuin epäjumalille uhrattuna, ja heidän omatuntonsa, joka on heikko, tahraantuu siitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 8, 'Mutta ruoka ei lähennä meitä Jumalaan; jos olemme syömättä, emme siitä vahingoitu; jos syömme, emme siitä hyödy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 9, 'Katsokaa kuitenkin, ettei tämä vapautenne koidu heikoille loukkaukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 10, 'Sillä jos joku näkee sinun, jolla on tieto, aterioivan epäjumalan huoneessa, eikö hänen omatuntonsa, kun hän on heikko, vahvistu epäjumalille uhratun syömiseen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 11, 'Sinun tietosi kautta turmeltuu silloin tuo heikko, sinun veljesi, jonka tähden Kristus on kuollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 12, 'Mutta kun te näin teette syntiä veljiä vastaan ja haavoitatte heidän heikkoa omaatuntoaan, niin teette syntiä Kristusta vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 8, 13, 'Sentähden, jos ruoka on viettelykseksi veljelleni, en minä ikinä enää syö lihaa, etten olisi viettelykseksi veljelleni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 1, 'Enkö minä ole vapaa? Enkö minä ole apostoli? Enkö ole nähnyt Jeesusta, meidän Herraamme? Ettekö te ole minun tekoni Herrassa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 2, 'Jos en olekaan apostoli muille, olen ainakin teille; sillä te olette minun apostolinvirkani sinetti Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 3, 'Tämä on minun puolustukseni niitä vastaan, jotka asettuvat minua tutkimaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 4, 'Eikö meillä olisi oikeus saada ruokamme ja juomamme?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 5, 'Eikö meillä olisi oikeus kuljettaa muassamme vaimoa, uskonsisarta, niinkuin muutkin apostolit ja Herran veljet ja Keefas tekevät?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 6, 'Vai ainoastaanko minulla ja Barnabaalla ei ole oikeutta olla ruumiillista työtä tekemättä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 7, 'Kuka tekee koskaan sotapalvelusta omalla kustannuksellaan? Kuka istuttaa viinitarhan, eikä syö sen hedelmää? Tai kuka kaitsee karjaa, eikä nauti karjansa maitoa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 8, 'Puhunko tätä vain ihmisten tavalla? Eikö myös laki sano samaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 9, 'Onhan Mooseksen laissa kirjoitettuna: \"Älä sido puivan härän suuta\". Eihän Jumala häristä näin huolta pitäne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 10, 'Eikö hän sano sitä kaiketikin meidän tähtemme? Meidän tähtemmehän on kirjoitettu, että kyntäjän tulee kyntää toivossa ja puivan puida osansa saamisen toivossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 11, 'Jos me olemme kylväneet teille hengellistä hyvää, onko paljon, jos me niitämme teiltä aineellista?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 12, 'Jos muilla on teihin tällainen oikeus, eikö paljoa enemmän meillä? Mutta me emme ole käyttäneet tätä oikeutta, vaan kestämme kaikki, ettemme panisi mitään estettä Kristuksen evankeliumille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 13, 'Ettekö tiedä, että ne, jotka hoitavat pyhäkön toimia, saavat ravintonsa pyhäköstä, ja jotka ovat asetetut uhrialttarin palvelukseen, saavat osansa silloin kuin alttarikin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 14, 'Samoin myös Herra on säätänyt, että evankeliumin julistajain tulee saada evankeliumista elatuksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 15, 'Mutta minä en ole ainoatakaan näistä oikeuksistani hyväkseni käyttänyt. Enkä kirjoitakaan tätä siinä tarkoituksessa, että niitä minuun sovitettaisiin, sillä mieluummin minä kuolen. Ei kukaan ole minun kerskaustani tyhjäksi tekevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 16, 'Sillä siitä, että julistan evankeliumia, ei minulla ole kerskaamista; minun täytyy se tehdä. Voi minua, ellen evankeliumia julista!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 17, 'Sillä jos vapaasta tahdostani sitä teen, niin minulla on palkka; mutta jos en tee sitä vapaasta tahdostani, niin on huoneenhaltijan toimi kuitenkin minulle uskottu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 18, 'Mikä siis on minun palkkani? Se, että kun julistan evankeliumia, teen sen ilmaiseksi, niin etten käytä oikeutta, jonka evankeliumi minulle myöntää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 19, 'Sillä vaikka minä olen riippumaton kaikista, olen tehnyt itseni kaikkien palvelijaksi, voittaakseni niin monta kuin suinkin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 20, 'ja olen ollut juutalaisille ikäänkuin juutalainen, voittaakseni juutalaisia; lain alaisille ikäänkuin lain alainen, vaikka itse en ole lain alainen, voittaakseni lain alaiset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 21, 'ilman lakia oleville ikäänkuin olisin ilman lakia-vaikka en ole ilman Jumalan lakia, vaan olen Kristuksen laissa-voittaakseni ne, jotka ovat ilman lakia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 22, 'heikoille minä olen ollut heikko, voittaakseni heikot; kaikille minä olen ollut kaikkea, pelastaakseni edes muutamia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 23, 'Mutta kaiken minä teen evankeliumin tähden, että minäkin tulisin siitä osalliseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 24, 'Ettekö tiedä, että jotka kilparadalla juoksevat, ne tosin kaikki juoksevat, mutta yksi saa voittopalkinnon? Juoskaa niinkuin hän, että sen saavuttaisitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 25, 'Mutta jokainen kilpailija noudattaa itsensähillitsemistä kaikessa; he saadakseen vain katoavaisen seppeleen, mutta me katoamattoman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 26, 'Minä en siis juokse umpimähkään, en taistele niinkuin ilmaan hosuen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 9, 27, 'vaan minä kuritan ruumistani ja masennan sitä, etten minä, joka muille saarnaan, itse ehkä joutuisi hyljättäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 1, 'Sillä minä en tahdo, veljet, pitää teitä tietämättöminä siitä, että isämme olivat kaikki pilven alla ja kulkivat kaikki meren läpi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 2, 'ja saivat kaikki kasteen Moosekseen pilvessä ja meressä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 3, 'ja söivät kaikki samaa hengellistä ruokaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 4, 'ja joivat kaikki samaa hengellistä juomaa. Sillä he joivat hengellisestä kalliosta, joka heitä seurasi; ja se kallio oli Kristus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 5, 'Mutta useimpiin heistä Jumala ei mielistynyt, koskapa he hukkuivat erämaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 6, 'Tämä tapahtui varoittavaksi esimerkiksi meille, että me emme pahaa himoitsisi, niinkuin he himoitsivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 7, 'Älkää myöskään ruvetko epäjumalanpalvelijoiksi kuten muutamat heistä, niinkuin kirjoitettu on: \"Kansa istui syömään ja juomaan, ja he nousivat iloa pitämään\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 8, 'Älkäämmekä harjoittako haureutta, niinkuin muutamat heistä haureutta harjoittivat, ja heitä kaatui yhtenä päivänä kaksikymmentä kolme tuhatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 9, 'Älkäämme myöskään kiusatko Herraa, niinkuin muutamat heistä kiusasivat ja saivat käärmeiltä surmansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 10, 'Älkääkä napisko, niinkuin muutamat heistä napisivat ja saivat surmansa tuhoojalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 11, 'Tämä, mikä tapahtui heille, on esikuvallista ja on kirjoitettu varoitukseksi meille, joille maailmanaikojen loppukausi on tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 12, 'Sentähden, joka luulee seisovansa, katsokoon, ettei lankea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 13, 'Teitä ei ole kohdannut muu kuin inhimillinen kiusaus; ja Jumala on uskollinen, hän ei salli teitä kiusattavan yli voimienne, vaan salliessaan kiusauksen hän valmistaa myös pääsyn siitä, niin että voitte sen kestää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 14, 'Sentähden, rakkaani, paetkaa epäjumalanpalvelusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 15, 'Minä puhun niinkuin ymmärtäväisille; arvostelkaa itse, mitä minä sanon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 16, 'Siunauksen malja, jonka me siunaamme, eikö se ole osallisuus Kristuksen vereen? Se leipä, jonka murramme, eikö se ole osallisuus Kristuksen ruumiiseen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 17, 'Koska leipä on yksi, niin me monet olemme yksi ruumis; sillä me olemme kaikki tuosta yhdestä leivästä osalliset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 18, 'Katsokaa luonnollista Israelia; eivätkö ne, jotka syövät uhreja, ole alttarista osalliset?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 19, 'Mitä siis sanon? Ettäkö epäjumalanuhri on jotakin, tai että epäjumala on jotakin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 20, 'Ei, vaan että, mitä pakanat uhraavat, sen he uhraavat riivaajille eivätkä Jumalalle; mutta minä en tahdo, että te tulette osallisiksi riivaajista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 21, 'Ette voi juoda Herran maljasta ja riivaajien maljasta, ette voi olla osalliset Herran pöydästä ja riivaajien pöydästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 22, 'Vai tahdommeko herättää Herran kiivauden? Emme kaiketi me ole häntä väkevämmät?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 23, '\"Kaikki on luvallista\", mutta ei kaikki ole hyödyksi; \"kaikki on luvallista\", mutta ei kaikki rakenna.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 24, 'Älköön kukaan katsoko omaa parastaan, vaan toisen parasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 25, 'Syökää kaikkea, mitä lihakaupassa myydään, kyselemättä mitään omantunnon tähden,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 26, 'sillä: \"Herran on maa ja kaikki, mitä siinä on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 27, 'Jos joku, joka ei usko, kutsuu teitä ja te tahdotte mennä hänen luokseen, niin syökää kaikkea, mitä eteenne pannaan, kyselemättä mitään omantunnon tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 28, 'Mutta jos joku sanoo teille: \"Tämä on epäjumalille uhrattua\", niin jättäkää se syömättä hänen tähtensä, joka sen ilmaisi, ja omantunnon tähden;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 29, 'en tarkoita sinun omaatuntoasi, vaan tuon toisen; sillä miksi minun vapauteni joutuisi toisen omantunnon tuomittavaksi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 30, 'Jos minä sen kiittäen nautin, miksi minua herjataan siitä, mistä kiitän?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 31, 'Söittepä siis tai joitte tai teittepä mitä hyvänsä, tehkää kaikki Jumalan kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 32, 'Älkää olko pahennukseksi juutalaisille, älkää kreikkalaisille älkääkä Jumalan seurakunnalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 10, 33, 'niinkuin minäkin koetan kelvata kaikille kaikessa enkä katso omaa hyötyäni, vaan monien hyötyä, että he pelastuisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 1, 'Olkaa minun seuraajiani, niinkuin minä olen Kristuksen seuraaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 2, 'Minä kiitän teitä, että minua kaikessa muistatte ja noudatatte minun opetuksiani, niinkuin minä ne teille olen antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 3, 'Mutta minä tahdon, että te tiedätte sen, että Kristus on jokaisen miehen pää ja että mies on vaimon pää ja että Jumala on Kristuksen pää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 4, 'Jokainen mies, joka rukoilee tai profetoi pää peitettynä, häpäisee päänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 5, 'Mutta jokainen vaimo, joka rukoilee tai profetoi pää peittämätönnä, häpäisee päänsä, sillä se on aivan sama, kuin jos hänen päänsä olisi paljaaksi ajeltu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 6, 'Sillä jos vaimo ei verhoa päätään, leikkauttakoon hiuksensakin; mutta koska on häpeäksi vaimolle, että hän leikkauttaa tai ajattaa hiuksensa, niin verhotkoon itsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 7, 'Miehen ei tule peittää päätänsä, koska hän on Jumalan kuva ja kunnia; mutta vaimo on miehen kunnia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 8, 'Sillä mies ei ole alkuisin vaimosta, vaan vaimo miehestä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 9, 'eikä miestä luotu vaimoa varten, vaan vaimo miestä varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 10, 'Sentähden vaimon tulee pitää päässään vallanalaisuuden merkki enkelien tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 11, 'Herrassa ei kuitenkaan ole vaimoa ilman miestä eikä miestä ilman vaimoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 12, 'Sillä samoin kuin vaimo on alkuisin miehestä, samoin myös mies on vaimon kautta; mutta kaikki on Jumalasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 13, 'Päättäkää itse: sopiiko vaimon rukoilla Jumalaa pää peittämätönnä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 14, 'Eikö itse luontokin opeta teille, että jos miehellä on pitkät hiukset, se on hänelle häpeäksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 15, 'ja että jos vaimolla on pitkät hiukset, se on hänelle kunniaksi? Sillä ovathan hiukset annetut hänelle hunnuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 16, 'Mutta jos joku haluaa väittää vastaan, niin tietäköön, että meillä ei ole sellaista tapaa eikä Jumalan seurakunnilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 17, 'Mutta tätä käskiessäni en kiitä sitä, että kokoontumisenne ei tee teitä paremmiksi, vaan pahemmiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 18, 'Sillä ensiksikin olen kuullut, että kun kokoonnutte seurakunnankokoukseen, teillä on riitaisuuksia keskenänne, ja osittain sen uskonkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 19, 'Täytyyhän teidän keskuudessanne olla puolueitakin, että kävisi ilmi, ketkä teistä kestävät koetuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 20, 'Kun te näin kokoonnutte yhteen, niin ei se ole Herran aterian nauttimista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 21, 'sillä syömään ruvettaessa kukin rientää ottamaan eteensä omat ruokansa, ja niin toinen on nälissään ja toinen juovuksissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 22, 'Eikö teillä sitten ole muita huoneita, niissä syödäksenne ja juodaksenne? Vai halveksitteko Jumalan seurakuntaa ja tahdotteko häväistä niitä, joilla ei mitään ole? Mitä minun on teille sanominen? Onko minun teitä kiittäminen? Tässä kohden en kiitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 23, 'Sillä minä olen saanut Herralta sen, minkä myös olen teille tiedoksi antanut, että Herra Jeesus sinä yönä, jona hänet kavallettiin, otti leivän,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 24, 'kiitti, mursi ja sanoi: \"Tämä on minun ruumiini, joka teidän edestänne annetaan; tehkää tämä minun muistokseni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 25, 'Samoin hän otti myös maljan aterian jälkeen ja sanoi: \"Tämä malja on uusi liitto minun veressäni; niin usein kuin te juotte, tehkää se minun muistokseni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 26, 'Sillä niin usein kuin te syötte tätä leipää ja juotte tämän maljan, te julistatte Herran kuolemaa, siihen asti kuin hän tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 27, 'Sentähden, joka kelvottomasti syö tätä leipää tai juo Herran maljan, hän on oleva vikapää Herran ruumiiseen ja vereen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 28, 'Koetelkoon siis ihminen itseänsä, ja niin syököön tätä leipää ja juokoon tästä maljasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 29, 'sillä joka syö ja juo erottamatta Herran ruumista muusta, syö ja juo tuomioksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 30, 'Sentähden onkin teidän joukossanne paljon heikkoja ja sairaita, ja moni on nukkunut pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 31, 'Mutta jos me tutkisimme itseämme, ei meitä tuomittaisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 32, 'mutta kun meitä tuomitaan, niin se on meille Herran kuritusta, ettei meitä maailman kanssa kadotukseen tuomittaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 33, 'Sentähden, veljeni, kun kokoonnutte aterioimaan, odottakaa toisianne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 11, 34, 'Jos kenellä on nälkä, syököön kotonaan, ettette kokoontuisi tuomioksenne. Muista seikoista minä säädän, sitten kuin tulen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 1, 'Mutta mitä hengellisiin lahjoihin tulee, niin en tahdo, veljet, pitää teitä niistä tietämättöminä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 2, 'Te tiedätte, että kun olitte pakanoita, teitä vietiin mykkien epäjumalien luo, miten vain tahdottiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 3, 'Sentähden minä teen teille tiettäväksi, ettei kukaan, joka puhuu Jumalan Hengessä, sano: \"Jeesus olkoon kirottu\", ja ettei kukaan voi sanoa: \"Jeesus olkoon Herra\", paitsi Pyhässä Hengessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 4, 'Armolahjat ovat moninaiset, mutta Henki on sama;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 5, 'ja seurakuntavirat ovat moninaiset, mutta Herra on sama;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 6, 'ja voimavaikutukset ovat moninaiset, mutta Jumala, joka kaikki kaikissa vaikuttaa, on sama.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 7, 'Mutta kullekin annetaan Hengen ilmoitus yhteiseksi hyödyksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 8, 'Niinpä saa Hengen kautta toinen viisauden sanat, toinen tiedon sanat saman Hengen vaikutuksesta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 9, 'toinen saa uskon samassa Hengessä, toinen taas terveeksitekemisen lahjat siinä yhdessä Hengessä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 10, 'toinen lahjan tehdä voimallisia tekoja; toinen profetoimisen lahjan, toinen lahjan arvostella henkiä; toinen eri kielillä puhumisen lahjan, toinen taas lahjan selittää kieliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 11, 'Mutta kaiken tämän vaikuttaa yksi ja sama Henki, jakaen kullekin erikseen, niinkuin tahtoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 12, 'Sillä niinkuin ruumis on yksi ja siinä on monta jäsentä, mutta kaikki ruumiin jäsenet, vaikka niitä on monta, ovat yksi ruumis, niin on Kristuskin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 13, 'sillä me olemme kaikki yhdessä Hengessä kastetut yhdeksi ruumiiksi, olimmepa juutalaisia tai kreikkalaisia, orjia tai vapaita, ja kaikki olemme saaneet juoda samaa Henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 14, 'Sillä eihän ruumiskaan ole yksi jäsen, vaan niitä on siinä monta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 15, 'Jos jalka sanoisi: \"Koska en ole käsi, en kuulu ruumiiseen\", niin ei se silti olisi ruumiiseen kuulumaton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 16, 'Ja jos korva sanoisi: \"Koska en ole silmä, en kuulu ruumiiseen\", niin ei se silti olisi ruumiiseen kuulumaton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 17, 'Jos koko ruumis olisi silmänä, missä sitten olisi kuulo? Jos taas kokonaan kuulona, missä silloin haisti?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 18, 'Mutta nyt Jumala on asettanut jäsenet, itsekunkin niistä, ruumiiseen, niinkuin hän on tahtonut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 19, 'Vaan jos ne kaikki olisivat yhtenä jäsenenä, missä sitten ruumis olisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 20, 'Mutta nytpä onkin monta jäsentä, ja ainoastaan yksi ruumis.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 21, 'Silmä ei saata sanoa kädelle: \"En tarvitse sinua\", eikä myöskään pää jaloille: \"En tarvitse teitä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 22, 'Päinvastoin ne ruumiin jäsenet, jotka näyttävät olevan heikompia, ovat välttämättömiä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 23, 'ja ne ruumiin jäsenet, jotka meistä ovat vähemmän kunniakkaita, me verhoamme sitä kunniallisemmin, ja niitä, joita häpeämme, me sitä häveliäämmin peitämme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 24, 'mutta ne, joita emme häpeä, eivät sitä tarvitse. Mutta Jumala on liittänyt ruumiin yhteen niin, että antoi halvempiarvoiselle suuremman kunnian,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 25, 'ettei ruumiissa olisi eripuraisuutta, vaan että jäsenet pitäisivät yhtäläistä huolta toinen toisestaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 26, 'Ja jos yksi jäsen kärsii, niin kaikki jäsenet kärsivät sen kanssa; tai jos jollekulle jäsenelle annetaan kunnia, niin kaikki jäsenet iloitsevat sen kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 27, 'Mutta te olette Kristuksen ruumis ja kukin osaltanne hänen jäseniänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 28, 'Niinpä Jumala asetti seurakuntaan ensiksi muutamia apostoleiksi, toisia profeetoiksi, kolmansia opettajiksi, sitten hän antoi voimallisia tekoja, sitten armolahjoja parantaa tauteja, avustaa, hallita, puhua eri kielillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 29, 'Eivät suinkaan kaikki ole apostoleja? Eivät kaikki profeettoja? Eivät kaikki opettajia? Eiväthän kaikki tee voimallisia tekoja?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 30, 'Eihän kaikilla ole parantamisen armolahjoja? Eiväthän kaikki puhu kielillä? Eiväthän kaikki kykene niitä selittämään?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 12, 31, 'Pyrkikää osallisiksi parhaimmista armolahjoista. Ja vielä minä osoitan teille tien, verrattoman tien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 1, 'Vaikka minä puhuisin ihmisten ja enkelien kielillä, mutta minulla ei olisi rakkautta, olisin minä vain helisevä vaski tai kilisevä kulkunen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 2, 'Ja vaikka minulla olisi profetoimisen lahja ja minä tietäisin kaikki salaisuudet ja kaiken tiedon, ja vaikka minulla olisi kaikki usko, niin että voisin vuoria siirtää, mutta minulla ei olisi rakkautta, en minä mitään olisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 3, 'Ja vaikka minä jakelisin kaiken omaisuuteni köyhäin ravinnoksi, ja vaikka antaisin ruumiini poltettavaksi, mutta minulla ei olisi rakkautta, ei se minua mitään hyödyttäisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 4, 'Rakkaus on pitkämielinen, rakkaus on lempeä; rakkaus ei kadehdi, ei kerskaa, ei pöyhkeile,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 5, 'ei käyttäydy sopimattomasti, ei etsi omaansa, ei katkeroidu, ei muistele kärsimäänsä pahaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 6, 'ei iloitse vääryydestä, vaan iloitsee yhdessä totuuden kanssa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 7, 'kaikki se peittää, kaikki se uskoo, kaikki se toivoo, kaikki se kärsii.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 8, 'Rakkaus ei koskaan häviä; mutta profetoiminen, se katoaa, ja kielillä puhuminen lakkaa, ja tieto katoaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 9, 'Sillä tietomme on vajavaista, ja profetoimisemme on vajavaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 10, 'Mutta kun tulee se, mikä täydellistä on, katoaa se, mikä on vajavaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 11, 'Kun minä olin lapsi, niin minä puhuin kuin lapsi, minulla oli lapsen mieli, ja minä ajattelin kuin lapsi; kun tulin mieheksi, hylkäsin minä sen, mikä lapsen on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 12, 'Sillä nyt me näemme kuin kuvastimessa, arvoituksen tavoin, mutta silloin kasvoista kasvoihin; nyt minä tunnen vajavaisesti, mutta silloin minä olen tunteva täydellisesti, niinkuin minut itsenikin täydellisesti tunnetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 13, 13, 'Niin pysyvät nyt usko, toivo, rakkaus, nämä kolme; mutta suurin niistä on rakkaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 1, 'Tavoitelkaa rakkautta ja pyrkikää saamaan hengellisiä lahjoja, mutta varsinkin profetoimisen lahjaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 2, 'Sillä kielillä puhuva ei puhu ihmisille, vaan Jumalalle; ei häntä näet kukaan ymmärrä, sillä hän puhuu salaisuuksia hengessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 3, 'Mutta profetoiva puhuu ihmisille rakennukseksi ja kehoitukseksi ja lohdutukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 4, 'Kielillä puhuva rakentaa itseään, mutta profetoiva rakentaa seurakuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 5, 'Soisin teidän kaikkien puhuvan kielillä, mutta vielä mieluummin soisin teidän profetoivan; sillä profetoiva on suurempi kuin kielillä puhuva, ellei tämä samalla selitä, niin että seurakunta siitä rakentuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 6, 'Jos minä nyt, veljet, tulisin luoksenne kielillä puhuen, mitä minä teitä sillä hyödyttäisin, ellen puhuisi teille ilmestyksen tai tiedon tai profetian tai opetuksen sanoja?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 7, 'Niinhän on elottomain soittimienkin laita, huilujen tai kitarain: kuinka tiedetään, mitä huilulla tai kitaralla soitetaan, elleivät ne soi toisistaan erottuvin sävelin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 8, 'Niinikään, jos pasuna antaa epäselvän äänen, kuka silloin valmistautuu taisteluun?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 9, 'Samoin tekin: jos ette kielellänne saa esiin selvää puhetta, kuinka voidaan sellainen puhe ymmärtää? Tehän puhutte silloin tuuleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 10, 'Maailmassa on, kuka tietää, kuinka monta eri kieltä, mutta ei ainoatakaan, jonka äänet eivät ole ymmärrettävissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 11, 'Mutta jos en tiedä sanojen merkitystä, olen minä puhujalle muukalainen, ja puhuja on minulle muukalainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 12, 'Samoin tekin, koska tavoittelette henkilahjoja, niin pyrkikää seurakunnan rakennukseksi saamaan niitä runsaasti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 13, 'Sentähden rukoilkoon se, joka kielillä puhuu, että hän taitaisi selittää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 14, 'Sillä jos minä rukoilen kielillä puhuen, niin minun henkeni kyllä rukoilee, mutta ymmärrykseni on hedelmätön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 15, 'Kuinka siis on? Minun on rukoiltava hengelläni, mutta minun on rukoiltava myöskin ymmärrykselläni; minun on veisattava kiitosta hengelläni, mutta minun on veisattava myöskin ymmärrykselläni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 16, 'Sillä jos ylistät Jumalaa hengessä, kuinka oppimattoman paikalla istuva saattaa sanoa \"amen\" sinun kiitokseesi? Eihän hän ymmärrä, mitä sanot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 17, 'Sinä kyllä kiität hyvin, mutta toinen ei siitä rakennu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 18, 'Minä kiitän Jumalaa, että puhun kielillä enemmän kuin teistä kukaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 19, 'mutta seurakunnassa tahdon mieluummin puhua viisi sanaa ymmärrykselläni, opettaakseni muitakin, kuin kymmenentuhatta sanaa kielillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 20, 'Veljet, älkää olko lapsia ymmärrykseltänne, vaan pahuudessa olkaa lapsia; mutta ymmärrykseltä olkaa täysi-ikäisiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 21, 'Laissa on kirjoitettuna: \"Vieraskielisten kautta ja muukalaisten huulilla minä olen puhuva tälle kansalle, eivätkä he sittenkään minua kuule, sanoo Herra\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 22, 'Kielet eivät siis ole merkiksi uskoville, vaan niille, jotka eivät usko; mutta profetoiminen ei ole merkiksi uskottomille, vaan uskoville.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 23, 'Jos nyt koko seurakunta kokoontuisi yhteen ja kaikki siellä puhuisivat kielillä ja sinne tulisi opetuksesta tai uskosta osattomia, eivätkö he sanoisi teidän olevan järjiltänne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 24, 'Mutta jos kaikki profetoisivat ja joku uskosta tai opetuksesta osaton tulisi sisään, niin kaikki paljastaisivat hänet ja kaikki langettaisivat hänestä tuomion,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 25, 'hänen sydämensä salaisuudet tulisivat ilmi, ja niin hän kasvoilleen langeten rukoilisi Jumalaa ja julistaisi, että Jumala totisesti on teissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 26, 'Kuinka siis on, veljet? Kun tulette yhteen, on jokaisella jotakin annettavaa: millä on virsi, millä opetus, millä ilmestys, mikä puhuu kielillä, mikä selittää; kaikki tapahtukoon rakennukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 27, 'Jos kielillä puhutaan, niin puhukoon kullakin kertaa vain kaksi tai enintään kolme, ja yksi kerrallaan, ja yksi selittäköön;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 28, 'mutta jos ei ole selittäjää, niin olkoot vaiti seurakunnassa ja puhukoot itselleen ja Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 29, 'Profeetoista saakoon kaksi tai kolme puhua, ja muut arvostelkoot;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 30, 'mutta jos joku toinen siinä istuva saa ilmestyksen, vaietkoon ensimmäinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 31, 'Sillä te saatatte kaikki profetoida, toinen toisenne jälkeen, että kaikki saisivat opetusta ja kaikki kehoitusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 32, 'Ja profeettain henget ovat profeetoille alamaiset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 33, 'sillä ei Jumala ole epäjärjestyksen, vaan rauhan Jumala. Niinkuin kaikissa pyhien seurakunnissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 34, 'olkoot vaimot vaiti teidänkin seurakunnankokouksissanne, sillä heidän ei ole lupa puhua, vaan olkoot alamaisia, niinkuin lakikin sanoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 35, 'Mutta jos he tahtovat tietoa jostakin, niin kysykööt kotonaan omilta miehiltään, sillä häpeällistä on naisen puhua seurakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 36, 'Vai teistäkö Jumalan sana on lähtenyt? Vai ainoastaan teidänkö tykönne se on tullut?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 37, 'Jos joku luulee olevansa profeetta tai hengellinen, niin tietäköön, että mitä minä kirjoitan teille, se on Herran käsky.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 38, 'Mutta jos joku ei sitä ymmärrä, niin olkoon ymmärtämättä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 39, 'Sentähden, veljeni, harrastakaa profetoimista älkääkä estäkö kielillä puhumasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 14, 40, 'Mutta kaikki tapahtukoon säädyllisesti ja järjestyksessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 1, 'Veljet, minä johdatan teidät tuntemaan sen evankeliumin, jonka minä teille julistin, jonka te myöskin olette ottaneet vastaan ja jossa myös pysytte');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 2, 'ja jonka kautta te myös pelastutte, jos pidätte siitä kiinni semmoisena, kuin minä sen teille julistin, ellette turhaan ole uskoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 3, 'Sillä minä annoin teille ennen kaikkea tiedoksi sen, minkä itse olin saanut: että Kristus on kuollut meidän syntiemme tähden, kirjoitusten mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 4, 'ja että hänet haudattiin ja että hän nousi kuolleista kolmantena päivänä, kirjoitusten mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 5, 'ja että hän näyttäytyi Keefaalle, sitten niille kahdelletoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 6, 'Sen jälkeen hän näyttäytyi yhtä haavaa enemmälle kuin viidellesadalle veljelle, joista useimmat vielä nytkin ovat elossa, mutta muutamat ovat nukkuneet pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 7, 'Sen jälkeen hän näyttäytyi Jaakobille, sitten kaikille apostoleille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 8, 'Mutta kaikkein viimeiseksi hän näyttäytyi minullekin, joka olen ikäänkuin keskensyntynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 9, 'Sillä minä olen apostoleista halvin enkä ole sen arvoinen, että minua apostoliksi kutsutaan, koska olen vainonnut Jumalan seurakuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 10, 'Mutta Jumalan armosta minä olen se, mikä olen, eikä hänen armonsa minua kohtaan ole ollut turha, vaan enemmän kuin he kaikki minä olen työtä tehnyt, en kuitenkaan minä, vaan Jumalan armo, joka on minun kanssani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 11, 'Olinpa siis minä tai olivatpa he: näin me saarnaamme, ja näin te olette uskoon tulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 12, 'Mutta jos Kristuksesta saarnataan, että hän on noussut kuolleista, kuinka muutamat teistä saattavat sanoa, ettei kuolleitten ylösnousemusta ole?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 13, 'Vaan jos ei ole kuolleitten ylösnousemusta, ei Kristuskaan ole noussut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 14, 'Mutta jos Kristus ei ole noussut kuolleista, turha on silloin meidän saarnamme, turha myös teidän uskonne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 15, 'ja silloin meidät myös havaitaan vääriksi Jumalan todistajiksi, koska olemme todistaneet Jumalaa vastaan, että hän on herättänyt Kristuksen, jota hän ei ole herättänyt, jos kerran kuolleita ei herätetä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 16, 'Sillä jos kuolleita ei herätetä, ei Kristuskaan ole herätetty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 17, 'Mutta jos Kristus ei ole herätetty, niin teidän uskonne on turha, ja te olette vielä synneissänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 18, 'Ja silloinhan Kristuksessa nukkuneetkin olisivat kadotetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 19, 'Jos olemme panneet toivomme Kristukseen ainoastaan tämän elämän ajaksi, niin olemme kaikkia muita ihmisiä surkuteltavammat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 20, 'Mutta nytpä Kristus on noussut kuolleista, esikoisena kuoloon nukkuneista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 21, 'Sillä koska kuolema on tullut ihmisen kautta, niin on myöskin kuolleitten ylösnousemus tullut ihmisen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 22, 'Sillä niinkuin kaikki kuolevat Aadamissa, niin myös kaikki tehdään eläviksi Kristuksessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 23, 'mutta jokainen vuorollaan: esikoisena Kristus, sitten Kristuksen omat hänen tulemuksessaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 24, 'sitten tulee loppu, kun hän antaa valtakunnan Jumalan ja Isän haltuun, kukistettuaan kaiken hallituksen ja kaiken vallan ja voiman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 25, 'Sillä hänen pitää hallitseman \"siihen asti, kunnes hän on pannut kaikki viholliset jalkojensa alle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 26, 'Vihollisista viimeisenä kukistetaan kuolema.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 27, 'Sillä: \"kaikki hän on alistanut hänen jalkojensa alle\". Mutta kun hän sanoo: \"kaikki on alistettu\", niin ei tietenkään ole alistettu se, joka on alistanut kaiken hänen allensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 28, 'Ja kun kaikki on alistettu Pojan valtaan, silloin itse Poikakin alistetaan sen valtaan, joka on alistanut hänen valtaansa kaiken, että Jumala olisi kaikki kaikissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 29, 'Mitä muutoin ne, jotka kastattavat itsensä kuolleitten puolesta, sillä saavat aikaan? Jos kuolleet eivät heräjä, miksi nämä sitten kastattavat itsensä heidän puolestaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 30, 'Ja miksi mekään antaudumme joka hetki vaaraan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 31, 'Joka päivä minä olen kuoleman kidassa, niin totta kuin te, veljet, olette minun kerskaukseni Kristuksessa Jeesuksessa, meidän Herrassamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 32, 'Jos minä ihmisten tavoin olen taistellut petojen kanssa Efesossa, mitä hyötyä minulle siitä on? Jos kuolleet eivät heräjä, niin: \"syökäämme ja juokaamme, sillä huomenna me kuolemme\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 33, 'Älkää eksykö. \"Huono seura hyvät tavat turmelee.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 34, 'Raitistukaa oikealla tavalla, älkääkä syntiä tehkö; sillä niitä on, joilla ei ole mitään tietoa Jumalasta. Teidän häpeäksenne minä tämän sanon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 35, 'Mutta joku ehkä kysyy: \"Millä tavoin kuolleet heräjävät, ja millaisessa ruumiissa he tulevat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 36, 'Sinä mieletön, se, minkä kylvät, ei virkoa eloon, ellei se ensin kuole!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 37, 'Ja kun kylvät, et kylvä sitä vartta, joka on nouseva, vaan paljaan jyvän, nisun jyvän tai muun minkä tahansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 38, 'Mutta Jumala antaa sille varren, sellaisen kuin tahtoo, ja kullekin siemenelle sen oman varren.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 39, 'Ei kaikki liha ole samaa lihaa, vaan toista on ihmisten, toista taas karjan liha, toista on lintujen liha, toista kalojen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 40, 'Ja on taivaallisia ruumiita ja maallisia ruumiita; mutta toinen on taivaallisten kirkkaus, toinen taas maallisten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 41, 'Toinen on auringon kirkkaus ja toinen kuun kirkkaus ja toinen tähtien kirkkaus, ja toinen tähti voittaa toisen kirkkaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 42, 'Niin on myös kuolleitten ylösnousemus: kylvetään katoavaisuudessa, nousee katoamattomuudessa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 43, 'kylvetään alhaisuudessa, nousee kirkkaudessa; kylvetään heikkoudessa, nousee voimassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 44, 'kylvetään sielullinen ruumis, nousee hengellinen ruumis. Jos kerran on sielullinen ruumis, niin on myös hengellinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 45, 'Niin on myös kirjoitettu: \"Ensimmäisestä ihmisestä, Aadamista, tuli elävä sielu\"; viimeisestä Aadamista tuli eläväksitekevä henki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 46, 'Mutta mikä on hengellistä, se ei ole ensimmäinen, vaan se, mikä on sielullista, on ensimmäinen; sitten on se, mikä on hengellistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 47, 'Ensimmäinen ihminen oli maasta, maallinen, toinen ihminen on taivaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 48, 'Minkäkaltainen maallinen oli, senkaltaisia ovat myös maalliset; ja minkäkaltainen taivaallinen on, senkaltaisia ovat myös taivaalliset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 49, 'Ja niinkuin meissä on ollut maallisen kuva, niin meissä on myös oleva taivaallisen kuva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 50, 'Mutta tämän minä sanon, veljet, ettei liha ja veri voi periä Jumalan valtakuntaa, eikä katoavaisuus peri katoamattomuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 51, 'Katso, minä sanon teille salaisuuden: emme kaikki kuolemaan nuku, mutta kaikki me muutumme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 52, 'yhtäkkiä, silmänräpäyksessä, viimeisen pasunan soidessa; sillä pasuna soi, ja kuolleet nousevat katoamattomina, ja me muutumme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 53, 'Sillä tämän katoavaisen pitää pukeutuman katoamattomuuteen, ja tämän kuolevaisen pitää pukeutuman kuolemattomuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 54, 'Mutta kun tämä katoavainen pukeutuu katoamattomuuteen ja tämä kuolevainen pukeutuu kuolemattomuuteen, silloin toteutuu se sana, joka on kirjoitettu: \"Kuolema on nielty ja voitto saatu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 55, '\"Kuolema, missä on sinun voittosi? Kuolema, missä on sinun otasi?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 56, 'Mutta kuoleman ota on synti, ja synnin voima on laki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 57, 'Mutta kiitos olkoon Jumalan, joka antaa meille voiton meidän Herramme Jeesuksen Kristuksen kautta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 15, 58, 'Sentähden, rakkaat veljeni, olkaa lujat, järkähtämättömät, aina innokkaat Herran työssä, tietäen, että teidän vaivannäkönne ei ole turha Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 1, 'Mitä tulee keräykseen pyhiä varten, niin tehkää tekin samalla tavoin, kuin minä olen määrännyt Galatian seurakunnille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 2, 'Kunkin viikon ensimmäisenä päivänä pankoon jokainen teistä kotonaan jotakin talteen, säästäen menestymisensä mukaan, ettei keräyksiä tehtäisi vasta minun tultuani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 3, 'Mutta kun olen saapunut teidän tykönne, lähetän minä ne henkilöt, jotka siihen sopiviksi katsotte, kirjeet mukanaan, viemään teidän rakkaudenlahjanne Jerusalemiin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 4, 'ja jos asia on sen arvoinen, että minunkin on lähteminen, niin saavat he lähteä minun kanssani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 5, 'Aion nimittäin tulla teidän tykönne kuljettuani läpi Makedonian, sillä minä kuljen Makedonian kautta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 6, 'mutta teidän luonanne viivyn ehkä jonkin aikaa, kenties vietän talvenkin, että te sitten auttaisitte minua eteenpäin, minne matkustanenkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 7, 'Sillä en tahdo nyt vain ohimennen käydä teitä katsomassa, toivon näet saavani viipyä jonkin aikaa teidän luonanne, jos Herra sallii.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 8, 'Mutta Efesossa minä viivyn helluntaihin saakka;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 9, 'sillä minulle on avautunut ovi suureen ja hedelmälliseen työhön, ja vastustajia on paljon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 10, 'Mutta jos Timoteus saapuu, niin katsokaa, että hän pelotta voi olla teidän luonanne, sillä Herran työtä hän toimittaa niinkuin minäkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 11, 'Älköön siis kukaan häntä halveksiko, vaan auttakaa häntä lähtemään rauhassa matkalle, että hän tulisi minun tyköni; sillä minä ja veljet odotamme häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 12, 'Mitä veli Apollokseen tulee, olen hartaasti kehoittanut häntä lähtemään veljien kanssa teidän tykönne; mutta hän ei ole ollenkaan halukas lähtemään nyt, vaan tulee, kun hänelle sopii.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 13, 'Valvokaa, pysykää lujina uskossa, olkaa miehuulliset, olkaa väkevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 14, 'Kaikki, mitä teette, tapahtukoon rakkaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 15, 'Mutta minä kehoitan teitä, veljet: te tunnette Stefanaan perhekunnan ja tiedätte, että se on Akaian ensi hedelmä ja että he ovat antautuneet pyhien palvelukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 16, 'Olkaa tekin kuuliaisia heidän kaltaisilleen ja jokaiselle, joka heidän kanssaan työtä tekee ja vaivaa näkee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 17, 'Minä iloitsen Stefanaan ja Fortunatuksen ja Akaikuksen tännetulosta, koska he korvaavat minulle teidän poissaolonne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 18, 'he ovat virkistäneet minun henkeäni niinkuin teidänkin. Antakaa siis täysi tunnustus sellaisille miehille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 19, 'Aasian seurakunnat tervehtivät teitä. Monet tervehdykset Herrassa lähettävät teille Akylas ja Priska sekä heidän kodissaan kokoontuva seurakunta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 20, 'Kaikki veljet lähettävät teille tervehdyksen. Tervehtikää toisianne pyhällä suunannolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 21, 'Tervehdys minulta, Paavalilta, omakätisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 22, 'Jos joku ei pidä Herraa rakkaana, hän olkoon kirottu! Maran ata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 23, 'Herran Jeesuksen armo olkoon teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 16, 24, 'Minun rakkauteni on teidän kaikkien kanssa Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Paavali, Jumalan tahdosta Kristuksen Jeesuksen apostoli, ja veli Timoteus Korintossa olevalle Jumalan seurakunnalle ynnä kaikille pyhille koko Akaiassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Kiitetty olkoon meidän Herramme Jeesuksen Kristuksen Jumala ja Isä, laupeuden Isä ja kaiken lohdutuksen Jumala,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'joka lohduttaa meitä kaikessa ahdistuksessamme, että me sillä lohdutuksella, jolla Jumala meitä itseämme lohduttaa, voisimme lohduttaa niitä, jotka kaikkinaisessa ahdistuksessa ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Sillä samoin kuin Kristuksen kärsimykset runsaina tulevat meidän osaksemme, samoin tulee meidän osaksemme myöskin lohdutus runsaana Kristuksen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Mutta jos olemme ahdistuksessa, niin tapahtuu se teille lohdutukseksi ja pelastukseksi; jos taas saamme lohdutusta, niin tapahtuu sekin teille lohdutukseksi, ja se vaikuttaa, että te kestätte samat kärsimykset, joita mekin kärsimme; ja toivomme teistä on vahva,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'koska me tiedämme, että samoin kuin olette osalliset kärsimyksistä, samoin olette osalliset myöskin lohdutuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Sillä me emme tahdo, veljet, pitää teitä tietämättöminä siitä ahdistuksesta, jossa me olimme Aasiassa, kuinka ylenpalttiset, yli voimiemme käyvät, meidän rasituksemme olivat, niin että jo olimme epätoivossa hengestämmekin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'ja itse me jo luulimme olevamme kuolemaan tuomitut, ettemme luottaisi itseemme, vaan Jumalaan, joka kuolleet herättää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Ja hän pelasti meidät niin suuresta kuolemanvaarasta, ja yhä pelastaa, ja häneen me olemme panneet toivomme, että hän vielä vastakin pelastaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'kun tekin autatte meitä rukouksillanne, että monesta suusta meidän tähtemme kohoaisi runsas kiitos siitä armosta, joka on osaksemme tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Sillä meidän kerskauksemme on tämä: meidän omantuntomme todistus siitä, että me maailmassa ja varsinkin teidän luonanne olemme vaeltaneet Jumalan pyhyydessä ja puhtaudessa, emme lihallisessa viisaudessa, vaan Jumalan armossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Sillä eihän siinä, mitä teille kirjoitamme, ole muuta, kuin mikä siinä on luettavana ja minkä te myös ymmärrätte; ja minä toivon teidän loppuun asti ymmärtävän');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, '-niinkuin meitä osaksi myös olette oppineet ymmärtämään-että me olemme teidän kerskauksenne, samoin kuin tekin meidän, Herramme Jeesuksen päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 15, 'Ja tässä luottamuksessa minä aioin ensin tulla teidän tykönne, että saisitte vielä toisenkin todistuksen minun suosiostani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 16, 'ja sitten teidän kauttanne matkustaa Makedoniaan, ja taas Makedoniasta palata teidän tykönne ja teidän varustamananne matkata Juudeaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 17, 'Kun minulla siis oli tämä aikomus, en kaiketi ole menetellyt kevytmielisesti? Vai päätänkö lihan mukaan, minkä päätän, niin että puheeni on sekä \"on, on\", että \"ei, ei\"?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 18, 'Mutta Jumala sen takaa, että puheemme teille ei ole \"on\" ja \"ei\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 19, 'Sillä Jumalan Poika, Kristus Jeesus, jota me, minä ja Silvanus ja Timoteus, olemme teidän keskellänne saarnanneet, ei tullut ollakseen \"on\" ja \"ei\", vaan hänessä tuli \"on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 20, 'Sillä niin monta kuin Jumalan lupausta on, kaikki ne ovat hänessä \"on\"; sentähden tulee hänen kauttaan myös niiden \"amen\", Jumalalle kunniaksi meidän kauttamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 21, 'Mutta se, joka lujittaa meidät yhdessä teidän kanssanne Kristukseen ja joka on voidellut meidät, on Jumala,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 22, 'joka myös on painanut meihin sinettinsä ja antanut Hengen vakuudeksi meidän sydämiimme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 23, 'Mutta minä kutsun Jumalan sieluni todistajaksi, että minä teitä säästääkseni en vielä tullut Korinttoon;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 24, 'ei niin, että tahdomme vallita teidän uskoanne, vaan me yhdessä autamme teitä teidän iloonne; sillä uskossa te olette lujat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 1, 'Olin nimittäin mielessäni päättänyt, etten tullessani teidän tykönne taas toisi murhetta mukanani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 2, 'Sillä jos minä saatan teidät murheellisiksi, niin eihän minua voi saada iloiseksi kukaan muu kuin se, jonka minä olen murheelliseksi saattanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 3, 'Ja juuri sen minä kirjoitin sitä varten, etten tullessani saisi murhetta niistä, joista minun piti saada iloa, koska minulla on teihin kaikkiin se luottamus, että minun iloni on kaikkien teidän ilonne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 4, 'Sillä suuressa sydämen ahdistuksessa ja hädässä minä kirjoitin teille monin kyynelin, en sitä varten, että te murheellisiksi tulisitte, vaan että tuntisitte sen erinomaisen rakkauden, joka minulla on teihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 5, 'Mutta jos eräs on tuottanut murhetta, ei hän ole tuottanut murhetta minulle, vaan teille kaikille, jossakin määrin, etten liikaa sanoisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 6, 'Semmoiselle riittää se rangaistus, minkä hän useimmilta on saanut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 7, 'niin että teidän päinvastoin ennemmin tulee antaa anteeksi ja lohduttaa, ettei hän ehkä menehtyisi liian suureen murheeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 8, 'Sentähden minä kehoitan teitä, että päätätte ruveta osoittamaan rakkautta häntä kohtaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 9, 'sillä sitä varten minä kirjoitinkin, että saisin nähdä, kuinka te kestätte koetuksen, oletteko kaikessa kuuliaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 10, 'Mutta kenelle te jotakin anteeksi annatte, sille minäkin; sillä mitä minä olen anteeksi antanut-jos minulla on ollut jotakin anteeksiannettavaa-sen olen anteeksi antanut teidän tähtenne Kristuksen kasvojen edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 11, 'ettei saatana pääsisi meistä voitolle; sillä hänen juonensa eivät ole meille tuntemattomat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 12, 'Tultuani Trooaaseen julistamaan Kristuksen evankeliumia avautui minulle ovi työhön Herrassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 13, 'mutta minä en saanut lepoa hengessäni, kun en tavannut Tiitusta, veljeäni. Sentähden sanoin heille jäähyväiset ja lähdin Makedoniaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 14, 'Mutta kiitos olkoon Jumalan, joka aina kuljettaa meitä voittosaatossa Kristuksessa ja meidän kauttamme joka paikassa tuo ilmi hänen tuntemisensa tuoksun!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 15, 'Sillä me olemme Kristuksen tuoksu Jumalalle sekä pelastuvien että kadotukseen joutuvien joukossa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 16, 'näille tosin kuoleman haju kuolemaksi, mutta noille elämän tuoksu elämäksi. Ja kuka on tällaiseen kelvollinen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 2, 17, 'Sillä me emme ole niinkuin nuo monet, jotka myyskentelevät Jumalan sanaa; vaan puhtaasta mielestä, niinkuin Jumalan vaikutuksesta, Jumalan edessä, me Kristuksessa puhumme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 1, 'Alammeko taas suositella itseämme? Vai tarvinnemmeko, niinkuin muutamat, suosituskirjeitä teille tai teiltä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 2, 'Te itse olette meidän kirjeemme, joka on sydämeemme kirjoitettu ja jonka kaikki ihmiset tuntevat ja lukevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 3, 'Sillä ilmeistä on, että te olette Kristuksen kirje, meidän palvelustyöllämme kirjoitettu, ei musteella, vaan elävän Jumalan Hengellä, ei kivitauluihin, vaan sydämen lihatauluihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 4, 'Tämmöinen luottamus meillä on Kristuksen kautta Jumalaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 5, 'ei niin, että meillä itsellämme olisi kykyä ajatella jotakin, ikäänkuin se tulisi meistä itsestämme, vaan se kyky, mikä meillä on, on Jumalasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 6, 'joka myös on tehnyt meidät kykeneviksi olemaan uuden liiton palvelijoita, ei kirjaimen, vaan Hengen; sillä kirjain kuolettaa, mutta Henki tekee eläväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 7, 'Mutta jos jo kuoleman virka, joka oli kirjaimin kaiverrettu kiviin, ilmestyi kirkkaudessa, niin etteivät Israelin lapset kärsineet katsella Mooseksen kasvoja hänen kasvojensa kirkkauden tähden, joka kuitenkin oli katoavaista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 8, 'kuinka paljoa enemmän onkaan Hengen virka oleva kirkkaudessa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 9, 'Sillä jos kadotustuomion virka jo oli kirkkautta, niin on vanhurskauden virka vielä paljoa runsaammassa määrin kirkkautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 10, 'Sillä se, millä ennen oli kirkkaus, on tämän rinnalla kirkkautta vailla, tämän ylenpalttisen kirkkauden tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 11, 'Jos sillä, mikä on katoavaista, oli kirkkaus, niin vielä paljoa enemmän on sillä, mikä on pysyväistä, oleva kirkkautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 12, 'Koska meillä siis on tämmöinen toivo, niin me olemme aivan rohkeat');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 13, 'emmekä tee niinkuin Mooses, joka pani peitteen kasvoillensa, etteivät Israelin lapset näkisi sen loppua, mikä on katoavaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 14, 'Mutta heidän mielensä paatuivat, sillä vielä tänäkin päivänä sama peite, vanhan liiton kirjoituksia luettaessa, pysyy poisottamatta, sillä vasta Kristuksessa se katoaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 15, 'Vielä tänäkin päivänä, kun Moosesta luetaan, on peite heidän sydämensä päällä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 16, 'mutta kun heidän sydämensä kääntyy Herran tykö, otetaan peite pois.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 17, 'Sillä Herra on Henki, ja missä Herran Henki on, siinä on vapaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 3, 18, 'Mutta me kaikki, jotka peittämättömin kasvoin katselemme Herran kirkkautta kuin kuvastimesta, muutumme saman kuvan kaltaisiksi kirkkaudesta kirkkauteen, niinkuin muuttaa Herra, joka on Henki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 1, 'Sentähden, kun meillä on tämä virka sen laupeuden mukaan, joka on osaksemme tullut, me emme lannistu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 2, 'vaan olemme hyljänneet kaikki häpeälliset salatiet, niin ettemme vaella kavaluudessa emmekä väärennä Jumalan sanaa, vaan julkituomalla totuuden me suositamme itseämme jokaisen ihmisen omalletunnolle Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 3, 'Mutta jos meidän evankeliumimme on peitossa, niin se peite on niissä, jotka kadotukseen joutuvat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 4, 'niissä uskottomissa, joiden mielet tämän maailman jumala on niin sokaissut, ettei heille loista valkeus, joka lähtee Kristuksen kirkkauden evankeliumista, hänen, joka on Jumalan kuva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 5, 'Sillä me emme julista itseämme, vaan Kristusta Jeesusta, että hän on Herra ja me teidän palvelijanne Jeesuksen tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 6, 'Sillä Jumala, joka sanoi: \"Loistakoon valkeus pimeydestä\", on se, joka loisti sydämiimme, että Jumalan kirkkauden tunteminen, sen kirkkauden, joka loistaa Kristuksen kasvoissa, levittäisi valoansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 7, 'Mutta tämä aarre on meillä saviastioissa, että tuo suunnattoman suuri voima olisi Jumalan eikä näyttäisi tulevan meistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 8, 'Me olemme kaikin tavoin ahdingossa, mutta emme umpikujassa, neuvottomat, mutta emme toivottomat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 9, 'vainotut, mutta emme hyljätyt, maahan kukistetut, mutta emme tuhotut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 10, 'Me kuljemme, aina kantaen Jeesuksen kuolemaa ruumiissamme, että Jeesuksen elämäkin tulisi meidän ruumiissamme näkyviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 11, 'Sillä me, jotka elämme, olemme alati annetut kuolemaan Jeesuksen tähden, että Jeesuksen elämäkin tulisi kuolevaisessa lihassamme näkyviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 12, 'Niinpä siis kuolema tekee työtään meissä, mutta elämä teissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 13, 'Mutta koska meillä on sama uskon Henki, niinkuin kirjoitettu on: \"Minä uskon, sentähden minä puhun\", niin mekin uskomme, ja sentähden me myös puhumme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 14, 'tietäen, että hän, joka herätti Herran Jeesuksen, on herättävä meidätkin Jeesuksen kanssa ja asettava esiin yhdessä teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 15, 'Sillä kaikki tapahtuu teidän tähtenne, että aina enenevä armo yhä useampien kautta saisi aikaan yhä runsaampaa kiitosta Jumalan kunniaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 16, 'Sentähden me emme lannistu; vaan vaikka ulkonainen ihmisemme menehtyykin, niin sisällinen kuitenkin päivä päivältä uudistuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 17, 'Sillä tämä hetkisen kestävä ja kevyt ahdistuksemme tuottaa meille iankaikkisen ja määrättömän kirkkauden, ylenpalttisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 4, 18, 'meille, jotka emme katso näkyväisiä, vaan näkymättömiä; sillä näkyväiset ovat ajallisia, mutta näkymättömät iankaikkisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 1, 'Sillä me tiedämme, että vaikka tämä meidän maallinen majamme hajotetaankin maahan, meillä on asumus Jumalalta, iankaikkinen maja taivaissa, joka ei ole käsin tehty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 2, 'Sentähden me huokaammekin ikävöiden, että saisimme pukeutua taivaalliseen majaamme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 3, 'sillä kun me kerran olemme siihen pukeutuneet, ei meitä enää havaita alastomiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 4, 'Sillä me, jotka olemme tässä majassa, huokaamme raskautettuina, koska emme tahdo riisuutua, vaan pukeutua, että elämä nielisi sen, mikä on kuolevaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 5, 'Mutta se, joka on valmistanut meidät juuri tähän, on Jumala, joka on antanut meille Hengen vakuudeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 6, 'Sentähden me aina olemme turvallisella mielellä ja tiedämme, että, niin kauan kuin olemme kotona tässä ruumiissamme, me olemme poissa Herrasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 7, 'sillä me vaellamme uskossa emmekä näkemisessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 8, 'Mutta me olemme turvallisella mielellä ja haluaisimme mieluummin muuttaa pois ruumiista ja päästä kotiin Herran tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 9, 'Sentähden me, olimmepa kotona tai olimmepa poissa, ahkeroitsemme olla hänelle mieliksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 10, 'Sillä kaikkien meidän pitää ilmestymän Kristuksen tuomioistuimen eteen, että kukin saisi sen mukaan, kuin hän ruumiissa ollessaan on tehnyt, joko hyvää tai pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 11, 'Kun siis tiedämme, mitä Herran pelko on, niin me koetamme saada ihmisiä uskomaan, mutta Jumala kyllä meidät tuntee; ja minä toivon, että tekin omissatunnoissanne meidät tunnette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 12, 'Emme nyt taas suosittele itseämme teille, vaan tahdomme antaa teille aihetta kerskata meistä, että teillä olisi mitä vastata niille, jotka kerskaavat siitä, mikä silmään näkyy, eikä siitä, mikä sydämessä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 13, 'Sillä jos me olemme olleet suunniltamme, niin olemme olleet Jumalan tähden; jos taas maltamme mielemme, teemme sen teidän tähtenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 14, 'Sillä Kristuksen rakkaus vaatii meitä, jotka olemme tulleet tähän päätökseen: yksi on kuollut kaikkien edestä, siis myös kaikki ovat kuolleet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 15, 'ja hän on kuollut kaikkien edestä, että ne, jotka elävät, eivät enää eläisi itselleen, vaan hänelle, joka heidän edestään on kuollut ja ylösnoussut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 16, 'Sentähden me emme tästä lähtien tunne ketään lihan mukaan; jos olemmekin tunteneet Kristuksen lihan mukaan, emme kuitenkaan nyt enää tunne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 17, 'Siis, jos joku on Kristuksessa, niin hän on uusi luomus; se, mikä on vanhaa, on kadonnut, katso, uusi on sijaan tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 18, 'Mutta kaikki on Jumalasta, joka on sovittanut meidät itsensä kanssa Kristuksen kautta ja antanut meille sovituksen viran.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 19, 'Sillä Jumala oli Kristuksessa ja sovitti maailman itsensä kanssa eikä lukenut heille heidän rikkomuksiaan, ja hän uskoi meille sovituksen sanan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 20, 'Kristuksen puolesta me siis olemme lähettiläinä, ja Jumala kehoittaa meidän kauttamme. Me pyydämme Kristuksen puolesta: antakaa sovittaa itsenne Jumalan kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 5, 21, 'Sen, joka ei synnistä tiennyt, hän meidän tähtemme teki synniksi, että me hänessä tulisimme Jumalan vanhurskaudeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 1, 'Hänen työtovereinaan me myös kehoitamme teitä vastaanottamaan Jumalan armon niin, ettei se jää turhaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 2, 'Sillä hän sanoo: \"Otollisella ajalla minä olen sinua kuullut ja pelastuksen päivänä sinua auttanut\". Katso, nyt on otollinen aika, katso, nyt on pelastuksen päivä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 3, 'Me emme missään kohden anna aihetta pahennukseen, ettei virkaamme moitittaisi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 4, 'vaan kaikessa me osoittaudumme Jumalan palvelijoiksi: suuressa kärsivällisyydessä, vaivoissa, hädissä, ahdistuksissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 5, 'ruoskittaessa, vankeudessa, meteleissä, vaivannäöissä, valvomisissa, paastoissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 6, 'puhtaudessa, tiedossa, pitkämielisyydessä, ystävällisyydessä, Pyhässä Hengessä, vilpittömässä rakkaudessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 7, 'totuuden sanassa, Jumalan voimassa, vanhurskauden sota-aseet oikeassa kädessä ja vasemmassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 8, 'kunniassa ja häpeässä, pahassa maineessa ja hyvässä, villitsijöinä ja kuitenkin totta puhuvina,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 9, 'tuntemattomina ja kuitenkin hyvin tunnettuina; kuolemaisillamme, ja katso, me elämme, kuritettuina emmekä kuitenkaan tapettuina,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 10, 'murheellisina, mutta aina iloisina, köyhinä, mutta kuitenkin monia rikkaiksi tekevinä, mitään omistamatta, mutta kuitenkin omistaen kaiken.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 11, 'Suumme on auennut puhumaan teille, korinttolaiset, sydämemme on avartunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 12, 'Ei ole teillä ahdasta meidän sydämessämme, mutta ahdas on teidän oma sydämenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 13, 'Antakaa verta verrasta-puhun kuin lapsilleni-avartukaa tekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 14, 'Älkää antautuko kantamaan vierasta iestä yhdessä uskottomien kanssa; sillä mitä yhteistä on vanhurskaudella ja vääryydellä? Tai mitä yhteyttä on valkeudella ja pimeydellä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 15, 'Ja miten sopivat yhteen Kristus ja Beliar? Tai mitä yhteistä osaa uskovaisella on uskottoman kanssa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 16, 'Ja miten soveltuvat yhteen Jumalan temppeli ja epäjumalat? Sillä me olemme elävän Jumalan temppeli, niinkuin Jumala on sanonut: \"Minä olen heissä asuva ja vaeltava heidän keskellään ja oleva heidän Jumalansa, ja he ovat minun kansani\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 17, 'Sentähden: \"Lähtekää pois heidän keskeltänsä ja erotkaa heistä, sanoo Herra, älkääkä saastaiseen koskeko; niin minä otan teidät huostaani');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 6, 18, 'ja olen teidän Isänne, ja te tulette minun pojikseni ja tyttärikseni, sanoo Herra, Kaikkivaltias\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 1, 'Koska meillä siis on nämä lupaukset, rakkaani, niin puhdistautukaamme kaikesta lihan ja hengen saastutuksesta, saattaen pyhityksemme täydelliseksi Jumalan pelossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 2, 'Antakaa meille tilaa sydämessänne. Emme ole tehneet kenellekään vääryyttä, emme ole olleet kenellekään turmioksi, emme kenellekään vahinkoa tuottaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 3, 'En sano tätä tuomitakseni teitä, sillä olenhan jo sanonut, että te olette meidän sydämessämme, yhdessä kuollaksemme ja yhdessä elääksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 4, 'Paljon minulla on luottamusta teihin, paljon minulla on kerskaamista teistä; olen täynnä lohdutusta, minulla on ylenpalttinen ilo kaikessa ahdingossamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 5, 'Sillä ei Makedoniaan tultuammekaan lihamme saanut mitään rauhaa, vaan me olimme kaikin tavoin ahdistetut: ulkoapäin taisteluja, sisältäpäin pelkoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 6, 'Mutta Jumala, joka masentuneita lohduttaa, lohdutti meitä Tiituksen tulolla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 7, 'eikä ainoastaan hänen tulollansa, vaan myöskin sillä lohdutuksella, jonka hän oli teistä saanut, sillä hän on kertonut meille teidän ikävöimisestänne, valittelustanne ja innostanne minun hyväkseni, niin että minä iloitsin vielä enemmän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 8, 'Sillä vaikka murehutinkin teitä kirjeelläni, en sitä kadu, ja jos kaduinkin, niin minä-kun näen, että tuo kirje on, vaikkapa vain vähäksi aikaa, murehuttanut teitä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 9, 'nyt iloitsen, en siitä, että tulitte murheellisiksi, vaan siitä, että murheenne oli teille parannukseksi; sillä te tulitte murheellisiksi Jumalan mielen mukaan, ettei teillä olisi mitään vahinkoa meistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 10, 'Sillä Jumalan mielen mukainen murhe saa aikaan parannuksen, joka koituu pelastukseksi ja jota ei kukaan kadu; mutta maailman murhe tuottaa kuoleman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 11, 'Sillä katsokaa, kuinka suurta intoa juuri tuo Jumalan mielen mukainen murehtimisenne on saanut teissä aikaan, mitä puolustautumista, mitä paheksumista, mitä pelkoa, ikävöimistä, kiivautta, mitä kurittamista! Olette kaikin tavoin osoittaneet olevanne puhtaat tässä asiassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 12, 'Vaikka minä siis kirjoitinkin teille, en kirjoittanut vääryyttä tehneen enkä vääryyttä kärsineen vuoksi, vaan sentähden, että teidän intonne meidän hyväksemme tulisi julki teidän keskuudessanne Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 13, 'Sentähden me olemme nyt lohdutetut. Mutta tämän lohdutuksemme ohessa on meitä vielä paljoa enemmän ilahuttanut Tiituksen ilo, sillä hänen henkensä on saanut virvoitusta teiltä kaikilta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 14, 'Sillä jos olenkin jossakin kohden teitä hänelle kehunut, en ole joutunut häpeään, vaan niinkuin kaikki, mitä olemme teille puhuneet, on totta, niin on myös se, mistä olemme teitä Tiitukselle kehuneet, osoittautunut todeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 15, 'Ja hänen sydämensä heltyy yhä enemmän teitä kohtaan, kun hän muistelee kaikkien teidän kuuliaisuuttanne, kuinka te pelolla ja vavistuksella otitte hänet vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 7, 16, 'Minä iloitsen, että kaikessa voin olla teistä turvallisella mielellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 1, 'Mutta me saatamme teidän tietoonne, veljet, mitä Jumalan armo on vaikuttanut Makedonian seurakunnissa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 2, 'että, vaikka he olivatkin monessa ahdistuksen koetuksessa, niin oli heidän ilonsa heidän suuressa köyhyydessäänkin niin ylenpalttinen, että he alttiisti antoivat runsaita lahjoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 3, 'Sillä voimiensa mukaan, sen minä todistan, jopa yli voimiensakin he antoivat omasta halustansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 4, 'paljolla pyytämisellä anoen meiltä sitä suosiota, että pääsisivät osallisiksi pyhien avustamiseen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 5, 'eivätkä he vain tehneet, niinkuin me olimme toivoneet, vaan antoivat itsensäkin, ennen kaikkea Herralle ja sitten meille, Jumalan tahdosta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 6, 'niin että me kehoitimme Tiitusta, niinkuin hän jo oli alkanut, saattamaan teidän keskuudessanne päätökseen tämänkin rakkaudentyön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 7, 'Mutta niinkuin teillä on ylenpalttisesti kaikkea: uskoa, sanaa, tietoa, kaikkinaista intoa ja meistä teihin tullutta rakkautta, niin olkaa ylenpalttiset tässäkin rakkaudentyössä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 8, 'En sano tätä käskien, vaan viittaamalla muiden intoon minä tahdon koetella teidänkin rakkautenne vilpittömyyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 9, 'Sillä te tunnette meidän Herramme Jeesuksen Kristuksen armon, että hän, vaikka oli rikas, tuli teidän tähtenne köyhäksi, että te hänen köyhyydestään rikastuisitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 10, 'Minä annan vain neuvon tässä asiassa; sillä se on hyödyksi teille, jotka jo viime vuonna olitte ensimmäiset, ette ainoastaan tekemässä, vaan myös tahtomassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 11, 'Täyttäkää nyt siis tekonne, niin että, yhtä alttiisti kuin olitte sen päättäneet, sen myös täyttäisitte, varojenne mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 12, 'Sillä jos on alttiutta, niin se on otollinen sen mukaan, kuin on varoja, eikä sen mukaan, kuin niitä ei ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 13, 'Sillä ei ole tarkoitus, että muilla olisi huojennus, teillä rasitus, vaan tasauksen vuoksi tulkoon tätä nykyä teidän yltäkylläisyytenne heidän puutteensa hyväksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 14, 'että heidänkin yltäkylläisyytensä tulisi teidän puutteenne hyväksi, niin että syntyisi tasaus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 15, 'niinkuin kirjoitettu on: \"Joka oli paljon koonnut, sille ei jäänyt liikaa, ja joka oli koonnut vähän, siltä ei mitään puuttunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 16, 'Mutta kiitos Jumalalle, joka antaa Tiituksen sydämeen saman innon teidän hyväksenne!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 17, 'Sillä hän otti varteen minun kehoitukseni, innostuipa niinkin, että lähtee omasta halustaan teidän tykönne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 18, 'Ja me lähetämme hänen kanssaan veljen, jota evankeliumin julistamisesta kiitetään kaikissa seurakunnissa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 19, 'ja jonka seurakunnat vielä sen lisäksi myös ovat valinneet matkatoveriksemme viemään tätä rakkauden lahjaa, joka on meidän toimitettavanamme itse Herran kunniaksi ja oman alttiutemme osoitukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 20, 'Näin me teemme, ettei kukaan pääsisi moittimaan meitä mistään, mikä koskee tätä runsasta avustusta, joka on meidän toimitettavanamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 21, 'Sillä me ahkeroitsemme sitä, mikä on hyvää ei ainoastaan Herran, vaan myös ihmisten edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 22, 'Ja näiden kanssa me lähetämme vielä erään veljemme, jonka intoa usein ja monessa asiassa olemme koetelleet ja joka nyt on entistä paljon innokkaampi, koska hänellä on niin suuri luottamus teihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 23, 'Jos siis on puhe Tiituksesta, niin hän on minun toverini ja työkumppanini teidän hyväksenne; meidän veljemme taas ovat seurakuntien lähettiläitä, ovat Kristuksen kunnia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 8, 24, 'Kun te siis osoitatte heille rakkauttanne ja näytätte todeksi sen, mistä me olemme teitä kehuneet, niin teette sen seurakuntien edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 1, 'Pyhien avustamisesta minun tosin on tarpeetonta kirjoittaa teille;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 2, 'sillä minä tunnen teidän alttiutenne, ja siitä minä kehun teitä makedonialaisille, että näet Akaia on ollut valmiina menneestä vuodesta alkaen, ja niin on teidän intonne saanut sangen monta innostumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 3, 'Lähetän nyt kuitenkin nämä veljet, ettei kerskaamisemme teistä tässä kohden näyttäytyisi tyhjäksi, vaan että olisitte valmiit, niinkuin olen sanonut teidän olevan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 4, 'muutoin, jos makedonialaisia tulee minun kanssani ja he tapaavat teidät valmistumattomina, me-ettemme sanoisi te-ehkä joutuisimme häpeään tässä luottamuksessamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 5, 'Olen siis katsonut tarpeelliseksi kehoittaa veljiä edeltäpäin lähtemään teidän tykönne ja toimittamaan valmiiksi ennen lupaamanne runsaan lahjan, niin että se olisi valmis runsaana eikä kitsaana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 6, 'Huomatkaa tämä: joka niukasti kylvää, se myös niukasti niittää, ja joka runsaasti kylvää, se myös runsaasti niittää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 7, 'Antakoon kukin, niinkuin hänen sydämensä vaatii, ei surkeillen eikä pakosta; sillä iloista antajaa Jumala rakastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 8, 'Ja Jumala on voimallinen antamaan teille ylenpalttisesti kaikkea armoa, että teillä kaikessa aina olisi kaikkea riittävästi, voidaksenne ylenpalttisesti tehdä kaikkinaista hyvää;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 9, 'niinkuin kirjoitettu on: \"Hän sirottelee, hän antaa köyhille, hänen vanhurskautensa pysyy iankaikkisesti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 10, 'Ja hän, joka antaa siemenen kylväjälle ja leivän ruuaksi, on antava teillekin ja enentävä kylvönne ja kasvattava teidän vanhurskautenne hedelmät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 11, 'niin että te kaikessa vaurastuen voitte vilpittömästi harjoittaa kaikkinaista anteliaisuutta, joka meidän kauttamme saa aikaan kiitosta Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 12, 'Sillä tämä avustamispalvelus ei ainoastaan poista pyhien puutteita, vaan käy vieläkin hedelmällisemmäksi Jumalalle annettujen monien kiitosten kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 13, 'kun he, tästä teidän palveluksestanne huomattuaan, kuinka taattu teidän mielenne on, ylistävät Jumalaa siitä, että te näin alistuvaisesti tunnustaudutte Kristuksen evankeliumiin ja näin vilpittömästi olette ruvenneet yhteyteen heidän kanssaan ja kaikkien kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 14, 'Ja hekin rukoilevat teidän edestänne ja ikävöivät teitä sen ylen runsaan Jumalan armon tähden, joka on teidän osaksenne tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 9, 15, 'Kiitos Jumalalle hänen sanomattomasta lahjastaan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 1, 'Minä, Paavali, itse kehoitan teitä Kristuksen laupeuden ja lempeyden kautta, minä, joka olen muka nöyrä kasvotusten teidän kanssanne, mutta poissa ollessani rohkea teitä kohtaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 2, 'ja pyydän, ettei minun, kun tulen teidän tykönne, tarvitsisi käyttää sitä rohkeutta, millä aion luottavaisesti uskaltaa käydä eräiden kimppuun, jotka ajattelevat meistä, aivan kuin vaeltaisimme lihan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 3, 'Vaikka me vaellammekin lihassa, emme kuitenkaan lihan mukaan sodi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 4, 'sillä meidän sota-aseemme eivät ole lihalliset, vaan ne ovat voimalliset Jumalan edessä hajottamaan maahan linnoituksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 5, 'Me hajotamme maahan järjen päätelmät ja jokaisen varustuksen, joka nostetaan Jumalan tuntemista vastaan, ja vangitsemme jokaisen ajatuksen kuuliaiseksi Kristukselle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 6, 'ja olemme valmiit rankaisemaan kaikkea tottelemattomuutta, kunhan te ensin olette täysin kuuliaisiksi tulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 7, 'Nähkää, mitä silmäin edessä on. Jos joku on mielessään varma siitä, että hän on Kristuksen oma, ajatelkoon hän edelleen mielessään, että samoin kuin hän on Kristuksen, samoin olemme mekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 8, 'Ja vaikka minä jonkun verran enemmänkin kerskaisin siitä vallastamme, jonka Herra on antanut teitä rakentaaksemme eikä kukistaaksemme, en ole häpeään joutuva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 9, 'Tämän minä sanon, ettei näyttäisi siltä, kuin peloittelisin teitä kirjeilläni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 10, 'Sillä hänen kirjeensä ovat, sanotaan, kyllä mahtavat ja pontevat, mutta ruumiillisesti läsnäollessaan hän on heikko, eikä hänen puheensa ole minkään arvoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 11, 'Joka niin sanoo, ajatelkoon, että samaa, mitä me poissaolevina olemme kirjeissämme sanoissa, samaa me myös olemme läsnäolevina teoissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 12, 'Sillä me emme rohkene lukeutua emmekä verrata itseämme eräisiin, jotka itseänsä suosittelevat; mutta he ovat ymmärtämättömiä, kun mittaavat itsensä omalla itsellään ja vertailevat itseään omaan itseensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 13, 'Me taas emme rupea kerskaamaan yli määrän, vaan ainoastaan sen määrätyn vaikutusalan mukaan, minkä Jumala on asettanut meille määräksi, ulottuaksemme teihinkin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 14, 'Sillä me emme kurota itseämme liiaksi, ikäänkuin emme teihin ulottuisikaan, sillä olemmehan ehtineet Kristuksen evankeliumin julistamisessa teihinkin asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 15, 'Emme kerskaa yli määrän, emme muiden vaivannäöistä, mutta meillä on se toivo, että teidän uskonne lisääntyessä me oman vaikutusalamme mukaan kasvamme teidän keskuudessanne niin suuriksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 16, 'että saamme viedä evankeliumin myöskin tuolla puolen teitä oleviin maihin-tahtomatta kerskata siitä, mikä jo on valmista toisten vaikutusalalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 17, 'Mutta joka kerskaa, hänen kerskauksenaan olkoon Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 10, 18, 'Sillä ei se ole koetuksen kestävä, joka itse itseään suosittelee, vaan se, jota Herra suosittelee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 1, 'Jospa kärsisitte minulta hiukan mielettömyyttäkin! Ja kyllähän te minua kärsittekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 2, 'Sillä minä kiivailen teidän puolestanne Jumalan kiivaudella; minähän olen kihlannut teidät miehelle, yhdelle ainoalle, asettaakseni Kristuksen eteen puhtaan neitsyen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 3, 'Mutta minä pelkään, että niinkuin käärme kavaluudellaan petti Eevan, niin teidän mielenne ehkä turmeltuu pois vilpittömyydestä ja puhtaudesta, joka teissä on Kristusta kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 4, 'Sillä jos joku tulee ja saarnaa jotakin toista Jeesusta kuin sitä, jota me olemme saarnanneet, tai jos te saatte toisen hengen, kuin minkä olette saaneet, tai toisen evankeliumin, kuin minkä olette vastaanottaneet, niin sen te hyvin kärsitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 5, 'Mutta minä en katso itseäni missään suhteessa noita isoisia apostoleja huonommaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 6, 'Jos olenkin oppimaton puheessa, en kuitenkaan tiedossa; olemmehan tuoneet sen teille kaikin tavoin ilmi kaikissa asioissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 7, 'Vai olenko tehnyt syntiä siinä, että-alentaessani itseni, jotta te ylenisitte-olen ilmaiseksi julistanut teille Jumalan evankeliumia?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 8, 'Muita seurakuntia minä riistin, ottaessani heiltä palkkaa palvellakseni teitä. Kun olin teidän luonanne ja kärsin puutetta, en rasittanut ketään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 9, 'Sillä mitä minulta puuttui, sen täyttivät veljet, jotka tulivat Makedoniasta; ja kaikessa minä varoin olemasta teille rasitukseksi, ja olen vastakin varova.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 10, 'Niin totta kuin Kristuksen totuus on minussa, ei tätä kerskausta minulta riistetä Akaian maanäärissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 11, 'Minkätähden? Senkötähden, etten muka rakasta teitä? Jumala tietää sen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 12, 'Mutta mitä minä teen, sen olen vastakin tekevä, riistääkseni aiheen niiltä, jotka aihetta etsivät, että heidät siinä, missä kerskaavat, havaittaisiin samankaltaisiksi kuin mekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 13, 'Sillä semmoiset ovat valheapostoleja, petollisia työntekijöitä, jotka tekeytyvät Kristuksen apostoleiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 14, 'Eikä ihme; sillä itse saatana tekeytyy valkeuden enkeliksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 15, 'Ei ole siis paljon, jos hänen palvelijansakin tekeytyvät vanhurskauden palvelijoiksi, mutta heidän loppunsa on oleva heidän tekojensa mukainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 16, 'Vielä minä sanon: älköön kukaan luulko minua mielettömäksi; mutta vaikka olisinkin, ottakaa minut mieletönnäkin vastaan, että minäkin saisin hiukan kerskata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 17, 'Mitä nyt puhun, kun näin suurella luottamuksella kerskaan, sitä en puhu Herran mielen mukaan, vaan niinkuin mieletön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 18, 'Koska niin monet kerskaavat lihan mukaan, niin kerskaan minäkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 19, 'Tehän hyvin suvaitsette mielettömiä, kun itse olette niin mieleviä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 20, 'Tehän suvaitsette, että joku teidät orjuuttaa, että joku teidät syö puhtaaksi, että joku teidät saa saaliiksensa, että joku itsensä korottaa, että joku lyö teitä kasvoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 21, 'Häpeäkseni sanon: tähän me kyllä olemme olleet liian heikkoja. Mutta minkä joku toinen uskaltaa-puhun kuin mieletön-sen uskallan minäkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 22, 'He ovat hebrealaisia; minä myös. He ovat israelilaisia; minä myös. He ovat Aabrahamin siementä; minä myös.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 23, 'He ovat Kristuksen palvelijoita-puhun kuin mieltä vailla-minä vielä enemmän. Olen nähnyt vaivaa enemmän, olen ollut useammin vankeudessa, minua on ruoskittu ylen paljon, olen monta kertaa ollut kuoleman vaarassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 24, 'Juutalaisilta olen viidesti saanut neljäkymmentä lyöntiä, yhtä vaille;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 25, 'kolmesti olen saanut raippoja, kerran minua kivitettiin, kolmesti olen joutunut haaksirikkoon, vuorokauden olen meressä ajelehtinut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 26, 'olen usein ollut matkoilla, vaaroissa virtojen vesillä, vaaroissa rosvojen keskellä, vaaroissa heimoni puolelta, vaaroissa pakanain puolelta, vaaroissa kaupungeissa, vaaroissa erämaassa, vaaroissa merellä, vaaroissa valheveljien keskellä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 27, 'ollut työssä ja vaivassa; paljon valvonut, kärsinyt nälkää ja janoa, paljon paastonnut, kärsinyt vilua ja alastomuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 28, 'Ja kaiken muun lisäksi jokapäiväistä tunkeilua luonani, huolta kaikista seurakunnista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 29, 'Kuka on heikko, etten minäkin olisi heikko? Kuka lankeaa, ettei se minua polttaisi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 30, 'Jos minun kerskata täytyy, niin kerskaan heikkoudestani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 31, 'Herran Jeesuksen Jumala ja Isä, joka on ylistetty iankaikkisesti, tietää, etten valhettele.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 32, 'Damaskossa kuningas Aretaan käskynhaltija vartioi damaskolaisten kaupunkia ottaaksensa minut kiinni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 11, 33, 'ja muurin ikkuna-aukosta minut laskettiin korissa maahan, ja niin minä pääsin hänen käsistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 1, 'Minun täytyy kerskata; se tosin ei ole hyödyllistä, mutta minä siirryn nyt näkyihin ja Herran ilmestyksiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 2, 'Tunnen miehen, joka on Kristuksessa: neljätoista vuotta sitten hänet temmattiin kolmanteen taivaaseen-oliko hän ruumiissaan, en tiedä, vai poissa ruumiista, en tiedä, Jumala sen tietää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 3, 'Ja minä tiedän, että tämä mies-oliko hän ruumiissaan vai poissa ruumiista, en tiedä, Jumala sen tietää-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 4, 'temmattiin paratiisiin ja kuuli sanomattomia sanoja, joita ihmisen ei ole lupa puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 5, 'Tästä miehestä minä kerskaan, mutta itsestäni en kerskaa, paitsi heikkoudestani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 6, 'Sillä jos tahtoisinkin kerskata, en olisi mieletön, sillä minä puhuisin totta; mutta minä pidättäydyn siitä, ettei kukaan ajattelisi minusta enempää, kuin mitä näkee minun olevan tai mitä hän minusta kuulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 7, 'Ja etten niin erinomaisten ilmestysten tähden ylpeilisi, on minulle annettu lihaani pistin, saatanan enkeli, rusikoimaan minua, etten ylpeilisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 8, 'Tämän tähden olen kolmesti rukoillut Herraa, että se erkanisi minusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 9, 'Ja hän sanoi minulle: \"Minun armossani on sinulle kyllin; sillä minun voimani tulee täydelliseksi heikkoudessa\". Sentähden minä mieluimmin kerskaan heikkoudestani, että Kristuksen voima asettuisi minuun asumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 10, 'Sentähden minä olen mielistynyt heikkouteen, pahoinpitelyihin, hätään, vainoihin, ahdistuksiin, Kristuksen tähden; sillä kun olen heikko, silloin minä olen väkevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 11, 'Olen joutunut mielettömyyksiin; te olette minut siihen pakottaneet. Minunhan olisi pitänyt saada suositusta teiltä, sillä en ole missään ollut noita isoisia apostoleja huonompi, vaikka en olekaan mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 12, 'Onhan apostolin tunnusteot teidän keskuudessanne tehty kaikella kestävyydellä, tunnusmerkeillä ja ihmeillä ja voimateoilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 13, 'Sillä missä muussa te olette jääneet muita seurakuntia vähemmälle kuin siinä, etten minä puolestani ole rasittanut teitä? Antakaa minulle anteeksi tämä vääryys.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 14, 'Katso, kolmannen kerran minä nyt olen valmis tulemaan teidän tykönne, enkä ole oleva teille rasitukseksi; sillä minä en etsi teidän omaanne, vaan teitä itseänne. Eiväthän lapset ole velvolliset kokoamaan tavaraa vanhemmilleen, vaan vanhemmat lapsilleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 15, 'Ja minä olen mielelläni uhraava kaikki, uhraava itsenikin, teidän sielujenne hyväksi. Senkötähden, että teitä näin suuresti rakastan, minä saan teiltä vähemmän vastarakkautta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 16, 'Olkoonpa niin, etten minä ole teitä rasittanut; mutta entä jos olen viekas ja olen kavaluudella kietonut teidät pauloihini!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 17, 'Olenkohan minä kenenkään kautta, joita olen luoksenne lähettänyt, pyrkinyt teistä hyötymään?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 18, 'Kehoitin Tiitusta menemään ja lähetin veljen hänen kanssaan; ei kai Tiitus ole pyrkinyt teistä hyötymään? Emmekö ole vaeltaneet samassa hengessä? Emmekö samoja jälkiä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 19, 'Olette kai jo kauan sitten luulleet, että me puolustaudumme teidän edessänne. Jumalan edessä, Kristuksessa me puhumme; mutta kaikki teille rakennukseksi, rakkaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 20, 'Sillä minä pelkään, että tullessani ehkä en tapaa teitä semmoisina, kuin tahdon, ja että te tapaatte minut semmoisena, kuin te ette tahdo. Minä pelkään, että teidän keskuudessanne ehkä on riitaa, kateutta, vihaa, juonia, panetteluja, juoruja, pöyhkeilyä, epäjärjestyksiä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 12, 21, 'ja että, kun tulen, Jumalani on taas nöyryyttävä minua teidän tykönänne, ja että joudun suremaan monen tähden, jotka ennen ovat synnissä eläneet eivätkä ole katuneet sitä saastaisuutta ja haureutta ja irstautta, jota ovat harjoittaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 1, 'Kolmannen kerran minä nyt tulen teidän tykönne. Kahden tai kolmen todistajan sanalla on jokainen asia vahvistettava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 2, 'Olen edeltäpäin sanonut ja sanon edeltäpäin niille, jotka ennen ovat syntiä tehneet, ja kaikille muille-niinkuin silloin sanoin, kun olin toista kertaa tykönänne, samoin nytkin, kun olen poissa-etten, kun taas tulen, ole teitä säästävä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 3, 'koska te etsitte todistetta siitä, että minussa puhuu Kristus, joka ei ole heikko teitä kohtaan, vaan on teissä voimallinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 4, 'Sillä vaikka hänet ristiinnaulittiin, kun hän oli heikko, elää hän kuitenkin Jumalan voimasta; olemmehan mekin hänessä heikot, mutta me elämme hänen kanssaan Jumalan voimasta teitä kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 5, 'Koetelkaa itseänne, oletteko uskossa; tutkikaa itseänne. Vai ettekö tunne itseänne, että Jeesus Kristus on teissä? Ellei, niin ette kestä koetusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 6, 'Minä toivon teidän tulevan tuntemaan, että me emme ole niitä, jotka eivät koetusta kestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 7, 'Mutta me rukoilemme Jumalaa, ettette tekisi mitään pahaa, emme sitä varten, että näyttäisi siltä, kuin me olisimme koetuksen kestäviä, vaan että te tekisitte hyvää ja me olisimme ikäänkuin ne, jotka eivät koetusta kestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 8, 'Sillä me emme voi mitään totuutta vastaan, vaan totuuden puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 9, 'Sillä me iloitsemme, kun me olemme heikot, mutta te olette voimalliset; sitä me rukoilemmekin, että te täydellisiksi tulisitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 10, 'Sentähden minä kirjoitan tämän poissa ollessani, ettei minun teidän luonanne ollessani tarvitsisi käyttää ankaruutta sen vallan nojalla, minkä Herra on minulle antanut rakentamiseksi, ei kukistamiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 11, 'Lopuksi, veljet, iloitkaa, tulkaa täydellisiksi, ottakaa vastaan kehoituksia, olkaa yhtä mieltä, eläkää sovussa, niin rakkauden ja rauhan Jumala on oleva teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 12, 'Tervehtikää toisianne pyhällä suunannolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 13, '{13:12} Kaikki pyhät lähettävät teille tervehdyksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 13, 14, '{13:13} Herran Jeesuksen Kristuksen armo ja Jumalan rakkaus ja Pyhän Hengen osallisuus olkoon kaikkien teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Paavali, apostoli, virkansa saanut, ei ihmisiltä eikä ihmisen kautta, vaan Jeesuksen Kristuksen kautta ja Isän Jumalan, joka on hänet kuolleista herättänyt,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'ja kaikki veljet, jotka ovat minun kanssani, Galatian seurakunnille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'joka antoi itsensä alttiiksi meidän syntiemme tähden, pelastaaksensa meidät nykyisestä pahasta maailmanajasta meidän Jumalamme ja Isämme tahdon mukaan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Hänen olkoon kunnia aina ja iankaikkisesti! Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Minua kummastuttaa, että te niin äkkiä käännytte hänestä, joka on kutsunut teidät Kristuksen armossa, pois toisenlaiseen evankeliumiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'joka kuitenkaan ei ole mikään toinen; on vain eräitä, jotka hämmentävät teitä ja tahtovat vääristellä Kristuksen evankeliumin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Mutta vaikka me, tai vaikka enkeli taivaasta julistaisi teille evankeliumia, joka on vastoin sitä, minkä me olemme teille julistaneet, hän olkoon kirottu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Niinkuin ennenkin olemme sanoneet, niin sanon nytkin taas: jos joku julistaa teille evankeliumia, joka on vastoin sitä, minkä te olette saaneet, hän olkoon kirottu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Ihmistenkö suosiota minä nyt etsin vai Jumalan? Tai ihmisillekö pyydän olla mieliksi? Jos minä vielä tahtoisin olla ihmisille mieliksi, en olisi Kristuksen palvelija.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Sillä minä teen teille tiettäväksi, veljet, että minun julistamani evankeliumi ei ole ihmisten mukaista;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'enkä minä olekaan sitä ihmisiltä saanut, eikä sitä ole minulle opetettu, vaan Jeesus Kristus on sen minulle ilmoittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Olettehan kuulleet minun entisestä vaelluksestani juutalaisuudessa, että minä ylenmäärin vainosin Jumalan seurakuntaa ja sitä hävitin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'ja että edistyin juutalaisuudessa pitemmälle kuin monet samanikäiset heimossani ja ylen innokkaasti kiivailin isieni perinnäissääntöjen puolesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Mutta kun hän, joka äitini kohdusta saakka on minut erottanut ja kutsunut armonsa kautta, näki hyväksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'ilmaista minussa Poikansa, että minä julistaisin evankeliumia hänestä pakanain seassa, niin minä heti alunpitäenkään en kysynyt neuvoa lihalta ja vereltä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'enkä lähtenyt ylös Jerusalemiin niiden luo, jotka ennen minua olivat apostoleja, vaan menin pois Arabiaan ja palasin taas takaisin Damaskoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Sitten, kolmen vuoden kuluttua, minä menin ylös Jerusalemiin tutustuakseni Keefaaseen ja jäin hänen tykönsä viideksitoista päiväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Mutta muita apostoleja minä en nähnyt; näin ainoastaan Jaakobin, Herran veljen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Ja mitä kirjoitan teille, katso, Jumalan kasvojen edessä minä sanon, etten valhettele.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Sitten menin Syyrian ja Kilikian paikkakuntiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Mutta olin kasvoiltani tuntematon Juudean seurakunnille, jotka ovat Kristuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'Heidän kuuloonsa oli vain tullut: \"Meidän entinen vainoojamme julistaa nyt sitä uskoa, jota hän ennen hävitti\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'ja he ylistivät Jumalaa minun tähteni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 1, 'Sitten, neljäntoista vuoden kuluttua, minä taas menin ylös Jerusalemiin Barnabaan kanssa ja otin Tiituksenkin mukaani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 2, 'Mutta minä menin sinne ilmestyksen johdosta ja esitin heille sen evankeliumin, jota julistan pakanain keskuudessa; esitin sen yksityisesti arvokkaimmille heistä, etten ehkä juoksisi tai olisi juossut turhaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 3, 'Mutta ei edes seuralaistani Tiitusta, joka oli kreikkalainen, pakotettu ympärileikkauttamaan itseänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 4, 'Noiden pariimme luikertaneiden valheveljien tähden, jotka orjuuttaakseen meitä olivat hiipineet vakoilemaan vapauttamme, mikä meillä on Kristuksessa Jeesuksessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 5, 'me emme hetkeksikään alistuneet antamaan heille myöten, että evankeliumin totuus säilyisi teidän keskuudessanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 6, 'Ja nuo, joita jonakin pidettiin-millaisia lienevät olleet, ei kuulu minuun; Jumala ei katso henkilöön-nuo arvossapidetyt eivät velvoittaneet minua mihinkään enempään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 7, 'vaan päinvastoin, kun näkivät, että minulle oli uskottu evankeliumin julistaminen ympärileikkaamattomille, samoin kuin Pietarille sen julistaminen ympärileikatuille-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 8, 'sillä hän, joka antoi Pietarille voimaa hänen apostolintoimeensa ympärileikattujen keskuudessa, antoi minullekin siihen voimaa pakanain keskuudessa-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 9, 'ja kun olivat tulleet tuntemaan sen armon, mikä oli minulle annettu, niin Jaakob ja Keefas ja Johannes, joita pidettiin pylväinä, antoivat minulle ja Barnabaalle yhteisen työn merkiksi kättä, mennäksemme, me pakanain keskuuteen ja he ympärileikattujen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 10, 'Meidän oli vain muistaminen köyhiä, ja juuri sitä minä olenkin ahkeroinut tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 11, 'Mutta kun Keefas tuli Antiokiaan, vastustin minä häntä vasten kasvoja, koska hän oli herättänyt suurta paheksumista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 12, 'Sillä ennenkuin Jaakobin luota oli tullut muutamia miehiä, oli hän syönyt yhdessä pakanain kanssa; mutta heidän tultuaan hän vetäytyi pois ja pysytteli erillään peläten ympärileikattuja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 13, 'ja hänen kanssaan lankesivat ulkokultaisuuteen muutkin juutalaiset, niin että heidän ulkokultaisuutensa tempasi mukaansa Barnabaankin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 14, 'Mutta kun minä näin, etteivät he vaeltaneet suoraan evankeliumin totuuden mukaan, sanoin minä Keefaalle kaikkien kuullen: \"Jos sinä, joka olet juutalainen, noudatat pakanain tapoja etkä juutalaisten, miksi sinä pakotat pakanoita noudattamaan juutalaisten tapoja?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 15, 'Me olemme luonnostamme juutalaisia, emmekä pakanasyntisiä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 16, 'mutta koska tiedämme, ettei ihminen tule vanhurskaaksi lain teoista, vaan uskon kautta Jeesukseen Kristukseen, niin olemme mekin uskoneet Kristukseen Jeesukseen tullaksemme vanhurskaiksi uskosta Kristukseen eikä lain teoista, koska ei mikään liha tule vanhurskaaksi lain teoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 17, 'Mutta jos meidät itsemmekin, pyrkiessämme vanhurskautumaan Kristuksessa, on havaittu syntisiksi, onko sitten Kristus synnin palvelija? Pois se!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 18, 'Sillä jos minä uudestaan rakennan sen, minkä olen hajottanut maahan, osoitan minä olevani lain rikkoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 19, 'Sillä minä olen lain kautta kuollut pois laista, elääkseni Jumalalle. Minä olen Kristuksen kanssa ristiinnaulittu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 20, 'ja minä elän, en enää minä, vaan Kristus elää minussa; ja minkä nyt elän lihassa, sen minä elän Jumalan Pojan uskossa, hänen, joka on rakastanut minua ja antanut itsensä minun edestäni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 2, 21, 'En minä tee mitättömäksi Jumalan armoa, sillä jos vanhurskaus on saatavissa lain kautta, silloinhan Kristus on turhaan kuollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 1, 'Oi te älyttömät galatalaiset! Kuka on lumonnut teidät, joiden silmäin eteen Jeesus Kristus oli kuvattu ristiinnaulittuna?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 2, 'Tämän vain tahdon saada teiltä tietää: lain teoistako saitte Hengen vai uskossa kuulemisesta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 3, 'Niinkö älyttömiä olette? Te alotitte Hengessä, lihassako nyt lopetatte?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 4, 'Niin paljonko olette turhaan kärsineet? -jos se on turhaa ollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 5, 'Joka siis antaa teille Hengen ja tekee voimallisia tekoja teidän keskuudessanne, saako hän sen aikaan lain tekojen vai uskossa kuulemisen kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 6, 'samalla tavalla kuin \"Aabraham uskoi Jumalaa, ja se luettiin hänelle vanhurskaudeksi\"?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 7, 'Tietäkää siis, että ne, jotka uskoon perustautuvat, ovat Aabrahamin lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 8, 'Ja koska Raamattu edeltäpäin näki, että Jumala vanhurskauttaa pakanat uskosta, julisti se Aabrahamille edeltäpäin tämän hyvän sanoman: \"Sinussa kaikki kansat tulevat siunatuiksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 9, 'Niinmuodoin ne, jotka perustautuvat uskoon, siunataan uskovan Aabrahamin kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 10, 'Sillä kaikki, jotka perustautuvat lain tekoihin, ovat kirouksen alaisia; sillä kirjoitettu on: \"Kirottu olkoon jokainen, joka ei pysy kaikessa, mikä on kirjoitettuna lain kirjassa, niin että hän sen tekee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 11, 'Ja selvää on, ettei kukaan tule vanhurskaaksi Jumalan edessä lain kautta, koska \"vanhurskas on elävä uskosta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 12, 'Mutta laki ei perustaudu uskoon, vaan: \"Joka ne täyttää, on niistä elävä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 13, 'Kristus on lunastanut meidät lain kirouksesta, kun hän tuli kiroukseksi meidän edestämme-sillä kirjoitettu on: \"Kirottu on jokainen, joka on puuhun ripustettu\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 14, 'että Aabrahamin siunaus tulisi Jeesuksessa Kristuksessa pakanain osaksi ja me niin uskon kautta saisimme luvatun Hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 15, 'Veljet, minä puhun ihmisten tavalla. Eihän kukaan voi kumota ihmisenkään vahvistettua testamenttia eikä siihen mitään lisätä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 16, 'Mutta nyt lausuttiin lupaukset Aabrahamille ja hänen siemenelleen. Hän ei sano: \"Ja siemenille\", ikäänkuin monesta, vaan ikäänkuin yhdestä: \"Ja sinun siemenellesi\", joka on Kristus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 17, 'Minä tarkoitan tätä: Jumalan ennen vahvistamaa testamenttia ei neljänsadan kolmenkymmenen vuoden perästä tullut laki voi kumota, niin että se tekisi lupauksen mitättömäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 18, 'Sillä jos perintö tulisi laista, niin se ei enää tulisikaan lupauksesta. Mutta Aabrahamille Jumala on sen lahjoittanut lupauksen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 19, 'Mitä varten sitten on laki? Se on rikkomusten tähden jäljestäpäin lisätty olemaan siihen asti, kunnes oli tuleva se siemen, jolle lupaus oli annettu; ja se säädettiin enkelien kautta, välimiehen kädellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 20, 'Välimies taas ei ole yhtä varten; mutta Jumala on yksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 21, 'Onko sitten laki vastoin Jumalan lupauksia? Pois se! Sillä jos olisi annettu laki, joka voisi eläväksi tehdä, niin vanhurskaus todella tulisi laista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 22, 'Mutta Raamattu on sulkenut kaikki synnin alle, että se, mikä luvattu oli, annettaisiin uskosta Jeesukseen Kristukseen niille, jotka uskovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 23, 'Mutta ennenkuin usko tuli, vartioitiin meitä lain alle suljettuina uskoa varten, joka oli vastedes ilmestyvä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 24, 'Niinmuodoin on laista tullut meille kasvattaja Kristukseen, että me uskosta vanhurskaiksi tulisimme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 25, 'Mutta uskon tultua me emme enää ole kasvattajan alaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 26, 'Sillä te olette kaikki uskon kautta Jumalan lapsia Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 27, 'Sillä kaikki te, jotka olette Kristukseen kastetut, olette Kristuksen päällenne pukeneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 28, 'Ei ole tässä juutalaista eikä kreikkalaista, ei ole orjaa eikä vapaata, ei ole miestä eikä naista; sillä kaikki te olette yhtä Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 3, 29, 'Mutta jos te olette Kristuksen omat, niin te siis olette Aabrahamin siementä, perillisiä lupauksen mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 1, 'Mutta minä sanon: niin kauan kuin perillinen on alaikäinen, ei hän missään kohden eroa orjasta, vaikka hän onkin kaiken herra;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 2, 'vaan hän on holhoojain ja huoneenhaltijain alainen isän määräämään aikaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 3, 'Samoin mekin; kun olimme alaikäisiä, olimme orjuutetut maailman alkeisvoimien alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 4, 'Mutta kun aika oli täytetty, lähetti Jumala Poikansa, vaimosta syntyneen, lain alaiseksi syntyneen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 5, 'lunastamaan lain alaiset, että me pääsisimme lapsen asemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 6, 'Ja koska te olette lapsia, on Jumala lähettänyt meidän sydämeemme Poikansa Hengen, joka huutaa: \"Abba! Isä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 7, 'Niinpä sinä et siis enää ole orja, vaan lapsi; mutta jos olet lapsi, olet myös perillinen Jumalan kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 8, 'Mutta silloin, kun ette tunteneet Jumalaa, te palvelitte jumalia, jotka luonnostaan eivät jumalia ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 9, 'Nyt sitävastoin, kun olette tulleet tuntemaan Jumalan ja, mikä enemmän on, kun Jumala tuntee teidät, kuinka te jälleen käännytte noiden heikkojen ja köyhien alkeisvoimien puoleen, joiden orjiksi taas uudestaan tahdotte tulla?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 10, 'Te otatte vaarin päivistä ja kuukausista ja juhla-ajoista ja vuosista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 11, 'Minä pelkään teidän tähtenne, että olen ehkä turhaan teistä vaivaa nähnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 12, 'Tulkaa minun kaltaisikseni, koska minäkin olen tullut teidän kaltaiseksenne, veljet, minä pyydän sitä teiltä. Ette ole minua mitenkään loukanneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 13, 'Tiedättehän, että ruumiillinen heikkous oli syynä siihen, että minä ensi kerralla julistin teille evankeliumia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 14, 'ja tiedätte, mikä kiusaus teillä oli minun ruumiillisesta tilastani; ette minua halveksineet ettekä vieroneet, vaan otitte minut vastaan niinkuin Jumalan enkelin, jopa niinkuin Kristuksen Jeesuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 15, 'Missä on nyt teiltä kerskaaminen onnestanne? Sillä minä annan teistä sen todistuksen, että te, jos se olisi ollut mahdollista, olisitte kaivaneet silmät päästänne ja antaneet minulle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 16, 'Onko minusta siis tullut teidän vihamiehenne sentähden, että minä puhun teille totuuden?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 17, 'Heillä on intoa teidän hyväksenne, mutta ei oikeata; vaan he tahtovat eristää teidät, että teillä olisi intoa heidän hyväksensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 18, 'On hyvä, jos osoitetaan intoa hyvässä asiassa aina, eikä ainoastaan silloin, kun minä olen teidän tykönänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 19, 'Lapsukaiseni, jotka minun jälleen täytyy kivulla synnyttää, kunnes Kristus saa muodon teissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 20, 'tahtoisinpa nyt olla teidän tykönänne ja äänenikin muuttaa! Sillä minä olen aivan ymmällä teistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 21, 'Sanokaa minulle te, jotka tahdotte lain alaisia olla, ettekö kuule, mitä laki sanoo?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 22, 'Onhan kirjoitettu, että Aabrahamilla oli kaksi poikaa, toinen orjattaresta, toinen vapaasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 23, 'Mutta orjattaren poika oli syntynyt lihan mukaan, vapaan taas lupauksen voimasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 24, 'Tämä on kuvannollista puhetta; nämä naiset ovat kaksi liittoa: toinen on Siinain vuorelta, joka synnyttää orjuuteen, ja se on Haagar;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 25, 'sillä Haagar on Siinain vuori Arabiassa ja vastaa nykyistä Jerusalemia, joka elää orjuudessa lapsineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 26, 'Mutta se Jerusalem, joka ylhäällä on, on vapaa, ja se on meidän äitimme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 27, 'Sillä kirjoitettu on: \"Iloitse, sinä hedelmätön, joka et synnytä, riemahda ja huuda sinä, jolla ei ole synnytyskipuja. Sillä yksinäisellä on paljon lapsia, enemmän kuin sillä, jolla on mies.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 28, 'Ja te, veljet, olette lupauksen lapsia, niinkuin Iisak oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 29, 'Mutta niinkuin lihan mukaan syntynyt silloin vainosi Hengen mukaan syntynyttä, niin nytkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 30, 'Mutta mitä sanoo Raamattu? \"Aja pois orjatar poikinensa; sillä orjattaren poika ei saa periä vapaan vaimon pojan kanssa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 4, 31, 'Niin me siis, veljet, emme ole orjattaren lapsia, vaan vapaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 1, 'Vapauteen Kristus vapautti meidät. Pysykää siis lujina, älkääkä antako uudestaan sitoa itseänne orjuuden ikeeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 2, 'Katso, minä, Paavali, sanon teille, että jos ympärileikkautatte itsenne, niin Kristus ei ole oleva teille miksikään hyödyksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 3, 'Ja minä todistan taas jokaiselle ihmiselle, joka ympärileikkauttaa itsensä, että hän on velvollinen täyttämään kaiken lain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 4, 'Te olette joutuneet pois Kristuksesta, te, jotka tahdotte lain kautta tulla vanhurskaiksi; te olette langenneet pois armosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 5, 'Sillä me odotamme uskosta vanhurskauden toivoa Hengen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 6, 'Sillä Kristuksessa Jeesuksessa ei auta ympärileikkaus eikä ympärileikkaamattomuus, vaan rakkauden kautta vaikuttava usko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 7, 'Te juoksitte hyvin; kuka esti teitä olemasta totuudelle kuuliaisia?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 8, 'Houkutus siihen ei ole hänestä, joka teitä kutsuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 9, 'Vähäinen hapatus hapattaa koko taikinan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 10, 'Minulla on teihin se luottamus Herrassa, että te ette missään kohden tule ajattelemaan toisin; mutta teidän häiritsijänne saa kantaa tuomionsa, olkoon kuka hyvänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 11, 'Mutta jos minä, veljet, vielä saarnaan ympärileikkausta, miksi minua vielä vainotaan? Silloinhan olisi ristin pahennus poistettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 12, 'Kunpa aivan silpoisivat itsensä, nuo teidän kiihoittajanne!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 13, 'Te olette näet kutsutut vapauteen, veljet; älkää vain salliko vapauden olla yllykkeeksi lihalle, vaan palvelkaa toisianne rakkaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 14, 'Sillä kaikki laki on täytetty yhdessä käskysanassa, tässä: \"Rakasta lähimmäistäsi niinkuin itseäsi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 15, 'Mutta jos te purette ja syötte toisianne, katsokaa, ettette toinen toistanne perin hävitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 16, 'Minä sanon: vaeltakaa Hengessä, niin ette lihan himoa täytä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 17, 'Sillä liha himoitsee Henkeä vastaan, ja Henki lihaa vastaan; nämä ovat nimittäin toisiansa vastaan, niin että te ette tee sitä, mitä tahdotte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 18, 'Mutta jos te olette Hengen kuljetettavina, niin ette ole lain alla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 19, 'Mutta lihan teot ovat ilmeiset, ja ne ovat: haureus, saastaisuus, irstaus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 20, 'epäjumalanpalvelus, noituus, vihamielisyys, riita, kateellisuus, vihat, juonet, eriseurat, lahkot,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 21, 'kateus, juomingit, mässäykset ja muut senkaltaiset, joista teille edeltäpäin sanon, niinkuin jo ennenkin olen sanonut, että ne, jotka semmoista harjoittavat, eivät peri Jumalan valtakuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 22, 'Mutta Hengen hedelmä on rakkaus, ilo, rauha, pitkämielisyys, ystävällisyys, hyvyys, uskollisuus, sävyisyys, itsensähillitseminen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 23, 'Sellaista vastaan ei ole laki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 24, 'Ja ne, jotka ovat Kristuksen Jeesuksen omat, ovat ristiinnaulinneet lihansa himoineen ja haluineen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 25, 'Jos me Hengessä elämme, niin myös Hengessä vaeltakaamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 5, 26, 'Älkäämme olko turhan kunnian pyytäjiä, niin että toisiamme ärsyttelemme, toisiamme kadehdimme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 1, 'Veljet, jos joku tavataan jostakin rikkomuksesta, niin ojentakaa te, hengelliset, häntä sävyisyyden hengessä; ja ole varuillasi, ettet sinäkin joutuisi kiusaukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 2, 'Kantakaa toistenne kuormia, ja niin te täytätte Kristuksen lain.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 3, 'Sillä jos joku luulee jotakin olevansa, vaikka ei ole mitään, niin hän pettää itsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 4, 'Mutta tutkikoon kukin omat tekonsa, ja silloin hänen kerskaamisensa on vain siinä, mitä hän itse on, ei siinä, mitä toinen on;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 5, 'sillä kunkin on kannettava oma taakkansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 6, 'Jolle sanaa opetetaan, se jakakoon kaikkea hyvää opettajallensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 7, 'Älkää eksykö, Jumala ei salli itseänsä pilkata; sillä mitä ihminen kylvää, sitä hän myös niittää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 8, 'Joka lihaansa kylvää, se lihasta turmeluksen niittää; mutta joka Henkeen kylvää, se Hengestä iankaikkisen elämän niittää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 9, 'Ja kun hyvää teemme, älkäämme lannistuko, sillä me saamme ajan tullen niittää, jos emme väsy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 10, 'Sentähden, kun meillä vielä aikaa on, tehkäämme hyvää kaikille, mutta varsinkin uskonveljille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 11, 'Katsokaa, kuinka suurilla kirjaimilla minä omakätisesti teille kirjoitan!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 12, 'Kaikki, jotka pyrkivät lihassa olemaan mieliksi, ne pakottavat teitä ympärileikkauttamaan itsenne vain siksi, ettei heitä Kristuksen ristin tähden vainottaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 13, 'Eiväthän nekään, jotka ympärileikkauttavat itsensä, itse noudata lakia, vaan he tahtovat teitä ympärileikkauttamaan itsenne saadakseen kerskata teidän lihastanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 14, 'Mutta pois se minusta, että minä muusta kerskaisin kuin meidän Herramme Jeesuksen Kristuksen rististä, jonka kautta maailma on ristiinnaulittu minulle, ja minä maailmalle!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 15, 'Sillä ei ympärileikkaus ole mitään eikä ympärileikkaamattomuus, vaan uusi luomus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 16, 'Ja kaikille, jotka tämän säännön mukaan vaeltavat, kaikille heille rauha ja laupeus, ja Jumalan Israelille!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 17, 'Älköön tästedes kukaan minulle vaivoja tuottako; sillä minä kannan Jeesuksen arvet ruumiissani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 6, 18, 'Meidän Herramme Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa, veljet. Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Paavali, Jumalan tahdosta Kristuksen Jeesuksen apostoli, sossa oleville pyhille ja uskoville Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Ylistetty olkoon meidän Herramme Jeesuksen Kristuksen Jumala ja Isä, joka on siunannut meitä taivaallisissa kaikella hengellisellä siunauksella Kristuksessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'niinkuin hän ennen maailman perustamista oli hänessä valinnut meidät olemaan pyhät ja nuhteettomat hänen edessään, rakkaudessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'edeltäpäin määräten meidät lapseuteen, hänen yhteyteensä Jeesuksen Kristuksen kautta, hänen oman tahtonsa mielisuosion mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'sen armonsa kirkkauden kiitokseksi, minkä hän on lahjoittanut meille siinä rakastetussa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'jossa meillä on lunastus hänen verensä kautta, rikkomusten anteeksisaaminen, hänen armonsa rikkauden mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Tätä armoa hän on ylenpalttisesti antanut meille kaikkinaiseksi viisaudeksi ja ymmärrykseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'tehden meille tiettäväksi sen tahtonsa salaisuuden, että hän, päätöksensä mukaan, jonka hän oli nähnyt hyväksi itsessään tehdä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'siitä armotaloudesta, minkä hän aikojen täyttyessä aikoi toteuttaa, -oli yhdistävä Kristuksessa yhdeksi kaikki, mitä on taivaissa ja mitä on maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'Hänessä me myös olemme saaneet perintöosan, ollen siihen edeltämäärätyt hänen aivoituksensa mukaan, hänen, joka vaikuttaa kaikki oman tahtonsa päättämän mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'että me olisimme hänen kirkkautensa kiitokseksi, me, jotka jo edeltä olimme panneet toivomme Kristukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'Hänessä on teihinkin, sittenkuin olitte kuulleet totuuden sanan, pelastuksenne evankeliumin, uskoviksi tultuanne pantu luvatun Pyhän Hengen sinetti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'sen, joka on meidän perintömme vakuutena, hänen omaisuutensa lunastamiseksi-hänen kirkkautensa kiitokseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Sentähden, kun kuulin siitä uskosta, joka teillä on Herrassa Jeesuksessa, ja teidän rakkaudestanne kaikkia pyhiä kohtaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'en minäkään lakkaa kiittämästä teidän tähtenne, kun muistelen teitä rukouksissani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'anoen, että meidän Herramme Jeesuksen Kristuksen Jumala, kirkkauden Isä, antaisi teille viisauden ja ilmestyksen Hengen hänen tuntemisessaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'ja valaisisi teidän sydämenne silmät, että tietäisitte, mikä on se toivo, johon hän on teidät kutsunut, kuinka suuri hänen perintönsä kirkkaus hänen pyhissään');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'ja mikä hänen voimansa ylenpalttinen suuruus meitä kohtaan, jotka uskomme-sen hänen väkevyytensä voiman vaikutuksen mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'jonka hän vaikutti Kristuksessa, kun hän herätti hänet kuolleista ja asetti hänet oikealle puolellensa taivaissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 21, 'korkeammalle kaikkea hallitusta ja valtaa ja voimaa ja herrautta ja jokaista nimeä, mikä mainitaan, ei ainoastaan tässä maailmanajassa, vaan myös tulevassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 22, 'Ja kaikki hän on asettanut hänen jalkainsa alle ja antanut hänet kaiken pääksi seurakunnalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 23, 'joka on hänen ruumiinsa, hänen täyteytensä, joka kaikki kaikissa täyttää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Ja Jumala on eläviksi tehnyt teidät, jotka olitte kuolleet rikoksiinne ja synteihinne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'joissa te ennen vaelsitte tämän maailman menon mukaan, ilmavallan hallitsijan, sen hengen hallitsijan, mukaan, joka nyt tekee työtään tottelemattomuuden lapsissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'joiden joukossa mekin kaikki ennen vaelsimme lihamme himoissa, noudattaen lihan ja ajatusten mielitekoja, ja olimme luonnostamme vihan lapsia niinkuin muutkin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'mutta Jumala, joka on laupeudesta rikas, suuren rakkautensa tähden, jolla hän on meitä rakastanut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'on tehnyt meidät, jotka olimme kuolleet rikoksiimme, eläviksi Kristuksen kanssa-armosta te olette pelastetut-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'ja yhdessä hänen kanssaan herättänyt ja yhdessä hänen kanssaan asettanut meidät taivaallisiin Kristuksessa Jeesuksessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'osoittaakseen tulevina maailmanaikoina armonsa ylenpalttista runsautta, hyvyydessään meitä kohtaan Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Sillä armosta te olette pelastetut uskon kautta, ette itsenne kautta-se on Jumalan lahja-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'ette tekojen kautta, ettei kukaan kerskaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Sillä me olemme hänen tekonsa, luodut Kristuksessa Jeesuksessa hyviä töitä varten, jotka Jumala on edeltäpäin valmistanut, että me niissä vaeltaisimme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Muistakaa sentähden, että te ennen, te lihanne puolesta pakanat, jotka olette saaneet ympärileikkaamattomien nimen niiltä, joita, lihaan käsillä tehdyn ympärileikkauksen mukaisesti, sanotaan ympärileikatuiksi-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'että te siihen aikaan olitte ilman Kristusta, olitte vailla Israelin kansalaisoikeutta ja vieraat lupauksen liitoille, ilman toivoa ja ilman Jumalaa maailmassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'mutta nyt, kun olette Kristuksessa Jeesuksessa, olette te, jotka ennen olitte kaukana, päässeet lähelle Kristuksen veressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Sillä hän on meidän rauhamme, hän, joka teki molemmat yhdeksi ja purki erottavan väliseinän, nimittäin vihollisuuden,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'kun hän omassa lihassaan teki tehottomaksi käskyjen lain säädöksinensä, luodakseen itsessänsä nuo kaksi yhdeksi uudeksi ihmiseksi, tehden rauhan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'ja yhdessä ruumiissa sovittaakseen molemmat Jumalan kanssa ristin kautta, kuolettaen itsensä kautta vihollisuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Ja hän tuli ja julisti rauhaa teille, jotka kaukana olitte, ja rauhaa niille, jotka lähellä olivat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'sillä hänen kauttansa on meillä molemmilla pääsy yhdessä Hengessä Isän tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Niin ette siis enää ole vieraita ettekä muukalaisia, vaan te olette pyhien kansalaisia ja Jumalan perhettä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'apostolien ja profeettain perustukselle rakennettuja, kulmakivenä itse Kristus Jeesus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'jossa koko rakennus liittyy yhteen ja kasvaa pyhäksi temppeliksi Herrassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'ja hänessä tekin yhdessä muitten kanssa rakennutte Jumalan asumukseksi Hengessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Sen takia minä, Paavali, teidän, pakanain, tähden Kristuksen Jeesuksen vanki, notkistan polveni-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'olette kaiketi kuulleet siitä Jumalan armon taloudenhoidosta, mikä on minulle teitä varten annettu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'että näet tämä salaisuus on ilmestyksen kautta tehty minulle tiettäväksi, niinkuin olen siitä edellä lyhyesti kirjoittanut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'josta te sitä lukiessanne voitte huomata, kuinka perehtynyt minä olen Kristuksen salaisuuteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'jota menneiden sukupolvien aikana ei ole ihmisten lapsille tiettäväksi tehty, niinkuin se nyt Hengessä on ilmoitettu hänen pyhille apostoleilleen ja profeetoille:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'että näet pakanatkin ovat kanssaperillisiä ja yhtä ruumista ja osallisia lupaukseen Kristuksessa Jeesuksessa evankeliumin kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'jonka palvelijaksi minä olen tullut Jumalan armon lahjan kautta, joka minulle on annettu hänen voimansa vaikutuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Minulle, kaikista pyhistä halvimmalle, on annettu tämä armo: julistaa pakanoille evankeliumia Kristuksen tutkimattomasta rikkaudesta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'ja saattaa kaikille ilmeiseksi, mitä on sen salaisuuden taloudenhoito, joka ikuisista ajoista asti on ollut kätkettynä Jumalassa, kaiken Luojassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'että Jumalan moninainen viisaus seurakunnan kautta nyt tulisi taivaallisten hallitusten ja valtojen tietoon');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'sen iankaikkisen aivoituksen mukaisesti, jonka hän oli säätänyt Kristuksessa Jeesuksessa, meidän Herrassamme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'jossa meillä, uskon kautta häneen, on uskallus ja luottavainen pääsy Jumalan tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Siksi minä pyydän, ettette lannistuisi niiden ahdistusten vuoksi, joita minä teidän tähtenne kärsin, sillä ne ovat teidän kunnianne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Sentähden minä notkistan polveni Isän edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'josta kaikki, millä isä on, taivaissa ja maan päällä, saa nimensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'että hän kirkkautensa runsauden mukaisesti antaisi teidän, sisällisen ihmisenne puolesta, voimassa vahvistua hänen Henkensä kautta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'ja Kristuksen asua uskon kautta teidän sydämissänne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'niin että te, rakkauteen juurtuneina ja perustuneina, voisitte kaikkien pyhien kanssa käsittää, mikä leveys ja pituus ja korkeus ja syvyys on,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'ja oppia tuntemaan Kristuksen rakkauden, joka on kaikkea tietoa ylempänä; että tulisitte täyteen Jumalan kaikkea täyteyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Mutta hänelle, joka voi tehdä enemmän, monin verroin enemmän kuin kaikki, mitä me anomme tai ymmärrämme, sen voiman mukaan, joka meissä vaikuttaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'hänelle kunnia seurakunnassa ja Kristuksessa Jeesuksessa kautta kaikkien sukupolvien, aina ja iankaikkisesti! Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Niin kehoitan siis minä, joka olen vankina Herrassa, teitä vaeltamaan, niinkuin saamanne kutsumuksen arvo vaatii,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'kaikessa nöyryydessä ja hiljaisuudessa ja pitkämielisyydessä kärsien toinen toistanne rakkaudessa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'ja pyrkien säilyttämään hengen yhteyden rauhan yhdyssiteellä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'yksi ruumis ja yksi henki, niinkuin te olette kutsututkin yhteen ja samaan toivoon, jonka te kutsumuksessanne saitte;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'yksi Herra, yksi usko, yksi kaste;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'yksi Jumala ja kaikkien Isä, joka on yli kaikkien ja kaikkien kautta ja kaikissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Mutta itsekullekin meistä on armo annettu Kristuksen lahjan mitan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Sentähden on sanottu: \"Hän astui ylös korkeuteen, hän otti vankeja saaliikseen, hän antoi lahjoja ihmisille\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Mutta että hän astui ylös, mitä se on muuta, kuin että hän oli astunut alaskin, maan alimpiin paikkoihin?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Hän, joka on astunut alas, on se, joka myös astui ylös, kaikkia taivaita ylemmäksi, täyttääkseen kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Ja hän antoi muutamat apostoleiksi, toiset profeetoiksi, toiset evankelistoiksi, toiset paimeniksi ja opettajiksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 12, 'tehdäkseen pyhät täysin valmiiksi palveluksen työhön, Kristuksen ruumiin rakentamiseen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 13, 'kunnes me kaikki pääsemme yhteyteen uskossa ja Jumalan Pojan tuntemisessa, täyteen miehuuteen, Kristuksen täyteyden täyden iän määrään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 14, 'ettemme enää olisi alaikäisiä, jotka ajelehtivat ja joita viskellään kaikissa opintuulissa ja ihmisten arpapelissä ja eksytyksen kavalissa juonissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 15, 'vaan että me, totuutta noudattaen rakkaudessa, kaikin tavoin kasvaisimme häneen, joka on pää, Kristus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 16, 'josta koko ruumis, yhteen liitettynä ja koossa pysyen jokaisen jänteensä avulla, kasvaa rakentuakseen rakkaudessa sen voiman määrän mukaan, mikä kullakin osalla on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 17, 'Sen minä siis sanon ja varoitan Herrassa: älkää enää vaeltako, niinkuin pakanat vaeltavat mielensä turhuudessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 18, 'nuo, jotka, pimentyneinä ymmärrykseltään ja vieraantuneina Jumalan elämästä heissä olevan tietämättömyyden tähden ja sydämensä paatumuksen tähden,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 19, 'ovat päästäneet tuntonsa turtumaan ja heittäytyneet irstauden valtaan, harjoittamaan kaikkinaista saastaisuutta, ahneudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 20, 'Mutta näin te ette ole oppineet Kristusta tuntemaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 21, 'jos muutoin olette hänestä kuulleet ja hänessä opetusta saaneet, niinkuin totuus on Jeesuksessa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 22, 'että teidän tulee panna pois vanha ihmisenne, jonka mukaan te ennen vaelsitte ja joka turmelee itsensä petollisia himoja seuraten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 23, 'ja uudistua mielenne hengeltä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 24, 'ja pukea päällenne uusi ihminen, joka Jumalan mukaan on luotu totuuden vanhurskauteen ja pyhyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 25, 'Pankaa sentähden pois valhe ja puhukaa totta, kukin lähimmäisensä kanssa, sillä me olemme toinen toisemme jäseniä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 26, '\"Vihastukaa, mutta älkää syntiä tehkö.\" Älkää antako auringon laskea vihanne yli,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 27, 'Älkääkä antako perkeleelle sijaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 28, 'Joka on varastanut, älköön enää varastako, vaan tehköön ennemmin työtä ja toimittakoon käsillään sitä, mikä hyvää on, että hänellä olisi, mitä antaa tarvitsevalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 29, 'Mikään rietas puhe älköön suustanne lähtekö, vaan ainoastaan sellainen, mikä on rakentavaista ja tarpeellista ja on mieluista niille, jotka kuulevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 30, 'Älkääkä saattako murheelliseksi Jumalan Pyhää Henkeä, joka on teille annettu sinetiksi lunastuksen päivään saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 31, 'Kaikki katkeruus ja kiivastus ja viha ja huuto ja herjaus, kaikki pahuus olkoon kaukana teistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 32, 'Olkaa sen sijaan toisianne kohtaan ystävällisiä, hyväsydämisiä, anteeksiantavaisia toinen toisellenne, niinkuin Jumalakin on Kristuksessa teille anteeksi antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Olkaa siis Jumalan seuraajia, niinkuin rakkaat lapset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'ja vaeltakaa rakkaudessa, niinkuin Kristuskin rakasti teitä ja antoi itsensä meidän edestämme lahjaksi ja uhriksi, Jumalalle \"suloiseksi tuoksuksi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Mutta haureutta ja minkäänlaista saastaisuutta tai ahneutta älköön edes mainittako teidän keskuudessanne-niinkuin pyhien sopii-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Älköön myös rivoutta tai tyhmää lorua tai ilvehtimistä, jotka ovat sopimattomia, vaan paremmin kiitosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Sillä sen te tiedätte ja tunnette, ettei yhdelläkään haureellisella eikä saastaisella eikä ahneella-sillä hän on epäjumalanpalvelija-ole perintöosaa Kristuksen ja Jumalan valtakunnassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Älköön kukaan pettäkö teitä tyhjillä puheilla, sillä semmoisten tähden kohtaa Jumalan viha tottelemattomuuden lapsia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Älkää siis olko niihin osallisia heidän kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Ennen te olitte pimeys, mutta nyt te olette valkeus Herrassa. Vaeltakaa valkeuden lapsina');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, '-sillä kaikkinainen hyvyys ja vanhurskaus ja totuus on valkeuden hedelmä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'ja tutkikaa, mikä on otollista Herralle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Älköönkä teillä olko mitään osallisuutta pimeyden hedelmättömiin tekoihin, vaan päinvastoin nuhdelkaakin niistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Sillä häpeällistä on jo sanoakin, mitä he salassa tekevät;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'mutta tämä kaikki tulee ilmi, kun valkeus sen paljastaa, sillä kaikki, mikä tulee ilmi, on valkeutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Sentähden sanotaan: \"Heräjä sinä, joka nukut, ja nouse kuolleista, niin Kristus sinua valaisee!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 15, 'Katsokaa siis tarkoin, kuinka vaellatte: ei niinkuin tyhmät, vaan niinkuin viisaat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 16, 'ja ottakaa vaari oikeasta hetkestä, sillä aika on paha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 17, 'Älkää sentähden olko mielettömät, vaan ymmärtäkää, mikä Herran tahto on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 18, 'Älkääkä juopuko viinistä, sillä siitä tulee irstas meno, vaan täyttykää Hengellä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 19, 'puhuen keskenänne psalmeilla ja kiitosvirsillä ja hengellisillä lauluilla, veisaten ja laulaen sydämessänne Herralle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 20, 'kiittäen aina Jumalaa ja Isää kaikesta meidän Herramme Jeesuksen Kristuksen nimessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 21, 'Ja olkaa toinen toisellenne alamaiset Kristuksen pelossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 22, 'Vaimot, olkaa omille miehillenne alamaiset niinkuin Herralle;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 23, 'sillä mies on vaimon pää, niinkuin myös Kristus on seurakunnan pää, hän, ruumiin vapahtaja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 24, 'Mutta niinkuin seurakunta on Kristukselle alamainen, niin olkoot vaimotkin miehillensä kaikessa alamaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 25, 'Miehet, rakastakaa vaimojanne, niinkuin Kristuskin rakasti seurakuntaa ja antoi itsensä alttiiksi sen edestä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 26, 'että hän sen pyhittäisi, puhdistaen sen, vedellä pesten, sanan kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 27, 'saadakseen asetetuksi eteensä kirkastettuna seurakunnan, jossa ei olisi tahraa eikä ryppyä eikä mitään muuta sellaista, vaan joka olisi pyhä ja nuhteeton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 28, 'Samalla tavoin tulee myös miesten rakastaa vaimojansa niinkuin omia ruumiitaan; joka rakastaa vaimoansa, hän rakastaa itseänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 29, 'Sillä eihän kukaan koskaan ole vihannut omaa lihaansa, vaan hän ravitsee ja vaalii sitä, niinkuin Kristuskin seurakuntaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 30, 'sillä me olemme hänen ruumiinsa jäseniä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 31, '\"Sentähden mies luopukoon isästänsä ja äidistänsä ja liittyköön vaimoonsa, ja ne kaksi tulevat yhdeksi lihaksi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 32, 'Tämä salaisuus on suuri; minä tarkoitan Kristusta ja seurakuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 33, 'Mutta myös teistä kukin kohdaltaan rakastakoon vaimoaan niinkuin itseänsä; mutta vaimo kunnioittakoon miestänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Lapset, olkaa vanhemmillenne kuuliaiset Herrassa, sillä se on oikein.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, '\"Kunnioita isääsi ja äitiäsi\" -tämä on ensimmäinen käsky, jota seuraa lupaus-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, '\"että menestyisit ja kauan eläisit maan päällä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Ja te isät, älkää kiihoittako lapsianne vihaan, vaan kasvattakaa heitä Herran kurissa ja nuhteessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Palvelijat, olkaa kuuliaiset maallisille isännillenne, pelossa ja vavistuksessa, sydämenne yksinkertaisuudessa, niinkuin Kristukselle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'ei silmänpalvelijoina, ihmisille mieliksi, vaan Kristuksen palvelijoina, sydämestänne tehden, mitä Jumala tahtoo,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'hyvällä mielellä palvellen, niinkuin palvelisitte Herraa ettekä ihmisiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'tietäen, että mitä hyvää kukin tekee, sen hän saa takaisin Herralta, olkoonpa orja tai vapaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Ja te isännät, tehkää samoin heille, jättäkää pois uhkaileminen, sillä tiedättehän, että sekä heidän että teidän Herranne on taivaissa ja ettei hän katso henkilöön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Lopuksi, vahvistukaa Herrassa ja hänen väkevyytensä voimassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Pukekaa yllenne Jumalan koko sota-asu, voidaksenne kestää perkeleen kavalat juonet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Sillä meillä ei ole taistelu verta ja lihaa vastaan, vaan hallituksia vastaan, valtoja vastaan, tässä pimeydessä hallitsevia maailmanvaltiaita vastaan, pahuuden henkiolentoja vastaan taivaan avaruuksissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Sentähden ottakaa päällenne Jumalan koko sota-asu, voidaksenne pahana päivänä tehdä vastarintaa ja kaikki suoritettuanne pysyä pystyssä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Seisokaa siis kupeet totuuteen vyötettyinä, ja olkoon pukunanne vanhurskauden haarniska,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'ja kenkinä jaloissanne alttius rauhan evankeliumille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'Kaikessa ottakaa uskon kilpi, jolla voitte sammuttaa kaikki pahan palavat nuolet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'ja ottakaa vastaan pelastuksen kypäri ja Hengen miekka, joka on Jumalan sana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 18, 'Ja tehkää tämä kaikella rukouksella ja anomisella, rukoillen joka aika Hengessä ja sitä varten valvoen kaikessa kestäväisyydessä ja anomisessa kaikkien pyhien puolesta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 19, 'ja minunkin puolestani, että minulle, kun suuni avaan, annettaisiin oikeat sanat rohkeasti julistaakseni evankeliumin salaisuutta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 20, 'jonka tähden minä olen lähettiläänä kahleissa, että minä siitä rohkeasti puhuisin, niinkuin minun puhua tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 21, 'Mutta että tekin tietäisitte tilani, kuinka minun on, niin on Tykikus, rakas veljeni ja uskollinen palvelija Herrassa, antava teille siitä kaikesta tiedon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 22, 'Minä lähetän hänet teidän tykönne juuri sitä varten, että saisitte tietää meidän tilamme ja että hän lohduttaisi teidän sydämiänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 23, 'Rauha veljille ja rakkaus, uskon kanssa, Isältä Jumalalta ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 24, 'Armo olkoon kaikkien kanssa, jotka rakastavat meidän Herraamme Jeesusta Kristusta-katoamattomuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 1, 'Paavali ja Timoteus, Kristuksen Jeesuksen palvelijat, kaikille pyhille Kristuksessa Jeesuksessa, jotka ovat Filippissä, sekä myös seurakunnan kaitsijoille ja seurakuntapalvelijoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 2, 'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 3, 'Minä kiitän Jumalaani, niin usein kuin teitä muistan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 4, 'aina kaikissa rukouksissani ilolla rukoillen teidän kaikkien puolesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 5, 'kiitän siitä, että olette olleet osallisia evankeliumiin ensi päivästä alkaen tähän päivään saakka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 6, 'varmasti luottaen siihen, että hän, joka on alkanut teissä hyvän työn, on sen täyttävä Kristuksen Jeesuksen päivään saakka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 7, 'Ja oikein onkin, että minä näin ajattelen teitä kaikkia, koska te olette minun sydämessäni, te, jotka sekä ollessani kahleissa että evankeliumia puolustaessani ja vahvistaessani olette kaikki minun kanssani armosta osalliset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 8, 'Sillä Jumala on minun todistajani, kuinka minä teitä kaikkia ikävöitsen Kristuksen Jeesuksen sydämellisellä rakkaudella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 9, 'Ja sitä minä rukoilen, että teidän rakkautenne tulisi yhä runsaammaksi tiedossa ja kaikessa käsittämisessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 10, 'voidaksenne tutkia, mikä paras on, että te Kristuksen päivään saakka olisitte puhtaat ettekä kenellekään loukkaukseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 11, 'täynnä vanhurskauden hedelmää, jonka Jeesus Kristus saa aikaan, Jumalan kunniaksi ja ylistykseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 12, 'Mutta minä tahdon, että te, veljet, tietäisitte, että se, mitä minulle on tapahtunut, on koitunutkin evankeliumin menestykseksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 13, 'niin että koko henkivartioston ja kaikkien muiden tietoon on tullut, että minä olen kahleissa Kristuksen tähden,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 14, 'ja että useimmat veljistä, saaden Herrassa uskallusta minun kahleistani, yhä enemmän rohkenevat pelkäämättä puhua Jumalan sanaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 15, 'Muutamat tosin julistavat Kristusta kateudestakin ja riidan halusta, mutta toiset hyvässä tarkoituksessa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 16, 'nämä tekevät sitä rakkaudesta, koska tietävät, että minut on pantu evankeliumia puolustamaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 17, 'nuo toiset taas julistavat Kristusta itsekkyydestä, epäpuhtaalla mielellä, luullen tuottavansa minulle murhetta kahleissani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 18, 'Vaan mitäpä tuosta, kunhan Kristusta vain tavalla tai toisella julistetaan, joko näön vuoksi tai totuudessa! Ja siitä minä iloitsen, ja olen vastakin iloitseva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 19, 'Sillä minä tiedän, että tämä on päättyvä minulle pelastukseksi teidän rukoustenne kautta ja Jeesuksen Kristuksen Hengen avulla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 20, 'minun hartaan odotukseni ja toivoni mukaan, etten ole missään häpeään joutuva, vaan että Kristus nytkin, niinkuin aina, on tuleva ylistetyksi minun ruumiissani kaikella rohkeudella, joko elämän tai kuoleman kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 21, 'Sillä elämä on minulle Kristus, ja kuolema on voitto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 22, 'Mutta jos minun on eläminen täällä lihassa, niin siitä koituu hedelmää työlleni, ja silloin en tiedä, minkä valitsisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 23, 'Ahtaalla minä olen näiden kahden välissä: halu minulla on täältä eritä ja olla Kristuksen kanssa, sillä se olisi monin verroin parempi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 24, 'mutta teidän tähtenne on lihassa viipymiseni tarpeellisempi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 25, 'Ja kun olen tästä varma, niin minä tiedän jääväni eloon ja viipyväni kaikkien teidän luonanne teidän edistymiseksenne ja iloksenne uskossa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 26, 'että teidän kerskaamisenne minusta olisi yhä runsaampi Kristuksessa Jeesuksessa, kun minä taas tulen teidän tykönne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 27, 'Käyttäytykää vain Kristuksen evankeliumin arvon mukaisesti, että minä, tulinpa sitten teidän tykönne ja näin teidät tai olin tulematta, saan kuulla teistä, että te pysytte samassa hengessä ja yksimielisinä taistelette minun kanssani evankeliumin uskon puolesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 28, 'vastustajia missään kohden säikähtämättä; ja se on heille kadotuksen, mutta teille pelastuksen merkki, merkki Jumalalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 29, 'Sillä teidän on suotu, Kristuksen tähden, ei ainoastaan uskoa häneen, vaan myös kärsiä hänen tähtensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 1, 30, 'teidän, joilla on sama taistelu, mitä näitte ja nyt kuulette minun taistelevan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 1, 'Jos siis on jotakin kehoitusta Kristuksessa, jos jotakin rakkauden lohdutusta, jos jotakin Hengen yhteyttä, jos jotakin sydämellisyyttä ja laupeutta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 2, 'niin tehkää minun iloni täydelliseksi siten, että olette samaa mieltä, että teillä on sama rakkaus, että olette sopuisat ja yksimieliset');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 3, 'ettekä tee mitään itsekkyydestä tai turhan kunnian pyynnöstä, vaan että nöyryydessä pidätte toista parempana kuin itseänne');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 4, 'ja että katsotte kukin, ette vain omaanne, vaan toistenkin parasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 5, 'Olkoon teillä se mieli, joka myös Kristuksella Jeesuksella oli,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 6, 'joka ei, vaikka hänellä olikin Jumalan muoto, katsonut saaliiksensa olla Jumalan kaltainen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 7, 'vaan tyhjensi itsensä ja otti orjan muodon, tuli ihmisten kaltaiseksi, ja hänet havaittiin olennaltaan sellaiseksi kuin ihminen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 8, 'hän nöyryytti itsensä ja oli kuuliainen kuolemaan asti, hamaan ristin kuolemaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 9, 'Sentähden onkin Jumala hänet korkealle korottanut ja antanut hänelle nimen, kaikkia muita nimiä korkeamman,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 10, 'niin että kaikkien polvien pitää Jeesuksen nimeen notkistuman, sekä niitten, jotka taivaissa ovat, että niitten, jotka maan päällä ovat, ja niitten, jotka maan alla ovat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 11, 'ja jokaisen kielen pitää tunnustaman Isän Jumalan kunniaksi, että Jeesus Kristus on Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 12, 'Siis, rakkaani, samoin kuin aina olette olleet kuuliaiset, niin ahkeroikaa, ei ainoastaan niinkuin silloin, kun minä olin teidän tykönänne, vaan paljoa enemmän nyt, kun olen poissa, pelolla ja vavistuksella, että pelastuisitte;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 13, 'sillä Jumala on se, joka teissä vaikuttaa sekä tahtomisen että tekemisen, että hänen hyvä tahtonsa tapahtuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 14, 'Tehkää kaikki nurisematta ja epäröimättä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 15, 'että olisitte moitteettomat ja puhtaat, olisitte tahrattomat Jumalan lapset kieron ja nurjan sukukunnan keskellä, joiden joukossa te loistatte niinkuin tähdet maailmassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 16, 'tarjolla pitäessänne elämän sanaa, ollen minulle kerskaukseksi Kristuksen päivänä siitä, etten ole turhaan juossut enkä turhaan vaivaa nähnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 17, 'Vaan jos minut uhrataankin tehdessäni teidän uskonne uhri-ja palvelustoimitusta, niin minä kuitenkin iloitsen, ja iloitsen kaikkien teidän kanssanne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 18, 'samoin iloitkaa tekin, ja iloitkaa minun kanssani!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 19, 'Toivon Herrassa Jeesuksessa pian voivani lähettää Timoteuksen teidän tykönne, että minäkin tulisin rohkaistuksi, saatuani tietää, kuinka teidän on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 20, 'Sillä minulla ei ole ketään samanmielistä, joka vilpittömästi huolehtisi teidän tilastanne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 21, 'sillä kaikki he etsivät omaansa eivätkä sitä, mikä Kristuksen Jeesuksen on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 22, 'Mutta hänen koetellun mielensä te tunnette, että hän, niinkuin poika isäänsä, on minua palvellut evankeliumin työssä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 23, 'Hänet minä siis toivon voivani lähettää heti, kun olen saanut nähdä, miten minun käy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 24, 'Ja minä luotan Herrassa siihen, että itsekin pian olen tuleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 25, 'Katson kuitenkin välttämättömäksi palauttaa luoksenne veljeni, työkumppanini ja taistelutoverini Epafrodituksen, teidän lähettinne ja auttajan minun tarpeissani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 26, 'Sillä hän ikävöi teitä kaikkia ja on kovin levoton siitä, että olitte kuulleet hänen sairastavan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 27, 'Ja hän olikin sairaana, kuoleman kielissä; mutta Jumala armahti häntä, eikä ainoastaan häntä, vaan myös minua, etten saisi murhetta murheen päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 28, 'Lähetän hänet sentähden kiiruimmiten, että te hänet nähdessänne taas iloitsisitte ja minäkin olisin murheettomampi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 29, 'Ottakaa siis hänet vastaan Herrassa kaikella ilolla, ja pitäkää semmoisia kunniassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 2, 30, 'sillä Kristuksen työn tähden hän joutui aivan kuoleman partaalle, kun pani henkensä alttiiksi tehdäkseen minulle sen palveluksen, mitä te ette voineet tehdä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 1, 'Sitten vielä, veljeni, iloitkaa Herrassa! Samoista asioista teille kirjoittaminen ei minua kyllästytä, ja teille se on turvaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 2, 'Kavahtakaa noita koiria, kavahtakaa noita pahoja työntekijöitä, kavahtakaa noita pilalleleikattuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 3, 'Sillä oikeita ympärileikattuja olemme me, jotka Jumalan Hengessä palvelemme Jumalaa ja kerskaamme Kristuksessa Jeesuksessa, emmekä luota lihaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 4, 'vaikka minulla on, mihin luottaa lihassakin. Jos kuka muu luulee voivansa luottaa lihaan, niin voin vielä enemmän minä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 5, 'joka olen ympärileikattu kahdeksanpäiväisenä ja olen Israelin kansaa, Benjaminin sukukuntaa, hebrealainen hebrealaisista syntynyt, ollut lakiin nähden fariseus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 6, 'intoon nähden seurakunnan vainooja, lain vanhurskauteen nähden nuhteeton.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 7, 'Mutta mikä minulle oli voitto, sen minä olen Kristuksen tähden lukenut tappioksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 8, 'Niinpä minä todella luen kaikki tappioksi tuon ylen kalliin, Kristuksen Jeesuksen, minun Herrani, tuntemisen rinnalla, sillä hänen tähtensä minä olen menettänyt kaikki ja pidän sen roskana-että voittaisin omakseni Kristuksen');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 9, 'ja minun havaittaisiin olevan hänessä ja omistavan, ei omaa vanhurskautta, sitä, joka laista tulee, vaan sen, joka tulee Kristuksen uskon kautta, sen vanhurskauden, joka tulee Jumalasta uskon perusteella;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 10, 'tunteakseni hänet ja hänen ylösnousemisensa voiman ja hänen kärsimyksiensä osallisuuden, tullessani hänen kaltaisekseen samankaltaisen kuoleman kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 11, 'jos minä ehkä pääsen ylösnousemiseen kuolleista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 12, 'Ei niin, että jo olisin sen saavuttanut tai että jo olisin tullut täydelliseksi, vaan minä riennän sitä kohti, että minä sen omakseni voittaisin, koskapa Kristus Jeesus on voittanut minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 13, 'Veljet, minä en vielä katso sitä voittaneeni; mutta yhden minä teen: unhottaen sen, mikä on takana, ja kurottautuen sitä kohti, mikä on edessäpäin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 14, 'minä riennän kohti päämäärää, voittopalkintoa, johon Jumala on minut taivaallisella kutsumisella kutsunut Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 15, 'Olkoon siis meillä, niin monta kuin meitä on täydellistä, tämä mieli; ja jos teillä jossakin kohden on toinen mieli, niin Jumala on siinäkin teille ilmoittava, kuinka asia on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 16, 'Kunhan vain, mihin saakka olemme ehtineetkin, vaellamme samaa tietä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 17, 'Olkaa minun seuraajiani, veljet, ja katselkaa niitä, jotka näin vaeltavat, niinkuin me olemme teille esikuvana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 18, 'Sillä monet, joista usein olen sen teille sanonut ja nyt aivan itkien sanon, vaeltavat Kristuksen ristin vihollisina;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 19, 'heidän loppunsa on kadotus, vatsa on heidän jumalansa, heidän kunnianaan on heidän häpeänsä, ja maallisiin on heidän mielensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 20, 'Mutta meillä on yhdyskuntamme taivaissa, ja sieltä me myös odotamme Herraa Jeesusta Kristusta Vapahtajaksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 3, 21, 'joka on muuttava meidän alennustilamme ruumiin kirkkautensa ruumiin kaltaiseksi sillä voimallaan, jolla hän myös voi tehdä kaikki itsellensä alamaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 1, 'Sentähden, rakkaat ja ikävöidyt veljeni, te minun iloni ja kruununi, seisokaa näin Herrassa lujina, rakkaat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 2, 'Euodiaa minä kehoitan ja Syntykeä minä kehoitan olemaan yksimielisiä Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 3, 'Myös sinua, sinä minun oikea Synsygukseni, minä pyydän: ole näille vaimoille avullinen, sillä he ovat taistelleet minun kanssani evankeliumin hyväksi, yhdessä sekä Klemensin että muiden työtoverieni kanssa, joiden nimet ovat elämän kirjassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 4, 'Iloitkaa aina Herrassa! Vieläkin minä sanon: iloitkaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 5, 'Tulkoon teidän lempeytenne kaikkien ihmisten tietoon. Herra on lähellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 6, 'Älkää mistään murehtiko, vaan kaikessa saattakaa pyyntönne rukouksella ja anomisella kiitoksen kanssa Jumalalle tiettäväksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 7, 'ja Jumalan rauha, joka on kaikkea ymmärrystä ylempi, on varjeleva teidän sydämenne ja ajatuksenne Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 8, 'Ja vielä, veljet, kaikki, mikä on totta, mikä kunnioitettavaa, mikä oikeaa, mikä puhdasta, mikä rakastettavaa, mikä hyvältä kuuluvaa, jos on jokin avu ja jos on jotakin kiitettävää, sitä ajatelkaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 9, 'mitä myös olette oppineet ja saaneet ja minulta kuulleet ja minussa nähneet, sitä tehkää, niin rauhan Jumala on oleva teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 10, 'Minä ihastuin suuresti Herrassa, että te jo vihdoinkin olitte elpyneet pitämään minusta huolta, johon teillä ennenkin oli ollut halua, vaikka ei tilaisuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 11, 'Ei niin, että minä puutteen vuoksi tätä sanon; sillä minä olen oppinut oloihini tyytymään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 12, 'Osaan elää niukkuudessa, osaan myös elää runsaudessa; kaikkeen ja kaikenlaisiin oloihin minä olen tottunut; sekä olemaan ravittuna että näkemään nälkää, elämään sekä runsaudessa että puutteessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 13, 'Kaikki minä voin hänessä, joka minua vahvistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 14, 'Kuitenkin teitte hyvin, kun otitte osaa minun ahdinkooni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 15, 'Tiedättehän tekin, filippiläiset, että evankeliumin alkuaikoina, kun lähdin Makedoniasta, ei mikään muu seurakunta kuin te yksin käynyt minun kanssani tiliyhteyteen annetusta ja vastaanotetusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 16, 'Sillä Tessalonikaankin te minulle kerran, jopa kahdesti, lähetitte, mitä tarvitsin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 17, 'Ei niin, että haluaisin lahjaa, vaan minä haluan teidän hyväksenne karttuvaa hedelmää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 18, 'Olen nyt saanut kaikkea, jopa ylenpalttisesti; minulla on yllinkyllin, saatuani Epafroditukselta teidän lähetyksenne, joka on \"suloinen tuoksu\", otollinen, Jumalalle mieluinen uhri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 19, 'Mutta minun Jumalani on rikkautensa mukaisesti täyttävä kaikki teidän tarpeenne kirkkaudessa, Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 20, 'Mutta meidän Jumalallemme ja Isällemme kunnia aina ja iankaikkisesti! Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 21, 'Tervehdys jokaiselle pyhälle Kristuksessa Jeesuksessa. Tervehdyksen lähettävät teille minun kanssani olevat veljet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 22, 'Tervehdyksen lähettävät teille kaikki pyhät, mutta varsinkin ne, jotka ovat keisarin huoneväkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (67, 4, 23, 'Herran Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 1, 'Paavali, Jumalan tahdosta Kristuksen Jeesuksen apostoli, ja veli Timoteus');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 2, 'Kolossassa asuville pyhille ja uskoville veljille Kristuksessa. Armo teille ja rauha Jumalalta, meidän Isältämme!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 3, 'Me kiitämme Jumalaa, Herramme Jeesuksen Kristuksen Isää, aina kun rukoilemme teidän edestänne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 4, 'sillä me olemme saaneet kuulla teidän uskostanne Kristuksessa Jeesuksessa ja rakkaudesta, mikä teillä on kaikkia pyhiä kohtaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 5, 'me kiitämme häntä sen toivon tähden, joka teille on talletettuna taivaissa ja josta jo ennen olette kuulleet sen evankeliumin totuuden sanassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 6, 'joka on tullut teidän tykönne, niinkuin se on myös kaikessa maailmassa, missä se kantaa hedelmää ja kasvaa, samoin kuin teidänkin keskuudessanne siitä päivästä alkaen, jona te kuulitte ja opitte tuntemaan Jumalan armon totuudessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 7, 'niinkuin te sen opitte Epafraalta, meidän rakkaalta kanssapalvelijaltamme, joka on uskollinen Kristuksen palvelija teidän hyväksenne');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 8, 'ja joka myös on kertonut meille teidän rakkaudestanne Hengessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 9, 'Sentähden emme mekään, siitä päivästä alkaen, jona sen kuulimme, ole lakanneet teidän edestänne rukoilemasta ja anomasta, että tulisitte täyteen hänen tahtonsa tuntemista kaikessa hengellisessä viisaudessa ja ymmärtämisessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 10, 'vaeltaaksenne Herran edessä arvollisesti, hänelle kaikessa otollisesti, kaikessa hyvässä työssä hedelmää kantaen ja kasvaen Jumalan tuntemisen kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 11, 'ja hänen kirkkautensa väkevyyden mukaan kaikella voimalla vahvistettuina olemaan kaikessa kestäviä ja pitkämielisiä, ilolla');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 12, 'kiittäen Isää, joka on tehnyt teidät soveliaiksi olemaan osalliset siitä perinnöstä, mikä pyhillä on valkeudessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 13, 'häntä, joka on pelastanut meidät pimeyden vallasta ja siirtänyt meidät rakkaan Poikansa valtakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 14, 'Hänessä meillä on lunastus, syntien anteeksisaaminen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 15, 'ja hän on näkymättömän Jumalan kuva, esikoinen ennen kaikkea luomakuntaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 16, 'Sillä hänessä luotiin kaikki, mikä taivaissa ja mikä maan päällä on, näkyväiset ja näkymättömät, olkoot ne valtaistuimia tai herrauksia, hallituksia tai valtoja, kaikki on luotu hänen kauttansa ja häneen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 17, 'ja hän on ennen kaikkia, ja hänessä pysyy kaikki voimassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 18, 'Ja hän on ruumiin, se on: seurakunnan, pää; hän, joka on alku, esikoinen kuolleista nousseitten joukossa, että hän olisi kaikessa ensimmäinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 19, 'Sillä Jumala näki hyväksi, että kaikki täyteys hänessä asuisi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 20, 'ja että hän, tehden rauhan hänen ristinsä veren kautta, hänen kauttaan sovittaisi itsensä kanssa kaikki, hänen kauttaan kaikki sekä maan päällä että taivaissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 21, 'Teidätkin, jotka ennen olitte vieraantuneet ja mieleltänne hänen vihamiehiänsä pahoissa teoissanne, hän nyt on sovittanut');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 22, 'Poikansa lihan ruumiissa kuoleman kautta, asettaakseen teidät pyhinä ja nuhteettomina ja moitteettomina eteensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 23, 'jos te vain pysytte uskossa, siihen perustuneina ja siinä lujina, horjahtamatta pois sen evankeliumin toivosta, jonka olette kuulleet, jota on julistettu kaikessa luomakunnassa taivaan alla ja jonka palvelijaksi minä, Paavali, olen tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 24, 'Nyt minä iloitsen kärsiessäni teidän tähtenne, ja mikä vielä puuttuu Kristuksen ahdistuksista, sen minä täytän lihassani hänen ruumiinsa hyväksi, joka on seurakunta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 25, 'jonka palvelijaksi minä olen tullut Jumalan armotalouden mukaan, joka minulle on annettu teitä varten, täydellisesti julistaakseni Jumalan sanan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 26, 'sen salaisuuden, joka on ollut kätkettynä ikuisista ajoista ja polvesta polveen, mutta joka nyt on ilmoitettu hänen pyhillensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 27, 'joille Jumala tahtoi tehdä tiettäväksi, kuinka suuri pakanain keskuudessa on tämän salaisuuden kirkkaus: Kristus teissä, kirkkauden toivo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 28, 'Ja häntä me julistamme, neuvoen jokaista ihmistä ja opettaen jokaista ihmistä kaikella viisaudella, asettaaksemme esiin jokaisen ihmisen täydellisenä Kristuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 1, 29, 'Sitä varten minä vaivaa näenkin, taistellen hänen vaikutuksensa mukaan, joka minussa voimallisesti vaikuttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 1, 'Sillä minä tahdon, että te tiedätte, kuinka suuri kilvoittelu minulla on teidän tähtenne ja laodikealaisten ja kaikkien tähden, jotka eivät ole minun ruumiillisia kasvojani nähneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 2, 'että heidän sydämensä, yhteenliittyneinä rakkaudessa, saisivat kehoitusta omistamaan täyden ymmärtämyksen koko rikkauden ja pääsisivät tuntemaan Jumalan salaisuuden, Kristuksen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 3, 'jossa kaikki viisauden ja tiedon aarteet ovat kätkettyinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 4, 'Tämän minä sanon, ettei kukaan teitä pettäisi suostuttelevilla puheilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 5, 'Sillä jos ruumiillisesti olenkin poissa, olen kuitenkin teidän kanssanne hengessä ja iloitsen nähdessäni järjestyksen, joka teidän keskuudessanne vallitsee, ja teidän lujan uskonne Kristukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 6, 'Niinkuin te siis olette omaksenne ottaneet Kristuksen Jeesuksen, Herran, niin vaeltakaa hänessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 7, 'juurtuneina häneen ja hänessä rakentuen ja uskossa vahvistuen, niinkuin teille on opetettu; ja olkoon teidän kiitoksenne ylitsevuotavainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 8, 'Katsokaa, ettei kukaan saa teitä saaliikseen järkeisopilla ja tyhjällä petoksella, pitäytyen ihmisten perinnäissääntöihin ja maailman alkeisvoimiin eikä Kristukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 9, 'Sillä hänessä asuu jumaluuden koko täyteys ruumiillisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 10, 'ja te olette täytetyt hänessä, joka on kaiken hallituksen ja vallan pää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 11, 'ja hänessä te myös olette ympärileikatut, ette käsintehdyllä ympärileikkauksella, vaan lihan ruumiin poisriisumisella, Kristuksen ympärileikkauksella:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 12, 'ollen haudattuina hänen kanssaan kasteessa, jossa te myös hänen kanssaan olette herätetyt uskon kautta, jonka vaikuttaa Jumala, joka herätti hänet kuolleista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 13, 'Ja teidät, jotka olitte kuolleet rikoksiinne ja lihanne ympärileikkaamattomuuteen, teidät hän teki eläviksi yhdessä hänen kanssaan, antaen meille anteeksi kaikki rikokset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 14, 'ja pyyhki pois sen kirjoituksen säädöksineen, joka oli meitä vastaan ja oli meidän vastustajamme; sen hän otti meidän tieltämme pois ja naulitsi ristiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 15, 'Hän riisui aseet hallituksilta ja valloilta ja asetti heidät julkisen häpeän alaisiksi; hän sai heistä hänen kauttaan voiton riemun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 16, 'Älköön siis kukaan teitä tuomitko syömisestä tai juomisesta, älköön myös minkään juhlan tai uudenkuun tai sapatin johdosta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 17, 'jotka vain ovat tulevaisten varjo, mutta ruumis on Kristuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 18, 'Älköön teiltä riistäkö voittopalkintoanne kukaan, joka on mieltynyt nöyryyteen ja enkelien palvelemiseen ja pöyhkeilee näyistään ja on lihallisen mielensä turhaan paisuttama');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 19, 'eikä pitäydy häneen, joka on pää ja josta koko ruumis, nivelten ja jänteiden avulla koossa pysyen, kasvaa Jumalan antamaa kasvua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 20, 'Jos te olette Kristuksen kanssa kuolleet pois maailman alkeisvoimista, miksi te, ikäänkuin eläisitte maailmassa, sallitte määrätä itsellenne säädöksiä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 21, '\"Älä tartu, älä maista, älä koske!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 22, '-sehän on kaikki tarkoitettu katoamaan käyttämisen kautta-ihmisten käskyjen ja oppien mukaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 2, 23, 'Tällä kaikella tosin on viisauden maine itsevalitun jumalanpalveluksen ja nöyryyden vuoksi ja sentähden, ettei se ruumista säästä; mutta se on ilman mitään arvoa, ja se tapahtuu lihan tyydyttämiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 1, 'Jos te siis olette herätetyt Kristuksen kanssa, niin etsikää sitä, mikä on ylhäällä, jossa Kristus on, istuen Jumalan oikealla puolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 2, 'Olkoon mielenne siihen, mikä ylhäällä on, älköön siihen, mikä on maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 3, 'Sillä te olette kuolleet, ja teidän elämänne on kätkettynä Kristuksen kanssa Jumalassa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 4, 'kun Kristus, meidän elämämme, ilmestyy, silloin tekin hänen kanssaan ilmestytte kirkkaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 5, 'Kuolettakaa siis maalliset jäsenenne: haureus, saastaisuus, kiihko, paha himo ja ahneus, joka on epäjumalanpalvelusta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 6, 'sillä niiden tähden tulee Jumalan viha,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 7, 'ja niissä tekin ennen vaelsitte, kun niissä elitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 8, 'Mutta nyt pankaa tekin pois ne kaikki: viha, kiivastus, pahuus, herjaus ja häpeällinen puhe suustanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 9, 'Älkää puhuko valhetta toisistanne, te, jotka olette riisuneet pois vanhan ihmisen tekoinensa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 10, 'ja pukeutuneet uuteen, joka uudistuu tietoon, Luojansa kuvan mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 11, 'Ja tässä ei ole kreikkalaista eikä juutalaista, ei ympärileikkausta eikä ympärileikkaamattomuutta, ei barbaaria, ei skyyttalaista, ei orjaa, ei vapaata, vaan kaikki ja kaikissa on Kristus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 12, 'Pukeutukaa siis te, jotka olette Jumalan valituita, pyhiä ja rakkaita, sydämelliseen armahtavaisuuteen, ystävällisyyteen, nöyryyteen, sävyisyyteen, pitkämielisyyteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 13, 'kärsikää toinen toistanne ja antakaa toisillenne anteeksi, jos kenellä on moitetta toista vastaan. Niinkuin Herrakin on antanut teille anteeksi, niin myös te antakaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 14, 'Mutta kaiken tämän lisäksi pukeutukaa rakkauteen, mikä on täydellisyyden side.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 15, 'Ja vallitkoon teidän sydämissänne Kristuksen rauha, johon te olette kutsututkin yhdessä ruumiissa, ja olkaa kiitolliset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 16, 'Runsaasti asukoon teissä Kristuksen sana; opettakaa ja neuvokaa toinen toistanne kaikessa viisaudessa, psalmeilla, kiitosvirsillä ja hengellisillä lauluilla, veisaten kiitollisesti Jumalalle sydämissänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 17, 'Ja kaikki, minkä teette sanalla tai työllä, kaikki tehkää Herran Jeesuksen nimessä, kiittäen Isää Jumalaa hänen kauttansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 18, 'Vaimot, olkaa miehillenne alamaiset, niinkuin sopii Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 19, 'Miehet, rakastakaa vaimojanne, älkääkä olko heitä kohtaan katkerat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 20, 'Lapset, olkaa vanhemmillenne kuuliaiset kaikessa, sillä se on otollista Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 21, 'Isät, älkää kiihoittako lapsianne, etteivät he kävisi aroiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 22, 'Palvelijat, olkaa maallisille isännillenne kaikessa kuuliaiset, ei silmänpalvelijoina, ihmisille mieliksi, vaan sydämen yksinkertaisuudessa peljäten Herraa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 23, 'Kaikki, mitä teette, se tehkää sydämestänne, niinkuin Herralle eikä ihmisille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 24, 'tietäen, että te saatte Herralta palkaksi perinnön; te palvelette Herraa Kristusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 3, 25, 'Sillä se, joka tekee väärin, on saava takaisin, mitä on väärin tehnyt; ja henkilöön ei katsota.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 1, 'Isännät, tehkää palvelijoillenne, mitä oikeus ja kohtuus vaatii, sillä te tiedätte, että teilläkin on Herra taivaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 2, 'Olkaa kestäväiset rukouksessa ja siinä kiittäen valvokaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 3, 'rukoillen samalla meidänkin edestämme, että Jumala avaisi meille sanan oven puhuaksemme Kristuksen salaisuutta, jonka tähden minä myös olen sidottuna,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 4, 'että minä sen ilmoittaisin, niinkuin minun tulee puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 5, 'Vaelluksessanne olkaa viisaat ulkopuolella olevia kohtaan, ja ottakaa vaari oikeasta hetkestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 6, 'Olkoon puheenne aina suloista, suolalla höystettyä, ja tietäkää, kuinka teidän tulee itsekullekin vastata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 7, 'Kaikista minun oloistani antaa teille tiedon Tykikus, rakas veli ja uskollinen palvelija, minun kanssapalvelijani Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 8, 'Hänet minä lähetän teidän tykönne juuri sitä varten, että saisitte tietää tilamme ja että hän lohduttaisi teidän sydämiänne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 9, 'ja myös Onesimuksen, uskollisen ja rakkaan veljen, joka on teikäläisiä; he ilmoittavat teille, kuinka täällä kaikki on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 10, 'Teille lähettää tervehdyksen Aristarkus, minun vankitoverini, ja Markus, Barnabaan serkku, josta olette saaneet ohjeita-jos hän tulee teidän tykönne, niin ottakaa hänet vastaan-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 11, 'ja Jeesus, jota sanotaan Justukseksi; nämä ovat ympärileikatuista ainoat, jotka ovat olleet minun auttajani työssä Jumalan valtakunnan hyväksi, ja he ovat olleet minulle lohdutukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 12, 'Tervehdyksen lähettää teille teikäläinen Epafras, Kristuksen Jeesuksen palvelija, joka rukouksissaan aina taistelee teidän puolestanne, että te pysyisitte täydellisinä ja täysin vahvoina kaikessa, mikä on Jumalan tahto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 13, 'Sillä minä annan hänestä sen todistuksen, että hän näkee paljon vaivaa teidän hyväksenne ja niiden hyväksi, jotka ovat Laodikeassa, sekä niiden, jotka ovat Hierapolissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 14, 'Luukas, rakas lääkäri, lähettää teille tervehdyksen, niin myös Deemas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 15, 'Tervehdys Laodikeassa oleville veljille ja Nymfalle sekä hänen kodissaan kokoontuvalle seurakunnalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 16, 'Ja kun tämä kirje on luettu teille, niin toimittakaa, että se luetaan Laodikeankin seurakunnassa ja että myös te luette Laodikeasta tulevan kirjeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 17, 'Ja sanokaa Arkippukselle: \"Ota vaari virasta, jonka olet saanut Herrassa, että sen täysin toimitat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (68, 4, 18, 'Tervehdys minulta, Paavalilta, omakätisesti. Muistakaa minun kahleitani. Armo olkoon teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 1, 'Paavali ja Silvanus ja Timoteus tessalonikalaisten seurakunnalle Isässä Jumalassa ja Herrassa Jeesuksessa Kristuksessa. Armo teille ja rauha!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 2, 'Me kiitämme Jumalaa aina kaikkien teidän tähtenne, mainiten teitä rukouksissamme, sillä lakkaamatta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 3, 'me Jumalamme ja Isämme edessä muistamme teidän työtänne uskossa ja vaivannäköänne rakkaudessa ja kärsivällisyyttänne toivossa Herraamme Jeesukseen Kristukseen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 4, 'tietäen, veljet, te Jumalan rakastetut, teidän valitsemisenne:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 5, 'että meidän evankeliumimme tuli teidän tykönne, ei ainoastaan sanana, vaan myös voimana ja Pyhässä Hengessä ja suurella varmuudella-niinkuin tiedätte, millaisia me olimme teidän keskuudessanne, teidän tähtenne-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 6, 'ja teistä tuli meidän seuraajiamme ja Herran, kun suuressa ahdingossa otitte sanan vastaan ilolla Pyhässä Hengessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 7, 'niin että te olette tulleet esikuviksi kaikille uskoville Makedoniassa ja Akaiassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 8, 'Sillä teidän tyköänne on Herran sana kaikunut; ei ainoastaan Makedoniaan ja Akaiaan, vaan kaikkialle on teidän uskonne Jumalaan levinnyt, niin ettei meidän tarvitse siitä mitään puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 9, 'Sillä itse he kertovat meistä, millainen meidän tulomme teidän tykönne oli ja kuinka te epäjumalista käännyitte Jumalan tykö, palvelemaan elävää ja totista Jumalaa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 1, 10, 'ja odottamaan taivaista hänen Poikaansa, jonka hän on herättänyt kuolleista, Jeesusta, joka pelastaa meidät tulevasta vihasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 1, 'Tiedättehän itsekin, veljet, ettei tulomme teidän tykönne ollut turha;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 2, 'vaan, vaikka me ennen, niinkuin tiedätte, olimme kärsineet Filippissä ja meitä siellä oli pahoin pidelty, oli meillä kuitenkin Jumalassamme rohkeutta puhua teille Jumalan evankeliumia, suuressa kilvoituksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 3, 'Sillä meidän kehoituspuheemme ei lähde eksymyksestä eikä epäpuhtaasta mielestä eikä ole kavaluudessa puhuttua;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 4, 'vaan niinkuin Jumala on katsonut meidän kelpaavan siihen, että meille uskottiin evankeliumi, niin me puhumme, emme, niinkuin tahtoisimme olla mieliksi ihmisille, vaan Jumalalle, joka koettelee meidän sydämemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 5, 'Sillä me emme koskaan ole liikkuneet liehakoivin sanoin, sen te tiedätte, emmekä millään tekosyyllä voittoa ahnehtineet; Jumala on todistajamme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 6, 'emmekä ole etsineet kunniaa ihmisiltä, emme teiltä emmekä muilta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 7, 'vaikka me Kristuksen apostoleina olisimme voineet vaatia arvonantoa; vaan me olimme lempeät teidän keskuudessanne, niinkuin imettävä äiti, joka vaalii lapsiansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 8, 'niin mekin, teitä hellien, halusimme antaa teille, ei ainoastaan Jumalan evankeliumia, vaan oman henkemmekin, sillä te olitte meille rakkaiksi tulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 9, 'Muistattehan, veljet, meidän työmme ja vaivamme: yöt ja päivät työtä tehden, ettemme ketään teistä rasittaisi, me julistimme teille Jumalan evankeliumia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 10, 'Te olette meidän todistajamme, ja Jumala, kuinka pyhät ja oikeamieliset ja nuhteettomat me olimme teitä kohtaan, jotka uskotte,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 11, 'samoinkuin te tiedätte, kuinka me, niinkuin isä lapsiansa, kehoitimme itsekutakin teistä ja rohkaisimme teitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 12, 'ja teroitimme teille, että teidän on vaeltaminen arvollisesti Jumalan edessä, joka kutsuu teitä valtakuntaansa ja kirkkauteensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 13, 'Ja sentähden me myös lakkaamatta kiitämme Jumalaa siitä, että te, kun saitte meiltä kuulemanne Jumalan sanan, otitte sen vastaan, ette ihmisten sanana, vaan, niinkuin se totisesti on, Jumalan sanana, joka myös vaikuttaa teissä, jotka uskotte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 14, 'Sillä teistä, veljet, on tullut niiden Kristuksessa Jeesuksessa olevien Jumalan seurakuntain seuraajia, jotka ovat Juudeassa, sillä tekin olette kärsineet omilta kansalaisiltanne samaa kuin he juutalaisilta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 15, 'jotka tappoivat Herran Jeesuksenkin ja profeetat ja ovat vainonneet meitä, eivätkä ole Jumalalle otollisia, vaan ovat kaikkien ihmisten vihollisia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 16, 'kun estävät meitä puhumasta pakanoille heidän pelastumiseksensa. Näin he yhäti täyttävät syntiensä mittaa. Viha onkin jo saavuttanut heidät, viimeiseen määräänsä asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 17, 'Mutta kun meidät nyt, veljet, on hetkeksi aikaa erotettu teistä, ulkonaisesti, ei sydämeltä, niin on meille tullut yhä suurempi halu päästä näkemään teidän kasvojanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 18, 'Sentähden olemme tahtoneet tulla teidän tykönne, minä, Paavali, puolestani, en vain kerran, vaan kahdestikin, mutta saatana on meidät estänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 19, 'Sillä kuka on meidän toivomme tai ilomme tai meidän kerskauksemme kruunu? Ettekö myös te, meidän Herramme Jeesuksen edessä hänen tulemuksessaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 2, 20, 'Sillä te olette meidän kunniamme ja meidän ilomme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 1, 'Sentähden me, kun emme enää voineet kestää kauemmin, päätimme jäädä yksinämme Ateenaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 2, 'ja lähetimme Timoteuksen, veljemme ja Jumalan palvelijan Kristuksen evankeliumissa, vahvistamaan teitä ja rohkaisemaan teitä uskossanne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 3, 'ettei kukaan horjuisi näissä ahdingoissa. Sillä itse te tiedätte, että meidät on semmoisiin pantu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 4, 'Sanoimmehan, kun olimme teidän tykönänne, teille jo edeltäpäin, että meidän oli ahdinkoon joutuminen, niinkuin on käynytkin ja te tiedätte käyneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 5, 'Sentähden minä, kun en enää jaksanut kestää kauemmin, lähetinkin tiedustelemaan teidän uskoanne, ettei vain kiusaaja liene teitä kiusannut ja meidän vaivannäkömme mennyt hukkaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 6, 'Mutta nyt, kun Timoteus tuli teidän tyköänne meidän tykömme ja toi meille ilosanoman teidän uskostanne ja rakkaudestanne ja siitä, että te aina pidätte meitä rakkaassa muistossa ikävöiden meitä nähdäksenne niinkuin mekin teitä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 7, 'sentähden olemme teidän uskostanne, veljet, saaneet lohdutusta teihin nähden kaikessa hädässämme ja ahdistuksessamme;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 8, 'sillä nyt me elämme, jos te seisotte lujina Herrassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 9, 'Kuinka voimmekaan kyllin kiittää Jumalaa teidän tähtenne kaikesta siitä ilosta, mikä meillä teistä on Jumalamme edessä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 10, 'Öin ja päivin me mitä hartaimmin rukoilemme saadaksemme nähdä teidän kasvonne ja täyttää sen, mitä teidän uskostanne puuttuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 11, 'Mutta hän itse, meidän Jumalamme ja Isämme, ja meidän Herramme Jeesus ohjatkoon meidän tiemme teidän tykönne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 12, 'Ja teille Herra antakoon yhä enemmän ja runsaammin rakkautta toisianne kohtaan ja kaikkia kohtaan, niinkuin meilläkin on teitä kohtaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 3, 13, 'vahvistaaksensa teidän sydämenne nuhteettomiksi pyhyydessä meidän Jumalamme ja Isämme edessä, meidän Herramme Jeesuksen tulemuksessa, kun hän tulee kaikkien pyhiensä kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 1, 'Sitten vielä, veljet, me pyydämme teitä ja kehoitamme Herrassa Jeesuksessa, että te, niinkuin olette meiltä oppineet, miten teidän tulee vaeltaa ja olla Jumalalle otolliset, niinkuin vaellattekin, siinä yhä enemmän varttuisitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 2, 'Tiedättehän, mitkä käskyt me olemme Herran Jeesuksen kautta teille antaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 3, 'Sillä tämä on Jumalan tahto, teidän pyhityksenne, että kartatte haureutta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 4, 'että kukin teistä tietää ottaa oman vaimon pyhyydessä ja kunniassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 5, 'ei himon kiihkossa niinkuin pakanat, jotka eivät Jumalaa tunne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 6, 'ettei kukaan sorra veljeänsä eikä tuota hänelle vahinkoa missään asiassa, sillä Herra on kaiken tämän kostaja, niinkuin myös ennen olemme teille sanoneet ja todistaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 7, 'Sillä ei Jumala ole kutsunut meitä saastaisuuteen, vaan pyhitykseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 8, 'Sentähden, joka nämä hylkää, ei hylkää ihmistä, vaan Jumalan, joka myös antaa Pyhän Henkensä teihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 9, 'Veljellisestä rakkaudesta ei ole tarvis teille kirjoittaa; sillä itse te olette Jumalalta oppineet rakastamaan toisianne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 10, 'niin te myös teette kaikkia veljiä kohtaan koko Makedoniassa. Mutta me kehoitamme teitä, veljet, siinä varttumaan yhä enemmän');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 11, 'ja katsomaan kunniaksenne, että elätte hiljaisuudessa ja toimitatte omia tehtäviänne ja teette työtä käsillänne, niinkuin olemme teitä käskeneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 12, 'että vaelluksessanne olisitte säädylliset ulkopuolella olevia kohtaan ettekä olisi kenenkään avun tarpeessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 13, 'Mutta me emme tahdo pitää teitä, veljet, tietämättöminä siitä, kuinka poisnukkuneiden on, ettette murehtisi niinkuin muut, joilla ei toivoa ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 14, 'Sillä jos uskomme, että Jeesus on kuollut ja noussut ylös, niin samoin on Jumala Jeesuksen kautta myös tuova poisnukkuneet esiin yhdessä hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 15, 'Sillä sen me sanomme teille Herran sanana, että me, jotka olemme elossa, jotka jäämme tänne Herran tulemukseen, emme suinkaan ehdi ennen niitä, jotka ovat nukkuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 16, 'Sillä itse Herra on tuleva alas taivaasta käskyhuudon, ylienkelin äänen ja Jumalan pasunan kuuluessa, ja Kristuksessa kuolleet nousevat ylös ensin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 17, 'sitten meidät, jotka olemme elossa, jotka olemme jääneet tänne, temmataan yhdessä heidän kanssaan pilvissä Herraa vastaan yläilmoihin; ja niin me saamme aina olla Herran kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 4, 18, 'Niin lohduttakaa siis toisianne näillä sanoilla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 1, 'Mutta aikakausista ja määrähetkistä ei teille, veljet, ole tarvis kirjoittaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 2, 'sillä itse te varsin hyvin tiedätte, että Herran päivä tulee niinkuin varas yöllä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 3, 'Kun he sanovat: \"Nyt on rauha, ei hätää mitään\", silloin yllättää heidät yhtäkkiä turmio, niinkuin synnytyskipu raskaan vaimon, eivätkä he pääse pakoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 4, 'Mutta te, veljet, ette ole pimeydessä, niin että se päivä voisi yllättää teidät niinkuin varas;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 5, 'sillä kaikki te olette valkeuden lapsia ja päivän lapsia; me emme ole yön emmekä pimeyden lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 6, 'Älkäämme siis nukkuko niinkuin muut, vaan valvokaamme ja olkaamme raittiit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 7, 'Sillä ne, jotka nukkuvat, ne yöllä nukkuvat, ja jotka juovat itsensä juovuksiin, ne yöllä juovuksissa ovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 8, 'Mutta me, jotka olemme päivän lapsia, olkaamme raittiit, ja olkoon pukunamme uskon ja rakkauden haarniska ja kypärinämme pelastuksen toivo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 9, 'Sillä ei Jumala ole määrännyt meitä vihaan, vaan saamaan pelastuksen Herramme Jeesuksen Kristuksen kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 10, 'joka on kuollut meidän edestämme, että me, valvoimmepa tai nukuimme, eläisimme yhdessä hänen kanssaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 11, 'Sentähden kehoittakaa toisianne ja rakentakaa toinen toistanne, niinkuin teettekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 12, 'Mutta me pyydämme teitä, veljet, antamaan tunnustuksenne niille, jotka tekevät työtä teidän keskuudessanne ja ovat teidän johtajanne Herrassa ja neuvovat teitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 13, 'sekä pitämään heitä erinomaisen rakkaina heidän työnsä tähden. Eläkää rauhassa keskenänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 14, 'Me kehoitamme teitä, veljet: nuhdelkaa kurittomia, rohkaiskaa alakuloisia, holhotkaa heikkoja, olkaa pitkämieliset kaikkia kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 15, 'Katsokaa, ettei kukaan kosta kenellekään pahaa pahalla, vaan pyrkikää aina tekemään hyvää toinen toisellenne ja kaikille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 16, 'Olkaa aina iloiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 17, 'Rukoilkaa lakkaamatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 18, 'Kiittäkää joka tilassa. Sillä se on Jumalan tahto teihin nähden Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 19, 'Henkeä älkää sammuttako,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 20, 'profetoimista älkää halveksuko,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 21, 'mutta koetelkaa kaikki, pitäkää se, mikä hyvää on;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 22, 'karttakaa kaikenkaltaista pahaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 23, 'Mutta itse rauhan Jumala pyhittäköön teidät kokonansa, ja säilyköön koko teidän henkenne ja sielunne ja ruumiinne nuhteettomana meidän Herramme Jeesuksen Kristuksen tulemukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 24, 'Hän, joka teitä kutsuu, on uskollinen, ja hän on sen myös tekevä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 25, 'Veljet, rukoilkaa meidän edestämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 26, 'Tervehtikää kaikkia veljiä pyhällä suunannolla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 27, 'Minä vannotan teitä Herran kautta, että luetatte tämän kirjeen kaikille veljille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (69, 5, 28, 'Meidän Herramme Jeesuksen Kristuksen armo olkoon teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 1, 'Paavali ja Silvanus ja Timoteus tessalonikalaisten seurakunnalle Jumalassa, meidän Isässämme, ja Herrassa Jeesuksessa Kristuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 2, 'Armo teille ja rauha Isältä Jumalalta ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 3, 'Me olemme velvolliset aina kiittämään Jumalaa teidän tähtenne, veljet, niinkuin oikein onkin, koska teidän uskonne runsaasti kasvaa ja keskinäinen rakkautenne lisääntyy itsekussakin, kaikissa teissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 4, 'niin että me itsekin Jumalan seurakunnissa kerskaamme teistä, teidän kärsivällisyydestänne ja uskostanne kaikissa vainoissanne ja ahdistuksissa, joita teillä on kestettävänä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 5, 'ja jotka ovat osoituksena Jumalan vanhurskaasta tuomiosta, että teidät katsottaisiin arvollisiksi Jumalan valtakuntaan, jonka tähden kärsittekin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 6, 'koskapa Jumala katsoo oikeaksi kostaa ahdistuksella niille, jotka teitä ahdistavat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 7, 'ja antaa teille, joita ahdistetaan, levon yhdessä meidän kanssamme, kun Herra Jeesus ilmestyy taivaasta voimansa enkelien kanssa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 8, 'tulen liekissä ja kostaa niille, jotka eivät tunne Jumalaa eivätkä ole kuuliaisia meidän Herramme Jeesuksen evankeliumille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 9, 'Heitä kohtaa silloin rangaistukseksi iankaikkinen kadotus Herran kasvoista ja hänen voimansa kirkkaudesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 10, 'kun hän sinä päivänä tulee, että hän kirkastuisi pyhissänsä ja olisi ihmeteltävä kaikissa uskovissa, sillä te olette uskoneet meidän todistuksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 11, 'Sitä varten me aina rukoilemmekin teidän puolestanne, että meidän Jumalamme katsoisi teidät kutsumisensa arvoisiksi ja voimallisesti saattaisi täydelliseksi kaiken teidän halunne hyvään ja teidän uskonne teot,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 1, 12, 'että meidän Herramme Jeesuksen nimi teissä kirkastuisi ja te hänessä, meidän Jumalamme ja Herran Jeesuksen Kristuksen armon mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 1, 'Mutta mitä tulee meidän Herramme Jeesuksen Kristuksen tulemukseen ja meidän kokoontumiseemme hänen tykönsä, niin me pyydämme teitä, veljet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 2, 'ettette anna minkään hengen ettekä sanan ettekä minkään muka meidän lähettämämme kirjeen heti järkyttää itseänne, niin että menetätte mielenne maltin, ettekä anna niiden itseänne peljästyttää, ikäänkuin Herran päivä jo olisi käsissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 3, 'Älkää antako kenenkään vietellä itseänne millään tavalla. Sillä se päivä ei tule, ennenkuin luopumus ensin tapahtuu ja laittomuuden ihminen ilmestyy, kadotuksen lapsi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 4, 'tuo vastustaja, joka korottaa itsensä yli kaiken, mitä jumalaksi tai jumaloitavaksi kutsutaan, niin että hän asettuu Jumalan temppeliin ja julistaa olevansa Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 5, 'Ettekö muista, että minä, kun vielä olin teidän tykönänne, sanoin tämän teille?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 6, 'Ja nyt te tiedätte, mikä pidättää, niin että hän vasta ajallansa ilmestyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 7, 'Sillä laittomuuden salaisuus on jo vaikuttamassa; jahka vain tulee tieltä poistetuksi se, joka nyt vielä pidättää,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 8, 'niin silloin ilmestyy tuo laiton, jonka Herra Jeesus on surmaava suunsa henkäyksellä ja tuhoava tulemuksensa ilmestyksellä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 9, 'tuo, jonka tulemus tapahtuu saatanan vaikutuksesta valheen kaikella voimalla ja tunnusteoilla ja ihmeillä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 10, 'ja kaikilla vääryyden viettelyksillä niille, jotka joutuvat kadotukseen, sentähden etteivät ottaneet vastaan rakkautta totuuteen, voidaksensa pelastua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 11, 'Ja sentähden Jumala lähettää heille väkevän eksytyksen, niin että he uskovat valheen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 12, 'että kaikki ne tuomittaisiin, jotka eivät ole uskoneet totuutta, vaan mielistyneet vääryyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 13, 'Mutta me olemme velvolliset aina kiittämään Jumalaa teidän tähtenne, veljet, te Herran rakastetut, sentähden että Jumala alusta alkaen valitsi teidät pelastukseen Hengen pyhityksessä ja uskossa totuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 14, 'Siihen hän on myös kutsunut teidät meidän evankeliumimme kautta, omistamaan meidän Herramme Jeesuksen Kristuksen kirkkauden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 15, 'Niin seisokaa siis, veljet, lujina ja pitäkää kiinni niistä opetuksista, joita olette oppineet joko meidän puheestamme tai kirjeestämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 16, 'Ja meidän Herramme Jeesus Kristus itse ja Jumala, meidän Isämme, joka on rakastanut meitä ja armossa antanut meille iankaikkisen lohdutuksen ja hyvän toivon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 2, 17, 'lohduttakoon teidän sydämiänne ja vahvistakoon teitä kaikessa hyvässä työssä ja puheessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 1, 'Sitten vielä, veljet, rukoilkaa meidän edestämme, että Herran sana nopeasti leviäisi ja tulisi kirkastetuksi muuallakin niinkuin teidän keskuudessanne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 2, 'ja että me pelastuisimme nurjista ja häijyistä ihmisistä; sillä usko ei ole joka miehen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 3, 'Mutta Herra on uskollinen, ja hän on vahvistava teitä ja varjeleva teidät pahasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 4, 'Ja me luotamme teihin Herrassa, että te sekä nyt että vasta teette, mitä me käskemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 5, 'Ja Herra ohjatkoon teidän sydämenne Jumalan rakkauteen ja Kristuksen kärsivällisyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 6, 'Mutta Herran Jeesuksen Kristuksen nimessä me käskemme teitä, veljet, vetäytymään pois jokaisesta veljestä, joka vaeltaa kurittomasti eikä sen opetuksen mukaan, jonka olette meiltä saaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 7, 'Tiedättehän itse, kuinka meidän jälkiämme on seurattava, sillä me emme ole olleet kurittomia teidän keskuudessanne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 8, 'emmekä ilmaiseksi syöneet kenenkään leipää, vaan työssä ja vaivassa me ahkeroitsimme yöt ja päivät, ettemme olisi kenellekään teistä rasitukseksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 9, 'ei niin, ettei meillä olisi siihen valtaa, vaan me tahdomme olla teille esikuvaksi, että te kulkisitte meidän jälkiämme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 10, 'Sillä jo silloin, kun olimme teidän tykönänne, me sääsimme teille, että kuka ei tahdo työtä tehdä, ei hänen syömänkään pidä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 11, 'Sillä me olemme kuulleet, että muutamat teidän keskuudessanne vaeltavat kurittomasti, eivät tee työtä, vaan puuhailevat sellaisessa, mikä ei heille kuulu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 12, 'Semmoisia me käskemme ja kehoitamme Herrassa Jeesuksessa Kristuksessa, tekemään työtä hiljaisuudessa ja syömään omaa leipäänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 13, 'Mutta te, veljet, älkää väsykö tekemästä sitä, mikä hyvää on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 14, 'Mutta jos kuka ei tottele sitä, mitä me tässä kirjeessä olemme sanoneet, niin merkitkää hänet älkääkä seurustelko hänen kanssaan, että hän häpeäisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 15, 'Älkää kuitenkaan pitäkö häntä vihollisena, vaan neuvokaa niinkuin veljeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 16, 'Mutta itse rauhan Herra antakoon teille rauhan, aina ja kaikella tavalla. Herra olkoon kaikkien teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 17, 'Tervehdys minulta, Paavalilta, omakätisesti. Tämä on merkkinä jokaisessa kirjeessäni; näin minä kirjoitan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (70, 3, 18, 'Meidän Herramme Jeesuksen Kristuksen armo olkoon kaikkien teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 1, 'Paavali, Kristuksen Jeesuksen apostoli, Jumalan, meidän vapahtajamme, ja Kristuksen Jeesuksen, meidän toivomme, asettama,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 2, 'Timoteukselle, oikealle pojallensa uskossa. Armo, laupeus ja rauha Isältä Jumalalta ja Kristukselta Jeesukselta, meidän Herraltamme!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 3, 'Niinkuin minä Makedoniaan lähtiessäni kehoitin sinua jäämään Efesoon, käskeäksesi eräitä kavahtamaan, etteivät vieraita oppeja opettaisi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 4, 'eivätkä puuttuisi taruihin ja loppumattomiin sukuluetteloihin, jotka pikemmin edistävät turhaa mietiskelyä kuin Jumalan armotaloutta, joka perustuu uskoon, niin kehoitan nytkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 5, 'Mutta käskyn päämäärä on rakkaus, joka tulee puhtaasta sydämestä ja hyvästä omastatunnosta ja vilpittömästä uskosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 6, 'Muutamat ovat hairahtuneet niistä pois ja poikenneet turhiin jaarituksiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 7, 'tahtoen olla lainopettajia, vaikka eivät ymmärrä, mitä puhuvat ja minkä varmaksi väittävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 8, 'Mutta me tiedämme, että laki on hyvä, kun sitä lain mukaisesti käytetään');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 9, 'ja tiedetään, että lakia ei ole pantu vanhurskaalle, vaan laittomille ja niskoitteleville, jumalattomille ja syntisille, epähurskaille ja epäpyhille, isänsä tappajille ja äitinsä tappajille, murhamiehille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 10, 'haureellisille, miehimyksille, ihmiskauppiaille, valhettelijoille, valapattoisille ja kaikelle muulle, mikä on tervettä oppia vastaan-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 11, 'autuaan Jumalan kirkkauden evankeliumin mukaisesti, joka on minulle uskottu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 12, 'Minä kiitän häntä, joka minulle on voimaa antanut, Kristusta Jeesusta, meidän Herraamme, siitä, että hän katsoi minut uskolliseksi ja asetti palvelukseensa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 13, 'minut, entisen pilkkaajan ja vainoojan ja väkivallantekijän. Mutta minä sain laupeuden, koska olin tehnyt sitä tietämättömänä, epäuskossa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 14, 'ja meidän Herramme armo oli ylen runsas, vaikuttaen uskoa ja rakkautta, joka on Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 15, 'Varma on se sana ja kaikin puolin vastaanottamisen arvoinen, että Kristus Jeesus on tullut maailmaan syntisiä pelastamaan, joista minä olen suurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 16, 'Mutta sentähden minä sain laupeuden, että Jeesus Kristus minussa ennen muita osoittaisi kaiken pitkämielisyytensä, esikuvaksi niille, jotka tulevat uskomaan häneen, itsellensä iankaikkiseksi elämäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 17, 'Mutta iankaikkiselle kuninkaalle, katoamattomalle, näkymättömälle, ainoalle Jumalalle, kunnia ja kirkkaus aina ja iankaikkisesti! Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 18, 'Tämän käskyn minä annan sinun toimitettavaksesi, poikani Timoteus, aikaisempien, sinusta lausuttujen ennustusten mukaisesti, että niiden nojalla taistelisit jalon taistelun,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 19, 'säilyttäen uskon ja hyvän omantunnon, jonka eräät ovat hyljänneet ja uskossaan haaksirikkoon joutuneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 1, 20, 'Niitä ovat Hymeneus ja Aleksander, jotka minä olen antanut saatanan haltuun, kuritettaviksi, etteivät enää pilkkaisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 1, 'Minä kehoitan siis ennen kaikkea anomaan, rukoilemaan, pitämään esirukouksia ja kiittämään kaikkien ihmisten puolesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 2, 'kuningasten ja kaiken esivallan puolesta, että saisimme viettää rauhallista ja hiljaista elämää kaikessa jumalisuudessa ja kunniallisuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 3, 'Sillä se on hyvää ja otollista Jumalalle, meidän vapahtajallemme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 4, 'joka tahtoo, että kaikki ihmiset pelastuisivat ja tulisivat tuntemaan totuuden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 5, 'Sillä yksi on Jumala, yksi myös välimies Jumalan ja ihmisten välillä, ihminen Kristus Jeesus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 6, 'joka antoi itsensä lunnaiksi kaikkien edestä, josta todistus oli annettava aikanansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 7, 'ja sitä varten minä olen saarnaajaksi ja apostoliksi asetettu-minä puhun totta, en valhettele-pakanain opettajaksi uskossa ja totuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 8, 'Minä tahdon siis, että miehet rukoilevat, joka paikassa kohottaen pyhät kädet ilman vihaa ja epäilystä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 9, 'niin myös, että naiset ovat säädyllisessä puvussa, kaunistavat itseään kainosti ja siveästi, ei palmikoiduilla hiuksilla, ei kullalla, ei helmillä eikä kallisarvoisilla vaatteilla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 10, 'vaan hyvillä teoilla, niinkuin sopii naisille, jotka tunnustautuvat jumalaapelkääviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 11, 'Oppikoon nainen hiljaisuudessa, kaikin puolin alistuvaisena;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 12, 'mutta minä en salli, että vaimo opettaa, enkä että hän vallitsee miestänsä, vaan eläköön hän hiljaisuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 13, 'Sillä Aadam luotiin ensin, sitten Eeva;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 14, 'eikä Aadamia petetty, vaan nainen petettiin ja joutui rikkomukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 2, 15, 'Mutta hän on pelastuva lastensynnyttämisen kautta, jos hän pysyy uskossa ja rakkaudessa ja pyhityksessä ynnä siveydessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 1, 'Varma on tämä sana: jos joku pyrkii seurakunnan kaitsijan virkaan, niin hän haluaa jaloon toimeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 2, 'Niin tulee siis seurakunnan kaitsijan olla nuhteeton, yhden vaimon mies, raitis, maltillinen, säädyllinen, vieraanvarainen, taitava opettamaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 3, 'ei juomari, ei tappelija, vaan lempeä, ei riitaisa, ei rahanahne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 4, 'vaan sellainen, joka oman kotinsa hyvin hallitsee ja kaikella kunniallisuudella pitää lapsensa kuuliaisina;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 5, 'sillä jos joku ei osaa hallita omaa kotiansa, kuinka hän voi pitää huolta Jumalan seurakunnasta?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 6, 'Älköön hän olko äsken kääntynyt, ettei hän paisuisi ja joutuisi perkeleen tuomion alaiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 7, 'Ja hänellä tulee myös olla hyvä todistus ulkopuolella olevilta, ettei hän joutuisi häväistyksen alaiseksi eikä perkeleen paulaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 8, 'Niin myös seurakuntapalvelijain tulee olla arvokkaita, ei kaksikielisiä, ei paljon viinin nauttijoita, ei häpeällisen voiton pyytäjiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 9, 'vaan sellaisia, jotka pitävät uskon salaisuuden puhtaassa omassatunnossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 10, 'Mutta heitäkin koeteltakoon ensin, sitten palvelkoot, jos ovat nuhteettomat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 11, 'Samoin tulee vaimojen olla arvokkaita, ei panettelijoita, vaan raittiita, uskollisia kaikessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 12, 'Seurakuntapalvelija olkoon yhden vaimon mies, lapsensa ja kotinsa hyvin hallitseva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 13, 'Sillä ne, jotka ovat hyvin palvelleet, saavuttavat itselleen kunnioitettavan aseman ja suuren pelottomuuden uskossa, Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 14, 'Vaikka toivon pian pääseväni sinun tykösi, kirjoitan sinulle tämän,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 15, 'että, jos viivyn, tietäisit, miten tulee olla Jumalan huoneessa, joka on elävän Jumalan seurakunta, totuuden pylväs ja perustus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 3, 16, 'Ja tunnustetusti suuri on jumalisuuden salaisuus: Hän, joka on ilmestynyt lihassa, vanhurskautunut Hengessä, näyttäytynyt enkeleille, saarnattu pakanain keskuudessa, uskottu maailmassa, otettu ylös kirkkauteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 1, 'Mutta Henki sanoo selvästi, että tulevina aikoina moniaat luopuvat uskosta ja noudattavat villitseviä henkiä ja riivaajien oppeja');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 2, 'valheenpuhujain ulkokultaisuuden vaikutuksesta, joiden omatunto on poltinraudalla merkitty');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 3, 'ja jotka kieltävät menemästä naimisiin ja nauttimasta ruokia, mitkä Jumala on luonut niiden nautittavaksi kiitoksella, jotka uskovat ja ovat tulleet totuuden tuntemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 4, 'Sillä kaikki, minkä Jumala on luonut, on hyvää, eikä mikään ole hyljättävää, kun se kiitoksella vastaanotetaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 5, 'sillä se pyhitetään Jumalan sanalla ja rukouksella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 6, 'Kun tätä veljille opetat, niin olet hyvä Kristuksen Jeesuksen palvelija, joka ravitset itseäsi uskon ja sen hyvän opin sanoilla, jota olet noudattanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 7, 'Mutta epäpyhiä ämmäin taruja karta ja harjoita itseäsi jumalisuuteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 8, 'Sillä ruumiillisesta harjoituksesta on hyötyä vain vähään; mutta jumalisuudesta on hyötyä kaikkeen, koska sillä on elämän lupaus, sekä nykyisen että tulevaisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 9, 'Varma on se sana ja kaikin puolin vastaanottamisen arvoinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 10, 'Sillä siksi me vaivaa näemme ja kilvoittelemme, että olemme panneet toivomme elävään Jumalaan, joka on kaikkien ihmisten vapahtaja, varsinkin uskovien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 11, 'Tätä käske ja opeta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 12, 'Älköön kukaan nuoruuttasi katsoko ylen, vaan ole sinä uskovaisten esikuva puheessa, vaelluksessa, rakkaudessa, uskossa, puhtaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 13, 'Lue, kehoita ja opeta ahkerasti, kunnes minä tulen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 14, 'Älä laiminlyö armolahjaa, joka sinussa on ja joka sinulle annettiin profetian kautta, vanhinten pannessa kätensä sinun päällesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 15, 'Harrasta näitä, elä näissä, että edistymisesi olisi kaikkien nähtävissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 4, 16, 'Valvo itseäsi ja opetustasi, ole siinä kestävä; sillä jos sen teet, olet pelastava sekä itsesi että ne, jotka sinua kuulevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 1, 'Älä nuhtele kovasti vanhaa miestä, vaan neuvo niinkuin isää, nuorempia niinkuin veljiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 2, 'vanhoja naisia niinkuin äitejä, nuorempia niinkuin sisaria, kaikessa puhtaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 3, 'Kunnioita leskiä, jotka ovat oikeita leskiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 4, 'Mutta jos jollakin leskellä on lapsia tai lapsenlapsia, oppikoot nämä ensin hurskaasti hoitamaan omaa perhekuntaansa ja maksamaan, mitä ovat velkaa vanhemmilleen, sillä se on otollista Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 5, 'Oikea leski ja yksinäiseksi jäänyt panee toivonsa Jumalaan ja anoo ja rukoilee alinomaa, yötä päivää;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 6, 'mutta hekumoitseva on jo eläessään kuollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 7, 'Teroita tätäkin, että he olisivat nuhteettomat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 8, 'Mutta jos joku ei pidä huolta omaisistaan ja varsinkaan ei perhekuntalaisistaan, niin hän on kieltänyt uskon ja on uskotonta pahempi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 9, 'Luetteloon otettakoon ainoastaan semmoinen leski, joka ei ole kuuttakymmentä vuotta nuorempi ja joka on ollut yhden miehen vaimo,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 10, 'josta on todistettu, että hän on tehnyt hyviä töitä, on lapsia kasvattanut, vieraita holhonnut, pyhien jalkoja pessyt, ahdistettuja auttanut ja kaiken hyvän tekemistä harrastanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 11, 'Mutta nuoret lesket hylkää; sillä kun he himokkaiksi käyden vieraantuvat Kristuksesta, tahtovat he mennä naimisiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 12, 'ja ovat tuomion alaisia, koska ovat ensimmäisen uskonsa hyljänneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 13, 'He oppivat kylää kierrellessään vielä laiskoiksikin, eikä ainoastaan laiskoiksi, vaan myös juoruisiksi ja monitouhuisiksi ja sopimattomia puhumaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 14, 'Minä tahdon sentähden, että nuoret lesket menevät naimisiin, synnyttävät lapsia, hoitavat kotiansa eivätkä anna vastustajalle mitään aihetta solvaamiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 15, 'Sillä muutamat ovat jo kääntyneet pois seuraamaan saatanaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 16, 'Jos jollakin uskovaisella naisella on leskiä, niin pitäköön niistä huolen, älköönkä seurakuntaa rasitettako, että se voisi pitää huolta oikeista leskistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 17, 'Vanhimpia, jotka seurakuntaa hyvin hoitavat, pidettäköön kahdenkertaisen kunnian ansainneina, varsinkin niitä, jotka sanassa ja opetuksessa työtä tekevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 18, 'Sillä Raamattu sanoo: \"Älä sido puivan härän suuta\", ja: \"Työmies on palkkansa ansainnut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 19, 'Älä ota huomioosi syytettä vanhinta vastaan, ellei ole kahta tai kolmea todistajaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 20, 'Syntiä tekeviä nuhtele kaikkien kuullen, että muutkin pelkäisivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 21, 'Minä vannotan sinua Jumalan ja Kristuksen Jeesuksen ja valittujen enkelien edessä, että noudatat tätä, tekemättä ennakolta päätöstä ja ketään suosimatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 22, 'Älä ole liian kerkeä panemaan käsiäsi kenenkään päälle, äläkä antaudu osalliseksi muiden synteihin. Pidä itsesi puhtaana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 23, 'Älä enää juo vain vettä, vaan käytä vähän viiniä vatsasi tähden ja usein uudistuvien vaivojesi vuoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 24, 'Muutamien ihmisten synnit ovat ilmeiset ja joutuvat ennen tuomittaviksi, toisten taas seuraavat jäljestäpäin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 5, 25, 'samoin myös hyvät teot ovat ilmeiset, eivätkä nekään, jotka eivät ole ilmeisiä, voi salassa pysyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 1, 'Kaikki, jotka ovat orjina ikeen alla, pitäkööt isäntiänsä kaikkea kunnioitusta ansaitsevina, ettei Jumalan nimi ja oppi tulisi häväistyksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 2, 'Mutta ne, joilla on uskovaiset isännät, älkööt pitäkö heitä vähemmässä arvossa sentähden, että he ovat veljiä, vaan palvelkoot heitä sitä mieluummin, koska he ovat uskovia ja rakastettuja ja harrastavat hyväntekemistä. Tätä opeta ja tähän kehoita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 3, 'Jos joku muuta oppia opettaa eikä pitäydy meidän Herramme Jeesuksen Kristuksen terveisiin sanoihin eikä siihen oppiin, joka on jumalisuuden mukainen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 4, 'niin hän on paisunut eikä ymmärrä mitään, vaan on riitakysymyksien ja sanakiistojen kipeä, joista syntyy kateutta, riitaa, herjauksia, pahoja epäluuloja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 5, 'alituisia kinastuksia niiden ihmisten kesken, jotka ovat turmeltuneet mieleltään ja totuuden menettäneet ja jotka pitävät jumalisuutta keinona voiton saamiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 6, 'Ja suuri voitto onkin jumalisuus yhdessä tyytyväisyyden kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 7, 'Sillä me emme ole maailmaan mitään tuoneet, emme myös voi täältä mitään viedä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 8, 'mutta kun meillä on elatus ja vaatteet, niin tyytykäämme niihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 9, 'Mutta ne, jotka rikastua tahtovat, lankeavat kiusaukseen ja paulaan ja moniin mielettömiin ja vahingollisiin himoihin, jotka upottavat ihmiset turmioon ja kadotukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 10, 'Sillä rahan himo on kaiken pahan juuri; sitä haluten monet ovat eksyneet pois uskosta ja lävistäneet itsensä monella tuskalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 11, 'Mutta sinä, Jumalan ihminen, pakene semmoista, ja tavoita vanhurskautta, jumalisuutta, uskoa, rakkautta, kärsivällisyyttä, hiljaisuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 12, 'Kilvoittele hyvä uskon kilvoitus, tartu kiinni iankaikkiseen elämään, johon olet kutsuttu ja johon hyvällä tunnustuksella olet tunnustautunut monen todistajan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 13, 'Jumalan edessä, joka kaikki eläväksi tekee, ja Kristuksen Jeesuksen edessä, joka Pontius Pilatuksen edessä todisti, tunnustaen hyvän tunnustuksen, minä kehoitan sinua,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 14, 'että tahrattomasti ja moitteettomasti pidät käskyn meidän Herramme Jeesuksen Kristuksen ilmestymiseen saakka,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 15, 'jonka aikanansa on antava meidän nähdä se autuas ja ainoa valtias, kuningasten Kuningas ja herrain Herra,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 16, 'jolla ainoalla on kuolemattomuus; joka asuu valkeudessa, mihin ei kukaan taida tulla; jota yksikään ihminen ei ole nähnyt eikä voi nähdä-hänen olkoon kunnia ja iankaikkinen valta. Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 17, 'Kehoita niitä, jotka nykyisessä maailmanajassa ovat rikkaita, etteivät ylpeilisi eivätkä panisi toivoansa epävarmaan rikkauteen, vaan Jumalaan, joka runsaasti antaa meille kaikkea nautittavaksemme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 18, 'kehoita heitä, että tekevät hyvää, hyvissä töissä rikastuvat, ovat anteliaita ja omastansa jakelevat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 19, 'kooten itsellensä aarteen, hyvän perustuksen tulevaisuuden varalle, että saisivat todellisen elämän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 20, 'Oi Timoteus, talleta se, mikä sinulle on uskottu, ja vältä tiedon nimellä kulkevan valhetiedon epäpyhiä ja tyhjiä puheita ja vastaväitteitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (71, 6, 21, 'johon tunnustautuen muutamat ovat uskosta hairahtuneet. Armo olkoon teidän kanssanne!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 1, 'Paavali, Jumalan tahdosta Kristuksen Jeesuksen apostoli, lähetetty julistamaan lupausta siitä elämästä, joka on Kristuksessa Jeesuksessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 2, 'rakkaalle pojalleni Timoteukselle. Armo, laupeus ja rauha Isältä Jumalalta ja Kristukselta Jeesukselta, meidän Herraltamme!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 3, 'Minä kiitän Jumalaa, jota esivanhemmistani asti palvelen puhtaalla omallatunnolla-samoinkuin minä lakkaamatta muistan sinua rukouksissani öin ja päivin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 4, 'haluten, muistaessani kyyneleitäsi, saada sinua nähdä, että täyttyisin ilolla-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 5, 'kun mieleeni muistuu se vilpitön usko, joka sinulla on, joka ensin oli isoäidilläsi Looiksella ja äidilläsi Eunikellä ja joka, siitä olen varma, on sinullakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 6, 'Siitä syystä minä sinua muistutan virittämään palavaksi Jumalan armolahjan, joka sinussa on minun kätteni päällepanemisen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 7, 'Sillä Jumala ei ole antanut meille pelkuruuden henkeä, vaan voiman ja rakkauden ja raittiuden hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 8, 'Älä siis häpeä todistusta Herrastamme äläkä minua, hänen vankiaan, vaan kärsi yhdessä minun kanssani vaivaa evankeliumin tähden, sen mukaan kuin Jumala antaa voimaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 9, 'hän, joka on meidät pelastanut ja kutsunut pyhällä kutsumuksella, ei meidän tekojemme mukaan, vaan oman aivoituksensa ja armonsa mukaan, joka meille on annettu Kristuksessa Jeesuksessa ennen ikuisia aikoja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 10, 'mutta nyt ilmisaatettu meidän Vapahtajamme Kristuksen Jeesuksen ilmestymisen kautta, joka kukisti kuoleman ja toi valoon elämän ja katoamattomuuden evankeliumin kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 11, 'jonka julistajaksi ja apostoliksi ja opettajaksi minä olen asetettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 12, 'Siitä syystä minä myös näitä kärsin, enkä sitä häpeä; sillä minä tunnen hänet, johon minä uskon, ja olen varma siitä, että hän on voimallinen siihen päivään asti säilyttämään sen, mikä minulle on uskottu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 13, 'Ota esikuvaksi ne terveelliset sanat, jotka olet minulta kuullut, uskossa ja rakkaudessa, joka on Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 14, 'Säilytä se hyvä, mikä sinulle on uskottu, Pyhän Hengen kautta, joka meissä asuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 15, 'Sinä tiedät, että kaikki aasialaiset ovat kääntyneet minusta pois; niiden joukossa ovat Fygelus ja Hermogenes.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 16, 'Antakoon Herra laupeutta Onesiforuksen huonekunnalle, sillä usein hän on minua virvoittanut, eikä ole kahleitani hävennyt;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 17, 'vaan kun hän tuli Roomaan, etsi hän minua innokkaasti ja löysi minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 1, 18, 'Suokoon Herra, että hän löytää laupeuden Herran tykönä sinä päivänä. Ja kuinka suuria ne palvelukset olivat, joita hän teki Efesossa, sen sinä parhaiten tiedät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 1, 'Vahvistu siis, poikani, siinä armossa, joka on Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 2, 'Ja minkä olet kuullut minulta ja minkä monet ovat todistaneet, usko se luotettaville miehille, jotka sitten ovat soveliaita muitakin opettamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 3, 'Kärsi vaivaa niinkuin ainakin jalo Kristuksen Jeesuksen sotamies.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 4, 'Ei kukaan, joka sodassa palvelee, sekaannu elatuksen toimiin, sillä hän tahtoo olla mieliksi sille, joka on hänet palkannut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 5, 'Eihän sitäkään, joka kilpailee, seppelöidä, ellei hän kilpaile sääntöjen mukaisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 6, 'Peltomiehen, joka vaivaa näkee, tulee ennen muita päästä osalliseksi hedelmistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 7, 'Tarkkaa, mitä sanon; Herra on antava sinulle ymmärrystä kaikkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 8, 'Muista Jeesusta Kristusta, joka on kuolleista herätetty ja on Daavidin siementä minun evankeliumini mukaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 9, 'jonka julistamisessa minä kärsin vaivaa, kahleisiin asti, niinkuin pahantekijä; mutta Jumalan sana ei ole kahlehdittu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 10, 'Siitä syystä minä kärsin kaikki valittujen tähden, että hekin saavuttaisivat pelastuksen, joka on Kristuksessa Jeesuksessa, ynnä iankaikkisen kirkkauden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 11, 'Varma on tämä sana; sillä: jos olemme kuolleet yhdessä hänen kanssaan, saamme myös hänen kanssaan elää;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 12, 'jos kärsimme yhdessä, saamme hänen kanssaan myös hallita; jos kiellämme hänet, on hänkin kieltävä meidät;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 13, 'jos me olemme uskottomat, pysyy kuitenkin hän uskollisena; sillä itseänsä kieltää hän ei saata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 14, 'Muistuta tästä, ja teroita heille Jumalan edessä, etteivät kiistelisi sanoista, mikä ei ole miksikään hyödyksi, vaan niiden turmioksi, jotka kuulevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 15, 'Pyri osoittautumaan Jumalalle semmoiseksi, joka koetukset kestää, työntekijäksi, joka ei työtään häpeä, joka oikein jakelee totuuden sanaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 16, 'Mutta pysy erilläsi epäpyhistä ja tyhjistä puheista, sillä niiden puhujat menevät yhä pitemmälle jumalattomuudessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 17, 'ja heidän puheensa jäytää ympäristöään niinkuin syöpä. Niitä ovat Hymeneus ja Filetus,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 18, 'jotka ovat totuudesta eksyneet, kun sanovat, että ylösnousemus jo on tapahtunut, ja he turmelevat useiden uskon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 19, 'Kuitenkin Jumalan vahva perustus pysyy lujana, ja siinä on tämä sinetti: \"Herra tuntee omansa\", ja: \"Luopukoon vääryydestä jokainen, joka Herran nimeä mainitsee\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 20, 'Mutta suuressa talossa ei ole ainoastaan kulta-ja hopea-astioita, vaan myös puu-ja saviastioita, ja toiset ovat jaloa, toiset halpaa käyttöä varten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 21, 'Jos nyt joku puhdistaa itsensä tämänkaltaisista, tulee hänestä astia jaloa käyttöä varten, pyhitetty, isännälleen hyödyllinen, kaikkiin hyviin tekoihin valmis.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 22, 'Pakene nuoruuden himoja, harrasta vanhurskautta, uskoa, rakkautta, rauhaa niiden kanssa, jotka huutavat avuksensa Herraa puhtaasta sydämestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 23, 'Mutta vältä tyhmiä ja taitamattomia väittelyjä, sillä tiedäthän, että ne synnyttävät riitoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 24, 'Mutta Herran palvelijan ei sovi riidellä, vaan hänen tulee olla lempeä kaikkia kohtaan, kyetä opettamaan ja pahaa kärsimään;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 25, 'hänen tulee sävyisästi ojentaa vastustelijoita; ehkäpä Jumala antaa heille mielenmuutoksen, niin että tulevat tuntemaan totuuden');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 2, 26, 'ja selviävät perkeleen pauloista, joka on heidät vanginnut tahtoansa tekemään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 1, 'Mutta tiedä se, että viimeisinä päivinä on tuleva vaikeita aikoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 2, 'Sillä ihmiset ovat silloin itserakkaita, rahanahneita, kerskailijoita, ylpeitä, herjaajia, vanhemmilleen tottelemattomia, kiittämättömiä, epähurskaita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 3, 'rakkaudettomia, epäsopuisia, panettelijoita, hillittömiä, raakoja, hyvän vihamiehiä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 4, 'pettureita, väkivaltaisia, pöyhkeitä, hekumaa enemmän kuin Jumalaa rakastavia;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 5, 'heissä on jumalisuuden ulkokuori, mutta he kieltävät sen voiman. Senkaltaisia karta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 6, 'Sillä niitä ovat ne, jotka tungettelevat taloihin ja pauloihinsa kietovat syntien rasittamia ja monenlaisten himojen heiteltäviä naisparkoja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 7, 'jotka aina ovat opetusta ottamassa, eivätkä koskaan voi päästä totuuden tuntemiseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 8, 'Ja niinkuin Jannes ja Jambres vastustivat Moosesta, niin nuokin vastustavat totuutta, nuo mieleltään turmeltuneet ihmiset, jotka eivät uskonkoetuksissa kestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 9, 'Mutta he eivät pitemmälle edisty, sillä heidän mielettömyytensä on käyvä ilmeiseksi kaikille, niinkuin noidenkin mielettömyys kävi ilmi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 10, 'Mutta sinä olet seurannut minun opetustani, vaellustani, aivoitustani, uskoani, pitkämielisyyttäni, rakkauttani, kärsivällisyyttäni,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 11, 'vainoissa ja kärsimyksissä, samanlaisissa kuin minun osakseni tuli Antiokiassa, Ikonionissa ja Lystrassa. Mimmoisia vainoja olenkaan kärsinyt, ja kaikista Herra on minut pelastanut!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 12, 'Ja kaikki, jotka tahtovat elää jumalisesti Kristuksessa Jeesuksessa, joutuvat vainottaviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 13, 'Mutta pahat ihmiset ja petturit menevät yhä pitemmälle pahuudessa, eksyttäen ja eksyen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 14, 'Mutta pysy sinä siinä, minkä olet oppinut ja mistä olet varma, koska tiedät, keiltä olet sen oppinut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 15, 'ja koska jo lapsuudestasi saakka tunnet pyhät kirjoitukset, jotka voivat tehdä sinut viisaaksi, niin että pelastut uskon kautta, joka on Kristuksessa Jeesuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 16, 'Jokainen kirjoitus, joka on syntynyt Jumalan Hengen vaikutuksesta, on myös hyödyllinen opetukseksi, nuhteeksi, ojennukseksi, kasvatukseksi vanhurskaudessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 3, 17, 'että Jumalan ihminen olisi täydellinen, kaikkiin hyviin tekoihin valmistunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 1, 'Minä vannotan sinua Jumalan ja Kristuksen Jeesuksen edessä, joka on tuomitseva eläviä ja kuolleita, sekä hänen ilmestymisensä että hänen valtakuntansa kautta:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 2, 'saarnaa sanaa, astu esiin sopivalla ja sopimattomalla ajalla, nuhtele, varoita, kehoita, kaikella pitkämielisyydellä ja opetuksella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 3, 'Sillä aika tulee, jolloin he eivät kärsi tervettä oppia, vaan omien himojensa mukaan korvasyyhyynsä haalivat itselleen opettajia');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 4, 'ja kääntävät korvansa pois totuudesta ja kääntyvät taruihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 5, 'Mutta ole sinä raitis kaikessa, kärsi vaivaa, tee evankelistan työ, toimita virkasi täydellisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 6, 'Sillä minut jo uhrataan, ja minun lähtöni aika on jo tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 7, 'Minä olen hyvän kilvoituksen kilvoitellut, juoksun päättänyt, uskon säilyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 8, 'Tästedes on minulle talletettuna vanhurskauden seppele, jonka Herra, vanhurskas tuomari, on antava minulle sinä päivänä, eikä ainoastaan minulle, vaan myös kaikille, jotka hänen ilmestymistään rakastavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 9, 'Koeta päästä pian tulemaan luokseni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 10, 'Sillä tähän nykyiseen maailmaan rakastuneena jätti minut Deemas ja matkusti Tessalonikaan, Kreskes meni Galatiaan ja Tiitus Dalmatiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 11, 'Luukas yksin on minun kanssani. Ota Markus mukaasi ja tuo hänet tänne, sillä hän on minulle hyvin tarpeellinen palvelukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 12, 'Mutta Tykikuksen minä olen lähettänyt Efesoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 13, 'Tuo tullessasi päällysvaippa, jonka jätin Trooaaseen Karpuksen luo, ja kirjat, ennen kaikkea pergamentit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 14, 'Aleksander, vaskiseppä, on tehnyt minulle paljon pahaa; Herra on maksava hänelle hänen tekojensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 15, 'Kavahda sinäkin häntä, sillä hän on kovin vastustanut meidän sanojamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 16, 'Ensi kertaa puolustautuessani ei kukaan tullut avukseni, vaan kaikki jättivät minut; älköön sitä heille syyksi luettako.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 17, 'Mutta Herra auttoi minua ja vahvisti minua, että sanan julistaminen minun kauttani tulisi täydelleen suoritetuksi, ja kaikki pakanat sen kuulisivat; ja minä pelastuin jalopeuran kidasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 18, 'Ja Herra on vapahtava minut kaikesta ilkivallasta ja pelastava minut taivaalliseen valtakuntaansa; hänelle kunnia aina ja iankaikkisesti! Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 19, 'Tervehdys Priskalle ja Akylaalle ja Onesiforuksen huonekunnalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 20, 'Erastus jäi Korinttoon, mutta Trofimuksen minä jätin Miletoon sairastamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 21, 'Koeta päästä tulemaan ennen talvea. Tervehdyksen lähettävät sinulle Eubulus ja Pudes ja Linus ja Klaudia ja kaikki veljet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (72, 4, 22, 'Herra olkoon sinun henkesi kanssa. Armo olkoon teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 1, 'Paavali, Jumalan palvelija ja Jeesuksen Kristuksen apostoli Jumalan valittujen uskoa ja sen totuuden tuntemista varten, joka on jumalisuuden mukainen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 2, 'apostoli sen iankaikkisen elämän toivon perusteella, jonka Jumala, joka ei valhettele, on luvannut ennen ikuisia aikoja-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 3, 'mutta kun aika oli tullut, ilmoitti hän sanansa saarnassa, joka on uskottu minulle Jumalan, meidän vapahtajamme, käskyn mukaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 4, 'Tiitukselle, oikealle pojalleni yhteisen uskomme perusteella. Armo ja rauha Isältä Jumalalta ja meidän Vapahtajaltamme Kristukselta Jeesukselta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 5, 'Minä jätin sinut Kreettaan sitä varten, että järjestäisit, mitä vielä jäi järjestämättä, ja että asettaisit, niinkuin minä sinulle määräsin, joka kaupunkiin vanhimmat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 6, 'jos missä olisi joku nuhteeton, yhden vaimon mies, jonka lapset ovat uskovia, eivät irstaudesta syytettyjä eivätkä niskoittelevia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 7, 'Sillä seurakunnan kaitsijan on, niinkuin Jumalan huoneenhaltijan tulee, oltava nuhteeton, ei itserakas, ei pikavihainen, ei juomari, ei tappelija, ei häpeällisen voiton pyytäjä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 8, 'vaan vieraanvarainen, hyvää rakastava, maltillinen, oikeamielinen, pyhä, itsensähillitseväinen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 9, 'hänen tulee pysyä kiinni opinmukaisessa, luotettavassa sanassa, että olisi kykenevä sekä neuvomaan terveellä opilla että kumoamaan vastaansanojain väitteet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 10, 'Sillä paljon on niskoittelevia, turhanpuhujia ja eksyttäjiä, varsinkin ympärileikattujen joukossa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 11, 'semmoisilta on suu tukittava, sillä he kääntävät ylösalaisin kokonaisia huonekuntia opettamalla sopimattomia häpeällisen voiton vuoksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 12, 'Eräs heistä, heidän oma profeettansa, on sanonut: \"Petturi Kreetan mies, peto ilkeä, laiskurivatsa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 13, 'Tämä todistus on tosi; sentähden nuhtele heitä ankarasti, että tulisivat uskossa terveiksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 14, 'eivätkä kiinnittäisi huomiotansa juutalaisiin taruihin eikä totuudesta pois kääntyvien ihmisten käskyihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 15, 'Kaikki on puhdasta puhtaille; mutta saastaisille ja uskottomille ei mikään ole puhdasta, vaan heidän sekä mielensä että omatuntonsa on saastainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 1, 16, 'He väittävät tuntevansa Jumalan, mutta teoillaan he hänet kieltävät, sillä he ovat inhottavia ja tottelemattomia ja kaikkiin hyviin tekoihin kelvottomia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 1, 'Mutta sinä puhu sitä, mikä terveeseen oppiin soveltuu:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 2, 'vanhat miehet olkoot raittiit, arvokkaat, siveät ja uskossa, rakkaudessa ja kärsivällisyydessä terveet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 3, 'niin myös vanhat naiset olkoot käytöksessään niinkuin pyhien sopii, ei panettelijoita, ei paljon viinin orjia, vaan hyvään neuvojia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 4, 'voidakseen ohjata nuoria vaimoja rakastamaan miehiänsä ja lapsiansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 5, 'olemaan siveitä, puhtaita, kotinsa hoitajia, hyviä, miehilleen alamaisia, ettei Jumalan sana pilkatuksi tulisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 6, 'Nuorempia miehiä samoin kehoita käyttäytymään siveästi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 7, 'Aseta itsesi kaikessa hyvien tekojen esikuvaksi, olkoon opetuksesi puhdasta ja arvokasta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 8, 'ja puheesi tervettä ja moitteetonta, että vastustaja häpeäisi, kun hänellä ei ole meistä mitään pahaa sanottavana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 9, 'Kehoita palvelijoita olemaan isännilleen kaikessa alamaisia, heille mieliksi, etteivät vastustele,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 10, 'etteivät näpistele, vaan kaikin tavoin osoittavat vilpitöntä uskollisuutta, että he Jumalan, meidän vapahtajamme, opin kaikessa kaunistaisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 11, 'Sillä Jumalan armo on ilmestynyt pelastukseksi kaikille ihmisille');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 12, 'ja kasvattaa meitä, että me, hyljäten jumalattomuuden ja maailmalliset himot, eläisimme siveästi ja vanhurskaasti ja jumalisesti nykyisessä maailmanajassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 13, 'odottaessamme autuaallisen toivon täyttymistä ja suuren Jumalan ja Vapahtajamme Kristuksen Jeesuksen kirkkauden ilmestymistä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 14, 'hänen, joka antoi itsensä meidän edestämme lunastaakseen meidät kaikesta laittomuudesta ja puhdistaakseen itselleen omaisuudeksi kansan, joka hyviä tekoja ahkeroitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 2, 15, 'Puhu tätä ja kehoita ja nuhtele kaikella käskyvallalla. Älköön kukaan sinua halveksiko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 1, 'Muistuta heitä olemaan hallituksille ja esivalloille alamaiset, kuuliaiset, kaikkiin hyviin tekoihin valmiit,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 2, 'etteivät ketään herjaa, eivät riitele, vaan ovat lempeitä ja osoittavat kaikkea sävyisyyttä kaikkia ihmisiä kohtaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 3, 'Olimmehan mekin ennen ymmärtämättömiä, tottelemattomia, eksyksissä, moninaisten himojen ja hekumain orjia, elimme pahuudessa ja kateudessa, olimme inhottavia ja vihasimme toisiamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 4, 'Mutta kun Jumalan, meidän vapahtajamme, hyvyys ja ihmisrakkaus ilmestyi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 5, 'pelasti hän meidät, ei vanhurskaudessa tekemiemme tekojen ansiosta, vaan laupeutensa mukaan uudestisyntymisen peson ja Pyhän Hengen uudistuksen kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 6, 'jonka Hengen hän runsaasti vuodatti meihin meidän Vapahtajamme Jeesuksen Kristuksen kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 7, 'että me vanhurskautettuina hänen armonsa kautta tulisimme iankaikkisen elämän perillisiksi toivon mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 8, 'Tämä sana on varma, ja minä tahdon, että sinä näitä teroitat, niin että ne, jotka Jumalaan uskovat, ahkeroisivat hyvien tekojen harjoittamista. Nämä ovat hyviä ja hyödyllisiä ihmisille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 9, 'Mutta vältä mielettömiä riitakysymyksiä ja sukuluetteloita ja kinastelua ja kiistoja laista, sillä ne ovat hyödyttömiä ja turhia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 10, 'Harhaoppista ihmistä karta, varoitettuasi häntä kerran tai kahdesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 11, 'sillä sinä tiedät, että semmoinen ihminen on joutunut harhaan ja tekee syntiä, ja hän on itse itsensä tuominnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 12, 'Kun lähetän luoksesi Artemaan tai Tykikuksen, niin tule viipymättä minun tyköni Nikopoliin, sillä siellä olen päättänyt viettää talven.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 13, 'Varusta huolellisesti matkalle Zeenas, lainoppinut, ja Apollos, ettei heiltä mitään puuttuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 14, 'Oppikoot meikäläisetkin, tarpeen vaatiessa, harjoittamaan hyviä tekoja, etteivät jäisi hedelmättömiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (73, 3, 15, 'Tervehdyksen lähettävät sinulle kaikki, jotka ovat minun kanssani. Sano tervehdys niille, jotka pitävät meitä rakkaina uskossa. Armo olkoon kaikkien teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 1, 'Paavali, Kristuksen Jeesuksen vanki, ja veli Timoteus rakkaalle Filemonille, työtoverillemme,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 2, 'ja Appialle, sisarellemme, ja Arkippukselle, taistelutoverillemme, ja sinun kodissasi kokoontuvalle seurakunnalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 3, 'Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 4, 'Minä kiitän Jumalaani aina, muistaessani sinua rukouksissani,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 5, 'sillä minä olen kuullut sinun rakkaudestasi ja uskostasi, joka sinulla on Herraan Jeesukseen ja kaikkia pyhiä kohtaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 6, 'ja rukoukseni on, että sinun uskosi, se usko, joka on meille yhteinen, olisi väkevä kaiken hyvän tuntemisessa, mikä meillä Kristuksessa on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 7, 'Sillä minä olen saanut paljon iloa ja lohdutusta sinun rakkaudestasi, koska pyhien sydämet ovat virvoittuneet sinun kauttasi, veljeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 8, 'Sentähden, vaikka minulla Kristuksessa on paljon rohkeutta käskeä sinua tekemään, mitä tehdä tulee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 9, 'niin rakkauden tähden minä kuitenkin mieluummin pyydän, ollen tämmöinen kuin olen, minä vanha Paavali, ja nyt myös Kristuksen Jeesuksen vanki-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 10, 'pyydän sinua poikani puolesta, jonka minä kahleissani synnytin, Onesimuksen puolesta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 11, 'sinulle ennen hyödyttömän, mutta nyt sekä sinulle että minulle hyödyllisen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 12, 'hänet minä lähetän sinulle takaisin, hänet, se on: oman sydämeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 13, 'Olisin tahtonut pidättää hänet tykönäni, että hän sinun sijassasi olisi palvellut minua, joka olen evankeliumin tähden kahleissa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 14, 'mutta ilman sinun suostumustasi en tahtonut tehdä mitään, ettei hyvyytesi olisi ikäänkuin pakollinen, vaan vapaaehtoinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 15, 'Sillä ehkäpä hän sentähden joutui eroamaan sinusta ajaksi, että saisit hänet takaisin iäksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 16, 'ei enää orjana, vaan orjaa enempänä: rakkaana veljenä, ylen rakkaana jo minulle, kuinka paljoa enemmän sitten sinulle, sekä ihmisenä että Herran omana!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 17, 'Jos siis pidät minua toverinasi, niin ota hänet luoksesi niinkuin minut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 18, 'mutta jos hän on tehnyt sinulle jotakin vääryyttä tai on sinulle jotakin velkaa, niin pane se minun laskuuni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 19, 'Minä, Paavali, kirjoitan omalla kädelläni: \"Minä sen maksan\"; saattaisinpa sanoa: pane se omaan laskuusi; sillä sinä olet minulle velkaa oman itsesikin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 20, 'Niin, veljeni, jospa saisin sinusta hyötyä Herrassa; virvoita sydäntäni Kristuksessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 21, 'Luottaen kuuliaisuuteesi minä kirjoitan sinulle, ja minä tiedän, että sinä teet enemmänkin, kuin mitä sanon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 22, 'Lisäksi vielä: valmista minulle maja luonasi; toivon näet, että minut rukoustenne kautta lahjoitetaan teille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 23, 'Tervehdyksen lähettävät sinulle Epafras, minun vankitoverini Kristuksessa Jeesuksessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 24, 'Markus, Aristarkus, Deemas ja Luukas, jotka ovat minun työtovereitani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (74, 1, 25, 'Herran Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 1, 'Sittenkuin Jumala muinoin monesti ja monella tapaa oli puhunut isille profeettain kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 2, 'on hän näinä viimeisinä päivinä puhunut meille Pojan kautta, jonka hän on pannut kaiken perilliseksi, jonka kautta hän myös on maailman luonut');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 3, 'ja joka, ollen hänen kirkkautensa säteily ja hänen olemuksensa kuva ja kantaen kaikki voimansa sanalla, on, toimitettuaan puhdistuksen synneistä, istunut Majesteetin oikealle puolelle korkeuksissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 4, 'tullen enkeleitä niin paljoa korkeammaksi, kuin hänen perimänsä nimi on jalompi kuin heidän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 5, 'Sillä kenelle enkeleistä hän koskaan on sanonut: \"Sinä olet minun Poikani, tänä päivänä minä sinut synnytin\"; ja taas: \"Minä olen oleva hänen Isänsä, ja hän on oleva minun Poikani\"?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 6, 'Ja siitä, kun hän jälleen tuo esikoisensa maailmaan, hän sanoo: \"Ja kumartakoot häntä kaikki Jumalan enkelit\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 7, 'Ja enkeleistä hän sanoo: \"Hän tekee enkelinsä tuuliksi ja palvelijansa tulen liekiksi\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 8, 'mutta Pojasta: \"Jumala, sinun valtaistuimesi pysyy aina ja iankaikkisesti, ja sinun valtakuntasi valtikka on oikeuden valtikka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 9, 'Sinä rakastit vanhurskautta ja vihasit laittomuutta; sentähden on Jumala, sinun Jumalasi, voidellut sinua iloöljyllä, enemmän kuin sinun osaveljiäsi.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 10, 'Ja: \"Sinä, Herra, olet alussa maan perustanut, ja taivaat ovat sinun kättesi tekoja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 11, 'ne katoavat, mutta sinä pysyt, ja ne vanhenevat kaikki niinkuin vaate,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 12, 'ja niinkuin vaipan sinä ne käärit, niinkuin vaatteen, ja ne muuttuvat; mutta sinä olet sama, eivätkä sinun vuotesi lopu\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 13, 'Kenelle enkeleistä hän koskaan on sanonut: \"Istu minun oikealle puolelleni, kunnes minä panen sinun vihollisesi sinun jalkojesi astinlaudaksi\"?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 1, 14, 'Eivätkö he kaikki ole palvelevia henkiä, palvelukseen lähetettyjä niitä varten, jotka saavat autuuden periä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 1, 'Sentähden tulee meidän sitä tarkemmin ottaa vaari siitä, mitä olemme kuulleet, ettemme vain kulkeutuisi sen ohitse.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 2, 'Sillä jos enkelien kautta puhuttu sana pysyi lujana, ja jokainen rikkomus ja tottelemattomuus sai oikeudenmukaisen palkkansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 3, 'kuinka me voimme päästä pakoon, jos emme välitä tuosta niin suuresta pelastuksesta, jonka Herra alkuaan julisti ja joka niiden vahvistamana, jotka olivat sen kuulleet, saatettiin meille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 4, 'kun Jumala yhdessä heidän kanssaan todisti tunnusmerkeillä ja ihmeillä ja moninaisilla väkevillä teoilla ja jakamalla Pyhää Henkeä tahtonsa mukaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 5, 'Sillä enkelien alle hän ei alistanut tulevaa maailmaa, josta me puhumme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 6, 'Vaan joku on jossakin paikassa todistanut, sanoen: \"Mikä on ihminen, että sinä häntä muistat, tai ihmisen poika, että pidät hänestä huolen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 7, 'Sinä teit hänet vähäksi aikaa enkeleitä halvemmaksi, kirkkaudella ja kunnialla sinä hänet seppelöitsit, ja sinä panit hänet hallitsemaan kättesi tekoja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 8, 'asetit kaikki hänen jalkojensa alle.\" Sillä, asettaessaan kaikki hänen valtansa alle, hän ei jättänyt mitään hänen allensa alistamatta. Mutta nyt emme vielä näe kaikkea hänen valtansa alle asetetuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 9, 'Mutta hänet, joka vähäksi aikaa oli tehty enkeleitä halvemmaksi, Jeesuksen, me näemme hänen kuolemansa kärsimyksen tähden kirkkaudella ja kunnialla seppelöidyksi, että hän Jumalan armosta olisi kaikkien edestä joutunut maistamaan kuolemaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 10, 'Sillä hänen, jonka tähden kaikki on ja jonka kautta kaikki on, sopi, saattaessaan paljon lapsia kirkkauteen, kärsimysten kautta tehdä heidän pelastuksensa päämies täydelliseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 11, 'Sillä sekä hän, joka pyhittää, että ne, jotka pyhitetään, ovat kaikki alkuisin yhdestä. Sentähden hän ei häpeä kutsua heitä veljiksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 12, 'kun hän sanoo: \"Minä julistan sinun nimeäsi veljilleni, ylistän sinua seurakunnan keskellä\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 13, 'ja taas: \"Minä panen uskallukseni häneen\"; ja taas: \"Katso, minä ja lapset, jotka Jumala on minulle antanut!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 14, 'Koska siis lapsilla on veri ja liha, tuli hänkin niistä yhtäläisellä tavalla osalliseksi, että hän kuoleman kautta kukistaisi sen, jolla oli kuolema vallassaan, se on: perkeleen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 15, 'ja vapauttaisi kaikki ne, jotka kuoleman pelosta kautta koko elämänsä olivat olleet orjuuden alaisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 16, 'Sillä ei hän ota huomaansa enkeleitä, vaan Aabrahamin siemenen hän ottaa huomaansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 17, 'Sentähden piti hänen kaikessa tuleman veljiensä kaltaiseksi, että hänestä tulisi laupias ja uskollinen ylimmäinen pappi tehtävissään Jumalan edessä, sovittaakseen kansan synnit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 2, 18, 'Sillä sentähden, että hän itse on kärsinyt ja ollut kiusattu, voi hän kiusattuja auttaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 1, 'Sentähden, pyhät veljet, jotka olette taivaallisesta kutsumuksesta osalliset, kiinnittäkää mielenne meidän tunnustuksemme apostoliin ja ylimmäiseen pappiin, Jeesukseen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 2, 'joka on uskollinen asettajalleen, niinkuin Mooseskin oli \"uskollinen koko hänen huoneessansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 3, 'Sillä hänen on Moosekseen verraten katsottu ansaitsevan niin paljoa suuremman kirkkauden, kuin huoneen rakentajan kunnia on suurempi kuin huoneen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 4, 'Sillä jokainen huone on jonkun rakentama, mutta kaiken rakentaja on Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 5, 'Ja Mooses tosin oli \"palvelijana uskollinen koko hänen huoneessansa\", todistukseksi siitä, mikä vastedes piti sanottaman,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 6, 'mutta Kristus on uskollinen Poikana, hänen huoneensa haltijana; ja hänen huoneensa olemme me, jos loppuun asti pidämme vahvana toivon rohkeuden ja kerskauksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 7, 'Sentähden, niinkuin Pyhä Henki sanoo: \"Tänä päivänä, jos te kuulette hänen äänensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 8, 'Älkää paaduttako sydämiänne, niinkuin teitte katkeroituksessa, kiusauksen päivänä erämaassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 9, 'jossa teidän isänne minua kiusasivat ja koettelivat, vaikka olivat nähneet minun tekojani neljäkymmentä vuotta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 10, 'sentähden minä vihastuin tähän sukupolveen ja sanoin: \'Aina he eksyvät sydämessään\'; mutta he eivät oppineet tuntemaan minun teitäni;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 11, 'ja niin minä vihassani vannoin: \'He eivät pääse minun lepooni\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 12, 'Katsokaa, veljet, ettei vain kenelläkään teistä ole paha, epäuskoinen sydän, niin että hän luopuu elävästä Jumalasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 13, 'vaan kehoittakaa toisianne joka päivä, niin kauan kuin sanotaan: \"tänä päivänä\", ettei teistä kukaan synnin pettämänä paatuisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 14, 'sillä me olemme tulleet osallisiksi Kristuksesta, kunhan vain pysymme luottamuksessa, joka meillä alussa oli, vahvoina loppuun asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 15, 'Kun sanotaan: \"Tänä päivänä, jos te kuulette hänen äänensä, älkää paaduttako sydämiänne, niinkuin teitte katkeroituksessa\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 16, 'ketkä sitten, vaikka kuulivat, katkeroittivat hänet? Eivätkö kaikki, jotka olivat Mooseksen johdolla lähteneet Egyptistä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 17, 'Mutta keihin hän oli vihastunut neljäkymmentä vuotta? Eikö niihin, jotka olivat syntiä tehneet, joiden ruumiit kaatuivat erämaahan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 18, 'Ja keille hän vannoi, etteivät he pääse hänen lepoonsa? Eikö tottelemattomille?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 3, 19, 'Ja niin me näemme, että he epäuskon tähden eivät voineet siihen päästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 1, 'Varokaamme siis, koska lupaus päästä hänen lepoonsa vielä pysyy varmana, ettei vain havaittaisi kenenkään teistä jääneen taipaleelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 2, 'Sillä hyvä sanoma on julistettu meille niinkuin heillekin; mutta heidän kuulemansa sana ei heitä hyödyttänyt, koska se ei uskossa sulautunut niihin, jotka sen kuulivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 3, 'Sillä me pääsemme lepoon, me, jotka tulimme uskoon, niinkuin hän on sanonut: \"Ja niin minä vihassani vannoin: \'He eivät pääse minun lepooni\'\", vaikka hänen tekonsa olivat valmiina maailman perustamisesta asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 4, 'Sillä hän on jossakin sanonut seitsemännestä päivästä näin: \"Ja Jumala lepäsi seitsemäntenä päivänä kaikista teoistansa\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 5, 'ja tässä taas: \"He eivät pääse minun lepooni\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 6, 'Koska siis varmana pysyy, että muutamat pääsevät siihen, ja ne, joille hyvä sanoma ensin julistettiin, eivät päässeet siihen tottelemattomuuden tähden,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 7, 'niin hän taas määrää päivän, \"tämän päivän\", sanomalla Daavidin kautta niin pitkän ajan jälkeen, niinkuin ennen on sanottu: \"Tänä päivänä, jos te kuulette hänen äänensä, älkää paaduttako sydämiänne\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 8, 'Sillä jos Joosua olisi saattanut heidät lepoon, niin hän ei puhuisi toisesta, senjälkeisestä päivästä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 9, 'Niin on Jumalan kansalle sapatinlepo varmasti tuleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 10, 'Sillä joka on päässyt hänen lepoonsa, on saanut levon teoistaan, hänkin, niinkuin Jumala omista teoistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 11, 'Ahkeroikaamme siis päästä siihen lepoon, ettei kukaan lankeaisi seuraamaan samaa tottelemattomuuden esimerkkiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 12, 'Sillä Jumalan sana on elävä ja voimallinen ja terävämpi kuin mikään kaksiteräinen miekka ja tunkee lävitse, kunnes se erottaa sielun ja hengen, nivelet sekä ytimet, ja on sydämen ajatusten ja aivoitusten tuomitsija;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 13, 'eikä mikään luotu ole hänelle näkymätön, vaan kaikki on alastonta ja paljastettua hänen silmäinsä edessä, jolle meidän on tehtävä tili.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 14, 'Kun meillä siis on suuri ylimmäinen pappi, läpi taivasten kulkenut, Jeesus, Jumalan Poika, niin pitäkäämme kiinni tunnustuksesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 15, 'Sillä ei meillä ole sellainen ylimmäinen pappi, joka ei voi sääliä meidän heikkouksiamme, vaan joka on ollut kaikessa kiusattu samalla lailla kuin mekin, kuitenkin ilman syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 4, 16, 'Käykäämme sentähden uskalluksella armon istuimen eteen, että saisimme laupeuden ja löytäisimme armon, avuksemme oikeaan aikaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 1, 'Sillä jokainen ylimmäinen pappi, ollen ihmisten joukosta otettu, asetetaan ihmisten puolesta toimittamaan sitä, mikä Jumalalle tulee, uhraamaan lahjoja ja uhreja syntien edestä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 2, 'ja hän voi säälien kohdella tietämättömiä ja eksyviä, koska hän itsekin on heikkouden alainen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 3, 'ja tämän heikkoutensa tähden hänen täytyy, samoinkuin kansan puolesta, niin itsensäkin puolesta uhrata syntien edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 4, 'Eikä kukaan sitä arvoa itselleen ota, vaan Jumala kutsuu hänet niinkuin Aaroninkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 5, 'Niinpä Kristuskaan ei itse korottanut itseänsä ylimmäisen papin kunniaan, vaan hän, joka sanoi hänelle: \"Sinä olet minun Poikani, tänä päivänä minä sinut synnytin\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 6, 'niinkuin hän toisessakin paikassa sanoo: \"Sinä olet pappi iankaikkisesti Melkisedekin järjestyksen mukaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 7, 'Ja lihansa päivinä hän väkevällä huudolla ja kyynelillä uhrasi rukouksia ja anomuksia sille, joka voi hänet kuolemasta pelastaa; ja hänen rukouksensa kuultiin hänen jumalanpelkonsa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 8, 'Ja niin hän, vaikka oli Poika, oppi siitä, mitä hän kärsi, kuuliaisuuden,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 9, 'ja kun oli täydelliseksi tullut, tuli hän iankaikkisen autuuden aikaansaajaksi kaikille, jotka ovat hänelle kuuliaiset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 10, 'hän, jota Jumala nimittää \"ylimmäiseksi papiksi Melkisedekin järjestyksen mukaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 11, 'Tästä meillä on paljon sanottavaa, ja sitä on vaikea selittää, koska olette käyneet hitaiksi kuulemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 12, 'Sillä te, joiden olisi jo aika olla opettajia, olette taas sen tarpeessa, että teille opetetaan Jumalan sanojen ensimmäisiä alkeita; te olette tulleet maitoa tarvitseviksi, ei vahvaa ruokaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 13, 'Sillä jokainen, joka vielä nauttii maitoa, on kokematon vanhurskauden sanassa, sillä hän on lapsi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 5, 14, 'mutta vahva ruoka on täysi-ikäisiä varten, niitä varten, joiden aistit tottumuksesta ovat harjaantuneet erottamaan hyvän pahasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 1, 'Jättäkäämme sentähden Kristuksen opin alkeet ja pyrkikäämme täydellisyyteen, ryhtymättä taas uudestaan laskemaan perustusta: parannusta kuolleista töistä ja uskoa Jumalaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 2, 'oppia kasteista ja kätten päällepanemisesta, kuolleitten ylösnousemisesta ja iankaikkisesta tuomiosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 3, 'Ja niin me tahdomme tehdä, jos vain Jumala sallii.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 4, 'Sillä mahdotonta on niitä, jotka kerran ovat valistetut ja taivaallista lahjaa maistaneet ja Pyhästä Hengestä osallisiksi tulleet');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 5, 'ja maistaneet Jumalan hyvää sanaa ja tulevan maailmanajan voimia,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 6, 'ja sitten ovat luopuneet-taas uudistaa parannukseen, he kun jälleen itsellensä ristiinnaulitsevat Jumalan Pojan ja häntä julki häpäisevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 7, 'Sillä maa, joka särpii sisäänsä sen päälle usein tulevan sateen ja kantaa kasvun hyödyksi niille, joita varten sitä viljelläänkin, saa siunauksen Jumalalta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 8, 'mutta se, joka tuottaa orjantappuroita ja ohdakkeita, on kelvoton ja lähellä kirousta, ja sen loppu on, että se poltetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 9, 'Mutta teistä, rakkaat, uskomme sitä, mikä on parempaa ja mikä koituu teille pelastukseksi-vaikka puhummekin näin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 10, 'Sillä Jumala ei ole väärämielinen, niin että hän unhottaisi teidän työnne ja rakkautenne, jota olette osoittaneet hänen nimeänsä kohtaan, kun olette palvelleet pyhiä ja vielä palvelette.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 11, 'Mutta me halajamme sitä, että kukin teistä osoittaa samaa intoa, säilyttääkseen toivon varmuuden loppuun asti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 12, 'ettette kävisi veltoiksi, vaan että teistä tulisi niiden seuraajia, jotka uskon ja kärsivällisyyden kautta perivät sen, mikä luvattu on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 13, 'Sillä kun Jumala oli antanut lupauksen Aabrahamille, vannoi hän itse kauttansa, koska hänellä ei ollut ketään suurempaa, kenen kautta vannoa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 14, 'ja sanoi: \"Totisesti, siunaamalla minä sinut siunaan, ja enentämällä minä sinut enennän\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 15, 'ja näin Aabraham, kärsivällisesti odotettuaan, sai, mitä luvattu oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 16, 'Sillä ihmiset vannovat suurempansa kautta, ja vala on heille asian vahvistus ja tekee lopun kaikista vastaväitteistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 17, 'Sentähden, kun Jumala lupauksen perillisille vielä tehokkaammin tahtoi osoittaa, että hänen päätöksensä on muuttumaton, vakuutti hän sen valalla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 18, 'että me näistä kahdesta muuttumattomasta asiasta, joissa Jumala ei ole voinut valhetella, saisimme voimallisen kehoituksen, me, jotka olemme paenneet pitämään kiinni edessämme olevasta toivosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 19, 'Se toivo meille on ikäänkuin sielun ankkuri, varma ja luja, joka ulottuu esiripun sisäpuolelle asti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 6, 20, 'jonne Jeesus edelläjuoksijana meidän puolestamme on mennyt, tultuaan ylimmäiseksi papiksi Melkisedekin järjestyksen mukaan, iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 1, 'Sillä tämä Melkisedek, Saalemin kuningas, Jumalan, Korkeimman, pappi, joka meni Aabrahamia vastaan, hänen palatessaan kuninkaita voittamasta, ja siunasi hänet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 2, 'jolle Aabraham myös antoi kymmenykset kaikesta ja joka ensiksi, niinkuin hänen nimensäkin merkitsee, on \"vanhurskauden kuningas\" ja sen lisäksi vielä \"Saalemin kuningas\", se on \"rauhan kuningas\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 3, 'jolla ei ole isää, ei äitiä, ei sukua, ei päivien alkua eikä elämän loppua, mutta joka on Jumalan Poikaan verrattava-hän pysyy pappina ainaisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 4, 'Katsokaa, kuinka suuri hän on, jolle itse kantaisä Aabraham antoi kymmenykset parhaimmasta saaliistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 5, 'Onhan niillä Leevin pojista, jotka saavat pappeuden, käsky lain mukaan ottaa kymmenyksiä kansalta, se on veljiltään, vaikka nämä ovatkin Aabrahamin kupeista lähteneet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 6, 'mutta hän, jonka sukua ei johdeta heistä, otti kymmenykset Aabrahamilta ja siunasi sen, jolla oli lupaukset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 7, 'Mutta kieltämätöntä on, että halvempi saa siunauksen paremmaltaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 8, 'Ja täällä kuolevaiset ihmiset ottavat kymmenyksiä, mutta siellä se, jonka todistetaan elävän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 9, 'Ja Aabrahamin kautta, niin sanoakseni, on Leevikin, joka kymmenyksiä ottaa, maksanut kymmenyksiä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 10, 'sillä hän oli vielä isänsä kupeissa, kun Melkisedek meni tätä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 11, 'Jos siis täydellisyys olisi saavutettu leeviläisen pappeuden kautta, sillä tähän on kansa laissa sidottu, miksi sitten oli tarpeen, että nousi toinen pappi Melkisedekin järjestyksen mukaan eikä tullut nimitetyksi Aaronin järjestyksen mukaan?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 12, 'Sillä pappeuden muuttuessa tapahtuu välttämättä myös lain muutos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 13, 'Sillä se, josta tämä sanotaan, oli toista sukukuntaa, josta ei kukaan ole alttaritointa hoitanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 14, 'Onhan tunnettua, että meidän Herramme on noussut Juudasta, jonka sukukunnan pappeudesta Mooses ei ole mitään puhunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 15, 'Ja tämä käy vielä paljoa selvemmäksi, kun nousee toinen pappi, Melkisedekin kaltainen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 16, 'joka ei ole siksi tullut lihallisen käskyn lain mukaan, vaan katoamattoman elämän voimasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 17, 'Sillä hänestä todistetaan: \"Sinä olet pappi iankaikkisesti Melkisedekin järjestyksen mukaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 18, 'Täten kyllä entinen säädös kumotaan, koska se oli voimaton ja hyödytön');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 19, '-sillä laki ei tehnyt mitään täydelliseksi-mutta sijaan tulee parempi toivo, jonka kautta me lähestymme Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 20, 'Ja niinkuin tämä ei tapahtunut ilman valan vannomista-nuo taas ovat papeiksi tulleet ilman heistä vannottua valaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 21, 'mutta tämä hänestä vannotulla valalla, sen asettamana, joka hänelle sanoi: \"Herra on vannonut eikä ole katuva: \'Sinä olet pappi iankaikkisesti\'\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 22, 'niin on myös se liitto parempi, jonka takaajaksi Jeesus on tullut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 23, 'Ja noita toisia pappeja on tullut useampia, koska kuolema ei sallinut heidän pysyä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 24, 'mutta tällä on katoamaton pappeus, sentähden että hän pysyy iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 25, 'jonka tähden hän myös voi täydellisesti pelastaa ne, jotka hänen kauttaan Jumalan tykö tulevat, koska hän aina elää rukoillakseen heidän puolestansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 26, 'Senkaltainen ylimmäinen pappi meille sopikin: pyhä, viaton, tahraton, syntisistä erotettu ja taivaita korkeammaksi tullut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 27, 'jonka ei joka päivä ole tarvis, niinkuin ylimmäisten pappien, ensiksi uhrata omien syntiensä edestä ja sitten kansan; sillä tämän hän teki kerta kaikkiaan, uhratessaan itsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 7, 28, 'Sillä laki asettaa ylimmäisiksi papeiksi ihmisiä, jotka ovat heikkoja, mutta valan sana, joka on myöhäisempi kuin laki, asettaa Pojan, iankaikkisesti täydelliseksi tulleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 1, 'Mutta pääkohta siinä, mistä me puhumme, on tämä: meillä on sellainen ylimmäinen pappi, joka istuu Majesteetin valtaistuimen oikealla puolella taivaissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 2, 'tehdäkseen pappispalvelusta kaikkeinpyhimmässä, siinä oikeassa majassa, jonka on rakentanut Herra eikä ihminen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 3, 'Sillä jokainen ylimmäinen pappi asetetaan uhraamaan lahjoja ja uhreja, jonka tähden on välttämätöntä, että tälläkin on jotakin uhraamista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 4, 'Jos hän siis olisi maan päällä, ei hän olisikaan pappi, koska jo ovat olemassa ne, jotka lain mukaan esiinkantavat lahjoja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 5, 'ja jotka palvelevat siinä, mikä on taivaallisten kuva ja varjo, niinkuin ilmoitettiin Moosekselle, kun hänen oli valmistettava maja. Sillä hänelle sanottiin: \"Katso, että teet kaikki sen kaavan mukaan, joka sinulle vuorella näytettiin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 6, 'Mutta tämä taas on saanut niin paljoa jalomman viran, kuin hän on myös paremman liiton välimies, liiton, joka on paremmille lupauksille perustettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 7, 'Sillä jos ensimmäinen liitto olisi ollut moitteeton, ei olisi etsitty sijaa toiselle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 8, 'Sillä moittien heitä hän sanoo: \"Katso, päivät tulevat, sanoo Herra, jolloin minä teen Israelin heimon ja Juudan heimon kanssa uuden liiton,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 9, 'en sellaista liittoa kuin se, jonka minä tein heidän isäinsä kanssa silloin, kun minä tartuin heidän käteensä ja vein heidät pois Egyptin maasta. Sillä he eivät pysyneet minun liitossani, ja niin en minäkään heistä huolinut, sanoo Herra.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 10, 'Sillä tämä on se liitto, jonka minä teen Israelin heimon kanssa näiden päivien jälkeen, sanoo Herra: Minä panen lakini heidän mieleensä, ja kirjoitan ne heidän sydämiinsä, ja niin minä olen heidän Jumalansa, ja he ovat minun kansani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 11, 'Ja silloin ei enää kukaan opeta kansalaistaan eikä veli veljeään sanoen: \'Tunne Herra\'; sillä he kaikki, pienimmästä suurimpaan, tuntevat minut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 12, 'Sillä minä annan anteeksi heidän vääryytensä enkä enää muista heidän syntejänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 8, 13, 'Sanoessaan \"uuden\" hän on julistanut ensimmäisen liiton vanhentuneeksi; mutta se, mikä vanhenee ja käy iälliseksi, on lähellä häviämistään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 1, 'Olihan tosin ensimmäiselläkin liitolla jumalanpalvelussäännöt ja maallinen pyhäkkö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 2, 'Sillä maja oli valmistettu niin, että siinä oli etumainen maja, jossa oli sekä lampunjalka että pöytä ja näkyleivät, ja sen nimi on \"pyhä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 3, 'Mutta toisen esiripun takana oli se maja, jonka nimi on \"kaikkeinpyhin\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 4, 'siinä oli kultainen suitsutusalttari ja liiton arkki, yltympäri kullalla päällystetty, jossa säilytettiin kultainen mannaa sisältävä astia ja Aaronin viheriöinyt sauva ja liiton taulut,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 5, 'ja arkin päällä kirkkauden kerubit varjostamassa armoistuinta. Mutta näistä nyt ei ole syytä puhua kustakin erikseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 6, 'Kun nyt kaikki on näin järjestetty, menevät papit joka aika etumaiseen majaan jumalanpalvelusta toimittamaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 7, 'mutta toiseen majaan menee ainoastaan ylimmäinen pappi kerran vuodessa, ei ilman verta, jonka hän uhraa itsensä edestä ja kansan tahattomien syntien edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 8, 'Näin Pyhä Henki osoittaa, että tie kaikkeinpyhimpään vielä on ilmoittamatta, niin kauan kuin etumainen maja vielä seisoo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 9, 'Tämä on nykyistä aikaa tarkoittava vertauskuva, ja sen mukaisesti uhrataan lahjoja ja uhreja, jotka eivät kykene tekemään täydelliseksi omassatunnossaan sitä, joka jumalanpalvelusta toimittaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 10, 'vaan jotka, niinkuin ruuat ja juomat ja erilaiset pesotkin, ovat ainoastaan lihan sääntöjä, jotka ovat voimassa uuden järjestyksen aikaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 11, 'Mutta kun Kristus tuli tulevaisen hyvän ylimmäiseksi papiksi, niin hän suuremman ja täydellisemmän majan kautta, joka ei ole käsillä tehty, se on: joka ei ole tätä luomakuntaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 12, 'meni, ei kauristen ja vasikkain veren kautta, vaan oman verensä kautta kerta kaikkiaan kaikkeinpyhimpään ja sai aikaan iankaikkisen lunastuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 13, 'Sillä jos kauristen ja härkäin veri ja hiehon tuhka, saastaisten päälle vihmottuna, pyhittää lihanpuhtauteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 14, 'kuinka paljoa enemmän on Kristuksen veri, hänen, joka iankaikkisen Hengen kautta uhrasi itsensä viattomana Jumalalle, puhdistava meidän omantuntomme kuolleista teoista palvelemaan elävää Jumalaa!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 15, 'Ja sentähden hän on uuden liiton välimies, että, koska hänen kuolemansa on tapahtunut lunastukseksi ensimmäisen liiton aikuisista rikkomuksista, ne, jotka ovat kutsutut, saisivat luvatun iankaikkisen perinnön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 16, 'Sillä missä on testamentti, siinä on sen tekijän kuolema toteennäytettävä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 17, 'sillä vasta kuoleman jälkeen testamentti on pitävä, koska se ei milloinkaan ole voimassa tekijänsä eläessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 18, 'Sentähden ei myöskään ensimmäistä liittoa verettä vihitty.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 19, 'Sillä kun Mooses oli kaikelle kansalle julkilukenut kaikki käskyt, niinkuin ne laissa kuuluvat, otti hän vasikkain ja kauristen veren ynnä vettä ja purppuravillaa ja isopin ja vihmoi sekä itse kirjan että kaiken kansan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 20, 'sanoen: \"Tämä on sen liiton veri, jonka Jumala on teille säätänyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 21, 'Ja samoin hän verellä vihmoi myös majan ja kaikki palvelukseen kuuluvat esineet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 22, 'Niin puhdistetaan lain mukaan miltei kaikki verellä, ja ilman verenvuodatusta ei tapahdu anteeksiantamista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 23, 'On siis välttämätöntä, että taivaallisten kuvat tällä tavalla puhdistetaan, mutta että taivaalliset itse puhdistetaan paremmilla uhreilla kuin nämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 24, 'Sillä Kristus ei mennyt käsillä tehtyyn kaikkeinpyhimpään, joka vain on sen oikean kuva, vaan itse taivaaseen, nyt ilmestyäkseen Jumalan kasvojen eteen meidän hyväksemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 25, 'Eikä hän mennyt uhratakseen itseänsä monta kertaa, niinkuin ylimmäinen pappi joka vuosi menee kaikkeinpyhimpään, vierasta verta mukanaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 26, 'sillä muutoin hänen olisi pitänyt kärsimän monta kertaa maailman perustamisesta asti; mutta nyt hän on yhden ainoan kerran maailmanaikojen lopulla ilmestynyt, poistaakseen synnin uhraamalla itsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 27, 'Ja samoinkuin ihmisille on määrätty, että heidän kerran on kuoleminen, mutta senjälkeen tulee tuomio,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 9, 28, 'samoin Kristuskin, kerran uhrattuna ottaakseen pois monien synnit, on toistamiseen ilman syntiä ilmestyvä pelastukseksi niille, jotka häntä odottavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 1, 'Sillä koska laissa on vain tulevan hyvän varjo, ei itse asiain olemusta, ei se koskaan voi samoilla jokavuotisilla uhreilla, joita he alinomaa kantavat esiin, tehdä niiden tuojia täydellisiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 2, 'Sillä eikö muutoin olisi lakattu niitä uhraamasta, koska näillä, jotka jumalanpalvelustaan toimittavat, kerran puhdistettuina, ei enää olisi ollut mitään tuntoa synneistä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 3, 'Mutta niissä on jokavuotinen muistutus synneistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 4, 'Sillä mahdotonta on, että härkäin ja kauristen veri voi ottaa pois syntejä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 5, 'Sentähden hän maailmaan tullessaan sanoo: \"Uhria ja antia sinä et tahtonut, mutta ruumiin sinä minulle valmistit;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 6, 'polttouhreihin ja syntiuhreihin sinä et mielistynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 7, 'Silloin minä sanoin: \'Katso, minä tulen-kirjakääröön on minusta kirjoitettu-tekemään sinun tahtosi, Jumala\'.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 8, 'Kun hän ensin sanoo: \"Uhreja ja anteja ja polttouhreja ja syntiuhreja sinä et tahtonut etkä niihin mielistynyt\", vaikka niitä lain mukaan uhrataankin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 9, 'sanoo hän sitten: \"Katso, minä tulen tekemään sinun tahtosi\". Hän poistaa ensimmäisen, pystyttääkseen toisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 10, 'Ja tämän tahdon perusteella me olemme pyhitetyt Jeesuksen Kristuksen ruumiin uhrilla kerta kaikkiaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 11, 'Ja kaikki papit seisovat päivä päivältä palvelustaan toimittamassa ja usein uhraamassa, aina samoja uhreja, jotka eivät ikinä voi syntejä poistaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 12, 'mutta tämä on, uhrattuaan yhden ainoan uhrin syntien edestä, ainiaaksi istuutunut Jumalan oikealle puolelle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 13, 'ja odottaa nyt vain, kunnes hänen vihollisensa pannaan hänen jalkojensa astinlaudaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 14, 'Sillä hän on yhdellä ainoalla uhrilla ainiaaksi tehnyt täydellisiksi ne, jotka pyhitetään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 15, 'Todistaahan sen meille myös Pyhä Henki; sillä sanottuaan:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 16, '\"Tämä on se liitto, jonka minä näiden päivien jälkeen teen heidän kanssaan\", sanoo Herra: \"Minä panen lakini heidän sydämiinsä ja kirjoitan ne heidän mieleensä\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 17, 'ja: \"heidän syntejänsä ja laittomuuksiansa en minä enää muista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 18, 'Mutta missä nämä ovat anteeksi annetut, siinä ei uhria synnin edestä enää tarvita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 19, 'Koska meillä siis, veljet, on luja luottamus siihen, että meillä Jeesuksen veren kautta on pääsy kaikkeinpyhimpään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 20, 'jonka pääsyn hän on vihkinyt meille uudeksi ja eläväksi tieksi, joka käy esiripun, se on hänen lihansa, kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 21, 'ja koska meillä on \"suuri pappi, Jumalan huoneen haltija\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 22, 'niin käykäämme esiin totisella sydämellä, täydessä uskon varmuudessa, sydän vihmottuna puhtaaksi pahasta omastatunnosta ja ruumis puhtaalla vedellä pestynä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 23, 'pysykäämme järkähtämättä toivon tunnustuksessa, sillä hän, joka antoi lupauksen, on uskollinen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 24, 'ja valvokaamme toinen toistamme rohkaisuksi toisillemme rakkauteen ja hyviin tekoihin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 25, 'Älkäämme jättäkö omaa seurakunnankokoustamme, niinkuin muutamien on tapana, vaan kehoittakaamme toisiamme, sitä enemmän, kuta enemmän näette tuon päivän lähestyvän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 26, 'Sillä jos me tahallamme teemme syntiä, päästyämme totuuden tuntoon, niin ei ole enää uhria meidän syntiemme edestä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 27, 'vaan hirmuinen tuomion odotus ja tulen kiivaus, joka on kuluttava vastustajat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 28, 'Joka hylkää Mooseksen lain, sen pitää armotta kahden tai kolmen todistajan todistuksen nojalla kuoleman:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 29, 'kuinka paljoa ankaramman rangaistuksen luulettekaan sen ansaitsevan, joka tallaa jalkoihinsa Jumalan Pojan ja pitää epäpyhänä liiton veren, jossa hänet on pyhitetty, ja pilkkaa armon Henkeä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 30, 'Sillä me tunnemme hänet, joka on sanonut: \"Minun on kosto, minä olen maksava\"; ja vielä: \"Herra on tuomitseva kansansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 31, 'Hirmuista on langeta elävän Jumalan käsiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 32, 'Mutta muistakaa entisiä päiviä, jolloin te, valistetuiksi tultuanne, kestitte monet kärsimysten kilvoitukset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 33, 'kun te toisaalta olitte häväistysten ja ahdistusten alaisina, kaikkien katseltavina, toisaalta taas tulitte niiden osaveljiksi, joiden kävi samalla tavalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 34, 'Sillä vankien kanssa te olette kärsineet ja ilolla pitäneet hyvänänne omaisuutenne ryöstön, tietäen, että teillä on parempi tavara, joka pysyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 35, 'Älkää siis heittäkö pois uskallustanne, jonka palkka on suuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 36, 'Sillä te tarvitsette kestäväisyyttä, tehdäksenne Jumalan tahdon ja saadaksenne sen, mikä luvattu on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 37, 'Sillä \"vähän, aivan vähän aikaa vielä, niin tulee hän, joka tuleva on, eikä viivyttele;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 38, 'mutta minun vanhurskaani on elävä uskosta, ja jos hän vetäytyy pois, ei minun sieluni mielisty häneen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 10, 39, 'Mutta me emme ole niitä, jotka vetäytyvät pois omaksi kadotuksekseen, vaan niitä, jotka uskovat sielunsa pelastukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 1, 'Mutta usko on luja luottamus siihen, mitä toivotaan, ojentautuminen sen mukaan, mikä ei näy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 2, 'Sillä sen kautta saivat vanhat todistuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 3, 'Uskon kautta me ymmärrämme, että maailma on rakennettu Jumalan sanalla, niin että se, mikä nähdään, ei ole syntynyt näkyväisestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 4, 'Uskon kautta uhrasi Aabel Jumalalle paremman uhrin kuin Kain, ja uskon kautta hän sai todistuksen, että hän oli vanhurskas, kun Jumala antoi todistuksen hänen uhrilahjoistaan; ja uskonsa kautta hän vielä kuoltuaankin puhuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 5, 'Uskon kautta otettiin Eenok pois, näkemättä kuolemaa, \"eikä häntä enää ollut, koska Jumala oli ottanut hänet pois\". Sillä ennen poisottamistaan hän oli saanut todistuksen, että hän oli otollinen Jumalalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 6, 'Mutta ilman uskoa on mahdoton olla otollinen; sillä sen, joka Jumalan tykö tulee, täytyy uskoa, että Jumala on ja että hän palkitsee ne, jotka häntä etsivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 7, 'Uskon kautta rakensi Nooa, saatuaan ilmoituksen siitä, mikä ei vielä näkynyt, pyhässä pelossa arkin perhekuntansa pelastukseksi; ja uskonsa kautta hän tuomitsi maailman, ja hänestä tuli sen vanhurskauden perillinen, joka uskosta tulee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 8, 'Uskon kautta oli Aabraham kuuliainen, kun hänet kutsuttiin lähtemään siihen maahan, jonka hän oli saava perinnöksi, ja hän lähti tietämättä, minne oli saapuva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 9, 'Uskon kautta hän eli muukalaisena lupauksen maassa niinkuin vieraassa maassa, asuen teltoissa Iisakin ja Jaakobin kanssa, jotka olivat saman lupauksen perillisiä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 10, 'sillä hän odotti sitä kaupunkia, jolla on perustukset ja jonka rakentaja ja luoja on Jumala.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 11, 'Uskon kautta sai Saarakin voimaa suvun perustamiseen, vieläpä yli-ikäisenä, koska hän piti luotettavana sen, joka oli antanut lupauksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 12, 'Sentähden syntyikin yhdestä miehestä, vieläpä kuolettuneesta, niin suuri paljous, kuin on tähtiä taivaalla ja kuin meren rannalla hiekkaa, epälukuisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 13, 'Uskossa nämä kaikki kuolivat eivätkä luvattua saavuttaneet, vaan kaukaa he olivat sen nähneet ja sitä tervehtineet ja tunnustaneet olevansa vieraita ja muukalaisia maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 14, 'Sillä jotka näin puhuvat, ilmaisevat etsivänsä isänmaata.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 15, 'Ja jos he olisivat tarkoittaneet sitä maata, josta olivat lähteneet, niin olisihan heillä ollut tilaisuus palata takaisin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 16, 'mutta nyt he pyrkivät parempaan, se on taivaalliseen. Sentähden Jumala ei heitä häpeä, vaan sallii kutsua itseään heidän Jumalaksensa; sillä hän on valmistanut heille kaupungin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 17, 'Uskon kautta uhrasi Aabraham, koetukselle pantuna, Iisakin, uhrasi ainoan poikansa, hän, joka oli lupaukset vastaanottanut');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 18, 'ja jolle oli sanottu: \"Iisakista sinä saat nimellesi jälkeläisen\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 19, 'sillä hän päätti, että Jumala on voimallinen kuolleistakin herättämään; ja sen vertauskuvana hän saikin hänet takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 20, 'Uskon kautta antoi Iisak Jaakobille ja Eesaulle siunauksen, joka koski tulevaisiakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 21, 'Uskon kautta siunasi Jaakob kuollessaan kumpaisenkin Joosefin pojista ja rukoili sauvansa päähän nojaten.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 22, 'Uskon kautta muistutti Joosef loppunsa lähetessä Israelin lasten lähdöstä ja antoi määräyksen luistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 23, 'Uskon kautta pitivät Mooseksen vanhemmat häntä heti hänen syntymänsä jälkeen kätkössä kolme kuukautta, sillä he näkivät, että lapsi oli ihana; eivätkä he peljänneet kuninkaan käskyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 24, 'Uskon kautta kieltäytyi Mooses suureksi tultuaan kantamasta faraon tyttären pojan nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 25, 'Hän otti mieluummin kärsiäkseen vaivaa yhdessä Jumalan kansan kanssa kuin saadakseen synnistä lyhytaikaista nautintoa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 26, 'katsoen \"Kristuksen pilkan\" suuremmaksi rikkaudeksi kuin Egyptin aarteet; sillä hän käänsi katseensa palkintoa kohti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 27, 'Uskon kautta hän jätti Egyptin pelkäämättä kuninkaan vihaa; sillä koska hän ikäänkuin näki sen, joka on näkymätön, niin hän kesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 28, 'Uskon kautta hän pani toimeen pääsiäisenvieton ja verensivelyn, ettei esikoisten surmaaja koskisi heihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 29, 'Uskon kautta he kulkivat poikki Punaisen meren ikäänkuin kuivalla maalla; jota yrittäessään egyptiläiset hukkuivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 30, 'Uskon kautta kaatuivat Jerikon muurit, sittenkuin niiden ympäri oli kuljettu seitsemän päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 31, 'Uskon kautta pelastui portto Raahab joutumasta perikatoon yhdessä uppiniskaisten kanssa, kun oli, rauha mielessään, ottanut vakoojat luoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 32, 'Ja mitä minä vielä sanoisin? Sillä minulta loppuisi aika, jos kertoisin Gideonista, Baarakista, Simsonista, Jeftasta, Daavidista ja Samuelista ja profeetoista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 33, 'jotka uskon kautta kukistivat valtakuntia, pitivät vanhurskautta voimassa, saivat kokea lupauksien toteutumista, tukkivat jalopeurain kidat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 34, 'sammuttivat tulen voiman, pääsivät miekanteriä pakoon, voimistuivat heikkoudesta, tulivat väkeviksi sodassa, ajoivat pakoon muukalaisten sotajoukot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 35, 'On ollut vaimoja, jotka ylösnousemuksen kautta ovat saaneet kuolleensa takaisin. Toiset ovat antaneet kiduttaa itseään eivätkä ole ottaneet vastaan vapautusta, että saisivat paremman ylösnousemuksen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 36, 'toiset taas ovat saaneet kokea pilkkaa ja ruoskimista, vieläpä kahleita ja vankeutta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 37, 'heitä on kivitetty, kiusattu, rikki sahattu, miekalla surmattu; he ovat kierrelleet ympäri lampaannahoissa ja vuohennahoissa, puutteenalaisina, ahdistettuina, pahoinpideltyinä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 38, 'he, jotka olivat liian hyviä tälle maailmalle-;he ovat harhailleet erämaissa ja vuorilla ja luolissa ja maakuopissa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 39, 'Ja vaikka nämä kaikki uskon kautta olivat todistuksen saaneet, eivät he kuitenkaan saavuttaneet sitä, mikä oli luvattu;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 11, 40, 'sillä Jumala oli varannut meitä varten jotakin parempaa, etteivät he ilman meitä pääsisi täydellisyyteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 1, 'Sentähden, kun meillä on näin suuri pilvi todistajia ympärillämme, pankaamme mekin pois kaikki, mikä meitä painaa, ja synti, joka niin helposti meidät kietoo, ja juoskaamme kestävinä edessämme olevassa kilvoituksessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 2, 'silmät luotuina uskon alkajaan ja täyttäjään, Jeesukseen, joka hänelle tarjona olevan ilon sijasta kärsi ristin, häpeästä välittämättä, ja istui Jumalan valtaistuimen oikealle puolelle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 3, 'Ajatelkaa häntä, joka syntisiltä on saanut kärsiä sellaista vastustusta itseänsä kohtaan, ettette väsyisi ja menettäisi toivoanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 4, 'Ette vielä ole verille asti tehneet vastarintaa, taistellessanne syntiä vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 5, 'ja te olette unhottaneet kehoituksen, joka puhuu teille niinkuin lapsille: \"Poikani, älä pidä halpana Herran kuritusta, äläkä menetä toivoasi, kun hän sinua nuhtelee;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 6, 'sillä jota Herra rakastaa, sitä hän kurittaa; ja hän ruoskii jokaista lasta, jonka hän ottaa huomaansa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 7, 'Kuritukseksenne te kärsitte; Jumala kohtelee teitä niinkuin lapsia. Sillä mikä on se lapsi, jota isä ei kurita?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 8, 'Mutta jos te olette ilman kuritusta, josta kaikki ovat osallisiksi tulleet, silloinhan te olette äpäriä ettekä lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 9, 'Ja vielä: meillä oli ruumiilliset isämme kurittajina, ja heitä me kavahdimme; emmekö paljoa ennemmin olisi alamaiset henkien Isälle, että eläisimme?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 10, 'Sillä nuo kurittivat meitä vain muutamia päiviä varten, oman ymmärryksensä mukaan, mutta tämä kurittaa meitä tosi parhaaksemme, että me pääsisimme osallisiksi hänen pyhyydestään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 11, 'Mikään kuritus ei tosin sillä kertaa näytä olevan iloksi, vaan murheeksi, mutta jälkeenpäin se antaa vanhurskauden rauhanhedelmän niille, jotka sen kautta ovat harjoitetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 12, 'Sentähden: \"Ojentakaa hervonneet kätenne ja rauenneet polvenne\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 13, 'ja: \"tehkää polut suoriksi jaloillenne\", ettei ontuvan jalka nyrjähtäisi, vaan ennemmin parantuisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 14, 'Pyrkikää rauhaan kaikkien kanssa ja pyhitykseen, sillä ilman sitä ei kukaan ole näkevä Herraa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 15, 'ja pitäkää huoli siitä, ettei kukaan jää osattomaksi Jumalan armosta, \"ettei mikään katkeruuden juuri pääse kasvamaan ja tekemään häiriötä\", ja monet sen kautta tule saastutetuiksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 16, 'ja ettei kukaan olisi haureellinen tahi epäpyhä niinkuin Eesau, joka yhdestä ateriasta myi esikoisuutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 17, 'Sillä te tiedätte, että hänet sittemminkin, kun hän tahtoi päästä siunausta perimään, hyljättiin; sillä hän ei löytänyt tilaa peruutukselle, vaikka hän kyynelin sitä pyysi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 18, 'Sillä te ette ole käyneet sen vuoren tykö, jota voidaan käsin koskea ja joka tulessa palaa, ettekä synkeyden, ette pimeyden, ette myrskyn,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 19, 'ette pasunan kaiun ettekä äänen tykö, joka puhui niin, että ne, jotka sen kuulivat, pyysivät, ettei heille enää puhuttaisi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 20, 'sillä he eivät voineet kestää tätä käskyä: \"Koskettakoon vuorta vaikka eläinkin, se kivitettäköön\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 21, 'ja niin hirmuinen oli se näky, että Mooses sanoi: \"Minä olen peljästynyt ja vapisen\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 22, 'vaan te olette käyneet Siionin vuoren tykö ja elävän Jumalan kaupungin, taivaallisen Jerusalemin tykö, ja kymmenien tuhansien enkelien tykö,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 23, 'taivaissa kirjoitettujen esikoisten juhlajoukon ja seurakunnan tykö, ja tuomarin tykö, joka on kaikkien Jumala, ja täydellisiksi tulleitten vanhurskasten henkien tykö,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 24, 'ja uuden liiton välimiehen, Jeesuksen, tykö, ja vihmontaveren tykö, joka puhuu parempaa kuin Aabelin veri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 25, 'Katsokaa, ettette torju luotanne häntä, joka puhuu; sillä jos nuo, jotka torjuivat luotaan hänet, joka ilmoitti Jumalan tahdon maan päällä, eivät voineet päästä pakoon, niin paljoa vähemmän me, jos käännymme pois hänestä, joka ilmoittaa sen taivaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 26, 'Silloin hänen äänensä järkytti maata, mutta nyt hän on luvannut sanoen: \"Vielä kerran minä liikutan maan, jopa taivaankin\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 27, 'Mutta tuo \"vielä kerran\" osoittaa, että ne, mitkä järkkyvät, koska ovat luotuja, tulevat muuttumaan, että ne, jotka eivät järky, pysyisivät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 28, 'Sentähden, koska me saamme valtakunnan, joka ei järky, olkaamme kiitolliset ja siten palvelkaamme Jumalaa, hänelle mielihyväksi, pyhällä arkuudella ja pelolla;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 12, 29, 'sillä meidän Jumalamme on kuluttavainen tuli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 1, 'Pysyköön veljellinen rakkaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 2, 'Älkää unhottako vieraanvaraisuutta; sillä sitä osoittamalla muutamat ovat tietämättään saaneet pitää enkeleitä vierainaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 3, 'Muistakaa vankeja, niinkuin olisitte itsekin heidän kanssaan vangittuina; muistakaa pahoinpideltyjä, sillä onhan teillä itsellännekin ruumis.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 4, 'Avioliitto pidettäköön kunniassa kaikkien kesken, ja aviovuode saastuttamatonna; sillä haureelliset ja avionrikkojat Jumala tuomitsee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 5, 'Älkää olko vaelluksessanne ahneita; tyytykää siihen, mitä teillä on; sillä hän itse on sanonut: \"En minä sinua hylkää enkä sinua jätä\";');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 6, 'niin että me turvallisin mielin sanomme: \"Herra on minun auttajani, en minä pelkää; mitä voi ihminen minulle tehdä?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 7, 'Muistakaa johtajianne, jotka ovat puhuneet teille Jumalan sanaa; katsokaa, kuinka heidän vaelluksensa on päättynyt, ja seuratkaa heidän uskoansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 8, 'Jeesus Kristus on sama eilen ja tänään ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 9, 'Älkää antako monenlaisten ja vieraiden oppien itseänne vietellä; sillä on hyvä, että sydän saa vahvistusta armosta eikä ruuista, joista ne, jotka niitä menoja ovat noudattaneet, eivät ole mitään hyötyneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 10, 'Meillä on uhrialttari, josta majassa palvelevilla ei ole valta syödä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 11, 'Sillä niiden eläinten ruumiit, joiden veren ylimmäinen pappi syntien sovitukseksi kantaa kaikkeinpyhimpään, poltetaan ulkopuolella leirin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 12, 'Sentähden myös Jeesus, pyhittääkseen omalla verellänsä kansan, kärsi portin ulkopuolella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 13, 'Niin menkäämme siis hänen tykönsä \"ulkopuolelle leirin\", hänen pilkkaansa kantaen;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 14, 'sillä ei meillä ole täällä pysyväistä kaupunkia, vaan tulevaista me etsimme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 15, 'Uhratkaamme siis hänen kauttansa Jumalalle joka aika kiitosuhria, se on: niiden huulten hedelmää, jotka hänen nimeänsä ylistävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 16, 'Mutta älkää unhottako tehdä hyvää ja jakaa omastanne, sillä senkaltaisiin uhreihin Jumala mielistyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 17, 'Olkaa kuuliaiset johtajillenne ja tottelevaiset, sillä he valvovat teidän sielujanne niinkuin ne, joiden on tehtävä tili, että he voisivat tehdä sitä ilolla eikä huokaillen; sillä se ei ole teille hyödyllistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 18, 'Rukoilkaa meidän edestämme; sillä me tiedämme, että meillä on hyvä omatunto, koska tahdomme kaikessa hyvin vaeltaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 19, 'Vielä hartaammin kehoitan teitä näin tekemään, että minut sitä pikemmin annettaisiin teille takaisin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 20, 'Mutta rauhan Jumala, joka on kuolleista nostanut hänet, joka iankaikkisen liiton veren kautta on se suuri lammasten paimen, meidän Herramme Jeesuksen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 21, 'hän tehköön teidät kykeneviksi kaikkeen hyvään, voidaksenne toteuttaa hänen tahtonsa, ja vaikuttakoon teissä sen, mikä on hänelle otollista, Jeesuksen Kristuksen kautta; hänelle kunnia aina ja iankaikkisesti! Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 22, 'Minä pyydän teitä, veljet: kestäkää tämä kehoituksen sana; sillä lyhykäisesti minä olen teille kirjoittanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 23, 'Tietäkää, että veljemme Timoteus on päästetty vapaaksi; ja jos hän pian tulee, saan minä hänen kanssaan nähdä teidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 24, 'Sanokaa tervehdys kaikille johtajillenne ja kaikille pyhille. Tervehdyksen lähettävät teille ne, jotka ovat Italiasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (75, 13, 25, 'Armo olkoon kaikkien teidän kanssanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 1, 'Jaakob, Jumalan ja Herran Jeesuksen Kristuksen palvelija, lähettää tervehdyksen kahdelletoista hajalla asuvalle sukukunnalle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 2, 'Veljeni, pitäkää pelkkänä ilona, kun joudutte moninaisiin kiusauksiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 3, 'tietäen, että teidän uskonne kestäväisyys koetuksissa saa aikaan kärsivällisyyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 4, 'Ja kärsivällisyys tuottakoon täydellisen teon, että te olisitte täydelliset ja eheät ettekä missään puuttuvaiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 5, 'Mutta jos joltakin teistä puuttuu viisautta, anokoon sitä Jumalalta, joka antaa kaikille alttiisti ja soimaamatta, niin se hänelle annetaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 6, 'Mutta anokoon uskossa, ollenkaan epäilemättä; sillä joka epäilee, on meren aallon kaltainen, jota tuuli ajaa ja heittelee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 7, 'Älköön sellainen ihminen luulko Herralta mitään saavansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 8, 'kaksimielinen mies, epävakainen kaikilla teillään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 9, 'Alhainen veli kerskatkoon ylhäisyydestään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 10, 'mutta rikas alhaisuudestaan, sillä hän on katoava niinkuin ruohon kukka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 11, 'Aurinko nousee helteineen ja kuivaa ruohon, ja sen kukka varisee, ja sen muodon sulous häviää; niin on rikaskin lakastuva retkillänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 12, 'Autuas se mies, joka kiusauksen kestää, sillä kun hänet on koeteltu, on hän saava elämän kruunun, jonka Herra on luvannut niille, jotka häntä rakastavat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 13, 'Älköön kukaan, kiusauksessa ollessaan, sanoko: \"Jumala minua kiusaa\"; sillä Jumala ei ole pahan kiusattavissa, eikä hän ketään kiusaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 14, 'Vaan jokaista kiusaa hänen oma himonsa, joka häntä vetää ja houkuttelee;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 15, 'kun sitten himo on tullut raskaaksi, synnyttää se synnin, mutta kun synti on täytetty, synnyttää se kuoleman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 16, 'Älkää eksykö, rakkaat veljeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 17, 'Jokainen hyvä anti ja jokainen täydellinen lahja tulee ylhäältä, valkeuksien Isältä, jonka tykönä ei ole muutosta, ei vaihteen varjoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 18, 'Tahtonsa mukaan hän synnytti meidät totuuden sanalla, ollaksemme hänen luotujensa esikoiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 19, 'Te tiedätte sen, rakkaat veljeni. Mutta olkoon jokainen ihminen nopea kuulemaan, hidas puhumaan, hidas vihaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 20, 'sillä miehen viha ei tee sitä, mikä on oikein Jumalan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 21, 'Sentähden pankaa pois kaikki saastaisuus ja kaikkinainen pahuus ja ottakaa hiljaisuudella vastaan sana, joka on teihin istutettu ja joka voi teidän sielunne pelastaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 22, 'Mutta olkaa sanan tekijöitä, eikä vain sen kuulijoita, pettäen itsenne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 23, 'Sillä jos joku on sanan kuulija eikä sen tekijä, niin hän on miehen kaltainen, joka katselee kuvastimessa luonnollisia kasvojaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 24, 'hän katselee itseään, lähtee pois ja unhottaa heti, millainen hän oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 25, 'Mutta joka katsoo täydelliseen lakiin, vapauden lakiin, ja pysyy siinä, eikä ole muistamaton kuulija, vaan todellinen tekijä, hän on oleva autuas tekemisessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 26, 'Jos joku luulee olevansa jumalanpalvelija, mutta ei hillitse kieltään, vaan pettää sydämensä, niin hänen jumalanpalveluksensa on turha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 1, 27, 'Puhdas ja tahraton jumalanpalvelus Jumalan ja Isän silmissä on käydä katsomassa orpoja ja leskiä heidän ahdistuksessaan ja varjella itsensä niin, ettei maailma saastuta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 1, 'Veljeni, älköön teidän uskonne meidän kirkastettuun Herraamme, Jeesukseen Kristukseen, olko sellainen, joka katsoo henkilöön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 2, 'Sillä jos kokoukseenne tulee mies, kultasormus sormessa ja loistavassa puvussa, ja tulee myös köyhä ryysyissä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 3, 'ja te katsotte loistavapukuisen puoleen ja sanotte: \"Istu sinä tähän mukavasti\", ja köyhälle sanotte: \"Seiso sinä tuossa\", tahi: \"Istu tähän jalkajakkarani viereen\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 4, 'niin ettekö ole joutuneet ristiriitaan itsenne kanssa, ja eikö teistä ole tullut väärämielisiä tuomareita?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 5, 'Kuulkaa, rakkaat veljeni. Eikö Jumala ole valinnut niitä, jotka maailman silmissä ovat köyhiä, olemaan rikkaita uskossa ja sen valtakunnan perillisiä, jonka hän on luvannut niille, jotka häntä rakastavat?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 6, 'Mutta te olette häväisseet köyhän. Eivätkö juuri rikkaat teitä sorra, ja eivätkö juuri he vedä teitä tuomioistuimien eteen?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 7, 'Eivätkö juuri he pilkkaa sitä jaloa nimeä, joka on lausuttu teidän ylitsenne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 8, 'Vaan jos täytätte kuninkaallisen lain Raamatun mukaan: \"Rakasta lähimmäistäsi niinkuin itseäsi\", niin te hyvin teette;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 9, 'mutta jos te henkilöön katsotte, niin teette syntiä, ja laki näyttää teille, että olette lainrikkojia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 10, 'Sillä joka pitää koko lain, mutta rikkoo yhtä kohtaa vastaan, se on syypää kaikissa kohdin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 11, 'Sillä hän, joka on sanonut: \"Älä tee huorin\", on myös sanonut: \"Älä tapa\"; jos et teekään huorin, mutta tapat, olet lainrikkoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 12, 'Puhukaa niin ja tehkää niin kuin ne, jotka vapauden laki on tuomitseva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 13, 'Sillä tuomio on laupeudeton sille, joka ei ole laupeutta tehnyt; laupeudelle tuomio koituu kerskaukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 14, 'Mitä hyötyä, veljeni, siitä on, jos joku sanoo itsellään olevan uskon, mutta hänellä ei ole tekoja? Ei kaiketi usko voi häntä pelastaa?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 15, 'Jos veli tai sisar on alaston ja jokapäiväistä ravintoa vailla');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 16, 'ja joku teistä sanoo heille: \"Menkää rauhassa, lämmitelkää ja ravitkaa itsenne\", mutta ette anna heille ruumiin tarpeita, niin mitä hyötyä siitä on?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 17, 'Samoin uskokin, jos sillä ei ole tekoja, on itsessään kuollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 18, 'Joku ehkä sanoo: \"Sinulla on usko, ja minulla on teot\"; näytä sinä minulle uskosi ilman tekoja, niin minä teoistani näytän sinulle uskon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 19, 'Sinä uskot, että Jumala on yksi. Siinä teet oikein; riivaajatkin sen uskovat ja vapisevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 20, 'Mutta tahdotko tietää, sinä turha ihminen, että usko ilman tekoja on voimaton?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 21, 'Eikö Aabraham, meidän isämme, tullut vanhurskaaksi teoista, kun vei poikansa Iisakin uhrialttarille?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 22, 'Sinä näet, että usko vaikutti hänen tekojensa mukana, ja teoista usko tuli täydelliseksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 23, 'ja niin toteutui Raamatun sana: \"Aabraham uskoi Jumalaa, ja se luettiin hänelle vanhurskaudeksi\", ja häntä sanottiin Jumalan ystäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 24, 'Te näette, että ihminen tulee vanhurskaaksi teoista eikä ainoastaan uskosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 25, 'Eikö samoin myös portto Raahab tullut vanhurskaaksi teoista, kun hän otti lähettiläät luokseen ja päästi heidät toista tietä pois?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 2, 26, 'Sillä niinkuin ruumis ilman henkeä on kuollut, niin myös usko ilman tekoja on kuollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 1, 'Veljeni, älkööt aivan monet teistä pyrkikö opettajiksi, sillä te tiedätte, että me saamme sitä kovemman tuomion.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 2, 'Sillä monessa kohden me kaikki hairahdumme. Jos joku ei hairahdu puheessa, niin hän on täydellinen mies ja kykenee hillitsemään myös koko ruumiinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 3, 'Kun panemme suitset hevosten suuhun, että ne meitä tottelisivat, niin voimme ohjata niiden koko ruumiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 4, 'Katso, laivatkin, vaikka ovat niin suuria ja tuimain tuulten kuljetettavia, ohjataan varsin pienellä peräsimellä, minne perämiehen mieli tekee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 5, 'Samoin myös kieli on pieni jäsen ja voi kuitenkin kerskata suurista asioista. Katso, kuinka pieni tuli, ja kuinka suuren metsän se sytyttää!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 6, 'Myös kieli on tuli, on vääryyden maailma; kieli on se meidän jäsenistämme, joka tahraa koko ruumiin, sytyttää tuleen elämän pyörän, itse syttyen helvetistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 7, 'Sillä kaiken luonnon, sekä petojen että lintujen, sekä matelijain että merieläinten luonnon, voi ihmisluonto kesyttää ja onkin kesyttänyt;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 8, 'mutta kieltä ei kukaan ihminen voi kesyttää; se on levoton ja paha, täynnä kuolettavaa myrkkyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 9, 'Kielellä me kiitämme Herraa ja Isää, ja sillä me kiroamme ihmisiä, Jumalan kaltaisiksi luotuja;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 10, 'samasta suusta lähtee kiitos ja kirous. Näin ei saa olla, veljeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 11, 'Uhkuuko lähde samasta silmästä makeaa ja karvasta vettä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 12, 'Eihän, veljeni, viikunapuu voi tuottaa öljymarjoja eikä viinipuu viikunoita? Eikä myöskään suolainen lähde voi antaa makeata vettä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 13, 'Kuka on viisas ja ymmärtäväinen teidän joukossanne? Tuokoon hän näkyviin tekonsa hyvällä vaelluksellaan viisauden sävyisyydessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 14, 'Mutta jos teillä on katkera kiivaus ja riitaisuus sydämessänne, niin älkää kerskatko älkääkä valhetelko totuutta vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 15, 'Tämä ei ole se viisaus, joka ylhäältä tulee, vaan se on maallista, sielullista, riivaajien viisautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 16, 'Sillä missä kiivaus ja riitaisuus on, siellä on epäjärjestys ja kaikkinainen paha meno.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 17, 'Mutta ylhäältä tuleva viisaus on ensiksikin puhdas, sitten rauhaisa, lempeä, taipuisa, täynnä laupeutta ja hyviä hedelmiä, se ei epäile, ei teeskentele.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 3, 18, 'Vanhurskauden hedelmä kylvetään rauhassa rauhan tekijöille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 1, 'Mistä tulevat taistelut ja mistä riidat teidän keskuudessanne? Eikö teidän himoistanne, jotka sotivat jäsenissänne?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 2, 'Te himoitsette, eikä teillä kuitenkaan ole; te tapatte ja kiivailette, ettekä voi saavuttaa; te riitelette ja taistelette. Teillä ei ole, sentähden ettette ano.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 3, 'Te anotte, ettekä saa, sentähden että anotte kelvottomasti, kuluttaaksenne sen himoissanne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 4, 'Te avionrikkojat, ettekö tiedä, että maailman ystävyys on vihollisuutta Jumalaa vastaan? Joka siis tahtoo olla maailman ystävä, siitä tulee Jumalan vihollinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 5, 'Vai luuletteko, että Raamattu turhaan sanoo: \"Kateuteen asti hän halajaa henkeä, jonka hän on pannut meihin asumaan\"?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 6, 'Mutta hän antaa sitä suuremman armon. Sentähden sanotaan: \"Jumala on ylpeitä vastaan, mutta nöyrille hän antaa armon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 7, 'Olkaa siis Jumalalle alamaiset; mutta vastustakaa perkelettä, niin se teistä pakenee.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 8, 'Lähestykää Jumalaa, niin hän lähestyy teitä. Puhdistakaa kätenne, te syntiset, ja tehkää sydämenne puhtaiksi, te kaksimieliset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 9, 'Tuntekaa kurjuutenne ja murehtikaa ja itkekää; naurunne muuttukoon murheeksi ja ilonne suruksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 10, 'Nöyrtykää Herran edessä, niin hän teidät korottaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 11, 'Älkää panetelko toisianne, veljet. Joka veljeään panettelee tai veljensä tuomitsee, se panettelee lakia ja tuomitsee lain; mutta jos sinä tuomitset lain, niin et ole lain noudattaja, vaan sen tuomari.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 12, 'Yksi on lainsäätäjä ja tuomari, hän, joka voi pelastaa ja hukuttaa; mutta kuka olet sinä, joka tuomitset lähimmäisesi?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 13, 'Kuulkaa nyt, te, jotka sanotte: \"Tänään tai huomenna lähdemme siihen ja siihen kaupunkiin ja viivymme siellä vuoden ja teemme kauppaa ja saamme voittoa\" -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 14, 'te, jotka ette tiedä, mitä huomenna tapahtuu; sillä mikä on teidän elämänne? Savu te olette, joka hetkisen näkyy ja sitten haihtuu-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 15, 'sen sijaan, että teidän tulisi sanoa: \"Jos Herra tahtoo ja me elämme, niin teemme tämän tai tuon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 16, 'Mutta nyt te kerskaatte ylvästelyssänne. Kaikki sellainen kerskaaminen on paha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 4, 17, 'Joka siis ymmärtää tehdä sitä, mikä hyvää on, eikä tee, hänelle se on synniksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 1, 'Kuulkaa nyt, te rikkaat: itkekää ja vaikeroikaa sitä kurjuutta, joka on teille tulossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 2, 'Teidän rikkautenne on mädännyt, ja teidän vaatteenne ovat koin syömät;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 3, 'teidän kultanne ja hopeanne on ruostunut, ja niiden ruoste on oleva todistuksena teitä vastaan ja syövä teidän lihanne niinkuin tuli. Te olette koonneet aarteita viimeisinä päivinä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 4, 'Katso, työmiesten palkka, jonka te vainioittenne niittäjiltä olette pidättäneet, huutaa, ja leikkuumiesten valitukset ovat tulleet Herran Sebaotin korviin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 5, 'Te olette herkutelleet maan päällä ja hekumoineet, te olette sydäntänne syötelleet teurastuspäivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 6, 'Vanhurskaan te olette tuominneet ja tappaneet; hän ei vastusta teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 7, 'Niin olkaa kärsivällisiä, veljet, Herran tulemukseen asti. Katso, peltomies odottaa maan kallista hedelmää, kärsivällisesti sitä vartoen, kunnes saa syksyisen sateen ja keväisen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 8, 'Olkaa tekin kärsivällisiä, vahvistakaa sydämenne, sillä Herran tulemus on lähellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 9, 'Älkää huokailko, veljet, toisianne vastaan, ettei teitä tuomittaisi; katso, tuomari seisoo ovella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 10, 'Ottakaa, veljet, vaivankestämisen ja kärsivällisyyden esikuvaksi profeetat, jotka ovat puhuneet Herran nimessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 11, 'Katso, me ylistämme autuaiksi niitä, jotka ovat kestäneet; Jobin kärsivällisyyden te olette kuulleet, ja lopun, jonka Herra antaa, te olette nähneet. Sillä Herra on laupias ja armahtavainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 12, 'Mutta ennen kaikkea, veljeni, älkää vannoko, älkää taivaan kautta älkääkä maan, älkää mitään muutakaan valaa; vaan \"on\" olkoon teillä \"on\", ja \"ei\" olkoon teillä \"ei\", ettette joutuisi tuomion alle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 13, 'Jos joku teistä kärsii vaivaa, niin rukoilkoon; jos joku on hyvillä mielin, veisatkoon kiitosta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 14, 'Jos joku teistä sairastaa, kutsukoon tykönsä seurakunnan vanhimmat, ja he rukoilkoot hänen edestään, voidellen häntä öljyllä Herran nimessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 15, 'Ja uskon rukous pelastaa sairaan, ja Herra antaa hänen nousta jälleen; ja jos hän on syntejä tehnyt, niin ne annetaan hänelle anteeksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 16, 'Tunnustakaa siis toisillenne syntinne ja rukoilkaa toistenne puolesta, että te parantuisitte; vanhurskaan rukous voi paljon, kun se on harras.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 17, 'Elias oli ihminen, yhtä vajavainen kuin mekin, ja hän rukoili rukoilemalla, ettei sataisi; eikä satanut maan päällä kolmeen vuoteen ja kuuteen kuukauteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 18, 'Ja hän rukoili uudestaan, ja taivas antoi sateen, ja maa kasvoi hedelmänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 19, 'Veljeni, jos joku teistä eksyy totuudesta ja hänet joku palauttaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (76, 5, 20, 'niin tietäkää, että joka palauttaa syntisen hänen eksymyksensä tieltä, se pelastaa hänen sielunsa kuolemasta ja peittää syntien paljouden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 1, 'Pietari, Jeesuksen Kristuksen apostoli, valituille muukalaisille, jotka asuvat hajallaan Pontossa, Galatiassa, Kappadokiassa, Aasiassa ja Bityniassa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 2, 'ja jotka Isän Jumalan edeltätietämisen mukaan ovat Hengen pyhittämisen kautta valitut Jeesuksen Kristuksen kuuliaisuuteen ja hänen verellänsä vihmottaviksi. Lisääntyköön teille armo ja rauha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 3, 'Ylistetty olkoon meidän Herramme Jeesuksen Kristuksen Jumala ja Isä, joka suuren laupeutensa mukaan on uudestisynnyttänyt meidät elävään toivoon Jeesuksen Kristuksen kuolleistanousemisen kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 4, 'turmeltumattomaan ja saastumattomaan ja katoamattomaan perintöön, joka taivaissa on säilytettynä teitä varten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 5, 'jotka Jumalan voimasta uskon kautta varjellutte pelastukseen, joka on valmis ilmoitettavaksi viimeisenä aikana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 6, 'Sentähden te riemuitsette, vaikka te nyt, jos se on tarpeellista, vähän aikaa kärsittekin murhetta moninaisissa kiusauksissa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 7, 'että teidän uskonne kestäväisyys koetuksissa havaittaisiin paljoa kallisarvoisemmaksi kuin katoava kulta, joka kuitenkin tulessa koetellaan, ja koituisi kiitokseksi, ylistykseksi ja kunniaksi Jeesuksen Kristuksen ilmestyessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 8, 'Häntä te rakastatte, vaikka ette ole häntä nähneet, häneen te uskotte, vaikka ette nyt häntä näe, ja riemuitsette sanomattomalla ja kirkastuneella ilolla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 9, 'sillä te saavutatte uskon päämäärän, sielujen pelastuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 10, 'Sitä pelastusta ovat etsineet ja tutkineet profeetat, jotka ovat ennustaneet teidän osaksenne tulevasta armosta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 11, 'ovat tutkineet, mihin tai millaiseen aikaan heissä oleva Kristuksen Henki viittasi, edeltäpäin todistaessaan Kristusta kohtaavista kärsimyksistä ja niiden jälkeen tulevasta kunniasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 12, 'Ja heille, koska he eivät palvelleet itseänsä, vaan teitä, ilmoitettiin se, mikä nyt on teille julistettu niiden kautta, jotka taivaasta lähetetyssä Pyhässä Hengessä ovat teille evankeliumia julistaneet; ja siihen enkelitkin halajavat katsahtaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 13, 'Vyöttäkää sentähden mielenne kupeet ja olkaa raittiit; ja pankaa täysi toivonne siihen armoon, joka teille tarjotaan Jeesuksen Kristuksen ilmestymisessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 14, 'Niinkuin kuuliaisten lasten tulee, älkää mukautuko niiden himojen mukaan, joissa te ennen, tietämättömyytenne aikana, elitte,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 15, 'vaan sen Pyhän mukaan, joka on teidät kutsunut, tulkaa tekin kaikessa vaelluksessanne pyhiksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 16, 'Sillä kirjoitettu on: \"Olkaa pyhät, sillä minä olen pyhä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 17, 'Ja jos te Isänänne huudatte avuksi häntä, joka henkilöön katsomatta tuomitsee kunkin hänen tekojensa mukaan, niin vaeltakaa pelossa tämä muukalaisuutenne aika,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 18, 'tietäen, ettette ole millään katoavaisella, ette hopealla ettekä kullalla, lunastetut turhasta, isiltä peritystä vaelluksestanne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 19, 'vaan Kristuksen kalliilla verellä, niinkuin virheettömän ja tahrattoman karitsan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 20, 'hänen, joka tosin oli edeltätiedetty jo ennen maailman perustamista, mutta vasta viimeisinä aikoina on ilmoitettu teitä varten,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 21, 'jotka hänen kauttansa uskotte Jumalaan, joka herätti hänet kuolleista ja antoi hänelle kirkkauden, niin että teidän uskonne on myös toivo Jumalaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 22, 'Puhdistakaa sielunne totuuden kuuliaisuudessa vilpittömään veljenrakkauteen ja rakastakaa toisianne hartaasti puhtaasta sydämestä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 23, 'te, jotka olette uudestisyntyneet, ette katoavasta, vaan katoamattomasta siemenestä, Jumalan elävän ja pysyvän sanan kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 24, 'Sillä: \"kaikki liha on kuin ruoho, ja kaikki sen kauneus kuin ruohon kukkanen; ruoho kuivuu, ja kukkanen varisee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 1, 25, 'mutta Herran sana pysyy iankaikkisesti\". Ja tämä on se sana, joka on teille ilosanomana julistettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 1, 'Pankaa siis pois kaikki pahuus ja kaikki vilppi ja ulkokultaisuus ja kateus ja kaikki panettelu,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 2, 'ja halatkaa niinkuin vastasyntyneet lapset sanan väärentämätöntä maitoa, että te sen kautta kasvaisitte pelastukseen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 3, 'jos \"olette maistaneet, että Herra on hyvä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 4, 'Ja tulkaa hänen tykönsä, elävän kiven tykö, jonka ihmiset tosin ovat hyljänneet, mutta joka Jumalan edessä on valittu, kallis,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 5, 'ja rakentukaa itsekin elävinä kivinä hengelliseksi huoneeksi, pyhäksi papistoksi, uhraamaan hengellisiä uhreja, jotka Jeesuksen Kristuksen kautta ovat Jumalalle mieluisia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 6, 'Sillä Raamatussa sanotaan: \"Katso, minä lasken Siioniin valitun kiven, kalliin kulmakiven; ja joka häneen uskoo, ei ole häpeään joutuva\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 7, 'Teille siis, jotka uskotte, se on kallis, mutta niille, jotka eivät usko, \"on se kivi, jonka rakentajat hylkäsivät, tullut kulmakiveksi\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 8, 'ja \"kompastuskiveksi ja loukkauskallioksi\". Koska he eivät tottele sanaa, niin he kompastuvat; ja siihen heidät on pantukin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 9, 'Mutta te olette \"valittu suku, kuninkaallinen papisto, pyhä heimo, omaisuuskansa, julistaaksenne sen jaloja tekoja\", joka on pimeydestä kutsunut teidät ihmeelliseen valkeuteensa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 10, 'te, jotka ennen \"ette olleet kansa\", mutta nyt olette \"Jumalan kansa\", jotka ennen \"ette olleet armahdetut\", mutta nyt \"olette armahdetut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 11, 'Rakkaani, niinkuin outoja ja muukalaisia minä kehoitan teitä pidättymään lihallisista himoista, jotka sotivat sielua vastaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 12, 'ja vaeltamaan nuhteettomasti pakanain keskuudessa, että he siitä, mistä he parjaavat teitä niinkuin pahantekijöitä, teidän hyvien tekojenne tähden, niitä tarkatessaan, ylistäisivät Jumalaa etsikkopäivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 13, 'Olkaa alamaiset kaikelle inhimilliselle järjestykselle Herran tähden, niin hyvin kuninkaalle, joka on ylin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 14, 'kuin käskynhaltijoille, jotka hän on lähettänyt pahaa tekeville rangaistukseksi, mutta hyvää tekeville kiitokseksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 15, 'sillä se on Jumalan tahto, että te hyvää tekemällä tukitte suun mielettömäin ihmisten ymmärtämättömyydeltä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 16, 'niinkuin vapaat, ei niinkuin ne, joilla vapaus on pahuuden verhona, vaan niinkuin Jumalan palvelijat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 17, 'Kunnioittakaa kaikkia, rakastakaa veljiä, peljätkää Jumalaa, kunnioittakaa kuningasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 18, 'Palvelijat, olkaa kaikella pelolla isännillenne alamaiset, ei ainoastaan hyville ja lempeille, vaan nurjillekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 19, 'Sillä se on armoa, että joku omantunnon tähden Jumalan edessä kestää vaivoja, syyttömästi kärsien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 20, 'Sillä mitä kiitettävää siinä on, jos te olette kärsivällisiä silloin, kun teitä syntienne tähden piestään? Mutta jos olette kärsivällisiä, kun hyvien tekojenne tähden saatte kärsiä, niin se on Jumalan armoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 21, 'Sillä siihen te olette kutsutut, koska Kristuskin kärsi teidän puolestanne, jättäen teille esikuvan, että te noudattaisitte hänen jälkiänsä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 22, 'joka \"ei syntiä tehnyt ja jonka suussa ei petosta ollut\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 23, 'joka häntä herjattaessa ei herjannut takaisin, joka kärsiessään ei uhannut, vaan jätti asiansa sen haltuun, joka oikein tuomitsee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 24, 'joka \"itse kantoi meidän syntimme\" ruumiissansa ristinpuuhun, että me, synneistä pois kuolleina, eläisimme vanhurskaudelle; ja hänen \"haavainsa kautta te olette paratut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 2, 25, 'Sillä te olitte \"eksyksissä niinkuin lampaat\", mutta nyt te olette palanneet sielujenne paimenen ja kaitsijan tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 1, 'Samoin te, vaimot, olkaa alamaiset miehillenne, että nekin, jotka ehkä eivät ole sanalle kuuliaisia, vaimojen vaelluksen kautta sanoittakin voitettaisiin,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 2, 'kun he katselevat, kuinka te vaellatte puhtaina ja pelossa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 3, 'Älköön teidän kaunistuksenne olko ulkonaista, ei hiusten palmikoimista eikä kultien ympärillenne ripustamista eikä koreihin vaatteisiin pukeutumista,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 4, 'vaan se olkoon salassa oleva sydämen ihminen, hiljaisen ja rauhaisan hengen katoamattomuudessa; tämä on Jumalan silmissä kallis.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 5, 'Sillä näin myös muinoin pyhät vaimot, jotka panivat toivonsa Jumalaan, kaunistivat itsensä ja olivat miehillensä alamaiset;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 6, 'niin oli Saara kuuliainen Aabrahamille, kutsuen häntä herraksi; ja hänen lapsikseen te olette tulleet, kun teette sitä, mikä hyvää on, ettekä anna minkään itseänne peljättää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 7, 'Samoin te, miehet, eläkää taidollisesti kukin vaimonne kanssa, niinkuin heikomman astian kanssa, ja osoittakaa heille kunnioitusta, koska he ovat elämän armon perillisiä niinkuin tekin; etteivät teidän rukouksenne estyisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 8, 'Ja lopuksi: olkaa kaikki yksimielisiä, helläsydämisiä, veljiä kohtaan rakkaita, armahtavaisia, nöyriä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 9, 'Älkää kostako pahaa pahalla, älkää herjausta herjauksella, vaan päinvastoin siunatkaa; sillä siihen te olette kutsututkin, että siunauksen perisitte.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 10, 'Sillä: \"joka tahtoo rakastaa elämää ja nähdä hyviä päiviä, varjelkoon kielensä pahasta ja huulensa vilppiä puhumasta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 11, 'kääntyköön pois pahasta ja tehköön hyvää, etsiköön rauhaa ja pyrkiköön siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 12, 'Sillä Herran silmät tarkkaavat vanhurskaita ja hänen korvansa heidän rukouksiansa, mutta Herran kasvot ovat pahantekijöitä vastaan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 13, 'Ja kuka on, joka voi teitä vahingoittaa, jos teillä on kiivaus hyvään?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 14, 'Vaan vaikka saisittekin kärsiä vanhurskauden tähden, olette kuitenkin autuaita. \"Mutta älkää antako heidän pelkonsa peljättää itseänne, älkääkä hämmästykö\",');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 15, 'vaan pyhittäkää Herra Kristus sydämissänne ja olkaa aina valmiit vastaamaan jokaiselle, joka teiltä kysyy sen toivon perustusta, joka teissä on, kuitenkin sävyisyydellä ja pelolla,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 16, 'pitäen hyvän omantunnon, että ne, jotka parjaavat teidän hyvää vaellustanne Kristuksessa, joutuisivat häpeään siinä, mistä he teitä panettelevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 17, 'Sillä parempi on hyvää tehden kärsiä, jos niin on Jumalan tahto, kuin pahaa tehden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 18, 'Sillä myös Kristus kärsi kerran kuoleman syntien tähden, vanhurskas vääräin puolesta, johdattaaksensa meidät Jumalan tykö; hän, joka tosin kuoletettiin lihassa, mutta tehtiin eläväksi hengessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 19, 'jossa hän myös meni pois ja saarnasi vankeudessa oleville hengille,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 20, 'jotka muinoin eivät olleet kuuliaiset, kun Jumalan pitkämielisyys odotti Nooan päivinä, silloin kun valmistettiin arkkia, jossa vain muutamat, se on kahdeksan sielua, pelastuivat veden kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 21, 'Tämän vertauskuvan mukaan vesi nyt teidätkin pelastaa, kasteena-joka ei ole lihan saastan poistamista, vaan hyvän omantunnon pyytämistä Jumalalta-Jeesuksen Kristuksen ylösnousemuksen kautta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 3, 22, 'hänen, joka on mennyt taivaaseen ja on Jumalan oikealla puolella; ja hänen allensa ovat enkelit ja vallat ja voimat alistetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 1, 'Koska siis Kristus on kärsinyt lihassa, niin ottakaa tekin aseeksenne sama mieli-sillä joka lihassa kärsii, se lakkaa synnistä-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 2, 'ettette enää eläisi tätä lihassa vielä elettävää aikaa ihmisten himojen mukaan, vaan Jumalan tahdon mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 3, 'Riittäähän, että menneen ajan olette täyttäneet pakanain tahtoa vaeltaessanne irstaudessa, himoissa, juoppoudessa, mässäyksissä, juomingeissa ja kauheassa epäjumalain palvelemisessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 4, 'Sentähden he oudoksuvat sitä, ettette juokse heidän mukanansa samaan riettauden lätäkköön, ja herjaavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 5, 'Mutta heidän on tehtävä tili hänelle, joka on valmis tuomitsemaan eläviä ja kuolleita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 6, 'Sillä sitä varten kuolleillekin on julistettu evankeliumi, että he tosin olisivat tuomitut lihassa niinkuin ihmiset, mutta että heillä hengessä olisi elämä, niinkuin Jumala elää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 7, 'Mutta kaiken loppu on lähellä. Sentähden olkaa maltilliset ja raittiit rukoilemaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 8, 'Ennen kaikkea olkoon teidän rakkautenne toisianne kohtaan harras, sillä \"rakkaus peittää syntien paljouden\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 9, 'Olkaa vieraanvaraisia toinen toistanne kohtaan, nurkumatta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 10, 'Palvelkaa toisianne, kukin sillä armolahjalla, minkä on saanut, Jumalan moninaisen armon hyvinä huoneenhaltijoina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 11, 'Jos joku puhuu, puhukoon niinkuin Jumalan sanoja; jos joku palvelee, palvelkoon sen voiman mukaan, minkä Jumala antaa, että Jumala tulisi kaikessa kirkastetuksi Jeesuksen Kristuksen kautta. Hänen on kunnia ja valta aina ja iankaikkisesti. Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 12, 'Rakkaani, älkää oudoksuko sitä hellettä, jossa olette ja joka on teille koetukseksi, ikäänkuin teille tapahtuisi jotakin outoa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 13, 'vaan iloitkaa, sitä myöten kuin olette osallisia Kristuksen kärsimyksistä, että te myös hänen kirkkautensa ilmestymisessä saisitte iloita ja riemuita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 14, 'Jos teitä solvataan Kristuksen nimen tähden, niin te olette autuaat, sillä kirkkauden ja Jumalan Henki lepää teidän päällänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 15, 'Älköön näet kukaan teistä kärsikö murhaajana tai varkaana tai pahantekijänä tahi sentähden, että sekaantuu hänelle kuulumattomiin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 16, 'mutta jos hän kärsii kristittynä, älköön hävetkö, vaan ylistäköön sen nimensä tähden Jumalaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 17, 'Sillä aika on tuomion alkaa Jumalan huoneesta; mutta jos se alkaa ensiksi meistä, niin mikä on niiden loppu, jotka eivät ole Jumalan evankeliumille kuuliaiset?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 18, 'Ja \"jos vanhurskas vaivoin pelastuu, niin mihinkä joutuukaan jumalaton ja syntinen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 4, 19, 'Sentähden, uskokoot myös ne, jotka Jumalan tahdon mukaan kärsivät, sielunsa uskolliselle Luojalle, tehden sitä, mikä hyvää on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 1, 'Vanhimpia teidän joukossanne minä siis kehoitan, minä, joka myös olen vanhin ja Kristuksen kärsimysten todistaja ja osallinen myös siihen kirkkauteen, joka vastedes on ilmestyvä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 2, 'kaitkaa teille uskottua Jumalan laumaa, ei pakosta, vaan vapaaehtoisesti, Jumalan tahdon mukaan, ei häpeällisen voiton tähden, vaan sydämen halusta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 3, 'ei herroina halliten niitä, jotka ovat teidän osallenne tulleet, vaan ollen laumalle esikuvina,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 4, 'niin te, ylipaimenen ilmestyessä, saatte kirkkauden kuihtumattoman seppeleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 5, 'Samoin te, nuoremmat, olkaa vanhemmille alamaiset ja pukeutukaa kaikki keskinäiseen nöyryyteen, sillä \"Jumala on ylpeitä vastaan, mutta nöyrille hän antaa armon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 6, 'Nöyrtykää siis Jumalan väkevän käden alle, että hän ajallansa teidät korottaisi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 7, 'ja \"heittäkää kaikki murheenne hänen päällensä, sillä hän pitää teistä huolen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 8, 'Olkaa raittiit, valvokaa. Teidän vastustajanne, perkele, käy ympäri niinkuin kiljuva jalopeura, etsien, kenen hän saisi niellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 9, 'Vastustakaa häntä lujina uskossa, tietäen, että samat kärsimykset täytyy teidän veljiennekin maailmassa kestää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 10, 'Mutta kaiken armon Jumala, joka on kutsunut teidät iankaikkiseen kirkkauteensa Kristuksessa, vähän aikaa kärsittyänne, hän on teidät valmistava, teitä tukeva, vahvistava ja lujittava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 11, 'Hänen olkoon valta aina ja iankaikkisesti! Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 12, 'Silvanuksen, uskollisen veljen, kautta-jona häntä pidän-olen lyhyesti teille tämän kirjoittanut, kehoittaen teitä ja vakuuttaen, että se armo, jossa te olette, on Jumalan totinen armo.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 13, 'Tervehdyksen lähettää teille Babylonissa oleva seurakunta, valittu niinkuin tekin, ja minun poikani Markus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (77, 5, 14, 'Tervehtikää toisianne rakkauden suunannolla. Rauha teille kaikille, jotka Kristuksessa olette!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 1, 'Simeon Pietari, Jeesuksen Kristuksen palvelija ja apostoli, niille, jotka ovat saaneet yhtä kalliin uskon kuin mekin meidän Jumalamme ja Vapahtajan Jeesuksen Kristuksen vanhurskaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 2, 'Armo ja rauha lisääntyköön teille Jumalan ja meidän Herramme Jeesuksen tuntemisen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 3, 'Koska hänen jumalallinen voimansa on lahjoittanut meille kaiken, mikä elämään ja jumalisuuteen tarvitaan, hänen tuntemisensa kautta, joka on kutsunut meidät kirkkaudellaan ja täydellisyydellään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 4, 'joiden kautta hän on lahjoittanut meille kalliit ja mitä suurimmat lupaukset, että te niiden kautta tulisitte jumalallisesta luonnosta osallisiksi ja pelastuisitte siitä turmeluksesta, joka maailmassa himojen tähden vallitsee,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 5, 'niin pyrkikää juuri sentähden kaikella ahkeruudella osoittamaan uskossanne avuja, avuissa ymmärtäväisyyttä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 6, 'ymmärtäväisyydessä itsenne hillitsemistä, itsenne hillitsemisessä kärsivällisyyttä, kärsivällisyydessä jumalisuutta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 7, 'jumalisuudessa veljellistä rakkautta, veljellisessä rakkaudessa yhteistä rakkautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 8, 'Sillä jos teillä on nämä ja ne yhä enenevät, niin ne eivät salli teidän olla toimettomia eikä hedelmättömiä meidän Herramme Jeesuksen Kristuksen tuntemisessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 9, 'Jolla sitävastoin ei niitä ole, se on sokea, likinäköinen, on unhottanut puhdistuneensa entisistä synneistänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 10, 'Pyrkikää sentähden, veljet, sitä enemmän tekemään kutsumisenne ja valitsemisenne lujaksi; sillä jos sen teette, ette koskaan lankea;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 11, 'sillä näin teille runsain määrin tarjotaan pääsy meidän Herramme ja Vapahtajamme Jeesuksen Kristuksen iankaikkiseen valtakuntaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 12, 'Sentähden minä aina aion muistuttaa teitä tästä, vaikka sen tiedättekin ja olette vahvistetut siinä totuudessa, joka teillä on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 13, 'Ja minä katson oikeaksi, niin kauan kuin tässä majassa olen, näin muistuttamalla herättää teitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 14, 'Sillä minä tiedän, että tämän majani poispaneminen tapahtuu äkisti, niinkuin myös meidän Herramme Jeesus Kristus minulle ilmoitti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 15, 'Mutta minä olen huolehtiva siitä, että te minun lähtöni jälkeenkin aina voisitte tämän muistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 16, 'Sillä me emme seuranneet viekkaasti sommiteltuja taruja tehdessämme teille tiettäväksi Herramme Jeesuksen Kristuksen voimaa ja tulemusta, vaan me olimme omin silmin nähneet hänen valtasuuruutensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 17, 'Sillä hän sai Isältä Jumalalta kunnian ja kirkkauden, kun tältä ylhäisimmältä kirkkaudelta tuli hänelle tämä ääni: \"Tämä on minun rakas Poikani, johon minä olen mielistynyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 18, 'Ja tämän äänen me kuulimme tulevan taivaasta, kun olimme hänen kanssaan pyhällä vuorella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 19, 'Ja sitä lujempi on meille nyt profeetallinen sana, ja te teette hyvin, jos otatte siitä vaarin, niinkuin pimeässä paikassa loistavasta lampusta, kunnes päivä valkenee ja kointähti koittaa teidän sydämissänne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 20, 'Ja tietäkää ennen kaikkea se, ettei yksikään Raamatun profetia ole kenenkään omin neuvoin selitettävissä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 1, 21, 'sillä ei koskaan ole mitään profetiaa tuotu esiin ihmisen tahdosta, vaan Pyhän Hengen johtamina ihmiset ovat puhuneet sen, minkä saivat Jumalalta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 1, 'Mutta myös valheprofeettoja oli kansan seassa, niinkuin teidänkin keskuudessanne on oleva valheenopettajia, jotka salaa kuljettavat sisään turmiollisia harhaoppeja, kieltävätpä Herrankin, joka on heidät ostanut, ja tuottavat itselleen äkillisen perikadon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 2, 'Ja moni on seuraava heidän irstauksiaan, ja heidän tähtensä totuuden tie tulee häväistyksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 3, 'ja ahneudessaan he valheellisilla sanoilla kiskovat teistä hyötyä; mutta jo ammoisista ajoista heidän tuomionsa valvoo, eikä heidän perikatonsa torku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 4, 'Sillä ei Jumala säästänyt enkeleitä, jotka syntiä tekivät, vaan syöksi heidät syvyyteen, pimeyden kuiluihin, ja hylkäsi heidät tuomiota varten säilytettäviksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 5, 'Eikä hän säästänyt muinaista maailmaa, vaikka varjelikin Nooan, vanhurskauden saarnaajan, ynnä seitsemän muuta, vaan antoi vedenpaisumuksen tulla jumalattomain maailman päälle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 6, 'Ja hän poltti poroksi Sodoman ja Gomorran kaupungit ja tuomitsi ne häviöön, asettaen ne varoitukseksi niille, jotka vastedes jumalattomasti elävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 7, 'Kuitenkin hän pelasti hurskaan Lootin, jota rietasten vaellus irstaudessa vaivasi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 8, 'sillä asuessaan heidän keskuudessansa tuo hurskas mies kiusaantui hurskaassa sielussaan joka päivä heidän pahain tekojensa tähden, joita hänen täytyi nähdä ja kuulla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 9, 'Näin Herra tietää pelastaa jumaliset kiusauksesta, mutta tuomion päivään säilyttää rangaistuksen alaisina väärät,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 10, 'ja varsinkin ne, jotka lihan jäljessä kulkevat saastaisissa himoissa ja ylenkatsovat herrauden. Nuo uhkarohkeat, itserakkaat eivät kammo herjata henkivaltoja,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 11, 'vaikka enkelitkään, jotka väkevyydeltään ja voimaltaan ovat suuremmat, eivät lausu heitä vastaan herjaavaa tuomiota Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 12, 'Mutta niinkuin järjettömät, luonnostaan pyydystettäviksi ja häviämään syntyneet eläimet, niin joutuvat myös nämä, kun herjaavat sitä, mitä eivät tunne, häviämään omaan turmelukseensa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 13, 'saaden vääryyden palkan; he pitävät nautintonaan elää päivänsä hekumassa; he ovat tahra-ja häpeäpilkkuja; he herkuttelevat petoksissaan, kemuillessaan teidän kanssanne;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 14, 'heidän silmänsä ovat täynnä haureutta eivätkä saa kylläänsä synnistä; he viekoittelevat horjuvia sieluja, heillä on ahneuteen harjaantunut sydän; he ovat kirouksen lapsia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 15, 'He ovat hyljänneet suoran tien, ovat eksyneet ja seuranneet Bileamin, Beorin pojan, tietä, hänen, joka rakasti vääryyden palkkaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 16, 'mutta sai rikkomuksestaan ojennuksen: mykkä juhta puhui ihmisen äänellä ja esti profeetan mielettömyyden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 17, 'Sellaiset ovat vedettömiä lähteitä ja myrskytuulen ajamia hattaroita, ja pimeyden synkeys on heille varattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 18, 'Sillä he puhuvat pöyhkeitä turhuuden sanoja ja viekoittelevat lihan himoissa irstauksilla niitä, jotka tuskin ovat päässeet eksyksissä vaeltavia pakoon,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 19, 'ja lupaavat heille vapautta, vaikka itse ovat turmeluksen orjia; sillä kenen voittama joku on, sen orja hän on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 20, 'Sillä jos he meidän Herramme ja Vapahtajan Jeesuksen Kristuksen tuntemisen kautta ovat päässeetkin maailman saastutuksia pakoon, mutta niihin taas kietoutuvat ja tulevat voitetuiksi, niin on viimeinen tullut heille ensimmäistä pahemmaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 21, 'Parempi olisi heille ollut, etteivät olisi tulleet tuntemaan vanhurskauden tietä, kuin että sen tunnettuaan kääntyvät pois heille annetusta pyhästä käskystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 2, 22, 'Heille on tapahtunut, mitä tosi sananlasku sanoo: \"Koira palaa oksennukselleen\", ja: \"Pesty sika rypee rapakossa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 1, 'Tämä on jo toinen kirje, jonka minä kirjoitan teille, rakkaani, ja näissä molemmissa minä muistuttamalla herätän teidän puhdasta mieltänne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 2, 'että muistaisitte niitä sanoja, joita pyhät profeetat ennen ovat puhuneet, ja Herran ja Vapahtajan käskyä, jonka te apostoleiltanne olette saaneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 3, 'Ja ennen kaikkea tietäkää se, että viimeisinä päivinä tulee pilkkapuheinensa pilkkaajia, jotka vaeltavat omien himojensa mukaan');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 4, 'ja sanovat: \"Missä on lupaus hänen tulemuksestansa? Sillä onhan siitä asti, kuin isät nukkuivat pois, kaikki pysynyt, niinkuin se on ollut luomakunnan alusta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 5, 'Sillä tietensä he eivät ole tietävinään, että taivaat ja samoin maa, vedestä ja veden kautta rakennettu, olivat ikivanhastaan olemassa Jumalan sanan voimasta');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 6, 'ja että niiden kautta silloinen maailma hukkui vedenpaisumukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 7, 'Mutta nykyiset taivaat ja maa ovat samalla sanalla talletetut tulelle, säästetyt jumalattomain ihmisten tuomion ja kadotuksen päivään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 8, 'Mutta tämä yksi älköön olko teiltä, rakkaani, salassa, että \"yksi päivä on Herran edessä niinkuin tuhat vuotta ja tuhat vuotta niinkuin yksi päivä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 9, 'Ei Herra viivytä lupauksensa täyttämistä, niinkuin muutamat pitävät sitä viivyttelemisenä, vaan hän on pitkämielinen teitä kohtaan, sillä hän ei tahdo, että kukaan hukkuu, vaan että kaikki tulevat parannukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 10, 'Mutta Herran päivä on tuleva niinkuin varas, ja silloin taivaat katoavat pauhinalla, ja alkuaineet kuumuudesta hajoavat, ja maa ja kaikki, mitä siihen on tehty, palavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 11, 'Kun siis nämä kaikki näin hajoavat, millaisia tuleekaan teidän olla pyhässä vaelluksessa ja jumalisuudessa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 12, 'teidän, jotka odotatte ja joudutatte Jumalan päivän tulemista, jonka voimasta taivaat hehkuen hajoavat ja alkuaineet kuumuudesta sulavat!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 13, 'Mutta hänen lupauksensa mukaan me odotamme uusia taivaita ja uutta maata, joissa vanhurskaus asuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 14, 'Sentähden, rakkaani, pyrkikää tätä odottaessanne siihen, että teidät havaittaisiin tahrattomiksi ja nuhteettomiksi, rauhassa, hänen edessänsä;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 15, 'ja lukekaa meidän Herramme pitkämielisyys pelastukseksi, josta myös meidän rakas veljemme Paavali hänelle annetun viisauden mukaan teille on kirjoittanut;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 16, 'niinkuin hän tekee kaikissa kirjeissään, kun hän niissä puhuu näistä asioista, vaikka niissä tosin on yhtä ja toista vaikeatajuista, jota tietämättömät ja vakaantumattomat vääntävät kieroon niinkuin muitakin kirjoituksia, omaksi kadotuksekseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 17, 'Koska te siis, rakkaani, tämän jo edeltäpäin tiedätte, niin olkaa varuillanne, ettette rietasten eksymyksen mukaansa tempaamina lankeaisi pois omalta lujalta pohjaltanne,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (78, 3, 18, 'ja kasvakaa meidän Herramme ja Vapahtajamme Jeesuksen Kristuksen armossa ja tuntemisessa. Hänen olkoon kunnia sekä nyt että hamaan iankaikkisuuden päivään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 1, 'Mikä on alusta ollut, minkä olemme kuulleet, minkä omin silmin nähneet, mitä katselimme ja käsin kosketimme, siitä me puhumme: elämän Sanasta-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 2, 'ja elämä ilmestyi, ja me olemme nähneet sen ja todistamme siitä ja julistamme teille sen iankaikkisen elämän, joka oli Isän tykönä ja ilmestyi meille-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 3, 'minkä olemme nähneet ja kuulleet, sen me myös teille julistamme, että teilläkin olisi yhteys meidän kanssamme; ja meillä on yhteys Isän ja hänen Poikansa, Jeesuksen Kristuksen, kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 4, 'Ja tämän me kirjoitamme, että meidän ilomme olisi täydellinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 5, 'Ja tämä on se sanoma, jonka olemme häneltä kuulleet ja jonka me teille julistamme: että Jumala on valkeus ja ettei hänessä ole mitään pimeyttä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 6, 'Jos sanomme, että meillä on yhteys hänen kanssaan, mutta vaellamme pimeydessä, niin me valhettelemme emmekä tee totuutta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 7, 'Mutta jos me valkeudessa vaellamme, niinkuin hän on valkeudessa, niin meillä on yhteys keskenämme, ja Jeesuksen Kristuksen, hänen Poikansa, veri puhdistaa meidät kaikesta synnistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 8, 'Jos sanomme, ettei meillä ole syntiä, niin me eksytämme itsemme, ja totuus ei ole meissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 9, 'Jos me tunnustamme syntimme, on hän uskollinen ja vanhurskas, niin että hän antaa meille synnit anteeksi ja puhdistaa meidät kaikesta vääryydestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 1, 10, 'Jos sanomme, ettemme ole syntiä tehneet, niin me teemme hänet valhettelijaksi, ja hänen sanansa ei ole meissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 1, 'Lapsukaiseni, tämän minä kirjoitan teille, ettette syntiä tekisi; mutta jos joku syntiä tekeekin, niin meillä on puolustaja Isän tykönä, Jeesus Kristus, joka on vanhurskas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 2, 'Ja hän on meidän syntiemme sovitus; eikä ainoastaan meidän, vaan myös koko maailman syntien.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 3, 'Ja siitä me tiedämme hänet tuntevamme, että pidämme hänen käskynsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 4, 'Joka sanoo: \"Minä tunnen hänet\", eikä pidä hänen käskyjänsä, se on valhettelija, ja totuus ei ole hänessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 5, 'Mutta joka pitää hänen sanansa, hänessä on Jumalan rakkaus totisesti täydelliseksi tullut. Siitä me tiedämme, että me hänessä olemme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 6, 'Joka sanoo hänessä pysyvänsä, on velvollinen vaeltamaan, niinkuin hän vaelsi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 7, 'Rakkaani, en minä kirjoita teille uutta käskyä, vaan vanhan käskyn, joka teillä on alusta ollut; tämä vanha käsky on se sana, jonka te olette kuulleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 8, 'Ja kuitenkin minä kirjoitan teille uuden käskyn, sen, mikä on totta hänessä ja teissä; sillä pimeys katoaa, ja totinen valkeus jo loistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 9, 'Joka sanoo valkeudessa olevansa, mutta vihaa veljeänsä, se on yhä vielä pimeydessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 10, 'Joka rakastaa veljeänsä, se pysyy valkeudessa, ja hänessä ei ole pahennusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 11, 'Mutta joka vihaa veljeänsä, se on pimeydessä ja vaeltaa pimeydessä, eikä hän tiedä, mihin menee; sillä pimeys on sokaissut hänen silmänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 12, 'Minä kirjoitan teille, lapsukaiset, sillä synnit ovat teille anteeksi annetut hänen nimensä tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 13, 'Minä kirjoitan teille, isät, sillä te olette oppineet tuntemaan hänet, joka alusta on ollut. Minä kirjoitan teille, nuorukaiset, sillä te olette voittaneet sen, joka on paha. Minä olen kirjoittanut teille, lapsukaiset, sillä te olette oppineet tuntemaan Isän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 14, 'Minä olen kirjoittanut teille, isät, sillä te olette oppineet tuntemaan hänet, joka alusta on ollut. Minä olen kirjoittanut teille, nuorukaiset, sillä te olette väkevät, ja Jumalan sana pysyy teissä, ja te olette voittaneet sen, joka on paha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 15, 'Älkää rakastako maailmaa älkääkä sitä, mikä maailmassa on. Jos joku maailmaa rakastaa, niin Isän rakkaus ei ole hänessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 16, 'Sillä kaikki, mikä maailmassa on, lihan himo, silmäin pyyntö ja elämän korskeus, se ei ole Isästä, vaan maailmasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 17, 'Ja maailma katoaa ja sen himo; mutta joka tekee Jumalan tahdon, se pysyy iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 18, 'Lapsukaiset, nyt on viimeinen aika. Ja niinkuin te olette kuulleet, että antikristus tulee, niin onkin nyt monta antikristusta ilmaantunut; siitä me tiedämme, että nyt on viimeinen aika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 19, 'Meistä he ovat lähteneet, mutta he eivät olleet yhtä meidän kanssamme; sillä jos he olisivat olleet yhtä meidän kanssamme, niin he olisivat meidän kanssamme pysyneet; mutta heissä oli tuleva ilmi, että kaikki eivät ole yhtä meidän kanssamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 20, 'Teillä on voitelu Pyhältä, ja kaikilla teillä on tieto.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 21, 'En minä ole kirjoittanut teille sentähden, ettette totuutta tiedä, vaan sentähden, että te tiedätte sen ja ettei mikään valhe ole totuudesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 22, 'Kuka on valhettelija, ellei se, joka kieltää sen, että Jeesus on Kristus? Hän on antikristus, se, joka kieltää Isän ja Pojan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 23, 'Kuka ikinä kieltää Pojan, hänellä ei ole Isääkään. Joka tunnustaa Pojan, hänellä on myös Isä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 24, 'Minkä te olette alusta asti kuulleet, se pysyköön teissä. Jos teissä pysyy se, minkä olette alusta asti kuulleet, niin tekin pysytte Pojassa ja Isässä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 25, 'Ja tämä on se lupaus, minkä hän on meille luvannut: iankaikkinen elämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 26, 'Tämän minä olen kirjoittanut teille niistä, jotka teitä eksyttävät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 27, 'Mutta te-teissä pysyy se voitelu, jonka olette häneltä saaneet, ja te ette ole kenenkään opetuksen tarpeessa; vaan niinkuin hänen voitelunsa opettaa teitä kaikessa, niin se opetus on myös totta eikä ole valhetta; ja niinkuin se on opettanut teitä, niin pysykää hänessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 28, 'Ja nyt, lapsukaiset, pysykää hänessä, että meillä hänen ilmestyessään olisi turva eikä meitä häpeällä karkoitettaisi pois hänen tyköänsä hänen tulemuksessaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 2, 29, 'Jos tiedätte, että hän on vanhurskas, niin te ymmärrätte, että myös jokainen, joka vanhurskauden tekee, on hänestä syntynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 1, 'Katsokaa, minkäkaltaisen rakkauden Isä on meille antanut, että meitä kutsutaan Jumalan lapsiksi, joita me olemmekin. Sentähden ei maailma tunne meitä, sillä se ei tunne häntä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 2, 'Rakkaani, nyt me olemme Jumalan lapsia, eikä ole vielä käynyt ilmi, mitä meistä tulee. Me tiedämme tulevamme hänen kaltaisikseen, kun hän ilmestyy, sillä me saamme nähdä hänet sellaisena, kuin hän on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 3, 'Ja jokainen, joka panee häneen tämän toivon, puhdistaa itsensä, niinkuin hän on puhdas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 4, 'Jokainen, joka tekee synnin, tekee myös laittomuuden; ja synti on laittomuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 5, 'Ja te tiedätte hänen ilmestyneen ottamaan pois synnit; ja hänessä ei ole syntiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 6, 'Kuka ikinä hänessä pysyy, hän ei tee syntiä; kuka ikinä syntiä tekee, hän ei ole häntä nähnyt eikä häntä tuntenut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 7, 'Lapsukaiset, älköön kukaan saako teitä eksyttää. Se, joka vanhurskauden tekee, on vanhurskas, niinkuin hän on vanhurskas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 8, 'Joka syntiä tekee, se on perkeleestä, sillä perkele on tehnyt syntiä alusta asti. Sitä varten Jumalan Poika ilmestyi, että hän tekisi tyhjäksi perkeleen teot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 9, 'Ei yksikään Jumalasta syntynyt tee syntiä, sillä Jumalan siemen pysyy hänessä; eikä hän saata syntiä tehdä, sillä hän on Jumalasta syntynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 10, 'Siitä käy ilmi, ketkä ovat Jumalan lapsia ja ketkä perkeleen lapsia. Kuka ikinä ei tee vanhurskautta, hän ei ole Jumalasta, ei myöskään se, joka ei veljeänsä rakasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 11, 'Sillä tämä on se sanoma, jonka te olette alusta asti kuulleet, että meidän tulee rakastaa toinen toistamme');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 12, 'eikä olla Kainin kaltaisia, joka oli pahasta ja tappoi veljensä. Ja minkätähden hän tappoi hänet? Sentähden, että hänen tekonsa olivat pahat, mutta hänen veljensä teot vanhurskaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 13, 'Älkää ihmetelkö, veljeni, jos maailma teitä vihaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 14, 'Me tiedämme siirtyneemme kuolemasta elämään, sillä me rakastamme veljiä. Joka ei rakasta, pysyy kuolemassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 15, 'Jokainen, joka vihaa veljeänsä, on murhaaja; ja te tiedätte, ettei kenessäkään murhaajassa ole iankaikkista elämää, joka hänessä pysyisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 16, 'Siitä me olemme oppineet tuntemaan rakkauden, että hän antoi henkensä meidän edestämme; meidänkin tulee antaa henkemme veljiemme edestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 17, 'Jos nyt jollakin on tämän maailman hyvyyttä ja hän näkee veljensä olevan puutteessa, mutta sulkee häneltä sydämensä, kuinka Jumalan rakkaus saattaa pysyä hänessä?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 18, 'Lapsukaiset, älkäämme rakastako sanalla tai kielellä, vaan teossa ja totuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 19, 'Siitä me tiedämme, että olemme totuudesta, ja me saatamme hänen edessään rauhoittaa sydämemme sillä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 20, 'että jos sydämemme syyttää meitä, niin Jumala on suurempi kuin meidän sydämemme ja tietää kaikki.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 21, 'Rakkaani, jos sydämemme ei syytä meitä, niin meillä on uskallus Jumalaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 22, 'ja mitä ikinä anomme, sen me häneltä saamme, koska pidämme hänen käskynsä ja teemme sitä, mikä on hänelle otollista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 23, 'Ja tämä on hänen käskynsä, että meidän tulee uskoa hänen Poikansa Jeesuksen Kristuksen nimeen ja rakastaa toinen toistamme, niinkuin hän on meille käskyn antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 3, 24, 'Ja joka pitää hänen käskynsä, se pysyy Jumalassa ja Jumala hänessä. Ja siitä me tiedämme hänen meissä pysyvän, siitä Hengestä, jonka hän on meille antanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 1, 'Rakkaani, älkää jokaista henkeä uskoko, vaan koetelkaa henget, ovatko ne Jumalasta; sillä monta väärää profeettaa on lähtenyt maailmaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 2, 'Tästä te tunnette Jumalan Hengen: jokainen henki, joka tunnustaa Jeesuksen Kristukseksi, lihaan tulleeksi, on Jumalasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 3, 'ja yksikään henki, joka ei tunnusta Jeesusta, ei ole Jumalasta; se on antikristuksen henki, jonka olette kuulleet olevan tulossa, ja se on jo nyt maailmassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 4, 'Lapsukaiset, te olette Jumalasta ja olette voittaneet heidät; sillä hän, joka teissä on, on suurempi kuin se, joka on maailmassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 5, 'He ovat maailmasta; sentähden he puhuvat, niinkuin maailma puhuu, ja maailma kuulee heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 6, 'Me olemme Jumalasta. Joka tuntee Jumalan, se kuulee meitä; joka ei ole Jumalasta, se ei kuule meitä. Siitä me tunnemme totuuden hengen ja eksytyksen hengen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 7, 'Rakkaani, rakastakaamme toinen toistamme, sillä rakkaus on Jumalasta; ja jokainen, joka rakastaa, on Jumalasta syntynyt ja tuntee Jumalan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 8, 'Joka ei rakasta, se ei tunne Jumalaa, sillä Jumala on rakkaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 9, 'Siinä ilmestyi meille Jumalan rakkaus, että Jumala lähetti ainokaisen Poikansa maailmaan, että me eläisimme hänen kauttansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 10, 'Siinä on rakkaus-ei siinä, että me rakastimme Jumalaa, vaan siinä, että hän rakasti meitä ja lähetti Poikansa meidän syntiemme sovitukseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 11, 'Rakkaani, jos Jumala on näin meitä rakastanut, niin mekin olemme velvolliset rakastamaan toinen toistamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 12, 'Jumalaa ei kukaan ole koskaan nähnyt. Jos me rakastamme toinen toistamme, niin Jumala pysyy meissä, ja hänen rakkautensa on tullut täydelliseksi meissä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 13, 'Siitä me tiedämme pysyvämme hänessä ja hänen pysyvän meissä, että hän on antanut meille Henkeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 14, 'Ja me olemme nähneet ja todistamme, että Isä on lähettänyt Poikansa maailman Vapahtajaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 15, 'Joka tunnustaa, että Jeesus on Jumalan Poika, hänessä Jumala pysyy, ja hän Jumalassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 16, 'Ja me olemme oppineet tuntemaan ja me uskomme sen rakkauden, mikä Jumalalla on meihin. Jumala on rakkaus, ja joka pysyy rakkaudessa, se pysyy Jumalassa, ja Jumala pysyy hänessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 17, 'Näin on rakkaus tullut täydelliseksi meissä, että meillä olisi turva tuomiopäivänä; sillä sellainen kuin hän on, sellaisia mekin olemme tässä maailmassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 18, 'Pelkoa ei rakkaudessa ole, vaan täydellinen rakkaus karkoittaa pelon, sillä pelossa on rangaistusta; ja joka pelkää, se ei ole päässyt täydelliseksi rakkaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 19, 'Me rakastamme, sillä hän on ensin rakastanut meitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 20, 'Jos joku sanoo: \"Minä rakastan Jumalaa\", mutta vihaa veljeänsä, niin hän on valhettelija. Sillä joka ei rakasta veljeänsä, jonka hän on nähnyt, se ei voi rakastaa Jumalaa, jota hän ei ole nähnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 4, 21, 'Ja tämä käsky meillä on häneltä, että joka rakastaa Jumalaa, se rakastakoon myös veljeänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 1, 'Jokainen, joka uskoo, että Jeesus on Kristus, on Jumalasta syntynyt; ja jokainen, joka rakastaa häntä, joka on synnyttänyt, rakastaa myöskin sitä, joka hänestä on syntynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 2, 'Siitä me tiedämme, että rakastamme Jumalan lapsia, kun rakastamme Jumalaa ja noudatamme hänen käskyjänsä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 3, 'Sillä rakkaus Jumalaan on se, että pidämme hänen käskynsä. Ja hänen käskynsä eivät ole raskaat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 4, 'sillä kaikki, mikä on syntynyt Jumalasta, voittaa maailman; ja tämä on se voitto, joka on maailman voittanut, meidän uskomme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 5, 'Kuka on se, joka voittaa maailman, ellei se, joka uskoo, että Jeesus on Jumalan Poika?');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 6, 'Hän on se, joka on tullut veden ja veren kautta, Jeesus Kristus, ei ainoastaan vedessä, vaan vedessä ja veressä; ja Henki on se, joka todistaa, sillä Henki on totuus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 7, 'Sillä kolme on, jotka todistavat:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 8, 'Henki ja vesi ja veri, ja ne kolme pitävät yhtä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 9, 'Jos me otamme vastaan ihmisten todistuksen, niin onhan Jumalan todistus suurempi. Ja tämä on Jumalan todistus, sillä hän on todistanut Pojastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 10, 'Joka uskoo Jumalan Poikaan, hänellä on todistus itsessänsä; joka ei usko Jumalaa, tekee hänet valhettelijaksi, koska hän ei usko sitä todistusta, jonka Jumala on todistanut Pojastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 11, 'Ja tämä on se todistus: Jumala on antanut meille iankaikkisen elämän, ja tämä elämä on hänen Pojassansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 12, 'Jolla Poika on, sillä on elämä; jolla Jumalan Poikaa ei ole, sillä ei ole elämää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 13, 'Tämän minä olen kirjoittanut teille, jotka uskotte Jumalan Pojan nimeen, tietääksenne, että teillä on iankaikkinen elämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 14, 'Ja tämä on se uskallus, joka meillä on häneen, että jos me jotakin anomme hänen tahtonsa mukaan, niin hän kuulee meitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 15, 'Ja jos me tiedämme hänen kuulevan meitä, mitä ikinä anommekin, niin tiedämme, että meillä myös on kaikki se, mitä olemme häneltä anoneet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 16, 'Jos joku näkee veljensä tekevän syntiä, joka ei ole kuolemaksi, niin rukoilkoon, ja hän on antava hänelle elämän, niille nimittäin, jotka eivät tee syntiä kuolemaksi. On syntiä, joka on kuolemaksi; siitä minä en sano, että olisi rukoiltava.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 17, 'Kaikki vääryys on syntiä. Ja on syntiä, joka ei ole kuolemaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 18, 'Me tiedämme, ettei yksikään Jumalasta syntynyt tee syntiä; vaan Jumalasta syntynyt pitää itsestänsä vaarin, eikä häneen ryhdy se paha.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 19, 'Me tiedämme, että olemme Jumalasta, ja koko maailma on pahan vallassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 20, 'Mutta me tiedämme, että Jumalan Poika on tullut ja antanut meille ymmärryksen, tunteaksemme sen Totisen; ja me olemme siinä Totisessa, hänen Pojassansa, Jeesuksessa Kristuksessa. Hän on totinen Jumala ja iankaikkinen elämä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (79, 5, 21, 'Lapsukaiset, kavahtakaa epäjumalia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 1, 'Vanhin valitulle rouvalle ja hänen lapsillensa, joita minä totuudessa rakastan-enkä ainoastaan minä, vaan myös kaikki, jotka ovat tulleet totuuden tuntemaan-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 2, 'totuuden tähden, joka meissä pysyy ja on oleva meidän kanssamme iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 3, 'Armo, laupeus ja rauha Isältä Jumalalta ja Jeesukselta Kristukselta, Isän Pojalta, on oleva meidän kanssamme, totuudessa ja rakkaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 4, 'Minua on suuresti ilahuttanut, että olen lastesi joukossa havainnut olevan niitä, jotka totuudessa vaeltavat sen käskyn mukaan, jonka me olemme saaneet Isältä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 5, 'Ja nyt, rouva, minulla on sinulle pyyntö, ei niinkuin kirjoittaisin sinulle uuden käskyn, vaan minä kirjoitan sen, joka meillä alusta asti on ollut: että meidän tulee rakastaa toinen toistamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 6, 'Ja tämä on rakkaus, että me vaellamme hänen käskyjensä mukaan. Tämä on käsky, että teidän, niinkuin olette alusta kuulleet, tulee siinä vaeltaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 7, 'Sillä monta villitsijää on lähtenyt maailmaan, jotka eivät tunnusta Jeesusta Kristukseksi, joka oli lihaan tuleva; tämä tämmöinen on villitsijä ja antikristus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 8, 'Ottakaa vaari itsestänne, ettette menetä sitä, minkä me olemme työllämme aikaansaaneet, vaan että saatte täyden palkan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 9, 'Kuka ikinä menee edemmäksi eikä pysy Kristuksen opissa, hänellä ei ole Jumalaa; joka siinä opissa pysyy, hänellä on sekä Isä että Poika.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 10, 'Jos joku tulee teidän luoksenne eikä tuo mukanaan tätä oppia, niin älkää ottako häntä huoneeseenne älkääkä sanoko häntä tervetulleeksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 11, 'sillä joka sanoo hänet tervetulleeksi, joutuu osalliseksi hänen pahoihin tekoihinsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 12, 'Minulla olisi paljon kirjoittamista teille, mutta en tahdo tehdä sitä paperilla ja musteella; vaan toivon pääseväni teidän tykönne ja saavani puhutella teitä suullisesti, että meidän ilomme olisi täydellinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (80, 1, 13, 'Valitun sisaresi lapset lähettävät sinulle tervehdyksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 1, 'Vanhin rakkaalle Gaiukselle, jota minä totuudessa rakastan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 2, 'Rakkaani, minä toivotan sinulle, että kaikessa menestyt ja pysyt terveenä, niinkuin sielusikin menestyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 3, 'Minua ilahutti suuresti, kun veljet tulivat ja antoivat todistuksen sinun totuudestasi, niinkuin sinä totuudessa vaellatkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 4, 'Minulla ei ole suurempaa iloa kuin se, että kuulen lasteni vaeltavan totuudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 5, 'Rakkaani, sinä toimit uskollisesti kaikessa, mitä teet veljien, vieläpä vieraittenkin hyväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 6, 'He ovat seurakunnan edessä antaneet todistuksen sinun rakkaudestasi; ja sinä teet hyvin, kun autat heitä eteenpäin heidän matkallaan, niinkuin Jumalan edessä arvollista on.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 7, 'Sillä hänen nimensä tähden he ovat matkalle lähteneet eivätkä ota pakanoilta mitään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 8, 'Me olemme siis velvolliset ottamaan semmoisia vastaan, auttaaksemme yhdessä totuutta eteenpäin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 9, 'Minä kirjoitin seurakunnalle; mutta Diotrefes, joka haluaa olla ensimmäinen heidän joukossaan, ei ota meitä vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 10, 'Sentähden minä, jos tulen, muistutan hänen teoistansa, mitä hän tekee, kun pahoilla sanoilla meistä juoruaa; ja vielä siihenkään tyytymättä, hän ei itse ota veljiä vastaan, vaan estää niitäkin, jotka tahtovat sen tehdä, ja ajaa heidät pois seurakunnasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 11, 'Rakkaani, älä seuraa pahaa, vaan hyvää. Joka hyvin tekee, se on Jumalasta; joka pahoin tekee, se ei ole Jumalaa nähnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 12, 'Demetrius on kaikilta, jopa itse totuudeltakin, saanut hyvän todistuksen; ja mekin todistamme hänestä samaa, ja sinä tiedät, että meidän todistuksemme on tosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 13, 'Minulla olisi paljon kirjoittamista sinulle, mutta en tahdo kirjoittaa sinulle musteella ja kynällä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 14, 'sillä minä toivon pian näkeväni sinut, ja silloin saamme suullisesti puhella. {1:15} Rauha sinulle! Ystävät tervehtivät sinua. Tervehdys ystäville, kullekin erikseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (81, 1, 15, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 1, 'Juudas, Jeesuksen Kristuksen palvelija ja Jaakobin veli, kutsutuille, jotka ovat Isässä Jumalassa rakastetut ja Jeesukselle Kristukselle varjellut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 2, 'Lisääntyköön teille laupeus ja rauha ja rakkaus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 3, 'Rakkaani! Kun minulla on ollut harras halu kirjoittaa teille yhteisestä pelastuksestamme, tuli minulle pakko kirjoittaa ja kehoittaa teitä kilvoittelemaan sen uskon puolesta, joka kerta kaikkiaan on pyhille annettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 4, 'Sillä teidän keskuuteenne on pujahtanut eräitä ihmisiä, joiden jo aikoja sitten on kirjoitettu tulevan tähän tuomioon, jumalattomia, jotka kääntävät meidän Jumalamme armon irstaudeksi ja kieltävät meidän ainoan valtiaamme ja Herramme, Jeesuksen Kristuksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 5, 'Vaikka jo kerran olette saaneet tietää kaiken, tahdon kuitenkin muistuttaa teitä siitä, että Herra, joka oli pelastanut kansan Egyptistä, toisella kertaa hukutti ne, jotka eivät uskoneet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 6, 'ja että hän ne enkelit, jotka eivät säilyttäneet valta-asemaansa, vaan jättivät oman asumuksensa, pani pimeyteen iankaikkisissa kahleissa säilytettäviksi suuren päivän tuomioon;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 7, 'samoin kuin Sodoma ja Gomorra ja niiden ympärillä olevat kaupungit, jotka samalla tavalla kuin nekin harjoittivat haureutta ja eksyivät luonnottomiin lihanhimoihin, ovat varoittavana esimerkkinä, kärsiessään iankaikkisen tulen rangaistusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 8, 'Yhtäkaikki nämä uneksijat samoin saastuttavat lihan; he halveksivat herrautta, herjaavat kirkkauden henkiolentoja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 9, 'Mutta ei ylienkeli Miikaelkaan, kun riiteli ja väitteli perkeleen kanssa Mooseksen ruumiista, rohjennut lausua herjaavaa tuomiota, vaan sanoi: \"Rangaiskoon sinua Herra!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 10, 'Nämä sitävastoin herjaavat sitä, mitä eivät tunne; mutta minkä he järjettömäin eläinten tavoin luonnostaan ymmärtävät, sillä he turmelevat itsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 11, 'Voi heitä, sillä he kulkevat Kainin tietä ja heittäytyvät palkan tähden Bileamin eksytykseen ja hukkuvat niskoitteluunsa niinkuin Koora!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 12, 'He likapilkkuina teidän rakkausaterioillanne julkeasti kemuilevat ja itseään kestitsevät. He ovat vedettömiä, tuulten ajeltavia pilviä, paljaita, syksyisiä puita, hedelmättömiä, kahdesti kuolleita, juurineen maasta reväistyjä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 13, 'rajuja meren aaltoja, jotka vaahtoavat omia häpeitään, harhailevia tähtiä, joille pimeyden synkeys ikuisiksi ajoiksi on varattu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 14, 'Heistäkin Eenok, Aadamista seitsemäs, on ennustanut, sanoen: \"Katso, Herra tulee tuhannen tuhansine pyhinensä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 15, 'tuomitsemaan kaikkia ja rankaisemaan kaikkia jumalattomia kaikista heidän jumalattomista teoistansa, joita he jumalattomuudessaan ovat tehneet, ja kaikesta julkeasta, mitä nuo jumalattomat syntiset ovat häntä vastaan puhuneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 16, 'He ovat napisijoita, kohtalonsa nurkujia ja vaeltavat himojensa mukaan; heidän suunsa puhuu pöyhkeitä, ja he mielistelevät ihmisiä oman etunsa tähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 17, 'Mutta te, rakkaani, muistakaa nämä sanat, mitkä meidän Herramme Jeesuksen Kristuksen apostolit ovat edeltäpäin puhuneet,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 18, 'sanoen teille: \"Viimeisenä aikana tulee pilkkaajia, jotka vaeltavat jumalattomuutensa himojen mukaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 19, 'Nämä juuri saavat aikaan hajaannusta, he ovat sielullisia, henkeä heillä ei ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 20, 'Mutta te, rakkaani, rakentakaa itseänne pyhimmän uskonne perustukselle, rukoilkaa Pyhässä Hengessä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 21, 'ja pysyttäkää niin itsenne Jumalan rakkaudessa, odottaessanne meidän Herramme Jeesuksen Kristuksen laupeutta iankaikkiseksi elämäksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 22, 'Ja armahtakaa toisia, niitä, jotka epäilevät, pelastakaa heidät, tulesta temmaten;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 23, 'toisia taas armahtakaa pelolla, inhoten lihan tahraamaa ihokastakin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 24, 'Mutta hänelle, joka voi varjella teidät lankeamasta ja asettaa teidät nuhteettomina, riemuitsevina, kirkkautensa eteen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (82, 1, 25, 'hänelle, ainoalle Jumalalle ja meidän pelastajallemme Herramme Jeesuksen Kristuksen kautta, hänelle kunnia, majesteetti, voima ja valta ennen kaikkia aikoja ja nyt ja iankaikkisesti! Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 1, 'Jeesuksen Kristuksen ilmestys, jonka Jumala antoi hänelle, näyttääkseen palvelijoillensa, mitä pian tapahtuman pitää; ja sen hän lähettämänsä enkelin kautta antoi tiedoksi palvelijalleen Johannekselle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 2, 'joka tässä todistaa Jumalan sanan ja Jeesuksen Kristuksen todistuksen, kaiken sen, minkä hän on nähnyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 3, 'Autuas se, joka lukee, ja autuaat ne, jotka kuulevat tämän profetian sanat ja ottavat vaarin siitä, mitä siihen kirjoitettu on; sillä aika on lähellä!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 4, 'Johannes seitsemälle Aasian seurakunnalle: Armo teille ja rauha häneltä, joka on ja joka oli ja joka tuleva on, ja niiltä seitsemältä hengeltä, jotka ovat hänen valtaistuimensa edessä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 5, 'ja Jeesukselta Kristukselta, uskolliselta todistajalta, häneltä, joka on kuolleitten esikoinen ja maan kuningasten hallitsija! Hänelle, joka meitä rakastaa ja on päästänyt meidät synneistämme verellänsä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 6, 'ja tehnyt meidät kuningaskunnaksi, papeiksi Jumalalleen ja Isälleen, hänelle kunnia ja voima aina ja iankaikkisesti! Amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 7, 'Katso, hän tulee pilvissä, ja kaikki silmät saavat nähdä hänet, niidenkin, jotka hänet lävistivät, ja kaikki maan sukukunnat vaikeroitsevat hänen tullessansa. Totisesti, amen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 8, '\"Minä olen A ja O\", sanoo Herra Jumala, joka on ja joka oli ja joka tuleva on, Kaikkivaltias.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 9, 'Minä, Johannes, teidän veljenne, joka teidän kanssanne olen osallinen ahdistukseen ja valtakuntaan ja kärsivällisyyteen Jeesuksessa, minä olin Jumalan sanan ja Jeesuksen todistuksen tähden saaressa, jonka nimi on Patmos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 10, 'Minä olin hengessä Herran päivänä, ja kuulin takaani suuren äänen, ikäänkuin pasunan äänen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 11, 'joka sanoi: \"Kirjoita kirjaan, mitä näet, ja lähetä niille seitsemälle seurakunnalle, Efesoon ja Smyrnaan ja Pergamoon ja Tyatiraan ja Sardeeseen ja Filadelfiaan ja Laodikeaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 12, 'Ja minä käännyin katsomaan, mikä ääni minulle puhui; ja kääntyessäni minä näin seitsemän kultaista lampunjalkaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 13, 'ja lampunjalkain keskellä Ihmisen Pojan muotoisen, pitkäliepeiseen viittaan puetun ja rinnan kohdalta kultaisella vyöllä vyötetyn.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 14, 'Ja hänen päänsä ja hiuksensa olivat valkoiset niinkuin valkoinen villa, niinkuin lumi, ja hänen silmänsä niinkuin tulen liekki;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 15, 'hänen jalkansa olivat ahjossa hehkuvan, kiiltävän vasken kaltaiset, ja hänen äänensä oli niinkuin paljojen vetten pauhina.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 16, 'Ja hänellä oli oikeassa kädessään seitsemän tähteä, ja hänen suustaan lähti kaksiteräinen, terävä miekka, ja hänen kasvonsa olivat niinkuin aurinko, kun se täydeltä terältä paistaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 17, 'Ja kun minä hänet näin, kaaduin minä kuin kuolleena hänen jalkojensa juureen. Ja hän pani oikean kätensä minun päälleni sanoen: \"Älä pelkää! Minä olen ensimmäinen ja viimeinen,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 18, 'ja minä elän; ja minä olin kuollut, ja katso, minä elän aina ja iankaikkisesti, ja minulla on kuoleman ja tuonelan avaimet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 19, 'Kirjoita siis, mitä olet nähnyt ja mikä nyt on ja mitä tämän jälkeen on tapahtuva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 1, 20, 'Niiden seitsemän tähden salaisuus, jotka näit minun oikeassa kädessäni, ja niiden seitsemän kultaisen lampunjalan salaisuus on tämä: ne seitsemän tähteä ovat niiden seitsemän seurakunnan enkelit, ja ne seitsemän lampunjalkaa ovat ne seitsemän seurakuntaa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 1, '\"Efeson seurakunnan enkelille kirjoita: \'Näin sanoo hän, joka pitää niitä seitsemää tähteä oikeassa kädessään, hän, joka käyskelee niiden seitsemän kultaisen lampunjalan keskellä:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 2, 'Minä tiedän sinun tekosi ja vaivannäkösi ja kärsivällisyytesi, ja ettet voi pahoja sietää; sinä olet koetellut niitä, jotka sanovat itseänsä apostoleiksi, eivätkä ole, ja olet havainnut heidät valhettelijoiksi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 3, 'ja sinulla on kärsivällisyyttä, ja paljon sinä olet saanut kantaa minun nimeni tähden, etkä ole uupunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 4, 'Mutta se minulla on sinua vastaan, että olet hyljännyt ensimmäisen rakkautesi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 5, 'Muista siis, mistä olet langennut, ja tee parannus, ja tee niitä ensimmäisiä tekoja; mutta jos et, niin minä tulen sinun tykösi ja työnnän sinun lampunjalkasi pois paikaltaan, ellet tee parannusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 6, 'Mutta se sinulla on, että sinä vihaat nikolaiittain tekoja, joita myös minä vihaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 7, 'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo. Sen, joka voittaa, minä annan syödä elämän puusta, joka on Jumalan paratiisissa.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 8, 'Ja Smyrnan seurakunnan enkelille kirjoita: \'Näin sanoo ensimmäinen ja viimeinen, joka kuoli ja virkosi elämään:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 9, 'Minä tiedän sinun ahdistuksesi ja köyhyytesi-sinä olet kuitenkin rikas-ja mitä pilkkaa sinä kärsit niiltä, jotka sanovat olevansa juutalaisia, eivätkä ole, vaan ovat saatanan synagooga.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 10, 'Älä pelkää sitä, mitä tulet kärsimään. Katso, perkele on heittävä muutamia teistä vankeuteen, että teidät pantaisiin koetukselle, ja teidän on oltava ahdistuksessa kymmenen päivää. Ole uskollinen kuolemaan asti, niin minä annan sinulle elämän kruunun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 11, 'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo. Sitä, joka voittaa, ei toinen kuolema vahingoita.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 12, 'Ja Pergamon seurakunnan enkelille kirjoita: \'Näin sanoo hän, jolla on se kaksiteräinen, terävä miekka:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 13, 'Minä tiedän, missä sinä asut: siellä, missä saatanan valtaistuin on; ja sinä pidät minun nimestäni kiinni etkä ole kieltänyt minun uskoani niinäkään päivinä, jolloin Antipas, minun todistajani, minun uskolliseni, tapettiin teidän luonanne, siellä, missä saatana asuu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 14, 'Mutta minulla on vähän sinua vastaan: sinulla on siellä niitä, jotka pitävät kiinni Bileamin opista, hänen, joka opetti Baalakia virittämään Israelin lapsille sen viettelyksen, että söisivät epäjumalille uhrattua ja haureutta harjoittaisivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 15, 'Niin on myös sinulla niitä, jotka samoin pitävät kiinni nikolaiittain opista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 16, 'Tee siis parannus; mutta jos et, niin minä tulen sinun tykösi pian ja sodin heitä vastaan suuni miekalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 17, 'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo. Sille, joka voittaa, minä annan salattua mannaa ja annan hänelle valkoisen kiven ja siihen kiveen kirjoitetun uuden nimen, jota ei tiedä kukaan muu kuin sen saaja.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 18, 'Ja Tyatiran seurakunnan enkelille kirjoita: \'Näin sanoo Jumalan Poika, jolla on silmät niinkuin tulen liekki ja jonka jalat ovat niinkuin kiiltävä vaski:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 19, 'Minä tiedän sinun tekosi ja rakkautesi ja uskosi ja palveluksesi ja kärsivällisyytesi ja että sinun viimeiset tekosi ovat useammat kuin ensimmäiset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 20, 'Mutta se minulla on sinua vastaan, että sinä suvaitset tuota naista, Iisebeliä, joka sanoo itseään profeetaksi ja opettaa ja eksyttää minun palvelijoitani harjoittamaan haureutta ja syömään epäjumalille uhrattua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 21, 'Ja minä olen antanut hänelle aikaa parannuksen tekoon, mutta hän ei tahdo parannusta tehdä eikä luopua haureudestaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 22, 'Katso, minä syöksen hänet tautivuoteeseen, ja ne, jotka hänen kanssaan tekevät huorin, minä syöksen suureen ahdistukseen, jos eivät tee parannusta ja luovu hänen teoistansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 23, 'ja hänen lapsensa minä tappamalla tapan, ja kaikki seurakunnat saavat tuntea, että minä olen se, joka tutkin munaskuut ja sydämet; ja minä annan teille kullekin tekojenne mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 24, 'Mutta teille muille Tyatirassa oleville, kaikille, joilla ei ole tätä oppia, teille, jotka ette ole tulleet tuntemaan, niinkuin ne sanovat, saatanan syvyyksiä, minä sanon: en minä pane teidän päällenne muuta kuormaa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 25, 'pitäkää vain, mitä teillä on, siihen asti kuin minä tulen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 26, 'Ja joka voittaa ja loppuun asti ottaa minun teoistani vaarin, sille minä annan vallan hallita pakanoita,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 27, 'ja hän on kaitseva heitä rautaisella valtikalla, niinkuin saviastiat heidät särjetään-niinkuin minäkin sen vallan Isältäni sain-');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 28, 'ja minä annan hänelle kointähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 2, 29, 'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 1, '\"Ja Sardeen seurakunnan enkelille kirjoita: \'Näin sanoo hän, jolla on ne Jumalan seitsemän henkeä ja ne seitsemän tähteä: Minä tiedän sinun tekosi: sinulla on se nimi, että elät, mutta sinä olet kuollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 2, 'Heräjä valvomaan ja vahvista jäljellejääneitä, niitä, jotka ovat olleet kuolemaisillaan; sillä minä en ole havainnut sinun tekojasi täydellisiksi Jumalani edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 3, 'Muista siis, mitä olet saanut ja kuullut, ja ota siitä vaari ja tee parannus. Jos et valvo, niin minä tulen kuin varas, etkä sinä tiedä, millä hetkellä minä sinun päällesi tulen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 4, 'Kuitenkin on sinulla Sardeessa muutamia harvoja nimiä, jotka eivät ole tahranneet vaatteitaan, ja he saavat käyskennellä minun kanssani valkeissa vaatteissa, sillä he ovat siihen arvolliset.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 5, 'Joka voittaa, se näin puetaan valkeihin vaatteisiin, enkä minä pyyhi pois hänen nimeänsä elämän kirjasta, ja minä olen tunnustava hänen nimensä Isäni edessä ja hänen enkeliensä edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 6, 'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 7, 'Ja Filadelfian seurakunnan enkelille kirjoita: \'Näin sanoo Pyhä, Totinen, jolla on Daavidin avain, hän, joka avaa, eikä kukaan sulje, ja joka sulkee, eikä kukaan avaa:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 8, 'Minä tiedän sinun tekosi. Katso, minä olen avannut sinun eteesi oven, eikä kukaan voi sitä sulkea; sillä tosin on sinun voimasi vähäinen, mutta sinä olet ottanut vaarin minun sanastani etkä ole minun nimeäni kieltänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 9, 'Katso, minä annan sinulle saatanan synagoogasta niitä, jotka sanovat olevansa juutalaisia, eivätkä ole, vaan valhettelevat; katso, minä olen saattava heidät siihen, että he tulevat ja kumartuvat sinun jalkojesi eteen ja ymmärtävät, että minä sinua rakastan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 10, 'Koska sinä olet ottanut minun kärsivällisyyteni sanasta vaarin, niin minä myös otan sinusta vaarin ja pelastan sinut koetuksen hetkestä, joka on tuleva yli koko maanpiirin koettelemaan niitä, jotka maan päällä asuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 11, 'Minä tulen pian; pidä, mitä sinulla on, ettei kukaan ottaisi sinun kruunuasi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 12, 'Joka voittaa, sen minä teen pylvääksi Jumalani temppeliin, eikä hän koskaan enää lähde sieltä ulos, ja minä kirjoitan häneen Jumalani nimen ja Jumalani kaupungin nimen, sen uuden Jerusalemin, joka laskeutuu alas taivaasta minun Jumalani tyköä, ja oman uuden nimeni.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 13, 'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo.\'');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 14, 'Ja Laodikean seurakunnan enkelille kirjoita: \'Näin sanoo Amen, se uskollinen ja totinen todistaja, Jumalan luomakunnan alku:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 15, 'Minä tiedän sinun tekosi: sinä et ole kylmä etkä palava; oi, jospa olisit kylmä tai palava!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 16, 'Mutta nyt, koska olet penseä, etkä ole palava etkä kylmä, olen minä oksentava sinut suustani ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 17, 'Sillä sinä sanot: Minä olen rikas, minä olen rikastunut enkä mitään tarvitse; etkä tiedä, että juuri sinä olet viheliäinen ja kurja ja köyhä ja sokea ja alaston.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 18, 'Minä neuvon sinua ostamaan minulta kultaa, tulessa puhdistettua, että rikastuisit, ja valkeat vaatteet, että niihin pukeutuisit eikä alastomuutesi häpeä näkyisi, ja silmävoidetta voidellaksesi silmäsi, että näkisit.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 19, 'Kaikkia niitä, joita minä pidän rakkaina, minä nuhtelen ja kuritan; ahkeroitse siis ja tee parannus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 20, 'Katso, minä seison ovella ja kolkutan; jos joku kuulee minun ääneni ja avaa oven, niin minä käyn hänen tykönsä sisälle ja aterioitsen hänen kanssaan, ja hän minun kanssani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 21, 'Joka voittaa, sen minä annan istua kanssani valtaistuimellani, niinkuin minäkin olen voittanut ja istunut Isäni kanssa hänen valtaistuimellensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 3, 22, 'Jolla on korva, se kuulkoon, mitä Henki seurakunnille sanoo.\'\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 1, 'Sen jälkeen minä näin, ja katso: taivaassa oli ovi avoinna, ja ensimmäinen ääni, jonka minä olin kuullut ikäänkuin pasunan puhuvan minulle, sanoi: \"Nouse ylös tänne, niin minä näytän sinulle, mitä tämän jälkeen on tapahtuva\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 2, 'Ja kohta minä olin hengessä. Ja katso, taivaassa oli valtaistuin, ja valtaistuimella oli istuja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 3, 'Ja istuja oli näöltänsä jaspis-ja sardionkiven kaltainen; ja valtaistuimen ympärillä oli taivaankaari, näöltänsä smaragdin kaltainen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 4, 'Ja valtaistuimen ympärillä oli kaksikymmentä neljä valtaistuinta, ja niillä valtaistuimilla istui kaksikymmentä neljä vanhinta, puettuina valkeihin vaatteisiin, ja heillä oli päässänsä kultaiset kruunut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 5, 'Ja valtaistuimesta lähti salamoita ja ääniä ja ukkosen jylinää; ja valtaistuimen edessä paloi seitsemän tulisoihtua, jotka ovat ne seitsemän Jumalan henkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 6, 'Ja valtaistuimen edessä oli ikäänkuin lasinen meri, kristallin näköinen; ja valtaistuimen keskellä ja valtaistuimen ympärillä oli neljä olentoa, edestä ja takaa silmiä täynnä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 7, 'Ja ensimmäinen olento oli leijonan näköinen, ja toinen olento nuoren härän näköinen, ja kolmannella olennolla oli ikäänkuin ihmisen kasvot, ja neljäs olento oli lentävän kotkan näköinen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 8, 'Ja niillä neljällä olennolla oli kullakin kuusi siipeä, ja ne olivat yltympäri ja sisältä silmiä täynnä. Ja ne sanoivat lakkaamatta yötä päivää: \"Pyhä, pyhä, pyhä on Herra Jumala, Kaikkivaltias, joka oli ja joka on ja joka tuleva on\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 9, 'Ja niin usein kuin olennot antavat ylistyksen, kunnian ja kiitoksen hänelle, joka valtaistuimella istuu, joka elää aina ja iankaikkisesti,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 10, 'lankeavat ne kaksikymmentä neljä vanhinta hänen eteensä, joka valtaistuimella istuu, ja kumartaen rukoilevat häntä, joka elää aina ja iankaikkisesti, ja heittävät kruununsa valtaistuimen eteen sanoen:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 4, 11, '\"Sinä, meidän Herramme ja meidän Jumalamme, olet arvollinen saamaan ylistyksen ja kunnian ja voiman, sillä sinä olet luonut kaikki, ja sinun tahdostasi ne ovat olemassa ja ovat luodut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 1, 'Ja minä näin valtaistuimella-istuvan oikeassa kädessä kirjakäärön, sisältä ja päältä täyteen kirjoitetun, seitsemällä sinetillä suljetun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 2, 'Ja minä näin väkevän enkelin, joka suurella äänellä kuulutti: \"Kuka on arvollinen avaamaan tämän kirjan ja murtamaan sen sinetit?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 3, 'Eikä kukaan taivaassa eikä maan päällä eikä maan alla voinut avata kirjaa eikä katsoa siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 4, 'Ja minä itkin kovin sitä, ettei ketään havaittu arvolliseksi avaamaan kirjaa eikä katsomaan siihen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 5, 'Ja yksi vanhimmista sanoi minulle: \"Älä itke; katso, jalopeura Juudan sukukunnasta, Daavidin juurivesa, on voittanut, niin että hän voi avata kirjan ja sen seitsemän sinettiä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 6, 'Ja minä näin, että valtaistuimen ja niiden neljän olennon ja vanhinten keskellä seisoi Karitsa, ikäänkuin teurastettu; sillä oli seitsemän sarvea ja seitsemän silmää, jotka ovat ne seitsemän Jumalan henkeä, lähetetyt kaikkeen maailmaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 7, 'Ja se tuli ja otti kirjan valtaistuimella-istuvan oikeasta kädestä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 8, 'Ja kun se oli ottanut kirjan, niin ne neljä olentoa ja kaksikymmentä neljä vanhinta lankesivat Karitsan eteen, ja heillä oli kantele kullakin, ja heillä oli kultaiset maljat täynnä suitsutuksia, jotka ovat pyhien rukoukset,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 9, 'ja he veisasivat uutta virttä, sanoen: \"Sinä olet arvollinen ottamaan kirjan ja avaamaan sen sinetit, sillä sinä olet tullut teurastetuksi ja olet verelläsi ostanut Jumalalle ihmiset kaikista sukukunnista ja kielistä ja kansoista ja kansanheimoista');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 10, 'ja tehnyt heidät meidän Jumalallemme kuningaskunnaksi ja papeiksi, ja he tulevat hallitsemaan maan päällä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 11, 'Ja minä näin, ja minä kuulin monien enkelien äänen valtaistuimen ja olentojen ja vanhinten ympäriltä, ja heidän lukunsa oli kymmenentuhatta kertaa kymmenentuhatta ja tuhat kertaa tuhat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 12, 'ja he sanoivat suurella äänellä: \"Karitsa, joka on teurastettu, on arvollinen saamaan voiman ja rikkauden ja viisauden ja väkevyyden ja kunnian ja kirkkauden ja ylistyksen\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 13, 'Ja kaikkien luotujen, jotka ovat taivaassa ja maan päällä ja maan alla ja meren päällä, ja kaikkien niissä olevain minä kuulin sanovan: \"Hänelle, joka valtaistuimella istuu, ja Karitsalle ylistys ja kunnia ja kirkkaus ja valta aina ja iankaikkisesti!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 5, 14, 'Ja ne neljä olentoa sanoivat: \"Amen\", ja vanhimmat lankesivat kasvoilleen ja kumartaen rukoilivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 1, 'Ja minä näin, kuinka Karitsa avasi yhden niistä seitsemästä sinetistä, ja kuulin yhden niistä neljästä olennosta sanovan niinkuin ukkosen äänellä: \"Tule!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 2, 'Ja minä näin, ja katso: valkea hevonen; ja sen selässä istuvalla oli jousi, ja hänelle annettiin seppele, ja hän lähti voittajana ja voittamaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 3, 'Ja kun Karitsa avasi toisen sinetin, kuulin minä toisen olennon sanovan: \"Tule!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 4, 'Niin lähti toinen hevonen, tulipunainen, ja sen selässä istuvalle annettiin valta ottaa pois rauha maasta, että ihmiset surmaisivat toisiaan; ja hänelle annettiin suuri miekka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 5, 'Ja kun Karitsa avasi kolmannen sinetin, kuulin minä kolmannen olennon sanovan: \"Tule!\" Ja minä näin, ja katso: musta hevonen; ja sen selässä istuvalla oli kädessään vaaka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 6, 'Ja minä kuulin ikäänkuin äänen niiden neljän olennon keskeltä sanovan: \"Koiniks-mitta nisuja yhden denarin, ja kolme koiniksia ohria yhden denarin! Mutta älä turmele öljyä äläkä viiniä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 7, 'Ja kun Karitsa avasi neljännen sinetin, kuulin minä neljännen olennon äänen sanovan: \"Tule!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 8, 'Ja minä näin, ja katso: hallava hevonen; ja sen selässä istuvan nimi oli Kuolema, ja Tuonela seurasi hänen mukanaan, ja heidän valtaansa annettiin neljäs osa maata, annettiin valta tappaa miekalla ja nälällä ja rutolla ja maan petojen kautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 9, 'Ja kun Karitsa avasi viidennen sinetin, näin minä alttarin alla niiden sielut, jotka olivat surmatut Jumalan sanan tähden ja sen todistuksen tähden, joka heillä oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 10, 'Ja he huusivat suurella äänellä sanoen: \"Kuinka kauaksi sinä, pyhä ja totinen Valtias, siirrät tuomiosi ja jätät kostamatta meidän veremme niille, jotka maan päällä asuvat?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 11, 'Ja heille kullekin annettiin pitkä valkoinen vaippa, ja heille sanottiin, että vielä vähän aikaa pysyisivät levollisina, kunnes oli täyttyvä myös heidän kanssapalvelijainsa ja veljiensä luku, joiden tuli joutua tapettaviksi niinkuin hekin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 12, 'Ja minä näin, kuinka Karitsa avasi kuudennen sinetin; ja tuli suuri maanjäristys, ja aurinko meni mustaksi niinkuin karvainen säkkipuku, ja kuu muuttui kokonaan kuin vereksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 13, 'ja taivaan tähdet putosivat maahan, niinkuin viikunapuu varistaa raakaleensa, kun suuri tuuli sitä pudistaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 14, 'ja taivas väistyi pois niinkuin kirja, joka kääritään kokoon, ja kaikki vuoret ja saaret siirtyivät sijoiltansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 15, 'Ja maan kuninkaat ja ylimykset ja sotapäälliköt ja rikkaat ja väkevät ja kaikki orjat ja vapaat kätkeytyivät luoliin ja vuorten rotkoihin');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 16, 'ja sanoivat vuorille ja kallioille: \"Langetkaa meidän päällemme ja kätkekää meidät hänen kasvoiltansa, joka valtaistuimella istuu, ja Karitsan vihalta!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 6, 17, 'Sillä heidän vihansa suuri päivä on tullut, ja kuka voi kestää?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 1, 'Senjälkeen minä näin neljä enkeliä seisovan maan neljällä kulmalla ja pitävän kiinni maan neljää tuulta, ettei mikään tuuli pääsisi puhaltamaan maan päälle eikä meren päälle eikä yhteenkään puuhun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 2, 'Ja minä näin erään muun enkelin kohoavan auringonnoususta, ja hänellä oli elävän Jumalan sinetti, ja hän huusi suurella äänellä niille neljälle enkelille, joille oli annettu valta vahingoittaa maata ja merta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 3, 'ja sanoi: \"Älkää vahingoittako maata älkääkä merta, älkää myös puita, ennenkuin me olemme painaneet sinetin Jumalamme palvelijain otsaan\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 4, 'Ja minä kuulin sinetillä merkittyjen luvun, sata neljäkymmentä neljä tuhatta merkittyä kaikista Israelin lasten sukukunnista:');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 5, 'Juudan sukukunnasta kaksitoista tuhatta merkittyä, Ruubenin sukukunnasta kaksitoista tuhatta, Gaadin sukukunnasta kaksitoista tuhatta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 6, 'Asserin sukukunnasta kaksitoista tuhatta, Naftalin sukukunnasta kaksitoista tuhatta, Manassen sukukunnasta kaksitoista tuhatta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 7, 'Simeonin sukukunnasta kaksitoista tuhatta, Leevin sukukunnasta kaksitoista tuhatta, Isaskarin sukukunnasta kaksitoista tuhatta,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 8, 'Sebulonin sukukunnasta kaksitoista tuhatta, Joosefin sukukunnasta kaksitoista tuhatta, Benjaminin sukukunnasta kaksitoista tuhatta merkittyä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 9, 'Tämän jälkeen minä näin, ja katso, oli suuri joukko, jota ei kukaan voinut lukea, kaikista kansanheimoista ja sukukunnista ja kansoista ja kielistä, ja ne seisoivat valtaistuimen edessä ja Karitsan edessä puettuina pitkiin valkeihin vaatteisiin, ja heillä oli palmut käsissään,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 10, 'ja he huusivat suurella äänellä sanoen: \"Pelastus tulee meidän Jumalaltamme, joka valtaistuimella istuu, ja Karitsalta\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 11, 'Ja kaikki enkelit seisoivat piirissä valtaistuimen ja vanhinten ja neljän olennon ympärillä ja lankesivat kasvoilleen valtaistuimen eteen ja kumartaen rukoilivat Jumalaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 12, 'sanoen: \"Amen! Ylistys ja kirkkaus ja viisaus ja kiitos ja kunnia ja voima ja väkevyys meidän Jumalallemme aina ja iankaikkisesti, amen!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 13, 'Ja yksi vanhimmista puhui minulle ja sanoi: \"Keitä ovat nämä pitkiin valkeihin vaatteisiin puetut, ja mistä he ovat tulleet?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 14, 'Ja minä sanoin hänelle: \"Herrani, sinä tiedät sen\". Ja hän sanoi minulle: \"Nämä ovat ne, jotka siitä suuresta ahdistuksesta tulevat, ja he ovat pesseet vaatteensa ja valkaisseet ne Karitsan veressä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 15, 'Sentähden he ovat Jumalan valtaistuimen edessä ja palvelevat häntä päivät ja yöt hänen temppelissään, ja hän, joka valtaistuimella istuu, on levittävä telttamajansa heidän ylitsensä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 16, 'Ei heidän enää tule nälkä eikä enää jano, eikä aurinko ole sattuva heihin, eikä mikään helle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 7, 17, 'sillä Karitsa, joka on valtaistuimen keskellä, on kaitseva heitä ja johdattava heidät elämän vetten lähteille, ja Jumala on pyyhkivä pois kaikki kyyneleet heidän silmistänsä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 1, 'Ja kun Karitsa avasi seitsemännen sinetin, tuli taivaassa äänettömyys, jota kesti noin puoli hetkeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 2, 'Ja minä näin ne seitsemän enkeliä, jotka seisoivat Jumalan edessä, ja heille annettiin seitsemän pasunaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 3, 'Ja tuli eräs muu enkeli ja asettui alttarin ääreen pitäen kultaista suitsutusastiaa, ja hänelle annettiin paljon suitsukkeita pantavaksi kaikkien pyhien rukouksiin kultaiselle alttarille, joka oli valtaistuimen edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 4, 'Ja suitsukkeiden savu nousi pyhien rukousten kanssa enkelin kädestä Jumalan eteen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 5, 'Ja enkeli otti suitsutusastian ja täytti sen alttarin tulella ja heitti maan päälle; silloin syntyi ukkosenjylinää ja ääniä ja salamoita ja maanjäristystä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 6, 'Ja ne seitsemän enkeliä, joilla oli ne seitsemän pasunaa, hankkiutuivat puhaltamaan pasunoihin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 7, 'Ja ensimmäinen enkeli puhalsi pasunaan; niin tuli rakeita ja tulta, verellä sekoitettuja, ja ne heitettiin maan päälle; ja kolmas osa maata paloi, ja kolmas osa puita paloi, ja kaikki vihanta ruoho paloi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 8, 'Ja toinen enkeli puhalsi pasunaan; niin heitettiin mereen ikäänkuin suuri, tulena palava vuori; ja kolmas osa merta muuttui vereksi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 9, 'ja kolmas osa luoduista, mitä meressä on ja joissa henki on, kuoli, ja kolmas osa laivoista hukkui.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 10, 'Ja kolmas enkeli puhalsi pasunaan; niin putosi taivaasta suuri tähti, palava kuin tulisoihtu, ja se putosi virtoihin, kolmanteen osaan niistä, ja vesilähteisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 11, 'Ja tähden nimi oli Koiruoho. Ja kolmas osa vesistä muuttui koiruohoksi, ja paljon ihmisiä kuoli vedestä, koska se oli karvaaksi käynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 12, 'Ja neljäs enkeli puhalsi pasunaan; niin kolmas osa auringosta ja kolmas osa kuusta ja kolmas osa tähdistä lyötiin vitsauksella, niin että kolmas osa niistä pimeni ja päivä kolmannelta osaltaan oli valoton, ja niin myös yö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 8, 13, 'Ja minä näin, ja minä kuulin kotkan, joka lensi keskitaivaalla, sanovan suurella äänellä: \"Voi, voi, voi maan päällä asuvaisia niiden jäljellä olevain pasunain äänten tähden, joihin kolmen enkelin vielä on määrä puhaltaa!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 1, 'Ja viides enkeli puhalsi pasunaan; niin minä näin tähden, taivaasta maan päälle pudonneen, ja sille annettiin syvyyden kaivon avain;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 2, 'ja se avasi syvyyden kaivon, ja kaivosta nousi savu, niinkuin savu suuresta pätsistä, ja kaivon savu pimitti auringon ja ilman.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 3, 'Ja savusta lähti heinäsirkkoja maan päälle, ja niille annettiin valta, niinkuin maan skorpioneilla on valta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 4, 'ja niille sanottiin, etteivät ne saa vahingoittaa maan ruohoa eikä mitään vihantaa eikä yhtään puuta, vaan ainoastaan niitä ihmisiä, joilla ei ole Jumalan sinettiä otsassaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 5, 'Ja niille annettiin valta vaivata heitä viisi kuukautta, vaan ei tappaa heitä; ja ne vaivasivat, niinkuin vaivaa skorpioni, kun se ihmistä pistää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 6, 'Ja niinä päivinä ihmiset etsivät kuolemaa, eivätkä sitä löydä; he haluavat kuolla, mutta kuolema pakenee heitä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 7, 'Ja heinäsirkat olivat sotaan varustettujen hevosten kaltaiset, ja niillä oli päässään ikäänkuin seppeleet, kullan näköiset, ja niiden kasvot olivat ikäänkuin ihmisten kasvot;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 8, 'ja niillä oli hiukset niinkuin naisten hiukset, ja niiden hampaat olivat niinkuin leijonain hampaat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 9, 'Ja niillä oli haarniskat ikäänkuin rautahaarniskat, ja niiden siipien kohina oli kuin sotavaunujen ryske monien hevosten kiitäessä taisteluun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 10, 'Ja niillä oli pyrstöt niinkuin skorpioneilla ja pistimet, ja pyrstöissänsä niillä oli voima vahingoittaa ihmisiä viisi kuukautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 11, 'Niillä oli kuninkaanaan syvyyden enkeli, jonka nimi hebreaksi on Abaddon ja kreikaksi Apollyon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 12, 'Ensimmäinen \"voi!\" on mennyt; katso, tulee vielä kaksi \"voi!\" -huutoa tämän jälkeen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 13, 'Ja kuudes enkeli puhalsi pasunaan; niin minä kuulin äänen tulevan kultaisen alttarin neljästä sarvesta, Jumalan edestä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 14, 'ja se sanoi kuudennelle enkelille, jolla oli pasuna: \"Päästä ne neljä enkeliä, jotka ovat sidottuina suuren Eufrat-virran varrella\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 15, 'Silloin päästettiin ne neljä enkeliä, jotka hetkelleen, päivälleen, kuukaudelleen ja vuodelleen olivat valmiina tappamaan kolmannen osan ihmisistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 16, 'Ja ratsuväen joukkojen luku oli kaksikymmentä tuhatta kertaa kymmenen tuhatta; minä kuulin niiden luvun.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 17, 'Ja tämänkaltaisilta minusta näyttivät hevoset ja niiden selässä istujat näyssä: ratsastajilla oli tulipunaiset ja tummansinervät ja tulikivenkeltaiset haarniskat; ja hevosten päät olivat kuin leijonain päät, ja niiden suusta lähti tuli ja savu ja tulikivi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 18, 'Näistä kolmesta vitsauksesta sai kolmas osa ihmisiä surmansa: tulesta ja savusta ja tulikivestä, jotka lähtivät niiden suusta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 19, 'Sillä hevosten voima oli niiden suussa ja niiden hännässä; niiden hännät näet olivat käärmeitten kaltaiset, ja niissä oli päät, joilla ne vahingoittivat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 20, 'Ja jäljelle jääneet ihmiset, ne, joita ei tapettu näillä vitsauksilla, eivät tehneet parannusta kättensä teoista, niin että olisivat lakanneet kumartamasta riivaajia ja kultaisia ja hopeaisia ja vaskisia ja kivisiä ja puisia epäjumalankuvia, jotka eivät voi nähdä eikä kuulla eikä kävellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 9, 21, 'He eivät tehneet parannusta murhistaan eikä velhouksistaan eikä haureudestaan eikä varkauksistaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 1, 'Ja minä näin erään toisen, väkevän enkelin tulevan alas taivaasta; hänen verhonaan oli pilvi, ja taivaankaari oli hänen päänsä päällä, ja hänen kasvonsa olivat niinkuin aurinko, ja hänen jalkansa niinkuin tulipatsaat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 2, 'ja hänellä oli kädessään avattu kirjanen. Ja hän laski oikean jalkansa meren päälle ja vasemman maan päälle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 3, 'ja huusi suurella äänellä, niinkuin leijona ärjyy; ja kun hän huusi, antoivat ne seitsemän ukkosen jylinää ääntensä puhua.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 4, 'Ja kun ne seitsemän ukkosenjylinää olivat puhuneet, yritin minä kirjoittaa, mutta minä kuulin äänen taivaasta sanovan: \"Pane sinetin taakse, mitä ne seitsemän ukkosenjylinää puhuivat, äläkä sitä kirjoita\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 5, 'Ja enkeli, jonka minä näin seisovan meren päällä ja maan päällä, kohotti oikean kätensä taivasta kohti');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 6, 'ja vannoi hänen kauttansa, joka elää aina ja iankaikkisesti, hänen, joka on luonut taivaan ja mitä siinä on, ja maan ja mitä siinä on, ja meren ja mitä siinä on, ettei enää ole oleva aikaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 7, 'vaan että niinä päivinä, jolloin seitsemännen enkelin ääni kuuluu hänen puhaltaessaan pasunaan, Jumalan salaisuus käy täytäntöön sen hyvän sanoman mukaan, jonka hän on ilmoittanut palvelijoillensa profeetoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 8, 'Ja sen äänen, jonka minä olin kuullut taivaasta, kuulin taas puhuvan minulle ja sanovan: \"Mene ja ota tuo avattu kirjakäärö, joka on meren ja maan päällä seisovan enkelin kädessä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 9, 'Ja minä menin enkelin tykö ja pyysin, että hän antaisi minulle sen kirjasen. Ja hän sanoi minulle: \"Ota ja syö se; se on karvasteleva vatsassasi, mutta suussasi se on oleva makea kuin hunaja\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 10, 'Niin minä otin kirjasen enkelin kädestä ja söin sen; se oli minun suussani makea kuin hunaja; mutta sen syötyäni minun vatsaani karvasteli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 10, 11, 'Ja minulle sanottiin: \"Sinun tulee taas profetoida monista kansoista ja kansanheimoista ja kielistä ja kuninkaista\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 1, 'Ja minulle annettiin sauvan kaltainen ruoko ja sanottiin: \"Nouse ja mittaa Jumalan temppeli ja alttari ja ne, jotka siinä kumartaen rukoilevat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 2, 'Mutta temppelin ulkopuolella oleva esikartano erota pois, äläkä sitä mittaa, sillä se on annettu pakanakansoille; ja he tallaavat pyhää kaupunkia neljäkymmentäkaksi kuukautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 3, 'Ja minä annan kahdelle todistajalleni toimeksi säkkipukuihin puettuina profetoida tuhannen kahdensadan kuudenkymmenen päivän ajan.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 4, 'Nämä ovat ne kaksi öljypuuta ja ne kaksi lampunjalkaa, jotka seisovat maan Herran edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 5, 'Ja jos joku tahtoo heitä vahingoittaa, lähtee tuli heidän suustaan ja kuluttaa heidän vihollisensa; ja jos joku tahtoo heitä vahingoittaa, on hän saava surmansa sillä tavalla.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 6, 'Heillä on valta sulkea taivas, niin ettei sadetta tule heidän profetoimisensa päivinä, ja heillä on valta muuttaa vedet vereksi ja lyödä maata kaikkinaisilla vitsauksilla, niin usein kuin tahtovat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 7, 'Ja kun he ovat lopettaneet todistamisensa, on peto, se, joka nousee syvyydestä, käyvä sotaa heitä vastaan ja voittava heidät ja tappava heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 8, 'Ja heidän ruumiinsa viruvat sen suuren kaupungin kadulla, jota hengellisesti puhuen kutsutaan Sodomaksi ja Egyptiksi ja jossa myös heidän Herransa ristiinnaulittiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 9, 'Ja ihmiset eri kansoista ja sukukunnista ja kielistä ja kansanheimoista näkevät heidän ruumiinsa kolme ja puoli päivää, eivätkä salli, että heidän ruumiinsa pannaan hautaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 10, 'Ja ne, jotka maan päällä asuvat, iloitsevat heidän kohtalostaan ja riemuitsevat ja lähettävät lahjoja toisilleen; sillä nämä kaksi profeettaa olivat vaivanneet niitä, jotka maan päällä asuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 11, 'Ja niiden kolmen ja puolen päivän kuluttua meni heihin Jumalasta elämän henki, ja he nousivat jaloilleen, ja suuri pelko valtasi ne, jotka näkivät heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 12, 'Ja he kuulivat suuren äänen taivaasta sanovan heille: \"Nouskaa tänne!\" Niin he nousivat taivaaseen pilvessä, ja heidän vihollisensa näkivät heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 13, 'Ja sillä hetkellä tapahtui suuri maanjäristys, ja kymmenes osa kaupunkia kukistui, ja maanjäristyksessä sai surmansa seitsemäntuhatta henkeä, ja muut peljästyivät ja antoivat taivaan Jumalalle kunnian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 14, 'Toinen \"voi!\" on mennyt; katso, kolmas \"voi!\" tulee pian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 15, 'Ja seitsemäs enkeli puhalsi pasunaan; niin kuului taivaassa suuria ääniä, jotka sanoivat: \"Maailman kuninkuus on tullut meidän Herrallemme ja hänen Voidellullensa, ja hän on hallitseva aina ja iankaikkisesti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 16, 'Ja ne kaksikymmentä neljä vanhinta, jotka istuivat valtaistuimillaan Jumalan edessä, lankesivat kasvoillensa ja kumartaen rukoilivat Jumalaa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 17, 'sanoen: \"Me kiitämme sinua, Herra Jumala, Kaikkivaltias, joka olet ja joka olit, siitä, että olet ottanut suuren voimasi ja ottanut hallituksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 18, 'Ja pakanakansat ovat vihastuneet, mutta sinun vihasi on tullut, ja tullut on aika tuomita kuolleet ja maksaa palkka sinun palvelijoillesi profeetoille ja pyhille ja niille, jotka sinun nimeäsi pelkäävät, pienille ja suurille, ja turmella ne, jotka maan turmelevat.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 11, 19, 'Ja Jumalan temppeli taivaassa aukeni, ja hänen liittonsa arkki näkyi hänen temppelissään, ja tuli salamoita ja ääniä ja ukkosenjylinää ja maanjäristystä ja suuria rakeita.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 1, 'Ja näkyi suuri merkki taivaassa: vaimo, vaatetettu auringolla, ja kuu hänen jalkojensa alla, ja hänen päässään seppeleenä kaksitoista tähteä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 2, 'Hän oli raskaana ja huusi synnytyskivuissaan, ja hänen oli vaikea synnyttää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 3, 'Ja näkyi toinen merkki taivaassa, ja katso: suuri, tulipunainen lohikäärme, jolla oli seitsemän päätä ja kymmenen sarvea, ja sen päissä seitsemän kruunua;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 4, 'ja sen pyrstö pyyhkäisi pois kolmannen osan taivaan tähtiä ja heitti ne maan päälle. Ja lohikäärme seisoi synnyttämäisillään olevan vaimon edessä nielläkseen hänen lapsensa, kun hän sen synnyttäisi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 5, 'Ja hän synnytti poikalapsen, joka on kaitseva kaikkia pakanakansoja rautaisella valtikalla; ja hänen lapsensa temmattiin Jumalan tykö ja hänen valtaistuimensa tykö.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 6, 'Ja vaimo pakeni erämaahan, jossa hänellä oli Jumalan valmistama paikka, että häntä elätettäisiin siellä tuhat kaksisataa kuusikymmentä päivää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 7, 'Ja syttyi sota taivaassa: Miikael ja hänen enkelinsä sotivat lohikäärmettä vastaan; ja lohikäärme ja hänen enkelinsä sotivat,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 8, 'mutta eivät voittaneet, eikä heillä enää ollut sijaa taivaassa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 9, 'Ja suuri lohikäärme, se vanha käärme, jota perkeleeksi ja saatanaksi kutsutaan, koko maanpiirin villitsijä, heitettiin maan päälle, ja hänen enkelinsä heitettiin hänen kanssansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 10, 'Ja minä kuulin suuren äänen taivaassa sanovan: \"Nyt on tullut pelastus ja voima ja meidän Jumalamme valtakunta ja hänen Voideltunsa valta, sillä meidän veljiemme syyttäjä, joka yöt ja päivät syytti heitä meidän Jumalamme edessä, on heitetty ulos.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 11, 'Ja he ovat voittaneet hänet Karitsan veren kautta ja todistuksensa sanan kautta, eivätkä ole henkeänsä rakastaneet, vaan olleet alttiit kuolemaan asti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 12, 'Sentähden riemuitkaa, taivaat, ja te, jotka niissä asutte! Voi maata ja merta, sillä perkele on astunut alas teidän luoksenne pitäen suurta vihaa, koska hän tietää, että hänellä on vähän aikaa!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 13, 'Ja kun lohikäärme näki olevansa heitetty maan päälle, ajoi hän takaa sitä vaimoa, joka oli poikalapsen synnyttänyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 14, 'Mutta vaimolle annettiin sen suuren kotkan kaksi siipeä hänen lentääksensä erämaahan sille paikalleen, jossa häntä elätetään aika ja kaksi aikaa ja puoli aikaa poissa käärmeen näkyvistä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 15, 'Ja käärme syöksi kidastansa vaimon jälkeen vettä niinkuin virran, saattaakseen hänet virran vietäväksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 16, 'Mutta maa auttoi vaimoa: maa avasi suunsa ja nieli virran, jonka lohikäärme oli syössyt kidastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 17, 'Ja lohikäärme vihastui vaimoon ja lähti käymään sotaa muita hänen jälkeläisiänsä vastaan, jotka pitävät Jumalan käskyt ja joilla on Jeesuksen todistus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 12, 18, '');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 1, '{12:18} Ja se asettui seisomaan meren hiekalle. {13:1} Ja minä näin pedon nousevan merestä; sillä oli kymmenen sarvea ja seitsemän päätä, ja sarvissansa kymmenen kruunua, ja sen päihin oli kirjoitettu pilkkaavia nimiä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 2, 'Ja peto, jonka minä näin, oli leopardin näköinen, ja sen jalat ikäänkuin karhun, ja sen kita niinkuin leijonan kita. Ja lohikäärme antoi sille voimansa ja valtaistuimensa ja suuren vallan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 3, 'Ja minä näin yhden sen päistä olevan ikäänkuin kuoliaaksi haavoitetun, mutta sen kuolinhaava parantui. Ja koko maa seurasi ihmetellen petoa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 4, 'Ja he kumarsivat lohikäärmettä, koska se oli antanut sellaisen vallan pedolle, ja kumarsivat petoa sanoen: \"Kuka on pedon vertainen, ja kuka voi sotia sitä vastaan?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 5, 'Ja sille annettiin suu puhua suuria sanoja ja pilkkapuheita, ja sille annettiin valta tehdä sitä neljäkymmentä kaksi kuukautta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 6, 'Ja se avasi suunsa Jumalaa pilkkaamaan, pilkatakseen hänen nimeänsä ja hänen majaansa, niitä, jotka taivaassa asuvat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 7, 'Ja sille annettiin valta käydä sotaa pyhiä vastaan ja voittaa heidät, ja sen valtaan annettiin kaikki sukukunnat ja kansat ja kielet ja kansanheimot.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 8, 'Ja kaikki maan päällä asuvaiset kumartavat sitä, jokainen, jonka nimi ei ole kirjoitettu teurastetun Karitsan elämänkirjaan, hamasta maailman perustamisesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 9, 'Jos kenellä on korva, hän kuulkoon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 10, 'Jos kuka vankeuteen vie, niin hän itse vankeuteen joutuu; jos kuka miekalla tappaa, hänet pitää miekalla tapettaman. Tässä on pyhien kärsivällisyys ja usko.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 11, 'Ja minä näin toisen pedon nousevan maasta, ja sillä oli kaksi sarvea niinkuin karitsan sarvet, ja se puhui niinkuin lohikäärme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 12, 'Ja se käyttää kaikkea ensimmäisen pedon valtaa sen nähden ja saattaa maan ja siinä asuvaiset kumartamaan ensimmäistä petoa, sitä, jonka kuolinhaava parani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 13, 'Ja se tekee suuria ihmeitä, niin että saa tulenkin taivaasta lankeamaan maahan ihmisten nähden.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 14, 'Ja se villitsee maan päällä asuvaiset niillä ihmeillä, joita sen sallittiin tehdä pedon nähden; se yllyttää maan päällä asuvaiset tekemään sen pedon kuvan, jossa oli miekanhaava ja joka virkosi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 15, 'Ja sille annettiin valta antaa pedon kuvalle henki, että pedon kuva puhuisikin ja saisi aikaan, että ketkä vain eivät kumartaneet pedon kuvaa, ne tapettaisiin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 16, 'Ja se saa kaikki, pienet ja suuret, sekä rikkaat että köyhät, sekä vapaat että orjat, panemaan merkin oikeaan käteensä tai otsaansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 17, 'ettei kukaan muu voisi ostaa eikä myydä kuin se, jossa on merkki: pedon nimi tai sen nimen luku.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 13, 18, 'Tässä on viisaus. Jolla ymmärrys on, se laskekoon pedon luvun; sillä se on ihmisen luku. Ja sen luku on kuusisataa kuusikymmentä kuusi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 1, 'Ja minä näin, ja katso, Karitsa seisoi Siionin vuorella, ja hänen kanssaan sata neljäkymmentä neljä tuhatta, joiden otsaan oli kirjoitettu hänen nimensä ja hänen Isänsä nimi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 2, 'Ja minä kuulin äänen taivaasta ikäänkuin paljojen vetten pauhinan ja ikäänkuin suuren ukkosenjylinän, ja ääni, jonka minä kuulin, oli ikäänkuin kanteleensoittajain, kun he kanteleitaan soittavat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 3, 'Ja he veisasivat uutta virttä valtaistuimen edessä ja neljän olennon ja vanhinten edessä; eikä kukaan voinut oppia sitä virttä, paitsi ne sata neljäkymmentä neljä tuhatta, jotka ovat ostetut maasta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 4, 'Nämä ovat ne, jotka eivät ole saastuttaneet itseään naisten kanssa; sillä he ovat niinkuin neitsyet. Nämä ovat ne, jotka seuraavat Karitsaa, mihin ikinä hän menee. Nämä ovat ostetut ihmisistä esikoiseksi Jumalalle ja Karitsalle,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 5, 'eikä heidän suussaan ole valhetta havaittu; he ovat tahrattomat.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 6, 'Ja minä näin lentävän keskitaivaalla erään toisen enkelin, jolla oli iankaikkinen evankeliumi julistettavana maan päällä asuvaisille, kaikille kansanheimoille ja sukukunnille ja kielille ja kansoille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 7, 'Ja hän sanoi suurella äänellä: \"Peljätkää Jumalaa ja antakaa hänelle kunnia, sillä hänen tuomionsa hetki on tullut, ja kumartakaa häntä, joka on tehnyt taivaan ja maan ja meren ja vetten lähteet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 8, 'Ja seurasi vielä toinen enkeli, joka sanoi: \"Kukistunut, kukistunut on se suuri Babylon, joka haureutensa vihan viinillä on juottanut kaikki kansat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 9, 'Ja heitä seurasi vielä kolmas enkeli, joka sanoi suurella äänellä: \"Jos joku kumartaa petoa ja sen kuvaa ja ottaa sen merkin otsaansa tai käteensä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 10, 'niin hänkin on juova Jumalan vihan viiniä, joka sekoittamattomana on kaadettu hänen vihansa maljaan, ja häntä pitää tulella ja tulikivellä vaivattaman pyhien enkelien edessä ja Karitsan edessä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 11, 'Ja heidän vaivansa savu on nouseva aina ja iankaikkisesti, eikä heillä ole lepoa päivällä eikä yöllä, heillä, jotka petoa ja sen kuvaa kumartavat, eikä kenelläkään, joka ottaa sen nimen merkin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 12, 'Tässä on pyhien kärsivällisyys, niiden, jotka pitävät Jumalan käskyt ja Jeesuksen uskon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 13, 'Ja minä kuulin äänen taivaasta sanovan: \"Kirjoita: Autuaat ovat ne kuolleet, jotka Herrassa kuolevat tästedes. Totisesti-sanoo Henki-he saavat levätä vaivoistansa, sillä heidän tekonsa seuraavat heitä.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 14, 'Ja minä näin, ja katso: valkoinen pilvi, ja pilvellä istui Ihmisen Pojan muotoinen, päässänsä kultainen kruunu ja kädessänsä terävä sirppi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 15, 'Ja temppelistä tuli eräs toinen enkeli huutaen suurella äänellä pilvellä istuvalle: \"Lähetä sirppisi ja leikkaa, sillä leikkuuaika on tullut, ja maan elo on kypsynyt\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 16, 'Ja pilvellä istuva heitti sirppinsä maan päälle, ja maa tuli leikatuksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 17, 'Ja taivaan temppelistä lähti eräs toinen enkeli, ja hänelläkin oli terävä sirppi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 18, 'Ja alttarista lähti vielä toinen enkeli, jolla oli tuli vallassaan, ja hän huusi suurella äänellä sille, jolla oli se terävä sirppi, sanoen: \"Lähetä terävä sirppisi ja korjaa tertut maan viinipuusta, sillä sen rypäleet ovat kypsyneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 19, 'Ja enkeli heitti sirppinsä alas maahan ja korjasi maan viinipuun hedelmät ja heitti ne Jumalan vihan suureen kuurnaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 14, 20, 'Ja kuurna poljettiin kaupungin ulkopuolella, ja kuurnasta kuohui veri hevosten kuolaimiin asti, tuhannen kuudensadan vakomitan päähän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 1, 'Ja minä näin toisen tunnusmerkin taivaassa, suuren ja ihmeellisen: seitsemän enkeliä, joilla oli seitsemän viimeistä vitsausta, sillä niissä Jumalan viha täyttyy.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 2, 'Ja minä näin ikäänkuin lasisen meren, tulella sekoitetun, ja niiden, jotka olivat saaneet voiton pedosta ja sen kuvasta ja sen nimen luvusta, seisovan sillä lasisella merellä, ja heillä oli Jumalan kanteleet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 3, 'Ja he veisasivat Mooseksen, Jumalan palvelijan, virttä ja Karitsan virttä, sanoen: \"Suuret ja ihmeelliset ovat sinun tekosi, Herra Jumala, Kaikkivaltias; vanhurskaat ja totiset ovat sinun tiesi, sinä kansojen kuningas.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 4, 'Kuka ei pelkäisi, Herra, ja ylistäisi sinun nimeäsi? Sillä sinä yksin olet Pyhä; sillä kaikki kansat tulevat ja kumartavat sinua, koska sinun vanhurskaat tuomiosi ovat julki tulleet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 5, 'Ja sen jälkeen minä näin: todistuksen majan temppeli taivaassa avattiin;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 6, 'ja ne seitsemän enkeliä, joilla oli ne seitsemän vitsausta, lähtivät temppelistä, puettuina puhtaisiin, hohtaviin pellavavaatteisiin ja rinnoilta vyötettyinä kultaisilla vöillä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 7, 'Ja yksi niistä neljästä olennosta antoi niille seitsemälle enkelille seitsemän kultaista maljaa, täynnä Jumalan vihaa, hänen, joka elää aina ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 15, 8, 'Ja temppeli tuli savua täyteen Jumalan kirkkaudesta ja hänen voimastansa, eikä kukaan voinut mennä sisälle temppeliin, ennenkuin niiden seitsemän enkelin seitsemän vitsausta oli käynyt täytäntöön.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 1, 'Ja minä kuulin suuren äänen temppelistä sanovan niille seitsemälle enkelille: \"Menkää ja vuodattakaa ne seitsemän Jumalan vihan maljaa maan päälle\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 2, 'Ja ensimmäinen lähti ja vuodatti maljansa maan päälle; ja tuli pahoja ja ilkeitä paiseita niihin ihmisiin, joissa oli pedon merkki ja jotka kumarsivat sen kuvaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 3, 'Ja toinen enkeli vuodatti maljansa mereen, ja se tuli vereksi, ikäänkuin kuolleen vereksi, ja jokainen elävä olento kuoli, mitä meressä oli.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 4, 'Ja kolmas enkeli vuodatti maljansa jokiin ja vesilähteisiin, ja ne tulivat vereksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 5, 'Ja minä kuulin vetten enkelin sanovan: \"Vanhurskas olet sinä, joka olet ja joka olit, sinä Pyhä, kun näin olet tuominnut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 6, 'Sillä pyhien ja profeettain verta he ovat vuodattaneet, ja verta sinä olet antanut heille juoda; sen he ovat ansainneet.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 7, 'Ja minä kuulin alttarin sanovan: \"Totisesti, Herra Jumala, Kaikkivaltias, totiset ja vanhurskaat ovat sinun tuomiosi\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 8, 'Ja neljäs enkeli vuodatti maljansa aurinkoon, ja sille annettiin valta paahtaa ihmisiä tulella.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 9, 'Ja ihmiset paahtuivat kovassa helteessä ja pilkkasivat Jumalan nimeä, hänen, jolla on vallassaan nämä vitsaukset; mutta he eivät tehneet parannusta, niin että olisivat antaneet hänelle kunnian.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 10, 'Ja viides enkeli vuodatti maljansa pedon valtaistuimelle, ja sen valtakunta pimeni; ja he pureskelivat kielensä rikki tuskissansa');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 11, 'ja pilkkasivat taivaan Jumalaa tuskiensa ja paiseittensa tähden, mutta eivät tehneet parannusta teoistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 12, 'Ja kuudes enkeli vuodatti maljansa suureen Eufrat-virtaan, ja sen vesi kuivui, että tie valmistuisi auringon noususta tuleville kuninkaille.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 13, 'Ja minä näin lohikäärmeen suusta ja pedon suusta ja väärän profeetan suusta lähtevän kolme saastaista henkeä, sammakon muotoista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 14, 'Sillä ne ovat riivaajain henkiä, jotka tekevät ihmeitä; ne lähtevät koko maanpiirin kuningasten luo kokoamaan heidät sotaan Jumalan, Kaikkivaltiaan, suurena päivänä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 15, '-Katso, minä tulen niinkuin varas; autuas se, joka valvoo ja pitää vaatteistansa vaarin, ettei hän kulkisi alastomana eikä hänen häpeätänsä nähtäisi! -');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 16, 'Ja ne kokosivat heidät siihen paikkaan, jonka nimi hebreaksi on Harmagedon.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 17, 'Ja seitsemäs enkeli vuodatti maljansa ilmaan, ja temppelistä, valtaistuimelta, lähti suuri ääni, joka sanoi: \"Se on tapahtunut\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 18, 'Ja tuli salamoita ja ääniä ja ukkosenjylinää; ja tuli suuri maanjäristys, niin ankara ja suuri maanjäristys, ettei sen vertaista ole ollut siitä asti, kuin ihmisiä on ollut maan päällä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 19, 'Ja se suuri kaupunki meni kolmeen osaan, ja kansojen kaupungit kukistuivat. Ja se suuri Babylon tuli muistetuksi Jumalan edessä, niin että hän antoi sille vihansa kiivauden viinimaljan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 20, 'Ja kaikki saaret pakenivat, eikä vuoria enää ollut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 16, 21, 'Ja suuria rakeita, leiviskän painoisia, satoi taivaasta ihmisten päälle; ja ihmiset pilkkasivat Jumalaa raesateen vitsauksen tähden, sillä se vitsaus oli ylen suuri.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 1, 'Ja tuli yksi niistä seitsemästä enkelistä, joilla oli ne seitsemän maljaa, ja puhui minulle sanoen: \"Tule, minä näytän sinulle sen suuren porton tuomion, joka istuu paljojen vetten päällä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 2, 'hänen, jonka kanssa maan kuninkaat ovat haureutta harjoittaneet ja jonka haureuden viinistä maan asukkaat ovat juopuneet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 3, 'Ja hän vei minut hengessä erämaahan. Siellä minä näin naisen istuvan helakanpunaisen pedon selässä; peto oli täynnä pilkkaavia nimiä, ja sillä oli seitsemän päätä ja kymmenen sarvea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 4, 'Ja nainen oli puettu purppuraan ja helakanpunaan ja koristettu kullalla ja jalokivillä ja helmillä ja piti kädessään kultaista maljaa, joka oli täynnä kauhistuksia ja hänen haureutensa riettauksia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 5, 'Ja hänen otsaansa oli kirjoitettu nimi, salaisuus: \"Suuri Babylon, maan porttojen ja kauhistuksien äiti\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 6, 'Ja minä näin sen naisen olevan juovuksissa pyhien verestä ja Jeesuksen todistajain verestä; ja nähdessäni hänet minä suuresti ihmettelin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 7, 'Ja enkeli sanoi minulle: \"Miksi ihmettelet? Minä sanon sinulle tuon naisen salaisuuden ja tuon pedon salaisuuden, joka häntä kantaa ja jolla on seitsemän päätä ja kymmenen sarvea.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 8, 'Peto, jonka sinä näit, on ollut, eikä sitä enää ole, mutta se on nouseva syvyydestä ja menevä kadotukseen; ja ne maan päällä asuvaiset, joiden nimet eivät ole kirjoitetut elämän kirjaan, hamasta maailman perustamisesta, ihmettelevät, kun he näkevät pedon, että se on ollut eikä sitä enää ole, mutta se on tuleva.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 9, 'Tässä on ymmärrys, jossa viisaus on: Ne seitsemän päätä ovat seitsemän vuorta, joiden päällä nainen istuu; ne ovat myös seitsemän kuningasta;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 10, 'heistä on viisi kaatunut, yksi on, viimeinen ei ole vielä tullut, ja kun hän tulee, pitää hänen vähän aikaa pysymän.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 11, 'Ja peto, joka on ollut ja jota ei enää ole, on itse kahdeksas, ja on yksi noista seitsemästä, ja menee kadotukseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 12, 'Ja ne kymmenen sarvea, jotka sinä näit, ovat kymmenen kuningasta, jotka eivät vielä ole saaneet kuninkuutta, mutta saavat vallan niinkuin kuninkaat yhdeksi hetkeksi pedon kanssa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 13, 'Näillä on yksi ja sama mieli, ja he antavat voimansa ja valtansa pedolle.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 14, 'He sotivat Karitsaa vastaan, mutta Karitsa on voittava heidät, sillä hän on herrain Herra ja kuningasten Kuningas; ja kutsutut ja valitut ja uskolliset voittavat hänen kanssansa.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 15, 'Ja hän sanoi minulle: \"Vedet, jotka sinä näit, tuolla, missä portto istuu, ovat kansoja ja väkijoukkoja ja kansanheimoja ja kieliä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 16, 'Ja ne kymmenen sarvea, jotka sinä näit, ja peto, ne vihaavat porttoa ja riisuvat hänet paljaaksi ja alastomaksi ja syövät hänen lihansa ja polttavat hänet tulessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 17, 'Sillä Jumala on pannut heidän sydämeensä, että he täyttävät hänen aivoituksensa, yksimielisesti, ja antavat kuninkuutensa pedolle, kunnes Jumalan sanat täyttyvät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 17, 18, 'Ja nainen, jonka sinä näit, on se suuri kaupunki, jolla on maan kuninkaitten kuninkuus.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 1, 'Sen jälkeen minä näin tulevan taivaasta alas erään toisen enkelin, jolla oli suuri valta, ja maa valkeni hänen kirkkaudestaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 2, 'Ja hän huusi voimallisella äänellä sanoen: \"Kukistunut, kukistunut on suuri Babylon ja tullut riivaajain asuinpaikaksi ja kaikkien saastaisten henkien tyyssijaksi ja kaikkien saastaisten ja vihattavain lintujen tyyssijaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 3, 'Sillä hänen haureutensa vihan viiniä ovat kaikki kansat juoneet, ja maan kuninkaat ovat haureutta harjoittaneet hänen kanssansa, ja maan kauppiaat ovat rikastuneet hänen hekumansa runsaudesta.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 4, 'Ja minä kuulin toisen äänen taivaasta sanovan: \"Lähtekää siitä ulos, te minun kansani, ettette tulisi hänen synteihinsä osallisiksi ja saisi tekin kärsiä hänen vitsauksistansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 5, 'Sillä hänen syntinsä ulottuvat taivaaseen asti, ja Jumala on muistanut hänen rikoksensa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 6, 'Kostakaa hänelle sen mukaan, kuin hän on tehnyt, ja antakaa hänelle kaksinkertaisesti hänen teoistansa; siihen maljaan, johon hän on kaatanut, kaatakaa te hänelle kaksin verroin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 7, 'Niin paljon kuin hän on itselleen kunniaa ja hekumaa hankkinut, niin paljon antakaa hänelle vaivaa ja surua. Koska hän sanoo sydämessään: \'Minä istun kuningattarena enkä ole leski enkä ole surua näkevä\',');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 8, 'sentähden hänen vitsauksensa tulevat yhtenä päivänä: kuolema ja suru ja nälkä, ja hän joutuu tulessa poltettavaksi, sillä väkevä on Herra Jumala, joka on hänet tuominnut.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 9, 'Ja maanpiirin kuninkaat, jotka hänen kanssansa ovat haureutta harjoittaneet ja hekumallisesti eläneet, itkevät ja parkuvat häntä, kun näkevät hänen palonsa savun;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 10, 'he seisovat loitolla kauhistuen hänen vaivaansa ja sanovat: \"Voi, voi sinua, Babylon, sinä suuri kaupunki, sinä vahva kaupunki, sillä sinun tuomiosi tuli yhdessä hetkessä!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 11, 'Ja maanpiirin kauppiaat itkevät ja surevat häntä, kun ei kukaan enää osta heidän tavaraansa,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 12, 'kaupaksi tuotua kultaa ja hopeata ja jalokiviä ja helmiä ja pellavakangasta ja purppuraa ja silkkiä ja helakanpunaa ja kaikkinaista hajupuuta ja kaikenlaisia norsunluu-esineitä ja kaikenlaisia kalleimmasta puusta ja vaskesta ja raudasta ja marmorista tehtyjä esineitä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 13, 'ja kanelia ja hiusvoidetta ja suitsuketta ja hajuvoidetta ja suitsutuspihkaa ja viiniä ja öljyä ja lestyjä jauhoja ja viljaa ja karjaa ja lampaita ja hevosia ja vaunuja ja orjia ja ihmissieluja.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 14, 'Ja hedelmät, joita sinun sielusi himoitsi, ovat sinulta menneet, ja kaikki kalleutesi ja komeutesi ovat sinulta hävinneet, eikä niitä enää koskaan löydetä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 15, 'Niiden kauppiaat, ne, jotka rikastuivat tästä kaupungista, seisovat loitolla kauhistuen hänen vaivaansa, itkien ja surren,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 16, 'ja sanovat: \"Voi, voi sitä suurta kaupunkia, joka oli puettu pellavaan ja purppuraan ja helakanpunaan ja koristettu kullalla ja jalokivillä ja helmillä, kun semmoinen rikkaus yhdessä hetkessä tuhoutui!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 17, 'Ja kaikki laivurit ja kaikki rannikkopurjehtijat ja merimiehet ja kaikki merenkulkijat seisoivat loitolla');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 18, 'ja huusivat nähdessään hänen palonsa savun ja sanoivat: \"Mikä on tämän suuren kaupungin vertainen?\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 19, 'Ja he heittivät tomua päänsä päälle ja huusivat itkien ja surren ja sanoivat: \"Voi, voi sitä suurta kaupunkia, jonka kalleuksista rikastuivat kaikki, joilla oli laivoja merellä, kun se yhdessä hetkessä tuhoutui!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 20, 'Riemuitse hänestä, taivas, ja te pyhät ja apostolit ja profeetat; sillä Jumala on hänet tuominnut ja kostanut hänelle teidän tuomionne.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 21, 'Ja väkevä enkeli otti kiven, niinkuin suuren myllynkiven, ja heitti sen mereen sanoen: \"Näin heitetään kiivaasti pois Babylon, se suuri kaupunki, eikä sitä enää löydetä\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 22, 'Ei kuulla sinussa enää kanteleensoittajain ja laulajain, huilun-ja torvensoittajain ääntä; ei löydetä sinusta enää minkään ammatin taituria; ei kuulla sinussa enää myllyn jyrinää;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 23, 'ei loista sinussa enää lampun valo; ei kuulla sinussa enää huutoa yljälle eikä huutoa morsiamelle; sillä sinun kauppiaasi olivat maan mahtavia, ja sinun velhoutesi villitsi kaikki kansat;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 18, 24, 'ja hänestä on löydetty profeettain ja pyhien veri ja kaikkien veri, jotka maan päällä ovat tapetut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 1, 'Sen jälkeen minä kuulin ikäänkuin kansan paljouden suuren äänen taivaassa sanovan: \"Halleluja! Pelastus ja kunnia ja voima on Jumalan, meidän Jumalamme.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 2, 'Sillä totiset ja vanhurskaat ovat hänen tuomionsa; sillä hän on tuominnut sen suuren porton, joka turmeli maan haureudellaan, ja on kostanut ja on vaatinut hänen kädestänsä palvelijainsa veren.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 3, 'Ja he sanoivat toistamiseen: \"Halleluja!\" Ja hänen savunsa nousee aina ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 4, 'Ja ne kaksikymmentä neljä vanhinta ja neljä olentoa lankesivat maahan ja kumartaen rukoilivat Jumalaa, joka valtaistuimella istuu, ja sanoivat: \"Amen, halleluja!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 5, 'Ja valtaistuimelta lähti ääni, joka sanoi: \"Ylistäkää meidän Jumalaamme, kaikki hänen palvelijansa, te, jotka häntä pelkäätte, sekä pienet että suuret\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 6, 'Ja minä kuulin ikäänkuin kansan paljouden äänen ja ikäänkuin paljojen vetten pauhinan ja ikäänkuin suuren ukkosenjylinän sanovan: \"Halleluja! Sillä Herra, meidän Jumalamme, Kaikkivaltias, on ottanut hallituksen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 7, 'Iloitkaamme ja riemuitkaamme ja antakaamme kunnia hänelle, sillä Karitsan häät ovat tulleet, ja hänen vaimonsa on itsensä valmistanut.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 8, 'Ja hänen annettiin pukeutua liinavaatteeseen, hohtavaan ja puhtaaseen: se liina on pyhien vanhurskautus.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 9, 'Ja hän sanoi minulle: \"Kirjoita: Autuaat ne, jotka ovat kutsutut Karitsan hääaterialle!\" Vielä hän sanoi minulle: \"Nämä sanat ovat totiset Jumalan sanat\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 10, 'Ja minä lankesin hänen jalkojensa juureen, kumartaen rukoillakseni häntä. Mutta hän sanoi minulle: \"Varo, ettet sitä tee; minä olen sinun ja sinun veljiesi kanssapalvelija, niiden, joilla on Jeesuksen todistus; kumarra ja rukoile Jumalaa. Sillä Jeesuksen todistus on profetian henki.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 11, 'Ja minä näin taivaan auenneena. Ja katso: valkoinen hevonen, ja sen selässä istuvan nimi on Uskollinen ja Totinen, ja hän tuomitsee ja sotii vanhurskaudessa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 12, 'Ja hänen silmänsä olivat niinkuin tulen liekit, ja hänen päässään oli monta kruunua, ja hänellä oli kirjoitettuna nimi, jota ei tiedä kukaan muu kuin hän itse,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 13, 'ja hänellä oli yllään vereen kastettu vaippa, ja nimi, jolla häntä kutsutaan, on Jumalan Sana.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 14, 'Ja häntä seurasivat ratsastaen valkoisilla hevosilla taivaan sotajoukot, puettuina valkeaan ja puhtaaseen pellavavaatteeseen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 15, 'Ja hänen suustaan lähtee terävä miekka, että hän sillä löisi kansoja. Ja hän on kaitseva heitä rautaisella valtikalla, ja hän polkee kaikkivaltiaan Jumalan vihan kiivauden viinikuurnan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 16, 'Ja hänellä on vaipassa kupeellaan kirjoitettuna nimi: \"Kuningasten Kuningas ja herrain Herra\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 17, 'Ja minä näin enkelin seisovan auringossa, ja hän huusi suurella äänellä sanoen kaikille keskitaivaalla lentäville linnuille: \"Tulkaa, kokoontukaa Jumalan suurelle aterialle');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 18, 'syömään kuningasten lihaa ja sotapäällikköjen lihaa ja väkevien lihaa ja hevosten sekä niiden selässä istuvien lihaa ja kaikkien vapaitten ja orjien lihaa, sekä pienten että suurten\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 19, 'Ja minä näin pedon ja maan kuninkaat ja heidän sotajoukkonsa kokoontuneina sotiaksensa hevosen selässä istuvaa vastaan ja hänen sotajoukkoansa vastaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 20, 'Ja peto otettiin kiinni, ja sen kanssa väärä profeetta, joka sen nähden oli tehnyt ihmetekonsa, joilla hän oli eksyttänyt ne, jotka olivat ottaneet pedon merkin, ja ne, jotka olivat sen kuvaa kumartaneet; ne molemmat heitettiin elävältä tuliseen järveen, joka tulikiveä palaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 19, 21, 'Ja ne muut saivat surmansa hevosen selässä istuvan miekasta, joka lähti hänen suustaan; ja kaikki linnut tulivat ravituiksi heidän lihastansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 1, 'Ja minä näin tulevan taivaasta alas enkelin, jolla oli syvyyden avain ja suuret kahleet kädessään.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 2, 'Ja hän otti kiinni lohikäärmeen, sen vanhan käärmeen, joka on perkele ja saatana, ja sitoi hänet tuhanneksi vuodeksi');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 3, 'ja heitti hänet syvyyteen ja sulki ja lukitsi sen sinetillä hänen jälkeensä, ettei hän enää kansoja villitsisi, siihen asti kuin ne tuhat vuotta ovat loppuun kuluneet; sen jälkeen hänet pitää päästettämän irti vähäksi aikaa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 4, 'Ja minä näin valtaistuimia, ja he istuivat niille, ja heille annettiin tuomiovalta; ja minä näin niiden sielut, jotka olivat teloitetut Jeesuksen todistuksen ja Jumalan sanan tähden, ja niiden, jotka eivät olleet kumartaneet petoa eikä sen kuvaa eivätkä ottaneet sen merkkiä otsaansa eikä käteensä; ja he virkosivat eloon ja hallitsivat Kristuksen kanssa tuhannen vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 5, 'Muut kuolleet eivät vironneet eloon, ennenkuin ne tuhat vuotta olivat loppuun kuluneet. Tämä on ensimmäinen ylösnousemus.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 6, 'Autuas ja pyhä on se, jolla on osa ensimmäisessä ylösnousemuksessa; heihin ei toisella kuolemalla ole valtaa, vaan he tulevat olemaan Jumalan ja Kristuksen pappeja ja hallitsevat hänen kanssaan ne tuhannen vuotta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 7, 'Ja kun ne tuhat vuotta ovat loppuun kuluneet, päästetään saatana vankeudestaan,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 8, 'ja hän lähtee villitsemään maan neljällä kulmalla olevia kansoja, Googia ja Maagogia, kootakseen heidät sotaan, ja niiden luku on kuin meren hiekka.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 9, 'Ja he nousevat yli maan avaruuden ja piirittävät pyhien leirin ja sen rakastetun kaupungin. Mutta tuli lankeaa taivaasta ja kuluttaa heidät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 10, 'Ja perkele, heidän villitsijänsä, heitetään tuli-ja tulikivijärveen, jossa myös peto ja väärä profeetta ovat, ja heitä vaivataan yöt päivät, aina ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 11, 'Ja minä näin suuren, valkean valtaistuimen ja sillä istuvaisen, jonka kasvoja maa ja taivas pakenivat, eikä niille sijaa löytynyt.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 12, 'Ja minä näin kuolleet, suuret ja pienet, seisomassa valtaistuimen edessä, ja kirjat avattiin; ja avattiin toinen kirja, joka on elämän kirja; ja kuolleet tuomittiin sen perusteella, mitä kirjoihin oli kirjoitettu, tekojensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 13, 'Ja meri antoi ne kuolleet, jotka siinä olivat, ja Kuolema ja Tuonela antoivat ne kuolleet, jotka niissä olivat, ja heidät tuomittiin, kukin tekojensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 14, 'Ja Kuolema ja Tuonela heitettiin tuliseen järveen. Tämä on toinen kuolema, tulinen järvi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 20, 15, 'Ja joka ei ollut elämän kirjaan kirjoitettu, se heitettiin tuliseen järveen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 1, 'Ja minä näin uuden taivaan ja uuden maan; sillä ensimmäinen taivas ja ensimmäinen maa ovat kadonneet, eikä merta enää ole.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 2, 'Ja pyhän kaupungin, uuden Jerusalemin, minä näin laskeutuvan alas taivaasta Jumalan tyköä, valmistettuna niinkuin morsian, miehellensä kaunistettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 3, 'Ja minä kuulin suuren äänen valtaistuimelta sanovan: \"Katso, Jumalan maja ihmisten keskellä! Ja hän on asuva heidän keskellänsä, ja he ovat hänen kansansa, ja Jumala itse on oleva heidän kanssaan, heidän Jumalansa;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 4, 'ja hän on pyyhkivä pois kaikki kyyneleet heidän silmistänsä, eikä kuolemaa ole enää oleva, eikä murhetta eikä parkua eikä kipua ole enää oleva, sillä kaikki entinen on mennyt.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 5, 'Ja valtaistuimella istuva sanoi: \"Katso, uudeksi minä teen kaikki\". Ja hän sanoi: \"Kirjoita, sillä nämä sanat ovat vakaat ja todet\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 6, 'Ja hän sanoi minulle: \"Se on tapahtunut. Minä olen A ja O, alku ja loppu. Minä annan janoavalle elämän veden lähteestä lahjaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 7, 'Joka voittaa, on tämän perivä, ja minä olen oleva hänen Jumalansa, ja hän on oleva minun poikani.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 8, 'Mutta pelkurien ja epäuskoisten ja saastaisten ja murhaajien ja huorintekijäin ja velhojen ja epäjumalanpalvelijain ja kaikkien valhettelijain osa on oleva siinä järvessä, joka tulta ja tulikiveä palaa; tämä on toinen kuolema.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 9, 'Ja tuli yksi niistä seitsemästä enkelistä, joilla oli ne seitsemän maljaa täynnä seitsemää viimeistä vitsausta, ja puhui minun kanssani sanoen: \"Tule tänne, minä näytän sinulle morsiamen, Karitsan vaimon\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 10, 'Ja hän vei minut hengessä suurelle ja korkealle vuorelle ja näytti minulle pyhän kaupungin, Jerusalemin, joka laskeutui alas taivaasta Jumalan tyköä,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 11, 'ja siinä oli Jumalan kirkkaus; sen hohto oli kaikkein kalleimman kiven kaltainen, niinkuin kristallinkirkas jaspis-kivi;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 12, 'siinä oli suuri ja korkea muuri, jossa oli kaksitoista porttia ja porteilla kaksitoista enkeliä, ja niihin oli kirjoitettu nimiä, ja ne ovat Israelin lasten kahdentoista sukukunnan nimet;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 13, 'idässä kolme porttia ja pohjoisessa kolme porttia ja etelässä kolme porttia ja lännessä kolme porttia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 14, 'Ja kaupungin muurilla oli kaksitoista perustusta, ja niissä Karitsan kahdentoista apostolin kaksitoista nimeä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 15, 'Ja sillä, joka minulle puhui, oli mittasauvana kultainen ruoko, mitatakseen kaupungin ja sen portit ja sen muurin.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 16, 'Ja kaupunki oli neliskulmainen, ja sen pituus oli yhtä suuri kuin sen leveys. Ja hän mittasi sillä ruovolla kaupungin: se oli kaksitoista tuhatta vakomittaa. Sen pituus ja leveys ja korkeus olivat yhtä suuret.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 17, 'Ja hän mittasi sen muurin: se oli sata neljäkymmentä neljä kyynärää, ihmismitan mukaan, joka on enkelin mitta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 18, 'Ja sen muuri oli rakennettu jaspiksesta, ja kaupunki oli puhdasta kultaa, puhtaan lasin kaltaista.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 19, 'Ja kaupungin muurin perustukset olivat kaunistetut kaikkinaisilla kalleilla kivillä; ensimmäinen perustus oli jaspis, toinen safiiri, kolmas kalkedon, neljäs smaragdi,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 20, 'viides sardonyks, kuudes sardion, seitsemäs krysoliitti, kahdeksas berylli, yhdeksäs topaasi, kymmenes krysoprasi, yhdestoista hyasintti, kahdestoista ametisti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 21, 'Ja ne kaksitoista porttia olivat kaksitoista helmeä; kukin portti oli yhdestä helmestä; ja kaupungin katu oli puhdasta kultaa, ikäänkuin läpikuultavaa lasia.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 22, 'Mutta temppeliä minä en siinä nähnyt; sillä Herra Jumala, Kaikkivaltias, on sen temppeli, ja Karitsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 23, 'Eikä kaupunki tarvitse valoksensa aurinkoa eikä kuuta; sillä Jumalan kirkkaus valaisee sen, ja sen lamppu on Karitsa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 24, 'Ja kansat tulevat vaeltamaan sen valkeudessa, ja maan kuninkaat vievät sinne kunniansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 25, 'Eikä sen portteja suljeta päivällä, ja yötä ei siellä ole,');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 26, 'ja sinne viedään kansojen kunnia ja kalleudet.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 21, 27, 'Eikä sinne ole pääsevä mitään epäpyhää eikä ketään kauhistusten tekijää eikä valhettelijaa, vaan ainoastaan ne, jotka ovat kirjoitetut Karitsan elämänkirjaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 1, 'Ja hän näytti minulle elämän veden virran, joka kirkkaana kuin kristalli juoksi Jumalan ja Karitsan valtaistuimesta.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 2, 'Keskellä sen katua ja virran molemmilla puolilla oli elämän puu, joka kantoi kahdettoista hedelmät, antaen joka kuukausi hedelmänsä, ja puun lehdet ovat kansojen tervehtymiseksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 3, 'Eikä mitään kirousta ole enää oleva. Ja Jumalan ja Karitsan valtaistuin on siellä oleva, ja hänen palvelijansa palvelevat häntä');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 4, 'ja näkevät hänen kasvonsa, ja hänen nimensä on heidän otsissansa.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 5, 'Eikä yötä ole enää oleva, eivätkä he tarvitse lampun valoa eikä auringon valoa, sillä Herra Jumala on valaiseva heitä, ja he hallitsevat aina ja iankaikkisesti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 6, 'Ja hän sanoi minulle: \"Nämä sanat ovat vakaat ja todet, ja Herra, profeettain henkien Jumala, on lähettänyt enkelinsä näyttämään palvelijoilleen, mitä pian tapahtuman pitää.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 7, 'Ja katso, minä tulen pian. Autuas se, joka ottaa tämän kirjan ennustuksen sanoista vaarin!\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 8, 'Ja minä, Johannes, olen se, joka tämän kuulin ja näin. Ja kun olin sen kuullut ja nähnyt, minä lankesin maahan kumartuakseni sen enkelin jalkojen eteen, joka tämän minulle näytti.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 9, 'Ja hän sanoi minulle: \"Varo, ettet sitä tee; minä olen sinun ja sinun veljiesi, profeettain, kanssapalvelija, ja niiden, jotka ottavat tämän kirjan sanoista vaarin; kumartaen rukoile Jumalaa\".');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 10, 'Ja hän sanoi minulle: \"Älä lukitse tämän kirjan profetian sanoja; sillä aika on lähellä.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 11, 'Vääryyden tekijä tehköön edelleen vääryyttä, ja joka on saastainen, saastukoon edelleen, ja joka on vanhurskas, tehköön edelleen vanhurskautta, ja joka on pyhä, pyhittyköön edelleen.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 12, 'Katso, minä tulen pian, ja minun palkkani on minun kanssani, antaakseni kullekin hänen tekojensa mukaan.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 13, 'Minä olen A ja O, ensimmäinen ja viimeinen, alku ja loppu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 14, 'Autuaat ne, jotka pesevät vaatteensa, että heillä olisi valta syödä elämän puusta ja he pääsisivät porteista sisälle kaupunkiin!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 15, 'Ulkopuolella ovat koirat ja velhot ja huorintekijät ja murhaajat ja epäjumalanpalvelijat ja kaikki, jotka valhetta rakastavat ja tekevät.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 16, 'Minä, Jeesus, lähetin enkelini todistamaan näitä teille seurakunnissa. Minä olen Daavidin juurivesa ja hänen suvustansa, se kirkas kointähti.\"');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 17, 'Ja Henki ja morsian sanovat: \"Tule!\" Ja joka kuulee, sanokoon: \"Tule!\" Ja joka janoaa, tulkoon, ja joka tahtoo, ottakoon elämän vettä lahjaksi.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 18, 'Minä todistan jokaiselle, joka tämän kirjan profetian sanat kuulee: Jos joku panee niihin jotakin lisää, niin Jumala on paneva hänen päällensä ne vitsaukset, jotka ovat kirjoitetut tähän kirjaan;');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 19, 'ja jos joku ottaa pois jotakin tämän profetian kirjan sanoista, niin Jumala on ottava pois sen osan, mikä hänellä on elämän puuhun ja pyhään kaupunkiin, joista tässä kirjassa on kirjoitettu.');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 20, 'Hän, joka näitä todistaa, sanoo: \"Totisesti, minä tulen pian\". Amen, tule, Herra Jeesus!');
INSERT INTO `FinPR_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (83, 22, 21, 'Herran Jeesuksen armo olkoon kaikkien kanssa. Amen.');
